/****** Object:  UserDefinedFunction [dbo].[Assy_FN_Get_BarcodeParts_From_Barcode]    Script Date: 30-09-2026 14:44:31 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
CREATE function [dbo].[Assy_FN_Get_BarcodeParts_From_Barcode]
(
@ProfitCenterCode varchar(20),
@LineCode varchar(30),
@Barcode varchar(60)
)
returns @TmpBarcodeParts  table
(
PartNo varchar(30),
Datecode char(4),
SerialNo  varchar(15),
LineCode varchar(10)
)
as
begin
--Author:<Ravishankar Mishra>
--Created date:<16/09/2015>
--select * from Assy_FN_Get_BarcodeParts_From_Barcode('0021','M07','2906683537Qb00000001M07')
		insert into @TmpBarcodeParts(PartNo,Datecode,SerialNo,LineCode)
		 select PartNo,DateCode,SerialNo,LineCode from ASSY_Vision_System with (nolock) where ProfitCenterCode=@ProfitCenterCode 
		 and LineCode=@LineCode and Barcode=@Barcode

		 IF NOT EXISTS (SELECT 1 FROM @TmpBarcodeParts)
		 BEGIN
			insert into @TmpBarcodeParts(PartNo,Datecode,SerialNo,LineCode)
			select PartNo,DateCode,SerialNo,LineCode from ASSY_Vision_System_History with (nolock) where ProfitCenterCode=@ProfitCenterCode 
			and LineCode=@LineCode and Barcode=@Barcode
		 END
		 IF NOT EXISTS (SELECT 1 FROM @TmpBarcodeParts)
		 BEGIN
			insert into @TmpBarcodeParts(PartNo,Datecode,LineCode)
			select PartNo,DateCode,LineCode from Assy_LineAssyStatus_Running with (nolock) 
			where ProfitCenterCode=@ProfitCenterCode 
			and LineCode=@LineCode and Barcode=@Barcode and MachineCode='MCIG'
			and OperationCode='OCIG'
		 END
		 return
end


GO
/****** Object:  UserDefinedFunction [dbo].[ASSY_FN_GET_BoostRatio]    Script Date: 30-09-2026 14:44:31 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE function [dbo].[ASSY_FN_GET_BoostRatio]
(
@profitCenterCode varchar(20),
@PartNo varchar(20)

)
--Author:<Ravishankar Mishra>
--Created date:<22/07/2015>
--select * from Assy_Coupling_LabelInfo_Mst
--select dbo.ASSY_FN_GET_BoostRatio('0021','32067870')
returns varchar(20)
as
begin
		declare @BoostRatio varchar(20)
		select distinct @BoostRatio=isnull(LabelDataValue,'') from Assy_Coupling_LabelInfo_Mst(nolock) where ProfitCenterCode=@profitCenterCode and PartNo=@PartNo
		and labeldataname='Boost_Ratio'		
		return 	isnull(@BoostRatio,'')		

end


GO
/****** Object:  UserDefinedFunction [dbo].[Assy_FN_GET_CHANGEOVER_COUNT]    Script Date: 30-09-2026 14:44:31 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

--select dbo.Assy_FN_GET_CHANGEOVER_COUNT ('0021','M07','13GB')
CREATE function [dbo].[Assy_FN_GET_CHANGEOVER_COUNT](
@P_WH_CD    nvarchar(4)=''  ,
@P_LINECODE VARCHAR(10)='',
@P_DATECODE VARCHAR(4)=''
) returns INT
as
BEGIN

       declare @P_CHANGEOVER_COUNT INT

       select @P_CHANGEOVER_COUNT=count(a1.R_NUM) 
    from (select row_number () over (order by TIMESTAMP) as R_NUM,  PartNumber  from Assy_VIEW_Get_All_Assy_RunningPart_Data(nolock) where datecode=@P_DATECODE and LineCode =@P_LINECODE and ProfitCenterCode =@P_WH_CD) a1 
    join (select row_number () over (order by TIMESTAMP) as R_NUM,  PartNumber from Assy_VIEW_Get_All_Assy_RunningPart_Data(nolock) where datecode=@P_DATECODE and LineCode =@P_LINECODE and ProfitCenterCode =@P_WH_CD) a2 
    on a1.R_NUM = a2.R_NUM+1 
    where  a1.PartNumber != a2.PartNumber

       return @P_CHANGEOVER_COUNT

END



GO
/****** Object:  UserDefinedFunction [dbo].[Assy_FN_Get_COMPORT_NAME]    Script Date: 30-09-2026 14:44:31 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
