CREATE FUNCTION [dbo].[Assy_FN_Get_COMPORT_NAME]
(
@PROFITCENTERCODE VARCHAR(50)='0021',
@LINECODE VARCHAR(10)=NULL,
@OPERATIONCODE VARCHAR(50)=NULL,
@HARDWARENAME VARCHAR(50)=NULL,
@PORTTYPE  VARCHAR(50)=NULL
)
RETURNS VARCHAR(50)
AS

	--CREATED BY	:RAVISHANKAR MISHRA
	--DATE		:	17-10-2014

	--MODIFIED BY	:RAVISHANKAR MISHRA
	--MODIFIED DATE	:18-05-2016
	--REMARKS:ADDED LOGIC FOR CHECKING WHETHER PARTICULAR STATION RECORDS HAVE BEEN DEFINED IN HARDWARE TABLE OR NOT.

	--SELECT DBO.ASSY_FN_GET_COMPORT_NAME('0088','J04','OCFV','RFIDREADER','SERIALPORT')

BEGIN
		DECLARE @PORTNAME VARCHAR(30)
		IF EXISTS
		(
			SELECT 1 FROM ASSY_LINEHARDWAREDTL(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND OPERATIONCODE=@OPERATIONCODE  
		    AND HARDWARENAME =@HARDWARENAME  AND ISNULL(ISACTIVE,0)=1 
		)
		BEGIN
				SELECT @PORTNAME =PORTNO FROM ASSY_LINEWISEDEVICECONFIG(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND OPERATIONCODE=@OPERATIONCODE  
				AND HARDWARENAME =@HARDWARENAME
		END
		ELSE
			BEGIN
					SET @PORTNAME='N/A'
			END
		RETURN @PORTNAME

END

