		--select dbo.Assy_FN_Get_FinalViewing_MachineCode_From_LineCode('0021','p2')
		declare @FVMC as varchar(30)
		declare @LineTypeName as varchar(30) 
		SELECT @LineTypeName=ltm.linetypename FROM LINEMST LM WIth (nolock) join LineTypeMst LTM  with (nolock) 
