/****** Object:  UserDefinedFunction [dbo].[Assy_FN_Get_FirstStation_ProducePart]    Script Date: 30-09-2026 14:44:31 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[Assy_FN_Get_FirstStation_ProducePart]
(
@LineCode varchar(20)=Null
,@ProfitCenterCode varchar(20)=null
)
RETURNS varchar(20)
AS
BEGIN
----select dbo.Assy_FN_Get_FirstStation_ProducePart('j04','0088')

--Author:<Ravishankar Mishra>          
--Created Date:<12-10-14>

--Modified By:<Ravishankar Mishra>          
--Modified Date:<12-11-16>
--Remarks:-Read no. of printed barcode from table- Assy_Barcode_Printed_Counter insead from Assy_LineAssyStatus tables

						declare @Result varchar(13)
						declare @Datecode char(4)
						declare @PartNo varchar(30)
						select top 1 @Datecode=datecode,@PartNo=Assy_PartNo  from dbo.Assy_RunningPart(nolock) where ProfitCenterCode =@ProfitCenterCode 
						and LineCode=@linecode order by CreatedDate desc
   
							select  top 1 @Result=datecode+'|' +Assy_PartNo from dbo.Assy_RunningPart(nolock)
							where isauthorized=0 and ProfitCenterCode =@ProfitCenterCode and  LineCode=@linecode  
							and substring(datecode,3,1) in
								(
								SELECT code
									FROM   
									(  
										SELECT ShiftCode  
										 ,[Monday]  
										 ,[Tuesday]  
										 ,[Wednesday]  
										 ,[Thursday]  
										 ,[Friday]  
										 ,[Saturday]  
										 ,[Sunday]  
				  
										FROM dbo.DateCodeMst(nolock) where monday=substring(@datecode,3,1) or 
										tuesday=substring(@datecode,3,1) or 
										wednesday=substring(@datecode,3,1) or 
										thursday=substring(@datecode,3,1) or 
										friday=substring(@datecode,3,1) or 
										saturday=substring(@datecode,3,1) or 
										sunday=substring(@datecode,3,1)  
										and ProfitCenterCode=@ProfitCenterCode
								   ) p  
								UNPIVOT  
								(code FOR day1 IN   
									 (Monday  
									 ,[Tuesday]  
									 ,[Wednesday]  
									 ,[Thursday]  
									 ,[Friday]  
									 ,[Saturday]  
									 ,[Sunday]  
									 )        
								)AS unpvt  
							   ) 
							--) 

						if @Result<>''
						begin

								 declare @MachineCode varchar(20)
								 declare @VSPrintedBarcode as int
								select @MachineCode= MachineCode  from RoutingConfigLineWise(nolock) where Traceability=1 and OperationSeqNo=1 and LineCode =@LineCode
								and  ProfitCenterCode =@ProfitCenterCode 
							-- select @VSPrintedBarcode=count(barcode) from 
							-- (
							--		 select datecode,PartNo,barcode,MachineCode,LineCode,ProfitCenterCode,isnull(IsTallyChartApproved,0)IsTallyChartApproved from Assy_LineAssyStatus(nolock)
							--		 union
							--		 select datecode,PartNo,barcode,MachineCode,LineCode,ProfitCenterCode,isnull(IsTallyChartApproved,0)IsTallyChartApproved from Assy_LineAssyStatus_Running(nolock)

							-- )A 
							--where A.MachineCode =@MachineCode 
							--and LineCode= @LineCode 
							--and ProfitCenterCode=@ProfitCenterCode 
							--and isnull(A.IsTallyChartApproved,0)=0
							--and Datecode=@Datecode
							--and PartNo=@PartNo
								if exists
								(
										select top 1 1 from dbo.linemst with(nolock) where ProfitCenterCode =@ProfitCenterCode  and LineCode =@LineCode 
										and isnull(Allow2Parts,0)=0
								)	
								begin
										select top 1 @VSPrintedBarcode=isnull(PrintedQty,0) from Assy_Barcode_Printed_Counter with(nolock)
										where ProfitCenterCode=@ProfitCenterCode  and LineCode= @LineCode 	
								end
								else
									begin
											select @VSPrintedBarcode=count(1) from dbo.assy_lineassystatus_running with(nolock) where ProfitCenterCode=@ProfitCenterCode  
											and LineCode= @LineCode and isnull(IsPendingPart,0)=0 and isnull(status,'')=''
									end
									if  isnull(@VSPrintedBarcode,0)=0
										set @Result=''		
					end
							 
                     RETURN isnull(@Result,'')
END

GO
