CREATE FUNCTION [dbo].[Assy_FN_Get_LineTypeName_From_LineCode]
(
	@ProfitCenterCode VARCHAR(20),
	@LineCode VARCHAR(20)
)
RETURNS VARCHAR(50)
AS
BEGIN
		-- Author:<Rashid Siddiqui>
		-- Created on:<03rd Feb 2016>
		-- SELECT dbo.Assy_FN_Get_LineTypeName_From_LineCode('0021','P2')
		
		DECLARE @LineTypeName AS VARCHAR(50) 
		
		SELECT @LineTypeName = LTRIM(RTRIM(LT.LineTypeName))
			FROM LineTypeMst LT (NOLOCK)
				INNER JOIN LineMst LM (NOLOCK)
					ON LT.LineTypeCode = LM.LineTypeCode
						WHERE LM.LineCode = @LineCode AND LM.ProfitCenterCode = @ProfitCenterCode
		RETURN @LineTypeName
END
