CREATE function [dbo].[ASSY_FN_GET_PARAMETER_VALUE]
(    
 @p_parameter_c nvarchar(50),     
 @p_parameter_c1 nvarchar(50) =null,     
 @p_parameter_c2 nvarchar(50) = null,
 @ProfitCenterCode nvarchar(50) = null    
)    
returns nvarchar(200)    
as        
begin    
		 declare @val nvarchar(1000) 
		if(@p_parameter_c='DEFAULT WAREHOUSE')
		begin
				select top 1 @val=WAREHOUSE_CD from WAREHOUSE_MASTER nolock where DEFAULT_WH_CD=1
				return ISNULL(@val,'') 
		end
    
		 select @val=Rtrim(ltrim(parameter_value))    
		 from parameter_mst(nolock)  where parameter_c=@p_parameter_c and parameter_c1=isnull(@p_parameter_c1, '') and parameter_c2=isnull(@p_parameter_c2, '')  
		 and wh_code = @ProfitCenterCode     
		 return @val    
end



