create function  [dbo].[Assy_FN_Get_Runningpart_Group_Parts]
(
@PROFITCENTERCODE VARCHAR(20),
@LINECODE VARCHAR(20)
)
RETURNS @ALLPARTS TABLE
(
 PARTNO VARCHAR(20)  PRIMARY KEY
)
AS
BEGIN
--CREATED BY :<RAVISHANKAR MISHRA>
--CREATED ON :<24/12/2015>
--SELECT * FROM  ASSY_FN_GET_RUNNINGPART_GROUP_PARTS('0021','M08')
						
		INSERT INTO @ALLPARTS(PARTNO)
		SELECT DISTINCT PARTNO FROM ROUTINGCONFIGPARTWISE WITH(NOLOCK) WHERE PROFITCENTERCODE =@PROFITCENTERCODE 
