/****** Object:  UserDefinedFunction [dbo].[Assy_FN_Get_ServoTMCParts_From_STMCPart]    Script Date: 30-09-2026 14:44:31 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE  function [dbo].[Assy_FN_Get_ServoTMCParts_From_STMCPart]
(
@ProfitCenterCode varchar(20),
@STMCPartNo varchar(30),
@BOMVersion int
)
returns @Table table
(
 ServoPartNo varchar(30),
 TMCPartNo varchar(30)
)
as
begin
--Author:<Ravishankar Mishra>
--Created date:<16/09/2015>
--select * from Assy_FN_Get_ServoTMCParts_From_STMCPart('0021','32067870',1)


			select @BOMVersion=isnull(po.ver,1) from assy_runningpart(nolock) RP inner join Assy_ProductionOrderMst(nolock) PO on rp.ProfitCenterCode=PO.ProfitCenterCode
			and RP.ProductionOrderNo=PO.OrderNo and rp.Assy_PartNo=po.partno

			declare @ServoPartNo varchar(20),@TMCPartNo varchar(20)		
			select top 1 @ServoPartNo=RM_PART_NO  from BOM_MASTER BM with (nolock) inner join PRODUCT_MASTER PM with(nolock) 
			on BM.WH_CODE =pm.warehouse_cd and bm.RM_PART_NO =pm.SEWS_PART_NO 
			where pm.warehouse_cd =@ProfitCenterCode and BM.VER =@BOMVersion and BM.STS_CD=0 and pm.STS_CD=0 
			and BM.FG_PART_NO =@STMCPartNo and pm.MATERIAL_TP ='servo'

			select top 1 @TMCPartNo=RM_PART_NO  from BOM_MASTER BM with (nolock) inner join PRODUCT_MASTER PM with(nolock) 
			on BM.WH_CODE =pm.warehouse_cd and bm.RM_PART_NO =pm.SEWS_PART_NO 
			where pm.warehouse_cd =@ProfitCenterCode and BM.VER =@BOMVersion and BM.STS_CD=0 and pm.STS_CD=0 
			and BM.FG_PART_NO =@STMCPartNo and pm.MATERIAL_TP ='TMC'

			insert into @Table(ServoPartNo,TMCPartNo)
			select @ServoPartNo,@TMCPartNo
			return
end


GO
/****** Object:  UserDefinedFunction [dbo].[Assy_FN_Get_ServoTMCParts_From_STMCPart_Add_Part_Master]    Script Date: 30-09-2026 14:44:31 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

Create FUNCTION [dbo].[Assy_FN_Get_ServoTMCParts_From_STMCPart_Add_Part_Master]
(
	@ProfitCenterCode VARCHAR(20),
	@STMCPartNo VARCHAR(30),
	@BOMVersion INT
)
RETURNS @ReturnTable Table
(
	ServoPartNo VARCHAR(30),
	TMCPartNo VARCHAR(30)
)
AS
BEGIN
	-- Author		:	<Rashid Siddiqui>
	-- Created date	:	<02-April-2016>
	-- SELECT * FROM Assy_FN_Get_ServoTMCParts_From_STMCPart_Add_Part_Master('0021','14234601',1)

	DECLARE @ServoPartNo VARCHAR(20), @TMCPartNo VARCHAR(20)

	SELECT Top 1 @ServoPartNo = ISNULL(RM_PART_NO,'')
		FROM BOM_MASTER BM WITH (NOLOCK)
			INNER JOIN PRODUCT_MASTER PM WITH (NOLOCK)
				ON BM.WH_CODE = PM.warehouse_cd AND BM.RM_PART_NO = PM.SEWS_PART_NO 
					WHERE PM.warehouse_cd = @ProfitCenterCode AND BM.VER = @BOMVersion AND BM.STS_CD = 0 AND PM.STS_CD = 0 
							AND BM.FG_PART_NO = @STMCPartNo AND UPPER(ISNULL(PM.MATERIAL_TP,'')) = 'SERVO'

	SELECT Top 1 @TMCPartNo = ISNULL(RM_PART_NO,'')
		FROM BOM_MASTER BM WITH (NOLOCK)
			INNER JOIN PRODUCT_MASTER PM WITH (NOLOCK)
				ON BM.WH_CODE = PM.warehouse_cd AND BM.RM_PART_NO = PM.SEWS_PART_NO 
					WHERE PM.warehouse_cd = @ProfitCenterCode AND BM.VER = @BOMVersion AND BM.STS_CD = 0 AND PM.STS_CD = 0 
							AND BM.FG_PART_NO = @STMCPartNo AND UPPER(ISNULL(PM.MATERIAL_TP,'')) = 'TMC'

	INSERT INTO @ReturnTable (ServoPartNo, TMCPartNo)
	SELECT ISNULL(@ServoPartNo,''), ISNULL(@TMCPartNo,'')
	
	RETURN
END
GO
/****** Object:  UserDefinedFunction [dbo].[Assy_FN_Get_ShiftWise_Date]    Script Date: 30-09-2026 14:44:31 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE function [dbo].[Assy_FN_Get_ShiftWise_Date]
(
@ProfitCenterCode varchar(30)
)
returns date
--Author:<Ravishankar Mishra>
--Created date:<11-05-2015>
--select dbo.Assy_FN_Get_ShiftWise_Date('0021')

as
begin
			declare @CurrentDate date=getdate()
			declare @CurrentTimeInSeconds int,@DayShiftStartTimeInSeconds as int
			set @CurrentTimeInSeconds=DATEDIFF (SECOND,0,CONVERT(DATETIME, LEFT(CONVERT(VARCHAR(20),CONVERT(TIME,getdate())),8))) 
			SELECT @DayShiftStartTimeInSeconds=DATEDIFF (SECOND,0,CONVERT(DATETIME, FromTime))  FROM SHIFTMST(NOLOCK) 
			WHERE PROFITCENTERCODE=@ProfitCenterCode AND SHIFTNAME ='DAY' 
			--SELECT @CurrentTimeInSeconds
			--SELECT @OTShiftEndTimeInSeconds
			if(@CurrentTimeInSeconds>=0 and @CurrentTimeInSeconds< @DayShiftStartTimeInSeconds)
			begin
					 set @CurrentDate=convert(date,getdate()-1) 
			end
			return @CurrentDate

end


