CREATE FUNCTION [dbo].[Assy_FN_Get_User_Right]
(
@UserName varchar(50)=null,
@UserControlName varchar(100)=null,
@AppId int=3
)
returns char(1)
as
--created By : <Ravishankar Mishtra>
--Created Date: 29-04-15

--select dbo.Assy_FN_Get_User_Right ('user','UcTallyChart',3)
--select * from TL_MF_SEC_USER_MENU_SETUP_MST  where USER_GROUP_ID=5645

begin
		declare @RetVal char(1)
		if exists
		(
				select 1  from TL_MF_SEC_USER_MENU_SETUP_MST(nolock) where USER_GROUP_ID=(select top 1 user_id from TL_MF_SEC_USER_MST(nolock) where USER_CODE=@UserName) 
				and APP_ID =@AppId 
				and PARENT_ID=(select top 1 MENUID from ASSEMBLY_MENU(nolock) where MENUNAME='Assembly')
				and program_id=@UserControlName
				and(upper(ADD_ALLOW) ='Y' and upper(DELETE_ALLOW) ='Y' and upper(MODIFY_ALLOW) ='Y')
		)		
		begin
		     set @RetVal='Y'
		end
		else
		   set @RetVal='N'
		   return @RetVal
end


