/****** Object:  UserDefinedFunction [dbo].[ASSY_FN_IS_BARCODE_PRINTED_FOR_RUNNINGPART]    Script Date: 30-09-2026 14:44:31 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION  [dbo].[ASSY_FN_IS_BARCODE_PRINTED_FOR_RUNNINGPART]
(
@LINECODE VARCHAR(20)=NULL
,@PROFITCENTERCODE VARCHAR(20)=NULL
)
RETURNS BIT
AS
BEGIN

-- AUTHOR:		<RAVISHANKAR MISHRA>
-- CREATE DATE: < 22-02-2016>
----SELECT DBO.ASSY_FN_IS_BARCODE_PRINTED_FOR_RUNNINGPART('M07','0021')
	
						DECLARE @DATECODE CHAR(4)
						DECLARE @PARTNO VARCHAR(30)
						DECLARE @MACHINECODE VARCHAR(20)
						DECLARE @VSPRINTEDBARCODE AS INT,@CREATEDDATE DATETIME,@RETVAL BIT=0
						
						SELECT TOP 1 @DATECODE=DATECODE,@PARTNO=ASSY_PARTNO,@CREATEDDATE=CREATEDDATE FROM ASSY_RUNNINGPART WITH (NOLOCK) 
						WHERE PROFITCENTERCODE=@PROFITCENTERCODE  
						AND LINECODE=@LINECODE  ORDER BY CREATEDDATE DESC
												
						SELECT @MACHINECODE= MACHINECODE  FROM ROUTINGCONFIGLINEWISE(NOLOCK) WHERE ISNULL(TRACEABILITY,0)=1 AND OPERATIONSEQNO=1 AND LINECODE =@LINECODE
						AND PROFITCENTERCODE=@PROFITCENTERCODE
    
					SELECT @VSPRINTEDBARCODE=COUNT(BARCODE) FROM ASSY_LINEASSYSTATUS_RUNNING WITH(NOLOCK)
					WHERE 	PROFITCENTERCODE=@PROFITCENTERCODE 
					AND LINECODE= @LINECODE
					AND MACHINECODE =@MACHINECODE
					AND ISNULL(ISTALLYCHARTAPPROVED,0)=0
					AND DATECODE=@DATECODE
					AND PARTNO=@PARTNO
					AND SCANTIMESTAMP>=@CREATEDDATE
					
					IF @VSPRINTEDBARCODE=0
					BEGIN
							SELECT @VSPRINTEDBARCODE=COUNT(BARCODE) FROM ASSY_LINEASSYSTATUS WITH(NOLOCK)
							WHERE 	PROFITCENTERCODE=@PROFITCENTERCODE 
							AND LINECODE= @LINECODE
							AND MACHINECODE =@MACHINECODE
							AND ISNULL(ISTALLYCHARTAPPROVED,0)=0
							AND DATECODE=@DATECODE
							AND PARTNO=@PARTNO
							AND SCANTIMESTAMP>=@CREATEDDATE

					END
														 
					IF ISNULL(@VSPRINTEDBARCODE,0)>0
						SET @RETVAL= 1
					ELSE
					   SET @RETVAL= 0
				 RETURN @RETVAL
END
GO
/****** Object:  UserDefinedFunction [dbo].[ASSY_FN_ISPARTTESTEDATFV_FORPOKAYOKE]    Script Date: 30-09-2026 14:44:31 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[ASSY_FN_ISPARTTESTEDATFV_FORPOKAYOKE]
(
	@PROFITCENTERCODE VARCHAR(20),
	@LINECODE VARCHAR(20),
	@MACHINECODE VARCHAR(20) = NULL,
	@OPERATIONCODE VARCHAR(20) = NULL
)
RETURNS BIT
AS
BEGIN
	/*
	CREATED BY :<RAVISHANKAR MISHRA>
	CREATED ON :<24/12/2015>
	MODIFIED BY :<RASHID SIDDIQUI>
	MODIFIED ON :<18-AUG-2016>
	SELECT DBO.ASSY_FN_ISPARTTESTEDATFV_FORPOKAYOKE ('0021','M02','MCMS','OCMSLH')
	*/
	DECLARE @RETVAL BIT = 0, @DATECODE CHAR(4), @PARTNO VARCHAR(20), @CREATEDDATE DATETIME
	
	SELECT TOP 1 @PARTNO = ASSY_PARTNO, @DATECODE = DATECODE, @CREATEDDATE = CREATEDDATE FROM ASSY_RUNNINGPART WITH(NOLOCK) 
		WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE 
			ORDER BY CREATEDDATE DESC
		
	IF NOT EXISTS
	(	
		SELECT TOP 1 1 FROM ASSY_POKAYOKE_COMPLETED_DTL WITH (NOLOCK)
			WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND DATECODE = @DATECODE
	)
	BEGIN
		IF EXISTS
		(
			SELECT TOP 1 1 FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE 
				AND DATECODE = @DATECODE AND MACHINECODE = DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE)
					AND PARTNO = @PARTNO AND SCANTIMESTAMP >= @CREATEDDATE AND ISNULL(ISTALLYCHARTAPPROVED,0) = 0 AND ISNULL(STATUS,'') != ''
		)
		BEGIN
			IF EXISTS
			(
				SELECT 1 FROM ASSY_SCAN_OK WITH (NOLOCK) WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE 
				AND OPERATIONCODE = @OPERATIONCODE AND ISNULL(ISPOKAYOKECOMPLETED,0) = 1
			)
			BEGIN
				SET @RETVAL = 1
			END
			ELSE
			BEGIN
				SET @RETVAL = 0
			END
		END
		ELSE
			SET @RETVAL = 0
	END
	ELSE IF EXISTS
	(
		SELECT TOP 1 1 FROM ASSY_POKAYOKE_COMPLETED_DTL WITH (NOLOCK)
			WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND DATECODE = @DATECODE AND PARTNO = @PARTNO	
	)
	BEGIN
		DECLARE @MAXID INT = -1
		
		SELECT @MAXID = MAX(ISNULL(ID,0)) FROM ASSY_POKAYOKE_COMPLETED_DTL WITH (NOLOCK)
			WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND DATECODE = @DATECODE AND PARTNO = @PARTNO
				  
		IF @MAXID >= 1
		BEGIN
			IF EXISTS
			(
				SELECT TOP 1 PARTNO FROM ASSY_POKAYOKE_COMPLETED_DTL WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE AND DATECODE = @DATECODE AND PARTNO = @PARTNO AND ID = @MAXID AND ISNULL(IS_FV_COMPLETED,0) = 1
			)
			BEGIN
				IF EXISTS
				(
					SELECT 1 FROM ASSY_SCAN_OK WITH (NOLOCK) WHERE LINECODE=@LINECODE AND MACHINECODE = @MACHINECODE 
						AND OPERATIONCODE = @OPERATIONCODE AND ISNULL(ISPOKAYOKECOMPLETED,0) = 1 
				)
				BEGIN
					IF EXISTS
					(
						SELECT TOP 1 1 FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE 
							AND DATECODE = @DATECODE AND MACHINECODE = DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE)
								AND PARTNO = @PARTNO AND SCANTIMESTAMP >= @CREATEDDATE AND ISNULL(ISTALLYCHARTAPPROVED,0) = 0 AND ISNULL(STATUS,'') != ''
					)
					BEGIN
						SET @RETVAL = 1
					END
				END
				ELSE
				BEGIN
					SET @RETVAL = 0
				END
			END
			ELSE
			BEGIN
				SET @RETVAL = 0
			END
		END			  					
	END
	ELSE
	BEGIN
		SET @RETVAL=0
	END
	
	RETURN @RETVAL
END
GO
