CREATE FUNCTION [dbo].[Assy_FN_IsPartTestedAtFV_ForPokaYoke_temp]
(
@PROFITCENTERCODE VARCHAR(20),
@LINECODE VARCHAR(20),
@MachineCode VArchar(20)=null,
@OperationCode varchar(20)=null
)
RETURNS BIT
AS
BEGIN
--CREATED BY :<RAVISHANKAR MISHRA>
--CREATED ON :<24/12/2015>
--Modified BY :<RAVISHANKAR MISHRA>
--Modified ON :<27/02/2016>
--SELECT DBO.ASSY_FN_ISPARTTESTEDATFV_FORPOKAYOKE('0021','M02')
		DECLARE @RETVAL BIT=0,@DATECODE CHAR(4),@PARTNO VARCHAR(20),@CreatedDate DateTime
		SELECT TOP 1 @PARTNO=ASSY_PARTNO,@DATECODE=DATECODE,@CreatedDate=CreatedDate FROM ASSY_RUNNINGPART WITH(NOLOCK) 
		WHERE PROFITCENTERCODE =@PROFITCENTERCODE AND  LINECODE =@LINECODE 
		ORDER BY CREATEDDATE  DESC
		
		IF NOT EXISTS
		(	
			SELECT TOP 1 1 FROM ASSY_POKAYOKE_COMPLETED_DTL WITH (NOLOCK)
			WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE AND DATECODE =@DATECODE
		)
		BEGIN
				if exists
				(
							select top 1 1 from assy_lineassystatus with(nolock) where ProfitCenterCode=@profitcentercode 
							and linecode=@linecode 
							and Datecode=@Datecode and MachineCode=dbo.Assy_FN_Get_FinalViewing_MachineCode_From_LineCode(@profitcentercode,@linecode)
							and PartNo=@PartNo and ScanTimestamp>=@CreatedDate and isnull(IsTallyChartApproved,0)=0 and isnull(status,'')!=''							
				)
				begin
							if exists
							(
								select 1 from Assy_Scan_OK with (nolock) where linecode=@linecode and MachineCode=@MachineCode 
								and operationcode=@operationcode and isnull(isPokaYokeCompleted,0)=1 
							)
							begin
									SET @RETVAL=1
							end
							else
							begin
									SET @RETVAL=0
							end
				end
				else
							SET @RETVAL=0

		end
		else IF EXISTS
		(	
			SELECT TOP 1 1 FROM ASSY_POKAYOKE_COMPLETED_DTL WITH (NOLOCK)
			WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE AND DATECODE =@DATECODE AND PARTNO=@PARTNO	
		)
		BEGIN	
					DECLARE @MAXID INT=-1
					SELECT @MAXID=MAX(ISNULL(ID,0)) FROM ASSY_POKAYOKE_COMPLETED_DTL(NOLOCK)
					 WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE AND DATECODE =@DATECODE 	
				  
					   IF @MAXID>=1
					   BEGIN						
								IF EXISTS
								(
									SELECT TOP 1 PARTNO FROM ASSY_POKAYOKE_COMPLETED_DTL WITH (NOLOCK)
									WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE AND DATECODE =@DATECODE AND PARTNO=@PARTNO	AND ID=@MAXID
									AND ISNULL(IS_FV_COMPLETED,0)=1
								)
								BEGIN
										if exists
										(
											select 1 from Assy_Scan_OK with (nolock) where linecode=@linecode and MachineCode=@MachineCode 
											and operationcode=@operationcode and isnull(isPokaYokeCompleted,0)=1 
										)
										begin
												SET @RETVAL=1
										end
										else
										begin
												SET @RETVAL=0
										end
								END
								ELSE
									BEGIN
										SET @RETVAL=0
									END
					 END			  					
		END
		ELSE
			BEGIN
				    SET @RETVAL=0
			END
	RETURN @RETVAL
END
