	create FUNCTION [dbo].[assy_fnGetScannedStationIndex](@LineCode varchar(20), @OperationCode varchar(20))
	RETURNS int
	AS 
	Begin
	  declare @IsTwinIndex bit = 0;
	  declare @MachineCode varchar(20);
	  declare @StationIndex int = -1;
	  declare @InsideStationIndex int = -1;
	  set @MachineCode = (select dbo.assy_fnGetMachineCodeFromOperationCode(@OperationCode, @LineCode))
      set @IsTwinIndex = (select dbo.assy_fnIsTwinIndexStation(@MachineCode)) 
	  if(@IsTwinIndex = 1)
	  Begin
	    set @InsideStationIndex = ( select top 1 StationCode from Assy_Stations_Zig_In_Out_Status where OperationCode = @OperationCode and Linecode = @LineCode)
		if(@InsideStationIndex = 1)
		  set @StationIndex = 2
		else
		   set @StationIndex = 1
	  End 

	  return @StationIndex
	End


