/****** Object:  UserDefinedFunction [dbo].[FN_GET_DATE_FROM_DATECODE]    Script Date: 30-09-2026 14:44:31 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[FN_GET_DATE_FROM_DATECODE]
(
@DATECODE VARCHAR(10),
@PROFITCENTERCODE VARCHAR(4)
)
--@RETURNVALUE VARCHAR (2000)=NULL OUT,
RETURNS DATE
AS 
BEGIN

DECLARE @DATE DATE,@DAY VARCHAR(10),@YEAR INT, @WEEK INT,@WEEKDAY INT
SELECT @WEEK=CONVERT(INT,LEFT(@DATECODE,2))
SELECT @YEAR=YEAR FROM YEARMST WITH(NOLOCK) WHERE CODE=RIGHT(@DATECODE,1)
SELECT @DAY= SUBSTRING(@DATECODE,3,1)  
 
;WITH CTE
AS
(
SELECT CASE  @DAY
WHEN DCM.MONDAY THEN 1
WHEN DCM.TUESDAY THEN 2
WHEN DCM.WEDNESDAY THEN 3
WHEN DCM.THURSDAY THEN 4
WHEN DCM.FRIDAY THEN  5
WHEN DCM.SATURDAY THEN 6
WHEN DCM.SUNDAY THEN 7
END 'DAYCODE' --SM.FROMTIME,SM.TOTIME
FROM DATECODEMST DCM WITH(NOLOCK) 
--LEFT JOIN SHIFTMST SM WITH(NOLOCK) 
--ON DCM.SHIFTCODE=SM.SHIFTCODE
WHERE DCM.PROFITCENTERCODE=@PROFITCENTERCODE
)
SELECT @WEEKDAY=DAYCODE FROM CTE WHERE ISNULL(DAYCODE,'')<>''
 
SELECT @DATE= CASE
            WHEN @YEAR < 1900 OR @YEAR > 9999 THEN NULL
            WHEN @WEEK < 1 OR @WEEK > 53 THEN NULL
            WHEN @WEEKDAY < 1 OR @WEEKDAY > 7 THEN NULL
            WHEN @YEAR = 9999 AND @WEEK = 52 AND @WEEKDAY > 5 THEN NULL
            WHEN DATEPART(YEAR, DATEADD(DAY, 7 * @WEEK + DATEDIFF(DAY, 4, DATEADD(YEAR, @YEAR - 1900, 7)) / 7 * 7, -4)) <> @YEAR THEN NULL
            ELSE DATEADD(DAY, 7 * @WEEK + DATEDIFF(DAY, 4, DATEADD(YEAR, @YEAR - 1900, 7)) / 7 * 7, @WEEKDAY - 8)
        END
RETURN @DATE

END
GO
