/***************************************************************************************
PROCEDURE:		FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE
AUTHOR:			NITIN SINGHAL
DATE WRITTEN:	2018-01-02
PURPOSE:		FUNCTION WILL GIVE THE EXTENDED ATTRIBUTE VALUE FOR LINE CODE OR LINE TYPE CODE
				
****************************************************************************************/
CREATE FUNCTION [dbo].[FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE]
(
	@P_WH_CODE			NVARCHAR(10),
	@P_TYPE_CATEGORY_CD	NVARCHAR(100)= '',
	@P_TYPE_CD			NVARCHAR(100),
	@P_LINE_CODE		NVARCHAR(10),
	@P_LINE_TYPE_CODE	NVARCHAR(20)
)RETURNS NVARCHAR(1000)
BEGIN
	DECLARE @ATTRB_VAL NVARCHAR(1000) = ''

	SELECT @ATTRB_VAL = ISNULL(NULLIF(ATTRB_VAL,''),'') FROM TYPE_DEFINITION_XREF_DATA (NOLOCK) 
	WHERE TYPE_CATEGORY_CD = @P_TYPE_CATEGORY_CD AND TYPE_CD = @P_TYPE_CD AND STS_CD = 0 AND WH_CODE = @P_WH_CODE AND ATTRB_CD = @P_LINE_CODE

	IF ISNULL(@ATTRB_VAL,'') = ''
	BEGIN
		SELECT @ATTRB_VAL = ISNULL(NULLIF(ATTRB_VAL,''),'') FROM TYPE_DEFINITION_XREF_DATA (NOLOCK) 
		WHERE TYPE_CATEGORY_CD = @P_TYPE_CATEGORY_CD AND TYPE_CD = @P_TYPE_CD AND STS_CD = 0 AND WH_CODE = @P_WH_CODE AND ATTRB_CD = @P_LINE_TYPE_CODE

	END
	RETURN @ATTRB_VAL
END

GO
