/************************************************************************************************************  
(C) 2005 MothersonSumi Infotech & design Ltd, All rights reserved        
FUNCTION:  FN_GRID_SPLIT_STRING  
AUTHOR:  NK/SPC                               
DATE WRITTEN: SEPT 20, 2008  
PURPOSE: to spilt Grid String  
MODIFIED BY:        
DATE MODIFIED:        
REVISION HISTORY :     
TEST SCRIPT:                              
************************************************************************************************************/  
  
CREATE FUNCTION [dbo].[FN_GRID_SPLIT_STRING]  
(  
    @string VARCHAR(8000),  
    @delimiter_col CHAR(1),  
    @delimiter_row char(1)  
)  
RETURNS @output TABLE(  
    ROW_NO INT, col1 VARCHAR(150),col2 VARCHAR(150),col3 VARCHAR(150),col4 VARCHAR(150),col5 VARCHAR(150),  
 col6 VARCHAR(150), col7 VARCHAR(150), col8 VARCHAR(150),col9 VARCHAR(150),col10 VARCHAR(150)    ,  
 col11 VARCHAR(150),coL12 VARCHAR(150), col13 VARCHAR(150),col14 VARCHAR(150),col15 VARCHAR(150) ,  
 col16 VARCHAR(150),col17 VARCHAR(150),col18 VARCHAR(150), col19 VARCHAR(150),col20 VARCHAR(150)  ,  
 col21 VARCHAR(150),col22 VARCHAR(150),col23 VARCHAR(150),col24 VARCHAR(150), col25 VARCHAR(150)   ,  
        col26 VARCHAR(150),col27 VARCHAR(150),col28 VARCHAR(150),col29 VARCHAR(150),col30 VARCHAR(150)  ,  
 col31 VARCHAR(150),col32 VARCHAR(150), col33 VARCHAR(150),col34 VARCHAR(150),col35 VARCHAR(150)   ,  
 col36 VARCHAR(150),coL37 VARCHAR(150),col38 VARCHAR(150),col39 VARCHAR(150),col40 VARCHAR(150)  ,  
 col41 VARCHAR(150),col42 VARCHAR(150),col43 VARCHAR(150),col44 VARCHAR(150),coL45 VARCHAR(150)  ,  
 col46 VARCHAR(150),col47 VARCHAR(150),col48 VARCHAR(150),col49 VARCHAR(150), col50 VARCHAR(150)  
)  
BEGIN  
 declare @start_row int,@end_row int,@count_row int,@count_col int  
 DECLARE @start INT, @end INT  
 declare @string_row varchar(8000)  
 select @start_row=1,@end_row=charindex(@delimiter_row,@string)  
  
SET @count_row=1  
 while @start_row< len(@string)+1  
 begin   
          if @end_row=0  
    set @end_row=len(@string)+1  
          
    select @string_row= SUBSTRING(@string, @start_row, @end_row - @start_row)  
    SET @start_row = @end_row + 1  
    SET @end_row = CHARINDEX(@delimiter_row, @string, @start_row)   
  
      
    SELECT @start = 1, @end = CHARINDEX(@delimiter_col, @string_row)  
                set @count_col=1   
  
    WHILE @start < LEN(@string_row) + 1 BEGIN  
     IF @end = 0   
      SET @end = LEN(@string_row) + 1  
  
                        if @count_col=1  
    INSERT INTO @output (ROW_NO,col1) VALUES(@count_row,SUBSTRING(@string_row, @start, @end - @start))  
                            
   if @count_col=2  
                         update @output set col2=SUBSTRING(@string_row, @start, @end - @start) where ROW_NO =@count_row  
  
   if @count_col=3  
                         update @output set col3=SUBSTRING(@string_row, @start, @end - @start) where ROW_NO =@count_row  
        
   if @count_col=4  
                         update @output set col4=SUBSTRING(@string_row, @start, @end - @start) where ROW_NO =@count_row  
                         
   if @count_col=5  
                         update @output set col5=SUBSTRING(@string_row, @start, @end - @start) where ROW_NO =@count_row  
  
   if @count_col=6  
                         update @output set col6=SUBSTRING(@string_row, @start, @end - @start) where ROW_NO =@count_row  
  
   if @count_col=7  
                         update @output set col7=SUBSTRING(@string_row, @start, @end - @start) where ROW_NO =@count_row  
        
   if @count_col=8  
                         update @output set col8=SUBSTRING(@string_row, @start, @end - @start) where ROW_NO =@count_row  
                         
   if @count_col=9  
