GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[Assy_VIEW_LineAssyStatus_Both]
AS
-- SELECT * FROM [Assy_VIEW_LineAssyStatus_Both]
SELECT	0 AS 'OperationSeqNo', A.ProfitCenterCode, A.LineCode, A.StationCode, A.Datecode, A.MachineCode, A.Barcode,
		'' AS 'TagName', 0 AS 'Value', A.Status AS Result, '' AS 'NotProcessedStatus', 0 AS 'RePrint', A.UserID, A.ResultTimestamp,
		A.PartNo, A.IsTallyChartApproved, ISNULL(A.IsReworkPart,0) IsReworkPart
	FROM Assy_LineAssyStatus_Running (NOLOCK) A
		WHERE ISNULL(A.Status,'') <> '' AND ISNULL(A.IsReworkPart,0) = 0 AND A.Datecode != 'PKYK' AND ISNULL(A.IsTallyChartApproved,0) = 0
UNION
SELECT 0 AS 'OperationSeqNo', A.ProfitCenterCode, A.LineCode, A.StationCode, A.Datecode, A.MachineCode, A.Barcode,
		'' AS 'TagName', 0 AS 'Value', A.Status AS Result, '' AS 'NotProcessedStatus', 0 AS 'RePrint', A.UserID, A.ResultTimestamp,
		A.PartNo, A.IsTallyChartApproved, ISNULL(A.IsReworkPart,0) IsReworkPart
	FROM Assy_LineAssyStatus (NOLOCK) A
		WHERE ISNULL(A.Status,'') <> '' AND ISNULL(A.IsReworkPart,0) = 0 AND A.Datecode != 'PKYK'  AND ISNULL(A.IsTallyChartApproved,0) = 0		

