/****** Object:  View [dbo].[Assy_View_ParamData]    Script Date: 30-09-2026 14:44:32 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [dbo].[Assy_View_ParamData]
AS
SELECT        TOP (100) PERCENT P.Barcode, T .TagName, D .Value, T .TagId, P.LineCode, P.StationCode, P.Datecode, P.MachineCode, P.OperationCode, P.ProfitCenterCode,  P.Result, P.Timestamp, P.PartNo
FROM            dbo.Assy_LineAssyParamData AS P WITH (nolock) INNER JOIN
                         dbo.Assy_LineAssyParamData_Dtl AS D WITH (nolock) ON P.UID = D .UID INNER JOIN
                         dbo.TagMst AS T WITH (nolock) ON T .TagId = D .TagId
						 
UNION
SELECT        TOP (100) PERCENT P.Barcode, T .TagName, D .Value, T .TagId, P.LineCode, P.StationCode, P.Datecode, P.MachineCode, P.OperationCode, P.ProfitCenterCode, 
                         P.Result, P.Timestamp, P.PartNo
FROM            dbo.Assy_LineAssyParamData_Running AS P WITH (nolock) INNER JOIN
                         dbo.Assy_LineAssyParamData_Running_Dtl AS D WITH (nolock) ON P.UID = D .UID INNER JOIN
                         dbo.TagMst AS T WITH (nolock) ON T .TagId = D .TagId
						 
UNION
SELECT        alpd.Barcode,  isnull(alpd.TagName,'MCFV Barcode') as TagName, alpd.Barcode AS Value, 0 AS TagId, alpd.LineCode, StationCode, alpd.DateCode, alpd.MachineCode, 
                         alpd.OperationCode, alpd.ProfitcenterCode, Result, Timestamp, alpd.PartNo
FROM            Assy_LineAssyParamData alpd(nolock) 
WHERE        alpd.MachineCode = 'MCFV'
			
UNION
SELECT        alpd.Barcode,  isnull(alpd.TagName,'MCFV Barcode') as TagName, afrbm.Barcode AS Value, 0 AS TagId, alpd.LineCode, StationCode, alpd.DateCode, alpd.MachineCode, 
                         alpd.OperationCode, alpd.ProfitcenterCode, Result, Timestamp, alpd.PartNo
FROM            Assy_LineAssyParamData_Running alpd(nolock) INNER JOIN
                         Assy_FinalViewing_RFID_Barcode_Mapping afrbm(nolock) ON afrbm.RFID = alpd.Barcode
WHERE         afrbm.MachineCode='MCFV' 
			 






GO
