/****** Object:  StoredProcedure [dbo].[ASSY_Barcode_Print_Control]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[ASSY_Barcode_Print_Control]
	@ProfitCenterCode VARCHAR(10) = '',
	@LineCode VARCHAR(10) = ''
AS
BEGIN

DECLARE @LatestSequenceNumber VARCHAR(10) = '0',
		@LastScanSequenceNumber VARCHAR(10) = '0',
		@PartNo VARCHAR(25) = '',
		@Datecode VARCHAR(5),
		@OutMessage VARCHAR(500),
		@OutStatus INT,
		@PrintLimit INT = 0

	SELECT Top 1 @PartNo = Assy_PartNo, @Datecode = Datecode FROM Assy_RunningPart (NOLOCK) WHERE Linecode = @LineCode
	PRINT @PartNo
	PRINT @Datecode
	
	SELECT @LatestSequenceNumber = ISNULL([Counter],'0') FROM ASSY_Vision_System_Log (NOLOCK) WHERE PartNumber = @PartNo AND linecode = @LineCode;

	IF EXISTS(SELECT 1 FROM Assy_LineAssyStatus (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND PartNo = @PartNo AND datecode = @Datecode AND machinecode <>'MCSTRK')
	BEGIN
		SELECT TOP 1 @LastScanSequenceNumber = SUBSTRING(Barcode, 13, 8)  FROM Assy_LineAssyStatus (NOLOCK) WHERE  ProfitCenterCode = @ProfitCenterCode AND PartNo = @PartNo AND Datecode = @Datecode AND MachineCode <>'MCSTRK'
			ORDER BY SUBSTRING(Barcode, 13, 8) desc ;
	END
	
	PRINT 'LatestSequenceNumber ' + CONVERT(VARCHAR(10),(CONVERT(INT,@LatestSequenceNumber)))
	
	PRINT 'LastScanSequenceNumber' + CONVERT(VARCHAR(10),CONVERT(INT,@LastScanSequenceNumber))

	PRINT 'Difference '  + CONVERT(VARCHAR(10),(CONVERT(INT,@LatestSequenceNumber) - CONVERT(INT,@LastScanSequenceNumber)))
	/*
		INSERT INTO [dbo].[PARAMETER_MST]
           ([PARAMETER_C],[PARAMETER_C1],[PARAMETER_C2],[PARAMETER_NM],[PARAMETER_VALUE],[REMARKS],[wh_code],[ENT_STAMP],[ENT_BY],[LAST_UPD_STAMP],[LAST_UPD_BY],[USER_CONFIGURABLE_FLG])
		SELECT 'AssLine','FinalViewing','Limit_Barcode','Limit_Barcode',10,'Limit the Print Barcode in Servo Line','0021',GETDATE(),'admin',GETDATE(),'admin',1
	*/
	-- To Fetch Print Limit From PARAMETER_MST table
	SELECT @PrintLimit = ISNULL(PARAMETER_VALUE,5) FROM PARAMETER_MST(NOLOCK) WHERE PARAMETER_C = 'AssLine' AND PARAMETER_C1 = 'FinalViewing' AND PARAMETER_C2 = 'Limit_Barcode'
	
	PRINT '@PrintLimit - ' + @PrintLimit
	IF ((@PrintLimit = 0) OR (@PrintLimit IS NULL))
	BEGIN
		SET @PrintLimit = 5
	END

	PRINT '@PrintLimit - ' + CONVERT(VARCHAR(5),@PrintLimit)

	IF (CONVERT(INT,@LatestSequenceNumber) - CONVERT(INT,@LastScanSequenceNumber) > @PrintLimit)
	BEGIN
		SET @OutMessage = 'Already there are ' + CONVERT(VARCHAR(10),(CONVERT(INT,@LatestSequenceNumber) - CONVERT(INT,@LastScanSequenceNumber))) + ' barcodes in queue.'
		SET @OutStatus = 0
		SELECT @OutMessage OutMessage, @OutStatus OutStatus
		UPDATE ASSY_STROKING_PRINTSIGNAL SET PrintSignal = 0,Timestamp = GETDATE()
			WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @Linecode AND MachineCode = 'MCSTRK'
			--SELECT * FROM ASSY_STROKING_PRINTSIGNAL WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @Linecode AND MachineCode = 'MCSTRK'
	END
	ELSE
	BEGIN
		SET @OutMessage = 'OK'
		SET @OutStatus = 1
		SELECT @OutMessage OutMessage, @OutStatus OutStatus
	END
END
GO
/****** Object:  StoredProcedure [dbo].[Assy_Get_Line_ManPower]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[Assy_Get_Line_ManPower]
(
			@ProfitCenterCode Varchar(10) = null,
			@LineCode Varchar(10) = null,
			@PartNumber Varchar(10) = null,
			@DateCode Varchar(10) = null 
)
AS
BEGIN   
		
		-- Author:		<Aasiya>
		-- Create date: < 31-12-2015>
		-- Description:	<Gets line's stations and their clock ids>
		-- EXEC [Assy_Get_Line_ManPower] '0021','M07','','01Nc'
			SET NOCOUNT  ON
			--Get Station and Clock IDs for the line, part and date code.

			SELECT Top 1 @PartNumber = ISNULL(RTRIM(Assy_PartNo),'') FROM Assy_RunningPart (NOLOCK) WHERE LineCode = @LineCode Order By CreatedDate Desc

			SELECT Distinct RCL.ManPowerSeqNo as SeqNo, RCL.MachineCode as StationCode, MM.MachineName as StationName,  IsNull(AMP.Clock_ID,'NA') as ClockID
			FROM RoutingConfigLineWise RCL
					LEFT OUTER JOIN Assy_Manpower4S AMP
						ON (AMP.StationCode=RCL.MachineCode AND 
								AMP.ProfitCenterCode=@ProfitCenterCode AND
								AMP.LineCode=@LineCode AND
								AMP.DateCode=@DateCode AND 
								AMP.Created_TimeStamp=(SELECT MAX(Created_TimeStamp) FROM Assy_Manpower4S
													    WHERE ProfitCenterCode=@ProfitCenterCode AND
																	  LineCode=@LineCode AND
																	  DateCode=@DateCode AND StationCode=AMP.StationCode))
					INNER JOIN MachineMst MM
						ON (MM.MachineCode=RCL.MachineCode)
							WHERE RCL.LineCode = @LineCode --AND RCL.OperationRequired = 1 AND Traceability = 1
			
			ORDER BY RCL.ManPowerSeqNo ASC


		 -- Get ClockIDs for combobox input fields
		  SELECT [User_Code] as Clock_ID 
		  FROM		
				TL_MF_SEC_USER_MST		  		
		  WHERE 
			[USER_ID] IN (SELECT GMAP2.[USER_ID] 
						  FROM   Assy_RunningPart ARP
							INNER JOIN TL_MF_SEC_USER_MST UM2
								ON (UM2.[USER_CODE]=ARP.CreatedBy)
							INNER JOIN TL_MF_SEC_GROUP_USER_MAP_MST GMAP1 
								ON (GMAP1.[USER_ID]=UM2.[USER_ID])
							INNER JOIN TL_MF_SEC_GROUP_USER_MAP_MST GMAP2
								ON (GMAP2.GROUP_ID=GMAP1.GROUP_ID))
									Order By 1;

		  
		--Get History of changes done for the line and datecode.

		SELECT MM.MachineName as [Station Name],
				AMP.DateCode [Date Code],
				AMP.PartNo [Part Number],
				IsNull(AMP.Clock_ID,'NA')as [Clock ID],
				UM.[USER_NAME] as [Created By],
				AMP.Created_TimeStamp as [Date Time]
			FROM  Assy_Manpower4S AMP
					INNER JOIN MachineMst MM
						ON (MM.MachineCode=AMP.StationCode)
					INNER JOIN TL_MF_SEC_USER_MST UM
						ON (UM.[USER_CODE]=AMP.Created_By)
		WHERE AMP.ProfitCenterCode=@ProfitCenterCode AND
			  AMP.LineCode=@LineCode AND
			  AMP.DateCode=@DateCode
		ORDER BY AMP.Created_TimeStamp DESC, AMP.StationCode ASC
  END


GO
