CREATE Procedure  [dbo].[ASSY_GETSTROKINGSCANNINGRESULT]
@OUTPUT NVARcHAR(MAX) OUTPUT
as
begin
       select  top 1 BARCODE,case when isnull(RESULT,0)=1 then 'PASS'else 'FAIL' end AS RESULT ,MESSAGE From ASSY_STROKING_SCANNING_RESULT
end

