/****** Object:  StoredProcedure [dbo].[Assy_Insert_FV_Data_From_Local_To_MainServer]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[Assy_Insert_FV_Data_From_Local_To_MainServer]
	@DateCode CHAR(4) = NULL,
	@ProfitCenterCode VARCHAR(10) = NULL,
	@LineCode VARCHAR(10) = NULL,
	@RETURNVALUE VARCHAR (2000) = NULL OUT,
	@RETURNINT INT = NULL OUT
AS
BEGIN
	-- AUTHOR		:	Rashid Siddiqui
	-- CREATE DATE	:	08th Jan 2016
	-- DESCRIPTION	:	Copy FV Data From Local Server to Main Server

	-- EXEC Assy_Insert_FV_Data_From_Local_To_MainServer @DateCode = '01Vc'
	SET NOCOUNT ON;
	Declare @OpCode VARCHAR(15) = '', @FV_Count INT = 0, @LinkServerName VARCHAR(500), @ExecQuery NVARCHAR(MAX)
		
		IF ISNULL (@ProfitCenterCode, '') = ''
			SET @ProfitCenterCode = '0021'	
		
		--SELECT Top 1 @LineCode = ISNULL(LineCode,'') FROM LineMst (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
		
		IF @LineCode <> ''
		BEGIN
			SELECT @LinkServerName = LinkServerName + '.' + DataBaseName FROM Assy_LinkServer_Dtl  WITH (NOLOCK) 
				WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode

			SELECT @OpCode = dbo.Assy_FN_Get_FinalViewing_OperationCode_From_LineCode(@ProfitCenterCode,@LineCode)
			IF @OpCode = ''
			BEGIN
				IF (LEFT(@LineCode,1) = 'M')
					SET @OpCode = 'OCFV'
				ELSE IF(LEFT(@LineCode,1) = 'P')
					SET @OpCode = 'OCFVSTMC'
			END

			IF ISNULL(@DateCode,'') = ''
			BEGIN
				SELECT Top 1 @DateCode = Datecode FROM Assy_RunningPart (NOLOCK) WHERE LineCode = @LineCode Order by CreatedDate Desc

				IF ISNULL(@DateCode,'') = ''
				BEGIN
					SELECT Top 1 @DateCode = Datecode FROM Assy_RunningPart_History (NOLOCK) WHERE LineCode = @LineCode Order by CreatedDate Desc
				END
			END

			IF (ISNULL(@DateCode,'') != '' AND @OpCode != '')
			BEGIN
				SET @ExecQuery = '
				INSERT INTO ' + @LinkServerName + '.dbo.Assy_LineAssystatus (ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,Status,FailCount,Datecode,PartNo,ScanTimestamp,ResultTimestamp,Active,UserID,IsTallyChartApproved,Transaction_Number,isConfirmed,Kanban_Id,ERP_Conf_Timestamp,IsReworkPart,Is_Manual)
				SELECT S.ProfitCenterCode,S.LineCode,S.MachineCode,S.OperationCode,S.StationCode,S.Barcode,S.Status,S.FailCount,S.Datecode,S.PartNo,
				S.ScanTimestamp,S.ResultTimestamp,S.Active,S.UserID,S.IsTallyChartApproved,S.Transaction_Number,S.isConfirmed,S.Kanban_Id,
				S.ERP_Conf_Timestamp,S.IsReworkPart,S.Is_Manual
					FROM ' + @LinkServerName + '.dbo.Assy_LineAssyStatus  T (NOLOCK)
							RIGHT OUTER JOIN Assy_LineAssyStatus S (NOLOCK)
								ON T.ProfitCenterCode = S.ProfitCenterCode AND T.LineCode = S.LineCode AND T.MachineCode = S.MachineCode
									AND T.OperationCode = S.OperationCode
									AND T.Datecode = S.Datecode AND T.Barcode = S.Barcode AND T.DateCode = ''' + @DateCode + '''
									AND T.ProfitCenterCode = ''' + @ProfitCenterCode + ''' AND T.LineCode = ''' + @LineCode + '''
									AND T.OperationCode = ''' + @OpCode + '''
									 WHERE S.ProfitCenterCode = ''' + @ProfitCenterCode + ''' AND S.LineCode = ''' + @LineCode + '''
									 And  ISNULL(S.Status, '''') <> ''''  
										AND S.OperationCode = ''' + @OpCode + ''' AND S.Datecode = ''' + @DateCode + ''' AND ISNULL(T.Barcode,'''') = ''''
										'
				
				PRINT @ExecQuery
				EXEC (@ExecQuery)
				SELECT @FV_Count = @@ROWCOUNT

				IF EXISTS (SELECT 1 FROM Assy_FinalViewing_RFID_Barcode_Mapping WITH (NOLOCK) 
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode 
					AND OperationCode = @OpCode AND Datecode = @DateCode)
				BEGIN
					SET @ExecQuery = ''
					SET @ExecQuery = '
					INSERT INTO ' + @LinkServerName + '.dbo.Assy_FinalViewing_RFID_Barcode_Mapping (ProfitCenterCode, LineCode, MachineCode, OperationCode, RFID, Barcode, Status, PartNo, Datecode, PrintedTimestamp, CaliperSerNo, CaliperDatecode, CustomerBarcodeScanValidation, ScanValidationTimeStamp)
					SELECT DISTINCT A.ProfitCenterCode, A.LineCode, A.MachineCode, A.OperationCode, A.RFID, A.Barcode, A.Status, A.PartNo, A.Datecode, A.PrintedTimestamp, A.CaliperSerNo, A.CaliperDatecode, A.CustomerBarcodeScanValidation, A.ScanValidationTimeStamp 
					FROM dbo.Assy_FinalViewing_RFID_Barcode_Mapping A with (nolock)
					INNER JOIN Assy_LineAssyStatus S (NOLOCK) ON A.ProfitCenterCode = S.ProfitCenterCode AND A.LineCode = S.LineCode AND A.MachineCode = S.MachineCode
					AND A.OperationCode = S.OperationCode AND A.RFID = S.Barcode AND A.PartNo = S.PartNo
					LEFT OUTER JOIN ' + @LinkServerName + '.dbo.Assy_FinalViewing_RFID_Barcode_Mapping M (NOLOCK)
					ON A.ProfitCenterCode = M.ProfitCenterCode AND A.LineCode = M.LineCode AND A.MachineCode = M.MachineCode
					AND A.OperationCode = M.OperationCode AND A.Datecode = M.Datecode AND A.Barcode = M.Barcode
					WHERE A.ProfitCenterCode = ''' + @ProfitCenterCode + ''' AND A.LineCode = ''' + @LineCode + ''' 
					AND A.OperationCode = ''' + @OpCode + ''' AND A.Datecode = ''' + @DateCode + '''
					AND ISNULL(M.Barcode, '''') = '''''

					EXEC (@ExecQuery)
					SELECT @FV_Count = @@ROWCOUNT
				END

				/*
				SET @ExecQuery = '
				MERGE ' + @LinkServerName + '.dbo.Assy_LineAssystatus AS D
				USING (SELECT * FROM Assy_LineAssystatus WHERE ProfitCenterCode = ''' + @ProfitCenterCode + '''
				 AND LineCode = ''' + @LineCode + ''' AND OperationCode = ''' + @OpCode + ''' AND Datecode = ''' + @DateCode + ''') AS S
				ON D.ProfitCenterCode = S.ProfitCenterCode AND D.LineCode = S.LineCode AND D.MachineCode = S.MachineCode 
				AND D.OperationCode = S.OperationCode 
				AND D.Barcode = S.Barcode
				WHEN NOT MATCHED THEN
									INSERT(	ProfitCenterCode,
											LineCode,
											MachineCode,
											OperationCode,
											StationCode,
											Barcode,
											Status,
											FailCount,
											Datecode,
											PartNo,
											ScanTimestamp,
											ResultTimestamp,
											Active,
											UserID,
											isTallyChartApproved)

										   VALUES(S.ProfitCenterCode,
											S.LineCode,
											S.MachineCode,
											S.OperationCode,
											S.StationCode,
											S.Barcode,
											S.Status,
											S.FailCount,
											S.Datecode,
											S.PartNo,
											S.ScanTimestamp,
											S.ResultTimestamp,
											Active,
											S.UserID,
											S.isTallyChartApproved);'
				PRINT @ExecQuery
				*/

				--EXEC (@ExecQuery)
				--SELECT @FV_Count = @@ROWCOUNT

				IF (@FV_Count > 0)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'Y'
					TRUNCATE TABLE Assy_LineAssyStatus_Network_Drop_Records
					PRINT CONVERT(VARCHAR(10),@FV_Count) + ' - Records Inserted successfully in Main Server'
				END
				ELSE
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'N'
					PRINT 'No Records Found'
				END
			END
		END
END


GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_AddPartMaster]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[Assy_Proc_AddPartMaster]
(
	@Condition VARCHAR(100) = NULL,
	@ProfitCenterCode VARCHAR(10) = NULL,
	@LineCode VARCHAR(10) = NULL,
	@SelectionType VARCHAR(20) = NULL,
	@NewPartNo VARCHAR(10) = NULL,
	@ReferencePartNo VARCHAR(10) = NULL,
	@BoostRatio VARCHAR(10) = NULL,
	@PartType VARCHAR(10) = NULL,
	@CustomerPartNo VARCHAR(18) = NULL,
	@PlantCode VARCHAR(10) = NULL,
	@ModelName VARCHAR(10) = NULL,
	@PartIdentificationCode VARCHAR(10) = NULL,
	@NewPokaYokeGroup INT = NULL,
	@PartRoutingExists INT = NULL,
	@TMCChildPart VARCHAR(10) = NULL,
	@ServoChildPart VARCHAR(10) = NULL,
	@UserID VARCHAR(20) = NULL,
	@PartID VARCHAR(10) = NULL,
	@TMCCuttingType VARCHAR(10) = NULL,
	@DateCodeEngravedRequired CHAR(1) = NULL,
	@NippleCutRequired CHAR(1) = NULL,
	@CapColorCode INT = NULL,
	@ReturnValue VARCHAR(MAX) = NULL OUT,
	@ReturnInt INT = NULL OUT
)
AS
BEGIN
	/*
	 Author:		<Rashid Siddiqui>
	 Create Date:	<16 March 2016>
	 Description:	<Add Part Master For TMC, Servo & STMC>
	 Modified Date: <29 April 2016>
	 Description:	<Poka Yoke Group is not taken from Reference PartNo>
	 Modified Date: <17 May 2017>
	 Description:	<Nissan Line 6 Add Part Master Logic>
	 Modified Date: <02 Aug 2018>
	 Description:	<Nissan Line 6 Add Part Master Logic For Cap Color Code>
	 Modified Date: <28 Sep 2018>
	 Description:	<Improved/Optimized Query>
	*/
	SET TRANSACTION ISOLATION LEVEL SNAPSHOT;
	BEGIN TRY
		
		Declare @GroupCode VARCHAR(50) = '', @MaxGroupValue INT = 0, @Part_FixtureGroupType VARCHAR(20), @GroupCodeLen INT = 0,
				@Material_TP VARCHAR(20) = '', @PRNGroupCode VARCHAR(20) = '', @ServoPartNo VARCHAR(10) = '', @TMCPartNo VARCHAR(10) = '', @BOMVersion INT = 0
		
		IF @CONDITION = 'Get_Line_Type'
		BEGIN
			SELECT Top 1 @ReturnValue = RTRIM(ISNULL(LineTypeCode,'')) FROM LineMst WITH (NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			SET @ReturnInt = 1
		END

		ELSE IF @CONDITION = 'Get_Part_List_All'
		BEGIN
			Create Table #Temp1
			(
				ProfitCenterCode Varchar(10) collate database_default,
				PartNo Varchar(50)  collate database_default PRIMARY KEY,
				MATERIAL_TP Varchar(20)  collate database_default
			)

			INSERT INTO #Temp1 (ProfitCenterCode,PartNo,MATERIAL_TP)
			SELECT Distinct RCPW.ProfitCenterCode, RCPW.PartNo, ISNULL(PM.MATERIAL_TP,'') MATERIAL_TP FROM RoutingConfigPartWise RCPW WITH (NOLOCK)
				INNER JOIN PRODUCT_MASTER PM WITH (NOLOCK)
					ON RCPW.ProfitCenterCode = PM.warehouse_cd AND RCPW.PartNo = PM.SEWS_PART_NO
						WHERE RCPW.ProfitCenterCode = @ProfitCenterCode

			-- TMC Part List
			SELECT @Material_TP = 'TMC'
			SELECT PartNo FROM #Temp1 WHERE MATERIAL_TP = @Material_TP

			-- Servo Part List
			SELECT @Material_TP = 'SERVO'
			SELECT PartNo FROM #Temp1 WHERE MATERIAL_TP = @Material_TP

			Create Table #Temp2
			(	
				PartNo Varchar(50) collate database_default PRIMARY KEY ,
				MATERIAL_TP Varchar(20) collate database_default,
				GroupCode Varchar(100) collate database_default
			)

			INSERT INTO #Temp2 (PartNo,MATERIAL_TP,GroupCode)
			SELECT Distinct T.PartNo, ISNULL(T.MATERIAL_TP,'') MATERIAL_TP, APCGM.GroupCode FROM #Temp1 T
				INNER JOIN Assy_PRN_CustomerGroupMaster APCGM WITH (NOLOCK)
					ON T.PartNo = APCGM.PartNo
						WHERE T.ProfitCenterCode = @ProfitCenterCode

		

			-- Mahindra Coupling Part List
			SELECT @Material_TP = 'STMC'
			SELECT @GroupCode = 'GC_MAHINDRA'

			SELECT PartNo FROM #Temp2 WHERE MATERIAL_TP = @Material_TP AND GroupCode = @GroupCode
				
			-- Non-Mahindra Coupling Part List
			SELECT @GroupCode = 'GC_NON_MAHINDRA'
			SELECT PartNo FROM #Temp2 WHERE MATERIAL_TP = @Material_TP AND GroupCode = @GroupCode

			-- Nissan Coupling Part List For STMC Line 6 and 7
			SELECT @GroupCode = 'GC_NISSAN_LINE_6_7'
			SELECT PartNo FROM #Temp2 WHERE MATERIAL_TP = @Material_TP AND GroupCode = @GroupCode

			-- Duster Coupling Part List For STMC Line 6 and 7
			SELECT @GroupCode = 'GC_DUSTER_LINE_6_7'
			SELECT PartNo FROM #Temp2 WHERE MATERIAL_TP = @Material_TP AND GroupCode = @GroupCode

			-- CALIPER Part List
			SELECT @Material_TP = 'CALIPER'			
			SELECT PartNo FROM #Temp1 WHERE MATERIAL_TP = @Material_TP

			Drop Table #Temp1
			Drop Table #Temp2

			SET @ReturnInt = 1
		END

		ELSE IF @CONDITION = 'Save_Part_Main'
		BEGIN
			--Get All Part List
			SELECT * INTO #PRODUCT_MASTER FROM PRODUCT_MASTER (NOLOCK) WHERE warehouse_cd = @ProfitCenterCode

			IF NOT EXISTS ( SELECT 1 FROM #PRODUCT_MASTER PM WHERE PM.SEWS_PART_NO = @NewPartNo)
			BEGIN
				SELECT @ReturnValue = 'New_Part_not_Exists_in_Product_Master._Please_contact_Target.', @ReturnInt = 1
				RETURN
			END
			
			ELSE IF NOT EXISTS ( SELECT 1 FROM #PRODUCT_MASTER PM WHERE PM.SEWS_PART_NO = @NewPartNo AND ISNULL(PM.STS_CD,100) = 0)
			BEGIN
				SELECT @ReturnValue = 'New_Part_exists_But_not_Active_in_Product_Master._Please_contact_Target.', @ReturnInt = 1
				RETURN
			END

			--Get All Part Routing
			SELECT * INTO #RoutingConfigPartWise FROM RoutingConfigPartWise (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode

			IF @PartRoutingExists = 0
			BEGIN
				IF ISNULL(@CustomerPartNo,'') = ''
				BEGIN
					IF EXISTS(SELECT Top 1 1 FROM #RoutingConfigPartWise WHERE PartNo = @NewPartNo)
					BEGIN
						SELECT @ReturnValue = 'Part_Routing_already_exists_For_New_Part.', @ReturnInt = 1
						RETURN
					END
				END
			END
			
			--Get All Coupling Label Information
			IF @SelectionType != 'TMC'
			BEGIN
				SELECT * INTO #Assy_Coupling_LabelInfo_Mst FROM Assy_Coupling_LabelInfo_Mst WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
			END

			IF @SelectionType IN ('MAHINDRA','NONMAHINDRA','NISSAN','DUSTER')
			BEGIN
				SELECT * INTO #BOM_MASTER FROM BOM_MASTER BM WITH (NOLOCK) WHERE BM.WH_CODE = @ProfitCenterCode
				SELECT * INTO #Assy_PRN_CustomerGroupMaster FROM Assy_PRN_CustomerGroupMaster WITH (NOLOCK)
			END
			-- TMC Part
			IF @SelectionType = 'TMC'
			BEGIN
				IF @NewPokaYokeGroup = 1
				BEGIN
					SELECT @GroupCode = RTRIM(ISNULL(PARAMETER_VALUE,'')) FROM PARAMETER_MST WITH (NOLOCK)
						WHERE wh_code = @ProfitCenterCode AND PARAMETER_C = 'AssLine' AND PARAMETER_C1 = 'PartFixtureGroupType'
							AND PARAMETER_C2 = @SelectionType 
					
					SELECT @GroupCodeLen = LEN(@GroupCode)

					SELECT @MaxGroupValue = MAX(RIGHT(Part_FixtureGroupType,5)) FROM #RoutingConfigPartWise
						WHERE LEFT(Part_FixtureGroupType,@GroupCodeLen) = @GroupCode AND ISNULL(Part_FixtureGroupType,'') != ''
					
					SELECT @MaxGroupValue = @MaxGroupValue + 1

					SELECT @Part_FixtureGroupType = RIGHT('00000' + CONVERT(VARCHAR,@MaxGroupValue),5)
					IF ISNULL(@Part_FixtureGroupType,'') = ''
						SET @Part_FixtureGroupType = '00001'
					
					SELECT @Part_FixtureGroupType =  @GroupCode + @Part_FixtureGroupType
				END
				
				 SELECT Top 1 @Material_TP = ISNULL(MATERIAL_TP,'') FROM #PRODUCT_MASTER PM WHERE LTRIM(RTRIM(PM.SEWS_PART_NO)) = @NewPartNo
				
				IF @Material_TP != ''
				BEGIN		
					IF (@Material_TP != @SelectionType)
					BEGIN
						SELECT @ReturnValue = 'Material_TP_is_exists_other_than_TMC_For_New_Part_in_Product_Master._Please_contact_MIND.', @ReturnInt = 1
						RETURN
					END
				END
				ELSE
					UPDATE PRODUCT_MASTER SET MATERIAL_TP = @SelectionType WHERE warehouse_cd = @ProfitCenterCode AND SEWS_PART_NO = @NewPartNo AND ISNULL(STS_CD,100) = 0

				INSERT INTO [dbo].[RoutingConfigPartWise]
						   ([ProfitCenterCode] , [OperationCode] , [MachineCode] , [PartNo] , [OperationRequired] , [Traceability] , [Recipe] , [LabelPrinting] , [Torque] , [Engraving]
							, [POKA_YOKE_ALLOWED] , [OperationSeqNo] , [ent_stamp] , [last_upd_stamp] , [ent_by] , [last_upd_by] , [Part_FixtureGroupType])

				SELECT [ProfitCenterCode] , [OperationCode] , [MachineCode] , @NewPartNo [PartNo], [OperationRequired] , [Traceability] , [Recipe] , [LabelPrinting] , [Torque] , [Engraving]
							, [POKA_YOKE_ALLOWED] , [OperationSeqNo] , GETDATE() [ent_stamp] , GETDATE() [last_upd_stamp] , @UserID [ent_by] , @UserID [last_upd_by] , Case @NewPokaYokeGroup WHEN 0 THEN NULL WHEN 1 THEN @Part_FixtureGroupType END
							FROM #RoutingConfigPartWise WHERE PartNo = @ReferencePartNo
				
				SELECT @ReturnValue = 'SUCCESS', @ReturnInt = 1
				
				RETURN
			END
			-- Servo Part
			ELSE IF @SelectionType = 'SERVO'
			BEGIN
				IF NOT EXISTS(SELECT 1 FROM #Assy_Coupling_LabelInfo_Mst WHERE PartNo = @ReferencePartNo)
				BEGIN
					SELECT @ReturnValue = 'Booster_Ratio_is_not_exists_for_selected_Ref_Part._Please_Select_Other_Part.', @ReturnInt = 1
					
					RETURN
				END

				IF EXISTS(SELECT 1 FROM #Assy_Coupling_LabelInfo_Mst WHERE PartNo = @NewPartNo)
				BEGIN
					SELECT @ReturnValue = 'Booster_Ratio_already_exists_For_New_Part.', @ReturnInt = 1
					
					RETURN
				END
				IF @NewPokaYokeGroup = 1
				BEGIN
					SELECT @GroupCode = RTRIM(ISNULL(PARAMETER_VALUE,'')) FROM PARAMETER_MST WITH (NOLOCK)
						WHERE wh_code = @ProfitCenterCode AND PARAMETER_C = 'AssLine' AND PARAMETER_C1 = 'PartFixtureGroupType'
							AND PARAMETER_C2 = @SelectionType 
					
					SELECT @GroupCodeLen = LEN(@GroupCode)

					SELECT @MaxGroupValue = MAX(RIGHT(Part_FixtureGroupType,5)) FROM #RoutingConfigPartWise
						WHERE LEFT(Part_FixtureGroupType,@GroupCodeLen) = @GroupCode AND ISNULL(Part_FixtureGroupType,'') != ''
					
					SELECT @MaxGroupValue = @MaxGroupValue + 1

					SELECT @Part_FixtureGroupType = RIGHT('00000' + CONVERT(VARCHAR,@MaxGroupValue),5)
					IF ISNULL(@Part_FixtureGroupType,'') = ''
						SET @Part_FixtureGroupType = '00001'
					
					SELECT @Part_FixtureGroupType =  @GroupCode + @Part_FixtureGroupType
				END

				SELECT Top 1 @Material_TP = ISNULL(MATERIAL_TP,'') FROM #PRODUCT_MASTER PM WHERE LTRIM(RTRIM(PM.SEWS_PART_NO)) = @NewPartNo
				
				IF @Material_TP != ''
				BEGIN		
					IF (@Material_TP != @SelectionType)
					BEGIN
						SELECT @ReturnValue = 'Material_TP_is_exists_other_than_Servo_For_New_Part_in_Product_Master._Please_contact_MIND.', @ReturnInt = 1
						RETURN
					END
				END
				ELSE
					UPDATE PRODUCT_MASTER SET MATERIAL_TP = @SelectionType WHERE warehouse_cd = @ProfitCenterCode AND SEWS_PART_NO = @NewPartNo AND ISNULL(STS_CD,100) = 0
				

				INSERT [dbo].[Assy_Coupling_LabelInfo_Mst] 
				([ProfitCenterCode], [PartNo], [CustomerPartNo], [LabelDataName], [LabelDataValue], [Engraving], [LabelPrinting], [isActive], [SeqNo], [ENT_BY], [ENT_STMP], [UPD_BY], [UPD_STMP]) 
				VALUES (@ProfitCenterCode, @NewPartNo, @NewPartNo, 'Boost_Ratio', @BoostRatio, 1, 1, 1, 1, @UserID, GETDATE(), @UserID, GETDATE())

				INSERT INTO [dbo].[RoutingConfigPartWise]
						   ([ProfitCenterCode] , [OperationCode] , [MachineCode] , [PartNo] , [OperationRequired] , [Traceability] , [Recipe] , [LabelPrinting] , [Torque] , [Engraving]
							, [POKA_YOKE_ALLOWED] , [OperationSeqNo] , [ent_stamp] , [last_upd_stamp] , [ent_by] , [last_upd_by] , [Part_FixtureGroupType])

				SELECT [ProfitCenterCode] , [OperationCode] , [MachineCode] , @NewPartNo [PartNo], [OperationRequired] , [Traceability] , [Recipe] , [LabelPrinting] ,
						[Torque] , [Engraving], [POKA_YOKE_ALLOWED] , [OperationSeqNo] , GETDATE() [ent_stamp] , GETDATE() [last_upd_stamp] , @UserID [ent_by] ,
							@UserID [last_upd_by] , Case @NewPokaYokeGroup WHEN 0 THEN NULL WHEN 1 THEN @Part_FixtureGroupType END
								FROM #RoutingConfigPartWise WHERE PartNo = @ReferencePartNo
				
				SELECT @ReturnValue = 'SUCCESS', @ReturnInt = 1
				
				RETURN
			END
			-- Mahindra Coupling Part & Non - Mahindra Coupling Part
			ELSE IF @SelectionType IN ('MAHINDRA','NONMAHINDRA')
			BEGIN
				IF @SelectionType = 'MAHINDRA'
					SELECT @PRNGroupCode = 'GC_MAHINDRA'
				ELSE IF @SelectionType = 'NONMAHINDRA'
					SELECT @PRNGroupCode = 'GC_NON_MAHINDRA'

				IF NOT EXISTS ( SELECT 1 FROM #BOM_MASTER BM
					WHERE LTRIM(RTRIM(BM.FG_PART_NO)) = @NewPartNo)
				BEGIN
					SELECT @ReturnValue = 'New_Part_not_Exists_in_BOM_Master._Please_contact_Target.', @ReturnInt = 1
					RETURN
				END
			
				ELSE IF NOT EXISTS ( SELECT 1 FROM #BOM_MASTER BM
					WHERE LTRIM(RTRIM(BM.FG_PART_NO)) = @NewPartNo AND ISNULL(BM.STS_CD,100) = 0)
				BEGIN
					SELECT @ReturnValue = 'New_Part_exists_But_not_Active_in_BOM_Master._Please_contact_Target.', @ReturnInt = 1
					RETURN
				END
				
				ELSE IF NOT EXISTS ( SELECT 1 FROM #BOM_MASTER BM
					WHERE LTRIM(RTRIM(BM.FG_PART_NO)) = @NewPartNo AND RM_PART_NO = @TMCChildPart)
				BEGIN
					SELECT @ReturnValue = 'TMC_Child_Part_not_Exists_in_BOM_Master._Please_contact_Target.', @ReturnInt = 1
					RETURN
				END
				
				ELSE IF NOT EXISTS ( SELECT 1 FROM #BOM_MASTER BM
					WHERE LTRIM(RTRIM(BM.FG_PART_NO)) = @NewPartNo AND RM_PART_NO = @TMCChildPart AND ISNULL(BM.STS_CD,100) = 0)
				BEGIN
					SELECT @ReturnValue = 'TMC_Child_Part_exists_But_not_Active_in_BOM_Master._Please_contact_Target.', @ReturnInt = 1
					RETURN
				END
				
				ELSE IF NOT EXISTS ( SELECT 1 FROM #BOM_MASTER BM
					WHERE LTRIM(RTRIM(BM.FG_PART_NO)) = @NewPartNo AND RM_PART_NO = @ServoChildPart)
				BEGIN
					SELECT @ReturnValue = 'Servo_Child_Part_not_Exists_in_BOM_Master._Please_contact_Target.', @ReturnInt = 1
					RETURN
				END
				
				ELSE IF NOT EXISTS ( SELECT 1 FROM #BOM_MASTER BM
					WHERE LTRIM(RTRIM(BM.FG_PART_NO)) = @NewPartNo AND RM_PART_NO = @ServoChildPart AND ISNULL(BM.STS_CD,100) = 0)
				BEGIN
					SELECT @ReturnValue = 'Servo_Child_Part_exists_But_not_Active_in_BOM_Master._Please_contact_Target.', @ReturnInt = 1
					RETURN
				END

				-- Servo Child Part Material TP Check
				SELECT Top 1 @Material_TP = ISNULL(MATERIAL_TP,'') FROM #PRODUCT_MASTER PM WHERE LTRIM(RTRIM(PM.SEWS_PART_NO)) = @ServoChildPart

				IF @Material_TP != ''
				BEGIN		
					IF (UPPER(@Material_TP) != 'SERVO')
					BEGIN
						SELECT @ReturnValue = 'Material_TP_is_exists_other_than_Servo_For_Child_Servo_Part_in_Product_Master._Please_contact_MIND.', @ReturnInt = 1
						RETURN
					END
				END
				ELSE
					UPDATE PRODUCT_MASTER SET MATERIAL_TP = 'SERVO' WHERE warehouse_cd = @ProfitCenterCode AND SEWS_PART_NO = @ServoChildPart AND ISNULL(STS_CD,100) = 0
				
				-- TMC Child Part Material TP Check
				SELECT @Material_TP = ''
				SELECT Top 1 @Material_TP = ISNULL(MATERIAL_TP,'') FROM #PRODUCT_MASTER PM WHERE LTRIM(RTRIM(PM.SEWS_PART_NO)) = @TMCChildPart

				IF @Material_TP != ''
				BEGIN		
					IF (UPPER(@Material_TP) != 'TMC')
					BEGIN
						SELECT @ReturnValue = 'Material_TP_is_exists_other_than_TMC_For_Child_TMC_Part_in_Product_Master._Please_contact_MIND.', @ReturnInt = 1
						RETURN
					END
				END
				ELSE
					UPDATE PRODUCT_MASTER SET MATERIAL_TP = 'TMC' WHERE warehouse_cd = @ProfitCenterCode AND SEWS_PART_NO = @TMCChildPart AND ISNULL(STS_CD,100) = 0
				
				SELECT @ServoPartNo = ServoPartNo, @TMCPartNo = TMCPartNo FROM Assy_FN_Get_ServoTMCParts_From_STMCPart_Add_Part_Master(@ProfitCenterCode, @NewPartNo, 1)
				
				IF ISNULL(@ServoPartNo,'') = '' OR ISNULL(@TMCPartNo,'') = ''
				BEGIN
					SELECT @ReturnValue = 'Either_Servo_or_TMC_part_has_not_been_defined_for_this_New_part_no._in_BOM_Master/Product_Master._Please_Contact_Target.', @ReturnInt = 1
						
					RETURN
				END

				IF NOT EXISTS(SELECT 1 FROM #Assy_Coupling_LabelInfo_Mst WHERE PartNo = @ReferencePartNo AND LabelDataName = 'Boost_Ratio')
				BEGIN
					SELECT @ReturnValue = 'Booster_Ratio_is_not_exists_for_selected_Ref_Part._Please_Select_Other_Part.', @ReturnInt = 1
					
					RETURN
				END

				IF NOT EXISTS(SELECT 1 FROM #Assy_Coupling_LabelInfo_Mst WHERE PartNo = @ReferencePartNo AND LabelDataName = 'Model_Name')
				BEGIN
					SELECT @ReturnValue = 'Model_Name_is_not_exists_for_selected_Ref_Part._Please_Select_Other_Part.', @ReturnInt = 1
					
					RETURN
				END

				IF @PRNGroupCode != 'GC_NON_MAHINDRA'
				BEGIN
					IF NOT EXISTS(SELECT 1 FROM #Assy_Coupling_LabelInfo_Mst WHERE PartNo = @ReferencePartNo AND LabelDataName = 'Part_Identification_Code')
					BEGIN
						SELECT @ReturnValue = 'Part_Identification_Code_is_not_exists_for_selected_Ref_Part._Please_Select_Other_Part.', @ReturnInt = 1
					
						RETURN
					END
				END

				IF @PRNGroupCode != 'GC_MAHINDRA'
				BEGIN
					IF NOT EXISTS(SELECT 1 FROM #Assy_Coupling_LabelInfo_Mst WHERE PartNo = @ReferencePartNo AND LabelDataName = 'Part_Type')
					BEGIN
						SELECT @ReturnValue = 'Part_Type_is_not_exists_for_selected_Ref_Part._Please_Select_Other_Part.', @ReturnInt = 1
					
						RETURN
					END
				END

				IF NOT EXISTS(SELECT 1 FROM #Assy_Coupling_LabelInfo_Mst WHERE PartNo = @ReferencePartNo AND LabelDataName = 'Plant_Code')
				BEGIN
					SELECT @ReturnValue = 'Plant_Code_is_not_exists_for_selected_Ref_Part._Please_Select_Other_Part.', @ReturnInt = 1
					
					RETURN
				END

				IF NOT EXISTS(SELECT 1 FROM #Assy_PRN_CustomerGroupMaster WHERE PartNo = @ReferencePartNo)
				BEGIN
					SELECT @ReturnValue = 'PRN_CustomerGroupMaster_is_Not_exists_For_Selected_Ref_Part._Please_Other_Part.', @ReturnInt = 1
					
					RETURN
				END

				IF EXISTS(SELECT 1 FROM #Assy_Coupling_LabelInfo_Mst WHERE PartNo = @NewPartNo AND CustomerPartNo = @CustomerPartNo AND LabelDataName = 'Boost_Ratio')
				BEGIN
					SELECT @ReturnValue = 'Booster_Ratio_already_exists_For_New_Part.', @ReturnInt = 1
					
					RETURN
				END

				IF EXISTS(SELECT 1 FROM #Assy_PRN_CustomerGroupMaster WHERE PartNo = @NewPartNo AND CustomerPartNo = @CustomerPartNo)
				BEGIN
					SELECT @ReturnValue = 'PRN_CustomerGroupMaster_is_already_exists_For_New_Part.', @ReturnInt = 1
					
					RETURN
				END

				SELECT @SelectionType = 'STMC'

				IF @NewPokaYokeGroup = 1
				BEGIN
					SELECT @GroupCode = RTRIM(ISNULL(PARAMETER_VALUE,'')) FROM PARAMETER_MST WITH (NOLOCK)
						WHERE wh_code = @ProfitCenterCode AND PARAMETER_C = 'AssLine' AND PARAMETER_C1 = 'PartFixtureGroupType' AND PARAMETER_C2 = @SelectionType 
					
					SELECT @GroupCodeLen = LEN(@GroupCode)

					SELECT @MaxGroupValue = MAX(RIGHT(Part_FixtureGroupType,5)) FROM #RoutingConfigPartWise WITH (NOLOCK)
						WHERE LEFT(Part_FixtureGroupType,@GroupCodeLen) = @GroupCode AND ISNULL(Part_FixtureGroupType,'') != ''

					SELECT @MaxGroupValue = @MaxGroupValue + 1

					SELECT @Part_FixtureGroupType = RIGHT('00000' + CONVERT(VARCHAR,@MaxGroupValue),5)
					IF ISNULL(@Part_FixtureGroupType,'') = ''
						SELECT @Part_FixtureGroupType = '00001'
					
					SET @Part_FixtureGroupType =  @GroupCode + @Part_FixtureGroupType
				END

				UPDATE PRODUCT_MASTER SET MATERIAL_TP = @SelectionType WHERE warehouse_cd = @ProfitCenterCode AND SEWS_PART_NO = @NewPartNo AND ISNULL(STS_CD,100) = 0

				INSERT [dbo].[Assy_Coupling_LabelInfo_Mst] 
				([ProfitCenterCode], [PartNo], [CustomerPartNo], [LabelDataName], [LabelDataValue], [Engraving], [LabelPrinting], [isActive], [SeqNo], [ENT_BY], [ENT_STMP], [UPD_BY], [UPD_STMP]) 

				SELECT @ProfitCenterCode, @NewPartNo, @CustomerPartNo, 'Boost_Ratio', @BoostRatio, 1, 1, 1, 1, @UserID, GETDATE(), @UserID, GETDATE()
					UNION ALL
				SELECT @ProfitCenterCode, @NewPartNo, @CustomerPartNo, 'Model_Name', @ModelName, 1, 1, 1, 1, @UserID, GETDATE(), @UserID, GETDATE()
					UNION ALL
				SELECT @ProfitCenterCode, @NewPartNo, @CustomerPartNo, 'Part_Identification_Code', @PartIdentificationCode, 1, 1, 1, 1, @UserID, GETDATE(), @UserID, GETDATE()
					UNION ALL
				SELECT @ProfitCenterCode, @NewPartNo, @CustomerPartNo, 'Part_Type', @PartType, 1, 1, 1, 1, @UserID, GETDATE(), @UserID, GETDATE()
					UNION ALL
				SELECT @ProfitCenterCode, @NewPartNo, @CustomerPartNo, 'Plant_Code', @PlantCode, 1, 1, 1, 1, @UserID, GETDATE(), @UserID, GETDATE()

				IF NOT EXISTS(SELECT 1 FROM Assy_PRN_CustomerGroupMaster (NOLOCK) WHERE PartNo = @NewPartNo AND CustomerPartNo = @CustomerPartNo)
				BEGIN
					INSERT INTO Assy_PRN_CustomerGroupMaster
					(PartNo,CustomerPartNo,GroupCode,CreatedBy,CreatedDate,ModifiedBy,ModifiedDate)
						VALUES (@NewPartNo, @CustomerPartNo, @PRNGroupCode, @UserID, GETDATE(), @UserID, GETDATE())
				END

				IF NOT EXISTS(SELECT 1 FROM RoutingConfigPartWise WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND PartNo = @NewPartNo)
				BEGIN
					INSERT INTO [dbo].[RoutingConfigPartWise]
							   ([ProfitCenterCode] , [OperationCode] , [MachineCode] , [PartNo] , [OperationRequired] , [Traceability] , [Recipe] , [LabelPrinting] , [Torque] , [Engraving]
								, [POKA_YOKE_ALLOWED] , [OperationSeqNo] , [ent_stamp] , [last_upd_stamp] , [ent_by] , [last_upd_by] , [Part_FixtureGroupType])

					SELECT [ProfitCenterCode] , [OperationCode] , [MachineCode] , @NewPartNo [PartNo], [OperationRequired] , [Traceability] , [Recipe] , [LabelPrinting] ,
							[Torque] , [Engraving], [POKA_YOKE_ALLOWED] , [OperationSeqNo] , GETDATE() [ent_stamp] , GETDATE() [last_upd_stamp] , @UserID [ent_by] ,
								@UserID [last_upd_by] , Case @NewPokaYokeGroup WHEN 0 THEN NULL WHEN 1 THEN @Part_FixtureGroupType END
									FROM #RoutingConfigPartWise WHERE PartNo = @ReferencePartNo
				END
				
				SELECT @ReturnValue = 'SUCCESS', @ReturnInt = 1
				
				RETURN
			END
			-- Nissan & Duster Coupling Part
			ELSE IF @SelectionType IN ('NISSAN','DUSTER')
			BEGIN
				IF @SelectionType = 'NISSAN'
					SELECT @PRNGroupCode = 'GC_NISSAN_LINE_6_7'
				ELSE IF @SelectionType = 'DUSTER'
					SELECT @PRNGroupCode = 'GC_DUSTER_LINE_6_7'

				IF NOT EXISTS ( SELECT 1 FROM #BOM_MASTER BM
					WHERE LTRIM(RTRIM(BM.FG_PART_NO)) = @NewPartNo)
				BEGIN
					SELECT @ReturnValue = 'New_Part_not_Exists_in_BOM_Master._Please_contact_Target.', @ReturnInt = 1
					RETURN
				END
			
				ELSE IF NOT EXISTS ( SELECT 1 FROM #BOM_MASTER BM
					WHERE LTRIM(RTRIM(BM.FG_PART_NO)) = @NewPartNo AND ISNULL(BM.STS_CD,100) = 0)
				BEGIN
					SELECT @ReturnValue = 'New_Part_exists_But_not_Active_in_BOM_Master._Please_contact_Target.', @ReturnInt = 1
					RETURN
				END
				
				ELSE IF NOT EXISTS ( SELECT 1 FROM #BOM_MASTER BM
					WHERE LTRIM(RTRIM(BM.FG_PART_NO)) = @NewPartNo AND RM_PART_NO = @TMCChildPart)
				BEGIN
					SELECT @ReturnValue = 'TMC_Child_Part_not_Exists_in_BOM_Master._Please_contact_Target.', @ReturnInt = 1
					RETURN
				END
				
				ELSE IF NOT EXISTS ( SELECT 1 FROM #BOM_MASTER BM
					WHERE LTRIM(RTRIM(BM.FG_PART_NO)) = @NewPartNo AND RM_PART_NO = @TMCChildPart AND ISNULL(BM.STS_CD,100) = 0)
				BEGIN
					SELECT @ReturnValue = 'TMC_Child_Part_exists_But_not_Active_in_BOM_Master._Please_contact_Target.', @ReturnInt = 1
					RETURN
				END
				
				ELSE IF NOT EXISTS ( SELECT 1 FROM #BOM_MASTER BM
					WHERE LTRIM(RTRIM(BM.FG_PART_NO)) = @NewPartNo AND RM_PART_NO = @ServoChildPart)
				BEGIN
					SELECT @ReturnValue = 'Servo_Child_Part_not_Exists_in_BOM_Master._Please_contact_Target.', @ReturnInt = 1
					RETURN
				END
				
				ELSE IF NOT EXISTS ( SELECT 1 FROM #BOM_MASTER BM
					WHERE LTRIM(RTRIM(BM.FG_PART_NO)) = @NewPartNo AND RM_PART_NO = @ServoChildPart AND ISNULL(BM.STS_CD,100) = 0)
				BEGIN
					SELECT @ReturnValue = 'Servo_Child_Part_exists_But_not_Active_in_BOM_Master._Please_contact_Target.', @ReturnInt = 1
					RETURN
				END

				-- Servo Child Part Material TP Check
				SELECT Top 1 @Material_TP = ISNULL(MATERIAL_TP,'') FROM #PRODUCT_MASTER PM WHERE LTRIM(RTRIM(PM.SEWS_PART_NO)) = @ServoChildPart

				IF @Material_TP != ''
				BEGIN		
					IF (@Material_TP != 'SERVO')
					BEGIN
						SELECT @ReturnValue = 'Material_TP_is_exists_other_than_Servo_For_Child_Servo_Part_in_Product_Master._Please_contact_MIND.', @ReturnInt = 1
						RETURN
					END
				END
				ELSE
					UPDATE PRODUCT_MASTER SET MATERIAL_TP = 'SERVO' WHERE warehouse_cd = @ProfitCenterCode AND SEWS_PART_NO = @ServoChildPart AND ISNULL(STS_CD,100) = 0
				
				-- TMC Child Part Material TP Check
				SELECT @Material_TP = ''
				SELECT Top 1 @Material_TP = ISNULL(MATERIAL_TP,'') FROM #PRODUCT_MASTER PM WHERE LTRIM(RTRIM(PM.SEWS_PART_NO)) = @TMCChildPart

				IF @Material_TP != ''
				BEGIN		
					IF (@Material_TP != 'TMC')
					BEGIN
						SELECT @ReturnValue = 'Material_TP_is_exists_other_than_TMC_For_Child_TMC_Part_in_Product_Master._Please_contact_MIND.', @ReturnInt = 1
						RETURN
					END
				END
				ELSE
					UPDATE PRODUCT_MASTER SET MATERIAL_TP = 'TMC' WHERE warehouse_cd = @ProfitCenterCode AND SEWS_PART_NO = @TMCChildPart AND ISNULL(STS_CD,100) = 0
				
				SELECT @ServoPartNo = ServoPartNo, @TMCPartNo = TMCPartNo FROM Assy_FN_Get_ServoTMCParts_From_STMCPart_Add_Part_Master(@ProfitCenterCode, @NewPartNo, 1)
				
				IF ISNULL(@ServoPartNo,'') = '' OR ISNULL(@TMCPartNo,'') = ''
				BEGIN
					SELECT @ReturnValue = 'Either_Servo_or_TMC_part_has_not_been_defined_for_this_New_part_no._in_BOM_Master/Product_Master._Please_Contact_Target.', @ReturnInt = 1
					RETURN
				END

				IF NOT EXISTS(SELECT 1 FROM #Assy_Coupling_LabelInfo_Mst WHERE PartNo = @ReferencePartNo AND LabelDataName = 'Indicator')
				BEGIN
					SELECT @ReturnValue = 'Indicator_is_not_exists_for_selected_Ref_Part._Please_Select_Other_Part.', @ReturnInt = 1
					RETURN
				END

				IF NOT EXISTS(SELECT 1 FROM #Assy_Coupling_LabelInfo_Mst WHERE PartNo = @ReferencePartNo AND LabelDataName = 'Assy_Type')
				BEGIN
					SELECT @ReturnValue = 'Assy_Type_is_not_exists_for_selected_Ref_Part._Please_Select_Other_Part.', @ReturnInt = 1					
					RETURN
				END
				
				IF NOT EXISTS(SELECT 1 FROM #Assy_PRN_CustomerGroupMaster WHERE PartNo = @ReferencePartNo)
				BEGIN
					SELECT @ReturnValue = 'PRN_CustomerGroupMaster_is_Not_exists_For_Selected_Ref_Part._Please_Other_Part.', @ReturnInt = 1					
					RETURN
				END

				IF EXISTS(SELECT 1 FROM #Assy_Coupling_LabelInfo_Mst WHERE PartNo = @NewPartNo AND CustomerPartNo = @CustomerPartNo AND LabelDataName = 'Indicator')
				BEGIN
					SELECT @ReturnValue = 'Indicator_already_exists_For_New_Part.', @ReturnInt = 1					
					RETURN
				END

				IF EXISTS(SELECT 1 FROM #Assy_PRN_CustomerGroupMaster WHERE PartNo = @NewPartNo AND CustomerPartNo = @CustomerPartNo)
				BEGIN
					SELECT @ReturnValue = 'PRN_CustomerGroupMaster_is_already_exists_For_New_Part.', @ReturnInt = 1					
					RETURN
				END

				SELECT @SelectionType = 'STMC'

				IF @NewPokaYokeGroup = 1
				BEGIN
					SELECT @GroupCode = RTRIM(ISNULL(PARAMETER_VALUE,'')) FROM PARAMETER_MST WITH (NOLOCK)
						WHERE wh_code = @ProfitCenterCode AND PARAMETER_C = 'AssLine' AND PARAMETER_C1 = 'PartFixtureGroupType' AND PARAMETER_C2 = @SelectionType
					
					SELECT @GroupCodeLen = LEN(@GroupCode)

					SELECT @MaxGroupValue = MAX(RIGHT(Part_FixtureGroupType,5)) FROM #RoutingConfigPartWise
						WHERE LEFT(Part_FixtureGroupType,@GroupCodeLen) = @GroupCode AND ISNULL(Part_FixtureGroupType,'') != ''

					SELECT @MaxGroupValue = @MaxGroupValue + 1

					SELECT @Part_FixtureGroupType = RIGHT('00000' + CONVERT(VARCHAR,@MaxGroupValue),5)
					IF ISNULL(@Part_FixtureGroupType,'') = ''
						SELECT @Part_FixtureGroupType = '00001'
					
					SET @Part_FixtureGroupType =  @GroupCode + @Part_FixtureGroupType
				END

				UPDATE PRODUCT_MASTER SET MATERIAL_TP = @SelectionType WHERE warehouse_cd = @ProfitCenterCode AND SEWS_PART_NO = @NewPartNo AND ISNULL(STS_CD,100) = 0

				INSERT [dbo].[Assy_Coupling_LabelInfo_Mst] 
				([ProfitCenterCode], [PartNo], [CustomerPartNo], [LabelDataName], [LabelDataValue], [Engraving], [LabelPrinting], [isActive], [SeqNo], [ENT_BY], [ENT_STMP], [UPD_BY], [UPD_STMP]) 

				SELECT @ProfitCenterCode, @NewPartNo, @CustomerPartNo, 'Assy_Type', @PartType, 1, 0, 1, 1, @UserID, GETDATE(), @UserID, GETDATE()
					UNION ALL
				SELECT @ProfitCenterCode, @NewPartNo, @CustomerPartNo, 'Cat_ID', @PlantCode, 1, 0, 1, 1, @UserID, GETDATE(), @UserID, GETDATE()
					UNION ALL
				SELECT @ProfitCenterCode, @NewPartNo, @CustomerPartNo, 'Customer_Part_ID', @PartIdentificationCode, 1, 0, 1, 1, @UserID, GETDATE(), @UserID, GETDATE()
					UNION ALL
				SELECT @ProfitCenterCode, @NewPartNo, @CustomerPartNo, 'Indicator', @BoostRatio, 1, 0, 1, 1, @UserID, GETDATE(), @UserID, GETDATE()
					UNION ALL
				SELECT @ProfitCenterCode, @NewPartNo, @CustomerPartNo, 'Is_Clutch_Nipple_Cut_Required', @NippleCutRequired, 1, 0, 1, 1, @UserID, GETDATE(), @UserID, GETDATE()
					UNION ALL
				SELECT @ProfitCenterCode, @NewPartNo, @CustomerPartNo, 'IsDateCode_Engraving', @DateCodeEngravedRequired, 1, 0, 1, 1, @UserID, GETDATE(), @UserID, GETDATE()
					UNION ALL
				SELECT @ProfitCenterCode, @NewPartNo, @CustomerPartNo, 'Issue_level', @ModelName, 1, 0, 1, 1, @UserID, GETDATE(), @UserID, GETDATE()
					UNION ALL
				SELECT @ProfitCenterCode, @NewPartNo, @CustomerPartNo, 'Part_ID', @PartID, 1, 0, 1, 1, @UserID, GETDATE(), @UserID, GETDATE()
					UNION ALL
				SELECT @ProfitCenterCode, @NewPartNo, @CustomerPartNo, 'TMC_Cutting_Type', @TMCCuttingType, 1, 0, 1, 1, @UserID, GETDATE(), @UserID, GETDATE()
					UNION ALL
				SELECT @ProfitCenterCode, @NewPartNo, @CustomerPartNo, 'CapColorCode', CONVERT(VARCHAR,@CapColorCode), 1, 0, 1, 1, @UserID, GETDATE(), @UserID, GETDATE()

				IF NOT EXISTS(SELECT 1 FROM Assy_PRN_CustomerGroupMaster WITH (NOLOCK) WHERE PartNo = @NewPartNo AND CustomerPartNo = @CustomerPartNo)
				BEGIN
					INSERT INTO Assy_PRN_CustomerGroupMaster
					(PartNo,CustomerPartNo,GroupCode,CreatedBy,CreatedDate,ModifiedBy,ModifiedDate)
						VALUES (@NewPartNo, @CustomerPartNo, @PRNGroupCode, @UserID, GETDATE(), @UserID, GETDATE())
				END

				IF NOT EXISTS(SELECT 1 FROM RoutingConfigPartWise WITH (NOLOCK) WHERE PartNo = @NewPartNo AND ProfitCenterCode = @ProfitCenterCode)
				BEGIN
					INSERT INTO [dbo].[RoutingConfigPartWise]
							   ([ProfitCenterCode] , [OperationCode] , [MachineCode] , [PartNo] , [OperationRequired] , [Traceability] , [Recipe] , [LabelPrinting] , [Torque] , [Engraving]
								, [POKA_YOKE_ALLOWED] , [OperationSeqNo] , [ent_stamp] , [last_upd_stamp] , [ent_by] , [last_upd_by] , [Part_FixtureGroupType])

					SELECT [ProfitCenterCode] , [OperationCode] , [MachineCode] , @NewPartNo [PartNo], [OperationRequired] , [Traceability] , [Recipe] , [LabelPrinting] ,
							[Torque] , [Engraving], [POKA_YOKE_ALLOWED] , [OperationSeqNo] , GETDATE() [ent_stamp] , GETDATE() [last_upd_stamp] , @UserID [ent_by] ,
								@UserID [last_upd_by] , Case @NewPokaYokeGroup WHEN 0 THEN NULL WHEN 1 THEN @Part_FixtureGroupType END
									FROM #RoutingConfigPartWise WHERE PartNo = @ReferencePartNo
				END
				
				SELECT @ReturnValue = 'SUCCESS', @ReturnInt = 1
				
				RETURN
			END
			-- CALIPER Part
			ELSE IF @SelectionType = 'CALIPER'
			BEGIN
				IF @NewPokaYokeGroup = 1
				BEGIN
					SELECT @GroupCode = RTRIM(ISNULL(PARAMETER_VALUE,'')) FROM PARAMETER_MST WITH (NOLOCK)
						WHERE wh_code = @ProfitCenterCode AND PARAMETER_C = 'AssLine' AND PARAMETER_C1 = 'PartFixtureGroupType'
							AND PARAMETER_C2 = @SelectionType 
					
					SET @GroupCodeLen = LEN(@GroupCode)

					SELECT @MaxGroupValue = MAX(RIGHT(Part_FixtureGroupType,5)) FROM RoutingConfigPartWise WITH (NOLOCK)
						WHERE ProfitCenterCode = @ProfitCenterCode AND LEFT(Part_FixtureGroupType,@GroupCodeLen) = @GroupCode
							AND ISNULL(Part_FixtureGroupType,'') != ''
					
					SET @MaxGroupValue = @MaxGroupValue + 1

					SET @Part_FixtureGroupType = RIGHT('00000' + CONVERT(VARCHAR,@MaxGroupValue),5)
					IF ISNULL(@Part_FixtureGroupType,'') = ''
						SET @Part_FixtureGroupType = '00001'
					
					SET @Part_FixtureGroupType =  @GroupCode + @Part_FixtureGroupType
				END
				
				 SELECT Top 1 @Material_TP = ISNULL(MATERIAL_TP,'') FROM PRODUCT_MASTER PM WITH (NOLOCK) WHERE PM.warehouse_cd = @ProfitCenterCode
							AND LTRIM(RTRIM(PM.SEWS_PART_NO)) = @NewPartNo
				IF @Material_TP != ''
				BEGIN		
					IF (@Material_TP != @SelectionType)
					BEGIN
						SET @ReturnValue = 'Material_TP_is_exists_other_than_Caliper_For_New_Part_in_Product_Master._Please_contact_MIND.'
						SET @ReturnInt = 1
						RETURN
					END
				END
				ELSE
					UPDATE PRODUCT_MASTER SET MATERIAL_TP = @SelectionType WHERE warehouse_cd = @ProfitCenterCode AND SEWS_PART_NO = @NewPartNo AND ISNULL(STS_CD,100) = 0
				
				INSERT INTO [dbo].[RoutingConfigPartWise]
						   ([ProfitCenterCode] , [OperationCode] , [MachineCode] , [PartNo] , [OperationRequired] , [Traceability] , [Recipe] , [LabelPrinting] , [Torque] , [Engraving]
							, [POKA_YOKE_ALLOWED] , [OperationSeqNo] , [ent_stamp] , [last_upd_stamp] , [ent_by] , [last_upd_by] , [Part_FixtureGroupType])

				SELECT [ProfitCenterCode] , [OperationCode] , [MachineCode] , @NewPartNo [PartNo], [OperationRequired] , [Traceability] , [Recipe] , [LabelPrinting] , [Torque] , [Engraving]
							, [POKA_YOKE_ALLOWED] , [OperationSeqNo] , GETDATE() [ent_stamp] , GETDATE() [last_upd_stamp] , @UserID [ent_by] , @UserID [last_upd_by] , Case @NewPokaYokeGroup WHEN 0 THEN [Part_FixtureGroupType] WHEN 1 THEN @Part_FixtureGroupType END
							FROM [RoutingConfigPartWise] WITH (NOLOCK) 
							WHERE PartNo = @ReferencePartNo AND ProfitCenterCode = @ProfitCenterCode
				
				SET @ReturnValue = 'SUCCESS'
				SET @ReturnInt = 1
				
				RETURN
			END
		END
	END TRY
	BEGIN CATCH
		SET @RETURNVALUE =	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' +
							CAST(ERROR_SEVERITY() AS VARCHAR(5)) + '|' +
							CAST(ERROR_STATE() AS VARCHAR(5)) + '|' +
							CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' +
							CAST(ERROR_LINE() AS VARCHAR(5)) + '|' +
							CAST(ERROR_MESSAGE() AS VARCHAR(1500))
		SET @RETURNINT = 2
		RAISERROR (@RETURNVALUE, 16, 1)
	END CATCH
END

GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_Barcode_Printed_Counter]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [dbo].[Assy_Proc_Barcode_Printed_Counter]
(

@CONDITION VARCHAR(50),
@ProfitCenterCode varchar(20)=null,
@LineCode varchar(20)=null,
@ManualPrintedQty int=0,
@ReturnValue VARCHAR (2000)=NULL OUT,
@ReturnInt INT=NULL OUT,
@P_PartNumber varchar(30)='', -- added by SK 210621
@P_IsEkanbanEnabled bit=0 -- added by SK 210621
)
as
BEGIN



-- Author:		<Ravishankar Mishra>
-- Create date: < 1 april 2015>
-- Description:	<Update printed barcode counter.>

-- Modified Date:		<Ravishankar Mishra>
-- Modified By: 12-02-2016
-- Description:	Delete data from Assy_Barcode_Printed_Counter table if this table's date code is not matching with assy_runningPart Datecode
-- MODIFIED ON:		< 17-July-2020 BY RS>
-- DESCRIPTION:		< Set Parameter count and Direct scanning count stopping on reaching>

-- To Rembember
-- Nothing = 0
-- Success = 1
-- Error = 2
-- AlreadyExists = 3
-- NotExists = 4
     
	 --EXEC Assy_Proc_Barcode_Printed_Counter @CONDITION='UPDATE',@LineCode ='M07',@ProfitCenterCode ='0021'
	 --DECLARE @ReturnValue VARCHAR(10)
	 --EXEC Assy_Proc_Barcode_Printed_Counter @CONDITION='SELECT',@LineCode ='M07',@ProfitCenterCode ='0021',@ManualPrintedQty=12,@ReturnValue=@ReturnValue OUT 
	 --SELECT @ReturnValue
	 --EXEC Assy_Proc_Barcode_Printed_Counter @CONDITION='DELETE',@LineCode ='M07',@ProfitCenterCode ='0021'
	 --EXEC Assy_Proc_Barcode_Printed_Counter @CONDITION='UPDATE_CURRENTPLANNEDQTY_FOR_SAMEPART',@LineCode ='M07',@ProfitCenterCode ='0021'	 
	 --SELECT * FROM Assy_Barcode_Printed_Counter
	 --SELECT * FROM Assy_RunningPart
	 --select *from Assy_RunningPart_Previous 

		SET NOCOUNT ON
		DECLARE @PrintedQty AS INT
		if @CONDITION='UPDATE'
		begin
					
					--Added by ravi on 12-02-16
					--Delete data from Assy_Barcode_Printed_Counter table if this table's date code is not matching with assy_runningPart Datecode
					IF EXISTS
					(
							SELECT TOP 1 1 FROM ASSY_BARCODE_PRINTED_COUNTER(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE 
					)
					BEGIN	
								
								IF(
									(SELECT TOP 1 DATECODE FROM ASSY_BARCODE_PRINTED_COUNTER(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE)
									<>(SELECT TOP 1 DATECODE FROM ASSY_RUNNINGPART(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE ORDER BY CREATEDDATE DESC)
								)
								BEGIN
										DELETE FROM ASSY_BARCODE_PRINTED_COUNTER WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE 
								END
					END
					----------------------------end---------------------------------------
					IF EXISTS
					(
							SELECT TOP 1 1 FROM Assy_Barcode_Printed_Counter(NOLOCK) WHERE ProfitCenterCode=@ProfitCenterCode AND LineCode =@LineCode 
					)
					BEGIN				    
									   UPDATE Assy_Barcode_Printed_Counter  SET PrintedQty=ISNULL(PrintedQty,0)+1,Timestamp =GETDATE() 
									   WHERE ProfitCenterCode=@ProfitCenterCode AND LineCode =@LineCode AND CurrentPlannedQty>ISNULL(PrintedQty,0)								

					END
					ELSE
						 BEGIN
									  INSERT INTO Assy_Barcode_Printed_Counter
									  ( ProfitCenterCode,
										LineCode ,
										Datecode ,
										ProductionOrderNo ,
										PartNo,
										CurrentPlannedQty,
										PrintedQty,
										Timestamp 
									 )
									 SELECT @ProfitCenterCode 
									 ,LINECODE
									  ,Datecode
									 ,ProductionOrderNo
									 ,Assy_PartNo
									 ,CurrentPlannedQty
									 ,1,
									 GETDATE()
									 FROM Assy_RunningPart(NOLOCK) WHERE LineCode =@LineCode   
						 END
								 SET @ReturnInt=1
				

		end
		ELSE if @CONDITION='DELETE'
		begin
				DELETE FROM Assy_Barcode_Printed_Counter WHERE ProfitCenterCode=@ProfitCenterCode AND LineCode =@LineCode 
				 SET @ReturnInt=1
		END		
		ELSE if @CONDITION = 'IS_PLANNED_QTY_REACHED'
		Begin
		  declare @PlannedQty int = 0;
		  set @PrintedQty = 0;
		  if exists
		  (
		     select top 1 1 from Assy_Barcode_Printed_Counter where LineCode = @LineCode and ProfitCenterCode = @ProfitCenterCode
		  )
		  begin
			
			if(ISNULL(@P_PartNumber,'') != '' AND @P_IsEkanbanEnabled = 1) --Added By Sachin 210621
			begin
					select @PlannedQty = CurrentPlannedQty, @PrintedQty = PrintedQty from Assy_Barcode_Printed_Counter (NOLOCK)
					where LineCode = @LineCode and ProfitCenterCode = @ProfitCenterCode and PartNo=ISNULL(@P_PartNumber,'')
			end
			else 
			begin
					select @PlannedQty = CurrentPlannedQty, @PrintedQty = PrintedQty from Assy_Barcode_Printed_Counter (NOLOCK)
					where LineCode = @LineCode and ProfitCenterCode = @ProfitCenterCode
			end

			if(@PlannedQty <= @PrintedQty)
			begin
			   set @ReturnValue = 'Yes'
			end
			
			else
			begin
			  set @ReturnValue = 'No'
			end
		  end
		  
		  else
		  begin
		    set @ReturnValue = 'Not Exists'
		  end
		  
		End
		ELSE if @CONDITION='SELECT'
		begin			
				if @ManualPrintedQty>0
				begin

								SELECT @ReturnValue=CONVERT(VARCHAR(20),ISNULL(PrintedQty,0)) FROM Assy_Barcode_Printed_Counter(NOLOCK) 
								WHERE ProfitCenterCode=@ProfitCenterCode AND LineCode =@LineCode 
								IF @ReturnValue IS NULL OR @ReturnValue=''
								begin
										
										if exists 
										(
												select 1 from Assy_RunningPart(nolock) where LineCode =@LineCode  and assy_mode IN ('Production','Rework')
												and CurrentPlannedQty>= @ManualPrintedQty
										)
										begin
													 SET @ReturnValue='OK'											
										end
									   ELSE
											BEGIN
													SET @ReturnValue='NOT_OK'
											END
										 select @ReturnValue as ReturnValue
										 SET @ReturnInt=1
									     return
								end

								set @ReturnValue=''

							   SELECT @ReturnValue=CONVERT(VARCHAR(20),ISNULL(PrintedQty,0)) FROM Assy_Barcode_Printed_Counter(NOLOCK) 
								WHERE ProfitCenterCode=@ProfitCenterCode AND LineCode =@LineCode AND CurrentPlannedQty>=(isnull(PrintedQty,0)+ISNULL(@ManualPrintedQty,0))
								IF @ReturnValue IS NOT NULL and @ReturnValue<>''
									 SET @ReturnValue='OK'
								ELSE
									SET @ReturnValue='NOT_OK'
									select @ReturnValue as ReturnValue
								SET @ReturnInt=1
				END
				ELSE
					BEGIN				
					
								SELECT @ReturnValue=CONVERT(VARCHAR(20),ISNULL(PrintedQty,0)) FROM Assy_Barcode_Printed_Counter(NOLOCK) 
								WHERE ProfitCenterCode=@ProfitCenterCode AND LineCode =@LineCode 
								IF @ReturnValue IS NULL OR @ReturnValue=''
								begin
				
									 SET @ReturnValue='OK'
									 select @ReturnValue as ReturnValue
									 SET @ReturnInt=1
									 return
								end

								set @ReturnValue=''
							
								SELECT @ReturnValue=CONVERT(VARCHAR(20),ISNULL(PrintedQty,0)) FROM Assy_Barcode_Printed_Counter(NOLOCK) 
								WHERE ProfitCenterCode=@ProfitCenterCode AND LineCode =@LineCode AND CurrentPlannedQty>ISNULL(PrintedQty,0)
								IF @ReturnValue IS NOT NULL and @ReturnValue<>''
									 SET @ReturnValue='OK'
								ELSE
									SET @ReturnValue='NOT_OK'
									select @ReturnValue as ReturnValue
								SET @ReturnInt=1

					END
		END
		else if @CONDITION='UPDATE_CURRENTPLANNEDQTY_FOR_SAMEPART'
		begin
					--Added by ravi on 12-02-16
					--Delete data from Assy_Barcode_Printed_Counter table if this table's date code is not matching with assy_runningPart Datecode
					IF Exists(select top 1 1 from ASSY_BARCODE_PRINTED_COUNTER where  PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE and CurrentPlannedQty < ISNULL(PrintedQty,0))
					Begin
						Update ASSY_BARCODE_PRINTED_COUNTER set PrintedQty=CurrentPlannedQty where  PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE
					End
					IF EXISTS
					(
							SELECT TOP 1 1 FROM ASSY_BARCODE_PRINTED_COUNTER(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE 
					)
					BEGIN	
								
								IF(
									(SELECT TOP 1 DATECODE FROM ASSY_BARCODE_PRINTED_COUNTER(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE)
									<>(SELECT TOP 1 DATECODE FROM ASSY_RUNNINGPART(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE ORDER BY CREATEDDATE DESC)
								)
								BEGIN
										DELETE FROM ASSY_BARCODE_PRINTED_COUNTER WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE 
								END
					END
					----------------------------end---------------------------------------
					IF EXISTS
					(
							SELECT TOP 1 1 FROM Assy_Barcode_Printed_Counter(NOLOCK) C inner join Assy_RunningPart_Previous(nolock) RPP on c.LineCode =rpp.LineCode  
							and c.Datecode =rpp.Datecode and c.PartNo =rpp.Assy_PartNo 
							inner join Assy_RunningPart(nolock)RP on rp.LineCode =rpp.LineCode and rp.Datecode =rpp.Datecode and rp.Assy_PartNo =rpp.Assy_PartNo
							and rp.Assy_Mode =rpp.Assy_Mode 
							WHERE c.ProfitCenterCode=@ProfitCenterCode AND c.LineCode =@LineCode 
					)
					BEGIN
					
						--IF EXISTS(SELECT TOP 1 1 FROM TYPE_DEFINITION_XREF_DATA(NOLOCK)
						--WHERE ATTRB_CD=@LineCode AND TYPE_CATEGORY_CD='LINE_ATTRB'
						--AND TYPE_CD='eKanban_Enable' AND WH_CODE=@ProfitCenterCode AND ATTRB_VAL='1')
						--BEGIN			
										Declare @currentcount int

										--select @currentcount=rpp.CurrentPlannedQty +sum(rp.CurrentPlannedQty) from Assy_Barcode_Printed_Counter(nolock) C 
										--inner join Assy_RunningPart(nolock) RP on C.LineCode =RP.LineCode and C.Datecode =rp.Datecode and c.PartNo =rp.Assy_PartNo 
										--inner join Assy_RunningPart_Previous(nolock) RPP	on rp.LineCode =rpp.LineCode and rp.Datecode =rpp.Datecode 
										--and rp.Assy_PartNo =rpp.Assy_PartNo and rp.Assy_Mode =rpp.Assy_Mode 							   
										--WHERE C.ProfitCenterCode=@ProfitCenterCode AND C.LineCode =@LineCode AND C.CurrentPlannedQty>=ISNULL(C.PrintedQty,0)	
										--group by rpp.CurrentPlannedQty

										select 
										@currentcount=sum(tab1.totalcount) from 
										(select rp.CurrentPlannedQty   totalcount from Assy_Barcode_Printed_Counter(nolock) C 
										inner join Assy_RunningPart(nolock) RP on C.LineCode =RP.LineCode and C.Datecode =rp.Datecode and c.PartNo =rp.Assy_PartNo 
										union  ALL
										select rp.CurrentPlannedQty   totalcount from Assy_Barcode_Printed_Counter(nolock) C 
										inner join Assy_RunningPart_Previous(nolock) RP on C.LineCode =RP.LineCode and C.Datecode =rp.Datecode and c.PartNo =rp.Assy_PartNo )
										as Tab1

										update C  set C.CurrentPlannedQty=@currentcount from Assy_Barcode_Printed_Counter(nolock) C
										WHERE C.ProfitCenterCode=@ProfitCenterCode AND C.LineCode =@LineCode AND C.CurrentPlannedQty>=ISNULL(PrintedQty,0)
						--END
						--else
						--Begin
									    

						--				UPDATE C SET C.CurrentPlannedQty=(rpp.CurrentPlannedQty +rp.CurrentPlannedQty) ,Timestamp =GETDATE()  from Assy_Barcode_Printed_Counter(nolock) C 
						--				inner join Assy_RunningPart(nolock) RP on C.LineCode =RP.LineCode and C.Datecode =rp.Datecode and c.PartNo =rp.Assy_PartNo 
						--				inner join Assy_RunningPart_Previous(nolock) RPP	on rp.LineCode =rpp.LineCode and rp.Datecode =rpp.Datecode 
						--				and rp.Assy_PartNo =rpp.Assy_PartNo and rp.Assy_Mode =rpp.Assy_Mode 							   
						--				WHERE C.ProfitCenterCode=@ProfitCenterCode AND C.LineCode =@LineCode AND C.CurrentPlannedQty>=ISNULL(C.PrintedQty,0)								
						--END
					END
					SET @ReturnInt=1			

		end

END


