CREATE PROC [dbo].[Assy_PROC_BreakDownReporting]
(
@DATA  ASSY_BREAKDOWN_REPORTING Readonly,
@OPERATION VARCHAR(100)=NULL,
@LINECODE varchar(20)=null,
@PROFITCENTERCODE VARCHAR(20)=NULL,
@DateCode VARCHAR(20)=NULL,
@PARTNUMBER VARCHAR(20)=NULL,
@STATIONNAME VARCHAR(20)=NULL,
@FROMTIME VARCHAR(20)=NULL,
@TOTIME VARCHAR(20)=NULL,
@IDLEMINS VARCHAR(20)=NULL,
@REPORTEDMINS VARCHAR(20)=NULL,
@IDLEREASON VARCHAR(100)=NULL,
@REMARKS VARCHAR(200)=NULL,
@USERID VARCHAR(12)=NULL,
@ReturnValue VARCHAR (2000)=NULL OUT,
@ReturnInt INT=NULL OUT
)
as
begin 
-- Author:		<Praveen Kumar>
-- Create date: <28 Aug 2014>
-- Description:	<Rejection Reporting.>

-- To Rembember
-- Nothing = 0
-- Success = 1
-- Error = 2
-- AlreadyExists = 3
-- NotExists = 4
  
BEGIN TRY
BEGIN TRAN
DECLARE @ERRORMSG AS VARCHAR(200)
Declare @PACKETQTY as Decimal(9,4)=0
 Declare @ChildPart varchar(20)
	 Declare @LotNumber varchar(20)
	 Declare @PartQuantity Decimal(9,4)

	 if @OPERATION='GETREASONCODE'
	 begin
	 select REASON_CD,REASON_DESC  from REASON_MASTER where REASON_TP='DP_REJECT'
	 end
	 if @OPERATION='LOAD'
	 begin
	   select [Datecode],[PartNumber],[StationName],[FromTime],[ToTime],IdleMins,[ReportedMins],[IdleReason],				[Remarks]       from         [Assy_BreakDownReporting] where [Datecode] = @DateCode order by EntDt desc
	    set @ReturnValue='DATA SELECTED'
	    set @ReturnInt=1
	 end
    
    if @OPERATION='SEARCH'
	begin
	--if @DateCode='' and @PARTNUMBER='' and @STATIONNAME='' and @FROMTIME='' and @TOTIME=''
	-- begin
	--	 set @ReturnValue='NO DATA FOUND'
	--	  set @ReturnInt=0
 --    end
	-- else
	 begin
	 select [Datecode],[PartNumber],[StationName],[FromTime],[ToTime],IdleMins,[ReportedMins],[IdleReason],							[Remarks] from [Assy_BreakDownReporting] where [Datecode] like '%'+@DateCode+'%' AND PartNumber Like							'%'+@PARTNUMBER+'%' AND StationName Like
			'%'+@STATIONNAME+'%' AND FromTime Like '%'+@FROMTIME+'%' AND	ToTime Like	'%'+@TOTIME+'%' 
			order by EntDt desc
		  set @ReturnValue='DATA SEARCHED'
		  set @ReturnInt=1
	     
	 end
	end

	 if @OPERATION='SAVE'
	 begin
	   
	    UPDATE A
		 set A.[IdleReason]=B.IdleReason ,A.Remarks=B.Remarks,A.EntDt=getdate() 
		 from [Assy_BreakDownReporting] A inner join @DATA B
		 on A.Datecode=B.Datecode and A.StationName=B.StationName and A.FromTime=B.FromTime and A.ToTime =B.ToTime 
		 where ProfitCenterCode=@PROFITCENTERCODE  and    LineCode=@LINECODE  
	    set @ReturnValue='DATA UPDATED'
	    set @ReturnInt=1
	 end
COMMIT TRAN
END TRY
			BEGIN CATCH
			ROLLBACK TRAN
			SET @ReturnValue =	CAST(ERROR_NUMBER() as varchar(5)) + '|' + 
			CAST(ERROR_SEVERITY()as varchar(5)) + '|' + 
			CAST(ERROR_STATE() as varchar(5)) + '|' + 
			CAST(ERROR_PROCEDURE() as varchar(200)) + '|' + 
			CAST(ERROR_LINE() as varchar(5)) + '|' + 
			CAST(ERROR_MESSAGE() as varchar(1500))
							
		   SET @ReturnInt = 2
			END CATCH
end





