/****** Object:  StoredProcedure [dbo].[ASSY_PROC_BUBBLE_TEST]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*************************************************************************************** 
PROCEDURE : ASSY_PROC_BUBBLE_TEST
AUTHOR: SACHIN KUMAR
DATE WRITTEN :  Sep. 21, 2017
PURPOSE:  

TEST SCRIPT		


****************************************************************************************/
CREATE PROCEDURE [dbo].[ASSY_PROC_BUBBLE_TEST]
(
 @P_MODE varchar(50)='',
 @P_profitCenterCode varchar(10)='',
 @P_lineCode varchar(10)='',
 @P_PartNo varchar(30)='',
 @P_barcode varchar(30)='',
 @P_UserCode varchar(30)='',
 @P_Result varchar(4)='',
 @P_MachineCode varchar(6)='',
 @P_OperationCode varchar(6)='',
 @P_SerialPort varchar(6)='',
 @ReturnValue VARCHAR (2000)=NULL OUT,
 @ReturnInt INT=NULL OUT
)
AS
BEGIN
	begin try
	
	IF(@P_MODE='GET_RUNNING_PART')
	BEGIN
			select ISNULL(Assy_PartNo,'') from Assy_RunningPart where LineCode=@P_lineCode 
			and ProfitCenterCode=@P_profitCenterCode
	END

	IF(@P_MODE='SAVE_RESULT')
	BEGIN
			Declare @ParameterData Assy_TYPE_LineAssyParamData_Running_DB

			insert into @ParameterData(ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,
			TagName,Value,Result,Datecode,UserID)
			select @P_profitCenterCode,@P_lineCode,@P_MachineCode,
			@P_OperationCode,'1',@P_barcode,'Result',@P_Result,@P_Result,'',@P_UserCode 

			exec Assy_Proc_DBIntegration @Operation='INSERT_PLC_PARAMS',@lineCode=@P_lineCode,
			@tblParameters=@ParameterData , @TD_Table=''

			Select 'OK'

	END

	IF(@P_MODE='CHK_BUBBLE_TEST_DTL')
	BEGIN
			declare @OperationCode varchar(6)
						
			select @OperationCode=keyValue from routingConfigDetails(nolock) 
			where ProfitCenterCode=@P_profitCenterCode and
			LineCode=@p_lineCode and partNumber = @P_PartNo and KeyType='BubbleTestStationCode' and sts_cd=0

			select distinct OperationName,OperationCode from operationMst(nolock) where ProfitCenterCode=@P_profitCenterCode
			and OperationCode=@OperationCode

	END

	IF(@P_MODE='CHK_BUBBLE_TEST_OC_CODE_IN_PARTWISE_ROUTING')
	BEGIN
			if exists(select top 1 1 from RoutingConfigPartWise(nolock)
			where ProfitCenterCode=@P_profitCenterCode and
			PartNo = @P_PartNo and OperationCode=@p_operationCode
			)
			begin
					select top 1 MachineCode,OperationCode from RoutingConfigPartWise(nolock) where ProfitCenterCode=@P_profitCenterCode and
					PartNo = @P_PartNo and OperationCode=@p_operationCode
			end
			else
			begin
					SELECT 'NOK'
			end
	END

	IF(@P_MODE='GET_SERIAL_PORT')
	BEGIN			
			
			select ISNULL(KeyValue,'') from routingConfigDetails(nolock) where ProfitCenterCode=@P_profitCenterCode and
			LineCode=@P_lineCode and STS_CD=0 and KeyType='BubbleTestSerialPort'
	END

	IF(@P_MODE='SET_SERIAL_PORT')
	BEGIN			
			
			if exists(select top 1 1 from routingConfigDetails(nolock) where ProfitCenterCode=@P_profitCenterCode and
			LineCode=@P_lineCode and STS_CD=0 and KeyType='BubbleTestSerialPort')
			begin
					update routingConfigDetails
					set KeyValue=@P_SerialPort
					where ProfitCenterCode=@P_profitCenterCode and
					LineCode=@P_lineCode and STS_CD=0 and KeyType='BubbleTestSerialPort'
			end
			else
			begin
					insert into RoutingConfigDetails(ProfitCenterCode,LineCode,MachineCode,OperationCode,PartNumber,
					KeyType,KeyValue,SeqNumber,isSeqReq,chkFromTable,Remarks,STS_CD,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP
					)
					values(@P_profitCenterCode,@P_lineCode,'','','','BubbleTestSerialPort',@P_SerialPort,NULL,NULL,'',
					'Configure Bubble Test Serial Port',0,'ADMIN',GETDATE(),'ADMIN',GETDATE())
			end 
			
	END

	IF(@P_MODE='SCAN_DONE')
	BEGIN
			IF EXISTS
			(	
			SELECT 1 FROM  ASSY_SCAN_OK_RFID WITH (NOLOCK) WHERE PROFITCENTERCODE=@P_profitCenterCode 
			AND LINECODE=@P_lineCode	AND MACHINECODE=@p_machineCode AND OPERATIONCODE=@P_OperationCode 
			)			
			BEGIN
					UPDATE ASSY_SCAN_OK_RFID SET BARCODE=@P_barcode ,ISSCAN=1,TIMESTAMP=GETDATE() WHERE PROFITCENTERCODE=@P_profitCenterCode 
					AND LINECODE=@P_lineCode	AND MACHINECODE=@p_machineCode AND OPERATIONCODE=@P_OperationCode 
			END
			ELSE
			BEGIN
					INSERT INTO ASSY_SCAN_OK_RFID
					(
					PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE
					,STATIONCODE,BARCODE,ISSCAN,TIMESTAMP
					)
					SELECT @P_profitCenterCode,@P_lineCode,@p_machineCode,@P_OperationCode
					,1,@P_barcode,1,GETDATE()
			END				
			
			SELECT 'OK'
		END

	IF(@P_Mode='getValidationResult')
	BEGIN
		
			
			CREATE TABLE #IS_SCANNED_BARCODE_OK
			(
			   BARCODE varchar(100),
			   isScanOK int
			)

			insert into #IS_SCANNED_BARCODE_OK
			exec [Assy_Proc_DBIntegration] @Operation='GET_SCAN_OK_AND_BARCODE',@OperationCode=@P_OperationCode,@lineCode=@P_lineCode


			if exists(select top 1 1 from #IS_SCANNED_BARCODE_OK)
			begin
					IF((SELECT top 1 ISSCANOK  FROM #IS_SCANNED_BARCODE_OK where barcode=@P_barcode) = 1)
					BEGIN
							update Assy_Scan_OK 
							set isScan=0
							where LineCode=@P_lineCode and OperationCode=@P_OperationCode and Barcode=@P_barcode 

							SELECT 'OK','Scanned Successfully'
					END
			end

			CREATE TABLE #IS_SCANNED_BARCODE_FAIL
			(
			   BARCODE varchar(100),
			   isIncorrect int,
			   HMIMessage VARCHAR(1000)
			)

			insert into #IS_SCANNED_BARCODE_FAIL
			exec [Assy_Proc_DBIntegration] @Operation='IS_INCORRECT_LABEL_SCANNED',
			@OperationCode=@P_OperationCode , @lineCode=@P_lineCode

			if exists(select top 1 1 from #IS_SCANNED_BARCODE_FAIL)
			begin
					if((select top 1 isIncorrect  from #IS_SCANNED_BARCODE_FAIL where barcode=@P_barcode) = 1)
					begin							     
							update Assy_incorrectLabel 
							set isIncorrect=0
							where LineCode=@P_lineCode and OperationCode=@P_OperationCode
							and Barcode=@P_barcode

							SELECT 'NOK',HMIMessage  FROM #IS_SCANNED_BARCODE_FAIL(NOLOCK) 										
					end
			end
                
				CREATE TABLE #IS_SCANNED_BARCODE_DUPLICATE
				(
				   BARCODE varchar(100),
				   isDuplicate int
				)

				insert into #IS_SCANNED_BARCODE_DUPLICATE
				exec [Assy_Proc_DBIntegration] @Operation='IS_DUPLICATE_LABEL_SCANNED',
				@OperationCode=@P_OperationCode , @lineCode=@P_lineCode


				if exists(select top 1 1 from #IS_SCANNED_BARCODE_DUPLICATE)
				begin
						if((select top 1 isDuplicate  from #IS_SCANNED_BARCODE_DUPLICATE where barcode=@P_barcode) = 1)
						begin		    			
								update Assy_DuplicateLabel 
								set isDuplicate=0
								where LineCode=@P_lineCode and OperationCode=@P_OperationCode
								and Barcode=@P_barcode 

								SELECT 'NOK','Duplicate Label' 
						end
				end

	END

	end try
	begin catch
			SELECT 'NOK', CAST(ISNULL(ERROR_NUMBER(),0) AS VARCHAR(5)) + '|' + 
			CAST(ISNULL(ERROR_SEVERITY(),0)AS VARCHAR(5)) + '|' + 
			CAST(ISNULL(ERROR_STATE(),0) AS VARCHAR(5)) + '|' + 
			CAST(ISNULL(ERROR_PROCEDURE(),'') AS VARCHAR(200)) + '|' + 
			CAST(ISNULL(ERROR_LINE(),0) AS VARCHAR(5)) + '|' + 
			CAST(ISNULL(ERROR_MESSAGE(),'') AS VARCHAR(1500)) AS 'MSG'

	end catch

END

GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_Bypass_QAInspection]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/*---------------------------------------------------------------------------  
'PROCEDURE NAME   : Assy_Proc_Bypass_QAInspection
'FUNCTION		  : Validate QA Inspection for ABS Line (Jomesa,wet test etc.)
'CREATED BY		  : Sachin Kumar  
'CREATED ON		  : 2017-10-09
'REVISION HISTORY :

 
'Script			  :

declare @ReturnValue VARCHAR (2000)=NULL 
declare @ReturnInt INT=NULL 

exec Assy_Proc_Bypass_QAInspection @P_ProfitCentercode='0018' , @P_LineCode='S01' , 
@P_Condition='GetQAInspectionLotNumber',@ReturnValue=@ReturnValue out,@ReturnInt=@ReturnInt out
select @ReturnValue
'---------------------------------------------------------------------------*/    
CREATE PROCEDURE [dbo].[Assy_Proc_Bypass_QAInspection]
(
		@P_ProfitCentercode	varchar(10)=null,
		@P_LineCode	varchar(10)=null,
		@P_Condition varchar(100)=null,	
		@P_EnableDisable bit=0,
		@P_LotNumber varchar(10)=null,
		@P_PartNumber varchar (20)='',
		@ReturnValue VARCHAR (2000)=NULL OUT,
		@ReturnInt INT=NULL OUT
)
AS
BEGIN
	 begin try

		IF(@P_Condition='IsQAInspectionRequired')
		BEGIN
			
			if not exists(select top 1 1 from RoutingConfigDetails(nolock) where LineCode=@P_LineCode and ProfitCenterCode=@P_ProfitCentercode 
			and KeyType='IsQAInspectionRequired')
			begin
			insert into RoutingConfigDetails(ProfitCenterCode,LineCode,MachineCode,OperationCode,PartNumber,KeyType,KeyValue,
			SeqNumber,isSeqReq,chkFromTable,Remarks,STS_CD,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP
			) values(@P_ProfitCentercode,@P_LineCode,'','','','IsQAInspectionRequired','0',NULL,NULL,'','Check QA Inspection Done for Previous Part or Not'
			,0,'ADMIN',GETDATE(),'ADMIN',GETDATE())
			end

			if exists(select top 1 1 from RoutingConfigDetails(nolock) where LineCode=@P_LineCode and ProfitCenterCode=@P_ProfitCentercode 
			and KeyType='IsQAInspectionRequired' and KeyValue='1')
			begin
					SET @RETURNVALUE='Y'
					SET @RETURNINT=1
			end
			else
			begin

					SET @RETURNVALUE='N'
					SET @RETURNINT=1
			end
			
			RETURN

		END	

		IF(@P_Condition='QAInspectionEnableDisable')
		BEGIN
			
			if not exists(select top 1 1 from RoutingConfigDetails(nolock) where LineCode=@P_LineCode and ProfitCenterCode=@P_ProfitCentercode 
			and KeyType='IsQAInspectionRequired')
			begin
			insert into RoutingConfigDetails(ProfitCenterCode,LineCode,MachineCode,OperationCode,PartNumber,KeyType,KeyValue,
			SeqNumber,isSeqReq,chkFromTable,Remarks,STS_CD,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP
			) values(@P_ProfitCentercode,@P_LineCode,'','','','IsQAInspectionRequired','0',NULL,NULL,'','Check QA Inspection Done for Previous Part or Not'
			,0,'ADMIN',GETDATE(),'ADMIN',GETDATE())
			end

			update RoutingConfigDetails
			set KeyValue=@P_EnableDisable
			where LineCode=@P_LineCode and ProfitCenterCode=@P_ProfitCentercode 
			and KeyType='IsQAInspectionRequired'
			
			if(@P_EnableDisable=1)
			begin
					SELECT 'Y' --Enabled					
			end
			else
			begin
					SELECT 'N' --Disabled					
			end
			SET @RETURNINT=1
			RETURN

		END	
		-- Local DB Call only
		IF(@P_Condition='GetQAInspectionLotNumber')
		BEGIN
		        DECLARE @PartType varchar(20)=''
		        SELECT Top 1 @PartType = ISNULL(MATERIAL_TP,'') FROM PRODUCT_MASTER (NOLOCK)
				WHERE warehouse_cd = @P_ProfitCentercode AND STS_CD = 0 AND SEWS_PART_NO = @P_PartNumber
				IF @PartType = ''
				BEGIN
					SET @ReturnValue = 'MATERIAL_TP NOT DEFINED FOR PART.'
					SET @ReturnInt = 2
					RETURN
				END
					-- First Check QA Inspection Required Or Not
				if exists (select top 1 1 from RoutingConfigDetails(nolock)
				where LineCode=@P_LineCode and ProfitCenterCode=@P_ProfitCentercode 
				and KeyType='IsQAInspectionRequired' and keyvalue='1')
				begin
					 -- get lot number
					 
					IF EXISTS(SELECT TOP 1 1 FROM SYS.TABLES WHERE name = 'ASSY_GENERATE_LOTNO_ON_DATACHANGE')
					BEGIN
							
							declare @lot_no varchar(6) =''
							declare @dateCode varchar(4)=''
							declare @lotSerialNo varchar(10)=''

							select @dateCode=ISNULL(Datecode,''),@lot_no=ISNULL(Lot_No,'') 
							from ASSY_GENERATE_LOTNO_ON_DATACHANGE(nolock)
							where ProfitCenterCode=@P_ProfitCentercode and LineCode=@P_LineCode
							
							SET @lotSerialNo = REPLACE(STR(@lot_no, 6), SPACE(1), '0')
							SET @lotSerialNo = @lotSerialNo+ISNULL(@dateCode,'')

							SET @RETURNVALUE=ISNULL(@lotSerialNo,'N')

					END
					ELSE
					BEGIN
					SET @RETURNVALUE='N'
					END
				end
				else
				begin
				SET @RETURNVALUE='N'
				SET @RETURNINT=1
				end
		END

		IF(@P_Condition='Check_IsQAInspection_Done')
		BEGIN
			 if exists(select top 1 1 from ABS_QA_Assy(nolock) where wh_code=@P_ProfitCentercode
			and Linecode=@P_LineCode and lotNo=@P_LotNumber and sts_cd=2)
			begin
					SELECT 'OK'
			end
			else
			begin
					SELECT 'NOK','Please Do QA Inspection For Lot Number ' + ISNULL(@P_LotNumber,'')
			end
		END
		


	END TRY
	 BEGIN catch
		SET @ReturnValue =	CAST(ERROR_NUMBER() as varchar(5)) + '|' + 
			CAST(ERROR_SEVERITY()as varchar(5)) + '|' + 
			CAST(ERROR_STATE() as varchar(5)) + '|' + 
			CAST(ERROR_PROCEDURE() as varchar(200)) + '|' + 
			CAST(ERROR_LINE() as varchar(5)) + '|' + 
			CAST(ERROR_MESSAGE() as varchar(1500))
			RAISERROR (@ReturnValue,16,1)						
		   SET @ReturnInt = 2
	END CATCH
END


GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_Check_RunningPart_SeclectPart_Same]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
