CREATE Proc [dbo].[Assy_Proc_Check_RunningPart_SeclectPart_Same]
(
@LineCode varchar(20)=Null,
@ProfitCenterCode varchar(20)=null,
@CurrentlySelPartNo varchar(20)=null,
@ReturnValue VARCHAR (50)=NULL OUT,
@ReturnInt INT=NULL OUT
)
AS
BEGIN
		-- Author:		<Ravishankar Mishra>
		-- Create date: < 1 july 2015>

		-- Author:		<Ravishankar Mishra>
		-- Create date: < 1 july 2015>
		
		-- Modified By:	<Ravishankar Mishra>
		-- Modified date: 07-04-2017
		--DESCRIPTION :Added condition by Ravi for Auto Tally chart Bypass

		-- Modified By:	<Rashid>
		-- Modified date: 01-06-2017
		--DESCRIPTION : Remove condition for Auto Tally chart Bypass. Handle through Front end
		
		-- To Rembember
		-- Nothing = 0
		-- Success = 1
		-- Error = 2
		-- AlreadyExists = 3
		-- NotExists = 4
			--Added  by Ravi on 07-04-17 for Auto Tally chart Bypass
			--if exists
			--(
			--	select 1 from dbo.linemst with(nolock) where  ProfitCenterCode=@profitCenterCode AND LineCode = @LINECODE and isnull(AutoTallyChartEnable,0)=1
			--)
			--begin
			--		set @ReturnValue='OK'
			--		set @ReturnInt=1
			--		return
			--end
			 exec Assy_proc_datecode @ProfitCenterCode,@ReturnValue out,@ReturnInt out	
			  if exists
			  (
			  		select Top 1 datecode from dbo.Assy_RunningPart(nolock) where ProfitCenterCode =@ProfitCenterCode 
					and LineCode=@linecode and datecode=@ReturnValue order by CreatedDate desc
			  )
			  BEGIN
						if exists
						(
							select Top 1 Assy_PartNo  from dbo.Assy_RunningPart(nolock) where ProfitCenterCode =@ProfitCenterCode 
							and LineCode=@linecode and Assy_PartNo=@CurrentlySelPartNo  order by CreatedDate desc
						)
						begin
								IF EXISTS(SELECT TOP 1 1 FROM TYPE_DEFINITION_XREF_DATA(NOLOCK)
								WHERE ATTRB_CD=@LineCode AND TYPE_CATEGORY_CD='LINE_ATTRB'
								AND TYPE_CD='eKanban_Enable' AND WH_CODE=@ProfitCenterCode AND ATTRB_VAL='1')
								BEGIN
									IF EXISTS(select Top 1 1 from assy_runningkanban where isnull(iscompleted,0)=1 and PartNo = @CurrentlySelPartNo
									AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode and Datecode <> PostedDatecode )									
									Begin
										select @ReturnValue=dbo.Assy_FN_Get_FirstStation_ProducePart(@LineCode,@ProfitCenterCode)
										set @ReturnInt=1
										return						
									end	    

								END

								set @ReturnValue='OK'
								set @ReturnInt=1
								return
						end
						else
						begin
								select @ReturnValue=dbo.Assy_FN_Get_FirstStation_ProducePart(@LineCode,@ProfitCenterCode)
								set @ReturnInt=1
								return
						end					
			  END
			  ELSE
				  BEGIN
							IF EXISTS(SELECT TOP 1 1 FROM TYPE_DEFINITION_XREF_DATA(NOLOCK)
							WHERE ATTRB_CD=@LineCode AND TYPE_CATEGORY_CD='LINE_ATTRB'
							AND TYPE_CD='eKanban_Enable' AND WH_CODE=@ProfitCenterCode AND ATTRB_VAL='1')
							BEGIN
								IF EXISTS(select Top 1 1 from assy_runningkanban where isnull(Isrunning,0)=1 and PartNo = @CurrentlySelPartNo
								AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode)									
								Begin
									set @ReturnValue='OK'
									set @ReturnInt=1
									return						
								end	    
							END
			  				select @ReturnValue=dbo.Assy_FN_Get_FirstStation_ProducePart(@LineCode,@ProfitCenterCode)
							set @ReturnInt=1
							return					
				  END
END


GO
