CREATE proc [dbo].[assy_Proc_ChildPartConsumption]
(
    @CONDITION varchar(40) = null,
	@ProfitCenterCode varchar(20)=null,
	@LineCode varchar(20)=null,
	@Kanban_Id varchar(20) = null,
	@Is_Manual bit = 0,
	@FG_Conf_Qty int = 0,
