				from BOM_MASTER as a left join INV_SERIAL as b
				on a.RM_PART_NO = b.SEWS_PART_NO and b.STS_CD = 0 and b.LOC_ID = @LOCATION_CODE and b.WH_CODE = @ProfitCenterCode  and isnull(b.INTRANSIT_FLG, 0) = 0
				where a.FG_PART_NO = @Running_Part and a.MAT_PROCURE_TYPE is null and a.ALT_ITEM_GRP_CODE  is null and a.ver=@BOM_VER and a.STS_CD =0
				group by a.RM_PART_NO, a.BOM_QTY, a.BASE_QTY, a.MAT_PROCURE_TYPE
