				--on a.RM_PART_NO = b.SEWS_PART_NO and b.STS_CD = 0 and b.LOC_ID = @LOCATION_CODE and b.WH_CODE = @ProfitCenterCode
					inner join PRODUCT_MASTER as p on a.RM_PART_NO = p.SEWS_PART_NO  and a.WH_CODE =p.warehouse_cd 
