				  insert into assy_CurrentStockStatus (ProfitCenterCode, FG_PART_NO, RM_PART_NO, Required_Qty , Available_Qty, Ent_Dt, Prod_Version)
				  select @ProfitCenterCode, @Running_Part,  rm_part_no, RequiredQty, AvailableQty, GETDATE(), Prod_Version from #tempSample

				 
				  delete from #tempSample where LineCode = @LineCode
				  delete from  #tempSample1 where LineCode = @LineCode
				
				Fetch next from curProdVersion into @PROD_VER
				END
			  close curProdVersion
			  deallocate curProdVersion

