		--			inner join PRODUCT_MASTER as p on a.RM_PART_NO = p.SEWS_PART_NO  and a.WH_CODE =p.warehouse_cd 
		--			where a.FG_PART_NO = @RM_PART_NO and a.MAT_PROCURE_TYPE ='50' and a.WH_CODE =@ProfitCenterCode and ISNULL(p.MATERIAL_TP,'') <> 'TMC'
					

		--			FETCH NEXT FROM CUR INTO @RM_PART_NO
		--		End

		--		CLOSE CUR
		--		DEALLOCATE CUR
				
		--	   delete from assy_ChildPartConsumption_Temp where LineCode = @LineCode and ProfitCenterCode = @ProfitCenterCode

		--	   insert into assy_ChildPartConsumption_Temp (ProfitCenterCode, LineCode, rm_part_no, RequiredQty, AvailableQty, MAT_Procure_Type)
		--	   select @ProfitCenterCode, @LineCode,  rm_part_no, RequiredQty, AvailableQty, MAT_Procure_Type from ##tempSample
				
		--	   select rm_part_no, sum(RequiredQty), AvailableQty from ##tempSample group by rm_part_no, AvailableQty
				
				


		--		drop table ##tempSample
		--		drop table ##tempSample1
		--  End	
		--End

		
		IF(@CONDITION = 'GET_STOCK_STATUS')
		Begin
		 select rm_part_no, sum(isnull(Required_qty, 0)) as Required_qty, isnull(available_qty, 0) as available_qty, Prod_Version from assy_CurrentStockStatus (nolock) where 
		 fg_part_no = @Running_Part and ProfitCenterCode = @ProfitCenterCode
		 group by rm_part_no, available_qty, Prod_Version
		End

		
		IF(@CONDITION = 'GET_STOCK_STATUS_BY_KANBAN')
		Begin
		 set @PROD_VERSION = (select top 1 PRODUCTION_VERSION from physical_bin_master where BIN_ID = @Kanban_Id)
		  select rm_part_no, sum(isnull(Required_qty, 0)) as Required_qty, ISNULL(available_qty, 0) as available_qty, Prod_Version from assy_CurrentStockStatus (nolock) where 
		 fg_part_no = @Running_Part and ProfitCenterCode = @ProfitCenterCode and Prod_Version = @PROD_VERSION
		 group by rm_part_no, available_qty, Prod_Version
		End

		
		IF(@CONDITION = 'GET_STOCK_STATUS_BY_PROD_VER')
		Begin
		 
		 select rm_part_no, sum(isnull(Required_qty, 0)) as Required_qty, isnull(available_qty, 0) as available_qty, Prod_Version from assy_CurrentStockStatus (nolock) where 
		 fg_part_no = @Running_Part and ProfitCenterCode = @ProfitCenterCode and Prod_Version = @PROD_VERSION
		 group by rm_part_no, available_qty, Prod_Version
		End

		IF(@CONDITION = 'GET_STOCK_STATUS_MANUAL')
		Begin
		

		 if not exists
		   (
		      select top 1 Kanban_id from assy_lineassystatus where kanban_id is not null and PartNo = @Running_Part order by ResultTimestamp desc
		   )
		   Begin
		     set @PROD_VERSION = (select top 1 PRODUCTION_VERSION from physical_bin_master where Part_No = @Running_Part)
		   End
		   else
		   Begin
				set @Kanban_Id = (select top 1 Kanban_id from assy_lineassystatus where kanban_id is not null and PartNo = @Running_Part order by ResultTimestamp desc)
				set @PROD_VERSION = (select top 1 PRODUCTION_VERSION from physical_bin_master where Bin_Id = @Kanban_Id)
		  end


		 set @Manual_Conf_Qty = (select count(1) from Assy_Passed_Items_At_FV where Is_Posted = 0 and LineCode = @LineCode and ProfitCenterCode = @ProfitCenterCode)
		 delete from assy_CurrentStockStatus_Manual where FG_PART_NO = @Running_Part and ProfitCenterCode = @ProfitCenterCode

		 
		 create table #tempManualConsumption
			(
			   [ID] Bigint identity(1,1),
				[ProfitCenterCode] [varchar](10) NULL,
				[FG_PART_NO] [varchar](20) NULL,
				[RM_PART_NO] [varchar](20) NULL,
				[Required_Qty] [int] NULL,
				[Available_Qty] [int] NULL,
				[Ent_Dt] [datetime] NULL,
				[Prod_Version] [varchar](10) NULL
			)

			insert into #tempManualConsumption(ProfitCenterCode, FG_PART_NO, RM_PART_NO, Required_Qty, Available_Qty,
			Ent_Dt, Prod_Version)
			select ProfitCenterCode, FG_PART_NO, RM_PART_NO, isnull(Required_Qty, 0) as Required_Qty, isnull(Available_Qty, 0) as Available_Qty,
			Ent_Dt, Prod_Version from assy_CurrentStockStatus (nolock) where 
			 FG_PART_NO = @Running_Part and ProfitCenterCode = @ProfitCenterCode and Prod_Version = @PROD_VERSION
		     
			 
			
			select @MinIndex = min(id), @MaxIndex = max(id) from #tempManualConsumption (nolock) 
			where  FG_PART_NO = @Running_Part and ProfitCenterCode = @ProfitCenterCode and Prod_Version = @PROD_VERSION

			set @CurIndex = @MinIndex

		 --select * from assy_CurrentStockStatus

		  declare @factor int;
		 declare @RM_QTY INT
		 declare @Avlbl_Qty INT

		  while(@CurIndex <= @MaxIndex)
		  Begin
			select @RM_PART_NO = rm_part_no, @RM_QTY = Required_Qty, @Avlbl_Qty = Available_Qty from #tempManualConsumption
			where ID = @CurIndex

			print @Confirmation_Qty
		    set @factor = @RM_QTY / @Confirmation_Qty
			
			declare @temp int;
			set @temp = @Manual_Conf_Qty * @factor
			
			insert into assy_CurrentStockStatus_Manual(ProfitCenterCode, FG_PART_NO, RM_PART_NO, Required_Qty, Available_Qty, Ent_Dt)
			values (@ProfitCenterCode, @Running_Part, @RM_PART_NO, @temp, @Avlbl_Qty, getdate())

			set @CurIndex = @CurIndex + 1
		  End
		 
		  drop table #tempManualConsumption
	 
		 select rm_part_no, sum(Required_qty), available_qty from assy_CurrentStockStatus_manual (nolock) where 
		 fg_part_no = @Running_Part and ProfitCenterCode = @ProfitCenterCode
		 group by rm_part_no, available_qty

		End

		

		IF (@CONDITION = 'CONSUME_CHILD_PARTS')
	    Begin
		  IF(@ChildValidationRequired = 'N')
		Begin
		    
			
			declare @INV_QTY INT
			declare @BAL_QTY INT
			declare @INV_SERIAL varchar(20)

			select @MinIndex = min(id), @MaxIndex = max(id) from assy_StockForConsumption (nolock) where LineCode = @LineCode and FG_PART_NO = @Running_Part
			set @CurIndex = @MinIndex

            while(@CurIndex <= @MaxIndex)
			Begin
			  select @RM_PART_NO =  rm_part_no, @RM_QTY = isnull(Required_Qty, 0), @Avlbl_Qty = isnull(available_qty, 0) from assy_StockForConsumption where ID = @CurIndex

			  Begin
			 
			set @factor = @RM_QTY / @confirmation_qty
			set @RM_QTY = @FG_Conf_Qty * @factor
			 
			  SET @BAL_QTY = @RM_QTY
			  while (@BAL_QTY <> 0)
			  Begin
			    set @ITEM_NO = [dbo].[FN_GET_ITEM_NO](@RM_PART_NO, @ProfitCenterCode) 

				set @INV_SERIAL = (select top 1 SERIAL_NO from inv_serial (nolock)
				where WH_CODE = @ProfitCenterCode and SEWS_PART_NO = @RM_PART_NO AND LOC_ID = @LOCATION_CODE
				 and STS_CD = 0 and isnull(INTRANSIT_FLG, 0) = 0  order by ENT_STAMP)
				
				SET @INV_QTY = (select convert(int, isnull(SERIAL_QTY, 0)) from INV_SERIAL where SERIAL_NO = @INV_SERIAL)
				--print 'inv_serial'
				--print @INV_SERIAL
				--print 'rm-part'
				--print @RM_PART_NO
				--print 'inv-qty'
				--print @INV_QTY

				--print 'required qty'
				--print @RM_QTY

				--print 'balance qty'
				--print @BAL_QTY
				if(@INV_QTY <= @BAL_QTY)
				Begin
				 -- print 'inv qty is less than required bal qty'
				  set @BAL_QTY = @BAL_QTY - @INV_QTY 
				 -- print 'Balance Qty'
				 -- print @BAL_QTY
				  UPDATE inv_serial set SERIAL_QTY = 0, sts_cd = 100 where SERIAL_NO = @INV_SERIAL
				  --update assy_CurrentStockStatus set Available_Qty = 0 where rm_part_no = @RM_PART_NO
				End
				else
				Begin
				  set @BAL_QTY = @INV_QTY - @BAL_QTY
				  UPDATE inv_serial set SERIAL_QTY = @BAL_QTY where SERIAL_NO = @INV_SERIAL
				  set @BAL_QTY = 0
				End

			  End

			  --select * from assy_CurrentStockStatus

			  declare @iAvlblTemp int;
			 -- set @iAvlblTemp = @Avlbl_Qty - @RM_QTY

			  set @iAvlblTemp = (select sum(serial_qty) from inv_serial (nolock)
				where WH_CODE = @ProfitCenterCode and SEWS_PART_NO = @RM_PART_NO AND LOC_ID = @LOCATION_CODE
				 and STS_CD = 0 and isnull(INTRANSIT_FLG, 0) = 0)

			  update assy_CurrentStockStatus set Available_Qty = @iAvlblTemp where rm_part_no = @RM_PART_NO

			  set @CurIndex = @CurIndex + 1

			end

			End
		
			
			
			delete from assy_StockForConsumption where LineCode = @LineCode 
		  
		End
		End
		
									
					     
END TRY
			BEGIN CATCH
			
			SET @ReturnValue =	CAST(ERROR_NUMBER() as varchar(5)) + '|' + 
			CAST(ERROR_SEVERITY()as varchar(5)) + '|' + 
			CAST(ERROR_STATE() as varchar(5)) + '|' + 
			CAST(ERROR_PROCEDURE() as varchar(200)) + '|' + 
			CAST(ERROR_LINE() as varchar(5)) + '|' + 
			CAST(ERROR_MESSAGE() as varchar(1500))			
			--ROLLBACK TRAN			
			SET @ReturnInt = 2
			raiserror(@ReturnValue,16,1)
			END CATCH
			

END






GO
/****** Object:  StoredProcedure [dbo].[ASSY_PROC_COUPLING]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
CREATE PROC [dbo].[ASSY_PROC_COUPLING] 
(
	@CONDITION VARCHAR(500),
	@PROFITCENTERCODE VARCHAR(10) = NULL,
	@LINECODE VARCHAR(20) = NULL,
	@OPERATIONCODE VARCHAR(20) = NULL,
	@FG_PART_NO VARCHAR(20) = NULL,
	@CHILD_PART_NO VARCHAR(20) = NULL,
	@MACHINECODE VARCHAR(20) = NULL,
	@STATIONCODE VARCHAR(20) = '1',
	@DATECODE CHAR(4) = NULL,
	@BARCODE VARCHAR(100) = NULL,
	@PREFIX CHAR(2) = NULL,
	@SUFFIX CHAR(2) = NULL,
	@RETURNVALUE VARCHAR (MAX) = NULL OUT,
	@RETURNINT INT = NULL OUT,
	@USERID VARCHAR(10) = NULL,
	@ENGRAVING_MACHINECODE VARCHAR(20) = NULL,
	@ENGRAVING_OPERATIONCODE VARCHAR(20) = NULL,
	@ENGRAVINGSTATUS VARCHAR(10) = NULL,
	@ENABLE_TMC_VALIDATION INT = 0,
	@CNCREQUIREDSTATUS BIT = NULL,
	@ENABLEDISABLECNCVALIDATION INT = NULL
)
AS
BEGIN
	/*
	 AUTHOR:			< RAVISHANKAR MISHRA >
	 CREATE DATE:		< 13 JAN 2015 >
	 MODIFIED BY:		< RASHID SIDDIQUI >
	 MODIFIED DATE:		< 12 OCT 2016>
	 DESCRIPTION:		< ENGRAVING AND COUPLING FOR NISSAN LINE 6 >
	 MODIFIED DATE:		< 24 JAN 2017 >
	 DESCRIPTION:		< COUPLING DATA WILL INSERT FROM COUPLING PROCEDURE IMMEDIATELY - INSERT_COUPLING_BARCODE BLOCK >
	 MODIFIED DATE:		< 02 FEB 2017 >
	 DESCRIPTION:		< TORQUE VALUE IN DECIMAL > 
	 MODIFIED BY:		< SUDESH KUMAR >
	 MODIFIED DATE:		< 20170515 >
	 DESCRIPTION:		< ADDED COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING FOR MAPPING OF PRODUCTION ORDER WITH BARCODE >
	 MODIFIED BY:		< RASHID SIDDIQUI >
	 MODIFIED DATE:		< 20170515 >
	 DESCRIPTION:		< INSERT COUPLING SCAN LOG >
	 MODIFIED BY:		< RASHID SIDDIQUI >
	 MODIFIED DATE:		< 20171211 >
	 DESCRIPTION:		< SELECT TOP 1 IN LINK SERVER WHILE VALIDATING TMC IN CENTRAL SERVER >
	 MODIFIED DATE:		< 20180228 >
	 DESCRIPTION:		< VALIDATING CUSTOMER PART NUMBER OF ENGRAVED TMC PART WHILE COUPLING IN NISSAN LINE 6 ONLY >
	
	DECLARE @RETURNVALUE VARCHAR(100)
	EXEC [ASSY_PROC_COUPLING] @CONDITION = 'VALIDATEBARCODEFORREPRINIING',@LINECODE = 'P2',@PROFITCENTERCODE = '0021',@OPERATIONCODE = 'OCCPLSTN',@MACHINECODE = 'MCCPLSTN',@BARCODE = '2906741153AB00007396M07',@RETURNVALUE = @RETURNVALUE OUT
	SELECT @RETURNVALUE

	SELECT * FROM MACHINEMST
	SELECT * FROM OPERATIONMST

	EXEC [ASSY_PROC_COUPLING] @CONDITION = 'VALIDATE_SERVO',@FG_PART_NO = '32067870',@PROFITCENTERCODE = '0021',@MACHINECODE = 'MCCPLSTN',@OPERATIONCODE = 'OCCPLSTN',@BARCODE = '3204880943GB00000002P2',@LINECODE = 'P2'
	*/
	BEGIN TRY
		SET NOCOUNT ON;
		DECLARE @LINECODE_OF_BARCODE VARCHAR(5) = '', @TORQUE_1 NUMERIC(10,5) = 0, @TORQUE_2 NUMERIC (10,5) = 0, @ISTORQUE1OK BIT, @ISTORQUE2OK BIT, @PART_TYPE VARCHAR(10) = '',
		@FAILCOUNTDEFINED INT = 0, @FAILCOUNT INT = 0, @TEMPSCANNEDPARTTYPE VARCHAR(15), @TEMPRUNNINGPARTTYPE VARCHAR(15), @TEMPOPERATIONTYPE VARCHAR(20), @LINETYPECODE VARCHAR(20) = '',
		@FINALVIEWING_OPERATIONCODE VARCHAR(10), @OPERATIONSEQNO INT, @OPERATIONNAME VARCHAR(50), @EXECQUERY VARCHAR(MAX) = '', @LINKSERVERNAME VARCHAR(200) = '', @INCORRECTMSG VARCHAR(200),
		@PARTNUMBER VARCHAR(20) = NULL, @RUNNINGDATECODE CHAR(4) = ''
		
		DECLARE @P_PART_LOCAL VARCHAR(30) = '', @P_CUST_PART_LOCAL VARCHAR(30) = '', @P_DATE_CODE VARCHAR(10) = ''

		SET @PARTNUMBER = @FG_PART_NO
		
		SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL WITH (NOLOCK) 
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

		DECLARE @ISTMCVALIDATION INT = 0
		--RESET SERVO AND TMC SCANNED BARCODE AFTER USER PRESS REFRESH BUTTON OR SCAN RESET BARCODE		
		IF @CONDITION = 'RESET_BOTH_SCANNED_BARCODE'
		BEGIN 
			-- DELETE THE RECORD FROM TEMP TABLE..
			DELETE FROM ASSY_COUPLING_TEMP WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE			
			UPDATE ASSY_SCAN_OK SET ISSCAN = 0 WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE

			IF EXISTS(SELECT 1 FROM PARAMETER_MST(NOLOCK) WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'ISTORQUEONCOUPLING'  AND PARAMETER_C2 = @LINECODE AND WH_CODE = @PROFITCENTERCODE AND PARAMETER_VALUE = '1')
			BEGIN
				UPDATE ASSY_COUPLINGTORQUESTATUS SET IS_TORQUE1_OK = 0, IS_TORQUE2_OK = 0, TORQUE_1 = 0.0, TORQUE_2 = 0.0 WHERE LINECODE = @LINECODE AND PROFITCENTRECODE = @PROFITCENTERCODE
			END
			
			SET @RETURNINT = 1
			SET @RETURNVALUE = 'SUCCESS'
			RETURN
		END
		ELSE IF @CONDITION = 'VALIDATE_SERVO'
		BEGIN			
			IF EXISTS 
			(
				SELECT TOP 1 1 FROM ASSY_COUPLING_TEMP WITH (NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND CHILD_BARCODE = @BARCODE AND PART_TYPE = 'SERVO'
			)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'SERVO_ALREADY_SCANNED_SCAN_TMC_BARCODE'

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				RETURN
			END
			--CHECK SCANNED BARCODE HAVING CORRECT LINE CODE OR NOT
			IF CHARINDEX(@LINECODE,@BARCODE) = 0
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'BARCODE_HAVING_DIFFERENT_LINE_CODE'

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				RETURN
			END
			--GET PARTNO,DATECODE FROM BARCODE
			SELECT @CHILD_PART_NO = PARTNO,@DATECODE = DATECODE FROM ASSY_FN_GET_BARCODEPARTS_FROM_BARCODE(@PROFITCENTERCODE,@LINECODE,@BARCODE)

			IF ISNULL(@CHILD_PART_NO,'') = ''
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'BARCODE IS NOT PRINTED.'

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				RETURN
			END

			IF NOT EXISTS 
			(
				SELECT TOP 1 1 FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
					AND ASSY_PARTNO = @FG_PART_NO AND SERVO_PARTNO = @CHILD_PART_NO AND ASSY_MODE IN ('PRODUCTION','REWORK')
			)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'INVALID_CHILD_PART_AGAINST_FG'

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				RETURN
			END
			--THIS SERVO PART SHOULD NOT BE COUPLED WITH ANY OTHER STMC PART..		
			IF EXISTS
			(
				SELECT TOP 1 1 FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND CHILD_BARCODE = @BARCODE AND PART_TYPE = 'SERVO'
			) 
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'PART_HAS_ALREADY_BEEN_COUPLED'

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				RETURN
			END 
			--CHECK SERVO BARCODE HAS BEEN REWORKED AND MAEKED AS FAILED
			IF EXISTS
			(
				SELECT TOP 1 1 FROM ASSY_STMC_REWORK WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND CHILDBARCODE = @BARCODE
					AND ISNULL(STATUS,'') = 'FAIL' AND ISNULL(PARTTYPE,'') = 'SERVO'
			)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'PART_HAS_MARKED_AS_SCRAP'

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				RETURN
			END
				
			--CHECK PART HAS ALREADY PROCESSED IN TALLY CHART
			IF EXISTS
			( 
			SELECT TOP 1 1 FROM ASSY_TALLYCHARTSTATUSDATA WITH (NOLOCK) WHERE BARCODE = @BARCODE AND (ISNULL(ASSY_AUTH,0) = 1 OR ISNULL(NOTPROCESSEDSTATUS,'' ) <> '')
				AND LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
			)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'PART_HAS_ALREADY_PROCESSED_IN_TALLYCHART'

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				RETURN
			END	
			----------CHECK A PART HAS CLEARED FROM PREVIOUS STATION-----------------------			
			DECLARE @PREVMACHINECODE VARCHAR(20) = NULL,@CHECK_BARCODE VARCHAR (100) = ''
			EXEC ASSY_PROC_GET_PREVIOUS_MACHINECODE @LINECODE = @LINECODE,@MACHINECODE = @MACHINECODE,@PARTNUMBER = @PARTNUMBER
			,@PREVMACHINECODE = @PREVMACHINECODE OUTPUT
			--SELECT @PREVMACHINECODE
			SELECT @CHECK_BARCODE = ISNULL(BARCODE,'') FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE AND BARCODE = @BARCODE AND MACHINECODE = @PREVMACHINECODE
						
			IF @CHECK_BARCODE = ''
			BEGIN
				SELECT @CHECK_BARCODE = ISNULL(BARCODE,'') FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE AND BARCODE = @BARCODE AND MACHINECODE = @PREVMACHINECODE AND ISNULL(ISTALLYCHARTAPPROVED,0) = 0
			END
			IF @CHECK_BARCODE = ''						
			BEGIN											
				SELECT TOP 1 @OPERATIONSEQNO = L.OPERATIONSEQNO FROM ROUTINGCONFIGLINEWISE L WITH (NOLOCK) 
					INNER JOIN ROUTINGCONFIGPARTWISE P WITH (NOLOCK) 
						ON L.OPERATIONCODE = P.OPERATIONCODE AND L.MACHINECODE = P.MACHINECODE 
					WHERE L.LINECODE = @LINECODE
						AND P.PARTNO = (SELECT TOP 1 ASSY_PARTNO FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE)
							AND L.TRACEABILITY = 1 AND P.TRACEABILITY = 1 AND L.MACHINECODE = @PREVMACHINECODE AND P.MACHINECODE = @PREVMACHINECODE
								-- ADDED BY RASHID FOR HANDLING ENGRAVING STATION ON 10TH SEP 2016
								AND ISNULL(L.ENGRAVING,0) = 0 AND ISNULL(P.ENGRAVING,0) = 0
					ORDER BY L.OPERATIONSEQNO 					
					 
				SELECT TOP 1 @LINETYPECODE = LTM.LINETYPENAME FROM LINEMST LM WITH (NOLOCK) 
					INNER JOIN LINETYPEMST LTM WITH (NOLOCK) ON LM.LINETYPECODE = LTM.LINETYPECODE WHERE LM.LINECODE = @LINECODE

				SET @INCORRECTMSG = (SELECT TOP 1 MACHINENAME FROM MACHINEMST WITH (NOLOCK) WHERE MACHINECODE = @PREVMACHINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE)
				SET @RETURNVALUE = 'NOT_PROCESSED_FROM_|'+@INCORRECTMSG
													
				SET @INCORRECTMSG = 'NOT PROCESSED FROM'+@INCORRECTMSG
				SET @RETURNINT = 1

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				RETURN
			END
			-------------------------------------------
			--CHECK PART HAS BEEN ONLY SCANNED BUT NOT TESTED
			SET @CHECK_BARCODE = ''
			
			SELECT @CHECK_BARCODE = ISNULL(BARCODE,'') FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE AND BARCODE = @BARCODE AND MACHINECODE = @PREVMACHINECODE AND ISNULL(STATUS,'') = ''
						
			IF @CHECK_BARCODE = ''
			BEGIN
				SELECT @CHECK_BARCODE = ISNULL(BARCODE,'') FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE AND BARCODE = @BARCODE AND MACHINECODE = @PREVMACHINECODE AND ISNULL(ISTALLYCHARTAPPROVED,0) = 0 AND ISNULL(STATUS,'') = '' 
			END
								
			IF @CHECK_BARCODE <> ''
			BEGIN
				SELECT TOP 1 @OPERATIONSEQNO = L.OPERATIONSEQNO FROM ROUTINGCONFIGLINEWISE L WITH (NOLOCK) 
					INNER JOIN ROUTINGCONFIGPARTWISE P WITH (NOLOCK) 
						ON L.OPERATIONCODE = P.OPERATIONCODE AND L.MACHINECODE = P.MACHINECODE 
					WHERE L.LINECODE = @LINECODE
						AND P.PARTNO = (SELECT TOP 1 ASSY_PARTNO FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE)
							AND L.TRACEABILITY = 1 AND P.TRACEABILITY = 1 AND L.MACHINECODE = @PREVMACHINECODE AND P.MACHINECODE = @PREVMACHINECODE
								-- ADDED BY RASHID FOR HANDLING ENGRAVING STATION ON 10TH SEP 2016
								AND ISNULL(L.ENGRAVING,0) = 0 AND ISNULL(P.ENGRAVING,0) = 0
									ORDER BY L.OPERATIONSEQNO
					 
				SELECT TOP 1 @LINETYPECODE = LTM.LINETYPENAME FROM LINEMST LM WITH (NOLOCK) 
					INNER JOIN LINETYPEMST LTM WITH (NOLOCK) ON LM.LINETYPECODE = LTM.LINETYPECODE WHERE LM.LINECODE = @LINECODE

				SET @INCORRECTMSG = (SELECT TOP 1 MACHINENAME FROM MACHINEMST WITH (NOLOCK) WHERE MACHINECODE = @PREVMACHINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE)
										
				--SET @RETURNVALUE = 'NOT_CLEARED_FROM_|'+@INCORRECTMSG		
				SET @RETURNVALUE = 'THIS_BARCODE_HAS_BEEN_ONLY_SCANNED_AND_NOT_TESTED_|'+@INCORRECTMSG
				SET @RETURNINT = 1

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				RETURN
			END 	
			--------------------------------------------
			SET @CHECK_BARCODE = ''
			
			SELECT @CHECK_BARCODE = ISNULL(BARCODE,'') FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE AND BARCODE = @BARCODE AND MACHINECODE = @PREVMACHINECODE AND ISNULL(STATUS,'') = 'PS' 
						
			IF @CHECK_BARCODE = ''
			BEGIN
				SELECT @CHECK_BARCODE = ISNULL(BARCODE,'') FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE AND BARCODE = @BARCODE AND MACHINECODE = @PREVMACHINECODE AND ISNULL(ISTALLYCHARTAPPROVED,0) = 0 AND ISNULL(STATUS,'') = 'PS' 
			END

			IF @CHECK_BARCODE = ''
			BEGIN
				SELECT TOP 1 @OPERATIONSEQNO = L.OPERATIONSEQNO FROM ROUTINGCONFIGLINEWISE L WITH (NOLOCK) 
					INNER JOIN ROUTINGCONFIGPARTWISE P WITH (NOLOCK) 
						ON L.OPERATIONCODE = P.OPERATIONCODE AND L.MACHINECODE = P.MACHINECODE 
							WHERE L.LINECODE = @LINECODE
								AND P.PARTNO = (SELECT TOP 1 ASSY_PARTNO FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE)
									AND L.TRACEABILITY = 1 AND P.TRACEABILITY = 1 AND L.MACHINECODE = @PREVMACHINECODE AND P.MACHINECODE = @PREVMACHINECODE
										-- ADDED BY RASHID FOR HANDLING ENGRAVING STATION ON 10TH SEP 2016
										AND ISNULL(L.ENGRAVING,0) = 0 AND ISNULL(P.ENGRAVING,0) = 0
											ORDER BY L.OPERATIONSEQNO
					 
				SELECT TOP 1 @LINETYPECODE = LTM.LINETYPENAME FROM LINEMST LM WITH (NOLOCK) 
					INNER JOIN LINETYPEMST LTM WITH (NOLOCK) ON LM.LINETYPECODE = LTM.LINETYPECODE WHERE LM.LINECODE = @LINECODE

				SET @INCORRECTMSG = (SELECT TOP 1 MACHINENAME FROM MACHINEMST WITH (NOLOCK) WHERE MACHINECODE = @PREVMACHINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE)

				SET @RETURNVALUE = 'NOT_CLEARED_FROM_|'+@INCORRECTMSG
				SET @RETURNINT = 1

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				RETURN
			END 	

			----CHECK FOR WIP LIMIT
			DECLARE @RETURNVALUEWIP VARCHAR(200), @RETURNINTWIP INT
			EXEC ASSY_PROC_WIP_MANAGE @CONDITION = 'VALIDATE_WIP',@LINECODE = @LINECODE,@MACHINECODE = @MACHINECODE,@BARCODE = @BARCODE,@PROFITCENTERCODE = @PROFITCENTERCODE 
				,@RETURNVALUE = @RETURNVALUEWIP OUT,@RETURNINT = @RETURNINTWIP OUT
			
			IF RTRIM(LTRIM(@RETURNVALUEWIP)) = 'WIP_LIMIT_HAS_REACHED'
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'WIP_LIMIT_HAS_REACHED'

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				RETURN
			END

			--IF EXISTS
			--(
			--	SELECT DISTINCT 1 FROM ASSY_SCAN_OK WITH (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE AND STATIONCODE = '1'
			--)
			--BEGIN
			--	UPDATE ASSY_SCAN_OK SET ISSCAN = 1,BARCODE = @BARCODE WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE AND STATIONCODE = '1'
			--END
			--ELSE
			--BEGIN
			--	INSERT INTO ASSY_SCAN_OK(LINECODE,OPERATIONCODE,STATIONCODE,BARCODE,ISSCAN,MACHINECODE)
			--	SELECT @LINECODE,@OPERATIONCODE,'1',@BARCODE,1,@MACHINECODE
			--END

			IF EXISTS
			(
				SELECT TOP 1 1 FROM ASSY_COUPLING_TEMP WITH (NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE 
					AND LINECODE = @LINECODE AND PART_TYPE = 'SERVO'
			)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = @BARCODE + '- OLD_SERVO_BARCODE_ALREADY_FOUND.REFRESH_DATA.'

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				RETURN
			END
			
			--HOLD A RECORD IN TEMP TABLE..
			IF NOT EXISTS
			( 
				SELECT 1 CHILD_BARCODE FROM ASSY_COUPLING_TEMP WITH (NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
					AND CHILD_BARCODE = @BARCODE AND PART_TYPE = 'SERVO'
			)
			BEGIN
				INSERT INTO ASSY_COUPLING_TEMP(PROFITCENTRECODE,LINECODE,STMC_PART_NO,CHILD_PART_NO,PART_TYPE,MACHINE_CODE,OPERATION_CODE,TORQUE_1,TORQUE_2,ENT_DT,CHILD_BARCODE,ENT_BY)
				VALUES(@PROFITCENTERCODE,@LINECODE,@FG_PART_NO,@CHILD_PART_NO,'SERVO',@MACHINECODE,@OPERATIONCODE,@TORQUE_1,@TORQUE_2,GETDATE(),@BARCODE,@USERID)
			END
			ELSE
			BEGIN
				UPDATE ASSY_COUPLING_TEMP SET ENT_DT = GETDATE(),ENT_BY = @USERID
					WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND CHILD_BARCODE = @BARCODE AND PART_TYPE = 'SERVO'
			END
			
			SET @RETURNVALUE = 'SCANNED_SUCCESSFULLY'
			SET @RETURNINT = 1

			-- SCANNING LOG BY RS ON 20170913
			INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
			SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

			RETURN
		END

		ELSE IF @CONDITION = 'VALIDATE_TMC'
		BEGIN 
			IF NOT EXISTS
			(
				SELECT TOP 1 1 FROM ASSY_COUPLING_TEMP WITH (NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND PART_TYPE = 'SERVO'
			)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'FIRST_SCAN_SERVO_BARCODE'

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				RETURN
			END
			
			IF EXISTS
			(
				SELECT TOP 1 1 FROM ASSY_COUPLING_TEMP WITH (NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE	AND LINECODE = @LINECODE AND CHILD_BARCODE = @BARCODE AND PART_TYPE = 'TMC'
			)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'TMC_ALREADY_SCANNED_SCAN_QC_OK_BARCODE'

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				RETURN
			END
						
			IF NOT EXISTS 
			(
				SELECT TOP 1 1 FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
					AND ASSY_PARTNO = @FG_PART_NO AND TMC_PARTNO = @CHILD_PART_NO AND ASSY_MODE IN ('PRODUCTION','REWORK')
			)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'INVALID_CHILD_PART_AGAINST_FG'

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				RETURN
			END
			--THIS SERVO PART SHOULD NOT BE COUPLED WITH ANY OTHER STMC PART..		
			IF EXISTS
			(
				SELECT TOP 1 1 FROM ASSY_COUPLINGDETAILS (NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND CHILD_BARCODE = @BARCODE AND PART_TYPE = 'TMC'
			) 
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'PART_HAS_ALREADY_BEEN_COUPLED'

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				RETURN
			END
			--CHECK SERVO BARCODE HAS BEEN REWORKED AND MARKED AS FAILED
			IF EXISTS
			(
				SELECT TOP 1 1 FROM ASSY_STMC_REWORK WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND CHILDBARCODE = @BARCODE
					AND ISNULL(STATUS,'') = 'FAIL' AND ISNULL(PARTTYPE,'') = 'TMC'
			)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'PART_HAS_MARKED_AS_SCRAP'

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				RETURN
			END

			--CHECK PART HAS BEEN ENGRAVED OR NOT
			--CHECK ROUTING IS ENABLE FOR THIS LINE
			IF EXISTS
			(
				SELECT 1 FROM ROUTINGCONFIGLINEWISE WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND MACHINECODE = @ENGRAVING_MACHINECODE
					AND OPERATIONCODE = @ENGRAVING_OPERATIONCODE AND ISNULL(OPERATIONREQUIRED,0) = 1 AND ISNULL(TRACEABILITY,0) = 1 AND ISNULL(ENGRAVING,0) = 1
			)
			BEGIN
				--CHECK ROUTING IS ENABLE FOR THIS PART
				IF EXISTS
				(
					SELECT 1 FROM ROUTINGCONFIGPARTWISE WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND MACHINECODE = @ENGRAVING_MACHINECODE
						AND OPERATIONCODE = @ENGRAVING_OPERATIONCODE AND ISNULL(OPERATIONREQUIRED,0) = 1 AND ISNULL(TRACEABILITY,0) = 1 AND ISNULL(ENGRAVING,0) = 1
							AND PARTNO = @FG_PART_NO
				)
				BEGIN
					--CHECK TMC BARCODE HAS BEEN ENGRAVED OR NOT
					IF NOT EXISTS
					(
						SELECT 1 FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND MACHINECODE = @ENGRAVING_MACHINECODE
							AND OPERATIONCODE = @ENGRAVING_OPERATIONCODE AND BARCODE = @BARCODE	AND ISNULL(STATUS,'') = 'PS' AND ISNULL(ISTALLYCHARTAPPROVED,0) = 0
					)
					BEGIN
						IF NOT EXISTS
						(
							SELECT 1 FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND MACHINECODE = @ENGRAVING_MACHINECODE
								AND OPERATIONCODE = @ENGRAVING_OPERATIONCODE AND BARCODE = @BARCODE	AND ISNULL(STATUS,'') = 'PS'
						)
						BEGIN
							SET @RETURNINT = 1
							SET @RETURNVALUE = 'PART_HAS_NOT_ENGRAVED'

							-- SCANNING LOG BY RS ON 20170913
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

							RETURN
						END
					END
				END
				ELSE
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'TMC_PART_WISE_ROUTING_IS_NOT_DEFINED_FOR_ENGRAVING'

					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

					RETURN
				END
			END
			--GET THE LINE CODE FROM THE BARCODE..

			-- VALIDATING RUNNING CUSTOMER PART NUMBER BY SET PARAMETER TABLE (ASSY_RUNNINGPART) BY RS ON 20180227
			IF EXISTS
			(
				SELECT 1 FROM ASSY_LINEASSYENGRAVING WITH (NOLOCK) WHERE LINECODE = @LINECODE AND MACHINECODE = @ENGRAVING_MACHINECODE AND OPERATIONCODE = @ENGRAVING_OPERATIONCODE
					AND PROFITCENTERCODE = @PROFITCENTERCODE AND BARCODE = @BARCODE
			)
			BEGIN
				SELECT TOP 1 @P_CUST_PART_LOCAL = CUSTOMERPARTNO FROM ASSY_RUNNINGPART WITH (NOLOCK)
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

				IF ISNULL(@P_CUST_PART_LOCAL,'') = ''
				BEGIN
					SELECT TOP 1 @P_CUST_PART_LOCAL = CLM.CUSTOMERPARTNO
							FROM ASSY_COUPLING_LABELINFO_MST CLM WITH (NOLOCK) INNER JOIN ASSY_RUNNINGPART RP WITH (NOLOCK)
								ON CLM.PROFITCENTERCODE = RP.PROFITCENTERCODE AND CLM.PARTNO = RP.ASSY_PARTNO
									WHERE CLM.PARTNO = @FG_PART_NO AND CLM.PROFITCENTERCODE = @PROFITCENTERCODE AND RP.LINECODE = @LINECODE AND CLM.LABELDATANAME = 'ISDATECODE_ENGRAVING'
				END

				IF NOT EXISTS
				(
					SELECT 1 FROM ASSY_LINEASSYENGRAVING WITH (NOLOCK) WHERE LINECODE = @LINECODE AND MACHINECODE = @ENGRAVING_MACHINECODE AND OPERATIONCODE = @ENGRAVING_OPERATIONCODE
						AND PROFITCENTERCODE = @PROFITCENTERCODE AND BARCODE = @BARCODE AND CUSTOMERPARTNO = @P_CUST_PART_LOCAL
				)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'PART_HAS_ENGRAVED_BUT_DIFFERENT_CUSTOMER'

					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

					RETURN
				END
			END

			-- ADD BY RASHID ON 09TH MAY 2016
			-- IS BARCODE PACKED OR NOT IN PACKAGING?
			--SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL WITH (NOLOCK) 
			--		WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
			SET @EXECQUERY = ''
			SET @EXECQUERY = @LINKSERVERNAME + '.DBO.SKIDBARCODEDETAIL WITH (NOLOCK) WHERE WH_CODE = ''' + @PROFITCENTERCODE + '''
			AND PARTBARCODE = ''' + @BARCODE + ''''
			--SELECT @EXECQUERY

			SET @EXECQUERY = 'SELECT PARTBARCODE FROM ' + @EXECQUERY
			DECLARE @PACKAGING AS TABLE
			(
				PACKEDBARCODE VARCHAR(60)
			)

			INSERT INTO @PACKAGING(PACKEDBARCODE)
			EXEC (@EXECQUERY)
				
			IF EXISTS (SELECT 1 FROM @PACKAGING)
			BEGIN
				SET @RETURNVALUE = 'PART ALREADY PACKED IN PACKAGING,CAN NOT COUPLE.'
				SET @RETURNINT = 0

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				RETURN
			END
						
			SELECT TOP 1 @ISTMCVALIDATION = ISNULL(ISTMCVALIDATIONOFF,0) FROM LINEMST (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
			--IF CHARINDEX('M4',@BARCODE ) = 0
			IF (UPPER(LEFT(RIGHT(@BARCODE,11),1)) ! = 'M')
			BEGIN
				IF @ISTMCVALIDATION = 1
				BEGIN
					SET @LINECODE_OF_BARCODE = RIGHT(@BARCODE,3)
					--CHECK IF THE TMC PART HAS BEEN PASSED FROM PARTICULAR LINE
					--SELECT @LINKSERVERNAME = LINKSERVERNAME+'.'+DATABASENAME FROM ASSY_LINKSERVER_DTL (NOLOCK) 
					--	WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
					SET @EXECQUERY = ''
					SET @EXECQUERY = @LINKSERVERNAME+'.DBO.ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE LINECODE = '''+@LINECODE_OF_BARCODE+''' 
					AND PROFITCENTERCODE = '''+@PROFITCENTERCODE+'''
					AND MACHINECODE = DBO.ASSY_FN_GET_PARAMETER_VALUE(''ASSLINE'',''FINALVIEWING'',''QCSTATION_MACHINECODE'','''+@PROFITCENTERCODE+''')
					AND BARCODE = '''+@BARCODE+'''
					AND ISNULL(STATUS,'''') = ''PS'' ORDER BY RESULTTIMESTAMP DESC'
					--SELECT @EXECQUERY
					/*
						CHANGE BY RS 20171211 SELECT TOP 1 ORDER BY RESULTTIMESTAMP DESC
					*/
					SET @EXECQUERY = 'SELECT TOP 1 STATUS FROM ' + @EXECQUERY

					DECLARE @STATUS AS TABLE
					(
						STATUSDATA VARCHAR(20)
					)
				
					INSERT INTO @STATUS(STATUSDATA)
					EXEC (@EXECQUERY)
				
					IF NOT EXISTS (SELECT 1 FROM @STATUS)
					BEGIN
						SET @RETURNVALUE = 'PART_HAS_NOT_PASSED_FROM_TMC_LINE'

						-- SCANNING LOG BY RS ON 20170913
						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

						RETURN
					END

					IF(SELECT ISNULL(STATUSDATA,'') FROM @STATUS)<>'PS'
					BEGIN
						SET @RETURNVALUE = 'PART_HAS_NOT_PASSED_FROM_TMC_LINE'

						-- SCANNING LOG BY RS ON 20170913
						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

						RETURN	
					END	
				END							 			
			END

			IF EXISTS
			(
				SELECT TOP 1 1 FROM ASSY_COUPLING_TEMP WITH (NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND PART_TYPE = 'TMC'
			)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'OLD_TMC_BARCODE_ALREADY_FOUND.REFRESH_DATA.'

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				RETURN
			END

			--SINCE STATUS IS SUCCESS INSERT A RECORD IN ASSY_SCAN_OK TABLE.
			IF EXISTS
			(
				SELECT DISTINCT 1 FROM ASSY_SCAN_OK (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE AND STATIONCODE = '2'
			)
			BEGIN
				UPDATE ASSY_SCAN_OK SET ISSCAN = 1,BARCODE = @BARCODE WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE AND STATIONCODE = '2'
			END
			ELSE
			BEGIN
				INSERT INTO ASSY_SCAN_OK(LINECODE,OPERATIONCODE,STATIONCODE,BARCODE,ISSCAN,MACHINECODE)
				SELECT @LINECODE,@OPERATIONCODE,'2',@BARCODE,1,@MACHINECODE
			END
		 
			--HOLD A RECORD IN TEMP TABLE..
			IF NOT EXISTS
			( 
				SELECT 1 CHILD_BARCODE FROM ASSY_COUPLING_TEMP (NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND CHILD_BARCODE = @BARCODE AND PART_TYPE = 'TMC'
			)
			BEGIN
				INSERT INTO ASSY_COUPLING_TEMP(PROFITCENTRECODE,LINECODE,STMC_PART_NO,CHILD_PART_NO,PART_TYPE,MACHINE_CODE,OPERATION_CODE,TORQUE_1,TORQUE_2,ENT_DT,CHILD_BARCODE,ENT_BY)
				VALUES (@PROFITCENTERCODE,@LINECODE,@FG_PART_NO,@CHILD_PART_NO,'TMC',@MACHINECODE,@OPERATIONCODE,@TORQUE_1,@TORQUE_2,GETDATE(),@BARCODE,@USERID)		
			END 
			ELSE
			BEGIN
				UPDATE ASSY_COUPLING_TEMP SET ENT_DT = GETDATE(),ENT_BY = @USERID 
					WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND CHILD_BARCODE = @BARCODE AND PART_TYPE = 'TMC'
			END
			
			SET @RETURNVALUE = 'SCANNED_SUCCESSFULLY' 
			SET @RETURNINT = 1
			
			-- SCANNING LOG BY RS ON 20170913
			INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
			SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

			----NEED TO CHECK IF TORQUE HAS TO BE MEASURED FOR THIS TMC PART..
			--IF ((SELECT TORQUE FROM ROUTINGCONFIGPARTWISE WHERE PARTNO = @CHILD_PART_NO AND OPERATIONCODE = @OPERATIONCODE) = 1)
			--BEGIN
			-- --TORQUE FLAG IS ON.. CHECK IF THE TORQUE HAS BEEN MEASURED.. IF NOT,RETURN WITH MESSAGE PLEASE MEASURE TORQUE..
			-- SELECT @TORQUE_1 = TORQUE_1,@TORQUE_2 = TORQUE_2,@ISTORQUE1OK = IS_TORQUE1_OK,
			-- @ISTORQUE2OK = IS_TORQUE2_OK FROM ASSY_COUPLINGTORQUESTATUS WHERE LINECODE = @LINECODE
		 
			-- IF(@TORQUE_1 = 0)
			-- BEGIN
			--   SET @RETURNVALUE = 'WAITING_FOR_TORQUE_1'
			--   RETURN
			-- END
		 
			-- IF(@TORQUE_2 = 0)
			-- BEGIN
			--   SET @RETURNVALUE = 'WAITING_FOR_TORQUE_2'
			--   RETURN
			-- END
		 
			-- IF(@ISTORQUE1OK <> 1)
			-- BEGIN
			--   SET @RETURNVALUE = 'TORQUE1_NOT_OK'
			--   RETURN
			-- END
		 
			-- IF(@ISTORQUE2OK <> 1)
			-- BEGIN
			--   SET @RETURNVALUE = 'TORQUE2_NOT_OK'
			--   RETURN
			-- END
			--END		

			RETURN		 
		END
		
		ELSE IF @CONDITION = 'INSERT_COUPLING_BARCODE'
		BEGIN 
			DECLARE @PRODUCTIONORDERNO VARCHAR(40)
			SELECT TOP 1 @USERID = ISNULL(CREATEDBY,''), @PRODUCTIONORDERNO = PRODUCTIONORDERNO 
			FROM ASSY_RUNNINGPART (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

			INSERT INTO ASSY_COUPLINGDETAILS 
			(
				PROFITCENTRECODE,LINECODE,STMC_PART_NO,CHILD_PART_NO,PART_TYPE,MACHINE_CODE,OPERATION_CODE,TORQUE_1,TORQUE_2,ENT_DT,ENT_BY,CHILD_BARCODE,FG_BARCODE,DATECODE
			)
			SELECT PROFITCENTRECODE,LINECODE,STMC_PART_NO,CHILD_PART_NO,PART_TYPE,MACHINE_CODE,OPERATION_CODE,TORQUE_1,TORQUE_2,ENT_DT,@USERID,CHILD_BARCODE,@BARCODE,@DATECODE
				FROM ASSY_COUPLING_TEMP WITH (NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
				
			--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
			INSERT INTO ASSY_LINEASSYSTATUS_RUNNING
			(
				PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,BARCODE,DATECODE,PARTNO,ACTIVE,STATIONCODE,SCANTIMESTAMP,USERID,RESULTTIMESTAMP,STATUS,PRODUCTIONORDERNO
			)
			SELECT @PROFITCENTERCODE,@LINECODE,@MACHINECODE,@OPERATIONCODE,@BARCODE,@DATECODE,@FG_PART_NO,1,'1',GETDATE(),@USERID,GETDATE(),'PS',@PRODUCTIONORDERNO
			
			--DELETE THE RECORD FROM TEMP TABLE..
			DELETE FROM ASSY_COUPLING_TEMP WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

			SET @RETURNVALUE = 'SUCCESS'

			-- INSERT COUPLING DATA INTO CENTRAL SERVER
			-- START -- ADDED BY RASHID ON 23RD JAN 2017 -----
			--SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE	

			SET @EXECQUERY = ''
			SET @EXECQUERY = '
			IF EXISTS (SELECT 1 FROM ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + ''')
			BEGIN
				INSERT INTO ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS_HISTORY (PROFITCENTRECODE, LINECODE, STMC_PART_NO, CHILD_PART_NO, PART_TYPE, MACHINE_CODE, OPERATION_CODE, TORQUE_1, TORQUE_2, ENT_DT, ENT_BY, FG_BARCODE, CHILD_BARCODE, DATECODE, HIS_ENT_DT, HIS_ENT_BY)
				SELECT PROFITCENTRECODE, LINECODE, STMC_PART_NO, CHILD_PART_NO, PART_TYPE, MACHINE_CODE, OPERATION_CODE, TORQUE_1, TORQUE_2, ENT_DT, ENT_BY, FG_BARCODE, CHILD_BARCODE, DATECODE, GETDATE(), ''' + ISNULL(@USERID, '''') + ''' FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + '''

				DELETE FROM ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS WHERE PROFITCENTRECODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + '''
								
				IF NOT EXISTS (SELECT 1 FROM ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + ''')
				BEGIN
					INSERT INTO ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS (PROFITCENTRECODE, LINECODE, STMC_PART_NO, CHILD_PART_NO, PART_TYPE, MACHINE_CODE, OPERATION_CODE, TORQUE_1, TORQUE_2, ENT_DT, ENT_BY, FG_BARCODE, CHILD_BARCODE, DATECODE)
					SELECT PROFITCENTRECODE, LINECODE, STMC_PART_NO, CHILD_PART_NO, PART_TYPE, MACHINE_CODE, OPERATION_CODE, TORQUE_1, TORQUE_2, ENT_DT, ENT_BY, FG_BARCODE, CHILD_BARCODE, DATECODE FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + '''
				END
			END
			ELSE
			BEGIN
				INSERT INTO ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS (PROFITCENTRECODE, LINECODE, STMC_PART_NO, CHILD_PART_NO, PART_TYPE, MACHINE_CODE, OPERATION_CODE, TORQUE_1, TORQUE_2, ENT_DT, ENT_BY, FG_BARCODE, CHILD_BARCODE, DATECODE)
				SELECT PROFITCENTRECODE, LINECODE, STMC_PART_NO, CHILD_PART_NO, PART_TYPE, MACHINE_CODE, OPERATION_CODE, TORQUE_1, TORQUE_2, ENT_DT, ENT_BY, FG_BARCODE, CHILD_BARCODE, DATECODE FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + '''
			END
			'
			PRINT @EXECQUERY
			EXEC (@EXECQUERY)
			-- END -- ADDED BY RASHID ON 23RD JAN 2017 -----
			
			RETURN
		END
		
		ELSE IF @CONDITION = 'VALIDATE_ENGRAVING'
		BEGIN 
			--CHECK IF PART IS A VALID SERVO TYPE..
			SET @PART_TYPE = (SELECT ISNULL(MATERIAL_TP,'') FROM PRODUCT_MASTER WHERE SEWS_PART_NO = @CHILD_PART_NO)
		 
			IF(@PART_TYPE <> 'TMC')
			BEGIN
				SET @RETURNVALUE = 'PART_IS_NOT_TMC'
				RETURN
			END

			IF NOT EXISTS (SELECT TOP 1 1 FROM BOM_MASTER WHERE FG_PART_NO = @FG_PART_NO AND RM_PART_NO = @CHILD_PART_NO)
			BEGIN
				SET @RETURNVALUE = 'INVALID_CHILD_PART_AGAINST_FG'
				RETURN
			END
		 
			--CHECK IF THE RECORD IS NOT THERE IN SCAN OK..
			IF EXISTS (SELECT BARCODE FROM ASSY_SCAN_OK WHERE BARCODE = @BARCODE AND MACHINECODE = @MACHINECODE)
			BEGIN
				SET @RETURNVALUE = 'PART_ALREADY_SCANNED'
				RETURN
			END
		 
			--GET THE LINE CODE FROM THE BARCODE..
			SET @LINECODE_OF_BARCODE = (SELECT SUBSTRING(@BARCODE,(LEN(@BARCODE) - 2),3))
			--CHECK IF THE SERVO PART HAS BEEN PASSED FROM PREVIOUS STATIONS..
			IF NOT EXISTS (SELECT TOP 1 1 FROM ASSY_LINEASSYSTATUS_RUNNING WHERE LINECODE = @LINECODE_OF_BARCODE
			AND BARCODE = @BARCODE AND STATUS <> 'PS')
			BEGIN
				SET @RETURNVALUE = 'PART_ALREADY_ENGRAVED'
				RETURN	
			END
		 
			IF NOT EXISTS
			(
				SELECT DISTINCT 1 FROM PRODUCT_MASTER (NOLOCK) WHERE WAREHOUSE_CD = @PROFITCENTERCODE AND SEWS_PART_NO = @CHILD_PART_NO AND STS_CD = 0 AND PT_PART_TYPE = 
				(SELECT LT.LINETYPENAME FROM LINETYPEMST (NOLOCK) LT INNER JOIN LINEMST (NOLOCK) LM ON LT.LINETYPECODE = LM.LINETYPECODE WHERE LM.LINECODE = @LINECODE) 
			)
			BEGIN
				--SELECT 'PART_NOT_ACTIVE_IN_PRODUCT_MASTER'
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'PART_NOT_ACTIVE_IN_PRODUCT_MASTER'

				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE',@LINECODE = @LINECODE,@OPERATIONCODE = @OPERATIONCODE
					,@BARCODE = @BARCODE,@HMIMESSAGE = 'PART_NOT_ACTIVE_IN_PRODUCT_MASTER'
				END
				
				COMMIT TRAN
				RETURN
			END
			
			--CHECK PART HAS ALREADY SCRAPED IN TALLY CHART
			IF EXISTS
			( 
				SELECT TOP 1 1 FROM ASSY_TALLYCHARTSTATUSDATA (NOLOCK) WHERE BARCODE = @BARCODE AND ISNULL(ASSY_AUTH,0) = 1 AND LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
			)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'PART_HAS_ALREADY_PROCESSED_IN_TALLYCHART'
				COMMIT TRAN
				RETURN
			END	
		
			--THIS SERVO PART SHOULD NOT BE COUPLED WITH ANY OTHER STMC PART..
			IF EXISTS
			(
				SELECT TOP 1 1 FROM ASSY_COUPLINGDETAILS WHERE CHILD_PART_NO = @CHILD_PART_NO
			) 
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'PART_HAS_ALREADY_BEEN_COUPLED'
				RETURN
			END 
		
			SET @RETURNVALUE = 'SUCCESS' 
			--SINCE STATUS IS SUCCESS INSERT A RECORD IN ASSY_SCAN_OK TABLE.
			--INSERT INTO ASSY_SCAN_OK VALUES (@LINECODE,@MACHINECODE,@OPERATIONCODE,@STATIONCODE,@BARCODE,1)
		END
						
		ELSE IF @CONDITION = 'IS_JIG_INSIDE'
		BEGIN 
			IF ((SELECT TOP 1 IS_JIG_IN FROM ASSY_JIGMOVEMENT WITH (NOLOCK) WHERE PART_CODE = @CHILD_PART_NO AND LINECODE = @LINECODE AND PROFITCENTRECODE = @PROFITCENTERCODE) = 1)
			BEGIN
				SET @RETURNVALUE = 'JIG_INSIDE'
				RETURN
			END
		 
			SET @RETURNVALUE = 'JIG_OUTSIDE'
		END
	
		ELSE IF @CONDITION = 'GET_ALL_TYPE_FG_PARTS'
		BEGIN 

			SELECT DISTINCT SEWS_PART_NO AS 'STMC' FROM PRODUCT_MASTER (NOLOCK) 
				WHERE WAREHOUSE_CD = @PROFITCENTERCODE AND STS_CD = 0 AND ISNULL(MATERIAL_TP,'') = 'STMC'
					ORDER BY SEWS_PART_NO

			SELECT DISTINCT SEWS_PART_NO AS 'SERVO' FROM PRODUCT_MASTER (NOLOCK) 
				WHERE WAREHOUSE_CD = @PROFITCENTERCODE AND STS_CD = 0 AND ISNULL(MATERIAL_TP,'') = 'SERVO'
					ORDER BY SEWS_PART_NO

			SELECT DISTINCT SEWS_PART_NO AS 'TMC' FROM PRODUCT_MASTER (NOLOCK) 
				WHERE WAREHOUSE_CD = @PROFITCENTERCODE AND STS_CD = 0 AND ISNULL(MATERIAL_TP,'') = 'TMC'
					ORDER BY SEWS_PART_NO	
			RETURN
		END

		ELSE IF @CONDITION = 'PARTSCOUNT'
		BEGIN 
			DECLARE @PARTWISE INT = 0,@SHIFTWISE INT = 0
			SET @RUNNINGDATECODE = ''
			SELECT @RUNNINGDATECODE = ISNULL(DATECODE,'') FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE

			SELECT @PARTWISE = COUNT(*) FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK) 
				WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
						AND PARTNO = @FG_PART_NO 
						AND MACHINECODE = @MACHINECODE
						AND OPERATIONCODE = @OPERATIONCODE
						AND DATECODE = CASE ISNULL(@RUNNINGDATECODE,'') WHEN '' THEN @DATECODE ELSE @RUNNINGDATECODE END
						AND ISNULL(STATUS,'') = 'PS'
			
			SELECT @PARTWISE = ISNULL(@PARTWISE,0) + ISNULL(COUNT(*),0) FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) 
				WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
						AND PARTNO = @FG_PART_NO 
						AND MACHINECODE = @MACHINECODE
						AND OPERATIONCODE = @OPERATIONCODE
						AND DATECODE = CASE ISNULL(@RUNNINGDATECODE,'') WHEN '' THEN @DATECODE ELSE @RUNNINGDATECODE END
						AND ISNULL(STATUS,'') = 'PS'

			SELECT @SHIFTWISE = COUNT(*) FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK) 
				WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
						AND DATECODE = CASE ISNULL(@RUNNINGDATECODE,'') WHEN '' THEN @DATECODE ELSE @RUNNINGDATECODE END
						AND MACHINECODE = @MACHINECODE
						AND OPERATIONCODE = @OPERATIONCODE
						AND ISNULL(STATUS,'') = 'PS'

			SELECT @SHIFTWISE = ISNULL(@SHIFTWISE,0) + ISNULL(COUNT(*),0) FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) 
				WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
						AND DATECODE = CASE ISNULL(@RUNNINGDATECODE,'') WHEN '' THEN @DATECODE ELSE @RUNNINGDATECODE END
						AND MACHINECODE = @MACHINECODE
						AND OPERATIONCODE = @OPERATIONCODE
						AND ISNULL(STATUS,'') = 'PS'

			SELECT ISNULL(@PARTWISE,0) PARTWISE, ISNULL(@SHIFTWISE,0) SHIFTWISE

			SET @RETURNVALUE = 'SUCCESS'
			SET @RETURNINT = 1
			RETURN
		END

		ELSE IF @CONDITION = 'GETRUNNINGPART'
		BEGIN 
			DECLARE @ISCNCVALIDATIONOFF BIT = NULL
			SELECT TOP 1 @ISCNCVALIDATIONOFF = ISNULL(ISCNCVALIDATIONOFF,0) FROM LINEMST WITH (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE

			SELECT ASSY_PARTNO STMC_PARTNO, SERVO_PARTNO , TMC_PARTNO, PARTTYPE PART_TYPE, DATECODE , ISNULL(@ISCNCVALIDATIONOFF,0) ISCNCVALIDATION, CREATEDBY
				FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE

			SET @RETURNVALUE = 'SUCCESS'
			SET @RETURNINT = 1
			RETURN
		END

		ELSE IF @CONDITION = 'GETCOMPORT_ENGRAVINGSCNR'
		BEGIN 
			SELECT @RETURNVALUE = DBO.ASSY_FN_GET_COMPORT_NAME(@PROFITCENTERCODE,@LINECODE,@OPERATIONCODE,'ENGRAVINGRS232SCANNER','SERIALPORT')
			SET @RETURNINT = 1
			RETURN
		END

		ELSE IF @CONDITION = 'GETCOMPORT_ENGRAVINGMCH'
		BEGIN 
			SELECT @RETURNVALUE = DBO.ASSY_FN_GET_COMPORT_NAME(@PROFITCENTERCODE,@LINECODE,@OPERATIONCODE,'ENGRAVINGMACHINE','SERIALPORT')
			SET @RETURNINT = 1
			RETURN
		END

		ELSE IF @CONDITION = 'GETCOMPORT_COUPLINGMCH'
		BEGIN 
			SELECT @RETURNVALUE = DBO.ASSY_FN_GET_COMPORT_NAME(@PROFITCENTERCODE,@LINECODE,@OPERATIONCODE,'COUPLINGRS232SCANNER','SERIALPORT')
			SET @RETURNINT = 1
			RETURN
		END

		ELSE IF @CONDITION = 'GETPARAMETERS'
		BEGIN 
			SELECT RTRIM(LTRIM( PARAMETER_C1)) PARAMETER_C1,
				RTRIM(LTRIM( PARAMETER_C2)) PARAMETER_C2,
				RTRIM(LTRIM (PARAMETER_NM)) PARAMETER_NM,
				LTRIM(RTRIM(PARAMETER_VALUE)) PARAMETER_VALUE 
			FROM PARAMETER_MST (NOLOCK) 
				WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'ENGRAVING' AND WH_CODE = @PROFITCENTERCODE
			
			UNION
			
			SELECT RTRIM(LTRIM( PARAMETER_C1)) PARAMETER_C1,
				RTRIM(LTRIM( PARAMETER_C2)) PARAMETER_C2,
				RTRIM(LTRIM (PARAMETER_NM)) PARAMETER_NM,
				LTRIM(RTRIM(PARAMETER_VALUE)) PARAMETER_VALUE 
			FROM PARAMETER_MST (NOLOCK) 
				WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'COUPLING' AND WH_CODE = @PROFITCENTERCODE
           
			--SELECT ASSY_PARTNO STMC_PARTNO,SERVO_PARTNO,TMC_PARTNO,PARTTYPE PART_TYPE FROM ASSY_RUNNINGPART WHERE LINECODE = @LINECODE

			SET @RETURNVALUE = 'DATA SELECTED'
			SET @RETURNINT = 1
			RETURN
		END

		ELSE IF @CONDITION = 'RESETSCANOK'
		BEGIN 
			UPDATE ASSY_SCAN_OK SET ISSCAN = 0
				WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE
			--BIL--
			UPDATE ASSY_STATIONS_ZIG_IN_OUT_STATUS SET STATUSINOUT = 0
				WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND STATIONCODE = @STATIONCODE
			
			SET @RETURNVALUE = 'RESET SUCCESS'
			SET @RETURNINT = 1
			RETURN
		END

		ELSE IF @CONDITION = 'CHECKJIGSTATUS'
		BEGIN 
			DECLARE @ZIGIN BIT = NULL, @ISENGRAVESTARTCONFIRM BIT = NULL;

			SELECT @ZIGIN = ISNULL(STATUSINOUT,0) FROM ASSY_STATIONS_ZIG_IN_OUT_STATUS (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE

			IF @ZIGIN = 1
			BEGIN
				SELECT @ISENGRAVESTARTCONFIRM = ISNULL(ISENGRAVESTARTCONFIRM,0) FROM ASSY_ENGRAVE_START_CONFIRMATION (NOLOCK) WHERE LINECODE = @LINECODE
					AND OPERATIONCODE = @OPERATIONCODE AND PROFITCENTERCODE = @PROFITCENTERCODE
			END
			
			IF @ISENGRAVESTARTCONFIRM = 1
			BEGIN
				SET @RETURNVALUE = 1
				--UPDATE ASSY_ENGRAVE_START_CONFIRMATION SET ISENGRAVESTARTCONFIRM = 0 WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND PROFITCENTERCODE = @PROFITCENTERCODE
			END
			ELSE
				SET @RETURNVALUE = 0

			SET @RETURNINT = 1
			RETURN
		END

		ELSE IF @CONDITION = 'UPDATEENGRAVINGSTATUS'
		BEGIN 
		   SELECT TOP 1 @P_PART_LOCAL = ASSY_PARTNO, @P_CUST_PART_LOCAL = CUSTOMERPARTNO, @P_DATE_CODE = DATECODE FROM ASSY_RUNNINGPART WITH (NOLOCK)
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

			IF ISNULL(@P_CUST_PART_LOCAL,'') = ''
			BEGIN
				SELECT TOP 1 @P_CUST_PART_LOCAL = CLM.CUSTOMERPARTNO
						FROM ASSY_COUPLING_LABELINFO_MST CLM WITH (NOLOCK) INNER JOIN ASSY_RUNNINGPART RP WITH (NOLOCK)
							ON CLM.PROFITCENTERCODE = RP.PROFITCENTERCODE AND CLM.PARTNO = RP.ASSY_PARTNO
								WHERE CLM.PARTNO = @P_PART_LOCAL AND CLM.PROFITCENTERCODE = @PROFITCENTERCODE AND CLM.LABELDATANAME = 'ISDATECODE_ENGRAVING'
			END

			IF NOT EXISTS
			(
				SELECT 1 FROM ASSY_LINEASSYENGRAVING WITH (NOLOCK) WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE
					AND OPERATIONCODE = @OPERATIONCODE AND PROFITCENTERCODE = @PROFITCENTERCODE AND BARCODE = @BARCODE
			)
			BEGIN
				INSERT INTO ASSY_LINEASSYENGRAVING (PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,BARCODE,STATUS,DATECODE,PARTNO,CUSTOMERPARTNO)
				VALUES (@PROFITCENTERCODE, @LINECODE, @MACHINECODE, @OPERATIONCODE, @BARCODE, @ENGRAVINGSTATUS, @P_DATE_CODE, @P_PART_LOCAL, @P_CUST_PART_LOCAL)
			END

			UPDATE ASSY_LINEASSYSTATUS_RUNNING SET STATUS = @ENGRAVINGSTATUS, RESULTTIMESTAMP = GETDATE()
				WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND PROFITCENTERCODE = @PROFITCENTERCODE AND BARCODE = @BARCODE

			IF NOT EXISTS
			(
				SELECT TOP 1 1 FROM ASSY_ENGRAVE_START_CONFIRMATION WITH (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND PROFITCENTERCODE = @PROFITCENTERCODE
			)
			BEGIN
				INSERT INTO ASSY_ENGRAVE_START_CONFIRMATION (PROFITCENTERCODE, LINECODE, OPERATIONCODE, ISENGRAVECOMPLETECONFIRM)
				VALUES (@PROFITCENTERCODE, @LINECODE, @OPERATIONCODE, 1)
			END
			ELSE
			BEGIN
				UPDATE ASSY_ENGRAVE_START_CONFIRMATION SET ISENGRAVECOMPLETECONFIRM = 1 WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND PROFITCENTERCODE = @PROFITCENTERCODE
			END

			SET @RETURNVALUE = 'SUCCESS'
			SET @RETURNINT = 1
			RETURN
		END      

		ELSE IF @CONDITION = 'VALIDATE_AND_START_ENGRAVING'
		BEGIN 
			DECLARE @TMC_PART_NO_LOCAL VARCHAR(20),@MACHINECODE_LOCAL VARCHAR(20),@OPERATIONCODE_LOCAL VARCHAR(20), @STATUSDATA VARCHAR(10)

			--CHECK EITHER JIG IS IN OR OUT
			IF 
			(
				(SELECT TOP 1 ISNULL(STATUSINOUT,0) FROM ASSY_STATIONS_ZIG_IN_OUT_STATUS (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE) = 1
			)
			BEGIN
				SET @RETURNVALUE = 'JIG IS INSIDE.'
				SET @RETURNINT = 1
				RETURN
			END

			--SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL WITH (NOLOCK) 
			--		WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
			
			DECLARE @BARCODEDATA AS TABLE
			(
				BARCODE VARCHAR(60)
			)

			SET @RUNNINGDATECODE = ''
			SELECT @RUNNINGDATECODE = ISNULL(DATECODE,'') FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE

			SELECT @OPERATIONCODE_LOCAL = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE)               
			SELECT @TMC_PART_NO_LOCAL = @CHILD_PART_NO
               
			--GET THE LINE CODE FROM THE TMC BARCODE              
			SET @LINECODE_OF_BARCODE = RIGHT(@BARCODE,3)

			--CHECK IF PART IS A VALID TMC TYPE OR NOT.
			SET @EXECQUERY = ''
			SET @EXECQUERY = @LINKSERVERNAME + '.DBO.PRODUCT_MASTER WITH (NOLOCK) WHERE WAREHOUSE_CD = '''+@PROFITCENTERCODE+'''
											AND SEWS_PART_NO = '''+@TMC_PART_NO_LOCAL+''' AND ISNULL(MATERIAL_TP,'''') = ''TMC'' AND STS_CD = 0  '

			SET @EXECQUERY = 'SELECT MATERIAL_TP FROM ' + @EXECQUERY
			DELETE FROM @BARCODEDATA				
			INSERT INTO @BARCODEDATA(BARCODE)
			EXEC (@EXECQUERY)
				
			IF NOT EXISTS (SELECT 1 FROM @BARCODEDATA)
			BEGIN
				SET @RETURNVALUE = 'PART IS NOT A VALID TMC PART. CHECK MATERIAL TYPE OF PRODUCT_MASTER'
				SET @RETURNINT = 1

				EXEC ASSY_PROC_INCORRECTLABEL_MANAGE
						@CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE, @HMIMESSAGE = 'PART IS NOT A VALID TMC PART.'
				RETURN
			END

			--IF NOT EXISTS
			--(
			--	SELECT 1 MATERIAL_TP FROM PRODUCT_MASTER (NOLOCK) WHERE WAREHOUSE_CD = @PROFITCENTERCODE AND
			--	SEWS_PART_NO = @TMC_PART_NO_LOCAL AND ISNULL(MATERIAL_TP,'') = 'TMC' AND STS_CD = 0 
			--)
			--BEGIN
			--	SET @RETURNVALUE = 'PART IS NOT A VALID TMC PART. CHECK MATERIAL TYPE OF PRODUCT_MASTER'
			--	SET @RETURNINT = 1

			--	EXEC ASSY_PROC_INCORRECTLABEL_MANAGE
			--			@CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
			--			,@BARCODE = @BARCODE, @HMIMESSAGE = 'PART IS NOT A VALID TMC PART.'
			--	RETURN
			--END
			
			IF NOT EXISTS 
			(
				SELECT TOP 1 1 FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
					AND ASSY_PARTNO = @FG_PART_NO AND TMC_PARTNO = @CHILD_PART_NO AND ASSY_MODE IN ('PRODUCTION','REWORK')
			)
			BEGIN
				SET @RETURNVALUE = 'INVALID_CHILD_PART_AGAINST_FG'
				SET @RETURNINT = 1
				EXEC ASSY_PROC_INCORRECTLABEL_MANAGE
						@CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE, @HMIMESSAGE = 'INVALID_CHILD_PART_AGAINST_FG'
				RETURN
			END

			IF NOT EXISTS
			(
				SELECT 1 FROM ROUTINGCONFIGLINEWISE WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE
					AND OPERATIONCODE = @OPERATIONCODE AND ISNULL(OPERATIONREQUIRED,0) = 1 AND ISNULL(TRACEABILITY,0) = 1 AND ISNULL(ENGRAVING,0) = 1
			)
			BEGIN
				SET @RETURNVALUE = 'ENGRAVING OPERATION ROUTING IS NOT AVAILABLE'
				SET @RETURNINT = 1
				EXEC ASSY_PROC_INCORRECTLABEL_MANAGE
						@CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE, @HMIMESSAGE = 'ENGRAVING OPERATION ROUTING IS NOT AVAILABLE'
				RETURN
			END

			IF NOT EXISTS
			(
				SELECT 1 FROM ROUTINGCONFIGPARTWISE WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND PARTNO = @FG_PART_NO AND MACHINECODE = @MACHINECODE
					AND OPERATIONCODE = @OPERATIONCODE AND ISNULL(OPERATIONREQUIRED,0) = 1 AND ISNULL(TRACEABILITY,0) = 1 AND ISNULL(ENGRAVING,0) = 1
			)
			BEGIN
				SET @RETURNVALUE = 'PART WISE ENGRAVING ROUTING IS NOT DEFINED FOR THIS FG PART.'
				SET @RETURNINT = 1
				EXEC ASSY_PROC_INCORRECTLABEL_MANAGE
						@CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE, @HMIMESSAGE = 'PART WISE ENGRAVING ROUTING IS NOT DEFINED FOR THIS FG PART.'
				RETURN
			END                   
            
			SET @EXECQUERY = ''
			SET @EXECQUERY = @LINKSERVERNAME + '.DBO.PRODUCT_MASTER WITH (NOLOCK) WHERE WAREHOUSE_CD = '''+@PROFITCENTERCODE+'''
											AND SEWS_PART_NO = '''+@TMC_PART_NO_LOCAL+''' AND STS_CD = 0  AND MATERIAL_TP = ''TMC'''

			SET @EXECQUERY = 'SELECT TOP 1 MATERIAL_TP FROM ' + @EXECQUERY
			PRINT @EXECQUERY
			DELETE FROM @BARCODEDATA				
			INSERT INTO @BARCODEDATA(BARCODE)
			EXEC (@EXECQUERY)
				
			IF NOT EXISTS (SELECT 1 FROM @BARCODEDATA)
			BEGIN
				SET @RETURNVALUE = 'PART IS NOT ACTIVE.'
				SET @RETURNINT = 1
              
				--UPDATE INCORRECT LABEL
				EXEC ASSY_PROC_INCORRECTLABEL_MANAGE
					@CONDITION = 'UPDATE',@LINECODE = @LINECODE,
					@OPERATIONCODE = @OPERATIONCODE,@BARCODE = @BARCODE,@HMIMESSAGE = 'PART IS NOT ACTIVE.'
				RETURN
			END
			     
			--IF NOT EXISTS
			--(
			--	SELECT DISTINCT 1 FROM PRODUCT_MASTER (NOLOCK) WHERE WAREHOUSE_CD = @PROFITCENTERCODE 
			--	AND SEWS_PART_NO = @TMC_PART_NO_LOCAL AND STS_CD = 0 
			--	AND MATERIAL_TP = (SELECT LT.LINETYPENAME FROM LINETYPEMST (NOLOCK) LT 
			--	INNER JOIN LINEMST (NOLOCK) LM ON LT.LINETYPECODE = LM.LINETYPECODE WHERE LM.LINECODE = @LINECODE_OF_BARCODE) 
			--)
			--BEGIN
			--	SET @RETURNVALUE = 'PART IS NOT ACTIVE.'
			--	SET @RETURNINT = 1
              
			--	--UPDATE INCORRECT LABEL
			--	EXEC ASSY_PROC_INCORRECTLABEL_MANAGE
			--		@CONDITION = 'UPDATE',@LINECODE = @LINECODE,
			--		@OPERATIONCODE = @OPERATIONCODE,@BARCODE = @BARCODE,@HMIMESSAGE = 'PART IS NOT ACTIVE.'
			--	RETURN
			--END  

			SET @EXECQUERY = ''
			SET @EXECQUERY = @LINKSERVERNAME + '.DBO.BOM_MASTER WITH (NOLOCK) WHERE WH_CODE = '''+@PROFITCENTERCODE+'''
											AND FG_PART_NO = '''+@FG_PART_NO+''' AND STS_CD = 0  AND RM_PART_NO = ''' + @TMC_PART_NO_LOCAL + ''''

			SET @EXECQUERY = 'SELECT TOP 1 1 FROM ' + @EXECQUERY
			DELETE FROM @BARCODEDATA
			INSERT INTO @BARCODEDATA(BARCODE)
			EXEC (@EXECQUERY)
				
			IF NOT EXISTS (SELECT 1 FROM @BARCODEDATA)
			BEGIN
				SET @RETURNVALUE = 'INVALID CHILD PART AGAINST FG.'
				SET @RETURNINT = 1
				EXEC ASSY_PROC_INCORRECTLABEL_MANAGE
					@CONDITION = 'UPDATE',@LINECODE = @LINECODE,
					@OPERATIONCODE = @OPERATIONCODE,@BARCODE = @BARCODE,@HMIMESSAGE = 'INVALID CHILD PART AGAINST FG.'
				RETURN
			END

			--IF NOT EXISTS 
			--(
			--	SELECT TOP 1 1 FROM BOM_MASTER (NOLOCK) WHERE WH_CODE = @PROFITCENTERCODE 
			--	AND FG_PART_NO = @FG_PART_NO AND RM_PART_NO = @TMC_PART_NO_LOCAL AND STS_CD = 0
			--)
			--BEGIN
			--	SET @RETURNVALUE = 'INVALID CHILD PART AGAINST FG.'
			--	SET @RETURNINT = 1
			--	EXEC ASSY_PROC_INCORRECTLABEL_MANAGE
			--		@CONDITION = 'UPDATE',@LINECODE = @LINECODE,
			--		@OPERATIONCODE = @OPERATIONCODE,@BARCODE = @BARCODE,@HMIMESSAGE = 'INVALID CHILD PART AGAINST FG.'
			--	RETURN
			--END
        
			--THIS TMC PART SHOULD NOT BE COUPLED WITH ANY OTHER STMC PART
			
			SET @EXECQUERY = ''
			SET @EXECQUERY = @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = '''+@PROFITCENTERCODE+'''
											AND LINECODE = ''' + @LINECODE + ''' AND CHILD_BARCODE = ''' + @BARCODE + ''' AND PART_TYPE = ''TMC'''

			SET @EXECQUERY = 'SELECT CHILD_BARCODE FROM ' + @EXECQUERY
			DELETE FROM @BARCODEDATA
			INSERT INTO @BARCODEDATA(BARCODE)
			EXEC (@EXECQUERY)
				
			IF EXISTS (SELECT 1 FROM @BARCODEDATA)
			BEGIN
				SET @RETURNVALUE = 'PART HAS ALREADY BEEN COUPLED.'
				SET @RETURNINT = 1
				EXEC ASSY_PROC_INCORRECTLABEL_MANAGE
					@CONDITION = 'UPDATE',@LINECODE = @LINECODE,
					@OPERATIONCODE = @OPERATIONCODE,@BARCODE = @BARCODE,@HMIMESSAGE = 'PART HAS ALREADY BEEN COUPLED.'
				RETURN
			END
			   
			IF EXISTS
			(
				SELECT TOP 1 1 FROM ASSY_COUPLINGDETAILS (NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND CHILD_BARCODE = @BARCODE AND PART_TYPE = 'TMC'
			)
			BEGIN
				SET @RETURNVALUE = 'PART HAS ALREADY BEEN COUPLED.'
				SET @RETURNINT = 1
				EXEC ASSY_PROC_INCORRECTLABEL_MANAGE
					@CONDITION = 'UPDATE',@LINECODE = @LINECODE,
					@OPERATIONCODE = @OPERATIONCODE,@BARCODE = @BARCODE,@HMIMESSAGE = 'PART HAS ALREADY BEEN COUPLED.'
				RETURN
			END                
                 
			-- ADD BY RASHID ON 09TH MAY 2016
			-- IS BARCODE PACKED OR NOT IN PACKAGING?
			SET @EXECQUERY = ''
			SET @EXECQUERY = @LINKSERVERNAME + '.DBO.SKIDBARCODEDETAIL WITH (NOLOCK) WHERE WH_CODE = '''+@PROFITCENTERCODE+'''
											AND PARTBARCODE = '''+@BARCODE+''''

			SET @EXECQUERY = 'SELECT PARTBARCODE FROM ' + @EXECQUERY
			DECLARE @PACKAGINGENGRAVING AS TABLE
			(
				PACKEDBARCODE VARCHAR(60)
			)
				
			INSERT INTO @PACKAGINGENGRAVING(PACKEDBARCODE)
			EXEC (@EXECQUERY)
				
			IF EXISTS (SELECT 1 FROM @PACKAGINGENGRAVING)
			BEGIN
				SET @RETURNVALUE = 'PART ALREADY PACKED IN PACKAGING,CAN NOT ENGRAVE.'
				SET @RETURNINT = 1
				EXEC ASSY_PROC_INCORRECTLABEL_MANAGE
					@CONDITION = 'UPDATE',@LINECODE = @LINECODE,
					@OPERATIONCODE = @OPERATIONCODE,@BARCODE = @BARCODE,@HMIMESSAGE = 'PART ALREADY PACKED IN PACKAGING,CAN NOT ENGRAVE.'
				RETURN
			END

			SET @ISTMCVALIDATION = 0
			SELECT TOP 1 @ISTMCVALIDATION = ISNULL(ISTMCVALIDATIONOFF,0) FROM LINEMST (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
			--IF CHARINDEX('M4',@BARCODE ) = 0
			IF (UPPER(LEFT(RIGHT(@BARCODE,11),1)) ! = 'M')
			BEGIN
				IF @ISTMCVALIDATION = 1
				BEGIN					
					SET @LINECODE_OF_BARCODE = RIGHT(@BARCODE,3)
					--CHECK IF THE TMC PART HAS BEEN PASSED FROM PARTICULAR LINE
					SET @EXECQUERY = ''
					SET @EXECQUERY = @LINKSERVERNAME+'.DBO.ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE LINECODE = '''+@LINECODE_OF_BARCODE+''' 
					AND PROFITCENTERCODE = '''+@PROFITCENTERCODE+'''
					AND MACHINECODE = DBO.ASSY_FN_GET_PARAMETER_VALUE(''ASSLINE'',''FINALVIEWING'',''QCSTATION_MACHINECODE'','''+@PROFITCENTERCODE+''')
					AND BARCODE = '''+@BARCODE+'''
					AND ISNULL(STATUS,'''') = ''PS'''
					--SELECT @EXECQUERY
					SET @EXECQUERY = 'SELECT STATUS FROM ' + @EXECQUERY
					
					DECLARE @FVSTATUS AS TABLE
					(
						STATUSDATA VARCHAR(20)
					)
				
					INSERT INTO @FVSTATUS(STATUSDATA)
					EXEC (@EXECQUERY)
				
					IF NOT EXISTS (SELECT 1 FROM @FVSTATUS)
					BEGIN
						SET @RETURNVALUE = 'PART_HAS_NOT_PASSED_FROM_TMC_LINE'
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE
							@CONDITION = 'UPDATE',@LINECODE = @LINECODE,
							@OPERATIONCODE = @OPERATIONCODE,@BARCODE = @BARCODE,@HMIMESSAGE = 'PART_HAS_NOT_PASSED_FROM_TMC_LINE'
						RETURN	
					END

					IF(SELECT ISNULL(STATUSDATA,'') FROM @STATUS) <> 'PS'
					BEGIN
						SET @RETURNVALUE = 'PART_HAS_NOT_PASSED_FROM_TMC_LINE'
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE
							@CONDITION = 'UPDATE',@LINECODE = @LINECODE,
							@OPERATIONCODE = @OPERATIONCODE,@BARCODE = @BARCODE,@HMIMESSAGE = 'PART_HAS_NOT_PASSED_FROM_TMC_LINE'
						RETURN	
					END	
				END
			END

			--CHECK IF THE TMC PART HAS BEEN PASSED ALREADY ENGRAVED.
			IF EXISTS(SELECT TOP 1 1 FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) 
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND BARCODE = @BARCODE 
					AND STATUS = 'PS' AND ISNULL(RESULTTIMESTAMP,'') <> '' AND OPERATIONCODE = @OPERATIONCODE)
			BEGIN
				SET @RETURNVALUE = 'PART ALREADY ENGRAVED.'
				SET @RETURNINT = 1
				EXEC ASSY_PROC_INCORRECTLABEL_MANAGE
							@CONDITION = 'UPDATE',@LINECODE = @LINECODE,
							@OPERATIONCODE = @OPERATIONCODE,@BARCODE = @BARCODE,@HMIMESSAGE = 'PART ALREADY ENGRAVED.'
				RETURN    
			END	
			ELSE IF EXISTS(SELECT TOP 1 1 FROM ASSY_LINEASSYSTATUS (NOLOCK) 
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND BARCODE = @BARCODE 
						AND STATUS = 'PS' AND ISNULL(RESULTTIMESTAMP,'') <> '' AND OPERATIONCODE = @OPERATIONCODE)
			BEGIN
				SET @RETURNVALUE = 'PART ALREADY ENGRAVED.'
				SET @RETURNINT = 1
				EXEC ASSY_PROC_INCORRECTLABEL_MANAGE
							@CONDITION = 'UPDATE',@LINECODE = @LINECODE,
							@OPERATIONCODE = @OPERATIONCODE,@BARCODE = @BARCODE,@HMIMESSAGE = 'PART ALREADY ENGRAVED.'
				RETURN
			END			
        
			--SINCE STATUS IS SUCCESS INSERT A RECORD IN ASSY_SCAN_OK TABLE
			IF NOT EXISTS(SELECT TOP 1 1 FROM ASSY_SCAN_OK (NOLOCK) WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE)
			BEGIN               
				INSERT INTO ASSY_SCAN_OK
				(
				LINECODE,
				MACHINECODE,
				OPERATIONCODE,
				STATIONCODE,
				BARCODE,
				ISSCAN,
				ISCYCLESTARTED,
				ISPOKAYOKECOMPLETED
				)
				VALUES 
				(@LINECODE,@MACHINECODE,@OPERATIONCODE,@STATIONCODE,@BARCODE,1,0,0)
			END
			ELSE 
			BEGIN
				--RESET INCORRECT LABEL
				UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE = '', ISINCORRECT = 0 WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE

				--RESET DUPLICATE LABEL
				UPDATE ASSY_DUPLICATELABEL SET ISDUPLICATE = 0 WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
				             
				UPDATE ASSY_SCAN_OK
				SET ISSCAN = 1, BARCODE = @BARCODE
				WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE
			END

			IF NOT EXISTS 
			(
				SELECT TOP 1 1 FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND
					OPERATIONCODE = @OPERATIONCODE AND BARCODE = @BARCODE
			)
			BEGIN
				INSERT INTO ASSY_LINEASSYSTATUS_RUNNING(PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,STATIONCODE,BARCODE,STATUS,FAILCOUNT,DATECODE,PARTNO,RESULTTIMESTAMP,SCANTIMESTAMP,USERID)
				VALUES (@PROFITCENTERCODE,@LINECODE,@MACHINECODE,@OPERATIONCODE,@STATIONCODE,@BARCODE,NULL,0,@RUNNINGDATECODE,@FG_PART_NO,NULL,GETDATE(),@USERID)
			END
			ELSE IF EXISTS
			(
				SELECT TOP 1 1 FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE
					AND OPERATIONCODE = @OPERATIONCODE AND BARCODE = @BARCODE
			)
			BEGIN
				UPDATE ASSY_LINEASSYSTATUS_RUNNING SET SCANTIMESTAMP = GETDATE(),FAILCOUNT = CASE STATUS WHEN 'FL' THEN ISNULL(FAILCOUNT,0) + 1 ELSE 0 END 
					WHERE  PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND BARCODE = @BARCODE
			END

			SET @RETURNVALUE = 'CYCLE_START' 
			SET @RETURNINT = 1
			RETURN
		END

		ELSE IF @CONDITION = 'GETDATAFORENGRAVING'
		BEGIN 
			DECLARE @P_SEQ_NO_LOCAL VARCHAR(30) = '', @LINECODEPREFIX VARCHAR(1) = '', @ISDATECODESTAMP BIT = 0

			IF LEN(@BARCODE) = 24
			BEGIN
				SET @P_DATE_CODE = RIGHT(LEFT(@BARCODE,13),4)
				SET @P_SEQ_NO_LOCAL = RIGHT(LEFT(@BARCODE,21),8)
			END
			ELSE IF LEN(@BARCODE) = 23
			BEGIN
				SET @P_DATE_CODE = RIGHT(LEFT(@BARCODE,12),4)
				SET @P_SEQ_NO_LOCAL = RIGHT(LEFT(@BARCODE,20),8)
			END
			--ADDING PREFIX 2 OR '' AS PER LINE CODE
			SET @LINECODEPREFIX = CASE RIGHT(@BARCODE,1) WHEN '2' THEN '2' ELSE '' END
			SET @P_SEQ_NO_LOCAL = @LINECODEPREFIX + @P_SEQ_NO_LOCAL

			SELECT TOP 1 @P_PART_LOCAL = ASSY_PARTNO, @P_CUST_PART_LOCAL = CUSTOMERPARTNO FROM ASSY_RUNNINGPART WITH (NOLOCK)
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
			
			IF ISNULL(@P_CUST_PART_LOCAL,'') = ''
			BEGIN
				SELECT TOP 1 @P_CUST_PART_LOCAL = CLM.CUSTOMERPARTNO, @ISDATECODESTAMP = CASE LABELDATAVALUE WHEN 'Y' THEN 1 ELSE 0 END
						FROM ASSY_COUPLING_LABELINFO_MST CLM WITH (NOLOCK) INNER JOIN ASSY_RUNNINGPART RP WITH (NOLOCK)
							ON CLM.PROFITCENTERCODE = RP.PROFITCENTERCODE AND CLM.PARTNO = RP.ASSY_PARTNO
								WHERE CLM.PARTNO = @P_PART_LOCAL AND CLM.PROFITCENTERCODE = @PROFITCENTERCODE AND CLM.LABELDATANAME = 'ISDATECODE_ENGRAVING'
			END
			ELSE
			BEGIN
				SELECT TOP 1 @ISDATECODESTAMP = CASE LABELDATAVALUE WHEN 'Y' THEN 1 ELSE 0 END
						FROM ASSY_COUPLING_LABELINFO_MST CLM WITH (NOLOCK) INNER JOIN ASSY_RUNNINGPART RP WITH (NOLOCK)
							ON CLM.PROFITCENTERCODE = RP.PROFITCENTERCODE AND CLM.PARTNO = RP.ASSY_PARTNO
								WHERE CLM.PARTNO = @P_PART_LOCAL AND CLM.PROFITCENTERCODE = @PROFITCENTERCODE AND CLM.LABELDATANAME = 'ISDATECODE_ENGRAVING'
									AND CLM.CUSTOMERPARTNO = @P_CUST_PART_LOCAL
			END

			CREATE TABLE #TEMPKEY
			(
				_SEQ INT,
				_KEY VARCHAR(100),
				_VALUE VARCHAR(100)
			)

			INSERT INTO #TEMPKEY (_SEQ,_KEY,_VALUE)
			SELECT 1,'SEQUENCENUMBER',@P_SEQ_NO_LOCAL
			UNION
			SELECT 2,'CUSTPARTNO',@P_CUST_PART_LOCAL

			IF (@ISDATECODESTAMP = 1)
			BEGIN
				INSERT INTO #TEMPKEY (_SEQ,_KEY,_VALUE)
				SELECT 3,'DATECODE',@P_DATE_CODE
			END

			SELECT _VALUE AS DATATOENGRAVE FROM #TEMPKEY ORDER BY _SEQ
           
			SET @RETURNVALUE = 'SUCCESS'
			SET @RETURNINT = 1
			RETURN
		END

		ELSE IF @CONDITION = 'GETTORQUESTATUS'
		BEGIN 
			SELECT PROFITCENTRECODE,
			LINECODE,
			ISNULL(TORQUE_1,0) TORQUE_1,
			ISNULL(TORQUE_2,0) TORQUE_2,
			IS_TORQUE1_OK,
			IS_TORQUE2_OK,
			ENT_DT,
			PART_NO,
			IS_BARCODE_PRINT
			FROM ASSY_COUPLINGTORQUESTATUS WITH (NOLOCK) 
			WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND PART_NO = @FG_PART_NO --AND IS_TORQUE1_OK = 1 AND IS_TORQUE2_OK = 1
           
			SET @RETURNVALUE = 'SUCCESS'
			SET @RETURNINT = 1
			RETURN
		END

		ELSE IF @CONDITION = 'RESETTORQUESTATUS'
		BEGIN 
			IF ISNULL(@FG_PART_NO,'') ! = ''
			BEGIN
				IF EXISTS (SELECT 1 FROM ASSY_COUPLINGTORQUESTATUS (NOLOCK) 
					WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND PART_NO = @FG_PART_NO AND ISNULL(IS_TORQUE1_OK,0) = 1 AND ISNULL(IS_TORQUE2_OK,0) = 1)
					BEGIN
					
						DECLARE @UID AS UNIQUEIDENTIFIER, @TORQUE_1_VALUE NUMERIC(4,2), @TORQUE_2_VALUE NUMERIC(4,2)

						SET @UID = NEWID()
									
						SELECT @DATECODE = DATECODE, @USERID = CREATEDBY FROM ASSY_RUNNINGPART (NOLOCK) 
							WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
						
						SELECT TOP 1 @TORQUE_1_VALUE = TORQUE_1, @TORQUE_2_VALUE = TORQUE_2 FROM ASSY_COUPLINGTORQUESTATUS (NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND PART_NO = @FG_PART_NO

						INSERT INTO ASSY_LINEASSYPARAMDATA_RUNNING(PROFITCENTERCODE, LINECODE, MACHINECODE,OPERATIONCODE,STATIONCODE,BARCODE,RESULT,DATECODE,USERID,TIMESTAMP, PARTNO,UID,SCANTIMESTAMP)
						SELECT TOP 1 @PROFITCENTERCODE, @LINECODE, 'MCCPLSTN','OCCPLSTN',1,@BARCODE,'PS',@DATECODE,@USERID, GETDATE(), @FG_PART_NO,@UID,GETDATE()
					
						-- NO PASS TAG IN KEPWARE THAT'S WHY INSERTING MANUALLY
						INSERT INTO ASSY_LINEASSYPARAMDATA_RUNNING_DTL(UID,TAGID,VALUE)
						SELECT @UID,1556, @TORQUE_1_VALUE
						UNION
						SELECT @UID,1559, @TORQUE_2_VALUE

						UPDATE ASSY_COUPLINGTORQUESTATUS 
							SET 
							TORQUE_1 = 0,
							TORQUE_2 = 0,
							IS_TORQUE1_OK = 0,
							IS_TORQUE2_OK = 0,
							ENT_DT = GETDATE(),
							PART_NO = '',
							IS_BARCODE_PRINT = 1
						WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND PART_NO = @FG_PART_NO
				
						SET @RETURNVALUE = 'SUCCESS'
						SET @RETURNINT = 1
					END
			END
			RETURN
		END
		
		ELSE IF @CONDITION = 'VALIDATEBARCODEFORREPRINIING'
		BEGIN 
			IF EXISTS
			( 
				SELECT TOP 1 1 FROM ASSY_COUPLINGDETAILS (NOLOCK) WHERE FG_BARCODE = @BARCODE AND PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND 
					OPERATION_CODE = @OPERATIONCODE AND MACHINE_CODE = @MACHINECODE
			)
			BEGIN
				SELECT @BARCODE
				SET @RETURNVALUE = 'STMC'
				SET @RETURNINT = 1
				RETURN
			END

			IF EXISTS
			( 
				SELECT TOP 1 1 FROM ASSY_COUPLINGDETAILS (NOLOCK) WHERE CHILD_BARCODE = @BARCODE AND PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND 
					OPERATION_CODE = @OPERATIONCODE AND MACHINE_CODE = @MACHINECODE
			)
			BEGIN
				DECLARE @PART_TYPE_LOCAL VARCHAR(10)
				DECLARE @BARCODE_FGLOCAL VARCHAR(100)

				SELECT TOP 1 @PART_TYPE_LOCAL = PART_TYPE,@BARCODE_FGLOCAL = FG_BARCODE FROM ASSY_COUPLINGDETAILS (NOLOCK) WHERE CHILD_BARCODE = @BARCODE AND
					PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND OPERATION_CODE = @OPERATIONCODE AND MACHINE_CODE = @MACHINECODE

				SELECT @BARCODE_FGLOCAL
				SET @RETURNVALUE = @PART_TYPE_LOCAL
				SET @RETURNINT = 1
				RETURN
			END
           
			SET @RETURNVALUE = 'BARCODE DOES NOT EXIXTS.'
			SET @RETURNINT = 0
			RETURN
		END

		ELSE IF @CONDITION = 'REPRINT_STMC_BARCODE'
		BEGIN 
			INSERT INTO ASSY_STMCREPRINT
			(
			[PROFITCENTRECODE],
			[LINECODE],
			[MACHINE_CODE],
			[OPERATION_CODE],
			[BARCODE], 
			[ENT_BY],
			[ENT_DT]
			)
			VALUES
			(
			@PROFITCENTERCODE,
			@LINECODE,
			@MACHINECODE,
			@OPERATIONCODE,
			@BARCODE,
			@USERID,
			GETDATE()
			)

			IF @LINECODE IN ('P6','P7')
			BEGIN
				DECLARE @SERVOBARCODE VARCHAR(50) = '', @SERVOBARCODELSTFOURDGTSEQNO VARCHAR(50) = '', @SERVOBARCODEEIGHTDGTSEQNO VARCHAR(50) = ''
				SELECT TOP 1 @SERVOBARCODE =  ISNULL(CHILD_BARCODE,'') FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
					AND PART_TYPE = 'SERVO' AND FG_BARCODE = @BARCODE ORDER BY ENT_DT DESC

				--GET SERVO LAST FOUR DIGIT SEQUENCE NO. FROM SERVO BARCODE
				SELECT @SERVOBARCODELSTFOURDGTSEQNO = RIGHT(ISNULL(SERIALNO,''),4) FROM ASSY_FN_GET_BARCODEPARTS_FROM_BARCODE(@PROFITCENTERCODE,@LINECODE,@SERVOBARCODE)

				--GET SERVO 8 DIGIT SEQUENCE NO. FROM SERVO BARCODE
				SELECT @SERVOBARCODEEIGHTDGTSEQNO = RIGHT(ISNULL(SERIALNO,''),8) FROM ASSY_FN_GET_BARCODEPARTS_FROM_BARCODE(@PROFITCENTERCODE,@LINECODE,@SERVOBARCODE)

				SELECT DISTINCT	RTRIM(LTRIM(CP.PROFITCENTERCODE)) PROFITCENTERCODE, RTRIM(LTRIM(CP.PARTNO)) PARTNO, RTRIM(LTRIM(CP.CUSTOMERPARTNO)) CUSTOMERPARTNO,
				RIGHT(RTRIM(LTRIM(CP.PARTNO)),4) STMCLASTFOURDGTPARTNO, @SERVOBARCODELSTFOURDGTSEQNO SERVOLSTFOURDGTSEQNO, '' SHIFTDATE,
				'' SHIFTID, LINECODE, DATECODE, RTRIM(LTRIM(LABELDATANAME)) LABELDATANAME, RTRIM(LTRIM(LABELDATAVALUE)) LABELDATAVALUE,
				@SERVOBARCODEEIGHTDGTSEQNO SERVOBARCODEEIGHTDGTSEQNO
				FROM ASSY_COUPLINGDETAILS (NOLOCK) COU INNER JOIN ASSY_COUPLING_LABELINFO_MST (NOLOCK) CP 
				ON COU.STMC_PART_NO = CP.PARTNO AND COU.PROFITCENTRECODE = CP.PROFITCENTERCODE 
				WHERE COU.FG_BARCODE = @BARCODE
			END
			ELSE
			BEGIN
				SELECT DISTINCT CLI.LABELDATANAME, CLI.LABELDATAVALUE, COU.LINECODE, COU.FG_BARCODE, STMC_PART_NO AS PARTNO, RIGHT(COU.STMC_PART_NO,4) STMCLASTFOURDGTPARTNO,
					COU.DATECODE,CLI.CUSTOMERPARTNO AS CUSTOMERPARTNO
						FROM ASSY_COUPLINGDETAILS (NOLOCK) COU INNER JOIN ASSY_COUPLING_LABELINFO_MST (NOLOCK) CLI 
							ON COU.STMC_PART_NO = CLI.PARTNO AND COU.PROFITCENTRECODE = CLI.PROFITCENTERCODE 
								WHERE COU.FG_BARCODE = @BARCODE
			END
			SET @RETURNVALUE = 'SUCCESS.'
			SET @RETURNINT = 1        
			RETURN
		END

		ELSE IF @CONDITION = 'ENABLE_DISABLE_TMC_VALIDATION'
		BEGIN 
			IF(@ENABLE_TMC_VALIDATION IN (0,1))
			BEGIN
				UPDATE LINEMST SET ISTMCVALIDATIONOFF = @ENABLE_TMC_VALIDATION WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
			END
			
			SELECT  ISNULL(ISTMCVALIDATIONOFF,0) ISTMCVALIDATIONOFF FROM LINEMST (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
			RETURN 
		END

		ELSE IF @CONDITION = 'GET_ENGRAVING_INFO_NISSAN_LINE'
		BEGIN 
			IF EXISTS (SELECT TOP 1 1 FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND ASSY_MODE IN ('PRODUCTION','REWORK') AND PARTTYPE = 'STMC')
			BEGIN
				SELECT CLM.PARTNO, RP.CUSTOMERPARTNO, LABELDATANAME, LABELDATAVALUE
					FROM ASSY_COUPLING_LABELINFO_MST CLM WITH (NOLOCK) INNER JOIN ASSY_RUNNINGPART RP WITH (NOLOCK) 
						ON CLM.PROFITCENTERCODE = RP.PROFITCENTERCODE AND CLM.PARTNO = RP.ASSY_PARTNO 
							WHERE CLM.PARTNO = (SELECT TOP 1 ASSY_PARTNO FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE)
								AND CLM.PROFITCENTERCODE = @PROFITCENTERCODE
				SET @RETURNINT = 1
			END
			RETURN 
		END

		ELSE IF @CONDITION = 'SELECT_SENSOR_POSITION'
		BEGIN 
			SELECT TOP 1 @RETURNVALUE = ISNULL(SENSORPOSITION,'') FROM ASSY_CLUTCHNIPPLE_SENSOR_POSITION WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
				AND OPERATIONCODE = @OPERATIONCODE
			SET @RETURNINT = 1
		END

		ELSE IF (@CONDITION = 'ENGRAVE_JIG_IN')
		BEGIN 
			DECLARE @ISJIGINSIDE BIT = 0;
			SELECT @ISJIGINSIDE = ISNULL(STATUSINOUT,0) FROM ASSY_STATIONS_ZIG_IN_OUT_STATUS WITH (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
			
			IF(@ISJIGINSIDE = 1)
			BEGIN
				SET @RETURNVALUE = 'Y'
			END
			ELSE
			BEGIN
				SET @RETURNVALUE = 'N'
			END
			SET @RETURNINT = 1
		END

		ELSE IF(@CONDITION = 'UPDATE_CNC_REQUIRED_STATUS')
		BEGIN 
			DECLARE @UPDATECNCSTATUS SMALLINT = NULL
			
			IF ISNULL(@CNCREQUIREDSTATUS,0) = 0
			BEGIN
				SET @UPDATECNCSTATUS = 2
			END
			ELSE IF ISNULL(@CNCREQUIREDSTATUS,0) = 1
			BEGIN
				SET @UPDATECNCSTATUS = 1
			END

			IF NOT EXISTS
			(
			SELECT TOP 1 1 FROM ASSY_CLUTCHNIPPLE_SENSOR_POSITION WITH (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND PROFITCENTERCODE = @PROFITCENTERCODE
			)
			BEGIN
				INSERT INTO ASSY_CLUTCHNIPPLE_SENSOR_POSITION (PROFITCENTERCODE, LINECODE, OPERATIONCODE, ISCNCREQUIRED)
				VALUES (@PROFITCENTERCODE, @LINECODE, @OPERATIONCODE, @UPDATECNCSTATUS)
			END
			ELSE
			BEGIN
				UPDATE ASSY_CLUTCHNIPPLE_SENSOR_POSITION SET ISCNCREQUIRED = @UPDATECNCSTATUS WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
					AND PROFITCENTERCODE = @PROFITCENTERCODE
			END
		END

		ELSE IF @CONDITION = 'ENABLE_DISABLE_CNC_VALIDATION'
		BEGIN 
			IF(@ENABLEDISABLECNCVALIDATION IN (0,1))
			BEGIN
				UPDATE LINEMST SET ISCNCVALIDATIONOFF = @ENABLEDISABLECNCVALIDATION WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
			END
			
			SELECT  ISNULL(ISCNCVALIDATIONOFF,0) ISCNCVALIDATIONOFF FROM LINEMST (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
		END

		ELSE IF @CONDITION = 'REFRESH_COUPLING_TEMP'
		BEGIN 
			UPDATE ASSY_SCAN_OK SET ISSCAN = 0, BARCODE = '' WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
			
			DELETE FROM ASSY_COUPLING_TEMP WHERE LINECODE = @LINECODE AND PROFITCENTRECODE = @PROFITCENTERCODE AND OPERATION_CODE = @OPERATIONCODE

			UPDATE ASSY_COUPLINGTORQUESTATUS SET IS_TORQUE1_OK = 0, IS_TORQUE2_OK = 0, TORQUE_1 = 0.0, TORQUE_2 = 0.0 WHERE LINECODE = @LINECODE AND PROFITCENTRECODE = @PROFITCENTERCODE

			IF NOT EXISTS
			(
			SELECT TOP 1 1 FROM ASSY_CLUTCHNIPPLE_SENSOR_POSITION WITH (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND PROFITCENTERCODE = @PROFITCENTERCODE
			)
			BEGIN
				INSERT INTO ASSY_CLUTCHNIPPLE_SENSOR_POSITION (PROFITCENTERCODE, LINECODE, OPERATIONCODE, ISCOUPLINGREFRESHCYCLE)
				VALUES (@PROFITCENTERCODE, @LINECODE, @OPERATIONCODE, 1)
			END
			ELSE
			BEGIN
				UPDATE ASSY_CLUTCHNIPPLE_SENSOR_POSITION SET ISCOUPLINGREFRESHCYCLE = 1 WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND PROFITCENTERCODE = @PROFITCENTERCODE
			END

			SET @RETURNVALUE = 'SUCCESS'
			SET @RETURNINT = 1
		END

		ELSE IF @CONDITION = 'COUPLINGPARTSCOUNT'
		BEGIN 
			DECLARE @COUPLINGPARTWISE INT = 0,@COUPLINGSHIFTWISE INT = 0
			SET @RUNNINGDATECODE = ''
			
			SELECT @RUNNINGDATECODE = ISNULL(DATECODE,'') FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE

			SELECT @COUPLINGPARTWISE = COUNT(*) FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) 
				WHERE LINECODE = @LINECODE AND PROFITCENTRECODE = @PROFITCENTERCODE
						AND STMC_PART_NO = @FG_PART_NO 
						AND MACHINE_CODE = @MACHINECODE
						AND OPERATION_CODE = @OPERATIONCODE
						AND DATECODE = CASE ISNULL(@RUNNINGDATECODE,'') WHEN '' THEN @DATECODE ELSE @RUNNINGDATECODE END
						AND ISNULL(PART_TYPE,'') = 'TMC'
			
			SELECT @COUPLINGPARTWISE = ISNULL(@COUPLINGPARTWISE,0) + ISNULL(COUNT(*),0) FROM ASSY_COUPLINGDETAILS_HISTORY WITH (NOLOCK) 
				WHERE LINECODE = @LINECODE AND PROFITCENTRECODE = @PROFITCENTERCODE
						AND STMC_PART_NO = @FG_PART_NO 
						AND MACHINE_CODE = @MACHINECODE
						AND OPERATION_CODE = @OPERATIONCODE
						AND DATECODE = CASE ISNULL(@RUNNINGDATECODE,'') WHEN '' THEN @DATECODE ELSE @RUNNINGDATECODE END
						AND ISNULL(PART_TYPE,'') = 'TMC'

			SELECT @COUPLINGSHIFTWISE = COUNT(*) FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) 
				WHERE LINECODE = @LINECODE AND PROFITCENTRECODE = @PROFITCENTERCODE
						AND MACHINE_CODE = @MACHINECODE
						AND OPERATION_CODE = @OPERATIONCODE
						AND DATECODE = CASE ISNULL(@RUNNINGDATECODE,'') WHEN '' THEN @DATECODE ELSE @RUNNINGDATECODE END
						AND ISNULL(PART_TYPE,'') = 'TMC'

			SELECT @COUPLINGSHIFTWISE = ISNULL(@COUPLINGSHIFTWISE,0) + ISNULL(COUNT(*),0) FROM ASSY_COUPLINGDETAILS_HISTORY WITH (NOLOCK) 
				WHERE LINECODE = @LINECODE AND PROFITCENTRECODE = @PROFITCENTERCODE
						AND MACHINE_CODE = @MACHINECODE
						AND OPERATION_CODE = @OPERATIONCODE
						AND DATECODE = CASE ISNULL(@RUNNINGDATECODE,'') WHEN '' THEN @DATECODE ELSE @RUNNINGDATECODE END
						AND ISNULL(PART_TYPE,'') = 'TMC'

			SELECT ISNULL(@COUPLINGPARTWISE,0) PARTWISE, ISNULL(@COUPLINGSHIFTWISE,0) SHIFTWISE

			SET @RETURNVALUE = 'SUCCESS'
			SET @RETURNINT = 1
			RETURN
		END
		ELSE IF @CONDITION = 'VALIDATE_BACKPLATE' -- CODE ADDED BY PRERNA TO VALIDATE BACKPLATE
		BEGIN 
		------------------SCAN BACKPLATE ABOVE BACKPLATE--------------------------------------
		--CHECK SCANNED BARCODE HAVING CORRECT LINE CODE OR NOT
		
		
			IF EXISTS 
			(
				SELECT TOP 1 1 FROM ASSYBARCODEDATA(NOLOCK)
				WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND (LEFTSHOEBARCODE=@BARCODE OR RIGHTSHOEBARCODE=@BARCODE) 
				AND RESULT='OK' AND FGPARTNUMBER=@FG_PART_NO AND LINECODE=@LINECODE 
			)
			BEGIN					

				EXEC [ASSY_PROC_WRITEOPCTAGSAUTO] @P_MODE='WRITE_STATUS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@P_MACHINECODE=@MACHINECODE,@VALUE='19'				
				SET @RETURNVALUE = 'FIRST_SCAN_BACKPLATE'				  
				RETURN
			END
			IF EXISTS 
			(
				SELECT TOP 1 1 FROM ASSY_COUPLING_TEMP WITH (NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE 
				AND LINECODE = @LINECODE AND CHILD_BARCODE = @BARCODE AND PART_TYPE = 'BACKPLATE'
			)
			BEGIN
			    EXEC [ASSY_PROC_WRITEOPCTAGSAUTO] @P_MODE='WRITE_STATUS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@P_MACHINECODE=@MACHINECODE,@VALUE='15'
				EXEC [ASSY_PROC_WRITEOPCTAGSAUTO] @P_MODE='WRITE_BARCODE',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@P_MACHINECODE=@MACHINECODE,@VALUE=@BARCODE
				SET @RETURNVALUE = 'BACKPLATE_ALREADY_SCANNED_SCAN_SHOE_BARCODE'				  
				RETURN
			END				
			IF EXISTS
			(
				SELECT TOP 1 1 FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE 
					AND LINECODE = @LINECODE AND CHILD_BARCODE = @BARCODE AND PART_TYPE = 'BACKPLATE'
			) 
			BEGIN
			    EXEC [ASSY_PROC_WRITEOPCTAGSAUTO] @P_MODE='WRITE_STATUS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@P_MACHINECODE=@MACHINECODE,@VALUE='19'
				SET @RETURNVALUE = 'BACKPLATE_HAS_ALREADY_BEEN_COUPLED'
				RETURN
			END 			
			IF EXISTS
			( 
			SELECT TOP 1 1 FROM ASSY_TALLYCHARTSTATUSDATA WITH (NOLOCK) WHERE BARCODE = @BARCODE AND (ISNULL(ASSY_AUTH , 0) = 1 OR ISNULL(NOTPROCESSEDSTATUS , '' ) <> '')
				AND LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
			)
			BEGIN
			    EXEC [ASSY_PROC_WRITEOPCTAGSAUTO] @P_MODE='WRITE_STATUS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@P_MACHINECODE=@MACHINECODE,@VALUE='19'
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'PART_HAS_ALREADY_PROCESSED_IN_TALLYCHART'								
				RETURN
			END	
			----------CHECK A PART HAS CLEARED FROM PREVIOUS STATION-----------------------			
			DECLARE @PREVMACHINECODEBP VARCHAR(20) = NULL , @CHECK_BARCODEBP VARCHAR (100) = ''
			EXEC ASSY_PROC_GET_PREVIOUS_MACHINECODE @LINECODE = @LINECODE , @MACHINECODE = @MACHINECODE , @PARTNUMBER = @PARTNUMBER
			 , @PREVMACHINECODE = @PREVMACHINECODEBP OUTPUT
			--SELECT@PREVMACHINECODEBP
			SELECT @CHECK_BARCODEBP = ISNULL(BARCODE , '') FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
			AND LINECODE = @LINECODE AND BARCODE = @BARCODE AND MACHINECODE = @PREVMACHINECODEBP						

			IF @CHECK_BARCODEBP = ''
			BEGIN
				SELECT @CHECK_BARCODEBP = ISNULL(BARCODE , '') FROM ASSY_LINEASSYSTATUS (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE AND BARCODE = @BARCODE AND MACHINECODE =@PREVMACHINECODEBP AND ISNULL(ISTALLYCHARTAPPROVED , 0) = 0
			END

			IF @CHECK_BARCODEBP = ''						
			BEGIN											
				SELECT TOP 1 @OPERATIONSEQNO = L.OPERATIONSEQNO FROM ROUTINGCONFIGLINEWISE (NOLOCK) L
				INNER JOIN ROUTINGCONFIGPARTWISE (NOLOCK) P
				ON L.OPERATIONCODE = P.OPERATIONCODE 
				AND L.MACHINECODE = P.MACHINECODE 
				WHERE L.LINECODE = @LINECODE
				AND P.PARTNO = (SELECT TOP 1 ASSY_PARTNO FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE)
				AND L.TRACEABILITY = 1
				AND P.TRACEABILITY = 1
				AND L.MACHINECODE =@PREVMACHINECODEBP 
				AND P.MACHINECODE =@PREVMACHINECODEBP 
				ORDER BY L.OPERATIONSEQNO 					
					 
				SELECT TOP 1 @LINETYPECODE = LTM.LINETYPENAME FROM LINEMST (NOLOCK) LM 
				INNER JOIN LINETYPEMST (NOLOCK) LTM 
				ON LM.LINETYPECODE = LTM.LINETYPECODE  
				WHERE LM.LINECODE = @LINECODE					
							
				SET @INCORRECTMSG = (SELECT MACHINENAME FROM MACHINEMST (NOLOCK) WHERE MACHINECODE =@PREVMACHINECODEBP
				AND PROFITCENTERCODE = @PROFITCENTERCODE)
				SET @RETURNVALUE = 'NOT_PROCESSED_FROM_|'+@INCORRECTMSG
				EXEC [ASSY_PROC_WRITEOPCTAGSAUTO] @P_MODE='WRITE_STATUS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@P_MACHINECODE=@MACHINECODE,@VALUE='19'									
				SET @INCORRECTMSG = 'NOT PROCESSED FROM'+@INCORRECTMSG										
				SET @RETURNINT = 1
				RETURN
			END
			-------------------------------------------
			--CHECK PART HAS BEEN ONLY SCANNED BUT NOT TESTED
			SET @CHECK_BARCODEBP = ''			
			SELECT @CHECK_BARCODEBP = ISNULL(BARCODE , '') FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
			AND LINECODE = @LINECODE AND BARCODE = @BARCODE AND MACHINECODE =@PREVMACHINECODEBP AND ISNULL(STATUS , '') = '' 					
			IF @CHECK_BARCODEBP = ''
			BEGIN
				SELECT @CHECK_BARCODEBP = ISNULL(BARCODE , '') FROM ASSY_LINEASSYSTATUS (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE AND BARCODE = @BARCODE AND MACHINECODE =@PREVMACHINECODEBP AND ISNULL(ISTALLYCHARTAPPROVED , 0) = 0
				AND ISNULL(STATUS , '') = '' 
			END								
			IF @CHECK_BARCODEBP <> ''
			BEGIN
				SELECT TOP 1 @OPERATIONSEQNO = L.OPERATIONSEQNO FROM ROUTINGCONFIGLINEWISE(NOLOCK) L
				INNER JOIN ROUTINGCONFIGPARTWISE (NOLOCK) P
				ON L.OPERATIONCODE = P.OPERATIONCODE 
				AND L.MACHINECODE = P.MACHINECODE 
				WHERE L.LINECODE = @LINECODE
				AND P.PARTNO = (SELECT TOP 1 ASSY_PARTNO FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE)
				AND L.TRACEABILITY = 1
				AND P.TRACEABILITY = 1
				AND L.MACHINECODE =@PREVMACHINECODEBP 
				AND P.MACHINECODE =@PREVMACHINECODEBP 
				ORDER BY L.OPERATIONSEQNO 					
					 
				SELECT TOP 1 @LINETYPECODE = LTM.LINETYPENAME FROM LINEMST(NOLOCK) LM 
				INNER JOIN LINETYPEMST (NOLOCK) LTM 
				ON LM.LINETYPECODE  = LTM.LINETYPECODE  
				WHERE LM.LINECODE = @LINECODE
										
				SET @INCORRECTMSG = (SELECT MACHINENAME FROM MACHINEMST(NOLOCK) WHERE MACHINECODE =@PREVMACHINECODEBP
				AND PROFITCENTERCODE = @PROFITCENTERCODE)
										
				--SET @RETURNVALUE = 'NOT_CLEARED_FROM_|'+@INCORRECTMSG		
				EXEC [ASSY_PROC_WRITEOPCTAGSAUTO] @P_MODE='WRITE_STATUS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@P_MACHINECODE=@MACHINECODE,@VALUE='19'
				SET @RETURNVALUE = 'THIS_BARCODE_HAS_BEEN_ONLY_SCANNED_AND_NOT_TESTED_|'+@INCORRECTMSG											
				SET @RETURNINT = 1
				RETURN
			END 	
			--------------------------------------------

			SET @CHECK_BARCODEBP = ''			
			SELECT @CHECK_BARCODEBP = ISNULL(BARCODE , '') FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
			AND LINECODE = @LINECODE AND BARCODE = @BARCODE AND MACHINECODE =@PREVMACHINECODEBP AND ISNULL(STATUS , '') = 'PS' 						
			IF @CHECK_BARCODEBP = ''
			BEGIN
				SELECT @CHECK_BARCODEBP = ISNULL(BARCODE , '') FROM ASSY_LINEASSYSTATUS (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE AND BARCODE = @BARCODE AND MACHINECODE =@PREVMACHINECODEBP AND ISNULL(ISTALLYCHARTAPPROVED , 0) = 0
				AND ISNULL(STATUS , '') = 'PS' 
			END
			IF @CHECK_BARCODEBP = ''							
			BEGIN
				SELECT TOP 1 @OPERATIONSEQNO = L.OPERATIONSEQNO FROM ROUTINGCONFIGLINEWISE(NOLOCK) L
				INNER JOIN ROUTINGCONFIGPARTWISE (NOLOCK) P
				ON L.OPERATIONCODE = P.OPERATIONCODE 
				AND L.MACHINECODE = P.MACHINECODE 
				WHERE L.LINECODE  = @LINECODE
				AND P.PARTNO = (SELECT TOP 1 ASSY_PARTNO FROM ASSY_RUNNINGPART(NOLOCK) WHERE LINECODE = @LINECODE)
				AND L.TRACEABILITY = 1
				AND P.TRACEABILITY = 1
				AND L.MACHINECODE =@PREVMACHINECODEBP 
				AND P.MACHINECODE =@PREVMACHINECODEBP 
				ORDER BY L.OPERATIONSEQNO 					
					 
				SELECT TOP 1 @LINETYPECODE = LTM.LINETYPENAME FROM LINEMST(NOLOCK)LM 
				INNER JOIN LINETYPEMST (NOLOCK) LTM 
				ON LM.LINETYPECODE = LTM.LINETYPECODE  
				WHERE LM.LINECODE = @LINECODE
										
				SET @INCORRECTMSG = (SELECT MACHINENAME FROM MACHINEMST(NOLOCK) WHERE MACHINECODE =@PREVMACHINECODEBP
				AND PROFITCENTERCODE = @PROFITCENTERCODE)
				EXEC [ASSY_PROC_WRITEOPCTAGSAUTO] @P_MODE='WRITE_STATUS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@P_MACHINECODE=@MACHINECODE,@VALUE='19'						
				SET @RETURNVALUE = 'NOT_CLEARED_FROM_|'+@INCORRECTMSG			
				SET @RETURNINT = 1
				RETURN
			END 	

			----CHECK FOR WIP LIMIT
			DECLARE @RETURNVALUE1 VARCHAR(100) , @RETURNINT1 INT
			EXEC ASSY_PROC_WIP_MANAGE @CONDITION = 'VALIDATE_WIP' , @LINECODE = @LINECODE , @MACHINECODE = @MACHINECODE , @BARCODE = @BARCODE , @PROFITCENTERCODE = @PROFITCENTERCODE 
			 , @RETURNVALUE = @RETURNVALUE1 OUT , @RETURNINT = @RETURNINT1 OUT			
			IF RTRIM(LTRIM(@RETURNVALUE1)) = 'WIP_LIMIT_HAS_REACHED'
			BEGIN				
				EXEC [ASSY_PROC_WRITEOPCTAGSAUTO] @P_MODE='WRITE_STATUS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@P_MACHINECODE=@MACHINECODE,@VALUE='19'			
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'WIP_LIMIT_HAS_REACHED'							
				RETURN
			END						

			IF EXISTS
			(
				SELECT TOP 1 1 FROM ASSY_COUPLING_TEMP WITH (NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE 
				AND LINECODE = @LINECODE AND CHILD_BARCODE <> @BARCODE AND PART_TYPE = 'BACKPLATE'
			)
			BEGIN

			DELETE FROM ASSY_COUPLING_TEMP WHERE PART_TYPE = 'BACKPLATE'

			END

			--IF EXISTS
			--(
			--	SELECT DISTINCT 1 FROM ASSY_SCAN_OK(NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE 
			--	AND MACHINECODE = @MACHINECODE AND STATIONCODE = '1'
			--)
			--BEGIN
			--	UPDATE ASSY_SCAN_OK SET ISSCAN = 1 , BARCODE = @BARCODE WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE
			--	AND STATIONCODE = '1'									
			--END
			--ELSE
			--BEGIN
			--	INSERT INTO ASSY_SCAN_OK(LINECODE , OPERATIONCODE , STATIONCODE , BARCODE , ISSCAN , MACHINECODE)
			--	SELECT @LINECODE , @OPERATIONCODE , '1' , @BARCODE , 1 , @MACHINECODE												
			--END
														 
			--HOLD A RECORD IN TEMP TABLE..
			IF NOT EXISTS
			( 
				SELECT 1 CHILD_BARCODE FROM ASSY_COUPLING_TEMP (NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE 
				AND LINECODE = @LINECODE AND CHILD_BARCODE = @BARCODE AND PART_TYPE = 'BACKPLATE'
			)
			BEGIN
				INSERT INTO ASSY_COUPLING_TEMP(PROFITCENTRECODE , LINECODE , STMC_PART_NO , CHILD_PART_NO , PART_TYPE , 
					MACHINE_CODE , OPERATION_CODE , TORQUE_1 , TORQUE_2 , ENT_DT , CHILD_BARCODE , ENT_BY)
				VALUES 
				(@PROFITCENTERCODE , @LINECODE , @FG_PART_NO , @CHILD_PART_NO , 'BACKPLATE' , @MACHINECODE , @OPERATIONCODE , 
				@TORQUE_1 , @TORQUE_2 , GETDATE() , @BARCODE , @USERID)		
			END 
			ELSE
			BEGIN
				UPDATE ASSY_COUPLING_TEMP SET ENT_DT = GETDATE() , ENT_BY = @USERID 
				WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND CHILD_BARCODE = @BARCODE AND PART_TYPE = 'BACKPLATE'
			END		
			EXEC [ASSY_PROC_WRITEOPCTAGSAUTO] @P_MODE='WRITE_STATUS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@P_MACHINECODE=@MACHINECODE,@VALUE='15'
			EXEC [ASSY_PROC_WRITEOPCTAGSAUTO] @P_MODE='WRITE_BARCODE',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@P_MACHINECODE=@MACHINECODE,@VALUE=@BARCODE
			SET @RETURNVALUE = 'SCANNED_SUCCESSFULLY' 
			SET @RETURNINT = 1
			RETURN		
		END

		
		ELSE IF @CONDITION = 'VALIDATE_SHOE'
		BEGIN
			IF EXISTS 
			(
				SELECT TOP 1 1 FROM ASSY_COUPLING_TEMP WITH (NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE 
				AND LINECODE = @LINECODE AND CHILD_BARCODE = @BARCODE AND PART_TYPE = 'BACKPLATE'
			)
			BEGIN
			    EXEC [ASSY_PROC_WRITEOPCTAGSAUTO] @P_MODE='WRITE_STATUS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@P_MACHINECODE=@MACHINECODE,@VALUE='15'
				EXEC [ASSY_PROC_WRITEOPCTAGSAUTO] @P_MODE='WRITE_BARCODE',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@P_MACHINECODE=@MACHINECODE,@VALUE=@BARCODE
				SET @RETURNVALUE = 'BACKPLATE_ALREADY_SCANNED_SCAN_SHOE_BARCODE'				  
				RETURN
			END
			IF EXISTS
			(
				SELECT TOP 1 1 FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE 
					AND LINECODE = @LINECODE AND CHILD_BARCODE = @BARCODE AND PART_TYPE = 'SHOE'
			) 
			BEGIN
				DECLARE @BP_BARCODE VARCHAR(200)
				SELECT @BP_BARCODE=CHILD_BARCODE FROM ASSY_COUPLING_TEMP WHERE PART_TYPE='BACKPLATE'
				EXEC [ASSY_PROC_WRITEOPCTAGSAUTO] @P_MODE='WRITE_STATUS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@P_MACHINECODE=@MACHINECODE,@VALUE='19'
				SET @RETURNVALUE = 'SHOE_HAS_ALREADY_BEEN_COUPLED|'+@BP_BARCODE;
				RETURN
			END 
			ELSE IF EXISTS(
			SELECT TOP 1 1 FROM ASSYBARCODEDATA WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE 
			AND LINECODE = @LINECODE AND (LEFTSHOEBARCODE =@BARCODE OR RIGHTSHOEBARCODE=@BARCODE)			
			) 
			BEGIN
			    DECLARE @BP_BARCODE_C2 VARCHAR(200)
				SELECT @BP_BARCODE_C2=CHILD_BARCODE FROM ASSY_COUPLING_TEMP WHERE PART_TYPE='BACKPLATE'
				EXEC [ASSY_PROC_WRITEOPCTAGSAUTO] @P_MODE='WRITE_STATUS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@P_MACHINECODE=@MACHINECODE,@VALUE='19'
				SET @RETURNVALUE = 'SHOE_HAS_ALREADY_BEEN_COUPLED|'+@BP_BARCODE_C2 ;
				RETURN		   
			END
			IF NOT EXISTS 
			(
				SELECT TOP 1 1 FROM ASSYBARCODEDATA WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND (LEFTSHOEBARCODE=@BARCODE OR RIGHTSHOEBARCODE=@BARCODE) 
				AND RESULT='OK' AND FGPARTNUMBER=@FG_PART_NO AND LINECODE=@LINECODE 
			)
			BEGIN
			EXEC [ASSY_PROC_WRITEOPCTAGSAUTO] @P_MODE='WRITE_STATUS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@P_MACHINECODE=@MACHINECODE,@VALUE='19'
				SET @RETURNVALUE = 'NO_SHOE_FOR_THIS_PART'				  
				RETURN
			END
			IF NOT EXISTS
			( 
				SELECT 1 CHILD_BARCODE FROM ASSY_COUPLING_TEMP(NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE 
				AND LINECODE = @LINECODE AND CHILD_BARCODE = @BARCODE AND PART_TYPE = 'SHOE'
			)
			BEGIN
				INSERT INTO ASSY_COUPLING_TEMP(PROFITCENTRECODE , LINECODE , STMC_PART_NO , CHILD_PART_NO , PART_TYPE , 
				MACHINE_CODE , OPERATION_CODE , TORQUE_1 , TORQUE_2 , ENT_DT , CHILD_BARCODE , ENT_BY)
				VALUES 
				(@PROFITCENTERCODE , @LINECODE , @FG_PART_NO , @CHILD_PART_NO , 'SHOE' , @MACHINECODE , @OPERATIONCODE , 
				@TORQUE_1 , @TORQUE_2 , GETDATE() , @BARCODE , @USERID)		
			END 
			ELSE
			BEGIN
				UPDATE ASSY_COUPLING_TEMP SET ENT_DT = GETDATE() , ENT_BY = @USERID 
				WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND CHILD_BARCODE = @BARCODE AND PART_TYPE = 'SHOE'
			END
			
			EXEC [ASSY_PROC_WRITEOPCTAGSAUTO] @P_MODE='WRITE_STATUS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@P_MACHINECODE=@MACHINECODE,@VALUE='11'
			EXEC [ASSY_PROC_WRITEOPCTAGSAUTO] @P_MODE='WRITE_SHOE_BARCODE',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@P_MACHINECODE=@MACHINECODE,@VALUE=@BARCODE
			SET @RETURNVALUE = 'SCANNED_SUCCESSFULLY' 
			SET @RETURNINT = 1
			

		END

		ELSE IF @CONDITION = 'INSERT_COUPLING_BARCODE_BACKPLATE'
		BEGIN 

			--SELECT @DATECODE=DATECODE FROM ASSY_RUNNINGPART(NOLOCK)
			DECLARE @FG_BARCODE VARCHAR(200)
			SELECT @FG_BARCODE=CHILD_BARCODE FROM ASSY_COUPLING_TEMP(NOLOCK) 
			WHERE PART_TYPE='BACKPLATE' AND PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
			AND MACHINE_CODE=@MACHINECODE AND OPERATION_CODE=@OPERATIONCODE

			--INSERT INTO ASSY_COUPLINGDETAILS 
			--(
			--	PROFITCENTRECODE , LINECODE , STMC_PART_NO , 
			--	CHILD_PART_NO , PART_TYPE , MACHINE_CODE , OPERATION_CODE , TORQUE_1 , TORQUE_2 , ENT_DT , ENT_BY , CHILD_BARCODE , FG_BARCODE , DATECODE
			--)
			--SELECT PROFITCENTRECODE , LINECODE , STMC_PART_NO , 
			--CHILD_PART_NO , PART_TYPE , MACHINE_CODE , OPERATION_CODE , TORQUE_1 , TORQUE_2 , ENT_DT , ENT_BY , CHILD_BARCODE , @FG_BARCODE , @DATECODE 
			--FROM ASSY_COUPLING_TEMP WITH (NOLOCK)
			--WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
				
			--DELETE THE RECORD FROM TEMP TABLE..
			--DELETE FROM ASSY_COUPLING_TEMP WHERE PROFITCENTRECODE = @PROFITCENTERCODE AND LINECODE = @LINECODE				
			SET @RETURNVALUE = 'SUCCESS|'+ @FG_BARCODE;
			RETURN
		END

		ELSE IF @CONDITION = 'CHECK_BACKPLATE_SCANNED'
		BEGIN
				IF EXISTS 
					(
						SELECT TOP 1 1 FROM ASSY_COUPLING_TEMP WITH (NOLOCK) WHERE PROFITCENTRECODE = @PROFITCENTERCODE 
						AND LINECODE = @LINECODE AND PART_TYPE = 'BACKPLATE' AND MACHINE_CODE=@MACHINECODE
					)
					BEGIN			    
						SET @RETURNVALUE = 'OK'				  
						RETURN
					END
				END
		-- CODE ENDED BY PRERNA TO VALIDATE BACKPLATE

	END TRY
	BEGIN CATCH
		SET @RETURNVALUE = 	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_SEVERITY() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
		CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_MESSAGE() AS VARCHAR(1500))								
		SET @RETURNINT = 2
		RAISERROR(@RETURNVALUE,16,1)
		--ROLLBACK TRAN
	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_Coupling_LabelInfo_GetData]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [dbo].[Assy_Proc_Coupling_LabelInfo_GetData]
(
@Condition varchar(60)=null,
@ProfitCenterCode varchar(20),
@Linecode varchar(30)='',
@ReturnValue VARCHAR (2000)=NULL OUT,
@ReturnInt INT=NULL OUT
)
--Author :<Ravishankar Mishra>
--created date:<17/07/2015>
--exec Assy_Proc_Coupling_LabelInfo_GetData @Condition='GET_LABEL_INFO',@ProfitCenterCode='0021',@Linecode='P2'
--select * from Assy_Coupling_LabelInfo_Mst
--select * from Assy_RunningPart
--select * from Assy_Coupling_Temp

AS
BEGIN
		SET NOCOUNT ON
		if @Condition='GET_LABEL_INFO'
		begin

					declare @ServoBarcode varchar(30)			   
					declare @ServoBarcodeLstFourDgtSeqNo varchar(10)			  
					declare @ShiftDate varchar(20)		
					declare @DateCode char(4)	 
					DECLARE  @CurrentTime  AS TIME
					,@Time         AS VARCHAR(10)
					,@Shift        AS VARCHAR(10)
					,@ShiftCode   VARCHAR(10)
					
					    select top 1 @DateCode=datecode,@CurrentTime=CreatedDate from Assy_RunningPart(nolock) where ProfitCenterCode =@ProfitCenterCode and LineCode =@Linecode  
						order by CreatedDate desc   
						--set @CurrentTime=getdate()
						set  @Time =left(@CurrentTime,8)
					
						exec Assy_PROC_ShiftMst @Current_Time=@Time ,@ProfitCenterCode=@ProfitCenterCode,@Current_Shift=@Shift OUTPUT,@ShiftCode=@ShiftCode output  
			              --SELECT @Shift,@ShiftCode  
						--Get Production Date from date code
						declare @DateFromDatecode as table
						(
						 CurrDate varchar(20),
						 FromTime varchar(10),
						 ToTime  varchar(10)
 						)
						insert into @DateFromDatecode(CurrDate,FromTime,ToTime)
						EXEC ASSY_PROC_GETDATE_FROMDATECODE @DATECODE=@DateCode,@ProfitCenterCode=@ProfitCenterCode
						--Get date like ddmmyy
						select @ShiftDate=FORMAT (convert(date,CurrDate),'ddMMyy') from @DateFromDatecode
			  
						--Get Servo barcode
						select top 1 @ServoBarcode= isnull(CHILD_Barcode,'') from Assy_Coupling_Temp with (nolock) where 
						ProfitCentreCode=@ProfitCenterCode and LineCode=@linecode
						and PART_TYPE='SERVO' order by ENT_DT desc
			   
						--Get servo last four digit sequence no. from servo barcode
						select @ServoBarcodeLstFourDgtSeqNo=RIGHT(isnull(SerialNo,''),4) from Assy_FN_Get_BarcodeParts_From_Barcode(@ProfitCenterCode,@Linecode,@ServoBarcode)	

						select rtrim(ltrim(cp.ProfitCenterCode))ProfitCenterCode,rtrim(ltrim(CP.PartNo))PartNo,rtrim(ltrim(cp.CustomerPartNo))CustomerPartNo,right(rtrim(ltrim(cp.PartNo)),4)STMCLastFourDgtPartNo,@ServoBarcodeLstFourDgtSeqNo ServoLstFourDgtSeqNo
						,@ShiftDate ShiftDate
						,@ShiftCode ShiftID,@Linecode Linecode,@DateCode DateCode
						,rtrim(ltrim(LabelDataName))LabelDataName,rtrim(ltrim(LabelDataValue))LabelDataValue from  Assy_Coupling_LabelInfo_Mst(nolock) CP
						join Assy_RunningPart(nolock) RP on  cp.PartNo =rp.Assy_PartNo and cp.CustomerPartNo =rp.CustomerPartNo and CP.ProfitCenterCode=rp.ProfitCenterCode
						where CP.ProfitCenterCode=@ProfitCenterCode and RP.LineCode =@Linecode and RP.assy_mode IN ('Production','Rework')
						set @ReturnInt=1
		END
END
GO
