CREATE PROCEDURE [dbo].[Assy_Proc_DashBoard]
(
	@CONDITION			VARCHAR(100)=NULL,
	@LineCode			VARCHAR(20)=NULL,
	@operationCode		VARCHAR(50)=NULL,
	@PartNo				VARCHAR(10)=NULL,
	@DateCode		VARCHAR(20)=NULL,
	@MachineCode 			VARCHAR(50)=NULL,
	@ReturnValue		VARCHAR (2000)=NULL OUT,
	@ReturnInt			INT=NULL OUT
)
AS
BEGIN
-- Author:		SUNDARA MOORTHI
-- Create date: 02-02-2016
-- Description:	Dashboard details procedure
-- Modified date: 22-Sep-2016
-- Description:	Dashboard details procedure
-- =============================================
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	 BEGIN TRY

		DECLARE @Qry				VARCHAR (2000)='';
		DECLARE @Barcode			VARCHAR(50)=NULL;
		DECLARE @PartNumber			VARCHAR(20)=NULL;
		DECLARE @OperationName		VARCHAR(50)=NULL;
		DECLARE @profitCenterCode	VARCHAR(10)=NULL;
		DECLARE @plannedQty			VARCHAR(10)=NULL;
		DECLARE @prevDate			varchar(20)
		DECLARE @FAILQTY			INT=0;
		DECLARE @lastDayDate       varchar(20)=NULL;
		DECLARE @TOTAL_QTY VARCHAR(10)
		DECLARE @PASS_QTY VARCHAR(10)
					
		
				IF OBJECT_ID('tempdb..#TEMP_DASHBOARD_DATA_TABLE') IS NOT NULL
			DROP TABLE #TEMP_DASHBOARD_DATA_TABLE
		

			CREATE TABLE [dbo].[#TEMP_DASHBOARD_DATA_TABLE](
			[Barcode] [varchar](100) NOT NULL,
			[TagName] [varchar](50) NOT NULL,
			[Value] [varchar](60) NULL,
			[TagId] [int] NOT NULL,
			[LineCode] [varchar](10) NOT NULL,
			[StationCode] [varchar](10) NOT NULL,
			[Datecode] [char](4) NOT NULL,
			[MachineCode] [varchar](20) NOT NULL,
			[OperationCode] [varchar](10) NOT NULL,
			[ProfitCenterCode] [varchar](10) NOT NULL,
			[Result] [varchar](5) NOT NULL,
			[Timestamp] [datetime] NOT NULL,
			[PartNo] [varchar](60) NULL
			) ON [PRIMARY]


		SELECT TOP 1 @PartNumber=assy_partno , @datecode=Datecode ,@profitCenterCode=ProfitCenterCode,
		@plannedQty=convert(varchar,CurrentPlannedQty)
		  FROM ASSY_RUNNINGPART(NOLOCK) 
		WHERE LineCode=@LineCode

		create table #PassCount 
					(
					  PassCount varchar(10)
					)

		IF OBJECT_ID('tempdb..#tbMachineDetails') IS NOT NULL
				DROP TABLE #tbMachineDetails
				
				SELECT	DISTINCT mm.MachineCode
						,mm.MachineName
						,rclw.OperationSeqNo 
				INTO #tbMachineDetails 
				FROM  MachineMst mm(NOLOCK)
				JOIN RoutingConfigLinewise rclw(NOLOCK)  ON mm.MachineCode=rclw.MachineCode
				WHERE	rclw.Traceability=1
						AND LineCode=@LineCode 
				ORDER BY rclw.OperationSeqNo
		
	IF(@CONDITION='GET_PASS_COUNT')
			BEGIN
			DECLARE @PASSQTY VARCHAR(10)
					--SELECT	ISNULL(ARP.LineCode,0) AS LineCode
					--		,ISNULL(ARP.DateCode,0) AS DateCode
					--		,ISNULL(ARP.Assy_PartNo,0) AS PartNo
					--		,ISNULL(APPFC.PassQty,0) AS PassQty
					--		--,SUM(CASE WHEN ALAS.FailCount>0 THEN 1 ELSE 0 END)AS FailQty 
					--FROM Assy_PartWise_PassFail_Count(NOLOCK) APPFC
					--INNER	JOIN Assy_RunningPart ARP ON ARP.Datecode=APPFC.DateCode
					--		AND  ARP.Assy_PartNo=APPFC.PartNo
					--		AND ARP.ProfitcenterCode=APPFC.ProfitCenterCode
					--WHERE ARP.LineCode=@LineCode 
					--GROUP BY ARP.LineCode,ARP.Datecode,ARP.Assy_PartNo,APPFC.PassQty
					
					--SELECT SUM(ISNULL(APPFC.PassQty,0)) AS QTY
					--FROM Assy_PartWise_PassFail_Count(NOLOCK) APPFC
					--INNER	JOIN Assy_RunningPart ARP ON ARP.Datecode=APPFC.DateCode
					--		AND ARP.ProfitcenterCode=APPFC.ProfitCenterCode
					--WHERE ARP.LineCode=@LineCode 
					----GROUP BY ARP.LineCode,ARP.Datecode,APPFC.PassQty

					EXEC @MachineCode =[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode @PROFITCENTERCODE=@profitCenterCode,
					@LineCode=@LineCode

					INSERT INTO #TEMP_DASHBOARD_DATA_TABLE
					EXEC  ASSY_PROC_VIEW_DATA @LINECODE,@PROFITCENTERCODE,@PARTNUMBER,@DATECODE,'GET_DATECODE_PARTWISE_DATA'

					select 
					@lineCode AS LineCode ,
					@datecode AS DateCode ,
					@PartNumber AS PartNo, 
					count(distinct Barcode) AS  PassQty 
					from #TEMP_DASHBOARD_DATA_TABLE 
					where result='PS'
					and machinecode=@MachineCode
					group by result

					select 	count(distinct Barcode) AS  QTY 
					from #TEMP_DASHBOARD_DATA_TABLE 
					where result='PS'
					and machinecode=@MachineCode
					group by result

					SET @ReturnValue='SUCCESS'
					SET @ReturnInt=0
				END
	ELSE IF(@CONDITION='GET_FAIL_COUNT')
			BEGIN
			--		SET @ReturnValue=(SELECT	ISNULL(COUNT(Barcode),0) FROM Assy_LineAssyStatus (NOLOCK)
			--								WHERE	Datecode=@DateCode
			--										and FailCount=5 
			--										and LineCode=@LineCode
			--										and PartNo=@PartNo)

					--SELECT @ReturnValue=SUM(ISNULL(APPFC.FailQty,0)) 
					--FROM Assy_PartWise_PassFail_Count(NOLOCK) APPFC
					--INNER	JOIN Assy_RunningPart(nolock) ARP ON ARP.Datecode=APPFC.DateCode
					--		AND ARP.ProfitcenterCode=APPFC.ProfitCenterCode
					--WHERE ARP.LineCode=@LineCode

					EXEC @MachineCode =[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode @PROFITCENTERCODE=@profitCenterCode,
					@LineCode=@LineCode

					INSERT INTO #TEMP_DASHBOARD_DATA_TABLE
					EXEC  ASSY_PROC_VIEW_DATA @LINECODE,@PROFITCENTERCODE,@PARTNUMBER,@DATECODE,'GET_DATECODE_PARTWISE_DATA'

					

					select distinct Barcode into #TEMP_BARCODE  
					from #TEMP_DASHBOARD_DATA_TABLE 
					where linecode=@lineCode and 
					datecode=@datecode and 
					result='PS' and 
					machinecode=@MachineCode and
					ProfitCenterCode=@profitCenterCode 

					select @ReturnValue=count(distinct Barcode) 
					from #TEMP_DASHBOARD_DATA_TABLE 
					where linecode=@lineCode and 
					datecode=@datecode and 
					result='FL' and 
					ProfitCenterCode=@profitCenterCode and 
					PartNo=@PartNumber
					AND BARCODE NOT IN (select * from #TEMP_BARCODE)
					group by result

				
				SET @ReturnInt=1
				END
	ELSE IF(@CONDITION='GET_LINE_HEADER')
			BEGIN
					IF (SELECT COUNT(*) FROM  Assy_RunningPart WITH (NOLOCK))=1
						BEGIN
							SET @ReturnValue=(SELECT LM.LineName + '(' +LM.LineCode + ') is running in ' + ARP.Assy_Mode FROM Assy_RunningPart ARP
											INNER	JOIN LineMst LM ON ARP.LineCode=LM.LineCode
													AND ARP.ProfitCenterCode=LM.ProfitCenterCode
											  WHERE ARP.LineCode=@LineCode)
						END
					ELSE
						BEGIN
							SET @ReturnValue = 	(SELECT LineName FROM  LineMst (NOLOCK) WHERE LineCode =  @LineCode) + '(' + @LineCode + ') is not running in any mode.'					
						END
					SET @ReturnInt=0
				END
	ELSE IF(@CONDITION='GET_SHIFT_HISTORY') --GET_RUNNING_HISTORY
			BEGIN
					--SELECT	ISNULL(APPFC.LineCode,0) AS LineCode
					--		,ISNULL(APPFC.DateCode,0) AS DateCode
					--		,ISNULL(APPFC.PartNo,0)   AS PartNo
					--		,ISNULL(APPFC.TotalQty,0) AS PlannedQty
					--		--,(ISNULL(APPFC.PassQty,0) + SUM(CASE WHEN ALAS.FailCount>0 THEN 1 ELSE 0 END)) AS TotalProducedQty
					--		,ISNULL(APPFC.PassQty,0) AS PassQty
					--		--,SUM(CASE WHEN ALAS.FailCount>0 THEN 1 ELSE 0 END)AS FailQty 
					--FROM Assy_PartWise_PassFail_Count(nolock) APPFC
					--WHERE	APPFC.LineCode=@LineCode
					--		AND APPFC.DateCode=@DateCode
					--		AND APPFC.PassQty>0
					--GROUP BY APPFC.LineCode,APPFC.Datecode,APPFC.PartNo,APPFC.PassQty,APPFC.TotalQty
					
					EXEC @MachineCode =[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode @PROFITCENTERCODE=@profitCenterCode,
					@LineCode=@LineCode

					INSERT INTO #TEMP_DASHBOARD_DATA_TABLE
					EXEC  ASSY_PROC_VIEW_DATA @LINECODE,@PROFITCENTERCODE,@PARTNUMBER,@DATECODE,'GET_DATECODE_PARTWISE_DATA'


					select 
					@lineCode AS LineCode ,
					@datecode AS DateCode ,
					@PartNumber AS PartNo, 
					@plannedQty AS PlannedQty,
					count(distinct Barcode) AS  PassQty 
					from #TEMP_DASHBOARD_DATA_TABLE 
					where linecode=@lineCode and 
					datecode=@datecode and 
					result='PS' and 
					ProfitCenterCode=@profitCenterCode and 
					PartNo=@PartNumber and 
					Machinecode=@MachineCode
					group by result
					
					SET @ReturnValue='SUCCESS'
					SET @ReturnInt=0
				END
	ELSE IF(@CONDITION='GET_SHIFT_HISTORY_FAILQTY') --GET_RUNNING_HISTORY
		BEGIN
				SET @ReturnValue=(SELECT (ISNULL(COUNT(ATCSDH.BARCODE),0) + (SELECT	ISNULL(COUNT(Barcode),0) FROM Assy_LineAssyStatus (NOLOCK)
											WHERE	Datecode=@DateCode
													and FailCount=5 
													and LineCode=@LineCode
													and PartNo=@PartNo)) AS FailQty 
				FROM Assy_TallyChartStatusData_History ATCSDH WITH (NOLOCK) 
				WHERE	ATCSDH.Datecode=@DateCode
						AND ATCSDH.LineCode=@LineCode
						AND ATCSDH.PartNo=@PartNo
						AND ISNULL(Reason,'')<>'' 
						AND NotProcessedStatus<>'SCRAP')
				
				SET @ReturnInt=1
			END
	ELSE IF(@CONDITION='GET_LASTSHIFT_HISTORY')
		BEGIN
				DECLARE @PrevDateCode char(4);
			
				--SELECT @PrevDateCode=TB.DATECODE FROM (SELECT  DISTINCT DENSE_RANK() OVER (PARTITION BY LineCode  ORDER BY DATECODE DESC) AS RANK_ID,DATECODE,ProfitCenterCode,LineCOde from Assy_LineAssyStatus(NOLOCK)) TB
				--	WHERE TB.RANK_ID=2 and LineCode=@LineCode

				
				SELECT TOP 1 @PrevDateCode=Datecode FROM Assy_LineAssyStatus(NOLOCK) TB
				WHERE	LineCode=@LineCode
						AND Datecode<>@DateCode
				ORDER BY TB.ResultTimeStamp DESC

				SELECT	ISNULL(APPFC.DateCode,0) AS DateCode,
						ISNULL(APPFC.PartNo,0) AS PartNo
						--,ISNULL(APPFC.PassQty,0) AS TotalProducedQty
						,ISNULL(APPFC.PassQty,0) AS PassQty
						--,SUM(CASE WHEN ALAS.FailCount>0 THEN 1 ELSE 0 END)AS FailQty 
				FROM Assy_PartWise_PassFail_Count(NOLOCK) APPFC
				WHERE	APPFC.LineCode=@LineCode
						AND APPFC.DateCode=@PrevDateCode
				GROUP BY APPFC.LineCode,APPFC.Datecode,APPFC.PartNo,APPFC.PassQty,APPFC.TotalQty
					--ORDER BY Timestamp ASC

				SET @ReturnValue='SUCCESS'
				SET @ReturnInt=1
			END
	ELSE IF(@CONDITION='GET_LASTSHIFT_HISTORY_FAILQTY') --GET_RUNNING_HISTORY
		BEGIN
			
			SELECT TOP 1 @PrevDateCode=Datecode FROM Assy_LineAssyStatus(NOLOCK) TB
				WHERE	LineCode=@LineCode
						AND Datecode<>@DateCode
				ORDER BY TB.ResultTimeStamp DESC

				SET @ReturnValue=(SELECT (ISNULL(COUNT(ATCSDH.BARCODE),0) + (SELECT	ISNULL(COUNT(Barcode),0) FROM Assy_LineAssyStatus (NOLOCK)
											WHERE	Datecode=@PrevDateCode
													and FailCount=5 
													and LineCode=@LineCode
													and PartNo=@PartNo)) AS FailQty 
				FROM Assy_TallyChartStatusData_History ATCSDH WITH (NOLOCK) 
				WHERE	ATCSDH.Datecode=@PrevDateCode
						AND ATCSDH.LineCode=@LineCode
						AND ATCSDH.PartNo=@PartNo
						AND ISNULL(Reason,'')<>'' 
						AND NotProcessedStatus<>'SCRAP')
				
				SET @ReturnInt=1
			END
	ELSE IF(@CONDITION='GET_LASTMONTH_PRODUCTION')
		BEGIN

					EXEC @MachineCode =[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode 
					@PROFITCENTERCODE=@profitCenterCode,
					@LineCode=@LineCode
					
					INSERT INTO #TEMP_DASHBOARD_DATA_TABLE
					EXEC  ASSY_PROC_VIEW_DATA @LINECODE,@PROFITCENTERCODE,@PARTNUMBER,@DATECODE,'LASTMONTH_PRODUCTION'

					select @PASS_QTY=count(distinct Barcode) 
					from #TEMP_DASHBOARD_DATA_TABLE 
					where 
					result='PS' and 
					machinecode=@MachineCode
					group by result
					
					select @TOTAL_QTY=count(distinct Barcode) 
					from #TEMP_DASHBOARD_DATA_TABLE 
					where result in ('PS','FL') and
					machinecode=@MachineCode
					--group by result
					
					SELECT @TOTAL_QTY AS TotalProducedQty , @PASS_QTY AS PassQty

				--EXEC @MachineCode =[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode @PROFITCENTERCODE='0021',@LineCode=@LineCode
				
				--DECLARE @FAILQTY   INT=0;

				----Get Fail Quatity for the previous month
				--SET @FAILQTY =(SELECT (ISNULL(COUNT(ATCSDH.BARCODE),0) + (SELECT	ISNULL(COUNT(Barcode),0) FROM Assy_LineAssyStatus (NOLOCK)
				--							WHERE	CONVERT(VARCHAR(7),ResultTimestamp,126)=CONVERT(VARCHAR(7), DATEADD(MM,-1,GETDATE()),126)
				--									and FailCount=5 
				--									and LineCode=@LineCode
				--									)) AS FailQty 
				--				FROM Assy_TallyChartStatusData_History ATCSDH WITH (NOLOCK) 
				--				WHERE	CONVERT(VARCHAR(7),Timestamp,126)=CONVERT(VARCHAR(7), DATEADD(MM,-1,GETDATE()),126) 
				--						AND ATCSDH.LineCode=@LineCode
				--						AND ISNULL(Reason,'')<>'' 
				--						AND NotProcessedStatus<>'SCRAP')

				--SELECT	(ISNULL(SUM(CASE WHEN ALAS.STATUS='PS' AND ALAS.MachineCode=@MachineCode  THEN 1 ELSE 0 END),0) 
				--		+ @FAILQTY)  AS TotalProducedQty
				--		,ISNULL(SUM(CASE WHEN ALAS.STATUS='PS' AND ALAS.MachineCode=@MachineCode  THEN 1 ELSE 0 END),0) AS PassQty
				--		--,ISNULL(SUM(CASE WHEN ISNULL(ALAS.FailCount,0)>0 THEN 1 ELSE 0 END),0) AS FailQty
				--FROM ASSY_LINEASSYSTATUS(NOLOCK) ALAS
				--WHERE ALAS.LineCode=@LineCode
				--	AND CONVERT(VARCHAR(7),ResultTimestamp,126)=CONVERT(VARCHAR(7), DATEADD(MM,-1,GETDATE()),126)
			
			
				SET @ReturnValue='SUCCESS'
				SET @ReturnInt=1
			END
	ELSE IF(@CONDITION='GET_CURRENTMONTH_PRODUCTION')
		BEGIN

			
			
					
					EXEC @MachineCode =[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode 
					@PROFITCENTERCODE=@profitCenterCode,
					@LineCode=@LineCode
					
					INSERT INTO #TEMP_DASHBOARD_DATA_TABLE
					EXEC  ASSY_PROC_VIEW_DATA @LINECODE,@PROFITCENTERCODE,@PARTNUMBER,@DATECODE,'CURRENTMONTH_PRODUCTION'

					select @PASS_QTY=count(distinct Barcode) 
					from #TEMP_DASHBOARD_DATA_TABLE 
					where 
					result='PS' and 
					machinecode=@MachineCode
					group by result
					
					select @TOTAL_QTY=count(distinct Barcode) 
					from #TEMP_DASHBOARD_DATA_TABLE 
					where result in ('PS','FL')
					group by result
					
					SELECT isnull(@TOTAL_QTY,'0') AS TotalProducedQty , isnull(@PASS_QTY,'0') AS PassQty


			--	EXEC @MachineCode =[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode @PROFITCENTERCODE='0021',@LineCode=@LineCode
			
			----Get Fail Quatity for the current month
			--SET @FAILQTY=(SELECT (ISNULL(COUNT(ATCSDH.BARCODE),0) + (SELECT	ISNULL(COUNT(Barcode),0) FROM Assy_LineAssyStatus (NOLOCK)
			--								WHERE	CONVERT(VARCHAR(7),ResultTimestamp,126)=CONVERT(VARCHAR(7), GETDATE(),126)
			--										and FailCount=5 
			--										and LineCode=@LineCode
			--										)) AS FailQty 
			--	FROM Assy_TallyChartStatusData_History ATCSDH WITH (NOLOCK) 
			--	WHERE	CONVERT(VARCHAR(7),Timestamp,126)=CONVERT(VARCHAR(7), GETDATE(),126) 
			--			AND ATCSDH.LineCode=@LineCode
			--			AND ISNULL(Reason,'')<>'' 
			--			AND NotProcessedStatus<>'SCRAP')


			--	SELECT	(ISNULL(SUM(CASE WHEN ALAS.STATUS='PS' AND ALAS.MachineCode=@MachineCode  THEN 1 ELSE 0 END),0) 
			--			+ @FAILQTY)  AS TotalProducedQty
			--			,ISNULL(SUM(CASE WHEN ALAS.STATUS='PS' AND ALAS.MachineCode=@MachineCode THEN 1 ELSE 0 END),0) AS PassQty
			--			--,ISNULL(SUM(CASE WHEN ISNULL(ALAS.FailCount,0)>0 THEN 1 ELSE 0 END),0) AS FailQty
			--	FROM ASSY_LINEASSYSTATUS(NOLOCK) ALAS
			--	WHERE ALAS.LineCode=@LineCode
			--		AND CONVERT(VARCHAR(7),ResultTimestamp,126)=CONVERT(VARCHAR(7), GETDATE(),126)
			
				SET @ReturnValue='SUCCESS'
				SET @ReturnInt=1
			END
	ELSE IF(@CONDITION='GET_CURRENT_PROCESS_BARCODE')
		BEGIN
					DECLARE @MachineCode1 VARCHAR(20);

					EXEC @MachineCode1 =[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode @PROFITCENTERCODE='0021',@LineCode=@LineCode
					IF(@MachineCode <>@MachineCode1)
						BEGIN
							SET @ReturnValue=(SELECT TOP 1 BARCODE FROM Assy_LineAssyStatus_Running WITH (NOLOCK) WHERE MachineCode=@MachineCode AND CHARINDEX('PKYK',Barcode) = 0 ORDER BY ScanTimestamp DESC)
							SET @ReturnInt=1
						END
					ELSE
						BEGIN
							SET @ReturnValue=(SELECT TOP 1 BARCODE FROM Assy_LineAssyStatus WITH (NOLOCK) WHERE MachineCode=@MachineCode  AND DateCode=@DateCode AND CHARINDEX('PKYK',Barcode) = 0  ORDER BY ScanTimestamp DESC)
							SET @ReturnInt=1
						END
				END
	ELSE IF(@CONDITION='FTT_QTY')
		BEGIN
						IF(CHARINDEX('M',@LINECODE)=1 OR CHARINDEX('L',@LINECODE)=1)
							BEGIN
								SELECT	tb.PartNo
										,COUNT(tb.Barcode) AS TotalQty FROM 
											(SELECT DISTINCT(Barcode), PartNo,SUM(FailCount) AS TotalQty  FROM Assy_LineAssyStatus(NOLOCK)
												WHERE DateCode=@DateCode AND Linecode=@LineCode
													GROUP BY Barcode,PartNo 
														HAVING SUM(FailCount)=0) AS tb
														JOIN Assy_LineAssyStatus ALAS(NOLOCK) ON tb.PartNo=ALAS.PartNo AND tb.Barcode=ALAS.Barcode AND ALAS.MachineCode='MCFV'
								GROUP BY tb.Partno ORDER BY PartNo ASC
							END
						ELSE if CHARINDEX('P',@LINECODE)=1
							BEGIN
								IF OBJECT_ID('tempdb..#tmpFailBooster') IS NOT NULL
									DROP TABLE #tmpFailBooster
										
									SELECT	DISTINCT(alas.Barcode)
											,alas.PartNo,SUM(alas.FailCount) AS TotalQty
											,alas.MachineCode 
									INTO #tmpFailBooster  FROM Assy_LineAssyStatus alas(NOLOCK)
									JOIN  Assy_CouplingDetails acd(NOLOCK)  ON acd.Child_Barcode=alas.Barcode
									JOIN Assy_LineAssyStatus ALA(NOLOCK) ON alas.PartNo=ALAS.PartNo AND alas.Barcode=ALA.Barcode AND ALA.MachineCode='MCFVSTMC'
									WHERE	alas.DateCode=@DateCode
											AND alas.Linecode=@Linecode
									GROUP BY alas.Barcode,alas.PartNo,alas.MachineCode
									HAVING SUM(alas.FailCount)>0

								IF OBJECT_ID('tempdb..#tmpFailBooster1') IS NOT NULL
									DROP TABLE #tmpFailBooster1
									
									SELECT	DISTINCT(alas.Barcode)
											,PartNo
											,SUM(FailCount) AS TotalQty
											,MachineCode 
									INTO #tmpFailBooster1 FROM Assy_LineAssyStatus(NOLOCK) alas
									JOIN  Assy_CouplingDetails acd(NOLOCK)  ON acd.FG_Barcode=alas.Barcode
									WHERE	alas.DateCode=@DateCode
											AND alas.Linecode=@Linecode
									GROUP BY alas.Barcode,PartNo,MachineCode
									HAVING SUM(FailCount)>0
								
								SELECT STMC_PART_NO AS Partno,COUNT(FG_Barcode) AS TotalQty FROM Assy_CouplingDetails(NOLOCK) 
									WHERE	FG_Barcode NOT IN (SELECT Barcode FROM  #tmpFailBooster1)
											AND Child_Barcode NOT IN (SELECT Barcode FROM  #tmpFailBooster)
											AND FG_Barcode IN (SELECT Barcode FROM Assy_LineAssyStatus(NOLOCK) WHERE DateCode=@DateCode AND LineCode=@Linecode)
											AND DateCode=@DateCode
											AND LineCode=@Linecode
											AND Part_Type='SERVO'
									GROUP BY STMC_PART_NO ORDER BY STMC_PART_NO ASC
							END
					END
	ELSE IF(@CONDITION='MONTHLY_PRODUCTION_QTY')
		BEGIN
					
					--2017-01-06 11:24:34.143
					SET @prevDate= convert(varchar,year(getdate())) + '-'+convert(varchar,month(getdate()))+'-'+
					convert(varchar,1)+' 00:00:00.000'
					
					EXEC @MachineCode =[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode 
					@PROFITCENTERCODE=@profitCenterCode,
					@LineCode=@LineCode
					
					

					set @Qry=
					'
					select count(distinct Barcode) AS PASSQTY
					from Assy_View_ParamData 
					where linecode='+''''+@lineCode+''''+' and 
					result='+''''+'PS'+''''+' and 
					machinecode='+''''+@MachineCode+''''+' and
					ProfitCenterCode='+''''+@profitCenterCode+''''+' and 
					PartNo='+''''+@PartNumber+''''+' and
					Timestamp between '+''''+ @prevDate+''''+' and getdate()
					group by result
					
					'
					

					--print @qry
					insert into #PassCount
					exec sp_sqlexec @Qry

					
					SELECT @RETURNVALUE=ISNULL(PASSCOUNT,'') FROM #PASSCOUNT

						
						--SET @ReturnValue=(SELECT COUNT(Barcode) FROM Assy_LineAssyStatus(NOLOCK)
						--WHERE	Linecode=@LineCode
						--		AND PartNo=@PartNo
						--		AND CONVERT(VARCHAR(7),ResultTimestamp,126)=CONVERT(VARCHAR(7),GETDATE(),126)
						--		AND MachineCode=@MachineCode )
						----GROUP BY PartNo
				
				SET @ReturnInt = 1
		END
	ELSE IF(@CONDITION='WIP')
		BEGIN
					Declare @Assy_WIP AS Table(
									LineCode varchar(10) NULL,
									MachineCode varchar(20) NULL,
									WIPCount int NULL)

			

			Declare @PartType_WIP VARCHAR(30) = '';
			DECLARE @RowCount_Qty INT=0;
			DECLARE @FailCountDefined INT =5;
			--DECLARE @ProfitCenterCode VARCHAR(20)='';
			SELECT Top 1 @PartType_WIP = LTRIM(RTRIM(PartType)), @ProfitCenterCode=ProfitCenterCode FROM Assy_RunningPart (NOLOCK)
			IF @PartType_WIP = 'STMC'
			BEGIN
				IF OBJECT_ID('tempdb..#STMC_Final_Data_Qty') IS NOT NULL
				BEGIN
					DROP TABLE #STMC_Final_Data_Qty
				END
				IF OBJECT_ID('tempdb..#STMC_WIPMST_Qty') IS NOT NULL
				BEGIN
					DROP TABLE #STMC_WIPMST_Qty
				END
				SELECT ROW_NUMBER() OVER(ORDER BY OperationSeqNo) Seq, LineCode, Machinecode, OperationSeqNo, WIP_Quantity  
					INTO #STMC_WIPMST_Qty
						FROM (
							SELECT  ROW_NUMBER() OVER(PARTITION BY RCLW.MachineCode ORDER BY RCLW.OperationSeqNo) AS SeqNo,
									RCLW.LineCode, RCLW.MachineCode, RCLW.OperationSeqNo, RCLW.WIP_Quantity
										FROM RoutingConfigLineWise (NOLOCK) RCLW
										JOIN
										RoutingConfigPartWise (NOLOCK) RCPW
											ON	RCLW.ProfitCenterCode=RCPW.ProfitCenterCode AND
													RCLW.MachineCode = RCPW.MachineCode AND
														RCLW.OperationCode = RCPW.OperationCode AND
															RCLW.Traceability = RCPW.Traceability
																	
										JOIN
										LineMst (NOLOCK) LM
											ON	RCLW.ProfitCenterCode = LM.ProfitCenterCode AND
													RCLW.LineCode = LM.LineCode
											WHERE ISNULL(RCLW.Traceability,0) = 1 AND
													RCPW.PartNo = (SELECT Top 1 Assy_PartNo FROM ASSY_RUNNINGPART (NOLOCK) WHERE LineCode = @LineCode ORDER BY CreatedDate Desc) AND
														RCLW.WIP_Quantity <> 0 AND
															--ISNULL(LM.WIPCheck,0) = 1 AND
																ISNULL(LM.isActive,0) = 1 AND
																	ISNULL(RCPW.Traceability,0) = 1
																		AND LM.ProfitCenterCode = @ProfitCenterCode
																			AND LM.LineCode = @LineCode
																					
										) Source WHERE SeqNo = 1
			
				IF OBJECT_ID('tempdb..#STMC_Assy_LineAssyStatus_Running_WIP_Qty') IS NOT NULL
				BEGIN
					DROP TABLE #STMC_Assy_LineAssyStatus_Running_WIP_Qty
				END

				SELECT LineCode, MachineCode, Case WHEN CHARINDEX(':',Barcode) > 0 THEN RIGHT(Barcode,4) ELSE LEFT(RIGHT(Barcode,6),4) END Barcode, Status, FailCount INTO #STMC_Assy_LineAssyStatus_Running_WIP_Qty FROM Assy_LineAssyStatus_Running (NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(Status,'') != '' AND Datecode != 'PKYK'
						AND Barcode NOT IN (SELECT Distinct Barcode FROM Assy_TallyChartStatusData WITH (NOLOCK)
							WHERE ISNULL(Result,'') = '' AND ISNULL(NotProcessedStatus,'') = 'SCRAP' AND ISNULL(Assy_Auth,0) = 0
								AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode)
						ORDER BY 1

				IF ((OBJECT_ID('tempdb..#STMC_WIPMST_Qty') IS NOT NULL) AND (OBJECT_ID('tempdb..#STMC_Assy_LineAssyStatus_Running_WIP_Qty') IS NOT NULL))
				BEGIN
					SELECT W.Seq, W.LineCode, W.MachineCode, R.Barcode, R.Status, R.FailCount INTO #STMC_Final_Data_Qty FROM #STMC_WIPMST_Qty (NOLOCK) W
						LEFT OUTER JOIN #STMC_Assy_LineAssyStatus_Running_WIP_Qty (NOLOCK) R
							ON W.LineCode = R.LineCode AND W.MachineCode = R.MachineCode
								WHERE ISNULL(R.Status,'') != ''
				END

				--SELECT * FROM #Final_Data Order by 1,2,4
				

				SET @RowCount_Qty = (SELECT MAX(Seq) FROM #STMC_Final_Data_Qty);
					DECLARE @RowSeq1 INT = 1;
				WHILE @RowSeq1 <= @RowCount_Qty
				BEGIN
					Declare @SecondLastSeq1 INT = 0
					SELECT Top 1 @SecondLastSeq1 = Seq FROM #STMC_WIPMST_Qty Order by Seq Desc
					DELETE FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 AND Barcode IN (SELECT Barcode FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 + 1 AND ISNULL(Status,'') != 'FL')
					DELETE FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 AND Barcode IN (SELECT Barcode FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 + 1 AND ISNULL(Status,'') = 'FL')
					DELETE FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 AND Barcode IN (SELECT Barcode FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 + 1 AND ISNULL(Status,'') = 'FL' AND FailCount = @FailCountDefined) AND Seq != @SecondLastSeq1 - 1
					DELETE FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 + 1 AND ISNULL(Status,'') = 'FL' --AND FailCount = @FailCountDefined 
					SET @RowSeq1 = @RowSeq1 + 1
				END
				--SELECT * FROM #STMC_Final_Data_Qty WHERE MachineCode = (SELECT Top 1 MachineCode FROM MachineMst (NOLOCK) WHERE UPPER(MachineName) = UPPER(@MachineName))
				IF OBJECT_ID('tempdb..#N_Final_Data_Qty_WIP1') IS NOT NULL
				BEGIN
					DROP TABLE #N_Final_Data_Qty_WIP1
				END
				
				SELECT LineCode, MachineCode, Count(*) Qty INTO #N_Final_Data_Qty_WIP1 FROM #STMC_Final_Data_Qty
					Group By LineCode, MachineCode
					
				IF OBJECT_ID('tempdb..#N_Final_Data_Qty_WIP1') IS NOT NULL
				BEGIN
					DELETE FROM @Assy_WIP
					
					INSERT INTO @Assy_WIP
					SELECT Distinct LineCode, MachineCode, 0 FROM #STMC_WIPMST_Qty --ORDER BY Seq ASC

					Update AW SET AW.WIPCount = N.Qty
					FROM @Assy_WIP AW
					JOIN #N_Final_Data_Qty_WIP1 N
					ON AW.LineCode = N.LineCode AND AW.MachineCode = N.MachineCode
					
					SELECT  DISTINCT AW.LineCode,MM.MachineCode,MM.MachineName,AW.WIPCount,RCLW.OperationSeqNo FROM @Assy_WIP AW
					JOIN MachineMst MM ON AW.MachineCode=MM.MachineCode
					JOIN RoutingConfigLineWise RCLW ON AW.MachineCode=RCLW.MachineCode
					ORDER BY RCLW.OperationSeqNo
				END
			END
			ELSE IF @PartType_WIP IN ('TMC','SERVO')
			BEGIN
				IF OBJECT_ID('tempdb..#N_Final_Data_Qty') IS NOT NULL
				BEGIN
					DROP TABLE #N_Final_Data_Qty
				END
				IF OBJECT_ID('tempdb..#N_WIPMST_Qty') IS NOT NULL
				BEGIN
					DROP TABLE #N_WIPMST_Qty
				END
				SELECT ROW_NUMBER() OVER(ORDER BY OperationSeqNo) Seq, LineCode, Machinecode, OperationSeqNo, WIP_Quantity  
					INTO #N_WIPMST_Qty
						FROM (
							SELECT  ROW_NUMBER() OVER(PARTITION BY RCLW.MachineCode ORDER BY RCLW.OperationSeqNo) AS SeqNo,
									RCLW.LineCode, RCLW.MachineCode, RCLW.OperationSeqNo, RCLW.WIP_Quantity
										FROM RoutingConfigLineWise (NOLOCK) RCLW
										JOIN
										RoutingConfigPartWise (NOLOCK) RCPW
											ON	RCLW.ProfitCenterCode=RCPW.ProfitCenterCode AND
													RCLW.MachineCode = RCPW.MachineCode AND
														RCLW.OperationCode = RCPW.OperationCode AND
															RCLW.Traceability = RCPW.Traceability
																	
										JOIN
										LineMst (NOLOCK) LM
											ON	RCLW.ProfitCenterCode = LM.ProfitCenterCode AND
													RCLW.LineCode = LM.LineCode
											WHERE ISNULL(RCLW.Traceability,0) = 1 AND
													RCPW.PartNo = (SELECT Top 1 Assy_PartNo FROM ASSY_RUNNINGPART (NOLOCK) WHERE LineCode = @LineCode ORDER BY CreatedDate Desc) AND
														RCLW.WIP_Quantity <> 0 AND
															--ISNULL(LM.WIPCheck,0) = 1 AND
																ISNULL(LM.isActive,0) = 1 AND
																	ISNULL(RCPW.Traceability,0) = 1
																		AND LM.ProfitCenterCode = @ProfitCenterCode
																			AND LM.LineCode = @LineCode
																					
										) Source WHERE SeqNo = 1
			
				IF OBJECT_ID('tempdb..#N_Assy_LineAssyStatus_Running_WIP_Qty') IS NOT NULL
				BEGIN
					DROP TABLE #N_Assy_LineAssyStatus_Running_WIP_Qty
				END

				SELECT LineCode, MachineCode, Barcode, Status, FailCount INTO #N_Assy_LineAssyStatus_Running_WIP_Qty FROM Assy_LineAssyStatus_Running (NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(Status,'') != '' AND Datecode != 'PKYK'
						AND Barcode NOT IN (SELECT Distinct Barcode FROM Assy_TallyChartStatusData WITH (NOLOCK)
							WHERE ISNULL(Result,'') = '' AND ISNULL(NotProcessedStatus,'') = 'SCRAP' AND ISNULL(Assy_Auth,0) = 0
								AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode)
						ORDER BY 1

				IF ((OBJECT_ID('tempdb..#N_WIPMST_Qty') IS NOT NULL) AND (OBJECT_ID('tempdb..#N_Assy_LineAssyStatus_Running_WIP_Qty') IS NOT NULL))
				BEGIN
					SELECT W.Seq, W.LineCode, W.MachineCode, R.Barcode, R.Status, R.FailCount INTO #N_Final_Data_Qty FROM #N_WIPMST_Qty (NOLOCK) W
						LEFT OUTER JOIN #N_Assy_LineAssyStatus_Running_WIP_Qty (NOLOCK) R
							ON W.LineCode = R.LineCode AND W.MachineCode = R.MachineCode
								WHERE ISNULL(R.Status,'') != ''
				END

				--SELECT * FROM #Final_Data Order by 1,2,4
				--SELECT * FROM #N_Final_Data_Qty
				SET @RowCount_Qty = (SELECT MAX(Seq) FROM #N_Final_Data_Qty);
				DECLARE @RowSeq_TMC1 INT = 1;
				WHILE @RowSeq_TMC1 <= @RowCount_Qty
				BEGIN
					Declare @SecondLastSeq_TMC1 INT = 0
					SELECT Top 1 @SecondLastSeq_TMC1 = Seq FROM #N_WIPMST_Qty Order by Seq Desc
					DELETE FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 AND Barcode IN (SELECT Barcode FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 + 1 AND ISNULL(Status,'') != 'FL')
					DELETE FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 AND Barcode IN (SELECT Barcode FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 + 1 AND ISNULL(Status,'') = 'FL')
					DELETE FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 AND Barcode IN (SELECT Barcode FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 + 1 AND ISNULL(Status,'') = 'FL' AND FailCount = @FailCountDefined) AND Seq != @SecondLastSeq_TMC1 - 1
					DELETE FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 + 1 AND ISNULL(Status,'') = 'FL' --AND FailCount = @FailCountDefined 
					SET @RowSeq_TMC1 = @RowSeq_TMC1 + 1
				END
				--SELECT * FROM #N_Final_Data_Qty WHERE MachineCode = (SELECT Top 1 MachineCode FROM MachineMst (NOLOCK) WHERE UPPER(MachineName) = UPPER(@MachineName))
					IF OBJECT_ID('tempdb..#N_Final_Data_Qty_WIP') IS NOT NULL
					BEGIN
						DROP TABLE #N_Final_Data_Qty_WIP
					END
					--SELECT * FROM #N_Final_Data_Qty
					SELECT LineCode, MachineCode, Count(*) Qty INTO #N_Final_Data_Qty_WIP FROM #N_Final_Data_Qty
						Group By LineCode, MachineCode
					
					IF OBJECT_ID('tempdb..#N_Final_Data_Qty_WIP') IS NOT NULL
					BEGIN
						DELETE FROM @Assy_WIP
					
						INSERT INTO @Assy_WIP
						SELECT Distinct LineCode, MachineCode, 0 FROM #N_WIPMST_Qty --ORDER BY Seq ASC

						Update AW SET AW.WIPCount = N.Qty
						FROM @Assy_WIP AW
						JOIN #N_Final_Data_Qty_WIP N
						ON AW.LineCode = N.LineCode AND AW.MachineCode = N.MachineCode
						
					SELECT DISTINCT AW.LineCode,MM.MachineCode,MM.MachineName,AW.WIPCount,RCLW.OperationSeqNo FROM @Assy_WIP AW
					JOIN MachineMst MM ON AW.MachineCode=MM.MachineCode
					JOIN RoutingConfigLineWise RCLW ON AW.MachineCode=RCLW.MachineCode
					ORDER BY RCLW.OperationSeqNo
					END
			END
					END

			IF @PARTTYPE_WIP IN ('CALIPER')
			BEGIN
					
			CREATE TABLE #StationWiseResult
			(
			  StationName varchar(20) null,
			  MachineCode varchar(10) null,						
			  Pass  varchar(10) null,
			  WIP   varchar(10) null,
			  Fail  varchar(10) null
			)

			INSERT INTO #TEMP_DASHBOARD_DATA_TABLE
			EXEC  ASSY_PROC_VIEW_DATA @LINECODE,@PROFITCENTERCODE,@PARTNUMBER,@DATECODE,'GET_DATECODE_PARTWISE_DATA'
		
					select machineCode,count(distinct barcode) as QTY into #TEMP_PS_RESULT from #TEMP_DASHBOARD_DATA_TABLE
					where result='PS'
					group by machineCode 
					
					select machineCode,count(distinct barcode) as QTY into #TEMP_FL_RESULT from #TEMP_DASHBOARD_DATA_TABLE
					where result='FL'
					group by machineCode 

					select machineCode,count(distinct barcode) as QTY into #TEMP_WIP_RESULT from #TEMP_DASHBOARD_DATA_TABLE
					where result='WP'
					group by machineCode 

					
					insert into #StationWiseResult(MachineCode,StationName)
					select distinct mchmst.MachineCode, mchmst.MachineName from 
					machinemst(nolock) mchmst 
					where mchmst.ProfitCenterCode=@profitCenterCode
					and MachineType=@PARTTYPE_WIP
					
					update sr
					set sr.Pass=QTY
					from #StationWiseResult sr inner join 
					#TEMP_PS_RESULT tmp on 
					tmp.machineCode=sr.machineCode
					
					update sr
					set sr.Fail=QTY
					from #StationWiseResult sr inner join 
					#TEMP_FL_RESULT tmp on 
					tmp.machineCode=sr.machineCode


					update sr
					set sr.WIP=QTY
					from #StationWiseResult sr inner join 
					#TEMP_WIP_RESULT tmp on 
					tmp.machineCode=sr.machineCode

					alter table #StationWiseResult
					alter column MachineCode varchar(10) collate SQL_Latin1_General_CP1_CI_AS 

					select * into #TEMP_RoutingConfigPartWise 
					from [RoutingConfigPartWise](nolock) where 
					ProfitCenterCode=@profitCenterCode and 
					PartNo=@PartNumber

					select isnull(StationName,'') as 'MachineName' ,
						   isnull(Pass,'0')  as Pass ,
						    isnull(WIP,'0') as 'WIPCount' , 
							isnull(Fail,'0') as Fail
			        from #StationWiseResult sr inner join
					#TEMP_RoutingConfigPartWise rt on
					sr.machinecode=rt.machinecode
					where rt.OperationSeqNo <> 1
					order by OperationSeqNo asc
					

					
			END 


	 END TRY
	 BEGIN CATCH
		SET @ReturnValue =	CAST(ERROR_NUMBER() AS varchar(5)) + '|' + 
			CAST(ERROR_SEVERITY()AS varchar(5)) + '|' + 
			CAST(ERROR_STATE() AS varchar(5)) + '|' + 
			CAST(ERROR_PROCEDURE() AS varchar(200)) + '|' + 
			CAST(ERROR_LINE() AS varchar(5)) + '|' + 
			CAST(ERROR_MESSAGE() AS varchar(1500))
			RAISERROR (@ReturnValue,16,1)						
		   SET @ReturnInt = 2
	 END CATCH
END


GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_DashBoard_Jhagadia]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Assy_Proc_DashBoard_Jhagadia]
(
	@CONDITION			VARCHAR(100)=NULL,
	@LineCode			VARCHAR(20)=NULL,
	@operationCode		VARCHAR(50)=NULL,
	@PartNo				VARCHAR(10)=NULL,
	@DateCode		VARCHAR(20)=NULL,
	@MachineCode 			VARCHAR(50)=NULL,
	@ReturnValue		VARCHAR (2000)=NULL OUT,
	@ReturnInt			INT=NULL OUT
)
AS
BEGIN
-- Author:		SUNDARA MOORTHI
-- Create date: 02-02-2016
-- Description:	Dashboard details procedure
-- Modified date: 22-Sep-2016
-- Description:	Dashboard details procedure
-- =============================================
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	 BEGIN TRY

		DECLARE @Qry				VARCHAR (2000)='';
		DECLARE @Barcode			VARCHAR(50)=NULL;
		DECLARE @PartNumber			VARCHAR(20)=NULL;
		DECLARE @OperationName		VARCHAR(50)=NULL;
		DECLARE @profitCenterCode	VARCHAR(10)=NULL;
		DECLARE @plannedQty			VARCHAR(10)=NULL;
		DECLARE @prevDate			varchar(20)
		DECLARE @FAILQTY			INT=0;
		DECLARE @lastDayDate       varchar(20)=NULL;
		DECLARE @TOTAL_QTY VARCHAR(10)
		DECLARE @PASS_QTY VARCHAR(10)
					
		
				IF OBJECT_ID('tempdb..#TEMP_DASHBOARD_DATA_TABLE') IS NOT NULL
			DROP TABLE #TEMP_DASHBOARD_DATA_TABLE
		

			CREATE TABLE [dbo].[#TEMP_DASHBOARD_DATA_TABLE](
			[Barcode] [varchar](100) NOT NULL,
			[TagName] [varchar](50) NOT NULL,
			[Value] [varchar](60) NULL,
			[TagId] [int] NOT NULL,
			[LineCode] [varchar](10) NOT NULL,
			[StationCode] [varchar](10) NOT NULL,
			[Datecode] [char](4) NOT NULL,
			[MachineCode] [varchar](20) NOT NULL,
			[OperationCode] [varchar](10) NOT NULL,
			[ProfitCenterCode] [varchar](10) NOT NULL,
			[Result] [varchar](5) NOT NULL,
			[Timestamp] [datetime] NOT NULL,
			[PartNo] [varchar](60) NULL
			) ON [PRIMARY]


		SELECT TOP 1 @PartNumber=assy_partno , @datecode=Datecode ,@profitCenterCode=ProfitCenterCode,
		@plannedQty=convert(varchar,CurrentPlannedQty)
		  FROM ASSY_RUNNINGPART(NOLOCK) 
		WHERE LineCode=@LineCode

		create table #PassCount 
					(
					  PassCount varchar(10)
					)

		IF OBJECT_ID('tempdb..#tbMachineDetails') IS NOT NULL
				DROP TABLE #tbMachineDetails
				
				SELECT	DISTINCT mm.MachineCode
						,mm.MachineName
						,rclw.OperationSeqNo 
				INTO #tbMachineDetails 
				FROM  MachineMst mm(NOLOCK)
				JOIN RoutingConfigLinewise rclw(NOLOCK)  ON mm.MachineCode=rclw.MachineCode
				WHERE	rclw.Traceability=1
						AND LineCode=@LineCode 
				ORDER BY rclw.OperationSeqNo
		
	IF(@CONDITION='GET_PASS_COUNT')
			BEGIN
			DECLARE @PASSQTY VARCHAR(10)
					--SELECT	ISNULL(ARP.LineCode,0) AS LineCode
					--		,ISNULL(ARP.DateCode,0) AS DateCode
					--		,ISNULL(ARP.Assy_PartNo,0) AS PartNo
					--		,ISNULL(APPFC.PassQty,0) AS PassQty
					--		--,SUM(CASE WHEN ALAS.FailCount>0 THEN 1 ELSE 0 END)AS FailQty 
					--FROM Assy_PartWise_PassFail_Count(NOLOCK) APPFC
					--INNER	JOIN Assy_RunningPart ARP ON ARP.Datecode=APPFC.DateCode
					--		AND  ARP.Assy_PartNo=APPFC.PartNo
					--		AND ARP.ProfitcenterCode=APPFC.ProfitCenterCode
					--WHERE ARP.LineCode=@LineCode 
					--GROUP BY ARP.LineCode,ARP.Datecode,ARP.Assy_PartNo,APPFC.PassQty
					
					--SELECT SUM(ISNULL(APPFC.PassQty,0)) AS QTY
					--FROM Assy_PartWise_PassFail_Count(NOLOCK) APPFC
					--INNER	JOIN Assy_RunningPart ARP ON ARP.Datecode=APPFC.DateCode
					--		AND ARP.ProfitcenterCode=APPFC.ProfitCenterCode
					--WHERE ARP.LineCode=@LineCode 
					----GROUP BY ARP.LineCode,ARP.Datecode,APPFC.PassQty

					EXEC @MachineCode =[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode @PROFITCENTERCODE=@profitCenterCode,
					@LineCode=@LineCode

					INSERT INTO #TEMP_DASHBOARD_DATA_TABLE
					EXEC  ASSY_PROC_VIEW_DATA @LINECODE,@PROFITCENTERCODE,@PARTNUMBER,@DATECODE,'GET_DATECODE_PARTWISE_DATA'

					select 
					@lineCode AS LineCode ,
					@datecode AS DateCode ,
					@PartNumber AS PartNo, 
					count(distinct Barcode) AS  PassQty 
					from #TEMP_DASHBOARD_DATA_TABLE 
					where result='PS'
					and machinecode=@MachineCode
					group by result

					select 	count(distinct Barcode) AS  QTY 
					from #TEMP_DASHBOARD_DATA_TABLE 
					where result='PS'
					and machinecode=@MachineCode
					group by result

					SET @ReturnValue='SUCCESS'
					SET @ReturnInt=0
				END
	ELSE IF(@CONDITION='GET_FAIL_COUNT')
			BEGIN
			--		SET @ReturnValue=(SELECT	ISNULL(COUNT(Barcode),0) FROM Assy_LineAssyStatus (NOLOCK)
			--								WHERE	Datecode=@DateCode
			--										and FailCount=5 
			--										and LineCode=@LineCode
			--										and PartNo=@PartNo)

					--SELECT @ReturnValue=SUM(ISNULL(APPFC.FailQty,0)) 
					--FROM Assy_PartWise_PassFail_Count(NOLOCK) APPFC
					--INNER	JOIN Assy_RunningPart(nolock) ARP ON ARP.Datecode=APPFC.DateCode
					--		AND ARP.ProfitcenterCode=APPFC.ProfitCenterCode
					--WHERE ARP.LineCode=@LineCode

					EXEC @MachineCode =[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode @PROFITCENTERCODE=@profitCenterCode,
					@LineCode=@LineCode

					INSERT INTO #TEMP_DASHBOARD_DATA_TABLE
					EXEC  ASSY_PROC_VIEW_DATA @LINECODE,@PROFITCENTERCODE,@PARTNUMBER,@DATECODE,'GET_DATECODE_PARTWISE_DATA'

					

					select distinct Barcode into #TEMP_BARCODE  
					from #TEMP_DASHBOARD_DATA_TABLE 
					where linecode=@lineCode and 
					datecode=@datecode and 
					result='PS' and 
					machinecode=@MachineCode and
					ProfitCenterCode=@profitCenterCode 

					select @ReturnValue=count(distinct Barcode) 
					from #TEMP_DASHBOARD_DATA_TABLE 
					where linecode=@lineCode and 
					datecode=@datecode and 
					result='FL' and 
					ProfitCenterCode=@profitCenterCode and 
					PartNo=@PartNumber
					AND BARCODE NOT IN (select * from #TEMP_BARCODE)
					group by result

				
				SET @ReturnInt=1
				END
	ELSE IF(@CONDITION='GET_LINE_HEADER')
			BEGIN
					IF (SELECT COUNT(*) FROM  Assy_RunningPart WITH (NOLOCK))=1
						BEGIN
							SET @ReturnValue=(SELECT LM.LineName + '(' +LM.LineCode + ') is running in ' + ARP.Assy_Mode FROM Assy_RunningPart ARP
											INNER	JOIN LineMst LM ON ARP.LineCode=LM.LineCode
													AND ARP.ProfitCenterCode=LM.ProfitCenterCode
											  WHERE ARP.LineCode=@LineCode)
						END
					ELSE
						BEGIN
							SET @ReturnValue = 	(SELECT LineName FROM  LineMst (NOLOCK) WHERE LineCode =  @LineCode) + '(' + @LineCode + ') is not running in any mode.'					
						END
					SET @ReturnInt=0
				END
	ELSE IF(@CONDITION='GET_SHIFT_HISTORY') --GET_RUNNING_HISTORY
			BEGIN
					--SELECT	ISNULL(APPFC.LineCode,0) AS LineCode
					--		,ISNULL(APPFC.DateCode,0) AS DateCode
					--		,ISNULL(APPFC.PartNo,0)   AS PartNo
					--		,ISNULL(APPFC.TotalQty,0) AS PlannedQty
					--		--,(ISNULL(APPFC.PassQty,0) + SUM(CASE WHEN ALAS.FailCount>0 THEN 1 ELSE 0 END)) AS TotalProducedQty
					--		,ISNULL(APPFC.PassQty,0) AS PassQty
					--		--,SUM(CASE WHEN ALAS.FailCount>0 THEN 1 ELSE 0 END)AS FailQty 
					--FROM Assy_PartWise_PassFail_Count(nolock) APPFC
					--WHERE	APPFC.LineCode=@LineCode
					--		AND APPFC.DateCode=@DateCode
					--		AND APPFC.PassQty>0
					--GROUP BY APPFC.LineCode,APPFC.Datecode,APPFC.PartNo,APPFC.PassQty,APPFC.TotalQty
					
					EXEC @MachineCode =[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode @PROFITCENTERCODE=@profitCenterCode,
					@LineCode=@LineCode

					INSERT INTO #TEMP_DASHBOARD_DATA_TABLE
					EXEC  ASSY_PROC_VIEW_DATA @LINECODE,@PROFITCENTERCODE,@PARTNUMBER,@DATECODE,'GET_DATECODE_PARTWISE_DATA'


					select 
					@lineCode AS LineCode ,
					@datecode AS DateCode ,
					@PartNumber AS PartNo, 
					@plannedQty AS PlannedQty,
					count(distinct Barcode) AS  PassQty 
					from #TEMP_DASHBOARD_DATA_TABLE 
					where linecode=@lineCode and 
					datecode=@datecode and 
					result='PS' and 
					ProfitCenterCode=@profitCenterCode and 
					PartNo=@PartNumber and 
					Machinecode=@MachineCode
					group by result
					
					SET @ReturnValue='SUCCESS'
					SET @ReturnInt=0
				END
	ELSE IF(@CONDITION='GET_SHIFT_HISTORY_FAILQTY') --GET_RUNNING_HISTORY
		BEGIN
				SET @ReturnValue=(SELECT (ISNULL(COUNT(ATCSDH.BARCODE),0) + (SELECT	ISNULL(COUNT(Barcode),0) FROM Assy_LineAssyStatus (NOLOCK)
											WHERE	Datecode=@DateCode
													and FailCount=5 
													and LineCode=@LineCode
													and PartNo=@PartNo)) AS FailQty 
				FROM Assy_TallyChartStatusData_History ATCSDH WITH (NOLOCK) 
				WHERE	ATCSDH.Datecode=@DateCode
						AND ATCSDH.LineCode=@LineCode
						AND ATCSDH.PartNo=@PartNo
						AND ISNULL(Reason,'')<>'' 
						AND NotProcessedStatus<>'SCRAP')
				
				SET @ReturnInt=1
			END
	ELSE IF(@CONDITION='GET_LASTSHIFT_HISTORY')
		BEGIN
				DECLARE @PrevDateCode char(4);
			
				--SELECT @PrevDateCode=TB.DATECODE FROM (SELECT  DISTINCT DENSE_RANK() OVER (PARTITION BY LineCode  ORDER BY DATECODE DESC) AS RANK_ID,DATECODE,ProfitCenterCode,LineCOde from Assy_LineAssyStatus(NOLOCK)) TB
				--	WHERE TB.RANK_ID=2 and LineCode=@LineCode

				
				SELECT TOP 1 @PrevDateCode=Datecode FROM Assy_LineAssyStatus(NOLOCK) TB
				WHERE	LineCode=@LineCode
						AND Datecode<>@DateCode
				ORDER BY TB.ResultTimeStamp DESC

				SELECT	ISNULL(APPFC.DateCode,0) AS DateCode,
						ISNULL(APPFC.PartNo,0) AS PartNo
						--,ISNULL(APPFC.PassQty,0) AS TotalProducedQty
						,ISNULL(APPFC.PassQty,0) AS PassQty
						--,SUM(CASE WHEN ALAS.FailCount>0 THEN 1 ELSE 0 END)AS FailQty 
				FROM Assy_PartWise_PassFail_Count(NOLOCK) APPFC
				WHERE	APPFC.LineCode=@LineCode
						AND APPFC.DateCode=@PrevDateCode
				GROUP BY APPFC.LineCode,APPFC.Datecode,APPFC.PartNo,APPFC.PassQty,APPFC.TotalQty
					--ORDER BY Timestamp ASC

				SET @ReturnValue='SUCCESS'
				SET @ReturnInt=1
			END
	ELSE IF(@CONDITION='GET_LASTSHIFT_HISTORY_FAILQTY') --GET_RUNNING_HISTORY
		BEGIN
			
			SELECT TOP 1 @PrevDateCode=Datecode FROM Assy_LineAssyStatus(NOLOCK) TB
				WHERE	LineCode=@LineCode
						AND Datecode<>@DateCode
				ORDER BY TB.ResultTimeStamp DESC

				SET @ReturnValue=(SELECT (ISNULL(COUNT(ATCSDH.BARCODE),0) + (SELECT	ISNULL(COUNT(Barcode),0) FROM Assy_LineAssyStatus (NOLOCK)
											WHERE	Datecode=@PrevDateCode
													and FailCount=5 
													and LineCode=@LineCode
													and PartNo=@PartNo)) AS FailQty 
				FROM Assy_TallyChartStatusData_History ATCSDH WITH (NOLOCK) 
				WHERE	ATCSDH.Datecode=@PrevDateCode
						AND ATCSDH.LineCode=@LineCode
						AND ATCSDH.PartNo=@PartNo
						AND ISNULL(Reason,'')<>'' 
						AND NotProcessedStatus<>'SCRAP')
				
				SET @ReturnInt=1
			END
	ELSE IF(@CONDITION='GET_LASTMONTH_PRODUCTION')
		BEGIN

					EXEC @MachineCode =[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode 
					@PROFITCENTERCODE=@profitCenterCode,
					@LineCode=@LineCode
					
					INSERT INTO #TEMP_DASHBOARD_DATA_TABLE
					EXEC  ASSY_PROC_VIEW_DATA @LINECODE,@PROFITCENTERCODE,@PARTNUMBER,@DATECODE,'LASTMONTH_PRODUCTION'

					select @PASS_QTY=count(distinct Barcode) 
					from #TEMP_DASHBOARD_DATA_TABLE 
					where 
					result='PS' and 
					machinecode=@MachineCode
					group by result
					
					select @TOTAL_QTY=count(distinct Barcode) 
					from #TEMP_DASHBOARD_DATA_TABLE 
					where result in ('PS','FL') and
					machinecode=@MachineCode
					--group by result
					
					SELECT @TOTAL_QTY AS TotalProducedQty , @PASS_QTY AS PassQty

				--EXEC @MachineCode =[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode @PROFITCENTERCODE='0021',@LineCode=@LineCode
				
				--DECLARE @FAILQTY   INT=0;

				----Get Fail Quatity for the previous month
				--SET @FAILQTY =(SELECT (ISNULL(COUNT(ATCSDH.BARCODE),0) + (SELECT	ISNULL(COUNT(Barcode),0) FROM Assy_LineAssyStatus (NOLOCK)
				--							WHERE	CONVERT(VARCHAR(7),ResultTimestamp,126)=CONVERT(VARCHAR(7), DATEADD(MM,-1,GETDATE()),126)
				--									and FailCount=5 
				--									and LineCode=@LineCode
				--									)) AS FailQty 
				--				FROM Assy_TallyChartStatusData_History ATCSDH WITH (NOLOCK) 
				--				WHERE	CONVERT(VARCHAR(7),Timestamp,126)=CONVERT(VARCHAR(7), DATEADD(MM,-1,GETDATE()),126) 
				--						AND ATCSDH.LineCode=@LineCode
				--						AND ISNULL(Reason,'')<>'' 
				--						AND NotProcessedStatus<>'SCRAP')

				--SELECT	(ISNULL(SUM(CASE WHEN ALAS.STATUS='PS' AND ALAS.MachineCode=@MachineCode  THEN 1 ELSE 0 END),0) 
				--		+ @FAILQTY)  AS TotalProducedQty
				--		,ISNULL(SUM(CASE WHEN ALAS.STATUS='PS' AND ALAS.MachineCode=@MachineCode  THEN 1 ELSE 0 END),0) AS PassQty
				--		--,ISNULL(SUM(CASE WHEN ISNULL(ALAS.FailCount,0)>0 THEN 1 ELSE 0 END),0) AS FailQty
				--FROM ASSY_LINEASSYSTATUS(NOLOCK) ALAS
				--WHERE ALAS.LineCode=@LineCode
				--	AND CONVERT(VARCHAR(7),ResultTimestamp,126)=CONVERT(VARCHAR(7), DATEADD(MM,-1,GETDATE()),126)
			
			
				SET @ReturnValue='SUCCESS'
				SET @ReturnInt=1
			END
	ELSE IF(@CONDITION='GET_CURRENTMONTH_PRODUCTION')
		BEGIN

			
			
					
					EXEC @MachineCode =[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode 
					@PROFITCENTERCODE=@profitCenterCode,
					@LineCode=@LineCode
					
					INSERT INTO #TEMP_DASHBOARD_DATA_TABLE
					EXEC  ASSY_PROC_VIEW_DATA @LINECODE,@PROFITCENTERCODE,@PARTNUMBER,@DATECODE,'CURRENTMONTH_PRODUCTION'

					select @PASS_QTY=count(distinct Barcode) 
					from #TEMP_DASHBOARD_DATA_TABLE 
					where 
					result='PS' and 
					machinecode=@MachineCode
					group by result
					
					select @TOTAL_QTY=count(distinct Barcode) 
					from #TEMP_DASHBOARD_DATA_TABLE 
					where result in ('PS','FL')
					group by result
					
					SELECT isnull(@TOTAL_QTY,'0') AS TotalProducedQty , isnull(@PASS_QTY,'0') AS PassQty


			--	EXEC @MachineCode =[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode @PROFITCENTERCODE='0021',@LineCode=@LineCode
			
			----Get Fail Quatity for the current month
			--SET @FAILQTY=(SELECT (ISNULL(COUNT(ATCSDH.BARCODE),0) + (SELECT	ISNULL(COUNT(Barcode),0) FROM Assy_LineAssyStatus (NOLOCK)
			--								WHERE	CONVERT(VARCHAR(7),ResultTimestamp,126)=CONVERT(VARCHAR(7), GETDATE(),126)
			--										and FailCount=5 
			--										and LineCode=@LineCode
			--										)) AS FailQty 
			--	FROM Assy_TallyChartStatusData_History ATCSDH WITH (NOLOCK) 
			--	WHERE	CONVERT(VARCHAR(7),Timestamp,126)=CONVERT(VARCHAR(7), GETDATE(),126) 
			--			AND ATCSDH.LineCode=@LineCode
			--			AND ISNULL(Reason,'')<>'' 
			--			AND NotProcessedStatus<>'SCRAP')


			--	SELECT	(ISNULL(SUM(CASE WHEN ALAS.STATUS='PS' AND ALAS.MachineCode=@MachineCode  THEN 1 ELSE 0 END),0) 
			--			+ @FAILQTY)  AS TotalProducedQty
			--			,ISNULL(SUM(CASE WHEN ALAS.STATUS='PS' AND ALAS.MachineCode=@MachineCode THEN 1 ELSE 0 END),0) AS PassQty
			--			--,ISNULL(SUM(CASE WHEN ISNULL(ALAS.FailCount,0)>0 THEN 1 ELSE 0 END),0) AS FailQty
			--	FROM ASSY_LINEASSYSTATUS(NOLOCK) ALAS
			--	WHERE ALAS.LineCode=@LineCode
			--		AND CONVERT(VARCHAR(7),ResultTimestamp,126)=CONVERT(VARCHAR(7), GETDATE(),126)
			
				SET @ReturnValue='SUCCESS'
				SET @ReturnInt=1
			END
	ELSE IF(@CONDITION='GET_CURRENT_PROCESS_BARCODE')
		BEGIN
					DECLARE @MachineCode1 VARCHAR(20);

					EXEC @MachineCode1 =[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode @PROFITCENTERCODE='0021',@LineCode=@LineCode
					IF(@MachineCode <>@MachineCode1)
						BEGIN
							SET @ReturnValue=(SELECT TOP 1 BARCODE FROM Assy_LineAssyStatus_Running WITH (NOLOCK) WHERE MachineCode=@MachineCode AND CHARINDEX('PKYK',Barcode) = 0 ORDER BY ScanTimestamp DESC)
							SET @ReturnInt=1
						END
					ELSE
						BEGIN
							SET @ReturnValue=(SELECT TOP 1 BARCODE FROM Assy_LineAssyStatus WITH (NOLOCK) WHERE MachineCode=@MachineCode  AND DateCode=@DateCode AND CHARINDEX('PKYK',Barcode) = 0  ORDER BY ScanTimestamp DESC)
							SET @ReturnInt=1
						END
				END
	ELSE IF(@CONDITION='FTT_QTY')
		BEGIN
						IF(CHARINDEX('M',@LINECODE)=1 OR CHARINDEX('L',@LINECODE)=1)
							BEGIN
								SELECT	tb.PartNo
										,COUNT(tb.Barcode) AS TotalQty FROM 
											(SELECT DISTINCT(Barcode), PartNo,SUM(FailCount) AS TotalQty  FROM Assy_LineAssyStatus(NOLOCK)
												WHERE DateCode=@DateCode AND Linecode=@LineCode
													GROUP BY Barcode,PartNo 
														HAVING SUM(FailCount)=0) AS tb
														JOIN Assy_LineAssyStatus ALAS(NOLOCK) ON tb.PartNo=ALAS.PartNo AND tb.Barcode=ALAS.Barcode AND ALAS.MachineCode='MCFV'
								GROUP BY tb.Partno ORDER BY PartNo ASC
							END
						ELSE if CHARINDEX('P',@LINECODE)=1
							BEGIN
								IF OBJECT_ID('tempdb..#tmpFailBooster') IS NOT NULL
									DROP TABLE #tmpFailBooster
										
									SELECT	DISTINCT(alas.Barcode)
											,alas.PartNo,SUM(alas.FailCount) AS TotalQty
											,alas.MachineCode 
									INTO #tmpFailBooster  FROM Assy_LineAssyStatus alas(NOLOCK)
									JOIN  Assy_CouplingDetails acd(NOLOCK)  ON acd.Child_Barcode=alas.Barcode
									JOIN Assy_LineAssyStatus ALA(NOLOCK) ON alas.PartNo=ALAS.PartNo AND alas.Barcode=ALA.Barcode AND ALA.MachineCode='MCFVSTMC'
									WHERE	alas.DateCode=@DateCode
											AND alas.Linecode=@Linecode
									GROUP BY alas.Barcode,alas.PartNo,alas.MachineCode
									HAVING SUM(alas.FailCount)>0

								IF OBJECT_ID('tempdb..#tmpFailBooster1') IS NOT NULL
									DROP TABLE #tmpFailBooster1
									
									SELECT	DISTINCT(alas.Barcode)
											,PartNo
											,SUM(FailCount) AS TotalQty
											,MachineCode 
									INTO #tmpFailBooster1 FROM Assy_LineAssyStatus(NOLOCK) alas
									JOIN  Assy_CouplingDetails acd(NOLOCK)  ON acd.FG_Barcode=alas.Barcode
									WHERE	alas.DateCode=@DateCode
											AND alas.Linecode=@Linecode
									GROUP BY alas.Barcode,PartNo,MachineCode
									HAVING SUM(FailCount)>0
								
								SELECT STMC_PART_NO AS Partno,COUNT(FG_Barcode) AS TotalQty FROM Assy_CouplingDetails(NOLOCK) 
									WHERE	FG_Barcode NOT IN (SELECT Barcode FROM  #tmpFailBooster1)
											AND Child_Barcode NOT IN (SELECT Barcode FROM  #tmpFailBooster)
											AND FG_Barcode IN (SELECT Barcode FROM Assy_LineAssyStatus(NOLOCK) WHERE DateCode=@DateCode AND LineCode=@Linecode)
											AND DateCode=@DateCode
											AND LineCode=@Linecode
											AND Part_Type='SERVO'
									GROUP BY STMC_PART_NO ORDER BY STMC_PART_NO ASC
							END
					END
	ELSE IF(@CONDITION='MONTHLY_PRODUCTION_QTY')
		BEGIN
					
					--2017-01-06 11:24:34.143
					SET @prevDate= convert(varchar,year(getdate())) + '-'+convert(varchar,month(getdate()))+'-'+
					convert(varchar,1)+' 00:00:00.000'
					
					EXEC @MachineCode =[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode 
					@PROFITCENTERCODE=@profitCenterCode,
					@LineCode=@LineCode
					
					

					set @Qry=
					'
					select count(distinct Barcode) AS PASSQTY
					from Assy_View_ParamData 
					where linecode='+''''+@lineCode+''''+' and 
					result='+''''+'PS'+''''+' and 
					machinecode='+''''+@MachineCode+''''+' and
					ProfitCenterCode='+''''+@profitCenterCode+''''+' and 
					PartNo='+''''+@PartNumber+''''+' and
					Timestamp between '+''''+ @prevDate+''''+' and getdate()
					group by result
					
					'
					

					--print @qry
					insert into #PassCount
					exec sp_sqlexec @Qry

					
					SELECT @RETURNVALUE=ISNULL(PASSCOUNT,'') FROM #PASSCOUNT

						
						--SET @ReturnValue=(SELECT COUNT(Barcode) FROM Assy_LineAssyStatus(NOLOCK)
						--WHERE	Linecode=@LineCode
						--		AND PartNo=@PartNo
						--		AND CONVERT(VARCHAR(7),ResultTimestamp,126)=CONVERT(VARCHAR(7),GETDATE(),126)
						--		AND MachineCode=@MachineCode )
						----GROUP BY PartNo
				
				SET @ReturnInt = 1
		END
	ELSE IF(@CONDITION='WIP')
		BEGIN
					Declare @Assy_WIP AS Table(
									LineCode varchar(10) NULL,
									MachineCode varchar(20) NULL,
									WIPCount int NULL)

			

			Declare @PartType_WIP VARCHAR(30) = '';
			DECLARE @RowCount_Qty INT=0;
			DECLARE @FailCountDefined INT =5;
			--DECLARE @ProfitCenterCode VARCHAR(20)='';
			SELECT Top 1 @PartType_WIP = LTRIM(RTRIM(PartType)), @ProfitCenterCode=ProfitCenterCode FROM Assy_RunningPart (NOLOCK)
			IF @PartType_WIP = 'STMC'
			BEGIN
				IF OBJECT_ID('tempdb..#STMC_Final_Data_Qty') IS NOT NULL
				BEGIN
					DROP TABLE #STMC_Final_Data_Qty
				END
				IF OBJECT_ID('tempdb..#STMC_WIPMST_Qty') IS NOT NULL
				BEGIN
					DROP TABLE #STMC_WIPMST_Qty
				END
				SELECT ROW_NUMBER() OVER(ORDER BY OperationSeqNo) Seq, LineCode, Machinecode, OperationSeqNo, WIP_Quantity  
					INTO #STMC_WIPMST_Qty
						FROM (
							SELECT  ROW_NUMBER() OVER(PARTITION BY RCLW.MachineCode ORDER BY RCLW.OperationSeqNo) AS SeqNo,
									RCLW.LineCode, RCLW.MachineCode, RCLW.OperationSeqNo, RCLW.WIP_Quantity
										FROM RoutingConfigLineWise (NOLOCK) RCLW
										JOIN
										RoutingConfigPartWise (NOLOCK) RCPW
											ON	RCLW.ProfitCenterCode=RCPW.ProfitCenterCode AND
													RCLW.MachineCode = RCPW.MachineCode AND
														RCLW.OperationCode = RCPW.OperationCode AND
															RCLW.Traceability = RCPW.Traceability
																	
										JOIN
										LineMst (NOLOCK) LM
											ON	RCLW.ProfitCenterCode = LM.ProfitCenterCode AND
													RCLW.LineCode = LM.LineCode
											WHERE ISNULL(RCLW.Traceability,0) = 1 AND
													RCPW.PartNo = (SELECT Top 1 Assy_PartNo FROM ASSY_RUNNINGPART (NOLOCK) WHERE LineCode = @LineCode ORDER BY CreatedDate Desc) AND
														RCLW.WIP_Quantity <> 0 AND
															--ISNULL(LM.WIPCheck,0) = 1 AND
																ISNULL(LM.isActive,0) = 1 AND
																	ISNULL(RCPW.Traceability,0) = 1
																		AND LM.ProfitCenterCode = @ProfitCenterCode
																			AND LM.LineCode = @LineCode
																					
										) Source WHERE SeqNo = 1
			
				IF OBJECT_ID('tempdb..#STMC_Assy_LineAssyStatus_Running_WIP_Qty') IS NOT NULL
				BEGIN
					DROP TABLE #STMC_Assy_LineAssyStatus_Running_WIP_Qty
				END

				SELECT LineCode, MachineCode, Case WHEN CHARINDEX(':',Barcode) > 0 THEN RIGHT(Barcode,4) ELSE LEFT(RIGHT(Barcode,6),4) END Barcode, Status, FailCount INTO #STMC_Assy_LineAssyStatus_Running_WIP_Qty FROM Assy_LineAssyStatus_Running (NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(Status,'') != '' AND Datecode != 'PKYK'
						AND Barcode NOT IN (SELECT Distinct Barcode FROM Assy_TallyChartStatusData WITH (NOLOCK)
							WHERE ISNULL(Result,'') = '' AND ISNULL(NotProcessedStatus,'') = 'SCRAP' AND ISNULL(Assy_Auth,0) = 0
								AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode)
						ORDER BY 1

				IF ((OBJECT_ID('tempdb..#STMC_WIPMST_Qty') IS NOT NULL) AND (OBJECT_ID('tempdb..#STMC_Assy_LineAssyStatus_Running_WIP_Qty') IS NOT NULL))
				BEGIN
					SELECT W.Seq, W.LineCode, W.MachineCode, R.Barcode, R.Status, R.FailCount INTO #STMC_Final_Data_Qty FROM #STMC_WIPMST_Qty (NOLOCK) W
						LEFT OUTER JOIN #STMC_Assy_LineAssyStatus_Running_WIP_Qty (NOLOCK) R
							ON W.LineCode = R.LineCode AND W.MachineCode = R.MachineCode
								WHERE ISNULL(R.Status,'') != ''
				END

				--SELECT * FROM #Final_Data Order by 1,2,4
				

				SET @RowCount_Qty = (SELECT MAX(Seq) FROM #STMC_Final_Data_Qty);
					DECLARE @RowSeq1 INT = 1;
				WHILE @RowSeq1 <= @RowCount_Qty
				BEGIN
					Declare @SecondLastSeq1 INT = 0
					SELECT Top 1 @SecondLastSeq1 = Seq FROM #STMC_WIPMST_Qty Order by Seq Desc
					DELETE FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 AND Barcode IN (SELECT Barcode FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 + 1 AND ISNULL(Status,'') != 'FL')
					DELETE FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 AND Barcode IN (SELECT Barcode FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 + 1 AND ISNULL(Status,'') = 'FL')
					DELETE FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 AND Barcode IN (SELECT Barcode FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 + 1 AND ISNULL(Status,'') = 'FL' AND FailCount = @FailCountDefined) AND Seq != @SecondLastSeq1 - 1
					DELETE FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 + 1 AND ISNULL(Status,'') = 'FL' --AND FailCount = @FailCountDefined 
					SET @RowSeq1 = @RowSeq1 + 1
				END
				--SELECT * FROM #STMC_Final_Data_Qty WHERE MachineCode = (SELECT Top 1 MachineCode FROM MachineMst (NOLOCK) WHERE UPPER(MachineName) = UPPER(@MachineName))
				IF OBJECT_ID('tempdb..#N_Final_Data_Qty_WIP1') IS NOT NULL
				BEGIN
					DROP TABLE #N_Final_Data_Qty_WIP1
				END
				
				SELECT LineCode, MachineCode, Count(*) Qty INTO #N_Final_Data_Qty_WIP1 FROM #STMC_Final_Data_Qty
					Group By LineCode, MachineCode
					
				IF OBJECT_ID('tempdb..#N_Final_Data_Qty_WIP1') IS NOT NULL
				BEGIN
					DELETE FROM @Assy_WIP
					
					INSERT INTO @Assy_WIP
					SELECT Distinct LineCode, MachineCode, 0 FROM #STMC_WIPMST_Qty --ORDER BY Seq ASC

					Update AW SET AW.WIPCount = N.Qty
					FROM @Assy_WIP AW
					JOIN #N_Final_Data_Qty_WIP1 N
					ON AW.LineCode = N.LineCode AND AW.MachineCode = N.MachineCode
					
					SELECT  DISTINCT AW.LineCode,MM.MachineCode,MM.MachineName,AW.WIPCount,RCLW.OperationSeqNo FROM @Assy_WIP AW
					JOIN MachineMst MM ON AW.MachineCode=MM.MachineCode
					JOIN RoutingConfigLineWise RCLW ON AW.MachineCode=RCLW.MachineCode
					ORDER BY RCLW.OperationSeqNo
				END
			END
			ELSE IF @PartType_WIP IN ('TMC','SERVO')
			BEGIN
				IF OBJECT_ID('tempdb..#N_Final_Data_Qty') IS NOT NULL
				BEGIN
					DROP TABLE #N_Final_Data_Qty
				END
				IF OBJECT_ID('tempdb..#N_WIPMST_Qty') IS NOT NULL
				BEGIN
					DROP TABLE #N_WIPMST_Qty
				END
				SELECT ROW_NUMBER() OVER(ORDER BY OperationSeqNo) Seq, LineCode, Machinecode, OperationSeqNo, WIP_Quantity  
					INTO #N_WIPMST_Qty
						FROM (
							SELECT  ROW_NUMBER() OVER(PARTITION BY RCLW.MachineCode ORDER BY RCLW.OperationSeqNo) AS SeqNo,
									RCLW.LineCode, RCLW.MachineCode, RCLW.OperationSeqNo, RCLW.WIP_Quantity
										FROM RoutingConfigLineWise (NOLOCK) RCLW
										JOIN
										RoutingConfigPartWise (NOLOCK) RCPW
											ON	RCLW.ProfitCenterCode=RCPW.ProfitCenterCode AND
													RCLW.MachineCode = RCPW.MachineCode AND
														RCLW.OperationCode = RCPW.OperationCode AND
															RCLW.Traceability = RCPW.Traceability
																	
										JOIN
										LineMst (NOLOCK) LM
											ON	RCLW.ProfitCenterCode = LM.ProfitCenterCode AND
													RCLW.LineCode = LM.LineCode
											WHERE ISNULL(RCLW.Traceability,0) = 1 AND
													RCPW.PartNo = (SELECT Top 1 Assy_PartNo FROM ASSY_RUNNINGPART (NOLOCK) WHERE LineCode = @LineCode ORDER BY CreatedDate Desc) AND
														RCLW.WIP_Quantity <> 0 AND
															--ISNULL(LM.WIPCheck,0) = 1 AND
																ISNULL(LM.isActive,0) = 1 AND
																	ISNULL(RCPW.Traceability,0) = 1
																		AND LM.ProfitCenterCode = @ProfitCenterCode
																			AND LM.LineCode = @LineCode
																					
										) Source WHERE SeqNo = 1
			
				IF OBJECT_ID('tempdb..#N_Assy_LineAssyStatus_Running_WIP_Qty') IS NOT NULL
				BEGIN
					DROP TABLE #N_Assy_LineAssyStatus_Running_WIP_Qty
				END

				SELECT LineCode, MachineCode, Barcode, Status, FailCount INTO #N_Assy_LineAssyStatus_Running_WIP_Qty FROM Assy_LineAssyStatus_Running (NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(Status,'') != '' AND Datecode != 'PKYK'
						AND Barcode NOT IN (SELECT Distinct Barcode FROM Assy_TallyChartStatusData WITH (NOLOCK)
							WHERE ISNULL(Result,'') = '' AND ISNULL(NotProcessedStatus,'') = 'SCRAP' AND ISNULL(Assy_Auth,0) = 0
								AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode)
						ORDER BY 1

				IF ((OBJECT_ID('tempdb..#N_WIPMST_Qty') IS NOT NULL) AND (OBJECT_ID('tempdb..#N_Assy_LineAssyStatus_Running_WIP_Qty') IS NOT NULL))
				BEGIN
					SELECT W.Seq, W.LineCode, W.MachineCode, R.Barcode, R.Status, R.FailCount INTO #N_Final_Data_Qty FROM #N_WIPMST_Qty (NOLOCK) W
						LEFT OUTER JOIN #N_Assy_LineAssyStatus_Running_WIP_Qty (NOLOCK) R
							ON W.LineCode = R.LineCode AND W.MachineCode = R.MachineCode
								WHERE ISNULL(R.Status,'') != ''
				END

				--SELECT * FROM #Final_Data Order by 1,2,4
				--SELECT * FROM #N_Final_Data_Qty
				SET @RowCount_Qty = (SELECT MAX(Seq) FROM #N_Final_Data_Qty);
				DECLARE @RowSeq_TMC1 INT = 1;
				WHILE @RowSeq_TMC1 <= @RowCount_Qty
				BEGIN
					Declare @SecondLastSeq_TMC1 INT = 0
					SELECT Top 1 @SecondLastSeq_TMC1 = Seq FROM #N_WIPMST_Qty Order by Seq Desc
					DELETE FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 AND Barcode IN (SELECT Barcode FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 + 1 AND ISNULL(Status,'') != 'FL')
					DELETE FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 AND Barcode IN (SELECT Barcode FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 + 1 AND ISNULL(Status,'') = 'FL')
					DELETE FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 AND Barcode IN (SELECT Barcode FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 + 1 AND ISNULL(Status,'') = 'FL' AND FailCount = @FailCountDefined) AND Seq != @SecondLastSeq_TMC1 - 1
					DELETE FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 + 1 AND ISNULL(Status,'') = 'FL' --AND FailCount = @FailCountDefined 
					SET @RowSeq_TMC1 = @RowSeq_TMC1 + 1
				END
				--SELECT * FROM #N_Final_Data_Qty WHERE MachineCode = (SELECT Top 1 MachineCode FROM MachineMst (NOLOCK) WHERE UPPER(MachineName) = UPPER(@MachineName))
					IF OBJECT_ID('tempdb..#N_Final_Data_Qty_WIP') IS NOT NULL
					BEGIN
						DROP TABLE #N_Final_Data_Qty_WIP
					END
					--SELECT * FROM #N_Final_Data_Qty
					SELECT LineCode, MachineCode, Count(*) Qty INTO #N_Final_Data_Qty_WIP FROM #N_Final_Data_Qty
						Group By LineCode, MachineCode
					
					IF OBJECT_ID('tempdb..#N_Final_Data_Qty_WIP') IS NOT NULL
					BEGIN
						DELETE FROM @Assy_WIP
					
						INSERT INTO @Assy_WIP
						SELECT Distinct LineCode, MachineCode, 0 FROM #N_WIPMST_Qty --ORDER BY Seq ASC

						Update AW SET AW.WIPCount = N.Qty
						FROM @Assy_WIP AW
						JOIN #N_Final_Data_Qty_WIP N
						ON AW.LineCode = N.LineCode AND AW.MachineCode = N.MachineCode
						
					SELECT DISTINCT AW.LineCode,MM.MachineCode,MM.MachineName,AW.WIPCount,RCLW.OperationSeqNo FROM @Assy_WIP AW
					JOIN MachineMst MM ON AW.MachineCode=MM.MachineCode
					JOIN RoutingConfigLineWise RCLW ON AW.MachineCode=RCLW.MachineCode
					ORDER BY RCLW.OperationSeqNo
					END
			END
					END

			IF @PARTTYPE_WIP IN ('CALIPER')
			BEGIN
					
			CREATE TABLE #StationWiseResult
			(
			  StationName varchar(20) null,
			  MachineCode varchar(10) null,						
			  Pass  varchar(10) null,
			  WIP   varchar(10) null,
			  Fail  varchar(10) null
			)

			INSERT INTO #TEMP_DASHBOARD_DATA_TABLE
			EXEC  ASSY_PROC_VIEW_DATA @LINECODE,@PROFITCENTERCODE,@PARTNUMBER,@DATECODE,'GET_DATECODE_PARTWISE_DATA'
		
					select machineCode,count(distinct barcode) as QTY into #TEMP_PS_RESULT from #TEMP_DASHBOARD_DATA_TABLE
					where result='PS'
					group by machineCode 
					
					select machineCode,count(distinct barcode) as QTY into #TEMP_FL_RESULT from #TEMP_DASHBOARD_DATA_TABLE
					where result='FL'
					group by machineCode 

					select machineCode,count(distinct barcode) as QTY into #TEMP_WIP_RESULT from #TEMP_DASHBOARD_DATA_TABLE
					where result='WP'
					group by machineCode 

					
					insert into #StationWiseResult(MachineCode,StationName)
					select distinct mchmst.MachineCode, mchmst.MachineName from 
					machinemst(nolock) mchmst 
					where mchmst.ProfitCenterCode=@profitCenterCode
					and MachineType=@PARTTYPE_WIP
					
					update sr
					set sr.Pass=QTY
					from #StationWiseResult sr inner join 
					#TEMP_PS_RESULT tmp on 
					tmp.machineCode=sr.machineCode
					
					update sr
					set sr.Fail=QTY
					from #StationWiseResult sr inner join 
					#TEMP_FL_RESULT tmp on 
					tmp.machineCode=sr.machineCode


					update sr
					set sr.WIP=QTY
					from #StationWiseResult sr inner join 
					#TEMP_WIP_RESULT tmp on 
					tmp.machineCode=sr.machineCode

					alter table #StationWiseResult
					alter column MachineCode varchar(10) collate SQL_Latin1_General_CP1_CI_AS 

					select * into #TEMP_RoutingConfigPartWise 
					from [RoutingConfigPartWise](nolock) where 
					ProfitCenterCode=@profitCenterCode and 
					PartNo=@PartNumber

					select isnull(StationName,'') as 'MachineName' ,
						   isnull(Pass,'0')  as Pass ,
						    isnull(WIP,'0') as 'WIPCount' , 
							isnull(Fail,'0') as Fail
			        from #StationWiseResult sr inner join
					#TEMP_RoutingConfigPartWise rt on
					sr.machinecode=rt.machinecode
					where rt.OperationSeqNo <> 1
					order by OperationSeqNo asc
					

					
			END 


	 END TRY
	 BEGIN CATCH
		SET @ReturnValue =	CAST(ERROR_NUMBER() AS varchar(5)) + '|' + 
			CAST(ERROR_SEVERITY()AS varchar(5)) + '|' + 
			CAST(ERROR_STATE() AS varchar(5)) + '|' + 
			CAST(ERROR_PROCEDURE() AS varchar(200)) + '|' + 
			CAST(ERROR_LINE() AS varchar(5)) + '|' + 
			CAST(ERROR_MESSAGE() AS varchar(1500))
			RAISERROR (@ReturnValue,16,1)						
		   SET @ReturnInt = 2
	 END CATCH
END




GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_DashBoard_LineWise]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create PROCEDURE [dbo].[Assy_Proc_DashBoard_LineWise]
(
	@CONDITION VARCHAR(100)=NULL,
	@PROFITCENTERCODE varchar(50)=null,
	@PartNumber varchar(20)=null,
	@DateCode varchar(20)=null,
	@LineCode varchar(20)=null,
	@MachinCode varchar(50)=null,
	@OperationName varchar(50)=null,
	@operationCode varchar(50)=null,
	@Barcode varchar(50)=null,
	@ReturnValue VARCHAR (2000)=NULL OUT,
	@ReturnInt INT=NULL OUT
	)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

   BEGIN TRY
	--	BEGIN TRAN
		IF(@CONDITION='GET_LINE_CURRENTRUNNING_STATUS')
			BEGIN
				SELECT  @LineCode= LineCode,@DateCode= Datecode,@PartNumber= Assy_PartNo FROM assy_runningpart (nolock) where LineCode=@LineCode and Datecode=@DateCode
				SELECT  LineCode,Datecode,Assy_PartNo,ProductionOrderNo,CurrentPlannedQty FROM assy_runningpart(nolock) where LineCode=@LineCode and Datecode=@DateCode
				if(SUBSTRING(@LineCode,1,1)='T')
					begin
						EXEC @MachinCode=[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode @PROFITCENTERCODE=@ProfitCenterCode,@LineCode=@LineCode
					end

				else if(SUBSTRING(@LineCode,1,1)='S')
					begin
						EXEC @MachinCode=[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode @PROFITCENTERCODE=@PROFITCENTERCODE,@LineCode=@LineCode
					end
				



				select ProfitCenterCode,LineCode,SUM(CASE WHEN ISNULL(STATUS,'')='PS' THEN 1 ELSE 0 END) AS PASS ,
												SUM(CASE WHEN ISNULL(STATUS,'')='FL' THEN 1 ELSE 0 END) AS FAIL  from Assy_LineAssyStatus (nolock)
												WHERE ProfitCenterCode=@ProfitCenterCode AND LineCode=@LineCode AND Datecode=@DateCode and PartNo=@PartNumber
												GROUP BY ProfitCenterCode,LineCode--where Datecode='05Yc' --where linecode=@linecode and Datecode=@DateCode and PartNo=@PartNumber

				SET @ReturnValue='SUCCESS'
				SET @ReturnInt=0
			END
	ELSE IF(@CONDITION='GET_SHIFT_AND_DAY_STATUS')
			BEGIN
				EXEC @MachinCode=[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode @PROFITCENTERCODE=@PROFITCENTERCODE,@LineCode=@LineCode

				select ProfitCenterCode,LineCode,SUM(CASE WHEN ISNULL(STATUS,'')='PS' THEN 1 ELSE 0 END) AS PASS ,
												SUM(CASE WHEN ISNULL(STATUS,'')='FL' THEN 1 ELSE 0 END) AS FAIL  from Assy_LineAssyStatus(nolock)
												WHERE ProfitCenterCode=@ProfitCenterCode AND
												MachineCode=@MachinCode
												AND  LineCode=@LineCode AND Datecode=@DateCode
												GROUP BY ProfitCenterCode,LineCode


				select ProfitCenterCode,LineCode,SUM(CASE WHEN ISNULL(STATUS,'')='PS' THEN 1 ELSE 0 END) AS PASS ,
												SUM(CASE WHEN ISNULL(STATUS,'')='FL' THEN 1 ELSE 0 END) AS FAIL  from Assy_LineAssyStatus(nolock)
												WHERE ProfitCenterCode=@ProfitCenterCode 
													AND LineCode=@LineCode 
													AND MachineCode=@MachinCode
													AND DAY(ResultTimestamp)=DAY(GETDATE())
													AND MONTH(ResultTimestamp)=MONTH(GETDATE())
													AND YEAR(ResultTimestamp)=YEAR(GETDATE())
												GROUP BY ProfitCenterCode,LineCode
				SET @ReturnValue='SUCCESS'
				SET @ReturnInt=0
			END
		ELSE IF(@CONDITION='GET_LAST_SCAN_BARCODE_STATUS')
			BEGIN

				SELECT  @LineCode= LineCode,@DateCode= Datecode,@PartNumber= Assy_PartNo FROM assy_runningpart(nolock) where LineCode=@LineCode and Datecode=@DateCode

				EXEC @MachinCode=[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode @PROFITCENTERCODE=@PROFITCENTERCODE,@LineCode=@LineCode

				select TOP 1 ProfitCenterCode,LineCode,Barcode,CASE WHEN Status='PS' THEN 'PASS'
												WHEN STATUS='FL' THEN 'FAIL'
												WHEN isnull(STATUS,'')='' THEN 'PENDING' END AS STATUS
																	,ResultTimestamp from Assy_LineAssyStatus(nolock)
												WHERE ProfitCenterCode=@ProfitCenterCode and MachineCode=@MachinCode AND LineCode=@LineCode AND Datecode=@DateCode ORDER BY ResultTimestamp DESC


			
				select mm.MachineName FROM RoutingConfigLineWise(nolock) rclw 
				join MachineMst(nolock) mm on 
				rclw.MachineCode=MM.MachineCode
				WHERE rclw.ProfitCenterCode=@ProfitCenterCode AND isnull(rclw.Traceability,'')=0 and rclw.LineCode=@LineCode order by mm.MachineName asc

				
				SET @ReturnValue='SUCCESS'
				SET @ReturnInt=0
			END


		ELSE IF(@CONDITION='GET_LINE_STATUS')
			BEGIN
			
			SELECT  @LineCode= LineCode,@DateCode= Datecode,@PartNumber= Assy_PartNo FROM assy_runningpart(nolock) --where LineCode=@LineCode and Datecode=@DateCode
				SELECT TOP 1 * from assy_runningpart(nolock)
												WHERE ProfitCenterCode=@PROFITCENTERCODE AND LineCode=@LineCode AND Datecode=@DateCode ORDER BY LineCode DESC
			END

			ELSE IF(@CONDITION='GET_LINE_RUNNING_STATUS')
			BEGIN
				
				SELECT * from Assy_RunningPart(nolock)
												WHERE ProfitCenterCode=@PROFITCENTERCODE AND PartType='TMC' ORDER BY LineCode DESC
				
				SET @ReturnValue='SUCCESS'
				SET @ReturnInt=0
			END
			--Line Status get pass quantity for the day and month
		IF(@CONDITION='GET_ASSY_LINE_RUNNING_STATUS')
			BEGIN
				SELECT  @DateCode= Datecode,@PartNumber= Assy_PartNo FROM assy_runningpart (nolock) where LineCode=@LineCode
				SELECT  LineCode,Datecode,Assy_PartNo,ProductionOrderNo,CurrentPlannedQty FROM assy_runningpart(nolock) where LineCode=@LineCode and Datecode=@DateCode
			
				--select Assy_PartNo,currentplannedqty from assy_runningpart(nolock) 
				--	where ProfitCenterCode=@ProfitCenterCode 
				--		and LineCode=@Linecode
					
			EXEC @MachinCode=[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode @PROFITCENTERCODE=@PROFITCENTERCODE,@LineCode=@LineCode
				select ProfitCenterCode,LineCode,SUM(CASE WHEN ISNULL(STATUS,'')='PS' THEN 1 ELSE 0 END) AS PASS
												from Assy_LineAssyStatus (nolock)
												WHERE ProfitCenterCode=@ProfitCenterCode AND LineCode=@LineCode 
												AND day(ResultTimestamp)=day(Getdate())
												AND MachineCode=@MachinCode
												AND Month(ResultTimestamp)=Month(Getdate())
												AND YEAR(ResultTimestamp)=YEAR(Getdate())
												GROUP BY ProfitCenterCode,LineCode--where Datecode='05Yc' --where linecode=@linecode and Datecode=@DateCode and PartNo=@PartNumber

				select ProfitCenterCode,LineCode,SUM(CASE WHEN ISNULL(STATUS,'')='PS' THEN 1 ELSE 0 END) AS PASS
												from Assy_LineAssyStatus (nolock)
												WHERE ProfitCenterCode=@ProfitCenterCode 
													AND LineCode=@LineCode
													AND MachineCode=@MachinCode
													AND Month(ResultTimestamp)=Month(Getdate())
													AND YEAR(ResultTimestamp)=YEAR(Getdate())
													GROUP BY ProfitCenterCode,LineCode

				SET @ReturnValue='SUCCESS'
				SET @ReturnInt=0
			END

			IF(@CONDITION='GET_LINE_DETAILS')
				BEGIN
					select LineCode,LineName from linemst (nolock)
					where LineTypeCode in ('LTTMC','LTSTMC') 
						and WorkCenterCode<>'1001' 
						and Isactive=1
						and ProfitCenterCode=@ProfitCenterCode
						--and LineCode in (select LineCode from assy_runningpart(nolock))
					SET @ReturnValue='SUCCESS'
					SET @ReturnInt=0
				END
		IF(@CONDITION='GET_ASSY_LINE_RUNNING_STATUS_TMC')
			BEGIN
				select ProfitCenterCode,SUM(CASE WHEN ISNULL(STATUS,'')='PS' THEN 1 ELSE 0 END) AS PASS
												from Assy_LineAssyStatus (nolock)
												WHERE ProfitCenterCode=@ProfitCenterCode 
													AND SUBSTRING(LineCode,1,1)='M'
													AND Month(ResultTimestamp)=Month(Getdate())
													AND YEAR(ResultTimestamp)=YEAR(Getdate())
												GROUP BY ProfitCenterCode

				select ProfitCenterCode,LineCode,Partno,SUM(CASE WHEN ISNULL(STATUS,'')='PS' THEN 1 ELSE 0 END) AS PASS
												from Assy_LineAssyStatus (nolock)
												WHERE ProfitCenterCode=@ProfitCenterCode 
													AND SUBSTRING(LineCode,1,1)='M'
													AND Month(ResultTimestamp)=Month(Getdate())
													AND YEAR(ResultTimestamp)=YEAR(Getdate())
												GROUP BY ProfitCenterCode,LineCode,Partno


				select ProfitCenterCode,SUM(CASE WHEN ISNULL(STATUS,'')='PS' THEN 1 ELSE 0 END) AS PASS
												from Assy_LineAssyStatus (nolock)
												WHERE ProfitCenterCode=@ProfitCenterCode 
													AND SUBSTRING(LineCode,1,1)='S'
													AND Month(ResultTimestamp)=Month(Getdate())
													AND YEAR(ResultTimestamp)=YEAR(Getdate())
												GROUP BY ProfitCenterCode


				select ProfitCenterCode,LineCode,Partno,SUM(CASE WHEN ISNULL(STATUS,'')='PS' THEN 1 ELSE 0 END) AS PASS
												from Assy_LineAssyStatus (nolock)
												WHERE ProfitCenterCode=@ProfitCenterCode 
													AND SUBSTRING(LineCode,1,1)='S'
													AND Month(ResultTimestamp)=Month(Getdate())
													AND YEAR(ResultTimestamp)=YEAR(Getdate())
												GROUP BY ProfitCenterCode,LineCode,Partno


				select ProfitCenterCode,SUM(CASE WHEN ISNULL(STATUS,'')='PS' THEN 1 ELSE 0 END) AS PASS
												from Assy_LineAssyStatus (nolock)
												WHERE ProfitCenterCode=@ProfitCenterCode 
													AND SUBSTRING(LineCode,1,1)='F'
													AND Month(ResultTimestamp)=Month(Getdate())
													AND YEAR(ResultTimestamp)=YEAR(Getdate())
												GROUP BY ProfitCenterCode

				select ProfitCenterCode,LineCode,Partno,SUM(CASE WHEN ISNULL(STATUS,'')='PS' THEN 1 ELSE 0 END) AS PASS
												from Assy_LineAssyStatus (nolock)
												WHERE ProfitCenterCode=@ProfitCenterCode 
													AND SUBSTRING(LineCode,1,1)='F'
													AND Month(ResultTimestamp)=Month(Getdate())
													AND YEAR(ResultTimestamp)=YEAR(Getdate())
												GROUP BY ProfitCenterCode,LineCode,Partno
				SET @ReturnValue='SUCCESS'
				SET @ReturnInt=0
			END

	 END TRY
	 BEGIN CATCH
		SET @ReturnValue =	CAST(ERROR_NUMBER() as varchar(5)) + '|' + 
			CAST(ERROR_SEVERITY()as varchar(5)) + '|' + 
			CAST(ERROR_STATE() as varchar(5)) + '|' + 
			CAST(ERROR_PROCEDURE() as varchar(200)) + '|' + 
			CAST(ERROR_LINE() as varchar(5)) + '|' + 
			CAST(ERROR_MESSAGE() as varchar(1500))
			RAISERROR (@ReturnValue,16,1)						
		   SET @ReturnInt = 2
	 END CATCH

END



GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_Database_Backup]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROCEDURE [dbo].[Assy_Proc_Database_Backup]
            @databaseName sysname = null,   
            @backupType CHAR(1),   
            @backupLocation nvarchar(200)    
AS    
   
    -- =============================================    
	-- Author: Ravishankar Mishra    
	-- Create date: 02/06/2015 
	-- Description: Backup Databases for SQLExpress   
	-- Parameter1: databaseName    
	-- Parameter2: backupType F=full, D=differential, L=log  
	-- Parameter3: backup file location  
	-- =============================================   
       SET NOCOUNT ON;    
              
            DECLARE @DBs TABLE  
            (  
                  ID int IDENTITY PRIMARY KEY,  
                  DBNAME nvarchar(500)  
            )  
     --         -- Add By Rashid on 28 Sep 2015
			  Declare @LineCode VARCHAR(3) = ''
			  SELECT Top 1 @LineCode = ISNULL(LineCode,'') FROM dbo.LineMst (NOLOCK) Order By ent_stamp Desc
             -- Pick out only databases which are online in case ALL databases are chosen to be backed up  
             -- If specific database is chosen to be backed up only pick that out from @DBs  
            INSERT INTO @DBs (DBNAME)   
            SELECT Name FROM master.sys.databases   
            where state=0  
            AND name=@DatabaseName   
            OR @DatabaseName IS NULL   
            ORDER BY Name  
              
            -- Filter out databases which do not need to backed up  
            IF @backupType='F'  
                  BEGIN  
                  DELETE @DBs where DBNAME IN ('tempdb','Northwind','pubs','AdventureWorks')  
                  END  
            ELSE IF @backupType='D'  
                  BEGIN  
                  DELETE @DBs where DBNAME IN ('tempdb','Northwind','pubs','master','AdventureWorks')  
                  END  
            ELSE IF @backupType='L'  
                  BEGIN  
                  DELETE @DBs where DBNAME IN ('tempdb','Northwind','pubs','master','AdventureWorks')  
                  END  
            ELSE  
                  BEGIN  
                  RETURN  
                  END  
              
            -- Declare variables  
            DECLARE @BackupName varchar(100)  
            DECLARE @BackupFile varchar(100)  
            DECLARE @DBNAME varchar(300)  
            DECLARE @sqlCommand NVARCHAR(1000)    
        DECLARE @dateTime NVARCHAR(20)  
            DECLARE @Loop int                     
                          
            -- Loop through the databases one by one  
            SELECT @Loop = min(ID) FROM @DBs  
   
      WHILE @Loop IS NOT NULL  
      BEGIN  
   
-- Database Names have to be in [dbname] format since some have - or _ in their name  
      SET @DBNAME = '['+(SELECT DBNAME FROM @DBs WHERE ID = @Loop)+']'  
		
-- Set the current date and time n yyyyhhmmss format  
      SET @dateTime = REPLACE(CONVERT(VARCHAR, GETDATE(),103),'/','') + '_' +  REPLACE(CONVERT(VARCHAR, GETDATE(),108),':','')     
   
-- Create backup filename in path\filename.extension format for full,diff and log backups  
      IF @backupType = 'F'   
            SET @BackupFile = @backupLocation+REPLACE(REPLACE(@DBNAME, '[',''),']','')+ '_FULL_'+ @dateTime+ '_' + @LineCode + '.BAK'  
      ELSE IF @backupType = 'D'   
            SET @BackupFile = @backupLocation+REPLACE(REPLACE(@DBNAME, '[',''),']','')+ '_DIFF_'+ @dateTime+ '_' + @LineCode + '.BAK'  
      ELSE IF @backupType = 'L'  
            SET @BackupFile = @backupLocation+REPLACE(REPLACE(@DBNAME, '[',''),']','')+ '_LOG_'+ @dateTime+ '_' + @LineCode + '.TRN'  
  
-- Provide the backup a name for storing in the media  
      IF @backupType = 'F'  
            SET @BackupName = REPLACE(REPLACE(@DBNAME,'[',''),']','') +' full backup for '+ @dateTime  
      IF @backupType = 'D'  
            SET @BackupName = REPLACE(REPLACE(@DBNAME,'[',''),']','') +' differential backup for '+ @dateTime  
      IF @backupType = 'L'  
            SET @BackupName = REPLACE(REPLACE(@DBNAME,'[',''),']','') +' log backup for '+ @dateTime  
   
-- Generate the dynamic SQL command to be executed  
		
       IF @backupType = 'F'    
                  BEGIN  
               SET @sqlCommand = 'BACKUP DATABASE ' +@DBNAME+  ' TO DISK = '''+@BackupFile+ ''' WITH INIT, NAME= ''' +@BackupName+''', NOSKIP, NOFORMAT'  
                  END  
       IF @backupType = 'D'   
                  BEGIN   
               SET @sqlCommand = 'BACKUP DATABASE ' +@DBNAME+  ' TO DISK = '''+@BackupFile+ ''' WITH DIFFERENTIAL, INIT, NAME= ''' +@BackupName+''', NOSKIP, NOFORMAT'           
                  END  
       IF @backupType = 'L'    
                  BEGIN  
               SET @sqlCommand = 'BACKUP LOG ' +@DBNAME+  ' TO DISK = '''+@BackupFile+ ''' WITH INIT, NAME= ''' +@BackupName+''', NOSKIP, NOFORMAT'           
                  END  
   
-- Execute the generated SQL command  
       EXEC(@sqlCommand)  
	   exec [PROC_CHECK_AVAILABLE_DB_SIZE]
	   Declare @bcktype varchar(50)
	   IF @backupType = 'F'
	   BEGIN  
		  set @bcktype= 'Full'
	   END  
	   ELSE IF @backupType = 'D'
	   BEGIN  
		  set @bcktype= 'Differential'
	   END 
	   ELse IF @backupType = 'L'
	   BEGIN  
		  set @bcktype= 'Log'
	   END 
	   Insert into DatabaseBackupLog(DBBackupFileName,DBBackupType) values (@BackupFile,@bcktype)
-- Goto the next database  
SELECT @Loop = min(ID) FROM @DBs where ID>@Loop  

IF @backupType = 'F'    
 exec dbo.Assy_Proc_Shrink_LogFile
   
END  

GO
/****** Object:  StoredProcedure [dbo].[Assy_PROC_DATE_TO_DATECODE]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
--declare @RETURNINT int,  
--@RETURNVALUE varchar(2000)
--exec [Assy_PROC_DATE_TO_DATECODE] '2015-12-28 07:30:32.250',@RETURNVALUE  out,@RETURNINT   out
--select @RETURNVALUE,@RETURNINT



CREATE PROC [dbo].[Assy_PROC_DATE_TO_DATECODE] (
											@DATE DATETIME,
                                            @RETURNVALUE      VARCHAR (2000)=NULL OUT,
                                            @RETURNINT        INT=NULL OUT
											)
AS
  BEGIN
      DECLARE @DATECODEPARM CHAR(4)=NULL

      BEGIN TRY
          SET NOCOUNT ON
		  DECLARE @DAY      VARCHAR(20), 
				  @YEAR     VARCHAR(20), 
				  @WEEKCODE VARCHAR(12),
				  @CURRENTDATECODE VARCHAR(10),
				  @FROMTIME TIME, 
				  @TOTIME   TIME,
				  @PROFITCENTERCODE char(5) = '0021'
				  
			--Select GETDATE()
			
        SELECT @DAY = DATENAME(WEEKDAY, @DATE)
        SELECT @YEAR = DATENAME(YEAR, @DATE)
        SELECT @WeekCode = Right('0'+ Datename(ISO_WEEK,@DATE),2)	
		DECLARE @WEEKDAY VARCHAR(20)
        SET  @WEEKDAY=UPPER(DATENAME(WEEKDAY,@DATE))					
		IF @WEEKCODE=53
		BEGIN
				IF  @WEEKDAY='FRIDAY' OR @WEEKDAY='SATURDAY' OR @WEEKDAY='SUNDAY'
				BEGIN
						SET @YEAR=@YEAR-1
				END					
		END				

   -- --      SELECT @DAY = DATENAME(WEEKDAY, GETDATE())
		 -- Select  @DAY = DATENAME(WEEKDAY, @Date)
		 -- --Print @DAY
   --       SELECT @YEAR = DATENAME(YEAR, @Date)
   --       --SELECT @WEEKCODE = RIGHT('0' + DATENAME(WEEK, GETDATE()), 2)
		 -- --Get Week code
			--if (@DAY)='SUNDAY'
			--BEGIN
				
			--		SELECT  @WeekCode= Right('0'+convert(varchar(5), convert(int,Datename(week,@Date))-1),2)
			--END
			--ELSE
			--	BEGIN
			--		SELECT @WeekCode = Right('0'+ Datename(week,@Date),2)
			--	END


          --IF RTRIM(@WEEKCODE) = '53'
          --  BEGIN
          --      SET @WEEKCODE='01'

          --      SELECT @YEAR = DATENAME(YEAR, DATEADD(YY, 1, @Date))
          --  END

          ------- TO GET CURRENT SHIFT      
          DECLARE @CURRENTTIME AS TIME,
                  @TIME        AS VARCHAR(10),
                  @SHIFT       AS VARCHAR(10),
                  @SHIFTCODE   VARCHAR(10)

          SET @CURRENTTIME=@Date
          --SET @TIME=LEFT(CONVERT(VARCHAR(10), @CURRENTTIME), 8)
		  SET @TIME=CONVERT(VARCHAR(5),@Date,108)

          -- EXEC SHIFTMST_USP '02:30:01' , SHIFT OUTPUT,@SHIFTCODE OUTPUT  
          EXEC ASSY_PROC_GET_SHIFTDETAILS
				@PROFITCENTERCODE,
				@TIME,
				@SHIFT OUTPUT,
				@SHIFTCODE OUTPUT

          --GET CURRENT DAY FOR NIGHT
          IF @SHIFT = 'NIGHT'
            BEGIN
                SELECT @FROMTIME = CONVERT(TIME, FROMTIME), @TOTIME = CONVERT(TIME, TOTIME)
                FROM   SHIFTMST(NOLOCK)
                WHERE  SHIFTNAME = 'NIGHT'
                       AND ISACTIVE = 1
                       AND PROFITCENTERCODE = @PROFITCENTERCODE

                IF @TOTIME > @FROMTIME
                  SET @DAY=@DAY
                ELSE IF CONVERT(TIME, @TIME) <= (SELECT CONVERT(TIME, TOTIME)
													FROM   SHIFTMST(NOLOCK)
													WHERE  SHIFTNAME = 'NIGHT'
														   AND ISACTIVE = 1
														   AND PROFITCENTERCODE = @PROFITCENTERCODE)
                  SELECT @DAY = DATENAME(WEEKDAY, DATEADD(D, -1, @Date))
                ELSE
                  SET @DAY=@DAY
            END
          --GET CURRENT DAY FOR OT
          ELSE IF @SHIFT = 'OT'
            BEGIN
                SELECT @FROMTIME = CONVERT(TIME, FROMTIME),
                       @TOTIME = CONVERT(TIME, TOTIME)
                FROM   SHIFTMST(NOLOCK)
                WHERE  SHIFTNAME = 'OT'
                       AND ISACTIVE = 1
                       AND PROFITCENTERCODE = @PROFITCENTERCODE

                IF @TOTIME > @FROMTIME
                  SELECT @DAY = DATENAME(WEEKDAY, DATEADD(D, -1, @Date))
                ELSE IF CONVERT(TIME, @TIME) <= (SELECT CONVERT(TIME, TOTIME)
                                            FROM   SHIFTMST(NOLOCK)
                                            WHERE  SHIFTNAME = 'OT'
                                                   AND ISACTIVE = 1
                                                   AND
                        PROFITCENTERCODE = @PROFITCENTERCODE)
                  SELECT @DAY = DATENAME(WEEKDAY, DATEADD(D, -1, @Date))
                ELSE
                  SET @DAY=@DAY
            END

          --SELECT @SHIFT ,@SHIFTID    
          --SELECT * FROM DATECODEMST WHERE SHIFTID=@SHIFTID AND YEAR=@YEAR    
          --SELECT * AFROM SHIFTMST    
          --SELECT @DAY AS 'DAY'
          DECLARE @DATECODE TABLE
            (
               SHIFTCODE      VARCHAR(10),
               DAY            VARCHAR(20),
               CODE           VARCHAR(2),
               ENT_STAMP      DATETIME,
               ENT_BY         VARCHAR(20),
               LAST_UPD_BY    VARCHAR(20),
               LAST_UPD_STAMP DATETIME
            )

          INSERT INTO @DATECODE
          SELECT SHIFTCODE,
                 DAY1,
                 CODE,
                 ENT_STAMP,
                 ENT_BY,
                 LAST_UPD_BY,
                 LAST_UPD_STAMP
          FROM   (SELECT SHIFTCODE,
                         [MONDAY],
                         [TUESDAY],
                         [WEDNESDAY],
                         [THURSDAY],
                         [FRIDAY],
                         [SATURDAY],
                         [SUNDAY],
                         ENT_STAMP,
                         ENT_BY,
                         LAST_UPD_BY,
                         LAST_UPD_STAMP
                  FROM   DATECODEMST
                  WHERE  PROFITCENTERCODE = @PROFITCENTERCODE) P
                 UNPIVOT (CODE
                         FOR DAY1 IN (MONDAY,
                                      [TUESDAY],
                                      [WEDNESDAY],
                                      [THURSDAY],
                                      [FRIDAY],
                                      [SATURDAY],
                                      [SUNDAY] ) )AS UNPVT
          WHERE  SHIFTCODE = @SHIFTCODE
                 AND DAY1 = @DAY

	if @WEEKDAY='MONDAY' and @CurrentTime<=(select fromtime from ShiftMst(nolock)  where shiftname='Day' and ProfitCenterCode=@PROFITCENTERCODE)
	begin

			declare @PrevYearWeekCode tinyint
			SELECT @PrevYearWeekCode=Right('0'+ Datename(ISO_WEEK,Getdate()-1),2)	
			if (@PrevYearWeekCode=53 or @PrevYearWeekCode=52) and @weekCode=1
			begin

				set @weekCode= right(0+@PrevYearWeekCode,2)
				SET @YEAR=@YEAR-1
			end
			else
			begin
					set @weekCode=@weekCode-1
					SELECT @WeekCode = Right('0'+@weekCode, 2)	
			end
	end
          SELECT @CURRENTDATECODE = @WEEKCODE
                                    + (SELECT UPPER(RTRIM(CODE))
                                       FROM   @DATECODE)
                                    + (SELECT LOWER(LTRIM (RTRIM(CODE)))
                                       FROM   YEARMST
                                       WHERE  YEAR = @YEAR)
									             


	SET @DATECODEPARM=@CURRENTDATECODE
          
		  SET @RETURNVALUE=@CURRENTDATECODE
          SET @RETURNINT=1

          SELECT @DATECODEPARM
      END TRY

      BEGIN CATCH
          --CATCH BLOCK BEGINS
          SET @RETURNVALUE = CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|'
                             + CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|'
                             + CAST(ERROR_STATE() AS VARCHAR(5)) + '|'
                             + CAST(ERROR_PROCEDURE() AS VARCHAR(200))
                             + '|' + CAST(ERROR_LINE() AS VARCHAR(5)) + '|'
                             + CAST(ERROR_MESSAGE() AS VARCHAR(1500))
          SET @RETURNINT = 2
      --CATCH BLOCK ENDS 
      END CATCH
  END 

GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_DateCode]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROC [dbo].[Assy_Proc_DateCode]
(
	@ProfitCenterCode VARCHAR(10), 
	@ReturnValue VARCHAR (2000) = NULL OUT, 
	@ReturnInt INT = NULL OUT,
	@Condition VARCHAR(100) = '',	--Added By THK ON 10-05-2019
	@ManualDate DATETIME = NULL
)
AS
BEGIN
	/*
		Author:			< Ravishankar Mishra >
		Create Date:	< 17 march 2015 >
		Description:	< Get Date Code >
		Modified By:	< Rashid Siddiqui >
		Modified Date:	< 20181227 >
		Description:	< HANDLE CASE OF 31122018 - 01AF>
		Modified Date:	< 20190515 >
		Description:	< Shift Information >

		DECLARE @ReturnValue CHAR(1000) 
		EXEC Assy_Proc_DateCode_20122022 @ProfitCenterCode = '0021', @ReturnValue = @ReturnValue output 
		SELECT @ReturnValue 
	*/
	SET NOCOUNT ON;
	DECLARE @DATE_VAL DATETIME
	DECLARE @DAY VARCHAR(20), @YEAR VARCHAR(20), @WEEKCODE VARCHAR(12)
	DECLARE @WEEKDAY VARCHAR(20)
	DECLARE @CurrentDateCode VARCHAR(10)

	IF @ManualDate IS NULL
	BEGIN
		SET @DATE_VAL = GETDATE()
	END
	ELSE
	BEGIN
		SET @DATE_VAL = @ManualDate
	END

	SELECT @DAY = DATENAME(WEEKDAY, @DATE_VAL)
	SELECT @YEAR = DATENAME(YEAR, @DATE_VAL)
	SELECT @WEEKCODE = RIGHT('0' + DATENAME(ISO_WEEK, @DATE_VAL), 2)	
	SELECT @WEEKDAY = UPPER(DATENAME(WEEKDAY, @DATE_VAL))
	
	--IF @WEEKCODE = 52
	--BEGIN
	--	IF @WEEKDAY = 'SUNDAY'
	--	BEGIN
	--		SELECT @YEAR = '2023'
	--	END
	--END	
					
	IF @WEEKCODE = 53
	BEGIN
		IF @WEEKDAY = 'FRIDAY' OR @WEEKDAY = 'SATURDAY' OR @WEEKDAY = 'SUNDAY'
		BEGIN
			SET @YEAR = @YEAR - 1
		END
	END					
	 -- ADDED BY RS ON 20181227 - HANDLE CASE OF 31122018 - 01AF
	DECLARE @MONTH INT = 0
	SET @MONTH = MONTH(@DATE_VAL)

	--select @MONTH, @WEEKCODE, @YEAR
	IF @MONTH = 12 AND @WEEKCODE = '01'
	BEGIN
		SET @YEAR = @YEAR + 1
	END

	DECLARE @FromTime TIME, @ToTime TIME					
	 --To Get current shift
	DECLARE @CurrentTime AS TIME, @Time AS VARCHAR(10), @Shift AS VARCHAR(10), @ShiftCode VARCHAR(10)
	print @FromTime
	print @ToTime
	SET @CurrentTime = @DATE_VAL
	SET @Time = LEFT(CONVERT(VARCHAR(10), @CurrentTime), 8)					
	
	EXEC Assy_Proc_ShiftMst	@time , @ProfitCenterCode, @Shift OUTPUT, @ShiftCode OUTPUT
	
	 -- Get Current day for Night
	IF @Shift = 'NIGHT'
	BEGIN
		SELECT @FromTime = CONVERT(TIME, FromTime), @ToTime = CONVERT(TIME, ToTime)
		FROM ShiftMst (NOLOCK)
			WHERE ShiftName = @Shift AND IsActive = 1 AND ProfitCenterCode = @ProfitCenterCode

		IF @ToTime > @FromTime
			SET @Day = @Day
		ELSE
			IF CONVERT(TIME, @Time) < = (SELECT CONVERT(TIME, ToTime) FROM ShiftMst (NOLOCK) WHERE ShiftName = @Shift
				AND IsActive = 1 AND ProfitCenterCode = @ProfitCenterCode)
			SELECT @DAY = DATENAME(WEEKDAY, DATEADD(d, - 1, @DATE_VAL))
		ELSE
			SET @Day = @Day
	END
	 -- Get Current day for OT
	ELSE IF @Shift = 'OT'
	BEGIN
		SELECT @FromTime = CONVERT(TIME, FromTime), @ToTime = CONVERT(TIME, ToTime)
			FROM ShiftMst (NOLOCK)
				WHERE ShiftName = @Shift AND IsActive = 1 AND ProfitCenterCode = @ProfitCenterCode

		IF @ToTime > @FromTime
			SELECT @DAY = DATENAME(WEEKDAY, DATEADD(d, - 1, @DATE_VAL))
		ELSE
		IF CONVERT(TIME, @Time) < = (SELECT CONVERT(TIME, ToTime) FROM ShiftMst (NOLOCK) WHERE ShiftName = @Shift
				AND IsActive = 1 AND ProfitCenterCode = @ProfitCenterCode)
			SELECT @DAY = DATENAME(WEEKDAY, DATEADD(d, - 1, @DATE_VAL))
		ELSE
			SET @Day = @Day
	END

	DECLARE @Datecode TABLE
	(
		ShiftCode VARCHAR(10), 
		DAY VARCHAR(20), 
		Code VARCHAR(2), 
		Ent_Stamp DATETIME, 
		Ent_By VARCHAR(20), 
		Last_Upd_By VARCHAR(20), 
		Last_Upd_Stamp DATETIME
	)

	INSERT INTO @Datecode
	SELECT
		ShiftCode, 
		Day1, 
		Code, 
		Ent_Stamp, 
		Ent_By, 
		Last_Upd_By, 
		Last_Upd_Stamp
	FROM
		(
			SELECT
			ShiftCode, 
			[Monday], 
			[Tuesday], 
			[Wednesday], 
			[Thursday], 
			[Friday], 
			[Saturday], 
			[Sunday], 
			Ent_Stamp, 
			Ent_By, 
			Last_Upd_By, 
			Last_Upd_Stamp
			FROM DateCodeMst (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
		) P
	UNPIVOT
	(
		Code
			FOR Day1 IN ( Monday, [Tuesday], [Wednesday], [Thursday], [Friday], [Saturday], [Sunday] ) ) AS unpvt
				WHERE ShiftCode = @ShiftCode
		AND Day1 = @Day
	 -- Get date Code = week Code + shift Code + year Code
						
	IF @WEEKDAY = 'MONDAY' AND @CurrentTime< = (SELECT FromTime FROM ShiftMst(NOLOCK) WHERE ShiftName = 'Day' AND ProfitCenterCode = @ProfitCenterCode)
	BEGIN
	print 1
		DECLARE @PrevYearWeekCode TINYINT
		SELECT @PrevYearWeekCode = RIGHT('0' + DATENAME(ISO_WEEK, @DATE_VAL - 1), 2)	
		
		IF (@PrevYearWeekCode = 53 OR @PrevYearWeekCode = 52) AND @WEEKCODE = 1
		BEGIN
			SET @WEEKCODE = RIGHT(0 + @PrevYearWeekCode, 2)
			SET @YEAR = @YEAR - 1
		END
		ELSE
		BEGIN
			SET @WEEKCODE = @WEEKCODE - 1
			SELECT @WEEKCODE = RIGHT('0' + @WEEKCODE, 2)	
		END
	END

	SELECT @CurrentDateCode = @WEEKCODE
		+ (SELECT UPPER(RTRIM(Code)) FROM @Datecode)
		+ (SELECT LOWER(LTRIM(RTRIM(Code))) FROM YearMst (NOLOCK) WHERE YEAR = @YEAR)

	IF @Condition = 'ShiftTime' --Added By THK ON 10-05-2019
	BEGIN
		SELECT @CurrentDateCode CurrentDateCode, FromTime, ToTime FROM ShiftMst (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND ShiftName = @Shift
	END

	SET @ReturnValue = @CurrentDateCode
	SET @ReturnInt = 1
END

GO
