/****** Object:  StoredProcedure [dbo].[Assy_PROC_DateCode_Mode_CHANGED]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [dbo].[Assy_PROC_DateCode_Mode_CHANGED]
(
@Operation Varchar(20),
@LineCode varchar(30),
@ProfitCenterCode varchar(20),
@IsAutomatic bit =0,
@DateCode char(4)=NULL,
@UserId varchar(50)=NULL,
@ReturnValue VARCHAR (2000)=NULL OUT,
@ReturnInt INT=NULL OUT    
)
AS
BEGIN
--Author :<Ravishankar Mishra>
--Created Date: <19/12/2014>
	
   BEGIN TRY 
       set nocount on
       if @Operation='UPDATE'
       begin
	         BEGIN TRY
			   BEGIN TRAN	
					if exists(select isautomatic from Assy_datecode_mode(nolock) where linecode=@LineCode)
					begin
							update Assy_datecode_mode set datecode=@DateCode, isAutomatic=@isAutomatic,timestamp=getdate(),userid=@UserId 
							where linecode=@LineCode and ProfitCenterCode=@ProfitCenterCode						
					end
					else 
						begin
							 insert into Assy_datecode_mode(LineCode,DateCode,IsAutomatic,userid,timestamp,ProfitCenterCode) 
							 values(@linecode,@datecode,@isautomatic,@UserId,getdate(),@ProfitCenterCode)
						end			
						update Assy_RunningPart set Datecode=@DateCode,ModifiedOn=getdate(),ModifiedBy=@UserId where linecode=@LineCode
						update Assy_ProductionOrder_ParameterSetting set Datecode=@DateCode where linecode=@LineCode and ProfitCenterCode=@ProfitCenterCode

				COMMIT TRAN
			END TRY
			 BEGIN CATCH
					
						SET @ReturnValue =	CAST(ERROR_NUMBER() as varchar(5)) + '|' + 
						CAST(ERROR_SEVERITY()as varchar(5)) + '|' + 
						CAST(ERROR_STATE() as varchar(5)) + '|' + 
						CAST(ERROR_PROCEDURE() as varchar(200)) + '|' + 
						CAST(ERROR_LINE() as varchar(5)) + '|' + 
						CAST(ERROR_MESSAGE() as varchar(1500))							
						SET @ReturnInt = 2
						ROLLBACK TRAN
						raiserror(@ReturnValue,16,1)
			END CATCH	


       end  
       
       else if @Operation='select'
       begin
           select IsAutomatic from Assy_datecode_mode(nolock) where linecode=@LineCode and ProfitCenterCode=@ProfitCenterCode
       end
	    set @ReturnValue='DATE CODE MODE UPDATED'
		set @ReturnInt=1
   END TRY
   BEGIN CATCH
     --CATCH BLOCK BEGINS
		SET @ReturnValue =	CAST(ERROR_NUMBER() as varchar(5)) + '|' + 
		CAST(ERROR_SEVERITY()as varchar(5)) + '|' + 
		CAST(ERROR_STATE() as varchar(5)) + '|' + 
		CAST(ERROR_PROCEDURE() as varchar(200)) + '|' + 
		CAST(ERROR_LINE() as varchar(5)) + '|' + 
		CAST(ERROR_MESSAGE() as varchar(1500))							
		SET @ReturnInt = 2
	    raiserror(@ReturnValue,16,1)


   END CATCH
end
GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_DateCodeStamping]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[Assy_Proc_DateCodeStamping]
(
@CONDITION VARCHAR(50),
@LineCode varchar(20)=null,
@Barcode varchar(30)=null,
@ReturnValue VARCHAR (2000)=NULL OUT,
@ReturnInt INT=NULL OUT,
@ProfitCenterCode varchar(20)=null
)
AS
BEGIN
		 SET NOCOUNT ON
		-- Author:		<Ravishankar Mishra>
		-- Create date: < 13 march 2015>
		-- Modified date: < 23 Feb 2016>
		-- Description:	<Date code stamping>

		-- To Rembember
		-- Nothing = 0
		-- Success = 1
		-- Error = 2
		-- AlreadyExists = 3
		-- NotExists = 4

			--declare @ReturnValue varchar(20)
			--exec Assy_Proc_DateCodeStamping @CONDITION='Check_DateCodeStamping_Required',@LineCode ='M07',@ProfitCenterCode='0021',@ReturnValue=@ReturnValue out

			--select @ReturnValue
			--exec Assy_Proc_DateCodeStamping @CONDITION='Update_Stamping_ACK',@LineCode ='M07'
			----select * from assy_DateCodeStamping
			--delete assy_DateCodeStamping
			----exec Assy_Proc_DateCodeStamping @CONDITION='RESET',@LineCode ='M07',@ProfitCenterCode='0021'


		--UPDATE SCAN ok  form procedure, Assy_PROC_FinalViewing	
		 IF @CONDITION='Update_ScanOK'
		 BEGIN
		        IF EXISTS
				( 
				           
							select top 1  L.LineCode   from RoutingConfigLineWise(nolock) L 
							--inner join RoutingConfigPartWise(nolock) P 
							--	on L.ProfitCenterCode=p.ProfitCenterCode 
							--	and l.OperationCode =p.OperationCode   
							--	and l.MachineCode  =p.MachineCode										 
							where l.LineCode =@LineCode
							--and P.PartNo=(select Assy_PartNo from Assy_RunningPart where LineCode =@LineCode )
							and l.OperationRequired=1 
							--and p.OperationRequired =1
							and l.OperationCode =
							(
								select rtrim(ltrim( PARAMETER_VALUE)) PARAMETER_VALUE from PARAMETER_MST(nolock) 
								where PARAMETER_C ='assline' and PARAMETER_C1 ='FinalViewing' 
								and PARAMETER_C2 ='DateCodeStamping_OperationCode' and wh_code=@ProfitCenterCode 
							)
				)
				BEGIN
					  if exists(select top 1 barcode from Assy_DateCodeStamping(nolock) where  LineCode=@LineCode)
						   update Assy_DateCodeStamping set timestamp=getdate(),ISScan=1 
						   where  LineCode=@LineCode
					   else
						   insert into Assy_DateCodeStamping(LineCode,timestamp,ISScan) 
						   values(@LineCode,getdate(),1)
							
							set @ReturnInt=1
						    set @ReturnValue='Success' 
				 END
					   
		 END
		 --update table by PLC application after getting date code stamping ack from plc
		 ELSE IF @CONDITION='Update_Stamping_ACK'
		 BEGIN
						select @Barcode=isnull(barcode,'') from assy_scan_ok with(nolock) where linecode=@Linecode 
						and machinecode=dbo.Assy_FN_Get_FinalViewing_MachineCode_From_LineCode(@Profitcentercode,@Linecode)
		 				
						 update Assy_DateCodeStamping set isACK=1 ,barcode=@Barcode
						   where  LineCode=@LineCode				  

							 set @ReturnInt=1
						    set @ReturnValue='Success' 
					   
		 END
		 --Reset ack. after marking a part pass or fail ,called from procedure- Assy_PROC_FinalViewing
         ELSE IF @CONDITION='RESET_ACK'
         BEGIN
						IF EXISTS
						( 
									select top 1  L.LineCode   from RoutingConfigLineWise(nolock) L 
									--inner join RoutingConfigPartWise(nolock) P 
									--	on L.ProfitCenterCode=p.ProfitCenterCode 
									--	and l.OperationCode =p.OperationCode   
									--	and l.MachineCode  =p.MachineCode										 
									where l.LineCode =@LineCode
									--and P.PartNo=(select Assy_PartNo from Assy_RunningPart where LineCode =@LineCode )
									and l.OperationRequired=1 
									--and p.OperationRequired =1
									and l.OperationCode =
									(
										select rtrim(ltrim( PARAMETER_VALUE)) PARAMETER_VALUE from PARAMETER_MST(nolock) 
										where PARAMETER_C ='assline' and PARAMETER_C1 ='FinalViewing' 
										and PARAMETER_C2 ='DateCodeStamping_OperationCode' and wh_code=@ProfitCenterCode 
									)
						)
						BEGIN
								update Assy_DateCodeStamping set barcode='',isACK=0 where LineCode=@LineCode
								set @ReturnInt=1
								set @ReturnValue='Success' 
						END
         end
		 --Reset scan ok from PLC application
		 ELSE IF @CONDITION='RESET_SCANOK'
         BEGIN
						
								update Assy_DateCodeStamping set ISScan=0 where LineCode=@LineCode
								set @ReturnInt=1
								set @ReturnValue='Success' 
         end
         --Read scan ok from PLC application
		 else if @CONDITION='Get_ScanOK'
         begin
              select @ReturnValue=isnull(LineCode,'') from  Assy_DateCodeStamping(nolock) where LineCode=@LineCode and isnull(ISScan,0)=1			    
			  set @ReturnInt=1
			  
         end
         --Get ack for showing stamping ack into tS GUI
        else if @CONDITION='select_ACK'
         begin
              select @ReturnValue=barcode from  Assy_DateCodeStamping(nolock) where LineCode=@LineCode 
			  and  isnull(isACK,0)=1 and (barcode is not null or barcode<>'')
              
			  if(select isnull(isACK,0)isACK from  Assy_DateCodeStamping(nolock) where LineCode=@LineCode and  isnull(isACK,0)=1)=1
					  update Assy_DateCodeStamping set isACK=0 where LineCode=@LineCode			   
			 set @ReturnInt=1
         end
		 
		 --check whether datecode stamping is required for this line and for this part no.
		 else if @CONDITION ='Check_DateCodeStamping_Required'
		 begin
				select top 1 @ReturnValue=  L.LineCode   from RoutingConfigLineWise(nolock) L 
				--inner join RoutingConfigPartWise(nolock) P 
					--on L.ProfitCenterCode=p.ProfitCenterCode 
					--and l.OperationCode =p.OperationCode   
					--and l.MachineCode  =p.MachineCode										 
				where l.LineCode =@LineCode
				--and P.PartNo=(select  top 1 Assy_PartNo from Assy_RunningPart(nolock) where LineCode =@LineCode  order by CreatedDate desc)
				and l.OperationRequired=1 
				--and p.OperationRequired =1
				and l.OperationCode =
				(
					select rtrim(ltrim( PARAMETER_VALUE)) PARAMETER_VALUE from PARAMETER_MST(nolock) 
					where PARAMETER_C ='assline' and PARAMETER_C1 ='FinalViewing' 
					and PARAMETER_C2 ='DateCodeStamping_OperationCode' and wh_code=@ProfitCenterCode 
				)

				set @ReturnInt=1
		 end

		 else IF @CONDITION='GET_LAST_STAMPED_BARCODE'		
			BEGIN
					select top 1 @RETURNVALUE=isnull(barcode,'') from Assy_DateCodeStamping(nolock) where  LineCode=@LineCode and isnull(barcode,'')<>''
					if(ISNULL(@RETURNVALUE,'') = '')
					BEGIN
						SET @RETURNVALUE = ''
					END
					SET @RETURNINT=1
					RETURN
			END

end
GO
