	 Testing Script:

	 exec [Assy_Proc_DBIntegration] @ProfitCode='0064',@LineCode='C05',@Operation ='GET_PLC_ROUTING'

	DECLARE @TBLE AS [Assy_TYPE_LineAssyParamData_Running] 
	INSERT INTO @TBLE
	SELECT '0088','J04','MC4s','OC4s','1','','','','FL','','ADMIN'
	union
	SELECT '0088','J04','MCCP','OCCP','1','2903305230Qd00000389J05','CALIPER_SERIAL_NO','0012','PS','','ADMIN'
	union
	SELECT '0088','J05','mc4s','OC4s','1','','ROT_STN.SEAL_NG','true','FL','','ADMIN'
	SELECT * FROM @TBLE
	EXEC [Assy_Proc_PLCIntegration_Jhagadia] @Operation='INSERT_PLC_PARAMS',@LineCode='J04',@tblParameters=@TBLE,@SUBSTNOPERATIONCODE='OCCN',@PokaYokeMode=1

	declare @ReturnValueOut VARCHAR (2000)=NULL
	EXEC [Assy_Proc_DBIntegration] 	@Operation='Get_CaliperSrNo',@LineCode='C05',@ProfitCode='0064', @ReturnValue=@ReturnValueOut out, @EngPartNo='29082562'
	select @ReturnValueOut

	 To Rembember
	 Nothing = 0
	 Success = 1
	 Error = 2
	 AlreadyExists = 3
	 NotExists = 4

= = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = */
CREATE PROCEDURE [dbo].[Assy_Proc_DBIntegration] 
       @ID INT=NULL,
       @ProfitCode Varchar(10)= NULL, 
       @Operation VARCHAR (40) = NULL,
       @MachineCode varchar(20) = null,
       @OperationCode varchar(20) = NULL,
       @Part_No varchar(10) = NULL,
       @LineCode varchar(10) = NULL,
       @ZigStatus bit = null,
       @StationCode varchar(10) = '1',
       @TagName varchar(50) = null,
       @TagValue varchar(1000) = null,
       @Barcode varchar(100) = null,
       @IsCycleStarted bit = null,
       @DateCode varchar(10) = null,
       @IsDuplicate bit = null,
       @IsIncorrect bit = null,
       @Status varchar(10) = null,
       @UserId varchar(25) = null,
       @Password varchar(30) = null,
       @tblParameters dbo.Assy_TYPE_LineAssyParamData_Running_DB readonly,
       @ReturnValue VARCHAR (2000)=NULL OUT,
       @ReturnInt INT=NULL OUT,
	   @PreCoupling_Data varchar(500)=null,
	   @TD_Table varchar(100) = null,
	   @EngPartNo varchar(12) = NULL,
	   @HMIPartNo varchar(12) = NULL
AS
BEGIN
			DECLARE @Assy_LotTrolleyDetailsId bigint = 0;
			DECLARE @OpRequired BIT=NULL;
              DECLARE @TraceabilityRequired bit = null;
              declare @failcount int = 0;
              declare @PokaYokeDateCode varchar(20);
              declare @IsTwinIndex bit = 0;
              declare @ScannedStationIndex int;
              declare @InsideStationIndex varchar(10);
              declare @IsTorqueRequired bit = 0;
              declare @FlagStatus varchar(10) = '' --Added By sachin 20170830
              declare @TagId int;
			  declare @ProdDate as date=getdate()
			  declare @SerialNo smallint=null 
			  declare @CaliperDatecode char(4)='',@CaliperSrNo smallint=0 --Added By sachin 20190603

              SET NOCOUNT ON             
              BEGIN TRY 
			  if(ISNULL(@LineCode,'') <> '')
              Begin
                   SELECT top 1 @Part_No=ISNULL(Assy_PartNo,''),@DateCode=Datecode,@UserId=CreatedBy FROM Assy_RunningPart with (nolock) WHERE LineCode = @LineCode order by CreatedBy desc
              End
			  ---------------Added By Prerna for Live_Datecode
			  	if(isnull(@ProfitCode,'')='')
				begin
				  select @ProfitCode=ProfitCenterCode from Linemst with(nolock) where linecode=@LineCode
				end
				Declare	@Live_Datecode char(4),@return_int int
				exec Assy_proc_datecode @ProfitCode,@Live_Datecode out,@return_int out
			  -------------END

       
         if(@Operation = 'GET_CHANNEL_DEVICE_DETAILS')
         Begin

              SELECT a.MachineCode, a.OperationCode,  c.ChannelName, c.DeviceName, a.TagName, c.PLCAddress, b.TagType, b.TagSignificance, c.PLCMake, c.IsKepwareSupported, e.Torque, e.IS_PLCLogsRequired FROM MachineTagMapping(nolock) as a
              inner join TagMst(nolock) as b on a.TagName = b.TagName
              inner join MachineDtl(nolock) as c on a.MachineCode = c.MachineCode and a.ProfitCenterCode = c.ProfitCenterCode and a.LineCode = c.LineCode and a.OperationCode = c.OperationCode
              inner join MachineMst(nolock) as d on a.MachineCode = d.MachineCode
              inner join RoutingConfigLineWise(nolock) as e on a.MachineCode = e.MachineCode and a.ProfitCenterCode = e.ProfitCenterCode and a.LineCode = e.LineCode and a.OperationCode = e.OperationCode 
              WHERE a.ProfitCenterCode = @ProfitCode and a.MachineCode = @MachineCode AND a.OperationCode =  @OperationCode AND a.LineCode = @LineCode
  order by a.FirstTag Desc
         End

              if(@Operation = 'VALIDATE_BYPASS_USER')
              Begin
                 
                 if exists
                 (
                    select top 1 1 from
                       (
                        select a.userid, b.Password from qcusers as a 
                        inner join tl_mf_sec_user_mst as b
                        on a.userid = b.USER_ID
                        inner join USER_SITE_MAP_MASTER as c
                        on a.userid = c.USER_ID
                        where a.userid = @UserId
                        and b.Password = @Password
                        and c.SITE_CODE = @ProfitCode )p
                 )
                 Begin
                   set @ReturnValue = 'SUCCESS'
                 End
                 else
                 Begin
                     set @ReturnValue = 'LOGIN_FAILURE'
              End

                
               End


         if(@Operation = 'GET_CYCLE_START_STATUS')
         Begin
              set @ScannedStationIndex = (select  dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
              if(@ScannedStationIndex = -1)
              Begin
                     if((select isnull(IsCycleStarted, 0) from Assy_Scan_OK(nolock) 
                     where LineCode = @LineCode and MachineCode = @MachineCode and OperationCode = @OperationCode) = 1)
                     Begin
                       set @ReturnValue = 'Y'
                       return
                     End
                     else
                     Begin
                       set @ReturnValue = 'N'
                     End
              ENd
              else
           Begin
                set @ReturnValue = 'N'
              End

         End

           if(@Operation = 'GET_ACTIVE_BARCODE_WHILE_CYCLE_START')
         Begin
           set @ScannedStationIndex = (select  dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
              --if it is a single jig station
              if(@ScannedStationIndex = -1)
              Begin
                 select top 1 Barcode from Assy_Scan_OK where LineCode = @LineCode and OperationCode = @OperationCode
              End
              else
              Begin
                if(@ScannedStationIndex = 1)
                  set @InsideStationIndex = 1
                else if(@ScannedStationIndex = 2)
              set @InsideStationIndex = 2
                select top 1 Barcode from Assy_Scan_OK where LineCode = @LineCode and OperationCode = @OperationCode 
                and StationCode = @InsideStationIndex
              End
         End

         if(@Operation = 'GET_ACTIVE_BARCODE_WHILE_PASS')
         Begin
           set @ScannedStationIndex = (select  dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
              --if it is a single jig station
              if(@ScannedStationIndex = -1)
              Begin
                 select top 1 Barcode from Assy_Scan_OK(nolock) where LineCode = @LineCode and OperationCode = @OperationCode
              End
              else
              Begin
                if(@ScannedStationIndex = 1)
                  set @InsideStationIndex = 2
                else if(@ScannedStationIndex = 2)
                set @InsideStationIndex = 1
                select top 1 Barcode from Assy_Scan_OK (nolock) where LineCode = @LineCode and OperationCode = @OperationCode 
                and StationCode = @InsideStationIndex
              End
         End

       if(@Operation = 'LOG_PLC_DATA')
         Begin
          declare @IsLogRequired bit = 0
          select @IsLogRequired = Is_PlcLogsRequired from RoutingConfigLineWise (nolock) where LineCode = @LineCode and ProfitCenterCode = @ProfitCode
          and OperationCode = @OperationCode
          if(@IsLogRequired = 1)
          Begin
                     insert into Assy_PLCLogs (ProfitCenterCode, LineCode, MachineCode, OperationCode, TagName, TagValue, Ent_Dt, Barcode)
                     values (@ProfitCode, @LineCode, @MachineCode, @OperationCode, @TagName, @TagValue, Getdate(), @Barcode)
          End
         End
         If(@Operation ='GET_PLC_ROUTING')
              BEGIN

              
					select distinct  a.Operationcode, a.machinecode, b.OperationName,
					 c.OperationSeqNo,td.TD_TABLE_NAME,ISNULL(c.IsTextLogRequired,0) AS IsTextLogRequired, 
					 td.isEngraveReq,td.isValidationReq,td.isLabelPrintReq,c.Torque as 'isTorqueReq',
					 ISNULL(td.KeepwareConnection,'') as 'KeepwareConnectionString',
					 ISNULL(td.ChannelName,'') as 'ChannnelName',
					 ISNULL(td.DeviceName,'') as 'DeviceName',
					 ISNULL(td.OPC_Required,0) as 'OPC_Required',
					 ISNULL(td.OPC_Required_Exception,0) as 'OPC_Required_Exception',
					 ISNULL(td.WriteBarcodeOverTag,0) as 'WriteBarcodeOverTag',
					 ISNULL(td.WriteOPCTags,0) as 'WriteOPCTags',
					 ISNULL(c.Recipe,0) as 'Recipe',
					 ISNULL(td.Is100AckRequired,1) as 'Is100AckRequired',				 
					 ISNULL(td.IsbarcodeCheck,0) as 'IsBarcodeCheck'			 
					 into #TEMP_LINE_DETAILS
					FROM MachineTagMapping(nolock) as a inner join OperationMst(nolock) as b
					on a.OperationCode = b.OperationCode 
					and a.ProfitCenterCode = b.ProfitCenterCode
					INNER JOIN RoutingConfigLineWise(nolock) as c on a.OperationCode = c.OperationCode
					INNER JOIN ASSY_TD_OPERATION_TABLE_MAPPING(nolock) td on a.OperationCode= td.OperationCode 
					where 
					c.linecode = @LineCode AND a.PROFITCENTERCODE = @ProfitCode --and c.OperationRequired = 1
					and a.linecode = @LineCode AND a.PROFITCENTERCODE = @ProfitCode 
					and td.linecode = @LineCode AND td.PROFITCENTERCODE = @ProfitCode 


					insert into #TEMP_LINE_DETAILS
					select distinct  a.Operationcode, a.machinecode,'Barcode Generation',
					a.OperationSeqNo,td.TD_TABLE_NAME,ISNULL(a.IsTextLogRequired,0) AS IsTextLogRequired,
					td.isEngraveReq,td.isValidationReq,td.isLabelPrintReq,a.Torque as 'isTorqueReq',
					ISNULL(td.KeepwareConnection,'') as 'KeepwareConnectionString',
					 ISNULL(td.ChannelName,'') as 'ChannnelName',
					 ISNULL(td.DeviceName,'') as 'DeviceName',
					 ISNULL(td.OPC_Required,0) as 'OPC_Required',
					 ISNULL(td.OPC_Required_Exception,0) as 'OPC_Required_Exception',
					 ISNULL(td.WriteBarcodeOverTag,0) as 'WriteBarcodeOverTag',
					 ISNULL(td.WriteOPCTags,0) as 'WriteOPCTags',
					 ISNULL(a.Recipe,0) as 'Recipe',
					 ISNULL(td.Is100AckRequired,1) as 'Is100AckRequired',
					 ISNULL(td.IsbarcodeCheck,0) as 'IsBarcodeCheck'	
					from RoutingConfigLineWise(nolock) a 
					inner join ASSY_TD_OPERATION_TABLE_MAPPING(nolock) 
					td on a.OperationCode= td.OperationCode 
					where 	a.linecode = @LineCode 
					AND a.PROFITCENTERCODE = @ProfitCode --and a.OperationRequired = 1	
					and a.OperationCode='OCIG'
					and a.OperationSeqNo=1 and td.linecode = @LineCode AND td.PROFITCENTERCODE = @ProfitCode 
				     
					 SELECT Operationcode,machinecode,OperationName,OperationSeqNo,TD_TABLE_NAME,IsTextLogRequired,
					 isEngraveReq,isValidationReq,isLabelPrintReq,isTorqueReq,KeepwareConnectionString,ChannnelName,
					 DeviceName,OPC_Required,OPC_Required_Exception,WriteBarcodeOverTag,WriteOPCTags,Recipe,Is100AckRequired,IsBarcodeCheck
					 FROM #TEMP_LINE_DETAILS ORDER BY OPERATIONSEQNO
					 		
					 select ISNULL(ProfitCenterCode,'') as ProfitCenterCode,
					 ISNULL(LineCode,'') as LineCode,
					 ISNULL(MachineCode,'') as MachineCode,
					 ISNULL(OperationCode,'') as OperationCode,
					 ISNULL(TagName,'') as TagName,
					 ISNULL(TagType,'') as TagType,
					 ISNULL(ReadEvent,0) as ReadEvent,
					 ISNULL(TagAddress,'') as TagAddress,
					 ISNULL(IsLogWriteEventInHTMLFile,0) as IsLogWriteEventInHTMLFile  
					 from MachineTagDecisionMapping(nolock) where linecode = @LineCode 
					 and PROFITCENTERCODE = @ProfitCode

					 select 
					 ISNULL(ProfitCenterCode,'') as ProfitCenterCode  ,
					 ISNULL(LineCode,'') as LineCode,
					 ISNULL(MachineCode,'') as MachineCode,
					 ISNULL(OperationCode,'') as OperationCode,
					 ISNULL(ChannelName,'') as ChannelName,
					 ISNULL(DeviceName,'') as DeviceName,
					 ISNULL(TagName,'') as TagName,
					 ISNULL(TagType,'') as TagType 					 
					 from MachineTagDecisionMappingException(nolock)
					 where linecode = @LineCode  and PROFITCENTERCODE = @ProfitCode
					 -- Added BY Sachin 20180810 -- To Log Data.
					select 
					ISNULL(dl.MachineCode,'') as MachineCode,	
					ISNULL(dl.OperationCode,'')  as OperationCode,
					ISNULL(dl.DataLogTagName,'')  as DataLogTagName,	
					ISNULL(dl.DataLogTagAddress,'')  as DataLogTagAddress,
					ISNULL(dl.DataLogOnValue,'')  as DataLogOnValue,
					ISNULL(dt.TagName,'')  as TagName,	
					ISNULL(dt.TagAddress,'')  as TagAddress,	
					ISNULL(dt.LogTableName,'')  as LogTableName,	
					ISNULL(dt.LogTagValueInColumn,'')  as LogTagValueInColumn,	
					ISNULL(dt.LogTagTimestampInColumn,'')  as LogTagTimestampInColumn 
					from	DataLoggerDetails(nolock) dl 
					inner join  DataLoggerTagDetails(nolock) dt
					on dl.DataLoggerTagDetailsSetId = dt. TagLogSetId
					where dl.sts_cd=0 and dt.sts_cd=0 and  
					dl.linecode = @LineCode  and dl.ProfitCenterCode = @ProfitCode

                     SET @ReturnValue='Routing Configuration exists'
                     SET @ReturnInt=1
       END
           If(@Operation ='GET_RUNNING_PART')
              BEGIN

                  IF EXISTS
                     (
                        SELECT TOP 1 1 FROM Assy_LineAssyStatus_Running where ProfitCenterCode = @ProfitCode and LineCode = @LineCode
                        and OperationCode = @OperationCode and IsPendingPart = 1
                     )
 Begin
                       select top 1 @Part_No =  isnull(PartNo, '') from Assy_LineAssyStatus_Running where ProfitCenterCode = @ProfitCode and LineCode = @LineCode
                        and OperationCode = @OperationCode and IsPendingPart = 1
                     End
                     else
                     Begin
                           select @Part_No = isnull(Assy_PartNo, '')  from assy_runningpart (nolock) where LineCode = @LineCode
            end
                  set @ReturnValue=@Part_No
                  SELECT @Part_No AS Assy_PartNo
                     
       END

              IF(@Operation = 'IS_BYPASS_ENABLED')
              Begin
              select @OpRequired = isnull(OperationRequired, 0), @TraceabilityRequired = isnull(Traceability, 0) from
                RoutingConfigLineWise(nolock) where MachineCode = @MachineCode and OperationCode = @OperationCode and ProfitCenterCode = @ProfitCode
                and LineCode = @LineCode

                if((@OpRequired = 1) and (@TraceabilityRequired = 1))
                Begin
                  set @ReturnValue = 'N'
                End
                else
                Begin
        set @ReturnValue = 'Y'
                End
              End

              IF(@Operation = 'SAVE_INCORRECT_DUPLICATE_HISTORY')
              Begin
                print 'HI'
                --insert into Assy_DuplicateIncorrectHistory(DateCode, ProfitCenterCode, LineCode, MachineCode, OperationCode, Barcode, IsDuplicate, IsIncorrect, Ent_Dt)
                --values(@DateCode, @ProfitCode, @LineCode, @MachineCode, @OperationCode, @Barcode, @IsDuplicate, @IsIncorrect, GETDATE())
              End
              IF(@Operation = 'GET_SCAN_OK_AND_BARCODE')
              Begin
              
                   
                     set @ScannedStationIndex = (select  dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
                     if(@ScannedStationIndex = -1)
                           select Barcode, isScan from Assy_Scan_OK
						   where LineCode = @LineCode and OperationCode = @OperationCode
                     else
                     Begin
                       select Barcode, isScan from Assy_Scan_OK 
					   where LineCode = @LineCode and OperationCode = @OperationCode 
                       and StationCode = @ScannedStationIndex
                     End
                     
              End
              
              IF(@Operation = 'IS_INCORRECT_LABEL_SCANNED')
              Begin
                select Barcode, isIncorrect, HMIMessageCode from Assy_incorrectLabel  
				where LineCode = @LineCode and OperationCode = @OperationCode
              End

              IF(@Operation = 'GET_HMI_MESSAGE_CODES')
              Begin
                select WIPMessage, MessageCode from assy_WIPMessageMst(nolock) where LineCode = @LineCode and ProfitCenterCode = @ProfitCode
              End

              IF(@Operation = 'IS_DUPLICATE_LABEL_SCANNED')
              Begin
                select Barcode, isDuplicate from Assy_DuplicateLabel 
				where LineCode = @LineCode and OperationCode = @OperationCode
              End

              IF(@Operation = 'RESET_SCANOK_DUPLICATE_INCORRECT_FIELDS')
              Begin
                 
                 update Assy_Scan_OK set isScan = 0, IsCycleStarted = 0 where LineCode = @LineCode and OperationCode = @OperationCode
                 update Assy_incorrectLabel set isIncorrect = 0 where LineCode = @LineCode and OperationCode = @OperationCode
                 update Assy_DuplicateLabel set isDuplicate = 0 where LineCode = @LineCode and OperationCode = @OperationCode

                 set @ScannedStationIndex = (select  dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
                     if(@ScannedStationIndex = -1)
                           update Assy_Stations_Zig_In_Out_Status set StatusInOut = 0 where LineCode = @LineCode and OperationCode = @OperationCode
              End

              IF(@Operation = 'UPDATE_ZIG_STATUS')
              Begin
                  
                     set @ScannedStationIndex = (select  dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
                     --if these are not twin zig stations..
                     if(@ScannedStationIndex = -1)
                     Begin
                           set @StationCode = '1'  
                           if not exists
                           (
                                  select top 1 1 from Assy_Stations_Zig_In_Out_Status(nolock) where  LineCode = @LineCode and OperationCode = @OperationCode
                           )
                           Begin
                                  insert into Assy_Stations_Zig_In_Out_Status (LineCode, OperationCode, StationCode, StatusInOut)
                                  values (@LineCode, @OperationCode, @StationCode, @ZigStatus)
                           End 
                           else
                           Begin
                                  update Assy_Stations_Zig_In_Out_Status set StatusInOut = @ZigStatus, StationCode = @StationCode where LineCode = @LineCode and OperationCode = @OperationCode
                           end 
                     End

                     else
                     Begin
                     if not exists
                           (
                              select top 1 1 from Assy_Stations_Zig_In_Out_Status (nolock) where LineCode = @LineCode and OperationCode = @OperationCode
                           )
                           Begin
                             insert into Assy_Stations_Zig_In_Out_Status (LineCode, OperationCode, StationCode, StatusInOut) values
                             (@LineCode, @OperationCode, @StationCode, @ZigStatus)
                             return
                           End

                           else
                           Begin
                             update Assy_Stations_Zig_In_Out_Status set StatusInOut = 1, StationCode = @StationCode where LineCode = @LineCode
                             and OperationCode = @OperationCode 
                           End
                     End
              End           

              if(@Operation = 'UPDATE_CYCLE_START')
              Begin
                     set @ScannedStationIndex = (select  dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
                     if(@ScannedStationIndex = -1)
                     Begin
                           update Assy_Scan_OK set IsCycleStarted = @IsCycleStarted where Barcode = @Barcode and LineCode = @LineCode 
                  and OperationCode = @OperationCode and MachineCode = @MachineCode
                              
                              --Changed by Ravi on 01-02-2016 for Poka Yoke
                                  If @IsCycleStarted = 1
                                  begin                                           
                      exec ASSY_PROC_UPDATEPOKAYOKESTATUS @CONDITION='UPDATE_CYCLE_STARTED_FROM_PLC_PROC', @LINECODE=@LineCode,
                                         @MACHINECODE=@MachineCode, @OPERATIONCODE=@OperationCode, @BARCODE=@Barcode
                                  end
                                  else if(@IsCycleStarted = 0)
                                  Begin
                                         if(@ScannedStationIndex = -1)
                                         Begin
                                                update Assy_Scan_OK set Barcode = '' where  LineCode = @LineCode and OperationCode = @OperationCode 
                                                and Barcode = @Barcode     
                                         End
                                  End
                     End
                     
              End   
       
         IF(@Operation = 'INSERT_PLC_PARAMS')
              Begin         
                     

                      select * into #temp from @tblparameters
					  
					  -- Added By Sachin 2018-02-13 Temp. Save Data Given By Machine.
					  insert into Assy_Save_MachineData_TEMP(
					  ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,
					  TagName,Value,Result,Datecode,UserID,Ent_Stamp
					  )
					  select ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,
					  TagName,Value,Result,Datecode,UserID,getdate() from #temp
					  -- Ended By Sachin 2018-02-13					  

                     declare @result varchar(10) 
                     select distinct @result = Result, @LineCode = LineCode, @OperationCode = Operationcode,
                     @MachineCode = MachineCode, @Barcode = Barcode, @ProfitCode = ProfitCenterCode from #temp

                     set @ScannedStationIndex = (select  dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))

                     if(@ScannedStationIndex <> -1)
                     Begin
                       if(@ScannedStationIndex = 1)
                         set @InsideStationIndex = 2
                       else if(@ScannedStationIndex = 2)
                         set @InsideStationIndex = 1
                       set @Barcode = (select top 1 Barcode from Assy_Scan_OK (nolock) where LineCode = @LineCode 
                       and OperationCode = @OperationCode
                        and StationCode = @InsideStationIndex)
                     End                  
                     IF ISNULL(@BARCODE,'')=''
                        begin
                         --drop table #temp
                           RETURN        
                           end
						   -- Commented By Sachin 20170601
            --Added by Manoj on 17/05/2016 to take care of 4 station rotary..
                     --if(@OperationCode = 'OC4S')
                     --Begin
                     --   --since data will come from temp table delete the data from temporary table
                     --   delete from #temp
                     --   --Since this is four substation assembly previous subassembly result can be pass whereas next subassembly could be fail
                     --   update Assy_LineAssyParamData_Running_Temp set Result = @result where Barcode = @Barcode

                     --   insert into #temp (ProfitCenterCode, LineCode, MachineCode, OperationCode,
                     --   StationCode, Barcode, TagName, Value, Result, DateCode, UserID)
                     --   select ProfitCenterCode, LineCode, MachineCode, OperationCode,
                     --   StationCode, Barcode, TagName, Value, Result, DateCode, UserID
                     --   from Assy_LineAssyParamData_Running_Temp where Barcode = @Barcode

                     --   delete from Assy_LineAssyParamData_Running_Temp where Barcode = @Barcode
                     --End
					 -- END Commented By Sachin 20170601

                     --Servo performance should return from here.. Another application will read the data from excel sheet and declare the result.
                   if(@OperationCode = 'OCSVPR')
                     Begin
                        
                              if not exists
                              (
                                    select top 1 1 from assy_PLC_PerformanceResult where Barcode = @Barcode
                              )
                              Begin
                        insert into assy_PLC_PerformanceResult(Barcode, Result, Ent_Dt) values (@Barcode, @result, GETDATE())
                              End
                        
                              update Assy_LineAssyStatus_Running set Status = 'PE' where Barcode = @Barcode and OperationCode = @OperationCode and LineCode = @LineCode
                       
                              Return
                End

                     --Added by Manoj on 19-06-2016 to include torque data
                       select @IsTorqueRequired = Torque from RoutingConfigLineWise (nolock) where LineCode = @LineCode and OperationCode = @OperationCode and ProfitCenterCode = @ProfitCode
                       if(@IsTorqueRequired = 1)
                       Begin
                          

                           insert into #temp (ProfitCenterCode, LineCode, MachineCode, OperationCode, Barcode, TagName, Value, Result, Datecode, UserID)
                           select ProfitCenterCode, LineCode, MachineCode, OperationCode, Barcode, TagName, TagValue, @result, '', @UserId  from assy_TorqueDetails
                             where Barcode = @Barcode and OperationCode = @OperationCode and LineCode = @LineCode and ProfitCenterCode = @ProfitCode

                           delete from assy_TorqueDetails where Barcode = @Barcode and OperationCode = @OperationCode and LineCode = @LineCode and ProfitCenterCode = @ProfitCode
                       End


                       --delete duplicate entries from #temp
                       alter table #temp add sno int identity(1,1)
                 delete from #temp where sno in
                           (
                           select sno from (
                           select *,
                           RANK() OVER ( PARTITION BY Barcode, TagName,Value ORDER BY sno DESC )rank
                           From #temp
                           )T
                           where rank>1
                           )

                           alter table #temp drop column sno

                     --End
					--Added By Rashid On 20170816 to include ScanTimeStamp
					DECLARE @UID AS uniqueidentifier, @ScanTimeStamp DateTime
					SET @UID = NEWID()
					/* Commented By RS On 20170724
					INSERT INTO Assy_LineAssyParamData_Running(ProfitCentercode, LineCode, MachineCode, OperationCode, StationCode, Barcode, Result, Datecode, UserID, Timestamp,					PartNo, UID)
					SELECT Top 1 ProfitCentercode, LineCode, MachineCode, OperationCode, @StationCode, @Barcode, @Result, @DateCode, @UserID, GETDATE(), @Part_No, @UID
					FROM @tblparameters WHERE ISNULL(Value, '') <> ''
			 
					INSERT INTO Assy_LineAssyParamData_Running_Dtl(UID, TagId, Value)
					SELECT @UID, B.TagId, ISNULL(A.Value, 0) Value FROM @tblparameters A INNER JOIN TagMst B WITH (NOLOCK) ON A.TagName = B.TagName WHERE ISNULL(Value, '') <> ''
						*/
					

					-- Added By Sachin 20190603
					 select top 1 @CaliperDatecode=value from  #temp where  tagname in ('DATE_CODE_COUPLING','DCODE')
					select top 1  @CaliperSrNo=convert(smallint,value) from #temp where  tagname in ('CALIPER_SERIAL_NO','DC_SERIAL_NO')
					-- Ended By Sachin 20190603
						--Added By Rashid On 20170816 to include ScanTimeStamp
					SELECT Top 1 @ScanTimeStamp = ScanTimeStamp,@DateCode=Datecode FROM Assy_LineAssyStatus_Running (NOLOCK) 
					WHERE ProfitCentercode = @ProfitCode
					AND LineCode = @LineCode AND MachineCode = @MachineCode AND OperationCode = @OperationCode AND Barcode = @Barcode
					
					INSERT INTO Assy_LineAssyParamData_Running(ProfitCentercode, LineCode, MachineCode, OperationCode, StationCode, Barcode, 
					Result, Datecode, UserID, Timestamp, PartNo, UID, ScanTimeStamp,CaliperDatecode,CaliperSrNo,Live_Datecode)
					SELECT Top 1 ProfitCentercode, LineCode, MachineCode, OperationCode, @StationCode, @Barcode, @Result, @DateCode, 
					@UserID, GETDATE(), @Part_No, @UID, @ScanTimeStamp,ISNULL(@CaliperDatecode,''),ISNULL(@CaliperSrNo,0),@Live_Datecode
					FROM #temp WHERE ISNULL(Value, '') <> ''

					--ADDED BY RS ON 10-01-2019 [START]
					DECLARE @IsLotBasedAssembly varchar(10);
					
					SELECT TOP 1 @IsLotBasedAssembly = PARAMETER_VALUE FROM dbo.PARAMETER_MST (NOLOCK) 
						WHERE PARAMETER_C = 'ASSEMBLY' AND PARAMETER_C1 = 'LotBasedOrPartBased' AND PARAMETER_NM = 'ASSEMBLY_TRACEBILITY' 
							AND wh_code = @PROFITCODE AND PARAMETER_C2 = @LINECODE
                    
					IF(@result = 'PS' or @result = 'FL' )
					BEGIN
						IF @IsLotBasedAssembly = '1'
						BEGIN
							DECLARE @NoOfTorqueStation varchar(1) = '', @Torque_Angle varchar(50) = '', @Torque_Value varchar(50) = '', @AutoID bigint, @Ent_dt datetime = NULL,
									 @Torque_Max varchar(50) = '', @Torque_Min varchar(50) = '', @IsOk BIT = 0, @SetParamTimeStamp DateTime = NULL
							SELECT @NoOfTorqueStation = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND KeyType = 'NoOfTorqueStation'

							SELECT @SetParamTimeStamp = CreatedDate FROM Assy_RunningPart (NOLOCK)  WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode

							IF (ISNULL(@NoOfTorqueStation,'') = '1')
							BEGIN
								IF ISNULL(@SetParamTimeStamp,'') != ''
								BEGIN
									INSERT INTO [TD_Result_MCTQLH_Log](ProfitCenterCode,LineCode,OperationCode,Barcode,AutoID,Ent_dt,Torque_Angle,Torque_Max,Torque_Min,Torque_Value,Upd_dt,Upd_User,IsOk)
									SELECT @ProfitCode,@LineCode,@OperationCode,GETDATE(),AutoID,Ent_dt,Torque_Angle,Torque_Max,Torque_Min,Torque_Value,GETDATE(),@UserId,IsOk FROM [TD_Result_MCTQLH]
										WHERE Ent_dt < @SetParamTimeStamp

									DELETE FROM [TD_Result_MCTQLH] WHERE Ent_dt < @SetParamTimeStamp
								END

								-- FIFO Basis First Row Fetch
								SELECT Top 1 @AutoID = AutoID, @Torque_Angle = Torque_Angle, @Torque_Value = Torque_Value, @Ent_dt = Ent_dt, @Torque_Max = Torque_Max, @Torque_Min = Torque_Min,
									@IsOk = IsOk
										FROM [TD_Result_MCTQLH] (NOLOCK)

								IF @AutoID > 0
								BEGIN
									INSERT INTO #temp (ProfitCenterCode, LineCode, MachineCode, OperationCode, Barcode, TagName, Value, Result, Datecode, UserID)
									SELECT @ProfitCode, @LineCode, @MachineCode, @OperationCode, @Barcode, 'Torque_Angle', @Torque_Angle, @result, @DateCode, @UserId
									UNION ALL
									SELECT @ProfitCode, @LineCode, @MachineCode, @OperationCode, @Barcode, 'Torque_Value', @Torque_Value, @result, @DateCode, @UserId

									INSERT INTO [TD_Result_MCTQLH_Log](ProfitCenterCode,LineCode,OperationCode,Barcode,AutoID,Ent_dt,Torque_Angle,Torque_Max,Torque_Min,Torque_Value,Upd_dt,Upd_User,IsOk)
									SELECT @ProfitCode, @LineCode, @OperationCode, @Barcode, @AutoID, @Ent_dt, @Torque_Angle, @Torque_Max, @Torque_Min, @Torque_Value, GETDATE(), @UserId,@IsOk

									DELETE FROM [TD_Result_MCTQLH] WHERE AutoID = @AutoID
								END
								ELSE
								BEGIN
									INSERT INTO #temp (ProfitCenterCode, LineCode, MachineCode, OperationCode, Barcode, TagName, Value, Result, Datecode, UserID)
									SELECT @ProfitCode, @LineCode, @MachineCode, @OperationCode, @Barcode, 'Torque_Angle', ISNULL(@Torque_Angle,'0'), @result, @DateCode, @UserId
									UNION ALL
									SELECT @ProfitCode, @LineCode, @MachineCode, @OperationCode, @Barcode, 'Torque_Value', ISNULL(@Torque_Value,'0'), @result, @DateCode, @UserId
								END
							END
							ELSE IF ISNULL(@NoOfTorqueStation,'') = '2'
							BEGIN
								IF @OperationCode = 'OCLTLH'
								BEGIN
									IF ISNULL(@SetParamTimeStamp,'') != ''
									BEGIN
										INSERT INTO [TD_Result_MCTQLH_Log](ProfitCenterCode,LineCode,OperationCode,Barcode,AutoID,Ent_dt,Torque_Angle,Torque_Max,Torque_Min,Torque_Value,Upd_dt,Upd_User,IsOk)
										SELECT @ProfitCode,@LineCode,@OperationCode,GETDATE(),AutoID,Ent_dt,Torque_Angle,Torque_Max,Torque_Min,Torque_Value,GETDATE(),@UserId,IsOk FROM [TD_Result_MCTQLH]
											WHERE Ent_dt < @SetParamTimeStamp

										DELETE FROM [TD_Result_MCTQLH] WHERE Ent_dt < @SetParamTimeStamp
									END
									-- FIFO Basis First Row Fetch
									SELECT Top 1 @AutoID = AutoID, @Torque_Angle = Torque_Angle, @Torque_Value = Torque_Value, @Ent_dt = Ent_dt, @Torque_Max = Torque_Max, @Torque_Min = Torque_Min,
										@IsOk = IsOk
											FROM [TD_Result_MCTQLH] (NOLOCK)

									IF @AutoID > 0
									BEGIN
										INSERT INTO #temp (ProfitCenterCode, LineCode, MachineCode, OperationCode, Barcode, TagName, Value, Result, Datecode, UserID)
										SELECT @ProfitCode, @LineCode, @MachineCode, @OperationCode, @Barcode, 'Torque_Angle', @Torque_Angle, @result, @DateCode, @UserId
										UNION ALL
										SELECT @ProfitCode, @LineCode, @MachineCode, @OperationCode, @Barcode, 'Torque_Value', @Torque_Value, @result, @DateCode, @UserId

										INSERT INTO [TD_Result_MCTQLH_Log](ProfitCenterCode,LineCode,OperationCode,Barcode,AutoID,Ent_dt,Torque_Angle,Torque_Max,Torque_Min,Torque_Value,Upd_dt,Upd_User,IsOk)
										SELECT @ProfitCode, @LineCode, @OperationCode, @Barcode, @AutoID, @Ent_dt, @Torque_Angle, @Torque_Max, @Torque_Min, @Torque_Value, GETDATE(), @UserId,@IsOk

										DELETE FROM [TD_Result_MCTQLH] WHERE AutoID = @AutoID
									END
									ELSE
									BEGIN
										INSERT INTO #temp (ProfitCenterCode, LineCode, MachineCode, OperationCode, Barcode, TagName, Value, Result, Datecode, UserID)
										SELECT @ProfitCode, @LineCode, @MachineCode, @OperationCode, @Barcode, 'Torque_Angle', ISNULL(@Torque_Angle,'0'), @result, @DateCode, @UserId
										UNION ALL
										SELECT @ProfitCode, @LineCode, @MachineCode, @OperationCode, @Barcode, 'Torque_Value', ISNULL(@Torque_Value,'0'), @result, @DateCode, @UserId
									END
								END
								ELSE IF @OperationCode = 'OCLTRH'
								BEGIN
									IF ISNULL(@SetParamTimeStamp,'') != ''
									BEGIN
										INSERT INTO [TD_Result_MCTQRH_Log](ProfitCenterCode,LineCode,OperationCode,Barcode,AutoID,Ent_dt,Torque_Angle,Torque_Max,Torque_Min,Torque_Value,Upd_dt,Upd_User,IsOk)
										SELECT @ProfitCode,@LineCode,@OperationCode,GETDATE(),AutoID,Ent_dt,Torque_Angle,Torque_Max,Torque_Min,Torque_Value,GETDATE(),@UserId,IsOk FROM [TD_Result_MCTQRH]
											WHERE Ent_dt < @SetParamTimeStamp

										DELETE FROM [TD_Result_MCTQRH] WHERE Ent_dt < @SetParamTimeStamp
									END
									-- FIFO Basis First Row Fetch
									SELECT Top 1 @AutoID = AutoID, @Torque_Angle = Torque_Angle, @Torque_Value = Torque_Value, @Ent_dt = Ent_dt, @Torque_Max = Torque_Max, @Torque_Min = Torque_Min,
										@IsOk = IsOk
											FROM [TD_Result_MCTQRH] (NOLOCK)

									IF @AutoID > 0
									BEGIN
										INSERT INTO #temp (ProfitCenterCode, LineCode, MachineCode, OperationCode, Barcode, TagName, Value, Result, Datecode, UserID)
										SELECT @ProfitCode, @LineCode, @MachineCode, @OperationCode, @Barcode, 'Torque_Angle', @Torque_Angle, @result, @DateCode, @UserId
										UNION ALL
										SELECT @ProfitCode, @LineCode, @MachineCode, @OperationCode, @Barcode, 'Torque_Value', @Torque_Value, @result, @DateCode, @UserId

										INSERT INTO [TD_Result_MCTQRH_Log](ProfitCenterCode,LineCode,OperationCode,Barcode,AutoID,Ent_dt,Torque_Angle,Torque_Max,Torque_Min,Torque_Value,Upd_dt,Upd_User)
										SELECT @ProfitCode, @LineCode, @OperationCode, @Barcode, @AutoID, @Ent_dt, @Torque_Angle, @Torque_Max, @Torque_Min, @Torque_Value, GETDATE(), @UserId

										DELETE FROM [TD_Result_MCTQRH] WHERE AutoID = @AutoID
									END
									ELSE
									BEGIN
										INSERT INTO #temp (ProfitCenterCode, LineCode, MachineCode, OperationCode, Barcode, TagName, Value, Result, Datecode, UserID)
										SELECT @ProfitCode, @LineCode, @MachineCode, @OperationCode, @Barcode, 'Torque_Angle', ISNULL(@Torque_Angle,'0'), @result, @DateCode, @UserId
										UNION ALL
										SELECT @ProfitCode, @LineCode, @MachineCode, @OperationCode, @Barcode, 'Torque_Value', ISNULL(@Torque_Value,'0'), @result, @DateCode, @UserId
									END
								END
							END
						END
					END
					--ADDED BY RS ON 10-01-2019 [END]
                      insert into Assy_LineAssyParamData_Running_Dtl(UID,TagId,Value)
                     SELECT distinct @UID,B.TagId,isnull(A.Value,0)Value     FROM #temp A inner join 
					 tagmst B with(nolock) on A.tagname=b.tagname where isnull(Value,'')<>''
                       
                       select @PokaYokeDateCode=dbo.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE','POKAYOKE','POKAYOKE_DATECODE',@ProfitCode)
                     --update Assy_LineAssyStatus_Running table..
                           if charindex(@PokaYokeDateCode,@Barcode)=0
                           BEGIN
                                     update assy_LineAssyStatus_Running set ResultTimeStamp = GETDATE(), STATUS = @result 
									 WHERE ProfitCenterCode = @ProfitCode
                                     and Linecode = @LineCode and MachineCode = @MachineCode and OperationCode = 
									 @OperationCode and Barcode = @Barcode and isnull(STATUS,'')<>'PS' 

 if not exists
                                         (
                                            select top 1 1 from Assy_Result(nolock) where LineCode = @LineCode and OperationCode = @OperationCode
                                         )
                                         Begin
                                              insert into Assy_Result(LineCode, OperationCode , StationCode, Barcode )
                                     select @LineCode, @OperationCode, @StationCode, @Barcode
                                         End
                                         else
                                                Begin
                                                       update assy_Result set Barcode = @Barcode where LineCode = @LineCode and OperationCode = @OperationCode
                                                End
                           END    
                     
                     drop table #temp                         
                    update assy_Scan_OK set Barcode = '' where LineCode = @LineCode and OperationCode = @OperationCode and Barcode = @Barcode
                     update a set a.Barcode = '' from @tblParameters t inner join Assy_incorrectLabel as a on a.LineCode = t.LineCode and a.OperationCode = t.OperationCode
                     update a set a.Barcode = '' from @tblParameters t inner join Assy_DuplicateLabel as a on a.LineCode = t.LineCode and a.OperationCode = t.OperationCode
                           
                     select distinct @result = Result, @LineCode = LineCode, @OperationCode = Operationcode,
                     @MachineCode = MachineCode, @Barcode = Barcode, @ProfitCode = ProfitCenterCode from @tblparameters

                     --declare @PokaYokeDateCode varchar(20);

                     IF CHARINDEX(@POKAYOKEDATECODE,@BARCODE)<>0
                           BEGIN
                                 DECLARE @PLCRESULT VARCHAR(10),@ISTESTCOMPLETED varchar(10)

                           SELECT @PLCRESULT = (SELECT CASE(@RESULT) WHEN 'PS' THEN 'PASS' ELSE 'FAIL' END)
                                  EXEC ASSY_PROC_UPDATEPOKAYOKESTATUS @CONDITION='UPDATE_POKA_YOKE_RESULT',@LINECODE=@LINECODE, @OPERATIONCODE=@OPERATIONCODE,
                                  @MACHINECODE=@MACHINECODE, @PROFITCENTERCODE=@PROFITCODE, @PLCRESULT= @PLCRESULT
                                  ,@BARCODE=@BARCODE,@USERID = @USERID,@ISTESTCOMPLETED=@ISTESTCOMPLETED  OUTPUT
                           
                                  IF @ISTESTCOMPLETED='NA' or @ISTESTCOMPLETED='YES'
                                    RETURN
                                                             
                                    IF NOT EXISTS
                                     (
                                            SELECT TOP 1 1 FROM ASSY_RESULT(NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
                                     )
                                         BEGIN
                                              INSERT INTO ASSY_RESULT(LINECODE, OPERATIONCODE , STATIONCODE, BARCODE )
                                              SELECT @LINECODE, @OPERATIONCODE, @STATIONCODE, @BARCODE
                                                  UPDATE Assy_Scan_OK_History_For_PokaYoke SET BARCODE='',ISCYCLESTARTED=0 
                                                  WHERE LINECODE=@LINECODE AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE
                                         END
                                         ELSE
                                                BEGIN
                                                       UPDATE ASSY_RESULT SET BARCODE = @BARCODE WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
                                                       UPDATE Assy_Scan_OK_History_For_PokaYoke SET BARCODE='',ISCYCLESTARTED=0 
                                      WHERE LINECODE=@LINECODE AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE     
                                                END
                                  RETURN
                           END                          
						
						--ADDED BY AP ON 13-08-2018 [START]
						--Declare @IsLotBasedAssembly VARCHAR(10);
						--SELECT TOP 1 @IsLotBasedAssembly = PARAMETER_VALUE FROM dbo.PARAMETER_MST (NOLOCK) 
						--WHERE PARAMETER_C = 'ASSEMBLY' AND PARAMETER_C1 = 'LotBasedOrPartBased' AND PARAMETER_NM = 'ASSEMBLY_TRACEBILITY' 
						--AND wh_code = @PROFITCODE AND PARAMETER_C2 = @LINECODE
						IF(@IsLotBasedAssembly  = '1')
						BEGIN
							DECLARE @temp TABLE
							(
								id Int identity(1,1),
								LINECODE NVARCHAR(100),
								COL2 NVARCHAR(100),
								OPERATIONSEQNO INT,
								PARTNO NVARCHAR(100),
								OPERATIONCODE NVARCHAR(100),
								STATIONCODE NVARCHAR(100)
							);

							INSERT INTO @temp
							EXEC Assy_PROC_FinalViewing @CONDITION = 'GET_ACTIVE_STATION', @LineCode = @LINECODE, @PROFITCENTERCODE = @PROFITCODE

							DECLARE @RetestCase INT = 0

							IF EXISTS(SELECT 1 FROM Assy_LineAssyStatus_Running (NOLOCK) WHERE ProfitCenterCode = @PROFITCODE AND LineCode = @LINECODE AND OperationCode = @OperationCode AND Barcode = @BARCODE AND isNULL(FailCount,0) > 0)
							BEGIN
								IF(@result = 'PS')
								BEGIN
									SET @RetestCase = 1
								END
								ELSE
									SET @RetestCase = 2
							END
							ELSE
							BEGIN
								IF(@result = 'FL')
								BEGIN
									SET @Assy_LotTrolleyDetailsId = 0
									SELECT @Assy_LotTrolleyDetailsId = id FROM dbo.Assy_LotTrolleyDetails WHERE ProfitCenterCode = @PROFITCODE AND LineCode = @LINECODE 
										AND StatusCode = 0 AND TrolleyType = 'INPUT'

									INSERT INTO Assy_LotinputTrolleyDetails (Assy_LotTrolleyDetailsId,Barcode,EntDt,EntUser)
									VALUES(@Assy_LotTrolleyDetailsId,@BARCODE,GETDATE(),@UserId)

									SET @Assy_LotTrolleyDetailsId = 0
									SELECT @Assy_LotTrolleyDetailsId = id FROM dbo.Assy_LotTrolleyDetails WHERE ProfitCenterCode = @PROFITCODE AND LineCode = @LINECODE 
										AND StatusCode = 0 AND TrolleyType = 'SUSPECTED'

									INSERT INTO Assy_LotSuspectedTrolleyDetails (Assy_LotTrolleyDetailsId,Barcode,EntDt,EntUser)
									VALUES(@Assy_LotTrolleyDetailsId,@BARCODE,GETDATE(),@UserId)

									UPDATE dbo.Assy_LotTrolleyDetails
									SET Capacity = (Capacity + 1),
									UpdDt = GETDATE(),
									UpdUser = @UserId
									WHERE ProfitCenterCode = @PROFITCODE AND LineCode = @LINECODE 
									AND StatusCode = 0 AND TrolleyType = 'SUSPECTED'
									--Added BY RS On 02-Jan-2019
									IF EXISTS
									(
										SELECT TOP 1 1 FROM dbo.Assy_LotTrolleyDetails(NOLOCK) WHERE Capacity = TrolletQty AND ProfitCenterCode = @PROFITCODE AND LineCode = @LINECODE
											AND StatusCode = 0 AND TrolleyType = 'SUSPECTED'
									)
									BEGIN
										UPDATE dbo.Assy_LotTrolleyDetails
										SET StatusCode = 1,
										UpdDt = GETDATE(),
										UpdUser = @UserId
										WHERE ProfitCenterCode = @PROFITCODE AND LineCode = @LINECODE AND StatusCode = 0 AND TrolleyType = 'SUSPECTED'
									END
								END
							END
							DECLARE @idSeq INT = 0, @RowCount INT = 0;
							SELECT @idSeq = OPERATIONSEQNO FROM @temp WHERE OPERATIONCODE = @OperationCode
							--Added BY RS On 02-Jan-2019 Input Trolley Case
							DELETE FROM @temp WHERE OPERATIONSEQNO >= @idSeq

							SELECT @RowCount = COUNT(*) FROM @temp

							IF @RowCount = 1
							BEGIN
								IF @RetestCase = 1
								BEGIN
									IF EXISTS (SELECT 1 FROM [Assy_LotReworkBarcode_Log] WHERE Barcode = @BARCODE AND OperationCode = @OperationCode AND ISNULL(IsRest,0) = 0)
									BEGIN
										UPDATE [Assy_LotReworkBarcode_Log] SET IsRest = 1, UpdDt = GETDATE(), UpdUser = @UserId
											WHERE Barcode = @BARCODE AND OperationCode = @OperationCode AND ISNULL(IsRest,0) = 0
										
										SELECT @Assy_LotTrolleyDetailsId = Assy_LotTrolleyDetailsId FROM Assy_LotSuspectedTrolleyDetails (NOLOCK) WHERE Barcode = @BARCODE

										UPDATE dbo.Assy_LotTrolleyDetails
										SET Capacity = (ISNULL(Capacity,0) - 1),
										UpdDt = GETDATE(),
										UpdUser = @UserId
										WHERE id = @Assy_LotTrolleyDetailsId AND StatusCode = 0

										DELETE FROM Assy_LotSuspectedTrolleyDetails WHERE Barcode = @BARCODE
										--DELETE FROM Assy_LotReworkBarcode WHERE Barcode = @BARCODE
									END
								END
								ELSE
								BEGIN
									IF EXISTS (SELECT 1 FROM @temp WHERE OPERATIONCODE = 'OCIG')
									BEGIN
										DECLARE @TrolleyId_New VARCHAR(100) = ''
										SELECT Top 1 @TrolleyId_New = TrolleyId FROM dbo.Assy_LotTrolleyDetails(NOLOCK) WHERE ProfitCenterCode = @PROFITCODE AND LineCode = @LINECODE
											AND StatusCode = 0 AND TrolleyType = 'INPUT' Order By ID

										IF ISNULL(@RetestCase,0) = 0
										BEGIN
											UPDATE dbo.Assy_LotTrolleyDetails
											SET Capacity = (Capacity - 1),
											UpdDt = GETDATE(),
											UpdUser = @UserId
											WHERE ProfitCenterCode = @PROFITCODE AND LineCode = @LINECODE 
											AND StatusCode = 0 AND TrolleyType = 'INPUT' AND TrolleyId = @TrolleyId_New
											--Added BY RS On 02-Jan-2019
											IF EXISTS
											(
												SELECT TOP 1 1 FROM dbo.Assy_LotTrolleyDetails(NOLOCK) WHERE Capacity = 0 AND ProfitCenterCode = @PROFITCODE AND LineCode = @LINECODE
													AND StatusCode = 0 AND TrolleyType = 'INPUT' AND TrolleyId = @TrolleyId_New
											)
											BEGIN
												UPDATE dbo.Assy_LotTrolleyDetails
												SET StatusCode = 1,
												UpdDt = GETDATE(),
												UpdUser = @UserId
												WHERE ProfitCenterCode = @PROFITCODE AND LineCode = @LINECODE AND StatusCode = 0 AND TrolleyType = 'INPUT' AND TrolleyId = @TrolleyId_New
											END
										END
									END
								END
							END
							--For Testing purpose only
							--INSERT into ABCD(result)
							--Values (@PROFITCODE  + '|' + @LINECODE  + '|' + @BARCODE  + '|' + @MACHINECODE  + '|' + @OperationCode  + '|')
							
						END
						--ADDED BY AP ON 13-08-2018 [END]
						if ((SELECT TOP 1 PARAMETER_VALUE FROM PARAMETER_MST WHERE PARAMETER_C='ASSLINE' AND PARAMETER_C1='COUPLING' AND PARAMETER_C2='MACHINECODE'
						AND WH_CODE=@ProfitCode)=@MACHINECODE)
						BEGIN
							if(@result = 'PS')
							Begin
								-- Added by Sachin 20180712
								-- Save Coupling Data if Component Pass.
								
								INSERT INTO Assy_CouplingDetails 
								(
								ProfitCentreCode , LineCode , STMC_PART_NO , 
								CHILD_PART_NO , PART_TYPE , MACHINE_CODE , OPERATION_CODE , TORQUE_1 , TORQUE_2 , ENT_DT , ENT_BY , CHILD_Barcode , FG_Barcode , DateCode
								)
								SELECT ProfitCentreCode , LineCode , STMC_PART_NO , 
								CHILD_PART_NO , PART_TYPE , MACHINE_CODE , OPERATION_CODE , TORQUE_1 , TORQUE_2 , ENT_DT , ENT_BY , CHILD_Barcode , @BARCODE , @DateCode 
								FROM Assy_Coupling_Temp WITH (NOLOCK)
								WHERE ProfitCentreCode = @ProfitCode AND LineCode = @LineCode AND MACHINE_CODE=@MACHINECODE
								-- Ended by Sachin 20180712
							end
							 --DELETE the record FROM temp table..
							 DELETE FROM Assy_Coupling_Temp WHERE ProfitCentreCode = @ProfitCode AND LineCode = @LineCode AND MACHINE_CODE=@MACHINECODE
						END

						if(@result = 'PS')
						Begin                      
								
								  EXEC ASSY_PROC_WIP_MANAGE  @CONDITION='UPDATE_WIP_COUNT', 
								  @LINECODE=@LINECODE,@MACHINECODE=@MACHINECODE,@BARCODE=@BARCODE,
								  @PROFITCENTERCODE=@PROFITCODE, @RESULT = @RESULT                           
                                  if exists
                                  (
                                            select 1 from linemst with(nolock) where ProfitCenterCode = @PROFITCODE and LineCode = @LINECODE and isnull(isActive,0)=1 and  isnull(Allow2Parts,0)=1
                                  )
                                  begin
										 delete from Assy_PreviousPending_Parts  where ProfitCenterCode=@ProfitCode and LineCode =@LineCode 
					                     and MachineCode=@MachineCode and Barcode=@Barcode and   isnull(Is_Rejected,0)=0
                                  end

								  --Added By Sachin 20170830

								  select @FlagStatus=keyValue from RoutingConfigDetails(nolock) where ProfitCenterCode=@PROFITCODE and LineCode=@LINECODE 
								  and keyType='ContinuesFailCountReq' and STS_CD=0  

								  if(@FlagStatus=1)
								  begin
									     -- RESET IF PASS INBETWEEN
										 if exists(select top 1 1 from Assy_Continues_Fail_Count(nolock) where 
										 ProfitCenterCode=ISNULL(@PROFITCODE,'') and LineCode=ISNULL(@LINECODE,'') and OperationCode = ISNULL(@OperationCode,'')
										  and MachineCode=ISNULL(@MACHINECODE,''))
										 begin
										        delete from Assy_Continues_Fail_Count where ProfitCenterCode=ISNULL(@PROFITCODE,'') and LineCode=ISNULL(@LINECODE,'') 
												and OperationCode = ISNULL(@OperationCode,'') and MachineCode=ISNULL(@MACHINECODE,'')												
										 end										
								  end

								  --Ended By Sachin 20170830

								  --Start Added By Rashid On 20180205 For Final Viewing Insertion call automatically
								IF (ISNULL(@result,'') = 'PS')
								BEGIN
									Declare @IsAutoFVScanAndPassTrigger bit = 0

									SELECT @IsAutoFVScanAndPassTrigger = dbo.ASSY_FN_GET_PARAMETER_VALUE('AssLine','IsAutoFVInsertion',@LineCode,@ProfitCode)

									IF(@IsAutoFVScanAndPassTrigger = 1)
									BEGIN
										Declare @ASSY_PARTNO VARCHAR(20) = '', @Compare_OperationCode VARCHAR(20) = ''
										SELECT @ASSY_PARTNO = Assy_PartNo FROM ASSY_RUNNINGPART (NOLOCK) WHERE PROFITCENTERCODE = @ProfitCode AND LINECODE = @LineCode

										Create Table #OperationSeqWithOperationCode
										(
											OperationSeqNo INT NOT NULL,
											OperationCode VARCHAR(20) NOT NULL,
											PRIMARY KEY (OperationSeqNo,OperationCode)
										)

										INSERT INTO #OperationSeqWithOperationCode(OperationSeqNo,OperationCode)
										SELECT L.OPERATIONSEQNO, L.OPERATIONCODE FROM ROUTINGCONFIGLINEWISE (NOLOCK) L
										INNER JOIN ROUTINGCONFIGPARTWISE (NOLOCK) P
										ON L.OPERATIONCODE = P.OPERATIONCODE AND L.MACHINECODE = P.MACHINECODE
										WHERE L.PROFITCENTERCODE = @ProfitCode AND L.LINECODE = @LINECODE AND P.PARTNO = @ASSY_PARTNO
										AND L.TRACEABILITY = 1 AND P.TRACEABILITY = 1 AND L.OPERATIONREQUIRED = 1 AND P.OPERATIONREQUIRED = 1

										DELETE FROM #OperationSeqWithOperationCode WHERE OperationCode  = (SELECT dbo.Assy_FN_Get_FinalViewing_OperationCode_From_LineCode(@ProfitCode,@LINECODE))
				
										--SELECT Top 1 @Compare_OperationCode = OperationCode FROM #OperationSeqWithOperationCode Order By OperationSeqNo Desc
										Declare @TempOperationCode INT;
										SELECT Top 1 @TempOperationCode = OperationSeqNo FROM #OperationSeqWithOperationCode Order By OperationSeqNo Desc

										--Drop Table #OperationSeqWithOperationCode

										--IF ISNULL(@Compare_OperationCode,'') = @OperationCode
										IF EXISTS(SELECT TOP 1 1 FROM #OperationSeqWithOperationCode WHERE OperationCode = @OperationCode AND OperationSeqNo = @TempOperationCode)
										BEGIN
											INSERT INTO Assy_AutoFV_Trigger_Info(ProfitCenterCode,LineCode,MachineCode,OperationCode,Barcode,IsAutoFVTrigger)
											SELECT @ProfitCode,@LINECODE,@MACHINECODE,@OperationCode,@BARCODE,1
											UNION
											SELECT ProfitCenterCode,LineCode,MachineCode,OperationCode,Barcode,'1' FROM Assy_LineAssyStatus_running WITH(NOLOCK)
											WHERE Machinecode = @MACHINECODE AND Status = 'PS'
										END
										Drop Table #OperationSeqWithOperationCode
									END
								END
								--End Added By Rashid On 20180205 For Final Viewing Insertion call automatically

                                           
                     End
						else if(@result = 'FL')
						Begin  
                                                       
                                  update Assy_LineAssyStatus_Running set failcount = isnull(failcount,0)+1 
                                  where  ProfitCenterCode = @ProfitCode and LINECODE=@LINECODE and OperationCode = @OperationCode and  Barcode = @Barcode 
                                                                                                 
                                  EXEC ASSY_PROC_WIP_MANAGE  @CONDITION='UPDATE_WIP_COUNT', @LINECODE=@LINECODE,@MACHINECODE=@MACHINECODE,@BARCODE=@BARCODE,@PROFITCENTERCODE=@PROFITCODE, @RESULT = @RESULT

								  --Added By Sachin 20170830
								  
								  select @FlagStatus=keyValue from RoutingConfigDetails(nolock) where ProfitCenterCode=ISNULL(@PROFITCODE,'') and LineCode=ISNULL(@LINECODE,'') 
								  and keyType='ContinuesFailCountReq' and STS_CD=0  

								  if(@FlagStatus=1)
								  begin
											

									     if exists(select top 1 1 from Assy_Continues_Fail_Count(nolock) where 
										 ProfitCenterCode=ISNULL(@PROFITCODE,'') and LineCode=ISNULL(@LINECODE,'') 
										 and OperationCode = ISNULL(@OperationCode,'') 
										 and MachineCode=ISNULL(@MACHINECODE,''))
										 begin
										        update Assy_Continues_Fail_Count 
												set failCount = failCount + 1 , Timestamp=getdate()
												where ProfitCenterCode=ISNULL(@PROFITCODE,'') 
												and LineCode=ISNULL(@LINECODE,'') and 
												OperationCode = ISNULL(@OperationCode,'') and MachineCode=ISNULL(@MACHINECODE,'')
												
										 end
										 else
										 begin
												insert into Assy_Continues_Fail_Count (ProfitCenterCode,LineCode,MachineCode,OperationCode,
												FailCount,Timestamp,Reason)
												values(ISNULL(@PROFITCODE,''),ISNULL(@LINECODE,''),ISNULL(@MACHINECODE,''),ISNULL(@OperationCode,''),1,getdate(),'')
										 end
								  end

								  select @FlagStatus=keyValue from RoutingConfigDetails(nolock) where ProfitCenterCode=ISNULL(@PROFITCODE,'') and LineCode=ISNULL(@LINECODE,'') 
								  and keyType='HourlyFailCountReq' and STS_CD=0  

								  if(@FlagStatus=1)
								  begin
										
										if exists( select top 1 1 from Assy_Hourly_Fail_Count where profitCenterCode=ISNULL(@PROFITCODE,'') and LineCode=ISNULL(@LINECODE,'') 
										and MachineCode=ISNULL(@MACHINECODE,'') and OperationCode=ISNULL(@OperationCode,'') and GETDATE() between [FromTimestamp] and [ToTimestamp])
										begin
												
												update Assy_Hourly_Fail_Count 
												set FailCount=FailCount+1 , timestamp=getdate()
												where profitCenterCode=ISNULL(@PROFITCODE,'') and LineCode=ISNULL(@LINECODE,'') and MachineCode=ISNULL(@MACHINECODE,'') 
												and OperationCode=ISNULL(@OperationCode,'') and GETDATE() between [FromTimestamp] and [ToTimestamp]

										end
										else
										begin
										     delete from Assy_Hourly_Fail_Count
											 insert into Assy_Hourly_Fail_Count([ProfitCenterCode],[LineCode],[MachineCode],[OperationCode],[FromTimestamp],[ToTimestamp],FailCount,[Timestamp],Reason)
											 values(ISNULL(@PROFITCODE,''),ISNULL(@LINECODE,''),ISNULL(@MACHINECODE,''),ISNULL(@OperationCode,''),getdate(),DATEADD(hh,1,getdate()),1,getdate(),'')
										end

								  end
								  --Ended By Sachin 20170830
                     End 
					 
					 
					  -- Added By Sachin 2018-02-13
					  -- If all Data Saved Successfully Remove Saved data Temp. Machine data
					  delete from Assy_Save_MachineData_TEMP where barcode=isnull(@Barcode,'')
					  -- Ended By Sachin 2018-02-13
						          
              End
              IF(@Operation = 'UPDATE_RESULT_FOR_PERFORMANCE')
              Begin
                     
                     select @PokaYokeDateCode=dbo.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE','POKAYOKE','POKAYOKE_DATECODE',@ProfitCode)
                     if charindex(@PokaYokeDateCode,@Barcode)=0
                           BEGIN
                              update Assy_LineAssyStatus_Running  set ResultTimestamp=getdate(), Status=upper(@Status)  where
                                  ProfitCenterCode = @ProfitCode and LineCode = @LineCode and MachineCode = @MachineCode and OperationCode = @OperationCode and
                                  Barcode = @Barcode
                           end

                     if not exists
                     (
                        select top 1 1 from Assy_Result(nolock) where LineCode =  @LineCode and OperationCode  = @OperationCode
                     )
                     Begin
                       insert into Assy_Result(LineCode, OperationCode , StationCode, Barcode ) values (@LineCode, @OperationCode, @StationCode, @Barcode)
                       
                     End
                     else
                     Begin
                       update Assy_Result set Barcode = @Barcode where LineCode = @LineCode and OperationCode = @OperationCode
                     End

                     update Assy_Scan_OK set Barcode = '' where  LineCode =  @LineCode and OperationCode = @OperationCode
                     update Assy_incorrectLabel set Barcode = '' where LineCode = @LineCode and OperationCode = @OperationCode
                     update Assy_DuplicateLabel set Barcode = '' where LineCode = @LineCode and OperationCode = @OperationCode


                     --UnComment when WIP and PokaYoke goes live..
                     

                     
                     select @PokaYokeDateCode=dbo.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE','POKAYOKE','POKAYOKE_DATECODE',@ProfitCode)

                     if charindex(@PokaYokeDateCode,@Barcode)<>0
                           BEGIN
                                SELECT @PLCResult = (SELECT CASE(@result) WHEN 'PS' then 'PASS' ELSE 'FAIL' END)
                                  exec Assy_Proc_UpdatePokaYokeStatus @CONDITION='UPDATE_POKA_YOKE_RESULT',@LineCode=@LineCode, @OperationCode=@OperationCode,
                                  @MachineCode=@MachineCode, @ProfitCenterCode=@ProfitCode, @PLCResult= @PLCResult
                                  ,@Barcode=@Barcode
                                  ,@UserID = @UserId                              
                                  return
                           End                                        

              
                     if(@Status = 'PS')
                     Begin                
                                  exec Assy_Proc_WIP_Manage  @CONDITION='UPDATE_WIP_COUNT', @LineCode=@LineCode,@MachineCode=@MachineCode,@Barcode=@Barcode,@ProfitCenterCode=@ProfitCode, @Result = @Status                    
                              return                
                     End
                     else if(@Status = 'FL')
                     Begin
                                  exec Assy_Proc_WIP_Manage  @CONDITION='UPDATE_WIP_COUNT', @LineCode=@LineCode,@MachineCode=@MachineCode,@Barcode=@Barcode,@ProfitCenterCode=@ProfitCode, @Result = @Status                    
                                  
                                   update Assy_LineAssyStatus_Running set failcount =isnull(failcount,0)+ 1 where Barcode = @Barcode and OperationCode = @OperationCode and ProfitCenterCode = @ProfitCode
                     End              
              
              End
           
              
              IF(@Operation = 'IS_MODEL_CHANGED')
              Begin
                declare @IsModelChanged bit;
              set  @IsModelChanged = (select isnull(IsChanged, 0) as IsChanged from ASSY_ModelChanged(nolock) Where LineCode = @LineCode and OperationCode = @OperationCode)
              if(@IsModelChanged = 1)
              Begin
                 set @ReturnValue = 'Y'
                 update ASSY_ModelChanged set IsChanged = 0 Where LineCode = @LineCode and OperationCode = @OperationCode
              End
              else
              Begin
                 set @ReturnValue = 'N'
              End

              End
              if(@Operation = 'IS_RECIEPE_REQUIRED')

         Begin

           declare @IsRecipeRequired bit = 0

         set @IsRecipeRequired = (select isnull(Recipe, 0) from routingconfiglinewise (nolock) where OperationCode = @OperationCode 

              and Linecode = @Linecode and ProfitCentercode = @ProfitCode)

              if(@IsRecipeRequired = 1)

              Begin

                set @ReturnValue = 'Y'

              End

              else

              Begin

                set @ReturnValue = 'N'

              End

         End  

              if(@Operation = 'SAVE_TEMP_ROTARY_DATA')
         Begin
               if(@OperationCode = 'OC4S')
                        Begin
                             
                             --In case of rotary station part number will be retrieved from assy_runningpart table because scanok will not have records of substatyions
                             --Rotary has to be flushed out before starting new part..
                               SELECT top 1 @Part_No=ISNULL(Assy_PartNo,''),@DateCode=Datecode,@UserId=CreatedBy FROM Assy_RunningPart with (nolock) WHERE LineCode = @LineCode order by CreatedBy desc

                            insert into Assy_LineAssyParamData_Running_Temp (ProfitCenterCode, LineCode, MachineCode, OperationCode, StationCode,
                           Barcode, TagName, Value, Result, DateCode, UserId, Timestamp, PartNo)
                           select @ProfitCode, @LineCode, @MachineCode, @OperationCode, '1', @Barcode, @TagName, @TagValue, @Status,
                                         @DateCode, @UserId, GetDate(), @Part_No    
                                  
                           End
                     End

              if(@Operation = 'GET_TEMP_ROTARY_DATA')
       Begin

SELECT ProfitCenterCode, LineCode, MachineCode, OperationCode, StationCode,
                           Barcode, TagName, Value, Result, DateCode, UserId from Assy_LineAssyParamData_Running_Temp (nolock)
                           where Barcode = @Barcode
                           
            End

              if(@Operation = 'GET_TORQUE_TOOL_DETAILS')
              Begin
                 select TorqueToolIP, TorqueToolPort, TorqueToolModel from assy_TorqueMst (nolock) WHERE ProfitCenterCode = @ProfitCode and
                  OperationCode = @OperationCode and MachineCode = @MachineCode and LineCode = @LineCode
              End
			  if(@Operation = 'INSERT_TORQUE_DETAILS')
              Begin

					  if not exists 
					  (
						  select top 1 1 from dbo.assy_TorqueDetails(nolock) 
						  where ProfitCenterCode=@ProfitCode and LineCode=@LineCode and machineCode=@MachineCode and 
						  operationCode=@OperationCode and barcode=@Barcode and tagName=@TagName
					  )
					  begin
							INSERT INTO assy_TorqueDetails (ProfitCenterCode, LineCode , MachineCode, OperationCode, Barcode, TagName, TagValue, Ent_Dt, Ent_By)
						   select @ProfitCode, @LineCode, @MachineCode, @OperationCode, @Barcode, @TagName, @TagValue, GETDATE(), @UserId
					  end
              End
              
               if(@Operation = 'GET_LAST_RECORD')
              Begin
                     select Top 1 @uid = UID from Assy_LineAssyParamData_Running where  operationcode = @OperationCode and ProfitCenterCode = @ProfitCode
                     and LineCode = @LineCode order by Timestamp desc 

                     select a.Barcode, a.Result, c.TagName,  b.Value,  d.OperationName from Assy_LineAssyParamData_Running as a
                     inner join Assy_LineAssyParamData_Running_Dtl  as b on a.UID = b.UID 
                     inner join TagMst as c on b.TagId = c.TagId
                     inner join OperationMst as d on a.OperationCode = d.OperationCode
                     where a.UID = @uid 
               End

              if(@Operation = 'GET_CURRENT_DATE_PROCESSED_BARCODES')
              Begin
                     select distinct Barcode, Timestamp from Assy_LineAssyParamData_Running  where convert(date, Timestamp) = convert(date, getdate())
                     and LineCode = @LineCode and ProfitCenterCode = @ProfitCode order by timestamp desc
              End
              
              if(@Operation = 'GET_RESULT_FOR_BARCODE')
              Begin
                
                if exists
                (
                   select top 1 1 from Assy_LineAssyParamData_Running where Barcode = @Barcode and Result = 'PS'
                     
                     )
                     Begin
                           select a.Result, c.TagName,  b.Value,  d.OperationName from Assy_LineAssyParamData_Running as a
                           inner join Assy_LineAssyParamData_Running_Dtl  as b on a.UID = b.UID 
                           inner join TagMst as c on b.TagId = c.TagId
                           inner join OperationMst as d on a.OperationCode = d.OperationCode
                           where a.Barcode = @Barcode and a.Result = 'PS' order by a.OperationCode 
                     End
                else
                Begin
                           select a.Result, c.TagName,  b.Value,  d.OperationName from Assy_LineAssyParamData_Running as a
                         inner join Assy_LineAssyParamData_Running_Dtl  as b on a.UID = b.UID 
                           inner join TagMst as c on b.TagId = c.TagId
                    inner join OperationMst as d on a.OperationCode = d.OperationCode
                           where a.Barcode = @Barcode and a.Result = 'FL' order by a.OperationCode
                End
              End

              if(@Operation = 'GET_PASS_FAIL_COUNT')
              Begin
                DECLARE @PASSCOUNT INT = 0
         SELECT @PASSCOUNT = ISNULL( COUNT(BARCODE), 0) from Assy_LineAssyStatus_Running where Status = 'PS' and OperationCode = @OperationCode
                and LineCode = @LineCode and ProfitCenterCode = @ProfitCode
                 and convert(date, ResultTimeStamp) = convert(date, getdate()) 

                 SELECT @FAILCOUNT = ISNULL( COUNT(BARCODE), 0) from Assy_LineAssyStatus_Running where Status = 'FL' and OperationCode = @OperationCode
                and LineCode = @LineCode and ProfitCenterCode = @ProfitCode
                 and convert(date, ResultTimeStamp) = convert(date, getdate())

                 SELECT @PASSCOUNT, @FAILCOUNT
              End

                if(@Operation = 'GET_MAINSERVER_CONNECTION_STRING')
              Begin
                 
                 SELECT isnull(ConnectionString, '')ConnectionString FROM assy_ConnectionString_MainServer
                 where ProfitCenterCode = @ProfitCode AND LineCode = @LineCode
              End

		-- ADDED BY SACHIN 20161201
		-- CHECK TO SAVE TEXT LOG OR NOT.
		if(@Operation = 'TEXT_DATA_LOG')
        Begin
          
          
				  declare @IsTextLogRequired bit = 0
				  select @IsTextLogRequired = isnull(IsTextLogRequired,0) from RoutingConfigLineWise (nolock) where LineCode = @LineCode and ProfitCenterCode = @ProfitCode
				  and OperationCode = @OperationCode
          
				  if(@IsTextLogRequired=1)
				  begin
						SET @RETURNVALUE='YES'
				  end
				  else
					  begin
							SET @RETURNVALUE='NO'
					  end
		 End
		 if @Operation ='Insert_Caliper_PreCoupling_Data'
		 begin
						insert into Assy_Caliper_PreCoupling_Data
						(
							ProfitCenterCode,
							LineCode,
							MachineCode,
							Result,
							TimeStamp
						)
						select @ProfitCode,@linecode,@MachineCode,@PreCoupling_Data,getdate()

		end
         
       --TRY BLOCK ENDS
	   else if @Operation='Get_CaliperSrNo'
		begin
				
				--delete old date record				
				delete  from assy_DayWise_SerialNo where ProfitCenterCode=@ProfitCode and LineCode =@LineCode  and PartNo=@EngPartNo 
				and ProdDate<>@ProdDate

				if exists
				(
						select 1 from assy_DayWise_SerialNo where ProfitCenterCode=@ProfitCode and LineCode =@LineCode  and PartNo=@EngPartNo and ProdDate=@ProdDate
				)
				begin
						 update assy_DayWise_SerialNo set SerialNo=isnull(SerialNo,0)+1 ,ModifiedTimestamp=getdate()
						 where ProfitCenterCode=@ProfitCode and LineCode =@LineCode  and PartNo=@EngPartNo and ProdDate=@ProdDate
				end
				else
				begin
						  insert into assy_DayWise_SerialNo(ProfitCenterCode,LineCode,PartNo,SerialNo,ProdDate,CreatedTimestamp)
													  select @ProfitCode,@LineCode,@EngPartNo,1,convert(date,getdate()),getdate()
				end		
				
				select @SerialNo=isnull(isnull(SerialNo,0),0) from assy_DayWise_SerialNo(nolock) 
				where ProfitCenterCode=@ProfitCode and LineCode =@LineCode  and PartNo=@EngPartNo and ProdDate=@ProdDate
								
				set @ReturnValue=Convert(varchar(10),isnull(@SerialNo,0))
		end
		 --Added By Rashid On 20170606 For 2Parts Status
		ELSE IF @Operation ='GET_2PARTS_ALLOW_FLAG'
		BEGIN

			SELECT @ReturnValue = Allow2Parts FROM LineMst WITH (NOLOCK)  WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode
			SELECT @ReturnValue = ISNULL(@ReturnValue,''), @ReturnInt = 1
			RETURN
		END

		ELSE IF @Operation ='GET_STATION_ASSIGN_PART'
		BEGIN
			
			--MODIFIED BY AV ON 20181222
			--IF @OPERATIONCODE='OC4S'
			DECLARE @SecondOpperation VARCHAR(10)
			WITH CTE 
			AS(
				SELECT ROW_NUMBER() OVER(ORDER BY OperationSeqNo)AS RN, OperationCode
				FROM RoutingConfigLineWise(NOLOCK) 
				WHERE OperationRequired=1 AND Traceability=1
			)
			SELECT @SecondOpperation = OperationCode FROM CTE
			WHERE RN=2

		     IF @OPERATIONCODE=@SecondOpperation
			 begin
			         SELECT top 1 @ReturnValue = assy_PartNo FROM Assy_runningpart WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode
			 end
			 else
			 begin
					SELECT @ReturnValue = PartNo FROM Assy_MachineWise_RunningPart WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode 
					AND OperationCode = @OperationCode					
			 end
			 SELECT @ReturnValue = ISNULL(@ReturnValue,''), @ReturnInt = 1
			RETURN
		END

		ELSE IF @Operation = 'UPDATE_PART_NO_STATION_WISE_FROM_PLC'
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM Assy_MachineWise_RunningPart WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LINECODE AND OperationCode = @OPERATIONCODE)
			BEGIN
				INSERT INTO Assy_MachineWise_RunningPart (ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,PartNo,CreatedDate)
				SELECT @ProfitCode, @LINECODE, @MachineCode, @OPERATIONCODE, 1, @HMIPartNo, GETDATE()
			END
			ELSE
			BEGIN
				UPDATE Assy_MachineWise_RunningPart Set PartNo = @HMIPartNo, UpdatedDate = GETDATE()
					WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LINECODE AND OperationCode = @OPERATIONCODE
			END

			SELECT @ReturnValue = 'SUCCESS', @ReturnInt = 1
			RETURN
		END
		ELSE IF @Operation = 'UPDATE_SHOW_FLASH_MSG'
		Begin

			if exists (select top 1 1 from Assy_FlashMsg_Status where [MSG_CD]=@TagName and [Machine_Code]=@machinecode and [Operation_Code] = @OperationCode 
			and WH_Code = @ProfitCode and [Line_Code]=@linecode )
		   Begin
			   update Assy_FlashMsg_Status set 
			   [MsgShow_sts]=@Status,[Upd_dt]=getdate(),[MsgUpd_Count] = [MsgUpd_Count]+1
			   where [MSG_CD]=@TagName and [Machine_Code]=@machinecode and [Operation_Code] = @OperationCode
			   and WH_Code = @ProfitCode and [Line_Code]=@linecode

			end
			else
			begin

					INSERT INTO [dbo].[Assy_FlashMsg_Status]
					([WH_Code],[Machine_Code],[Operation_Code],[MSG_CD],[MSG_TEXT]
					,[Ent_dt],[Ent_By],[Upd_dt],[MsgShow_sts],[MsgUpd_Count],[Line_Code])
					VALUES
					(@ProfitCode,@machinecode,@OperationCode,@TagName,@TagName + ': Problem ',getdate(),'ADMIN',getdate(),
					@Status,0,@linecode)

			end

		END
       END TRY 
       BEGIN CATCH  
              --CATCH BLOCK BEGINS       
              SET @ReturnValue =   CAST(ERROR_NUMBER() as varchar(5)) + '|' + 
              CAST(ERROR_SEVERITY()as varchar(5)) + '|' + 
              CAST(ERROR_STATE() as varchar(5)) + '|' + 
              CAST(ERROR_PROCEDURE() as varchar(200)) + '|' + 
       CAST(ERROR_LINE() as varchar(5)) + '|' + 
              CAST(ERROR_MESSAGE() as varchar(1500))
              raiserror(@ReturnValue,16,1)
              SET @ReturnInt = 2
       --CATCH BLOCK ENDS 
       END CATCH
       END
GO
