/*************************************************************************************** 
PROCEDURE : ASSY_PROC_DO_VALIDATION
AUTHOR: SACHIN KUMAR
DATE WRITTEN :  23/06/2017
PURPOSE:  To Do Validation
TEST SCRIPT  

exec ASSY_PROC_DO_VALIDATION @P_ValidationCode=1,@P_PROFITCENTERCODE='0088',@P_LINECODE='ABS',
@P_MachineCode='MC10',@P_OPERATION_CODE='OC10',@P_TABLE_NAME='Assy_'

declare   @P_ReturnValue VARCHAR (2000)=NULL
 declare  @P_ReturnInt INT


exec ASSY_PROC_DO_VALIDATION @P_ValidationCode=2,
@P_PROFITCENTERCODE='0088',@P_LINECODE='ABS',
@P_MachineCode='MC10',@P_OPERATION_CODE='OC10',
@P_TABLE1='Assy_Result_20A_Log'
,@P_COLUMN_TABLE1='ISO_LH_Front,ISO_RH_Front,ISO_LH_REAR,ISO_RH_REAR',@P_TABLE2='ASSY_RESULT_40A_LOG',
@P_COLUMN_TABLE2='Cartridge1_Load,Cartridge2_Load,Cartridge3_Load,Cartridge4_Load',
@P_Barcode='L10034',@ReturnValue=@P_ReturnValue out ,@ReturnInt =@P_ReturnInt out
select @P_ReturnValue,@P_ReturnInt

declare   @P_ReturnValue VARCHAR (2000)=NULL
 declare  @P_ReturnInt INT
exec ASSY_PROC_DO_VALIDATION @P_ValidationCode=3,
@P_PROFITCENTERCODE='0018',@P_LINECODE='S01',
@P_MachineCode='MC50',@P_OPERATION_CODE='OC50',
@P_TABLE1='Assy_Result_50A'
,@P_COLUMN_TABLE1='Motor_Barcode',
@P_COLUMN_TABLE2='',
@P_Barcode='L10034',@ReturnValue=@P_ReturnValue out ,@ReturnInt =@P_ReturnInt out
select @P_ReturnValue,@P_ReturnInt


****************************************************************************************/
CREATE PROCEDURE [dbo].[ASSY_PROC_DO_VALIDATION]
(
  @P_ValidationCode int =0,
  @P_PROFITCENTERCODE varchar(10) = '',
  @P_LINECODE  varchar(10) = '',
  @P_MachineCode varchar(10)='',
  @P_PartNo varchar(30)='',
  @P_OPERATION_CODE varchar(10) ='',
  @P_Barcode varchar(30)='',
  @P_DateCode char(4)='',
  @P_TABLE1 varchar(100)='',
  @P_COLUMN_TABLE1 varchar(2000)='',
  @P_TABLE2 varchar(100)='',
  @P_COLUMN_TABLE2 varchar(2000)='',
  @ReturnValue VARCHAR (2000)=NULL OUT,
  @ReturnInt INT=NULL OUT
  
)
AS
BEGIN
DECLARE @SQL_QUERY nvarchar(2000)

IF(@P_ValidationCode=1)
BEGIN
		
		DECLARE @CHILDPART_1 VARCHAR(2000)
		DECLARE @SAVE_CHILD_PART_1 TABLE
		(
		   RW_CNT    INT,	
		   CHILD_PART varchar(30),
		   CHILD_PART_BARCODE varchar(100)
		)

		SET @SQL_QUERY = '
							select top 1 ' + @P_COLUMN_TABLE1 +' into #TEMP_VALIDATE_1_' + @P_TABLE1 +' from '+ @P_TABLE1+' (nolock) 
							WHERE SCANSTATUS=1 AND TS_SCAN_OK=0 
							AND Barcode =' + '''' +@P_Barcode+'''
							order by ScanTimeStamp desc

							DECLARE @XmldataLK XML = (SELECT * FROM  #TEMP_VALIDATE_1_' + @P_TABLE1 +' FOR XML PATH('''') )   
						
							--Dynamic unpivoting 
							SELECT * FROM  ( 
							SELECT 
							ROW_NUMBER()OVER(PARTITION BY   ColumnName ORDER BY  ColumnValue) rn,* FROM ( 
							SELECT  i.value(''local-name(.)'',''varchar(100)'')  ColumnName, 
							i.value(''.'',''varchar(100)'') ColumnValue 
							FROM @xmldataLK.nodes(''//*'') x(i) ) tmp ) tmp1
					
					'
		insert into @SAVE_CHILD_PART_1(RW_CNT,CHILD_PART,CHILD_PART_BARCODE)
		EXEC (@SQL_QUERY)

		select * into #temp_validation_1 from assy_Child_Part_Details(NOLOCK) 
		where --ProfitCenterCode=@P_PROFITCENTERCODE and LineCode=@P_LINECODE and MachineCode=@P_MachineCode and
		--OperationCode=@P_OPERATION_CODE and PartNumber=@P_PartNo and 
		ChildPartBarcode
		in (select CHILD_PART_BARCODE from @SAVE_CHILD_PART_1)
		and Barcode <> @P_Barcode and STS_CD=0
		if exists(select top 1 1 from #temp_validation_1)
		begin
				

				select @CHILDPART_1 = coalesce(@CHILDPART_1 + ',', '') +  convert(varchar(12),ChildPartBarcode)
				from #temp_validation_1
				order by ChildPartBarcode

				
				--select @CHILDPART_1 = ChildPartBarcode from #temp_validation_1
				SET @RETURNVALUE ='CP ('+@CHILDPART_1+') Already Scanned'
				SET @RETURNINT =1	
				return
		end

		SELECT * INTO #TEMP_VALIDATION_2 FROM ASSY_CHILD_PART_DETAILS_REWORK_LOG(NOLOCK) WHERE CHILDPARTBARCODE
		IN (SELECT CHILD_PART_BARCODE FROM @SAVE_CHILD_PART_1)
		--AND BARCODE <> @P_BARCODE 
		AND STS_CD=200

		IF EXISTS(SELECT TOP 1 1 FROM #TEMP_VALIDATION_2)
		BEGIN
				SELECT @CHILDPART_1 = COALESCE(@CHILDPART_1 + ',', '') +  CONVERT(VARCHAR(12),CHILDPARTBARCODE)
				FROM #TEMP_VALIDATION_2
				ORDER BY CHILDPARTBARCODE

				SET @RETURNVALUE ='CP ('+@CHILDPART_1+') SCRAPED'
				SET @RETURNINT =1	
				RETURN
		END

END

IF(@P_ValidationCode=2)
BEGIN

		DECLARE @CHILDPART_2 VARCHAR(2000)
		DECLARE @SAVE_CHILD_PART_2 TABLE
		(
		   RW_CNT    INT,	
		   CHILD_PART varchar(30),
		   CHILD_PART_BARCODE varchar(100)
		)
		DECLARE @SAVE_CHILD_PART_2_2 TABLE
		(
		   RW_CNT    INT,	
		   CHILD_PART varchar(30),
		   CHILD_PART_BARCODE varchar(100)
		)

		SET @SQL_QUERY = '
							select top 1 ' + @P_COLUMN_TABLE1 +' into #TEMP_VALIDATE_2_' + @P_TABLE1 +' from '+ @P_TABLE1+' (nolock) 
							WHERE SCANSTATUS=1 AND STS_CD=100 AND TS_SCAN_OK=1 
							AND Barcode =' + '''' +@P_Barcode+'''
							order by Result_Read_TS desc

							DECLARE @XmldataLK XML = (SELECT * FROM  #TEMP_VALIDATE_2_' + @P_TABLE1 +' FOR XML PATH('''') )   
						
							--Dynamic unpivoting 
							SELECT * FROM  ( 
							SELECT 
							ROW_NUMBER()OVER(PARTITION BY   ColumnName ORDER BY  ColumnValue) rn,* FROM ( 
							SELECT  i.value(''local-name(.)'',''varchar(100)'')  ColumnName, 
							i.value(''.'',''varchar(100)'') ColumnValue 
							FROM @xmldataLK.nodes(''//*'') x(i) ) tmp ) tmp1
					
					'
		insert into @SAVE_CHILD_PART_2(RW_CNT,CHILD_PART,CHILD_PART_BARCODE)
		EXEC (@SQL_QUERY)

		SET @SQL_QUERY = '
							select top 1 ' + @P_COLUMN_TABLE2 +' into #TEMP_VALIDATE_2_' + @P_TABLE2 +' from '+ @P_TABLE2+' (nolock) 
							WHERE SCANSTATUS=1 AND STS_CD=0 AND TS_SCAN_OK=0 
							AND Barcode =' + '''' +@P_Barcode+'''
							order by Result_Read_TS desc

							DECLARE @XmldataLK XML = (SELECT * FROM  #TEMP_VALIDATE_2_' + @P_TABLE2 +' FOR XML PATH('''') )   
						
							--Dynamic unpivoting 
							SELECT * FROM  ( 
							SELECT 
							ROW_NUMBER()OVER(PARTITION BY   ColumnName ORDER BY  ColumnValue) rn,* FROM ( 
							SELECT  i.value(''local-name(.)'',''varchar(100)'')  ColumnName, 
							i.value(''.'',''varchar(100)'') ColumnValue 
							FROM @xmldataLK.nodes(''//*'') x(i) ) tmp ) tmp1
					
					'
		insert into @SAVE_CHILD_PART_2_2(RW_CNT,CHILD_PART,CHILD_PART_BARCODE)
		EXEC (@SQL_QUERY)

		select distinct ROW_NO,col1 into #temp_COLUMN_TABLE1 from dbo.FN_GRID_SPLIT_STRING(@P_COLUMN_TABLE1,'',',')
		select distinct ROW_NO,col1 into #temp_COLUMN_TABLE2 from dbo.FN_GRID_SPLIT_STRING(@P_COLUMN_TABLE2,'',',')

		if (exists (select top 1 1 from #temp_COLUMN_TABLE1))
		begin
				declare @rowCount int 
				declare @value1 varchar(20)
				declare @value2 varchar(20)
				while exists(select top 1 1 from #temp_COLUMN_TABLE1)
				begin
					  
					  select top 1  @rowCount=ROW_NO from #temp_COLUMN_TABLE1 order by ROW_NO asc
					  
					  if ( (select top 1 CHILD_PART_BARCODE from @SAVE_CHILD_PART_2 where CHILD_PART in (
					    select col1 from #temp_COLUMN_TABLE1 where ROW_NO=@rowCount
					  )) <>
					  (select top 1 CHILD_PART_BARCODE from @SAVE_CHILD_PART_2_2 where CHILD_PART in (
					    select col1 from #temp_COLUMN_TABLE2 where ROW_NO=@rowCount
					  ))
					  )
					  begin 
							declare @positionX nvarchar(20)
							declare @positionY nvarchar(20)
							select @positionX=ISNULL(col1,'') from #temp_COLUMN_TABLE1 where ROW_NO=@rowCount
							select @positionY=ISNULL(col1,'') from #temp_COLUMN_TABLE2 where ROW_NO=@rowCount

						    SET @RETURNVALUE ='Sequence of ' + @positionX + ' Not Match With ' + @positionY
							SET @RETURNINT =1	
							return

					  end

					  delete from #temp_COLUMN_TABLE1 where ROW_NO=@rowCount
				end

		end

END

IF(@P_ValidationCode=3)
BEGIN


		DECLARE @SAVE_CHILD_PART_3 TABLE
		(
		   RW_CNT    INT,	
		   CHILD_PART varchar(30),
		   CHILD_PART_BARCODE varchar(100)
		)

		SET @SQL_QUERY = '
							select top 1 ' + @P_COLUMN_TABLE1 +' into #TEMP_VALIDATE_3_' + @P_TABLE1 +' from '+ @P_TABLE1+' (nolock) 
							WHERE SCANSTATUS=1 AND STS_CD=0 AND TS_SCAN_OK=0 
							AND Barcode =' + '''' +@P_Barcode+'''
							order by ScanTimeStamp desc

							DECLARE @XmldataLK XML = (SELECT * FROM  #TEMP_VALIDATE_3_' + @P_TABLE1 +' FOR XML PATH('''') )   
						
							--Dynamic unpivoting 
							SELECT * FROM  ( 
							SELECT 
							ROW_NUMBER()OVER(PARTITION BY   ColumnName ORDER BY  ColumnValue) rn,* FROM ( 
							SELECT  i.value(''local-name(.)'',''varchar(100)'')  ColumnName, 
							i.value(''.'',''varchar(100)'') ColumnValue 
							FROM @xmldataLK.nodes(''//*'') x(i) ) tmp ) tmp1
					
					'
		
		insert into @SAVE_CHILD_PART_3(RW_CNT,CHILD_PART,CHILD_PART_BARCODE)
		EXEC (@SQL_QUERY)

		
		
		if not exists (select top 1 1 from assy_Child_Part_Details(nolock) where barcode=@P_Barcode
		and ChildPartBarcode in (select distinct CHILD_PART_BARCODE from @SAVE_CHILD_PART_3)
		)begin
		
		insert into assy_Child_Part_Details(
		ProfitCenterCode,LineCode,MachineCode,OperationCode,PartNumber,DateCode,Barcode,ChildPartNo,
		ChildPartBarcode,STS_CD,ENT_BY,ENT_STAMP
		)
		select distinct @P_PROFITCENTERCODE,@P_LINECODE,@P_MachineCode,@P_OPERATION_CODE,@P_PartNo,@P_DateCode,@P_Barcode,CHILD_PART,
		CHILD_PART_BARCODE,0,'ADMIN',getdate() from @SAVE_CHILD_PART_3 tmp 

		-- inner join 
		--Assy_Child_Part_Details(nolock) cpd
		--on @P_Barcode <> cpd.barcode
		--and tmp.CHILD_PART_BARCODE <> cpd.ChildPartBarcode
		end
	 
END


IF(@P_ValidationCode=4)
BEGIN

	declare @scanningType varchar(10)
	declare @childPart varchar(30)
	declare @childPartSeqNo int
	declare @barcode nvarchar(100) ='2906683547Jb00000002M07'

	SELECT @SCANNINGTYPE=KEYVALUE FROM ROUTINGCONFIGDETAILS(NOLOCK) WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE 
	AND LINECODE = @P_LINECODE AND KEYTYPE='ChildPartScanningType' AND STS_CD=0
	
	select * into #TEMP_RoutingConfigDetails from RoutingConfigDetails(nolock) 
	where ProfitCenterCode=@P_PROFITCENTERCODE and LineCode = @P_LINECODE
	 and MachineCode=@P_MachineCode and OperationCode = @P_OPERATION_CODE and 
	PartNumber=@P_PartNo and KeyType='ChildParts' and STS_CD=0

	IF(@SCANNINGTYPE='DB') -- if DB mode we found child Parts in Table
	BEGIN			
			IF EXISTS(SELECT TOP 1 1 FROM #TEMP_ROUTINGCONFIGDETAILS)
			BEGIN
					
					-- Task :  Required Child Part From Table. 
					
					select * into #temp_assy_Child_Part_Details from assy_Child_Part_Details(nolock) 
					where ProfitCenterCode=@P_PROFITCENTERCODE and LineCode = @P_LINECODE
					and MachineCode=@P_MachineCode and OperationCode = @P_OPERATION_CODE and PartNumber=@P_PartNo 
					and Barcode=@barcode

					SELECT top 1 @CHILDPART=KEYVALUE,@childPartSeqNo=SEQNUMBER FROM #TEMP_ROUTINGCONFIGDETAILS tr
					where KEYVALUE not in (select ChildPartNo from #temp_assy_Child_Part_Details)
					ORDER BY tr.SEQNUMBER
					
					if (charindex(@CHILDPART,@p_barcode)=0)
					begin
							SET @RETURNVALUE ='Scan Child Part ' + @CHILDPART +''
							SET @RETURNINT =1	
							return
					end

					if (charindex(@CHILDPART,@p_barcode) > 0)
					begin					
							if exists(select top 1 1 from assy_Child_Part_Details(NOLOCK) 
							where ProfitCenterCode=@P_PROFITCENTERCODE and LineCode=@P_LINECODE and MachineCode=@P_MachineCode and
							OperationCode=@P_OPERATION_CODE and PartNumber=@P_PartNo and ChildPartBarcode=@p_barcode)
							begin
									SET @RETURNVALUE ='CP ('+@CHILDPART+') Already Scanned'
									SET @RETURNINT =1	
									return
							end
					end

					if(LEN(ISNULL(@CHILDPART,'')) > 1)
					begin
							insert into assy_Child_Part_Details(
							ProfitCenterCode,LineCode,MachineCode,OperationCode,PartNumber,DateCode,Barcode,ChildPartNo,
							ChildPartBarcode,SeqNumber,STS_CD,ENT_BY,ENT_STAMP
							)
							values( @P_PROFITCENTERCODE,@P_LINECODE,@P_MachineCode,@P_OPERATION_CODE,@P_PartNo,@P_DateCode,@barcode,@CHILDPART,
							@p_barcode,@childPartSeqNo,0,'ADMIN',getdate())

							SELECT top 1 @CHILDPART=KEYVALUE FROM #TEMP_ROUTINGCONFIGDETAILS tr
							where SEQNUMBER = ( @childPartSeqNo+1)
							

							SET @RETURNVALUE ='NEXT_CHILD_PART|'+CONVERT(varchar,@CHILDPART)
							SET @RETURNINT =1	
							return
					end

			END
			
			--select * from Assy_Child_Part_Details
	END 

	IF(@SCANNINGTYPE='BLUETOOTH') -- if Bluetooth mode we have to scan TS Barcode and Child Part both from front end.
	BEGIN
			select 1
	END
	
	 
END


IF(@P_ValidationCode=5) -- OCR Validation passed from machining or not
BEGIN
		DECLARE @EXECQUERY VARCHAR(MAX),@LINKSERVERNAME VARCHAR(100)
		DECLARE @CHILDPART_5 VARCHAR(2000)
	
		DECLARE @SAVE_CHILD_PART_5 TABLE
		(
		   RW_CNT    INT,	
		   CHILD_PART varchar(30),
		   CHILD_PART_BARCODE varchar(100)
		)

		SET @SQL_QUERY = '
							select top 1 ' + @P_COLUMN_TABLE1 +' into #TEMP_VALIDATE_1_' + @P_TABLE1 +' from '+ @P_TABLE1+' (nolock) 
							WHERE SCANSTATUS=1 AND STS_CD=0 AND TS_SCAN_OK=0 
							AND Barcode =' + '''' +@P_Barcode+'''
							order by ScanTimeStamp desc

							DECLARE @XmldataLK XML = (SELECT * FROM  #TEMP_VALIDATE_1_' + @P_TABLE1 +' FOR XML PATH('''') )   
						
							--Dynamic unpivoting 
							SELECT * FROM  ( 
							SELECT 
							ROW_NUMBER()OVER(PARTITION BY   ColumnName ORDER BY  ColumnValue) rn,* FROM ( 
							SELECT  i.value(''local-name(.)'',''varchar(100)'')  ColumnName, 
							i.value(''.'',''varchar(100)'') ColumnValue 
							FROM @xmldataLK.nodes(''//*'') x(i) ) tmp ) tmp1
					
					'
		
		insert into @SAVE_CHILD_PART_5(RW_CNT,CHILD_PART,CHILD_PART_BARCODE)
		EXEC (@SQL_QUERY)

		SELECT @CHILDPART_1=CHILD_PART_BARCODE FROM @SAVE_CHILD_PART_5
	
		SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL  WITH (NOLOCK) 
		WHERE PROFITCENTERCODE = @P_PROFITCENTERCODE AND LINECODE = @P_lineCode

		SET @EXECQUERY = 'SELECT * FROM ' + @LINKSERVERNAME + 
		'.DBO.ENG_FVDtl WITH (NOLOCK) 
		WHERE OCRCode=' +''''+@P_Barcode+'''' + ' AND StatusCode=1'

		exec(@EXECQUERY)
	
		if (@@ROWCOUNT=0)
		begin
					SET @RETURNVALUE ='OCR ('+@CHILDPART_1+') Not Passed From Engraving'
					SET @RETURNINT =1	
					return
		end

END


END




















