GO

/***************************************************************************************                    
PROCEDURE         :     ASSY_PROC_ENABLE_DISABLE_PARAMETERS
AUTHOR            :     SACHIN KUMAR
DATE WRITTEN      :     23/06/2017
PURPOSE           :     To Do Validation
TEST SCRIPT  

declare @ReturnValue VARCHAR (2000)=NULL
declare @ReturnInt INT=NULL   

exec  ASSY_PROC_ENABLE_DISABLE_PARAMETERS @P_PROFITCENTERCODE='0018', 
@P_LINECODE='S01' ,@P_Condition='CURRENTAUTOTALLYSTATUS',@ReturnInt=@ReturnInt out,
@ReturnValue =@ReturnValue out

select @ReturnInt,@ReturnValue 

****************************************************************************************/
CREATE PROCEDURE [dbo].[ASSY_PROC_ENABLE_DISABLE_PARAMETERS]
( 
  @P_PROFITCENTERCODE varchar(10) = '',
  @P_LINECODE  varchar(10) = '',
  @P_EnableDisable bit='0',
  @P_Condition varchar(100) = '',
  @P_Form_Page_Name varchar(50) = '',
  @P_UserType varchar(20) = '',
  @ReturnValue VARCHAR (2000)=NULL OUT,
  @ReturnInt INT=NULL OUT  
)
AS
BEGIN
		
 if(@p_Condition='CURRENTAUTOTALLYSTATUS')
 begin
		set @ReturnValue = (select top 1 case when ISNULL(AutoTallyChartEnable,0) = 1 then 'Y' else 'N' end as 'AutoTallyChartEnable'  from lineMst(nolock) where profitcenterCode=@P_PROFITCENTERCODE
		and lineCode=@P_LINECODE)
		set @ReturnInt=1
 end

  if(@p_Condition='ENABLE_DISABLE_AUTO_TALLY')
  begin
		update LineMst set AutoTallyChartEnable=@P_EnableDisable 
		where linecode=@P_LINECODE and profitcenterCode=@P_PROFITCENTERCODE
		if(@P_EnableDisable=1)
		begin
		set @ReturnValue = 'Y'
		end
		if(@P_EnableDisable=0)
		begin
		set @ReturnValue = 'N'
		end
		set @ReturnInt=1
  end

  if(@p_Condition='GET_AUTH_CNTRL_BTN_LIST')
  begin
			select UserType,ControlName,IsVisible,ISNULL(CtrlSequence,0) as CtrlSequence from Assy_PermissionControl(nolock)
			where 
			ProfitCenterCode=@P_PROFITCENTERCODE and
			LineCode = @P_LINECODE and Form_Page_Name=@P_Form_Page_Name and
			UserType = @P_UserType and ISNULL(IsActive,0)=1
  end
 

END





















