SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[Assy_proc_FinalQCStn_Label_Printing]
(
@CONDITION VARCHAR(60),
@PROFITCENTERCODE VARCHAR(20)=NULL,
@LINECODE VARCHAR(20)=NULL,
@Barcode varchar(100)=NUll,
@RFID varchar(60)=NULL,
@MachineCode varchar(10)=NUll,
@OperationCode varchar(10)=NUll,
@ActSerialNo smallint=0,
@ReturnValue VARCHAR (2000)=NULL OUT,
@ReturnInt INT=NULL OUT,
@PartNo varchar(60)=Null,
@DateCode char(4)=null,
@CaliperDatecode varchar(10)=null,
@ZPL_DATA nvarchar(2000)='', -- added by sachin 20170403 
@Allow2Parts bit=0
)
--Author :<Ravishankar Mishra>
--Created date:<15/06/2016>

--Modified By :<Ravishankar Mishra>
--Modified date:<21/11/2016>
--Description: 
/*
1.	INSERT_BARCODE_DATA -To get part no. and date code from vision system table instead of assy_running part table.
2.	INSERT_BARCODE_DATA_IN_MainServer - To Get part no and date code as an input parameters instead of getting from running part table
3.	GET_LABEL_INFO- 
	a.	Get DOY on basis of coupling station testing timestamp not from current timestamp.
	b.	Check duplicate Caliper Serial No on basis of date code provided by VE at coupling station not on basis of Set Parameter Data code.
4. CODE ADDED BY SACHIN 20170303 -- To Print Fv Barcode From Backend
5. CODE ADDED BY SACHIN 20170403 -- To Take Reprint of Customer label save it in assy_ZPL_LOG
*/

--Modified By :<Ravishankar Mishra>
--Modified date:<08/12/2016>
--Changed in block "GET_LABEL_INFO" to get label information according to RFID tags part no not on basis of currently selected running part no 
--,insert and get CaliperDatecode from table

--Modified By :<Ravishankar Mishra>
--Modified date:<19/06/2017>
--Description: If VE is generated duplicate Caliper serial no. at coupling station in a particular Date, TS shall not allow duplicate serial no. at Final QC station.
--Modified By :<Ravishankar Mishra>
--Modified date:<10/08/2017>
--Description: Done changes in GET_LABEL_INFO block, read caliper datecode and serial no. from Assy_LineAssyParamData_Running table only.

--exec Assy_proc_FinalQCStn_Label_Printing @Condition='INSERT_BARCODE_DATA',@ProfitCenterCode='0088',@Linecode='J04',@RFID='1931600548Jc00001298J04'
--,@Barcode='00193160050019990000117216 ',@ActSerialNo=98,@MachineCode='MCFV',@OperationCode='OCFV',,@CaliperDatecode='12Mc'

--declare @ReturnValue varchar(200)
--exec Assy_proc_FinalQCStn_Label_Printing @Condition='GET_LABEL_INFO',@ProfitCenterCode='0088',@Linecode='J04',@MachineCode='MCCP',@RFID='2903305230Qd00000381J05',@ReturnValue=@ReturnValue out
--select @ReturnValue

--exec Assy_proc_FinalQCStn_Label_Printing @Condition='INSERT_BARCODE_DATA_In_Mainserver',@ProfitCenterCode='0088',@Linecode='J04',@RFID='1931600525Ac00000001J04'
--,@Barcode='00193160050016180000117216 ',@MachineCode='MCFV',@OperationCode='OCFV',@CaliperDatecode='12Mc',@Datecode='12Pc',,@ActSerialNo=98

--exec Assy_proc_FinalQCStn_Label_Printing @Condition='ASSY_LINEASSYSTATUS_RFID_NETWORK_DROP_RECORDS',@ProfitCenterCode='0088',@Linecode='J04',@RFID='1931600525Ac00000002J04'
--,@MachineCode='MCFV',@OperationCode='OCFV'

AS
BEGIN
		SET NOCOUNT ON
		Declare @JulDate char(5)		
		declare @TotNoOfDupRecoreds tinyint 
		declare @CoupTestDateTime datetime	
	    declare @ProdDate Date,@CaliperSrNo smallint
		declare @IsPrintWithoutEngravingSerial  bit = 0
		Declare @CustomerPartNo nvarchar(100) = ''
		DECLARE @DATECODE_OUT VARCHAR(4) = ''
        DECLARE @CALIPERSERIALNO VARCHAR(10) = ''
		DECLARE @EngPartNo VARCHAR(12) = ''
		DECLARE @DrawingNo varchar(20) = ''
		DECLARE @SupplierNo varchar(20) = ''
		DECLARE @MM varchar(20) = ''
		DECLARE @TYPE varchar(20) = '' 
		DECLARE @BACKPLATE varchar(40) = ''
		DECLARE	@V_ABS varchar(40) = ''
		DECLARE	@V_DICV varchar(40) = ''
		DECLARE	@V_FUSO_PART_NO varchar(40) = ''
		DECLARE	@V_SIZE varchar(40) = ''
		DECLARE	@GenerationDateCode varchar(4) = ''
		DECLARE @IsCheckCaliperSerialNumber smallint = 1
		DECLARE @IsLabelRequired smallint = 1
		declare @PRNFILE nvarchar(max),@GROUPCODE nvarchar(50)
		DECLARE @strBarcode varchar(100)=''
		DECLARE @initpartno varchar(50)=''
		DECLARE @prefix varchar(5)=''
		DECLARE @DrgRevLvl varchar(50)=''
		DECLARE @VendorCd varchar(20)=''
		DECLARE @DateMMYY varchar(4)
		DECLARE @SerialNo varchar(6)

		select *  into #TEMP_Assy_Coupling_LabelInfo_Mst from Assy_Coupling_LabelInfo_Mst(NOLOCK) 
		where 1=2

		if @CONDITION='GET_LABEL_INFO'
		begin		   
				-- Comment By Sachin 20181122     
				--if isnull(@MachineCode,'')=''
				--begin
				--     set @MachineCode=dbo.ASSY_FN_GET_PARAMETER_VALUE('assline','Coupling','MachineCode',@PROFITCENTERCODE)
				--end
				-- Comment Ended
				set @strBarcode = @RFID
				select top 1 @MachineCode=KeyValue from RoutingConfigDetails(nolock) 
				where ProfitCenterCode=@PROFITCENTERCODE and LineCode=@LINECODE and STS_CD=0 and KeyType='EngravingStationMachineCode'
				
				select top 1 @IsCheckCaliperSerialNumber=Convert(smallint,KeyValue) from RoutingConfigDetails(nolock) 
				where ProfitCenterCode=@PROFITCENTERCODE and LineCode=@LINECODE and STS_CD=0 and KeyType='IsCheckCaliperSerialNumber'

				select top 1 @IsLabelRequired=Convert(smallint,KeyValue) from RoutingConfigDetails(nolock) 
				where ProfitCenterCode=@PROFITCENTERCODE and LineCode=@LINECODE and STS_CD=0 and KeyType='IsLabelRequired'

				if(isnull(@PartNo,'')='')
				begin
					select @PartNo=Assy_PartNo from Assy_RunningPart where PROFITCENTERCODE=@PROFITCENTERCODE 
					and LineCode=@LINECODE
				end

				select top 1 @IsPrintWithoutEngravingSerial=ISNULL(KeyValue,0) from RoutingConfigDetails(nolock) where 
				KeyType='IsPrintWithoutEngravingSerial' 
				and ProfitCenterCode=@PROFITCENTERCODE 
				and LineCode=@LINECODE 
				and machinecode=@MachineCode
				
				if(@IsPrintWithoutEngravingSerial=1)
				begin
	
				         Declare @ResetFreq varchar(10)=1
						 select @ResetFreq=isnull(keyvalue,'1')  from RoutingConfigDetails with(nolock)
						 where PartNumber=@PartNo and ProfitCenterCode=@PROFITCENTERCODE and linecode=@LINECODE
						 and KeyType='SERIALRESETFREQUENCY'
						 --print @ResetFreq
						 if(@ResetFreq='3')
						 begin
							  EXEC ASSY_PROC_GetSerial_DayPartWise  @P_PROFITCENTERCODE=@PROFITCENTERCODE,
							  @P_LINECODE=@LINECODE,@P_PartNumber=@PartNo,
							  @P_ReturnSerialNo=@CALIPERSERIALNO OUT,@P_RETURNDATECODE=@DATECODE_OUT OUT
						 end
						 else
						 begin
							 EXEC ASSY_PROC_GETCALIPERSERIAL_DATECODEWISE  @P_PROFITCENTERCODE=@PROFITCENTERCODE,
							 @P_LINECODE=@LINECODE,@P_MachineCode=@MachineCode,
							 @P_RETURNCALIPERSERIALNO=@CALIPERSERIALNO OUT,@P_RETURNDATECODE=@DATECODE_OUT OUT
						 end
						 --print @CALIPERSERIALNO
						 select top 1 @GenerationDateCode=Datecode,@initpartno=PartNo 
						 from Assy_LineAssyStatus(nolock) where 
						 ProfitCenterCode=@PROFITCENTERCODE
						 and LineCode=@LINECODE and Barcode=@RFID 
						 and MachineCode='MCIG' and OperationCode='OCIG'
						 order by ResultTimestamp desc

						 IF(ISNULL(@GenerationDateCode,'')='')
						 BEGIN
							select top 1 @GenerationDateCode=Datecode,@initpartno=PartNo 
							from Assy_LineAssyStatus_running(nolock) where 
							ProfitCenterCode=@PROFITCENTERCODE
							and LineCode=@LINECODE and Barcode=@RFID 
							and MachineCode='MCIG' and OperationCode='OCIG'
							order by ResultTimestamp desc
						 END

						 print 'GenerationDateCode ' + ISNULL(@GenerationDateCode,'') 
						 + ' initpartno ' + ISNULL(@initpartno,'')

						 if exists(select top 1 1 from Assy_RunningPart(nolock) 
						 where ProfitCenterCode=@PROFITCENTERCODE
						 and LineCode=@LINECODE and Assy_PartNo=@initpartno)
						 begin
								print '---1----'
								 select top 1 @PartNo=Assy_PartNo,@CustomerPartNo = ISNULL(CustomerPartNo,'') 
								 from Assy_RunningPart(nolock) 
								 where ProfitCenterCode=@PROFITCENTERCODE
								 and LineCode=@LINECODE and Assy_PartNo=@initpartno

						 end
						 else
						 begin
								print '---2----'
								select top 1 @PartNo=Assy_PartNo,@CustomerPartNo = ISNULL(CustomerPartNo,'') 
								from Assy_RunningPartFamily(nolock) 
								where ProfitCenterCode=@PROFITCENTERCODE
								and LineCode=@LINECODE and Assy_PartNo=@initpartno
								order by isnull(modifiedOn,CreatedDate) desc

						 end

						 if isnull(@CustomerPartNo,'')=''
						begin
							set @ReturnValue='Please_Select_Customer_Part_Number'
							set @ReturnInt=1
							return
						end


				end
				else
				begin
				--Get Serial No		
				select @CaliperDatecode=CaliperDatecode,@CaliperSrNo=CaliperSrNo,@PartNo=PartNo,@ProdDate=convert(date,Timestamp),@CoupTestDateTime=Timestamp
				from dbo.Assy_LineAssyParamData_Running  with (nolock)  				
				where ProfitCenterCode=@PROFITCENTERCODE  and LineCode=@LINECODE and machinecode=@MachineCode  
				and barcode=@RFID  and isnull(Result,'')='PS' 								

				if isnull(@CaliperSrNo,'0')='0' and @IsCheckCaliperSerialNumber = 1
				begin
						set @ReturnValue='Caliper_serial_no_has_not_been_generated_at_Coupling_Station'
						set @ReturnInt=1
						return
				end

				select @TotNoOfDupRecoreds=count(CaliperSrNo) from dbo.Assy_LineAssyParamData_Running  with (nolock)  
				where ProfitCenterCode=@PROFITCENTERCODE and LineCode=@LINECODE and machinecode=@MachineCode  
				and CaliperSrNo=@CaliperSrNo and isnull(Result,'')='PS'						
				and convert(date, Timestamp)=@ProdDate   
				and PartNo=@PartNo				
				print 'No of Records in Assy_LineAssyParamData_Running-'+Convert(varchar(20),@TotNoOfDupRecoreds)
				--Check this caliper serial no. has been already generated.
				
				IF (@IsCheckCaliperSerialNumber = 1)
				BEGIN
					if isnull(@TotNoOfDupRecoreds,0)>1 
					begin
							set @ReturnValue='Same_caliper_serial_no_has_been_already_generated.'
							set @ReturnInt=1
							return
					end				
					else if exists
					(
							select 1 from dbo.Assy_LineAssyParamData with (nolock)  							
							where ProfitCenterCode=@PROFITCENTERCODE and LineCode=@LINECODE and machinecode=@MachineCode 
							and  CaliperSrNo=@CaliperSrNo and isnull(Result,'')='PS'						
							and convert(date, Timestamp)=@ProdDate  
							and PartNo=@PartNo						
					)
					begin
							set @ReturnValue='Same_caliper_serial_no_has_been_already_generated.'
							set @ReturnInt=1
							print 'No of Records in Assy_LineAssyParamData-'+Convert(varchar(20),@TotNoOfDupRecoreds)
							return
					end		
				END
				set @ActSerialNo=@CaliperSrNo	
								
				--Get Julien Data
				--set @JulDate= rtrim(convert(char(3),datepart(dy,@CoupTestDateTime)))+convert(char(2),right(YEAR( @CoupTestDateTime),2))	
				--Added By Sachin 20190209
				declare @TEMP_DATE as Table
				(
				[DATE]	varchar(20),
				FROMTIME	 varchar(20),
				TOTIME varchar(20)
				)
				declare @Julian_Date date
				insert into @TEMP_DATE([Date],FROMTIME,TOTIME)
				EXEC ASSY_PROC_GETDATE_FROMDATECODE @DATECODE=@CaliperDatecode,@PROFITCENTERCODE=@PROFITCENTERCODE

				if exists(select top 1 1 from @TEMP_DATE where isnull([Date],'')<>'')
				begin
				select top 1 @Julian_Date=CONVERT(date,[Date]) from @TEMP_DATE
				end
				else
				begin
						set @ReturnValue='Julian_Date_Not_Found'
						set @ReturnInt=1							
						return
				end
				set @JulDate= rtrim(convert(char(3),datepart(dy,@Julian_Date)))+convert(char(2),right(YEAR( @Julian_Date),2))
				--Ended By Sachin 20190209


				-- modify by sachin 20170120
				if(LEN(@JulDate)=3)
				begin
				set @JulDate='00'+@JulDate
				end

				if(LEN(@JulDate)=4)
				begin
				set @JulDate='0'+@JulDate
				end

				
				--Get Part no
				select @PartNo=PartNo from dbo.Assy_FN_Get_BarcodeParts_From_Barcode(@ProfitCenterCode,@LineCode,@RFID)
				end
				/*
				  CODE ADDED BY SACHIN 20170303
				  CODE IS USED TO PRINT FV BARCODE FROM BACKEND
				*/
				
				print 'Part Number ' + ISNULL(@PartNo,'') + ' Customer Number ' + ISNULL(@CustomerPartNo,'')

				if(ISNULL(@CustomerPartNo,'')<>'')
				begin
					select @PRNFILE=ISNULL(PRNFile,''),@GROUPCODE=ISNULL(prn.GROUPCODE,'') from Assy_PRN_CustomerGroupMaster(NOLOCK) prnGroup
					inner join ASSY_PRN_GROUPMASTER(NOLOCK) prn on
					prnGroup.GROUPCODE=prn.GROUPCODE
					where PartNo=@PartNo and CustomerPartNo = @CustomerPartNo

					insert into #TEMP_Assy_Coupling_LabelInfo_Mst
					select *  from Assy_Coupling_LabelInfo_Mst(NOLOCK) prnGroup
					where PartNo=@PartNo and CustomerPartNo=@CustomerPartNo

				
				end
				else
				begin
					
					select @PRNFILE=ISNULL(PRNFile,''),@GROUPCODE=ISNULL(prn.GROUPCODE,'') from Assy_PRN_CustomerGroupMaster(NOLOCK) prnGroup
					inner join ASSY_PRN_GROUPMASTER(NOLOCK) prn on
					prnGroup.GROUPCODE=prn.GROUPCODE
					where PartNo=@PartNo

					insert into #TEMP_Assy_Coupling_LabelInfo_Mst
					select *  from Assy_Coupling_LabelInfo_Mst(NOLOCK) prnGroup
					where PartNo=@PartNo 

				end
				IF(@IsLabelRequired=1)
				BEGIN
					IF (ISNULL(@PRNFILE,'')='' OR ISNULL(@GROUPCODE,'')='') 
					BEGIn
					set @ReturnValue='PRN_FILE_DOES_NOT_EXISTS'
					set @ReturnInt=1
					return
					END
			
					IF NOT EXISTS(SELECT TOP 1 1 FROM Assy_Coupling_LabelInfo_Mst(nolock)
					where ProfitCenterCode=@ProfitCenterCode  and PartNo= @PartNo)
					BEGIN
					set @ReturnValue='PRN_DATA_DOES_NOT_EXISTS'
					set @ReturnInt=1
					return
					END
				END
				print @GROUPCODE
				IF(@GROUPCODE='GC_JHAGADIA_FINALVIEWING_STATION')
				BEGIN
						
						select top 1 @DrawingNo=rtrim(ltrim(LabelDataValue))
						from  #TEMP_Assy_Coupling_LabelInfo_Mst(nolock)
						where ProfitCenterCode=@ProfitCenterCode  and PartNo= @PartNo and rtrim(ltrim(LabelDataName))='Drawing_No'

						select top 1 @SupplierNo=rtrim(ltrim(LabelDataValue))
						from  #TEMP_Assy_Coupling_LabelInfo_Mst(nolock)
						where ProfitCenterCode=@ProfitCenterCode  and PartNo= @PartNo and rtrim(ltrim(LabelDataName))='Supplier_No'
				
						SET @strBarcode = ISNULL(@DrawingNo,'') + ISNULL(@SupplierNo,'') + 
						REPLICATE('0',5 - LEN(@ActSerialNo)) + CONVERT(NVARCHAR, @ActSerialNo)+ ISNULL(@JulDate,'');

						SET @PRNFILE=REPLACE(@PRNFILE,'V_BARCODE',ISNULL(@strBarcode,''))
						SET @PRNFILE=REPLACE(@PRNFILE,'V_TEXT',ISNULL(@strBarcode,''))
										
				END

				IF(@GROUPCODE='GC_JHAGADIA_FINALVIEWING_STATION_J01')-- added by sachin 20170331 -- to print J01 line label
				BEGIN

					select @CustomerPartNo=ISNULL(CustomerPartNo,'') from Assy_PRN_CustomerGroupMaster(NOLOCK) prnGroup
					where PartNo=@PartNo 
					
					SET @strBarcode = @CustomerPartNo+convert(varchar, getdate(), 103)

					SET @PRNFILE = REPLACE(@PRNFILE,'V_BARCODE',@strBarcode)
					SET @PRNFILE = REPLACE(@PRNFILE,'V_CUST_PART_NO',@CustomerPartNo)
					SET @PRNFILE = REPLACE(@PRNFILE,'V_DATE',convert(varchar, getdate(), 103))
										
				END

				IF(@GROUPCODE='GC_JHAGADIA_FINALVIEWING_STATION_J06')-- added by sachin 2019.703 -- to print J06 line label
				BEGIN
				
					select Top 1 @prefix=LabelDataValue from #TEMP_Assy_Coupling_LabelInfo_Mst(NOLOCK) prnGroup
					where PartNo=@PartNo and LabelDataName='prefix'

					select Top 1 @CustomerPartNo=LabelDataValue from #TEMP_Assy_Coupling_LabelInfo_Mst(NOLOCK) prnGroup
					where PartNo=@PartNo and LabelDataName='CustPartNo'					

					select Top 1 @DrgRevLvl=LabelDataValue from #TEMP_Assy_Coupling_LabelInfo_Mst(NOLOCK) prnGroup
					where PartNo=@PartNo and LabelDataName='DrgRevLvl'

					select Top 1 @VendorCd=LabelDataValue from #TEMP_Assy_Coupling_LabelInfo_Mst(NOLOCK) prnGroup
					where PartNo=@PartNo and LabelDataName='VendorCd'

					
					EXEC ASSY_PROC_GetSerial_MMYYDateWise 
					@PROFITCENTERCODE,@LINECODE,@PartNo,@P_ReturnSerialNo=@SerialNo out
					,@P_ReturnMMYY=@DateMMYY out
					

					SET @strBarcode = ISNULL(@prefix,'')+ISNULL(@CustomerPartNo,'') + 
					ISNULL(@DrgRevLvl,'') + ISNULL(@VendorCd,'') + ISNULL(@DateMMYY,'') + ISNULL(@SerialNo,'')

					SET @PRNFILE = REPLACE(@PRNFILE,'V_BARCODE',@strBarcode)
					SET @PRNFILE = REPLACE(@PRNFILE,'V_DRAWING_NO',@prefix)
					SET @PRNFILE = REPLACE(@PRNFILE,'V_PART_NO',@CustomerPartNo)
					SET @PRNFILE = REPLACE(@PRNFILE,'V_SERIAL',@SerialNo)
					SET @PRNFILE = REPLACE(@PRNFILE,'V_REVISIONLVL',@DrgRevLvl)
					SET @PRNFILE = REPLACE(@PRNFILE,'V_VENDORCODE',@VendorCd)
					SET @PRNFILE = REPLACE(@PRNFILE,'V_DATE',@DateMMYY)
															
				END


				IF(@GROUPCODE='FUSO')-- added by sachin 20181121 -- print for drum brake assembly
				BEGIN
					-- 29023398:ML270811:22Gd:29196429:RL-120:0001 example				
					--barcode = partno + ":" + custpartno + ":" + datecode + ":" + txtloadingbc.Text.Trim() + ":" + SIZE + "-" + MM + ":" + seq_no;
					
					select Top 1 @V_FUSO_PART_NO=LabelDataValue from #TEMP_Assy_Coupling_LabelInfo_Mst(NOLOCK) prnGroup
					where PartNo=@PartNo and CustomerPartNo=@CustomerPartNo and LabelDataName='V_FUSO_PART_NO'

					select Top 1 @V_SIZE=LabelDataValue from #TEMP_Assy_Coupling_LabelInfo_Mst(NOLOCK) prnGroup
					where PartNo=@PartNo and CustomerPartNo=@CustomerPartNo and LabelDataName='V_SIZE'

					select Top 1 @V_DICV=LabelDataValue from #TEMP_Assy_Coupling_LabelInfo_Mst(NOLOCK) prnGroup
					where PartNo=@PartNo and CustomerPartNo=@CustomerPartNo and LabelDataName='V_DICV'
					
					select Top 1 @V_ABS=LabelDataValue from #TEMP_Assy_Coupling_LabelInfo_Mst(NOLOCK) prnGroup
					where PartNo=@PartNo and CustomerPartNo=@CustomerPartNo and LabelDataName='V_ABS'

					select Top 1 @BACKPLATE=LabelDataValue from #TEMP_Assy_Coupling_LabelInfo_Mst(NOLOCK) prnGroup
					where PartNo=@PartNo and CustomerPartNo=@CustomerPartNo and LabelDataName='BACKPLATE'

					SET @strBarcode = @PartNo + ':' + @CustomerPartNo + ':' + @DATECODE_OUT + ':' + @BACKPLATE + ':'
					+ LTRIM(RTRIM(@V_SIZE)) + ':' + @CALIPERSERIALNO
					
					SET @ActSerialNo = @CALIPERSERIALNO
					SET @CaliperDatecode = @DATECODE_OUT

					SET @PRNFILE = REPLACE(@PRNFILE,'V_Size',@V_SIZE)
					SET @PRNFILE = REPLACE(@PRNFILE,'V_fusopartno',@V_FUSO_PART_NO)
					SET @PRNFILE = REPLACE(@PRNFILE,'V_DICV',@V_DICV)
					SET @PRNFILE = REPLACE(@PRNFILE,'V_SNO',@CALIPERSERIALNO)
					SET @PRNFILE = REPLACE(@PRNFILE,'V_Abs',@V_ABS)
					SET @PRNFILE = REPLACE(@PRNFILE,'V_Barcode',@strBarcode)

				END
				
				IF(@GROUPCODE='TITAN')-- added by sachin 20181121 -- print for drum brake assembly
				BEGIN
					-- \1E06\1DPA4004209101\1D1T2017060500001\1E\04 example				
					--  barcode = @"\1E06\1DP" + dicv_part_no + @"\1D1T" + date + seq_no + @"\1E\04";
					
					--select Top 1 @V_SIZE=LabelDataValue from #TEMP_Assy_Coupling_LabelInfo_Mst(NOLOCK) prnGroup
					--where PartNo=@PartNo and CustomerPartNo=@CustomerPartNo and LabelDataName='V_SIZE'

					--select Top 1 @V_DICV=LabelDataValue from #TEMP_Assy_Coupling_LabelInfo_Mst(NOLOCK) prnGroup
					--where PartNo=@PartNo and CustomerPartNo=@CustomerPartNo and LabelDataName='V_DICV'
					
					--select Top 1 @V_ABS=LabelDataValue from #TEMP_Assy_Coupling_LabelInfo_Mst(NOLOCK) prnGroup
					--where PartNo=@PartNo and CustomerPartNo=@CustomerPartNo and LabelDataName='V_ABS'

					--select Top 1 @BACKPLATE=LabelDataValue from #TEMP_Assy_Coupling_LabelInfo_Mst(NOLOCK) prnGroup
					--where PartNo=@PartNo and CustomerPartNo=@CustomerPartNo and LabelDataName='BACKPLATE'

					--SET @strBarcode = '[)>' + ISNULL(@PartNo,'') + ':' +  ISNULL(@CustomerPartNo,'') + ':' +  ISNULL(@DATECODE_OUT,'') 
					--+ ':' +  ISNULL(@BACKPLATE,'') + ':' + LTRIM(RTRIM(@V_SIZE)) + ':' +  ISNULL(@CALIPERSERIALNO,'')
					
					--SET @ActSerialNo = @CALIPERSERIALNO
					--SET @CaliperDatecode = @DATECODE_OUT

					select Top 1 @V_SIZE=LabelDataValue from #TEMP_Assy_Coupling_LabelInfo_Mst(NOLOCK) prnGroup
					where PartNo=@PartNo and CustomerPartNo=@CustomerPartNo and LabelDataName='V_SIZE'

					select Top 1 @V_DICV=LabelDataValue from #TEMP_Assy_Coupling_LabelInfo_Mst(NOLOCK) prnGroup
					where PartNo=@PartNo and CustomerPartNo=@CustomerPartNo and LabelDataName='V_DICV'
					
					select Top 1 @V_ABS=LabelDataValue from #TEMP_Assy_Coupling_LabelInfo_Mst(NOLOCK) prnGroup
					where PartNo=@PartNo and CustomerPartNo=@CustomerPartNo and LabelDataName='V_ABS'
					
					print @CALIPERSERIALNO
					SET @strBarcode ='[)>'+ '\1E06\1DP' + @CustomerPartNo + '\1D1T'
					+ convert(varchar, getdate(), 112) 
					+ @CALIPERSERIALNO + '\1E\04'

					SET @ActSerialNo = @CALIPERSERIALNO
					SET @CaliperDatecode = @DATECODE_OUT

					SET @PRNFILE = REPLACE(@PRNFILE,'V_Size',@V_SIZE)
					SET @PRNFILE = REPLACE(@PRNFILE,'V_DICV',@V_DICV)
					SET @PRNFILE = REPLACE(@PRNFILE,'V_SNO',@CALIPERSERIALNO)
					SET @PRNFILE = REPLACE(@PRNFILE,'V_Abs',@V_ABS)
					SET @PRNFILE = REPLACE(@PRNFILE,'V_Barcode',@strBarcode)

				END

				select top 1 rtrim(ltrim(LabelDataName))LabelDataName,rtrim(ltrim(LabelDataValue))LabelDataValue,
				 @ActSerialNo SerialNo,isnull(@JulDate,'') DOY
				,@CaliperDatecode as CaliperDatecode , @PRNFILE as 'PRN_FILE' , 
				ISNULL(@strBarcode,'') as PRINTED_BARCODE,
				ISNULL(@PartNo,'') as PARTNO,
				ISNULL(@GenerationDateCode,'') as GENERATIONDATECODE				
				from  Assy_Coupling_LabelInfo_Mst(nolock)
				where ProfitCenterCode=@ProfitCenterCode  and PartNo= @PartNo
				
				set @ReturnInt=1
				return
		end
		else if @CONDITION='INSERT_BARCODE_DATA'
		begin			
		      BEGIN TRY
						BEGIN TRAN
							
							select top 1 @IsPrintWithoutEngravingSerial=ISNULL(KeyValue,0) 
							from RoutingConfigDetails(nolock) where 
							KeyType='IsPrintWithoutEngravingSerial' 
							and ProfitCenterCode=@ProfitCenterCode 
							and LineCode=@LineCode 
							and machinecode=@MachineCode

							print '------- ' + isnull(convert(varchar,@IsPrintWithoutEngravingSerial),'') + ' -----------'
							if(@IsPrintWithoutEngravingSerial=1)
							begin
								print '----'
							end
							else
							begin
							select @PartNo=PartNo,@datecode=Datecode 
							from dbo.Assy_FN_Get_BarcodeParts_From_Barcode(@ProfitCenterCode,@LineCode,@RFID)
							end 

							print '------- ' + isnull(@PartNo,'') + ' -----------'
							insert into Assy_FinalViewing_RFID_Barcode_Mapping
							(
								[ProfitCenterCode] ,[LineCode] ,[MachineCode] ,[OperationCode] 
								,[RFID] ,[Barcode],[Status],[PartNo] ,[Datecode] ,[PrintedTimestamp],CaliperSerNo,CaliperDatecode 
							)
							select @PROFITCENTERCODE,@LINECODE,@MachineCode,@OperationCode 
							,@RFID,@Barcode,'PS',@PartNo,@datecode,getdate(),@ActSerialNo,@CaliperDatecode					
					
							insert into Assy_ZPL_log
							(
								[ProfitCenterCode] ,[LineCode] ,[MachineCode] ,[OperationCode] 
								,[RFID] ,[Barcode],[Status],[PartNo] ,[Datecode] ,[PrintedTimestamp],CaliperSerNo,CaliperDatecode,ZPL_DATA 
							)
							select @PROFITCENTERCODE,@LINECODE,@MachineCode,@OperationCode 
							,@RFID,@Barcode,'PS',@PartNo,@datecode,getdate(),@ActSerialNo,@CaliperDatecode,@ZPL_DATA					
					
							 --Added by Ravi on 04-07-17
						  if @Allow2Parts=1
					  	  Begin
								INSERT INTO ASSY_LINEASSYPARAMDATA_DTL
								(	
									UID,
									TAGID,
									VALUE
								)
								SELECT D.UID,D.TAGID,D.VALUE FROM  ASSY_LINEASSYPARAMDATA_RUNNING_DTL d (NOLOCK) 
								join ASSY_LINEASSYPARAMDATA_RUNNING H (NOLOCK)
								on H.UID =d.UID 
								WHERE LINECODE=@LINECODE 
								AND PROFITCENTERCODE =@PROFITCENTERCODE
								and barcode=@RFID

								INSERT INTO ASSY_LINEASSYPARAMDATA
								(
								[PROFITCENTERCODE]
								,[LINECODE]
								,[MACHINECODE]
								,[OPERATIONCODE]
								,[STATIONCODE]
								,[BARCODE]
								,[TAGNAME]
								,[VALUE]
								,[RESULT]
								,[DATECODE]
								,[USERID]
								,[TIMESTAMP]
								,PARTNO
								,UID
								,ScanTimestamp
								,CaliperDatecode
								,CaliperSrNo
								)
								SELECT
								[PROFITCENTERCODE]
								,[LINECODE]
								,[MACHINECODE]
								,[OPERATIONCODE]
								,[STATIONCODE]
								,[BARCODE]
								,[TAGNAME]
								,[VALUE]
								,[RESULT]
								,[DATECODE]
								,[USERID]
								,[TIMESTAMP]
								,PARTNO
								,UID
								,ScanTimestamp
								,CaliperDatecode
								,CaliperSrNo
								FROM ASSY_LINEASSYPARAMDATA_RUNNING(NOLOCK)
								WHERE  PROFITCENTERCODE =@PROFITCENTERCODE and LINECODE=@LINECODE
								and barcode=@RFID

								delete d FROM  ASSY_LINEASSYPARAMDATA_RUNNING_DTL d (NOLOCK) 
								join ASSY_LINEASSYPARAMDATA_RUNNING H (NOLOCK)
								on H.UID =d.UID 
								WHERE PROFITCENTERCODE =@PROFITCENTERCODE and LINECODE=@LINECODE
								and barcode=@RFID
							
								DELETE ASSY_LINEASSYPARAMDATA_RUNNING 
								WHERE PROFITCENTERCODE =@PROFITCENTERCODE and LINECODE=@LINECODE and barcode=@RFID
					      END
						 					   
							set @ReturnInt=1
							set @ReturnValue=@datecode+'|'+@PartNo
						COMMIT TRAN
				END TRY
				BEGIN CATCH
			
							SET @RETURNVALUE =	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
							CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
							CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
							CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
							CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
							CAST(ERROR_MESSAGE() AS VARCHAR(1500))
			
							ROLLBACK TRAN				
							SET @RETURNINT = 2
							RAISERROR(@RETURNVALUE,16,1)	
				END CATCH
				return
		end
		else if @CONDITION='INSERT_BARCODE_DATA_IN_MainServer'
		begin								

					insert into Assy_FinalViewing_RFID_Barcode_Mapping
					(
						[ProfitCenterCode] ,[LineCode] ,[MachineCode] ,[OperationCode] 
						,[RFID] ,[Barcode],[Status],[PartNo] ,[Datecode] ,[PrintedTimestamp],CaliperSerNo,CaliperDatecode 
					)
					select @PROFITCENTERCODE,@LINECODE,@MachineCode,@OperationCode 
					,@RFID,@Barcode,'PS',@PartNo,@datecode,getdate(),@ActSerialNo,@CaliperDatecode
					set @ReturnInt=1
				    return
		end
		else if @CONDITION='ASSY_LINEASSYSTATUS_RFID_NETWORK_DROP_RECORDS'
		begin
				 -- Modified by Sachin 16March2020
				 insert into  Assy_FinalViewing_RFID_Barcode_Network_Drop (ProfitCenterCode,LineCode,MachineCode,RFID,Barcode,Ent_Stamp)
                 select @PROFITCENTERCODE,@LINECODE,@MachineCode,@RFID,@Barcode,getdate()

		end 
		else if @CONDITION='GET_LABEL_INFO_VALIDATION'
		begin		   
				-- Comment By Sachin 20181122     
				--if isnull(@MachineCode,'')=''
				--begin
				--     set @MachineCode=dbo.ASSY_FN_GET_PARAMETER_VALUE			('assline','Coupling','MachineCode',@PROFITCENTERCODE)
				--end
				-- Comment Ended
				set @strBarcode = @RFID
				select top 1 @MachineCode=KeyValue from RoutingConfigDetails(nolock) 
				where ProfitCenterCode=@PROFITCENTERCODE and LineCode=@LINECODE and STS_CD=0 and KeyType='EngravingStationMachineCode'
				
				select top 1 @IsCheckCaliperSerialNumber=Convert(smallint,KeyValue) from RoutingConfigDetails(nolock) 
				where ProfitCenterCode=@PROFITCENTERCODE and LineCode=@LINECODE and STS_CD=0 and KeyType='IsCheckCaliperSerialNumber'

				select top 1 @IsLabelRequired=Convert(smallint,KeyValue) from RoutingConfigDetails(nolock) 
				where ProfitCenterCode=@PROFITCENTERCODE and LineCode=@LINECODE and STS_CD=0 and KeyType='IsLabelRequired'

				select top 1 @IsPrintWithoutEngravingSerial=ISNULL(KeyValue,0) from RoutingConfigDetails(nolock) where 
				KeyType='IsPrintWithoutEngravingSerial' 
				and ProfitCenterCode=@PROFITCENTERCODE 
				and LineCode=@LINECODE 
				and machinecode=@MachineCode

				if(@IsPrintWithoutEngravingSerial=1)
				begin
						 --EXEC ASSY_PROC_GETCALIPERSERIAL_DATECODEWISE  @P_PROFITCENTERCODE=@PROFITCENTERCODE,
						 --@P_LINECODE=@LINECODE,@P_MachineCode=@MachineCode,
						 --@P_RETURNCALIPERSERIALNO=@CALIPERSERIALNO OUT,@P_RETURNDATECODE=@DATECODE_OUT OUT
						  print 'RFID ' + ISNULL(@RFID,'') 

						 select top 1 @GenerationDateCode=Datecode,@initpartno=PartNo 
						 from Assy_LineAssyStatus_running(nolock) where 
						 ProfitCenterCode=@PROFITCENTERCODE
						 and LineCode=@LINECODE and Barcode=@RFID 
						 and MachineCode='MCIG' and OperationCode='OCIG'
						 order by ResultTimestamp desc

						 print 'GenerationDateCode ' + ISNULL(@GenerationDateCode,'') 
						 + ' initpartno ' + ISNULL(@initpartno,'')

						 if exists(select top 1 1 from Assy_RunningPart(nolock) 
						 where ProfitCenterCode=@PROFITCENTERCODE
						 and LineCode=@LINECODE and Assy_PartNo=@initpartno)
						 begin

								 select top 1 @PartNo=Assy_PartNo,@CustomerPartNo = ISNULL(CustomerPartNo,'') 
								 from Assy_RunningPart(nolock) 
								 where ProfitCenterCode=@PROFITCENTERCODE
								 and LineCode=@LINECODE and Assy_PartNo=@initpartno

						 end
						 else
						 begin

								select top 1 @PartNo=Assy_PartNo,@CustomerPartNo = ISNULL(CustomerPartNo,'') 
								from Assy_RunningPartFamily(nolock) 
								where ProfitCenterCode=@PROFITCENTERCODE
								and LineCode=@LINECODE and Assy_PartNo=@initpartno
								order by isnull(modifiedOn,CreatedDate) desc

						 end

						if isnull(@CustomerPartNo,'')=''
						begin
							set @ReturnValue='Please_Select_Customer_Part_Number'
							set @ReturnInt=1
							return
						end
				end
				else
				begin
				--Get Serial No		
				select @CaliperDatecode=CaliperDatecode,@CaliperSrNo=CaliperSrNo,@PartNo=PartNo,@ProdDate=convert(date,Timestamp),@CoupTestDateTime=Timestamp
				from dbo.Assy_LineAssyParamData_Running  with (nolock)  				
				where ProfitCenterCode=@PROFITCENTERCODE  and LineCode=@LINECODE and machinecode=@MachineCode  
				and barcode=@RFID  and isnull(Result,'')='PS' 								

				if isnull(@CaliperSrNo,'0')='0' and @IsCheckCaliperSerialNumber = 1
				begin
						set @ReturnValue='Caliper_serial_no_has_not_been_generated_at_Coupling_Station'
						set @ReturnInt=1
						return
				end

				select @TotNoOfDupRecoreds=count(CaliperSrNo) from dbo.Assy_LineAssyParamData_Running  with (nolock)  
				where ProfitCenterCode=@PROFITCENTERCODE and LineCode=@LINECODE and machinecode=@MachineCode  
				and CaliperSrNo=@CaliperSrNo and isnull(Result,'')='PS'						
				and convert(date, Timestamp)=@ProdDate   
				and PartNo=@PartNo				
				print 'No of Records in Assy_LineAssyParamData_Running-'+Convert(varchar(20),@TotNoOfDupRecoreds)
				--Check this caliper serial no. has been already generated.
				
				IF (@IsCheckCaliperSerialNumber = 1)
				BEGIN
					if isnull(@TotNoOfDupRecoreds,0)>1 
					begin
							set @ReturnValue='Same_caliper_serial_no_has_been_already_generated.'
							set @ReturnInt=1
							return
					end				
					else if exists
					(
							select 1 from dbo.Assy_LineAssyParamData with (nolock)  							
							where ProfitCenterCode=@PROFITCENTERCODE and LineCode=@LINECODE and machinecode=@MachineCode 
							and  CaliperSrNo=@CaliperSrNo and isnull(Result,'')='PS'						
							and convert(date, Timestamp)=@ProdDate  
							and PartNo=@PartNo						
					)
					begin
							set @ReturnValue='Same_caliper_serial_no_has_been_already_generated.'
							set @ReturnInt=1
							print 'No of Records in Assy_LineAssyParamData-'+Convert(varchar(20),@TotNoOfDupRecoreds)
							return
					end		
				END
				set @ActSerialNo=@CaliperSrNo	
								
				--Get Julien Data
				set @JulDate= rtrim(convert(char(3),datepart(dy,@CoupTestDateTime)))+convert(char(2),right(YEAR( @CoupTestDateTime),2))	
				-- modify by sachin 20170120
				if(LEN(@JulDate)=3)
				begin
				set @JulDate='00'+@JulDate
				end

				if(LEN(@JulDate)=4)
				begin
				set @JulDate='0'+@JulDate
				end

				
				--Get Part no
				select @PartNo=PartNo from dbo.Assy_FN_Get_BarcodeParts_From_Barcode(@ProfitCenterCode,@LineCode,@RFID)
				end
				/*
				  CODE ADDED BY SACHIN 20170303
				  CODE IS USED TO PRINT FV BARCODE FROM BACKEND
				*/
				
				print 'Part Number ' + ISNULL(@PartNo,'') + ' Customer Number ' + ISNULL(@CustomerPartNo,'')

				if(ISNULL(@CustomerPartNo,'')<>'')
				begin
					select @PRNFILE=ISNULL(PRNFile,''),@GROUPCODE=ISNULL(prn.GROUPCODE,'') from Assy_PRN_CustomerGroupMaster(NOLOCK) prnGroup
					inner join ASSY_PRN_GROUPMASTER(NOLOCK) prn on
					prnGroup.GROUPCODE=prn.GROUPCODE
					where PartNo=@PartNo and CustomerPartNo = @CustomerPartNo
					
					insert into #TEMP_Assy_Coupling_LabelInfo_Mst
					select * from Assy_Coupling_LabelInfo_Mst(NOLOCK) prnGroup
					where PartNo=@PartNo and CustomerPartNo=@CustomerPartNo

				end
				else
				begin
					select top 1 @PRNFILE=ISNULL(PRNFile,''),@GROUPCODE=ISNULL(prn.GROUPCODE,'') from Assy_PRN_CustomerGroupMaster(NOLOCK) prnGroup
					inner join ASSY_PRN_GROUPMASTER(NOLOCK) prn on
					prnGroup.GROUPCODE=prn.GROUPCODE
					where PartNo=@PartNo
				end

				IF(@IsLabelRequired=1)
				BEGIN
					IF (ISNULL(@PRNFILE,'')='' OR ISNULL(@GROUPCODE,'')='') 
					BEGIn
					set @ReturnValue='PRN_FILE_DOES_NOT_EXISTS'
					set @ReturnInt=1
					return
					END
			
					IF NOT EXISTS(SELECT TOP 1 1 FROM Assy_Coupling_LabelInfo_Mst(nolock)
					where ProfitCenterCode=@ProfitCenterCode  and PartNo= @PartNo)
					BEGIN
					set @ReturnValue='PRN_DATA_DOES_NOT_EXISTS'
					set @ReturnInt=1
					return
					END
				END

				select top 1 rtrim(ltrim(LabelDataName))LabelDataName,rtrim(ltrim(LabelDataValue))LabelDataValue,
				 @ActSerialNo SerialNo,isnull(@JulDate,'') DOY
				,@CaliperDatecode as CaliperDatecode , @PRNFILE as 'PRN_FILE' , 
				ISNULL(@strBarcode,'') as PRINTED_BARCODE,
				ISNULL(@PartNo,'') as PARTNO,
				ISNULL(@GenerationDateCode,'') as GENERATIONDATECODE				
				from  Assy_Coupling_LabelInfo_Mst(nolock)
				where ProfitCenterCode=@ProfitCenterCode  and PartNo= @PartNo
				
				set @ReturnInt=1
				return
		end
END

