		Declare @ParameterData Assy_TYPE_LineAssyParamData_Running_Db
		DECLARE @P_Result varchar(2) = 'PS'

		--Added By RS On 20180202 for rerun the transaction which is victim of Deadlock
		DECLARE @RetryCounter INT
		SET @RetryCounter = 1
		SELECT @ISLINKSERVERCPRUPDATE = 0, @CHANGEOVER_DATECODE = @DATECODE

		--Added By Sachin 20190301
		declare @MainTable  varchar(100) = ''
		declare @MainLogTable  varchar(100) = ''
		declare @listCoulumn varchar(2000) = ''
		declare @listCoulumnMain varchar(max) = null
		declare @listCoulumnlog varchar(2000) = ''
		declare @dynamic_query varchar(max) = ''
		declare @MachineDBTableName  varchar(100) = ''
		declare @MachineDBWhereClauseColumn  varchar(100) = ''
		--Ended By Sachin 20190301
		declare @SET_RESERVOIR_PART VARCHAR(50)= '',@GET_RESERVOIR_PART varchar(100) ='',@IS_RESERVOIR_LINE char(2) ='0',
		@FAULT_RESET_BARCODE VARCHAR(100) = '',@IsScanFGCoupledBarcode char(2)=0

		SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
		SELECT @OpenQueryLinkServerName = LINKSERVERNAME, @OpenQueryDBName = DATABASENAME FROM ASSY_LINKSERVER_DTL WITH (NOLOCK)
		WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE


		create table #tblOPCode (Row_No int , col1 VARCHAR(150))
		SET NOCOUNT ON;

		
		create table #Temp_RoboKey (RoboKey nvarchar(2))
		Insert into #Temp_RoboKey(RoboKey)
		SELECT  ISNULL(ATTRB_VAL,'0') RoboKey from DBO.FN_GET_EXTENDED_ATTRIBUTE(@PROFITCENTERCODE,'LINE_ATTRB','ROBO_VISION_ON_OFF',@LINECODE,'','','','','')

		SELECT @FV_ROBO_BUFFER_COUNT= ISNULL(ATTRB_VAL,'0') from DBO.FN_GET_EXTENDED_ATTRIBUTE(@PROFITCENTERCODE,'LINE_ATTRB','FV_ROBO_BUFFER_COUNT',@LINECODE,'','','','','')

		IF EXISTS
		(
			SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE KeyType = 'PLC_BAR_STATUS_SHARE' AND KeyValue = '1'
			AND ProfitCenterCode = @PROFITCENTERCODE AND LineCode = @LINECODE
		)
		BEGIN
			SET @BAR_STATUS_KEY = 1
		END
		
		-- Added By Sachin 210213
		IF @CONDITION = 'SCAN_OK'
		BEGIN
			IF @PROFITCENTERCODE in ('0088','0064')
			BEGIN
					EXEC ASSY_PROC_FINALVIEWING_BIJ @CONDITION='SCAN_OK',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@MACHINECODE=@MACHINECODE
					,@OPERATIONCODE=@OPERATIONCODE,@BARCODE=@BARCODE,@USERID=@USERID
					,@STATIONCODE=@STATIONCODE,@SUBSTNMACHINECODE=@SUBSTNMACHINECODE,@SUBSTNOPERATIONCODE=@SUBSTNOPERATIONCODE,
					@P_EKanbanAllowed=@P_EKanbanAllowed,@PRNGroupCode = @PRNGroupCode,
					@P_AutoFVMachineCode = @P_AutoFVMachineCode, @P_FINALVIEWING_OPERATIONCODE = @P_FINALVIEWING_OPERATIONCODE,
					@P_FINALVIEWING_MACHINECODE = @P_FINALVIEWING_MACHINECODE,@P_LIVE_DATE_CODE  =@P_LIVE_DATE_CODE,
					@P_PREVMACHINECODE =@P_PREVMACHINECODE,@P_PREVOPERATIONCODE  = @P_PREVOPERATIONCODE,
					@P_PREVMACHINENAME  = @P_PREVMACHINENAME,@P_LINETYPE_NAME = @P_LINETYPE_NAME,@P_VALIDATE_DATECODE = @P_VALIDATE_DATECODE
					,@P_NOOFSTATIONS = @P_NOOFSTATIONS,@P_ISPOKAYOKEMANDATORY = @P_ISPOKAYOKEMANDATORY
					,@P_POKA_YOKE_ALLOWED = @P_POKA_YOKE_ALLOWED,@P_ISMATFEEDREQUIRED = @P_ISMATFEEDREQUIRED
					,@P_LABELPRINTING = @P_LABELPRINTING,@P_POKAYOKEDATECODE=@P_POKAYOKEDATECODE
					,@P_IS2PARTSFIFO=@P_IS2PARTSFIFO,@ALLOW2PARTS=@ALLOW2PARTS,@P_RECIPE=@P_RECIPE,@P_INDEXPERSTATIONS=@P_INDEXPERSTATIONS
					,@P_OPERATIONSEQNO=@P_OPERATIONSEQNO,@P_IsTorqueCapturingFromKepServer=@P_IsTorqueCapturingFromKepServer
					,@P_IsCheckParameter=@P_IsCheckParameter,@P_REWORK_VISION_COUNT = @P_REWORK_VISION_COUNT,@P_REWORK_COUNT = @P_REWORK_COUNT
					,@P_CRIMPING_MACHINECODE = @P_CRIMPING_MACHINECODE, @Assy_str = @Assy_str
					,@P_FINALVIEWING_SERVO_PERFORMANCE_MACHINECODE  = @P_FINALVIEWING_SERVO_PERFORMANCE_MACHINECODE
					,@P_BOOSTERLINE_CRIMPINGTIMELIMIT = @P_BOOSTERLINE_CRIMPINGTIMELIMIT,@P_Family_Group_Code=@P_Family_Group_Code
					,@RETURNINT=@RETURNINT OUT,@RETURNVALUE=@RETURNVALUE OUT
					RETURN
			END
			ELSE IF @PROFITCENTERCODE in ('0018','0030','0068')
			BEGIN
					EXEC ASSY_PROC_FINALVIEWING_ABS @CONDITION='SCAN_OK',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@MACHINECODE=@MACHINECODE
					,@OPERATIONCODE=@OPERATIONCODE,@BARCODE=@BARCODE,@USERID=@USERID
					,@STATIONCODE=@STATIONCODE,@SUBSTNMACHINECODE=@SUBSTNMACHINECODE,@SUBSTNOPERATIONCODE=@SUBSTNOPERATIONCODE,
					 @P_EKanbanAllowed=@P_EKanbanAllowed,@RETURNINT=@RETURNINT OUT,@RETURNVALUE=@RETURNVALUE OUT
					RETURN
			END
		END
		-- Ended By Sachin 210213


		-- ADD/COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
		--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
		SELECT @ASSY_PARTNO = ASSY_PARTNO, @PRODUCTIONORDERNO = PRODUCTIONORDERNO, @Category = Category, @NEWCUSTOMERPARTNO = CUSTOMERPARTNO
			FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
		--Added By prerna for datcode change
		Declare	@Live_Datecode char(4),@return_int int
		exec Assy_proc_datecode @PROFITCENTERCODE,@Live_Datecode out,@return_int out

		--IF EXISTS
		--(
		--	SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
		--		AND KeyType = 'IsNissanLine6' AND KeyValue = '1'
		--)
		--BEGIN
		--	SET @ISLINE6 = 1
		--END
		--ELSE
		--	SET @ISLINE6 = 0
		
		/*
		IF @LINECODE = 'P6'
		BEGIN
			SET @ISLINE6 = 1
		END
		*/

		IF @CONDITION = 'SCAN_OK'
		BEGIN

			IF EXISTS
			(
				SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE 
				AND KeyType = 'QueueTimeValidation' AND KeyValue = '1'
			)
			BEGIN
				SET @QueueTimeValidation = 1
			END

			IF (@QueueTimeValidation = 1)
			BEGIN
				 SELECT  @StationQueueTimemst=QueueTime FROM RoutingConfigPartWise WITH (NOLOCK) WHERE OperationCode=@OPERATIONCODE and
				 partno=@ASSY_PARTNO

				 SELECT  @IsReofferStn=IsReoffer FROM RoutingConfigLineWise WITH (NOLOCK) WHERE ProfitCenterCode=@PROFITCENTERCODE and OperationCode=@OPERATIONCODE and
				 LineCode=@LINECODE
				
				SELECT * INTO #ASSY_LINEQUEUETIME_RUNNING FROM ASSY_LINEQUEUETIME_RUNNING WITH (NOLOCK) 
				WHERE ProfitCenterCode=@ProfitCenterCode AND LineCode=@LineCode AND Barcode=@BARCODE
			END
			--Added by THK --in case of rework-barcode
			SELECT TOP 1 @BARCODE = ISNULL(NULLIF(Barcode,''),@BARCODE) FROM ASSY_STATUS_REWORK_LOG WITH (NOLOCK)
			WHERE ProfitCenterCode=@PROFITCENTERCODE AND Rework_Barcode=@BARCODE

			select * INTO #Assy_StatusRework_Data_Move_To_Running 
			from Assy_StatusRework_Data_Move_To_Running(nolock) where ProfitCenterCode = @ProfitCenterCode
			and LineCode = @LineCode and Barcode=@BARCODE

			--rework movement if any
			if exists(select top 1 1 from #Assy_StatusRework_Data_Move_To_Running)
			begin
					IF NOT EXISTS (select top 1 1 from #Assy_StatusRework_Data_Move_To_Running where PartNo=@ASSY_PARTNO)
					BEGIN
						SELECT TOP 1 @PARTNO = PartNo FROM #Assy_StatusRework_Data_Move_To_Running
						SET @RETURNINT = 1
						SET @RETURNVALUE = 'SCANNED BARCODE PART NUMBER (' + ISNULL(@PARTNO,'') + ') MISMATCH WITH SET PARAMETR PART NUMBER'

						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()				
						RETURN	
					END

					insert into Assy_LineAssyStatus_Running(
					ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,Status,FailCount,Datecode,PartNo,
					Active,ResultTimestamp,ScanTimestamp,UserID,IsTallyChartApproved,IsReworkPart,ProductionOrderNo,PROD_LOT_NO
					)
					select ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,Status,FailCount,@Live_Datecode,PartNo,
					Active,ResultTimestamp,ScanTimestamp,UserID,0,IsReworkPart,ProductionOrderNo,PROD_LOT_NO
					from Assy_StatusRework_Data_Move_To_Running(nolock) 
					where PROFITCENTERCODE=@ProfitCenterCode and LineCode=@LineCode 
					and PartNo=@ASSY_PARTNO and barcode=@BARCODE

					insert into Assy_LineAssyParamData_running(
					ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,
					TagName,Value,Result,Datecode,UserID,Timestamp,PartNo,UID,ScanTimeStamp
					)
					select distinct ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,
					TagName,Value,Result,@Live_Datecode,UserID,Timestamp,PartNo,UID,ScanTimeStamp
					from Assy_ParamDataRework_To_Running(nolock) 
					where PROFITCENTERCODE=@ProfitCenterCode and LineCode=@LineCode 
					and PartNo=@ASSY_PARTNO and barcode=@BARCODE

					insert into Assy_LineAssyParamData_Running_Dtl(
					[UID],[TagId],[Value])
					select distinct UID,TagId,Value from Assy_ParamDataRework_Move_To_Running_Dtl  where UID in (
					select UID from Assy_LineAssyParamData_Running(nolock) 
					where PROFITCENTERCODE=@ProfitCenterCode and LineCode=@LineCode 
					and PartNo=@ASSY_PARTNO and barcode=@BARCODE
					)

					delete from Assy_StatusRework_Data_Move_To_Running	
					where PROFITCENTERCODE=@ProfitCenterCode and LineCode=@LineCode and PartNo=@ASSY_PARTNO and barcode=@BARCODE

					delete from Assy_ParamDataRework_To_Running	
					where PROFITCENTERCODE=@ProfitCenterCode and LineCode=@LineCode and PartNo=@ASSY_PARTNO and barcode=@BARCODE
							
					delete from Assy_ParamDataRework_Move_To_Running_Dtl  where UID in (
					select UID from Assy_LineAssyParamData_Running(nolock) 
					where PROFITCENTERCODE=@ProfitCenterCode and LineCode=@LineCode 
					and PartNo=@ASSY_PARTNO and barcode=@BARCODE
					)

			end

			SET @ISLINE6 = 0
			SELECT @PRNGroupCode = ISNULL(PGM.GroupCode,'')
				FROM Assy_PRN_CustomerGroupMaster PCGM (NOLOCK)
			INNER JOIN Assy_PRN_GroupMaster PGM (NOLOCK)
				ON PCGM.GroupCode = PGM.GroupCode
			WHERE PCGM.PartNo = @ASSY_PARTNO AND PCGM.CustomerPartNo = @NewCustomerPartNo

			SELECT @IsScanFGCoupledBarcode=  keyvalue from RoutingConfigDetails where ProfitCenterCode=@ProfitCenterCode and  KeyType='IsScanFGCoupledBarcode_'+@PRNGroupCode and LineCode=@LINECODE
			IF @PRNGroupCode IN ('GC_AL','GC_VW','GC_PSA')
			BEGIN
				SELECT @IsScanCustomerPartValidation = dbo.FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE(@ProfitCenterCode,'PART_ATTRB','IS_CUST_BARCODE_SCAN_VALIDATION',@ASSY_PARTNO,'')
				IF (@IsScanCustomerPartValidation = 1)
				BEGIN
					IF EXISTS (SELECT 1 FROM Assy_CustomerBarcode_Scan_Validation (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND Barcode = @BARCODE)
					BEGIN
						--UPDATE INCORRECT LABEL
						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
							, @BARCODE = @BARCODE, @HMIMESSAGE = 'Customer Barcode scan validation pending at coupling.'
						END
						SET @RETURNINT = 1
						SET @RETURNVALUE = 'Customer Barcode scan validation pending at coupling.'

						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'COUPLING_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
						RETURN
					END
				END
			END
			ELSE IF @PRNGroupCode = 'GC_TML'
			BEGIN
				IF EXISTS (SELECT 1 FROM Assy_FinalViewing_RFID_Barcode_Mapping (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @BARCODE)
				BEGIN
					--Declare @NBarcode VARCHAR(100) = ''
					SELECT @NBarcode = BARCODE FROM Assy_FinalViewing_RFID_Barcode_Mapping (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @BARCODE
					SET @BARCODE = @NBarcode
				END
			END
			ELSE IF @PRNGroupCode IN ('GC_DUSTER_LINE_6_7','GC_NISSAN_LINE_6_7')
			BEGIN
				SET @ISLINE6 = 1
			END

			SELECT @IS_RESERVOIR_LINE =  DBO.[FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE](@ProfitCenterCode,'LINE_ATTRB','IS_RESERVOIR_LINE',@LineCode,'')		   
			If (isnull(@IS_RESERVOIR_LINE,'0') ='1')   AND @BARCODE  not like '%PKYK%'
			Begin
				Insert into #tblOPCode(Row_No, col1)
			    SELECT Row_No, col1   FROM dbo.FN_GRID_SPLIT_STRING(DBO.[FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE](@ProfitCenterCode,'LINE_ATTRB','RESERVOIR_OPERATION_CODE',@LINECODE,''),'','|')
				IF EXISTS (SELECT 1 FROM #tblOPCode WHERE Col1 = @OperationCode)
				BEGIN
						SELECT @GET_RESERVOIR_PART=  DBO.[FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE](@ProfitCenterCode,'PART_ATTRB','RESERVOIR_PART_NUMBER',@ASSY_PARTNO,'')
						If (isnull(@GET_RESERVOIR_PART,'') <> '')
						Begin
							SELECT @FAULT_RESET_BARCODE = DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', @LINECODE, 'FAULT_RESET_BARCODE', @PROFITCENTERCODE)
							IF(@BARCODE = isnull(@FAULT_RESET_BARCODE,''))
							BEGIN
									DELETE from Assy_CustomerBarcode_Scan_Validation where LineCode=@LINECODE and ProfitCenterCode=@PROFITCENTERCODE and GroupCode='RESERVOIR'  
									AND OperationCode = @OperationCode
									SET @RETURNINT = 1
									SET @RETURNVALUE = 'BARCODES_RESET_SUCCESSFULLY_SCAN_RESERVOIR_BARCODE'
									INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
									SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()				
									RETURN
							END
							IF EXISTS (SELECT 1 FROM Assy_CustomerBarcode_Scan_Validation WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
							AND OperationCode=@OperationCode AND ISNULL(BARCODE,'') <> '' AND  ISNULL(CustomerBarcode,'') <> '')
							BEGIN
								 
							      SET @RETURNINT = 1
									SET @RETURNVALUE = 'BARCODES ALREADY SCANNED, WAITING FOR PASS'
									INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
									SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()				
									RETURN

							END

							IF (CHARINDEX(@GET_RESERVOIR_PART, @BARCODE) <> 0)   
							BEGIN
								IF NOT EXISTS (SELECT 1 FROM Assy_CustomerBarcode_Scan_Validation WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
								AND OperationCode=@OperationCode AND ISNULL(BARCODE,'')= '')
								BEGIN
									IF NOT EXISTS (SELECT 1 FROM Assy_TS_Reservoir_Barcode_Mapping(NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
									 AND LineCode = @LineCode AND ReservoirBarCode= @BARCODE AND  IsMapped = 0)
									BEGIN
										SET @EXECQUERY = ''
										SET @EXECQUERY = 'SELECT * FROM OPENQUERY(' + @OpenQueryLinkServerName + ',''SELECT ReservoirBarCode  FROM ' + @OpenQueryDBName + '.dbo.Assy_TS_Reservoir_Barcode_Mapping WITH(NOLOCK)
											WHERE PROFITCENTERCODE = ''''' + @PROFITCENTERCODE + '''''
											AND ReservoirBarCode = ''''' + @BARCODE + ''''' '')';

										INSERT INTO @Table_Variable(DataStatus)
										EXEC (@EXECQUERY)
										IF EXISTS (SELECT 1 FROM @Table_Variable)
										BEGIN

											SET @RETURNINT = 1
											SET @RETURNVALUE = 'SCANNED BARCODE ALREADY MAPPED IN ANOTHER LINE'
											INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
											SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()				
											RETURN	

										END

										PRINT @OPERATIONCODE
										UPDATE Assy_Scan_OK SET Barcode='' , isScan='' WHERE operationcode = @OPERATIONCODE
									    DELETE FROM Assy_CustomerBarcode_Scan_Validation WHERE  OperationCode = @OPERATIONCODE and  GroupCode='RESERVOIR'
									   	PRINT @OPERATIONCODE
									
										INSERT INTO Assy_CustomerBarcode_Scan_Validation(ProfitCenterCode,LineCode,GroupCode,Barcode,CustomerBarcode,CreatedTimestamp,ModifiedTimestamp,OperationCode)
										SELECT @ProfitCenterCode,@LineCode,'RESERVOIR','',@BARCODE,GETDATE(),GETDATE(),@OPERATIONCODE
										SET @RETURNINT = 1
										SET @RETURNVALUE = 'RESERVOIR_BARCODE_SCANNED_SUCCESSFULLY'
										INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
										SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
										RETURN
									END
									ELSE
									BEGIN
										SET @RETURNINT = 1
										SET @RETURNVALUE = 'SCANNED BARCODE ALREADY MAPPED'
										INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
										SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()				
										RETURN	
									END
								END
								ELSE
								BEGIN						
									SET @RETURNINT = 1
									SET @RETURNVALUE = 'RESERVOIR BARCODE ALREADY SCANNED, PLEASE SCAN TS BARCODE'
									INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
									SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()				
									RETURN
								END
							END
							ELSE
							BEGIN			
								IF NOT EXISTS (SELECT 1 FROM Assy_CustomerBarcode_Scan_Validation WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
								AND OperationCode=@OperationCode)
								BEGIN
										if(CHARINDEX(@LINECODE, @BARCODE) <> 0)
										Begin
											SET @RETURNINT = 1
											SET @RETURNVALUE = 'Please Scan Reservoir Barcode before Scanning TS Barcode'
											RETURN
										End
										Else
										Begin
											SET @RETURNINT = 1
											SET @RETURNVALUE = 'Scan Correct Reservoir Barcode'
											RETURN

										End
									
								END
							END
						End
							
				END

			END
				/*
			--Waki Customer Barcode Data - Added By RS On 20180828 For Waki Non-Mahindra Logic
			IF EXISTS
			(
				SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
					AND KeyType = 'WakiLogic' AND KeyValue = '1'
			)
			BEGIN
				IF EXISTS (SELECT 1 FROM Assy_FinalViewing_RFID_Barcode_Mapping (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @BARCODE)
				BEGIN
					Declare @NBarcode VARCHAR(100) = ''
					SELECT @NBarcode = BARCODE FROM Assy_FinalViewing_RFID_Barcode_Mapping (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @BARCODE
					SET @BARCODE = @NBarcode
				END
			END
			*/

			--Added By RS On 20180202 for rerun the transaction which is victim of Deadlock
			RETRYONDEADLOCK: -- Label RETRY
			-- commented By Sachin 210213
			--IF @PROFITCENTERCODE in ('0088','0064')
			--BEGIN
			--		EXEC ASSY_PROC_FINALVIEWING_BIJ @CONDITION='SCAN_OK',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@MACHINECODE=@MACHINECODE
			--		,@OPERATIONCODE=@OPERATIONCODE,@BARCODE=@BARCODE,@USERID=@USERID
			--		,@STATIONCODE=@STATIONCODE,@SUBSTNMACHINECODE=@SUBSTNMACHINECODE,@SUBSTNOPERATIONCODE=@SUBSTNOPERATIONCODE,
			--		@P_EKanbanAllowed=@P_EKanbanAllowed,@RETURNINT=@RETURNINT OUT,@RETURNVALUE=@RETURNVALUE OUT
			--		RETURN
			--END
			--ELSE IF @PROFITCENTERCODE in ('0018','0030','0068')
			--BEGIN
			--		EXEC ASSY_PROC_FINALVIEWING_ABS @CONDITION='SCAN_OK',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@MACHINECODE=@MACHINECODE
			--		,@OPERATIONCODE=@OPERATIONCODE,@BARCODE=@BARCODE,@USERID=@USERID
			--		,@STATIONCODE=@STATIONCODE,@SUBSTNMACHINECODE=@SUBSTNMACHINECODE,@SUBSTNOPERATIONCODE=@SUBSTNOPERATIONCODE,
			--		 @P_EKanbanAllowed=@P_EKanbanAllowed,@RETURNINT=@RETURNINT OUT,@RETURNVALUE=@RETURNVALUE OUT
			--		RETURN
			--END
			-- commented Ended By Sachin 210213
			BEGIN TRAN
			BEGIN TRY
			IF @FIRSTEXECUTE = 1
			BEGIN
				SELECT 1 FROM ASSY_LINEASSYSTATUS (NOLOCK)
				SELECT 1 FROM ASSY_TALLYCHARTSTATUSDATA_HISTORY (NOLOCK)
				COMMIT TRAN
				RETURN
			END
			--GET FINAL VIEWING OPERATION CODE FROM LINE CODE
			SELECT  @FINALVIEWING_OPERATIONCODE = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)
			-- IF USER ID IS NULL OR BLANK ADDED BY RASHID ON 06 JAN 2016
			IF(ISNULL(@USERID, '') = '')
			BEGIN
				SELECT TOP 1 @USERID = CREATEDBY FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
			END
			-- BORE OIL BYPASS BARCODE ADDED BY RASHID ON 21ST DEC 2016
			IF (ISNULL(@LINECODE,'') != '' AND ISNULL(@BARCODE,'') != '' AND (@OPERATIONCODE != @FINALVIEWING_OPERATIONCODE))
			BEGIN
				DECLARE @CLEVIS_BYPASS_TORQUE_BARCODE VARCHAR(100) = '', @BOREOIL_BYPASS_BARCODE VARCHAR(100) = '', @LASTPART_BYPASS_BARCODE VARCHAR(100) = '',
				
						@BSTATUS_BYPASS_BARCODE BIT = 0
				
				SELECT @CLEVIS_BYPASS_TORQUE_BARCODE = DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', @LINECODE, 'REAPPLY_CLEVIS_TORQUE_BARCODE', @PROFITCENTERCODE)

				SELECT @BOREOIL_BYPASS_BARCODE = DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'FSLINES', 'REAPPLY_BOREOIL_BARCODE', @PROFITCENTERCODE)
				
				SELECT @LASTPART_BYPASS_BARCODE = DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'ALLLINES', 'REAPPLY_LASTPART_BARCODE', @PROFITCENTERCODE)
				
				
						
				IF (@BARCODE = ISNULL(@CLEVIS_BYPASS_TORQUE_BARCODE, ''))
				BEGIN
					SELECT @RETURNVALUE = 'SCANNED_OK_TORQUE_APPLY', @BSTATUS_BYPASS_BARCODE = 1
				END
				ELSE IF (@BARCODE = ISNULL(@BOREOIL_BYPASS_BARCODE, ''))
				BEGIN
					SELECT @RETURNVALUE = 'SCANNED_OK_BORE_OIL_APPLY', @BSTATUS_BYPASS_BARCODE = 1
				END
				ELSE IF (@BARCODE = ISNULL(@LASTPART_BYPASS_BARCODE, ''))
				BEGIN
					SELECT @RETURNVALUE = 'SCANNED_OK_LAST_PART', @BSTATUS_BYPASS_BARCODE = 1
				END
				ELSE
				BEGIN
					SET @BSTATUS_BYPASS_BARCODE = 0
				END

				IF (ISNULL(@BSTATUS_BYPASS_BARCODE, 0) = 1)
				BEGIN
					IF EXISTS
					(
						SELECT 1 FROM ASSY_SCAN_OK (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE
					)
					BEGIN
						UPDATE ASSY_SCAN_OK SET ISSCAN = 1, BARCODE = @BARCODE WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE
					END
					ELSE
					BEGIN
						INSERT INTO ASSY_SCAN_OK(LINECODE, OPERATIONCODE, STATIONCODE, BARCODE, ISSCAN, MACHINECODE)
						SELECT @LINECODE, @OPERATIONCODE, 1, @BARCODE, 1, @MACHINECODE
					END

					--BAR_STATUS --3 dummy
					IF @BAR_STATUS_KEY = 1
					BEGIN
						insert into Barcode_Status_Time (Barcode, BAR_STATUS, LineCode, MachineCode, OperationCode, DateCode, EntStamp, UpdateStamp)
						values (@Barcode, 3, @LineCode, @MachineCode, @OperationCode, @DateCode, getdate(), getdate())
					END

					--RESET   INCORRECT LABEL
					UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE = '', ISINCORRECT = 0 WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE

					--RESET DUPLICATE LABEL
					UPDATE ASSY_DUPLICATELABEL SET ISDUPLICATE = 0 WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
						
					SET @RETURNINT = 1

					INSERT INTO ASSY_SCAN_OK_WITHOUT_ACTUAL_BARCODE(LINECODE, OPERATIONCODE, BARCODE, USERID, REMARK)
					SELECT @LINECODE, @OPERATIONCODE, @BARCODE, @USERID, @RETURNVALUE
					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

					COMMIT TRAN
					RETURN
				END

				
			END

			SELECT @REWORK_DATECODE = DATECODE, @REWORK_MODE = RTRIM(ASSY_MODE), @REWORK_CURRENT_PLANQTY = CURRENTPLANNEDQTY, @REWORK_ORDERNO = PRODUCTIONORDERNO, @Category = Category
				FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

			-- Print on DPM Scanning -- Starting Fixed Characters -- Added By RS On 06-Mar-2019
			IF EXISTS
			(
				SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND OperationCode = @OperationCode
					AND MachineCode = @MachineCode	AND KeyType = 'IsPrintOnScan' AND KeyValue = '1'
			)
			BEGIN
				SELECT @FixedDPMStartingCharacters = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
					AND KeyType = 'PrintOnScanBarcodeFixedCharacters'

				SELECT @FixedDPMStartingCharactersLength = LEN(@FixedDPMStartingCharacters)
				IF LEFT(@BARCODE,@FixedDPMStartingCharactersLength) = @FixedDPMStartingCharacters
				BEGIN	
				--------------------------Added by Prerna for Ekanban Print Stop for 			
					IF EXISTS(SELECT TOP 1 1 FROM TYPE_DEFINITION_XREF_DATA(NOLOCK)
					WHERE ATTRB_CD=@LineCode AND TYPE_CATEGORY_CD='LINE_ATTRB'
					AND TYPE_CD='eKanban_Enable' AND WH_CODE=@ProfitCenterCode AND ATTRB_VAL='1')
					BEGIN
							IF @REWORK_DATECODE != @DateCode AND ISNULL(@REWORK_DATECODE,'') != ''
							BEGIN
								If Exists(select top 1 1 from assy_runningkanban where ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
								and IsRunning='1' and PartNo=@ASSY_PARTNO )
								Begin
									set @DateCode=@REWORK_DATECODE
								End
							END
					End
					IF @REWORK_DATECODE = @DateCode AND ISNULL(@REWORK_DATECODE,'') != ''
					BEGIN
						IF EXISTS (SELECT 1 FROM Assy_TS_Bracket_Barcode_Mapping(NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND IsMapped = 0)
						BEGIN
							UPDATE Assy_TS_Bracket_Barcode_Mapping SET Timestamp = GETDATE(), BracketBarCode = @BARCODE, SignalMachineCode = @MachineCode
								WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND IsMapped = 0
						END
						ELSE
						BEGIN
							INSERT INTO Assy_TS_Bracket_Barcode_Mapping(ProfitCenterCode,LineCode,SignalMachineCode,BracketBarCode,IsMapped,Timestamp)
							SELECT @ProfitCenterCode,@LineCode,@MachineCode,@BARCODE,0,GETDATE()
						END

						EXEC ASSY_Proc_STROKING_PRINTSIGNAL @Condition = 'UPDATE', @ProfitCenterCode = @ProfitCenterCode, @LineCode = @LineCode, @MachineCode = @MachineCode
						
						SET @RETURNVALUE = 'SCAN_PRINT_SIGNAL'
						SET @RETURNINT = 1
						
						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
						COMMIT TRAN
						RETURN
					END
					ELSE
					BEGIN
						SET @RETURNINT = 1
						SET @RETURNVALUE = 'DATE_CODE_CHANGE_PRINT_SIGNAL_REJECT'
						
						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
						COMMIT TRAN
						RETURN
					END
				END
			END
			-- Print on DPM Scanner -- Starting Fixed Characters -- Added By RS On 06-Mar-2019

			-- Print on BV Validation and Vision Pass -- Added By RS On 24-May-2019
			IF EXISTS
			(
				SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
					AND KeyType = 'IsBoreViewingMixUpRequired' AND KeyValue = '1'
			)
			BEGIN
				SELECT @MixUpOperationCode = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
					AND KeyType = 'MixUpOperationCode'
				
				IF @MixUpOperationCode = @OperationCode
				BEGIN
					IF @REWORK_DATECODE = @DateCode AND ISNULL(@REWORK_DATECODE,'') != ''
					BEGIN
						SELECT @MachiningPartNo = LabelDataValue FROM Assy_Coupling_LabelInfo_Mst (NOLOCK)
							WHERE ProfitCenterCode = @ProfitCenterCode AND PartNo = @ASSY_PARTNO AND LabelDataName = 'BV_MachinePartNo' AND IsActive = 1

						IF @MachiningPartNo != LEFT(@BARCODE,4)
						BEGIN
							SET @RETURNINT = 1
							SET @RETURNVALUE = 'SCANNED_BARCODE_MACHINE_PART_NO_MISMATCH'

							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							COMMIT TRAN
							RETURN
						END

						----CHECK FOR WIP LIMIT
						EXEC ASSY_PROC_WIP_MANAGE  @CONDITION = 'VALIDATE_WIP', @LINECODE = @LINECODE, @MACHINECODE = @MACHINECODE, @BARCODE = @BARCODE, @PROFITCENTERCODE = @PROFITCENTERCODE
						,@RETURNVALUE = @RETURNVALUE1 OUT, @RETURNINT = @RETURNINT1 OUT
			
						IF @RETURNVALUE1 = 'WIP_LIMIT_HAS_REACHED'
						BEGIN							
							SELECT @RETURNINT = 1, @RETURNVALUE = 'WIP_LIMIT_HAS_REACHED'
				
							--UPDATE INCORRECT LABEL
							IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
							BEGIN
								EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
								, @BARCODE = @BARCODE, @HMIMESSAGE = 'WIP_LIMIT_HAS_REACHED'
							END
							-- SCANNING LOG BY RS ON 20170913
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

							COMMIT TRAN
							RETURN
						END

						/* Local Validation required after using sync method - change request by Mr. Prasath
						SET @EXECQUERY = ''
						SET @EXECQUERY = 'SELECT TOP 1 ISNULL(Barcode,''''), ISNULL(Status,''''), ISNULL(IsMapped,0), ISNULL(IsLocked,0) FROM ' + @LINKSERVERNAME + '.DBO.Assy_BoreInspection_Result
							WHERE Barcode = ''' + @BARCODE + ''''
						PRINT @EXECQUERY
						
						INSERT INTO @Assy_Bore_Inspection_Result(Barcode, Status, IsMapped, IsLocked)
						EXEC (@EXECQUERY)
						*/

						INSERT INTO @Assy_Bore_Inspection_Result(Barcode, Status, IsMapped, IsLocked)
						SELECT TOP 1 ISNULL(Barcode,''''), ISNULL(Status,''''), ISNULL(IsMapped,0), ISNULL(IsLocked,0) FROM Assy_BoreInspection_Result (NOLOCK)	WHERE Barcode = @BARCODE

						IF NOT EXISTS (SELECT 1 FROM @Assy_Bore_Inspection_Result)
						BEGIN
							SET @RETURNVALUE = 'BARCODE_NOT_TESTED_ON_BI_STATION'
							SET @RETURNINT = 1
					
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							COMMIT TRAN
							RETURN
						END

						SELECT @BI_BARCODE = ISNULL(Barcode,''), @BI_STATUS = ISNULL(Status,''), @BI_IsMapped = IsMapped, @BI_IsLocked = IsLocked
							FROM @Assy_Bore_Inspection_Result

						IF @BI_IsMapped = 1
						BEGIN
							SET @RETURNVALUE = 'BARCODE_ALREADY_MAPPED_BI_STATION'
							SET @RETURNINT = 1
					
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							COMMIT TRAN
							RETURN
						END

						IF @BI_STATUS != 'PS'
						BEGIN
							SET @RETURNVALUE = 'BARCODE_FAILED_ON_BI_STATION'
							SET @RETURNINT = 1
					
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							COMMIT TRAN
							RETURN
						END

						IF @BI_IsLocked = 1
						BEGIN
							SET @RETURNVALUE = 'BARCODE_IS_LOCKED_BI_STATION'
							SET @RETURNINT = 1
					
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							COMMIT TRAN
							RETURN
						END

						IF EXISTS (SELECT 1 FROM Assy_TS_Bracket_Barcode_Mapping (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND BracketBarcode = @BARCODE AND IsMapped = 1)
						BEGIN
							SET @RETURNVALUE = 'BARCODE_ALREADY_MAPPED_BI_STATION'
							SET @RETURNINT = 1
					
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							COMMIT TRAN
							RETURN
						END

						SELECT * INTO #Assy_TS_NonTS_Barcode_Scan_Validation FROM Assy_TS_NonTS_Barcode_Scan (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode

						IF EXISTS(SELECT 1 FROM #Assy_TS_NonTS_Barcode_Scan_Validation WHERE Barcode = @BARCODE)
						BEGIN
							-- Reinsert if same Barcode is scanned
							DELETE FROM Assy_TS_NonTS_Barcode_Scan

							INSERT INTO Assy_TS_NonTS_Barcode_Scan(ProfitCenterCode,LineCode,SignalMachineCode,DateCode,Barcode,IsMapped,ScanTimeStamp,Scan_By)
							SELECT @ProfitCenterCode,@LineCode,@MachineCode,@DateCode,@BARCODE,0,GETDATE(),@USERID

							SET @RETURNVALUE = 'RE_BORE_VIEWING_MIXUP_SIGNAL'
							SET @RETURNINT = 1
					
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							COMMIT TRAN
							RETURN
						END
						ELSE IF EXISTS(SELECT 1 FROM #Assy_TS_NonTS_Barcode_Scan_Validation WHERE Barcode != @BARCODE)
						BEGIN
							Declare @LockBarcode VARCHAR(100) = ''
							SELECT @LockBarcode = Barcode FROM #Assy_TS_NonTS_Barcode_Scan_Validation
							--Lock the Barcode in Central Server
							-- Reinsert if same Barcode is scanned
							DELETE FROM Assy_TS_NonTS_Barcode_Scan

							INSERT INTO Assy_TS_NonTS_Barcode_Scan(ProfitCenterCode,LineCode,SignalMachineCode,DateCode,Barcode,IsMapped,ScanTimeStamp,Scan_By)
							SELECT @ProfitCenterCode,@LineCode,@MachineCode,@DateCode,@BARCODE,0,GETDATE(),@USERID

							SET @RETURNVALUE = 'LOCK_PREV_BARCODE_AND_GIVE_BORE_VIEWING_MIXUP_SIGNAL'
							SET @RETURNINT = 1
					
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @LockBarcode + '-' + @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

							-- Local Update after sync
							UPDATE Assy_BoreInspection_Result SET IsLocked = 1, LockedTimeStamp = GETDATE() WHERE Barcode = @LockBarcode
							COMMIT TRAN

							--Lock the Barcode in Central Server
							SET @EXECQUERY = ''

							SET @EXECQUERY = 'Update openquery(' + @OpenQueryLinkServerName + ',''Select IsLocked,LockedTimeStamp,Barcode From Assy_BoreInspection_Result'')
							Set IsLocked = 1, LockedTimeStamp = GETDATE() Where WHERE Barcode = ''' + @LockBarcode + ''''
							--SET @EXECQUERY = 'UPDATE ' + @LINKSERVERNAME + '.DBO.Assy_BoreInspection_Result SET IsLocked = 1, LockedTimeStamp = GETDATE() WHERE Barcode = ''' + @LockBarcode + ''''
							PRINT @EXECQUERY
							EXEC (@EXECQUERY)
							RETURN
						END
						ELSE
						BEGIN
							INSERT INTO Assy_TS_NonTS_Barcode_Scan(ProfitCenterCode,LineCode,SignalMachineCode,DateCode,Barcode,IsMapped,ScanTimeStamp,Scan_By)
							SELECT @ProfitCenterCode,@LineCode,@MachineCode,@DateCode,@BARCODE,0,GETDATE(),@USERID

							SET @RETURNVALUE = 'BORE_VIEWING_MIXUP_SIGNAL'
							SET @RETURNINT = 1
					
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							COMMIT TRAN
							RETURN
						END

						--IF EXISTS (SELECT 1 FROM Assy_TS_NonTS_Barcode_Scan (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND Barcode = @BARCODE AND IsMapped = 0)
						--BEGIN
							
						--	INSERT INTO Assy_TS_NonTS_Barcode_Scan(ProfitCenterCode,LineCode,SignalMachineCode,DateCode,Barcode,IsMapped,ScanTimeStamp,Scan_By)
						--	SELECT @ProfitCenterCode,@LineCode,@MachineCode,@DateCode,@BARCODE,0,GETDATE(),@USERID

						--	SET @RETURNVALUE = 'BORE_VIEWING_MIXUP_SIGNAL'
						--	SET @RETURNINT = 1
					
						--	INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						--	SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
						--	COMMIT TRAN
						--	RETURN
						--END
						--ELSE
						--BEGIN
						--	INSERT INTO Assy_TS_NonTS_Barcode_Scan(ProfitCenterCode,LineCode,SignalMachineCode,DateCode,Barcode,IsMapped,ScanTimeStamp,Scan_By)
						--	SELECT @ProfitCenterCode,@LineCode,@MachineCode,@DateCode,@BARCODE,0,GETDATE(),@USERID
						--	/*
						--	INSERT INTO Assy_TS_Non_TS_Barcode_Mapping(ProfitCenterCode,LineCode,SignalMachineCode,NonTSBarCode,IsMapped,Timestamp)
						--	SELECT @ProfitCenterCode,@LineCode,@MachineCode,@BARCODE,0,GETDATE()
						--	*/
						--END

						--SET @RETURNVALUE = 'BORE_VIEWING_MIXUP_SIGNAL'
						--SET @RETURNINT = 1
					
						--INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						--SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
						--COMMIT TRAN
						--RETURN
					END
					ELSE
					BEGIN
						SET @RETURNINT = 1
						SET @RETURNVALUE = 'DATE_CODE_CHANGE_PRINT_SIGNAL_REJECT'
						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
						COMMIT TRAN
						RETURN
					END
				END

				IF EXISTS
				(
					SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE KeyType = 'IsBoreViewingValidationRequiredAtFV' AND KeyValue = '1'
						AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
				)
				BEGIN
					DECLARE @MixUpMachineCode VARCHAR(20) = NULL
					SELECT @MixUpMachineCode = dbo.Assy_fnGetMachineCodeFromOperationCode(@MixUpOperationCode,@LINECODE)

					DECLARE @NextMachineCode VARCHAR(20) = NULL, @NextOperationCode  VARCHAR(20) = NULL
					EXEC Assy_Proc_Get_Next_MachineCode @LineCode = @LINECODE, @MachineCode = @MixUpMachineCode, @PartNumber = @ASSY_PARTNO, @NextMachineCode = @NextMachineCode OUTPUT
					--SELECT @NextMachineCode
				
					IF @NextMachineCode = @MACHINECODE
					BEGIN
						IF NOT EXISTS (SELECT 1 FROM Assy_FV_BoreView_Mapping_Status (NOLOCK) WHERE OperationCode = @OperationCode AND ISNULL(Barcode,'') != '')
						BEGIN
							IF EXISTS (SELECT 1 FROM Assy_BoreInspection_Result (NOLOCK) WHERE Barcode = @Barcode AND IsMapped = 1 AND ProfitCenterCode = @ProfitCenterCode)
							BEGIN
								IF EXISTS (SELECT 1 FROM Assy_FV_BoreView_Mapping_Status WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND OperationCode = @OPERATIONCODE)
								BEGIN
									UPDATE Assy_FV_BoreView_Mapping_Status SET Barcode = @Barcode, MappingStatus = 1, TimeStamp = GETDATE(), TSBarcode = ''
										WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND OperationCode = @OPERATIONCODE
								END
								ELSE
								BEGIN
									INSERT INTO Assy_FV_BoreView_Mapping_Status(ProfitCenterCode,LineCode,Barcode,TSBarcode,MappingStatus,TimeStamp,MachineCode,OperationCode)
									SELECT @ProfitCenterCode,@LineCode,@Barcode,'',1,GETDATE(),@MACHINECODE,@OPERATIONCODE
								END
								SET @RETURNINT = 1
								SET @RETURNVALUE = 'SCANNED_SUCCESSFULLY_BORE_MIX_UP'

								INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
								SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

								COMMIT TRAN
								RETURN
							END
							ELSE
							BEGIN
								SELECT @RETURNINT = 1, @RETURNVALUE = 'SCAN_BORE_VIEWING_MIXUP_QRCODE'
								--UPDATE INCORRECT LABEL
								IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
								BEGIN
									EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
									, @BARCODE = @BARCODE, @HMIMESSAGE = 'SCAN_BORE_VIEWING_MIXUP_QRCODE'
								END

								INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
								SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

								COMMIT TRAN
								RETURN
							END
						END
					END
				END
			END
			-- Print on BV Validation and Vision Pass -- Added By RS On 24-May-2019

			--SELECT @REWORK_DATECODE = DATECODE, @REWORK_MODE = RTRIM(ASSY_MODE), @REWORK_CURRENT_PLANQTY = CURRENTPLANNEDQTY, @REWORK_ORDERNO = PRODUCTIONORDERNO
			--	FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
					
			SELECT @REWORK_CURRENT_PLANQTY = CURRENTPLANNEDQTY FROM ASSY_BARCODE_PRINTED_COUNTER WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
			--Add here and commented below -- add By RS On 20180112
			SELECT @POKAYOKEDATECODE = DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'POKAYOKE', 'POKAYOKE_DATECODE', @PROFITCENTERCODE)

			SELECT @IsDirServoScanPart = dbo.FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE(@PROFITCENTERCODE,'PART_ATTRB','IS_DIR_SERVO_SCAN_PART',@ASSY_PARTNO,'')
			IF @IsDirServoScanPart = 1
			BEGIN
				SELECT @MachineConfigValue = dbo.FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE(@PROFITCENTERCODE,'LINE_ATTRB','DIR_SERVO_SCAN_MACHINE_CODE',@LINECODE,'')
				IF @MachineConfigValue = @MACHINECODE
				BEGIN
					SET @IsImportBarcodeAllowed = 1
				END
			END
			ELSE IF EXISTS
			(
				SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
					AND KeyType = 'IsImportBarcodeAllowed' AND KeyValue = '1'
			)
			BEGIN
				SET @IsImportBarcodeAllowed = 1
			END

			--PokaYoke Barcode will not go into below block. So Add CHARINDEX('PKYK', @BARCODE) = 0) By RS On 20180112
			IF ((CHARINDEX(':', @BARCODE) <> 0 OR (ISNULL(@ISLINE6, 0) = 1 or (isnull(@IsScanFGCoupledBarcode,'0')='1' 
			AND CHARINDEX(@LINECODE, @BARCODE) = 0 )) AND (CHARINDEX(@ASSY_PARTNO, @BARCODE) <> 0
			or (isnull(@IsScanFGCoupledBarcode,'0')='1' AND CHARINDEX(@LINECODE, @BARCODE) = 0))
			AND CHARINDEX(@POKAYOKEDATECODE, @BARCODE) = 0)) AND ISNULL(@BARCODE, '') <> '' 
			BEGIN
				SELECT @LINECODE_STMC = ISNULL(LINECODE, ''), @DATECODE_TEMP = ISNULL(DATECODE, '')  FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) 
					WHERE  PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE  AND BARCODE = @BARCODE  
				
				SELECT @DATECODE = @DATECODE_TEMP, @ISSTMC = 1
						
				IF(@LINECODE_STMC) <> ''
				BEGIN
					-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
					-- SELECT DISTINCT @PARTNUMBER = ISNULL(STMC_PART_NO, ''), @DATECODE = DATECODE FROM ASSY_COUPLINGDETAILS (NOLOCK)
					SELECT @PARTNUMBER = ISNULL(STMC_PART_NO, ''), @DATECODE = DATECODE FROM ASSY_COUPLINGDETAILS (NOLOCK)
						WHERE FG_BARCODE = @BARCODE AND LINECODE = @LINECODE AND PROFITCENTRECODE = @PROFITCENTERCODE
				END
				ELSE
				BEGIN
					-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
					-- SELECT DISTINCT @PARTNUMBER = ISNULL(STMC_PART_NO, ''), @LINECODE_STMC = LINECODE, @DATECODE = DATECODE FROM ASSY_COUPLINGDETAILS (NOLOCK) 
					SELECT @PARTNUMBER = ISNULL(STMC_PART_NO, ''), @LINECODE_STMC = LINECODE, @DATECODE = DATECODE FROM ASSY_COUPLINGDETAILS (NOLOCK) 
						WHERE FG_BARCODE = @BARCODE AND LINECODE = @LINECODE AND PROFITCENTRECODE = @PROFITCENTERCODE
				END

				IF ISNULL(@PARTNUMBER, '') = ''
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'SCAN_ONLY_VALID_BARCODE'
					
					--UPDATE INCORRECT LABEL
					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
						, @BARCODE = @BARCODE, @HMIMESSAGE = 'SCAN_ONLY_VALID_BARCODE'
					END
					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

					COMMIT TRAN
					RETURN
				END
			END
			ELSE IF @ISSTMC = 0 AND ISNULL(@BARCODE, '') <> '' 
			BEGIN
				--Added BY RS Waki---
				IF @IsImportBarcodeAllowed = 1
				BEGIN
					Declare @NewPREVMACHINECODE VARCHAR(50) = '', @FirstStationMachineCode VARCHAR(50) = '', @FirstStationOperationCode VARCHAR(50) = ''
					SELECT @FirstStationMachineCode = MachineCode, @FirstStationOperationCode = OperationCode FROM RoutingConfigLineWise (NOLOCK)
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND OperationSeqNo = 1
					
					IF NOT EXISTS (SELECT 1 FROM ASSY_VISION_SYSTEM WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND BARCODE = @BARCODE)
					BEGIN
						SELECT Row_No, col1 INTO #tblPRNGroup FROM dbo.FN_GRID_SPLIT_STRING(dbo.FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE(@PROFITCENTERCODE,'LINE_ATTRB','CHECK_BTMC_COMBINATION_GROUP_WISE',@LINECODE,''),'','|')

						IF EXISTS (SELECT 1 FROM #tblPRNGroup WHERE Col1 = @PRNGroupCode)
						BEGIN
							Create Table #CheckBarcode
							(
								Barcode VARCHAR(50)
							)

							INSERT INTO #CheckBarcode(Barcode)
							SELECT Barcode FROM Assy_LineAssyStatus_Running (NOLOCK)
								WHERE ProfitCenterCode = @PROFITCENTERCODE AND LineCode = @LINECODE AND DateCode = @REWORK_DATECODE
							AND MachineCode = @FirstStationMachineCode

							IF EXISTS
							(
								SELECT 1 FROM #CheckBarcode WHERE LEFT(RIGHT(Barcode,6),4) = LEFT(RIGHT(@BARCODE,6),4)
							)
							BEGIN
								SET @RETURNVALUE = 'SAME_COMBINATION_SERVO_BARCODE_ALREADY_PRINTED_CONSUME_THIS_PART_IN_ANOTHER_SHIFT'
								SET @RETURNINT = 1

								IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
								BEGIN
									EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
									, @BARCODE = @BARCODE, @HMIMESSAGE = 'SAME_COMBINATION_BTMC_BARCODE_ALREADY_PRINTED_CONSUME_THIS_PART_IN_ANOTHER_SHIFT'
								END

								INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
								SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN-MANUAL_INSERT', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
								COMMIT TRAN
								RETURN
							END

							INSERT INTO #CheckBarcode(Barcode)
							SELECT Barcode FROM Assy_LineAssyStatus (NOLOCK)
								WHERE ProfitCenterCode = @PROFITCENTERCODE AND LineCode = @LINECODE AND DateCode = @REWORK_DATECODE
							AND MachineCode = @FirstStationMachineCode

							IF EXISTS
							(
								SELECT 1 FROM #CheckBarcode WHERE LEFT(RIGHT(Barcode,6),4) = LEFT(RIGHT(@BARCODE,6),4)
							)
							BEGIN
								SET @RETURNVALUE = 'SAME_COMBINATION_SERVO_BARCODE_ALREADY_PRINTED_CONSUME_THIS_PART_IN_ANOTHER_SHIFT'
								SET @RETURNINT = 1

								IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
								BEGIN
									EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
									, @BARCODE = @BARCODE, @HMIMESSAGE = 'SAME_COMBINATION_BTMC_BARCODE_ALREADY_PRINTED_CONSUME_THIS_PART_IN_ANOTHER_SHIFT'
								END

								INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
								SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN-MANUAL_INSERT', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
								COMMIT TRAN
								RETURN
							END

							SELECT 1 FROM Assy_CouplingDetails (NOLOCK) WHERE ProfitCentreCode = @PROFITCENTERCODE AND LineCode = @LINECODE AND DateCode = @REWORK_DATECODE

							IF EXISTS
							(
								SELECT 1 FROM Assy_CouplingDetails (NOLOCK) WHERE ProfitCentreCode = @PROFITCENTERCODE AND LineCode = @LINECODE AND DateCode = @REWORK_DATECODE
									AND RIGHT(FG_Barcode,4) = LEFT(RIGHT(@BARCODE,6),4)
							)
							BEGIN
								SET @RETURNVALUE = 'SAME_COMBINATION_BTMC_BARCODE_ALREADY_PRINTED_CONSUME_THIS_PART_IN_ANOTHER_SHIFT'
								SET @RETURNINT = 1

								IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
								BEGIN
									EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
									, @BARCODE = @BARCODE, @HMIMESSAGE = 'SAME_COMBINATION_BTMC_BARCODE_ALREADY_PRINTED_CONSUME_THIS_PART_IN_ANOTHER_SHIFT'
								END

								INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
								SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN-MANUAL_INSERT', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
								COMMIT TRAN
								RETURN
							END
						END
					END

					EXEC ASSY_PROC_GET_PREVIOUS_MACHINECODE @LINECODE = @LINECODE, @MACHINECODE = @MACHINECODE, @PARTNUMBER = @ASSY_PARTNO
					, @PREVMACHINECODE = @NewPREVMACHINECODE OUTPUT

					IF (@NewPREVMACHINECODE = @FirstStationMachineCode)
					BEGIN
						IF CHARINDEX(@LINECODE,@BARCODE) > 0
						BEGIN
							SET @RETURNVALUE = 'SERVO_PART_PRODUCED_FROM_SAME_LINE_IS_NOT_ALLOWED'
							SET @RETURNINT = 1

							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN-MANUAL_INSERT', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							COMMIT TRAN
							RETURN
						END
						--Start-- Check Set Parameter Part Count scanned before accepting scanning allow -- Added By Rashid On 17-July-2020
						SET @ReturnValue = ''
						EXEC Assy_Proc_Barcode_Printed_Counter @LineCode = @LINECODE, @ProfitCenterCode = @PROFITCENTERCODE, @CONDITION = 'IS_PLANNED_QTY_REACHED',
							@ReturnValue = @ReturnValue OUTPUT

						IF @ReturnValue = 'Yes'
						BEGIN
							SELECT @RETURNINT = 1, @RETURNVALUE = 'Barcode cannot be scanned since Planned Quantity has been reached.'
					
							--UPDATE INCORRECT LABEL
							IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
							BEGIN
								EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
								, @BARCODE = @BARCODE, @HMIMESSAGE = 'Barcode cannot be scanned since Planned Quantity has been reached.'
							END

							-- SCANNING LOG BY RS ON 20170913
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN-MANUAL_INSERT', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							COMMIT TRAN
							RETURN
						END
						--End---- Check Set Parameter Part Count scanned before accepting scanning allow -- Added By Rashid On 17-July-2020
						IF NOT EXISTS (SELECT 1 FROM ASSY_VISION_SYSTEM WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND BARCODE = @BARCODE)
						BEGIN
							IF NOT EXISTS (SELECT 1 FROM ASSY_Vision_System_History WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND BARCODE = @BARCODE)
							BEGIN
								IF CHARINDEX(':', @BARCODE) = 0 OR (ISNULL(@ISLINE6, 0) = 0 AND CHARINDEX(@ASSY_PARTNO, @BARCODE) = 0)
								BEGIN
									Declare @V_PartNo VARCHAR(20) = '', @V_Serial_No VARCHAR(8) = '', @Barcode_PartNo VARCHAR(20) = '', @bPartStatus BIT = 0
									SELECT @V_PartNo = Servo_PartNo FROM Assy_RunningPart (NOLOCK)  WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
									IF LEN(@BARCODE) = 22
									BEGIN
										SET @Barcode_PartNo = LEFT(@BARCODE,8)
										SET @V_Serial_No = LEFT(RIGHT(@BARCODE,10),8)
										IF @Barcode_PartNo != @V_PartNo
										BEGIN
											SET @bPartStatus = 1
										END
									END
									ELSE IF LEN(@BARCODE) = 23
									BEGIN
										SET @Barcode_PartNo = LEFT(@BARCODE,9)
										SET @V_Serial_No = LEFT(RIGHT(@BARCODE,10),8)
										IF @Barcode_PartNo != @V_PartNo
										BEGIN
											SET @bPartStatus = 1
										END
									END
									ELSE
										SET @bPartStatus = 1

									IF @bPartStatus = 1
									BEGIN
										SELECT @RETURNINT = 1, @RETURNVALUE = 'NOT_RUNNING_PART'
					
										--UPDATE INCORRECT LABEL
										IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
										BEGIN
											EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
											, @BARCODE = @BARCODE, @HMIMESSAGE = 'NOT_RUNNING_PART'
										END

										-- SCANNING LOG BY RS ON 20170913
										INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
										SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN-MANUAL_INSERT', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
										COMMIT TRAN
										RETURN
									END

									IF (UPPER(LEFT(RIGHT(@BARCODE,10),1)) != 'M')
									BEGIN
										SELECT @IsServoFV_Validation = dbo.FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE(@PROFITCENTERCODE,'LINE_ATTRB','IS_SERVO_FV_VALIDATION',@LINECODE,'')
										IF @IsServoFV_Validation = 1
										BEGIN
											SET @LINECODE_OF_BARCODE = RIGHT(@BARCODE,2)
											SELECT @FV_MachineCode = DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE','FINALVIEWING','SERVO_QCStation_MachineCode',@PROFITCENTERCODE)

											SET @EXECQUERY = ''
											SET @EXECQUERY = 'SELECT * FROM OPENQUERY(' + @OpenQueryLinkServerName + ',''SELECT Status FROM ' + @OpenQueryDBName + '.dbo.ASSY_LINEASSYSTATUS WITH (NOLOCK)
												WHERE LINECODE = ''''' + @LINECODE_OF_BARCODE + ''''' AND PROFITCENTERCODE = ''''' + @PROFITCENTERCODE + '''''
												AND MACHINECODE = ''''' + @FV_MachineCode + ''''' AND BARCODE = ''''' + @BARCODE + ''''' '')';

											INSERT INTO @Table_Variable(DataStatus)
											EXEC (@EXECQUERY)
				
											IF NOT EXISTS (SELECT 1 FROM @Table_Variable)
											BEGIN
												SET @RETURNVALUE = 'SERVO_PART_IS_NOT_FOUND_IN_CENTRAL_SERVER'
												SET @RETURNINT = 1
												INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
												SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
												COMMIT TRAN
												RETURN
											END

											IF ((SELECT DataStatus FROM @Table_Variable) = 'FL')
											BEGIN
												SET @RETURNVALUE = 'SERVO_PART_IS_FAILED_IN_CENTRAL_SERVER'
												SET @RETURNINT = 1
												INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
												SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
												COMMIT TRAN
												RETURN
											END

											IF ((SELECT ISNULL(DataStatus,'') FROM @Table_Variable) != 'PS')
											BEGIN
												SET @RETURNVALUE = 'SERVO_PART_IS_NOT_PASSED_IN_CENTRAL_SERVER'
												SET @RETURNINT = 1
												INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
												SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
												COMMIT TRAN
												RETURN
											END
										END
									END

									--Start--Added By RS On 05-Sep-2020 For a Barcode Packing Validation From Central Server
									SET @EXECQUERY = ''
									SET @EXECQUERY = 'SELECT * FROM OPENQUERY(' + @OpenQueryLinkServerName + ',''SELECT PARTBARCODE FROM ' + @OpenQueryDBName + '.dbo.SKIDBARCODEDETAIL WITH (NOLOCK)
											WHERE WH_CODE = ''''' + @PROFITCENTERCODE + ''''' AND PARTBARCODE = ''''' + @BARCODE + ''''' '' )';

									INSERT INTO @Table_Variable(DataStatus)
									EXEC (@EXECQUERY)
				
									IF EXISTS (SELECT 1 FROM @Table_Variable)
									BEGIN
										SET @RETURNVALUE = 'SERVO_PART_ALREADY_PACKED_IN_PACKAGING_CAN_NOT_SCAN'
										SET @RETURNINT = 1

										INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
										SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
										COMMIT TRAN
										RETURN
									END
									--End--Added By RS On 05-Sep-2020 For a Barcode Packing Validation From Central Server

									INSERT INTO ASSY_VISION_SYSTEM(PROFITCENTERCODE, LINECODE, BARCODE, TIMESTAMP, DATECODE, PARTNO, SERIALNO, ISREWORK)
									SELECT @PROFITCENTERCODE, @LINECODE, @BARCODE, GETDATE(), @REWORK_DATECODE, @V_PartNo,@V_Serial_No, 0

									UPDATE ASSY_RUNNINGPART  SET PRINTEDQTY = ISNULL(PRINTEDQTY, 0) + 1 WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

									IF NOT EXISTS
									(
										SELECT 1 FROM ASSY_BARCODE_PRINTED_COUNTER WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
										AND DATECODE = @REWORK_DATECODE 
										--AND PRODUCTIONORDERNO = @REWORK_ORDERNO 
										AND PARTNO = @ASSY_PARTNO
									)
									BEGIN
										IF CHARINDEX(':', @BARCODE) = 0 OR (ISNULL(@ISLINE6, 0) = 0 AND CHARINDEX(@ASSY_PARTNO, @BARCODE) = 0)
										BEGIN
											INSERT INTO ASSY_BARCODE_PRINTED_COUNTER(PROFITCENTERCODE, LINECODE, DATECODE, PRODUCTIONORDERNO, PARTNO, CURRENTPLANNEDQTY, PRINTEDQTY, TIMESTAMP)
											SELECT @PROFITCENTERCODE, @LINECODE, @REWORK_DATECODE, @REWORK_ORDERNO, @ASSY_PARTNO,
												@REWORK_CURRENT_PLANQTY, 1, GETDATE()
										END
									END
									ELSE
									BEGIN
										IF CHARINDEX(':', @BARCODE) = 0 OR (ISNULL(@ISLINE6, 0) = 0 AND CHARINDEX(@ASSY_PARTNO, @BARCODE) = 0)
										BEGIN
											UPDATE ASSY_BARCODE_PRINTED_COUNTER SET PRINTEDQTY = PRINTEDQTY + 1 WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
												AND DATECODE = @REWORK_DATECODE 
												--AND PRODUCTIONORDERNO = @REWORK_ORDERNO 
												AND PARTNO = @ASSY_PARTNO
										END
									END

									INSERT INTO ASSY_LINEASSYSTATUS_RUNNING(PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE, BARCODE, DATECODE, PARTNO, ACTIVE, 
											STATIONCODE, SCANTIMESTAMP, USERID, STATUS, RESULTTIMESTAMP, PRODUCTIONORDERNO,Category,Live_datecode)
									SELECT @PROFITCENTERCODE, @LINECODE, @FirstStationMachineCode, @FirstStationOperationCode, @BARCODE, @REWORK_DATECODE, 
									@ASSY_PARTNO, 1, 1, GETDATE(), @USERID, 'PS', GETDATE(), @REWORK_ORDERNO, @Category,@Live_Datecode

									INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
									SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN-MANUAL_INSERT', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
								END
							END
							ELSE
							BEGIN
								SELECT @RETURNINT = 1, @RETURNVALUE = 'BARCODE_IS_PROCESSED_VS_HISTORY'
					
								--UPDATE INCORRECT LABEL
								IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
								BEGIN
									EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
									, @BARCODE = @BARCODE, @HMIMESSAGE = 'BARCODE_IS_PROCESSED_VS_HISTORY'
								END
								-- SCANNING LOG BY RS ON 20170913
								INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
								SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

								COMMIT TRAN
								RETURN
							END
						END
					END
				END

				--Added BY RS Waki---
				--GET DATECODE AND PART NO OF SNANNED BARCODE FROM VISION SYSTEM
				SELECT @PARTNUMBER = PARTNO, @DATECODETEMP = DATECODE FROM ASSY_FN_GET_BARCODEPARTS_FROM_BARCODE(@PROFITCENTERCODE, @LINECODE, @BARCODE)							
				SET @DATECODE = @DATECODETEMP
				--ADDED BY RASHID ON 13TH JAN 2017
				IF @REWORK_DATECODE != @DATECODE
				BEGIN
					SET @DATECODE = @REWORK_DATECODE
				END
			END
			--GET FINAL VIEWING OPERATION CODE FROM LINE CODE
			--SELECT  @FINALVIEWING_OPERATIONCODE = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)
			--Commented From here and add above By RS On 20180112
			--SELECT @POKAYOKEDATECODE = DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'POKAYOKE', 'POKAYOKE_DATECODE', @PROFITCENTERCODE)
			--CHECK SCANNED BARCODE IS A VALID BARCODE OR NOT							
			IF NOT EXISTS
			(  
				SELECT 1 FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
			)
			BEGIN
				SELECT @RETURNINT = 1, @RETURNVALUE = 'PART_HAS_NOT_BEEN_SELECTED_AT_SET_PARAMETER_SCREEN'				
				
				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'PART_HAS_NOT_BEEN_SELECTED_AT_SET_PARAMETER_SCREEN'
				END

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
				COMMIT TRAN
				RETURN
			END
			IF NOT EXISTS
			(  
				SELECT 1 FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE AND ASSY_MODE IN ('PRODUCTION', 'REWORK') AND PROFITCENTERCODE = @PROFITCENTERCODE
			)
			BEGIN
				SELECT @RETURNINT = 1, @RETURNVALUE = 'PART_HAS_BEEN_SELECTED_BUT_MODE_IS_NOT_PRODUCTION_REWORK'
				
				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'PART_HAS_BEEN_SELECTED_BUT_MODE_IS_NOT_PRODUCTION_REWORK'
				END
				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				COMMIT TRAN
				RETURN
			END

			IF ISNULL(@PARTNUMBER, '') = '' AND @ISSTMC = 0 
			BEGIN					       
				IF CHARINDEX(@POKAYOKEDATECODE, @BARCODE) = 0	
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'SCAN_ONLY_VALID_BARCODE'						
					
					--UPDATE INCORRECT LABEL
					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
						, @BARCODE = @BARCODE, @HMIMESSAGE = 'SCAN_ONLY_VALID_BARCODE'
					END
					
					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
					COMMIT TRAN
					RETURN
				END
				ELSE IF CHARINDEX(@POKAYOKEDATECODE, @BARCODE) > 0
				BEGIN
					IF NOT EXISTS
					(
						SELECT 1 FROM ASSY_POKAYOKE (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND  BARCODE = @BARCODE
					)
					BEGIN
						SELECT @RETURNINT = 1, @RETURNVALUE = 'THIS_POKA_YOKE_IS_NOT_DEFINE_IN_POKA_YOKE_MASTER'
						
						--UPDATE INCORRECT LABEL
						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
							, @BARCODE = @BARCODE, @HMIMESSAGE = 'THIS_POKA_YOKE_IS_NOT_DEFINE_IN_POKA_YOKE_MASTER'
						END
							
						-- SCANNING LOG BY RS ON 20170913
						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
						COMMIT TRAN
						RETURN
					END
					--GET POKA YOKE  PART NO AND DATE CODE						  
					SELECT @PARTNUMBER = PARTNUMBER, @DATECODE = DATECODE FROM ASSY_POKAYOKE (NOLOCK) 
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND  BARCODE = @BARCODE
				END
			END

			IF(@ISSTMC = 1)
			BEGIN
				IF(ISNULL(@LINECODE_STMC, '') <> @LINECODE)
				BEGIN
					--Waki--
					IF @IsImportBarcodeAllowed = 1
					BEGIN
						PRINT 'No Need to Check'
					END
					ELSE
					BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'BARCODE_HAVING_DIFFERENT_LINE_CODE'
					
					--UPDATE INCORRECT LABEL
					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
						, @BARCODE = @BARCODE, @HMIMESSAGE = 'BARCODE_HAVING_DIFFERENT_LINE_CODE'
					END
					
					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
					COMMIT TRAN
					RETURN
					END
				END
			END
			ELSE
			BEGIN
				IF @IsImportBarcodeAllowed = 1
				BEGIN
					PRINT 'No Need to Check'
				END
				ELSE
				BEGIN
					--CHECK SCANNED BARCODE HAVING CORRECT LINE CODE OR NOT
					IF CHARINDEX(@LINECODE, @BARCODE) = 0
					BEGIN
						SELECT @RETURNINT = 1, @RETURNVALUE = 'BARCODE_HAVING_DIFFERENT_LINE_CODE'
					
						--UPDATE INCORRECT LABEL
						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
							, @BARCODE = @BARCODE, @HMIMESSAGE = 'BARCODE_HAVING_DIFFERENT_LINE_CODE'
						END
					
						-- SCANNING LOG BY RS ON 20170913
						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
						COMMIT TRAN
						RETURN
					END
				END
			END
			-- CHECK IF POKA YOKA MANDATORY
			DECLARE @ISPOKAYOKECOMPLETED BIT
			
			IF (SELECT ISNULL(ISPOKAYOKEMANDATORY, 0) FROM LINEMST (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE) = 1
			BEGIN
				IF  EXISTS
				(
					SELECT 1 FROM ROUTINGCONFIGLINEWISE (NOLOCK) L
						WHERE L.LINECODE = @LINECODE AND ISNULL(L.POKA_YOKE_ALLOWED, 0) = 1 AND ISNULL(L.TRACEABILITY, 0) = 1 AND L.MACHINECODE = @MACHINECODE
							AND L.PROFITCENTERCODE = @PROFITCENTERCODE
				)
				BEGIN
					IF NOT EXISTS
					(	
						SELECT ISNULL(ISPOKAYOKECOMPLETED, 0) FROM ASSY_SCAN_OK (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE
					)
					BEGIN
						if not exists
						(
								select 1  from Assy_PokaYoke_Last_Tested_Part with(nolock) where ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode
								and MachineCode=@MachineCode  and OperationCode=@OperationCode and PartNo=@ASSY_PARTNO and isPokaYokeCompleted='1'
						)
						Begin
							IF CHARINDEX(@POKAYOKEDATECODE, @BARCODE) = 0						
							BEGIN
								SELECT @RETURNINT = 1, @RETURNVALUE = 'POKAYOKE_NOT_DONE'
							
								IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
								BEGIN
									EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
									, @BARCODE = @BARCODE, @HMIMESSAGE = 'POKAYOKE_NOT_DONE'
								END
								
								-- SCANNING LOG BY RS ON 20170913
								INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
								SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
								COMMIT TRAN
								RETURN
							END
						End
					END

					SELECT @ISPOKAYOKECOMPLETED = ISNULL(ISPOKAYOKECOMPLETED, 0) FROM ASSY_SCAN_OK (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE

					IF CHARINDEX(@POKAYOKEDATECODE, @BARCODE) <> 0
					BEGIN
						IF(@ISPOKAYOKECOMPLETED = 1 AND DBO.ASSY_FN_ISPARTTESTEDATFV_FORPOKAYOKE(@PROFITCENTERCODE, @LINECODE, @MACHINECODE, @OPERATIONCODE) = 0 )						
						BEGIN
							SELECT @RETURNINT = 1, @RETURNVALUE = 'POKAYOKE_ALREADY_DONE'
							
							IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
							BEGIN
								EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
								, @BARCODE = @BARCODE, @HMIMESSAGE = 'POKAYOKE_ALREADY_DONE'
							END

							-- SCANNING LOG BY RS ON 20170913
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							COMMIT TRAN
							RETURN
						END
					END

					IF(@ISPOKAYOKECOMPLETED = 0 AND CHARINDEX(@POKAYOKEDATECODE, @BARCODE) = 0)							
					BEGIN
						if not exists
						(
								select 1  from Assy_PokaYoke_Last_Tested_Part with(nolock) where ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode
								and MachineCode=@MachineCode  and OperationCode=@OperationCode and PartNo=@ASSY_PARTNO and isPokaYokeCompleted='1'
						)
						Begin
							SELECT @RETURNINT = 1, @RETURNVALUE = 'POKAYOKE_NOT_DONE'
						
							IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
							BEGIN
								EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
								, @BARCODE = @BARCODE, @HMIMESSAGE = 'POKAYOKE_NOT_DONE'
							END
							-- SCANNING LOG BY RS ON 20170913
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

							COMMIT TRAN
							RETURN
						END
					END
				END
			END

			--CHECK SCANNED PART IS CURENTLY RUNNING PART OR NOT
			IF EXISTS
			(		
				SELECT 1 FROM ASSY_RUNNINGPART (NOLOCK) WHERE  LINECODE = @LINECODE AND  ASSY_MODE IN ('PRODUCTION', 'REWORK')
					AND ISNULL(PARTTYPE, '') = 'STMC' AND CHARINDEX(@POKAYOKEDATECODE, @BARCODE) = 0 AND @ISSTMC = 0
			)
			BEGIN
				IF  EXISTS
				(		
					SELECT 1 FROM ASSY_RUNNINGPART (NOLOCK) WHERE  LINECODE = @LINECODE AND  ASSY_MODE IN ('PRODUCTION', 'REWORK')
						AND SERVO_PARTNO <> @PARTNUMBER AND CHARINDEX(@POKAYOKEDATECODE, @BARCODE) = 0
				)
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'NOT_RUNNING_PART'
					
					--UPDATE INCORRECT LABEL
					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
						, @BARCODE = @BARCODE, @HMIMESSAGE = 'NOT_RUNNING_PART'
					END

					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
					COMMIT TRAN
					RETURN
				END
			END
			ELSE IF  EXISTS
			(		
				SELECT 1 FROM ASSY_RUNNINGPART (NOLOCK) WHERE  LINECODE = @LINECODE AND  ASSY_MODE IN ('PRODUCTION', 'REWORK')
					AND ASSY_PARTNO <> @PARTNUMBER AND CHARINDEX(@POKAYOKEDATECODE, @BARCODE) = 0
			)
			BEGIN
				SELECT @RETURNINT = 1, @RETURNVALUE = 'NOT_RUNNING_PART'

				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'NOT_RUNNING_PART'
				END

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
				COMMIT TRAN
				RETURN
			END
			
			--CHECK FOR JIG IN/OUT STATUS
			IF EXISTS 
			(
				SELECT 1 FROM MACHINEMST WITH (NOLOCK) WHERE MACHINECODE = @MACHINECODE  AND INDEXPERSTATIONS = 1
			)
			BEGIN
				IF EXISTS
				( 
				SELECT 1 FROM ASSY_STATIONS_ZIG_IN_OUT_STATUS (NOLOCK) WHERE LINECODE = @LINECODE  AND OPERATIONCODE = @OPERATIONCODE  AND STATUSINOUT = 1						 
				)
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'JIG_IS_INSIDE'
					
					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
					COMMIT TRAN
					RETURN
				END	
			END

			DECLARE @LINETYPE VARCHAR(20)
			DECLARE @TVLINETYPE AS TABLE
			(
				LINETYPE VARCHAR(20)
			)

			SELECT @LINETYPE = LT.LINETYPENAME FROM LINETYPEMST (NOLOCK) LT INNER JOIN LINEMST (NOLOCK) LM ON LT.LINETYPECODE = LM.LINETYPECODE WHERE LM.LINECODE = @LINECODE
			
			IF @LINETYPE = 'STMC'
			BEGIN
				INSERT INTO @TVLINETYPE(LINETYPE)
				SELECT 'SERVO' UNION SELECT 'STMC'
			END
			ELSE IF @LINETYPE = 'TMC'
			BEGIN
				INSERT INTO @TVLINETYPE(LINETYPE)
				SELECT 'TMC'
			END
			ELSE
			BEGIN
				INSERT INTO @TVLINETYPE(LINETYPE)
				SELECT @LINETYPE
			END

			--CHECK PART EXISTS IN PRODUCT MASTER

			SELECT WAREHOUSE_CD, SEWS_PART_NO, MATERIAL_TP, STS_CD INTO #PRODUCT_MASTER_FV FROM PRODUCT_MASTER (NOLOCK)
				WHERE WAREHOUSE_CD = @PROFITCENTERCODE AND SEWS_PART_NO = @PARTNUMBER

			IF NOT EXISTS
			(
				SELECT 1 FROM #PRODUCT_MASTER_FV
			)
			BEGIN
				SELECT @RETURNINT = 1, @RETURNVALUE = 'PART_DOES_NOT_EXISTS_IN_PRODUCT_MASTER'
								
				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'PART_DOES_NOT_EXISTS_IN_PRODUCT_MASTER'
				END

				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
				COMMIT TRAN									
				RETURN
			END

			--CHECK PART  ACTIVE IN PRODUCT MASTER
			IF NOT EXISTS
			(
				SELECT 1 FROM #PRODUCT_MASTER_FV WHERE STS_CD = 0
			)
			BEGIN
				SELECT @RETURNINT = 1, @RETURNVALUE = 'PART_NOT_ACTIVE_IN_PRODUCT_MASTER'

				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'PART_NOT_ACTIVE_IN_PRODUCT_MASTER'
				END
				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				COMMIT TRAN
				RETURN
			END

			--CHECK PART MATERIAL_TP IN PRODUCT MASTER
			IF NOT EXISTS
			(
				SELECT 1 FROM #PRODUCT_MASTER_FV WHERE ISNULL(MATERIAL_TP, '') IN (SELECT LINETYPE FROM @TVLINETYPE)
			)
			BEGIN
				SELECT @RETURNINT = 1, @RETURNVALUE = 'MATERIAL_TP_NOT_DEFINED_IN_PRODUCT_MASTER'

				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'MATERIAL_TP_NOT_DEFINED_IN_PRODUCT_MASTER'
				END
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				COMMIT TRAN
				RETURN
			END

			-- ADDED BY RASHID REWORK 11TH MAY 2016
			IF EXISTS
			(  
				SELECT 1 FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE AND ASSY_MODE IN ('PRODUCTION', 'REWORK')
			)
			BEGIN
				--CHECK PART HAS ALREADY PROCESSED IN TALLY  CHART
				IF EXISTS
				( 
					-- ADDED BY RASHID REWORK 11TH MAY 2016 CHANGE TABLE FROM ASSY_TALLYCHARTSTATUSDATA TO ASSY_TALLYCHARTSTATUSDATA_HISTORY
					SELECT 1 FROM ASSY_TALLYCHARTSTATUSDATA (NOLOCK) WHERE BARCODE = @BARCODE AND ISNULL(ASSY_AUTH, 0) = 0 AND ISNULL(NOTPROCESSEDSTATUS, '') <> ''
						AND LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
				)
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'PART_HAS_ALREADY_PROCESSED_IN_CURRENT_TALLYCHART'

					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
						, @BARCODE = @BARCODE, @HMIMESSAGE = 'PART_HAS_ALREADY_PROCESSED_IN_CURRENT_TALLYCHART'
					END

					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
					COMMIT TRAN
					RETURN
				END
			END

			IF CHARINDEX(@POKAYOKEDATECODE, @BARCODE) = 0
			BEGIN
				-- ADDED BY RASHID ON 14TH DEC 2016 FOR CHILD PART REJECTION APP LINKAGE IN PRODUCTION MODE --START
				DECLARE @ASSY_REJACCREWORK_HDR  TABLE
				(
					CPR_BARCODE VARCHAR(50),
					CPR_ISREWORK BIT,
					CPR_STATUS CHAR(2),
					CPR_ISASSYUSE BIT,
					REJECTIONID BIGINT
				)
				SET @EXECQUERY = ''
				SET @EXECQUERY = 'SELECT TOP 1 ISNULL(BARCODE,''''), ISNULL(ISREWORK,0), ISNULL(STATUS,''''), ISNULL(ISASSYUSE,0), REJECTIONID FROM ' + @LINKSERVERNAME + '.DBO.ASSY_REJECTIONACCOUNTINGREWORK_HDR
				WHERE BARCODE = ''' + @BARCODE + ''' ORDER BY REJECTIONID DESC'
				PRINT @EXECQUERY

				INSERT INTO @ASSY_REJACCREWORK_HDR(CPR_BARCODE, CPR_ISREWORK, CPR_STATUS, CPR_ISASSYUSE, REJECTIONID)
				EXEC (@EXECQUERY)
			
				SET @EXECQUERY = ''
				DECLARE @CPR_BARCODE VARCHAR(50) = '', @CPR_ISREWORK BIT = 0, @CPR_STATUS CHAR(2) = '', @CPR_ISASSYUSE BIT = 0, @REJECTIONID BIGINT = 0
					
				SELECT	@CPR_BARCODE = ISNULL(CPR_BARCODE,''), @CPR_ISREWORK = ISNULL(CPR_ISREWORK,0), @CPR_STATUS = ISNULL(CPR_STATUS,''), @CPR_ISASSYUSE = ISNULL(CPR_ISASSYUSE,0),
						@REJECTIONID = REJECTIONID
					FROM @ASSY_REJACCREWORK_HDR
					
				IF ISNULL(@CPR_BARCODE,'') != ''
				BEGIN
					IF ISNULL(@CPR_ISREWORK,0) = 0 AND ISNULL(@CPR_STATUS,'') != 'RW'
					BEGIN
						SELECT @RETURNINT = 1, @RETURNVALUE = 'PART_HAS_ALREADY_REJECTED_IN_CHILD_PART_REJ_APP'

						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
							, @BARCODE = @BARCODE, @HMIMESSAGE = 'PART_HAS_ALREADY_REJECTED_IN_CHILD_PART_REJ_APP'
						END	
						-- SCANNING LOG BY RS ON 20170913
						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
						COMMIT TRAN
						RETURN
					END

					IF ISNULL(@CPR_ISREWORK,0) = 1 AND ISNULL(@CPR_STATUS,'') = 'RW' AND ISNULL(@CPR_ISASSYUSE,0) = 1 AND (@OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE)
					BEGIN
						IF NOT EXISTS (SELECT 1 FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE ISNULL(ISTALLYCHARTAPPROVED,0) = 0 AND PROFITCENTERCODE = @PROFITCENTERCODE
							--MACHINE CODE COMMENT BY RASHID ON 17TH FEB 2017 HANDLING PERFORMANCE STATION CASE
							--AND LINECODE = @LINECODE AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END AND MACHINECODE = @MACHINECODE AND BARCODE = @BARCODE )
							-- Start - Added By RS On 20191021 DateCode Removed for WIP Logic
							--AND LINECODE = @LINECODE AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END AND BARCODE = @BARCODE )
							AND LINECODE = @LINECODE AND BARCODE = @BARCODE )
							-- End - Added By RS On 20191021 DateCode Removed for WIP Logic
						BEGIN
							SELECT @RETURNINT = 1, @RETURNVALUE = 'PART_HAS_ALREADY_PROCESSED_BY_ASSY_APP_CANT_REWORK'

							IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
							BEGIN
								EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
								,@BARCODE = @BARCODE, @HMIMESSAGE = 'PART_HAS_ALREADY_PROCESSED_BY_ASSY_APP_CANT_REWORK'
							END
							-- SCANNING LOG BY RS ON 20170913
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							COMMIT TRAN
							RETURN
						END
						ELSE
						BEGIN
							SET @ISCPR_APP_BARCODE_ACCEPT = 2
						END
					END
					--ELSE CASE ADD BY RASHID ON 17TH FEB 2017 HANDLING FV STATION CASE
					ELSE
					BEGIN
						SET @ISCPR_APP_BARCODE_ACCEPT = 2
					END
				END
				-- ADDED BY RASHID ON 14TH DEC 2016 FOR CHILD PART REJECTION APP LINKAGE IN PRODUCTION MODE --END
			END

			IF (@CPR_ISREWORK = 1 AND @CPR_STATUS = 'RW' AND @CPR_ISASSYUSE = 0)
			BEGIN
				SET @ISCPR_APP_BARCODE_ACCEPT = 1
			END
			ELSE
			BEGIN
				-- ADDED BY RASHID ON 14TH DEC 2016 FOR CHILD PART REJECTION APP LINKAGE AND IN PRODUCTION MODE
				IF @ISCPR_APP_BARCODE_ACCEPT != 2
				BEGIN
					IF EXISTS
					(  
						SELECT 1 FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE AND ASSY_MODE = 'PRODUCTION' AND PROFITCENTERCODE = @PROFITCENTERCODE
					)
					BEGIN
						IF EXISTS
						( 
							-- ADDED BY RASHID REWORK 11TH MAY 2016 CHANGE TABLE FROM ASSY_TALLYCHARTSTATUSDATA TO ASSY_TALLYCHARTSTATUSDATA_HISTORY
							SELECT 1 FROM ASSY_TALLYCHARTSTATUSDATA_HISTORY (NOLOCK) WHERE BARCODE = @BARCODE AND (ISNULL(ASSY_AUTH, 0) = 1 OR ISNULL(NOTPROCESSEDSTATUS, '' ) <> '')
								AND LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE AND ISNULL(ISREWORKAPPUSE, 0) = 0
						)
						BEGIN
							--ADDED BY RASHID ON 28TH APRIL 2017 HANDLING STMC REWORK BARCODE VALIDATION WHILE COUPLING
							IF NOT EXISTS
							(
								SELECT 1 FROM ASSY_STMC_REWORK_HISTORY WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND STMCBARCODE = @BARCODE
							)
							BEGIN
								SELECT @RETURNINT = 1, @RETURNVALUE = 'PART_HAS_ALREADY_PROCESSED_IN_TALLYCHART'

								IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
								BEGIN
									EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
									, @BARCODE = @BARCODE, @HMIMESSAGE = 'PART_HAS_ALREADY_PROCESSED_IN_TALLYCHART'
								END	

								-- SCANNING LOG BY RS ON 20170913
								INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
								SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
								COMMIT TRAN
								RETURN
							END
						END
					END
				END
			END

			--CHECK DATECODE VALIDATION IS  REQUIRED FOR THIS LINE OR NOT
			IF EXISTS 
			(
				SELECT 1 FROM LINEMST (NOLOCK) WHERE LINECODE = @LINECODE  AND PROFITCENTERCODE = @PROFITCENTERCODE AND ISNULL(VALIDATE_DATECODE, 0) = 1 AND ISNULL(ISACTIVE, 0) = 1
			)
			BEGIN	
				IF(@ISSTMC = 0)
				BEGIN
					IF @DATECODE <> ( SELECT TOP 1 ISNULL(DATECODE, '') FROM ASSY_DATECODE_MODE (NOLOCK) WHERE LINECODE = @LINECODE)
					BEGIN
						SELECT @RETURNINT = 1, @RETURNVALUE = 'DATE_CODE_NOT_MATCHING'

						--UPDATE INCORRECT LABEL
						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
							, @BARCODE = @BARCODE, @HMIMESSAGE = 'DATE_CODE_NOT_MATCHING'
						END

						-- SCANNING LOG BY RS ON 20170913
						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
						COMMIT TRAN
						RETURN
					END
				END

				IF @DATECODE <> (SELECT TOP 1 DATECODE FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE AND ASSY_MODE IN ('PRODUCTION', 'REWORK'))								
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'DATE_CODE_NOT_MATCHING'

					--UPDATE INCORRECT LABEL
					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
						, @BARCODE = @BARCODE, @HMIMESSAGE = 'DATE_CODE_NOT_MATCHING'
					END	
					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

					COMMIT TRAN
					RETURN
				END
			END		
			
			--CHECK A PART HAS ALREADY SCANNED ON LH AND SAME PART USER SCANS ON RH AND VICE VERSA
			IF EXISTS 
			(
				SELECT 1 FROM MACHINEMST (NOLOCK) WHERE MACHINECODE = @MACHINECODE AND ISNULL(NOOFSTATIONS, 0) > 1
			)
			BEGIN
				IF EXISTS
				(
					SELECT 1 FROM ASSY_SCAN_OK (NOLOCK) WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE <> @OPERATIONCODE AND BARCODE = @BARCODE						
				)
				BEGIN								
					DECLARE @STATIONNAME AS VARCHAR(100)
					SELECT @STATIONNAME = RTRIM(LTRIM(OPERATIONNAME)) FROM OPERATIONMST (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND OPERATIONCODE = (SELECT OPERATIONCODE  FROM ASSY_SCAN_OK (NOLOCK) WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE <> @OPERATIONCODE AND BARCODE = @BARCODE)

					SELECT @RETURNINT = 1, @RETURNVALUE = 'ALREADY_SCANNED_ON_OTHER_STATION^' + @STATIONNAME

					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
						, @BARCODE = @BARCODE, @HMIMESSAGE = 'ALREADY_SCANNED_ON_OTHER_STATION'
					END

					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
					COMMIT TRAN
					RETURN
				END
			END	
			--VALIDATE POKA YOKE-------------------------------------------------------------------------------------------------	
							
			--CHECK POKA YOKE REQUIRED FOR PARTICULAR OPERATION   -here
			IF CHARINDEX(@POKAYOKEDATECODE, @BARCODE) <> 0
			BEGIN 
				--IF POKA YOKE NOT REQUIRED FOR THIS LINE-SHOW MESSAGE TO USER	
				IF NOT EXISTS
				(						
					SELECT 1 FROM LINEMST (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE	AND LINECODE = @LINECODE AND ISNULL(ISACTIVE, 0) = 1 AND ISNULL(ISPOKAYOKEMANDATORY, 0) = 1
				)
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'POKA_YOKE_NOT_REQUIRED_FOR_THIS_LINE'
					
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'POKA_YOKE_NOT_REQUIRED_FOR_THIS_LINE'										
					
					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
					COMMIT TRAN
					RETURN
				END
				--IF POKA YOKE NOT REQUIRED FOR A PARTICULAR OPERATION IN LINE WISE ROUTNING-SHOW MESSAGE TO USER		
				IF NOT EXISTS
				(
					SELECT 1 FROM ROUTINGCONFIGLINEWISE (NOLOCK) L WHERE L.LINECODE = @LINECODE AND ISNULL(L.POKA_YOKE_ALLOWED, 0) = 1 AND ISNULL(L.TRACEABILITY, 0) = 1 
						AND L.MACHINECODE = @MACHINECODE AND L.PROFITCENTERCODE = @PROFITCENTERCODE
				)
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'POKA_YOKE_NOT_REQUIRED_FOR_THIS_MACHINE'										
					
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'POKA_YOKE_NOT_REQUIRED_FOR_THIS_MACHINE'										
					
					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
					COMMIT TRAN
					RETURN
				END
				--CHECK POKA YOKE NOT DEFINED FOR THIS MACHINE OR NOT IN ASSY_POKAYOKE
				IF NOT EXISTS
				(
					SELECT 1 FROM ASSY_POKAYOKE (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE AND MACHINECODE = @MACHINECODE AND BARCODE = @BARCODE 
				)
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'POKA_YOKE_NOT_DEFINED_FOR_THIS_MACHINE'
					
					--UPDATE INCORRECT LABEL											
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'POKA_YOKE_NOT_DEFINED_FOR_THIS_MACHINE'
					
					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
					COMMIT TRAN
					RETURN
				END
				--CHECK POKA YOKE DEFINED FOR THIS MACHINE AND ACTIVE
				IF NOT EXISTS
				(
					SELECT 1 FROM ASSY_POKAYOKE (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE AND MACHINECODE = @MACHINECODE AND BARCODE = @BARCODE 
						AND ISNULL(ISACTIVE, 0) = 1
				)
				BEGIN											
					SELECT @RETURNINT = 1, @RETURNVALUE = 'POKA_YOKE_DEFINED_BUT_NOT_ACTIVE'
					
					--UPDATE INCORRECT LABEL											
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'POKA_YOKE_DEFINED_BUT_NOT_ACTIVE'												
					
					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
					COMMIT TRAN
					RETURN
				END
				--CHECK POKA YOKE HAS BEEN EXPIRED
				IF  EXISTS
				(
					SELECT 1 FROM ASSY_POKAYOKE (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE AND MACHINECODE = @MACHINECODE AND BARCODE = @BARCODE   
						AND	CONVERT(DATE, EXPIRYDATE, 103) < CONVERT(DATE, GETDATE(), 103)
				)
				BEGIN										
					SELECT @RETURNINT = 1, @RETURNVALUE = 'POKA_YOKE_HAS_BEEN_EXPIRED'										
					
					--UPDATE INCORRECT LABEL											
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'POKA_YOKE_HAS_BEEN_EXPIRED'											
					
					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
					COMMIT TRAN
					RETURN
				END
				--CHECK GROUP HAS  DEFINED FOR SCANNED PART IN ROUTING PART WISE
				IF EXISTS
				(
					SELECT 1 FROM ROUTINGCONFIGPARTWISE (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND ISNULL(PARTNO, 0) = @PARTNUMBER AND ISNULL(PART_FIXTUREGROUPTYPE, '' ) = '' 	
				)
				BEGIN										
					SELECT @RETURNINT = 1, @RETURNVALUE = 'GROUP_HAS_NOT_DEFINED_FOR_THIS_PART_IN_PARTWISE_ROUTING'										
					
					--UPDATE INCORRECT LABEL										
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'GROUP_HAS_NOT_DEFINED_FOR_THIS_PART_IN_PARTWISE_ROUTING'
					
					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
					COMMIT TRAN
					RETURN			
				END
							  
				--CHECKING IF PART IN PRODUCTION AND SCANNED IN POKA YOKA ARE SAME
				IF NOT EXISTS
				(
					SELECT 1 FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE ASSY_PARTNO = @PARTNUMBER AND LINECODE = @LINECODE AND ASSY_MODE IN ('PRODUCTION', 'REWORK')
				)
				BEGIN
					--CHECK WHETHER SELECTED RUNNING PART AND SCANNED PART BELONGS TO SAME GROUP OR NOT.
					SELECT @PART_FIXTUREGROUPTYPE_COUNT = COUNT(PART_FIXTUREGROUPTYPE)
						FROM 
						(
							--FIND THE GROUP FOR RUNNING PART SELECTED FROM ASSY RUNNING PART TABLE.
							SELECT DISTINCT PART_FIXTUREGROUPTYPE FROM ROUTINGCONFIGPARTWISE (NOLOCK) 
								WHERE MACHINECODE = @MACHINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
									AND PARTNO IN 
										(
											SELECT ISNULL(ASSY_PARTNO, '') PARTNUMBER FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE AND ASSY_MODE IN ('PRODUCTION', 'REWORK')
										)
							UNION 
							--GET THE GROUP FOR SCANNED BARCODE FROM POKA YOKE MASTER TABLE.
							SELECT DISTINCT PART_FIXTUREGROUPTYPE FROM ROUTINGCONFIGPARTWISE (NOLOCK) WHERE MACHINECODE = @MACHINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
								AND PARTNO IN
								(
									SELECT ISNULL(PARTNUMBER, '') PARTNUMBER FROM ASSY_POKAYOKE (NOLOCK) WHERE BARCODE = @BARCODE AND MACHINECODE = @MACHINECODE
									AND PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND ISNULL(ISACTIVE, 0) = 1
								)
						)TBL
					
					IF @PART_FIXTUREGROUPTYPE_COUNT <> 1
					BEGIN
						SELECT @RETURNINT = 1, @RETURNVALUE = 'RUNNING_PART_AND_SCANNED_POKA_YOKE_DOES_NOT_BELONGS_IN_SAME_GROUP'				
						
						--UPDATE INCORRECT LABEL												
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
						, @BARCODE = @BARCODE, @HMIMESSAGE = 'RUNNING_PART_AND_SCANNED_POKA_YOKE_DOES_NOT_BELONGS_IN_SAME_GROUP'
						
						-- SCANNING LOG BY RS ON 20170913
						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
						COMMIT TRAN
						RETURN
					END
				END
				--CHECK FOR DUPLICATE LABEL 
				IF (DBO.ASSY_FN_ISPARTTESTEDATFV_FORPOKAYOKE(@PROFITCENTERCODE, @LINECODE, @MACHINECODE, @OPERATIONCODE) = 0)
				BEGIN
					IF EXISTS 
					(
						SELECT BARCODE FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND  MACHINECODE = @MACHINECODE 
						AND OPERATIONCODE = @OPERATIONCODE AND BARCODE = @BARCODE AND  ISNULL(STATUS, '') <> ''										
					)
					BEGIN
						--UPDATE ASSY_DUPLICATELABEL  TABLE
						IF EXISTS
						(
							SELECT 1 FROM ASSY_DUPLICATELABEL (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
						)
						BEGIN
							UPDATE ASSY_DUPLICATELABEL SET ISDUPLICATE = 1, BARCODE = @BARCODE  WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
							--RESET SCAN OK
	
						END
						ELSE
						BEGIN
							INSERT INTO ASSY_DUPLICATELABEL(LINECODE, OPERATIONCODE, STATIONCODE, BARCODE, ISDUPLICATE)
							SELECT @LINECODE, @OPERATIONCODE, @STATIONCODE, @BARCODE, 1
							--RESET SCAN OK

						END	
						UPDATE ASSY_SCAN_OK SET ISSCAN = 0  WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE 													   
						--RESET   INCORRECT LABEL
						UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE = '', ISINCORRECT = 0 WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE 						
						SELECT @RETURNINT = 1, @RETURNVALUE = 'THIS_POKA_YOKE_ALREADY_DONE'
						-- SCANNING LOG BY RS ON 20170913
						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

						COMMIT TRAN
						RETURN				   
					END
				END	
				--UPDATE SCAN OK RELEATED TABLE
				DECLARE @SCANNINGSTATION INT = 1
				IF EXISTS 
				(
					SELECT 1 FROM MACHINEMST WITH (NOLOCK) WHERE MACHINECODE = @MACHINECODE AND INDEXPERSTATIONS = 2
				)
				BEGIN
					
					SELECT @STATIONCODE = STATIONCODE FROM ASSY_STATIONS_ZIG_IN_OUT_STATUS (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
											
					IF @STATIONCODE = 1
						SET @SCANNINGSTATION = 2
					ELSE IF  @STATIONCODE = 2
						SET @SCANNINGSTATION = 1
																							
					SET @STATIONCODE = @SCANNINGSTATION	

					IF  EXISTS
					(
						SELECT 1 FROM ASSY_SCAN_OK (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE AND STATIONCODE = @SCANNINGSTATION
					)
					BEGIN
						UPDATE ASSY_SCAN_OK SET ISSCAN = 1, BARCODE = @BARCODE WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE AND STATIONCODE = @SCANNINGSTATION
					END
					ELSE
					BEGIN
						INSERT INTO ASSY_SCAN_OK(LINECODE, OPERATIONCODE, STATIONCODE, BARCODE, ISSCAN, MACHINECODE)
						SELECT @LINECODE, @OPERATIONCODE, @SCANNINGSTATION, @BARCODE, 1, @MACHINECODE
					END

					--RESET   INCORRECT LABEL
					UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE = '', ISINCORRECT = 0 WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE

					--RESET DUPLICATE LABEL
					UPDATE ASSY_DUPLICATELABEL SET ISDUPLICATE = 0 WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE	
				END
				ELSE IF EXISTS
				(
					SELECT 1 FROM ASSY_SCAN_OK (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE
				)
				BEGIN
					UPDATE ASSY_SCAN_OK SET ISSCAN = 1, BARCODE = @BARCODE WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE
											
	
				END
				ELSE
				BEGIN
					INSERT INTO ASSY_SCAN_OK(LINECODE, OPERATIONCODE, STATIONCODE, BARCODE, ISSCAN, MACHINECODE)
					SELECT @LINECODE, @OPERATIONCODE, @STATIONCODE, @BARCODE, 1, @MACHINECODE

			
				END

				--BAR_STATUS	--2 PY
				IF @BAR_STATUS_KEY = 1
				BEGIN
					if not exists (select top 1 1 from Barcode_Status_Time (nolock) where Barcode=@Barcode and DateCode=@Live_Datecode 
					and LineCode=@LineCode and MachineCode=@MachineCode and OperationCode=@OperationCode)
					begin
						insert into Barcode_Status_Time (Barcode, BAR_STATUS, LineCode, MachineCode, OperationCode, DateCode, EntStamp, UpdateStamp)
						values (@Barcode, 2, @LineCode, @MachineCode, @OperationCode, @Live_Datecode, getdate(), getdate())
					end
					else
					begin
						update Barcode_Status_Time set BAR_STATUS=2, UpdateStamp=getdate() where Barcode=@Barcode and DateCode=@Live_Datecode 
						and LineCode=@LineCode and MachineCode=@MachineCode and OperationCode=@OperationCode
					end
				END

				--RESET   INCORRECT LABEL
				UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE = '', ISINCORRECT = 0 WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE

				--RESET DUPLICATE LABEL
				UPDATE ASSY_DUPLICATELABEL SET ISDUPLICATE = 0 WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE

				UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE SET ISCYCLESTARTED = 0, BARCODE = @BARCODE, TIMESTAMP = GETDATE()
					WHERE  LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE

				-- INSERT INTO RUNNING PART TABLE..
				--ADDED BY SUNDARAMOORTHI S ON 22-DEC-2016	[START]
				--IF(ISNULL(@USERID, '') = '')
				--BEGIN
				--	SELECT TOP 1 @USERID = CREATEDBY FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
				--END
				--ADDED BY SUNDARAMOORTHI S ON 22-DEC-2016	[END]
				IF EXISTS
				( 
					SELECT 1 FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE  
						AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE  AND  BARCODE = @BARCODE AND ISNULL(STATUS, '') = ''
				)
				BEGIN
					UPDATE ASSY_LINEASSYSTATUS_RUNNING SET SCANTIMESTAMP = GETDATE(),Live_datecode=@Live_datecode
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE
							AND  BARCODE = @BARCODE AND ISNULL(STATUS, '') = ''
				END
				ELSE
				BEGIN									
					IF @STMCPARTNO <> ''
						SET @PARTNUMBER = @STMCPARTNO
					--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
					INSERT INTO ASSY_LINEASSYSTATUS_RUNNING(PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE, BARCODE, DATECODE, PARTNO, ACTIVE, STATIONCODE, 
						SCANTIMESTAMP, USERID, PRODUCTIONORDERNO,Category,Live_datecode)
					SELECT @PROFITCENTERCODE, @LINECODE, @MACHINECODE, @OPERATIONCODE, @BARCODE, CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END, 
						@PARTNUMBER, 0, @STATIONCODE, GETDATE(), @USERID, @REWORK_ORDERNO, @Category,@Live_datecode
				END
								
				SELECT @RETURNINT = 1, @RETURNVALUE = 'SCANNED_SUCCESSFULLY'
				
				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
				COMMIT TRAN							
				RETURN					           
			END
			--POKA YOKE END BLOCK---------------------------------

			----------CHECK A PART HAS CLEARED FROM PREVIOUS STATION
			DECLARE @PREVMACHINECODE VARCHAR(20) = NULL	
			IF EXISTS
			(
				SELECT 1 FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND ASSY_MODE IN ('PRODUCTION', 'REWORK')
					AND ISNULL(PARTTYPE, '') = 'STMC' 
			)
			BEGIN					
				SELECT @STMCPARTNO = ASSY_PARTNO FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE AND ASSY_MODE IN ('PRODUCTION', 'REWORK') AND ISNULL(PARTTYPE, '') = 'STMC' 
				
				EXEC ASSY_PROC_GET_PREVIOUS_MACHINECODE @LINECODE = @LINECODE, @MACHINECODE = @MACHINECODE, @PARTNUMBER = @STMCPARTNO
				, @PREVMACHINECODE = @PREVMACHINECODE OUTPUT
			END	
			ELSE
			BEGIN							
				EXEC ASSY_PROC_GET_PREVIOUS_MACHINECODE @LINECODE = @LINECODE, @MACHINECODE = @MACHINECODE, @PARTNUMBER = @PARTNUMBER
				, @PREVMACHINECODE = @PREVMACHINECODE OUTPUT
			END
					
			--ADD BY RASHID ON 11TH MAY 2016 FOR INSERTING PRINT BARCODE ENTRY -- ON 14TH DEC 2016 FOR CHILD PART REJECTION APP LINKAGE AND IN PRODUCTION MODE
			IF EXISTS
			(
				SELECT 1 FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND ASSY_MODE = 'REWORK'
			) OR @ISCPR_APP_BARCODE_ACCEPT = 1
			BEGIN
				DECLARE @REWORK_PARTTYPE VARCHAR(20) = '', @REWORK_PARTTYPE_CHILD VARCHAR(20) = ''
				
				SELECT @REWORK_PARTTYPE = ISNULL(PARTTYPE, ''), @REWORK_PARTTYPE_CHILD = ISNULL(SERVO_PARTNO, '') FROM ASSY_RUNNINGPART WITH (NOLOCK) 
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE --AND ASSY_MODE = 'REWORK' 
				-- ADDED BY RASHID ON 14TH DEC 2016 FOR CHILD PART REJECTION APP LINKAGE AND IN PRODUCTION MODE
				IF @ISCPR_APP_BARCODE_ACCEPT = 0
				BEGIN
					IF EXISTS
					(
						SELECT BARCODE FROM ASSY_TALLYCHARTSTATUSDATA_HISTORY WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
							 AND BARCODE = @BARCODE AND PARTNO = CASE @REWORK_PARTTYPE WHEN 'STMC' THEN @STMCPARTNO ELSE @PARTNUMBER END AND RESULT ! = 'PASS'
								 AND ISNULL(NOTPROCESSEDSTATUS, '') = 'SCRAP'
					)
					BEGIN
						SELECT @RETURNINT = 1, @RETURNVALUE = 'BARCODE_IS_ALREADY_SCRAPPED'
					
						--UPDATE INCORRECT LABEL
						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
							, @BARCODE = @BARCODE, @HMIMESSAGE = 'BARCODE_IS_ALREADY_SCRAPPED'
						END
						-- SCANNING LOG BY RS ON 20170913
						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

						COMMIT
						RETURN
					END
				END
				
				DECLARE @REWORKCOUNTDEFINED INT = 0, @REWORKVISIONCOUNT INT = 0, @REWORKFINALVIEWINGOPERATIONCODE VARCHAR(20) = '', @REWORKFIRSTSTATIONCOUNT INT = 0,
				@REWORK_FIRST_MACHINECODE VARCHAR(20) = '', @REWORK_FIRST_OPERATIONCODE VARCHAR(20) = '',
				@REWORK_SECOND_MACHINECODE VARCHAR(20) = '', @REWORK_SECOND_OPERATIONCODE VARCHAR(20) = ''
							
				SELECT @REWORK_FIRST_MACHINECODE = RTRIM(MACHINECODE), @REWORK_FIRST_OPERATIONCODE = RTRIM(OPERATIONCODE)
					FROM ROUTINGCONFIGLINEWISE WITH (NOLOCK) WHERE OPERATIONREQUIRED = 1 AND TRACEABILITY = 1 AND OPERATIONSEQNO = 1
				AND LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
				
				SELECT TOP 1 @REWORK_SECOND_MACHINECODE = RTRIM(L.MACHINECODE), @REWORK_SECOND_OPERATIONCODE = RTRIM(L.OPERATIONCODE)
					FROM ROUTINGCONFIGLINEWISE L (NOLOCK)
				INNER JOIN ROUTINGCONFIGPARTWISE P (NOLOCK)
					ON L.OPERATIONCODE = P.OPERATIONCODE AND L.MACHINECODE = P.MACHINECODE AND L.PROFITCENTERCODE = P.PROFITCENTERCODE
				WHERE	L.OPERATIONREQUIRED = 1 AND L.TRACEABILITY = 1 AND P.OPERATIONREQUIRED = 1 AND P.TRACEABILITY = 1 AND
						ISNULL(L.ENGRAVING, 0) = 0 AND ISNULL(P.ENGRAVING, 0) = 0 AND L.LINECODE = @LINECODE AND P.PARTNO = @ASSY_PARTNO
						AND L.OPERATIONSEQNO <> 1 ORDER BY L.OPERATIONSEQNO
						
				/*
				SELECT TOP 1 @REWORK_SECOND_MACHINECODE = RTRIM(MACHINECODE), @REWORK_SECOND_OPERATIONCODE = RTRIM(OPERATIONCODE)
					FROM ROUTINGCONFIGLINEWISE WITH (NOLOCK) WHERE OPERATIONREQUIRED = 1 AND TRACEABILITY = 1 AND OPERATIONSEQNO <> 1 ORDER BY OPERATIONSEQNO
				*/

				SELECT @REWORKFINALVIEWINGOPERATIONCODE = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)
							
				SELECT @REWORKFIRSTSTATIONCOUNT = COUNT(BARCODE) FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK) 
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND DATECODE = @REWORK_DATECODE AND OPERATIONCODE = @REWORK_FIRST_OPERATIONCODE
						AND ISNULL(ISTALLYCHARTAPPROVED, 0) = 0

				SELECT @REWORKFIRSTSTATIONCOUNT = @REWORKFIRSTSTATIONCOUNT + COUNT(BARCODE) FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) 
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND DATECODE = @REWORK_DATECODE AND OPERATIONCODE = @REWORK_FIRST_OPERATIONCODE
					AND ISNULL(ISTALLYCHARTAPPROVED, 0) = 0
							
				DECLARE @FG_BARCODE VARCHAR(20) = ''
				
				DECLARE @PACKAGEBARCODE  TABLE
				(
					BARCODE VARCHAR(60) NOT NULL
				)

				--SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL  WITH (NOLOCK) 
				--	WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
				
				IF @REWORK_PARTTYPE = 'STMC'
				BEGIN
					IF EXISTS(SELECT 1 FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE CHILD_BARCODE = @BARCODE)
					BEGIN
						SELECT TOP 1 @FG_BARCODE = ISNULL(FG_BARCODE, '') FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE CHILD_BARCODE = @BARCODE
					END
					ELSE IF EXISTS(SELECT 1 FROM ASSY_COUPLINGDETAILS_HISTORY WITH (NOLOCK) WHERE CHILD_BARCODE = @BARCODE)
					BEGIN
						SELECT TOP 1 @FG_BARCODE = ISNULL(FG_BARCODE, '') FROM ASSY_COUPLINGDETAILS_HISTORY WITH (NOLOCK) WHERE CHILD_BARCODE = @BARCODE
					END

					IF @FG_BARCODE ! = ''
					BEGIN
						SET @EXECQUERY = '
							SELECT PARTBARCODE FROM ' + @LINKSERVERNAME + '.DBO.SKIDBARCODEDETAIL WITH (NOLOCK) WHERE WH_CODE = ''' + @PROFITCENTERCODE + ''' AND PARTBARCODE = ''' + @FG_BARCODE + ''''
							PRINT @EXECQUERY
					END
				END
				ELSE
				BEGIN
					SET @EXECQUERY = '
						SELECT PARTBARCODE FROM ' + @LINKSERVERNAME + '.DBO.SKIDBARCODEDETAIL WITH (NOLOCK) WHERE WH_CODE = ''' + @PROFITCENTERCODE + ''' AND PARTBARCODE = ''' + @BARCODE + ''''
						PRINT @EXECQUERY
				END

				INSERT INTO @PACKAGEBARCODE(BARCODE)
				EXEC (@EXECQUERY)
				
				IF EXISTS (SELECT 1 FROM @PACKAGEBARCODE)
				BEGIN
					IF @REWORK_PARTTYPE = 'STMC'
					BEGIN
						SELECT @RETURNVALUE = 'PART_ALREADY_PACKED_FIRST_UNPACK_AND_DECOUPLE', @RETURNINT = 1
						
						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
							, @BARCODE = @BARCODE, @HMIMESSAGE = 'PART_ALREADY_PACKED_FIRST_UNPACK_AND_DECOUPLE'
						END

						DELETE FROM @PACKAGEBARCODE
						
						-- SCANNING LOG BY RS ON 20170913
						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
						COMMIT
						RETURN
					END
					ELSE
					BEGIN
						SELECT @RETURNVALUE = 'PART_ALREADY_PACKED_UNPACK_THE_PART', @RETURNINT = 1
						
						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
							, @BARCODE = @BARCODE, @HMIMESSAGE = 'PART_ALREADY_PACKED_UNPACK_THE_PART'
						END

						DELETE FROM @PACKAGEBARCODE
						-- SCANNING LOG BY RS ON 20170913
						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
						
						COMMIT
						RETURN
					END
				END

				-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
				-- SELECT @REWORKCOUNTDEFINED = CONVERT(INT, PARAMETER_VALUE) FROM PARAMETER_MST (NOLOCK) 
				-- WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'REWORK_VISION_COUNT' AND WH_CODE = @PROFITCENTERCODE
				
				SELECT @REWORKCOUNTDEFINED = CONVERT(INT,DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'REWORK_VISION_COUNT', 'REWORK_VISION_COUNT', @PROFITCENTERCODE))
					
				SELECT @REWORKVISIONCOUNT = COUNT(BARCODE) FROM ASSY_VISION_SYSTEM_HISTORY (NOLOCK) 
					WHERE BARCODE = @BARCODE AND LINECODE = @LINECODE AND ISNULL(ISREWORK, 0) = 1

				IF(@REWORKCOUNTDEFINED <= @REWORKVISIONCOUNT)
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'MAXIMUM_REWORK_ATTEMPT_REACHED'
					
					--UPDATE INCORRECT LABEL
					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
						, @BARCODE = @BARCODE, @HMIMESSAGE = 'MAXIMUM_REWORK_ATTEMPT_REACHED'
					END
					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

					COMMIT
					RETURN
				END
				--DECLARE @PRINTBARCODEMACHINECODE VARCHAR(20) = ''
				--SELECT @PRINTBARCODEMACHINECODE = DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)
				IF NOT EXISTS
				(
					SELECT 1 FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0 AND PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
						AND DATECODE = @REWORK_DATECODE AND MACHINECODE = @REWORK_FIRST_MACHINECODE AND BARCODE = @BARCODE
				)
				BEGIN
					IF @REWORK_PARTTYPE = 'STMC'
					BEGIN
						IF CHARINDEX(':', @BARCODE) <> 0 OR (ISNULL(@ISLINE6, 0) = 1 AND CHARINDEX(@ASSY_PARTNO, @BARCODE) <> 0)
						BEGIN
							--IF @OPERATIONCODE = @REWORK_SECOND_OPERATIONCODE
							IF @MACHINECODE = @REWORK_SECOND_MACHINECODE
							BEGIN
								SELECT @RETURNINT = 1, @RETURNVALUE = 'INVALID_BARCODE_COUPLED_BARCODE'
								
								--UPDATE INCORRECT LABEL
								IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
								BEGIN
									EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
									, @BARCODE = @BARCODE, @HMIMESSAGE = 'INVALID_BARCODE_COUPLED_BARCODE'
								END

								-- SCANNING LOG BY RS ON 20170913
								INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
								SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
								COMMIT
								RETURN
							END
						END

						IF EXISTS(SELECT 1 FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE CHILD_BARCODE = @BARCODE AND PROFITCENTRECODE = @PROFITCENTERCODE)
						BEGIN
							SELECT @RETURNINT = 1, @RETURNVALUE = 'BARCODE_COUPLED_DECOUPLE_FROM_STMC_REWORK'
							
							--UPDATE INCORRECT LABEL
							IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
							BEGIN
								EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
								, @BARCODE = @BARCODE, @HMIMESSAGE = 'BARCODE_COUPLED_DECOUPLE_FROM_STMC_REWORK'
							END
							-- SCANNING LOG BY RS ON 20170913
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

							COMMIT
							RETURN
						END
					END

					--IF @OPERATIONCODE = @REWORK_SECOND_OPERATIONCODE
					--IF @MACHINECODE = @REWORK_SECOND_MACHINECODE
					--BEGIN
						IF(@REWORKFIRSTSTATIONCOUNT >= @REWORK_CURRENT_PLANQTY)
						BEGIN
							SELECT @RETURNINT = 1, @RETURNVALUE = 'REWORK_PLANNED_QTY_REACHED'
							
							--UPDATE INCORRECT LABEL
							IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
							BEGIN
								EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
								, @BARCODE = @BARCODE, @HMIMESSAGE = 'REWORK_PLANNED_QTY_REACHED'
							END
							-- SCANNING LOG BY RS ON 20170913
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

							COMMIT
							RETURN
						END
					--END

					IF NOT EXISTS
					(
						SELECT 1 FROM ASSY_LINEASSYSTATUS (NOLOCK) WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0 AND PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND BARCODE = @BARCODE
					)
					BEGIN
						IF @MACHINECODE = @REWORK_SECOND_MACHINECODE
						BEGIN
							IF NOT EXISTS (SELECT 1 FROM ASSY_VISION_SYSTEM WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND BARCODE = @BARCODE)
							BEGIN
								IF CHARINDEX(':', @BARCODE) = 0 OR (ISNULL(@ISLINE6, 0) = 0 AND CHARINDEX(@ASSY_PARTNO, @BARCODE) = 0)
								BEGIN
									INSERT INTO ASSY_VISION_SYSTEM(PROFITCENTERCODE, LINECODE, BARCODE, TIMESTAMP, DATECODE, PARTNO, SERIALNO, ISREWORK)
									SELECT @PROFITCENTERCODE, @LINECODE, @BARCODE, GETDATE(), @REWORK_DATECODE, CASE @REWORK_PARTTYPE WHEN 'STMC' THEN @REWORK_PARTTYPE_CHILD ELSE @PARTNUMBER END,
										SUBSTRING(@BARCODE, LEN(CASE @REWORK_PARTTYPE WHEN 'STMC' THEN @REWORK_PARTTYPE_CHILD ELSE @PARTNUMBER END) + 5, 8), 1

									UPDATE ASSY_RUNNINGPART  SET PRINTEDQTY = ISNULL(PRINTEDQTY, 0) + 1 WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
								END
							END

							SELECT @REWORK_PRINT_QTY = ISNULL(PRINTEDQTY, 0) FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

							IF NOT EXISTS
							(
								SELECT 1 FROM ASSY_BARCODE_PRINTED_COUNTER WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
								AND DATECODE = @REWORK_DATECODE 
								--AND PRODUCTIONORDERNO = @REWORK_ORDERNO 
								AND PARTNO = CASE @REWORK_PARTTYPE WHEN 'STMC' THEN @STMCPARTNO ELSE @PARTNUMBER END
							)
							BEGIN
								IF CHARINDEX(':', @BARCODE) = 0 OR (ISNULL(@ISLINE6, 0) = 0 AND CHARINDEX(@ASSY_PARTNO, @BARCODE) = 0)
								BEGIN
									INSERT INTO ASSY_BARCODE_PRINTED_COUNTER(PROFITCENTERCODE, LINECODE, DATECODE, PRODUCTIONORDERNO, PARTNO, CURRENTPLANNEDQTY, PRINTEDQTY, TIMESTAMP)
									SELECT @PROFITCENTERCODE, @LINECODE, @REWORK_DATECODE, @REWORK_ORDERNO, CASE @REWORK_PARTTYPE WHEN 'STMC' THEN @STMCPARTNO ELSE @PARTNUMBER END,
										@REWORK_CURRENT_PLANQTY, @REWORK_PRINT_QTY, GETDATE()
								END
							END
							ELSE
							BEGIN
								IF CHARINDEX(':', @BARCODE) = 0 OR (ISNULL(@ISLINE6, 0) = 0 AND CHARINDEX(@ASSY_PARTNO, @BARCODE) = 0)
								BEGIN
									UPDATE ASSY_BARCODE_PRINTED_COUNTER SET PRINTEDQTY = @REWORK_PRINT_QTY WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
										AND DATECODE = @REWORK_DATECODE 
										--AND PRODUCTIONORDERNO = @REWORK_ORDERNO 
										AND PARTNO = CASE @REWORK_PARTTYPE WHEN 'STMC' THEN @STMCPARTNO ELSE @PARTNUMBER END
								END
							END
						
							IF CHARINDEX(':', @BARCODE) = 0 OR (ISNULL(@ISLINE6, 0) = 0 AND CHARINDEX(@ASSY_PARTNO, @BARCODE) = 0)
							BEGIN
								--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
								INSERT INTO ASSY_LINEASSYSTATUS_RUNNING(PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE, BARCODE, DATECODE, PARTNO, ACTIVE, STATIONCODE, 
								SCANTIMESTAMP, USERID, STATUS, RESULTTIMESTAMP, PRODUCTIONORDERNO,Category,Live_datecode)
								SELECT @PROFITCENTERCODE, @LINECODE, @REWORK_FIRST_MACHINECODE, @REWORK_FIRST_OPERATIONCODE, @BARCODE, @REWORK_DATECODE, 
								CASE @REWORK_PARTTYPE WHEN 'STMC' THEN @STMCPARTNO ELSE @PARTNUMBER END, 1, 1, GETDATE(), @USERID, 'PS', GETDATE(), @REWORK_ORDERNO, @Category,@Live_datecode

								--ADDED BY RASHID ON 17TH FEB 2017 HANDLING CRIMPING STATION ZIGOUT
							
									DELETE FROM ASSY_PERFORMANCE_ZIGOUTTIMESTAMP WHERE BARCODE = @BARCODE

								--ADDED BY RASHID ON 28TH APRIL 2017 HANDLING STMC REWORK BARCODE VALIDATION WHILE COUPLING
								DECLARE @STMCREWORKCOUPLINGBARCODE VARCHAR(50) = ''
								SELECT @STMCREWORKCOUPLINGBARCODE = ISNULL(STMCBARCODE,'') FROM ASSY_STMC_REWORK WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND CHILDBARCODE = @BARCODE
							
								IF ISNULL(@STMCREWORKCOUPLINGBARCODE,'') != ''
								BEGIN
									INSERT INTO ASSY_STMC_REWORK_HISTORY (PROFITCENTERCODE,LINECODE,STMCBARCODE,CHILDBARCODE,PARTTYPE,STATUS,REMARKS,ENT_BY,ENT_DT,HIS_ENT_BY,HIS_ENT_DT)
									SELECT PROFITCENTERCODE,LINECODE,STMCBARCODE,CHILDBARCODE,PARTTYPE,STATUS,REMARKS,ENT_BY,ENT_DT,ENT_BY HIS_ENT_BY,GETDATE() HIS_ENT_DT
										FROM ASSY_STMC_REWORK WHERE STMCBARCODE = @STMCREWORKCOUPLINGBARCODE AND PROFITCENTERCODE = @PROFITCENTERCODE
								
									DELETE FROM ASSY_STMC_REWORK WHERE STMCBARCODE = @STMCREWORKCOUPLINGBARCODE AND PROFITCENTERCODE = @PROFITCENTERCODE

									UPDATE ASSY_TALLYCHARTSTATUSDATA_HISTORY SET ISREWORKAPPUSE = 1 WHERE BARCODE = @STMCREWORKCOUPLINGBARCODE AND PROFITCENTERCODE = @PROFITCENTERCODE
								END 
								--ADDED BY RASHID ON 28TH APRIL 2017 HANDLING STMC REWORK BARCODE VALIDATION WHILE COUPLING

								SET @ISLINKSERVERCPRUPDATE = 1
								---- ADDED BY RASHID ON 14TH DEC 2016 FOR CHILD PART REJECTION APP LINKAGE AND IN PRODUCTION MODE
								--SET @EXECQUERY = ''
								--SET @EXECQUERY = 'UPDATE ' + @LINKSERVERNAME + '.DBO.ASSY_REJECTIONACCOUNTINGREWORK_HDR SET ISASSYUSE = 1, MODIFIEDBY = ''' + @USERID + ''', 
								--MODIFIEDON = CAST(GETDATE() AS VARCHAR) WHERE REJECTIONID = ' + CONVERT(VARCHAR(10),@REJECTIONID) +' AND BARCODE = ''' + @BARCODE +''''
								--PRINT @EXECQUERY
								--EXEC (@EXECQUERY)
								--UPDATE ASSY_REJECTIONACCOUNTINGREWORK_HDR SET ISASSYUSE = 1, MODIFIEDBY = @USERID, MODIFIEDON = GETDATE() WHERE REJECTIONID = @REJECTIONID AND BARCODE = @BARCODE
								SET @ISCPR_APP_BARCODE_ACCEPT = 0
							END

							IF EXISTS (SELECT 1 FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE BARCODE = @BARCODE AND PROFITCENTERCODE = @PROFITCENTERCODE)
							BEGIN
								INSERT INTO ASSY_LINEASSYSTATUS_HISTORY (PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE, 
								STATIONCODE, BARCODE, STATUS, FAILCOUNT, DATECODE, PARTNO, SCANTIMESTAMP, RESULTTIMESTAMP, ACTIVE, 
								USERID, ISTALLYCHARTAPPROVED, TRANSACTION_NUMBER, ISCONFIRMED, KANBAN_ID, ERP_CONF_TIMESTAMP, HIS_ENT_DT, 
								HIS_ENT_BY, ISREWORKPART,PRODUCTIONORDERNO,Category)
								SELECT PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE, STATIONCODE, BARCODE, STATUS, FAILCOUNT, DATECODE, PARTNO, 
								SCANTIMESTAMP, RESULTTIMESTAMP, ACTIVE, USERID, ISTALLYCHARTAPPROVED, TRANSACTION_NUMBER, ISCONFIRMED, KANBAN_ID, 
								ERP_CONF_TIMESTAMP, GETDATE(), @USERID, ISREWORKPART, PRODUCTIONORDERNO, @Category
								FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE BARCODE = @BARCODE

								DELETE FROM ASSY_LINEASSYSTATUS WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND BARCODE = @BARCODE
							END
									
							IF @REWORK_PARTTYPE = 'STMC'
							BEGIN
								SET @FG_BARCODE = ''
							
								IF EXISTS
								(
									SELECT 1 FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE CHILD_BARCODE = @BARCODE AND PROFITCENTRECODE = @PROFITCENTERCODE
								)
								BEGIN
									SELECT @FG_BARCODE = ISNULL(FG_BARCODE, '') FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) 
									WHERE CHILD_BARCODE = @BARCODE AND PROFITCENTRECODE = @PROFITCENTERCODE
								END
								ELSE IF EXISTS
								(
									SELECT 1 FROM ASSY_COUPLINGDETAILS_HISTORY WITH (NOLOCK) 
									WHERE CHILD_BARCODE = @BARCODE AND PROFITCENTRECODE = @PROFITCENTERCODE
								)
								BEGIN
									SELECT @FG_BARCODE = ISNULL(FG_BARCODE, '') FROM ASSY_COUPLINGDETAILS_HISTORY WITH (NOLOCK) 
									WHERE CHILD_BARCODE = @BARCODE AND PROFITCENTRECODE = @PROFITCENTERCODE
								END

								IF @FG_BARCODE ! = ''
								BEGIN
									INSERT INTO ASSY_LINEASSYSTATUS_HISTORY (PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE, 
									STATIONCODE, BARCODE, STATUS, FAILCOUNT, DATECODE, PARTNO, SCANTIMESTAMP, RESULTTIMESTAMP, ACTIVE, 
									USERID, ISTALLYCHARTAPPROVED, TRANSACTION_NUMBER, ISCONFIRMED, KANBAN_ID, ERP_CONF_TIMESTAMP, 
									HIS_ENT_DT, HIS_ENT_BY, ISREWORKPART, PRODUCTIONORDERNO,Category)
									SELECT PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE, STATIONCODE, BARCODE, STATUS, FAILCOUNT,
									DATECODE, PARTNO, SCANTIMESTAMP, RESULTTIMESTAMP, ACTIVE, USERID, ISTALLYCHARTAPPROVED, TRANSACTION_NUMBER, 
									ISCONFIRMED, KANBAN_ID, ERP_CONF_TIMESTAMP, GETDATE(), @USERID, ISREWORKPART, PRODUCTIONORDERNO, Category
									FROM ASSY_LINEASSYSTATUS WITH (NOLOCK)
									WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE 
									AND (BARCODE = @FG_BARCODE OR BARCODE = @BARCODE)

									DELETE FROM ASSY_LINEASSYSTATUS WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND (BARCODE = @FG_BARCODE OR BARCODE = @BARCODE)
								
								END
							END
						END
						ELSE
						BEGIN
							SELECT @INCORRECTMSG = 'REWORK_BARCODE_NEED_TO_BE_SCAN_NEXT_TO_PRINT_STATION'
							--UPDATE INCORRECT LABEL
							IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
							BEGIN
								EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
								, @BARCODE = @BARCODE, @HMIMESSAGE = @INCORRECTMSG
							END

							SET @RETURNINT = 1
							SET @RETURNVALUE = 'REWORK_BARCODE_NEED_TO_BE_SCAN_NEXT_TO_PRINT_STATION'
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							COMMIT TRAN

							RETURN
						END
					END
				END
			END
			--CHANGED BY RAVI ON 16-02-16
			DECLARE @SCANNEDBARCODE VARCHAR(100) = ''			

			SELECT @SCANNEDBARCODE = ISNULL(BARCODE, ''),@rework=IsReworkPart FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0 AND PROFITCENTERCODE = @PROFITCENTERCODE 
			--AND LINECODE = @LINECODE AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END AND  MACHINECODE = @PREVMACHINECODE AND BARCODE = @BARCODE
			-- Start - Added By RS On 20191021 DateCode Removed for WIP Logic
			AND LINECODE = @LINECODE AND MACHINECODE = @PREVMACHINECODE AND BARCODE = @BARCODE
			-- End - Added By RS On 20191021 DateCode Removed for WIP Logic
						
			IF @SCANNEDBARCODE = ''
			BEGIN
				SELECT @SCANNEDBARCODE = ISNULL(BARCODE, '') ,@rework=IsReworkPart FROM ASSY_LINEASSYSTATUS (NOLOCK) WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0 AND PROFITCENTERCODE = @PROFITCENTERCODE 
				-- Start - Added By RS On 20191021 DateCode Removed for WIP Logic
					--AND LINECODE = @LINECODE AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END AND  MACHINECODE = @PREVMACHINECODE AND BARCODE = @BARCODE
					AND LINECODE = @LINECODE AND MACHINECODE = @PREVMACHINECODE AND BARCODE = @BARCODE
				-- End - Added By RS On 20191021 DateCode Removed for WIP Logic
			END

			IF @SCANNEDBARCODE = ''									
			BEGIN
				-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
				-- SELECT TOP 1 @OPERATIONSEQNO = L.OPERATIONSEQNO FROM ROUTINGCONFIGLINEWISE (NOLOCK) L
				SELECT @OPERATIONSEQNO = L.OPERATIONSEQNO FROM ROUTINGCONFIGLINEWISE (NOLOCK) L
					INNER JOIN ROUTINGCONFIGPARTWISE (NOLOCK) P
						ON L.OPERATIONCODE = P.OPERATIONCODE AND L.MACHINECODE = P.MACHINECODE
							-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
							-- WHERE L.LINECODE = @LINECODE AND P.PARTNO = (SELECT TOP 1 ASSY_PARTNO  FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE ORDER BY CREATEDDATE DESC)
							WHERE L.LINECODE = @LINECODE AND P.PARTNO = @ASSY_PARTNO
								AND L.TRACEABILITY = 1 AND P.TRACEABILITY = 1
									-- ADDED BY RASHID FOR HANDLING ENGRAVING STATION ON 10TH SEP 2016
									AND ISNULL(L.ENGRAVING, 0) = 0 AND ISNULL(P.ENGRAVING, 0) = 0
										AND L.MACHINECODE = @PREVMACHINECODE AND P.MACHINECODE = @PREVMACHINECODE
						-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
						-- ORDER BY L.OPERATIONSEQNO
					 
				SELECT @LINETYPECODE = LTM.LINETYPENAME FROM LINEMST (NOLOCK) LM 
					INNER JOIN LINETYPEMST (NOLOCK) LTM 
						ON LM.LINETYPECODE = LTM.LINETYPECODE   
							WHERE LM.LINECODE = @LINECODE
							
				SELECT @INCORRECTMSG = (SELECT MACHINENAME FROM MACHINEMST (NOLOCK) WHERE MACHINECODE = @PREVMACHINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE), @RETURNVALUE = 'NOT_PROCESSED_FROM_|' + @INCORRECTMSG
													
				SELECT @INCORRECTMSG = 'NOT_PROCESSED_FROM_' + @INCORRECTMSG
				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = @INCORRECTMSG
				END

				SET @RETURNINT = 1											
				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
				COMMIT TRAN

				RETURN
			END	
			-----------------------------------------------------------
			--CHECK PART HAS BEEN ONLY SCANNED BUT NOT TESTED
			SET @SCANNEDBARCODE = ''
			
			SELECT @SCANNEDBARCODE = ISNULL(BARCODE, ''),@rework=IsReworkPart FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0 AND PROFITCENTERCODE = @PROFITCENTERCODE 
			-- Start - Added By RS On 20191021 DateCode Removed for WIP Logic
				--AND LINECODE = @LINECODE AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END AND  MACHINECODE = @PREVMACHINECODE AND BARCODE = @BARCODE AND ISNULL(STATUS, '') = ''
				AND LINECODE = @LINECODE AND MACHINECODE = @PREVMACHINECODE AND BARCODE = @BARCODE AND ISNULL(STATUS, '') = ''
			-- End - Added By RS On 20191021 DateCode Removed for WIP Logic
						
			IF @SCANNEDBARCODE = ''
			BEGIN
				SELECT @SCANNEDBARCODE = ISNULL(BARCODE, '') ,@rework=IsReworkPart FROM ASSY_LINEASSYSTATUS (NOLOCK) WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0 AND PROFITCENTERCODE = @PROFITCENTERCODE 
				-- Start - Added By RS On 20191021 DateCode Removed for WIP Logic
					--AND LINECODE = @LINECODE AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END AND  MACHINECODE = @PREVMACHINECODE AND BARCODE = @BARCODE  AND ISNULL(STATUS, '') = ''
					AND LINECODE = @LINECODE AND MACHINECODE = @PREVMACHINECODE AND BARCODE = @BARCODE AND ISNULL(STATUS, '') = ''
				-- End - Added By RS On 20191021 DateCode Removed for WIP Logic
			END

			IF @SCANNEDBARCODE <> ''
			BEGIN
				-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
				-- SELECT TOP 1 @OPERATIONSEQNO = L.OPERATIONSEQNO  FROM ROUTINGCONFIGLINEWISE (NOLOCK) L
				SELECT @OPERATIONSEQNO = L.OPERATIONSEQNO  FROM ROUTINGCONFIGLINEWISE (NOLOCK) L
					INNER JOIN ROUTINGCONFIGPARTWISE (NOLOCK) P
						ON L.OPERATIONCODE = P.OPERATIONCODE AND L.MACHINECODE = P.MACHINECODE
							-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
							--WHERE L.LINECODE = @LINECODE AND P.PARTNO = (SELECT TOP 1 ASSY_PARTNO  FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE ORDER BY CREATEDDATE DESC)
							WHERE L.LINECODE = @LINECODE AND P.PARTNO = @ASSY_PARTNO
								AND L.TRACEABILITY = 1 AND P.TRACEABILITY = 1
									-- ADDED BY RASHID FOR HANDLING ENGRAVING STATION ON 10TH SEP 2016
									AND ISNULL(L.ENGRAVING, 0) = 0 AND ISNULL(P.ENGRAVING, 0) = 0
										AND L.MACHINECODE = @PREVMACHINECODE AND P.MACHINECODE = @PREVMACHINECODE 
						-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
						-- ORDER BY L.OPERATIONSEQNO
					 
				SELECT @LINETYPECODE = LTM.LINETYPENAME  FROM LINEMST (NOLOCK) LM 
					INNER JOIN LINETYPEMST (NOLOCK) LTM 
						ON LM.LINETYPECODE = LTM.LINETYPECODE   
							WHERE LM.LINECODE = @LINECODE
							
				SELECT @INCORRECTMSG = (SELECT MACHINENAME FROM MACHINEMST (NOLOCK) WHERE MACHINECODE = @PREVMACHINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE), @RETURNVALUE = 'THIS_BARCODE_HAS_BEEN_ONLY_SCANNED_AND_NOT_TESTED_|' + @INCORRECTMSG
													
				SELECT @INCORRECTMSG = 'THIS_BARCODE_HAS_BEEN_ONLY_SCANNED_AND_NOT_TESTED_' + @INCORRECTMSG
				
				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = @INCORRECTMSG
				END
				
				SET @RETURNINT = 1
				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
				COMMIT TRAN

				RETURN
			END	
			------------------------------------------------------------------
			SET @SCANNEDBARCODE = ''
			SELECT @SCANNEDBARCODE = ISNULL(BARCODE, '') ,@rework=IsReworkPart FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0 AND PROFITCENTERCODE = @PROFITCENTERCODE 
			-- Start - Added By RS On 20191021 DateCode Removed for WIP Logic
				--AND LINECODE = @LINECODE AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END AND MACHINECODE = @PREVMACHINECODE AND BARCODE = @BARCODE AND ISNULL(STATUS, '') = 'PS'
				AND LINECODE = @LINECODE AND MACHINECODE = @PREVMACHINECODE AND BARCODE = @BARCODE AND ISNULL(STATUS, '') = 'PS'
			-- End - Added By RS On 20191021 DateCode Removed for WIP Logic
						
			IF @SCANNEDBARCODE = ''
			BEGIN
				SELECT @SCANNEDBARCODE = ISNULL(BARCODE, ''),@rework=IsReworkPart FROM ASSY_LINEASSYSTATUS (NOLOCK) WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0 AND PROFITCENTERCODE = @PROFITCENTERCODE 
				-- Start - Added By RS On 20191021 DateCode Removed for WIP Logic
					--AND LINECODE = @LINECODE AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END AND MACHINECODE = @PREVMACHINECODE AND BARCODE = @BARCODE AND ISNULL(STATUS, '') = 'PS'
					AND LINECODE = @LINECODE AND MACHINECODE = @PREVMACHINECODE AND BARCODE = @BARCODE AND ISNULL(STATUS, '') = 'PS'
				-- End - Added By RS On 20191021 DateCode Removed for WIP Logic
			END

			IF @SCANNEDBARCODE = ''
			BEGIN
				-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
				-- SELECT TOP 1 @OPERATIONSEQNO = L.OPERATIONSEQNO  FROM ROUTINGCONFIGLINEWISE (NOLOCK) L
				SELECT @OPERATIONSEQNO = L.OPERATIONSEQNO  FROM ROUTINGCONFIGLINEWISE (NOLOCK) L
					INNER JOIN ROUTINGCONFIGPARTWISE (NOLOCK) P
						ON L.OPERATIONCODE = P.OPERATIONCODE AND L.MACHINECODE = P.MACHINECODE
							-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
							--WHERE L.LINECODE = @LINECODE AND P.PARTNO = (SELECT TOP 1 ASSY_PARTNO  FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE ORDER BY CREATEDDATE DESC)
							WHERE L.LINECODE = @LINECODE AND P.PARTNO = @ASSY_PARTNO
								AND L.TRACEABILITY = 1 AND P.TRACEABILITY = 1
									-- ADDED BY RASHID FOR HANDLING ENGRAVING STATION ON 10TH SEP 2016
									AND ISNULL(L.ENGRAVING, 0) = 0 AND ISNULL(P.ENGRAVING, 0) = 0
										AND L.MACHINECODE = @PREVMACHINECODE AND P.MACHINECODE = @PREVMACHINECODE
						-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
						-- ORDER BY L.OPERATIONSEQNO
					 
				SELECT @LINETYPECODE = LTM.LINETYPENAME  FROM LINEMST (NOLOCK) LM 
					INNER JOIN LINETYPEMST (NOLOCK) LTM 
						ON LM.LINETYPECODE = LTM.LINETYPECODE   
							WHERE LM.LINECODE = @LINECODE

				SELECT @INCORRECTMSG = (SELECT MACHINENAME FROM MACHINEMST (NOLOCK) WHERE MACHINECODE = @PREVMACHINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE), @RETURNVALUE = 'NOT_CLEARED_FROM_|' + @INCORRECTMSG

				SELECT @INCORRECTMSG = 'NOT_CLEARED_FROM_' + @INCORRECTMSG
				
				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = @INCORRECTMSG
				END	
				
				SET @RETURNINT = 1
				COMMIT TRAN
				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				RETURN
			END  			
			
			--CHECK A PART HAS NO. OF TIMES FAILED-----------------------------------------------------------------OK
			SELECT @FAILCOUNTDEFINED = CONVERT(INT,DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'REWORK_COUNT', 'REWORK_COUNT', @PROFITCENTERCODE))
					
			SELECT @FAILCOUNT = ISNULL(FAILCOUNT, 0)  FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK)
				WHERE BARCODE = @BARCODE AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND ISNULL(STATUS, '') = 'FL'
			
			IF ISNULL(@FAILCOUNT,0) = 0
			BEGIN
				SELECT @FAILCOUNT = ISNULL(FAILCOUNT, 0)  FROM ASSY_LINEASSYSTATUS (NOLOCK)
					WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0 AND PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
					-- Start - Added By RS On 20191021 DateCode Removed for WIP Logic
						--AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END AND BARCODE = @BARCODE AND MACHINECODE = @MACHINECODE AND ISNULL(STATUS, '') = 'FL'
						AND BARCODE = @BARCODE AND MACHINECODE = @MACHINECODE AND ISNULL(STATUS, '') = 'FL'
					-- End - Added By RS On 20191021 DateCode Removed for WIP Logic
			END

			--BAR_STATUS
			IF @FAILCOUNT > 0 AND @BAR_STATUS_KEY = 1
			BEGIN
				SET @BAR_STATUS = 4
			END

			IF(@FAILCOUNTDEFINED <= @FAILCOUNT)
			BEGIN
				SELECT @RETURNINT = 1, @RETURNVALUE = 'MAXIMUM_FAILED_ATTEMPT_REACHED'
				
				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					-- ADDED BY RASHID ON 21ST OCT 2016 FOR HMI MESSAGE CHANGE IN CRIMPING STATION - REQUEST COME FROM MR. DINESH/PRASATH BIL
					DECLARE @CRIMPINGOPERATIONCODE VARCHAR(20) = '', @CSHELLCRIMPINGOPERATIONCODE VARCHAR(20) = ''

					SELECT @CRIMPINGOPERATIONCODE = ISNULL(LTRIM(RTRIM(DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'CRIMPING', 'OPERATIONCODE', @PROFITCENTERCODE))),'')
					SELECT @CSHELLCRIMPINGOPERATIONCODE = ISNULL(LTRIM(RTRIM(DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'CentreShellCrimping', 'OPERATIONCODE', @PROFITCENTERCODE))),'')

					IF ISNULL(@CRIMPINGOPERATIONCODE, '') = ''
						SET @CRIMPINGOPERATIONCODE = 'OCCRMP'
					IF ISNULL(@CSHELLCRIMPINGOPERATIONCODE, '') = ''
						SET @CSHELLCRIMPINGOPERATIONCODE = 'OCCSCR'
					
					--UPDATE ASSY_DUPLICATELABEL  TABLE
					IF @OPERATIONCODE = @CRIMPINGOPERATIONCODE OR @OPERATIONCODE = @CSHELLCRIMPINGOPERATIONCODE
					BEGIN
						IF NOT EXISTS
						( 
							SELECT 1 FROM ASSY_SCAN_OK (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND ISNULL(ISCYCLESTARTED, 0) = 1
						)
						BEGIN
							IF EXISTS
							(
								SELECT 1 FROM ASSY_DUPLICATELABEL (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
							)
							BEGIN
								UPDATE ASSY_DUPLICATELABEL SET ISDUPLICATE = 1, BARCODE = @BARCODE  WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
								
							END
							ELSE
							BEGIN
								INSERT INTO ASSY_DUPLICATELABEL(LINECODE, OPERATIONCODE, STATIONCODE, BARCODE, ISDUPLICATE)
								SELECT @LINECODE, @OPERATIONCODE, @STATIONCODE, @BARCODE, 1
								
							END
							--RESET SCAN OK
								UPDATE ASSY_SCAN_OK SET ISSCAN = 0  WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
								--RESET   INCORRECT LABEL
								UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE = '', ISINCORRECT = 0 WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
						END
					END
					ELSE
					BEGIN
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
						, @BARCODE = @BARCODE, @HMIMESSAGE = 'MAXIMUM_FAILED_ATTEMPT_REACHED'
					END
				END
				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				COMMIT TRAN
				RETURN
			END

			--CHECK FOR DUPLICATE LABEL -------------------------------------------------------------------------------
			SET @SCANNEDBARCODE = ''
			
			SELECT @SCANNEDBARCODE = ISNULL(BARCODE, '') FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0 AND PROFITCENTERCODE = @PROFITCENTERCODE 
			-- Start - Added By RS On 20191021 DateCode Removed for WIP Logic
				--AND LINECODE = @LINECODE AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END AND MACHINECODE = @MACHINECODE AND BARCODE = @BARCODE AND ISNULL(STATUS, '') = 'PS'
				AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND BARCODE = @BARCODE AND ISNULL(STATUS, '') = 'PS'
			-- End - Added By RS On 20191021 DateCode Removed for WIP Logic

			IF @SCANNEDBARCODE = ''
			BEGIN
				SELECT @SCANNEDBARCODE = ISNULL(BARCODE, '') FROM ASSY_LINEASSYSTATUS (NOLOCK) WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0 AND PROFITCENTERCODE = @PROFITCENTERCODE 
				-- Start - Added By RS On 20191021 DateCode Removed for WIP Logic
					--AND LINECODE = @LINECODE AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END AND MACHINECODE = @MACHINECODE AND BARCODE = @BARCODE AND ISNULL(STATUS, '') = 'PS'
					AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND BARCODE = @BARCODE AND ISNULL(STATUS, '') = 'PS'
				-- End - Added By RS On 20191021 DateCode Removed for WIP Logic
			END

			-- MOVE PERFORMANCE PASS DATA IF CRIMPING TIME LIMIT REACHED (ADDED BY RASHID ON 31ST MAY 2016)
			DECLARE @CRIMPINGMACHINECODE VARCHAR(30) = '', @CRIMPINGTIMELIMIT INT = 0, @PREVRESULTTIMESTAMP DATETIME = NULL, @BFLAG BIT = 0, 
			@PERFORMANCEMACHINECODE VARCHAR(30) = '', @MBAPERFORMANCEMACHINECODE VARCHAR(30) = '', @CSHELLCRIMPINGMACHINECODE VARCHAR(30) = ''
			
			
			/* -- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
			SELECT @CRIMPINGMACHINECODE = ISNULL(UPPER(LTRIM(RTRIM(PARAMETER_VALUE))), '') FROM PARAMETER_MST WITH (NOLOCK) 
				WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'CRIMPING' AND PARAMETER_C2 = 'MACHINECODE' AND WH_CODE = @PROFITCENTERCODE

			SELECT @PERFORMANCEMACHINECODE = ISNULL(UPPER(LTRIM(RTRIM(PARAMETER_VALUE))), '') FROM PARAMETER_MST WITH (NOLOCK) 
				WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'FINALVIEWING' AND PARAMETER_C2 = 'SERVO_PERFORMANCE_MACHINECODE' AND WH_CODE = @PROFITCENTERCODE
					
			-- ADDED BY RASHID ON 9TH SEP 2016 FOR MBA PERFORMANCE
			SELECT @MBAPERFORMANCEMACHINECODE = ISNULL(UPPER(LTRIM(RTRIM(PARAMETER_VALUE))), '') FROM PARAMETER_MST WITH (NOLOCK) 
				WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'MBA_PERFORMANCE' AND PARAMETER_C2 = 'MACHINECODE' AND WH_CODE = @PROFITCENTERCODE
			*/
			
			SELECT @CRIMPINGMACHINECODE = ISNULL(LTRIM(RTRIM(DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'CRIMPING', 'MACHINECODE', @PROFITCENTERCODE))),'')
			SELECT @PERFORMANCEMACHINECODE = ISNULL(LTRIM(RTRIM(DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'FINALVIEWING', 'SERVO_PERFORMANCE_MACHINECODE', @PROFITCENTERCODE))),'')
			SELECT @MBAPERFORMANCEMACHINECODE = ISNULL(LTRIM(RTRIM(DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'MBA_PERFORMANCE', 'MACHINECODE', @PROFITCENTERCODE))),'')
					
			SELECT @CSHELLCRIMPINGMACHINECODE = ISNULL(LTRIM(RTRIM(DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'CentreShellCrimping', 'MACHINECODE', @PROFITCENTERCODE))),'')
			IF @SCANNEDBARCODE <> '' AND ((@MACHINECODE = @PERFORMANCEMACHINECODE) or @IsReofferStn ='1' )
			BEGIN
				IF EXISTS
				(
					SELECT 1 FROM ASSY_LINE_CRIMPING_RETEST_STATUS WITH (NOLOCK)
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND BARCODE = @BARCODE AND ISNULL(ISRETEST, 0) = 0
				)
				BEGIN
					-- MOVE MBA PERFORMANCE PASS DATA IF CRIMPING TIME LIMIT REACHED (ADDED BY RASHID ON 9TH SEP 2016)
					IF EXISTS
					(
						-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
						-- SELECT TOP 1 L.OPERATIONREQUIRED FROM ROUTINGCONFIGLINEWISE L WITH (NOLOCK)
						SELECT L.OPERATIONREQUIRED FROM ROUTINGCONFIGLINEWISE L WITH (NOLOCK)
							INNER JOIN ROUTINGCONFIGPARTWISE P  WITH (NOLOCK)
								ON L.OPERATIONCODE = P.OPERATIONCODE AND L.MACHINECODE = P.MACHINECODE 
							WHERE L.LINECODE = @LINECODE AND L.PROFITCENTERCODE = @PROFITCENTERCODE AND P.PROFITCENTERCODE = @PROFITCENTERCODE
								-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
								--AND P.PARTNO = (SELECT TOP 1 ASSY_PARTNO FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE LINECODE = @LINECODE ORDER BY CREATEDDATE DESC)
								AND P.PARTNO = @ASSY_PARTNO
									AND L.TRACEABILITY = 1 AND P.TRACEABILITY = 1 AND L.MACHINECODE = @MBAPERFORMANCEMACHINECODE AND P.MACHINECODE = @MBAPERFORMANCEMACHINECODE
										-- ADDED BY RASHID FOR HANDLING ENGRAVING STATION ON 10TH SEP 2016
										AND ISNULL(L.ENGRAVING, 0) = 0 AND ISNULL(P.ENGRAVING, 0) = 0
					)
					BEGIN
					--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
						INSERT INTO ASSY_PERFORMANCEHISTORY(PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE, STATIONCODE, BARCODE, STATUS, FAILCOUNT, DATECODE, 
							PARTNO, ACTIVE, RESULTTIMESTAMP, SCANTIMESTAMP, USERID, ISTALLYCHARTAPPROVED, ISREWORKPART, HISTORYTIMESTAMP, PRODUCTIONORDERNO)
						SELECT PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE, STATIONCODE, BARCODE, STATUS, FAILCOUNT, DATECODE, PARTNO, ACTIVE, RESULTTIMESTAMP, 
							SCANTIMESTAMP, USERID, ISTALLYCHARTAPPROVED, ISREWORKPART, GETDATE(), PRODUCTIONORDERNO
							FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK)
								WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND MACHINECODE = @MBAPERFORMANCEMACHINECODE AND BARCODE = @BARCODE

						DELETE FROM ASSY_LINEASSYSTATUS_RUNNING
							WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND MACHINECODE = @MBAPERFORMANCEMACHINECODE AND BARCODE = @BARCODE
					END

					--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
					INSERT INTO ASSY_PERFORMANCEHISTORY(PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE, STATIONCODE, BARCODE, STATUS, FAILCOUNT, DATECODE, PARTNO, 
						ACTIVE, RESULTTIMESTAMP, SCANTIMESTAMP, USERID, ISTALLYCHARTAPPROVED, ISREWORKPART, HISTORYTIMESTAMP, PRODUCTIONORDERNO)
					SELECT PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE, STATIONCODE, BARCODE, STATUS, FAILCOUNT, DATECODE, PARTNO, ACTIVE, RESULTTIMESTAMP, 
						SCANTIMESTAMP, USERID, ISTALLYCHARTAPPROVED, ISREWORKPART, GETDATE(), PRODUCTIONORDERNO
						FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK)
							WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND BARCODE = @BARCODE AND ISNULL(STATUS, '') = 'PS'
							
					DELETE FROM ASSY_LINEASSYSTATUS_RUNNING
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND BARCODE = @BARCODE AND ISNULL(STATUS, '') = 'PS'
					
					DELETE FROM ASSY_LINEQUEUETIME_RUNNING where MACHINECODE=@MACHINECODE and Barcode=@BARCODE and QuarantineStatus=3

					IF(@MACHINECODE=@PERFORMANCEMACHINECODE)
					BEGIN
						DELETE FROM ASSY_PERFORMANCE_ZIGOUTTIMESTAMP WHERE BARCODE = @BARCODE
					END

					UPDATE ASSY_LINE_CRIMPING_RETEST_STATUS SET ISRETEST = 1
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND BARCODE = @BARCODE AND ISNULL(ISRETEST, 0) = 0
					SET @BFLAG = 1
				END
			END

			IF @SCANNEDBARCODE <> ''					
			BEGIN
				IF @BFLAG = 0
				BEGIN
					--UPDATE ASSY_DUPLICATELABEL  TABLE
					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						IF NOT EXISTS
						( 
							SELECT 1 FROM ASSY_SCAN_OK (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND ISNULL(ISCYCLESTARTED, 0) = 1
						)
						BEGIN
							IF EXISTS
							(
								SELECT 1 FROM ASSY_DUPLICATELABEL (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
							)
							BEGIN
								UPDATE ASSY_DUPLICATELABEL SET ISDUPLICATE = 1, BARCODE = @BARCODE  WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
								
							END
							ELSE
							BEGIN
								INSERT INTO ASSY_DUPLICATELABEL(LINECODE, OPERATIONCODE, STATIONCODE, BARCODE, ISDUPLICATE)
								SELECT @LINECODE, @OPERATIONCODE, @STATIONCODE, @BARCODE, 1
								
							END
							--RESET SCAN OK
								UPDATE ASSY_SCAN_OK SET ISSCAN = 0  WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
								--RESET   INCORRECT LABEL
								UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE = '', ISINCORRECT = 0 WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
						END
					END

					--GET TESTING TIME OF PARTICULAR BARCODE
					DECLARE @PARTTESTINGTIME DATETIME = NULL, @ISMBA_TRACEABILITY BIT = 0

					SELECT @PARTTESTINGTIME = RESULTTIMESTAMP FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0 AND PROFITCENTERCODE = @PROFITCENTERCODE
					-- Start - Added By RS On 20191021 DateCode Removed for WIP Logic
						--AND LINECODE = @LINECODE AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END AND MACHINECODE = @MACHINECODE AND BARCODE = @BARCODE AND ISNULL(STATUS, '') = 'PS'
						AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND BARCODE = @BARCODE AND ISNULL(STATUS, '') = 'PS'
					-- End - Added By RS On 20191021 DateCode Removed for WIP Logic
						
					IF @PARTTESTINGTIME IS NULL
					BEGIN
						SELECT @PARTTESTINGTIME = RESULTTIMESTAMP FROM ASSY_LINEASSYSTATUS (NOLOCK) WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0 AND PROFITCENTERCODE = @PROFITCENTERCODE 
						-- Start - Added By RS On 20191021 DateCode Removed for WIP Logic
							--AND LINECODE = @LINECODE AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END AND MACHINECODE = @MACHINECODE AND BARCODE = @BARCODE AND ISNULL(STATUS, '') = 'PS'
							AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND BARCODE = @BARCODE AND ISNULL(STATUS, '') = 'PS'
						-- End - Added By RS On 20191021 DateCode Removed for WIP Logic
					END										
						SELECT @RETURNINT = 1, @RETURNVALUE = 'DUPLICATE_LABEL^' + CONVERT(VARCHAR(100), @PARTTESTINGTIME)
						
					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
					COMMIT TRAN
					RETURN
				END
			END
			-- CHECK FOR CRIMPING TIME LIMIT FROM PERFORMANCE STATION (ADDED BY RASHID ON 31ST MAY 2016)
			IF (@CRIMPINGMACHINECODE ! = '' AND @CRIMPINGMACHINECODE = @MACHINECODE)
			BEGIN
				Declare @IsCrimpingFirstStation BIT = 0
				IF EXISTS
				(
					SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
						AND KeyType = 'IsCrimpingFirstStation' AND KeyValue = '1'
				)
				BEGIN
					SET @IsCrimpingFirstStation = 1
				END
				ELSE
				BEGIN
					SET @IsCrimpingFirstStation = 0
				END

				--IF @LINECODE != 'P1'
				IF @IsCrimpingFirstStation = 0
				BEGIN
					IF EXISTS
					(
						SELECT 1 FROM ROUTINGCONFIGLINEWISE R WITH (NOLOCK) 
							INNER JOIN ROUTINGCONFIGPARTWISE P WITH (NOLOCK) 
								ON R.PROFITCENTERCODE = P.PROFITCENTERCODE AND R.MACHINECODE = P.MACHINECODE AND R.OPERATIONCODE = P.OPERATIONCODE
									WHERE R.PROFITCENTERCODE = @PROFITCENTERCODE AND R.LINECODE = @LINECODE AND R.MACHINECODE = @PERFORMANCEMACHINECODE
										AND (ISNULL(R.TRACEABILITY, 0) = 0 OR ISNULL(P.TRACEABILITY, 0) = 0) AND P.PARTNO = @ASSY_PARTNO
					)
					BEGIN
						SELECT @RETURNINT = 1, @RETURNVALUE = 'PERFORMANCE_BYPASS_CAN_NOT_RUN_LINE_WITH_CRIMPING'
					
						-- SCANNING LOG BY RS ON 20170913
						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
						COMMIT TRAN
						RETURN
					END
				END

				/* It is obselete beacuse of handling mBA and Non-mBA Parts running in Nissan Line P6. So change approach to allow in all line
				SELECT @CRIMPINGTIMELIMIT = CONVERT(INT,ISNULL(LTRIM(RTRIM(DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', @LINECODE, 'CRIMPINGTIMELIMIT', @PROFITCENTERCODE))),0))
				*/
				Declare @mBA_Non_mBA_Category VARCHAR(50) = ''
				SELECT @mBA_Non_mBA_Category = dbo.FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE(@ProfitCenterCode,'PART_ATTRB','MBA_NON_MBA_Cat',@ASSY_PARTNO,'')
				--NMBA will be default category - as per Customer Request
				IF ISNULL(@mBA_Non_mBA_Category,'') = ''
				BEGIN
					SET @mBA_Non_mBA_Category = 'NMBA_Cat'
				END

				SELECT @CRIMPINGTIMELIMIT = dbo.FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE(@ProfitCenterCode,'LINE_ATTRB',@mBA_Non_mBA_Category,@LINECODE,'')
				
				--IF @LINECODE = 'P1'
				IF @IsCrimpingFirstStation = 1
				BEGIN
					SELECT @PREVRESULTTIMESTAMP = RESULTTIMESTAMP FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
								AND LINECODE = @LINECODE AND ISNULL(ISTALLYCHARTAPPROVED, 0) = 0 AND  MACHINECODE = @PREVMACHINECODE
								-- Start - Added By RS On 20191021 DateCode Removed for WIP Logic
									--AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END AND BARCODE = @BARCODE
									AND BARCODE = @BARCODE
								-- End - Added By RS On 20191021 DateCode Removed for WIP Logic
								AND  ISNULL(STATUS, '') = 'PS'
					
					IF @PREVRESULTTIMESTAMP IS NULL
					BEGIN
						EXEC ASSY_PROC_RETEST_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
							, @BARCODE = @BARCODE, @HMIMESSAGE = 'RESULT_TIMESTAMP_NOT_FOUND_FROM_PREV_STATION'

						SET @RETURNINT = 1
						SET @RETURNVALUE = 'RESULT_TIMESTAMP_NOT_FOUND_FROM_PREV_STATION'
					
						-- SCANNING LOG BY RS ON 20170913
						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
						COMMIT TRAN
						RETURN
					END
				END
				ELSE
				BEGIN
					SELECT @PREVRESULTTIMESTAMP = ZIGOUTTIMESTAMP FROM ASSY_PERFORMANCE_ZIGOUTTIMESTAMP WITH (NOLOCK) WHERE BARCODE = @BARCODE
				END
				
				IF @PREVRESULTTIMESTAMP IS NULL
				BEGIN
					EXEC ASSY_PROC_RETEST_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'JIG_NOT_COME_OUT_FROM_PERFORMANCE_RETEST'
							
					IF EXISTS
					(
						-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
						-- SELECT TOP 1 L.OPERATIONREQUIRED FROM ROUTINGCONFIGLINEWISE L WITH (NOLOCK)
						SELECT L.OPERATIONREQUIRED FROM ROUTINGCONFIGLINEWISE L WITH (NOLOCK) 
							INNER JOIN ROUTINGCONFIGPARTWISE P  WITH (NOLOCK) 
								ON L.OPERATIONCODE = P.OPERATIONCODE AND L.MACHINECODE = P.MACHINECODE 
									WHERE L.LINECODE = @LINECODE AND L.PROFITCENTERCODE = @PROFITCENTERCODE AND P.PROFITCENTERCODE = @PROFITCENTERCODE
										-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
										--AND P.PARTNO = (SELECT TOP 1 ASSY_PARTNO FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE LINECODE = @LINECODE ORDER BY CREATEDDATE DESC)
										AND P.PARTNO = @ASSY_PARTNO
											AND L.TRACEABILITY = 1 AND P.TRACEABILITY = 1 AND L.MACHINECODE = @MBAPERFORMANCEMACHINECODE AND P.MACHINECODE = @MBAPERFORMANCEMACHINECODE
												-- ADDED BY RASHID FOR HANDLING ENGRAVING STATION ON 10TH SEP 2016
												AND ISNULL(L.ENGRAVING, 0) = 0 AND ISNULL(P.ENGRAVING, 0) = 0
					)
					BEGIN
						SET @ISMBA_TRACEABILITY = 1
					END
					ELSE
					BEGIN
						SET @ISMBA_TRACEABILITY = 0
					END

					IF NOT EXISTS
					(
						SELECT 1 FROM ASSY_LINE_CRIMPING_RETEST_STATUS WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND	LINECODE = @LINECODE
							AND MACHINECODE = CASE @ISMBA_TRACEABILITY WHEN 0 THEN @PREVMACHINECODE WHEN 1 THEN @PERFORMANCEMACHINECODE END AND BARCODE = @BARCODE AND ISNULL(ISRETEST, 0) = 0
					)
					BEGIN	
						INSERT INTO ASSY_LINE_CRIMPING_RETEST_STATUS(PROFITCENTERCODE, LINECODE, MACHINECODE, BARCODE, TIMESTAMP, ISRETEST, REMARK)
						SELECT @PROFITCENTERCODE, @LINECODE, CASE @ISMBA_TRACEABILITY WHEN 0 THEN @PREVMACHINECODE WHEN 1 THEN @PERFORMANCEMACHINECODE END, @BARCODE, GETDATE(), 0, 'JIG IS NOT COME OUT FROM PERFORMANCE STATION PROPERLY. RETEST IN PERFORMANCE STATION'
					END

					SET @RETURNINT = 1
					SET @RETURNVALUE = 'JIG_NOT_COME_OUT_FROM_PERFORMANCE_RETEST'
					
					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
					COMMIT TRAN
					RETURN
				END

				IF(DATEDIFF(SECOND, @PREVRESULTTIMESTAMP, GETDATE()) > @CRIMPINGTIMELIMIT)
				BEGIN
					SET @ISMBA_TRACEABILITY = 0
					
					IF EXISTS
					(
						-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
						-- SELECT TOP 1 L.OPERATIONREQUIRED FROM ROUTINGCONFIGLINEWISE L WITH (NOLOCK)
						SELECT L.OPERATIONREQUIRED FROM ROUTINGCONFIGLINEWISE L WITH (NOLOCK)
							INNER JOIN ROUTINGCONFIGPARTWISE P  WITH (NOLOCK) 
								ON L.OPERATIONCODE = P.OPERATIONCODE AND L.MACHINECODE = P.MACHINECODE 
									WHERE L.LINECODE = @LINECODE AND L.PROFITCENTERCODE = @PROFITCENTERCODE AND P.PROFITCENTERCODE = @PROFITCENTERCODE
										-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
										-- AND P.PARTNO = (SELECT TOP 1 ASSY_PARTNO FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE LINECODE = @LINECODE ORDER BY CREATEDDATE DESC)
										AND P.PARTNO = @ASSY_PARTNO
											AND L.TRACEABILITY = 1 AND P.TRACEABILITY = 1 AND L.MACHINECODE = @MBAPERFORMANCEMACHINECODE AND P.MACHINECODE = @MBAPERFORMANCEMACHINECODE
												-- ADDED BY RASHID FOR HANDLING ENGRAVING STATION ON 10TH SEP 2016
												AND ISNULL(L.ENGRAVING, 0) = 0 AND ISNULL(P.ENGRAVING, 0) = 0
					)
					BEGIN
						SET @ISMBA_TRACEABILITY = 1
					END

					SET @INCORRECTMSG = ''
					SET @INCORRECTMSG = (SELECT MACHINENAME FROM MACHINEMST WITH (NOLOCK) WHERE MACHINECODE = CASE @ISMBA_TRACEABILITY WHEN 0 THEN @PREVMACHINECODE WHEN 1 THEN @PERFORMANCEMACHINECODE END AND PROFITCENTERCODE = @PROFITCENTERCODE)
					
					SELECT @RETURNINT = 1, @RETURNVALUE = 'SCAN_TIME_LIMIT_REACHED_RETEST_IN_PERFORMANCE_STATION'
					--SET @RETURNVALUE = 'SCAN TIME LIMIT REACHED. RETEST IN PERFORMANCE STATION - ' + @INCORRECTMSG
					--SET @RETURNVALUE = 'SCAN_TIME_LIMIT_REACHED_RETEST_IN_PERFORMANCE_STATION'
					
					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_RETEST_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
						, @BARCODE = @BARCODE, @HMIMESSAGE = 'SCAN_TIME_LIMIT_REACHED_RETEST_IN_PERFORMANCE_STATION'
					END
					
					IF NOT EXISTS
					(
						SELECT 1 FROM ASSY_LINE_CRIMPING_RETEST_STATUS WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
							AND MACHINECODE = CASE @ISMBA_TRACEABILITY WHEN 0 THEN @PREVMACHINECODE WHEN 1 THEN @PERFORMANCEMACHINECODE END AND BARCODE = @BARCODE AND ISNULL(ISRETEST, 0) = 0
					)
					BEGIN	
						INSERT INTO ASSY_LINE_CRIMPING_RETEST_STATUS(PROFITCENTERCODE, LINECODE, MACHINECODE, BARCODE, TIMESTAMP, ISRETEST, REMARK)
						SELECT @PROFITCENTERCODE, @LINECODE, CASE @ISMBA_TRACEABILITY WHEN 0 THEN @PREVMACHINECODE WHEN 1 THEN @PERFORMANCEMACHINECODE END, @BARCODE, GETDATE(),
						0, 'DIFFERECE OF TIME(SECONDS) BETWEEN RESULTTIMESTAMP OF PERFORMANCE STATION AND CRIMPING STATION'
					END
					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

					COMMIT TRAN
					RETURN
				END
			END

			-- CHECK FOR CENTRE SHELL CRIMPING TIME LIMIT FROM PREVIOUS STATION (ADDED BY RASHID ON 26TH APRIL 2018)
			IF (@CSHELLCRIMPINGMACHINECODE ! = '' AND @CSHELLCRIMPINGMACHINECODE = @MACHINECODE)
			BEGIN
				SELECT @CRIMPINGTIMELIMIT = CONVERT(INT,ISNULL(LTRIM(RTRIM(DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', @LINECODE, 'CShell_CrimpingTimeLimit', @PROFITCENTERCODE))),0))
				Declare @IsCenterShellCrimpingFirstStation BIT = 0
				IF EXISTS
				(
					SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
						AND KeyType = 'IsCenterShellCrimpingFirstStation' AND KeyValue = '1'
				)
				BEGIN
					SET @IsCenterShellCrimpingFirstStation = 1
				END
				ELSE
					SET @IsCenterShellCrimpingFirstStation = 0

				--IF @LINECODE = 'P2'
				IF @IsCenterShellCrimpingFirstStation = 1
				BEGIN
					SELECT @PREVRESULTTIMESTAMP = RESULTTIMESTAMP FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
								AND LINECODE = @LINECODE AND ISNULL(ISTALLYCHARTAPPROVED, 0) = 0 AND  MACHINECODE = @PREVMACHINECODE
								-- Start - Added By RS On 20191021 DateCode Removed for WIP Logic
								--AND DATECODE = @DATECODE AND BARCODE = @BARCODE
								AND BARCODE = @BARCODE
								-- End - Added By RS On 20191021 DateCode Removed for WIP Logic
								AND  ISNULL(STATUS, '') = 'PS'
					
					IF @PREVRESULTTIMESTAMP IS NULL
					BEGIN
						EXEC ASSY_PROC_RETEST_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
							, @BARCODE = @BARCODE, @HMIMESSAGE = 'RESULT_TIMESTAMP_NOT_FOUND_FROM_PREV_STATION'

						SET @RETURNINT = 1
						SET @RETURNVALUE = 'RESULT_TIMESTAMP_NOT_FOUND_FROM_PREV_STATION'
					
						-- SCANNING LOG BY RS ON 20170913
						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
						COMMIT TRAN
						RETURN
					END
				END

				IF(DATEDIFF(SECOND, @PREVRESULTTIMESTAMP, GETDATE()) > @CRIMPINGTIMELIMIT)
				BEGIN
					SET @INCORRECTMSG = ''
					SET @INCORRECTMSG = (SELECT MACHINENAME FROM MACHINEMST WITH (NOLOCK) WHERE MACHINECODE = CASE @ISMBA_TRACEABILITY WHEN 0 THEN @PREVMACHINECODE WHEN 1 THEN @PERFORMANCEMACHINECODE END AND PROFITCENTERCODE = @PROFITCENTERCODE)
					
					SELECT @RETURNINT = 1, @RETURNVALUE = 'SCAN_TIME_LIMIT_REACHED_RETEST_IN_PREV_STATION'
					
					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_RETEST_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
						, @BARCODE = @BARCODE, @HMIMESSAGE = 'SCAN_TIME_LIMIT_REACHED_RETEST_IN_PREV_STATION'
					END
					
					IF NOT EXISTS
					(
						SELECT 1 FROM ASSY_LINE_CRIMPING_RETEST_STATUS WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
							AND MACHINECODE = @PREVMACHINECODE AND BARCODE = @BARCODE AND ISNULL(ISRETEST, 0) = 0
					)
					BEGIN	
						INSERT INTO ASSY_LINE_CRIMPING_RETEST_STATUS(PROFITCENTERCODE, LINECODE, MACHINECODE, BARCODE, TIMESTAMP, ISRETEST, REMARK)
						SELECT @PROFITCENTERCODE, @LINECODE, CASE @ISMBA_TRACEABILITY WHEN 0 THEN @PREVMACHINECODE WHEN 1 THEN @PERFORMANCEMACHINECODE END, @BARCODE, GETDATE(), 0, 'DIFFERECE OF TIME(SECONDS) BETWEEN RESULTTIMESTAMP OF PREVIOUS STATION AND CENTRE SHELL CRIMPING STATION'
					END
					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

					COMMIT TRAN
					RETURN
				END
			END

			IF @OPERATIONCODE = @FINALVIEWING_OPERATIONCODE
			BEGIN
				--START-- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING STOCK DEDUCTION
				-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
				-- IF ((SELECT TOP 1 ISNULL(ISMATFEEDREQUIRED, 0) FROM LINEMST WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE) = 1)
				-- CHANGED BY RS ON 20170720
				SELECT @ISMATFEEDREQUIRED = ISNULL(ISMATFEEDREQUIRED, 0), @ISMATFEEDPRINTSCANREQUIRED = ISNULL(ISMATFEEDPRINTSCANREQUIRED,0) FROM LINEMST WITH (NOLOCK)
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
				IF (@ISMATFEEDREQUIRED = 1 AND @ISMATFEEDPRINTSCANREQUIRED = 1)
				BEGIN
					DECLARE @STMC_PARTNUMBER VARCHAR(20) = '', @MAT_FEED_PARTTYPE VARCHAR(20) = '', @MAT_FEED_PARTNUMBER VARCHAR(20) = ''
					-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
					-- SELECT TOP 1 @STMC_PARTNUMBER = ISNULL(ASSY_PARTNO,''), @MAT_FEED_PARTTYPE = PARTTYPE FROM ASSY_RUNNINGPART WITH (NOLOCK)
					SELECT @STMC_PARTNUMBER = ISNULL(ASSY_PARTNO,''), @MAT_FEED_PARTTYPE = PARTTYPE FROM ASSY_RUNNINGPART WITH (NOLOCK)
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
						-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
							-- ORDER BY CREATEDDATE DESC
					
					IF (@MAT_FEED_PARTTYPE) = ('STMC')
						SET @MAT_FEED_PARTNUMBER = @STMC_PARTNUMBER
					ELSE
						SET @MAT_FEED_PARTNUMBER = @PARTNUMBER
					--START-- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING VALIDATION
					--SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL WITH (NOLOCK) 
					--	WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

					SET @EXECQUERY = ''
					SET @EXECQUERY = '
					SELECT REMARKS FROM ' + @LINKSERVERNAME + '.DBO.ASSY_LINEMATFEEDREMARKSTATUS WITH (NOLOCK) 
						WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + '''
							AND PARTNO = ''' + @MAT_FEED_PARTNUMBER + ''' AND ISACTIVE = 1 '
					--PRINT @EXECQUERY

					DECLARE @MATFEEDREMARK AS TABLE
					(
						REMARKS VARCHAR(MAX)
					)

					INSERT INTO @MATFEEDREMARK(REMARKS)
					EXEC (@EXECQUERY)
				
					DECLARE @MATFEEDREMARKSTATUS VARCHAR(MAX) = ''

					IF EXISTS (SELECT 1 FROM @MATFEEDREMARK)
					BEGIN
						SELECT @MATFEEDREMARKSTATUS = LTRIM(RTRIM(REMARKS)) FROM @MATFEEDREMARK
								
						DECLARE @QTYLOWMESSAGE BIT = 0
						
						IF (@MATFEEDREMARKSTATUS ! = 'OK')
						BEGIN
							IF (LEFT(@MATFEEDREMARKSTATUS, 4) = 'SOME')
							BEGIN
								SET @QTYLOWMESSAGE = 1
							END
							ELSE
							BEGIN
								SELECT @RETURNVALUE = @MATFEEDREMARKSTATUS, @RETURNINT = 1

								-- SCANNING LOG BY RS ON 20170913
								INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
								SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
								COMMIT
								RETURN
							END
						END
					END
				END
			END
			--END-- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING VALIDATION
			
			----CHECK FOR WIP LIMIT			      	
			EXEC ASSY_PROC_WIP_MANAGE  @CONDITION = 'VALIDATE_WIP', @LINECODE = @LINECODE, @MACHINECODE = @MACHINECODE, @BARCODE = @BARCODE, @PROFITCENTERCODE = @PROFITCENTERCODE  
			, @RETURNVALUE = @RETURNVALUE1 OUT, @RETURNINT = @RETURNINT1 OUT
			
			IF RTRIM(LTRIM(@RETURNVALUE1)) = 'WIP_LIMIT_HAS_REACHED'
			BEGIN							
				SELECT @RETURNINT = 1, @RETURNVALUE = 'WIP_LIMIT_HAS_REACHED'
				
				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'WIP_LIMIT_HAS_REACHED'
				END
				-- SCANNING LOG BY RS ON 20170913
				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

				COMMIT TRAN
				RETURN
			END

			IF @NextMachineCode = @MACHINECODE
			BEGIN
				IF EXISTS
				(
					SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
						AND KeyType = 'IsBoreViewingMixUpRequired' AND KeyValue = '1'
				)
				BEGIN
					IF EXISTS
					(
						SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
							AND KeyType = 'IsBoreViewingValidationRequiredAtFV' AND KeyValue = '1'
					)
					BEGIN
						Declare @BoreMixUpBarcode VARCHAR(50) = ''
						SELECT @BoreMixUpBarcode = Barcode FROM Assy_FV_BoreView_Mapping_Status (NOLOCK) WHERE OperationCode = @OperationCode
						IF EXISTS
						(
							SELECT 1 FROM Assy_BoreInspection_Result (NOLOCK) WHERE TSBarcode = @Barcode AND IsMapped = 1 AND Barcode = @BoreMixUpBarcode
						)
						BEGIN
							DELETE FROM Assy_FV_BoreView_Mapping_Status WHERE OperationCode = @OperationCode
						END
						ELSE
						BEGIN
							DELETE FROM Assy_FV_BoreView_Mapping_Status WHERE OperationCode = @OperationCode
							
							SELECT @RETURNINT = 1, @RETURNVALUE = 'MAPPING_VALIDATION_FAIL'
							--UPDATE INCORRECT LABEL
							IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
							BEGIN
								EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
								, @BARCODE = @BARCODE, @HMIMESSAGE = 'MAPPING_VALIDATION_FAIL'
							END
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

							COMMIT TRAN
							RETURN
						END
					END
				END
			END

			IF EXISTS 
			(
				SELECT 1 FROM MACHINEMST WITH (NOLOCK) WHERE MACHINECODE = @MACHINECODE AND INDEXPERSTATIONS = 2
			)
			BEGIN
				SELECT @STATIONCODE = STATIONCODE FROM ASSY_STATIONS_ZIG_IN_OUT_STATUS (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE

				IF @STATIONCODE = 1
					SET @SCANNINGSTATION = 2
				ELSE IF  @STATIONCODE = 2
					SET @SCANNINGSTATION = 1

				SET @STATIONCODE = @SCANNINGSTATION
				--ADDED BY RS ON 20170529 FOR HANDLING TWIN STATION BARCODE WHILE SCANNING ON SAME PALLET
				IF ((SELECT TOP 1 BARCODE FROM ASSY_SCAN_OK (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE AND STATIONCODE = CASE @SCANNINGSTATION WHEN 1 THEN 2 ELSE 1 END) = @BARCODE)
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'BARCODE_TESTING_PROGRESS_IN_OTHER_PALLET'
					--UPDATE INCORRECT LABEL
					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
						, @BARCODE = @BARCODE, @HMIMESSAGE = 'BARCODE_TESTING_PROGRESS_IN_OTHER_PALLET'
					END
					-- SCANNING LOG BY RS ON 20170913
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

					COMMIT TRAN
					RETURN
				END

				IF EXISTS
				(
					SELECT 1 FROM ASSY_SCAN_OK (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE AND STATIONCODE = @SCANNINGSTATION
				)
				BEGIN
					UPDATE ASSY_SCAN_OK SET ISSCAN = 1, BARCODE = @BARCODE WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE AND STATIONCODE = @SCANNINGSTATION
					
				END
				ELSE
				BEGIN
					INSERT INTO ASSY_SCAN_OK(LINECODE, OPERATIONCODE, STATIONCODE, BARCODE, ISSCAN, MACHINECODE)
					SELECT @LINECODE, @OPERATIONCODE, @SCANNINGSTATION, @BARCODE, 1, @MACHINECODE												
				END

				--RESET   INCORRECT LABEL
				UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE = '', ISINCORRECT = 0 WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
				--RESET DUPLICATE LABEL
				UPDATE ASSY_DUPLICATELABEL SET ISDUPLICATE = 0 WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
			END
			ELSE IF EXISTS
			(
				SELECT 1 FROM ASSY_SCAN_OK (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE
			)
			BEGIN
				UPDATE ASSY_SCAN_OK SET ISSCAN = 1, BARCODE = @BARCODE WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE

			END
			ELSE
			BEGIN
				INSERT INTO ASSY_SCAN_OK(LINECODE, OPERATIONCODE, STATIONCODE, BARCODE, ISSCAN, MACHINECODE)
				SELECT @LINECODE, @OPERATIONCODE, @STATIONCODE, @BARCODE, 1, @MACHINECODE
			END

			--BAR_STATUS	--1 first time
			IF @BAR_STATUS_KEY = 1
			BEGIN
				if not exists (select top 1 1 from Barcode_Status_Time (nolock) where Barcode=@Barcode and DateCode=@Live_Datecode 
				and LineCode=@LineCode and MachineCode=@MachineCode and OperationCode=@OperationCode)
				begin
					insert into Barcode_Status_Time (Barcode, BAR_STATUS, LineCode, MachineCode, OperationCode, DateCode, EntStamp, UpdateStamp)
					values (@Barcode, @BAR_STATUS, @LineCode, @MachineCode, @OperationCode, @Live_Datecode, getdate(), getdate())
				end
				else
				begin
					update Barcode_Status_Time set BAR_STATUS=@BAR_STATUS, UpdateStamp=getdate() where Barcode=@Barcode and DateCode=@Live_Datecode 
					and LineCode=@LineCode and MachineCode=@MachineCode and OperationCode=@OperationCode
				end
			END

			INSERT INTO @BreakDetails (BreakID, PartNo)
			EXEC Assy_Proc_FinalViewing @CONDITION='QUEUETIME_BREAK_STATUS', @PROFITCENTERCODE=@PROFITCENTERCODE, @LineCode=@LineCode

			IF EXISTS (SELECT TOP 1 1 FROM @BreakDetails)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'BREAK IS ON'
				COMMIT TRAN
				RETURN
			END

			--START-- ADDED BY THRAINDER ON 25TH NOV 2025 FOR QUEUE TIME MANAGEMENT
			IF (@QueueTimeValidation=1 AND @StationQueueTimemst > 0 AND @IsReworkBarcodeCurrentStn = 0)
			BEGIN
				--EXEC ASSY_PROC_GET_PREVIOUS_MACHINECODE @LINECODE = @LINECODE, @MACHINECODE = @MACHINECODE, @PARTNUMBER = @ASSY_PARTNO
				--,@PREVMACHINECODE = @PreviousMachineCode OUTPUT	--MAY BE NOT EVEN REQ BCZ WE HAVE QUE TABLE DATA ALREADY TO SEE PREVIOUS STATION DATA


				IF EXISTS (SELECT TOP 1 1 FROM #ASSY_LINEQUEUETIME_RUNNING WHERE NextOperationcode=@OPERATIONCODE)
				BEGIN
					SELECT TOP 1 @PreviousStationCode=Operationcode,@PreviousMachineCode=MachineCode 
					FROM #ASSY_LINEQUEUETIME_RUNNING WHERE NextOperationcode=@OPERATIONCODE
					ORDER BY ResultTimestamp DESC
					
					SELECT TOP 1 @CurrentQueueStatus=QuarantineStatus FROM #ASSY_LINEQUEUETIME_RUNNING (NOLOCK) WHERE ProfitCenterCode=@PROFITCENTERCODE AND LineCode=@LINECODE
						AND NextOperationcode=@OPERATIONCODE ORDER BY EntStamp DESC

					IF @CurrentQueueStatus = 1
					BEGIN
						
						SET @INCORRECTMSG = 'Barcode_Already_Quarantine_Pending_For_Approval'
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE, @HMIMESSAGE = @INCORRECTMSG, @IsExpiredTag = 1
							
						SET @RETURNINT = 1
						SET @RETURNVALUE = @INCORRECTMSG


						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
						COMMIT TRAN
						RETURN
					END
					IF @CurrentQueueStatus in ( 2,3)
					BEGIN
						--ALREADY UPDATING THE SCAN TIME STAMP DOWN BELOW WITH SCAN_OK
						--THKPEND VALIDATION OF TIME PERIOD BETWEEN APPROVAL AND SCAN TIME
						--APPROVED BUT SCANNING PENDING	or Reoffer		
						If(@CurrentQueueStatus=3)
						Begin

							SET @INCORRECTMSG = 'QUARANTINE_APPROVED_RETEST_ON_PREVIOUS_STATION'
							
							SET @RETURNINT = 1
							SET @RETURNVALUE = @INCORRECTMSG

							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							COMMIT TRAN
							Return

						End
					END
					
					IF @CurrentQueueStatus = 0
					BEGIN
						Declare @strBreakID nvarchar(500)='',@TotalBreak int=0;
						select @strBreakID=isnull(BreakID,'') from #ASSY_LINEQUEUETIME_RUNNING 
						--UPDATE #ASSY_LINEQUEUETIME_RUNNING SET NextScanTimestamp=GETDATE() WHERE NextOperationcode=@OPERATIONCODE
						If(@strBreakID <> '')
						Begin 
							Insert into @BreakDetails(Breakid,BreakTime)
							Select col1,datediff(SECOND,B.BreakStartTime,B.BreakEndTime) from dbo.FN_GRID_SPLIT_STRING(@strBreakID,'',',') A inner join ASSY_BREAK_TIME B 
							on A.col1=B.BreakID  

							Select @TotalBreak=sum(BreakTime) from @BreakDetails

						End


						SELECT TOP 1 @StationQueueTime=DATEDIFF(SECOND, ResultTimestamp, Getdate()) 
						FROM #ASSY_LINEQUEUETIME_RUNNING WHERE NextOperationcode=@OPERATIONCODE
						ORDER BY ResultTimestamp DESC

						IF (@StationQueueTimemst<(@StationQueueTime - @TotalBreak))
						BEGIN
							
							SET @CurrentQueueStatus = 1
							UPDATE A SET A.QuarantineStatus=@CurrentQueueStatus, QuarantineTimeStamp=GETDATE(), A.NextScanTimestamp=Getdate()
							FROM ASSY_LINEQUEUETIME_RUNNING (NOLOCK) A 
							WHERE NextOperationcode=@OPERATIONCODE AND ISNULL(A.QuarantineStatus,0)=0 and Barcode=@Barcode

							SET @INCORRECTMSG = 'QUEUE_TIME_EXCEEDED_BARCODE_QUARANTINE'
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
							,@BARCODE = @BARCODE, @HMIMESSAGE = @INCORRECTMSG, @IsExpiredTag = 1
							
							SET @RETURNINT = 1
							SET @RETURNVALUE = @INCORRECTMSG

							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							COMMIT TRAN
							RETURN
						END

							UPDATE A SET A.QuarantineStatus=@CurrentQueueStatus, QuarantineTimeStamp=GETDATE(), A.NextScanTimestamp=Getdate()
							FROM ASSY_LINEQUEUETIME_RUNNING (NOLOCK) A INNER JOIN #ASSY_LINEQUEUETIME_RUNNING B
							ON A.ProfitCenterCode=B.ProfitCenterCode AND A.LineCode=B.LineCode AND A.Barcode=B.Barcode 
						    AND A.Datecode=B.Datecode
							WHERE B.NextOperationcode=@OPERATIONCODE AND ISNULL(A.QuarantineStatus,0)=0
					END
					
				END
			END
			--END-- ADDED BY THRAINDER ON 25TH NOV 2025 FOR QUEUE TIME MANAGEMENT

			--Start//Added By RS On 02-Apr-2020 For WIP Count Manage For Next Shift
			DELETE FROM Assy_WIP_Pending_Part_Status WHERE ProfitCenterCode = @PROFITCENTERCODE AND LineCode = @LINECODE AND Barcode = @BARCODE AND IsPrintUpdate = 1
			--End//Added By RS On 02-Apr-2020 For WIP Count Manage For Next Shift

			--RESET   INCORRECT LABEL
			UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE = '', ISINCORRECT = 0 WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
			--RESET DUPLICATE LABEL
			UPDATE ASSY_DUPLICATELABEL SET ISDUPLICATE = 0 WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE

			UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE SET BARCODE = '', ISCYCLESTARTED = 0 WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE

			IF (ISNULL(@STATIONCODE,0) = 0 OR ISNULL(@STATIONCODE,-1) = -1 OR ISNULL(@STATIONCODE,0) = 1)
			BEGIN
				SELECT @SCANNINGSTATION = 1
			END

			IF ISNULL(@SCANNINGSTATION,0) = 0
				SET @SCANNINGSTATION = 1
			IF EXISTS
			( 
				SELECT 1 FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
				-- Start - Added By RS On 20191021 DateCode Removed for WIP Logic
					--AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND BARCODE = @BARCODE
					AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND BARCODE = @BARCODE
				-- End - Added By RS On 20191021 DateCode Removed for WIP Logic
			)
			BEGIN
				-- ADDED BY RASHID ON 20TH JULY 2016 FOR PERFORMANCE
				-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
				-- SELECT @PERFORMANCEMACHINECODE = ISNULL(UPPER(LTRIM(RTRIM(PARAMETER_VALUE))), '') FROM PARAMETER_MST WITH (NOLOCK) 
				-- WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'FINALVIEWING' AND PARAMETER_C2 = 'SERVO_PERFORMANCE_MACHINECODE' AND WH_CODE = @PROFITCENTERCODE

				SELECT @PERFORMANCEMACHINECODE = ISNULL(LTRIM(RTRIM(DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'FINALVIEWING', 'SERVO_PERFORMANCE_MACHINECODE', @PROFITCENTERCODE))),'')

				IF (@OPERATIONCODE = @PERFORMANCEMACHINECODE)
				BEGIN
					UPDATE ASSY_LINEASSYSTATUS_RUNNING SET SCANTIMESTAMP = GETDATE(), STATIONCODE = @SCANNINGSTATION, RESULTTIMESTAMP = NULL, STATUS = NULL,
					Live_Datecode=@Live_Datecode,IsReworkPart=@Rework WHERE LINECODE = @LINECODE  AND MACHINECODE = @MACHINECODE AND	OPERATIONCODE = @OPERATIONCODE  AND  BARCODE = @BARCODE AND PROFITCENTERCODE = @PROFITCENTERCODE
				END
				ELSE
				BEGIN
					UPDATE ASSY_LINEASSYSTATUS_RUNNING SET SCANTIMESTAMP = GETDATE(), STATIONCODE = @SCANNINGSTATION,Live_Datecode=@Live_Datecode,IsReworkPart=@Rework WHERE LINECODE = @LINECODE  AND MACHINECODE = @MACHINECODE
						AND	OPERATIONCODE = @OPERATIONCODE  AND  BARCODE = @BARCODE AND PROFITCENTERCODE = @PROFITCENTERCODE
				END
			END
			ELSE
			BEGIN
				-- FAILCOUNT FIX FOR TWIN STATION ADDED BY RASHID ON MARCH 8, 2017
				DECLARE @FAILCOUNTBEFOREDELETEFORTWINSTATION INT = 0
				IF EXISTS (SELECT 1 FROM ASSY_LINEASSYSTATUS_RUNNING WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE AND BARCODE = @BARCODE)
				BEGIN
					SELECT @FAILCOUNTBEFOREDELETEFORTWINSTATION = ISNULL(FAILCOUNT,0) FROM ASSY_LINEASSYSTATUS_RUNNING WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE AND BARCODE = @BARCODE
					DELETE FROM ASSY_LINEASSYSTATUS_RUNNING WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE AND BARCODE = @BARCODE
				END
				IF @STMCPARTNO <> ''
					SET @PARTNUMBER = @STMCPARTNO

				--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
				INSERT INTO ASSY_LINEASSYSTATUS_RUNNING(PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE, BARCODE, DATECODE, PARTNO, ACTIVE, STATIONCODE, 
					SCANTIMESTAMP, USERID, FAILCOUNT, PRODUCTIONORDERNO, Category,Live_Datecode,IsReworkPart)
				SELECT @PROFITCENTERCODE, @LINECODE, @MACHINECODE, @OPERATIONCODE, @BARCODE, CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END, 
					@PARTNUMBER, 1, @SCANNINGSTATION, GETDATE(), @USERID, ISNULL(@FAILCOUNTBEFOREDELETEFORTWINSTATION,0), @REWORK_ORDERNO, @Category,@Live_Datecode,@Rework
				-- FAILCOUNT FIX FOR TWIN STATION ADDED BY RASHID ON MARCH 8, 2017
			END
							
			--UPDATE SCAN OK FOR DATE CODE STAMPING, IF STAMPING IS APPLICABLE FOR LINE AND PART NO.
			IF @OPERATIONCODE = @FINALVIEWING_OPERATIONCODE
			BEGIN
				EXEC ASSY_PROC_DATECODESTAMPING @CONDITION = 'UPDATE_SCANOK', @LINECODE = @LINECODE 
				, @BARCODE = @BARCODE, @PROFITCENTERCODE = @PROFITCENTERCODE		
				--Gasket Missing Check Functionality in Servo Line // Added By RS On 20180328
				--UPDATE SCAN OK FOR GASKET MISSING CHECK, IF IT IS APPLICABLE FOR LINE
				EXEC Assy_Proc_GasketMissing_Check @CONDITION = 'UPDATE_SCANOK', @LINECODE = @LINECODE
				, @BARCODE = @BARCODE, @PROFITCENTERCODE = @PROFITCENTERCODE
			END
							
			--IF (@CRIMPINGMACHINECODE ! = '' AND @CRIMPINGMACHINECODE = @MACHINECODE)
			--BEGIN
			--	IF EXISTS (SELECT TOP 1 BARCODE FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
			--			AND LINECODE = @LINECODE AND ISNULL(ISTALLYCHARTAPPROVED, 0) = 0 AND  MACHINECODE = @MACHINECODE
			--			AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END
			--			AND  ISNULL(STATUS, '') = '')
			--	BEGIN
			--		UPDATE ASSY_LINEASSYSTATUS_RUNNING SET STATUS = 'FL', FAILCOUNT = 5 
			--			WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND ISNULL(ISTALLYCHARTAPPROVED, 0) = 0
			--			AND MACHINECODE = @MACHINECODE AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END
			--			AND  ISNULL(STATUS, '') = ''
			--	END
			--END
			SET @RETURNINT = 1
			SET @RETURNVALUE = 'SCANNED_SUCCESSFULLY'

			IF @OPERATIONCODE = @FINALVIEWING_OPERATIONCODE
			BEGIN
				IF EXISTS
				(
					SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
						AND KeyType = 'IsBoreViewingMixUpRequired' AND KeyValue = '1'
				)
				BEGIN
					IF EXISTS
					(
						SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
							AND KeyType = 'IsBoreViewingValidationRequiredAtFV' AND KeyValue = '1'
					)
					BEGIN
						IF OBJECT_ID('Assy_FV_BoreView_Mapping_Status') IS NOT NULL
						BEGIN
							IF EXISTS (SELECT 1 FROM Assy_FV_BoreView_Mapping_Status WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND OperationCode = @OPERATIONCODE)
							BEGIN
								UPDATE Assy_FV_BoreView_Mapping_Status SET TSBarcode = @Barcode, MappingStatus = 1, TimeStamp = GETDATE(), Barcode = ''
									WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND OperationCode = @OPERATIONCODE
							END
							ELSE
							BEGIN
								INSERT INTO Assy_FV_BoreView_Mapping_Status(ProfitCenterCode,LineCode,Barcode,TSBarcode,MappingStatus,TimeStamp,MachineCode,OperationCode)
								SELECT @ProfitCenterCode,@LineCode,'',@Barcode,1,GETDATE(),@MACHINECODE,@OPERATIONCODE
							END
						END
					END
				END
			END

			IF @QTYLOWMESSAGE = 1
			BEGIN
				SET @RETURNVALUE = 'SCANNED_SUCCESSFULLY' + ' BUT ' + @MATFEEDREMARKSTATUS
			END
			-- SCANNING LOG BY RS ON 20170913
			INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
			SELECT @PROFITCENTERCODE, 'ASSEMBLY_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @ASSY_PARTNO, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()

			SELECT @IS_RESERVOIR_LINE =  DBO.[FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE](@ProfitCenterCode,'LINE_ATTRB','IS_RESERVOIR_LINE',@LineCode,'')
			IF((@IS_RESERVOIR_LINE='1'))			
			BEGIN
			    Insert into #tblOPCode(Row_No, col1)
			    SELECT Row_No, col1  FROM dbo.FN_GRID_SPLIT_STRING(DBO.[FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE]('0021','LINE_ATTRB','RESERVOIR_OPERATION_CODE',@LINECODE,''),'','|')
				IF EXISTS (SELECT 1 FROM #tblOPCode WHERE Col1 = @OperationCode)
				BEGIN
					UPDATE Assy_CustomerBarcode_Scan_Validation SET ModifiedTimestamp = GETDATE(), Barcode = @BARCODE
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND  OperationCode = @OPERATIONCODE
				END
			END

			COMMIT TRAN

			IF ISNULL(@ISLINKSERVERCPRUPDATE,0) = 1
			BEGIN
				-- ADDED BY RASHID ON 20TH DEC 2016 FOR CHILD PART REJECTION APP LINKAGE AND IN PRODUCTION MODE
				SET @EXECQUERY = ''
				SET @EXECQUERY = 'UPDATE ' + @LINKSERVERNAME + '.DBO.ASSY_REJECTIONACCOUNTINGREWORK_HDR SET ISASSYUSE = 1, MODIFIEDBY = ''' + @USERID + ''', 
				MODIFIEDON = CAST(GETDATE() AS VARCHAR) WHERE REJECTIONID = ' + CONVERT(VARCHAR(10),@REJECTIONID) +' AND BARCODE = ''' + @BARCODE +''''
				PRINT @EXECQUERY
				EXEC (@EXECQUERY)
			END

			END TRY
			
			BEGIN CATCH
				--Added By RS On 20180202 for rerun the transaction which is victim of Deadlock
				DECLARE @DoRetry bit; -- Whether to Retry transaction or not
				SET @DoRetry = 0;
				SET @RETURNVALUE = 	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
				CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
				CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_MESSAGE() AS VARCHAR(1500))
				ROLLBACK TRAN								
				IF ERROR_NUMBER() = 1205 -- Deadlock Error Number
				BEGIN
					SET @DoRetry = 1; -- Set @DoRetry to 1 only for Deadlock
				END
				
				IF @DoRetry = 1
				BEGIN
					SET @RetryCounter = @RetryCounter + 1 -- Increment Retry Counter By one
					IF (@RetryCounter > 2) -- Check whether Retry Counter reached to 2
					BEGIN
						SET @RETURNINT = 2
						RAISERROR(@RETURNVALUE, 16, 1)	-- Raise Error Message if 
						-- still deadlock occurred after three retries
					END
					ELSE
					BEGIN
						WAITFOR DELAY '00:00:00.05' -- Wait for 5 ms
						GOTO RETRYONDEADLOCK -- Go to Label RETRYONDEADLOCK:
					END
				END
				ELSE
				BEGIN
					SET @RETURNINT = 2
					RAISERROR(@RETURNVALUE, 16, 1)	
				END

				--SET @RETURNINT = 2
				--RAISERROR(@RETURNVALUE, 16, 1)	
			END CATCH
			
			RETURN
		END
		
		ELSE IF @CONDITION = 'POKAYOKE_FAULTBARCODE_SCANNING'
		BEGIN 
			DECLARE @EXPRESULT VARCHAR(10)	
			DECLARE @ISTESTCOMPLETED VARCHAR(20)
			
			SELECT @POKAYOKEDATECODE = DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'POKAYOKE', 'POKAYOKE_DATECODE', @PROFITCENTERCODE)

			--ADDED BY RASHID FOR POKAYOKE TWIN INDEX
			DECLARE @SCANNEDSTATIONINDEX INT = 0
			SET @SCANNEDSTATIONINDEX = (SELECT DBO.ASSY_FNGETSCANNEDSTATIONINDEX(@LINECODE, @OPERATIONCODE))

			IF(@SCANNEDSTATIONINDEX = -1)
			BEGIN
				IF NOT EXISTS
				(
				SELECT 1 FROM ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE WITH (NOLOCK) WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE
				)
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'NO_PENDING_RECORD_FOR_DECLARING_AS_FAULT'	
					
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'NO_PENDING_RECORD_FOR_DECLARING_AS_FAULT'
					RETURN
				END
				
				--CHECK IF CYCLE START HAS NOT PRESSED, SIMPLY RETURN
				ELSE IF EXISTS
				(
					SELECT 1 FROM ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE WITH (NOLOCK) WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE 
						AND OPERATIONCODE = @OPERATIONCODE AND (ISNULL(BARCODE, '') = '' OR CHARINDEX(@POKAYOKEDATECODE, ISNULL(BARCODE, '')) = 0 OR ISNULL(ISCYCLESTARTED, 0) = 0)
				)
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'YOU_CANT_DECLARE_A_PART_AS_FAULT_BECAUSE_TESTING_NOT_START'					
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'YOU_CANT_DECLARE_A_PART_AS_FAULT_BECAUSE_TESTING_NOT_START'
					RETURN
				END
			END
			ELSE
			BEGIN
				DECLARE @INSIDESTATIONINDEX INT;
				IF(@SCANNEDSTATIONINDEX = 1)
					SET @INSIDESTATIONINDEX = 2
				ELSE IF(@SCANNEDSTATIONINDEX = 2)
					SET @INSIDESTATIONINDEX = 1
					
				IF NOT EXISTS
				(
					SELECT 1 FROM ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE WITH (NOLOCK) 
						WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND STATIONCODE = @INSIDESTATIONINDEX
				)
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'NO_PENDING_RECORD_FOR_DECLARING_AS_FAULT'

					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'NO_PENDING_RECORD_FOR_DECLARING_AS_FAULT'
					RETURN
				END
				
				--CHECK IF CYCLE START HAS NOT PRESSED, SIMPLY RETURN
				ELSE IF EXISTS
				(
					SELECT 1 FROM ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE WITH (NOLOCK) WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE 
						AND OPERATIONCODE = @OPERATIONCODE AND STATIONCODE = @INSIDESTATIONINDEX
							AND (ISNULL(BARCODE, '') = '' OR CHARINDEX(@POKAYOKEDATECODE, ISNULL(BARCODE, '')) = 0 OR ISNULL(ISCYCLESTARTED, 0) = 0)
				)
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'YOU_CANT_DECLARE_A_PART_AS_FAULT_BECAUSE_TESTING_NOT_START.'	
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'YOU_CANT_DECLARE_A_PART_AS_FAULT_BECAUSE_TESTING_NOT_START'
					RETURN
				END
			END
				
			--IF IT IS A SINGLE JIG STATION
			IF(@SCANNEDSTATIONINDEX = -1)
			BEGIN
				IF EXISTS
				(
					SELECT  1 FROM ASSY_STATIONS_ZIG_IN_OUT_STATUS WITH (NOLOCK) WHERE LINECODE = @LINECODE  AND OPERATIONCODE = @OPERATIONCODE AND ISNULL(STATUSINOUT, 0) = 1
				)
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'YOU_CANT_DECLARE_A_PART_AS_FAULT_BECAUSE_JIG_IS_IN'
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'YOU_CANT_DECLARE_A_PART_AS_FAULT_BECAUSE_JIG_IS_IN'
					RETURN
				END
			END

			SELECT @BARCODE = S.BARCODE FROM ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE S WITH (NOLOCK) JOIN ASSY_LINEASSYSTATUS_RUNNING A WITH (NOLOCK) 
				ON S.LINECODE = A.LINECODE AND S.MACHINECODE = A.MACHINECODE AND S.OPERATIONCODE = A.OPERATIONCODE AND S.BARCODE = A.BARCODE 
					WHERE S.LINECODE = @LINECODE AND S.MACHINECODE = @MACHINECODE 
						AND S.OPERATIONCODE = @OPERATIONCODE AND ISNULL(A.STATUS, '') = ''
			--IF SCANNED BARCODE EXPECTED  RESULT IS NOT  FAIL RETURN

			SELECT @EXPRESULT = ISNULL(EXPRESULT, '') FROM ASSY_POKAYOKE WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE  
				AND MACHINECODE = @MACHINECODE	AND ISNULL(ISACTIVE, 0) = 1 AND BARCODE = @BARCODE

			IF @EXPRESULT = 'PASS'
			BEGIN
				SELECT @RETURNINT = 1, @RETURNVALUE = 'YOU_CANT_DECLARE_A_PART_AS_FAULT_BECAUSE_EXP_RESULT_IS_PASS'
				EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
				, @BARCODE = @BARCODE, @HMIMESSAGE = 'YOU_CANT_DECLARE_A_PART_AS_FAULT_BECAUSE_EXP_RESULT_IS_PASS'
				RETURN
			END
			ELSE IF @EXPRESULT = 'FAIL'
			BEGIN
				EXEC [ASSY_PROC_UPDATEPOKAYOKESTATUS] @CONDITION = 'UPDATE_POKA_YOKE_RESULT', @PROFITCENTERCODE = @PROFITCENTERCODE, @LINECODE = @LINECODE
				, @OPERATIONCODE = @OPERATIONCODE, @MACHINECODE = @MACHINECODE, @PLCRESULT = 'FAULT', @BARCODE = @BARCODE, @USERID = @USERID, @ISFAULTBARCODESCANNED = 1						
						
				IF @SCANNEDSTATIONINDEX = -1
				BEGIN
					UPDATE ASSY_SCAN_OK SET	BARCODE = '' WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE
					
					UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE SET BARCODE = '', ISCYCLESTARTED = 0 
						WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE
				END
				ELSE
				BEGIN
					UPDATE ASSY_SCAN_OK SET	BARCODE = '' WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE
						AND STATIONCODE = @INSIDESTATIONINDEX
					
					UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE SET BARCODE = '', ISCYCLESTARTED = 0 
						WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE	AND STATIONCODE = @INSIDESTATIONINDEX
				END

				SELECT @RETURNINT = 1, @RETURNVALUE = 'PART_HAS_BEEN_SUCCESSFULLY_DECLARED_AS_FAULT'
			END
			ELSE IF @EXPRESULT = 'FAULT'				
			BEGIN
				EXEC [ASSY_PROC_UPDATEPOKAYOKESTATUS] @CONDITION = 'UPDATE_POKA_YOKE_COMPELETE_FOR_FAULT_PART', @PROFITCENTERCODE = @PROFITCENTERCODE
				, @LINECODE = @LINECODE, @MACHINECODE = @MACHINECODE, @OPERATIONCODE = @OPERATIONCODE, @BARCODE = @BARCODE, @ISTESTCOMPLETED = @ISTESTCOMPLETED OUT											
				
				IF @ISTESTCOMPLETED = 'NO'
				BEGIN
					IF NOT EXISTS (SELECT 1 FROM ASSY_RESULT (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OPERATIONCODE)
					BEGIN
						INSERT INTO ASSY_RESULT(LineCode,OperationCode,StationCode,Barcode)
						SELECT @LineCode,@OPERATIONCODE,'1',@Barcode
					END
					ELSE
					BEGIN
						UPDATE ASSY_RESULT SET BARCODE = @BARCODE WHERE OPERATIONCODE = @OPERATIONCODE
					END
							
					IF @SCANNEDSTATIONINDEX = -1
					BEGIN
						UPDATE ASSY_SCAN_OK SET BARCODE = '' WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE
							AND OPERATIONCODE = @OPERATIONCODE
						UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE SET BARCODE = '', ISCYCLESTARTED = 0 
							WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE
					END
					ELSE
					BEGIN
						UPDATE ASSY_SCAN_OK SET BARCODE = '' WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE
							AND OPERATIONCODE = @OPERATIONCODE AND STATIONCODE = @INSIDESTATIONINDEX
						UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE SET BARCODE = '', ISCYCLESTARTED = 0 
							WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND STATIONCODE = @INSIDESTATIONINDEX
					END
				END

				SELECT @RETURNINT = 1, @RETURNVALUE = 'PART_HAS_BEEN_SUCCESSFULLY_DECLARED_AS_FAULT'	
			END
		END

		ELSE IF @CONDITION = 'GET_TAGS'
		BEGIN
		    IF @PROFITCENTERCODE in ('0088','0064')
			BEGIN
			     EXEC ASSY_PROC_FINALVIEWING_BIJ @CONDITION='GET_TAGS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
				 RETURN
			END
			 ELSE IF @PROFITCENTERCODE in ('0018','0030','0068')
			BEGIN
			     EXEC ASSY_PROC_FINALVIEWING_ABS @CONDITION='GET_TAGS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
				 RETURN
			END
		     
			--SHOW VISION SYSTEM LAST PRINTED BARODE
			SET @FV_OP_CODE = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)
			-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
			-- SELECT TOP 1 @OPERATIONSEQNO = L.OPERATIONSEQNO FROM ROUTINGCONFIGLINEWISE (NOLOCK) L
			SELECT @OPERATIONSEQNO = L.OPERATIONSEQNO FROM ROUTINGCONFIGLINEWISE (NOLOCK) L
				INNER JOIN ROUTINGCONFIGPARTWISE (NOLOCK) P
					ON L.OPERATIONCODE = P.OPERATIONCODE 
						AND L.MACHINECODE = P.MACHINECODE 
							WHERE L.LINECODE = @LINECODE
								-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
								-- AND P.PARTNO = (SELECT TOP 1 ASSY_PARTNO FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE ORDER BY CREATEDDATE DESC)
								AND P.PARTNO = @ASSY_PARTNO
									AND L.TRACEABILITY = 1
										AND P.TRACEABILITY = 1
											-- ADDED BY RASHID FOR HANDLING ENGRAVING STATION ON 10TH SEP 2016
											AND ISNULL(L.ENGRAVING, 0) = 0 AND ISNULL(P.ENGRAVING, 0) = 0
												AND L.OPERATIONCODE = @OPERATIONCODE 
													AND P.OPERATIONCODE = @OPERATIONCODE
													-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
													-- ORDER BY L.OPERATIONSEQNO 					 
					
			SELECT @LINETYPECODE = LTM.LINETYPENAME  FROM LINEMST (NOLOCK) LM 
				INNER JOIN LINETYPEMST (NOLOCK) LTM 
					ON LM.LINETYPECODE = LTM.LINETYPECODE
						WHERE LM.LINECODE = @LINECODE						
					
			IF @OPERATIONSEQNO = 1
			BEGIN	
				SELECT @OPERATIONNAME = OPERATIONNAME FROM  OPERATIONMST (NOLOCK) 
					WHERE OPERATIONCODE = @OPERATIONCODE AND ISACTIVE = 1
							
				SELECT TOP 1 @OPERATIONNAME AS OPERATIONNAME, LPB.BARCODE, '' AS TAGNAME, '' AS VALUE, 'PASS' AS RESULT, '' AS UOM FROM ASSY_VISION_SYSTEM_LAST_PRINTED_BARCODE (NOLOCK) LPB
				RETURN
			END

			IF @OPERATIONCODE = @FV_OP_CODE
			BEGIN
				SELECT TOP 1  OPMST.OPERATIONNAME, ASSY.BARCODE, ''TAGNAME, ASSY.VALUE, CASE WHEN ISNULL(ASSY.RESULT, '') = 'PS' THEN 'PASS' WHEN ISNULL(ASSY.RESULT, '') = 'FL' THEN 'FAIL' END RESULT
				, '' UOM   FROM 
				(									
				SELECT LINECODE, OPERATIONCODE, BARCODE, '' AS TAGNAME, '' AS VALUE, TIMESTAMP, RESULT  FROM ASSY_LINEASSYPARAMDATA_RUNNING (NOLOCK) 
				WHERE OPERATIONCODE = @OPERATIONCODE
				)ASSY							
				INNER JOIN OPERATIONMST (NOLOCK) OPMST ON  ASSY.OPERATIONCODE = OPMST.OPERATIONCODE 
					WHERE ASSY.LINECODE = @LINECODE AND ASSY.OPERATIONCODE = @OPERATIONCODE ORDER BY TIMESTAMP DESC
				RETURN
			END

			SELECT TOP 8  OPMST.OPERATIONNAME, ASSY.BARCODE, TAG.TAGDESCRIPTION TAGNAME, ASSY.VALUE
			, CASE WHEN ISNULL(ASSY.RESULT, '') = 'PS' THEN 'PASS' WHEN ISNULL(ASSY.RESULT, '') = 'FL' THEN 'FAIL' END RESULT, ISNULL( TAG.UOM, '') UOM FROM 
			(
				SELECT A.LINECODE, A.OPERATIONCODE, A.BARCODE, B.TAGID, B.VALUE, A.TIMESTAMP, A.RESULT  FROM ASSY_LINEASSYPARAMDATA_RUNNING A  WITH (NOLOCK) 
				INNER JOIN ASSY_LINEASSYPARAMDATA_RUNNING_DTL B WITH (NOLOCK) ON A.UID = B.UID
			)ASSY
			JOIN TAGMST (NOLOCK) TAG ON ASSY.TAGID = TAG.TAGID AND TAG.ISACTIVE = 1 
				INNER JOIN OPERATIONMST (NOLOCK) OPMST ON  ASSY.OPERATIONCODE = OPMST.OPERATIONCODE 
					WHERE ASSY.LINECODE = @LINECODE  AND ASSY.OPERATIONCODE = @OPERATIONCODE 
						--AND TAG.TAGNAME IN(SELECT TAGNAME FROM ASSY_PLC_PARAMETERS_TAGS (NOLOCK) )
							ORDER BY TIMESTAMP DESC
					RETURN
		END

		ELSE IF @CONDITION = 'GET_PLCADDRESS'
		BEGIN
		    IF @PROFITCENTERCODE in ('0088','0064')
			BEGIN
			     EXEC ASSY_PROC_FINALVIEWING_BIJ @CONDITION='GET_PLCADDRESS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE, @RETURNINT=@RETURNINT, @RETURNVALUE=@RETURNVALUE OUT
				 RETURN
			END
			ELSE IF @PROFITCENTERCODE in ('0018','0030','0068')			
			BEGIN
			     EXEC ASSY_PROC_FINALVIEWING_ABS @CONDITION='GET_PLCADDRESS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE
				 RETURN
			END

			SET @FV_OP_CODE = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)
			
			SELECT @FIRSTSTATIONCODE = OPERATIONCODE FROM ROUTINGCONFIGLINEWISE (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE AND OPERATIONSEQNO = 1 AND TRACEABILITY = 1

			SELECT R.LINECODE, O.OPERATIONNAME, O.OPERATIONCODE, STATIONCODE, R.MACHINECODE, M.MACHINENAME, M.PLCADDRESS FROM
			(
				SELECT L.LINECODE, L.OPERATIONCODE, L.OPERATIONSEQNO, P.PARTNO, MD.STATIONCODE, P.MACHINECODE   FROM ROUTINGCONFIGLINEWISE (NOLOCK) L 
				INNER JOIN ROUTINGCONFIGPARTWISE (NOLOCK) P 
				ON L.PROFITCENTERCODE = P.PROFITCENTERCODE AND L.OPERATIONCODE = P.OPERATIONCODE   AND L.MACHINECODE = P.MACHINECODE
				INNER JOIN MACHINEDTL MD ON L.OPERATIONCODE = MD.OPERATIONCODE AND L.LINECODE = MD.LINECODE 	
				WHERE L.LINECODE = @LINECODE  
				-- AND P.PARTNO = (SELECT TOP 1 ASSY_PARTNO  FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE ORDER BY CREATEDDATE DESC )
				AND P.PARTNO = @ASSY_PARTNO
				AND	L.TRACEABILITY = 1
				AND P.TRACEABILITY = 1
				-- ADDED BY RASHID FOR HANDLING ENGRAVING STATION ON 10TH SEP 2016
				AND ISNULL(L.ENGRAVING, 0) = 0 AND ISNULL(P.ENGRAVING, 0) = 0
			)R
			INNER JOIN OPERATIONMST (NOLOCK) O ON O.OPERATIONCODE = R.OPERATIONCODE 
			LEFT OUTER JOIN MACHINEMST (NOLOCK) M ON M.MACHINECODE = R.MACHINECODE
			WHERE O.OPERATIONCODE NOT IN (@FIRSTSTATIONCODE, @FV_OP_CODE)
			ORDER BY R.OPERATIONSEQNO 
			
			SELECT @RETURNINT = 1, @RETURNVALUE = 'SUCCESS'
			RETURN
		END
		
		ELSE IF @CONDITION = 'GET_SHOWRESULT_DATA'
		BEGIN				
			SELECT RES.LINECODE, RES.OPERATIONCODE, RUN.MACHINECODE, ''STATIONCODE, RUN.BARCODE, RUN.STATUS    FROM ASSY_RESULT (NOLOCK) RES
				INNER JOIN ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) RUN ON RES.LINECODE = RUN.LINECODE AND	RES.OPERATIONCODE = RUN.OPERATIONCODE
					AND RES.BARCODE = RUN.BARCODE
						WHERE  ISNULL(RES.BARCODE, '') <> '' AND (ISNULL(RUN.STATUS, '') <> '' OR CHARINDEX('PKYK', RUN.BARCODE) > 0)
			UNION
			SELECT  LINECODE, OPERATIONCODE, '' MACHINECODE, STATIONCODE, BARCODE, '' STATUS FROM ASSY_RESULT (NOLOCK) RES	WHERE  STATIONCODE = 'PKYK'
			
			UPDATE ASSY_RESULT SET BARCODE = '', STATIONCODE = '' WHERE  ISNULL(BARCODE, '') <> '' OR ISNULL(STATIONCODE, '') = 'PKYK'
			
			SELECT @RETURNINT = 1, @RETURNVALUE = 'SUCCESS' 
			RETURN
		END

		ELSE IF @CONDITION = 'GETPARAMETERS'
		BEGIN
			SELECT RTRIM(LTRIM( PARAMETER_C1)) PARAMETER_C1, RTRIM(LTRIM( PARAMETER_C2)) PARAMETER_C2, RTRIM(LTRIM (PARAMETER_NM)) PARAMETER_NM, LTRIM(RTRIM(PARAMETER_VALUE)) PARAMETER_VALUE 
			FROM PARAMETER_MST (NOLOCK) WHERE PARAMETER_C = 'ASSLINE' AND WH_CODE = @PROFITCENTERCODE

			SELECT @RETURNVALUE = 'DATA SELECTED', @RETURNINT = 1
			RETURN
		END

		ELSE IF @CONDITION = 'STATION_ORDERS'
		BEGIN
			-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
			SELECT @ASSY_PARTNO = ASSY_PARTNO  FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE; --AND PROFITCENTERCODE = @PROFITCENTERCODE
					
			SELECT O.OPERATIONCODE, R.OPERATIONSEQNO, O.OPERATIONNAME FROM 
			(			
				SELECT L.LINECODE, L.OPERATIONCODE, L.OPERATIONSEQNO, P.PARTNO  FROM ROUTINGCONFIGLINEWISE (NOLOCK) L 
				INNER JOIN ROUTINGCONFIGPARTWISE (NOLOCK) P 
				ON L.PROFITCENTERCODE = P.PROFITCENTERCODE AND L.OPERATIONCODE = P.OPERATIONCODE AND L.MACHINECODE = P.MACHINECODE
				WHERE L.LINECODE = @LINECODE AND
				L.OPERATIONREQUIRED = 1 AND L.TRACEABILITY = 1
				AND P.OPERATIONREQUIRED = 1 AND P.TRACEABILITY = 1
				-- ADDED BY RASHID FOR HANDLING ENGRAVING STATION ON 10TH SEP 2016
				AND ISNULL(L.ENGRAVING, 0) = 0 AND ISNULL(P.ENGRAVING, 0) = 0
				-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
				-- AND P.PARTNO = (SELECT TOP 1 ASSY_PARTNO FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE LINECODE = @LINECODE AND ASSY_MODE IN ('PRODUCTION', 'REWORK') ORDER BY CREATEDDATE DESC)
				AND P.PARTNO = @ASSY_PARTNO
			) R
			INNER JOIN OPERATIONMST (NOLOCK) O ON O.OPERATIONCODE = R.OPERATIONCODE  
			ORDER BY R.OPERATIONSEQNO
			
			SELECT @RETURNINT = 1, @RETURNVALUE = 'SUCCESS'
			RETURN
		END
		
		ELSE IF @CONDITION = 'GET_ACTIVE_STATION'
		BEGIN
			
			IF @PROFITCENTERCODE in ('0088','0064')
			BEGIN
			     EXEC ASSY_PROC_FINALVIEWING_BIJ @CONDITION='GET_ACTIVE_STATION',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@RETURNINT=@RETURNINT OUT,@RETURNVALUE=@RETURNVALUE OUT
				 RETURN
			END
			ELSE IF @PROFITCENTERCODE in ('0018','0030','0068')
			BEGIN
			     EXEC ASSY_PROC_FINALVIEWING_ABS @CONDITION='GET_ACTIVE_STATION',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@RETURNINT=@RETURNINT OUT,@RETURNVALUE=@RETURNVALUE OUT
				 RETURN
			END
			-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
			SELECT @ASSY_PARTNO = ASSY_PARTNO  FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE; --AND PROFITCENTERCODE = @PROFITCENTERCODE;

			WITH R(PROFITCENTERCODE, LINECODE, OPERATIONCODE, OPERATIONSEQNO, PARTNO, STATIONCODE)
			AS
			(
				SELECT L.PROFITCENTERCODE, L.LINECODE, L.OPERATIONCODE, L.OPERATIONSEQNO, P.PARTNO, '' AS STATIONCODE   FROM ROUTINGCONFIGLINEWISE (NOLOCK) L 
				INNER JOIN ROUTINGCONFIGPARTWISE (NOLOCK) P 
				ON L.PROFITCENTERCODE = P.PROFITCENTERCODE AND L.OPERATIONCODE = P.OPERATIONCODE   AND L.MACHINECODE = P.MACHINECODE
				WHERE L.LINECODE = @LINECODE
				-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
				-- AND P.PARTNO = (SELECT TOP 1 ASSY_PARTNO FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE LINECODE = @LINECODE ORDER BY CREATEDDATE DESC)
				AND P.PARTNO = @ASSY_PARTNO
				AND L.TRACEABILITY = 1
				AND P.TRACEABILITY = 1
				-- ADDED BY RASHID FOR HANDLING ENGRAVING STATION ON 10TH SEP 2016
				AND ISNULL(L.ENGRAVING, 0) = 0 AND ISNULL(P.ENGRAVING, 0) = 0
				AND L.PROFITCENTERCODE = @PROFITCENTERCODE
			)				
			SELECT LINECODE, O.OPERATIONNAME, OPERATIONSEQNO, PARTNO, O.OPERATIONCODE, STATIONCODE FROM R WITH (NOLOCK) 
			INNER JOIN OPERATIONMST (NOLOCK) O ON O.OPERATIONCODE = R.OPERATIONCODE AND O.PROFITCENTERCODE = R.PROFITCENTERCODE
			ORDER BY R.OPERATIONSEQNO

			SELECT @RETURNINT = 1, @RETURNVALUE = 'SUCCESS'
			RETURN
		END

		ELSE IF @CONDITION = 'GET_MACHINE_DTL'
		BEGIN
			SELECT LINECODE, MACHINECODE, OPERATIONCODE, STATIONCODE   FROM MACHINEDTL (NOLOCK) WHERE PREFIX = @PREFIX AND SUFFIX = @SUFFIX
				AND LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE

			SELECT @RETURNINT = 1, @RETURNVALUE = 'SUCCESS'
			RETURN
		END

		ELSE IF @CONDITION = 'GET_CONTROLLER_PORT_NAME'		
		BEGIN
			SELECT @RETURNVALUE = DBO.ASSY_FN_GET_COMPORT_NAME(@PROFITCENTERCODE, @LINECODE, @OPERATIONCODE, 'CONTROLLER', 'SERIALPORT')
			SET @RETURNINT = 1			     							
			RETURN
		END

		ELSE IF @CONDITION = 'GET_FV_BT_SCANNER_PORT_NAME'		
		BEGIN
			SELECT @RETURNVALUE = DBO.ASSY_FN_GET_COMPORT_NAME(@PROFITCENTERCODE, @LINECODE, @OPERATIONCODE, 'FINALVIEWINGBLUETOOTHSCANNER', 'SERIALPORT')
			SET @RETURNINT = 1
		RETURN
		END

		ELSE IF @CONDITION = 'GET_FV_RS232_SCANNER_PORT_NAME'		
		BEGIN
			SELECT @RETURNVALUE = DBO.ASSY_FN_GET_COMPORT_NAME(@PROFITCENTERCODE, @LINECODE, @OPERATIONCODE, 'FINALVIEWINGRS232SCANNER', 'SERIALPORT')
			
			SET @RETURNINT = 1			  
			RETURN
		END
		 --ADDED BY RAVI ON 18-05-16
		 IF @CONDITION='GET_FV_RFID_READER_PORT_NAME'		
		 BEGIN
				SELECT @RETURNVALUE=DBO.ASSY_FN_GET_COMPORT_NAME(@PROFITCENTERCODE,@LINECODE,@OPERATIONCODE ,'RFIDREADER','')
				SET @RETURNINT=1			  
				 RETURN
		 END
		ELSE IF @CONDITION = 'CHECK_HARDWARE_PUSHBUTTON_ENABLED'		
		BEGIN
			SELECT @RETURNVALUE = CONVERT(VARCHAR(50), ISNULL(FINALVIEWINGHWPUSHBUTTON, 0)) FROM ROUTINGCONFIGLINEWISE (NOLOCK) 
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND TRACEABILITY = 1
			
			SET @RETURNINT = 1
			RETURN
		END
		
		ELSE IF @CONDITION = 'MACHINEDTL'		
		BEGIN
			SELECT MACHINECODE, OPERATIONCODE, PREFIX, SUFFIX FROM MACHINEDTL (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
				AND(ISNULL(PREFIX, '') <> '' AND ISNULL(SUFFIX, '') <> '')
					ORDER BY MACHINECODE, OPERATIONCODE 
			
			SELECT @RETURNINT = 1, @RETURNVALUE = 'SUCCESS'
			RETURN
		END

		ELSE IF @CONDITION = 'UPDATE_FINALVIEWING_PASS_STATUS'		
		BEGIN
			BEGIN TRY
				IF @PRNGroupCode = 'GC_TML'
				BEGIN
					IF EXISTS (SELECT 1 FROM Assy_FinalViewing_RFID_Barcode_Mapping (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @BARCODE)
					BEGIN
						SELECT @NBarcode = BARCODE FROM Assy_FinalViewing_RFID_Barcode_Mapping (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @BARCODE
						SET @BARCODE = @NBarcode
					END
				END
				ELSE IF @PRNGroupCode IN ('GC_DUSTER_LINE_6_7','GC_NISSAN_LINE_6_7')
				BEGIN
					SET @ISLINE6 = 1
				END

				/*
				Declare @WakiLogicFlg BIT  = 0
				--Waki Customer Barcode Data - Added By RS On 20180828 For Waki Non-Mahindra Logic
				IF EXISTS
				(
					SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
						AND KeyType = 'WakiLogic' AND KeyValue = '1'
				)
				BEGIN
					SET @WakiLogicFlg = 1
					IF EXISTS (SELECT 1 FROM Assy_FinalViewing_RFID_Barcode_Mapping (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @BARCODE)
					BEGIN
						SELECT @NBarcode = BARCODE FROM Assy_FinalViewing_RFID_Barcode_Mapping (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @BARCODE
						SET @BARCODE = @NBarcode
					END
				END
				ELSE
					SET @WakiLogicFlg = 0
				*/

			    IF @PROFITCENTERCODE in ('0088','0064')
				BEGIN
						EXEC ASSY_PROC_FINALVIEWING_BIJ @CONDITION='UPDATE_FINALVIEWING_PASS_STATUS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@MACHINECODE=@MACHINECODE
						,@OPERATIONCODE=@OPERATIONCODE,@BARCODE=@BARCODE,@USERID=@USERID
						,@RETURNINT=@RETURNINT OUT,@RETURNVALUE=@RETURNVALUE OUT
						RETURN
				END
				ELSE IF @PROFITCENTERCODE in ('0018','0030','0068')
				BEGIN
						EXEC ASSY_PROC_FINALVIEWING_ABS @CONDITION='UPDATE_FINALVIEWING_PASS_STATUS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@MACHINECODE=@MACHINECODE
						,@OPERATIONCODE=@OPERATIONCODE,@BARCODE=@BARCODE,@USERID=@USERID
						,@RETURNINT=@RETURNINT OUT,@RETURNVALUE=@RETURNVALUE OUT
						RETURN
				END  

			BEGIN TRAN
			
			IF (CHARINDEX(':', @BARCODE) <> 0 OR (ISNULL(@ISLINE6, 0) = 1 AND CHARINDEX(@ASSY_PARTNO, @BARCODE) <> 0)) AND ISNULL(@BARCODE, '') <> '' 
			BEGIN
				SET @ISSTMC = 1
				SELECT @LINECODE_STMC = ISNULL(LINECODE, ''), @DATECODE_TEMP = ISNULL(DATECODE, '')  FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) 
					WHERE  PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE  AND BARCODE = @BARCODE  
				
				SET @DATECODE = @DATECODE_TEMP
				
				IF(@LINECODE_STMC) <> ''
				BEGIN
					-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
					-- SELECT DISTINCT @PARTNUMBER = ISNULL(STMC_PART_NO, ''), @DATECODE = DATECODE FROM ASSY_COUPLINGDETAILS (NOLOCK) 
					SELECT @PARTNUMBER = ISNULL(STMC_PART_NO, ''), @DATECODE = DATECODE FROM ASSY_COUPLINGDETAILS (NOLOCK) 
						WHERE FG_BARCODE = @BARCODE AND LINECODE = @LINECODE AND PROFITCENTRECODE = @PROFITCENTERCODE
				END
				ELSE
				BEGIN
					-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
					-- SELECT DISTINCT @PARTNUMBER = ISNULL(STMC_PART_NO, ''), @LINECODE_STMC = LINECODE, @DATECODE = DATECODE FROM ASSY_COUPLINGDETAILS (NOLOCK) 
					SELECT @PARTNUMBER = ISNULL(STMC_PART_NO, ''), @LINECODE_STMC = LINECODE, @DATECODE = DATECODE FROM ASSY_COUPLINGDETAILS (NOLOCK) 
						WHERE FG_BARCODE = @BARCODE AND LINECODE = @LINECODE AND PROFITCENTRECODE = @PROFITCENTERCODE
				END
			END
			ELSE IF @ISSTMC = 0 AND ISNULL(@BARCODE, '') <> '' 
			BEGIN
				--GET DATECODE AND PART NO OF SNANNED BARCODE FROM VISION SYSTEM
				SELECT @PARTNUMBER = PARTNO, @DATECODETEMP = DATECODE FROM ASSY_FN_GET_BARCODEPARTS_FROM_BARCODE(@PROFITCENTERCODE, @LINECODE, @BARCODE)
				
				SET @DATECODE = @DATECODETEMP
			END

			--Start-Added By RS On Bawal Site 29-Jan-2020
			IF ISNULL(@DATECODE,'') = ''
			BEGIN
				SELECT @DATECODE = Datecode FROM Assy_RunningPart (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE AND LineCode = @LINECODE
			END
			--End-Added By RS On Bawal Site 29-Jan-2020

			IF ISNULL(@DATECODE,'') = ''
			BEGIN
				SELECT @RETURNINT = 2, @RETURNVALUE = 'Date Code Empty. Re-run the process.'
				ROLLBACK TRAN
				RETURN
			END

			SELECT @FAILCOUNT = ISNULL(FAILCOUNT, 0)  FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE BARCODE = @BARCODE 
				AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND STATUS = 'FL'	

			UPDATE ASSY_LINEASSYSTATUS_RUNNING SET STATUS = 'PS', RESULTTIMESTAMP = GETDATE(),datecode= @DATECODE,Live_Datecode=@Live_Datecode
				WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND BARCODE = @BARCODE						
			
			--CLEAR SCAN OK BARCODE FROM ASSY_SCANOK
			UPDATE ASSY_SCAN_OK SET BARCODE = '', ISSCAN = 0  WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE
			
			-- Modified By RS On 20181213 - ScanTimeStamp Value is capturing
			SELECT @FVScanTimeStamp = ScanTimeStamp,@ProductionOrderNo=ISNULL(ProductionOrderNo,'')  FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE BARCODE = @BARCODE
				AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE

			--INSERT PASS DATA INTO ASSY_LINEASSYPARAMDATA_RUNNING TABLE
			INSERT INTO ASSY_LINEASSYPARAMDATA_RUNNING
			(
				PROFITCENTERCODE
				, LINECODE
				, MACHINECODE
				, OPERATIONCODE
				, STATIONCODE
				, BARCODE
				, RESULT
				, DATECODE
				, PARTNO
				, USERID
				, TIMESTAMP
				, ScanTimestamp
				,Live_Datecode
			)
			SELECT 
				@PROFITCENTERCODE 
				, @LINECODE 
				, @MACHINECODE 
				, @OPERATIONCODE
				, @STATIONCODE
				, @BARCODE
				, 'PS'
				, @DATECODE
				, @PARTNUMBER
				, @USERID 
				, GETDATE()
				, @FVScanTimeStamp
				,@live_datecode
			
			IF(@ISSTMC = 0)
			BEGIN
				--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
				INSERT INTO ASSY_LINEASSYSTATUS
				(
					PROFITCENTERCODE, 
					LINECODE, 
					MACHINECODE, 
					OPERATIONCODE, 
					STATIONCODE, 
					BARCODE, 
					STATUS, 
					FAILCOUNT, 
					DATECODE, 
					PARTNO, 
					SCANTIMESTAMP, 
					RESULTTIMESTAMP, 
					USERID,
					PRODUCTIONORDERNO,
					Category,
					Live_Datecode,
					IsReworkPart
				)

				SELECT 
					PROFITCENTERCODE, 
					LINECODE, 
					MACHINECODE, 
					OPERATIONCODE, 
					STATIONCODE, 
					BARCODE, 
					STATUS, 
					FAILCOUNT, 
					DATECODE, 
					PARTNO, 
					SCANTIMESTAMP, 
					RESULTTIMESTAMP, 
					USERID,
					PRODUCTIONORDERNO,
					Category,
					Live_Datecode,
					IsReworkPart
				FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE AND BARCODE = @BARCODE	
			END
			ELSE
			BEGIN
				SELECT CHILD_BARCODE, PART_TYPE INTO #CHILD_BARCODE FROM ASSY_COUPLINGDETAILS (NOLOCK) WHERE FG_BARCODE = @BARCODE

				IF EXISTS (SELECT 1 FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE BARCODE IN (SELECT CHILD_BARCODE FROM #CHILD_BARCODE WHERE PART_TYPE = 'TMC') AND PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE)
				BEGIN
					INSERT INTO ASSY_LINEASSYSTATUS_HISTORY (PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE, STATIONCODE, BARCODE, STATUS, FAILCOUNT, DATECODE, PARTNO,
						SCANTIMESTAMP, RESULTTIMESTAMP, USERID,PRODUCTIONORDERNO, His_ENT_DT, His_ENT_BY, Active, Category)
					SELECT PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE, STATIONCODE, BARCODE, STATUS, FAILCOUNT, DATECODE, PARTNO,
						SCANTIMESTAMP, RESULTTIMESTAMP, USERID, PRODUCTIONORDERNO, GETDATE(), @USERID, 1, Category
						FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND BARCODE IN (SELECT CHILD_BARCODE FROM #CHILD_BARCODE WHERE PART_TYPE = 'TMC')

					DELETE FROM ASSY_LINEASSYSTATUS WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND BARCODE IN (SELECT CHILD_BARCODE FROM #CHILD_BARCODE WHERE PART_TYPE = 'TMC')
				END

				--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
				INSERT INTO ASSY_LINEASSYSTATUS
				(
					PROFITCENTERCODE, 
					LINECODE, 
					MACHINECODE, 
					OPERATIONCODE, 
					STATIONCODE, 
					BARCODE, 
					STATUS, 
					FAILCOUNT, 
					DATECODE, 
					PARTNO, 
					SCANTIMESTAMP, 
					RESULTTIMESTAMP, 
					USERID,
					PRODUCTIONORDERNO,
					Category,
					Live_Datecode,
					IsReworkPart
				)

				SELECT 
					PROFITCENTERCODE, 
					LINECODE, 
					MACHINECODE, 
					OPERATIONCODE, 
					STATIONCODE, 
					BARCODE, 
					STATUS, 
					FAILCOUNT, 
					DATECODE, 
					PARTNO, 
					SCANTIMESTAMP, 
					RESULTTIMESTAMP, 
					USERID,
					PRODUCTIONORDERNO,
					Category,
					Live_Datecode,
					IsReworkPart
				FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE AND BARCODE = @BARCODE

				UNION

				SELECT 
					PROFITCENTERCODE, 
					LINECODE, 
					MACHINECODE, 
					OPERATIONCODE, 
					STATIONCODE, 
					BARCODE, 
					STATUS, 
					FAILCOUNT, 
					DATECODE, 
					PARTNO, 
					SCANTIMESTAMP, 
					RESULTTIMESTAMP, 
					USERID,
					PRODUCTIONORDERNO,
					Category,
					Live_Datecode,
					IsReworkPart
				FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
				--AND BARCODE IN (SELECT CHILD_BARCODE FROM ASSY_COUPLINGDETAILS (NOLOCK) WHERE FG_BARCODE = @BARCODE)
				AND Barcode IN (SELECT CHILD_BARCODE FROM #CHILD_BARCODE)
			END	
			IF (@QueueTimeValidation=1 AND @MACHINECODE <> 'MCIG')
			BEGIN
				IF EXISTS (SELECT TOP 1 1 FROM ASSY_LINEQUEUETIME_RUNNING (NOLOCK)
					WHERE ProfitCenterCode=@PROFITCENTERCODE AND LineCode=@LineCode AND Barcode=@Barcode 
					AND NextMachineCode=@MachineCode AND NextOperationcode=@OperationCode)
					BEGIN				
						INSERT INTO ASSY_LINEQUEUETIME (ProfitCenterCode,LineCode,Datecode,MachineCode,OperationCode,Barcode,Result,AssyUser,ResultTimestamp,
							NextMachineCode,NextOperationcode,PartNo,QuarantineStatus,EntStamp)
						SELECT ProfitCenterCode,LineCode,Datecode,MachineCode,OperationCode,Barcode,Result,AssyUser,ResultTimestamp,
							NextMachineCode,NextOperationcode,PartNo,QuarantineStatus,GETDATE() FROM ASSY_LINEQUEUETIME_RUNNING (NOLOCK)
							WHERE ProfitCenterCode=@PROFITCENTERCODE AND LineCode=@LineCode AND Barcode=@Barcode 
							AND NextMachineCode=@MachineCode AND NextOperationcode=@OperationCode
					
						DELETE FROM ASSY_LINEQUEUETIME_RUNNING
							WHERE ProfitCenterCode=@PROFITCENTERCODE AND LineCode=@LineCode AND Barcode=@Barcode 
							AND NextMachineCode=@MachineCode AND NextOperationcode=@OperationCode
					END
				--SELECT TOP 1 @NextOperationCode = A.OperationCode FROM RoutingConfigPartWise A (NOLOCK) INNER JOIN RoutingConfigLineWise b (NOLOCK) 
				--ON A.MachineCode=B.MachineCode AND A.Traceability=B.Traceability
				--WHERE A.MachineCode=@NextMachineCode AND PartNo=@PARTNUMBER AND A.Traceability=1 AND B.LineCode=@LINECODE
				--ORDER BY A.OperationSeqNo ASC

				--INSERT INTO ASSY_LINEQUEUETIME_RUNNING (ProfitCenterCode,LineCode,Datecode,MachineCode,OperationCode,Barcode,Result,AssyUser,ResultTimestamp,
				--				NextMachineCode,NextOperationcode,PartNo,QuarantineStatus)
				--SELECT TOP 1 ProfitCenterCode, LineCode, Datecode, MachineCode, OperationCode, Barcode, 'PS', UserID, ResultTimestamp,
				--				@NextMachineCode,@NextOperationCode,PartNo,0
				--FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE 
				--AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND BARCODE = @BARCODE AND ResultTimestamp='PS'

				----MOVE TO THE MAIN TABLE OF PREVIOUS MACHINE CODE	--WILL BE COMPLETED ONLY
				--INSERT INTO ASSY_LINEQUEUETIME (ProfitCenterCode,LineCode,Datecode,MachineCode,OperationCode,Barcode,Result,AssyUser,ResultTimestamp,
				--	NextMachineCode,NextOperationcode,PartNo,QuarantineStatus,EntStamp)
				--SELECT ProfitCenterCode,LineCode,Datecode,MachineCode,OperationCode,Barcode,Result,AssyUser,ResultTimestamp,
				--	NextMachineCode,NextOperationcode,PartNo,QuarantineStatus,GETDATE() FROM ASSY_LINEQUEUETIME_RUNNING (NOLOCK)
				--	WHERE ProfitCenterCode=@PROFITCENTERCODE AND LineCode=@LINECODE AND Barcode=@BARCODE 
				--	AND NextMachineCode=@MACHINECODE AND NextOperationcode=@OPERATIONCODE
			
			END	 				    
			--SELECT DATA FOR UPDATION INTO MAIN SERVER
			SELECT @STATUS = Concat(STATUS ,'|',IsReworkPart), @DATECODE = DATECODE, @SCANTIMESTAMP = CONVERT(VARCHAR(30), SCANTIMESTAMP, 121)
			, @RESULTTIMESTAMP = CONVERT(VARCHAR(30), RESULTTIMESTAMP, 121), @PARTFAILEDCOUNT = FAILCOUNT					
			FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) 
				WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE	AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND BARCODE = @BARCODE

			DELETE ASSY_LINEASSYSTATUS_RUNNING  WHERE LINECODE = @LINECODE  AND PROFITCENTERCODE = @PROFITCENTERCODE AND (BARCODE = @BARCODE OR BARCODE IN (SELECT CHILD_BARCODE FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE FG_BARCODE = @BARCODE))
			--IF(@ISSTMC = 1)
			--BEGIN
			--	DELETE ASSY_LINEASSYSTATUS_RUNNING  WHERE LINECODE = @LINECODE  AND PROFITCENTERCODE = @PROFITCENTERCODE
			--		AND BARCODE IN (SELECT CHILD_BARCODE FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE FG_BARCODE = @BARCODE)
			--END

			--COMMENT BY RAVI ON 18/03/16
			--UPDATE ASSY_PRODUCTIONORDER_PARAMETERSETTING SET PRODUCTIONQTY = ISNULL(PRODUCTIONQTY, 0)+1
			--WHERE LINECODE = @LINECODE   AND PROFITCENTERCODE = @PROFITCENTERCODE

			--UPDATE ASSY_PRODUCTIONORDER_PARAMETERSETTING SET BALANCEQTY = ISNULL(CURRENTPLANNEDQTY, 0)-ISNULL(PRODUCTIONQTY, 0)
			--WHERE LINECODE = @LINECODE   AND PROFITCENTERCODE = @PROFITCENTERCODE

			--DELETE BARCODE DATA FROM TALLY CHART TABLE, IF A BARCODE HAS ALREADY MARKED AS FAILED
			
			--IF EXISTS
			--(
			--	SELECT 1 FROM ASSY_TALLYCHARTSTATUSDATA (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE AND MACHINECODE = @MACHINECODE 
			--		AND BARCODE = @BARCODE AND ISNULL(RESULT, '') = 'FAIL'
			--)
			--BEGIN
				DELETE FROM ASSY_TALLYCHARTSTATUSDATA WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE 
					AND ISNULL(RESULT, '') = 'FAIL' AND PROFITCENTERCODE = @PROFITCENTERCODE
					AND (BARCODE = @BARCODE OR BARCODE IN ( SELECT CHILD_BARCODE FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE FG_BARCODE = @BARCODE AND PROFITCENTERCODE = @PROFITCENTERCODE))

				--IF(@ISSTMC = 1)
				--BEGIN
				--	DELETE FROM ASSY_TALLYCHARTSTATUSDATA WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE 
				--		AND ISNULL(RESULT, '') = 'FAIL' AND PROFITCENTERCODE = @PROFITCENTERCODE
				--			AND @BARCODE IN (SELECT CHILD_BARCODE FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE FG_BARCODE = @BARCODE AND PROFITCENTERCODE = @PROFITCENTERCODE)
				--END
			--END

			------------------UPDATE ASSY_POKAYOKE_COMPLETED_DTL TABLE FOR CHECKING WHETHER FINAL VIEWING TESTING HAS BEEN COMPLETED OR NOT--------------------------
			-- ADDED BY RASHID ON 11TH AUGUST 2016
			DECLARE @ISPARTTESTEDAFTERPKYK INT = 0
			DECLARE @CREATEDDATE DATETIME
			-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
			-- SELECT TOP 1  @DATECODE = DATECODE, @PARTNO = ASSY_PARTNO, @CREATEDDATE = CREATEDDATE FROM ASSY_RUNNINGPART WITH (NOLOCK) 
			--	WHERE PROFITCENTERCODE = @PROFITCENTERCODE  AND LINECODE = @LINECODE ORDER BY CREATEDDATE DESC
			SELECT @DATECODE = DATECODE, @PARTNO = ASSY_PARTNO, @CREATEDDATE = CREATEDDATE FROM ASSY_RUNNINGPART WITH (NOLOCK) 
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE  AND LINECODE = @LINECODE
								
			IF EXISTS
			(
				SELECT 1 FROM LINEMST WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND ISNULL(ISPOKAYOKEMANDATORY, 0) = 1
			)
			BEGIN
				SELECT @ISPARTTESTEDAFTERPKYK = ISNULL(COUNT(ISNULL (BARCODE, 0)), 0) FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE 
				AND LINECODE = @LINECODE AND DATECODE = @DATECODE AND MACHINECODE = DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)
				AND PARTNO = @PARTNO AND SCANTIMESTAMP>= @CREATEDDATE AND ISNULL(ISTALLYCHARTAPPROVED, 0) = 0 AND ISNULL(STATUS, '') != ''

				IF(ISNULL(@ISPARTTESTEDAFTERPKYK, 0) = 1)
				BEGIN
					--DELETE ASSY_POKAYOKE_COMPLETED_DTL IF DATECODE IS OLD
					IF EXISTS(SELECT 1 FROM ASSY_POKAYOKE_COMPLETED_DTL WITH (NOLOCK) WHERE DATECODE! = @DATECODE)
						TRUNCATE TABLE ASSY_POKAYOKE_COMPLETED_DTL 

					IF NOT EXISTS
					(
						SELECT 1 FROM ASSY_POKAYOKE_COMPLETED_DTL WHERE PROFITCENTERCODE = @PROFITCENTERCODE 
						AND LINECODE = @LINECODE	AND DATECODE = @DATECODE AND PARTNO = @PARTNO
					)
					BEGIN
						INSERT INTO ASSY_POKAYOKE_COMPLETED_DTL
						(
							PROFITCENTERCODE, LINECODE, DATECODE, PARTNO, IS_PKYK_COMPLETED, IS_FV_COMPLETED, TIMESTAMP
						)
						SELECT @PROFITCENTERCODE, @LINECODE, @DATECODE, @PARTNO, 1, (CASE WHEN @ISPARTTESTEDAFTERPKYK = 0 THEN 0 ELSE 1 END)IS_PKYK_COMPLETED, GETDATE()
					END
					ELSE
					BEGIN
						UPDATE ASSY_POKAYOKE_COMPLETED_DTL SET TIMESTAMP = GETDATE() WHERE PROFITCENTERCODE = @PROFITCENTERCODE 
							AND LINECODE = @LINECODE	AND DATECODE = @DATECODE AND PARTNO = @PARTNO
					END
				END
			END

			--DECREASE WIP COUNT AND REOMVE WIP FIFO BARCODE FROM PREVIOS STATION 				
					
			IF @FAILCOUNT = 0
				EXEC ASSY_PROC_WIP_MANAGE  @CONDITION = 'UPDATE_WIP_COUNT', @LINECODE = @LINECODE, @MACHINECODE = @MACHINECODE, @BARCODE = @BARCODE	, @PROFITCENTERCODE = @PROFITCENTERCODE 

			--RESET DATE CODE STAMPING ACK. AND BARCODE
			EXEC ASSY_PROC_DATECODESTAMPING @CONDITION = 'RESET_ACK', @LINECODE = @LINECODE, @PROFITCENTERCODE = @PROFITCENTERCODE
			--Gasket Missing Check Functionality in Servo Line // Added By RS On 20180328
			--RESET GASKET TAG RESULTS
			EXEC Assy_Proc_GasketMissing_Check @CONDITION = 'RESET_GASKET_TAG_RESULT', @LINECODE = @LINECODE, @PROFITCENTERCODE = @PROFITCENTERCODE,
				@BARCODE = @BARCODE, @Result = 'PS', @UserId = @USERID, @DateCode = @DateCode, @ScanTimeStamp = @ScanTimeStamp, @PartNumber = @PartNumber
				  
			---UPDATE PART AS WELL AS SHIFT PASS FAIL COUNTER
			EXEC ASSY_PROC_SHIFTQTY_UPDATE @CONDITION = 'UPDATE', @PROFITCENTERCODE = @PROFITCENTERCODE
			, @LINECODE = @LINECODE, @BARCODE = @BARCODE, @OPERATIONCODE = @OPERATIONCODE, @CURRENTDATECODE = @DATECODE, @CURRENTPARTNO = @PARTNUMBER

			SELECT @RETURNINT = 1, @RETURNVALUE = 'PASSED'
			
			SELECT @RETURNINT RETURNINT, @RETURNVALUE RETURNVALUE
			
			IF EXISTS
			(
				SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
					AND KeyType = 'IsBoreViewingMixUpRequired' AND KeyValue = '1'
			)
			BEGIN
				IF EXISTS
				(
					SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
						AND KeyType = 'IsBoreViewingValidationRequiredAtFV' AND KeyValue = '1'
				)
				BEGIN
					IF OBJECT_ID('Assy_FV_BoreView_Mapping_Status') IS NOT NULL
					BEGIN
						DELETE FROM Assy_FV_BoreView_Mapping_Status WHERE OperationCode = @OPERATIONCODE
					END
				END
			END

			
			SELECT @SCANTIMESTAMP SCANTIMESTAMP, @RESULTTIMESTAMP RESULTTIMESTAMP, @STATUS STATUS, @PARTFAILEDCOUNT PARTFAILEDCOUNT, @DATECODE DATECODE, @PARTNUMBER PARTNUMBER
			, ISNULL(@RETURN_LOT_NO,'') LOT_NO , ISNULL(@RETURN_ECU_BARCODE,'') ECU_BARCODE -- Added By Sachin By Sachin 20170726
			,ISNULL(@ProductionOrderNo,'') [ProductionOrderNo]
			COMMIT TRAN

			SELECT @IS_RESERVOIR_LINE =  DBO.[FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE](@ProfitCenterCode,'LINE_ATTRB','IS_RESERVOIR_LINE',@LineCode,'')
		    IF((@IS_RESERVOIR_LINE='1'))
			Begin
			   	Insert into #tblOPCode(Row_No, col1)
			    SELECT Row_No, col1   FROM dbo.FN_GRID_SPLIT_STRING(DBO.[FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE](@ProfitCenterCode,'LINE_ATTRB','RESERVOIR_OPERATION_CODE',@LINECODE,''),'','|')
				IF EXISTS (SELECT 1 FROM #tblOPCode WHERE Col1 = @OperationCode)
				BEGIN
					IF  EXISTS (SELECT 1 FROM Assy_CustomerBarcode_Scan_Validation WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
					AND OperationCode=@OperationCode)
					BEGIN
						
						   SET @EXECQUERY = ''
							SET @EXECQUERY = 'INSERT INTO OPENQUERY (' + @OpenQueryLinkServerName + ',''select ProfitCenterCode,LineCode,ReservoirBarCode,TSBarcode,IsMapped,Timestamp,UserID from ' + @OpenQueryDBName + '.dbo.Assy_TS_Reservoir_Barcode_Mapping'' )
											SELECT ProfitCenterCode,LineCode,CustomerBarcode,Barcode,0,GETDATE(),'''+@USERID+''' FROM Assy_CustomerBarcode_Scan_Validation where OperationCode='''+@OperationCode+'''';
						PRINT @ExecQuery
						EXEC (@ExecQuery)
						INSERT INTO Assy_TS_Reservoir_Barcode_Mapping(ProfitCenterCode,LineCode,ReservoirBarCode,TSBarcode,IsMapped,Timestamp,UserID)
						SELECT ProfitCenterCode,LineCode,CustomerBarcode,Barcode,0,GETDATE(),@USERID FROM Assy_CustomerBarcode_Scan_Validation where OperationCode=@OPERATIONCODE

						DELETE FROM Assy_CustomerBarcode_Scan_Validation where OperationCode=@OPERATIONCODE
					END
				END
			End

			
			/* COUPLING DATA INSERT INTO CENTRAL SERVER VIA COUPLING PROCEDURE IMMEDIATELY AFTER COUPLING - BLOCK INSERT_COUPLING_BARCODE -- COMMENT BY RASHID ON 23RD JAN 2017
			-- INSERT COUPLING DATA INTO CENTRAL SERVER
			-- START -- ADDED BY RASHID ON 20TH JUNE 2016 -----
			IF (CHARINDEX(':', @BARCODE) <> 0 OR (ISNULL(@ISLINE6, 0) = 1 AND CHARINDEX(@ASSY_PARTNO, @BARCODE) <> 0)) AND ISNULL(@BARCODE, '') <> ''
			BEGIN
				--SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE	
				
				SET @EXECQUERY = ''

				SET @EXECQUERY = '
				IF EXISTS (SELECT 1 FROM ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + ''')
				BEGIN
					INSERT INTO ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS_HISTORY (PROFITCENTRECODE, LINECODE, STMC_PART_NO, CHILD_PART_NO, PART_TYPE, MACHINE_CODE,
					OPERATION_CODE, TORQUE_1, TORQUE_2, ENT_DT, ENT_BY, FG_BARCODE, CHILD_BARCODE, DATECODE, HIS_ENT_DT, HIS_ENT_BY)
					SELECT PROFITCENTRECODE, LINECODE, STMC_PART_NO, CHILD_PART_NO, PART_TYPE, MACHINE_CODE, OPERATION_CODE, TORQUE_1, TORQUE_2, ENT_DT, ENT_BY, FG_BARCODE, 
					CHILD_BARCODE, DATECODE, GETDATE(), ''' + ISNULL(@USERID, '''') + ''' FROM ASSY_COUPLINGDETAILS WITH (NOLOCK)
					WHERE PROFITCENTRECODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + '''

					DELETE FROM ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS WHERE PROFITCENTRECODE = ''' + @PROFITCENTERCODE + '''
					AND LINECODE = ''' + @LINECODE + '''AND FG_BARCODE = ''' + @BARCODE + '''
								
					IF NOT EXISTS
					(
						SELECT 1 FROM ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = ''' + @PROFITCENTERCODE + '''
							AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + '''
					)
					BEGIN
						INSERT INTO ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS (PROFITCENTRECODE, LINECODE, STMC_PART_NO, CHILD_PART_NO, PART_TYPE, MACHINE_CODE,
							OPERATION_CODE, TORQUE_1, TORQUE_2, ENT_DT, ENT_BY, FG_BARCODE, CHILD_BARCODE, DATECODE)
						SELECT PROFITCENTRECODE, LINECODE, STMC_PART_NO, CHILD_PART_NO, PART_TYPE, MACHINE_CODE, OPERATION_CODE, TORQUE_1, TORQUE_2, ENT_DT,
							ENT_BY, FG_BARCODE, CHILD_BARCODE, DATECODE FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = ''' + @PROFITCENTERCODE + '''
							AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + '''
					END
				END
				ELSE
				BEGIN
					INSERT INTO ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS (PROFITCENTRECODE, LINECODE, STMC_PART_NO, CHILD_PART_NO, PART_TYPE, MACHINE_CODE, OPERATION_CODE,
						TORQUE_1, TORQUE_2, ENT_DT, ENT_BY, FG_BARCODE, CHILD_BARCODE, DATECODE)
					SELECT PROFITCENTRECODE, LINECODE, STMC_PART_NO, CHILD_PART_NO, PART_TYPE, MACHINE_CODE, OPERATION_CODE, TORQUE_1, TORQUE_2, ENT_DT, ENT_BY, FG_BARCODE,
						CHILD_BARCODE, DATECODE FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + '''
				END
				'
				PRINT @EXECQUERY
				EXEC (@EXECQUERY)
			END
			-- END -- ADDED BY RASHID ON 20TH JUNE 2016 -----
			*/
				--------------Update Previous count and parametersetting data
					
					IF EXISTS
					(
						SELECT 1 FROM ASSY_RUNNINGPART_PREVIOUS (NOLOCK) WHERE ASSY_MODE IN ('PRODUCTION', 'REWORK')
							AND LINECODE = @LINECODE AND CURRENTPLANNEDQTY > ISNULL(PRODUCEDQTY, 0)
					)
					BEGIN
						Select top 1 * into #ASSY_RUNNINGPART_PREVIOUS_TEMP from ASSY_RUNNINGPART_PREVIOUS where 
						LINECODE = @LINECODE AND CURRENTPLANNEDQTY > ISNULL(PRODUCEDQTY, 0) AND 
						Assy_PartNo=@PARTNUMBER order by CreatedDate asc
											
						UPDATE RPS SET RPS.PRODUCEDQTY = ISNULL(RPS.PRODUCEDQTY, 0) + 1 , RPS.BALANCEQTY = ISNULL(RPS.BALANCEQTY,0) - 1 
						from ASSY_RUNNINGPART_PREVIOUS RPS
						Inner Join #ASSY_RUNNINGPART_PREVIOUS_TEMP (NOLOCK) RK ON  RK.ProductionOrderNo=RPS.PRODUCTIONORDERNO
						WHERE RPS.LINECODE = @LINECODE  
						
						--DELETE FROM ASSY_RUNNINGPART_PREVIOUS WHERE LINECODE = @LINECODE AND CURRENTPLANNEDQTY = ISNULL(PRODUCEDQTY, 0)
						
					END
					ELSE
					BEGIN	
								
						UPDATE ASSY_PRODUCTIONORDER_PARAMETERSETTING SET PRODUCTIONQTY = ISNULL(PRODUCTIONQTY, 0) + 1, BALANCEQTY = ISNULL(BALANCEQTY,0) - 1
						WHERE LINECODE = @LINECODE   AND PROFITCENTERCODE = @PROFITCENTERCODE
											
					END	      
			END TRY
			BEGIN CATCH
				SET @RETURNVALUE = 	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
				CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
				CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_MESSAGE() AS VARCHAR(1500))
			
				ROLLBACK TRAN				
				SET @RETURNINT = 2
				RAISERROR(@RETURNVALUE, 16, 1)	
			END CATCH
			
			RETURN
		END
	      			
		ELSE IF @CONDITION = 'UPDATE_FINALVIEWING_FAIL_STATUS'		
		BEGIN
			BEGIN TRY
				IF @PRNGroupCode = 'GC_TML'
				BEGIN
					IF EXISTS (SELECT 1 FROM Assy_FinalViewing_RFID_Barcode_Mapping (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @BARCODE)
					BEGIN
						SELECT @NBarcode = BARCODE FROM Assy_FinalViewing_RFID_Barcode_Mapping (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @BARCODE
						SET @BARCODE = @NBarcode
					END
				END
				ELSE IF @PRNGroupCode IN ('GC_DUSTER_LINE_6_7','GC_NISSAN_LINE_6_7')
				BEGIN
					SET @ISLINE6 = 1
				END

				/*
				--Waki Customer Barcode Data - Added By RS On 20180828 For Waki Non-Mahindra Logic
				IF EXISTS
				(
					SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
						AND KeyType = 'WakiLogic' AND KeyValue = '1'
				)
				BEGIN
					IF EXISTS (SELECT 1 FROM Assy_FinalViewing_RFID_Barcode_Mapping (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @BARCODE)
					BEGIN
						SELECT @NBarcode = BARCODE FROM Assy_FinalViewing_RFID_Barcode_Mapping (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @BARCODE
						SET @BARCODE = @NBarcode
					END
				END
				*/
				 IF @PROFITCENTERCODE in ('0088','0064')
				BEGIN
						EXEC ASSY_PROC_FINALVIEWING_BIJ @CONDITION='UPDATE_FINALVIEWING_FAIL_STATUS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@MACHINECODE=@MACHINECODE
						,@OPERATIONCODE=@OPERATIONCODE,@BARCODE=@BARCODE,@USERID=@USERID
						,@RETURNINT=@RETURNINT OUT,@RETURNVALUE=@RETURNVALUE OUT
						RETURN
				END
				ELSE IF @PROFITCENTERCODE in ('0018','0030','0068')
				BEGIN
						EXEC ASSY_PROC_FINALVIEWING_ABS @CONDITION='UPDATE_FINALVIEWING_FAIL_STATUS',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@MACHINECODE=@MACHINECODE
						,@OPERATIONCODE=@OPERATIONCODE,@BARCODE=@BARCODE,@USERID=@USERID
						,@RETURNINT=@RETURNINT OUT,@RETURNVALUE=@RETURNVALUE OUT
						RETURN
				END
			BEGIN TRAN
			
			IF (CHARINDEX(':', @BARCODE) <> 0 OR (ISNULL(@ISLINE6, 0) = 1 AND CHARINDEX(@ASSY_PARTNO, @BARCODE) <> 0)) AND ISNULL(@BARCODE, '') <> '' 
			BEGIN
				SET @ISSTMC = 1
				SELECT @LINECODE_STMC = ISNULL(LINECODE, ''), @DATECODE_TEMP = ISNULL(DATECODE, '')  FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) 
					WHERE  PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE  AND BARCODE = @BARCODE  
				
				SET @DATECODE = @DATECODE_TEMP
				
				IF(@LINECODE_STMC) <> ''
				BEGIN
					-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
					-- SELECT DISTINCT @PARTNUMBER = ISNULL(STMC_PART_NO, ''), @DATECODE = DATECODE FROM ASSY_COUPLINGDETAILS (NOLOCK) 
					SELECT @PARTNUMBER = ISNULL(STMC_PART_NO, ''), @DATECODE = DATECODE FROM ASSY_COUPLINGDETAILS (NOLOCK) 
						WHERE FG_BARCODE = @BARCODE AND LINECODE = @LINECODE AND PROFITCENTRECODE = @PROFITCENTERCODE
				END
				ELSE
				BEGIN
					-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
					-- SELECT DISTINCT @PARTNUMBER = ISNULL(STMC_PART_NO, ''), @LINECODE_STMC = LINECODE, @DATECODE = DATECODE FROM ASSY_COUPLINGDETAILS (NOLOCK) 
					SELECT @PARTNUMBER = ISNULL(STMC_PART_NO, ''), @LINECODE_STMC = LINECODE, @DATECODE = DATECODE FROM ASSY_COUPLINGDETAILS (NOLOCK) 
					WHERE FG_BARCODE = @BARCODE AND LINECODE = @LINECODE AND PROFITCENTRECODE = @PROFITCENTERCODE
				END
			END		
			ELSE IF @ISSTMC = 0 AND ISNULL(@BARCODE, '') <> '' 
			BEGIN
				--GET DATECODE AND PART NO OF SNANNED BARCODE FROM VISION SYSTEM
				SELECT @PARTNUMBER = PARTNO, @DATECODETEMP = DATECODE FROM ASSY_FN_GET_BARCODEPARTS_FROM_BARCODE(@PROFITCENTERCODE, @LINECODE, @BARCODE)
				
				SET @DATECODE = @DATECODETEMP
			END

			UPDATE ASSY_LINEASSYSTATUS_RUNNING SET STATUS = 'FL', RESULTTIMESTAMP = GETDATE(), FAILCOUNT = ISNULL (FAILCOUNT, 0 )+1, Live_datecode = @Live_Datecode
				WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND BARCODE = @BARCODE AND ISNULL(STATUS, '') <> 'PS'
					
			--CLEAR SCAN OK BARCODE FROM ASSY_SCANOK
			UPDATE ASSY_SCAN_OK SET BARCODE = '', ISSCAN = 0  WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE

			
			-- Modified By RS On 20181213 - ScanTimeStamp Value is capturing
			SELECT @FVScanTimeStamp = ScanTimeStamp  FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE BARCODE = @BARCODE
				AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE

			--INSERT FAIL DATA INTO ASSY_LINEASSYPARAMDATA_RUNNING TABLE

			INSERT INTO ASSY_LINEASSYPARAMDATA_RUNNING
			(
				PROFITCENTERCODE
				, LINECODE
				, MACHINECODE
				, OPERATIONCODE
				, STATIONCODE
				, BARCODE					
				, RESULT
				, DATECODE
				, USERID
				, TIMESTAMP
				, PARTNO
				, ScanTimestamp
				,LIVE_DATECODE
			)

			SELECT 
				@PROFITCENTERCODE 
				, @LINECODE 
				, @MACHINECODE 
				, @OPERATIONCODE
				, @STATIONCODE
				, @BARCODE
				, 'FL'
				, @DATECODE 
				, @USERID 
				, GETDATE()
				, @PARTNUMBER
				, @FVScanTimeStamp
				,@Live_Datecode
			
			-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
			-- SELECT @FAILCOUNTDEFINED = CONVERT(INT, PARAMETER_VALUE) FROM PARAMETER_MST (NOLOCK) WHERE PARAMETER_C = 'ASSLINE' 
			-- AND PARAMETER_C1 = 'REWORK_COUNT' AND WH_CODE = @PROFITCENTERCODE

			SELECT @FAILCOUNTDEFINED = CONVERT(INT,DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'REWORK_COUNT', 'REWORK_COUNT', @PROFITCENTERCODE))

			SELECT @FAILCOUNT = ISNULL(FAILCOUNT, 0) FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE BARCODE = @BARCODE AND LINECODE = @LINECODE  
				AND	MACHINECODE = @MACHINECODE AND STATUS = 'FL'
					
			--SELECT DATA FOR UPDATION INTO MAIN SERVER
			SELECT @STATUS = Concat(STATUS ,'|',IsReworkPart)	, @DATECODE = DATECODE, @SCANTIMESTAMP = SCANTIMESTAMP, @RESULTTIMESTAMP = RESULTTIMESTAMP					
				FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) 
				WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE	AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND BARCODE = @BARCODE

			--MOVE BARCODE FROM RUNNING TO ASSY_LINEASSYSTATUS TABLE AFTER MAXIMUMM NO OF TIMES FAIL REACHED
			IF @FAILCOUNTDEFINED = @FAILCOUNT 
			BEGIN
				IF(@ISSTMC = 0)
				BEGIN
					--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
					INSERT INTO ASSY_LINEASSYSTATUS
					(
						PROFITCENTERCODE, 
						LINECODE, 
						MACHINECODE, 
						OPERATIONCODE, 
						STATIONCODE, 
						BARCODE, 
						STATUS, 
						FAILCOUNT, 
						DATECODE, 
						PARTNO, 
						SCANTIMESTAMP, 
						RESULTTIMESTAMP, 
						USERID,
						PRODUCTIONORDERNO,
						Category,
						Live_Datecode,
						IsReworkPart
					)

					SELECT 
						PROFITCENTERCODE, 
						LINECODE, 
						MACHINECODE, 
						OPERATIONCODE, 
						STATIONCODE, 
						BARCODE, 
						STATUS, 
						FAILCOUNT, 
						DATECODE, 
						PARTNO, 
						SCANTIMESTAMP, 
						RESULTTIMESTAMP, 
						USERID,
						PRODUCTIONORDERNO,
						Category,
						Live_Datecode,
						IsReworkPart
					FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE LINECODE = @LINECODE AND BARCODE = @BARCODE AND PROFITCENTERCODE = @PROFITCENTERCODE
				END
				ELSE
				BEGIN
					--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
					INSERT INTO ASSY_LINEASSYSTATUS
					(
						PROFITCENTERCODE, 
						LINECODE, 
						MACHINECODE, 
						OPERATIONCODE, 
						STATIONCODE, 
						BARCODE, 
						STATUS, 
						FAILCOUNT, 
						DATECODE, 
						PARTNO, 
						SCANTIMESTAMP, 
						RESULTTIMESTAMP, 
						USERID,
						PRODUCTIONORDERNO,
						Category,
						Live_Datecode,
						IsReworkPart
					)

					SELECT 
						PROFITCENTERCODE, 
						LINECODE, 
						MACHINECODE, 
						OPERATIONCODE, 
						STATIONCODE, 
						BARCODE, 
						STATUS, 
						FAILCOUNT, 
						DATECODE, 
						PARTNO, 
						SCANTIMESTAMP, 
						RESULTTIMESTAMP, 
						USERID,
						PRODUCTIONORDERNO,
						Category,
						Live_Datecode,
						IsReworkPart
					FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE LINECODE = @LINECODE AND BARCODE = @BARCODE AND PROFITCENTERCODE = @PROFITCENTERCODE

					UNION

					SELECT 
						PROFITCENTERCODE, 
						LINECODE, 
						MACHINECODE, 
						OPERATIONCODE, 
						STATIONCODE, 
						BARCODE, 
						STATUS, 
						FAILCOUNT, 
						DATECODE, 
						PARTNO, 
						SCANTIMESTAMP, 
						RESULTTIMESTAMP,
						USERID,
						PRODUCTIONORDERNO,
						Category,
						Live_Datecode,
						IsReworkPart
					FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
					AND BARCODE IN (SELECT CHILD_BARCODE FROM ASSY_COUPLINGDETAILS (NOLOCK) WHERE FG_BARCODE = @BARCODE AND PROFITCENTRECODE = @PROFITCENTERCODE)
				END

				DELETE ASSY_LINEASSYSTATUS_RUNNING  WHERE LINECODE = @LINECODE AND (BARCODE = @BARCODE OR 
				BARCODE IN (SELECT CHILD_BARCODE FROM ASSY_COUPLINGDETAILS (NOLOCK) WHERE FG_BARCODE = @BARCODE AND PROFITCENTRECODE = @PROFITCENTERCODE))

				--IF(@ISSTMC = 1)
				--BEGIN
				--	DELETE ASSY_LINEASSYSTATUS_RUNNING  WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
				--	AND BARCODE IN (SELECT CHILD_BARCODE FROM ASSY_COUPLINGDETAILS (NOLOCK) WHERE FG_BARCODE = @BARCODE AND PROFITCENTRECODE = @PROFITCENTERCODE)
				--END
			END
					 
			--RESET DATE CODE STAMPING ACK. AND BARCODE
			EXEC ASSY_PROC_DATECODESTAMPING @CONDITION = 'RESET_ACK', @LINECODE = @LINECODE, @PROFITCENTERCODE = @PROFITCENTERCODE

			--Gasket Missing Check Functionality in Servo Line // Added By RS On 20180328
			--RESET GASKET TAG RESULTS
			EXEC Assy_Proc_GasketMissing_Check @CONDITION = 'RESET_GASKET_TAG_RESULT', @LINECODE = @LINECODE, @PROFITCENTERCODE = @PROFITCENTERCODE,
				@BARCODE = @BARCODE, @Result = 'FL', @UserId = @USERID, @DateCode = @DateCode, @ScanTimeStamp = @ScanTimeStamp, @PartNumber = @PartNumber
			--DECREASE WIP COUNT AND REOMVE WIP FIFO BARCODE FROM PREVIOS STATION 	
			IF @FAILCOUNT = 1					
				EXEC ASSY_PROC_WIP_MANAGE  @CONDITION = 'UPDATE_WIP_COUNT', @LINECODE = @LINECODE, @MACHINECODE = @MACHINECODE, @BARCODE = @BARCODE	, @PROFITCENTERCODE = @PROFITCENTERCODE 

			---UPDATE PART AS WELL AS SHIFT PASS FAIL COUNTER
			EXEC ASSY_PROC_SHIFTQTY_UPDATE @CONDITION = 'UPDATE', @PROFITCENTERCODE = @PROFITCENTERCODE
			, @LINECODE = @LINECODE, @BARCODE = @BARCODE, @OPERATIONCODE = @OPERATIONCODE, @CURRENTDATECODE = @DATECODE, @CURRENTPARTNO = @PARTNUMBER

			SELECT @RETURNINT = 1, @RETURNVALUE = 'FAILED'
			
			SELECT @RETURNINT RETURNINT, @RETURNVALUE RETURNVALUE

			IF EXISTS
			(
				SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
					AND KeyType = 'IsBoreViewingMixUpRequired' AND KeyValue = '1'
			)
			BEGIN
				IF EXISTS
				(
					SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
						AND KeyType = 'IsBoreViewingValidationRequiredAtFV' AND KeyValue = '1'
				)
				BEGIN
					IF OBJECT_ID('Assy_FV_BoreView_Mapping_Status') IS NOT NULL
					BEGIN
						DELETE FROM Assy_FV_BoreView_Mapping_Status WHERE OperationCode = @OPERATIONCODE
					END
				END
			END			
			SELECT @IS_RESERVOIR_LINE =  DBO.[FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE](@ProfitCenterCode,'LINE_ATTRB','IS_RESERVOIR_LINE',@LineCode,'')
			IF((@IS_RESERVOIR_LINE='1'))
			Begin
			   	Insert into #tblOPCode(Row_No, col1)
			    SELECT Row_No, col1   FROM dbo.FN_GRID_SPLIT_STRING(DBO.[FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE]('0021','LINE_ATTRB','RESERVOIR_OPERATION_CODE',@LINECODE,''),'','|')
				IF EXISTS (SELECT 1 FROM #tblOPCode WHERE Col1 = @OperationCode)
				BEGIN
					IF  EXISTS (SELECT 1 FROM Assy_CustomerBarcode_Scan_Validation WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
					AND OperationCode=@OPERATIONCODE)
					BEGIN
						DELETE FROM Assy_CustomerBarcode_Scan_Validation  where OperationCode=@OPERATIONCODE 
					END
				END
			End

			SELECT @SCANTIMESTAMP SCANTIMESTAMP, @RESULTTIMESTAMP RESULTTIMESTAMP, @STATUS STATUS, @FAILCOUNT PARTFAILEDCOUNT, @DATECODE DATECODE, @PARTNUMBER PARTNUMBER
			COMMIT TRAN			   
			
			END TRY
			
			BEGIN CATCH			
				SET @RETURNVALUE = 	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
				CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
				CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_MESSAGE() AS VARCHAR(1500))			
				SET @RETURNINT = 2
				ROLLBACK TRAN
				RAISERROR(@RETURNVALUE, 16, 1)	
			END CATCH					
			RETURN
		END
		
		ELSE IF @CONDITION = 'GET_FINALVIEWING_LAST_SCAN_BARCODE'		
		BEGIN

				if exists(select top 1 1 from #Temp_RoboKey where RoboKey in('1','2'))
				Begin
					if exists(select top 1 1 from #Temp_RoboKey where RoboKey in('1'))
					Begin
						Declare @RFID NVARCHAR(200)='';

						Select @RFID=SB.Barcode  from ASSY_SCAN_OK_ROBO As SB with(nolock)  
						Inner Join ASSY_FV_ROBOT_INSPECTION_SERIAL_HOLD As ST with(NOLOCK) on SB.Barcode=ST.RFID
						where ST.PRINTED_BARCODE=@barcode and ProfitCenterCode=@ProfitCenterCode 
						and LineCode=@linecode and MachineCode=@MACHINECODE

						if exists(Select top 1 1  from ASSY_SCAN_OK As SB with(nolock)  
						Inner Join ASSY_FV_ROBOT_INSPECTION_SERIAL_HOLD As ST with(NOLOCK) on SB.Barcode=ST.PRINTED_BARCODE
						where ProfitCenterCode=@ProfitCenterCode 
						and LineCode=@linecode and MachineCode=@MACHINECODE)
						Begin
							Declare @scannedRFID nvarchar(100)='';
							Select top 1 @scannedRFID=ST.RFID from ASSY_SCAN_OK As SB with(nolock)  
							Inner Join ASSY_FV_ROBOT_INSPECTION_SERIAL_HOLD As ST with(NOLOCK) on SB.Barcode=ST.PRINTED_BARCODE
							where ProfitCenterCode=@ProfitCenterCode 
							and LineCode=@linecode and MachineCode=@MACHINECODE
							select  @scannedRFID,@RFID

							if(@scannedRFID!=@RFID)
							Begin
								Select @RETURNINT=1, @RETURNVALUE=@scannedRFID
								Return
							End

						End	
						if(@rfid !='')	
						Begin			
							Select @RETURNINT=3, @RETURNVALUE=@RFID

							update Assy_scan_ok set barcode=@BARCODE,isScan='1'where ProfitCenterCode=@PROFITCENTERCODE And OperationCode=@OPERATIONCODE and MachineCode=@MACHINECODE
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @ProfitCenterCode, 'ROBO_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, 'ADMIN', GETDATE(), 'ADMIN', GETDATE()
							RETURN
						END
					END

					select @Buffer_Count= count(*) from Assy_Scan_Ok_ROBO with(nolock) where ProfitCenterCode=@PROFITCENTERCODE and Linecode=@linecode 
					AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE and isnull(isprocess ,'0') != '1'
					if(@Buffer_Count = @FV_ROBO_BUFFER_COUNT)
					Begin
						set @RETURNVALUE=STUFF((SELECT ',' + CAST(BARCODE AS VARCHAR(200))
						FROM ASSY_SCAN_OK_ROBO with(nolock)
						WHERE  LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE and isnull(isprocess ,'0') != '1'
						FOR XML PATH(''), TYPE)
					.value('.','NVARCHAR(MAX)'),1,1,'') 
								--UPDATE INCORRECT LABEL
											
					
						SET @RETURNINT = 1
						RETURN
					End
					else
					Begin
						set @RETURNVALUE=''
						SET @RETURNINT = 0
						return
					End
				END
			


				SELECT @RETURNVALUE = ISNULL(BARCODE, '') FROM ASSY_SCAN_OK (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE 
			
				SET @RETURNINT = 1
				RETURN
		END
		
		ELSE IF @CONDITION = 'GET_NO_OF_CHANGEOVERS'		
		BEGIN		
			DECLARE @CHANGEOVERCOUNT INT
			SELECT @CHANGEOVERCOUNT = DBO.ASSY_FN_GET_CHANGEOVER_COUNT (@PROFITCENTERCODE, @LINECODE, @CHANGEOVER_DATECODE )
			
			SET @RETURNVALUE = CONVERT(VARCHAR (30), @CHANGEOVERCOUNT)
			SET @RETURNINT = 1
			RETURN
		END

		ELSE IF @CONDITION = 'GET_FINALVIEWING_MACHINECODE_OPERATIONCODE'		
		BEGIN
			SELECT @FINALVIEWING_OPERATIONCODE = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)	
			, @FINALVIEWING_MACHINECODE = DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)	
			
			SELECT @RETURNVALUE = @FINALVIEWING_MACHINECODE+'|'+@FINALVIEWING_OPERATIONCODE, @RETURNINT = 1
			RETURN
		END

		ELSE IF @CONDITION = 'GET_FIRSTSTATION_MACHINECODE'		
		BEGIN
			SELECT @RETURNVALUE = MACHINECODE FROM ROUTINGCONFIGLINEWISE WITH (NOLOCK) 
				WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE AND OPERATIONSEQNO = 1
			
			SET @RETURNINT = 1
			RETURN
		END	
				
		ELSE IF @CONDITION = 'UPDATE_FV_QC_OK_PASS_DATA_IN_MAINSERVER'
		BEGIN
			BEGIN TRY
			--#20210709
			if(CHARINDEX('|',@STATUS) <> 0)
			Begin
				select @STATUS=col1,@Rework=isnull(col2,0) from dbo.FN_GRID_SPLIT_STRING(isnull(@STATUS,'NULL'),'|','');
			End
			INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
			SELECT @PROFITCENTERCODE, 'FV_MAIN_PASS', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, 
			'ScanTimestamp-' + CONVERT(VARCHAR(60),@ScanTimestamp) + ',ResultTimestamp-' + CONVERT(VARCHAR(60),@ResultTimestamp) + ',Status-' + ISNULL(@Status,'NULL'),
			@USERID, GETDATE(), @USERID, GETDATE()

			IF @PRNGroupCode = 'GC_TML'
			BEGIN
				IF EXISTS (SELECT 1 FROM Assy_FinalViewing_RFID_Barcode_Mapping (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @BARCODE)
				BEGIN
					SELECT @NBarcode = BARCODE FROM Assy_FinalViewing_RFID_Barcode_Mapping (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @BARCODE
					SET @BARCODE = @NBarcode
				END
			END

			/*
			--Waki Customer Barcode Data - Added By RS On 20180828 For Waki Non-Mahindra Logic
			IF EXISTS
			(
				SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
					AND KeyType = 'WakiLogic' AND KeyValue = '1'
			)
			BEGIN
				IF EXISTS (SELECT 1 FROM Assy_FinalViewing_RFID_Barcode_Mapping (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @BARCODE)
				BEGIN
					SELECT @NBarcode = BARCODE FROM Assy_FinalViewing_RFID_Barcode_Mapping (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @BARCODE
					SET @BARCODE = @NBarcode
				END
			END
			*/

			IF EXISTS (SELECT 1 FROM ASSY_LINEASSYSTATUS (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND
				MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND STATUS = 'FL' AND BARCODE = @BARCODE)
			BEGIN
				DELETE FROM ASSY_LINEASSYSTATUS WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND
					MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND STATUS = 'FL' AND BARCODE = @BARCODE
			END
			---- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING STOCK DEDUCTION ----
			ELSE
			BEGIN
					   --CHANGED BY RAVI ON 08-08-17 TO UPDATE DATA INTO ASSY_MACHINEWISE_RUNNINGPART
					    IF ISNULL( @ALLOW2PARTS,0)=1
						BEGIN
								IF EXISTS
								( 
										SELECT 1 FROM ASSY_MACHINEWISE_RUNNINGPART WITH(NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
										AND OPERATIONCODE = @OPERATIONCODE
								)
								BEGIN
										UPDATE ASSY_MACHINEWISE_RUNNINGPART SET PARTNO = @PARTNUMBER,UPDATEDDATE=GETDATE() 
										WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE	AND OPERATIONCODE =@OPERATIONCODE
								END
								ELSE 
									BEGIN
										INSERT INTO ASSY_MACHINEWISE_RUNNINGPART(PROFITCENTERCODE,LINECODE,OPERATIONCODE,MACHINECODE ,PARTNO,CREATEDDATE)
										SELECT @PROFITCENTERCODE,@LINECODE,@OPERATIONCODE,@MACHINECODE,@PARTNUMBER,GETDATE()

									END
						END
				--START-- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING STOCK DEDUCTION
				IF ((SELECT ISNULL(ISMATFEEDREQUIRED, 0) FROM LINEMST WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE) = 1)
				BEGIN
					EXEC ASSY_PROC_MATERIALFEEDINGVALIDATION
					@CONDITION = 'MAT_FEED_STOCK_DEDUCTION', 
					@PROFITCENTERCODE = @PROFITCENTERCODE, 
					@LINECODE = @LINECODE, 
					@USERID = @USERID, 
					@PARTNUMBER = @PARTNUMBER, 
					@BARCODE = @BARCODE							
				END
				--END-- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING STOCK DEDUCTION
			END

			IF EXISTS (SELECT 1 FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE BARCODE = @BARCODE AND PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE)
			BEGIN
				INSERT INTO ASSY_LINEASSYSTATUS_HISTORY (PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE, STATIONCODE, BARCODE, STATUS, FAILCOUNT, DATECODE, PARTNO,
					SCANTIMESTAMP, RESULTTIMESTAMP, USERID,PRODUCTIONORDERNO, His_ENT_DT, His_ENT_BY, Active, Category,IsReworkPart)
				SELECT PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE, STATIONCODE, BARCODE, STATUS, FAILCOUNT, DATECODE, PARTNO,
					SCANTIMESTAMP, RESULTTIMESTAMP, USERID, PRODUCTIONORDERNO, GETDATE(), @USERID, 1, Category,IsReworkPart
					FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND BARCODE = @BARCODE

				DELETE FROM ASSY_LINEASSYSTATUS WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND BARCODE = @BARCODE
			END
			--Added By Sachin 2020May25
			if(ISNULL(@P_ProductionOrderNo,'') <>'')
			begin
					set @PRODUCTIONORDERNO = @P_ProductionOrderNo;
			End
			--Ended By Sachin 2020May25
			
				INSERT INTO ASSY_LINEASSYSTATUS
				(
					PROFITCENTERCODE, 
					LINECODE, 
					MACHINECODE, 
					OPERATIONCODE, 
					STATIONCODE, 
					BARCODE, 
					STATUS, 
					FAILCOUNT, 
					DATECODE, 
					PARTNO, 
					SCANTIMESTAMP, 
					RESULTTIMESTAMP, 
					USERID,
					PRODUCTIONORDERNO,
					PROD_LOT_NO,
					Category,
					Live_Datecode,
					Kanban_ID,
					IsReworkPart
				)

				SELECT 
					@PROFITCENTERCODE, 
					@LINECODE, 
					@MACHINECODE, 
					@OPERATIONCODE, 
					@STATIONCODE, 
					@BARCODE, 
					@STATUS, 
					@PARTFAILEDCOUNT, 
					@DATECODE, 
					@PARTNUMBER, 
					ISNULL(@SCANTIMESTAMP,GETDATE()),
					ISNULL(@RESULTTIMESTAMP,GETDATE()),
					@USERID,
					@PRODUCTIONORDERNO,
					@P_LOT_NO,
					@Category,
					@Live_Datecode,
					ISNULL(@Kanban_Id,''),
					@Rework

					-- ADDED BY SACHIN TO SAVE BRACKET ASSY DATA
					IF OBJECT_ID('DBO.ASSY_BRACKETDATA','U') IS NOT NULL
					BEGIN
						  IF(ISNULL(@P_ECU_BARCODE,'') <> '')
						  BEGIN
								  INSERT INTO ASSY_BRACKETDATA(
								  PROFITCENTERCODE,LINECODE,BARCODE,ECU_BARCODE,PART_NO,RESULT,ENTDATE,PRCSS_FLG,PRCSS_DT						  
								  )
								  SELECT @PROFITCENTERCODE,@LINECODE,@BARCODE,@P_ECU_BARCODE,@PARTNUMBER,@STATUS,GETDATE(),0,NULL
						  END
					END
						
				----START-- ADDED BY RASHID SIDDIQUI ON 08TH AUGUST 2016 FOR MATERIAL FEEDING STOCK DEDUCTION
				IF ((SELECT ISNULL(ISPRODCONFREQUIRED, 0) FROM LINEMST WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE) = 1)
				BEGIN
					IF EXISTS (SELECT 1 FROM ASSY_MAT_FEED_STATUS_ISPRODCONF WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE)
					BEGIN
						UPDATE ASSY_FGCHILDPARTCONSUMPTION SET ISACTIVE = 2 WHERE WH_CODE = @PROFITCENTERCODE AND LINE_CODE = @LINECODE AND ISACTIVE = 1
						DELETE FROM ASSY_MAT_FEED_STATUS_ISPRODCONF WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
					END
				END
				----END-- ADDED BY RASHID SIDDIQUI ON 08TH AUGUST 2016 FOR MATERIAL FEEDING STOCK DEDUCTION

				--ADDED BY RAVI ON 18/03/16-------------
				DELETE FROM ASSY_LINEASSYSTATUS_FV_LASTTESTED_BARCODE WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
				
				INSERT INTO ASSY_LINEASSYSTATUS_FV_LASTTESTED_BARCODE (PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE, BARCODE, DATECODE, PARTNO, SCANTIMESTAMP, RESULTTIMESTAMP)
				SELECT @PROFITCENTERCODE, @LINECODE, @MACHINECODE, @OPERATIONCODE, @BARCODE, @DATECODE, @PARTNUMBER, @SCANTIMESTAMP, @RESULTTIMESTAMP
				--------------------------END--------------
				
				IF @STATUS = 'PS'
				BEGIN
					-- ADD/COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
					--DECLARE @GROUPCODE VARCHAR(10) = ''
					SELECT @GROUPCODE = GROUPCODE FROM ASSY_LINEGROUP_MASTER (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE

					-----------------------Added by Prerna Gupta for EKanban Process
						Declare @Isekanbanreq varchar(2) , @ekanbanMode int;
						SELECT @Isekanbanreq=DBO.[FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE](@ProfitCenterCode,'LINE_ATTRB','eKanban_Enable',@LineCode,'')
						if(isnull(@Isekanbanreq,0)=1)
						Begin
							SELECT @ekanbanMode=DBO.[FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE](@ProfitCenterCode,'LINE_ATTRB','E_KANBAN_MODE',@LineCode,'')																		
						end
					------------------END

					IF(ISNULL(@P_ProductionOrderNo,'')<>''  and ISNULL( @ALLOW2PARTS,0)=1) -- Added By Sachin 2020May22
					BEGIN
												
						--UPDATE PRODUCE QTY INTO ASSY_PRODUCTIONORDERMST
						if(@Isekanbanreq = 1)
						Begin

							UPDATE POM SET PRODUCEDQTY = ISNULL(PRODUCEDQTY, 0) + 1, 
							POM.STATUS = CASE WHEN POM.QTY = ISNULL(POM.PRODUCEDQTY, 0) + 1 AND @ekanbanMode in ('1','3')  THEN '100' 
							else '50' END,
							last_upd_stamp =getdate(),
							LAST_UPD_BY =@UserId
							FROM ASSY_PRODUCTIONORDERMST (NOLOCK) POM
							WHERE 
							POM.PROFITCENTERCODE = @PROFITCENTERCODE
							AND ISNULL(POM.STATUS,0) <> '100'
							AND POM.ORDERNO=ISNULL(@P_ProductionOrderNo,'')
							AND POM.PARTNO = ISNULL(@PARTNUMBER,'')

							if exists(select top 1 1
							FROM ASSY_PRODUCTIONORDERMST (NOLOCK) POM
							WHERE 
							POM.PROFITCENTERCODE = @PROFITCENTERCODE
							AND ISNULL(POM.STATUS,0) <> '100'
							AND POM.ORDERNO=ISNULL(@P_ProductionOrderNo,'')
							AND POM.PARTNO = ISNULL(@PARTNUMBER,'')
							AND balanceqty = 0
							)
							begin
								UPDATE PBM SET PBM.STS_CD ='50',
								PBM.LAST_UPD_DATE =getdate(),
								PBM.LAST_UPD_BY =@UserId			
								FROM Physical_bin_Master (NOLOCK) PBM
								Where PBM.STS_CD <> '100'	
								AND PBM.ORDER_NO=ISNULL(@P_ProductionOrderNo,'')
								AND PBM.PART_NO = ISNULL(@PARTNUMBER,'')
								AND PBM.BIN_TYPE = 'EPK'
							end

						end
						else
						Begin

							UPDATE POM 
							SET PRODUCEDQTY = ISNULL(PRODUCEDQTY, 0) + 1, 
							POM.STATUS = CASE WHEN POM.QTY = ISNULL(POM.PRODUCEDQTY, 0) + 1 THEN '100' END,
							last_upd_stamp =getdate(),
							LAST_UPD_BY =@UserId
							FROM ASSY_PRODUCTIONORDERMST (NOLOCK) POM							
							WHERE
							POM.PROFITCENTERCODE = @PROFITCENTERCODE
							AND ISNULL(POM.STATUS,0) <> '100'
							AND POM.ORDERNO=ISNULL(@P_ProductionOrderNo,'')
							AND POM.PARTNO = ISNULL(@PARTNUMBER,'')
							
						End

						UPDATE ASSY_PRODUCTIONORDER_PARAMETERSETTING 
						SET PRODUCTIONQTY = ISNULL(PRODUCTIONQTY, 0) + 1, BALANCEQTY = ISNULL(BALANCEQTY,0) - 1						
						WHERE LINECODE = ISNULL(@LINECODE,'')   AND PROFITCENTERCODE = ISNULL(@PROFITCENTERCODE,'')
						AND ProdOrderNo = ISNULL(@P_ProductionOrderNo,'') and PartNumber=ISNULL(@PARTNUMBER,'')
						AND CURRENTPLANNEDQTY > ISNULL(PRODUCTIONQTY, 0)
																			
						UPDATE ASSY_RUNNINGPART_PREVIOUS 
						SET PRODUCEDQTY = ISNULL(PRODUCEDQTY, 0) + 1 , BALANCEQTY = ISNULL(BALANCEQTY,0) - 1,
						ModifiedOn=getdate(),ModifiedBy=@UserId
						WHERE LineCode  = ISNULL(@LINECODE,'')   
						AND ProductionOrderNo = ISNULL(@P_ProductionOrderNo,'') and Assy_PartNo=ISNULL(@PARTNUMBER,'')
						AND CURRENTPLANNEDQTY > ISNULL(PRODUCEDQTY, 0)

					END
					ELSE
					BEGIN
					IF EXISTS
					(
						SELECT 1 FROM ASSY_RUNNINGPART_PREVIOUS (NOLOCK) WHERE ASSY_MODE IN ('PRODUCTION', 'REWORK')
							AND LINECODE = @LINECODE AND CURRENTPLANNEDQTY > ISNULL(PRODUCEDQTY, 0)
					)
					BEGIN
						--UPDATE PRODUCE QTY INTO ASSY_PRODUCTIONORDERMST
						if(@Isekanbanreq = 1)
						Begin
								Select top 1 * into #ASSY_RUNNINGPART_PREVIOUS from ASSY_RUNNINGPART_PREVIOUS where 
								LINECODE = @LINECODE AND CURRENTPLANNEDQTY > ISNULL(PRODUCEDQTY, 0) AND 
								Assy_PartNo=@PARTNUMBER order by CreatedDate asc

								UPDATE POM SET POM.PRODUCEDQTY = ISNULL(POM.PRODUCEDQTY, 0) + 1,
								POM.STATUS = CASE WHEN POM.QTY = ISNULL(POM.PRODUCEDQTY, 0) + 1 AND @ekanbanMode in ('1','3')  THEN '100' 
								else '50' END,
								last_upd_stamp =getdate(),
								LAST_UPD_BY =@UserId
								FROM ASSY_PRODUCTIONORDERMST (NOLOCK) POM
								INNER JOIN #ASSY_RUNNINGPART_PREVIOUS (NOLOCK) RP ON POM.ORDERNO = RP.PRODUCTIONORDERNO AND POM.PARTNO = RP.ASSY_PARTNO					
								WHERE RP.LINECODE = @LINECODE  
								AND POM.PROFITCENTERCODE = @PROFITCENTERCODE
								AND ISNULL(POM.STATUS,0) <> '100'
								AND POM.WORKCENTERCODE 
								IN
								(
									-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
									-- SELECT  DISTINCT L.WORKCENTERCODE FROM LINEMST (NOLOCK) L
									SELECT L.WORKCENTERCODE FROM LINEMST (NOLOCK) L
									INNER JOIN ASSY_LINEGROUP_MASTER (NOLOCK) LG ON L.PROFITCENTERCODE = LG.PROFITCENTERCODE AND L.LINECODE = LG.LINECODE
									-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
									-- WHERE LG.GROUPCODE = (SELECT GROUPCODE FROM ASSY_LINEGROUP_MASTER (NOLOCK) WHERE LINECODE = @LINECODE) AND L.ISACTIVE = 1
									WHERE LG.GROUPCODE = @GROUPCODE AND L.ISACTIVE = 1 AND L.PROFITCENTERCODE = @PROFITCENTERCODE
								)

								UPDATE PBM SET PBM.STS_CD = '50',
								PBM.LAST_UPD_DATE=getdate(),
								PBM.LAST_UPD_BY=@UserId			
								FROM Physical_bin_Master (NOLOCK) PBM
								INNER JOIN #ASSY_RUNNINGPART_PREVIOUS (NOLOCK) RP ON PBM.ORDER_NO = RP.PRODUCTIONORDERNO AND PBM.part_no = RP.ASSY_PARTNO
								where isnull(RP.PRODUCEDQTY, 0)=0
								and  PBM.STS_CD <> '100'	
								AND PBM.BIN_TYPE = 'EPK'

								UPDATE RPS SET RPS.PRODUCEDQTY = ISNULL(RPS.PRODUCEDQTY, 0) + 1 , RPS.BALANCEQTY = ISNULL(RPS.BALANCEQTY,0) - 1 
								from ASSY_RUNNINGPART_PREVIOUS RPS
								Inner Join #ASSY_RUNNINGPART_PREVIOUS (NOLOCK) RK ON  RK.ProductionOrderNo=RPS.PRODUCTIONORDERNO
								WHERE RPS.LINECODE = @LINECODE  

						end
						else
						Begin
						
								UPDATE POM SET POM.PRODUCEDQTY = ISNULL(POM.PRODUCEDQTY, 0) + 1, POM.STATUS = CASE WHEN POM.QTY = ISNULL(POM.PRODUCEDQTY, 0) + 1 THEN '100' END,
								last_upd_stamp =getdate(),
								LAST_UPD_BY =@UserId
								FROM ASSY_PRODUCTIONORDERMST (NOLOCK) POM
								INNER JOIN ASSY_RUNNINGPART_PREVIOUS (NOLOCK) RP ON POM.ORDERNO = RP.PRODUCTIONORDERNO AND POM.PARTNO = RP.ASSY_PARTNO
								WHERE RP.LINECODE = @LINECODE  
								AND POM.PROFITCENTERCODE = @PROFITCENTERCODE
								AND ISNULL(POM.STATUS,0) <> '100'
								AND POM.WORKCENTERCODE 
								IN
								(
									-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
									-- SELECT  DISTINCT L.WORKCENTERCODE FROM LINEMST (NOLOCK) L
									SELECT L.WORKCENTERCODE FROM LINEMST (NOLOCK) L
									INNER JOIN ASSY_LINEGROUP_MASTER (NOLOCK) LG ON L.PROFITCENTERCODE = LG.PROFITCENTERCODE AND L.LINECODE = LG.LINECODE
									-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
									-- WHERE LG.GROUPCODE = (SELECT GROUPCODE FROM ASSY_LINEGROUP_MASTER (NOLOCK) WHERE LINECODE = @LINECODE) AND L.ISACTIVE = 1
									WHERE LG.GROUPCODE = @GROUPCODE AND L.ISACTIVE = 1 AND L.PROFITCENTERCODE = @PROFITCENTERCODE
								)

								UPDATE ASSY_RUNNINGPART_PREVIOUS SET PRODUCEDQTY = ISNULL(PRODUCEDQTY, 0) + 1 , BALANCEQTY = ISNULL(BALANCEQTY,0) - 1
								WHERE LINECODE = @LINECODE 
						end
				

						--UPDATE ASSY_RUNNINGPART_PREVIOUS SET BALANCEQTY = ISNULL(CURRENTPLANNEDQTY, 0)-ISNULL(PRODUCEDQTY, 0)
						--	WHERE LINECODE = @LINECODE

						--UPDATE POM SET POM.STATUS = '100'  FROM ASSY_PRODUCTIONORDERMST (NOLOCK) POM
						--INNER JOIN ASSY_RUNNINGPART_PREVIOUS (NOLOCK) RP ON POM.ORDERNO = RP.PRODUCTIONORDERNO AND POM.PARTNO = RP.ASSY_PARTNO 							
						--WHERE RP.LINECODE = @LINECODE  
						--AND POM.PROFITCENTERCODE = @PROFITCENTERCODE
						--AND POM.STATUS <> '100'
						--AND POM.QTY = POM.PRODUCEDQTY
						--AND POM.WORKCENTERCODE 
						--IN
						--(
						--	-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
						--	-- SELECT  DISTINCT L.WORKCENTERCODE FROM LINEMST (NOLOCK) L
						--	SELECT L.WORKCENTERCODE FROM LINEMST (NOLOCK) L
						--	INNER JOIN ASSY_LINEGROUP_MASTER (NOLOCK) LG ON L.PROFITCENTERCODE = LG.PROFITCENTERCODE AND L.LINECODE = LG.LINECODE
						--	-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
						--	-- WHERE LG.GROUPCODE = (SELECT GROUPCODE FROM ASSY_LINEGROUP_MASTER (NOLOCK) WHERE LINECODE = @LINECODE) AND L.ISACTIVE = 1
						--	WHERE LG.GROUPCODE = @GROUPCODE AND L.ISACTIVE = 1 AND L.PROFITCENTERCODE = @PROFITCENTERCODE
						--)
							
						--IF EXISTS
						--( 
						--	SELECT 1 FROM ASSY_RUNNINGPART_PREVIOUS (NOLOCK) WHERE ASSY_MODE IN ('PRODUCTION', 'REWORK')
						--	AND LINECODE = @LINECODE AND CURRENTPLANNEDQTY = ISNULL(PRODUCEDQTY, 0)
						--)
						--BEGIN
							--DELETE FROM ASSY_RUNNINGPART_PREVIOUS WHERE LINECODE = @LINECODE AND CURRENTPLANNEDQTY = ISNULL(PRODUCEDQTY, 0)
						--END
					END
					ELSE
					BEGIN
						--UPDATE PRODUCE QTY INTO ASSY_PRODUCTIONORDERMST
						if(@Isekanbanreq = 1)
						Begin
							UPDATE POM SET PRODUCEDQTY = ISNULL(PRODUCEDQTY, 0) + 1, 
							POM.STATUS = CASE WHEN POM.QTY = ISNULL(POM.PRODUCEDQTY, 0) + 1 AND @ekanbanMode in ('1','3')  THEN '100' 
							else '50' END,
							last_upd_stamp =getdate(),
							LAST_UPD_BY =@UserId
							FROM ASSY_PRODUCTIONORDERMST (NOLOCK) POM
							INNER JOIN ASSY_RUNNINGPART (NOLOCK) RP ON POM.ORDERNO = RP.PRODUCTIONORDERNO AND POM.PARTNO = RP.ASSY_PARTNO 
							WHERE RP.LINECODE = @LINECODE  
							AND POM.PROFITCENTERCODE = @PROFITCENTERCODE
							AND ISNULL(POM.STATUS,0) <> '100'
							AND POM.WORKCENTERCODE 
							IN
							(
								-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
								-- SELECT  DISTINCT L.WORKCENTERCODE FROM LINEMST (NOLOCK) L
								SELECT L.WORKCENTERCODE FROM LINEMST (NOLOCK) L
								INNER JOIN ASSY_LINEGROUP_MASTER (NOLOCK) LG ON L.PROFITCENTERCODE = LG.PROFITCENTERCODE AND L.LINECODE = LG.LINECODE
								-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
								-- WHERE LG.GROUPCODE = (SELECT GROUPCODE FROM ASSY_LINEGROUP_MASTER (NOLOCK) WHERE LINECODE = @LINECODE) AND L.ISACTIVE = 1
								WHERE LG.GROUPCODE = @GROUPCODE AND L.ISACTIVE = 1 AND L.PROFITCENTERCODE = @PROFITCENTERCODE
							)


							UPDATE PBM SET PBM.STS_CD = '50',
							PBM.LAST_UPD_DATE=getdate(),
							PBM.LAST_UPD_BY=@UserId				
							FROM Physical_bin_Master (NOLOCK) PBM
							INNER JOIN ASSY_PRODUCTIONORDER_PARAMETERSETTING (NOLOCK) RP 
							ON PBM.ORDER_NO = RP.ProdOrderNo AND PBM.part_no = RP.PartNumber
							where  PBM.STS_CD <> '100'							
							AND PBM.BIN_TYPE = 'EPK'

						end
						else
						Begin
							UPDATE POM SET PRODUCEDQTY = ISNULL(PRODUCEDQTY, 0) + 1, POM.STATUS = CASE WHEN POM.QTY = ISNULL(POM.PRODUCEDQTY, 0) + 1 THEN '100' END
							FROM ASSY_PRODUCTIONORDERMST (NOLOCK) POM
							INNER JOIN ASSY_RUNNINGPART (NOLOCK) RP ON POM.ORDERNO = RP.PRODUCTIONORDERNO AND POM.PARTNO = RP.ASSY_PARTNO 
							WHERE RP.LINECODE = @LINECODE  
							AND POM.PROFITCENTERCODE = @PROFITCENTERCODE
							AND ISNULL(POM.STATUS,0) <> '100'
							AND POM.WORKCENTERCODE 
							IN
							(
								-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
								-- SELECT  DISTINCT L.WORKCENTERCODE FROM LINEMST (NOLOCK) L
								SELECT L.WORKCENTERCODE FROM LINEMST (NOLOCK) L
								INNER JOIN ASSY_LINEGROUP_MASTER (NOLOCK) LG ON L.PROFITCENTERCODE = LG.PROFITCENTERCODE AND L.LINECODE = LG.LINECODE
								-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
								-- WHERE LG.GROUPCODE = (SELECT GROUPCODE FROM ASSY_LINEGROUP_MASTER (NOLOCK) WHERE LINECODE = @LINECODE) AND L.ISACTIVE = 1
								WHERE LG.GROUPCODE = @GROUPCODE AND L.ISACTIVE = 1 AND L.PROFITCENTERCODE = @PROFITCENTERCODE
							)
						End

						UPDATE ASSY_PRODUCTIONORDER_PARAMETERSETTING SET PRODUCTIONQTY = ISNULL(PRODUCTIONQTY, 0) + 1, BALANCEQTY = ISNULL(BALANCEQTY,0) - 1
						WHERE LINECODE = @LINECODE   AND PROFITCENTERCODE = @PROFITCENTERCODE
						
						--UPDATE ASSY_PRODUCTIONORDER_PARAMETERSETTING SET BALANCEQTY = ISNULL(CURRENTPLANNEDQTY, 0)-ISNULL(PRODUCTIONQTY, 0)
						--	WHERE LINECODE = @LINECODE   AND PROFITCENTERCODE = @PROFITCENTERCODE
						
						--UPDATE POM SET POM.STATUS = '100'  FROM ASSY_PRODUCTIONORDERMST (NOLOCK) POM
						--INNER JOIN ASSY_RUNNINGPART (NOLOCK) RP ON POM.ORDERNO = RP.PRODUCTIONORDERNO AND POM.PARTNO = RP.ASSY_PARTNO 							
						--WHERE RP.LINECODE = @LINECODE  
						--AND POM.PROFITCENTERCODE = @PROFITCENTERCODE
						--AND POM.STATUS <> '100'
						--AND POM.QTY = POM.PRODUCEDQTY
						--AND POM.WORKCENTERCODE 
						--IN
						--(
						--	-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
						--	-- SELECT  DISTINCT L.WORKCENTERCODE FROM LINEMST (NOLOCK) L
						--	SELECT L.WORKCENTERCODE FROM LINEMST (NOLOCK) L
						--	INNER JOIN ASSY_LINEGROUP_MASTER (NOLOCK) LG ON L.PROFITCENTERCODE = LG.PROFITCENTERCODE AND L.LINECODE = LG.LINECODE
						--	-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
						--	-- WHERE LG.GROUPCODE = (SELECT GROUPCODE FROM ASSY_LINEGROUP_MASTER (NOLOCK) WHERE LINECODE = @LINECODE) AND L.ISACTIVE = 1
						--	WHERE LG.GROUPCODE = @GROUPCODE AND L.ISACTIVE = 1 AND L.PROFITCENTERCODE = @PROFITCENTERCODE
						--)
					END
					END
					
					--Added By Sachin 2020June03
					if exists(select top 1 1 FROM ASSY_RUNNINGPART_PREVIOUS WHERE LINECODE = @LINECODE AND CURRENTPLANNEDQTY = ISNULL(PRODUCEDQTY, 0 ))
					begin
					print 1
						--DELETE FROM ASSY_RUNNINGPART_PREVIOUS WHERE LINECODE = @LINECODE AND CURRENTPLANNEDQTY = ISNULL(PRODUCEDQTY, 0)
					end
					--Ended By Sachin 2020June03

					SELECT @RETURNVALUE = 'SUCCESS', @RETURNINT = 1
				END
			END TRY
		
			BEGIN CATCH			
				SET @RETURNVALUE = 	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
				CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
				CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_MESSAGE() AS VARCHAR(1500))		
				SET @RETURNINT = 2
				--ROLLBACK TRAN
				RAISERROR(@RETURNVALUE, 16, 1)
			END CATCH

			RETURN
		END
		
		ELSE IF @CONDITION = 'GET_PREFIX_SUFFIX_LIST'
		BEGIN
				;WITH R(PROFITCENTERCODE, LINECODE, OPERATIONCODE)
				AS
				(
					SELECT L.PROFITCENTERCODE, L.LINECODE, L.OPERATIONCODE
						FROM ROUTINGCONFIGLINEWISE (NOLOCK) L			   
						WHERE L.LINECODE = @LINECODE AND L.PROFITCENTERCODE = @PROFITCENTERCODE
						AND L.TRACEABILITY = 1  AND ISNULL(L.ENGRAVING, 0) = 0 
				)
				SELECT M.PREFIX, M.SUFFIX
					FROM R WITH (NOLOCK)
				INNER JOIN MACHINEDTL (NOLOCK) M
					ON M.OPERATIONCODE = R.OPERATIONCODE AND M.PROFITCENTERCODE = R.PROFITCENTERCODE AND M.LineCode = R.LineCode
				WHERE M.PREFIX <> '' AND M.SUFFIX <> ''
			RETURN
		END

		ELSE IF @CONDITION = 'UPDATE_FV_QC_OK_FAIL_DATA_IN_MAINSERVER'
		BEGIN
			BEGIN TRY
			--#20210709
			if(CHARINDEX('|',@STATUS) <> 0)
			Begin
				select @STATUS=col1,@Rework=isnull(col2,0) from dbo.FN_GRID_SPLIT_STRING(isnull(@STATUS,'NULL'),'|','');
			End
			INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
			SELECT @PROFITCENTERCODE, 'FV_MAIN_PASS', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, 
			'ScanTimestamp-' + CONVERT(VARCHAR(30),@ScanTimestamp) + ',ResultTimestamp-' + CONVERT(VARCHAR(30),@ResultTimestamp) + ',Status-' + ISNULL(@Status,''),
			@USERID, GETDATE(), @USERID, GETDATE()

			IF @PRNGroupCode = 'GC_TML'
			BEGIN
				IF EXISTS (SELECT 1 FROM Assy_FinalViewing_RFID_Barcode_Mapping (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @BARCODE)
				BEGIN
					SELECT @NBarcode = BARCODE FROM Assy_FinalViewing_RFID_Barcode_Mapping (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @BARCODE
					SET @BARCODE = @NBarcode
				END
			END

			/*
			--Waki Customer Barcode Data - Added By RS On 20180828 For Waki Non-Mahindra Logic
			IF EXISTS
			(
				SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
					AND KeyType = 'WakiLogic' AND KeyValue = '1'
			)
			BEGIN
				IF EXISTS (SELECT 1 FROM Assy_FinalViewing_RFID_Barcode_Mapping (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @BARCODE)
				BEGIN
					SELECT @NBarcode = BARCODE FROM Assy_FinalViewing_RFID_Barcode_Mapping (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @BARCODE
					SET @BARCODE = @NBarcode
				END
			END
			*/

			IF EXISTS (SELECT 1 FROM ASSY_LINEASSYSTATUS (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND
				MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND STATUS = 'FL' AND BARCODE = @BARCODE)
			BEGIN
				DELETE FROM ASSY_LINEASSYSTATUS WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND
					MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND STATUS = 'FL' AND BARCODE = @BARCODE
			END
			---- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING STOCK DEDUCTION ----
			ELSE
			BEGIN
					    --CHANGED BY RAVI ON 08-08-17 TO UPDATE DATA INTO ASSY_MACHINEWISE_RUNNINGPART
					    IF ISNULL( @ALLOW2PARTS,0)=1
						BEGIN
								IF EXISTS
								( 
										SELECT 1 FROM ASSY_MACHINEWISE_RUNNINGPART WITH(NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
										AND OPERATIONCODE = @OPERATIONCODE
								)
								BEGIN
										UPDATE ASSY_MACHINEWISE_RUNNINGPART SET PARTNO = @PARTNUMBER,UPDATEDDATE=GETDATE() 
										WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE	AND OPERATIONCODE =@OPERATIONCODE
								END
								ELSE 
									BEGIN
										INSERT INTO ASSY_MACHINEWISE_RUNNINGPART(PROFITCENTERCODE,LINECODE,OPERATIONCODE,MACHINECODE ,PARTNO,CREATEDDATE)
										SELECT @PROFITCENTERCODE,@LINECODE,@OPERATIONCODE,@MACHINECODE,@PARTNUMBER,GETDATE()

									END
						END
				--START-- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING STOCK DEDUCTION
				IF ((SELECT ISNULL(ISMATFEEDREQUIRED, 0) FROM LINEMST WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE) = 1)
				BEGIN
					EXEC ASSY_PROC_MATERIALFEEDINGVALIDATION
					@CONDITION = 'MAT_FEED_STOCK_DEDUCTION',
					@PROFITCENTERCODE = @PROFITCENTERCODE, 
					@LINECODE = @LINECODE, 
					@USERID = @USERID, 
					@PARTNUMBER = @PARTNUMBER, 
					@BARCODE = @BARCODE
				END
				--END-- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING STOCK DEDUCTION
			END
				--MODIFIED BY SUDESH ON 20170516 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
				INSERT INTO ASSY_LINEASSYSTATUS
				(
					PROFITCENTERCODE, 
					LINECODE, 
					MACHINECODE, 
					OPERATIONCODE, 
					STATIONCODE, 
					BARCODE, 
					STATUS, 
					FAILCOUNT, 
					DATECODE, 
					PARTNO, 
					SCANTIMESTAMP, 
					RESULTTIMESTAMP, 
					USERID,
					PRODUCTIONORDERNO,
					PROD_LOT_NO,
					Category,
					Live_Datecode,
					IsReworkPart
				)

				SELECT 
					@PROFITCENTERCODE, 
					@LINECODE, 
					@MACHINECODE, 
					@OPERATIONCODE, 
					@STATIONCODE, 
					@BARCODE, 
					@STATUS, 
					@PARTFAILEDCOUNT, 
					(SELECT TOP 1 DATECODE FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE ), 
					@PARTNUMBER, 
					@SCANTIMESTAMP, 
					@RESULTTIMESTAMP, 
					@USERID,
					@PRODUCTIONORDERNO,
					@P_LOT_NO,
					@Category,
					@Live_Datecode,
					@Rework

					-- ADDED BY SACHIN TO SAVE BRACKET ASSY DATA
					IF OBJECT_ID('DBO.ASSY_BRACKETDATA','U') IS NOT NULL
					BEGIN
						 IF(ISNULL(@P_ECU_BARCODE,'') <> '')
						  BEGIN
								  INSERT INTO ASSY_BRACKETDATA(
								  PROFITCENTERCODE,LINECODE,BARCODE,ECU_BARCODE,PART_NO,RESULT,ENTDATE,PRCSS_FLG,PRCSS_DT						  
								  )
								  SELECT @PROFITCENTERCODE,@LINECODE,@BARCODE,@P_ECU_BARCODE,@PARTNUMBER,@STATUS,GETDATE(),0,NULL
						  END
					END

				----START-- ADDED BY RASHID SIDDIQUI ON 08TH AUGUST 2016 FOR MATERIAL FEEDING STOCK DEDUCTION
				IF ((SELECT ISNULL(ISPRODCONFREQUIRED, 0) FROM LINEMST WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE) = 1)
				BEGIN
					IF EXISTS (SELECT 1 FROM ASSY_MAT_FEED_STATUS_ISPRODCONF WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE)
					BEGIN
						UPDATE ASSY_FGCHILDPARTCONSUMPTION SET ISACTIVE = 2 WHERE WH_CODE = @PROFITCENTERCODE AND LINE_CODE = @LINECODE AND ISACTIVE = 1
						DELETE FROM ASSY_MAT_FEED_STATUS_ISPRODCONF WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
					END
				END

				--ADDED BY RAVI ON 18/03/16-------------
				DELETE FROM ASSY_LINEASSYSTATUS_FV_LASTTESTED_BARCODE WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
			
				INSERT INTO ASSY_LINEASSYSTATUS_FV_LASTTESTED_BARCODE (PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE, BARCODE, DATECODE, PARTNO, SCANTIMESTAMP, RESULTTIMESTAMP)
				SELECT @PROFITCENTERCODE, @LINECODE, @MACHINECODE, @OPERATIONCODE, @BARCODE, @DATECODE, @PARTNUMBER, @SCANTIMESTAMP, @RESULTTIMESTAMP

				--Added By Rashid For ABS Fail Part-Trolley Association Logic From Central Server On 23rd Nov 2018 (Only for Fail Case)
				IF EXISTS (SELECT TOP 1 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE AND LineCode = @LINECODE
					AND KeyType = 'ABSFVFailTrayReq' AND STS_CD = 0 AND KeyValue = 1)
				BEGIN
					IF EXISTS (SELECT 1 FROM VIEWING_MACHINE(NOLOCK) WHERE Barcode = @BARCODE AND ProcessType = 'ABS_FTA' AND WH_CODE = @PROFITCENTERCODE)
					BEGIN
						DELETE FROM VIEWING_MACHINE WHERE Barcode = @BARCODE AND ProcessType = 'ABS_FTA' AND WH_CODE = @PROFITCENTERCODE
					END

					INSERT INTO VIEWING_MACHINE (BARCODE,DATE_CODE,STS,STATION_CD,LINE_CODE,VW_PARTNO,ENT_STAMP,ENT_BY,UPD_STAMP,UPD_BY,WH_CODE,TrolleyID,IsComplete,ProcessType)
					SELECT @BARCODE, @DATECODE, 0, @OPERATIONCODE, @LINECODE, @PARTNUMBER, GETDATE(), @USERID, GETDATE(), @USERID, @PROFITCENTERCODE, '', 0, 'ABS_FTA'
				END

				--------------------------END--------------
				SET @RETURNVALUE = 'SUCCESS'
				SET @RETURNINT = 1
			END TRY
			
			BEGIN CATCH			
				SET @RETURNVALUE = 	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
				CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
				CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_MESSAGE() AS VARCHAR(1500))		
				SET @RETURNINT = 2
				--ROLLBACK TRAN
				RAISERROR(@RETURNVALUE, 16, 1)
			END CATCH
			RETURN
		END

		ELSE IF @CONDITION = 'UPDATE_FINALVIEWING_FROMLOCALDBTOMAIN'
		BEGIN
			DECLARE @OPCODE VARCHAR(20) = '', @FV_COUNT INT = 0, @ERRORCOUNT INT = -1
			DECLARE @DROP_RECORDS INT = 0
			
			SELECT @DROP_RECORDS = COUNT(*) FROM ASSY_LINEASSYSTATUS_NETWORK_DROP_RECORDS (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE --AND LINECODE = @LINECODE
			
			IF (@DROP_RECORDS > 0)
			BEGIN
				--SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL  WITH (NOLOCK) 
				--	WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

				SELECT @OPCODE = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)
				
				IF @OPCODE = ''
				BEGIN
					IF (LEFT(@LINECODE, 1) IN ('M','L'))
						SET @OPCODE = 'OCFV'
					ELSE IF(LEFT(@LINECODE, 1) = 'P')
						SET @OPCODE = 'OCFVSTMC'
				END

				IF (@OPCODE ! = '')
				BEGIN
					--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
					SET @EXECQUERY = '
					INSERT INTO ' + @LINKSERVERNAME + '.DBO.ASSY_LINEASSYSTATUS (PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,STATIONCODE,BARCODE,STATUS,FAILCOUNT,DATECODE,PARTNO,SCANTIMESTAMP,RESULTTIMESTAMP,ACTIVE
					,USERID,ISTALLYCHARTAPPROVED,TRANSACTION_NUMBER,ISCONFIRMED,KANBAN_ID,ERP_CONF_TIMESTAMP
					,ISREWORKPART,IS_MANUAL,PRODUCTIONORDERNO,Category,Live_Datecode)
					SELECT PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,STATIONCODE,BARCODE,STATUS,FAILCOUNT,DATECODE,PARTNO,SCANTIMESTAMP,RESULTTIMESTAMP,ACTIVE,USERID,ISTALLYCHARTAPPROVED,TRANSACTION_NUMBER,ISCONFIRMED
					,KANBAN_ID,ERP_CONF_TIMESTAMP,ISREWORKPART,IS_MANUAL,PRODUCTIONORDERNO,Category,Live_Datecode
					FROM ASSY_LINEASSYSTATUS (NOLOCK) WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + '''
					AND LINECODE = ''' + @LINECODE + ''' AND OPERATIONCODE = ''' + @OPCODE + ''' AND BARCODE IN (SELECT BARCODE FROM ASSY_LINEASSYSTATUS_NETWORK_DROP_RECORDS (NOLOCK) 
					WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''')
					AND BARCODE NOT IN (SELECT BARCODE FROM ' + @LINKSERVERNAME + '.DBO.ASSY_LINEASSYSTATUS WITH (NOLOCK) 
					WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND OPERATIONCODE = ''' + @OPCODE + ''')
					'
					PRINT @EXECQUERY
					EXEC (@EXECQUERY)
					
					SET @ERRORCOUNT = @@ERROR
					
					IF @ERRORCOUNT > 0
					BEGIN
						SELECT @RETURNVALUE = '', @RETURNINT = 0
					RETURN
					END
				END
				
				IF (@ERRORCOUNT = 0)
				BEGIN
				DELETE  ASSY_LINEASSYSTATUS_NETWORK_DROP_RECORDS
				SELECT @RETURNVALUE = 'SUCCESS', @RETURNINT = 1

				--Added by thk on 220418
				IF EXISTS(SELECT TOP 1 1 FROM TYPE_DEFINITION_XREF_DATA(NOLOCK)
				WHERE ATTRB_CD=@LineCode AND TYPE_CATEGORY_CD='LINE_ATTRB'
				AND TYPE_CD='SAVE_DATA_FOR_3RD_PARTY_SYS' AND WH_CODE=@ProfitCenterCode AND ATTRB_VAL='1')
				BEGIN
					UPDATE MachineWiseSetParameterData_3RDParty
					SET Status=1
					WHERE Status=0
				END
				END
			END
			ELSE
			BEGIN
				SELECT @RETURNVALUE = 'NORECORDFOUND', @RETURNINT = 1
			END
		END

		ELSE IF @CONDITION = 'GETASSYRUNNINGPART'
		BEGIN
			SELECT LINECODE, DATECODE, ASSY_PARTNO, PRODUCTIONORDERNO, ASSY_MODE, PARTTYPE, PROFITCENTERCODE, CUSTOMERPARTNO FROM ASSY_RUNNINGPART (NOLOCK)
				WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
			RETURN
		END

		ELSE IF @CONDITION = 'DELETE_RUNNINGPART_NOTPRINT'
		BEGIN
			IF NOT EXISTS(select top 1 1 from linemst with(nolock) where PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE and Allow2Parts='1')
			 BEGIN
				DECLARE @ASSY_DATECODE CHAR(4) = ''
			
				IF ISNULL(RTRIM(@CHANGEOVER_DATECODE), '') = 'NA'
				BEGIN
					EXEC ASSY_PROC_DATECODE @PROFITCENTERCODE = @PROFITCENTERCODE, @RETURNVALUE = @CHANGEOVER_DATECODE OUTPUT      
				END

				IF ISNULL(@CHANGEOVER_DATECODE, '') ! = ''
				BEGIN
					-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
					--SELECT TOP 1 @PARTNO = ASSY_PARTNO, @ASSY_DATECODE = DATECODE FROM ASSY_RUNNINGPART (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					SELECT @PARTNO = ASSY_PARTNO, @ASSY_DATECODE = DATECODE FROM ASSY_RUNNINGPART (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE

					IF @ASSY_DATECODE ! = @CHANGEOVER_DATECODE
					BEGIN
						SELECT @OPERATIONCODE = RTRIM(LTRIM(OPERATIONCODE)) FROM ROUTINGCONFIGLINEWISE (NOLOCK) 
							WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND OPERATIONSEQNO = 1

						IF NOT EXISTS
							(SELECT 1 FROM ASSY_BARCODE_PRINTED_COUNTER A (NOLOCK)
								INNER JOIN
								ASSY_RUNNINGPART R (NOLOCK) 
								ON A.PROFITCENTERCODE = R.PROFITCENTERCODE AND A.LINECODE = R.LINECODE
								WHERE A.LINECODE = @LINECODE AND ISNULL(A.PRINTEDQTY, 0) > 0 AND R.PROFITCENTERCODE = @PROFITCENTERCODE
							)
						BEGIN
							DELETE FROM ASSY_RUNNINGPART WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
							DELETE FROM [dbo].[Assy_ProductionOrder_ParameterSetting] WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

							IF EXISTS(SELECT TOP 1 1 FROM TYPE_DEFINITION_XREF_DATA(NOLOCK)
							WHERE ATTRB_CD=@LineCode AND TYPE_CATEGORY_CD='LINE_ATTRB'
							AND TYPE_CD='eKanban_Enable' AND WH_CODE=@ProfitCenterCode AND ATTRB_VAL='1')
							BEGIN
								DELETE from assy_RunningKanban where PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE and isnull(IsCompleted,0)=0 and 
								isnull(Isrunning,0)=0
							end
							SET @EXECQUERY = ''
						
							SET @EXECQUERY = '
							DELETE FROM ' + @LINKSERVERNAME + '.DBO.ASSY_RUNNINGPART WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''''
							set @EXECQUERY = @EXECQUERY + '
							DELETE FROM ' + @LINKSERVERNAME + '.DBO.Assy_ProductionOrder_ParameterSetting WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''''

							PRINT @EXECQUERY
							EXEC (@EXECQUERY)
						
							SELECT @RETURNVALUE = 'Y', @RETURNINT = 1
						END
						ELSE
						BEGIN
							SELECT @RETURNVALUE = 'N', @RETURNINT = 1
						END
					END
				END
			END 
		END

		ELSE IF @CONDITION = 'ASSY_LINEASSYSTATUS_NETWORK_DROP_RECORDS'
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM ASSY_LINEASSYSTATUS_NETWORK_DROP_RECORDS (NOLOCK) WHERE BARCODE = @BARCODE)
			BEGIN
				INSERT INTO ASSY_LINEASSYSTATUS_NETWORK_DROP_RECORDS
				(
					PROFITCENTERCODE, 
					LINECODE, 
					MACHINECODE, 
					BARCODE,
					Ent_Stamp
				)

				SELECT 
					@PROFITCENTERCODE, 
					@LINECODE, 
					@MACHINECODE, 
					@BARCODE,
					getdate()
			END
		END

		ELSE IF @CONDITION = 'GET_COUPLING_STATIONS_PARAMETER_DATA'
		BEGIN
			SELECT RTRIM(LTRIM(PARAMETER_C2))PARAMETER_C2, RTRIM(LTRIM(PARAMETER_VALUE))PARAMETER_VALUE FROM PARAMETER_MST (NOLOCK) 
				WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'COUPLING' AND  WH_CODE = @PROFITCENTERCODE 
			
			SET @RETURNINT = 1
		END
--ADDED BY RAVI ON 01-06-2016 FOR JHAGADIA
		IF @CONDITION='IS_LABEL_PRINTING_REQUIRED_AT_FV'
		BEGIN
				 IF EXISTS
				 (	
					 SELECT 1 FROM ROUTINGCONFIGLINEWISE WITH (NOLOCK) WHERE PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE=@LINECODE 
					 AND MACHINECODE=DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE) AND ISNULL(LABELPRINTING,0)=1 
				 )
				 BEGIN
						SET @RETURNVALUE = 'Y'

				 END
				 ELSE 
				 BEGIN
						SET @RETURNVALUE = 'N'
				 END
			
			SET @RETURNINT=1
		END

		--ADDED BY RAVI ON 01-06-2016 FOR JHAGADIA
		IF @CONDITION='GET_PRN_FILE_FOR_FV'
		BEGIN
				SELECT @RETURNVALUE=PRNFILE FROM ASSY_PRN_GROUPMASTER WITH(NOLOCK) WHERE GROUPCODE ='GC_JHAGADIA_FINALVIEWING_STATION'			
			    SET @RETURNINT=1
				RETURN
		END
		--ADDED BY RAVI ON 02-08-2016 FOR JHAGADIA
		IF @CONDITION='RUN2PARTS_AT_SAMETIME'
		BEGIN
				--SELECT @RETURNVALUE=PRNFILE FROM ASSY_PRN_GROUPMASTER WITH(NOLOCK) WHERE GROUPCODE ='GC_JHAGADIA_FINALVIEWING_STATION'	
				IF EXISTS
				(
				 SELECT 1 FROM LINEMST WITH(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE 
				 AND ISNULL(ISACTIVE,0)=1 AND ISNULL(ALLOW2PARTS,0)=1 
				)		
				 BEGIN
						SET @RETURNVALUE = 'Y'
				 END
				 ELSE 
				 BEGIN
						SET @RETURNVALUE = 'N'
				 END			
				SET @RETURNINT=1
				RETURN
		END
		ELSE IF @CONDITION='ASSY_LINEASSYSTATUS_RFID_NETWORK_DROP_RECORDS'
		BEGIN
				IF NOT EXISTS 
				(
					SELECT 1 FROM DBO.ASSY_FINALVIEWING_RFID_BARCODE_NETWORK_DROP(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE
					AND RFID = @BARCODE AND MACHINECODE=@MACHINECODE
				)
				BEGIN
					INSERT INTO ASSY_FINALVIEWING_RFID_BARCODE_NETWORK_DROP
					(
						PROFITCENTERCODE,
						LINECODE,
						MACHINECODE,
						RFID
					)
					SELECT 
						@PROFITCENTERCODE,
						@LINECODE,
						@MACHINECODE,
						@BARCODE
				END
				RETURN
		END

		ELSE IF @CONDITION = 'UPDATE_RFID_DATA_FROMLOCALDBTOMAIN'
		BEGIN			
			SELECT @DROP_RECORDS = COUNT(RFID) FROM DBO.ASSY_FINALVIEWING_RFID_BARCODE_NETWORK_DROP (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
																									AND LINECODE = @LINECODE
			IF (@DROP_RECORDS > 0)
			BEGIN
						SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL  WITH (NOLOCK) 
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

						SET @OPCODE=@OPERATIONCODE
					--SELECT @OPCODE = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE)	
					IF (@OPCODE != '')
					BEGIN						

						DECLARE @TV AS TABLE
						(
							 ID INT IDENTITY(1,1),
							 RFID VARCHAR(100)
						)
						INSERT INTO @TV(RFID)					
						SELECT RFID FROM DBO.ASSY_FINALVIEWING_RFID_BARCODE_NETWORK_DROP (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
			
							DECLARE	@COUNTERSTART AS INT=1, @RFIDTAGS VARCHAR(100)																			
							 WHILE (@COUNTERSTART<= @DROP_RECORDS)
							 BEGIN
										  SELECT @RFIDTAGS=RFID FROM @TV WHERE ID=@COUNTERSTART
								 						  
										  SET @EXECQUERY = 'IF  NOT EXISTS(SELECT RFID FROM ' + @LINKSERVERNAME + '.DBO.ASSY_FINALVIEWING_RFID_BARCODE_MAPPING 
														WITH (NOLOCK) WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' 
														AND RFID= ''' + @RFIDTAGS + ''')
											BEGIN
													INSERT INTO ' + @LINKSERVERNAME + '.DBO.ASSY_FINALVIEWING_RFID_BARCODE_MAPPING(PROFITCENTERCODE,LINECODE,MACHINECODE
													,OPERATIONCODE,RFID,BARCODE,STATUS,
													PARTNO,DATECODE,PRINTEDTIMESTAMP,CALIPERSERNO,CALIPERDATECODE)
													SELECT PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,RFID,BARCODE,STATUS,PARTNO,DATECODE,PRINTEDTIMESTAMP
													,CALIPERSERNO,CALIPERDATECODE
													FROM ASSY_FINALVIEWING_RFID_BARCODE_MAPPING (NOLOCK) WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + '''
													AND LINECODE = ''' + @LINECODE + ''' AND OPERATIONCODE = ''' + @OPCODE + ''' AND
													RFID='''+@RFIDTAGS+'''
											END'
											
											EXEC (@EXECQUERY)
											--PRINT @EXECQUERY
											DELETE FROM ASSY_FINALVIEWING_RFID_BARCODE_NETWORK_DROP WHERE RFID=@RFIDTAGS AND PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
											SET @COUNTERSTART=@COUNTERSTART+1
						END
				
					SET @RETURNVALUE = 'SUCCESS'
					SET @RETURNINT = 1
				END
			END
			ELSE
			BEGIN
				SET @RETURNVALUE = 'NORECORDFOUND'
				SET @RETURNINT = 1
			END
		END		

		--ADDED BY RASHID ON 20170601 FOR JHAGADIA
		ELSE IF @CONDITION = 'GET_PART_NO_STATION_WISE_LIST'
		BEGIN
				SELECT AMR.PROFITCENTERCODE, AMR.MACHINECODE, M.MACHINENAME, AMR.OPERATIONCODE, O.OPERATIONNAME, ISNULL(PARTNO,'') PARTNO FROM ASSY_MACHINEWISE_RUNNINGPART AMR WITH (NOLOCK)
					INNER JOIN OPERATIONMST O WITH (NOLOCK)
						ON AMR.PROFITCENTERCODE = O.PROFITCENTERCODE AND AMR.OPERATIONCODE = O.OPERATIONCODE
					INNER JOIN MACHINEMST M WITH (NOLOCK)
						ON AMR.PROFITCENTERCODE = M.PROFITCENTERCODE AND AMR.MACHINECODE = M.MACHINECODE
					WHERE AMR.PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
			    
				SELECT @RETURNINT = 1
				RETURN
		END
		--ADDED BY RASHID ON 20170601 FOR JHAGADIA
		ELSE IF @CONDITION = 'GET_NON_HMI_STATION_LIST'
		BEGIN
				SELECT RCLW.OPERATIONCODE, O.OPERATIONNAME FROM ROUTINGCONFIGLINEWISE RCLW WITH (NOLOCK)
					INNER JOIN OPERATIONMST O WITH (NOLOCK)
						ON RCLW.PROFITCENTERCODE = O.PROFITCENTERCODE AND RCLW.OPERATIONCODE = O.OPERATIONCODE
							WHERE ISHMIRECIPEAVAILABLE = 0 AND RCLW.PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND OPERATIONREQUIRED = 1 AND TRACEABILITY = 1
								ORDER BY OPERATIONSEQNO
			    
				SELECT @RETURNINT = 1
				RETURN
		END
		--ADDED BY RASHID ON 20170601 FOR JHAGADIA
		ELSE IF @CONDITION = 'GET_FAMILY_RUNNING_PART_LIST'
		BEGIN
				SELECT ASSY_PARTNO PARTNO FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
				UNION
			    SELECT ASSY_PARTNO PARTNO FROM ASSY_RUNNINGPARTFAMILY WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

				SELECT @RETURNINT = 1
				RETURN
		END
		--ADDED BY RASHID ON 20170601 FOR JHAGADIA
		ELSE IF @CONDITION = 'UPDATE_PART_NO_STATION_WISE'
		BEGIN
			
			--ADDED BY RASHID ON 20170613 FOR JHAGADIA PC
			IF EXISTS (SELECT 1 FROM LINEMST WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND ISPRODCONFREQUIRED = 1)
			BEGIN
				IF ((SELECT DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE)) = @OPERATIONCODE)
				BEGIN
					DECLARE @PRODCONFPARTNO VARCHAR(30) = '', @IS_POSTED BIT = 0
					SELECT TOP 1 @PRODCONFPARTNO = PARTNO, @IS_POSTED = IS_POSTED FROM ASSY_PASSED_ITEMS_AT_FV WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE ORDER BY ENT_DT DESC

					IF ISNULL(@PRODCONFPARTNO,'') != ''
					BEGIN
						IF ISNULL(@IS_POSTED,0) = 0
						BEGIN
							SELECT @RETURNVALUE = 'PC_POSTING_PENDING', @RETURNINT = 1
							RETURN
						END
					END
				END
			END

			SELECT @MACHINECODE = ''
			--SELECT @MACHINECODE = DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE)
			IF NOT EXISTS (SELECT 1 FROM ASSY_MACHINEWISE_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE)
			BEGIN
				SELECT @MACHINECODE = MachineCode FROM RoutingConfigLineWise (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
				INSERT INTO ASSY_MACHINEWISE_RUNNINGPART (PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,STATIONCODE,PARTNO,CREATEDDATE)
				SELECT @PROFITCENTERCODE, @LINECODE, @MACHINECODE, @OPERATIONCODE, 1, @PARTNUMBER, GETDATE()
			END
			ELSE
			BEGIN
				UPDATE ASSY_MACHINEWISE_RUNNINGPART SET PARTNO = @PARTNUMBER, UPDATEDDATE = GETDATE()
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
			END

			SELECT @RETURNINT = 1
			SELECT @RETURNVALUE = 'SUCCESS'
			RETURN
		END
		--ADDED BY RASHID ON 20170601 FOR JHAGADIA		
		ELSE IF @CONDITION = 'CHECKAUTOTALLYCHARTENABLE'
		BEGIN 
			IF EXISTS
			(
				SELECT 1 FROM LINEMST WITH(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE 
				AND ISNULL(ISACTIVE,0) = 1 AND ISNULL(AUTOTALLYCHARTENABLE,0) = 1
			)		
			BEGIN
				SET @RETURNVALUE = 'Y'
			END
			ELSE
			BEGIN
				SET @RETURNVALUE = 'N'
			END
			SET @RETURNINT=1
			RETURN
		END
			-- ADDED BY SACHIN 20170519
		-- ISMACHINESCANREQUIRED : CHECK USER WANT TO SCAN MACHINE CODE FIRST THEN BARCODE 
		--						   USING BLUETOOTH SCANNER
		IF @CONDITION ='ISMACHINESCANREQUIRED'
		BEGIN
		--ISMACHINESCANREQUIRED 
		DECLARE @ISMACHINESCANREQUIRED VARCHAR(2)
		SELECT @ISMACHINESCANREQUIRED =DBO.ASSY_FN_GET_PARAMETER_VALUE('ISMACHINESCANREQUIRED',@LINECODE,'',@PROFITCENTERCODE)

				IF(ISNULL(@ISMACHINESCANREQUIRED,'N')='Y')
				BEGIN
				SET @RETURNVALUE = 'Y'
				END
				ELSE
				BEGIN
				SET @RETURNVALUE = 'N'
				END
		
				SET @RETURNINT=1
				RETURN 
		END	
		-- ADDED BY SACHIN 20170519
		-- PROVIDE MACHINE INFORMATION 
		  IF @CONDITION='GET_MACHINE_INFO'
		BEGIN		
				SELECT TOP 1 LINECODE,MACHINECODE,OPERATIONCODE,STATIONCODE   FROM DBO.MACHINEDTL (NOLOCK)  
				WHERE MACHINECODE=@MACHINECODE
				AND LINECODE =@LINECODE AND PROFITCENTERCODE =@PROFITCENTERCODE
				SET @RETURNINT=1
				SET @RETURNVALUE='SUCCESS'
				RETURN
		END
		-- ADDED BY RASHID 20170705
		-- GET SUB STATION MACHINE CODE
		ELSE IF @CONDITION='GETSUBMACHINECODE'
		BEGIN		
				SELECT S.MACHINECODE,R.OPERATIONCODE, S.OPERATIONCODE AS SUBOPERATIONCODE, S.SUBMACHINECODE FROM ROUTINGCONFIGLINEWISEFORSUBSTATION S WITH (NOLOCK) 
				JOIN ROUTINGCONFIGLINEWISE R WITH(NOLOCK)
					ON R.PROFITCENTERCODE =S.PROFITCENTERCODE 
				       AND R.LINECODE =S.LINECODE
					   AND R.MACHINECODE=S.MACHINECODE
					   AND ISNULL(R.TRACEABILITY,0) =1
					   AND ISNULL(R.ISPOKAYOKEFORSUBSTATION,0)=1
					WHERE R.PROFITCENTERCODE =@PROFITCENTERCODE AND R.LINECODE =@LINECODE AND ISNULL(S.POKA_YOKE_ALLOWED,0) = 1
				
				SELECT MACHINECODE,OPERATIONCODE,ISNULL(ISPOKAYOKEFORSUBSTATION,0)ISPOKAYOKEFORSUBSTATION FROM DBO.ROUTINGCONFIGLINEWISE WITH(NOLOCK)
				WHERE PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE =@LINECODE AND ISNULL(ISPOKAYOKEFORSUBSTATION,0)=0
				
				SET @RETURNINT=1
				SET @RETURNVALUE='SUCCESS'
				RETURN
		END
		ELSE IF @CONDITION='ISRFIDBASED_TRACEABILITY'
		BEGIN		
			   IF EXISTS
			   (
				 SELECT 1 FROM DBO.LINEMST WITH(NOLOCK) 
				 WHERE PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE =@LINECODE AND ISNULL(ISRFIDBASEDSCANNING,0) = 1
			   )
				BEGIN
				     	SET @RETURNVALUE='Y'
				END
				ELSE
				BEGIN
				      	SET @RETURNVALUE='N'
				END
				SET @RETURNINT=1			
				RETURN
		END		
				-- ADDED BY SACHIN 20180105
		-- provide scanned data to PLC 
		-- using advance tag write data on PLC tag.				
		IF @CONDITION ='IS_DB_SCANNING_MODE_REQ'
		BEGIN
		--ISMACHINESCANREQUIRED 
		DECLARE @ISDB_SCANNING_REQUIRED VARCHAR(2)
		SELECT @ISDB_SCANNING_REQUIRED =DBO.ASSY_FN_GET_PARAMETER_VALUE('IS_DB_SCANNING_MODE_REQ',@LINECODE,'',@PROFITCENTERCODE)
				IF(ISNULL(@ISDB_SCANNING_REQUIRED,'N')='Y')
				BEGIN
				SET @RETURNVALUE = 'Y'
				END
				ELSE
				BEGIN
				SET @RETURNVALUE = 'N'
				END
		
				SET @RETURNINT=1
				RETURN 
		END	
		 --Added By Rashid On 20180205 For Final Viewing Insertion call automatically
		ELSE IF(@CONDITION = 'IS_AUTO_FV_SCAN_PASS_TRIGGER')
		BEGIN
			DECLARE @ISAUTOFVSCANANDPASSTRIGGER BIT = 0

			SELECT @ISAUTOFVSCANANDPASSTRIGGER = DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE','ISAUTOFVINSERTION',@LINECODE,@PROFITCENTERCODE)

			IF(@ISAUTOFVSCANANDPASSTRIGGER = 1)
			BEGIN
				SET @RETURNVALUE = 'Y'
			END
			ELSE
			BEGIN
				SET @RETURNVALUE = 'N'
			END
		END
		 --Added By Rashid On 20180205 For Final Viewing Insertion call automatically
		ELSE IF(@CONDITION = 'GET_AUTO_FV_SCAN_PASS_TRIGGER_DETAIL')
		BEGIN
			if exists(select top 1 1 from #Temp_RoboKey where RoboKey in('2'))
			Begin

				Select top 1 C.Barcode,RESULT,RESULT_TIMESTAMP,A.QR_CODE into #Temp_ROBO_DATA_WITH_PARAMETER from [dbo].[TD_ROBO_DATA_WITH_PARAMETER] A with(nolock)
				Inner Join ASSY_FV_ROBOT_INSPECTION_SERIAL_HOLD B with(nolock) on A.QR_CODE=B.PRINTED_BARCODE
				Inner Join Assy_Scan_OK_ROBO C with(nolock) on B.rfiD=C.Barcode
				Where A.TS_FLAG='0' and A.RESULT_TIMESTAMP > C.Timestamp order by A.RESULT_TIMESTAMP
				if exists(select Top 1 * from #Temp_ROBO_DATA_WITH_PARAMETER)
				Begin
					select * from #Temp_ROBO_DATA_WITH_PARAMETER

					Update C set C.isprocess=1 from Assy_Scan_OK_ROBO C inner join
					#Temp_ROBO_DATA_WITH_PARAMETER B on C.Barcode=B.Barcode					
					
					insert into Assy_Scan_OK_ROBO_history(ProfitCenterCode,LineCode,MachineCode,OperationCode,WIPBufferSeq,Barcode
					,isScan,Timestamp,isProcess,Hist_Dt)
					select C.ProfitCenterCode,C.LineCode,C.MachineCode,C.OperationCode,C.WIPBufferSeq,C.Barcode
					,C.isScan,C.Timestamp,C.isProcess,getdate()  from Assy_Scan_OK_ROBO C inner join
					#Temp_ROBO_DATA_WITH_PARAMETER B on C.Barcode=B.Barcode
				
				End 
				return

			End
			
			select Top 1 Barcode from Assy_LineAssyStatus_running(nolock) where isnull(status,'')='PS' 
			AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND MachineCode=ISNULL(@P_AutoFVMachineCode,'')
			order by ScanTimestamp

			SET @RETURNVALUE = 'Y'
		END
		 --Start Added By Rashid On 20180305 For Tray scanning Concept
		ELSE IF(@CONDITION = 'IS_TRAY_SCAN_TRIGGER')
		BEGIN
			DECLARE @ISTRAYSCANANDTRIGGER BIT = 0

			SELECT @ISTRAYSCANANDTRIGGER = DBO.ASSY_FN_GET_PARAMETER_VALUE('PACKAGING','PACKAGING_TRAY',@LINECODE,@PROFITCENTERCODE)

			IF(@ISTRAYSCANANDTRIGGER = 1)
			BEGIN
				SET @RETURNVALUE = 'Y'
			END
			ELSE
			BEGIN
				SET @RETURNVALUE = 'N'
			END
		END
		 --End Added By Rashid On 20180305 For Tray scanning Concept

		 --Start Added By Rashid On 20180619 - Get Print Serial Port Controller Name For Barcode Printing From Print Station
		ELSE IF(@CONDITION = 'SERIAL_PORT_BARCODE_PRINT_SIGNAL')
		BEGIN
			Declare @PrintStation_OpCode VARCHAR(30) = ''
			SELECT @PrintStation_OpCode = OperationCode
					FROM RoutingConfigLineWise WITH (NOLOCK) WHERE Traceability = 1 AND OperationSeqNo = 1 AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode

			INSERT INTO TD_ID_GENERATION_SIGNAL(OC_CODE,Barcode,Part_No,FlushCycle,PokaYoke,ent_dt)
			VALUES(@PrintStation_OpCode,NULL,'ESC',0,0,getdate())
			SET @RETURNVALUE = 'Y'
			SET @RETURNINT = 1
		END
		--ENd Added By Rashid On 20180619 - Get Print Serial Port Controller Name For Barcode Printing From Print Station

	--Start Added By Prerna On 20180703 - Get Parameter Details for PreFinalViewing Station

		ELSE IF @CONDITION = 'GET_PREFINALVIEWING_STATIONS_PARAMETER_DATA'
		BEGIN
			SELECT RTRIM(LTRIM(PARAMETER_C2))PARAMETER_C2, RTRIM(LTRIM(PARAMETER_VALUE))PARAMETER_VALUE FROM PARAMETER_MST (NOLOCK) 
			WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'PREFINALVIEWING' AND  WH_CODE = @PROFITCENTERCODE 
			
			SET @RETURNINT = 1
		END

		
		ELSE IF @CONDITION = 'GET_ETHERNETPORT_STATIONS_DATA'
		BEGIN
			SELECT RTRIM(LTRIM(PARAMETER_C2))PARAMETER_C2, RTRIM(LTRIM(PARAMETER_VALUE))PARAMETER_VALUE FROM PARAMETER_MST (NOLOCK) 
			WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'ETHERNETPORTSCANNER' AND  WH_CODE = @PROFITCENTERCODE 
			
			SET @RETURNINT = 1
		END

		--Added By Rashid On 20180619 - Get Print Serial Port Controller Name For Barcode Printing From Print Station
		ELSE IF @CONDITION = 'GET_PRINT_CONTROLLER_PORT_NAME'		
		BEGIN
			SELECT @RETURNVALUE = DBO.ASSY_FN_GET_COMPORT_NAME(@PROFITCENTERCODE, @LINECODE, @OPERATIONCODE, 'PRINTERPORT', 'SERIALPORT')
			SET @RETURNINT = 1			     							
			RETURN
		END

		ELSE IF @CONDITION='FETCH_STATUS_DATECODEMANUAL'
		BEGIN		
			IF EXISTS
			(
				SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND KeyType = @KEYTYPE AND KeyValue = 1
			)
			BEGIN
				    SET @RETURNVALUE = 'Y'
			END
			ELSE
			BEGIN
				    SET @RETURNVALUE = 'N'
			END
			SET @RETURNINT = 1
			RETURN
		END
		ELSE IF @CONDITION = 'ENABLE_DISABLE_DATECODE_MANUAL'
		BEGIN 
			IF(@EnableDisable IN (0,1))
			BEGIN
				UPDATE RoutingConfigDetails SET KeyValue = @EnableDisable WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND KeyType = @KEYTYPE
			END
			
			SELECT  ISNULL(KeyValue,0) KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND KeyType = @KEYTYPE
			RETURN 
		END
		--Added By Rashid For ABS Fail Part-Trolley Association Logic From Central Server On 23rd Nov 2018
		ELSE IF @CONDITION = 'CHECK_FAILPART_TROLLEY_ASSOCIATION'
		BEGIN
			Declare @FTA_Barcode Varchar(50) = '', @TrolleyID Varchar(50) = '', @Trolley_Type NVarchar(6) = ''

			SELECT * INTO #VIEWING_MACHINE FROM VIEWING_MACHINE (NOLOCK) WHERE ProcessType = 'ABS_FTA' AND WH_CODE = @PROFITCENTERCODE
				AND Line_Code = @LINECODE AND ISNULL(STS,0) = 0 AND ISNULL(IsComplete,0) = 0
			
			IF EXISTS (SELECT 1 FROM #VIEWING_MACHINE)
			BEGIN
				SELECT * INTO #Physical_Bin_Master FROM Physical_Bin_Master (NOLOCK) WHERE BIN_ID = @BARCODE AND WH_CODE = @PROFITCENTERCODE
				SELECT Top 1 @FTA_Barcode = Barcode FROM #VIEWING_MACHINE Order By Ent_Stamp Desc

				IF NOT EXISTS (SELECT 1 FROM #Physical_Bin_Master)
				BEGIN
					SET @RETURNVALUE = 'Fail Part ' + @FTA_Barcode +' not associated with Rejection Trolley.'
					SELECT @RETURNINT = 1
					RETURN
				END

				SELECT @Trolley_Type = dbo.ASSY_FN_GET_PARAMETER_VALUE('ABS-ASSEMBLY', 'REJECTION_TROLLEY', 'BINTYPE', @PROFITCENTERCODE)

				IF ISNULL(@Trolley_Type,'') = ''
				BEGIN
					SET @RETURNVALUE = 'Trolley Type is not available in PARAMETER_MST, Rej. Trolley scanning Req. for Barcode - ' + @FTA_Barcode
					SELECT @RETURNINT = 1
					RETURN
				END

				IF NOT EXISTS (SELECT 1 FROM #Physical_Bin_Master WHERE BIN_TYPE = @Trolley_Type) 
				BEGIN 
					SET @RETURNVALUE = 'Trolley Type (PARAMETER_MST) is not match with Physical_Bin_Master Bin Type, Rej. Trolley scanning Req. for Barcode - ' + @FTA_Barcode
					SELECT @RETURNINT = 1
					RETURN
				END

				IF NOT EXISTS (SELECT 1 FROM #Physical_Bin_Master WHERE ISNULL(STS_CD,0) = 0) 
				BEGIN 
					SET @RETURNVALUE = 'Trolley is not active, Rej. Trolley scanning Req. for Barcode - ' + @FTA_Barcode
					SELECT @RETURNINT = 1
					RETURN
				END

				IF EXISTS (SELECT 1 FROM #Physical_Bin_Master WHERE ISNULL(capacity, 0) = 0)
				BEGIN 
					SET @RETURNVALUE = 'Trolley capacity is Zero (0). So can not Process, Rej. Trolley scanning Req. for Barcode - ' + @FTA_Barcode
					SELECT @RETURNINT = 1
					RETURN
				END
				
				---------------------Part Number Validation is removed - approved By Vinod Sir 23rd Nov 2018-----------------------
				---------------------Trolley Capacity full is removed - approved By Vinod Sir 23rd Nov 2018------------------------
				
				Update VIEWING_MACHINE Set STS = 1, TrolleyID = @BARCODE WHERE ProcessType = 'ABS_FTA' AND WH_CODE = @PROFITCENTERCODE AND Line_Code = @LINECODE
					AND ISNULL(STS,0) = 0 AND Barcode = @FTA_Barcode

				SET @RETURNVALUE = 'Success|Rejected Trolley associated with Barcode - ' + @FTA_Barcode
				--SET @RETURNVALUE = 'Previous Fail Part, Trolley/Tray association is pending. Rejected Trolley scanning required for Barcode - ' + @FTA_Barcode
				SELECT @RETURNINT = 1
				RETURN
			END
		END
		--Added By Rashid For ABS Fail Part-Trolley Association Logic From Central Server On 23rd Nov 2018
		ELSE IF @CONDITION = 'IS_FAIL_PART_TROLLEY_ASSTRIGGER'
		BEGIN
			SELECT TOP 1 @RETURNVALUE = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE 
										AND LineCode = @LINECODE AND KeyType = 'ABSFVFailTrayReq' AND STS_CD = 0
			SELECT @RETURNINT = 1
			RETURN
		END
		--Added By RS On 20180828 For Waki Non-Mahindra Logic
		ELSE IF @CONDITION = 'FETCH_WAKI_LOGIC'
		BEGIN
			IF EXISTS
			(
				SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND KeyType = 'WakiLogic' AND KeyValue = 1
			)
			BEGIN
				SET @RETURNVALUE = 'Y'
			END
			ELSE
			BEGIN
				SET @RETURNVALUE = 'N'
			END
			SET @RETURNINT = 1
			RETURN
		END
		--Added By RS On 20180828 For Waki Non-Mahindra Logic
		ELSE IF @CONDITION = 'SaveBarcodeMappingData'
		BEGIN
			SET @ExecQuery = ''
			Declare @FilterQuery VARCHAR(50) = ''
			IF @PRNGroupCode IN ('GC_NISSAN_LINE_6_7','GC_DUSTER_LINE_6_7')
			BEGIN
				SET @ExecQuery = '
					DELETE FROM ' + @LinkServerName + '.dbo.Assy_FinalViewing_RFID_Barcode_Mapping WHERE ProfitCenterCode = ''' + @ProfitCenterCode + ''' AND LineCode = ''' + @LineCode + ''' AND RFID = ''' + @Barcode + ''' '
				PRINT @ExecQuery
				EXEC (@ExecQuery)
			
				SET @ExecQuery = ''
				SET @ExecQuery = '
					INSERT INTO ' + @LinkServerName + '.dbo.Assy_FinalViewing_RFID_Barcode_Mapping (ProfitCenterCode,LineCode,MachineCode,OperationCode,RFID,Barcode,Status,PartNo,Datecode,PrintedTimestamp)
					SELECT ProfitCenterCode,LineCode,MachineCode,OperationCode,RFID,Barcode,Status,PartNo,Datecode,PrintedTimestamp FROM Assy_FinalViewing_RFID_Barcode_Mapping WHERE ProfitCenterCode = ''' + @ProfitCenterCode + ''' AND LineCode = ''' + @LineCode + ''' AND RFID = ''' + @Barcode + ''' '
			END
			ELSE
			BEGIN
				SET @ExecQuery = '
					DELETE FROM ' + @LinkServerName + '.dbo.Assy_FinalViewing_RFID_Barcode_Mapping WHERE ProfitCenterCode = ''' + @ProfitCenterCode + ''' AND LineCode = ''' + @LineCode + ''' AND Barcode = ''' + @Barcode + ''' '
				PRINT @ExecQuery
				EXEC (@ExecQuery)
			
				SET @ExecQuery = ''
				SET @ExecQuery = '
					INSERT INTO ' + @LinkServerName + '.dbo.Assy_FinalViewing_RFID_Barcode_Mapping (ProfitCenterCode,LineCode,MachineCode,OperationCode,RFID,Barcode,Status,PartNo,Datecode,PrintedTimestamp)
					SELECT ProfitCenterCode,LineCode,MachineCode,OperationCode,RFID,Barcode,Status,PartNo,Datecode,PrintedTimestamp FROM Assy_FinalViewing_RFID_Barcode_Mapping WHERE ProfitCenterCode = ''' + @ProfitCenterCode + ''' AND LineCode = ''' + @LineCode + ''' AND Barcode = ''' + @Barcode + ''' '
			END
			
			PRINT @ExecQuery
			EXEC (@ExecQuery)

			SET @RETURNVALUE = 'SUCCESS'
			SET @RETURNINT = 1
		END
		ELSE IF @CONDITION = 'Is_FV_Rework_Barcode_ForPC' -- Added By Prerna -- Merged By Sachin 24Feb2020
		BEGIN

			if exists(select top 1 1 from [dbo].[Assy_Status_Rework_log] WITH (NOLOCK)
			where barcode=@barcode and Machinecode='MCFV' )
			begin 
			  set @RETURNVALUE ='REWORK_BARCODE'
			end
			else
			begin
			  set @RETURNVALUE ='NORMAL_BARCODE'
			end
			SET @RETURNINT = 1

		END  
		-- Ended By Prerna -- Merged By Sachin 24Feb2020
		-- Added By Sachin on 2019015 Client Visit Assembly Line Implimentation Cell 02 BIJ
		-- Get Data From Machine DB and Save In TS Database.
		ELSE IF @CONDITION='GetandSaveMachineParametersInDB'
		BEGIN
				
				SELECT TOP 1 @MachineLinkServerName = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE 
				AND LineCode = @LINECODE AND KeyType = 'MachineDBLinkServerName' AND STS_CD = 0
				
				SELECT TOP 1 @MachineLinkServerDB = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE 
				AND LineCode = @LINECODE AND KeyType = 'MachineDBLinkServerDB' AND STS_CD = 0

				SELECT TOP 1 @MACHINECODE = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE 
				AND LineCode = @LINECODE AND KeyType = 'SaveDataForMachineCode' AND STS_CD = 0

				SELECT TOP 1 @OPERATIONCODE = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE 
				AND LineCode = @LINECODE AND KeyType = 'SaveDataForOperationCode' AND STS_CD = 0				
				
				if(ISNULL(@MachineLinkServerName,'') = '' )
				begin
					SELECT 'Machine Link Server Name Configuration Not Found !! [RoutingConfigDetails Key: MachineDBLinkServerName] ' as MSG ,
						   100 as STS
					return
				end

				if(ISNULL(@MachineLinkServerDB,'') = '' )
				begin
					SELECT 'Machine Link Server Database Configuration Not Found !! [RoutingConfigDetails Key: MachineDBLinkServerDB]' as MSG ,
					 100 as STS
					return
				end

				if(ISNULL(@MACHINECODE,'') = '' )
				begin
					SELECT 'Machine Code Configuration Not Found !! [RoutingConfigDetails Key: SaveDataForMachineCode]' as MSG,
					100 as STS
					return
				end

				if(ISNULL(@OPERATIONCODE,'') = '' )
				begin
					SELECT 'Operation Code Configuration Not Found !! [RoutingConfigDetails Key: SaveDataForOperationCode]' as MSG,
				    100 as STS
					return
				end
				
				SET @MachineLinkServer = @MachineLinkServerName+'.'+@MachineLinkServerDB
							

				SET @EXECQUERY = ''
				SET @EXECQUERY = 'SELECT TOP 1 
					 isnull(convert(varchar,R_Oiling_Part_No),''NULL'') as R_Oiling_Part_No
					,isnull(convert(varchar,R_Oiling_Status),''NULL'') as R_Oiling_Status
					,isnull(convert(varchar,R_Seal_Check_Status),''NULL'') as R_Seal_Check_Status
					,isnull(convert(varchar,R_Bleed_Continuity_Status),''NULL'') as R_Bleed_Continuity_Status
					,isnull(convert(varchar,R_Bleed_Torque_Status),''NULL'') as R_Bleed_Torque_Status
					,isnull(convert(varchar,H_Model_Name) ,''NULL'') as H_Model_Name
					,isnull(convert(varchar,H_Loading_Status) ,''NULL'') as H_Loading_Status
					,isnull(convert(varchar,H_Piston_Seal_Cross_Load) ,''NULL'') as H_Piston_Seal_Cross_Load
					,isnull(convert(varchar,H_Piston_Assembly_Depth) ,''NULL'') as H_Piston_Assembly_Depth
					,isnull(convert(varchar,H_Piston_Assembly_Status) ,''NULL'') as H_Piston_Assembly_Status
					,isnull(convert(varchar,H_Orientation_Status) ,''NULL'') as H_Orientation_Status
					,isnull(convert(varchar,H_PFT_Drop_Val) ,''NULL'') as H_PFT_Drop_Val
					,isnull(convert(varchar,H_PFT_Status) ,''NULL'') as H_PFT_Status
					,isnull(convert(varchar,H_LP_Drop_val) ,''NULL'') as H_LP_Drop_val
					,isnull(convert(varchar,H_LP_Status) ,''NULL'') as H_LP_Status
					,isnull(convert(varchar,H_HP_Drop_Val) ,''NULL'') as H_HP_Drop_Val
					,isnull(convert(varchar,H_HP_Status) ,''NULL'') as H_HP_Status
					,isnull(convert(varchar,H_UL_Status) ,''NULL'') as H_UL_Status
					,isnull(convert(varchar,C_Model_Name) ,''NULL'') as C_Model_Name
					,isnull(convert(varchar,C_Loading_Status) ,''NULL'') as C_Loading_Status
					,isnull(convert(varchar,C_Probing_Status) ,''NULL'') as C_Probing_Status
					,isnull(convert(varchar,C_Torque_LH_Status) ,''NULL'') as C_Torque_LH_Status
					,isnull(convert(varchar,C_Torque_Val_LH) ,''NULL'') as C_Torque_Val_LH
					,isnull(convert(varchar,C_Angle_Val_LH) ,''NULL'') as C_Angle_Val_LH
					,isnull(convert(varchar,C_Torque_RH_Status) ,''NULL'') as C_Torque_RH_Status
					,isnull(convert(varchar,C_Torque_Val_RH) ,''NULL'') as C_Torque_Val_RH
					,isnull(convert(varchar,C_Angle_Val_RH) ,''NULL'') as C_Angle_Val_RH
					,isnull(convert(varchar,C_PRF_Status) ,''NULL'') as C_PRF_Status
					,isnull(convert(varchar,C_ASR_Test_val) ,''NULL'') as C_ASR_Test_val
					,isnull(convert(varchar,C_ASR_Status) ,''NULL'') as C_ASR_Status
					,isnull(convert(varchar,C_Eng_Machine_Datecode) ,''NULL'') as C_Eng_Machine_Datecode
					,isnull(convert(varchar,C_DC_Serial_No) ,''NULL'') as C_DC_Serial_No
					,isnull(convert(varchar,C_DC_Status) ,''NULL'') as C_DC_Status
					,isnull(convert(varchar,C_UL_Status) ,''NULL'') as C_UL_Status				
				 FROM ' 
				+ @MachineLinkServer + '.DBO.MASTER WITH 
				(NOLOCK) WHERE R_Oiling_Part_No = ''' + @BARCODE + ''''
				BEGIN TRY
				--print @EXECQUERY
				
				insert into @TEMP_Master(R_Oiling_Part_No,R_Oiling_Status,R_Seal_Check_Status,R_Bleed_Continuity_Status,R_Bleed_Torque_Status,H_Model_Name,
				H_Loading_Status,H_Piston_Seal_Cross_Load,H_Piston_Assembly_Depth,H_Piston_Assembly_Status,H_Orientation_Status,H_PFT_Drop_Val,
				H_PFT_Status,H_LP_Drop_val,H_LP_Status,H_HP_Drop_Val,H_HP_Status,H_UL_Status,C_Model_Name,C_Loading_Status,C_Probing_Status,C_Torque_LH_Status,
				C_Torque_Val_LH,C_Angle_Val_LH,C_Torque_RH_Status,C_Torque_Val_RH,C_Angle_Val_RH,C_PRF_Status,C_ASR_Test_val,C_ASR_Status,C_Eng_Machine_Datecode,C_DC_Serial_No,
				C_DC_Status,C_UL_Status)
				EXEC(@EXECQUERY)				

				
				if not exists (select top 1 1 from @TEMP_Master )
				begin
					Select 'Parameter Data Not Found For Barcode ( ' + @BARCODE + ' )' as MSG,
					100 as STS
					return
				end


				SET @XmldataLK  = (SELECT * FROM  @TEMP_Master FOR XML PATH('') )   
				
				--Dynamic unpivoting 
				insert into @TagData(TagName,TagValue)
				SELECT TagName,TagValue FROM  ( 
				SELECT 
				ROW_NUMBER()OVER(PARTITION BY   TagName ORDER BY  TagValue) rn,* FROM ( 
				SELECT  i.value('local-name(.)','VARCHAR(100)')  TagName,
				i.value('.','VARCHAR(100)') TagValue 
				FROM @xmldataLK.nodes('//*') x(i) ) tmp ) tmp1

				update @TagData set TagValue=0 where TagName like '%_Status%' and TagValue='NULL'
				update @TagData set TagValue='ND' where TagName not like '%_Status%' and TagValue='NULL'
				update @TagData set TagValue='NG' where TagName like '%_Status%' and TagValue<>'1'
				update @TagData set TagValue='OK' where TagName like '%_Status%' and TagValue='1'
				update @TagData set TagName='DATE_CODE_COUPLING' where TagName = 'C_Eng_Machine_Datecode' 
				update @TagData set TagName='CALIPER_SERIAL_NO' where TagName like 'C_DC_Serial_No' 
				update @TagData set TagValue='0' where TagName like 'CALIPER_SERIAL_NO' and TagValue='ND'

				
				if exists (select top 1 1 from @TagData where TagValue='NG')
				begin
					  SET @P_Result='FL'
				end

				INSERT INTO @ParameterData(
				ProfitCenterCode,LineCode,MachineCode,
				OperationCode,StationCode,Barcode,TagName,Value,Result,Datecode,UserID)
				select @PROFITCENTERCODE,@LINECODE,@MACHINECODE,
				@OPERATIONCODE,'1',@Barcode,TagName,TagValue,@P_Result,'',@USERID 
				from @TagData
								
				exec Assy_Proc_DBIntegration @Operation = 'INSERT_PLC_PARAMS',@LineCode = @LINECODE,
				@tblParameters = @ParameterData
				
				SELECT 'SAVED' as MSG , 1 as STS 

				END TRY
				BEGIN CATCH

				SET @ReturnValue =   CAST(ISNULL(ERROR_NUMBER(),0) as varchar(5)) + '|' + 
				CAST(ISNULL(ERROR_SEVERITY(),0) as varchar(5)) + '|' + 
				CAST(ISNULL(ERROR_STATE(),0) as varchar(5)) + '|' + 
				CAST(ISNULL(ERROR_PROCEDURE(),'Assy_Proc_FinalViewing') as varchar(200)) + '|' + 
				CAST(ISNULL(ERROR_LINE(),0) as varchar(5)) + '|' + 
				CAST(ISNULL(ERROR_MESSAGE(),'') as varchar(1500))
				
				SET @RETURNINT = 100
				END CATCH

		END
		ELSE IF @CONDITION='ShowMachineParametersInMESServer'
		BEGIN
				
				SELECT TOP 1 @MachineLinkServerName = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE 
				AND LineCode = @LINECODE AND KeyType = 'MachineDBLinkServerName' AND STS_CD = 0
				
				SELECT TOP 1 @MachineLinkServerDB = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE 
				AND LineCode = @LINECODE AND KeyType = 'MachineDBLinkServerDB' AND STS_CD = 0

				SELECT TOP 1 @MACHINECODE = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE 
				AND LineCode = @LINECODE AND KeyType = 'SaveDataForMachineCode' AND STS_CD = 0

				SELECT TOP 1 @OPERATIONCODE = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE 
				AND LineCode = @LINECODE AND KeyType = 'SaveDataForOperationCode' AND STS_CD = 0				
				
				if(ISNULL(@MachineLinkServerName,'') = '' )
				begin
					SELECT 'Machine Link Server Name Configuration Not Found !! [RoutingConfigDetails Key: MachineDBLinkServerName] ' as MSG ,
						   100 as STS, @MACHINECODE as 'MACHINECODE', @OPERATIONCODE as 'OPERATIONCODE'
					return
				end

				if(ISNULL(@MachineLinkServerDB,'') = '' )
				begin
					SELECT 'Machine Link Server Database Configuration Not Found !! [RoutingConfigDetails Key: MachineDBLinkServerDB]' as MSG ,
					 100 as STS, @MACHINECODE as 'MACHINECODE', @OPERATIONCODE as 'OPERATIONCODE'
					return
				end

				if(ISNULL(@MACHINECODE,'') = '' )
				begin
					SELECT 'Machine Code Configuration Not Found !! [RoutingConfigDetails Key: SaveDataForMachineCode]' as MSG,
					100 as STS, @MACHINECODE as 'MACHINECODE', @OPERATIONCODE as 'OPERATIONCODE'
					return
				end

				if(ISNULL(@OPERATIONCODE,'') = '' )
				begin
					SELECT 'Operation Code Configuration Not Found !! [RoutingConfigDetails Key: SaveDataForOperationCode]' as MSG,
				    100 as STS, @MACHINECODE as 'MACHINECODE', @OPERATIONCODE as 'OPERATIONCODE'
					return
				end
				
				DECLARE @RESULTTIMESTAMP_PS DATETIME = NULL
				DECLARE @RESULTTIMESTAMP_FL DATETIME = NULL

				SELECT @RESULTTIMESTAMP_PS = RESULTTIMESTAMP FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) 
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE 
				AND BARCODE = @BARCODE AND  ISNULL(STATUS, '') = 'PS'
						
				IF @RESULTTIMESTAMP_PS IS NULL
				BEGIN
					SELECT @RESULTTIMESTAMP_PS = RESULTTIMESTAMP FROM ASSY_LINEASSYSTATUS (NOLOCK) 
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE 
					AND BARCODE = @BARCODE AND  ISNULL(STATUS, '') = 'PS'				
				END	
				
				SELECT @RESULTTIMESTAMP_FL = RESULTTIMESTAMP FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) 
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE 
				AND BARCODE = @BARCODE AND  ISNULL(STATUS, '') = 'FL'
						
				IF @RESULTTIMESTAMP_FL IS NULL
				BEGIN
					SELECT @RESULTTIMESTAMP_FL = RESULTTIMESTAMP FROM ASSY_LINEASSYSTATUS (NOLOCK) 
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE 
					AND BARCODE = @BARCODE AND  ISNULL(STATUS, '') = 'FL'				
				END										
				
				IF (@RESULTTIMESTAMP_FL IS NOT NULL)
				begin
					SELECT 'Part has already failed,testing date time= ' + convert(varchar,@RESULTTIMESTAMP_FL,25)   as MSG,
				    50 as STS, @MACHINECODE as 'MACHINECODE', @OPERATIONCODE as 'OPERATIONCODE'
					return
				end	
					
				IF (@RESULTTIMESTAMP_PS IS NOT NULL)
				begin
					SELECT 'Part has already passed,testing date time= ' + convert(varchar,@RESULTTIMESTAMP_PS,25)   as MSG,
				    50 as STS, @MACHINECODE as 'MACHINECODE', @OPERATIONCODE as 'OPERATIONCODE'
					return
				end	
				
				begin try
				declare @s sysname=REPLACE(REPLACE(@MachineLinkServerName,'[',''),']','')
				exec sys.sp_testlinkedserver @s
				end try
				begin catch
				SELECT 'Kindly Check, Not Able To Connect MES SQL Server !!! '+@MachineLinkServerName as MSG ,
						   100 as STS, @MACHINECODE as 'MACHINECODE', @OPERATIONCODE as 'OPERATIONCODE'
				return
				end catch
			BEGIN TRY

			if(@LINECODE='J02')
			begin

				SET @MachineLinkServer = @MachineLinkServerName+'.'+@MachineLinkServerDB
			    
				SET @EXECQUERY = ''
				SET @EXECQUERY = 'SELECT TOP 1 
					 isnull(convert(varchar,R_Oiling_Part_No),''NULL'') as R_Oiling_Part_No
					,isnull(convert(varchar,R_Oiling_Status),''NULL'') as R_Oiling_Status
					,isnull(convert(varchar,R_Seal_Check_Status),''NULL'') as R_Seal_Check_Status
					,isnull(convert(varchar,R_Bleed_Continuity_Status),''NULL'') as R_Bleed_Continuity_Status
					,isnull(convert(varchar,R_Bleed_Torque_Status),''NULL'') as R_Bleed_Torque_Status
					,isnull(convert(varchar,H_Model_Name) ,''NULL'') as H_Model_Name
					,isnull(convert(varchar,H_Loading_Status) ,''NULL'') as H_Loading_Status
					,isnull(convert(varchar,H_Piston_Seal_Cross_Load) ,''NULL'') as H_Piston_Seal_Cross_Load
					,isnull(convert(varchar,H_Piston_Assembly_Depth) ,''NULL'') as H_Piston_Assembly_Depth
					,isnull(convert(varchar,H_Piston_Assembly_Status) ,''NULL'') as H_Piston_Assembly_Status
					,isnull(convert(varchar,H_Orientation_Status) ,''NULL'') as H_Orientation_Status
					,isnull(convert(varchar,H_PFT_Drop_Val) ,''NULL'') as H_PFT_Drop_Val
					,isnull(convert(varchar,H_PFT_Status) ,''NULL'') as H_PFT_Status
					,isnull(convert(varchar,H_LP_Drop_val) ,''NULL'') as H_LP_Drop_val
					,isnull(convert(varchar,H_LP_Status) ,''NULL'') as H_LP_Status
					,isnull(convert(varchar,H_HP_Drop_Val) ,''NULL'') as H_HP_Drop_Val
					,isnull(convert(varchar,H_HP_Status) ,''NULL'') as H_HP_Status
					,isnull(convert(varchar,H_UL_Status) ,''NULL'') as H_UL_Status
					,isnull(convert(varchar,C_Model_Name) ,''NULL'') as C_Model_Name
					,isnull(convert(varchar,C_Loading_Status) ,''NULL'') as C_Loading_Status
					,isnull(convert(varchar,C_Probing_Status) ,''NULL'') as C_Probing_Status
					,isnull(convert(varchar,C_Torque_LH_Status) ,''NULL'') as C_Torque_LH_Status
					,isnull(convert(varchar,C_Torque_Val_LH) ,''NULL'') as C_Torque_Val_LH
					,isnull(convert(varchar,C_Angle_Val_LH) ,''NULL'') as C_Angle_Val_LH
					,isnull(convert(varchar,C_Torque_RH_Status) ,''NULL'') as C_Torque_RH_Status
					,isnull(convert(varchar,C_Torque_Val_RH) ,''NULL'') as C_Torque_Val_RH
					,isnull(convert(varchar,C_Angle_Val_RH) ,''NULL'') as C_Angle_Val_RH
					,isnull(convert(varchar,C_PRF_Status) ,''NULL'') as C_PRF_Status
					,isnull(convert(varchar,C_ASR_Test_val) ,''NULL'') as C_ASR_Test_val
					,isnull(convert(varchar,C_ASR_Status) ,''NULL'') as C_ASR_Status
					,isnull(convert(varchar,C_Eng_Machine_Datecode) ,''NULL'') as C_Eng_Machine_Datecode
					,isnull(convert(varchar,C_DC_Serial_No) ,''NULL'') as C_DC_Serial_No
					,isnull(convert(varchar,C_DC_Status) ,''NULL'') as C_DC_Status
					,isnull(convert(varchar,C_UL_Status) ,''NULL'') as C_UL_Status				
				 FROM ' 
				+ @MachineLinkServer + '.DBO.MASTER WITH 
				(NOLOCK) WHERE ISNULL(TS_Read,0)=0 and R_Oiling_Part_No = ''' + @BARCODE + ''''
				
				--print @EXECQUERY
				
				insert into @TEMP_Master(R_Oiling_Part_No,R_Oiling_Status,R_Seal_Check_Status,R_Bleed_Continuity_Status,R_Bleed_Torque_Status,H_Model_Name,
				H_Loading_Status,H_Piston_Seal_Cross_Load,H_Piston_Assembly_Depth,H_Piston_Assembly_Status,H_Orientation_Status,H_PFT_Drop_Val,
				H_PFT_Status,H_LP_Drop_val,H_LP_Status,H_HP_Drop_Val,H_HP_Status,H_UL_Status,C_Model_Name,C_Loading_Status,C_Probing_Status,C_Torque_LH_Status,
				C_Torque_Val_LH,C_Angle_Val_LH,C_Torque_RH_Status,C_Torque_Val_RH,C_Angle_Val_RH,C_PRF_Status,C_ASR_Test_val,C_ASR_Status,C_Eng_Machine_Datecode,C_DC_Serial_No,
				C_DC_Status,C_UL_Status)
				EXEC(@EXECQUERY)				

				
				if not exists (select top 1 1 from @TEMP_Master )
				begin
					Select 'Parameter Data Not Found In MES Server For Barcode ( ' + @BARCODE + ' )' as MSG,
					100 as STS, @MACHINECODE as 'MACHINECODE', @OPERATIONCODE as 'OPERATIONCODE'
					return
				end


				SET @XmldataLK  = (SELECT * FROM  @TEMP_Master FOR XML PATH('') )   

				--Dynamic unpivoting 
				insert into @TagData(TagName,TagValue)
				SELECT TagName,TagValue FROM  ( 
				SELECT 
				ROW_NUMBER()OVER(PARTITION BY   TagName ORDER BY  TagValue) rn,* FROM ( 
				SELECT  i.value('local-name(.)','VARCHAR(100)')  TagName,
				i.value('.','VARCHAR(100)') TagValue 
				FROM @xmldataLK.nodes('//*') x(i) ) tmp ) tmp1

				update @TagData set TagValue=0 where TagName like '%_Status%' and TagValue='NULL'
				update @TagData set TagValue='ND' where TagName not like '%_Status%' and TagValue='NULL'
				update @TagData set TagValue='NG' where TagName like '%_Status%' and TagValue<>'1'
				update @TagData set TagValue='OK' where TagName like '%_Status%' and TagValue='1'
				update @TagData set TagName='DATE_CODE_COUPLING' where TagName = 'C_Eng_Machine_Datecode' 
				update @TagData set TagName='CALIPER_SERIAL_NO' where TagName like 'C_DC_Serial_No' 
				update @TagData set TagValue='0' where TagName like 'CALIPER_SERIAL_NO' and TagValue='ND'

				INSERT INTO @ParameterData(
				ProfitCenterCode,LineCode,MachineCode,
				OperationCode,StationCode,Barcode,TagName,Value,Result,Datecode,UserID)
				select @PROFITCENTERCODE,@LINECODE,@MACHINECODE,
				@OPERATIONCODE,'1',@Barcode,TagName,TagValue,@P_Result,'',@USERID 
				from @TagData				

				end
			else
			begin
				SET @MachineLinkServer =  @MachineLinkServerName+'...'+@MachineLinkServerDB
			    print @MachineLinkServer
				SET @MachineLinkServerGetId = @MachineLinkServer
				print '-------1--------'
				if not exists(select top 1 1 from Assy_LineAssyStatus_Running(nolock)
				where MachineCode='MCIG' and Barcode=ISNULL(@BARCODE,'') and ProfitCenterCode=@PROFITCENTERCODE
				and LineCode= @LINECODE
				)
				begin
					SELECT TOP 1 @MachineDBTableName = KeyValue FROM RoutingConfigDetails (NOLOCK) 
					WHERE ProfitCenterCode = @PROFITCENTERCODE 
					AND LineCode = @LINECODE AND KeyType = 'GetGenIdFromTable' AND STS_CD = 0				

					if(ISNULL(@MachineDBTableName,'') = '' )
					begin
						SELECT 'Link Server ID Gen Table Name Configuration Not Found !! [RoutingConfigDetails Key: GetGenIdFromTable] ' as MSG ,
							   100 as STS, @MACHINECODE as 'MACHINECODE', @OPERATIONCODE as 'OPERATIONCODE'
						return
					end
					
					set @MachineLinkServerGetId = REPLACE(@MachineLinkServer,'TABLE_NAME',@MachineDBTableName)
					print '-------2--------'
					set @dynamic_query = '

					select ' 
					+ '''' + @PROFITCENTERCODE + '''' + ',' 
					+ '''' + @LINECODE + '''' + ',' 
					+ '''' + 'MCIG' + '''' + ',' 
					+ '''' + 'OCIG' + '''' + ',' 
					+ '''' + '1' + '''' + ','
					+ '''' + @BARCODE + '''' + ','
					+ '''' + 'PS' + '''' + ','
					+ '''' + '0' + '''' + ','
					+ 'DCODE' + ','
					+ 'modelNo' + ','
					+ '''' + '1' + '''' + ','
					+  'DTS' +','
					+  'DTS' + ','
					+ '''' + @USERID + '''' + ','
					+ '''' + @Live_Datecode + ''''
					 +' from ' + @MachineLinkServerGetId + 
					' where ' + 'rfid' + ' = ' 
					+'''' + @BARCODE + ''''
					+ '
					
				
					'
					print '-------3--------'
					print @dynamic_query
					insert into Assy_LineAssyStatus_Running(
					ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,
					Barcode,Status,FailCount,Datecode,PartNo,Active,ResultTimestamp,
					ScanTimestamp,UserID,Live_Datecode)
					exec(@dynamic_query)
					
					if not exists(select top 1 1 from Assy_LineAssyStatus_Running(nolock)
					where MachineCode='MCIG' and Barcode=ISNULL(@BARCODE,'') and ProfitCenterCode=@PROFITCENTERCODE
					and LineCode= @LINECODE
					)
					begin
							SELECT 'Id Gen. Fail From MES (' + ISNULL(@BARCODE,'') + ') Chk Tbl:'+
							ISNULL(@MachineLinkServerGetId,'')
							 as MSG ,
							100 as STS, @MACHINECODE as 'MACHINECODE', @OPERATIONCODE as 'OPERATIONCODE'
							return
					end
					else
					begin
						--UPDATE PRINTED BARCODE COUNTER
						EXEC Assy_Proc_Barcode_Printed_Counter @CONDITION='UPDATE',@LINECODE =@LINECODE ,@PROFITCENTERCODE =@PROFITCENTERCODE
						UPDATE ASSY_RUNNINGPART SET PRINTEDQTY=ISNULL(PRINTEDQTY,0)+1 WHERE LINECODE=@LINECODE AND CURRENTPLANNEDQTY>ISNULL(PRINTEDQTY,0)
					end
				end
				print '-------4--------'
				if not exists(select top 1 1 from Assy_LineAssyStatus_Running(nolock)
				where MachineCode=@MACHINECODE and OperationCode=@OPERATIONCODE and 
				Barcode=ISNULL(@BARCODE,'') and ProfitCenterCode=@PROFITCENTERCODE
				and LineCode= @LINECODE)
				
				begin
				print '-------5--------'
				insert into Assy_LineAssyStatus_Running(ProfitCenterCode,LineCode, OperationCode,MachineCode,
				StationCode,Barcode,Datecode,PartNo,Active, ScanTimestamp,UserID,Live_Datecode )
				select ProfitCenterCode,LineCode,@OPERATIONCODE as OperationCode,@MACHINECODE as MachineCode,
				StationCode,Barcode,Datecode,PartNo,Active,getdate() as ScanTimestamp,UserID,@Live_Datecode 
				from Assy_LineAssyStatus_Running(nolock)
				where MachineCode='MCIG' and OperationCode='OCIG' and 
				Barcode=ISNULL(@BARCODE,'') and ProfitCenterCode=@PROFITCENTERCODE
				and LineCode= @LINECODE


				end
				
				print '-------6--------'
				select @listCoulumnMain=COALESCE(@listCoulumnMain+ ',', '') 
				+ 'isnull(convert(varchar,' + '[' + CONVERT(VARCHAR,main.TagName) + ']'  + '),''NULL'')' + ' as ['
				+ 'C_' + CONVERT(VARCHAR,main.TagName) + ']'
				from MachineTagMapping(nolock)  main
				where MachineCode=@MACHINECODE and OperationCode=@OPERATIONCODE
				and PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE 

				if(ISNULL(@listCoulumnMain,'') = '' )
				begin
					SELECT 'Machine Column Name Configuration Not Found !! [MachineTagMapping] ' as MSG ,
						   100 as STS, @MACHINECODE as 'MACHINECODE', @OPERATIONCODE as 'OPERATIONCODE'
					return
				end

				set @MachineDBTableName=''
				SELECT TOP 1 @MachineDBTableName = KeyValue FROM RoutingConfigDetails (NOLOCK) 
				WHERE ProfitCenterCode = @PROFITCENTERCODE 
				AND LineCode = @LINECODE AND KeyType = 'MachineDBResultTableName' AND STS_CD = 0				

				if(ISNULL(@MachineDBTableName,'') = '' )
				begin
					SELECT 'Link Server Result Table Name Configuration Not Found !! [RoutingConfigDetails Key: MachineDBResultTableName] ' as MSG ,
						   100 as STS, @MACHINECODE as 'MACHINECODE', @OPERATIONCODE as 'OPERATIONCODE'
					return
				end

				SELECT TOP 1 @MachineDBWhereClauseColumn = KeyValue FROM RoutingConfigDetails (NOLOCK) 
				WHERE ProfitCenterCode = @PROFITCENTERCODE 
				AND LineCode = @LINECODE AND KeyType = 'MachineDBWhereClauseColumn' AND STS_CD = 0	

				if(ISNULL(@MachineDBWhereClauseColumn,'') = '' )
				begin
					SELECT 'Result Table Column Name Configuration Not Found !! [RoutingConfigDetails Key: MachineDBLinkServerName] ' as MSG ,
						   100 as STS, @MACHINECODE as 'MACHINECODE', @OPERATIONCODE as 'OPERATIONCODE'
					return
				end
				set @MachineLinkServer = REPLACE(@MachineLinkServer,'TABLE_NAME',@MachineDBTableName)
				print @MachineDBTableName
				print @MachineLinkServer
				print '-------7--------'
				-- Get Data From MES Table
				set @dynamic_query = '

				if object_id(''tempdb..#TEMP_MES_DATA'') is not null
				drop table #TEMP_MES_DATA

				select ' + @listCoulumnMain  +' into #TEMP_MES_DATA from ' + @MachineLinkServer + 
				' where ' + @MachineDBWhereClauseColumn + ' = ' 
				+'''' + @BARCODE + ''''
				+ '
				DECLARE @Xmldata XML 
				SET @Xmldata = (SELECT * FROM  #TEMP_MES_DATA FOR XML PATH(''''))

				SELECT TagName,TagValue FROM  ( 
				SELECT 
				ROW_NUMBER()OVER(PARTITION BY   TagName ORDER BY  TagValue) rn,* FROM ( 
				SELECT  i.value(''local-name(.)'',''VARCHAR(100)'')  TagName,
				i.value(''.'',''VARCHAR(100)'') TagValue 
				FROM @Xmldata.nodes(''//*'') x(i) ) tmp ) tmp1
				
				if object_id(''tempdb..#TEMP_MES_DATA'') is not null
				drop table #TEMP_MES_DATA

				'
				
				--print @dynamic_query
				insert into @TagData(TagName,TagValue)
				execute(@dynamic_query)

				
				if not exists (select top 1 1 from @TagData )
				begin
					Select 'Parameter Data Not Found In MES Server For Barcode ( ' + @BARCODE + ' )' as MSG,
					100 as STS, @MACHINECODE as 'MACHINECODE', @OPERATIONCODE as 'OPERATIONCODE'
					return
				end

				update @TagData set TagName=REPLACE(TagName,'C_','')
				update @TagData set TagValue='ND' where TagName not like '%_Status%' and TagValue='NULL'
				print '-------8--------'
				INSERT INTO @ParameterData(
				ProfitCenterCode,LineCode,MachineCode,
				OperationCode,StationCode,Barcode,TagName,Value,Result,Datecode,UserID)
				select @PROFITCENTERCODE,@LINECODE,@MACHINECODE,
				@OPERATIONCODE,'1',@Barcode,TagName,TagValue,@P_Result,'',@USERID 
				from @TagData

				if exists(select top 1 1 from Assy_ReportAnalysis_Tags(nolock)
				where ProfitCentercode=@PROFITCENTERCODE and MachineCode=@MACHINECODE
				and LineCode=@LINECODE
				)
				begin

				  update p 
				  set p.StationCode=a.OperationSeqno
				  from Assy_ReportAnalysis_Tags(nolock) a inner join 
				  @ParameterData p on a.TagName=p.TagName
				  inner join TagMst(nolock) t on
				  t.TagId=a.TagId

				end

				--SET @EXECQUERY = ''
				--SET @EXECQUERY = 'SELECT TOP 1 *					 	
				-- FROM ' 
				--+ @MachineLinkServer + ' WITH 
				--(NOLOCK) WHERE rfid = ''' + @BARCODE + ''''
				
				--print @EXECQUERY
				----exec(@EXECQUERY)

				--SET @EXECQUERY = ''
				--SET @EXECQUERY = 
				--'UPDATE '+ @MachineLinkServer + ' 
				--set STATUS=''PASS''
				--WHERE rfid = ''' + @BARCODE + ''''
				
				--print @EXECQUERY
				--exec(@EXECQUERY)


			end
			select ProfitCenterCode,LineCode,MachineCode,
			OperationCode,StationCode,Barcode,TagName,Value,Result,Datecode,UserID, 0 as STS 
			from @ParameterData order by convert(int,isnull(StationCode,0)) asc
				
		END TRY
		BEGIN CATCH

			SELECT CAST(ISNULL(ERROR_NUMBER(),0) as varchar(5)) + '|' + 
		CAST(ISNULL(ERROR_SEVERITY(),0) as varchar(5)) + '|' + 
		CAST(ISNULL(ERROR_STATE(),0) as varchar(5)) + '|' + 
		CAST(ISNULL(ERROR_PROCEDURE(),'Assy_Proc_FinalViewing') as varchar(200)) + '|' + 
		CAST(ISNULL(ERROR_LINE(),0) as varchar(5)) + '|' + 
		CAST(ISNULL(ERROR_MESSAGE(),'') as varchar(1500)) as MSG,
		100 as STS,
		@MACHINECODE as 'MACHINECODE', 
		@OPERATIONCODE as 'OPERATIONCODE'
		END CATCH

		END
		ELSE IF @CONDITION='UpdateTsReadStatusInMESServer'
		BEGIN
				SELECT TOP 1 @MachineLinkServerName = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE 
				AND LineCode = @LINECODE AND KeyType = 'MachineDBLinkServerName' AND STS_CD = 0
				
				SELECT TOP 1 @MachineLinkServerDB = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE 
				AND LineCode = @LINECODE AND KeyType = 'MachineDBLinkServerDB' AND STS_CD = 0
				
				SELECT TOP 1 @MachineDBTableName = KeyValue FROM RoutingConfigDetails (NOLOCK) 
				WHERE ProfitCenterCode = @PROFITCENTERCODE 
				AND LineCode = @LINECODE AND KeyType = 'MachineDBResultTableName' AND STS_CD = 0		
					
				

				if(@LINECODE='J02')
				begin
				    SET @MachineLinkServer = @MachineLinkServerName+'.'+@MachineLinkServerDB
					SET @EXECQUERY = ''
					SET @EXECQUERY = 
					'UPDATE '+ @MachineLinkServer + '.DBO.MASTER 
					set TS_Read=1,TS_TimeStamp=getdate()
					WHERE ISNULL(TS_Read,0)=0 and R_Oiling_Part_No = ''' + @BARCODE + ''''
				
					--print @EXECQUERY
					exec(@EXECQUERY)
				end
				else
				begin

				SET @MachineLinkServer =  @MachineLinkServerName+'...'+@MachineLinkServerDB				
				print @MachineLinkServer
				set @MachineDBTableName=''

				SELECT TOP 1 @MachineDBTableName = KeyValue FROM RoutingConfigDetails (NOLOCK) 
				WHERE ProfitCenterCode = @PROFITCENTERCODE 
				AND LineCode = @LINECODE AND KeyType = 'MachineDBResultTableName' AND STS_CD = 0	

				set @MachineLinkServer = REPLACE(@MachineLinkServer,'TABLE_NAME',@MachineDBTableName)

					SET @EXECQUERY = ''
					SET @EXECQUERY = 
					'UPDATE '+ @MachineLinkServer + '
					set TS_Read=1
					WHERE ISNULL(TS_Read,0)=0 and RFID = ''' + @BARCODE + ''''
				
					print @EXECQUERY
					exec(@EXECQUERY)

				end
		END
		--Ended By Sachin
		ELSE IF @CONDITION = 'GET_BORE_SCOPE_REASON_LIST'
		BEGIN
			SELECT REASON_CD, REASON_DESC FROM REASON_MASTER (NOLOCK) WHERE Warehouse_cd = @PROFITCENTERCODE AND STS_CD = 0 AND REASON_TP = 'BS_REASON'
			SET @RETURNINT = 1
		END
		ELSE IF @CONDITION = 'SCAN_BORE_SCOPE_BARCODE'
		BEGIN
			SELECT * INTO #Assy_BoreInspection_Scan FROM Assy_BoreInspection_Scan (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE AND LineCode = @LineCode AND ISNULL(Barcode,'') != ''
			IF EXISTS (SELECT 1 FROM #Assy_BoreInspection_Scan)
			BEGIN
				Declare @PrevBarcode Varchar(100) = ''
				SELECT @PrevBarcode = Barcode FROM #Assy_BoreInspection_Scan
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'Previous Scanned Barcode - ' + @PrevBarcode + ' is already available. Can not scan another - ' + @Barcode
				RETURN
			END

			--SELECT * INTO #Assy_BoreInspection_Result FROM Assy_BoreInspection_Result (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE AND LineCode = @LineCode AND Barcode = @Barcode
			SELECT * INTO #Assy_BoreInspection_Result FROM Assy_BoreInspection_Result (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE AND Barcode = @Barcode

			IF @Rework = 1
			BEGIN
				IF EXISTS (SELECT 1 FROM #Assy_BoreInspection_Result WHERE (IsMapped = 0 OR IsLocked = 1))
				BEGIN
					INSERT INTO Assy_BoreInspection_Result_History(ProfitCenterCode,LineCode,DateCode,PartNo,Barcode,Status,ReasonCode,Remark,IsRework,IsMapped,TSBarcode,ScanTimeStamp,
						Scan_By,ResultTimeStamp,MappedTimeStamp,ResultUpdated_By,IsLocked,LockedTimeStamp,Hist_Upd_Stamp,Hist_Upd_By)
					SELECT ProfitCenterCode,LineCode,DateCode,PartNo,Barcode,Status,ReasonCode,Remark,IsRework,IsMapped,TSBarcode,ScanTimeStamp,Scan_By,ResultTimeStamp,MappedTimeStamp,
						ResultUpdated_By,IsLocked,LockedTimeStamp,GETDATE() Hist_Upd_Stamp,@UserId Hist_Upd_By FROM #Assy_BoreInspection_Result

					DELETE FROM Assy_BoreInspection_Result WHERE ProfitCenterCode = @PROFITCENTERCODE AND LineCode = @LineCode AND Barcode = @Barcode
					DELETE FROM #Assy_BoreInspection_Result WHERE ProfitCenterCode = @PROFITCENTERCODE AND LineCode = @LineCode AND Barcode = @Barcode
				END
				ELSE IF EXISTS (SELECT 1 FROM #Assy_BoreInspection_Result WHERE IsMapped = 1)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'Scanned Barcode - ' + @Barcode + ' is already mapped with TS Barcode so can not Rework.'
					RETURN
				END
				ELSE
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'Scanned Barcode - ' + @Barcode + ' is not tested previously so can not Rework.'
					RETURN
				END
			END

			--Start HP Leak Test Validation from Central Table by Rashid On 28-06-2019--
			IF EXISTS
			(
				SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
					AND KeyType = 'IsHPLeakTestValidation' AND KeyValue = '1'
			)
			BEGIN
				IF NOT EXISTS
				(
					SELECT 1 FROM Assy_LineAssyHP (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND Barcode = @Barcode
				)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'Scanned Barcode - ' + @Barcode + ' is not passed on HP Leak Test station (Offline station).'
					RETURN
				END
			END
			--End HP Leak Test Validation from Central Table by Rashid On 28-06-2019--

			IF EXISTS (SELECT 1 FROM #Assy_BoreInspection_Result WHERE IsLocked = 1)
			BEGIN
				Declare @LockedTimeStamp DateTime
				SELECT @LockedTimeStamp = LockedTimeStamp FROM #Assy_BoreInspection_Result
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'Scanned Barcode - ' + @Barcode + ' is locked on DateTime - ' + CAST(@LockedTimeStamp AS VARCHAR)
				RETURN
			END
			ELSE IF EXISTS (SELECT 1 FROM #Assy_BoreInspection_Result WHERE IsMapped = 1)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'Scanned Barcode - ' + @Barcode + ' is already mapped with TS Barcode.'
				RETURN
			END
			ELSE IF EXISTS (SELECT 1 FROM #Assy_BoreInspection_Result WHERE IsMapped = 0)
			BEGIN
				SELECT @STATUS = Status, @DateCode = DateCode FROM #Assy_BoreInspection_Result
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'Scanned Barcode - ' + @Barcode + ' is already ' + Case @STATUS WHEN 'FL' THEN 'Fail' WHEN 'PS' THEN 'Pass' ELSE @STATUS END + ' on DateCode - ' + @DateCode
				RETURN
			END
			ELSE
			BEGIN
				INSERT INTO Assy_BoreInspection_Scan(ProfitCenterCode,LineCode,DateCode,Barcode,IsRework,ScanTimeStamp,Scan_By)
				SELECT @PROFITCENTERCODE,@LineCode,@DateCode,@Barcode,@Rework,GETDATE(),@UserId
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'Barcode - ' + @Barcode + ' scanned successfully.'
			END
		END
		ELSE IF @CONDITION = 'SAVE_BORE_SCOPE_BARCODE'
		BEGIN
		
		SELECT * INTO #Assy_BoreInspection_Scan_Save FROM Assy_BoreInspection_Scan (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE AND LineCode = @LineCode AND ISNULL(Barcode,'') != ''	
		SELECT @BORESCANTIMESTAMP = SCANTIMESTAMP FROM #Assy_BoreInspection_Scan_Save
		SELECT @BORESCANTIMESTAMP = ISNULL(NULLIF(@BORESCANTIMESTAMP,''),'')--  DEFAULT VALUE IS ''
		--IF NOT EXISTS (SELECT 1 FROM #Assy_BoreInspection_Scan_Save)
		  IF (@BORESCANTIMESTAMP = '')
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'No Barcode Pending for Marking as ' + Case @STATUS WHEN 'FL' THEN 'Fail' WHEN 'PS' THEN 'Pass' ELSE @STATUS END + '.'
				RETURN
			END
		SELECT @BorePassFailLimit = dbo.ASSY_FN_GET_PARAMETER_VALUE('AssLine', @LineCode, 'BV_ProcessTime', @PROFITCENTERCODE)  
		SELECT @BorePassFailLimit = ISNULL(NULLIF(@BorePassFailLimit,''),'0')--  DEFAULT VALUE IS 0
	    IF (CAST(@BorePassFailLimit AS int) <> 0 ) 
		Begin 
		 IF(DATEDIFF(SECOND, @BORESCANTIMESTAMP, GETDATE()) < CAST(@BorePassFailLimit AS int)) 
			BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'Time Limit to declare ' + Case @STATUS WHEN 'FL' THEN 'Fail' WHEN 'PS' THEN 'Pass' ELSE @STATUS END + ' decision not reached.'
					RETURN
			END
		END
			
			UPDATE #Assy_BoreInspection_Scan_Save SET Status = @Status

			INSERT INTO Assy_BoreInspection_Result(ProfitCenterCode,LineCode,DateCode,PartNo,Barcode,Status,ReasonCode,Remark,IsRework,ScanTimeStamp,Scan_By,ResultTimeStamp,ResultUpdated_By)
			SELECT ProfitCenterCode,LineCode,DateCode,LEFT(Barcode,4) PartNo,Barcode,Status,@Reason,@Remark,IsRework,ScanTimeStamp,Scan_By,GETDATE() ResultTimeStamp,@UserID ResultUpdated_By FROM #Assy_BoreInspection_Scan_Save

			DELETE FROM Assy_BoreInspection_Scan WHERE ProfitCenterCode = @PROFITCENTERCODE AND LineCode = @LineCode

			SELECT @Barcode = Barcode FROM #Assy_BoreInspection_Scan_Save
			SET @RETURNINT = 1
			SET @RETURNVALUE = 'Barcode - ' + @Barcode + ' has been marked as ' + Case @STATUS WHEN 'FL' THEN 'Fail' WHEN 'PS' THEN 'Pass' ELSE @STATUS END + ' successfully.'
		END
		ELSE IF @CONDITION = 'GET_RESULT_BARCODE_LIST'
		BEGIN
			SELECT ISNULL(Barcode,'') + ' - ' + Case ISNULL(Status,'') WHEN 'PS' THEN 'Pass' ELSE 'Fail' END Barcode FROM Assy_BoreInspection_Result (NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND DateCode = @DateCode Order By ResultTimeStamp Desc
		END
		ELSE IF @CONDITION = 'BORE_SCOPE_PARTS_COUNT'
		BEGIN
			SELECT * INTO #Assy_BoreInspection_Result_Count FROM Assy_BoreInspection_Result (NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND DateCode = @DateCode

			SELECT COUNT(*) FROM #Assy_BoreInspection_Result_Count WHERE Status = 'PS'
			SELECT COUNT(*) FROM #Assy_BoreInspection_Result_Count WHERE Status = 'FL'
			SET @RETURNINT = 1
			SET @RETURNVALUE = 'Success'
		END
		ELSE IF @CONDITION = 'CHECK_BORE_INSPECTION_BARCODE_FOR_MAPPING'
		BEGIN
			IF EXISTS
			(
				SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
					AND KeyType = 'IsBoreViewingMixUpRequired' AND KeyValue = '1'
			)
			BEGIN
				SELECT @MixUpOperationCode = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
					AND KeyType = 'MixUpOperationCode'
				
				SELECT L.OperationCode INTO #Routing FROM RoutingConfigLineWise (NOLOCK) L
					INNER JOIN RoutingConfigPartWise (NOLOCK) P
						ON L.OperationCode = P.OperationCode AND L.MachineCode = P.MachineCode AND L.ProfitCenterCode = P.ProfitCenterCode
							WHERE L.ProfitCenterCode = @PROFITCENTERCODE AND L.LineCode = @LINECODE AND P.PARTNO = @PARTNUMBER
								AND L.Traceability = 1 AND P.Traceability = 1
									AND ISNULL(L.Engraving, 0) = 0 AND ISNULL(P.Engraving, 0) = 0

				IF EXISTS (SELECT 1 FROM #Routing WHERE OperationCode = @MixUpOperationCode)
				BEGIN
					--Declare @NonTSBarcode VARCHAR(100) = ''
					SELECT * INTO #Assy_TS_NonTS_Barcode_Scan FROM Assy_TS_NonTS_Barcode_Scan (NOLOCK)
						WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode

					IF EXISTS (SELECT 1 FROM #Assy_TS_NonTS_Barcode_Scan)
					BEGIN
						SELECT Top 1 @NonTSBarcode = Barcode FROM #Assy_TS_NonTS_Barcode_Scan
						DELETE FROM Assy_TS_NonTS_Barcode_Scan

						IF ISNULL(@NonTSBarcode,'') = ''
						BEGIN
							SET @RETURNVALUE = 'TMC_SERVICE-BARCODE_FOUND_BLANK'
							SELECT @RETURNVALUE
					
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SERVICE', @MixUpOperationCode, 'BARCODE', @NonTSBarcode, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							RETURN
						END

						INSERT INTO Assy_TS_Bracket_Barcode_Mapping(ProfitCenterCode,LineCode,SignalMachineCode,DateCode,BracketBarCode,IsMapped,Timestamp,UserID)
						SELECT ProfitCenterCode,LineCode,SignalMachineCode,DateCode,Barcode,IsMapped,ScanTimeStamp,Scan_By FROM #Assy_TS_NonTS_Barcode_Scan
						/* -- Validation is happening on scanning time
						SET @EXECQUERY = ''
						SET @EXECQUERY = 'SELECT TOP 1 ISNULL(Barcode,''''), ISNULL(Status,''''), ISNULL(IsMapped,0) FROM ' + @LINKSERVERNAME + '.DBO.Assy_BoreInspection_Result
							WHERE Barcode = ''' + @NonTSBarcode + ''''
						PRINT @EXECQUERY

						INSERT INTO @Assy_Bore_Inspection_Result(Barcode, Status, IsMapped)
						EXEC (@EXECQUERY)
					
						IF NOT EXISTS (SELECT 1 FROM @Assy_Bore_Inspection_Result)
						BEGIN
							SET @RETURNVALUE = 'FAIL|TMC_SERVICE-BARCODE_NOT_TESTED_ON_BI_STATION'
							SELECT @RETURNVALUE
					
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SERVICE', @MixUpOperationCode, 'BARCODE', @NonTSBarcode, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							RETURN
						END

						SELECT	@BI_BARCODE = ISNULL(Barcode,''), @BI_STATUS = ISNULL(Status,''), @BI_IsMapped = IsMapped
							FROM @Assy_Bore_Inspection_Result

						IF @BI_IsMapped = 1
						BEGIN
							SET @RETURNVALUE = 'FAIL|TMC_SERVICE-BARCODE_ALREADY_MAPPED_BI_STATION'
							SELECT @RETURNVALUE
					
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SERVICE', @MixUpOperationCode, 'BARCODE', @NonTSBarcode, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							RETURN
						END

						IF @BI_STATUS != 'PS'
						BEGIN
							SET @RETURNVALUE = 'FAIL|TMC_SERVICE-BARCODE_FAILED_ON_BI_STATION'
							SELECT @RETURNVALUE
					
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ASSEMBLY_SERVICE', @MixUpOperationCode, 'BARCODE', @NonTSBarcode, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							RETURN
						END
						*/
						SET @RETURNVALUE = 'SUCCESS|' + @NonTSBarcode
						SELECT @RETURNVALUE
					
						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'ASSEMBLY_SERVICE', @MixUpOperationCode, 'BARCODE', @NonTSBarcode, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
					END
					ELSE
					BEGIN
						SET @RETURNVALUE = 'FAIL|' + 'NO_BARCODE_SCANNED_BUT_PASS_IN_VISION'
						SELECT @RETURNVALUE
					
						INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
						SELECT @PROFITCENTERCODE, 'ASSEMBLY_SERVICE', @MixUpOperationCode, 'BARCODE', @NonTSBarcode, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
					END
				END
			END
			ELSE
			BEGIN
				SELECT 'OTHER|NOT_REQUIRED'
			END
		END
		ELSE IF @CONDITION = 'MAP_BORE_INSPECTION_BARCODE_WITH_TS'
		BEGIN
			UPDATE Assy_TS_Bracket_Barcode_Mapping SET TSBarcode = @Barcode, IsMapped = 1, UpdateTimestamp = GETDATE()
				WHERE BracketBarCode = @NonTSBarcode AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode

			SELECT @MixUpOperationCode = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
					AND KeyType = 'MixUpOperationCode'

			Declare @Curr_MachineCode VARCHAR(20) = '', @First_OperationCode VARCHAR(20) = ''
			SELECT * INTO #RoutingConfigLineWise FROM RoutingConfigLineWise WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			SELECT @Curr_MachineCode = MachineCode FROM #RoutingConfigLineWise WHERE OperationCode = @MixUpOperationCode
			SELECT @First_OperationCode = OperationCode FROM #RoutingConfigLineWise WHERE OperationSeqNo = 1

			INSERT INTO Assy_LineAssyStatus_Running(ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,Status,FailCount,Datecode,PartNo,Active,ResultTimestamp,
				ScanTimestamp,UserID,IsTallyChartApproved,IsReworkPart,ProductionOrderNo,PROD_LOT_NO,IsPendingPart,Category,Live_Datecode)
			SELECT ProfitCenterCode,LineCode,@Curr_MachineCode MachineCode,@MixUpOperationCode OperationCode,StationCode,Barcode,'PS' Status,FailCount,Datecode,PartNo,Active,GETDATE() ResultTimestamp,
				GETDATE() ScanTimestamp,UserID,IsTallyChartApproved,IsReworkPart,ProductionOrderNo,PROD_LOT_NO,IsPendingPart,Category,@Live_Datecode
					FROM Assy_LineAssyStatus_Running (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND Barcode = @Barcode
						AND OperationCode = @First_OperationCode
			
			IF NOT EXISTS (SELECT 1 FROM ASSY_RESULT (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @MixUpOperationCode)
			BEGIN
				INSERT INTO ASSY_RESULT(LineCode,OperationCode,StationCode,Barcode)
				SELECT @LineCode,@MixUpOperationCode,'1',@Barcode
			END
			ELSE
			BEGIN
				UPDATE ASSY_RESULT SET BARCODE = @Barcode WHERE OperationCode = @MixUpOperationCode
			END
			
			UPDATE Assy_BoreInspection_Result SET IsMapped = 1, MappedTimeStamp = GETDATE(), TSBarcode = @Barcode WHERE Barcode = @NonTSBarcode

			--SET @EXECQUERY = ''
			--SET @EXECQUERY = 'UPDATE ' + @LINKSERVERNAME + '.DBO.Assy_BoreInspection_Result SET IsMapped = 1, MappedTimeStamp = GETDATE(), TSBarcode = ''' + @Barcode + '''
			--	WHERE Barcode = ''' + @NonTSBarcode + ''''
			--PRINT @EXECQUERY
			--EXEC (@EXECQUERY)

			SELECT 'Success'
		END
		ELSE IF @CONDITION = 'VALIDATE_BORE_VIEW_BARCODE'
		BEGIN
			Declare @MapBarcode1 VARCHAR(100) = '',@MapBarcode2 VARCHAR(100) = ''
			SELECT @MapBarcode1 = TSBarcode FROM Assy_TS_Bracket_Barcode_Mapping (NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode AND BracketBarcode = @Barcode AND IsMapped = 1
			
			SELECT @MapBarcode2 = Barcode FROM ASSY_SCAN_OK (NOLOCK) WHERE LineCode = @LineCode
				AND OperationCode = (SELECT dbo.Assy_FN_Get_FinalViewing_OperationCode_From_LineCode(@ProfitCenterCode,@LineCode))
			
			IF ISNULL(@MapBarcode1,'') != '' AND ISNULL(@MapBarcode2,'') != '' AND @MapBarcode1 = @MapBarcode2
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'MAPPING_SUCCESS'
			END
			ELSE
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'MAPPING_FAIL'
			END

			IF EXISTS (SELECT 1 FROM Assy_FV_BoreView_Mapping_Status WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND OperationCode = @OperationCode)
			BEGIN
				UPDATE Assy_FV_BoreView_Mapping_Status SET Barcode = @Barcode, MappingStatus = Case @RETURNVALUE WHEN 'MAPPING_SUCCESS' THEN 2 WHEN 'MAPPING_FAIL' THEN 3 END, TimeStamp = GETDATE()
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND OperationCode = @OperationCode
			END
			ELSE
			BEGIN
				INSERT INTO Assy_FV_BoreView_Mapping_Status(ProfitCenterCode,LineCode,Barcode,MappingStatus,TimeStamp,OperationCode,MachineCode)
				SELECT @ProfitCenterCode,@LineCode,@Barcode,Case @RETURNVALUE WHEN 'MAPPING_SUCCESS' THEN 2 WHEN 'MAPPING_FAIL' THEN 3 END,GETDATE(),@OperationCode,@MachineCode
			END
		END
		ELSE IF @CONDITION = 'GET_BOREVIEWING_LAST_SCAN_BARCODE'
		BEGIN
			SELECT @RETURNVALUE = ISNULL(MappingStatus, 0) FROM Assy_FV_BoreView_Mapping_Status (NOLOCK)
				WHERE LINECODE = @LINECODE AND ProfitCenterCode = @ProfitCenterCode AND OperationCode = @OperationCode
			SET @RETURNINT = 1
			RETURN
		END
		ELSE IF @CONDITION = 'GET_BORE_VIEWING_TOUCH_PANEL_DATA'
		BEGIN
			IF ISNULL(@DateCode,'') = ''
			BEGIN
				SELECT ProfitCenterCode, LineCode, DateCode, Barcode, Case Status WHEN 'PS' THEN 'Pass' WHEN 'FL' THEN 'Fail' ELSE Status END Result,
					ISNULL(RM.REASON_DESC,'') Reason_Desc, Remark, ScanTimeStamp, Scan_By
					FROM Assy_BoreInspection_Result (NOLOCK) ABIR
						LEFT JOIN REASON_MASTER (NOLOCK) RM
							ON ABIR.ReasonCode = RM.REASON_CD AND ABIR.ProfitCenterCode = RM.warehouse_cd AND RM.REASON_TP = 'BS_REASON'
								WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LINECODE AND Barcode Like '%' + @Barcode + '%'
									Order By 8
			END
			ELSE
			BEGIN
				SELECT ProfitCenterCode, LineCode, DateCode, Barcode, Case Status WHEN 'PS' THEN 'Pass' WHEN 'FL' THEN 'Fail' ELSE Status END Result,
					ISNULL(RM.REASON_DESC,'') Reason_Desc, Remark, ScanTimeStamp, Scan_By
					FROM Assy_BoreInspection_Result (NOLOCK) ABIR
						LEFT JOIN REASON_MASTER (NOLOCK) RM
							ON ABIR.ReasonCode = RM.REASON_CD AND ABIR.ProfitCenterCode = RM.warehouse_cd AND RM.REASON_TP = 'BS_REASON'
								WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LINECODE AND DateCode = @DateCode AND Barcode Like '%' + @Barcode + '%'
									Order By 8
			END
			RETURN
		END
		ELSE IF @CONDITION = 'GET_BORE_VIEWING_MAPPED_TS_BARCODE_DATA'
		BEGIN
			IF ISNULL(@DateCode,'') = ''
			BEGIN
				SELECT ProfitCenterCode, LineCode, DateCode, TSBarcode, BracketBarcode QRBarcode,UpdateTimeStamp MappingTimeStamp, UserID
					FROM Assy_TS_Bracket_Barcode_Mapping (NOLOCK)
						WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LINECODE AND TSBarcode Like '%' + @Barcode + '%'
							Order By 6
			END
			ELSE
			BEGIN
				SELECT ProfitCenterCode, LineCode, DateCode, TSBarcode, BracketBarcode QRBarcode,UpdateTimeStamp MappingTimeStamp, UserID
					FROM Assy_TS_Bracket_Barcode_Mapping (NOLOCK)
						WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LINECODE AND DateCode = @DateCode AND TSBarcode Like '%' + @Barcode + '%'
							Order By 6
			END
			RETURN
		END
		ELSE IF @CONDITION = 'SYNC_BORE_VIEWING_DATA_FROM_CENTRAL_TO_LOCAL'
		BEGIN
			SET @ExecQuery = @LinkServerName + '.dbo.Assy_BoreInspection_Result WITH (NOLOCK) WHERE IsMapped = 0 AND ProfitCenterCode = ''' + @ProfitCenterCode + ''''

			SET @ExecQuery = N'SELECT ProfitCenterCode,LineCode,DateCode,PartNo,Barcode,Status,ReasonCode,Remark,IsRework,IsMapped,TSBarcode,ScanTimeStamp,Scan_By,ResultTimeStamp,
			ResultUpdated_By,MappedTimeStamp,IsLocked,LockedTimeStamp FROM ' + @ExecQuery
			
			IF OBJECT_ID('TempDB..#Temp_Assy_BoreInspection_Result') IS NOT NULL 
			BEGIN 
				DROP TABLE #Temp_Assy_BoreInspection_Result
			END

			SELECT ProfitCenterCode,LineCode,DateCode,PartNo,Barcode,Status,ReasonCode,Remark,IsRework,IsMapped,TSBarcode,ScanTimeStamp,Scan_By,ResultTimeStamp,
				ResultUpdated_By,MappedTimeStamp,IsLocked,LockedTimeStamp
					INTO #Temp_Assy_BoreInspection_Result FROM Assy_BoreInspection_Result WITH (NOLOCK) WHERE 1 = 2 
			
			PRINT @ExecQuery
			INSERT INTO #Temp_Assy_BoreInspection_Result
			EXECUTE (@ExecQuery)
			
			IF EXISTS (SELECT Top 1 1 FROM #Temp_Assy_BoreInspection_Result WITH (NOLOCK)) 
			BEGIN
				DELETE FROM Assy_BoreInspection_Result WHERE IsMapped = 0 AND ProfitCenterCode = @ProfitCenterCode

				MERGE INTO Assy_BoreInspection_Result AS A
					USING #Temp_Assy_BoreInspection_Result AS B
						ON	ISNULL(A.ProfitCenterCode,'') = ISNULL(B.ProfitCenterCode,'')
							AND ISNULL(A.LineCode,'') = ISNULL(B.LineCode,'')
							AND ISNULL(A.Barcode,'') = ISNULL(B.Barcode,'')
				WHEN NOT MATCHED THEN
					INSERT
					(
						ProfitCenterCode,LineCode,DateCode,PartNo,Barcode,Status,ReasonCode,Remark,IsRework,IsMapped,TSBarcode,ScanTimeStamp,Scan_By,
							ResultTimeStamp,ResultUpdated_By,MappedTimeStamp,IsLocked,LockedTimeStamp
					)
					VALUES
					(
						B.ProfitCenterCode,B.LineCode,B.DateCode,B.PartNo,B.Barcode,B.Status,B.ReasonCode,B.Remark,B.IsRework,B.IsMapped,B.TSBarcode,B.ScanTimeStamp,B.Scan_By,
							B.ResultTimeStamp,B.ResultUpdated_By,B.MappedTimeStamp,B.IsLocked,B.LockedTimeStamp
					);

				IF OBJECT_ID('MissingUpdateList') IS NOT NULL 
				BEGIN 
					DROP TABLE MissingUpdateList
				END

				SELECT L.Barcode, L.IsMapped, L.TSBarcode INTO MissingUpdateList FROM #Temp_Assy_BoreInspection_Result C
						JOIN Assy_BoreInspection_Result L
							ON C.Barcode = L.Barcode AND C.ProfitCenterCode = L.ProfitCenterCode AND C.TSBarcode = L.TSBarcode
								WHERE L.ProfitCenterCode = @PROFITCENTERCODE AND L.IsMapped = 1

				IF EXISTS
				(
					SELECT 1 FROM MissingUpdateList
				)
				BEGIN
					SET @ExecQuery = ''
					SET @ExecQuery = 'Update C SET C.IsMapped = 1 FROM ' + @LinkServerName + '.dbo.Assy_BoreInspection_Result C
					JOIN MissingUpdateList L
					ON C.Barcode = L.Barcode'

					PRINT @ExecQuery
					EXECUTE (@ExecQuery)
				END

				SET @RETURNVALUE = 'Data Sync Successful from Central to Local.'
				SET @RETURNINT = 1
			END
			ELSE
			BEGIN
				SET @RETURNVALUE = 'No Data Found for syncing.'
				SET @RETURNINT = 2
			END
			RETURN
		END
		ELSE IF @CONDITION='IS_LABEL_PRINTING_REQUIRED'
		BEGIN
				--Added By Sachin Kumar 12Aug2019
				--Get Label Printing Required For Station Other Than Final Viewing.
				 SELECT distinct MACHINECODE,OPERATIONCODE FROM ROUTINGCONFIGLINEWISE WITH (NOLOCK) 
				 WHERE PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE=@LINECODE 
				 AND MACHINECODE !=DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE) 
				 AND ISNULL(LABELPRINTING,0)=1 
		END
		ELSE IF @CONDITION = 'GET_PP_RESULT_BARCODE_LIST'
		BEGIN
			SELECT ISNULL(Barcode,'') + ' - ' + Case ISNULL(Result,'') WHEN '' THEN 'Scanned' WHEN 'PS' THEN 'Pass' ELSE 'Fail' END Barcode FROM Assy_LineAssyHP (NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND DateCode = @DateCode Order By TimeStamp Desc
		END
		ELSE IF @CONDITION = 'PIN_PRESSING_PARTS_COUNT'
		BEGIN
			SELECT * INTO #Assy_LineAssyHP_Count FROM Assy_LineAssyHP (NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND DateCode = @DateCode

			SELECT COUNT(*) FROM #Assy_LineAssyHP_Count WHERE Result = 'PS'
			SELECT COUNT(*) FROM #Assy_LineAssyHP_Count WHERE Result = 'FL'
			SET @RETURNINT = 1
			SET @RETURNVALUE = 'Success'
		END
		ELSE IF @CONDITION = 'SCAN_PIN_PRESSING_BARCODE'
		BEGIN
			--CHECK FOR JIG IN/OUT STATUS
			IF EXISTS 
			(
				SELECT 1 FROM MachineMst WITH (NOLOCK) WHERE MachineCode = @MachineCode  AND IndexPerStations = 1
			)
			BEGIN
				IF EXISTS
				( 
					SELECT 1 FROM Assy_Stations_Zig_In_Out_Status (NOLOCK) WHERE LineCode = @LineCode  AND OperationCode = @OperationCode  AND StatusInOut = 1
				)
				BEGIN
					SELECT @ReturnInt = 1, @ReturnValue = 'Jig is inside, So You cannot scan Barcode.'
					
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @ProfitCenterCode, 'TMC_PP_SCAN', @OperationCode, 'Barcode', @Barcode, @PartNumber, @LineCode, @ReturnValue, @UserId, GETDATE(), @UserId, GETDATE()
					RETURN
				END
			END

			SELECT @FailCountDefined = CONVERT(INT,dbo.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'REWORK_COUNT', 'REWORK_COUNT', @ProfitCenterCode))
			
			SELECT * INTO #Assy_LineAssyHP FROM Assy_LineAssyHP (NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND Barcode = @Barcode

			SELECT @FailCount = ISNULL(FailCount, 0) FROM #Assy_LineAssyHP
					WHERE MachineCode = @MachineCode AND ISNULL(Result, '') = 'FL'
			
			IF(@FailCount >= @FailCountDefined)
			BEGIN
				SELECT @ReturnInt = 1, @ReturnValue = 'Maximum failed attempt reached.'
				
				--UPDATE INCORRECT LABEL
				EXEC Assy_Proc_IncorrectLabel_Manage @Condition = 'UPDATE', @LineCode = @LineCode, @OperationCode = @OperationCode,
						@Barcode = @Barcode, @HMIMessage = @ReturnValue

				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @ProfitCenterCode, 'TMC_PP_SCAN', @OperationCode, 'Barcode', @Barcode, @PartNumber, @LineCode, @ReturnValue, @UserId, GETDATE(), @UserId, GETDATE()
				RETURN
			END

			IF @FailCount > 0 AND @BAR_STATUS_KEY = 1
			BEGIN
				SET @BAR_STATUS = 4
			END

			IF EXISTS
			( 
				SELECT 1 FROM #Assy_LineAssyHP WHERE MachineCode = @MachineCode AND ISNULL(Result, '') = 'PS'
			)
			BEGIN
				SELECT @ReturnInt = 1, @ReturnValue = 'Part has already processed.'

				--UPDATE INCORRECT LABEL
				EXEC Assy_Proc_IncorrectLabel_Manage @Condition = 'UPDATE', @LineCode = @LineCode, @OperationCode = @OperationCode,
						@Barcode = @Barcode, @HMIMessage = @ReturnValue

				INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
				SELECT @ProfitCenterCode, 'TMC_PP_SCAN', @OperationCode, 'Barcode', @Barcode, @PartNumber, @LineCode, @ReturnValue, @UserId, GETDATE(), @UserId, GETDATE()
				RETURN
			END

			IF EXISTS
			(
				SELECT 1 FROM Assy_Scan_OK (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode AND MachineCode = @MachineCode
			)
			BEGIN
				UPDATE Assy_Scan_OK SET IsScan = 1, Barcode = @Barcode WHERE LineCode = @LineCode AND OperationCode = @OperationCode AND MachineCode = @MachineCode
				
			END
			ELSE
			BEGIN
				INSERT INTO Assy_Scan_OK(LineCode, OperationCode, StationCode, Barcode, IsScan, MachineCode)
				SELECT @LineCode, @OperationCode, @StationCode, @Barcode, 1, @MachineCode
			END
			
			--BAR_STATUS	--1 first time scan
			IF @BAR_STATUS_KEY = 1
			BEGIN
				if not exists (select top 1 1 from Barcode_Status_Time (nolock) where Barcode=@Barcode and DateCode=@Live_Datecode
				and LineCode=@LineCode and MachineCode=@MachineCode and OperationCode=@OperationCode)
				begin
					insert into Barcode_Status_Time (Barcode, BAR_STATUS, LineCode, MachineCode, OperationCode, DateCode, EntStamp, UpdateStamp)
					values (@Barcode, @BAR_STATUS, @LineCode, @MachineCode, @OperationCode, @Live_Datecode, getdate(), getdate())
				end
				else
				begin
					update Barcode_Status_Time set BAR_STATUS=@BAR_STATUS, UpdateStamp=getdate() where Barcode=@Barcode and DateCode=@Live_Datecode 
					and LineCode=@LineCode and MachineCode=@MachineCode and OperationCode=@OperationCode
				end
			END

			--RESET INCORRECT LABEL
			UPDATE Assy_incorrectLabel SET HMIMessageCode = '', IsIncorrect = 0 WHERE LineCode = @LineCode AND OperationCode = @OperationCode
			--RESET DUPLICATE LABEL
			UPDATE Assy_DuplicateLabel SET IsDuplicate = 0 WHERE LineCode = @LineCode AND OperationCode = @OperationCode

			IF NOT EXISTS (SELECT 1 FROM #Assy_LineAssyHP)
			BEGIN
				INSERT INTO Assy_LineAssyHP(ProfitCenterCode,LineCode,Datecode,MachineCode,OperationCode,Barcode,FailCount,Result,UserID,Timestamp,PartNo,IsCentralUpdate)
				SELECT @ProfitCenterCode,@LineCode,@Datecode,@MachineCode,@OperationCode,@Barcode,0,'',@UserID,GETDATE(),@PartNumber,0
			END
			ELSE
			BEGIN
				UPDATE Assy_LineAssyHP SET Timestamp = GETDATE(), UpdateTimeStamp = GETDATE(), DateCode = @Datecode
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND Barcode = @Barcode AND OperationCode = @OperationCode
			END

			SELECT @ReturnInt = 1, @ReturnValue = 'SCANNED_SUCCESSFULLY'
			
			INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
			SELECT @ProfitCenterCode, 'TMC_PP_SCAN', @OperationCode, 'Barcode', @Barcode, @PartNumber, @LineCode, @ReturnValue, @UserId, GETDATE(), @UserId, GETDATE()
			RETURN
		END
		ELSE IF @CONDITION = 'SHOWRESULT_PP_DATA'
		BEGIN				
			SELECT Res.LineCode, Res.OperationCode, PP.MachineCode, '' StationCode, PP.Barcode, PP.Result Status
				FROM Assy_Result (NOLOCK) Res
					INNER JOIN Assy_LineAssyHP (NOLOCK) PP
				ON Res.LineCode = PP.LineCode AND Res.OperationCode = PP.OperationCode AND Res.Barcode = PP.Barcode
					WHERE  ISNULL(Res.Barcode, '') <> '' AND (ISNULL(PP.Result, '') <> '')
			
			UPDATE Assy_Result SET Barcode = '', StationCode = '' WHERE ISNULL(Barcode, '') <> ''
			
			SELECT @ReturnInt = 1, @ReturnValue = 'SUCCESS'
			RETURN
		END
		ELSE IF @CONDITION = 'GET_PIN_PRESSING_BARCODE_DATA'
		BEGIN
			IF ISNULL(@DateCode,'') = ''
			BEGIN
				SELECT ProfitCenterCode, LineCode, DateCode, PartNo, Barcode, Case Result WHEN 'PS' THEN 'Pass' WHEN 'FL' THEN 'Fail' ELSE Result END Result, ISNULL(FailCount,0) FailCount,
					Timestamp ScanTimeStamp, UserID, UpdateTimeStamp
						FROM Assy_LineAssyHP (NOLOCK) PP
							WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND Barcode Like '%' + @Barcode + '%'
								Order By 8
			END
			ELSE
			BEGIN
				SELECT ProfitCenterCode, LineCode, DateCode, PartNo, Barcode, Case Result WHEN 'PS' THEN 'Pass' WHEN 'FL' THEN 'Fail' ELSE Result END Result, ISNULL(FailCount,0) FailCount,
					Timestamp ScanTimeStamp, UserID, UpdateTimeStamp
						FROM Assy_LineAssyHP (NOLOCK) PP
							WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND DateCode = @DateCode AND Barcode Like '%' + @Barcode + '%'
								Order By 8
			END
			RETURN
		END
		ELSE IF @CONDITION = 'GET_TMC_PART_LIST'
		BEGIN
			SELECT SEWS_PART_NO PartNo FROM Product_Master (NOLOCK) WHERE warehouse_cd = @ProfitCenterCode AND STS_CD = 0 AND MATERIAL_TP = 'TMC' Order By 1
		END
		ELSE IF @CONDITION = 'GET_PP_MACHINE_OPERATION'
		BEGIN
			SELECT MachineCode, OperationCode FROM MachineDtl (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
		END
		ELSE IF @CONDITION = 'SYNC_PP_PRODUCT_MASTER'
		BEGIN
			EXEC Assy_Proc_Sync_Masters_Data @LineCode = @LineCode, @ProfitCenterCode = @ProfitCenterCode, @UserName = @USERID,
				@ReturnValue = @ReturnValue OUT, @ReturnInt = @ReturnInt OUT, @UIInterfaceName = 'SYNCBUTTON', @table_name = 'PRODUCT_MASTER', @Condition = ''
		END
		ELSE IF @CONDITION = 'CENTRAL_FV_VALIDATE_BARCODE'
		BEGIN
			IF EXISTS(SELECT TOP 1 1 FROM Assy_LineAssyStatus (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND Barcode = @Barcode AND OperationCode = @OperationCode AND Status = 'PS')
			BEGIN
				SET @ReturnValue = 'SUCCESS'
				SET @ReturnInt = 1
			END
			ELSE
			BEGIN
				SET @ReturnValue = 'Scanned Barcode not cleared from final viewing station.'
				SET @ReturnInt = 1
			END
		END
		ELSE IF @CONDITION = 'GET_BORE_SCOPE_PART_LIST'
		BEGIN
			SELECT PartNo, LabelDataValue INTO #Assy_Coupling_LabelInfo_Mst FROM Assy_Coupling_LabelInfo_Mst (NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode AND LabelDataName = 'BV_MachinePartNo' AND IsActive = 1
					Order By PartNo

			SELECT Distinct PartNo + ' - ' + LabelDataValue FROM #Assy_Coupling_LabelInfo_Mst
		END
		ELSE IF @CONDITION = 'GET_BIL_PART_CUSTOMER_PART_LIST'
		BEGIN
			SELECT PartNo, CustomerPartNo INTO #Assy_Coupling_LabelInfo_Mst_CustPartNo FROM Assy_Coupling_LabelInfo_Mst (NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode AND IsActive = 1
					Order By PartNo

			SELECT Distinct PartNo, CustomerPartNo FROM #Assy_Coupling_LabelInfo_Mst_CustPartNo
		END
		ELSE IF @CONDITION = 'UPDATE_CUSTOMER_PART_FOR_COUPLING_PACKAGING'
		BEGIN
			SELECT PKG_DEF_ID,WH_CODE,IS_STANDARD_PACKING,PART_NUMBER,PART_DESC,CUSTOMER_PART_NO,COUNTRY,CONTAINERTYPE,PACKAGE_TYPE_CODE,DISPATCH_TYPE,
				LOT_QTY,IS_LAYERED_PACKING,IS_SKID_LABEL,PKG_SERIAL_NO,NO_OF_LAYERS,ROWS_PER_LAYER,COLS_PER_LAYER,MODEL,Layer_Lbl_Prn,
					Skid_Lbl_Prn,CUST_ADDRESS1,CUST_ADDRESS2,CUST_ADDRESS3,CUST_ADDRESS4,IS_ACTIVE,ENT_DATE,ENT_BY,MOD_DATE,MOD_BY,
						TMC_Lbl_Prn,Servo_Lbl_Prn,Coupling_Lbl_Prn,CUSTOMER_CD,IS_PALLET_LABEL,PALLETSIZE,PALLET_LBL_PRN,
							IS_CUST_LBL_SCAN,PKG_SERIAL_NO_MANUAL
								INTO #PKG_Part_Mapping FROM PKG_Part_Mapping (NOLOCK)
									WHERE WH_CODE = @ProfitCenterCode AND PART_NUMBER = @PartNumber AND IS_ACTIVE = 1
										Order By MOD_DATE Desc
			
			IF NOT EXISTS (SELECT 1 FROM #PKG_Part_Mapping)
			BEGIN
				SET @ReturnValue = 'Packaging data is not available.'
				SET @ReturnInt = 1
				RETURN;
			END

			SELECT Row_No, col1 INTO #OldNewCustomerPartNumber FROM dbo.FN_GRID_SPLIT_STRING(@CustPartNumber,'','|')

			SELECT @OldCustomerPartNo = col1 FROM #OldNewCustomerPartNumber WHERE ROW_NO = 1
			SELECT @NewCustomerPartNo = col1 FROM #OldNewCustomerPartNumber WHERE ROW_NO = 2

			SELECT ProfitCenterCode,PartNo,CustomerPartNo,LabelDataName,LabelDataValue,Engraving,LabelPrinting,isActive,SeqNo,ENT_BY,ENT_STMP,UPD_BY,UPD_STMP
				INTO #Assy_Coupling_LabelInfo_Mst_Hist FROM Assy_Coupling_LabelInfo_Mst (NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode AND PartNo = @PartNumber AND isActive = 1 AND CustomerPartNo = @OldCustomerPartNo

			IF NOT EXISTS (SELECT 1 FROM #Assy_Coupling_LabelInfo_Mst_Hist)
			BEGIN
				SET @ReturnValue = 'Coupling data is not available.'
				SET @ReturnInt = 1
				RETURN;
			END
			
			--Coupling Data History and New Entry
			INSERT INTO Assy_Coupling_LabelInfo_Mst_History
			(
				ProfitCenterCode,PartNo,CustomerPartNo,LabelDataName,LabelDataValue,Engraving,LabelPrinting,isActive,SeqNo,ENT_BY,ENT_STMP,UPD_BY,UPD_STMP,HIS_ENT_BY,HIS_ENT_STMP
			)
			SELECT ProfitCenterCode,PartNo,CustomerPartNo,LabelDataName,LabelDataValue,Engraving,LabelPrinting,isActive,SeqNo,ENT_BY,ENT_STMP,UPD_BY,UPD_STMP,@UserId,GETDATE()
				FROM #Assy_Coupling_LabelInfo_Mst_Hist

			DELETE FROM Assy_Coupling_LabelInfo_Mst WHERE ProfitCenterCode = @ProfitCenterCode AND PartNo = @PartNumber AND CustomerPartNo = @OldCustomerPartNo

			INSERT INTO Assy_Coupling_LabelInfo_Mst
			(
				ProfitCenterCode,PartNo,CustomerPartNo,LabelDataName,LabelDataValue,Engraving,LabelPrinting,isActive,SeqNo,ENT_BY,ENT_STMP,UPD_BY,UPD_STMP
			)
			SELECT ProfitCenterCode,PartNo,@NewCustomerPartNo,LabelDataName,LabelDataValue,Engraving,LabelPrinting,isActive,SeqNo,@UserId,GETDATE(),@UserId,GETDATE()
				FROM #Assy_Coupling_LabelInfo_Mst_Hist

			SELECT PartNo,CustomerPartNo,GroupCode,CreatedBy,CreatedDate,ModifiedBy,ModifiedDate
				INTO #Assy_PRN_CustomerGroupMaster FROM Assy_PRN_CustomerGroupMaster
					WHERE PartNo = @PartNumber AND CustomerPartNo = @OldCustomerPartNo

			IF NOT EXISTS (SELECT 1 FROM #Assy_PRN_CustomerGroupMaster)
			BEGIN
				SET @ReturnValue = 'PRN Customer Group data is not available.'
				SET @ReturnInt = 1
				RETURN;
			END
			
			DELETE FROM Assy_PRN_CustomerGroupMaster WHERE PartNo = @PartNumber AND CustomerPartNo = @OldCustomerPartNo

			INSERT INTO Assy_PRN_CustomerGroupMaster
			(
				PartNo,CustomerPartNo,GroupCode,CreatedBy,CreatedDate,ModifiedBy,ModifiedDate
			)
			SELECT PartNo,@NewCustomerPartNo,GroupCode,@UserId,GETDATE(),@UserId,GETDATE()
				FROM #Assy_PRN_CustomerGroupMaster
			
			--Packaging Data History and New Entry
			INSERT INTO PKG_Part_Mapping_HISTORY
			(
				PKG_DEF_ID,WH_CODE,IS_STANDARD_PACKING,PART_NUMBER,PART_DESC,CUSTOMER_PART_NO,COUNTRY,CONTAINERTYPE,PACKAGE_TYPE_CODE,DISPATCH_TYPE,LOT_QTY,IS_LAYERED_PACKING,
				IS_SKID_LABEL,PKG_SERIAL_NO,NO_OF_LAYERS,ROWS_PER_LAYER,COLS_PER_LAYER,MODEL,Layer_Lbl_Prn,Skid_Lbl_Prn,CUST_ADDRESS1,CUST_ADDRESS2,CUST_ADDRESS3,CUST_ADDRESS4,
				IS_ACTIVE,ENT_DATE,ENT_BY,MOD_DATE,MOD_BY,TMC_Lbl_Prn,Servo_Lbl_Prn,Coupling_Lbl_Prn,ENTRY_DATE
			)
			SELECT PKG_DEF_ID,WH_CODE,IS_STANDARD_PACKING,PART_NUMBER,PART_DESC,CUSTOMER_PART_NO,COUNTRY,CONTAINERTYPE,PACKAGE_TYPE_CODE,DISPATCH_TYPE,LOT_QTY,IS_LAYERED_PACKING,
				IS_SKID_LABEL,PKG_SERIAL_NO,NO_OF_LAYERS,ROWS_PER_LAYER,COLS_PER_LAYER,MODEL,Layer_Lbl_Prn,Skid_Lbl_Prn,CUST_ADDRESS1,CUST_ADDRESS2,CUST_ADDRESS3,CUST_ADDRESS4,
					IS_ACTIVE,ENT_DATE,ENT_BY,MOD_DATE,@UserId,TMC_Lbl_Prn,Servo_Lbl_Prn,Coupling_Lbl_Prn,GETDATE()
						FROM #PKG_Part_Mapping

			UPDATE PKG_Part_Mapping SET IS_ACTIVE = 0, MOD_DATE = GETDATE(), MOD_BY = @UserId WHERE WH_CODE = @ProfitCenterCode AND PART_NUMBER = @PartNumber

			INSERT INTO PKG_Part_Mapping
			(
				WH_CODE,IS_STANDARD_PACKING,PART_NUMBER,PART_DESC,CUSTOMER_PART_NO,COUNTRY,CONTAINERTYPE,PACKAGE_TYPE_CODE,DISPATCH_TYPE,LOT_QTY,IS_LAYERED_PACKING,IS_SKID_LABEL,
				PKG_SERIAL_NO,NO_OF_LAYERS,ROWS_PER_LAYER,COLS_PER_LAYER,MODEL,Layer_Lbl_Prn,Skid_Lbl_Prn,CUST_ADDRESS1,CUST_ADDRESS2,CUST_ADDRESS3,CUST_ADDRESS4,IS_ACTIVE,
				ENT_DATE,ENT_BY,MOD_DATE,MOD_BY,TMC_Lbl_Prn,Servo_Lbl_Prn,Coupling_Lbl_Prn,CUSTOMER_CD,IS_PALLET_LABEL,PALLETSIZE,PALLET_LBL_PRN,IS_CUST_LBL_SCAN,PKG_SERIAL_NO_MANUAL
			)
			SELECT WH_CODE,IS_STANDARD_PACKING,PART_NUMBER,PART_DESC,@CustPartNumber,COUNTRY,CONTAINERTYPE,PACKAGE_TYPE_CODE,DISPATCH_TYPE,LOT_QTY,IS_LAYERED_PACKING,IS_SKID_LABEL,
				PKG_SERIAL_NO,NO_OF_LAYERS,ROWS_PER_LAYER,COLS_PER_LAYER,MODEL,Layer_Lbl_Prn,Skid_Lbl_Prn,CUST_ADDRESS1,CUST_ADDRESS2,CUST_ADDRESS3,CUST_ADDRESS4,IS_ACTIVE,
					GETDATE(),@UserId,GETDATE(),@UserId,TMC_Lbl_Prn,Servo_Lbl_Prn,Coupling_Lbl_Prn,CUSTOMER_CD,IS_PALLET_LABEL,PALLETSIZE,PALLET_LBL_PRN,IS_CUST_LBL_SCAN,PKG_SERIAL_NO_MANUAL
						FROM #PKG_Part_Mapping

			SET @ReturnValue = 'Success'
			SET @ReturnInt = 1
		END
		ELSE IF @CONDITION = 'UPDATE_CUSTOMER_PART_FOR_COUPLING_LOCAL'
		BEGIN
			SELECT Row_No, col1 INTO #OldNewCustomerPartNumber_Local FROM dbo.FN_GRID_SPLIT_STRING(@CustPartNumber,'','|')

			SELECT @OldCustomerPartNo = col1 FROM #OldNewCustomerPartNumber_Local WHERE ROW_NO = 1
			SELECT @NewCustomerPartNo = col1 FROM #OldNewCustomerPartNumber_Local WHERE ROW_NO = 2

			SELECT ProfitCenterCode,PartNo,CustomerPartNo,LabelDataName,LabelDataValue,Engraving,LabelPrinting,isActive,SeqNo,ENT_BY,ENT_STMP,UPD_BY,UPD_STMP
				INTO #Assy_Coupling_LabelInfo_Mst_Local FROM Assy_Coupling_LabelInfo_Mst (NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode AND PartNo = @PartNumber AND isActive = 1 AND CustomerPartNo = @OldCustomerPartNo

			DELETE FROM Assy_Coupling_LabelInfo_Mst WHERE ProfitCenterCode = @ProfitCenterCode AND PartNo = @PartNumber AND CustomerPartNo = @OldCustomerPartNo

			INSERT INTO Assy_Coupling_LabelInfo_Mst
			(
				ProfitCenterCode,PartNo,CustomerPartNo,LabelDataName,LabelDataValue,Engraving,LabelPrinting,isActive,SeqNo,ENT_BY,ENT_STMP,UPD_BY,UPD_STMP
			)
			SELECT
				ProfitCenterCode,PartNo,@NewCustomerPartNo,LabelDataName,LabelDataValue,Engraving,LabelPrinting,isActive,SeqNo,@UserId,GETDATE(),@UserId,GETDATE()
					FROM #Assy_Coupling_LabelInfo_Mst_Local
			
			SELECT PartNo,CustomerPartNo,GroupCode,CreatedBy,CreatedDate,ModifiedBy,ModifiedDate
				INTO #Assy_PRN_CustomerGroupMaster_Local FROM Assy_PRN_CustomerGroupMaster
					WHERE PartNo = @PartNumber AND CustomerPartNo = @OldCustomerPartNo

			IF NOT EXISTS (SELECT 1 FROM #Assy_PRN_CustomerGroupMaster_Local)
			BEGIN
				SET @ReturnValue = 'PRN Customer Group data is not available.'
				SET @ReturnInt = 1
				RETURN;
			END
			
			DELETE FROM Assy_PRN_CustomerGroupMaster WHERE PartNo = @PartNumber AND CustomerPartNo = @OldCustomerPartNo

			INSERT INTO Assy_PRN_CustomerGroupMaster
			(
				PartNo,CustomerPartNo,GroupCode,CreatedBy,CreatedDate,ModifiedBy,ModifiedDate
			)
			SELECT PartNo,@NewCustomerPartNo,GroupCode,@UserId,GETDATE(),@UserId,GETDATE()
				FROM #Assy_PRN_CustomerGroupMaster_Local
		END
		ELSE IF @CONDITION = 'FETCH_MAPPING_DATA_BORE_MIX_UP'
		BEGIN
			SELECT ProfitCenterCode, LineCode, Barcode, TSBarcode, MappedTimeStamp FROM Assy_BoreInspection_Result (NOLOCK)
				WHERE IsMapped = 1 AND ISNULL(IsSynced,0) = 0 AND ProfitCenterCode = @ProfitCenterCode
		END
		ELSE IF @CONDITION = 'UPDATE_MAPPING_DATA_BORE_MIX_UP_CENTRAL'
		BEGIN
			SELECT * INTO #Temp_BoreMixUpMappingCentralTable FROM @BoreMixUpMappingTable
			IF EXISTS (SELECT 1 FROM #Temp_BoreMixUpMappingCentralTable)
			BEGIN
				MERGE INTO Assy_BoreInspection_Result AS C
					USING #Temp_BoreMixUpMappingCentralTable AS L
						ON ISNULL(C.ProfitCenterCode,0) = ISNULL(L.ProfitCenterCode,0)	
							AND ISNULL(C.LineCode,0) = ISNULL(L.LineCode,0)
								AND ISNULL(C.Barcode,0) = ISNULL(L.Barcode,0)
						WHEN MATCHED THEN
							UPDATE SET
								C.IsMapped = 1, C.TSBarcode = L.TSBarcode, C.MappedTimeStamp = L.MappedTimeStamp, C.IsSynced = 1;

				SELECT ProfitCenterCode, LineCode, Barcode, TSBarcode, MappedTimeStamp FROM #Temp_BoreMixUpMappingCentralTable
			END
		END
		ELSE IF @CONDITION = 'UPDATE_MAPPING_DATA_BORE_MIX_UP_LOCAL'
		BEGIN
			SELECT * INTO #Temp_BoreMixUpMappingLocalTable FROM @BoreMixUpMappingTable
			IF EXISTS (SELECT 1 FROM #Temp_BoreMixUpMappingLocalTable)
			BEGIN
				MERGE INTO Assy_BoreInspection_Result AS L
					USING #Temp_BoreMixUpMappingLocalTable AS T
						ON ISNULL(T.ProfitCenterCode,0) = ISNULL(L.ProfitCenterCode,0)	
							AND ISNULL(T.LineCode,0) = ISNULL(L.LineCode,0)
								AND ISNULL(T.Barcode,0) = ISNULL(L.Barcode,0)
						WHEN MATCHED THEN
							UPDATE SET L.IsSynced = 1;
			END
		END
		ELSE IF @CONDITION = 'WIP_PENDING_PART'
		BEGIN
			SELECT * INTO #Assy_WIP_Pending_Part_Status FROM Assy_WIP_Pending_Part_Status (NOLOCK)
			WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND IsPrintUpdate = 0
			
			if exists( select top 1 1 from routingconfigdetails (NOLOCK) where 
		    ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode and KeyType='IsWIPPartManage' and keyvalue='1')
			Begin
				SELECT Top 1 @WIP_Part_Number = PartNo FROM #Assy_WIP_Pending_Part_Status
				IF ISNULL(@WIP_Part_Number,'') != ''
				BEGIN
					IF (@WIP_Part_Number != @PARTNUMBER)
					BEGIN
				    
						IF (@WIP_Part_Number != @PARTNUMBER)
						SET @ReturnValue = 'As per Last Tally Pending WIP Part Number - ' + @WIP_Part_Number + ' is different from selected Part - ' + @PARTNUMBER + '. Set Parameter can not be done.'
						SET @ReturnInt = 2
						RETURN;
					END
				end
			end
			
		    SELECT @WIP_Part_Count = COUNT(*) FROM #Assy_WIP_Pending_Part_Status where PartNo=@PARTNUMBER
			IF @WIP_Part_Count IS NULL
				SET @WIP_Part_Count = 0
			--@PASSQTY is current planned Qty
			IF @PASSQTY < ISNULL(@WIP_Part_Count,0)
			BEGIN
				SET @ReturnValue = 'Pending WIP Part Number count - ' + CONVERT(VARCHAR,@WIP_Part_Count) + ' is more than the selected Qty ' + CONVERT(VARCHAR,@PASSQTY) + '. Set Parameter can not be done.'
				SET @ReturnInt = 2
				RETURN;
			END

			SELECT @PRINT_QTY = @PASSQTY - ISNULL(@WIP_Part_Count,0)
			UPDATE Assy_WIP_Pending_Part_Status SET IsPrintUpdate = 1 WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			SET @ReturnValue = 'Pending WIP Part Number count is - ' + CONVERT(VARCHAR,@WIP_Part_Count) + '. You can print only ' + CONVERT(VARCHAR,@PRINT_QTY)
			SET @ReturnInt = 1
			SELECT ISNULL(@WIP_Part_Count,0) WIP_Part_Count
			RETURN;
			
			
		END
		ELSE IF @CONDITION = 'UPDATE_WIP_PRINT_COUNT'
		BEGIN
			IF ISNULL(@PASSQTY,0) > 0
			BEGIN
				IF EXISTS
				(
					SELECT 1 FROM Assy_Barcode_Printed_Counter (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
				)
				BEGIN
					UPDATE Assy_Barcode_Printed_Counter SET PrintedQty = ISNULL(PrintedQty,0) + ISNULL(@PASSQTY,0), Timestamp = GETDATE()
						WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND CurrentPlannedQty > ISNULL(PrintedQty,0)
				END
				ELSE
				BEGIN
					INSERT INTO Assy_Barcode_Printed_Counter(ProfitCenterCode,LineCode,Datecode,ProductionOrderNo,PartNo,CurrentPlannedQty,PrintedQty,Timestamp)
					SELECT ProfitCenterCode,LineCode,Datecode,ProductionOrderNo,Assy_PartNo,CurrentPlannedQty,ISNULL(@PASSQTY,0),GETDATE()
						FROM Assy_RunningPart(NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
				END

				UPDATE Assy_RunningPart SET PrintedQty = ISNULL(PrintedQty,0) + ISNULL(@PASSQTY,0) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			END
			SELECT @PRINT_QTY = PrintedQty FROM Assy_RunningPart (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			SET @ReturnValue = CONVERT(VARCHAR,@PRINT_QTY)
			SET @ReturnInt = 1
			RETURN;
		END
		else if @CONDITION='GetFlashMsgStatus'
		Begin

			select top 1 MSG_CD,MSG_TEXT,MsgShow_sts from assy_flashmsg_status with(Nolock) where MsgShow_sts='1'

		End
		ELSE IF @CONDITION = 'Get_Sync_Value'
		Begin
		Declare @Sync_value int = 0

		Select @Sync_value= isnull(ATTRB_VAL,0) from TYPE_DEFINITION_XREF_DATA (NOLOCK) where TYPE_CD ='Is_Allow_Station_Aftr_FV' 
		and WH_CODE = @ProfitCenterCode AND ATTRB_CD = @LineCode
		if(@Sync_value = 1)
		Begin
		SET @ReturnValue ='Success'
		SET @ReturnInt = 1
		End
		else
		Begin 
		SET @ReturnValue ='Fail'
		SET @ReturnInt = 0
		End
		
		End
		ELSE IF @CONDITION = 'Get_Operation_Machine_Value'
		Begin
		Select ATTRB_VAL from TYPE_DEFINITION_XREF_DATA where TYPE_CD ='fvnextstatiomachinecode' 
		and WH_CODE = @ProfitCenterCode AND ATTRB_CD = @LineCode
		Select  ATTRB_VAL from TYPE_DEFINITION_XREF_DATA where TYPE_CD ='fvnextstationoperationcode' 
		and WH_CODE = @ProfitCenterCode AND ATTRB_CD = @LineCode
		End
		
		ELSE IF @CONDITION = 'BarcodeData_AssyStatus_Running'
		BEGIN
		
		Select * from Assy_lineAssyStatus_running(NOLOCK) where MachineCode =@MachineCode and OperationCode =@OperationCode
		order by ResultTimestamp desc
		
		End
		ELSE IF @CONDITION = 'Get_Reservoir_Mapping_OperationCode'
		Begin
		    SELECT @IS_RESERVOIR_LINE =  DBO.[FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE](@ProfitCenterCode,'LINE_ATTRB','IS_RESERVOIR_LINE',@LineCode,'')
			Insert into #tblOPCode(Row_No, col1)
			SELECT Row_No, col1  FROM dbo.FN_GRID_SPLIT_STRING(DBO.[FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE]('0021','LINE_ATTRB','RESERVOIR_OPERATION_CODE',@LINECODE,''),'','|')
			SELECT @GET_RESERVOIR_PART=  DBO.[FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE](@ProfitCenterCode,'PART_ATTRB','RESERVOIR_PART_NUMBER',@ASSY_PARTNO,'')						
			select ltrim(rtrim(@IS_RESERVOIR_LINE)), col1,@GET_RESERVOIR_PART from #tblOPCode
		End
		ELSE 
		IF @CONDITION = 'Reset_Reservoir_Data'
		Begin
		
			Insert into #tblOPCode(Row_No, col1)
			SELECT Row_No, col1  FROM dbo.FN_GRID_SPLIT_STRING(DBO.[FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE]('0021','LINE_ATTRB','RESERVOIR_OPERATION_CODE',@LINECODE,''),'','|')
			
			--update Assy_Scan_OK set Barcode='' , isScan='' where operationcode in (select col1 from #tblOPCode )

			--delete from Assy_CustomerBarcode_Scan_Validation where LineCode=@LINECODE and ProfitCenterCode=@PROFITCENTERCODE and GroupCode='RESERVOIR'

		End
		
		 
	else if @CONDITION='Move_Data'
    BEGIN

    BEGIN TRAN
    INSERT INTO Assy_LineAssyStatus
		(
			ProfitCenterCode, 
			LineCode, 
			MachineCode, 
			OperationCode, 
			StationCode, 
			Barcode, 
			Status, 
			FailCount, 
			DateCode, 
			PartNo, 
			ScanTimeStamp, 
			ResultTimeStamp, 
			Active, 
			UserID, 
			IsTallyChartApproved,
			ProductionOrderNo,
			PROD_LOT_NO, 
			Live_Datecode,
			IsReworkPart
		)
		
		SELECT 
			ALR.ProfitCenterCode, 
			ALR.LineCode, 
			ALR.MachineCode, 
			ALR.OperationCode, 
			ALR.StationCode, 
			ALR.Barcode, 
			ALR.Status, 
			ALR.FailCount, 
			ALR.DateCode, 
			ALR.PartNo, 
			ALR.ScanTimeStamp, 
			ALR.ResultTimeStamp, 
			ALR.Active, 
			ALR.UserID, 
			ALR.IsTallyChartApproved,
			ALR.ProductionOrderNo,
			ALR.PROD_LOT_NO ,
			ALR.Live_Datecode,
			ALR.IsReworkPart
		FROM Assy_LineAssyStatus_Running ALR (NOLOCK) RIGHT JOIN @P_DataTable DT 
		ON ALR.Barcode=DT.Barcode 
		where ALR.Barcode=DT.Barcode and ALR.MachineCode=DT.MachineCode
		and ALR.OperationCode=DT.OperationCode
		DELETE  Assy_LineAssyStatus_Running WHERE Barcode IN (
		SELECT Barcode from @P_DataTable) and MachineCode IN (SELECT MachineCode from @P_DataTable)


		INSERT INTO Assy_LineAssyParamData
		(
			[ProfitCenterCode]
			, [LineCode]
			, [MachineCode]
			, [OperationCode]
			, [StationCode]
			, [Barcode]
			, [TagName]
			, [Value]
			, [Result]
			, [DateCode]
			, [UserID]
			, [TimeStamp]
			, PartNo
			, UID
			, ScanTimeStamp
			, CaliperDatecode
			, CaliperSrNo
			,Live_Datecode
		)
		SELECT
			  APR.[ProfitCenterCode]
			, APR.[LineCode]
			, APR.[MachineCode]
			, APR.[OperationCode]
			, APR.[StationCode]
			, APR.[Barcode]
			, APR.[TagName]
			, APR.[Value]
			, APR.[Result]
			, APR.[DateCode]
			, APR.[UserID]
			, APR.[TimeStamp]
			, APR.PartNo
			, APR.UID
			, APR.ScanTimeStamp
			, APR.CaliperDatecode
			, APR.CaliperSrNo
			, APR.Live_Datecode
		FROM Assy_LineAssyParamData_Running  APR (NOLOCK) RIGHT JOIN @P_DataTable DT 
		ON APR.Barcode=DT.Barcode 
		where APR.Barcode=DT.Barcode and APR.MachineCode=DT.MachineCode
		and APR.OperationCode=DT.OperationCode

		--INSERT INTO Assy_LineAssyParamData_Running_Dtl(UID)
		--SELECT DISTINCT [UID] FROM  Assy_LineAssyParamData_Running where MachineCode ='MCDF' and OperationCode ='OCDF'
											
		--DELETE Assy_LineAssyParamData_Running WHERE  MachineCode ='MCDF' and OperationCode ='OCDF'
		
			--Assy_LineAssyStatus_Running -> Assy_LineAssyStatus
			--Assy_LineAssyParamData_Running --> Assy_LineAssyParamData
			--Assy_LineAssyParamData_Running_Dtl --> Assy_LineAssyParamData_Dtl
        --INSERT INTO #Temp_Assy_LineAssyParamData_Running_Dtl
		--SELECT DISTINCT [UID] FROM  Assy_LineAssyParamData_Running ALPRD Right JOIN @P_DataTable DT
		--ON ALPRD.Barcode = DT.Barcode 
		--Where ALPRD.Barcode=DT.Barcode and ALPRD.MachineCode=DT.MachineCode
		--and ALPRD.OperationCode=DT.OperationCode

	   -- WHERE Barcode IN (
		--SELECT Barcode from @P_DataTable) and MachineCode IN (SELECT MachineCode from @P_DataTable)

		
        INSERT INTO dbo.[Assy_LineAssyParamData_Dtl] 
		(UID, 
		TagId,
		Value,
		Timestamp, 
		SyncTimeStamp, 
		IsSyncDone)
		
		Select
		UID, 
		TagId,
		Value,
		Timestamp, 
		SyncTimeStamp, 
		IsSyncDone 

		From ASSY_LINEASSYPARAMDATA_RUNNING_DTL where UID IN( SELECT DISTINCT [UID] FROM  Assy_LineAssyParamData_Running ALPRD Right JOIN @P_DataTable DT
		ON ALPRD.Barcode = DT.Barcode 
		Where ALPRD.Barcode=DT.Barcode and ALPRD.MachineCode=DT.MachineCode
		and ALPRD.OperationCode=DT.OperationCode)

		
		--ALPRD  Right Join #Temp_Assy_LineAssyParamData_Running_Dtl TMP
		--ON ALPRD.UID = TMP.UID where ALPRD.UID = TMP.UID
		--where UID in (select UID from #Temp_Assy_LineAssyParamData_Running_Dtl)

		DELETE  Assy_LineAssyParamData_Running WHERE Barcode IN (
		SELECT Barcode from @P_DataTable) and MachineCode IN (SELECT MachineCode from @P_DataTable)
	    COMMIT TRAN;
		
   END 

		ELSE IF @CONDITION = 'GET_RUNNING_PART_TYPE'
		BEGIN
			SELECT @ReturnValue = PartType FROM Assy_RunningPart (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			IF ISNULL(@ReturnValue,'') = ''
				SET @ReturnValue = ''
			SET @ReturnInt = 1
		END
		else if @CONDITION='ResetFlashMsgStatus' -- Added BY Sachin 07Oct2020
		Begin
			update assy_flashmsg_status set MsgShow_sts='0'
		End
		ELSE IF(@CONDITION = 'AUTO_FV_MACHINE_CODE') -- Added BY Sachin 07Oct2020
		BEGIN
			DECLARE @AutoFVMachineCode varchar(10) = 0

			SELECT @AutoFVMachineCode = DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE','IsAutoFVMachineCode',@LINECODE,@PROFITCENTERCODE)
			SET @RETURNVALUE = ISNULL(@AutoFVMachineCode,'')			
		END
		/* Printer Name is required based on PRN Group
		ELSE IF @CONDITION = 'GET_PRINTER_VAL'
		BEGIN
		   SELECT TOP 1 @PARTNUMBER = ISNULL(Assy_PartNo,'')
				FROM Assy_RunningPart(NOLOCK)
		   WHERE ProfitCenterCode = @PROFITCENTERCODE and LineCode = @LINECODE

		   IF @PARTNUMBER != ''
		   BEGIN
			SELECT @RETURNVALUE = ISNULL(DBO.FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE(@PROFITCENTERCODE,@P_TYPE_CATEGORY_CD,@P_TYPE_CD,@PARTNUMBER,''),'')
		   END
		END
		*/
		ELSE IF @CONDITION='GET_LINE_CONFIG'
		BEGIN		
				
				select ROW_NUMBER() over (order by rl.OperationSeqNo) id,lt.LineTypeName,rl.RECIPE,rl.OPERATIONSEQNO,rl.OperationCode,
				rl.MachineCode,m.MachineName ,
				m.INDEXPERSTATIONS  , l.VALIDATE_DATECODE,l.ISPOKAYOKEMANDATORY,rl.POKA_YOKE_ALLOWED,l.ISMATFEEDREQUIRED,
				rl.LABELPRINTING,rl.OperationCode as PreOC,rl.MachineCode as PreMC, m.MachineName as 'PreMachineName',m.NOOFSTATIONS,
				isnull(l.IS2PARTSFIFO,0) as IS2PARTSFIFO
				into #TEMp_LINE_CONFIG__
				from LineMst(nolock) l 
				inner join LineTypeMst(nolock) lt on l.profitcenterCode= lt.profitcenterCode
				and l.lineTypeCode=lt.LineTypeCode 
				inner join ROUTINGCONFIGLINEWISE (NOLOCK) rl on l.profitcenterCode= rl.profitcenterCode
				AND l.LINECODE = rl.LINECODE 
				inner join MachineMst (nolock) m on l.profitcenterCode= m.profitcenterCode
				and  rl.MachineCode=m.MachineCode
				where l.LineCode=@LINECODE and l.profitcenterCode=@PROFITCENTERCODE
				AND ISNULL(rl.TRACEABILITY,0) =1 and ISNULL(rl.OperationRequired,0) =1

				if(ISNULL(@PARTNUMBER,'') != '' )
				begin							  
					delete a from #TEMp_LINE_CONFIG__ a
					inner join ROUTINGCONFIGPARTWISE(nolock) p on a.MachineCode =p.MachineCode
					and a.OperationCode = p.OperationCode
					where p.profitcenterCode=@PROFITCENTERCODE
					AND ISNULL(p.TRACEABILITY,0) =0 and ISNULL(p.OperationRequired,0) =0 
					AND PartNo=@PARTNUMBER
				end
				
				select ROW_NUMBER() over (order by id) as id,LineTypeName,RECIPE,OPERATIONSEQNO,OperationCode,
				MachineCode,MachineName,INDEXPERSTATIONS,VALIDATE_DATECODE,ISPOKAYOKEMANDATORY,POKA_YOKE_ALLOWED,ISMATFEEDREQUIRED,
				LABELPRINTING,PreOC,PreMC, PreMachineName,NOOFSTATIONS,IS2PARTSFIFO
				into #TEMp_LINE_CONFIG_
				from #TEMp_LINE_CONFIG__

				update a set a.preOC = b.preOC, a.preMC = b.preMC , a.PreMachineName = b.PreMachineName
				from #TEMp_LINE_CONFIG_ a inner join
				#TEMp_LINE_CONFIG_ b on a.id = (b.id + 1)

				select LineTypeName,RECIPE,OPERATIONSEQNO,OperationCode,MachineCode,MachineName ,
				INDEXPERSTATIONS  , VALIDATE_DATECODE,ISPOKAYOKEMANDATORY,POKA_YOKE_ALLOWED,ISMATFEEDREQUIRED,
				LABELPRINTING,PreOC,PreMC,PreMachineName,NOOFSTATIONS,IS2PARTSFIFO from #TEMp_LINE_CONFIG_ order by id

		END
		ELSE IF(@CONDITION='GET_DATA_REF_DATA')
		BEGIN
			IF(@P_TYPE_CATEGORY_CD = 'LINE_ATTRB')
				SELECT @RETURNVALUE = ISNULL(DBO.FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE(@PROFITCENTERCODE,@P_TYPE_CATEGORY_CD,@P_TYPE_CD,@LINECODE,''),'')
			ELSE IF(@P_TYPE_CATEGORY_CD = 'PART_ATTRB')
				SELECT @RETURNVALUE = ISNULL(DBO.FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE(@PROFITCENTERCODE,@P_TYPE_CATEGORY_CD,@P_TYPE_CD,@PARTNUMBER,''),'')
		END
		
		ELSE IF @CONDITION='GET_PART_FORM_BARCODE'  
		BEGIN
			SELECT TOP 1 @PARTNUMBER=PARTNO FROM ASSY_LINEASSYSTATUS_RUNNING (NOLOCK)  
			WHERE Barcode = @BARCODE AND LineCode = @LINECODE AND ProfitCenterCode = @PROFITCENTERCODE AND OperationCode = 'OCIG'

			IF(RTRIM(ISNULL(@PARTNUMBER,'')) = '')
			BEGIN
				SELECT TOP 1 @PARTNUMBER=PARTNO FROM ASSY_LINEASSYSTATUS (NOLOCK)  
				WHERE Barcode = @BARCODE AND LineCode = @LINECODE AND ProfitCenterCode = @PROFITCENTERCODE AND OperationCode = 'OCIG'
			END

			SELECT @PARTNUMBER AS PART_NUMBER

			SET @RETURNINT=1  
			SET @RETURNVALUE='SUCCESS'  
			RETURN
		END  

		ELSE IF @CONDITION='SetPartNo_ASSY_MACHINEWISE_RUNNINGPART'
		BEGIN	
			IF ISNULL( @ALLOW2PARTS,0)=1
			BEGIN
				IF EXISTS
				( 
						SELECT 1 FROM ASSY_MACHINEWISE_RUNNINGPART WITH(NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
						AND OPERATIONCODE = @OPERATIONCODE
				)
				BEGIN
						UPDATE ASSY_MACHINEWISE_RUNNINGPART SET PARTNO = @PARTNUMBER,UPDATEDDATE=GETDATE() 
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE	AND OPERATIONCODE =@OPERATIONCODE
				END
				ELSE 
				BEGIN
					INSERT INTO ASSY_MACHINEWISE_RUNNINGPART(PROFITCENTERCODE,LINECODE,OPERATIONCODE,MACHINECODE ,PARTNO,CREATEDDATE)
					SELECT @PROFITCENTERCODE,@LINECODE,@OPERATIONCODE,@MACHINECODE,@PARTNUMBER,GETDATE()
				END
				SELECT @PARTNUMBER AS PART_NUMBER
			END
		END

		ELSE IF(@CONDITION = 'GetBV_ProcessTime')
		BEGIN
			SELECT @BorePassFailLimit = dbo.ASSY_FN_GET_PARAMETER_VALUE('AssLine', @LineCode, 'BV_ProcessTime', @PROFITCENTERCODE)
			SELECT isnull(@BorePassFailLimit,0) BV_ProcessTime
		END

		ELSE IF (@CONDITION ='ENABLE_DISABLE_ROBO_VISION')
		BEGIN
			IF EXISTS(	SELECT * FROM TYPE_DEFINITION_XREF_DATA (NOLOCK) WHERE WH_CODE=@PROFITCENTERCODE AND ATTRB_CD=@LINECODE and TYPE_CATEGORY_CD='LINE_ATTRB'
						and STS_CD=0 AND ATTRB_VAL != ''AND TYPE_CD = 'ROBO_VISION_ON_OFF')
			BEGIN
				
					IF(@KEYTYPE = 'UPDATE')
					BEGIN
						BEGIN TRY 

							SET @EXECQUERY = 'UPDATE '+@LINKSERVERNAME+'.dbo.TYPE_DEFINITION_XREF_DATA SET ATTRB_VAL ='''+convert(varchar(10),@STATUS)+''' WHERE WH_CODE = '''+ @PROFITCENTERCODE + '''
								AND ATTRB_CD = '''+ @LINECODE + ''' AND TYPE_CATEGORY_CD = ''LINE_ATTRB'' AND STS_CD = 0 AND TYPE_CD = ''ROBO_VISION_ON_OFF'''																
							EXEC (@EXECQUERY)							

						END TRY	
						BEGIN CATCH

							SET @RETURNVALUE = 	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
							CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
							CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
							CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
							CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
							CAST(ERROR_MESSAGE() AS VARCHAR(1500))

							SELECT 'Kindly Check, Not Able To Connect Central Server !!! '+@LINKSERVERNAME AS STATUS,'FAIL'	AS RESULT				
							RETURN
						END CATCH

						UPDATE TYPE_DEFINITION_XREF_DATA SET ATTRB_VAL = @STATUS WHERE WH_CODE=@PROFITCENTERCODE AND ATTRB_CD=@LINECODE and TYPE_CATEGORY_CD='LINE_ATTRB'
						and STS_CD=0 AND TYPE_CD = 'ROBO_VISION_ON_OFF'

						SELECT 'OK'AS STATUS,'SUCCESS' AS RESULT
						RETURN
					END
					ELSE IF (@KEYTYPE = 'CHECKED')
					BEGIN
								
						SELECT RoboKey AS STATUS,'CHECKED_SUCCESS' AS RESULT  from #Temp_RoboKey
						RETURN
					END
				 ELSE 
				 BEGIN	
				  SELECT 'FAIL' AS STATUS,'KEYNOT' AS RESULT
				  RETURN
				 END
		    END
			BEGIN	
			 SELECT 'FAIL' AS STATUS,'KEYNOT'AS RESULT
			 RETURN
			END
	    END	

		/*
		Comment Start: Imdadul Rehmaan
		Case: To get the robo buffer count
		*/
		ELSE IF (@CONDITION='ROBO_BUFFER_COUNT')
		BEGIN 
			   select A.Timestamp [Scan Timestamp], B.CaliperDatecode as [Caliper Datecode], B.SerialNo as [Caliper Serial No.],A.Barcode [RFID],B.PRINTED_BARCODE [2D barcode],B.ent_stamp [Printed timestamp],0 as[Fail Count],A.MachineCode
			   into #temp_robo_BufferDetails from 
			   Assy_Scan_OK_ROBO A with(nolock) inner join ASSY_FV_ROBOT_INSPECTION_SERIAL_HOLD B 
			   with(nolock) on A.Barcode=B.Rfid where ProfitCenterCode=@PROFITCENTERCODE and LineCode=@LINECODE  
 
			   update A set A.[Fail Count]=B.FailCount from  #temp_robo_BufferDetails A inner join Assy_LineAssyStatus_Running B with(nolock) 
			   on A.RFID=B.barcode and B.MachineCode=A.MachineCode
 
			   select ROW_NUMBER()OVER(ORDER BY  [Scan Timestamp]) [Sr.No.],[Caliper Datecode],[Caliper Serial No.],[RFID],[2D barcode],[Printed timestamp],[Scan Timestamp],[Fail Count] from #temp_robo_BufferDetails order by [Scan Timestamp] desc
		End	
		/*
		Comment End: Imdadul Rehmaan
		Case: To get the robo buffer count
		*/
		ELSE IF (@CONDITION='UPDATE_SCAN_OK_FLG_MANUAL')
		BEGIN
			IF  @PROFITCENTERCODE in ('0088','0064')
			BEGIN
				print 'na'
			END
			ELSE IF @PROFITCENTERCODE in ('0018','0030','0068')
			BEGIN
				EXEC ASSY_PROC_FINALVIEWING_ABS @CONDITION='UPDATE_SCAN_OK_FLG_MANUAL',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE
				,@MACHINECODE=@MACHINECODE,@OPERATIONCODE=@OPERATIONCODE,@BARCODE=@BARCODE,@USERID=@USERID
				,@STATIONCODE=@STATIONCODE,@SUBSTNMACHINECODE=@SUBSTNMACHINECODE,@SUBSTNOPERATIONCODE=@SUBSTNOPERATIONCODE
				,@P_EKanbanAllowed=@P_EKanbanAllowed,@RETURNINT=@RETURNINT OUT,@RETURNVALUE=@RETURNVALUE OUT
				RETURN
			END
		END
		ELSE IF @CONDITION = 'VALIDATE_THROUGHPUT_TIME'
		BEGIN
			IF  @PROFITCENTERCODE in ('0088','0064')
			BEGIN
				print 'na'
			END
			ELSE IF @PROFITCENTERCODE in ('0018','0030','0068')
			BEGIN
				EXEC ASSY_PROC_FINALVIEWING_ABS @CONDITION='VALIDATE_THROUGHPUT_TIME',@PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE
				,@BARCODE=@BARCODE,@USERID=@USERID,@STATIONCODE=@STATIONCODE,@ThroughputTime=@ThroughputTime
				,@RETURNINT=@RETURNINT OUT,@RETURNVALUE=@RETURNVALUE OUT
				RETURN
			END
		END
		ELSE IF (@CONDITION='QUEUETIME_APPROVE')
		BEGIN		
			SELECT Row_No, col1 AS Barcode INTO #QueueBars FROM dbo.FN_GRID_SPLIT_STRING(@Assy_str,'',',')

			ALTER TABLE #QueueBars
			ADD MachineCode VARCHAR(10), NextMC VARCHAR(10), IsReoffer bit, QueStatus tinyint

			UPDATE A SET A.MachineCode=B.MachineCode, A.NextMC=B.NextMachineCode, A.IsReoffer=C.IsReoffer			--NEED PREV STN FOR REOFFER
			FROM #QueueBars A INNER JOIN ASSY_LINEQUEUETIME_RUNNING B WITH (NOLOCK) ON A.Barcode=B.Barcode
			INNER JOIN RoutingConfigLineWise C WITH (NOLOCK) ON  B.OperationCode=C.OperationCode
			AND B.MachineCode=C.MachineCode AND B.LineCode=C.LineCode
			WHERE B.LineCode=@LINECODE AND B.ProfitCenterCode=@PROFITCENTERCODE

			UPDATE #QueueBars SET QueStatus = CASE WHEN IsReoffer=1 THEN 3 ELSE 2 END

			IF EXISTS (SELECT TOP 1 1 FROM #QueueBars WHERE IsReoffer=1)
			Begin
				IF NOT EXISTS
				(
					SELECT 1 FROM ASSY_LINE_CRIMPING_RETEST_STATUS A WITH (NOLOCK) 
					INNER JOIN #QueueBars B ON A.Barcode=B.Barcode AND A.MachineCode=B.MachineCode
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND ISNULL(ISRETEST, 0) = 0
				)
				BEGIN
					INSERT INTO ASSY_LINE_CRIMPING_RETEST_STATUS(PROFITCENTERCODE, LINECODE, MACHINECODE, BARCODE, TIMESTAMP, ISRETEST, REMARK)
					SELECT @PROFITCENTERCODE, @LINECODE, MachineCode, Barcode, GETDATE(), 0, 'Retest,Quarantine Part Approved on '+NextMC
					FROM #QueueBars WHERE IsReoffer=1
				END
			END

			UPDATE A SET QuarantineStatus=B.QueStatus, QuarantineApproveTimestamp=GETDATE(), QuarantineApproveByUser=@USERID, QuarantineRemarks=@Remark
			FROM ASSY_LINEQUEUETIME_RUNNING (NOLOCK) A
			INNER JOIN #QueueBars B ON A.Barcode=B.Barcode
			WHERE A.ProfitCenterCode=@PROFITCENTERCODE AND A.LineCode=@LINECODE 
			--AND A.Barcode=@BARCODE 
			--AND A.NextMachineCode=@OPERATIONCODE		--PREV, WHERE IT INSERTED WHEN RESULT CAME

			IF @@ROWCOUNT > 0
			BEGIN
				SET @RETURNINT=1  
				SET @RETURNVALUE='SUCCESS'  
			END
		END
		ELSE IF (@CONDITION='QUEUETIME_BREAK_START')
		BEGIN
			INSERT INTO ASSY_BREAK_TIME (ProfitCenterCode,LineCode,Datecode,PartNo,BreakStartByUser,BreakStartTime)
			OUTPUT INSERTED.BreakID,'BreakID' INTO @OUT_TABLE (ID,VAL)
			VALUES (@PROFITCENTERCODE,@LINECODE,@DATECODE,'',@USERID,GETDATE())

			IF @@ROWCOUNT > 0
			BEGIN
				SELECT TOP 1 @RETURNVALUE=CONVERT(VARCHAR,ID) FROM @OUT_TABLE WHERE VAL='BreakID' ORDER BY ID DESC

				UPDATE ASSY_LINEQUEUETIME_RUNNING SET BreakID=ISNULL(BreakID,'') + @RETURNVALUE + ','
				WHERE ProfitCenterCode=@PROFITCENTERCODE AND LineCode=@LINECODE AND QuarantineStatus='0'
				
				SET @RETURNINT=1
			END
		END
		ELSE IF (@CONDITION='QUEUETIME_BREAK_END')
		BEGIN
			UPDATE ASSY_BREAK_TIME SET BreakEndByUser=@USERID,BreakEndTime=GETDATE()
			OUTPUT INSERTED.BreakID,'BreakID' INTO @OUT_TABLE (ID,VAL)
			WHERE ProfitCenterCode=@PROFITCENTERCODE AND LineCode=@LINECODE --AND PartNo=@PARTNUMBER
			AND BreakEndTime IS NULL
			IF @@ROWCOUNT > 0
			BEGIN
				SELECT TOP 1 @RETURNVALUE=CONVERT(VARCHAR,ID) FROM @OUT_TABLE WHERE VAL='BreakID' ORDER BY ID DESC
				SET @RETURNINT=1
			END
		END
		ELSE IF (@CONDITION='QUEUETIME_BREAK_STATUS')
		BEGIN
			SELECT TOP 1 BreakID, PartNo FROM ASSY_BREAK_TIME (NOLOCK)
			WHERE ProfitCenterCode=@PROFITCENTERCODE AND LineCode=@LINECODE
			AND BreakEndTime IS NULL

			SET @RETURNINT=1
			SET @RETURNVALUE='SUCCESS'
		END

		ELSE IF (@CONDITION='GET_QUEUE_RUNNING_MACHINES')
		BEGIN
			SELECT DISTINCT A.PartNo PartNo, A.MachineCode MachineCode, A.OperationSeqNo OperationSeqNo,
			O.OperationCode OperationCode, O.OperationName OperationName
			FROM RoutingConfigPartWise A WITH (NOLOCK)
			INNER JOIN ASSY_LINEQUEUETIME_RUNNING B WITH (NOLOCK) ON A.PartNo=B.PartNo
			INNER JOIN OperationMst O WITH (NOLOCK) ON A.OperationCode=O.OperationCode
			--AND A.MachineCode=B.MachineCode
			WHERE A.ProfitCenterCode=@PROFITCENTERCODE AND B.LineCode=@LINECODE AND A.Traceability=1
			ORDER BY A.PartNo, OperationSeqNo ASC

			SET @RETURNINT=1
			SET @RETURNVALUE='SUCCESS'
		END

		ELSE IF (@CONDITION='GET_QUEUE_DETAIL_DATA')
		BEGIN
		BEGIN TRY
			SELECT DISTINCT     
				A.MachineCode, 
				A.OperationCode,
				A.OperationSeqNo, 
				O.OperationName,
				A.QueueTime
			INTO #ROUTING_QUEUE 
			FROM OperationMst O WITH (NOLOCK) 
			INNER JOIN RoutingConfigPartWise A ON O.OperationCode = A.OperationCode 
			--INNER JOIN ASSY_LINEQUEUETIME_RUNNING B WITH (NOLOCK) 
			--ON A.OperationCode = B.NextOperationcode
			WHERE A.PartNo = @PARTNUMBER 
			AND A.Traceability = 1

			--SELECT * FROM #ROUTING_QUEUE

			SELECT * INTO #QUEUE_RUNNING FROM ASSY_LINEQUEUETIME_RUNNING WITH (NOLOCK) WHERE 
			ProfitCenterCode = @PROFITCENTERCODE AND LineCode = @LINECODE 
			AND PartNo = @PARTNUMBER 

			--SELECT * FROM #QUEUE_RUNNING

			SELECT 
				A.Barcode,
				A.NextMachineCode AS MachineCode,
				A.NextOperationcode AS OperationCode,
				B.OperationName AS Machine,		--op name as machine
				CONVERT(VARCHAR(150),ISNULL(A.NextScanTimestamp,GETDATE()), 120) AS [Scan Time],
				--ISNULL(A.NextScanTimestamp, GETDATE()) AS [Scan Time],
				A.MachineCode AS [PrevMachineCode],
				A.OperationCode AS [PrevOperationCode],
				C.OperationName AS [Previous Operation],
				--A.Result AS [Prev. Result],
				ISNULL(CONVERT(VARCHAR(150),A.ResultTimestamp, 120),'') AS [Prev. Result],
				CASE
					WHEN ISNULL(A.QuarantineStatus,'0') = '0' THEN 'Running'
					WHEN ISNULL(A.QuarantineStatus,'0') = '1' THEN 'Quarantined'
					WHEN ISNULL(A.QuarantineStatus,'0') = '2' THEN 'Approved'
				END AS [Queue Status],
				DATEDIFF(SECOND, A.ResultTimestamp, ISNULL(A.NextScanTimestamp,ISNULL(A.QuarantineTimeStamp,GETDATE()))) AS [QueueTime],
				CONVERT(varchar(20), DATEDIFF(SECOND, A.ResultTimestamp, ISNULL(A.NextScanTimestamp,ISNULL(A.QuarantineTimeStamp,GETDATE())))) + ' ('+  Convert(varchar(20), B.QueueTime) + ')' AS [Queue Time],
				ISNULL(CONVERT(VARCHAR(150),A.QuarantineTimeStamp, 120),'') AS [Quarantined On],
				A.AssyUser,
				ISNULL(A.QuarantineApproveByUser,'') AS Approver,
				ISNULL(A.QuarantineRemarks, '') AS Remarks
			INTO #QUEUE_TIME_RESULT
			FROM #QUEUE_RUNNING A
			LEFT JOIN #ROUTING_QUEUE B 
				ON A.NextMachineCode = B.MachineCode 
				AND A.NextOperationcode = B.OperationCode
			LEFT JOIN #ROUTING_QUEUE C 
				ON A.MachineCode = C.MachineCode 
				AND A.OperationCode = C.OperationCode
			WHERE (@MACHINECODE = 'All' OR A.NextMachineCode = @MACHINECODE)
			--AND NOT EXISTS (
			--	SELECT 1
			--	FROM #QUEUE_RUNNING r2
			--	WHERE r2.Barcode = A.Barcode
			--		AND ISNULL(r2.NextScanTimestamp, ISNULL(r2.QuarantineTimeStamp, GETDATE())) 
			--		> ISNULL(A.NextScanTimestamp, ISNULL(A.QuarantineTimeStamp, GETDATE()))
			--)

			IF @Assy_str='Quarantine'
			BEGIN
				SELECT Barcode, MachineCode, OperationCode, Machine, [Scan Time], [PrevMachineCode], [PrevOperationCode], [Previous Operation], [Prev. Result],
				[Queue Status],[QueueTime], [Queue Time], [Quarantined On], AssyUser--, Approver 
				FROM #QUEUE_TIME_RESULT 
				WHERE [Queue Status] = 'Quarantined'
				ORDER BY [MachineCode], [Scan Time] DESC;
			END
			ELSE
			BEGIN
				SELECT Barcode, MachineCode, OperationCode, Machine, [Scan Time], [PrevMachineCode], [PrevOperationCode], [Previous Operation], [Prev. Result],
				[Queue Status],[QueueTime], [Queue Time], [Quarantined On], AssyUser, Approver, Remarks 
				FROM #QUEUE_TIME_RESULT
				WHERE (@Assy_str = 'All' OR [Queue Status] = CASE WHEN @Assy_str='Quarantine' THEN 'Quarantined' WHEN @Assy_str='Approved' THEN 'Approved' END)
				ORDER BY [MachineCode], [Scan Time] DESC;
			END

			IF OBJECT_ID('tempdb..#ROUTING_QUEUE') IS NOT NULL DROP TABLE #ROUTING_QUEUE;
			IF OBJECT_ID('tempdb..#QUEUE_RUNNING') IS NOT NULL DROP TABLE #QUEUE_RUNNING;
			IF OBJECT_ID('tempdb..#QUEUE_TIME_RESULT') IS NOT NULL DROP TABLE #QUEUE_TIME_RESULT;

			SET @RETURNINT=1
			SET @RETURNVALUE='SUCCESS'

			END TRY
			BEGIN CATCH
				SET @RETURNVALUE = 	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
				CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
				CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_MESSAGE() AS VARCHAR(1500))
			END CATCH
		END

		ELSE IF (@CONDITION='GET_QUEUE_DETAIL_DATA_FULL')
		BEGIN
			--@PARTNUMBER
			
			DECLARE @cols NVARCHAR(MAX);
			DECLARE @cols_na NVARCHAR(MAX);
			DECLARE @whereClause NVARCHAR(200) = '';
			DECLARE @ResultTable SYSNAME  = '##QueueResultTemp_' + CAST(@@SPID AS VARCHAR(10));
			IF @MACHINECODE <> 'All'
			BEGIN
				SET @whereClause = ' WHERE MachineCode = ''' + @MACHINECODE + '''';
			END
 
			--IF LEN(ISNULL(@PARTNUMBER,'')) > 0
			--BEGIN
			--	IF LEN(ISNULL(@whereClause,'')) > 0
			--	BEGIN
			--		SET @whereClause = ' AND PartNo = ''' + @PARTNUMBER + '''';
			--	END
			--	ELSE
			--	BEGIN
			--		SET @whereClause = ' WHERE PartNo = ''' + @PARTNUMBER + '''';
			--	END
			--END
 
			SELECT DISTINCT A.MachineCode, A.OperationSeqNo INTO #ROUTING_QUEUE_FULL FROM RoutingConfigPartWise A WITH (NOLOCK)
			--INNER JOIN ASSY_LINEQUEUETIME_RUNNING B WITH (NOLOCK) ON A.MachineCode=B.MachineCode	--IF JUST DATA
			--AND A.ProfitCenterCode=B.ProfitCenterCode
			WHERE A.PartNo=@PARTNUMBER AND (@MACHINECODE = 'All' OR A.MachineCode = @MACHINECODE) AND A.Traceability=1
 
			IF NOT EXISTS (SELECT TOP 1 1 FROM #ROUTING_QUEUE_FULL)
			BEGIN
				SET @RETURNINT=1
				SET @RETURNVALUE='FAILED|MACHINE AND PART DETAILS NOT FOUND'
				RETURN
			END
 
			SELECT @cols = STUFF((
				SELECT 
					',' + CASE WHEN @MACHINECODE = 'All' THEN QUOTENAME(r.MachineCode + '_ResultTimeStamp') ELSE 'ResultTimeStamp' END  + ',' +
						CASE WHEN @MACHINECODE = 'All' THEN QUOTENAME(r.MachineCode + '_Result') ELSE 'Result' END + ',' +
						CASE WHEN @MACHINECODE = 'All' THEN QUOTENAME(r.MachineCode + '_NextMachineCode') ELSE 'NextMachineCode' END + ',' + 
						CASE WHEN @MACHINECODE = 'All' THEN QUOTENAME(r.MachineCode + '_NextScanTimeStamp') ELSE 'NextScanTimeStamp' END + ',' + 
						CASE WHEN @MACHINECODE = 'All' THEN QUOTENAME(r.MachineCode + '_QueueStatus') ELSE 'QueueStatus' END
				FROM (
					SELECT DISTINCT MachineCode, OperationSeqNo
					FROM #ROUTING_QUEUE_FULL
				) r
				ORDER BY r.OperationSeqNo
				FOR XML PATH(''), TYPE
			).value('.', 'NVARCHAR(MAX)'), 1, 1, '');
 
 
			SELECT @cols_na = STUFF((
				SELECT 
					',ISNULL(' + CASE WHEN @MACHINECODE = 'All' THEN QUOTENAME(r.MachineCode + '_ResultTimeStamp')  ELSE 'ResultTimeStamp' END + ',''NA'') AS ' + 
					CASE WHEN @MACHINECODE = 'All' THEN QUOTENAME(r.MachineCode + '_ResultTimeStamp')  ELSE 'ResultTimeStamp' END + 
					',ISNULL(' + CASE WHEN @MACHINECODE = 'All' THEN QUOTENAME(r.MachineCode + '_Result')  ELSE 'Result' END + ',''NA'') AS ' + 
					CASE WHEN @MACHINECODE = 'All' THEN QUOTENAME(r.MachineCode + '_Result')  ELSE 'Result' END + 
					',ISNULL(' + CASE WHEN @MACHINECODE = 'All' THEN QUOTENAME(r.MachineCode + '_NextMachineCode')  ELSE 'NextMachineCode' END + ',''NA'') AS ' + 
					CASE WHEN @MACHINECODE = 'All' THEN QUOTENAME(r.MachineCode + '_NextMachineCode')  ELSE 'NextMachineCode' END + 
					',ISNULL(' + CASE WHEN @MACHINECODE = 'All' THEN QUOTENAME(r.MachineCode + '_NextScanTimeStamp')  ELSE 'NextScanTimeStamp' END + ',''NA'') AS ' + 
					CASE WHEN @MACHINECODE = 'All' THEN QUOTENAME(r.MachineCode + '_NextScanTimeStamp')  ELSE 'NextScanTimeStamp' END + 
					',ISNULL(' + CASE WHEN @MACHINECODE = 'All' THEN QUOTENAME(r.MachineCode + '_QueueStatus')  ELSE 'QueueStatus' END + ',''NA'') AS ' + 
					CASE WHEN @MACHINECODE = 'All' THEN QUOTENAME(r.MachineCode + '_QueueStatus')  ELSE 'QueueStatus' END
				FROM (
					SELECT DISTINCT MachineCode, OperationSeqNo
					FROM #ROUTING_QUEUE_FULL
				) r
				ORDER BY r.OperationSeqNo
				FOR XML PATH(''), TYPE
			).value('.', 'NVARCHAR(MAX)'), 1, 1, '');

			IF OBJECT_ID('tempdb..#ROUTING_QUEUE_FULL') IS NOT NULL
			DROP TABLE #ROUTING_QUEUE_FULL
 
			SET @query = '
 
			SELECT * INTO #QUEUE_RUNNING_FULL FROM ASSY_LINEQUEUETIME_RUNNING WITH (NOLOCK) WHERE 
			ProfitCenterCode = ''' + ISNULL(@PROFITCENTERCODE,'') + ''' AND LineCode = ''' + ISNULL(@LINECODE,'') + '''
			AND PartNo = ''' + ISNULL(@PARTNUMBER,'') + '''
			AND DateCode = ''' + ISNULL(@DATECODE,'') + '''

			INSERT INTO #QUEUE_RUNNING_FULL (ProfitCenterCode,LineCode,Datecode,MachineCode,OperationCode,Barcode,Result,AssyUser,ResultTimestamp,NextMachineCode,NextOperationcode,NextScanTimestamp,PartNo,BreakID,QuarantineStatus,QuarantineTimeStamp,QuarantineApproveTimestamp,QuarantineApproveByUser,QuarantineRemarks)
			SELECT ProfitCenterCode,LineCode,Datecode,MachineCode,OperationCode,Barcode,Result,AssyUser,ResultTimestamp,NextMachineCode,NextOperationcode,NextScanTimestamp,PartNo,BreakID,QuarantineStatus,QuarantineTimeStamp,QuarantineApproveTimestamp,QuarantineApproveByUser,QuarantineRemarks 
			FROM ASSY_LINEQUEUETIME (NOLOCK) WHERE 
			ProfitCenterCode = ''' + ISNULL(@PROFITCENTERCODE,'') + ''' AND LineCode = ''' + ISNULL(@LINECODE,'') + '''
			AND PartNo = ''' + ISNULL(@PARTNUMBER,'') + '''
			AND Barcode IN (SELECT DISTINCT Barcode FROM #QUEUE_RUNNING_FULL)
 
			SELECT Barcode, DateCode, ' + @cols_na + '
			INTO '+@ResultTable+' 
			FROM (
				SELECT 
					Barcode,
					DateCode,
					'+ CASE WHEN @MACHINECODE = 'All' THEN  'MachineCode + ''_NextScanTimeStamp''' ELSE '''NextScanTimeStamp''' END + '
					AS ColumnName,
					Convert(varchar(50), NextScanTimeStamp, 121) AS Value
				FROM #QUEUE_RUNNING_FULL' + @whereClause + '
				UNION ALL
				SELECT 
					Barcode,
					DateCode,
					'+ CASE WHEN @MACHINECODE = 'All' THEN  'MachineCode + ''_NextMachineCode''' ELSE '''NextMachineCode''' END + '
					AS ColumnName,
					Convert(varchar(50), NextMachineCode) AS Value
				FROM #QUEUE_RUNNING_FULL' + @whereClause + '
				UNION ALL
				SELECT 
					Barcode,
					DateCode,
					'+ CASE WHEN @MACHINECODE = 'All' THEN  'MachineCode + ''_ResultTimeStamp''' ELSE '''ResultTimeStamp''' END + '
					AS ColumnName,
					Convert(varchar(50), ResultTimeStamp, 121) AS Value
				FROM #QUEUE_RUNNING_FULL' + @whereClause + '
				UNION ALL
				SELECT 
					Barcode,
					DateCode,
					'+ CASE WHEN @MACHINECODE = 'All' THEN  'MachineCode + ''_Result''' ELSE '''Result''' END + '
					AS ColumnName,
					Convert(varchar(10), Result) AS Value
				FROM #QUEUE_RUNNING_FULL' + @whereClause + '
				UNION ALL
				SELECT 
					Barcode,
					DateCode,
					'+ CASE WHEN @MACHINECODE = 'All' THEN  'MachineCode + ''_QueueStatus''' ELSE '''QueueStatus''' END + '
					AS ColumnName,
					CASE WHEN ISNULL(QuarantineStatus,''0'') = ''0'' THEN ''Running'' ELSE
					CASE WHEN ISNULL(QuarantineStatus,''0'') = ''1'' THEN ''Quarantined'' ELSE 
					CASE WHEN ISNULL(QuarantineStatus,''0'') = ''2'' THEN ''Approved'' 
					END END END AS Value
				FROM #QUEUE_RUNNING_FULL' + @whereClause + '
			) AS SourceData
			PIVOT (
				MAX(Value)
				FOR ColumnName IN (' + @cols + ')
			) AS PivotTable
			ORDER BY Barcode';
 
			print @query
			EXEC sp_executesql @query;
 
			IF @MACHINECODE='All'
			BEGIN
				EXEC('SELECT * FROM ' + @ResultTable);
			END
			ELSE
			BEGIN
				EXEC('SELECT '''+ @MACHINECODE + ''' AS MachineCode,* FROM ' + @ResultTable);
			END
 
			IF OBJECT_ID('tempdb..'+@ResultTable+'') IS NOT NULL 
			BEGIN 
				EXEC('DROP TABLE ' + @ResultTable);
			END
 
			SET @RETURNINT=1
			SET @RETURNVALUE='SUCCESS'
		END

		IF (@CONDITION = 'GET_QUEUE_DETAIL_DATA_FULL_2')
		BEGIN
			--DECLARE @query NVARCHAR(MAX);
			--DECLARE @whereClause NVARCHAR(200) = '';
			SET @whereClause = ''
			PRINT @MACHINECODE
			DECLARE @ResultTable2 SYSNAME = '##QueueResultTemp_' + CAST(@@SPID AS VARCHAR(10));

			IF @MACHINECODE <> 'All'
				SET @whereClause = ' WHERE MachineCode = ''' + @MACHINECODE + '''';

			SET @query = '
			----------------------------------------
			-- 1. CREATE QUEUE RUNNING DATA
			----------------------------------------
			SELECT *
			INTO #QUEUE_RUNNING_FULL
			FROM ASSY_LINEQUEUETIME_RUNNING WITH (NOLOCK)
			WHERE ProfitCenterCode = ''' + ISNULL(@PROFITCENTERCODE,'') + '''
				AND LineCode = ''' + ISNULL(@LINECODE,'') + '''
				AND PartNo = ''' + ISNULL(@PARTNUMBER,'') + '''
				AND DateCode = ''' + ISNULL(@DATECODE,'') + ''';

			INSERT INTO #QUEUE_RUNNING_FULL
			(
				ProfitCenterCode, LineCode, DateCode, MachineCode, OperationCode,
				Barcode, Result, AssyUser, ResultTimeStamp,
				NextMachineCode, NextOperationCode, NextScanTimeStamp,
				PartNo, BreakID,
				QuarantineStatus, QuarantineTimeStamp,
				QuarantineApproveTimestamp, QuarantineApproveByUser, QuarantineRemarks
			)
			SELECT
				ProfitCenterCode, LineCode, DateCode, MachineCode, OperationCode,
				Barcode, Result, AssyUser, ResultTimeStamp,
				NextMachineCode, NextOperationCode, NextScanTimeStamp,
				PartNo, BreakID,
				QuarantineStatus, QuarantineTimeStamp,
				QuarantineApproveTimestamp, QuarantineApproveByUser, QuarantineRemarks
			FROM ASSY_LINEQUEUETIME WITH (NOLOCK)
			WHERE ProfitCenterCode = ''' + ISNULL(@PROFITCENTERCODE,'') + '''
				AND LineCode = ''' + ISNULL(@LINECODE,'') + '''
				AND PartNo = ''' + ISNULL(@PARTNUMBER,'') + '''
				AND Barcode IN (SELECT DISTINCT Barcode FROM #QUEUE_RUNNING_FULL);

			----------------------------------------
			-- 2. CREATE ROUTING FROM QUEUE DATA
			----------------------------------------
			SELECT DISTINCT     
				A.MachineCode, 
				A.OperationCode,
				A.OperationSeqNo, 
				O.OperationName,
				A.QueueTime
			INTO #ROUTING_QUEUE_FULL 
			FROM OperationMst O WITH (NOLOCK) 
			INNER JOIN RoutingConfigPartWise A ON O.OperationCode = A.OperationCode 
			INNER JOIN #QUEUE_RUNNING_FULL B
			ON A.OperationCode = B.NextOperationcode
			WHERE A.PartNo = ''' + ISNULL(@PARTNUMBER,'') + '''
			AND A.Traceability = 1

			----------------------------------------
			-- 3. BUILD DYNAMIC COLUMN LIST
			----------------------------------------
			DECLARE @cols NVARCHAR(MAX);
			DECLARE @cols_na NVARCHAR(MAX);

			SELECT @cols = STUFF((
				SELECT
					'','' + CASE WHEN ''' + @MACHINECODE + ''' = ''All''
						THEN QUOTENAME(MachineCode + ''_ResultTimeStamp'')
						ELSE ''ResultTimeStamp'' END
					+ '','' + CASE WHEN ''' + @MACHINECODE + ''' = ''All''
						THEN QUOTENAME(MachineCode + ''_Result'')
						ELSE ''Result'' END
					+ '','' + CASE WHEN ''' + @MACHINECODE + ''' = ''All''
						THEN QUOTENAME(MachineCode + ''_NextMachineCode'')
						ELSE ''NextMachineCode'' END
					+ '','' + CASE WHEN ''' + @MACHINECODE + ''' = ''All''
						THEN QUOTENAME(MachineCode + ''_NextScanTimeStamp'')
						ELSE ''NextScanTimeStamp'' END
					+ '','' + CASE WHEN ''' + @MACHINECODE + ''' = ''All''
						THEN QUOTENAME(MachineCode + ''_QueueStatus'')
						ELSE ''QueueStatus'' END
				FROM #ROUTING_QUEUE_FULL
				ORDER BY OperationSeqNo
				FOR XML PATH(''''), TYPE
			).value(''.'', ''NVARCHAR(MAX)''), 1, 1, '''');

			SELECT @cols_na = STUFF((
				SELECT
					'',ISNULL('' + QUOTENAME(MachineCode + ''_ResultTimeStamp'') + '', ''''NA'''') AS ''
					+ QUOTENAME(MachineCode + ''_ResultTimeStamp'') +
					'',ISNULL('' + QUOTENAME(MachineCode + ''_Result'') + '', ''''NA'''') AS ''
					+ QUOTENAME(MachineCode + ''_Result'') +
					'',ISNULL('' + QUOTENAME(MachineCode + ''_NextMachineCode'') + '', ''''NA'''') AS ''
					+ QUOTENAME(MachineCode + ''_NextMachineCode'') +
					'',ISNULL('' + QUOTENAME(MachineCode + ''_NextScanTimeStamp'') + '', ''''NA'''') AS ''
					+ QUOTENAME(MachineCode + ''_NextScanTimeStamp'') +
					'',ISNULL('' + QUOTENAME(MachineCode + ''_QueueStatus'') + '', ''''NA'''') AS ''
					+ QUOTENAME(MachineCode + ''_QueueStatus'')
				FROM #ROUTING_QUEUE_FULL
				ORDER BY OperationSeqNo
				FOR XML PATH(''''), TYPE
			).value(''.'', ''NVARCHAR(MAX)''), 1, 1, '''');

			----------------------------------------
			-- 4. PIVOT DATA
			----------------------------------------
			SELECT Barcode, DateCode, ' + ''' + @cols_na + '''' + ''
			INTO ' + @ResultTable2 + '
			FROM
			(
				SELECT Barcode, DateCode,
						CASE WHEN ''' + @MACHINECODE + ''' = ''All''
							THEN MachineCode + ''_NextScanTimeStamp''
							ELSE ''NextScanTimeStamp'' END AS ColumnName,
						CONVERT(VARCHAR(50), NextScanTimeStamp, 121) AS Value
				FROM #QUEUE_RUNNING_FULL' + @whereClause + '

				UNION ALL
				SELECT Barcode, DateCode,
						CASE WHEN ''' + @MACHINECODE + ''' = ''All''
							THEN MachineCode + ''_NextMachineCode''
							ELSE ''NextMachineCode'' END,
						CONVERT(VARCHAR(50), NextMachineCode)
				FROM #QUEUE_RUNNING_FULL' + @whereClause + '

				UNION ALL
				SELECT Barcode, DateCode,
						CASE WHEN ''' + @MACHINECODE + ''' = ''All''
							THEN MachineCode + ''_ResultTimeStamp''
							ELSE ''ResultTimeStamp'' END,
						CONVERT(VARCHAR(50), ResultTimeStamp, 121)
				FROM #QUEUE_RUNNING_FULL' + @whereClause + '

				UNION ALL
				SELECT Barcode, DateCode,
						CASE WHEN ''' + @MACHINECODE + ''' = ''All''
							THEN MachineCode + ''_Result''
							ELSE ''Result'' END,
						CONVERT(VARCHAR(10), Result)
				FROM #QUEUE_RUNNING_FULL' + @whereClause + '

				UNION ALL
				SELECT Barcode, DateCode,
						CASE WHEN ''' + @MACHINECODE + ''' = ''All''
							THEN MachineCode + ''_QueueStatus''
							ELSE ''QueueStatus'' END,
						CASE
							WHEN ISNULL(QuarantineStatus,''0'') = ''0'' THEN ''Running''
							WHEN ISNULL(QuarantineStatus,''0'') = ''1'' THEN ''Quarantined''
							WHEN ISNULL(QuarantineStatus,''0'') = ''2'' THEN ''Approved''
						END
				FROM #QUEUE_RUNNING_FULL' + @whereClause + '
			) S
			PIVOT (MAX(Value) FOR ColumnName IN (' + @cols + ')) P
			ORDER BY Barcode;
			';

			PRINT @query;
			--EXEC (@query);

			--IF @MACHINECODE = 'All'
			--	EXEC ('SELECT * FROM ' + @ResultTable2);
			--ELSE
			--	EXEC ('SELECT ''' + @MACHINECODE + ''' AS MachineCode, * FROM ' + @ResultTable2);

			--EXEC ('DROP TABLE ' + @ResultTable2);

			SET @RETURNINT = 1;
			SET @RETURNVALUE = 'SUCCESS';
		END

		--Added By Binny 02122025
		ELSE IF (@Condition = 'ENABLE_DISABLE_QUEUE_VALIDATION')
		BEGIN
				IF(@Enable_QueueTime = 1) 
				BEGIN 
					UPDATE RoutingConfigDetails SET KeyValue = @Enable_QueueTime WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND KeyType='QueueTimeValidation'
     
					SET @RETURNVALUE = (SELECT TOP 1 Case ISNULL(KeyValue,0) WHEN 1 THEN 'Y' ELSE 'N' END QueueTimeValidation FROM RoutingConfigDetails (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND KeyType='QueueTimeValidation')
					SET @RETURNVALUE = @RETURNVALUE
					SET @RETURNINT = 1
					SELECT @RETURNVALUE
					RETURN
				END

				IF(@Enable_QueueTime = 0) 
				BEGIN 
					UPDATE RoutingConfigDetails SET KeyValue = @Enable_QueueTime WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND KeyType='QueueTimeValidation'
				
					SET @RETURNVALUE = (SELECT TOP 1 Case ISNULL(KeyValue,0) WHEN 1 THEN 'Y' ELSE 'N' END QueueTimeValidation FROM RoutingConfigDetails (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND KeyType='QueueTimeValidation')
					SET @RETURNVALUE = @RETURNVALUE
					SET @RETURNINT = 1
					SELECT @RETURNVALUE
					RETURN 
				END
		END	--End By Binny 02122025
		ELSE IF @Condition = 'GET_QueueTime_STATUS' 
		BEGIN 
			SET @RETURNVALUE = (SELECT TOP 1 Case ISNULL(KeyValue,0) WHEN 1 THEN 'Y' ELSE 'N' END QueueTimeValidation FROM RoutingConfigDetails (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND KeyType='QueueTimeValidation')
			SELECT @ReturnInt = 1 
			SELECT @RETURNVALUE
			RETURN 
		END
		ELSE IF @Condition = 'GetRFIDFromRoboBarcode'
		BEGIN
			IF @PROFITCENTERCODE IN ('0088')
			BEGIN
				EXEC ASSY_PROC_FINALVIEWING_BIJ @PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,@MACHINECODE=@MACHINECODE,
				@OPERATIONCODE=@OPERATIONCODE,@Condition='GetRFIDFromRoboBarcode',
				@USERID=@USERID,@RETURNINT=@ReturnInt OUTPUT,@RETURNVALUE=@RETURNVALUE OUTPUT
				RETURN
			END
		END
		ELSE IF @Condition = 'CaptureRoboParametersAndResult'
		BEGIN
			IF @PROFITCENTERCODE IN ('0088')
			BEGIN
				EXEC ASSY_PROC_FINALVIEWING_BIJ @PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,--@MACHINECODE=@MACHINECODE,@OPERATIONCODE=@OPERATIONCODE,
				@Condition='CaptureRoboParametersAndResult',@USERID=@USERID,@RETURNINT=@ReturnInt OUTPUT,@RETURNVALUE=@RETURNVALUE OUTPUT
			END
		END
END
GO
