CREATE PROC [dbo].[ASSY_PROC_FINALVIEWING_ABS] (
	@CONDITION VARCHAR(60)
	,@PROFITCENTERCODE VARCHAR(20) = NULL
	,@LINECODE VARCHAR(20) = NULL
	,@OPERATIONCODE VARCHAR(20) = NULL
	,@MACHINECODE VARCHAR(20) = NULL
	,@STATIONCODE VARCHAR(20) = '1'
	,@DATECODE VARCHAR(4) = NULL
	,@PARTNUMBER VARCHAR(20) = NULL
	,@BARCODE VARCHAR(200) = NULL
	,@PREFIX CHAR(2) = NULL
	,@SUFFIX CHAR(2) = NULL
	,@USERID VARCHAR(50) = NULL
	,@PASSQTY INT = 0
	,@FAILQTY INT = 0
	,@STATUS CHAR(2) = NULL
	,@SCANTIMESTAMP DATETIME = NULL
	,@RESULTTIMESTAMP DATETIME = NULL
	,@PARTFAILEDCOUNT TINYINT = 0
	,@P_Lot_No VARCHAR(20) = ''
	,@P_ECU_Barcode VARCHAR(30) = ''
	,@RETURNVALUE VARCHAR(2000) = NULL OUT
	,@RETURNINT INT = NULL OUT
	,@SubStnMACHINECODE VARCHAR(20) = NULL
	,@SubStnOperationCODE VARCHAR(20) = NULL
	,--Added by Ravi on 21-July-17
	@Allow2Parts BIT = 0
	,@ScannerIpAddress VARCHAR(30) = NULL
	,@ScannerPortNo INT = 0
	,@P_EKanbanAllowed BIT = 0
	,-- Added By Sachin 2020June04
	@Kanban_Id VARCHAR(40) = ''
	)
AS
BEGIN
	DECLARE @FAILCOUNTDEFINED INT = 0
	DECLARE @FAILCOUNT INT = 0
	DECLARE @TEMPSCANNEDPARTTYPE VARCHAR(15)
	DECLARE @TEMPRUNNINGPARTTYPE VARCHAR(15)
	DECLARE @TEMPOPERATIONTYPE VARCHAR(20)
		,@LINETYPECODE VARCHAR(20) = ''
	DECLARE @OPERATIONSEQNO INT
		,@OPERATIONNAME VARCHAR(50)
	DECLARE @BARCODE_LENGTH AS INT
	DECLARE @INCORRECTMSG VARCHAR(200)
	DECLARE @POKAYOKEDATECODE VARCHAR(20)
	DECLARE @EXECQUERY VARCHAR(MAX)
		,@LINKSERVERNAME VARCHAR(100)
	DECLARE @PART_FIXTUREGROUPTYPE_COUNT INT = 0
	DECLARE @FINALVIEWING_OPERATIONCODE VARCHAR(20) = NULL
		,@FINALVIEWING_MACHINECODE VARCHAR(20) = NULL
	DECLARE @DATECODETEMP VARCHAR(4) = NULL
		,@STMCPARTNO VARCHAR(30)
		,@PARTTYPE VARCHAR(20)
	DECLARE @RETURNVALUE1 VARCHAR(100)
	DECLARE @RETURNINT1 INT
	DECLARE @ISSTMC BIT = 0
	DECLARE @LINECODE_STMC VARCHAR(30)
	DECLARE @DATECODE_TEMP CHAR(4)
	DECLARE @FAULTRESULTCOUNT INT
	DECLARE @PASSFAILRESULTCOUNT INT
	DECLARE @PART_FIXTUREGROUPTYPE VARCHAR(30)
	DECLARE @CHANGEOVER_DATECODE CHAR(4) = NULL
	DECLARE @REWORK_DATECODE CHAR(4) = NULL
	DECLARE @REWORK_MODE VARCHAR(20) = NULL
	DECLARE @REWORK_CURRENT_PLANQTY INT = 0
	DECLARE @REWORK_ORDERNO VARCHAR(20) = ''
	DECLARE @REWORK_PRINT_QTY INT = 0
	DECLARE @PARTNO VARCHAR(60) = ''
	DECLARE @V_DateCode CHAR(4) = ''

	SET @CHANGEOVER_DATECODE = @DATECODE

	DECLARE @PREVMACHINECODE VARCHAR(20) = NULL
	DECLARE @ProductionOrderNo VARCHAR(20) = ''
	DECLARE @RETURN_LOT_NO VARCHAR(20) = '' -- Added By Sachin 20170726
	DECLARE @RETURN_ECU_BARCODE VARCHAR(20) = '' -- Added By Sachin  20170809
	DECLARE @FlagStatus VARCHAR(10) = '' --Added By sachin 20170830
	DECLARE @IsImportBarcodeMode BIT = 0 --Added By sachin 20170913
	DECLARE @lotSerialNo VARCHAR(10) = '' --Added By sachin 20170914
	DECLARE @VarhildPartsList VARCHAR(max) --Added By sachin 20190601
	DECLARE @TSBarcodeSeq INT --Added By sachin 20190601
	DECLARE @FindPartNo VARCHAR(100) --Added By sachin 20190601
	DECLARE @WIPMsg VARCHAR(200) --Added By sachin 20190607
	DECLARE @PARTTESTINGTIME DATETIME = NULL

	SET NOCOUNT ON;

	--Modified By Sudesh on 20170515 for new column ProductionOrderNo in Table Assy_LineAssyStatus_Running
	SELECT @ProductionOrderNo = ProductionOrderNo
	FROM Assy_RunningPart(NOLOCK)
	WHERE LineCode = @LineCode
		AND ProfitCenterCode = @ProfitCenterCode

	DECLARE @Live_Datecode CHAR(4)
		,@return_int INT

	EXEC Assy_proc_datecode @PROFITCENTERCODE
		,@Live_Datecode OUT
		,@return_int OUT

	IF @CONDITION = 'SCAN_OK'
	BEGIN
		BEGIN TRAN

		BEGIN TRY
			DECLARE @LOT_NO VARCHAR(20) = '' -- Added By Sachin By Sachin 20170726

			SELECT @REWORK_DATECODE = DATECODE
				,@REWORK_MODE = RTRIM(ASSY_MODE)
				,@REWORK_CURRENT_PLANQTY = CURRENTPLANNEDQTY
				,@REWORK_ORDERNO = PRODUCTIONORDERNO
				,@PARTNO = Assy_PartNo
				,@V_DateCode = Datecode
			FROM ASSY_RUNNINGPART WITH (NOLOCK)
			WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE

			SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME
			FROM ASSY_LINKSERVER_DTL WITH (NOLOCK)
			WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE

			-- Added By Sachin By Sachin 20170726
			-- Get Rework Data if Exists --
			--Added By Sachin 20170925
			IF EXISTS (
					SELECT TOP 1 1
					FROM Assy_StatusRework_Data_Move_To_Running(NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode
						AND LineCode = @LineCode
						AND PartNo = @PARTNO
						AND Barcode = @BARCODE
					)
			BEGIN
				INSERT INTO Assy_LineAssyStatus_Running (
					ProfitCenterCode
					,LineCode
					,MachineCode
					,OperationCode
					,StationCode
					,Barcode
					,STATUS
					,FailCount
					,Datecode
					,PartNo
					,Active
					,ResultTimestamp
					,ScanTimestamp
					,UserID
					,IsTallyChartApproved
					,IsReworkPart
					,ProductionOrderNo
					,PROD_LOT_NO
					)
				SELECT ProfitCenterCode
					,LineCode
					,MachineCode
					,OperationCode
					,StationCode
					,Barcode
					,STATUS
					,FailCount
					,@V_DateCode
					,PartNo
					,Active
					,ResultTimestamp
					,ScanTimestamp
					,UserID
					,0
					,IsReworkPart
					,ProductionOrderNo
					,PROD_LOT_NO
				FROM Assy_StatusRework_Data_Move_To_Running(NOLOCK)
				WHERE PROFITCENTERCODE = @ProfitCenterCode
					AND LineCode = @LineCode
					AND PartNo = @PARTNO
					AND barcode = @BARCODE

				INSERT INTO Assy_LineAssyParamData_running (
					ProfitCenterCode
					,LineCode
					,MachineCode
					,OperationCode
					,StationCode
					,Barcode
					,TagName
					,Value
					,Result
					,Datecode
					,UserID
					,TIMESTAMP
					,PartNo
					,UID
					,ScanTimeStamp
					)
				SELECT DISTINCT ProfitCenterCode
					,LineCode
					,MachineCode
					,OperationCode
					,StationCode
					,Barcode
					,TagName
					,Value
					,Result
					,@V_DateCode
					,UserID
					,TIMESTAMP
					,PartNo
					,UID
					,ScanTimeStamp
				FROM Assy_ParamDataRework_To_Running(NOLOCK)
				WHERE PROFITCENTERCODE = @ProfitCenterCode
					AND LineCode = @LineCode
					AND PartNo = @PARTNO
					AND barcode = @BARCODE

				INSERT INTO Assy_LineAssyParamData_Running_Dtl (
					[UID]
					,[TagId]
					,[Value]
					)
				SELECT DISTINCT UID
					,TagId
					,Value
				FROM Assy_ParamDataRework_Move_To_Running_Dtl
				WHERE UID IN (
						SELECT UID
						FROM Assy_LineAssyParamData_Running(NOLOCK)
						WHERE PROFITCENTERCODE = @ProfitCenterCode
							AND LineCode = @LineCode
							AND PartNo = @PARTNO
							AND barcode = @BARCODE
						)

				DELETE
				FROM Assy_StatusRework_Data_Move_To_Running
				WHERE PROFITCENTERCODE = @ProfitCenterCode
					AND LineCode = @LineCode
					AND PartNo = @PARTNO
					AND barcode = @BARCODE

				DELETE
				FROM Assy_ParamDataRework_To_Running
				WHERE PROFITCENTERCODE = @ProfitCenterCode
					AND LineCode = @LineCode
					AND PartNo = @PARTNO
					AND barcode = @BARCODE

				DELETE
				FROM Assy_ParamDataRework_Move_To_Running_Dtl
				WHERE UID IN (
						SELECT UID
						FROM Assy_LineAssyParamData_Running(NOLOCK)
						WHERE PROFITCENTERCODE = @ProfitCenterCode
							AND LineCode = @LineCode
							AND PartNo = @PARTNO
							AND barcode = @BARCODE
						)
			END

			----------------------------------------------------------------------------------
			--------------------------  Import Label -----------------------------------------						
			CREATE TABLE #COUNT (COUNT_VALUE INT)

			DECLARE @ImportLabelOperationCode VARCHAR(10) = '' -- Added By Sachin 20190506
			DECLARE @ImportLabelBarcodeLength SMALLINT = 0 -- Added By Sachin 20210401

			INSERT INTO #COUNT (COUNT_VALUE)
			SELECT TOP 1 1
			FROM RoutingConfigDetails(NOLOCK)
			WHERE ProfitCenterCode = @ProfitCenterCode
				AND sts_cd = 0
				AND keyType = 'IsImportBarcodeMode'
				AND KeyValue = '1'
				AND LineCode = @LineCode
				AND PartNumber = @PARTNO

			SELECT TOP 1 @ImportLabelOperationCode = ISNULL(KeyValue, '')
			FROM RoutingConfigDetails(NOLOCK)
			WHERE ProfitCenterCode = @ProfitCenterCode
				AND sts_cd = 0
				AND keyType = 'ImportLabelOperationCode'
				AND LineCode = @LineCode

			SELECT TOP 1 @ImportLabelBarcodeLength = CONVERT(SMALLINT, ISNULL(KeyValue, 0))
			FROM RoutingConfigDetails(NOLOCK)
			WHERE ProfitCenterCode = @ProfitCenterCode
				AND sts_cd = 0
				AND keyType = 'ImportLabelBarcodeLength'
				AND LineCode = @LineCode

			-- Label Not Generated By TS System.			
			IF (
					(
						EXISTS (
							SELECT TOP 1 1
							FROM #COUNT
							)
						)
					AND (@ImportLabelOperationCode = @OPERATIONCODE)
					) -- Added By Sachin 20190506
			BEGIN
				-- Validate Import Label Length
				IF (LEN(@BARCODE) <> @ImportLabelBarcodeLength)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'RESCAN !!! SCAN BARCODE LEN MISMATCH - ' + CONVERT(VARCHAR, @ImportLabelBarcodeLength)

					COMMIT TRAN

					RETURN
				END

				EXEC Assy_Proc_Barcode_Printed_Counter @CONDITION = 'IS_PLANNED_QTY_REACHED'
					,@ProfitCenterCode = @ProfitCenterCode
					,@LineCode = @LineCode
					,@RETURNVALUE = @WIPMsg OUTPUT

				IF (@WIPMSG = 'Yes')
				BEGIN
					--UPDATE INCORRECT LABEL
					--IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
					--BEGIN
					--	EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
					--	,@BARCODE=@BARCODE,@HMIMESSAGE='Printed QTY. Reached'
					--END
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'Printed QTY. Reached !!! Kindly Do Set Parameter.'

					COMMIT TRAN

					RETURN
				END

				DECLARE @ImportLabelLineCode VARCHAR(5)

				SELECT TOP 1 @ImportLabelLineCode = KeyValue
				FROM RoutingConfigDetails(NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode
					AND sts_cd = 0
					AND keyType = 'ImportLabelLineCode'
					AND LineCode = @LineCode
				
				IF (CHARINDEX(@ImportLabelLineCode, @BARCODE) <= 0)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'SCANNED BARCODE DOES NOT MATCH WITH RUNNING LINE CODE'
					COMMIT TRAN
					RETURN
				END

				DECLARE @ValidatePartOnImport VARCHAR(5),@PartValidationEndDigit int=0,@PartValidationStartDigit int=0
				declare @Partnostring nvarchar(50)

				SELECT TOP 1 @ValidatePartOnImport = KeyValue
				FROM RoutingConfigDetails(NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode
					AND sts_cd = 0
					AND keyType = 'ValidatePartOnImport'
					AND LineCode = @LineCode

					SELECT TOP 1 @PartValidationEndDigit = cast(isnull(KeyValue,0) as int)
				FROM RoutingConfigDetails(NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode
					AND sts_cd = 0
					AND keyType = 'PartValidationEndDigit'
					AND LineCode = @LineCode

					SELECT TOP 1 @PartValidationStartDigit = cast(isnull(KeyValue,0) as int)
				FROM RoutingConfigDetails(NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode
					AND sts_cd = 0
					AND keyType = 'PartValidationStartDigit'
					AND LineCode = @LineCode

				IF (ISNULL(@ValidatePartOnImport, '') = '1')
				BEGIN

					if(@PartValidationEndDigit>0)
					Begin
							
							select @Partnostring=substring(@PARTNO,(len(@PARTNO)-(@PartValidationEndDigit-1)),len(@PARTNO))

							If(CHARINDEX(@Partnostring, @BARCODE) <= 0)
							Begin

								SET @RETURNINT = 1
								SET @RETURNVALUE = 'SCANNED BARCODE DOES NOT MATCH WITH RUNNING PART'

								COMMIT TRAN
								RETURN

							end
					End
					else if(@PartValidationStartDigit>0)
					Begin

						select @Partnostring=substring(@PARTNO,1,@PartValidationStartDigit)
						
						If(CHARINDEX(@Partnostring, @BARCODE) <= 0)
							Begin

								SET @RETURNINT = 1
								SET @RETURNVALUE = 'SCANNED BARCODE DOES NOT MATCH WITH RUNNING PART'

								COMMIT TRAN
								RETURN

							end

					End
					else IF (CHARINDEX(@PARTNO, @BARCODE) <= 0)
					BEGIN
						SET @RETURNINT = 1
						SET @RETURNVALUE = 'SCANNED BARCODE DOES NOT MATCH WITH RUNNING PART'

						--UPDATE INCORRECT LABEL
						--	IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
						--	BEGIN
						--		EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
						--		,@BARCODE=@BARCODE,@HMIMESSAGE='SCANNED BARCODE DOES NOT MATCH WITH RUNNING PART'
						--	END
						COMMIT TRAN

						RETURN
					END
				END

				SELECT TOP 1 @ValidatePartOnImport = KeyValue
				FROM RoutingConfigDetails(NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode
					AND sts_cd = 0
					AND keyType = 'ValidateChildPartOnImport'
					AND LineCode = @LineCode
					AND OperationCode = @OPERATIONCODE

				IF (ISNULL(@ValidatePartOnImport, '') = '1')
				BEGIN
					SELECT TOP 1 @VarhildPartsList = ChildPartsList
						,@TSBarcodeSeq = TSBarcodeSeq
					FROM RoutingConfigPartWise(NOLOCK)
					WHERE OperationCode = @OPERATIONCODE
						AND PartNo = @PARTNO
						AND IsCPValidationRequired = 1
						AND ChildPartsList IS NOT NULL

					SELECT TOP 1 @FindPartNo = col1
					FROM dbo.FN_GRID_SPLIT_STRING(@VarhildPartsList, '', ',')
					WHERE ROW_NO = @TSBarcodeSeq

					IF (CHARINDEX(@FindPartNo, @BARCODE) <= 0)
					BEGIN
						--UPDATE INCORRECT LABEL
						--	IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
						--	BEGIN
						--		EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
						--		,@BARCODE=@BARCODE,@HMIMESSAGE='SCANNED BARCODE DOES NOT MATCH WITH RUNNING PART'
						--	END
						SET @RETURNINT = 1
						SET @RETURNVALUE = 'Child Part No. ' + ISNULL(@FindPartNo, '') + ' Not In Barcode (' + ISNULL(@BARCODE, '') + ')'

						COMMIT TRAN

						RETURN
					END
				END

				SET @ISIMPORTBARCODEMODE = 1

				IF NOT EXISTS (
						SELECT TOP 1 1
						FROM ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
						WHERE PROFITCENTERCODE = @ProfitCenterCode
							AND lineCode = @LineCode
							AND MachineCode = 'MCIG'
							AND OperationCode = 'OCIG'
							AND Barcode = @BARCODE
						)
				BEGIN
					IF NOT EXISTS (
							SELECT TOP 1 1
							FROM ASSY_LINEASSYSTATUS(NOLOCK)
							WHERE PROFITCENTERCODE = @ProfitCenterCode
								AND lineCode = @LineCode
								AND MachineCode = 'MCIG'
								AND OperationCode = 'OCIG'
								AND Barcode = @BARCODE
							)
					BEGIN
						DECLARE @CurrentDateCode VARCHAR(4)

						EXEC ASSY_PROC_DATECODE @PROFITCENTERCODE = @ProfitCenterCode
							,@RETURNVALUE = @CurrentDateCode OUTPUT

						-- if Current date Not Matched With Running Date
						-- User Must Have to do tally chart and set parameter again
						IF EXISTS (
								SELECT TOP 1 1
								FROM lineMst(NOLOCK)
								WHERE lineCode = @LINECODE
									AND ProfitCenterCode = @PROFITCENTERCODE
									AND ISNULL(AutoTallyChartEnable, 0) = 0
								)
						BEGIN
							IF (@V_DateCode != @CurrentDateCode)
							BEGIN
								SET @RETURNINT = 1
								SET @RETURNVALUE = 'Shift Changed Please Do Tally Chart'

								EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
									,@LINECODE = @LINECODE
									,@OPERATIONCODE = @OPERATIONCODE
									,@BARCODE = @BARCODE
									,@HMIMESSAGE = 'Shift Changed Please Do Tally Chart'

								COMMIT TRAN

								RETURN
							END
						END

						-- Generate Lot Number
						BEGIN
							IF EXISTS (
									SELECT TOP 1 1
									FROM RoutingConfigDetails(NOLOCK)
									WHERE ProfitCenterCode = @ProfitCenterCode
										AND LineCode = @LineCode
										AND sts_cd = 0
										AND KeyType = 'isLotNumberReq'
										AND keyvalue = '1'
									)
							BEGIN
								DECLARE @lotNo INT

								IF EXISTS (
										SELECT TOP 1 1
										FROM ASSY_GENERATE_LOTNO_ON_DATACHANGE(NOLOCK)
										WHERE ProfitCenterCode = @ProfitCenterCode
											AND LineCode = @LineCode
											AND Datecode = @V_DateCode
										)
								BEGIN
									PRINT 'no change get same lot number again'
								END
								ELSE
								BEGIN
									PRINT 'update Lot Number '

									SELECT @lotNo = Lot_No
									FROM ASSY_GENERATE_LOTNO_ON_DATACHANGE(NOLOCK)

									INSERT INTO ASSY_GENERATE_LOTNO_ON_DATACHANGE_LOG (
										ProfitCenterCode
										,LineCode
										,Datecode
										,PartNo
										,ProductionOrderNo
										,Lot_No
										,STS_CD
										,ENT_BY
										,ENT_STAMP
										)
									SELECT ProfitCenterCode
										,LineCode
										,Datecode
										,PartNo
										,ProductionOrderNo
										,Lot_No
										,STS_CD
										,ENT_BY
										,ENT_STAMP
									FROM ASSY_GENERATE_LOTNO_ON_DATACHANGE(NOLOCK)

									DELETE
									FROM ASSY_GENERATE_LOTNO_ON_DATACHANGE

									SET @lotNo = ISNULL(@lotNo, 0) + 1

									INSERT INTO ASSY_GENERATE_LOTNO_ON_DATACHANGE (
										ProfitCenterCode
										,LineCode
										,Datecode
										,PartNo
										,ProductionOrderNo
										,Lot_No
										,STS_CD
										,ENT_BY
										,ENT_STAMP
										)
									SELECT @ProfitCenterCode
										,@LineCode
										,@V_DateCode
										,@PARTNO
										,@ProductionOrderNo
										,@lotNo
										,0
										,'ADMIN'
										,GETDATE()
								END

								SELECT @lotNo = Lot_No
								FROM ASSY_GENERATE_LOTNO_ON_DATACHANGE(NOLOCK)
								WHERE ProfitCenterCode = @ProfitCenterCode
									AND LineCode = @LineCode
									AND Datecode = @V_DateCode

								SET @lotSerialNo = REPLACE(STR(@LOTNO, 6), SPACE(1), '0')
								SET @lotSerialNo = @lotSerialNo + ISNULL(@V_DateCode, '')
							END
						END

						INSERT INTO ASSY_LINEASSYSTATUS_RUNNING (
							PROFITCENTERCODE
							,LINECODE
							,MACHINECODE
							,OPERATIONCODE
							,STATIONCODE
							,BARCODE
							,STATUS
							,FAILCOUNT
							,DATECODE
							,PARTNO
							,RESULTTIMESTAMP
							,SCANTIMESTAMP
							,USERID
							,ProductionOrderNo
							,PROD_LOT_NO
							,Live_Datecode
							)
						SELECT @ProfitCenterCode
							,@LineCode
							,'MCIG'
							,'OCIG'
							,'1'
							,@BARCODE
							,'PS'
							,0
							,@V_DateCode
							,@PARTNO
							,GETDATE()
							,GETDATE()
							,@USERID
							,@ProductionOrderNo
							,@lotSerialNo
							,@Live_Datecode

						--UPDATE PRINTED BARCODE COUNTER
						EXEC Assy_Proc_Barcode_Printed_Counter @CONDITION = 'UPDATE'
							,@LINECODE = @LINECODE
							,@PROFITCENTERCODE = @PROFITCENTERCODE

						UPDATE ASSY_RUNNINGPART
						SET PRINTEDQTY = ISNULL(PRINTEDQTY, 0) + 1
						WHERE LINECODE = @LINECODE
							AND CURRENTPLANNEDQTY > ISNULL(PRINTEDQTY, 0)

						EXEC ASSY_PROC_WIP_MANAGE @CONDITION = 'UPDATE_WIP_COUNT'
							,@LINECODE = @LINECODE
							,@MACHINECODE = 'MCIG'
							,@BARCODE = @BARCODE
							,@PROFITCENTERCODE = @PROFITCENTERCODE
					END
				END
			END

			---------------------------------------------------------------------------------------
			SELECT @LOT_NO = ISNULL(PROD_LOT_NO, '')
			FROM ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
			WHERE ProfitCenterCode = @ProfitCenterCode
				AND LineCode = @LineCode
				AND PartNo = @PARTNO
				AND Barcode = @BARCODE
				AND OperationCode = 'OCIG'

			SELECT @REWORK_CURRENT_PLANQTY = CURRENTPLANNEDQTY
			FROM ASSY_BARCODE_PRINTED_COUNTER WITH (NOLOCK)
			WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE

			-- Commented By Sachin 13-11-2018
			--   IF CHARINDEX(':',@BARCODE) <> 0 AND ISNULL(@BARCODE,'') <> '' 
			--   BEGIN
			--		SET @ISSTMC = 1
			--		SELECT DISTINCT @LINECODE_STMC =  ISNULL(LINECODE, '') , @DATECODE_TEMP = ISNULL(DATECODE, '')  FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK) 
			--		WHERE  PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE=@LINECODE AND MACHINECODE =@MACHINECODE  AND BARCODE = @BARCODE  
			--		SET @DATECODE = @DATECODE_TEMP
			--		IF(@LINECODE_STMC)<>''
			--		BEGIN
			--			  SELECT DISTINCT @PARTNUMBER=ISNULL(STMC_PART_NO, ''),@DATECODE=DATECODE FROM DBO.ASSY_COUPLINGDETAILS(NOLOCK) WHERE FG_BARCODE = @BARCODE AND LINECODE = @LINECODE
			--		END
			--		ELSE
			--		  BEGIN
			--				 SELECT DISTINCT @PARTNUMBER=ISNULL(STMC_PART_NO, ''),@LINECODE_STMC=LINECODE,@DATECODE=DATECODE FROM DBO.ASSY_COUPLINGDETAILS(NOLOCK) WHERE FG_BARCODE = @BARCODE 
			--				 AND LINECODE = @LINECODE AND PROFITCENTRECODE=@PROFITCENTERCODE
			--		  END
			--		  print 1
			--		  IF ISNULL(@PARTNUMBER,'') =''
			--		  BEGIN
			--				SET @RETURNINT=1
			--				SET @RETURNVALUE='SCAN_ONLY_VALID_BARCODE'						
			--				--UPDATE INCORRECT LABEL
			--				IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
			--				BEGIN
			--					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
			--					,@BARCODE=@BARCODE,@HMIMESSAGE='SCAN ONLY VALID BARCODE'
			--				END
			--				COMMIT TRAN
			--				RETURN
			--		  END
			--END				
			--ELSE 
			IF @ISSTMC = 0
				AND ISNULL(@BARCODE, '') <> ''
			BEGIN
				-- commented by Sachin 20170928 -- Vision System not used in ABS Line
				--GET DATECODE AND PART NO OF SNANNED BARCODE FROM VISION SYSTEM
				--SELECT @PARTNUMBER=PARTNO,@DATECODETEMP=DATECODE FROM DBO.ASSY_FN_GET_BARCODEPARTS_FROM_BARCODE(@PROFITCENTERCODE,@LINECODE,@BARCODE)							
				--SET @DATECODE=@DATECODETEMP
				SELECT @DATECODE = Datecode
					,@PARTNUMBER = PartNo
				FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
				WHERE BARCODE = @BARCODE
					AND LINECODE = @LINECODE
					AND MACHINECODE = 'MCIG'
					AND OperationCode = 'OCIG'
					AND ProfitcenterCode = @PROFITCENTERCODE
			END

			--GET FINAL VIEWING OPERATION CODE FROM LINE CODE
			SELECT @FINALVIEWING_OPERATIONCODE = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)

			SELECT @POKAYOKEDATECODE = DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'POKAYOKE', 'POKAYOKE_DATECODE', @PROFITCENTERCODE)

			--CHECK SCANNED BARCODE IS A VALID BARCODE OR NOT							
			IF NOT EXISTS (
					SELECT 1
					FROM DBO.ASSY_RUNNINGPART(NOLOCK)
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE
					)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'PART HAS NOT BEEN SELECTED AT SET PARAMETER SCREEN.'

				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
						,@LINECODE = @LINECODE
						,@OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE
						,@HMIMESSAGE = 'PART NOT SELECTED IN SET PARAMETER'
				END

				COMMIT TRAN

				RETURN
			END

			--Commnted by sachin to testing rework part
			--IF NOT EXISTS
			--(  
			--	SELECT 1 FROM ASSY_RUNNINGPART(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE  AND ASSY_MODE='PRODUCTION'
			--)
			--BEGIN
			--				SET @RETURNINT=1
			--				SET @RETURNVALUE='PART HAS BEEN SELECTED BUT MODE IS NOT PRODUCTION / REWORK.'				
			--				--UPDATE INCORRECT LABEL
			--					IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
			--					BEGIN
			--						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
			--						,@BARCODE=@BARCODE,@HMIMESSAGE='MODE IS NOT PRODUCTION IN SET PARAMETER'
			--					END
			--				COMMIT TRAN
			--				RETURN
			--END
			IF ISNULL(@PARTNUMBER, '') = ''
				AND @ISSTMC = 0
			BEGIN
				IF CHARINDEX(@POKAYOKEDATECODE, @BARCODE) = 0
				BEGIN
					IF (@IsImportBarcodeMode = 0)
					BEGIN
						--Check DUPLICATE_LABEL GET TESTING TIME OF PARTICULAR BARCODE
						IF @OPERATIONCODE = @FINALVIEWING_OPERATIONCODE
						BEGIN
							SELECT @PARTTESTINGTIME = RESULTTIMESTAMP
							FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
							WHERE PROFITCENTERCODE = @PROFITCENTERCODE
								AND LINECODE = @LINECODE
								AND MACHINECODE = @MACHINECODE
								AND BARCODE = @BARCODE
								AND ISNULL(STATUS, '') = 'PS'

							IF @PARTTESTINGTIME IS NULL
							BEGIN
								SELECT @PARTTESTINGTIME = RESULTTIMESTAMP
								FROM DBO.ASSY_LINEASSYSTATUS(NOLOCK)
								WHERE PROFITCENTERCODE = @PROFITCENTERCODE
									AND LINECODE = @LINECODE
									AND MACHINECODE = @MACHINECODE
									AND BARCODE = @BARCODE
									AND ISNULL(STATUS, '') = 'PS'
							END

							IF (@PARTTESTINGTIME IS NOT NULL)
							BEGIN
								SET @RETURNINT = 1
								SET @RETURNVALUE = 'DUPLICATE_LABEL^' + CONVERT(VARCHAR(100), @PARTTESTINGTIME)

								COMMIT TRAN

								RETURN
							END
						END

						----		   
						SET @RETURNINT = 1
						SET @RETURNVALUE = 'SCAN_ONLY_VALID_BARCODE'

						--UPDATE INCORRECT LABEL
						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
								,@LINECODE = @LINECODE
								,@OPERATIONCODE = @OPERATIONCODE
								,@BARCODE = @BARCODE
								,@HMIMESSAGE = 'SCAN ONLY VALID BARCODE'
						END

						COMMIT TRAN

						RETURN
					END
					ELSE
					BEGIN
						SET @PARTNUMBER = @PARTNO
						SET @DATECODE = @V_DateCode
					END
				END
				ELSE IF CHARINDEX(@POKAYOKEDATECODE, @BARCODE) > 0
				BEGIN
					IF NOT EXISTS (
							SELECT 1
							FROM DBO.ASSY_POKAYOKE(NOLOCK)
							WHERE PROFITCENTERCODE = @PROFITCENTERCODE
								AND LINECODE = @LINECODE
								AND BARCODE = @BARCODE
							)
					BEGIN
						SET @RETURNINT = 1
						SET @RETURNVALUE = 'THIS_POKA_YOKE_IS_NOT_DEFINE_IN_POKA_YOKE_MASTER.'

						--UPDATE INCORRECT LABEL
						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
								,@LINECODE = @LINECODE
								,@OPERATIONCODE = @OPERATIONCODE
								,@BARCODE = @BARCODE
								,@HMIMESSAGE = 'THIS POKA YOKE IS NOT DEFINE IN POKA YOKE MASTER.'
						END

						COMMIT TRAN

						RETURN
					END

					--GET POKA YOKE  PART NO AND DATE CODE						  
					SELECT @PARTNUMBER = PARTNUMBER
						,@DATECODE = DATECODE
					FROM DBO.ASSY_POKAYOKE(NOLOCK)
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE
						AND BARCODE = @BARCODE
				END
			END

			IF (@ISSTMC = 1)
			BEGIN
				IF (ISNULL(@LINECODE_STMC, '') <> @LINECODE)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'BARCODE_HAVING_DIFFERENT_LINE_CODE'

					--UPDATE INCORRECT LABEL
					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
							,@LINECODE = @LINECODE
							,@OPERATIONCODE = @OPERATIONCODE
							,@BARCODE = @BARCODE
							,@HMIMESSAGE = 'BARCODE HAVING DIFFERENT LINE CODE'
					END

					COMMIT TRAN

					RETURN
				END
			END
			ELSE
			BEGIN
				--CHECK SCANNED BARCODE HAVING CORRECT LINE CODE OR NOT
				-- modified by sachin 20170720 -- check for line code validation if Bypass Not
				-- required to check. 
				IF OBJECT_ID('DBO.ROUTINGCONFIGDETAILS', 'U') IS NOT NULL
				BEGIN
					DECLARE @isActive VARCHAR(2) = ''

					SELECT @isActive = KeyValue
					FROM ROUTINGCONFIGDETAILS(NOLOCK)
					WHERE ProfitCenterCode = @PROFITCENTERCODE
						AND LineCode = @LINECODE
						AND STS_CD = 0
						AND KeyType = 'isValidateLineCode'

					IF (@isActive = 1)
					BEGIN
						IF CHARINDEX(@LINECODE, @BARCODE) = 0
						BEGIN
							SET @RETURNINT = 1
							SET @RETURNVALUE = 'BARCODE_HAVING_DIFFERENT_LINE_CODE'

							--UPDATE INCORRECT LABEL
							IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
							BEGIN
								EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
									,@LINECODE = @LINECODE
									,@OPERATIONCODE = @OPERATIONCODE
									,@BARCODE = @BARCODE
									,@HMIMESSAGE = 'BARCODE HAVING DIFFERENT LINE CODE'
							END

							COMMIT TRAN

							RETURN
						END
					END
				END
				ELSE
				BEGIN
					IF CHARINDEX(@LINECODE, @BARCODE) = 0
					BEGIN
						SET @RETURNINT = 1
						SET @RETURNVALUE = 'BARCODE_HAVING_DIFFERENT_LINE_CODE'

						--UPDATE INCORRECT LABEL
						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
								,@LINECODE = @LINECODE
								,@OPERATIONCODE = @OPERATIONCODE
								,@BARCODE = @BARCODE
								,@HMIMESSAGE = 'BARCODE HAVING DIFFERENT LINE CODE'
						END

						COMMIT TRAN

						RETURN
					END
				END
			END

			-- CHECK IF POKA YOKA MANDATORY
			DECLARE @ISPOKAYOKECOMPLETED BIT

			IF (
					SELECT ISNULL(ISPOKAYOKEMANDATORY, 0)
					FROM DBO.LINEMST(NOLOCK)
					WHERE LINECODE = @LINECODE
						AND PROFITCENTERCODE = @PROFITCENTERCODE
					) = 1
			BEGIN
				IF EXISTS (
						SELECT DISTINCT 1
						FROM DBO.ROUTINGCONFIGLINEWISE(NOLOCK) L
						WHERE L.LINECODE = @LINECODE
							AND ISNULL(L.POKA_YOKE_ALLOWED, 0) = 1
							AND ISNULL(L.TRACEABILITY, 0) = 1
							AND L.MACHINECODE = @MACHINECODE
							AND L.PROFITCENTERCODE = @PROFITCENTERCODE
						)
				BEGIN
					IF NOT EXISTS (
							SELECT ISNULL(ISPOKAYOKECOMPLETED, 0)
							FROM DBO.ASSY_SCAN_OK(NOLOCK)
							WHERE LINECODE = @LINECODE
								AND OPERATIONCODE = @OPERATIONCODE
								AND MACHINECODE = @MACHINECODE
							)
					BEGIN
						IF CHARINDEX(@POKAYOKEDATECODE, @BARCODE) = 0
						BEGIN
							SET @RETURNINT = 1
							SET @RETURNVALUE = 'POKAYOKE_NOT_DONE'

							IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
							BEGIN
								EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
									,@LINECODE = @LINECODE
									,@OPERATIONCODE = @OPERATIONCODE
									,@BARCODE = @BARCODE
									,@HMIMESSAGE = 'POKA YOKE NOT DONE.'
							END

							COMMIT TRAN

							RETURN
						END
					END

					SELECT @ISPOKAYOKECOMPLETED = ISNULL(ISPOKAYOKECOMPLETED, 0)
					FROM DBO.ASSY_SCAN_OK(NOLOCK)
					WHERE LINECODE = @LINECODE
						AND OPERATIONCODE = @OPERATIONCODE
						AND MACHINECODE = @MACHINECODE

					IF CHARINDEX(@POKAYOKEDATECODE, @BARCODE) <> 0
					BEGIN
						IF (
								@ISPOKAYOKECOMPLETED = 1
								AND DBO.ASSY_FN_ISPARTTESTEDATFV_FORPOKAYOKE(@PROFITCENTERCODE, @LINECODE, @MACHINECODE, @OPERATIONCODE) = 0
								)
						BEGIN
							SET @RETURNINT = 1
							SET @RETURNVALUE = 'POKAYOKE_ALREADY_DONE'

							IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
							BEGIN
								EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
									,@LINECODE = @LINECODE
									,@OPERATIONCODE = @OPERATIONCODE
									,@BARCODE = @BARCODE
									,@HMIMESSAGE = 'POKA YOKE ALREADY DONE.'
							END

							COMMIT TRAN

							RETURN
						END
					END

					IF (
							@ISPOKAYOKECOMPLETED = 0
							AND CHARINDEX(@POKAYOKEDATECODE, @BARCODE) = 0
							)
					BEGIN
						SET @RETURNINT = 1
						SET @RETURNVALUE = 'POKAYOKE_NOT_DONE'

						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
								,@LINECODE = @LINECODE
								,@OPERATIONCODE = @OPERATIONCODE
								,@BARCODE = @BARCODE
								,@HMIMESSAGE = 'POKA YOKE NOT DONE.'
						END

						COMMIT TRAN

						RETURN
					END
				END
			END

			--CHECK SCANNED PART IS CURENTLY RUNNING PART OR NOT
			IF EXISTS (
					SELECT DISTINCT ASSY_PARTNO
					FROM DBO.ASSY_RUNNINGPART(NOLOCK)
					WHERE LINECODE = @LINECODE
						AND ASSY_MODE IN (
							'PRODUCTION'
							,'REWORK'
							)
						AND ISNULL(PARTTYPE, '') = 'STMC'
						AND CHARINDEX(@POKAYOKEDATECODE, @BARCODE) = 0
						AND @ISSTMC = 0
					)
			BEGIN
				IF EXISTS (
						SELECT DISTINCT ASSY_PARTNO
						FROM DBO.ASSY_RUNNINGPART(NOLOCK)
						WHERE LINECODE = @LINECODE
							AND ASSY_MODE IN (
								'PRODUCTION'
								,'REWORK'
								)
							AND SERVO_PARTNO <> @PARTNUMBER
							AND CHARINDEX(@POKAYOKEDATECODE, @BARCODE) = 0
						)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'NOT_RUNNING_PART'

					--UPDATE INCORRECT LABEL
					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
							,@LINECODE = @LINECODE
							,@OPERATIONCODE = @OPERATIONCODE
							,@BARCODE = @BARCODE
							,@HMIMESSAGE = 'NOT CURRENT RUNNING PART 1'
					END

					COMMIT TRAN

					RETURN
				END
			END
					--CHANGED BY RAVI ON 16/08/16 FOR ALLOW TO RUN 2 PARTS AT A TIME FOR JHAGADIA
			ELSE IF EXISTS (
					SELECT 1
					FROM DBO.LINEMST WITH (NOLOCK)
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE
						AND ISNULL(ISACTIVE, 0) = 1
						AND ISNULL(ALLOW2PARTS, 0) = 1
						AND CHARINDEX(@POKAYOKEDATECODE, @BARCODE) = 0
					)
			BEGIN
				--EXEC ASSY_PROC_GET_PREVIOUS_MACHINECODE @LINECODE=@LINECODE ,@MACHINECODE=@MACHINECODE,@PARTNUMBER=@PARTNUMBER
				--	,@PREVMACHINECODE=@PREVMACHINECODE OUTPUT	
				DECLARE @TOTPENDINGPARTS SMALLINT
					,@CURBARCODEDATA VARCHAR(100)
					,@RESULT VARCHAR(5)
					,@CupPart AS INT = - 1

				SELECT @TOTPENDINGPARTS = COUNT(r.BARCODE)
				FROM DBO.ASSY_LINEASSYSTATUS_RUNNING R WITH (NOLOCK)
				LEFT OUTER JOIN dbo.Assy_PreviousPending_Parts p WITH (NOLOCK) ON R.PROFITCENTERCODE = P.PROFITCENTERCODE
					AND R.LINECODE = P.LINECODE
					AND R.MACHINECODE = P.MACHINECODE
					AND ISNULL(P.IS_REJECTED, 0) = 0
				WHERE R.PROFITCENTERCODE = @PROFITCENTERCODE
					AND r.LINECODE = @LINECODE
					AND r.MACHINECODE = @MACHINECODE
					AND ISNULL(r.ISPENDINGPART, 0) = 1
					AND ISNULL(r.STATUS, '') = ''

				SELECT @CupPart = count(r.barcode)
				FROM DBO.ASSY_LINEASSYSTATUS_RUNNING R WITH (NOLOCK)
				LEFT OUTER JOIN dbo.Assy_PreviousPending_Parts p WITH (NOLOCK) ON R.PROFITCENTERCODE = P.PROFITCENTERCODE
					AND R.LINeCODE = P.LINECODE
					AND R.MACHINECODE = P.MACHINECODE
					AND R.barcode = P.barcode
					AND ISNULL(P.IS_REJECTED, 0) = 0
				WHERE R.PROFITCENTERCODE = @PROFITCENTERCODE
					AND r.LINECODE = @LINECODE
					AND r.MACHINECODE = @MACHINECODE
					AND ISNULL(r.ISPENDINGPART, 0) = 0
					AND r.BARCODE = @BARCODE

				IF @TOTPENDINGPARTS > 0
					AND @CupPart > 0
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'PREVIOUS_PENDING_PARTS'

					--UPDATE INCORRECT LABEL
					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
							,@LINECODE = @LINECODE
							,@OPERATIONCODE = @OPERATIONCODE
							,@BARCODE = @BARCODE
							,@HMIMESSAGE = 'PREVIOUS PENDING PARTS'
					END

					COMMIT TRAN

					RETURN
				END
				ELSE IF NOT EXISTS (
						SELECT PARTNO
						FROM (
							SELECT TOP 1 ASSY_PARTNO AS PARTNO
							FROM DBO.ASSY_RUNNINGPART(NOLOCK)
							WHERE PROFITCENTERCODE = @PROFITCENTERCODE
								AND LINECODE = @LINECODE
							ORDER BY CREATEDDATE DESC
							
							UNION
							
							SELECT DISTINCT PARTNO
							FROM DBO.ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK)
							WHERE PROFITCENTERCODE = @PROFITCENTERCODE
								AND LINECODE = @LINECODE
								--AND ISNULL(ISPENDINGPART,0)=1
							) A
						WHERE PARTNO = @PARTNUMBER
						)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'NOT_RUNNING_PART'

					--UPDATE INCORRECT LABEL
					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
							,@LINECODE = @LINECODE
							,@OPERATIONCODE = @OPERATIONCODE
							,@BARCODE = @BARCODE
							,@HMIMESSAGE = 'NOT CURRENT RUNNING PART 2'
					END

					COMMIT TRAN

					RETURN
				END
			END
					--CHANGED BY RAVI ON 12/08/16 FOR ALLOW TO RUN 2 PARTS AT A TIME FOR JHAGADIA
			ELSE IF EXISTS (
					SELECT DISTINCT ASSY_PARTNO
					FROM DBO.ASSY_RUNNINGPART(NOLOCK)
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE
						AND ASSY_PARTNO <> @PARTNUMBER
						AND CHARINDEX(@POKAYOKEDATECODE, @BARCODE) = 0
					)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'NOT_RUNNING_PART'

				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
						,@LINECODE = @LINECODE
						,@OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE
						,@HMIMESSAGE = 'NOT CURRENT RUNNING PART 3'
				END

				COMMIT TRAN

				RETURN
			END

			--CHECK FOR JIG IN/OUT STATUS
			IF EXISTS (
					SELECT 1
					FROM DBO.MACHINEMST WITH (NOLOCK)
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND MACHINECODE = @MACHINECODE
						AND INDEXPERSTATIONS = 1
					)
			BEGIN
				IF EXISTS (
						SELECT 1
						FROM DBO.ASSY_STATIONS_ZIG_IN_OUT_STATUS(NOLOCK)
						WHERE LINECODE = @LINECODE
							AND OPERATIONCODE = @OPERATIONCODE
							AND STATUSINOUT = 1
						)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'JIG_IS_INSIDE'

					COMMIT TRAN

					RETURN
				END
			END

			DECLARE @LINETYPE VARCHAR(20)
			DECLARE @TVLINETYPE AS TABLE (LINETYPE VARCHAR(20))

			SELECT @LINETYPE = LT.LINETYPENAME
			FROM DBO.LINETYPEMST(NOLOCK) LT
			INNER JOIN DBO.LINEMST(NOLOCK) LM ON LT.LINETYPECODE = LM.LINETYPECODE
			WHERE LM.LINECODE = @LINECODE

			IF @LINETYPE = 'STMC'
			BEGIN
				INSERT INTO @TVLINETYPE (LINETYPE)
				SELECT 'SERVO'
				
				UNION
				
				SELECT 'STMC'
			END
			ELSE IF @LINETYPE = 'TMC'
			BEGIN
				INSERT INTO @TVLINETYPE (LINETYPE)
				SELECT 'TMC'
			END
			ELSE IF @LINETYPE = 'CALIPER'
			BEGIN
				INSERT INTO @TVLINETYPE (LINETYPE)
				SELECT 'CALIPER'
			END

			--CHECK PART EXISTS IN PRODUCT MASTER
			IF NOT EXISTS (
					SELECT DISTINCT 1
					FROM DBO.PRODUCT_MASTER(NOLOCK)
					WHERE WAREHOUSE_CD = @PROFITCENTERCODE
						AND SEWS_PART_NO = @PARTNUMBER
						AND ISNULL(MATERIAL_TP, '') IN (
							SELECT LINETYPE
							FROM @TVLINETYPE
							)
					)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'PART_DOES_NOT_EXISTS_IN_PRODUCT_MASTER'

				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
						,@LINECODE = @LINECODE
						,@OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE
						,@HMIMESSAGE = 'PART DOES NOT EXISTS IN PRODUCT MASTER'
				END

				COMMIT TRAN

				RETURN
			END

			--CHECK PART  ACTIVE IN PRODUCT MASTER
			IF NOT EXISTS (
					SELECT DISTINCT 1
					FROM DBO.PRODUCT_MASTER(NOLOCK)
					WHERE WAREHOUSE_CD = @PROFITCENTERCODE
						AND SEWS_PART_NO = @PARTNUMBER
						AND STS_CD = 0
						AND ISNULL(MATERIAL_TP, '') IN (
							SELECT LINETYPE
							FROM @TVLINETYPE
							)
					)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'PART_NOT_ACTIVE_IN_PRODUCT_MASTER'

				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
						,@LINECODE = @LINECODE
						,@OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE
						,@HMIMESSAGE = 'PART NOT ACTIVE IN PRODUCT MASTER'
				END

				COMMIT TRAN

				RETURN
			END

			-- ADDED BY RASHID REWORK 11TH MAY 2016
			IF EXISTS (
					SELECT 1
					FROM ASSY_RUNNINGPART(NOLOCK)
					WHERE LINECODE = @LINECODE
						AND ASSY_MODE IN (
							'PRODUCTION'
							,'REWORK'
							)
					)
			BEGIN
				--CHECK PART HAS ALREADY PROCESSED IN TALLY  CHART
				IF EXISTS (
						-- ADDED BY RASHID REWORK 11TH MAY 2016 CHANGE TABLE FROM ASSY_TALLYCHARTSTATUSDATA TO ASSY_TALLYCHARTSTATUSDATA_HISTORY
						SELECT TOP 1 1
						FROM ASSY_TALLYCHARTSTATUSDATA(NOLOCK)
						WHERE BARCODE = @BARCODE
							AND ISNULL(ASSY_AUTH, 0) = 0
							AND ISNULL(NOTPROCESSEDSTATUS, '') <> ''
							AND LINECODE = @LINECODE
							AND PROFITCENTERCODE = @PROFITCENTERCODE
						)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'PART_HAS_ALREADY_PROCESSED_IN_CURRENT_TALLYCHART'

					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
							,@LINECODE = @LINECODE
							,@OPERATIONCODE = @OPERATIONCODE
							,@BARCODE = @BARCODE
							,@HMIMESSAGE = 'PART HAS ALREADY PROCESSED IN CURRENT TALLYCHART'
					END

					COMMIT TRAN

					RETURN
				END
			END

			IF EXISTS (
					SELECT 1
					FROM ASSY_RUNNINGPART(NOLOCK)
					WHERE LINECODE = @LINECODE
						AND ASSY_MODE = 'PRODUCTION'
					)
			BEGIN
				IF EXISTS (
						-- ADDED BY RASHID REWORK 11TH MAY 2016 CHANGE TABLE FROM ASSY_TALLYCHARTSTATUSDATA TO ASSY_TALLYCHARTSTATUSDATA_HISTORY
						SELECT TOP 1 1
						FROM ASSY_TALLYCHARTSTATUSDATA_HISTORY(NOLOCK)
						WHERE BARCODE = @BARCODE
							AND (
								ISNULL(ASSY_AUTH, 0) = 1
								OR ISNULL(NOTPROCESSEDSTATUS, '') <> ''
								)
							AND LINECODE = @LINECODE
							AND PROFITCENTERCODE = @PROFITCENTERCODE
							AND ISNULL(ISREWORKAPPUSE, 0) = 0 -- added by sachin 20170926
						)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'PART_HAS_ALREADY_PROCESSED_IN_TALLYCHART'

					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
							,@LINECODE = @LINECODE
							,@OPERATIONCODE = @OPERATIONCODE
							,@BARCODE = @BARCODE
							,@HMIMESSAGE = 'PART HAS ALREADY PROCESSED IN TALLYCHART'
					END

					COMMIT TRAN

					RETURN
				END
			END

			--CHECK DATECODE VALIDATION IS  REQUIRED FOR THIS LINE OR NOT
			IF EXISTS (
					SELECT 1
					FROM DBO.LINEMST(NOLOCK)
					WHERE LINECODE = @LINECODE
						AND PROFITCENTERCODE = @PROFITCENTERCODE
						AND ISNULL(VALIDATE_DATECODE, 0) = 1
						AND ISNULL(ISACTIVE, 0) = 1
					)
			BEGIN
				IF (@ISSTMC = 0)
				BEGIN
					IF @DATECODE <> (
							SELECT ISNULL(DATECODE, '')
							FROM DBO.ASSY_DATECODE_MODE(NOLOCK)
							WHERE LINECODE = @LINECODE
							)
					BEGIN
						SET @RETURNINT = 1
						SET @RETURNVALUE = 'DATE_CODE_NOT_MATCHING'

						--UPDATE INCORRECT LABEL
						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
								,@LINECODE = @LINECODE
								,@OPERATIONCODE = @OPERATIONCODE
								,@BARCODE = @BARCODE
								,@HMIMESSAGE = 'DATE CODE NOT MATCHING'
						END

						COMMIT TRAN

						RETURN
					END
				END

				IF @DATECODE <> (
						SELECT TOP 1 DATECODE
						FROM ASSY_RUNNINGPART(NOLOCK)
						WHERE LINECODE = @LINECODE
							AND ASSY_MODE IN (
								'PRODUCTION'
								,'REWORK'
								)
						)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'DATE_CODE_NOT_MATCHING'

					--UPDATE INCORRECT LABEL
					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
							,@LINECODE = @LINECODE
							,@OPERATIONCODE = @OPERATIONCODE
							,@BARCODE = @BARCODE
							,@HMIMESSAGE = 'DATE CODE NOT MATCHING'
					END

					COMMIT TRAN

					RETURN
				END
			END

			--CHECK A PART HAS ALREADY SCANNED ON LH AND SAME PART USER SCANS ON RH AND VICE VERSA
			IF EXISTS (
					SELECT 1
					FROM DBO.MACHINEMST(NOLOCK)
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND MACHINECODE = @MACHINECODE
						AND ISNULL(NOOFSTATIONS, 0) > 1
					)
			BEGIN
				IF EXISTS (
						SELECT 1
						FROM DBO.ASSY_SCAN_OK(NOLOCK)
						WHERE LINECODE = @LINECODE
							AND MACHINECODE = @MACHINECODE
							AND OPERATIONCODE <> @OPERATIONCODE
							AND BARCODE = @BARCODE
						)
				BEGIN
					DECLARE @STATIONNAME AS VARCHAR(100)

					SELECT @STATIONNAME = RTRIM(LTRIM(OPERATIONNAME))
					FROM DBO.OPERATIONMST(NOLOCK)
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND OPERATIONCODE = (
							SELECT OPERATIONCODE
							FROM DBO.ASSY_SCAN_OK(NOLOCK)
							WHERE LINECODE = @LINECODE
								AND MACHINECODE = @MACHINECODE
								AND OPERATIONCODE <> @OPERATIONCODE
								AND BARCODE = @BARCODE
							)

					SET @RETURNINT = 1
					SET @RETURNVALUE = 'ALREADY_SCANNED_ON_OTHER_STATION^' + @STATIONNAME

					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
							,@LINECODE = @LINECODE
							,@OPERATIONCODE = @OPERATIONCODE
							,@BARCODE = @BARCODE
							,@HMIMESSAGE = 'ALREADY SCANNED ON OTHER STATION'
					END

					COMMIT TRAN

					RETURN
				END
			END

			--VALIDATE POKA YOKE-------------------------------------------------------------------------------------------------	
			--CHECK POKA YOKE REQUIRED FOR PARTICULAR OPERATION
			IF CHARINDEX(@POKAYOKEDATECODE, @BARCODE) <> 0
			BEGIN
				--IF POKA YOKE NOT REQUIRED FOR THIS LINE-SHOW MESSAGE TO USER	
				IF NOT EXISTS (
						SELECT TOP 1 1
						FROM DBO.LINEMST(NOLOCK)
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE
							AND LINECODE = @LINECODE
							AND ISNULL(ISACTIVE, 0) = 1
							AND ISNULL(ISPOKAYOKEMANDATORY, 0) = 1
						)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'POKA_YOKE_NOT_REQUIRED_FOR_THIS_LINE'

					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
						,@LINECODE = @LINECODE
						,@OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE
						,@HMIMESSAGE = 'POKA YOKE NOT REQUIRED FOR THIS LINE.'

					COMMIT TRAN

					RETURN
				END

				--IF POKA YOKE NOT REQUIRED FOR A PARTICULAR OPERATION IN LINE WISE ROUTNING-SHOW MESSAGE TO USER		
				IF NOT EXISTS (
						SELECT DISTINCT 1
						FROM DBO.ROUTINGCONFIGLINEWISE(NOLOCK) L
						WHERE L.LINECODE = @LINECODE
							AND ISNULL(L.POKA_YOKE_ALLOWED, 0) = 1
							AND ISNULL(L.TRACEABILITY, 0) = 1
							AND L.MACHINECODE = @MACHINECODE
							AND L.PROFITCENTERCODE = @PROFITCENTERCODE
						)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'POKA_YOKE_NOT_REQUIRED_FOR_THIS_MACHINE'

					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
						,@LINECODE = @LINECODE
						,@OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE
						,@HMIMESSAGE = 'POKA YOKE NOT REQUIRED FOR THIS MACHINE'

					COMMIT TRAN

					RETURN
				END

				--CHECK POKA YOKE NOT DEFINED FOR THIS MACHINE OR NOT IN ASSY_POKAYOKE
				IF NOT EXISTS (
						SELECT DISTINCT 1
						FROM DBO.ASSY_POKAYOKE(NOLOCK)
						WHERE LINECODE = @LINECODE
							AND PROFITCENTERCODE = @PROFITCENTERCODE
							AND MACHINECODE = @MACHINECODE
							AND BARCODE = @BARCODE
						)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'POKA_YOKE_NOT_DEFINED_FOR_THIS_MACHINE'

					--UPDATE INCORRECT LABEL											
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
						,@LINECODE = @LINECODE
						,@OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE
						,@HMIMESSAGE = 'POKA YOKE HAS NOT DEFINED FOR THIS MACHINE'

					COMMIT TRAN

					RETURN
				END

				--CHECK POKA YOKE DEFINED FOR THIS MACHINE AND ACTIVE
				IF NOT EXISTS (
						SELECT DISTINCT 1
						FROM DBO.ASSY_POKAYOKE(NOLOCK)
						WHERE LINECODE = @LINECODE
							AND PROFITCENTERCODE = @PROFITCENTERCODE
							AND MACHINECODE = @MACHINECODE
							AND BARCODE = @BARCODE
							AND ISNULL(ISACTIVE, 0) = 1
						)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'POKA_YOKE_DEFINED_BUT_NOT_ACTIVE'

					--UPDATE INCORRECT LABEL											
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
						,@LINECODE = @LINECODE
						,@OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE
						,@HMIMESSAGE = 'POKA YOKE HAS NOT BEEN ACTIVE THIS MACHINE'

					COMMIT TRAN

					RETURN
				END

				--CHECK POKA YOKE HAS BEEN EXPIRED
				IF EXISTS (
						SELECT DISTINCT 1
						FROM DBO.ASSY_POKAYOKE(NOLOCK)
						WHERE LINECODE = @LINECODE
							AND PROFITCENTERCODE = @PROFITCENTERCODE
							AND MACHINECODE = @MACHINECODE
							AND BARCODE = @BARCODE
							AND CONVERT(DATE, EXPIRYDATE, 103) < CONVERT(DATE, GETDATE(), 103)
						)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'POKA_YOKE_HAS_BEEN_EXPIRED'

					--UPDATE INCORRECT LABEL											
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
						,@LINECODE = @LINECODE
						,@OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE
						,@HMIMESSAGE = 'POKA YOKE HAS BEEN EXPIRED'

					COMMIT TRAN

					RETURN
				END

				--CHECK GROUP HAS  DEFINED FOR SCANNED PART IN ROUTING PART WISE
				IF EXISTS (
						SELECT TOP 1 1
						FROM DBO.ROUTINGCONFIGPARTWISE(NOLOCK)
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE
							AND ISNULL(PARTNO, 0) = @PARTNUMBER
							AND ISNULL(PART_FIXTUREGROUPTYPE, '') = ''
						)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'GROUP_HAS_NOT_DEFINED_FOR_THIS_PART_IN_PARTWISE_ROUTING.'

					--UPDATE INCORRECT LABEL										
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
						,@LINECODE = @LINECODE
						,@OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE
						,@HMIMESSAGE = 'GROUP HAS NOT DEFINED FOR THIS PART IN PART WISE ROUTING.'

					COMMIT TRAN

					RETURN
				END

				--CHECKING IF PART IN PRODUCTION AND SCANNED IN POKA YOKA ARE SAME
				IF NOT EXISTS (
						SELECT TOP 1 1
						FROM DBO.ASSY_RUNNINGPART WITH (NOLOCK)
						WHERE ASSY_PARTNO = @PARTNUMBER
							AND LINECODE = @LINECODE
							AND ASSY_MODE IN (
								'PRODUCTION'
								,'REWORK'
								)
						)
				BEGIN
					--CHECK WHETHER SELECTED RUNNING PART AND SCANNED PART BELONGS TO SAME GROUP OR NOT.
					SELECT @PART_FIXTUREGROUPTYPE_COUNT = COUNT(PART_FIXTUREGROUPTYPE)
					FROM (
						--FIND THE GROUP FOR RUNNING PART SELECTED FROM ASSY RUNNING PART TABLE.
						SELECT DISTINCT PART_FIXTUREGROUPTYPE
						FROM DBO.ROUTINGCONFIGPARTWISE(NOLOCK)
						WHERE MACHINECODE = @MACHINECODE
							AND PROFITCENTERCODE = @PROFITCENTERCODE
							AND PARTNO IN (
								SELECT DISTINCT ISNULL(ASSY_PARTNO, '') PARTNUMBER
								FROM DBO.ASSY_RUNNINGPART(NOLOCK)
								WHERE LINECODE = @LINECODE
									AND ASSY_MODE IN (
										'PRODUCTION'
										,'REWORK'
										)
								)
						
						UNION
						
						--GET THE GROUP FOR SCANNED BARCODE FROM POKA YOKE MASTER TABLE.
						SELECT DISTINCT PART_FIXTUREGROUPTYPE
						FROM DBO.ROUTINGCONFIGPARTWISE(NOLOCK)
						WHERE MACHINECODE = @MACHINECODE
							AND PROFITCENTERCODE = @PROFITCENTERCODE
							AND PARTNO IN (
								SELECT DISTINCT ISNULL(PARTNUMBER, '') PARTNUMBER
								FROM DBO.ASSY_POKAYOKE(NOLOCK)
								WHERE BARCODE = @BARCODE
									AND MACHINECODE = @MACHINECODE
									AND PROFITCENTERCODE = @PROFITCENTERCODE
									AND LINECODE = @LINECODE
									AND ISNULL(ISACTIVE, 0) = 1
								)
						) TBL

					IF @PART_FIXTUREGROUPTYPE_COUNT <> 1
					BEGIN
						SET @RETURNINT = 1
						SET @RETURNVALUE = 'RUNNING_PART_AND_SCANNED_POKA_YOKE_DOES_NOT_BELONGS_IN_SAME_GROUP'

						--UPDATE INCORRECT LABEL												
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
							,@LINECODE = @LINECODE
							,@OPERATIONCODE = @OPERATIONCODE
							,@BARCODE = @BARCODE
							,@HMIMESSAGE = 'RUNNING PART AND SCANNED POKA YOKE DOES NOT BELONGS IN SAME GROUP.'

						COMMIT TRAN

						RETURN
					END
				END

				--CHECK FOR DUPLICATE LABEL 
				IF (DBO.ASSY_FN_ISPARTTESTEDATFV_FORPOKAYOKE(@PROFITCENTERCODE, @LINECODE, @MACHINECODE, @OPERATIONCODE) = 0)
				BEGIN
					IF EXISTS (
							SELECT TOP 1 BARCODE
							FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
							WHERE PROFITCENTERCODE = @PROFITCENTERCODE
								AND LINECODE = @LINECODE
								AND MACHINECODE = @MACHINECODE
								AND OPERATIONCODE = @OPERATIONCODE
								AND BARCODE = @BARCODE
								AND ISNULL(STATUS, '') <> ''
							)
					BEGIN
						--UPDATE ASSY_DUPLICATELABEL  TABLE										
						IF EXISTS (
								SELECT DISTINCT 1
								FROM DBO.ASSY_DUPLICATELABEL(NOLOCK)
								WHERE LINECODE = @LINECODE
									AND OPERATIONCODE = @OPERATIONCODE
								)
						BEGIN
							UPDATE ASSY_DUPLICATELABEL
							SET ISDUPLICATE = 1
								,BARCODE = @BARCODE
							WHERE LINECODE = @LINECODE
								AND OPERATIONCODE = @OPERATIONCODE

							--RESET SCAN OK
							UPDATE ASSY_SCAN_OK
							SET ISSCAN = 0
							WHERE LINECODE = @LINECODE
								AND OPERATIONCODE = @OPERATIONCODE

							--RESET   INCORRECT LABEL
							UPDATE ASSY_INCORRECTLABEL
							SET HMIMESSAGECODE = ''
								,ISINCORRECT = 0
							WHERE LINECODE = @LINECODE
								AND OPERATIONCODE = @OPERATIONCODE
						END
						ELSE
						BEGIN
							INSERT INTO ASSY_DUPLICATELABEL (
								LINECODE
								,OPERATIONCODE
								,STATIONCODE
								,BARCODE
								,ISDUPLICATE
								)
							SELECT @LINECODE
								,@OPERATIONCODE
								,@STATIONCODE
								,@BARCODE
								,1

							--RESET SCAN OK
							UPDATE ASSY_SCAN_OK
							SET ISSCAN = 0
							WHERE LINECODE = @LINECODE
								AND OPERATIONCODE = @OPERATIONCODE

							--RESET   INCORRECT LABEL
							UPDATE ASSY_INCORRECTLABEL
							SET HMIMESSAGECODE = ''
								,ISINCORRECT = 0
							WHERE LINECODE = @LINECODE
								AND OPERATIONCODE = @OPERATIONCODE
						END

						SET @RETURNINT = 1
						SET @RETURNVALUE = 'THIS POKA YOKE ALREADY DONE.'

						COMMIT TRAN

						RETURN
					END
				END

				--UPDATE SCAN OK RELEATED TABLE
				IF EXISTS (
						SELECT 1
						FROM DBO.MACHINEMST WITH (NOLOCK)
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE
							AND MACHINECODE = @MACHINECODE
							AND INDEXPERSTATIONS = 2
						)
				BEGIN
					DECLARE @SCANNINGSTATION INT

					SELECT @STATIONCODE = STATIONCODE
					FROM DBO.ASSY_STATIONS_ZIG_IN_OUT_STATUS(NOLOCK)
					WHERE LINECODE = @LINECODE
						AND OPERATIONCODE = @OPERATIONCODE

					IF @STATIONCODE = 1
						SET @SCANNINGSTATION = 2
					ELSE IF @STATIONCODE = 2
						SET @SCANNINGSTATION = 1
					SET @STATIONCODE = @SCANNINGSTATION

					IF EXISTS (
							SELECT DISTINCT 1
							FROM DBO.ASSY_SCAN_OK(NOLOCK)
							WHERE PROFITCENTERCODE = @PROFITCENTERCODE
								AND LINECODE = @LINECODE
								AND OPERATIONCODE = @OPERATIONCODE
								AND MACHINECODE = @MACHINECODE
								AND STATIONCODE = @SCANNINGSTATION
							)
					BEGIN
						UPDATE ASSY_SCAN_OK
						SET ISSCAN = 1
							,BARCODE = @BARCODE
							,ASSY_PARTNO = @PARTNUMBER
							,DATECODE = @DATECODE
							,CREATEDBY = @USERID
							,CREATEDDATE = GETDATE()
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE
							AND LINECODE = @LINECODE
							AND OPERATIONCODE = @OPERATIONCODE
							AND MACHINECODE = @MACHINECODE
							AND STATIONCODE = @SCANNINGSTATION
					END
					ELSE
					BEGIN
						INSERT INTO ASSY_SCAN_OK (
							PROFITCENTERCODE
							,LINECODE
							,OPERATIONCODE
							,STATIONCODE
							,BARCODE
							,ISSCAN
							,MACHINECODE
							,ASSY_PARTNO
							,DATECODE
							,CREATEDBY
							,CREATEDDATE
							)
						SELECT @PROFITCENTERCODE
							,@LINECODE
							,@OPERATIONCODE
							,@SCANNINGSTATION
							,@BARCODE
							,1
							,@MACHINECODE
							,@PARTNUMBER
							,@DATECODE
							,@USERID
							,GETDATE()
					END

					--RESET   INCORRECT LABEL
					UPDATE ASSY_INCORRECTLABEL
					SET HMIMESSAGECODE = ''
						,ISINCORRECT = 0
					WHERE LINECODE = @LINECODE
						AND OPERATIONCODE = @OPERATIONCODE

					--RESET DUPLICATE LABEL
					UPDATE ASSY_DUPLICATELABEL
					SET ISDUPLICATE = 0
					WHERE LINECODE = @LINECODE
						AND OPERATIONCODE = @OPERATIONCODE
				END
				ELSE IF EXISTS (
						SELECT DISTINCT 1
						FROM DBO.ASSY_SCAN_OK(NOLOCK)
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE
							AND LINECODE = @LINECODE
							AND OPERATIONCODE = @OPERATIONCODE
							AND MACHINECODE = @MACHINECODE
						)
				BEGIN
					UPDATE ASSY_SCAN_OK
					SET ISSCAN = 1
						,BARCODE = @BARCODE
						,ASSY_PARTNO = @PARTNUMBER
						,DATECODE = @DATECODE
						,CREATEDBY = @USERID
						,CREATEDDATE = GETDATE()
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE
						AND OPERATIONCODE = @OPERATIONCODE
						AND MACHINECODE = @MACHINECODE

					--AND STATIONCODE=@SCANNINGSTATION commented by sachin 20170808 -- during POKA YOKE this value is Null											
					--RESET   INCORRECT LABEL
					UPDATE ASSY_INCORRECTLABEL
					SET HMIMESSAGECODE = ''
						,ISINCORRECT = 0
					WHERE LINECODE = @LINECODE
						AND OPERATIONCODE = @OPERATIONCODE

					--RESET DUPLICATE LABEL
					UPDATE ASSY_DUPLICATELABEL
					SET ISDUPLICATE = 0
					WHERE LINECODE = @LINECODE
						AND OPERATIONCODE = @OPERATIONCODE

					UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE
					SET ISCYCLESTARTED = 0
						,BARCODE = @BARCODE
						,TIMESTAMP = GETDATE()
					WHERE LINECODE = @LINECODE
						AND MACHINECODE = @MACHINECODE
						AND OPERATIONCODE = @OPERATIONCODE
				END
				ELSE
				BEGIN
					INSERT INTO ASSY_SCAN_OK (
						PROFITCENTERCODE
						,LINECODE
						,OPERATIONCODE
						,STATIONCODE
						,BARCODE
						,ISSCAN
						,MACHINECODE
						,ASSY_PARTNO
						,DATECODE
						,CREATEDBY
						,CREATEDDATE
						)
					SELECT @PROFITCENTERCODE
						,@LINECODE
						,@OPERATIONCODE
						,@SCANNINGSTATION
						,@BARCODE
						,1
						,@MACHINECODE
						,@PARTNUMBER
						,@DATECODE
						,@USERID
						,GETDATE()

					--RESET   INCORRECT LABEL
					UPDATE ASSY_INCORRECTLABEL
					SET HMIMESSAGECODE = ''
						,ISINCORRECT = 0
					WHERE LINECODE = @LINECODE
						AND OPERATIONCODE = @OPERATIONCODE

					--RESET DUPLICATE LABEL
					UPDATE ASSY_DUPLICATELABEL
					SET ISDUPLICATE = 0
					WHERE LINECODE = @LINECODE
						AND OPERATIONCODE = @OPERATIONCODE

					UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE
					SET ISCYCLESTARTED = 0
						,BARCODE = @BARCODE
						,TIMESTAMP = GETDATE()
					WHERE LINECODE = @LINECODE
						AND MACHINECODE = @MACHINECODE
						AND OPERATIONCODE = @OPERATIONCODE
				END

				-- INSERT INTO RUNNING PART TABLE..
				IF EXISTS (
						SELECT DISTINCT 1
						FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE
							AND LINECODE = @LINECODE
							AND MACHINECODE = @MACHINECODE
							AND OPERATIONCODE = @OPERATIONCODE
							AND BARCODE = @BARCODE
							AND ISNULL(STATUS, '') = ''
						)
				BEGIN
					UPDATE ASSY_LINEASSYSTATUS_RUNNING
					SET SCANTIMESTAMP = GETDATE()
						,Live_Datecode = @Live_Datecode
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE
						AND MACHINECODE = @MACHINECODE
						AND OPERATIONCODE = @OPERATIONCODE
						AND BARCODE = @BARCODE
						AND ISNULL(STATUS, '') = ''
				END
				ELSE
				BEGIN
					IF (ISNULL(@DATECODE, '') = '')
					BEGIN
						SET @RETURNINT = 1
						SET @RETURNVALUE = 'Date Code Not Available, Restart Application !!!'
					END

					IF @STMCPARTNO <> ''
						SET @PARTNUMBER = @STMCPARTNO

					--Modified By Sudesh on 20170515 for new column ProductionOrderNo in Table Assy_LineAssyStatus_Running
					INSERT INTO ASSY_LINEASSYSTATUS_RUNNING (
						PROFITCENTERCODE
						,LINECODE
						,MACHINECODE
						,OPERATIONCODE
						,BARCODE
						,DATECODE
						,PARTNO
						,ACTIVE
						,STATIONCODE
						,SCANTIMESTAMP
						,USERID
						,ProductionOrderNo
						,PROD_LOT_NO
						,Live_Datecode
						) -- Added By Sachin By Sachin 20170726
					SELECT @PROFITCENTERCODE
						,@LINECODE
						,@MACHINECODE
						,@OPERATIONCODE
						,@BARCODE
						,CASE @REWORK_MODE
							WHEN 'REWORK'
								THEN @REWORK_DATECODE
							ELSE @DATECODE
							END
						,@PARTNUMBER
						,0
						,@STATIONCODE
						,GETDATE()
						,@USERID
						,@ProductionOrderNo
						,@Lot_No
						,@Live_Datecode -- Added By Sachin By Sachin 20170726
				END

				SET @RETURNINT = 1
				SET @RETURNVALUE = 'SCANNED_SUCCESSFULLY'

				COMMIT TRAN

				RETURN
			END

			--POKA YOKE END BLOCK---------------------------------
			----------CHECK A PART HAS CLEARED FROM PREVIOUS STATION
			IF EXISTS (
					SELECT TOP 1 1
					FROM DBO.ASSY_RUNNINGPART WITH (NOLOCK)
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE
						AND ASSY_MODE IN (
							'PRODUCTION'
							,'REWORK'
							)
						AND ISNULL(PARTTYPE, '') = 'STMC'
					)
			BEGIN
				SELECT @STMCPARTNO = ASSY_PARTNO
				FROM DBO.ASSY_RUNNINGPART(NOLOCK)
				WHERE LINECODE = @LINECODE
					AND ASSY_MODE IN (
						'PRODUCTION'
						,'REWORK'
						)
					AND ISNULL(PARTTYPE, '') = 'STMC'

				EXEC ASSY_PROC_GET_PREVIOUS_MACHINECODE @LINECODE = @LINECODE
					,@MACHINECODE = @MACHINECODE
					,@PARTNUMBER = @STMCPARTNO
					,@PREVMACHINECODE = @PREVMACHINECODE OUTPUT
			END
			ELSE
			BEGIN
				EXEC ASSY_PROC_GET_PREVIOUS_MACHINECODE @LINECODE = @LINECODE
					,@MACHINECODE = @MACHINECODE
					,@PARTNUMBER = @PARTNUMBER
					,@PREVMACHINECODE = @PREVMACHINECODE OUTPUT
			END

			--ADD BY RASHID ON 11TH MAY 2016 FOR INSERTING PRINT BARCODE ENTRY
			IF EXISTS (
					SELECT TOP 1 1
					FROM ASSY_RUNNINGPART WITH (NOLOCK)
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE
						AND ASSY_MODE = 'REWORK'
					)
			BEGIN
				DECLARE @REWORK_PARTTYPE VARCHAR(20) = ''
					,@REWORK_PARTTYPE_CHILD VARCHAR(20) = ''

				SELECT TOP 1 @REWORK_PARTTYPE = ISNULL(PARTTYPE, '')
					,@REWORK_PARTTYPE_CHILD = ISNULL(SERVO_PARTNO, '')
				FROM ASSY_RUNNINGPART WITH (NOLOCK)
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE
					AND ASSY_MODE = 'REWORK'

				IF EXISTS (
						SELECT TOP 1 BARCODE
						FROM ASSY_TALLYCHARTSTATUSDATA_HISTORY WITH (NOLOCK)
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE
							AND LINECODE = @LINECODE
							AND ISNULL(NOTPROCESSEDSTATUS, '') = 'SCRAP'
							AND PARTNO = CASE @REWORK_PARTTYPE
								WHEN 'STMC'
									THEN @STMCPARTNO
								ELSE @PARTNUMBER
								END
							AND RESULT != 'PASS'
							AND BARCODE = @BARCODE
						)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'BARCODE IS ALREADY SCRAPPED.'

					--UPDATE INCORRECT LABEL
					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
							,@LINECODE = @LINECODE
							,@OPERATIONCODE = @OPERATIONCODE
							,@BARCODE = @BARCODE
							,@HMIMESSAGE = 'BARCODE IS ALREADY SCRAPPED.'
					END

					COMMIT

					RETURN
				END

				DECLARE @REWORKCOUNTDEFINED INT = 0
					,@REWORKVISIONCOUNT INT = 0
					,@REWORKFINALVIEWINGOPERATIONCODE VARCHAR(20) = ''
					,@REWORKFIRSTSTATIONCOUNT INT = 0
					,@REWORK_FIRST_MACHINECODE VARCHAR(20) = ''
					,@REWORK_FIRST_OPERATIONCODE VARCHAR(20) = ''
					,@REWORK_SECOND_MACHINECODE VARCHAR(20) = ''
					,@REWORK_SECOND_OPERATIONCODE VARCHAR(20) = ''

				SELECT TOP 1 @REWORK_FIRST_MACHINECODE = RTRIM(MACHINECODE)
					,@REWORK_FIRST_OPERATIONCODE = RTRIM(OPERATIONCODE)
				FROM ROUTINGCONFIGLINEWISE WITH (NOLOCK)
				WHERE OPERATIONREQUIRED = 1
					AND TRACEABILITY = 1
					AND OPERATIONSEQNO = 1

				SELECT TOP 1 @REWORK_SECOND_MACHINECODE = RTRIM(MACHINECODE)
					,@REWORK_SECOND_OPERATIONCODE = RTRIM(OPERATIONCODE)
				FROM ROUTINGCONFIGLINEWISE WITH (NOLOCK)
				WHERE OPERATIONREQUIRED = 1
					AND TRACEABILITY = 1
					AND OPERATIONSEQNO <> 1
				ORDER BY OPERATIONSEQNO

				SELECT @REWORKFINALVIEWINGOPERATIONCODE = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)

				SELECT @REWORKFIRSTSTATIONCOUNT = COUNT(BARCODE)
				FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK)
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE
					AND DATECODE = @REWORK_DATECODE
					AND OPERATIONCODE = @REWORK_FIRST_OPERATIONCODE
					AND ISNULL(ISTALLYCHARTAPPROVED, 0) = 0

				SELECT @REWORKFIRSTSTATIONCOUNT = @REWORKFIRSTSTATIONCOUNT + COUNT(BARCODE)
				FROM ASSY_LINEASSYSTATUS WITH (NOLOCK)
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE
					AND DATECODE = @REWORK_DATECODE
					AND OPERATIONCODE = @REWORK_FIRST_OPERATIONCODE
					AND ISNULL(ISTALLYCHARTAPPROVED, 0) = 0

				DECLARE @FG_BARCODE VARCHAR(20) = ''
				DECLARE @PACKAGEBARCODE TABLE (BARCODE VARCHAR(60) NOT NULL)

				SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME
				FROM ASSY_LINKSERVER_DTL WITH (NOLOCK)
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE

				IF @REWORK_PARTTYPE = 'STMC'
				BEGIN
					IF EXISTS (
							SELECT 1
							FROM ASSY_COUPLINGDETAILS WITH (NOLOCK)
							WHERE CHILD_BARCODE = @BARCODE
							)
					BEGIN
						SELECT TOP 1 @FG_BARCODE = ISNULL(FG_BARCODE, '')
						FROM ASSY_COUPLINGDETAILS WITH (NOLOCK)
						WHERE CHILD_BARCODE = @BARCODE
					END
					ELSE IF EXISTS (
							SELECT 1
							FROM ASSY_COUPLINGDETAILS_HISTORY WITH (NOLOCK)
							WHERE CHILD_BARCODE = @BARCODE
							)
					BEGIN
						SELECT TOP 1 @FG_BARCODE = ISNULL(FG_BARCODE, '')
						FROM ASSY_COUPLINGDETAILS_HISTORY WITH (NOLOCK)
						WHERE CHILD_BARCODE = @BARCODE
					END

					IF @FG_BARCODE != ''
					BEGIN
						SET @EXECQUERY = '
										SELECT PARTBARCODE FROM ' + @LINKSERVERNAME + '.DBO.SKIDBARCODEDETAIL WITH (NOLOCK) WHERE WH_CODE = ''' + @PROFITCENTERCODE + ''' AND PARTBARCODE = ''' + @FG_BARCODE + ''''

						PRINT @EXECQUERY
					END
				END
				ELSE
				BEGIN
					SET @EXECQUERY = '
										SELECT PARTBARCODE FROM ' + @LINKSERVERNAME + '.DBO.SKIDBARCODEDETAIL WITH (NOLOCK) WHERE WH_CODE = ''' + @PROFITCENTERCODE + ''' AND PARTBARCODE = ''' + @BARCODE + ''''

					PRINT @EXECQUERY
				END

				INSERT INTO @PACKAGEBARCODE (BARCODE)
				EXEC (@EXECQUERY)

				IF EXISTS (
						SELECT 1
						FROM @PACKAGEBARCODE
						)
				BEGIN
					IF @REWORK_PARTTYPE = 'STMC'
					BEGIN
						SET @RETURNVALUE = 'PART ALREADY PACKED IN PACKAGING, FIRST UNPACK AND THEN DECOUPLE IF IT IS COUPLED.'
						SET @RETURNINT = 1

						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
								,@LINECODE = @LINECODE
								,@OPERATIONCODE = @OPERATIONCODE
								,@BARCODE = @BARCODE
								,@HMIMESSAGE = 'PART ALREADY PACKED IN PACKAGING, FIRST UNPACKED AND DECOUPLE IF IT IS COUPLED.'
						END

						DELETE
						FROM @PACKAGEBARCODE

						COMMIT

						RETURN
					END
					ELSE
					BEGIN
						SET @RETURNVALUE = 'PART ALREADY PACKED IN PACKAGING, UNPACK THE PART.'
						SET @RETURNINT = 1

						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
								,@LINECODE = @LINECODE
								,@OPERATIONCODE = @OPERATIONCODE
								,@BARCODE = @BARCODE
								,@HMIMESSAGE = 'PART ALREADY PACKED IN PACKAGING, UNPACKED THE PART.'
						END

						DELETE
						FROM @PACKAGEBARCODE

						COMMIT

						RETURN
					END
				END

				SELECT @REWORKCOUNTDEFINED = CONVERT(INT, PARAMETER_VALUE)
				FROM PARAMETER_MST(NOLOCK)
				WHERE PARAMETER_C = 'ASSLINE'
					AND PARAMETER_C1 = 'REWORK_VISION_COUNT'
					AND WH_CODE = @PROFITCENTERCODE

				SELECT @REWORKVISIONCOUNT = COUNT(BARCODE)
				FROM ASSY_VISION_SYSTEM_HISTORY(NOLOCK)
				WHERE BARCODE = @BARCODE
					AND LINECODE = @LINECODE
					AND ISNULL(ISREWORK, 0) = 1

				IF (@REWORKCOUNTDEFINED <= @REWORKVISIONCOUNT)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'PART MAXIMUM REWORK ATTEMP REACHED. CAN NOT DO REWORK'

					--UPDATE INCORRECT LABEL
					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
							,@LINECODE = @LINECODE
							,@OPERATIONCODE = @OPERATIONCODE
							,@BARCODE = @BARCODE
							,@HMIMESSAGE = 'MAXIMUM REWORK ATTEMPT REACHED'
					END

					COMMIT

					RETURN
				END

				--DECLARE @PRINTBARCODEMACHINECODE VARCHAR(20) = ''
				--SELECT @PRINTBARCODEMACHINECODE = DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE)
				IF NOT EXISTS (
						SELECT 1
						FROM ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
						WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0
							AND PROFITCENTERCODE = @PROFITCENTERCODE
							AND LINECODE = @LINECODE
							AND DATECODE = @REWORK_DATECODE
							AND MACHINECODE = @REWORK_FIRST_MACHINECODE
							AND BARCODE = @BARCODE
						)
				BEGIN
					IF @REWORK_PARTTYPE = 'STMC'
					BEGIN
						IF CHARINDEX(':', @BARCODE) <> 0
						BEGIN
							IF @OPERATIONCODE = @REWORK_SECOND_OPERATIONCODE
							BEGIN
								SET @RETURNINT = 1
								SET @RETURNVALUE = 'INVALID BARCODE (COUPLED BARCODE)'

								--UPDATE INCORRECT LABEL
								IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
								BEGIN
									EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
										,@LINECODE = @LINECODE
										,@OPERATIONCODE = @OPERATIONCODE
										,@BARCODE = @BARCODE
										,@HMIMESSAGE = 'INVALID BARCODE'
								END

								COMMIT

								RETURN
							END
						END

						IF EXISTS (
								SELECT 1
								FROM ASSY_COUPLINGDETAILS WITH (NOLOCK)
								WHERE CHILD_BARCODE = @BARCODE
								)
						BEGIN
							SET @RETURNINT = 1
							SET @RETURNVALUE = 'BARCODE ALREADY COUPLED. FIRST DECOUPLE FROM STMC REWORK FORM.'

							--UPDATE INCORRECT LABEL
							IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
							BEGIN
								EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
									,@LINECODE = @LINECODE
									,@OPERATIONCODE = @OPERATIONCODE
									,@BARCODE = @BARCODE
									,@HMIMESSAGE = 'BARCODE ALREADY COUPLED. FIRST DECOUPLE FROM STMC REWORK FORM.'
							END

							COMMIT

							RETURN
						END
					END

					IF @OPERATIONCODE = @REWORK_SECOND_OPERATIONCODE
					BEGIN
						IF (@REWORKFIRSTSTATIONCOUNT >= @REWORK_CURRENT_PLANQTY)
						BEGIN
							SET @RETURNINT = 1
							SET @RETURNVALUE = 'REWORK PLANNED QTY REACHED.'

							--UPDATE INCORRECT LABEL
							IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
							BEGIN
								EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
									,@LINECODE = @LINECODE
									,@OPERATIONCODE = @OPERATIONCODE
									,@BARCODE = @BARCODE
									,@HMIMESSAGE = 'REWORK PLANNED QTY REACHED.'
							END

							COMMIT

							RETURN
						END
					END

					IF NOT EXISTS (
							SELECT 1
							FROM ASSY_LINEASSYSTATUS(NOLOCK)
							WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0
								AND PROFITCENTERCODE = @PROFITCENTERCODE
								AND LINECODE = @LINECODE
								AND BARCODE = @BARCODE
							)
					BEGIN
						IF NOT EXISTS (
								SELECT 1
								FROM ASSY_VISION_SYSTEM WITH (NOLOCK)
								WHERE PROFITCENTERCODE = @PROFITCENTERCODE
									AND LINECODE = @LINECODE
									AND BARCODE = @BARCODE
								)
						BEGIN
							IF CHARINDEX(':', @BARCODE) = 0
							BEGIN
								INSERT INTO ASSY_VISION_SYSTEM (
									PROFITCENTERCODE
									,LINECODE
									,BARCODE
									,TIMESTAMP
									,DATECODE
									,PARTNO
									,SERIALNO
									,ISREWORK
									)
								SELECT @PROFITCENTERCODE
									,@LINECODE
									,@BARCODE
									,GETDATE()
									,@REWORK_DATECODE
									,CASE @REWORK_PARTTYPE
										WHEN 'STMC'
											THEN @REWORK_PARTTYPE_CHILD
										ELSE @PARTNUMBER
										END
									,SUBSTRING(@BARCODE, LEN(CASE @REWORK_PARTTYPE
												WHEN 'STMC'
													THEN @REWORK_PARTTYPE_CHILD
												ELSE @PARTNUMBER
												END) + 5, 8)
									,1

								UPDATE ASSY_RUNNINGPART
								SET PRINTEDQTY = ISNULL(PRINTEDQTY, 0) + 1
								WHERE PROFITCENTERCODE = @PROFITCENTERCODE
									AND LINECODE = @LINECODE
							END
						END

						SELECT @REWORK_PRINT_QTY = ISNULL(PRINTEDQTY, 0)
						FROM ASSY_RUNNINGPART WITH (NOLOCK)
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE
							AND LINECODE = @LINECODE

						IF NOT EXISTS (
								SELECT 1
								FROM ASSY_BARCODE_PRINTED_COUNTER WITH (NOLOCK)
								WHERE PROFITCENTERCODE = @PROFITCENTERCODE
									AND LINECODE = @LINECODE
									AND DATECODE = @REWORK_DATECODE
									AND PRODUCTIONORDERNO = @REWORK_ORDERNO
									AND PARTNO = CASE @REWORK_PARTTYPE
										WHEN 'STMC'
											THEN @STMCPARTNO
										ELSE @PARTNUMBER
										END
								)
						BEGIN
							IF CHARINDEX(':', @BARCODE) = 0
							BEGIN
								INSERT INTO ASSY_BARCODE_PRINTED_COUNTER (
									PROFITCENTERCODE
									,LINECODE
									,DATECODE
									,PRODUCTIONORDERNO
									,PARTNO
									,CURRENTPLANNEDQTY
									,PRINTEDQTY
									,TIMESTAMP
									)
								SELECT @PROFITCENTERCODE
									,@LINECODE
									,@REWORK_DATECODE
									,@REWORK_ORDERNO
									,CASE @REWORK_PARTTYPE
										WHEN 'STMC'
											THEN @STMCPARTNO
										ELSE @PARTNUMBER
										END
									,@REWORK_CURRENT_PLANQTY
									,@REWORK_PRINT_QTY
									,GETDATE()
							END
						END
						ELSE
						BEGIN
							IF CHARINDEX(':', @BARCODE) = 0
							BEGIN
								UPDATE ASSY_BARCODE_PRINTED_COUNTER
								SET PRINTEDQTY = @REWORK_PRINT_QTY
								WHERE PROFITCENTERCODE = @PROFITCENTERCODE
									AND LINECODE = @LINECODE
									AND DATECODE = @REWORK_DATECODE
									AND PRODUCTIONORDERNO = @REWORK_ORDERNO
									AND PARTNO = CASE @REWORK_PARTTYPE
										WHEN 'STMC'
											THEN @STMCPARTNO
										ELSE @PARTNUMBER
										END
							END
						END

						IF CHARINDEX(':', @BARCODE) = 0
						BEGIN
							--Added By Sachin 20170825 -- Rework Start from first station if check allowed
							IF EXISTS (
									SELECT TOP 1 1
									FROM RoutingConfigDetails(NOLOCK)
									WHERE PROFITCENTERCODE = @PROFITCENTERCODE
										AND LINECODE = @LINECODE
										AND KeyType = 'ReworkFromFirstStation'
										AND KeyValue = '1'
										AND STS_CD = 0
									)
							BEGIN
								INSERT INTO ASSY_LINEASSYSTATUS_RUNNING (
									PROFITCENTERCODE
									,LINECODE
									,MACHINECODE
									,OPERATIONCODE
									,BARCODE
									,DATECODE
									,PARTNO
									,ACTIVE
									,STATIONCODE
									,SCANTIMESTAMP
									,USERID
									,STATUS
									,RESULTTIMESTAMP
									,ProductionOrderNo
									,PROD_LOT_NO
									,Live_Datecode
									) -- Added By Sachin By Sachin 20170726
								SELECT TOP 1 @PROFITCENTERCODE
									,@LINECODE
									,@REWORK_FIRST_MACHINECODE
									,@REWORK_FIRST_OPERATIONCODE
									,@BARCODE
									,@REWORK_DATECODE
									,CASE @REWORK_PARTTYPE
										WHEN 'STMC'
											THEN @STMCPARTNO
										ELSE @PARTNUMBER
										END
									,1
									,1
									,GETDATE()
									,@USERID
									,'PS'
									,GETDATE()
									,@ProductionOrderNo
									,@Lot_No
									,@Live_Datecode -- Added By Sachin By Sachin 20170726
							END
						END

						--Added By Sachin 20170825	-- Rework Start from first station if check allowed
						IF EXISTS (
								SELECT TOP 1 1
								FROM RoutingConfigDetails(NOLOCK)
								WHERE PROFITCENTERCODE = @PROFITCENTERCODE
									AND LINECODE = @LINECODE
									AND KeyType = 'ReworkFromFirstStation'
									AND KeyValue = '1'
									AND STS_CD = 0
								)
						BEGIN
							IF EXISTS (
									SELECT 1
									FROM ASSY_LINEASSYSTATUS WITH (NOLOCK)
									WHERE BARCODE = @BARCODE
									)
							BEGIN
								INSERT INTO ASSY_LINEASSYSTATUS_HISTORY (
									PROFITCENTERCODE
									,LINECODE
									,MACHINECODE
									,OPERATIONCODE
									,STATIONCODE
									,BARCODE
									,STATUS
									,FAILCOUNT
									,DATECODE
									,PARTNO
									,SCANTIMESTAMP
									,RESULTTIMESTAMP
									,ACTIVE
									,USERID
									,ISTALLYCHARTAPPROVED
									,TRANSACTION_NUMBER
									,ISCONFIRMED
									,KANBAN_ID
									,ERP_CONF_TIMESTAMP
									,HIS_ENT_DT
									,HIS_ENT_BY
									,ISREWORKPART
									,ProductionOrderNo
									)
								SELECT PROFITCENTERCODE
									,LINECODE
									,MACHINECODE
									,OPERATIONCODE
									,STATIONCODE
									,BARCODE
									,STATUS
									,FAILCOUNT
									,DATECODE
									,PARTNO
									,SCANTIMESTAMP
									,RESULTTIMESTAMP
									,ACTIVE
									,USERID
									,ISTALLYCHARTAPPROVED
									,TRANSACTION_NUMBER
									,ISCONFIRMED
									,KANBAN_ID
									,ERP_CONF_TIMESTAMP
									,GETDATE()
									,@USERID
									,ISREWORKPART
									,@ProductionOrderNo
								FROM ASSY_LINEASSYSTATUS WITH (NOLOCK)
								WHERE BARCODE = @BARCODE

								DELETE
								FROM ASSY_LINEASSYSTATUS
								WHERE PROFITCENTERCODE = @PROFITCENTERCODE
									AND LINECODE = @LINECODE
									AND BARCODE = @BARCODE
							END
						END

						IF @REWORK_PARTTYPE = 'STMC'
						BEGIN
							SET @FG_BARCODE = ''

							IF EXISTS (
									SELECT 1
									FROM ASSY_COUPLINGDETAILS WITH (NOLOCK)
									WHERE CHILD_BARCODE = @BARCODE
									)
							BEGIN
								SELECT TOP 1 @FG_BARCODE = ISNULL(FG_BARCODE, '')
								FROM ASSY_COUPLINGDETAILS WITH (NOLOCK)
								WHERE CHILD_BARCODE = @BARCODE
							END
							ELSE IF EXISTS (
									SELECT 1
									FROM ASSY_COUPLINGDETAILS_HISTORY WITH (NOLOCK)
									WHERE CHILD_BARCODE = @BARCODE
									)
							BEGIN
								SELECT TOP 1 @FG_BARCODE = ISNULL(FG_BARCODE, '')
								FROM ASSY_COUPLINGDETAILS_HISTORY WITH (NOLOCK)
								WHERE CHILD_BARCODE = @BARCODE
							END

							IF @FG_BARCODE != ''
							BEGIN
								IF EXISTS (
										SELECT TOP 1 1
										FROM RoutingConfigDetails(NOLOCK)
										WHERE PROFITCENTERCODE = @PROFITCENTERCODE
											AND LINECODE = @LINECODE
											AND KeyType = 'ReworkFromFirstStation'
											AND KeyValue = '1'
											AND STS_CD = 0
										)
								BEGIN
									IF EXISTS (
											SELECT 1
											FROM ASSY_LINEASSYSTATUS WITH (NOLOCK)
											WHERE BARCODE = @FG_BARCODE
											)
									BEGIN
										INSERT INTO ASSY_LINEASSYSTATUS_HISTORY (
											PROFITCENTERCODE
											,LINECODE
											,MACHINECODE
											,OPERATIONCODE
											,STATIONCODE
											,BARCODE
											,STATUS
											,FAILCOUNT
											,DATECODE
											,PARTNO
											,SCANTIMESTAMP
											,RESULTTIMESTAMP
											,ACTIVE
											,USERID
											,ISTALLYCHARTAPPROVED
											,TRANSACTION_NUMBER
											,ISCONFIRMED
											,KANBAN_ID
											,ERP_CONF_TIMESTAMP
											,HIS_ENT_DT
											,HIS_ENT_BY
											,ISREWORKPART
											,ProductionOrderNo
											)
										SELECT PROFITCENTERCODE
											,LINECODE
											,MACHINECODE
											,OPERATIONCODE
											,STATIONCODE
											,BARCODE
											,STATUS
											,FAILCOUNT
											,DATECODE
											,PARTNO
											,SCANTIMESTAMP
											,RESULTTIMESTAMP
											,ACTIVE
											,USERID
											,ISTALLYCHARTAPPROVED
											,TRANSACTION_NUMBER
											,ISCONFIRMED
											,KANBAN_ID
											,ERP_CONF_TIMESTAMP
											,GETDATE()
											,@USERID
											,ISREWORKPART
											,@ProductionOrderNo
										FROM ASSY_LINEASSYSTATUS WITH (NOLOCK)
										WHERE BARCODE = @FG_BARCODE
											OR BARCODE = @BARCODE

										DELETE
										FROM ASSY_LINEASSYSTATUS
										WHERE PROFITCENTERCODE = @PROFITCENTERCODE
											AND LINECODE = @LINECODE
											AND (
												BARCODE = @FG_BARCODE
												OR BARCODE = @BARCODE
												)
									END
								END
							END
						END
					END
				END
			END

			--Check DUPLICATE_LABEL GET TESTING TIME OF PARTICULAR BARCODE
			IF @OPERATIONCODE = @FINALVIEWING_OPERATIONCODE
			BEGIN
				SELECT @PARTTESTINGTIME = RESULTTIMESTAMP
				FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE
					AND MACHINECODE = @MACHINECODE
					AND BARCODE = @BARCODE
					AND ISNULL(STATUS, '') = 'PS'

				IF @PARTTESTINGTIME IS NULL
				BEGIN
					SELECT @PARTTESTINGTIME = RESULTTIMESTAMP
					FROM DBO.ASSY_LINEASSYSTATUS(NOLOCK)
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE
						AND MACHINECODE = @MACHINECODE
						AND BARCODE = @BARCODE
						AND ISNULL(STATUS, '') = 'PS'
				END

				IF (@PARTTESTINGTIME IS NOT NULL)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'DUPLICATE_LABEL^' + CONVERT(VARCHAR(100), @PARTTESTINGTIME)

					COMMIT TRAN

					RETURN
				END
			END

			----
			--CHANGED BY RAVI ON 16-02-16
			DECLARE @SCANNEDBARCODE VARCHAR(100) = ''

			SELECT @SCANNEDBARCODE = ISNULL(BARCODE, '')
			FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
			WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0
				AND PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE --AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END 
				AND MACHINECODE = @PREVMACHINECODE
				AND BARCODE = @BARCODE

			IF @SCANNEDBARCODE = ''
			BEGIN
				SELECT @SCANNEDBARCODE = ISNULL(BARCODE, '')
				FROM DBO.ASSY_LINEASSYSTATUS(NOLOCK)
				WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0
					AND PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE --AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END 
					AND MACHINECODE = @PREVMACHINECODE
					AND BARCODE = @BARCODE
			END

			IF @SCANNEDBARCODE = ''
			BEGIN
				SELECT TOP 1 @OPERATIONSEQNO = L.OPERATIONSEQNO
				FROM DBO.ROUTINGCONFIGLINEWISE(NOLOCK) L
				INNER JOIN ROUTINGCONFIGPARTWISE(NOLOCK) P ON L.OPERATIONCODE = P.OPERATIONCODE
					AND L.MACHINECODE = P.MACHINECODE
				WHERE L.LINECODE = @LINECODE
					AND P.PARTNO = (
						SELECT TOP 1 ASSY_PARTNO
						FROM DBO.ASSY_RUNNINGPART(NOLOCK)
						WHERE LINECODE = @LINECODE
						ORDER BY CREATEDDATE DESC
						)
					AND L.TRACEABILITY = 1
					AND P.TRACEABILITY = 1
					AND L.MACHINECODE = @PREVMACHINECODE
					AND P.MACHINECODE = @PREVMACHINECODE
				ORDER BY L.OPERATIONSEQNO

				SELECT TOP 1 @LINETYPECODE = LTM.LINETYPENAME
				FROM LINEMST(NOLOCK) LM
				INNER JOIN LINETYPEMST(NOLOCK) LTM ON LM.LINETYPECODE = LTM.LINETYPECODE
				WHERE LM.LINECODE = @LINECODE

				SET @INCORRECTMSG = (
						SELECT MACHINENAME
						FROM DBO.MACHINEMST(NOLOCK)
						WHERE MACHINECODE = @PREVMACHINECODE
							AND PROFITCENTERCODE = @PROFITCENTERCODE
						)
				SET @RETURNVALUE = 'NOT_PROCESSED_FROM_|' + ISNULL(@INCORRECTMSG, '')
				SET @INCORRECTMSG = 'NOT PROCESSED FROM' + @INCORRECTMSG

				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
						,@LINECODE = @LINECODE
						,@OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE
						,@HMIMESSAGE = 'Previous station not tested.'
				END

				SET @RETURNINT = 1

				COMMIT TRAN

				RETURN
			END

			-----------------------------------------------------------
			--CHECK PART HAS BEEN ONLY SCANNED BUT NOT TESTED
			SET @SCANNEDBARCODE = ''

			SELECT @SCANNEDBARCODE = ISNULL(BARCODE, '')
			FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
			WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0
				AND PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE --AND DATECODE =CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END 
				AND MACHINECODE = @PREVMACHINECODE
				AND BARCODE = @BARCODE
				AND ISNULL(STATUS, '') = ''

			IF @SCANNEDBARCODE = ''
			BEGIN
				SELECT @SCANNEDBARCODE = ISNULL(BARCODE, '')
				FROM DBO.ASSY_LINEASSYSTATUS(NOLOCK)
				WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0
					AND PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE --AND DATECODE =CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END 
					AND MACHINECODE = @PREVMACHINECODE
					AND BARCODE = @BARCODE
					AND ISNULL(STATUS, '') = ''
			END

			IF @SCANNEDBARCODE <> ''
			BEGIN
				SELECT TOP 1 @OPERATIONSEQNO = L.OPERATIONSEQNO
				FROM DBO.ROUTINGCONFIGLINEWISE(NOLOCK) L
				INNER JOIN ROUTINGCONFIGPARTWISE(NOLOCK) P ON L.OPERATIONCODE = P.OPERATIONCODE
					AND L.MACHINECODE = P.MACHINECODE
				WHERE L.LINECODE = @LINECODE
					AND P.PARTNO = (
						SELECT TOP 1 ASSY_PARTNO
						FROM DBO.ASSY_RUNNINGPART(NOLOCK)
						WHERE LINECODE = @LINECODE
						ORDER BY CREATEDDATE DESC
						)
					AND L.TRACEABILITY = 1
					AND P.TRACEABILITY = 1
					AND L.MACHINECODE = @PREVMACHINECODE
					AND P.MACHINECODE = @PREVMACHINECODE
				ORDER BY L.OPERATIONSEQNO

				SELECT TOP 1 @LINETYPECODE = LTM.LINETYPENAME
				FROM DBO.LINEMST(NOLOCK) LM
				INNER JOIN LINETYPEMST(NOLOCK) LTM ON LM.LINETYPECODE = LTM.LINETYPECODE
					AND LM.PROFITCENTERCODE = LTM.PROFITCENTERCODE
				WHERE LM.LINECODE = @LINECODE
					AND LM.PROFITCENTERCODE = @PROFITCENTERCODE

				SET @INCORRECTMSG = (
						SELECT MACHINENAME
						FROM DBO.MACHINEMST(NOLOCK)
						WHERE MACHINECODE = @PREVMACHINECODE
							AND PROFITCENTERCODE = @PROFITCENTERCODE
						)
				SET @RETURNVALUE = 'THIS_BARCODE_HAS_BEEN_ONLY_SCANNED_AND_NOT_TESTED_|' + @INCORRECTMSG
				SET @INCORRECTMSG = 'THIS BARCODE HAS BEEN ONLY SCANNED AND NOT TESTED' + @INCORRECTMSG

				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
						,@LINECODE = @LINECODE
						,@OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE
						,@HMIMESSAGE = 'Previous station not tested.'
				END

				SET @RETURNINT = 1

				COMMIT TRAN

				RETURN
			END

			------------------------------------------------------------------
			SET @SCANNEDBARCODE = ''

			SELECT @SCANNEDBARCODE = ISNULL(BARCODE, '')
			FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
			WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0
				AND PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE --AND DATECODE =CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END 
				AND MACHINECODE = @PREVMACHINECODE
				AND BARCODE = @BARCODE
				AND ISNULL(STATUS, '') = 'PS'

			IF @SCANNEDBARCODE = ''
			BEGIN
				SELECT @SCANNEDBARCODE = ISNULL(BARCODE, '')
				FROM DBO.ASSY_LINEASSYSTATUS(NOLOCK)
				WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0
					AND PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE --AND DATECODE =CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END 
					AND MACHINECODE = @PREVMACHINECODE
					AND BARCODE = @BARCODE
					AND ISNULL(STATUS, '') = 'PS'
			END

			IF @SCANNEDBARCODE = ''
			BEGIN
				SELECT TOP 1 @OPERATIONSEQNO = L.OPERATIONSEQNO
				FROM DBO.ROUTINGCONFIGLINEWISE(NOLOCK) L
				INNER JOIN ROUTINGCONFIGPARTWISE(NOLOCK) P ON L.OPERATIONCODE = P.OPERATIONCODE
					AND L.MACHINECODE = P.MACHINECODE
				WHERE L.LINECODE = @LINECODE
					AND P.PARTNO = (
						SELECT TOP 1 ASSY_PARTNO
						FROM DBO.ASSY_RUNNINGPART(NOLOCK)
						WHERE LINECODE = @LINECODE
						ORDER BY CREATEDDATE DESC
						)
					AND L.TRACEABILITY = 1
					AND P.TRACEABILITY = 1
					AND L.MACHINECODE = @PREVMACHINECODE
					AND P.MACHINECODE = @PREVMACHINECODE
				ORDER BY L.OPERATIONSEQNO

				SELECT TOP 1 @LINETYPECODE = LTM.LINETYPENAME
				FROM DBO.LINEMST(NOLOCK) LM
				INNER JOIN LINETYPEMST(NOLOCK) LTM ON LM.LINETYPECODE = LTM.LINETYPECODE
				WHERE LM.LINECODE = @LINECODE

				SET @INCORRECTMSG = (
						SELECT MACHINENAME
						FROM DBO.MACHINEMST(NOLOCK)
						WHERE MACHINECODE = @PREVMACHINECODE
							AND PROFITCENTERCODE = @PROFITCENTERCODE
						)
				SET @RETURNVALUE = 'NOT_CLEARED_FROM_|' + @INCORRECTMSG
				SET @INCORRECTMSG = 'NOT CLEARED FROM' + @INCORRECTMSG

				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
						,@LINECODE = @LINECODE
						,@OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE
						,@HMIMESSAGE = 'Previous station Fail.'
				END

				SET @RETURNINT = 1

				COMMIT TRAN

				RETURN
			END

			--CHECK A PART HAS NO. OF TIMES FAILED-----------------------------------------------------------------OK
			SELECT @FAILCOUNTDEFINED = CONVERT(INT, PARAMETER_VALUE)
			FROM DBO.PARAMETER_MST(NOLOCK)
			WHERE PARAMETER_C = 'ASSLINE'
				AND PARAMETER_C1 = 'REWORK_COUNT'
				AND WH_CODE = @PROFITCENTERCODE

			IF (@MACHINECODE = 'MCFV')
			BEGIN
				-- ECU BARCODE DATA CAPTURED FOR PART OR NOT
				DECLARE @_operationCode VARCHAR(6)

				SELECT @_operationCode = isNull(keyValue, '')
				FROM RoutingConfigDetails(NOLOCK)
				WHERE ProfitCenterCode = @PROFITCENTERCODE
					AND LineCode = @LINECODE
					AND KeyType = 'ECUBarcodeStationCode'
					AND sts_cd = 0

				IF EXISTS (
						SELECT TOP 1 1
						FROM RoutingConfigLineWise(NOLOCK)
						WHERE ProfitCenterCode = @PROFITCENTERCODE
							AND LineCode = @LINECODE
							AND Traceability = 1
							AND OperationRequired = 1
							AND OperationCode = @_operationCode
						)
				BEGIN
					IF NOT EXISTS (
							SELECT TOP 1 1
							FROM assy_Child_Part_Details(NOLOCK)
							WHERE barcode = @BARCODE
								AND ChildPartNo = 'ECU_BARCODE'
								AND ProfitCenterCode = @PROFITCENTERCODE
								AND lineCode = @LINECODE
							)
					BEGIN
						SELECT DISTINCT t1.ProfitCenterCode
							,t1.LineCode
							,t1.MachineCode
							,t1.OperationCode
							,t1.PartNo AS [PartNumber]
							,t1.Datecode
							,t1.Barcode
							,'ECU_BARCODE' AS ChildPartNo
							,t2.Value AS ChildPartBarcode
							,0 AS STS_CD
							,'ADMIN' AS ENT_BY
							,getdate() AS ENT_STAMP
						INTO #CHILD_PART_DATA
						FROM Assy_LineAssyParamData_Running(NOLOCK) t1
						INNER JOIN Assy_LineAssyParamData_Running_Dtl(NOLOCK) t2 ON t1.UID = t2.UID
						INNER JOIN TagMst(NOLOCK) t3 ON t2.TagId = t3.TagId
						WHERE Barcode = @BARCODE
							AND t1.ProfitCenterCode = @PROFITCENTERCODE
							AND LineCode = @LINECODE
							AND OperationCode = @_operationCode
							AND t3.TagName = 'ECU_BARCODE'
							AND t3.ProfitCenterCode = @PROFITCENTERCODE

						IF EXISTS (
								SELECT TOP 1 1
								FROM #CHILD_PART_DATA
								)
						BEGIN
							INSERT INTO assy_Child_Part_Details (
								ProfitCenterCode
								,LineCode
								,MachineCode
								,OperationCode
								,PartNumber
								,DateCode
								,Barcode
								,ChildPartNo
								,ChildPartBarcode
								,STS_CD
								,ENT_BY
								,ENT_STAMP
								)
							SELECT ProfitCenterCode
								,LineCode
								,MachineCode
								,OperationCode
								,PartNumber
								,DateCode
								,Barcode
								,ChildPartNo
								,ChildPartBarcode
								,STS_CD
								,ENT_BY
								,ENT_STAMP
							FROM #CHILD_PART_DATA
						END
						ELSE
						BEGIN
							SET @RETURNINT = 1
							SET @RETURNVALUE = 'ECU Barcode Not Found'

							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
								,@LINECODE = @LINECODE
								,@OPERATIONCODE = @OPERATIONCODE
								,@BARCODE = @BARCODE
								,@HMIMESSAGE = 'ECU Barcode Not Found'

							COMMIT TRAN

							RETURN
						END
					END
				END

				----------------------Validate Child Part Rejection Data
				DECLARE @MATERIAL_TYPE_REJECT NVARCHAR(500)

				SELECT @MATERIAL_TYPE_REJECT = [dbo].[ASSY_FN_GET_PARAMETER_VALUE]('ASSLINE', 'RejectionAccounting', 'ASSYREJECTIONVALIDATION', '0018')

				IF (isnull(@MATERIAL_TYPE_REJECT, '') <> '')
				BEGIN
					SELECT barcode
						,childpartbarcode
						,childpartno
					INTO #childpartdetails
					FROM assy_child_part_details
					WHERE barcode = @BARCODE

					ALTER TABLE #childpartdetails ADD rejectedchildpartinfo VARCHAR(500)

					UPDATE A
					SET A.rejectedchildpartinfo = 'Barcode coupled with Rejected Child Part - ' + B.part_type + '.'
					FROM #childpartdetails A
					INNER JOIN [ASSY_REJECTION_VALIDATION_DATA] B ON A.childpartbarcode = B.CHILD_PART_BARCODE

					IF EXISTS (
							SELECT TOP 1 1
							FROM #childpartdetails
							WHERE rejectedchildpartinfo IS NOT NULL
							)
					BEGIN
						SET @RETURNINT = 1

						SELECT TOP 1 @RETURNVALUE = rejectedchildpartinfo
						FROM #childpartdetails
						WHERE rejectedchildpartinfo IS NOT NULL

						COMMIT TRAN

						RETURN
					END
				END
						-----------------------------------END
			END

			-- Added By Sachin 20170703 -- Override fail count value.
			IF OBJECT_ID('dbo.RoutingConfigDetails', 'U') IS NOT NULL
			BEGIN
				IF EXISTS (
						SELECT TOP 1 1
						FROM RoutingConfigDetails(NOLOCK)
						WHERE ProfitCenterCode = @PROFITCENTERCODE
							AND LineCode = @LINECODE
							AND MachineCode = @MACHINECODE
							AND OperationCode = @OPERATIONCODE
							AND KeyType = 'failCount'
							AND STS_CD = 0
						)
				BEGIN
					SELECT @FAILCOUNTDEFINED = CONVERT(INT, KeyValue)
					FROM RoutingConfigDetails(NOLOCK)
					WHERE ProfitCenterCode = @PROFITCENTERCODE
						AND LineCode = @LINECODE
						AND MachineCode = @MACHINECODE
						AND OperationCode = @OPERATIONCODE
						AND KeyType = 'failCount'
						AND STS_CD = 0
				END
			END

			SELECT @FAILCOUNT = ISNULL(FAILCOUNT, 0)
			FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
			WHERE BARCODE = @BARCODE
				AND LINECODE = @LINECODE
				AND MACHINECODE = @MACHINECODE
				AND ISNULL(STATUS, '') = 'FL'

			IF @FAILCOUNT IS NULL
				OR @FAILCOUNT = 0
			BEGIN
				SELECT @FAILCOUNT = ISNULL(FAILCOUNT, 0)
				FROM DBO.ASSY_LINEASSYSTATUS(NOLOCK)
				WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0
					AND PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE
					--AND DATECODE=CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END 
					AND BARCODE = @BARCODE
					AND MACHINECODE = @MACHINECODE
					AND ISNULL(STATUS, '') = 'FL'
			END

			IF (@FAILCOUNTDEFINED <= @FAILCOUNT)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'MAXIMUM_FAILED_ATTEMPT_REACHED'

				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
						,@LINECODE = @LINECODE
						,@OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE
						,@HMIMESSAGE = 'MAXIMUM FAILED ATTEMPT REACHED'
				END

				COMMIT TRAN

				RETURN
			END

			--CHECK FOR DUPLICATE LABEL -------------------------------------------------------------------------------OK
			SET @SCANNEDBARCODE = ''

			SELECT @SCANNEDBARCODE = ISNULL(BARCODE, '')
			FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
			WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0
				AND PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE --AND DATECODE =CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END 
				AND MACHINECODE = @MACHINECODE
				AND BARCODE = @BARCODE
				AND ISNULL(STATUS, '') = 'PS'

			IF @SCANNEDBARCODE = ''
			BEGIN
				SELECT @SCANNEDBARCODE = ISNULL(BARCODE, '')
				FROM DBO.ASSY_LINEASSYSTATUS(NOLOCK)
				WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0
					AND PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE --AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END 
					AND MACHINECODE = @MACHINECODE
					AND BARCODE = @BARCODE
					AND ISNULL(STATUS, '') = 'PS'
			END

			-- MOVE PERFORMANCE PASS DATA IF CRIMPING TIME LIMIT REACHED (ADDED BY RASHID ON 31ST MAY 2016)
			DECLARE @CRIMPINGMACHINECODE VARCHAR(30) = ''
				,@CRIMPINGTIMELIMIT INT = 0
				,@PREVRESULTTIMESTAMP DATETIME = NULL
				,@BFLAG BIT = 0
				,@PERFORMANCEMACHINECODE VARCHAR(30) = ''

			SELECT @CRIMPINGMACHINECODE = ISNULL(UPPER(LTRIM(RTRIM(PARAMETER_VALUE))), '')
			FROM PARAMETER_MST WITH (NOLOCK)
			WHERE PARAMETER_C = 'ASSLINE'
				AND PARAMETER_C1 = 'CRIMPING'
				AND PARAMETER_C2 = 'MACHINECODE'
				AND WH_CODE = @PROFITCENTERCODE

			SELECT @PERFORMANCEMACHINECODE = ISNULL(UPPER(LTRIM(RTRIM(PARAMETER_VALUE))), '')
			FROM PARAMETER_MST WITH (NOLOCK)
			WHERE PARAMETER_C = 'ASSLINE'
				AND PARAMETER_C1 = 'FINALVIEWING'
				AND PARAMETER_C2 = 'SERVO_PERFORMANCE_MACHINECODE'
				AND WH_CODE = @PROFITCENTERCODE

			IF @SCANNEDBARCODE <> ''
				AND (@MACHINECODE = @PERFORMANCEMACHINECODE)
			BEGIN
				IF EXISTS (
						SELECT 1
						FROM ASSY_LINE_CRIMPING_RETEST_STATUS WITH (NOLOCK)
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE
							AND LINECODE = @LINECODE
							AND MACHINECODE = @MACHINECODE
							AND BARCODE = @BARCODE
							AND ISNULL(ISRETEST, 0) = 0
						)
				BEGIN
					--Modified By Sudesh on 20170515 for new column ProductionOrderNo in Table Assy_LineAssyStatus_Running
					INSERT INTO ASSY_PERFORMANCEHISTORY (
						PROFITCENTERCODE
						,LINECODE
						,MACHINECODE
						,OPERATIONCODE
						,STATIONCODE
						,BARCODE
						,STATUS
						,FAILCOUNT
						,DATECODE
						,PARTNO
						,ACTIVE
						,RESULTTIMESTAMP
						,SCANTIMESTAMP
						,USERID
						,ISTALLYCHARTAPPROVED
						,ISREWORKPART
						,HISTORYTIMESTAMP
						,ProductionOrderNo
						)
					SELECT PROFITCENTERCODE
						,LINECODE
						,MACHINECODE
						,OPERATIONCODE
						,STATIONCODE
						,BARCODE
						,STATUS
						,FAILCOUNT
						,DATECODE
						,PARTNO
						,ACTIVE
						,RESULTTIMESTAMP
						,SCANTIMESTAMP
						,USERID
						,ISTALLYCHARTAPPROVED
						,ISREWORKPART
						,GETDATE()
						,ProductionOrderNo
					FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK)
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE
						AND MACHINECODE = @MACHINECODE
						AND BARCODE = @BARCODE
						AND ISNULL(STATUS, '') = 'PS'

					DELETE
					FROM ASSY_LINEASSYSTATUS_RUNNING
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE
						AND MACHINECODE = @MACHINECODE
						AND BARCODE = @BARCODE
						AND ISNULL(STATUS, '') = 'PS'

					DELETE
					FROM ASSY_PERFORMANCE_ZIGOUTTIMESTAMP
					WHERE BARCODE = @BARCODE

					UPDATE ASSY_LINE_CRIMPING_RETEST_STATUS
					SET ISRETEST = 1
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE
						AND MACHINECODE = @MACHINECODE
						AND BARCODE = @BARCODE
						AND ISNULL(ISRETEST, 0) = 0

					SET @BFLAG = 1
				END
			END

			IF @SCANNEDBARCODE <> ''
			BEGIN
				IF @BFLAG = 0
				BEGIN
					--UPDATE ASSY_DUPLICATELABEL  TABLE
					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						IF NOT EXISTS (
								SELECT 1
								FROM DBO.ASSY_SCAN_OK(NOLOCK)
								WHERE LINECODE = @LINECODE
									AND OPERATIONCODE = @OPERATIONCODE
									AND ISNULL(ISCYCLESTARTED, 0) = 1
								)
						BEGIN
							IF EXISTS (
									SELECT DISTINCT 1
									FROM DBO.ASSY_DUPLICATELABEL(NOLOCK)
									WHERE LINECODE = @LINECODE
										AND OPERATIONCODE = @OPERATIONCODE
									)
							BEGIN
								UPDATE ASSY_DUPLICATELABEL
								SET ISDUPLICATE = 1
									,BARCODE = @BARCODE
								WHERE LINECODE = @LINECODE
									AND OPERATIONCODE = @OPERATIONCODE

								--RESET SCAN OK
								UPDATE ASSY_SCAN_OK
								SET ISSCAN = 0
								WHERE LINECODE = @LINECODE
									AND OPERATIONCODE = @OPERATIONCODE

								--RESET   INCORRECT LABEL
								UPDATE ASSY_INCORRECTLABEL
								SET HMIMESSAGECODE = ''
									,ISINCORRECT = 0
								WHERE LINECODE = @LINECODE
									AND OPERATIONCODE = @OPERATIONCODE
							END
							ELSE
							BEGIN
								INSERT INTO ASSY_DUPLICATELABEL (
									LINECODE
									,OPERATIONCODE
									,STATIONCODE
									,BARCODE
									,ISDUPLICATE
									)
								SELECT @LINECODE
									,@OPERATIONCODE
									,@STATIONCODE
									,@BARCODE
									,1

								--RESET SCAN OK
								UPDATE ASSY_SCAN_OK
								SET ISSCAN = 0
								WHERE LINECODE = @LINECODE
									AND OPERATIONCODE = @OPERATIONCODE

								--RESET   INCORRECT LABEL
								UPDATE ASSY_INCORRECTLABEL
								SET HMIMESSAGECODE = ''
									,ISINCORRECT = 0
								WHERE LINECODE = @LINECODE
									AND OPERATIONCODE = @OPERATIONCODE
							END
						END
					END

					--GET TESTING TIME OF PARTICULAR BARCODE
					--DECLARE @PARTTESTINGTIME DATETIME = NULL		
					SELECT @PARTTESTINGTIME = RESULTTIMESTAMP
					FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
					WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0
						AND PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE --AND DATECODE =CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END 
						AND MACHINECODE = @MACHINECODE
						AND BARCODE = @BARCODE
						AND ISNULL(STATUS, '') = 'PS'

					IF @PARTTESTINGTIME IS NULL
					BEGIN
						SELECT @PARTTESTINGTIME = RESULTTIMESTAMP
						FROM DBO.ASSY_LINEASSYSTATUS(NOLOCK)
						WHERE ISNULL(ISTALLYCHARTAPPROVED, 0) = 0
							AND PROFITCENTERCODE = @PROFITCENTERCODE
							AND LINECODE = @LINECODE --AND DATECODE =CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END 
							AND MACHINECODE = @MACHINECODE
							AND BARCODE = @BARCODE
							AND ISNULL(STATUS, '') = 'PS'
					END

					SET @RETURNINT = 1
					SET @RETURNVALUE = 'DUPLICATE_LABEL^' + CONVERT(VARCHAR(100), @PARTTESTINGTIME)

					COMMIT TRAN

					RETURN
				END
			END

			-- CHECK FOR CRIMPING TIME LIMIT FROM PERFORMANCE STATION (ADDED BY RASHID ON 31ST MAY 2016)
			IF (
					@CRIMPINGMACHINECODE != ''
					AND @CRIMPINGMACHINECODE = @MACHINECODE
					)
			BEGIN
				IF EXISTS (
						SELECT 1
						FROM ROUTINGCONFIGLINEWISE WITH (NOLOCK)
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE
							AND LINECODE = @LINECODE
							AND MACHINECODE = @PERFORMANCEMACHINECODE
							AND ISNULL(TRACEABILITY, 0) = 0
						)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'PERFORMANCE STATION IS BYPASS. SO CAN NOT RUN LINE WITH CRIMPING STATION.'

					COMMIT TRAN

					RETURN
				END

				SELECT @CRIMPINGTIMELIMIT = CONVERT(INT, ISNULL(LTRIM(RTRIM(PARAMETER_VALUE)), 0))
				FROM PARAMETER_MST WITH (NOLOCK)
				WHERE PARAMETER_C = 'ASSLINE'
					AND PARAMETER_C1 = 'BOOSTERLINE'
					AND PARAMETER_C2 = 'CRIMPINGTIMELIMIT'
					AND WH_CODE = @PROFITCENTERCODE

				SELECT @PREVRESULTTIMESTAMP = ZIGOUTTIMESTAMP
				FROM ASSY_PERFORMANCE_ZIGOUTTIMESTAMP WITH (NOLOCK)
				WHERE BARCODE = @BARCODE

				IF @PREVRESULTTIMESTAMP IS NULL
				BEGIN
					EXEC ASSY_PROC_RETEST_MANAGE @CONDITION = 'UPDATE'
						,@LINECODE = @LINECODE
						,@OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE
						,@HMIMESSAGE = 'JIG IS NOT COME OUT FROM PERFORMANCE STATION PROPERLY. RETEST IN PREVIOUS STATION'

					IF NOT EXISTS (
							SELECT 1
							FROM ASSY_LINE_CRIMPING_RETEST_STATUS WITH (NOLOCK)
							WHERE PROFITCENTERCODE = @PROFITCENTERCODE
								AND LINECODE = @LINECODE
								AND MACHINECODE = @PREVMACHINECODE
								AND BARCODE = @BARCODE
								AND ISNULL(ISRETEST, 0) = 0
							)
					BEGIN
						INSERT INTO ASSY_LINE_CRIMPING_RETEST_STATUS (
							PROFITCENTERCODE
							,LINECODE
							,MACHINECODE
							,BARCODE
							,TIMESTAMP
							,ISRETEST
							,REMARK
							)
						SELECT @PROFITCENTERCODE
							,@LINECODE
							,@PREVMACHINECODE
							,@BARCODE
							,GETDATE()
							,0
							,'JIG IS NOT COME OUT FROM PERFORMANCE STATION PROPERLY. RETEST IN PREVIOUS STATION'
					END

					SET @RETURNINT = 1
					SET @RETURNVALUE = 'JIG IS NOT COME OUT FROM PERFORMANCE STATION PROPERLY. RETEST IN PREVIOUS STATION'

					--SET @RETURNVALUE = 'ZIG IS NOT COME OUT FROM PERFORMANCE STATION. SO CAN NOT SCAN.'
					COMMIT TRAN

					RETURN
				END

				--SELECT @PREVRESULTTIMESTAMP = RESULTTIMESTAMP FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK) WHERE PROFITCENTERCODE =@PROFITCENTERCODE
				--				AND LINECODE = @LINECODE AND ISNULL(ISTALLYCHARTAPPROVED,0) = 0 AND  MACHINECODE = @PREVMACHINECODE
				--				AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END  AND BARCODE = @BARCODE
				--				AND  ISNULL(STATUS,'') = 'PS'
				IF (DATEDIFF(SECOND, @PREVRESULTTIMESTAMP, GETDATE()) > @CRIMPINGTIMELIMIT)
				BEGIN
					SET @INCORRECTMSG = ''
					SET @INCORRECTMSG = (
							SELECT MACHINENAME
							FROM MACHINEMST WITH (NOLOCK)
							WHERE MACHINECODE = @PREVMACHINECODE
								AND PROFITCENTERCODE = @PROFITCENTERCODE
							)
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'SCAN TIME LIMIT REACHED. RETEST IN PREVIOUS STATION - ' + @INCORRECTMSG

					IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					BEGIN
						EXEC ASSY_PROC_RETEST_MANAGE @CONDITION = 'UPDATE'
							,@LINECODE = @LINECODE
							,@OPERATIONCODE = @OPERATIONCODE
							,@BARCODE = @BARCODE
							,@HMIMESSAGE = 'SCAN TIME LIMIT REACHED. RETEST IN PREVIOUS STATION'
					END

					IF NOT EXISTS (
							SELECT 1
							FROM ASSY_LINE_CRIMPING_RETEST_STATUS WITH (NOLOCK)
							WHERE PROFITCENTERCODE = @PROFITCENTERCODE
								AND LINECODE = @LINECODE
								AND MACHINECODE = @PREVMACHINECODE
								AND BARCODE = @BARCODE
								AND ISNULL(ISRETEST, 0) = 0
							)
					BEGIN
						INSERT INTO ASSY_LINE_CRIMPING_RETEST_STATUS (
							PROFITCENTERCODE
							,LINECODE
							,MACHINECODE
							,BARCODE
							,TIMESTAMP
							,ISRETEST
							,REMARK
							)
						SELECT @PROFITCENTERCODE
							,@LINECODE
							,@PREVMACHINECODE
							,@BARCODE
							,GETDATE()
							,0
							,'DIFFERECE OF TIME(SECONDS) BETWEEN RESULTTIMESTAMP OF PERFORMANCE STATION AND CRIMPING STATION'
					END

					COMMIT TRAN

					RETURN
				END
			END

			IF @OPERATIONCODE = @FINALVIEWING_OPERATIONCODE
			BEGIN
				--START-- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING STOCK DEDUCTION
				IF (
						(
							SELECT ISNULL(ISMATFEEDREQUIRED, 0)
							FROM LINEMST WITH (NOLOCK)
							WHERE PROFITCENTERCODE = @PROFITCENTERCODE
								AND LINECODE = @LINECODE
							) = 1
						)
				BEGIN
					--START-- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING VALIDATION
					SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME
					FROM ASSY_LINKSERVER_DTL WITH (NOLOCK)
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE

					SET @EXECQUERY = ''
					SET @EXECQUERY = '
								SELECT REMARKS FROM ' + @LINKSERVERNAME + '.DBO.ASSY_LINEMATFEEDREMARKSTATUS WITH (NOLOCK)
									WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + '''
									AND PARTNO = ''' + @PARTNUMBER + ''' AND ISACTIVE = 1 '

					--PRINT @EXECQUERY
					DECLARE @MATFEEDREMARK AS TABLE (
						REMARKS VARCHAR(500) --VARCHAR(200) modified by sachin 20170411
						)

					INSERT INTO @MATFEEDREMARK (REMARKS)
					EXEC (@EXECQUERY)

					DECLARE @MATFEEDREMARKSTATUS VARCHAR(500) = ''

					IF EXISTS (
							SELECT 1
							FROM @MATFEEDREMARK
							)
					BEGIN
						SELECT @MATFEEDREMARKSTATUS = LTRIM(RTRIM(REMARKS))
						FROM @MATFEEDREMARK

						DECLARE @QTYLOWMESSAGE BIT = 0

						IF (@MATFEEDREMARKSTATUS != 'OK')
						BEGIN
							IF (UPPER(LEFT(@MATFEEDREMARKSTATUS, 4)) = 'SOME')
							BEGIN
								SET @QTYLOWMESSAGE = 1
							END
							ELSE
							BEGIN
								SET @RETURNVALUE = @MATFEEDREMARKSTATUS
								SET @RETURNINT = 1

								COMMIT

								RETURN
							END
						END
					END
				END
			END

			--END-- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING VALIDATION
			----CHECK FOR WIP LIMIT			      	
			EXEC ASSY_PROC_WIP_MANAGE @CONDITION = 'VALIDATE_WIP'
				,@LINECODE = @LINECODE
				,@MACHINECODE = @MACHINECODE
				,@BARCODE = @BARCODE
				,@PROFITCENTERCODE = @PROFITCENTERCODE
				,@RETURNVALUE = @RETURNVALUE1 OUT
				,@RETURNINT = @RETURNINT1 OUT

			IF RTRIM(LTRIM(@RETURNVALUE1)) = 'WIP_LIMIT_HAS_REACHED'
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'WIP_LIMIT_HAS_REACHED'

				--UPDATE INCORRECT LABEL
				IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
				BEGIN
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
						,@LINECODE = @LINECODE
						,@OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE
						,@HMIMESSAGE = 'WIP LIMIT HAS REACHED'
				END

				COMMIT TRAN

				RETURN
			END

			--CHANGED BY RAVI FOR JHAGADIA ON 10/08/16 TO CHECK WHETHER SAME CALIPER SERIAL NO. HAS BEEN ALREADY GENERATED AT COUPLING STATION OR NOT.
			-- check if customer label required only
			IF (
					(
						SELECT TOP 1 KeyValue
						FROM RoutingConfigDetails(NOLOCK)
						WHERE ProfitCenterCode = @PROFITCENTERCODE
							AND LineCode = @LINECODE
							AND @OPERATIONCODE = @OperationCode
							AND KeyType = 'isCustomerLabelReq'
							AND STS_CD = 0
						) = 1
					)
			BEGIN
				IF EXISTS (
						SELECT 1
						FROM DBO.ROUTINGCONFIGLINEWISE WITH (NOLOCK)
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE
							AND LINECODE = @LINECODE
							--AND @OPERATIONCODE=@FINALVIEWING_OPERATIONCODE -- Cmt By Sachin 2019Aug12
							AND @OPERATIONCODE = @OperationCode -- Added By Sachin 2019Aug12
							AND ISNULL(LABELPRINTING, 0) = 1
							AND ISNULL(TRACEABILITY, 0) = 1
						)
				BEGIN
					PRINT 'ASSY_PROC_FINALQCSTN_LABEL_PRINTING : GET_LABEL_INFO_VALIDATION'

					EXEC ASSY_PROC_FINALQCSTN_LABEL_PRINTING @CONDITION = 'GET_LABEL_INFO_VALIDATION'
						,@PROFITCENTERCODE = @PROFITCENTERCODE
						,@LINECODE = @LINECODE
						,@RFID = @BARCODE
						,@RETURNVALUE = @RETURNVALUE OUT

					IF @RETURNVALUE = 'SAME_CALIPER_SERIAL_NO_HAS_BEEN_ALREADY_GENERATED.'
					BEGIN
						SET @RETURNINT = 1
						SET @RETURNVALUE = 'SAME_CALIPER_SERIAL_NO_HAS_BEEN_ALREADY_GENERATED.'

						--UPDATE INCORRECT LABEL
						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
								,@LINECODE = @LINECODE
								,@OPERATIONCODE = @OPERATIONCODE
								,@BARCODE = @BARCODE
								,@HMIMESSAGE = 'SAME_CALIPER_SERIAL_NO_HAS_BEEN_ALREADY_GENERATED.'
						END

						COMMIT TRAN

						RETURN
					END
					ELSE IF @RETURNVALUE = 'CALIPER_SERIAL_NO_HAS_NOT_BEEN_GENERATED_AT_COUPLING_STATION'
					BEGIN
						SET @RETURNINT = 1
						SET @RETURNVALUE = 'CALIPER_SERIAL_NO_HAS_NOT_BEEN_GENERATED_AT_COUPLING_STATION'

						--UPDATE INCORRECT LABEL
						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
								,@LINECODE = @LINECODE
								,@OPERATIONCODE = @OPERATIONCODE
								,@BARCODE = @BARCODE
								,@HMIMESSAGE = 'CALIPER_SERIAL_NO_HAS_NOT_BEEN_GENERATED_AT_COUPLING_STATION.'
						END

						COMMIT TRAN

						RETURN
					END -- ADDED BY SACHIN 20170302 CHECK ALL DATA BEFORE PRINT
					ELSE IF @RETURNVALUE = 'PRN_FILE_DOES_NOT_EXISTS'
					BEGIN
						SET @RETURNINT = 1
						SET @RETURNVALUE = 'PRN_FILE_DOES_NOT_EXISTS'

						--UPDATE INCORRECT LABEL
						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
								,@LINECODE = @LINECODE
								,@OPERATIONCODE = @OPERATIONCODE
								,@BARCODE = @BARCODE
								,@HMIMESSAGE = 'PRN_FILE_DOES_NOT_EXISTS.'
						END

						COMMIT TRAN

						RETURN
					END
					ELSE IF @RETURNVALUE = 'PRN_DATA_DOES_NOT_EXISTS'
					BEGIN
						SET @RETURNINT = 1
						SET @RETURNVALUE = 'PRN_DATA_DOES_NOT_EXISTS'

						--UPDATE INCORRECT LABEL
						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
								,@LINECODE = @LINECODE
								,@OPERATIONCODE = @OPERATIONCODE
								,@BARCODE = @BARCODE
								,@HMIMESSAGE = 'PRN_DATA_DOES_NOT_EXISTS.'
						END

						COMMIT TRAN

						RETURN
					END
					ELSE IF @RETURNVALUE = 'PLEASE_SELECT_CUSTOMER_PART_NUMBER'
					BEGIN
						SET @RETURNINT = 1
						SET @RETURNVALUE = 'PLEASE_SELECT_CUSTOMER_PART_NUMBER'

						--UPDATE INCORRECT LABEL
						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
								,@LINECODE = @LINECODE
								,@OPERATIONCODE = @OPERATIONCODE
								,@BARCODE = @BARCODE
								,@HMIMESSAGE = 'PLEASE_SELECT_CUSTOMER_PART_NUMBER.'
						END

						COMMIT TRAN

						RETURN
					END
				END
			END

			/**********
						 - Code Added By Sachin 20170711
						 - Below is Used to Validation using Validation Matrix Table
						*/
			IF OBJECT_ID('dbo.Assy_Validation_Matrix', 'U') IS NOT NULL
			BEGIN
				IF EXISTS (
						SELECT TOP 1 1
						FROM Assy_Validation_Matrix(NOLOCK)
						WHERE profitcenterCode = @PROFITCENTERCODE
							AND LineCode = @LINECODE
							AND OperationCode = @OPERATIONCODE
							AND isValidationReq = 1
							AND STS_CD = 0
							AND [Priority] > 0
							AND ISNUll(PartNo, '') = ISNULL(@PARTNO, '') -- Added By Sachin 2019-06-20
						)
				BEGIN
					DECLARE @validationCode INT = 0

					SELECT *
					INTO #temp1
					FROM Assy_Validation_Matrix(NOLOCK)
					WHERE profitcenterCode = @PROFITCENTERCODE
						AND LineCode = @LINECODE
						AND OperationCode = @OPERATIONCODE
						AND isValidationReq = 1
						AND STS_CD = 0
						AND [Priority] > 0
						AND ISNUll(PartNo, '') = ISNULL(@PARTNO, '') -- Added By Sachin 2019-06-20

					--select * from #temp1
					DECLARE @error_found BIT = 0
					DECLARE @V_RETURNINT INT
					DECLARE @V_RETURNVALUE VARCHAR(2000)
					DECLARE @V_TABLE1 VARCHAR(100)
					DECLARE @V_TABLE1_COL VARCHAR(2000)
					DECLARE @V_TABLE2 VARCHAR(100)
					DECLARE @V_TABLE2_COL VARCHAR(2000)

					--Added By Sahcin 20190302
					IF EXISTS (
							SELECT TOP 1 1
							FROM RoutingConfigDetails(NOLOCK)
							WHERE ProfitCenterCode = @PROFITCENTERCODE
								AND LineCode = @LINECODE
								AND MachineCode = @MACHINECODE
								AND OperationCode = @OPERATIONCODE
								AND Keytype = 'IsValidationsAlreadyDone'
								AND ISNULL(KeyValue, 'N') = 'Y'
							)
					BEGIN
						DELETE
						FROM #temp1
					END

					--Ended by Sahcin 20190302
					WHILE (
							EXISTS (
								SELECT TOP 1 1
								FROM #temp1
								)
							)
					BEGIN
						SELECT TOP 1 @validationCode = ISNULL(ValidationCode, 0)
							,@V_TABLE1 = ISNULL(ChkDataFromTable1, '')
							,@V_TABLE1_COL = ISNULL(ChkColumnFromTable1, '')
							,@V_TABLE2 = ISNULL(ChkDataFromTable2, '')
							,@V_TABLE2_COL = ISNULL(ChkColumnFromTable2, '')
						FROM #temp1
						ORDER BY [Priority] ASC

						BEGIN
							EXEC ASSY_PROC_DO_VALIDATION @P_VALIDATIONCODE = @validationCode
								,@P_PROFITCENTERCODE = @PROFITCENTERCODE
								,@P_LINECODE = @LINECODE
								,@P_OPERATION_CODE = @OPERATIONCODE
								,@P_PartNo = @PARTNO
								,@P_MachineCode = @MACHINECODE
								,@P_TABLE1 = @V_TABLE1
								,@P_COLUMN_TABLE1 = @V_TABLE1_COL
								,@P_TABLE2 = @V_TABLE2
								,@P_COLUMN_TABLE2 = @V_TABLE2_COL
								,@P_Barcode = @barcode
								,@P_DateCode = @V_DateCode
								,@RETURNINT = @V_RETURNINT OUT
								,@RETURNVALUE = @V_RETURNVALUE OUT

							--print @V_RETURNVALUE + ' ' + convert(varchar,@V_RETURNINT)
							--insert into do_validation_log(
							--dt,ValidationCode,ValidationDescription,ChkDataFromTable1,ChkColumnFromTable1,ChkDataFromTable2,
							--ChkColumnFromTable2,[output]
							--)
							--values(getdate(),@validationCode,'',@V_TABLE1,@V_TABLE1_COL,@V_TABLE2,@V_TABLE2_COL,ISNULL											(@V_RETURNVALUE,''))
							IF (ISNULL(@V_RETURNINT, 0) = 1)
							BEGIN
								SET @error_found = 1

								DELETE
								FROM #temp1
							END
						END

						DELETE
						FROM #temp1
						WHERE ValidationCode = @validationCode
					END

					IF (@error_found = 1)
					BEGIN
						SET @RETURNINT = @V_RETURNINT
						SET @RETURNVALUE = @V_RETURNVALUE

						EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
							,@LINECODE = @LINECODE
							,@OPERATIONCODE = @OPERATIONCODE
							,@BARCODE = @BARCODE
							,@HMIMESSAGE = '19'

						COMMIT TRAN

						RETURN
					END
				END
			END

			/**********
						 - Code Ended By Sachin 20170711
						*/
			/**********
						 - Code Added By Sachin 20170831
						 - Check For Continues Fail and Hourly Fail
						*/
			SELECT @FlagStatus = keyValue
			FROM RoutingConfigDetails(NOLOCK)
			WHERE ProfitCenterCode = @PROFITCENTERCODE
				AND LineCode = @LINECODE
				AND keyType = 'ContinuesFailCountReq'
				AND STS_CD = 0

			IF (@FlagStatus = 1)
			BEGIN
				SELECT @FAILCOUNT = ISNULL(keyValue, 0)
				FROM RoutingConfigDetails(NOLOCK)
				WHERE ProfitCenterCode = @PROFITCENTERCODE
					AND LineCode = @LINECODE
					AND keyType = 'MaxContinuesFailCount'
					AND STS_CD = 0

				IF EXISTS (
						SELECT TOP 1 1
						FROM Assy_Continues_Fail_Count(NOLOCK)
						WHERE ProfitCenterCode = ISNULL(@PROFITCENTERCODE, '')
							AND LineCode = ISNULL(@LINECODE, '')
							AND OperationCode = ISNULL(@OperationCode, '')
							AND FailCount >= @FAILCOUNT
						)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'MAXIMUM_CONTINUES_FAIL_COUNT_REACHED|' + CONVERT(VARCHAR, @FAILCOUNT)

					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
						,@LINECODE = @LINECODE
						,@OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE
						,@HMIMESSAGE = 'MAXIMUM CONTINUES FAIL COUNT REACHED '

					COMMIT TRAN

					RETURN
				END
			END

			SELECT @FlagStatus = keyValue
			FROM RoutingConfigDetails(NOLOCK)
			WHERE ProfitCenterCode = @PROFITCENTERCODE
				AND LineCode = @LINECODE
				AND keyType = 'HourlyFailCountReq'
				AND STS_CD = 0

			IF (@FlagStatus = 1)
			BEGIN
				SELECT @FAILCOUNT = ISNULL(keyValue, 0)
				FROM RoutingConfigDetails(NOLOCK)
				WHERE ProfitCenterCode = @PROFITCENTERCODE
					AND LineCode = @LINECODE
					AND keyType = 'MaxHourlyFailCount'
					AND STS_CD = 0

				IF EXISTS (
						SELECT TOP 1 1
						FROM Assy_Hourly_Fail_Count
						WHERE profitCenterCode = ISNULL(@PROFITCENTERCODE, '')
							AND LineCode = ISNULL(@LINECODE, '')
							AND OperationCode = ISNULL(@OperationCode, '')
							AND GETDATE() BETWEEN [FromTimestamp]
								AND [ToTimestamp]
							AND FailCount >= @FAILCOUNT
						)
				BEGIN
					SET @RETURNINT = 1
					SET @RETURNVALUE = 'MAXIMUM_HOURLY_FAIL_COUNT_REACHED|' + CONVERT(VARCHAR, @FAILCOUNT)

					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
						,@LINECODE = @LINECODE
						,@OPERATIONCODE = @OPERATIONCODE
						,@BARCODE = @BARCODE
						,@HMIMESSAGE = 'MAXIMUM HOURLY FAIL COUNT REACHED '

					COMMIT TRAN

					RETURN
				END
			END

			/**********
						 - Code Ended By Sachin 20170831
						*/
			SET @SCANNINGSTATION = 1

			IF EXISTS (
					SELECT 1
					FROM DBO.MACHINEMST WITH (NOLOCK)
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND MACHINECODE = @MACHINECODE
						AND INDEXPERSTATIONS = 2
					)
			BEGIN
				SELECT @STATIONCODE = STATIONCODE
				FROM DBO.ASSY_STATIONS_ZIG_IN_OUT_STATUS(NOLOCK)
				WHERE LINECODE = @LINECODE
					AND OPERATIONCODE = @OPERATIONCODE

				IF @STATIONCODE = 1
					SET @SCANNINGSTATION = 2
				ELSE IF @STATIONCODE = 2
					SET @SCANNINGSTATION = 1
				SET @STATIONCODE = @SCANNINGSTATION

				IF EXISTS (
						SELECT DISTINCT 1
						FROM DBO.ASSY_SCAN_OK(NOLOCK)
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE
							AND LINECODE = @LINECODE
							AND OPERATIONCODE = @OPERATIONCODE
							AND MACHINECODE = @MACHINECODE
							AND STATIONCODE = @SCANNINGSTATION
						)
				BEGIN
					UPDATE ASSY_SCAN_OK
					SET ISSCAN = 1
						,BARCODE = @BARCODE
						,ASSY_PARTNO = @PARTNUMBER
						,DATECODE = @DATECODE
						,CREATEDBY = @USERID
						,CREATEDDATE = GETDATE()
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE
						AND OPERATIONCODE = @OPERATIONCODE
						AND MACHINECODE = @MACHINECODE
						AND STATIONCODE = @SCANNINGSTATION
				END
				ELSE
				BEGIN
					INSERT INTO ASSY_SCAN_OK (
						PROFITCENTERCODE
						,LINECODE
						,OPERATIONCODE
						,STATIONCODE
						,BARCODE
						,ISSCAN
						,MACHINECODE
						,ASSY_PARTNO
						,DATECODE
						,CREATEDBY
						,CREATEDDATE
						)
					SELECT @PROFITCENTERCODE
						,@LINECODE
						,@OPERATIONCODE
						,@SCANNINGSTATION
						,@BARCODE
						,1
						,@MACHINECODE
						,@PARTNUMBER
						,@DATECODE
						,@USERID
						,GETDATE()
				END

				--RESET   INCORRECT LABEL
				UPDATE ASSY_INCORRECTLABEL
				SET HMIMESSAGECODE = ''
					,ISINCORRECT = 0
				WHERE LINECODE = @LINECODE
					AND OPERATIONCODE = @OPERATIONCODE

				--RESET DUPLICATE LABEL
				UPDATE ASSY_DUPLICATELABEL
				SET ISDUPLICATE = 0
				WHERE LINECODE = @LINECODE
					AND OPERATIONCODE = @OPERATIONCODE
			END
			ELSE IF EXISTS (
					SELECT DISTINCT 1
					FROM DBO.ASSY_SCAN_OK(NOLOCK)
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE
						AND OPERATIONCODE = @OPERATIONCODE
						AND MACHINECODE = @MACHINECODE
					)
			BEGIN
				UPDATE ASSY_SCAN_OK
				SET ISSCAN = 1
					,BARCODE = @BARCODE
					,ASSY_PARTNO = @PARTNUMBER
					,DATECODE = @DATECODE
					,CREATEDBY = @USERID
					,CREATEDDATE = GETDATE()
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE
					AND OPERATIONCODE = @OPERATIONCODE
					AND MACHINECODE = @MACHINECODE
					AND STATIONCODE = @SCANNINGSTATION

				--RESET   INCORRECT LABEL
				UPDATE ASSY_INCORRECTLABEL
				SET HMIMESSAGECODE = ''
					,ISINCORRECT = 0
				WHERE LINECODE = @LINECODE
					AND OPERATIONCODE = @OPERATIONCODE

				--RESET DUPLICATE LABEL
				UPDATE ASSY_DUPLICATELABEL
				SET ISDUPLICATE = 0
				WHERE LINECODE = @LINECODE
					AND OPERATIONCODE = @OPERATIONCODE

				UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE
				SET BARCODE = ''
					,ISCYCLESTARTED = 0
				WHERE LINECODE = @LINECODE
					AND MACHINECODE = @MACHINECODE
					AND OPERATIONCODE = @OPERATIONCODE
			END
			ELSE
			BEGIN
				INSERT INTO ASSY_SCAN_OK (
					PROFITCENTERCODE
					,LINECODE
					,OPERATIONCODE
					,STATIONCODE
					,BARCODE
					,ISSCAN
					,MACHINECODE
					,ASSY_PARTNO
					,DATECODE
					,CREATEDBY
					,CREATEDDATE
					)
				SELECT @PROFITCENTERCODE
					,@LINECODE
					,@OPERATIONCODE
					,@SCANNINGSTATION
					,@BARCODE
					,1
					,@MACHINECODE
					,@PARTNUMBER
					,@DATECODE
					,@USERID
					,GETDATE()

				--RESET   INCORRECT LABEL
				UPDATE ASSY_INCORRECTLABEL
				SET HMIMESSAGECODE = ''
					,ISINCORRECT = 0
				WHERE LINECODE = @LINECODE
					AND OPERATIONCODE = @OPERATIONCODE

				--RESET DUPLICATE LABEL
				UPDATE ASSY_DUPLICATELABEL
				SET ISDUPLICATE = 0
				WHERE LINECODE = @LINECODE
					AND OPERATIONCODE = @OPERATIONCODE

				UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE
				SET BARCODE = ''
					,ISCYCLESTARTED = 0
				WHERE LINECODE = @LINECODE
					AND MACHINECODE = @MACHINECODE
					AND OPERATIONCODE = @OPERATIONCODE
			END

			--Start//Added By Prerna On 25-Apr-2020 For WIP Count Manage For Next Shift
			DELETE
			FROM Assy_WIP_Pending_Part_Status
			WHERE ProfitCenterCode = @PROFITCENTERCODE
				AND LineCode = @LINECODE
				AND Barcode = @BARCODE
				AND IsPrintUpdate = 1

			--End//Added By Prerna On 25-Apr-2020 For WIP Count Manage For Next Shift
			IF EXISTS (
					SELECT DISTINCT 1
					FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE
						AND DATECODE = CASE @REWORK_MODE
							WHEN 'REWORK'
								THEN @REWORK_DATECODE
							ELSE @DATECODE
							END
						AND MACHINECODE = @MACHINECODE
						AND OPERATIONCODE = @OPERATIONCODE
						AND BARCODE = @BARCODE
					)
			BEGIN
				-- ADDED BY RASHID ON 20TH JULY 2016 FOR PERFORMANCE
				IF (@OPERATIONCODE = 'OCSVPR')
				BEGIN
					UPDATE ASSY_LINEASSYSTATUS_RUNNING
					SET SCANTIMESTAMP = GETDATE()
						,STATIONCODE = @SCANNINGSTATION
						,RESULTTIMESTAMP = NULL
						,STATUS = NULL
						,Live_Datecode = @Live_Datecode
					WHERE LINECODE = @LINECODE
						AND MACHINECODE = @MACHINECODE
						AND OPERATIONCODE = @OPERATIONCODE
						AND BARCODE = @BARCODE
						AND PROFITCENTERCODE = @PROFITCENTERCODE
				END
				ELSE
				BEGIN
					UPDATE ASSY_LINEASSYSTATUS_RUNNING
					SET SCANTIMESTAMP = GETDATE()
						,STATIONCODE = @SCANNINGSTATION
						,Live_Datecode = @Live_Datecode
					WHERE LINECODE = @LINECODE
						AND MACHINECODE = @MACHINECODE
						AND OPERATIONCODE = @OPERATIONCODE
						AND BARCODE = @BARCODE
						AND PROFITCENTERCODE = @PROFITCENTERCODE
				END
			END
			ELSE
			BEGIN
				DELETE
				FROM ASSY_LINEASSYSTATUS_RUNNING
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE
					AND MACHINECODE = @MACHINECODE
					AND BARCODE = @BARCODE

				IF @STMCPARTNO <> ''
					SET @PARTNUMBER = @STMCPARTNO

				INSERT INTO ASSY_LINEASSYSTATUS_RUNNING (
					PROFITCENTERCODE
					,LINECODE
					,MACHINECODE
					,OPERATIONCODE
					,BARCODE
					,DATECODE
					,PARTNO
					,ACTIVE
					,STATIONCODE
					,SCANTIMESTAMP
					,USERID
					,ProductionOrderNo
					,PROD_LOT_NO
					,Live_Datecode
					) -- Added By Sachin By Sachin 20170726
				SELECT @PROFITCENTERCODE
					,@LINECODE
					,@MACHINECODE
					,@OPERATIONCODE
					,@BARCODE
					,CASE @REWORK_MODE
						WHEN 'REWORK'
							THEN @REWORK_DATECODE
						ELSE @DATECODE
						END
					,@PARTNUMBER
					,1
					,@SCANNINGSTATION
					,GETDATE()
					,@USERID
					,@ProductionOrderNo
					,@Lot_No
					,@Live_Datecode -- Added By Sachin By Sachin 20170726
			END

			--UPDATE SCAN OK FOR DATE CODE STAMPING,IF STAMPING IS APPLICABLE FOR LINE AND PART NO.
			IF @OPERATIONCODE = @FINALVIEWING_OPERATIONCODE
			BEGIN
				EXEC ASSY_PROC_DATECODESTAMPING @CONDITION = 'UPDATE_SCANOK'
					,@LINECODE = @LINECODE
					,@BARCODE = @BARCODE
					,@PROFITCENTERCODE = @PROFITCENTERCODE
			END

			--IF (@CRIMPINGMACHINECODE != '' AND @CRIMPINGMACHINECODE = @MACHINECODE)
			--BEGIN
			--	IF EXISTS (SELECT TOP 1 BARCODE FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK) WHERE PROFITCENTERCODE =@PROFITCENTERCODE
			--			AND LINECODE = @LINECODE AND ISNULL(ISTALLYCHARTAPPROVED,0) = 0 AND  MACHINECODE = @MACHINECODE
			--			AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END
			--			AND  ISNULL(STATUS,'') = '')
			--	BEGIN
			--		UPDATE ASSY_LINEASSYSTATUS_RUNNING SET STATUS = 'FL', FAILCOUNT = 5 
			--			WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND ISNULL(ISTALLYCHARTAPPROVED,0) = 0
			--			AND MACHINECODE = @MACHINECODE AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END
			--			AND  ISNULL(STATUS,'') = ''
			--	END
			--END
			SET @RETURNINT = 1
			SET @RETURNVALUE = 'SCANNED_SUCCESSFULLY'

			IF @QTYLOWMESSAGE = 1
			BEGIN
				SET @RETURNVALUE = 'SCANNED_SUCCESSFULLY' + ' BUT ' + @MATFEEDREMARKSTATUS
			END

			COMMIT TRAN
		END TRY

		BEGIN CATCH
			-- 20170411 ISNULL ADDED BY SACHIN 						
			SET @RETURNVALUE = CAST(ISNULL(ERROR_NUMBER(), 0) AS VARCHAR(5)) + '|' + CAST(ISNULL(ERROR_SEVERITY(), 0) AS VARCHAR(5)) + '|' + CAST(ISNULL(ERROR_STATE(), 0) AS VARCHAR(5)) + '|' + CAST(ISNULL(ERROR_PROCEDURE(), '') AS VARCHAR(200)) + '|' + CAST(ISNULL(ERROR_LINE(), 0) AS VARCHAR(5)) + '|' + CAST(ISNULL(ERROR_MESSAGE(), '') AS VARCHAR(1500))

			ROLLBACK TRAN

			SET @RETURNINT = 2

			RAISERROR (
					@RETURNVALUE
					,16
					,1
					)
		END CATCH

		RETURN
	END

	IF @CONDITION = 'POKAYOKE_FAULTBARCODE_SCANNING'
	BEGIN
		DECLARE @EXPRESULT VARCHAR(10)
		DECLARE @ISTESTCOMPLETED VARCHAR(20)

		SELECT @POKAYOKEDATECODE = DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'POKAYOKE', 'POKAYOKE_DATECODE', @PROFITCENTERCODE)

		--ADDED BY RASHID FOR POKAYOKE TWIN INDEX
		DECLARE @SCANNEDSTATIONINDEX INT = 0

		SET @SCANNEDSTATIONINDEX = (
				SELECT DBO.ASSY_FNGETSCANNEDSTATIONINDEX(@LINECODE, @OPERATIONCODE)
				)

		IF (@SCANNEDSTATIONINDEX = - 1)
		BEGIN
			IF NOT EXISTS (
					SELECT 1
					FROM ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE WITH (NOLOCK)
					WHERE LINECODE = @LINECODE
						AND MACHINECODE = @MACHINECODE
						AND OPERATIONCODE = @OPERATIONCODE
					)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'NO PENDING RECORD FOR DECLARING AS FAULT.'

				EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
					,@LINECODE = @LINECODE
					,@OPERATIONCODE = @OPERATIONCODE
					,@BARCODE = @BARCODE
					,@HMIMESSAGE = 'NO PENDING RECORD FOR DECLARING AS FAULT.'

				RETURN
			END
					--CHECK IF CYCLE START HAS NOT PRESSED ,SIMPLY RETURN
			ELSE IF EXISTS (
					SELECT 1
					FROM ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE WITH (NOLOCK)
					WHERE LINECODE = @LINECODE
						AND MACHINECODE = @MACHINECODE
						AND OPERATIONCODE = @OPERATIONCODE
						AND (
							ISNULL(BARCODE, '') = ''
							OR CHARINDEX(@POKAYOKEDATECODE, ISNULL(BARCODE, '')) = 0
							OR ISNULL(ISCYCLESTARTED, 0) = 0
							)
					)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'YOU CAN’T DECLARE A PART AS FAULT BECAUSE TESTING NOT START.'

				EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
					,@LINECODE = @LINECODE
					,@OPERATIONCODE = @OPERATIONCODE
					,@BARCODE = @BARCODE
					,@HMIMESSAGE = 'YOU CAN’T DECLARE A PART AS FAULT BECAUSE TESTING NOT START.'

				RETURN
			END
		END
		ELSE
		BEGIN
			DECLARE @INSIDESTATIONINDEX INT;

			IF (@SCANNEDSTATIONINDEX = 1)
				SET @INSIDESTATIONINDEX = 2
			ELSE IF (@SCANNEDSTATIONINDEX = 2)
				SET @INSIDESTATIONINDEX = 1

			IF NOT EXISTS (
					SELECT 1
					FROM ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE WITH (NOLOCK)
					WHERE LINECODE = @LINECODE
						AND MACHINECODE = @MACHINECODE
						AND OPERATIONCODE = @OPERATIONCODE
						AND STATIONCODE = @INSIDESTATIONINDEX
					)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'NO PENDING RECORD FOR DECLARING AS FAULT.'

				EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
					,@LINECODE = @LINECODE
					,@OPERATIONCODE = @OPERATIONCODE
					,@BARCODE = @BARCODE
					,@HMIMESSAGE = 'NO PENDING RECORD FOR DECLARING AS FAULT.'

				RETURN
			END
					--CHECK IF CYCLE START HAS NOT PRESSED ,SIMPLY RETURN
			ELSE IF EXISTS (
					SELECT 1
					FROM ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE WITH (NOLOCK)
					WHERE LINECODE = @LINECODE
						AND MACHINECODE = @MACHINECODE
						AND OPERATIONCODE = @OPERATIONCODE
						AND STATIONCODE = @INSIDESTATIONINDEX
						AND (
							ISNULL(BARCODE, '') = ''
							OR CHARINDEX(@POKAYOKEDATECODE, ISNULL(BARCODE, '')) = 0
							OR ISNULL(ISCYCLESTARTED, 0) = 0
							)
					)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'YOU CAN’T DECLARE A PART AS FAULT BECAUSE TESTING NOT START.'

				EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
					,@LINECODE = @LINECODE
					,@OPERATIONCODE = @OPERATIONCODE
					,@BARCODE = @BARCODE
					,@HMIMESSAGE = 'YOU CAN’T DECLARE A PART AS FAULT BECAUSE TESTING NOT START.'

				RETURN
			END
		END

		--IF IT IS A SINGLE JIG STATION
		IF (@SCANNEDSTATIONINDEX = - 1)
		BEGIN
			IF EXISTS (
					SELECT 1
					FROM ASSY_STATIONS_ZIG_IN_OUT_STATUS WITH (NOLOCK)
					WHERE LINECODE = @LINECODE
						AND OPERATIONCODE = @OPERATIONCODE
						AND ISNULL(STATUSINOUT, 0) = 1
					)
			BEGIN
				SET @RETURNINT = 1
				SET @RETURNVALUE = 'YOU CAN’T DECLARE A PART AS FAULT BECAUSE JIG IS IN.'

				EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
					,@LINECODE = @LINECODE
					,@OPERATIONCODE = @OPERATIONCODE
					,@BARCODE = @BARCODE
					,@HMIMESSAGE = 'YOU CAN’T DECLARE A PART AS FAULT BECAUSE JIG IS IN.'

				RETURN
			END
		END

		SELECT @BARCODE = S.BARCODE
		FROM ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE S WITH (NOLOCK)
		JOIN ASSY_LINEASSYSTATUS_RUNNING A WITH (NOLOCK) ON S.LINECODE = A.LINECODE
			AND S.MACHINECODE = A.MACHINECODE
			AND S.OPERATIONCODE = A.OPERATIONCODE
			AND S.BARCODE = A.BARCODE
		WHERE S.LINECODE = @LINECODE
			AND S.MACHINECODE = @MACHINECODE
			AND S.OPERATIONCODE = @OPERATIONCODE
			AND ISNULL(A.STATUS, '') = ''

		--IF SCANNED BARCODE EXPECTED  RESULT IS NOT  FAIL RETURN
		SELECT @EXPRESULT = ISNULL(EXPRESULT, '')
		FROM ASSY_POKAYOKE WITH (NOLOCK)
		WHERE PROFITCENTERCODE = @PROFITCENTERCODE
			AND LINECODE = @LINECODE
			AND MACHINECODE = @MACHINECODE
			AND ISNULL(ISACTIVE, 0) = 1
			AND BARCODE = @BARCODE

		IF @EXPRESULT = 'PASS'
		BEGIN
			SET @RETURNINT = 1
			SET @RETURNVALUE = 'YOU CAN’T DECLARE A PART AS FAULT,BECAUSE EXP. RESULT IS PASS.'

			EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE'
				,@LINECODE = @LINECODE
				,@OPERATIONCODE = @OPERATIONCODE
				,@BARCODE = @BARCODE
				,@HMIMESSAGE = 'YOU CAN’T DECLARE A PART AS FAULT,BECAUSE EXP. RESULT IS PASS.'

			RETURN
		END
		ELSE IF @EXPRESULT = 'FAIL'
		BEGIN
			EXEC [ASSY_PROC_UPDATEPOKAYOKESTATUS] @CONDITION = 'UPDATE_POKA_YOKE_RESULT'
				,@PROFITCENTERCODE = @PROFITCENTERCODE
				,@LINECODE = @LINECODE
				,@OPERATIONCODE = @OPERATIONCODE
				,@MACHINECODE = @MACHINECODE
				,@PLCRESULT = 'FAULT'
				,@BARCODE = @BARCODE
				,@USERID = @USERID
				,@ISFAULTBARCODESCANNED = 1

			IF @SCANNEDSTATIONINDEX = - 1
			BEGIN
				UPDATE ASSY_SCAN_OK
				SET BARCODE = ''
				WHERE LINECODE = @LINECODE
					AND MACHINECODE = @MACHINECODE
					AND OPERATIONCODE = @OPERATIONCODE

				UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE
				SET BARCODE = ''
					,ISCYCLESTARTED = 0
				WHERE LINECODE = @LINECODE
					AND MACHINECODE = @MACHINECODE
					AND OPERATIONCODE = @OPERATIONCODE
			END
			ELSE
			BEGIN
				UPDATE ASSY_SCAN_OK
				SET BARCODE = ''
				WHERE LINECODE = @LINECODE
					AND MACHINECODE = @MACHINECODE
					AND OPERATIONCODE = @OPERATIONCODE
					AND STATIONCODE = @INSIDESTATIONINDEX

				UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE
				SET BARCODE = ''
					,ISCYCLESTARTED = 0
				WHERE LINECODE = @LINECODE
					AND MACHINECODE = @MACHINECODE
					AND OPERATIONCODE = @OPERATIONCODE
					AND STATIONCODE = @INSIDESTATIONINDEX
			END

			SET @RETURNINT = 1
			SET @RETURNVALUE = 'PART HAS BEEN SUCCESSFULLY DECLARED AS FAULT.'
		END
		ELSE IF @EXPRESULT = 'FAULT'
		BEGIN
			EXEC [ASSY_PROC_UPDATEPOKAYOKESTATUS] @CONDITION = 'UPDATE_POKA_YOKE_COMPELETE_FOR_FAULT_PART'
				,@PROFITCENTERCODE = @PROFITCENTERCODE
				,@LINECODE = @LINECODE
				,@MACHINECODE = @MACHINECODE
				,@OPERATIONCODE = @OPERATIONCODE
				,@BARCODE = @BARCODE
				,@ISTESTCOMPLETED = @ISTESTCOMPLETED OUT

			IF @ISTESTCOMPLETED = 'NO'
			BEGIN
				UPDATE ASSY_RESULT
				SET BARCODE = @BARCODE
				WHERE OPERATIONCODE = @OPERATIONCODE

				IF @SCANNEDSTATIONINDEX = - 1
				BEGIN
					UPDATE ASSY_SCAN_OK
					SET BARCODE = ''
					WHERE LINECODE = @LINECODE
						AND MACHINECODE = @MACHINECODE
						AND OPERATIONCODE = @OPERATIONCODE

					UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE
					SET BARCODE = ''
						,ISCYCLESTARTED = 0
					WHERE LINECODE = @LINECODE
						AND MACHINECODE = @MACHINECODE
						AND OPERATIONCODE = @OPERATIONCODE
				END
				ELSE
				BEGIN
					UPDATE ASSY_SCAN_OK
					SET BARCODE = ''
					WHERE LINECODE = @LINECODE
						AND MACHINECODE = @MACHINECODE
						AND OPERATIONCODE = @OPERATIONCODE
						AND STATIONCODE = @INSIDESTATIONINDEX

					UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE
					SET BARCODE = ''
						,ISCYCLESTARTED = 0
					WHERE LINECODE = @LINECODE
						AND MACHINECODE = @MACHINECODE
						AND OPERATIONCODE = @OPERATIONCODE
						AND STATIONCODE = @INSIDESTATIONINDEX
				END
			END

			SET @RETURNINT = 1
			SET @RETURNVALUE = 'PART HAS BEEN SUCCESSFULLY DECLARED AS FAULT.'
		END
	END

	DECLARE @FV_OP_CODE VARCHAR(20) = ''
		,@FIRSTSTATIONCODE VARCHAR(20) = ''

	IF @CONDITION = 'GET_TAGS'
	BEGIN
		--SHOW VISION SYSTEM LAST PRINTED BARODE
		SET @FV_OP_CODE = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)
		print @FV_OP_CODE

		SELECT TOP 1 @OPERATIONSEQNO = L.OPERATIONSEQNO
		FROM DBO.ROUTINGCONFIGLINEWISE(NOLOCK) L
		WHERE L.PROFITCENTERCODE = @PROFITCENTERCODE
			AND L.LINECODE = @LINECODE
			AND ISNULL(L.TRACEABILITY, 0) = 1
			AND ISNULL(L.OPERATIONREQUIRED, 0) = 1
			AND l.operationcode = @OPERATIONCODE
			print @OPERATIONSEQNO

		IF @OPERATIONSEQNO = 1
		BEGIN
		print 'gorakh1'
			SELECT @OPERATIONNAME = OPERATIONNAME
			FROM DBO.OPERATIONMST(NOLOCK)
			WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND OPERATIONCODE = @OPERATIONCODE
				AND ISACTIVE = 1
			print 'gorakh2'
			SELECT TOP 1 @OPERATIONNAME AS OPERATIONNAME
				,LPB.BARCODE
				,'' AS TAGNAME
				,'' AS VALUE
				,'PASS' AS RESULT
				,'' AS UOM
			FROM DBO.ASSY_VISION_SYSTEM_LAST_PRINTED_BARCODE(NOLOCK) LPB

			RETURN
		END
		print 'gorakh3'
		IF @OPERATIONCODE = @FV_OP_CODE
		BEGIN

		print 'gorakh4'
			SELECT TOP 1 OPMST.OPERATIONNAME
				,ASSY.BARCODE
				,'' TAGNAME
				,ASSY.VALUE
				,CASE 
					WHEN ISNULL(ASSY.RESULT, '') = 'PS'
						THEN 'PASS'
					WHEN ISNULL(ASSY.RESULT, '') = 'FL'
						THEN 'FAIL'
					END RESULT
				,'' UOM
			FROM (
				SELECT PROFITCENTERCODE
					,LINECODE
					,OPERATIONCODE
					,BARCODE
					,'' AS TAGNAME
					,'' AS VALUE
					,TIMESTAMP
					,RESULT
				FROM DBO.ASSY_LINEASSYPARAMDATA_RUNNING(NOLOCK)
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE
					AND OPERATIONCODE = @OPERATIONCODE
				) ASSY
			INNER JOIN DBO.OPERATIONMST(NOLOCK) OPMST ON ASSY.PROFITCENTERCODE = OPMST.PROFITCENTERCODE
				AND ASSY.OPERATIONCODE = OPMST.OPERATIONCODE
			ORDER BY TIMESTAMP DESC

			RETURN
			print 'gorakh5'
		END

		SELECT TOP 1 @barcode = BARCODE
			,@STATUS = result
		FROM ASSY_LINEASSYPARAMDATA_RUNNING A WITH (NOLOCK)
		WHERE A.PROFITCENTERCODE = @PROFITCENTERCODE
			AND A.LINECODE = @LINECODE
			AND A.OPERATIONCODE = @OPERATIONCODE
		ORDER BY TIMESTAMP DESC
		print 'gorakh6'
		SELECT OPMST.OPERATIONNAME
			,ASSY.BARCODE
			,TAG.TAGDESCRIPTION TAGNAME
			,ASSY.VALUE
			,CASE 
				WHEN ISNULL(ASSY.RESULT, '') = 'PS'
					THEN 'PASS'
				WHEN ISNULL(ASSY.RESULT, '') = 'FL'
					THEN 'FAIL'
				END RESULT
			,ISNULL(TAG.UOM, '') UOM
		FROM (
			SELECT A.PROFITCENTERCODE
				,A.LINECODE
				,A.OPERATIONCODE
				,A.BARCODE
				,B.TAGID
				,B.VALUE
				,A.TIMESTAMP
				,A.RESULT
			FROM DBO.ASSY_LINEASSYPARAMDATA_RUNNING A WITH (NOLOCK)
			INNER JOIN DBO.ASSY_LINEASSYPARAMDATA_RUNNING_DTL B WITH (NOLOCK) ON A.UID = B.UID
			WHERE A.PROFITCENTERCODE = @PROFITCENTERCODE
				AND A.LINECODE = @LINECODE
				AND A.OPERATIONCODE = @OPERATIONCODE
				AND BARCODE = @barcode
				AND result = @STATUS
			) ASSY
		JOIN TAGMST(NOLOCK) TAG ON ASSY.TAGID = TAG.TAGID
			AND TAG.ISACTIVE = 1
		INNER JOIN OPERATIONMST(NOLOCK) OPMST ON ASSY.PROFITCENTERCODE = OPMST.PROFITCENTERCODE
			AND ASSY.OPERATIONCODE = OPMST.OPERATIONCODE
		ORDER BY TIMESTAMP DESC

		RETURN

		print 'gorakh7'
	END

	IF @CONDITION = 'GET_PLCADDRESS'
	BEGIN
		SET @FV_OP_CODE = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)

		SELECT @FIRSTSTATIONCODE = OPERATIONCODE
		FROM ROUTINGCONFIGLINEWISE(NOLOCK)
		WHERE PROFITCENTERCODE = @PROFITCENTERCODE
			AND LINECODE = @LINECODE
			AND OPERATIONSEQNO = 1
			AND TRACEABILITY = 1

		SELECT R.PROFITCENTERCODE
			,R.LINECODE
			,O.OPERATIONNAME
			,O.OPERATIONCODE
			,STATIONCODE
			,R.MACHINECODE
			,MACH.MACHINENAME
			,MACH.PLCADDRESS
		FROM (
			SELECT L.PROFITCENTERCODE
				,L.LINECODE
				,L.OPERATIONCODE
				,L.OPERATIONSEQNO
				,P.PARTNO
				,MD.STATIONCODE
				,P.MACHINECODE
			FROM ROUTINGCONFIGLINEWISE(NOLOCK) L
			INNER JOIN ROUTINGCONFIGPARTWISE(NOLOCK) P ON L.PROFITCENTERCODE = P.PROFITCENTERCODE
				AND L.OPERATIONCODE = P.OPERATIONCODE
				AND L.MACHINECODE = P.MACHINECODE
			INNER JOIN MACHINEDTL MD ON L.OPERATIONCODE = MD.OPERATIONCODE
				AND L.LINECODE = MD.LINECODE
			WHERE L.PROFITCENTERCODE = @PROFITCENTERCODE
				AND L.LINECODE = @LINECODE
				AND P.PARTNO = (
					SELECT TOP 1 ASSY_PARTNO
					FROM ASSY_RUNNINGPART(NOLOCK)
					WHERE LINECODE = @LINECODE
					ORDER BY CREATEDDATE DESC
					)
				AND L.TRACEABILITY = 1
				AND P.TRACEABILITY = 1
			) R
		INNER JOIN OPERATIONMST(NOLOCK) O ON O.PROFITCENTERCODE = R.PROFITCENTERCODE
			AND O.OPERATIONCODE = R.OPERATIONCODE
		LEFT OUTER JOIN MACHINEMST(NOLOCK) MACH ON MACH.PROFITCENTERCODE = R.PROFITCENTERCODE
			AND MACH.MACHINECODE = R.MACHINECODE
		WHERE O.OPERATIONCODE NOT IN (
				@FIRSTSTATIONCODE
				,@FV_OP_CODE
				)
		ORDER BY R.OPERATIONSEQNO

		SET @RETURNINT = 1
		SET @RETURNVALUE = 'SUCCESS'

		RETURN
	END

	IF @CONDITION = 'GET_SHOWRESULT_DATA'
	BEGIN
		SELECT RES.LINECODE
			,RES.OPERATIONCODE
			,RUN.MACHINECODE
			,'' STATIONCODE
			,RUN.BARCODE
			,RUN.STATUS
		FROM ASSY_RESULT(NOLOCK) RES
		INNER JOIN ASSY_LINEASSYSTATUS_RUNNING(NOLOCK) RUN ON RES.LINECODE = RUN.LINECODE
			AND RES.OPERATIONCODE = RUN.OPERATIONCODE
			AND RES.BARCODE = RUN.BARCODE
		WHERE ISNULL(RES.BARCODE, '') <> ''
			AND (
				ISNULL(RUN.STATUS, '') <> ''
				OR CHARINDEX('PKYK', RUN.BARCODE) > 0
				)
		
		UNION
		
		SELECT LINECODE
			,OPERATIONCODE
			,'' MACHINECODE
			,STATIONCODE
			,BARCODE
			,'' STATUS
		FROM ASSY_RESULT(NOLOCK) RES
		WHERE STATIONCODE = 'PKYK'

		UPDATE ASSY_RESULT
		SET BARCODE = ''
			,STATIONCODE = ''
		WHERE ISNULL(BARCODE, '') <> ''
			OR ISNULL(STATIONCODE, '') = 'PKYK'

		SET @RETURNINT = 1
		SET @RETURNVALUE = 'SUCCESS'

		RETURN
	END

	IF @CONDITION = 'GETPARAMETERS'
	BEGIN
		SELECT RTRIM(LTRIM(PARAMETER_C1)) PARAMETER_C1
			,RTRIM(LTRIM(PARAMETER_C2)) PARAMETER_C2
			,RTRIM(LTRIM(PARAMETER_NM)) PARAMETER_NM
			,LTRIM(RTRIM(PARAMETER_VALUE)) PARAMETER_VALUE
		FROM PARAMETER_MST(NOLOCK)
		WHERE PARAMETER_C = 'ASSLINE'
			AND WH_CODE = @PROFITCENTERCODE

		SET @RETURNVALUE = 'DATA SELECTED'
		SET @RETURNINT = 1

		RETURN
	END

	IF @CONDITION = 'GET_ACTIVE_STATION'
	BEGIN
		WITH R (
			PROFITCENTERCODE
			,LINECODE
			,OPERATIONCODE
			,OPERATIONSEQNO
			,PARTNO
			,STATIONCODE
			)
		AS (
			SELECT L.PROFITCENTERCODE
				,L.LINECODE
				,L.OPERATIONCODE
				,L.OPERATIONSEQNO
				,P.PARTNO
				,'' AS STATIONCODE
			FROM DBO.ROUTINGCONFIGLINEWISE(NOLOCK) L
			INNER JOIN DBO.ROUTINGCONFIGPARTWISE(NOLOCK) P ON L.PROFITCENTERCODE = P.PROFITCENTERCODE
				AND L.OPERATIONCODE = P.OPERATIONCODE
				AND L.MACHINECODE = P.MACHINECODE
			WHERE L.PROFITCENTERCODE = @PROFITCENTERCODE
				AND L.LINECODE = @LINECODE
				AND P.PARTNO = (
					SELECT TOP 1 ASSY_PARTNO
					FROM DBO.ASSY_RUNNINGPART WITH (NOLOCK)
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE
					ORDER BY CREATEDDATE DESC
					)
				AND L.TRACEABILITY = 1
				AND P.TRACEABILITY = 1
			)
		SELECT LINECODE
			,O.OPERATIONNAME
			,OPERATIONSEQNO
			,PARTNO
			,O.OPERATIONCODE
			,STATIONCODE
		FROM R WITH (NOLOCK)
		INNER JOIN OPERATIONMST(NOLOCK) O ON O.PROFITCENTERCODE = R.PROFITCENTERCODE
			AND O.OPERATIONCODE = R.OPERATIONCODE
		ORDER BY R.OPERATIONSEQNO

		SET @RETURNINT = 1
		SET @RETURNVALUE = 'SUCCESS'

		RETURN
	END

	IF @CONDITION = 'GET_MACHINE_DTL'
	BEGIN
		SELECT LINECODE
			,MACHINECODE
			,OPERATIONCODE
			,STATIONCODE
		FROM DBO.MACHINEDTL(NOLOCK)
		WHERE PREFIX = @PREFIX
			AND SUFFIX = @SUFFIX
			AND LINECODE = @LINECODE
			AND PROFITCENTERCODE = @PROFITCENTERCODE

		SET @RETURNINT = 1
		SET @RETURNVALUE = 'SUCCESS'

		RETURN
	END

	IF @CONDITION = 'GET_CONTROLLER_PORT_NAME'
	BEGIN
		SELECT @RETURNVALUE = DBO.ASSY_FN_GET_COMPORT_NAME(@PROFITCENTERCODE, @LINECODE, @OPERATIONCODE, 'CONTROLLER', 'SERIALPORT')

		SET @RETURNINT = 1

		RETURN
	END

	IF @CONDITION = 'GET_FV_BT_SCANNER_PORT_NAME'
	BEGIN
		SELECT @RETURNVALUE = DBO.ASSY_FN_GET_COMPORT_NAME(@PROFITCENTERCODE, @LINECODE, @OPERATIONCODE, 'FINALVIEWINGBLUETOOTHSCANNER', 'SERIALPORT')

		SET @RETURNINT = 1

		RETURN
	END

	IF @CONDITION = 'GET_FV_RS232_SCANNER_PORT_NAME'
	BEGIN
		SELECT @RETURNVALUE = DBO.ASSY_FN_GET_COMPORT_NAME(@PROFITCENTERCODE, @LINECODE, @OPERATIONCODE, 'FINALVIEWINGRS232SCANNER', 'SERIALPORT')

		SET @RETURNINT = 1

		RETURN
	END

	--ADDED BY RAVI ON 18-05-16
	IF @CONDITION = 'GET_FV_RFID_READER_PORT_NAME'
	BEGIN
		SELECT @RETURNVALUE = DBO.ASSY_FN_GET_COMPORT_NAME(@PROFITCENTERCODE, @LINECODE, @OPERATIONCODE, 'RFIDREADER', '')

		SET @RETURNINT = 1

		RETURN
	END

	IF @CONDITION = 'CHECK_HARDWARE_PUSHBUTTON_ENABLED'
	BEGIN
		SELECT TOP 1 @RETURNVALUE = CONVERT(VARCHAR(50), ISNULL(FINALVIEWINGHWPUSHBUTTON, 0))
		FROM DBO.ROUTINGCONFIGLINEWISE(NOLOCK)
		WHERE PROFITCENTERCODE = @PROFITCENTERCODE
			AND LINECODE = @LINECODE
			AND TRACEABILITY = 1

		SET @RETURNINT = 1

		RETURN
	END

	IF @CONDITION = 'MACHINEDTL'
	BEGIN
		SELECT MACHINECODE
			,OPERATIONCODE
			,PREFIX
			,SUFFIX
		FROM DBO.MACHINEDTL(NOLOCK)
		WHERE LINECODE = @LINECODE
			AND PROFITCENTERCODE = @PROFITCENTERCODE
			AND (
				ISNULL(PREFIX, '') <> ''
				AND ISNULL(SUFFIX, '') <> ''
				)
		ORDER BY MACHINECODE
			,OPERATIONCODE

		SET @RETURNINT = 1
		SET @RETURNVALUE = 'SUCCESS'

		RETURN
	END

	IF @CONDITION = 'UPDATE_FINALVIEWING_PASS_STATUS'
	BEGIN
		BEGIN TRY
			BEGIN TRAN

			-- Commented By Sachin 13-11-2018
			--IF CHARINDEX(':',@BARCODE)<> 0 AND ISNULL(@BARCODE,'')<>'' 
			--BEGIN
			--		SET @ISSTMC = 1
			--		SELECT DISTINCT @LINECODE_STMC =  ISNULL(LINECODE, '') , @DATECODE_TEMP = ISNULL(DATECODE, '')  FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK) 
			--		WHERE  PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE=@LINECODE AND MACHINECODE =@MACHINECODE  AND BARCODE = @BARCODE  
			--		SET @DATECODE = @DATECODE_TEMP
			--		IF(@LINECODE_STMC)<>''
			--		BEGIN
			--				SELECT DISTINCT @PARTNUMBER=ISNULL(STMC_PART_NO, ''),@DATECODE=DATECODE FROM DBO.ASSY_COUPLINGDETAILS(NOLOCK)
			--				 WHERE PROFITCENTRECODE=@PROFITCENTERCODE  AND LINECODE = @LINECODE AND FG_BARCODE = @BARCODE
			--		END
			--		ELSE
			--			BEGIN
			--				SELECT DISTINCT @PARTNUMBER=ISNULL(STMC_PART_NO, ''),@LINECODE_STMC=LINECODE,@DATECODE=DATECODE FROM DBO.ASSY_COUPLINGDETAILS(NOLOCK) 
			--				WHERE PROFITCENTRECODE=@PROFITCENTERCODE  AND LINECODE = @LINECODE AND FG_BARCODE = @BARCODE
			--			END							  
			--END		
			--ELSE 
			--EKATA DELETE DUPLICATE RECOURD
			--EXEC [dbo].[DeleteDuplicateData_ASSY_LINEASSYSTATUS_RUNNING] @PROFITCENTERCODE
			--	,@LINECODE
			--	,@BARCODE
				 ;
				 WITH CTE (  
	  PROFITCENTERCODE  
	  ,LineCode  
	  ,MachineCode  
	  ,OperationCode  
	  ,barcode  
	  ,datecode  
	  ,partno  
	  ,DuplicateCount  
	  )  
	 AS (  
	  SELECT PROFITCENTERCODE  
	   ,LineCode  
	   ,MachineCode  
	   ,OperationCode  
	   ,barcode  
	   ,datecode  
	   ,partno  
	   ,ROW_NUMBER() OVER (  
		PARTITION BY PROFITCENTERCODE  
		,LineCode  
		,MachineCode  
		,OperationCode  
		,barcode  
		,datecode  
		,partno ORDER BY PROFITCENTERCODE  
		) AS DuplicateCount  
	  FROM ASSY_LINEASSYSTATUS_RUNNING  
	  WHERE LINECODE = @LINECODE  
	   AND PROFITCENTERCODE = @PROFITCENTERCODE  
	   AND BARCODE = @BARCODE  
	  )  
	 DELETE  
	 FROM CTE  
	 WHERE DuplicateCount > 1  


			IF @ISSTMC = 0
				AND ISNULL(@BARCODE, '') <> ''
			BEGIN
				-- commented by Sachin 20170928 -- Vision System not used in ABS Line
				--GET DATECODE AND PART NO OF SNANNED BARCODE FROM VISION SYSTEM
				--SELECT @PARTNUMBER=PARTNO,@DATECODETEMP=DATECODE FROM DBO.ASSY_FN_GET_BARCODEPARTS_FROM_BARCODE(@PROFITCENTERCODE,@LINECODE,@BARCODE)							
				--SET @DATECODE=@DATECODETEMP
				SELECT @DATECODE = Datecode
					,@PARTNUMBER = PartNo
					,@ProductionOrderNo = ProductionOrderNo
				FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
				WHERE BARCODE = @BARCODE
					AND LINECODE = @LINECODE
					AND MACHINECODE = 'MCIG'
					AND OperationCode = 'OCIG'
					AND ProfitcenterCode = @PROFITCENTERCODE
			END

			SELECT @FAILCOUNT = ISNULL(FAILCOUNT, 0)
			FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
			WHERE BARCODE = @BARCODE
				AND LINECODE = @LINECODE
				AND MACHINECODE = @MACHINECODE
				AND STATUS = 'FL'

			IF (
					ISNULL(@PARTNUMBER, '') = ''
					OR ISNULL(@DATECODE, '') = ''
					)
			BEGIN
				SELECT @DATECODE = Datecode
					,@PARTNUMBER = PartNo
					,@ProductionOrderNo = ProductionOrderNo
				FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
				WHERE BARCODE = @BARCODE
					AND LINECODE = @LINECODE
					AND MACHINECODE = 'MCIG'
					AND OperationCode = 'OCIG'
					AND ProfitcenterCode = @PROFITCENTERCODE
			END

			-- Added on 22Dec2020
			IF ISNULL(@DATECODE, '') = ''
				OR ISNULL(@PARTNUMBER, '') = ''
				OR ISNULL(@ProductionOrderNo, '') = ''
			BEGIN
				SELECT @RETURNINT = 2
					,@RETURNVALUE = 'Date Code Empty. Re-run the process. ' + ISNULL(@DATECODE, '') + ISNULL(@PARTNUMBER, '') + ISNULL(@ProductionOrderNo, '')

				ROLLBACK TRAN

				RETURN
			END

			-- Ended on 22Dec2020
			DECLARE @QTY INT

			SELECT @QTY = COUNT(1)
				,@Kanban_Id = ISNULL(Kanban_Id, '')
			FROM Assy_Passed_Items_At_FV WITH (NOLOCK)
			WHERE ProfitCenterCode = @ProfitCenterCode
				AND LineCode = @LineCode
				AND PartNo = ISNULL(@PARTNUMBER, '') -- Added By Sachin 2020May25
				AND ISNULL(Is_Posted, 0) = 0
			GROUP BY Kanban_Id
				,PartNo

			IF (isnull(@Qty, 0) = 0)
			BEGIN
				SELECT TOP 1 @Kanban_Id = ISNULL(KanbanId, '')
				FROM Assy_runningkanban WITH (NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode
					AND LineCode = @LineCode
					AND PartNo = ISNULL(@PARTNUMBER, '') -- Added By Sachin 2020May25
					AND ISNULL(Iscompleted, 0) = 0
				ORDER BY sequenceid ASC
			END

			UPDATE ASSY_LINEASSYSTATUS_RUNNING
			SET STATUS = 'PS'
				,RESULTTIMESTAMP = GETDATE()
				,Live_Datecode = @Live_Datecode
			WHERE LINECODE = @LINECODE
				AND PROFITCENTERCODE = @PROFITCENTERCODE
				AND MACHINECODE = @MACHINECODE
				AND OPERATIONCODE = @OPERATIONCODE
				AND BARCODE = @BARCODE

			--CLEAR SCAN OK BARCODE FROM ASSY_SCANOK
			UPDATE ASSY_SCAN_OK
			SET BARCODE = ''
				,ISSCAN = 0
			WHERE LINECODE = @LINECODE
				AND MACHINECODE = @MACHINECODE
				AND OPERATIONCODE = @OPERATIONCODE

			--INSERT PASS DATA INTO ASSY_LINEASSYPARAMDATA_RUNNING TABLE
			INSERT INTO ASSY_LINEASSYPARAMDATA_RUNNING (
				PROFITCENTERCODE
				,LINECODE
				,MACHINECODE
				,OPERATIONCODE
				,STATIONCODE
				,BARCODE
				,RESULT
				,DATECODE
				,PARTNO
				,USERID
				,TIMESTAMP
				,LIVE_DATECODE
				)
			SELECT @PROFITCENTERCODE
				,@LINECODE
				,@MACHINECODE
				,@OPERATIONCODE
				,@STATIONCODE
				,@BARCODE
				,'PS'
				,@DATECODE
				,@PARTNUMBER
				,@USERID
				,GETDATE()
				,@LIVE_DATECODE

			IF (@ISSTMC = 0)
			BEGIN
				INSERT INTO ASSY_LINEASSYSTATUS (
					PROFITCENTERCODE
					,LINECODE
					,MACHINECODE
					,OPERATIONCODE
					,STATIONCODE
					,BARCODE
					,STATUS
					,FAILCOUNT
					,DATECODE
					,PARTNO
					,SCANTIMESTAMP
					,RESULTTIMESTAMP
					,USERID
					,ProductionOrderNo
					,PROD_LOT_NO
					,-- Added By Sachin By Sachin 20170726
					Live_Datecode
					,Kanban_ID
					)
				SELECT PROFITCENTERCODE
					,LINECODE
					,MACHINECODE
					,OPERATIONCODE
					,STATIONCODE
					,BARCODE
					,STATUS
					,FAILCOUNT
					,DATECODE
					,PARTNO
					,SCANTIMESTAMP
					,RESULTTIMESTAMP
					,USERID
					,ProductionOrderNo
					,PROD_LOT_NO
					,-- Added By Sachin By Sachin 20170726
					Live_Datecode
					,ISNULL(@Kanban_Id, '')
				FROM ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
				WHERE LINECODE = @LINECODE
					AND PROFITCENTERCODE = @PROFITCENTERCODE
					AND BARCODE = @BARCODE
			END
			ELSE
			BEGIN
				INSERT INTO ASSY_LINEASSYSTATUS (
					PROFITCENTERCODE
					,LINECODE
					,MACHINECODE
					,OPERATIONCODE
					,STATIONCODE
					,BARCODE
					,STATUS
					,FAILCOUNT
					,DATECODE
					,PARTNO
					,SCANTIMESTAMP
					,RESULTTIMESTAMP
					,USERID
					,ProductionOrderNo
					,PROD_LOT_NO
					,-- Added By Sachin By Sachin 20170726
					Live_Datecode
					,Kanban_Id
					)
				SELECT PROFITCENTERCODE
					,LINECODE
					,MACHINECODE
					,OPERATIONCODE
					,STATIONCODE
					,BARCODE
					,STATUS
					,FAILCOUNT
					,DATECODE
					,PARTNO
					,SCANTIMESTAMP
					,RESULTTIMESTAMP
					,USERID
					,ProductionOrderNo
					,PROD_LOT_NO
					,-- Added By Sachin By Sachin 20170726
					Live_Datecode
					,ISNULL(@Kanban_Id, '')
				FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE
					AND BARCODE = @BARCODE
				
				UNION
				
				SELECT PROFITCENTERCODE
					,LINECODE
					,MACHINECODE
					,OPERATIONCODE
					,STATIONCODE
					,BARCODE
					,STATUS
					,FAILCOUNT
					,DATECODE
					,PARTNO
					,SCANTIMESTAMP
					,RESULTTIMESTAMP
					,USERID
					,ProductionOrderNo
					,PROD_LOT_NO
					,-- Added By Sachin By Sachin 20170726
					Live_Datecode
					,ISNULL(@Kanban_Id, '')
				FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
				WHERE LINECODE = @LINECODE
					AND PROFITCENTERCODE = @PROFITCENTERCODE
					AND BARCODE IN (
						SELECT CHILD_BARCODE
						FROM DBO.ASSY_COUPLINGDETAILS(NOLOCK)
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE
							AND LINECODE = @LINECODE
							AND FG_BARCODE = @BARCODE
						)
			END

			--SELECT DATA FOR UPDATION INTO MAIN SERVER
			SELECT @STATUS = STATUS
				,@DATECODE = DATECODE
				,@SCANTIMESTAMP = CONVERT(VARCHAR(30), SCANTIMESTAMP, 121)
				,@RESULTTIMESTAMP = CONVERT(VARCHAR(30), RESULTTIMESTAMP, 121)
				,@PARTFAILEDCOUNT = FAILCOUNT
				,@RETURN_LOT_NO = PROD_LOT_NO -- added by sachin 20170726					
			FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
			WHERE LINECODE = @LINECODE
				AND PROFITCENTERCODE = @PROFITCENTERCODE
				AND MACHINECODE = @MACHINECODE
				AND OPERATIONCODE = @OPERATIONCODE
				AND BARCODE = @BARCODE

			---UPDATE PART AS WELL AS SHIFT PASS FAIL COUNTER
			EXEC ASSY_PROC_SHIFTQTY_UPDATE @CONDITION = 'UPDATE'
				,@PROFITCENTERCODE = @PROFITCENTERCODE
				,@ComponentStatus = 'PASS' --Modified by Aadil on 25012021 for Pass mode 
				,@LINECODE = @LINECODE
				,@BARCODE = @BARCODE
				,@OPERATIONCODE = @OPERATIONCODE
				,@CURRENTDATECODE = @DATECODE
				,@CURRENTPARTNO = @PARTNUMBER

			DELETE DBO.ASSY_LINEASSYSTATUS_RUNNING
			WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE
				AND BARCODE = @BARCODE

			IF (@ISSTMC = 1)
			BEGIN
				DELETE ASSY_LINEASSYSTATUS_RUNNING
				WHERE LINECODE = @LINECODE
					AND PROFITCENTERCODE = @PROFITCENTERCODE
					AND BARCODE IN (
						SELECT CHILD_BARCODE
						FROM ASSY_COUPLINGDETAILS WITH (NOLOCK)
						WHERE FG_BARCODE = @BARCODE
						)
			END

			--COMMENT BY RAVI ON 18/03/16
			--UPDATE ASSY_PRODUCTIONORDER_PARAMETERSETTING SET PRODUCTIONQTY=ISNULL(PRODUCTIONQTY,0)+1
			--WHERE LINECODE =@LINECODE   AND PROFITCENTERCODE=@PROFITCENTERCODE
			--UPDATE ASSY_PRODUCTIONORDER_PARAMETERSETTING SET BALANCEQTY=ISNULL(CURRENTPLANNEDQTY,0)-ISNULL(PRODUCTIONQTY,0)
			--WHERE LINECODE =@LINECODE   AND PROFITCENTERCODE=@PROFITCENTERCODE
			--DELETE BARCODE DATA FROM TALLY CHART TABLE, IF A BARCODE HAS ALREADY MARKED AS FAILED
			IF EXISTS (
					SELECT 1
					FROM DBO.ASSY_TALLYCHARTSTATUSDATA(NOLOCK)
					WHERE LINECODE = @LINECODE
						AND PROFITCENTERCODE = @PROFITCENTERCODE
						AND MACHINECODE = @MACHINECODE
						AND BARCODE = @BARCODE
						AND ISNULL(RESULT, '') = 'FAIL'
					)
			BEGIN
				DELETE
				FROM ASSY_TALLYCHARTSTATUSDATA
				WHERE LINECODE = @LINECODE
					AND MACHINECODE = @MACHINECODE
					AND BARCODE = @BARCODE
					AND ISNULL(RESULT, '') = 'FAIL'
					AND PROFITCENTERCODE = @PROFITCENTERCODE

				IF (@ISSTMC = 1)
				BEGIN
					DELETE
					FROM ASSY_TALLYCHARTSTATUSDATA
					WHERE LINECODE = @LINECODE
						AND MACHINECODE = @MACHINECODE
						AND ISNULL(RESULT, '') = 'FAIL'
						AND PROFITCENTERCODE = @PROFITCENTERCODE
						AND @BARCODE IN (
							SELECT CHILD_BARCODE
							FROM ASSY_COUPLINGDETAILS WITH (NOLOCK)
							WHERE FG_BARCODE = @BARCODE
							)
				END
			END

			------------------UPDATE ASSY_POKAYOKE_COMPLETED_DTL TABLE FOR CHECKING WHETHER FINAL VIEWING TESTING HAS BEEN COMPLETED OR NOT--------------------------
			-- ADDED BY RASHID ON 11TH AUGUST 2016
			DECLARE @ISPARTTESTEDAFTERPKYK INT = 0
			DECLARE @CREATEDDATE DATETIME

			SELECT TOP 1 @DATECODE = DATECODE
				,@PARTNO = ASSY_PARTNO
				,@CREATEDDATE = CREATEDDATE
			FROM ASSY_RUNNINGPART WITH (NOLOCK)
			WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE
			ORDER BY CREATEDDATE DESC

			IF EXISTS (
					SELECT 1
					FROM LINEMST WITH (NOLOCK)
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE
						AND ISNULL(ISPOKAYOKEMANDATORY, 0) = 1
					)
			BEGIN
				SELECT @ISPARTTESTEDAFTERPKYK = ISNULL(COUNT(ISNULL(BARCODE, 0)), 0)
				FROM ASSY_LINEASSYSTATUS WITH (NOLOCK)
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE
					AND DATECODE = @DATECODE
					AND MACHINECODE = DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)
					AND PARTNO = @PARTNO
					AND SCANTIMESTAMP >= @CREATEDDATE
					AND ISNULL(ISTALLYCHARTAPPROVED, 0) = 0
					AND ISNULL(STATUS, '') != ''

				IF (ISNULL(@ISPARTTESTEDAFTERPKYK, 0) = 1)
				BEGIN
					--DELETE ASSY_POKAYOKE_COMPLETED_DTL IF DATECODE IS OLD
					IF EXISTS (
							SELECT 1
							FROM ASSY_POKAYOKE_COMPLETED_DTL WITH (NOLOCK)
							WHERE DATECODE != @DATECODE
							)
						TRUNCATE TABLE ASSY_POKAYOKE_COMPLETED_DTL

					IF NOT EXISTS (
							SELECT 1
							FROM ASSY_POKAYOKE_COMPLETED_DTL
							WHERE PROFITCENTERCODE = @PROFITCENTERCODE
								AND LINECODE = @LINECODE
								AND DATECODE = @DATECODE
								AND PARTNO = @PARTNO
							)
					BEGIN
						INSERT INTO ASSY_POKAYOKE_COMPLETED_DTL (
							PROFITCENTERCODE
							,LINECODE
							,DATECODE
							,PARTNO
							,IS_PKYK_COMPLETED
							,IS_FV_COMPLETED
							,TIMESTAMP
							)
						SELECT @PROFITCENTERCODE
							,@LINECODE
							,@DATECODE
							,@PARTNO
							,1
							,(
								CASE 
									WHEN @ISPARTTESTEDAFTERPKYK = 0
										THEN 0
									ELSE 1
									END
								) IS_PKYK_COMPLETED
							,GETDATE()
					END
					ELSE
					BEGIN
						UPDATE ASSY_POKAYOKE_COMPLETED_DTL
						SET TIMESTAMP = GETDATE()
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE
							AND LINECODE = @LINECODE
							AND DATECODE = @DATECODE
							AND PARTNO = @PARTNO
					END
				END
			END

			--DECREASE WIP COUNT AND REOMVE WIP FIFO BARCODE FROM PREVIOS STATION 				
			IF @FAILCOUNT = 0
				EXEC ASSY_PROC_WIP_MANAGE @CONDITION = 'UPDATE_WIP_COUNT'
					,@LINECODE = @LINECODE
					,@MACHINECODE = @MACHINECODE
					,@BARCODE = @BARCODE
					,@PROFITCENTERCODE = @PROFITCENTERCODE

			--RESET DATE CODE STAMPING ACK. AND BARCODE
			EXEC ASSY_PROC_DATECODESTAMPING @CONDITION = 'RESET_ACK'
				,@LINECODE = @LINECODE
				,@PROFITCENTERCODE = @PROFITCENTERCODE

			---UPDATE PART AS WELL AS SHIFT PASS FAIL COUNTER
			--EXEC ASSY_PROC_SHIFTQTY_UPDATE @CONDITION='UPDATE', @PROFITCENTERCODE=@PROFITCENTERCODE
			--,@LINECODE=@LINECODE,@BARCODE=@BARCODE,@OPERATIONCODE=@OPERATIONCODE,@CURRENTDATECODE=@DATECODE,@CURRENTPARTNO=@PARTNUMBER
			-- Get ECU Barcode --
			-- Added by sachin to save bracket assy data
			IF OBJECT_ID('DBO.Assy_BracketData', 'U') IS NOT NULL
			BEGIN
				SELECT @RETURN_ECU_BARCODE = ChildPartBarcode
				FROM ASSY_CHILD_PART_DETAILS(NOLOCK)
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE
					AND BARCODE = @BARCODE
					AND ChildPartNo = 'ECU_BARCODE'

				SET @RETURN_ECU_BARCODE = ISNULL(@RETURN_ECU_BARCODE, '')

				IF (@RETURN_ECU_BARCODE <> '')
				BEGIN
					INSERT INTO Assy_BracketData (
						ProfitCenterCode
						,LineCode
						,Barcode
						,ECU_Barcode
						,Part_No
						,Result
						,Entdate
						,prcss_flg
						,prcss_dt
						)
					SELECT @PROFITCENTERCODE
						,@LINECODE
						,@BARCODE
						,@RETURN_ECU_BARCODE
						,@PARTNUMBER
						,@STATUS
						,getdate()
						,0
						,NULL
				END
			END

			SET @RETURNINT = 1
			SET @RETURNVALUE = 'PASSED'

			SELECT @RETURNINT RETURNINT
				,@RETURNVALUE RETURNVALUE

			SELECT @SCANTIMESTAMP SCANTIMESTAMP
				,@RESULTTIMESTAMP RESULTTIMESTAMP
				,@STATUS STATUS
				,@PARTFAILEDCOUNT PARTFAILEDCOUNT
				,@DATECODE DATECODE
				,@PARTNUMBER PARTNUMBER
				,ISNULL(@RETURN_LOT_NO, '') LOT_NO
				,ISNULL(@RETURN_ECU_BARCODE, '') ECU_BARCODE -- Added By Sachin By Sachin 20170726,
				,ISNULL(@ProductionOrderNo, '') [ProductionOrderNo]

			COMMIT TRAN
				-- INSERT COUPLING DATA INTO CENTRAL SERVER
				-- START -- ADDED BY RASHID ON 20TH JUNE 2016 -----
				--					IF CHARINDEX(':',@BARCODE) <> 0 AND ISNULL(@BARCODE,'') <> ''
				--					BEGIN
				--						SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL WITH (NOLOCK) 
				--								WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE	
				--						SET @EXECQUERY = ''
				--						SET @EXECQUERY = '
				--							IF EXISTS (SELECT 1 FROM ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + ''')
				--							BEGIN
				--								INSERT INTO ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS_HISTORY (PROFITCENTRECODE,LINECODE,STMC_PART_NO,CHILD_PART_NO,PART_TYPE,MACHINE_CODE,OPERATION_CODE,TORQUE_1,TORQUE_2,ENT_DT,ENT_BY,FG_BARCODE,CHILD_BARCODE,DATECODE,HIS_ENT_DT,HIS_EN
				T_

			--B
			--Y)
			--								SELECT PROFITCENTRECODE,LINECODE,STMC_PART_NO,CHILD_PART_NO,PART_TYPE,MACHINE_CODE,OPERATION_CODE,TORQUE_1,TORQUE_2,ENT_DT,ENT_BY,FG_BARCODE,CHILD_BARCODE,DATECODE,GETDATE(),''' + ISNULL(@USERID,'''') 
			--								+ ''' FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + '''
			--								DELETE FROM ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS WHERE PROFITCENTRECODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + '''
			--								IF NOT EXISTS (SELECT 1 FROM ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + ''')
			--								BEGIN
			--									INSERT INTO ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS (PROFITCENTRECODE,LINECODE,STMC_PART_NO,CHILD_PART_NO,PART_TYPE,MACHINE_CODE,OPERATION_CODE,TORQUE_1,TORQUE_2,ENT_DT,ENT_BY,FG_BARCODE,CHILD_BARCODE,DATECODE)
			--									SELECT PROFITCENTRECODE,LINECODE,STMC_PART_NO,CHILD_PART_NO,PART_TYPE,MACHINE_CODE,OPERATION_CODE,TORQUE_1,TORQUE_2,ENT_DT,ENT_BY,FG_BARCODE,CHILD_BARCODE,DATECODE FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = ''' + 
			--									@PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + '''
			--								END
			--							END
			--							ELSE
			--							BEGIN
			--								INSERT INTO ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS (PROFITCENTRECODE,LINECODE,STMC_PART_NO,CHILD_PART_NO,PART_TYPE,MACHINE_CODE,OPERATION_CODE,TORQUE_1,TORQUE_2,ENT_DT,ENT_BY,FG_BARCODE,CHILD_BARCODE,DATECODE)
			--								SELECT PROFITCENTRECODE,LINECODE,STMC_PART_NO,CHILD_PART_NO,PART_TYPE,MACHINE_CODE,OPERATION_CODE,TORQUE_1,TORQUE_2,ENT_DT,ENT_BY,FG_BARCODE,CHILD_BARCODE,DATECODE FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = ''' 
			--								+ @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + '''
			--							END
			--							'
			--						PRINT @EXECQUERY
			--						EXEC (@EXECQUERY)
			--					END
			-- END -- ADDED BY RASHID ON 20TH JUNE 2016 -----		       
			--------------Update Previous count and parametersetting data
			IF EXISTS (
					SELECT 1
					FROM ASSY_RUNNINGPART_PREVIOUS(NOLOCK)
					WHERE ASSY_MODE IN (
							'PRODUCTION'
							,'REWORK'
							)
						AND LINECODE = @LINECODE
						AND CURRENTPLANNEDQTY > ISNULL(PRODUCEDQTY, 0)
					)
			BEGIN
				SELECT TOP 1 *
				INTO #ASSY_RUNNINGPART_PREVIOUS
				FROM ASSY_RUNNINGPART_PREVIOUS
				WHERE LINECODE = @LINECODE
					AND CURRENTPLANNEDQTY > ISNULL(PRODUCEDQTY, 0)
					AND Assy_PartNo = @PARTNUMBER
				ORDER BY CreatedDate ASC

				UPDATE RPS
				SET RPS.PRODUCEDQTY = ISNULL(RPS.PRODUCEDQTY, 0) + 1
					,RPS.BALANCEQTY = ISNULL(RPS.BALANCEQTY, 0) - 1
				FROM ASSY_RUNNINGPART_PREVIOUS RPS
				INNER JOIN #ASSY_RUNNINGPART_PREVIOUS(NOLOCK) RK ON RK.ProductionOrderNo = RPS.PRODUCTIONORDERNO
				WHERE RPS.LINECODE = @LINECODE

				DELETE
				FROM ASSY_RUNNINGPART_PREVIOUS
				WHERE LINECODE = @LINECODE
					AND CURRENTPLANNEDQTY = ISNULL(PRODUCEDQTY, 0)
			END
			ELSE
			BEGIN
				UPDATE ASSY_PRODUCTIONORDER_PARAMETERSETTING
				SET PRODUCTIONQTY = ISNULL(PRODUCTIONQTY, 0) + 1
					,BALANCEQTY = ISNULL(BALANCEQTY, 0) - 1
				WHERE LINECODE = @LINECODE
					AND PROFITCENTERCODE = @PROFITCENTERCODE
			END
		END TRY

		BEGIN CATCH
			SET @RETURNVALUE = CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + CAST(ERROR_SEVERITY() AS VARCHAR(5)) + '|' + CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + CAST(ERROR_MESSAGE() AS VARCHAR(1500))

			ROLLBACK TRAN

			SET @RETURNINT = 2

			RAISERROR (
					@RETURNVALUE
					,16
					,1
					)
		END CATCH

		RETURN
	END

	IF @CONDITION = 'UPDATE_FINALVIEWING_FAIL_STATUS'
	BEGIN
		BEGIN TRY
			BEGIN TRAN

			--  IF CHARINDEX(':',@BARCODE)<> 0 AND ISNULL(@BARCODE,'')<>'' 
			--	BEGIN
			--			SET @ISSTMC = 1
			--			SELECT DISTINCT @LINECODE_STMC =  ISNULL(LINECODE, '') , @DATECODE_TEMP = ISNULL(DATECODE, '')  FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK) 
			--			WHERE  PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE=@LINECODE AND MACHINECODE =@MACHINECODE  AND BARCODE = @BARCODE  
			--			SET @DATECODE = @DATECODE_TEMP
			--			IF(@LINECODE_STMC)<>''
			--			BEGIN
			--					SELECT DISTINCT @PARTNUMBER=ISNULL(STMC_PART_NO, ''),@DATECODE=DATECODE FROM DBO.ASSY_COUPLINGDETAILS(NOLOCK)
			--					 WHERE FG_BARCODE = @BARCODE AND LINECODE = @LINECODE
			--			END
			--			ELSE
			--				BEGIN
			--					SELECT DISTINCT @PARTNUMBER=ISNULL(STMC_PART_NO, ''),@LINECODE_STMC=LINECODE,@DATECODE=DATECODE FROM DBO.ASSY_COUPLINGDETAILS(NOLOCK) 
			--					WHERE FG_BARCODE = @BARCODE 
			--					AND LINECODE = @LINECODE AND PROFITCENTRECODE=@PROFITCENTERCODE
			--				END							  
			--END		
			--ELSE 
			IF @ISSTMC = 0
				AND ISNULL(@BARCODE, '') <> ''
			BEGIN
				-- commented by Sachin 20170928 -- Vision System not used in ABS Line
				--GET DATECODE AND PART NO OF SNANNED BARCODE FROM VISION SYSTEM
				--SELECT @PARTNUMBER=PARTNO,@DATECODETEMP=DATECODE FROM DBO.ASSY_FN_GET_BARCODEPARTS_FROM_BARCODE(@PROFITCENTERCODE,@LINECODE,@BARCODE)							
				--SET @DATECODE=@DATECODETEMP
				SELECT @DATECODE = Datecode
					,@PARTNUMBER = PartNo
				FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
				WHERE BARCODE = @BARCODE
					AND LINECODE = @LINECODE
					AND MACHINECODE = 'MCIG'
					AND OperationCode = 'OCIG'
					AND ProfitcenterCode = @PROFITCENTERCODE
			END

			UPDATE ASSY_LINEASSYSTATUS_RUNNING
			SET STATUS = 'FL'
				,RESULTTIMESTAMP = GETDATE()
				,FAILCOUNT = ISNULL(FAILCOUNT, 0) + 1
				,Live_Datecode = @Live_Datecode
			WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE
				AND MACHINECODE = @MACHINECODE
				AND OPERATIONCODE = @OPERATIONCODE
				AND BARCODE = @BARCODE
				AND ISNULL(STATUS, '') <> 'PS'

			--CLEAR SCAN OK BARCODE FROM ASSY_SCANOK
			UPDATE ASSY_SCAN_OK
			SET BARCODE = ''
				,ISSCAN = 0
			WHERE LINECODE = @LINECODE
				AND MACHINECODE = @MACHINECODE
				AND OPERATIONCODE = @OPERATIONCODE

			IF (
					ISNULL(@PARTNUMBER, '') = ''
					OR ISNULL(@DATECODE, '') = ''
					)
			BEGIN
				SELECT @DATECODE = Datecode
					,@PARTNUMBER = PartNo
				FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
				WHERE BARCODE = @BARCODE
					AND LINECODE = @LINECODE
					AND MACHINECODE = 'MCIG'
					AND OperationCode = 'OCIG'
					AND ProfitcenterCode = @PROFITCENTERCODE
			END

			--INSERT FAIL DATA INTO ASSY_LINEASSYPARAMDATA_RUNNING TABLE
			INSERT INTO ASSY_LINEASSYPARAMDATA_RUNNING (
				PROFITCENTERCODE
				,LINECODE
				,MACHINECODE
				,OPERATIONCODE
				,STATIONCODE
				,BARCODE
				,RESULT
				,DATECODE
				,USERID
				,TIMESTAMP
				,PARTNO
				,LIVE_DATECODE
				)
			SELECT @PROFITCENTERCODE
				,@LINECODE
				,@MACHINECODE
				,@OPERATIONCODE
				,@STATIONCODE
				,@BARCODE
				,'FL'
				,@DATECODE
				,@USERID
				,GETDATE()
				,@PARTNUMBER
				,@LIVE_DATECODE

			SELECT @FAILCOUNTDEFINED = CONVERT(INT, PARAMETER_VALUE)
			FROM PARAMETER_MST(NOLOCK)
			WHERE PARAMETER_C = 'ASSLINE'
				AND PARAMETER_C1 = 'REWORK_COUNT'
				AND WH_CODE = @PROFITCENTERCODE

			SELECT @FAILCOUNT = ISNULL(FAILCOUNT, 0)
			FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
			WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE
				AND BARCODE = @BARCODE
				AND MACHINECODE = @MACHINECODE
				AND ISNULL(STATUS, '') = 'FL'

			--SELECT DATA FOR UPDATION INTO MAIN SERVER
			SELECT @STATUS = STATUS
				,@DATECODE = DATECODE
				,@SCANTIMESTAMP = SCANTIMESTAMP
				,@RESULTTIMESTAMP = RESULTTIMESTAMP
				,@RETURN_LOT_NO = PROD_LOT_NO -- Added By Sachin By Sachin 20170726				
			FROM ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
			WHERE LINECODE = @LINECODE
				AND PROFITCENTERCODE = @PROFITCENTERCODE
				AND MACHINECODE = @MACHINECODE
				AND OPERATIONCODE = @OPERATIONCODE
				AND BARCODE = @BARCODE

			--MOVE BARCODE FROM RUNNING TO ASSY_LINEASSYSTATUS TABLE AFTER MAXIMUMM NO OF TIMES FAIL REACHED
			IF @FAILCOUNTDEFINED = @FAILCOUNT
			BEGIN
				IF (@ISSTMC = 0)
				BEGIN
					INSERT INTO ASSY_LINEASSYSTATUS (
						PROFITCENTERCODE
						,LINECODE
						,MACHINECODE
						,OPERATIONCODE
						,STATIONCODE
						,BARCODE
						,STATUS
						,FAILCOUNT
						,DATECODE
						,PARTNO
						,SCANTIMESTAMP
						,RESULTTIMESTAMP
						,USERID
						,ProductionOrderNo
						,PROD_LOT_NO
						,-- Added By Sachin By Sachin 20170726
						Live_Datecode
						)
					SELECT PROFITCENTERCODE
						,LINECODE
						,MACHINECODE
						,OPERATIONCODE
						,STATIONCODE
						,BARCODE
						,STATUS
						,FAILCOUNT
						,DATECODE
						,PARTNO
						,SCANTIMESTAMP
						,RESULTTIMESTAMP
						,USERID
						,ProductionOrderNo
						,PROD_LOT_NO
						,-- Added By Sachin By Sachin 20170726
						Live_Datecode
					FROM ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
					WHERE LINECODE = @LINECODE
						AND BARCODE = @BARCODE
				END
				ELSE
				BEGIN
					INSERT INTO ASSY_LINEASSYSTATUS (
						PROFITCENTERCODE
						,LINECODE
						,MACHINECODE
						,OPERATIONCODE
						,STATIONCODE
						,BARCODE
						,STATUS
						,FAILCOUNT
						,DATECODE
						,PARTNO
						,SCANTIMESTAMP
						,RESULTTIMESTAMP
						,USERID
						,ProductionOrderNo
						,PROD_LOT_NO
						,-- Added By Sachin By Sachin 20170726
						Live_Datecode
						)
					SELECT PROFITCENTERCODE
						,LINECODE
						,MACHINECODE
						,OPERATIONCODE
						,STATIONCODE
						,BARCODE
						,STATUS
						,FAILCOUNT
						,DATECODE
						,PARTNO
						,SCANTIMESTAMP
						,RESULTTIMESTAMP
						,USERID
						,ProductionOrderNo
						,PROD_LOT_NO
						,-- Added By Sachin By Sachin 20170726
						Live_Datecode
					FROM ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
					WHERE LINECODE = @LINECODE
						AND BARCODE = @BARCODE
					
					UNION
					
					SELECT PROFITCENTERCODE
						,LINECODE
						,MACHINECODE
						,OPERATIONCODE
						,STATIONCODE
						,BARCODE
						,STATUS
						,FAILCOUNT
						,DATECODE
						,PARTNO
						,SCANTIMESTAMP
						,RESULTTIMESTAMP
						,USERID
						,ProductionOrderNo
						,PROD_LOT_NO
						,-- Added By Sachin By Sachin 20170726
						Live_Datecode
					FROM ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
					WHERE LINECODE = @LINECODE
						AND BARCODE IN (
							SELECT CHILD_BARCODE
							FROM ASSY_COUPLINGDETAILS(NOLOCK)
							WHERE FG_BARCODE = @BARCODE
							)
				END

				---UPDATE PART AS WELL AS SHIFT PASS FAIL COUNTER
				EXEC ASSY_PROC_SHIFTQTY_UPDATE @CONDITION = 'UPDATE'
					,@ComponentStatus = 'FAIL'
					,@PROFITCENTERCODE = @PROFITCENTERCODE --Modified by Aadil on 25012021 for Pass mode 
					,@LINECODE = @LINECODE
					,@BARCODE = @BARCODE
					,@OPERATIONCODE = @OPERATIONCODE
					,@CURRENTDATECODE = @DATECODE
					,@CURRENTPARTNO = @PARTNUMBER

				DELETE ASSY_LINEASSYSTATUS_RUNNING
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE
					AND BARCODE = @BARCODE

				DELETE
				FROM ASSY_VISION_SYSTEM
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE
					AND BARCODE = @BARCODE

				IF (@ISSTMC = 1)
				BEGIN
					DELETE ASSY_LINEASSYSTATUS_RUNNING
					WHERE LINECODE = @LINECODE
						AND BARCODE IN (
							SELECT CHILD_BARCODE
							FROM ASSY_COUPLINGDETAILS(NOLOCK)
							WHERE FG_BARCODE = @BARCODE
							)
				END
			END
			ELSE
			BEGIN
				--[Start] Added by Aadil for Pass fail qty update 
				---UPDATE PART AS WELL AS SHIFT PASS FAIL COUNTER
				EXEC ASSY_PROC_SHIFTQTY_UPDATE @CONDITION = 'UPDATE'
					,@ComponentStatus = 'FAIL'
					,@PROFITCENTERCODE = @PROFITCENTERCODE --Modified by Aadil on 25012021 for Pass mode 
					,@LINECODE = @LINECODE
					,@BARCODE = @BARCODE
					,@OPERATIONCODE = @OPERATIONCODE
					,@CURRENTDATECODE = @DATECODE
					,@CURRENTPARTNO = @PARTNUMBER
					--[END] Added by Aadil for Pass fail qty update 
			END

			--RESET DATE CODE STAMPING ACK. AND BARCODE
			EXEC ASSY_PROC_DATECODESTAMPING @CONDITION = 'RESET_ACK'
				,@LINECODE = @LINECODE
				,@PROFITCENTERCODE = @PROFITCENTERCODE

			--DECREASE WIP COUNT AND REOMVE WIP FIFO BARCODE FROM PREVIOS STATION 	
			IF @FAILCOUNT = 1
				EXEC ASSY_PROC_WIP_MANAGE @CONDITION = 'UPDATE_WIP_COUNT'
					,@LINECODE = @LINECODE
					,@MACHINECODE = @MACHINECODE
					,@BARCODE = @BARCODE
					,@PROFITCENTERCODE = @PROFITCENTERCODE

			---UPDATE PART AS WELL AS SHIFT PASS FAIL COUNTER
			--EXEC ASSY_PROC_SHIFTQTY_UPDATE @CONDITION='UPDATE', @PROFITCENTERCODE=@PROFITCENTERCODE
			--,@LINECODE=@LINECODE,@BARCODE=@BARCODE,@OPERATIONCODE=@OPERATIONCODE,@CURRENTDATECODE=@DATECODE,@CURRENTPARTNO=@PARTNUMBER
			-- Get ECU Barcode --
			-- Added by sachin to save bracket assy data
			IF OBJECT_ID('DBO.Assy_BracketData', 'U') IS NOT NULL
			BEGIN
				SELECT @RETURN_ECU_BARCODE = ChildPartBarcode
				FROM ASSY_CHILD_PART_DETAILS(NOLOCK)
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE
					AND BARCODE = @BARCODE
					AND ChildPartNo = 'ECU_BARCODE'

				SET @RETURN_ECU_BARCODE = ISNULL(@RETURN_ECU_BARCODE, '')

				IF (@RETURN_ECU_BARCODE <> '')
				BEGIN
					INSERT INTO Assy_BracketData (
						ProfitCenterCode
						,LineCode
						,Barcode
						,ECU_Barcode
						,Part_No
						,Result
						,Entdate
						,prcss_flg
						,prcss_dt
						)
					SELECT @PROFITCENTERCODE
						,@LINECODE
						,@BARCODE
						,@RETURN_ECU_BARCODE
						,@PARTNUMBER
						,@STATUS
						,getdate()
						,0
						,NULL
				END
			END

			SET @RETURNINT = 1
			SET @RETURNVALUE = 'FAILED'

			SELECT @RETURNINT RETURNINT
				,@RETURNVALUE RETURNVALUE

			SELECT @SCANTIMESTAMP SCANTIMESTAMP
				,@RESULTTIMESTAMP RESULTTIMESTAMP
				,@STATUS STATUS
				,@FAILCOUNT PARTFAILEDCOUNT
				,@DATECODE DATECODE
				,@PARTNUMBER PARTNUMBER
				,ISNULL(@RETURN_LOT_NO, '') LOT_NO
				,ISNULL(@RETURN_ECU_BARCODE, '') ECU_BARCODE -- Added By Sachin By Sachin 20170726

			COMMIT TRAN
		END TRY

		BEGIN CATCH
			SET @RETURNVALUE = CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + CAST(ERROR_SEVERITY() AS VARCHAR(5)) + '|' + CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + CAST(ERROR_MESSAGE() AS VARCHAR(1500))
			SET @RETURNINT = 2

			ROLLBACK TRAN

			RAISERROR (
					@RETURNVALUE
					,16
					,1
					)
		END CATCH

		RETURN
	END

	IF @CONDITION = 'GET_FINALVIEWING_LAST_SCAN_BARCODE'
	BEGIN
		SELECT @RETURNVALUE = ISNULL(BARCODE, '')
		FROM ASSY_SCAN_OK(NOLOCK)
		WHERE LINECODE = @LINECODE
			AND OPERATIONCODE = @OPERATIONCODE
			AND MACHINECODE = @MACHINECODE

		SET @RETURNINT = 1

		RETURN
	END

	IF @CONDITION = 'GET_NO_OF_CHANGEOVERS'
	BEGIN
		DECLARE @CHANGEOVERCOUNT INT

		SELECT @CHANGEOVERCOUNT = DBO.ASSY_FN_GET_CHANGEOVER_COUNT(@PROFITCENTERCODE, @LINECODE, @CHANGEOVER_DATECODE)

		SET @RETURNVALUE = CONVERT(VARCHAR(30), @CHANGEOVERCOUNT)
		SET @RETURNINT = 1

