			,@FINALVIEWING_MACHINECODE = DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)

		SET @RETURNVALUE = @FINALVIEWING_MACHINECODE + '|' + @FINALVIEWING_OPERATIONCODE
		SET @RETURNINT = 1

		RETURN
	END

	IF @CONDITION = 'GET_FIRSTSTATION_MACHINECODE'
