	IF @CONDITION = 'UPDATE_FV_QC_OK_PASS_DATA_IN_MAINSERVER'
	BEGIN
		BEGIN TRY
			IF EXISTS (
					SELECT 1
					FROM ASSY_LINEASSYSTATUS(NOLOCK)
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE
						AND MACHINECODE = @MACHINECODE
						AND OPERATIONCODE = @OPERATIONCODE --AND STATUS = 'FL'  // commented by sachin if user rework a pass part 20170729
						AND BARCODE = @BARCODE
					)
			BEGIN
				DELETE
				FROM ASSY_LINEASSYSTATUS
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE
					AND MACHINECODE = @MACHINECODE
					AND OPERATIONCODE = @OPERATIONCODE --AND STATUS = 'FL' // commented by sachin if user rework a pass part 20170729
					AND BARCODE = @BARCODE
			END
					---- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING STOCK DEDUCTION ----
			ELSE
			BEGIN
				--START-- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING STOCK DEDUCTION
				IF (
						(
							SELECT ISNULL(ISMATFEEDREQUIRED, 0)
							FROM LINEMST WITH (NOLOCK)
							WHERE PROFITCENTERCODE = @PROFITCENTERCODE
								AND LINECODE = @LINECODE
							) = 1
						)
				BEGIN
					PRINT 'RASHID'

					EXEC ASSY_PROC_MATERIALFEEDINGVALIDATION @CONDITION = 'MAT_FEED_STOCK_DEDUCTION'
						,@PROFITCENTERCODE = @PROFITCENTERCODE
						,@LINECODE = @LINECODE
						,@USERID = @USERID
						,@PARTNUMBER = @PARTNUMBER
						,@BARCODE = @BARCODE
				END
						--END-- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING STOCK DEDUCTION
			END

			INSERT INTO ASSY_LINEASSYSTATUS (
				PROFITCENTERCODE
				,LINECODE
				,MACHINECODE
				,OPERATIONCODE
				,STATIONCODE
				,BARCODE
				,STATUS
				,FAILCOUNT
				,DATECODE
				,PARTNO
				,SCANTIMESTAMP
				,RESULTTIMESTAMP
				,USERID
				,ProductionOrderNo
				,PROD_LOT_NO
				,Live_Datecode
				)
			SELECT @PROFITCENTERCODE
				,@LINECODE
				,@MACHINECODE
				,@OPERATIONCODE
				,@STATIONCODE
				,@BARCODE
				,@STATUS
				,@PARTFAILEDCOUNT
				,@DATECODE
				,@PARTNUMBER
				,@SCANTIMESTAMP
				,@RESULTTIMESTAMP
				,@USERID
				,@ProductionOrderNo
				,@P_Lot_No
				,@Live_Datecode

			-- Added by sachin to save bracket assy data
			IF OBJECT_ID('DBO.Assy_BracketData', 'U') IS NOT NULL
			BEGIN
				INSERT INTO Assy_BracketData (
					ProfitCenterCode
					,LineCode
					,Barcode
					,ECU_Barcode
					,Part_No
					,Result
					,Entdate
					,prcss_flg
					,prcss_dt
					)
				SELECT @PROFITCENTERCODE
					,@LINECODE
					,@BARCODE
					,@P_ECU_Barcode
					,@PARTNUMBER
					,@STATUS
					,getdate()
					,0
					,NULL
			END

			----START-- ADDED BY RASHID SIDDIQUI ON 08TH AUGUST 2016 FOR MATERIAL FEEDING STOCK DEDUCTION
			IF (
					(
						SELECT ISNULL(ISPRODCONFREQUIRED, 0)
						FROM LINEMST WITH (NOLOCK)
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE
							AND LINECODE = @LINECODE
						) = 1
					)
			BEGIN
				IF EXISTS (
						SELECT 1
						FROM ASSY_MAT_FEED_STATUS_ISPRODCONF WITH (NOLOCK)
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE
							AND LINECODE = @LINECODE
						)
				BEGIN
					UPDATE ASSY_FGCHILDPARTCONSUMPTION
					SET ISACTIVE = 2
					WHERE WH_CODE = @PROFITCENTERCODE
						AND LINE_CODE = @LINECODE
						AND ISACTIVE = 1

					DELETE
					FROM ASSY_MAT_FEED_STATUS_ISPRODCONF
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE
				END
			END

			----END-- ADDED BY RASHID SIDDIQUI ON 08TH AUGUST 2016 FOR MATERIAL FEEDING STOCK DEDUCTION
			--ADDED BY RAVI ON 18/03/16-------------
			DELETE
			FROM ASSY_LINEASSYSTATUS_FV_LASTTESTED_BARCODE
			WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE

			INSERT INTO ASSY_LINEASSYSTATUS_FV_LASTTESTED_BARCODE (
				PROFITCENTERCODE
				,LINECODE
				,MACHINECODE
				,OPERATIONCODE
				,BARCODE
				,DATECODE
				,PARTNO
				,SCANTIMESTAMP
				,RESULTTIMESTAMP
				)
			SELECT @PROFITCENTERCODE
				,@LINECODE
				,@MACHINECODE
				,@OPERATIONCODE
				,@BARCODE
				,@DATECODE
				,@PARTNUMBER
				,@SCANTIMESTAMP
				,@RESULTTIMESTAMP

			--------------------------END--------------
			IF @STATUS = 'PS'
			BEGIN
				IF EXISTS (
						SELECT 1
						FROM ASSY_RUNNINGPART_PREVIOUS(NOLOCK)
						WHERE ASSY_MODE IN (
								'PRODUCTION'
								,'REWORK'
								)
							AND LINECODE = @LINECODE
							AND CURRENTPLANNEDQTY > ISNULL(PRODUCEDQTY, 0)
						)
				BEGIN
					--UPDATE PRODUCE QTY INTO ASSY_PRODUCTIONORDERMST
					UPDATE POM
					SET POM.PRODUCEDQTY = ISNULL(POM.PRODUCEDQTY, 0) + 1
					FROM ASSY_PRODUCTIONORDERMST(NOLOCK) POM
					INNER JOIN ASSY_RUNNINGPART_PREVIOUS(NOLOCK) RP ON POM.ORDERNO = RP.PRODUCTIONORDERNO
						AND POM.PARTNO = RP.ASSY_PARTNO
					WHERE RP.LINECODE = @LINECODE
						AND POM.PROFITCENTERCODE = @PROFITCENTERCODE
						AND POM.STATUS <> '100'
						AND POM.WORKCENTERCODE IN (
							SELECT DISTINCT L.WORKCENTERCODE
							FROM LINEMST(NOLOCK) L
							INNER JOIN ASSY_LINEGROUP_MASTER(NOLOCK) LG ON L.PROFITCENTERCODE = LG.PROFITCENTERCODE
								AND L.LINECODE = LG.LINECODE
							WHERE LG.GROUPCODE = (
									SELECT GROUPCODE
									FROM ASSY_LINEGROUP_MASTER(NOLOCK)
									WHERE LINECODE = @LINECODE
									)
								AND L.ISACTIVE = 1
							)

					UPDATE ASSY_RUNNINGPART_PREVIOUS
					SET PRODUCEDQTY = ISNULL(PRODUCEDQTY, 0) + 1
					WHERE LINECODE = @LINECODE

					UPDATE ASSY_RUNNINGPART_PREVIOUS
					SET BALANCEQTY = ISNULL(CURRENTPLANNEDQTY, 0) - ISNULL(PRODUCEDQTY, 0)
					WHERE LINECODE = @LINECODE

					UPDATE POM
					SET POM.STATUS = '100'
					FROM ASSY_PRODUCTIONORDERMST(NOLOCK) POM
					INNER JOIN ASSY_RUNNINGPART_PREVIOUS(NOLOCK) RP ON POM.ORDERNO = RP.PRODUCTIONORDERNO
						AND POM.PARTNO = RP.ASSY_PARTNO
					WHERE RP.LINECODE = @LINECODE
						AND POM.PROFITCENTERCODE = @PROFITCENTERCODE
						AND POM.STATUS <> '100'
						AND POM.QTY = POM.PRODUCEDQTY
						AND POM.WORKCENTERCODE IN (
							SELECT DISTINCT L.WORKCENTERCODE
							FROM LINEMST(NOLOCK) L
							INNER JOIN ASSY_LINEGROUP_MASTER(NOLOCK) LG ON L.PROFITCENTERCODE = LG.PROFITCENTERCODE
								AND L.LINECODE = LG.LINECODE
							WHERE LG.GROUPCODE = (
									SELECT GROUPCODE
									FROM ASSY_LINEGROUP_MASTER(NOLOCK)
									WHERE LINECODE = @LINECODE
									)
								AND L.ISACTIVE = 1
							)

					IF EXISTS (
							SELECT 1
							FROM ASSY_RUNNINGPART_PREVIOUS(NOLOCK)
							WHERE ASSY_MODE IN (
									'PRODUCTION'
									,'REWORK'
									)
								AND LINECODE = @LINECODE
								AND CURRENTPLANNEDQTY = ISNULL(PRODUCEDQTY, 0)
							)
					BEGIN
						DELETE
						FROM ASSY_RUNNINGPART_PREVIOUS
						WHERE LINECODE = @LINECODE
					END
				END
				ELSE
				BEGIN
					--UPDATE PRODUCE QTY INTO ASSY_PRODUCTIONORDERMST
					UPDATE POM
					SET PRODUCEDQTY = ISNULL(PRODUCEDQTY, 0) + 1
					FROM ASSY_PRODUCTIONORDERMST(NOLOCK) POM
					INNER JOIN ASSY_RUNNINGPART(NOLOCK) RP ON POM.ORDERNO = RP.PRODUCTIONORDERNO
						AND POM.PARTNO = RP.ASSY_PARTNO
					WHERE RP.LINECODE = @LINECODE
						AND POM.PROFITCENTERCODE = @PROFITCENTERCODE
						AND POM.STATUS <> '100'
						AND POM.WORKCENTERCODE IN (
							SELECT DISTINCT L.WORKCENTERCODE
							FROM LINEMST(NOLOCK) L
							INNER JOIN ASSY_LINEGROUP_MASTER(NOLOCK) LG ON L.PROFITCENTERCODE = LG.PROFITCENTERCODE
								AND L.LINECODE = LG.LINECODE
							WHERE LG.GROUPCODE = (
									SELECT GROUPCODE
									FROM ASSY_LINEGROUP_MASTER(NOLOCK)
									WHERE LINECODE = @LINECODE
									)
								AND L.ISACTIVE = 1
							)

					UPDATE ASSY_PRODUCTIONORDER_PARAMETERSETTING
					SET PRODUCTIONQTY = ISNULL(PRODUCTIONQTY, 0) + 1
					WHERE LINECODE = @LINECODE
						AND PROFITCENTERCODE = @PROFITCENTERCODE

					UPDATE ASSY_PRODUCTIONORDER_PARAMETERSETTING
					SET BALANCEQTY = ISNULL(CURRENTPLANNEDQTY, 0) - ISNULL(PRODUCTIONQTY, 0)
					WHERE LINECODE = @LINECODE
						AND PROFITCENTERCODE = @PROFITCENTERCODE

					UPDATE POM
					SET POM.STATUS = '100'
					FROM ASSY_PRODUCTIONORDERMST(NOLOCK) POM
					INNER JOIN ASSY_RUNNINGPART(NOLOCK) RP ON POM.ORDERNO = RP.PRODUCTIONORDERNO
						AND POM.PARTNO = RP.ASSY_PARTNO
					WHERE RP.LINECODE = @LINECODE
						AND POM.PROFITCENTERCODE = @PROFITCENTERCODE
						AND POM.STATUS <> '100'
						AND POM.QTY = POM.PRODUCEDQTY
						AND POM.WORKCENTERCODE IN (
							SELECT DISTINCT L.WORKCENTERCODE
							FROM LINEMST(NOLOCK) L
							INNER JOIN ASSY_LINEGROUP_MASTER(NOLOCK) LG ON L.PROFITCENTERCODE = LG.PROFITCENTERCODE
								AND L.LINECODE = LG.LINECODE
							WHERE LG.GROUPCODE = (
									SELECT GROUPCODE
									FROM ASSY_LINEGROUP_MASTER(NOLOCK)
									WHERE LINECODE = @LINECODE
									)
								AND L.ISACTIVE = 1
							)
				END

				SET @RETURNVALUE = 'SUCCESS'
				SET @RETURNINT = 1
			END
		END TRY

		BEGIN CATCH
			SET @RETURNVALUE = CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + CAST(ERROR_SEVERITY() AS VARCHAR(5)) + '|' + CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + CAST(ERROR_MESSAGE() AS VARCHAR(1500))
			SET @RETURNINT = 2

			--ROLLBACK TRAN
			RAISERROR (
					@RETURNVALUE
					,16
					,1
					)
		END CATCH

		RETURN
	END

