	IF @CONDITION = 'UPDATE_FINALVIEWING_FROMLOCALDBTOMAIN'
	BEGIN
		DECLARE @OPCODE VARCHAR(20) = ''
			,@FV_COUNT INT = 0
			,@ERRORCOUNT INT = - 1
		DECLARE @DROP_RECORDS INT = 0

		SELECT @DROP_RECORDS = COUNT(*)
		FROM ASSY_LINEASSYSTATUS_NETWORK_DROP_RECORDS(NOLOCK)
		WHERE PROFITCENTERCODE = @PROFITCENTERCODE
			AND LINECODE = @LINECODE

		IF (@DROP_RECORDS > 0)
		BEGIN
			SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME
			FROM ASSY_LINKSERVER_DTL WITH (NOLOCK)
			WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE

			SELECT @OPCODE = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)

			IF @OPCODE = ''
			BEGIN
				IF (LEFT(@LINECODE, 1) = 'M')
					SET @OPCODE = 'OCFV'
				ELSE IF (LEFT(@LINECODE, 1) = 'P')
					SET @OPCODE = 'OCFVSTMC'
			END

			IF (@OPCODE != '')
			BEGIN
				SET @EXECQUERY = '
					INSERT INTO ' + @LINKSERVERNAME + '.DBO.ASSY_LINEASSYSTATUS (PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,STATIONCODE,BARCODE,STATUS,FAILCOUNT,DATECODE,PARTNO,SCANTIMESTAMP,RESULTTIMESTAMP,ACTIVE,USERID,ISTALLYCHARTAPPROVED,TRANSACTION_NUMBER
					ISCONFIRMED,KANBAN_ID,ERP_CONF_TIMESTAMP,ISREWORKPART,IS_MANUAL,Live_Datecode)
					SELECT PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,STATIONCODE,BARCODE,STATUS,FAILCOUNT,DATECODE,PARTNO,SCANTIMESTAMP,RESULTTIMESTAMP,ACTIVE,USERID,ISTALLYCHARTAPPROVED,TRANSACTION_NUMBER,ISCONFIRMED,KANBAN_ID,ERP_CONF_TIMESTAMP,ISREWORKPART,
					IS_MANUAL,Live_Datecode FROM ASSY_LINEASSYSTATUS (NOLOCK) WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + '''
					AND LINECODE = ''' + @LINECODE + ''' AND OPERATIONCODE = ''' + @OPCODE + ''' AND BARCODE IN (SELECT BARCODE FROM ASSY_LINEASSYSTATUS_NETWORK_DROP_RECORDS (NOLOCK) WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + 
					''')
					AND BARCODE NOT IN (SELECT BARCODE FROM ' + @LINKSERVERNAME + '.DBO.ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND OPERATIONCODE = ''' + @OPCODE + ''')
					'

				PRINT @EXECQUERY

				EXEC (@EXECQUERY)

				SET @ERRORCOUNT = @@ERROR

				IF @ERRORCOUNT > 0
				BEGIN
					SET @RETURNVALUE = ''
					SET @RETURNINT = 0

					RETURN
				END
			END

			IF (@ERRORCOUNT = 0)
			BEGIN
				TRUNCATE TABLE ASSY_LINEASSYSTATUS_NETWORK_DROP_RECORDS

				SET @RETURNVALUE = 'SUCCESS'
				SET @RETURNINT = 1
			END
		END
		ELSE
		BEGIN
			SET @RETURNVALUE = 'NORECORDFOUND'
			SET @RETURNINT = 1
		END
	END

