	IF @CONDITION = 'DELETE_RUNNINGPART_NOTPRINT'
	BEGIN
		DECLARE @ASSY_DATECODE CHAR(4) = ''

		IF ISNULL(RTRIM(@CHANGEOVER_DATECODE), '') = 'NA'
		BEGIN
			EXEC ASSY_PROC_DATECODE @PROFITCENTERCODE = @PROFITCENTERCODE
				,@RETURNVALUE = @CHANGEOVER_DATECODE OUTPUT
		END

		IF ISNULL(@CHANGEOVER_DATECODE, '') != ''
		BEGIN
			SELECT TOP 1 @PARTNO = ASSY_PARTNO
				,@ASSY_DATECODE = DATECODE
			FROM ASSY_RUNNINGPART(NOLOCK)
			WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE

			IF @ASSY_DATECODE != @CHANGEOVER_DATECODE
			BEGIN
				SELECT @OPERATIONCODE = RTRIM(LTRIM(OPERATIONCODE))
				FROM ROUTINGCONFIGLINEWISE(NOLOCK)
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE
					AND OPERATIONSEQNO = 1

				IF NOT EXISTS (
						SELECT TOP 1 1
						FROM ASSY_BARCODE_PRINTED_COUNTER A(NOLOCK)
						INNER JOIN ASSY_RUNNINGPART R(NOLOCK) ON A.PROFITCENTERCODE = R.PROFITCENTERCODE
							AND A.LINECODE = R.LINECODE
						WHERE A.LINECODE = @LINECODE
							AND ISNULL(A.PRINTEDQTY, 0) > 0
						)
				BEGIN
					DELETE
					FROM ASSY_RUNNINGPART
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE
						AND LINECODE = @LINECODE

					SET @RETURNVALUE = 'Y'
					SET @RETURNINT = 1
				END
				ELSE
				BEGIN
					SET @RETURNVALUE = 'N'
					SET @RETURNINT = 1
				END
			END
		END
	END
	ELSE IF @CONDITION = 'ASSY_LINEASSYSTATUS_NETWORK_DROP_RECORDS'
	BEGIN
		IF NOT EXISTS (
				SELECT 1
				FROM ASSY_LINEASSYSTATUS_NETWORK_DROP_RECORDS(NOLOCK)
				WHERE BARCODE = @BARCODE
				)
		BEGIN
			INSERT INTO ASSY_LINEASSYSTATUS_NETWORK_DROP_RECORDS (
				PROFITCENTERCODE
				,LINECODE
				,MACHINECODE
				,BARCODE
				)
			SELECT @PROFITCENTERCODE
				,@LINECODE
				,@MACHINECODE
				,@BARCODE
		END
	END

	IF @CONDITION = 'GET_COUPLING_STATIONS_PARAMETER_DATA'
	BEGIN
		SELECT RTRIM(LTRIM(PARAMETER_C2)) PARAMETER_C2
			,RTRIM(LTRIM(PARAMETER_VALUE)) PARAMETER_VALUE
		FROM PARAMETER_MST(NOLOCK)
		WHERE PARAMETER_C = 'ASSLINE'
			AND PARAMETER_C1 = 'COUPLING'
			AND WH_CODE = @PROFITCENTERCODE

		SET @RETURNINT = 1
	END

	--ADDED BY RAVI ON 01-06-2016 FOR JHAGADIA
	IF @CONDITION = 'IS_LABEL_PRINTING_REQUIRED_AT_FV'
	BEGIN
		IF EXISTS (
				SELECT 1
				FROM ROUTINGCONFIGLINEWISE WITH (NOLOCK)
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE
					AND MACHINECODE = DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)
					AND ISNULL(LABELPRINTING, 0) = 1
				)
		BEGIN
			SET @RETURNVALUE = 'Y'
		END
		ELSE
		BEGIN
			SET @RETURNVALUE = 'N'
		END

		SET @RETURNINT = 1
	END

	--ADDED BY RAVI ON 01-06-2016 FOR JHAGADIA
	IF @CONDITION = 'GET_PRN_FILE_FOR_FV'
	BEGIN
		SELECT @RETURNVALUE = PRNFILE
		FROM ASSY_PRN_GROUPMASTER WITH (NOLOCK)
		WHERE GROUPCODE = 'GC_JHAGADIA_FINALVIEWING_STATION'

		SET @RETURNINT = 1

		RETURN
	END

	--ADDED BY RAVI ON 02-08-2016 FOR JHAGADIA
	IF @CONDITION = 'RUN2PARTS_AT_SAMETIME'
	BEGIN
		--SELECT @RETURNVALUE=PRNFILE FROM ASSY_PRN_GROUPMASTER WITH(NOLOCK) WHERE GROUPCODE ='GC_JHAGADIA_FINALVIEWING_STATION'	
		IF EXISTS (
				SELECT 1
				FROM LINEMST WITH (NOLOCK)
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE
					AND ISNULL(ISACTIVE, 0) = 1
					AND ISNULL(ALLOW2PARTS, 0) = 1
				)
		BEGIN
			SET @RETURNVALUE = 'Y'
		END
		ELSE
		BEGIN
			SET @RETURNVALUE = 'N'
		END

		SET @RETURNINT = 1

		RETURN
	END
	ELSE IF @CONDITION = 'ASSY_LINEASSYSTATUS_RFID_NETWORK_DROP_RECORDS'
	BEGIN
		IF NOT EXISTS (
				SELECT 1
				FROM DBO.ASSY_FINALVIEWING_RFID_BARCODE_NETWORK_DROP(NOLOCK)
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE
					AND RFID = @BARCODE
					AND MACHINECODE = @MACHINECODE
				)
		BEGIN
			INSERT INTO ASSY_FINALVIEWING_RFID_BARCODE_NETWORK_DROP (
				PROFITCENTERCODE
				,LINECODE
				,MACHINECODE
				,RFID
				)
			SELECT @PROFITCENTERCODE
				,@LINECODE
				,@MACHINECODE
				,@BARCODE
		END

		RETURN
	END

	IF @CONDITION = 'UPDATE_RFID_DATA_FROMLOCALDBTOMAIN'
	BEGIN
		SELECT @DROP_RECORDS = COUNT(RFID)
		FROM DBO.ASSY_FINALVIEWING_RFID_BARCODE_NETWORK_DROP(NOLOCK)
		WHERE PROFITCENTERCODE = @PROFITCENTERCODE
			AND LINECODE = @LINECODE

		IF (@DROP_RECORDS > 0)
		BEGIN
			SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME
			FROM ASSY_LINKSERVER_DTL WITH (NOLOCK)
			WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE

			SELECT @OPCODE = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)

			IF (@OPCODE != '')
			BEGIN
				SET @EXECQUERY = '
					INSERT INTO ' + @LINKSERVERNAME + '.DBO.ASSY_FINALVIEWING_RFID_BARCODE_MAPPING
					(PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,RFID,BARCODE,STATUS,
					PARTNO,DATECODE,PRINTEDTIMESTAMP,CALIPERSERNO)
					SELECT PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,RFID,BARCODE,STATUS,
					PARTNO,DATECODE,PRINTEDTIMESTAMP,CALIPERSERNO
					FROM ASSY_FINALVIEWING_RFID_BARCODE_MAPPING (NOLOCK) WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + '''
					AND LINECODE = ''' + @LINECODE + ''' AND OPERATIONCODE = ''' + @OPCODE + ''' AND
					RFID IN (SELECT RFID FROM ASSY_FINALVIEWING_RFID_BARCODE_NETWORK_DROP (NOLOCK)
					WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''')
				
					AND RFID NOT IN (SELECT RFID FROM ' + @LINKSERVERNAME + '.DBO.ASSY_FINALVIEWING_RFID_BARCODE_MAPPING 
					WITH (NOLOCK) WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' 
					AND OPERATIONCODE = ''' + @OPCODE + ''')'

				--PRINT @EXECQUERY
				EXEC (@EXECQUERY)

				SET @ERRORCOUNT = @@ERROR

				IF @ERRORCOUNT > 0
				BEGIN
					SET @RETURNVALUE = ''
					SET @RETURNINT = 0

					RETURN
				END
			END

			IF (@ERRORCOUNT = 0)
			BEGIN
				TRUNCATE TABLE ASSY_FINALVIEWING_RFID_BARCODE_NETWORK_DROP

				SET @RETURNVALUE = 'SUCCESS'
				SET @RETURNINT = 1
			END
		END
		ELSE
		BEGIN
			SET @RETURNVALUE = 'NORECORDFOUND'
			SET @RETURNINT = 1
		END
	END

	IF @CONDITION = 'IsRFIDBased_Traceability'
	BEGIN
		IF EXISTS (
				SELECT 1
				FROM dbo.Linemst WITH (NOLOCK)
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE
					AND LINECODE = @LINECODE
					AND isnull(IsRFIDBasedScanning, 0) = 1
				)
		BEGIN
			SET @RETURNVALUE = 'Y'
		END
		ELSE
		BEGIN
			SET @RETURNVALUE = 'N'
		END

		SET @RETURNINT = 1

		RETURN
	END

	IF @CONDITION = 'FETCH_MACHINECODE_AND_OPERATIONCODE'
	BEGIN
		SELECT ISNULL(MachineCode, '') MachineCode
			,ISNULL(OperationCode, '') OperationCode
			,ISNULL(StationCode, '1') StationCode
		FROM MachineDtl(NOLOCK)
		WHERE PROFITCENTERCODE = @PROFITCENTERCODE
			AND LINECODE = @LINECODE
			AND ScannerIpAddress = @ScannerIpAddress
			AND ScannerPortNo = @ScannerPortNo

		SET @RETURNINT = 1

		RETURN
	END
	ELSE IF @CONDITION = 'FETCH_SCANNERIP_ADDRESS_AND_PORTNO'
	BEGIN
		SELECT ISNULL(ScannerIpAddress, '') ScannerIpAddress
			,ISNULL(ScannerPortNo, 0) ScannerPortNo
		FROM MachineDtl(NOLOCK)
		WHERE PROFITCENTERCODE = @PROFITCENTERCODE
			AND LINECODE = @LINECODE
			AND OperationCode = @OPERATIONCODE

		SET @RETURNINT = 1

		RETURN
	END
	ELSE IF @CONDITION = 'IS_IPBASED_SCANNING_REQUIRED'
	BEGIN
		IF EXISTS (
				SELECT TOP 1 1
				FROM RoutingConfigDetails(NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode
					AND LineCode = @LineCode
					AND Sts_cd = 0
					AND KeyType = 'IsIPbasedScanningRequired'
					AND keyValue = '1'
				)
		BEGIN
			SET @RETURNVALUE = 'Y'
		END
		ELSE
		BEGIN
			SET @RETURNVALUE = 'N'
		END

		SET @RETURNINT = 1

		RETURN
	END
			--Added By Rashid On 20180531 For Multiple COM Port Scaning Mode
	ELSE IF @CONDITION = 'IS_MULTIPLE_COM_SCANNING_REQUIRED'
	BEGIN
		IF EXISTS (
				SELECT TOP 1 1
				FROM RoutingConfigDetails(NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode
					AND LineCode = @LineCode
					AND Sts_cd = 0
					AND KeyType = 'IsMultiCOMScanningRequired'
					AND keyValue = '1'
				)
		BEGIN
			SET @RETURNVALUE = 'Y'
		END
		ELSE
		BEGIN
			SET @RETURNVALUE = 'N'
		END

		SET @RETURNINT = 1

		RETURN
	END
			--Added By Rashid On 20180531 For Multiple COM Port Scaning Mode
	ELSE IF @CONDITION = 'FETCH_PORTNO_FOR_MULTI_COM'
	BEGIN
		SELECT ISNULL(ScannerPortNo, 0) ScannerPortNo
		FROM MachineDtl(NOLOCK)
		WHERE PROFITCENTERCODE = @PROFITCENTERCODE
			AND LINECODE = @LINECODE
			AND OperationCode = @OPERATIONCODE

		SET @RETURNINT = 1

		RETURN
	END
			--Added By Rashid On 20180531 For Multiple COM Port Scanning Mode
	ELSE IF @CONDITION = 'FETCH_MACHINECODE_AND_OPCODE_MULTICOM'
	BEGIN
		SELECT TOP 1 ISNULL(MachineCode, '') MachineCode
			,ISNULL(OperationCode, '') OperationCode
			,ISNULL(StationCode, '1') StationCode
		FROM MachineDtl(NOLOCK)
		WHERE PROFITCENTERCODE = @PROFITCENTERCODE
			AND LINECODE = @LINECODE
			AND @ScannerPortNo IN (
				SELECT *
				FROM dbo.splitstring(ScannerPortNo, ',')
				)

		SET @RETURNINT = 1

		RETURN
	END
			--Added By Rashid On 20180531 For Multiple COM Port Scanning Mode
	ELSE IF @CONDITION = 'GET_COM_STATION_WISE_LIST'
	BEGIN
		SELECT ProfitCenterCode
			,LineCode
			,MachineCode
			,OperationCode
			,'COM' + CONVERT(VARCHAR, ISNULL(ScannerPortNo, 0)) PortNo
		FROM MachineDtl(NOLOCK)
		WHERE ProfitCenterCode = @ProfitCenterCode
			AND LineCode = @LineCode

		SELECT @RETURNINT = 1

		RETURN
	END
END
GO
