CREATE PROC [dbo].[ASSY_PROC_FINALVIEWING_BIJ]
(
	@CONDITION VARCHAR(200), 
	@PROFITCENTERCODE VARCHAR(10) = NULL, 
	@LINECODE VARCHAR(10) = NULL, 
	@OPERATIONCODE VARCHAR(20)=NULL,
	@MACHINECODE VARCHAR(20)=NULL,
	@STATIONCODE VARCHAR(10) = '1', 
	@DATECODE VARCHAR(4)=NULL,
	@PARTNUMBER VARCHAR(20)=NULL,
	@BARCODE VARCHAR(200)=NULL,
	@PREFIX CHAR(2)=NULL,
	@SUFFIX CHAR(2)=NULL,
	@USERID VARCHAR(20) = NULL, 
	@PASSQTY INT=0,
	@FAILQTY INT=0,
	@STATUS CHAR(2)=NULL,
	@SCANTIMESTAMP DATETIME = NULL,
	@RESULTTIMESTAMP DATETIME = NULL,
	@PARTFAILEDCOUNT TINYINT = 0,
	@FIRSTEXECUTE BIT = 0, 
	@RETURNVALUE VARCHAR (MAX) = NULL OUT, 
	@RETURNINT INT=NULL OUT,
	@SUBSTNMACHINECODE VARCHAR(20)=NULL ,
	@SUBSTNOPERATIONCODE VARCHAR(20)=NULL, --ADDED BY RAVI ON 21-JULY-17
	@ALLOW2PARTS BIT=0,
	@P_LOT_NO VARCHAR(40)=NULL,
	@P_ECU_BARCODE  VARCHAR(50)=NULL,
	@P_EKanbanAllowed bit = 0, -- Added By Sachin 2020June04
	@PRNGroupCode VARCHAR(50) = NULL , -- Added By Rashid 2020Sep25
	@P_AutoFVMachineCode VARCHAR(10) = NULL,  -- Added By Sachin 07Oct2020'
	@P_FINALVIEWING_OPERATIONCODE VARCHAR(20) = NULL,  -- Added By Sachin 210215
	@P_FINALVIEWING_MACHINECODE VARCHAR(20) = NULL, -- Added By Sachin 210215
	@P_LIVE_DATE_CODE  VARCHAR(4) = NULL, -- Added By Sachin 210215
	@P_PREVMACHINECODE  VARCHAR(20) = NULL,  -- Added By Sachin 210215
	@P_PREVOPERATIONCODE  VARCHAR(20) = NULL,  -- Added By Sachin 210215
	@P_PREVMACHINENAME  VARCHAR(20) = NULL,  -- Added By Sachin 210215
	@P_LINETYPE_NAME VARCHAR(20) = NULL,  -- Added By Sachin 210215
	@P_VALIDATE_DATECODE bit = 0, -- Added By Sachin 210215
	@P_NOOFSTATIONS int = 0, -- Added By Sachin 210215
	@P_ISPOKAYOKEMANDATORY bit = 0, -- Added By Sachin 210215
	@P_POKA_YOKE_ALLOWED bit = 0, -- Added By Sachin 210215
	@P_ISMATFEEDREQUIRED bit = 0, -- Added By Sachin 210215
	@P_LABELPRINTING bit = 0 , -- Added By Sachin 210215
	@P_POKAYOKEDATECODE varchar(4) = '', -- Added By Sachin 210215
	@P_IS2PARTSFIFO  bit = 0,  -- Added By Sachin 210215
	@P_RECIPE bit = 0,  -- Added By Sachin 210215
	@P_OPERATIONSEQNO int = 0,  -- Added By Sachin 210215
	@P_INDEXPERSTATIONS int = 0,  -- Added By Sachin 210215
	@P_IsTorqueCapturingFromKepServer bit = 0,  -- Added By Sachin 210215
	@P_IsCheckParameter bit = 0,  -- Added By Sachin 210215
	@P_REWORK_VISION_COUNT int = 0,  -- Added By Sachin 210215
	@P_REWORK_COUNT int = 0,  -- Added By Sachin 210215
	@P_CRIMPING_MACHINECODE varchar(10)='',  -- Added By Sachin 210215
	@P_FINALVIEWING_SERVO_PERFORMANCE_MACHINECODE  varchar(10)='',  -- Added By Sachin 210215
	@P_BOOSTERLINE_CRIMPINGTIMELIMIT int = 0, -- Added By Sachin 210215
	@P_Family_Group_Code varchar(50)='',  -- Added By Sachin 210302,
	@Kanban_Id varchar(40)='',
	@Assy_str VARCHAR(MAX) = ''
)
AS
BEGIN
	-- AUTHOR:			<RAVISHANKAR MISHRA>
	-- CREATE DATE:		< 5 SEP 2014>
	-- DESCRIPTION:		<FINAL VIEWING.>

	-- MODIFIED BY:	<RAVISHANKAR MISHRA>
	-- MODIFIED ON: <30-03-2016>
	-- DESCRIPTION: <CHANGED IN BLOCK GET_TAGS FOR SHOWING DATA AS PER FS LINE-2 CHANGES >

	-- MODIFIED BY:	<RAVISHANKAR MISHRA>
	-- MODIFIED ON: <23-08-2016>
	-- DESCRIPTION: <ADDED BLOCK TO CHECK RUN 2 PARTS AT A TIME FROM LINE MASTER.>
					--SYNC RFID BARCODE MAPPING TABLE IF NETWORK PROBLEM

	-- MODIFIED BY:	<RAVISHANKAR MISHRA>
	-- MODIFIED ON: <08-09-2016>
	-- DESCRIPTION: <DELETE VISION SYSTEM TABLE AFTER DECLARING A PART PASS OR AFTER MAKING A PART FIVE TIMES FAIL..>
	-- MODIFIED ON:     <09-SEP-2016>
	-- DESCRIPTION:     <JIG IS NOT COME OUT FROM PERFORMANCE STATION PROPERLY. RETEST IN PREVIOUS STATION>

	-- MODIFIED BY:	<RAVISHANKAR MISHRA>
	-- MODIFIED ON: <11-11-2016>
	-- DESCRIPTION: CORRECTED GET_TAGS CONDITION TO SHOW ALL PARAMETERS DATA ALONG WITH ITS RESULT.

	-- MODIFIED BY:	<RAVISHANKAR MISHRA>
	-- MODIFIED ON: <08-12-2016>
	-- DESCRIPTION: TO ALLOW TO SCAN A PART ON FINAL QC STATION ONLY WHEN CALIPER SERIAL NO HAS BEEN FOUND IN PARAMETER TABLE.

	-- MODIFIED BY:	<SACHIN>
	-- MODIFIED ON: <03-03-2017>
	-- DESCRIPTION: CHECK ALL DATA BEFORE PRINT

	-- MODIFIED BY:	<SACHIN>
	-- MODIFIED ON: <11-04-2017>
	-- DESCRIPTION: ISNULL ADDED IN CATCH , REMARK LENGHT MODIFIED TO 500

	-- MODIFIED BY:	<RASHID SIDDIQUI>
	-- MODIFIED ON: <20170607>
	-- DESCRIPTION: ADD LOGIC FOR TWO PARTS IN SCAN_OK AND ADD NEW CONDITION - GET_PART_NO_STATION_WISE_LIST,GET_NON_HMI_STATION_LIST,GET_FAMILY_RUNNING_PART_LIST,UPDATE_PART_NO_STATION_WISE,CHECKAUTOTALLYCHARTENABLE

	-- MODIFIED BY:		< SUDESH KUMAR > 
	-- MODIFIED ON:		< 20170615 > 
	-- DESCRIPTION:		< ADDED COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING FOR MAPPING OF PRODUCTION ORDER WITH BARCODE >

    -- MODIFIED BY:	< RAVISHANKAR MISHRA> 
	-- MODIFIED ON:	< 22-08-17 > 
	-- DESCRIPTION:	ADDED BLOCK TO CHECK WHETHER THIS LINE IS BASED ON RFID OR NOT AND ALSO PUT VALIDATION FOR 2 PARTS FIFO
	-- MODIFIED ON:	< 18-09-17 > 
	-- DESCRIPTION:	MERGED WITH ABS

	-- TO REMBEMBER
	-- NOTHING = 0
	-- SUCCESS = 1
	-- ERROR = 2
	-- ALREADYEXISTS = 3
	-- NOTEXISTS = 4

	/*
	SELECT * FROM ASSY_STATIONS_ZIG_IN_OUT_STATUS
	EXEC [ASSY_PROC_FINALVIEWING] @CONDITION='UPDATE_FINALVIEWING_FROMLOCALDBTOMAIN',@LINECODE='M08' ,@PROFITCENTERCODE='0021'
	*/

	--UPDATE  ASSY_STATIONS_ZIG_IN_OUT_STATUS SET STATUSINOUT=1
	--EXEC [ASSY_PROC_FINALVIEWING] @CONDITION='GET_ACTIVE_STATION',@LINECODE='J04',@PROFITCENTERCODE='0088'
	--29150259
	--DECLARE @RETURNVALUE VARCHAR(2000)
	--EXEC ASSY_PROC_FINALVIEWING @CONDITION='UPDATE_FINALVIEWING_PASS_STATUS',@PROFITCENTERCODE='0021',@LINECODE='M07',@OPERATIONCODE='OCFV',@MACHINECODE='MCFV',@PARTNUMBER='29066835',
	--@BARCODE='2906683551QA00000002M07',@RETURNVALUE=@RETURNVALUE OUT,@STATIONCODE='1',@DATECODE='51QA'
	----SELECT @RETURNVALUE
	
	--DECLARE @P9 VARCHAR(2000)
	--SET @P9='SCANNED_SUCCESSFULLY'	
	--DECLARE @P10 INT	
	--EXEC ASSY_PROC_FINALVIEWING @CONDITION=N'SCAN_OK',@LINECODE=N'J05',@OPERATIONCODE=N'OC4S',@BARCODE='2903305230QD00000345J05'
	--,@STATIONCODE=N'1',@PROFITCENTERCODE=N'0088',@MACHINECODE=N'MC4S',@USERID=N'1445',@RETURNVALUE=@P9 OUTPUT,@RETURNINT=@P10 OUTPUT,@SUBSTNMACHINECODE='MCPFT',@SUBSTNOPERATIONCODE='OCPFT'
	--SELECT @P9, @P10
	
	--GO
	--EXEC ASSY_PROC_FINALVIEWING	@CONDITION='UPDATE_FV_QC_OK_PASS_DATA_IN_MAINSERVER',@LINECODE='',@MACHINECODE='',@OPERATIONCODE='',@BARCODE=''

	--DECLARE @RETURNVALUE1 VARCHAR(2000)='RAVI'
	--EXEC ASSY_PROC_FINALVIEWING @CONDITION='POKAYOKE_FAULTBARCODE_SCANNING',@PROFITCENTERCODE='0021',@LINECODE='M08',@OPERATIONCODE='OCMSLH',@MACHINECODE='MCMS'
	--,@BARCODE='FAULTBARCODEFORPOKAYOKE',@RETURNVALUE=@RETURNVALUE1 OUT,@STATIONCODE='1',@DATECODE='37GB'
	--SELECT @RETURNVALUE1
	--EXEC ASSY_PROC_FINALVIEWING @CONDITION='GET_TAGS',@PROFITCENTERCODE='0088',@LINECODE='J04',@OPERATIONCODE='OCCR'
	--EXEC ASSY_PROC_FINALVIEWING @CONDITION='UPDATE_RFID_DATA_FROMLOCALDBTOMAIN',@PROFITCENTERCODE='0088',@LINECODE='J04'
        
        DECLARE @FAILCOUNTDEFINED INT=0
		DECLARE @FAILCOUNT INT=0
		DECLARE @TEMPSCANNEDPARTTYPE VARCHAR(15)
		DECLARE @TEMPRUNNINGPARTTYPE VARCHAR(15)
		DECLARE @TEMPOPERATIONTYPE VARCHAR(20),@LINETYPECODE VARCHAR(20)=''		
		DECLARE @OPERATIONSEQNO INT,@OPERATIONNAME VARCHAR(50)
		DECLARE @BARCODE_LENGTH AS INT
		DECLARE @INCORRECTMSG VARCHAR(200)
		DECLARE @POKAYOKEDATECODE VARCHAR(20)	
		DECLARE @EXECQUERY NVARCHAR(MAX),@LINKSERVERNAME VARCHAR(100), @LINKDB VARCHAR(100)
		DECLARE @PART_FIXTUREGROUPTYPE_COUNT INT=0
		DECLARE @FINALVIEWING_OPERATIONCODE VARCHAR(20)=NULL,@FINALVIEWING_MACHINECODE VARCHAR(20)=NULL
		DECLARE @DATECODETEMP VARCHAR(4)=NULL,@STMCPARTNO VARCHAR(30),@PARTTYPE VARCHAR(20)
		DECLARE @RETURNVALUE1 VARCHAR(100)
		DECLARE @RETURNINT1 INT
		DECLARE @ISSTMC BIT = 0
		DECLARE @LINECODE_STMC VARCHAR(30)
	    DECLARE @DATECODE_TEMP CHAR(4)	
		DECLARE @FAULTRESULTCOUNT INT
	    DECLARE @PASSFAILRESULTCOUNT INT
		DECLARE @PART_FIXTUREGROUPTYPE VARCHAR(30)
		DECLARE @CHANGEOVER_DATECODE CHAR(4) = NULL
		DECLARE @REWORK_DATECODE CHAR(4) = NULL
		DECLARE @REWORK_MODE VARCHAR(20) = NULL
		DECLARE @REWORK_CURRENT_PLANQTY INT = 0
		DECLARE @REWORK_ORDERNO VARCHAR(20) = ''
		DECLARE @REWORK_PRINT_QTY INT = 0
		DECLARE @PARTNO VARCHAR(60) = ''
		DECLARE @IsPartWiseRoutingApplicable INT = 0
		DECLARE @TallyChartWithPartFamily BIT = 0
		DECLARE @MESPARTNO VARCHAR(60) = ''

		DECLARE @ThroughputTime		VARCHAR(5)
		DECLARE @FromOperationCode	VARCHAR(10)
		DECLARE @ToOperationCode	VARCHAR(10)
		DECLARE @ThroughputPartKey	VARCHAR(10)
		DECLARE @FIRST_TIME			DATETIME
		
		SET @CHANGEOVER_DATECODE = @DATECODE
		DECLARE @PREVMACHINECODE VARCHAR(20)=NULL, @ALLOW2PARTSFLAG BIT, @ALLOW2PARTNO VARCHAR(60) = '', @ROUTINGRECIPEFLAG BIT, @MACHINEWISE_RUNNINGPART VARCHAR(60) = '',
		@PRODUCTIONORDERNO VARCHAR(40) = ''
		DECLARE @IS2PARTSFIFO BIT, @FV_OP_CODE VARCHAR(20) = '', @FIRSTSTATIONCODE VARCHAR(20) = '', @ISLINKSERVERCPRUPDATE BIT, @ASSY_PARTNO VARCHAR(12) = ''
		
		SELECT * into #TEMP_ASSY_RUNNINGPART FROM ASSY_RUNNINGPART(NOLOCK) 
		WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE 

		--SELECT @PRODUCTIONORDERNO = PRODUCTIONORDERNO FROM ASSY_RUNNINGPART (NOLOCK) 
		--WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE

		SELECT TOP 1 @PRODUCTIONORDERNO = PRODUCTIONORDERNO,@MESPARTNO=ASSY_PARTNO FROM #TEMP_ASSY_RUNNINGPART (NOLOCK)

		DECLARE @RETURN_LOT_NO VARCHAR(20)='' -- Added By Sachin 20170726
		DECLARE @RETURN_ECU_BARCODE VARCHAR(20)='' -- Added By Sachin  20170809
		DECLARE @IsRunning int = 0 --Added By Sachin 07March2020
		DECLARE @IsTallyChartApproved int = 1 --Added By Sachin 30June2020
		DECLARE @IsAllow2Part_ bit = 0 --Added By Sachin 1oct2020
		DECLARE @IsLabelPrintingEnabled bit = 0 --Added By Sachin 1oct2020
		DECLARE @ProdSTS_CD int = null -- Added By Sachin 210216
		
		DECLARE @StrIslabel_partwise varchar(2000)
		DECLARE @IntIslabel_partwise int
		DECLARE @Buffer_Count int=0,@FV_ROBO_BUFFER_COUNT int=0
		DECLARE @ParameterData Assy_TYPE_LineAssyParamData_Running

		DECLARE @RESULT VARCHAR(5)
		DECLARE @QR_CODE NVARCHAR(500)=''
		DECLARE @XmldataLK XML 
		DECLARE @TagData as table(
			TagName varchar(30),
			TagValue varchar(30)
		)

		SET NOCOUNT ON;
		
		--GET TESTING TIME OF PARTICULAR BARCODE
		DECLARE @PARTTESTINGTIME DATETIME = NULL	
		
		--Added By prerna for datcode change
		DECLARE	@Live_Datecode char(4) = @P_VALIDATE_DATECODE  --,@return_int int
		--exec Assy_proc_datecode @PROFITCENTERCODE,@Live_Datecode out,@return_int out

		DECLARE @Assy_LineAssyParamData_Running_Dtl as table 
		(
			[UID] [uniqueidentifier] NOT NULL
		)

		create table #Temp_RoboKey_bij (RoboKey nvarchar(2), LineCode nvarchar(20), MachineCode nvarchar(20), OperationCode nvarchar(20))

		Insert into #Temp_RoboKey_bij(RoboKey, LineCode)
		SELECT  ISNULL(ATTRB_VAL,'0'), @LINECODE
		from DBO.FN_GET_EXTENDED_ATTRIBUTE(@PROFITCENTERCODE,'LINE_ATTRB','ROBO_VISION_ON_OFF',@LINECODE,'','','','','')

		update a set a.MachineCode = b.MachineCode, a.OperationCode = b.OperationCode
		FROM #Temp_RoboKey_bij a inner join RoutingConfigDetails (nolock) b on a.LineCode = b.LineCode 
		and b.ProfitCenterCode = @PROFITCENTERCODE and b.KeyType='ROBO_STATION' and b.KeyValue='1' and b.STS_CD=0


		SELECT @FV_ROBO_BUFFER_COUNT= ISNULL(ATTRB_VAL,'0') from DBO.FN_GET_EXTENDED_ATTRIBUTE(@PROFITCENTERCODE,'LINE_ATTRB','FV_ROBO_BUFFER_COUNT',@LINECODE,'','','','','')
		
        IF @CONDITION='SCAN_OK'
		BEGIN
			 BEGIN TRAN
				BEGIN TRY

					--GET FINAL VIEWING OPERATION CODE FROM LINE CODE

					SELECT  @FINALVIEWING_OPERATIONCODE = @P_FINALVIEWING_OPERATIONCODE -- =DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE)
					SELECT @POKAYOKEDATECODE = @P_POKAYOKEDATECODE   -- =DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE','POKAYOKE','POKAYOKE_DATECODE',@PROFITCENTERCODE)

					--SELECT LINECODE,PROFITCENTERCODE,ALLOW2PARTS,IS2PARTSFIFO,LINETYPECODE,VALIDATE_DATECODE,
					--ISACTIVE,ISPOKAYOKEMANDATORY,ISMATFEEDREQUIRED into #TEMP_LINEMST
					--FROM LINEMST(NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE

					--SELECT * into #TEMP_ASSY_RUNNINGPART FROM ASSY_RUNNINGPART(NOLOCK) 
					--WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE 
					
					SELECT  RECIPE,OPERATIONSEQNO,POKA_YOKE_ALLOWED,TRACEABILITY,MACHINECODE,PROFITCENTERCODE,
					OPERATIONCODE,LINECODE,LABELPRINTING into #TEMP_ROUTINGCONFIGLINEWISE
					FROM ROUTINGCONFIGLINEWISE(NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE 
					AND LINECODE = @LINECODE 
					
					--select * into #TEMP_MACHINEMST from MACHINEMST WITH (NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE
											
					-- ADD/COMMENT BY RS ON 20170524 FOR SCANNING VALIDATION FAMILY BARCODE
					--SELECT @ALLOW2PARTSFLAG = ISNULL(ALLOW2PARTS,0),@IS2PARTSFIFO=ISNULL(IS2PARTSFIFO,0) 
					--FROM #TEMP_LINEMST WITH (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE

					SET @ALLOW2PARTSFLAG = @ALLOW2PARTS 
					SET @IS2PARTSFIFO = @P_IS2PARTSFIFO

					SELECT * into #TEMP_ASSY_LINEASSYSTATUS_RUNNING FROM ASSY_LINEASSYSTATUS_RUNNING(NOLOCK) WHERE 
					PROFITCENTERCODE =@PROFITCENTERCODE 
					AND LINECODE=@LINECODE 					
					AND BARCODE=@BARCODE 
					
					set @IsRunning=@@rowcount
			

					DECLARE @ASSY_RUNNINGPARTGLOBAL AS TABLE (
						[LINECODE] [VARCHAR](10) NULL,
						[DATECODE] [CHAR](4) NULL,
						[ASSY_PARTNO] [VARCHAR](60) NULL,
						[PRODUCTIONORDERNO] [VARCHAR](40) NULL,
						[CURRENTPLANNEDQTY] [NUMERIC](15, 3) NULL,
						[ASSY_MODE] [VARCHAR](20) NULL,
						[CREATEDDATE] [DATETIME] NULL,
						[CREATEDBY] [VARCHAR](20) NULL,
						[MODIFIEDON] [DATETIME] NULL,
						[MODIFIEDBY] [VARCHAR](20) NULL,
						[ISAUTHORIZED] [BIT] NULL,
						[ISTALLYSNOOZED] [BIT] NULL,
						[PRINTEDQTY] [INT] NULL,
						[BOOST_RATIO] [VARCHAR](20) NULL,
						[SERVO_PARTNO] [VARCHAR](20) NULL,
						[TMC_PARTNO] [VARCHAR](20) NULL,
						[PARTTYPE] [VARCHAR](20) NULL,
						[PROFITCENTERCODE] [VARCHAR](20) NULL,
						[CUSTOMERPARTNO] [VARCHAR](60) NULL
					)

--********************** START VALIDATE LINE CODE *******************			   
				IF(@ISSTMC = 1)
				BEGIN
					IF(ISNULL(@LINECODE_STMC, '') <> @LINECODE)
					BEGIN
								  SET @RETURNINT=1
									SET @RETURNVALUE='BARCODE_HAVING_DIFFERENT_LINE_CODE'						
									--UPDATE INCORRECT LABEL
									IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
										BEGIN
												EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
												,@BARCODE=@BARCODE,@HMIMESSAGE='BARCODE HAVING DIFFERENT LINE CODE'
										END
									COMMIT TRAN
									RETURN
					END
				END
				ELSE
				BEGIN
					--CHECK SCANNED BARCODE HAVING CORRECT LINE CODE OR NOT
					IF CHARINDEX(@LINECODE,@BARCODE)=0
					BEGIN
									if(@OPERATIONCODE=@FINALVIEWING_OPERATIONCODE)
									Begin
										if exists(select top 1 1 from #Temp_RoboKey_bij where RoboKey in('1'))
										Begin
											if exists(Select Top 1 1 from Assy_FinalViewing_RFID_Barcode_Mapping with(nolock) where ProfitCenterCode=@PROFITCENTERCODE and
											barcode=@barcode and linecode=@LINECODE and MachineCode=@MACHINECODE)
											Begin
												SET @RETURNINT=1
												SET @RETURNVALUE='Scanned Barcode Already Printed and Passed.'
												
											END
											else
											Begin
												SET @RETURNINT=1
												SET @RETURNVALUE='First Scan Mapped RFID.'
											End
											INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
											SELECT @PROFITCENTERCODE, 'ROBO_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()							
											COMMIT TRAN
											RETURN
										End
									END

									SET @RETURNINT=1
									SET @RETURNVALUE='BARCODE_HAVING_DIFFERENT_LINE_CODE'						
									--UPDATE INCORRECT LABEL
									IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
										BEGIN
												EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
												,@BARCODE=@BARCODE,@HMIMESSAGE='BARCODE HAVING DIFFERENT LINE CODE'
										END
									COMMIT TRAN
									RETURN

					END
				END
--********************** END VALIDATE LINE CODE *******************	
------------------------ROBO INSPECTION BUFFER CHECK--------------
					if(@OPERATIONCODE=@FINALVIEWING_OPERATIONCODE)
					Begin
						if exists(select top 1 1 from #Temp_RoboKey_bij where RoboKey in('1','2'))
						Begin
							Select * into #temp_ASSY_SCAN_OK_ROBO from ASSY_SCAN_OK_ROBO with(nolock) where ProfitCenterCode=@ProfitCenterCode 
							and LineCode=@linecode and MachineCode=@MACHINECODE
					    
							If exists(Select top 1 1 from #temp_ASSY_SCAN_OK_ROBO with(nolock) where barcode=@barcode and ProfitCenterCode=@ProfitCenterCode 
							and LineCode=@linecode and MachineCode=@MACHINECODE)
							Begin
								SELECT @RETURNINT=1, @RETURNVALUE='Barcode_Already_in_Scanned_Buffer.'
								--UPDATE INCORRECT LABEL
											
								INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
								SELECT @PROFITCENTERCODE, 'ROBO_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
								COMMIT TRAN
								RETURN
							end
						end
					END

					IF EXISTS (SELECT 1 FROM #Temp_RoboKey_bij WHERE RoboKey in('3') AND MachineCode=@MACHINECODE)
					BEGIN
						IF EXISTS (SELECT 1 FROM Assy_Scan_OK_ROBO WITH (NOLOCK) 
						WHERE Barcode=@BARCODE AND isnull(isScan,0)=1 AND isnull(isProcess,0)=0
						AND ProfitCenterCode=@PROFITCENTERCODE AND MachineCode=@MACHINECODE)
						BEGIN
							--other than below update there is no TD_Scan_OK_ROBO update for any scan not ok case
							UPDATE A SET A.IsScan=1 FROM TD_Scan_OK_ROBO A WITH (NOLOCK) WHERE Barcode=@Assy_str AND MachineCode=@MACHINECODE	--if want to scan again
							--UPDATE A SET A.IsScan=2 FROM TD_Scan_OK_ROBO A WITH (NOLOCK) WHERE Barcode=@Assy_str AND MachineCode=@MACHINECODE	--if no scan_ok ack for already scan (it wont come again as updated)
							--do nthin																											--if no scan_ok no ack

							SELECT @RETURNINT=1, @RETURNVALUE='Barcode_Already_in_Scanned_Buffer.'
								
							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ROBO_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							COMMIT TRAN
							RETURN
						END

						SELECT @Buffer_Count=COUNT(*) FROM Assy_Scan_OK_ROBO WITH (NOLOCK) 
						WHERE ProfitCenterCode=@PROFITCENTERCODE and MachineCode=@MACHINECODE and isnull(isScan,0)=1 and isnull(isProcess,0)=0

						IF(@Buffer_Count > @FV_ROBO_BUFFER_COUNT)
						BEGIN
							SET @RETURNINT=1
							SET @RETURNVALUE='SCAN_BUFFER_REACHED_FOR_ROBO_INSPECTION'

							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ROBO_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
							COMMIT TRAN
							RETURN
						END
					END
					
					IF CHARINDEX(':',@BARCODE) = 0 AND ISNULL(@BARCODE,'') <> '' AND CHARINDEX(@POKAYOKEDATECODE,@BARCODE) = 0
					BEGIN
						
						IF ISNULL(@ALLOW2PARTSFLAG,0) = 1
						BEGIN

							SELECT @ALLOW2PARTNO = PARTNO FROM DBO.ASSY_FN_GET_BARCODEPARTS_FROM_BARCODE(@PROFITCENTERCODE,@LINECODE,@BARCODE)
							
							IF ISNULL(@ALLOW2PARTNO,'') != ''
							BEGIN
								
								SELECT @REWORK_DATECODE = DATECODE, @REWORK_MODE = RTRIM(ASSY_MODE), @REWORK_CURRENT_PLANQTY = CURRENTPLANNEDQTY, @REWORK_ORDERNO = PRODUCTIONORDERNO
								FROM #TEMP_ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND ASSY_PARTNO = @ALLOW2PARTNO
								
								INSERT INTO @ASSY_RUNNINGPARTGLOBAL([LINECODE],[DATECODE],[ASSY_PARTNO],[PRODUCTIONORDERNO],[CURRENTPLANNEDQTY],[ASSY_MODE],[CREATEDDATE],[CREATEDBY],[MODIFIEDON],[MODIFIEDBY],[ISAUTHORIZED],[ISTALLYSNOOZED],
								[PRINTEDQTY],[BOOST_RATIO],[SERVO_PARTNO],[TMC_PARTNO],[PARTTYPE],[PROFITCENTERCODE],[CUSTOMERPARTNO])
								SELECT [LINECODE],[DATECODE],[ASSY_PARTNO],[PRODUCTIONORDERNO],[CURRENTPLANNEDQTY],[ASSY_MODE],
								[CREATEDDATE],[CREATEDBY],[MODIFIEDON],[MODIFIEDBY],[ISAUTHORIZED],[ISTALLYSNOOZED],[PRINTEDQTY],
								[BOOST_RATIO],[SERVO_PARTNO],[TMC_PARTNO],[PARTTYPE],[PROFITCENTERCODE],[CUSTOMERPARTNO]
							    FROM #TEMP_ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND ASSY_PARTNO = @ALLOW2PARTNO

								IF ISNULL(@REWORK_DATECODE,'') = ''
									SELECT TOP 1 @REWORK_DATECODE = DATECODE, @REWORK_MODE = RTRIM(ASSY_MODE), @REWORK_CURRENT_PLANQTY = CURRENTPLANNEDQTY, @REWORK_ORDERNO = PRODUCTIONORDERNO
										FROM ASSY_RUNNINGPARTFAMILY WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND ASSY_PARTNO = @ALLOW2PARTNO
								
								INSERT INTO @ASSY_RUNNINGPARTGLOBAL ([LINECODE],[DATECODE],[ASSY_PARTNO],[PRODUCTIONORDERNO],[CURRENTPLANNEDQTY],[ASSY_MODE],[CREATEDDATE],[CREATEDBY],[MODIFIEDON],[MODIFIEDBY],[ISAUTHORIZED],[ISTALLYSNOOZED],[PRINTEDQTY],[BOOST_RATIO],
								[SERVO_PARTNO],[TMC_PARTNO],[PARTTYPE],[PROFITCENTERCODE],[CUSTOMERPARTNO])
								SELECT TOP 1 [LINECODE],[DATECODE],[ASSY_PARTNO],[PRODUCTIONORDERNO],[CURRENTPLANNEDQTY],[ASSY_MODE],
								[CREATEDDATE],[CREATEDBY],[MODIFIEDON],[MODIFIEDBY],[ISAUTHORIZED],[ISTALLYSNOOZED],[PRINTEDQTY],
								[BOOST_RATIO],[SERVO_PARTNO],[TMC_PARTNO],[PARTTYPE],[PROFITCENTERCODE],[CUSTOMERPARTNO]
									FROM ASSY_RUNNINGPARTFAMILY WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND ASSY_PARTNO = @ALLOW2PARTNO

								IF ISNULL(@REWORK_DATECODE,'') = ''
								BEGIN
									SELECT @RETURNINT=1, @RETURNVALUE='PART/GROUP PART HAS NOT BEEN SELECTED AT SET PARAMETER SCREEN.'				
									--UPDATE INCORRECT LABEL
										IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
										BEGIN
											EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
											,@BARCODE=@BARCODE,@HMIMESSAGE='PART NOT SELECTED IN SET PARAMETER'
										END
									COMMIT TRAN
									RETURN
								END

								--RECIPE VALIDATION STATION WISE FOR JHAGADIA 20170526
								
								--SELECT @ROUTINGRECIPEFLAG = RECIPE,@OPERATIONSEQNO=OPERATIONSEQNO 
								--FROM #TEMP_ROUTINGCONFIGLINEWISE WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE 
								--AND LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE=@MACHINECODE
								
								SET @ROUTINGRECIPEFLAG = @P_RECIPE
								SET @OPERATIONSEQNO = @P_OPERATIONSEQNO

								print '@IS2PARTSFIFO ' + convert(varchar,@IS2PARTSFIFO) 
									IF @IS2PARTSFIFO=1
										BEGIN											
												IF(@OPERATIONSEQNO-1)<>1
												BEGIN
													   --EXEC ASSY_PROC_GET_PREVIOUS_MACHINECODE @LINECODE=@LINECODE ,@MACHINECODE=@MACHINECODE,@PARTNUMBER=@ALLOW2PARTNO
												    --   ,@PREVMACHINECODE=@PREVMACHINECODE OUTPUT											
											 			
														SET @PREVMACHINECODE = @P_PREVMACHINECODE

														DECLARE @STATUSRUNNINGTMP AS TABLE
														(												
														 PARTNO VARCHAR(60)
														)
														INSERT INTO @STATUSRUNNINGTMP(PARTNO)												
														SELECT  PARTNO FROM ASSY_LINEASSYSTATUS_RUNNING WITH(NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE 
														AND LINECODE = @LINECODE 
														AND MACHINECODE = @PREVMACHINECODE AND ISNULL(STATUS,'')='PS'
														ORDER BY RESULTTIMESTAMP
												
														DECLARE @STATUSRUNNING AS TABLE
														(
														 ID INT IDENTITY(1,1),
														 PARTNO VARCHAR(60)
														)
														INSERT INTO @STATUSRUNNING(PARTNO)
														SELECT DISTINCT PARTNO FROM @STATUSRUNNINGTMP

														IF EXISTS
														(
														    SELECT 1 FROM @STATUSRUNNING WHERE ID=2 AND PARTNO=@ALLOW2PARTNO
														)
														BEGIN														    
																DECLARE @OLDPARTS AS TABLE
																(
																	BARCODE VARCHAR(100),
																	PARTNO VARCHAR(60),
																	MACHINECODE VARCHAR(10)
																)
														
																INSERT INTO @OLDPARTS(BARCODE,PARTNO,MACHINECODE)
																SELECT BARCODE,PARTNO,MACHINECODE FROM DBO.ASSY_LINEASSYSTATUS_RUNNING WITH(NOLOCK) 
																WHERE MACHINECODE=@PREVMACHINECODE
																AND ISNULL(STATUS,'')='PS'
																AND PARTNO=(SELECT PARTNO FROM @STATUSRUNNING WHERE ID=1)															

																MERGE @OLDPARTS OP
																USING ASSY_LINEASSYSTATUS_RUNNING ASSY ON									
																OP.BARCODE = ASSY.BARCODE
																AND OP.PARTNO=ASSY.PARTNO
																AND ISNULL(ASSY.STATUS,'')<>''
																AND ASSY.MACHINECODE=@MACHINECODE
																WHEN MATCHED THEN   
																	DELETE ;

																	IF EXISTS( SELECT 1 FROM @OLDPARTS)
																	BEGIN								
																			SELECT @RETURNINT=1, @RETURNVALUE='FIRST TEST OLD PENDING PARTS.'
																			--UPDATE INCORRECT LABEL
																			IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
																			BEGIN
																				EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
																				,@BARCODE=@BARCODE,@HMIMESSAGE='TEST PENDING PARTS'
																			END
																			COMMIT TRAN
																			RETURN
																	END
														END															
														
										 END
								   END								
								
								IF ISNULL(@ROUTINGRECIPEFLAG,0) = 1
								BEGIN
										SELECT TOP 1 @MACHINEWISE_RUNNINGPART = PARTNO FROM ASSY_MACHINEWISE_RUNNINGPART WITH (NOLOCK) 
										WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
										IF (ISNULL(@MACHINEWISE_RUNNINGPART,'') != @ALLOW2PARTNO)
										BEGIN
												SELECT @RETURNINT=1, @RETURNVALUE='HMI PART AND SCANNED PART ARE MISMATCHED.'
												--UPDATE INCORRECT LABEL
												IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
												BEGIN
													EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
													,@BARCODE=@BARCODE,@HMIMESSAGE='HMI PART AND SCANNED PART ARE MISMATCHED'
												END
												COMMIT TRAN
												RETURN
										END
								END							
								
							END
							ELSE
							BEGIN
								SELECT @RETURNINT=1, @RETURNVALUE='SCAN ONLY VALID BARCODE/RFID'
								--PRINT 'BARCODE/RFID IS NOT PRINTED/GENERATED.'
								--UPDATE INCORRECT LABEL
								IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
								BEGIN
									EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
									,@BARCODE=@BARCODE,@HMIMESSAGE='SCAN ONLY VALID BARCODE/RFID'
								END
								COMMIT TRAN
								RETURN
								
							END
						END
						ELSE
						BEGIN
							SELECT @REWORK_DATECODE = DATECODE, @REWORK_MODE = RTRIM(ASSY_MODE), @REWORK_CURRENT_PLANQTY = CURRENTPLANNEDQTY,
								@REWORK_ORDERNO = PRODUCTIONORDERNO
							FROM #TEMP_ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

							INSERT INTO @ASSY_RUNNINGPARTGLOBAL ([LINECODE],[DATECODE],[ASSY_PARTNO],[PRODUCTIONORDERNO],[CURRENTPLANNEDQTY],[ASSY_MODE],[CREATEDDATE],[CREATEDBY],[MODIFIEDON],[MODIFIEDBY],[ISAUTHORIZED],[ISTALLYSNOOZED],[PRINTEDQTY],[BOOST_RATIO],
							[SERVO_PARTNO],[TMC_PARTNO],[PARTTYPE],[PROFITCENTERCODE],[CUSTOMERPARTNO])
							SELECT [LINECODE],[DATECODE],[ASSY_PARTNO],[PRODUCTIONORDERNO],[CURRENTPLANNEDQTY],[ASSY_MODE],[CREATEDDATE],
							[CREATEDBY],[MODIFIEDON],[MODIFIEDBY],[ISAUTHORIZED],[ISTALLYSNOOZED],[PRINTEDQTY],[BOOST_RATIO],[SERVO_PARTNO],[TMC_PARTNO],[PARTTYPE],
							[PROFITCENTERCODE],[CUSTOMERPARTNO]
								FROM #TEMP_ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
						END
					END
					ELSE
					BEGIN
						
						print '---------B------S---------'

						SELECT @REWORK_DATECODE = DATECODE, @REWORK_MODE = RTRIM(ASSY_MODE), @REWORK_CURRENT_PLANQTY = CURRENTPLANNEDQTY,
								@REWORK_ORDERNO = PRODUCTIONORDERNO
							FROM #TEMP_ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

						INSERT INTO @ASSY_RUNNINGPARTGLOBAL ([LINECODE],[DATECODE],[ASSY_PARTNO],[PRODUCTIONORDERNO],[CURRENTPLANNEDQTY],[ASSY_MODE],[CREATEDDATE],[CREATEDBY],[MODIFIEDON],[MODIFIEDBY],[ISAUTHORIZED],[ISTALLYSNOOZED],[PRINTEDQTY],[BOOST_RATIO],
						[SERVO_PARTNO],[TMC_PARTNO],[PARTTYPE],[PROFITCENTERCODE],[CUSTOMERPARTNO])
							SELECT [LINECODE],[DATECODE],[ASSY_PARTNO],[PRODUCTIONORDERNO],[CURRENTPLANNEDQTY],[ASSY_MODE],[CREATEDDATE],
							[CREATEDBY],[MODIFIEDON],[MODIFIEDBY],[ISAUTHORIZED],[ISTALLYSNOOZED],[PRINTEDQTY],[BOOST_RATIO],
							[SERVO_PARTNO],[TMC_PARTNO],[PARTTYPE],[PROFITCENTERCODE],[CUSTOMERPARTNO]
								FROM #TEMP_ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
					END
					
					SELECT @REWORK_CURRENT_PLANQTY = CURRENTPLANNEDQTY
						FROM ASSY_BARCODE_PRINTED_COUNTER WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
					--SELECT * FROM @ASSY_RUNNINGPARTGLOBAL
					   IF CHARINDEX(':',@BARCODE) <> 0 AND ISNULL(@BARCODE,'') <> '' 
					   BEGIN
							SET @ISSTMC = 1
							SELECT DISTINCT @LINECODE_STMC =  ISNULL(LINECODE, '') , @DATECODE_TEMP = ISNULL(DATECODE, '')  FROM #TEMP_ASSY_LINEASSYSTATUS_RUNNING(NOLOCK) 
							WHERE  PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE=@LINECODE AND MACHINECODE =@MACHINECODE  AND BARCODE = @BARCODE  
							SET @DATECODE = @DATECODE_TEMP
							IF(@LINECODE_STMC)<>''
							BEGIN
								  SELECT DISTINCT @PARTNUMBER=ISNULL(STMC_PART_NO, ''),@DATECODE=DATECODE FROM DBO.ASSY_COUPLINGDETAILS(NOLOCK) WHERE FG_BARCODE = @BARCODE AND LINECODE = @LINECODE
							END
							ELSE
							  BEGIN
									 SELECT DISTINCT @PARTNUMBER=ISNULL(STMC_PART_NO, ''),@LINECODE_STMC=LINECODE,@DATECODE=DATECODE FROM DBO.ASSY_COUPLINGDETAILS(NOLOCK) WHERE FG_BARCODE = @BARCODE 
									 AND LINECODE = @LINECODE AND PROFITCENTRECODE=@PROFITCENTERCODE
							  END

							  IF ISNULL(@PARTNUMBER,'') =''
							  BEGIN
									SET @RETURNINT=1
									SET @RETURNVALUE='SCAN_ONLY_VALID_BARCODE'						
									--UPDATE INCORRECT LABEL
									IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
									BEGIN
