						--			,@BARCODE=@BARCODE,@HMIMESSAGE='SCAN ONLY VALID BARCODE/RFID'
						--		END
						--		COMMIT TRAN
						--		RETURN
						--END
						IF CHARINDEX(@POKAYOKEDATECODE,@BARCODE)>0
				        BEGIN
								 					  
								  IF NOT EXISTS
								  (
									SELECT 1 FROM DBO.ASSY_POKAYOKE(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND  BARCODE=@BARCODE
								  )
								  BEGIN
											  SET @RETURNINT=1
