												,@BARCODE=@BARCODE,@HMIMESSAGE='THIS POKA YOKE IS NOT DEFINED IN POKA YOKE MASTER'
											END		
											COMMIT TRAN
								            RETURN							
								 END
								 --GET POKA YOKE  PART NO AND DATE CODE						  
								  SELECT @PARTNUMBER=PARTNUMBER,@DATECODE=DATECODE FROM DBO.ASSY_POKAYOKE(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE 
								  AND LINECODE=@LINECODE AND  BARCODE=@BARCODE
					 END
