--*************** START CHECK DUPLICATE_LABEL GET TESTING TIME OF PARTICULAR BARCODE ********************
									
				--IF @OPERATIONCODE = @FINALVIEWING_OPERATIONCODE
				--BEGIN
				    -- 2%%%
					
					SELECT ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,[Status],FailCount,Datecode,PartNo,ScanTimestamp,ResultTimestamp,Active,
					UserID,IsTallyChartApproved,Transaction_Number,isConfirmed,Kanban_Id,ERP_Conf_Timestamp,IsReworkPart,Is_Manual,IsPendingPart,ProductionOrderNo,
					PROD_LOT_NO,Category,IsSyncDone,SyncTimeStamp into #TEMP_ASSY_LINEASSYSTATUS FROM ASSY_LINEASSYSTATUS (NOLOCK) WHERE 1=2

					SELECT @PARTTESTINGTIME=RESULTTIMESTAMP FROM #TEMP_ASSY_LINEASSYSTATUS_RUNNING 
					(NOLOCK) WHERE MACHINECODE=@MACHINECODE 
					AND BARCODE=@BARCODE AND  ISNULL(STATUS,'')='PS'
						
					IF ( @PARTTESTINGTIME IS NULL AND @IsRunning=0)
					BEGIN
					-- 2%%%
						insert into #TEMP_ASSY_LINEASSYSTATUS(
						ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,[Status],FailCount,Datecode,PartNo,ScanTimestamp,ResultTimestamp,Active,
						UserID,IsTallyChartApproved,Transaction_Number,isConfirmed,Kanban_Id,ERP_Conf_Timestamp,IsReworkPart,Is_Manual,IsPendingPart,ProductionOrderNo,
						PROD_LOT_NO,Category,IsSyncDone,SyncTimeStamp
						)
						SELECT ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,[Status],FailCount,Datecode,PartNo,ScanTimestamp,ResultTimestamp,Active,
						UserID,IsTallyChartApproved,Transaction_Number,isConfirmed,Kanban_Id,ERP_Conf_Timestamp,IsReworkPart,Is_Manual,IsPendingPart,ProductionOrderNo,
						PROD_LOT_NO,Category,IsSyncDone,SyncTimeStamp
						FROM ASSY_LINEASSYSTATUS (NOLOCK) WHERE 
						PROFITCENTERCODE =@PROFITCENTERCODE 
						AND LINECODE=@LINECODE 						
						AND BARCODE=@BARCODE

						SELECT @PARTTESTINGTIME=RESULTTIMESTAMP FROM #TEMP_ASSY_LINEASSYSTATUS
						(NOLOCK) WHERE 
						MACHINECODE=@MACHINECODE 
						AND BARCODE=@BARCODE AND  ISNULL(STATUS,'')='PS'
					END	

					IF(@PARTTESTINGTIME IS NOT NULL)
					BEGIN							
						--UPDATE ASSY_DUPLICATELABEL  TABLE
						IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
						BEGIN
							IF  NOT EXISTS
							( 
								SELECT 1 FROM DBO.ASSY_SCAN_OK(NOLOCK) WHERE LINECODE =@LINECODE AND OPERATIONCODE=@OPERATIONCODE AND ISNULL(ISCYCLESTARTED,0)=1
							)
							BEGIN
								IF EXISTS
								(
									SELECT DISTINCT 1 FROM DBO.ASSY_DUPLICATELABEL (NOLOCK) WHERE LINECODE=@LINECODE AND    
									OPERATIONCODE=@OPERATIONCODE 
								)
								BEGIN
									UPDATE ASSY_DUPLICATELABEL SET ISDUPLICATE=1, BARCODE=@BARCODE  WHERE LINECODE=@LINECODE AND 
									OPERATIONCODE=@OPERATIONCODE
									--RESET SCAN OK
									UPDATE ASSY_SCAN_OK SET ISSCAN=0  WHERE LINECODE=@LINECODE AND 
									OPERATIONCODE=@OPERATIONCODE 													   
									--RESET   INCORRECT LABEL
									UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE='' ,ISINCORRECT=0 WHERE LINECODE=@LINECODE AND 
									OPERATIONCODE=@OPERATIONCODE 

								END
								ELSE
								BEGIN
									INSERT INTO ASSY_DUPLICATELABEL(LINECODE,OPERATIONCODE,STATIONCODE,BARCODE,ISDUPLICATE)
									SELECT @LINECODE,@OPERATIONCODE,@STATIONCODE ,@BARCODE ,1
									--RESET SCAN OK
									UPDATE ASSY_SCAN_OK SET ISSCAN=0  WHERE LINECODE=@LINECODE AND 
									OPERATIONCODE=@OPERATIONCODE 													   
									--RESET   INCORRECT LABEL
									UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE='' ,ISINCORRECT=0 WHERE LINECODE=@LINECODE AND 
									OPERATIONCODE=@OPERATIONCODE 
								END
							END												
						END
						print '-------------A----------------'																
						SET @RETURNINT = 1
						--SET @RETURNVALUE = 'DUPLICATE_LABEL^'+CONVERT(VARCHAR(100), @PARTTESTINGTIME)
						SET @RETURNVALUE = 'DUPLICATE_LABEL^'+FORMAT(getdate(), 'ddMMMyyyy h:mmtt')
						COMMIT TRAN
						GOTO SCAN_NOT_OK_ROBO
						RETURN
					END

--*************** END CHECK DUPLICATE_LABEL GET TESTING TIME OF PARTICULAR BARCODE ********************
				

				-- CHECK IF POKA YOKA MANDATORY
					DECLARE @ISPOKAYOKECOMPLETED BIT
					print '@P_ISPOKAYOKEMANDATORY ' + convert(varchar,@P_ISPOKAYOKEMANDATORY)
					--IF (SELECT ISNULL(ISPOKAYOKEMANDATORY,0) FROM #TEMP_LINEMST(NOLOCK) WHERE LINECODE=@LINECODE AND PROFITCENTERCODE=@PROFITCENTERCODE)=1
					IF (@P_ISPOKAYOKEMANDATORY=1)
					BEGIN
							 -- IF  EXISTS
							 -- (
								--	SELECT DISTINCT 1 FROM #TEMP_ROUTINGCONFIGLINEWISE(NOLOCK)L 						
								--	WHERE L.LINECODE =@LINECODE
								--	AND ISNULL(L.POKA_YOKE_ALLOWED,0) =1 						
								--	AND ISNULL(L.TRACEABILITY,0) =1 
								--	AND L.MACHINECODE=@MACHINECODE
								--	AND L.PROFITCENTERCODE=@PROFITCENTERCODE  
					
							 --)
							 print '@@P_POKA_YOKE_ALLOWED ' + convert(varchar,@P_POKA_YOKE_ALLOWED)
							 IF(@P_POKA_YOKE_ALLOWED = 1)
							 BEGIN																					
																
												IF NOT EXISTS
												(	
													SELECT ISNULL(ISPOKAYOKECOMPLETED,0) FROM DBO.ASSY_SCAN_OK(NOLOCK) WHERE LINECODE=@LINECODE
													AND OPERATIONCODE=@OPERATIONCODE AND MACHINECODE=@MACHINECODE
												)
												BEGIN
														IF CHARINDEX(@POKAYOKEDATECODE,@BARCODE)=0						
															BEGIN
																SET @RETURNINT=1
																SET @RETURNVALUE='POKAYOKE_NOT_DONE'
																IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
																BEGIN
																		EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
																		,@BARCODE=@BARCODE,@HMIMESSAGE='POKA YOKE HAS NOT BEEN DONE'
																END	
																COMMIT TRAN
																RETURN
															END
												END	
												SELECT @ISPOKAYOKECOMPLETED=ISNULL(ISPOKAYOKECOMPLETED,0) FROM DBO.ASSY_SCAN_OK(NOLOCK) WHERE LINECODE=@LINECODE 
												AND OPERATIONCODE=@OPERATIONCODE AND MACHINECODE=@MACHINECODE
												 
												 IF CHARINDEX(@POKAYOKEDATECODE,@BARCODE)<>0
												 BEGIN
														IF(@ISPOKAYOKECOMPLETED=1 AND DBO.ASSY_FN_ISPARTTESTEDATFV_FORPOKAYOKE(@PROFITCENTERCODE,@LINECODE,@MACHINECODE,@OPERATIONCODE)=0 )						
															BEGIN
																SET @RETURNINT=1
																SET @RETURNVALUE='POKAYOKE_ALREADY_DONE'
																IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
																BEGIN
																		EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
																		,@BARCODE=@BARCODE,@HMIMESSAGE='POKA YOKE HAS BEEN ALREADY DONE'
																END	
																COMMIT TRAN
																RETURN
															END
												END

												IF(@ISPOKAYOKECOMPLETED=0 AND CHARINDEX(@POKAYOKEDATECODE,@BARCODE)=0)							
													BEGIN
														SET @RETURNINT=1
														SET @RETURNVALUE='POKAYOKE_NOT_DONE'
														IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
														BEGIN
																EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
																,@BARCODE=@BARCODE,@HMIMESSAGE='POKA YOKE HAS NOT BEEN DONE'
														END	
														COMMIT TRAN
														RETURN
													END
							END

					END

