					--Endded By Sachin 04June2020

						--TORQUE
					--------------------------------------------------------------------
					--IF EXISTS(SELECT TOP 1 1 FROM RoutingConfigDetails(NOLOCK) WHERE LineCode=@LINECODE AND KeyType='IsTorqueCapturingFromKepServer' and KeyValue=1)
					IF(@P_IsTorqueCapturingFromKepServer = 1)
					BEGIN

						;WITH TEMP_BLEED_TORQUE
					AS
					(
						SELECT A.UID,T.TagId,B.Torque,B.Barcode,
						ROW_NUMBER() OVER (Partition by B.Barcode order by B.[Timestamp] desc) AS Ran
						FROM Assy_LineAssyParamData_Running(nolock) A 
						INNER JOIN Bleed_Torque B with(nolock) on A.Barcode=B.Barcode 
						INNER JOIN TagMst T ON T.TagName='TORQUE' AND T.ProfitCenterCode=A.ProfitCenterCode
						LEFT JOIN Assy_LineAssyParamData_Running_DTL D ON A.UID=D.UID AND T.TagId=D.TagId
						WHERE A.OperationCode='OC4S' AND ISNULL(D.TagId,'')='' AND ISNULL(B.TIMESTAMP,'')<>'' AND A.Result='PS'
					)
					SELECT * 
					INTO #TEMP_BLEED_TORQUE
					FROM TEMP_BLEED_TORQUE WHERE Ran=1

						if exists(select top 1 1 from #TEMP_Bleed_Torque)
						begin
				
						INSERT INTO Assy_LineAssyParamData_Running_Dtl(UID,TagId,Value)
						select UID,TagId,Torque from #TEMP_Bleed_Torque
						end

						--------------------------------------------------------------------
						--TORQUE_ANGLE

						;WITH TORQUE_ANGLE
					AS
					(
						SELECT A.UID,T.TagId,B.ANGLE,B.Barcode,
						ROW_NUMBER() OVER (Partition by B.Barcode order by B.[Timestamp] desc) AS Ran
						FROM Assy_LineAssyParamData_Running(nolock) A 
						INNER JOIN Bleed_Torque B with(nolock) on A.Barcode=B.Barcode 
						INNER JOIN TagMst T ON T.TagName='TORQUE_ANGLE' AND T.ProfitCenterCode=A.ProfitCenterCode
						LEFT JOIN Assy_LineAssyParamData_Running_DTL D ON A.UID=D.UID AND T.TagId=D.TagId
						WHERE A.OperationCode='OC4S' AND ISNULL(D.TagId,'')='' AND ISNULL(B.TIMESTAMP,'')<>'' AND A.Result='PS'
					)
					SELECT * 
					INTO #TEMP_TORQUE_ANGLE
					FROM TORQUE_ANGLE WHERE Ran=1

						if exists(select top 1 1 from #TEMP_TORQUE_ANGLE)
						begin
				
						INSERT INTO Assy_LineAssyParamData_Running_Dtl(UID,TagId,Value)
						select UID,TagId,ANGLE from #TEMP_TORQUE_ANGLE
					end

						--------------------------------------------------------------------
						--RH_TORQUE

						;WITH RH_TORQUE
					AS
					(
						SELECT A.UID,T.TagId,B.RH_Torque,B.Barcode, ROW_NUMBER() OVER (Partition by B.Barcode order by B.[Timestamp] desc) AS Ran
						FROM Assy_LineAssyParamData_Running(nolock) A 
						INNER JOIN PIN_BOLT_TORQUE B with(nolock) on A.Barcode=B.Barcode 
						INNER JOIN TagMst T ON T.TagName='RH_TORQUE' AND T.ProfitCenterCode=A.ProfitCenterCode
						LEFT JOIN Assy_LineAssyParamData_Running_DTL D ON A.UID=D.UID AND T.TagId=D.TagId
						WHERE A.OperationCode='OCCP' AND ISNULL(D.TagId,'')='' AND ISNULL(B.RH_Torque,'')<>'' AND ISNULL(B.TIMESTAMP,'')<>'' --AND A.Result='PS'
					)
					SELECT * 
					INTO #TEMP_PIN_RH_TORQUE
					FROM RH_TORQUE WHERE Ran=1

						if exists(select top 1 1 from #TEMP_PIN_RH_TORQUE)
						begin
				
						INSERT INTO Assy_LineAssyParamData_Running_Dtl(UID,TagId,Value)
						select UID,TagId,RH_Torque from #TEMP_PIN_RH_TORQUE
					end

						--------------------------------------------------------------------
						--RH_TORQUE_ANGLE

						;WITH RH_TORQUE_ANGLE
					AS
					(
						SELECT A.UID,T.TagId,B.RH_Angle,B.Barcode, ROW_NUMBER() OVER (Partition by B.Barcode order by B.[Timestamp] desc) AS Ran
						FROM Assy_LineAssyParamData_Running(nolock) A 
						INNER JOIN PIN_BOLT_TORQUE B with(nolock) on A.Barcode=B.Barcode 
						INNER JOIN TagMst T ON T.TagName='RH_TORQUE_ANGLE' AND T.ProfitCenterCode=A.ProfitCenterCode
						LEFT JOIN Assy_LineAssyParamData_Running_DTL D ON A.UID=D.UID AND T.TagId=D.TagId
						WHERE A.OperationCode='OCCP' AND ISNULL(D.TagId,'')='' AND ISNULL(B.RH_Angle,'')<>'' AND ISNULL(B.TIMESTAMP,'')<>'' --AND A.Result='PS'
					)
					SELECT * 
					INTO #TEMP_PIN_RH_TORQUE_ANGLE
					FROM RH_TORQUE_ANGLE WHERE Ran=1

						if exists(select top 1 1 from #TEMP_PIN_RH_TORQUE_ANGLE)
						begin
				
						INSERT INTO Assy_LineAssyParamData_Running_Dtl(UID,TagId,Value)
						select UID,TagId,RH_Angle from #TEMP_PIN_RH_TORQUE_ANGLE
					end

						--------------------------------------------------------------------
						--LH_TORQUE_ANGLE

						;WITH LH_TORQUE_ANGLE
					AS
					(
						SELECT A.UID,T.TagId,B.LH_Angle,B.Barcode, ROW_NUMBER() OVER (Partition by B.Barcode order by B.[Timestamp] desc) AS Ran
						FROM Assy_LineAssyParamData_Running(nolock) A 
						INNER JOIN PIN_BOLT_TORQUE B with(nolock) on A.Barcode=B.Barcode 
						INNER JOIN TagMst T ON T.TagName='LH_TORQUE_ANGLE' AND T.ProfitCenterCode=A.ProfitCenterCode
						LEFT JOIN Assy_LineAssyParamData_Running_DTL D ON A.UID=D.UID AND T.TagId=D.TagId
						WHERE A.OperationCode='OCCP' AND ISNULL(D.TagId,'')='' AND ISNULL(B.LH_Angle,'')<>'' AND ISNULL(B.TIMESTAMP,'')<>'' --AND A.Result='PS'
					)
					SELECT * INTO #TEMP_PIN_LH_TORQUE_ANGLE
					FROM LH_TORQUE_ANGLE WHERE Ran=1
						if exists(select top 1 1 from #TEMP_PIN_LH_TORQUE_ANGLE)
						begin
				
						INSERT INTO Assy_LineAssyParamData_Running_Dtl(UID,TagId,Value)
						select UID,TagId,LH_Angle from #TEMP_PIN_LH_TORQUE_ANGLE
					end
						--------------------------------------------------------------------
						--LH_TORQUE

						;WITH LH_TORQUE
					AS
					(
						SELECT A.UID,T.TagId,B.LH_Torque,B.Barcode, ROW_NUMBER() OVER (Partition by B.Barcode order by B.[Timestamp] desc) AS Ran
						FROM Assy_LineAssyParamData_Running(nolock) A 
						INNER JOIN PIN_BOLT_TORQUE B with(nolock) on A.Barcode=B.Barcode 
						INNER JOIN TagMst T ON T.TagName='LH_TORQUE' AND T.ProfitCenterCode=A.ProfitCenterCode
						LEFT JOIN Assy_LineAssyParamData_Running_DTL D ON A.UID=D.UID AND T.TagId=D.TagId
						WHERE A.OperationCode='OCCP'  AND ISNULL(B.LH_Torque,'')<>'' AND ISNULL(B.TIMESTAMP,'')<>'' --AND A.Result='PS'
						AND ISNULL(D.TagId,'')=''
					)
					SELECT * INTO #TEMP_PIN_LH_TORQUE
					FROM LH_TORQUE WHERE Ran=1

						if exists(select top 1 1 from #TEMP_PIN_LH_TORQUE)
						begin
				
						INSERT INTO Assy_LineAssyParamData_Running_Dtl(UID,TagId,Value)
						select UID,TagId,LH_Torque from #TEMP_PIN_LH_TORQUE
					end

					IF(@OPERATIONCODE =@FINALVIEWING_OPERATIONCODE)
					BEGIN
					DECLARE @COUNT INT=0
						SELECT @Count=COUNT(*) FROM Assy_LineAssyParamData_Running_Dtl(NOLOCK) D
						INNER JOIN Assy_LineAssyParamData_Running(NOLOCK) H ON H.UID=D.UID
						INNER JOIN TagMst(nolock) T ON T.TagId=D.TagId AND T.ProfitCenterCode=H.ProfitCenterCode
						WHERE H.Barcode=@BARCODE AND H.ProfitCenterCode=@PROFITCENTERCODE AND H.LineCode=@LINECODE
						AND T.TagName IN ('LH_TORQUE','RH_TORQUE','LH_TORQUE_ANGLE','RH_TORQUE_ANGLE','TORQUE_ANGLE','TORQUE')

						IF(@COUNT=6)
						BEGIN
							DELETE FROM PIN_BOLT_TORQUE WHERE Barcode=@BARCODE
							DELETE FROM Bleed_Torque WHERE Barcode = @BARCODE
						END
					END
				END
			   --CHECK SCANNED PART IS CURENTLY RUNNING PART OR NOT
			   		IF  EXISTS
					(		
					-- ADD/COMMENT BY RS ON 20170524 FOR SCANNING VALIDATION FAMILY BARCODE
						--SELECT DISTINCT ASSY_PARTNO FROM DBO.ASSY_RUNNINGPART(NOLOCK) WHERE  LINECODE=@LINECODE 
