								AND OPERATIONCODE=(SELECT OPERATIONCODE  FROM DBO.ASSY_SCAN_OK(NOLOCK) WHERE LINECODE=@LINECODE AND MACHINECODE= @MACHINECODE 
								AND OPERATIONCODE <>@OPERATIONCODE AND BARCODE =@BARCODE)

								SET @RETURNINT=1
								SET @RETURNVALUE='ALREADY_SCANNED_ON_OTHER_STATION^'+@STATIONNAME
								IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
								BEGIN
