								  BEGIN										
											SET @RETURNINT=1
											SET @RETURNVALUE='POKA_YOKE_HAS_BEEN_EXPIRED'										
											--UPDATE INCORRECT LABEL											
											EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
											,@BARCODE=@BARCODE,@HMIMESSAGE='POKA YOKE PART HAS EXPIRED'											
											COMMIT TRAN
											RETURN
								  END
							  --CHECK GROUP HAS  DEFINED FOR SCANNED PART IN ROUTING PART WISE
								IF EXISTS
								(
									SELECT TOP 1 1 FROM DBO.ROUTINGCONFIGPARTWISE(NOLOCK)
									WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND ISNULL(PARTNO,0)=@PARTNUMBER AND ISNULL(PART_FIXTUREGROUPTYPE,'' )='' 	
								)
								BEGIN										
										SET @RETURNINT=1
										SET @RETURNVALUE='GROUP_HAS_NOT_DEFINED_FOR_THIS_PART_IN_PARTWISE_ROUTING.'										
										--UPDATE INCORRECT LABEL										
										EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
										,@BARCODE=@BARCODE,@HMIMESSAGE='GROUP IS NOT DEFINED FOR THIS PART IN ROUTING'										
										COMMIT TRAN
										RETURN			
								END
							  
							   --CHECKING IF PART IN PRODUCTION AND SCANNED IN POKA YOKA ARE SAME
								  IF NOT EXISTS
								  (
								  -- ADD/COMMENT BY RS ON 20170524 FOR SCANNING VALIDATION FAMILY BARCODE	
									--SELECT TOP 1 1 FROM DBO.ASSY_RUNNINGPART WITH (NOLOCK) WHERE ASSY_PARTNO=@PARTNUMBER AND LINECODE=@LINECODE AND ASSY_MODE IN ('PRODUCTION','REWORK')
									SELECT TOP 1 1 FROM @ASSY_RUNNINGPARTGLOBAL WHERE ASSY_PARTNO=@PARTNUMBER AND LINECODE=@LINECODE AND ASSY_MODE IN ('PRODUCTION','REWORK')
								  )
								  BEGIN
									 --CHECK WHETHER SELECTED RUNNING PART AND SCANNED PART BELONGS TO SAME GROUP OR NOT.
										SELECT @PART_FIXTUREGROUPTYPE_COUNT=COUNT(PART_FIXTUREGROUPTYPE)  FROM 
										(
												--FIND THE GROUP FOR RUNNING PART SELECTED FROM ASSY RUNNING PART TABLE.
												SELECT DISTINCT PART_FIXTUREGROUPTYPE FROM DBO.ROUTINGCONFIGPARTWISE(NOLOCK)
												WHERE MACHINECODE=@MACHINECODE AND PROFITCENTERCODE=@PROFITCENTERCODE
												AND PARTNO IN 
													(
													-- ADD/COMMENT BY RS ON 20170524 FOR SCANNING VALIDATION FAMILY BARCODE	
														--SELECT DISTINCT ISNULL(ASSY_PARTNO,'') PARTNUMBER FROM DBO.ASSY_RUNNINGPART(NOLOCK) 
														--WHERE LINECODE=@LINECODE AND ASSY_MODE IN ('PRODUCTION','REWORK')
														SELECT DISTINCT ISNULL(ASSY_PARTNO,'') PARTNUMBER FROM @ASSY_RUNNINGPARTGLOBAL
														WHERE LINECODE=@LINECODE AND ASSY_MODE IN ('PRODUCTION','REWORK')
													)
												UNION 
												--GET THE GROUP FOR SCANNED BARCODE FROM POKA YOKE MASTER TABLE.
												SELECT DISTINCT PART_FIXTUREGROUPTYPE FROM DBO.ROUTINGCONFIGPARTWISE(NOLOCK)
												WHERE MACHINECODE=@MACHINECODE AND PROFITCENTERCODE=@PROFITCENTERCODE
												AND PARTNO IN 
													(
														SELECT DISTINCT ISNULL(PARTNUMBER,'') PARTNUMBER FROM DBO.ASSY_POKAYOKE(NOLOCK) 
														WHERE BARCODE=@BARCODE AND MACHINECODE=@MACHINECODE AND PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE
														AND ISNULL(ISACTIVE,0)=1
													)
										)TBL
										IF @PART_FIXTUREGROUPTYPE_COUNT<>1
										BEGIN
											SET @RETURNINT=1
											SET @RETURNVALUE='RUNNING_PART_AND_SCANNED_POKA_YOKE_DOES_NOT_BELONGS_IN_SAME_GROUP'				
											--UPDATE INCORRECT LABEL												
											EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
											,@BARCODE=@BARCODE,@HMIMESSAGE='RUN. PART AND SCANNED PART  NOT BELONG IN SAME GRP.'												
											COMMIT TRAN
											RETURN
										END
								  END
                                --CHECK FOR DUPLICATE LABEL 
								IF (DBO.ASSY_FN_ISPARTTESTEDATFV_FORPOKAYOKE(@PROFITCENTERCODE,@LINECODE,@MACHINECODE,@OPERATIONCODE)=0)
								BEGIN
										IF EXISTS 
										 (
												SELECT TOP 1 BARCODE FROM #TEMP_ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND  
												LINECODE=@LINECODE AND  MACHINECODE=@MACHINECODE  AND OPERATIONCODE=@OPERATIONCODE AND BARCODE=@BARCODE 
												AND  ISNULL(STATUS,'')<>''										
										 )
										BEGIN							
														 --UPDATE ASSY_DUPLICATELABEL  TABLE										
											
														IF EXISTS
														(
															SELECT DISTINCT 1 FROM DBO.ASSY_DUPLICATELABEL (NOLOCK) WHERE LINECODE=@LINECODE AND    
															OPERATIONCODE=@OPERATIONCODE 
														)
														BEGIN
																	UPDATE ASSY_DUPLICATELABEL SET ISDUPLICATE=1, BARCODE=@BARCODE  WHERE LINECODE=@LINECODE AND 
																	OPERATIONCODE=@OPERATIONCODE
																	--RESET SCAN OK
																	UPDATE ASSY_SCAN_OK SET ISSCAN=0  WHERE LINECODE=@LINECODE AND 
																	OPERATIONCODE=@OPERATIONCODE 													   
																	--RESET   INCORRECT LABEL
																	UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE='' ,ISINCORRECT=0 WHERE LINECODE=@LINECODE AND 
																	OPERATIONCODE=@OPERATIONCODE 

														END
														ELSE
															BEGIN
																	INSERT INTO ASSY_DUPLICATELABEL(LINECODE,OPERATIONCODE,STATIONCODE,BARCODE,ISDUPLICATE)
																	SELECT @LINECODE,@OPERATIONCODE,@STATIONCODE ,@BARCODE ,1
																	--RESET SCAN OK
																	UPDATE ASSY_SCAN_OK SET ISSCAN=0  WHERE LINECODE=@LINECODE AND 
																	OPERATIONCODE=@OPERATIONCODE 													   
																	--RESET   INCORRECT LABEL
																	UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE='' ,ISINCORRECT=0 WHERE LINECODE=@LINECODE AND 
																	OPERATIONCODE=@OPERATIONCODE 

															END	
														SET @RETURNINT=1
														SET @RETURNVALUE='POKA YOKE HAS BEEN ALREADY DONE'													
											           
														COMMIT TRAN
														RETURN				   
												END
								END	
							 --UPDATE SCAN OK RELEATED TABLE
									--IF EXISTS 
									--(
									--	SELECT TOP 1 1 FROM #TEMP_MACHINEMST WITH (NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE
									--	 AND MACHINECODE=@MACHINECODE AND INDEXPERSTATIONS =2
									--)
									IF(@P_INDEXPERSTATIONS = 2)
									BEGIN
											DECLARE @SCANNINGSTATION INT												
											SELECT @STATIONCODE=STATIONCODE FROM DBO.ASSY_STATIONS_ZIG_IN_OUT_STATUS(NOLOCK) WHERE LINECODE=@LINECODE AND 
											OPERATIONCODE=@OPERATIONCODE	
											
											IF @STATIONCODE=1
												SET @SCANNINGSTATION=2
											ELSE IF  @STATIONCODE=2
												SET @SCANNINGSTATION=1
																							
											SET @STATIONCODE=@SCANNINGSTATION	
																		
											IF  EXISTS
											(
												SELECT DISTINCT 1 FROM DBO.ASSY_SCAN_OK(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE 
												AND OPERATIONCODE=@OPERATIONCODE AND MACHINECODE=@MACHINECODE AND STATIONCODE=@SCANNINGSTATION
											)
											BEGIN
													 UPDATE ASSY_SCAN_OK SET ISSCAN=1,BARCODE=@BARCODE,ASSY_PARTNO=@PARTNUMBER,DATECODE=@DATECODE
													,CREATEDBY=@USERID,CREATEDDATE=GETDATE()
													 WHERE 
													PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND OPERATIONCODE=@OPERATIONCODE 
													AND MACHINECODE=@MACHINECODE
													AND STATIONCODE=@SCANNINGSTATION
											END
											ELSE
												BEGIN
															INSERT INTO ASSY_SCAN_OK
															(	PROFITCENTERCODE,LINECODE,OPERATIONCODE,STATIONCODE,BARCODE,ISSCAN,MACHINECODE
																,ASSY_PARTNO,DATECODE,CREATEDBY,CREATEDDATE
															)
															SELECT @PROFITCENTERCODE ,@LINECODE,@OPERATIONCODE,@SCANNINGSTATION,@BARCODE,1,@MACHINECODE	
															,@PARTNUMBER,@DATECODE,@USERID,GETDATE() 																								
												END

												  --RESET   INCORRECT LABEL
												UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE='' ,ISINCORRECT=0 WHERE LINECODE=@LINECODE AND 
												OPERATIONCODE=@OPERATIONCODE

												--RESET DUPLICATE LABEL
												UPDATE ASSY_DUPLICATELABEL SET ISDUPLICATE=0 WHERE LINECODE=@LINECODE AND 
												OPERATIONCODE=@OPERATIONCODE	
									END
									--CHANGED BY RAVI ON 21-07-17 FOR SUB STATION POKA YOKE
									ELSE IF ISNULL(@SUBSTNMACHINECODE,'')<>''
									BEGIN
											IF  EXISTS
											(
												SELECT DISTINCT 1 FROM DBO.ASSY_SCAN_OK(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE 
												AND LINECODE=@LINECODE AND OPERATIONCODE=@SUBSTNOPERATIONCODE AND MACHINECODE=@SUBSTNMACHINECODE
											)
											BEGIN
															UPDATE ASSY_SCAN_OK SET ISSCAN=1,BARCODE=@BARCODE,ASSY_PARTNO=@PARTNUMBER,DATECODE=@DATECODE
															,CREATEDBY=@USERID,CREATEDDATE=GETDATE()
															WHERE 
															PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND OPERATIONCODE=@SUBSTNOPERATIONCODE 
															AND MACHINECODE=@SUBSTNMACHINECODE
															--AND STATIONCODE=@SCANNINGSTATION									
											END
											ELSE
												BEGIN
															INSERT INTO ASSY_SCAN_OK
															(	PROFITCENTERCODE,LINECODE,OPERATIONCODE,STATIONCODE,BARCODE,ISSCAN,MACHINECODE
																,ASSY_PARTNO,DATECODE,CREATEDBY,CREATEDDATE
															)
															SELECT @PROFITCENTERCODE ,@LINECODE,@SUBSTNOPERATIONCODE,@SCANNINGSTATION,@BARCODE,1,@SUBSTNMACHINECODE	
															,@PARTNUMBER,@DATECODE,@USERID,GETDATE() 
																						
												END
												--RESET   INCORRECT LABEL
												UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE='' ,ISINCORRECT=0 WHERE LINECODE=@LINECODE AND 
												OPERATIONCODE=@OPERATIONCODE

												--RESET DUPLICATE LABEL
												UPDATE ASSY_DUPLICATELABEL SET ISDUPLICATE=0 WHERE LINECODE=@LINECODE AND 
												OPERATIONCODE=@OPERATIONCODE	
												
												UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE SET ISCYCLESTARTED=0,BARCODE= @BARCODE,TIMESTAMP=GETDATE()
												WHERE  LINECODE=@LINECODE AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE	
									END
									--BLOCK END CHANGED BY RAVI ON 21-07-17 FOR SUB STATION POKA YOKE
							 		ELSE IF  EXISTS
									(
										SELECT DISTINCT 1 FROM DBO.ASSY_SCAN_OK(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE 
										AND LINECODE=@LINECODE AND OPERATIONCODE=@OPERATIONCODE AND MACHINECODE=@MACHINECODE
									)
									BEGIN
													UPDATE ASSY_SCAN_OK SET ISSCAN=1,BARCODE=@BARCODE,ASSY_PARTNO=@PARTNUMBER,DATECODE=@DATECODE
													,CREATEDBY=@USERID,CREATEDDATE=GETDATE()
													WHERE 
													PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND OPERATIONCODE=@OPERATIONCODE 
													AND MACHINECODE=@MACHINECODE
													--AND STATIONCODE=@SCANNINGSTATION	// COMMENTED BY SACHIN 20170515
											
										--RESET   INCORRECT LABEL
										UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE='' ,ISINCORRECT=0 WHERE LINECODE=@LINECODE AND 
										OPERATIONCODE=@OPERATIONCODE

										--RESET DUPLICATE LABEL
										UPDATE ASSY_DUPLICATELABEL SET ISDUPLICATE=0 WHERE LINECODE=@LINECODE AND 
										OPERATIONCODE=@OPERATIONCODE

										UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE SET ISCYCLESTARTED=0,BARCODE= @BARCODE,TIMESTAMP=GETDATE()
										WHERE  LINECODE=@LINECODE AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE	
									
									END
									ELSE
										BEGIN
												INSERT INTO ASSY_SCAN_OK
												(	PROFITCENTERCODE,LINECODE,OPERATIONCODE,STATIONCODE,BARCODE,ISSCAN,MACHINECODE
													,ASSY_PARTNO,DATECODE,CREATEDBY,CREATEDDATE
												)
												SELECT @PROFITCENTERCODE ,@LINECODE,@OPERATIONCODE,@SCANNINGSTATION,@BARCODE,1,@MACHINECODE	
												,@PARTNUMBER,@DATECODE,@USERID,GETDATE() 

												  --RESET   INCORRECT LABEL
												UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE='' ,ISINCORRECT=0 WHERE LINECODE=@LINECODE AND 
												OPERATIONCODE=@OPERATIONCODE

												--RESET DUPLICATE LABEL
												UPDATE ASSY_DUPLICATELABEL SET ISDUPLICATE=0 WHERE LINECODE=@LINECODE AND 
												OPERATIONCODE=@OPERATIONCODE	
												
												UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE SET ISCYCLESTARTED=0,BARCODE= @BARCODE,TIMESTAMP=GETDATE()
												WHERE  LINECODE=@LINECODE AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE											
										END
								-- INSERT INTO RUNNING PART TABLE..
									IF EXISTS
									( 
										SELECT DISTINCT 1 FROM #TEMP_ASSY_LINEASSYSTATUS_RUNNING(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE  
										AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE  AND  BARCODE=@BARCODE AND ISNULL(STATUS,'')=''
								
									)
									BEGIN
									--1%%%
										UPDATE ASSY_LINEASSYSTATUS_RUNNING SET SCANTIMESTAMP =GETDATE(),Live_Datecode=@Live_Datecode WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE  AND 
										MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE  AND  BARCODE=@BARCODE 
										AND ISNULL(STATUS,'')=''
									END
									ELSE
									BEGIN			
											--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING						
											IF @STMCPARTNO<>''
											     SET @PARTNUMBER=@STMCPARTNO
											INSERT INTO ASSY_LINEASSYSTATUS_RUNNING(PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,BARCODE,DATECODE,PARTNO,ACTIVE,
													STATIONCODE,SCANTIMESTAMP,USERID,PRODUCTIONORDERNO,Live_Datecode)
											SELECT @PROFITCENTERCODE,@LINECODE,@MACHINECODE,@OPERATIONCODE,@BARCODE,
												CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END,@PARTNUMBER,0,@STATIONCODE,GETDATE(),@USERID, @PRODUCTIONORDERNO,@Live_Datecode

									END
								
							SET @RETURNINT=1							
							SET @RETURNVALUE='SCANNED_SUCCESSFULLY'
							COMMIT TRAN							
							RETURN					           
			END
		--POKA YOKE END BLOCK---------------------------------
        ----------CHECK A PART HAS CLEARED FROM PREVIOUS STATION
				
				IF EXISTS
				(
					-- ADD/COMMENT BY RS ON 20170524 FOR SCANNING VALIDATION FAMILY BARCODE	
						--SELECT  TOP 1 1 FROM DBO.ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE =@LINECODE AND ASSY_MODE IN ('PRODUCTION','REWORK') AND ISNULL(PARTTYPE,'')='STMC' 
						SELECT  TOP 1 1 FROM @ASSY_RUNNINGPARTGLOBAL WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE =@LINECODE AND ASSY_MODE IN ('PRODUCTION','REWORK') AND ISNULL(PARTTYPE,'')='STMC' 
				)
				BEGIN					
						-- ADD/COMMENT BY RS ON 20170524 FOR SCANNING VALIDATION FAMILY BARCODE	
						--SELECT @STMCPARTNO=ASSY_PARTNO FROM DBO.ASSY_RUNNINGPART(NOLOCK)  WHERE LINECODE =@LINECODE AND ASSY_MODE IN ('PRODUCTION','REWORK') AND ISNULL(PARTTYPE,'')='STMC' 
						SELECT @STMCPARTNO=ASSY_PARTNO FROM @ASSY_RUNNINGPARTGLOBAL  WHERE LINECODE =@LINECODE AND ASSY_MODE IN ('PRODUCTION','REWORK') AND ISNULL(PARTTYPE,'')='STMC' 
						--EXEC ASSY_PROC_GET_PREVIOUS_MACHINECODE @LINECODE=@LINECODE ,@MACHINECODE=@MACHINECODE,@PARTNUMBER=@STMCPARTNO
						--,@PREVMACHINECODE=@PREVMACHINECODE OUTPUT

						SET @PREVMACHINECODE = @P_PREVMACHINECODE

				END	
				ELSE
				BEGIN							
							--EXEC ASSY_PROC_GET_PREVIOUS_MACHINECODE @LINECODE=@LINECODE ,@MACHINECODE=@MACHINECODE,@PARTNUMBER=@PARTNUMBER
							--,@PREVMACHINECODE=@PREVMACHINECODE OUTPUT
							SET @PREVMACHINECODE = @P_PREVMACHINECODE
				END
					
						--ADD BY RASHID ON 11TH MAY 2016 FOR INSERTING PRINT BARCODE ENTRY
						IF EXISTS
						(
						-- ADD/COMMENT BY RS ON 20170524 FOR SCANNING VALIDATION FAMILY BARCODE	
							--SELECT  TOP 1 1 FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE =@LINECODE AND ASSY_MODE = 'REWORK'
							SELECT  TOP 1 1 FROM @ASSY_RUNNINGPARTGLOBAL WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE =@LINECODE AND ASSY_MODE = 'REWORK'
						)
						BEGIN
							DECLARE @REWORK_PARTTYPE VARCHAR(20) = '',@REWORK_PARTTYPE_CHILD VARCHAR(20) = ''
							-- ADD/COMMENT BY RS ON 20170524 FOR SCANNING VALIDATION FAMILY BARCODE	
							--SELECT  TOP 1 @REWORK_PARTTYPE = ISNULL(PARTTYPE,''), @REWORK_PARTTYPE_CHILD = ISNULL(SERVO_PARTNO,'') FROM ASSY_RUNNINGPART WITH (NOLOCK)
							--	WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND ASSY_MODE = 'REWORK' 
							SELECT  TOP 1 @REWORK_PARTTYPE = ISNULL(PARTTYPE,''), @REWORK_PARTTYPE_CHILD = ISNULL(SERVO_PARTNO,'') FROM @ASSY_RUNNINGPARTGLOBAL
								WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND ASSY_MODE = 'REWORK' 

							IF EXISTS (SELECT TOP 1 BARCODE FROM ASSY_TALLYCHARTSTATUSDATA_HISTORY WITH (NOLOCK)
								WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND ISNULL(NOTPROCESSEDSTATUS,'') = 'SCRAP'
									AND PARTNO = CASE @REWORK_PARTTYPE WHEN 'STMC' THEN @STMCPARTNO ELSE @PARTNUMBER END AND RESULT != 'PASS' AND BARCODE = @BARCODE)
							BEGIN
								SET @RETURNINT = 1
								SET @RETURNVALUE = 'BARCODE IS ALREADY SCRAPPED.'
								--UPDATE INCORRECT LABEL
								IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
								BEGIN
									EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
									,@BARCODE = @BARCODE, @HMIMESSAGE = 'REJECTED PART.'
								END
								COMMIT
								RETURN
							END

							DECLARE @REWORKCOUNTDEFINED INT = 0,@REWORKVISIONCOUNT INT = 0,@REWORKFINALVIEWINGOPERATIONCODE VARCHAR(20) = '',
									@REWORKFIRSTSTATIONCOUNT INT = 0, @REWORK_FIRST_MACHINECODE VARCHAR(20) = '',@REWORK_FIRST_OPERATIONCODE VARCHAR(20) = '',
									@REWORK_SECOND_MACHINECODE VARCHAR(20) = '',@REWORK_SECOND_OPERATIONCODE VARCHAR(20) = ''
							
							SELECT TOP 1 @REWORK_FIRST_MACHINECODE = RTRIM(MACHINECODE), @REWORK_FIRST_OPERATIONCODE = RTRIM(OPERATIONCODE)
								FROM #TEMP_ROUTINGCONFIGLINEWISE WITH (NOLOCK) WHERE OPERATIONREQUIRED = 1 AND TRACEABILITY = 1 AND OPERATIONSEQNO = 1
							
							SELECT TOP 1 @REWORK_SECOND_MACHINECODE = RTRIM(MACHINECODE), @REWORK_SECOND_OPERATIONCODE = RTRIM(OPERATIONCODE)
								FROM #TEMP_ROUTINGCONFIGLINEWISE WITH (NOLOCK) WHERE OPERATIONREQUIRED = 1 AND TRACEABILITY = 1 AND OPERATIONSEQNO <> 1 
								ORDER BY OPERATIONSEQNO

							SELECT @REWORKFINALVIEWINGOPERATIONCODE = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE)
							
							SELECT @REWORKFIRSTSTATIONCOUNT = COUNT(BARCODE) FROM #TEMP_ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK)
								WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND
									DATECODE = @REWORK_DATECODE AND OPERATIONCODE = @REWORK_FIRST_OPERATIONCODE
										AND ISNULL(ISTALLYCHARTAPPROVED,0) = 0

							SELECT @REWORKFIRSTSTATIONCOUNT = @REWORKFIRSTSTATIONCOUNT + COUNT(BARCODE) FROM ASSY_LINEASSYSTATUS WITH (NOLOCK)
								WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND
									DATECODE = @REWORK_DATECODE AND OPERATIONCODE = @REWORK_FIRST_OPERATIONCODE
										AND ISNULL(ISTALLYCHARTAPPROVED,0) = 0
							
							DECLARE @FG_BARCODE VARCHAR(20) = ''
							DECLARE @PACKAGEBARCODE  TABLE
							(BARCODE VARCHAR(60) NOT NULL)

							SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL  WITH (NOLOCK) 
											WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
							IF @REWORK_PARTTYPE = 'STMC'
							BEGIN
								IF EXISTS(SELECT 1 FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE CHILD_BARCODE = @BARCODE)
								BEGIN
									SELECT TOP 1 @FG_BARCODE = ISNULL(FG_BARCODE,'') FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE CHILD_BARCODE = @BARCODE
								END
								ELSE IF EXISTS(SELECT 1 FROM ASSY_COUPLINGDETAILS_HISTORY WITH (NOLOCK) WHERE CHILD_BARCODE = @BARCODE)
								BEGIN
									SELECT TOP 1 @FG_BARCODE = ISNULL(FG_BARCODE,'') FROM ASSY_COUPLINGDETAILS_HISTORY WITH (NOLOCK) WHERE CHILD_BARCODE = @BARCODE
								END

								IF @FG_BARCODE != ''
								BEGIN
									SET @EXECQUERY = '
										SELECT PARTBARCODE FROM ' + @LINKSERVERNAME + '.DBO.SKIDBARCODEDETAIL WITH (NOLOCK) WHERE WH_CODE = ''' + @PROFITCENTERCODE + ''' AND PARTBARCODE = ''' + @FG_BARCODE + ''''
									PRINT @EXECQUERY
								END
							END
							ELSE
							BEGIN
								SET @EXECQUERY = '
										SELECT PARTBARCODE FROM ' + @LINKSERVERNAME + '.DBO.SKIDBARCODEDETAIL WITH (NOLOCK) WHERE WH_CODE = ''' + @PROFITCENTERCODE + ''' AND PARTBARCODE = ''' + @BARCODE + ''''
									PRINT @EXECQUERY
							END

							INSERT INTO @PACKAGEBARCODE(BARCODE)
							EXEC (@EXECQUERY)
				
							IF EXISTS (SELECT 1 FROM @PACKAGEBARCODE)
							BEGIN
								IF @REWORK_PARTTYPE = 'STMC'
								BEGIN
									SET @RETURNVALUE = 'PART ALREADY PACKED IN PACKAGING, FIRST UNPACK AND THEN DECOUPLE IF IT IS COUPLED.'
									SET @RETURNINT = 1
									IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
									BEGIN
										EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
										,@BARCODE = @BARCODE, @HMIMESSAGE = 'PART ALREADY PACKED IN PACKAGING, FIRST UNPACKED AND DECOUPLE IF IT IS COUPLED.'
									END
									DELETE FROM @PACKAGEBARCODE
									COMMIT
									RETURN
								END
								ELSE
								BEGIN
									SET @RETURNVALUE = 'PART ALREADY PACKED IN PACKAGING, UNPACK THE PART.'
									SET @RETURNINT = 1
									IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
									BEGIN
										EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
										,@BARCODE = @BARCODE, @HMIMESSAGE = 'PART ALREADY PACKED IN PACKAGING, UNPACKED THE PART.'
									END
									DELETE FROM @PACKAGEBARCODE
									COMMIT
									RETURN
								END
							END

							SELECT @REWORKCOUNTDEFINED = @P_REWORK_VISION_COUNT --CONVERT(INT,PARAMETER_VALUE) FROM PARAMETER_MST(NOLOCK)  
							   --WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'REWORK_VISION_COUNT' AND WH_CODE = @PROFITCENTERCODE
					
								SELECT @REWORKVISIONCOUNT = COUNT(BARCODE) FROM ASSY_VISION_SYSTEM_HISTORY (NOLOCK)
									WHERE BARCODE = @BARCODE AND LINECODE = @LINECODE AND ISNULL(ISREWORK,0) = 1

							IF(@REWORKCOUNTDEFINED <= @REWORKVISIONCOUNT)
							BEGIN
								SET @RETURNINT = 1
								SET @RETURNVALUE = 'PART MAXIMUM REWORK ATTEMP REACHED. CAN NOT DO REWORK'
								--UPDATE INCORRECT LABEL
								IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
								BEGIN
									EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
									,@BARCODE = @BARCODE, @HMIMESSAGE = 'MAXIMUM REWORK ATTEMPT REACHED'
								END
								COMMIT
								RETURN
							END
							--DECLARE @PRINTBARCODEMACHINECODE VARCHAR(20) = ''
							--SELECT @PRINTBARCODEMACHINECODE = DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE)
							IF NOT EXISTS (SELECT 1 FROM #TEMP_ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE ISNULL(ISTALLYCHARTAPPROVED,0) = 0 AND
								PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND DATECODE = @REWORK_DATECODE
								AND MACHINECODE = @REWORK_FIRST_MACHINECODE AND BARCODE = @BARCODE)
							BEGIN
								IF @REWORK_PARTTYPE = 'STMC'
								BEGIN
									IF CHARINDEX(':',@BARCODE) <> 0
									BEGIN
										IF @OPERATIONCODE = @REWORK_SECOND_OPERATIONCODE
										BEGIN
											SET @RETURNINT = 1
											SET @RETURNVALUE = 'INVALID BARCODE (COUPLED BARCODE)'
											--UPDATE INCORRECT LABEL
											IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
											BEGIN
												EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
												,@BARCODE = @BARCODE, @HMIMESSAGE = 'INVALID BARCODE'
											END
											COMMIT
											RETURN
										END
									END

									IF EXISTS(SELECT 1 FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE CHILD_BARCODE = @BARCODE)
									BEGIN
										SET @RETURNINT = 1
										SET @RETURNVALUE = 'BARCODE ALREADY COUPLED. FIRST DECOUPLE FROM STMC REWORK FORM.'
										--UPDATE INCORRECT LABEL
										IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
										BEGIN
											EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
											,@BARCODE = @BARCODE, @HMIMESSAGE = 'BARCODE ALREADY COUPLED. FIRST DECOUPLE FROM STMC REWORK FORM.'
										END
										COMMIT
										RETURN
									END
								END

								IF @OPERATIONCODE = @REWORK_SECOND_OPERATIONCODE
								BEGIN
									IF(@REWORKFIRSTSTATIONCOUNT >= @REWORK_CURRENT_PLANQTY)
									BEGIN
										SET @RETURNINT = 1
										SET @RETURNVALUE = 'REWORK PLANNED QTY REACHED.'
										--UPDATE INCORRECT LABEL
										IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
										BEGIN
											EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
											,@BARCODE = @BARCODE, @HMIMESSAGE = 'REWORK PLANNED QTY REACHED.'
										END
										COMMIT
										RETURN
									END
								END

								IF NOT EXISTS (SELECT 1 FROM ASSY_LINEASSYSTATUS (NOLOCK) WHERE ISNULL(ISTALLYCHARTAPPROVED,0) = 0 AND
												PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND BARCODE = @BARCODE )
								BEGIN
									IF NOT EXISTS (SELECT 1 FROM ASSY_VISION_SYSTEM WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND BARCODE = @BARCODE)
									BEGIN
										IF CHARINDEX(':',@BARCODE) = 0
										BEGIN
											INSERT INTO ASSY_VISION_SYSTEM(PROFITCENTERCODE,LINECODE,BARCODE,TIMESTAMP,DATECODE,PARTNO,SERIALNO,ISREWORK)
											SELECT @PROFITCENTERCODE,@LINECODE,@BARCODE,GETDATE(),@REWORK_DATECODE,CASE @REWORK_PARTTYPE WHEN 'STMC' 
											THEN @REWORK_PARTTYPE_CHILD ELSE @PARTNUMBER END,SUBSTRING(@BARCODE,LEN(CASE @REWORK_PARTTYPE WHEN 'STMC' 
											THEN @REWORK_PARTTYPE_CHILD ELSE @PARTNUMBER END) + 5,8),1

											UPDATE ASSY_RUNNINGPART  SET PRINTEDQTY = ISNULL(PRINTEDQTY,0) + 1 WHERE PROFITCENTERCODE = @PROFITCENTERCODE
												AND LINECODE = @LINECODE
										END
									END
										
									SELECT @REWORK_PRINT_QTY = ISNULL(PRINTEDQTY,0) FROM #TEMP_ASSY_RUNNINGPART WITH (NOLOCK)
										WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

									IF NOT EXISTS (SELECT 1 FROM ASSY_BARCODE_PRINTED_COUNTER WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
														AND DATECODE = @REWORK_DATECODE AND PRODUCTIONORDERNO = @REWORK_ORDERNO AND PARTNO = CASE @REWORK_PARTTYPE WHEN 'STMC' THEN @STMCPARTNO ELSE @PARTNUMBER END )
									BEGIN
										IF CHARINDEX(':',@BARCODE) = 0
										BEGIN
											INSERT INTO ASSY_BARCODE_PRINTED_COUNTER(PROFITCENTERCODE,LINECODE,DATECODE,PRODUCTIONORDERNO,PARTNO,CURRENTPLANNEDQTY,PRINTEDQTY,TIMESTAMP)
											SELECT @PROFITCENTERCODE, @LINECODE, @REWORK_DATECODE,@REWORK_ORDERNO,CASE @REWORK_PARTTYPE WHEN 'STMC' THEN @STMCPARTNO ELSE @PARTNUMBER END,@REWORK_CURRENT_PLANQTY,@REWORK_PRINT_QTY,GETDATE()
										END
									END
									ELSE
									BEGIN
										IF CHARINDEX(':',@BARCODE) = 0
										BEGIN
											UPDATE ASSY_BARCODE_PRINTED_COUNTER SET PRINTEDQTY = @REWORK_PRINT_QTY WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
													AND DATECODE = @REWORK_DATECODE AND PRODUCTIONORDERNO = @REWORK_ORDERNO AND PARTNO = CASE @REWORK_PARTTYPE WHEN 'STMC' THEN @STMCPARTNO ELSE @PARTNUMBER END
											END
									END
									IF CHARINDEX(':',@BARCODE) = 0
									BEGIN
										--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
										INSERT INTO ASSY_LINEASSYSTATUS_RUNNING(PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,BARCODE,DATECODE,PARTNO,ACTIVE,
													STATIONCODE,SCANTIMESTAMP,USERID,STATUS,RESULTTIMESTAMP,PRODUCTIONORDERNO,Live_Datecode)
										SELECT TOP 1 @PROFITCENTERCODE,@LINECODE,@REWORK_FIRST_MACHINECODE,@REWORK_FIRST_OPERATIONCODE,@BARCODE,@REWORK_DATECODE,
											CASE @REWORK_PARTTYPE WHEN 'STMC' THEN @STMCPARTNO ELSE @PARTNUMBER END,1,1,GETDATE(),@USERID,'PS',GETDATE(), @PRODUCTIONORDERNO,@Live_Datecode
									END
											
									IF EXISTS (SELECT 1 FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE BARCODE = @BARCODE)
									BEGIN
										--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
										INSERT INTO ASSY_LINEASSYSTATUS_HISTORY (PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,
										STATIONCODE,BARCODE,STATUS,FAILCOUNT,DATECODE,PARTNO,SCANTIMESTAMP,RESULTTIMESTAMP,ACTIVE,USERID,
										ISTALLYCHARTAPPROVED,TRANSACTION_NUMBER,ISCONFIRMED,KANBAN_ID,ERP_CONF_TIMESTAMP,HIS_ENT_DT,HIS_ENT_BY,ISREWORKPART,PRODUCTIONORDERNO)
										SELECT PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,STATIONCODE,BARCODE,STATUS,
										FAILCOUNT,DATECODE,PARTNO,SCANTIMESTAMP,RESULTTIMESTAMP,ACTIVE,USERID,ISTALLYCHARTAPPROVED,
										TRANSACTION_NUMBER,ISCONFIRMED,KANBAN_ID,ERP_CONF_TIMESTAMP,GETDATE(),@USERID,ISREWORKPART,
										PRODUCTIONORDERNO FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE BARCODE = @BARCODE

										DELETE FROM ASSY_LINEASSYSTATUS WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND BARCODE = @BARCODE
									END
									
									IF @REWORK_PARTTYPE = 'STMC'
									BEGIN
										SET @FG_BARCODE = ''
										IF EXISTS(SELECT 1 FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE CHILD_BARCODE = @BARCODE)
										BEGIN
											SELECT TOP 1 @FG_BARCODE = ISNULL(FG_BARCODE,'') FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE CHILD_BARCODE = @BARCODE
										END
										ELSE IF EXISTS(SELECT 1 FROM ASSY_COUPLINGDETAILS_HISTORY WITH (NOLOCK) WHERE CHILD_BARCODE = @BARCODE)
										BEGIN
											SELECT TOP 1 @FG_BARCODE = ISNULL(FG_BARCODE,'') FROM ASSY_COUPLINGDETAILS_HISTORY WITH (NOLOCK) WHERE CHILD_BARCODE = @BARCODE
										END

										IF @FG_BARCODE != ''
										BEGIN
											IF EXISTS (SELECT 1 FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE BARCODE = @FG_BARCODE)
											BEGIN
												--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
												INSERT INTO ASSY_LINEASSYSTATUS_HISTORY (PROFITCENTERCODE,LINECODE,MACHINECODE,
												OPERATIONCODE,STATIONCODE,BARCODE,STATUS,FAILCOUNT,DATECODE,PARTNO,SCANTIMESTAMP,
												RESULTTIMESTAMP,ACTIVE,USERID,ISTALLYCHARTAPPROVED,TRANSACTION_NUMBER,
												ISCONFIRMED,KANBAN_ID,ERP_CONF_TIMESTAMP,HIS_ENT_DT,HIS_ENT_BY,ISREWORKPART,
												PRODUCTIONORDERNO)
												SELECT PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,STATIONCODE,BARCODE,STATUS,
												FAILCOUNT,DATECODE,PARTNO,SCANTIMESTAMP,RESULTTIMESTAMP,ACTIVE,USERID,
												ISTALLYCHARTAPPROVED,TRANSACTION_NUMBER,ISCONFIRMED,KANBAN_ID,ERP_CONF_TIMESTAMP,
												GETDATE(),@USERID,ISREWORKPART,PRODUCTIONORDERNO FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE BARCODE = @FG_BARCODE OR BARCODE = @BARCODE

												DELETE FROM ASSY_LINEASSYSTATUS WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND ( BARCODE = @FG_BARCODE OR BARCODE = @BARCODE)
											END
										END
									END
								END
							END
						END
					--CHANGED BY RAVI ON 16-02-16
