				    SELECT @FAILCOUNTDEFINED=@P_REWORK_COUNT --CONVERT(INT,PARAMETER_VALUE)   FROM DBO.PARAMETER_MST(NOLOCK)  
				   --WHERE PARAMETER_C='ASSLINE' 
				   --AND PARAMETER_C1='REWORK_COUNT'	
				   --AND WH_CODE =@PROFITCENTERCODE 
					
					--30%%%
					SELECT @FAILCOUNT=ISNULL(FAILCOUNT,0)  FROM #TEMP_ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE BARCODE=@BARCODE 
					AND LINECODE=@LINECODE  
					AND	MACHINECODE=@MACHINECODE 
					AND ISNULL(STATUS,'') ='FL'			
					IF ISNULL(@FAILCOUNT,0) = 0
					BEGIN
						SELECT @FAILCOUNT = ISNULL(FAILCOUNT, 0)  FROM ASSY_LINEASSYSTATUS (NOLOCK)
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
						-- Start - Added By RS On 20191021 DateCode Removed for WIP Logic
							--AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END AND BARCODE = @BARCODE AND MACHINECODE = @MACHINECODE AND ISNULL(STATUS, '') = 'FL'
							AND BARCODE = @BARCODE AND MACHINECODE = @MACHINECODE AND ISNULL(STATUS, '') = 'FL'
						-- End - Added By RS On 20191021 DateCode Removed for WIP Logic
					END						
					IF(@FAILCOUNTDEFINED<=@FAILCOUNT)
					BEGIN					    
						 SET @RETURNINT=1
						 SET @RETURNVALUE='MAXIMUM_FAILED_ATTEMPT_REACHED'
						--UPDATE INCORRECT LABEL
						IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
						BEGIN
							EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
							,@BARCODE=@BARCODE,@HMIMESSAGE='MAXIMUM FAILED ATTEMPT REACHED'
						END
						 COMMIT TRAN
						 RETURN
					END		
									 
					--CHECK FOR DUPLICATE LABEL -------------------------------------------------------------------------------OK
					--Commented By Sachin 16March2020
					--SET @SCANNEDBARCODE=''
					----7%%%
			  --  	SELECT @SCANNEDBARCODE=ISNULL(BARCODE,'') FROM DBO.ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) 
					--WHERE --ISNULL(ISTALLYCHARTAPPROVED,0)=0 AND commented by Sachin 20190617
					--PROFITCENTERCODE =@PROFITCENTERCODE 
					--AND LINECODE=@LINECODE 
					----AND DATECODE =CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END  commented by Sachin 20190617
					--AND  MACHINECODE=@MACHINECODE AND BARCODE=@BARCODE AND  ISNULL(STATUS,'')='PS'
						
					--IF @SCANNEDBARCODE = ''
					--BEGIN
					--	--7%%%
					--		SELECT @SCANNEDBARCODE=ISNULL(BARCODE,'') FROM DBO.ASSY_LINEASSYSTATUS (NOLOCK) 
					--		WHERE --ISNULL(ISTALLYCHARTAPPROVED,0)=0 AND commented by Sachin 20190617
					--		PROFITCENTERCODE = @PROFITCENTERCODE 
					--		AND LINECODE = @LINECODE 
					--		--AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END commented by Sachin 20190617
					--		AND  MACHINECODE=@MACHINECODE AND BARCODE=@BARCODE AND  ISNULL(STATUS,'')='PS'
					--END
					--Comment Ended by Sachin 16March2020
					
					-- MOVE PERFORMANCE PASS DATA IF CRIMPING TIME LIMIT REACHED (ADDED BY RASHID ON 31ST MAY 2016)
					DECLARE @CRIMPINGMACHINECODE VARCHAR(30) = '', @CRIMPINGTIMELIMIT INT = 0, @PREVRESULTTIMESTAMP DATETIME = NULL, @BFLAG BIT = 0,
							@PERFORMANCEMACHINECODE VARCHAR(30) = ''
					
					SELECT @CRIMPINGMACHINECODE = @P_CRIMPING_MACHINECODE --ISNULL(UPPER(LTRIM(RTRIM(PARAMETER_VALUE))),'') FROM PARAMETER_MST WITH (NOLOCK)
							   --WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'CRIMPING' AND PARAMETER_C2 = 'MACHINECODE' AND WH_CODE = @PROFITCENTERCODE

					SELECT @PERFORMANCEMACHINECODE = @P_FINALVIEWING_SERVO_PERFORMANCE_MACHINECODE --ISNULL(UPPER(LTRIM(RTRIM(PARAMETER_VALUE))),'') FROM PARAMETER_MST WITH (NOLOCK)
							   --WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'FINALVIEWING' AND PARAMETER_C2 = 'SERVO_PERFORMANCE_MACHINECODE' AND WH_CODE = @PROFITCENTERCODE
					
					IF @SCANNEDBARCODE <> '' AND (@MACHINECODE = @PERFORMANCEMACHINECODE)
					BEGIN
						IF EXISTS (SELECT 1 FROM ASSY_LINE_CRIMPING_RETEST_STATUS WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND
												LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND BARCODE = @BARCODE AND ISNULL(ISRETEST,0) = 0)
						BEGIN	
							--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
							INSERT INTO ASSY_PERFORMANCEHISTORY(PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,STATIONCODE,
							BARCODE,STATUS,FAILCOUNT,DATECODE,PARTNO,ACTIVE,RESULTTIMESTAMP,SCANTIMESTAMP,USERID,ISTALLYCHARTAPPROVED,
							ISREWORKPART,HISTORYTIMESTAMP,PRODUCTIONORDERNO)
							SELECT PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,STATIONCODE,BARCODE,STATUS,FAILCOUNT,DATECODE,PARTNO,ACTIVE,RESULTTIMESTAMP,SCANTIMESTAMP,USERID,ISTALLYCHARTAPPROVED,ISREWORKPART,GETDATE(),PRODUCTIONORDERNO
								FROM #TEMP_ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
									AND MACHINECODE = @MACHINECODE AND BARCODE = @BARCODE AND ISNULL(STATUS,'') = 'PS'
							
							DELETE FROM ASSY_LINEASSYSTATUS_RUNNING WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
									AND MACHINECODE = @MACHINECODE AND BARCODE = @BARCODE AND ISNULL(STATUS,'') = 'PS'
							
							DELETE FROM ASSY_PERFORMANCE_ZIGOUTTIMESTAMP WHERE BARCODE = @BARCODE

							UPDATE ASSY_LINE_CRIMPING_RETEST_STATUS SET ISRETEST = 1 WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND
												LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND BARCODE = @BARCODE AND ISNULL(ISRETEST,0) = 0
							SET @BFLAG = 1
						END
					END
					--Commented By Sachin 16March2020
					--IF @SCANNEDBARCODE <> ''					
					-- BEGIN
					--	IF @BFLAG = 0
					--	BEGIN
						
					--		--UPDATE ASSY_DUPLICATELABEL  TABLE
					--		IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
					--		BEGIN
					--			IF  NOT EXISTS
					--			( 
					--								SELECT 1 FROM DBO.ASSY_SCAN_OK(NOLOCK) WHERE LINECODE =@LINECODE AND OPERATIONCODE=@OPERATIONCODE AND ISNULL(ISCYCLESTARTED,0)=1
					--			)
					--			BEGIN
					--				IF EXISTS
					--				(
					--										SELECT DISTINCT 1 FROM DBO.ASSY_DUPLICATELABEL (NOLOCK) WHERE LINECODE=@LINECODE AND    
					--					OPERATIONCODE=@OPERATIONCODE 
					--				)
					--				BEGIN
					--					UPDATE ASSY_DUPLICATELABEL SET ISDUPLICATE=1, BARCODE=@BARCODE  WHERE LINECODE=@LINECODE AND 
					--					OPERATIONCODE=@OPERATIONCODE
					--					--RESET SCAN OK
					--					UPDATE ASSY_SCAN_OK SET ISSCAN=0  WHERE LINECODE=@LINECODE AND 
					--					OPERATIONCODE=@OPERATIONCODE 													   
					--					--RESET   INCORRECT LABEL
					--					UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE='' ,ISINCORRECT=0 WHERE LINECODE=@LINECODE AND 
					--					OPERATIONCODE=@OPERATIONCODE 

					--				END
					--				ELSE
					--				BEGIN
					--					INSERT INTO ASSY_DUPLICATELABEL(LINECODE,OPERATIONCODE,STATIONCODE,BARCODE,ISDUPLICATE)
					--					SELECT @LINECODE,@OPERATIONCODE,@STATIONCODE ,@BARCODE ,1
					--					--RESET SCAN OK
					--					UPDATE ASSY_SCAN_OK SET ISSCAN=0  WHERE LINECODE=@LINECODE AND 
					--					OPERATIONCODE=@OPERATIONCODE 													   
					--					--RESET   INCORRECT LABEL
					--					UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE='' ,ISINCORRECT=0 WHERE LINECODE=@LINECODE AND 
					--					OPERATIONCODE=@OPERATIONCODE 
					--				END
					--			END												
					--		END
              
								
					--			-- 2%%%
					--		SELECT @PARTTESTINGTIME=RESULTTIMESTAMP FROM DBO.ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) 
					--		WHERE --ISNULL(ISTALLYCHARTAPPROVED,0)=0 AND commented by Sachin 20190617
					--		PROFITCENTERCODE =@PROFITCENTERCODE 
					--		AND LINECODE=@LINECODE 
					--		--AND DATECODE =CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END 
					--		AND  MACHINECODE=@MACHINECODE AND BARCODE=@BARCODE AND  ISNULL(STATUS,'')='PS'
						
					--		IF @PARTTESTINGTIME IS NULL
					--		BEGIN
					--		-- 2%%%
					--			SELECT @PARTTESTINGTIME=RESULTTIMESTAMP FROM DBO.ASSY_LINEASSYSTATUS (NOLOCK) 
					--			WHERE --ISNULL(ISTALLYCHARTAPPROVED,0)=0 AND commented by Sachin 20190617
					--			PROFITCENTERCODE =@PROFITCENTERCODE 
					--			AND LINECODE=@LINECODE 
					--			--AND DATECODE =CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END 
					--			AND  MACHINECODE=@MACHINECODE AND BARCODE=@BARCODE AND  ISNULL(STATUS,'')='PS'
					--		END										
					--		SET @RETURNINT = 1
					--		SET @RETURNVALUE = 'DUPLICATE_LABEL^'+CONVERT(VARCHAR(100), @PARTTESTINGTIME)
					--		COMMIT TRAN
					--		RETURN
					--	END
				 --  END
				 --Commented Ended Sachin 16March2020

				  -- CHECK FOR CRIMPING TIME LIMIT FROM PERFORMANCE STATION (ADDED BY RASHID ON 31ST MAY 2016)
					IF (@CRIMPINGMACHINECODE != '' AND @CRIMPINGMACHINECODE = @MACHINECODE)
					BEGIN
						IF EXISTS (SELECT 1 FROM #TEMP_ROUTINGCONFIGLINEWISE WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
									AND MACHINECODE = @PERFORMANCEMACHINECODE AND ISNULL(TRACEABILITY,0) = 0)
						BEGIN
							SET @RETURNINT = 1
							SET @RETURNVALUE = 'PERFORMANCE STATION IS BYPASS. SO CAN NOT RUN LINE WITH CRIMPING STATION.'
							COMMIT TRAN
							RETURN
						END
						SELECT @CRIMPINGTIMELIMIT = @P_BOOSTERLINE_CRIMPINGTIMELIMIT --CONVERT(INT,ISNULL(LTRIM(RTRIM(PARAMETER_VALUE)),0)) FROM PARAMETER_MST WITH (NOLOCK)
							  -- WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'BOOSTERLINE' AND PARAMETER_C2 = 'CRIMPINGTIMELIMIT' AND WH_CODE = @PROFITCENTERCODE
						
						SELECT @PREVRESULTTIMESTAMP = ZIGOUTTIMESTAMP FROM ASSY_PERFORMANCE_ZIGOUTTIMESTAMP WITH (NOLOCK) WHERE BARCODE = @BARCODE
						
						IF @PREVRESULTTIMESTAMP IS NULL
						BEGIN
							EXEC ASSY_PROC_RETEST_MANAGE @CONDITION = 'UPDATE',@LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
								,@BARCODE = @BARCODE, @HMIMESSAGE = 'JIG IS NOT COME OUT FROM PERFORMANCE STATION PROPERLY. RETEST IN PREVIOUS STATION'
							
							IF NOT EXISTS (SELECT 1 FROM ASSY_LINE_CRIMPING_RETEST_STATUS WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND
											LINECODE = @LINECODE AND MACHINECODE = @PREVMACHINECODE AND BARCODE = @BARCODE AND ISNULL(ISRETEST,0) = 0)
							BEGIN	
								INSERT INTO ASSY_LINE_CRIMPING_RETEST_STATUS(PROFITCENTERCODE,LINECODE,MACHINECODE,BARCODE,TIMESTAMP,ISRETEST,REMARK)
								SELECT @PROFITCENTERCODE,@LINECODE,@PREVMACHINECODE,@BARCODE,GETDATE(),0,'JIG IS NOT COME OUT FROM PERFORMANCE STATION PROPERLY. RETEST IN PREVIOUS STATION'
							END

							SET @RETURNINT = 1
							SET @RETURNVALUE = 'JIG IS NOT COME OUT FROM PERFORMANCE STATION PROPERLY. RETEST IN PREVIOUS STATION'
							--SET @RETURNVALUE = 'ZIG IS NOT COME OUT FROM PERFORMANCE STATION. SO CAN NOT SCAN.'
							COMMIT TRAN
							RETURN
						END				
						--SELECT @PREVRESULTTIMESTAMP = RESULTTIMESTAMP FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK) WHERE PROFITCENTERCODE =@PROFITCENTERCODE
						--				AND LINECODE = @LINECODE AND ISNULL(ISTALLYCHARTAPPROVED,0) = 0 AND  MACHINECODE = @PREVMACHINECODE
						--				AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END  AND BARCODE = @BARCODE
						--				AND  ISNULL(STATUS,'') = 'PS'
						
						IF(DATEDIFF(SECOND,@PREVRESULTTIMESTAMP,GETDATE()) > @CRIMPINGTIMELIMIT)
						BEGIN
							SET @INCORRECTMSG = ''
							SET @INCORRECTMSG= @P_PREVMACHINENAME --(SELECT TOP 1 MACHINENAME FROM #TEMP_MACHINEMST WITH (NOLOCK) WHERE MACHINECODE = @PREVMACHINECODE
													 --AND PROFITCENTERCODE = @PROFITCENTERCODE)
							SET @RETURNINT = 1
							SET @RETURNVALUE = 'SCAN TIME LIMIT REACHED. RETEST IN PREVIOUS STATION - ' + @INCORRECTMSG
							IF @OPERATIONCODE <> @FINALVIEWING_OPERATIONCODE
							BEGIN
								EXEC ASSY_PROC_RETEST_MANAGE @CONDITION = 'UPDATE',@LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
								,@BARCODE = @BARCODE, @HMIMESSAGE = 'SCAN TIME LIMIT REACHED. RETEST IN PREVIOUS STATION'
							END
							IF NOT EXISTS (SELECT 1 FROM ASSY_LINE_CRIMPING_RETEST_STATUS WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND
											LINECODE = @LINECODE AND MACHINECODE = @PREVMACHINECODE AND BARCODE = @BARCODE AND ISNULL(ISRETEST,0) = 0)
							BEGIN	
								INSERT INTO ASSY_LINE_CRIMPING_RETEST_STATUS(PROFITCENTERCODE,LINECODE,MACHINECODE,BARCODE,TIMESTAMP,ISRETEST,REMARK)
								SELECT @PROFITCENTERCODE,@LINECODE,@PREVMACHINECODE,@BARCODE,GETDATE(),0,'DIFFERECE OF TIME(SECONDS) BETWEEN RESULTTIMESTAMP OF PERFORMANCE STATION AND CRIMPING STATION'
							END	
							COMMIT TRAN
							RETURN
						END
					END

					IF @OPERATIONCODE = @FINALVIEWING_OPERATIONCODE
					BEGIN
						--START-- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING STOCK DEDUCTION
						--IF ((SELECT ISNULL(ISMATFEEDREQUIRED,0) FROM #TEMP_LINEMST WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE) = 1)
						IF(@P_ISMATFEEDREQUIRED = 1)
						BEGIN
							--START-- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING VALIDATION
							 SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL WITH (NOLOCK)
									WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

							SET @EXECQUERY = ''
							SET @EXECQUERY = '
								SELECT REMARKS FROM ' + @LINKSERVERNAME + '.DBO.ASSY_LINEMATFEEDREMARKSTATUS WITH (NOLOCK)
									WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + '''
									AND PARTNO = ''' + @PARTNUMBER + ''' AND ISACTIVE = 1 '
							--PRINT @EXECQUERY

							DECLARE @MATFEEDREMARK AS TABLE
							(
								REMARKS VARCHAR(500) --VARCHAR(200) MODIFIED BY SACHIN 20170411
							)

							INSERT INTO @MATFEEDREMARK(REMARKS)
							EXEC (@EXECQUERY)
				
							DECLARE @MATFEEDREMARKSTATUS VARCHAR(500) = ''

							IF EXISTS (SELECT 1 FROM @MATFEEDREMARK)
							BEGIN
								SELECT @MATFEEDREMARKSTATUS = LTRIM(RTRIM(REMARKS)) FROM @MATFEEDREMARK
								
								DECLARE @QTYLOWMESSAGE BIT = 0
								IF (@MATFEEDREMARKSTATUS != 'OK')
								BEGIN
									IF (UPPER(LEFT(@MATFEEDREMARKSTATUS,4)) = 'SOME')
									BEGIN
										SET @QTYLOWMESSAGE = 1
									END
									ELSE
									BEGIN
										SET @RETURNVALUE = @MATFEEDREMARKSTATUS
										SET @RETURNINT = 1

										COMMIT
										RETURN
									END
								END
							END
						END
					END
					--END-- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING VALIDATION
					  ----CHECK FOR WIP LIMIT			      	
			        EXEC ASSY_PROC_WIP_MANAGE  @CONDITION='VALIDATE_WIP', @LINECODE=@LINECODE,@MACHINECODE=@MACHINECODE,@BARCODE=@BARCODE,@PROFITCENTERCODE =@PROFITCENTERCODE  
					,@RETURNVALUE=@RETURNVALUE1 OUT,@RETURNINT=@RETURNINT1 OUT
			           IF  RTRIM(LTRIM(@RETURNVALUE1))='WIP_LIMIT_HAS_REACHED'
					   BEGIN							
								 SET @RETURNINT=1
								 SET @RETURNVALUE='WIP_LIMIT_HAS_REACHED'
								--UPDATE INCORRECT LABEL
								IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
								BEGIN
									EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
									,@BARCODE=@BARCODE,@HMIMESSAGE='WIP LIMIT REACHED'
								END
								 COMMIT TRAN
								RETURN
						END		
					   
						--CHANGED BY RAVI FOR JHAGADIA ON 10/08/16 TO CHECK WHETHER SAME CALIPER SERIAL NO. HAS BEEN ALREADY GENERATED AT COUPLING STATION OR NOT.
						 --IF EXISTS
						 --(
						 --		   SELECT 1 FROM #TEMP_ROUTINGCONFIGLINEWISE WITH(NOLOCK) 
							--	   WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND @OPERATIONCODE=@FINALVIEWING_OPERATIONCODE
							--	   AND ISNULL(LABELPRINTING ,0)=1 AND ISNULL(TRACEABILITY,0)=1 AND PROFITCENTERCODE =@PROFITCENTERCODE
						 --)

						--ADDED BY THK

						select top 1 @IsPartWiseRoutingApplicable=Convert(smallint,KeyValue) from RoutingConfigDetails(nolock) 
							where ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode and STS_CD=0 and KeyType='IsPartWiseRoutingApplicable'

						IF (@IsPartWiseRoutingApplicable = 1)
						BEGIN
							exec Assy_PROC_FinalViewing @CONDITION=N'IS_Label_Printing_Required_AT_FV',
							@LineCode=@LineCode,@ProfitCenterCode=@ProfitCenterCode,@PARTNUMBER=@PARTNUMBER,
							@ReturnValue=@StrIslabel_partwise output,@ReturnInt=@IntIslabel_partwise output

							IF (ISNULL(@StrIslabel_partwise,'') = 'Y')
							BEGIN
								SET @P_LABELPRINTING=1
							END
							ELSE
							BEGIN
								SET @P_LABELPRINTING=0
							END
						END
						--END BY THK

						IF (@P_LABELPRINTING = 1)
						BEGIN

							EXEC ASSY_PROC_FINALQCSTN_LABEL_PRINTING @CONDITION='GET_LABEL_INFO_VALIDATION',@PROFITCENTERCODE=@PROFITCENTERCODE
							,@LINECODE=@LINECODE,@RFID=@BARCODE,@RETURNVALUE=@RETURNVALUE OUT

							IF @RETURNVALUE='SAME_CALIPER_SERIAL_NO_HAS_BEEN_ALREADY_GENERATED.'
							BEGIN
										SET @RETURNINT=1
										SET @RETURNVALUE='SAME_CALIPER_SERIAL_NO_HAS_BEEN_ALREADY_GENERATED.'
									--UPDATE INCORRECT LABEL
									IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
									BEGIN
										EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
										,@BARCODE=@BARCODE,@HMIMESSAGE='SAME_CALIPER_SERIAL_NO_HAS_BEEN_ALREADY_GENERATED.'
									END
										COMMIT TRAN
									RETURN
							END
							ELSE IF @RETURNVALUE='CALIPER_SERIAL_NO_HAS_NOT_BEEN_GENERATED_AT_COUPLING_STATION'
							BEGIN
										SET @RETURNINT=1
										SET @RETURNVALUE='CALIPER_SERIAL_NO_HAS_NOT_BEEN_GENERATED_AT_COUPLING_STATION'
									--UPDATE INCORRECT LABEL
									IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
									BEGIN
										EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
										,@BARCODE=@BARCODE,@HMIMESSAGE='CALIPER_SERIAL_NO_HAS_NOT_BEEN_GENERATED_AT_COUPLING_STATION.'
									END
										COMMIT TRAN
									RETURN
							END -- ADDED BY SACHIN 20170302 CHECK ALL DATA BEFORE PRINT
							ELSE IF @RETURNVALUE='PRN_FILE_DOES_NOT_EXISTS'
							BEGIN
										SET @RETURNINT=1
										SET @RETURNVALUE='PRN_FILE_DOES_NOT_EXISTS'
									--UPDATE INCORRECT LABEL
									IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
									BEGIN
										EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
										,@BARCODE=@BARCODE,@HMIMESSAGE='PRN_FILE_DOES_NOT_EXISTS.'
									END
										COMMIT TRAN
									RETURN
							END
							ELSE IF @RETURNVALUE='PRN_DATA_DOES_NOT_EXISTS'
							BEGIN
										SET @RETURNINT=1
										SET @RETURNVALUE='PRN_DATA_DOES_NOT_EXISTS'
									--UPDATE INCORRECT LABEL
									IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
									BEGIN
										EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
										,@BARCODE=@BARCODE,@HMIMESSAGE='PRN_DATA_DOES_NOT_EXISTS.'
									END
										COMMIT TRAN
									RETURN
							END

						END
					    ELSE
					    BEGIN
							DECLARE @IsCheckCaliperSerialNumber bit, @CaliperDatecode varchar(5), @CaliperSrNo int, @ProdDate date, @TotNoOfDupRecoreds int

							select top 1 @IsCheckCaliperSerialNumber=Convert(smallint,KeyValue) from RoutingConfigDetails(nolock) 
							where ProfitCenterCode=@PROFITCENTERCODE and LineCode=@LINECODE and STS_CD=0 and KeyType='IsCheckCaliperSerialNumber'
					    
							IF (@IsCheckCaliperSerialNumber = 1)
							BEGIN
								select @CaliperDatecode=CaliperDatecode,@CaliperSrNo=CaliperSrNo,@PartNo=PartNo,@ProdDate=convert(date,Timestamp)
								from dbo.Assy_LineAssyParamData_Running  with (nolock)  				
								where ProfitCenterCode=@PROFITCENTERCODE  and LineCode=@LINECODE and machinecode=@MachineCode  
								and barcode=@BARCODE -- and isnull(Result,'')='PS' 			
					    
								select @TotNoOfDupRecoreds=count(CaliperSrNo) 
								from dbo.Assy_LineAssyParamData_Running  with (nolock)  
								where ProfitCenterCode=@PROFITCENTERCODE and LineCode=@LINECODE and machinecode=@MachineCode  
								and CaliperSrNo=@CaliperSrNo -- and isnull(Result,'')='PS'						
								and convert(date, Timestamp)=@ProdDate   
								and PartNo=@PartNo
								--Check this caliper serial no. has been already generated.
					    
					    
								if isnull(@TotNoOfDupRecoreds,0)>1 
								begin
						  				SET @RETURNINT=1
										SET @RETURNVALUE='SAME_CALIPER_SERIAL_NO_HAS_BEEN_ALREADY_GENERATED.'
										--UPDATE INCORRECT LABEL
										IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
										BEGIN
											EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
											,@BARCODE=@BARCODE,@HMIMESSAGE='SAME_CALIPER_SERIAL_NO_HAS_BEEN_ALREADY_GENERATED.'
										END
										COMMIT TRAN
										RETURN
								end				
								else if exists
								(
						  				select 1 from dbo.Assy_LineAssyParamData with (nolock)  							
						  				where ProfitCenterCode=@PROFITCENTERCODE and LineCode=@LINECODE and machinecode=@MachineCode 
						  				and  CaliperSrNo=@CaliperSrNo and isnull(Result,'')='PS'						
						  				and convert(date, Timestamp)=@ProdDate  
						  				and PartNo=@PartNo						
								)
								begin
						  				SET @RETURNINT=1
										SET @RETURNVALUE='SAME_CALIPER_SERIAL_NO_HAS_BEEN_ALREADY_GENERATED.'
										--UPDATE INCORRECT LABEL
										IF @OPERATIONCODE <>@FINALVIEWING_OPERATIONCODE
										BEGIN
											EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION='UPDATE',@LINECODE=@LINECODE,@OPERATIONCODE=@OPERATIONCODE
											,@BARCODE=@BARCODE,@HMIMESSAGE='SAME_CALIPER_SERIAL_NO_HAS_BEEN_ALREADY_GENERATED.'
										END
										COMMIT TRAN
										RETURN
								end		
							END
						END

						IF @OPERATIONCODE = @FINALVIEWING_OPERATIONCODE
						Begin
							if exists(select top 1 1 from #Temp_RoboKey_bij where RoboKey in('1','2'))
							Begin
								Select @Buffer_Count=count(*) from Assy_Scan_OK_ROBO with(nolock) where PROFITCENTERCODE=@PROFITCENTERCODE 
								and Linecode=@LINECODE and isnull(isprocess ,'0') != '1'
								 
								if(@Buffer_Count < @FV_ROBO_BUFFER_COUNT)
								Begin
									Insert into  Assy_Scan_OK_ROBO(ProfitCenterCode,LineCode,MachineCode,OperationCode,WIPBufferSeq,Barcode,isScan,Timestamp)
									Select @ProfitCenterCode,@LineCode,@MACHINECODE,@OPERATIONCODE,@Buffer_Count,@barcode,'1',getdate()

									INSERT INTO ASSY_SYSTEM_SCAN_LOG(WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
									SELECT @PROFITCENTERCODE, 'ROBO_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
								End
								else
								Begin
									SET @RETURNINT=1
									SET @RETURNVALUE='SCAN_BUFFER_REACHED_FOR_ROBO_INSPECTION'

									INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
									SELECT @PROFITCENTERCODE, 'ROBO_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()
									COMMIT TRAN
									RETURN
								End
							END

							--CHECK THROUGHPUT TIME FOR MES
							--IF EXISTS (SELECT TOP 1 1 FROM ROUTINGCONFIGDETAILS(NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE
							--						AND LineCode = @LINECODE AND STS_CD = 0 AND KeyType = 'ThroughputTimeValidation')
							--BEGIN
							--	SELECT TOP 1 @ThroughputTime=KeyValue FROM ROUTINGCONFIGDETAILS(NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE
							--						AND LineCode = @LINECODE AND STS_CD = 0 AND KeyType = 'ThroughputTimeRig1'
							--	SELECT TOP 1 @FromOperationCode=KeyValue,@ThroughputPartKey=PartNumber FROM ROUTINGCONFIGDETAILS(NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE
							--						AND LineCode = @LINECODE AND STS_CD = 0 AND KeyType = 'ThroughputTimeRig1Stations' AND PartNumber=@PARTNUMBER
							--	IF(ISNULL(@FromOperationCode,'')='')
							--	BEGIN
							--		SELECT TOP 1 @FromOperationCode=KeyValue,@ThroughputPartKey=PartNumber FROM ROUTINGCONFIGDETAILS(NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE
							--			AND LineCode = @LINECODE AND STS_CD = 0 AND KeyType = 'ThroughputTimeRig1Stations' AND ISNULL(PartNumber,'')=''
							--	END

							--	SELECT top 1 @ToOperationCode=col1 FROM dbo.FN_GRID_SPLIT_STRING(@FromOperationCode,'','|') ORDER BY ROW_NO DESC
							--	SELECT top 1 @FromOperationCode=col1 FROM dbo.FN_GRID_SPLIT_STRING(@FromOperationCode,'','|') ORDER BY ROW_NO ASC

							--	--SELECT @ThroughputPartKey partno,@ThroughputTime timeinterval, @FromOperationCode fromcode, @ToOperationCode tocode

							--	SELECT TOP 1 @FIRST_TIME=ScanTimestamp FROM Assy_LineAssyStatus (NOLOCK) WHERE OperationCode=@FromOperationCode and Barcode=@BARCODE

							--	IF (DATEDIFF(MINUTE,ISNULL(@FIRST_TIME,GETDATE()),GETDATE()) > CONVERT(INT, @ThroughputTime))
							--	BEGIN
							--		SET @RETURNINT=1
							--		SET @RETURNVALUE='THROUGHPUT_TIME EXCEEDED_GENERATED_ON|||' + CONVERT(VARCHAR(100), @FIRST_TIME) 
							--						+ '|||' + CONVERT(VARCHAR, DATEDIFF(MINUTE,ISNULL(@FIRST_TIME,GETDATE()),GETDATE()))
							--	END

							--END
							SELECT @ThroughputTime = DBO.[FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE](@PROFITCENTERCODE,'LINE_ATTRB','ASSY_THROUGHPUT_MINUTES',@LINECODE,'')
							SET @ThroughputTime = ISNULL(@ThroughputTime, '0')

							IF (CONVERT(INT, @ThroughputTime) > 1)
							BEGIN
								SELECT @FromOperationCode = 'OCIG'
								SELECT TOP 1 @FIRST_TIME=ResultTimestamp FROM Assy_LineAssyStatus_running (nolock) 
								WHERE ProfitCenterCode=@PROFITCENTERCODE and LineCode=@LINECODE
								AND OperationCode=@FromOperationCode AND Barcode=@BARCODE

								IF (DATEDIFF(MINUTE,ISNULL(@FIRST_TIME,GETDATE()),GETDATE()) > CONVERT(INT, @ThroughputTime))
								BEGIN
									SET @RETURNINT=1
									SET @RETURNVALUE='THROUGHPUT_TIME EXCEEDED_GENERATED_ON|||' + CONVERT(VARCHAR(100), @FIRST_TIME) 
													+ '|||' + CONVERT(VARCHAR, DATEDIFF(MINUTE,ISNULL(@FIRST_TIME,GETDATE()),GETDATE()))
									COMMIT TRAN
									RETURN
								END
							END
						END
							

									SET @SCANNINGSTATION=1
									--IF EXISTS 
									--(
									--	SELECT TOP 1 1 FROM #TEMP_MACHINEMST WITH (NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND MACHINECODE=@MACHINECODE AND INDEXPERSTATIONS =2
									--)
									IF(@P_INDEXPERSTATIONS = 2)
									BEGIN
																						
											SELECT @STATIONCODE=STATIONCODE FROM DBO.ASSY_STATIONS_ZIG_IN_OUT_STATUS(NOLOCK) WHERE LINECODE=@LINECODE AND 
											OPERATIONCODE=@OPERATIONCODE	
											
											IF @STATIONCODE=1
												SET @SCANNINGSTATION=2
											ELSE IF  @STATIONCODE=2
												SET @SCANNINGSTATION=1
																							
											SET @STATIONCODE=@SCANNINGSTATION																			
											IF  EXISTS
											(
									SELECT DISTINCT 1 FROM DBO.ASSY_SCAN_OK(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE 
												AND OPERATIONCODE=@OPERATIONCODE AND MACHINECODE=@MACHINECODE AND STATIONCODE=@SCANNINGSTATION
											)
											BEGIN
										UPDATE ASSY_SCAN_OK SET ISSCAN=1,BARCODE=@BARCODE,ASSY_PARTNO=@PARTNUMBER,DATECODE=@DATECODE
										,CREATEDBY=@USERID,CREATEDDATE=GETDATE()
										 WHERE 
										PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND OPERATIONCODE=@OPERATIONCODE 
										AND MACHINECODE=@MACHINECODE
										AND STATIONCODE=@SCANNINGSTATION	
																				
											END
											ELSE
												BEGIN
											INSERT INTO ASSY_SCAN_OK
											(	PROFITCENTERCODE,LINECODE,OPERATIONCODE,STATIONCODE,BARCODE,ISSCAN,MACHINECODE
												,ASSY_PARTNO,DATECODE,CREATEDBY,CREATEDDATE
											)
											SELECT @PROFITCENTERCODE ,@LINECODE,@OPERATIONCODE,@SCANNINGSTATION,@BARCODE,1,@MACHINECODE	
											,@PARTNUMBER,@DATECODE,@USERID,GETDATE() 											
												END

												  --RESET   INCORRECT LABEL
												UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE='' ,ISINCORRECT=0 WHERE LINECODE=@LINECODE AND 
												OPERATIONCODE=@OPERATIONCODE

												--RESET DUPLICATE LABEL
												UPDATE ASSY_DUPLICATELABEL SET ISDUPLICATE=0 WHERE LINECODE=@LINECODE AND 
												OPERATIONCODE=@OPERATIONCODE	
									END
									ELSE IF  EXISTS
									(
									SELECT DISTINCT 1 FROM DBO.ASSY_SCAN_OK(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE 
									AND LINECODE=@LINECODE AND OPERATIONCODE=@OPERATIONCODE AND MACHINECODE=@MACHINECODE
									)
									BEGIN
								    UPDATE ASSY_SCAN_OK SET ISSCAN=1,BARCODE=@BARCODE,ASSY_PARTNO=@PARTNUMBER,DATECODE=@DATECODE
									,CREATEDBY=@USERID,CREATEDDATE=GETDATE()
									   WHERE 
										PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND OPERATIONCODE=@OPERATIONCODE 
										AND MACHINECODE=@MACHINECODE
										AND STATIONCODE=@SCANNINGSTATION	
											
										--RESET   INCORRECT LABEL
										UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE='' ,ISINCORRECT=0 WHERE LINECODE=@LINECODE AND 
										OPERATIONCODE=@OPERATIONCODE

										--RESET DUPLICATE LABEL
										UPDATE ASSY_DUPLICATELABEL SET ISDUPLICATE=0 WHERE LINECODE=@LINECODE AND 
										OPERATIONCODE=@OPERATIONCODE

										UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE SET BARCODE='',ISCYCLESTARTED=0 
										WHERE LINECODE=@LINECODE AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE	
									
									END
									ELSE
										BEGIN
									INSERT INTO ASSY_SCAN_OK
									(	PROFITCENTERCODE,LINECODE,OPERATIONCODE,STATIONCODE,BARCODE,ISSCAN,MACHINECODE
										,ASSY_PARTNO,DATECODE,CREATEDBY,CREATEDDATE
									)
									SELECT @PROFITCENTERCODE ,@LINECODE,@OPERATIONCODE,@SCANNINGSTATION,@BARCODE,1,@MACHINECODE	
									,@PARTNUMBER,@DATECODE,@USERID,GETDATE() 

												  --RESET   INCORRECT LABEL
												UPDATE ASSY_INCORRECTLABEL SET HMIMESSAGECODE='' ,ISINCORRECT=0 WHERE LINECODE=@LINECODE AND 
												OPERATIONCODE=@OPERATIONCODE

												--RESET DUPLICATE LABEL
												UPDATE ASSY_DUPLICATELABEL SET ISDUPLICATE=0 WHERE LINECODE=@LINECODE AND 
												OPERATIONCODE=@OPERATIONCODE

												UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE SET BARCODE='',ISCYCLESTARTED=0 
												WHERE LINECODE=@LINECODE AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE	
												
										END

				

			--Start//Added By Prerna On 25-Apr-2020 For WIP Count Manage For Next Shift
			DELETE FROM Assy_WIP_Pending_Part_Status WHERE ProfitCenterCode = @PROFITCENTERCODE AND LineCode = @LINECODE AND Barcode = @BARCODE AND IsPrintUpdate = 1
			--End//Added By Prerna On 25-Apr-2020 For WIP Count Manage For Next Shift
							
							IF EXISTS
							( 
								SELECT DISTINCT 1 FROM #TEMP_ASSY_LINEASSYSTATUS_RUNNING(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE 
								AND LINECODE=@LINECODE AND DATECODE=CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END AND MACHINECODE=@MACHINECODE AND 
							     OPERATIONCODE=@OPERATIONCODE  AND  BARCODE=@BARCODE 								
						    )
							BEGIN
								-- ADDED BY RASHID ON 20TH JULY 2016 FOR PERFORMANCE
								IF (@OPERATIONCODE = 'OCSVPR')
								BEGIN
								--1%%%
									UPDATE ASSY_LINEASSYSTATUS_RUNNING SET SCANTIMESTAMP =GETDATE(),STATIONCODE=@SCANNINGSTATION, RESULTTIMESTAMP = NULL,
									STATUS = NULL,Live_Datecode=@Live_Datecode
									 WHERE LINECODE=@LINECODE  AND 
									MACHINECODE=@MACHINECODE AND	OPERATIONCODE=@OPERATIONCODE  AND  BARCODE=@BARCODE 
									AND PROFITCENTERCODE=@PROFITCENTERCODE
								END
								ELSE
								BEGIN
								--1%%%
									UPDATE ASSY_LINEASSYSTATUS_RUNNING SET SCANTIMESTAMP =GETDATE(),STATIONCODE=@SCANNINGSTATION,
									Live_Datecode=@Live_Datecode
									WHERE LINECODE=@LINECODE  AND 
									MACHINECODE=@MACHINECODE AND	OPERATIONCODE=@OPERATIONCODE  AND  BARCODE=@BARCODE 
									AND PROFITCENTERCODE=@PROFITCENTERCODE
								END
							END
							ELSE
							BEGIN
										DELETE FROM ASSY_LINEASSYSTATUS_RUNNING WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE 
									AND BARCODE=@BARCODE	

									IF @STMCPARTNO<>''
											SET @PARTNUMBER=@STMCPARTNO

									--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
									INSERT INTO ASSY_LINEASSYSTATUS_RUNNING(PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,BARCODE,DATECODE,PARTNO,ACTIVE,
											STATIONCODE,SCANTIMESTAMP,USERID,PRODUCTIONORDERNO,Live_Datecode)
									SELECT @PROFITCENTERCODE,@LINECODE,@MACHINECODE,@OPERATIONCODE,@BARCODE,
										CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END,@PARTNUMBER,1,@SCANNINGSTATION,GETDATE(),@USERID,@PRODUCTIONORDERNO,@Live_Datecode
							END
							
							--UPDATE SCAN OK FOR DATE CODE STAMPING,IF STAMPING IS APPLICABLE FOR LINE AND PART NO.
							IF @OPERATIONCODE=@FINALVIEWING_OPERATIONCODE
							BEGIN
									EXEC ASSY_PROC_DATECODESTAMPING @CONDITION='UPDATE_SCANOK',@LINECODE =@LINECODE 
									,@BARCODE=@BARCODE,@PROFITCENTERCODE=@PROFITCENTERCODE		
							END

							if exists (select top 1 1 from #Temp_RoboKey_bij where RoboKey in('3') AND MachineCode=@MACHINECODE)
							begin
								--UPDATE A SET A.IsScan=1
								--FROM TD_Scan_OK_ROBO A WITH (NOLOCK) 
								--INNER JOIN ASSY_FV_ROBOT_INSPECTION_SERIAL_HOLD C WITH (NOLOCK)
								--ON A.Barcode=C.PRINTED_BARCODE
								--WHERE A.ProfitCenterCode=@PROFITCENTERCODE AND A.MachineCode=@MACHINECODE 
								--AND C.RFID=@BARCODE
								--AND ISNULL(A.IsScan,0)=0

								UPDATE TD_Scan_OK_ROBO SET isScan=1
								WHERE Barcode=@Assy_str and isnull(isScan,0)=0
								and ProfitCenterCode=@PROFITCENTERCODE and MachineCode=@MACHINECODE

								Insert into Assy_Scan_OK_ROBO (ProfitCenterCode,LineCode,MachineCode,OperationCode,WIPBufferSeq,Barcode,IsScan,Timestamp,IsProcess)
								VALUES (@PROFITCENTERCODE,@LINECODE,@MACHINECODE,@OPERATIONCODE,0,@BARCODE,1,GETDATE(),0)
							END
							
							--IF (@CRIMPINGMACHINECODE != '' AND @CRIMPINGMACHINECODE = @MACHINECODE)
							--BEGIN
							--	IF EXISTS (SELECT TOP 1 BARCODE FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK) WHERE PROFITCENTERCODE =@PROFITCENTERCODE
							--			AND LINECODE = @LINECODE AND ISNULL(ISTALLYCHARTAPPROVED,0) = 0 AND  MACHINECODE = @MACHINECODE
							--			AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END
							--			AND  ISNULL(STATUS,'') = '')
							--	BEGIN
							--		UPDATE ASSY_LINEASSYSTATUS_RUNNING SET STATUS = 'FL', FAILCOUNT = 5 
							--			WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND ISNULL(ISTALLYCHARTAPPROVED,0) = 0
							--			AND MACHINECODE = @MACHINECODE AND DATECODE = CASE @REWORK_MODE WHEN 'REWORK' THEN @REWORK_DATECODE ELSE @DATECODE END
							--			AND  ISNULL(STATUS,'') = ''
							--	END
							--END
							SET @RETURNINT=1							
							SET @RETURNVALUE='SCANNED_SUCCESSFULLY'	--MAIN,HERE,SCAN_OK
							
							IF @QTYLOWMESSAGE = 1
							BEGIN
								SET @RETURNVALUE = 'SCANNED_SUCCESSFULLY' + ' BUT ' + @MATFEEDREMARKSTATUS
							END

							COMMIT TRAN
							END TRY
							BEGIN CATCH								
							    -- 20170411 ISNULL ADDED BY SACHIN 						
							   SET @RETURNVALUE =	CAST(ISNULL(ERROR_NUMBER(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_SEVERITY(),0)AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_STATE(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_PROCEDURE(),'') AS VARCHAR(200)) + '|' + 
								CAST(ISNULL(ERROR_LINE(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_MESSAGE(),'') AS VARCHAR(1500))
							     ROLLBACK TRAN								
							   SET @RETURNINT = 2
							   RAISERROR(@RETURNVALUE,16,1)	
							END CATCH 
							
				
			RETURN

			SCAN_NOT_OK_ROBO:
			if exists (select top 1 1 from #Temp_RoboKey_bij where RoboKey in('3') AND MachineCode=@MACHINECODE)
			begin
				UPDATE TD_Scan_OK_ROBO SET isScan=2, WIPBufferSeq=0
				WHERE Barcode=@Assy_str and isnull(isScan,0)=0
				and ProfitCenterCode=@PROFITCENTERCODE and MachineCode=@MACHINECODE

				INSERT INTO Assy_Scan_OK_ROBO_history(ProfitCenterCode,LineCode,MachineCode,OperationCode,
				WIPBufferSeq,Barcode,isScan,Timestamp,isProcess,Hist_Dt)
				SELECT TOP 1 @PROFITCENTERCODE,@LINECODE,@MACHINECODE,@OPERATIONCODE,
				0,@Assy_str,2,getdate(),0,getdate()
			end
			return
		END
		ELSE IF @CONDITION = 'POKAYOKE_FAULTBARCODE_SCANNING'
		BEGIN	
			DECLARE @EXPRESULT VARCHAR(10)	
			DECLARE @ISTESTCOMPLETED VARCHAR(20)
			
			SELECT @POKAYOKEDATECODE = DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'POKAYOKE', 'POKAYOKE_DATECODE', @PROFITCENTERCODE)

			--ADDED BY RASHID FOR POKAYOKE TWIN INDEX
			DECLARE @SCANNEDSTATIONINDEX INT = 0
			SET @SCANNEDSTATIONINDEX = (SELECT DBO.ASSY_FNGETSCANNEDSTATIONINDEX(@LINECODE, @OPERATIONCODE))

			IF(@SCANNEDSTATIONINDEX = -1)
			BEGIN
				IF NOT EXISTS
				(
				SELECT 1 FROM ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE WITH (NOLOCK) WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE
				)
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'NO_PENDING_RECORD_FOR_DECLARING_AS_FAULT'	
					
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'NO_PENDING_RECORD_FOR_DECLARING_AS_FAULT'
					RETURN
				END
				
				--CHECK IF CYCLE START HAS NOT PRESSED, SIMPLY RETURN
				ELSE IF EXISTS
				(
					SELECT 1 FROM ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE WITH (NOLOCK) WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE 
						AND OPERATIONCODE = @OPERATIONCODE AND (ISNULL(BARCODE, '') = '' OR CHARINDEX(@POKAYOKEDATECODE, ISNULL(BARCODE, '')) = 0 OR ISNULL(ISCYCLESTARTED, 0) = 0)
				)
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'YOU_CANT_DECLARE_A_PART_AS_FAULT_BECAUSE_TESTING_NOT_START'					
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'YOU_CANT_DECLARE_A_PART_AS_FAULT_BECAUSE_TESTING_NOT_START'
					RETURN
				END
			END
			ELSE
			BEGIN
				DECLARE @INSIDESTATIONINDEX INT;
				IF(@SCANNEDSTATIONINDEX = 1)
					SET @INSIDESTATIONINDEX = 2
				ELSE IF(@SCANNEDSTATIONINDEX = 2)
					SET @INSIDESTATIONINDEX = 1
					
				IF NOT EXISTS
				(
					SELECT 1 FROM ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE WITH (NOLOCK) 
						WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND STATIONCODE = @INSIDESTATIONINDEX
				)
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'NO_PENDING_RECORD_FOR_DECLARING_AS_FAULT'

					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'NO_PENDING_RECORD_FOR_DECLARING_AS_FAULT'
					RETURN
				END
				
				--CHECK IF CYCLE START HAS NOT PRESSED, SIMPLY RETURN
				ELSE IF EXISTS
				(
					SELECT 1 FROM ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE WITH (NOLOCK) WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE 
						AND OPERATIONCODE = @OPERATIONCODE AND STATIONCODE = @INSIDESTATIONINDEX
							AND (ISNULL(BARCODE, '') = '' OR CHARINDEX(@POKAYOKEDATECODE, ISNULL(BARCODE, '')) = 0 OR ISNULL(ISCYCLESTARTED, 0) = 0)
				)
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'YOU_CANT_DECLARE_A_PART_AS_FAULT_BECAUSE_TESTING_NOT_START.'	
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'YOU_CANT_DECLARE_A_PART_AS_FAULT_BECAUSE_TESTING_NOT_START'
					RETURN
				END
			END
				
			--IF IT IS A SINGLE JIG STATION
			IF(@SCANNEDSTATIONINDEX = -1)
			BEGIN
				IF EXISTS
				(
					SELECT  1 FROM ASSY_STATIONS_ZIG_IN_OUT_STATUS WITH (NOLOCK) WHERE LINECODE = @LINECODE  AND OPERATIONCODE = @OPERATIONCODE AND ISNULL(STATUSINOUT, 0) = 1
				)
				BEGIN
					SELECT @RETURNINT = 1, @RETURNVALUE = 'YOU_CANT_DECLARE_A_PART_AS_FAULT_BECAUSE_JIG_IS_IN'
					EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
					, @BARCODE = @BARCODE, @HMIMESSAGE = 'YOU_CANT_DECLARE_A_PART_AS_FAULT_BECAUSE_JIG_IS_IN'
					RETURN
				END
			END

			SELECT @BARCODE = S.BARCODE FROM ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE S WITH (NOLOCK) JOIN ASSY_LINEASSYSTATUS_RUNNING A WITH (NOLOCK) 
				ON S.LINECODE = A.LINECODE AND S.MACHINECODE = A.MACHINECODE AND S.OPERATIONCODE = A.OPERATIONCODE AND S.BARCODE = A.BARCODE 
					WHERE S.LINECODE = @LINECODE AND S.MACHINECODE = @MACHINECODE 
						AND S.OPERATIONCODE = @OPERATIONCODE AND ISNULL(A.STATUS, '') = ''
			--IF SCANNED BARCODE EXPECTED  RESULT IS NOT  FAIL RETURN

			SELECT @EXPRESULT = ISNULL(EXPRESULT, '') FROM ASSY_POKAYOKE WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE  
				AND MACHINECODE = @MACHINECODE	AND ISNULL(ISACTIVE, 0) = 1 AND BARCODE = @BARCODE

			IF @EXPRESULT = 'PASS'
			BEGIN
				SELECT @RETURNINT = 1, @RETURNVALUE = 'YOU_CANT_DECLARE_A_PART_AS_FAULT_BECAUSE_EXP_RESULT_IS_PASS'
				EXEC ASSY_PROC_INCORRECTLABEL_MANAGE @CONDITION = 'UPDATE', @LINECODE = @LINECODE, @OPERATIONCODE = @OPERATIONCODE
				, @BARCODE = @BARCODE, @HMIMESSAGE = 'YOU_CANT_DECLARE_A_PART_AS_FAULT_BECAUSE_EXP_RESULT_IS_PASS'
				RETURN
			END
			ELSE IF @EXPRESULT = 'FAIL'
			BEGIN
				EXEC [ASSY_PROC_UPDATEPOKAYOKESTATUS] @CONDITION = 'UPDATE_POKA_YOKE_RESULT', @PROFITCENTERCODE = @PROFITCENTERCODE, @LINECODE = @LINECODE
				, @OPERATIONCODE = @OPERATIONCODE, @MACHINECODE = @MACHINECODE, @PLCRESULT = 'FAULT', @BARCODE = @BARCODE, @USERID = @USERID, @ISFAULTBARCODESCANNED = 1						
						
				IF @SCANNEDSTATIONINDEX = -1
				BEGIN
					UPDATE ASSY_SCAN_OK SET	BARCODE = '' WHERE LINECODE = @LINECODE
					AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE
					
					UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE SET BARCODE = '', ISCYCLESTARTED = 0 
						WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE
				END
				ELSE
				BEGIN
					UPDATE ASSY_SCAN_OK SET	BARCODE = '' WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE
						AND STATIONCODE = @INSIDESTATIONINDEX
					
					UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE SET BARCODE = '', ISCYCLESTARTED = 0 
						WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE	AND STATIONCODE = @INSIDESTATIONINDEX
				END

				SELECT @RETURNINT = 1, @RETURNVALUE = 'PART_HAS_BEEN_SUCCESSFULLY_DECLARED_AS_FAULT'
			END
			ELSE IF @EXPRESULT = 'FAULT'				
			BEGIN
				EXEC [ASSY_PROC_UPDATEPOKAYOKESTATUS] @CONDITION = 'UPDATE_POKA_YOKE_COMPELETE_FOR_FAULT_PART', @PROFITCENTERCODE = @PROFITCENTERCODE
				, @LINECODE = @LINECODE, @MACHINECODE = @MACHINECODE, @OPERATIONCODE = @OPERATIONCODE, @BARCODE = @BARCODE, @ISTESTCOMPLETED = @ISTESTCOMPLETED OUT											
				
				IF @ISTESTCOMPLETED = 'NO'
				BEGIN											
					UPDATE ASSY_RESULT SET BARCODE = @BARCODE WHERE OPERATIONCODE = @OPERATIONCODE
							
					IF @SCANNEDSTATIONINDEX = -1
					BEGIN
						UPDATE ASSY_SCAN_OK SET BARCODE = '' WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE
							AND OPERATIONCODE = @OPERATIONCODE
						UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE SET BARCODE = '', ISCYCLESTARTED = 0 
							WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE
					END
					ELSE
					BEGIN
						UPDATE ASSY_SCAN_OK SET BARCODE = '' WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE
							AND OPERATIONCODE = @OPERATIONCODE AND STATIONCODE = @INSIDESTATIONINDEX
						UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE SET BARCODE = '', ISCYCLESTARTED = 0 
							WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND STATIONCODE = @INSIDESTATIONINDEX
					END
				END

				SELECT @RETURNINT = 1, @RETURNVALUE = 'PART_HAS_BEEN_SUCCESSFULLY_DECLARED_AS_FAULT'	
			END
		END

		ELSE IF @CONDITION = 'GET_TAGS'
		BEGIN		  
					--SHOW VISION SYSTEM LAST PRINTED BARODE
					SET @FV_OP_CODE = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE)

					SELECT TOP 1 @OPERATIONSEQNO=L.OPERATIONSEQNO  FROM DBO.ROUTINGCONFIGLINEWISE(NOLOCK) L
					WHERE L.PROFITCENTERCODE=@PROFITCENTERCODE AND  L.LINECODE  =@LINECODE							
					AND ISNULL(L.TRACEABILITY,0) =1
					AND ISNULL(L.OPERATIONREQUIRED,0) =1							
					AND L.OPERATIONCODE=@OPERATIONCODE 
										
					IF @OPERATIONSEQNO=1 
					BEGIN	
					       
						    SELECT @OPERATIONNAME=OPERATIONNAME FROM  DBO.OPERATIONMST(NOLOCK) 
							WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND OPERATIONCODE=@OPERATIONCODE 
							AND ISACTIVE =1
							
							SELECT TOP 1 @OPERATIONNAME AS OPERATIONNAME ,LPB.BARCODE,'' AS TAGNAME,'' AS VALUE,'PASS' AS RESULT ,'' AS UOM   FROM 
							DBO.ASSY_VISION_SYSTEM_LAST_PRINTED_BARCODE(NOLOCK)LPB 							
								RETURN
					END

				IF @OPERATIONCODE= @FV_OP_CODE
				BEGIN
						SELECT TOP 1  OPMST.OPERATIONNAME ,ASSY.BARCODE,''TAGNAME,ASSY.VALUE
						,CASE WHEN ISNULL(ASSY.RESULT,'')='PS' THEN 'PASS' WHEN ISNULL(ASSY.RESULT,'')='FL' THEN 'FAIL' END RESULT
					 ,''UOM   FROM 
						 (									
							SELECT PROFITCENTERCODE,LINECODE, OPERATIONCODE,BARCODE,'' AS TAGNAME,'' AS VALUE,TIMESTAMP,RESULT  
							FROM DBO.ASSY_LINEASSYPARAMDATA_RUNNING(NOLOCK)
							WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND OPERATIONCODE =@OPERATIONCODE
						)ASSY							
						INNER JOIN DBO.OPERATIONMST(NOLOCK)OPMST 
							ON ASSY.PROFITCENTERCODE=OPMST.PROFITCENTERCODE   
							AND  ASSY.OPERATIONCODE =OPMST.OPERATIONCODE 
					ORDER BY TIMESTAMP DESC
					RETURN
				END
				
				SELECT TOP 1 @BARCODE=BARCODE,@STATUS=RESULT FROM  ASSY_LINEASSYPARAMDATA_RUNNING A WITH(NOLOCK) WHERE A.PROFITCENTERCODE=@PROFITCENTERCODE 
					 AND A.LINECODE=@LINECODE AND A.OPERATIONCODE =@OPERATIONCODE ORDER BY TIMESTAMP DESC

				SELECT OPMST.OPERATIONNAME ,ASSY.BARCODE,TAG.TAGDESCRIPTION TAGNAME,ASSY.VALUE
				,CASE WHEN ISNULL(ASSY.RESULT,'')='PS' THEN 'PASS' WHEN ISNULL(ASSY.RESULT,'')='FL' THEN 'FAIL' END RESULT ,ISNULL( TAG.UOM,'')UOM   FROM 
				(
					SELECT A.PROFITCENTERCODE,A.LINECODE, A.OPERATIONCODE,A.BARCODE,B.TAGID,B.VALUE,A.TIMESTAMP,A.RESULT  
					FROM DBO.ASSY_LINEASSYPARAMDATA_RUNNING A WITH(NOLOCK)
					INNER JOIN DBO.ASSY_LINEASSYPARAMDATA_RUNNING_DTL B WITH(NOLOCK) ON A.UID=B.UID
					WHERE A.PROFITCENTERCODE=@PROFITCENTERCODE AND A.LINECODE=@LINECODE AND A.OPERATIONCODE =@OPERATIONCODE
					 AND BARCODE =@BARCODE AND RESULT=@STATUS

				)ASSY
				JOIN TAGMST(NOLOCK) TAG ON ASSY.TAGID=TAG.TAGID AND TAG.ISACTIVE=1 
				INNER JOIN OPERATIONMST(NOLOCK)OPMST ON ASSY.PROFITCENTERCODE =OPMST.PROFITCENTERCODE  AND ASSY.OPERATIONCODE =OPMST.OPERATIONCODE 
				ORDER BY TIMESTAMP DESC						
				RETURN
		END
		IF @CONDITION='GET_PLCADDRESS'
		BEGIN
			SET @FV_OP_CODE = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)
				

				SELECT @FIRSTSTATIONCODE = OPERATIONCODE FROM ROUTINGCONFIGLINEWISE (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
													AND LINECODE = @LINECODE AND OPERATIONSEQNO = 1 AND TRACEABILITY = 1

						SELECT R.PROFITCENTERCODE,R.LINECODE,O.OPERATIONNAME,O.OPERATIONCODE,STATIONCODE,R.MACHINECODE,MACH.MACHINENAME ,MACH.PLCADDRESS FROM
						(
							SELECT L.PROFITCENTERCODE,L.LINECODE , L.OPERATIONCODE,L.OPERATIONSEQNO,P.PARTNO,MD.STATIONCODE,P.MACHINECODE   FROM ROUTINGCONFIGLINEWISE(NOLOCK) L 
							INNER JOIN ROUTINGCONFIGPARTWISE(NOLOCK) P 
								ON L.PROFITCENTERCODE=P.PROFITCENTERCODE AND L.OPERATIONCODE =P.OPERATIONCODE   AND L.MACHINECODE=P.MACHINECODE
							INNER JOIN MACHINEDTL MD ON L.OPERATIONCODE=MD.OPERATIONCODE AND L.LINECODE=MD.LINECODE 	
								WHERE L.PROFITCENTERCODE=@PROFITCENTERCODE  AND L.LINECODE =@LINECODE  
								AND P.PARTNO=(SELECT TOP 1 ASSY_PARTNO  FROM ASSY_RUNNINGPART(NOLOCK) WHERE LINECODE = @LINECODE ORDER BY CREATEDDATE DESC ) 
								AND	L.TRACEABILITY =1								
								AND P.TRACEABILITY =1
												
						)R
					INNER JOIN OPERATIONMST (NOLOCK) O ON O.PROFITCENTERCODE=R.PROFITCENTERCODE  AND O.OPERATIONCODE  =R.OPERATIONCODE 
					LEFT OUTER JOIN MACHINEMST (NOLOCK) MACH ON  MACH.PROFITCENTERCODE=R.PROFITCENTERCODE AND  MACH.MACHINECODE = R.MACHINECODE
					WHERE O.OPERATIONCODE NOT IN (@FIRSTSTATIONCODE,@FV_OP_CODE)
					ORDER BY R.OPERATIONSEQNO 

					SET @RETURNINT=1
					SET @RETURNVALUE='SUCCESS' 	
					RETURN
		END
		ELSE IF @CONDITION = 'GET_SHOWRESULT_DATA'
		BEGIN				
			SELECT RES.LINECODE, RES.OPERATIONCODE, RUN.MACHINECODE, ''STATIONCODE, RUN.BARCODE, RUN.STATUS    FROM ASSY_RESULT (NOLOCK) RES				
				INNER JOIN ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) RUN ON RES.LINECODE = RUN.LINECODE AND	RES.OPERATIONCODE = RUN.OPERATIONCODE 
					AND RES.BARCODE = RUN.BARCODE 
						WHERE  ISNULL(RES.BARCODE, '') <> '' AND (ISNULL(RUN.STATUS, '') <> '' OR CHARINDEX('PKYK', RUN.BARCODE) > 0) 				
			UNION
			SELECT  LINECODE, OPERATIONCODE, '' MACHINECODE, STATIONCODE, BARCODE, '' STATUS FROM ASSY_RESULT (NOLOCK) RES	WHERE  STATIONCODE = 'PKYK'
			
			UPDATE ASSY_RESULT SET BARCODE = '', STATIONCODE = '' WHERE  ISNULL(BARCODE, '') <> '' OR ISNULL(STATIONCODE, '') = 'PKYK'
			
			SELECT @RETURNINT = 1, @RETURNVALUE = 'SUCCESS' 
			RETURN
		END
		ELSE IF @CONDITION = 'GETPARAMETERS'
		BEGIN
			SELECT RTRIM(LTRIM( PARAMETER_C1)) PARAMETER_C1, RTRIM(LTRIM( PARAMETER_C2)) PARAMETER_C2, RTRIM(LTRIM (PARAMETER_NM)) PARAMETER_NM, LTRIM(RTRIM(PARAMETER_VALUE)) PARAMETER_VALUE 
			FROM PARAMETER_MST (NOLOCK) WHERE PARAMETER_C = 'ASSLINE' AND WH_CODE = @PROFITCENTERCODE

			SELECT @RETURNVALUE = 'DATA SELECTED', @RETURNINT = 1
			RETURN
		END
		ELSE IF @CONDITION = 'STATION_ORDERS'
		BEGIN
			-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
			SELECT @ASSY_PARTNO = ASSY_PARTNO  FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE; --AND PROFITCENTERCODE = @PROFITCENTERCODE
					
			SELECT O.OPERATIONCODE, R.OPERATIONSEQNO, O.OPERATIONNAME FROM 
			(			
				SELECT L.LINECODE, L.OPERATIONCODE, L.OPERATIONSEQNO, P.PARTNO  FROM ROUTINGCONFIGLINEWISE (NOLOCK) L 
				INNER JOIN ROUTINGCONFIGPARTWISE (NOLOCK) P 
				ON L.PROFITCENTERCODE = P.PROFITCENTERCODE AND L.OPERATIONCODE = P.OPERATIONCODE AND L.MACHINECODE = P.MACHINECODE
				WHERE L.LINECODE = @LINECODE AND
				L.OPERATIONREQUIRED = 1 AND L.TRACEABILITY = 1
				AND P.OPERATIONREQUIRED = 1 AND P.TRACEABILITY = 1
				-- ADDED BY RASHID FOR HANDLING ENGRAVING STATION ON 10TH SEP 2016
				AND ISNULL(L.ENGRAVING, 0) = 0 AND ISNULL(P.ENGRAVING, 0) = 0
				-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
				-- AND P.PARTNO = (SELECT TOP 1 ASSY_PARTNO FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE LINECODE = @LINECODE AND ASSY_MODE IN ('PRODUCTION', 'REWORK') ORDER BY CREATEDDATE DESC)
				AND P.PARTNO = @ASSY_PARTNO
			) R
			INNER JOIN OPERATIONMST (NOLOCK) O ON O.OPERATIONCODE = R.OPERATIONCODE  
			ORDER BY R.OPERATIONSEQNO
			
			SELECT @RETURNINT = 1, @RETURNVALUE = 'SUCCESS'
			RETURN
		END
		
		ELSE IF @CONDITION = 'GET_ACTIVE_STATION'
		BEGIN				
			       WITH  R(PROFITCENTERCODE,LINECODE,OPERATIONCODE,OPERATIONSEQNO,PARTNO,STATIONCODE)
				   AS
				   (
						SELECT L.PROFITCENTERCODE,L.LINECODE , L.OPERATIONCODE,L.OPERATIONSEQNO,P.PARTNO,'' AS STATIONCODE   FROM DBO.ROUTINGCONFIGLINEWISE(NOLOCK) L 
						INNER JOIN DBO.ROUTINGCONFIGPARTWISE(NOLOCK) P 
							ON L.PROFITCENTERCODE=P.PROFITCENTERCODE AND L.OPERATIONCODE =P.OPERATIONCODE   AND L.MACHINECODE  =P.MACHINECODE						
						WHERE L.PROFITCENTERCODE=@PROFITCENTERCODE AND L.LINECODE =@LINECODE 
						AND P.PARTNO=(SELECT TOP 1 ASSY_PARTNO FROM DBO.ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE
						             AND LINECODE =@LINECODE ORDER BY CREATEDDATE DESC)
						AND L.TRACEABILITY =1
						AND P.TRACEABILITY =1
						
				  )				
				SELECT LINECODE,O.OPERATIONNAME,OPERATIONSEQNO,PARTNO,O.OPERATIONCODE,STATIONCODE FROM R WITH (NOLOCK) 
				INNER JOIN OPERATIONMST (NOLOCK) O ON  O.PROFITCENTERCODE=R.PROFITCENTERCODE AND O.OPERATIONCODE  =R.OPERATIONCODE  				
				ORDER BY R.OPERATIONSEQNO 
				SET @RETURNINT=1
				SET @RETURNVALUE='SUCCESS'
				RETURN
		END
		ELSE IF @CONDITION = 'GET_MACHINE_DTL'
		BEGIN
			SELECT LINECODE, MACHINECODE, OPERATIONCODE, STATIONCODE   FROM MACHINEDTL (NOLOCK) WHERE PREFIX = @PREFIX AND SUFFIX = @SUFFIX
				AND LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE

			SELECT @RETURNINT = 1, @RETURNVALUE = 'SUCCESS'
			RETURN
		END
		ELSE IF @CONDITION = 'GET_CONTROLLER_PORT_NAME'		
		BEGIN
			SELECT @RETURNVALUE = DBO.ASSY_FN_GET_COMPORT_NAME(@PROFITCENTERCODE, @LINECODE, @OPERATIONCODE, 'CONTROLLER', 'SERIALPORT')
			SET @RETURNINT = 1			     							
			RETURN
		END

		ELSE IF @CONDITION = 'GET_FV_BT_SCANNER_PORT_NAME'		
		BEGIN
			SELECT @RETURNVALUE = DBO.ASSY_FN_GET_COMPORT_NAME(@PROFITCENTERCODE, @LINECODE, @OPERATIONCODE, 'FINALVIEWINGBLUETOOTHSCANNER', 'SERIALPORT')
			SET @RETURNINT = 1
		RETURN
		END

		ELSE IF @CONDITION = 'GET_FV_RS232_SCANNER_PORT_NAME'		
		BEGIN
			SELECT @RETURNVALUE = DBO.ASSY_FN_GET_COMPORT_NAME(@PROFITCENTERCODE, @LINECODE, @OPERATIONCODE, 'FINALVIEWINGRS232SCANNER', 'SERIALPORT')
			
			SET @RETURNINT = 1			  
			RETURN
		END
		 --ADDED BY RAVI ON 18-05-16
		 IF @CONDITION='GET_FV_RFID_READER_PORT_NAME'		
		 BEGIN
				SELECT @RETURNVALUE=DBO.ASSY_FN_GET_COMPORT_NAME(@PROFITCENTERCODE,@LINECODE,@OPERATIONCODE ,'RFIDREADER','')
				SET @RETURNINT=1			  
				 RETURN
		 END
		ELSE IF @CONDITION = 'CHECK_HARDWARE_PUSHBUTTON_ENABLED'		
		BEGIN
			SELECT @RETURNVALUE = CONVERT(VARCHAR(50), ISNULL(FINALVIEWINGHWPUSHBUTTON, 0)) FROM ROUTINGCONFIGLINEWISE (NOLOCK) 
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND TRACEABILITY = 1
			
			SET @RETURNINT = 1
			RETURN
		END
		
		ELSE IF @CONDITION = 'MACHINEDTL'		
		BEGIN
			SELECT MACHINECODE, OPERATIONCODE, PREFIX, SUFFIX FROM MACHINEDTL (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
				AND(ISNULL(PREFIX, '') <> '' AND ISNULL(SUFFIX, '') <> '')
					ORDER BY MACHINECODE, OPERATIONCODE 
			
			SELECT @RETURNINT = 1, @RETURNVALUE = 'SUCCESS'
			RETURN
		END
		IF @CONDITION='UPDATE_FINALVIEWING_PASS_STATUS'		
		BEGIN
			BEGIN TRY
				BEGIN TRAN
				
						DECLARE @mydate datetime = getdate()
						print convert(vaRCHAR,@mydate,121)
						print '----1------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
						set @mydate = getdate()
					
						

						IF CHARINDEX(':',@BARCODE)<> 0 AND ISNULL(@BARCODE,'')<>'' 
						BEGIN
								SET @ISSTMC = 1
								SELECT DISTINCT @LINECODE_STMC =  ISNULL(LINECODE, '') , @DATECODE_TEMP = ISNULL(DATECODE, '')  FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK) 
								WHERE  PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE=@LINECODE AND MACHINECODE =@MACHINECODE  AND BARCODE = @BARCODE  
								SET @DATECODE = @DATECODE_TEMP
								IF(@LINECODE_STMC)<>''
								BEGIN
										SELECT DISTINCT @PARTNUMBER=ISNULL(STMC_PART_NO, ''),@DATECODE=DATECODE FROM DBO.ASSY_COUPLINGDETAILS(NOLOCK)
										 WHERE PROFITCENTRECODE=@PROFITCENTERCODE  AND LINECODE = @LINECODE AND FG_BARCODE = @BARCODE
								END
								ELSE
									BEGIN
										SELECT DISTINCT @PARTNUMBER=ISNULL(STMC_PART_NO, ''),@LINECODE_STMC=LINECODE,@DATECODE=DATECODE FROM DBO.ASSY_COUPLINGDETAILS(NOLOCK) 
										WHERE PROFITCENTRECODE=@PROFITCENTERCODE  AND LINECODE = @LINECODE AND FG_BARCODE = @BARCODE
									END							  
						END		
						ELSE IF @ISSTMC = 0 AND ISNULL(@BARCODE,'')<>'' 
						BEGIN
								--GET DATECODE AND PART NO OF SNANNED BARCODE FROM VISION SYSTEM
								SELECT @PARTNUMBER=PARTNO,@DATECODETEMP=DATECODE FROM DBO.ASSY_FN_GET_BARCODEPARTS_FROM_BARCODE(@PROFITCENTERCODE,@LINECODE,@BARCODE)							
								SET @DATECODE=@DATECODETEMP
						END
		print '----2------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()

					--added by sachin 22-May-2020					
					select top 1 @ProductionOrderNo=ProductionOrderNo,@PARTNUMBER=PartNo,@DATECODE=Datecode 
					from Assy_lineAssyStatus_running(nolock) 
					where ProfitCenterCode=@PROFITCENTERCODE and LineCode=@LINECODE
					and barcode=@BARCODE and machineCode='MCIG'
					order by ScanTimestamp desc 	
					--ended by sachin 22-May-2020

					-- Added on 22Dec2020
					IF ISNULL(@DATECODE,'') = '' OR ISNULL(@PARTNUMBER,'')='' OR  ISNULL(@ProductionOrderNo,'')=''
					BEGIN
						SELECT @RETURNINT = 2, @RETURNVALUE = 'Date Code Empty. Re-run the process. ' 
						+ ISNULL(@DATECODE,'') + '-' + ISNULL(@PARTNUMBER,'') + '-' + ISNULL(@ProductionOrderNo,'')
						+ '-' + ISNULL(@BARCODE,'')
						ROLLBACK TRAN
						RETURN
					END

					-- Ended on 22Dec2020
					DECLARE @QTY int
					SELECT @QTY =  COUNT(1), @Kanban_Id = ISNULL(Kanban_Id, '') FROM Assy_Passed_Items_At_FV WITH (NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode 
					AND PartNo=ISNULL(@PARTNUMBER,'') -- Added By Sachin 2020May25
					AND ISNULL(Is_Posted,0) = 0 Group By Kanban_Id, PartNo			
					if(isnull(@Qty,0) =0)
					begin
						SELECT top 1 @Kanban_Id = ISNULL(KanbanId, '') FROM Assy_runningkanban WITH (NOLOCK)
						WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode 
						AND PartNo=ISNULL(@PARTNUMBER,'') -- Added By Sachin 2020May25
						And ISNULL(Iscompleted,0) = 0
						order by sequenceid asc
					end


		print '----3------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()
					SELECT @FAILCOUNT=ISNULL(FAILCOUNT,0)  FROM DBO.ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE BARCODE=@BARCODE 
					AND LINECODE=@LINECODE  
					AND	MACHINECODE=@MACHINECODE 
					AND STATUS ='FL'	
		print '----4------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()
					UPDATE ASSY_LINEASSYSTATUS_RUNNING SET STATUS='PS',RESULTTIMESTAMP =GETDATE(),Live_Datecode=@Live_Datecode
					WHERE LINECODE=@LINECODE AND PROFITCENTERCODE=@PROFITCENTERCODE AND MACHINECODE =@MACHINECODE 
					AND OPERATIONCODE=@OPERATIONCODE AND BARCODE=@BARCODE						
					--CLEAR SCAN OK BARCODE FROM ASSY_SCANOK
					 UPDATE ASSY_SCAN_OK SET BARCODE ='',ISSCAN=0  WHERE LINECODE =@LINECODE AND MACHINECODE =@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE
					
					if exists(select top 1 1 from #Temp_RoboKey_bij where RoboKey in('1'))
					Begin
					Delete from Assy_Scan_OK_ROBO where barcode=@BARCODE AND LINECODE =@LINECODE AND MACHINECODE =@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE
					END
					 select top 1 @TallyChartWithPartFamily=Convert(smallint,KeyValue) from RoutingConfigDetails(nolock) 
					where ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode and STS_CD=0 and KeyType='TallyChartWithPartFamily'

					 if exists(select top 1 1 from LineMst(nolock) where LineCode=@LINECODE 
					 and Allow2Parts=1 and ProfitCenterCode = @PROFITCENTERCODE)
					 begin
							IF(@TallyChartWithPartFamily = 1)
							BEGIN
								set @IsTallyChartApproved = 0
							END
							ELSE
							BEGIN
								set @IsTallyChartApproved = 1
							END
							set @IsAllow2Part_ = 1
					 end
					 else
					 begin
							set @IsTallyChartApproved = 0
							set @IsAllow2Part_ = 0
					 end

					 if exists(select top 1 1 from RoutingConfigLineWise(nolock)  where LineCode=@LINECODE 
					 and LabelPrinting=1 and ProfitCenterCode = @PROFITCENTERCODE and MachineCode=@MACHINECODE)
					 begin
							set @IsLabelPrintingEnabled = 1
					 end
					 else
					 begin
							set @IsLabelPrintingEnabled = 0
					 end

					 select top 1 @IsPartWiseRoutingApplicable=Convert(smallint,KeyValue) from RoutingConfigDetails(nolock) 
							where ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode and STS_CD=0 and KeyType='IsPartWiseRoutingApplicable'

						IF (@IsPartWiseRoutingApplicable = 1)
						BEGIN
							exec Assy_PROC_FinalViewing @CONDITION=N'IS_Label_Printing_Required_AT_FV',
							@LineCode=@LineCode,@ProfitCenterCode=@ProfitCenterCode,@PARTNUMBER=@PARTNUMBER,
							@ReturnValue=@StrIslabel_partwise output,@ReturnInt=@IntIslabel_partwise output

							IF (ISNULL(@StrIslabel_partwise,'') = 'Y')
							BEGIN
								set @IsLabelPrintingEnabled = 1
							END
							ELSE
							BEGIN
								set @IsLabelPrintingEnabled = 0
							END
						END


		print '----5------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()

					if exists(select top 1 1 from #Temp_RoboKey_bij where RoboKey in('2'))
					Begin				
					Begin Try
						Select @QR_CODE =PRINTED_BARCODE from ASSY_FV_ROBOT_INSPECTION_SERIAL_HOLD where PARTNO=@PARTNUMBER AND RFID=@BARCODE 
						SELECT top 1 P1,P2,P3,P4,P5,P6,P7,P8,P9,P10,P11,P12,P13,P14,P15,P16,P17,P18,P19,P20,P21,P22,P23,P24,P25,P26 INTO #ROBO_PARAMETER_DATA_PASS
						FROM TD_ROBO_DATA_WITH_PARAMETER WITH(NOLOCK)
						WHERE  QR_CODE=@QR_CODE AND TS_FLAG='0' order by RESULT_TIMESTAMP desc

						SET @XmldataLK  = (SELECT * FROM  #ROBO_PARAMETER_DATA_PASS FOR XML PATH('') )   
				
						--Dynamic unpivoting 
						insert into @TagData(TagName,TagValue)
						SELECT TagName,TagValue FROM  ( 
						SELECT 
						ROW_NUMBER()OVER(PARTITION BY   TagName ORDER BY  TagValue) rn,* FROM ( 
						SELECT  i.value('local-name(.)','VARCHAR(100)')  TagName,
						i.value('.','VARCHAR(100)') TagValue 
						FROM @xmldataLK.nodes('//*') x(i) ) tmp ) tmp1
											
						INSERT INTO @ParameterData(
						ProfitCenterCode,LineCode,MachineCode,
						OperationCode,StationCode,Barcode,TagName,Value,Result,Datecode,UserID)
						select @PROFITCENTERCODE,@LINECODE,@MACHINECODE,
						@OPERATIONCODE,'1',@Barcode,TagName,TagValue,'PS','',@USERID 
						from @TagData
								
						exec Assy_Proc_PLCIntegration_Jhagadia @Operation = 'INSERT_PLC_PARAMS',@LineCode = @LINECODE,
						@tblParameters = @ParameterData,@UpdateDataMannual=1

						Delete TD_ROBO_DATA_WITH_PARAMETER where QR_CODE=@QR_CODE 
						Delete from Assy_Scan_OK_ROBO where barcode=@BARCODE

					END TRY
					BEGIN CATCH
			
								SET @RETURNVALUE =	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
								CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
								CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
								CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
								CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
								CAST(ERROR_MESSAGE() AS VARCHAR(1500))
			
								ROLLBACK TRAN				
								SET @RETURNINT = 2
								RAISERROR(@RETURNVALUE,16,1)	
								RETURN
					END CATCH
					End
					else
					Begin
						INSERT INTO ASSY_LINEASSYPARAMDATA_RUNNING
						(
						PROFITCENTERCODE
						,LINECODE
						,MACHINECODE
						,OPERATIONCODE
						,STATIONCODE
						,BARCODE					
						,RESULT
						,DATECODE
						,PARTNO
						,USERID
						,TIMESTAMP
						,LIVE_DATECODE
						)
						SELECT 
						@PROFITCENTERCODE 
						,@LINECODE 
						,@MACHINECODE 
						,@OPERATIONCODE
						,@STATIONCODE
						,@BARCODE					
						,'PS'
						,@DATECODE
						,@PARTNUMBER
						,@USERID 
						,GETDATE()
						,@LIVE_DATECODE
					END
					IF(@ISSTMC = 0)
					BEGIN
					--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
					INSERT INTO ASSY_LINEASSYSTATUS
					(
					PROFITCENTERCODE,
					LINECODE,
					MACHINECODE,
					OPERATIONCODE,
					STATIONCODE,
					BARCODE,
					STATUS,
					FAILCOUNT,
					DATECODE,
					PARTNO,
					SCANTIMESTAMP,
					RESULTTIMESTAMP,
					USERID,
					PRODUCTIONORDERNO,
					Live_Datecode,
					IsTallyChartApproved,
					Kanban_ID
					)
					SELECT 
					PROFITCENTERCODE,
					LINECODE,
					MACHINECODE,
					OPERATIONCODE,
					STATIONCODE,
					BARCODE,
					STATUS,
					FAILCOUNT,
					DATECODE,
					PARTNO,
					SCANTIMESTAMP,
					RESULTTIMESTAMP,
					USERID,
					PRODUCTIONORDERNO,
					Live_Datecode,
					@IsTallyChartApproved,
					ISNULL(@Kanban_Id,'')
					FROM
					ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
					WHERE LINECODE=@LINECODE AND PROFITCENTERCODE=@PROFITCENTERCODE
					AND BARCODE=@BARCODE	

					--ADDED BY MANU FOR PUSHING FV  PASS DATA TO TARGET TABLE:- 'Target_data' (14Nov2019)
					IF(@MACHINECODE='MCFV')
						BEGIN
							IF EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[Target_data]') 
							AND type in (N'U'))
							BEGIN

							INSERT INTO Target_data
							(PROFITCENTERCODE,LINECODE,MACHINECODE,RFID,MODELNO,DTS_SCAN,DTS_PASS,STATUS,DCODE)
							SELECT
							PROFITCENTERCODE,LINECODE,MACHINECODE,BARCODE,PARTNO,SCANTIMESTAMP,RESULTTIMESTAMP,
							CASE WHEN ISNULL(STATUS, '') = 'PS' THEN 'PASS' WHEN ISNULL(STATUS, '') = 'FL' THEN 'FAIL' ELSE STATUS END STATUS
							,DATECODE
							FROM
							ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
							WHERE LINECODE=@LINECODE AND PROFITCENTERCODE=@PROFITCENTERCODE	AND BARCODE=@BARCODE AND MACHINECODE=@MACHINECODE	
							END
						END

				 END
				 
				 ELSE
				 BEGIN
				 --MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
				  INSERT INTO ASSY_LINEASSYSTATUS
						(
						PROFITCENTERCODE,
						LINECODE,
						MACHINECODE,
						OPERATIONCODE,
						STATIONCODE,
						BARCODE,
						STATUS,
						FAILCOUNT,
						DATECODE,
						PARTNO,
						SCANTIMESTAMP,
						RESULTTIMESTAMP,
						USERID,
						PRODUCTIONORDERNO,
						Live_Datecode,
						IsTallyChartApproved,
						Kanban_Id
						)

						SELECT 
						PROFITCENTERCODE,
						LINECODE,
						MACHINECODE,
						OPERATIONCODE,
						STATIONCODE,
						BARCODE,
						STATUS,
						FAILCOUNT,
						DATECODE,
						PARTNO,
						SCANTIMESTAMP,
						RESULTTIMESTAMP,
						USERID,
						PRODUCTIONORDERNO,
						Live_Datecode,
						@IsTallyChartApproved,
						ISNULL(@Kanban_Id,'')
						FROM
								DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
								WHERE  PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE
						AND BARCODE=@BARCODE
						
						UNION

						SELECT 
						PROFITCENTERCODE,
						LINECODE,
						MACHINECODE,
						OPERATIONCODE,
						STATIONCODE,
						BARCODE,
						STATUS,
						FAILCOUNT,
						DATECODE,
						PARTNO,
						SCANTIMESTAMP,
						RESULTTIMESTAMP,
						USERID,
						PRODUCTIONORDERNO,
						Live_Datecode,
						@IsTallyChartApproved,
						ISNULL(@Kanban_Id,'')
						FROM
								DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
						WHERE LINECODE=@LINECODE AND PROFITCENTERCODE=@PROFITCENTERCODE
								AND BARCODE IN 
								(
									SELECT CHILD_BARCODE FROM DBO.ASSY_COUPLINGDETAILS (NOLOCK) 
									WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND FG_BARCODE = @BARCODE
								)
					END	

		print '----6------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()				 				    
					--SELECT DATA FOR UPDATION INTO MAIN SERVER
					SELECT @STATUS=STATUS,@DATECODE=DATECODE,@SCANTIMESTAMP=CONVERT(VARCHAR(30),SCANTIMESTAMP,121)
					,@RESULTTIMESTAMP=CONVERT(VARCHAR(30),RESULTTIMESTAMP,121),@PARTFAILEDCOUNT=FAILCOUNT 					
					FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
					WHERE LINECODE=@LINECODE AND PROFITCENTERCODE=@PROFITCENTERCODE
					AND MACHINECODE =@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE 
					AND BARCODE=@BARCODE

					IF ISDATE(@SCANTIMESTAMP) != 1  
					BEGIN
						SELECT @RETURNINT = 2, @RETURNVALUE = 'Scan Time Not Found. Re-run the process. '
						ROLLBACK TRAN
						RETURN
					END

					IF ISDATE(@RESULTTIMESTAMP) != 1  
					BEGIN
						SELECT @RETURNINT = 2, @RETURNVALUE = 'Result Time Not Found. Re-run the process. '
						ROLLBACK TRAN
						RETURN
					END

		print '----7------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()	
				  ---UPDATE PART AS WELL AS SHIFT PASS FAIL COUNTER
					EXEC ASSY_PROC_SHIFTQTY_UPDATE @CONDITION='UPDATE', @PROFITCENTERCODE=@PROFITCENTERCODE,@ComponentStatus='PASS'--Modified by Aadil on 25012021 for Pass mode 
					,@LINECODE=@LINECODE,@BARCODE=@BARCODE,@OPERATIONCODE=@OPERATIONCODE,@CURRENTDATECODE=@DATECODE,@CURRENTPARTNO=@PARTNUMBER

					DELETE DBO.ASSY_LINEASSYSTATUS_RUNNING  WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND BARCODE=@BARCODE
					
					DELETE FROM DBO.ASSY_VISION_SYSTEM WHERE PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE=@LINECODE AND BARCODE=@BARCODE
					IF(@ISSTMC = 1)
					BEGIN
					DELETE ASSY_LINEASSYSTATUS_RUNNING  WHERE LINECODE=@LINECODE  AND PROFITCENTERCODE=@PROFITCENTERCODE
						AND BARCODE IN (SELECT CHILD_BARCODE FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE FG_BARCODE = @BARCODE)
					END

					/*
							IF @IsAllow2Part_ = 0 AND  @IsLabelPrintingEnabled=1
							IF @IsAllow2Part_ = 1 AND  @IsLabelPrintingEnabled=1
							MOVEMENT IN [Assy_proc_FinalQCStn_Label_Printing (INSERT_BARCODE_DATA)]
							Assy_LineAssyParamData_Running_Dtl -> Assy_LineAssyParamData_Running
							Assy_LineAssyParamData_Running -> Assy_LineAssyParamData
					*/

					IF((@IsAllow2Part_ = 0 AND  @IsLabelPrintingEnabled=0) OR (@IsAllow2Part_ = 1 AND  @IsLabelPrintingEnabled=0) )
					begin 
							print '----8------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
							set @mydate = getdate()		
							--Added By Sachin 24June2020
							INSERT INTO Assy_LineAssyParamData
							(
								[ProfitCenterCode]
								, [LineCode]
								, [MachineCode]
								, [OperationCode]
								, [StationCode]
								, [Barcode]
								, [TagName]
								, [Value]
								, [Result]
								, [DateCode]
								, [UserID]
								, [TimeStamp]
								, PartNo
								, UID
								, ScanTimeStamp
								,Live_Datecode
							)
							SELECT
								[ProfitCenterCode]
								, [LineCode]
								, [MachineCode]
								, [OperationCode]
								, [StationCode]
								, [Barcode]
								, [TagName]
								, [Value]
								, [Result]
								, [DateCode]
								, [UserID]
								, [TimeStamp]
								, PartNo
								, UID
								, ScanTimeStamp
								,Live_Datecode
							FROM Assy_LineAssyParamData_Running (NOLOCK) 
							WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
							AND Barcode=@BARCODE

							INSERT INTO @Assy_LineAssyParamData_Running_Dtl(UID)
							SELECT DISTINCT [UID] FROM  Assy_LineAssyParamData_Running 
							WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
							AND Barcode=@BARCODE AND uid IS NOT NULL		

							DELETE Assy_LineAssyParamData_Running WHERE LineCode = @LineCode 
							AND ProfitCenterCode = @ProfitCenterCode
							AND Barcode=@BARCODE
							print '----9------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
							set @mydate = getdate()		
							INSERT INTO Assy_LineAssyParamData_Dtl
							(
							UID, 
							TagId, 
							Value
							)
							SELECT UID, TagId, Value FROM  Assy_LineAssyParamData_Running_Dtl (NOLOCK)
							WHERE [UID] IN (SELECT [UID] FROM @Assy_LineAssyParamData_Running_Dtl)

							DELETE FROM Assy_LineAssyParamData_Running_Dtl
							WHERE [UID] IN (SELECT [UID] FROM @Assy_LineAssyParamData_Running_Dtl)
							print '----10------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
							set @mydate = getdate()	
							--Ended By Sachin 24June2020
					  end
					--COMMENT BY RAVI ON 18/03/16
					--UPDATE ASSY_PRODUCTIONORDER_PARAMETERSETTING SET PRODUCTIONQTY=ISNULL(PRODUCTIONQTY,0)+1
					--WHERE LINECODE =@LINECODE   AND PROFITCENTERCODE=@PROFITCENTERCODE

					--UPDATE ASSY_PRODUCTIONORDER_PARAMETERSETTING SET BALANCEQTY=ISNULL(CURRENTPLANNEDQTY,0)-ISNULL(PRODUCTIONQTY,0)
					--WHERE LINECODE =@LINECODE   AND PROFITCENTERCODE=@PROFITCENTERCODE

					--DELETE BARCODE DATA FROM TALLY CHART TABLE, IF A BARCODE HAS ALREADY MARKED AS FAILED
					IF EXISTS
					(
				     	SELECT 1 FROM DBO.ASSY_TALLYCHARTSTATUSDATA (NOLOCK) WHERE LINECODE =@LINECODE AND PROFITCENTERCODE =@PROFITCENTERCODE  AND MACHINECODE=@MACHINECODE 
						AND BARCODE =@BARCODE AND ISNULL(RESULT,'')='FAIL'   
					)
					BEGIN
							DELETE FROM ASSY_TALLYCHARTSTATUSDATA WHERE LINECODE =@LINECODE AND MACHINECODE=@MACHINECODE 
						    AND BARCODE =@BARCODE AND ISNULL(RESULT,'')='FAIL' AND PROFITCENTERCODE =@PROFITCENTERCODE 

							IF(@ISSTMC = 1)
							BEGIN
								DELETE FROM ASSY_TALLYCHARTSTATUSDATA WHERE LINECODE =@LINECODE AND MACHINECODE=@MACHINECODE 
								AND ISNULL(RESULT,'')='FAIL' AND PROFITCENTERCODE =@PROFITCENTERCODE AND @BARCODE IN (SELECT CHILD_BARCODE FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE FG_BARCODE = @BARCODE)
							END
					END
		print '----11------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()	
					------------------UPDATE ASSY_POKAYOKE_COMPLETED_DTL TABLE FOR CHECKING WHETHER FINAL VIEWING TESTING HAS BEEN COMPLETED OR NOT--------------------------
					-- ADDED BY RASHID ON 11TH AUGUST 2016
					DECLARE @ISPARTTESTEDAFTERPKYK INT =0
					DECLARE @CREATEDDATE DATETIME

					SELECT TOP 1  @DATECODE=DATECODE,@PARTNO=ASSY_PARTNO,@CREATEDDATE=CREATEDDATE FROM ASSY_RUNNINGPART WITH (NOLOCK) 
							WHERE PROFITCENTERCODE=@PROFITCENTERCODE  AND LINECODE=@LINECODE ORDER BY CREATEDDATE DESC
								
					IF EXISTS
					(
					  SELECT 1 FROM LINEMST WITH(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND ISNULL(ISPOKAYOKEMANDATORY,0)=1
					)
					BEGIN		 
						SELECT @ISPARTTESTEDAFTERPKYK=ISNULL(COUNT(ISNULL (BARCODE,0)),0) FROM ASSY_LINEASSYSTATUS WITH(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE 
						AND LINECODE=@LINECODE
						AND DATECODE=@DATECODE AND MACHINECODE=DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE)
						AND PARTNO=@PARTNO AND SCANTIMESTAMP>=@CREATEDDATE AND ISNULL(ISTALLYCHARTAPPROVED,0)=0 AND ISNULL(STATUS,'')!=''
						
						IF(ISNULL(@ISPARTTESTEDAFTERPKYK,0) = 1)
							BEGIN
							--DELETE ASSY_POKAYOKE_COMPLETED_DTL IF DATECODE IS OLD
								IF EXISTS(SELECT 1 FROM ASSY_POKAYOKE_COMPLETED_DTL WITH(NOLOCK) WHERE DATECODE!=@DATECODE)
									TRUNCATE TABLE ASSY_POKAYOKE_COMPLETED_DTL 

								IF NOT EXISTS (SELECT 1 FROM ASSY_POKAYOKE_COMPLETED_DTL WHERE PROFITCENTERCODE=@PROFITCENTERCODE 
										AND LINECODE=@LINECODE	AND DATECODE=@DATECODE AND PARTNO=@PARTNO)
								BEGIN
									INSERT INTO ASSY_POKAYOKE_COMPLETED_DTL
									(
									PROFITCENTERCODE,LINECODE,DATECODE,PARTNO,IS_PKYK_COMPLETED,IS_FV_COMPLETED,TIMESTAMP
									)
									SELECT @PROFITCENTERCODE,@LINECODE,@DATECODE,@PARTNO,1, (CASE WHEN @ISPARTTESTEDAFTERPKYK=0 THEN 0 ELSE 1 END)IS_PKYK_COMPLETED,GETDATE()
								END
								ELSE
								BEGIN
									UPDATE ASSY_POKAYOKE_COMPLETED_DTL SET TIMESTAMP = GETDATE() WHERE PROFITCENTERCODE=@PROFITCENTERCODE 
										AND LINECODE=@LINECODE	AND DATECODE=@DATECODE AND PARTNO=@PARTNO
								END
							END
					END
		print '----12------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()	
					--DECREASE WIP COUNT AND REOMVE WIP FIFO BARCODE FROM PREVIOS STATION 				
					
					IF @FAILCOUNT=0
						 EXEC ASSY_PROC_WIP_MANAGE  @CONDITION='UPDATE_WIP_COUNT', @LINECODE=@LINECODE,@MACHINECODE=@MACHINECODE,@BARCODE=@BARCODE	,@PROFITCENTERCODE =@PROFITCENTERCODE 
						 print '----13 00------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
						set @mydate = getdate()	
					--RESET DATE CODE STAMPING ACK. AND BARCODE
					  EXEC ASSY_PROC_DATECODESTAMPING @CONDITION='RESET_ACK',@LINECODE =@LINECODE,@PROFITCENTERCODE=@PROFITCENTERCODE
				  	print '----13 01------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
					set @mydate = getdate()	
		print '----13------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()	
				--------------Update Previous count and parametersetting data
					
					IF EXISTS
					(
						SELECT 1 FROM ASSY_RUNNINGPART_PREVIOUS (NOLOCK) WHERE ASSY_MODE IN ('PRODUCTION', 'REWORK')
							AND LINECODE = @LINECODE AND CURRENTPLANNEDQTY > ISNULL(PRODUCEDQTY, 0)
					)
					BEGIN
						Select top 1 * into #ASSY_RUNNINGPART_PREVIOUS from ASSY_RUNNINGPART_PREVIOUS where 
						LINECODE = @LINECODE AND CURRENTPLANNEDQTY > ISNULL(PRODUCEDQTY, 0) AND 
						Assy_PartNo=@PARTNUMBER order by CreatedDate asc
											
						UPDATE RPS SET RPS.PRODUCEDQTY = ISNULL(RPS.PRODUCEDQTY, 0) + 1 , RPS.BALANCEQTY = ISNULL(RPS.BALANCEQTY,0) - 1 
						from ASSY_RUNNINGPART_PREVIOUS RPS
						Inner Join #ASSY_RUNNINGPART_PREVIOUS (NOLOCK) RK ON  RK.ProductionOrderNo=RPS.PRODUCTIONORDERNO
						WHERE RPS.LINECODE = @LINECODE  
						
						DELETE FROM ASSY_RUNNINGPART_PREVIOUS WHERE LINECODE = @LINECODE AND CURRENTPLANNEDQTY = ISNULL(PRODUCEDQTY, 0)
						
					END
					ELSE
					BEGIN	
								
						UPDATE ASSY_PRODUCTIONORDER_PARAMETERSETTING SET PRODUCTIONQTY = ISNULL(PRODUCTIONQTY, 0) + 1, BALANCEQTY = ISNULL(BALANCEQTY,0) - 1
						WHERE LINECODE = @LINECODE   AND PROFITCENTERCODE = @PROFITCENTERCODE
											
					END

		print '----14------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()	

				
				  SET @RETURNINT = 1
				  SET @RETURNVALUE = 'PASSED' 
				  SELECT @RETURNINT RETURNINT,@RETURNVALUE RETURNVALUE
				  SELECT @SCANTIMESTAMP SCANTIMESTAMP, @RESULTTIMESTAMP RESULTTIMESTAMP, @STATUS [STATUS], @PARTFAILEDCOUNT PARTFAILEDCOUNT,
				  @DATECODE DATECODE, @PARTNUMBER PARTNUMBER,'' LOT_NO , '' ECU_BARCODE,ISNULL(@ProductionOrderNo,'') [ProductionOrderNo]
		print '----15------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()	
				   COMMIT TRAN
				  -- INSERT COUPLING DATA INTO CENTRAL SERVER
				-- START -- ADDED BY RASHID ON 20TH JUNE 2016 -----
					IF CHARINDEX(':',@BARCODE) <> 0 AND ISNULL(@BARCODE,'') <> ''
					BEGIN
						SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL WITH (NOLOCK) 
								WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE	
						SET @EXECQUERY = ''

						SET @EXECQUERY = '
							IF EXISTS (SELECT 1 FROM ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + ''')
							BEGIN
								INSERT INTO ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS_HISTORY (PROFITCENTRECODE,LINECODE,STMC_PART_NO,CHILD_PART_NO,PART_TYPE,MACHINE_CODE,OPERATION_CODE,TORQUE_1,TORQUE_2,ENT_DT,ENT_BY,FG_BARCODE,CHILD_BARCODE,DATECODE,HIS_ENT_DT,HIS_ENT_

BY)
								SELECT PROFITCENTRECODE,LINECODE,STMC_PART_NO,CHILD_PART_NO,PART_TYPE,MACHINE_CODE,OPERATION_CODE,TORQUE_1,TORQUE_2,ENT_DT,ENT_BY,FG_BARCODE,CHILD_BARCODE,DATECODE,GETDATE(),''' + ISNULL(@USERID,'''') + ''' FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) 

WHERE PROFITCENTRECODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + '''

								DELETE FROM ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS WHERE PROFITCENTRECODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + '''
								
								IF NOT EXISTS (SELECT 1 FROM ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + ''')
								BEGIN
									INSERT INTO ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS (PROFITCENTRECODE,LINECODE,STMC_PART_NO,CHILD_PART_NO,PART_TYPE,MACHINE_CODE,OPERATION_CODE,TORQUE_1,TORQUE_2,ENT_DT,ENT_BY,FG_BARCODE,CHILD_BARCODE,DATECODE)
									SELECT PROFITCENTRECODE,LINECODE,STMC_PART_NO,CHILD_PART_NO,PART_TYPE,MACHINE_CODE,OPERATION_CODE,TORQUE_1,TORQUE_2,ENT_DT,ENT_BY,FG_BARCODE,CHILD_BARCODE,DATECODE FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = ''' 
									+ @PROFITCENTERCODE +''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + '''
								END
							END
							ELSE
							BEGIN
								INSERT INTO ' + @LINKSERVERNAME + '.DBO.ASSY_COUPLINGDETAILS (PROFITCENTRECODE,LINECODE,STMC_PART_NO,CHILD_PART_NO,PART_TYPE,MACHINE_CODE,OPERATION_CODE,TORQUE_1,TORQUE_2,ENT_DT,ENT_BY,FG_BARCODE,CHILD_BARCODE,DATECODE)
								SELECT PROFITCENTRECODE,LINECODE,STMC_PART_NO,CHILD_PART_NO,PART_TYPE,MACHINE_CODE,OPERATION_CODE,TORQUE_1,TORQUE_2,ENT_DT,ENT_BY,FG_BARCODE,CHILD_BARCODE,DATECODE FROM ASSY_COUPLINGDETAILS WITH (NOLOCK) WHERE PROFITCENTRECODE = ''' 
								+ @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND FG_BARCODE = ''' + @BARCODE + '''
							END
							'
						PRINT @EXECQUERY
						EXEC (@EXECQUERY)
		print '----16------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)

		 
		set @mydate = getdate()	
		END
		
		IF EXISTS(SELECT TOP 1 1 FROM RoutingConfigDetails(NOLOCK) 
		WHERE PROFITCENTERCODE = @PROFITCENTERCODE and LineCode=@LINECODE AND KeyType='IsBarcodeCapturingFromMES' 
		AND KeyValue='1' AND PartNumber=@MESPARTNO)
		BEGIN

			INSERT INTO Assy_FinalViewing_RFID_Barcode_Mapping
			(
				ProfitCenterCode, LineCode, MachineCode, OperationCode,
				RFID, Barcode, Status, PartNo, Datecode, PrintedTimestamp
			)
			SELECT TOP 1 @PROFITCENTERCODE,	@LINECODE, @MachineCode, @OperationCode,
				RFID, PRINTED_BARCODE, 'PS', PartNo, @datecode, GETDATE()
			FROM ASSY_FV_ROBOT_INSPECTION_SERIAL_HOLD WITH (NOLOCK)
			WHERE RFID = @Barcode;

			SELECT @LINKSERVERNAME = LINKSERVERNAME, @LINKDB = DATABASENAME FROM ASSY_LINKSERVER_DTL WITH (NOLOCK) 
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE	
			SET @EXECQUERY = ''

			SET @EXECQUERY = N'
			INSERT INTO OPENQUERY(' + @LINKSERVERNAME + ',
				''SELECT PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE,
						RFID, BARCODE, STATUS, PARTNO, DATECODE,
						PRINTEDTIMESTAMP, CALIPERSERNO, CALIPERDATECODE
				  FROM ' + @LINKDB + '.dbo.ASSY_FINALVIEWING_RFID_BARCODE_MAPPING'')
			SELECT PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE,
				   RFID, BARCODE, STATUS, PARTNO, DATECODE,
				   PRINTEDTIMESTAMP, CALIPERSERNO, CALIPERDATECODE
			FROM ASSY_FINALVIEWING_RFID_BARCODE_MAPPING WITH (NOLOCK)
			WHERE PROFITCENTERCODE = @PC
			  AND LINECODE = @LC
			  AND RFID = @RF;'

			EXEC sp_executesql
				@EXECQUERY,
				N'@PC VARCHAR(50), @LC VARCHAR(50), @RF VARCHAR(100)',
				@PC = @PROFITCENTERCODE,
				@LC = @LINECODE,
				@RF = @Barcode

			IF EXISTS (SELECT 1 FROM ASSY_FINALVIEWING_RFID_BARCODE_MAPPING (NOLOCK)
				WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND RFID = @Barcode)
			BEGIN
				DELETE FROM ASSY_FV_ROBOT_INSPECTION_SERIAL_HOLD
				WHERE RFID = @Barcode;
			END
		END


		print '----17------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
				-- END -- ADDED BY RASHID ON 20TH JUNE 2016 -----		       
				    END TRY
					BEGIN CATCH
			
								SET @RETURNVALUE =	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
								CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
								CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
								CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
								CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
								CAST(ERROR_MESSAGE() AS VARCHAR(1500))
			
								ROLLBACK TRAN				
								SET @RETURNINT = 2
								RAISERROR(@RETURNVALUE,16,1)	
					END CATCH
					RETURN

       END
	      			
		ELSE IF @CONDITION = 'UPDATE_FINALVIEWING_FAIL_STATUS'		
		BEGIN
		      BEGIN TRY
		       BEGIN TRAN
					
					IF CHARINDEX(':',@BARCODE)<> 0 AND ISNULL(@BARCODE,'')<>'' 
							BEGIN
									SET @ISSTMC = 1
									SELECT DISTINCT @LINECODE_STMC =  ISNULL(LINECODE, '') , @DATECODE_TEMP = ISNULL(DATECODE, '')  FROM DBO.ASSY_LINEASSYSTATUS_RUNNING(NOLOCK) 
									WHERE  PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE=@LINECODE AND MACHINECODE =@MACHINECODE  AND BARCODE = @BARCODE  
									SET @DATECODE = @DATECODE_TEMP
									IF(@LINECODE_STMC)<>''
									BEGIN
											SELECT DISTINCT @PARTNUMBER=ISNULL(STMC_PART_NO, ''),@DATECODE=DATECODE FROM DBO.ASSY_COUPLINGDETAILS(NOLOCK)
											 WHERE FG_BARCODE = @BARCODE AND LINECODE = @LINECODE
									END
									ELSE
										BEGIN
											SELECT DISTINCT @PARTNUMBER=ISNULL(STMC_PART_NO, ''),@LINECODE_STMC=LINECODE,@DATECODE=DATECODE FROM DBO.ASSY_COUPLINGDETAILS(NOLOCK) 
											WHERE FG_BARCODE = @BARCODE 
											AND LINECODE = @LINECODE AND PROFITCENTRECODE=@PROFITCENTERCODE
										END							  
						END		
						ELSE IF @ISSTMC = 0 AND ISNULL(@BARCODE,'')<>'' 
						BEGIN
								--GET DATECODE AND PART NO OF SNANNED BARCODE FROM VISION SYSTEM
								SELECT @PARTNUMBER=PARTNO,@DATECODETEMP=DATECODE FROM ASSY_FN_GET_BARCODEPARTS_FROM_BARCODE(@PROFITCENTERCODE,@LINECODE,@BARCODE)							
								SET @DATECODE=@DATECODETEMP
						END
					
					if not exists(select top 1 1 from #Temp_RoboKey_bij where RoboKey in('2'))
					Begin
						UPDATE ASSY_LINEASSYSTATUS_RUNNING SET STATUS='FL',RESULTTIMESTAMP =GETDATE(),
						FAILCOUNT =ISNULL (FAILCOUNT,0 )+1,Live_Datecode=@Live_Datecode
						WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND MACHINECODE =@MACHINECODE 
						AND OPERATIONCODE=@OPERATIONCODE AND BARCODE=@BARCODE 
						AND ISNULL(STATUS,'')<>'PS'
					End
					
					--CLEAR SCAN OK BARCODE FROM ASSY_SCANOK
					 UPDATE ASSY_SCAN_OK SET BARCODE ='',ISSCAN=0  WHERE LINECODE =@LINECODE AND MACHINECODE =@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE
					if exists(select top 1 1 from #Temp_RoboKey_bij where RoboKey in('1'))
					Begin
						Delete from Assy_Scan_OK_ROBO where barcode=@BARCODE AND LINECODE =@LINECODE AND MACHINECODE =@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE
					END					
					
					select top 1 @TallyChartWithPartFamily=Convert(smallint,KeyValue) from RoutingConfigDetails(nolock) 
					where ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode and STS_CD=0 and KeyType='TallyChartWithPartFamily'

					 if exists(select top 1 1 from LineMst(nolock) where LineCode=@LINECODE 
					 and Allow2Parts=1 and ProfitCenterCode = @PROFITCENTERCODE)
					 begin
							IF(@TallyChartWithPartFamily = 1)
							BEGIN
								set @IsTallyChartApproved = 0
							END
							ELSE
							BEGIN
								set @IsTallyChartApproved = 1
							END
					 end
					 else
					 begin
							set @IsTallyChartApproved = 0
					 end

					 --added by sachin 22-May-2020					
					select top 1 @ProductionOrderNo=ProductionOrderNo,@PARTNUMBER=PartNo,@DATECODE=Datecode 
					from Assy_lineAssyStatus_running(nolock) 
					where ProfitCenterCode=@PROFITCENTERCODE and LineCode=@LINECODE
					and barcode=@BARCODE and machineCode='MCIG'
					order by ScanTimestamp desc 	
					--ended by sachin 22-May-2020

					-- Added on 22Dec2020
					IF ISNULL(@DATECODE,'') = '' OR ISNULL(@PARTNUMBER,'')='' OR  ISNULL(@ProductionOrderNo,'')=''
					BEGIN
						SELECT @RETURNINT = 2, @RETURNVALUE = 'Date Code Empty. Re-run the process. ' 
						+ ISNULL(@DATECODE,'') + ISNULL(@PARTNUMBER,'') + ISNULL(@ProductionOrderNo,'')
						 + ISNULL(@BARCODE,'')
						ROLLBACK TRAN
						RETURN
					END
					-- Ended on 22Dec2020

					--INSERT FAIL DATA INTO ASSY_LINEASSYPARAMDATA_RUNNING TABLE
					
					if exists(select top 1 1 from #Temp_RoboKey_bij where RoboKey in('2'))
					Begin					
						Begin Try
								Select @QR_CODE =PRINTED_BARCODE from ASSY_FV_ROBOT_INSPECTION_SERIAL_HOLD where PARTNO=@PARTNUMBER AND RFID=@BARCODE 
								SELECT P1,P2,P3,P4,P5,P6,P7,P8,P9,P10,P11,P12,P13,P14,P15,P16,P17,P18,P19,P20,P21,P22,P23,P24,P25,P26 INTO #ROBO_PARAMETER_DATA_FAIL
								FROM TD_ROBO_DATA_WITH_PARAMETER WITH(NOLOCK)
								WHERE  QR_CODE=@QR_CODE AND TS_FLAG='0'

								SET @XmldataLK  = (SELECT * FROM  #ROBO_PARAMETER_DATA_FAIL FOR XML PATH('') )   
				
								--Dynamic unpivoting 
								insert into @TagData(TagName,TagValue)
								SELECT TagName,TagValue FROM  ( 
								SELECT 
								ROW_NUMBER()OVER(PARTITION BY   TagName ORDER BY  TagValue) rn,* FROM ( 
								SELECT  i.value('local-name(.)','VARCHAR(100)')  TagName,
								i.value('.','VARCHAR(100)') TagValue 
								FROM @xmldataLK.nodes('//*') x(i) ) tmp ) tmp1
											
								INSERT INTO @ParameterData(
								ProfitCenterCode,LineCode,MachineCode,
								OperationCode,StationCode,Barcode,TagName,Value,Result,Datecode,UserID)
								select @PROFITCENTERCODE,@LINECODE,@MACHINECODE,
								@OPERATIONCODE,'1',@Barcode,TagName,TagValue,'FL','',@USERID 
								from @TagData
								
								exec Assy_Proc_PLCIntegration_Jhagadia @Operation = 'INSERT_PLC_PARAMS',@LineCode = @LINECODE,
								@tblParameters = @ParameterData

								 Delete TD_ROBO_DATA_WITH_PARAMETER where QR_CODE=@QR_CODE 
								 Delete from Assy_Scan_OK_ROBO where barcode=@BARCODE
						END TRY
						BEGIN CATCH			
								SET @RETURNVALUE =	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
								CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
								CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
								CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
								CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
								CAST(ERROR_MESSAGE() AS VARCHAR(1500))			
								SET @RETURNINT = 2
								ROLLBACK TRAN
								RAISERROR(@RETURNVALUE,16,1)
								RETURN
						END CATCH					
					End
					else
					Begin

						INSERT INTO ASSY_LINEASSYPARAMDATA_RUNNING
					(
					PROFITCENTERCODE
					,LINECODE
					,MACHINECODE
					,OPERATIONCODE
					,STATIONCODE
					,BARCODE					
					,RESULT
					,DATECODE
					,USERID
					,TIMESTAMP
					,PARTNO
					,LIVE_DATECODE
					)
					SELECT 
					@PROFITCENTERCODE 
					,@LINECODE 
					,@MACHINECODE 
					,@OPERATIONCODE
					,@STATIONCODE
					,@BARCODE					
					,'FL'
					,@DATECODE 
					,@USERID 
					,GETDATE()
					,@PARTNUMBER 
					,@LIVE_DATECODE

					end
					SELECT @FAILCOUNTDEFINED=CONVERT(INT,PARAMETER_VALUE)   FROM PARAMETER_MST (NOLOCK)  
				   WHERE PARAMETER_C='ASSLINE' 
				   AND PARAMETER_C1='REWORK_COUNT'	
				   AND WH_CODE =@PROFITCENTERCODE 
				   
					SELECT @FAILCOUNT=ISNULL(FAILCOUNT,0)  FROM DBO.ASSY_LINEASSYSTATUS_RUNNING (NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE 
					AND LINECODE=@LINECODE  AND BARCODE=@BARCODE 
					AND	MACHINECODE=@MACHINECODE 
					AND ISNULL(STATUS,'') ='FL'
					
					--SELECT DATA FOR UPDATION INTO MAIN SERVER
					SELECT @STATUS=STATUS,@DATECODE=DATECODE,@SCANTIMESTAMP=SCANTIMESTAMP,@RESULTTIMESTAMP=RESULTTIMESTAMP					
					FROM ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
					WHERE LINECODE=@LINECODE AND PROFITCENTERCODE=@PROFITCENTERCODE
					AND MACHINECODE =@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE 
					AND BARCODE=@BARCODE

					--MOVE BARCODE FROM RUNNING TO ASSY_LINEASSYSTATUS TABLE AFTER MAXIMUMM NO OF TIMES FAIL REACHED
					IF @FAILCOUNTDEFINED=@FAILCOUNT 
					BEGIN
					   
						  IF(@ISSTMC = 0)
						  BEGIN
							--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
							INSERT INTO ASSY_LINEASSYSTATUS
							(
							PROFITCENTERCODE,
							LINECODE,
							MACHINECODE,
							OPERATIONCODE,
							STATIONCODE,
							BARCODE,
							STATUS,
							FAILCOUNT,
							DATECODE,
							PARTNO,
							SCANTIMESTAMP,
							RESULTTIMESTAMP,
							USERID,
							PRODUCTIONORDERNO,
							Live_Datecode,
							IsTallyChartApproved
							)

							SELECT 
							PROFITCENTERCODE,
							LINECODE,
							MACHINECODE,
							OPERATIONCODE,
							STATIONCODE,
							BARCODE,
							STATUS,
							FAILCOUNT,
							DATECODE,
							PARTNO,
							SCANTIMESTAMP,
							RESULTTIMESTAMP,
							USERID,
							PRODUCTIONORDERNO,
							Live_Datecode,
							@IsTallyChartApproved
							FROM
							ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
							WHERE LINECODE=@LINECODE 
							AND BARCODE=@BARCODE
						  END

						  ELSE
						  BEGIN
							--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
							INSERT INTO ASSY_LINEASSYSTATUS
							(
							PROFITCENTERCODE,
							LINECODE,
							MACHINECODE,
							OPERATIONCODE,
							STATIONCODE,
							BARCODE,
							STATUS,
							FAILCOUNT,
							DATECODE,
							PARTNO,
							SCANTIMESTAMP,
							RESULTTIMESTAMP,
							USERID,
							PRODUCTIONORDERNO,
							Live_Datecode,
							IsTallyChartApproved
							)

							SELECT 
							PROFITCENTERCODE,
							LINECODE,
							MACHINECODE,
							OPERATIONCODE,
							STATIONCODE,
							BARCODE,
							STATUS,
							FAILCOUNT,
							DATECODE,
							PARTNO,
							SCANTIMESTAMP,
							RESULTTIMESTAMP,
							USERID,
							PRODUCTIONORDERNO,
							Live_Datecode,
							@IsTallyChartApproved
							FROM
							ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
							WHERE LINECODE=@LINECODE 
							AND BARCODE=@BARCODE

							UNION

							SELECT 
							PROFITCENTERCODE,
							LINECODE,
							MACHINECODE,
							OPERATIONCODE,
							STATIONCODE,
							BARCODE,
							STATUS,
							FAILCOUNT,
							DATECODE,
							PARTNO,
							SCANTIMESTAMP,
							RESULTTIMESTAMP,
							USERID,
							PRODUCTIONORDERNO,
							Live_Datecode,
							@IsTallyChartApproved
							FROM
							ASSY_LINEASSYSTATUS_RUNNING(NOLOCK)
							WHERE LINECODE=@LINECODE 
							AND BARCODE  IN (SELECT CHILD_BARCODE FROM ASSY_COUPLINGDETAILS (NOLOCK) WHERE FG_BARCODE = @BARCODE)
						END

							---UPDATE PART AS WELL AS SHIFT PASS FAIL COUNTER
							EXEC ASSY_PROC_SHIFTQTY_UPDATE @CONDITION='UPDATE',@ComponentStatus='FAIL', @PROFITCENTERCODE=@PROFITCENTERCODE --Modified by Aadil on 25012021 for Pass mode 
							,@LINECODE=@LINECODE,@BARCODE=@BARCODE,@OPERATIONCODE=@OPERATIONCODE,@CURRENTDATECODE=@DATECODE,@CURRENTPARTNO=@PARTNUMBER

							DELETE ASSY_LINEASSYSTATUS_RUNNING  WHERE PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE=@LINECODE							
							AND BARCODE=@BARCODE

							DELETE FROM ASSY_VISION_SYSTEM WHERE PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE=@LINECODE AND BARCODE=@BARCODE
							IF(@ISSTMC = 1)
							BEGIN
								DELETE ASSY_LINEASSYSTATUS_RUNNING  WHERE LINECODE=@LINECODE							
								AND BARCODE IN (SELECT CHILD_BARCODE FROM ASSY_COUPLINGDETAILS (NOLOCK) WHERE FG_BARCODE = @BARCODE)
							END
								--Added By Sachin 24June2020
								INSERT INTO Assy_LineAssyParamData
								(
									[ProfitCenterCode]
									, [LineCode]
									, [MachineCode]
									, [OperationCode]
									, [StationCode]
									, [Barcode]
									, [TagName]
									, [Value]
									, [Result]
									, [DateCode]
									, [UserID]
									, [TimeStamp]
									, PartNo
									, UID
									, ScanTimeStamp
									,Live_Datecode
								)
								SELECT
									[ProfitCenterCode]
									, [LineCode]
									, [MachineCode]
									, [OperationCode]
									, [StationCode]
									, [Barcode]
									, [TagName]
									, [Value]
									, [Result]
									, [DateCode]
									, [UserID]
									, [TimeStamp]
									, PartNo
									, UID
									, ScanTimeStamp
									,Live_Datecode
								FROM Assy_LineAssyParamData_Running (NOLOCK) 
								WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
								AND Barcode=@BARCODE

								INSERT INTO @Assy_LineAssyParamData_Running_Dtl(UID)
								SELECT DISTINCT [UID] FROM  Assy_LineAssyParamData_Running 
								WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
								AND Barcode=@BARCODE AND uid IS NOT NULL		

								DELETE Assy_LineAssyParamData_Running WHERE LineCode = @LineCode 
								AND ProfitCenterCode = @ProfitCenterCode
								AND Barcode=@BARCODE

								INSERT INTO Assy_LineAssyParamData_Dtl
								(
								UID, 
								TagId, 
								Value
								)
								SELECT UID, TagId, Value FROM  Assy_LineAssyParamData_Running_Dtl (NOLOCK)
								WHERE [UID] IN (SELECT [UID] FROM @Assy_LineAssyParamData_Running_Dtl)

								DELETE FROM Assy_LineAssyParamData_Running_Dtl
								WHERE [UID] IN (SELECT [UID] FROM @Assy_LineAssyParamData_Running_Dtl)
					  END
					  ELSE
					  BEGIN
					    --[Start] Added by Aadil for Pass fail qty update 
						---UPDATE PART AS WELL AS SHIFT PASS FAIL COUNTER
							EXEC ASSY_PROC_SHIFTQTY_UPDATE @CONDITION='UPDATE',@ComponentStatus='FAIL', @PROFITCENTERCODE=@PROFITCENTERCODE --Modified by Aadil on 25012021 for Pass mode 
							,@LINECODE=@LINECODE,@BARCODE=@BARCODE,@OPERATIONCODE=@OPERATIONCODE,@CURRENTDATECODE=@DATECODE,@CURRENTPARTNO=@PARTNUMBER
						--[END] Added by Aadil for Pass fail qty update 
					  END				 
					 --RESET DATE CODE STAMPING ACK. AND BARCODE
					  EXEC ASSY_PROC_DATECODESTAMPING @CONDITION='RESET_ACK',@LINECODE =@LINECODE,@PROFITCENTERCODE=@PROFITCENTERCODE
					 
					 --DECREASE WIP COUNT AND REOMVE WIP FIFO BARCODE FROM PREVIOS STATION 	
					 IF @FAILCOUNT = 1					
						EXEC ASSY_PROC_WIP_MANAGE  @CONDITION='UPDATE_WIP_COUNT', @LINECODE=@LINECODE,@MACHINECODE=@MACHINECODE,@BARCODE=@BARCODE	,@PROFITCENTERCODE =@PROFITCENTERCODE 
					
					  SET @RETURNINT=1
					  SET @RETURNVALUE='FAILED' 
				  SELECT @RETURNINT RETURNINT,@RETURNVALUE RETURNVALUE
				  SELECT @SCANTIMESTAMP SCANTIMESTAMP, @RESULTTIMESTAMP RESULTTIMESTAMP, @STATUS STATUS, @FAILCOUNT PARTFAILEDCOUNT,@DATECODE DATECODE, @PARTNUMBER PARTNUMBER
				  ,ISNULL(@RETURN_LOT_NO,'') LOT_NO , ISNULL(@RETURN_ECU_BARCODE,'') ECU_BARCODE
				  
					  COMMIT TRAN			   
				   END TRY
					BEGIN CATCH			
								SET @RETURNVALUE =	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
								CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
								CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
								CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
								CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
								CAST(ERROR_MESSAGE() AS VARCHAR(1500))			
								SET @RETURNINT = 2
							    ROLLBACK TRAN
								RAISERROR(@RETURNVALUE,16,1)	
					END CATCH					
					RETURN
       END
		ELSE IF @CONDITION = 'GET_FINALVIEWING_LAST_SCAN_BARCODE'		
		BEGIN
			SELECT @RETURNVALUE = ISNULL(BARCODE, '') FROM ASSY_SCAN_OK (NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE AND MACHINECODE = @MACHINECODE 
			
			SET @RETURNINT = 1
			RETURN
		END
		ELSE IF @CONDITION = 'GET_NO_OF_CHANGEOVERS'		
		BEGIN		
			DECLARE @CHANGEOVERCOUNT INT
			SELECT @CHANGEOVERCOUNT = DBO.ASSY_FN_GET_CHANGEOVER_COUNT (@PROFITCENTERCODE, @LINECODE, @CHANGEOVER_DATECODE )
			
			SET @RETURNVALUE = CONVERT(VARCHAR (30), @CHANGEOVERCOUNT)
			SET @RETURNINT = 1
			RETURN
		END

		ELSE IF @CONDITION = 'GET_FINALVIEWING_MACHINECODE_OPERATIONCODE'		
		BEGIN					
			SELECT @FINALVIEWING_OPERATIONCODE = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)	
			, @FINALVIEWING_MACHINECODE = DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)	
			
			SELECT @RETURNVALUE = @FINALVIEWING_MACHINECODE+'|'+@FINALVIEWING_OPERATIONCODE, @RETURNINT = 1
			RETURN
		END

		ELSE IF @CONDITION = 'GET_FIRSTSTATION_MACHINECODE'		
		BEGIN
			SELECT @RETURNVALUE = MACHINECODE FROM ROUTINGCONFIGLINEWISE WITH (NOLOCK) 
				WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE AND OPERATIONSEQNO = 1
			
			SET @RETURNINT = 1
			RETURN
		END	
				
		ELSE IF @CONDITION = 'UPDATE_FV_QC_OK_PASS_DATA_IN_MAINSERVER'
		BEGIN
			BEGIN TRY
			IF EXISTS (SELECT 1 FROM ASSY_LINEASSYSTATUS (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND
				MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND STATUS = 'FL' AND BARCODE = @BARCODE)
			BEGIN
				DELETE FROM ASSY_LINEASSYSTATUS WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND
					MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND STATUS = 'FL' AND BARCODE = @BARCODE
			END
			---- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING STOCK DEDUCTION ----
			ELSE
			BEGIN
					   --CHANGED BY RAVI ON 08-08-17 TO UPDATE DATA INTO ASSY_MACHINEWISE_RUNNINGPART
					    IF ISNULL( @ALLOW2PARTS,0)=1
						BEGIN
								IF EXISTS
								( 
										SELECT 1 FROM ASSY_MACHINEWISE_RUNNINGPART WITH(NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
										AND OPERATIONCODE = @OPERATIONCODE
								)
								BEGIN
										UPDATE ASSY_MACHINEWISE_RUNNINGPART SET PARTNO = @PARTNUMBER,UPDATEDDATE=GETDATE() 
										WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE	AND OPERATIONCODE =@OPERATIONCODE
								END
								ELSE 
									BEGIN
										INSERT INTO ASSY_MACHINEWISE_RUNNINGPART(PROFITCENTERCODE,LINECODE,OPERATIONCODE,MACHINECODE ,PARTNO,CREATEDDATE)
										SELECT @PROFITCENTERCODE,@LINECODE,@OPERATIONCODE,@MACHINECODE,@PARTNUMBER,GETDATE()

									END
						END
				--START-- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING STOCK DEDUCTION
				IF ((SELECT ISNULL(ISMATFEEDREQUIRED, 0) FROM LINEMST WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE) = 1)
				BEGIN
					EXEC ASSY_PROC_MATERIALFEEDINGVALIDATION
					@CONDITION = 'MAT_FEED_STOCK_DEDUCTION', 
					@PROFITCENTERCODE = @PROFITCENTERCODE, 
					@LINECODE = @LINECODE, 
					@USERID = @USERID, 
					@PARTNUMBER = @PARTNUMBER, 
					@BARCODE = @BARCODE							
				END
				--END-- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING STOCK DEDUCTION
			END

				INSERT INTO ASSY_LINEASSYSTATUS
				(
					PROFITCENTERCODE, 
					LINECODE, 
					MACHINECODE, 
					OPERATIONCODE, 
					STATIONCODE, 
					BARCODE, 
					STATUS, 
					FAILCOUNT, 
					DATECODE, 
					PARTNO, 
					SCANTIMESTAMP, 
					RESULTTIMESTAMP, 
					USERID,
					PRODUCTIONORDERNO,
					Live_Datecode
				)

				SELECT 
					@PROFITCENTERCODE, 
					@LINECODE, 
					@MACHINECODE, 
					@OPERATIONCODE, 
					@STATIONCODE, 
					@BARCODE, 
					@STATUS, 
					@PARTFAILEDCOUNT, 
					@DATECODE, 
					@PARTNUMBER, 
					@SCANTIMESTAMP, 
					@RESULTTIMESTAMP, 
					@USERID,
					@PRODUCTIONORDERNO,
					@Live_Datecode
						
				----START-- ADDED BY RASHID SIDDIQUI ON 08TH AUGUST 2016 FOR MATERIAL FEEDING STOCK DEDUCTION
				IF ((SELECT ISNULL(ISPRODCONFREQUIRED, 0) FROM LINEMST WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE) = 1)
				BEGIN
					IF EXISTS (SELECT 1 FROM ASSY_MAT_FEED_STATUS_ISPRODCONF WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE)
					BEGIN
						UPDATE ASSY_FGCHILDPARTCONSUMPTION SET ISACTIVE = 2 WHERE WH_CODE = @PROFITCENTERCODE AND LINE_CODE = @LINECODE AND ISACTIVE = 1
						DELETE FROM ASSY_MAT_FEED_STATUS_ISPRODCONF WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
					END
				END
				----END-- ADDED BY RASHID SIDDIQUI ON 08TH AUGUST 2016 FOR MATERIAL FEEDING STOCK DEDUCTION

				--ADDED BY RAVI ON 18/03/16-------------
				DELETE FROM ASSY_LINEASSYSTATUS_FV_LASTTESTED_BARCODE WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
				
				INSERT INTO ASSY_LINEASSYSTATUS_FV_LASTTESTED_BARCODE (PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE, BARCODE, DATECODE, PARTNO, SCANTIMESTAMP, RESULTTIMESTAMP)
				SELECT @PROFITCENTERCODE, @LINECODE, @MACHINECODE, @OPERATIONCODE, @BARCODE, @DATECODE, @PARTNUMBER, @SCANTIMESTAMP, @RESULTTIMESTAMP
				--------------------------END--------------
				
				IF @STATUS = 'PS'
				BEGIN
					-- ADD/COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
					DECLARE @GROUPCODE VARCHAR(10) = ''
					SELECT @GROUPCODE = GROUPCODE FROM ASSY_LINEGROUP_MASTER (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE

					IF EXISTS
					(
						SELECT 1 FROM ASSY_RUNNINGPART_PREVIOUS (NOLOCK) WHERE ASSY_MODE IN ('PRODUCTION', 'REWORK')
							AND LINECODE = @LINECODE AND CURRENTPLANNEDQTY > ISNULL(PRODUCEDQTY, 0)
					)
					BEGIN
						--UPDATE PRODUCE QTY INTO ASSY_PRODUCTIONORDERMST
						UPDATE POM SET POM.PRODUCEDQTY = ISNULL(POM.PRODUCEDQTY, 0) + 1,
						POM.STATUS = CASE WHEN POM.QTY = ISNULL(POM.PRODUCEDQTY, 0) + 1 THEN '100' ELSE ISNULL(POM.STATUS,'0') END,
						LAST_UPD_BY = @USERID, LAST_UPD_STAMP = GETDATE()
						FROM ASSY_PRODUCTIONORDERMST (NOLOCK) POM
						INNER JOIN ASSY_RUNNINGPART_PREVIOUS (NOLOCK) RP ON POM.ORDERNO = RP.PRODUCTIONORDERNO AND POM.PARTNO = RP.ASSY_PARTNO
						WHERE RP.LINECODE = @LINECODE  
						AND POM.PROFITCENTERCODE = @PROFITCENTERCODE
						AND POM.STATUS <> '100'
						AND POM.WORKCENTERCODE 
						IN
						(
							-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
							-- SELECT  DISTINCT L.WORKCENTERCODE FROM LINEMST (NOLOCK) L
							SELECT L.WORKCENTERCODE FROM LINEMST (NOLOCK) L
							INNER JOIN ASSY_LINEGROUP_MASTER (NOLOCK) LG ON L.PROFITCENTERCODE = LG.PROFITCENTERCODE AND L.LINECODE = LG.LINECODE
							-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
							-- WHERE LG.GROUPCODE = (SELECT GROUPCODE FROM ASSY_LINEGROUP_MASTER (NOLOCK) WHERE LINECODE = @LINECODE) AND L.ISACTIVE = 1
							WHERE LG.GROUPCODE = @GROUPCODE AND L.ISACTIVE = 1 AND L.PROFITCENTERCODE = @PROFITCENTERCODE
						)

						UPDATE ASSY_RUNNINGPART_PREVIOUS SET PRODUCEDQTY = ISNULL(PRODUCEDQTY, 0) + 1 , BALANCEQTY = ISNULL(BALANCEQTY,0) - 1
							WHERE LINECODE = @LINECODE 

						--UPDATE ASSY_RUNNINGPART_PREVIOUS SET BALANCEQTY = ISNULL(CURRENTPLANNEDQTY, 0)-ISNULL(PRODUCEDQTY, 0)
						--	WHERE LINECODE = @LINECODE

						--UPDATE POM SET POM.STATUS = '100'  FROM ASSY_PRODUCTIONORDERMST (NOLOCK) POM
						--INNER JOIN ASSY_RUNNINGPART_PREVIOUS (NOLOCK) RP ON POM.ORDERNO = RP.PRODUCTIONORDERNO AND POM.PARTNO = RP.ASSY_PARTNO 							
						--WHERE RP.LINECODE = @LINECODE  
						--AND POM.PROFITCENTERCODE = @PROFITCENTERCODE
						--AND POM.STATUS <> '100'
						--AND POM.QTY = POM.PRODUCEDQTY
						--AND POM.WORKCENTERCODE 
						--IN
						--(
						--	-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
						--	-- SELECT  DISTINCT L.WORKCENTERCODE FROM LINEMST (NOLOCK) L
						--	SELECT L.WORKCENTERCODE FROM LINEMST (NOLOCK) L
						--	INNER JOIN ASSY_LINEGROUP_MASTER (NOLOCK) LG ON L.PROFITCENTERCODE = LG.PROFITCENTERCODE AND L.LINECODE = LG.LINECODE
						--	-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
						--	-- WHERE LG.GROUPCODE = (SELECT GROUPCODE FROM ASSY_LINEGROUP_MASTER (NOLOCK) WHERE LINECODE = @LINECODE) AND L.ISACTIVE = 1
						--	WHERE LG.GROUPCODE = @GROUPCODE AND L.ISACTIVE = 1 AND L.PROFITCENTERCODE = @PROFITCENTERCODE
						--)
							
						--IF EXISTS
						--( 
						--	SELECT 1 FROM ASSY_RUNNINGPART_PREVIOUS (NOLOCK) WHERE ASSY_MODE IN ('PRODUCTION', 'REWORK')
						--	AND LINECODE = @LINECODE AND CURRENTPLANNEDQTY = ISNULL(PRODUCEDQTY, 0)
						--)
						--BEGIN
							DELETE FROM ASSY_RUNNINGPART_PREVIOUS WHERE LINECODE = @LINECODE AND CURRENTPLANNEDQTY = ISNULL(PRODUCEDQTY, 0)
						--END
					END
					ELSE
					BEGIN
						--UPDATE PRODUCE QTY INTO ASSY_PRODUCTIONORDERMST
						UPDATE POM SET PRODUCEDQTY = ISNULL(PRODUCEDQTY, 0) + 1,
						POM.STATUS = CASE WHEN POM.QTY = ISNULL(POM.PRODUCEDQTY, 0) + 1 THEN '100' ELSE ISNULL(POM.STATUS,'0') END,
						LAST_UPD_BY = @USERID, LAST_UPD_STAMP = GETDATE()
						FROM ASSY_PRODUCTIONORDERMST (NOLOCK) POM
						INNER JOIN ASSY_RUNNINGPART (NOLOCK) RP ON POM.ORDERNO = RP.PRODUCTIONORDERNO AND POM.PARTNO = RP.ASSY_PARTNO
						WHERE RP.LINECODE = @LINECODE
						AND POM.PROFITCENTERCODE = @PROFITCENTERCODE
						AND POM.STATUS <> '100'
						AND POM.WORKCENTERCODE
						IN
						(
							-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
							-- SELECT  DISTINCT L.WORKCENTERCODE FROM LINEMST (NOLOCK) L
							SELECT L.WORKCENTERCODE FROM LINEMST (NOLOCK) L
							INNER JOIN ASSY_LINEGROUP_MASTER (NOLOCK) LG ON L.PROFITCENTERCODE = LG.PROFITCENTERCODE AND L.LINECODE = LG.LINECODE
							-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
							-- WHERE LG.GROUPCODE = (SELECT GROUPCODE FROM ASSY_LINEGROUP_MASTER (NOLOCK) WHERE LINECODE = @LINECODE) AND L.ISACTIVE = 1
							WHERE LG.GROUPCODE = @GROUPCODE AND L.ISACTIVE = 1 AND L.PROFITCENTERCODE = @PROFITCENTERCODE
						)

						UPDATE ASSY_PRODUCTIONORDER_PARAMETERSETTING SET PRODUCTIONQTY = ISNULL(PRODUCTIONQTY, 0) + 1, BALANCEQTY = ISNULL(BALANCEQTY,0) - 1
							WHERE LINECODE = @LINECODE   AND PROFITCENTERCODE = @PROFITCENTERCODE
						
						--UPDATE ASSY_PRODUCTIONORDER_PARAMETERSETTING SET BALANCEQTY = ISNULL(CURRENTPLANNEDQTY, 0)-ISNULL(PRODUCTIONQTY, 0)
						--	WHERE LINECODE = @LINECODE   AND PROFITCENTERCODE = @PROFITCENTERCODE
						
						--UPDATE POM SET POM.STATUS = '100'  FROM ASSY_PRODUCTIONORDERMST (NOLOCK) POM
						--INNER JOIN ASSY_RUNNINGPART (NOLOCK) RP ON POM.ORDERNO = RP.PRODUCTIONORDERNO AND POM.PARTNO = RP.ASSY_PARTNO 							
						--WHERE RP.LINECODE = @LINECODE  
						--AND POM.PROFITCENTERCODE = @PROFITCENTERCODE
						--AND POM.STATUS <> '100'
						--AND POM.QTY = POM.PRODUCEDQTY
						--AND POM.WORKCENTERCODE 
						--IN
						--(
						--	-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
						--	-- SELECT  DISTINCT L.WORKCENTERCODE FROM LINEMST (NOLOCK) L
						--	SELECT L.WORKCENTERCODE FROM LINEMST (NOLOCK) L
						--	INNER JOIN ASSY_LINEGROUP_MASTER (NOLOCK) LG ON L.PROFITCENTERCODE = LG.PROFITCENTERCODE AND L.LINECODE = LG.LINECODE
						--	-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
						--	-- WHERE LG.GROUPCODE = (SELECT GROUPCODE FROM ASSY_LINEGROUP_MASTER (NOLOCK) WHERE LINECODE = @LINECODE) AND L.ISACTIVE = 1
						--	WHERE LG.GROUPCODE = @GROUPCODE AND L.ISACTIVE = 1 AND L.PROFITCENTERCODE = @PROFITCENTERCODE
						--)
					END
					
					SELECT @RETURNVALUE = 'SUCCESS', @RETURNINT = 1
				END
			END TRY
		
			BEGIN CATCH			
				SET @RETURNVALUE = 	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
				CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
				CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_MESSAGE() AS VARCHAR(1500))		
				SET @RETURNINT = 2
				--ROLLBACK TRAN
				RAISERROR(@RETURNVALUE, 16, 1)
			END CATCH

			RETURN
		END
		
		ELSE IF @CONDITION = 'GET_PREFIX_SUFFIX_LIST'
		BEGIN
			SELECT LTRIM(RTRIM(ISNULL(PREFIX,''))), LTRIM(RTRIM(ISNULL(SUFFIX,''))) FROM MACHINEDTL (NOLOCK) WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
				AND(ISNULL(PREFIX,'') <> '' AND ISNULL(SUFFIX,'') <> '') --ORDER BY 1
			
			RETURN
		END
		ELSE IF @CONDITION = 'UPDATE_FV_QC_OK_FAIL_DATA_IN_MAINSERVER'
		BEGIN
			BEGIN TRY
			IF EXISTS (SELECT 1 FROM ASSY_LINEASSYSTATUS (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND
				MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND STATUS = 'FL' AND BARCODE = @BARCODE)
			BEGIN
				DELETE FROM ASSY_LINEASSYSTATUS WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND
					MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND STATUS = 'FL' AND BARCODE = @BARCODE
			END
			---- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING STOCK DEDUCTION ----
			ELSE
			BEGIN
					    --CHANGED BY RAVI ON 08-08-17 TO UPDATE DATA INTO ASSY_MACHINEWISE_RUNNINGPART
					    IF ISNULL( @ALLOW2PARTS,0)=1
						BEGIN
								IF EXISTS
								( 
										SELECT 1 FROM ASSY_MACHINEWISE_RUNNINGPART WITH(NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
										AND OPERATIONCODE = @OPERATIONCODE
								)
								BEGIN
										UPDATE ASSY_MACHINEWISE_RUNNINGPART SET PARTNO = @PARTNUMBER,UPDATEDDATE=GETDATE() 
										WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE	AND OPERATIONCODE =@OPERATIONCODE
								END
								ELSE 
									BEGIN
										INSERT INTO ASSY_MACHINEWISE_RUNNINGPART(PROFITCENTERCODE,LINECODE,OPERATIONCODE,MACHINECODE ,PARTNO,CREATEDDATE)
										SELECT @PROFITCENTERCODE,@LINECODE,@OPERATIONCODE,@MACHINECODE,@PARTNUMBER,GETDATE()

									END
						END
				--START-- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING STOCK DEDUCTION
				IF ((SELECT ISNULL(ISMATFEEDREQUIRED, 0) FROM LINEMST WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE) = 1)
				BEGIN
					EXEC ASSY_PROC_MATERIALFEEDINGVALIDATION
					@CONDITION = 'MAT_FEED_STOCK_DEDUCTION',
					@PROFITCENTERCODE = @PROFITCENTERCODE, 
					@LINECODE = @LINECODE, 
					@USERID = @USERID, 
					@PARTNUMBER = @PARTNUMBER, 
					@BARCODE = @BARCODE
				END
				--END-- ADDED BY RASHID SIDDIQUI ON 28TH JUNE 2016 FOR MATERIAL FEEDING STOCK DEDUCTION
			END
				--MODIFIED BY SUDESH ON 20170516 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
				INSERT INTO ASSY_LINEASSYSTATUS
				(
					PROFITCENTERCODE, 
					LINECODE, 
					MACHINECODE, 
					OPERATIONCODE, 
					STATIONCODE, 
					BARCODE, 
					STATUS, 
					FAILCOUNT, 
					DATECODE, 
					PARTNO, 
					SCANTIMESTAMP, 
					RESULTTIMESTAMP, 
					USERID,
					PRODUCTIONORDERNO,
					Live_Datecode
				)

				SELECT 
					@PROFITCENTERCODE, 
					@LINECODE, 
					@MACHINECODE, 
					@OPERATIONCODE, 
					@STATIONCODE, 
					@BARCODE, 
					@STATUS, 
					@PARTFAILEDCOUNT, 
					@DATECODE,
					@PARTNUMBER, 
					@SCANTIMESTAMP, 
					@RESULTTIMESTAMP, 
					@USERID,
					@PRODUCTIONORDERNO,
					@Live_Datecode

				----START-- ADDED BY RASHID SIDDIQUI ON 08TH AUGUST 2016 FOR MATERIAL FEEDING STOCK DEDUCTION
				IF ((SELECT ISNULL(ISPRODCONFREQUIRED, 0) FROM LINEMST WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE) = 1)
				BEGIN
					IF EXISTS (SELECT 1 FROM ASSY_MAT_FEED_STATUS_ISPRODCONF WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE)
					BEGIN
						UPDATE ASSY_FGCHILDPARTCONSUMPTION SET ISACTIVE = 2 WHERE WH_CODE = @PROFITCENTERCODE AND LINE_CODE = @LINECODE AND ISACTIVE = 1
						DELETE FROM ASSY_MAT_FEED_STATUS_ISPRODCONF WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
					END
				END

				--ADDED BY RAVI ON 18/03/16-------------
				DELETE FROM ASSY_LINEASSYSTATUS_FV_LASTTESTED_BARCODE WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
			
				INSERT INTO ASSY_LINEASSYSTATUS_FV_LASTTESTED_BARCODE (PROFITCENTERCODE, LINECODE, MACHINECODE, OPERATIONCODE, BARCODE, DATECODE, PARTNO, SCANTIMESTAMP, RESULTTIMESTAMP)
				SELECT @PROFITCENTERCODE, @LINECODE, @MACHINECODE, @OPERATIONCODE, @BARCODE, @DATECODE, @PARTNUMBER, @SCANTIMESTAMP, @RESULTTIMESTAMP

				--------------------------END--------------
				SET @RETURNVALUE = 'SUCCESS'
				SET @RETURNINT = 1
			END TRY
			
			BEGIN CATCH			
				SET @RETURNVALUE = 	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
				CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
				CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_MESSAGE() AS VARCHAR(1500))		
				SET @RETURNINT = 2
				--ROLLBACK TRAN
				RAISERROR(@RETURNVALUE, 16, 1)
			END CATCH												
			RETURN
		END

		ELSE IF @CONDITION = 'UPDATE_FINALVIEWING_FROMLOCALDBTOMAIN'
		BEGIN
			DECLARE @OPCODE VARCHAR(20) = '', @FV_COUNT INT = 0, @ERRORCOUNT INT = -1
			DECLARE @DROP_RECORDS INT = 0
			
			SELECT @DROP_RECORDS = COUNT(*) FROM ASSY_LINEASSYSTATUS_NETWORK_DROP_RECORDS (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE --AND LINECODE = @LINECODE
			
			IF (@DROP_RECORDS > 0)
			BEGIN
				--SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL  WITH (NOLOCK) 
				--	WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

				SELECT @OPCODE = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)
				
				IF @OPCODE = ''
				BEGIN
					IF (LEFT(@LINECODE, 1) IN ('M','L'))
						SET @OPCODE = 'OCFV'
					ELSE IF(LEFT(@LINECODE, 1) = 'P')
						SET @OPCODE = 'OCFVSTMC'
				END

				IF (@OPCODE ! = '')
				BEGIN
					--MODIFIED BY SUDESH ON 20170515 FOR NEW COLUMN PRODUCTIONORDERNO IN TABLE ASSY_LINEASSYSTATUS_RUNNING
					SET @EXECQUERY = '
					INSERT INTO ' + @LINKSERVERNAME + '.DBO.ASSY_LINEASSYSTATUS (PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,STATIONCODE,BARCODE,STATUS,FAILCOUNT,DATECODE,PARTNO,SCANTIMESTAMP,RESULTTIMESTAMP,ACTIVE,USERID,ISTALLYCHARTAPPROVED,TRANSACTION_NUMBER





,ISCONFIRMED,KANBAN_ID,ERP_CONF_TIMESTAMP,ISREWORKPART,IS_MANUAL,PRODUCTIONORDERNO,Live_Datecode)
					SELECT PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,STATIONCODE,BARCODE,STATUS,FAILCOUNT,DATECODE,PARTNO,SCANTIMESTAMP,RESULTTIMESTAMP,ACTIVE,USERID,ISTALLYCHARTAPPROVED,TRANSACTION_NUMBER,ISCONFIRMED,KANBAN_ID,ERP_CONF_TIMESTAMP,ISREWORKPART,


IS_MANUAL,PRODUCTIONORDERNO,Live_Datecode FROM ASSY_LINEASSYSTATUS (NOLOCK) WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + '''
					AND LINECODE = ''' + @LINECODE + ''' AND OPERATIONCODE = ''' + @OPCODE + ''' AND BARCODE IN (SELECT BARCODE FROM ASSY_LINEASSYSTATUS_NETWORK_DROP_RECORDS (NOLOCK) WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE +


 ''')
					AND BARCODE NOT IN (SELECT BARCODE FROM ' + @LINKSERVERNAME + '.DBO.ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' AND OPERATIONCODE = ''' + @OPCODE + ''')
					'
					PRINT @EXECQUERY
					EXEC (@EXECQUERY)
					
					SET @ERRORCOUNT = @@ERROR
					
					IF @ERRORCOUNT > 0
					BEGIN
						SELECT @RETURNVALUE = '', @RETURNINT = 0
					RETURN
					END
				END
				
				IF (@ERRORCOUNT = 0)
				BEGIN
				TRUNCATE TABLE ASSY_LINEASSYSTATUS_NETWORK_DROP_RECORDS
				SELECT @RETURNVALUE = 'SUCCESS', @RETURNINT = 1
				END
			END
			ELSE
			BEGIN
				SELECT @RETURNVALUE = 'NORECORDFOUND', @RETURNINT = 1
			END
		END
		ELSE IF @CONDITION = 'GETASSYRUNNINGPART'
		BEGIN
			SELECT LINECODE, DATECODE, ASSY_PARTNO, PRODUCTIONORDERNO, ASSY_MODE, PARTTYPE, PROFITCENTERCODE, CUSTOMERPARTNO FROM ASSY_RUNNINGPART (NOLOCK)
				WHERE LINECODE = @LINECODE AND PROFITCENTERCODE = @PROFITCENTERCODE
			RETURN
		END
		ELSE IF @CONDITION = 'DELETE_RUNNINGPART_NOTPRINT'
		BEGIN
			DECLARE @ASSY_DATECODE CHAR(4) = ''
			
			IF ISNULL(RTRIM(@CHANGEOVER_DATECODE), '') = 'NA'
			BEGIN
				EXEC ASSY_PROC_DATECODE @PROFITCENTERCODE = @PROFITCENTERCODE, @RETURNVALUE = @CHANGEOVER_DATECODE OUTPUT      
			END

			IF ISNULL(@CHANGEOVER_DATECODE, '') ! = ''
			BEGIN
				-- COMMENETED BY RASHID ON 20170501 FOR OPTIMIZING OF QUERIES
				--SELECT TOP 1 @PARTNO = ASSY_PARTNO, @ASSY_DATECODE = DATECODE FROM ASSY_RUNNINGPART (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				SELECT @PARTNO = ASSY_PARTNO, @ASSY_DATECODE = DATECODE FROM ASSY_RUNNINGPART (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
				AND LINECODE = @LINECODE

				IF @ASSY_DATECODE ! = @CHANGEOVER_DATECODE
				BEGIN
					SELECT @OPERATIONCODE = RTRIM(LTRIM(OPERATIONCODE)) FROM ROUTINGCONFIGLINEWISE (NOLOCK) 
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND OPERATIONSEQNO = 1

					IF NOT EXISTS
						(SELECT 1 FROM ASSY_BARCODE_PRINTED_COUNTER A (NOLOCK)
							INNER JOIN
							ASSY_RUNNINGPART R (NOLOCK) 
							ON A.PROFITCENTERCODE = R.PROFITCENTERCODE AND A.LINECODE = R.LINECODE
							WHERE A.LINECODE = @LINECODE AND ISNULL(A.PRINTEDQTY, 0) > 0 AND R.PROFITCENTERCODE = @PROFITCENTERCODE
						)
					BEGIN
						DELETE FROM ASSY_RUNNINGPART WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
						
						SET @EXECQUERY = ''
						
						SET @EXECQUERY = '
						DELETE FROM ' + @LINKSERVERNAME + '.DBO.ASSY_RUNNINGPART WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''''
						PRINT @EXECQUERY
						EXEC (@EXECQUERY)
						
						SELECT @RETURNVALUE = 'Y', @RETURNINT = 1
					END
					ELSE
					BEGIN
						SELECT @RETURNVALUE = 'N', @RETURNINT = 1
					END
				END
			END
		END

		ELSE IF @CONDITION = 'ASSY_LINEASSYSTATUS_NETWORK_DROP_RECORDS'
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM ASSY_LINEASSYSTATUS_NETWORK_DROP_RECORDS (NOLOCK) WHERE BARCODE = @BARCODE)
			BEGIN
				INSERT INTO ASSY_LINEASSYSTATUS_NETWORK_DROP_RECORDS
				(
					PROFITCENTERCODE, 
					LINECODE, 
					MACHINECODE, 
					BARCODE
				)

				SELECT 
					@PROFITCENTERCODE, 
					@LINECODE, 
					@MACHINECODE, 
					@BARCODE
			END
		END

		ELSE IF @CONDITION = 'GET_COUPLING_STATIONS_PARAMETER_DATA'
		BEGIN
			SELECT RTRIM(LTRIM(PARAMETER_C2))PARAMETER_C2, RTRIM(LTRIM(PARAMETER_VALUE))PARAMETER_VALUE FROM PARAMETER_MST (NOLOCK) 
				WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'COUPLING' AND  WH_CODE = @PROFITCENTERCODE 
			
			SET @RETURNINT = 1
		END

		--ADDED BY RAVI ON 01-06-2016 FOR JHAGADIA
		IF @CONDITION='IS_LABEL_PRINTING_REQUIRED_AT_FV'
		BEGIN
				 IF EXISTS
				 (	
					 SELECT 1 FROM ROUTINGCONFIGLINEWISE WITH (NOLOCK) WHERE PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE=@LINECODE 
					 AND MACHINECODE=DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE) AND ISNULL(LABELPRINTING,0)=1 
				 )
				 BEGIN
				 	IF(rtrim(ISNULL(@PARTNUMBER, '')) = '')
					BEGIN
						SET @RETURNVALUE = 'Y'
					END
					ELSE
					IF EXISTS
					(SELECT 1 FROM ROUTINGCONFIGPARTWISE WITH (NOLOCK) WHERE PROFITCENTERCODE =@PROFITCENTERCODE
						AND MACHINECODE=DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE) 
						AND ISNULL(LABELPRINTING,0)=1
						AND PartNo=@PARTNUMBER
					)
					BEGIN
						SET @RETURNVALUE = 'Y'
					END
					ELSE
					BEGIN
						SET @RETURNVALUE = 'N'
					END
				 END
				 ELSE 
				 BEGIN
					SET @RETURNVALUE = 'N'
				 END
			
			SET @RETURNINT=1
		END

		--ADDED BY RAVI ON 01-06-2016 FOR JHAGADIA
		IF @CONDITION='GET_PRN_FILE_FOR_FV'
		BEGIN
				SELECT @RETURNVALUE=PRNFILE FROM ASSY_PRN_GROUPMASTER WITH(NOLOCK) WHERE GROUPCODE ='GC_JHAGADIA_FINALVIEWING_STATION'			
			    SET @RETURNINT=1
				RETURN
		END
		--ADDED BY RAVI ON 02-08-2016 FOR JHAGADIA
		IF @CONDITION='RUN2PARTS_AT_SAMETIME'
		BEGIN
				--SELECT @RETURNVALUE=PRNFILE FROM ASSY_PRN_GROUPMASTER WITH(NOLOCK) WHERE GROUPCODE ='GC_JHAGADIA_FINALVIEWING_STATION'	
				IF EXISTS
				(
				 SELECT 1 FROM LINEMST WITH(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE 
				 AND ISNULL(ISACTIVE,0)=1 AND ISNULL(ALLOW2PARTS,0)=1 
				)		
				 BEGIN
						SET @RETURNVALUE = 'Y'
				 END
				 ELSE 
				 BEGIN
						SET @RETURNVALUE = 'N'
				 END			
				SET @RETURNINT=1
				RETURN
		END
		ELSE IF @CONDITION='ASSY_LINEASSYSTATUS_RFID_NETWORK_DROP_RECORDS'
		BEGIN
				IF NOT EXISTS 
				(
					SELECT 1 FROM DBO.ASSY_FINALVIEWING_RFID_BARCODE_NETWORK_DROP(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE
					AND RFID = @BARCODE AND MACHINECODE=@MACHINECODE
				)
				BEGIN
					INSERT INTO ASSY_FINALVIEWING_RFID_BARCODE_NETWORK_DROP
					(
						PROFITCENTERCODE,
						LINECODE,
						MACHINECODE,
						RFID
					)
					SELECT 
						@PROFITCENTERCODE,
						@LINECODE,
						@MACHINECODE,
						@BARCODE
				END
				RETURN
		END

		ELSE IF @CONDITION = 'UPDATE_RFID_DATA_FROMLOCALDBTOMAIN'
		BEGIN
			SELECT @DROP_RECORDS = COUNT(RFID) FROM DBO.ASSY_FINALVIEWING_RFID_BARCODE_NETWORK_DROP (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE
																									AND LINECODE = @LINECODE
			IF (@DROP_RECORDS > 0)
			BEGIN
						SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL  WITH (NOLOCK) 
						WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

						SET @OPCODE=@OPERATIONCODE
					--SELECT @OPCODE = DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE)	
					IF (@OPCODE != '')
					BEGIN						

						DECLARE @TV AS TABLE
						(
							 ID INT IDENTITY(1,1),
							 RFID VARCHAR(100)
						)
						INSERT INTO @TV(RFID)					
						SELECT RFID FROM DBO.ASSY_FINALVIEWING_RFID_BARCODE_NETWORK_DROP (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
			
							DECLARE	@COUNTERSTART AS INT=1, @RFIDTAGS VARCHAR(100)																			
							 WHILE (@COUNTERSTART<= @DROP_RECORDS)
							 BEGIN
										  SELECT @RFIDTAGS=RFID FROM @TV WHERE ID=@COUNTERSTART
								 						  
										  SET @EXECQUERY = 'IF  NOT EXISTS(SELECT RFID FROM ' + @LINKSERVERNAME + '.DBO.ASSY_FINALVIEWING_RFID_BARCODE_MAPPING 
														WITH (NOLOCK) WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + ''' AND LINECODE = ''' + @LINECODE + ''' 
														AND RFID= ''' + @RFIDTAGS + ''')
											BEGIN
													INSERT INTO ' + @LINKSERVERNAME + '.DBO.ASSY_FINALVIEWING_RFID_BARCODE_MAPPING(PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,RFID,BARCODE,STATUS,
													PARTNO,DATECODE,PRINTEDTIMESTAMP,CALIPERSERNO,CALIPERDATECODE)
													SELECT PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,RFID,BARCODE,STATUS,PARTNO,DATECODE,PRINTEDTIMESTAMP,CALIPERSERNO,CALIPERDATECODE
													FROM ASSY_FINALVIEWING_RFID_BARCODE_MAPPING (NOLOCK) WHERE PROFITCENTERCODE = ''' + @PROFITCENTERCODE + '''
													AND LINECODE = ''' + @LINECODE + ''' AND OPERATIONCODE = ''' + @OPCODE + ''' AND
													RFID='''+@RFIDTAGS+'''
											END'
											
											EXEC (@EXECQUERY)
											--PRINT @EXECQUERY
											DELETE FROM ASSY_FINALVIEWING_RFID_BARCODE_NETWORK_DROP WHERE RFID=@RFIDTAGS AND PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
											SET @COUNTERSTART=@COUNTERSTART+1
						END
				
					SET @RETURNVALUE = 'SUCCESS'
					SET @RETURNINT = 1
				END
			END
			ELSE
			BEGIN
				SET @RETURNVALUE = 'NORECORDFOUND'
				SET @RETURNINT = 1
			END
		END		

		--ADDED BY RASHID ON 20170601 FOR JHAGADIA
		ELSE IF @CONDITION = 'GET_PART_NO_STATION_WISE_LIST'
		BEGIN
				SELECT AMR.PROFITCENTERCODE, AMR.MACHINECODE, M.MACHINENAME, AMR.OPERATIONCODE, O.OPERATIONNAME, ISNULL(PARTNO,'') PARTNO FROM ASSY_MACHINEWISE_RUNNINGPART AMR WITH (NOLOCK)
					INNER JOIN OPERATIONMST O WITH (NOLOCK)
						ON AMR.PROFITCENTERCODE = O.PROFITCENTERCODE AND AMR.OPERATIONCODE = O.OPERATIONCODE
					INNER JOIN MACHINEMST M WITH (NOLOCK)
						ON AMR.PROFITCENTERCODE = M.PROFITCENTERCODE AND AMR.MACHINECODE = M.MACHINECODE
					WHERE AMR.PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
			    
				SELECT @RETURNINT = 1
				RETURN
		END
		--ADDED BY RASHID ON 20170601 FOR JHAGADIA
		ELSE IF @CONDITION = 'GET_NON_HMI_STATION_LIST'
		BEGIN
				SELECT RCLW.OPERATIONCODE, O.OPERATIONNAME FROM ROUTINGCONFIGLINEWISE RCLW WITH (NOLOCK)
					INNER JOIN OPERATIONMST O WITH (NOLOCK)
						ON RCLW.PROFITCENTERCODE = O.PROFITCENTERCODE AND RCLW.OPERATIONCODE = O.OPERATIONCODE
							WHERE ISHMIRECIPEAVAILABLE = 0 AND RCLW.PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND OPERATIONREQUIRED = 1 AND TRACEABILITY = 1
								ORDER BY OPERATIONSEQNO
			    
				SELECT @RETURNINT = 1
				RETURN
		END
		--ADDED BY RASHID ON 20170601 FOR JHAGADIA
		ELSE IF @CONDITION = 'GET_FAMILY_RUNNING_PART_LIST'
		BEGIN
				SELECT ASSY_PARTNO PARTNO FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE
				UNION
			    SELECT ASSY_PARTNO PARTNO FROM ASSY_RUNNINGPARTFAMILY WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

				SELECT @RETURNINT = 1
				RETURN
		END
		--ADDED BY RASHID ON 20170601 FOR JHAGADIA
		ELSE IF @CONDITION = 'UPDATE_PART_NO_STATION_WISE'
		BEGIN
			
			--ADDED BY RASHID ON 20170613 FOR JHAGADIA PC
			IF EXISTS (SELECT 1 FROM LINEMST WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND ISPRODCONFREQUIRED = 1)
			BEGIN
				IF ((SELECT DBO.ASSY_FN_GET_FINALVIEWING_OPERATIONCODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE)) = @OPERATIONCODE)
				BEGIN
					DECLARE @PRODCONFPARTNO VARCHAR(30) = '', @IS_POSTED BIT = 0
					SELECT TOP 1 @PRODCONFPARTNO = PARTNO, @IS_POSTED = IS_POSTED FROM ASSY_PASSED_ITEMS_AT_FV WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE ORDER BY ENT_DT DESC

					IF ISNULL(@PRODCONFPARTNO,'') != ''
					BEGIN
						IF ISNULL(@IS_POSTED,0) = 0
						BEGIN
							SELECT @RETURNVALUE = 'PC_POSTING_PENDING', @RETURNINT = 1
							RETURN
						END
					END
				END
			END

			SELECT @MACHINECODE = ''
			--SELECT @MACHINECODE = DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE)
			
			IF NOT EXISTS (SELECT 1 FROM ASSY_MACHINEWISE_RUNNINGPART WITH (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE)
			BEGIN
				SELECT @MACHINECODE = MachineCode FROM RoutingConfigLineWise (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE

				INSERT INTO ASSY_MACHINEWISE_RUNNINGPART (PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,STATIONCODE,PARTNO,CREATEDDATE)
				SELECT @PROFITCENTERCODE, @LINECODE, @MACHINECODE, @OPERATIONCODE, 1, @PARTNUMBER, GETDATE()
			END
			ELSE
			BEGIN
				UPDATE ASSY_MACHINEWISE_RUNNINGPART SET PARTNO = @PARTNUMBER, UPDATEDDATE = GETDATE()
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
			END

			SELECT @RETURNINT = 1
			SELECT @RETURNVALUE = 'SUCCESS'
			RETURN
		END
		--ADDED BY RASHID ON 20170601 FOR JHAGADIA		
		ELSE IF @CONDITION = 'CHECKAUTOTALLYCHARTENABLE'
		BEGIN 
			IF EXISTS
			(
				SELECT 1 FROM LINEMST WITH(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE 
				AND ISNULL(ISACTIVE,0) = 1 AND ISNULL(AUTOTALLYCHARTENABLE,0) = 1
			)		
			BEGIN
				SET @RETURNVALUE = 'Y'
			END
			ELSE
			BEGIN
				SET @RETURNVALUE = 'N'
			END
			SET @RETURNINT=1
			RETURN
		END
			-- ADDED BY SACHIN 20170519
		-- ISMACHINESCANREQUIRED : CHECK USER WANT TO SCAN MACHINE CODE FIRST THEN BARCODE 
		--						   USING BLUETOOTH SCANNER
		IF @CONDITION ='ISMACHINESCANREQUIRED'
		BEGIN
		--ISMACHINESCANREQUIRED 
		DECLARE @ISMACHINESCANREQUIRED VARCHAR(2)
		SELECT @ISMACHINESCANREQUIRED =DBO.ASSY_FN_GET_PARAMETER_VALUE('ISMACHINESCANREQUIRED',@LINECODE,'',@PROFITCENTERCODE)

				IF(ISNULL(@ISMACHINESCANREQUIRED,'N')='Y')
				BEGIN
				SET @RETURNVALUE = 'Y'
				END
				ELSE
				BEGIN
				SET @RETURNVALUE = 'N'
				END
		
				SET @RETURNINT=1
				RETURN 
		END	
		-- ADDED BY SACHIN 20170519
		-- PROVIDE MACHINE INFORMATION 
		  IF @CONDITION='GET_MACHINE_INFO'
		BEGIN		
				SELECT TOP 1 LINECODE,MACHINECODE,OPERATIONCODE,STATIONCODE   FROM DBO.MACHINEDTL (NOLOCK)  
				WHERE MACHINECODE=@MACHINECODE
				AND LINECODE =@LINECODE AND PROFITCENTERCODE =@PROFITCENTERCODE
				SET @RETURNINT=1
				SET @RETURNVALUE='SUCCESS'
				RETURN
		END
		-- ADDED BY RASHID 20170705
		-- GET SUB STATION MACHINE CODE
		ELSE IF @CONDITION='GETSUBMACHINECODE'
		BEGIN		
				SELECT S.MACHINECODE,R.OPERATIONCODE, S.OPERATIONCODE AS SUBOPERATIONCODE, S.SUBMACHINECODE FROM ROUTINGCONFIGLINEWISEFORSUBSTATION S WITH (NOLOCK) 
				JOIN ROUTINGCONFIGLINEWISE R WITH(NOLOCK)
					ON R.PROFITCENTERCODE =S.PROFITCENTERCODE 
				       AND R.LINECODE =S.LINECODE
					   AND R.MACHINECODE=S.MACHINECODE
					   AND ISNULL(R.TRACEABILITY,0) =1
					   AND ISNULL(R.ISPOKAYOKEFORSUBSTATION,0)=1
					WHERE R.PROFITCENTERCODE =@PROFITCENTERCODE AND R.LINECODE =@LINECODE AND ISNULL(S.POKA_YOKE_ALLOWED,0) = 1
				
				SELECT MACHINECODE,OPERATIONCODE,ISNULL(ISPOKAYOKEFORSUBSTATION,0)ISPOKAYOKEFORSUBSTATION FROM DBO.ROUTINGCONFIGLINEWISE WITH(NOLOCK)
				WHERE PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE =@LINECODE AND ISNULL(ISPOKAYOKEFORSUBSTATION,0)=0
				
				SET @RETURNINT=1
				SET @RETURNVALUE='SUCCESS'
				RETURN
		END
		ELSE IF @CONDITION='ISRFIDBASED_TRACEABILITY'
		BEGIN		
			   IF EXISTS
			   (
				 SELECT 1 FROM DBO.LINEMST WITH(NOLOCK) 
				 WHERE PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE =@LINECODE AND ISNULL(ISRFIDBASEDSCANNING,0) = 1
			   )
				BEGIN
				     	SET @RETURNVALUE='Y'
				END
				ELSE
				BEGIN
				      	SET @RETURNVALUE='N'
				END
				SET @RETURNINT=1			
				RETURN
		END
		ELSE IF @Condition = 'GetRFIDFromRoboBarcode'
		BEGIN
			SET @RETURNVALUE = (SELECT TOP 1 ISNULL(RFID,@Barcode) FROM ASSY_FV_ROBOT_INSPECTION_SERIAL_HOLD (NOLOCK) WHERE PRINTED_BARCODE=@Barcode ORDER BY ent_stamp DESC)
			SELECT @ReturnInt = 1
			SELECT @RETURNVALUE
			RETURN 
		END
		ELSE IF @Condition = 'CaptureRoboParametersAndResult'
		BEGIN
				;WITH CTE_LATEST AS
				(
					SELECT 
						A.*,
						ROW_NUMBER() OVER (
							PARTITION BY A.QR_CODE 
							ORDER BY A.RESULT_TIMESTAMP DESC
						) AS RN
					FROM TD_ROBO_DATA_WITH_PARAMETER A WITH (NOLOCK)
					WHERE A.TS_FLAG = '0' AND ISNULL(QR_CODE,'') <> '' 
					AND RESULT_TIMESTAMP > DATEADD(DAY, -5, GETDATE())	--to keep search range short
				)

				SELECT TOP (@FV_ROBO_BUFFER_COUNT) C.Barcode,C.MachineCode,C.OperationCode,A.* INTO #ROBO_RESULT_PARAMETERS 
				--FROM TD_ROBO_DATA_WITH_PARAMETER A WITH (NOLOCK)
				FROM CTE_LATEST A WITH (NOLOCK)
				INNER JOIN ASSY_FV_ROBOT_INSPECTION_SERIAL_HOLD B WITH (NOLOCK) ON A.QR_CODE=B.PRINTED_BARCODE
			 	INNER JOIN Assy_Scan_OK_ROBO C WITH (NOLOCK) ON B.rfiD=C.Barcode
				WHERE ISNULL(A.TS_FLAG,'0')='0' and ISNULL(C.IsProcess,0)=0 and C.IsScan=1 
				--and A.Result=1		--commented as discussed both pass/fail will be captured
				--AND A.RESULT_TIMESTAMP > C.Timestamp 
				ORDER BY A.RESULT_TIMESTAMP

				IF EXISTS(SELECT TOP 1 * FROM #ROBO_RESULT_PARAMETERS)
				BEGIN
					
					ALTER TABLE #ROBO_RESULT_PARAMETERS ADD start_ BIT
					ALTER TABLE #ROBO_RESULT_PARAMETERS ADD complete_ BIT

					WHILE EXISTS(SELECT TOP 1 * FROM #ROBO_RESULT_PARAMETERS WHERE start_ IS NULL)
					BEGIN
						SELECT TOP 1 @QR_CODE=QR_CODE, @Barcode=Barcode, @RESULT=CASE WHEN ISNULL(RESULT,0)=1 THEN 'PS' ELSE 'FL' END,
						@MACHINECODE=MachineCode, @OPERATIONCODE=OperationCode 
						FROM #ROBO_RESULT_PARAMETERS
						WHERE start_ IS NULL
						ORDER BY RESULT_TIMESTAMP
						
						UPDATE TOP (1) #ROBO_RESULT_PARAMETERS SET start_ = 1 
						WHERE QR_CODE = @QR_CODE AND start_ IS NULL

						BEGIN TRY
							BEGIN TRANSACTION RoboParameter

							SET @XmldataLK  = 
							(SELECT TOP 1 P1,P2,P3,P4,P5,P6,P7,P8,P9,P10,P11,P12,P13,P14,P15,P16,P17,P18,P19,P20,P21,P22,P23,P24,P25,P26 
							FROM #ROBO_RESULT_PARAMETERS 
							WHERE QR_CODE=@QR_CODE AND start_=1 order by RESULT_TIMESTAMP desc
							FOR XML PATH(''))
				
							INSERT INTO @TagData(TagName,TagValue)
							SELECT TagName,TagValue FROM  ( 
							SELECT 
							ROW_NUMBER()OVER(PARTITION BY   TagName ORDER BY  TagValue) rn,* FROM ( 
							SELECT  i.value('local-name(.)','VARCHAR(100)')  TagName,
							i.value('.','VARCHAR(100)') TagValue 
							FROM @xmldataLK.nodes('//*') x(i)) tmp) tmp1
							
							INSERT INTO @ParameterData(ProfitCenterCode,LineCode,MachineCode,
							OperationCode,StationCode,Barcode,TagName,Value,Result,Datecode,UserID)
							SELECT @PROFITCENTERCODE,@LINECODE,@MACHINECODE,
							@OPERATIONCODE,'1',@Barcode,TagName,TagValue,@RESULT,'',@USERID 
							FROM @TagData
							
							EXEC Assy_Proc_PLCIntegration_Jhagadia @Operation = 'INSERT_PLC_PARAMS',@LineCode = @LINECODE,
							@tblParameters = @ParameterData,@UpdateDataMannual=1

							INSERT INTO Assy_Scan_OK_ROBO_history(ProfitCenterCode,LineCode,MachineCode,OperationCode,
							WIPBufferSeq,Barcode,isScan,Timestamp,isProcess,Hist_Dt)
							SELECT TOP 1 C.ProfitCenterCode,C.LineCode,C.MachineCode,C.OperationCode,
							C.WIPBufferSeq,C.Barcode,C.IsScan,C.Timestamp,1,getdate()  
							FROM Assy_Scan_OK_ROBO C INNER JOIN #ROBO_RESULT_PARAMETERS B ON C.Barcode=B.Barcode

							--DELETE FROM TD_ROBO_DATA_WITH_PARAMETER where QR_CODE=@QR_CODE	--commented
							DELETE FROM Assy_Scan_OK_ROBO where barcode=@BARCODE				--commented --uncommented to delete

							--UPDATE C SET C.isprocess=1 FROM Assy_Scan_OK_ROBO C 
							--INNER JOIN #ROBO_RESULT_PARAMETERS B ON C.Barcode=B.Barcode

							UPDATE A SET A.TS_FLAG='1' FROM TD_ROBO_DATA_WITH_PARAMETER A WITH (NOLOCK)
							INNER JOIN #ROBO_RESULT_PARAMETERS B ON A.QR_CODE=B.QR_CODE AND A.RESULT=B.RESULT 
							AND A.TS_FLAG=B.TS_FLAG AND A.RESULT_TIMESTAMP=B.RESULT_TIMESTAMP
							WHERE B.QR_CODE=@QR_CODE

							UPDATE TOP (1) #ROBO_RESULT_PARAMETERS SET complete_ = 1 
							WHERE QR_CODE = @QR_CODE AND complete_ IS NULL

							COMMIT TRANSACTION RoboParameter

							IF @@TRANCOUNT > 0
								ROLLBACK TRANSACTION

						END TRY
						BEGIN CATCH
							SET @RETURNVALUE = CAST(ISNULL(ERROR_NUMBER(),0) AS VARCHAR(5)) + '|' + 
							CAST(ISNULL(ERROR_SEVERITY(),0)AS VARCHAR(5)) + '|' + 
							CAST(ISNULL(ERROR_STATE(),0) AS VARCHAR(5)) + '|' + 
							CAST(ISNULL(ERROR_PROCEDURE(),'') AS VARCHAR(200)) + '|' + 
							'lineNo:'+ CAST(ISNULL(ERROR_LINE(),0) AS VARCHAR(5)) + '|' + 
							'ErrorMssg:'+ CAST(ISNULL(ERROR_MESSAGE(),'') AS VARCHAR(1500))

							IF @@TRANCOUNT > 0
								ROLLBACK TRANSACTION

							INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE, 'ROBO_SCAN', @OPERATIONCODE, 'BARCODE', @BARCODE, @PARTNUMBER, @LINECODE, @RETURNVALUE, @USERID, GETDATE(), @USERID, GETDATE()							
						END CATCH
					END
					print 6
					SELECT Barcode as RFID, QR_CODE, RESULT, RESULT_TIMESTAMP, MachineCode, OperationCode FROM #ROBO_RESULT_PARAMETERS
					WHERE complete_ = 1
				END
				SET @RETURNINT=1
				SET @RETURNVALUE='SUCCESS'
			END
	END
GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_FinalViewingFailed_TallyChartReject_Rework]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create proc [dbo].[Assy_Proc_FinalViewingFailed_TallyChartReject_Rework]
(
@Condition varchar(60),
@ProfitCenterCode varchar(20) =null,
@LineCode varchar(20)=null,
@Barcode varchar(30)=null,
@Status varchar(10)=null,
@UserId varchar(20)=null,
@Remarks varchar(200)=null,
@ReturnValue VARCHAR (200)=NULL OUT,
@ReturnInt INT=NULL OUT
)
as
begin
		--delete Assy_FinalViewingFailed_TallyChartReject_Rework
		--select * from Assy_FinalViewingFailed_TallyChartReject_Rework

		--select * from Assy_TallyChartStatusData
		set nocount on
		if @Condition='VALIDATE_SCANNING'
		begin
			Declare @PartNo varchar(20)

			select @PartNo=assy_partno from assy_runningpart(nolock) where linecode=@LineCode 

			if isnull(@PartNo,'') =''
			begin
					set @ReturnValue='First select a part no. in Set Parameter Form.'
					set @ReturnInt=1
					return
			end

			if right(@barcode,3)<>@LineCode
			begin
				set @ReturnValue='Scanned barcode is not for this line.'
				set @ReturnInt=1
				return
			end

			if left(@barcode,8)<>@PartNo
			begin
				set @ReturnValue='Scanned barcode part no. and running part no. is not matching.'
				set @ReturnInt=1
				return				
			end			

			if exists
			(
					select 1 from Assy_FinalViewingFailed_TallyChartReject_Rework(nolock) 
					where linecode=@LineCode and ProfitCenterCode =@ProfitCenterCode  and barcode=@Barcode 
					and isnull(Status,'')='PASS'
			)
			begin
					set @ReturnValue='Scanned barcode has been already reworked and marked as Pass.'
					set @ReturnInt=1
					return

			end

			if exists
			(
					select 1 from assy_lineassystatus(nolock) 
					where linecode=@LineCode and ProfitCenterCode =@ProfitCenterCode  and barcode=@Barcode 
					and isnull(Status,'')='PS' 
					--and isnull(FailCount,0)=0
					and MachineCode=
					(
						select PARAMETER_VALUE  from PARAMETER_MST(nolock) where PARAMETER_C ='AssLine' 
						and PARAMETER_C1='FinalViewing' and PARAMETER_C2='QCStation_MachineCode' and wh_code =@ProfitCenterCode 
					)
			)
			begin
					set @ReturnValue='Scanned barcode has been already tested and marked as Passed at Final QC station.'
					set @ReturnInt=1
					return

			end
			
			if exists
			(
					select 1 from assy_lineassystatus(nolock) 
					where linecode=@LineCode and ProfitCenterCode =@ProfitCenterCode  and barcode=@Barcode 
					and isnull(Status,'')='FL' 
					and isnull(FailCount,0)>0
					and MachineCode=
					(
						select PARAMETER_VALUE  from PARAMETER_MST(nolock) where PARAMETER_C ='AssLine' 
						and PARAMETER_C1='FinalViewing' and PARAMETER_C2='QCStation_MachineCode' and wh_code =@ProfitCenterCode 
					)
			)
			begin								
								set @ReturnValue='Scanned Successfully.'
								set @ReturnInt=1
								return
			end

			if exists
			(
				select  1 from Assy_TallyChartStatusData(nolock) where  ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode and Barcode=@Barcode
				and isnull(NotProcessedStatus,'')<>'REWORK'
				and MachineCode=
					(
						select PARAMETER_VALUE  from PARAMETER_MST(nolock) where PARAMETER_C ='AssLine' 
						and PARAMETER_C1='FinalViewing' and PARAMETER_C2='QCStation_MachineCode' and wh_code =@ProfitCenterCode 
					)
			)
			begin
					set @ReturnValue='Scanned barcode has not been marked as Rework in tally chart.'
					set @ReturnInt=1
					return

			end
			if exists
			(
				select  1 from Assy_TallyChartStatusData(nolock) where  ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode and Barcode=@Barcode
				and isnull(NotProcessedStatus,'')='REWORK'
				and MachineCode=
					(
						select PARAMETER_VALUE  from PARAMETER_MST(nolock) where PARAMETER_C ='AssLine' 
						and PARAMETER_C1='FinalViewing' and PARAMETER_C2='QCStation_MachineCode' and wh_code =@ProfitCenterCode 
					)
			)
			begin
					set @ReturnValue='Scanned Successfully.'
					set @ReturnInt=1
					return

			end

			if  not exists
			(
					select 1 from assy_lineassystatus(nolock) 
					where linecode=@LineCode and ProfitCenterCode =@ProfitCenterCode  and barcode=@Barcode 
					--and isnull(Status,'')='FL' 
					--and isnull(FailCount,0)>0
					and MachineCode=
					(
						select PARAMETER_VALUE  from PARAMETER_MST(nolock) where PARAMETER_C ='AssLine' 
						and PARAMETER_C1='FinalViewing' and PARAMETER_C2='QCStation_MachineCode' and wh_code =@ProfitCenterCode 
					)
			)
			begin								
								set @ReturnValue='Barcode has not tested on Final Viewing station.'
								set @ReturnInt=1
								return
			end
			set @ReturnValue='Scanned Successfully.'
			set @ReturnInt=1
			return
		end
		else if @Condition='SAVE_REWORK'
		begin		

					insert into Assy_FinalViewingFailed_TallyChartReject_Rework
					(	ProfitCenterCode,
						LineCode,
						Barcode,
						Status,
						UserId,
						Timestamp,
						Remarks,
						Datecode,
						PartNo
						
					)
				    select 
					@ProfitCenterCode,
					@LineCode,
					@Barcode,
					@Status,
					@UserId,
					getdate(),
					@Remarks,
					Datecode,					
					Assy_PartNo					
					from Assy_RunningPart(nolock) where linecode=@linecode
					
					set @ReturnInt=1
					return
		end


end

GO
