select @RequesTD                  

STS_CD

Declare @RequesTD varchar(2000)
EXEC ASSY_PROC_GENERATE_BARCODE @P_Mode='Barcode_Gen',@P_RESQUEST_ID='12034',
@P_LINE_CODE='C10',@P_PROFITCENTER_CODE='0064',@P_OPERATION_CODE='OCIG',
@ReturnValue=@RequesTD output
select @RequesTD


12 - Barcode Generated By TS System.
13 - Barcode Generation Fail TS System.
                                     
****************************************************************************************/
CREATE procedure [dbo].[ASSY_PROC_GENERATE_BARCODE]
(
   @P_Mode varchar(20)='',
   @P_RESQUEST_ID varchar(17)='',
   @P_LINE_CODE varchar(10)='',     
   @P_PROFITCENTER_CODE varchar(10)='',
   @P_OPERATION_CODE varchar(10)='',
   @ReturnValue VARCHAR (2000)=NULL OUT,
   @ReturnInt INT=NULL OUT
)
AS
BEGIN

DECLARE @LINE_CODE varchar(10)=@P_LINE_CODE --'CEL10' -- From Window Service we get this Line Code
DECLARE @PROFITCENTER_CODE varchar(10) =@P_PROFITCENTER_CODE --'0018' -- From Window Service we get this ProfitCenterCode
DECLARE @SERIAL_PREFIX1 VARCHAR(10) = ''
DECLARE @SERIAL_PREFIX2 VARCHAR(10) = ''
DECLARE @TMP_DATE_CODE VARCHAR(10) = ''
DECLARE @PRINT_BARCODE VARCHAR(100) =''
DECLARE @PRINT_CONTENT VARCHAR(100) =''
DECLARE @seqence_number nvarchar(8) = ''
DECLARE @ZPL  VARCHAR(2000) = ''
DECLARE @strBarcode varchar(40)='' 			
			
IF (@P_Mode='Barcode_Gen')
BEGIN
BEGIN TRY
		BEGIN TRAN
			-- Get Machine Code ID Generation
			DECLARE @EXECQUERY VARCHAR(MAX),@LINKSERVERNAME VARCHAR(100)
			declare @MachineCode varchar(2000)
			declare @ProductionOrder varchar(20)
			declare @lotSerialNo varchar(20)
			set @MachineCode=NULL
			declare @p7 int
			set @p7=NULL
			-- code get serial and current dateCode
			CREATE TABLE #TEMP_SEQUENCE_DATECODE
			(
			   SEQUENCE_NUMBER VARCHAR(4),
			   DATECODE VARCHAR(4)
			)
			DECLARE @CurrentDateCode varchar(4)
			declare @DateCode_ varchar(4)
			declare @SerialNo varchar(4)


			exec Assy_Proc_Scan_OK_RFID @LINECODE=@LINE_CODE,@PROFITCENTERCODE=@PROFITCENTER_CODE,@CONDITION=N'GET_ID_Generation_Machinecode',
			@ReturnValue=@MachineCode output,@ReturnInt=@p7 output



			IF(ISNULL(@MachineCode,'') = '')
			BEGIN
					ROLLBACK TRANSACTION
					update ASSY_ID_GENERATION
					set 
					ProfitCenterCode =@PROFITCENTER_CODE,
					LineCode = @LINE_CODE,
					TS_ACK_Time=getdate(),
					STS_CD=13,
					TS_ERROR_MSG='ID Generation Machine Code Not Found'
					where IsClampON=1 and sts_cd=0 and RequestID=CONVERT(numeric,@P_RESQUEST_ID)

					
					--waitfor delay '00:00:03'
					--EXEC ASSY_PROC_RESET_ID_GENERATION_SIGNAL'NG' ,'', @P_OPERATION_CODE
					SELECT 'NOK' as 'RESULT' , 'ID Generation Machine Code Not Found' as 'MSG' , 13 as 'STS_CD'
					
					RETURN
			END


			EXEC ASSY_PROC_WIP_MANAGE  @CONDITION='UPDATE_WIP_COUNT', @LINECODE=@LINE_CODE,
			@MACHINECODE=@MachineCode,@BARCODE='',@PROFITCENTERCODE=@PROFITCENTER_CODE

			declare @WIPMsg varchar(2000)
			exec Assy_Proc_WIP_Manage @CONDITION='VALIDATE_WIP',@ProfitCenterCode=@PROFITCENTER_CODE,
			@LINECODE=@LINE_CODE,@MachineCode=@MachineCode,@RETURNVALUE=@WIPMsg output

			 IF(@WIPMSG='WIP_LIMIT_HAS_REACHED')
			 BEGIN
					ROLLBACK TRANSACTION
							update ASSY_ID_GENERATION
							set 
							ProfitCenterCode =@PROFITCENTER_CODE,
							LineCode = @LINE_CODE,
							TS_ACK_Time=getdate(),
							STS_CD=5,
							TS_ERROR_MSG='WIP Limit Reached'
							where IsClampON=1 and sts_cd=0 and RequestID=CONVERT(numeric,@P_RESQUEST_ID)
							
							--waitfor delay '00:00:03'
							--EXEC ASSY_PROC_RESET_ID_GENERATION_SIGNAL'NG' ,'',@P_OPERATION_CODE

							SELECT 'NOK' as 'RESULT' , 'WIP Limit Reached' as 'MSG' , 5 as 'STS_CD'
							
					RETURN
			 END

			 exec Assy_Proc_Barcode_Printed_Counter @CONDITION='IS_PLANNED_QTY_REACHED',
			 @ProfitCenterCode=@PROFITCENTER_CODE,@LineCode=@LINE_CODE,@RETURNVALUE=@WIPMsg output

			 IF(@WIPMSG='Yes')
			 BEGIN
					ROLLBACK TRANSACTION
							update ASSY_ID_GENERATION
							set 
							ProfitCenterCode =@PROFITCENTER_CODE,
							LineCode = @LINE_CODE,
							TS_ACK_Time=getdate(),
							STS_CD=5,
							TS_ERROR_MSG='WIP Limit Reached'
							where IsClampON=1 and sts_cd=0 and RequestID=CONVERT(numeric,@P_RESQUEST_ID)
							
							--waitfor delay '00:00:03'
							--EXEC ASSY_PROC_RESET_ID_GENERATION_SIGNAL'NG' ,'',@P_OPERATION_CODE

							SELECT 'NOK' as 'RESULT' , 'WIP Limit Reached' as 'MSG', 5 as 'STS_CD'
							
					RETURN
			 END
			 

			 IF EXISTS(select top 1 1 from assy_runningPart(nolock) where Assy_Mode='Rework')
			 BEGIN
					ROLLBACK TRANSACTION
							update ASSY_ID_GENERATION
							set 
							ProfitCenterCode =@PROFITCENTER_CODE,
							LineCode = @LINE_CODE,
							TS_ACK_Time=getdate(),
							STS_CD=17,
							TS_ERROR_MSG='Barcode Print Not Allowed In Rework Mode'
							where IsClampON=1 and sts_cd=0 and RequestID=CONVERT(numeric,@P_RESQUEST_ID)
							
							--waitfor delay '00:00:03'
							--EXEC ASSY_PROC_RESET_ID_GENERATION_SIGNAL'NG' ,'',@P_OPERATION_CODE

							SELECT 'NOK' as 'RESULT' , 'Barcode Print Not Allowed In Rework Mode' as 'MSG' , 17 as 'STS_CD'
							
					RETURN
			END

			begin try
			DROP TABLE #TEMP_RUNING_DATA
			END TRY
			BEGIN CATCH
			END CATCH

			CREATE TABLE #TEMP_RUNING_DATA
			(
			  ASSY_PARTNO varchar(11),
			  DATECODE    VARCHAR(4),
			  ASSY_MODE   VARCHAR(20)
			)

			INSERT INTO #TEMP_RUNING_DATA
			exec ASSY_PROC_Vision_System_PART_SELECTION 
			@Operation='SELECT',@lineCode =@LINE_CODE,@ProfitCenterCode=@ProfitCenter_Code

			IF NOT EXISTS(SELECT TOP 1 1 FROM #TEMP_RUNING_DATA)
			BEGIN
					ROLLBACK TRANSACTION
					update ASSY_ID_GENERATION
					set 
					ProfitCenterCode =@PROFITCENTER_CODE,
					LineCode = @LINE_CODE,
					TS_ACK_Time=getdate(),
					STS_CD=17,
					TS_ERROR_MSG='Set Parameter Not Done For Line'
					where IsClampON=1 and sts_cd=0 and RequestID=CONVERT(numeric,@P_RESQUEST_ID)
					
					--waitfor delay '00:00:03'
					--EXEC ASSY_PROC_RESET_ID_GENERATION_SIGNAL'NG' ,'',@P_OPERATION_CODE

					SELECT 'NOK' as 'RESULT' , 'Set Parameter Not Done For Line' as 'MSG', 17 as 'STS_CD'
					
					RETURN
			END

		

			declare @strPartNo NVARCHAR(11) = (SELECT TOP 1 ASSY_PARTNO FROM #TEMP_RUNING_DATA)
			declare @DateCode NVARCHAR(4) = (SELECT TOP 1 DATECODE FROM #TEMP_RUNING_DATA)
			declare @strMode NVARCHAR(50) = (SELECT TOP 1 ASSY_MODE FROM #TEMP_RUNING_DATA)
			declare @strCustPartNo NVARCHAR(30) = ''
			
			select Top 1 @ProductionOrder=ProductionOrderNo,@strCustPartNo = CustomerPartNo from Assy_RunningPart(nolock) 
			where ProfitCenterCode=@ProfitCenter_Code and LineCode=@LINE_CODE

			--SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL  WITH (NOLOCK) 
			--WHERE PROFITCENTERCODE = @PROFITCENTER_CODE AND LINECODE = @LINE_CODE

			--CREATE TABLE #COUNT
			--(
			--COUNT_VALUE int
			--)

			--SET @EXECQUERY = 'select top 1 1 from ' + @LINKSERVERNAME +'.DBO.'+'RoutingConfigDetails WITH (NOLOCK) 
			--where ProfitCenterCode='+''''+@PROFITCENTER_CODE +'''' + ' and 
			--sts_cd=0 and keyType=' +'''IsImportBarcodeMode'''+' and KeyValue=''1'' 
			--and LineCode='+''''+@LINE_CODE+''''+' and PartNumber='+''''+@strPartNo+''''
					
			--insert into #COUNT(COUNT_VALUE)				
			--EXEC(@EXECQUERY)					
			---- Label Not Generated By TS System.			
			--if exists(select top 1 1 from #COUNT)
			--begin
		
			--		ROLLBACK TRANSACTION

			--		update ASSY_ID_GENERATION
			--		set 
			--		ProfitCenterCode =@PROFITCENTER_CODE,
			--		LineCode = @LINE_CODE,
			--		TS_ACK_Time=getdate(),
			--		STS_CD=17,
			--		TS_ERROR_MSG='Import Label Run on Line'
			--		where IsClampON=1 and sts_cd=0 and RequestID=CONVERT(numeric,@P_RESQUEST_ID)
					
			--		--waitfor delay '00:00:03'
			--		--EXEC ASSY_PROC_RESET_ID_GENERATION_SIGNAL'NG' ,'',@P_OPERATION_CODE

			--		SELECT 'NOK' as 'RESULT' , 'Import Label Run on Line' as 'MSG', 17 as 'STS_CD'
					
			--		RETURN
			--end

			

			begin try
			DROP TABLE #TEMP_SEQUENCE_NUMBER
			END TRY
			BEGIN CATCH
			END CATCH
			-- Get Barcode Format Option From RoutingConfigDetails
			Declare @BarcodeFormatOption varchar(20)

			select @BarcodeFormatOption=ISNULL(KeyValue,'') from RoutingConfigDetails(nolock) where profitcenterCode=@PROFITCENTER_CODE
			and lineCode=@LINE_CODE and keytype='BarcodeFormat' and STS_CD=0

			IF (ISNULL(@BarcodeFormatOption,'') = '')
			BEGIN
					ROLLBACK TRANSACTION
					update ASSY_ID_GENERATION
					set 
					ProfitCenterCode =@PROFITCENTER_CODE,
					LineCode = @LINE_CODE,
					TS_ACK_Time=getdate(),
					STS_CD=13,
					TS_ERROR_MSG='Barcode Generation Failed'
					where IsClampON=1 and sts_cd=0 and RequestID=CONVERT(numeric,@P_RESQUEST_ID)
					
					--waitfor delay '00:00:03'
					--EXEC ASSY_PROC_RESET_ID_GENERATION_SIGNAL'NG' ,'',@P_OPERATION_CODE

					SELECT 'NOK' as 'RESULT' , 'Barcode Generation Failed Barcode Format Option Not Found' as 'MSG', 13 as 'STS_CD'
					RETURN
			END

			IF(@BarcodeFormatOption='Option_1')
			BEGIN
			
			CREATE TABLE #TEMP_SEQUENCE_NUMBER
			(
			   SEQUENCE_NUMBER INT
			)
			
			INSERT INTO #TEMP_SEQUENCE_NUMBER
			exec ASSY_Proc_Vision_System_Log  @Operation= 'SELECT_SEQUENCE_NUMBER',
			@PartNo= @strPartNo,
			@linecode =@LINE_CODE,
			@ProfitCenterCode=@PROFITCENTER_CODE

			IF NOT EXISTS(SELECT TOP 1 1 FROM #TEMP_SEQUENCE_NUMBER)
			BEGIN
					ROLLBACK TRANSACTION
					update ASSY_ID_GENERATION
					set 
					ProfitCenterCode =@PROFITCENTER_CODE,
					LineCode = @LINE_CODE,
					TS_ACK_Time=getdate(),
					STS_CD=13,
					TS_ERROR_MSG='Barcode Generation Failed'
					where IsClampON=1 and sts_cd=0 and RequestID=CONVERT(numeric,@P_RESQUEST_ID)
					
					--waitfor delay '00:00:03'
					--EXEC ASSY_PROC_RESET_ID_GENERATION_SIGNAL'NG' ,'',@P_OPERATION_CODE

					SELECT 'NOK' as 'RESULT' , 'Barcode Generation Failed Sequence Not Found in Table ASSY_Vision_System_Log ' as 'MSG' , 13 as 'STS_CD'
					RETURN
			END

			SET @seqence_number = convert(nvarchar,(select top 1 (SEQUENCE_NUMBER+1) from #TEMP_SEQUENCE_NUMBER))
			if ( LEN(@seqence_number) < 8)
			BEGIN
			 SET @seqence_number = REPLACE(STR(@seqence_number, 8), SPACE(1), '0')
			END

			
			SET @strBarcode  = @strPartNo + @DateCode + @seqence_number + @line_code;
			
			exec ASSY_Proc_Vision_System_Log  @OPeration ='UPDATE_SEQUENCE_NUMBER',@PartNo=@strPartNo,
			@LastPrintBarcode=@strBarcode,@linecode =@LINE_CODE,
			@ProfitCenterCode=@PROFITCENTER_CODE

			
			END

			IF(@BarcodeFormatOption='Option_2')
			begin
			BEGIN
			
		    


			EXEC ASSY_PROC_GetSerial_DateWise 
			@PROFITCENTER_CODE,@LINE_CODE,@MachineCode,@P_ReturnSerialNo=@SerialNo out
			,@P_ReturnDateCode=@DateCode_ out
			
			insert into #TEMP_SEQUENCE_DATECODE(SEQUENCE_NUMBER,DATECODE)
			values(@SerialNo,@DateCode_)
			
			
			IF NOT EXISTS(SELECT TOP 1 1 FROM #TEMP_SEQUENCE_DATECODE)
			BEGIN
					ROLLBACK TRANSACTION
					update ASSY_ID_GENERATION
					set 
					ProfitCenterCode =@PROFITCENTER_CODE,
					LineCode = @LINE_CODE,
					TS_ACK_Time=getdate(),
					STS_CD=13,
					TS_ERROR_MSG='Barcode Generation Failed'
					where IsClampON=1 and sts_cd=0 and RequestID=CONVERT(numeric,@P_RESQUEST_ID)
					
					--waitfor delay '00:00:03'
					--EXEC ASSY_PROC_RESET_ID_GENERATION_SIGNAL'NG' ,'',@P_OPERATION_CODE

					SELECT 'NOK' as 'RESULT' , 'Barcode Generation Failed' as 'MSG' , 13 as 'STS_CD'
					RETURN
			END

				
				EXEC ASSY_PROC_DATECODE @PROFITCENTERCODE=@PROFITCENTER_CODE,
				@RETURNVALUE= @CurrentDateCode OUTPUT

			--if ((SELECT DBO.FN_GET_DATE_FROM_DATECODE(@CurrentDateCode,@PROFITCENTER_CODE))<>
			--(SELECT DBO.FN_GET_DATE_FROM_DATECODE(@DateCode,@PROFITCENTER_CODE)))
			-- Check for Shift Change If Shift Changed User Must Have To Do 
			-- Set Parameter To Take New Print.
			if exists(select top 1 1 from lineMst(nolock) where lineCode=@LINE_CODE and ProfitCenterCode=@PROFITCENTER_CODE
			   and ISNULL(AutoTallyChartEnable,0)=0)
			   begin
			if not exists (select top 1 1 from #TEMP_SEQUENCE_DATECODE where DATECODE=@DateCode)
			begin
					
					ROLLBACK TRANSACTION
					update ASSY_ID_GENERATION
					set 
					ProfitCenterCode =@PROFITCENTER_CODE,
					LineCode = @LINE_CODE,
					TS_ACK_Time=getdate(),
					STS_CD=17,
					TS_ERROR_MSG='Set Parameter Not Done For Line'
					where IsClampON=1 and sts_cd=0 and RequestID=CONVERT(numeric,@P_RESQUEST_ID)
					
					--waitfor delay '00:00:03'
					--EXEC ASSY_PROC_RESET_ID_GENERATION_SIGNAL'NG' ,'',@P_OPERATION_CODE

					SELECT 'NOK' as 'RESULT' , 'Set Parameter Not Done For Line' as 'MSG' , 17 as 'STS_CD'
					RETURN
			end
			end

			SELECT @SEQENCE_NUMBER=SEQUENCE_NUMBER FROM #TEMP_SEQUENCE_DATECODE
			--SELECT @TMP_DATE_CODE=DATECODE FROM #TEMP_SEQUENCE_DATECODE

			IF (CONVERT(INT,@SEQENCE_NUMBER) > 999)
			BEGIN
					ROLLBACK TRANSACTION
					update ASSY_ID_GENERATION
					set 
					ProfitCenterCode =@PROFITCENTER_CODE,
					LineCode = @LINE_CODE,
					TS_ACK_Time=getdate(),
					STS_CD=13,
					TS_ERROR_MSG='Barcode Generation Failed'
					where IsClampON=1 and sts_cd=0 and RequestID=CONVERT(numeric,@P_RESQUEST_ID)
					
					--waitfor delay '00:00:03'
					--EXEC ASSY_PROC_RESET_ID_GENERATION_SIGNAL'NG' ,'',@P_OPERATION_CODE

					SELECT 'NOK' as 'RESULT' , 'Barcode Generation Failed' as 'MSG' , 13 as 'STS_CD'
					RETURN
			END


			if ( LEN(@seqence_number) < 3)
			BEGIN
			 SET @seqence_number = REPLACE(STR(@seqence_number, 3), SPACE(1), '0')
			END

			select @SERIAL_PREFIX1 = keyvalue from RoutingConfigDetails(nolock) where ProfitCenterCode=@PROFITCENTER_CODE
			and LineCode=@LINE_CODE and MachineCode=@MachineCode and STS_CD=0 and KeyType='BarcodePrefix1'
		
			select @SERIAL_PREFIX2 = keyvalue from RoutingConfigDetails(nolock) where ProfitCenterCode=@PROFITCENTER_CODE
			and LineCode=@LINE_CODE and MachineCode=@MachineCode and STS_CD=0 and KeyType='BarcodePrefix2'
		

			--SET @strBarcode  = ISNULL(@SERIAL_PREFIX1,'') + ISNULL(@SERIAL_PREFIX2,'') + @seqence_number + @DateCode
			SET @strBarcode    = @seqence_number + @DateCode 
			set @PRINT_CONTENT = ISNULL(@SERIAL_PREFIX1,'') + ISNULL(@SERIAL_PREFIX2,'') + @seqence_number + @DateCode 
			
			IF EXISTS (SELECT TOP 1 1 FROM ASSY_TD_OPERATION_TABLE_MAPPING(NOLOCK)
			WHERE PROFITCENTERCODE=@PROFITCENTER_CODE AND LINECODE=@LINE_CODE AND 
			MACHINECODE=@machineCode AND ISLABELPRINTREQ=1
			)
			BEGIN
					select @ZPL=ISNULL(keyvalue,'') from RoutingConfigDetails(nolock) 
					where PROFITCENTERCODE=@PROFITCENTER_CODE AND 
					LINECODE=@LINE_CODE AND MACHINECODE=@MachineCode and STS_CD=0
					and KeyType='BarcodeLbl'

					SET @ZPL = REPLACE(@ZPL,'[SERIAL_PREFIX1]',@SERIAL_PREFIX1)
					SET @ZPL = REPLACE(@ZPL,'[SERIAL_PREFIX2]',@SERIAL_PREFIX2)
					SET @ZPL = REPLACE(@ZPL,'[SEQENCE_NUMBER]',@SEQENCE_NUMBER)
					SET @ZPL = REPLACE(@ZPL,'[TMP_DATE_CODE1]',SUBSTRING(@DateCode,1,1))
					SET @ZPL = REPLACE(@ZPL,'[TMP_DATE_CODE2]',SUBSTRING(@DateCode,2,3))
					SET @ZPL = REPLACE(@ZPL,'[PRINT_CONTENT]',@PRINT_CONTENT)
			END
			ELSE
			BEGIN
			   SET @ZPL = ''
			END

			END
			end

			IF(@BarcodeFormatOption='Option_3')
			begin
			BEGIN
			
		    
			EXEC ASSY_PROC_GetSerial_DateWise 
			@PROFITCENTER_CODE,@LINE_CODE,@MachineCode,@P_ReturnSerialNo=@SerialNo out
			,@P_ReturnDateCode=@DateCode_ out
			
			insert into #TEMP_SEQUENCE_DATECODE(SEQUENCE_NUMBER,DATECODE)
			values(@SerialNo,@DateCode_)
			
			
			IF NOT EXISTS(SELECT TOP 1 1 FROM #TEMP_SEQUENCE_DATECODE)
			BEGIN
					ROLLBACK TRANSACTION
					update ASSY_ID_GENERATION
					set 
					ProfitCenterCode =@PROFITCENTER_CODE,
					LineCode = @LINE_CODE,
					TS_ACK_Time=getdate(),
					STS_CD=13,
					TS_ERROR_MSG='Barcode Generation Failed'
					where IsClampON=1 and sts_cd=0 and RequestID=CONVERT(numeric,@P_RESQUEST_ID)
					
					--waitfor delay '00:00:03'
					--EXEC ASSY_PROC_RESET_ID_GENERATION_SIGNAL'NG' ,'',@P_OPERATION_CODE

					SELECT 'NOK' as 'RESULT' , 'Barcode Generation Failed' as 'MSG' , 13 as 'STS_CD'
					RETURN
			END

			
				EXEC ASSY_PROC_DATECODE @PROFITCENTERCODE=@PROFITCENTER_CODE,
				@RETURNVALUE= @CurrentDateCode OUTPUT

			--if ((SELECT DBO.FN_GET_DATE_FROM_DATECODE(@CurrentDateCode,@PROFITCENTER_CODE))<>
			--(SELECT DBO.FN_GET_DATE_FROM_DATECODE(@DateCode,@PROFITCENTER_CODE)))
			-- Check for Shift Change If Shift Changed User Must Have To Do 
			-- Set Parameter To Take New Print.
			if exists(select top 1 1 from lineMst(nolock) where lineCode=@LINE_CODE and ProfitCenterCode=@PROFITCENTER_CODE
			   and ISNULL(AutoTallyChartEnable,0)=0)
			 begin
			if not exists (select top 1 1 from #TEMP_SEQUENCE_DATECODE where DATECODE=@DateCode)
			begin
					
					ROLLBACK TRANSACTION
					update ASSY_ID_GENERATION
					set 
					ProfitCenterCode =@PROFITCENTER_CODE,
					LineCode = @LINE_CODE,
					TS_ACK_Time=getdate(),
					STS_CD=17,
					TS_ERROR_MSG='Set Parameter Not Done For Line'
					where IsClampON=1 and sts_cd=0 and RequestID=CONVERT(numeric,@P_RESQUEST_ID)
					
					--waitfor delay '00:00:03'
					--EXEC ASSY_PROC_RESET_ID_GENERATION_SIGNAL'NG' ,'',@P_OPERATION_CODE

					SELECT 'NOK' as 'RESULT' , 'Set Parameter Not Done For Line' as 'MSG', 17 as 'STS_CD'
					RETURN
			end
			end

			SELECT @SEQENCE_NUMBER=SEQUENCE_NUMBER FROM #TEMP_SEQUENCE_DATECODE
			--SELECT @TMP_DATE_CODE=DATECODE FROM #TEMP_SEQUENCE_DATECODE

			IF (CONVERT(INT,@SEQENCE_NUMBER) > 99999)
			BEGIN
					ROLLBACK TRANSACTION
					update ASSY_ID_GENERATION
					set 
					ProfitCenterCode =@PROFITCENTER_CODE,
					LineCode = @LINE_CODE,
					TS_ACK_Time=getdate(),
					STS_CD=13,
					TS_ERROR_MSG='Barcode Generation Failed'
					where IsClampON=1 and sts_cd=0 and RequestID=CONVERT(numeric,@P_RESQUEST_ID)
					
					--waitfor delay '00:00:03'
					--EXEC ASSY_PROC_RESET_ID_GENERATION_SIGNAL'NG' ,'',@P_OPERATION_CODE

					SELECT 'NOK' as 'RESULT' , 'Barcode Generation Failed' as 'MSG', 13 as 'STS_CD'
					RETURN
			END


			if ( LEN(@seqence_number) < 5)
			BEGIN
			 SET @seqence_number = REPLACE(STR(@seqence_number, 5), SPACE(1), '0')
			END
						
			
			SET @strBarcode    = @seqence_number + @DateCode_ + @LINE_CODE
			
			IF EXISTS (SELECT TOP 1 1 FROM ASSY_TD_OPERATION_TABLE_MAPPING(NOLOCK)
			WHERE PROFITCENTERCODE=@PROFITCENTER_CODE AND LINECODE=@LINE_CODE AND 
			MACHINECODE=@machineCode AND ISLABELPRINTREQ=1
			)
			BEGIN
					select @ZPL=ISNULL(keyvalue,'') from RoutingConfigDetails(nolock) 
					where PROFITCENTERCODE=@PROFITCENTER_CODE AND 
					LINECODE=@LINE_CODE AND MACHINECODE=@MachineCode and STS_CD=0
					and KeyType='BarcodeLbl'

					
			END
			ELSE
			BEGIN
			   SET @ZPL = ''
			END

			END
			end

			-----Start Option 4-------
			IF(@BarcodeFormatOption='Option_4')
			begin
			BEGIN
			
		    
			EXEC ASSY_PROC_GetSerial_DateWise 
			@PROFITCENTER_CODE,@LINE_CODE,@MachineCode,@P_ReturnSerialNo=@SerialNo out
			,@P_ReturnDateCode=@DateCode_ out
			
			insert into #TEMP_SEQUENCE_DATECODE(SEQUENCE_NUMBER,DATECODE)
			values(@SerialNo,@DateCode_)
			
			IF NOT EXISTS(SELECT TOP 1 1 FROM #TEMP_SEQUENCE_DATECODE)
			BEGIN
					ROLLBACK TRANSACTION
					update ASSY_ID_GENERATION
					set 
					ProfitCenterCode =@PROFITCENTER_CODE,
					LineCode = @LINE_CODE,
					TS_ACK_Time=getdate(),
					STS_CD=13,
					TS_ERROR_MSG='Barcode Generation Failed'
					where IsClampON=1 and sts_cd=0 and RequestID=CONVERT(numeric,@P_RESQUEST_ID)
					
					--waitfor delay '00:00:03'
					--EXEC ASSY_PROC_RESET_ID_GENERATION_SIGNAL'NG' ,'',@P_OPERATION_CODE

					SELECT 'NOK' as 'RESULT' , 'Barcode Generation Failed' as 'MSG' , 13 as 'STS_CD'
					RETURN
			END

			
				EXEC ASSY_PROC_DATECODE @PROFITCENTERCODE=@PROFITCENTER_CODE,
				@RETURNVALUE= @CurrentDateCode OUTPUT

			--if ((SELECT DBO.FN_GET_DATE_FROM_DATECODE(@CurrentDateCode,@PROFITCENTER_CODE))<>
			--(SELECT DBO.FN_GET_DATE_FROM_DATECODE(@DateCode,@PROFITCENTER_CODE)))
			-- Check for Shift Change If Shift Changed User Must Have To Do 
			-- Set Parameter To Take New Print.
			if exists(select top 1 1 from lineMst(nolock) where lineCode=@LINE_CODE and ProfitCenterCode=@PROFITCENTER_CODE
			   and ISNULL(AutoTallyChartEnable,0)=0)
			 begin
			if not exists (select top 1 1 from #TEMP_SEQUENCE_DATECODE where DATECODE=@DateCode)
			begin
					
					ROLLBACK TRANSACTION
					update ASSY_ID_GENERATION
					set 
					ProfitCenterCode =@PROFITCENTER_CODE,
					LineCode = @LINE_CODE,
					TS_ACK_Time=getdate(),
					STS_CD=17,
					TS_ERROR_MSG='Set Parameter Not Done For Line'
					where IsClampON=1 and sts_cd=0 and RequestID=CONVERT(numeric,@P_RESQUEST_ID)
					
					--waitfor delay '00:00:03'
					--EXEC ASSY_PROC_RESET_ID_GENERATION_SIGNAL'NG' ,'',@P_OPERATION_CODE

					SELECT 'NOK' as 'RESULT' , 'Set Parameter Not Done For Line' as 'MSG', 17 as 'STS_CD'
					RETURN
			end
			end

			SELECT @SEQENCE_NUMBER=SEQUENCE_NUMBER FROM #TEMP_SEQUENCE_DATECODE
			--SELECT @TMP_DATE_CODE=DATECODE FROM #TEMP_SEQUENCE_DATECODE

			IF (CONVERT(INT,@SEQENCE_NUMBER) > 9999)
			BEGIN
					ROLLBACK TRANSACTION
					update ASSY_ID_GENERATION
					set 
					ProfitCenterCode =@PROFITCENTER_CODE,
					LineCode = @LINE_CODE,
					TS_ACK_Time=getdate(),
					STS_CD=13,
					TS_ERROR_MSG='Barcode Generation Failed'
					where IsClampON=1 and sts_cd=0 and RequestID=CONVERT(numeric,@P_RESQUEST_ID)
					
					--waitfor delay '00:00:03'
					--EXEC ASSY_PROC_RESET_ID_GENERATION_SIGNAL'NG' ,'',@P_OPERATION_CODE

					SELECT 'NOK' as 'RESULT' , 'Barcode Generation Failed' as 'MSG', 13 as 'STS_CD'
					RETURN
			END


			if ( LEN(@seqence_number) < 4)
			BEGIN
			 SET @seqence_number = REPLACE(STR(@seqence_number, 4), SPACE(1), '0')
			END

			--SELECT Top 1 @strPartNo = CustomerPartNo FROM Assy_RunningPart (NOLOCK) WHERE lineCode=@LINE_CODE and ProfitCenterCode=@PROFITCENTER_CODE

			if ISNULL(@strPartNo,'') = ''
			begin
					ROLLBACK TRANSACTION
					update ASSY_ID_GENERATION
					set 
					ProfitCenterCode =@PROFITCENTER_CODE,
					LineCode = @LINE_CODE,
					TS_ACK_Time=getdate(),
					STS_CD=17,
					TS_ERROR_MSG='Customer Part Number is not available Running Part Table'
					where IsClampON=1 and sts_cd=0 and RequestID=CONVERT(numeric,@P_RESQUEST_ID)
					
					--waitfor delay '00:00:03'
					--EXEC ASSY_PROC_RESET_ID_GENERATION_SIGNAL'NG' ,'',@P_OPERATION_CODE

					SELECT 'NOK' as 'RESULT' , 'Customer Part Number is not available Running Part Table' as 'MSG', 17 as 'STS_CD'
					RETURN
			end
			Declare @DisplayBarcode VARCHAR(100) = ''
			IF EXISTS
			(
				SELECT Top 1 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTER_CODE AND LineCode = @LINE_CODE AND
					sts_cd = 0 AND KeyType = 'IsCustomerPartInBarcodeLabel' AND keyvalue = '1'
			)
			BEGIN
				SET @strBarcode = @strCustPartNo + @DateCode_ + @seqence_number + @LINE_CODE
				SET @DisplayBarcode = @strCustPartNo + @seqence_number
			END
			ELSE
			BEGIN
				SET @strBarcode = @strPartNo + @DateCode_ + @seqence_number + @LINE_CODE
				SET @DisplayBarcode = RIGHT(@strPartNo,4) + @seqence_number
			END
			
			IF EXISTS
			(
				SELECT TOP 1 1 FROM ASSY_TD_OPERATION_TABLE_MAPPING(NOLOCK)
					WHERE PROFITCENTERCODE=@PROFITCENTER_CODE AND LINECODE=@LINE_CODE AND MACHINECODE=@machineCode AND ISLABELPRINTREQ=1
			)
			BEGIN
				Declare
					@Part_Desc VARCHAR(100) = ''
					,@Part_Diameter VARCHAR(100) = ''
					,@Part_Model VARCHAR(100) = ''
					,@Part_Type VARCHAR(100) = ''

				SELECT @Part_Desc = ISNULL(LabelDataValue,'') FROM Assy_Coupling_LabelInfo_Mst (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTER_CODE AND PartNo = @strPartNo
					AND CustomerPartNo = @strCustPartNo	AND LabelDataName = 'Part_Desc'
				
				SELECT @Part_Diameter = ISNULL(LabelDataValue,'') FROM Assy_Coupling_LabelInfo_Mst (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTER_CODE AND PartNo = @strPartNo
					AND CustomerPartNo = @strCustPartNo	AND LabelDataName = 'Part_Diameter'
				
				SELECT @Part_Model = ISNULL(LabelDataValue,'') FROM Assy_Coupling_LabelInfo_Mst (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTER_CODE AND PartNo = @strPartNo
					AND CustomerPartNo = @strCustPartNo	AND LabelDataName = 'Part_Model'
				
				SELECT @Part_Type = ISNULL(LabelDataValue,'') FROM Assy_Coupling_LabelInfo_Mst (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTER_CODE AND PartNo = @strPartNo
					AND CustomerPartNo = @strCustPartNo	AND LabelDataName = 'Part_Type'
					
				SELECT @ZPL=ISNULL(keyvalue,'') from RoutingConfigDetails(nolock) 
				WHERE PROFITCENTERCODE=@PROFITCENTER_CODE AND 
				LINECODE=@LINE_CODE AND MACHINECODE=@MachineCode and STS_CD=0
				and KeyType='BarcodeLbl'

				SET @ZPL = REPLACE(@ZPL,'@Part_Barcode@',@strBarcode)
				SET @ZPL = REPLACE(@ZPL,'@Display_Barcode@',@DisplayBarcode)
				SET @ZPL = REPLACE(@ZPL,'@Part_Model@',@Part_Model)
				SET @ZPL = REPLACE(@ZPL,'@Part_Diameter@',@Part_Diameter)
				SET @ZPL = REPLACE(@ZPL,'@Part_Type@',@Part_Type)
				SET @ZPL = REPLACE(@ZPL,'@Part_Desc@',@Part_Desc)
			END
			ELSE
			BEGIN
			   SET @ZPL = ''
			END

			END
			end
			-----End Option 4-------

			print 1
			if exists(select top 1 1 from RoutingConfigDetails(nolock)
			where ProfitCenterCode=@PROFITCENTER_CODE and LineCode=@LINE_CODE and 
			sts_cd=0 and KeyType='isLotNumberReq' and keyvalue='1'
			 )
			begin

				 declare @lotNo int

			     if exists(select top 1 1 from ASSY_GENERATE_LOTNO_ON_DATACHANGE(nolock)
				 where ProfitCenterCode=@PROFITCENTER_CODE and LineCode=@LINE_CODE and 
				 Datecode=@DateCode 
				 )
				 begin
						
						print 'no change get same lot number again'
												
				 end
				 else
				 begin
					print 'update Lot Number '
					select @lotNo=Lot_No from ASSY_GENERATE_LOTNO_ON_DATACHANGE(nolock)
							
					insert into ASSY_GENERATE_LOTNO_ON_DATACHANGE_LOG(ProfitCenterCode,LineCode,Datecode,PartNo,ProductionOrderNo,Lot_No,
					STS_CD,ENT_BY,ENT_STAMP)
					select ProfitCenterCode,LineCode,Datecode,PartNo,ProductionOrderNo,Lot_No,STS_CD,ENT_BY,ENT_STAMP	
					from ASSY_GENERATE_LOTNO_ON_DATACHANGE(NOLOCK)

					delete from ASSY_GENERATE_LOTNO_ON_DATACHANGE

					set @lotNo=ISNULL(@lotNo,0)+1
					
					insert into ASSY_GENERATE_LOTNO_ON_DATACHANGE(ProfitCenterCode,LineCode,Datecode,PartNo,
					ProductionOrderNo,Lot_No,STS_CD,ENT_BY,ENT_STAMP)
					select @PROFITCENTER_CODE,@LINE_CODE,@DateCode,@strPartNo,
					@ProductionOrder,@lotNo,0,'ADMIN',GETDATE()	
					
				 end

				 select @lotNo=Lot_No from ASSY_GENERATE_LOTNO_ON_DATACHANGE(nolock)
						where ProfitCenterCode=@PROFITCENTER_CODE and LineCode=@LINE_CODE and 
						Datecode=@DateCode 

				SET @lotSerialNo = REPLACE(STR(@LOTNO, 6), SPACE(1), '0')
				SET @lotSerialNo = @lotSerialNo+ISNULL(@DateCode,'')

			end

			exec Assy_Proc_Vision_System @Barcode= @strBarcode,@LineCode=@LINE_CODE
			,@ProfitCenterCode=@PROFITCENTER_CODE,@SerialNo=@seqence_number,
			@lotSerialNo=@lotSerialNo

			update ASSY_ID_GENERATION
			set 
			ProfitCenterCode =@PROFITCENTER_CODE,
			LineCode = @LINE_CODE,
			MachineCode = 'MCIG',
			StationCode ='',
			Datecode=@DateCode,
			PartNo=@strPartNo,
			Barcode=@strBarcode,
			TS_ACK_Time=getdate(),
			STS_CD=12,
			TS_ERROR_MSG=''
			where IsClampON=1 and sts_cd=0 and RequestID=CONVERT(numeric,@P_RESQUEST_ID)

			SELECT 'OK' as 'RESULT', @strBarcode as 'MSG' , @ZPL as 'PRN', 12 as 'STS_CD'

			--waitfor delay '00:00:03'
			--exec ASSY_PROC_RESET_ID_GENERATION_SIGNAL'OK' ,@strBarcode
			SET @ReturnValue=@strBarcode
			SET @ReturnInt=1
		
		COMMIT TRAN
END TRY
BEGIN CATCH

ROLLBACK TRAN

DECLARE @ERROR_MSG NVARCHAR(2000)
SET @ERROR_MSG=LTRIM(RTRIM(ERROR_MESSAGE()))

update ASSY_ID_GENERATION
set 
ProfitCenterCode =@PROFITCENTER_CODE,
LineCode = @LINE_CODE,
TS_ACK_Time=getdate(),
STS_CD=18,
TS_ERROR_MSG=@ERROR_MSG
where IsClampON=1 and sts_cd=0 and RequestID=CONVERT(numeric,@P_RESQUEST_ID)

SELECT 'NOK' as 'RESULT' , @ERROR_MSG as 'MSG' , 18 as 'STS_CD'
							
END CATCH
END

IF(@P_Mode='getRequestId')
BEGIN
		
   SELECT CONVERT(VARCHAR,REQUESTID) as REQUESTID, OperationCode FROM ASSY_ID_GENERATION(NOLOCK) WHERE ISCLAMPON=1 AND sts_cd=0
   --SET @ReturnValue=ISNULL(@ReturnValue,'') 

END
END


GO
/****** Object:  StoredProcedure [dbo].[Assy_PROC_GET_CHANNEL_DETAILS]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Assy_PROC_GET_CHANNEL_DETAILS]
@LINECODE VARCHAR(100)=NULL,
@PARTNUMBER VARCHAR(100)=NULL,
@OPERATIONCODE VARCHAR(100)=NULL,
@RETURNVALUE VARCHAR (2000)=NULL OUT,
@RETURNINT INT=NULL OUT
AS
BEGIN
BEGIN TRY
BEGIN TRAN

if isnull(@PARTNUMBER,'')=''
begin
select MT.MachineCode,L.OperationCode,MD.ChannelName ,MD.DeviceName,MT.TagName  from MachineDtl MD 
inner join	
MachineTagMapping MT on MD.MachineCode=MT.MachineCode  and MD.ProfitCenterCode=MT.ProfitCenterCode inner join  RoutingConfigLineWise L 
on MD.OperationCode=L.OperationCode and MD.MachineCode =L.MachineCode and MD.LineCode =L.LineCode and	MD.ProfitCenterCode =L.ProfitCenterCode 
--inner join
--RoutingConfigPartWise P  on L.OperationCode =P.OperationCode and 
--l.ProfitCenterCode =p.ProfitCenterCode  and p.MachineCode =l.MachineCode 
where --P.Traceability =1 and P.OperationRequired =1 and 
L.LineCode =@LINECODE and L.Traceability =1 and L.OperationRequired =1  and	 L.OperationCode =@OPERATIONCODE
end
else
begin
select MT.MachineCode,L.OperationCode,MD.ChannelName ,MD.DeviceName,MT.TagName  from MachineDtl MD 
inner join	
MachineTagMapping MT on MD.MachineCode=MT.MachineCode  and MD.ProfitCenterCode=MT.ProfitCenterCode inner join  RoutingConfigLineWise L 
on MD.OperationCode=L.OperationCode and MD.MachineCode =L.MachineCode and MD.LineCode =L.LineCode and  MD.ProfitCenterCode =L.ProfitCenterCode 
inner join
RoutingConfigPartWise P  on L.OperationCode =P.OperationCode and 
l.ProfitCenterCode =p.ProfitCenterCode  and p.MachineCode =l.MachineCode 
where P.Traceability =1 and P.OperationRequired =1
and L.LineCode =@LINECODE and L.Traceability =1 and L.OperationRequired =1 and P.PartNo=@PARTNUMBER and	 L.OperationCode =@OPERATIONCODE
end

COMMIT TRAN
END TRY
BEGIN CATCH
        ROLLBACK TRAN
		SET @RETURNVALUE =	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 	CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
		CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
		CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + CAST(ERROR_MESSAGE() AS VARCHAR(1500))
		SET @RETURNINT = 2
END CATCH
END




GO
/****** Object:  StoredProcedure [dbo].[ASSY_PROC_GET_DATECODE]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[ASSY_PROC_GET_DATECODE]
(
	@ProfitCenterCode VARCHAR(10), 
	@LINECODE VARCHAR (10)=NULL,
	@ReturnValue VARCHAR (2000) = NULL OUT, 
	@ReturnInt INT = NULL OUT,
	@Condition VARCHAR(100) = NULL	--Added By THK ON 10-05-2019
)
AS
BEGIN
	/*
		Author:			< Ravishankar Mishra >
		Create Date:	< 17 march 2015 >
		Description:	< Get Date Code >
		Modified By:	< Rashid Siddiqui >
		Modified Date:	< 20181227 >
		Description:	< HANDLE CASE OF 31122018 - 01AF>
		Modified Date:	< 20190515 >
		Description:	< Shift Information >

		DECLARE @ReturnValue CHAR(1000) 
		EXEC Assy_Proc_DateCode @ProfitCenterCode = '0066', @ReturnValue = @ReturnValue output 
		SELECT @ReturnValue 
	*/
	BEGIN TRY
	SET NOCOUNT ON;
	DECLARE @DATE_VAL DATETIME = GETDATE()
	DECLARE @DAY VARCHAR(20), @YEAR VARCHAR(20), @WEEKCODE VARCHAR(12)
	DECLARE @CurrentDateCode VARCHAR(10)
	
	SELECT @DAY = DATENAME(WEEKDAY, @DATE_VAL)
	SELECT @YEAR = DATENAME(YEAR, @DATE_VAL)					
	SELECT @WEEKCODE = RIGHT('0' + DATENAME(ISO_WEEK, @DATE_VAL), 2)	
	DECLARE @WEEKDAY VARCHAR(20)					

	SET @WEEKDAY = UPPER(DATENAME(WEEKDAY, @DATE_VAL))					
	IF @WEEKCODE = 53
	BEGIN
		IF @WEEKDAY = 'FRIDAY' OR @WEEKDAY = 'SATURDAY' OR @WEEKDAY = 'SUNDAY'
		BEGIN
			SET @YEAR = @YEAR - 1
		END
	END					
	 -- ADDED BY RS ON 20181227 - HANDLE CASE OF 31122018 - 01AF
	DECLARE @MONTH INT = 0
	SET @MONTH = MONTH(@DATE_VAL)

	IF @MONTH = 12 AND @WEEKCODE = '01'
	BEGIN
		SET @YEAR = @YEAR + 1
	END

	DECLARE @FromTime TIME, @ToTime TIME					
	 --To Get current shift
	DECLARE @CurrentTime AS TIME, @Time AS VARCHAR(10), @Shift AS VARCHAR(10), @ShiftCode VARCHAR(10)

	SET @CurrentTime = @DATE_VAL
	SET @Time = LEFT(CONVERT(VARCHAR(10), @CurrentTime), 8)					
	
	EXEC Assy_Proc_ShiftMst	@time , @ProfitCenterCode, @Shift OUTPUT, @ShiftCode OUTPUT
	
	 -- Get Current day for Night
	IF @Shift = 'NIGHT'
	BEGIN
		SELECT @FromTime = CONVERT(TIME, FromTime), @ToTime = CONVERT(TIME, ToTime)
		FROM ShiftMst (NOLOCK)
			WHERE ShiftName = @Shift AND IsActive = 1 AND ProfitCenterCode = @ProfitCenterCode

		IF @ToTime > @FromTime
			SET @Day = @Day
		ELSE
			IF CONVERT(TIME, @Time) < = (SELECT CONVERT(TIME, ToTime) FROM ShiftMst (NOLOCK) WHERE ShiftName = @Shift
				AND IsActive = 1 AND ProfitCenterCode = @ProfitCenterCode)
			SELECT @DAY = DATENAME(WEEKDAY, DATEADD(d, - 1, @DATE_VAL))
		ELSE
			SET @Day = @Day
	END
	 -- Get Current day for OT
	ELSE IF @Shift = 'OT'
	BEGIN
		SELECT @FromTime = CONVERT(TIME, FromTime), @ToTime = CONVERT(TIME, ToTime)
			FROM ShiftMst (NOLOCK)
				WHERE ShiftName = @Shift AND IsActive = 1 AND ProfitCenterCode = @ProfitCenterCode

		IF @ToTime > @FromTime
			SELECT @DAY = DATENAME(WEEKDAY, DATEADD(d, - 1, @DATE_VAL))
		ELSE
		IF CONVERT(TIME, @Time) < = (SELECT CONVERT(TIME, ToTime) FROM ShiftMst (NOLOCK) WHERE ShiftName = @Shift
				AND IsActive = 1 AND ProfitCenterCode = @ProfitCenterCode)
			SELECT @DAY = DATENAME(WEEKDAY, DATEADD(d, - 1, @DATE_VAL))
		ELSE
			SET @Day = @Day
	END

	DECLARE @Datecode TABLE
	(
		ShiftCode VARCHAR(10), 
		DAY VARCHAR(20), 
		Code VARCHAR(2), 
		Ent_Stamp DATETIME, 
		Ent_By VARCHAR(20), 
		Last_Upd_By VARCHAR(20), 
		Last_Upd_Stamp DATETIME
	)

	INSERT INTO @Datecode
	SELECT
		ShiftCode, 
		Day1, 
		Code, 
		Ent_Stamp, 
		Ent_By, 
		Last_Upd_By, 
		Last_Upd_Stamp
	FROM
		(
			SELECT
			ShiftCode, 
			[Monday], 
			[Tuesday], 
			[Wednesday], 
			[Thursday], 
			[Friday], 
			[Saturday], 
			[Sunday], 
			Ent_Stamp, 
			Ent_By, 
			Last_Upd_By, 
			Last_Upd_Stamp
			FROM DateCodeMst (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
		) P
	UNPIVOT
	(
		Code
			FOR Day1 IN ( Monday, [Tuesday], [Wednesday], [Thursday], [Friday], [Saturday], [Sunday] ) ) AS unpvt
				WHERE ShiftCode = @ShiftCode
		AND Day1 = @Day
	 -- Get date Code = week Code + shift Code + year Code
						
	IF @WEEKDAY = 'MONDAY' AND @CurrentTime< = (SELECT FromTime FROM ShiftMst(NOLOCK) WHERE ShiftName = 'Day' AND ProfitCenterCode = @ProfitCenterCode)
	BEGIN
		DECLARE @PrevYearWeekCode TINYINT
		SELECT @PrevYearWeekCode = RIGHT('0' + DATENAME(ISO_WEEK, @DATE_VAL - 1), 2)	
		
		IF (@PrevYearWeekCode = 53 OR @PrevYearWeekCode = 52) AND @WEEKCODE = 1
		BEGIN
			SET @WEEKCODE = RIGHT(0 + @PrevYearWeekCode, 2)
			SET @YEAR = @YEAR - 1
		END
		ELSE
		BEGIN
			SET @WEEKCODE = @WEEKCODE - 1
			SELECT @WEEKCODE = RIGHT('0' + @WEEKCODE, 2)	
		END
	END

	SELECT @CurrentDateCode = @WEEKCODE
		+ (SELECT UPPER(RTRIM(Code)) FROM @Datecode)
		+ (SELECT LOWER(LTRIM(RTRIM(Code))) FROM YearMst (NOLOCK) WHERE YEAR = @YEAR)

	IF ISNULL(@CurrentDateCode,'')=''
	BEGIN
		DECLARE @Value CHAR(1000) 
		EXEC ASSY_PROC_DATECODE @ProfitCenterCode = @ProfitCenterCode, @ReturnValue = @Value output 
		SELECT @CurrentDateCode= @VALUE
	END
	ELSE
	BEGIN
		IF @Condition = 'ShiftTime' --Added By THK ON 10-05-2019
		BEGIN
			SELECT @CurrentDateCode CurrentDateCode, FromTime, ToTime FROM ShiftMst (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND ShiftName = @Shift
		END
		ELSE
		BEGIN
			SELECT @CurrentDateCode
		END
	END

	SET @ReturnValue = @CurrentDateCode
	SET @ReturnInt = 1
	END TRY
	BEGIN CATCH
		  --CATCH BLOCK BEGINS
          SET @RETURNVALUE = CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|'
                             + CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|'
                             + CAST(ERROR_STATE() AS VARCHAR(5)) + '|'
                             + CAST(ERROR_PROCEDURE() AS VARCHAR(200))
                             + '|' + CAST(ERROR_LINE() AS VARCHAR(5)) + '|'
                             + CAST(ERROR_MESSAGE() AS VARCHAR(1500))
          SET @RETURNINT = 2
      --CATCH BLOCK ENDS 
	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[Assy_proc_Get_DateCode_Prefix]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[Assy_proc_Get_DateCode_Prefix]
(
@PROFITCENTERCODE NVARCHAR(4),
@RETURNVALUE VARCHAR (2000)=NULL OUT,
@RETURNINT INT=NULL OUT	
)
AS
--CREATED BY:<RAVISHANKAR MISHRA>
--CREATED DATE:<28-06-16>
--DECLARE @RETURNVALUE VARCHAR (2000)=NULL 
--EXEC ASSY_PROC_GET_DATECODE_PREFIX @PROFITCENTERCODE='0021',@RETURNVALUE=@RETURNVALUE OUT
--SELECT @RETURNVALUE
BEGIN
		SET NOCOUNT ON

		IF DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE','DATECODE','SHOW_PREFIX',@PROFITCENTERCODE)='Y'
		BEGIN
				SELECT @RETURNVALUE=RTRIM(LTRIM(WH_SHORT_NM)) FROM WAREHOUSE_MASTER WITH(NOLOCK) WHERE WAREHOUSE_CD=@PROFITCENTERCODE
		END
		SET @RETURNINT=1
END

