CREATE PROC [dbo].[ASSY_PROC_GET_NEW_SERIAL_NO]
(
	@P_USER_ID	NVARCHAR(10),
	@P_WH_CODE	NVARCHAR(10),
	@SERIAL_NO  NVARCHAR(32) OUT
) 
AS
BEGIN
	 
	 DECLARE @WH_PREFIX varchar(20)      
	 DECLARE @NEXT_SERIAL_ID varchar(20)          
	 
	 DECLARE @BOX_PREFIX varchar(20)   
	
	 SELECT @WH_PREFIX=DBO.FN_GET_WMS_KEY_VAL(@P_WH_CODE,'WAREHOUSE PREFIX')          
	 SELECT @BOX_PREFIX=DBO.FN_GET_WMS_KEY_VAL(@P_WH_CODE,'DEFAULT BOX_PREFIX')          
	 EXEC PROC_GETNEXTID 'BOX_SERIAL_NO' , @P_USER_ID , @P_WH_CODE,   @NEXT_SERIAL_ID OUT          
	 SET @SERIAL_NO = @BOX_PREFIX + @WH_PREFIX  + RIGHT('0000000' + CONVERT(NVARCHAR,@NEXT_SERIAL_ID),8)          
	
END
