/****** Object:  StoredProcedure [dbo].[Assy_PRoc_Get_Next_MachineCode_OperationCode]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create proc [dbo].[Assy_PRoc_Get_Next_MachineCode_OperationCode]
(
@PROFITCENTERCODE nvarchar(4),
@LINECODE VARCHAR(10),
@PartNumber varchar(20),
@MachineCode varchar(10)
)
as
begin

	--CREATED BY :<RAVISHANKAR MISHRA>
	--CREATED ON :<25/08/2016>
	--exec  Assy_proc_Get_Next_MachineCode_OperationCode '0088','J04','19316006','MCCP'
	--INSERT INTO @ALLPARTS(PARTNO)
		SET NOCOUNT ON

		select   l.MachineCode,l.OperationCode,l.OperationSeqNo into #Temp_PreviousStation from  dbo.RoutingConfigLinewise(nolock) L 
		inner join dbo.RoutingConfigPartWise(nolock)P
		on L.ProfitCenterCode =p.ProfitCenterCode 
		and l.machinecode=p.machinecode
		and l.OperationCode =p.OperationCode 
		where  L.Traceability =1 
		and L.LineCode=@LineCode		
		and p.Traceability =1 
		and p.PartNo =@PartNumber
		and l.ProfitCenterCode=@PROFITCENTERCODE
		order by l.OperationSeqNo  

		create table #Temp_PreviousStation_New
		(
			MachineCode varchar(20),
			OperationCode varchar(20),
			OperationSeqNo int
		)
		create table #Temp_Actual_Machine_Seq
		(
			id int,
			MachineCode varchar(20),
			OperationCode varchar(20),
			OperationSeqNo int
		)
		insert into #Temp_PreviousStation_New(MachineCode,OperationCode,OperationSeqNo)
		select distinct MachineCode,OperationCode,OperationSeqNo  from #Temp_PreviousStation order by OperationSeqNo 
		
		insert into #Temp_Actual_Machine_Seq
		(
			id,
			MachineCode,
			OperationCode,
			OperationSeqNo
		)

		select 
		ROW_NUMBER() over (order by OperationSeqNo)id,
		MachineCode,
		OperationCode,
		OperationSeqNo
		from #Temp_PreviousStation_New(nolock) order by OperationSeqNo
		--select * from #Temp_Actual_Machine_Seq
		select MachineCode,OperationCode from #Temp_Actual_Machine_Seq(nolock) 
		where id=(select id+1 from #Temp_Actual_Machine_Seq(nolock) where MachineCode=@MachineCode )
				
		drop table #Temp_PreviousStation_New
		drop table #Temp_PreviousStation
		drop table #Temp_Actual_Machine_Seq
end




