/****** Object:  StoredProcedure [dbo].[ASSY_PROC_GET_PARAMETERS_ON_FV_STATION]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
/***************************************************************************************                    
PROCEDURE         :     ASSY_PROC_VARIFY_PARAMETERS_ON_FV
AUTHOR            :     SACHIN KUMAR
DATE WRITTEN      :     May 24, 2019
PURPOSE           :     

TEST SCRIPT  
exec ASSY_PROC_GET_PARAMETERS_ON_FV_STATION 'MAL1','0088','L1000829Nd'

****************************************************************************************/
CREATE PROCEDURE [dbo].[ASSY_PROC_GET_PARAMETERS_ON_FV_STATION]
(
 @P_Mode varchar(10)='',
 @P_lineCode varchar(10)='',
 @P_profitCenterCode varchar(10)='',
 @P_barcode varchar(30)='',
 @ReturnValue VARCHAR (2000)=NULL OUT,
 @ReturnInt INT=NULL OUT
)
AS
BEGIN

DECLARE @OC VARCHAR(10) = ''
DECLARE @SEQNo smallint = 0
CREATE TABLE #Get_Parameter_values 
(
   Barcode varchar(100),
   MachineCode varchar(10),
   OperationCode varchar(10),
   TagName varchar(100),
   TagValue varchar(50),
   TagId int,
   SeqNo smallint
)

DECLARE @PartNo VARCHAR(50) = ''

IF (@P_Mode='A')
BEGIN
	select * into #temp_VRF_LS from Assy_LineAssyStatus_Running(nolock) 
	where Barcode=@P_barcode and LineCode=@P_lineCode and ProfitCenterCode=@P_profitCenterCode

	select top 1 @PartNo=isnull(PartNo,'') from #temp_VRF_LS
	
	select distinct p.OperationSeqNo,p.OperationCode,p.MachineCode into #TEMP_ACT_OC 
	from RoutingConfigPartWise(nolock) p inner join
	RoutingConfigLineWise(nolock) l
	on p.MachineCode=l.MachineCode
	where 
	l.LineCode=@P_lineCode
	and p.ProfitCenterCode=@P_profitCenterCode  
	and p.OperationCode not in ('OCIG') 
	and p.OperationRequired=1 and p.Traceability=1
	and l.OperationRequired=1 and l.Traceability=1
	and PartNo=@PartNo

	select *  into #TEMP_VRF_MTM from machineTagMapping(nolock) where LineCode=@P_lineCode and ProfitCenterCode=@P_profitCenterCode

	select * into #temp_VRF_PDR from Assy_LineAssyParamData_Running(nolock) 
	where Barcode=@P_barcode and LineCode=@P_lineCode and ProfitCenterCode=@P_profitCenterCode

	select * into #temp_VRF_TM from  TagMst(nolock) where ProfitCenterCode=@P_profitCenterCode

	select * into #WHILE_TEMP_ACT_OC from #TEMP_ACT_OC

	while exists(select top 1 1 from #WHILE_TEMP_ACT_OC  )
	begin

	select top 1 @OC = OperationCode, @SEQNo=OperationSeqNo from #WHILE_TEMP_ACT_OC order by OperationSeqNo asc

	insert into #Get_Parameter_values(Barcode,MachineCode,OperationCode,TagName,TagValue,TagId,seqNo)
	select pdr.Barcode,pdr.MachineCode,pdr.OperationCode,tag.TagDescription,dtl.Value,tag.TagId,@SEQNo 
	from  #temp_VRF_PDR(nolock) pdr inner join
	Assy_LineAssyParamData_Running_Dtl(nolock) dtl on 
	pdr.UID=dtl.UID
	inner join #temp_VRF_TM tag on
	tag.TagId=dtl.TagId
	where pdr.OperationCode=@OC

	delete #WHILE_TEMP_ACT_OC where OperationCode=@OC

	end
	
	select  distinct oc.MachineCode, oc.OperationSeqNo,mtm.operationCode,tag.TagDescription,'' as TagValue,tagId 
	into #TEMP_PRM_DATA 
	from #TEMP_VRF_MTM mtm inner join #temp_VRF_TM tag on tag.tagName=mtm.tagName
	inner join #TEMP_ACT_OC oc on oc.operationCode= mtm.operationCode

	insert into #Get_Parameter_values(Barcode,MachineCode,OperationCode,TagName,TagValue,TagId,seqNo)
	select @P_barcode ,l.MachineCode ,l.operationCode ,
	l.TagDescription ,l.TagValue ,l.tagId ,l.OperationSeqNo from
	#TEMP_PRM_DATA l  left join #Get_Parameter_values f 
	on l.tagId=f.tagId and l.MachineCode=f.MachineCode 
	where f.barcode is null

	select Barcode,MachineCode,OperationCode,TagName,TagValue as 'Value' 
	from #Get_Parameter_values order by SeqNo


END


END

GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_Get_Pending_Parts]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[Assy_Proc_Get_Pending_Parts]
(
    @CONDITION VARCHAR(60),
	@ProfitCenterCode nvarchar(4),
	@Linecode varchar(10)
)
as
begin
		--<Author>: Ravishankar Mishra
		----<Created Date>:15-11-16	
		--exec Assy_Proc_Get_Pending_Parts @CONDITION='PREVIOUS', @ProfitCenterCode='0088',@Linecode='j04'
		--exec Assy_Proc_Get_Pending_Parts @CONDITION='Saved', @ProfitCenterCode='0088',@Linecode='j04'

		SET NOCOUNT ON
		declare @TV as table
		(
			ProfitCenterCode nvarchar(4),
			LineCode varchar(10),
			Barcode varchar(100)
			,MachineCode varchar(10),
			OperationCode varchar(10) 
			,OperationSeqNo smallint
			,StationCode varchar(10)
			,datecode varchar(10)
			,partno varchar(60)
			,userid varchar(20)  
		)						
			if @CONDITION='PREVIOUS'
			begin
						;with CTE
						as
						(	select A.ProfitCenterCode,A.LineCode,A.Barcode,(case when max(r.OperationSeqNo+1)=9 then 10 else max(r.OperationSeqNo+1) end) OperationSeqNo
						,A.StationCode,A.datecode,A.partno,A.userid   
							from dbo.Assy_LineAssyStatus_Running A with(nolock) 
							inner join dbo.RoutingConfigLineWise R with(nolock) 
								on A.ProfitCenterCode =r.ProfitCenterCode 
								and a.linecode=r.LineCode 
								and a.MachineCode =r.MachineCode 
								and a.OperationCode =r.OperationCode 
							where A.ProfitCenterCode=@ProfitCenterCode and A.linecode=@Linecode and isnull(status,'')='PS'
							and isnull(r.OperationRequired ,0)=1 and isnull(r.Traceability ,0)=1 and isnull(IsPendingPart,0)=0
							group by A.ProfitCenterCode,A.LineCode,A.Barcode ,A.StationCode,A.datecode,A.partno,A.userid
						)

						insert into @TV
						(
							ProfitCenterCode,LineCode,Barcode,MachineCode,OperationCode ,OperationSeqNo,StationCode,datecode,partno,userid 
						)
						select C.ProfitCenterCode,C.LineCode,C.Barcode,r.MachineCode,r.OperationCode ,c.OperationSeqNo,C.StationCode,C.datecode,C.partno,C.userid   
							from CTE C with(nolock)  
						inner join dbo.RoutingConfigLineWise R with(nolock) 
							on c.ProfitCenterCode =r.ProfitCenterCode 
							and c.linecode=r.LineCode 
							and c.OperationSeqNo=r.OperationSeqNo 
						where isnull(r.OperationRequired ,0)=1 and isnull(r.Traceability ,0)=1
						order by c.OperationSeqNo
						
						delete A from
						(
 
						 select *, row_number() over( partition by ProfitCenterCode,LineCode,Barcode,MachineCode,OperationCode,OperationSeqNo,StationCode,datecode,partno 
						 order by ProfitCenterCode,LineCode,Barcode,MachineCode,OperationCode,OperationSeqNo,StationCode,datecode,partno)id from @TV
						 ) A
						where id<>1
												
						MERGE Assy_LineAssyStatus_Running PP
						USING @TV UT ON PP.ProfitCenterCode = UT.ProfitCenterCode
						and PP.LineCode = UT.LineCode
						and PP.MachineCode = UT.MachineCode 
						and PP.Barcode = UT.Barcode 
						WHEN NOT MATCHED THEN					
							insert 
							(
								ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,Datecode,PartNo,UserID,ScanTimestamp
							)
							values( UT.ProfitCenterCode,UT.LineCode,UT.MachineCode,ut.OperationCode,ut.StationCode,UT.Barcode,UT.Datecode,UT.PartNo,ut.UserID,getdate());
						--WHEN MATCHED THEN   
							--UPDATE SET ScanTimestamp=getdate();

						

			end
			else if @CONDITION='Saved'
			begin
						;with CTE
						as
						(	select A.ProfitCenterCode,A.LineCode,A.Barcode,(case when max(r.OperationSeqNo+1)=9 then 10 else max(r.OperationSeqNo+1) end) OperationSeqNo
						    ,A.StationCode,A.datecode,A.partno,A.userid   
							from dbo.Assy_LineAssyStatus_Running A with(nolock) 
							inner join dbo.RoutingConfigLineWise R with(nolock) 
								on A.ProfitCenterCode =r.ProfitCenterCode 
								and a.linecode=r.LineCode 
								and a.MachineCode =r.MachineCode 
								and a.OperationCode =r.OperationCode 
							where A.ProfitCenterCode=@ProfitCenterCode and A.linecode=@Linecode and isnull(status,'')='PS'
							and isnull(r.OperationRequired ,0)=1 and isnull(r.Traceability ,0)=1 and isnull(IsPendingPart,0)=1
							group by A.ProfitCenterCode,A.LineCode,A.Barcode ,A.StationCode,A.datecode,A.partno,A.userid
						)
						insert into @TV
						(
							ProfitCenterCode,LineCode,Barcode,MachineCode,OperationCode ,OperationSeqNo,StationCode,datecode,partno,userid 
						)

						select C.ProfitCenterCode,C.LineCode,C.Barcode,r.MachineCode,r.OperationCode ,c.OperationSeqNo,C.StationCode,C.datecode,C.partno,C.userid   
							from CTE C with(nolock)  
						inner join dbo.RoutingConfigLineWise R with(nolock) 
							on c.ProfitCenterCode =r.ProfitCenterCode 
							and c.linecode=r.LineCode 
							and c.OperationSeqNo=r.OperationSeqNo 
						where isnull(r.OperationRequired ,0)=1 and isnull(r.Traceability ,0)=1
						order by c.OperationSeqNo

				
						MERGE Assy_LineAssyStatus_Running PP
						USING @TV UT ON PP.ProfitCenterCode = UT.ProfitCenterCode
						and PP.LineCode = UT.LineCode
						and PP.MachineCode = UT.MachineCode 
						and PP.Barcode = UT.Barcode 
						WHEN NOT MATCHED THEN					
							insert 
							(
								ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,Datecode,PartNo,UserID,ScanTimestamp,IsPendingPart
							)
							values( UT.ProfitCenterCode,UT.LineCode,UT.MachineCode,ut.OperationCode,ut.StationCode,UT.Barcode,UT.Datecode,UT.PartNo,ut.UserID,getdate(),1);
					

								;MERGE Assy_PreviousPending_Parts PP
									USING @TV UT ON PP.ProfitCenterCode = UT.ProfitCenterCode
									and PP.LineCode = UT.LineCode
									and PP.MachineCode = UT.MachineCode 
									and PP.Barcode = UT.Barcode 
								    and  isnull(pp.REASON_CD,'')=''
									WHEN NOT MATCHED THEN					
										insert 
										(
											ProfitCenterCode,LineCode,MachineCode,Barcode,REASON_CD,Remarks,IsProcessed,ent_by,ent_stamp
										)
										values( UT.ProfitCenterCode,UT.LineCode,UT.MachineCode,UT.Barcode,NULL,NULL,1,USERID,Getdate());
									
																	
			end

end

GO
