/****** Object:  StoredProcedure [dbo].[Assy_Proc_Get_Previous_MachineCode]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

--declare @PrevMachineCode varchar(20)=null
--exec Assy_Proc_Get_Previous_MachineCode @LineCode='M07',@MachineCode='MCrt',@PartNumber='29150259',@PrevMachineCode=@PrevMachineCode output
--select @PrevMachineCode

CREATE proc [dbo].[Assy_Proc_Get_Previous_MachineCode]
(
@LineCode varchar(10)=null,
@MachineCode varchar(20)='MCms',
@PartNumber varchar(10)=null,
@PrevMachineCode varchar(20)=null output
)
as
begin
		
		--Author- Ravishankar Mishra
		--Created Date-31-10-2014

		SET NOCOUNT ON

		select   l.MachineCode,l.OperationSeqNo into #Temp_PreviousStation from  RoutingConfigLinewise(nolock) L 
		inner join RoutingConfigPartWise(nolock)P
		on L.ProfitCenterCode =p.ProfitCenterCode 
		and l.machinecode=p.machinecode
		and l.OperationCode =p.OperationCode 

		where  L.Traceability =1 
		and L.LineCode=@LineCode		
		and p.Traceability =1 
		and p.PartNo =@PartNumber
		order by l.OperationSeqNo  

		create table #Temp_PreviousStation_New
		(
		MachineCode varchar(20),
		OperationSeqNo int

		)

		create table #Temp_Actual_Machine_Seq
		(
		id int,
		MachineCode varchar(20),
		OperationSeqNo int

		)

		insert into #Temp_PreviousStation_New(MachineCode,OperationSeqNo)
		select distinct MachineCode,OperationSeqNo   from #Temp_PreviousStation order by OperationSeqNo 
		
		insert into #Temp_Actual_Machine_Seq
		(
		id,
		MachineCode,
		OperationSeqNo

		)

		select 
		ROW_NUMBER() over (order by OperationSeqNo)id,
		MachineCode,
		OperationSeqNo
		from #Temp_PreviousStation_New(nolock) order by OperationSeqNo
		--select * from #Temp_Actual_Machine_Seq
		select @PrevMachineCode=MachineCode from #Temp_Actual_Machine_Seq(nolock) 
		where id=(select id-1 from #Temp_Actual_Machine_Seq(nolock) where MachineCode=@MachineCode )
		--select @PrevMachineCode

		if @PrevMachineCode is null or @PrevMachineCode=''
			set @PrevMachineCode='First_station'

		drop table #Temp_PreviousStation_New
		drop table #Temp_PreviousStation
		drop table #Temp_Actual_Machine_Seq
end

