/***************************************************************************************                    
PROCEDURE         :     ASSY_PROC_GET_ROUTINGDETAILS
AUTHOR            :     SACHIN KUMAR
DATE WRITTEN      :     July 24, 2017
PURPOSE           :     

TEST SCRIPT  
declare @r nvarchar(2000)
declare @r2 int
exec ASSY_PROC_GET_ROUTINGDETAILS '0088','MAL1','','','','isLotNumberReq',
@ReturnValue=@r out , @ReturnInt=@r2
select @r , @r2

****************************************************************************************/
CREATE PROCEDURE [dbo].[ASSY_PROC_GET_ROUTINGDETAILS]
(
 @P_Mode varchar(100)='',
 @P_profitCenterCode varchar(10)='',
 @P_lineCode varchar(10)='',
 @P_MachineCode varchar(10)='',
 @P_OperationCode varchar(10)='',
 @P_PartNo varchar(30)='',
 @P_KeyType varchar(100)='',
 @P_KeyValue varchar(100)='',
 @P_UserCode varchar(30) = '',
 @ReturnValue VARCHAR (2000)=NULL OUT,
 @ReturnInt INT=NULL OUT
)
AS
BEGIN

IF(@P_MODE='GET')
BEGIN
		if(ISNULL(@P_KeyType,'')<>'')
		begin


			SELECT @ReturnValue=ISNULL(KeyValue,'') FROM ROUTINGCONFIGDETAILS(NOLOCK)
			where ProfitCenterCode=ISNULL(@P_profitCenterCode,'') and LineCode=ISNULL(@P_lineCode,'')
			and MachineCode=ISNULL(@P_MachineCode,'') and OperationCode=ISNULL(@P_OperationCode,'')
			and PartNumber=ISNULL(@P_PartNo,'') and KeyType=ISNULL(@P_KeyType,'') and STS_CD=0

		end
END

IF(@P_MODE='UPDATE')
BEGIN
		if(ISNULL(@P_KeyType,'')<>'' AND ISNULL(@P_KeyValue,'') <> '')
		begin

			UPDATE ROUTINGCONFIGDETAILS
			SET KeyValue=@P_KeyValue,LAST_UPD_BY=@P_UserCode,LAST_UPD_STAMP=getdate()
			where ProfitCenterCode=ISNULL(@P_profitCenterCode,'') and LineCode=ISNULL(@P_lineCode,'')
			and MachineCode=ISNULL(@P_MachineCode,'') and OperationCode=ISNULL(@P_OperationCode,'')
			and PartNumber=ISNULL(@P_PartNo,'') and KeyType=ISNULL(@P_KeyType,'') and STS_CD=0

			SELECT @ReturnValue='OK'

		end
END

IF(@P_MODE='INSERT_OR_UPDATE_IMPORT_BARCODE_MODE')
BEGIN

		if exists (select top 1 1 from RoutingConfigDetails(nolock) where ProfitCenterCode=@P_profitCenterCode and 
		sts_cd=0 and keyType='IsImportBarcodeMode' and LineCode=@P_lineCode and PartNumber=@P_PartNo
		)
		begin
		update RoutingConfigDetails 
		set keyValue = convert(varchar,convert(bit,@P_KeyValue)),LAST_UPD_BY=@P_UserCode,LAST_UPD_STAMP=getdate()
		where ProfitCenterCode=@P_profitCenterCode and 
		sts_cd=0 and keyType='IsImportBarcodeMode' and LineCode=@P_lineCode and PartNumber=@P_PartNo
		end
		else
		begin
		insert into RoutingConfigDetails (ProfitCenterCode,LineCode,MachineCode,OperationCode,PartNumber,KeyType,
		KeyValue,SeqNumber,isSeqReq,chkFromTable,Remarks,STS_CD,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP
		)values(@P_profitCenterCode,@P_lineCode,'','',@P_PartNo,'IsImportBarcodeMode',convert(varchar,convert(bit,@P_KeyValue)),'',
		'','','Imported Barcode Setting',0,@P_UserCode,GETDATE(),@P_UserCode,GETDATE()
		)
		end
		set @ReturnValue='OK'
		set @ReturnInt=1

END

END


GO
