/*************************************************************************************** 
PROCEDURE : ASSY_PROC_GET_SCANNED_VALUE
AUTHOR: SACHIN KUMAR
DATE WRITTEN :  May 31, 2017
PURPOSE:  To 

TEST SCRIPT  
Declare @RequesTD varchar(2000)
EXEC ASSY_PROC_GET_SCANNED_VALUE 'getScannedValue','','0088','J04','MC4S',
'OC4S','ASSY_RESULT_50A'
select @RequesTD
 
****************************************************************************************/
CREATE procedure [dbo].[ASSY_PROC_GET_SCANNED_VALUE]
(
   @P_Mode varchar(20)='',
   @P_REQUEST_ID varchar(17)='',
   @P_PROFITCENTER_CODE varchar(10)='',
   @P_LINE_CODE varchar(10)='',     
   @P_Machine_Code varchar(10)='', 
   @P_Operation_Code varchar(10)='',     
   @P_Table_Name varchar(100)='',
   @ReturnValue VARCHAR (2000)=NULL OUT,
   @ReturnInt INT=NULL OUT
)
AS
BEGIN

DECLARE @LINE_CODE varchar(10)=@P_LINE_CODE --'CEL10' -- From Window Service we get this Line Code
DECLARE @PROFITCENTER_CODE varchar(10) =@P_PROFITCENTER_CODE --'0018' -- From Window Service we get this ProfitCenterCode
DECLARE @SQL_QUERY nvarchar(2000)
IF(@P_Mode='getScannedValue')
BEGIN
	
	SET @SQL_QUERY='SELECT SCANID,PARTNUMBER,BARCODE,SCANSTATUS,SCANTIMESTAMP,STS_CD,TS_SCAN_OK FROM '+
	 @P_TABLE_NAME+'(NOLOCK) WHERE SCANSTATUS=1 AND STS_CD=14 AND TS_SCAN_OK in (0,1)'
	 EXEC(@SQL_QUERY)
END

IF(@P_Mode='Modal_Not_OK')
BEGIN
	
	SET @SQL_QUERY='UPDATE '+ @P_TABLE_NAME+' SET STS_CD=8 , TD_ACK_Time=getdate() WHERE SCANSTATUS=1 AND STS_CD=14 AND TS_SCAN_OK=0 AND SCANID ='+@P_REQUEST_ID
	EXEC(@SQL_QUERY)

END


