/****** Object:  StoredProcedure [dbo].[ASSY_PROC_GET_SHIFTDETAILS]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROC [dbo].[ASSY_PROC_GET_SHIFTDETAILS] (
												@PROFITCENTERCODE VARCHAR (10)=NULL,
												@CURRENT_TIME  VARCHAR(20),
												@CURRENT_SHIFT VARCHAR(10) OUTPUT,
												@SHIFTCODE     VARCHAR(10) OUTPUT)
AS
  BEGIN
      SET NOCOUNT ON

      DECLARE @STARTSHIFT AS CHAR(12), @ENDSHIFT AS CHAR(12)

      SELECT @STARTSHIFT = CONVERT(CHAR(12), FROMTIME, 114),
             @ENDSHIFT = CONVERT(CHAR(12), TOTIME, 114)
      FROM   SHIFTMST
      WHERE  TOTIME < FROMTIME
             AND ( PROFITCENTERCODE = @PROFITCENTERCODE )

      SELECT @CURRENT_SHIFT = SHIFT,
             @SHIFTCODE = SHIFTCODE
      FROM   (SELECT RTRIM(SHIFTNAME) SHIFT,
                     SHIFTCODE
              FROM   SHIFTMST
              WHERE  CONVERT(CHAR(12), @CURRENT_TIME, 114) >=
                     CONVERT(CHAR(12), FROMTIME, 114)
                     AND CONVERT(CHAR(12), @CURRENT_TIME, 114) <=
                         CONVERT(CHAR(12), TOTIME, 114) AND (PROFITCENTERCODE=@PROFITCENTERCODE)
              UNION ALL
              SELECT RTRIM(SHIFTNAME) SHIFT,
                     SHIFTCODE
              FROM   SHIFTMST
              WHERE  PROFITCENTERCODE = @PROFITCENTERCODE
                     AND ( ( CONVERT(CHAR(12), @CURRENT_TIME, 114) ) >=
                           '00:00:00:000'
                           AND CONVERT(CHAR(12), @CURRENT_TIME, 114) <=
                               CONVERT(CHAR(12), @ENDSHIFT, 114)
                            OR ( CONVERT(CHAR(12), @CURRENT_TIME, 114) >
                                 CONVERT(CHAR(12), @STARTSHIFT, 114)
                                 AND CONVERT(CHAR(12), @CURRENT_TIME, 114) <
                                     '24:00:00:000' ) AND (PROFITCENTERCODE=@PROFITCENTERCODE)
                         )
                     AND ( CONVERT(CHAR(12), FROMTIME, 114) >= @STARTSHIFT
                           AND CONVERT(CHAR(12), TOTIME, 114) <= @ENDSHIFT )) A
  END 


   SET ANSI_NULLS OFF


GO
