/********************************************************************
 Procedure Name : ASSY_PROC_GetCaliperSerial_DateCodeWise
 Objective		: Provide Running Caliper Serial Number for Current Shift DateCode
 Created By		: Sachin Kumar
 Created On		: 14 06 2017

 Revision History:

 Test Script :
 declare @DateCode varchar(4)
 declare @CaliperSerialNo varchar(5)
 EXEC ASSY_PROC_GetCaliperSerial_DateCodeWise 
 '0088','J04','MCDC','OC90',@P_ReturnCaliperSerialNo=@CaliperSerialNo out
 ,@P_ReturnDateCode=@DateCode out
 select @DateCode , @CaliperSerialNo
*********************************************************************/
CREATE Proc [dbo].[ASSY_PROC_GetCaliperSerial_DateCodeWise]
(
@P_PROFITCENTERCODE VARCHAR(8)='',
@P_LINECODE VARCHAR(10)=NULL,
@P_MachineCode varchar(10)='',
@P_OperationCode varchar(10)='',
@P_ReturnDateCode VARCHAR (4)='' OUT,
@P_ReturnCaliperSerialNo VARCHAR (5)='' OUT
)
AS
BEGIN


EXEC ASSY_PROC_DATECODE @PROFITCENTERCODE=@P_PROFITCENTERCODE,
@RETURNVALUE= @P_ReturnDateCode OUTPUT


IF EXISTS(SELECT TOP 1 1 FROM ASSY_GETCALIPERSERIAL_DATECODEWISE(NOLOCK)
WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE AND LINECODE=@P_LINECODE AND MACHINECODE=@P_MACHINECODE and
OPERATIONCODE=@P_OPERATIONCODE AND DATECODE=@P_ReturnDateCode
)
BEGIN

UPDATE ASSY_GETCALIPERSERIAL_DATECODEWISE
SET CaliperSerialNo=CaliperSerialNo+1
WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE AND LINECODE=@P_LINECODE AND MACHINECODE=@P_MACHINECODE and
OPERATIONCODE=@P_OPERATIONCODE AND DATECODE=@P_ReturnDateCode

select @P_ReturnCaliperSerialNo=convert(varchar,CaliperSerialNo) from ASSY_GETCALIPERSERIAL_DATECODEWISE(NOLOCK) 
WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE AND LINECODE=@P_LINECODE AND MACHINECODE=@P_MACHINECODE and
OPERATIONCODE=@P_OPERATIONCODE AND DATECODE=@P_ReturnDateCode

set @P_ReturnCaliperSerialNo = REPLACE(STR(@P_ReturnCaliperSerialNo, 4), SPACE(1), '0')

END
ELse
begin

insert into ASSY_GetCaliperSerial_DateCodeWise(
ProfitCenterCode,LineCode,MachineCode,OperationCode,Datecode,CaliperSerialNo,STS_CD,ENT_BY,ENT_STAMP,UPD_BY,UPD_STAMP)
values(@P_PROFITCENTERCODE,@P_LINECODE,@P_MACHINECODE,@P_OPERATIONCODE,@P_ReturnDateCode,1,0,'ADMIN',GETDATE(),'ADMIN',GETDATE())

select @P_ReturnCaliperSerialNo=convert(varchar,CaliperSerialNo) from ASSY_GETCALIPERSERIAL_DATECODEWISE(NOLOCK) 
WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE AND LINECODE=@P_LINECODE AND MACHINECODE=@P_MACHINECODE and
OPERATIONCODE=@P_OPERATIONCODE AND DATECODE=@P_ReturnDateCode

set @P_ReturnCaliperSerialNo = REPLACE(STR(@P_ReturnCaliperSerialNo, 4), SPACE(1), '0')


end

IF EXISTS(SELECT TOP 1 1 FROM ASSY_GETCALIPERSERIAL_DATECODEWISE(NOLOCK)
WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE AND LINECODE=@P_LINECODE AND MACHINECODE=@P_MACHINECODE and
OPERATIONCODE=@P_OPERATIONCODE AND DATECODE<>@P_ReturnDateCode
)
BEGIN

insert into ASSY_GetCaliperSerial_DateCodeWise_log(
ProfitCenterCode,LineCode,MachineCode,OperationCode,Datecode,CaliperSerialNo,STS_CD,ENT_BY,ENT_STAMP,UPD_BY,UPD_STAMP)
SELECT ProfitCenterCode,LineCode,MachineCode,OperationCode,Datecode,CaliperSerialNo,STS_CD,ENT_BY,ENT_STAMP,UPD_BY,UPD_STAMP
FROM ASSY_GETCALIPERSERIAL_DATECODEWISE(NOLOCK)
WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE AND LINECODE=@P_LINECODE AND MACHINECODE=@P_MACHINECODE and
OPERATIONCODE=@P_OPERATIONCODE AND DATECODE<>@P_ReturnDateCode


delete FROM ASSY_GETCALIPERSERIAL_DATECODEWISE
WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE AND LINECODE=@P_LINECODE AND MACHINECODE=@P_MACHINECODE and
OPERATIONCODE=@P_OPERATIONCODE AND DATECODE<>@P_ReturnDateCode

END
END


