CREATE procedure [dbo].[Assy_Proc_GetHourleyRpt]                

as

BEGIN

--Exec Assy_Proc_GetHourleyRpt

--Select * from Assy_HourlyRpt
--Drop procedure Assy_Proc_GetHourleyRpt
/*********************************************
Select RptingDate,Fromtime,Totime,ProfitCenterCode,Linecode,Datecode,PartNo,Status,Pass,Fail from Assy_HourlyRpt(nolock)  order by  Linecode,Datecode,PartNo
*****************************/
set nocount on

if OBJECT_ID('#Productionpass') is not null
drop table #Productionpass

if OBJECT_ID('#Productionfail') is not null
drop table #Productionfail 

if OBJECT_ID('#Assy_HourlyRpt') is not null
drop table #Assy_HourlyRpt
Declare @HrlyrptingDate Date=convert(varchar(10),getdate()-1,121)
Declare @fromdate varchar(25)
Declare @Todate varchar(25)
set @fromdate=cast(@HrlyrptingDate as varchar(10))+' 07:30:00'
set @Todate=cast(Dateadd(dd,1,@HrlyrptingDate) as varchar(10))+' 02:30:00'

Begin

select aa.ProfitCenterCode,aa.Partno,aa.LineCode,Datecode,[Status],left(Fromtime,5) Fromtime,left(Totime,5) Totime,count(*) Pass, 0 fail 
 into #Productionpass from [Assy_LineAssyStatus] aa right join Assy_HourlyMst bb 
on left(cast(aa.resulttimestamp as time),5) between Fromtime and Totime and status='PS' and Convert(varchar(20),ResultTimestamp,120) between @fromdate and @todate 
 and OperationCode in(select top 1 PARAMETER_VALUE 
from PARAMETER_MST where PARAMETER_C ='assline' and PARAMETER_C1 ='FinalViewing' and PARAMETER_C2 ='QCStation_OperationCode')
group by aa.ProfitCenterCode,aa.Partno,aa.LineCode,Datecode,status,Fromtime,Totime order by Fromtime asc


select aa.ProfitCenterCode,aa.Partno,aa.LineCode,Datecode,[Status],left(Fromtime,5) Fromtime,left(Totime,5) Totime,0 Pass,count(*) Fail 
into #Productionfail
from [Assy_LineAssyStatus] aa right join Assy_HourlyMst bb 
on left(cast(aa.resulttimestamp as time),5) between Fromtime and Totime and status='FA' and Convert(varchar(20),ResultTimestamp,120) between @fromdate and @todate
and OperationCode in(select top 1 PARAMETER_VALUE 
from PARAMETER_MST where PARAMETER_C ='assline' and PARAMETER_C1 ='FinalViewing' and PARAMETER_C2 ='QCStation_OperationCode')
group by aa.ProfitCenterCode,aa.Partno,aa.LineCode,Datecode,status,Fromtime,Totime order by Fromtime asc

update #Productionpass set pass=0  where partno is null
update #Productionfail set fail=0 where partno is null

select * into #Assy_HourlyRpt from #Productionpass
union 
select * from #Productionfail

Delete from #Assy_HourlyRpt where fromtime in(
Select fromtime from #Assy_HourlyRpt
group by fromtime,totime having count(*)>1) and partno is null

TRUNCATE TABLE Assy_HourlyRpt
Insert into Assy_HourlyRpt(RptingDate,Fromtime,Totime,ProfitCenterCode,PartNo,LineCode,Datecode,[Status],Pass,Fail)
select @HrlyrptingDate,aa.Fromtime,aa.Totime,isnull(aa.ProfitCenterCode,'')ProfitCenterCode,isnull(PartNo,'')PartNo,isnull(aa.LineCode,'')LineCode,
isnull(Datecode,'')Datecode,isnull([Status],'') Status,Pass,Fail from #Assy_HourlyRpt aa join Assy_HourlyMst bb on
 aa.Fromtime=left(bb.fromtime,5) and aa.Totime=left(bb.totime,5) 
 order by bb.Sno asc

End

END












