Create PROCEDURE [dbo].[Assy_Proc_GetPRN] 
	@ProfitCode VARCHAR(10) = NULL, 
	@LineCode VARCHAR(10) = NULL,
	@Condition VARCHAR(500) = NULL,
	@CustomerPartNumber VARCHAR(30) = NULL,
	@PartNo VARCHAR(30) = NULL,
	@ReturnValue VARCHAR (2000) = NULL OUT,
	@ReturnInt INT = NULL OUT
AS
BEGIN
	-- =============================================
	-- Author:	<Rashid Siddiqui>
	-- Create date:	<12 Oct 2015>
	-- Description:	<To get PRN File From Database>
	-- To Rembember
	-- Nothing = 0
	-- Success = 1
	-- Error = 2
	-- AlreadyExists = 3
	-- NotExists = 4
		
	-- EXEC Assy_Proc_GetPRN @ProfitCode = '0021', @LineCode = 'P2', @Condition = 'GET_REPRINT_PRN'
	-- SELECT * FROM Assy_RunningPart (NOLOCK)
	-- 29049100
	-- =============================================
	BEGIN TRY
		DECLARE @PartType VARCHAR(10) = '',  @PRNFile NVARCHAR(MAX) = '' --, @PartNo VARCHAR(30) = '', @CustomerPartNumber VARCHAR(30) = ''

		IF @Condition = 'GET_REGULAR_PRN'
		BEGIN
			SELECT Top 1 @PartType = ISNULL(PartType,''), @PartNo = ISNULL(Assy_PartNo,''), @CustomerPartNumber = CustomerPartNo FROM Assy_RunningPart WITH (NOLOCK)
			WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode Order by CreatedDate Desc
			IF @PartNo != ''
			BEGIN								 
				IF @PartType = 'STMC'
				BEGIN			
					-- Get PRN File FOR THIS STMC PART NO
					IF @CustomerPartNumber != ''
							SELECT Distinct Top 1 @PRNFile = ISNULL(PGM.PRNFile,'')
								FROM Assy_PRN_CustomerGroupMaster PCGM (NOLOCK)
									INNER JOIN Assy_PRN_GroupMaster PGM (NOLOCK)
										ON PCGM.GroupCode = PGM.GroupCode
											WHERE PCGM.PartNo = @PartNo AND PCGM.CustomerPartNo = @CustomerPartNumber

						SET @ReturnValue = @PRNFile
						SET @ReturnInt = 1
				END
			END
		END
		ELSE IF @Condition = 'GET_REPRINT_PRN'
		BEGIN
			-- Get PRN File FOR REPRINT OF THIS STMC PART NO
					IF @CustomerPartNumber != ''
							SELECT Distinct Top 1 @PRNFile = ISNULL(PGM.PRNFile,'')
								FROM Assy_PRN_CustomerGroupMaster PCGM (NOLOCK)
									INNER JOIN Assy_PRN_GroupMaster PGM (NOLOCK)
										ON PCGM.GroupCode = PGM.GroupCode
											WHERE PCGM.PartNo = @PartNo AND PCGM.CustomerPartNo = @CustomerPartNumber

						SET @ReturnValue = @PRNFile
						SET @ReturnInt = 1
		END
		ELSE IF @Condition = 'GET_MACHINE_LINE_PRN'
		BEGIN
			-- Get PRN File FOR Print of Line Code and Machine Code
			SELECT Top 1 @PRNFile = ISNULL(PGM.PRNFile,'')
				FROM Assy_PRN_GroupMaster PGM (NOLOCK) WHERE GroupCode = 'GC_JHAGADIA_FINALVIEWING_STATION'

			SET @ReturnValue = @PRNFile
			SET @ReturnInt = 1
		END
	END TRY
	BEGIN CATCH  
	--CATCH BLOCK BEGINS
		SET @ReturnValue =	CAST(ERROR_NUMBER() as VARCHAR(5)) + '|' + 
		CAST(ERROR_SEVERITY()as VARCHAR(5)) + '|' + 
		CAST(ERROR_STATE() as VARCHAR(5)) + '|' + 
		CAST(ERROR_PROCEDURE() as VARCHAR(200)) + '|' + 
		CAST(ERROR_LINE() as VARCHAR(5)) + '|' + 
		CAST(ERROR_MESSAGE() as VARCHAR(1500))
		RAISERROR(@ReturnValue,16,1)
		SET @ReturnInt = 2
	--CATCH BLOCK ENDS 
	END CATCH
END



GO
