 Objective		: Provide Running Caliper Serial Number for Current Shift DateCode
 Created By		: Sachin Kumar
 Created On		: 14 06 2017

 Revision History:
  Test Script :
 declare @DateCode varchar(4)
 declare @CaliperSerialNo varchar(4)
 EXEC ASSY_PROC_GetSerial_DateWise 
 '0088','J04','MCDC',@P_ReturnSerialNo=@CaliperSerialNo out
 ,@P_ReturnDateCode=@DateCode out
 select @DateCode , @CaliperSerialNo
*********************************************************************/
CREATE Proc [dbo].[ASSY_PROC_GetSerial_DateWise]
(
@P_PROFITCENTERCODE VARCHAR(8)=NULL,
@P_LINECODE VARCHAR(10)=NULL,
@P_PartNumber varchar(30)=NUll,
@P_ReturnDateCode VARCHAR (4)=NULL OUT,
@P_ReturnSerialNo VARCHAR (4)=NULL OUT
)
AS
BEGIN


EXEC ASSY_PROC_DATECODE @PROFITCENTERCODE=@P_PROFITCENTERCODE,
@RETURNVALUE= @P_ReturnDateCode OUTPUT


IF EXISTS(SELECT TOP 1 1 FROM ASSY_GETSERIAL_DATEWISE(NOLOCK)
WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE AND LINECODE=@P_LINECODE 
--and [DATE]=convert(date, getdate()) Change Date Logic To ShiftWise
and [DateCode]=@P_ReturnDateCode
)
BEGIN

UPDATE ASSY_GETSERIAL_DATEWISE
SET SerialNo=SerialNo+1
WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE AND LINECODE=@P_LINECODE 
--and [DATE]=convert(date, getdate()) Change Date Logic To ShiftWise
and [DateCode]=@P_ReturnDateCode

select @P_ReturnSerialNo=convert(varchar,SerialNo) from ASSY_GETSERIAL_DATEWISE(NOLOCK) 
WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE AND LINECODE=@P_LINECODE   
--and [DATE]=convert(date, getdate()) Change Date Logic To ShiftWise
and [DateCode]=@P_ReturnDateCode

set @P_ReturnSerialNo = @P_ReturnSerialNo

END
ELse
begin

insert into ASSY_GETSERIAL_DATEWISE(
ProfitCenterCode,LineCode,Date,Datecode,SerialNo,STS_CD,ENT_BY,ENT_STAMP,UPD_BY,UPD_STAMP)
values(@P_PROFITCENTERCODE,@P_LINECODE,convert(date, getdate()),@P_ReturnDateCode,1,0,'ADMIN',GETDATE(),'ADMIN',GETDATE())

select @P_ReturnSerialNo=convert(varchar,SerialNo) from ASSY_GETSERIAL_DATEWISE(NOLOCK) 
WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE AND LINECODE=@P_LINECODE  
--and [DATE]=convert(date, getdate()) Change Date Logic To ShiftWise
and [DateCode]=@P_ReturnDateCode

set @P_ReturnSerialNo = @P_ReturnSerialNo


end
print 1
IF EXISTS(SELECT TOP 1 1 FROM ASSY_GETSERIAL_DATEWISE(NOLOCK)
WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE AND LINECODE=@P_LINECODE AND   
--and [DATE]<>convert(date, getdate()) Change Date Logic To ShiftWise
[DateCode]<>@P_ReturnDateCode
)
BEGIN

print 2
insert into ASSY_GetSerial_DateWise_log(
ProfitCenterCode,LineCode,Date,Datecode,SerialNo,STS_CD,ENT_BY,ENT_STAMP,UPD_BY,UPD_STAMP)
SELECT ProfitCenterCode,LineCode,Date,Datecode,SerialNo,STS_CD,ENT_BY,ENT_STAMP,UPD_BY,UPD_STAMP
FROM ASSY_GetSerial_DateWise(NOLOCK)
WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE AND LINECODE=@P_LINECODE AND   
--and [DATE]<>convert(date, getdate()) Change Date Logic To ShiftWise
[DateCode]<>@P_ReturnDateCode


delete FROM ASSY_GetSerial_DateWise
WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE AND LINECODE=@P_LINECODE AND   
--and [DATE]<>convert(date, getdate()) Change Date Logic To ShiftWise
[DateCode]<>@P_ReturnDateCode

END

END










