AS
BEGIN
	BEGIN TRY
		BEGIN TRAN --Begin Transaction
			IF @CONDITION ='GETOPERATIONCODE'
				BEGIN
					--SELECT OperationCode,OperationName,Barcode,CASE Status WHEN 'PS' THEN 'PASS' ELSE 'FAIL' end [Status],
					--FailCount,PartNo FROM (
					--SELECT Distinct L.OperationCode,Opt.OperationName,ISNULL(Assy.Barcode,'')Barcode,
					--CASE Assy.Status WHEN 'PS' THEN 'PASS' ELSE 'FAIL' end [Status],ISNULL(Assy.FailCount,0)FailCount,
					--ISNULL(Assy.PartNo,'')PartNo,L.OperationSeqNo    
					--FROM RoutingConfigLineWise L 
