					--LEFT OUTER JOIN Assy_LineAssyStatus Assy on L.OperationCode=Assy.OperationCode and L.LineCode=Assy.LineCode 
					--WHERE P.Traceability =1 and P.OperationRequired =1 and L.LineCode =@LINECODE and L.Traceability =1 and L.OperationRequired =1
					--) tb 
					--ORDER BY  OperationSeqNo ASC

                    SELECT Distinct L.OperationCode,Opt.OperationName,
					ISNULL(Assy.PartNo,'') PartNumber,L.OperationSeqNo    
					FROM RoutingConfigLineWise L 
					INNER JOIN RoutingConfigPartWise P  on L.OperationCode =l.OperationCode and l.ProfitCenterCode =p.ProfitCenterCode  and p.MachineCode =l.MachineCode inner join OperationMst Opt on L.OperationCode=Opt.OperationCode 
					LEFT OUTER JOIN Assy_LineAssyStatus_Running  Assy on L.OperationCode=Assy.OperationCode and L.LineCode=Assy.LineCode 
					WHERE P.Traceability =1 and P.OperationRequired =1 and L.LineCode =@LINECODE and L.Traceability =1 and L.OperationRequired =1
					and Assy.PartNo=(select Assy_PartNo from Assy_RunningPart where LineCode=@LINECODE)

					SET @RETURNVALUE='DATA SELECTED'
					SET @RETURNINT=1
				END

			IF @CONDITION='GETOPERRATIONCODEDATA'
				BEGIN
					DECLARE @AvgCycleTime NUMERIC(18,2)=0
					DECLARE @ShiftProduction INT=0
					DECLARE @TotalStoppageTime NUMERIC(18,2)=0

					--Part Running
					SELECT Isnull(Barcode,'')Barcode 
					FROM Assy_LineAssyStatus_Running
					WHERE LineCode=@LINECODE AND Datecode=@DATECODE AND Status='PS' AND OperationCode=@OPERATIONCODE

					--Shift Production
					SET @ShiftProduction=(SELECT Count(*) AS Shift_Production
					FROM Assy_LineAssyStatus 
					WHERE LineCode=@LINECODE AND Datecode=@DATECODE AND Status='PS' AND OperationCode=@OPERATIONCODE)

					SELECT @ShiftProduction [Shift Production]

					--Rejected Parts
					SELECT Count(*) AS Rejected_Parts
					FROM Assy_LineAssyStatus 
					WHERE LineCode=@LINECODE AND Datecode=@DATECODE AND Status='FL' AND OperationCode=@OPERATIONCODE

					--Average Cycle Time
					SET @TotalStoppageTime=(SELECT ISNULL(SUM(ReportedMins),0) ReportedMins
					FROM Assy_BreakDownReporting 
					WHERE LineCode=@LINECODE AND Datecode=@DATECODE AND OperationCode=@OPERATIONCODE)

					IF (@ShiftProduction=0)
						SET @AvgCycleTime=0
					ELSE
						SET @AvgCycleTime=(@TotalStoppageTime/@ShiftProduction)

						select @AvgCycleTime [Avg Cycle Time]
				   			
					SET @RETURNVALUE='DATA SELECTED'
					SET @RETURNINT=1
				END

			IF @CONDITION='GETDATAFORGRAPHICALREPRESENTATION'
			BEGIN
				--Rejection Informaion
				SELECT IdleReason,Count(IdleReason)[Rejection Count] 
				FROM Assy_BreakDownReporting 
				WHERE LineCode=@LINECODE and Datecode=@DATECODE and OperationCode=@OPERATIONCODE
				GROUP BY IdleReason

				--Stoppage Time Information
				SELECT IdleReason,Sum(ReportedMins-IdleMins) [Stoppage Time] 
				FROM Assy_BreakDownReporting 
				WHERE LineCode=@LINECODE and Datecode=@DATECODE and OperationCode=@OPERATIONCODE
				GROUP BY IdleReason

				SET @RETURNVALUE='DATA SELECTED'
				SET @RETURNINT=1
		  END

			IF @CONDITION='GetTotalStoppageAndRejectionData'
			BEGIN

			    --Rejection Information
				 SELECT IdleReason,Count(IdleReason)[Remarks Count] 
				 FROM Assy_BreakDownReporting 
                 WHERE LineCode=@LINECODE and Datecode=@DATECODE and OperationCode=@OPERATIONCODE
                 GROUP BY IdleReason

				 --Total Stoppage Time
				 SELECT IdleReason  ,Sum(ReportedMins-IdleMins) [Stoppage Time] 
				 FROM Assy_BreakDownReporting 
				 WHERE LineCode=@LINECODE and Datecode=@DATECODE and OperationCode=@OPERATIONCODE
				 GROUP BY IdleReason

			END
		COMMIT TRAN	--Commit Transaction
	END TRY

	BEGIN CATCH
				--CATCH BLOCK BEGINS
				SET @RETURNVALUE =	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
				CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
				CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
				CAST(ERROR_MESSAGE() AS VARCHAR(1500))
				SET @RETURNINT = 2
				ROLLBACK TRAN	--ROLLBACK TRANSACTION
				--CATCH BLOCK ENDS 
	END CATCH
END







