/****** Object:  StoredProcedure [dbo].[ASSY_PROC_HANDLE_FAIL_STATUS]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*---------------------------------------------------------------------------
'PROCEDURE NAME		: ASSY_PROC_HANDLE_FAIL_STATUS
'FUNCTION			: Reset Countinues and Hourly Fail Status
'CREATED BY			: Sachin Kumar
'CREATED ON			: 01-09-2018
'TEST SCRIPT    	: 
'REVISION HISTORY   : 
'---------------------------------------------------------------------------*/
CREATE PROCEDURE [dbo].[ASSY_PROC_HANDLE_FAIL_STATUS]
(
	@P_CONDITION VARCHAR(60),
	@P_PROFITCENTERCODE VARCHAR(20)=NULL,
	@P_LINECODE VARCHAR(20)=NULL,
	@P_OPERATIONCODE VARCHAR(20)=NULL,
	@P_MACHINECODE VARCHAR(20)=NULL,
	@P_DATECODE VARCHAR(4)=NULL,
	@P_PARTNUMBER VARCHAR(20)=NULL,
	@P_BARCODE VARCHAR(60)=NULL,
	@P_REASON  VARCHAR(2000)=NULL,
	@RETURNVALUE VARCHAR (2000) = NULL OUT,
	@RETURNINT INT=NULL OUT
)
AS 
BEGIN

	IF (@P_CONDITION='CONTINUES_FAIL_RESET')
	BEGIN
		
		insert into Assy_Continues_Fail_Count_log(ProfitCenterCode,LineCode,MachineCode,OperationCode,FailCount,Reason,
		Timestamp,LogTimestamp
		) 
		select ProfitCenterCode,LineCode,MachineCode,OperationCode,FailCount,ISNULL(@P_REASON,''),Timestamp,getdate()
		from Assy_Continues_Fail_Count(nolock) where ProfitCenterCode=@P_PROFITCENTERCODE and LineCode=@P_LINECODE
		and  OperationCode=@P_OPERATIONCODE

		delete from Assy_Continues_Fail_Count where ProfitCenterCode=@P_PROFITCENTERCODE and LineCode=@P_LINECODE
		and  OperationCode=@P_OPERATIONCODE
	END

	IF (@P_CONDITION='HOURLY_FAIL_RESET')
	BEGIN
			
			insert into Assy_Hourly_Fail_Count_Log(ProfitCenterCode,LineCode,MachineCode,OperationCode,FromTimestamp,ToTimestamp,FailCount,Reason,
			Timestamp,LogTimestamp
			) 
			select ProfitCenterCode,LineCode,MachineCode,OperationCode,FromTimestamp,ToTimestamp,FailCount,ISNULL(@P_REASON,''),Timestamp,getdate()
			from Assy_Hourly_Fail_Count(nolock) where ProfitCenterCode=@P_PROFITCENTERCODE and LineCode=@P_LINECODE
			and  OperationCode=@P_OPERATIONCODE

			delete from Assy_Hourly_Fail_Count where ProfitCenterCode=@P_PROFITCENTERCODE and LineCode=@P_LINECODE
			and  OperationCode=@P_OPERATIONCODE


	END

END
