/****** Object:  StoredProcedure [dbo].[ASSY_PROC_ID_GENERATION_SIGNAL]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/***************************************************************************************                    
PROCEDURE         :     ASSY_PROC_ID_GENERATION_SIGNAL
AUTHOR            :     SACHIN KUMAR
DATE WRITTEN      :     May 31, 2017
PURPOSE           :     To Generate Barcode

TEST SCRIPT  
declare @sts_cd int = 0
exec ASSY_PROC_ID_GENERATION_SIGNAL 'OC50','','',1,0,0,@P_STS_CD=@sts_cd out
select @sts_cd

STS_CD

11 - Wait For Barcode Generation
12 - Barcode Generated By TS System , WIP

****************************************************************************************/
CREATE procedure [dbo].[ASSY_PROC_ID_GENERATION_SIGNAL]
(
  @P_OperationCode varchar(10) = '',
  @P_PartNo  varchar(60) = '',
  @P_DateCode varchar(4) ='',
  @P_Clamp_ON  bit = 1,  -- Clamp Singal Must be 1 to generate ID
  @P_FlushCycle bit = 0, -- if Flush Cycle ON need to generate new ID
  @P_PokaYoke bit = 0,    -- if POKA YOKE Mode is ON no need to generate New ID
  @P_STS_CD int = 0 out 
)
AS
BEGIN

    IF(ISNULL(@P_OPERATIONCODE,'') <> '' and @P_Clamp_ON = 1 and  @P_FlushCycle = 0 and @P_PokaYoke = 0)
	BEGIN
			IF NOT EXISTS(SELECT TOP 1 1 FROM ASSY_ID_GENERATION(NOLOCK))
			BEGIN
			        print 'Insert Call'
					INSERT INTO ASSY_ID_GENERATION(OPERATIONCODE,PartNo,ISCLAMPON,TD_ACK_TIME,STS_CD)
											VALUES(@P_OPERATIONCODE,@P_PartNo,1,GETDATE(),0)
					print 'Insert Done'
					SELECT 0 AS 'STS_CD'
			END
			ELSE
			BEGIN
				 SELECT @P_STS_CD=STS_CD FROM ASSY_ID_GENERATION(NOLOCK)
				 SELECT  @P_STS_CD AS 'STS_CD'
		    END
	END

END




