CREATE PROC [dbo].[Assy_proc_IncorrectLabel_Manage]
(    
@CONDITION varchar(50),   
@LineCode varchar(10) ='',
@OperationCode VARCHAR(20), 
@BARCODE VARCHAR(30)='',
@stationCode varchar(5)  ='',
@HMIMEssage varchar(500) =''
)    
AS    
BEGIN    
	SET NOCOUNT ON
	if @CONDITION='UPDATE'
	begin
		IF  EXISTS(SELECT 1 FROM Assy_incorrectLabel(nolock) WHERE  OperationCode=@OperationCode and linecode =@linecode)					
			BEGIN

							if exists( select 1 from Assy_Scan_OK(nolock) where LineCode =@linecode and OperationCode=@OperationCode and isnull(IsCycleStarted,0)=1
							)
							begin

									return
							end
				
						 UPDATE Assy_incorrectLabel SET isIncorrect =1,barcode=@BARCODE ,HMIMessageCode=@HMIMEssage
						 WHERE OperationCode=@OperationCode and linecode =@linecode					
							--Reset duplicate label
						update Assy_DuplicateLabel set isDuplicate=0 where LineCode=@LineCode and OperationCode=@OperationCode
					
						--reset scan ok
						Update Assy_Scan_OK set isScan=0 where LineCode=@LineCode and OperationCode=@OperationCode 

			
			end
		ELSE
			BEGIN
				
					 insert into Assy_incorrectLabel(LineCode,OperationCode,Barcode,HMIMessageCode,isIncorrect)
						select @LineCode,@OperationCode,@BARCODE,@HMIMEssage,1 
				
						--Reset duplicate label
						update Assy_DuplicateLabel set isDuplicate=0 where LineCode=@LineCode and OperationCode=@OperationCode
					
						--reset scan ok
						Update Assy_Scan_OK set isScan=0 where LineCode=@LineCode and OperationCode=@OperationCode 		
			
			END
	END
end






