/****** Object:  StoredProcedure [dbo].[assy_Proc_Insert_Inv]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

 --exec assy_Proc_Insert_Inv @ProfitCenterCode = '0021', @UserId = 'admin', @Qty =  10, @PartNo= '29066616', @OUTPUT_BIN_ID= 'PKBD011000102523'

create PROC [dbo].[assy_Proc_Insert_Inv]
  ( 
      @ProfitCenterCode	varchar(10), 
      @UserId		varchar(10),
	  @Qty          int,		
      @PartNo		varchar(10),
      @OUTPUT_BIN_ID	varchar(20),
	  @ReturnValue VARCHAR (2000)=NULL OUT,
	  @ReturnInt INT=NULL OUT
    ) 
AS
BEGIN
  
  BEGIN TRY
		declare @WH_PREFIX varchar(20);    
	    declare @NEXT_SERIAL_ID varchar(20);          
        declare @SERIAL_NO varchar(20);      
        declare @BOX_PREFIX varchar(20);    
		declare @INT_LOT NVARCHAR(20)  
		Declare @Item_No varchar(10) = null;    
		Declare @Zone_Cd varchar(10) = null; 
        DECLARE @LOC_ID VARCHAR(20) = NULL;

		

		  SELECT @WH_PREFIX = DBO.FN_GET_WMS_KEY_VAL(@ProfitCenterCode,'WAREHOUSE PREFIX')          
		SELECT @BOX_PREFIX=DBO.FN_GET_WMS_KEY_VAL(@ProfitCenterCode,'DEFAULT BOX_PREFIX')     
		EXEC PROC_GETNEXTID 'BOX_SERIAL_NO' , 'admin' , @ProfitCenterCode,   @NEXT_SERIAL_ID OUT          
		SET @SERIAL_NO = @BOX_PREFIX + @WH_PREFIX  + RIGHT('0000000' + CONVERT(NVARCHAR,@NEXT_SERIAL_ID),8)     
		-- print 'serial_no'
		-- print @SERIAL_NO
		EXEC PROC_GETNEXTID 'LOT_NO','admin', @ProfitCenterCode,0,@INT_LOT OUT   
	--	print 'lot no'
		--print @INT_LOT
	   set @Item_No = (SELECT Item_No FROM Product_Master WHERE SEWS_PART_NO = @PartNo AND Warehouse_Cd = @ProfitCenterCode)     
	 --  print 'item_no'
	  -- print @Item_No
  
     set @LOC_ID = (select dbo.[assy_fn_get_parameter_value]('AssLine', 'Viewing', 'LOCATION_CODE', @ProfitCenterCode))
      --set @LOC_ID = (select PARAMETER_VALUE from PARAMETER_MST where PARAMETER_C = 'AssLine' and PARAMETER_C1 = 'Viewing' AND PARAMETER_C2 = 'LOCATION_CODE')
	 -- print 'locid'
	 -- print @LOC_ID
      set @Zone_Cd = ( select Zone_Cd from Location_Master where LOC_ID = @LOC_ID and WH_CODE = @ProfitCenterCode)

	  INSERT INTO inv_serial (SERIAL_NO, ITEM_NO, LOC_ID, WH_CODE, ZONE_CD, SERIAL_QTY, SEQ_NO, STS_CD,
	  ENT_STAMP, ENT_BY, LAST_UPD_STAMP, LAST_UPD_BY, INT_LOT_NO,  
		SEWS_PART_NO, PALLET_PHY_ID )
	 Values  
	(@SERIAL_NO, @Item_No, @LOC_ID, @ProfitCenterCode, @Zone_Cd, @Qty, 
	0, 0, GETDATE(), @UserId, GETDATE(), @UserId, @INT_LOT, @PartNo, @OUTPUT_BIN_ID)
	Set @ReturnValue = 'insert success'

	
  END TRY

  BEGIN CATCH
			
			SET @ReturnValue =	CAST(ERROR_NUMBER() as varchar(5)) + '|' + 
			CAST(ERROR_SEVERITY()as varchar(5)) + '|' + 
			CAST(ERROR_STATE() as varchar(5)) + '|' + 
			CAST(ERROR_PROCEDURE() as varchar(200)) + '|' + 
			CAST(ERROR_LINE() as varchar(5)) + '|' + 
			CAST(ERROR_MESSAGE() as varchar(1500))			
			--ROLLBACK TRAN			
			SET @ReturnInt = 2
			raiserror(@ReturnValue,16,1)
			END CATCH
END


