/****** Object:  StoredProcedure [dbo].[Assy_Proc_LineMst_SuperUser_Control]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[Assy_Proc_LineMst_SuperUser_Control]
(
@PROFITCENTERCODE VARCHAR(20)=NULL,
@LINECODE VARCHAR(20)=NULL,
@IsLocalDB bit=0
)
as
begin
--Author :Ravishankar Mishra
--Created Date: 24/03/16
--Modified By: Rashid Siddiqui
--Modified Date: 18-August-2016
--Description: Add IsMatFeedRequired column

--Modified By: Ravishankar Mishra
--Modified Date: 13-Nov-2016
--Description: Added Allow2Parts column

--MODIFIED BY:<RAVISHANKAR MISHRA>
--MODIFIED ON:<07-04-17> 
--DESCRIPTION:<In Line mst, AutoTallyChartEnable column has been added >
--exec Assy_Proc_LineMst_SuperUser_Control @PROFITCENTERCODE='0021',@LINECODE='M01',@IsLocalDB=1
		set nocount on
		DECLARE @LineTypeName VARCHAR(10) 
		 DECLARE @ExecQuery AS NVARCHAR(MAX),@LinkServerName VARCHAR(100),@Id BIGINT   
		if @IsLocalDB=1
		begin

					SELECT @LinkServerName = LinkServerName + '.' + DataBaseName FROM Assy_LinkServer_Dtl  WITH (NOLOCK) 
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode 
			        --Sync line master from main server to local
					 SET @EXECQUERY=@LINKSERVERNAME+'.DBO.LINEMST WITH (NOLOCK) WHERE LINECODE='''+@LINECODE+''' AND PROFITCENTERCODE='''+@PROFITCENTERCODE+''''
					SET @EXECQUERY = N'SELECT PROFITCENTERCODE, COSTCENTERCODE, LINECODE, LINENAME, LINEPREFIX, ISACTIVE, ENT_STAMP, LAST_UPD_STAMP, ENT_BY, LAST_UPD_BY
					, WORKCENTERCODE, WIPCHECK, WIPFIFOCHECK, VALIDATE_DATECODE, LINETYPECODE, TALLYCHARTAPPLICABLE, ISPRODCONFREQUIRED,ISPOKAYOKEMANDATORY
					,IsManPowerRequired,isTMCValidationOff,IsMatFeedRequired,Allow2Parts,AutoTallyChartEnable FROM ' + @EXECQUERY
					--SELECT  @EXECQUERY 
					IF OBJECT_ID('TEMPDB..#TEMP_LINEMST') IS NOT NULL 
					BEGIN 
					  DROP TABLE #TEMP_LINEMST 
					END 
					SELECT PROFITCENTERCODE, 
						COSTCENTERCODE, 
						LINECODE, 
						LINENAME, 
						LINEPREFIX, 
						ISACTIVE, 
						ENT_STAMP, 
						LAST_UPD_STAMP, 
						ENT_BY, 
						LAST_UPD_BY, 
						WORKCENTERCODE, 
						WIPCHECK, 
						WIPFIFOCHECK, 
						VALIDATE_DATECODE, 
						LINETYPECODE, 
						TALLYCHARTAPPLICABLE, 
						ISPRODCONFREQUIRED ,
						ISPOKAYOKEMANDATORY,
						IsManPowerRequired,
						isTMCValidationOff,
						IsMatFeedRequired,
						Allow2Parts,
						AutoTallyChartEnable
					INTO #TEMP_LINEMST FROM LINEMST WITH (NOLOCK) WHERE 1=2 
					
					INSERT INTO #TEMP_LINEMST 
					EXECUTE (@EXECQUERY) 
					
					IF EXISTS 
					( 
					  SELECT TOP 1 1 FROM  #TEMP_LINEMST WITH (NOLOCK) 
					) 
					BEGIN 
						DELETE FROM LINEMST 
						INSERT INTO LINEMST 
						( 
						PROFITCENTERCODE, 
						COSTCENTERCODE, 
						LINECODE, 
						LINENAME, 
						LINEPREFIX, 
						ISACTIVE, 
						ENT_STAMP, 
						LAST_UPD_STAMP, 
						ENT_BY, 
						LAST_UPD_BY, 
						WORKCENTERCODE, 
						WIPCHECK, 
						WIPFIFOCHECK, 
						VALIDATE_DATECODE, 
						LINETYPECODE, 
						TALLYCHARTAPPLICABLE, 
						ISPRODCONFREQUIRED,
						ISPOKAYOKEMANDATORY ,
						IsManPowerRequired,
						isTMCValidationOff,
						IsMatFeedRequired,
						Allow2Parts,
						AutoTallyChartEnable
						) 
						SELECT 
						PROFITCENTERCODE, 
						COSTCENTERCODE, 
						LINECODE, 
						LINENAME, 
						LINEPREFIX, 
						ISACTIVE, 
						ENT_STAMP, 
						LAST_UPD_STAMP, 
						ENT_BY, 
						LAST_UPD_BY, 
						WORKCENTERCODE, 
						WIPCHECK, 
						WIPFIFOCHECK, 
						VALIDATE_DATECODE, 
						LINETYPECODE, 
						TALLYCHARTAPPLICABLE, 
						ISPRODCONFREQUIRED,
						ISPOKAYOKEMANDATORY ,
						IsManPowerRequired,
						isTMCValidationOff,
						IsMatFeedRequired,
						Allow2Parts,
						AutoTallyChartEnable
						FROM #TEMP_LINEMST 
					end
				return
		END
		ELSE IF @ISLOCALDB=0
		BEGIN
					if exists
					(
						select 1 from Assy_LineMst_SuperUser_Control with(nolock) where ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode 
						and isnull(isActive,0)=1 and isnull(isPokaYokeMandatory,0)=1
					)
					begin
							update linemst set isPokaYokeMandatory=1 where   ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode and isnull(isPokaYokeMandatory,0)=0
					end
					else if exists
					(
						select 1 from Assy_LineMst_SuperUser_Control with(nolock) where ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode 
						and isnull(isActive,0)=1 and isnull(isPokaYokeMandatory,0)=0
					)
					begin
							update linemst set isPokaYokeMandatory=0 where   ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode and isnull(isPokaYokeMandatory,0)=1
					end

		END
end

