/****** Object:  StoredProcedure [dbo].[ASSY_PROC_LINES_RUNNING_STATUS]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[ASSY_PROC_LINES_RUNNING_STATUS]
(
@PROFITCENTERCODE varchar(10)=NULL,
@BINID varchar(60)=NULL,
@PRODUCTIONQTY numeric(18,2)=0,
@BINQTY numeric(18,2)=0,
@LOADQTY numeric(18,2)=0,
@DATECODE char(4)=NULL,
@LINECODE varchar(10)=NULL,
@PARTNO varchar(60)=NULL,
@BINPARTNO varchar(60)=null,
@PRODORDERNO varchar(40)=NULL,
@USER_ID varchar(20)=NULL,
@CONDITION varchar(50),
@RETURNVALUE VARCHAR (2000)=NULL OUT,
@RETURNINT INT=NULL OUT
)
AS 
BEGIN
	BEGIN TRY
		BEGIN TRAN --Begin Transaction
			IF @CONDITION='GetLineDetails'
			BEGIN
				SELECT DISTINCT L.LineCode,L.LineName,P.PartNumber,PM.PRODUCT_NM AS PartDescription,P.ProdOrderNo,ISNUll(P.ProductionQty,0)ProductionQty,ProdOrderPriority
				FROM LINEMST L
				INNER JOIN ASSY_PRODUCTIONORDER_PARAMETERSETTING P ON P.ProfitCenterCode=L.ProfitCenterCode AND P.LineCode=L.LineCode
				LEFT OUTER JOIN PRODUCT_MASTER PM On PM.SEWS_PART_NO=P.PartNumber
				WHERE L.ProfitCenterCode=@PROFITCENTERCODE AND P.Datecode=@DATECODE AND P.ProdOrderPriority IN ('1','2')
				ORDER BY ProdOrderPriority

				SET @ReturnValue='DATA SELECTED'
		        SET @ReturnInt=1
			END

			IF @CONDITION='GetOperationDetails'
			BEGIN
				SELECT OperationCode,ISNULL(CycleTime,0)CycleTime 
		        FROM RoutingConfigLineWise
		        WHERE LineCode=@LINECODE AND ProfitCenterCode=@PROFITCENTERCODE

				SET @ReturnValue='DATA SELECTED'
		        SET @ReturnInt=1
			END

			IF @CONDITION='GetBinDetails'
			BEGIN
				SELECT PartNo,ISNULL(ReceivedQty,0)ReceivedQty,ISNULL(PM.product_nm,'') AS Part_Description
				FROM WS_RECEIVING WR
				LEFT OUTER JOIN PRODUCT_MASTER PM ON PM.SEWS_PART_NO=WR.PartNo
				WHERE BinID=@BINID AND ProfitCenterCode=@PROFITCENTERCODE

				SET @ReturnValue='DATA SELECTED'
		        SET @ReturnInt=1
			END

			IF @CONDITION='VerifyBinDetails'
			BEGIN
				DECLARE @ValidScanBinID varchar(20)
				SET @ValidScanBinID=''

				SET @ValidScanBinID=(SELECT Count(*) FROM WS_RECEIVING WHERE BinID=@BINID AND ProfitCenterCode=@PROFITCENTERCODE)

				if ((@ValidScanBinID=0) or (@ValidScanBinID IS NULL))
					BEGIN
						SET @ReturnValue='NOT A VALID BIN'
		                SET @ReturnInt=2
					END
			END

			IF @CONDITION='VerifyLoadQty'
			BEGIN
				IF ((@LOADQTY>@PRODUCTIONQTY) OR (@LOADQTY>@BINQTY))
					BEGIN
						SET @ReturnValue='LOAD QTY SHOULD BE LESS THAN PRODUCTION QTY AND BIN QTY!!!'
					    SET @ReturnInt=2
					END
     		END

			IF @CONDITION='SearchData'
			BEGIN
				SELECT Distinct L.LineCode,L.LineName,P.PartNumber,PM.PRODUCT_NM AS PartDescription,P.ProdOrderNo,ISNUll(P.ProductionQty,0)ProductionQty,ProdOrderPriority
				FROM LINEMST L
				INNER JOIN ASSY_PRODUCTIONORDER_PARAMETERSETTING P ON P.ProfitCenterCode=L.ProfitCenterCode AND P.LineCode=L.LineCode
				LEFT OUTER JOIN PRODUCT_MASTER PM On PM.SEWS_PART_NO=P.PartNumber
				WHERE L.ProfitCenterCode=@PROFITCENTERCODE AND P.Datecode=@DATECODE AND P.ProdOrderPriority IN ('1','2')
				AND L.LineCode LIKE '%'+ @LINECODE +'%' AND P.PartNumber LIKE '%' + @PARTNO + '%' AND P.ProdOrderNo LIKE '%' + @PRODORDERNO + '%'
				ORDER BY ProdOrderPriority

				SET @ReturnValue='DATA SELECTED'
		        SET @ReturnInt=1
			END

			IF @CONDITION='SaveData'
			BEGIN
				IF NOT EXISTS(SELECT * FROM WS_LOADING WHERE BinID=@BINID AND BinPartNo=@BINPARTNO)
						BEGIN
							INSERT INTO WS_LOADING(ProfitCenterCode,CostCenterCode,WorkCenterCode,LineCode,ProductionOrderNo,
							PartNo,BinID,BinPartNo,BinQty,LoadQty,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
							SELECT @PROFITCENTERCODE,'','',@LINECODE,@PRODORDERNO,@PARTNO,@BINID,@BINPARTNO,@BINQTY,
							@LOADQTY,@USER_ID,GETDATE(),@USER_ID,GETDATE()
							
							SET @ReturnValue= 'DATA SAVED!!!'
		                    SET @ReturnInt=2
						END
				   ELSE
						BEGIN
							UPDATE WS_LOADING
							SET LoadQty=@LOADQTY
							WHERE  BinID=@BINID AND BinPartNo=@BINPARTNO

						    SET @ReturnValue= 'DATA UPDATED!!!'
		      SET @ReturnInt=1
						END
			END
		COMMIT TRAN	--Commit Transaction
   END TRY

	BEGIN CATCH
		--CATCH BLOCK BEGINS
		SET @RETURNVALUE =	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
		CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
		CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_MESSAGE() AS VARCHAR(1500))
		SET @RETURNINT = 2
		ROLLBACK TRAN	--ROLLBACK TRANSACTION
		--CATCH BLOCK ENDS 
	END CATCH

END




GO
/****** Object:  StoredProcedure [dbo].[ASSY_PROC_MANUAL_DATECODE]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[ASSY_PROC_MANUAL_DATECODE]  @PROFITCENTERCODE VARCHAR(10)=NULL,
											  @LINECODE  VARCHAR(10)=NULL,
                                              @OPERATION        VARCHAR(50),
                                              @DATECODE         CHAR(4)=NULL,
                                              @USERNAME         VARCHAR(50)=NULL,
                                              @MANUAL_DATECODE  VARCHAR(4)=NULL,
                                              @LOGINID          VARCHAR(20)=NULL,
											  @ISAUTOMATIC		BIT =0,
                                              @RETURNVALUE      VARCHAR (2000)=NULL OUT,
                                              @RETURNINT        INT=NULL OUT
AS
  BEGIN
      -- NOTHING = 0            
      -- SUCCESS = 1            
      -- ERROR = 2            
      -- ALREADYEXISTS = 3            
      -- NOTEXISTS = 4           
      BEGIN TRY
          SET NOCOUNT ON

          IF @OPERATION = 'UPDATEMANUALDATECODE'
            BEGIN
                IF EXISTS(SELECT DATECODE
                          FROM   MANUAL_DATECODE_ENTRY(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE)
                  UPDATE MANUAL_DATECODE_ENTRY
							SET DATECODE = @DATECODE,
								USERNAME = @USERNAME,
								TIMESTAMP = GETDATE()
							WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE
                ELSE
                  INSERT INTO MANUAL_DATECODE_ENTRY
                              (DATECODE,
                               USERNAME,
                               TIMESTAMP,
							   PROFITCENTERCODE,
							   LINECODE)
                  VALUES     (@DATECODE,
                              @USERNAME,
                              GETDATE(),
							  @PROFITCENTERCODE,
							  @LINECODE)
                
                SET @RETURNVALUE= 'OK'
                SET @RETURNINT=1                
            END

          IF @OPERATION = 'FILL_SHIFT'
          BEGIN
				  SELECT SHIFTCODE, DAY1,CODE
				  FROM     
					 (    
							SELECT SHIFTCODE    
							 ,[MONDAY]    
							 ,[TUESDAY]    
							 ,[WEDNESDAY]    
							 ,[THURSDAY]    
							 ,[FRIDAY]    
							 ,[SATURDAY]    
							 ,[SUNDAY]  				
							FROM DATECODEMST WHERE PROFITCENTERCODE=@PROFITCENTERCODE 
			         
					 ) P    
				  UNPIVOT    
					 (
							 CODE FOR DAY1 IN     
							 (MONDAY    
							 ,[TUESDAY]    
							 ,[WEDNESDAY]    
							 ,[THURSDAY]    
							 ,[FRIDAY]    
							 ,[SATURDAY]    
							 ,[SUNDAY]    
					 )			            
				  )AS UNPVT    

					SET @RETURNVALUE= 'OK'
					SET @RETURNINT=1
          END

          IF @OPERATION = 'FILL_WEEK'
            BEGIN
                SELECT CODE
                FROM   WEEKMST(NOLOCK)
                WHERE  CODE <= 52
                ORDER  BY CODE

                SET @RETURNVALUE= 'OK'
                SET @RETURNINT=1
            END

          IF @OPERATION = 'FILL_YEAR'
            BEGIN
                SELECT CODE
                FROM   YEARMST(NOLOCK)
                WHERE  CODE <> ''
                ORDER  BY YEAR

                SET @RETURNVALUE= 'OK'
                SET @RETURNINT=1
            END

          IF @OPERATION = 'VALIDATE_DATECODE'
            BEGIN
                --GET CURRENT DATECODE
                DECLARE @CURRENT_DATECODE VARCHAR(4)
                DECLARE @CURRENT_DATE VARCHAR(12)
                DECLARE @MANUAL_DATE VARCHAR(12)

                EXEC ASSY_PROC_GET_DATECODE
                  @PROFITCENTERCODE,
				  @LINECODE,
                  @CURRENT_DATECODE OUTPUT

                CREATE TABLE #TEMPDATE
                  (
                     _DATE     VARCHAR(12),
                     _TIMEFROM VARCHAR(12),
                     _TIMETO   VARCHAR(12)
                  )

                INSERT INTO #TEMPDATE
  EXEC ASSY_PROC_GETDATE_FROMDATECODE
                  @CURRENT_DATECODE

                SELECT @CURRENT_DATE = _DATE
                FROM   #TEMPDATE

                DELETE FROM #TEMPDATE

                INSERT INTO #TEMPDATE
                EXEC ASSY_PROC_GETDATE_FROMDATECODE
                  @MANUAL_DATECODE

                SELECT @MANUAL_DATE = _DATE
                FROM   #TEMPDATE

                IF( CAST(@MANUAL_DATE AS DATE) <= CAST(@CURRENT_DATE AS DATE) )
                  BEGIN
                      SET @RETURNVALUE= 'OK'
                      SET @RETURNINT=1
                  END
                ELSE
                  BEGIN
                      SET @RETURNVALUE='DATECODE CANNOT BE GREATER THAN CURRENT DATECODE.'
                      SET @RETURNINT=0
                  END
            END

		IF @OPERATION='UPDATEDATAFORAUTOMATICFLAG'
		BEGIN
			IF EXISTS(SELECT ISAUTOMATIC FROM DATECODE_MODE(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE)
					UPDATE DATECODE_MODE SET ISAUTOMATIC=@ISAUTOMATIC,TIMESTAMP=GETDATE() 
							WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE
			ELSE 
					INSERT INTO DATECODE_MODE(ISAUTOMATIC,TIMESTAMP,PROFITCENTERCODE,LINECODE) VALUES(@ISAUTOMATIC,GETDATE(),@PROFITCENTERCODE,@LINECODE)

			SET @RETURNVALUE='MODE UPDATED'
			SET @RETURNINT=1
		END         
			
		IF @OPERATION='SELECTDATECODEMODE'
		BEGIN
			SELECT ISAUTOMATIC FROM DATECODE_MODE(NOLOCK) 
			WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE
		
			SET @RETURNVALUE='MODE SELECTED'
			SET @RETURNINT=1
		END

		IF @OPERATION='SELECTMANUALDATECODE'
		BEGIN
			     SELECT DateCode FROM MANUAL_DATECODE_ENTRY(NOLOCK) 
				 WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE
				 
				 SET @RETURNVALUE='DATE CODE MANUAL SELECTED'
		         SET @RETURNINT=1
			END
      END TRY

      BEGIN CATCH
          --CATCH BLOCK BEGINS
          SET @RETURNVALUE = CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|'
                             + CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|'
                             + CAST(ERROR_STATE() AS VARCHAR(5)) + '|'
                             + CAST(ERROR_PROCEDURE() AS VARCHAR(200))
                             + '|' + CAST(ERROR_LINE() AS VARCHAR(5)) + '|'
                             + CAST(ERROR_MESSAGE() AS VARCHAR(1500))
          SET @RETURNINT = 2
      --CATCH BLOCK ENDS 
      END CATCH
  END 



GO
