/****** Object:  StoredProcedure [dbo].[Assy_Proc_Manual_Printed_Barcode]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC  [dbo].[Assy_Proc_Manual_Printed_Barcode]
(
    @CONDITION VARCHAR(50),
	@PROFITCENTERCODE VARCHAR(20)='0021' ,
	@LINECODE VARCHAR(5)=NULL,	
	@DATECODE CHAR(4)=NULL,
	@BARCODE [VARCHAR](30)=NULL ,
	@USERID VARCHAR(50)=NULL,
	@RETURNVALUE VARCHAR (2000)=NULL OUT,
	@RETURNINT INT=NULL OUT,
	@PARTNO [VARCHAR](30)=NULL,
	@NOOFPRINTEDLBL INT=1,
	@FROMSERIALNO VARCHAR(15)=NULL ,
	@TOSERIALNO VARCHAR(15)=NULL ,
	@REASON VARCHAR(500)=NULL ,
	@SERIALNO VARCHAR(15)=NULL,
	@CUSTPARTNO VARCHAR(40)=NULL,
	@CUSTSERIALNO VARCHAR(100)=NULL,
	@SHIFT_CODE VARCHAR(2)=''
)
AS
BEGIN
--<AUTHOR:RAVISHANKAR MISHRA>
--<CREATED DATE:20/04/2015>

-- TO REMBEMBER
-- NOTHING = 0
-- SUCCESS = 1
-- ERROR = 2
-- ALREADYEXISTS = 3
-- NOTEXISTS = 4		
		--EXEC Assy_Proc_Manual_Printed_Barcode @CONDITION='GET_PARTS_FOR_PRINTING' ,@LINECODE='M07',@PROFITCENTERCODE ='0021'

         --EXEC Assy_Proc_Manual_Printed_Barcode @CONDITION='CHECK_SETPARAMETER',@LINECODE ='M07'
	   --EXEC Assy_Proc_Barcode_Printed_Counter @CONDITION='UPDATE',@LINECODE ='' ,@PROFITCENTERCODE =@PROFITCENTERCODE
		--EXEC Assy_Proc_Manual_Printed_Barcode  @CONDITION='SELECT_RUNNING_PART',@LINECODE='P2',@PROFITCENTERCODE='0021'
		--EXEC Assy_Proc_Manual_Printed_Barcode  @CONDITION='INSERT_BARCODE',@LINECODE='M07',@PROFITCENTERCODE ='0021'
		--,@BARCODE='2906683512MX12345677M08',@DATECODE='12MX',@USERID ='RAVI',@PARTNO='29066835',@SERIALNO='00000001' 
		--EXEC  Assy_Proc_Manual_Printed_Barcode @CONDITION='INSERT_BARCODES_DETAILS',@LINECODE='M07',@PROFITCENTERCODE ='0021'
		--,@PARTNO='PART1'
		--		,@DATECODE='12MX',
		--		@NOOFPRINTEDLBL=10 ,
		--		@FROMSERIALNO='10' ,
		--		@TOSERIALNO='20',
		--		@REASON='X', 
		--		@USERID='RAVI'

		DECLARE @SERVERNAME NVARCHAR(30)
				DECLARE @DBNAME NVARCHAR(20)
				SELECT @SERVERNAME=LINKSERVERNAME,@DBNAME=DATABASENAME FROM ASSY_LINKSERVER_DTL(NOLOCK)
				DECLARE @QUERY NVARCHAR(1000)

	  SET NOCOUNT ON
	  IF @CONDITION='INSERT_BARCODE'
	  BEGIN
			 BEGIN TRY
					   BEGIN TRAN 
			  
						 EXEC Assy_Proc_Vision_System  @PROFITCENTERCODE=@PROFITCENTERCODE,@LINECODE=@LINECODE,
													   @BARCODE=@BARCODE,@USERID =@USERID,@SERIALNO=@SERIALNO,@ISMANUAL=1,  
													   @P_DateCode=@DATECODE, @P_PartNo=@PARTNO

						 INSERT INTO ASSY_MANUAL_PRINTED_BARCODE(PROFITCENTERCODE,LINECODE,DATECODE,BARCODE,REPRINT,USERID,TIMESTAMP,PARTNO,
						 SERIALNO,CustomerPartNo,CustomerSerial)
						 SELECT @PROFITCENTERCODE,  @LINECODE,@DATECODE ,@BARCODE,0,@USERID,GETDATE(),@PARTNO,
						 @SERIALNO,@CUSTPARTNO,@CUSTSERIALNO 
						 --UPDATE ASSY_VISION_SYSTEM_LOG
						 EXEC ASSY_PROC_VISION_SYSTEM_LOG  @OPERATION ='UPDATE_SEQUENCE_NUMBER',@PARTNO=@PARTNO,@LINECODE=@LINECODE,
						 @LASTPRINTBARCODE=@BARCODE,@PROFITCENTERCODE=@PROFITCENTERCODE --PROFIT CENTER CODE added by sachin 20170330  						             
					   COMMIT TRAN
					    SET @RETURNINT=1    
			 END TRY
     
			 BEGIN CATCH
					   ROLLBACK TRAN      
					   DECLARE @ERRORMSG AS VARCHAR(500)=ERROR_MESSAGE()
					   RAISERROR(@ERRORMSG,16,1)
             
			 END CATCH
     END
	  ELSE IF @CONDITION='INSERT_BARCODES_DETAILS'
	  BEGIN
				INSERT INTO ASSY_MANUAL_PRINTED_BARCODE_DTL
				(
				PROFITCENTERCODE ,
				[LINECODE] ,
				[PARTNO] ,
				[DATECODE] ,
				[NOOFPRINTEDLBL],
				[FROMSERIALNO] ,
				[TOSERIALNO] ,
				[REASON] ,
				USERID ,
				[TIMESTAMP] 
				)
				SELECT 
				@PROFITCENTERCODE ,
				@LINECODE ,
				@PARTNO,
				@DATECODE,
				@NOOFPRINTEDLBL ,
				@FROMSERIALNO ,
				@TOSERIALNO,
				@REASON, 
				@USERID,
				GETDATE()				
				SET @RETURNINT=1
	  END
	 ELSE IF @CONDITION='SELECT_RUNNING_PART'
	 BEGIN


				DECLARE @RUNNINGPART AS TABLE
				(
				 ASSY_PARTNO VARCHAR(50),
				 DATECODE CHAR(4),
				 ASSY_MODE VARCHAR(20),
				 PARTTYPE VARCHAR(10)
				)
				INSERT INTO @RUNNINGPART(ASSY_PARTNO,DATECODE,ASSY_MODE,PARTTYPE)
				SELECT RP.ASSY_PARTNO,RP.DATECODE ,RP.ASSY_MODE,ISNULL(PARTTYPE,'') FROM ASSY_RUNNINGPART(NOLOCK) RP 
				WHERE LINECODE=@LINECODE AND ASSY_MODE IN ('Production','Rework') 
				and ProfitCenterCode=@PROFITCENTERCODE -- added by sachin 20170327
				
				IF(SELECT PARTTYPE FROM @RUNNINGPART)='STMC'
				BEGIN
							SELECT  TOP 1 ISNULL(SERVO_PARTNO,'')  AS PARTNO, RP.DATECODE,RP.ASSY_MODE,RP.PARTTYPE,CONVERT(INT, ISNULL(VS.COUNTER,0))COUNTER,
							BOOST_RATIO  AS BOOSTRATIO  FROM ASSY_RUNNINGPART(NOLOCK)RP							
							LEFT OUTER JOIN ASSY_VISION_SYSTEM_LOG(NOLOCK) VS ON RP.SERVO_PARTNO =VS.PARTNUMBER AND RP.LINECODE =VS.LINECODE 
						    AND VS.LINECODE=@LINECODE WHERE RP.LINECODE=@LINECODE AND ASSY_MODE IN ('Production','Rework')
							AND RP.ProfitCenterCode=@PROFITCENTERCODE -- added by sachin 20170327
							AND VS.ProfitCenterCode=@PROFITCENTERCODE -- added by sachin 20170327
							
				END
				ELSE  IF (SELECT PARTTYPE FROM @RUNNINGPART)='TMC'
				BEGIN
					   SELECT ASSY_PARTNO PARTNO,DATECODE,ASSY_MODE,PARTTYPE,CONVERT(INT, ISNULL(VS.COUNTER,0))COUNTER
						FROM @RUNNINGPART RP
						LEFT OUTER JOIN ASSY_VISION_SYSTEM_LOG(NOLOCK) VS ON RP.ASSY_PARTNO =VS.PARTNUMBER 
						AND VS.LINECODE=@LINECODE 
						AND VS.ProfitCenterCode=@PROFITCENTERCODE -- added by sachin 20170327
				END

				ELSE  IF (SELECT PARTTYPE FROM @RUNNINGPART)='SERVO' 
				BEGIN
						SELECT ASSY_PARTNO PARTNO,DATECODE,ASSY_MODE,PARTTYPE,CONVERT(INT, ISNULL(VS.COUNTER,0))COUNTER,
						DBO.ASSY_FN_GET_BOOSTRATIO(@PROFITCENTERCODE,(SELECT ASSY_PARTNO FROM @RUNNINGPART)) AS BOOSTRATIO  FROM @RUNNINGPART RP
						LEFT OUTER JOIN ASSY_VISION_SYSTEM_LOG(NOLOCK) VS ON RP.ASSY_PARTNO =VS.PARTNUMBER 
						AND VS.LINECODE=@LINECODE 
						AND VS.ProfitCenterCode=@PROFITCENTERCODE -- added by sachin 20170327	
				END
				ELSE  IF (SELECT PARTTYPE FROM @RUNNINGPART)='CALIPER' 
				BEGIN
						SELECT TOP 1  ASSY_PARTNO PARTNO,DATECODE,ASSY_MODE,PARTTYPE,CONVERT(INT, ISNULL(VS.COUNTER,0))COUNTER,
						DBO.ASSY_FN_GET_BOOSTRATIO(@PROFITCENTERCODE,(SELECT ASSY_PARTNO FROM @RUNNINGPART)) AS BOOSTRATIO  
						FROM @RUNNINGPART RP
						LEFT OUTER JOIN ASSY_VISION_SYSTEM_LOG(NOLOCK) VS ON RP.ASSY_PARTNO =VS.PARTNUMBER 
						AND VS.LINECODE=@LINECODE
						AND VS.ProfitCenterCode=@PROFITCENTERCODE -- added by sachin 20170327 	
				END
				SET @RETURNINT=1

		  RETURN
	 END
	 ELSE IF @CONDITION='GET_PARTS'
	 BEGIN
		SELECT SEWS_PART_NO FROM PRODUCT_MASTER(NOLOCK) WHERE warehouse_cd=@PROFITCENTERCODE AND STS_CD=0
		SET @RETURNINT=1
		RETURN
	 END
	 ELSE IF @CONDITION='SELECT_PART_DETAILS'
	 BEGIN
		DECLARE @TIME DATETIME=CONVERT(TIME,GETDATE())
		DECLARE @Diff INT,@HalfTime INT
			;WITH CTE
			AS
			(			
				SELECT CASE  @SHIFT_CODE				
						WHEN DCM.MONDAY THEN 1
						WHEN DCM.TUESDAY THEN 2
						WHEN DCM.WEDNESDAY THEN 3
						WHEN DCM.THURSDAY THEN 4
						WHEN DCM.FRIDAY THEN  5
						WHEN DCM.SATURDAY THEN 6
						WHEN DCM.SUNDAY THEN 7
						END AS 'DAYCODE', ShiftCode		
				FROM DATECODEMST DCM WITH(NOLOCK) 
				WHERE DCM.PROFITCENTERCODE='0064'
			)
			SELECT @SHIFT_CODE=ShiftCode FROM CTE WHERE ISNULL(DAYCODE,'')<>''
			IF EXISTS(SELECT TOP 1 1 FROM ShiftMst WHERE ShiftCode=@SHIFT_CODE AND ToTime>FromTime)
			BEGIN
				SELECT @HalfTime= DATEDIFF(MINUTE,FromTime,ToTime) FROM ShiftMst WHERE ShiftCode=@SHIFT_CODE
			END
			ELSE IF EXISTS(SELECT TOP 1 1 FROM ShiftMst WHERE ShiftCode=@SHIFT_CODE AND ToTime<FromTime)
			BEGIN
				SELECT @HalfTime= DATEDIFF(MINUTE,ToTime,FromTime) FROM ShiftMst WHERE ShiftCode=@SHIFT_CODE
			END
			SELECT @HalfTime=@HalfTime/2
			SELECT @Diff= DATEDIFF(MINUTE,FromTime,@TIME) FROM ShiftMst WHERE ShiftCode=@SHIFT_CODE
			IF(@Diff>@HalfTime) 
			BEGIN 
				SELECT @SHIFT_CODE= '2'
			END
			ELSE 
			BEGIN 
				SELECT @SHIFT_CODE= '1'
			END

		SELECT TOP 1 @RETURNINT= CONVERT(INT, ISNULL(VS.COUNTER,0))
		FROM ASSY_VISION_SYSTEM_LOG(NOLOCK) VS
		WHERE  VS.LINECODE=@LINECODE
		AND VS.ProfitCenterCode=@PROFITCENTERCODE 
		AND VS.PartNumber=@PARTNO

		SELECT ISNULL(@RETURNINT,'') AS COUNTER, @SHIFT_CODE AS BATCH

		SET @RETURNINT=1
		RETURN
	 END
	 ELSE IF @CONDITION='CHECK_SETPARAMETER'
	 BEGIN
	      SELECT @RETURNVALUE=RP.ASSY_PARTNO  FROM ASSY_RUNNINGPART(NOLOCK)RP		 
		  WHERE RP.LINECODE=@LINECODE AND ASSY_MODE IN ('Production','Rework')
		  SET @RETURNINT=1
		    RETURN
	 END
	 ELSE IF @CONDITION='GET_PARTS_FOR_PRINTING'
	 BEGIN

	       IF EXISTS
		   (
				SELECT TOP 1 1 FROM ASSY_RUNNINGPART WITH(NOLOCK) WHERE PROFITCENTERCODE =@PROFITCENTERCODE 
				AND LINECODE =@LINECODE AND ASSY_MODE IN ('Production','Rework') AND ISNULL(PARTTYPE,'')='STMC'  
		   )   
		   BEGIN
					 SELECT M.LINECODE,M.DATECODE,M.PARTNO, M.BARCODE,M.SERIALNO FROM ASSY_MANUAL_PRINTED_BARCODE(NOLOCK) M INNER JOIN ASSY_RUNNINGPART(NOLOCK)P
					 ON M.LINECODE =P.LINECODE AND M.DATECODE =P.DATECODE AND M.PARTNO =P.SERVO_PARTNO 
					 WHERE M.LINECODE =@LINECODE AND M.PROFITCENTERCODE =@PROFITCENTERCODE AND ISNULL(M.REPRINT,0)=0  AND P.ASSY_MODE IN ('Production','Rework')
			END
			ELSE
				BEGIN
						 SELECT M.LINECODE,M.DATECODE,M.PARTNO, M.BARCODE,M.SERIALNO FROM ASSY_MANUAL_PRINTED_BARCODE(NOLOCK) M INNER JOIN ASSY_RUNNINGPART(NOLOCK)P
						ON M.LINECODE =P.LINECODE AND M.DATECODE =P.DATECODE AND M.PARTNO =P.ASSY_PARTNO
						WHERE M.LINECODE =@LINECODE AND M.PROFITCENTERCODE =@PROFITCENTERCODE AND ISNULL(M.REPRINT,0)=0  AND P.ASSY_MODE IN ('Production','Rework')

				END
			 SET @RETURNINT=1
		   RETURN
	 END
	 ELSE IF @CONDITION='UPDATE_PRINT_STATUS'
	 BEGIN
			 IF EXISTS
		      (
				  SELECT TOP 1 1 FROM ASSY_RUNNINGPART WITH(NOLOCK) WHERE PROFITCENTERCODE =@PROFITCENTERCODE 
				  AND LINECODE =@LINECODE AND ASSY_MODE IN ('Production','Rework') AND ISNULL(PARTTYPE,'')='STMC'  
		      )   
		     BEGIN
		   
				 UPDATE M SET M.REPRINT=1 FROM ASSY_MANUAL_PRINTED_BARCODE(NOLOCK) M INNER JOIN ASSY_RUNNINGPART(NOLOCK)P
				 ON M.LINECODE =P.LINECODE AND M.DATECODE =P.DATECODE AND M.PARTNO =P.SERVO_PARTNO
				 WHERE M.LINECODE =@LINECODE AND M.PROFITCENTERCODE =@PROFITCENTERCODE AND ISNULL(M.REPRINT,0)=0  AND P.ASSY_MODE IN ('Production','Rework')
		    END
			ELSE
			  BEGIN
					 UPDATE M SET M.REPRINT=1 FROM ASSY_MANUAL_PRINTED_BARCODE(NOLOCK) M INNER JOIN ASSY_RUNNINGPART(NOLOCK)P
				    ON M.LINECODE =P.LINECODE AND M.DATECODE =P.DATECODE AND M.PARTNO =P.ASSY_PARTNO 
				    WHERE M.LINECODE =@LINECODE AND M.PROFITCENTERCODE =@PROFITCENTERCODE AND ISNULL(M.REPRINT,0)=0  AND P.ASSY_MODE IN ('Production','Rework')


			  END


		  SET @RETURNINT=1
		   RETURN
	 END
	 ELSE IF @CONDITION='GET_DEFAULT_LABEL_QTY'
	 BEGIN	 
			SELECT  @RETURNVALUE=RTRIM(LTRIM(PARAMETER_VALUE)) FROM PARAMETER_MST(NOLOCK) 
			WHERE PARAMETER_C='ASSLINE' AND PARAMETER_C1 ='MANUALLABELPRINTING' AND PARAMETER_C2='MANUALBARCODEQTY'
			AND WH_CODE =@PROFITCENTERCODE 
			 SET @RETURNINT=1
			  RETURN
	 END
	 ELSE IF @CONDITION='INSERT_BARCODES_DETAILS_INTO_MAINSERVER'
	  BEGIN
				INSERT INTO ASSY_MANUAL_PRINTED_BARCODE_DTL
				(
				PROFITCENTERCODE ,
				[LINECODE] ,
				[PARTNO] ,
				[DATECODE] ,
				[NOOFPRINTEDLBL],
				[FROMSERIALNO] ,
				[TOSERIALNO] ,
				[REASON] ,
				USERID ,
				[TIMESTAMP] 
				)
				SELECT 
				@PROFITCENTERCODE ,
				@LINECODE ,
				@PARTNO,
				@DATECODE,
				@NOOFPRINTEDLBL ,
				@FROMSERIALNO ,
				@TOSERIALNO,
				@REASON, 
				@USERID,
				GETDATE()				
				SET @RETURNINT=1
	  END
	 ELSE IF @CONDITION='MANUAL_PRINT_BARCODE_LIMIT'
			BEGIN
			SELECT  @RETURNVALUE = RTRIM(LTRIM(PARAMETER_VALUE)) FROM PARAMETER_MST (NOLOCK)
				WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'FINALVIEWING' AND PARAMETER_C2 = 'MANUAL_PRINT_BARCODE_LIMIT'
					AND WH_CODE = @PROFITCENTERCODE 
			SET @RETURNINT = 1
		RETURN
	END  -- OPTION ADDED BY SACHIN 20170329 - TO GET CUSTOMER PART NUMBER
	 ELSE IF @CONDITION='GET_CUSTOMER_PART'
	 BEGIN
				DECLARE @customer table
				(
				  RESULT   varchar(3),
				  CUST_PART_NO nvarchar(50),
				  ZPL   nvarchar(2000)
				)

				

				
				SET @QUERY= 'SELECT CUSTOMER_PART_NO,COUPLING_LBL_PRN FROM '+ @SERVERNAME +
				'.' +@DBNAME+'.dbo.PKG_PART_MAPPING '+'
				WHERE PART_NUMBER=' + '''' + @PARTNO + '''' + ' and ' +
				'wh_code=' + '''' + @PROFITCENTERCODE + '''' 

				insert into @customer(CUST_PART_NO,ZPL)
				EXEC(@QUERY)

				IF EXISTS(SELECT TOP 1 1 FROM @CUSTOMER where ISNULL(ZPL,'')<>'')
				BEGIN
				SELECT 'OK' AS RESULT,CUST_PART_NO FROM @CUSTOMER
				END
				ELSE
				BEGIN
				INSERT INTO @CUSTOMER VALUES('NOK','','')	
				SELECT RESULT,'PART NO FOUND IN PKG PART MAPPING '+@PARTNO + ' OR COUPLING LBL PRN NOT DEFINED' AS CUST_PART_NO  FROM @CUSTOMER			 
				END


		 END
	  ELSE IF @CONDITION='GenerateSerial'
	 BEGIN
		
				DECLARE @GenerateSerial table
				(
				   strBarcode nvarchar(100),
				   strBarcodeAndSeqNo nvarchar(100),
				   barcodelabel nvarchar(1000),
				   CustomerSerial nvarchar(100),
				   Customerlabel nvarchar(1000)
				)
				DECLARE @ZPL nvarchar(2000)
				DECLARE @TMP_BARCODE_ZPL nvarchar(2000)
				DECLARE @TMP_CUST_ZPL nvarchar(2000)
				DECLARE @iSeqNo INT = 0
				DECLARE @NO_OF_LABELS INT = 0
				DECLARE @Barcode_ nvarchar(100)=''
				DECLARE @Barcode_With_Squence nvarchar(200)=''
				DECLARE @CustomerSerial nvarchar(100)=''
				SET @iSeqNo = convert(INT,@SERIALNO) + 1
				SET @NO_OF_LABELS = convert(INT,@TOSERIALNO)
        
				DECLARE @TBL_ZPL table	
				(ZPL nvarchar(2000))
		
				SET @QUERY= 'SELECT Coupling_Lbl_Prn FROM '+ @SERVERNAME +
				'.' +@DBNAME+'.dbo.PKG_PART_MAPPING '+'
				WHERE PART_NUMBER=' + '''' + @PARTNO + '''' + ' and ' +
				'CUSTOMER_PART_NO=' + '''' + @CUSTPARTNO + '''' + ' and ' +
				'wh_code=' + '''' + @PROFITCENTERCODE + '''' 

				insert into @TBL_ZPL(ZPL)
				EXEC(@QUERY)

				
				SELECT @ZPL=ZPL FROM @TBL_ZPL
				SET @TMP_BARCODE_ZPL=@ZPL
				SET @TMP_CUST_ZPL=@ZPL
				
				
		
		while(@NO_OF_LABELS > 0)
		begin
			

			SET @Barcode_=@PARTNO + @DATECODE + REPLICATE('0', 8-LEN(@iSeqNo))+RTRIM(@iSeqNo) + @LINECODE
			SET @Barcode_With_Squence=@BARCODE_+'~'+REPLICATE('0', 8-LEN(@iSeqNo))+RTRIM(@iSeqNo)
			SET @CUSTOMERSERIAL = @CUSTPARTNO + convert(varchar, getdate(), 103)

			SET @TMP_BARCODE_ZPL = REPLACE(@TMP_BARCODE_ZPL,'V_BARCODE',@Barcode_)
			SET @TMP_BARCODE_ZPL = REPLACE(@TMP_BARCODE_ZPL,'V_CUST_PART_NO',@Barcode_)
			SET @TMP_BARCODE_ZPL = REPLACE(@TMP_BARCODE_ZPL,'V_DATE','')

			SET @TMP_CUST_ZPL = REPLACE(@TMP_CUST_ZPL,'V_BARCODE',@CUSTOMERSERIAL)
			SET @TMP_CUST_ZPL = REPLACE(@TMP_CUST_ZPL,'V_CUST_PART_NO',@CUSTPARTNO)
			SET @TMP_CUST_ZPL = REPLACE(@TMP_CUST_ZPL,'V_DATE',convert(varchar, getdate(), 103))

			insert into @GenerateSerial
			values(@Barcode_,@Barcode_With_Squence,@TMP_BARCODE_ZPL,@CUSTOMERSERIAL,@TMP_CUST_ZPL)
        
        
    		set @NO_OF_LABELS = @NO_OF_LABELS-1
			set @iSeqNo = @iSeqNo+1
			SET @TMP_BARCODE_ZPL=@ZPL
			SET @TMP_CUST_ZPL=@ZPL
				
		end
		  
		SELECT strBarcode,strBarcodeAndSeqNo,barcodelabel,CustomerSerial ,Customerlabel  FROM @GENERATESERIAL	
		    
	 END
END











GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_Manual_TallyChart]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[Assy_Proc_Manual_TallyChart]
AS
BEGIN
	-- AUTHOR:	<Rashid Siddiqui>
	-- CREATE DATE:	<22 September 2015>
	-- DESCRIPTION:	<Tally Chart Manually>
	-- EXEC TallyChart_Manually
	SET NOCOUNT ON;
	Declare @LineCode VARCHAR(5), @ProfitCenterCode VARCHAR(5), @Datecode CHAR (4), @AssyPartNo VARCHAR(15)
	SET @ProfitCenterCode = '0021'

	SELECT Top 1 @Datecode = ISNULL(Datecode,''), @AssyPartNo = ISNULL(Assy_PartNo,''), @LineCode = ISNULL(LineCode,'') FROM Assy_RunningPart (NOLOCK)
		--WHERE RTRIM(LTRIM(LineCode)) = @LineCode
		ORDER By CreatedDate DESC
	PRINT '@LineCode - ' + ISNULL(@LineCode,'')
	PRINT '@Datecode - ' + ISNULL(@Datecode,'')
	PRINT '@AssyPartNo - ' + ISNULL(@AssyPartNo,'')
	
	IF (@Datecode != '' AND @AssyPartNo != '' AND @LineCode != '')
	BEGIN
		UPDATE Assy_LineAssyStatus SET IsTallyChartApproved = 1 
			WHERE RTRIM(LTRIM(LineCode)) = @LineCode
					AND RTRIM(LTRIM(ProfitCenterCode)) = @ProfitCenterCode 
						AND ISNULL(IsTallyChartApproved,0) = 0

		UPDATE Assy_LineAssyStatus_Running SET IsTallyChartApproved = 1
			WHERE RTRIM(LTRIM(LineCode)) = @LineCode
					AND RTRIM(LTRIM(ProfitCenterCode)) = @ProfitCenterCode 
						AND ISNULL(IsTallyChartApproved,0) = 0

		UPDATE Assy_TallyChartStatusData SET Assy_Auth = 1
			WHERE RTRIM(LTRIM(ProfitCenterCode)) = @ProfitCenterCode
				AND RTRIM(LTRIM(LineCode)) = @LineCode
					AND Datecode = @Datecode
						AND ISNULL(Assy_Auth,0) = 0

		UPDATE Assy_RunningPart SET isauthorized = 1
			WHERE RTRIM(LTRIM(LineCode)) = @LineCode

		DELETE FROM Assy_RunningPart
			WHERE RTRIM(LTRIM(LineCode)) = @LineCode

		DELETE FROM Assy_ProductionOrder_ParameterSetting
			WHERE RTRIM(LTRIM(LineCode)) = @LineCode
				AND RTRIM(LTRIM(ProfitCenterCode)) = @ProfitCenterCode

		DELETE FROM Assy_RunningPart_Previous
			WHERE RTRIM(LTRIM(LineCode)) = @LineCode
		
		UPDATE Assy_Scan_OK SET isScan = 0, Barcode = ''
			WHERE RTRIM(LTRIM(LineCode)) = @LineCode
	
		 --Reset all wip related tables
		EXEC Assy_Proc_WIP_Manage  @CONDITION = 'RESET_WIP_RELEATED_TABLES', @LineCode = @LineCode 

		UPDATE Assy_PartWise_PassFail_Count SET IsAuthorized = 1
			WHERE RTRIM(LTRIM(LineCode)) = @LineCode
				  AND RTRIM(LTRIM(ProfitCenterCode)) = @ProfitCenterCode
					AND DateCode = @Datecode
						AND PartNo = @AssyPartNo
							AND ISNULL(IsAuthorized,0) = 0

		--Reset Assy_TallyChart_Approval_Pending table
		EXEC Assy_Proc_TallyChart_Approval_Pending @CONDITION = 'RESET_PENDING_STATUS', @ProfitCenterCode = @ProfitCenterCode, @LineCode = @LineCode
		   
		-- DELETE printed barcode counter FROM table Assy_Barcode_Printed_Counter
		EXEC Assy_Proc_Barcode_Printed_Counter @CONDITION = 'DELETE', @LineCode = @LineCode, @ProfitCenterCode = @ProfitCenterCode  	
	
		--DELETE part type(servo/tmc/stmc) retlated data, if table exists
		IF EXISTS
		(
			SELECT 1 FROM sys.objects WHERE OBJECT_ID = OBJECT_ID('assy_runningpart_type','U')
		)
		BEGIN
				DELETE FROM assy_runningpart_type WHERE LineCode=@LineCode
		END
	
		INSERT INTO Assy_LineAssyStatus
				(
				ProfitCenterCode,
				LineCode,
				MachineCode,
				OperationCode,
				StationCode,
				Barcode,
				Status,
				FailCount,
				Datecode,
				PartNo,
				ScanTimestamp,
				ResultTimestamp,
				Active,
				UserID,
				IsTallyChartApproved,
				IsReworkPart,
				IsPendingPart,
				ProductionOrderNo,
				PROD_LOT_NO
				)
				SELECT 
				ProfitCenterCode,
				LineCode,
				MachineCode,
				OperationCode,
				StationCode,
				Barcode,
				Status,
				FailCount,
				Datecode,
				PartNo,
				ScanTimestamp,
				ResultTimestamp,
				Active,
				UserID,
				IsTallyChartApproved,
				IsReworkPart,
				IsPendingPart,
				ProductionOrderNo,
				PROD_LOT_NO
				FROM
				Assy_LineAssyStatus_Running(NOLOCK)
				WHERE LineCode = @LineCode 
				AND ProfitCenterCode = @ProfitCenterCode	

				DELETE Assy_LineAssyStatus_Running  
				WHERE LineCode = @LineCode 
				AND ProfitCenterCode = @ProfitCenterCode	
					

					--Insert data FROM Assy_LineAssyParamData_Running into Assy_LineAssyParamData for curent barcode AND line code
				INSERT INTO Assy_LineAssyParamData
					(
					[ProfitCenterCode]
					,[LineCode]
					,[MachineCode]
					,[OperationCode]
					,[StationCode]
					,[Barcode]
					,[TagName]
					,[Value]
					,[Result]
					,[Datecode]
					,[UserID]
					,[Timestamp]
					,PartNo
					,[UID]
					,ScanTimestamp
					,CaliperDatecode
					,CaliperSrNo
					)

				SELECT
					[ProfitCenterCode]
					,[LineCode]
					,[MachineCode]
					,[OperationCode]
					,[StationCode]
					,[Barcode]
					,[TagName]
					,[Value]
					,[Result]
					,[Datecode]
					,[UserID]
					,[Timestamp]
					,PartNo
					,[UID]
					,ScanTimestamp
					,CaliperDatecode
					,CaliperSrNo
				FROM Assy_LineAssyParamData_Running(NOLOCK)
				WHERE LineCode = @LineCode 
				AND ProfitCenterCode = @ProfitCenterCode					

				DELETE Assy_LineAssyParamData_Running 
				WHERE	LineCode = @LineCode 
						AND ProfitCenterCode = @ProfitCenterCode

		PRINT 'Manual Tally Chart has been done Successfully.'
	END
	ELSE
		PRINT 'Manual Tally Chart has been not done. Please Open Procedure AND execute Manually...'
END



GO
/****** Object:  StoredProcedure [dbo].[Assy_PROC_ManualDateCode_Updating]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[Assy_PROC_ManualDateCode_Updating]
(

@Operation varchar(50),
@DateCode char(4)='',
@UserName varchar(50)='',
@ReturnValue VARCHAR (2000)=NULL OUT,
@ReturnInt INT=NULL OUT,
@ProfitCenterCode varchar(20)=null,
@LineCode varchar(20)=null    
)
as

begin
			BEGIN TRY   
			SET NOCOUNT ON

			if @Operation='Update'

			begin 				
					
					if exists(select datecode from Assy_Manual_DateCode_Entry(nolock) where ProfitCenterCode=@ProfitCenterCode and Linecode=@linecode)
						update Assy_Manual_DateCode_Entry set Datecode=@datecode,username=@username,timestamp=getdate() 
						where ProfitCenterCode=@ProfitCenterCode and Linecode=@linecode
				   else
				   begin
					   insert into Assy_Manual_DateCode_Entry(datecode,username,timestamp,ProfitCenterCode,LineCode) 
					   values(@datecode,@userName,getdate(),@ProfitCenterCode,@LineCode )
                   end
				   set @ReturnInt=1

			end

			else if @Operation='select'

			begin
			     select @ReturnValue=Datecode from Assy_Manual_DateCode_Entry (nolock) where ProfitCenterCode=@ProfitCenterCode and Linecode=@linecode				 
		         set @ReturnInt=1
			end

			
     END TRY 
	BEGIN CATCH  
		
		SET @ReturnValue =	CAST(ERROR_NUMBER() as varchar(5)) + '|' + 
		CAST(ERROR_SEVERITY()as varchar(5)) + '|' + 
		CAST(ERROR_STATE() as varchar(5)) + '|' + 
		CAST(ERROR_PROCEDURE() as varchar(200)) + '|' + 
		CAST(ERROR_LINE() as varchar(5)) + '|' + 
		CAST(ERROR_MESSAGE() as varchar(1500))							
		SET @ReturnInt = 2

		RAISERROR(@RETURNVALUE,16,1)
	
	   END CATCH
		
end







