/****** Object:  StoredProcedure [dbo].[Assy_Proc_ManualPass]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Assy_Proc_ManualPass] 
	@ID VARCHAR(20) = NULL,
	@ProfitCode VARCHAR(10) = NULL, 
	@Operation VARCHAR (40) = NULL,
	@MachineCode VARCHAR(20) = NULL,
	@OperationCode VARCHAR(20) = NULL,
	@Part_No VARCHAR(10) = NULL,
	@LineCode VARCHAR(10) = NULL,
	@Barcode VARCHAR(100) = NULL,
	@PassFail INT = NULL,
	@Remarks VARCHAR(200) = NULL,
	@IsServer INT = NULL,
	@ReturnValue VARCHAR (2000) = NULL OUT,
	@ReturnInt INT = NULL OUT
AS
BEGIN
		-- =============================================
		-- Author:		<Rashid Siddiqui>
		-- Create date: <27 July 2015>
		-- Description:	<To Update Manually BarCode Pass>
		--
		-- =============================================
	BEGIN TRY
		DECLARE @FV_MachineCode VARCHAR(20) = '', @VS_MachineCode VARCHAR(20) = ''

		SELECT @FV_MachineCode = dbo.Assy_FN_Get_FinalViewing_MachineCode_From_LineCode(@ProfitCode,@LineCode)
		
		SELECT Top 1 @VS_MachineCode = ISNULL(MachineCode,'') FROM RoutingConfigLineWise (NOLOCK)
			WHERE	ProfitCenterCode = @ProfitCode AND LineCode = @LineCode
					AND OperationSeqNo = 1

			IF @FV_MachineCode = ''
			BEGIN
				IF (LEFT(@LineCode,1) = 'M')
					SET @FV_MachineCode = 'MCFV'
				ELSE IF(LEFT(@LineCode,1) = 'P')
					SET @FV_MachineCode = 'MCFVSTMC'
			END
		--Start Add by Rashid Siddiqui 25/07/2015 for Pass Manually BarCode
		IF(@Operation = 'GET_MACHINE_CODE')
		BEGIN
			SELECT Distinct M.MachineCode, M.MachineName FROM MachineMst M
				JOIN Assy_LineAssyStatus_Running A
					ON M.ProfitCenterCode = A.ProfitCenterCode
						AND M.MachineCode = A.MachineCode
							--AND ISNULL(STATUS,'') = ''
							--Modified by Rashid Siddiqui on 27/04/2016 for Performance
							AND (ISNULL(STATUS,'') = '' OR ISNULL(STATUS,'') = 'PE')
								WHERE
									M.MachineCode NOT IN (@FV_MachineCode,@VS_MachineCode) AND 
									--Add by Rashid Siddiqui 21/09/2015 for Not Considering PokaYoke
									A.Datecode != 'PKYK' AND M.MachineCode != 'MCCRMP'
									AND
										A.ProfitCenterCode = @ProfitCode AND A.LineCode = @LineCode Order By 2
		END
		
		ELSE IF(@Operation = 'GET_PENDING_BARCODE')
		BEGIN
			IF (ISNULL(@MachineCode,'') != '')
			BEGIN
				SELECT Distinct A.Barcode, A.OperationCode FROM MachineMst M
					JOIN Assy_LineAssyStatus_Running A
						ON M.ProfitCenterCode = A.ProfitCenterCode
							AND M.MachineCode = A.MachineCode
								--AND ISNULL(STATUS,'') = ''
								--Modified by Rashid Siddiqui on 27/04/2016 for Performance
								AND (ISNULL(STATUS,'') = '' OR ISNULL(STATUS,'') = 'PE')
									WHERE
										M.MachineCode NOT IN (@FV_MachineCode,@VS_MachineCode) AND 
										--Add by Rashid Siddiqui 21/09/2015 for Not Considering PokaYoke
											A.Datecode != 'PKYK'
											AND
												A.ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND M.MachineCode = @MachineCode Order By 1
			END
		END

		ELSE IF(@Operation = 'PASS_MANUAL_BARCODE')
		BEGIN
				INSERT INTO [dbo].[Assy_LineAssyManualPassFail] ([ProfitCenterCode],[LineCode],[MachineCode],[OperationCode],[Barcode],[Status],[Remarks],[Timestamp],[UserID])
								VALUES(@ProfitCode,@LineCode,@MachineCode,@OperationCode,@Barcode,Case @PassFail WHEN 1 THEN 'PS' WHEN 0 THEN 'FL' END,@Remarks,GETDATE(),@ID)

				UPDATE Assy_LineAssyStatus_Running
						SET STATUS = Case @PassFail WHEN 1 THEN 'PS' WHEN 0 THEN 'FL' END, ResultTimestamp = GETDATE()
							WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND MachineCode = @MachineCode AND 
								Barcode = @Barcode AND OperationCode = @OperationCode
								--Modified by Rashid Siddiqui on 27/04/2016 for Performance
								AND (ISNULL(STATUS,'') = '' OR ISNULL(STATUS,'') = 'PE')
				
				UPDATE Assy_Scan_OK SET Barcode = '' WHERE LineCode = @LineCode AND MachineCode = @MachineCode AND OperationCode = @OperationCode
										AND ISNULL(Barcode,'') <> ''

				UPDATE Assy_Result SET Barcode = @Barcode WHERE LineCode = @LineCode AND OperationCode = @OperationCode AND ISNULL(Barcode,'') <> ''
				
				--Changed by ravi on 151216 for jhagadia
				if exists
				(
					select 1 from linemst with(nolock) where ProfitCenterCode =@ProfitCode and LineCode =@LineCode and isnull(isActive,0)=1 and  isnull(Allow2Parts,0)=1
				)
				begin
					delete from Assy_PreviousPending_Parts  where ProfitCenterCode=@ProfitCode and LineCode =@LineCode 
					and MachineCode=@MachineCode and Barcode=@Barcode and isnull(Is_Rejected,0)=0
				end


				--Add by Rashid Siddiqui 21/09/2015 for WIP Limit
				IF @IsServer = 0
					EXEC Assy_proc_WIP_Manage @CONDITION = 'UPDATE_WIP_COUNT', @LineCode = @LineCode, @MachineCode = @MachineCode , @Barcode = @Barcode, @ProfitCenterCode = @ProfitCode				 
		END
		--End Add by Rashid Siddiqui 25/07/2015 for Pass Manually BarCode
	--TRY BLOCK ENDS
	    ELSE IF (@Operation='LOG_MANUAL_PASS_BARCODE')
		BEGIN
			INSERT INTO [dbo].[Assy_LineAssyManualPassFail] ([ProfitCenterCode],[LineCode],[MachineCode],[OperationCode],[Barcode],[Status],[Remarks],[Timestamp],[UserID])
			VALUES(@ProfitCode,@LineCode,@MachineCode,@OperationCode,@Barcode,Case @PassFail WHEN 1 THEN 'PS' WHEN 0 THEN 'FL' END,@Remarks,GETDATE(),@ID)
		END
	END TRY
	BEGIN CATCH  
		--CATCH BLOCK BEGINS
		SET @ReturnValue =	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_SEVERITY() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
		CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_MESSAGE() AS VARCHAR(1500))
		RAISERROR(@ReturnValue,16,1)
		SET @ReturnInt = 2
		--CATCH BLOCK ENDS 
	END CATCH
END


GO
/****** Object:  StoredProcedure [dbo].[ASSY_PROC_MASTERS_SYNC_REQUIRED]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[ASSY_PROC_MASTERS_SYNC_REQUIRED]
(
@CONDITION VARCHAR(50) = NULL,
@PROFITCENTERCODE VARCHAR(30)=NULL,
@LINECODE VARCHAR(30)=NULL,
@TABLECODE VARCHAR(100) = NULL,
@ISACTIVE BIT = 0,
@USERNAME VARCHAR(25)= NULL,
@RETURNVALUE VARCHAR (2000)=NULL OUT,
@RETURNINT INT=NULL OUT
)
AS
BEGIN
		--AUTHOR:<RAVISHANKAR MISHRA>
		--CREATED DATE:<08-05-15>
		--SELECT * FROM ASSY_MASTERS_SYNC_REQUIRED
		--EXEC ASSY_PROC_MASTERS_SYNC_REQUIRED @CONDITION='SELECT',@PROFITCENTERCODE ='0021',@LINECODE ='M07'
		--SELECT * FROM ASSY_MASTERS_SYNC_REQUIRED WHERE LINECODE = 'M07'
		SET NOCOUNT ON
		IF @CONDITION='SELECT'
		BEGIN
				SELECT A.TABLECODE, A.TABLENAME AS [TABLE NAME], ISNULL(B.ISACTIVE, 0) AS [IS ACTIVE] FROM ASSY_SYNC_MASTER_HDR_DTL  A 
				LEFT OUTER JOIN ASSY_MASTERS_SYNC_REQUIRED  B ON A.TABLECODE = B.TABLECODE
				AND B.PROFITCENTERCODE = @PROFITCENTERCODE AND B.LINECODE = @LINECODE
			     ORDER BY B.SequenceNo --Modified by Sachin 19Nov2019
				SET @RETURNINT=1
		END
		ELSE IF @CONDITION='UPDATE'
		BEGIN
				IF EXISTS
				(
					SELECT 1 FROM ASSY_MASTERS_SYNC_REQUIRED(NOLOCK) WHERE PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE =@LINECODE AND TABLECODE = @TABLECODE
				)
				BEGIN
				
				--PRINT 'CONTROL HERE'
						UPDATE ASSY_MASTERS_SYNC_REQUIRED SET ISACTIVE = @ISACTIVE, ENT_USER=@USERNAME,ENT_DT=GETDATE()
						 WHERE PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE =@LINECODE AND TABLECODE = @TABLECODE

				END
				ELSE
				BEGIN
					INSERT INTO ASSY_MASTERS_SYNC_REQUIRED
					(
						PROFITCENTERCODE,
						LINECODE,
						TABLECODE,
						ISACTIVE,
						ENT_DT,
						ENT_USER
					)
					SELECT 
					@PROFITCENTERCODE,
						@LINECODE,
						@TABLECODE,
						@ISACTIVE,
						GETDATE(),
						@USERNAME
						
				END

				SET @RETURNINT =1
		END

END




GO
/****** Object:  StoredProcedure [dbo].[ASSY_PROC_MATERIALFEED_CONSUMEDQTY]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[ASSY_PROC_MATERIALFEED_CONSUMEDQTY]
		@PART_NUMBER NVARCHAR(20),
		@WH_CODE NVARCHAR(4),
		@LINECODE NVARCHAR(4)
		AS
		BEGIN

		 SET XACT_ABORT ON;
		  SET NOCOUNT ON;
		  BEGIN TRY
		DECLARE @A Table(Result nvarchar(max));
		DECLARE @PLANNEDQTY int=0;
		DECLARE @PRODUCTIONORDERNO nvarchar(30),@DATECODE NVARCHAR(4);
		select top 1 @PLANNEDQTY=CURRENTPLANNEDQTY,@PRODUCTIONORDERNO=PRODUCTIONORDERNO,@DATECODE=DATECODE From Assy_RunningPart(NOLOCK) where  LineCode=@LINECODE;
		--select @PLANNEDQTY;
		-- WITH CTE (RM_PART_NO, FG_PART_NO, LEVEL, MAT_PROCURE_TYPE)
  --      AS (SELECT
  --        RM_PART_NO,
  --        FG_PART_NO,
  --        0 AS LEVEL,
  --        MAT_PROCURE_TYPE
  --      FROM BOM_MASTER(nolock)
  --      WHERE FG_PART_NO = @PART_NUMBER
  --      AND WH_CODE = @WH_CODE
  --      AND STS_CD = 0
  --      UNION ALL
  --      SELECT
  --        BOM.RM_PART_NO,
  --        CTE.RM_PART_NO,
  --        LEVEL + 1,
  --        BOM.MAT_PROCURE_TYPE
  --      FROM CTE AS CTE
  --      INNER JOIN BOM_MASTER BOM (NOLOCK)
  --        ON BOM.FG_PART_NO = CTE.RM_PART_NO
  --        AND CTE.MAT_PROCURE_TYPE = 50
  --      WHERE WH_CODE = @WH_CODE
  --      AND STS_CD = 0)
  --      insert into @A select  concat(cte.RM_PART_NO,'	-- ',@PLANNEDQTY,'	-- ',ISNULL(STOCKSTATUS.CONSUMED_QTY,0),'	-- ', case when STOCKSTATUS.BALANCE_QTY is null then (@PLANNEDQTY-ISNULL(STOCKSTATUS.CONSUMED_QTY,0))  else  ISNULL(STOCKSTATUS.BALANCE_QTY,0)  end)  From CTE as cte inner join product_master(nolock) as pm on cte.RM_PART_NO=pm.SEWS_PART_NO  and Pm.sts_Cd=0  and warehouse_cd=@WH_CODE and pm.PART_TRACE_FLAG=1 
		--LEFT join Assy_LineMaterialStockStatus as STOCKSTATUS on cte.RM_PART_NO=STOCKSTATUS.RM_PART_NO and STOCKSTATUS.STS_CD=0 
		
		
		DECLARE  @TEMPEXPLOSION TABLE(FG_PART_NO NVARCHAR(12),BOMPART_NO NVARCHAR(20),RM_PART_NO NVARCHAR(12),BOM_QTY DECIMAL(18,2),BOM_UNIT NVARCHAR(10),MAT_PROCEDURE_TYPE NVARCHAR(50),MAT_USE_RATIO INT,ALT_ITEM_GRP_CODE NVARCHAR(50))
		INSERT INTO @TEMPEXPLOSION exec Proc_BOM_Explosion @WH_CODE,@PART_NUMBER,'','1','SUMMARY'

		insert into @A select concat(BOMEXPLOSION.RM_PART_NO,'	-- ',(BOMEXPLOSION.BOM_QTY*@PLANNEDQTY),'	-- ',ISNULL(SUM(STOCKSTATUS.CONSUMED_QTY),0),'	-- ',case when SUM(STOCKSTATUS.BALANCE_QTY) is null then (@PLANNEDQTY-ISNULL(SUM(STOCKSTATUS.CONSUMED_QTY),0))  else  ISNULL(SUM(STOCKSTATUS.BALANCE_QTY),0)   end ) From @TEMPEXPLOSION as BOMEXPLOSION inner join PRODUCT_MASTER AS PM on BOMEXPLOSION.RM_PART_NO=PM.SEWS_PART_NO  and Pm.sts_Cd=0  and warehouse_cd=@WH_CODE and pm.PART_TRACE_FLAG=1 
		LEFT join Assy_LineMaterialStockStatus as STOCKSTATUS on BOMEXPLOSION.RM_PART_NO=STOCKSTATUS.RM_PART_NO and STOCKSTATUS.STS_CD=0  group by BOMEXPLOSION.FG_PART_NO,BOMEXPLOSION.RM_PART_NO,BOMEXPLOSION.BOM_QTY
		DECLARE @BALQTY int=0;
		select top 1  @BALQTY=(ISNULL(PASSQTY,0)+ISNULL(FAILQTY,0)) From Assy_PartWise_PassFail_Count(noloCK) where PARTNO=@PART_NUMBER and  DateCode=@DATECODE   order by [Timestamp] DESC;
		select CONCAT('FG PART NO','	 --','BALALNCE QTY','^',@PART_NUMBER,'		 --',@BALQTY,'^','Part No','	--','BOM Qty','--','Avl Qty','--','Bal Qty','^',stuff((select '^'+RESULT From @A for xml path('')),1,1,''))

		END TRY
		BEGIN CATCH
		SELECT  CONCAT('FAILURE|',ERROR_MESSAGE());
		END CATCH
		END


GO
/****** Object:  StoredProcedure [dbo].[ASSY_PROC_MATERIALFEED_DATA]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[ASSY_PROC_MATERIALFEED_DATA]
@TYPE int =0,
@profitcentercode NVARCHAR(MAX)=NULL,
@ReturnValue NVARCHAR(MAX) OUTPUT,
@ReturnInt int output
AS

BEGIN
IF(@TYPE=1)
BEGIN
SELECT linecode FROM LineTypeMst AS lt with(nolock) INNER JOIN linemst AS lm with(nolock) ON lm.LineTypeCode = lt.LineTypeCode
AND
                                                                              lm.isActive = 1
                                                                              AND
                                                                              lm.ProfitCenterCode = lt.ProfitCenterCode
                                                                              AND
                                                                              lm.ProfitCenterCode = '0021'
                                                                              
                                                                              AND
                                                                              lt.LineTypeName IN( SELECT PARAMETER_VALUE
                                                                                                  FROM PARAMETER_MST  with(nolock)
                                                                                                  WHERE wh_code = '0021'
                                                                                                        AND
                                                                                                        PARAMETER_C = 'assline'
                                                                                                        AND
                                                                                                        PARAMETER_C1 = 'MaterialFeedLineType')
END
ELSE IF(@TYPE=2)
BEGIN
select  distinct Datecode From Assy_MaterialFeeding with(nolock)
END
ELSE IF(@TYPE=3)
BEGIN
select  distinct FGPartCode From Assy_MaterialFeeding with(nolock)
END
ELSE IF(@TYPE=4)
BEGIN
select  distinct PACKETID From Assy_MaterialFeeding with(nolock)
END
END


GO
/****** Object:  StoredProcedure [dbo].[ASSY_PROC_MATERIALFEED_ONLINESTATUS]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
--Created by Nelson
-- Date  01/03/2016
--DECLARE	@return_value int,
--		@RETURNVALUE nvarchar(max),
--		@RETURNINT int

--EXEC	[dbo].[ASSY_PROC_MATERIALFEED_ONLINESTATUS]
--		@DATECODE = N'09Dc',
--		@LINECODE = N'M03',
--		@PROFITCENTERCODE = N'0021',
--		@RETURNVALUE = @RETURNVALUE OUTPUT,
--		@RETURNINT = @RETURNINT OUTPUT

CREATE proc [dbo].[ASSY_PROC_MATERIALFEED_ONLINESTATUS]
@PARTNUMBER  NVARCHAR(30)=NULL,
@DATECODE NVARCHAR(4)=NULL,
@LINECODE NVARCHAR(10)=NULL,
@PROFITCENTERCODE NVARCHAR(6)=NULL,
@VERSION nvarchar(2)=null,
@RETURNVALUE NVARCHAR(MAX) OUTPUT,
@RETURNINT int output
as
begin
DECLARE @SQL NVARCHAR(MAX)='';
--select @PARTNUMBER= isnull(Assy_PartNo,'') From Assy_RunningPart with(nolock) where LineCode=@LINECODE;

select @PARTNUMBER=isnull(Assy_PartNo,''),@VERSION=isnull(PO.ver,0) From ASSY_RUNNINGPART as RUNNING with(nolock) inner join Assy_ProductionOrderMst as PO with(nolock) on RUNNING.Assy_PartNo=PO.PartNo and RUNNING.productionOrderno=PO.OrderNo where LineCode=@LINECODE
SET @SQL=';with CTE(RM_PART_NO ,FG_PART_NO,LEVEL)
as
(
select RM_PART_NO ,FG_PART_NO,0 as LEVEL from BOM_MASTER  with(nolock) where FG_PART_NO='''+@PARTNUMBER+''' and WH_CODE='''+@PROFITCENTERCODE+'''  and isnull(ver,0)='''+@VERSION+''' and isnull(sts_cd,0)=0
union all
select BOM.RM_PART_NO, CTE.RM_PART_NO,LEVEL+1 from CTE as CTE inner join BOM_MASTER BOM with(nolock) on BOM.FG_PART_NO=CTE.RM_PART_NO where WH_CODE='''+@PROFITCENTERCODE+''' and  isnull(BOM.ver,0)='''+@VERSION+''' and  isnull(sts_cd,0)=0
)
, cte2 (FGPartCode,ChildPartNo,SerialNo,ENTDT)
as
(
select  MF.FGPartCode,MF.ChildPartNo,PacketId as SerialNo,MF.ENTDT from ASSY_MATERIALFEEDING as MF with(nolock)  where MF.FGPartCode='''+@PARTNUMBER+''' and Datecode='''+@DATECODE+''' and LINECODE='''+@LINECODE+'''
)
select CTE.FG_PART_NO,CTE.RM_PART_NO,pm.product_nm as CHILDPARTDESC,CTE2.ChildPartNo,CTE2.FGPartCode,CTE2.SerialNo,CTE2.ENTDT,CASE WHEN isnull(CTE2.ChildPartNo,'''')!='''' THEN CAST(CTE2.entdT AS NVARCHAR(20)) ELSE ''NOT FEEDED'' END AS RESULT from CTE as CTE LEFT join cte2 as CTE2 on CTE.RM_PART_NO=CTE2.ChildPartNo  left join product_master as pm with(nolock) on  CTE.rm_part_no=pm.SEWS_PART_NO and pm.sts_cd=0 and warehouse_cd='''+@PROFITCENTERCODE+'''  order by LEVEL option(maxrecursion 0)'
--SET @SQL='select t1.FG_PART_NO,T1.RM_PART_NO,[PRODUCT_NM] CHILDPARTDESC,t2.SerialNo,t2.FGPARTCODE,t2.CHILDPARTNO,t2.ENTDT,CASE WHEN isnull(t2.ChildPartNo,'''')!='''' THEN CAST(t2.entdT AS NVARCHAR(20)) ELSE ''NOT FEEDED'' END AS RESULT From  (select FG_PART_NO,RM_PART_NO,PM.PRODUCT_NM From  BOM_MASTER as BOM inner join PRODUCT_MASTER AS PM on BOM.RM_PART_NO=PM.SEWS_PART_NO  where FG_PART_NO='''+@PARTNUMBER+''' and pm.WAREHOUSE_CD='''+@PROFITCENTERCODE+''')T1 left join
--(select  MF.FGPartCode,MF.ChildPartNo,PacketId as SerialNo,MF.ENTDT from ASSY_MATERIALFEEDING as MF  where 1=1 and MF.FGPartCode='''+@PARTNUMBER+''' and Datecode='''+@DATECODE+''' and LINECODE='''+@LINECODE+''') as t2 on t1.RM_PART_NO=t2.ChildPartNo where t1.FG_PART_NO='''+@PARTNUMBER+'''';

--IF(@PARTNUMBER!='')
--begin
--SET @SQL=CONCAT(@SQL,' AND FG_PART_NO='''+@PARTNUMBER+'''');
--end
--IF(@LINECODE!='')
--begin
--SET @SQL=CONCAT(@SQL,' AND DATECODE='''+@DATECODE+'''');
--end
--IF(@DATECODE!='')
--begin
--SET @SQL=CONCAT(@SQL,' AND LINECODE='''+@LINECODE+'''');
--end
--IF(@PROFITCENTERCODE!='')
--BEGIN
--SET @SQL= CONCAT(@SQL,' AND PROFITCENTERCODE='''+@PROFITCENTERCODE+'''')
--END
--PRINT @SQL;
EXEC SP_EXECUTESQL @SQL;
end



GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_MaterialFeedingValidation]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[Assy_Proc_MaterialFeedingValidation]
(
	@Condition VARCHAR(MAX) = NULL,
	@ProfitCenterCode VARCHAR(10) = NULL,
	@LineCode VARCHAR(10) = NULL,
	@PartNumber VARCHAR(20) = NULL,
	@Barcode VARCHAR(100) = NULL,
	@UserId VARCHAR(10) = NULL,
	@EnableDisableMatFeedValidation INT = NULL,
	@MatFeedIdString VARCHAR(MAX) = NULL,
	@FlushQtyString VARCHAR(MAX) = NULL,
	@MatFeedTable Table_Assy_MatFeed_Type ReadOnly,
	@MsgRemark VARCHAR(MAX) = NULL,
	@ToLineCode VARCHAR(10) = NULL,
	@VendorCode VARCHAR(60) = NULL,
	@NewSerialNoForPrint VARCHAR(60) = NULL,
	@ReturnValue VARCHAR (MAX) = NULL OUT,
	@ReturnInt INT = NULL OUT
)
AS
BEGIN
	-- Author:			<Rashid Siddiqui>
	-- Create Date:		<27-June-2016>
	-- Description:		<Material Feeding Validation>

	-- Modified By:		<Rashid Siddiqui>
	-- Modified Date:	<18-August-2016>
	-- Description:		<Material Feeding Validation>

	-- Modified By:		<Sudesh Kumar>
	-- Modified Date:	<06-Apr-2016>
	-- Description:		<VALIDATING MATERIAL FEEDING BEFORE RFID GENERATION>

	-- Modified By:		<Sudesh Kumar>
	-- Modified Date:	<06-Apr-2016>
	-- Description:		<APPLY WHERE CONDITION ON STUFF IN CONSOLIDATE HISTORY TO GROUP BY NEW SERIAL NO>

	-- Modified By:		<Rashid Siddiqui>
	-- Modified Date:	<01-June-2017>
	-- Description:		<Item Code Variable Changed AND LTCALIPER LineTypeCode added in LOAD_ALL_LINES Block 20170601>

	-- Modified By:		<Naresh Kumar>
	-- Modified Date:	<05-June-2017>
	-- Description:		<Minimum LOT to be assigned so that it can be moved to line on First Picklist AND Code Optimisation (Removing Loop) in CONSOLIDATE_QTY block>

	-- Modified By:		<Rashid Siddiqui>
	-- Modified Date:	<12-June-2017>
	-- Description:		<2 Parts Material Feeding>

	-- Modified By:		<Rashid Siddiqui>
	-- Modified Date:	<12-July-2017>
	-- Description:		<2 Parts Material Feeding Concept commented>

	-- Modified By:		<Bhupendra Singh>
	-- Modified Date:	<25-Sept-2017>
	-- Description:		TASKID:1525 <Insert 00000000000 as INT_LOT_NO for CONSOLIDATED_QTY>

	-- Modified By:		<Ravishankar Mishra>
	-- Modified Date:	<26-Sep-2017>
	-- Description:		Passing part no. from front END instead of getting from Assy_MachineWise_RunningPart table

	-- Modified By:		<Ravishankar Mishra>
	-- Modified Date:	<30-Oct-2017>
	-- Description:		For Jhagadia Line-4 ,read data Partno from Assy_RunningPart part

	-- Modified By:		<Rashid Siddiqui>
	-- Modified Date:	<26-Oct-2017>
	-- Description:		Optimized Child Part Consumption Block - MAT_FEED_STOCK_DEDUCTION

	-- Modified By:		<Rashid Siddiqui>
	-- Modified Date:	<01-Nov-2017>
	-- Description:		New Block - GET_FLUSH_OUT_STOCK - Fetch Flush Out Stock

	/*
	Declare @ReturnValue VARCHAR(2000), @ReturnInt INT
	EXEC Assy_Proc_MaterialFeedingValidation	@Condition = 'CHECK_MAT_FEED_STOCK', @ProfitCenterCode = '0021', @LineCode = 'P6', @UserId = '1445',
												@Barcode = '2904965552Nc00001934P6', @ReturnValue = @ReturnValue OUT, @ReturnInt = @ReturnInt OUT
	SELECT @ReturnInt, @ReturnValue

	Declare @ReturnValue VARCHAR(2000), @ReturnInt INT
	EXEC Assy_Proc_MaterialFeedingValidation	@Condition = 'MAT_FEED_STOCK_DEDUCTION', @ProfitCenterCode = '0021', @LineCode = 'P6', @UserId = '1445',
												@Barcode = '', @PartNumber = '', @ReturnValue = @ReturnValue OUT, @ReturnInt = @ReturnInt OUT
	SELECT @ReturnInt, @ReturnValue

	Declare @ReturnValue VARCHAR(2000), @ReturnInt INT
	EXEC Assy_Proc_MaterialFeedingValidation	@Condition = 'MAT_FEED_STOCK_DEDUCTION_IN_INV_SERIAL_WHEN_PROD_CONF_ENABLE', @ProfitCenterCode = '0021',
												@LineCode = 'P6', @UserId = '1445', @Barcode = '', @ReturnValue = @ReturnValue OUT, @ReturnInt = @ReturnInt OUT
	SELECT @ReturnInt, @ReturnValue

	Declare @ReturnValue VARCHAR(2000), @ReturnInt INT
	EXEC Assy_Proc_MaterialFeedingValidation	@Condition = 'GET_STOCK_STATUS', @ProfitCenterCode = '0021',
												@LineCode = 'P6', @UserId = '1445', @ReturnValue = @ReturnValue OUT, @ReturnInt = @ReturnInt OUT
	SELECT @ReturnInt, @ReturnValue
	
	*/
	BEGIN TRAN
	BEGIN TRY
		SET NOCOUNT ON;
		DECLARE @Status INT = 0, @PartsNotExistsInStockTable VARCHAR(100) = '', @LoopStart INT = 1, @LoopEnd INT = 0, @MandatoryPartNo VARCHAR(200) = '', @Alt_userId VARCHAR(10) = '',
				@PartsHavingLowQty VARCHAR(200) = '', @Child_Part_Count INT = 0, @Remarks VARCHAR(500) = '', @FedPartsRunningLowQty VARCHAR(300) = '', @PartType VARCHAR(20) = '',
				@IsProdConfRequired BIT = 0, @LoopStockBal INT = 0, @LoopPartBOMQty INT = 0, @IsMatFeedRequired BIT = 0, @MatFeed_Id INT = 0, @FlushQty INT = 0, @sSerialNo VARCHAR(20) = '',
				@STMC_PartNumber VARCHAR(20) = '', @ConsolidateQty INT = 0, @ConsolidatePartNo VARCHAR(20) = '', @Item_No VARCHAR(20) = '', @LocationId VARCHAR(20) = '',@Zone_Code VARCHAR(20) = '',
				@AvailableQty INT = 0, @MissngQty INT = 0, @Allow2Parts BIT = 0;
		
		SELECT Top 1 @IsProdConfRequired = ISNULL(IsProdConfRequired,0), @IsMatFeedRequired = ISNULL(IsMatFeedRequired,0), @Allow2Parts = ISNULL(Allow2Parts,0) FROM LineMst WITH (NOLOCK)
			WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
		
		IF @Allow2Parts = 0
		BEGIN
			SELECT Top 1 @STMC_PartNumber = ISNULL(Assy_PartNo,''), @Alt_userId = ISNULL(CreatedBy,''), @PartType = PartType FROM Assy_RunningPart WITH (NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
		
			IF @PartType = 'STMC'
				SET @PartNumber = @STMC_PartNumber

			IF ISNULL(@PartNumber,'') = ''
				SET @PartNumber = @STMC_PartNumber
			
		END
		ELSE
		BEGIN
		      --Commented By Ravi On 26-09-2017
			--SELECT Top 1 @STMC_PartNumber = ISNULL(Assy_PartNo,''), @Alt_userId = ISNULL(CreatedBy,''), @PartType = PartType FROM Assy_RunningPart WITH (NOLOCK)
			--	WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
		
			--IF @PartType = 'STMC'
			--	SET @PartNumber = @STMC_PartNumber

			--IF ISNULL(@PartNumber,'') = ''
			--	SET @PartNumber = @STMC_PartNumber
			
			-- Commented By Rashid On 12-July-2017 - Material Feeding is not working in Jhagadia beacuse of Allow2Parts Flag -  same is used in Pending part concept in Jhagadia
			--This is only for temp bassis
			IF @Allow2Parts = 1 AND @ProfitCenterCode = '0088' AND @LineCode = 'J04'
			BEGIN
				SELECT Top 1 @PartNumber = ISNULL(Assy_PartNo,''), @Alt_userId = ISNULL(CreatedBy,'') FROM Assy_RunningPart WITH (NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			END
			ELSE
			BEGIN
				SELECT Top 1 @Alt_userId = ISNULL(CreatedBy,'') FROM Assy_RunningPart WITH (NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			END
			
			IF @Condition <>'CHECK_MAT_FEED_STOCK'
			BEGIN
				SELECT @PartNumber = PartNo FROM Assy_MachineWise_RunningPart WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
				AND OperationCode = (SELECT dbo.Assy_FN_Get_FinalViewing_OperationCode_From_LineCode(@ProfitCenterCode,@LineCode))
			END
			--PRINT 'RAVI '+@PartNumber
		END

		--IF @Condition NOT IN ('ENABLE_DISABLE_MAT_FEED_VALIDATION','ALERT_STOCK_CONFIRM','ALERT_STOCK_ACKLATER','FLUSH_QTY','VALIDATE_STOCK_STATUS_FOR_PRINT','TRANSFER_QTY','SELECT_LEFT_QTY_STOCK','TRANSFER_QTY','CONSOLIDATE_QTY','LOAD_CONSOLIDATE_SERIAL_HISTORY','PRINT_STORE_LABEL','VALIDATE_MATFEEDING_BEFORE_RFID')
		IF @Condition IN ('CHECK_MAT_FEED_STOCK','MAT_FEED_STOCK_DEDUCTION')
		BEGIN
			IF ISNULL(@PartNumber,'') = ''
			BEGIN
				SET @ReturnInt = 1
				SET @ReturnValue = 'SetParameterNotDone'
				COMMIT TRAN
				RETURN
				--RAISERROR(@ReturnValue,16,1)
			END
		END

		IF ISNULL(@UserId,'') = ''
			SET @UserId = @Alt_userId

		DECLARE @Bom_Explosion AS TABLE
		(
			AutoID SMALLINT IDENTITY(1,1),
			FG_Part_No VARCHAR(20) NULL,
			BOM_Part_No VARCHAR(20) NULL,
			RM_Part_No VARCHAR(20) NULL,
			BOM_Qty INT NULL,
			BOM_Unit VARCHAR(20) NULL,
			MAT_Procure_Type VARCHAR(20) NULL,
			MAT_Use_Ration VARCHAR(20) NULL,
			Alt_Item_Grp_Code VARCHAR(20) NULL,
			IsMandatory BIT DEFAULT(0)
		)

		IF @Condition = 'CHECK_MAT_FEED_STOCK'
		BEGIN
			IF (@IsMatFeedRequired = 1)
			BEGIN
				DELETE FROM Assy_LineMatFeedRemarkStatus WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode;
				
				IF EXISTS (SELECT 1 FROM Assy_LineAssyStatus WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND Barcode = @Barcode AND ISNULL(Status,'') = 'FL')
				BEGIN
					SET @Remarks = 'OK'
					IF NOT EXISTS (SELECT 1 FROM Assy_LineMatFeedRemarkStatus WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode)
					BEGIN
						INSERT INTO Assy_LineMatFeedRemarkStatus
							(	ProfitCenterCode, LineCode, PartNo, Remarks, [Timestamp], UserID, IsActive)
						SELECT	@ProfitCenterCode, @LineCode, @PartNumber, @Remarks, GETDATE(), @UserId, 1
					END
					ELSE
					BEGIN
						UPDATE Assy_LineMatFeedRemarkStatus
							SET PartNo = @PartNumber, Remarks = @Remarks,
								[Timestamp] = GETDATE(), UserID = @UserId, IsActive = 1
									WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
					END

					SET @ReturnInt = 1
					SET @ReturnValue = @Remarks
					COMMIT TRAN
					RETURN
				END
							
				DELETE FROM @Bom_Explosion

				INSERT INTO @Bom_Explosion(FG_Part_No, BOM_Part_No, RM_Part_No, BOM_Qty, BOM_Unit, MAT_Procure_Type, MAT_Use_Ration, Alt_Item_grp_Code)
				EXEC Proc_BOM_Explosion @ProfitCenterCode, @PartNumber, '', '1', 'SUMMARY'

				SET @LoopEnd = 0
				SELECT @LoopEnd = COUNT(*) FROM @Bom_Explosion

				WHILE (@LoopStart <= @LoopEnd)
				BEGIN
					SET @MandatoryPartNo = ''
					SELECT @MandatoryPartNo = LTRIM(RTRIM(ISNULL(SEWS_PART_NO,''))) FROM Product_Master WITH (NOLOCK) WHERE warehouse_cd = @ProfitCenterCode
						AND SEWS_PART_NO =  (SELECT Top 1 RM_Part_No FROM @Bom_Explosion WHERE AutoID = @LoopStart) AND ISNULL(PART_TRACE_FLAG,0) = 1
	
					IF ISNULL(@MandatoryPartNo,'') <> ''
					BEGIN
						UPDATE @Bom_Explosion
							SET IsMandatory = 1
								WHERE RM_Part_No = @MandatoryPartNo
	
						IF EXISTS (SELECT 1 FROM @Bom_Explosion WHERE IsMandatory = 1 AND RM_Part_No = @MandatoryPartNo AND BOM_Qty > 0)
						BEGIN
							SET @LoopPartBOMQty = 0
							SELECT @LoopPartBOMQty = ISNULL(BOM_Qty,0) FROM @Bom_Explosion WHERE IsMandatory = 1 AND RM_Part_No = @MandatoryPartNo AND BOM_Qty > 0
						
							IF NOT EXISTS (SELECT 1 FROM Assy_LineMaterialStockStatus WITH (NOLOCK)
									WHERE WH_Code = @ProfitCenterCode AND Line_Code = @LineCode AND RM_Part_No = @MandatoryPartNo)
							BEGIN
								SET @Status = 1
								IF ISNULL(@PartsNotExistsInStockTable,'') = ''
									SET @PartsNotExistsInStockTable = @MandatoryPartNo
								ELSE
									SET @PartsNotExistsInStockTable = @PartsNotExistsInStockTable + ',' + @MandatoryPartNo
							END

							IF @Status IN (0,2,3)
							BEGIN
								SET @LoopStockBal = 0
								SELECT @LoopStockBal = ISNULL(SUM(ISNULL(BALANCE_QTY,0)),0) FROM Assy_LineMaterialStockStatus WITH (NOLOCK)
										WHERE WH_Code = @ProfitCenterCode AND Line_Code = @LineCode AND RM_Part_No = @MandatoryPartNo
							
								IF (ISNULL(@LoopStockBal,0) = 0)
										SET @LoopStockBal = 0

								IF (@LoopStockBal < @LoopPartBOMQty)
								BEGIN
									SET @Status = 2
									IF ISNULL(@PartsHavingLowQty,'') = ''
									BEGIN
										SET @PartsHavingLowQty = @MandatoryPartNo
									END
									ELSE
										SET @PartsHavingLowQty = @PartsHavingLowQty + ',' + @MandatoryPartNo
								END
								ELSE
								BEGIN
									SET @LoopStockBal = 0
									SELECT @LoopStockBal = SUM(ISNULL(BALANCE_QTY,0)) FROM Assy_LineMaterialStockStatus WITH (NOLOCK)
											WHERE WH_Code = @ProfitCenterCode AND Line_Code = @LineCode AND RM_Part_No = @MandatoryPartNo AND ISNULL(STS_CD,0) = 0
								
									IF (ISNULL(@LoopStockBal,0) = 0)
										SET @LoopStockBal = 0

									IF NOT (@LoopStockBal >= @LoopPartBOMQty)
									BEGIN
										SET @Status = 2
										IF ISNULL(@PartsHavingLowQty,'') = ''
										BEGIN
											SET @PartsHavingLowQty = @MandatoryPartNo
										END
										ELSE
											SET @PartsHavingLowQty = @PartsHavingLowQty + ',' + @MandatoryPartNo
									END
								END
							END
							-- On Final Viewing Pass
							IF @Status IN (0,3)
							BEGIN
								DECLARE @RunningBalancePercentage DECIMAL(10,2) = 0.0
								SELECT
									--@RunningBalancePercentage = CONVERT(DECIMAL(10,2),
									--Case CONVERT(FLOAT(3),SUM(ISNULL(CONSUMED_QTY,0))) WHEN 0 THEN '0' ELSE CONVERT(FLOAT(3),(CONVERT(FLOAT,SUM(ISNULL(CONSUMED_QTY,0)))/CONVERT(FLOAT(3),SUM(ISNULL(FED_Qty,0))))*100)END)
									@RunningBalancePercentage =  (CONVERT(DECIMAL(10,2),SUM(Balance_Qty)) * 100) / CONVERT(DECIMAL(10,2),SUM(Fed_Qty))
										FROM Assy_LineMaterialStockStatus WITH (NOLOCK)
											WHERE WH_Code = @ProfitCenterCode AND Line_Code = @LineCode AND RM_Part_No = @MandatoryPartNo AND ISNULL(STS_CD,0) = 0
								
								IF ISNULL(@RunningBalancePercentage,0) = 0
									SET @RunningBalancePercentage = 0
								
								SET @RunningBalancePercentage = 100 - @RunningBalancePercentage

								IF (@RunningBalancePercentage
										>=
									ISNULL((SELECT CONVERT(DECIMAL(10,2),PARAMETER_VALUE) FROM PARAMETER_MST WITH (NOLOCK) WHERE PARAMETER_C1 = 'Material_Feeding'
										AND WH_Code = @ProfitCenterCode	AND PARAMETER_C2 = 'Mat_Feed_Percentage'),80))
								BEGIN
									SET @Status = 3

									IF ISNULL(@FedPartsRunningLowQty,'') = ''
									BEGIN
										SET @FedPartsRunningLowQty = @MandatoryPartNo + '(' + CONVERT(VARCHAR(10),@RunningBalancePercentage) + ' % consumed)'
									END
									ELSE
										SET @FedPartsRunningLowQty = @FedPartsRunningLowQty + ',' + @MandatoryPartNo + '(' + CONVERT(VARCHAR(10),@RunningBalancePercentage) + ' % consumed)'
								END
							END
						END
					END

					IF NOT EXISTS(SELECT 1 FROM Product_Master WITH (NOLOCK) WHERE warehouse_cd = @ProfitCenterCode
						AND SEWS_PART_NO =  (SELECT Top 1 RM_Part_No FROM @Bom_Explosion WHERE AutoID = @LoopStart) AND ISNULL(PART_TRACE_FLAG,0) = 1)
					BEGIN
						SET @Child_Part_Count = @Child_Part_Count + 1
					END

					SET @LoopStart = @LoopStart + 1
				END
				
				IF @Status = 1 AND ISNULL(@PartsNotExistsInStockTable,'') <> ''
				BEGIN
					SET @Remarks = ''
					SET @Remarks = 'Mandatory Child Part(s) - ' + @PartsNotExistsInStockTable + ' stock is not exists in Line Material Stock. Feed Material'
				END

				IF @Status = 2 AND ISNULL(@PartsHavingLowQty,'') <> ''
				BEGIN
					SET @Remarks = ''
					SET @Remarks = 'Qty is not sufficient for the Child Part(s) - ' + @PartsHavingLowQty + '. Feed Material'
				END

				-- On Final Viewing Pass
				IF @Status = 3 AND ISNULL(@FedPartsRunningLowQty,'') <> ''
				BEGIN
					SET @Remarks = ''
					SET @Remarks = 'Some Child Part(s) - ' + @FedPartsRunningLowQty + ' running low Qty. Feed Material'
				
				END
			
				IF (@Remarks = '')
					SET @Remarks = 'OK'

				IF NOT EXISTS (SELECT 1 FROM Assy_LineMatFeedRemarkStatus WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode)
				BEGIN
					INSERT INTO Assy_LineMatFeedRemarkStatus
						(	ProfitCenterCode, LineCode, PartNo, Remarks, [Timestamp], UserID, IsActive)
					SELECT	@ProfitCenterCode, @LineCode, @PartNumber, @Remarks, GETDATE(), @UserId, 1
				END
				ELSE
				BEGIN
					UPDATE Assy_LineMatFeedRemarkStatus
						SET PartNo = @PartNumber, Remarks = @Remarks,
							[Timestamp] = GETDATE(), UserID = @UserId, IsActive = 1
								WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
				END
				SET @ReturnInt = 1
				SET @ReturnValue = @Remarks
			END
			ELSE
			BEGIN
				SET @ReturnInt = 1
				SET @ReturnValue = 'Mat_Feed_Validaion_is_Off'
			END
			COMMIT TRAN
			RETURN
		END

		ELSE IF @Condition = 'MAT_FEED_STOCK_DEDUCTION_OLD'
		BEGIN
		
			DELETE FROM @Bom_Explosion

			INSERT INTO @Bom_Explosion(FG_Part_No, BOM_Part_No, RM_Part_No, BOM_Qty, BOM_Unit, MAT_Procure_Type, MAT_Use_Ration, Alt_Item_grp_Code)
			EXEC Proc_BOM_Explosion @ProfitCenterCode,@PartNumber,'','1','SUMMARY'
			
			SET @LoopEnd = 0
			SELECT @LoopEnd = COUNT(*) FROM @Bom_Explosion

			WHILE (@LoopStart <= @LoopEnd)
			BEGIN
				SET @MandatoryPartNo = ''
				SELECT @MandatoryPartNo = LTRIM(RTRIM(ISNULL(SEWS_PART_NO,''))) FROM Product_Master WITH (NOLOCK) WHERE warehouse_cd = @ProfitCenterCode
					AND SEWS_PART_NO =  (SELECT Top 1 RM_Part_No FROM @Bom_Explosion WHERE AutoID = @LoopStart) --AND ISNULL(PART_TRACE_FLAG,0) = 1
	
				IF ISNULL(@MandatoryPartNo,'') <> ''
				BEGIN
					UPDATE @Bom_Explosion
						SET IsMandatory = 1
							WHERE RM_Part_No = @MandatoryPartNo
	
					IF EXISTS (SELECT 1 FROM @Bom_Explosion WHERE IsMandatory = 1 AND RM_Part_No = @MandatoryPartNo AND BOM_Qty > 0)
					BEGIN
						IF EXISTS (SELECT 1 FROM Assy_LineMaterialStockStatus WITH (NOLOCK)
								WHERE WH_Code = @ProfitCenterCode AND Line_Code = @LineCode AND RM_Part_No = @MandatoryPartNo AND ISNULL(STS_CD,0) = 0)
						BEGIN
							IF ((SELECT SUM(ISNULL(BALANCE_QTY,0)) FROM Assy_LineMaterialStockStatus WITH (NOLOCK)
									WHERE WH_Code = @ProfitCenterCode AND Line_Code = @LineCode AND RM_Part_No = @MandatoryPartNo AND ISNULL(STS_CD,0) = 0)
									>= 
								(SELECT Top 1 ISNULL(BOM_Qty,0) FROM @Bom_Explosion WHERE IsMandatory = 1 AND RM_Part_No = @MandatoryPartNo AND BOM_Qty > 0))
							BEGIN
								DECLARE @StockChildPartNo VARCHAR(20) = '', @Child_Part_StockQty INT = 0, @Min_Mat_Feed_Id INT = 0, @Mat_SerialNo VARCHAR(20) = '',
										@StockFGPartNo VARCHAR(20) = '', @Min_Mat_Feed_BalanceQty INT = 0
								
								SELECT @StockFGPartNo = FG_Part_No, @StockChildPartNo = RM_Part_No, @Child_Part_StockQty = BOM_Qty FROM @Bom_Explosion
									WHERE IsMandatory = 1 AND RM_Part_No = @MandatoryPartNo AND BOM_Qty > 0
								
								SELECT @Min_Mat_Feed_Id = MIN(Mat_Feed_ID) FROM Assy_LineMaterialStockStatus WITH (NOLOCK)
									WHERE	WH_Code = @ProfitCenterCode AND Line_Code = @LineCode AND RM_Part_No = @MandatoryPartNo
											AND ISNULL(STS_CD,0) = 0 AND ISNULL(BALANCE_QTY,0) > 0
								
								SELECT @Mat_SerialNo = Serial_No, @Min_Mat_Feed_BalanceQty = ISNULL(BALANCE_QTY,0)
									FROM Assy_LineMaterialStockStatus WITH (NOLOCK)
										WHERE WH_Code = @ProfitCenterCode AND Line_Code = @LineCode AND RM_Part_No = @MandatoryPartNo
											AND ISNULL(STS_CD,0) = 0 AND ISNULL(BALANCE_QTY,0) > 0 AND Mat_Feed_ID = @Min_Mat_Feed_Id
								
								IF (@Min_Mat_Feed_Id > 0 AND @Child_Part_StockQty > 0)
								BEGIN
									IF (@Min_Mat_Feed_BalanceQty < @Child_Part_StockQty)
									BEGIN
										Declare @Loop_Low_Qty INT = 0
										SET @Loop_Low_Qty = @Min_Mat_Feed_BalanceQty
										
										WHILE(@Loop_Low_Qty > 0)
										BEGIN
											INSERT INTO Assy_FGChildPartConsumption(WH_Code,Line_Code,FG_PART_NO,FG_BARCODE,Mat_Feed_ID,RM_Part_No,RM_SERIAL_NO,
														CONSUMED_QTY,PROD_CONFIRM_STS,ENT_STAMP,ENT_BY,LAST_UPD_STAMP,LAST_UPD_BY,IsActive)
									
											SELECT @ProfitCenterCode, @LineCode, @StockFGPartNo, @Barcode , @Min_Mat_Feed_Id, @StockChildPartNo, @Mat_SerialNo,
													1 StockQty, 0, GETDATE(), @UserId, GETDATE(), @UserId, Case @IsProdConfRequired WHEN 0 THEN 1 WHEN 1 THEN 2 END
										
											SET @Loop_Low_Qty = @Loop_Low_Qty - 1
										END

										UPDATE Assy_LineMaterialStockStatus SET CONSUMED_QTY = CONSUMED_QTY + @Min_Mat_Feed_BalanceQty,
																			LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId, IsActive = 1
											WHERE WH_Code = @ProfitCenterCode AND Line_Code = @LineCode AND RM_Part_No = @MandatoryPartNo
												AND ISNULL(STS_CD,0) = 0 AND Mat_Feed_ID = @Min_Mat_Feed_Id
										
										IF (@IsProdConfRequired IN (0,1))
										BEGIN
											-- Variable Changed By Rashid On 20170601
											SELECT @Item_No =  dbo.FN_GET_ITEM_NO(@MandatoryPartNo,@ProfitCenterCode)
											INSERT INTO [dbo].[TRANS_LOG]
										   ([Serial_No],[FROM_CD],[TO_CD],[ORDER_NO],[DELV_BOL_NO],[ITEM_NO],[SERIAL_QTY],[WH_Code],[ENT_STAMP],[ENT_BY]
												  ,[PALLET_NO],[INPFLNAME_ID],[PROGRAM_ID],[TRAN_TYPE],[TR_TRNBR],[pallet_phy_id])
												  VALUES(@Mat_SerialNo,'','','',@Barcode,@Item_No,@Min_Mat_Feed_BalanceQty,@ProfitCenterCode,GETDATE(),
												  @UserId,'',NULL,'MAT_FEEDING_BITS',NULL,NULL, '')
											
											SELECT @Mat_SerialNo = Serial_No FROM Assy_LineMaterialStockStatus WITH (NOLOCK) WHERE Mat_Feed_ID = @Min_Mat_Feed_Id
											
											UPDATE INV_SERIAL SET SERIAL_QTY = SERIAL_QTY - @Min_Mat_Feed_BalanceQty, LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId
												WHERE WH_Code = @ProfitCenterCode AND SEWS_PART_NO = @MandatoryPartNo
													AND Serial_No = @Mat_SerialNo

											UPDATE Assy_LineMaterialStockStatus SET IsActive = 0, LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId
												WHERE Mat_Feed_ID = @Min_Mat_Feed_Id AND IsActive = 1
											
											UPDATE Assy_FGChildPartConsumption SET IsActive = 0, LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId
												 WHERE Mat_Feed_ID = @Min_Mat_Feed_Id AND IsActive = 1
											
											IF EXISTS (SELECT 1 FROM Assy_LineMaterialStockStatus WITH (NOLOCK) WHERE WH_Code = @ProfitCenterCode
												AND Line_Code = @LineCode AND RM_Part_No = @MandatoryPartNo AND ISNULL(BALANCE_QTY,0) = 0)
											BEGIN
												UPDATE Assy_LineMaterialStockStatus SET STS_CD = 100, LAST_UPD_BY = @UserId, LAST_UPD_STAMP = GETDATE()
													WHERE WH_Code = @ProfitCenterCode AND Line_Code = @LineCode
														AND RM_Part_No = @MandatoryPartNo AND ISNULL(BALANCE_QTY,0) = 0
											END
										END
										
										SELECT @Min_Mat_Feed_Id = MIN(Mat_Feed_ID) FROM Assy_LineMaterialStockStatus WITH (NOLOCK)
											WHERE	WH_Code = @ProfitCenterCode AND Line_Code = @LineCode AND RM_Part_No = @MandatoryPartNo
												AND ISNULL(STS_CD,0) = 0 AND ISNULL(BALANCE_QTY,0) > 0

										SET @Loop_Low_Qty = @Child_Part_StockQty - @Min_Mat_Feed_BalanceQty
										
										SELECT @Mat_SerialNo = Serial_No FROM Assy_LineMaterialStockStatus WITH (NOLOCK) WHERE Mat_Feed_ID = @Min_Mat_Feed_Id

										WHILE(@Loop_Low_Qty > 0)
										BEGIN
											INSERT INTO Assy_FGChildPartConsumption(WH_Code,Line_Code,FG_PART_NO,FG_BARCODE,Mat_Feed_ID,RM_Part_No,RM_SERIAL_NO,
														CONSUMED_QTY,PROD_CONFIRM_STS,ENT_STAMP,ENT_BY,LAST_UPD_STAMP,LAST_UPD_BY,IsActive)
									
											SELECT @ProfitCenterCode, @LineCode, @StockFGPartNo, @Barcode , @Min_Mat_Feed_Id, @StockChildPartNo, @Mat_SerialNo,
													1 StockQty, 0, GETDATE(), @UserId, GETDATE(), @UserId, Case @IsProdConfRequired WHEN 0 THEN 1 WHEN 1 THEN 2 END
										
											SET @Loop_Low_Qty = @Loop_Low_Qty - 1
										END

										UPDATE Assy_LineMaterialStockStatus SET CONSUMED_QTY = CONSUMED_QTY + (@Child_Part_StockQty - @Min_Mat_Feed_BalanceQty),
												LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId, IsActive = 1
											WHERE WH_Code = @ProfitCenterCode AND Line_Code = @LineCode AND RM_Part_No = @MandatoryPartNo
												AND ISNULL(STS_CD,0) = 0 AND Mat_Feed_ID = @Min_Mat_Feed_Id
										
										IF (@IsProdConfRequired IN (0,1))
										BEGIN
											-- Variable Changed By Rashid On 20170601
											SELECT @Item_No =  dbo.FN_GET_ITEM_NO(@MandatoryPartNo,@ProfitCenterCode)
											INSERT INTO [dbo].[TRANS_LOG]
										   ([Serial_No],[FROM_CD],[TO_CD],[ORDER_NO],[DELV_BOL_NO],[ITEM_NO],[SERIAL_QTY],[WH_Code],[ENT_STAMP],[ENT_BY]
												  ,[PALLET_NO],[INPFLNAME_ID],[PROGRAM_ID],[TRAN_TYPE],[TR_TRNBR],[pallet_phy_id])
												   VALUES(@Mat_SerialNo,'','','',@Barcode,@Item_No,(@Child_Part_StockQty - @Min_Mat_Feed_BalanceQty),@ProfitCenterCode,GETDATE(),
												  @UserId,'',NULL,'MAT_FEEDING_BITS',NULL,NULL, '')
											
											UPDATE INV_SERIAL SET SERIAL_QTY = SERIAL_QTY - (@Child_Part_StockQty - @Min_Mat_Feed_BalanceQty), LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId
												WHERE WH_Code = @ProfitCenterCode AND SEWS_PART_NO = @MandatoryPartNo
													AND Serial_No = @Mat_SerialNo

											UPDATE Assy_LineMaterialStockStatus SET IsActive = 0, LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId
												WHERE Mat_Feed_ID = @Min_Mat_Feed_Id AND IsActive = 1
											
											UPDATE Assy_FGChildPartConsumption SET IsActive = 0, LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId
												WHERE Mat_Feed_ID = @Min_Mat_Feed_Id AND IsActive = 1

											IF EXISTS (SELECT 1 FROM Assy_LineMaterialStockStatus WITH (NOLOCK) WHERE WH_Code = @ProfitCenterCode
												AND Line_Code = @LineCode AND RM_Part_No = @MandatoryPartNo AND ISNULL(BALANCE_QTY,0) = 0)
											BEGIN
												UPDATE Assy_LineMaterialStockStatus SET STS_CD = 100, LAST_UPD_BY = @UserId, LAST_UPD_STAMP = GETDATE()
													WHERE WH_Code = @ProfitCenterCode AND Line_Code = @LineCode
														AND RM_Part_No = @MandatoryPartNo AND ISNULL(BALANCE_QTY,0) = 0
											END
										END
									END
									ELSE
									BEGIN
										Declare @Loop_Ok_Qty INT = 0
										SET @Loop_Ok_Qty = @Child_Part_StockQty
										WHILE(@Loop_Ok_Qty > 0)
										BEGIN
											INSERT INTO Assy_FGChildPartConsumption(WH_Code,Line_Code,FG_PART_NO,FG_BARCODE,Mat_Feed_ID,RM_Part_No,RM_SERIAL_NO,
														CONSUMED_QTY,PROD_CONFIRM_STS,ENT_STAMP,ENT_BY,LAST_UPD_STAMP,LAST_UPD_BY,IsActive)
									
											SELECT @ProfitCenterCode, @LineCode, @StockFGPartNo, @Barcode , @Min_Mat_Feed_Id, @StockChildPartNo, @Mat_SerialNo,
													1 StockQty, 0, GETDATE(), @UserId, GETDATE(), @UserId, Case @IsProdConfRequired WHEN 0 THEN 1 WHEN 1 THEN 2 END
										
											SET @Loop_Ok_Qty = @Loop_Ok_Qty - 1
										END

										UPDATE Assy_LineMaterialStockStatus SET CONSUMED_QTY = CONSUMED_QTY + @Child_Part_StockQty,
											LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId, IsActive = 1
											WHERE WH_Code = @ProfitCenterCode AND Line_Code = @LineCode AND RM_Part_No = @MandatoryPartNo
												AND ISNULL(STS_CD,0) = 0 AND Mat_Feed_ID = @Min_Mat_Feed_Id

										IF (@IsProdConfRequired IN (0,1))
										BEGIN
											-- Variable Changed By Rashid On 20170601
											SELECT @Item_No =  dbo.FN_GET_ITEM_NO(@MandatoryPartNo,@ProfitCenterCode)
											INSERT INTO [dbo].[TRANS_LOG]
										   ([Serial_No],[FROM_CD],[TO_CD],[ORDER_NO],[DELV_BOL_NO],[ITEM_NO],[SERIAL_QTY],[WH_Code],[ENT_STAMP],[ENT_BY]
												  ,[PALLET_NO],[INPFLNAME_ID],[PROGRAM_ID],[TRAN_TYPE],[TR_TRNBR],[pallet_phy_id])
												 VALUES(@Mat_SerialNo,'','','',@Barcode,@Item_No,@Child_Part_StockQty,@ProfitCenterCode,GETDATE(),
												  @UserId,'',NULL,'MAT_FEEDING_BITS',NULL,NULL, '')
											
											SELECT @Mat_SerialNo = Serial_No FROM Assy_LineMaterialStockStatus WITH (NOLOCK) WHERE Mat_Feed_ID = @Min_Mat_Feed_Id

											UPDATE INV_SERIAL SET SERIAL_QTY = SERIAL_QTY - @Child_Part_StockQty, LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId
												WHERE WH_Code = @ProfitCenterCode AND SEWS_PART_NO = @MandatoryPartNo
													AND Serial_No = @Mat_SerialNo
											
											UPDATE Assy_LineMaterialStockStatus SET IsActive = 0, LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId
												WHERE Mat_Feed_ID = @Min_Mat_Feed_Id AND IsActive = 1
											
											UPDATE Assy_FGChildPartConsumption SET IsActive = 0, LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId
												WHERE Mat_Feed_ID = @Min_Mat_Feed_Id AND IsActive = 1

											IF EXISTS (SELECT 1 FROM Assy_LineMaterialStockStatus WITH (NOLOCK) WHERE WH_Code = @ProfitCenterCode
												AND Line_Code = @LineCode AND RM_Part_No = @MandatoryPartNo AND ISNULL(BALANCE_QTY,0) = 0)
											BEGIN
												UPDATE Assy_LineMaterialStockStatus SET STS_CD = 100, LAST_UPD_BY = @UserId, LAST_UPD_STAMP = GETDATE()
													WHERE WH_Code = @ProfitCenterCode AND Line_Code = @LineCode
														AND RM_Part_No = @MandatoryPartNo AND ISNULL(BALANCE_QTY,0) = 0
											END
										END
									END
								END
							END
						END
					END
				END
				SET @LoopStart = @LoopStart + 1
			END
			
			SET @ReturnInt = 1
			SET @ReturnValue = 'SUCCESS'
			COMMIT TRAN
			RETURN
		END

		ELSE IF @Condition = 'MAT_FEED_STOCK_DEDUCTION'
		BEGIN
			DELETE FROM @Bom_Explosion

			INSERT INTO @Bom_Explosion(FG_Part_No, BOM_Part_No, RM_Part_No, BOM_Qty, BOM_Unit, MAT_Procure_Type, MAT_Use_Ration, Alt_Item_grp_Code)
			EXEC Proc_BOM_Explosion @ProfitCenterCode,@PartNumber,'','1','SUMMARY'
			
			DELETE FROM @Bom_Explosion WHERE RM_Part_No NOT IN (
			SELECT B.RM_Part_No FROM @Bom_Explosion B
			JOIN Assy_LineMaterialStockStatus S (NOLOCK)
				ON B.RM_Part_No = S.RM_Part_No AND S.WH_Code = @ProfitCenterCode
					WHERE S.Wh_Code = @ProfitCenterCode AND S.Line_Code = @LineCode AND Balance_Qty > 0 AND B.BOM_Qty > 0 AND ISNULL(STS_CD,0) = 0)
			
			;WITH DuplicateRecordsTable
			As
			(
				SELECT ROW_NUMBER() OVER (PARTITION BY RM_Part_No Order BY RM_Part_No) As DuplicateRecordsFilter FROM @Bom_Explosion
			)
			DELETE FROM DuplicateRecordsTable WHERE DuplicateRecordsFilter > 1

			IF OBJECT_ID('Tempdb..#Temp_Bom_Explosion') IS NOT NULL
				DROP TABLE #Temp_Bom_Explosion
			
			SELECT AutoID = IDENTITY (int, 1,1), FG_Part_No, BOM_Part_No, RM_Part_No, BOM_Qty, BOM_Unit, MAT_Procure_Type, MAT_Use_Ration, Alt_Item_grp_Code 
			INTO #Temp_Bom_Explosion 
			FROM @Bom_Explosion
			
			--SELECT * FROM #Temp_Bom_Explosion

			IF OBJECT_ID('Tempdb..#CTE') IS NOT NULL
				DROP TABLE #CTE

			;WITH CTE As
			(
				SELECT S.Mat_Feed_ID, T.RM_Part_No TRM_Part_No, T.BOM_Qty, S.RM_Part_No, S.Serial_No, S.Balance_Qty,
				ROW_NUMBER() OVER (PARTITION BY S.RM_Part_No ORDER BY S.Mat_Feed_ID) As RowNo
				FROM #Temp_Bom_Explosion T INNER JOIN
				Assy_LineMaterialStockStatus S 
				ON T.RM_Part_No = S.RM_Part_No AND S.WH_Code = @ProfitCenterCode
				INNER JOIN INV_SERIAL (NOLOCK) I ON I.SERIAL_NO = S.Serial_No
				WHERE S.Line_Code = @LineCode AND S.Balance_Qty > 0 AND ISNULL(S.STS_CD,0) = 0 AND I.SERIAL_QTY > 0
			)
			SELECT * INTO #CTE FROM CTE --WHERE RowNo = 1

			IF OBJECT_ID('Tempdb..#FINAL_DATA') IS NOT NULL
				DROP TABLE #FINAL_DATA
			
			IF OBJECT_ID('Tempdb..#REQ_DATA') IS NOT NULL
				DROP TABLE #REQ_DATA

			--SELECT * FROM #CTE
			
			SELECT Mat_Feed_ID,TRM_Part_No,BOM_Qty,RM_Part_No,Serial_No,Balance_Qty,
					CASE WHEN BOM_Qty >= Balance_Qty THEN Balance_Qty 
					      WHEN BOM_Qty < Balance_Qty  THEN BOM_Qty END As CONSUMED_QTY,RowNo
			INTO #FINAL_DATA 
			FROM #CTE WHERE RowNo = 1
			
			SELECT * INTO #REQ_DATA FROM #CTE WHERE BOM_Qty > Balance_Qty AND RowNo = 1
			--SELECT * FROM #REQ_DATA

			UPDATE #REQ_DATA
				SET BOM_Qty = BOM_Qty - Balance_Qty

			Declare @RowNo INT = 2

			WHILE EXISTS(SELECT C.* FROM #REQ_DATA R INNER JOIN #CTE C ON R.RM_Part_No = C.RM_Part_No WHERE C.RowNo = @RowNo AND R.BOM_Qty > 0 )
			BEGIN
			 IF EXISTS(SELECT 1 FROM #REQ_DATA R INNER JOIN #CTE C ON R.RM_Part_No = C.RM_Part_No WHERE C.RowNo = @RowNo)
				BEGIN
					INSERT INTO #FINAL_DATA(Mat_Feed_ID,TRM_Part_No,BOM_Qty,RM_Part_No,Serial_No,Balance_Qty,CONSUMED_QTY,RowNo)
					SELECT  C.Mat_Feed_ID,C.TRM_Part_No,C.BOM_Qty,C.RM_Part_No,C.Serial_No,C.Balance_Qty,
							CASE WHEN R.BOM_Qty>=C.Balance_Qty THEN C.Balance_Qty 
							WHEN R.BOM_Qty<C.Balance_Qty  THEN R.BOM_Qty END As CONSUMED_QTY,
					C.RowNo
					FROM #REQ_DATA R INNER JOIN #CTE C ON R.RM_Part_No =C.RM_Part_No 
					WHERE C.RowNo=@RowNo

					UPDATE  R  
					SET R.BOM_Qty = CASE WHEN R.BOM_Qty - C.Balance_Qty >= 0 THEN R.BOM_Qty - C.Balance_Qty
					ELSE 0 END
					FROM  #REQ_DATA R
					INNER JOIN #CTE C ON R.RM_Part_No = C.RM_Part_No WHERE C.RowNo = @RowNo
				END
				SET @RowNo = @RowNo + 1
			END
			
			INSERT INTO Assy_FGChildPartConsumption(WH_Code,Line_Code,FG_PART_NO,FG_BARCODE,Mat_Feed_ID,RM_Part_No,RM_SERIAL_NO,
													CONSUMED_QTY,PROD_CONFIRM_STS,ENT_STAMP,ENT_BY,LAST_UPD_STAMP,LAST_UPD_BY,IsActive)
			SELECT @ProfitCenterCode, @LineCode, @PartNumber, @Barcode ,Mat_Feed_ID, RM_Part_No, Serial_No,
					CONSUMED_QTY, 0, GETDATE(), @UserId, GETDATE(), @UserId,CASE @IsProdConfRequired WHEN 0 THEN 1 WHEN 1 THEN 2 END
			FROM #FINAL_DATA F
										
			UPDATE  ALMSS
			SET ALMSS.CONSUMED_QTY = ALMSS.CONSUMED_QTY + F.CONSUMED_QTY,
			LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId, IsActive = 1,
			ALMSS.STS_CD=CASE WHEN ALMSS.Balance_Qty = F.CONSUMED_QTY THEN 100
							ELSE ALMSS.STS_CD
							END 
			FROM Assy_LineMaterialStockStatus ALMSS
			INNER JOIN #FINAL_DATA F ON ALMSS.Mat_Feed_ID=F.Mat_Feed_ID AND ALMSS.RM_Part_No = F.RM_Part_No AND ALMSS.Serial_No=F.Serial_No
			WHERE ALMSS.WH_Code = @ProfitCenterCode AND ALMSS.Line_Code = @LineCode 
			AND ISNULL(STS_CD,0) = 0
			
			IF (@@ROWCOUNT > 0)
			BEGIN
				UPDATE  I  
					SET I.SERIAL_QTY = I.SERIAL_QTY - F.CONSUMED_QTY,
					LAST_UPD_STAMP = GETDATE(),
					LAST_UPD_BY = @UserId,
					I.STS_CD = CASE WHEN I.SERIAL_QTY = F.CONSUMED_QTY THEN 100
									ELSE I.STS_CD
									END
					FROM INV_SERIAL I
					INNER JOIN #FINAL_DATA F ON I.SERIAL_NO=F.Serial_No  AND I.SEWS_PART_NO=F.RM_Part_No
					WHERE WH_Code = @ProfitCenterCode AND I.SERIAL_QTY > 0
									
					SELECT @Item_No =  dbo.FN_GET_ITEM_NO(@MandatoryPartNo,@ProfitCenterCode)
					INSERT INTO [dbo].[TRANS_LOG]
					([Serial_No],[FROM_CD],[TO_CD],[ORDER_NO],[DELV_BOL_NO],[ITEM_NO],[SERIAL_QTY],[WH_Code],[ENT_STAMP],[ENT_BY]
							,[PALLET_NO],[INPFLNAME_ID],[PROGRAM_ID],[TRAN_TYPE],[TR_TRNBR],[pallet_phy_id])
					SELECT I.Serial_No,'','','',@Barcode,I.ITEM_NO,I.SERIAL_QTY,I.WH_CODE,GETDATE(),
							@UserId,'',NULL,'MAT_FEEDING_BITS',NULL,NULL, ''
					FROM INV_SERIAL(NOLOCK) I 
					INNER JOIN #FINAL_DATA F ON I.SERIAL_NO = F.Serial_No AND I.SEWS_PART_NO = F.RM_Part_No
					WHERE I.WH_Code = @ProfitCenterCode
			END	 
			SET @ReturnInt = 1
			SET @ReturnValue = 'SUCCESS'
			COMMIT TRAN
			RETURN
		END

		ELSE IF @Condition = 'ENABLE_DISABLE_MAT_FEED_VALIDATION'
		BEGIN
			IF(@EnableDisableMatFeedValidation IN (0,1))
			BEGIN
				UPDATE LineMst SET IsMatFeedRequired = @EnableDisableMatFeedValidation WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			END
			
			SELECT  ISNULL(IsMatFeedRequired,0) IsMatFeedRequired FROM LineMst (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			COMMIT TRAN
			RETURN
		END

		ELSE IF @Condition = 'GET_STOCK_STATUS'
		BEGIN
			IF ISNULL(@PartNumber,'') != ''
			BEGIN
				
				DELETE FROM @Bom_Explosion

				INSERT INTO @Bom_Explosion(FG_Part_No, BOM_Part_No, RM_Part_No, BOM_Qty, BOM_Unit, MAT_Procure_Type, MAT_Use_Ration, Alt_Item_grp_Code)
				EXEC Proc_BOM_Explosion @ProfitCenterCode,@PartNumber,'','1','SUMMARY'

				Update B SET B.IsMandatory = ISNULL(P.PART_TRACE_FLAG,0) FROM @Bom_Explosion B
							INNER JOIN Product_Master P
								ON P.SEWS_PART_NO = B.RM_Part_No AND P.warehouse_cd = @ProfitCenterCode
									WHERE P.warehouse_cd = @ProfitCenterCode
				
				/* Loop Removed By Rashid On 20170601
				SET @LoopEnd = 0
				SELECT @LoopEnd = COUNT(*) FROM @Bom_Explosion

				WHILE (@LoopStart <= @LoopEnd)
				BEGIN
					SET @MandatoryPartNo = ''
					SELECT @MandatoryPartNo = LTRIM(RTRIM(ISNULL(SEWS_PART_NO,''))) FROM Product_Master WITH (NOLOCK) WHERE warehouse_cd = @ProfitCenterCode
						AND SEWS_PART_NO =  (SELECT Top 1 RM_Part_No FROM @Bom_Explosion WHERE AutoID = @LoopStart) AND ISNULL(PART_TRACE_FLAG,0) = 1
					--PRINT @MandatoryPartNo
					
					IF ISNULL(@MandatoryPartNo,'') <> ''
					BEGIN
						UPDATE @Bom_Explosion
							SET IsMandatory = 1
								WHERE RM_Part_No = @MandatoryPartNo
					END
					SET @LoopStart = @LoopStart + 1
				END
				*/
				--SELECT * FROM @Bom_Explosion WHERE ISNULL(IsMandatory,0) = 1
				-- Non Common Parts Stock
				SELECT	0 ChkSelect, Mat_Feed_ID, Serial_No, RM_Part_No PartNo, ISNULL(LTRIM(RTRIM(PM.product_nm)),'') PartDescr, FED_Qty PacketQty, FED_Qty FeedQty, ISNULL(BALANCE_QTY,0) Qty, ISNULL(BALANCE_QTY,0) FlushQty
							FROM Assy_LineMaterialStockStatus ALMS WITH (NOLOCK) 
					INNER JOIN PRODUCT_MASTER PM WITH (NOLOCK) 
						ON ALMS.WH_Code = PM.warehouse_cd AND ALMS.RM_Part_No = PM.SEWS_PART_NO
								WHERE Line_Code = @LineCode AND WH_Code = @ProfitCenterCode AND (ISNULL(BALANCE_QTY,0) > 0 ) AND ISNULL(ALMS.STS_CD,0) != 100
									--AND RM_Part_No NOT IN (SELECT Distinct RM_Part_No FROM @Bom_Explosion WHERE ISNULL(IsMandatory,0) = 1)
									AND RM_Part_No NOT IN (SELECT Distinct RM_Part_No FROM @Bom_Explosion)
										Order By 4,5
				-- Common Parts Stock
				SELECT	0 ChkSelect, Mat_Feed_ID, Serial_No, RM_Part_No PartNo, ISNULL(LTRIM(RTRIM(PM.product_nm)),'') PartDescr, FED_Qty PacketQty, FED_Qty FeedQty, ISNULL(BALANCE_QTY,0) Qty, ISNULL(BALANCE_QTY,0) FlushQty
							FROM Assy_LineMaterialStockStatus ALMS WITH (NOLOCK)
					INNER JOIN PRODUCT_MASTER PM WITH (NOLOCK) 
						ON ALMS.WH_Code = PM.warehouse_cd AND ALMS.RM_Part_No = PM.SEWS_PART_NO
								WHERE Line_Code = @LineCode AND WH_Code = @ProfitCenterCode AND (ISNULL(BALANCE_QTY,0) > 0 ) AND ISNULL(ALMS.STS_CD,0) != 100
									--AND RM_Part_No IN (SELECT Distinct RM_Part_No FROM @Bom_Explosion WHERE ISNULL(IsMandatory,0) = 1)
									AND RM_Part_No IN (SELECT Distinct RM_Part_No FROM @Bom_Explosion)
										Order By 4,5
				
				-- BOM Explode with Available Qty AND Traceable Parts Information
				SELECT FG_Part_No, B.RM_Part_No, BOM_Qty, Case ISNULL(IsMandatory,0) WHEN 1 THEN 'Y' ELSE 'N' END TracePart, ISNULL(ALMS.Qty,0) Qty --, ISNULL(ALMS.FlushQty,0) FlushQty
					FROM @Bom_Explosion B
						LEFT OUTER JOIN 
						(SELECT RM_Part_No, SUM(ISNULL(BALANCE_QTY,0)) Qty, SUM(ISNULL(FlushQty,0)) FlushQty FROM Assy_LineMaterialStockStatus WITH (NOLOCK)
							WHERE Line_Code = @LineCode AND WH_Code = @ProfitCenterCode AND (ISNULL(BALANCE_QTY,0) > 0 ) AND ISNULL(STS_CD,0) != 100
									Group By RM_Part_No
							) ALMS
							ON B.RM_Part_No = ALMS.RM_Part_No
								Order By 2
				-- Set Parameter Running Part
				SELECT @PartNumber PartNumber
			END
			ELSE
			BEGIN
				-- Non Common Parts Stock
				SELECT	0 ChkSelect, Mat_Feed_ID, Serial_No, RM_Part_No PartNo, ISNULL(LTRIM(RTRIM(PM.product_nm)),'') PartDescr, FED_Qty FeedQty, FED_Qty PacketQty, ISNULL(BALANCE_QTY,0) Qty, ISNULL(BALANCE_QTY,0) FlushQty
							FROM Assy_LineMaterialStockStatus  ALMS WITH (NOLOCK)
					INNER JOIN PRODUCT_MASTER PM WITH (NOLOCK) 
						ON ALMS.WH_Code = PM.warehouse_cd AND ALMS.RM_Part_No = PM.SEWS_PART_NO
								WHERE Line_Code = @LineCode AND WH_Code = @ProfitCenterCode AND ISNULL(BALANCE_QTY,0) > 0 AND ISNULL(ALMS.STS_CD,0) != 100
									Order By 4,5
			END

			COMMIT TRAN
			RETURN
		END

		ELSE IF @Condition = 'GET_ALERT_STOCK_STATUS'
		BEGIN
			IF ISNULL(@PartNumber,'') != ''
			BEGIN
				
				DELETE FROM @Bom_Explosion

				INSERT INTO @Bom_Explosion(FG_Part_No, BOM_Part_No, RM_Part_No, BOM_Qty, BOM_Unit, MAT_Procure_Type, MAT_Use_Ration, Alt_Item_grp_Code)
				EXEC Proc_BOM_Explosion @ProfitCenterCode,@PartNumber,'','1','SUMMARY'
				
				Update B SET B.IsMandatory = ISNULL(P.PART_TRACE_FLAG,0) FROM @Bom_Explosion B
							INNER JOIN Product_Master P
								ON P.SEWS_PART_NO = B.RM_Part_No AND P.warehouse_cd = @ProfitCenterCode
									WHERE P.warehouse_cd = @ProfitCenterCode
				
				/* Loop Removed By Rashid On 20170601
				SET @LoopEnd = 0
				SELECT @LoopEnd = COUNT(*) FROM @Bom_Explosion

				WHILE (@LoopStart <= @LoopEnd)
				BEGIN
					SET @MandatoryPartNo = ''
					SELECT @MandatoryPartNo = LTRIM(RTRIM(ISNULL(SEWS_PART_NO,''))) FROM Product_Master WITH (NOLOCK) WHERE warehouse_cd = @ProfitCenterCode
						AND SEWS_PART_NO =  (SELECT Top 1 RM_Part_No FROM @Bom_Explosion WHERE AutoID = @LoopStart) AND ISNULL(PART_TRACE_FLAG,0) = 1
					--PRINT @MandatoryPartNo
					
					IF ISNULL(@MandatoryPartNo,'') <> ''
					BEGIN
						UPDATE @Bom_Explosion
							SET IsMandatory = 1
								WHERE RM_Part_No = @MandatoryPartNo
					END
					SET @LoopStart = @LoopStart + 1
				END
				*/
				--SELECT * FROM @Bom_Explosion WHERE ISNULL(IsMandatory,0) = 1
				-- BOM Explode with Available Qty AND Traceable Parts Information
				SELECT FG_Part_No, B.RM_Part_No, ISNULL(LTRIM(RTRIM(PM.product_nm)),'') Descr, BOM_Qty, Case ISNULL(IsMandatory,0) WHEN 1 THEN 'Y' ELSE 'N' END TracePart, ISNULL(ALMS.Qty,0) Qty
					FROM @Bom_Explosion B
						LEFT OUTER JOIN 
						(SELECT RM_Part_No, SUM(ISNULL(BALANCE_QTY,0)) Qty, SUM(ISNULL(FlushQty,0)) FlushQty FROM Assy_LineMaterialStockStatus WITH (NOLOCK)
							WHERE Line_Code = @LineCode AND WH_Code = @ProfitCenterCode AND (ISNULL(BALANCE_QTY,0) > 0 ) AND ISNULL(STS_CD,0) != 100
									Group By RM_Part_No
							) ALMS
							ON B.RM_Part_No = ALMS.RM_Part_No
						INNER JOIN Product_Master PM WITH (NOLOCK)
							ON PM.SEWS_PART_NO = B.RM_Part_No AND PM.warehouse_cd = @ProfitCenterCode AND PM.STS_CD = 0
								Order By 2
			END
			ELSE
			BEGIN
				SELECT 'SET_PARAMETER_NOT_DONE'
			END
			COMMIT TRAN
			RETURN
		END

		ELSE IF @Condition = 'ALERT_STOCK_CONFIRM'
		BEGIN
			IF (LEN(@MatFeedIdString) > 0)
			BEGIN
				SELECT ROW_NUMBER() OVER(ORDER BY Data) Id,* INTO #Confirm_Mat_Feed_Id_List FROM dbo.SplitString(@MatFeedIdString,',')
				
				UPDATE A SET LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId
					FROM Assy_LineMaterialStockStatus A
						INNER JOIN #Confirm_Mat_Feed_Id_List C
							ON A.Mat_Feed_ID = C.Data
								WHERE A.Line_Code = @LineCode AND A.WH_Code = @ProfitCenterCode AND ISNULL(A.STS_CD,0) != 100
				/* Loop Removed By Rashid On 20170601
				SELECT @LoopEnd = COUNT(Id) FROM #Confirm_Mat_Feed_Id_List
				SET @LoopStart = 1
				
				IF (@LoopEnd > 0)
				BEGIN
					WHILE (@LoopStart <= @LoopEnd)
					BEGIN
						SET @MatFeed_Id = 0
						SELECT Top 1 @MatFeed_Id = Data FROM #Confirm_Mat_Feed_Id_List WHERE Id = @LoopStart
						
						IF @MatFeed_Id > 0
						BEGIN
							UPDATE Assy_LineMaterialStockStatus SET LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId
								WHERE Mat_Feed_ID = @MatFeed_Id AND Line_Code = @LineCode AND WH_Code = @ProfitCenterCode AND ISNULL(STS_CD,0) != 100
						END
						SET @LoopStart = @LoopStart + 1
					END
				END
				*/
			END
			SET @ReturnValue = 'Success'
			SET @ReturnInt = 1

			COMMIT TRAN
			RETURN
		END

		ELSE IF @Condition = 'ALERT_STOCK_ACKLATER'
		BEGIN
			IF (LEN(@MatFeedIdString) > 0)
			BEGIN
				SELECT ROW_NUMBER() OVER(ORDER BY Data) Id,* INTO #Mat_Feed_Id_List FROM dbo.SplitString(@MatFeedIdString,',')
				
				UPDATE A SET LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId
					FROM Assy_LineMaterialStockStatus A
						INNER JOIN #Mat_Feed_Id_List M
							ON A.Mat_Feed_ID = M.Data
								WHERE A.Line_Code = @LineCode AND A.WH_Code = @ProfitCenterCode AND ISNULL(A.STS_CD,0) != 100

				/* Loop Removed By Rashid On 20170601
				SELECT @LoopEnd = COUNT(Id) FROM #Mat_Feed_Id_List
				SET @LoopStart = 1
				
				IF (@LoopEnd > 0)
				BEGIN
					WHILE (@LoopStart <= @LoopEnd)
					BEGIN
						
						SET @MatFeed_Id = 0
						SELECT Top 1 @MatFeed_Id = Data FROM #Mat_Feed_Id_List WHERE Id = @LoopStart
						
						IF @MatFeed_Id > 0
						BEGIN
							UPDATE Assy_LineMaterialStockStatus SET LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId
								WHERE Mat_Feed_ID = @MatFeed_Id AND Line_Code = @LineCode AND WH_Code = @ProfitCenterCode AND ISNULL(STS_CD,0) != 100
						END
						SET @LoopStart = @LoopStart + 1
					END
				END
				*/
			END
		
			SET @ReturnValue = 'Success'
			SET @ReturnInt = 1
			COMMIT TRAN
			RETURN
		END

		ELSE IF @Condition = 'FLUSH_QTY'
		BEGIN
			IF (LEN(@MatFeedIdString) > 0)
			BEGIN
				SELECT ROW_NUMBER() OVER(ORDER BY MatFeedId) Id,* INTO #Mat_Feed_Serial_List FROM @MatFeedTable

				INSERT INTO Assy_LineMaterialStockStatus_FlushHistory (WH_Code,Line_Code,WorkCenterCode,Mat_Feed_ID,Serial_No,RM_Part_No,Fed_Qty,Consumed_Qty,Missed_Qty,FlushQty,Balance_Qty,Transfer_Qty,Consolidate_Qty,ProductionType,PacketTypeStatus,Remark,IsActive,IsLineSideStockConfirm,STS_CD,ENT_STAMP,ENT_BY,LAST_UPD_STAMP,LAST_UPD_BY,IsFVUserConfirm,HIS_ENT_STAMP,HIS_ENT_BY)
				SELECT WH_Code,Line_Code,WorkCenterCode,Mat_Feed_ID,Serial_No,RM_Part_No,Fed_Qty,Consumed_Qty,Missed_Qty,A.FlushQty,Balance_Qty,Transfer_Qty,Consolidate_Qty,ProductionType,PacketTypeStatus,Remark,IsActive,IsLineSideStockConfirm,STS_CD,ENT_STAMP,ENT_BY,LAST_UPD_STAMP,LAST_UPD_BY,IsFVUserConfirm,GETDATE(), @UserId HIS_ENT_BY
					FROM Assy_LineMaterialStockStatus A
						JOIN #Mat_Feed_Serial_List M
							ON A.Mat_Feed_ID = M.MatfeedID
								WHERE A.Line_Code = @LineCode AND A.WH_Code = @ProfitCenterCode

					UPDATE A SET A.FlushQty = M.FlushQty - A.Missed_Qty, A.Missed_Qty = A.Balance_Qty - M.FlushQty, Remark = @MsgRemark,
						IsFVUserConfirm = 1, LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId
							FROM Assy_LineMaterialStockStatus A
								JOIN #Mat_Feed_Serial_List M
									ON A.Mat_Feed_ID = M.MatfeedID
										WHERE A.Line_Code = @LineCode AND A.WH_Code = @ProfitCenterCode

				/* Loop Removed By Rashid On 20170601
				SELECT @LoopEnd = COUNT(Id) FROM #Mat_Feed_Serial_List
				SET @LoopStart = 1
				
				IF (@LoopEnd > 0)
				BEGIN
					WHILE (@LoopStart <= @LoopEnd)
					BEGIN
						SET @FlushQty = 0
						SET @MatFeed_Id = 0
						SET @sSerialNo = ''
						SET @AvailableQty = 0
						SET @MissngQty = 0

						SELECT Top 1 @MatFeed_Id = MatFeedId, @FlushQty = FlushQty FROM #Mat_Feed_Serial_List WHERE Id = @LoopStart
						SELECT Top 1 @sSerialNo = Serial_No, @AvailableQty = ISNULL(Balance_Qty,0) FROM Assy_LineMaterialStockStatus WITH (NOLOCK) WHERE Mat_Feed_ID = @MatFeed_Id

						IF ISNULL(@AvailableQty,0) != ISNULL(@FlushQty,0)
						BEGIN
							IF @AvailableQty > @FlushQty
							BEGIN
								SET @MissngQty = @AvailableQty - @FlushQty
							END
						END

						IF @sSerialNo != '' AND @FlushQty > 0
						BEGIN
							INSERT INTO Assy_LineMaterialStockStatus_FlushHistory (WH_Code,Line_Code,WorkCenterCode,Mat_Feed_ID,Serial_No,RM_Part_No,Fed_Qty,Consumed_Qty,Missed_Qty,FlushQty,Balance_Qty,Transfer_Qty,Consolidate_Qty,ProductionType,PacketTypeStatus,Remark,IsActive,IsLineSideStockConfirm,STS_CD,ENT_STAMP,ENT_BY,LAST_UPD_STAMP,LAST_UPD_BY,HIS_ENT_STAMP,HIS_ENT_BY)
							SELECT WH_Code,Line_Code,WorkCenterCode,Mat_Feed_ID,Serial_No,RM_Part_No,Fed_Qty,Consumed_Qty,Missed_Qty,FlushQty,Balance_Qty,Transfer_Qty,Consolidate_Qty,ProductionType,PacketTypeStatus,Remark,IsActive,IsLineSideStockConfirm,STS_CD,ENT_STAMP,ENT_BY,LAST_UPD_STAMP,LAST_UPD_BY,GETDATE(), @UserId HIS_ENT_BY
								FROM Assy_LineMaterialStockStatus WITH (NOLOCK) WHERE Mat_Feed_ID = @MatFeed_Id AND Serial_No = @sSerialNo AND Line_Code = @LineCode AND WH_Code = @ProfitCenterCode
									--AND ISNULL(STS_CD,0) != 100

							UPDATE Assy_LineMaterialStockStatus SET FlushQty = ISNULL(FlushQty,0) + @FlushQty, Missed_Qty = ISNULL(Missed_Qty,0) + @MissngQty,
								Remark = @MsgRemark, IsFVUserConfirm = 1, LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId
									WHERE Mat_Feed_ID = @MatFeed_Id AND Serial_No = @sSerialNo AND Line_Code = @LineCode AND WH_Code = @ProfitCenterCode
										--AND ISNULL(STS_CD,0) != 100
						END
						SET @LoopStart = @LoopStart + 1
					END
				END
				*/
			END

			SET @ReturnValue = 'Success'
			SET @ReturnInt = 1
			COMMIT TRAN
			RETURN
		END

		ELSE IF @Condition = 'GET_STOCK_STATUS_FOR_PRINT'
		BEGIN
			IF ISNULL(@IsMatFeedRequired,0) = 1
			BEGIN
				IF ISNULL(@PartNumber,'') != ''
				BEGIN
				
					DELETE FROM @Bom_Explosion

					INSERT INTO @Bom_Explosion(FG_Part_No, BOM_Part_No, RM_Part_No, BOM_Qty, BOM_Unit, MAT_Procure_Type, MAT_Use_Ration, Alt_Item_grp_Code)
					EXEC Proc_BOM_Explosion @ProfitCenterCode,@PartNumber,'','1','SUMMARY'

					Update B SET B.IsMandatory = ISNULL(P.PART_TRACE_FLAG,0) FROM @Bom_Explosion B
							INNER JOIN Product_Master P
								ON P.SEWS_PART_NO = B.RM_Part_No AND P.warehouse_cd = @ProfitCenterCode
									WHERE P.warehouse_cd = @ProfitCenterCode
					/* Loop Removed By Rashid On 20170601
					SET @LoopEnd = 0
					SELECT @LoopEnd = COUNT(*) FROM @Bom_Explosion

					WHILE (@LoopStart <= @LoopEnd)
					BEGIN
						SET @MandatoryPartNo = ''
						SELECT @MandatoryPartNo = LTRIM(RTRIM(ISNULL(SEWS_PART_NO,''))) FROM Product_Master WITH (NOLOCK) WHERE warehouse_cd = @ProfitCenterCode
							AND SEWS_PART_NO =  (SELECT Top 1 RM_Part_No FROM @Bom_Explosion WHERE AutoID = @LoopStart) AND ISNULL(PART_TRACE_FLAG,0) = 1
						--PRINT @MandatoryPartNo

						IF ISNULL(@MandatoryPartNo,'') <> ''
						BEGIN
							UPDATE @Bom_Explosion
								SET IsMandatory = 1
									WHERE RM_Part_No = @MandatoryPartNo
						END
						SET @LoopStart = @LoopStart + 1
					END
					*/
					--SELECT * FROM @Bom_Explosion WHERE ISNULL(IsMandatory,0) = 1
					-- BOM Explode with Available Qty AND Traceable Parts Information
					IF EXISTS
					(
					SELECT Top 1 1
						FROM @Bom_Explosion B
							LEFT OUTER JOIN 
								(SELECT RM_Part_No, SUM(ISNULL(BALANCE_QTY,0)) Qty, SUM(ISNULL(FlushQty,0)) FlushQty FROM Assy_LineMaterialStockStatus WITH (NOLOCK)
									WHERE Line_Code = @LineCode AND WH_Code = @ProfitCenterCode AND (ISNULL(BALANCE_QTY,0) > 0 ) AND ISNULL(STS_CD,0) != 100
											Group By RM_Part_No
									) ALMS
									ON B.RM_Part_No = ALMS.RM_Part_No
										WHERE ISNULL(B.IsMandatory,0) = 1 AND ISNULL(ALMS.Qty,0) <= 0
					)
					BEGIN
						IF NOT EXISTS (SELECT 1 FROM Assy_Stock_Alert_For_MaterialFeed WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode)
						BEGIN
							INSERT INTO Assy_Stock_Alert_For_MaterialFeed(ProfitCenterCode,LineCode,IsStockOK,IsMessageAlert,ENT_STAMP,ENT_BY,Remark)
							SELECT @ProfitCenterCode, @LineCode, 0, 1, GETDATE(), @UserId,'LessStockOfAnyChildPart'
						END
						ELSE
						BEGIN
							UPDATE Assy_Stock_Alert_For_MaterialFeed SET IsStockOK = 0, IsMessageAlert = 1, LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId, Remark = 'LessStockOfAnyChildPart'
								WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
						END
						SET @ReturnValue = 'LessStockOfAnyChildPart'
						SET @ReturnInt = 1
					END
					ELSE
					BEGIN
						IF NOT EXISTS (SELECT 1 FROM Assy_Stock_Alert_For_MaterialFeed WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode)
						BEGIN
							INSERT INTO Assy_Stock_Alert_For_MaterialFeed(ProfitCenterCode,LineCode,IsStockOK,IsMessageAlert,ENT_STAMP,ENT_BY,Remark)
							SELECT @ProfitCenterCode, @LineCode, 1, 0, GETDATE(), @UserId,'StockOK'
						END
						ELSE
						BEGIN
							UPDATE Assy_Stock_Alert_For_MaterialFeed SET IsStockOK = 1, IsMessageAlert = 0, LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId, Remark = 'StockOK'
								WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
						END
						SET @ReturnValue = 'StockOK'
						SET @ReturnInt = 1
					END
				END
				ELSE
				BEGIN
					IF NOT EXISTS (SELECT 1 FROM Assy_Stock_Alert_For_MaterialFeed WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode)
					BEGIN
						INSERT INTO Assy_Stock_Alert_For_MaterialFeed(ProfitCenterCode,LineCode,IsStockOK,IsMessageAlert,ENT_STAMP,ENT_BY,Remark)
						SELECT @ProfitCenterCode, @LineCode, 0, 0, GETDATE(), @UserId,'SetParameterNotDone'
					END
					ELSE
					BEGIN
						UPDATE Assy_Stock_Alert_For_MaterialFeed SET IsStockOK = 0, IsMessageAlert = 0, LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId, Remark = 'SetParameterNotDone'
							WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
					END
					SET @ReturnValue = 'SetParameterNotDone'
					SET @ReturnInt = 1
				END
			END
			ELSE
			BEGIN
				IF NOT EXISTS (SELECT 1 FROM Assy_Stock_Alert_For_MaterialFeed WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode)
				BEGIN
					INSERT INTO Assy_Stock_Alert_For_MaterialFeed(ProfitCenterCode,LineCode,IsStockOK,IsMessageAlert,ENT_STAMP,ENT_BY,Remark)
					SELECT @ProfitCenterCode, @LineCode, 0, 0, GETDATE(), @UserId,'MatFeedOff'
				END
				ELSE
				BEGIN
					UPDATE Assy_Stock_Alert_For_MaterialFeed SET IsStockOK = 0, IsMessageAlert = 0, LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId, Remark = 'MatFeedOff'
						WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
				END
				SET @ReturnValue = 'MatFeedOff'
				SET @ReturnInt = 1
			END
			COMMIT TRAN
			RETURN
		END

		ELSE IF @Condition = 'VALIDATE_STOCK_STATUS_FOR_PRINT'
		BEGIN
			SELECT Top 1 IsStockOK, IsMessageAlert, Remark FROM Assy_Stock_Alert_For_MaterialFeed WITH (NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode Order By ENT_STAMP Desc
			
			SET @ReturnValue = 'Success'
			SET @ReturnInt = 1
			COMMIT TRAN
			RETURN
		END

		ELSE IF @Condition = 'SELECT_LEFT_QTY_STOCK'
		BEGIN
			SELECT Distinct 0 chkSelect, UPPER(Line_Code) Line_Code, RM_Part_No, S.Serial_No, Fed_Qty, FlushQty, Mat_Feed_ID,
				--Case ISNULL(IsLineSideStockConfirm,0) WHEN 0 THEN 'Pending' WHEN 1 THEN 'Confirmed' ELSE 'Nothing' END IsLineSideStockConfirm, ISNULL(I.SUPPLIER_CD,'') VendorCode
				Case ISNULL(IsLineSideStockConfirm,0) WHEN 0 THEN 'Pending' WHEN 1 THEN Case ISNULL(IsFVUserConfirm,0) WHEN 1 THEN 'Confirmed' ELSE 'Pending' END ELSE 'Nothing' END IsLineSideStockConfirm, ISNULL(I.SUPPLIER_CD,'') VendorCode
					FROM Assy_LineMaterialStockStatus S WITH (NOLOCK)
						LEFT OUTER JOIN INV_SERIAL I WITH (NOLOCK)
							ON I.WH_CODE = S.WH_Code AND I.SERIAL_NO = S.Serial_No
								WHERE S.WH_Code = @ProfitCenterCode AND S.FlushQty > 0
									Order By 1,2,3 Desc
			
			SET @ReturnValue = 'Success'
			SET @ReturnInt = 1
			COMMIT TRAN
			RETURN
		END

		ELSE IF @Condition = 'LOAD_ALL_LINES'
		BEGIN
			-- LTCALIPER Added By Rashid On 20170601
			SELECT LM.LineCode, LM.LineName
					FROM LineMst LM WITH (NOLOCK)
						JOIN LineTypeMst LTM WITH (NOLOCK)
							ON LM.LineTypeCode = LTM.LineTypeCode
								WHERE LM.ProfitCenterCode = @ProfitCenterCode AND LTM.LineTypeCode IN ('LTTMC','LTSTMC','LTCALIPER') Order By 1,2 Desc
			
			SET @ReturnValue = 'Success'
			SET @ReturnInt = 1
			COMMIT TRAN
			RETURN
		END

		ELSE IF @Condition = 'TRANSFER_QTY'
		BEGIN
			IF (LEN(@MatFeedIdString) > 0)
			BEGIN
				Declare @CheckCurrentFlushQty INT = 0
				SELECT ROW_NUMBER() OVER(ORDER BY MatFeedId) Id,* INTO #Mat_Feed_Trasnfer_Qty_List FROM @MatFeedTable

				IF EXISTS (
						SELECT 1 FROM Assy_LineMaterialStockStatus A
							JOIN #Mat_Feed_Serial_List M
								ON A.Mat_Feed_ID = M.MatfeedID
									WHERE A.FlushQty != M.FlushQty
						)
						BEGIN
							SET @ReturnValue = 'Please Refresh the Page.'
							SET @ReturnInt = 1
							ROLLBACK TRAN
							RETURN
						END

				INSERT INTO Assy_LineMaterialStockStatus_FlushHistory (WH_Code,Line_Code,WorkCenterCode,Mat_Feed_ID,Serial_No,RM_Part_No,Fed_Qty,Consumed_Qty,Missed_Qty,FlushQty,Balance_Qty,Transfer_Qty,Consolidate_Qty,ProductionType,PacketTypeStatus,Remark,IsActive,IsLineSideStockConfirm,STS_CD,ENT_STAMP,ENT_BY,LAST_UPD_STAMP,LAST_UPD_BY,IsFVUserConfirm,HIS_ENT_STAMP,HIS_ENT_BY)
				SELECT WH_Code,Line_Code,WorkCenterCode,Mat_Feed_ID,Serial_No,RM_Part_No,Fed_Qty,Consumed_Qty,Missed_Qty,A.FlushQty,Balance_Qty,Transfer_Qty,Consolidate_Qty,ProductionType,PacketTypeStatus,Remark,IsActive,IsLineSideStockConfirm,STS_CD,ENT_STAMP,ENT_BY,LAST_UPD_STAMP,LAST_UPD_BY,IsFVUserConfirm,GETDATE(), @UserId HIS_ENT_BY
					FROM Assy_LineMaterialStockStatus A
						JOIN #Mat_Feed_Serial_List M
							ON A.Mat_Feed_ID = M.MatfeedID

				INSERT INTO Assy_LineMaterialStockStatus(WH_Code,Line_Code,WorkCenterCode,Serial_No,RM_Part_No,Fed_Qty,ProductionType,PacketTypeStatus,Remark,STS_CD,ENT_STAMP,ENT_BY,LAST_UPD_STAMP,LAST_UPD_BY)
				SELECT WH_Code,@ToLineCode,WorkCenterCode,Serial_No,RM_Part_No,M.FlushQty,ProductionType,1,@MsgRemark Remark,0 STS_CD,GETDATE() ENT_STAMP,@UserId ENT_BY, GETDATE() LAST_UPD_STAMP,@UserId LAST_UPD_BY
					FROM Assy_LineMaterialStockStatus A
						JOIN #Mat_Feed_Serial_List M
							ON A.Mat_Feed_ID = M.MatfeedID
								WHERE A.WH_Code = @ProfitCenterCode

				UPDATE A SET A.FlushQty = A.FlushQty - M.FlushQty, Transfer_Qty = M.FlushQty, Remark = @MsgRemark, LAST_UPD_STAMP = GETDATE(),LAST_UPD_BY = @UserId
					FROM Assy_LineMaterialStockStatus A
						JOIN #Mat_Feed_Serial_List M
							ON A.Mat_Feed_ID = M.MatfeedID
								WHERE A.WH_Code = @ProfitCenterCode
				/* Loop Removed By Rashid On 20170601
				SELECT @LoopEnd = COUNT(Id) FROM #Mat_Feed_Trasnfer_Qty_List
				SET @LoopStart = 1
				
				IF (@LoopEnd > 0)
				BEGIN
					WHILE (@LoopStart <= @LoopEnd)
					BEGIN
						SET @FlushQty = 0
						SET @MatFeed_Id = 0
						SET @sSerialNo = ''
						SELECT Top 1 @MatFeed_Id = MatFeedId, @FlushQty = ISNULL(FlushQty,0) FROM #Mat_Feed_Trasnfer_Qty_List WHERE Id = @LoopStart

						SELECT Top 1 @sSerialNo = Serial_No, @CheckCurrentFlushQty = ISNULL(FlushQty,0) FROM Assy_LineMaterialStockStatus WITH (NOLOCK) WHERE Mat_Feed_ID = @MatFeed_Id

						IF (ISNULL(@CheckCurrentFlushQty,0) != ISNULL(@FlushQty,0))
						BEGIN
							SET @ReturnValue = 'Please Refresh the Page.'
							SET @ReturnInt = 1
							ROLLBACK TRAN
							RETURN
						END

						IF @sSerialNo != '' AND @FlushQty > 0
						BEGIN
							INSERT INTO Assy_LineMaterialStockStatus_FlushHistory (WH_Code,Line_Code,WorkCenterCode,Mat_Feed_ID,Serial_No,RM_Part_No,Fed_Qty,Consumed_Qty,Missed_Qty,FlushQty,Balance_Qty,Transfer_Qty,Consolidate_Qty,ProductionType,PacketTypeStatus,Remark,IsActive,IsLineSideStockConfirm,STS_CD,ENT_STAMP,ENT_BY,LAST_UPD_STAMP,LAST_UPD_BY,HIS_ENT_STAMP,HIS_ENT_BY)
							SELECT WH_Code,Line_Code,WorkCenterCode,Mat_Feed_ID,Serial_No,RM_Part_No,Fed_Qty,Consumed_Qty,Missed_Qty,FlushQty,Balance_Qty,Transfer_Qty,Consolidate_Qty,ProductionType,PacketTypeStatus,Remark,IsActive,IsLineSideStockConfirm,STS_CD,ENT_STAMP,ENT_BY,LAST_UPD_STAMP,LAST_UPD_BY,GETDATE(), @UserId HIS_ENT_BY
								FROM Assy_LineMaterialStockStatus WITH (NOLOCK) WHERE Mat_Feed_ID = @MatFeed_Id AND Serial_No = @sSerialNo AND WH_Code = @ProfitCenterCode
							
							INSERT INTO Assy_LineMaterialStockStatus(WH_Code,Line_Code,WorkCenterCode,Serial_No,RM_Part_No,Fed_Qty,ProductionType,PacketTypeStatus,Remark,STS_CD,ENT_STAMP,ENT_BY,LAST_UPD_STAMP,LAST_UPD_BY)
							SELECT Top 1 WH_Code,@ToLineCode,WorkCenterCode,Serial_No,RM_Part_No,@FlushQty,ProductionType,1,@MsgRemark Remark,0 STS_CD,GETDATE() ENT_STAMP,@UserId ENT_BY, GETDATE() LAST_UPD_STAMP,
								@UserId LAST_UPD_BY FROM Assy_LineMaterialStockStatus WITH (NOLOCK) WHERE Mat_Feed_ID = @MatFeed_Id AND Serial_No = @sSerialNo AND WH_Code = @ProfitCenterCode
							 
							UPDATE Assy_LineMaterialStockStatus SET FlushQty = FlushQty - @FlushQty, Transfer_Qty = @FlushQty, Remark = @MsgRemark, LAST_UPD_STAMP = GETDATE(),
								LAST_UPD_BY = @UserId WHERE Mat_Feed_ID = @MatFeed_Id AND Serial_No = @sSerialNo AND WH_Code = @ProfitCenterCode

							--UPDATE Assy_LineMaterialStockStatus SET FlushQty = FlushQty - @FlushQty, Remark = @MsgRemark, LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId
							--	WHERE Mat_Feed_ID = @MatFeed_Id AND Serial_No = @sSerialNo AND WH_Code = @ProfitCenterCode
						END
						SET @LoopStart = @LoopStart + 1
					END
				END
				*/
			END

			SET @ReturnValue = 'Success'
			SET @ReturnInt = 1
			COMMIT TRAN
			RETURN
		END

		ELSE IF @Condition = 'CONSOLIDATE_QTY'
		BEGIN
			IF (LEN(@MatFeedIdString) > 0)
			BEGIN
				SELECT ROW_NUMBER() OVER(ORDER BY MatFeedId) Id,* INTO #Mat_Feed_Consolidate_Qty_List FROM @MatFeedTable

				SELECT ALMS.*, MFCQL.FlushQty AS MFCFlushQty INTO #TMP_SERIAL_NO
			    FROM Assy_LineMaterialStockStatus (NOLOCK) ALMS
					INNER JOIN #Mat_Feed_Consolidate_Qty_List MFCQL (NOLOCK) 
				ON MFCQL.MatFeedId = ALMS.Mat_Feed_ID AND ALMS.WH_Code = @ProfitCenterCode

				DECLARE @PARAM_REF_ID_BY_LEAST_EXPIRYDATE BIGINT
				DECLARE @LEAST_EXPIRY_DATE DATETIME
				DECLARE @EXPIRIED_SERIAL_NO NVARCHAR (20)

				SELECT TOP 1 @PARAM_REF_ID_BY_LEAST_EXPIRYDATE = I.PARAM_REF_ID, @LEAST_EXPIRY_DATE = R.PARAMETER_VALUE, @EXPIRIED_SERIAL_NO = I.SERIAL_NO  
				FROM INV_SERIAL (NOLOCK) I
					INNER JOIN RECV_PART_SET_PARAM_DTL (NOLOCK) R ON I.PARAM_REF_ID = R.PARAM_REF_ID
					INNER JOIN #TMP_SERIAL_NO (NOLOCK) TSN ON TSN.Serial_No = I.SERIAL_NO
				WHERE I.PARAM_REF_ID IS NOT NULL AND R.PARAMETER_CODE = 'EXPIRY_DATE'
				ORDER BY R.PARAMETER_VALUE
				
				IF(@LEAST_EXPIRY_DATE IS NOT NULL AND @LEAST_EXPIRY_DATE < GETDATE())
				BEGIN
					SET @ReturnValue = 'Serial No ' + @EXPIRIED_SERIAL_NO + ' has been expired.'
					SET @ReturnInt = 1
					ROLLBACK TRAN
					RETURN
				END
							
							INSERT INTO Assy_LineMaterialStockStatus_FlushHistory 
										(WH_Code,Line_Code,WorkCenterCode,Mat_Feed_ID,Serial_No,RM_Part_No,Fed_Qty,Consumed_Qty,Missed_Qty,
											FlushQty,Balance_Qty,Transfer_Qty,Consolidate_Qty,ProductionType,PacketTypeStatus,Remark,
											IsActive,IsLineSideStockConfirm,STS_CD,ENT_STAMP,ENT_BY,LAST_UPD_STAMP,LAST_UPD_BY,HIS_ENT_STAMP,HIS_ENT_BY)
							
							SELECT WH_Code,Line_Code,WorkCenterCode,Mat_Feed_ID,Serial_No,RM_Part_No,Fed_Qty,Consumed_Qty,Missed_Qty,
								ALMS.FlushQty,Balance_Qty,Transfer_Qty,Consolidate_Qty,ProductionType,PacketTypeStatus,Remark,
								IsActive,IsLineSideStockConfirm,STS_CD,ENT_STAMP,ENT_BY,LAST_UPD_STAMP,LAST_UPD_BY,GETDATE(), @UserId HIS_ENT_BY
							FROM #TMP_SERIAL_NO AS ALMS(NOLOCK)
							WHERE ALMS.MFCFlushQty > 0


							UPDATE Assy_LineMaterialStockStatus SET FlushQty = ISNULL(ALMS.FlushQty,0) - TSN.MFCFlushQty, Consolidate_Qty = ISNULL(ALMS.Consolidate_Qty,0) + TSN.MFCFlushQty,
								Remark = @MsgRemark, LAST_UPD_STAMP = GETDATE(),
									LAST_UPD_BY = @UserId --WHERE Mat_Feed_ID = @MatFeed_Id AND Serial_No = @sSerialNo AND WH_Code = @ProfitCenterCode
							FROM 
							Assy_LineMaterialStockStatus (NOLOCK) ALMS
							INNER JOIN #TMP_SERIAL_NO (NOLOCK) AS TSN
							--INNER JOIN #TMP_SERIAL_NO TSN
							ON TSN.SERIAL_NO = ALMS.SERIAL_NO
							WHERE TSN.MFCFlushQty > 0


							UPDATE INV_SERIAL SET SERIAL_QTY = SERIAL_QTY - ALMS.MFCFlushQty, LAST_UPD_STAMP = GETDATE(), LAST_UPD_BY = @UserId
							FROM INV_SERIAL (NOLOCK) INVS
							INNER JOIN #TMP_SERIAL_NO (NOLOCK) ALMS ON ALMS.Serial_No = INVS.SERIAL_NO

							Declare @NewSerialNo VARCHAR(20) = '', @GE_Number VARCHAR(60) = '', @GR_Number VARCHAR(60) = ''

							SELECT Top 1 @PartType = MATERIAL_TP, @Item_No = ITEM_NO FROM PRODUCT_MASTER (NOLOCK) PM
							INNER JOIN #TMP_SERIAL_NO (NOLOCK) ALMS ON ALMS.RM_Part_No = PM.SEWS_PART_NO
								
							
							SELECT Top 1 @LocationId =  ISNULL(CostCenterCode,'2104') FROM LineMst (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode

							SELECT @Zone_Code = ZONE_CD FROM LOCATION_MASTER WITH (NOLOCK) WHERE LOC_ID = @LocationId AND WH_CODE = @ProfitCenterCode
							--SELECT Top 1 @GE_Number = SUPPLIER_CD FROM INV_SERIAL WITH (NOLOCK) WHERE Serial_No = @sSerialNo AND WH_Code = @ProfitCenterCode AND SEWS_PART_NO = @ConsolidatePartNo
							SET @GE_Number = 'GE' + ISNULL(@VendorCode,'')
							SET @GR_Number = 'MRN'

							COMMIT TRAN
							 --- GENERATING SERIAL NO
							EXEC ASSY_PROC_GET_NEW_SERIAL_NO @UserId,@ProfitCenterCode,@NewSerialNo OUT
							
							BEGIN TRAN
							INSERT INTO [DBO].[inv_serial]
							([serial_no],[item_no],[loc_id],pallet_phy_id,[wh_code],[zone_cd],[serial_qty],[seq_no],[sts_cd],
							[ent_stamp],[ent_by],[last_upd_stamp],[last_upd_by],[GE_NO],[GR_NO],[SUPPLIER_CD],[int_lot_no],[PARAM_REF_ID],[sews_part_no])
							--VALUES(
							  SELECT @NewSerialNo AS SERIAL_NO,@Item_No AS ITEM_NO,@LocationId AS LOC_ID,'' AS PALLET_PHY_ID,@ProfitCenterCode AS WH_CODE
							 ,@Zone_Code AS ZONE_CD,SUM(ALMS.MFCFlushQty) AS SERIAL_QTY,0 AS SEQ_NO,0 AS STS_CD,
							 GETDATE() AS ENT_STAMP,@UserId AS ENT_BY,GETDATE() AS LAST_UPD_STAMP,@UserId AS LAST_UPD_BY,@GE_Number AS GE_NO
							 ,@GR_Number AS GR_NO,'' AS SUPPLIER_CD,'00000000000' AS INT_LOT_NO,@PARAM_REF_ID_BY_LEAST_EXPIRYDATE AS PARAM_REF_ID,
							 ALMS.RM_Part_No AS SEWS_PART_NO--)
							FROM #TMP_SERIAL_NO (NOLOCK) AS ALMS
							INNER JOIN INV_SERIAL (NOLOCK) INVS ON INVS.SERIAL_NO = ALMS.Serial_No
							group by ALMS.RM_Part_No
							
							--INSERT OLD SERIALS DATA INTO TRANS_LOG TABLE
							INSERT INTO [dbo].[TRANS_LOG]
								([Serial_No],[FROM_CD],[TO_CD],[ORDER_NO],[DELV_BOL_NO]
								,[ITEM_NO],[SERIAL_QTY],[WH_Code],[ENT_STAMP],[ENT_BY]
								,[PALLET_NO],[INPFLNAME_ID],[PROGRAM_ID],[TRAN_TYPE],[TR_TRNBR],[pallet_phy_id])
									--VALUES
							SELECT ALMS.Serial_No,@LocationId,@LocationId,'STOCK_CONSOLIDATE',(CONVERT(NVARCHAR, ALMS.MFCFlushQty) + ' --> ' + @NewSerialNo) + ' (' + CONVERT(NVARCHAR, ALMS.MFCFlushQty) + ')'--@NewSerialNo + ' (' + CONVERT(NVARCHAR, MFCQL.FlushQty) + ') --> ' + ALMS.Serial_No
								,dbo.FN_GET_ITEM_NO(ALMS.RM_Part_No,@ProfitCenterCode),ALMS.MFCFlushQty,@ProfitCenterCode,GETDATE(),
								@UserId,'',NULL,'MAT_CONSOLIDATE_BITS',NULL,NULL, ''
							FROM #TMP_SERIAL_NO (NOLOCK) AS ALMS
							GROUP BY ALMS.MFCFlushQty, ALMS.Serial_No, ALMS.RM_Part_No
							
							--INSERT NEW SERIALS DATA INTO TRANS_LOG TABLE
							INSERT INTO [dbo].[TRANS_LOG] ([SERIAL_NO] ,[FROM_CD],[TO_CD],[ORDER_NO] ,[DELV_BOL_NO]
							,[ITEM_NO],[SERIAL_QTY] ,[WH_CODE],[ENT_STAMP],[ENT_BY],[PALLET_NO]
							,[INPFLNAME_ID],[PROGRAM_ID] ,[TRAN_TYPE],[TR_TRNBR],[pallet_phy_id])
							SELECT @NewSerialNo,@LocationId, @LocationId,'STOCK_CONSOLIDATE',ALMS.Serial_No + ' (' + CONVERT(NVARCHAR, ALMS.MFCFlushQty) + ') --> ' + @NewSerialNo 
							,@Item_No,SUM(ALMS.MFCFlushQty),@ProfitCenterCode,GETDATE(),@UserId,'',NULL,'STOCK_CONSOLIDATE',NULL, NULL,''
							FROM #TMP_SERIAL_NO (NOLOCK) AS ALMS
							GROUP BY ALMS.MFCFlushQty, ALMS.Serial_No, ALMS.RM_Part_No

							SET @ConsolidateQty = (SELECT SUM(FlushQty) FROM #Mat_Feed_Consolidate_Qty_List (NOLOCK))

							INSERT INTO Assy_LineMaterialStockConsolidate_History(WH_Code,Line_Code,RM_Part_No,New_Serial_No,New_Serial_Qty,Old_Serial_No,Old_Serial_Qty,
							ENT_STAMP,ENT_BY,LAST_UPD_STAMP, LAST_UPD_BY, ISUPDATE)
							SELECT @ProfitCenterCode, @LineCode,dbo.FN_GET_ITEM_NO(ALMS.RM_Part_No,@ProfitCenterCode),@NewSerialNo,@ConsolidateQty, ALMS.Serial_No, ALMS.MFCFlushQty,
							GETDATE(), @UserId,GETDATE(), @UserId,1
							FROM #TMP_SERIAL_NO (NOLOCK) ALMS
								
							PRINT 'INSERT INTO INV_SERIAL'
						--END

						--SET @LoopStart = @LoopStart + 1
					--END
				--END
			END

			SET @ReturnValue = 'Success'
			SET @ReturnInt = 1
			COMMIT TRAN
			RETURN
		END

		ELSE IF @Condition = 'LOAD_CONSOLIDATE_SERIAL_HISTORY'
		BEGIN
			IF OBJECT_ID('tempdb..#tmpConsolidate') IS NOT NULL 
				DROP TABLE #tmpConsolidate

			SELECT 0 chkSelect, RM_Part_No,(SELECT Top 1 RTRIM(LTRIM(ISNULL(product_nm,''))) FROM PRODUCT_MASTER (NOLOCK) WHERE WH_Code = @ProfitCenterCode
				AND SEWS_PART_NO = RM_Part_No) PartDescr,New_Serial_No, New_Serial_Qty, Old_Serial_No, Old_Serial_Qty, LAST_UPD_BY, LAST_UPD_STAMP,
				CONVERT(NVARCHAR(MAX) ,'' ) AS Con_Old_Serial_No, CONVERT(NVARCHAR(MAX) ,'' ) AS Con_Old_Serial_Qty
			INTO #tmpConsolidate
			FROM Assy_LineMaterialStockConsolidate_History WITH (NOLOCK) WHERE WH_Code = @ProfitCenterCode Order By LAST_UPD_STAMP Desc
			--MODIFIED BY SUDESH ON 20170516 FOR APPLYING WHERE CONDITION ON STUFF
			UPDATE T SET Con_Old_Serial_No = Con_Old_Serial_No  + STUFF
			(
				(
					SELECT ',' + CONVERT(NVARCHAR(20),OLD_SERIAL_NO)
					FROM #tmpConsolidate(NOLOCK) TCS
					WHERE T.New_Serial_No = TCS.New_Serial_No
					ORDER BY TCS.Con_Old_Serial_No
					FOR XML PATH('')
				), 1, 1, ''
			) ,
			Con_Old_Serial_Qty = Con_Old_Serial_Qty  + STUFF
			(
				(
					SELECT ',' + CONVERT(NVARCHAR(20),OLD_SERIAL_QTY)
					FROM #tmpConsolidate(NOLOCK) TCQ
					WHERE T.New_Serial_No = TCQ.New_Serial_No
					ORDER BY Con_Old_Serial_No
					FOR XML PATH('')
				), 1, 1, ''
			) 
			FROM #tmpConsolidate T

			SELECT DISTINCT chkSelect, RM_Part_No, PartDescr, New_Serial_No, New_Serial_Qty, LAST_UPD_BY, LAST_UPD_STAMP ,Con_Old_Serial_No Old_Serial_No, 
				Con_Old_Serial_Qty Old_Serial_Qty
			FROM #tmpConsolidate

			SET @ReturnValue = 'Success'
			SET @ReturnInt = 1
			COMMIT TRAN
			RETURN
		END

		ELSE IF @Condition = 'PRINT_STORE_LABEL'
		BEGIN
			Declare @Qty INT = 0
			SELECT Top 1 @Qty = ISNULL(New_Serial_Qty,0) FROM Assy_LineMaterialStockConsolidate_History WITH (NOLOCK) WHERE WH_Code = @ProfitCenterCode AND New_Serial_No = @NewSerialNoForPrint
			
			SELECT Top 1
				@ReturnValue = LTRIM(RTRIM(ISNULL(SEWS_PART_NO,''))) +'~'+ LTRIM(RTRIM(ISNULL(GE_NO,'')))
					+'~'+ LTRIM(RTRIM(ISNULL(GR_NO,''))) +'~'+ LTRIM(RTRIM(ISNULL(SERIAL_NO,''))) +'~'+ CAST (@Qty AS VARCHAR(10)) +'|'
						FROM INV_SERIAL WITH (NOLOCK) WHERE WH_Code = @ProfitCenterCode AND SERIAL_NO = @NewSerialNoForPrint
			
			SET @ReturnValue = @ReturnValue
			SET @ReturnInt = 1
			COMMIT TRAN
			RETURN
		END

		--ADDED BY SUDESH ON 20170406 FOR VALIDATING STOCK FEED BEFORE RFID GENERATION
		ELSE IF @Condition = 'VALIDATE_MATFEEDING_BEFORE_RFID'
		BEGIN
			DECLARE @ValidMatFeed BIT = 1
			IF EXISTS(SELECT 1 FROM LineMst
						WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(IsMatFeedRequired,0) = 1)
			BEGIN
				IF EXISTS (SELECT 1 FROM Assy_Stock_Alert_For_MaterialFeed
							WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(IsStockOK,0) = 0)
				BEGIN
					SET @ValidMatFeed = 0
				END
			END
			
			SELECT @ValidMatFeed

			SET @ReturnValue = 'Success'
			SET @ReturnInt = 1
			COMMIT TRAN
			RETURN
		END

		ELSE IF @Condition = 'GET_MAT_FEED_PRINT_SCAN_STATUS'
		BEGIN
			SELECT @ReturnValue = ISNULL(IsMatFeedPrintScanRequired,0) FROM LineMst (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			SELECT @ReturnValue = ISNULL(@ReturnValue,0)
			SELECT @ReturnInt = 1
			COMMIT TRAN
			RETURN
		END

		ELSE IF @Condition = 'FETCH_FLUSH_OUT_STOCK'
		BEGIN
			SELECT	WH_Code [WH Code], UPPER(Line_Code) [Line Code], Serial_No [Serial No], RM_Part_No [RM Part No], Fed_Qty [Packet Qty], FlushQty [Flush Qty],
				CASE ISNULL(IsFVUserConfirm,0) WHEN 1 THEN 'Confirmed' ELSE 'Pending' END [FV User Confirmation],
				CASE ISNULL(IsLineSideStockConfirm,0) WHEN 1 THEN 'Confirmed' ELSE 'Pending' END [Mat. Feed User Confirmation],
				ProductionType, UPPER(Remark) Remark, UPPER(ENT_BY) [Fed By], ENT_STAMP [Fed TimeStamp] FROM Assy_LineMaterialStockStatus (NOLOCK)
			WHERE Line_Code = @LineCode AND WH_Code = @ProfitCenterCode AND ISNULL(FlushQty,0) > 0 Order By ENT_STAMP Desc

			SELECT @ReturnInt = 1

			COMMIT TRAN
			RETURN
		END
	END TRY
	BEGIN CATCH
		SET @ReturnValue = CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' +
		CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' +
		CAST(ERROR_STATE() AS VARCHAR(5)) + '|' +
		CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' +
		CAST(ERROR_LINE() AS VARCHAR(5)) + '|' +
		CAST(ERROR_MESSAGE() AS VARCHAR(1500))

		ROLLBACK TRAN
		SET @ReturnInt = 2
		RAISERROR(@ReturnValue,16,1)
	END CATCH
END




