/****** Object:  StoredProcedure [dbo].[ASSY_PROC_MENU_DISPLAY]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
--EXEC ASSY_PROC_MENU_DISPLAY @P_APP_ID=3, @P_USER_ID='mishra'
--EXEC ASSY_PROC_MENU_DISPLAY @P_APP_ID=3, @P_USER_ID='admin'

--select * from ASSEMBLY_MENU
--select * from TL_MF_SEC_APPS
--select * from TL_MF_SEC_USER_MENU_SETUP_MST where USER_GROUP_ID=5641 and PROGRAM_DES ='Assembly'

CREATE PROCEDURE [dbo].[ASSY_PROC_MENU_DISPLAY]
(    
	 @P_APP_ID           VARCHAR(20)='3',
	 @P_USER_ID          NVARCHAR(30) = '',
	 @P_USER_GROUP_ID  NUMERIC=0,
	 @P_USER_TYPE   VARCHAR(1)='U',
	 @P_MODE       VARCHAR(50)='PROGRAM ACCESS',
	 
	 @RETURNVALUE      VARCHAR (2000)=NULL OUT,
	 @RETURNINT        INT=NULL OUT
)          
AS          
BEGIN
	BEGIN TRY   
	set nocount on
			IF @P_MODE='GETASSEMBLYMENU'
			BEGIN
				IF EXISTS (SELECT 1 FROM ASSEMBLY_MENU)
				BEGIN
					SELECT MENUID, MENUNAME FROM ASSEMBLY_MENU
				END
				ELSE
				BEGIN
					SELECT 0 MENUID,'' MENUNAME
				END

				RETURN	
			END

 			CREATE TABLE #MENU_DISPLAY_TEMP          
			(          
				APP_ID VARCHAR(100),          
				APP_NM VARCHAR(100),          
				PARENT_ID VARCHAR(100),          
				PROGRAM_ID VARCHAR(100),          
				RES_ID VARCHAR(100),          
				PROGRAM_DES VARCHAR(1000 ),          
				LOCAL_FLG VARCHAR(100),          
				PROCESS_FLG VARCHAR(100),          
				MENU_ID VARCHAR(100),          
				PROGRAM_ORDER VARCHAR(100),          
				MENU_EDITED VARCHAR(100),          
				PROGRAM_MODE VARCHAR(100),
				MODIFY_ALLOW VARCHAR(100)
			)      
		
			DECLARE @USER_GROUP_ID AS  DECIMAL      
			SELECT @USER_GROUP_ID = user_id FROM tl_mf_sec_user_mst (nolock) WHERE USER_CODE=@P_USER_ID      
	
			INSERT INTO #MENU_DISPLAY_TEMP          
			--EXEC SP_R_MF_SEC_USER_MENU_FILLTREE @USER_GROUP_ID,'U','PROGRAM ACCESS'          
			SELECT          
				ISNULL(APP.APP_ID,0) AS APP_ID,
				ISNULL(APP.APP_LONG_NM, '') AS APP_NM,
				MSM.PARENT_ID, 
                MSM.PROGRAM_ID, 
				MSM.RES_ID, 
				MSM.PROGRAM_DES, 
				MSM.LOCAL_FLG, 
                MSM.PROCESS_FLG, 
				MSM.MENU_ID, 
				MSM.PROGRAM_ORDER, 
                MSM.MENU_EDITED,
				MSM.PROGRAM_MODE,
				MSM.MODIFY_ALLOW	
			FROM            
				TL_MF_SEC_USER_MENU_SETUP_MST MSM inner JOIN TL_MF_SEC_APPS APP ON MSM.APP_ID = APP.APP_ID
			WHERE           
				(MSM.USER_GROUP_ID = @USER_GROUP_ID) 
				AND (MSM.USER_TYPE = 'U') 
			ORDER BY APP.APP_ID, MSM.PARENT_ID, MSM.PROGRAM_ORDER

	      
			SELECT DISTINCT * INTO #MENU_DISPLAY FROM  #MENU_DISPLAY_TEMP ORDER BY PROGRAM_ORDER
			UPDATE #MENU_DISPLAY SET PROGRAM_DES=UPPER(PROGRAM_DES)	
			-------------------
				
			--SELECT  PROGRAM_ORDER AS MENU_NO, 
			--		PROGRAM_DES AS MENU_NAME, 
			--		PARENT_ID AS PARENT_ID,
			--		PROGRAM_ID AS PROG_ID, 
			--		MENU_ID,
			--		MODIFY_ALLOW
			--FROM #MENU_DISPLAY WHERE APP_ID =@P_APP_ID 


			--select * from #MENU_DISPLAY_temp WHERE APP_ID =@P_APP_ID 
						------------
			
			SELECT  PROGRAM_ORDER AS MENU_NO, 
					PROGRAM_DES AS MENU_NAME, 
					PARENT_ID AS PARENT_ID,
					PROGRAM_ID AS PROG_ID, 
					MENU_ID,
					MODIFY_ALLOW
			FROM #MENU_DISPLAY WHERE APP_ID =@P_APP_ID AND PROCESS_FLG='Y'       
			ORDER BY CAST( PROGRAM_ORDER AS INT), CAST( PARENT_ID AS INT)
       
			DROP TABLE #MENU_DISPLAY
			drop table #MENU_DISPLAY_TEMP
	  END TRY

      BEGIN CATCH
          --CATCH BLOCK BEGINS
          SET @RETURNVALUE = CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|'
                             + CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|'
                             + CAST(ERROR_STATE() AS VARCHAR(5)) + '|'
                             + CAST(ERROR_PROCEDURE() AS VARCHAR(200))
                             + '|' + CAST(ERROR_LINE() AS VARCHAR(5)) + '|'
                             + CAST(ERROR_MESSAGE() AS VARCHAR(1500))
          SET @RETURNINT = 2

		  Raiserror(@RETURNVALUE,16,1)
      --CATCH BLOCK ENDS 
      END CATCH
END


