/****** Object:  StoredProcedure [dbo].[Assy_PROC_METERIALFEEDING]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



--Update Assy_ProductionOrder_ParameterSetting set LineCode='L0001'
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
CREATE PROC [dbo].[Assy_PROC_METERIALFEEDING]
(
@OPERATION VARCHAR(100)=NULL,
@LINECODE varchar(20)=null,
@PROFITCENTERCODE VARCHAR(20)=NULL,
@FGPARTCODE VARCHAR(20)=NULL,
@PRODUCTIONORDERNO VARCHAR(20)=NULL,
@PACKETBARCODE VARCHAR(20)=NULL,
@DateCode VARCHAR(20)=NULL,
--@BINID VARCHAR(50)=NULL,
--@NOOFPARTS INT=-1,
--@LOTNO VARCHAR(50)=NULL,
--@KANBANID VARCHAR(50)=NULL,
@USERID VARCHAR(12)=NULL
)
as
begin 
	  
BEGIN TRY
BEGIN TRAN
DECLARE @ERRORMSG AS VARCHAR(200)
Declare @PACKETQTY as Decimal(9,4)=0
 Declare @ChildPart varchar(20)
	 Declare @LotNumber varchar(20)
	 Declare @PartQuantity Decimal(9,4)

   if @OPERATION='CURRENTRUNNINGPART'
	   begin
	      if not exists(select top 1 1 from Assy_RunningPart where LineCode=@LINECODE)
	      begin
	      select 'RUNNING PART NOT FOUND'  
		  end
		  else
		  begin
		  
         select top 1 A.LineCode,Assy_PartNo,ProductionOrderNo,P.BalanceQty  from Assy_RunningPart A inner join                 Assy_ProductionOrder_ParameterSetting P on A.ProductionOrderNo=P.ProdOrderNo  and                                      A.Assy_PartNo=P.PartNumber           where A.LineCode=@LINECODE
		  end
	   end

    if @OPERATION='PACKETVALIDATE'
	begin
	  
	  if exists( select top 1 1 from Assy_MaterialFeeding where PacketId=@PACKETBARCODE)
	  begin
	     select 'ALREADY FEEDED'
	     return
	  end
	  --part validation from stores...
	 if not exists( SELECT TOP 1 1 FROM INV_SERIAL (NOLOCK) 
	 WHERE 1=1
	 AND WH_CODE = @PROFITCENTERCODE
	 AND SERIAL_NO = @PACKETBARCODE
	 --AND LOC_ID = @TO_LOC_ID
	 AND STS_CD = 0)
	 begin
	   select 'SERIAL NO NOT VALID'
	   return
	 end

	 --select 'VALIDATED','Child Part','Temp Lot',22.00
	 --return
	 --FG and Child partCode validation...
	  if not exists (select top 1 1 from BOM_MASTER where WH_CODE=@PROFITCENTERCODE and FG_PART_NO=@FGPARTCODE and RM_PART_NO=
	  (select SEWS_PART_NO  from PRODUCT_MASTER where ITEM_NO=(select ITEM_NO from INV_SERIAL where SERIAL_NO=@PACKETBARCODE)))
	   begin
	      select 'RM PART AND FG PART MISSMATCH'
	      return
	   end

	 -- Expired or Not validation...
	 Declare @Expiry datetime
	   Create table #temp
			   (
			     SERIAL_NO varchar(60),
				 partNumber varchar(100),
				 SerialQty decimal(9,3),
				 Location varchar(40),
				 Status varchar(50),
				 LotNumber varchar(100),
				 ERP_LotNumber varchar(100),
				 SupplierCode varchar(50),
				 ExpiryDate DateTime,
				 GE_Number varchar(50),
				 GR_Number varchar(50)
			   )

        insert into #temp
	    EXEC [PROC_GET_SERIAL_INFO] @PACKETBARCODE, @PROFITCENTERCODE, '1', '', '', 'SHELL', '105'

	    if  exists (select top 1 1 from #temp)
		begin
		    select @Expiry=ExpiryDate from #temp
				if(@Expiry<getdate())
				begin
				select 'PACKET EXPIRED'
				return
				end
		end
		else
		   begin
			  select 'PACKET EXPIRED'
			  return
		   end
       
	 --if vendor Code available the validate that it is verifier or not
	
	 Declare @VenderFromStores varchar(20)
	 Declare @VendorCode varchar(20)
	     select @VendorCode=PART_SUPPLIER from BOM_MASTER where RM_PART_NO=(select SEWS_PART_NO  from PRODUCT_MASTER where ITEM_NO=(select ITEM_NO from INV_SERIAL where SERIAL_NO=@PACKETBARCODE)) and WH_CODE=@PROFITCENTERCODE

	     if @VendorCode=''
	      begin
				select @ChildPart=Bom.RM_PART_NO ,@LotNumber=INV.INT_LOT_NO ,@PartQuantity=INV.SERIAL_QTY   from INV_SERIAL INV						inner join	PRODUCT_MASTER PROD on INV.ITEM_NO=PROD.ITEM_NO inner join BOM_MASTER BOM on												PROD.SEWS_PART_NO=BOM.FG_PART_NO   where  INV.SERIAL_NO=@PACKETBARCODE

				select 'VALIDATED',@ChildPart,@LotNumber,@PartQuantity
	      return
	      end
		  else if @VendorCode<>''
		  begin
				select @VenderFromStores=SUPPLIER_CD  from INV_SERIAL where SERIAL_NO=@PACKETBARCODE
				if @VenderFromStores=@VendorCode
				begin
					select @ChildPart=Bom.RM_PART_NO  ,@LotNumber=INV.INT_LOT_NO ,@PartQuantity=INV.SERIAL_QTY   from INV_SERIAL					INV	inner join	PRODUCT_MASTER PROD on INV.ITEM_NO=PROD.ITEM_NO inner join BOM_MASTER BOM on												PROD.SEWS_PART_NO=BOM.FG_PART_NO   where  INV.SERIAL_NO=@PACKETBARCODE

				select 'VALIDATED',@ChildPart,@LotNumber,@PartQuantity
				end
				else
				begin
				   select 'NOT VALID SUPPLIER'
				end
		  end
	end

	if @OPERATION='FEED'
	begin
	   select @ChildPart=Bom.RM_PART_NO  ,@LotNumber=INV.INT_LOT_NO ,@PartQuantity=INV.SERIAL_QTY   from INV_SERIAL							INV	inner join	PRODUCT_MASTER PROD on INV.ITEM_NO=PROD.ITEM_NO inner join BOM_MASTER BOM on									PROD.SEWS_PART_NO=BOM.FG_PART_NO   where  INV.SERIAL_NO=@PACKETBARCODE

	  insert into Assy_MaterialFeeding
	  (ProfitCenterCode,
		LineCode,
		Datecode,
		FGPartCode,
		ProductionOrderNo,
		PacketId,
		ChildPartNo,
		LotNumber,
		FeedQuantity,
		UserCode,
		EntDt
		 )
	  select @PROFITCENTERCODE,@LINECODE,@DateCode,@FGPARTCODE,@PRODUCTIONORDERNO,@PACKETBARCODE,@ChildPart,@LotNumber,
	  @PartQuantity,@USERID,getdate()

	  select 'CONFIRM'
	end
COMMIT TRAN
END TRY
			BEGIN CATCH
			     ROLLBACK TRAN
			     SET @ERRORMSG=ERROR_MESSAGE ()
			     RAISERROR(@ERRORMSG,16,1)
			END CATCH
end





