/****** Object:  StoredProcedure [dbo].[ASSY_Proc_ModelChanged]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create proc [dbo].[ASSY_Proc_ModelChanged]
(
@Operation varchar(30),
@LineCode varchar(10),
@profitCenterCode VArchar(20)='0021',
@operationCode varchar(20)=null
)
as
begin
--Created By:<Ravishankar Mishra>
--Created Date:<11/04/2015>

--Modified By:<Ravishankar Mishra>
--Modified Date:<23/01/2016>
--select * from assy_ModelChanged
--delete assy_ModelChanged
--exec ASSY_Proc_ModelChanged @Operation='update',@LineCode='M07',@profitCenterCode='0021'
     SET NOCOUNT ON
     if @Operation='UPDATE'
     begin
					
					--declare 
					declare @TempOpeartions as table
					(
						Id int not null identity(1,1),
						OperationSeqNo int,
						OperationCode varchar(20),
						MachineCode varchar(20)
					)

					insert into @TempOpeartions
					(
					
						OperationSeqNo, 
						OperationCode,
						MachineCode
					)
					select  OperationSeqNo,OperationCode,MachineCode from RoutingConfigLineWise(nolock)   
					where LineCode =@linecode
					and OperationRequired =1 
					and Recipe=1
					and ProfitCenterCode =@profitCenterCode
					order by OperationSeqNo

					declare @TotReoreds int=(select count(id) from @TempOpeartions)
					declare @StartCount int=1

					delete from Assy_ModelChanged where LineCode =@LineCode 
					while(@StartCount<=@TotReoreds)
					begin
							  
								  select @operationCode=operationcode from @TempOpeartions where Id=@StartCount							        
								 insert into Assy_ModelChanged(OperationCode,IsChanged,LineCode) values(@operationCode,1,@LineCode)		
								 set @StartCount=@StartCount+1
					end               
     end      
     else if @Operation='Reset'
     begin          
               update assy_ModelChanged set isChanged=0 where  OperationCode=@operationCode and LineCode =@LineCode                 
     end      
    else if @Operation='select'
     begin          
               select isChanged from assy_ModelChanged(nolock) where  OperationCode=@operationCode and LineCode=@LineCode  and isChanged=1          
               update assy_ModelChanged set isChanged=0 where  OperationCode=@operationCode and linecode =@linecode  
     end 
end
if object_id('Assy_Trg_ProductionOrder_ParameterSetting_After_Insert') is not null
begin
  drop trigger Assy_Trg_ProductionOrder_ParameterSetting_After_Insert
end

