/****** Object:  StoredProcedure [dbo].[Assy_PROC_OnlineStatus]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[Assy_PROC_OnlineStatus] (
	@CONDITION VARCHAR(50),
	@ProfitCenterCode Varchar(20)='0021',
	@LineCode VARCHAR(20),
	@ReturnVaLue VARCHAR(2000) = NULL OUT,
	@ReturnInt INT = NULL OUT)
AS
BEGIN

	-- Author:		<Ravishankar Mishra>
	-- Create date: <09 August 2014>

	-- Modified By:	<Rashid Siddiqui>
	-- Modified Date: <11 Feb 2016>
	-- Change:	<Couple Barcode Status>

	-- Modified By:	<Ravishankar Mishra>
	-- Modified Date: <08/06/2016>
	-- Remarks:	Included profit center code in conditions

	-- To Rembember
	-- Nothing = 0
	-- Success = 1
	-- Error = 2
	-- ALreadyExists = 3
	-- NotExists = 4
	/*
	 DECLARE @p3 VARCHAR(2000)
	 SET @p3 = 'SuccessfuLLy'
	 DECLARE @p4 INT
	 SET @p4 = 1
	 EXEC Assy_PROC_OnLineStatus @CONDITION = N'STATUS',@LineCode = N'J04',@ProfitCenterCode='0088',@ReturnVaLue = @p3 output,@ReturnInt = @p4 output
	 SELECT @p3, @p4

	 EXEC Assy_PROC_OnLineStatus @CONDITION = N'GET_ACTIVE_STATION',@LineCode = N'j04',@ProfitCenterCode='0088',@ReturnVaLue = @p3 output,@ReturnInt = @p4 output
	 */
	
	SET NOCOUNT ON
	DECLARE	@PartNo VARCHAR(20) = '', @DateCode char(4) = '', @PartType VARCHAR(20) = ''
	DECLARE	@Cols AS nVARCHAR(MAX),	@Query AS nVARCHAR(MAX)
	
	IF @CONDITION = 'STATUS'
	BEGIN
		
		SELECT TOP 1
			@PartNo = Assy_PartNo,
			@DateCode = Datecode,
			@PartType = ISNULL(PartType,'')
		FROM Assy_RunningPart(NOLOCK)
			WHERE LineCode = @LineCode
		
		IF @PartType = 'STMC'
		BEGIN
			SELECT DISTINCT
				R.OperationSeqNo,
				ISNULL(A.Barcode, '') Barcode,
				ISNULL(A.MachineCode, '') MachineCode,
				M.MachineName AS MachineName,
				(CASE
					WHEN ISNULL(A.Status,'') = '' THEN ''
					ELSE (CASE
							WHEN A.Status = 'PS' THEN 'PASS'
							ELSE 'FAIL'
						END)
				END) ResuLt,
				ISNULL(A.ResultTimestamp, '') ResultTimestamp INTO #RunningStatus_STMC
			FROM (SELECT
				L.*
			FROM RoutingConfigLineWise (NOLOCK) L
			INNER JOIN RoutingConfigPartWise (NOLOCK) P
				ON L.ProfitCenterCode = P.ProfitCenterCode
				AND L.OperationCode = P.OperationCode
				AND L.MachineCode = P.MachineCode
			WHERE L.LineCode = @LineCode
			AND P.PartNo = @PartNo
			AND L.TraceabiLity = 1
			AND P.TraceabiLity = 1) R
			LEFT OUTER JOIN Assy_VIEW_Both_LineAssyStatus_Data(NOLOCK) A
				ON A.LineCode = R.LineCode
				AND A.MachineCode = R.MachineCode
			INNER JOIN machinemst(NOLOCK) M
				ON A.MachineCode = M.MachineCode
			WHERE A.LineCode = @LineCode
					AND A.Datecode = @DateCode
						AND A.PartNo = @PartNo
							AND M.isActive = 1
								AND ISNULL(A.IsTaLLyChartApproved,0) = 0
				Order By R.OperationSeqNo

			SELECT * INTO #Normal FROM #RunningStatus_STMC WHERE CHARINDEX(':',Barcode) = 0

			SELECT * INTO #Couple FROM #RunningStatus_STMC WHERE CHARINDEX(':',Barcode) != 0

			SELECT * INTO #Normal1 FROM #RunningStatus_STMC WHERE CHARINDEX(':',Barcode) = 0

			SELECT * INTO #Couple1 FROM #RunningStatus_STMC WHERE CHARINDEX(':',Barcode) != 0

			Update C SET C.Barcode = N.Barcode
				FROM #Couple C
					JOIN #Normal N ON RIGHT(C.Barcode,4) = LEFT(RIGHT(N.Barcode,6),4)

			Update N SET N.Barcode = C.Barcode
				FROM #Normal1 N
					JOIN #Couple1 C ON LEFT(RIGHT(N.Barcode,6),4) = RIGHT(C.Barcode,4)

			SELECT * INTO #RunningStatus_STMC_Updated FROM (
						SELECT *  FROM #Normal
						UNION
						SELECT *  FROM #Couple
						UNION
						SELECT *  FROM #Normal1
						UNION
						SELECT *  FROM #Couple1
					) S

			--SELECT * FROM #RunningStatus_STMC_Updated Order by Barcode,OperationSeqNo

			DECLARE @TempRunning_STMC AS TABLE (
				MachineCode VARCHAR(20),
				Barcode VARCHAR(60),
				Record INT
			)
		
			INSERT INTO @TempRunning_STMC (MachineCode, Barcode, Record)
				SELECT
					MachineCode,
					Barcode,
					COUNT(Barcode)
				FROM #RunningStatus_STMC_Updated(NOLOCK)
					GROUP By	MachineCode,Barcode
						HAVING COUNT(Barcode) > 1
		
			DELETE Running_Temp
				FROM #RunningStatus_STMC_Updated Running_Temp
					INNER JOIN @TempRunning_STMC TV
						ON Running_Temp.MachineCode = TV.MachineCode
							AND Running_Temp.Barcode = TV.Barcode
						WHERE Running_Temp.ResuLt = 'FaiL'
		
			SELECT
				@Cols = STUFF((SELECT
					',' + QUOTENAME(Col + '_' + CAST(Seq AS VARCHAR(10)))
				FROM (SELECT
					ROW_NUMBER() OVER (Partition By Barcode
					Order By OperationSeqNo) Seq
				FROM #RunningStatus_STMC_Updated) T
				CROSS APPLY (SELECT
					'MachineName',
					1
				UNION ALL
				SELECT
					'ResuLt',
					2
				UNION ALL
				SELECT
					'ResultTimestamp',
					3) c (Col, So)
				GROUP By	Col,Seq,So
				Order By Seq, So
				FOR xml PATH (''), TYPE)
				.value('.', 'NVARCHAR(MAX)')
				, 1, 1, '')

				--drop tabLe test
				SET @Query = 'SELECT Barcode ,' + @Cols + ' 
							FROM 
							(
							 SELECT Barcode, 
								Col = Col+''_''+cast(Seq AS VARCHAR(10)), 
								value
							 FROM
							 (
								SELECT Barcode, MachineName , ResuLt,CONVERT(VARCHAR,ResultTimestamp,120)ResultTimestamp,
								 row_number() OVER(Partition By Barcode
													Order By OperationSeqNo ) Seq
								FROM #RunningStatus_STMC_Updated
							 ) SRC
							 CROSS APPLY
							 (
       
								SELECT ''MachineName'',MachineName UNION ALL
								SELECT ''ResuLt'', ResuLt UNION ALL
								SELECT ''ResultTimestamp'', CONVERT(VARCHAR(100), ResultTimestamp) 
							 ) c (Col, value)
							) x
							pivot 
							(
								MAX(value)
								for Col in (' + @Cols + ')
							) P '

				EXECUTE sp_EXECutesqL @Query

			IF OBJECT_ID('tempdb..#RunningStatus_STMC', 'U') IS NOT NULL
				DROP TABLE #RunningStatus_STMC
			IF OBJECT_ID('tempdb..#Normal', 'U') IS NOT NULL
				DROP TABLE #Normal
			IF OBJECT_ID('tempdb..#Normal1', 'U') IS NOT NULL
				DROP TABLE #Normal1
			IF OBJECT_ID('tempdb..#Couple', 'U') IS NOT NULL
				DROP TABLE #Couple
			IF OBJECT_ID('tempdb..#Couple1', 'U') IS NOT NULL
				DROP TABLE #Couple1
			IF OBJECT_ID('tempdb..#RunningStatus_STMC_Updated', 'U') IS NOT NULL
				DROP TABLE #RunningStatus_STMC_Updated

				SET @ReturnInt = 1
				SET @ReturnVaLue = 'SuccessfuLLy'
		END
		ELSE
		BEGIN
					-- Added  by sachin 20170822 -- Due to BYPASS 
					--Station Overlap on Each Other 

					CREATE TABLE  #RunningStatus
					(
					  OperationSeqNo int, 
					  Barcode varchar(30),
					  MachineCode varchar(10),
					  MachineName varchar(100),
					  Result varchar(6),
					  ResultTimestamp datetime
					)

					SELECT DISTINCT
					R.OperationSeqNo,
					'' as Barcode,
					ISNULL(R.MachineCode, '') MachineCode,
					R.MachineName AS MachineName,
					'' as ResuLt, 
					'' as ResultTimestamp
					into #TEMP_RUNNING_LINE_DETAILS
					FROM (SELECT
					L.OperationSeqNo,L.machineCode,M.MachineName
					FROM RoutingConfigLineWise (NOLOCK) L
					INNER JOIN machineMst (NOLOCK) M
					ON L.ProfitCenterCode = M.ProfitCenterCode
					AND L.MachineCode = M.MachineCode
					INNER JOIN RoutingConfigPartWise (NOLOCK) P
					ON P.OperationCode=L.OperationCode
					WHERE L.LineCode = @LineCode AND
					L.ProfitCenterCode=@ProfitCenterCode AND
					P.ProfitCenterCode=@ProfitCenterCode AND
					P.PartNo=@PartNo
					) R


					SELECT 0 as OperationSeqNo,ISNULL(A.Barcode, '') Barcode,ISNULL(A.MachineCode, '') MachineCode,
					'' as MachineName,
					(CASE WHEN ISNULL(A.Status,'') = '' THEN ''
					ELSE (CASE WHEN A.Status = 'PS' THEN 'PASS'
					ELSE 'FAIL' END) END) ResuLt,ISNULL(A.ResultTimestamp, '') ResultTimestamp
					into #TEMP_CURRENT_RUNING_BARCODE_DATA			
					FROM ASSY_VIEW_BOTH_LINEASSYSTATUS_DATA(NOLOCK) A
					WHERE A.LINECODE = @LINECODE
					AND A.DATECODE = @DATECODE
					AND A.PARTNO = @PARTNO
					AND A.PROFITCENTERCODE=@PROFITCENTERCODE 
					AND A.ISTALLYCHARTAPPROVED = 0

				--select * from #TEMP_CURRENT_RUNING_BARCODE_DATA order by barcode
				--select * from #TEMP_RUNNING_LINE_DETAILS
						
						update tmp 
						set tmp.OperationSeqNo=convert(int,r.OperationSeqNo)
						from #TEMP_CURRENT_RUNING_BARCODE_DATA tmp inner join  #TEMP_RUNNING_LINE_DETAILS r on
						tmp.machineCode=r.machineCode
						
				while exists(select top 1 1 from #TEMP_CURRENT_RUNING_BARCODE_DATA)
				begin
						declare @getBarcode varchar(30)
						declare @getResult varchar(30)
						declare @getResultTimestamp datetime
						
						select top 1 @getBarcode=Barcode,@getResult=Result,@getResultTimestamp=ResultTimestamp from #TEMP_CURRENT_RUNING_BARCODE_DATA 
						

						insert into #RunningStatus(OperationSeqNo,Barcode,MachineCode,MachineName,Result,ResultTimestamp)
						select distinct tmp.OperationSeqNo,barcode.Barcode,tmp.MachineCode,tmp.MachineName,barcode.ResuLt,barcode.ResultTimestamp 
						from  #TEMP_RUNNING_LINE_DETAILS tmp inner join #TEMP_CURRENT_RUNING_BARCODE_DATA barcode
						on barcode.MachineCode=tmp.MachineCode
						where barcode.Barcode=@getBarcode
						--where tmp.MachineCode in (
						--select distinct MachineCode from #TEMP_CURRENT_RUNING_BARCODE_DATA 
						--where Barcode=@getBarcode
						--)
						
						insert into #RunningStatus(OperationSeqNo,Barcode,MachineCode,MachineName,Result,ResultTimestamp)
						select OperationSeqNo,@getBarcode,MachineCode,MachineName,'BYPASS','1900-01-01 00:00:00' 
						from  #TEMP_RUNNING_LINE_DETAILS where MachineCode in (
						select distinct machineCode from #TEMP_RUNNING_LINE_DETAILS where machineCode not in(
						select distinct machineCode from #TEMP_CURRENT_RUNING_BARCODE_DATA	where Barcode=@getBarcode)
						and OperationSeqNo < (select max(OperationSeqNo) from #TEMP_CURRENT_RUNING_BARCODE_DATA	where Barcode=@getBarcode)
						)
					
						delete from #TEMP_CURRENT_RUNING_BARCODE_DATA where Barcode=@getBarcode

				end
				--Ended By Sachin 20170822
				--SELECT * FROM #RunningStatus  Order By OperationSeqNo
			-- Commented by sachin 20170822 -- Due to BYPASS --Station Overlap on Each Other
			--SELECT DISTINCT
			--	R.OperationSeqNo,
			--	ISNULL(A.Barcode, '') Barcode,
			--	ISNULL(A.MachineCode, '') MachineCode,
			--	M.MachineName AS MachineName,
			--	(CASE
			--		WHEN ISNULL(A.Status,'') = '' THEN ''
			--		ELSE (CASE
			--				WHEN A.Status = 'PS' THEN 'PASS'
			--				ELSE 'FAIL'
			--			END)
			--	END) ResuLt,
			--	ISNULL(A.ResultTimestamp, '') ResultTimestamp INTO #RunningStatus
			--FROM (SELECT
			--	L.*
			--FROM RoutingConfigLineWise (NOLOCK) L
			--INNER JOIN RoutingConfigPartWise (NOLOCK) P
			--	ON L.ProfitCenterCode = P.ProfitCenterCode
			--	AND L.OperationCode = P.OperationCode
			--	AND L.MachineCode = P.MachineCode
			--WHERE L.LineCode = @LineCode
			--AND P.PartNo = @PartNo
			----AND L.TraceabiLity = 1 //Commented By Sachin 20170822
			----AND P.TraceabiLity = 1 //Commented By Sachin 20170822
			--) R
			--LEFT OUTER JOIN Assy_VIEW_Both_LineAssyStatus_Data(NOLOCK) A
			--	ON A.LineCode = R.LineCode
			--	AND A.MachineCode = R.MachineCode
			--inner JOIN machinemst(NOLOCK) M
			--	ON A.MachineCode = M.MachineCode and a.profitcentercode=m.profitcentercode
			--WHERE A.LineCode = @LineCode
			--AND A.Datecode = @DateCode
			--AND A.PartNo = @PartNo
			--AND M.isActive = 1
			--and m.profitcentercode=@ProfitCenterCode 
			--AND A.IsTaLLyChartApproved = 0
			--Order By R.OperationSeqNo
							
			DECLARE @TempRunning AS TABLE (
				MachineCode VARCHAR(20),
				Barcode VARCHAR(60),
				Record INT
			)
		
			INSERT INTO @TempRunning (MachineCode, Barcode, Record)
				SELECT
					MachineCode,
					Barcode,
					COUNT(Barcode)
				FROM #RunningStatus(NOLOCK)
					GROUP By	MachineCode,Barcode
						HAVING COUNT(Barcode) > 1
				
				
				
			DELETE Running_Temp
				FROM #RunningStatus Running_Temp
				INNER JOIN @TempRunning TV
					ON Running_Temp.MachineCode  collate  Latin1_General_CI_AI = TV.MachineCode collate  Latin1_General_CI_AI
					AND Running_Temp.Barcode  collate  Latin1_General_CI_AI = TV.Barcode collate  Latin1_General_CI_AI
			WHERE Running_Temp.ResuLt = 'FaiL'
		
				
			SELECT
				@Cols = STUFF((SELECT
					',' + QUOTENAME(Col + '_' + CAST(Seq AS VARCHAR(10)))
				FROM (SELECT
					ROW_NUMBER() OVER (Partition By Barcode
					Order By OperationSeqNo) Seq
				FROM #RunningStatus) T
				CROSS APPLY (SELECT
					'MachineName',
					1
				UNION ALL
				SELECT
					'ResuLt',
					2
				UNION ALL
				SELECT
					'ResultTimestamp',
					3) c (Col, So)
				GROUP By	Col,Seq,So
				Order By Seq, So
				FOR xml PATH (''), TYPE)
				.value('.', 'NVARCHAR(MAX)')
				, 1, 1, '')

				
		
				--drop tabLe test
				SET @Query = 'SELECT Barcode ,' + @Cols + ' 
							FROM 
							(
							 SELECT Barcode, 
								Col = Col+''_''+cast(Seq AS VARCHAR(10)), 
								value
							 FROM
							 (
								SELECT Barcode, MachineName , ResuLt,CONVERT(VARCHAR,ResultTimestamp,120)ResultTimestamp,
								 row_number() OVER(Partition By Barcode
													Order By OperationSeqNo ) Seq
								FROM #RunningStatus
							 ) SRC
							 CROSS APPLY
							 (
       
								SELECT ''MachineName'',MachineName UNION ALL
								SELECT ''ResuLt'', ResuLt UNION ALL
								SELECT ''ResultTimestamp'', CONVERT(VARCHAR(100), ResultTimestamp) 
							 ) c (Col, value)
							) x
							pivot 
							(
								MAX(value)
								for Col in (' + @Cols + ')
							) P '

				EXECUTE sp_EXECutesqL @Query

			IF OBJECT_ID('tempdb..#RunningStatus', 'U') IS NOT NULL
				DROP TABLE #RunningStatus
			
				SET @ReturnInt = 1
				SET @ReturnVaLue = 'SuccessfuLLy'
		END
	END

	IF @CONDITION = 'GET_ACTIVE_STATION'
	BEGIN

		SELECT DISTINCT
		    R.ProfitCenterCode,
			R.LineCode,
			R.MachineCode,
			M.MachineName,
			R.OperationSeqNo
		FROM (SELECT
				L.ProfitCenterCode,
				L.LineCode,
				L.MachineCode,
				L.OperationSeqNo
			FROM RoutingConfigLineWise(NOLOCK) L
				INNER JOIN RoutingConfigPartWise(NOLOCK) P
					ON L.ProfitCenterCode = P.ProfitCenterCode
						AND L.OperationCode = P.OperationCode
							AND L.MachineCode = P.MachineCode
								WHERE L.LineCode = @LineCode
									AND P.PartNo = (SELECT
													Top 1 Assy_PartNo
													FROM Assy_RunningPart (NOLOCK)
														WHERE LineCode = @LineCode)
													--AND L.TraceabiLity = 1			//Commented By Sachin 20170822
														--AND P.TraceabiLity = 1		//Commented By Sachin 20170822
														) R
															INNER JOIN MachineMst M (NOLOCK)
																ON M.MachineCode = R.MachineCode
																and M.profitcentercode=r.ProfitCenterCode
																 where M.profitcentercode=@profitcentercode
																	Order By R.OperationSeqNo
		SET @ReturnInt = 1
		SET @ReturnVaLue = 'Success'

		RETURN
	END
END


GO
/****** Object:  StoredProcedure [dbo].[ASSY_PROC_PART_ROUTING_WASHING]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[ASSY_PROC_PART_ROUTING_WASHING]
(
@PROFITCENTERCODE varchar(20)=NULL,
@LINECODE varchar(20)=NULL,
@LINEDESCRIPTION varchar(50)=NULL,
@CONDITION varchar(50),
@RETURNVALUE VARCHAR (2000)=NULL OUT,
@RETURNINT INT=NULL OUT
)
AS
BEGIN
	BEGIN TRY
		IF @CONDITION='GetLineCode'
			SELECT LineCode,LineName FROM LINEMST WHERE ProfitCenterCode=@PROFITCENTERCODE
			
			SET @RETURNVALUE='DATA SELECTED'
			SET @RETURNINT=1

		IF @CONDITION ='SearchLineCode'
			BEGIN
			SELECT LineCode,LineName 
			FROM LINEMST 
			WHERE ProfitCenterCode=@PROFITCENTERCODE AND LineCode LIKE '%' + @LINECODE + '%' AND LineName LIKE '%' + @LINEDESCRIPTION + '%'
			ORDER BY LineCode
		
			SET @RETURNVALUE='DATA SEARCHED'
			SET @RETURNINT=1
			END

		IF @CONDITION='GetPartCode'
			SELECT DISTINCT L.LineCode,L.OperationCode,P.PartNo,PM.product_nm As Product_Description
			FROM RoutingConfigLineWise(NOLOCK) L
			INNER JOIN RoutingConfigPartWise(NOLOCK) P ON L.ProfitCenterCode=p.ProfitCenterCode 
			                                           AND l.OperationCode =p.OperationCode   
													   AND l.MachineCode =p.MachineCode
													   AND l.OperationSeqNo =p.OperationSeqNo 
            LEFT OUTER JOIN PRODUCT_MASTER PM ON P.PartNo=PM.SEWS_PART_NO                       
            WHERE L.LineCode =@LINECODE AND L.OperationRequired =1 AND l.Traceability =1 
			AND p.OperationRequired =1 and p.Traceability =1 AND L.ProfitCenterCode=@PROFITCENTERCODE

			SET @RETURNVALUE='DATA SELECTED'
			SET @RETURNINT=1
 	END TRY

	BEGIN CATCH
			--CATCH BLOCK BEGINS
			SET @RETURNVALUE =	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
			CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
			CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
			CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
			CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
			CAST(ERROR_MESSAGE() AS VARCHAR(1500))
			SET @RETURNINT = 2
            --CATCH BLOCK ENDS 
	END CATCH
END
