/****** Object:  StoredProcedure [dbo].[ASSY_PROC_PARTROUTINGDEFINITION]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[ASSY_PROC_PARTROUTINGDEFINITION] 
(
@TBLROUTINGPART TBLROUTINGCONFIGPARTWISE READONLY,
@PART_NO VARCHAR(60) = NULL,
@PROFITCENTERCODE VARCHAR(10) = '0021',
@OPERATIONCODE VARCHAR(10) = NULL,
@MACHINECODE VARCHAR(10) = NULL,
@OPERATIONNAME VARCHAR(50) = NULL,
@CONDITION VARCHAR(50),
@LINECODE VARCHAR(20) = NULL,
@USERNAME VARCHAR(50) = NULL,
@RETURNVALUE VARCHAR(2000) = NULL OUT,
@RETURNINT INT = NULL OUT,
@ISLocal BIT = 0
)
AS
BEGIN
	DECLARE @COUNTMASTER INT = 0;
	DECLARE @INVALIDMACHINECODE VARCHAR(100) = '';
	Declare @MachineLinkServerName varchar(100)						-- ADDED BY Rashid 20190424
				, @MachineLinkServerDB varchar(100)						-- ADDED BY Rashid 20190424
				, @MachineLinkServer varchar(300)						-- ADDED BY Rashid 20190424
				, @MachineDBRoutingLineWiseTableName varchar(100)		-- ADDED BY Rashid 20190424
				, @MachineDBRoutingPartWiseTableName varchar(100)		-- ADDED BY Rashid 20190424
				, @MachineDBPokaYokeMasterTableName varchar(100)		-- ADDED BY Rashid 20190424
				, @LinkServerType VARCHAR(60) = ''						-- ADDED BY Rashid 20190424
				, @Dynamic_Query VARCHAR(MAX) = ''						-- ADDED BY Rashid 20190424
				, @PartNo VARCHAR(50) = ''								-- ADDED BY Rashid 20190424

	SET NOCOUNT ON

	--EXEC ASSY_PROC_PARTROUTINGDEFINITION @CONDITION='GETPARTNO',@LINECODE='S04',@PROFITCENTERCODE='0021'
	IF @CONDITION = 'GETPARTNO'
	BEGIN
		DECLARE @LINETYPENAME VARCHAR(20)

		SELECT TOP 1
			@LINETYPENAME = LINETYPENAME
		FROM LINEMST(NOLOCK) LM
		INNER JOIN LINETYPEMST(NOLOCK) LTM
			ON LM.LINETYPECODE = LTM.LINETYPECODE
		WHERE LINECODE = @LINECODE

		IF @LINETYPENAME = 'TMC'
		BEGIN
			SELECT DISTINCT
				SEWS_PART_NO AS [PART NO],
				PRODUCT_NM AS [PART DESCRIPTION]
			FROM PRODUCT_MASTER(NOLOCK) PM
			INNER JOIN ROUTINGCONFIGPARTWISE(NOLOCK) RP
				ON RTRIM(LTRIM(PM.SEWS_PART_NO)) =
				RTRIM(LTRIM(RP.PARTNO))
			WHERE ISNULL(PM.MATERIAL_TP, '') = 'TMC'
			AND WAREHOUSE_CD = @PROFITCENTERCODE
			ORDER BY SEWS_PART_NO
		END
		ELSE
		IF @LINETYPENAME = 'STMC'
		BEGIN
			SELECT DISTINCT
				SEWS_PART_NO AS [PART NO],
				PRODUCT_NM AS [PART DESCRIPTION]
			FROM PRODUCT_MASTER(NOLOCK) PM
			INNER JOIN ROUTINGCONFIGPARTWISE(NOLOCK) RP
				ON RTRIM(LTRIM(PM.SEWS_PART_NO)) =
				RTRIM(LTRIM(RP.PARTNO))
			WHERE ISNULL(PM.MATERIAL_TP, '') IN ('SERVO', 'STMC')
			AND WAREHOUSE_CD = @PROFITCENTERCODE
			ORDER BY SEWS_PART_NO
		END

		SET @RETURNVALUE = 'DATA SELECTED'
		SET @RETURNINT = 1

		RETURN
	END

	IF @CONDITION = 'SEARCHPARTNO'
	BEGIN
		SELECT DISTINCT
			SEWS_PART_NO AS [PART NO],
			PRODUCT_NM AS [PART DESCRIPTION]
		FROM PRODUCT_MASTER
		WHERE SEWS_PART_NO LIKE '%' + @PART_NO + '%'
		ORDER BY SEWS_PART_NO

		SET @RETURNVALUE = 'DATA SELECTED'
		SET @RETURNINT = 1
	END

	IF @CONDITION = 'GETDATAFORPARTICULARPARTNO'
	BEGIN
		SELECT
			R.OPERATIONCODE,
			OPERATIONNAME,
			OPERATIONSEQNO,
			R.MACHINECODE,
			OPERATIONREQUIRED,
			TRACEABILITY,
			RECIPE,
			LABELPRINTING,
			TORQUE,
			ENGRAVING,
			POKA_YOKE_ALLOWED,
			M.NOOFSTATIONS
		FROM ROUTINGCONFIGPARTWISE R
		INNER JOIN MACHINEMST M
			ON M.MACHINECODE = R.MACHINECODE
			AND M.PROFITCENTERCODE = R.PROFITCENTERCODE
		INNER JOIN OPERATIONMST O
			ON R.OPERATIONCODE = O.OPERATIONCODE
			AND M.PROFITCENTERCODE = O.PROFITCENTERCODE
		WHERE PARTNO = @PART_NO
		AND R.PROFITCENTERCODE = @PROFITCENTERCODE
		ORDER BY OPERATIONSEQNO,
		R.PROFITCENTERCODE

		SET @RETURNVALUE = 'DATA SELECTED'
		SET @RETURNINT = 1
	END

	IF @CONDITION = 'UPDATEDDATA'
	BEGIN
	BEGIN TRY
		BEGIN TRAN--TRY TRAN BEGINS 

			CREATE TABLE #TBLVALIDATE (
				MACHINECODE VARCHAR(10)
			);

			SELECT
				* INTO #TBLROUTING
			FROM @TBLROUTINGPART;

			INSERT INTO #TBLVALIDATE
				SELECT
					#TBLROUTING.NEWMACHINECODE
				FROM	#TBLROUTING,
							MACHINEMST
				WHERE #TBLROUTING.MACHINECODE = MACHINEMST.MACHINECODE
				AND #TBLROUTING.NEWMACHINECODE NOT IN (SELECT
					MACHINECODE
				FROM MACHINEMST
				WHERE ISACTIVE = 1)
				AND #TBLROUTING.PROFITCENTERCODE =
				MACHINEMST.PROFITCENTERCODE;

			SELECT
				@COUNTMASTER = COUNT(*)
			FROM #TBLVALIDATE
			WHERE MACHINECODE IS NOT NULL;

			SELECT
				*
			FROM #TBLVALIDATE;

			SELECT
				*
			FROM #TBLROUTING;

			IF (@COUNTMASTER = 0)
			BEGIN
				UPDATE ROUTINGCONFIGPARTWISE
				SET	ROUTINGCONFIGPARTWISE.MACHINECODE =
																									CASE
																										WHEN
																											#TBLROUTING.NEWMACHINECODE <> '' THEN #TBLROUTING.NEWMACHINECODE
																										ELSE #TBLROUTING.MACHINECODE
																									END,
						ROUTINGCONFIGPARTWISE.OPERATIONREQUIRED =
						#TBLROUTING.OPERATIONREQUIRED,
						ROUTINGCONFIGPARTWISE.TRACEABILITY = #TBLROUTING.TRACEABILITY,
						ROUTINGCONFIGPARTWISE.RECIPE = #TBLROUTING.RECIPE,
						ROUTINGCONFIGPARTWISE.LABELPRINTING = #TBLROUTING.LABELPRINTING,
						ROUTINGCONFIGPARTWISE.TORQUE = #TBLROUTING.TORQUE,
						ROUTINGCONFIGPARTWISE.ENGRAVING = #TBLROUTING.ENGRAVING,
						ROUTINGCONFIGPARTWISE.POKA_YOKE_ALLOWED =
						#TBLROUTING.POKA_YOKE_ALLOWED
				--ROUTINGCONFIGPARTWISE.OPERATIONSEQNO= #TBLROUTING.OPERATIONSEQNO 
				FROM ROUTINGCONFIGPARTWISE,
				#TBLROUTING
				WHERE ROUTINGCONFIGPARTWISE.PROFITCENTERCODE =
				#TBLROUTING.PROFITCENTERCODE
				AND ROUTINGCONFIGPARTWISE.OPERATIONCODE = #TBLROUTING.OPERATIONCODE
				AND ROUTINGCONFIGPARTWISE.PARTNO = #TBLROUTING.PARTNO
				AND ROUTINGCONFIGPARTWISE.MACHINECODE = #TBLROUTING.MACHINECODE;

				SET @RETURNVALUE = 'DATA SAVED'
				SET @RETURNINT = 1
			END
			ELSE
			BEGIN
				SET @INVALIDMACHINECODE = (SELECT TOP 1
					MACHINECODE #TBLVALIDATE
				FROM #TBLVALIDATE)
				SET @RETURNVALUE = 'INVALID MACHINE CODE:'
				+ @INVALIDMACHINECODE
				SET @RETURNINT = 4
			END

		COMMIT TRAN--TRY TRAN END   
		IF @ISLocal = 1
		BEGIN
			IF EXISTS
			(
				SELECT TOP 1 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
					AND LineCode = @LineCode AND KeyType = 'IsPushMasterDataIntoMESServerOnSetParameter' AND ISNULL(KeyValue,'0') = '1'
			)
			BEGIN
				SELECT TOP 1 @MachineLinkServerName = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode 
					AND LineCode = @LineCode AND KeyType = 'MachineDBLinkServerName' AND STS_CD = 0
				
				IF(ISNULL(@MachineLinkServerName,'') = '' )
				BEGIN
					SET @ReturnValue = 'Machine Link Server Name Configuration Not Found !! [RoutingConfigDetails Key: MachineDBLinkServerName] '
					SET @ReturnInt = 2
					RETURN
				END

				SELECT TOP 1 @MachineLinkServerDB = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
					AND LineCode = @LineCode AND KeyType = 'MachineDBLinkServerDB' AND STS_CD = 0

				IF(ISNULL(@MachineLinkServerDB,'') = '' )
				BEGIN
					SET @ReturnValue = 'Machine Link Server Database Configuration Not Found !! [RoutingConfigDetails Key: MachineDBLinkServerDB]'
					SET @ReturnInt = 2
					RETURN
				END

				SELECT TOP 1 @MachineDBRoutingPartWiseTableName = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
					AND LineCode = @LineCode AND KeyType = 'MachineDBRoutingPartWiseTableName' AND STS_CD = 0

				IF(ISNULL(@MachineDBRoutingPartWiseTableName,'') = '' )
				BEGIN
					SET @ReturnValue = 'Link Server Routing Part Wise Table Configuration Not Found !! [RoutingConfigDetails Key: MachineDBRoutingPartWiseTableName] '
					SET @ReturnInt = 2
					RETURN
				END

				SELECT TOP 1 @LinkServerType = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
					AND LineCode = @LineCode AND KeyType = 'LinkServerType' AND STS_CD = 0

				IF(ISNULL(@LinkServerType,'') = '' )
				BEGIN
					SET @ReturnValue = 'Link Server Type Parameter Configuration Not Found !! [RoutingConfigDetails Key: LinkServerType] '
					SET @ReturnInt = 2
					RETURN
				END

				BEGIN TRY
					Declare @s sysname = REPLACE(REPLACE(@MachineLinkServerName,'[',''),']','')
					EXEC sys.sp_testlinkedserver @s
				END TRY
				BEGIN CATCH
					SET @ReturnValue = 'Kindly Check, Not Able To Connect MES SQL Server !!! ' + @MachineLinkServerName
					SET @ReturnInt = 2
					RETURN
				END CATCH

				IF(@LinkServerType = 'MSSQL')
				BEGIN
					SET @MachineLinkServer = @MachineLinkServerName + '.' + @MachineLinkServerDB
					SET @MachineLinkServer = REPLACE(@MachineLinkServer,'TABLE_NAME',@MachineDBRoutingPartWiseTableName)
					PRINT 'RoutingConfigPartWise - LinkServer - ' + @MachineLinkServer

					EXEC Assy_Proc_PushMasterDataIntoMES @MachineLinkServer = @MachineLinkServer, @ProfitCenterCode = @ProfitCenterCode, @LineCode = @LineCode,
						@Condition = 'RoutingConfigPartWise', @PartNo = @PART_NO
				END

				IF(@LinkServerType = 'MYSQL')
				BEGIN
					PRINT 'MYSQL Connection Code Required'
				END
			END
		END
	END TRY

	BEGIN CATCH
		--CATCH BLOCK BEGINS 
		SET @RETURNVALUE = CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|'
		+ CAST(ERROR_SEVERITY() AS VARCHAR(5)) + '|'
		+ CAST(ERROR_STATE() AS VARCHAR(5)) + '|'
		+ CAST(ERROR_PROCEDURE() AS VARCHAR(200))
		+ '|' + CAST(ERROR_LINE() AS VARCHAR(5)) +
		'|'
		+ CAST(ERROR_MESSAGE() AS VARCHAR(1500))
		SET @RETURNINT = 2

		ROLLBACK TRAN

		RAISERROR (@RETURNVALUE, 16, 1)
	END CATCH
	END

	IF @CONDITION = 'SEARCHSELECTEDDATA'
	BEGIN
		SELECT
			ROW_NUMBER()
			OVER (
			ORDER BY RC.OPERATIONCODE) SNO,
			UPPER(RC.PROFITCENTERCODE) PROFITCENTERCODE,
			UPPER(RC.PARTNO) PARTNO,
			UPPER(RC.OPERATIONCODE) OPERATIONCODE,
			UPPER(O.OPERATIONNAME) OPERATIONNAME,
			UPPER(RC.MACHINECODE) MACHINECODE,
			UPPER(M.MACHINENAME) MACHINENAME,
			OPERATIONSEQNO,
			OPERATIONREQUIRED,
			TRACEABILITY,
			RECIPE,
			LABELPRINTING,
			TORQUE,
			POKA_YOKE_ALLOWED,
			ENGRAVING,
			M.NOOFSTATIONS,
			RC.ENT_BY AS [ENT_BY],
			RC.ENT_STAMP,
			RC.LAST_UPD_BY AS [LAST_UPD_BY],
			RC.LAST_UPD_STAMP
		FROM ROUTINGCONFIGPARTWISE(NOLOCK) RC
		INNER JOIN MACHINEMST M
			ON RC.MACHINECODE = M.MACHINECODE
			AND RC.PROFITCENTERCODE = M.PROFITCENTERCODE
		INNER JOIN OPERATIONMST O
			ON RC.OPERATIONCODE = O.OPERATIONCODE
			AND RC.PROFITCENTERCODE = O.PROFITCENTERCODE
		WHERE RC.PROFITCENTERCODE = @PROFITCENTERCODE
		AND RC.PARTNO = @PART_NO
		AND RC.OPERATIONCODE LIKE '%' + @OPERATIONCODE + '%'
		AND O.OPERATIONNAME LIKE '%' + @OPERATIONNAME + '%'
		AND RC.MACHINECODE LIKE '%' + @MACHINECODE + '%'
		ORDER BY RC.PROFITCENTERCODE,
		OPERATIONSEQNO,
		RC.OPERATIONCODE

		SET @RETURNVALUE = 'DATA SEARCHED'
		SET @RETURNINT = 1
	END
--END 
END

GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_PLCIntegration]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
