CREATE PROCEDURE [dbo].[Assy_Proc_PLCIntegration]
	@ID INT = NULL, 
	@ProfitCode VARCHAR(10) = NULL, 
	@Operation VARCHAR (200) = NULL, 
	@MachineCode VARCHAR(20) = NULL, 
	@OperationCode VARCHAR(20) = NULL, 
	@Part_No VARCHAR(10) = NULL, 
	@LineCode VARCHAR(10) = NULL, 
	@ZigStatus BIT = NULL, 
	@StationCode VARCHAR(10) = '1', 
	@TagName VARCHAR(50) = NULL, 
	@TagValue VARCHAR(20) = NULL, 
	@Barcode VARCHAR(100) = NULL, 
	@IsCycleStarted BIT = NULL, 
	@DateCode VARCHAR(10) = NULL, 
	@IsDuplicate BIT = NULL, 
	@IsIncorrect BIT = NULL, 
	@Status VARCHAR(10) = NULL, 
	--Added By RS On 30th Sep 2016 For Nissan Line 6 To be Merge
	@SensorPosition CHAR(2) = NULL, 
	@EngraveStatus BIT = NULL, 
	@CNCRequiredStatus BIT = NULL, 
	@Is_Torque1_OK BIT = NULL, 
	@Is_Torque2_OK BIT = NULL, 
	@Torque1 VARCHAR(20) = NULL, 
	@Torque2 VARCHAR(20) = NULL, 
	@IsNissan SMALLINT = NULL, 
	@tblParameters dbo.Assy_TYPE_LineAssyParamData_Running ReadOnly, 
	--Added By RS On 05th Dec 2016 For Bypasa/unbypass authentication
	@UserName VARCHAR(20) = NULL, 
	@Remark VARCHAR(MAX) = NULL, 
	@StationName VARCHAR(100) = NULL, 
	@IsBypass BIT = NULL, 
	--Added By RS On 20180725 For TMC Part Cap Color 
	@CapColorCode INT = NULL, -- | 0-Default,1-NoColor,2-Black,3-Yellow
	@Is_Vision_OK INT = 0,
	@TorqueAngle1 VARCHAR(20) = NULL, 
	@TorqueAngle2 VARCHAR(20) = NULL, 

	@ReturnValue VARCHAR (2000) = NULL OUT, 
	@ReturnInt INT = NULL OUT
	
	/* = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = 
	 Author:		<Manoj Kumar>
	 Create date:	<06 June 2015>
	 Description:	<To know at which stages PLCs are involved to capture data>

	 Modified By:	<Rashid Siddiqui>
	 Modified ON:	<16-Dec-2016>
	 Description:	<Modified for Bypass/unbypass Authentication>
	 Description:	<Modified for Line 6 MBA Performance>
	 Description:	<Modified for FS Line 1 AND 2 For Reservoir Testing Station IF Vaccum Drop AND Air Drop is Zero>
	 Modified ON:	<09-Feb-2017>
	 Description:	<Add Rubesh Email Id in Bypass/Unbypass Alert>
	 Modified By:	< Sudesh Kumar > 
	 Modified ON:	< 20170515 > 
	 Description:	< Added column ProductionOrderNo in Table Assy_LineAssyStatus_Running for mapping of Production Order WITH Barcode >
	 Modified By:	< Rashid Siddiqui > 
	 Modified ON:	< 20170713 > 
	 Description:	< Added Torque in SELECT Statement >
	 Modified ON:	< 20170816 >
	 Description:	< Added ScanTimeStamp On Pass/Fail Barcode >
	 Modified ON:	< 20170822 >
	 Description:	< Changed for Servo Line 1 Crimping Logic >
	 Modified ON:	< 20180725 >
	 Description:	< Changed For TMC Part Cap Color | 0-Default,1-NoColor,2-Black,3-Yellow >
	 Modified ON:	< 20190726 >
	 Description:	< Offline HP Leak Test >
	 Modified ON:	< 17-Oct-2019 BY RS >
	 Description:	< Pin Pressing for TMC Lines >
	 = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = */
AS
BEGIN
	DECLARE @OpRequired BIT = NULL
	, @TraceabilityRequired BIT = NULL
	, @FailCount INT = 0
	, @PokaYokeDateCode VARCHAR(20)
	--, @IsTwinIndex BIT = 0
	, @ScannedStationIndex INT
	, @InsideStationIndex VARCHAR(10)
	, @UserID VARCHAR(20) = ''
	, @LinkServerName VARCHAR(500) = ''
	, @ExecQuery NVARCHAR(MAX) = ''

	SET NOCOUNT ON;
	BEGIN TRY
		-- Added By Rashid on 9th Sep 2016 to remove hard coded Machine Code
		Declare @CrimpingMachineCode VARCHAR(30) = '', @PerformanceMachineCode VARCHAR(30) = '', @MBAPerformanceMachineCode VARCHAR(30) = '', 
				@CrimpingOperationCode VARCHAR(30) = '', @PerformanceOperationCode VARCHAR(30) = '', @MBAPerformanceOperationCode VARCHAR(30) = '',
				--Added By Rashid on 04th Oct 2017 For Centre Shell Crimping Station
				@CentreShellCrimpingMachineCode VARCHAR(30) = '', @CentreShellCrimpingOperationCode VARCHAR(30) = '',
				@CustomerPartNo VARCHAR(50) = '',
				@IsReservoirKeyVal INT = 0
			
			--------------------Added by Prerna on Live_datecode change
				if(isnull(@ProfitCode,'')='')
				begin
				  select @ProfitCode=ProfitCenterCode from Linemst with(nolock) where linecode=@LineCode
				end

				Declare	@Live_Datecode char(4),@return_int int
				exec Assy_proc_datecode @ProfitCode,@Live_Datecode out,@return_int out
			-------------------------end
					
		--Added By Rashid on 04th Oct 2017 For Centre Shell Crimping Station
		SELECT @CentreShellCrimpingMachineCode = dbo.ASSY_FN_GET_PARAMETER_VALUE('AssLine', 'CentreShellCrimping', 'MachineCode', @ProfitCode)

		IF ISNULL(@CentreShellCrimpingMachineCode, '') = ''
			SET @CentreShellCrimpingMachineCode = 'MCCSCR'

		SELECT @CentreShellCrimpingOperationCode = dbo.ASSY_FN_GET_PARAMETER_VALUE('AssLine', 'CentreShellCrimping', 'OperationCode', @ProfitCode)

		IF ISNULL(@CentreShellCrimpingOperationCode, '') = ''
			SET @CentreShellCrimpingOperationCode = 'OCCSCR'

		--END Added By Rashid on 04th Oct 2017 For Centre Shell Crimping Station

		SELECT @CrimpingMachineCode = dbo.ASSY_FN_GET_PARAMETER_VALUE('AssLine', 'Crimping', 'MachineCode', @ProfitCode)

		IF ISNULL(@CrimpingMachineCode, '') = ''
			SET @CrimpingMachineCode = 'MCCRMP'

		SELECT @CrimpingOperationCode = dbo.ASSY_FN_GET_PARAMETER_VALUE('AssLine', 'Crimping', 'OperationCode', @ProfitCode)

		IF ISNULL(@CrimpingOperationCode, '') = ''
			SET @CrimpingOperationCode = 'OCCRMP'

		SELECT @PerformanceMachineCode = dbo.ASSY_FN_GET_PARAMETER_VALUE('AssLine', 'Finalviewing', 'Servo_Performance_MachineCode', @ProfitCode)

		IF ISNULL(@PerformanceMachineCode, '') = ''
			SET @PerformanceMachineCode = 'MCSVPR'

		SELECT @PerformanceOperationCode = dbo.ASSY_FN_GET_PARAMETER_VALUE('AssLine', 'Finalviewing', 'Servo_Performance_OperationCode', @ProfitCode)
		
		IF ISNULL(@PerformanceOperationCode, '') = ''
			SET @PerformanceOperationCode = 'OCSVPR'

		SELECT @MBAPerformanceMachineCode = dbo.ASSY_FN_GET_PARAMETER_VALUE('AssLine', 'MBA_Performance', 'MachineCode', @ProfitCode)

		IF ISNULL(@MBAPerformanceMachineCode, '') = ''
			SET @MBAPerformanceMachineCode = 'MCMBAPR'
		
		SELECT @MBAPerformanceOperationCode = dbo.ASSY_FN_GET_PARAMETER_VALUE('AssLine', 'MBA_Performance', 'OperationCode', @ProfitCode)
		
		IF ISNULL(@MBAPerformanceOperationCode, '') = ''
			SET @MBAPerformanceOperationCode = 'OCMBAPR'

		IF(ISNULL(@LineCode, '') <> '')
		BEGIN
			SELECT Top 1 @Part_No = ISNULL(Assy_PartNo, ''), @DateCode = Datecode, @UserID = CreatedBy, @CustomerPartNo = CustomerPartNo FROM Assy_RunningPart WITH (NOLOCK)
				WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCode --ORDER By CreatedBy Desc

			IF ISNULL(@DateCode,'') = ''
			BEGIN
				DECLARE @CurrDateCode CHAR(10) 
				EXEC Assy_Proc_DateCode @ProfitCenterCode = @ProfitCode, @ReturnValue = @CurrDateCode output
				SET @DateCode = @CurrDateCode
				--SELECT @CurrDateCode
			END
		END

		-- Added By Rashid On 20170713 - Torque Column
		IF(@Operation = 'GET_CHANNEL_DEVICE_DETAILS')
		BEGIN
			SELECT A.MachineCode, A.OperationCode, C.ChannelName, C.DeviceName, A.TagName, C.PLCAddress, B.TagSignificance, E.Torque, E.IsTextLogRequired
			,A.KepwareTagName, A.IsExtendedTag, A.IsActive, E.IsOfflineCapturingStation, C.ChannelName + '.' + C.DeviceName + '.' + A.TagName as TagAddress FROM MachineTagMapping (NOLOCK) AS A
			INNER JOIN TagMst (NOLOCK) AS B ON A.TagName = B.TagName AND A.ProfitCenterCode = B.ProfitCenterCode
			INNER JOIN MachineDtl (NOLOCK) AS C ON A.MachineCode = C.MachineCode AND A.ProfitCentercode = C.ProfitCentercode AND A.LineCode = C.LineCode AND A.OperationCode = C.OperationCode
			INNER JOIN MachineMst (NOLOCK) AS D ON A.MachineCode = D.MachineCode
			INNER JOIN RoutingConfigLineWise (NOLOCK) AS E ON A.MachineCode = E.MachineCode AND A.ProfitCentercode = E.ProfitCentercode AND A.LineCode = E.LineCode AND A.OperationCode = E.OperationCode 
			WHERE A.ProfitCentercode = @ProfitCode AND A.MachineCode = @MachineCode AND A.OperationCode = @OperationCode AND A.LineCode = @LineCode
				AND A.IsActive = 1
			ORDER By A.FirstTag Desc
		END

		ELSE IF(@Operation = 'GET_CYCLE_START_STATUS')
		BEGIN
			SELECT @ScannedStationIndex = (SELECT dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
			IF(@ScannedStationIndex = -1)
			BEGIN
				IF((SELECT ISNULL(IsCycleStarted, 0) FROM Assy_Scan_OK WITH (NOLOCK) WHERE LineCode = @LineCode AND MachineCode = @MachineCode
						AND OperationCode = @OperationCode) = 1)
				BEGIN
					SELECT @ReturnValue = 'Y'					
				END
				ELSE
				BEGIN
					SELECT @ReturnValue = 'N'
				END
			END
			ELSE
			BEGIN
				SELECT @ReturnValue = 'N'
			END
			RETURN
		END

		ELSE IF(@Operation = 'GET_ACTIVE_BARCODE_WHILE_CYCLE_START')
		BEGIN
			SELECT @ScannedStationIndex = (SELECT dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
			--IF it is A single jig station
			IF(@ScannedStationIndex = -1)
			BEGIN
				SELECT Top 1 Barcode FROM Assy_Scan_OK WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode
			END
			ELSE
			BEGIN
				IF(@ScannedStationIndex = 1)
					SELECT @InsideStationIndex = 1
				ELSE IF(@ScannedStationIndex = 2)
					SELECT @InsideStationIndex = 2
				
				SELECT Top 1 Barcode FROM Assy_Scan_OK WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode AND StationCode = @InsideStationIndex
			END
		END

		ELSE IF(@Operation = 'GET_ACTIVE_BARCODE_WHILE_PASS')
		BEGIN
			SET @ScannedStationIndex = (SELECT dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
			--IF it is A single jig station
			IF(@ScannedStationIndex = -1)
			BEGIN
				SELECT Top 1 Barcode FROM Assy_Scan_OK WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode
			END
			ELSE
			BEGIN
				IF(@ScannedStationIndex = 1)
					SELECT @InsideStationIndex = 2
				ELSE IF(@ScannedStationIndex = 2)
					SELECT @InsideStationIndex = 1
				
				SELECT Top 1 Barcode FROM Assy_Scan_OK WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode AND StationCode = @InsideStationIndex
			END
		END

		ELSE IF(@Operation = 'LOG_PLC_DATA')
		BEGIN
			INSERT INTO Assy_PLCLogs (ProfitCentercode, LineCode, MachineCode, OperationCode, TagName, TagValue, Ent_Dt, Barcode)
			VALUES (@ProfitCode, @LineCode, @MachineCode, @OperationCode, @TagName, @TagValue, GETDATE(), @Barcode)
		END	
		
		ELSE IF(@Operation = 'GET_PLC_ROUTING')
		BEGIN
			SELECT DISTINCT A.OperationCode, A.MachineCode, B.OperationName, C.OperationSeqNo
			FROM MachineTagMapping (NOLOCK) AS A INNER JOIN OperationMst (NOLOCK) AS B ON A.OperationCode = B.OperationCode 
			INNER JOIN RoutingConfigLineWise (NOLOCK) AS C ON A.OperationCode = C.OperationCode
			WHERE C.LineCode = @LineCode AND A.ProfitCentercode = @ProfitCode AND C.OperationRequired = 1
			ORDER By C.OperationSeqNo
		
			SELECT @ReturnValue = 'Routing Configuration EXISTS', @ReturnInt = 1
		END

		ELSE IF(@Operation = 'GET_RUNNING_PART')
		BEGIN
			SELECT @ReturnValue = @Part_No
			SELECT @Part_No AS Assy_PartNo
		END

		ELSE IF(@Operation = 'IS_BYPASS_ENABLED')
		BEGIN
			SELECT @OpRequired = ISNULL(OperationRequired, 0), @TraceabilityRequired = ISNULL(Traceability, 0)
			FROM RoutingConfigLineWise WITH (NOLOCK) WHERE MachineCode = @MachineCode AND OperationCode = @OperationCode AND ProfitCentercode = @ProfitCode AND LineCode = @LineCode

			IF((@OpRequired = 1) AND (@TraceabilityRequired = 1))
			BEGIN
				SELECT @ReturnValue = 'N'
			END
			ELSE
			BEGIN
				SELECT @ReturnValue = 'Y'
			END
		END

		ELSE IF(@Operation = 'SAVE_INCORRECT_DUPLICATE_HISTORY')
		BEGIN
			PRINT 'HI'
			--INSERT INTO Assy_DuplicateIncorrectHistory(DateCode, ProfitCentercode, LineCode, MachineCode, OperationCode, Barcode, IsDuplicate, IsIncorrect, Ent_Dt)
			--VALUES(@DateCode, @ProfitCode, @LineCode, @MachineCode, @OperationCode, @Barcode, @IsDuplicate, @IsIncorrect, GETDATE())
		END

		ELSE IF(@Operation = 'GET_SCAN_OK_AND_BARCODE')
		BEGIN
			SELECT @ScannedStationIndex = (SELECT dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
			
			IF(@ScannedStationIndex = -1)
				SELECT Barcode, isScan FROM Assy_Scan_OK WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode
			ELSE
			BEGIN
				SELECT Barcode, isScan FROM Assy_Scan_OK WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode 
				AND StationCode = @ScannedStationIndex
			END
		END

		ELSE IF(@Operation = 'IS_INCORRECT_LABEL_SCANNED')
		BEGIN
			SELECT Barcode, isIncorrect FROM Assy_incorrectLabel WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode
		END

		ELSE IF(@Operation = 'IS_DUPLICATE_LABEL_SCANNED')
		BEGIN
			SELECT Barcode, isDuplicate FROM Assy_DuplicateLabel WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode
		END

		ELSE IF(@Operation = 'IS_RETEST_LABEL_SCANNED')
		BEGIN
			SELECT Barcode, IsReTest FROM Assy_ReTestLabel WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode
		END

		ELSE IF(@Operation = 'RESET_SCANOK_DUPLICATE_INCORRECT_FIELDS')
		BEGIN
			SELECT @ScannedStationIndex = (SELECT dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
			IF(@ScannedStationIndex = -1)
			BEGIN
				-- Added By Nelson on 05-05-2016
				IF (@OperationCode != @PerformanceOperationCode)
				BEGIN
					UPDATE Assy_Stations_Zig_In_Out_Status SET StatusInOut = 0 WHERE LineCode = @LineCode AND OperationCode = @OperationCode
				END
			END
			UPDATE Assy_Scan_OK SET isScan = 0, IsCycleStarted = 0 WHERE LineCode = @LineCode AND OperationCode = @OperationCode
			UPDATE Assy_incorrectLabel SET isIncorrect = 0 WHERE LineCode = @LineCode AND OperationCode = @OperationCode
			UPDATE Assy_DuplicateLabel SET isDuplicate = 0 WHERE LineCode = @LineCode AND OperationCode = @OperationCode
			UPDATE Assy_ReTestLabel SET IsReTest = 0 WHERE OperationCode = @OperationCode AND LineCode = @LineCode

			SELECT @ReturnInt = 1
			SELECT @ReturnValue = ISNULL(isScan,'0') FROM Assy_Scan_OK (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode
		END

		ELSE IF(@Operation = 'UPDATE_ZIG_STATUS')
		BEGIN
			SELECT @ScannedStationIndex = (SELECT dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
			--IF these are NOT twin zig stations..
			IF(@ScannedStationIndex = -1)
			BEGIN
				SET @StationCode = '1' 
				IF NOT EXISTS
				(
					SELECT Top 1 1 FROM Assy_Stations_Zig_In_Out_Status WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode
				)
				BEGIN
					INSERT INTO Assy_Stations_Zig_In_Out_Status (LineCode, OperationCode, StationCode, StatusInOut)
					VALUES (@LineCode, @OperationCode, @StationCode, @ZigStatus)

					IF @OperationCode = @CrimpingOperationCode
					BEGIN
						IF (@ZigStatus = 1)
						BEGIN
							SELECT @Barcode = ISNULL(Barcode, '') FROM Assy_Scan_OK WITH (NOLOCK) WHERE OperationCode = @OperationCode AND ISNULL(Barcode, '') != '' AND ISNULL(IsCycleStarted, 0) = 1
							IF @Barcode != ''
							BEGIN
								IF NOT EXISTS (SELECT 1 FROM Assy_Crimp_CycleStartTimeStamp WITH (NOLOCK) WHERE Barcode = @Barcode )
								BEGIN
									INSERT INTO Assy_Crimp_CycleStartTimeStamp (Barcode, CyleStartTimestamp)
									SELECT @Barcode, GETDATE()
								END
								ELSE
								BEGIN
									UPDATE Assy_Crimp_CycleStartTimeStamp SET CyleStartTimestamp = GETDATE() WHERE Barcode = @Barcode
								END
							END	
						END
					END
				END 
				ELSE
				BEGIN
					UPDATE Assy_Stations_Zig_In_Out_Status SET StatusInOut = @ZigStatus, StationCode = @StationCode WHERE LineCode = @LineCode AND OperationCode = @OperationCode
					
					IF @OperationCode = @CrimpingOperationCode
					BEGIN
						IF (@ZigStatus = 1)
						BEGIN
							SELECT @Barcode = ISNULL(Barcode, '') FROM Assy_Scan_OK WITH (NOLOCK) WHERE OperationCode = @OperationCode AND ISNULL(Barcode, '') != '' AND ISNULL(IsCycleStarted, 0) = 1
							IF @Barcode != ''
							BEGIN
								IF NOT EXISTS (SELECT 1 FROM Assy_Crimp_CycleStartTimeStamp WITH (NOLOCK) WHERE Barcode = @Barcode )
								BEGIN
									INSERT INTO Assy_Crimp_CycleStartTimeStamp (Barcode, CyleStartTimestamp)
									SELECT @Barcode, GETDATE()
								END
								ELSE
								BEGIN
									UPDATE Assy_Crimp_CycleStartTimeStamp SET CyleStartTimestamp = GETDATE() WHERE Barcode = @Barcode
								END
							END	
						END
					END
				END 
			END
			ELSE
			BEGIN
				IF NOT EXISTS
				(
					SELECT Top 1 1 FROM Assy_Stations_Zig_In_Out_Status WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode
				)
				BEGIN
					INSERT INTO Assy_Stations_Zig_In_Out_Status (LineCode, OperationCode, StationCode, StatusInOut)
					VALUES (@LineCode, @OperationCode, @StationCode, @ZigStatus)

					IF @OperationCode = @CrimpingOperationCode
					BEGIN
						IF (@ZigStatus = 1)
						BEGIN
							SELECT @Barcode = ISNULL(Barcode, '') FROM Assy_Scan_OK WITH (NOLOCK) WHERE OperationCode = @OperationCode AND ISNULL(Barcode, '') != '' AND ISNULL(IsCycleStarted, 0) = 1
							IF @Barcode != ''
							BEGIN
								IF NOT EXISTS (SELECT 1 FROM Assy_Crimp_CycleStartTimeStamp WITH (NOLOCK) WHERE Barcode = @Barcode )
								BEGIN
									INSERT INTO Assy_Crimp_CycleStartTimeStamp (Barcode, CyleStartTimestamp)
									SELECT @Barcode, GETDATE()
								END
								ELSE
								BEGIN
									UPDATE Assy_Crimp_CycleStartTimeStamp SET CyleStartTimestamp = GETDATE() WHERE Barcode = @Barcode
								END
							END	
						END
					END

					RETURN
				END
				ELSE
				BEGIN
					UPDATE Assy_Stations_Zig_In_Out_Status SET StatusInOut = 1, StationCode = @StationCode WHERE LineCode = @LineCode
						AND OperationCode = @OperationCode

					IF @OperationCode = @CrimpingOperationCode
					BEGIN
						SELECT @Barcode = ISNULL(Barcode, '') FROM Assy_Scan_OK WITH (NOLOCK) WHERE OperationCode = @OperationCode AND ISNULL(Barcode, '') != '' AND ISNULL(IsCycleStarted, 0) = 1
						IF @Barcode != ''
						BEGIN
							IF NOT EXISTS (SELECT 1 FROM Assy_Crimp_CycleStartTimeStamp WITH (NOLOCK) WHERE Barcode = @Barcode )
							BEGIN
								INSERT INTO Assy_Crimp_CycleStartTimeStamp (Barcode, CyleStartTimestamp)
								SELECT @Barcode, GETDATE()
							END
							ELSE
							BEGIN
								UPDATE Assy_Crimp_CycleStartTimeStamp SET CyleStartTimestamp = GETDATE() WHERE Barcode = @Barcode
							END
						END
					END
				END
			END
		END		 

		ELSE IF(@Operation = 'UPDATE_CYCLE_START')
		BEGIN
			SELECT @ScannedStationIndex = (SELECT dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
			
			IF(@ScannedStationIndex = -1)
			BEGIN
				UPDATE Assy_Scan_OK SET IsCycleStarted = @IsCycleStarted WHERE Barcode = @Barcode AND LineCode = @LineCode
					AND OperationCode = @OperationCode AND MachineCode = @MachineCode
				--Changed By Ravi ON 01-02-2016 for Poka Yoke
				IF @IsCycleStarted = 1
				BEGIN							
					EXEC Assy_Proc_UpdatePokaYokeStatus @Condition = 'UPDATE_CYCLE_STARTED_FROM_PLC_PROC', @LineCode = @LineCode, @MachineCode = @MachineCode
					, @OperationCode = @OperationCode, @Barcode = @Barcode
				END
				ELSE IF(@IsCycleStarted = 0)
				BEGIN
					IF(@ScannedStationIndex = -1)
					BEGIN
						--Added By Rashid on 14th July 2016 For Poka Yoke
						IF(@OperationCode = @PerformanceOperationCode AND CHARINDEX('PKYK', @Barcode) > 0)
						BEGIN
							UPDATE Assy_Scan_OK SET Barcode = '' WHERE LineCode = @LineCode AND OperationCode = @OperationCode AND Barcode = @Barcode
						END

						IF(@OperationCode ! = @PerformanceOperationCode)
						BEGIN
							UPDATE Assy_Scan_OK SET Barcode = '' WHERE LineCode = @LineCode AND OperationCode = @OperationCode AND Barcode = @Barcode
						END
					END
				END
			END
			ELSE
			-- Added By Rashid For PokaYoke 21-June-2016
			BEGIN
				UPDATE Assy_Scan_OK SET IsCycleStarted = @IsCycleStarted WHERE Barcode = @Barcode AND LineCode = @LineCode 
					AND OperationCode = @OperationCode AND MachineCode = @MachineCode
				--Changed By Ravi ON 01-02-2016 for Poka Yoke
				IF @IsCycleStarted = 1
				BEGIN							
					EXEC Assy_Proc_UpdatePokaYokeStatus @Condition = 'UPDATE_CYCLE_STARTED_FROM_PLC_PROC', @LineCode = @LineCode, @MachineCode = @MachineCode
					, @OperationCode = @OperationCode, @Barcode = @Barcode
				END
			END
		END	
	 
		ELSE IF(@Operation = 'INSERT_PLC_PARAMS')
		BEGIN 
			DECLARE @Result VARCHAR(10)	
			SELECT DISTINCT @Result = Result, @LineCode = LineCode, @OperationCode = OperationCode, 
				@MachineCode = MachineCode, @Barcode = Barcode, @ProfitCode = ProfitCentercode FROM @tblparameters

			SELECT @ScannedStationIndex = (SELECT dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))

			IF(@ScannedStationIndex <> -1)
			BEGIN
				IF(@ScannedStationIndex = 1)
					SELECT @InsideStationIndex = 2
				ELSE IF(@ScannedStationIndex = 2)
					SELECT @InsideStationIndex = 1
				
				SELECT @Barcode = (SELECT Top 1 Barcode FROM Assy_Scan_OK WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode
									AND StationCode = @InsideStationIndex)
			END
			
			IF ISNULL(@Barcode, '') = ''
				RETURN
			
			--Servo performance should RETURN FROM here.. Another application will read the data FROM excel sheet AND DECLARE the result.
			--Add PokaYoke DateCode CharImdex By Rashid on 28th July 2016
			IF(RTRIM(LTRIM(@OperationCode)) = @PerformanceOperationCode AND CHARINDEX('PKYK', @Barcode) = 0)
			BEGIN
				IF NOT EXISTS
				(
					SELECT 1 FROM Assy_PLC_PerformanceResult WITH (NOLOCK) WHERE Barcode = @Barcode
				)
				BEGIN
					INSERT INTO Assy_PLC_PerformanceResult(Barcode, Result, Ent_Dt) VALUES (@Barcode, @Result, GETDATE())
				END
				--comment By Rashid on 28th July 2016
				--IF (CHARINDEX('PKYK', @Barcode) != 0)
				--BEGIN
				--	UPDATE Assy_LineAssyStatus_Running SET Status = @Result, ResultTimestamp = GETDATE()
				--		WHERE Barcode = @Barcode AND OperationCode = @OperationCode AND LineCode = @LineCode
				--END
				--ELSE
				--BEGIN
					UPDATE Assy_PLC_PerformanceResult SET Result = @Result, Ent_Dt = GETDATE() WHERE Barcode = @Barcode
					UPDATE Assy_LineAssyStatus_Running SET Status = 'PE', ResultTimestamp = GETDATE()  WHERE Barcode = @Barcode AND OperationCode = @OperationCode AND LineCode = @LineCode
					RETURN
				--END
			END

			Declare @MachineConfigValue VARCHAR(100) = ''
			SELECT @MachineConfigValue = dbo.FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE(@ProfitCode,'LINE_ATTRB','RES_VAL_LINE_MACHINE',@LineCode,'')
			SELECT * INTO #MachineConfigTable FROM [dbo].[SplitString] (@MachineConfigValue,',')

			--Add Missing Logic of RESERVOIR TMC Station (added by Prerna on - 10-Jan-2020)
			--IF @MachineCode = 'MCRT'
			IF EXISTS (SELECT 1 FROM #MachineConfigTable WHERE RTRIM(LTRIM(Data)) = @MachineCode)
			BEGIN
				IF @Result = 'PS'
				BEGIN
					SELECT @IsReservoirKeyVal = dbo.FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE(@ProfitCode,'PART_ATTRB','RES_VAL_LINE_PART',@Part_No,'')
					--SELECT @IsReservoirKeyVal = ISNULL(KeyValue,'0') FROM RoutingConfigDetails WITH(NOLOCK)
					--	WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND MachineCode = @MachineCode
					--		AND PartNumber = @Part_No AND KeyType = 'IsReservoirValidationReq'

					IF(@IsReservoirKeyVal != 0)
					BEGIN
						Declare @AirDrop NUMERIC(10, 5) = 0, @VaccumDrop NUMERIC(10, 5) = 0
						
						SELECT Top 1 @AirDrop = ISNULL(A.Value, 0) FROM @tblparameters A INNER JOIN TagMst B WITH (NOLOCK)
							ON A.TagName = B.TagName WHERE ISNULL(Value, '') <> '' AND B.TagId IN (20, 66)

						SELECT Top 1 @VaccumDrop = ISNULL(A.Value, 0) FROM @tblparameters A INNER JOIN TagMst B WITH (NOLOCK)
							ON A.TagName = B.TagName WHERE ISNULL(Value, '') <> '' AND B.TagId IN (53, 99)

						-- 1-Reservoir(Air,Vaccum Drop Check), 2-Adaptor(Vaccum Drop Check), 3-DateCode(No Drop Check)
						IF(@IsReservoirKeyVal = 1 AND @AirDrop = 0 AND @VaccumDrop = 0)
						BEGIN
						 SELECT @Result = 'FL'
						END
						ELSE IF(@IsReservoirKeyVal = 2 AND @VaccumDrop = 0)
						BEGIN
						  SELECT @Result = 'FL'
						END
					END
				END
			END

			/* --Add Missing Logic of FS Line 2 (Check in Old Application WITH Ravi - 09-Dec-2016)
			IF @LineCode IN ('L02','L01')
			BEGIN
				IF @OperationCode IN ('OCRTRH', 'OCRTLH')
				BEGIN
					IF @Result = 'PS'
					BEGIN
						Declare @PartType VARCHAR(50) = ''
						--For Nissan AND Duster Sub Type
						SELECT Top 1 @PartType = ISNULL(PROD_TYPE_CD, '') FROM PRODUCT_MASTER WITH (NOLOCK) WHERE SEWS_PART_NO = @Part_No AND warehouse_cd = @ProfitCode

						IF @PartType = 'NISSAN'
						BEGIN
							Declare @AirDrop NUMERIC(10, 5) = 0, @VaccumDrop NUMERIC(10, 5) = 0
							PRINT 'Wrote Old FS Line 2 Logic Here'
							SELECT Top 1 @AirDrop = ISNULL(A.Value, 0) FROM @tblparameters A INNER JOIN TagMst B WITH (NOLOCK)
								ON A.TagName = B.TagName WHERE ISNULL(Value, '') <> '' AND B.TagId IN (20, 66)

							SELECT Top 1 @VaccumDrop = ISNULL(A.Value, 0) FROM @tblparameters A INNER JOIN TagMst B WITH (NOLOCK)
								ON A.TagName = B.TagName WHERE ISNULL(Value, '') <> '' AND B.TagId IN (53, 99)
							--	Mr. Prasath confirmed this logic On 09th Dec 2016
							--	IF @AirDrop AND @VaccumDrop is zero or not exists then make it fail (It can not be scan in next station)
							IF (@AirDrop = 0 AND @VaccumDrop = 0)
							BEGIN
								SELECT @Result = 'FL'
							END
						END
					END
				END
			END
			*/
			--Added By Rashid On 20170724 to include Torque Data
			DECLARE @IsTorqueRequired BIT = 0
            SELECT @IsTorqueRequired = Torque FROM RoutingConfigLineWise (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode AND ProfitCenterCode = @ProfitCode

			SELECT * INTO #Temp_tblparameters FROM @tblparameters
			
			IF(ISNULL(@IsTorqueRequired,0) = 1)
            BEGIN
				IF EXISTS (SELECT 1 FROM Assy_TorqueDetails (NOLOCK)
                    WHERE Barcode = @Barcode AND OperationCode = @OperationCode AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCode)
				BEGIN
					INSERT INTO #Temp_tblparameters (ProfitCenterCode, LineCode, MachineCode, OperationCode, Barcode, TagName, Value, Result, Datecode, UserID)
					SELECT ProfitCenterCode, LineCode, MachineCode, OperationCode, Barcode, TagName, TagValue, @Result, @DateCode, @UserId FROM Assy_TorqueDetails (NOLOCK)
						WHERE Barcode = @Barcode AND OperationCode = @OperationCode AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCode

					--DELETE FROM Assy_TorqueDetails WHERE Barcode = @Barcode AND OperationCode = @OperationCode AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCode
				END
            END
			--Added By Rashid On 20170816 to include ScanTimeStamp
			DECLARE @UID AS uniqueidentifier, @ScanTimeStamp DateTime
			SET @UID = NEWID()
			/* Commented By RS On 20170724
			INSERT INTO Assy_LineAssyParamData_Running(ProfitCentercode, LineCode, MachineCode, OperationCode, StationCode, Barcode, Result, Datecode, UserID, Timestamp, PartNo, UID)
			SELECT Top 1 ProfitCentercode, LineCode, MachineCode, OperationCode, @StationCode, @Barcode, @Result, @DateCode, @UserID, GETDATE(), @Part_No, @UID
			FROM @tblparameters WHERE ISNULL(Value, '') <> ''
			 
			INSERT INTO Assy_LineAssyParamData_Running_Dtl(UID, TagId, Value)
			SELECT @UID, B.TagId, ISNULL(A.Value, 0) Value FROM @tblparameters A INNER JOIN TagMst B WITH (NOLOCK) ON A.TagName = B.TagName WHERE ISNULL(Value, '') <> ''
			 */

			 --Added By Rashid On 20170816 to include ScanTimeStamp
			SELECT Top 1 @ScanTimeStamp = ScanTimeStamp FROM Assy_LineAssyStatus_Running (NOLOCK) WHERE ProfitCentercode = @ProfitCode
				AND LineCode = @LineCode AND MachineCode = @MachineCode AND OperationCode = @OperationCode AND Barcode = @Barcode

			IF EXISTS (SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND STS_CD = 0 AND KeyType = 'PinPressingLineCode' AND KeyValue = @LineCode)
			BEGIN
				IF @ScanTimeStamp IS NULL
				BEGIN
					SELECT @ScanTimeStamp = Timestamp, @Part_No = PartNo, @UserID = UserID FROM Assy_LineAssyHP (NOLOCK)
						WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND Barcode = @Barcode AND OperationCode = @OperationCode
				END
			END
			
			INSERT INTO Assy_LineAssyParamData_Running(ProfitCentercode, LineCode, MachineCode, OperationCode, StationCode, Barcode, Result, Datecode, UserID, Timestamp, PartNo, UID, ScanTimeStamp,Live_Datecode)
			SELECT Top 1 ProfitCentercode, LineCode, MachineCode, OperationCode, @StationCode, @Barcode, @Result, @DateCode, @UserID, GETDATE(), @Part_No, @UID, @ScanTimeStamp,@Live_Datecode
			FROM #Temp_tblparameters WHERE ISNULL(Value, '') <> ''
			 
			INSERT INTO Assy_LineAssyParamData_Running_Dtl(UID, TagId, Value)
			SELECT @UID, B.TagId, ISNULL(A.Value, 0) Value FROM #Temp_tblparameters A INNER JOIN TagMst B WITH (NOLOCK) ON A.TagName = B.TagName WHERE ISNULL(Value, '') <> ''

			SELECT @PokaYokeDateCode = dbo.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'POKAYOKE', 'POKAYOKE_DATECODE', @ProfitCode)
			
			--UPDATE Assy_LineAssyStatus_Running table..
			IF CHARINDEX(@PokaYokeDateCode, @Barcode) = 0
			BEGIN
				UPDATE Assy_LineAssyStatus_Running SET ResultTimeStamp = GETDATE(), STATUS = @Result WHERE ProfitCentercode = @ProfitCode
				AND LineCode = @LineCode AND MachineCode = @MachineCode AND OperationCode = @OperationCode AND Barcode = @Barcode AND ISNULL(STATUS, '') <> 'PS'

				IF NOT EXISTS
				(
					SELECT 1 FROM Assy_Result WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode
				)
				BEGIN
					SET @StationCode = '1'
					INSERT INTO Assy_Result(LineCode, OperationCode , StationCode, Barcode)
					SELECT @LineCode, @OperationCode, @StationCode, @Barcode
				END
				ELSE
				BEGIN
					UPDATE Assy_Result SET Barcode = @Barcode WHERE LineCode = @LineCode AND OperationCode = @OperationCode
				END
			END
			
			--Added By Rashid on 14th July 2016 For PokaYoke
			IF(@OperationCode = @PerformanceOperationCode AND CHARINDEX('PKYK', @Barcode) > 0)
			BEGIN
				UPDATE Assy_Scan_OK SET Barcode = '' WHERE LineCode = @LineCode AND OperationCode = @OperationCode AND Barcode = @Barcode
			END
			 	
			IF(@OperationCode ! = @PerformanceOperationCode AND CHARINDEX('PKYK', @Barcode) = 0)
			BEGIN
				UPDATE Assy_Scan_OK SET Barcode = '' WHERE LineCode = @LineCode AND OperationCode = @OperationCode AND Barcode = @Barcode
			END
			
			UPDATE A SET A.Barcode = '' FROM @tblParameters T INNER JOIN Assy_incorrectLabel AS A ON A.LineCode = T.LineCode AND A.OperationCode = T.OperationCode
			UPDATE A SET A.Barcode = '' FROM @tblParameters T INNER JOIN Assy_DuplicateLabel AS A ON A.LineCode = T.LineCode AND A.OperationCode = T.OperationCode
			
			IF CHARINDEX(@PokaYokeDateCode, @Barcode) = 0
			BEGIN
				--SELECT DISTINCT @Result = Result, @LineCode = LineCode, @OperationCode = OperationCode, 	
				SELECT DISTINCT @LineCode = LineCode, @OperationCode = OperationCode, 
				@MachineCode = MachineCode, @Barcode = Barcode, @ProfitCode = ProfitCentercode FROM @tblparameters
			END
			--DECLARE @PokaYokeDateCode VARCHAR(20);

			IF CHARINDEX(@PokaYokeDateCode, @Barcode) <> 0
			BEGIN
				DECLARE @PLCResult VARCHAR(10), @IsTestCompleted VARCHAR(10)

				SELECT @PLCResult = (SELECT CASE(@Result) WHEN 'PS' THEN 'PASS' ELSE 'FAIL' END)
				
				EXEC Assy_Proc_UpdatePokaYokeStatus @Condition = 'UPDATE_POKA_YOKE_RESULT', @LineCode = @LineCode, @OperationCode = @OperationCode, 
					@MachineCode = @MachineCode, @ProfitCentercode = @ProfitCode, @PLCResult = @PLCResult
					, @Barcode = @Barcode, @UserID = @UserID, @IsTestCompleted = @IsTestCompleted OUTPUT
				
				IF @IsTestCompleted = 'NA' or @IsTestCompleted = 'YES'
					RETURN
					 				
				IF NOT EXISTS
				(
					SELECT Top 1 1 FROM Assy_Result WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode
				)
				BEGIN
					SET @StationCode = '1'
					INSERT INTO Assy_Result(LineCode, OperationCode, StationCode, Barcode)
					SELECT @LineCode, @OperationCode, @StationCode, @Barcode

					UPDATE Assy_Scan_OK_History_For_PokaYoke SET Barcode = '', IsCycleStarted = 0 
						WHERE LineCode = @LineCode AND MachineCode = @MachineCode AND OperationCode = @OperationCode
				END
				ELSE
				BEGIN
					UPDATE Assy_Result SET Barcode = @Barcode WHERE LineCode = @LineCode AND OperationCode = @OperationCode
					UPDATE Assy_Scan_OK_History_For_PokaYoke SET Barcode = '', IsCycleStarted = 0 
							WHERE LineCode = @LineCode AND MachineCode = @MachineCode AND OperationCode = @OperationCode	
				END
				RETURN
			END

			IF(@Result = 'PS')
			BEGIN
				EXEC Assy_Proc_WIP_Manage @Condition = 'UPDATE_WIP_COUNT', @LineCode = @LineCode, @MachineCode = @MachineCode, @Barcode = @Barcode, @ProfitCentercode = @ProfitCode, @Result = @Result
				--RETURN 
			END
			ELSE IF(@Result = 'FL')
			BEGIN
				IF @OperationCode = @CrimpingOperationCode OR @OperationCode = @CentreShellCrimpingOperationCode
				BEGIN
					UPDATE Assy_LineAssyStatus_Running SET FailCount = 5
						WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND OperationCode = @OperationCode AND Barcode = @Barcode
					
					UPDATE Assy_Crimp_CycleStartTimeStamp SET IsRejected = 1 WHERE Barcode = @Barcode
				END
				ELSE
				BEGIN
					UPDATE Assy_LineAssyStatus_Running SET FailCount = ISNULL(FailCount, 0) + 1
						WHERE ProfitCentercode = @ProfitCode AND LineCode = @LineCode AND OperationCode = @OperationCode AND Barcode = @Barcode
				END
													 
				EXEC Assy_Proc_WIP_Manage @Condition = 'UPDATE_WIP_COUNT', @LineCode = @LineCode, @MachineCode = @MachineCode, @Barcode = @Barcode, @ProfitCentercode = @ProfitCode, @Result = @Result
			END

			IF EXISTS (SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND STS_CD = 0 AND KeyType = 'PinPressingLineCode' AND KeyValue = @LineCode)
			BEGIN
				IF(@Result = 'FL')
				BEGIN
					UPDATE Assy_LineAssyHP SET FailCount = ISNULL(FailCount, 0) + 1, Result = @Result, UpdateTimeStamp = GETDATE()
						WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND Barcode = @Barcode AND OperationCode = @OperationCode
				END
				ELSE
				BEGIN
					UPDATE Assy_LineAssyHP SET Result = @Result, UpdateTimeStamp = GETDATE()
						WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND Barcode = @Barcode AND OperationCode = @OperationCode
				END

				INSERT INTO Assy_LineAssyParamData
				(
					  [ProfitCenterCode]
					, [LineCode]
					, [MachineCode]
					, [OperationCode]
					, [StationCode]
					, [Barcode]
					, [TagName]
					, [Value]
					, [Result]
					, [DateCode]
					, [UserID]
					, [TimeStamp]
					, PartNo
					, UID
					, ScanTimeStamp
					,Live_Datecode
				)
				SELECT
					  [ProfitCenterCode]
					, [LineCode]
					, [MachineCode]
					, [OperationCode]
					, [StationCode]
					, [Barcode]
					, [TagName]
					, [Value]
					, [Result]
					, [DateCode]
					, [UserID]
					, [TimeStamp]
					, PartNo
					, UID
					, ScanTimeStamp
					,Live_Datecode
				FROM Assy_LineAssyParamData_Running (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCode

				INSERT INTO Assy_LineAssyParamData_Dtl
				(
					  UID
					, TagId
					, Value
				)
				SELECT UID, TagId, Value FROM  Assy_LineAssyParamData_Running_Dtl (NOLOCK)
		
				TRUNCATE Table Assy_LineAssyParamData_Running_Dtl
				TRUNCATE Table Assy_LineAssyParamData_Running

				IF(@Result = 'PS')
				BEGIN
					SELECT @LinkServerName = LinkServerName + '.' + DatabaseName FROM Assy_LinkServer_Dtl WITH (NOLOCK)
						WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode

					SET @ExecQuery = '	INSERT INTO ' + @LinkServerName + '.DBO.Assy_LineAssyHP (ProfitCenterCode,LineCode,Datecode,MachineCode,OperationCode,Barcode,FailCount,Result,UserID,Timestamp,PartNo,IsCentralUpdate,UpdateTimeStamp)
					SELECT ProfitCenterCode,LineCode,Datecode,MachineCode,OperationCode,Barcode,FailCount,Result,UserID,Timestamp,PartNo, 1 IsCentralUpdate, UpdateTimeStamp FROM Assy_LineAssyHP (NOLOCK)
					WHERE IsCentralUpdate = 0 AND Result = ''' + @Result + ''' '

					PRINT @ExecQuery
					EXEC (@ExecQuery)
					
					UPDATE Assy_LineAssyHP SET IsCentralUpdate = 1 WHERE IsCentralUpdate = 0 AND Result = @Result
				END
			END
		END
		
		ELSE IF(@Operation = 'UPDATE_RESULT_FOR_PERFORMANCE')
		BEGIN
			SELECT @PokaYokeDateCode = dbo.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'POKAYOKE', 'POKAYOKE_DATECODE', @ProfitCode)
			
			IF CHARINDEX(@PokaYokeDateCode, @Barcode) = 0
			BEGIN
				UPDATE Assy_LineAssyStatus_Running SET ResultTimestamp = GETDATE(), Status = UPPER(@Status)
					WHERE ProfitCentercode = @ProfitCode AND LineCode = @LineCode AND MachineCode = @MachineCode AND OperationCode = @OperationCode AND	Barcode = @Barcode

				IF @OperationCode = @PerformanceOperationCode AND @Status = 'PS'
				BEGIN
				IF NOT EXISTS(SELECT 1 FROM Assy_Performance_ZigOutTimeStamp WITH (NOLOCK) WHERE Barcode = @Barcode)
					BEGIN
						INSERT INTO Assy_Performance_ZigOutTimeStamp(Barcode, ResultTimestamp) Values (@Barcode, GETDATE())
					END
				END
			END

			IF NOT EXISTS
			(
				SELECT Top 1 1 FROM Assy_Result WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode
			)
			BEGIN
				INSERT INTO Assy_Result(LineCode, OperationCode , StationCode, Barcode ) 
				VALUES (@LineCode, @OperationCode, @StationCode, @Barcode)
			END
			ELSE
			BEGIN
				UPDATE Assy_Result SET Barcode = @Barcode WHERE LineCode = @LineCode AND OperationCode = @OperationCode
			END
			-- Check 07 April 2016
			UPDATE Assy_Scan_OK SET Barcode = '' WHERE LineCode = @LineCode AND OperationCode = @OperationCode AND Barcode = @Barcode
			UPDATE Assy_incorrectLabel SET Barcode = '' WHERE LineCode = @LineCode AND OperationCode = @OperationCode
			UPDATE Assy_DuplicateLabel SET Barcode = '' WHERE LineCode = @LineCode AND OperationCode = @OperationCode
			
			-- Added By Nelson 05-05-2016
			SELECT @ScannedStationIndex = (SELECT dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
			IF(@ScannedStationIndex = -1)
			BEGIN
				-- Added By Nelson on 05-05-2016
				IF (@OperationCode = @PerformanceOperationCode)
				BEGIN
					UPDATE Assy_Stations_Zig_In_Out_Status SET StatusInOut = 0 WHERE LineCode = @LineCode AND OperationCode = @OperationCode
				END
			END

			--UnComment when WIP AND PokaYoke goes live..
			SELECT @PokaYokeDateCode = dbo.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'POKAYOKE', 'POKAYOKE_DATECODE', @ProfitCode)

			IF CHARINDEX(@PokaYokeDateCode, @Barcode) <> 0
			BEGIN
				SELECT @PLCResult = (SELECT CASE(@Result) WHEN 'PS' then 'PASS' ELSE 'FAIL' END)
				
				EXEC Assy_Proc_UpdatePokaYokeStatus @Condition = 'UPDATE_POKA_YOKE_RESULT', @LineCode = @LineCode, @OperationCode = @OperationCode, 
				@MachineCode = @MachineCode, @ProfitCentercode = @ProfitCode, @PLCResult = @PLCResult, @Barcode = @Barcode, @UserID = @UserID
				RETURN
			END
		
			IF(@Status = 'PS')
			BEGIN
				EXEC Assy_Proc_WIP_Manage @Condition = 'UPDATE_WIP_COUNT', @LineCode = @LineCode, @MachineCode = @MachineCode, @Barcode = @Barcode, @ProfitCentercode = @ProfitCode, @Result = @Status
				RETURN 
			END
			ELSE IF(@Status = 'FL')
			BEGIN
				EXEC Assy_Proc_WIP_Manage @Condition = 'UPDATE_WIP_COUNT', @LineCode = @LineCode, @MachineCode = @MachineCode, @Barcode = @Barcode, @ProfitCentercode = @ProfitCode, @Result = @Status
				UPDATE Assy_LineAssyStatus_Running SET FailCount = ISNULL(FailCount, 0)+ 1 WHERE Barcode = @Barcode AND OperationCode = @OperationCode AND ProfitCentercode = @ProfitCode
			END		 
		END
	 
		ELSE IF(@Operation = 'IS_MODEL_CHANGED')
		BEGIN
			DECLARE @IsModelChanged BIT;
			SELECT @IsModelChanged = (SELECT ISNULL(IsChanged, 0) AS IsChanged FROM ASSY_ModelChanged WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode)
			IF(@IsModelChanged = 1)
			BEGIN
				SELECT @ReturnValue = 'Y'
				UPDATE ASSY_ModelChanged SET IsChanged = 0 WHERE LineCode = @LineCode AND OperationCode = @OperationCode
			END
			ELSE
			BEGIN
				SELECT @ReturnValue = 'N'
			END
		END

		ELSE IF(@Operation = 'IS_RECIEPE_REQUIRED')
		BEGIN
			DECLARE @IsRecipeRequired BIT = 0
			SET @IsRecipeRequired = (SELECT ISNULL(Recipe, 0) FROM RoutingConfigLineWise WITH (NOLOCK) WHERE OperationCode = @OperationCode 
				AND LineCode = @LineCode AND ProfitCentercode = @ProfitCode)

			IF(@IsRecipeRequired = 1)
			BEGIN
				SELECT @ReturnValue = 'Y'
			END
			ELSE
			BEGIN
				SELECT @ReturnValue = 'N'
			END
		END

		ELSE IF @Operation = 'MOVE_PERFORMANCE_PASS_DATA_CRIMP_EXPIRE'
		BEGIN
			IF (ISNULL(@OperationCode, '') = @CrimpingOperationCode OR ISNULL(@OperationCode, '') = @CentreShellCrimpingOperationCode)
			BEGIN
				DECLARE @NextMachineCode VARCHAR(20) = NULL
				EXEC Assy_Proc_Get_Next_MachineCode @LineCode = @LineCode, @MachineCode = @MachineCode, @PartNumber = @Part_No, @NextMachineCode = @NextMachineCode OUTPUT

				SELECT @Barcode = (SELECT Top 1 Barcode FROM Assy_Scan_OK WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode)
				PRINT @Barcode
				
				IF ISNULL(@Barcode, '') ! = ''
				BEGIN
					IF @LineCode = 'P1'
					BEGIN
						IF EXISTS (SELECT 1 FROM Assy_LineAssyStatus_Running WITH (NOLOCK) WHERE ProfitCentercode = @ProfitCode AND
								LineCode = @LineCode AND MachineCode = 'MCSTRKLP' AND Barcode = @Barcode AND ISNULL(Status, '') = 'PS')
						BEGIN
							INSERT INTO Assy_PerformanceHistory(ProfitCenterCode, LineCode, MachineCode, OperationCode, StationCode, Barcode, Status, FailCount, Datecode, 
										PartNo, Active, ResultTimestamp, ScanTimestamp, UserID, IsTallyChartApproved, IsReworkPart, HistoryTimestamp,ProductionOrderNo)
							SELECT ProfitCenterCode, LineCode, MachineCode, OperationCode, StationCode, Barcode, Status, FailCount, Datecode, PartNo, Active, 
								ResultTimestamp, ScanTimestamp, UserID, IsTallyChartApproved, IsReworkPart, GETDATE(), ProductionOrderNo
							FROM Assy_LineAssyStatus_Running WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode
								AND MachineCode = @MachineCode AND Barcode = @Barcode

							DELETE FROM Assy_LineAssyStatus_Running WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode
								AND MachineCode = @MachineCode AND Barcode = @Barcode
						END
					END
					ELSE
					BEGIN
						IF EXISTS (SELECT 1 FROM Assy_LineAssyStatus_Running WITH (NOLOCK) WHERE ProfitCentercode = @ProfitCode AND
								LineCode = @LineCode AND MachineCode = @PerformanceMachineCode AND Barcode = @Barcode AND ISNULL(Status, '') = 'PS')
						BEGIN
							-- Move MBA Performance Pass Data IF Crimping Time Limit reached (Added By Rashid on 9th Sep 2016)
							IF EXISTS	( SELECT L.OperationRequired FROM RoutingConfigLineWise L WITH (NOLOCK)
											INNER JOIN RoutingConfigPartWise P WITH (NOLOCK)
											ON L.OperationCode = P.OperationCode AND L.MachineCode = P.MachineCode 
											WHERE L.LineCode = @LineCode AND L.ProfitCenterCode = @ProfitCode AND P.ProfitCenterCode = @ProfitCode
											--AND P.PartNo = (SELECT Top 1 Assy_PartNo FROM Assy_RunningPart WITH (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCode)
											AND P.PartNo = @Part_No
											AND L.Traceability = 1 AND P.Traceability = 1 AND L.MachineCode = @MBAPerformanceMachineCode AND P.MachineCode = @MBAPerformanceMachineCode
											-- Added By Rashid For Handling Engraving Station on 10th Sep 2016
											AND ISNULL(L.Engraving, 0) = 0 AND ISNULL(P.Engraving, 0) = 0
										)
							BEGIN
								IF NOT EXISTS (SELECT 1 FROM Assy_LineAssyStatus_Running WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode
									AND MachineCode = @NextMachineCode AND Barcode = @Barcode )
								BEGIN
									--Modified By Sudesh on 20170515 for new column ProductionOrderNo in Table Assy_LineAssyStatus_Running
									INSERT INTO Assy_PerformanceHistory(ProfitCenterCode, LineCode, MachineCode, OperationCode, StationCode, Barcode, Status, FailCount, Datecode, 
										PartNo, Active, ResultTimestamp, ScanTimestamp, UserID, IsTallyChartApproved, IsReworkPart, HistoryTimestamp,ProductionOrderNo)
									SELECT ProfitCenterCode, LineCode, MachineCode, OperationCode, StationCode, Barcode, Status, FailCount, Datecode, PartNo, Active, 
										ResultTimestamp, ScanTimestamp, UserID, IsTallyChartApproved, IsReworkPart, GETDATE(), ProductionOrderNo
									FROM Assy_LineAssyStatus_Running WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode
										AND MachineCode = @MBAPerformanceMachineCode AND Barcode = @Barcode

									DELETE FROM Assy_LineAssyStatus_Running WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode
										AND MachineCode = @MBAPerformanceMachineCode AND Barcode = @Barcode
								END
							END
							IF NOT EXISTS (SELECT 1 FROM Assy_LineAssyStatus_Running WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode
									AND MachineCode = @NextMachineCode AND Barcode = @Barcode )
								BEGIN
									--Modified By Sudesh on 20170515 for new column ProductionOrderNo in Table Assy_LineAssyStatus_Running
									INSERT INTO Assy_PerformanceHistory(ProfitCentercode, LineCode, MachineCode, OperationCode, StationCode, Barcode, Status, FailCount, Datecode, 
										PartNo, Active, ResultTimestamp, ScanTimestamp, UserID, IsTallyChartApproved, IsReworkPart, HistoryTimestamp, ProductionOrderNo)
									SELECT ProfitCentercode, LineCode, MachineCode, OperationCode, StationCode, Barcode, Status, FailCount, Datecode, PartNo, Active, ResultTimestamp, 
										ScanTimestamp, UserID, IsTallyChartApproved, IsReworkPart, GETDATE(),ProductionOrderNo
									FROM Assy_LineAssyStatus_Running WITH (NOLOCK) WHERE ProfitCentercode = @ProfitCode AND LineCode = @LineCode
									AND MachineCode = @PerformanceMachineCode AND Barcode = @Barcode AND ISNULL(Status, '') = 'PS'

									DELETE FROM Assy_LineAssyStatus_Running WHERE ProfitCentercode = @ProfitCode AND LineCode = @LineCode
									AND MachineCode = @PerformanceMachineCode AND Barcode = @Barcode AND ISNULL(Status, '') = 'PS'

									DELETE FROM Assy_LineAssyStatus_Running WHERE ProfitCentercode = @ProfitCode AND LineCode = @LineCode
										AND OperationCode = @OperationCode AND Barcode = @Barcode
								END

							UPDATE Assy_Line_Crimping_Retest_Status SET IsRetest = 1 WHERE ProfitCentercode = @ProfitCode AND
								LineCode = @LineCode AND MachineCode = @PerformanceMachineCode AND Barcode = @Barcode AND ISNULL(IsRetest, 0) = 0
						END
					END
					SELECT @ReturnValue = 'Success', @ReturnInt = 1
				END
				ELSE IF ISNULL(@Barcode, '') = ''
				BEGIN
					IF EXISTS (SELECT 1 FROM Assy_Line_Crimping_Retest_Status WITH (NOLOCK) WHERE ProfitCentercode = @ProfitCode AND
							LineCode = @LineCode AND MachineCode = @PerformanceMachineCode AND ISNULL(IsRetest, 0) = 0)
					BEGIN
						SET @Barcode = (SELECT Top 1 Barcode FROM Assy_Line_Crimping_Retest_Status WITH (NOLOCK)
								WHERE ProfitCentercode = @ProfitCode AND LineCode = @LineCode AND MachineCode = @PerformanceMachineCode AND ISNULL(IsRetest, 0) = 0)
						IF ISNULL(@Barcode, '') ! = ''
						BEGIN
							-- Move MBA Performance Pass Data IF Crimping Time Limit reached (Added By Rashid on 9th Sep 2016)
							IF EXISTS	( SELECT L.OperationRequired FROM RoutingConfigLineWise L WITH (NOLOCK)
											INNER JOIN RoutingConfigPartWise P WITH (NOLOCK)
											ON L.OperationCode = P.OperationCode AND L.MachineCode = P.MachineCode 
											WHERE L.LineCode = @LineCode AND L.ProfitCenterCode = @ProfitCode AND P.ProfitCenterCode = @ProfitCode
											--AND P.PartNo = (SELECT Top 1 Assy_PartNo FROM Assy_RunningPart WITH (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCode)
											AND P.PartNo = @Part_No
											AND L.Traceability = 1 AND P.Traceability = 1 AND L.MachineCode = @MBAPerformanceMachineCode AND P.MachineCode = @MBAPerformanceMachineCode
											-- Added By Rashid For Handling Engraving Station on 10th Sep 2016
											AND ISNULL(L.Engraving, 0) = 0 AND ISNULL(P.Engraving, 0) = 0
										)
							BEGIN
								IF NOT EXISTS (SELECT 1 FROM Assy_LineAssyStatus_Running WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode
									AND MachineCode = @NextMachineCode AND Barcode = @Barcode )
								BEGIN
									--Modified By Sudesh on 20170515 for new column ProductionOrderNo in Table Assy_LineAssyStatus_Running
									INSERT INTO Assy_PerformanceHistory(ProfitCenterCode, LineCode, MachineCode, OperationCode, StationCode, Barcode, Status, FailCount, 
										Datecode, PartNo, Active, ResultTimestamp, ScanTimestamp, UserID, IsTallyChartApproved, IsReworkPart, HistoryTimestamp, ProductionOrderNo)
									SELECT ProfitCenterCode, LineCode, MachineCode, OperationCode, StationCode, Barcode, Status, FailCount, Datecode, PartNo, Active, 
										ResultTimestamp, ScanTimestamp, UserID, IsTallyChartApproved, IsReworkPart, GETDATE(), ProductionOrderNo
									FROM Assy_LineAssyStatus_Running WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode
										AND MachineCode = @MBAPerformanceMachineCode AND Barcode = @Barcode

									DELETE FROM Assy_LineAssyStatus_Running WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode
										AND MachineCode = @MBAPerformanceMachineCode AND Barcode = @Barcode
								END
							END

							IF NOT EXISTS (SELECT 1 FROM Assy_LineAssyStatus_Running WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode
									AND MachineCode = @NextMachineCode AND Barcode = @Barcode )
							BEGIN
								--Modified By Sudesh on 20170515 for new column ProductionOrderNo in Table Assy_LineAssyStatus_Running
								INSERT INTO Assy_PerformanceHistory(ProfitCentercode, LineCode, MachineCode, OperationCode, StationCode, Barcode, Status, FailCount, 
									Datecode, PartNo, Active, ResultTimestamp, ScanTimestamp, UserID, IsTallyChartApproved, IsReworkPart, HistoryTimestamp, ProductionOrderNo)
								SELECT ProfitCentercode, LineCode, MachineCode, OperationCode, StationCode, Barcode, Status, FailCount, Datecode, PartNo, Active, 
									ResultTimestamp, ScanTimestamp, UserID, IsTallyChartApproved, IsReworkPart, GETDATE(),ProductionOrderNo
								FROM Assy_LineAssyStatus_Running WITH (NOLOCK) WHERE ProfitCentercode = @ProfitCode AND LineCode = @LineCode
								AND MachineCode = @PerformanceMachineCode AND Barcode = @Barcode AND ISNULL(Status, '') = 'PS'
							
								DELETE FROM Assy_LineAssyStatus_Running WHERE ProfitCentercode = @ProfitCode AND LineCode = @LineCode
									AND MachineCode = @PerformanceMachineCode AND Barcode = @Barcode AND ISNULL(Status, '') = 'PS'

								DELETE FROM Assy_LineAssyStatus_Running WHERE ProfitCentercode = @ProfitCode AND LineCode = @LineCode
									AND OperationCode = @OperationCode AND Barcode = @Barcode
							
								DELETE FROM Assy_Performance_ZigOutTimeStamp WHERE Barcode = @Barcode
							END

							UPDATE Assy_Line_Crimping_Retest_Status SET IsRetest = 1 WHERE ProfitCentercode = @ProfitCode AND
								LineCode = @LineCode AND MachineCode = @PerformanceMachineCode AND Barcode = @Barcode AND ISNULL(IsRetest, 0) = 0
						END
					END
				END
			END
		END

		ELSE IF(@Operation = 'CRIMPING_DIFF_BETWEEN_SCANOK_AND_CYCLESTART')
		BEGIN
			IF @OperationCode = 'OCCSCR'
			BEGIN
				SELECT @ReturnValue = (SELECT ISNULL(PARAMETER_VALUE, '') FROM PARAMETER_MST WITH (NOLOCK) WHERE PARAMETER_C = 'AssLine'
					AND PARAMETER_C1 = @LineCode AND PARAMETER_C2 = 'CShell_Crimping_ScanOK_And_CycleStart_TimeLimit')
			END
			ELSE
			BEGIN
				SELECT @ReturnValue = (SELECT ISNULL(PARAMETER_VALUE, '') FROM PARAMETER_MST WITH (NOLOCK) WHERE PARAMETER_C = 'AssLine'
					AND PARAMETER_C1 = @LineCode AND PARAMETER_C2 = 'CRIMPING_SCANOK_AND_CYCLESTART_TIMELIMIT')
			END
			
			IF ISNULL(@ReturnValue, '') = ''
				SELECT @ReturnValue = '30'
		END

		ELSE IF(@Operation = 'PART_REJECTED_CRIMPING')
		BEGIN
			Declare @PrevResultTimestamp DateTime = NULL, @PrevScanTimestamp DateTime = NULL, @CrimpingXYZLimit INT = 0, @CrimpingXLimit INT = 0, 
			@CrimpingYLimit INT = 0, @CrimpingZLimit INT = 0, @Crimp_Barcode VARCHAR(60) = '', @bRejectStatus bit = 0, @CycleStartTimestamp DateTime = NULL
			
			SELECT Top 1 @PrevResultTimestamp = ResultTimestamp, @PrevScanTimestamp = ScanTimestamp, @Crimp_Barcode = Barcode FROM Assy_LineAssyStatus_Running WITH (NOLOCK)
					WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND MachineCode = @MachineCode AND OperationCode = @OperationCode
						AND (ISNULL(Status, '') = '' OR ResultTimestamp IS NULL) Order By ScanTimestamp
			
			IF @PrevResultTimestamp IS NULL
			BEGIN
				SELECT @CycleStartTimestamp = CyleStartTimestamp FROM Assy_Crimp_CycleStartTimeStamp WITH (NOLOCK) WHERE Barcode = @Crimp_Barcode

				IF @CycleStartTimestamp IS NULL
				BEGIN
					SELECT @CycleStartTimestamp = @PrevScanTimestamp
				END

				IF @OperationCode = 'OCCSCR'
				BEGIN
					SELECT @CrimpingZLimit = dbo.ASSY_FN_GET_PARAMETER_VALUE('AssLine', @LineCode, 'CShell_Crimping_Process_Limit', @ProfitCode)
				END
				ELSE
				BEGIN
					SELECT @CrimpingZLimit = dbo.ASSY_FN_GET_PARAMETER_VALUE('AssLine', @LineCode, 'Crimping_Process_Limit', @ProfitCode)
				END

				IF ISNULL(@CrimpingZLimit, 0) = 0
					SELECT @CrimpingZLimit = 25

				SELECT @CrimpingXYZLimit = @CrimpingZLimit

				IF(DATEDIFF(SECOND, @CycleStartTimestamp, GETDATE()) > @CrimpingXYZLimit)
				BEGIN
					UPDATE Assy_LineAssyStatus_Running SET Status = 'FL', FailCount = 5, ResultTimestamp = GETDATE()
						WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND MachineCode = @MachineCode AND OperationCode = @OperationCode
								AND (ISNULL(Status, '') = '' OR ResultTimestamp IS NULL) AND Barcode = @Crimp_Barcode
					
					UPDATE Assy_Crimp_CycleStartTimeStamp SET IsRejected = 1 WHERE Barcode = @Crimp_Barcode

					SELECT @bRejectStatus = 1
				END

				IF @bRejectStatus = 0
					SELECT @ReturnValue = 'N'
				ELSE IF @bRejectStatus = 1
					SELECT @ReturnValue = 'Y|' + @Crimp_Barcode
				
				RETURN
			END
		END
		--Added By RS On 30th Sep 2016 For Nissan Line 6 To be Merge
		ELSE IF(@Operation = 'UPDATE_SENSOR_POSITION')
		BEGIN
			IF NOT EXISTS
			(
				SELECT 1 FROM Assy_ClutchNipple_Sensor_Position WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode AND ProfitCenterCode = @ProfitCode
			)
			BEGIN
				INSERT INTO Assy_ClutchNipple_Sensor_Position (ProfitCenterCode, LineCode, OperationCode, SensorPosition)
				VALUES (@ProfitCode, @LineCode, @OperationCode, @SensorPosition)
			END
			ELSE
			BEGIN
				UPDATE Assy_ClutchNipple_Sensor_Position SET SensorPosition = @SensorPosition WHERE LineCode = @LineCode AND OperationCode = @OperationCode AND ProfitCenterCode = @ProfitCode
			END
		END

		ELSE IF(@Operation = 'UPDATE_ENGRAVE_START_STATUS')
		BEGIN
			IF NOT EXISTS
			(
				SELECT 1 FROM Assy_Engrave_Start_Confirmation WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode AND ProfitCenterCode = @ProfitCode
			)
			BEGIN
				INSERT INTO Assy_Engrave_Start_Confirmation (ProfitCenterCode, LineCode, OperationCode, IsEngraveStartConfirm)
				VALUES (@ProfitCode, @LineCode, @OperationCode, @EngraveStatus)
			END
			ELSE
			BEGIN
				UPDATE Assy_Engrave_Start_Confirmation SET IsEngraveStartConfirm = @EngraveStatus WHERE LineCode = @LineCode AND OperationCode = @OperationCode AND ProfitCenterCode = @ProfitCode
			END
		END

		ELSE IF(@Operation = 'SELECT_COUPLING_REFRESH_CYCLE_STATUS')
		BEGIN
			Declare @IsCouplingRefreshCycle BIT = NULL;
			SELECT Top 1 @IsCouplingRefreshCycle = ISNULL(IsCouplingRefreshCycle, 0) FROM Assy_ClutchNipple_Sensor_Position	WITH (NOLOCK)
				WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND OperationCode = @OperationCode
			
			IF(@IsCouplingRefreshCycle = 1)
			BEGIN
				UPDATE Assy_ClutchNipple_Sensor_Position SET IsCouplingRefreshCycle = 0
					WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND OperationCode = @OperationCode
				SELECT @ReturnValue = 'Y'
			END
			ELSE
			BEGIN
				SELECT @ReturnValue = 'N'
			END
			SELECT @ReturnInt = 1
		END

		ELSE IF (@Operation = 'SELECT_CNC_REQUIRED_STATUS')
		BEGIN
			Declare @IsCNCRequired SMALLINT = NULL;
			SELECT Top 1 @IsCNCRequired = ISNULL(IsCNCRequired, 0) FROM Assy_ClutchNipple_Sensor_Position WITH (NOLOCK)
				WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND OperationCode = @OperationCode
			
			IF(@IsCNCRequired = 1)
			BEGIN
				UPDATE Assy_ClutchNipple_Sensor_Position SET IsCNCRequired = 0 WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND OperationCode = @OperationCode
				SELECT @ReturnValue = 'Y'
			END
			ELSE IF(@IsCNCRequired = 2)
			BEGIN
				UPDATE Assy_ClutchNipple_Sensor_Position SET IsCNCRequired = 0 WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND OperationCode = @OperationCode
				SELECT @ReturnValue = 'N'
			END
			ELSE
				SELECT @ReturnValue = 'CNC_Cut_Ideal'

			SELECT @ReturnInt = 1
		END

		ELSE IF(@Operation = 'SELECT_ENGRAVE_COMPLETE_STATUS')
		BEGIN
			Declare @IsEngraveCompleteConfirm BIT = 0;
			SELECT @IsEngraveCompleteConfirm = ISNULL(IsEngraveCompleteConfirm, 0) FROM Assy_Engrave_Start_Confirmation WITH (NOLOCK)
				WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND OperationCode = @OperationCode
				
			IF(ISNULL(@IsEngraveCompleteConfirm, 0) = 1)
			BEGIN
				UPDATE Assy_Engrave_Start_Confirmation SET IsEngraveCompleteConfirm = 0 WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND OperationCode = @OperationCode
				SELECT @ReturnValue = 'Y'
			END
			ELSE
			BEGIN
				SELECT @ReturnValue = 'N'
			END
			SELECT @ReturnInt = 1
		END

		ELSE IF(@Operation = 'UPDATE_TORQUE_VALUE_AND_STATUS')
		BEGIN
			Declare @Torque_PartNo VARCHAR(20) = '';

			IF ISNULL(@Torque1, '') = ''
				SELECT @Torque1 = '0'

			IF ISNULL(@Torque2, '') = ''
				SELECT @Torque2 = '0'

			IF ISNULL(@TorqueAngle1, '') = ''
				SELECT @TorqueAngle1 = '0'

			IF ISNULL(@TorqueAngle2, '') = ''
				SELECT @TorqueAngle2 = '0'

			SELECT Top 1 @Torque_PartNo = Assy_PartNo FROM Assy_RunningPart WITH (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCode
			
			IF NOT EXISTS
			(
				SELECT Top 1 1 FROM Assy_CouplingTorqueStatus WITH (NOLOCK) WHERE LineCode = @LineCode AND ProfitCentreCode = @ProfitCode
			)
			BEGIN
				INSERT INTO Assy_CouplingTorqueStatus (ProfitCentreCode, LineCode, Torque_1, Torque_2, Is_Torque1_OK, Is_Torque2_OK, Ent_Dt, PART_NO, Is_Barcode_Print,TORQUE_ANGLE_1,TORQUE_ANGLE_2,Is_Vision_OK)
				VALUES (@ProfitCode, @LineCode, Case @Is_Torque1_OK WHEN 1 THEN CONVERT(NUMERIC(4, 2), @Torque1) ELSE NULL END, Case @Is_Torque2_OK WHEN 1 THEN CONVERT(NUMERIC(4, 2), @Torque2) ELSE NULL END, @Is_Torque1_OK, @Is_Torque2_OK, GETDATE(), @Torque_PartNo, 0,@TorqueAngle1,@TorqueAngle2,@Is_Vision_OK)
			END
			ELSE
			BEGIN
				IF ISNULL(@Is_Torque1_OK, 0) = 1
				BEGIN
					UPDATE Assy_CouplingTorqueStatus SET Torque_1 = CONVERT(NUMERIC(4, 2), @Torque1), Is_Torque1_OK = @Is_Torque1_OK, Ent_Dt = GETDATE(), PART_NO = @Torque_PartNo, 
					 Is_Barcode_Print = 0, TORQUE_ANGLE_1 = @TorqueAngle1
						WHERE LineCode = @LineCode AND ProfitCentreCode = @ProfitCode
				END
				ELSE IF ISNULL(@Is_Torque2_OK, 0) = 1
				BEGIN
					UPDATE Assy_CouplingTorqueStatus SET Ent_Dt = GETDATE(), PART_NO = @Torque_PartNo, Torque_2 = CONVERT(NUMERIC(4, 2), @Torque2), Torque_1 = CONVERT(NUMERIC(4, 2), @Torque1), 
						Is_Torque2_OK = @Is_Torque2_OK , Is_Barcode_Print = 0, TORQUE_ANGLE_1 = @TorqueAngle1, TORQUE_ANGLE_2 = @TorqueAngle2
							WHERE LineCode = @LineCode AND ProfitCentreCode = @ProfitCode
				END
			END
		END

		ELSE IF(@Operation = 'SELECT_AND_RESET_FG_BARCODE_PRINT_STATUS')
		BEGIN
			Declare @Is_Barcode_Print BIT = NULL;
			SELECT @Is_Barcode_Print = ISNULL(Is_Barcode_Print, 0) FROM Assy_CouplingTorqueStatus WITH (NOLOCK) WHERE ProfitCentreCode = @ProfitCode AND LineCode = @LineCode
			
			IF(@Is_Barcode_Print = 1)
			BEGIN
				SELECT @ReturnValue = 'Y'
				UPDATE Assy_CouplingTorqueStatus SET Is_Barcode_Print = 0 WHERE ProfitCentreCode = @ProfitCode AND LineCode = @LineCode
			END
			ELSE
			BEGIN
				SELECT @ReturnValue = 'N'
			END
			SELECT @ReturnInt = 1
		END

		ELSE IF(@Operation = 'SELECT_AND_UPDATE_NISSAN_DUSTER_STATUS_OP_ROD')
		BEGIN
			IF (@IsNissan IN (0, 1))
			BEGIN
				IF NOT EXISTS
				(
					SELECT 1 FROM Assy_ClutchNipple_Sensor_Position WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode --AND ProfitCenterCode = @ProfitCode
				)
				BEGIN
					INSERT INTO Assy_ClutchNipple_Sensor_Position ( LineCode, OperationCode, IsNissan)
					VALUES ( @LineCode, @OperationCode, @IsNissan)

					SET @ReturnValue = 'Success'
				END
				ELSE
				BEGIN
					UPDATE Assy_ClutchNipple_Sensor_Position SET IsNissan = @IsNissan
						WHERE LineCode = @LineCode AND OperationCode = @OperationCode

					SELECT @ReturnValue = 'Success'
				END
			END
			ELSE IF @IsNissan = 2
			BEGIN
				Declare @IsNissan_True BIT = NULL;
				SELECT Top 1 @IsNissan_True = ISNULL(IsNissan, 0) FROM Assy_ClutchNipple_Sensor_Position WITH (NOLOCK)
					WHERE LineCode = @LineCode AND OperationCode = @OperationCode

				IF(@IsNissan_True = 1)
				BEGIN
					SELECT @ReturnValue = 'Y'
				END
				ELSE
				BEGIN
					SELECT @ReturnValue = 'N'
				END
			END
			SELECT @ReturnInt = 1
		END

		ELSE IF (@Operation = 'SELECT_CNC_BYPASS_STATUS_LINE_MST')
		BEGIN
			Declare @IsCNCBypass BIT = NULL;
			SELECT Top 1 @IsCNCBypass = ISNULL(IsCNCValidationOff, 0) FROM LineMst WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode
			
			IF(@IsCNCBypass = 1)
			BEGIN
				SELECT @ReturnValue = 'Y'
			END
			ELSE
			BEGIN
				SELECT @ReturnValue = 'N'
			END
			SELECT @ReturnInt = 1
		END

		ELSE IF (@Operation = 'SELECT_SENSOR_POSITION')
		BEGIN
			SELECT Top 1 @ReturnValue = ISNULL(SensorPosition, '') FROM Assy_ClutchNipple_Sensor_Position WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND OperationCode = @OperationCode
			SELECT @ReturnInt = 1
		END

		ELSE IF (@Operation = 'BYPASS_UNBYPASS_SEND_MAIL')
		BEGIN
			Declare @LineName VARCHAR(100) = '', @Message VARCHAR(MAX) = '', @Web_To_eMailId VARCHAR(MAX) = '', @Web_Cc_eMailId VARCHAR(MAX) = '', @Subject VARCHAR(MAX) = ''
			
			SELECT @LineName = LTRIM(RTRIM(LineName)) FROM LineMst WITH (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCode
			
			SELECT @Web_To_eMailId = dbo.ASSY_FN_GET_PARAMETER_VALUE('AssLine', 'BYPASS_UNBYPASS_PLC', 'ALERT_LIST_TO', @ProfitCode)
			IF ISNULL(@Web_To_eMailId,'') = ''
			BEGIN
				SELECT @WEB_TO_EMAILID = 'Prasath.M@brakesindia.co.in;DineshKumar.V@brakesindia.co.in;Suresharumugam@brakesindia.co.in;'
			END
			
			SELECT @Web_Cc_eMailId = dbo.ASSY_FN_GET_PARAMETER_VALUE('AssLine', 'BYPASS_UNBYPASS_PLC', 'ALERT_LIST_CC', @ProfitCode)
			IF ISNULL(@Web_Cc_eMailId,'') = ''
			BEGIN
				SELECT @Web_Cc_eMailId = 'rashid.siddiqui@mind-infotech.com;'
			END
			
			SET @Message ='</BR></BR>Dear User,</BR></BR>'						
			SELECT @Message = ISNULL(@MESSAGE, '') + 'Please find the below details of Bypass / Unbypass Station Status in Assembly Line for Unit-  '  
						+ @ProfitCode + '</BR></BR>'
			
			SELECT @Subject = 'Bypass / Unbypass Station Status in Unit '+ @ProfitCode +' for Assembly Line - ' + @LineName + ' ( ' + @LineCode + ' )'
			
			CREATE Table #MAIL_DATA_BYPASS_PLC
			(
				ProfitCenterCode varchar(10),
				LineCode varchar(10),
				LineName Varchar(50),
				StationName varchar(50),
				Status varchar(50),
				UserName varchar(50),
				Remark Varchar(MAX)
			)

			IF (@IsBypass = 1)
				INSERT INTO #MAIL_DATA_BYPASS_PLC(ProfitCenterCode,LineCode,LineName,StationName,Status,UserName,Remark)
				SELECT @ProfitCode,@LineCode,@LineName,@StationName,'Bypassed',@UserName,@Remark
				--SELECT @Message = @StationName + ' station is bypassed in ' + @LineName + ' ( ' + @LineCode + ' ) ' + ' by User ID - ' + @UserName + ' WITH Remark - ' + @Remark
			ELSE IF (@IsBypass = 0)
				INSERT INTO #MAIL_DATA_BYPASS_PLC(ProfitCenterCode,LineCode,LineName,StationName,Status,UserName,Remark)
				SELECT @ProfitCode,@LineCode,@LineName,@StationName,'Unbypassed',@UserName,@Remark
				--SELECT @Message = @StationName + ' station is Unbypassed in ' + @LineName + ' ( ' + @LineCode + ' ) ' + ' by User ID - ' + @UserName + ' WITH Remark - ' + @Remark

			--PRINT @Message
			-- SELECT @WEB_TO_EMAILID, @WEB_CC_EMAILID, @MESSAGE, @SUBJECT
			IF (@Web_To_eMailId != '')
			BEGIN
				SELECT  @MESSAGE = @MESSAGE + REPLICATE('*',70)+'</BR></BR>'
				Declare @POSTMSG NVARCHAR(MAX)
				--EXEC PROC_SEND_MAIL @Web_To_eMailId, '', @Message, @Subject, @Web_Cc_eMailId, '', 'HTML'
				EXEC PROC_TABLE_TO_HTML @P_HTML = @POSTMSG OUTPUT,  @P_DYNSQL = '#MAIL_DATA_BYPASS_PLC', @P_TABLESTR='#tablestr',@P_Orderby='';
					SELECT @MESSAGE=@MESSAGE+ISNULL(@POSTMSG,'');	
					SELECT @MESSAGE=@MESSAGE+'</BR>'+dbo.fn_get_server_details() +'</BR>'
					SELECT  @MESSAGE = @MESSAGE + REPLICATE('*',70) + '</BR>'
					IF (ISNULL(@MESSAGE,'') <> '')
					BEGIN
						EXEC PROC_SEND_MAIL @WEB_TO_EMAILID, '', @MESSAGE, @SUBJECT, @WEB_CC_EMAILID,'','HTML'
					END
			END
			SELECT @ReturnValue = 'Mail_Sent', @ReturnInt = 1
		END

		ELSE IF (@Operation = 'TEXT_DATA_LOG')
		BEGIN
			Declare @IsTextLogRequired BIT = 0
			SELECT @IsTextLogRequired = ISNULL(IsTextLogRequired,0) FROM RoutingConfigLineWise (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCode AND OperationCode = @OperationCode
			IF(@IsTextLogRequired = 1)
			BEGIN
				SET @ReturnValue = 'YES'
			END
			ELSE
			BEGIN
				SET @ReturnValue = 'NO'
			END
		END

		ELSE IF (@Operation = 'GET_TORQUE_TOOL_DETAILS')
		BEGIN
			SELECT TorqueToolIP, TorqueToolPort, TorqueToolModel FROM Assy_TorqueMst (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND OperationCode = @OperationCode
				AND MachineCode = @MachineCode AND LineCode = @LineCode
		END
		
		ELSE IF(@Operation = 'INSERT_TORQUE_DETAILS')
        BEGIN
			IF NOT EXISTS
			(
				SELECT 1 FROM Assy_TorqueDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND MachineCode = @MachineCode AND
					OperationCode = @OperationCode AND Barcode = @Barcode AND TagName = @TagName
			)
			BEGIN
				INSERT INTO Assy_TorqueDetails (ProfitCenterCode, LineCode , MachineCode, OperationCode, Barcode, TagName, TagValue, Ent_Dt, Ent_By)
				SELECT @ProfitCode, @LineCode, @MachineCode, @OperationCode, @Barcode, @TagName, @TagValue, GETDATE(), @UserId
			END
			ELSE IF EXISTS 
			(
				SELECT Top 1 1 FROM Assy_TorqueDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND MachineCode = @MachineCode AND
					OperationCode = @OperationCode AND Barcode = @Barcode AND TagName = @TagName
			)
			BEGIN
				UPDATE Assy_TorqueDetails SET TagValue = @TagValue, Ent_Dt = GETDATE(), Ent_By = @UserId
					WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND MachineCode = @MachineCode
						AND OperationCode = @OperationCode AND Barcode = @Barcode AND TagName = @TagName
			END
        END

		ELSE IF(@Operation = 'UPDATE_VISION_OK')
		BEGIN
			UPDATE Assy_CouplingTorqueStatus SET Ent_Dt = GETDATE(), Is_Vision_OK = @Is_Vision_OK
					WHERE LineCode = @LineCode AND ProfitCentreCode = @ProfitCode
			
			--IF @Is_Vision_OK = 2
			--BEGIN
			--	update Assy_CouplingTorqueStatus set Is_Torque1_OK = 0, Is_Torque2_OK = 0, Part_No = ''
			--		WHERE LineCode = @LineCode AND ProfitCentreCode = @ProfitCode
			--END

		END

		ELSE IF(@Operation = 'RESET_COUPLING')
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM [Assy_Stations_Reset] (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode)
			BEGIN
				INSERT INTO [Assy_Stations_Reset] (LineCode,OperationCode,ResetStatus,TimeStamp)
				SELECT @LineCode, @OperationCode, 1, GETDATE()
			END
			ELSE
			BEGIN
				UPDATE [Assy_Stations_Reset] SET ResetStatus = 1 WHERE LineCode = @LineCode AND OperationCode = @OperationCode
			END
		END

		ELSE IF(@Operation = 'RESET_COUPLING_STATUS')
		BEGIN
			Declare @ResetStatus BIT = 0
			SELECT @ResetStatus = ISNULL(ResetStatus,0) FROM [Assy_Stations_Reset] (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode

			IF @ResetStatus = 1
			BEGIN
				UPDATE [Assy_Stations_Reset] SET ResetStatus = 0 WHERE LineCode = @LineCode AND OperationCode = @OperationCode
			END

			SET @ReturnValue = @ResetStatus
		END


		--Added By RS On 20180725 For TMC Part Cap Color 
		ELSE IF (@Operation = 'Validate_CapColor_Code')
		BEGIN
			IF ISNULL(@Part_No,'') = ''
			BEGIN
				SELECT @ReturnValue = 'Set Parameter is not available.', @ReturnInt = 1
				
				IF NOT EXISTS (SELECT 1 FROM Assy_Result (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode)
				BEGIN
					INSERT INTO Assy_Result(LineCode,OperationCode,StationCode,Barcode)
					SELECT @LineCode, @OperationCode, '1', @ReturnValue
				END
				ELSE
				BEGIN
					UPDATE Assy_Result SET Barcode = @ReturnValue WHERE LineCode = @LineCode AND OperationCode = @OperationCode
				END
				RETURN
			END

			Declare @CapColorMasterCode VARCHAR(1) = ''
			SELECT @CapColorMasterCode = LabelDataValue FROM Assy_Coupling_LabelInfo_Mst WHERE ProfitCenterCode = @ProfitCode AND PartNo = @Part_No AND CustomerPartNo = @CustomerPartNo
				AND LabelDataName = 'CapColorCode'
			
			IF ISNULL(@CapColorMasterCode,'') = ''
			BEGIN
				SELECT @ReturnValue = 'Cap Color Code is not defined in Coupling Master.', @ReturnInt = 1
				
				IF NOT EXISTS (SELECT 1 FROM Assy_Result (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode)
				BEGIN
					INSERT INTO Assy_Result(LineCode,OperationCode,StationCode,Barcode)
					SELECT @LineCode, @OperationCode, '1', @ReturnValue
				END
				ELSE
				BEGIN
					UPDATE Assy_Result SET Barcode = @ReturnValue WHERE LineCode = @LineCode AND OperationCode = @OperationCode
				END
				RETURN
			END

			IF CONVERT(INT,@CapColorMasterCode) != @CapColorCode
			BEGIN
				SELECT @ReturnValue = 'Cap Color Code is not match WITH master,CapColorMasterCode - ' + CONVERT(VARCHAR,@CapColorMasterCode) + ', CapColorCodeFromKepware - ' + CONVERT(VARCHAR,@CapColorCode)
				
				IF NOT EXISTS (SELECT 1 FROM Assy_Result (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode)
				BEGIN
					INSERT INTO Assy_Result(LineCode,OperationCode,StationCode,Barcode)
					SELECT @LineCode, @OperationCode, '1', @ReturnValue
				END
				ELSE
				BEGIN
					UPDATE Assy_Result SET Barcode = @ReturnValue WHERE LineCode = @LineCode AND OperationCode = @OperationCode
				END
				
				SET @ReturnInt = 1
				RETURN
			END
			ELSE
			BEGIN
				SELECT @ReturnValue = 'OK', @ReturnInt = 1
			END
		END

		ELSE IF(@Operation = 'OFFLINE_INSERT_PLC_PARAMS')
		BEGIN
			SELECT * INTO #Offline_tblParameters FROM @tblparameters

			SELECT DISTINCT @Result = Result, @LineCode = LineCode, @OperationCode = OperationCode, 
				@MachineCode = MachineCode, @Barcode = Barcode, @ProfitCode = ProfitCentercode FROM #Offline_tblParameters

			DECLARE @OfflineUID AS uniqueidentifier
			SET @OfflineUID = NEWID()

			INSERT INTO Assy_LineAssyParamData_Running(ProfitCentercode, LineCode, MachineCode, OperationCode, StationCode, Barcode, Result, Datecode, UserID, Timestamp, PartNo, UID, ScanTimeStamp,Live_Datecode)
			SELECT Top 1 ProfitCentercode, LineCode, MachineCode, OperationCode, @StationCode, @Barcode, @Result, @DateCode, @UserID, GETDATE(), @Part_No, @OfflineUID, GETDATE(),@Live_Datecode
			FROM #Offline_tblParameters WHERE ISNULL(Value, '') <> ''
			 
			INSERT INTO Assy_LineAssyParamData_Running_Dtl(UID, TagId, Value)
			SELECT @OfflineUID, B.TagId, ISNULL(A.Value, 0) Value FROM #Offline_tblParameters A INNER JOIN TagMst B WITH (NOLOCK) ON A.TagName = B.TagName WHERE ISNULL(Value, '') <> ''
		END

		ELSE IF(@Operation = 'OFFLINE_INDEPENDENT_INSERT_PLC_PARAMS')
		BEGIN
			SELECT * INTO #Offline_Independent_tblParameters FROM @tblparameters

			SELECT DISTINCT @Result = Result, @LineCode = LineCode, @OperationCode = OperationCode, @MachineCode = MachineCode, @Barcode = Barcode,
				@ProfitCode = ProfitCentercode, @DateCode = DateCode, @UserID = UserID FROM #Offline_Independent_tblParameters

			DECLARE @OfflineAutoID AS BIGINT

			INSERT INTO Assy_LineAssyParamData_Offline(ProfitCentercode, LineCode, Datecode, MachineCode, OperationCode, Barcode, Result, UserID, Timestamp, PartNo)
			SELECT @ProfitCode, @LineCode, @DateCode, @MachineCode, @OperationCode, @Barcode, @Result, @UserID, GETDATE(), @Part_No

			SELECT @OfflineAutoID = IDENT_CURRENT('Assy_LineAssyParamData_Offline')
			 
			INSERT INTO Assy_LineAssyParamData_Dtl_Offline(AutoID, TagId, Value)
			SELECT @OfflineAutoID, B.TagId, ISNULL(A.Value, 0) Value FROM #Offline_Independent_tblParameters A
				INNER JOIN TagMst B WITH (NOLOCK)
					ON A.TagName = B.TagName WHERE ISNULL(Value, '') <> ''

			IF (ISNULL(@Barcode,'') != '' AND ISNULL(@Barcode,'0') != '0')
			BEGIN
				SELECT * INTO #Assy_LineAssyHP FROM Assy_LineAssyHP (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND Barcode = @Barcode

				IF EXISTS (SELECT 1 FROM #Assy_LineAssyHP)
				BEGIN
					SELECT @FailCount = ISNULL(FailCount,0) FROM #Assy_LineAssyHP WHERE Result = 'FL'
					DELETE FROM Assy_LineAssyHP WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND Barcode = @Barcode AND Result = 'FL'
				END

				IF @Result = 'FL'
				BEGIN
					SET @FailCount = @FailCount + 1
				END
				--SELECT @FailCount
				IF NOT EXISTS (SELECT 1 FROM #Assy_LineAssyHP WHERE Result = 'PS')
				BEGIN
					INSERT INTO Assy_LineAssyHP(ProfitCenterCode,LineCode,Datecode,MachineCode,OperationCode,Barcode,FailCount,Result,UserID,Timestamp,PartNo)
					SELECT @ProfitCode, @LineCode, @DateCode, @MachineCode, @OperationCode, @Barcode, @FailCount, @Result, @UserID, GETDATE(), @Part_No

					SELECT @LinkServerName = LinkServerName + '.' + DatabaseName FROM Assy_LinkServer_Dtl WITH (NOLOCK)
						WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode

					--SET @ExecQuery = '	INSERT INTO ' + @LinkServerName + '.DBO.Assy_LineAssyHP (ProfitCenterCode,LineCode,Datecode,MachineCode,OperationCode,Barcode,FailCount,Result,UserID,Timestamp,PartNo,IsCentralUpdate)
					--SELECT ProfitCenterCode,LineCode,Datecode,MachineCode,OperationCode,Barcode,FailCount,Result,UserID,Timestamp,PartNo, 1 IsCentralUpdate FROM Assy_LineAssyHP (NOLOCK)
					--WHERE Barcode = ''' + @Barcode + '''
					--'

					SET @ExecQuery = '	INSERT INTO ' + @LinkServerName + '.DBO.Assy_LineAssyHP (ProfitCenterCode,LineCode,Datecode,MachineCode,OperationCode,Barcode,FailCount,Result,UserID,Timestamp,PartNo,IsCentralUpdate)
					SELECT ProfitCenterCode,LineCode,Datecode,MachineCode,OperationCode,Barcode,FailCount,Result,UserID,Timestamp,PartNo, 1 IsCentralUpdate FROM Assy_LineAssyHP (NOLOCK)
					WHERE IsCentralUpdate = 0'

					PRINT @ExecQuery
					EXEC (@ExecQuery)
					
					UPDATE Assy_LineAssyHP SET IsCentralUpdate = 1 WHERE IsCentralUpdate = 0
				END
				ELSE
				BEGIN
					INSERT INTO ASSY_SYSTEM_SCAN_LOG (WH_CODE,PROCESS_NAME,PROGRAM_ID,SCANNED_INPUT,SCANNED_VALUE,PART_NO,LINE_CD,REMARK,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP)
					SELECT @ProfitCode, 'ASSY_HP_SCAN', @OperationCode, 'BARCODE', @Barcode, @Part_No, @LineCode, 'Already Exists WITH Pass', @UserID, GETDATE(), @UserID, GETDATE()
				END
			END
		END

		ELSE IF(@Operation = 'OFFLINE_INDEPENDENT_PART_COUNT')
		BEGIN
			SELECT ISNULL(COUNT(Result),0) ResultCount, Result FROM Assy_LineAssyParamData_Offline (NOLOCK)
				WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode AND DateCode = @DateCode
			GROUP BY Result
		END
		--TRY BLOCK ENDS
	END TRY 
	BEGIN CATCH
		--CATCH BLOCK BEGINS
		SET @ReturnValue = 	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_SEVERITY() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
		CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_MESSAGE() AS VARCHAR(1500))
		RAISERROR(@ReturnValue, 16, 1)
		SET @ReturnInt = 2
		--CATCH BLOCK ENDS 
	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_PLCIntegration_Jhagadia]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Assy_Proc_PLCIntegration_Jhagadia] 
       @ID INT=NULL,
       @ProfitCode Varchar(10)= NULL, 
       @Operation VARCHAR (40) = NULL,
       @MachineCode varchar(20) = null,
       @OperationCode varchar(20) = NULL,
       @Part_No varchar(10) = NULL,
       @LineCode varchar(10) = NULL,
       @ZigStatus bit = null,
       @StationCode varchar(10) = '1',
       @TagName varchar(50) = null,
       @TagValue varchar(1000) = null,
       @Barcode varchar(100) = null,
       @IsCycleStarted bit = null,
       @DateCode varchar(10) = null,
       @IsDuplicate bit = null,
       @IsIncorrect bit = null,
       @Status varchar(10) = null,
       @UserId varchar(25) = null,
       @Password varchar(30) = null,
       @tblParameters dbo.Assy_TYPE_LineAssyParamData_Running readonly,
       @ReturnValue VARCHAR (2000)=NULL OUT,
       @ReturnInt INT=NULL OUT,
	   @PreCoupling_Data varchar(500)=null,
	   @HMIPartNo varchar(10) = NULL,
	   @EngPartNo varchar(10) = NULL,
	   @SUBSTNOPERATIONCODE VARCHAR(20)=NULL,
	   @PokaYokeMode bit=0,
	   @TorqueString VARCHAR(MAX)=NULL,
	   @Result2 varchar(500)=null,
	   @Result3 varchar(500)=null,
	   @CouplingBarcode varchar(100)=null,
	   @UpdateDataMannual bit=0
       -- =============================================
-- Author:           <Manoj Kumar>
-- Create date: <06 June 2015>
-- Description:      <To know at which stages PLCs are involved to capture data>

-- Modified By:     <RAVISHANKAR MISHRA>
-- Modified on:      <15-12-2016>
-- Description:    Added Insert_Caliper_PreCoupling_Data new block for inserting coupling data even after getting PKNG.
--                 Put condition in INSERT_TORQUE_DETAILS block if data is not available then only insert.
-- Modified By:     <RAVISHANKAR MISHRA>
-- Modified on:     <15-06-2017>
-- Description:    Added block to generate Caliper Serial on daily basis.
-- Modified By:     <Rashid Siddiqui>
-- Modified on:      <07-06-2017>
-- Description:     Added Two Block For 2 Parts and Recipe Validation Station wise (GET_2PARTS_ALLOW_FLAG,GET_STATION_ASSIGN_PART)
-- Modified By:     <RAVISHANKAR MISHRA>
-- Modified on:      <27-06-2017>
 /*Description:    1.After getting result from PLC if RFID tags value is # or empty or not 23 digits then read from scan ok table
                   2.If a part has been alreday tested at coupling station with result as pass, next time do not store result for same part no. 
				  */
--Modified on:      <12-08-2017>
--Description:  Get datecode and part no. against barcode from VS table,also added two new paramaters @HMIPartNo,@EngPartno
--Modified on:      <20-09-2017>
--Description: Changed in 'INSERT_TORQUE_DETAILS' block to resolve Netrunner issue at Actuator Tightening station
--,issue occured bacause RFID tags data was coming blanks some times.

--DECLARE @TBLE AS [Assy_TYPE_LineAssyParamData_Running] 
--INSERT INTO @TBLE
--SELECT '0088','J04','MC4s','OC4s','1','','','','FL','','ADMIN'
--union
--SELECT '0088','J04','MCCP','OCCP','1','2903305230Qd00000389J05','CALIPER_SERIAL_NO','0012','PS','','ADMIN'
--union
--SELECT '0088','J05','mc4s','OC4s','1','','ROT_STN.SEAL_NG','true','FL','','ADMIN'
--SELECT * FROM @TBLE
--EXEC [Assy_Proc_PLCIntegration_Jhagadia] @Operation='INSERT_PLC_PARAMS',@LineCode='J04',@tblParameters=@TBLE,@SUBSTNOPERATIONCODE='OCCN',@PokaYokeMode=1


-- To Rembember
-- Nothing = 0
-- Success = 1
-- Error = 2
-- AlreadyExists = 3
-- NotExists = 4
-- =============================================
       
AS
BEGIN
              DECLARE @OpRequired BIT=NULL;
              DECLARE @TraceabilityRequired bit = null;
              declare @failcount int = 0;
              declare @PokaYokeDateCode varchar(20);
              --declare @IsTwinIndex bit = 0;
              declare @ScannedStationIndex int;
              declare @InsideStationIndex varchar(10);
              declare @IsTorqueRequired bit = 0;
              --Added by Ravi on 15-06-17
			  declare @ProdDate as date=getdate()
			  declare @SerialNo smallint=null 
			  declare @ScanTimestamp datetime,@CaliperDatecode char(4),@CaliperSrNo smallint
			  declare @PRODUCTIONORDERNO varchar(50) =''
              declare @TagId int;
              SET NOCOUNT ON             
              BEGIN TRY 
           if(ISNULL(@LineCode,'') <> '')
              Begin
                   SELECT top 1 @Part_No=ISNULL(Assy_PartNo,''),@DateCode=Datecode,@UserId=CreatedBy ,@PRODUCTIONORDERNO=ProductionOrderNo FROM Assy_RunningPart with (nolock) 
				   WHERE LineCode = @LineCode order by CreatedBy desc
              End
			  ---------------Added By Prerna for Live_Datecode Change
			  if(isnull(@ProfitCode,'')='')
				begin
				  select @ProfitCode=ProfitCenterCode from Linemst with(nolock) where linecode=@LineCode
				end

			  Declare	@Live_Datecode char(4),@return_int int
			  exec Assy_proc_datecode @ProfitCode,@Live_Datecode out,@return_int out
			-------------------end
       
         if(@Operation = 'GET_CHANNEL_DEVICE_DETAILS')
         Begin

              SELECT a.MachineCode, a.OperationCode,  a.ChannelName, a.DeviceName, a.TagName, c.PLCAddress, b.TagType, b.TagSignificance, c.PLCMake, 
			  c.IsKepwareSupported, e.Torque, e.IS_PLCLogsRequired,ISNULL(c.OPCServer,'') as OPCServer, ISNULL(IsDisplayInGrid,0) as IsDisplayInGrid			  
			  FROM MachineTagMapping(nolock) as a
              inner join TagMst(nolock) as b on a.TagName = b.TagName
              inner join MachineDtl(nolock) as c on a.MachineCode = c.MachineCode and a.ProfitCenterCode = c.ProfitCenterCode and a.LineCode = c.LineCode and a.OperationCode = c.OperationCode
              inner join MachineMst(nolock) as d on a.MachineCode = d.MachineCode
              inner join RoutingConfigLineWise(nolock) as e on a.MachineCode = e.MachineCode and a.ProfitCenterCode = e.ProfitCenterCode and a.LineCode = e.LineCode and a.OperationCode = e.OperationCode 
              WHERE a.ProfitCenterCode = @ProfitCode and a.MachineCode = @MachineCode AND a.OperationCode =  @OperationCode AND a.LineCode = @LineCode
              order by a.FirstTag Desc
         End
         else if(@Operation = 'VALIDATE_BYPASS_USER')
         Begin
                 
                 if exists
                 (
                    select top 1 1 from
                       (
                        select a.userid, b.Password from qcusers as a 
                        inner join tl_mf_sec_user_mst as b
                        on a.userid = b.USER_ID
                        inner join USER_SITE_MAP_MASTER as c
                        on a.userid = c.USER_ID
                        where a.userid = @UserId
                        and b.Password = @Password
                        and c.SITE_CODE = @ProfitCode )p
                 )
                 Begin
                   set @ReturnValue = 'SUCCESS'
                 End
                 else
                 Begin
                     set @ReturnValue = 'LOGIN_FAILURE'
                 End

                
             End
        else if(@Operation = 'GET_CYCLE_START_STATUS')
         Begin
              set @ScannedStationIndex = (select  dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
              if(@ScannedStationIndex = -1)
              Begin
                     if((select isnull(IsCycleStarted, 0) from Assy_Scan_OK(nolock) 
                     where LineCode = @LineCode and MachineCode = @MachineCode and OperationCode = @OperationCode) = 1)
                     Begin
                       set @ReturnValue = 'Y'
                       return
                     End
                     else
                     Begin
                       set @ReturnValue = 'N'
                     End
              ENd
              else
           Begin
                set @ReturnValue = 'N'
              End

         End
          else if(@Operation = 'GET_ACTIVE_BARCODE_WHILE_CYCLE_START')
         Begin
           set @ScannedStationIndex = (select  dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
              --if it is a single jig station
              if(@ScannedStationIndex = -1)
              Begin
                 select top 1 Barcode from Assy_Scan_OK where LineCode = @LineCode and OperationCode = @OperationCode
              End
              else
              Begin
                if(@ScannedStationIndex = 1)
                  set @InsideStationIndex = 1
                else if(@ScannedStationIndex = 2)
              set @InsideStationIndex = 2
                select top 1 Barcode from Assy_Scan_OK where LineCode = @LineCode and OperationCode = @OperationCode 
                and StationCode = @InsideStationIndex
              End
         End

         else if(@Operation = 'GET_ACTIVE_BARCODE_WHILE_PASS')
         Begin
           set @ScannedStationIndex = (select  dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
              --if it is a single jig station
              if(@ScannedStationIndex = -1)
              Begin
                 select top 1 Barcode from Assy_Scan_OK(nolock) where LineCode = @LineCode and OperationCode = @OperationCode
              End
              else
              Begin
                if(@ScannedStationIndex = 1)
                  set @InsideStationIndex = 2
                else if(@ScannedStationIndex = 2)
                set @InsideStationIndex = 1
                select top 1 Barcode from Assy_Scan_OK (nolock) where LineCode = @LineCode and OperationCode = @OperationCode 
                and StationCode = @InsideStationIndex
              End
         End

      else if(@Operation = 'LOG_PLC_DATA')
         Begin
          declare @IsLogRequired bit = 0
          select @IsLogRequired = Is_PlcLogsRequired from RoutingConfigLineWise (nolock) where LineCode = @LineCode and ProfitCenterCode = @ProfitCode
          and OperationCode = @OperationCode
          if(@IsLogRequired = 1)
          Begin
                     insert into Assy_PLCLogs (ProfitCenterCode, LineCode, MachineCode, OperationCode, TagName, TagValue, Ent_Dt, Barcode)
                     values (@ProfitCode, @LineCode, @MachineCode, @OperationCode, @TagName, @TagValue, Getdate(), @Barcode)
          End
         End
        else If(@Operation ='GET_PLC_ROUTING')
              BEGIN

              
                           select distinct  a.Operationcode, a.machinecode, b.OperationName, c.OperationSeqNo  FROM MachineTagMapping(nolock) as a inner join OperationMst(nolock) as b
                           on a.OperationCode = b.OperationCode 
                           INNER JOIN RoutingConfigLineWise(nolock) as c on a.OperationCode = c.OperationCode
                             where c.linecode = @LineCode AND a.PROFITCENTERCODE = @ProfitCode and c.OperationRequired = 1
                             order by c.OperationSeqNo
              
                     SET @ReturnValue='Routing Configuration exists'
                     SET @ReturnInt=1
       END
           else If(@Operation ='GET_RUNNING_PART')
              BEGIN

                  IF EXISTS
                     (
                        SELECT TOP 1 1 FROM Assy_LineAssyStatus_Running(nolock) where ProfitCenterCode = @ProfitCode and LineCode = @LineCode
                        and OperationCode = @OperationCode and IsPendingPart = 1
                     )
                     Begin
                       select top 1 @Part_No =  isnull(PartNo, '') from Assy_LineAssyStatus_Running(nolock) where ProfitCenterCode = @ProfitCode and LineCode = @LineCode
                        and OperationCode = @OperationCode and IsPendingPart = 1
                     End
                     else
                     Begin
                           select @Part_No = isnull(Assy_PartNo, '')  from assy_runningpart (nolock) where LineCode = @LineCode
            end
                  set @ReturnValue=@Part_No
                  SELECT @Part_No AS Assy_PartNo
                     
       END

             else IF(@Operation = 'IS_BYPASS_ENABLED')
              Begin
              select @OpRequired = isnull(OperationRequired, 0), @TraceabilityRequired = isnull(Traceability, 0) from
                RoutingConfigLineWise(nolock) where MachineCode = @MachineCode and OperationCode = @OperationCode and ProfitCenterCode = @ProfitCode
                and LineCode = @LineCode

                if((@OpRequired = 1) and (@TraceabilityRequired = 1))
                Begin
                  set @ReturnValue = 'N'
                End
                else
                Begin
                  set @ReturnValue = 'Y'
                End
              End

             else  IF(@Operation = 'SAVE_INCORRECT_DUPLICATE_HISTORY')
              Begin
                print 'HI'
                --insert into Assy_DuplicateIncorrectHistory(DateCode, ProfitCenterCode, LineCode, MachineCode, OperationCode, Barcode, IsDuplicate, IsIncorrect, Ent_Dt)
                --values(@DateCode, @ProfitCode, @LineCode, @MachineCode, @OperationCode, @Barcode, @IsDuplicate, @IsIncorrect, GETDATE())
              End
              IF(@Operation = 'GET_SCAN_OK_AND_BARCODE')
              Begin
              
                   
                     set @ScannedStationIndex = (select  dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
                     if(@ScannedStationIndex = -1)
                           select Barcode, isScan from Assy_Scan_OK(nolock) where LineCode = @LineCode and OperationCode = @OperationCode
                     else
                     Begin
                       select Barcode, isScan from Assy_Scan_OK(nolock) where LineCode = @LineCode and OperationCode = @OperationCode 
                       and StationCode = @ScannedStationIndex
                     End
                     
              End
              
             else IF(@Operation = 'IS_INCORRECT_LABEL_SCANNED')
              Begin
                select Barcode, isIncorrect, HMIMessageCode from Assy_incorrectLabel(nolock) where LineCode = @LineCode and OperationCode = @OperationCode
              End

              else IF(@Operation = 'GET_HMI_MESSAGE_CODES')
              Begin
                select WIPMessage, MessageCode from assy_WIPMessageMst(nolock) where LineCode = @LineCode and ProfitCenterCode = @ProfitCode
              End

              else IF(@Operation = 'IS_DUPLICATE_LABEL_SCANNED')
              Begin
                select Barcode, isDuplicate from Assy_DuplicateLabel(nolock) where LineCode = @LineCode and OperationCode = @OperationCode
              End

             else IF(@Operation = 'RESET_SCANOK_DUPLICATE_INCORRECT_FIELDS')
              Begin
                 
                 update Assy_Scan_OK set isScan = 0, IsCycleStarted = 0 where LineCode = @LineCode and OperationCode = @OperationCode
                 update Assy_incorrectLabel set isIncorrect = 0 where LineCode = @LineCode and OperationCode = @OperationCode
                 update Assy_DuplicateLabel set isDuplicate = 0 where LineCode = @LineCode and OperationCode = @OperationCode

                 set @ScannedStationIndex = (select  dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
                     if(@ScannedStationIndex = -1)
                           update Assy_Stations_Zig_In_Out_Status set StatusInOut = 0 where LineCode = @LineCode and OperationCode = @OperationCode
              End

             else IF(@Operation = 'UPDATE_ZIG_STATUS')
              Begin
                  
                     set @ScannedStationIndex = (select  dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
                     --if these are not twin zig stations..
                     if(@ScannedStationIndex = -1)
                     Begin
                           set @StationCode = '1'  
                           if not exists
                           (
                                  select top 1 1 from Assy_Stations_Zig_In_Out_Status(nolock) where  LineCode = @LineCode and OperationCode = @OperationCode
                           )
                           Begin
                                  insert into Assy_Stations_Zig_In_Out_Status (LineCode, OperationCode, StationCode, StatusInOut)
                                  values (@LineCode, @OperationCode, @StationCode, @ZigStatus)
                           End 
                           else
                           Begin
                                  update Assy_Stations_Zig_In_Out_Status set StatusInOut = @ZigStatus, StationCode = @StationCode where LineCode = @LineCode and OperationCode = @OperationCode
                           end 
                     End

                     else
                     Begin
                     if not exists
                           (
                              select top 1 1 from Assy_Stations_Zig_In_Out_Status (nolock) where LineCode = @LineCode and OperationCode = @OperationCode
                           )
                           Begin
                             insert into Assy_Stations_Zig_In_Out_Status (LineCode, OperationCode, StationCode, StatusInOut) values
                             (@LineCode, @OperationCode, @StationCode, @ZigStatus)
                             return
                           End

                           else
                           Begin
                             update Assy_Stations_Zig_In_Out_Status set StatusInOut = 1, StationCode = @StationCode where LineCode = @LineCode
                             and OperationCode = @OperationCode 
                           End
                     End
              End           

              else if(@Operation = 'UPDATE_CYCLE_START')
              Begin
                     set @ScannedStationIndex = (select  dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
                     if(@ScannedStationIndex = -1)
                     Begin
                           update Assy_Scan_OK set IsCycleStarted = @IsCycleStarted where Barcode = @Barcode and LineCode = @LineCode 
                            and OperationCode = @OperationCode and MachineCode = @MachineCode
                              
                              --Changed by Ravi on 01-02-2016 for Poka Yoke
                                  If @IsCycleStarted = 1
                                  begin                                           
                                         exec ASSY_PROC_UPDATEPOKAYOKESTATUS @CONDITION='UPDATE_CYCLE_STARTED_FROM_PLC_PROC', @LINECODE=@LineCode,
                                         @MACHINECODE=@MachineCode, @OPERATIONCODE=@OperationCode, @BARCODE=@Barcode
                                  end
                                  else if(@IsCycleStarted = 0)
                                  Begin
                                         if(@ScannedStationIndex = -1)
                                         Begin
                                                update Assy_Scan_OK set Barcode = '' where  LineCode = @LineCode and OperationCode = @OperationCode 
                                                and Barcode = @Barcode     
                                         End
                                  End
                     End
                     
              End   
          
        else IF(@Operation = 'INSERT_PLC_PARAMS')
              Begin  
			                       
					 select * into #temp from @tblparameters

					 if(@UpdateDataMannual=0)
					 begin
						  -- Added By Sachin 2018-02-13 Temp. Save Data Given By Machine.
						  insert into Assy_Save_MachineData_TEMP(
						  ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,
						  TagName,Value,Result,Datecode,UserID,Entdtl
						  )
						  select ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,
						  TagName,Value,Result,Datecode,UserID,getdate() from #temp
						  -- Ended By Sachin 2018-02-13	
					  end

                     declare @result varchar(10) 
                     select distinct @result = Result, @LineCode = LineCode, @OperationCode = Operationcode,
                     @MachineCode = MachineCode, @Barcode = Barcode, @ProfitCode = ProfitCenterCode from #temp
					                    
					  --Added by Ravi on 260617
					 if isnull( @SUBSTNOPERATIONCODE,'')<>''
					 begin
					          select top 1 @Barcode=Barcode from Assy_Scan_OK (nolock) where LineCode = @LineCode  and OperationCode = @SUBSTNOPERATIONCODE  
					 end
					 -- Commented By Sachin 07Nov2019
					 --else
					 --begin
						--	IF ISNULL(@BARCODE,'')=''	or rtrim(ltrim(@BARCODE)) ='#' 	or len(rtrim(ltrim(@Barcode)))<23		 
						--	select top 1 @Barcode=Barcode from Assy_Scan_OK (nolock) where LineCode = @LineCode  and OperationCode = @OperationCode                   
					 --end

				     IF ISNULL(@BARCODE,'')=''
                     begin
                        --drop table #temp
                        RETURN        
                     end
					  
					  --Added by Ravi on 260617
					  select @PokaYokeDateCode=dbo.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE','POKAYOKE','POKAYOKE_DATECODE',@ProfitCode)
					  if  @OperationCode='OCCP' and charindex(@PokaYokeDateCode,@BARCODE)=0
					  begin

							 if exists
							 (
							    select 1 from assy_lineassystatus_running with (nolock) where ProfitCenterCode=@ProfitCode and Linecode=@Linecode 
								and MachineCode=@MachineCode and OperationCode=@OperationCode and barcode=@Barcode and isnull(status,'')='PS'
							 )
							 begin
							        print 'Record already saved.'
							        return							   
							 end
					  end
					  
					   -- select @PokaYokeDateCode=dbo.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE','POKAYOKE','POKAYOKE_DATECODE',@ProfitCode)

					    if charindex(@PokaYokeDateCode,@Barcode)=0
                         BEGIN						        
								 select @DateCode=datecode,@Part_No=partno from Assy_FN_Get_BarcodeParts_From_Barcode(@ProfitCode,@Linecode,@Barcode)
						 end
						else
						 begin
						       --Changed by Ravi on 12-08-17
							    select top 1 @Part_No=Assy_PartNo from dbo.assy_runningpart with(nolock) where ProfitCenterCode=@ProfitCode and linecode=@Linecode							         
								 
								 exec assy_PROC_DateCode @ProfitCenterCode=@ProfitCode,@ReturnValue= @DateCode output     									 
						 end		  
					  	
                    --Added by Manoj on 17/05/2016 to take care of 4 station rotary..
                     --if(@OperationCode = 'OC4S' and isnull(@PokaYokeMode,0)=0)
					 if exists (select top 1 1 from Assy_LineAssyParamData_Running_Temp 
					 where Barcode = @Barcode and OperationCode=@OperationCode)
                     Begin
							--since data will come from temp table delete the data from temporary table
							--delete from #temp
							--Since this is four substation assembly previous subassembly result can be pass whereas next subassembly could be fail
							update Assy_LineAssyParamData_Running_Temp set Result = @result 
							where Barcode = @Barcode and  OperationCode=@OperationCode

							insert into #temp (ProfitCenterCode, LineCode, MachineCode, OperationCode,
							StationCode, Barcode, TagName, Value, Result, DateCode, UserID)
							select ProfitCenterCode, LineCode, MachineCode, OperationCode,
							StationCode, Barcode, TagName, Value, Result, DateCode, UserID
							from Assy_LineAssyParamData_Running_Temp where Barcode = @Barcode
							and OperationCode=@OperationCode

							delete from Assy_LineAssyParamData_Running_Temp 
							where Barcode = @Barcode and  OperationCode=@OperationCode					

                     End                    

                     --Changed by Ravi on 12-08-17
                       select @IsTorqueRequired = Torque from dbo.RoutingConfigLineWise with (nolock) where ProfitCenterCode = @ProfitCode and LineCode = @LineCode and OperationCode = @OperationCode 
                       if(@IsTorqueRequired = 1)
                       Begin
					   
					   		   insert into #temp (ProfitCenterCode, LineCode, MachineCode, OperationCode, Barcode, TagName, Value, Result, Datecode, UserID)
							   select ProfitCenterCode, LineCode, MachineCode, OperationCode, Barcode, TagName, TagValue, @result, '', @UserId  from dbo.assy_TorqueDetails with(nolock)
							   where ProfitCenterCode = @ProfitCode and LineCode = @LineCode and machinecode=@MachineCode and OperationCode = @OperationCode and  Barcode = @Barcode
                          
							   delete from assy_TorqueDetails  where ProfitCenterCode = @ProfitCode and LineCode = @LineCode and machinecode=@MachineCode and OperationCode = @OperationCode and  Barcode = @Barcode				     

					   End

                       --delete duplicate entries from #temp
                       alter table #temp add sno int identity(1,1)
                       delete from #temp where sno in
                       (
                           select sno from (
                           select *,
                           RANK() OVER ( PARTITION BY Barcode, TagName,Value ORDER BY sno DESC )rank
                           From #temp
                           )T
                           where rank>1
                       )
                       alter table #temp drop column sno
					   -- Added By Sachin 2018306
					  if(@OperationCode='OCHA')
					  begin
							if not exists(select top 1 1 from dbo.Assy_LineAssyStatus_running with(nolock) where ProfitCenterCode=@ProfitCode
								and LineCode=@LineCode and MachineCode=@MachineCode and OperationCode=@OperationCode and barcode=@Barcode)
							begin
									INSERT INTO ASSY_LINEASSYSTATUS_RUNNING(PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,BARCODE,DATECODE,PARTNO,ACTIVE,
													STATIONCODE,SCANTIMESTAMP,USERID,PRODUCTIONORDERNO)
									SELECT @ProfitCode,@LineCode,@MachineCode,@OperationCode,@Barcode,@DateCode,@Part_No,0,1,GETDATE(),@USERID,@PRODUCTIONORDERNO
							end
					  end					 
					  -- Ended By Sachin 2018306

                      select @ScanTimestamp=ScanTimestamp from dbo.Assy_LineAssyStatus_running with(nolock) where ProfitCenterCode=@ProfitCode
					  and LineCode=@LineCode and MachineCode=@MachineCode and OperationCode=@OperationCode and barcode=@Barcode

                     declare @UID as uniqueidentifier
                     set @UID=newid()     
					 if @OperationCode in ('OCCP','OCDC') and charindex(@PokaYokeDateCode,@Barcode)=0
					 begin 					           
								--Added By Sachin 2020Jan01		
								update #temp set [value] = 0  where  tagname='CALIPER_SERIAL_NO' and [value]='ND'
								--Ended BY Sachin 2020Jan01

					            select @CaliperDatecode=[value] from  #temp where  tagname ='DATE_CODE_COUPLING'
								select @CaliperSrNo=convert(smallint,[value]) from #temp where  tagname='CALIPER_SERIAL_NO'

								INSERT INTO Assy_LineAssyParamData_Running(ProfitCenterCode, LineCode, MachineCode,OperationCode,StationCode,Barcode,Result,Datecode,UserID
								,Timestamp, PartNo,uid,ScanTimestamp,CaliperDatecode,CaliperSrNo,Live_Datecode)
								SELECT top 1 ProfitCenterCode, LineCode, MachineCode,OperationCode,@StationCode,@Barcode,Result,ISNULL(@DateCode,''),@UserId
								, GETDATE(), @Part_No,@UID,@ScanTimestamp,@CaliperDatecode,@CaliperSrNo,@Live_Datecode
								 FROM #temp where isnull(Value,'')<>''
                     end
					 else
					 begin
								INSERT INTO Assy_LineAssyParamData_Running(ProfitCenterCode, LineCode, MachineCode,OperationCode,StationCode,Barcode,Result,Datecode,UserID,Timestamp, PartNo,uid,ScanTimestamp,Live_Datecode)
								SELECT top 1 ProfitCenterCode, LineCode, MachineCode,OperationCode,@StationCode,@Barcode,Result,ISNULL(@DateCode,''),@UserId, GETDATE(), @Part_No,@UID,@ScanTimestamp,@Live_Datecode
								FROM #temp where isnull(Value,'')<>''
					 end
                      insert into Assy_LineAssyParamData_Running_Dtl(UID,TagId,Value)
                      SELECT distinct @UID,B.TagId,isnull(A.Value,0)Value     
					  FROM #temp A inner join tagmst B with(nolock) on A.tagname=b.tagname where isnull(Value,'')<>''                       
					 
					 if(@@ROWCOUNT > 0)
					 begin
					 -- Added By Sachin 2018-02-13
					  -- If all Data Saved Successfully, Remove Saved data Temp. Machine data
					  delete from Assy_Save_MachineData_TEMP where barcode=isnull(@Barcode,'')
					  and OperationCode=@OperationCode
					  -- Ended By Sachin 2018-02-13
					end                     

                     --update Assy_LineAssyStatus_Running table..
                           if charindex(@PokaYokeDateCode,@Barcode)=0
                           BEGIN
									update assy_LineAssyStatus_Running set ResultTimeStamp = GETDATE(), STATUS = @result WHERE ProfitCenterCode = @ProfitCode
									and Linecode = @LineCode and MachineCode = @MachineCode and OperationCode = @OperationCode and Barcode = @Barcode and isnull(STATUS,'')<>'PS' 

									if not exists
									(
										select top 1 1 from Assy_Result(nolock) where LineCode = @LineCode and OperationCode = @OperationCode
									)
									Begin
											insert into Assy_Result(LineCode, OperationCode , StationCode, Barcode )
											select @LineCode, @OperationCode, @StationCode, @Barcode
									End
									else
									Begin
											update assy_Result set Barcode = @Barcode where LineCode = @LineCode and OperationCode = @OperationCode
									End
                           END    
                     
						   drop table #temp
						   if isnull( @SUBSTNOPERATIONCODE,'')<>''
						   begin                         
						   		update assy_Scan_OK set Barcode = '' where LineCode = @LineCode and OperationCode = @SUBSTNOPERATIONCODE 
						   end
						   else
						   begin
						   		update assy_Scan_OK set Barcode = '' where LineCode = @LineCode and OperationCode = @OperationCode
						   end

                     update a set a.Barcode = '' from @tblParameters t inner join Assy_incorrectLabel as a on a.LineCode = t.LineCode and a.OperationCode = t.OperationCode
                     update a set a.Barcode = '' from @tblParameters t inner join Assy_DuplicateLabel as a on a.LineCode = t.LineCode and a.OperationCode = t.OperationCode
                           
                     --select distinct @result = Result, @LineCode = LineCode, @OperationCode = Operationcode,
                     --@MachineCode = MachineCode,  @ProfitCode = ProfitCenterCode from @tblparameters

                     --declare @PokaYokeDateCode varchar(20);

                     IF CHARINDEX(@POKAYOKEDATECODE,@BARCODE)<>0
                           BEGIN
                                 DECLARE @PLCRESULT VARCHAR(10),@ISTESTCOMPLETED varchar(10)

                                  SELECT @PLCRESULT = (SELECT CASE(@RESULT) WHEN 'PS' THEN 'PASS' ELSE 'FAIL' END)
                                  EXEC ASSY_PROC_UPDATEPOKAYOKESTATUS @CONDITION='UPDATE_POKA_YOKE_RESULT',@LINECODE=@LINECODE, @OPERATIONCODE=@OPERATIONCODE,
                                  @MACHINECODE=@MACHINECODE, @PROFITCENTERCODE=@PROFITCODE, @PLCRESULT= @PLCRESULT
                                  ,@BARCODE=@BARCODE,@USERID = @USERID,@ISTESTCOMPLETED=@ISTESTCOMPLETED  OUTPUT,@Allow2Parts=1
                           
                                  IF @ISTESTCOMPLETED='NA' or @ISTESTCOMPLETED='YES'
                                    RETURN
                                                             
                                    IF NOT EXISTS
                                     (
                                            SELECT TOP 1 1 FROM ASSY_RESULT(NOLOCK) WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
                                     )
									  BEGIN
												 INSERT INTO ASSY_RESULT(LINECODE, OPERATIONCODE , STATIONCODE, BARCODE )
												  SELECT @LINECODE, @OPERATIONCODE, @STATIONCODE, @BARCODE
                                                
												  UPDATE Assy_Scan_OK_History_For_PokaYoke SET BARCODE='',ISCYCLESTARTED=0 
                                                  WHERE LINECODE=@LINECODE AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE
                                       END
                                         ELSE
                                                BEGIN
                                                       UPDATE ASSY_RESULT SET BARCODE = @BARCODE WHERE LINECODE = @LINECODE AND OPERATIONCODE = @OPERATIONCODE
                                                       UPDATE Assy_Scan_OK_History_For_PokaYoke SET BARCODE='',ISCYCLESTARTED=0 
                                                       WHERE LINECODE=@LINECODE AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE     
                                                END
                                          RETURN
                                    END                          
              
                     if(@result = 'PS')
                     Begin                      
                               -- EXEC ASSY_PROC_WIP_MANAGE  @CONDITION='UPDATE_WIP_COUNT', @LINECODE=@LINECODE,@MACHINECODE=@MACHINECODE,@BARCODE=@BARCODE,@PROFITCENTERCODE=@PROFITCODE, @RESULT = @RESULT                           
                                  if exists
                                  (
                                            select 1 from linemst with(nolock) where ProfitCenterCode = @PROFITCODE and LineCode = @LINECODE and isnull(isActive,0)=1 
											and  isnull(Allow2Parts,0)=1
                                  )
                                  begin
										 delete from Assy_PreviousPending_Parts  where ProfitCenterCode=@ProfitCode and LineCode =@LineCode 
					                     and MachineCode=@MachineCode and Barcode=@Barcode and   isnull(Is_Rejected,0)=0
                                  end

                                  return                
                     End
                     else if(@result = 'FL')
                     Begin  
                                                       
                                  update Assy_LineAssyStatus_Running set failcount = isnull(failcount,0)+1 
                                  where  ProfitCenterCode = @ProfitCode and LINECODE=@LINECODE and OperationCode = @OperationCode and  Barcode = @Barcode 
                                                                                                 
                                  --EXEC ASSY_PROC_WIP_MANAGE  @CONDITION='UPDATE_WIP_COUNT', @LINECODE=@LINECODE,@MACHINECODE=@MACHINECODE,@BARCODE=@BARCODE,@PROFITCENTERCODE=@PROFITCODE, @RESULT = @RESULT
                     End     
					 
					  
					       
              End              
              else IF(@Operation = 'IS_MODEL_CHANGED')
              Begin
                declare @IsModelChanged bit;
              set  @IsModelChanged = (select isnull(IsChanged, 0) as IsChanged from ASSY_ModelChanged(nolock) Where LineCode = @LineCode and OperationCode = @OperationCode)
              if(@IsModelChanged = 1)
              Begin
                 set @ReturnValue = 'Y'
                 update ASSY_ModelChanged set IsChanged = 0 Where LineCode = @LineCode and OperationCode = @OperationCode
              End
              else
              Begin
                 set @ReturnValue = 'N'
              End

              End
            else  if(@Operation = 'IS_RECIEPE_REQUIRED')

         Begin

           declare @IsRecipeRequired bit = 0

         set @IsRecipeRequired = (select isnull(Recipe, 0) from routingconfiglinewise (nolock) where OperationCode = @OperationCode 

              and Linecode = @Linecode and ProfitCentercode = @ProfitCode)

              if(@IsRecipeRequired = 1)

              Begin

                set @ReturnValue = 'Y'

              End

              else

              Begin

                set @ReturnValue = 'N'

              End

         End  
		       --changed by ravi on 120817
              else if @Operation = 'SAVE_TEMP_ROTARY_DATA'
              Begin
							--if(@OperationCode = 'OC4S')
							--Begin
                             
								 --In case of rotary station part number will be retrieved from assy_runningpart table because scanok will not have records of substations
								 --Rotary has to be flushed out before starting new part..
								   select @DateCode=datecode,@Part_No=partno from Assy_FN_Get_BarcodeParts_From_Barcode(@ProfitCode,@Linecode,@Barcode)
							 
								  insert into dbo.Assy_LineAssyParamData_Running_Temp (ProfitCenterCode, LineCode, MachineCode, OperationCode, StationCode,
								  Barcode, TagName, Value, Result, DateCode, UserId, Timestamp, PartNo)
							
								 select @ProfitCode, @LineCode, @MachineCode, @OperationCode, '1', @Barcode, @TagName, @TagValue, @Status,
											 @DateCode, '', GetDate(), @Part_No    
                                  
							  --End
				End

            -- else if(@Operation = 'GET_TEMP_ROTARY_DATA')
            -- Begin

            --  SELECT ProfitCenterCode, LineCode, MachineCode, OperationCode, StationCode,
            --               Barcode, TagName, Value, Result, DateCode, UserId from Assy_LineAssyParamData_Running_Temp (nolock)
            --               where Barcode = @Barcode
                           
            --End

             else if(@Operation = 'GET_TORQUE_TOOL_DETAILS')
              Begin
                 select TorqueToolIP, TorqueToolPort, TorqueToolModel from assy_TorqueMst (nolock) WHERE ProfitCenterCode = @ProfitCode and
                  OperationCode = @OperationCode and MachineCode = @MachineCode and LineCode = @LineCode
              End
			 else if(@Operation = 'INSERT_TORQUE_DETAILS')
              Begin
			  			    
					  IF ISNULL(@BARCODE,'')=''	or rtrim(ltrim(@BARCODE)) ='#' 	or len(rtrim(ltrim(@Barcode)))<23		 
							select top 1 @Barcode=Barcode from Assy_Scan_OK (nolock) where LineCode = @LineCode  and OperationCode = @OperationCode  

					  if not exists 
					  (
						  select top 1 1 from dbo.assy_TorqueDetails(nolock) 
						  where ProfitCenterCode=@ProfitCode and LineCode=@LineCode and machineCode=@MachineCode and 
						  operationCode=@OperationCode and barcode=@Barcode and tagName=@TagName
					  )
					  begin
							INSERT INTO assy_TorqueDetails (ProfitCenterCode, LineCode , MachineCode, OperationCode, Barcode, TagName, TagValue, Ent_Dt, Ent_By)
						   select @ProfitCode, @LineCode, @MachineCode, @OperationCode, @Barcode, @TagName, @TagValue, GETDATE(), @UserId
					  end
              End
              
              else if(@Operation = 'GET_LAST_RECORD')
              Begin
                     select Top 1 @uid = UID from Assy_LineAssyParamData_Running where  operationcode = @OperationCode and ProfitCenterCode = @ProfitCode
                     and LineCode = @LineCode order by Timestamp desc 

                     select a.Barcode, a.Result, c.TagName,  b.Value,  d.OperationName from Assy_LineAssyParamData_Running as a
                     inner join Assy_LineAssyParamData_Running_Dtl  as b on a.UID = b.UID 
                     inner join TagMst as c on b.TagId = c.TagId
                     inner join OperationMst as d on a.OperationCode = d.OperationCode
                     where a.UID = @uid 
               End

             else if(@Operation = 'GET_CURRENT_DATE_PROCESSED_BARCODES')
              Begin
                     select distinct Barcode, Timestamp from Assy_LineAssyParamData_Running  where convert(date, Timestamp) = convert(date, getdate())
                     and LineCode = @LineCode and ProfitCenterCode = @ProfitCode order by timestamp desc
              End
              
             else if(@Operation = 'GET_RESULT_FOR_BARCODE')
              Begin
                
                if exists
                (
                   select top 1 1 from Assy_LineAssyParamData_Running where Barcode = @Barcode and Result = 'PS'
                     
                     )
                     Begin
                           select a.Result, c.TagName,  b.Value,  d.OperationName from Assy_LineAssyParamData_Running as a
                           inner join Assy_LineAssyParamData_Running_Dtl  as b on a.UID = b.UID 
                           inner join TagMst as c on b.TagId = c.TagId
                           inner join OperationMst as d on a.OperationCode = d.OperationCode
                           where a.Barcode = @Barcode and a.Result = 'PS' order by a.OperationCode 
                     End
                else
                Begin
                           select a.Result, c.TagName,  b.Value,  d.OperationName from Assy_LineAssyParamData_Running as a
                           inner join Assy_LineAssyParamData_Running_Dtl  as b on a.UID = b.UID 
                           inner join TagMst as c on b.TagId = c.TagId
                           inner join OperationMst as d on a.OperationCode = d.OperationCode
                           where a.Barcode = @Barcode and a.Result = 'FL' order by a.OperationCode
                End
              End

             else if(@Operation = 'GET_PASS_FAIL_COUNT')
              Begin
                
				DECLARE @PASSCOUNT INT = 0

				SELECT @PASSCOUNT = ISNULL( COUNT(BARCODE), 0) from Assy_LineAssyStatus_Running(nolock) 
				where Status = 'PS' and OperationCode = @OperationCode
				and LineCode = @LineCode and ProfitCenterCode = @ProfitCode
				and dateCode in (select top 1 Datecode from Assy_RunningPart(nolock))
				 --convert(date, ResultTimeStamp) = convert(date, getdate()) 

				SELECT @FAILCOUNT = ISNULL( COUNT(BARCODE), 0) from Assy_LineAssyStatus_Running(nolock) 
				where Status = 'FL' and 
				OperationCode = @OperationCode
				and LineCode = @LineCode and ProfitCenterCode = @ProfitCode
				and dateCode in (select top 1 Datecode from Assy_RunningPart(nolock))
				 --convert(date, ResultTimeStamp) = convert(date, getdate())

                 SELECT @PASSCOUNT, @FAILCOUNT
              End

               else if(@Operation = 'GET_MAINSERVER_CONNECTION_STRING')
              Begin
                 
                 SELECT isnull(ConnectionString, '')ConnectionString FROM assy_ConnectionString_MainServer
                 where ProfitCenterCode = @ProfitCode AND LineCode = @LineCode
              End

		-- ADDED BY SACHIN 20161201
		-- CHECK TO SAVE TEXT LOG OR NOT.
		else if(@Operation = 'TEXT_DATA_LOG')
        Begin
          
          
				  declare @IsTextLogRequired bit = 0
				  select @IsTextLogRequired = isnull(IsTextLogRequired,0) from RoutingConfigLineWise (nolock) where LineCode = @LineCode and ProfitCenterCode = @ProfitCode
				  and OperationCode = @OperationCode
          
				  if(@IsTextLogRequired=1)
				  begin
						SET @RETURNVALUE='YES'
				  end
				  else
					  begin
							SET @RETURNVALUE='NO'
					  end
		 End
		else if @Operation ='Insert_Caliper_PreCoupling_Data'
		 begin
						insert into Assy_Caliper_PreCoupling_Data
						(
							ProfitCenterCode,
							LineCode,
							MachineCode,
							Result,
							TimeStamp,
							Result2,
							Barcode
						)
						select @ProfitCode,@linecode,@MachineCode,@PreCoupling_Data,getdate(),
						@Result2, @CouplingBarcode
		end
		else if @Operation='Update_CaliperSrNo'
		begin
			   
				if exists
				(
						select 1 from assy_DayWise_SerialNo where ProfitCenterCode=@ProfitCode and LineCode =@LineCode  and PartNo=@EngPartNo and ProdDate=@ProdDate
				)
				begin
						 update assy_DayWise_SerialNo set SerialNo=isnull(SerialNo,0)+1 ,ModifiedTimestamp=getdate()
						 where ProfitCenterCode=@ProfitCode and LineCode =@LineCode  and PartNo=@EngPartNo and ProdDate=@ProdDate
				end
				else
					begin
						  insert into assy_DayWise_SerialNo(ProfitCenterCode,LineCode,PartNo,SerialNo,ProdDate,CreatedTimestamp)
													  select @ProfitCode,@LineCode,@EngPartNo,1,convert(date,getdate()),getdate()
					end		
		end		
		else if @Operation='Get_CaliperSrNo'
		begin
				--delete old date record				
				delete  from assy_DayWise_SerialNo where ProfitCenterCode=@ProfitCode and LineCode =@LineCode  and PartNo=@EngPartNo and ProdDate<>@ProdDate

				select @SerialNo=isnull(isnull(SerialNo,0),0) from assy_DayWise_SerialNo 
				where ProfitCenterCode=@ProfitCode and LineCode =@LineCode  and PartNo=@EngPartNo and ProdDate=@ProdDate

				set @ReturnValue=Convert(varchar(10),isnull(@SerialNo,0))
		end
		 --Added By Rashid On 20170606 For 2Parts Status
		ELSE IF @Operation ='GET_2PARTS_ALLOW_FLAG'
		BEGIN

			SELECT @ReturnValue = Allow2Parts FROM LineMst WITH (NOLOCK)  WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode
			SELECT @ReturnValue = ISNULL(@ReturnValue,''), @ReturnInt = 1
			RETURN
		END

		ELSE IF @Operation ='GET_STATION_ASSIGN_PART'
		BEGIN

		     IF @OPERATIONCODE='OC4S'
			 begin
			         SELECT top 1 @ReturnValue = assy_PartNo FROM Assy_runningpart WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode
			 end
			 else
			 begin
					SELECT @ReturnValue = PartNo FROM Assy_MachineWise_RunningPart WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LineCode 
					AND OperationCode = @OperationCode					
			 end
			 SELECT @ReturnValue = ISNULL(@ReturnValue,''), @ReturnInt = 1
			RETURN
		END

		ELSE IF @Operation = 'UPDATE_PART_NO_STATION_WISE_FROM_PLC'
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM Assy_MachineWise_RunningPart WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LINECODE AND OperationCode = @OPERATIONCODE)
			BEGIN
				INSERT INTO Assy_MachineWise_RunningPart (ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,PartNo,CreatedDate)
				SELECT @ProfitCode, @LINECODE, @MachineCode, @OPERATIONCODE, 1, @HMIPartNo, GETDATE()
			END
			ELSE
			BEGIN
				UPDATE Assy_MachineWise_RunningPart Set PartNo = @HMIPartNo, UpdatedDate = GETDATE()
					WHERE ProfitCenterCode = @ProfitCode AND LineCode = @LINECODE AND OperationCode = @OPERATIONCODE
			END

			SELECT @ReturnValue = 'SUCCESS', @ReturnInt = 1
			RETURN
		END
		ELSE IF @Operation = 'GetPartHandSuffix'
		BEGIN
			DECLARE @PartNo VARCHAR(20)
			SELECT @PartNo =Assy_PartNo FROM Assy_runningPart(NOLOCK) 
			WHERE LineCode=@LineCode AND ProfitCenterCode=@ProfitCode
			
			SELECT @ReturnValue= LabelDataValue FROM Assy_Coupling_LabelInfo_Mst(NOLOCK)
			WHERE LabelDataName='HAND' AND PartNo=@PartNo AND ProfitCenterCode=@ProfitCode

			SELECT @ReturnInt = 1
			RETURN
		END
		ELSE IF @Operation='SaveTorqueLog'
		BEGIN
			INSERT INTO Assy_TorqueLog(Barcode,ProfitCenterCode,LineCode,TorqueString,TagName,Ent_Dt)
			SELECT @Barcode,@ProfitCode,@LineCode,@TorqueString,@TagName,GETDATE()
		END
		else if(@Operation = 'GET_FilterTagsTemplate')
        Begin							
				SELECT   FilterId,[Index],TagName ,IsChkLength ,[Length] ,IsChkContent ,Content 
				,IsChkOKNGValue ,OKValue ,NGValue ,IsData ,IsSubString ,SubStringStart ,SubStringEnd 
				FROM [dbo].[Assy_MachineWiseFilterTagsTemplate] 
				where LineCode=@LineCode and ProfitcenterCode=@ProfitCode and MachineCode=@MachineCode
				order by FilterId,[Index] asc
		end
       --TRY BLOCK ENDS

       END TRY 
       BEGIN CATCH  
              --CATCH BLOCK BEGINS       
              SET @ReturnValue =   CAST(ERROR_NUMBER() as varchar(5)) + '|' + 
              CAST(ERROR_SEVERITY()as varchar(5)) + '|' + 
              CAST(ERROR_STATE() as varchar(5)) + '|' + 
              CAST(ERROR_PROCEDURE() as varchar(200)) + '|' + 
              CAST(ERROR_LINE() as varchar(5)) + '|' + 
              CAST(ERROR_MESSAGE() as varchar(1500))
              raiserror(@ReturnValue,16,1)
              SET @ReturnInt = 2
       --CATCH BLOCK ENDS 
       END CATCH
       END


GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_PokaYoke]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
-- AUTHOR:		<PRAVEEN KUMAR>
-- CREATE DATE: <03 SEP 2014>
-- DESCRIPTION:	<POKA YOKE .>

-- MODIFIED BY : <Rashid Siddiqui>
-- MODIFIED DATE: <19 March 2016>
-- DESCRIPTION:	<GET_PARTCODE block>

-- MODIFIED BY : <Sachin>
-- MODIFIED DATE: <19 05 2017>
-- DESCRIPTION:	<Return Part Type , Print POKA YOKE Barcode>

-- MODIFIED BY : <Sachin>
-- MODIFIED DATE: <21 08 2017>
-- DESCRIPTION:	<Configurable Flag Based Label Format>

-- TO REMBEMBER
-- NOTHING = 0
-- SUCCESS = 1
-- ERROR = 2
-- ALREADYEXISTS = 3
-- NOTEXISTS = 4
--exec [ASSY_PROC_POKAYOKE] @CONDITION='GET_CUST_PART_NO',@linecode='M07',@PROFITCENTERCODE ='0021',@PARTNUMBER='29049084'
--exec [ASSY_PROC_POKAYOKE] @CONDITION='GET_DATA',@linecode='M07',@PROFITCENTERCODE ='0021',@PARTNUMBER='29049084'
--exec [ASSY_PROC_POKAYOKE] @CONDITION='GET_SUB_MACHINE',@linecode='S01',@PROFITCENTERCODE ='0018',@PARTNUMBER='29049084'
--select * from assy_pokayoke
*/
CREATE PROC [dbo].[Assy_Proc_PokaYoke]
(
@CONDITION VARCHAR(100)=NULL,
@LINECODE VARCHAR(20)=NULL,
@PROFITCENTERCODE VARCHAR(20)=NULL,
@DATECODE VARCHAR(20)=NULL,
@PARTNUMBER VARCHAR(20)=NULL,
@CUSTPARTNO VARCHAR(200)=NULL,
@MACHINECODE VARCHAR(20)=NULL,
@POKAYOKENUMBER VARCHAR(20)=NULL,
@EXPIRYDATE VARCHAR(30)=NULL,
@BARCODE VARCHAR(100)=NULL,
@ISACTIVE BIT =NULL,
@USERID VARCHAR(12)=NULL,
@EXPRESULT VARCHAR(20)=NULL,
@RESVERREQUIRED BIT=0,
@DESCRIPTION VARCHAR(100)=NULL,
@RETURNVALUE VARCHAR (2000)=NULL OUT,
@RETURNINT INT=NULL OUT,
@NEWRECORD BIT=0,
@PARTTYPE varchar(20)=NULL,
@SubMachineCode varchar(10)=''
)
AS
BEGIN 


BEGIN TRY

		SET NOCOUNT ON	
		DECLARE @ERRORMSG AS VARCHAR(200)
		DECLARE @PACKETQTY AS DECIMAL(9,4)=0
		DECLARE @CHILDPART VARCHAR(20)
		DECLARE @LOTNUMBER VARCHAR(20)
		DECLARE @PARTQUANTITY DECIMAL(9,4)
		 
		DECLARE @EXECQUERY AS NVARCHAR(MAX),@LINKSERVERNAME VARCHAR(100)

		Declare @MachineLinkServerName varchar(100)						-- ADDED BY Rashid 20190506
				, @MachineLinkServerDB varchar(100)						-- ADDED BY Rashid 20190506
				, @MachineLinkServer varchar(300)						-- ADDED BY Rashid 20190506
				, @MachineDBRoutingLineWiseTableName varchar(100)		-- ADDED BY Rashid 20190506
				, @MachineDBRoutingPartWiseTableName varchar(100)		-- ADDED BY Rashid 20190506
				, @MachineDBPokaYokeMasterTableName varchar(100)		-- ADDED BY Rashid 20190506
				, @LinkServerType VARCHAR(60) = ''						-- ADDED BY Rashid 20190506
				, @Dynamic_Query VARCHAR(MAX) = ''						-- ADDED BY Rashid 20190506
				, @PartNo VARCHAR(50) = ''								-- ADDED BY Rashid 20190506

		SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL  WITH (NOLOCK) 
			WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE 
		--SELECT TOP 1 @PARTTYPE=PARTTYPE FROM ASSY_RUNNINGPART(NOLOCK) WHERE LINECODE=@LINECODE AND PROFITCENTERCODE=@PROFITCENTERCODE
		-- Add By Rashid on 30thJune2016
		IF ISNULL(@PARTTYPE,'') = ''
			SELECT TOP 1 @PARTTYPE=PARTTYPE FROM ASSY_RUNNINGPART(NOLOCK) WHERE LINECODE=@LINECODE AND PROFITCENTERCODE=@PROFITCENTERCODE
		
		--Added by Ravi on 12/12/2015
		IF @CONDITION='PART_TYPE'
		BEGIN
			    SELECT  @PARTTYPE=LINETYPEMST.LINETYPENAME FROM LINEMST(NOLOCK) 
				INNER JOIN LINETYPEMST(NOLOCK) ON LINEMST.LINETYPECODE=LINETYPEMST.LINETYPECODE AND LINEMST.ProfitCenterCode=LINETYPEMST.ProfitCenterCode
				WHERE LINEMST.LINECODE=@LINECODE AND LINEMST.PROFITCENTERCODE=@PROFITCENTERCODE
				IF @PARTTYPE='TMC'
				BEGIN
						SELECT 'TMC' AS [PART TYPE]
				END
			    ELSE IF @PARTTYPE='STMC'
				BEGIN
				        SELECT 'SELECT' AS [PART TYPE]
						UNION
						SELECT 'SERVO' AS [PART TYPE]
						UNION
						SELECT 'STMC' AS [PART TYPE]
				END
				ELSE IF @PARTTYPE='CALIPER' -- add by sachin 20170519
				BEGIN
				      SELECT 'CALIPER' AS [PART TYPE]
				END
				
				SET @RETURNVALUE='DATA SELECTED'
			    SET @RETURNINT=1
		END	
	 IF @CONDITION='GETPARAMETERS'
		BEGIN
			SELECT PARAMETER_C2,PARAMETER_NM,PARAMETER_VALUE FROM PARAMETER_MST(NOLOCK) 
			WHERE PARAMETER_C='ASSLINE' AND PARAMETER_C1='POKAYOKE' 
			AND   USER_CONFIGURABLE_FLG=1
			SET @RETURNVALUE='DATA SELECTED'
			SET @RETURNINT=1
		END
	 IF @CONDITION='GET_DATA'
	 BEGIN
			        SELECT PARTNUMBER [PART NUMBER],
					CUSTPARTNO  [CUST. PART NO.],
					MM.MACHINENAME [MACHINE NAME],
					POKAYOKENUMBER [POKA YOKE NUMBER],
					DATECODE AS [DATE CODE],
					CONVERT(VARCHAR(10),EXPIRYDATE,103) [EXPIRY DATE],
					BARCODE,PK.DESCRIPTION,PK.EXPRESULT[EXPECTED RESULT],PK.RESVERREQUIRED[RESULT VERIFICATION REQUIRED],
					PK.ISACTIVE AS ACTIVE, ( select distinct MachineName  from MACHINEMST(NOLOCK) where machineCode=PK.SubMachineCode
					and profitcenterCode=PK.ProfitCenterCode)as [SUB MACHINE NAME]  -- SUB MACHINE NAME added by sachin 20180419
					FROM [ASSY_POKAYOKE](NOLOCK) PK 
				        INNER JOIN MACHINEMST(NOLOCK) MM ON PK.MACHINECODE =MM.MACHINECODE  
					       inner join PRODUCT_MASTER  PM WITH (nolock)  on PM.SEWS_PART_NO =pk.PartNumber AND PM.warehouse_cd =pk.ProfitCenterCode 
					WHERE LINECODE=@LINECODE AND PK.ProfitCenterCode=@PROFITCENTERCODE AND isnull(PM.MATERIAL_TP ,'')=@PARTTYPE			
					ORDER BY PARTNUMBER,MM.MACHINENAME,BARCODE,EXPIRYDATE	
					SET @RETURNVALUE='DATA SELECTED'
					SET @RETURNINT=1
	 END
	 IF @CONDITION='SAVE'
	 BEGIN
			
			IF @NEWRECORD=1
			BEGIN
				 IF EXISTS(SELECT TOP 1 1 FROM [ASSY_POKAYOKE] WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND BARCODE=@BARCODE)
		         BEGIN
						SET @RETURNVALUE='BARCODE ALREADY EXISTS'
			            SET @RETURNINT=1						
						
						RETURN
				 END			     
			END

	       IF EXISTS(SELECT TOP 1 1 FROM [ASSY_POKAYOKE] WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND BARCODE=@BARCODE)
		   BEGIN
				
				 UPDATE [ASSY_POKAYOKE] SET 
				 EXPIRYDATE=CONVERT(VARCHAR(20),CONVERT(DATETIME,@EXPIRYDATE,103),107),
				 ISACTIVE=@ISACTIVE,
				 EXPRESULT=@EXPRESULT,
				 DESCRIPTION=@DESCRIPTION,
				 RESVERREQUIRED=@RESVERREQUIRED,
				 UPDBY=@USERID,
				 UPDDT=GETDATE ()				 
				 WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND BARCODE=@BARCODE
				
		   END
		   ELSE
		   BEGIN
		    IF @PARTTYPE='TMC' OR  @PARTTYPE='SERVO'
			 BEGIN
						INSERT INTO [ASSY_POKAYOKE]
						(
							PROFITCENTERCODE,LINECODE,DATECODE,PARTNUMBER
							,CUSTPARTNO,MACHINECODE,POKAYOKENUMBER
							,EXPIRYDATE
							,BARCODE,
							ISPRINTED,ENTBY,ENTDT,ISACTIVE,EXPRESULT,RESVERREQUIRED,DESCRIPTION,UpdBy,UpdDt,SubMachineCode
						)
						SELECT  @PROFITCENTERCODE,@LINECODE,@DATECODE ,@PARTNUMBER,						
								@CUSTPARTNO,@MACHINECODE,@POKAYOKENUMBER ,
								CONVERT(VARCHAR(20),CONVERT(DATETIME,@EXPIRYDATE,103),107),
								@BARCODE,
								1,@USERID,GETDATE(),@ISACTIVE,@EXPRESULT,@RESVERREQUIRED,@DESCRIPTION,@USERID,GETDATE(),ISNULL(@SubMachineCode,'')
			 END
			 ELSE
					 BEGIN
						INSERT INTO [ASSY_POKAYOKE]
						(
						PROFITCENTERCODE,LINECODE,DATECODE,PARTNUMBER,CUSTPARTNO,MACHINECODE,POKAYOKENUMBER,EXPIRYDATE,BARCODE,
						ISPRINTED,ENTBY,ENTDT,ISACTIVE,EXPRESULT,RESVERREQUIRED,DESCRIPTION,UpdBy,UpdDt,SubMachineCode
						)
						SELECT  @PROFITCENTERCODE,@LINECODE,@DATECODE ,@PARTNUMBER,						
								@CUSTPARTNO,
								@MACHINECODE,					
								@POKAYOKENUMBER ,
								CONVERT(VARCHAR(20),CONVERT(DATETIME,@EXPIRYDATE,103),107),
								@BARCODE,
								1,
								@USERID,GETDATE(),@ISACTIVE,@EXPRESULT,@RESVERREQUIRED,@DESCRIPTION,@USERID,GETDATE(),ISNULL(@SubMachineCode,'')
					 END
		   END

			SET @RETURNVALUE='DATA SAVED SUCCESSFULLY'
			SET @RETURNINT=1
	 END
	 IF @CONDITION='GET_CUST_PART_NO'
	 BEGIN
	  IF(SELECT isnull(MATERIAL_TP,'')MATERIAL_TP FROM PRODUCT_MASTER WITH (nolock) WHERE SEWS_PART_NO=@PARTNUMBER AND WAREHOUSE_CD=@PROFITCENTERCODE)='STMC'
	  BEGIN			   
			   select DISTINCT CustomerPartNo CUSTOMER_PART_NO from Assy_Coupling_LabelInfo_Mst WITH (nolock) WHERE ProfitCenterCode=@PROFITCENTERCODE 
			   AND PartNo=@PARTNUMBER
			   order by CUSTOMER_PART_NO
	  END 
	  ELSE
		BEGIN
				 SELECT '' CUSTOMER_PART_NO
		END
	 END

	  IF @CONDITION='GET_LABEL_DATA'
	 BEGIN
	    DECLARE @PART_IDENTIFICATION_CODE VARCHAR(20) 
		DECLARE @PLANT_CODE VARCHAR(20) ,@BOOST_RATIO VARCHAR(20),@MODEL_NAME VARCHAR(20),@PART_TYPE VARCHAR(20)	

	   SELECT @PART_IDENTIFICATION_CODE=LTRIM(RTRIM(LABELDATAVALUE)) FROM [ASSY_COUPLING_LABELINFO_MST] 
	   WHERE PARTNO=@PARTNUMBER AND CUSTOMERPARTNO=@CUSTPARTNO AND LABELDATANAME='PART_IDENTIFICATION_CODE'       
	   
	   SELECT @PLANT_CODE=LTRIM(RTRIM(LABELDATAVALUE))FROM [ASSY_COUPLING_LABELINFO_MST] 
	   WHERE PARTNO=@PARTNUMBER AND CUSTOMERPARTNO=@CUSTPARTNO AND LABELDATANAME='PLANT_CODE'
	   
	    SELECT @BOOST_RATIO=LTRIM(RTRIM(LABELDATAVALUE))FROM [ASSY_COUPLING_LABELINFO_MST] 
	   WHERE PARTNO=@PARTNUMBER AND CUSTOMERPARTNO=@CUSTPARTNO AND LABELDATANAME='BOOST_RATIO'
	     
		  SELECT @MODEL_NAME=LTRIM(RTRIM(LABELDATAVALUE))FROM [ASSY_COUPLING_LABELINFO_MST] 
	   WHERE PARTNO=@PARTNUMBER AND CUSTOMERPARTNO=@CUSTPARTNO AND LABELDATANAME='MODEL_NAME'
	    
		 SELECT @PART_TYPE=LTRIM(RTRIM(LABELDATAVALUE))FROM [ASSY_COUPLING_LABELINFO_MST] 
	   WHERE PARTNO=@PARTNUMBER AND CUSTOMERPARTNO=@CUSTPARTNO AND LABELDATANAME='PART_TYPE'



	   --select rtrim(ltrim(cp.ProfitCenterCode))ProfitCenterCode,rtrim(ltrim(CP.PartNo))PartNo,rtrim(ltrim(cp.CustomerPartNo))CustomerPartNo,right(rtrim(ltrim(cp.PartNo)),4)STMCLastFourDgtPartNo,@ServoBarcodeLstFourDgtSeqNo ServoLstFourDgtSeqNo
				--		,@ShiftDate ShiftDate
				--		,@ShiftCode ShiftID,@Linecode Linecode,@DateCode DateCode
				--		,rtrim(ltrim(LabelDataName))LabelDataName,rtrim(ltrim(LabelDataValue))LabelDataValue from  Assy_Coupling_LabelInfo_Mst(nolock) CP
				--		join Assy_RunningPart(nolock) RP on  cp.PartNo =rp.Assy_PartNo AND cp.CustomerPartNo =rp.CustomerPartNo AND CP.ProfitCenterCode=rp.ProfitCenterCode
				--		WHERE CP.ProfitCenterCode=@ProfitCenterCode AND RP.LineCode =@Linecode AND RP.assy_mode='PRODUCTION'
						

	   SELECT @PART_IDENTIFICATION_CODE PART_IDENTIFICATION_CODE,@PLANT_CODE  PLANT_CODE 
	 END
	 IF @CONDITION='GET_PARTCODE'
	 BEGIN
	       IF @PARTTYPE='STMC'
		   BEGIN
	     	   SELECT DISTINCT PM.SEWS_PART_NO,PM.PRODUCT_NM FROM ASSY_COUPLING_LABELINFO_MST CL WITH (NOLOCK) 
			   INNER JOIN PRODUCT_MASTER  PM WITH (NOLOCK)
					ON CL.PROFITCENTERCODE=PM.WAREHOUSE_CD AND CL.PARTNO=PM.SEWS_PART_NO
               INNER JOIN ROUTINGCONFIGPARTWISE PR WITH(NOLOCK)  ON PM.WAREHOUSE_CD=PR.PROFITCENTERCODE AND PM.SEWS_PART_NO=PR.PARTNO
			     WHERE PM.WAREHOUSE_CD =@PROFITCENTERCODE AND ISNULL(MATERIAL_TP,'')=@PARTTYPE 
			    ORDER BY PM.SEWS_PART_NO
          END
		  ELSE
				
				WITH CTE AS (
				SELECT  Distinct PartNo
						FROM ASSY_PRODUCTIONORDERMST(NOLOCK) PO 					
						WHERE ISNULL(PO.STATUS,'0') <> '100' AND PO.ProfitCenterCode = @PROFITCENTERCODE AND PO.isActive = 1
								AND PO.WorkCenterCode 
								IN
									( 
										SELECT  DISTINCT WorkCenterCode FROM LINEMST L WITH (NOLOCK)   
										INNER JOIN Assy_LineGroup_Master LG WITH (NOLOCK)
										ON L.ProfitCenterCode = LG.ProfitCenterCode AND L.LineCode = LG.LineCode
										WHERE LG.groupcode = (SELECT Top 1 GroupCode FROM Assy_LineGroup_Master WITH (NOLOCK) WHERE LineCode = @LINECODE)
										AND L.isActive = 1
									)
								)
				SELECT LTRIM(RTRIM(CTE.PartNo)) SEWS_PART_NO, RTRIM(LTRIM(RB.PRODUCT_NM)) PRODUCT_NM FROM CTE
				INNER JOIN
					(
					SELECT DISTINCT SEWS_PART_NO,PRODUCT_NM FROM PRODUCT_MASTER PM WITH (NOLOCK) 
					INNER JOIN RoutingConfigPartWise PR WITH (NOLOCK)
					ON PM.warehouse_cd = PR.ProfitCenterCode AND PM.SEWS_PART_NO = PR.PartNo
					WHERE PM.warehouse_cd = @PROFITCENTERCODE AND ISNULL(MATERIAL_TP,'') = @PARTTYPE 
					) RB
					ON RB.SEWS_PART_NO = CTE.PartNo
				ORDER BY 1
				
	 END
	 IF @CONDITION='GET_MACHINE'
	 BEGIN
			  IF @PARTTYPE='SERVO' OR @PARTTYPE='TMC'
			  begin
	  					 SELECT DISTINCT M.MACHINECODE,M.MACHINENAME,OperationSeqNo FROM MACHINEMST(NOLOCK) M INNER JOIN ROUTINGCONFIGLINEWISE(NOLOCK)RL 
		    			 ON M.MACHINECODE=RL.MACHINECODE AND M.PROFITCENTERCODE=RL.PROFITCENTERCODE
						 WHERE M.MACHINETYPE=@PARTTYPE AND M.PROFITCENTERCODE=@PROFITCENTERCODE AND RL.LINECODE=@LINECODE AND ISNULL(RL.POKA_YOKE_ALLOWED,0)=1
						 order by RL.OperationSeqNo
			  end
			  ELSE IF @PARTTYPE='STMC'
			  begin
	  					 SELECT DISTINCT M.MACHINECODE,M.MACHINENAME,OperationSeqNo FROM MACHINEMST(NOLOCK) M INNER JOIN ROUTINGCONFIGLINEWISE(NOLOCK)RL 
		    			 ON M.MACHINECODE=RL.MACHINECODE AND M.PROFITCENTERCODE=RL.PROFITCENTERCODE
						 WHERE M.MACHINETYPE=@PARTTYPE AND M.PROFITCENTERCODE=@PROFITCENTERCODE AND RL.LINECODE=@LINECODE AND ISNULL(RL.POKA_YOKE_ALLOWED,0)=1
						 order by RL.OperationSeqNo
			  end
			  ELSE IF @PARTTYPE='CALIPER' -- Added By Sachin 20170519
			  begin
	  					 SELECT DISTINCT M.MACHINECODE,M.MACHINENAME,OperationSeqNo FROM MACHINEMST(NOLOCK) M INNER JOIN ROUTINGCONFIGLINEWISE(NOLOCK)RL 
		    			 ON M.MACHINECODE=RL.MACHINECODE AND M.PROFITCENTERCODE=RL.PROFITCENTERCODE
						 WHERE M.MACHINETYPE=@PARTTYPE AND M.PROFITCENTERCODE=@PROFITCENTERCODE AND RL.LINECODE=@LINECODE AND ISNULL(RL.POKA_YOKE_ALLOWED,0)=1
						 order by RL.OperationSeqNo
			  end
	 END
	 IF @CONDITION='REPRINT'
	 BEGIN	      
			  UPDATE [ASSY_POKAYOKE] SET ISPRINTED=0  WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND BARCODE=@BARCODE			
		 SET @RETURNVALUE='REPRINT COMMAND FOR SELECTED BARCODES IS SEND.'
	     SET @RETURNINT=1
	 END
	IF @CONDITION='DELETE'
	 BEGIN
		DELETE FROM [ASSY_POKAYOKE]  WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND BARCODE=@BARCODE

		SET @EXECQUERY = 'DELETE FROM ' + @LINKSERVERNAME+'.dbo.Assy_PokaYoke WHERE LINECODE='''+@LINECODE+''' AND PROFITCENTERCODE='''+@PROFITCENTERCODE+''' AND Barcode = ''' + @BARCODE + ''''
		PRINT @EXECQUERY
		EXECUTE (@EXECQUERY)

		IF EXISTS
		(
			SELECT TOP 1 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
				AND LineCode = @LineCode AND KeyType = 'IsPushMasterDataIntoMESServerOnSetParameter' AND ISNULL(KeyValue,'0') = '1'
		)
		BEGIN
			SELECT TOP 1 @MachineLinkServerName = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode 
				AND LineCode = @LineCode AND KeyType = 'MachineDBLinkServerName' AND STS_CD = 0
				
			IF(ISNULL(@MachineLinkServerName,'') = '' )
			BEGIN
				SET @ReturnValue = 'Machine Link Server Name Configuration Not Found !! [RoutingConfigDetails Key: MachineDBLinkServerName] '
				SET @ReturnInt = 2
				RETURN
			END

			SELECT TOP 1 @MachineLinkServerDB = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
				AND LineCode = @LineCode AND KeyType = 'MachineDBLinkServerDB' AND STS_CD = 0

			IF(ISNULL(@MachineLinkServerDB,'') = '' )
			BEGIN
				SET @ReturnValue = 'Machine Link Server Database Configuration Not Found !! [RoutingConfigDetails Key: MachineDBLinkServerDB]'
				SET @ReturnInt = 2
				RETURN
			END

			SELECT TOP 1 @MachineDBPokaYokeMasterTableName = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
				AND LineCode = @LineCode AND KeyType = 'MachineDBPokaYokeMasterTableName' AND STS_CD = 0

			IF(ISNULL(@MachineDBPokaYokeMasterTableName,'') = '' )
			BEGIN
				SET @ReturnValue = 'Link Server Poka Yoke Master Table Configuration Not Found !! [RoutingConfigDetails Key: MachineDBPokaYokeMasterTableName] '
				SET @ReturnInt = 2
				RETURN
			END

			SELECT TOP 1 @LinkServerType = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
				AND LineCode = @LineCode AND KeyType = 'LinkServerType' AND STS_CD = 0

			IF(ISNULL(@LinkServerType,'') = '' )
			BEGIN
				SET @ReturnValue = 'Link Server Type Parameter Configuration Not Found !! [RoutingConfigDetails Key: LinkServerType] '
				SET @ReturnInt = 2
				RETURN
			END

			BEGIN TRY
				Declare @s sysname = REPLACE(REPLACE(@MachineLinkServerName,'[',''),']','')
				EXEC sys.sp_testlinkedserver @s
			END TRY
			BEGIN CATCH
				SET @ReturnValue = 'Kindly Check, Not Able To Connect MES SQL Server !!! ' + @MachineLinkServerName
				SET @ReturnInt = 2
				RETURN
			END CATCH

			IF(@LinkServerType = 'MSSQL')
			BEGIN
				SET @MachineLinkServer = @MachineLinkServerName + '.' + @MachineLinkServerDB
				SET @MachineLinkServer = REPLACE(@MachineLinkServer,'TABLE_NAME',@MachineDBPokaYokeMasterTableName)
				PRINT 'Assy_PokaYoke - LinkServer - ' + @MachineLinkServer

				EXEC Assy_Proc_PushMasterDataIntoMES @MachineLinkServer = @MachineLinkServer, @ProfitCenterCode = @ProfitCenterCode, @LineCode = @LineCode,
					@Condition = 'Assy_PokaYoke'
			END

			IF(@LinkServerType = 'MYSQL')
			BEGIN
				PRINT 'MYSQL Connection Code Required'
			END
		END

		 SET @RETURNVALUE='DATA DELETED SUCCESSFULLY'
	     SET @RETURNINT=1
	 END
	 IF @CONDITION='GET_LINE_TYPECODE'
	 BEGIN
	     SELECT LINETYPEMST.LINETYPENAME FROM LINEMST 
		INNER JOIN LINETYPEMST ON LINEMST.LINETYPECODE=LINETYPEMST.LINETYPECODE
		WHERE LINEMST.LINECODE=@LINECODE AND LINEMST.PROFITCENTERCODE=@PROFITCENTERCODE
		 SET @RETURNVALUE='DATA SELECTED'
	     SET @RETURNINT=1
	 END
	 IF @CONDITION='GET_PARTTYPE'
	 BEGIN
	    SELECT ISNULL(MATERIAL_TP,'')MATERIAL_TP FROM PRODUCT_MASTER(NOLOCK) WHERE WAREHOUSE_CD=@PROFITCENTERCODE  AND SEWS_PART_NO=@PARTNUMBER
		SET @RETURNVALUE='DATA SELECTED'
	    SET @RETURNINT=1
	 END	 
	 IF @CONDITION='CHECK_POKAYOKE_RESULT'
	  BEGIN
			IF EXISTS 
			(
				SELECT top 1 1 FROM ASSY_POKAYOKE_CURRENT_RESULT WITH (NOLOCK) WHERE ISNULL(ISPROCESSED,0 )=1 AND  
				(ISNULL(ACTRESULT,'')<>ISNULL(EXPRESULT,'') ) AND PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE =@LINECODE
			)
			BEGIN
				SELECT MACHINECODE,OPERATIONCODE,BARCODE,ISNULL(EXPRESULT,'')EXPRESULT,ISNULL(ACTRESULT,'')ACTRESULT FROM ASSY_POKAYOKE_CURRENT_RESULT WITH (NOLOCK)  
				WHERE ISNULL(ISPROCESSED,0 )=1 
				AND  (ISNULL(ACTRESULT,'')<>ISNULL(EXPRESULT,'')) AND PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE =@LINECODE
   
			   UPDATE  ASSY_POKAYOKE_CURRENT_RESULT SET ISPROCESSED=0  
			   WHERE ISNULL(ISPROCESSED,0 )=1 AND  (ISNULL(ACTRESULT,'')<>ISNULL(EXPRESULT,'')) AND PROFITCENTERCODE =@PROFITCENTERCODE AND LINECODE =@LINECODE
			   SET @RETURNVALUE='SUCCESS'
	           SET @RETURNINT=1
			END
	  END
	  ELSE IF @CONDITION = 'SAVE_DATA_IN_MAIN_SERVER'
	  BEGIN
            IF OBJECT_ID('TEMPDB..##Temp_Assy_PokaYoke') IS NOT NULL 
            BEGIN 
              DROP TABLE ##Temp_Assy_PokaYoke 
            END
			
            SELECT ProfitCenterCode,LineCode,Datecode,PartNumber,PartDescription,CustPartNo,MachineCode,MachineDescription,PokaYokeNumber,
				Description,ExpiryDate,Barcode,IsPrINTed,IsActive,EntBy,EntDt,UpdBy,UpdDt,ExpResult,ResVerRequired,SubMachineCode
            INTO ##Temp_Assy_PokaYoke FROM Assy_PokaYoke WITH (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE AND LineCode = @LINECODE
            
			IF EXISTS 
            ( 
              SELECT TOP 1 1 FROM  ##Temp_Assy_PokaYoke WITH (NOLOCK) 
            ) 
            BEGIN
				SET @EXECQUERY = N'SELECT ProfitCenterCode,LineCode,Datecode,PartNumber,PartDescription,CustPartNo,MachineCode,MachineDescription,PokaYokeNumber,Description,ExpiryDate,Barcode,IsPrINTed,IsActive,EntBy,EntDt,UpdBy,UpdDt,ExpResult,ResVerRequired,SubMachineCode FROM '
 

+ @EXECQUERY 
           
                SET @EXECQUERY = 'DELETE FROM ' + @LINKSERVERNAME+'.dbo.Assy_PokaYoke WHERE LINECODE='''+@LINECODE+''' AND PROFITCENTERCODE='''+@PROFITCENTERCODE+''''
                print @EXECQUERY
				
				EXECUTE (@EXECQUERY)
				
				SET @EXECQUERY = ''
				
				SET @EXECQUERY = '
				INSERT INTO ' + @LINKSERVERNAME+'.dbo.Assy_PokaYoke ' + '
                ( 
                ProfitCenterCode,LineCode,Datecode,PartNumber,PartDescription,CustPartNo,MachineCode,MachineDescription,PokaYokeNumber,
				Description,ExpiryDate,Barcode,IsPrINTed,IsActive,EntBy,EntDt,UpdBy,UpdDt,ExpResult,ResVerRequired,SubMachineCode
                ) 
                SELECT 
                ProfitCenterCode,LineCode,Datecode,PartNumber,PartDescription,CustPartNo,MachineCode,MachineDescription,PokaYokeNumber,
				Description,ExpiryDate,Barcode,IsPrINTed,IsActive,EntBy,EntDt,UpdBy,UpdDt,ExpResult,ResVerRequired,SubMachineCode
                
				FROM ##Temp_Assy_PokaYoke '
				PRINT @EXECQUERY
				EXEC (@EXECQUERY)
				print '--------3-----------'
				IF OBJECT_ID('TEMPDB..##Temp_Assy_PokaYoke') IS NOT NULL 
				BEGIN 
					DROP TABLE ##Temp_Assy_PokaYoke 
				END

				IF EXISTS
				(
					SELECT TOP 1 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
						AND LineCode = @LineCode AND KeyType = 'IsPushMasterDataIntoMESServerOnSetParameter' AND ISNULL(KeyValue,'0') = '1'
				)
				BEGIN
					SELECT TOP 1 @MachineLinkServerName = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode 
						AND LineCode = @LineCode AND KeyType = 'MachineDBLinkServerName' AND STS_CD = 0
				
					IF(ISNULL(@MachineLinkServerName,'') = '' )
					BEGIN
						SET @ReturnValue = 'Machine Link Server Name Configuration Not Found !! [RoutingConfigDetails Key: MachineDBLinkServerName] '
						SET @ReturnInt = 2
						RETURN
					END

					SELECT TOP 1 @MachineLinkServerDB = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
						AND LineCode = @LineCode AND KeyType = 'MachineDBLinkServerDB' AND STS_CD = 0

					IF(ISNULL(@MachineLinkServerDB,'') = '' )
					BEGIN
						SET @ReturnValue = 'Machine Link Server Database Configuration Not Found !! [RoutingConfigDetails Key: MachineDBLinkServerDB]'
						SET @ReturnInt = 2
						RETURN
					END

					SELECT TOP 1 @MachineDBPokaYokeMasterTableName = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
						AND LineCode = @LineCode AND KeyType = 'MachineDBPokaYokeMasterTableName' AND STS_CD = 0

					IF(ISNULL(@MachineDBPokaYokeMasterTableName,'') = '' )
					BEGIN
						SET @ReturnValue = 'Link Server Poka Yoke Master Table Configuration Not Found !! [RoutingConfigDetails Key: MachineDBPokaYokeMasterTableName] '
						SET @ReturnInt = 2
						RETURN
					END

					SELECT TOP 1 @LinkServerType = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
						AND LineCode = @LineCode AND KeyType = 'LinkServerType' AND STS_CD = 0

					IF(ISNULL(@LinkServerType,'') = '' )
					BEGIN
						SET @ReturnValue = 'Link Server Type Parameter Configuration Not Found !! [RoutingConfigDetails Key: LinkServerType] '
						SET @ReturnInt = 2
						RETURN
					END

					BEGIN TRY
						Declare @s1 sysname = REPLACE(REPLACE(@MachineLinkServerName,'[',''),']','')
						EXEC sys.sp_testlinkedserver @s1
					END TRY
					BEGIN CATCH
						SET @ReturnValue = 'Kindly Check, Not Able To Connect MES SQL Server !!! ' + @MachineLinkServerName
						SET @ReturnInt = 2
						RETURN
					END CATCH

				   IF(@LinkServerType = 'MSSQL')
					BEGIN
						SET @MachineLinkServer = @MachineLinkServerName + '.' + @MachineLinkServerDB
						SET @MachineLinkServer = REPLACE(@MachineLinkServer,'TABLE_NAME',@MachineDBPokaYokeMasterTableName)
						PRINT 'Assy_PokaYoke - LinkServer - ' + @MachineLinkServer

						EXEC Assy_Proc_PushMasterDataIntoMES @MachineLinkServer = @MachineLinkServer, @ProfitCenterCode = @ProfitCenterCode, @LineCode = @LineCode,
							@Condition = 'Assy_PokaYoke'
					END

					IF(@LinkServerType = 'MYSQL')
					BEGIN
						PRINT 'MYSQL Connection Code Required'
					END
				END

			   SET @RETURNVALUE='SUCCESS'
	           SET @RETURNINT=1
			END
	END
	IF @CONDITION='CALIPER_REPRINT' -- added by sachin print POKE YOKE Barcode
	BEGIN
			DECLARE @PRNFILE NVARCHAR(2000) = ''
			DECLARE @PKYK_PRINT_OPTION NVARCHAR(20)=''
			 
			UPDATE [ASSY_POKAYOKE] SET ISPRINTED=0  WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND BARCODE=@BARCODE
			
			select @PKYK_PRINT_OPTION=ISNULL(KeyValue,'') from RoutingConfigDetails(nolock) where 
			PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND KeyType='PKYKPrintOption' AND STS_CD=0

			if(ISNULL(@PKYK_PRINT_OPTION,'')='')
			BEGIN
					SET @RETURNVALUE='PRINT_OPTION_NOT_FOUND'
					SET @RETURNINT=0
					return
			END

			if (@PKYK_PRINT_OPTION='Option_1')
			begin
			SELECT top 1 @PRNFILE=PRNFile FROM [DBO].[ASSY_PRN_GROUPMASTER](NOLOCK) WHERE GROUPCODE='POKA_YOKE'
			
				if(ISNULL(@PRNFILE,'')='')
				BEGIN
						SET @RETURNVALUE='PRN_FILE_NOT_FOUND'
						SET @RETURNINT=0
						return
				END
				ELSE
				BEGIN
							SET @PRNFILE=REPLACE(@PRNFILE,'V_BARCODE',ISNULL(@BARCODE,''))
							SET @PRNFILE=REPLACE(@PRNFILE,'V_TEXT',ISNULL(@BARCODE,''))
							SET @RETURNVALUE=@PRNFILE
							SET @RETURNINT=1
			
				END
			END
			
			if (@PKYK_PRINT_OPTION='Option_2')
			begin

				select @PRNFILE=ISNULL(KeyValue,'') from RoutingConfigDetails(nolock) where 
				PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND KeyType='PKYKPrintZPL' AND STS_CD=0	
				
				if(ISNULL(@PRNFILE,'')='')
				BEGIN
						SET @RETURNVALUE='PRN_FILE_NOT_FOUND'
						SET @RETURNINT=0
						return
				END
				ELSE
				BEGIN
							SET @PRNFILE=REPLACE(@PRNFILE,'@PKYKDATECODE',ISNULL(SUBSTRING(@BARCODE,1,4),''))
							SET @PRNFILE=REPLACE(@PRNFILE,'@SERIAL',ISNULL(SUBSTRING(@BARCODE,5,4),''))
							SET @PRNFILE=REPLACE(@PRNFILE,'@PRINTCONTENT',ISNULL(@BARCODE,''))
							SET @RETURNVALUE=@PRNFILE
							SET @RETURNINT=1
			
				END
			end
	END

	IF @CONDITION='GETLABELPARAMETERS'
	BEGIN
			DECLARE @PKYK_SERIAL_LEN varchar(2)
			DECLARE @PKYK_IS_PART_REQ varchar(1)
			DECLARE @PKYK_IS_LINE_REQ varchar(1)

			select @PKYK_SERIAL_LEN=ISNULL(KeyValue,'0') from routingConfigDetails(NOLOCK) 
			where PROFITCENTERCODE=@PROFITCENTERCODE 
			AND LINECODE=@LINECODE AND KeyType='PKYKSerialLen' 
			AND STS_CD=0

			select @PKYK_IS_PART_REQ=ISNULL(KeyValue,'0') from routingConfigDetails(NOLOCK) 
			where PROFITCENTERCODE=@PROFITCENTERCODE 
			AND LINECODE=@LINECODE AND KeyType='PKYKIsPartRequired' 
			AND STS_CD=0

			select @PKYK_IS_LINE_REQ=ISNULL(KeyValue,'0') from routingConfigDetails(NOLOCK) 
			where PROFITCENTERCODE=@PROFITCENTERCODE 
			AND LINECODE=@LINECODE AND KeyType='PKYKIsLineRequired' 
			AND STS_CD=0

			SELECT ISNULL(@PKYK_SERIAL_LEN,'0'),ISNULL(@PKYK_IS_PART_REQ,'0'),ISNULL(@PKYK_IS_LINE_REQ,'0')
			
			
	END

	IF @CONDITION='GET_SUB_MACHINE'
	BEGIN
			 select s.SubMachineCode,m.MachineName from [RoutingConfigLineWiseForSubStation] (nolock) s inner join
			 [RoutingConfigLineWise](nolock) l on s.MachineCode=l.MachineCode
			 inner join MachineMst(nolock) m on m.machineCode=s.submachineCode
			 where l.profitcenterCode=@PROFITCENTERCODE and l.lineCode=@LINECODE
			 and s.profitcenterCode=@PROFITCENTERCODE and s.lineCode=@LINECODE
			 and m.profitcenterCode=@PROFITCENTERCODE 
			 and isnull(l.ISPOKAYOKEFORSUBSTATION,0)=1
	END


	
	END TRY
	BEGIN CATCH
			
			SET @RETURNVALUE =	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
			CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
			CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
			CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
			CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
			CAST(ERROR_MESSAGE() AS VARCHAR(1500))		
			
			SET @RETURNINT = 2
			raiserror(@RETURNVALUE,16,1)
	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[Assy_PROC_PokaYoke_Approval]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[Assy_PROC_PokaYoke_Approval]
(
	@Condition VARCHAR(100) = NULL,
	@LineCode VARCHAR(20) = NULL,
	@CurrentLineCode VARCHAR(20) = NULL,
	@OperationCode VARCHAR(20) = NULL,
	@ProfitCenterCode VARCHAR(20) = NULL,
	@DateCode CHAR(4) = NULL,
	@PartNumber VARCHAR(20) = NULL,
	@IsPokaYokeApproved BIT = 0,
	@UserID VARCHAR(20) = NULL,
	@Enable_Prod_Conf INT = 0,
	@CaptionName VARCHAR(200) = NULL,
	@ReturnValue VARCHAR (2000) = NULL OUT,
	@ReturnInt INT = NULL OUT
)
AS
BEGIN
	-- =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  = 
	-- Author:			< Rashid Siddiqui >
	-- Create Date:		< 17-03-2016 >
	-- Description:		< Poka Yoke Approval >
	-- Modified by:		< Rashid Siddiqui >
	-- Modified Date:	< 16-Jan-2017 >
	-- Description:		< Poka Yoke Approval For Line Type Wise Only By Default All Coming in GETLINENAMEDETAILS Block >
-- =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  = 
	BEGIN TRY
		SET NOCOUNT ON;
		Declare @LineTypeCode VARCHAR(20) = ''
		SELECT Top 1 @LineTypeCode = LineTypeCode FROM LineMst (NOLOCK) WHERE LineCode = @CurrentLineCode AND ProfitCenterCode = @ProfitCenterCode

		IF(@Condition = 'GETLINENAMEDETAILS')
		BEGIN
			IF(@LineCode <> '')
			BEGIN
				--SET @LineCode = (SELECT Top 1 LineCode FROM LineMst (NOLOCK) WHERE LineName = @LineCode)
				
				SELECT DISTINCT APK.LineCode, LM.LineName, APK.ProfitCenterCode, APK.DateCode, APK.PartNo, APK.UserID
					FROM LineMst LM (NOLOCK) INNER JOIN
						Assy_POKAYOKE_Status APK (NOLOCK) ON LM.LineCode = APK.LineCode
							WHERE APK.IsApproved = 0 AND APK.LineCode = @LineCode
								Order By 1,4,5,6
			END
			ELSE
			BEGIN
				SELECT DISTINCT APK.LineCode, LM.LineName, APK.ProfitCenterCode, APK.DateCode, APK.PartNo, APK.UserID
						FROM LineMst LM (NOLOCK) INNER JOIN
							Assy_POKAYOKE_Status APK (NOLOCK) ON LM.LineCode = APK.LineCode
								WHERE APK.IsApproved = 0
									AND APK.LineCode IN (SELECT DISTINCT LineCode FROM LineMst (NOLOCK) WHERE LineTypeCode = @LineTypeCode AND ProfitCenterCode = @ProfitCenterCode)
										Order By 1,4,5,6
			END

			SET @ReturnValue = 'SUCCESS'
			SET @ReturnInt = 0
			RETURN
		END

		ELSE IF(@Condition = 'GETISAPPROVED')
		BEGIN
			--SET @LineCode = (SELECT Top 1 LineCode FROM LineMst (NOLOCK) WHERE LineName = @LineCode)
			
			SELECT DISTINCT APS.PartNo, APS.DateCode, APS.LineCode, LM.LineName, APS.IsApproved 
				FROM Assy_POKAYOKE_Status APS (NOLOCK) INNER JOIN
					LineMst LM (NOLOCK) ON APS.LineCode = LM.LineCode
						WHERE APS.LineCode = @LineCode AND APS.ProfitCenterCode = @ProfitCenterCode	AND	APS.DateCode = @DateCode AND APS.PartNo = @PartNumber
							AND APS.IsApproved = 0
			
			SET @ReturnValue = 'SUCCESS'
			SET @ReturnInt = 0
		END

		ELSE IF(@Condition = 'GETLINENAMES')
		BEGIN
			SELECT DISTINCT LM.LineName, LM.LineCode
				FROM LineMst LM (NOLOCK) LEFT OUTER JOIN
					Assy_POKAYOKE_Status APS (NOLOCK) ON LM.LineCode = APS.LineCode
						WHERE APS.LineCode IN (SELECT DISTINCT LineCode FROM LineMst (NOLOCK) WHERE LineTypeCode = @LineTypeCode AND ProfitCenterCode = @ProfitCenterCode)
							AND APS.IsApproved = 0
							Order By 2,1
			SET @ReturnValue = 'SUCCESS'
			SET @ReturnInt = 0
		END

		ELSE IF(@Condition = 'SAVE')
		BEGIN
			--SET @LineCode = (SELECT Top 1 LineCode FROM LineMst WHERE LineName = @LineCode)
			
			INSERT INTO Assy_POKAYOKE_Approval
			(
				ProfitCenterCode,
				LineCode,
				DateCode,
				PartNumber,
				IsPokaYokeApproved,
				UserID,
				[TimeStamp]
			)
			VALUES
			(
				@ProfitCenterCode,
				@LineCode,
				@DateCode,
				@PartNumber,
				@IsPokaYokeApproved,
				@UserID,
				GETDATE()
			)

			UPDATE Assy_POKAYOKE_Status SET IsApproved = 1
				WHERE LineCode = @LineCode AND DateCode = @DateCode AND PartNo = @PartNumber

			SET @ReturnValue = 'SUCCESS'
			SET @ReturnInt = 0
		END

		ELSE IF (@Condition = 'GET_LINECODE')
		BEGIN
			SELECT L.LineCode, L.LineName FROM LineMst L (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LEFT(LineCode,1) = LEFT(@LineCode,1) Order By 2
			SET @ReturnInt = 1
		END		
	
		ELSE IF @Condition = 'GET_POKAYOKE_CONF_STATUS'
		BEGIN
			SELECT ISNULL(isPokaYokeMandatory,0) isPokaYokeMandatory FROM LineMst (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
			SET @ReturnInt = 1
			RETURN
		END
		  
		ELSE IF @Condition = 'ENABLE_DISABLE_POKAYOKE'
		BEGIN
			IF(@Enable_Prod_Conf = 1)
			BEGIN
				UPDATE LineMst SET isPokaYokeMandatory = 1 WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
				--SELECT ISNULL(isPokaYokeMandatory,0) isPokaYokeMandatory FROM LineMst (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
			END

			IF(@Enable_Prod_Conf = 0)
			BEGIN
				UPDATE LineMst SET isPokaYokeMandatory = 0 WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
				UPDATE Assy_Scan_OK SET isPokaYokeCompleted = 0 WHERE LineCode = @LineCode
				DELETE FROM Assy_LineAssyStatus_Running WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode AND DateCode = 'PKYK'
				UPDATE Assy_Scan_OK_History_For_PokaYoke SET BARCODE = '', IsCycleStarted = 0 WHERE LineCode = @LineCode
			END

			SELECT ISNULL(isPokaYokeMandatory,0) isPokaYokeMandatory FROM LineMst (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode

			IF EXISTS
			(
				SELECT TOP 1 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
					AND LineCode = @LineCode AND KeyType = 'EnableDisablePokaYokeStatusMailFromCentral' AND ISNULL(KeyValue,'0') = '1'
			)
			BEGIN
				----Mail Configuration on Enable/Disbale of Poka Yoke By RS On 20190425----
				Declare @LineName VARCHAR(100) = '', @Message VARCHAR(MAX) = '', @Web_To_eMailId VARCHAR(MAX) = '', @Web_Cc_eMailId VARCHAR(MAX) = '', @Subject VARCHAR(MAX) = ''

				SELECT @LineName = LTRIM(RTRIM(LineName)) FROM LineMst WITH (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
			
				SELECT @Web_To_eMailId = dbo.ASSY_FN_GET_PARAMETER_VALUE('AssLine', 'BYPASS_UNBYPASS_PLC', 'ALERT_LIST_TO', @ProfitCenterCode)
				SELECT @Web_Cc_eMailId = dbo.ASSY_FN_GET_PARAMETER_VALUE('AssLine', 'BYPASS_UNBYPASS_PLC', 'ALERT_LIST_CC', @ProfitCenterCode)
			
				SET @Message ='</BR></BR>Dear User,</BR></BR>'						
				SELECT @Message = ISNULL(@Message, '') + 'Please find the below details of Enable / Disable Poka Yoke Status in Assembly Line for Unit - '  
							+ @ProfitCenterCode + '</BR></BR>'
			
				SELECT @Subject = 'Enable / Disable Poka Yoke Status in Unit '+ @ProfitCenterCode +' for Assembly Line - ' + @LineName + ' ( ' + @LineCode + ' )'
			
				CREATE Table #Mail_Data_Enable_Disable_PokaYoke
				(
					ProfitCenterCode VARCHAR(10),
					LineCode VARCHAR(10),
					LineName VARCHAR(50),
					Status VARCHAR(50),
					UserName VARCHAR(50),
				)

				IF (@Enable_Prod_Conf = 1)
				BEGIN
					INSERT INTO #Mail_Data_Enable_Disable_PokaYoke(ProfitCenterCode,LineCode,LineName,Status,UserName)
					SELECT @ProfitCenterCode,@LineCode,@LineName,'Enabled',@UserID
				END
				ELSE IF (@Enable_Prod_Conf = 0)
				BEGIN
					INSERT INTO #Mail_Data_Enable_Disable_PokaYoke(ProfitCenterCode,LineCode,LineName,Status,UserName)
					SELECT @ProfitCenterCode,@LineCode,@LineName,'Disabled',@UserID
				END

				IF (@Web_To_eMailId != '')
				BEGIN
					SELECT  @Message = @Message + REPLICATE('*',70) + '</BR></BR>'
					Declare @PostMsg NVARCHAR(MAX)
				
					EXEC PROC_TABLE_TO_HTML @P_HTML = @PostMsg OUTPUT, @P_DYNSQL = '#Mail_Data_Enable_Disable_PokaYoke', @P_TABLESTR = '#tablestr', @P_Orderby = '';
					SELECT @Message = @Message + ISNULL(@PostMsg,'');
					SELECT @Message = @Message + '</BR>' + dbo.FN_GET_SERVER_DETAILS() + '</BR>'
					SELECT @Message = @Message + REPLICATE('*',70) + '</BR>'
				
					IF (ISNULL(@Message,'') <> '')
					BEGIN
						EXEC PROC_SEND_MAIL @Web_To_eMailId, '', @Message, @Subject, @Web_Cc_eMailId,'','HTML'
					END
				END
				----Mail Configuration on Enable/Disbale of Poka Yoke By RS On 20190425----
			END
		END
	
		ELSE IF @Condition = 'Get_PokaYokeStation'
		BEGIN
			SELECT RTRIM(ISNULL(R.OperationCode,'')) OperationCodeCode, RTRIM(ISNULL(O.OperationName,'')) OperationCodeName
				FROM RoutingConfigLineWise R WITH (NOLOCK)
					INNER JOIN OperationMst O WITH (NOLOCK)
						ON O.ProfitCenterCode = R.ProfitCenterCode AND O.OperationCode = R.OperationCode
							WHERE R.ProfitCenterCode = @ProfitCenterCode AND R.LineCode = @LineCode AND ISNULL(R.POKA_YOKE_ALLOWED,0) = 1 AND ISNULL(R.Traceability,0) = 1
		END

		ELSE IF @Condition = 'Bypass_PokaYokeStation'
		BEGIN
			DECLARE @ExecQuery AS NVARCHAR(MAX), @LinkServerName VARCHAR(500)
		
			SELECT @LinkServerName = LinkServerName + '.' + DataBaseName FROM Assy_LinkServer_Dtl with (nolock) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode

			UPDATE Assy_Scan_OK SET isPokaYokeCompleted = 1 WHERE LineCode = @LineCode AND OperationCode = @OperationCode

			SET @ReturnValue = 'SUCCESS'
			SET @ReturnInt = 1

			SET @ExecQuery = 'INSERT INTO ' + @LinkServerName + '.dbo.QCUsers_Login_History (UserID, CaptionName, LineCode, Status)
							Values ( '''+ @UserID + ''','''+ @CaptionName + ''','''+ @LineCode + ''',''UPDATE'' )'
			EXEC (@ExecQuery)
		END

		ELSE IF @Condition = 'Status_Bypass_PokaYokeStation'
		BEGIN
			DECLARE @isPokaYokeCompleted INT = 0
			
			SELECT @isPokaYokeCompleted = ISNULL(isPokaYokeCompleted,0) FROM Assy_Scan_OK (NOLOCK)
				WHERE LineCode = @LineCode AND OperationCode = @OperationCode

			SET @ReturnValue = @isPokaYokeCompleted
			SET @ReturnInt = 1
		END
	END TRY
	BEGIN CATCH
		SET @ReturnValue = 	CAST(ERROR_NUMBER() as VARCHAR(5)) + '|' + 
		CAST(ERROR_SEVERITY()as VARCHAR(5)) + '|' + 
		CAST(ERROR_STATE() as VARCHAR(5)) + '|' + 
		CAST(ERROR_PROCEDURE() as VARCHAR(200)) + '|' + 
		CAST(ERROR_LINE() as VARCHAR(5)) + '|' + 
		CAST(ERROR_MESSAGE() as VARCHAR(1500))
		RAISERROR (@ReturnValue,16,1)						
		SET @ReturnInt = 2
	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_Pokayoke_Check]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Assy_Proc_Pokayoke_Check] 
(
	@CONDITION VARCHAR(100)=NULL,
	@PROFITCENTERCODE VARCHAR(20)=NULL,
	@PARTNUMBER VARCHAR(20)=NULL,
	@LINECODE VARCHAR(20)=NULL,
	@MACHINCODE VARCHAR(50)=NULL,
	@OPERATIONNAME VARCHAR(50)=NULL,
	@OPERATIONCODE VARCHAR(50)=NULL,
	@Part_FixtureGroupType VARCHAR(20) = NULL,
	@NewPokaYokeGroup INT = NULL,
	@SelectionType VARCHAR(20) = NULL,
	@ReferencePartNo VARCHAR(15) = NULL,
	@UserID VARCHAR(20) = NULL,
	@BARCODE VARCHAR(50)=NULL,
	@RETURNVALUE VARCHAR (2000)=NULL OUT,
	@RETURNINT INT=NULL OUT
)
AS
BEGIN
-- =============================================
-- AUTHOR:		SUNDARA MOORTHI
-- CREATE DATE: 21-01-2016
-- MODIFIED BY: Rashid Siddiqui
-- MODIFIED DATE: 29-Aug-2016
-- DESCRIPTION:	Description Column is added in Poka Yoke Status Form
-- =============================================
	SET NOCOUNT ON;

	--EXEC [ASSY_PROC_POKAYOKE_CHECK] @CONDITION='GET_OPERATION_NAME',@LINECODE='M03'
	--EXEC [ASSY_PROC_POKAYOKE_CHECK] @CONDITION='GET_POKAYOKE_AVAIL',@LINECODE='M03'
	--EXEC [ASSY_PROC_POKAYOKE_CHECK] @CONDITION='GET_POKAYOKE_DETAILS',@LINECODE='P5',@PROFITCENTERCODE='0021'
	

	BEGIN TRY
		IF(@CONDITION='GET_POKAYOKE_DETAILS')
		BEGIN					
					--WITH CTEPK
					--AS
					--(
					--	SELECT DISTINCT PK.PROFITCENTERCODE,PK.LINECODE,PK.PARTNUMBER,PK.MACHINECODE,M.MACHINENAME,PR.OPERATIONCODE,O.OPERATIONNAME,PK.BARCODE,PK.EXPRESULT 
					--	FROM ASSY_POKAYOKE PK WITH(NOLOCK) 
					--	INNER JOIN ROUTINGCONFIGPARTWISE PR WITH (NOLOCK) ON 
					--		--PR.PART_FIXTUREGROUPTYPE=DBO.ASSY_FN_GET_RUNNINGPART_FIXTURECODE(@PROFITCENTERCODE,@LINECODE)
					--		--AND 
					--		PK.PROFITCENTERCODE=PR.PROFITCENTERCODE AND PK.MACHINECODE=PR.MACHINECODE AND PK.PARTNUMBER=PR.PARTNO
					--	INNER JOIN MACHINEMST M WITH(NOLOCK)  ON M.MACHINECODE=PR.MACHINECODE
					--	INNER JOIN OPERATIONMST O WITH(NOLOCK)  ON O.OPERATIONCODE=PR.OPERATIONCODE
					--	INNER JOIN ROUTINGCONFIGLINEWISE L WITH (NOLOCK)ON PK.PROFITCENTERCODE=L.PROFITCENTERCODE AND PK.LINECODE=L.LINECODE AND PK.MACHINECODE=L.MACHINECODE 
					--		AND PR.OPERATIONCODE=L.OPERATIONCODE
					--		WHERE PK.PROFITCENTERCODE=@PROFITCENTERCODE AND PK.LINECODE=@LINECODE AND ISNULL(L.OPERATIONREQUIRED,0)=1 
					--		AND ISNULL(L.TRACEABILITY,0)=1 AND ISNULL(L.POKA_YOKE_ALLOWED,0)=1 AND ISNULL(PK.ISACTIVE,0)=1
					--		AND PR.PART_FIXTUREGROUPTYPE=DBO.ASSY_FN_GET_RUNNINGPART_FIXTURECODE(@PROFITCENTERCODE,@LINECODE)
					--)

					--SELECT LINECODE,MACHINENAME,OPERATIONNAME,PARTNUMBER,BARCODE,EXPRESULT,STATUS FROM 
					--(
					--	SELECT DISTINCT PK.LINECODE,PK.MACHINENAME,PK.OPERATIONNAME,PK.PARTNUMBER, PK.BARCODE,PK.EXPRESULT,PK.MACHINECODE,PK.OPERATIONCODE,
					--	CASE 
					--		WHEN ISNULL(ASSY.STATUS,'') <>'' 
					--		AND ASSY.OPERATIONCODE=PK.OPERATIONCODE
					--		THEN 'COMPLETED'								
					--		ELSE 'PENDING' END AS [STATUS]   FROM CTEPK PK WITH(NOLOCK)
						
					--		 LEFT JOIN ASSY_LINEASSYSTATUS_RUNNING ASSY WITH (NOLOCK) 
					--		ON PK.PROFITCENTERCODE =ASSY.PROFITCENTERCODE AND PK.LINECODE =ASSY.LINECODE 
					--		AND PK.MACHINECODE =ASSY.MACHINECODE 
					--		AND PK.OPERATIONCODE=ASSY.OPERATIONCODE
					--		AND PK.BARCODE =ASSY.BARCODE
					--)M
					--ORDER BY M.MACHINECODE,M.OPERATIONCODE,M.BARCODE							
				
				IF OBJECT_ID('Tempdb..#Result') IS NOT NULL
				BEGIN
					DROP TABLE #Result
				END;

				WITH CTEPK
					AS
					(
						SELECT DISTINCT PK.PROFITCENTERCODE,PK.LINECODE,PK.PARTNUMBER,PK.MACHINECODE,M.MACHINENAME,PR.OPERATIONCODE,O.OPERATIONNAME,PK.BARCODE,PK.EXPRESULT, PK.Description
						FROM ASSY_POKAYOKE PK WITH(NOLOCK) 
						INNER JOIN ROUTINGCONFIGPARTWISE PR WITH (NOLOCK) ON 
							--PR.PART_FIXTUREGROUPTYPE=DBO.ASSY_FN_GET_RUNNINGPART_FIXTURECODE(@PROFITCENTERCODE,@LINECODE)
							--AND 
							PK.PROFITCENTERCODE=PR.PROFITCENTERCODE AND PK.MACHINECODE=PR.MACHINECODE AND PK.PARTNUMBER=PR.PARTNO
						INNER JOIN MACHINEMST M WITH(NOLOCK)  ON M.MACHINECODE=PR.MACHINECODE
						INNER JOIN OPERATIONMST O WITH(NOLOCK)  ON O.OPERATIONCODE=PR.OPERATIONCODE
						INNER JOIN ROUTINGCONFIGLINEWISE L WITH (NOLOCK)ON PK.PROFITCENTERCODE=L.PROFITCENTERCODE AND PK.LINECODE=L.LINECODE AND PK.MACHINECODE=L.MACHINECODE 
							AND PR.OPERATIONCODE=L.OPERATIONCODE
							WHERE PK.PROFITCENTERCODE=@PROFITCENTERCODE AND PK.LINECODE=@LINECODE AND ISNULL(L.OPERATIONREQUIRED,0)=1 
							AND ISNULL(L.TRACEABILITY,0)=1 AND ISNULL(L.POKA_YOKE_ALLOWED,0)=1 AND ISNULL(PK.ISACTIVE,0)=1
							AND PR.PART_FIXTUREGROUPTYPE=DBO.ASSY_FN_GET_RUNNINGPART_FIXTURECODE(@PROFITCENTERCODE,@LINECODE)
					)


					SELECT LINECODE,MACHINENAME,OPERATIONNAME,PARTNUMBER,BARCODE,EXPRESULT,STATUS,ISNULL([Description],'') [Description],IDENTITY(int, 1,1) AS AutoID INTO #Result FROM 
					(
						SELECT DISTINCT PK.LINECODE,PK.MACHINENAME,PK.OPERATIONNAME,PK.PARTNUMBER, PK.BARCODE,PK.EXPRESULT,PK.MACHINECODE,PK.OPERATIONCODE,
						CASE --Comment By  Rashid on 27th July 2016
							--WHEN ISNULL(ASSY.STATUS,'') <>'' 
							WHEN PK.ExpResult<>CASE WHEN ASSY.Status='PS' THEN 'PASS' ELSE ASSY.Status END AND PK.ExpResult='PASS'
							THEN 'PENDING'
							WHEN ISNULL(ASSY.STATUS,'') <>'' 
							AND ASSY.OPERATIONCODE=PK.OPERATIONCODE
							THEN 'COMPLETED'				
							ELSE 'PENDING' END AS [STATUS], [Description]  FROM CTEPK PK WITH(NOLOCK)
						
							 LEFT JOIN ASSY_LINEASSYSTATUS_RUNNING ASSY WITH (NOLOCK) 
							ON PK.PROFITCENTERCODE =ASSY.PROFITCENTERCODE AND PK.LINECODE =ASSY.LINECODE 
							AND PK.MACHINECODE =ASSY.MACHINECODE 
							AND PK.OPERATIONCODE=ASSY.OPERATIONCODE
							AND PK.BARCODE =ASSY.BARCODE
					)M
					ORDER BY M.MACHINECODE,M.OPERATIONCODE,M.BARCODE
				---SELECT * FROM #Result
				IF EXISTS(SELECT 1 FROM #Result WHERE Status = 'PENDING')
				BEGIN
					Declare @StartLoop INT = 1, @EndLoop INT = 0, @DeleteBarcode VARCHAR(50) = '', @DeleteOperationName VARCHAR(100) = ''
					SELECT @EndLoop = COUNT(*) FROM #Result
					WHILE (@StartLoop <= @EndLoop)
					BEGIN
						SET @DeleteBarcode = ''
						SELECT @DeleteBarcode = Barcode, @DeleteOperationName = OperationName FROM #Result WHERE Status = 'PENDING' AND AutoID = @StartLoop
						IF EXISTS (SELECT 1 FROM #Result WHERE Status = 'COMPLETED' AND Barcode = @DeleteBarcode AND OperationName = @DeleteOperationName)
						BEGIN
							DELETE FROM #Result WHERE Status = 'PENDING' AND AutoID = @StartLoop AND Barcode = @DeleteBarcode AND OperationName = @DeleteOperationName
						END
						SET @StartLoop = @StartLoop + 1	
					END
				END
				--Comment By  Rashid on 27th July 2016
				--SELECT LINECODE,MACHINENAME,OPERATIONNAME,PARTNUMBER,BARCODE,EXPRESULT,STATUS FROM #Result
				SELECT LINECODE,--Case MACHINENAME When 'PERFORMANCE' THEN 'PRFC SERVO' ELSE MACHINENAME END MACHINENAME,
				MACHINENAME,
				OPERATIONNAME,
				--Case OPERATIONNAME When 'PERFORMANCE' THEN 'PRFC SERVO' ELSE OPERATIONNAME END OPERATIONNAME,
				PARTNUMBER,BARCODE,EXPRESULT,STATUS,[Description] FROM #Result
					
				SET @RETURNVALUE='SUCCESS'
				SET @RETURNINT=0
				RETURN
			END
		ELSE IF(@CONDITION = 'GET_POKAYOKE_AVAIL')
		BEGIN
				IF EXISTS (
				SELECT 1 FROM ASSY_POKAYOKE (NOLOCK) P
				JOIN 
					(
						SELECT DISTINCT PROFITCENTERCODE, PARTNO FROM ROUTINGCONFIGPARTWISE (NOLOCK)
						WHERE PART_FIXTUREGROUPTYPE = DBO.ASSY_FN_GET_RUNNINGPART_FIXTURECODE(@PROFITCENTERCODE,@LINECODE)
					) R
				ON R.PROFITCENTERCODE = P.PROFITCENTERCODE AND R.PARTNO = P.PARTNUMBER)
				BEGIN
					SELECT 'Y'
				END
				ELSE
				BEGIN
					SELECT 'N'
				END
				SET @RETURNVALUE = 'SUCCESS'
				SET @RETURNINT = 1
		END
		ELSE IF(@CONDITION='GET_OPERATION_NAME')
		BEGIN	
			SELECT OM.OPERATIONCODE,OM.OPERATIONNAME FROM OPERATIONMST OM WITH(NOLOCK)
			INNER JOIN
				ROUTINGCONFIGLINEWISE(NOLOCK) RCPW ON RCPW.OPERATIONCODE=OM.OPERATIONCODE
			WHERE
			RCPW.LINECODE=@LINECODE
			AND
			ISNULL(RCPW.POKA_YOKE_ALLOWED,0)=1 AND ISNULL(RCPW .TRACEABILITY,0) =1
			ORDER BY RCPW.OPERATIONSEQNO ASC

				SET @RETURNVALUE='SUCCESS'
				SET @RETURNINT=0
		END
		ELSE IF(@CONDITION = 'GET_POKAYOKE_STATUS_FROM_LINE_MST')
		BEGIN	
			SELECT @RETURNVALUE = ISNULL(ISPOKAYOKEMANDATORY,0) FROM LINEMST (NOLOCK) WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE

				IF (@RETURNVALUE = '1')
				BEGIN
					SET @RETURNVALUE = 'Y'
					SET @RETURNINT = 1
				END
				ELSE
				BEGIN
					SET @RETURNVALUE = 'N'
					SET @RETURNINT = 1
				END
		END
		ELSE IF(@CONDITION = 'GET_POKAYOKE_GROUP')
		BEGIN
			SELECT @RETURNVALUE = dbo.Assy_FN_Get_Runningpart_FixtureCode(@PROFITCENTERCODE,@LINECODE)
			SET @RETURNINT = 1
		END
		ELSE IF(@CONDITION = 'GET_PART_LIST_POKAYOKE_GROUP')
		BEGIN
			SELECT Distinct PartNo, ISNULL(Part_FixtureGroupType,'') Part_FixtureGroupType FROM RoutingConfigPartWise WITH (NOLOCK)
				WHERE ProfitCenterCode = @PROFITCENTERCODE

			SELECT Distinct PartNo, ISNULL(Part_FixtureGroupType,'') Part_FixtureGroupType FROM RoutingConfigPartWise WITH (NOLOCK)
				WHERE ProfitCenterCode = @PROFITCENTERCODE AND ISNULL(Part_FixtureGroupType,'') != ''

			SET @RETURNINT = 1
		END
		ELSE IF(@CONDITION = 'GET_ALL_PART_LIST_DEFINED_IN_POKAYOKE_GROUP')
		BEGIN
			SELECT Distinct PartNo, ISNULL(Part_FixtureGroupType,'') PokaYokeGroup FROM RoutingConfigPartWise WITH (NOLOCK)
				WHERE ProfitCenterCode = @PROFITCENTERCODE AND Part_FixtureGroupType = @Part_FixtureGroupType
			SET @RETURNINT = 1
		END
		ELSE IF(@CONDITION = 'UPDATE_POKAYOKE_GROUP')
		BEGIN
			Declare @GroupCode VARCHAR(15) = '', @MaxGroupValue INT = 0, @Part_GroupType VARCHAR(20) = '', @GroupCodeLen INT = 0
			
			IF @NewPokaYokeGroup = 1
			BEGIN
				SELECT @GroupCode = RTRIM(ISNULL(PARAMETER_VALUE,'')) FROM PARAMETER_MST WITH (NOLOCK)
					WHERE wh_code = @ProfitCenterCode AND PARAMETER_C = 'AssLine' AND PARAMETER_C1 = 'PartFixtureGroupType' AND PARAMETER_C2 = @SelectionType 
				
				SET @GroupCodeLen = LEN(@GroupCode)

				SELECT @MaxGroupValue = MAX(RIGHT(Part_FixtureGroupType,5)) FROM RoutingConfigPartWise WITH (NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode
						AND LEFT(Part_FixtureGroupType,@GroupCodeLen) = @GroupCode AND ISNULL(Part_FixtureGroupType,'') != ''
				
				SET @MaxGroupValue = @MaxGroupValue + 1

				SET @Part_GroupType = RIGHT('00000' + CONVERT(VARCHAR,@MaxGroupValue),5)
				
				IF ISNULL(@Part_GroupType,'') = ''
					SET @Part_GroupType = '00001'
					
				SET @Part_GroupType =  @GroupCode + @Part_GroupType
			END
			
			UPDATE RoutingConfigPartWise
				SET Part_FixtureGroupType = Case @NewPokaYokeGroup WHEN 1 THEN @Part_GroupType WHEN 0 THEN @Part_FixtureGroupType END,
					last_upd_by = @UserID, last_upd_stamp = GETDATE()						
				WHERE ProfitCenterCode = @PROFITCENTERCODE AND PartNo = @PARTNUMBER AND ISNULL(Part_FixtureGroupType,'') = ''

			SET @RETURNINT = 1
		END
	END TRY
	BEGIN CATCH
		SET @RETURNVALUE =	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
			CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
			CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
			CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
			CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
			CAST(ERROR_MESSAGE() AS VARCHAR(1500))
			RAISERROR (@RETURNVALUE,16,1)						
		   SET @RETURNINT = 2
	END CATCH
END

GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_PokaYoke_Last_Tested_Part]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

create proc [dbo].[Assy_Proc_PokaYoke_Last_Tested_Part]
(   @CONDITION VARCHAR(60),
	@ProfitCenterCode varchar(20)=NULL ,
	@LineCode varchar(20)=NULL ,
	@MachineCode varchar(20)=NULL ,
	@OperationCode varchar(20)=NULL
	
)
as
begin
		--Author :<Ravishankar Mishra>
		--Created date:<20/02/2016>
		--exec Assy_Proc_PokaYoke_Last_Tested_Part @CONDITION='INSERT',@ProfitCenterCode='0021',@LineCode='M01',@MachineCode='MCMS',@OperationCode='OCMSLH'
		--exec Assy_Proc_PokaYoke_Last_Tested_Part @CONDITION='delete',@ProfitCenterCode='0021',@LineCode='M01'
		--select * from Assy_PokaYoke_Last_Tested_Part

		set nocount on
		declare @Partno varchar(60),@DateCode char(4)
		if @CONDITION='DELETE'
		begin
			  delete from Assy_PokaYoke_Last_Tested_Part where ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode
		end

		else if @CONDITION='INSERT'
		begin
			
					select top 1 @Partno=Assy_PartNo, @DateCode=Datecode from assy_runningPart with(nolock)
					where ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode order by CreatedDate desc

					if isnull(@Partno,'')=''
						return

					if not exists
					(
							select 1  from Assy_PokaYoke_Last_Tested_Part with(nolock) where ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode
							and MachineCode=@MachineCode  and OperationCode=@OperationCode
					)
					begin

								insert into Assy_PokaYoke_Last_Tested_Part
								(
									ProfitCenterCode,LineCode,MachineCode,OperationCode,PartNo,Datecode,isPokaYokeCompleted,timestamp
								)
								select @ProfitCenterCode,@LineCode,@MachineCode,@OperationCode,@PartNo,@Datecode,1,getdate()

					end
					else
						begin
									update Assy_PokaYoke_Last_Tested_Part set isPokaYokeCompleted=1 ,timestamp=getdate()
									where ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode and MachineCode=@MachineCode  and OperationCode=@OperationCode
									and Datecode=@Datecode and PartNo=@PartNo
						end
		end
end


