/****** Object:  StoredProcedure [dbo].[Assy_Proc_PORelatedMasterValidation_Email]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[Assy_Proc_PORelatedMasterValidation_Email]
(
	@CONDITION VARCHAR(50),
	@ProfitCenterCode varchar(10)='0021',
	@ReturnValue VARCHAR (2000)=NULL OUT,
	@ReturnInt INT=NULL OUT
)
as
begin
		--Author:<RUBESH KANNAN>
		--Created date:<19/11/2015>
		--exec [Assy_Proc_PORelatedMasterValidation_Email] @CONDITION='Assy_PO_PORelatedMasterValidation_Email',@ProfitCenterCode='0021'
		
		SET NOCOUNT ON
		declare @WEB_TO_EMAILID nvarchar(max), @WEB_CC_EMAILID nvarchar(1000),@MESSAGE NVARCHAR(max),@SUBJECT NVARCHAR(1000),@MessageHeading varchar(500)

		if  @CONDITION='Assy_PO_RelatedMasterValidation_Email'
		BEGIN

		select @WEB_TO_EMAILID=dbo.ASSY_FN_GET_PARAMETER_VALUE('assline','Assy_PO_RelatedMasterValidation_Email','MAIL_ALERT_LIST_TO',@ProfitCenterCode)
				--select @WEB_TO_EMAILID='manoj.kumar@mind-infotech.com;ravi.mishra@mind-infotech.com'
				select @WEB_CC_EMAILID=dbo.ASSY_FN_GET_PARAMETER_VALUE('assline','Assy_PO_RelatedMasterValidation_Email','TS_MAIL_ALERT_LIST_CC',@ProfitCenterCode)
				--select @WEB_TO_EMAILID,@WEB_CC_EMAILID
				--SET @WEB_TO_EMAILID=@WEB_CC_EMAILID
				set @MESSAGE =''								
				IF OBJECT_ID('tempdb..#tmpassypodata') IS NOT NULL
				BEGIN
				DROP TABLE #tmpassypodata
				END


				Select Distinct L.LineCode,L.LineName,P.WorkCenterCode,RTRIM(P.PartNo) PartNo into #tmpassypodata from Assy_ProductionOrderMst P
				JOIN LineMst L
				ON L.WorkCenterCode = P.WorkCenterCode AND P.ProfitCenterCode = '0021' AND P.Status <> 100 AND convert(date,P.OrderDate) =convert(date,getdate())
				Where P.PartNo NOT IN (
					Select Distinct PartNo FROM RoutingConfigPartWise WHERE LineCode = L.LineCode) 
					AND (LEFT(L.LineCode,1) IN ('M','P'))
				Order By 1,2,3

				set @MESSAGE =''									
				set @SUBJECT ='PartNo''s not available in Our Master'	
				set @MessageHeading='Line Code'+space(2)+'|Line Name'+space(4)+'|WorkCenterCode|Part No.'+char(13)
				set @MESSAGE=@MessageHeading
				select @MESSAGE=isnull(@MESSAGE,'')+pod.LineCode +space(8)+'|' +pod.LineName+space(5)+'|'+pod.WorkCenterCode+space(8)+'|'
								+space(2)+pod.PartNo+ char(13)
								from #tmpassypodata pod
								inner join PRODUCT_MASTER(Nolock) pm on pm.SEWS_PART_NO=pod.PartNo where pm.warehouse_cd='0021'

								Print @MESSAGE
			END

			End
GO
/****** Object:  StoredProcedure [dbo].[Assy_PROC_POStatus]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[Assy_PROC_POStatus] 
(
@Condition VARCHAR(50) = NULL,
@ProfitCenterCode varchar(20) = NULL,
@LineCode varchar(20) = NULL,
@PartNo varchar(20) = NULL,
@OrderNo varchar(20) = NULL,
@WorkCenterCode varchar(20) = NULL,
@ReturnValue VARCHAR (2000) = NULL OUT,
@ReturnInt INT = NULL OUT
)
AS
BEGIN

-- Author:		<Rashid Siddiqui>
-- Create date: < 18 Feb 2016>

-- To Rembember
-- Nothing = 0
-- Success = 1
-- Error = 2
-- AlreadyExists = 3
-- NotExists = 4

	BEGIN TRY
		IF @CONDITION = 'GET_PO_STATUS'
		BEGIN
			SELECT	LTRIM(RTRIM(ProfitCenterCode)) [Profit Center Code], LTRIM(RTRIM(WorkCenterCode)) [Work Center Code],
					LTRIM(RTRIM(OrderNo)) [Order No], OrderDate [Order Date], 
					LTRIM(RTRIM(PartNo)) [Part No], qty [Order Qty], CONVERT(VARCHAR,ENT_STAMP,109) [Created Date Time],
					CONVERT(VARCHAR,LAST_UPD_STAMP,109) [Updated Date Time]
						FROM Assy_ProductionOrderMst (NOLOCK)
							WHERE ProfitCenterCode = @ProfitCenterCode
								AND (PartNo Like '%' + @PartNo +'%' AND OrderNo Like '%' + @OrderNo +'%' AND WorkCenterCode Like '%' + @WorkCenterCode +'%')
								AND ISNULL(Status ,'0') != '100'
									Order By 4 Desc

			SET @RETURNVALUE = 'SUCCESS'
			RETURN
		END
	END TRY
	BEGIN CATCH
		SET @ReturnValue =	CAST(ERROR_NUMBER() as varchar(5)) + '|' + 
		CAST(ERROR_SEVERITY()as varchar(5)) + '|' + 
		CAST(ERROR_STATE() as varchar(5)) + '|' + 
		CAST(ERROR_PROCEDURE() as varchar(200)) + '|' + 
		CAST(ERROR_LINE() as varchar(5)) + '|' + 
		CAST(ERROR_MESSAGE() as varchar(1500))								
		SET @ReturnInt = 2
		RAISERROR(@ReturnValue,16,1)
		--Rollback tran
	END CATCH
END

