GO
CREATE proc [dbo].[Assy_Proc_PreviousPending_Parts]
(
	@CONDITION VARCHAR(60),
    @UDT as Assy_Type_PreviousPending_Parts readonly,
	@ProfitCenterCode nvarchar(4)=Null,
	@Linecode varchar(10)=Null,
	@RETURNVALUE VARCHAR (2000) = NULL OUT,
	@RETURNINT INT=NULL OUT,
	@IsFinalQCOKPart bit=0,
	@Barcode varchar(100)=NUll,
	@RFID varchar(60)=NULL,
	@PartNo varchar(60)=null,
	@DateCode varchar(10)=null,
	@CaliperSerNo varchar(5)=null,
	@CouOperationCode varchar(10)=null,
	@CouMachinecode varchar(10)=null,
	@FVMachinecode varchar(10)=null,
	@Machinecode varchar(10)=null,
	@IsRFIDUseAtPKGStn bit=0,
	@P_ShowPassedPartFromFV bit=0
)
as
begin
	--<Author>: Ravishankar Mishra
	----<Created Date>:10-08-16
	--Modified Date:<15-11-16>
		
	--<Modified By>: Ravishankar Mishra
	--Modified Date:<08-12-16>
	--Description:Move rejected part from pending part table to tally chart history table
	
	--<Modified By>: Ravishankar Mishra
	--Modified Date:<22-08-17>
	--Description:Added new block-Get_Stations and modified blocks(select) for part rejection

	--exec Assy_Proc_PreviousPending_Parts @CONDITION='select',@ProfitCenterCode='0088',@Linecode='J04',@RFID='1931600532Gd00000002J04'	
	--exec Assy_Proc_PreviousPending_Parts @CONDITION='select',@ProfitCenterCode='0088',@Linecode='J04',@PartNo='19316005',@DateCode='27Qd',@CaliperSerNo='0268'
	--,@CouMachinecode='MCCP'
	--exec Assy_Proc_PreviousPending_Parts @CONDITION='select',@ProfitCenterCode='0088',@Linecode='J04',@PartNo='19316005',@DateCode='33md',@CouMachinecode='MCCP'
	--exec Assy_Proc_PreviousPending_Parts @CONDITION='select',@ProfitCenterCode='0088',@Linecode='J04',@FVMachinecode='MCFV',@Barcode='00193160050016180000102017'	
	--exec Assy_Proc_PreviousPending_Parts @CONDITION='Get_Stations',@ProfitCenterCode='0088',@Linecode='J04'	
	--declare @udt as Assy_Type_PreviousPending_Parts
	--insert into @udt
	--select '0088','j04','MCFV','','1931600533Md00000004J04','C001','',1
	--exec Assy_Proc_PreviousPending_Parts @CONDITION='Save_Central_Server',@ProfitCenterCode='0088',@Linecode='J04,@ISFINALQCOKPART=1	,@UDT=@udt;

	--declare @udt as Assy_Type_PreviousPending_Parts
	--insert into @udt
	--select '0088','j04','MCFV','','1931600533Md00000004J04','C001','',1
	--exec Assy_Proc_PreviousPending_Parts @CONDITION='Reject',@ProfitCenterCode='0088',@Linecode='J04',@ISFINALQCOKPART=1,@UDT=@udt

	--declare @RETURNVALUE varchar(20)
	--exec Assy_Proc_PreviousPending_Parts @CONDITION='Check_Rejection',@ProfitCenterCode='0088',@Linecode='J04',@IsRFIDUseAtPKGStn=1
	--,@RFID='1931600532Gd00000002J04',@barcode='',@RETURNVALUE=@RETURNVALUE out	
	--select @RETURNVALUE
			
			 if OBJECT_ID('TEMPDB..#TV') is not null
			 drop table #TV
			
			 create Table #TV
						 (
							ProfitCenterCode varchar(10) ,
							LineCode varchar(10) ,
							Datecode char(4) ,
							MachineCode varchar(10) ,					
							Barcode varchar(100) ,
							Result varchar(10) ,
							NotProcessedStatus varchar(10) ,
							Reason varchar(250) ,
							Remarks  varchar(250) ,
							Assy_Auth bit ,
							UserID varchar(20) ,
							Timestamp datetime ,
							PartNo varchar(60) 
						 )


			SET NOCOUNT ON
			if @CONDITION='Reject'
			BEGIN
					BEGIN TRY
							BEGIN TRAN
							--IF ISNULL(@ISFINALQCOKPART,0)=0
							--BEGIN
																
							insert into #TV (
							ProfitCenterCode,LineCode,Datecode,MachineCode,Barcode,Result,NotProcessedStatus,
							Reason,Remarks,Assy_Auth,UserID,Timestamp,PartNo)						              
							select A.ProfitCenterCode,A.LineCode,A.datecode,A.MachineCode,A.Barcode,
							A.Result,'Rework',A.REASON_CD,A.Remarks,1 as Auth,A.UserID,getdate(),
							A.partno from @UDT A 
							
							insert into Assy_TallyChartStatusData_History(
							ProfitCenterCode,LineCode,Datecode,MachineCode,Barcode,Result,NotProcessedStatus,Reason,
							Remarks,Assy_Auth,UserID,Timestamp,PartNo,EntStamp)
							select  ProfitCenterCode, LineCode, Datecode, MachineCode, Barcode, Result, NotProcessedStatus, Reason,
							Remarks + ' Using PPR' , Assy_Auth, UserID, Timestamp, PartNo,getdate() from  #TV		
							
							if OBJECT_ID('TEMPDB..#TV') is not null
							drop table #TV											
									
									--Copy data into Permanent tables
									INSERT INTO ASSY_LINEASSYSTATUS
									(
										PROFITCENTERCODE,
										LINECODE,
										MACHINECODE,
										OPERATIONCODE,
										STATIONCODE,
										BARCODE,
										STATUS,
										FAILCOUNT,
										DATECODE,
										PARTNO,
										SCANTIMESTAMP,
										RESULTTIMESTAMP,
										ACTIVE,
										USERID,
										ISTALLYCHARTAPPROVED,
										IsReworkPart,
										IsPendingPart,
										ProductionOrderNo,
										PROD_LOT_NO
									)
									SELECT distinct
									A.PROFITCENTERCODE,
									A.LINECODE,
									A.MACHINECODE,
									A.OPERATIONCODE,
									STATIONCODE,
									A.BARCODE,
									STATUS,
									FAILCOUNT,
									A.DATECODE,
									A.PARTNO,
									SCANTIMESTAMP,
									RESULTTIMESTAMP,
									ACTIVE,
									A.USERID,
									1,
									IsReworkPart,
									IsPendingPart,
									ProductionOrderNo,
									PROD_LOT_NO
									FROM
									ASSY_LINEASSYSTATUS_RUNNING(NOLOCK) A 
									join @UDT UT 
									 ON A.ProfitCenterCode = UT.ProfitCenterCode
										and A.LineCode = UT.LineCode
										and A.Barcode = UT.Barcode  
									WHERE A.LINECODE=@LINECODE 
									AND A.PROFITCENTERCODE =@PROFITCENTERCODE	
									AND A.DATECODE !='PKYK' --and isnull(UT.REASON_CD,'')<>'' and isnull(ut.Is_Rejected,0)=1
											
								    DELETE A from ASSY_LINEASSYSTATUS_RUNNING  A 
									join @UDT UT 
									 ON A.ProfitCenterCode = UT.ProfitCenterCode
										and A.LineCode = UT.LineCode
										and A.Barcode = UT.Barcode  
									WHERE A.LINECODE=@LINECODE 
									AND A.PROFITCENTERCODE =@PROFITCENTERCODE	
									AND A.DATECODE !='PKYK' --and isnull(UT.REASON_CD,'')<>''  and isnull(ut.Is_Rejected,0)=1
									
								INSERT INTO ASSY_LINEASSYPARAMDATA
								(
									[PROFITCENTERCODE]
									,[LINECODE]
									,[MACHINECODE]
									,[OPERATIONCODE]
									,[STATIONCODE]
									,[BARCODE]
									,[RESULT]
									,[DATECODE]
									,UserID
									,Timestamp
									,PartNo
									,UID
									,ScanTimestamp
									,CaliperDatecode
									,CaliperSrNo
								)
								SELECT
								distinct A.[PROFITCENTERCODE]
								,A.[LINECODE]
								,A.[MACHINECODE]
								,A.[OPERATIONCODE]
								,[STATIONCODE]
								,A.[BARCODE]
								,A.[RESULT]
								,A.[DATECODE]
								,A.UserID
								,Timestamp
								,A.PartNo
								,UID								
								,ScanTimestamp
								,CaliperDatecode
								,CaliperSrNo								
								FROM ASSY_LINEASSYPARAMDATA_RUNNING(NOLOCK) A 
								join @UDT UT 
									ON A.ProfitCenterCode = UT.ProfitCenterCode
									and A.LineCode = UT.LineCode
									and A.Barcode = UT.Barcode  
								WHERE A.LINECODE=@LINECODE 
								AND A.PROFITCENTERCODE =@PROFITCENTERCODE	
								--and isnull(UT.REASON_CD,'')<>''  and isnull(ut.Is_Rejected,0)=1							
														
								insert into ASSY_LINEASSYPARAMDATA_Dtl(UID,TagId,Value)
