								insert into #tmp(SerialNo,MachineName,MachineCode,OperationCode,Datecode,Barcode,
								Result,REASON_CD,Remarks,ProfitCenterCode,LineCode,PartNo,IsTallyChartApproved,OperationSeqNo,FinalQCOKPart)

								 select (ROW_NUMBER()  over (order by rl.OperationSeqNo,la.Barcode ))SerialNo,m.MachineName,la.MachineCode,la.OperationCode,la.Datecode,la.Barcode,
							(case when isnull(La.status,'')='PS' then 'PASS' when isnull(La.status,'')='FL' then 'FAIL' else 'WIP' end) as Result
							, '' as REASON_CD, '' as Remarks ,La.ProfitCenterCode,La.LineCode,LA.PartNo,IsTallyChartApproved,rl.OperationSeqNo ,0
									from dbo.Assy_LineAssyStatus LA with(nolock)						
								Join dbo.MachineMst M with(nolock)
										on m.ProfitCenterCode =la.ProfitCenterCode and m.MachineCode =la.MachineCode 															
								join dbo.RoutingConfigLineWise rl with(nolock) 
									on rl.ProfitCenterCode=La.ProfitCenterCode and rl.LineCode =la.linecode and rl.MachineCode=la.MachineCode
									and isnull(rl.Traceability,0)=1 
