				begin							
						;with CTETbl(SerialNo,MachineName,MachineCode,OperationCode,Datecode,Barcode,
								Result,REASON_CD,Remarks,ProfitCenterCode,LineCode,PartNo,IsTallyChartApproved)
						AS					
						(
							select (ROW_NUMBER()  over (order by rl.OperationSeqNo,la.Barcode ))SerialNo,m.MachineName,la.MachineCode,la.OperationCode,la.Datecode,la.Barcode,
							(case when isnull(La.status,'')='PS' then 'PASS' when isnull(La.status,'')='FL' then 'FAIL' else 'WIP' end) as Result
							, '' as REASON_CD, '' as Remarks,La.ProfitCenterCode,La.LineCode,LA.PartNo,IsTallyChartApproved 
