								where ProfitCenterCode=@ProfitCenterCode and linecode=@Linecode and barcode=@Barcode)
						)
						
						select SerialNo,MachineName,C.MachineCode,OperationCode,Datecode,Barcode,Result,isnull(C.REASON_CD,'')REASON_CD,isnull(r.REASON_DESC,'')REASON_DESC
						,isnull(Remarks,'')Remarks,ProfitCenterCode,LineCode,PartNo,1 as FinalQCOKPart,IsTallyChartApproved  from CTETbl C
						left outer join dbo.reason_master R with(nolock) 
							on r.warehouse_cd= C.ProfitCenterCode and r.REASON_CD =c.REASON_CD 
