					--exec Assy_Proc_Get_Pending_Parts @CONDITION='PREVIOUS',@ProfitCenterCode=@ProfitCenterCode,@Linecode=@Linecode;
					
					if object_id('tempdb..#tmpAll') is not null
				        drop table #tmpAll

						
						select (ROW_NUMBER()  over (order by la.Barcode,rl.OperationSeqNo ))SerialNo,m.MachineName,la.MachineCode,la.OperationCode,la.Datecode,la.Barcode,
						(case when isnull(La.status,'')='PS' then 'PASS' when isnull(La.status,'')='FL' then 'FAIL' else 'WIP' end) as Result
						, '' as REASON_CD, '' as Remarks ,La.ProfitCenterCode,La.LineCode,LA.PartNo,IsTallyChartApproved,rl.OperationSeqNo  into #tmpAll
						 from dbo.Assy_LineAssyStatus_Running LA with(nolock)  						
						Join dbo.MachineMst M with(nolock)
							 on m.ProfitCenterCode =la.ProfitCenterCode and m.MachineCode =la.MachineCode 													
						join dbo.RoutingConfigLineWise rl with(nolock) 
							on rl.ProfitCenterCode=La.ProfitCenterCode and rl.LineCode =la.linecode and rl.MachineCode=la.MachineCode
							and isnull(rl.Traceability,0)=1 
							and isnull(rl.OperationRequired,0)=1 
