					begin 
							select (ROW_NUMBER() OVER (order by c.SerialNo)) SerialNo,MachineName,MachineCode,OperationCode,Datecode,Barcode,
							 Result, '' as REASON_CD, isnull(r.REASON_DESC,'')REASON_DESC,'' as Remarks ,ProfitCenterCode,LineCode,PartNo,0 as FinalQCOKPart,IsTallyChartApproved  from #tmpAll C
							left outer join dbo.reason_master R with(nolock) 
								on r.warehouse_cd= C.ProfitCenterCode and r.REASON_CD =c.REASON_CD 
								 and r.STS_CD =0 	where machinecode=@MachineCode and PartNo=@PartNo
								 order by Barcode, OperationSeqNo			
					end
					else if isnull (@Machinecode,'')<>''
					begin 
							select (ROW_NUMBER() OVER (order by c.SerialNo)) SerialNo,MachineName,MachineCode,OperationCode,Datecode,Barcode,
							Result,'' as REASON_CD,isnull(r.REASON_DESC,'')REASON_DESC, '' as Remarks ,ProfitCenterCode,LineCode,PartNo,0 as FinalQCOKPart,IsTallyChartApproved  from #tmpAll C
							left outer join dbo.reason_master R with(nolock) 
								on r.warehouse_cd= C.ProfitCenterCode and r.REASON_CD =c.REASON_CD 
								 and r.STS_CD =0 	where machinecode=@MachineCode	
								 order by Barcode, OperationSeqNo
					end
					else if  isnull(@PartNo,'')<>''
					begin 
							select (ROW_NUMBER() OVER (order by c.SerialNo)) SerialNo,MachineName,MachineCode,OperationCode,Datecode,Barcode,
							Result, '' as REASON_CD,isnull(r.REASON_DESC,'')REASON_DESC, '' as Remarks ,ProfitCenterCode,LineCode,PartNo,0 as FinalQCOKPart,IsTallyChartApproved  from #tmpAll C
							left outer join dbo.reason_master R with(nolock) 
								on r.warehouse_cd= C.ProfitCenterCode and r.REASON_CD =c.REASON_CD 
								 and r.STS_CD =0 where  PartNo=@PartNo
								 order by Barcode, OperationSeqNo
								   			
					end
					else
					   begin
					         	select (ROW_NUMBER() OVER (order by c.SerialNo)) SerialNo,MachineName,MachineCode,OperationCode,Datecode,Barcode,
								Result, '' as REASON_CD, isnull(r.REASON_DESC,'')REASON_DESC,'' as Remarks ,ProfitCenterCode,LineCode,PartNo,0 as FinalQCOKPart,IsTallyChartApproved  from #tmpAll C
							     left outer join dbo.reason_master R with(nolock) 
								on r.warehouse_cd= C.ProfitCenterCode and r.REASON_CD =c.REASON_CD 
								 and r.STS_CD =0 	   
								 order by Barcode, OperationSeqNo
					   end
					if object_id('tempdb..#tmpAll') is not null
