							select  ProfitCenterCode, LineCode, Datecode, MachineCode, Barcode, Result, NotProcessedStatus, Reason,
							Remarks + ' Using PPR' , Assy_Auth, UserID, Timestamp, PartNo,getdate() from  #TV				
							
							select distinct barcode into #RFIData from  @UDT
							
							if exists ( select top 1 1 from Assy_FinalViewing_RFID_Barcode_Mapping f 
							inner join #RFIData temp on f.barcode=temp.barcode
							and ProfitCenterCode=@ProfitCenterCode and Linecode=@LineCode)
							begin

									insert into [Assy_FinalViewing_RFID_Barcode_Mapping_RWK_DEL_LOG](
									ProfitCenterCode,LineCode,MachineCode,OperationCode,RFID,Barcode,[Status],PartNo,
									Datecode,PrintedTimestamp,CaliperSerNo,CaliperDatecode,DelRWKDT
									)
									select  A.ProfitCenterCode,A.LineCode,A.MachineCode,A.OperationCode,A.RFID,A.Barcode,A.[Status],A.PartNo,
									A.Datecode,A.PrintedTimestamp,A.CaliperSerNo,A.CaliperDatecode,getdate() 
									from Assy_FinalViewing_RFID_Barcode_Mapping(nolock) A inner join #RFIData temp
									on A.barcode=temp.barcode
									and ProfitCenterCode=@ProfitCenterCode and Linecode=@LineCode


									delete f from Assy_FinalViewing_RFID_Barcode_Mapping(nolock) f inner join #RFIData temp
									on f.barcode=temp.barcode
									and ProfitCenterCode=@ProfitCenterCode and Linecode=@LineCode

							end
				
					
					--print @EXECQUERY
					if OBJECT_ID('TEMPDB..#TV') is not null
						drop table #TV	
					if OBJECT_ID('TEMPDB..#RFIData') is not null
						drop table #RFIData		
						
				     set @RETURNINT=1
					 
					  COMMIT TRAN
					  RETURN
					END TRY
					BEGIN CATCH
							SET @RETURNVALUE =	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
							CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
							CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
							CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
							CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
							CAST(ERROR_MESSAGE() AS VARCHAR(1500))
								ROLLBACK TRAN								
							SET @RETURNINT = 2
							RAISERROR(@RETURNVALUE,16,1)	
					END CATCH


			end
			--Check part is packed or not before marking as rejection
			else if @condition='Check_Rejection'
			begin
			        declare @PartBarcode varchar(50)
					if isnull(@IsRFIDUseAtPKGStn,0)=1
					begin
					      set @PartBarcode=@RFID 
						  --print '1'
					end
					else
					  begin
							   if isnull(@Barcode,'')='' 
							   begin
									 select @PartBarcode=barcode from dbo.Assy_FinalViewing_RFID_Barcode_Mapping with(nolock) where ProfitCenterCode=@ProfitCenterCode 
									 and Linecode=@Linecode  and RFID=@RFID	
									  --print '2'
							   end						
							   else
									begin
									   set @PartBarcode=@Barcode
									    --print '3'
									end
					  end					
				    
					if exists
					(
						select 1 from dbo.SkidBarcodeDetail with(nolock) where WH_CODE=@ProfitCenterCode 
						and Line_no=@Linecode and PartBarcode=@PartBarcode
					)
					begin
					        set @RETURNVALUE='Y'
					end
					else
					begin
							set @RETURNVALUE='N'
					end
			         set @RETURNINT=1
					 return
			end	
			else if @condition='RFID_COM_PORT'
			begin
				
				select top 1 @RETURNVALUE=PortNo from Assy_LineWiseDeviceConfig(nolock)
				where ProfitCenterCode=@ProfitCenterCode
				and LineCode=@Linecode and OperationCode='PPR'
				and HardwareName='RFIDPort' and PortType='SERIALPORT'
				set @RETURNINT =1
			end						
end


GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_PrintLabels]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create Proc [dbo].[Assy_Proc_PrintLabels]
(
	@Condition VARCHAR(100) = NULL,
	@ProfitCenterCode VARCHAR(10) = NULL,
	@LineCode VARCHAR(10) = NULL,
	@ReturnValue VARCHAR(MAX) = NULL OUT,
	@ReturnInt INT = NULL OUT
)
AS
BEGIN
	/*
	 Author:		<Rashid Siddiqui>
	 Create Date:	<02 August 2017>
	 Description:	<Print Machine Code and Line Code>
	*/
	--exec Assy_Proc_PrintLabels 'Machine','0088','J05'
	BEGIN TRY
		IF @Condition = 'Machine'
		BEGIN 
			;WITH CTS (ProfitCenterCode, LineCode, SubMachineCode,MachineCode, MachineName)
			AS (
			SELECT M.ProfitCenterCode, R.LineCode, R.SubMachineCode,r.MachineCode, M.MachineName
				FROM MachineMst M (NOLOCK)
					JOIN RoutingConfigLineWiseForSubStation R (NOLOCK)
						ON M.ProfitCenterCode = R.ProfitCenterCode AND M.MachineCode = R.SubMachineCode
					join  RoutingConfigLineWise RL (nolock)
						ON RL.ProfitCenterCode = R.ProfitCenterCode and RL.linecode=r.linecode AND RL.MachineCode = R.MachineCode
						and isnull(rl.IsPokaYokeForSubStation,0)=1
			)
			SELECT SubMachineCode, MachineName FROM CTS WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode Order By MachineCode
		END
		ELSE IF @Condition = 'Line'
		BEGIN 
			SELECT L.LineCode, L.LineName
				FROM LineMst L (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode Order By 2
		END
	END TRY
	
	BEGIN CATCH
		SET @ReturnValue =	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' +
							CAST(ERROR_SEVERITY() AS VARCHAR(5)) + '|' +
							CAST(ERROR_STATE() AS VARCHAR(5)) + '|' +
							CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' +
							CAST(ERROR_LINE() AS VARCHAR(5)) + '|' +
							CAST(ERROR_MESSAGE() AS VARCHAR(1500))
		SET @ReturnInt = 2
		RAISERROR (@ReturnValue, 16, 1)
	END CATCH
END


