---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

CREATE PROC [dbo].[Assy_Proc_Production_Confirmation]
( 
	@Condition VARCHAR(250) = NULL,
	@ProfitCenterCode VARCHAR(20) = NULL, 
	@LineCode VARCHAR(20) = NULL, 
	@LineType VARCHAR(20) = NULL,
	@OperationCode VARCHAR(20) = NULL,
	@MachineCode VARCHAR(20) = NULL, 
	@Status VARCHAR(10) = NULL, 
	@Bin_Id VARCHAR(20) = NULL, 
	@StationCode VARCHAR(20) = '1', 
	@IsConfirmationManual BIT = 0, 
	@DateCode VARCHAR(4) = NULL, 
	@PartNumber VARCHAR(20) = NULL, 
	@Barcode VARCHAR(100) = NULL, 
	@TransId NUMERIC(9,0) = NULL, 
	@Prefix CHAR(2) = NULL, 
	@Suffix CHAR(2) = NULL, 
	@ReturnValue VARCHAR (2000) = NULL OUT, 
	@ReturnInt INT = NULL OUT, 
	@UserId VARCHAR(50) = NULL, 
	@Kanban_Param VARCHAR(20) = NULL, 
	@Dacs_TR_ID INT = NULL, 
	@PassQty INT = 0, 
	@Prod_Version VARCHAR(10) = NULL, 
	@FailQty INT = 0, 
	@Confirmation_Qty INT = NULL, 
	@Passed_Qty INT = NULL, 
	@Enable_Prod_Conf INT = NULL, 
	@Part_As_Param VARCHAR(20) = NULL, 
	@Qty INT = 0 ,
	@P_PartNumber VARCHAR(30) = NULL, -- Added By Sachin 2020May05
	@P_Allow2Parts bit = 0, -- Added By Sachin 2020May05
	@EKanban_Id VARCHAR(40) = NULL -- Added By Sachin 2020June04
) 
AS 
BEGIN 
	-- Author:   
	-- Create Date:		< 13 May 2015 >
	-- Description:
	-- Modified Date:	< 29 Sep 2016 >
	-- Modify By:		< Rashid Siddiqui >
	-- Description:		< Lead Time validation >
	-- Modified ON:		< 04-May-2017 > 
	-- Description:		< Optimize the Query - Remove not necessary Order By, Top , Distinct and Link server update Query >
	-- Modified ON:		< 29-Nov-2017 > 
	-- Description:		< Update Link server Query commented and insert into central server added >
	-- Modified ON:		< 18-Oct-2018 > 
	-- Description:		< Validation of Status Code in Physical Bin Master for all cases >

	-- To Rembember 
	-- Nothing = 0 
	-- Success = 1 
	-- Error = 2 
	-- AlreadyExists = 3 
	-- NotExists = 4 

	/* 
		SELECT * FROM Assy_Stations_Zig_In_Out_Status 
		EXEC [Assy_Proc_FinalViewing] @Condition = 'GET_TAGS', @LineCode = 'M07', @OperationCode = 'OCFV'

		UPDATE Assy_Stations_Zig_In_Out_Status SET StatusInOut = 1 

		Declare @ReturnValue1 VARCHAR(10), @ReturnInt1 INT 
		EXEC [Assy_Proc_Production_Confirmation] @Condition = 'IS_PROD_CONF_REQUIRED_AND_PENDING', @ProfitCenterCode = '0021',
			@LineCode = 'M07', @PartNumber = '12345678', @ReturnValue = @ReturnValue1 OUT, @ReturnInt = @ReturnInt1 OUT 

		EXEC [Assy_Proc_Production_Confirmation] @Condition = 'VALIDATE_KANBAN', @Bin_Id = 'PKBD011000102380', @ProfitCenterCode = '0021',
			@LineCode = 'P2', @UserId = 'admin' 

		SELECT @ReturnValue1,@ReturnInt1 
	*/ 
	
	BEGIN TRY 
		Declare @TR_TYPE_OUT INT 
		, @LeadTime NUMERIC(9,2)
		, @ConfTimeStamp DATETIME 
		, @Timediff NUMERIC(10,2) 
		--Declare @failCountDefined INT = 0 
		--Declare @failCount INT = 0 
		--Declare @TempScannedPartType VARCHAR(15) 
		--Declare @TempRunningPartType VARCHAR(15) 
		--, @FinalViewing_OperationCode VARCHAR(10)
		--Declare @OperationSeqNo INT,@OperationName VARCHAR(50) 
		--Declare @Barcode_Length AS INT 
		, @Is_Confirmation_Required BIT = 0
		, @ExecQuery NVARCHAR(MAX)
		, @LinkServerName VARCHAR(500)
		, @OpCode VARCHAR(50)
		, @Var VARCHAR(1000) = NULL
		, @Kanban_Id VARCHAR(25) = NULL
		--Declare @BOM_VERSION INT = 0;
		, @IsMatFeedRequired INT = 0 
		, @PostLoc Char(4) = ''
		, @Kanban_Category VARCHAR(10) = NULL
		, @RunningPartcategory VARCHAR(10) = NULL
		DECLARE @BinType VARCHAR(10)
   
		--SELECT @FinalViewing_OperationCode = RTRIM(LTRIM( PARAMETER_VALUE)) FROM PARAMETER_MST WITH (NOLOCK)
		--	WHERE PARAMETER_C = 'Assline' AND PARAMETER_C1 = 'FinalViewing' 
		--		AND PARAMETER_C2 = 'QCStation_OperationCode' AND wh_code = @ProfitCenterCode

		SET @QTY = ISNULL(@QTY,0)

		SELECT @LinkServerName = LinkServerName + '.' + DataBaseName FROM Assy_LinkServer_Dtl  WITH (NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode

		SELECT @OpCode = dbo.Assy_FN_Get_FinalViewing_OperationCode_From_LineCode(@ProfitCenterCode,@LineCode)
		
		SELECT * INTO #Assy_RunningPart FROM Assy_RunningPart WITH (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
		SELECT Top 1 @PartNumber = Assy_PartNo, @DateCode = Datecode FROM #Assy_RunningPart

		SELECT * INTO #LineMst FROM LineMst WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
		-----------------------Added by Prerna Gupta for EKanban Process
		Declare @Isekanbanreq int , @ekanbanMode int;
		SELECT @Isekanbanreq=DBO.[FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE](@ProfitCenterCode,'LINE_ATTRB','eKanban_Enable',@LineCode,'')
		if(isnull(@Isekanbanreq,0)=1)
		Begin
						SELECT @ekanbanMode=DBO.[FN_GET_LINE_AND_LINE_TYPE_ATTRIBUTE](@ProfitCenterCode,'LINE_ATTRB','E_KANBAN_MODE',@LineCode,'')	
						if(@ekanbanMode in ('1','3'))
						Begin
								Update #LineMst set IsProdConfRequired='1'
						end
						else
						Begin
								Update #LineMst set IsProdConfRequired='0'
						End
		end
		------------------END
		SELECT Top 1 @IsMatFeedRequired = ISNULL(IsMatFeedRequired,0), @Is_Confirmation_Required = ISNULL(IsProdConfRequired, 0) FROM #LineMst
		declare @Tmp_Assy_Passed_Items_At_FV as table
			(
				ProfitCenterCode varchar(10),
				LineCode varchar(10),
				PartNo varchar(25),
				Transaction_Number varchar(20),
				Old_Transaction_Number  varchar(20),
				Kanban_Id varchar(25)
			)
		IF(ISNULL(@LineCode,'') != '') 
		BEGIN 
			--BEGIN TRAN 
				SELECT @LineType = LTM.LineTypeName FROM #LineMst LM WITH (NOLOCK)
					INNER JOIN LineTypeMst LTM  WITH (NOLOCK)
						ON LM.LineTypeCode  = LTM.LineTypeCode AND LM.ProfitCenterCode = LTM.ProfitCenterCode
							WHERE LM.LineCode = @LineCode AND LM.ProfitCenterCode = @ProfitCenterCode
      
				SET @Var = ( CASE @LineType 
				WHEN 'SERVO'THEN 'PROD_CONF_COUNT_SERVO' 
				WHEN 'TMC'	THEN 'PROD_CONF_COUNT_TMC' 
				WHEN 'STMC' THEN 'PROD_CONF_COUNT_STMC' 
				END) 
     
				--SET @Confirmation_Qty = (SELECT dbo.[assy_fn_get_parameter_value]('AssLine', 'FinalViewing', @Var, @ProfitCenterCode)) 
				Declare @SetKanban VARCHAR(100) = '';

				WITH CTE AS(
				--SELECT Distinct Top 1 Kanban_Id, MIN(Ent_Dt) Dt FROM Assy_Passed_Items_At_FV WITH (NOLOCK) WHERE PartNo = @PartNumber
				SELECT Top 1 Kanban_Id, MIN(Ent_Dt) Dt FROM Assy_Passed_Items_At_FV WITH (NOLOCK) WHERE PartNo = @PartNumber
								AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode AND ISNULL(Is_Posted,0) = 1 AND ISNULL(isConfirmed,'') = 0 
								Group By Kanban_Id
								Order By 2)
				SELECT @SetKanban = Kanban_Id FROM CTE
				--SELECT @SetKanban
				--SET @Kanban_Id = (SELECT Distinct Kanban_Id FROM Assy_Passed_Items_At_FV WITH (NOLOCK) WHERE PartNo = @PartNumber
				--AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode AND ISNULL(Is_Posted,0) = 1 AND ISNULL(isConfirmed,'') = 0 Order By Ent_Dt) 

				IF(ISNULL(@Bin_Id,'') != '') 
				BEGIN
					IF ISNULL(@ProfitCenterCode,'') != ''
					BEGIN
						SELECT Top 1 @Prod_Version = PRODUCTION_VERSION FROM PHYSICAL_BIN_MASTER WITH (NOLOCK) WHERE BIN_ID = @Bin_Id AND STS_CD = 0 AND WH_CODE = @ProfitCenterCode
					END
					ELSE
					BEGIN
						SELECT Top 1 @Prod_Version = PRODUCTION_VERSION FROM PHYSICAL_BIN_MASTER WITH (NOLOCK) WHERE BIN_ID = @Bin_Id AND STS_CD = 0
					END
				END 
			--COMMIT TRAN 
		END 

		SET NOCOUNT ON;

		IF @Condition = 'GET_RUNNING_PART' 
		BEGIN 
			SELECT @PartNumber 
			RETURN 
		END 

		--FROM Local server 
		ELSE IF @Condition = 'GET_PASS_QTY_AND_KANBAN'
		BEGIN 
			if (isnull(@P_PartNumber ,'')='')
			begin
					SELECT @QTY =  COUNT(1), @Kanban_Id = ISNULL(Kanban_Id, '') FROM Assy_Passed_Items_At_FV WITH (NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode 
					AND ISNULL(Is_Posted,0) = 0 Group By Kanban_Id, PartNo
						
					if(isnull(@Qty,0) =0)
					begin
						SELECT top 1 @QTY =  0, @Kanban_Id = ISNULL(KanbanId, '') FROM Assy_runningkanban WITH (NOLOCK)
						WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode 
						And ISNULL(Iscompleted,0) = 0
						order by sequenceid asc
					end
			end
			else
			begin
					SELECT @QTY =  COUNT(1), @Kanban_Id = ISNULL(Kanban_Id, '') FROM Assy_Passed_Items_At_FV WITH (NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode 
					AND PartNo=ISNULL(@P_PartNumber,'') -- Added By Sachin 2020May25
					AND ISNULL(Is_Posted,0) = 0 Group By Kanban_Id, PartNo
						
					if(isnull(@Qty,0) =0)
					begin
						SELECT top 1 @QTY =  0, @Kanban_Id = ISNULL(KanbanId, '') FROM Assy_runningkanban WITH (NOLOCK)
						WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode 
						AND PartNo=ISNULL(@P_PartNumber,'') -- Added By Sachin 2020May25
						And ISNULL(Iscompleted,0) = 0
						order by sequenceid asc
					end
			end

			SELECT @Qty, @Kanban_Id 
		END 
   
		--Main Server.. 
		ELSE IF @Condition = 'GET_CONF_QTY' 
		BEGIN 
			SELECT CONVERT(INT, ISNULL(capacity, 0)) AS capacity FROM PHYSICAL_BIN_MASTER WITH (NOLOCK) WHERE Bin_Id = @Bin_Id AND STS_CD in ('0','50')
		END 


		ELSE IF @Condition = 'IS_PROD_CONF_REQUIRED' 
		BEGIN 
			--SELECT @Is_Confirmation_Required = ISNULL(IsProdConfRequired, 0) FROM #LineMst
			IF(@Is_Confirmation_Required = 1) 
			BEGIN 
				SET @ReturnValue = 'Y' 
			END 
			ELSE 
			BEGIN 
				SET @ReturnValue = 'N' 
			END 
		END 

		ELSE IF @Condition = 'IS_PROD_CONF_REQUIRED_AND_PENDING' 
		BEGIN 
			--SELECT @Is_Confirmation_Required = ISNULL(IsProdConfRequired, 0) FROM #LineMst
			IF @Is_Confirmation_Required = 1 
			BEGIN 
				IF EXISTS 
				( 
					SELECT Is_posted FROM Assy_Passed_Items_At_FV WITH (NOLOCK) WHERE LineCode = @LineCode
						AND ProfitCenterCode = @ProfitCenterCode AND PartNo = @PartNumber 
				) 
				BEGIN 
					SELECT @ReturnValue = 'Y' , @ReturnInt = 1 
				END 
				ELSE 
				BEGIN 
					SELECT @ReturnValue = 'N' , @ReturnInt = 1 
				END 
			END 
			ELSE 
			BEGIN 
				SELECT @ReturnValue = 'N' , @ReturnInt = 1 
			END 
		END 
   
		ELSE IF @Condition = 'TRIGGER_PROD_CONF' 
		BEGIN 
			SELECT @Qty = COUNT (1) FROM Assy_Passed_Items_At_FV  WITH (NOLOCK) WHERE PartNo = @PartNumber AND LineCode = @LineCode AND ISNULL(Transaction_Number,'') = ''
    
			IF(@Confirmation_Qty = @Qty) 
			BEGIN 
				SELECT @ReturnValue = 'Y' 
			END 
			ELSE 
			BEGIN 
				SELECT @ReturnValue = 'N' 
			END 
		END 
   
		ELSE IF @Condition = 'ALLOW_USER_TO_SCAN' 
		BEGIN 
			SELECT @Qty = COUNT (Distinct Transaction_Number) FROM Assy_Passed_Items_At_FV WITH (NOLOCK) WHERE ISNULL(Is_Posted,0) = 1
				AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			
			IF(@Qty < = 1) 
			BEGIN 
				SELECT @ReturnValue = 'Y' 
				RETURN 
			END 
			ELSE 
			BEGIN
				SELECT @ReturnValue = 'N' 
			END 
		END 
   
		--For Local server 
		ELSE IF @Condition = 'SAVE_PASS_BARCODE_FOR_PROD_CONF' 
		BEGIN
			SELECT Top 1 @DateCode = Datecode FROM Assy_RunningPart WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode 
			if(ISNULL(@P_PartNumber,'') <> '')
			begin
				IF NOT EXISTS 
				( 
					SELECT 1 FROM Assy_Passed_Items_At_FV WITH (NOLOCK) WHERE Barcode = @Barcode AND ProfitCenterCode = @ProfitCenterCode
				) 
				BEGIN 
					INSERT INTO Assy_Passed_Items_At_FV(ProfitCenterCode, DateCode, LineCode, Barcode, PartNo, Status, Ent_Dt, Ent_User, Kanban_Id)
					VALUES( @ProfitCenterCode, @DateCode, @LineCode, @Barcode, @P_PartNumber, @Status, GETDATE(), @UserId, @Kanban_Param)
				END 
			end
			else
			begin
				IF NOT EXISTS 
				( 
					SELECT 1 FROM Assy_Passed_Items_At_FV WITH (NOLOCK) WHERE Barcode = @Barcode AND ProfitCenterCode = @ProfitCenterCode
				) 
				BEGIN 
					INSERT INTO Assy_Passed_Items_At_FV(ProfitCenterCode, DateCode, LineCode, Barcode, PartNo, Status, Ent_Dt, Ent_User, Kanban_Id)
					VALUES( @ProfitCenterCode, @DateCode, @LineCode, @Barcode, @PartNumber, @Status, GETDATE(), @UserId, @Kanban_Param)
				END 
			end
		END 

		ELSE IF @Condition = 'DO_PROD_CONF_MANUAL' 
		BEGIN 
			BEGIN TRAN
				SELECT Top 1 @Prod_Version = PRODUCTION_VERSION FROM PHYSICAL_BIN_MASTER WITH (NOLOCK) WHERE BIN_ID = @Kanban_Param AND STS_CD = 0 AND WH_CODE = @ProfitCenterCode
				SET @PostLoc = RIGHT(@ProfitCenterCode,2) + '04'
      
				--Post the call to SAP against this transaction number.. 
				EXEC PROC_CALL_ERP @P_WH_CODE = @ProfitCenterCode, 
				@P_PROGRAM_ID = 'ASSY_MANUAL_CONF', 
				@P_SESSION_ID = '000', 
				@P_ERP_TS_TRAN_ID = @Dacs_TR_ID, 
				@P_TS_TRAN_TYPE = 'PROD_MANUAL_CONFIRMATION', 
				@P_PART_NO = @PartNumber, 
				@P_SRC_LOC = @PostLoc, 
				@P_DEST_LOC = @PostLoc, 
				@P_BACKFLUSH_LINE = @LineCode, 
				@P_QTY = @Qty, 
				@P_OPTION = 'LOG', 
				@P_USER = @UserId, 
				@P_CALLING_SEQ = '643', 
				@P_PLANT_CODE = 'BD01', 
				@P_SRC_WH_CODE = @ProfitCenterCode, 
				@P_KANBAN_NO = '', 
				@P_BIN_TP = 'F', 
				@P_REJECTION_DATA = @Prod_Version 

			COMMIT TRAN
						
			SELECT 'SUCCESS' 
		END 

		--FROM Central Server 
		ELSE IF @Condition = 'VALIDATE_KANBAN_FOR_MANUAL' 
		BEGIN 
			SELECT Top 1 @Prod_Version = PRODUCTION_VERSION FROM PHYSICAL_BIN_MASTER WITH (NOLOCK) WHERE BIN_ID = @Kanban_Param AND STS_CD = 0 AND WH_CODE = @ProfitCenterCode
			
			SELECT * INTO #ERP_PRODUCTION_VERSION_DATA FROM ERP_PRODUCTION_VERSION_DATA WITH (NOLOCK) WHERE PART_NO = @PartNumber AND 
					PRODUCTION_VER = @Prod_Version AND WH_CODE = @ProfitCenterCode 

			IF NOT EXISTS 
			( 
				SELECT 1 FROM #ERP_PRODUCTION_VERSION_DATA
			) 
			BEGIN 
				SELECT 'PRODUCTION VERSION IS NOT DEFINED'
				RETURN 
			END
   
			SELECT Top 1 @Var = STATUS FROM #ERP_PRODUCTION_VERSION_DATA

			IF(@Var = '1') 
			BEGIN 
				SELECT 'PRODUCTION VERSION IS LOCKED' 
				RETURN 
			END
			SELECT 'SUCCESS' 
		END 

		--FROM Local Server 
		ELSE IF @Condition = 'IS_KANBAN_FREE' 
		BEGIN 
			Declare @IsPosted BIT = 0; 
			SELECT @IsPosted = ISNULL(Is_Posted, 0) FROM Assy_Passed_Items_At_FV WITH (NOLOCK) WHERE Kanban_Id = @Bin_Id
			IF(@IsPosted = 1) 
				SELECT @ReturnValue = 'N' 
			ELSE 
				SELECT @ReturnValue = 'Y' 
		END 

		--FROM Central Server 
		ELSE IF @Condition = 'VALIDATE_KANBAN' 
		BEGIN
			SELECT * INTO #PHYSICAL_BIN_MASTER FROM PHYSICAL_BIN_MASTER WITH (NOLOCK) WHERE Bin_Id = @Bin_Id AND WH_CODE = @ProfitCenterCode

			IF NOT EXISTS 
			( 
				SELECT 1 FROM #PHYSICAL_BIN_MASTER
			) 
			BEGIN 
				SELECT 'KANBAN - ' + @Bin_Id + ' IS NOT DEFINED FOR WH_CODE - ' +  @ProfitCenterCode
				RETURN 
			END

			IF NOT EXISTS 
			( 
				SELECT 1 FROM #PHYSICAL_BIN_MASTER WHERE ISNULL(STS_CD,0) = 0
			) 
			BEGIN 
				SELECT 'KANBAN IS NOT ACTIVE' 
				RETURN 
			END 

			SELECT Top 1 @Confirmation_Qty = ISNULL(capacity, 0) FROM #PHYSICAL_BIN_MASTER

			IF ISNULL(@Confirmation_Qty,0) = 0
			BEGIN
				SELECT 'Kanban Qty is Zero (0). So Can not Process. Please Check with PPC.' 
				RETURN 
			END

			IF NOT EXISTS 
			( 
				SELECT 1 FROM #PHYSICAL_BIN_MASTER WHERE BIN_TYPE = 'PK' 
			) 
			BEGIN 
				SELECT 'INVALID_KANBAN' 
				RETURN 
			END 
    
			IF NOT EXISTS 
			( 
				SELECT 1 FROM #PHYSICAL_BIN_MASTER WHERE BIN_TYPE = 'PK' AND part_no = @PartNumber
			) 
			BEGIN 
				SELECT 'KANBAN IS NOT DEFINED FOR THIS PART' 
				RETURN 
			END 

			SELECT @Qty = CONVERT(INT,capacity) FROM #PHYSICAL_BIN_MASTER

			IF(@Qty <> @Confirmation_Qty) 
			BEGIN 
				SELECT 'KANBAN QTY MISMATCH'
				RETURN 
			END 
			
			IF EXISTS
			(
				SELECT 1 FROM RoutingConfigDetails (NOLOCK)	WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
					AND KeyType = 'IsCategoryRequired' AND KeyValue = '1'
			)
			BEGIN
				SELECT Top 1 @RunningPartcategory = Category FROM #Assy_RunningPart
				
				IF ISNULL(@RunningPartcategory,'') = ''
				BEGIN
					SELECT 'Running Part Category is blank'
					RETURN
				END
				
				SELECT Top 1 @Kanban_Category = KB_CATEGORY FROM #PHYSICAL_BIN_MASTER
				
				--IF ISNULL(@Kanban_Category,'') = ''
				--BEGIN
				--	SELECT 'Kanban Category is blank'
				--	RETURN
				--END

				IF ISNULL(@Kanban_Category,'') = ''
				BEGIN
					SET @Kanban_Category = 'OE'
				END

				IF ISNULL(@Kanban_Category,'OE') != ISNULL(@RunningPartcategory,'')
				BEGIN
					SELECT 'Kanban Category - ' + ISNULL(@Kanban_Category,'') + ' is not match with Running Part Category - ' + ISNULL(@RunningPartcategory,'')
					RETURN
				END
			END

			SELECT * INTO #ERP_PRODUCTION_VERSION_DATA_VK FROM ERP_PRODUCTION_VERSION_DATA WITH (NOLOCK) WHERE PART_NO = @PartNumber
				AND PRODUCTION_VER = @Prod_Version AND WH_CODE = @ProfitCenterCode 

			IF NOT EXISTS 
			( 
				SELECT 1 FROM #ERP_PRODUCTION_VERSION_DATA_VK
			)
			BEGIN 
				--PRINT @PartNumber 
				--PRINT @Prod_Version 
				SELECT 'PRODUCTION VERSION IS NOT DEFINED' 
				RETURN
			END 
   
			SELECT Top 1 @Var = STATUS FROM #ERP_PRODUCTION_VERSION_DATA_VK

			IF(@Var = '1') 
			BEGIN 
				SELECT 'PRODUCTION VERSION IS LOCKED' 
				RETURN 
			END 

			SELECT ERP_Conf_Timestamp, ResultTimestamp, isConfirmed INTO #Assy_LineAssyStatus FROM Assy_LineAssyStatus WITH (NOLOCK) WHERE Kanban_Id = @Bin_Id
				AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			
			SELECT @LeadTime = CONVERT(NUMERIC(5,2), LEAD_TIME) FROM PHYSICAL_BIN_MASTER WITH (NOLOCK) WHERE BIN_ID = @Bin_Id AND Sts_Cd = 0 AND WH_CODE = @ProfitCenterCode
			SELECT @LeadTime = ((@LeadTime * 100) * 60)/100 

			IF EXISTS 
			( 
				SELECT 1 FROM #Assy_LineAssyStatus
			) 
			BEGIN 
				--CONVERT the lead time INTO Minutes.. 
				--SELECT @LeadTime = ((@LeadTime * 100) * 60)/100 
				SELECT Top 1 @ConfTimeStamp = Case ISNULL(ERP_Conf_Timestamp,'') WHEN '' THEN ResultTimestamp ELSE ERP_Conf_Timestamp END FROM #Assy_LineAssyStatus
					WHERE ISNULL(isConfirmed,0) = 0 Order By ResultTimestamp Desc
   
				SELECT @Timediff = DATEDIFF(MI,@ConfTimeStamp,GETDATE()) 
     
				IF(@Timediff < @LeadTime)
				BEGIN 
					SELECT 'LEAD TIME IS NOT REACHED. SO PLEASE SCAN OTHER KANBAN' 
					RETURN 
				END 
			END

			SELECT Ent_Dt INTO #Assy_Kanban_Lead_Time_Check FROM Assy_Kanban_Lead_Time_Check WITH (NOLOCK) WHERE Kanban_Id = @Bin_Id AND ProfitCenterCode = @ProfitCenterCode
					AND LineCode = @LineCode
			-- New Validation For Lead Time Check
			IF EXISTS 
			( 
				SELECT 1 FROM #Assy_Kanban_Lead_Time_Check
			) 
			BEGIN 
				--SELECT @LeadTime = CONVERT(NUMERIC(5,2), LEAD_TIME) FROM PHYSICAL_BIN_MASTER WITH (NOLOCK) WHERE BIN_ID = @Bin_Id 
   
				--CONVERT the lead time INTO Minutes.. 
				--SELECT @LeadTime = ((@LeadTime * 100) * 60)/100 
				SELECT Top 1 @ConfTimeStamp = Ent_Dt FROM #Assy_Kanban_Lead_Time_Check Order By Ent_Dt Desc
   
				SELECT @Timediff = DATEDIFF(MI,@ConfTimeStamp,GETDATE()) 
     
				IF(@Timediff < @LeadTime) 
				BEGIN 
					SELECT 'LEAD TIME IS NOT REACHED. SO PLEASE SCAN OTHER KANBAN' 
					RETURN 
				END 
			END
			SELECT 'SUCCESS' 
		END 

		--Execute at Main Server
		ELSE IF @Condition = 'GENERATE_TRANSACTION_ID' 
		BEGIN 
			EXEC PROC_GET_DACS_TR_ID @ProfitCenterCode, 'PROD_CONFIRMATION', 'INSERT', '', @Dacs_TR_ID OUT, @TR_TYPE_OUT OUT
			SELECT @ReturnValue = CONVERT(VARCHAR(15), @Dacs_TR_ID) 
		END
	
		ELSE IF @Condition = 'DO_PROD_CONF' 
		BEGIN 
			IF(@Bin_Id LIKE 'EPK%')
			BEGIN
				SELECT @BinType='EPK'
			END
			ELSE 
			BEGIN
				SELECT @BinType='PK'
			END
			--Generate a Transaction Id AND UPDATE. 
			BEGIN TRAN 
				SET @PostLoc = RIGHT(@ProfitCenterCode,2) + '04'
				--Post the call to SAP against this transaction number.. 
				EXEC PROC_CALL_ERP @P_WH_CODE = @ProfitCenterCode, 
				@P_PROGRAM_ID = 'PROD_CONF', 
				@P_SESSION_ID = '000', 
				@P_ERP_TS_TRAN_ID = @Dacs_TR_ID, 
				@P_TS_TRAN_TYPE = 'PROD_CONFIRMATION', 
				@P_PART_NO = @PartNumber, 
				@P_SRC_LOC = @PostLoc, 
				@P_DEST_LOC = @PostLoc, 
				@P_BACKFLUSH_LINE = @LineCode, 
				@P_QTY = @Qty, 
				@P_OPTION = 'LOG', 
				@P_USER = @UserId, 
				@P_CALLING_SEQ = '643', 
				@P_PLANT_CODE = 'BD01', 
				@P_SRC_WH_CODE = @ProfitCenterCode, 
				@P_KANBAN_NO = @Bin_Id, 
				@P_BIN_TP = @BinType
			IF EXISTS(SELECT TOP 1 1 FROM TYPE_DEFINITION_XREF_DATA(NOLOCK)
			WHERE ATTRB_CD=@LineCode AND TYPE_CATEGORY_CD='LINE_ATTRB'
			AND TYPE_CD='eKanban_Enable' AND WH_CODE=@ProfitCenterCode AND ATTRB_VAL='1')
			BEGIN

				Declare @Production_order nvarchar(100)
				select * into #temp_PHYSICAL_BIN_MASTER from PHYSICAL_BIN_MASTER with(nolock)
				where WH_CODE=@ProfitCenterCode and Bin_id=@Bin_Id

				select @Production_order=ORDER_NO from #temp_PHYSICAL_BIN_MASTER

				Update PHYSICAL_BIN_MASTER set STS_CD ='100' 	
				where WH_CODE=@ProfitCenterCode and Bin_id=@Bin_Id 

				Update Assy_productionordermst set status ='100', producedqty=qty	
				where ProfitCenterCode=@ProfitCenterCode and OrderNo=@Production_order

			END
			COMMIT TRAN

			SELECT 'SUCCESS'
		END 
   
		--Local Server.. 
		ELSE IF @Condition = 'UPDATE_FV_POST_POSTING' 
		BEGIN
			UPDATE Assy_Passed_Items_At_FV SET Transaction_Number = @Dacs_TR_ID, Is_Posted = 1 WHERE PartNo = @PartNumber
				AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode AND Is_Posted = 0
			-------------EKANBAN Prerna 06042020
			IF EXISTS(SELECT TOP 1 1 FROM TYPE_DEFINITION_XREF_DATA(NOLOCK)
			WHERE ATTRB_CD=@LineCode AND TYPE_CATEGORY_CD='LINE_ATTRB'
			AND TYPE_CD='eKanban_Enable' AND WH_CODE=@ProfitCenterCode AND ATTRB_VAL='1')
			BEGIN
			        Declare @runningdatecode nvarchar(100)=''
					exec Assy_proc_datecode @ProfitCenterCode,@ReturnValue out,@ReturnInt out
						
					if exists(select top 1 1 from Assy_RunningKanban with(nolock) where Isrunning=1 and PartNo = @PartNumber
					AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode)
					Begin
					    select  @runningdatecode =datecode from Assy_RunningKanban  with(nolock) where Isrunning=1 and PartNo = @PartNumber
					    AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
						if(@runningdatecode != @ReturnValue)
						Begin
						    delete from Assy_RunningKanban where Isrunning=0 and PartNo = @PartNumber
						    AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
						end
						update Assy_RunningKanban set Isrunning='0',Iscompleted='1',PostedDatecode=@ReturnValue where Isrunning=1 and PartNo = @PartNumber
						AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
					end
				    
			END
			-------------END
			
			--Added By Rashid On 08th August 2016 For Material Feeding Validation
			IF @IsMatFeedRequired = 1
			BEGIN
				SELECT Top 1 @UserId = Ent_User FROM Assy_Passed_Items_At_FV WHERE  LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode AND Transaction_Number = @Dacs_TR_ID
				IF (@Dacs_TR_ID != '')
				BEGIN
					SET @ExecQuery = '
					DELETE FROM ' + @LinkServerName + '.dbo.Assy_Mat_Feed_Status_IsProdConf WHERE LineCode = ''' + @LineCode + ''' AND ProfitCenterCode = ''' + @ProfitCenterCode + '''

					INSERT INTO ' + @LinkServerName + '.dbo.Assy_Mat_Feed_Status_IsProdConf(ProfitCenterCode, LineCode, PartNumber, Transaction_Number, Ent_Dt, Ent_User, FedStatus)
					SELECT ''' + @ProfitCenterCode + ''', ''' + @LineCode + ''', ''' + @PartNumber + ''', ' + Convert(Varchar(20),@Dacs_TR_ID) + ', GETDATE(), ''' + @UserId + ''', 2
					'
					PRINT @ExecQuery
					--EXEC (@ExecQuery)
					EXEC SP_EXECUTESQL @ExecQuery
				END
			END
		END 
		--Added By Sachin 18Dec2019
		--Main\Mini\Central Server.. 
		ELSE IF @Condition = 'UPDATE_FV_POST_POSTING_M_SERVER' 
		BEGIN
			UPDATE Assy_Passed_Items_At_FV SET Transaction_Number = @Dacs_TR_ID, Is_Posted = 1 WHERE PartNo = @PartNumber
			AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode AND Is_Posted = 0
		END 
		ELSE IF @Condition = 'UPDATE_FV_POST_POSTING_FOR_MANUAL_M_SERVER' 
		BEGIN
			UPDATE Assy_Passed_Items_At_FV SET Transaction_Number = @Dacs_TR_ID, Is_Posted = 1 WHERE PartNo = @PartNumber
			AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode AND Is_Posted = 0
		END 
		--Ended By Sachin 18Dec2019		
		--Local Server.. 
		ELSE IF @Condition = 'UPDATE_FV_POST_POSTING_FOR_MANUAL' 
		BEGIN 
			UPDATE Assy_Passed_Items_At_FV SET Transaction_Number = @Dacs_TR_ID, Is_Manual = 1, Is_Posted = 1 WHERE PartNo = @PartNumber
				AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode AND Is_Posted = 0

			--Added By Rashid On 08th August 2016 For Material Feeding Validation
			IF @IsMatFeedRequired = 1
			BEGIN
				SELECT Top 1 @UserId = Ent_User FROM Assy_Passed_Items_At_FV WHERE  LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode AND Transaction_Number = @Dacs_TR_ID
				IF (@Dacs_TR_ID != '')
				BEGIN
					SET @ExecQuery = '
						DELETE FROM ' + @LinkServerName + '.dbo.Assy_Mat_Feed_Status_IsProdConf WHERE LineCode = ''' + @LineCode + ''' AND ProfitCenterCode = ''' + @ProfitCenterCode + '''
						
						INSERT INTO ' + @LinkServerName + '.dbo.Assy_Mat_Feed_Status_IsProdConf(ProfitCenterCode, LineCode, PartNumber, Transaction_Number, Ent_Dt, Ent_User, FedStatus)
						SELECT ''' + @ProfitCenterCode + ''', ''' + @LineCode + ''', ''' + @PartNumber + ''', ''' + Convert(Varchar(20),@Dacs_TR_ID) + ''', GETDATE(), ''' + @UserId + ''', 2
						'
						PRINT @ExecQuery
						--EXEC (@ExecQuery)
						EXEC SP_EXECUTESQL @ExecQuery
				END
			END
		END

		--Local Server.. 
		ELSE IF @Condition = 'GET_POSTED_TRAN_ID' 
		BEGIN 
			--Added By Sachin 18Dec2019
			if exists(select top 1 1 from RoutingConfigDetails(nolock) where KeyType='IsProductionConfirmationUsingMINI' 
			and Isnull(KeyValue,'')='1' and STS_Cd=0 and ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode)
			begin
			
			SET @ExecQuery = ''
			SET @ExecQuery = 'SELECT ProfitCenterCode,LineCode,PartNo,Transaction_Number,Old_Transaction_Number,Kanban_Id FROM '  + @LinkServerName + 
							  '.dbo.Assy_Passed_Items_At_FV WITH (NOLOCK) WHERE ProfitCenterCode =' +'''' + @ProfitCenterCode + '''' + ' AND LineCode = ' +
							   + '''' + @LineCode +'''' +' AND Is_Posted = 1 Order By Ent_Dt'

			PRINT @ExecQuery			
			insert into @Tmp_Assy_Passed_Items_At_FV(ProfitCenterCode,LineCode,PartNo,Transaction_Number,Old_Transaction_Number,Kanban_Id)
			EXEC SP_EXECUTESQL @ExecQuery

			if exists(select top 1 1 from @Tmp_Assy_Passed_Items_At_FV where Old_Transaction_Number is not null)
			begin
					
					update f
					set f.Transaction_Number = tf.Transaction_Number
					from Assy_Passed_Items_At_FV(nolock) f inner join
					@Tmp_Assy_Passed_Items_At_FV tf on
					f.ProfitCenterCode=tf.ProfitCenterCode and
					f.LineCode=tf.LineCode and
					f.PartNo=tf.PartNo and
					f.Kanban_Id=tf.Kanban_Id and
					f.Transaction_Number=tf.Old_Transaction_Number and
					Is_Posted = 1

			end

			SELECT @ReturnValue =  (SELECT Top 1 Transaction_Number FROM Assy_Passed_Items_At_FV WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			AND Is_Posted = 1 Order By Ent_Dt) 

			end
			else
			begin
			SELECT @ReturnValue =  (SELECT Top 1 Transaction_Number FROM Assy_Passed_Items_At_FV WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
				AND Is_Posted = 1 Order By Ent_Dt) 
			end			
		END 

		--Local Server.. 
		ELSE IF @Condition = 'GET_POSTED_PART_NO' 
		BEGIN 
			SELECT Top 1 @ReturnValue =  PartNo FROM Assy_Passed_Items_At_FV WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
				AND Is_Posted = 1
		END 

		ELSE IF @Condition = 'GET_POSTED_PASSED_QTY' 
		BEGIN 
			SELECT COUNT(1) FROM Assy_Passed_Items_At_FV WITH (NOLOCK) WHERE PartNo = @PartNumber 
				AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode AND Is_Posted = 1 
		END 

		ELSE IF @Condition = 'CHECK_ERP_RESPONSE' 
		BEGIN 
			SELECT @Var = CONVERT(VARCHAR(20), @Dacs_TR_ID); 

			IF(ISNULL(@Var,'') = '') 
			BEGIN 
				SELECT 'NO_DATA_TO_CHECK' 
				RETURN 
			END 

			SELECT @TransId = CONVERT(NUMERIC(9,0), @Var) 
			
			SELECT WS_RESULT INTO #ERP_TS_DATA FROM ERP_TS_DATA WITH (NOLOCK) WHERE ERP_TS_TRAN_ID = @TransId

			IF NOT EXISTS 
			( 
				SELECT 1 FROM #ERP_TS_DATA
			) 
			BEGIN 
				SELECT 'DATA_NOT_POSTED' 
				RETURN 
			END 
    
			SELECT @Var = WS_RESULT FROM #ERP_TS_DATA
    
			IF (@Var = '') 
			BEGIN 
				SELECT 'WAITING_FOR_RESPONSE' 
				RETURN
			END 

			IF(@Var NOT LIKE '%success%' AND @var NOT LIKE '%duplicate record%') 
			BEGIN 
				Declare @Error_Part VARCHAR(20) = ''
				UPDATE Assy_Passed_Items_At_FV SET isConfirmed = 0 WHERE Transaction_Number = @TransId 
				--SELECT Top 1 @Error_Part = RTRIM(ISNULL(Assy_PartNo,'')) FROM Assy_RunningPart WITH (NOLOCK) Order by CreatedDate Desc
				SET @Error_Part = @Part_As_Param
				--SELECT 'FAILED' 
				SELECT 'Failed|' + @Error_Part + '|' + @Var
				RETURN 
			END 
			--Comment By Rashid On 19th Oct 2016 because Inv Serial entry is inserted from Packaging application
			--EXEC assy_Proc_Insert_Inv @ProfitCenterCode = @ProfitCenterCode, @UserId = @UserId, @Qty =  @Passed_Qty, @PartNo = @Part_As_Param, @OUTPUT_BIN_ID = @Kanban_Id

			SELECT 'SUCCESS' 
		END 
   
		ELSE IF @Condition = 'UPDATE_FV_POST_CONF' 
		BEGIN 
			SELECT * INTO #Assy_Passed_Items_At_FV FROM Assy_Passed_Items_At_FV WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode

			IF (ISNULL(@Dacs_TR_ID,0) = 0)
			BEGIN
				SELECT Top 1 @Dacs_TR_ID = Transaction_Number FROM #Assy_Passed_Items_At_FV	Order by Ent_Dt
			END
			-- Modiffied By Rashid on 19th Feb 2016
			SELECT Top 1 @DateCode = LTRIM(RTRIM(DateCode)), @UserId = Ent_User FROM #Assy_Passed_Items_At_FV WHERE Transaction_Number = @Dacs_TR_ID Order by Ent_Dt Desc
			
			IF (ISNULL(@DateCode,'') = '')
			BEGIN
				SELECT Top 1 @DateCode = Datecode, @UserId = CreatedBy FROM Assy_RunningPart WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode	
			END
			--UPDATE the confirmation flag that indicates that confirmatin has been recieved.. 
			UPDATE Assy_Passed_Items_At_FV SET isConfirmed = 1 WHERE Transaction_Number = @Dacs_TR_ID
			UPDATE #Assy_Passed_Items_At_FV SET isConfirmed = 1 WHERE Transaction_Number = @Dacs_TR_ID
    
			--UPDATE the details in Assy_LineAssyStatus Table.. 
			UPDATE A SET A.Transaction_Number = B.Transaction_Number, A.isConfirmed = B.isConfirmed,
				A.Kanban_Id = B.Kanban_Id, A.ERP_Conf_Timestamp = GETDATE() FROM Assy_LineAssyStatus AS A (NOLOCK)
					INNER JOIN #Assy_Passed_Items_At_FV AS B ON A.Barcode = B.Barcode AND A.ProfitCenterCode = B.ProfitCenterCode AND A.LineCode = B.LineCode
						WHERE A.ProfitCenterCode = @ProfitCenterCode AND A.LineCode = @LineCode
					--AND B.Transaction_Number = @Dacs_TR_ID
			/*
			Declare @Assy_LineAssyStatus Table(
						[ProfitCenterCode] [varchar](10) NOT NULL,
						[LineCode] [varchar](10) NOT NULL,
						[MachineCode] [varchar](20) NOT NULL,
						[OperationCode] [varchar](10) NOT NULL,
						[StationCode] [varchar](20) NOT NULL,
						[Barcode] [varchar](100) NOT NULL,
						[Status] [char](2) NULL,
						[FailCount] [tinyint] NOT NULL,
						[Datecode] [char](4) NOT NULL,
						[PartNo] [varchar](60) NOT NULL,
						[ScanTimestamp] [datetime] NULL,
						[ResultTimestamp] [datetime] NULL,
						[Active] [BIT] NOT NULL,
						[UserID] [varchar](20) NULL,
						[IsTallyChartApproved] [BIT] NULL,
						[Transaction_Number] [varchar](20) NULL,
						[isConfirmed] [BIT] NULL,
						[Kanban_Id] [varchar](20) NULL,
						[ERP_Conf_Timestamp] [datetime] NULL,
						[IsReworkPart] [BIT] NULL,
						[Is_Manual] [BIT] NULL
					)
			INSERT INTO @Assy_LineAssyStatus ([ProfitCenterCode],[LineCode],[MachineCode],[OperationCode],[StationCode],	[Barcode],[Status],[FailCount],[Datecode],[PartNo],[ScanTimestamp],[ResultTimestamp],[Active],[UserID],[IsTallyChartApproved],[Transaction_Num

ber],[isConfirmed],[Kanban_Id],[ERP_Conf_Timestamp],[IsReworkPart],[Is_Manual])
			SELECT A.[ProfitCenterCode],A.[LineCode],A.[MachineCode],A.[OperationCode],A.[StationCode],A.[Barcode],A.[Status],A.[FailCount],A.[Datecode],A.[PartNo],A.[ScanTimestamp],A.[ResultTimestamp],A.[Active],A.[UserID],A.[IsTallyChartApproved],A.[Transaction_

Number],A.[isConfirmed],A.[Kanban_Id],A.[ERP_Conf_Timestamp],A.[IsReworkPart],A.[Is_Manual] FROM Assy_LineAssyStatus AS A (NOLOCK)
			INNER JOIN Assy_Passed_Items_At_FV AS B (NOLOCK) ON A.Barcode = B.Barcode
			WHERE A.ProfitCenterCode = @ProfitCenterCode AND A.LineCode = @LineCode
					--AND B.Transaction_Number = @Dacs_TR_ID
			*/
			IF ((SELECT COUNT(*) FROM Assy_LineAssyStatus_Temp_Update_FV(NOLOCK)) > 0)
			BEGIN
				TRUNCATE TABLE Assy_LineAssyStatus_Temp_Update_FV
			END
			
			SELECT @MachineCode = dbo.Assy_FN_Get_FinalViewing_MachineCode_From_LineCode(@ProfitCenterCode,@LineCode)
			
			IF @OpCode = '' OR @MachineCode = ''
			BEGIN
				IF (LEFT(@LineCode,1) = 'M')
				BEGIN
					SET @OpCode = 'OCFV'
					SET @MachineCode = 'MCFV'
				END
				ELSE IF(LEFT(@LineCode,1) = 'P')
				BEGIN
					SET @OpCode = 'OCFVSTMC'
					SET @MachineCode = 'MCFVSTMC'
				END
			END

			INSERT INTO Assy_LineAssyStatus_Temp_Update_FV (ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,Status,FailCount,
			Datecode,PartNo,ScanTimestamp,ResultTimestamp,Active,UserID,IsTallyChartApproved,Transaction_Number,isConfirmed,
			Kanban_Id,ERP_Conf_Timestamp,IsReworkPart,Is_Manual)
			SELECT A.[ProfitCenterCode],A.[LineCode],A.[MachineCode],A.[OperationCode],A.[StationCode],A.[Barcode],A.[Status],A.[FailCount],A.[Datecode],A.[PartNo],A.[ScanTimestamp],A.[ResultTimestamp],A.[Active],A.[UserID],
			A.[IsTallyChartApproved],A.[Transaction_Number],A.[isConfirmed],A.[Kanban_Id],A.[ERP_Conf_Timestamp],A.[IsReworkPart],A.[Is_Manual]
				FROM Assy_LineAssyStatus AS A (NOLOCK)
					INNER JOIN #Assy_Passed_Items_At_FV AS B (NOLOCK) ON A.Barcode = B.Barcode AND A.ProfitCenterCode = B.ProfitCenterCode AND A.LineCode = B.LineCode
						WHERE A.ProfitCenterCode = @ProfitCenterCode AND A.LineCode = @LineCode AND A.MachineCode = @MachineCode
							AND ISNULL(B.Transaction_Number,'') != ''
			
			SET @ExecQuery = ''
			SET @ExecQuery = 'INSERT INTO ' + @LinkServerName + '.dbo.Assy_Kanban_Lead_Time_Check(ProfitCenterCode,LineCode,DateCode,PartNo,Kanban_Id,Transaction_Number,Ent_Dt,Ent_User)
								SELECT Top 1 ProfitCenterCode,LineCode,DateCode,PartNo,Kanban_Id,Transaction_Number,GETDATE(),Ent_User FROM Assy_Passed_Items_At_FV WHERE Transaction_Number != '''' Order By Ent_Dt Desc'
			
			PRINT @ExecQuery
			--EXEC (@ExecQuery)
			EXEC SP_EXECUTESQL @ExecQuery

			--DELETE FROM Assy_Passed_Items_At_FV WHERE Transaction_Number = @Dacs_TR_ID --COMMENTED BY SACHIN 18Dec2019
			--Added By Sachin 18Dec2019
			delete from Assy_Passed_Items_At_FV
			OUTPUT deleted.[ProfitCenterCode],deleted.[DateCode],deleted.LineCode,deleted.Barcode,
			deleted.PartNo,deleted.[Status],deleted.Ent_Dt,deleted.Ent_User,deleted.Transaction_Number,deleted.isConfirmed,
			deleted.Kanban_Id,deleted.Is_Posted,deleted.Is_Manual,deleted.Old_Transaction_Number,deleted.[TRAN_UID]
			into Assy_Passed_Items_At_FV_History
			WHERE Transaction_Number = @Dacs_TR_ID
			--Ended By Sachin 18Dec2019

			--SELECT COUNT(*) FROM Assy_LineAssyStatus_Temp_Update_FV(NOLOCK)
			--UPDATE the details in Assy_LineAssyStatus Table in Main Server
			IF ((SELECT COUNT(*) FROM Assy_LineAssyStatus_Temp_Update_FV(NOLOCK)) > 0)
			BEGIN
				----Start-- Added By Rashid Siddiqui ON 17th July 2016 For Material Feeding Validation
				--SET @ExecQuery = ''
				--SET @ExecQuery = '
				--EXEC ' + @LinkServerName + '.dbo.Assy_Proc_MaterialFeedingValidation
				--							@Condition = ''MAT_FEED_STOCK_DEDUCTION_IN_INV_SERIAL_WHEN_PROD_CONF_ENABLE'',
				--							@ProfitCenterCode = ''' + @ProfitCenterCode + ''',
				--							@LineCode = ''' + @LineCode + ''', @UserId = ''' + @UserId + ''' '
				--PRINT @ExecQuery
				--EXEC (@ExecQuery)
				/* Commented By RS On 29-Nov-2017 beacuase of Update Central Server table through link Server
				IF @IsMatFeedRequired = 1
				BEGIN
					SET @ExecQuery = ''
					SET @ExecQuery = '
							UPDATE M SET M.PROD_CONFIRM_STS = 1, M.IsActive = 0, M.ERP_TS_TRAN_ID = (Case ISNULL(Q.Transaction_Number,'''') WHEN '''' THEN '''' ELSE ISNULL(Q.Transaction_Number,'''') END )
								FROM ' + @LinkServerName + '.dbo.Assy_FGChildPartConsumption M
									INNER JOIN Assy_LineAssyStatus_Temp_Update_FV Q
										ON M.WH_CODE = Q.ProfitCenterCode AND M.LINE_CODE = Q.LineCode
											AND M.FG_Barcode = Q.Barcode 
											WHERE M.WH_CODE = ''' + @ProfitCenterCode + ''' AND M.LINE_CODE = ''' + @LineCode + ''' AND Q.DateCode = ''' + @DateCode + ''' '
					PRINT @ExecQuery
					--EXEC (@ExecQuery)
					EXEC SP_EXECUTESQL @ExecQuery
				END
				SET @ExecQuery = ''
				
				SET @ExecQuery = '
						UPDATE T SET T.Transaction_Number = S.Transaction_Number, T.isConfirmed = S.isConfirmed, T.Kanban_Id = S.Kanban_Id, T.ERP_Conf_Timestamp = S.ERP_Conf_Timestamp
							FROM ' + @LinkServerName + '.dbo.Assy_LineAssyStatus T
								INNER JOIN Assy_LineAssyStatus_Temp_Update_FV S
									ON T.ProfitCenterCode = S.ProfitCenterCode AND T.LineCode = S.LineCode AND T.Barcode = S.Barcode
												WHERE S.ProfitCenterCode = ''' + @ProfitCenterCode + ''' AND S.LineCode = ''' + @LineCode + ''''
					PRINT @ExecQuery
					--EXEC (@ExecQuery)
					EXEC SP_EXECUTESQL @ExecQuery
					
					*/
					-- Added By RS On 29-Nov-2017 Later we have to update in central by a new proc
					SET @ExecQuery = ''
					SET @ExecQuery = 'INSERT INTO ' + @LinkServerName + '.dbo.Assy_LineAssyStatus_Temp_Update_FV(ProfitCenterCode,LineCode,MachineCode,OperationCode,
					StationCode,Barcode,Status,FailCount,Datecode,PartNo,ScanTimestamp,ResultTimestamp,Active,UserID,IsTallyChartApproved,Transaction_Number,isConfirmed,
					Kanban_Id,ERP_Conf_Timestamp,IsReworkPart,Is_Manual)
					SELECT ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,Status,FailCount,Datecode,PartNo,ScanTimestamp,ResultTimestamp,
					Active,UserID,IsTallyChartApproved,Transaction_Number,isConfirmed,Kanban_Id,ERP_Conf_Timestamp,IsReworkPart,Is_Manual FROM Assy_LineAssyStatus_Temp_Update_FV WHERE ProfitCenterCode = ''' + @ProfitCenterCode + ''' AND LineCode = ''' + @LineCode + ''' '
					Print @ExecQuery
					EXEC SP_EXECUTESQL @ExecQuery

					IF ((SELECT COUNT(*) FROM Assy_LineAssyStatus_Temp_Update_FV(NOLOCK)) > 0)
					BEGIN
						TRUNCATE TABLE Assy_LineAssyStatus_Temp_Update_FV
					END
				END
		END 
		--Added By Sachin 18Dec2019
		--Main\Mini\Central Server.. 
		ELSE IF @Condition = 'UPDATE_FV_POST_CONF_M_SERVER' 
		BEGIN
				IF (ISNULL(@Dacs_TR_ID,0) = 0)
				BEGIN
					SELECT Top 1 @Dacs_TR_ID = Transaction_Number FROM Assy_Passed_Items_At_FV WITH (NOLOCK)
					Order by Ent_Dt
				END			
			
				delete from Assy_Passed_Items_At_FV
				OUTPUT deleted.[ProfitCenterCode],deleted.[DateCode],deleted.LineCode,deleted.Barcode,
				deleted.PartNo,deleted.[Status],deleted.Ent_Dt,deleted.Ent_User,deleted.Transaction_Number,deleted.isConfirmed,
				deleted.Kanban_Id,deleted.Is_Posted,deleted.Is_Manual,deleted.Old_Transaction_Number,deleted.[TRAN_UID]
				into Assy_Passed_Items_At_FV_History
				WHERE Transaction_Number = @Dacs_TR_ID
		END 
		--Endded By Sachin 18Dec2019
		ELSE IF @Condition = 'IS_PREV_CONF_PENDING' 
		BEGIN 
			IF 
			( 
				(SELECT Top 1 Is_posted FROM Assy_Passed_Items_At_FV WITH (NOLOCK) WHERE LineCode = @LineCode 
					AND ProfitCenterCode = @ProfitCenterCode AND PartNo = @PartNumber AND ISNULL(Is_Posted,0) = 1 ORDER By Ent_Dt DESC) = 1
			) 
			BEGIN 
				SELECT @ReturnValue = 'Y' 
				RETURN 
			END 
    
			SELECT @ReturnValue = 'N' 
		END 
   
		ELSE IF @Condition = 'IS_LEAD_TIME_EXPIRED' 
		BEGIN 
			SELECT Kanban_Id, ERP_Conf_Timestamp, Transaction_Number, ResultTimestamp INTO #Assy_LineAssyStatus_ILTE FROM Assy_LineAssyStatus WITH (NOLOCK)
				WHERE Kanban_Id = @Bin_Id AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			
			IF NOT EXISTS 
			( 
				SELECT 1 FROM #Assy_LineAssyStatus_ILTE
			) 
			BEGIN 
				SELECT @ReturnValue = 'NOT_FOUND' 
				RETURN 
			END

			IF OBJECT_ID('LEAD_TIME_TEMP') IS NOT NULL
			BEGIN
				DROP TABLE LEAD_TIME_TEMP
			END
			SET @ExecQuery = ''
			SET @ExecQuery = '
				SELECT  CONVERT(NUMERIC(5,2), LEAD_TIME) AS Lead_Time INTO LEAD_TIME_TEMP  FROM ' +  @LinkServerName + '.dbo.PHYSICAL_BIN_MASTER WITH (NOLOCK)
					WHERE BIN_ID = ''' + @Bin_Id + ''' AND STS_CD = 0 AND WH_CODE = ''' + @ProfitCenterCode + '''' 
			--PRINT @ExecQuery
			--EXEC(@ExecQuery)
			EXEC SP_EXECUTESQL @ExecQuery
			
			SELECT Top 1 @LeadTime = Lead_Time FROM LEAD_TIME_TEMP
			SELECT @LeadTime = ((@LeadTime * 60) / 100)
			
			SELECT Top 1 @ConfTimeStamp = ERP_Conf_Timestamp FROM #Assy_LineAssyStatus_ILTE Order By Transaction_Number desc,ResultTimestamp,Kanban_Id
   
			SELECT @Timediff = DATEDIFF(MI,@ConfTimeStamp,GETDATE()) 
			
			--IF OBJECT_ID('LEAD_TIME_TEMP') IS NOT NULL
			--BEGIN
			--	DROP TABLE LEAD_TIME_TEMP
			--END
			
			IF(@Timediff < @LeadTime) 
			BEGIN
				SELECT @ReturnValue = 'N'
				--SELECT 'LEAD TIME IS NOT REACHED. SO PLEASE SCAN OTHER KANBAN' 
				RETURN 
			END
   
			SELECT @ReturnValue = 'Y' 
		END
   
		ELSE IF @Condition = 'GET_PENDING_FOR_CONFIRMATION' 
		BEGIN 
			SELECT Barcode, Ent_Dt FROM Assy_Passed_Items_At_FV WITH (NOLOCK) WHERE ISNULL(Is_Posted,0) = 0 AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
		END 

		ELSE IF @Condition = 'GET_PRODUCTION_ORDERS' 
		BEGIN 
			SELECT Distinct PRODUCTION_VER FROM ERP_PRODUCTION_VERSION_DATA WITH (NOLOCK) WHERE WH_CODE = @ProfitCenterCode AND PART_NO = @PartNumber
		END
		 
		--ELSE IF @Condition = 'GET_PRODUCTION_ORDERS' 
		--BEGIN 
		--	SELECT Distinct PRODUCTION_VER FROM ERP_PRODUCTION_VERSION_DATA WITH (NOLOCK) WHERE WH_CODE = @ProfitCenterCode AND PART_NO = @PartNumber
		--END
		 
		ELSE IF @Condition = 'ENABLE_DISABLE_PROD_CONF' 
		BEGIN 
			IF(@Enable_Prod_Conf = 1)
			BEGIN 
				UPDATE LineMst SET IsProdConfRequired = 1 WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
			END
			ELSE IF(@Enable_Prod_Conf = 0)
			BEGIN 
				UPDATE LineMst SET IsProdConfRequired = 0 WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode

				--Added by Sachin 18Dec2019
				delete from Assy_Passed_Items_At_FV
				OUTPUT deleted.[ProfitCenterCode],deleted.[DateCode],deleted.LineCode,deleted.Barcode,
				deleted.PartNo,deleted.[Status],deleted.Ent_Dt,deleted.Ent_User,deleted.Transaction_Number,deleted.isConfirmed,
				deleted.Kanban_Id,deleted.Is_Posted,deleted.Is_Manual,deleted.Old_Transaction_Number,deleted.[TRAN_UID]
				into Assy_Passed_Items_At_FV_History
				WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
				--Ended by Sachin 18Dec2019

				--Commented By Sachin 18Dec2019
				--DELETE FROM Assy_Passed_Items_At_FV WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
				--Commented Ended By Sachin 18Dec2019

				--Added By Rashid on 11 August 2016 For Material Feeding
				--IF OBJECT_ID('Assy_LineMaterialStockStatus') IS NOT NULL
				--BEGIN
				--	IF EXISTS (SELECT 1 FROM Assy_LineMaterialStockStatus WITH (NOLOCK) WHERE IsActive = 1)
				--	BEGIN
				--		UPDATE Assy_LineMaterialStockStatus SET IsActive = 9 WHERE IsActive = 1
				--	END
				--END
				--IF OBJECT_ID('Assy_FGChildPartConsumption') IS NOT NULL
				--BEGIN
				--	IF EXISTS (SELECT 1 FROM Assy_FGChildPartConsumption WITH (NOLOCK) WHERE IsActive = 2)
				--	BEGIN
				--		UPDATE Assy_FGChildPartConsumption SET IsActive = 9 WHERE IsActive = 1
				--	END
				--END
			END
			
			SELECT ISNULL(IsProdConfRequired,0) IsProdConfRequired FROM LineMst WITH (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
			RETURN 
		END

		ELSE IF @Condition = 'GET_PROD_CONF_STATUS' 
		BEGIN 
			--SELECT ISNULL(IsProdConfRequired,0) IsProdConfRequired FROM LineMst WITH (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
			SELECT ISNULL(IsProdConfRequired,0) IsProdConfRequired FROM #LineMst
			SELECT @ReturnInt = 1 
			RETURN 
		END 

		ELSE IF (@Condition = 'GET_LINECODE') 
		BEGIN 
			SELECT L.LineCode, L.LineName FROM #LineMst L WHERE LEFT(LineCode,1) = LEFT(@LineCode,1) Order By 2
			SELECT @ReturnInt = 1 
		END 

		ELSE IF (@Condition = 'IS_NEW_PART') 
		BEGIN 
			--SELECT Top 1 @DateCode = Datecode, @PartNumber = Assy_PartNo FROM Assy_RunningPart WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode --Order By CreatedDate Desc
			SELECT Top 1 @DateCode = Datecode, @PartNumber = Assy_PartNo FROM #Assy_RunningPart
    
			IF EXISTS (SELECT Top 1 1 FROM Assy_LineAssyStatus (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
				AND LineCode = @LineCode AND PartNo = @PartNumber AND isConfirmed = 1) 
			BEGIN 
				SELECT @ReturnValue = 'Y' 
			END 
			ELSE 
			BEGIN 
				SELECT @ReturnValue = 'N' 
			END 
		END

		ELSE IF (@Condition = 'GET_RUNNING_PART_PRINT_QTY') 
		BEGIN 
			Declare @PrintQty INT = 0
			SELECT @PrintQty = ISNULL(PrintedQty,0)  From Assy_Barcode_Printed_Counter (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			SET @PrintQty = ISNULL(@PrintQty,0)

			IF (@PrintQty > 0 )
			BEGIN
				SELECT @ReturnValue = 'Y'
			END
			ELSE
				SELECT @ReturnValue = 'N'

			SELECT @ReturnInt = 1 
		END

		ELSE IF (@Condition = 'GET_LineTypeName_From_LineCode')
		BEGIN 
			SELECT @ReturnValue = dbo.Assy_FN_Get_LineTypeName_From_LineCode(@ProfitCenterCode,@LineCode)
			IF (ISNULL(@ReturnValue,'') = '')
				SELECT @ReturnValue = 'N'
			ELSE
				SELECT @ReturnValue = @ReturnValue
			SELECT @ReturnInt = 1 
		END
		ELSE IF (@Condition = 'UPDATE_RUNNING_KANBAN')
		BEGIN
					Declare @rundatecode nvarchar(100)=''
					exec Assy_proc_datecode @ProfitCenterCode,@ReturnValue out,@ReturnInt out
				
				if(@P_Allow2Parts = 0)
				begin
				   if exists(select top 1 1 from Assy_RunningKanban with(nolock) where Isrunning=1 and PartNo = @PartNumber
					AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode and isnull(IsCompleted,0) <> '1' 
					and PostedDatecode is null and kanbanid=@Bin_Id)
					Begin
					    select  @rundatecode =datecode from Assy_RunningKanban  with(nolock) where Isrunning=1 and PartNo = @PartNumber
					    AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
						if(@rundatecode != @ReturnValue)
						Begin
						    delete from Assy_RunningKanban where Isrunning=0 and PartNo = @PartNumber
						    AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
						end
						update Assy_Passed_Items_At_FV set Transaction_Number ='Ekanban' where Kanban_Id=@Bin_Id
						and Transaction_Number is null and Is_Posted=0
						delete from Assy_Passed_Items_At_FV  where Kanban_Id=@Bin_Id
						update Assy_RunningKanban set Isrunning='0',Iscompleted='1',PostedDatecode=@ReturnValue where Isrunning=1 and PartNo = @PartNumber
						AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode and kanbanid=@Bin_Id
					end
					else
					begin
						update Assy_RunningKanban set Isrunning='1' where kanbanid=@Bin_Id and isnull(IsCompleted,0) <> '1'
						SELECT @ReturnInt = 1 , @returnValue ='Success' 
					end
				end
				else
				begin
					if exists(select top 1 1 from Assy_RunningKanban with(nolock) where Isrunning=1 
					AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode and isnull(IsCompleted,0) <> '1' 
					and PostedDatecode is null and kanbanid=@Bin_Id)
					Begin
						update Assy_Passed_Items_At_FV set Transaction_Number ='Ekanban',Is_Posted=1 where Kanban_Id=@Bin_Id
						and Transaction_Number is null and Is_Posted=0
						delete from Assy_Passed_Items_At_FV  where Kanban_Id=@Bin_Id
						update Assy_RunningKanban set Isrunning='0',Iscompleted='1',PostedDatecode=@ReturnValue where Isrunning=1 
						AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode and kanbanid=@Bin_Id
					end
					else
					begin
						update Assy_RunningKanban set Isrunning='1' where kanbanid=@Bin_Id and isnull(IsCompleted,0) <> '1'
						SELECT @ReturnInt = 1 , @returnValue ='Success' 
					end
				end
		END
		ELSE IF @Condition = 'Get_EKanban_Data'
		BEGIN 
				SELECT top 1 isnull(PartNo,'') as 'PartNo',Isnull(KanbanId,'') as 'KanbanId',
				Isnull(ProductionOrderNo,'') as 'ProductionOrderNo'
				FROM Assy_runningkanban WITH (NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode 
				and KanbanId=@EKanban_Id
		END 
	END TRY

	BEGIN CATCH 
		SET @ReturnValue =  CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
		CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
		CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_MESSAGE() AS VARCHAR(1500)) 
		ROLLBACK TRAN 
		SET @ReturnInt = 2 
		RAISERROR(@ReturnValue,16,1) 
	END CATCH 
END


GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_ProductionOrder]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
CREATE PROC [dbo].[Assy_Proc_ProductionOrder]
(
	@ParameterTable TBLSETPARAMETERS READONLY, 
	@ParameterTable_PC TBLSetParameters_PlungerCrimping READONLY, 
	@ChangeOverTable TBL_SETPARAMETERS_CHANGEOVERHISTORY READONLY, 
	@ProfitCenterCode VARCHAR(20) = NULL, 
	@LineCode VARCHAR(20) = NULL, 
	@StationCode VARCHAR(20) = NULL, 
	@ProdOrderNo VARCHAR(20) = NULL, 
	@DateCode VARCHAR(20) = NULL, 
	@ProdOrderDate VARCHAR(20) = NULL, 
	@PartNumber VARCHAR(20) = NULL, 
	@PlannedQty NUMERIC(15, 4) = 0, 
	@ProductionQty NUMERIC(15, 4) = 0, 
	@BalanceQty NUMERIC(15, 4) = 0, 
	@ProdOrderPriority INT = 0, 
	@Current_Planned_Qty NUMERIC(15, 4) = 0, 
	@Mode VARCHAR(20) = NULL, 
	@Remarks VARCHAR(100) = NULL, 
	@Status VARCHAR(20) = NULL, 
	@UserCode VARCHAR(20) = NULL, 
	@Condition VARCHAR(70), 
	@ReturnValue VARCHAR (2000) = NULL OUT, 
	@ReturnInt INT = NULL OUT, 
	@ProductionOrderNo VARCHAR(40) = NULL, 
	@CreatedDate DATETIME = NULL, 
	@CreatedBy VARCHAR(20) = NULL, 
	@ModifiedOn DATETIME = NULL, 
	@ModifiedBy VARCHAR(20) = NULL, 
	@ProducedQty NUMERIC(15, 4) = 0, 
	@BOMVersion INT = 1, 
	@CustomerPartNumber VARCHAR(60) = NULL,
	@RealTimeDateCode char(4)=NULL,
	@RealTimeRunningPartNo VARCHAR(20) = NULL,
	@Allow2Parts bit=0,
	@IsAppStart bit=0,
	@ISALLOWIMPORTEDBARCODE BIT = 0, -- added by sachin 20170914
	@PartCategory VARCHAR(10) = NULL, -- added by Rashid 20190509
	@P_KanbanId varchar(100) = '' -- added by sachin 2020June03
)
As 
BEGIN
	/****************************************************
	Author:			<RAVISHANKAR MISHRA>
	Create Date:	<30 JULY 2014>
	Description:	<PRODUCTION Order AND THE PARAMETER VALUES SETTINGS...>

	Modified By	:	Rashid Siddiqui
	Modified ON	:	27-Sep-2016 
	Description :	Tally Chart Routing Previous.
	Description :	IF Poka Yoke IS Bypassed for a particular part no., it will not UnBypass Poka Yoke for same part no AND DateCode.
	Description :	9 CHAR Part Allow	
	
	Modified By :	Sachin
	Modified ON	:	20-01-2017 
	Description :	in jaghadia Plant, We have found a part 29032341FI having length 10 to get Order ON screen we increase length.
	
	Modified By :	RAVISHANKAR MISHRA
	Modified ON	:	21-03-2017
	Description :	Added By Ravi to get all lengths part no. except the character that has been defined in Line Master Filed Name-ExceptChars AND has removed length checking Condition. 

	Modified By :	Rashid Siddiqui
	Modified ON	:	20170511
	Description :	Added New Block For 2 Parts (Family Concept) - CheckTwoPartSetParameter

	Modified By :	Ravishankar Mishra
	Modified ON	:	13-08-2017
	Description :	Added New Block For 2 Parts (Family Concept) - Reset_PokaYoke_After_Change_Over
	Modified ON	:	07-09-2017
	Description :	Done changes in 'Reset_PokaYoke_After_Change_Over' block to copy Poka Yoke data into central server after shift is changed.
	Modified By :	Rashid Siddiqui
	Modified ON	:	20180720
	Description :	For TMC Part Cap Color | 0-Default,1-NoColor,2-Black,3-Yellow
	EXEC Assy_Proc_ProductionOrder @Condition = 'READ_RUNNING_PART_DETAILS_FROM_MAINSERVER', @LineCode = 'M03', @UserCode = 'ravi', @ProfitCenterCode = '0021'
		
	EXEC Assy_Proc_ProductionOrder @Condition = 'DELTE_CURRENT_RUNNING_PATR_FROM_MAIN_SERVER', @LineCode = 'M07', @ProductionOrderNo = 'PO-050515', @ProfitCenterCode = '0021'
	EXEC Assy_Proc_ProductionOrder @Condition = 'SEARCH', @PartNumber = '29066835', @ProdOrderNo = '', @LineCode = 'M07', @UserCode = 'ravi', @ProfitCenterCode = '0021'
	EXEC Assy_Proc_ProductionOrder @Condition = 'Search_PlungerCrimping', @PartNumber = '29066278', @LineCode = 'M03', @UserCode = 'ravi', @ProfitCenterCode = '0021'		
	EXEC Assy_Proc_ProductionOrder @Condition = 'GET_PRODUCTION_ORDERS_PLUNGER_CRIMPING', @LineCode = 'M03', @ProfitCenterCode = '0021'
	EXEC Assy_Proc_ProductionOrder @Condition = 'CheckTwoPartSetParameter', @LineCode = 'J04', @ProfitCenterCode = '0088', @PartNumber = '29324509'
		
	Declare @ReturnValueData VARCHAR (2000) = NULL 
	Declare @ReturnIntData INT 
	EXEC Assy_Proc_ProductionOrder @Condition = 'DO_POKAYOKE', @LineCode = 'M07', @ProfitCenterCode = '0021', @ReturnValue = @ReturnValueData OUT, @ReturnInt = @ReturnIntData OUT
	SELECT @ReturnValueData, @ReturnIntData	
	exec Assy_Proc_ProductionOrder @Condition ='Reset_PokaYoke_After_Change_Over',@ProfitCenterCode='0088'
	,@LineCode ='j05' ,@RealTimeDateCode ='',@RealTimeRunningPartNo='30Dd',@Allow2Parts=1

	
	declare @ParameterTable TBLSETPARAMETERS 

	insert into @ParameterTable values ('0064','C13','','09Yf','ORDXYZ','',
	'29032640/D','400','200','0','0','200','0','0','0','0',GETDATE())

	declare @p4 varchar(2000)
	set @p4=NULL
	declare @p5 int
	set @p5=NULL
	exec ASSY_PROC_PRODUCTIONORDER @PROFITCENTERCODE=N'0064',@PARTNUMBER=N'29032640/D',@LINECODE='C13',@ISALLOWIMPORTEDBARCODE=0,
	@condition=N'SAVE',@Allow2Parts=0,@ParameterTable=@ParameterTable,
	@ReturnValue=@p4 output,@ReturnInt=@p5 output
	select @p4, @p5

	******************************************************/
	SET NOCOUNT ON;
	SET DATEFORMAT DMY
	Declare @GroupCode VARCHAR(10), @LstRunningPartNo VARCHAR(60), @LstRunningDateCode CHAR(4), @CurRunningPartNo VARCHAR(60), @CurRunningDateCode CHAR(4), @IsPokaYokeAlreadyBypassedForThisPart BIT = 0

	--Added By Ravi to get all lengths part no. except the character that has been defined IN Line Master
	--Filed Name-ExceptChars AND has removed length checking Condition. 
	Declare @ExceptChars As VARCHAR(20), @NewPart_Family_Group_Code VARCHAR(10) = '', @OldPart_Family_Group_Code VARCHAR(10) = '', @CapColor CHAR(1) = ''
	, @MachineLinkServerName varchar(100) -- ADDED BY SACHIN 20190501
	, @MachineLinkServerDB varchar(100) -- ADDED BY SACHIN 20190501
	, @MachineLinkServer varchar(300) -- ADDED BY SACHIN 20190501
	, @MachineDBTableName varchar(100) -- ADDED BY SACHIN 20190501
	,@RunPartNoWithPrefix VARCHAR(60) = ''
	,@LinkServerType VARCHAR(60) = ''
	,@HandInfo VARCHAR(10) = '' -- ADDED BY SACHIN 20190306

	declare @Target int=0
	--Added By Rashid ON 19th Aug 2016 For K Part
	--Declare @9CharPartAllow BIT = 0

	--SELECT @9CharPartAllow = ISNULL(Parameter_Value, 0) FROM PARAMETER_MST WITH (NOLOCK) 
	--	WHERE wh_code = @ProfitCenterCode AND PARAMETER_C1 = 'Production_Order' AND PARAMETER_C2 = 'K_Part'

	--IF ISNULL(@9CharPartAllow, 0) = 0
	--	SET @9CharPartAllow = 0

	IF @Condition = 'DYNAMIC_HEADER_SETTING'
	BEGIN
		Declare @Parameter_Value VARCHAR(100) = NULL, @Operation_Name VARCHAR(500) = NULL, @Line_Type VARCHAR(50) = NULL

		--SET @Parameter_Value = (SELECT Parameter_Value FROM parameter_mst WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'SET_PARAMETER' AND PARAMETER_C2 = 'Activity_Other_Than_Production' AND wh_code = @ProfitCenterCode)
		SELECT @Parameter_Value = dbo.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'SET_PARAMETER', 'Activity_Other_Than_Production', @ProfitCenterCode)
		--SET @Operation_Name = (SELECT OperationName FROM OperationMst (NOLOCK) WHERE OperationCode = @Parameter_Value)
		SELECT @Operation_Name = OperationName FROM OperationMst WITH (NOLOCK) WHERE OperationCode = @Parameter_Value

		--SET @Line_Type = (SELECT LTM.LineTypeName FROM LineMst (NOLOCK) LM INNER JOIN LineTypeMst (NOLOCK) LTM ON LM.LineTypeCode = LTM.LineTypeCode WHERE LM.LineCode = @LineCode)
		SELECT @Line_Type = LTM.LineTypeName FROM LineMst (NOLOCK) LM INNER JOIN LineTypeMst (NOLOCK) LTM ON LM.LineTypeCode = LTM.LineTypeCode WHERE LM.LineCode = @LineCode AND LM.ProfitCenterCode = @ProfitCenterCode

		SELECT @Operation_Name + '-' + @Line_Type
		RETURN
	END

	ELSE IF @Condition = 'VALIDATE_FOR_WHICH_LINE_PC_IS_ON_OR_OFF'
	BEGIN
		Declare @Parameter_Val VARCHAR(100) = NULL, @Operation_Req VARCHAR(50) = NULL

		--SET @Parameter_Val = (SELECT Parameter_Value FROM parameter_mst WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'SET_PARAMETER' AND PARAMETER_C2 = 'Activity_Other_Than_Production' AND wh_code = @ProfitCenterCode)
		SELECT @Parameter_Val = dbo.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'SET_PARAMETER', 'Activity_Other_Than_Production', @ProfitCenterCode)
		--SET @Operation_Req = (SELECT DISTINCT L.OperationRequired FROM RoutingConfigLineWise (NOLOCK) L WHERE L.LineCode = @LineCode AND L.ProfitCenterCode = @ProfitCenterCode AND OperationCode = @Parameter_Val)
		SELECT DISTINCT @Operation_Req = L.OperationRequired FROM RoutingConfigLineWise (NOLOCK) L WHERE L.LineCode = @LineCode AND L.ProfitCenterCode = @ProfitCenterCode AND OperationCode = @Parameter_Val

		SELECT ISNULL(@Operation_Req, 0) [Operation_Req]
		RETURN
	END

	ELSE IF @Condition = 'GET_PRODUCTION_ORDERS_PLUNGER_CRIMPING'
	BEGIN				
		--Added By Ravi ON 21-03-17 ExceptChars
		SELECT @ExceptChars = ISNULL(ExceptChars, '') FROM dbo.LineMst WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
		SELECT @GroupCode = GroupCode FROM Assy_LineGroup_Master WITH (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
	
		SELECT ProfitCenterCode, ProdOrderNo, CONVERT(VARCHAR, ProdOrderDate, 105)ProdOrderDate, PlannedQty, PartNumber, ISNULL(SUM(CurrentPlannedQty), 0) CurrentPlannedQty
		INTO #temp1_RunningPart_PC
		FROM Assy_ProductionOrder_ParameterSetting_PlungerCrimping (NOLOCK) WHERE LineCode
		in
		(
			SELECT LineCode FROM Assy_LineGroup_Master WITH (NOLOCK) WHERE GroupCode = @GroupCode AND isActive = 1 AND ProfitCenterCode = @ProfitCenterCode
		)
		AND ProfitCenterCode = @ProfitCenterCode
		Group By ProfitCenterCode, ProdOrderNo, PlannedQty, PartNumber, ProdOrderNo, CONVERT(VARCHAR, ProdOrderDate, 105)

		IF not EXISTS(SELECT 1 FROM Assy_RunningPart_PlungerCrimping (NOLOCK) WHERE LineCode = @LineCode)
		BEGIN
			SELECT '0' As Chk, PO.ORDERNO [PRODUCTION Order], PO.OrderDate [Date], RTRIM(LTRIM(PO.PartNo)) [PART NUMBER], 
			CONVERT(INT, ISNULL(PO.QTY, 0)) [PLANNED QTY], CONVERT(INT, ISNULL(PO.ProducedQty, 0)) [PROD. QTY], 
			CONVERT(INT, ISNULL(PO.BalanceQty, 0)) [BALANCE QTY], 
			CONVERT(INT, ISNULL(AssyProd.CurrentPlannedQty, 0)) [CURRENT PLANNED QTY], 
			CASE WHEN AssyProd.ProdOrderPriority IS NULL THEN ISNULL(PO.PRIORITY, ROW_NUMBER() OVER(Order By PO.ENT_STAMP)) 
			ELSE ISNULL(AssyProd.ProdOrderPriority, 0) END As [PRIORITY], 	
			ISNULL(AssyProd.Mode, '') As Mode, ISNULL(AssyProd.Remarks, '') Remarks, PO.Status
			Status INTO #Temp_POData_PC
			FROM Assy_ProductionOrderMst (NOLOCK) PO
			LEFT OUTER JOIN Assy_ProductionOrder_ParameterSetting_PlungerCrimping (NOLOCK) AssyProd
			ON PO.ORDERNO = AssyProd.ProdOrderNo AND PO.PartNo = AssyProd.PartNumber 
			AND PO.ProfitCenterCode = AssyProd.ProfitCenterCode 
			AND AssyProd.LineCode 
			in
			(
				SELECT L.LineCode FROM LineMst (NOLOCK) L 
				INNER JOIN Assy_LineGroup_Master (NOLOCK) LG ON L.ProfitCenterCode = LG.ProfitCenterCode AND L.LineCode = LG.LineCode
				WHERE LG.GroupCode = @GroupCode AND L.isActive = 1 AND LG.ProfitCenterCode = @ProfitCenterCode
			) 
			WHERE ISNULL(PO.Status, '0') <> '100' AND PO.ProfitCenterCode = @ProfitCenterCode AND PO.isActive = 1
			AND PO.WorkCenterCode 
			in
			( 
				SELECT WorkCenterCode FROM LineMst (NOLOCK) L 
				INNER JOIN Assy_LineGroup_Master (NOLOCK) LG ON L.ProfitCenterCode = LG.ProfitCenterCode AND L.LineCode = LG.LineCode
				WHERE LG.GroupCode = @GroupCode AND L.isActive = 1 AND LG.ProfitCenterCode = @ProfitCenterCode
			)
			AND CONVERT(Date, OrderDate) < = (SELECT dbo.Assy_FN_Get_ShiftWise_Date(@ProfitCenterCode))
							
			--UPDATE current planned qty FROM Assy_ProductionOrder_ParameterSetting_PlungerCrimping Table
			UPDATE POT SET POT.[balance qty] = POT.[balance qty]-ISNULL(CRP.CurrentPlannedQty, 0) FROM #Temp_POData_PC (NOLOCK) POT 
			LEFT OUTER JOIN #temp1_RunningPart_PC (NOLOCK) CRP
