CREATE PROC [dbo].[Assy_Proc_ProductionOrder_BIJ]
(
	@ParameterTable TBLSETPARAMETERS READONLY, 
	@ParameterTable_PC TBLSetParameters_PlungerCrimping READONLY, 
	@ChangeOverTable TBL_SETPARAMETERS_CHANGEOVERHISTORY READONLY, 
	@ProfitCenterCode VARCHAR(20) = NULL, 
	@LineCode VARCHAR(20) = NULL, 
	@StationCode VARCHAR(20) = NULL, 
	@ProdOrderNo VARCHAR(20) = NULL, 
	@DateCode VARCHAR(20) = NULL, 
	@ProdOrderDate VARCHAR(20) = NULL, 
	@PartNumber VARCHAR(20) = NULL, 
	@PlannedQty NUMERIC(15, 4) = 0, 
	@ProductionQty NUMERIC(15, 4) = 0, 
	@BalanceQty NUMERIC(15, 4) = 0, 
	@ProdOrderPriority INT = 0, 
	@Current_Planned_Qty NUMERIC(15, 4) = 0, 
	@Mode VARCHAR(20) = NULL, 
	@Remarks VARCHAR(100) = NULL, 
	@Status VARCHAR(20) = NULL, 
	@UserCode VARCHAR(20) = NULL, 
	@Condition VARCHAR(70), 
	@ReturnValue VARCHAR (2000) = NULL OUT, 
	@ReturnInt INT = NULL OUT, 
	@ProductionOrderNo VARCHAR(40) = NULL, 
	@CreatedDate DATETIME = NULL, 
	@CreatedBy VARCHAR(20) = NULL, 
	@ModifiedOn DATETIME = NULL, 
	@ModifiedBy VARCHAR(20) = NULL, 
	@ProducedQty NUMERIC(15, 4) = 0, 
	@BOMVersion INT = 1, 
	@CustomerPartNumber VARCHAR(60) = NULL,
	@RealTimeDateCode char(4)=NULL,
	@RealTimeRunningPartNo VARCHAR(20) = NULL,
	@Allow2Parts bit=0,
	@IsAppStart bit=0,
	@ISALLOWIMPORTEDBARCODE BIT = 0, -- added by sachin 20170914
	@P_KanbanId varchar(100) = '' -- added by sachin 2020June03
)
As 
BEGIN
	/****************************************************
	Author:			<RAVISHANKAR MISHRA>
	Create Date:	<30 JULY 2014>
	Description:	<PRODUCTION Order AND THE PARAMETER VALUES SETTINGS...>

	Modified By	:	Rashid Siddiqui
	Modified ON	:	27-Sep-2016 
	Description :	Tally Chart Routing Previous.
	Description :	IF Poka Yoke IS Bypassed for a particular part no., it will NOT UnBypass Poka Yoke for same part no AND DateCode.
	Description :	9 CHAR Part Allow	
	
	Modified By :	Sachin
	Modified ON	:	20-01-2017 
	Description :	IN jaghadia Plant, We have found a part 29032341FI having length 10 to get Order ON screen we increase length.
	
	Modified By :	RAVISHANKAR MISHRA
	Modified ON	:	21-03-2017
	Description :	Added By Ravi to get all lengths part no. except the character that has been defined IN Line Master Filed Name-ExceptChars AND has removed length checking Condition.

	Modified By :	Rashid Siddiqui
	Modified ON	:	20170511
	Description :	Added New Block For 2 Parts (Family Concept) - CheckTwoPartSetParameter

	Modified By :	Ravishankar Mishra
	Modified ON	:	13-08-2017
	Description :	Added New Block For 2 Parts (Family Concept) - Reset_PokaYoke_After_Change_Over
	Modified ON	:	07-09-2017
	Description :	Done changes in 'Reset_PokaYoke_After_Change_Over' block to copy Poka Yoke data into central server after shift is changed.
	
	EXEC Assy_Proc_ProductionOrder @Condition = 'READ_RUNNING_PART_DETAILS_FROM_MAINSERVER', @LineCode = 'j05', @UserCode = 'ravi', @ProfitCenterCode = '0088'
		
	EXEC Assy_Proc_ProductionOrder @Condition = 'DELTE_CURRENT_RUNNING_PATR_FROM_MAIN_SERVER', @LineCode = 'M07', @ProductionOrderNo = 'PO-050515', @ProfitCenterCode = '0021'
	EXEC Assy_Proc_ProductionOrder @Condition = 'SEARCH', @PartNumber = '29066835', @ProdOrderNo = '', @LineCode = 'M07', @UserCode = 'ravi', @ProfitCenterCode = '0021'
	EXEC Assy_Proc_ProductionOrder @Condition = 'Search_PlungerCrimping', @PartNumber = '29066278', @LineCode = 'M03', @UserCode = 'ravi', @ProfitCenterCode = '0021'		
	EXEC Assy_Proc_ProductionOrder @Condition = 'GET_PRODUCTION_ORDERS_PLUNGER_CRIMPING', @LineCode = 'M03', @ProfitCenterCode = '0021'
	EXEC Assy_Proc_ProductionOrder @Condition = 'CheckTwoPartSetParameter', @LineCode = 'J04', @ProfitCenterCode = '0088', @PartNumber = '29324509'
		
	Declare @ReturnValueData VARCHAR (2000) = NULL 
	Declare @ReturnIntData INT 
	EXEC Assy_Proc_ProductionOrder @Condition = 'DO_POKAYOKE', @LineCode = 'M07', @ProfitCenterCode = '0021', @ReturnValue = @ReturnValueData OUT, @ReturnInt = @ReturnIntData OUT
	SELECT @ReturnValueData, @ReturnIntData	

	exec Assy_Proc_ProductionOrder @Condition ='Reset_PokaYoke_After_Change_Over',@ProfitCenterCode='0088'
	,@LineCode ='j05' ,@RealTimeDateCode ='',@RealTimeRunningPartNo='30Dd',@Allow2Parts=1

	
	declare @ParameterTable TBLSETPARAMETERS 

	insert into @ParameterTable values ('0064','C13','','09Yf','ORDXYZ','',
	'29032640/D','400','200','0','0','200','0','0','0','0',GETDATE())

	declare @p4 varchar(2000)
	set @p4=NULL
	declare @p5 int
	set @p5=NULL
	exec ASSY_PROC_PRODUCTIONORDER @PROFITCENTERCODE=N'0064',@PARTNUMBER=N'29032640/D',@LINECODE='C13',@ISALLOWIMPORTEDBARCODE=0,
	@condition=N'SAVE',@Allow2Parts=0,@ParameterTable=@ParameterTable,
	@ReturnValue=@p4 output,@ReturnInt=@p5 output
	select @p4, @p5

	******************************************************/
	SET NOCOUNT ON;
	SET DATEFORMAT DMY
	Declare @GroupCode VARCHAR(10), @LstRunningPartNo VARCHAR(60), @LstRunningDateCode CHAR(4), @CurRunningPartNo VARCHAR(60), @CurRunningDateCode CHAR(4), @IsPokaYokeAlreadyBypassedForThisPart BIT = 0

	--Added By Ravi to get all lengths part no. except the character that has been defined IN Line Master
	--Filed Name-ExceptChars AND has removed length checking Condition. 
	Declare @ExceptChars As VARCHAR(20), @NewPart_Family_Group_Code VARCHAR(10) = '', @OldPart_Family_Group_Code VARCHAR(10) = '', @CapColor CHAR(1) = ''
	, @MachineLinkServerName varchar(100) -- ADDED BY SACHIN 20190501
	, @MachineLinkServerDB varchar(100) -- ADDED BY SACHIN 20190501
	, @MachineLinkServer varchar(300) -- ADDED BY SACHIN 20190501
	, @MachineDBTableName varchar(100) -- ADDED BY SACHIN 20190501
	,@RunPartNoWithPrefix VARCHAR(60) = ''
	,@LinkServerType VARCHAR(60) = ''
	,@HandInfo VARCHAR(10) = '' -- ADDED BY SACHIN 20190306

	declare @Target int=0
	--Added By Rashid ON 19th Aug 2016 For K Part
	--Declare @9CharPartAllow BIT = 0

	--SELECT @9CharPartAllow = ISNULL(Parameter_Value, 0) FROM PARAMETER_MST WITH (NOLOCK) 
	--	WHERE wh_code = @ProfitCenterCode AND PARAMETER_C1 = 'Production_Order' AND PARAMETER_C2 = 'K_Part'

	--IF ISNULL(@9CharPartAllow, 0) = 0
	--	SET @9CharPartAllow = 0

	IF @Condition = 'DYNAMIC_HEADER_SETTING'
	BEGIN
		Declare @Parameter_Value VARCHAR(100) = NULL, @Operation_Name VARCHAR(500) = NULL, @Line_Type VARCHAR(50) = NULL

		--SET @Parameter_Value = (SELECT Parameter_Value FROM parameter_mst WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'SET_PARAMETER' AND PARAMETER_C2 = 'Activity_Other_Than_Production' AND wh_code = @ProfitCenterCode)
		SELECT @Parameter_Value = dbo.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'SET_PARAMETER', 'Activity_Other_Than_Production', @ProfitCenterCode)
		--SET @Operation_Name = (SELECT OperationName FROM OperationMst (NOLOCK) WHERE OperationCode = @Parameter_Value)
		SELECT @Operation_Name = OperationName FROM OperationMst WITH (NOLOCK) WHERE OperationCode = @Parameter_Value

		--SET @Line_Type = (SELECT LTM.LineTypeName FROM LineMst (NOLOCK) LM INNER JOIN LineTypeMst (NOLOCK) LTM ON LM.LineTypeCode = LTM.LineTypeCode WHERE LM.LineCode = @LineCode)
		SELECT @Line_Type = LTM.LineTypeName FROM LineMst (NOLOCK) LM INNER JOIN LineTypeMst (NOLOCK) LTM ON LM.LineTypeCode = LTM.LineTypeCode WHERE LM.LineCode = @LineCode AND LM.ProfitCenterCode = @ProfitCenterCode

		SELECT @Operation_Name + '-' + @Line_Type
		RETURN
	END

	ELSE IF @Condition = 'VALIDATE_FOR_WHICH_LINE_PC_IS_ON_OR_OFF'
	BEGIN
		Declare @Parameter_Val VARCHAR(100) = NULL, @Operation_Req VARCHAR(50) = NULL

		--SET @Parameter_Val = (SELECT Parameter_Value FROM parameter_mst WHERE PARAMETER_C = 'ASSLINE' AND PARAMETER_C1 = 'SET_PARAMETER' AND PARAMETER_C2 = 'Activity_Other_Than_Production' AND wh_code = @ProfitCenterCode)
		SELECT @Parameter_Val = dbo.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'SET_PARAMETER', 'Activity_Other_Than_Production', @ProfitCenterCode)
		--SET @Operation_Req = (SELECT DISTINCT L.OperationRequired FROM RoutingConfigLineWise (NOLOCK) L WHERE L.LineCode = @LineCode AND L.ProfitCenterCode = @ProfitCenterCode AND OperationCode = @Parameter_Val)
		SELECT DISTINCT @Operation_Req = L.OperationRequired FROM RoutingConfigLineWise (NOLOCK) L WHERE L.LineCode = @LineCode AND L.ProfitCenterCode = @ProfitCenterCode AND OperationCode = @Parameter_Val

		SELECT ISNULL(@Operation_Req, 0) [Operation_Req]
		RETURN
	END

	ELSE IF @Condition = 'GET_PRODUCTION_ORDERS_PLUNGER_CRIMPING'
	BEGIN				
		--Added By Ravi ON 21-03-17 ExceptChars
		SELECT @ExceptChars = ISNULL(ExceptChars, '') FROM dbo.LineMst WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
		SELECT @GroupCode = GroupCode FROM Assy_LineGroup_Master WITH (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
	
		SELECT ProfitCenterCode, ProdOrderNo, CONVERT(VARCHAR, ProdOrderDate, 105)ProdOrderDate, PlannedQty, PartNumber, ISNULL(SUM(CurrentPlannedQty), 0) CurrentPlannedQty
		INTO #temp1_RunningPart_PC
		FROM Assy_ProductionOrder_ParameterSetting_PlungerCrimping (NOLOCK) WHERE LineCode
		IN
		(
			SELECT LineCode FROM Assy_LineGroup_Master WITH (NOLOCK) WHERE GroupCode = @GroupCode AND isActive = 1 AND ProfitCenterCode = @ProfitCenterCode
		)
		AND ProfitCenterCode = @ProfitCenterCode
		Group By ProfitCenterCode, ProdOrderNo, PlannedQty, PartNumber, ProdOrderNo, CONVERT(VARCHAR, ProdOrderDate, 105)

		IF NOT EXISTS(SELECT 1 FROM Assy_RunningPart_PlungerCrimping (NOLOCK) WHERE LineCode = @LineCode)
		BEGIN
			SELECT '0' As Chk, PO.ORDERNO [PRODUCTION Order], PO.OrderDate [Date], RTRIM(LTRIM(PO.PartNo)) [PART NUMBER], 
			CONVERT(INT, ISNULL(PO.QTY, 0)) [PLANNED QTY], CONVERT(INT, ISNULL(PO.ProducedQty, 0)) [PROD. QTY], 
			CONVERT(INT, ISNULL(PO.BalanceQty, 0)) [BALANCE QTY], 
			CONVERT(INT, ISNULL(AssyProd.CurrentPlannedQty, 0)) [CURRENT PLANNED QTY], 
			CASE WHEN AssyProd.ProdOrderPriority IS NULL THEN ISNULL(PO.PRIORITY, ROW_NUMBER() OVER(Order By PO.ENT_STAMP)) 
			ELSE ISNULL(AssyProd.ProdOrderPriority, 0) END As [PRIORITY], 	
			ISNULL(AssyProd.Mode, '') As Mode, ISNULL(AssyProd.Remarks, '') Remarks, PO.Status
			Status INTO #Temp_POData_PC
			FROM Assy_ProductionOrderMst (NOLOCK) PO
			LEFT OUTER JOIN Assy_ProductionOrder_ParameterSetting_PlungerCrimping (NOLOCK) AssyProd
			ON PO.ORDERNO = AssyProd.ProdOrderNo AND PO.PartNo = AssyProd.PartNumber 
			AND PO.ProfitCenterCode = AssyProd.ProfitCenterCode 
			AND AssyProd.LineCode 
			IN
			(
				SELECT L.LineCode FROM LineMst (NOLOCK) L 
				INNER JOIN Assy_LineGroup_Master (NOLOCK) LG ON L.ProfitCenterCode = LG.ProfitCenterCode AND L.LineCode = LG.LineCode
				WHERE LG.GroupCode = @GroupCode AND L.isActive = 1 AND LG.ProfitCenterCode = @ProfitCenterCode
			) 
			WHERE ISNULL(PO.Status, '0') <> '100' AND PO.ProfitCenterCode = @ProfitCenterCode AND PO.isActive = 1
			AND PO.WorkCenterCode 
			IN
			( 
				SELECT WorkCenterCode FROM LineMst (NOLOCK) L 
				INNER JOIN Assy_LineGroup_Master (NOLOCK) LG ON L.ProfitCenterCode = LG.ProfitCenterCode AND L.LineCode = LG.LineCode
				WHERE LG.GroupCode = @GroupCode AND L.isActive = 1 AND LG.ProfitCenterCode = @ProfitCenterCode
			)
			AND CONVERT(Date, OrderDate) < = (SELECT dbo.Assy_FN_Get_ShiftWise_Date(@ProfitCenterCode))
							
			--UPDATE current planned qty FROM Assy_ProductionOrder_ParameterSetting_PlungerCrimping Table
			UPDATE POT SET POT.[balance qty] = POT.[balance qty]-ISNULL(CRP.CurrentPlannedQty, 0) FROM #Temp_POData_PC (NOLOCK) POT 
			LEFT OUTER JOIN #temp1_RunningPart_PC (NOLOCK) CRP
			ON POT.[production Order] = CRP.ProdOrderNo AND CONVERT(VARCHAR, POT.Date, 105) = CRP.ProdOrderDate AND POT.[PART NUMBER] = CRP.PartNumber 
			AND POT.[PLANNED QTY] = CRP.PlannedQty 
								
			--Added By Ravi ON 21-03-17
			IF LEN(@ExceptChars) > 0
			BEGIN
				SELECT @ExceptChars = '[^'+REPLACE(@ExceptChars, ', ', '')+']%'
				SELECT chk, [production Order], CONVERT(VARCHAR, Date, 105)[DATE1], [part number], [planned qty], [PROD. Qty], [balance qty]
				, [CURRENT PLANNED QTY] 
				, PRIORITY, Mode, Remarks, Status, ROW_NUMBER() OVER(Order By CONVERT(DATETIME, [Date])) FROM #Temp_POData_PC (NOLOCK) WHERE [balance qty] > 0
				AND [part number] like @ExceptChars
				Group By chk, [production Order], Date, [part number], [planned qty], [PROD. Qty], [balance qty], [CURRENT PLANNED QTY], PRIORITY, Mode, Remarks, Status
				Order By [part number], [Date]
			END
			ELSE
			BEGIN
				SELECT chk, [production Order], CONVERT(VARCHAR, Date, 105)[DATE1], [part number], [planned qty], [PROD. Qty], [balance qty]
				, [CURRENT PLANNED QTY] 
				, PRIORITY, Mode, Remarks, Status, ROW_NUMBER() OVER(Order By CONVERT(DATETIME, [Date])) FROM #Temp_POData_PC (NOLOCK) WHERE [balance qty] > 0
				Group By chk, [production Order], Date, [part number], [planned qty], [PROD. Qty], [balance qty], [CURRENT PLANNED QTY], PRIORITY, Mode, Remarks, Status
				Order By [part number], [Date]
			END
		END
		ELSE
		BEGIN
			SELECT CASE WHEN AssyProd.ProdOrderPriority IS NULL THEN 0 ELSE 1 END As CHK, 
			ORDERNO [PRODUCTION Order], PO.OrderDate [Date], RTRIM(LTRIM(PartNo)) [PART NUMBER], 
			CONVERT(INT, ISNULL(QTY, 0)) [PLANNED QTY], CONVERT(INT, ISNULL(PO .ProducedQty, 0)) [PROD. QTY], 
			CONVERT(INT, ISNULL(PO .BalanceQty, 0)) [BALANCE QTY], 
			CASE WHEN AssyProd.CurrentPlannedQty IS NULL THEN CONVERT(INT, ISNULL(PO .BalanceQty, 0)) ELSE 
			CONVERT(INT, ISNULL(AssyProd.CurrentPlannedQty, 0)) END As [CURRENT PLANNED QTY], 
			CASE WHEN AssyProd.ProdOrderPriority IS NULL THEN ISNULL(PO .PRIORITY, ROW_NUMBER() OVER(Order By PO.ENT_STAMP)) ELSE 
			ISNULL(AssyProd.ProdOrderPriority, 0) END As [PRIORITY], 	
			ISNULL(AssyProd.Mode, '') As Mode, ISNULL(AssyProd.Remarks, '') Remarks, PO .Status Status, 
			CASE WHEN AssyProd.ProdOrderPriority IS NULL THEN 1 ELSE 0 END As NEWPRIORITY INTO #Temp_POData_WithRecord_PC
			FROM Assy_ProductionOrderMst (NOLOCK) PO 				
			LEFT OUTER JOIN Assy_ProductionOrder_ParameterSetting_PlungerCrimping (NOLOCK) AssyProd 
			ON PO .ORDERNO = AssyProd.ProdOrderNo AND PO .PartNo = AssyProd.PartNumber AND PO.ProfitCenterCode = AssyProd.ProfitCenterCode 
			AND AssyProd.LineCode = @LineCode							 
			WHERE ISNULL(PO.Status, '0')<>'100' AND PO.ProfitCenterCode = @ProfitCenterCode AND PO.isActive = 1
			AND PO.WorkCenterCode 
			IN
			( 
				SELECT WorkCenterCode FROM LineMst (NOLOCK) L 
				INNER JOIN Assy_LineGroup_Master (NOLOCK) LG ON L.ProfitCenterCode = LG.ProfitCenterCode AND L.LineCode = LG.LineCode
				WHERE LG.GroupCode = @GroupCode AND L.isActive = 1 AND LG.ProfitCenterCode = @ProfitCenterCode
			)
			AND CONVERT(Date, PO.OrderDate) < = (SELECT dbo.Assy_FN_Get_ShiftWise_Date(@ProfitCenterCode))

			--UPDATE current planned qty FROM Assy_ProductionOrder_ParameterSetting_PlungerCrimping Table
			UPDATE POT SET POT.[balance qty] = POT.[balance qty]-ISNULL(CRP.CurrentPlannedQty, 0) FROM #Temp_POData_WithRecord_PC (NOLOCK) POT 
			LEFT OUTER JOIN #temp1_RunningPart_PC (NOLOCK) CRP
			ON POT.[production Order] = CRP.ProdOrderNo AND CONVERT(VARCHAR, POT.Date, 105) = CRP.ProdOrderDate AND POT.[PART NUMBER] = CRP.PartNumber 
			AND POT.[PLANNED QTY] = CRP.PlannedQty 
							
			--Added By Ravi ON 21-03-17
			IF LEN(@ExceptChars) > 0
			BEGIN
				SELECT @ExceptChars = '[^'+REPLACE(@ExceptChars, ', ', '')+']%'	
				SELECT chk, [production Order], CONVERT(VARCHAR, Date, 105)[DATE1], [part number], [planned qty], [PROD. Qty], [balance qty]
				, [CURRENT PLANNED QTY] 
				, PRIORITY, Mode, Remarks, Status, ROW_NUMBER() OVER(Order By CONVERT(DATETIME, [Date])) FROM #Temp_POData_WithRecord_PC (NOLOCK) WHERE [balance qty] > 0
				AND [part number] like @ExceptChars
				Group By chk, [production Order], Date, [part number], [planned qty], [PROD. Qty], [balance qty], [CURRENT PLANNED QTY], PRIORITY, Mode, Remarks, Status
				Order By [part number], [Date]
			END
			ELSE
			BEGIN										
				SELECT chk, [production Order], CONVERT(VARCHAR, Date, 105)[DATE1], [part number], [planned qty], [PROD. Qty], [balance qty]
				, [CURRENT PLANNED QTY] 
				, PRIORITY, Mode, Remarks, Status, ROW_NUMBER() OVER(Order By CONVERT(DATETIME, [Date])) FROM #Temp_POData_WithRecord_PC (NOLOCK) WHERE [balance qty] > 0
				Group By chk, [production Order], Date, [part number], [planned qty], [PROD. Qty], [balance qty], [CURRENT PLANNED QTY], PRIORITY, Mode, Remarks, Status
				Order By [part number], [Date]
			END
		END
			 
		IF OBJECT_ID('tempdb..#Temp_POData_PC') IS NOT NULL
			Drop Table #Temp_POData_PC
		IF OBJECT_ID('tempdb..#temp1_RunningPart_PC') IS NOT NULL
			Drop Table #temp1_RunningPart_PC						
		IF OBJECT_ID('tempdb..#Temp_POData_WithRecord_PC') IS NOT NULL
			Drop Table #Temp_POData_WithRecord_PC

		SELECT @ReturnValue = 'DATA SELECTED', @ReturnInt = 1
		RETURN
	END

	ELSE IF @Condition = 'SAVE_PC_IN_LOCAL_SERVER'
	BEGIN		 
		BEGIN TRY
			BEGIN TRAN
			Declare @PCOperationCode VARCHAR(20)
			SELECT Top 1 @ProdOrderNo = ProdOrderNo, @DateCode = DateCode, @LineCode = LineCode, @PartNumber = PartNumber, @UserCode = UserCode
			, @Current_Planned_Qty = Current_Planned_Qty, @ProfitCenterCode = ProfitCenterCode, @Mode = Mode FROM @ParameterTable_PC

			SELECT @PCOperationCode = DBO.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'SET_PARAMETER', 'ACTIVITY_OTHER_THAN_PRODUCTION', @ProfitCenterCode)

			DELETE FROM Assy_RunningPart_PlungerCrimping WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode					
			INSERT INTO Assy_RunningPart_PlungerCrimping(LineCode, DateCode, Assy_PartNo, ProductionOrderNo, Assy_Mode, 
			CreatedDate, CreatedBy, CurrentPlannedQty, ProfitCenterCode)
			SELECT @LineCode, @DateCode, @PartNumber, @ProdOrderNo, @Mode, GETDATE(), @UserCode, @Current_Planned_Qty, @ProfitCenterCode
										
			DELETE FROM Assy_ModelChanged WHERE LineCode = @LineCode AND OperationCode = @PCOperationCode
			INSERT INTO Assy_ModelChanged(OperationCode, IsChanged, LineCode) values(@PCOperationCode, 1, @LineCode)	
			
			SELECT @ReturnValue = 'DATA SAVED', @ReturnInt = 1
			COMMIT TRAN

		END TRY
		BEGIN CATCH
			--CATCH BLOCK BEGINS
			SET @RETURNVALUE =	CAST(ISNULL(ERROR_NUMBER(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_SEVERITY(),0)AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_STATE(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_PROCEDURE(),'') AS VARCHAR(200)) + '|' + 
								CAST(ISNULL(ERROR_LINE(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_MESSAGE(),'') AS VARCHAR(1500))
			SET @ReturnInt = 2
			ROLLBACK TRAN
			RAISERROR(@ReturnValue, 16, 1)
		END CATCH
		RETURN
	END

	ELSE IF @Condition = 'Search_PlungerCrimping'
	BEGIN
		--Added By Ravi ON 21-03-17
		SELECT @ExceptChars = ISNULL(ExceptChars, '') FROM dbo.LineMst WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
		SELECT @GroupCode = GroupCode FROM Assy_LineGroup_Master (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
		
		SELECT ProfitCenterCode, ProdOrderNo, CONVERT(VARCHAR, ProdOrderDate, 105)ProdOrderDate, PlannedQty, PartNumber
		, ISNULL(SUM(CurrentPlannedQty), 0)CurrentPlannedQty INTO #temp1_RunningPart_Search_PC
		FROM Assy_ProductionOrder_ParameterSetting_PlungerCrimping (NOLOCK) WHERE LineCode 
		IN
		(
			SELECT LineCode FROM Assy_LineGroup_Master WITH (NOLOCK) WHERE GroupCode = @GroupCode AND isActive = 1 AND ProfitCenterCode = @ProfitCenterCode
		)
		AND ProfitCenterCode = @ProfitCenterCode
		Group By ProfitCenterCode, ProdOrderNo, PlannedQty, PartNumber, ProdOrderNo, CONVERT(VARCHAR, ProdOrderDate, 105)

		IF NOT EXISTS(SELECT 1 FROM Assy_RunningPart_PlungerCrimping (NOLOCK) WHERE LineCode = @LineCode)
		BEGIN
			SELECT '0' As Chk, PO.ORDERNO [PRODUCTION Order], PO.OrderDate [Date], RTRIM(LTRIM(PO.PartNo)) [PART NUMBER], 
			CONVERT(INT, ISNULL(PO.QTY, 0)) [PLANNED QTY], CONVERT(INT, ISNULL(PO.ProducedQty, 0)) [PROD. QTY], 
			CONVERT(INT, ISNULL(PO.BalanceQty, 0)) [BALANCE QTY], 
			CONVERT(INT, ISNULL(AssyProd.CurrentPlannedQty, 0)) [CURRENT PLANNED QTY], 
			CASE WHEN AssyProd.ProdOrderPriority IS NULL THEN ISNULL(PO.PRIORITY, ROW_NUMBER() OVER(Order By PO.ENT_STAMP)) 
			ELSE ISNULL(AssyProd.ProdOrderPriority, 0) END As [PRIORITY], 	
			ISNULL(AssyProd.Mode, '') As Mode, ISNULL(AssyProd.Remarks, '') Remarks, PO.Status
			Status INTO #Temp_PODATa_Search_PC
			FROM Assy_ProductionOrderMst (NOLOCK) PO 
			LEFT OUTER JOIN Assy_ProductionOrder_ParameterSetting_PlungerCrimping (NOLOCK) AssyProd 
			ON PO.ORDERNO = AssyProd.ProdOrderNo AND PO.PartNo = AssyProd.PartNumber 
			AND PO.ProfitCenterCode = AssyProd.ProfitCenterCode 
			AND AssyProd.LineCode 
			IN
			(
				SELECT L.LineCode FROM LineMst (NOLOCK) L 
				INNER JOIN Assy_LineGroup_Master (NOLOCK) LG ON L.ProfitCenterCode = LG.ProfitCenterCode AND L.LineCode = LG.LineCode
				WHERE LG.GroupCode = @GroupCode AND L.isActive = 1 AND LG.ProfitCenterCode = @ProfitCenterCode
			) 
					
			WHERE ISNULL(PO.Status, '0') <> '100' AND PO.ProfitCenterCode = @ProfitCenterCode AND PO.isActive = 1
			AND PO.WorkCenterCode 
			IN
			( 
				SELECT WorkCenterCode FROM LineMst (NOLOCK) L 
				INNER JOIN Assy_LineGroup_Master (NOLOCK) LG ON L.ProfitCenterCode = LG.ProfitCenterCode AND L.LineCode = LG.LineCode
				WHERE LG.GroupCode = @GroupCode AND L.isActive = 1 AND LG.ProfitCenterCode = @ProfitCenterCode
			)
			AND CONVERT(Date, OrderDate) < = (SELECT dbo.Assy_FN_Get_ShiftWise_Date(@ProfitCenterCode))

			--UPDATE current planned qty FROM Assy_ProductionOrder_ParameterSetting_PlungerCrimping Table
			UPDATE POT SET POT.[balance qty] = POT.[balance qty] - ISNULL(CRP.CurrentPlannedQty, 0) FROM #Temp_PODATa_Search_PC (NOLOCK) POT 
			LEFT OUTER JOIN #temp1_RunningPart_Search_PC (NOLOCK) CRP
			ON POT.[production Order] = CRP.ProdOrderNo AND CONVERT(VARCHAR, POT.Date, 105) = CRP.ProdOrderDate AND POT.[PART NUMBER] = CRP.PartNumber 
			AND POT.[PLANNED QTY] = CRP.PlannedQty 

			--Modified By Ravi ON 21-03-17
			IF LEN(@ExceptChars)>0
			BEGIN
				SELECT @ExceptChars = '[^'+REPLACE(@ExceptChars, ', ', '')+']%'
				SELECT chk, [production Order], CONVERT(VARCHAR, Date, 105)[DATE1], [part number], [planned qty], [PROD. Qty], [balance qty]
				, [CURRENT PLANNED QTY] 
				, PRIORITY, Mode, Remarks, Status, ROW_NUMBER() OVER(Order By CONVERT(DATETIME, [Date])) FROM #Temp_PODATa_Search_PC (NOLOCK) 
				WHERE [production Order] like '%'+@ProdOrderNo+'%' AND [part number]Like '%'+@PartNumber+'%' AND [balance qty] > 0
				AND [part number] like @ExceptChars
				Group By chk, [production Order], Date, [part number], [planned qty], [PROD. Qty], [balance qty], [CURRENT PLANNED QTY], PRIORITY, Mode, Remarks, Status
				Order By [part number], [Date]
			END
			ELSE
			BEGIN											
				SELECT chk, [production Order], CONVERT(VARCHAR, Date, 105)[DATE1], [part number], [planned qty], [PROD. Qty], [balance qty]
				, [CURRENT PLANNED QTY] 
				, PRIORITY, Mode, Remarks, Status, ROW_NUMBER() OVER(Order By CONVERT(DATETIME, [Date])) FROM #Temp_PODATa_Search_PC (NOLOCK) 
				WHERE [production Order] like '%'+@ProdOrderNo+'%' AND [part number]Like '%'+@PartNumber+'%' AND [balance qty] > 0
				Group By chk, [production Order], Date, [part number], [planned qty], [PROD. Qty], [balance qty], [CURRENT PLANNED QTY], PRIORITY, Mode, Remarks, Status
				Order By [part number], [Date]
			END
		END
		ELSE
		BEGIN
			SELECT CASE WHEN AssyProd.ProdOrderPriority IS NULL THEN 0 ELSE 1 END As CHK, 
			ORDERNO [PRODUCTION Order], PO.OrderDate [Date], RTRIM(LTRIM(PartNo)) [PART NUMBER], 
			CONVERT(INT, ISNULL(QTY, 0)) [PLANNED QTY], CONVERT(INT, ISNULL(PO .ProducedQty, 0)) [PROD. QTY], 
			CONVERT(INT, ISNULL(PO .BalanceQty, 0)) [BALANCE QTY], 
			CASE WHEN AssyProd.CurrentPlannedQty IS NULL THEN CONVERT(INT, ISNULL(PO .BalanceQty, 0)) ELSE 
			CONVERT(INT, ISNULL(AssyProd.CurrentPlannedQty, 0)) END As [CURRENT PLANNED QTY], 
			CASE WHEN AssyProd.ProdOrderPriority IS NULL THEN ISNULL(PO .PRIORITY, ROW_NUMBER() OVER(Order By PO.ENT_STAMP)) ELSE 
			ISNULL(AssyProd.ProdOrderPriority, 0) END As [PRIORITY], 	
			ISNULL(AssyProd.Mode, '') As Mode, ISNULL(AssyProd.Remarks, '') Remarks, PO .Status Status, 
			CASE WHEN AssyProd.ProdOrderPriority IS NULL THEN 1 ELSE 0 END As NEWPRIORITY INTO #Temp_PODATa_WithRecord_Search_PC
			FROM Assy_ProductionOrderMst (NOLOCK) PO 				
			LEFT OUTER JOIN Assy_ProductionOrder_ParameterSetting_PlungerCrimping (NOLOCK) AssyProd 
			ON PO .ORDERNO = AssyProd.ProdOrderNo AND PO .PartNo = AssyProd.PartNumber AND PO.ProfitCenterCode = AssyProd.ProfitCenterCode 
			AND AssyProd.LineCode = @LineCode							 
			WHERE ISNULL(PO.Status, '0') <> '100' AND PO.ProfitCenterCode = @ProfitCenterCode AND PO.isActive = 1
			AND PO.WorkCenterCode 
			IN
			( 
				SELECT WorkCenterCode FROM LineMst (NOLOCK) L
				INNER JOIN Assy_LineGroup_Master (NOLOCK) LG ON L.ProfitCenterCode = LG.ProfitCenterCode AND L.LineCode = LG.LineCode
				WHERE LG.GroupCode = @GroupCode AND L.isActive = 1 AND LG.ProfitCenterCode = @ProfitCenterCode
			)
			AND CONVERT(Date, PO.OrderDate) < = (SELECT dbo.Assy_FN_Get_ShiftWise_Date(@ProfitCenterCode))

			--UPDATE current planned qty FROM Assy_ProductionOrder_ParameterSetting_PlungerCrimping Table
			UPDATE POT SET POT.[balance qty] = POT.[balance qty]-ISNULL(CRP.CurrentPlannedQty, 0) FROM #Temp_PODATa_WithRecord_Search_PC (NOLOCK) POT 
			LEFT OUTER JOIN #temp1_RunningPart_Search_PC (NOLOCK) CRP
			ON POT.[production Order] = CRP.ProdOrderNo AND CONVERT(VARCHAR, POT.Date, 105) = CRP.ProdOrderDate AND POT.[PART NUMBER] = CRP.PartNumber 
			AND POT.[PLANNED QTY] = CRP.PlannedQty 
								
			--Modified By Ravi ON 21-03-17
			IF LEN(@ExceptChars)>0
			BEGIN
				SELECT @ExceptChars = '[^'+REPLACE(@ExceptChars, ', ', '')+']%'

				SELECT chk, [production Order], CONVERT(VARCHAR, Date, 105)[DATE1], [part number], [planned qty], [PROD. Qty], [balance qty]
				, [CURRENT PLANNED QTY] 
				, PRIORITY, Mode, Remarks, Status, ROW_NUMBER() OVER(Order By CONVERT(DATETIME, [Date])) FROM #Temp_PODATa_WithRecord_Search_PC (NOLOCK) 
				WHERE [production Order] like '%'+@ProdOrderNo+'%' AND [part number]Like '%'+@PartNumber+'%' AND [balance qty] > 0
				AND [part number] like @ExceptChars
				Group By chk, [production Order], Date, [part number], [planned qty], [PROD. Qty], [balance qty], [CURRENT PLANNED QTY], PRIORITY, Mode, Remarks, Status
				Order By [part number], [Date]
			END
			ELSE
			BEGIN
				SELECT chk, [production Order], CONVERT(VARCHAR, Date, 105)[DATE1], [part number], [planned qty], [PROD. Qty], [balance qty]
				, [CURRENT PLANNED QTY] 
				, PRIORITY, Mode, Remarks, Status, ROW_NUMBER() OVER(Order By CONVERT(DATETIME, [Date])) FROM #Temp_PODATa_WithRecord_Search_PC (NOLOCK) 
				WHERE [production Order] like '%'+@ProdOrderNo+'%' AND [part number]Like '%'+@PartNumber+'%' AND [balance qty] > 0
				Group By chk, [production Order], Date, [part number], [planned qty], [PROD. Qty], [balance qty], [CURRENT PLANNED QTY], PRIORITY, Mode, Remarks, Status
				Order By [part number], [Date]
			END
		END			 
		
		IF OBJECT_ID('tempdb..#Temp_PODATa_Search_PC') IS NOT NULL
			Drop Table #Temp_PODATa_Search_PC
		IF OBJECT_ID('tempdb..#temp1_RunningPart_Search_PC') IS NOT NULL
			Drop Table #temp1_RunningPart_Search_PC						
		IF OBJECT_ID('tempdb..#Temp_PODATa_WithRecord_Search_PC') IS NOT NULL
			Drop Table #Temp_PODATa_WithRecord_Search_PC

		SELECT @ReturnValue = 'DATA SEARCHED', @ReturnInt = 1	
		RETURN 			
	END

	ELSE IF @Condition = 'GET_PRODUCTION_ORDERS_ERP'
	BEGIN
		--Added By Ravi ON 21-03-17
		SELECT @ExceptChars = ISNULL(ExceptChars, '') FROM dbo.LineMst WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
		SELECT @GroupCode = GroupCode FROM Assy_LineGroup_Master (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
		
		SELECT ProfitCenterCode, ProdOrderNo, CONVERT(VARCHAR, ProdOrderDate, 105)ProdOrderDate, PlannedQty, PartNumber
		, ISNULL(SUM(CurrentPlannedQty), 0)CurrentPlannedQty INTO #temp1_RunningPart
		FROM Assy_ProductionOrder_ParameterSetting (NOLOCK) WHERE LineCode 
		IN
		(
			SELECT LineCode FROM Assy_LineGroup_Master WHERE GroupCode = @GroupCode AND isActive = 1 AND ProfitCenterCode = @ProfitCenterCode
		)
		AND ProfitCenterCode = @ProfitCenterCode
		Group By ProfitCenterCode, ProdOrderNo, PlannedQty, PartNumber, ProdOrderNo, CONVERT(VARCHAR, ProdOrderDate, 105)
		
		IF NOT EXISTS(SELECT 1 FROM Assy_RunningPart (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode)
		BEGIN
			SELECT '0' As Chk, PO.ORDERNO [PRODUCTION Order], PO.OrderDate [Date], RTRIM(LTRIM(PO.PartNo)) [PART NUMBER], 
			CONVERT(INT, ISNULL(PO.QTY, 0)) [PLANNED QTY], CONVERT(INT, ISNULL(PO.ProducedQty, 0)) [PROD. QTY], 
			CONVERT(INT, ISNULL(PO.BalanceQty, 0)) [BALANCE QTY], 
			CONVERT(INT, ISNULL(AssyProd.CurrentPlannedQty, 0)) [CURRENT PLANNED QTY], 
			CASE WHEN AssyProd.ProdOrderPriority IS NULL THEN ISNULL(PO.PRIORITY, ROW_NUMBER() OVER(Order By PO.ENT_STAMP)) 
			ELSE ISNULL(AssyProd.ProdOrderPriority, 0) END As [PRIORITY], 	
			ISNULL(AssyProd.Mode, '') As Mode, ISNULL(AssyProd.Remarks, '') Remarks, PO.Status
			Status INTO #Temp_PODATa
			FROM Assy_ProductionOrderMst (NOLOCK) PO 
			LEFT OUTER JOIN Assy_ProductionOrder_ParameterSetting (NOLOCK) AssyProd 
			ON PO.ORDERNO = AssyProd.ProdOrderNo AND PO.PartNo = AssyProd.PartNumber 
			AND PO.ProfitCenterCode = AssyProd.ProfitCenterCode 
			AND AssyProd.LineCode 
			IN
			(
				SELECT L.LineCode FROM LineMst (NOLOCK) L 
				INNER JOIN Assy_LineGroup_Master (NOLOCK) LG ON L.ProfitCenterCode = LG.ProfitCenterCode AND L.LineCode = LG.LineCode
				WHERE LG.GroupCode = @GroupCode AND L.isActive = 1 AND LG.ProfitCenterCode = @ProfitCenterCode
			) 
			WHERE ISNULL(PO.Status, '0') <> '100' AND PO.ProfitCenterCode = @ProfitCenterCode AND PO.isActive = 1
			AND PO.WorkCenterCode 
			IN
			( 
				SELECT WorkCenterCode FROM LineMst (NOLOCK) L 
				INNER JOIN Assy_LineGroup_Master (NOLOCK) LG ON L.ProfitCenterCode = LG.ProfitCenterCode AND L.LineCode = LG.LineCode
				WHERE LG.GroupCode = @GroupCode AND L.isActive = 1 AND LG.ProfitCenterCode = @ProfitCenterCode
			)
			AND CONVERT(Date, OrderDate) < = (SELECT dbo.Assy_FN_Get_ShiftWise_Date(@ProfitCenterCode))
							
			--UPDATE current planned qty FROM Assy_ProductionOrder_ParameterSetting Table
			UPDATE POT SET POT.[balance qty] = POT.[balance qty]-ISNULL(CRP.CurrentPlannedQty, 0) FROM #Temp_PODATa (NOLOCK) POT 
			LEFT OUTER JOIN #temp1_RunningPart (NOLOCK) CRP
			ON POT.[production Order] = CRP.ProdOrderNo AND CONVERT(VARCHAR, POT.Date, 105) = CRP.ProdOrderDate AND POT.[PART NUMBER] = CRP.PartNumber 
			AND POT.[PLANNED QTY] = CRP.PlannedQty 								
							
			--Modified By Ravi ON 21-03-17
			IF LEN(@ExceptChars) > 0
			BEGIN
				SET @ExceptChars = '[^'+REPLACE(@ExceptChars, ', ', '')+']%'

				SELECT chk, [production Order], CONVERT(VARCHAR, Date, 105)[DATE1], [part number], [planned qty], [PROD. Qty], [balance qty]
				, [CURRENT PLANNED QTY] 
				, PRIORITY, Mode, Remarks, Status, ROW_NUMBER() OVER(Order By CONVERT(DATETIME, [Date])) FROM #Temp_PODATa (NOLOCK) WHERE [balance qty] > 0
				AND [part number] like @ExceptChars
				Group By chk, [production Order], Date, [part number], [planned qty], [PROD. Qty], [balance qty], [CURRENT PLANNED QTY], PRIORITY, Mode, Remarks, Status
				Order By [part number], [Date]
			END
			ELSE 
			BEGIN
				SELECT chk, [production Order], CONVERT(VARCHAR, Date, 105)[DATE1], [part number], [planned qty], [PROD. Qty], [balance qty]
				, [CURRENT PLANNED QTY] 
				, PRIORITY, Mode, Remarks, Status, ROW_NUMBER() OVER(Order By CONVERT(DATETIME, [Date])) FROM #Temp_PODATa (NOLOCK) WHERE [balance qty] > 0
				Group By chk, [production Order], Date, [part number], [planned qty], [PROD. Qty], [balance qty], [CURRENT PLANNED QTY], PRIORITY, Mode, Remarks, Status
				Order By [part number], [Date]
			END
		END
		ELSE
		BEGIN
			SELECT CASE WHEN AssyProd.ProdOrderPriority IS NULL THEN 0 ELSE 1 END As CHK, 
			ORDERNO [PRODUCTION Order], PO.OrderDate [Date], RTRIM(LTRIM(PartNo)) [PART NUMBER], 
			CONVERT(INT, ISNULL(QTY, 0)) [PLANNED QTY], CONVERT(INT, ISNULL(PO .ProducedQty, 0)) [PROD. QTY], 
			CONVERT(INT, ISNULL(PO .BalanceQty, 0)) [BALANCE QTY], 
			CASE WHEN AssyProd.CurrentPlannedQty IS NULL THEN CONVERT(INT, ISNULL(PO .BalanceQty, 0)) ELSE 
			CONVERT(INT, ISNULL(AssyProd.CurrentPlannedQty, 0)) END As [CURRENT PLANNED QTY], 
			CASE WHEN AssyProd.ProdOrderPriority IS NULL THEN ISNULL(PO .PRIORITY, ROW_NUMBER() OVER(Order By PO.ENT_STAMP)) ELSE 
			ISNULL(AssyProd.ProdOrderPriority, 0) END As [PRIORITY], 	
			ISNULL(AssyProd.Mode, '') As Mode, ISNULL(AssyProd.Remarks, '') Remarks, PO .Status Status, 
			CASE WHEN AssyProd.ProdOrderPriority IS NULL THEN 1 ELSE 0 END As NEWPRIORITY INTO #Temp_PODATa_WithRecord
			FROM Assy_ProductionOrderMst (NOLOCK) PO 				
			LEFT OUTER JOIN Assy_ProductionOrder_ParameterSetting (NOLOCK) AssyProd 
			ON PO .ORDERNO = AssyProd.ProdOrderNo AND PO .PartNo = AssyProd.PartNumber AND PO.ProfitCenterCode = AssyProd.ProfitCenterCode 
			AND AssyProd.LineCode = @LineCode							 
			WHERE ISNULL(PO.Status, '0') <> '100' AND PO.ProfitCenterCode = @ProfitCenterCode AND PO.isActive = 1
			AND PO.WorkCenterCode 
			IN
			( 
				SELECT WorkCenterCode FROM LineMst (NOLOCK) L 
				INNER JOIN Assy_LineGroup_Master (NOLOCK) LG ON L.ProfitCenterCode = LG.ProfitCenterCode AND L.LineCode = LG.LineCode
				WHERE LG.GroupCode = @GroupCode AND L.isActive = 1 AND LG.ProfitCenterCode = @ProfitCenterCode
			)
			AND CONVERT(Date, PO.OrderDate) < = (SELECT dbo.Assy_FN_Get_ShiftWise_Date(@ProfitCenterCode))

			--UPDATE current planned qty FROM Assy_ProductionOrder_ParameterSetting Table
			UPDATE POT SET POT.[balance qty] = POT.[balance qty]-ISNULL(CRP.CurrentPlannedQty, 0) FROM #Temp_PODATa_WithRecord (NOLOCK) POT 
			LEFT OUTER JOIN #temp1_RunningPart (NOLOCK) CRP
			ON POT.[production Order] = CRP.ProdOrderNo AND CONVERT(VARCHAR, POT.Date, 105) = CRP.ProdOrderDate AND POT.[PART NUMBER] = CRP.PartNumber 
			AND POT.[PLANNED QTY] = CRP.PlannedQty 
								
			--Modified By Ravi ON 21-03-17
			IF LEN(@ExceptChars) > 0
			BEGIN
				SET @ExceptChars = '[^'+REPLACE(@ExceptChars, ', ', '')+']%'

				SELECT chk, [production Order], CONVERT(VARCHAR, Date, 105)[DATE1], [part number], [planned qty], [PROD. Qty], [balance qty]
				, [CURRENT PLANNED QTY] 
				, PRIORITY, Mode, Remarks, Status, ROW_NUMBER() OVER(Order By CONVERT(DATETIME, [Date])) FROM #Temp_PODATa_WithRecord (NOLOCK) WHERE [balance qty] > 0
				AND [part number] like @ExceptChars
				Group By chk, [production Order], Date, [part number], [planned qty], [PROD. Qty], [balance qty], [CURRENT PLANNED QTY], PRIORITY, Mode, Remarks, Status
				Order By [part number], [Date]
			END
			ELSE 
			BEGIN
				SELECT chk, [production Order], CONVERT(VARCHAR, Date, 105)[DATE1], [part number], [planned qty], [PROD. Qty], [balance qty]
				, [CURRENT PLANNED QTY] 
				, PRIORITY, Mode, Remarks, Status, ROW_NUMBER() OVER(Order By CONVERT(DATETIME, [Date])) FROM #Temp_PODATa_WithRecord (NOLOCK) WHERE [balance qty] > 0
				Group By chk, [production Order], Date, [part number], [planned qty], [PROD. Qty], [balance qty], [CURRENT PLANNED QTY], PRIORITY, Mode, Remarks, Status
				Order By [part number], [Date]
			END
		END
			 
		IF OBJECT_ID('tempdb..#Temp_PODATa') IS NOT NULL
			Drop Table #Temp_PODATa
		IF OBJECT_ID('tempdb..#temp1_RunningPart') IS NOT NULL
			Drop Table #temp1_RunningPart						
		IF OBJECT_ID('tempdb..#Temp_PODATa_WithRecord') IS NOT NULL
			Drop Table #Temp_PODATa_WithRecord

		SELECT @ReturnValue = 'DATA SELECTED', @ReturnInt = 1
		RETURN
	END

	ELSE IF @Condition = 'GETPARAMETERS'
	BEGIN
		SELECT PARAMETER_C2, PARAMETER_NM, Parameter_Value 
		FROM PARAMETER_MST (NOLOCK) 
		WHERE PARAMETER_C = 'ASSLINE' AND USER_CONFIGURABLE_FLG = 1 AND wh_code = @ProfitCenterCode

		SELECT @ReturnValue = 'DATA SELECTED', @ReturnInt = 1
		RETURN
	END

	ELSE IF @Condition = 'GETLIST_MODE'
	BEGIN
		SELECT VALUE FROM [LISTMASTER] (NOLOCK) WHERE MODULE = 'ASSEMBLY' AND [KEY] = 'SETPARAMETER' AND SUBKEY = 'Mode' AND active = 1
		
		SELECT @ReturnValue = 'DATA SELECTED', @ReturnInt = 1
		RETURN
	END

	ELSE IF @Condition = 'SAVE'
	BEGIN
		BEGIN TRY
		BEGIN TRAN
		-- Add By Rashid 0n 29 Sep 2015 to handle Subquery returned more than 1 value. This IS NOT permitted when the subquery follows =, ! =, <, < =, >, > = OR when the subquery IS used As an expression
		SELECT Top 1 * INTO #Temp_ParameterTable FROM @ParameterTable
		SELECT @ProdOrderNo = [ProdOrderNo], @DateCode = [DateCode], @LineCode = [LineCode], @PartNumber = [PartNumber]
		, @Current_Planned_Qty = [Current_Planned_Qty], @UserCode = [UserCode]
		, @ProfitCenterCode = ProfitCenterCode, @Mode = Mode, @Remarks = ISNULL(Remarks, '') FROM #Temp_ParameterTable 

		--Added By Sachin 20190611
		IF ISNULL(@DateCode,'') = ''
		BEGIN
			SELECT @ReturnValue = 'Date Code Not Found !!!', @ReturnInt = 1
			COMMIT TRAN 
			RETURN
		END
		--Ended By Sachin 20190611


				-- ADDED BY SACHIN 20170914 
		if exists (select top 1 1 from RoutingConfigDetails(nolock) where ProfitCenterCode=@PROFITCENTERCODE and 
			sts_cd=0 and keyType='IsImportBarcodeMode' and LineCode=@LINECODE and PartNumber=@PARTNUMBER
		)
		begin
				update RoutingConfigDetails 
				set keyValue = convert(varchar,@ISALLOWIMPORTEDBARCODE)
				where ProfitCenterCode=@PROFITCENTERCODE and 
				sts_cd=0 and keyType='IsImportBarcodeMode' and LineCode=@LINECODE and PartNumber=@PARTNUMBER
		end
		else
		begin
				insert into RoutingConfigDetails (ProfitCenterCode,LineCode,MachineCode,OperationCode,PartNumber,KeyType,
				KeyValue,SeqNumber,isSeqReq,chkFromTable,Remarks,STS_CD,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP
				)values(@PROFITCENTERCODE,@LINECODE,'','',@PARTNUMBER,'IsImportBarcodeMode',convert(varchar,@ISALLOWIMPORTEDBARCODE),'',
				'','','Imported Barcode Setting',0,'ADMIN',GETDATE(),'ADMIN',GETDATE()
				)
		end
 
		-- ENDED By SACHIN 20170914
		--Check Part Type has been defined IN product master
		Declare @ProdPartType VARCHAR(30), @STS_CD SMALLINT
		SELECT @ProdPartType = ISNULL(MATERIAL_TP, ''), @NewPart_Family_Group_Code = Family_Group_Code, @STS_CD = STS_CD FROM PRODUCT_MASTER (NOLOCK) WHERE warehouse_cd = @ProfitCenterCode AND SEWS_PART_NO = @PartNumber
		
		Declare @isPokaYokeMandatory BIT = 0
		
		SELECT @isPokaYokeMandatory = isPokaYokeMandatory, @Allow2Parts = Allow2Parts FROM LineMst WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode

		IF ISNULL(@ProdPartType, '') = ''
		BEGIN
			SELECT @ReturnValue = 'Part Type has NOT been defined for this Part IN Part Master(New Part).', @ReturnInt = 1
			COMMIT TRAN 
			RETURN
		END
		IF ISNULL(@STS_CD, 0) = 100
		BEGIN
			SELECT @ReturnValue = 'Part is not active in Part Master.', @ReturnInt = 1
			COMMIT TRAN 
			RETURN
		END
		-- ADDED By RS On 20171214 For Validating Family Group Code
		IF ISNULL(@Allow2Parts,0) = 1 AND ISNULL(@NewPart_Family_Group_Code,'') = ''
		BEGIN
			SELECT @ReturnValue = 'Please define Family_Group_Code in Part Master in Central DB and Sync in Local DB.', @ReturnInt = 1
			COMMIT TRAN 
			RETURN
		END
		-- CHECK PART WISE ROUTING IS AVAILABLE FOR THIS PART NO.
		IF NOT EXISTS
		(
			SELECT 1 FROM RoutingConfigPartWise (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND PartNo = @PartNumber
		)
		BEGIN
			SELECT @ReturnValue = 'Partwise Routing IS NOT available for this Part number(New Part).', @ReturnInt = 1
			COMMIT TRAN 
			RETURN
		END
		--Check Group has been defined for this part IN PART WISE ROUTING
		IF EXISTS
		(
			SELECT 1 FROM RoutingConfigPartWise RP WITH (NOLOCK) INNER JOIN LineMst LM WITH (NOLOCK) 
			ON LM.ProfitCenterCode = RP.ProfitCenterCode
			WHERE LM.ProfitCenterCode = @ProfitCenterCode 
			AND PartNo = @PartNumber AND ISNULL(Part_FixtureGroupType, '') = ''
			AND LM.LineCode = @LineCode AND ISNULL(LM.isPokaYokeMandatory, 0) = 1
		)
		BEGIN
			SELECT @ReturnValue = 'Poka Yoke Group has NOT been defined for this part IN Part Wise Routing Master.', @ReturnInt = 1
			COMMIT TRAN 
			RETURN
		END

		 --@PartType VARCHAR(20),
		Declare	@ServoPartNo VARCHAR(30), @TMCPartNo VARCHAR(30), @BoostRatio VARCHAR(20), @PRNFile NVARCHAR(MAX) = '', @ModelName VARCHAR(30), @PlantCode VARCHAR(30),
				@PRN_CustomerGroupCode VARCHAR(100) = '', @PartID VARCHAR(10) = '', @Indicator VARCHAR(10) = ''
		
		--SELECT Top 1 @PartType = ISNULL(MATERIAL_TP, '') FROM PRODUCT_MASTER WITH (NOLOCK) 
		--	WHERE warehouse_cd = @ProfitCenterCode AND STS_CD = 0 AND SEWS_PART_NO = @PartNumber

		SELECT @PRN_CustomerGroupCode = ISNULL(GroupCode, '') FROM Assy_PRN_CustomerGroupMaster WITH (NOLOCK) 
			WHERE PartNo = @PartNumber AND CustomerPartNo = LTRIM(RTRIM(@CustomerPartNumber))
																 
		IF @ProdPartType = 'STMC'
		BEGIN
			--Get servo AND tmc parts FROM bom master
			SELECT @ServoPartNo = ServoPartNo, @TMCPartNo = TMCPartNo FROM Assy_FN_Get_ServoTMCParts_From_STMCPart(@ProfitCenterCode, @PartNumber, 1)
			
			IF ISNULL(@ServoPartNo, '') = '' OR ISNULL(@TMCPartNo, '') = ''
			BEGIN
				SELECT @ReturnValue = 'Either servo OR TMC part has NOT been defined OR NOT Active for this FG part no. IN BOM master.', @ReturnInt = 1
				COMMIT TRAN
				RETURN
			END
			
			IF @PRN_CustomerGroupCode IN ('GC_DUSTER_LINE_6_7', 'GC_NISSAN_LINE_6_7')
			BEGIN
				--Get Part Id for this stmc part no IN Nissan Line 6
				SELECT @PartID = ISNULL(LabelDataValue, '') FROM Assy_Coupling_LabelInfo_Mst (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode 
				AND PartNo = @PartNumber AND CustomerPartNo = LTRIM(RTRIM(@CustomerPartNumber))
				AND LabelDataName = 'Part_ID'	
				
				IF ISNULL(@PartID, '') = ''
				BEGIN
					SELECT @ReturnValue = 'Part ID (Last 4 digit) has NOT been defined for this part IN Coupling Label Info Master.', @ReturnInt = 1
					COMMIT TRAN 
					RETURN
				END

				--Get Model name for this stmc part no
				SELECT @Indicator = ISNULL(LabelDataValue, '') FROM ASSY_COUPLING_LABELINFO_MST (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode 
				AND PartNo = @PartNumber AND CUSTOMERPARTNO = LTRIM(RTRIM(@CustomerPartNumber))
				AND LabelDataName = 'Indicator'
				
				IF ISNULL(@Indicator, '') = ''
				BEGIN
					SELECT @ReturnValue = 'Indicator has NOT been defined for this part IN Coupling Label Info Master.', @ReturnInt = 1
					COMMIT TRAN 
					RETURN
				END
				--Added By RS On 20180720 For TMC Part Cap Color | 0-Default,1-NoColor,2-Black,3-Yellow
				--Get TMC Part Cap Color for this stmc part no in Nissan Line 6
				SELECT @CapColor = ISNULL(LabelDataValue, '') FROM Assy_Coupling_LabelInfo_Mst (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode 
				AND PartNo = @PartNumber AND CustomerPartNo = LTRIM(RTRIM(@CustomerPartNumber))
				AND LabelDataName = 'CapColorCode'
				
				IF ISNULL(@CapColor, '') = ''
				BEGIN
					SELECT @ReturnValue = 'TMC Cap Color has not been defined for this part in Coupling Label Info Master.', @ReturnInt = 1
					COMMIT TRAN 
					RETURN
				END
			END
			ELSE
			BEGIN
				--Get boost ratio for this stmc part no
				SELECT @BoostRatio = ISNULL(LabelDataValue, '') FROM Assy_Coupling_LabelInfo_Mst (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode 
				AND PartNo = @PartNumber AND CustomerPartNo = LTRIM(RTRIM(@CustomerPartNumber))
				AND LabelDataName = 'Boost_Ratio'	
				
				IF ISNULL(@BoostRatio, '') = '' 
				BEGIN
					SELECT @ReturnValue = 'Boost Ratio has NOT been defined for this part IN Coupling Label Info Master.', @ReturnInt = 1
					COMMIT TRAN 
					RETURN
				END	
				--Get Model name for this stmc part no
				SELECT @ModelName = ISNULL(LabelDataValue, '') FROM ASSY_COUPLING_LABELINFO_MST (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode 
				AND PartNo = @PartNumber AND CUSTOMERPARTNO = LTRIM(RTRIM(@CustomerPartNumber))
				AND LabelDataName = 'MODEL_NAME'
				
				IF ISNULL(@ModelName, '') = '' 
				BEGIN
					SELECT @ReturnValue = 'Model Name has NOT been defined for this part IN Coupling Label Info Master.', @ReturnInt = 1
					COMMIT TRAN 
					RETURN
				END	
				--Get Plant Code for this stmc part no
				SELECT @PlantCode = ISNULL(LabelDataValue, '') FROM ASSY_COUPLING_LABELINFO_MST (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode 
				AND PartNo = @PartNumber AND CUSTOMERPARTNO = LTRIM(RTRIM(@CustomerPartNumber))
				AND LabelDataName = 'PLANT_CODE'	
				
				IF ISNULL(@PlantCode, '') = '' 										
				BEGIN
					SELECT @ReturnValue = 'Plant Code has NOT been defined for this part IN Coupling Label Info Master.', @ReturnInt = 1
					COMMIT TRAN 
					RETURN
				END	
																			
				--Get PRN FIle for this stmc part no
				IF @CustomerPartNumber ! = ''
					SELECT Distinct Top 1 @PRNFile = ISNULL(PGM.PRNFile, '') FROM Assy_PRN_CustomerGroupMaster PCGM (NOLOCK) INNER JOIN Assy_PRN_GroupMaster PGM (NOLOCK)
						ON PCGM.GroupCode = PGM.GroupCode
							WHERE PCGM.PartNo = @PartNumber AND PCGM.CustomerPartNo = @CustomerPartNumber										
				
				IF ISNULL(@PRNFile, '') = '' 
				BEGIN
					SELECT @ReturnValue = 'PRN File has NOT been defined for this part IN PRN master.', @ReturnInt = 1
					COMMIT TRAN
					RETURN
				END
			END
		END
		ELSE IF @ProdPartType = 'SERVO'
		BEGIN
			--Get boost ratio for this part no
			SELECT @BoostRatio = ISNULL(LabelDataValue, '') FROM Assy_Coupling_LabelInfo_Mst (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode 
			AND PartNo = @PartNumber 
			AND LabelDataName = 'Boost_Ratio'

			IF ISNULL(@BoostRatio, '') = '' 
			BEGIN
				SELECT @ReturnValue = 'Boost Ratio has NOT been defined for this part IN Coupling Label Info Master.', @ReturnInt = 1
				COMMIT TRAN 
				RETURN
			END
		END
		
		--IF EXISTS
		--(
		--	SELECT 1 FROM LineMst WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(isPokaYokeMandatory, 0) = 0
		--)
		IF ISNULL(@isPokaYokeMandatory,0) = 0
		BEGIN
			IF EXISTS
			(
				SELECT 1 FROM Assy_RunningPart WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode 
					AND Assy_PartNo = @PartNumber AND DateCode = @DateCode
			)
			BEGIN
				SET @IsPokaYokeAlreadyBypassedForThisPart = 1
			END
		END		

		DELETE FROM Assy_ProductionOrder_ParameterSetting WHERE LineCode = @LineCode
		
		INSERT INTO Assy_ProductionOrder_ParameterSetting
		SELECT [ProfitCenterCode], [LineCode], [StationCode], [DateCode], [ProdOrderNo], --CONVERT(DATETIME, [ProdOrderDate], 103), 
		[ProdOrderDate], 
		[PartNumber], CONVERT(NUMERIC(15, 3), [PlannedQty]), CONVERT(NUMERIC(15, 3), [ProductionQty]), CONVERT(NUMERIC(15, 3), 
		[BalanceQty]), CONVERT(INT, [ProdOrderPriority]), [Current_Planned_Qty], [Mode], [Remarks], [Status], [UserCode], GETDATE() 
		FROM #Temp_ParameterTable

		-- COMMENTED By PANKAJ
		--DELETE FROM Assy_RunningPart WHERE LineCode = @LineCode			
		--INSERT INTO Assy_RunningPart(LineCode, DateCode, Assy_PartNo, ProductionOrderNo, CurrentPlannedQty, Assy_Mode, CreatedDate, CreatedBy)			
		--SELECT LineCode, DateCode, PartNumber, ProdOrderNo, Current_Planned_Qty, Mode, GETDATE(), UserCode FROM #Temp_ParameterTable 

		IF EXISTS(SELECT 1 FROM Assy_RunningPart (NOLOCK) WHERE LineCode = @LineCode AND DateCode = @DateCode AND Assy_PartNo = @PartNumber AND ProfitCenterCode = @ProfitCenterCode)
		BEGIN
			UPDATE Assy_RunningPart SET CurrentPlannedQty = @Current_Planned_Qty, Assy_Mode = @Mode, ProductionOrderNo = @ProdOrderNo,
			ModifiedBy = @UserCode, ModifiedOn = GETDATE(), CustomerPartNo = @CustomerPartNumber, Boost_Ratio = @BoostRatio, 
			Servo_PartNo = @ServoPartNo, TMC_PartNo = @TMCPartNo 
			WHERE LineCode = @LineCode AND DateCode = @DateCode AND Assy_PartNo = @PartNumber AND ProfitCenterCode = @ProfitCenterCode
		END
		ELSE
		BEGIN
			IF ISNULL(@Allow2Parts,0) = 1 AND ISNULL(@NewPart_Family_Group_Code,'') != ''
			BEGIN
				Declare @OldSetParameterPart VARCHAR(20) = '', @OldSetParameterDateCode CHAR(4) = ''
				SELECT @OldSetParameterPart = Assy_PartNo, @OldSetParameterDateCode = Datecode FROM Assy_RunningPart (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
			
				IF ISNULL(@OldSetParameterPart,'') != ''
				BEGIN
					SELECT @OldPart_Family_Group_Code = Family_Group_Code FROM PRODUCT_MASTER (NOLOCK) WHERE warehouse_cd = @ProfitCenterCode AND SEWS_PART_NO = @OldSetParameterPart
				END
				IF @OldPart_Family_Group_Code = @NewPart_Family_Group_Code
				BEGIN
					--IF @OldSetParameterDateCode = @DateCode
					--BEGIN
						INSERT INTO Assy_RunningPartFamily(LineCode,Datecode,Assy_PartNo,ProductionOrderNo,CurrentPlannedQty,Assy_Mode,CreatedDate,
						CreatedBy,ModifiedOn,ModifiedBy,IsAuthorized,IsTallySnoozed,PrintedQty,Boost_Ratio,Servo_PartNo,TMC_PartNo,PartType,ProfitCenterCode,CustomerPartNo)
						SELECT LineCode,Datecode,Assy_PartNo,ProductionOrderNo,CurrentPlannedQty,Assy_Mode,CreatedDate,CreatedBy,ModifiedOn,ModifiedBy,IsAuthorized,IsTallySnoozed,PrintedQty,Boost_Ratio,Servo_PartNo,TMC_PartNo,PartType,ProfitCenterCode,CustomerPartNo
							FROM Assy_RunningPart WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
					--END
				END
			END

			DELETE FROM Assy_RunningPart WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
			
			INSERT INTO Assy_RunningPart(LineCode, DateCode, Assy_PartNo, ProductionOrderNo, CurrentPlannedQty, Assy_Mode, CreatedDate, CreatedBy, 
			Boost_Ratio, Servo_PartNo, TMC_PartNo, PartType, ProfitCenterCode, CustomerPartNo)
			SELECT LineCode, DateCode, PartNumber, ProdOrderNo, Current_Planned_Qty, Mode, GETDATE(), UserCode, 
			@BoostRatio, @ServoPartNo, @TMCPartNo, @ProdPartType, @ProfitCenterCode, @CustomerPartNumber FROM #Temp_ParameterTable

			
		END


		--Added by Ravi on 28-06-17, to resolve materail feeding issue
		if exists
		( 
				select 1 from Assy_MachineWise_RunningPart with(nolock) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
				AND OperationCode = dbo.Assy_FN_Get_FinalViewing_OperationCode_From_LineCode(@ProfitCenterCode,@LineCode)
		)
		begin
				UPDATE Assy_MachineWise_RunningPart SET PartNo = @PartNumber,UpdatedDate=getdate() WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
				AND OperationCode =dbo.Assy_FN_Get_FinalViewing_OperationCode_From_LineCode(@ProfitCenterCode,@LineCode)
		end
		else 
			begin
				insert into Assy_MachineWise_RunningPart(ProfitCenterCode,LineCode,OperationCode,MachineCode ,PartNo,CreatedDate)
				select @ProfitCenterCode,@LineCode,dbo.Assy_FN_Get_FinalViewing_OperationCode_From_LineCode(@ProfitCenterCode,@LineCode)
				,dbo.Assy_FN_Get_FinalViewing_MachineCode_From_LineCode(@ProfitCenterCode,@LineCode),@PartNumber,getdate()

			end
		INSERT INTO Assy_ProductionOrder_ParameterSetting_ChangeOver(ProdOrderNo, DateCode, Remarks, CurrMode, PrevMode, UserCode, Timestamp)
		SELECT A.ProdOrderNo, A.DateCode, B.Remarks, B.Mode, A.Mode, B.UserCode, GETDATE() 
		FROM Assy_ProductionOrder_ParameterSetting A 
		INNER JOIN #Temp_ParameterTable B ON A.ProdOrderNo = B.ProdOrderNo AND A.PartNumber = B.PartNumber
		WHERE A.LineCode = @LineCode

		IF @IsPokaYokeAlreadyBypassedForThisPart = 0
		BEGIN
			--Added By Ravi 24/03/2016-------------------
			IF NOT EXISTS
			(
				SELECT 1 FROM Assy_LineAssyStatus_FV_LastTested_Barcode WITH (NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			)
			BEGIN
				EXEC Assy_Proc_LineMst_SuperUser_Control @ProfitCenterCode = @ProfitCenterCode, @LineCode = @LineCode, @IsLocalDB = 0
			END
			ELSE
			BEGIN
				SELECT @LstRunningDateCode = DateCode, @LstRunningPartNo = PartNo FROM Assy_LineAssyStatus_FV_LastTested_Barcode WITH (NOLOCK) 
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
									
				IF (@LstRunningDateCode <> @DateCode) OR (@LstRunningDateCode = @DateCode AND @LstRunningPartNo <> @PartNumber)
				BEGIN
					EXEC Assy_Proc_LineMst_SuperUser_Control @ProfitCenterCode = @ProfitCenterCode, @LineCode = @LineCode, @IsLocalDB = 0
				END
			END
		END
		---------------------------------------------								 
		SELECT @ReturnValue = 'DATA SAVED', @ReturnInt = 1
		COMMIT TRAN

		END TRY
		BEGIN CATCH
			--CATCH BLOCK BEGINS	
			SET @RETURNVALUE =	CAST(ISNULL(ERROR_NUMBER(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_SEVERITY(),0)AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_STATE(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_PROCEDURE(),'') AS VARCHAR(200)) + '|' + 
								CAST(ISNULL(ERROR_LINE(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_MESSAGE(),'') AS VARCHAR(1500))
			SET @ReturnInt = 2
			ROLLBACK TRAN
			RAISERROR(@ReturnValue, 16, 1)
		END CATCH
		RETURN
	END

	ELSE IF @Condition = 'GET_CHANGEOVER_DATA'
	BEGIN
		--SELECT Remarks, DateCode, CURRMODE, PREVMODE 
		--FROM Assy_ProductionOrder_ParameterSetting_ChangeOver (NOLOCK) 
		----WHERE ProdOrderNo = @ProdOrderNo
		--WHERE DateCode = (SELECT DateCode FROM Assy_RunningPart (NOLOCK) WHERE LineCode = @LineCode )
		--Order By Timestamp

		IF OBJECT_ID('tempdb..#TempTable') IS NOT NULL
		BEGIN
			Drop Table #TempTable
		END

		SELECT ProdOrderNo, Remarks, DateCode, CURRMODE, PREVMODE INTO #TempTable FROM
		(
			SELECT distinct ProdOrderNo, Remarks, DateCode, CURRMODE, PREVMODE, Timestamp
			FROM Assy_ProductionOrder_ParameterSetting_ChangeOver (NOLOCK) 
			WHERE DateCode = (SELECT DateCode FROM Assy_RunningPart (NOLOCK) WHERE LineCode = @LineCode )
		)A
		Order By Timestamp

		SELECT Distinct ProdOrderNo Remarks, DateCode, CURRMODE, PREVMODE FROM #TempTable
		Drop Table #TempTable

		SELECT @ReturnValue = 'DATA SAVED', @ReturnInt = 1
		RETURN
	END

	ELSE IF @Condition = 'SEARCH'
	BEGIN
		--Added By Ravi ON 21-03-17
		SELECT @ExceptChars = ISNULL(ExceptChars, '') FROM dbo.LineMst WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
		SELECT @GroupCode = GroupCode FROM Assy_LineGroup_Master (NOLOCK) WHERE LineCode = @LineCode
		
		SELECT ProfitCenterCode, ProdOrderNo, CONVERT(VARCHAR, ProdOrderDate, 105)ProdOrderDate, PlannedQty, PartNumber
		, ISNULL(SUM(CurrentPlannedQty), 0)CurrentPlannedQty INTO #temp1_RunningPart_Search
		FROM Assy_ProductionOrder_ParameterSetting (NOLOCK) WHERE LineCode 
		IN
		(
			SELECT LineCode FROM Assy_LineGroup_Master WITH (NOLOCK) WHERE GroupCode = @GroupCode AND isActive = 1 AND ProfitCenterCode = @ProfitCenterCode
		)
		AND ProfitCenterCode = @ProfitCenterCode
		Group By ProfitCenterCode, ProdOrderNo, PlannedQty, PartNumber, ProdOrderNo, CONVERT(VARCHAR, ProdOrderDate, 105)

		IF NOT EXISTS(SELECT 1 FROM Assy_RunningPart (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode)
		BEGIN
			SELECT '0' As Chk, PO.ORDERNO [PRODUCTION Order], PO.OrderDate [Date], RTRIM(LTRIM(PO.PartNo)) [PART NUMBER], 
			CONVERT(INT, ISNULL(PO.QTY, 0)) [PLANNED QTY], CONVERT(INT, ISNULL(PO.ProducedQty, 0)) [PROD. QTY], 
			CONVERT(INT, ISNULL(PO.BalanceQty, 0)) [BALANCE QTY], 
			CONVERT(INT, ISNULL(AssyProd.CurrentPlannedQty, 0)) [CURRENT PLANNED QTY], 
			CASE WHEN AssyProd.ProdOrderPriority IS NULL THEN ISNULL(PO.PRIORITY, ROW_NUMBER() OVER(Order By PO.ENT_STAMP)) 
			ELSE ISNULL(AssyProd.ProdOrderPriority, 0) END As [PRIORITY], 	
			ISNULL(AssyProd.Mode, '') As Mode, ISNULL(AssyProd.Remarks, '') Remarks, PO.Status
			Status INTO #Temp_POData_Search
			FROM Assy_ProductionOrderMst (NOLOCK) PO 
			LEFT OUTER JOIN Assy_ProductionOrder_ParameterSetting (NOLOCK) AssyProd 
			ON PO.ORDERNO = AssyProd.ProdOrderNo AND PO.PartNo = AssyProd.PartNumber 
			AND PO.ProfitCenterCode = AssyProd.ProfitCenterCode 
			AND AssyProd.LineCode 
			IN
			(
				SELECT L.LineCode FROM LineMst (NOLOCK) L 
				INNER JOIN Assy_LineGroup_Master (NOLOCK) LG ON L.ProfitCenterCode = LG.ProfitCenterCode AND L.LineCode = LG.LineCode
				WHERE LG.GroupCode = @GroupCode AND L.isActive = 1 AND LG.ProfitCenterCode = @ProfitCenterCode
			) 
			WHERE ISNULL(PO.Status, '0') <> '100' AND PO.ProfitCenterCode = @ProfitCenterCode AND PO.isActive = 1
			AND PO.WorkCenterCode
			IN
			( 
				SELECT distinct WorkCenterCode FROM LineMst (NOLOCK) L 
				INNER JOIN Assy_LineGroup_Master (NOLOCK) LG ON L.ProfitCenterCode = LG.ProfitCenterCode AND L.LineCode = LG.LineCode
				WHERE LG.GroupCode = @GroupCode AND L.isActive = 1 AND LG.ProfitCenterCode = @ProfitCenterCode
			)
			AND CONVERT(Date, OrderDate) < = (SELECT dbo.Assy_FN_Get_ShiftWise_Date(@ProfitCenterCode))
							
			--UPDATE current planned qty FROM Assy_ProductionOrder_ParameterSetting Table
			UPDATE POT SET POT.[balance qty] = POT.[balance qty]-ISNULL(CRP.CurrentPlannedQty, 0) FROM #Temp_POData_Search (NOLOCK) POT 
			LEFT OUTER JOIN #temp1_RunningPart_Search (NOLOCK) CRP
			ON POT.[production Order] = CRP.ProdOrderNo AND CONVERT(VARCHAR, POT.Date, 105) = CRP.ProdOrderDate AND POT.[PART NUMBER] = CRP.PartNumber 
			AND POT.[PLANNED QTY] = CRP.PlannedQty 
								
			--Modified By Ravi ON 21-03-17
			IF LEN(@ExceptChars) > 0
			BEGIN
				SELECT @ExceptChars = '[^'+REPLACE(@ExceptChars, ', ', '')+']%'

				SELECT chk, [production Order], CONVERT(VARCHAR, Date, 105)[DATE1], [part number], [planned qty], [PROD. Qty], [balance qty]
				, [CURRENT PLANNED QTY] 
				, PRIORITY, Mode, Remarks, Status, ROW_NUMBER() OVER(Order By CONVERT(DATETIME, [Date])) FROM #Temp_POData_Search (NOLOCK) 
				WHERE [production Order] like '%'+@ProdOrderNo+'%' AND [part number]Like '%'+@PartNumber+'%' AND [balance qty] > 0
				AND [part number] like @ExceptChars
				Group By chk, [production Order], Date, [part number], [planned qty], [PROD. Qty], [balance qty], [CURRENT PLANNED QTY], PRIORITY, Mode, Remarks, Status
				Order By [part number], [Date]
			END
			ELSE 
			BEGIN
				SELECT chk, [production Order], CONVERT(VARCHAR, Date, 105)[DATE1], [part number], [planned qty], [PROD. Qty], [balance qty]
				, [CURRENT PLANNED QTY] 
				, PRIORITY, Mode, Remarks, Status, ROW_NUMBER() OVER(Order By CONVERT(DATETIME, [Date])) FROM #Temp_POData_Search (NOLOCK) 
				WHERE [production Order] like '%'+@ProdOrderNo+'%' AND [part number]Like '%'+@PartNumber+'%' AND [balance qty] > 0
				Group By chk, [production Order], Date, [part number], [planned qty], [PROD. Qty], [balance qty], [CURRENT PLANNED QTY], PRIORITY, Mode, Remarks, Status
				Order By [part number], [Date]
			END
		END
		ELSE
		BEGIN
			SELECT CASE WHEN AssyProd.ProdOrderPriority IS NULL THEN 0 ELSE 1 END As CHK, 
			ORDERNO [PRODUCTION Order], PO.OrderDate [Date], RTRIM(LTRIM(PartNo)) [PART NUMBER], 
			CONVERT(INT, ISNULL(QTY, 0)) [PLANNED QTY], CONVERT(INT, ISNULL(PO .ProducedQty, 0)) [PROD. QTY], 
			CONVERT(INT, ISNULL(PO .BalanceQty, 0)) [BALANCE QTY], 
			CASE WHEN AssyProd.CurrentPlannedQty IS NULL THEN CONVERT(INT, ISNULL(PO .BalanceQty, 0)) ELSE 
			CONVERT(INT, ISNULL(AssyProd.CurrentPlannedQty, 0)) END As [CURRENT PLANNED QTY], 
			CASE WHEN AssyProd.ProdOrderPriority IS NULL THEN ISNULL(PO .PRIORITY, ROW_NUMBER() OVER(Order By PO.ENT_STAMP)) ELSE 
			ISNULL(AssyProd.ProdOrderPriority, 0) END As [PRIORITY], 	
			ISNULL(AssyProd.Mode, '') As Mode, ISNULL(AssyProd.Remarks, '') Remarks, PO .Status Status, 
			CASE WHEN AssyProd.ProdOrderPriority IS NULL THEN 1 ELSE 0 END As NEWPRIORITY INTO #Temp_POData_WithRecord_Search
			FROM Assy_ProductionOrderMst (NOLOCK) PO 				
			LEFT OUTER JOIN Assy_ProductionOrder_ParameterSetting (NOLOCK) AssyProd 
			ON PO .ORDERNO = AssyProd.ProdOrderNo AND PO .PartNo = AssyProd.PartNumber AND PO.ProfitCenterCode = AssyProd.ProfitCenterCode 
			AND AssyProd.LineCode = @LineCode							 
			WHERE ISNULL(PO.Status, '0')<>'100' AND PO.ProfitCenterCode = @ProfitCenterCode AND PO.isActive = 1
			AND PO.WorkCenterCode 
			IN
			( 
				SELECT WorkCenterCode FROM LineMst (NOLOCK) L 
				INNER JOIN Assy_LineGroup_Master (NOLOCK) LG ON L.ProfitCenterCode = LG.ProfitCenterCode AND L.LineCode = LG.LineCode
				WHERE LG.GroupCode = @GroupCode AND L.isActive = 1 AND LG.ProfitCenterCode = @ProfitCenterCode
			)
			AND CONVERT(Date, PO.OrderDate) < = (SELECT dbo.Assy_FN_Get_ShiftWise_Date(@ProfitCenterCode))

			--UPDATE current planned qty FROM Assy_ProductionOrder_ParameterSetting Table
			UPDATE POT SET POT.[balance qty] = POT.[balance qty]-ISNULL(CRP.CurrentPlannedQty, 0) FROM #Temp_POData_WithRecord_Search (NOLOCK) POT 
			LEFT OUTER JOIN #temp1_RunningPart_Search (NOLOCK) CRP
			ON POT.[production Order] = CRP.ProdOrderNo AND CONVERT(VARCHAR, POT.Date, 105) = CRP.ProdOrderDate AND POT.[PART NUMBER] = CRP.PartNumber 
			AND POT.[PLANNED QTY] = CRP.PlannedQty 
								
			--Modified By Ravi ON 21-03-17
			IF LEN(@ExceptChars) > 0
			BEGIN
				SELECT @ExceptChars = '[^'+REPLACE(@ExceptChars, ', ', '')+']%'
				SELECT chk, [production Order], CONVERT(VARCHAR, Date, 105)[DATE1], [part number], [planned qty], [PROD. Qty], [balance qty]
				, [CURRENT PLANNED QTY] 
				, PRIORITY, Mode, Remarks, Status, ROW_NUMBER() OVER(Order By CONVERT(DATETIME, [Date])) FROM #Temp_POData_WithRecord_Search (NOLOCK) 
				WHERE [production Order] like '%'+@ProdOrderNo+'%' AND [part number]Like '%'+@PartNumber+'%' AND [balance qty] > 0
				AND [part number] like @ExceptChars
				Group By chk, [production Order], Date, [part number], [planned qty], [PROD. Qty], [balance qty], [CURRENT PLANNED QTY], PRIORITY, Mode, Remarks, Status
				Order By [part number], [Date]
			END
			ELSE 
			BEGIN
				SELECT chk, [production Order], CONVERT(VARCHAR, Date, 105)[DATE1], [part number], [planned qty], [PROD. Qty], [balance qty]
				, [CURRENT PLANNED QTY] 
				, PRIORITY, Mode, Remarks, Status, ROW_NUMBER() OVER(Order By CONVERT(DATETIME, [Date])) FROM #Temp_POData_WithRecord_Search (NOLOCK) 
				WHERE [production Order] like '%'+@ProdOrderNo+'%' AND [part number]Like '%'+@PartNumber+'%' AND [balance qty] > 0									
				Group By chk, [production Order], Date, [part number], [planned qty], [PROD. Qty], [balance qty], [CURRENT PLANNED QTY], PRIORITY, Mode, Remarks, Status
				Order By [part number], [Date]
			END
		END
			 
		IF OBJECT_ID('tempdb..#Temp_POData_Search') IS NOT NULL
			Drop Table #Temp_POData_Search
		IF OBJECT_ID('tempdb..#temp1_RunningPart_Search') IS NOT NULL
			Drop Table #temp1_RunningPart_Search						
		IF OBJECT_ID('tempdb..#Temp_POData_WithRecord_Search') IS NOT NULL
			Drop Table #Temp_POData_WithRecord_Search

		SELECT @ReturnValue = 'DATA SEARCHED', @ReturnInt = 1
		RETURN 				
	END

	ELSE IF @Condition = 'SAVE_PC'
	BEGIN		 
		BEGIN TRY
			BEGIN TRAN
			SELECT Top 1 @ProfitCenterCode = [ProfitCenterCode], @LineCode = [LineCode], @PartNumber = [PartNumber] FROM @ParameterTable_PC 					
			--Check Part Type has been defined IN product master
			SELECT @ProdPartType = ISNULL(material_tp, '') FROM PRODUCT_MASTER (NOLOCK) WHERE warehouse_cd = @ProfitCenterCode AND SEWS_PART_NO = @PartNumber
			
			IF ISNULL(@ProdPartType, '') = ''
			BEGIN
				SELECT @ReturnValue = 'Part Type has NOT been defined for this Part IN Part Master(New Part).', @ReturnInt = 1
				COMMIT TRAN 
				RETURN
			END	
			-- CHECK PART WISE ROUTING IS AVAILABLE FOR THIS PART NO.
			IF NOT EXISTS
			(
				SELECT Top 1 1 FROM RoutingConfigPartWise (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND PartNo = @PartNumber
			)
			BEGIN
				SELECT @ReturnValue = 'Partwise Routing IS NOT available for this part number(New Part).', @ReturnInt = 1
				COMMIT TRAN 
				RETURN
			END
			--INSERT only new production Order INTO Assy_ProductionOrder_ParameterSetting Table
			DELETE FROM Assy_ProductionOrder_ParameterSetting_PlungerCrimping WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode

			INSERT INTO Assy_ProductionOrder_ParameterSetting_PlungerCrimping
			(
				ProfitCenterCode
				, LineCode
				, StationCode
				, DateCode
				, ProdOrderNo
				, ProdOrderDate
				, PartNumber
				, PlannedQty
				, ProductionQty
				, BalanceQty
				, ProdOrderPriority
				, Mode
				, Remarks
				, Status
				, UserCode
				, Timestamp, 
				CurrentPlannedQty
			)
			SELECT Top 1 [ProfitCenterCode], [LineCode], [StationCode], [DateCode], [ProdOrderNo], 
			[ProdOrderDate], [PartNumber], CONVERT(NUMERIC(15, 3), [PlannedQty]), 
			CONVERT(NUMERIC(15, 3), [ProductionQty]), CONVERT(NUMERIC(15, 3), [BalanceQty]), 
			CONVERT(INT, [ProdOrderPriority]), [Mode], [Remarks], [Status], [UserCode], GETDATE(), [Current_Planned_Qty]
			FROM @ParameterTable_PC

			DELETE FROM Assy_RunningPart_PlungerCrimping WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
			INSERT INTO Assy_RunningPart_PlungerCrimping(LineCode, DateCode, Assy_PartNo, ProductionOrderNo, Assy_Mode, 
			CreatedDate, CreatedBy, CurrentPlannedQty, ProfitCenterCode)							 
			SELECT Top 1 LineCode, DateCode, PartNumber, ProdOrderNo, Mode
			, GETDATE(), UserCode, Current_Planned_Qty, ProfitCenterCode					
			FROM @ParameterTable_PC	
			
			SELECT @ReturnValue = 'DATA SAVED', @ReturnInt = 1

			COMMIT TRAN 
		END TRY
		BEGIN CATCH
			--CATCH BLOCK BEGINS
			SET @RETURNVALUE =	CAST(ISNULL(ERROR_NUMBER(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_SEVERITY(),0)AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_STATE(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_PROCEDURE(),'') AS VARCHAR(200)) + '|' + 
								CAST(ISNULL(ERROR_LINE(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_MESSAGE(),'') AS VARCHAR(1500))
			SET @ReturnInt = 2
			ROLLBACK TRAN
			Raiserror(@ReturnValue, 16, 1)
		END CATCH
		RETURN
	END
				
	ELSE IF @Condition = 'VALIDATE_RUNNING_PART'
	BEGIN
		BEGIN TRY
			BEGIN TRAN
			Declare @ProdctOrderNo_Production As VARCHAR(20) = '', @ProdctOrderNo_Plunger_Crimping As VARCHAR(20) = '', @PartNo_Prodution As VARCHAR(20) = '', @PartNo_PlungerCrimping As VARCHAR(20) = ''

			SELECT @ProdctOrderNo_Production = ProductionOrderNo, @PartNo_Prodution = Assy_PartNo
				FROM Assy_RunningPart (NOLOCK) WHERE LineCode = @LineCode

			SELECT @ProdctOrderNo_Plunger_Crimping = ProductionOrderNo, @PartNo_PlungerCrimping = Assy_PartNo
			FROM Assy_RunningPart_PlungerCrimping WHERE LineCode = @LineCode

			IF ((@ProdctOrderNo_Production = @ProdctOrderNo_Plunger_Crimping) AND (@PartNo_Prodution = @PartNo_PlungerCrimping))
			BEGIN
				SELECT @ReturnValue = 'OK', @ReturnInt = 1	
			END
			ELSE
			BEGIN
				SELECT @ReturnValue = 'SELECTED RUNNING PART NEED TO BE THE RUNNING PART IN PRODUCTION', @ReturnInt = 0	
			END

			COMMIT TRAN 
		END TRY
		BEGIN CATCH
			--CATCH BLOCK BEGINS
			SET @RETURNVALUE =	CAST(ISNULL(ERROR_NUMBER(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_SEVERITY(),0)AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_STATE(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_PROCEDURE(),'') AS VARCHAR(200)) + '|' + 
								CAST(ISNULL(ERROR_LINE(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_MESSAGE(),'') AS VARCHAR(1500))
			SET @ReturnInt = 2
			ROLLBACK TRAN
			Raiserror(@ReturnValue, 16, 1)
			END CATCH
		RETURN
	END
		
	ELSE IF @Condition = 'READ_RUNNING_PART_DETAILS_FROM_MAINSERVER'
	BEGIN			 
		BEGIN TRY
			--	Print '---------1----------'
			Declare @ExecQuery As NVARCHAR(MAX), @LinkServerName VARCHAR(2000), @ShiftQtyUpdated BIT = 0, 
			@RunDateCode CHAR(4) = NULL, @RunPartNo VARCHAR(60) = NULL,	@CustomerPartNo VARCHAR(60) = NULL,
			@ProductionOrder VARCHAR(60) = NULL,@kanbanid varchar(100)
				
			SELECT @LinkServerName = LinkServerName + '.' + DataBaseName FROM Assy_LinkServer_Dtl (NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			--	Print '---------2----------'
			SELECT @ExecQuery = @LinkServerName + '.dbo.Assy_RunningPart WITH (NOLOCK) WHERE LineCode = ' + ''''+ @LineCode + ''' AND ProfitCenterCode = ' + ''''+ @ProfitCenterCode + ''' ' 
			 
			SET @ExecQuery = N' SELECT Top 1 LineCode, 
					DateCode, 
					Assy_PartNo, 
					ProductionOrderNo, 
					CurrentPlannedQty, 
					Assy_Mode, 
					CreatedDate, 
					CreatedBy, 
					ModifiedOn, 
					ModifiedBy, 
					isauthorized, 
					istallySnoozed, Boost_Ratio, Servo_PartNo, TMC_PartNo, PartType, ProfitCenterCode, CustomerPartNo,Kanbanid FROM ' + @ExecQuery

			IF OBJECT_ID('tempdb..#Temp_Assy_RunningPart') IS NOT NULL
			BEGIN
				Drop Table #Temp_Assy_RunningPart
			END
				
			SELECT LineCode, 
				DateCode, 
				Assy_PartNo, 
				ProductionOrderNo, 
				CurrentPlannedQty, 
				Assy_Mode, 
				CreatedDate, 
				CreatedBy, 
				ModifiedOn, 
				ModifiedBy, 
				isauthorized, 
				istallySnoozed, Boost_Ratio, Servo_PartNo, TMC_PartNo, PartType, ProfitCenterCode, CustomerPartNo,Kanbanid INTO #Temp_Assy_RunningPart FROM Assy_RunningPart (NOLOCK) WHERE 1 = 2
								
			INSERT INTO #Temp_Assy_RunningPart
			EXEC (@ExecQuery)
			--Print '---------3----------'

			SELECT Top 1 @RunDateCode = DateCode, @RunPartNo = Assy_PartNo ,@Target=CurrentPlannedQty,@CustomerPartNo=CustomerPartNo,
			@ProductionOrder=ProductionOrderNo,@kanbanid=Kanbanid
			FROM #Temp_Assy_RunningPart WITH (NOLOCK) WHERE LineCode = @LineCode --Order By CreatedDate desc
			-- RESET POKA YOKE IF PART IS DIFFERENT OR new Date code
			SELECT Top 1 @CurRunningPartNo = ISNULL(Assy_PartNo, ''), @CurRunningDateCode = ISNULL(DateCode, '') FROM #Temp_Assy_RunningPart (NOLOCK)
				WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode AND Assy_Mode IN ('Production', 'Rework') --Order By CreatedDate DESC
			
			--- Added By Sachin 20190303
			-- Send TS To MES Server During Set Parameter
			if exists(select top 1 1 from RoutingConfigDetails(nolock) where ProfitCenterCode=@ProfitCenterCode
			and LineCode=@LineCode and KeyType='IsPushSetParameterDataIntoMEServer' and ISNULL(KeyValue,'0')='1'
			)
			begin
			
				declare @IsPokeYokeRequiired bit = 0
				DECLARE @CurrentDateCode varchar(4)=''

				EXEC ASSY_PROC_DATECODE @PROFITCENTERCODE=@ProfitCenterCode,
				@RETURNVALUE= @CurrentDateCode OUTPUT

				IF EXISTS
				(
					SELECT 1 FROM LineMst LM WITH (NOLOCK) INNER JOIN RoutingConfigLineWise RL WITH (NOLOCK) 
					ON LM.ProfitCenterCode = RL.ProfitCenterCode AND LM.LineCode = RL.LineCode
					LEFT OUTER JOIN Assy_Scan_OK SO WITH (NOLOCK) ON RL.LineCode = SO.LineCode AND RL.OperationCode = SO.OperationCode AND RL.MachineCode = SO.MachineCode
					WHERE LM.ProfitCenterCode = @ProfitCenterCode
					AND LM.LineCode = @LineCode AND ISNULL(LM.isActive, 0) = 1 AND ISNULL(LM.isPokaYokeMandatory, 0) = 1 AND ISNULL(RL.POKA_YOKE_ALLOWED, 0) = 1
					AND RL.OperationRequired = 1 AND Rl.Traceability = 1 AND ISNULL(SO.isPokaYokeCompleted, 0) = 0
				)
				BEGIN
					set @IsPokeYokeRequiired = 1
				END
				ELSE
				begin
					set @IsPokeYokeRequiired = 0;
				end
				
				SELECT TOP 1 @MachineLinkServerName = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE 
				AND LineCode = @LINECODE AND KeyType = 'MachineDBLinkServerName' AND STS_CD = 0
				
				if(ISNULL(@MachineLinkServerName,'') = '' )
				begin
					SET @ReturnValue = 'Machine Link Server Name Configuration Not Found !! [RoutingConfigDetails Key: MachineDBLinkServerName] '
					 SET @ReturnInt = 2
					return
				end

				SELECT TOP 1 @MachineLinkServerDB = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE 
				AND LineCode = @LINECODE AND KeyType = 'MachineDBLinkServerDB' AND STS_CD = 0

				if(ISNULL(@MachineLinkServerDB,'') = '' )
				begin
					 SET @ReturnValue = 'Machine Link Server Database Configuration Not Found !! [RoutingConfigDetails Key: MachineDBLinkServerDB]'
					 SET @ReturnInt = 2
					 return
				end

				SELECT TOP 1 @MachineDBTableName = KeyValue FROM RoutingConfigDetails (NOLOCK) 
				WHERE ProfitCenterCode = @PROFITCENTERCODE 
				AND LineCode = @LINECODE AND KeyType = 'MachineDBSetParameterTableName' AND STS_CD = 0				

				if(ISNULL(@MachineDBTableName,'') = '' )
				begin
					SET @ReturnValue = 'Link Server Set Parameter Table Name Configuration Not Found !! [RoutingConfigDetails Key: MachineDBSetParameterTableName] '
					SET @ReturnInt = 2
					
					return
				end
				
				SELECT TOP 1 @LinkServerType = KeyValue FROM RoutingConfigDetails (NOLOCK) 
				WHERE ProfitCenterCode = @PROFITCENTERCODE 
				AND LineCode = @LINECODE AND KeyType = 'LinkServerType' AND STS_CD = 0				

				if(ISNULL(@LinkServerType,'') = '' )
				begin
					SET @ReturnValue = 'Link Server Type Parameter Configuration Not Found !! [RoutingConfigDetails Key: LinkServerType] '
					SET @ReturnInt = 2
					
					return
				end

				begin try
				declare @s sysname=REPLACE(REPLACE(@MachineLinkServerName,'[',''),']','')
				exec sys.sp_testlinkedserver @s
				end try
				begin catch
				
				SET @ReturnValue = 'Kindly Check, Not Able To Connect MES SQL Server !!! '+@MachineLinkServerName
				SET @ReturnInt = 2
				return
				end catch
				
				select Top 1 @HandInfo = ISNULL(LabelDataValue,'') from Assy_Coupling_LabelInfo_Mst(nolock)
				where ProfitCenterCode=@PROFITCENTERCODE and PartNo=@RunPartNo 
				and LabelDataName='HAND'

				declare @dynamic_query varchar(max) = ''

				if(@LinkServerType='MYSQL')
				begin
					SET @MachineLinkServer =  @MachineLinkServerName+'...'+@MachineLinkServerDB
					set @MachineLinkServer = REPLACE(@MachineLinkServer,'TABLE_NAME',@MachineDBTableName)

					set @RunPartNoWithPrefix = right(REPLICATE('0',10)+@RunPartNo,10)
					--set @RunPartNoWithPrefix = left(@RunPartNo+REPLICATE('0',10),10)
				
					set @dynamic_query = '
				
					update ' + ISNULL(@MachineLinkServer,'') + ' set STS_CD = CONVERT(varchar, 1)

					insert into '+ISNULL(@MachineLinkServer,'')+'(ProfitcenterCode,LineCode,WorkOrderNumber,
					Model,Model_with_prefix,SetParameterDateCode,PokaYoke,[Target],
					Live_DateCode,CustomerPartNumber,Hand,Ent_Stamp,STS_CD)	
					values('
					+ '''' +ISNULL(@PROFITCENTERCODE,'')+''''+','
					+ '''' +ISNULL(@LINECODE,'')+''''+','
					+ '''' +ISNULL(@ProductionOrder,'')+''''+','
					+ '''' +ISNULL(@RunPartNo,'')+''''+','
					+ '''' +ISNULL(@RunPartNoWithPrefix,'')+''''+','
					+ '''' +ISNULL(@RunDateCode,'') + '''' + ',' 
					+ '''' +CONVERT(varchar, ISNULL(@IsPokeYokeRequiired,0))+ '''' +',' 
					+ '''' +CONVERT(varchar,ISNULL(@Target,0)) + '''' +  +',' 
					+ '''' +CONVERT(varchar,ISNULL(@CurrentDateCode,'')) + '''' +  +',' 
					+ '''' +CONVERT(varchar,ISNULL(@CustomerPartNo,'')) + '''' +  +',' 
					+ '''' +CONVERT(varchar,ISNULL(@HandInfo,'')) + '''' +  +',' 
					+	'GETDATE()' +  +',' 
					+ '0'+
					+')

					'

				end

				if(@LinkServerType='MSSQL')
				begin
				
					
					SET @MachineLinkServer =  @MachineLinkServerName+'.'+@MachineLinkServerDB
					set @MachineLinkServer = REPLACE(@MachineLinkServer,'TABLE_NAME',@MachineDBTableName)
					
					set @RunPartNoWithPrefix = right(REPLICATE('0',10)+@RunPartNo,10)
					--set @RunPartNoWithPrefix = left(@RunPartNo+REPLICATE('0',10),10)
					
					set @dynamic_query = '
				
					update ' + ISNULL(@MachineLinkServer,'') + ' set STS_CD = CONVERT(varchar, 1)

					insert into '+ISNULL(@MachineLinkServer,'')+'(ProfitcenterCode,LineCode,WorkOrderNumber,
					Model,Model_with_prefix,SetParameterDateCode,PokaYoke,[Target],
					Live_DateCode,CustomerPartNumber,Hand,Ent_Stamp,STS_CD)	
					values('
					+ '''' +ISNULL(@PROFITCENTERCODE,'')+''''+','
					+ '''' +ISNULL(@LINECODE,'')+''''+','
					+ '''' +ISNULL(@ProductionOrder,'')+''''+','
					+ '''' +ISNULL(@RunPartNo,'')+''''+','
					+ '''' +ISNULL(@RunPartNoWithPrefix,'')+''''+','
					+ '''' +ISNULL(@RunDateCode,'') + '''' + ',' 
					+ '''' +CONVERT(varchar, ISNULL(@IsPokeYokeRequiired,0))+ '''' +',' 
					+ '''' +CONVERT(varchar,ISNULL(@Target,0)) + '''' +  +',' 
					+ '''' +CONVERT(varchar,ISNULL(@CurrentDateCode,'')) + '''' +  +',' 
					+ '''' +CONVERT(varchar,ISNULL(@CustomerPartNo,'')) + '''' +  +',' 
					+ '''' +CONVERT(varchar,ISNULL(@HandInfo,'')) + '''' +  +',' 
					+	'GETDATE()' +  +',' 
					+ '0'+
					+')

					'
				end
				
				--print @dynamic_query
			
				exec(@dynamic_query)
				
				insert into OC003_TS_SYSTEM_INFO_LOG (ProfitcenterCode,LineCode,WorkOrderNumber,
				Model,Model_with_prefix,SetParameterDateCode,PokaYoke,[Target],
				Live_DateCode,CustomerPartNumber,Hand,Ent_Stamp,STS_CD,Audit_Insert)	
				values(ISNULL(@PROFITCENTERCODE,''),ISNULL(@LINECODE,''),ISNULL(@ProductionOrder,''),
				ISNULL(@RunPartNo,''),ISNULL(@RunPartNoWithPrefix,''),ISNULL(@RunDateCode,''),
				ISNULL(@IsPokeYokeRequiired,0),ISNULL(@Target,0),ISNULL(@CurrentDateCode,''),
				ISNULL(@CustomerPartNo,''),@HandInfo,GETDATE(),0,GETDATE()
				)


			end
			-- Ended By Sachin 20190303

			
			
			-- TALLY CHART BYPASS FUNCTIONALITY, ADDED By Ravi ON 29/03/2015
			--IF EXISTS
			--(
			--	SELECT 1 FROM Assy_Routing_Changed_Dtl WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode 
			--	AND LineCode = @LineCode AND (DateCode <> @RunDateCode OR (DateCode = @RunDateCode AND PartNo <>@RunPartNo))
			--)
			--BEGIN
			--	--EXEC Assy_Proc_TallyChartStatus @QueryExecuteOption = 'AUTO_TALLY_CHART', @ProfitCenterCode = @ProfitCenterCode, @LineCode = @LineCode
			--	--EXEC Assy_Proc_TallyChartStatus @QUERYEXECUTEOPTION = 'REQNOAUTH', @ProfitCenterCode = @ProfitCenterCode, @LineCode = @LineCode
			--	-- Routing Line wise changed As defined IN Super User Table
			--	--EXEC Assy_Proc_RoutingConfigLineWise_SuperUser_Control @ProfitCenterCode = @ProfitCenterCode, @LineCode = @LineCode, @IsLocalDB = 0
			--	--EXEC Assy_Proc_RoutingConfigLineWise_SuperUser_Control @ProfitCenterCode = @ProfitCenterCode, @LineCode = @LineCode, @IsLocalDB = 1

			--	DELETE FROM Assy_Routing_Changed_Dtl WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode

			--	SET @ExecQuery = N' INSERT INTO ' + @LinkServerName + '.dbo.Assy_RunningPart (LineCode, 
			--					DateCode, 
			--					Assy_PartNo, 
			--					ProductionOrderNo, 
			--					CurrentPlannedQty, 
			--					Assy_Mode, 
			--					CreatedDate, 
			--					CreatedBy, 
			--					ModifiedOn, 
			--					ModifiedBy, 
			--					isauthorized, 
			--					istallySnoozed, Boost_Ratio, Servo_PartNo, TMC_PartNo, PartType, ProfitCenterCode, CustomerPartNo)
									
			--					SELECT Top 1 LineCode, 
			--					DateCode, 
			--					Assy_PartNo, 
			--					ProductionOrderNo, 
			--					CurrentPlannedQty, 
			--					Assy_Mode, 
			--					CreatedDate, 
			--					CreatedBy, 
			--					ModifiedOn, 
			--					ModifiedBy, 
			--					isauthorized, 
			--					istallySnoozed, Boost_Ratio, Servo_PartNo, TMC_PartNo, PartType, ProfitCenterCode, CustomerPartNo FROM #Temp_Assy_RunningPart (NOLOCK) WHERE 
			--	LineCode = ' + ''''+ @LineCode + '''' + ' AND ProfitCenterCode = ' + ''''+ @ProfitCenterCode + ''' AND Assy_Mode = ''PRODUCTION'' Order By CreatedDate DESC'
			--	Print @ExecQuery
			--	EXEC (@ExecQuery)

			--END

			SET @ExecQuery = @LinkServerName + '.dbo.Assy_ProductionOrder_ParameterSetting WITH (NOLOCK) WHERE LineCode = ' + ''''+ @LineCode + ''''
		
			SET @ExecQuery = N'SELECT Top 1 * FROM ' + @ExecQuery
			IF OBJECT_ID('tempdb..#Temp_Assy_ProductionOrder_ParameterSetting') IS NOT NULL
			BEGIN
				Drop Table #Temp_Assy_ProductionOrder_ParameterSetting
			END	
		
			SELECT * INTO #Temp_Assy_ProductionOrder_ParameterSetting FROM Assy_ProductionOrder_ParameterSetting (NOLOCK) WHERE 1 = 2
			INSERT INTO #Temp_Assy_ProductionOrder_ParameterSetting
			EXEC (@ExecQuery)

			END TRY
			BEGIN CATCH
			--CATCH BLOCK BEGINS	
			SET @RETURNVALUE =	CAST(ISNULL(ERROR_NUMBER(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_SEVERITY(),0)AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_STATE(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_PROCEDURE(),'') AS VARCHAR(200)) + '|' + 
								CAST(ISNULL(ERROR_LINE(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_MESSAGE(),'') AS VARCHAR(1500))
			SET @ReturnInt = 2			
			Raiserror(@ReturnValue, 16, 1)
			RETURN
			END CATCH

			BEGIN TRY
			BEGIN TRAN
			--Print '---------4----------'
			--Copy records FROM Assy_RunningPart data INTO Assy_RunningPart_Previous IF part number IS same.

			IF	(
					--(SELECT Top 1 ISNULL(Assy_PartNo, '') FROM Assy_RunningPart (NOLOCK) WHERE Assy_Mode IN ('Production', 'Rework') AND LineCode = @LineCode Order By CreatedDate desc) = 
					(SELECT Top 1 ISNULL(Assy_PartNo, '') FROM Assy_RunningPart (NOLOCK) WHERE Assy_Mode IN ('Production', 'Rework') AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode) = 
					(SELECT Top 1 ISNULL(Assy_PartNo, '') FROM #Temp_Assy_RunningPart)
			)
			BEGIN
				IF EXISTS(SELECT TOP 1 1 FROM TYPE_DEFINITION_XREF_DATA(NOLOCK)
				WHERE ATTRB_CD=@LineCode AND TYPE_CATEGORY_CD='LINE_ATTRB'
				AND TYPE_CD='eKanban_Enable' AND WH_CODE=@ProfitCenterCode AND ATTRB_VAL='1')
				BEGIN		
						
						INSERT INTO Assy_RunningPart_Previous
						(
							LineCode, 
							DateCode, 
							Assy_PartNo, 
							ProductionOrderNo, 
							CurrentPlannedQty, 
							Assy_Mode, 
							CreatedDate, 
							CreatedBy, 
							ModifiedOn, 
							ModifiedBy, 
							isauthorized, 
							istallySnoozed, 
							ProducedQty, 
							BalanceQty,
							KanbanId
						)
						SELECT RP.LineCode, 
							RP.DateCode, 
							Assy_PartNo, 
							ProductionOrderNo, 
							RP.CurrentPlannedQty, 
							Assy_Mode, 
							PP.timestamp, 
							CreatedBy,
							CreatedDate, 
							CreatedBy, 
							isauthorized, 
							istallySnoozed, 
							PP.ProductionQty, 
							PP.BalanceQty,
							RP.KanbanId
						FROM Assy_RunningPart (NOLOCK) RP
							INNER JOIN Assy_ProductionOrder_ParameterSetting (NOLOCK) PP ON RP.Assy_PartNo = PP.PartNumber 
								AND RP.Assy_Mode = PP.Mode AND RP.DateCode = PP.DateCode AND RP.LineCode = PP.LineCode 											
									WHERE Assy_Mode IN ('Production', 'Rework') AND RP.LineCode = @LineCode	
					
					end
				--Changed By ravi ON 11-02-2016
				else IF EXISTS 
				(
					SELECT ISNULL(Assy_PartNo, '') FROM Assy_RunningPart (NOLOCK) WHERE Assy_Mode IN ('Production', 'Rework') AND LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
					AND ISNULL(PrintedQty, 0) > 0 --Order By CreatedDate DESC
				)
				BEGIN						
					IF EXISTS
					(
						SELECT 1 FROM Assy_RunningPart_Previous WITH (NOLOCK) WHERE LineCode = @LineCode
					)
					BEGIN
						UPDATE RPP SET RPP.CurrentPlannedQty = (RPP.CurrentPlannedQty + RP.CurrentPlannedQty) FROM Assy_RunningPart_Previous (NOLOCK) RPP
						INNER JOIN Assy_RunningPart (NOLOCK) RP ON RP.LineCode = RPP.LineCode AND RP.Assy_PartNo = RPP.Assy_PartNo 
						AND RP.DateCode = RPP.DateCode AND RP.Assy_Mode = RPP.Assy_Mode 
						WHERE RPP.LineCode = @LineCode AND ISNULL(RP.PrintedQty, 0) > 0
					END
					ELSE
					BEGIN
						DELETE FROM Assy_RunningPart_Previous
						INSERT INTO Assy_RunningPart_Previous
						(
							LineCode, 
							DateCode, 
							Assy_PartNo, 
							ProductionOrderNo, 
							CurrentPlannedQty, 
							Assy_Mode, 
							CreatedDate, 
							CreatedBy, 
							ModifiedOn, 
							ModifiedBy, 
							isauthorized, 
							istallySnoozed, 
							ProducedQty, 
							BalanceQty,
							KanbanId
						)
						SELECT RP.LineCode, 
							RP.DateCode, 
							Assy_PartNo, 
							ProductionOrderNo, 
							RP.CurrentPlannedQty, 
							Assy_Mode, 
							CreatedDate, 
							CreatedBy,
							CreatedDate, 
							CreatedBy, 
							isauthorized, 
							istallySnoozed, 
							PP.ProductionQty, 
							PP.BalanceQty,
							KanbanId
						FROM Assy_RunningPart (NOLOCK) RP
							INNER JOIN Assy_ProductionOrder_ParameterSetting (NOLOCK) PP ON RP.Assy_PartNo = PP.PartNumber 
								AND RP.Assy_Mode = PP.Mode AND RP.DateCode = PP.DateCode AND RP.LineCode = PP.LineCode 											
									WHERE Assy_Mode IN ('Production', 'Rework') AND RP.LineCode = @LineCode
					END
				END
			END
			ELSE
			BEGIN
				DELETE FROM Assy_RunningPart_Previous
			END
			--Print '---------5----------'
			IF EXISTS
			(
				SELECT 1 FROM Assy_RunningPart (NOLOCK) WHERE LineCode = @LineCode AND ISNULL(PrintedQty, 0) > 0 AND ProfitCenterCode = @ProfitCenterCode
			)
			BEGIN					
				SELECT @ShiftQtyUpdated = 1
			END
			--Print '---------6----------'
			------------INSERT INTO Local Assy_RunningPart -------------------------------------------
			
			SELECT @isPokaYokeMandatory = isPokaYokeMandatory, @Allow2Parts = isnull(Allow2Parts,0)
				 FROM LineMst WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode

			--IF EXISTS
			--(
			--	SELECT 1 FROM LineMst WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(isPokaYokeMandatory, 0) = 0
			--)
			IF ISNULL(@isPokaYokeMandatory,0) = 0
			BEGIN
				IF EXISTS
				(
					SELECT 1 FROM Assy_RunningPart WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode 
						AND Assy_PartNo = @CurRunningPartNo AND DateCode = @CurRunningDateCode
				)
				BEGIN
					SELECT @IsPokaYokeAlreadyBypassedForThisPart = 1
				END
			END		

			IF EXISTS
			(
				SELECT 1 FROM #Temp_Assy_RunningPart (NOLOCK) WHERE LineCode = @LineCode
			)
			BEGIN
				--Print 'before deleting'				

				IF ISNULL(@Allow2Parts,0) = 1
				BEGIN
					DELETE FROM Assy_Barcode_Printed_Counter WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
					SELECT @ExecQuery = @LinkServerName + '.dbo.Assy_RunningPartFamily WHERE LineCode = ' + ''''+ @LineCode + ''' AND ProfitCenterCode = ' + ''''+ @ProfitCenterCode + ''' ' 
			 
					SET @ExecQuery = N' SELECT LineCode,Datecode,Assy_PartNo,ProductionOrderNo,CurrentPlannedQty,Assy_Mode,CreatedDate,CreatedBy,
					ModifiedOn,ModifiedBy,IsAuthorized,IsTallySnoozed,PrintedQty,Boost_Ratio,Servo_PartNo,TMC_PartNo,PartType,ProfitCenterCode,CustomerPartNo 
					FROM ' + @ExecQuery
					DELETE FROM Assy_RunningPartFamily
					INSERT INTO Assy_RunningPartFamily (LineCode,Datecode,Assy_PartNo,ProductionOrderNo,CurrentPlannedQty,Assy_Mode,CreatedDate,CreatedBy,
					ModifiedOn,ModifiedBy,IsAuthorized,IsTallySnoozed,PrintedQty,Boost_Ratio,Servo_PartNo,TMC_PartNo,PartType,ProfitCenterCode,CustomerPartNo)
					EXEC (@ExecQuery)
					
					--Added by Ravi on 28-06-17, to resolve materail feeding issue
					if exists
					( 
					       select 1 from Assy_MachineWise_RunningPart with(nolock) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
							AND OperationCode = dbo.Assy_FN_Get_FinalViewing_OperationCode_From_LineCode(@ProfitCenterCode,@LineCode)
					)
					begin
							UPDATE Assy_MachineWise_RunningPart SET PartNo = @CurRunningPartNo,UpdatedDate=getdate() WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
							AND OperationCode =dbo.Assy_FN_Get_FinalViewing_OperationCode_From_LineCode(@ProfitCenterCode,@LineCode)
					end
					else 
					   begin
							insert into Assy_MachineWise_RunningPart(ProfitCenterCode,LineCode,OperationCode,MachineCode ,PartNo,CreatedDate)
							select @ProfitCenterCode,@LineCode,dbo.Assy_FN_Get_FinalViewing_OperationCode_From_LineCode(@ProfitCenterCode,@LineCode)
							,dbo.Assy_FN_Get_FinalViewing_MachineCode_From_LineCode(@ProfitCenterCode,@LineCode),@CurRunningPartNo,getdate()

					   end

				
					--SELECT * FROM Assy_RunningPartFamily
				END

			--Added for 2 Parts Poka Yoke	
			--IF(
			--		(SELECT Top 1 ISNULL(Assy_PartNo, '') FROM Assy_RunningPart (NOLOCK) WHERE  LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode) <>
			--		(SELECT Top 1 ISNULL(Assy_PartNo, '') FROM #Temp_Assy_RunningPart) and  ISNULL(@Allow2Parts,0) = 1
			--  )
			--BEGIN
			--		exec Assy_Proc_ProductionOrder @Condition ='Reset_PokaYoke_After_Change_Over',@ProfitCenterCode=@ProfitCenterCode
			--		,@LineCode =@LineCode ,@RealTimeRunningPartNo=@RunPartNo,@Allow2Parts=1
			--end

				DELETE FROM Assy_RunningPart WHERE ProfitCenterCode = @ProfitCenterCode

				INSERT INTO Assy_RunningPart
				(
					LineCode
					, DateCode
					, Assy_PartNo
					, ProductionOrderNo
					, CurrentPlannedQty
					, Assy_Mode
					, CreatedDate
					, CreatedBy
					, ModifiedOn
					, ModifiedBy
					, isauthorized
					, istallySnoozed, Boost_Ratio, Servo_PartNo, TMC_PartNo, PartType, ProfitCenterCode, CustomerPartNo,Kanbanid
				)
				SELECT 
					LineCode
					, DateCode
					, Assy_PartNo
					, ProductionOrderNo
					, CurrentPlannedQty
					, Assy_Mode
					, CreatedDate
					, CreatedBy
					, ModifiedOn
					, ModifiedBy
					, isauthorized
					, istallySnoozed, Boost_Ratio, Servo_PartNo, TMC_PartNo, PartType, ProfitCenterCode, CustomerPartNo,kanbanid
				FROM #Temp_Assy_RunningPart (NOLOCK) 
				WHERE LineCode = @LineCode
			END
			--Print '---------7----------'
			------------INSERT INTO Local Assy_ProductionOrder_ParameterSetting -------------------------------------------
			IF EXISTS
			(
				SELECT 1 FROM #Temp_Assy_ProductionOrder_ParameterSetting (NOLOCK) WHERE LineCode = @LineCode
			)
			BEGIN
				--Print 'before deleting'
				DELETE FROM Assy_ProductionOrder_ParameterSetting
				INSERT INTO Assy_ProductionOrder_ParameterSetting
				(
					ProfitCenterCode
					, LineCode
					, StationCode
					, DateCode
					, ProdOrderNo
					, ProdOrderDate
					, PartNumber
					, PlannedQty
					, ProductionQty
					, BalanceQty
					, ProdOrderPriority
					, CurrentPlannedQty
					, Mode
					, Remarks
					, Status
					, UserCode
					, Timestamp
				)
 
				SELECT 
					ProfitCenterCode
					, LineCode
					, StationCode
					, DateCode
					, ProdOrderNo
					, ProdOrderDate
					, PartNumber
					, PlannedQty
					, ProductionQty
					, BalanceQty
					, ProdOrderPriority
					, CurrentPlannedQty
					, Mode
					, Remarks
					, Status
					, UserCode
					, Timestamp
				FROM #Temp_Assy_ProductionOrder_ParameterSetting										
			END
			--Print '---------8----------'
			--change By ravi ON 10-09-15
			SELECT @Mode = Assy_Mode FROM Assy_RunningPart (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
		
			IF @Mode IN ('Production', 'Rework')
			BEGIN
				EXEC ASSY_Proc_ModelChanged @Operation = 'UPDATE', @LineCode = @LineCode, @ProfitCenterCode = @ProfitCenterCode
			END
		
			EXEC Assy_Proc_Barcode_Printed_Counter @Condition = 'UPDATE_CURRENTPLANNEDQTY_FOR_SAMEPART', @LineCode = @LineCode, @ProfitCenterCode = @ProfitCenterCode								
			 
			IF (@ShiftQtyUpdated = 0)				
			BEGIN
				EXEC Assy_Proc_ShiftQty_Update @Condition = 'Update_Planned_Qty', @ProfitCenterCode = @ProfitCenterCode, @LineCode = @LineCode, @IsLabelPrtForSelPart = 0
			END
			ELSE
				EXEC Assy_Proc_ShiftQty_Update @Condition = 'Update_Planned_Qty', @ProfitCenterCode = @ProfitCenterCode, @LineCode = @LineCode, @IsLabelPrtForSelPart = 1

			IF @IsPokaYokeAlreadyBypassedForThisPart = 0 and ISNULL(@Allow2Parts,0)=0
			BEGIN
				IF NOT EXISTS
				(
					SELECT 1 FROM Assy_PokaYoke_Last_Tested_Part WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
						AND DateCode = @CurRunningDateCode AND PartNo = @CurRunningPartNo
				)
				BEGIN
					EXEC Assy_Proc_LineMst_SuperUser_Control @ProfitCenterCode = @ProfitCenterCode, @LineCode = @LineCode, @IsLocalDB = 1
					--DELETE PokaYoke_Completed_Dtl IF DateCode IS old
					IF EXISTS(SELECT 1 FROM Assy_PokaYoke_Completed_Dtl WITH (NOLOCK) WHERE DateCode! = @CurRunningDateCode)
						Truncate Table Assy_PokaYoke_Completed_Dtl 	

					DELETE Assy_LineAssyStatus_Running WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode AND DateCode = 'PKYK'
					UPDATE Assy_Scan_OK SET isPokaYokeCompleted = 0 WHERE LineCode = @LineCode
					UPDATE Assy_POKAYOKE SET isActive = 1 WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(isActive, 0) = 0
					--UPDATE DeActive poka Yoke WITH Active
					EXEC Assy_Proc_UpdatePokaYokeStatus @Condition = 'UPDATE_POKAYOKE_COMPLETED_FOR_NA_PART', @LineCode = @LineCode, @ProfitCenterCode = @ProfitCenterCode, @ISByPassPokaYoke = 1
					EXEC Assy_Proc_PokaYoke_Last_Tested_Part @Condition = 'DELETE', @ProfitCenterCode = @ProfitCenterCode, @LineCode = @LineCode
				END		
			END

			IF EXISTS (SELECT 1 FROM Assy_RunningPart (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND Assy_Mode IN ('Production', 'Rework') AND PartType = 'STMC')
			BEGIN
				SELECT Top 1 @ReturnValue = ISNULL(PartType, '') + '|' + ISNULL(TMC_PartNo, '') + '|' + ISNULL(Servo_PartNo, '') FROM Assy_RunningPart 
				(NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND Assy_Mode IN ('Production', 'Rework') AND PartType = 'STMC'
			END
			ELSE
				SELECT Top 1 @ReturnValue = ISNULL(PartType, '') FROM Assy_RunningPart (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND Assy_Mode IN ('Production', 'Rework') AND PartType ! = 'STMC' 
						
			SET @ReturnInt = 1
			--Print '---------9----------'
			COMMIT TRAN
		END TRY
		BEGIN CATCH
			--CATCH BLOCK BEGINS
	
			SET @RETURNVALUE =	CAST(ISNULL(ERROR_NUMBER(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_SEVERITY(),0)AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_STATE(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_PROCEDURE(),'') AS VARCHAR(200)) + '|' + 
								CAST(ISNULL(ERROR_LINE(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_MESSAGE(),'') AS VARCHAR(1500))
			SET @ReturnInt = 2
			ROLLBACK TRAN
			Raiserror(@ReturnValue, 16, 1)
		END CATCH
		RETURN	
	END
	
	--DELTE CURRENT RUNNING PATR FROM main server
	ELSE IF @Condition = 'DELTE_CURRENT_RUNNING_PATR_FROM_MAIN_SERVER'
	BEGIN
		BEGIN TRY
			BEGIN TRAN
				UPDATE Assy_RunningPart SET isauthorized = 1 WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
				DELETE Assy_RunningPart WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
				DELETE FROM Assy_ProductionOrder_ParameterSetting WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode 
				DELETE FROM Assy_RunningPart_Previous WHERE LineCode = @LineCode
			COMMIT TRAN
		END TRY
		BEGIN CATCH
			--CATCH BLOCK BEGINS
			SET @RETURNVALUE =	CAST(ISNULL(ERROR_NUMBER(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_SEVERITY(),0)AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_STATE(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_PROCEDURE(),'') AS VARCHAR(200)) + '|' + 
								CAST(ISNULL(ERROR_LINE(),0) AS VARCHAR(5)) + '|' + 
								CAST(ISNULL(ERROR_MESSAGE(),'') AS VARCHAR(1500))
			SET @ReturnInt = 2
			ROLLBACK TRAN
			Raiserror(@ReturnValue, 16, 1)
		END CATCH
		RETURN
	END	

	ELSE IF @Condition = 'INSERT_INTO_ASSY_RUNNINGPART_PREVIOUS_IN_MAINSERVER'
	BEGIN
		DELETE FROM Assy_RunningPart_Previous WHERE LineCode = @LineCode
		INSERT INTO Assy_RunningPart_Previous
		(
			LineCode, 
			DateCode, 
			Assy_PartNo, 
			ProductionOrderNo, 
			CurrentPlannedQty, 
			Assy_Mode, 
			CreatedDate, 
			CreatedBy, 
			ModifiedOn, 
			ModifiedBy, 
			isauthorized, 
			istallySnoozed, 
			ProducedQty, 
			BalanceQty,
			KanbanId
		)
		SELECT @LineCode, 
			@DateCode, 
			@PartNumber, 
			@ProdOrderNo, 
			@Current_Planned_Qty, 
			@Mode, 
			@CreatedDate, 
			@CreatedBy, 
			@ModifiedOn, 
			@ModifiedBy, 
			0, 
			0, 
			@ProducedQty, 
			@BalanceQty,
			@P_KanbanId
					
		SELECT @ReturnInt = 1
		RETURN
	END

	ELSE IF @Condition = 'READ_ASSY_RUNNINGPART_PREVIOUS_FROM_LOCALSERVER'
	BEGIN				
		SELECT top 1 RP.LineCode, 
			RP.DateCode, 
			RP.Assy_PartNo, 
			RP.ProductionOrderNo, 
			RP.CurrentPlannedQty, 
			RP.Assy_Mode, 
			RP.CreatedDate, 
			RP.CreatedBy, 
			RP.ModifiedOn, 
			RP.ModifiedBy, 
			RP.isauthorized, 
			RP.istallySnoozed, 
			RP.ProducedQty, 
			RP.BalanceQty,
			ISNULL(RP.KanbanId,'') as KanbanId  
		FROM Assy_RunningPart_Previous (NOLOCK) RP															
		WHERE RP.Assy_Mode IN ('Production', 'Rework') AND RP.LineCode = @LineCode
		order by RP.CreatedDate desc 
		
		SELECT @ReturnInt = 1
		RETURN
	END

	ELSE IF @Condition = 'Read_Barcode_Label_Info'
	BEGIN
		IF EXISTS (SELECT Top 1 1 FROM Assy_RunningPart (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND Assy_Mode IN ('Production', 'Rework') AND PartType = 'STMC')
		BEGIN
			SELECT CLM.PartNo [Part Number], RP.CustomerPartNo [Customer Part Number], LabelDataName [Name], LabelDataValue Value 
			FROM Assy_Coupling_LabelInfo_Mst (NOLOCK) CLM INNER JOIN Assy_RunningPart (NOLOCK) RP 
			ON CLM.ProfitCenterCode = RP.ProfitCenterCode AND CLM.PartNo = RP.Assy_PartNo AND CLM.CustomerPartNo = RP.CustomerPartNo 
			WHERE NOT ISNULL(CLM.LabelDataValue, '') = ''
			
			SELECT @ReturnInt = 1
			RETURN
		END
	END
	
	ELSE IF @Condition = 'GET_CUSTOMER_PARTNUMBER'
	BEGIN
		IF EXISTS (SELECT 1 FROM Assy_Coupling_LabelInfo_Mst (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND PartNo = @PartNumber)
			SELECT DISTINCT ISNULL(CustomerPartNo, '') CustomerPartNo FROM Assy_Coupling_LabelInfo_Mst (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND PartNo = @PartNumber
	END
	
	--Added By Ravi ON 21/12/2015 for showing message- Do POKA Yoke 
	ELSE IF @Condition = 'DO_POKAYOKE'
	BEGIN
		--Added By Rashid For Poka Yoke disable IN Rework Mode ON 30th June 2016
		IF NOT EXISTS (SELECT 1 FROM Assy_Rework_PokaYoke_Status WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode)
		BEGIN
			INSERT INTO Assy_Rework_PokaYoke_Status(ProfitCenterCode, LineCode, PokaYokeMandatoryStatus, Ent_TimeStamp)
			SELECT @ProfitCenterCode, @LineCode, 0, GETDATE()
		END

		IF EXISTS (SELECT 1 FROM LineMst WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(isPokaYokeMandatory, 0) = 1)
		BEGIN
			IF EXISTS (SELECT 1 FROM Assy_Rework_PokaYoke_Status WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode)
			BEGIN
				UPDATE Assy_Rework_PokaYoke_Status
				SET PokaYokeMandatoryStatus = (SELECT ISNULL(isPokaYokeMandatory, 0) FROM LineMst WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode), 
				Ent_TimeStamp = GETDATE()
				WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			END
		END
						
		IF EXISTS (SELECT 1 FROM Assy_RunningPart WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND UPPER(Assy_Mode) = 'REWORK')
		BEGIN				
			--UPDATE Assy_Scan_OK SET isPokaYokeCompleted = 1 WHERE LineCode = @LineCode
			IF EXISTS (SELECT 1 FROM LineMst WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(isPokaYokeMandatory, 0) = 1)
			BEGIN					
				UPDATE LineMst SET isPokaYokeMandatory = 0 WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(isPokaYokeMandatory, 0) = 1
			END
		END
		ELSE
		BEGIN
			IF EXISTS (SELECT 1 FROM Assy_Rework_PokaYoke_Status WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(PokaYokeMandatoryStatus, 0) = 1)
			BEGIN
				UPDATE LineMst SET isPokaYokeMandatory = 1 WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(isPokaYokeMandatory, 0) = 0
			END
		END
		--Added By Rashid For Poka Yoke disable IN Rework Mode ON 30th June 2016
		IF EXISTS
		(
			SELECT 1 FROM LineMst LM WITH (NOLOCK) INNER JOIN RoutingConfigLineWise RL WITH (NOLOCK) 
			ON LM.ProfitCenterCode = RL.ProfitCenterCode AND LM.LineCode = RL.LineCode
			LEFT OUTER JOIN Assy_Scan_OK SO WITH (NOLOCK) ON RL.LineCode = SO.LineCode AND RL.OperationCode = SO.OperationCode AND RL.MachineCode = SO.MachineCode
			WHERE LM.ProfitCenterCode = @ProfitCenterCode
			AND LM.LineCode = @LineCode AND ISNULL(LM.isActive, 0) = 1 AND ISNULL(LM.isPokaYokeMandatory, 0) = 1 AND ISNULL(RL.POKA_YOKE_ALLOWED, 0) = 1
			AND RL.OperationRequired = 1 AND Rl.Traceability = 1 AND ISNULL(SO.isPokaYokeCompleted, 0) = 0
		)
		BEGIN
			SELECT @ReturnValue = 'DO_POKA_YOKE', @ReturnInt = 1
		END
		ELSE
			SELECT @ReturnValue = 'POKA_YOKE_NOT_REQUIRED', @ReturnInt = 1
		
		RETURN
	END

	ELSE IF @Condition = 'Check_TallyChartBypass_Status'
	BEGIN
		--Declare @execquery2 As NVARCHAR(MAX), @linkserverName2 VARCHAR(2000), @ShiftQtyUpdated2 BIT = 0, @RunDateCode2 CHAR(4) = NULL, 
		--@RunPartNo2 VARCHAR(60) = NULL
				
		--SELECT @linkserverName2 = LinkServerName+'.'+DataBaseName FROM Assy_LinkServer_Dtl (NOLOCK) 
		--WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode				
		--SET @execquery2 = @linkserverName2+'.dbo.Assy_RunningPart WITH (NOLOCK) WHERE LineCode = ' + ''''+ @LineCode + '''' 
			 
		--SET @execquery2 = N' SELECT Top 1 LineCode, 
		--					DateCode, 
		--					Assy_PartNo, 
		--					ProductionOrderNo, 
		--					CurrentPlannedQty, 
		--					Assy_Mode, 
		--					CreatedDate, 
		--					CreatedBy, 
		--					ModifiedOn, 
		--					ModifiedBy, 
		--					isauthorized, 
		--					istallySnoozed, Boost_Ratio, Servo_PartNo, TMC_PartNo, PartType, ProfitCenterCode, CustomerPartNo FROM ' + @execquery2
		--IF OBJECT_ID('tempdb..#temp_assy_runningpart2') IS NOT NULL
		--BEGIN
		--	Drop Table #temp_assy_runningpart2
		--END
				
		--SELECT LineCode, 
		--		DateCode, 
		--		Assy_PartNo, 
		--		ProductionOrderNo, 
		--		CurrentPlannedQty, 
		--		Assy_Mode, 
		--		CreatedDate, 
		--		CreatedBy, 
		--		ModifiedOn, 
		--		ModifiedBy, 
		--		isauthorized, 
		--		istallySnoozed, Boost_Ratio, Servo_PartNo, TMC_PartNo, PartType, ProfitCenterCode, CustomerPartNo INTO #temp_assy_runningpart2 FROM Assy_RunningPart (NOLOCK) WHERE 1 = 2
								
		--INSERT INTO #temp_assy_runningpart2			
		--EXEC (@execquery2)							

		-- SELECT Top 1 @RunDateCode = DateCode, @RunPartNo = Assy_PartNo FROM #temp_assy_runningpart2 WITH (NOLOCK) WHERE LineCode = @LineCode Order By CreatedDate desc

		IF EXISTS
		(
			SELECT 1 FROM Assy_Routing_Changed_Dtl WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode 
				AND LineCode = @LineCode AND (DateCode <> @DateCode OR (DateCode = @DateCode AND PartNo <> @PartNumber))
		)
		BEGIN
			SELECT @ReturnValue = 'CHNAGED', @ReturnInt = 1
		END
		--Commented By Rashid On 20170601- Handle in Front end
		--Added By Ravi On 06/04/17 For Auto Tally Chart Bypass
		--ELSE IF EXISTS
		--(
		--	SELECT 1 FROM dbo.LineMst WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(AutoTallyChartEnable,0) = 1
		--	AND EXISTS
		--	(
		--		SELECT 1 FROM dbo.Assy_RunningPart WHERE ProfitCenterCode = @ProfitCenterCode
		--		AND LineCode = @LineCode AND (Datecode <> @DateCode OR (Datecode = @DateCode AND Assy_PartNo <> @PartNumber))
		--	)
		--)
		--BEGIN
		--	SELECT @ReturnValue = 'AUTO_TALLY_CHART', @ReturnInt = 1
		--END
		ELSE
		BEGIN
			SELECT @ReturnValue = 'NOT_CHNAGED', @ReturnInt = 1
		END
		RETURN
	END

	--Added By Rashid ON 13th May 2016 For Rework Mode
	ELSE IF @Condition = 'Check_Running_Mode'
	BEGIN
		Declare @SaveMode VARCHAR(20) = '', @PrintedQty INT = 0, @B_PartNo VARCHAR(10) = '', @B_DateCode CHAR(4) = ''

		SELECT @SaveMode = UPPER(RTRIM(LTRIM(ISNULL(Assy_Mode, '')))) FROM Assy_RunningPart WITH (NOLOCK) 
			WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			
		SELECT @PrintedQty = ISNULL(PrintedQty, 0), @B_PartNo = ISNULL(PartNo, ''), @B_DateCode = ISNULL(DateCode, '') FROM Assy_Barcode_Printed_Counter WITH (NOLOCK) 
			WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode

		IF RTRIM(LTRIM(ISNULL(@SaveMode, ''))) ! = @Mode
		BEGIN
			IF @PrintedQty > 0
			BEGIN
				IF EXISTS
				(
					SELECT 1 FROM Assy_Routing_Changed_Dtl WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
				)
				BEGIN
					SELECT @ReturnValue = 'OK', @ReturnInt = 1
				END
				ELSE
				BEGIN
					IF @SaveMode = '' AND @PrintedQty IN (1, 2)
					BEGIN
						DELETE FROM Assy_Barcode_Printed_Counter WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
						--DELETE FROM Assy_LineAssyStatus_Running WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND PartNo = @B_PartNo AND DateCode = @B_DateCode
						DELETE FROM ASSY_Vision_System_Last_Printed_Barcode WHERE LineCode = @LineCode
								
						--SET @LinkServerName = ''
						--SELECT @LinkServerName = LinkServerName +'.' + DataBaseName FROM Assy_LinkServer_Dtl (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
						--SET @ExecQuery = ''
						--SET @ExecQuery = '
						--		SELECT LineCode, DateCode, Assy_PartNo, ProductionOrderNo, CurrentPlannedQty, Assy_Mode, CreatedDate, CreatedBy, ModifiedOn, ModifiedBy, isauthorized, istallySnoozed, PrintedQty, Boost_Ratio, Servo_PartNo, TMC_PartNo, ProfitCenterCode, PartType
						--,CustomerPartNo 
						--FROM ' + @LinkServerName + '.dbo.Assy_RunningPart WITH (NOLOCK) WHERE ProfitCenterCode = ''' + @ProfitCenterCode + ''' AND LineCode = ''' + @LineCode + ''''

						--INSERT INTO Assy_RunningPart (LineCode, DateCode, Assy_PartNo, ProductionOrderNo, CurrentPlannedQty, Assy_Mode, CreatedDate, CreatedBy, ModifiedOn, ModifiedBy, isauthorized, istallySnoozed, PrintedQty, Boost_Ratio, Servo_PartNo, TMC_PartNo, Profit
						--CenterCode, Par
						--tType, CustomerPartNo)
						--EXEC (@ExecQuery)

						--IF NOT EXISTS (SELECT 1 FROM Assy_RunningPart WITH (NOLOCK) 	WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode)
						--BEGIN
						--	DELETE FROM Assy_Barcode_Printed_Counter WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
						--	DELETE FROM Assy_LineAssyStatus_Running WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND PartNo = @B_PartNo AND DateCode = @B_DateCode
						--	DELETE FROM ASSY_Vision_System_Last_Printed_Barcode WHERE LineCode = @LineCode
						--END

						--IF EXISTS (SELECT 1 FROM Assy_RunningPart WITH (NOLOCK) 	WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode)
						--BEGIN
						--	SET @PartNumber = ''
						--	SELECT Top 1 @PartNumber = ISNULL(Assy_PartNo, '') FROM Assy_RunningPart WITH (NOLOCK) 	WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
						--	IF ISNULL(@B_PartNo, '') ! = ISNULL(@PartNumber, '')
						--	BEGIN
						--		DELETE FROM Assy_Barcode_Printed_Counter WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
						--		DELETE FROM Assy_LineAssyStatus_Running WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND PartNo = @B_PartNo AND DateCode = @B_DateCode
						--		DELETE FROM ASSY_Vision_System_Last_Printed_Barcode WHERE LineCode = @LineCode
						--	END
						--END
						SELECT @ReturnValue = 'OK', @ReturnInt = 1
					END
					ELSE
					BEGIN
						SELECT @ReturnValue = 'NOT_OK', @ReturnInt = 1
					END
				END
				RETURN
			END
			ELSE
				SELECT @ReturnValue = 'OK', @ReturnInt = 1
				RETURN
		END
		ELSE
		BEGIN
			SELECT @ReturnValue = 'OK', @ReturnInt = 1
			RETURN
		END
	END
	--Added By Rashid On 20170511 After AM For Twin Parts
	ELSE IF @Condition = 'CheckTwoPartSetParameter'
	BEGIN
		Declare @Existing_Family_Group_Code VARCHAR(10) = '', @Existing_PartNumber VARCHAR(20) = ''
		
		SELECT @NewPart_Family_Group_Code = Family_Group_Code, @STS_CD = STS_CD FROM PRODUCT_MASTER (NOLOCK) WHERE warehouse_cd = @ProfitCenterCode
				AND SEWS_PART_NO = @PartNumber
		
		IF ISNULL(@STS_CD,0) = 100
		BEGIN
			--SELECT 'Part Number is not active.'
			SELECT @ReturnValue = 'PART_IS_NOT_ACTIVE', @ReturnInt = 1
			RETURN
		END

		--IF ISNULL(@NewPart_Family_Group_Code,'') = ''
		--BEGIN
		--	--SELECT 'Family Group Code is not available for this Part Number.'
		--	SELECT @ReturnValue = 'GROUP_CODE_NOT_AVAILABLE', @ReturnInt = 1
		--	RETURN
		--END
		
		SELECT Top 1 @Existing_PartNumber = Assy_PartNo FROM Assy_RunningPart WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode

		IF ISNULL(@Existing_PartNumber,'') != ''
		BEGIN
			SELECT @Existing_Family_Group_Code = Family_Group_Code FROM PRODUCT_MASTER (NOLOCK) WHERE warehouse_cd = @ProfitCenterCode
					AND SEWS_PART_NO = @Existing_PartNumber
			
			--SELECT * FROM Assy_Barcode_Printed_Counter
			IF ISNULL(@NewPart_Family_Group_Code,'') != ''
			BEGIN
				IF (ISNULL(@Existing_Family_Group_Code,'') != ISNULL(@NewPart_Family_Group_Code,''))
				BEGIN
					--IF (SELECT ISNULL(PrintedQty,0) FROM Assy_Barcode_Printed_Counter WITH (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode AND PartNo = @Existing_PartNumber) > 0
					--BEGIN
						--SELECT 'New Set Parameter Part is belong to other Family'
						SELECT @ReturnValue = 'BELONG_TO_OTHER_FAMILY_TALLY_WILL_HAPPEN', @ReturnInt = 1
						RETURN
					--END
				END
			END
			ELSE
			BEGIN
				IF ISNULL(@Existing_PartNumber,'') != @PartNumber
				BEGIN
					--SELECT 'New Set Parameter Part is belong to no Family'
					SELECT @ReturnValue = 'BELONG_TO_NO_FAMILY_TALLY_WILL_HAPPEN', @ReturnInt = 1
					RETURN
				END
			END
		END

		SELECT @ReturnValue = 'OK', @ReturnInt = 1
		RETURN
	END
	ELSE IF @Condition = 'Reset_PokaYoke_After_Change_Over'
	begin
	 
            if ISNULL(@Allow2Parts,0)=1
			BEGIN
						if isnull(@RealTimeDateCode,'')=''
						begin
								exec assy_PROC_DateCode @ProfitCenterCode=@ProfitCenterCode,@ReturnValue= @RealTimeDateCode output     
						end	
						if isnull(@RealTimeRunningPartNo,'')=''
						begin
								select top 1 @RealTimeRunningPartNo=Assy_PartNo,@DateCode=datecode from dbo.Assy_RunningPart(nolock) 
								where ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
						end
						
						if isnull(@IsAppStart,0)=1
						begin
						      if @RealTimeDateCode<>@DateCode
							     set @DateCode='NG'
							   else
							     set @DateCode='OK'					   
						end
									
						IF  @DateCode<>'OK' or (SELECT count(PartNo) FROM Assy_PokaYoke_Last_Tested_Part WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode 
						    AND LineCode = @LineCode
							AND DateCode = @RealTimeDateCode AND PartNo = @RealTimeRunningPartNo) =0						
						BEGIN
							EXEC Assy_Proc_LineMst_SuperUser_Control @ProfitCenterCode = @ProfitCenterCode, @LineCode = @LineCode, @IsLocalDB = 1
							--DELETE PokaYoke_Completed_Dtl IF DateCode IS old
							IF EXISTS(SELECT 1 FROM Assy_PokaYoke_Completed_Dtl WITH (NOLOCK) WHERE DateCode! = @RealTimeDateCode)
								Truncate Table Assy_PokaYoke_Completed_Dtl 	

							DELETE Assy_LineAssyStatus_Running WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode AND DateCode = 'PKYK'
							UPDATE Assy_Scan_OK SET isPokaYokeCompleted = 0 WHERE ProfitCenterCode = @ProfitCenterCode and LineCode = @LineCode
							UPDATE Assy_POKAYOKE SET isActive = 1 WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(isActive, 0) = 0
							--UPDATE DeActive poka Yoke WITH Active
							EXEC Assy_Proc_UpdatePokaYokeStatus @Condition = 'UPDATE_POKAYOKE_COMPLETED_FOR_NA_PART', @LineCode = @LineCode, @ProfitCenterCode = @ProfitCenterCode, @ISByPassPokaYoke = 1
							EXEC Assy_Proc_PokaYoke_Last_Tested_Part @Condition = 'DELETE', @ProfitCenterCode = @ProfitCenterCode, @LineCode = @LineCode
							EXEC Assy_Proc_UpdatePokaYokeStatus @Condition = 'INSERT_BYPASS_POKA_YOKE_IN_MAIN_SERVER', @LineCode = @LineCode, @ProfitCenterCode = @ProfitCenterCode,@Allow2Parts=1
						END	
						       SELECT @ReturnValue = 'OK', @ReturnInt = 1
						RETURN	
		 END
	end
	ELSE IF @CONDITION = 'GETROUTINGPARAMETERS'
	BEGIN
		
		SELECT KEYVALUE AS 'VALUE' FROM ROUTINGCONFIGDETAILS(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND 
		STS_CD=0 AND KEYTYPE='ISSHOWIMPORTLABELCHECKBOX'  AND LINECODE=@LineCode 

		SELECT @RETURNVALUE = 'DATA SELECTED', @RETURNINT = 1
		RETURN
	END
	ELSE IF @CONDITION = 'GETImportBarcodeMode'
	BEGIN
			select top 1 ISNULL(KeyValue,0) from RoutingConfigDetails(nolock) where ProfitCenterCode=@PROFITCENTERCODE and 
			sts_cd=0 and keyType='IsImportBarcodeMode' and LineCode=@LINECODE and PartNumber=@PARTNUMBER
			and ISNULL(KeyValue,0)=1
	END
END


