							' + @LinkServer + ' where [RFID] in (' + ' select Barcode from #BarcodeList' +  ')'
							
							--print @dynamic_query
							insert into PUSH_OP10_Bore_Oil (RFID, Dts_Scan, Dts_Pass, Routing, Dcode, Status, CellNo, Profitcenter, MachineCode, OperationCode, FCS, FCA, Recipe_Selected, CT, Serial_No, ModelNo, WorkOrder, Bore_Oiling_Result_Single_Pot, Bore_Oiling_Result_Twin_Pot, TS_FLAG, RESERVED1, RESERVED2, RESERVED3, RESERVED4, RESERVED5, [Datetime], isUpdateCompleted, ServerSyncStatus )
							
							exec(@dynamic_query)

					end

					if(@TableName='OP10_Cont_Torq')
					begin
							set @dynamic_query = '
																		
							select RFID, Dts_Scan, Dts_Pass, Routing, Dcode, Status, CellNo, Profitcenter, MachineCode, OperationCode, FCS, FCA, Recipe_Selected, CT, Serial_No, ModelNo, WorkOrder, Bleed_Screw_Torque_Min_Nm, Bleed_Screw_Torque_Act_Nm, Bleed_Screw_Torque_Max_Nm, Bleed_Screw_Angle_Min_Deg, Bleed_Screw_Angle_Act_Deg, Bleed_Screw_Angle_Max_Deg, Continuity_Test_Lim, Continuity_Test_Actual, Continuity_Result, Bleed_screw_Torque_Result_Nm, No_of_Dummy_Strokes, TS_FLAG, RESERVED11, RESERVED12, RESERVED13, RESERVED14, RESERVED15, [Datetime], isUpdateCompleted, ServerSyncStatus from 
							' + @LinkServer + ' where [RFID] in (' + ' select Barcode from #BarcodeList' +  ')'
							
							--print @dynamic_query
							insert into PUSH_OP10_Cont_Torq ( RFID, Dts_Scan, Dts_Pass, Routing, Dcode, Status, CellNo, Profitcenter, MachineCode, OperationCode, FCS, FCA, Recipe_Selected, CT, Serial_No, ModelNo, WorkOrder, Bleed_Screw_Torque_Min_Nm, Bleed_Screw_Torque_Act_Nm, Bleed_Screw_Torque_Max_Nm, Bleed_Screw_Angle_Min_Deg, Bleed_Screw_Angle_Act_Deg, Bleed_Screw_Angle_Max_Deg, Continuity_Test_Lim, Continuity_Test_Actual, Continuity_Result, Bleed_screw_Torque_Result_Nm, No_of_Dummy_Strokes, TS_FLAG, RESERVED11, RESERVED12, RESERVED13, RESERVED14, RESERVED15, [Datetime], isUpdateCompleted, ServerSyncStatus) 
							
							exec(@dynamic_query)
					end

					if(@TableName='OP10_Seal_Checking')
					begin
							set @dynamic_query = '
																		
							select RFID, Dts_Scan, Dts_Pass, Routing, Dcode, Status, CellNo, Profitcenter, MachineCode, OperationCode, FCS, FCA, Recipe_Selected, CT, Serial_No, ModelNo, WorkOrder, Seal_Check_Vision_Limit_Seal_check_1, Vision_Actual_Status_Seal_check_2, Vision_Actual_Status, Seal_Check_Result, TS_FLAG, RESERVED6, RESERVED7, RESERVED8, RESERVED9, RESERVED10, [Datetime], isUpdateCompleted, ServerSyncStatus from 
							' + @LinkServer + ' where [RFID] in (' + ' select Barcode from #BarcodeList' +  ')'
							
							--print @dynamic_query
							insert into PUSH_OP10_Seal_Checking ( RFID, Dts_Scan, Dts_Pass, Routing, Dcode, Status, CellNo, Profitcenter, MachineCode, OperationCode, FCS, FCA, Recipe_Selected, CT, Serial_No, ModelNo, WorkOrder, Seal_Check_Vision_Limit_Seal_check_1, Vision_Actual_Status_Seal_check_2, Vision_Actual_Status, Seal_Check_Result, TS_FLAG, RESERVED6, RESERVED7, RESERVED8, RESERVED9, RESERVED10, [Datetime], isUpdateCompleted, ServerSyncStatus) 
							
							exec(@dynamic_query)
					end

					if(@TableName='OP20_HP')
					begin
							set @dynamic_query = '
																		
							select RFID, Dts_Scan, Dts_Pass, Routing, Dcode, Status, CellNo, Profitcenter, MachineCode, OperationCode, FCS, FCA, Recipe_Selected, CT, Serial_No, ModelNo, WorkOrder, Station_Name, Pallet_Number, MP_Fill_Min_b, MP_Fill_Act_b, MP_Fill_Max_b, MP_Fill_Time_s, MP_Stb_Time_s, MP_Test_Time_s, MP_Drop_Max_b, MP_Drop_Act_b, HP_Test_Result, HP_Test_Cycle_Time, HP_Fill_Min_b, HP_Fill_Act_b, HP_Fill_Max_b, HP_Fill_Time_s, HP_Stb_Time_s, HP_Test_Time_s, HP_Drop_Max_b, HP_Drop_Act_b, MP_Test_Result, TS_FLAG, RESERVED36, RESERVED37, RESERVED38, RESERVED39, RESERVED40, [Datetime], isUpdateCompleted, ServerSyncStatus from 
							' + @LinkServer + ' where [RFID] in (' + ' select Barcode from #BarcodeList' +  ')'
							
							--print @dynamic_query
							insert into PUSH_OP20_HP ( RFID, Dts_Scan, Dts_Pass, Routing, Dcode, Status, CellNo, Profitcenter, MachineCode, OperationCode, FCS, FCA, Recipe_Selected, CT, Serial_No, ModelNo, WorkOrder, Station_Name, Pallet_Number, MP_Fill_Min_b, MP_Fill_Act_b, MP_Fill_Max_b, MP_Fill_Time_s, MP_Stb_Time_s, MP_Test_Time_s, MP_Drop_Max_b, MP_Drop_Act_b, HP_Test_Result, HP_Test_Cycle_Time, HP_Fill_Min_b, HP_Fill_Act_b, HP_Fill_Max_b, HP_Fill_Time_s, HP_Stb_Time_s, HP_Test_Time_s, HP_Drop_Max_b, HP_Drop_Act_b, MP_Test_Result, TS_FLAG, RESERVED36, RESERVED37, RESERVED38, RESERVED39, RESERVED40, [Datetime], isUpdateCompleted, ServerSyncStatus ) 
							
							exec(@dynamic_query)
					end

					if(@TableName='OP20_Loading')
					begin
							set @dynamic_query = '
																		
							select RFID, Dts_Scan, Dts_Pass, Routing, Dcode, Status, CellNo, Profitcenter, MachineCode, OperationCode, FCS, FCA, Recipe_Selected, CT, Serial_No, ModelNo, WorkOrder, Station_Name, Pallet_Number, Loading_Result, TS_FLAG, RESERVED16, RESERVED17, RESERVED18, RESERVED19, RESERVED20, [Datetime], isUpdateCompleted, ServerSyncStatus from 
