					 --print @MachineLinkServer
					 --print 	@LinkServer
					
					insert into [Assy_LineAssyManualPassFail](ProfitCenterCode,LineCode,MachineCode,OperationCode,Barcode,
					Status,Remarks,Timestamp,UserID,IsMailSent)
					values(@P_PROFITCENTER_CODE,@P_LINE_CODE,'','',@P_BARCODE,'',
