							insert into PUSH_OP50_Auto_Inspection (RFID, Dts_Scan, Dts_Pass, Routing, Dcode, Status, CellNo, Profitcenter, MachineCode, OperationCode, FCS, FCA, Recipe_Selected, CT, Serial_No, ModelNo, WorkOrder, Pallet_Number, Vision_Status_01, Vision_Status_02, Vision_Status_03, Vision_Status_04, Vision_Status_05, Vision_Status_06, Vision_Status_07, Vision_Status_08, Vision_Status_09, Vision_Status_10, Vision_Status_11, Vision_Status_12, Vision_Status_13, Vision_Status_14, Vision_Status_15, Vision_Status_16, Vision_Status_17, Vision_Status_18, Vision_Status_19, Vision_Status_20, Vision_Status_21, Vision_Status_22, Vision_Status_23, Vision_Status_24, Vision_Status_25, Vision_Status_26, Vision_Status_27, Vision_Status_28, Vision_Status_29, Vision_Status_30, Customer_QR_Code_Printed_Result, Customer_QR_Code_Scanned_Result, QR_Code_Serial_No, TS_FLAG, RESERVED86, RESERVED87, RESERVED88, RESERVED89, RESERVED90, [Datetime], isUpdateCompleted, ServerSyncStatus	)
							exec(@dynamic_query)							
					end	
					

					print @P_TABLENAME
					
					--print 'Row Count : ' + convert(varchar,@@rowcount)
					--end

				end				
			
				SET @ReturnValue = 'Data Pulled Successfully'
				SET @ReturnInt = 1

			end try
			begin catch
			SET @ReturnValue =  CAST(ISNULL(ERROR_NUMBER(),0) as varchar(5)) + '|' + 
								CAST(ISNULL(ERROR_SEVERITY(),0) as varchar(5)) + '|' + 
								CAST(ISNULL(ERROR_STATE(),0) as varchar(5)) + '|' + 
								CAST(ISNULL(ERROR_PROCEDURE(),'ASSY_PROC_PULL_MES_DATA') as varchar(200)) + '|' + 
								CAST(ISNULL(ERROR_LINE(),0) as varchar(5)) + '|' + 
								CAST(ISNULL(ERROR_MESSAGE(),'') as varchar(1500))+ '|' +  
								CAST(ISNULL(@P_Mode,'') as varchar(100)) + '|' + 
								CAST(ISNULL(@P_PROFITCENTER_CODE,'') as varchar(100)) + '|' + 
								CAST(ISNULL(@P_LINE_CODE,'') as varchar(100)) + '|' + 
								CAST(ISNULL(@P_USER_ID,'') as varchar(100)) + '|' + 
								CAST(ISNULL(@P_MACHINECODE,'') as varchar(100)) + '|' + 
								CAST(ISNULL(@P_OPERATION_CODE,'') as varchar(100)) 
			
			SET @ReturnValue = @ReturnValue
			SET @ReturnInt = 2
			end catch


	end


	END TRY
	BEGIN CATCH

	SET @ReturnValue =   CAST(ISNULL(ERROR_NUMBER(),0) as varchar(5)) + '|' + 
	CAST(ISNULL(ERROR_SEVERITY(),0) as varchar(5)) + '|' + 
	CAST(ISNULL(ERROR_STATE(),0) as varchar(5)) + '|' + 
	CAST(ISNULL(ERROR_PROCEDURE(),'ASSY_PROC_PULL_MES_DATA') as varchar(200)) + '|' + 
	CAST(ISNULL(ERROR_LINE(),0) as varchar(5)) + '|' + 
	CAST(ISNULL(ERROR_MESSAGE(),'') as varchar(1500))+ '|' +  
	CAST(ISNULL(@P_Mode,'') as varchar(100)) + '|' + 
	CAST(ISNULL(@P_PROFITCENTER_CODE,'') as varchar(100)) + '|' + 
	CAST(ISNULL(@P_LINE_CODE,'') as varchar(100)) + '|' + 
	CAST(ISNULL(@P_USER_ID,'') as varchar(100)) + '|' + 
	CAST(ISNULL(@P_MACHINECODE,'') as varchar(100)) + '|' + 
	CAST(ISNULL(@P_OPERATION_CODE,'') as varchar(100)) 
				
	SET @RETURNINT = 2

	insert into ASSY_LOG_ERROR(ErrorProcedure,ErrorMsg,Ent_dtl)
	values('ASSY_PROC_PULL_MES_DATA',@ReturnValue,GETDATE())

	END CATCH

END





