@ReturnValue=@RequesTD output
         

****************************************************************************************/
Create procedure [dbo].[ASSY_PROC_PULL_MES_DATA_0088_J10_08012026]
(
   @P_Mode varchar(100)='',  
   @P_PROFITCENTER_CODE varchar(10)='',
   @P_LINE_CODE varchar(10)='',        
   @P_OPERATION_CODE varchar(10)='',
   @P_USER_ID varchar(60)='',
   @P_MACHINECODE varchar(10)='', 
   @P_BARCODE varchar(100)='', 
   @P_TABLENAME varchar(100)='',               
   @ReturnValue VARCHAR (2000)=NULL OUT,
   @ReturnInt INT=NULL OUT
)
AS
BEGIN
	
	Declare 
	@IDGenrationMachineCode varchar(10) = 'MCIG',
	@IDGenrationOperationCode varchar(10) = 'OCIG',
	@CELLNO varchar(10) = '',
	@StationCode smallint = 1,
	@RFID varchar(60) = '',
	@STATUS varchar(4) = '',
	@FCA smallint = 0,
	@DCODE varchar(4)='',
	@MODELNO varchar(60) = '',
	@Active smallint = 0,
	@DTS_PASS datetime,
	@DTS_SCAN datetime,	
	@IsTallyChartApproved smallint=0,
	@IsReworkPart smallint=0,
	@IsPendingPart smallint=0,
	@WORKORDER varchar(30),
	@PROD_LOT_NO varchar(30),
	@SERIAL_NO int,
	@Picked_Ids int = 0,
	@listCoulumnMain varchar(max)
	,@MachineLinkServerName varchar(100) 
	,@MachineLinkServerDB varchar(100) 
	,@MachineLinkServer varchar(300) 
	,@MachineDBTableName varchar(100) 
	,@RunPartNoWithPrefix VARCHAR(60) = ''
	,@LinkServerType VARCHAR(60) = ''
	,@dynamic_query varchar(max) = ''
	,@s sysname
	,@PassTimeStamp datetime
	,@IDGenerationTableName varchar(100)=''
	,@INT_TS_FLAG smallint = 0
	DECLARE @XmldataLK XML 
	
	Declare @ParameterData Assy_TYPE_LineAssyParamData_Running_Db
	DECLARE @P_Result varchar(2) = 'PS'
	set @IDGenerationTableName = 'PUSH_OP10_Bore_Oil'

	declare @TDTableName as Table 
	(
	   SeqNo smallint,
	   TableName varchar(100)
	)
	declare @WTableName varchar(100)=''
	declare @LastSeqNo smallint = 0
	declare @CurrentSeqNo smallint = 0

	BEGIN TRY

	If(@P_Mode='MCIG')
	begin
		
		DECLARE @ID_GEN_TBL as Table
		(	[RFID] [varchar](25) NULL,
			[DTS_PASS] [datetime] NULL,
			[STATUS] [varchar](10) NULL,
			[DCODE] [varchar](10) NULL,
			[DTS_SCAN] [datetime] NULL,
			[FCA] [varchar](10) NULL,
			[ROUTING] [varchar](10) NULL,
			[SERIAL_NO] [int] NULL,
			[MODELNO] [varchar](12) NULL,
			[WORKORDER] [varchar](15) NULL,
			[PROFITCENTER] [varchar](10) NULL,
			[CELLNO] [varchar](10) NULL,
			[MachineCode] [varchar](10) NULL,
			[OperationCode] [varchar](10) NULL			
		) 
		
		
		
		set @dynamic_query = 'select RFID,[DTS_PASS],[STATUS],DCODE,DTS_SCAN,FCA,ROUTING,SERIAL_NO,MODELNO,
		WORKORDER,PROFITCENTER,CELLNO,MachineCode,OperationCode		
		from ' + @IDGenerationTableName +'(nolock) where ISNULL(TS_FLAG,0)=0
		and DTS_SCAN is not null and DTS_PASS is not null'
		insert into @ID_GEN_TBL	(
		RFID,[DTS_PASS],[STATUS],DCODE,DTS_SCAN,FCA,ROUTING,SERIAL_NO,MODELNO,
		WORKORDER,PROFITCENTER,CELLNO,MachineCode,OperationCode		
		)
		
		
		exec(@dynamic_query)
		print @dynamic_query

		update @ID_GEN_TBL set STATUS= case when [STATUS]='PASS' then 'PS' else 'FL' end 
	
		while exists(select top 1 1 from @ID_GEN_TBL )
		begin
		
		BEGIN TRY
			
			set @Picked_Ids = ISNULL(@Picked_Ids,0) + 1
			select Top 1 @P_PROFITCENTER_CODE=PROFITCENTER,@CELLNO=CELLNO,@RFID=RFID,
			@STATUS=[STATUS],
			@FCA=FCA,@DCODE=DCODE,
			@MODELNO=MODELNO,@DTS_PASS=DTS_PASS,@DTS_SCAN=DTS_SCAN,
			@WORKORDER=WORKORDER,@SERIAL_NO=SERIAL_NO from @ID_GEN_TBL
			order by DTS_PASS asc
		
			if not exists (select top 1 1 from Assy_LineAssyStatus_Running(nolock) where 
			ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode=@CELLNO and MachineCode=@IDGenrationMachineCode and
			OperationCode=@IDGenrationOperationCode and Barcode=@RFID
			)
			begin
				insert into Assy_LineAssyStatus_Running(
				ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,Status,FailCount,
				Datecode,PartNo,Active,ResultTimestamp,ScanTimestamp,UserID,IsTallyChartApproved,IsReworkPart,IsPendingPart,ProductionOrderNo,
				PROD_LOT_NO
				)
				select @P_PROFITCENTER_CODE,@CELLNO,@IDGenrationMachineCode,@IDGenrationOperationCode,@StationCode,
				@RFID,@STATUS,@FCA,@DCODE,@MODELNO,@Active,@DTS_PASS,@DTS_SCAN,@P_USER_ID,@IsTallyChartApproved,@IsReworkPart,@IsPendingPart,@WORKORDER,
				@PROD_LOT_NO

	
				exec ASSY_Proc_Vision_System_Log  @OPeration ='UPDATE_SEQUENCE_NUMBER',@PartNo=@MODELNO,
				@LastPrintBarcode=@RFID,@linecode =@CELLNO,
				@ProfitCenterCode=@P_PROFITCENTER_CODE
			
				--UPDATE PRINTED BARCODE PickedCount
				EXEC Assy_Proc_Barcode_Printed_Counter @CONDITION='UPDATE',@LINECODE =@CELLNO ,@PROFITCENTERCODE =@P_PROFITCENTER_CODE
				UPDATE ASSY_RUNNINGPART SET PRINTEDQTY=ISNULL(PRINTEDQTY,0)+1 WHERE LINECODE=@CELLNO AND CURRENTPLANNEDQTY>ISNULL(PRINTEDQTY,0)
			
				EXEC ASSY_PROC_WIP_MANAGE  @CONDITION='UPDATE_WIP_COUNT', @LINECODE=@CELLNO,@MACHINECODE=@IDGenrationMachineCode
				,@BARCODE=@RFID,@PROFITCENTERCODE=@P_PROFITCENTER_CODE	
			
				if (CHARINDEX('PKYK',@RFID) <= 0)   
				begin
				INSERT INTO ASSY_VISION_SYSTEM(PROFITCENTERCODE,LINECODE,BARCODE,PARTNO,DATECODE,SERIALNO,TIMESTAMP,IsRework)        
				SELECT @P_PROFITCENTER_CODE,@CELLNO,@RFID,@MODELNO,@DCODE,@SERIAL_NO,GETDATE(),0
				end
			
				--update p set TS_FLAG=1
				--from @ID_GEN_TBL t inner join
				--PUSH_OP10_01_SEALCHECK(nolock) p on t.RFID=p.RFID
				--and t.DTS_PASS=p.DTS_PASS
				--where t.rfid=@RFID
				--AND ISNULL(p.TS_FLAG,0)=0

				set @dynamic_query = 'update p set TS_FLAG=1 from '+
				@IDGenerationTableName +' p 
				where p.rfid='''+@RFID+''' 
			    AND ISNULL(p.TS_FLAG,0)=0';
				print(@dynamic_query)
				exec(@dynamic_query)
				--print @RFID
				delete from @ID_GEN_TBL where rfid=@RFID
			end
			else
			begin

				--update p set TS_FLAG=3
				--from @ID_GEN_TBL t inner join
				--PUSH_OP10_01_SEALCHECK(nolock) p on t.RFID=p.RFID
				--and t.DTS_PASS=p.DTS_PASS
				--where t.rfid=@RFID
				--AND ISNULL(p.TS_FLAG,0)=0
				--print @RFID
				set @dynamic_query = 'update p set TS_FLAG=3 from  '+
				@IDGenerationTableName+' p 
				where p.rfid='''+@RFID+'''
			    AND ISNULL(p.TS_FLAG,0)=0';

				print(@dynamic_query)
				exec(@dynamic_query)
				delete from @ID_GEN_TBL where rfid=@RFID
				
			end
			END TRY
			BEGIN CATCH

			--update p set TS_FLAG=100
			--from @ID_GEN_TBL t inner join
			--PUSH_OP10_01_SEALCHECK(nolock) p on t.RFID=p.RFID
			--and t.DTS_PASS=p.DTS_PASS
			--where t.rfid=@RFID
			--AND ISNULL(p.TS_FLAG,0)=0
			set @dynamic_query = 'update p set TS_FLAG=100 from '+
			@IDGenerationTableName+' p 
			where p.rfid='''+@RFID+'''
			AND ISNULL(p.TS_FLAG,0)=0';

			print(@dynamic_query)
			exec(@dynamic_query)

			delete from @ID_GEN_TBL

			SET @ReturnValue =   CAST(ISNULL(ERROR_NUMBER(),0) as varchar(5)) + '|' + 
			CAST(ISNULL(ERROR_SEVERITY(),0) as varchar(5)) + '|' + 
			CAST(ISNULL(ERROR_STATE(),0) as varchar(5)) + '|' + 
			CAST(ISNULL(ERROR_PROCEDURE(),'ASSY_PROC_PULL_MES_DATA') as varchar(200)) + '|' + 
			CAST(ISNULL(ERROR_LINE(),0) as varchar(5)) + '|' + 
			CAST(ISNULL(ERROR_MESSAGE(),'') as varchar(1500)) + '|' +  
			CAST(ISNULL(@P_Mode,'') as varchar(100)) + '|' + 
			CAST(ISNULL(@P_PROFITCENTER_CODE,'') as varchar(100)) + '|' + 
			CAST(ISNULL(@P_LINE_CODE,'') as varchar(100)) + '|' + 
			CAST(ISNULL(@P_USER_ID,'') as varchar(100)) + '|' + 
			CAST(ISNULL(@P_MACHINECODE,'') as varchar(100)) + '|' + 
			CAST(ISNULL(@P_OPERATION_CODE,'') as varchar(100)) 
				
			SET @RETURNINT = 2

			insert into ASSY_LOG_ERROR(ErrorProcedure,ErrorMsg,Ent_dtl,MachineCode,OperationCode,Barcode,Mode)
			values('ASSY_PROC_PULL_MES_DATA',@ReturnValue,GETDATE(),@P_MACHINECODE,@P_OPERATION_CODE,@RFID,@P_Mode)

			END CATCH

		end

		select @Picked_Ids as 'PickedCount' , getdate() as 'PickedTime', 'MCIG' as 'TableName'

	end

	else if(@P_Mode='PUSH_OP10_Bore_Oil')
	begin
		
		if(@IDGenerationTableName=@P_Mode)
		begin
			set @INT_TS_FLAG=1
		end
		print @INT_TS_FLAG
		select * into #TEMP_PUSH_OP10_Bore_Oil_
		from PUSH_OP10_Bore_Oil(nolock) where ISNULL(TS_FLAG,0)=@INT_TS_FLAG
		and ISNULL(PROFITCENTER,'')=ISNULL(@P_PROFITCENTER_CODE,'') and ISNULL(CELLNO,'')=ISNULL(@P_LINE_CODE,'')
		and ISNULL(MachineCode,'')=@P_MACHINECODE and ISNULL(OperationCode,'')=ISNULL(@P_OPERATION_CODE,'')
		and DTS_SCAN is not null and DTS_PASS is not null

		update #TEMP_PUSH_OP10_Bore_Oil_ set STATUS= case when [STATUS]='PASS' then 'PS' else 'FL' end 

		select @listCoulumnMain=COALESCE(@listCoulumnMain+ ',', '') 
		+ 'isnull(convert(varchar(100),' + '[' + CONVERT(VARCHAR(100),main.TagName) + ']'  + '),''NULL'')' + ' as ['
		+  CONVERT(VARCHAR(100),main.TagName) + ']'
		from MachineTagMapping(nolock)  main
		where MachineCode=@P_MACHINECODE and OperationCode=@P_OPERATION_CODE
		and PROFITCENTERCODE = @P_PROFITCENTER_CODE
		AND LINECODE = @P_LINE_CODE 

		while exists(select top 1 1 from #TEMP_PUSH_OP10_Bore_Oil_ )
		begin

		begin try
		
		select Top 1 @RFID=RFID,
		@STATUS=[STATUS]
		,@PassTimeStamp=DTS_PASS
		from #TEMP_PUSH_OP10_Bore_Oil_(nolock) order by DTS_PASS asc
		
		-- If Poke Yoke Barcode
		if (CHARINDEX('PKYK',@RFID) > 0)   
		begin
			
				select @DCODE=Datecode,@MODELNO=Assy_PartNo,@WORKORDER=ProductionOrderNo			
				from Assy_RunningPart(nolock) where ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode=@P_LINE_CODE

				insert into Assy_LineAssyStatus_Running(
				ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,Status,FailCount,
				Datecode,PartNo,Active,ResultTimestamp,ScanTimestamp,UserID,IsTallyChartApproved,IsReworkPart,IsPendingPart,ProductionOrderNo,
				PROD_LOT_NO
				)
				select t.PROFITCENTER,t.CELLNO,t.MachineCode,t.OperationCode,@StationCode,
				t.RFID,t.STATUS,t.FCA,'PKYK',@MODELNO,@Active,t.DTS_PASS,t.DTS_SCAN,@P_USER_ID,@IsTallyChartApproved,@IsReworkPart,@IsPendingPart,@WORKORDER,
				@PROD_LOT_NO from #TEMP_PUSH_OP10_Bore_Oil_ t			
				where  t.RFID=@RFID
				and t.DTS_PASS=@PassTimeStamp
				
		end
		else
		begin
			
			if not exists (select top 1 1 from Assy_LineAssyStatus_Running(nolock) where 
			ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode=@P_LINE_CODE and MachineCode=@P_MACHINECODE and
			OperationCode=@P_OPERATION_CODE and Barcode=@RFID
			)
			begin
			    begin try
				insert into assy_lineassystatus_running(
				profitcentercode,linecode,machinecode,operationcode,stationcode,barcode,status,failcount,
				datecode,partno,active,resulttimestamp,scantimestamp,userid,istallychartapproved,isreworkpart,ispendingpart,productionorderno,
				prod_lot_no
				)
				select top 1 r.ProfitCenterCode,r.LineCode,t.MachineCode,t.OperationCode,r.StationCode,
				t.RFID,t.STATUS,t.FCA,r.Datecode,r.PartNo,r.Active,t.DTS_PASS,t.DTS_SCAN,@P_USER_ID,r.IsTallyChartApproved,r.IsReworkPart,r.IsPendingPart,
				r.ProductionOrderNo,r.PROD_LOT_NO from Assy_LineAssyStatus_Running(nolock) r inner join #TEMP_PUSH_OP10_Bore_Oil_ t
				on r.barcode = t.RFID
				where r.MachineCode='MCIG'
				and t.RFID=@RFID
				and t.DTS_PASS=@PassTimeStamp

				end try
				begin catch

					SET @ReturnValue =   CAST(ISNULL(ERROR_NUMBER(),0) as varchar(5)) + '|' + 
					CAST(ISNULL(ERROR_SEVERITY(),0) as varchar(5)) + '|' + 
					CAST(ISNULL(ERROR_STATE(),0) as varchar(5)) + '|' + 
					CAST(ISNULL(ERROR_PROCEDURE(),'ASSY_PROC_PULL_MES_DATA') as varchar(200)) + '|' + 
					CAST(ISNULL(ERROR_LINE(),0) as varchar(5)) + '|' + 
					CAST(ISNULL(ERROR_MESSAGE(),'') as varchar(1500)) + '|' +  
					CAST(ISNULL(@P_Mode,'') as varchar(100)) + '|' + 
					CAST(ISNULL(@P_PROFITCENTER_CODE,'') as varchar(100)) + '|' + 
					CAST(ISNULL(@P_LINE_CODE,'') as varchar(100)) + '|' + 
					CAST(ISNULL(@P_USER_ID,'') as varchar(100)) + '|' + 
					CAST(ISNULL(@P_MACHINECODE,'') as varchar(100)) + '|' + 
					CAST(ISNULL(@P_OPERATION_CODE,'') as varchar(100)) 

					insert into ASSY_LOG_ERROR(ErrorProcedure,ErrorMsg,Ent_dtl,MachineCode,OperationCode,Barcode,Mode)
					values('ASSY_PROC_PULL_MES_DATA',@ReturnValue,GETDATE(),@P_MACHINECODE,@P_OPERATION_CODE,@RFID,@P_Mode)

				end catch

			end
			else
			begin
					
				update r set r.Status=t.STATUS,
				       r.FailCount=t.FCA,
					   r.ResultTimestamp=t.DTS_PASS,
					   r.ScanTimestamp=t.DTS_SCAN				
				from Assy_LineAssyStatus_Running(nolock) r inner join #TEMP_PUSH_OP10_Bore_Oil_ t
				on r.barcode = t.RFID
				where 
				ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode=@P_LINE_CODE 
				and r.MachineCode=@P_MACHINECODE and r.OperationCode=@P_OPERATION_CODE 
				and Barcode=@RFID
				and t.DTS_PASS=@PassTimeStamp

			end
		end
		set @Picked_Ids = @Picked_Ids+@@ROWCOUNT


		IF exists (select top 1 1 from Assy_LineAssyStatus_Running(nolock)
		where MachineCode=@P_MACHINECODE and OperationCode=@P_OPERATION_CODE
		and PROFITCENTERCODE = @P_PROFITCENTER_CODE
		AND LINECODE = @P_LINE_CODE AND Barcode=@RFID
		)
		begin

				IF(OBJECT_ID('HASH_TEMP_TAGDATA_20')) IS NOT NULL
				DROP TABLE HASH_TEMP_TAGDATA_20
						
				create table HASH_TEMP_TAGDATA_20
				(
					TagName varchar(100),
					TagValue varchar(100)
				)

		if( ISNULL(@listCoulumnMain,'')<>'')
		begin
				
				
				set @dynamic_query = '

				if object_id(''tempdb..#TEMP_MES_DATA'') is not null
				drop table #TEMP_MES_DATA

				select ' + @listCoulumnMain  +' into #TEMP_MES_DATA from PUSH_OP10_Bore_Oil ' + 
				' where RFID = ''' + @RFID + ''' and DTS_PASS = ''' + convert(varchar,@PassTimeStamp,121) + ''''
				+ ' AND ISNULL(TS_FLAG,0)= '''+cast(@INT_TS_FLAG as varchar(2))+''' '
				+ '
				DECLARE @Xmldata XML 
				SET @Xmldata = (SELECT * FROM  #TEMP_MES_DATA FOR XML PATH(''''))

				SELECT TagName,TagValue FROM  ( 
				SELECT 
				ROW_NUMBER()OVER(PARTITION BY   TagName ORDER BY  TagValue) rn,* FROM ( 
				SELECT  i.value(''local-name(.)'',''VARCHAR(100)'')  TagName,
				i.value(''.'',''VARCHAR(100)'') TagValue 
				FROM @Xmldata.nodes(''//*'') x(i) ) tmp ) tmp1
				
				if object_id(''tempdb..#TEMP_MES_DATA'') is not null
				drop table #TEMP_MES_DATA

				'
				
				print @dynamic_query
				insert into HASH_TEMP_TAGDATA_20(TagName,TagValue)
				execute(@dynamic_query)

		end
		
		delete from @ParameterData

		INSERT INTO @ParameterData(
		ProfitCenterCode,LineCode,MachineCode,
		OperationCode,StationCode,Barcode,TagName,Value,Result,Datecode,UserID)
		select distinct @P_PROFITCENTER_CODE,@P_LINE_CODE,@P_MACHINECODE,
		@P_OPERATION_CODE,'1',@RFID,TagName,TagValue,@STATUS,'',@P_USER_ID
		from HASH_TEMP_TAGDATA_20
		
		if not exists(select top 1 1 from @ParameterData)
		begin
				insert into @ParameterData(
				ProfitCenterCode,LineCode,MachineCode,
