				ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode=@P_LINE_CODE 
				and r.MachineCode=@P_MACHINECODE and r.OperationCode=@P_OPERATION_CODE 
				and Barcode=@RFID
				and t.DTS_PASS=@PassTimeStamp

			end
		end
		set @Picked_Ids = @Picked_Ids+@@ROWCOUNT


		IF exists (select top 1 1 from Assy_LineAssyStatus_Running(nolock)
		where MachineCode=@P_MACHINECODE and OperationCode=@P_OPERATION_CODE
		and PROFITCENTERCODE = @P_PROFITCENTER_CODE
		AND LINECODE = @P_LINE_CODE AND Barcode=@RFID
		)
		begin

				IF(OBJECT_ID('HASH_TEMP_TAGDATA_20')) IS NOT NULL
				DROP TABLE HASH_TEMP_TAGDATA_20
						
				create table HASH_TEMP_TAGDATA_20
				(
					TagName varchar(100),
					TagValue varchar(100)
				)

		if( ISNULL(@listCoulumnMain,'')<>'')
		begin
				
				
				set @dynamic_query = '

				if object_id(''tempdb..#TEMP_MES_DATA'') is not null
				drop table #TEMP_MES_DATA

				select ' + @listCoulumnMain  +' into #TEMP_MES_DATA from PUSH_OP50_Auto_Inspection ' + 
				' where RFID = ''' + @RFID + ''' and DTS_PASS = ''' + convert(varchar,@PassTimeStamp,121) + ''''
				+ ' AND ISNULL(TS_FLAG,0)= '''+cast(@INT_TS_FLAG as varchar(2))+''' '
				+ '
				DECLARE @Xmldata XML 
				SET @Xmldata = (SELECT * FROM  #TEMP_MES_DATA FOR XML PATH(''''))

				SELECT TagName,TagValue FROM  ( 
				SELECT 
				ROW_NUMBER()OVER(PARTITION BY   TagName ORDER BY  TagValue) rn,* FROM ( 
				SELECT  i.value(''local-name(.)'',''VARCHAR(100)'')  TagName,
				i.value(''.'',''VARCHAR(100)'') TagValue 
				FROM @Xmldata.nodes(''//*'') x(i) ) tmp ) tmp1
				
				if object_id(''tempdb..#TEMP_MES_DATA'') is not null
				drop table #TEMP_MES_DATA

				'
				
				print @dynamic_query
				insert into HASH_TEMP_TAGDATA_20(TagName,TagValue)
				execute(@dynamic_query)

		end
		
		delete from @ParameterData

		INSERT INTO @ParameterData(
		ProfitCenterCode,LineCode,MachineCode,
		OperationCode,StationCode,Barcode,TagName,Value,Result,Datecode,UserID)
		select distinct @P_PROFITCENTER_CODE,@P_LINE_CODE,@P_MACHINECODE,
		@P_OPERATION_CODE,'1',@RFID,TagName,TagValue,@STATUS,'',@P_USER_ID
		from HASH_TEMP_TAGDATA_20
		
		if not exists(select top 1 1 from @ParameterData)
		begin
				insert into @ParameterData(
				ProfitCenterCode,LineCode,MachineCode,
				OperationCode,StationCode,Barcode,TagName,Value,Result,Datecode,UserID)
				select @P_PROFITCENTER_CODE,@P_LINE_CODE,@P_MACHINECODE,
				@P_OPERATION_CODE,'1',@RFID,'Result',@STATUS,@STATUS,'',@P_USER_ID
		end

		exec Assy_Proc_DBIntegration @Operation='INSERT_PLC_PARAMS',@LineCode=@P_LINE_CODE,
		@tblParameters=@ParameterData , @TD_Table=''	

		delete from @ParameterData

		update p set TS_FLAG=2
		from #TEMP_PUSH_OP50_Auto_Inspection_ t inner join
		PUSH_OP50_Auto_Inspection(nolock) p on t.RFID=p.RFID
		and t.DTS_PASS=p.DTS_PASS
		where t.rfid=@RFID
		AND ISNULL(p.TS_FLAG,0)=@INT_TS_FLAG
		AND p.DTS_PASS=@PassTimeStamp

		delete p 
		from #TEMP_PUSH_OP50_Auto_Inspection_ t inner join
		PUSH_OP50_Auto_Inspection(nolock) p on t.RFID=p.RFID
		and t.DTS_PASS=p.DTS_PASS
		where t.rfid=@RFID
		AND ISNULL(p.TS_FLAG,0)=2
		AND p.DTS_PASS=@PassTimeStamp

		END
			
		delete from #TEMP_PUSH_OP50_Auto_Inspection_ where rfid=@RFID	and DTS_PASS=@PassTimeStamp	
		END TRY
		BEGIN CATCH
		
		update p set TS_FLAG=100
		from #TEMP_PUSH_OP50_Auto_Inspection_ t inner join
		PUSH_OP50_Auto_Inspection(nolock) p on t.RFID=p.RFID
		and t.DTS_PASS=p.DTS_PASS
		where t.rfid=@RFID
		AND ISNULL(p.TS_FLAG,0)=@INT_TS_FLAG

		delete p
		from #TEMP_PUSH_OP50_Auto_Inspection_ t inner join
		PUSH_OP50_Auto_Inspection(nolock) p on t.RFID=p.RFID
		and t.DTS_PASS=p.DTS_PASS
		where t.rfid=@RFID
		AND ISNULL(p.TS_FLAG,0)=100

		delete from #TEMP_PUSH_OP50_Auto_Inspection_

		SET @ReturnValue =   CAST(ISNULL(ERROR_NUMBER(),0) as varchar(5)) + '|' + 
		CAST(ISNULL(ERROR_SEVERITY(),0) as varchar(5)) + '|' + 
		CAST(ISNULL(ERROR_STATE(),0) as varchar(5)) + '|' + 
		CAST(ISNULL(ERROR_PROCEDURE(),'ASSY_PROC_PULL_MES_DATA') as varchar(200)) + '|' + 
		CAST(ISNULL(ERROR_LINE(),0) as varchar(5)) + '|' + 
		CAST(ISNULL(ERROR_MESSAGE(),'') as varchar(1500))+ '|' +  
		CAST(ISNULL(@P_Mode,'') as varchar(100)) + '|' + 
		CAST(ISNULL(@P_PROFITCENTER_CODE,'') as varchar(100)) + '|' + 
		CAST(ISNULL(@P_LINE_CODE,'') as varchar(100)) + '|' + 
		CAST(ISNULL(@P_USER_ID,'') as varchar(100)) + '|' + 
		CAST(ISNULL(@P_MACHINECODE,'') as varchar(100)) + '|' + 
		CAST(ISNULL(@P_OPERATION_CODE,'') as varchar(100)) 
				
		SET @RETURNINT = 2

		insert into ASSY_LOG_ERROR(ErrorProcedure,ErrorMsg,Ent_dtl,MachineCode,OperationCode,Barcode,Mode)
		values('ASSY_PROC_PULL_MES_DATA',@ReturnValue,GETDATE(),@P_MACHINECODE,@P_OPERATION_CODE,@RFID,@P_Mode)

		END CATCH

	 END

	 select @Picked_Ids as 'PickedCount' , getdate() as 'PickedTime', 'PUSH_OP50_Auto_Inspection' as 'TableName'

	end
	  

	if(@P_Mode='GET_PUSHED_DATA_COUNT')
	begin
			
			insert into @TDTableName(SeqNo,TableName)
			select l.operationSeqNo,M.TD_TABLE_NAME from ASSY_TD_OPERATION_TABLE_MAPPING(nolock) m inner join
			RoutingConfigLineWise(nolock) l on m.MachineCode=l.MachineCode
			order by l.operationSeqNo asc
			
			select top 1 @LastSeqNo=SeqNo from @TDTableName order by SeqNo desc

			while exists(select top 1 1 from @TDTableName)
			begin
	
				select top 1 @WTableName=TableName,@CurrentSeqNo=SeqNo 
				from @TDTableName order by SeqNo
	
				if(@WTableName='MCIG')
				begin
					set @dynamic_query = @dynamic_query + 
					' select count(*) as ''PushedCount'' , ' 
					+ ''''+ @WTableName +'''' + ' as ''TableName'' from ' + @IDGenerationTableName +'(nolock) where ISNULL(TS_FLAG,0)=0
					'
				end
				else if (@WTableName=@IDGenerationTableName)
				begin
					set @dynamic_query = @dynamic_query + 
					' select count(*) as ''PushedCount'' , ' 
					+ ''''+ @WTableName +'''' + ' as ''TableName'' from ' + @IDGenerationTableName +'(nolock) where ISNULL(TS_FLAG,0)=1 
					'
				end
				else
				begin
					set @dynamic_query = @dynamic_query + 
					' select count(*) as ''PushedCount'' , ' 
					+ ''''+ @WTableName +'''' + ' as ''TableName'' from ' + @WTableName +'(nolock) where ISNULL(TS_FLAG,0)=0 
					'
				end
				if(@CurrentSeqNo != @LastSeqNo )
				begin
				set @dynamic_query = @dynamic_query + ' union all 
				'
				end
				delete from @TDTableName where TableName=@WTableName
			end

			exec (@dynamic_query)
			
	end

	if(@P_Mode='GET_MACHINE_TABLE_CONFIGURATION')
	begin
		  select  OperationSeqNo,l.MachineCode,l.OperationCode,t.TD_TABLE_NAME from ASSY_TD_OPERATION_TABLE_MAPPING(nolock) t inner join
		  RoutingConfigLineWise(nolock) l on l.MachineCode=t.MachineCode
		  and l.LineCode=t.lineCode
		  where t.ProfitCenterCode=@P_PROFITCENTER_CODE and l.LineCode=@P_LINE_CODE
		  and l.OperationRequired=1 and l.Traceability=1
		  order by OperationSeqNo
	end

