				SELECT TOP 1 @MachineLinkServerName = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @P_PROFITCENTER_CODE 
				AND LineCode = @P_LINE_CODE AND KeyType = 'MachineDBLinkServerName' AND STS_CD = 0
				
				if(ISNULL(@MachineLinkServerName,'') = '' )
				begin
					SET @ReturnValue = 'Machine Link Server Name Configuration Not Found !! [RoutingConfigDetails Key: MachineDBLinkServerName] '
					 SET @ReturnInt = 2
					return
				end

				SELECT TOP 1 @MachineLinkServerDB = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @P_PROFITCENTER_CODE 
				AND LineCode = @P_LINE_CODE AND KeyType = 'MachineDBLinkServerDB' AND STS_CD = 0

				if(ISNULL(@MachineLinkServerDB,'') = '' )
				begin
					 SET @ReturnValue = 'Machine Link Server Database Configuration Not Found !! [RoutingConfigDetails Key: MachineDBLinkServerDB]'
					 SET @ReturnInt = 2
					 return
				end
				
				SELECT TOP 1 @LinkServerType = KeyValue FROM RoutingConfigDetails (NOLOCK) 
				WHERE ProfitCenterCode = @P_PROFITCENTER_CODE 
				AND LineCode = @P_LINE_CODE AND KeyType = 'LinkServerType' AND STS_CD = 0				

				if(ISNULL(@LinkServerType,'') = '' )
				begin
					SET @ReturnValue = 'Link Server Type Parameter Configuration Not Found !! [RoutingConfigDetails Key: LinkServerType] '
					SET @ReturnInt = 2
					
					return
				end

				begin try
				set @s =REPLACE(REPLACE(@MachineLinkServerName,'[',''),']','')
				exec sys.sp_testlinkedserver @s
				end try
				begin catch
				
				SET @ReturnValue = 'Kindly Check, Not Able To Connect MES SQL Server !!! '+@MachineLinkServerName
				SET @ReturnInt = 2
				return
				end catch


				if(@LinkServerType='MYSQL')
				begin
					print 'MYSQL'
				end

				if(@LinkServerType='MSSQL')
				begin
				
					
					SET @MachineLinkServer =  @MachineLinkServerName+'.'+@MachineLinkServerDB
					set @MachineLinkServer = REPLACE(@MachineLinkServer,'TABLE_NAME','OP100_10_GLOBALDATA')
					
					set @dynamic_query = '
					
					select OP10_RFID as RFID, OP10_MODELNO as PART_NO,OP10_WORKORDER as WORKORDER,ISNULL([OP100_MINDACKG],0) as [READ]
					from ' + @MachineLinkServer +' where ISNULL([OP100_MINDACKG],0)=0
					'
				end
				


				--print @dynamic_query
				exec (@dynamic_query)
	end

	if(@P_Mode='PullMESData')
