					if(@TableName='OP20_LP')
					begin
							set @dynamic_query = '
																		
							select RFID, Dts_Scan, Dts_Pass, Routing, Dcode, Status, CellNo, Profitcenter, MachineCode, OperationCode, FCS, FCA, Recipe_Selected, CT, Serial_No, ModelNo, WorkOrder, Station_Name, Pallet_Number, PISTON_FREE_AIR_FILL_TIME, PISTON_FREE_TEST_TIME, PISTON_FREE_LOW_PR_LIMIT, PISTON_FREE_PRES_ACT, PISTON_FREE_HIGH_PR_LIMIT, PISTON_FREE_MIN_DROP_LIMIT, PFT_DROP_ACTUAL, Test_Method_ADVICS, LP_Test_Result, Test_Cycle_Time, LP_Fill_Min_b, LP_Fill_Act_b, LP_Fill_Max_b, LP_Fill_Time_s, LP_Stb_Time_s, LP_Test_Time_s, LP_Drop_Max_b, LP_Drop_Act_b, Test_Method_Dynamic, Dyn_LP_Test_Result, Dyn_LP_Test_Cycle_Time, Dyn_LP_Fill_Min_b, Dyn_LP_Fill_Act_b, Dyn_LP_Fill_Max_b, Dyn_LP_Fill_Time_s, Dyn_LP_Stb_Time_s, Dyn_LP_Test_Time_s, Dyn_LP_Drop_Max_b, Dyn_LP_Drop_Act_b, Piston_Stroke_Set, Piston_Stroke_Act, Test_Method_Static, Stc_LP_Test_Result, Stc_LP_Test_Cycle_Time, Stc_LP_Fill_Min_b, Stc_LP_Fill_Act_b, Stc_LP_Fill_Max_b, Stc_LP_Fill_Time_s, Stc_LP_Stb_Time_s, Stc_LP_Test_Time_s, Stc_LP_Drop_Max_b, Stc_LP_Drop_Act_b, TS_FLAG, RESERVED31, RESERVED32, RESERVED33, RESERVED34, RESERVED35, [Datetime], isUpdateCompleted, ServerSyncStatus from 
