				@RETURNVALUE= @CurrentDateCode OUTPUT

				SELECT TOP 1 @LinkServerType = KeyValue FROM RoutingConfigDetails (NOLOCK) 
				WHERE ProfitCenterCode = @P_PROFITCENTER_CODE 
				AND LineCode = @P_LINE_CODE AND KeyType = 'LinkServerType' AND STS_CD = 0	
				
				SELECT TOP 1 @MachineLinkServerName = KeyValue FROM RoutingConfigDetails (NOLOCK) 
				WHERE ProfitCenterCode = @P_PROFITCENTER_CODE 
				AND LineCode = @P_LINE_CODE AND KeyType = 'MachineDBLinkServerName' AND STS_CD = 0

				SELECT TOP 1 @MachineLinkServerDB = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE 
				ProfitCenterCode = @P_PROFITCENTER_CODE 
				AND LineCode = @P_LINE_CODE AND KeyType = 'MachineDBLinkServerDB' AND STS_CD = 0

