CREATE PROC [dbo].[Assy_Proc_PushMasterDataIntoMES]
( 
	@MachineLinkServer VARCHAR(300) = NULL, 
	@ProfitCenterCode VARCHAR(20) = '',
	@LineCode VARCHAR(10) = NULL, 
	@Condition VARCHAR(500) = NULL,
	@PartNo VARCHAR(20) = NULL,
	@Barcode VARCHAR(100) = NULL
) 
AS 
BEGIN
	--EXEC Assy_Proc_PushMasterDataIntoMES @MachineLinkServer = '', @ProfitCenterCode = '0064', @LineCode = 'C13', @Condition = 'RoutingConfigLineWise', @PartNo = NULL
	DECLARE @ExecQuery NVARCHAR(MAX) = '',
			@Dynamic_Query NVARCHAR(MAX) = ''
	
	IF @Condition = 'RoutingConfigLineWise'
	BEGIN
		SET @ExecQuery = N'	SELECT ProfitCenterCode,OperationCode,LineCode,MachineCode,OperationRequired,Traceability,Recipe,LabelPrinting,Torque,POKA_YOKE_ALLOWED,Engraving,
		OperationSeqNo,WIP_Quantity,FinalViewingHWPushButton,ScannerPrefix,ScannerSuffix,CycleTime,ent_stamp,last_upd_stamp,ent_by,last_upd_by,Scrap,WIPFIFOCheck,
		ManPowerSeqNo,IS_PLCLogsRequired,IsTextLogRequired,CustomerOperationNo,IsHMIRecipeAvailable,IsPokaYokeForSubStation,Lot_Rework_Key FROM ' + @MachineLinkServer

		IF OBJECT_ID('TEMPDB..#RoutingConfigLineWise_Log') IS NOT NULL
		BEGIN 
			DROP TABLE #RoutingConfigLineWise_Log
		END
			 
		SELECT	ProfitCenterCode,OperationCode,LineCode,MachineCode,OperationRequired,Traceability,Recipe,LabelPrinting,Torque,POKA_YOKE_ALLOWED,Engraving,
			OperationSeqNo,WIP_Quantity,FinalViewingHWPushButton,ScannerPrefix,ScannerSuffix,CycleTime,ent_stamp,last_upd_stamp,ent_by,last_upd_by,Scrap,WIPFIFOCheck,
			ManPowerSeqNo,IS_PLCLogsRequired,IsTextLogRequired,CustomerOperationNo,IsHMIRecipeAvailable,IsPokaYokeForSubStation,Lot_Rework_Key
		INTO #RoutingConfigLineWise_Log
		FROM RoutingConfigLineWise WITH (NOLOCK) WHERE 1 = 2

		PRINT @ExecQuery

		INSERT INTO #RoutingConfigLineWise_Log
		EXECUTE (@ExecQuery)

		IF EXISTS 
		( 
			SELECT TOP 1 1 FROM  #RoutingConfigLineWise_Log
		) 
		BEGIN 
			INSERT INTO RoutingConfigLineWise_Log
			( 
				ProfitCenterCode,OperationCode,LineCode,MachineCode,OperationRequired,Traceability,Recipe,LabelPrinting,Torque,POKA_YOKE_ALLOWED,Engraving,OperationSeqNo,
				WIP_Quantity,FinalViewingHWPushButton,ScannerPrefix,ScannerSuffix,CycleTime,ent_stamp,last_upd_stamp,ent_by,last_upd_by,Scrap,WIPFIFOCheck,ManPowerSeqNo,
				IS_PLCLogsRequired,IsTextLogRequired,CustomerOperationNo,IsHMIRecipeAvailable,IsPokaYokeForSubStation,Lot_Rework_Key,AUDIT_DELETED
			)
			SELECT 
				ProfitCenterCode,OperationCode,LineCode,MachineCode,OperationRequired,Traceability,Recipe,LabelPrinting,Torque,POKA_YOKE_ALLOWED,Engraving,OperationSeqNo,
				WIP_Quantity,FinalViewingHWPushButton,ScannerPrefix,ScannerSuffix,CycleTime,ent_stamp,last_upd_stamp,ent_by,last_upd_by,Scrap,WIPFIFOCheck,ManPowerSeqNo,
				IS_PLCLogsRequired,IsTextLogRequired,CustomerOperationNo,IsHMIRecipeAvailable,IsPokaYokeForSubStation,Lot_Rework_Key,GETDATE()
			FROM #RoutingConfigLineWise_Log
		END

		SET @Dynamic_Query = '
				
		DELETE FROM ' + ISNULL(@MachineLinkServer,'') + '

		INSERT INTO ' + ISNULL(@MachineLinkServer,'') + '(ProfitCenterCode,OperationCode,LineCode,MachineCode,OperationRequired,Traceability,Recipe,LabelPrinting,Torque,
		POKA_YOKE_ALLOWED,Engraving,OperationSeqNo,WIP_Quantity,FinalViewingHWPushButton,ScannerPrefix,ScannerSuffix,CycleTime,ent_stamp,last_upd_stamp,ent_by,last_upd_by,Scrap,
		WIPFIFOCheck,ManPowerSeqNo,IS_PLCLogsRequired,IsTextLogRequired,CustomerOperationNo,IsHMIRecipeAvailable,IsPokaYokeForSubStation,Lot_Rework_Key)
						
		SELECT ProfitCenterCode,OperationCode,LineCode,MachineCode,OperationRequired,Traceability,Recipe,LabelPrinting,Torque,POKA_YOKE_ALLOWED,Engraving,OperationSeqNo,
		WIP_Quantity,FinalViewingHWPushButton,ScannerPrefix,ScannerSuffix,CycleTime,ent_stamp,last_upd_stamp,ent_by,last_upd_by,Scrap,WIPFIFOCheck,ManPowerSeqNo,
		IS_PLCLogsRequired,IsTextLogRequired,CustomerOperationNo,IsHMIRecipeAvailable,IsPokaYokeForSubStation,Lot_Rework_Key FROM RoutingConfigLineWise (NOLOCK)
		WHERE ProfitCenterCode = ''' + @ProfitCenterCode + ''' AND LineCode = ''' + @LineCode + ''''

		PRINT @Dynamic_Query
		EXEC (@Dynamic_Query)
	END
	ELSE IF @Condition = 'RoutingConfigPartWise'
	BEGIN
		SET @ExecQuery = ''
		SET @ExecQuery = N'	SELECT ProfitCenterCode,OperationCode,PartNo,MachineCode,OperationRequired,Traceability,Recipe,LabelPrinting,Torque,Engraving,POKA_YOKE_ALLOWED,
		OperationSeqNo,ent_stamp,last_upd_stamp,ent_by,last_upd_by,Part_FixtureGroupType,IsCPValidationRequired,ChildPartsList,CPBomQty,CPTraceFlag,TSBarcodeSeq FROM '
		+ @MachineLinkServer

		IF OBJECT_ID('TEMPDB..#RoutingConfigPartWise_Log') IS NOT NULL
		BEGIN 
			DROP TABLE #RoutingConfigPartWise_Log
		END
			 
		SELECT	ProfitCenterCode,OperationCode,PartNo,MachineCode,OperationRequired,Traceability,Recipe,LabelPrinting,Torque,Engraving,POKA_YOKE_ALLOWED,
		OperationSeqNo,ent_stamp,last_upd_stamp,ent_by,last_upd_by,Part_FixtureGroupType,IsCPValidationRequired,ChildPartsList,CPBomQty,CPTraceFlag,TSBarcodeSeq
		INTO #RoutingConfigPartWise_Log
		FROM RoutingConfigPartWise WITH (NOLOCK) WHERE 1 = 2

		PRINT @ExecQuery
		INSERT INTO #RoutingConfigPartWise_Log
		EXECUTE (@ExecQuery)

		IF EXISTS 
		( 
			SELECT TOP 1 1 FROM  #RoutingConfigPartWise_Log
		) 
		BEGIN 
			INSERT INTO RoutingConfigPartWise_Log
			( 
				ProfitCenterCode,OperationCode,PartNo,MachineCode,OperationRequired,Traceability,Recipe,LabelPrinting,Torque,Engraving,POKA_YOKE_ALLOWED,
				OperationSeqNo,ent_stamp,last_upd_stamp,ent_by,last_upd_by,Part_FixtureGroupType,IsCPValidationRequired,ChildPartsList,CPBomQty,CPTraceFlag,TSBarcodeSeq,AUDIT_DELETED
			)
			SELECT 
				ProfitCenterCode,OperationCode,PartNo,MachineCode,OperationRequired,Traceability,Recipe,LabelPrinting,Torque,Engraving,POKA_YOKE_ALLOWED,
				OperationSeqNo,ent_stamp,last_upd_stamp,ent_by,last_upd_by,Part_FixtureGroupType,IsCPValidationRequired,ChildPartsList,CPBomQty,CPTraceFlag,TSBarcodeSeq,GETDATE()
			FROM #RoutingConfigPartWise_Log
		END

		SET @Dynamic_Query = ''
		SET @Dynamic_Query = '
				
		DELETE FROM ' + ISNULL(@MachineLinkServer,'') + '

		INSERT INTO ' + ISNULL(@MachineLinkServer,'') + '(ProfitCenterCode,OperationCode,PartNo,MachineCode,OperationRequired,Traceability,Recipe,LabelPrinting,Torque,Engraving,POKA_YOKE_ALLOWED,
		OperationSeqNo,ent_stamp,last_upd_stamp,ent_by,last_upd_by,Part_FixtureGroupType,IsCPValidationRequired,ChildPartsList,CPBomQty,CPTraceFlag,TSBarcodeSeq)
						
		SELECT ProfitCenterCode,OperationCode,PartNo,MachineCode,OperationRequired,Traceability,Recipe,LabelPrinting,Torque,Engraving,POKA_YOKE_ALLOWED,
		OperationSeqNo,ent_stamp,last_upd_stamp,ent_by,last_upd_by,Part_FixtureGroupType,IsCPValidationRequired,ChildPartsList,CPBomQty,CPTraceFlag,TSBarcodeSeq
		FROM RoutingConfigPartWise (NOLOCK)
		WHERE ProfitCenterCode = ''' + @ProfitCenterCode + ''' AND PartNo = ''' + @PartNo + ''''

		PRINT @Dynamic_Query
		EXEC (@Dynamic_Query)
	END
	ELSE IF @Condition = 'Assy_PokaYoke'
	BEGIN
		SET @ExecQuery = N'	SELECT ProfitCenterCode,LineCode,Datecode,PartNumber,PartDescription,CustPartNo,MachineCode,MachineDescription,PokaYokeNumber,Description,ExpiryDate,Barcode,
				IsPrinted,IsActive,EntBy,EntDt,UpdBy,UpdDt,ExpResult,ResVerRequired,SubMachineCode FROM ' + @MachineLinkServer + ''

		IF OBJECT_ID('TEMPDB..#Assy_PokaYoke_Log') IS NOT NULL
		BEGIN 
			DROP TABLE #Assy_PokaYoke_Log
		END
			 
		SELECT	ProfitCenterCode,LineCode,Datecode,PartNumber,PartDescription,CustPartNo,MachineCode,MachineDescription,PokaYokeNumber,Description,ExpiryDate,Barcode,
				IsPrinted,IsActive,EntBy,EntDt,UpdBy,UpdDt,ExpResult,ResVerRequired,SubMachineCode
		INTO #Assy_PokaYoke_Log
		FROM Assy_PokaYoke WITH (NOLOCK) WHERE 1 = 2

		PRINT @ExecQuery

		INSERT INTO #Assy_PokaYoke_Log
		EXECUTE (@ExecQuery)

		IF EXISTS 
		( 
			SELECT TOP 1 1 FROM  #Assy_PokaYoke_Log
		) 
		BEGIN 
			INSERT INTO Assy_PokaYoke_Log
			( 
				ProfitCenterCode,LineCode,Datecode,PartNumber,PartDescription,CustPartNo,MachineCode,MachineDescription,PokaYokeNumber,Description,ExpiryDate,Barcode,
				IsPrinted,IsActive,EntBy,EntDt,UpdBy,UpdDt,ExpResult,ResVerRequired,SubMachineCode,AUDIT_DELETED
			)
			SELECT 
				ProfitCenterCode,LineCode,Datecode,PartNumber,PartDescription,CustPartNo,MachineCode,MachineDescription,PokaYokeNumber,Description,ExpiryDate,Barcode,
				IsPrinted,IsActive,EntBy,EntDt,UpdBy,UpdDt,ExpResult,ResVerRequired,SubMachineCode,GETDATE()
			FROM #Assy_PokaYoke_Log
		END

		SET @Dynamic_Query = '
				
		DELETE FROM ' + ISNULL(@MachineLinkServer,'')  + ' WHERE ProfitCenterCode = ''' + @ProfitCenterCode + ''' AND LineCode = ''' + @LineCode + '''

		INSERT INTO ' + ISNULL(@MachineLinkServer,'') + '(ProfitCenterCode,LineCode,Datecode,PartNumber,PartDescription,CustPartNo,MachineCode,MachineDescription,PokaYokeNumber,
			Description,ExpiryDate,Barcode,IsPrinted,IsActive,EntBy,EntDt,UpdBy,UpdDt,ExpResult,ResVerRequired,SubMachineCode)
						
		SELECT ProfitCenterCode,LineCode,Datecode,PartNumber,PartDescription,CustPartNo,MachineCode,MachineDescription,PokaYokeNumber,
			Description,ExpiryDate,Barcode,IsPrinted,IsActive,EntBy,EntDt,UpdBy,UpdDt,ExpResult,ResVerRequired,SubMachineCode FROM Assy_PokaYoke (NOLOCK)
		WHERE ProfitCenterCode = ''' + @ProfitCenterCode + ''' AND LineCode = ''' + @LineCode + ''''

		PRINT @Dynamic_Query
		EXEC (@Dynamic_Query)
	END
END
GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_QCUsers_VALIDATION]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
Declare @UserId VARCHAR(20), @UserType VARCHAR(50)
SET @UserId = '1445'
SET @UserType = 'Quality'

INSERT INTO QCUsers
SELECT @UserId,'Bypass ManPower',1,GETDATE(),@UserType
UNION
SELECT @UserId,'Manual Label Printing',1,GETDATE(),@UserType
UNION
SELECT @UserId,'Manual Pass',1,GETDATE(),@UserType
UNION
SELECT @UserId,'Missing Barcode Reprint',1,GETDATE(),@UserType
UNION
SELECT @UserId,'Reprint Coupling Barcode',1,GETDATE(),@UserType

Update QCUsers Set IsAuthorise = 1 where UserId = '1445' AND CaptionName = 'Manual Label Printing'
*/
CREATE PROCEDURE [dbo].[Assy_Proc_QCUsers_VALIDATION] 
	@UserName VARCHAR(10) = NULL,
	@Password VARCHAR(30) = NULL,
	@CaptionName VARCHAR(200) = NULL,
	@Condition VARCHAR(MAX) = NULL,
	@Status VARCHAR(50) = NULL,
	@IntStatus INT = NULL,
	@Linecode VARCHAR(10) = NULL,
	@ReturnValue VARCHAR (2000) = NULL OUT,
	@ReturnInt INT = NULL OUT
AS
BEGIN
		-- =============================================
		-- Author:		<Rashid Siddiqui>
		-- Create date: <25 August 2015>
		-- Description:	<To Check QC Permission>
		-- To Rembember
		-- Nothing = 0
		-- Success = 1
		-- Error = 2
		-- AlreadyExists = 3
		-- NotExists = 4
		-- =============================================
	BEGIN TRY
		IF(@Condition = 'QCLogin')
		BEGIN
			IF EXISTS(SELECT 1 FROM QCUsers WHERE UserId = @UserName AND CaptionName = @CaptionName AND ISNULL(IsAuthorise,0) = 1)
			BEGIN
				IF EXISTS(SELECT 1 FROM TL_MF_SEC_USER_MST(NOLOCK) WHERE USER_CODE = @UserName AND Password = @Password)
				BEGIN
					INSERT INTO QCUsers_Login_History (UserId,CaptionName,LineCode,Status)
					SELECT @UserName, @CaptionName, @Linecode, @Status
					SELECT @UserName UserID, 1 bStatus
				END
				ELSE
					SELECT @UserName UserID, 2 bStatus
			END
			ELSE
				SELECT @UserName UserID, 0 bStatus
		END
		ELSE IF(@Condition = 'QCLoginDefault')
		BEGIN
			IF EXISTS(SELECT 1 FROM QCUsers WHERE UserId = @UserName AND CaptionName = @CaptionName AND ISNULL(IsAuthorise,0) = 1)
			BEGIN
				INSERT INTO QCUsers_Login_History (UserId,CaptionName,LineCode,Status)
				SELECT @UserName, @CaptionName, @Linecode, @Status
				
				SELECT @UserName UserID, 1 bStatus
			END
		END
		ELSE IF(@Condition = 'QCEnableDisableStatus')
		BEGIN
			IF (@IntStatus IN (0,1))
			BEGIN
				INSERT INTO QCUsers_Login_History (UserId,CaptionName,LineCode,Status)
				SELECT @UserName, @CaptionName, @Linecode, @Status
			END
		END
		--End Add by Rashid Siddiqui 25/08/2015 for QC -- 
		END TRY 
	BEGIN CATCH  
		--CATCH BLOCK BEGINS
		
		SET @ReturnValue =	CAST(ERROR_NUMBER() as VARCHAR(5)) + '|' + 
		CAST(ERROR_SEVERITY()as VARCHAR(5)) + '|' + 
		CAST(ERROR_STATE() as VARCHAR(5)) + '|' + 
		CAST(ERROR_PROCEDURE() as VARCHAR(200)) + '|' + 
		CAST(ERROR_LINE() as VARCHAR(5)) + '|' + 
		CAST(ERROR_MESSAGE() as VARCHAR(1500))
		raiserror(@ReturnValue,16,1)
		SET @ReturnInt = 2
	--CATCH BLOCK ENDS 
	END CATCH
END

GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_RejectionAccounting]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO



CREATE  proc [dbo].[Assy_Proc_RejectionAccounting]
@Mode VARCHAR(50),
@PartType VARCHAR(15)=NULL,
@Barcode VARCHAR(100)=NULL,
@PartNo VARCHAR(60)=NULL,
@DateCode CHAR(5)=NULL,
@Data VARCHAR(2000)=NULL,
@ReworkData VARCHAR(MAX)=NULL,
@WorkCenterCode VARCHAR(10)=NULL,
@BOMVersion smallint=NULL,
@Qty INT=NULL,
@CodeBIL VARCHAR(10)=NULL,
@LoveCode VARCHAR(10)=NULL,	
@StorageLocationCode VARCHAR(10)=NULL,
@ProductionDate datetime =NULL,
@Shift VARCHAR(10)=NULL,
@Description VARCHAR(500)=NULL,
@FecthingDateTime VARCHAR(30)=NULL,
@UserCode VARCHAR(10)=NULL,
@UserPassword VARCHAR(20)=NULL,
@ProfitCenterCode VARCHAR(5),
@DateFrom datetime =NULL,
@DateTo datetime =NULL,
@LineCode VARCHAR(10)=NULL,
@ReworkCenterLineCode VARCHAR(10)=NULL,
@isDateWise BIT=NULL,
@RecordRefIDStr VARCHAR(MAX)=NULL,
@RETURNVALUE      VARCHAR (2000)=NULL out,
@RETURNINT        INT=NULL out,
@RecordRefID BIGINT=NULL
AS
BEGIN	
	DECLARE @ProductionLocationCode VARCHAR(10)
	DECLARE @RejectionID BIGINT
	DECLARE @Query varchar(max)
	DECLARE @ReasonID BIGINT
	DECLARE @RefRejectionID VARCHAR(MAX)

	DECLARE @FG_PART_TYPE VARCHAR(50)
	DECLARE @RM_PART_TYPE_1 VARCHAR(50)
	DECLARE @RM_PART_TYPE_2 VARCHAR(50)
	DECLARE @LineTypeCode VARCHAR(500)

	SELECT @ProductionLocationCode=PARAMETER_VALUE FROM PARAMETER_MST 
	WHERE PARAMETER_C ='ASSLINE' AND PARAMETER_C1='RejectionAccounting' AND PARAMETER_C2='ProductionLocation'
	AND wh_code=@ProfitCenterCode

	SELECT @FG_PART_TYPE=PARAMETER_VALUE FROM PARAMETER_MST 
	WHERE PARAMETER_C ='ASSLINE' AND PARAMETER_C1='RejectionAccounting' AND PARAMETER_C2='FG_PART_TYPE'
	AND wh_code=@ProfitCenterCode

	SELECT @RM_PART_TYPE_1=PARAMETER_VALUE FROM PARAMETER_MST 
	WHERE PARAMETER_C ='ASSLINE' AND PARAMETER_C1='RejectionAccounting' AND PARAMETER_C2='RM_PART_TYPE_1'
	AND wh_code=@ProfitCenterCode
	SELECT @RM_PART_TYPE_2=PARAMETER_VALUE FROM PARAMETER_MST 
	WHERE PARAMETER_C ='ASSLINE' AND PARAMETER_C1='RejectionAccounting' AND PARAMETER_C2='RM_PART_TYPE_2'
	AND wh_code=@ProfitCenterCode
	
	IF @Mode='VALIDATE_DATECODE'
	BEGIN
		
		CREATE TABLE #tmpDateCode
		(
			Date VARCHAR(15),
			FromTime VARCHAR(10),
			ToTime VARCHAR(10)
		)


		SET @Query=' INSERT INTO #tmpDateCode(Date,FromTime,ToTime)
		EXEC ASSY_PROC_GETDATE_FROMDATECODE '''+@DateCode+''','''+@ProfitCenterCode+''' '

		EXEC(@Query)

		

		IF EXISTS(SELECT 1 FROM #tmpDateCode)
		BEGIN
			
			--exec ASSY_PROC_MANUAL_DATECODE @OPERATION='VALIDATE_DATECODE',@MANUAL_DATECODE=@DateCode,
			--@PROFITCENTERCODE=@ProfitCenterCode,@LINECODE=@LineCode,@RETURNVALUE=@RETURNVALUE out,@ReturnInt=@ReturnInt out
			
			SET @RETURNVALUE='12Ac'
			SET @ReturnInt=1
		END
		ELSE
		BEGIN
			SET @ReturnValue='Date Code is not valid.'
			SET @ReturnInt=0
		END

		
	END
	IF @Mode='VALIDATE_USER'
	BEGIN
		IF EXISTS(SELECT 1 FROM TL_MF_SEC_USER_MST WHERE USER_CODE=@UserCode AND PASSWORD=@UserPassword)
		BEGIN
			SET @ReturnValue='VALID'
			SET @ReturnInt=1
		END
		ELSE
		BEGIN
			SET @ReturnValue='User is not valid.'
			SET @ReturnInt=0
		END
	END
	IF @Mode='GET_REWORK_PRINT'
	BEGIN

	
		
		SELECT dtl.PartNo as PART_NO, CAST((sum(dtl.ReworkQty)-sum(ISNULL(dtl.PrintedQty,0))) AS VARCHAR)+'|'+CAST(C.PIECES_PER_BOX AS VARCHAR) as REWORK_QTY 
		FROM Assy_RejectionAccountingRework_Dtl dtl
		inner join Assy_RejectionAccountingRework_Hdr hdr		
		on hdr.RejectionID=dtl.RejectionID and hdr.ProfitCenterCode=dtl.ProfitCenterCode
		INNER JOIN PRODUCT_MASTER C
		ON HDR.PartNo=C.SEWS_PART_NO
		AND HDR.ProfitCenterCode=C.warehouse_cd
		WHERE  dtl.ProfitCenterCode=@ProfitCenterCode AND HDR.LineCode=@LineCode
		AND ISNULL(hdr.isPrinted,0)=0
		and dtl.ReworkQty-ISNULL(dtl.PrintedQty,0)>0 group by dtl.PartNo,C.PIECES_PER_BOX 
		ORDER BY dtl.PartNo

		

		SET @ReturnValue='DATA SELECTED'
		SET @ReturnInt=1
	END 
	IF @Mode='GET_WORKCENTER'
	BEGIN

		SELECT @LineTypeCode=PM.PARAMETER_VALUE FROM PARAMETER_MST PM WHERE PM.PARAMETER_C='ASSLINE' 
		AND PM.PARAMETER_C1='RejectionAccounting' AND PM.PARAMETER_C2='LineTypeCode' 
		AND PM.wh_code=@ProfitCenterCode

		PRINT @LineTypeCode
		IF(ISNULL(@LineTypeCode,'')<>'')
		BEGIN
			SELECT LineCode,WorkCenterCode   FROM LineMst  
			WHERE ProfitCenterCode=@ProfitCenterCode and ISNULL(ISACTIVE,0)=1 
			AND LineTypeCode IN (SELECT DISTINCT data FROM Splitstring(@LineTypeCode, ','))
			ORDER BY LineCode
		END
		ELSE
		BEGIN
			SELECT LineCode,WorkCenterCode   FROM LineMst  
			WHERE ProfitCenterCode=@ProfitCenterCode and ISNULL(ISACTIVE,0)=1 --AND LineTypeCode IN ('LTMC','LSTMC')
			ORDER BY LineCode
		END
	END
	IF @Mode='GET_BUTTON_CAPTION'
	BEGIN
		SELECT ISNULL(@RM_PART_TYPE_1,'TMC') BTN_TMC_CAPTION,ISNULL(@RM_PART_TYPE_2,'SERVO') BTN_SERVO_CAPTION
	END
	IF @Mode='REWORK_PRINT'
	BEGIN
	 BEGIN TRY
		
		IF (SELECT SNAPSHOT_ISOLATION_STATE FROM SYS.DATABASES WHERE NAME = DB_NAME()) = 1
		BEGIN
			   SET TRANSACTION ISOLATION LEVEL SNAPSHOT
		END

		BEGIN TRAN	
			DECLARE @BINCAPACITY INT
			DECLARE @LOCATIONID VARCHAR(10)=@ProductionLocationCode
			
			
			DECLARE @SERIAL_NO VARCHAR(50);
			DECLARE @ITEM_NO INT
			DECLARE @ZONE_CODE VARCHAR(10)			

			-- GETTING SERIAL FOR MULTIPLE PRINT
			 DECLARE @PackSize INT
			 DECLARE @PrintQty INT
			 DECLARE @TotalQty INT

			 SET @TotalQty=@Qty

			
			 SELECT @PackSize=PIECES_PER_BOX,@PartType=material_tp,@ITEM_NO = item_no FROM PRODUCT_MASTER WHERE SEWS_PART_NO=@PartNo AND warehouse_cd=@ProfitCenterCode AND ISNULL(STS_CD,0)=0
			 

			SELECT @ZONE_CODE = zone_cd   FROM   location_master(nolock) WHERE  loc_id = @LOCATIONID AND wh_code = @ProfitCenterCode

			 DECLARE @_Barcode VARCHAR(100)
			DECLARE @SerialNo VARCHAR(8)
			DECLARE @SN BIGINT
			-- GET DATE CODE
			DECLARE @DateCodeInt int,@DateCodeValue varchar(5)
			exec [ASSY_PROC_GET_DATECODE] @ProfitCenterCode,@LineCode,@DateCodeValue  out,@DateCodeInt   out
			
			 SET @PrintQty=@Qty
			 
			 WHILE @Qty>0
			 BEGIN
				
				IF @Qty>@PackSize
				BEGIN
					SET @Qty=@Qty-@PackSize
					SET @PrintQty=@PackSize
				END
				ELSE
				BEGIN
					
					SET @PrintQty=@Qty
					SET @Qty=0
				END
				
				  --- GENERATING SERIAL NO
				 
					exec ASSY_PROC_GET_NEW_SERIAL_NO @UserCode,@ProfitCenterCode,@SERIAL_NO out
				
					

					INSERT INTO [DBO].[inv_serial]
					([serial_no],[item_no],[loc_id],pallet_phy_id,[wh_code],[zone_cd],[serial_qty],[seq_no],[sts_cd],
					[ent_stamp],[ent_by],[last_upd_stamp],[last_upd_by],[int_lot_no],[sews_part_no])
					VALUES( @SERIAL_NO, @ITEM_NO,@LocationId, '', @ProfitCenterCode, @ZONE_CODE, @PrintQty,0,0,Getdate(), @UserCode, Getdate(), @UserCode, 0, @PartNo)

					INSERT INTO [dbo].[TRANS_LOG] ([SERIAL_NO] ,[FROM_CD],[TO_CD],[ORDER_NO] ,[DELV_BOL_NO],[ITEM_NO],[SERIAL_QTY] ,[WH_CODE],[ENT_STAMP],[ENT_BY],[PALLET_NO]
					,[INPFLNAME_ID],[PROGRAM_ID] ,[TRAN_TYPE],[TR_TRNBR],[pallet_phy_id])
					VALUES(@SERIAL_NO,@LocationId, @LocationId,'','', @ITEM_NO,@PrintQty, @ProfitCenterCode,GETDATE(),@UserCode,'', NULL,'ASSY_REWORK_LABEL',NULL, NULL,'')

					----- GENERATE BARCODE
					
					-- GET SERIAL NO
					SELECT @SN=ISNULL(MAX(Counter),0) FROM Assy_RejectionAccountingSerial WHERE LineCode=@LineCode AND ProfitCenterCode=@ProfitCenterCode AND PartNo=@PartNo

					IF(@SN)=0
					BEGIN
						SET @SerialNo='R0000001'
					END
					ELSE
					BEGIN
						SET @SerialNo='R'+RIGHT('00000000'+CAST(@SN+1 AS VARCHAR),7)
					END
					PRINT '-6-'
					IF EXISTS(SELECT 1 FROM Assy_RejectionAccountingSerial WHERE LineCode=@LineCode AND ProfitCenterCode=@ProfitCenterCode AND PartNo=@PartNo)
					BEGIN 
						UPDATE Assy_RejectionAccountingSerial SET Counter=ISNULL(Counter,0)+1,SerialNo=@SerialNo  WHERE LineCode=@LineCode AND ProfitCenterCode=@ProfitCenterCode AND PartNo=@PartNo
					END
					else
					BEGIN 
						INSERT INTO Assy_RejectionAccountingSerial(ProfitCenterCode,LineCode,PartNo,Counter,SerialNo,LastPrintedBarcode,LastPrintTimeStamp)
						VALUES(@ProfitCenterCode,@LineCode,@PartNo,1,@SerialNo,'',GETDATE())
					END
					
										
					SET @_Barcode=@PartNo+@DateCodeValue+@SerialNo+@LineCode

					
					INSERT INTO Assy_RejectionAccountingRework_Print
					(PART_NO,DateCode,Barcode,SerialNo,LineCode,QTY,TRACABILITY_NO,PartType,[user_name],[Ent_dt], WH_CODE)
					VALUES (@PartNo,@DateCodeValue,@_Barcode,@SerialNo,@LineCode,@PrintQty,@SERIAL_NO,@PartType, @UserCode,getdate(),@ProfitCenterCode)

					SET @ReturnValue=isnull(@ReturnValue,'')+@_Barcode+'~'+@DateCodeValue+'~'+@SerialNo+'|'

				---END WHILE LOOP
			 END


			

				-- UPDATE THE PRINTED QTY
				
				DECLARE @_RejectionID BIGINT
				DECLARE @_PartQty INT
				DECLARE @_ReworkQty INT
				DECLARE @_PrintedQty INT
				DECLARE @_PendingQty INT

				SET @Qty= @TotalQty

				DECLARE CURSOR_UPDATE CURSOR FOR 
					SELECT B.RejectionID,B.PartQty,B.ReworkQty,B.PrintedQty FROM  Assy_RejectionAccountingRework_Dtl B					
					WHERE B.PartNo=@PartNo and B.ProfitCenterCode=@ProfitCenterCode AND B.ReworkQty>ISNULL(B.PrintedQty,0)
					ORDER BY B.RejectionID
				OPEN CURSOR_UPDATE   
				FETCH NEXT FROM CURSOR_UPDATE INTO @_RejectionID,@_PartQty,@_ReworkQty,@_PrintedQty

				WHILE @@FETCH_STATUS = 0   
					BEGIN   
				
						SET @_PendingQty=ISNULL(@_ReworkQty,0)-ISNULL(@_PrintedQty,0)
					
						IF @Qty>=@_PendingQty
						BEGIN
							SET @Qty=@Qty-@_PendingQty
						END
						ELSE
						BEGIN
							
							SET @_PendingQty=@Qty
							SET @Qty=0
						END
					

						IF @_PendingQty>0
						BEGIN				
										

							UPDATE Assy_RejectionAccountingRework_Dtl SET PrintedQty=ISNULL(PrintedQty,0)+@_PendingQty WHERE RejectionID=@_RejectionID AND PartNo=@PartNo
							AND ReworkQty=@_ReworkQty AND ISNULL(PrintedQty,0)=ISNULL(@_PrintedQty,0)
						END
						FETCH NEXT FROM CURSOR_UPDATE INTO @_RejectionID,@_PartQty,@_ReworkQty,@_PrintedQty 
					END   

				CLOSE CURSOR_UPDATE   
				DEALLOCATE CURSOR_UPDATE
				-- END OF UPDATE PRINTED QTY

			  --SET @ReturnValue=@SERIAL_NO
			  SET @ReturnInt=1

			  COMMIT TRAN
			END TRY
			BEGIN CATCH						
				SET @ReturnValue='ERROR'
				SET @ReturnInt=0

				ROLLBACK TRAN				
				THROW				
			END CATCH

		  END 
	IF @Mode='GET_REWORK_REPRINT'
	BEGIN
		
		IF @PartType='NEW'
		BEGIN
			SELECT DISTINCT PART_NO as PartNo,Barcode,DateCode,SerialNo,PartType
			FROM Assy_RejectionAccountingRework_Print
			WHERE PART_NO LIKE CONCAT(@PartNo, '%') AND WH_CODE=@ProfitCenterCode
			AND LineCode=@LineCode

		END
		ELSE
		BEGIN
			SELECT DISTINCT B.CHILD_PART_NO as PartNo,B.CHILD_Barcode as Barcode,B.DateCode,C.SerialNo,B.PART_TYPE as PartType
			FROM Assy_RejectionAccountingRework_Dtl A INNER JOIN Assy_CouplingDetails B
			ON A.PartNo=B.CHILD_PART_NO
			and a.ProfitCenterCode=b.ProfitCentreCode
			INNER JOIN ASSY_Vision_System C
			ON B.CHILD_Barcode=C.Barcode
			AND C.ProfitCenterCode=b.ProfitCentreCode
			WHERE A.PartNo LIKE CONCAT(@PartNo, '%')
			AND B.LineCode=@LineCode
			and B.ProfitCentreCode=@ProfitCenterCode
		END
		

		
		SET @ReturnValue='DATA SELECTED'
		SET @ReturnInt=1
	END 
	IF @Mode='SAVE_REPRINT'
	BEGIN
			IF ISNULL(@Data,'')<>''
			BEGIN
					IF Object_id('tempdb..#temp_row_RePrint') IS NOT NULL
						DROP TABLE #temp_row_RePrint

					SELECT col1
					INTO   #temp_row_RePrint
					FROM   [dbo].[Fn_grid_split_string](@Data, '~', '|')
					
					
					INSERT INTO Assy_RejectionAccountingRework_RePrint
					(WH_CODE,LineCode,Barcode,Reason,ReworkCenterLineCode,USER_NAME,ENT_DT)
					SELECT @ProfitCenterCode,@LineCode,col1,@Description,@ReworkCenterLineCode,@UserCode,GETDATE() FROM #temp_row_RePrint
			END
			SET @ReturnValue='SAVED'
			SET @ReturnInt=1
	END 	
	IF @Mode='VALIDATE_QTY'
	BEGIN
		-- VALIDATE THE QTY IF BARCODE IS NOT SCANNED
		DECLARE @ScrapQty INT
		DECLARE @FeedQty INT
		DECLARE @StockQty INT

		IF ISNULL(@Barcode,'')=''
		BEGIN
			-- IF MATERIAL FEEDING ON AND TALLY CHART ON
			IF(SELECT PARAMETER_VALUE from PARAMETER_MST where PARAMETER_C='ASSLINE' AND PARAMETER_C1='RejectionAccounting' AND PARAMETER_C2='sTallyChartValidationOn' AND wh_code=@ProfitCenterCode)='Y'
				BEGIN
					IF @PartType='FG'
					BEGIN
						SELECT @ScrapQty=COUNT(PartNo) FROM Assy_TallyChartStatusData	WHERE PartNo=@PartNo AND ProfitCenterCode=@ProfitCenterCode AND LineCode=@LineCode and ISNULL(Result,'')<>'PASS'
					END
					ELSE
					BEGIN
					
						SELECT @ScrapQty=SUM(ISNULL(ScrappedQty,0)) FROM Assy_TallyChartMaterialStatus WHERE ChildPartNo=@PartNo AND ProfitCenterCode=@ProfitCenterCode AND LineCode=@LineCode
						
					END
				END
				-- IF MATERIAL FEEDING ON AND TALLY CHART OFF
				IF(SELECT PARAMETER_VALUE from PARAMETER_MST where PARAMETER_C='ASSLINE' AND PARAMETER_C1='RejectionAccounting' AND PARAMETER_C2='isMaterialFeedingOn' AND wh_code=@ProfitCenterCode)='Y'				
				BEGIN
					IF @PartType<>'FG'
					BEGIN
						SELECT @StockQty=SUM(B.SERIAL_QTY) FROM Assy_MaterialFeeding A INNER JOIN INV_SERIAL B
						ON A.PacketId=B.SERIAL_NO AND A.ProfitCenterCode=B.WH_CODE
						WHERE ProfitCenterCode=@ProfitCenterCode AND LineCode=@LineCode
						AND A.ChildPartNo=@PartNo
					END					 
				END
				-- IF MATERIAL FEEDING OFF AND TALLY CHART OFF
				IF(SELECT PARAMETER_VALUE from PARAMETER_MST where PARAMETER_C='ASSLINE' AND PARAMETER_C1='RejectionAccounting' AND PARAMETER_C2='isMaterialFeedingOn' AND wh_code=@ProfitCenterCode)<>'Y'
				BEGIN
				
					IF @PartType<>'FG'
					BEGIN
						SELECT @StockQty=SUM(SERIAL_QTY) FROM  INV_SERIAL WHERE WH_CODE=@ProfitCenterCode AND SEWS_PART_NO=@PartNo
						AND LOC_ID=@ProductionLocationCode AND STS_CD=0
					END					 
				END
		END

		IF ISNULL(@Qty,0)>ISNULL(@ScrapQty,0)+ISNULL(@StockQty,0)
		BEGIN
			SET @ReturnValue='You can not Rework/Reject more than '+cast(ISNULL(@ScrapQty,0)+ISNULL(@StockQty,0) as varchar)+' Qty.Please check the Qty.'
			SET @ReturnInt=0
		END

		SET @ReturnValue='VALID'
		SET @ReturnInt=1
		-- END VALIDATE THE QTY IF BARCODE IS NOT SCANNED
	END
	IF @Mode='EXPLODE_BOM'
	BEGIN
		
		--exec [Assy_Proc_BOM_Explosion] @ProfitCenterCode=@ProfitCenterCode,@PartNumber=@PartNo,@BOM_VERSION=@BOMVersion
		--DROP TABLE  #TEMP_BOM
		CREATE TABLE #TEMP_BOM
		(
			FG_PART_NO VARCHAR(30),
			BOMPART_NO VARCHAR(30),
			RM_PART_NO VARCHAR(30),
			BOM_QTY INT,
			BOM_UNIT VARCHAR(3),
			MAT_PROCURE_TYPE VARCHAR(10),
			MAT_USE_RATIO VARCHAR(10),
			ALT_ITEM_GRP_CODE VARCHAR(10),
			PART_TYPE VARCHAR(30),
			COMMON_PART_TYPE VARCHAR(30),
			PRODUCT_NM VARCHAR(200)
		)
		
		IF (SELECT ISNULL(material_tp,'') from PRODUCT_MASTER where SEWS_PART_NO=@PartNo AND warehouse_cd=@ProfitCenterCode AND STS_CD=0)='STMC'
		BEGIN
			INSERT INTO #TEMP_BOM
			SELECT @PartNo,'','',0,'','','','','STMC','FG','This is STMC Part, Please rework SERVO OR TMC Parts Only'
			SELECT * FROM #TEMP_BOM
			RETURN
		END

		DECLARE @BOMVER VARCHAR(4)
		SET @BOMVER=CAST(@BOMVersion AS VARCHAR)
		set @Query='
		INSERT INTO #TEMP_BOM(FG_PART_NO,BOMPART_NO,RM_PART_NO,BOM_QTY,BOM_UNIT,MAT_PROCURE_TYPE,MAT_USE_RATIO,ALT_ITEM_GRP_CODE)
		exec Proc_BOM_Explosion @ProfitCenterCode='''+@ProfitCenterCode+''',@PartNumber='''+@PartNo+''',@BOM_VERSION='''+@BOMVER+''' '
		exec(@Query)
	
		 UPDATE A SET A.PRODUCT_NM=B.product_nm  FROM #TEMP_BOM A INNER JOIN PRODUCT_MASTER B
		 ON A.RM_PART_NO=B.SEWS_PART_NO
		 WHERE B.warehouse_cd=@ProfitCenterCode AND ISNULL(B.STS_CD,0)=0

		PRINT '@FG_PART_TYPE='+@FG_PART_TYPE
		
		

			--UPDATE #TEMP_BOM SET PART_TYPE='STMC' WHERE BOMPART_NO=@PartNo
			
			--UPDATE A SET A.PART_TYPE=B.PART_TYPE  FROM #TEMP_BOM A INNER JOIN Assy_CouplingDetails B
			--ON A.BOMPART_NO=B.CHILD_PART_NO
			--WHERE B.ProfitCentreCode=@ProfitCenterCode AND B.LineCode=@LineCode

			--UPDATE #TEMP_BOM SET PART_TYPE='OTHER' WHERE ISNULL(PART_TYPE,'')=''
			
			
			---------GET THE DATA
			--SELECT SN,RM_PART_NO,PartType,COMMON_PART_TYPE,BOM_QTY,PRODUCT_NM FROM
			--(
			--	SELECT DISTINCT 3 as SN,RM_PART_NO,'TMC' as PartType,'RM_PART_TYPE_1' COMMON_PART_TYPE,BOM_QTY,PRODUCT_NM FROM #TEMP_BOM WHERE RM_PART_NO=(SELECT TOP 1 BOMPART_NO FROM  #TEMP_BOM WHERE PART_TYPE='TMC')
			--	UNION
			--	SELECT DISTINCT 4 as SN,RM_PART_NO,'TMC_RM' as PartType,'RM_PART_TYPE_1_RM' COMMON_PART_TYPE,BOM_QTY,PRODUCT_NM FROM #TEMP_BOM WHERE BOMPART_NO=(SELECT TOP 1 BOMPART_NO FROM  #TEMP_BOM WHERE PART_TYPE='TMC')
			--	UNION			
			--	SELECT DISTINCT 1 as SN,RM_PART_NO,'SERVO' as PartType,'RM_PART_TYPE_2' COMMON_PART_TYPE,BOM_QTY,PRODUCT_NM FROM #TEMP_BOM WHERE RM_PART_NO=(SELECT TOP 1 BOMPART_NO FROM  #TEMP_BOM WHERE PART_TYPE='SERVO')
			--	UNION
			--	SELECT DISTINCT 2 as SN,RM_PART_NO,'SERVO_RM' as PartType,'RM_PART_TYPE_2_RM' COMMON_PART_TYPE,BOM_QTY,PRODUCT_NM FROM #TEMP_BOM WHERE BOMPART_NO=(SELECT TOP 1 BOMPART_NO FROM  #TEMP_BOM WHERE PART_TYPE='SERVO')
			--	UNION			
			--	SELECT DISTINCT 5 as SN,RM_PART_NO,'STMC_RM' as PartType,'FG_PART_TYPE' COMMON_PART_TYPE,BOM_QTY,PRODUCT_NM FROM #TEMP_BOM WHERE BOMPART_NO=@PartNo
			--	AND RM_PART_NO NOT IN
			--	(
			--		SELECT DISTINCT BOMPART_NO FROM  #TEMP_BOM WHERE PART_TYPE IN('TMC' ,'SERVO')
			--	)
			--) A WHERE ISNULL(A.BOM_QTY,0)>0 ORDER BY SN
		IF (SELECT ISNULL(material_tp,'') from PRODUCT_MASTER where SEWS_PART_NO=@PartNo AND warehouse_cd=@ProfitCenterCode AND STS_CD=0)=@FG_PART_TYPE
		BEGIN 
			UPDATE #TEMP_BOM SET PART_TYPE=@FG_PART_TYPE WHERE BOMPART_NO=@PartNo
			
			--UPDATE A SET A.PART_TYPE=B.PART_TYPE  FROM #TEMP_BOM A INNER JOIN Assy_CouplingDetails B
			--ON A.BOMPART_NO=B.CHILD_PART_NO
			--WHERE B.ProfitCentreCode=@ProfitCenterCode AND B.LineCode=@LineCode

			
			UPDATE A SET A.PART_TYPE=B.MATERIAL_TP  FROM #TEMP_BOM A INNER JOIN PRODUCT_MASTER B
			ON A.BOMPART_NO=B.SEWS_PART_NO
			WHERE B.warehouse_cd=@ProfitCenterCode 
			AND B.SEWS_PART_NO IN (SELECT B.RM_PART_NO FROM #TEMP_BOM B WHERE B.MAT_PROCURE_TYPE='50')

			UPDATE #TEMP_BOM SET PART_TYPE='OTHER' WHERE ISNULL(PART_TYPE,'')=''
			
			
			-------GET THE DATA
			SELECT SN,RM_PART_NO,PartType,COMMON_PART_TYPE,BOM_QTY,PRODUCT_NM FROM
			(
				SELECT DISTINCT 3 as SN,RM_PART_NO,@RM_PART_TYPE_1 as PartType,'RM_PART_TYPE_1' COMMON_PART_TYPE,BOM_QTY,PRODUCT_NM FROM #TEMP_BOM WHERE RM_PART_NO=(SELECT TOP 1 BOMPART_NO FROM  #TEMP_BOM WHERE PART_TYPE=@RM_PART_TYPE_1)
				UNION
				SELECT DISTINCT 4 as SN,RM_PART_NO,@RM_PART_TYPE_1+'_RM' as PartType,'RM_PART_TYPE_1_RM' COMMON_PART_TYPE,BOM_QTY,PRODUCT_NM FROM #TEMP_BOM WHERE BOMPART_NO=(SELECT TOP 1 BOMPART_NO FROM  #TEMP_BOM WHERE PART_TYPE=@RM_PART_TYPE_1)
				UNION			
				SELECT DISTINCT 1 as SN,RM_PART_NO,@RM_PART_TYPE_2 as PartType,'RM_PART_TYPE_2' COMMON_PART_TYPE,BOM_QTY,PRODUCT_NM FROM #TEMP_BOM WHERE RM_PART_NO=(SELECT TOP 1 BOMPART_NO FROM  #TEMP_BOM WHERE PART_TYPE=@RM_PART_TYPE_2)
				UNION
				SELECT DISTINCT 2 as SN,RM_PART_NO,@RM_PART_TYPE_2+'_RM' as PartType,'RM_PART_TYPE_2_RM' COMMON_PART_TYPE,BOM_QTY,PRODUCT_NM FROM #TEMP_BOM WHERE BOMPART_NO=(SELECT TOP 1 BOMPART_NO FROM  #TEMP_BOM WHERE PART_TYPE=@RM_PART_TYPE_2)
				UNION			
				SELECT DISTINCT 5 as SN,RM_PART_NO,@FG_PART_TYPE+'_RM' as PartType,'FG_PART_TYPE_RM' COMMON_PART_TYPE,BOM_QTY,PRODUCT_NM FROM #TEMP_BOM WHERE BOMPART_NO=@PartNo
				AND RM_PART_NO NOT IN
				(
					SELECT DISTINCT BOMPART_NO FROM  #TEMP_BOM WHERE PART_TYPE IN(@RM_PART_TYPE_1 ,@RM_PART_TYPE_2)
				)
			) A WHERE ISNULL(A.BOM_QTY,0)>0 ORDER BY SN

			SELECT @RM_PART_TYPE_1 as 'BTN_TMC_CAPTION',@RM_PART_TYPE_2 'BTN_SERVO_CAPTION'-- USE @RM_PART_TYPE_1 AS TMC PART
																							 -- USE @RM_PART_TYPE_2 AS SERVO PART
		END
		ELSE
		BEGIN
			SELECT RM_PART_NO,PART_TYPE as PartType,PART_TYPE as COMMON_PART_TYPE,BOM_QTY,PRODUCT_NM FROM #TEMP_BOM WHERE ISNULL(BOM_QTY,0)>0
		END
		

		RETURN
	END
	IF @Mode='EXPLODE_RM'
	BEGIN
		
		SELECT SEWS_PART_NO as RM_PART_NO,material_tp as PartType,1 as BOM_QTY,product_nm 
		FROM PRODUCT_MASTER WHERE SEWS_PART_NO=@PartNo AND warehouse_cd=@ProfitCenterCode

