	IF @Mode='BOM_VER'
	BEGIN
		SELECT DISTINCT VER FROM BOM_MASTER WHERE FG_PART_NO=@PartNo AND STS_CD=0 AND WH_CODE=@ProfitCenterCode
	END
	IF @Mode='VALIDATE_BARCODE'
	BEGIN
		DECLARE @_PartCode varchar(30)
		DECLARE @_DateCode varchar(10)
		DECLARE @_WorkCenterCode varchar(10)
		DECLARE @_BomVer varchar(10)
		DECLARE @_Status varchar(10)
		DECLARE @_PartType varchar(30)
		DECLARE @_CouplingDone varchar(30)='NOT_COUPLED'
		
		SELECT @PartNo=PartNo FROM Assy_LineAssyStatus WHERE Barcode=@Barcode AND ProfitCenterCode=@ProfitCenterCode AND LineCode=@LineCode
		IF (SELECT ISNULL(material_tp,'') from PRODUCT_MASTER where SEWS_PART_NO=@PartNo AND warehouse_cd=@ProfitCenterCode AND STS_CD=0)='STMC'
			BEGIN
				SET @ReturnValue='ERROR|This is STMC Part, Please rework SERVO OR TMC Parts Only.'
				SET @ReturnInt=0
				return
			END
		IF EXISTS(SELECT 1 FROM Assy_RejectionAccountingRework_Hdr WHERE Barcode=@Barcode AND ProfitCenterCode=@ProfitCenterCode AND LineCode=@LineCode)
			BEGIN
				SET @ReturnValue='ERROR|Barcode is already marked in Rework.'
				SET @ReturnInt=0
				return
			END

		IF EXISTS(SELECT 1 FROM Assy_LineAssyStatus WHERE Barcode=@Barcode AND ProfitCenterCode=@ProfitCenterCode AND LineCode=@LineCode) OR
			EXISTS (Select 1 from Assy_TallyChartStatusData_History Where Barcode=@Barcode AND NotProcessedStatus != 'SCRAP' AND Result != 'PASS')
		BEGIN
			SELECT TOP 1 @_PartCode=A.PartNo,@_DateCode=A.Datecode,@_WorkCenterCode=B.WorkCenterCode,@_Status=A.Status
			FROM Assy_LineAssyStatus A INNER JOIN LineMst B
			ON A.LineCode=B.LineCode AND A.ProfitCenterCode=B.ProfitCenterCode			
			WHERE A.Barcode=@Barcode AND A.ProfitCenterCode=@ProfitCenterCode
			AND A.LineCode=@LineCode ORDER BY ScanTimestamp DESC

			--print '@_WorkCenterCode='+@_WorkCenterCode+' @_PartCode='+@_PartCode+' @_DateCode='+@_DateCode
			-- GET BOM VERSION

			SELECT @_BomVer=ver FROM Assy_ProductionOrderMst A INNER JOIN 
			(
				SELECT ProductionOrderNo FROM assy_runningpart_history WHERE Assy_PartNo=@_PartCode AND Datecode=@_DateCode AND LineCode=@LineCode AND Assy_Mode='Production'
				UNION
				SELECT ProductionOrderNo FROM assy_runningpart WHERE Assy_PartNo=@_PartCode AND Datecode=@_DateCode AND LineCode=@LineCode AND Assy_Mode='Production'
			) B
			ON A.OrderNo=B.ProductionOrderNo
			WHERE A.ProfitCenterCode=@ProfitCenterCode AND A.WorkCenterCode=@_WorkCenterCode AND A.PartNo=@_PartCode

			IF ISNULL(@_BomVer,'')=''
			BEGIN
				SET @ReturnValue='ERROR|Some Data Error is Found.BOM version not found. '
				SET @ReturnInt=0
				return
			END

			SELECT @_PartType=material_tp FROM PRODUCT_MASTER WHERE warehouse_cd=@ProfitCenterCode AND SEWS_PART_NO=@_PartCode AND ISNULL(STS_CD,0)=0
			
			

			IF @_PartType<>'STMC'
			BEGIN
				
				IF EXISTS(SELECT 1 FROM Assy_CouplingDetails WHERE CHILD_Barcode=@Barcode AND LineCode=@LineCode AND ProfitCentreCode=@ProfitCenterCode)
				BEGIN
					SET @_CouplingDone='COUPLED'
				END
			END
			
			 SET @ReturnValue='VALID|'+ISNULL(@_PartCode,'')+'~'+ISNULL(@_DateCode,'')+'~'+ISNULL(@_WorkCenterCode,'')+'~'+ISNULL(@_Status,'')
			 +'~'+ISNULL(@_BomVer,'')+'~'+ISNULL(@_PartType,'')+'~'+ISNULL(@_CouplingDone,'')

			SET @ReturnInt=1
		END		
		ELSE
		BEGIN
			SET @ReturnValue='INVALID'
			SET @ReturnInt=0
		END
	END
	IF @Mode='CHECK_DUPLICATE'
	BEGIN
		IF ISNULL(@Barcode,'')<>''
		BEGIN
		print 'CHECK_DUPLICATE'
			IF EXISTS(SELECT 1 FROM Assy_RejectionAccountingRework_Hdr WHERE Barcode=@Barcode AND ProfitCenterCode=@ProfitCenterCode)
			BEGIN
				SET @ReturnValue='Barcode is already marked in Rework.'
				SET @ReturnInt=0
			END
			ELSE
			BEGIN
				SET @ReturnValue='Barcode is VALID'
				SET @ReturnInt=1
			END

			RETURN
		END

		IF ISNULL(@PartNo,'')<>''
		BEGIN
			IF EXISTS(
					SELECT 1 FROM Assy_RejectionAccountingRework_Hdr a INNER JOIN Assy_RejectionAccountingRework_Dtl B
					ON A.RejectionID=B.RejectionID 
					WHERE A.PartNo=@PartNo AND ISNULL(B.isProcessed,0)=0 AND A.ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode)
			BEGIN
				SET @ReturnValue='Part Already Marked.'
				SET @ReturnInt=0
			END
			ELSE
			BEGIN
				SET @ReturnValue='PART is VALID'
				SET @ReturnInt=1
			END

			RETURN
		END


	END
	IF @Mode='VALIDATE_PART'
	BEGIN
		IF NOT EXISTS(SELECT SEWS_PART_NO AS PartNo,product_nm as PartDesc FROM PRODUCT_MASTER WHERE STS_CD=0 AND warehouse_cd=@ProfitCenterCode)
		BEGIN
			SET @ReturnValue='Part No is not valid.'
			SET @ReturnInt=0
		END

		IF @PartType='FG'
		BEGIN
			SELECT DISTINCT VER FROM BOM_MASTER WHERE FG_PART_NO=@PartNo AND STS_CD=0 AND WH_CODE=@ProfitCenterCode
			ORDER BY VER DESC
		END
		ELSE
		BEGIN
			SELECT DISTINCT VER FROM BOM_MASTER WHERE RM_PART_NO=@PartNo AND STS_CD=0 AND WH_CODE=@ProfitCenterCode
			ORDER BY VER DESC
		END

		SET @ReturnValue='Part No is valid.'
		SET @ReturnInt=1

	END
	IF @Mode='SAVE_PASS'
	BEGIN
		
		 BEGIN TRY
			  BEGIN TRAN	
				UPDATE Assy_LineAssyStatus set Status ='PS' , resulttimestamp=getdate() WHERE Barcode=@Barcode and LineCode=@LineCode
				UPDATE Assy_LineAssyStatus set Status ='PS' , resulttimestamp=getdate() WHERE Barcode=@Barcode and LineCode=@LineCode
				update Assy_TallyChartStatusData SET RESULT='PASS',Timestamp =GETDATE() WHERE Barcode=@Barcode and LineCode=@LineCode
				 
				 
				INSERT INTO Assy_RejectionAccountingPass_Dtl(ProfitCenterCode,ReworkCenterLineCode,LineCode,Barcode,Reason,USER_NAME,ENT_DT)
				VALUES(@ProfitCenterCode,@ReworkCenterLineCode,@LineCode,@Barcode,@Description,@UserCode,GETDATE())
				
				SET @ReturnValue='DATA SAVED'
				SET @ReturnInt=1

				COMMIT TRAN
			  END TRY
			BEGIN CATCH						
				SET @ReturnValue='ERROR'
				SET @ReturnInt=0

				ROLLBACK TRAN				
				THROW				
			END CATCH
	END
	IF @Mode='SAVE_REWORK'
		  BEGIN
		  BEGIN TRY
			  BEGIN TRAN			  
				  DECLARE @RECORD_COUNT INT
				  DECLARE @intFlagRework INT
				  DECLARE @ROW VARCHAR(1000)
				  DECLARE @LOCALPARTNO VARCHAR(30)
				  DECLARE @LOCALINSPECTEDDATE VARCHAR (12)
				   
			  	 --- SAVING REJECTION DATA	 
				  SET @RecordRefID=(SELECT ISNULL(MAX(RecordRefID),0)+1 FROM Assy_RejectionAccountingRework_Hdr WHERE ProfitCenterCode=@ProfitCenterCode)
				  IF ISNULL(@Data,'')<>''
				  BEGIN
							IF Object_id('tempdb..#temp_row_rework') IS NOT NULL
							  DROP TABLE #temp_row_rework

							SELECT col1,col2,col3,col4,col5
							INTO   #temp_row_rework
							FROM   [dbo].[Fn_grid_split_string](@Data, '~', '|')
									
							INSERT INTO Assy_RejectionAccountingRework_Hdr(RecordRefID,LineCode,Barcode,PartNo,PartType,DateCode,WorkCenterCode,BOMVersion,Qty,Reason,ReworkCenterLineCode,ProfitCenterCode,CreatedOn,CreatedBy)
							VALUES(@RecordRefID,@LineCode,@Barcode,@PartNo,@PartType,@DateCode,@WorkCenterCode,@BOMVersion,@Qty,@Description,@ReworkCenterLineCode,@ProfitCenterCode,GETDATE(),@UserCode)

							SELECT @RejectionID=SCOPE_IDENTITY()
							INSERT INTO Assy_RejectionAccountingRework_Dtl(RecordRefID,RejectionID,PartType,PartNo,PartQty,RejectedQty,ReworkQty,isProcessed,ProfitCenterCode,CreatedOn,CreatedBy)
							SELECT @RecordRefID,@RejectionID,col1,col2,col3,col4,col5,0,@ProfitCenterCode,GETDATE(),@UserCode FROM #temp_row_rework	
					END					
					IF ISNULL(@ReworkData,'')<>''
					BEGIN				
							IF Object_id('tempdb..#temp_row') IS NOT NULL
								DROP TABLE #temp_row

							SELECT col1,col2,col3,col4
							INTO   #temp_rowReowrk
							FROM   [dbo].[Fn_grid_split_string](@ReworkData, '~', '|')

												
							INSERT INTO Assy_RejectionAccountingRework_Hdr(RecordRefID,LineCode,Barcode,PartNo,PartType,DateCode,WorkCenterCode,BOMVersion,Qty,Reason,ReworkCenterLineCode,ProfitCenterCode,CreatedOn,CreatedBy)
							VALUES(@RecordRefID,@LineCode,@Barcode,@PartNo,@PartType,@DateCode,@WorkCenterCode,@BOMVersion,@Qty,@Description,@ReworkCenterLineCode,@ProfitCenterCode,GETDATE(),@UserCode)
								
							SELECT @RejectionID=SCOPE_IDENTITY()
							INSERT INTO Assy_RejectionAccountingRework_Dtl(RecordRefID,RejectionID,PartType,PartNo,PartQty,RejectedQty,ReworkQty,isProcessed,ProfitCenterCode,CreatedOn,CreatedBy)
							SELECT @RecordRefID,@RejectionID,col1,col2,col3,0,col4,0,@ProfitCenterCode,GETDATE(),@UserCode FROM #temp_rowReowrk		
					END

					UPDATE Assy_LineAssyStatus SET Status=CASE WHEN Status='PS' THEN 'RJ' ELSE Status END 
					WHERE Barcode=@Barcode AND ProfitCenterCode=@ProfitCenterCode AND LineCode=@LineCode

					--- CHANGING STATUS FAIL IN ASSEMBLY TABLES
					--IF ISNULL(@Barcode,'')<>''
					--BEGIN
						
