	IF @Mode='GET_REWORK_MARKED'
	BEGIN
		
		IF ISNULL(@isDateWise,0)=1
		BEGIN	
			SELECT A.PartNo,sum(A.RejectedQty) as RejectedQty,CONVERT(VARCHAR(12), A.CreatedOn, 13) AS CreatedOn,LineCode
			,STUFF((SELECT ', ' +  CAST(D.RecordRefID AS VARCHAR(10)) [text()]
			FROM Assy_RejectionAccountingRework_Dtl D 
			INNER JOIN Assy_RejectionAccountingRework_Hdr H
			on D.RejectionID=H.RejectionID
			where isnull(D.isProcessed,0)=0 AND D.ProfitCenterCode=@ProfitCenterCode
			AND ISNULL(D.RejectedQty,0)>0 --AND H.LineCode='P2'
			AND D.CreatedOn BETWEEN CONVERT(DATE, @DateFrom) AND DATEADD(day, 1,CONVERT(DATE, @DateTo))
			AND D.PartNo=A.PartNo AND CAST(D.CreatedOn AS date)=CAST(A.CreatedOn AS date)
			FOR XML PATH(''), TYPE)
			.value('.','NVARCHAR(MAX)'),1,2,' ') RefRejectionID

			FROM Assy_RejectionAccountingRework_Dtl A
			INNER JOIN Assy_RejectionAccountingRework_Hdr B
			on a.RejectionID=B.RejectionID
			where isnull(A.isProcessed,0)=0 AND A.ProfitCenterCode=@ProfitCenterCode
			AND ISNULL(A.RejectedQty,0)>0 --AND B.LineCode='P2'
			AND A.CreatedOn BETWEEN CONVERT(DATE, @DateFrom) AND DATEADD(day, 1,CONVERT(DATE, @DateTo))
			GROUP BY a.PartNo,CONVERT(VARCHAR(12), A.CreatedOn, 13),B.LineCode,CAST(A.CreatedOn AS date)
		END
		ELSE
		BEGIN
		
			SELECT A.PartNo,sum(A.RejectedQty) as RejectedQty,B.LineCode  
			,STUFF((SELECT ', ' +  CAST(D.RecordRefID AS VARCHAR(10)) [text()]
			FROM Assy_RejectionAccountingRework_Dtl D 
			INNER JOIN Assy_RejectionAccountingRework_Hdr H
			on D.RejectionID=H.RejectionID
			where isnull(D.isProcessed,0)=0 AND D.ProfitCenterCode=@ProfitCenterCode
			AND ISNULL(D.RejectedQty,0)>0 --AND H.LineCode='P2'
			AND D.CreatedOn BETWEEN CONVERT(DATE, @DateFrom) AND DATEADD(day, 1,CONVERT(DATE, @DateTo))
			AND D.PartNo=A.PartNo --AND CAST(D.CreatedOn AS date)=CAST(A.CreatedOn AS date)
			FOR XML PATH(''), TYPE)
			.value('.','NVARCHAR(MAX)'),1,2,' ') RefRejectionID

			FROM Assy_RejectionAccountingRework_Dtl A
			INNER JOIN Assy_RejectionAccountingRework_Hdr B
			on a.RejectionID=B.RejectionID
			where isnull(A.isProcessed,0)=0 AND A.ProfitCenterCode=@ProfitCenterCode
			AND ISNULL(A.RejectedQty,0)>0 --AND B.LineCode='P2'
			AND A.CreatedOn BETWEEN CONVERT(DATE, @DateFrom) AND DATEADD(day, 1,CONVERT(DATE, @DateTo))
			GROUP BY a.PartNo,B.LineCode
		END
	END
	IF @Mode='GET_Reason'
	BEGIN
	SELECT REASON_CD,REASON_DESC FROM REASON_MASTER
	WHERE REASON_TP=(SELECT PARAMETER_VALUE FROM PARAMETER_MST WHERE PARAMETER_C='ASSEMBLY' AND PARAMETER_C1='REJECTION_REASON' AND PARAMETER_C2='TYPE' AND wh_code=@ProfitCenterCode)
	END		  
	IF @Mode='GET_PENDING_ERP_POST'
	BEGIN	
		SELECT  a.ReasonID,A.ProfitCenterCode,A.PartNo,A.Qty,A.CodeGroup,A.QMCode,C.Description AS QMDesc,
		A.CauseCode,B.Description AS CauseDesc,A.RejectionCode,A.WorkCenterCode,A.Remarks,A.isProcessed
		,CONVERT(VARCHAR(10),A.CreatedOn,103) CreatedOn,D.RefRejectionID
		FROM Assy_RejectionAccountingReason_Dtl a  (NOLOCK)
		INNER JOIN ts_cause_mst B (NOLOCK)
		ON A.CauseCode=B.CauseCode
		INNER JOIN Assy_RejectionAccountingReason_hdr D (NOLOCK)
		on a.PartNo=d.PartNo and a.ReasonID=d.ReasonID and ISNULL(d.isProcessed,0)=0 
		INNER JOIN ts_codegroup_dtl C (NOLOCK)
		ON A.QMCode=C.Code AND C.CodeGroup=A.CodeGroup
		WHERE A.ProfitCenterCode=@ProfitCenterCode --AND D.LineCode=@LineCode
		AND A.CreatedOn BETWEEN CONVERT(DATE, @DateFrom) AND DATEADD(day, 1,CONVERT(DATE, @DateTo))
	END	
	IF @Mode='Undo_ReworkReject_Reason'
	BEGIN
		BEGIN TRAN
		BEGIN TRY
			DECLARE @RejectedQty INT,@ReportedBy VARCHAR(10),@ReportedDate DATETIME
			SELECT TOP 1 @RecordRefID=RecordRefID,@ReportedBy=CreatedBy,@ReportedDate=CreatedOn from Assy_RejectionAccountingRework_Hdr (NOLOCK)
			WHERE Barcode=@Barcode AND ProfitCenterCode=@ProfitCenterCode
			
			--INSERT INTO P(ID,MSG) SELECT @RecordRefID,'INSERT'+@Barcode

			-----------GET REWORK TABLE DETAILS
			SELECT D.PartNo,D.RejectedQty INTO #Rework_Dtl 
			FROM Assy_RejectionAccountingRework_Dtl D (NOLOCK) 
			WHERE D.RecordRefID=@RecordRefID AND D.RejectedQty>0 AND D.ProfitCenterCode=@ProfitCenterCode
			
			----------GET REASON TABLE DETAILS	
			SELECT D.ReasonID,D.PartNo,D.Qty,H.RefRejectionID INTO #Reason_Dtl 
			FROM Assy_RejectionAccountingReason_Hdr H (NOLOCK) 
			JOIN Assy_RejectionAccountingReason_Dtl D (NOLOCK)
			ON H.ReasonID=D.ReasonID AND H.ProfitCenterCode=D.ProfitCenterCode
			WHERE H.RefRejectionID LIKE '%'+CAST(@RecordRefID AS varchar)+'%'
			AND H.ProfitCenterCode=@ProfitCenterCode

			DECLARE @ReverseAction CURSOR 			
			SET @ReverseAction = CURSOR FAST_FORWARD FOR SELECT DISTINCT PartNo,RejectedQty FROM #Rework_Dtl 
			OPEN @ReverseAction
			FETCH NEXT FROM @ReverseAction INTO @PartNo,@RejectedQty
			WHILE @@FETCH_STATUS= 0
			BEGIN
				IF OBJECT_ID('TEMPDB..#TEMP') IS NOT NULL
				DROP TABLE #TEMP
				SELECT D.ReasonID,D.PartNo,D.Qty,D.RefRejectionID INTO #TEMP FROM #Reason_Dtl D 
				WHERE PartNo=@PartNo
				
				IF((SELECT COUNT(1) FROM #TEMP)>1)
				BEGIN					
					DECLARE @UpdateQtyAndRefID CURSOR 			
					SET @UpdateQtyAndRefID = CURSOR FAST_FORWARD FOR SELECT D.ReasonID,D.PartNo,D.Qty,D.RefRejectionID FROM #TEMP D 
					OPEN @UpdateQtyAndRefID
					FETCH NEXT FROM @UpdateQtyAndRefID INTO @ReasonID,@PartNo,@Qty,@RecordRefIDStr
					WHILE @@FETCH_STATUS= 0
					BEGIN
						EXEC Assy_Proc_UpdateQtyWithRefID @RecordRefID,@RecordRefIDStr,@PartNo,@ReasonID
					FETCH NEXT FROM @UpdateQtyAndRefID INTO @ReasonID,@PartNo,@Qty,@RecordRefIDStr
					END
					CLOSE @UpdateQtyAndRefID
					DEALLOCATE @UpdateQtyAndRefID
				END
				ELSE IF((SELECT COUNT(1) FROM #TEMP)=1)
				BEGIN 
					SELECT @ReasonID=ReasonID, @RecordRefIDStr=RefRejectionID FROM #TEMP
					EXEC Assy_Proc_UpdateQtyWithRefID @RecordRefID,@RecordRefIDStr,@PartNo,@ReasonID
					SELECT @ReasonID, @RecordRefIDStr
				END
			FETCH NEXT FROM @ReverseAction INTO  @PartNo,@RejectedQty
			END
			CLOSE @ReverseAction
			DEALLOCATE @ReverseAction

			
			DELETE FROM Assy_RejectionAccountingRework_Dtl  WHERE RecordRefID=@RecordRefID
			DELETE FROM Assy_RejectionAccountingRework_Hdr  WHERE RecordRefID=@RecordRefID
			UPDATE Assy_LineAssyStatus SET STATUS=CASE WHEN STATUS='RJ' THEN 'PS' ELSE STATUS END WHERE Barcode=@Barcode		

			INSERT INTO Assy_RejectionAccountingRevertDtl(Barcode,RecordRefID,ReportedBy,ReportedDate,UndoneBy,UndoneDate) VALUES
														 (@Barcode,@RecordRefID,@ReportedBy,@ReportedDate,@UserCode,GETDATE())
			 SET @ReturnValue='DATA SAVED'+'|'
			 SET @ReturnInt=1
			COMMIT TRAN
		END TRY
		BEGIN CATCH
			ROLLBACK TRAN
			--INSERT INTO P(ID,MSG) SELECT 2,ERROR_MESSAGE()
			SET @ReturnValue=(SELECT ERROR_MESSAGE())
		END CATCH
	END
	IF @Mode='SAVE_Reason'
	BEGIN
	BEGIN TRY
