				INSERT INTO Assy_RejectionAccountingReason_HDR(LineCode,ProfitCenterCode,PartNo,Qty,isProcessed,CreatedOn,CreatedBy,RefRejectionID)	
				SELECT @LineCode,@ProfitCenterCode,col1,col2,0,GETDATE(),@UserCode,@RefRejectionID FROM #temp_row1	
