				--	PartNo=@PartNo AND ISNULL(isProcessed,0)=0

				--	UPDATE Assy_RejectionAccountingReason_HDR SET Qty=Qty+ISNULL(@QTY,0),RefRejectionID=RefRejectionID+', '+@RefRejectionID   WHERE ReasonID=@ReasonID							
							
				--	INSERT INTO Assy_RejectionAccountingReason_Dtl(ReasonID,ProfitCenterCode,PartNo,Qty,CodeGroup,QMCode,CauseCode,RejectionCode,WorkCenterCode,Remarks,isProcessed,CreatedOn,CreatedBy)						
				--	SELECT @ReasonID,@ProfitCenterCode,col1,col2,col3,col4,col5,col6,col7,col8,0,GETDATE(),@UserCode FROM #temp_row1		
						
				--	update dtl set dtl.isProcessed=1 from  #temp_row1 t,Assy_RejectionAccountingRework_Dtl dtl where isProcessed=0 and t.col1=dtl.PartNo
				--	AND CAST(CreatedOn AS DATE)<=CAST(@FecthingDateTime AS DATE)					
				--END
				--ELSE
				--BEGIN
				--	INSERT INTO Assy_RejectionAccountingReason_HDR(LineCode,ProfitCenterCode,PartNo,Qty,isProcessed,CreatedOn,CreatedBy,RefRejectionID)	
				--	SELECT @LineCode,@ProfitCenterCode,col1,col2,0,GETDATE(),@UserCode,@RefRejectionID FROM #temp_row1	
				--	SELECT @ReasonID=SCOPE_IDENTITY()

						
				--	--INSERT OT DETAIL TABLE
				--	INSERT INTO Assy_RejectionAccountingReason_Dtl(ReasonID,ProfitCenterCode,PartNo,Qty,CodeGroup,QMCode,CauseCode,RejectionCode,WorkCenterCode,Remarks,isProcessed,CreatedOn,CreatedBy)						
				--	SELECT @ReasonID,@ProfitCenterCode,col1,col2,col3,col4,col5,col6,col7,col8,0,GETDATE(),@UserCode FROM #temp_row1		
						
				--	update dtl set dtl.isProcessed=1 from  #temp_row1 t,Assy_RejectionAccountingRework_Dtl dtl where isProcessed=0 and t.col1=dtl.PartNo
				--	AND CAST(CreatedOn AS DATE)<=CAST(@FecthingDateTime AS DATE)					
