			SET @ReturnValue='DATA SAVED'
			SET @ReturnInt=1

		COMMIT TRAN

		END TRY
	BEGIN CATCH						
				
		ROLLBACK TRAN
		THROW
				
	END CATCH
	END
	IF @Mode='POST'
	BEGIN
			
		IF(SELECT SNAPSHOT_ISOLATION_STATE FROM SYS.DATABASES WHERE NAME = DB_NAME()) = 1
		BEGIN
		SET TRANSACTION ISOLATION LEVEL SNAPSHOT
		END

	BEGIN TRY
		BEGIN TRAN
		DECLARE @ERP_TRAN_ID NUMERIC(15, 3)
        DECLARE @TR_TYPE_OUT INT
        DECLARE @P_MSG_OUT VARCHAR(100)
        DECLARE @ERROR_ID NVARCHAR(30)=''
		DECLARE @P_SAP_User NVARCHAR(10)
		DECLARE @RejDetailData VARCHAR(4000)
		
		SELECT DISTINCT Barcode INTO #tempBarCode FROM Assy_RejectionAccountingRework_Hdr 
		WHERE RecordRefID IN (SELECT DISTINCT data FROM Splitstring(@RecordRefIDStr, ',') WHERE DATA<>'') AND Barcode<>''
		------TRANSFER TO HISTORY TABLE
		
		DECLARE @TrnsferToHistory CURSOR 			
		SET @TrnsferToHistory = CURSOR FAST_FORWARD FOR SELECT DISTINCT Barcode FROM #tempBarCode where Barcode<>''
		OPEN @TrnsferToHistory
		FETCH NEXT FROM @TrnsferToHistory INTO @BarCode
		WHILE @@FETCH_STATUS= 0
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM Assy_LineAssyStatus_History WHERE Barcode=@Barcode)
			BEGIN
				INSERT INTO Assy_LineAssyStatus_History(ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,Status,FailCount,
				Datecode,PartNo,ScanTimestamp,ResultTimestamp,Active,UserID,IsTallyChartApproved,Transaction_Number,isConfirmed,
				Kanban_Id,ERP_Conf_Timestamp,His_ENT_DT,His_ENT_BY,IsReworkPart)
				SELECT ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,Status,FailCount,
				Datecode,PartNo,ScanTimestamp,ResultTimestamp,Active,UserID,IsTallyChartApproved,Transaction_Number,isConfirmed,
				Kanban_Id,ERP_Conf_Timestamp,GETDATE(),@UserCode,IsReworkPart
				FROM Assy_LineAssyStatus WHERE Barcode=@Barcode

				INSERT INTO  Assy_CouplingDetails_History(ProfitCentreCode,LineCode,STMC_PART_NO,CHILD_PART_NO,PART_TYPE,MACHINE_CODE,
							OPERATION_CODE,TORQUE_1,TORQUE_2,ENT_DT,ENT_BY,FG_Barcode,CHILD_Barcode,DateCode,His_ENT_DT,His_ENT_BY)
				SELECT ProfitCentreCode,LineCode,STMC_PART_NO,CHILD_PART_NO,PART_TYPE,MACHINE_CODE,
						OPERATION_CODE,TORQUE_1,TORQUE_2,ENT_DT,ENT_BY,FG_Barcode,CHILD_Barcode,DateCode,GETDATE(),@UserCode
						FROM Assy_CouplingDetails WHERE FG_Barcode=@Barcode

				INSERT INTO  Assy_TallyChartStatusData_History(ProfitCenterCode,LineCode,Datecode,MachineCode,Barcode,Result,NotProcessedStatus,Reason,Remarks,Assy_Auth,
				UserID,Timestamp,PartNo)
				SELECT ProfitCenterCode,LineCode,Datecode,MachineCode,Barcode,Result,NotProcessedStatus,Reason,Remarks,Assy_Auth,
				UserID,Timestamp,PartNo
				FROM Assy_TallyChartStatusData WHERE Barcode=@Barcode
			END
			IF EXISTS (SELECT 1 FROM Assy_LineAssyStatus WHERE Barcode=@Barcode)
			BEGIN				
				DELETE FROM Assy_LineAssyStatus			WHERE Barcode=@Barcode
				DELETE FROM Assy_couplingdetails		WHERE FG_Barcode=@Barcode
				DELETE FROM Assy_TallyChartStatusData WHERE Barcode=@Barcode
			END
		FETCH NEXT FROM @TrnsferToHistory INTO @BarCode
		END
		CLOSE @TrnsferToHistory
		DEALLOCATE @TrnsferToHistory


		-- GET THE SELECTED PT NO
		SELECT data	INTO #tempdatPart FROM Splitstring(@Data, '|')

		-- POSTING PART NO WISE
		DECLARE @_PartNo VARCHAR(30)
		DECLARE @_ReasonID BIGINT
		DECLARE @HeaderQty int

		
		CREATE TABLE #tmpPost
		(
			WorkCenterCode VARCHAR(10),
			Data VARCHAR(MAX),
			Qty INT,
			PartNo VARCHAR(30)

		)				

		DECLARE @CurPart CURSOR 
			
		SET @CurPart = CURSOR FAST_FORWARD FOR SELECT DISTINCT CAST(Data AS BIGINT) FROM #tempdatPart where CAST(Data AS BIGINT)<>0
		OPEN @CurPart
		FETCH NEXT FROM @CurPart INTO @_ReasonID
		WHILE @@FETCH_STATUS= 0
		BEGIN
			SET @RejDetailData=''
			-- GETTING HEADER DATA
				SELECT @_PartNo=PartNo,@HeaderQty=Qty FROM Assy_RejectionAccountingReason_hdr WHERE ReasonID=@_ReasonID AND ISNULL(isProcessed,0)=0
				-- GETTING DETAIL DATA
				DECLARE @_CodeGroup VARCHAR(10)
				DECLARE @_QMCode VARCHAR(10)
				DECLARE @_CauseCode VARCHAR(10)
				DECLARE @_Qty INT
				DECLARE @_Remarks VARCHAR(500)
				DECLARE @_WCCODE_temp VARCHAR(10)=''

				DELETE FROM #tmpPost
						
				-- CHECK THE QTY 
				IF @HeaderQty>(select SUM(ISNULL(SAP_STOCK,0)) from ERP_PSL_STOCK_DATA WHERE WH_CODE=@ProfitCenterCode AND STORAGE_LOC=@ProductionLocationCode AND PART_NO=@_PartNo)
				BEGIN
						
						SET @ReturnValue='Stock is not sufficient in SAP stock table for the Part no. '+@_PartNo
						SET @ReturnInt=0

						ROLLBACK TRAN
						RETURN
				END
				SET @HeaderQty=0
						
				DECLARE @CurDetail CURSOR 
				SET @CurDetail = CURSOR FAST_FORWARD FOR SELECT CodeGroup,QMCode,Qty,CauseCode,WorkCenterCode,Remarks from Assy_RejectionAccountingReason_Dtl 
				WHERE ReasonID=@_ReasonID AND ISNULL(isProcessed,0)=0 ORDER BY WorkCenterCode
				OPEN @CurDetail
				FETCH NEXT FROM @CurDetail INTO @_CodeGroup,@_QMCode,@_Qty,@_CauseCode,@_WorkCenterCode,@_Remarks
				WHILE @@FETCH_STATUS = 0
				BEGIN
							

						IF @_WCCODE_temp=@_WorkCenterCode
						BEGIN
							-- WC CODE IS SAME AS PREVIOUS DATA
							SET @HeaderQty=@HeaderQty+@_Qty
							SELECT @RejDetailData =ISNULL(@RejDetailData,'')+ @_CodeGroup + '|' + @_QMCode + '|'+ CONVERT(VARCHAR, @_Qty) + '|'+ @_CauseCode + '|' + REPLACE(@_Remarks,'.','')+ '~'
									
							IF EXISTS(SELECT 1 FROM #tmpPost WHERE WorkCenterCode=@_WorkCenterCode AND PartNo=@_PartNo)
							BEGIN
								UPDATE #tmpPost SET Data=Data+@RejDetailData,Qty=Qty+@HeaderQty WHERE WorkCenterCode=@_WorkCenterCode AND PartNo=@_PartNo
							END
							ELSE
							BEGIN
								INSERT INTO #tmpPost(WorkCenterCode,Data,Qty,PartNo)
								VALUES(@_WorkCenterCode,@RejDetailData,@HeaderQty,@_PartNo)
							END
						END
						ELSE IF @_WCCODE_temp=''
						BEGIN
							-- FIRST TIME 
							SET @_WCCODE_temp=@_WorkCenterCode
							SET @HeaderQty=@HeaderQty+@_Qty

							SELECT @RejDetailData =ISNULL(@RejDetailData,'')+ @_CodeGroup + '|' + @_QMCode + '|'+ CONVERT(VARCHAR, @_Qty) + '|'+ @_CauseCode + '|' + REPLACE(@_Remarks,'.','')+ '~'

							IF EXISTS(SELECT 1 FROM #tmpPost WHERE WorkCenterCode=@_WorkCenterCode AND PartNo=@_PartNo)
							BEGIN
								UPDATE #tmpPost SET Data=Data+@RejDetailData,Qty=Qty+@HeaderQty WHERE WorkCenterCode=@_WorkCenterCode AND PartNo=@_PartNo
							END
							ELSE
							BEGIN
								INSERT INTO #tmpPost(WorkCenterCode,Data,Qty,PartNo)
								VALUES(@_WorkCenterCode,@RejDetailData,@HeaderQty,@_PartNo)
							END

						END
						ELSE IF @_WCCODE_temp<>@_WorkCenterCode AND @_WCCODE_temp<>''
						BEGIN
							-- ANOTHER WC CODE STARTED
							IF EXISTS(SELECT 1 FROM #tmpPost WHERE WorkCenterCode=@_WorkCenterCode AND PartNo=@_PartNo)
							BEGIN
								UPDATE #tmpPost SET Data=Data+@RejDetailData,Qty=Qty+@HeaderQty WHERE WorkCenterCode=@_WorkCenterCode AND PartNo=@_PartNo
							END
							ELSE
							BEGIN
								INSERT INTO #tmpPost(WorkCenterCode,Data,Qty,PartNo)
								VALUES(@_WorkCenterCode,@RejDetailData,@HeaderQty,@_PartNo)
							END
							-- POST THE PREVIOUS DATA WITH DIFF WORK CENTER CODE AND CONCAT THIS NEW DATA
								
									
							SET @_WCCODE_temp=@_WorkCenterCode
							SET @HeaderQty=0

							SELECT @RejDetailData =@_CodeGroup + '|' + @_QMCode + '|'+ CONVERT(VARCHAR, @_Qty) + '|'+ @_CauseCode + '|' + REPLACE(@_Remarks,'.','')+ '~'
							SET @HeaderQty=@HeaderQty+@_Qty
						END
						FETCH NEXT FROM @CurDetail INTO @_CodeGroup,@_QMCode,@_Qty,@_CauseCode,@_WorkCenterCode,@_Remarks
				END
				CLOSE @CurDetail
				DEALLOCATE @CurDetail
			-- END GETTING DETAIL DATA
					

			-------------POSTING COLLECTED DATA -----------------------------------
				DECLARE @PartNo_Post VARCHAR(30)

				DECLARE @CurPost CURSOR 
				SET @CurPost = CURSOR FAST_FORWARD  FOR  SELECT WorkCenterCode,Qty,Data from #tmpPost					
				OPEN @CurPost
				FETCH NEXT FROM @CurPost INTO  @_WCCODE_temp,@HeaderQty,@RejDetailData
				WHILE @@FETCH_STATUS = 0
				BEGIN

						-------POSTING DATA
						SET @RejDetailData = Substring (@RejDetailData, 1,Len(@RejDetailData) - 1)

						EXEC Proc_get_dacs_tr_id   @WH_CODE = @ProfitCenterCode, @TR_TYPE = 'SCRAP_REJECTION',@MODE = 'INSERT',@ERP_TRAN_ID = @ERP_TRAN_ID out,@TR_TYPE_OUT = @TR_TYPE_OUT out
						SELECT @P_SAP_User = employee_id  FROM   tl_mf_sec_user_mst  WHERE  USER_CODE = @UserCode

					
								
													
						--EXEC Proc_call_erp
						--	@P_ERP_TS_TRAN_ID = @ERP_TRAN_ID,
						--	@P_PROGRAM_ID='REJECTION_REPORTING',
						--	@P_TS_TRAN_TYPE='SCRAP_REJECTION',
						--	@P_OPTION = 'LOG',
						--	@P_PLANT_CODE='BD01',
						--	@P_PART_NO=@_PartNo,
						--	@P_SRC_LOC=@StorageLocationCode,
						--	@P_Work_Center=@_WCCODE_temp,
						--	@P_QTY=@HeaderQty,
						--	@P_Prod_Date=@ProductionDate,
						--	@P_Header_Desc=@Description,
						--	@P_Code_BIL=@CodeBIL,
						--	@P_Lov_Code=@LoveCode,
						--	@P_ViewQty=@HeaderQty,
						--	@P_Rejection_Data=@RejDetailData,
						--	@P_WH_CODE=@ProfitCenterCode,
						--	@p_SHIFT_CD=@Shift,
						--	@P_SAP_User=@P_SAP_User 
								
								
								
								
								
								
						UPDATE Assy_RejectionAccountingReason_Dtl SET ERP_TS_TRAN_ID=@ERP_TRAN_ID WHERE ReasonID=@_ReasonID and WorkCenterCode=@_WCCODE_temp

						UPDATE Assy_RejectionAccountingReason_HDR 
						SET CodeBIL=@CodeBIL,LoveCode=@LoveCode,WorkCenterCode=@WorkCenterCode,StorageLocationCode=@StorageLocationCode,
						ProductionDate=@ProductionDate,Shift=@Shift,Description=@Description,isProcessed=1 WHERE ReasonID=@_ReasonID

						--------END OF POSTING DATA


				FETCH NEXT FROM @CurPost INTO  @_WCCODE_temp,@HeaderQty,@RejDetailData
				END
				CLOSE @CurPost
				DEALLOCATE @CurPost
			------------ END OF POSTING COLLECTED DATA -----------------------------
					 
						
				FETCH NEXT FROM @CurPart INTO @_ReasonID
		END
		CLOSE @CurPart
		DEALLOCATE @CurPart

						

			-----------------------------------
			SET @ReturnValue='DATA SAVED'
			SET @ReturnInt=1			

		COMMIT TRAN		
		END TRY
	BEGIN CATCH					
		ROLLBACK TRAN
		select ERROR_MESSAGE()
	END CATCH
	END
	IF @Mode='VALIDATE_GET_REWORK_DATA'
	BEGIN
		SELECT TOP 1 @RecordRefID=RecordRefID from Assy_RejectionAccountingRework_Hdr(NOLOCK)
		WHERE Barcode=@Barcode AND ProfitCenterCode=@ProfitCenterCode
		IF (ISNULL(@RecordRefID,0)<>0 AND NOT EXISTS (SELECT 1 FROM Assy_LineAssyStatus_History WHERE Barcode=@Barcode))
		BEGIN
			SELECT D.PartNo,P.product_nm,D.PartQty,D.RejectedQty,D.ReworkQty 
			FROM Assy_RejectionAccountingRework_Dtl D (NOLOCK) LEFT JOIN product_master P(NOLOCK) ON 
			D.PartNO=P.SEWS_PART_NO
			AND D.ProfitCenterCode=P.warehouse_cd
			WHERE D.RecordRefID=@RecordRefID AND D.ProfitCenterCode=@ProfitCenterCode
		END
		ELSE
		BEGIN
			SET @ReturnValue='INVALID'
			SET @ReturnInt=0
		END
	END
	IF @Mode='GET_REWORK_DATA_OF_PART'
	BEGIN
		SELECT D.PartNo,P.product_nm,D.PartQty,D.RejectedQty,D.ReworkQty 
		FROM Assy_RejectionAccountingRework_Dtl D (NOLOCK) LEFT JOIN product_master P(NOLOCK) ON 
		D.PartNO=P.SEWS_PART_NO
		AND D.ProfitCenterCode=P.warehouse_cd
		WHERE D.RecordRefID=@RecordRefID AND D.ProfitCenterCode=@ProfitCenterCode
	END	
	IF @Mode='GET_BARCODE_FOR_UNDO_REWORK_REJECT'
	BEGIN
		SELECT DISTINCT H.Barcode
		FROM Assy_RejectionAccountingRework_Hdr H (NOLOCK)
		WHERE CAST(H.CreatedOn AS DATE) BETWEEN CAST(@DateFrom AS DATE) AND CAST(@DateTo AS DATE)
		AND H.ProfitCenterCode=@ProfitCenterCode AND ISNULL(H.Barcode,'')!=''
		AND NOT EXISTS (SELECT TOP 1 1 FROM Assy_RejectionAccountingReason_Hdr RH
						WHERE RH.RefRejectionID LIKE '%'+CAST(H.RecordRefID AS VARCHAR)+'%' 
						AND ISNULL(RH.isProcessed,0)=1)	 
	END	
	IF @Mode='GET_PARTS_FOR_UNDO_REWORK_REJECT'
	BEGIN
		SELECT DISTINCT H.PartNo,H.RecordRefID,CONVERT(VARCHAR(10),H.CreatedOn,103) CreatedOn 
		FROM Assy_RejectionAccountingRework_Hdr H (NOLOCK)
		WHERE H.ProfitCenterCode=@ProfitCenterCode AND H.PartNo=@PartNo AND ISNULL(H.Barcode,'')='' 
		AND NOT EXISTS (SELECT TOP 1 1 FROM Assy_RejectionAccountingReason_Hdr RH
						WHERE RH.RefRejectionID LIKE '%'+CAST(H.RecordRefID AS VARCHAR)+'%' 
						AND ISNULL(RH.isProcessed,0)=1)	 
		ORDER  BY CONVERT(VARCHAR(10),H.CreatedOn,103)
	END
	IF @Mode='Get_PARTS_FOR_UNDO_REWORK_REJECT_BETWEEN_DATES'
	BEGIN
		SELECT DISTINCT H.PartNo,H.RecordRefID,CONVERT(VARCHAR(10),H.CreatedOn,103) CreatedOn 
		FROM Assy_RejectionAccountingRework_Hdr H (NOLOCK)
		WHERE H.ProfitCenterCode=@ProfitCenterCode 
		AND CAST(H.CreatedOn AS DATE) BETWEEN CAST(@DateFrom AS DATE) AND CAST(@DateTo AS DATE)	AND ISNULL(H.Barcode,'')='' 
		AND NOT EXISTS (SELECT TOP 1 1 FROM Assy_RejectionAccountingReason_Hdr RH
						WHERE RH.RefRejectionID LIKE '%'+CAST(H.RecordRefID AS VARCHAR)+'%' 
						AND ISNULL(RH.isProcessed,0)=1)	 
		ORDER  BY CONVERT(VARCHAR(10),H.CreatedOn,103)
	END
END


GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_RePrint_PartLabel]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Assy_Proc_RePrint_PartLabel] 
	@ProfitCode VARCHAR(10)= NULL, 
	@Operation VARCHAR(500) = NULL,
	@Part_No VARCHAR(10) = NULL,
	@LineCode VARCHAR(10) = NULL,
	@CurrLineCode VARCHAR(10) = NULL,
	@DateCode VARCHAR(10) = NULL,
	@CurrDateCode VARCHAR(10) = NULL,
	@Barcode VARCHAR(30) = NULL,
	@Remarks VARCHAR(500) = NULL,
	@Status VARCHAR(10) = NULL,
	@SerialNo VARCHAR(15) = NULL,
	@PrintType VARCHAR(10) = NULL,
	@Reprint bit = NULL,
	@Username VARCHAR(50) = NULL,
	@ReturnValue VARCHAR (2000) = NULL OUT,
	@ReturnInt INT = NULL OUT
AS
BEGIN
		-- =============================================
		-- Author:		<Rashid Siddiqui>
		-- Create Date:	<01 August 2015>
		
		-- Modify By:	<Rashid Siddiqui>
		-- Modify Date:	<20 Sep 2016>

		-- Description:	<Coupling Barcode also considering>
		
		-- EXEC Assy_Proc_RePrint_PartLabel @Operation = 'GET_LINECODE', @LineCode = 'M08', @ProfitCode = '0021'
		-- EXEC Assy_Proc_RePrint_PartLabel @Operation = 'GET_DATECODE', @LineCode = 'M03', @ProfitCode = '0021'
		-- EXEC Assy_Proc_RePrint_PartLabel @Operation = 'GET_PARTNUMBER', @LineCode = 'M03', @ProfitCode = '0021', @Datecode = '27Jb'
		-- EXEC Assy_Proc_RePrint_PartLabel @Operation = 'GET_REPRINT_BARCODE', @Part_No = '29066305', @ProfitCode = '0021', @Datecode = '39Vb', @LineCode = 'M03'
		-- =============================================
	BEGIN TRY
		DECLARE @ToDate INT,@FromDate INT, @DayRange INT = 0

		SELECT @DayRange = CONVERT(INT,ISNULL(PARAMETER_VALUE,0)) FROM PARAMETER_MST (NOLOCK) WHERE PARAMETER_C1 = 'MISSINGBARCODEREPRINT' AND PARAMETER_C2 = 'Date_Range' AND wh_code = '0021'
		
		IF (@DayRange = 0 OR @DayRange IS NULL)
		BEGIN
			SET @DayRange = 7
		END
		SET @ToDate = CONVERT(INT,CONVERT(VARCHAR(10), YEAR(GETDATE())) + RIGHT('00'+CONVERT(VARCHAR(10), MONTH(GETDATE())),2) + RIGHT('00'+CONVERT(VARCHAR(10), DAY(GETDATE())),2))
		SET @FromDate = CONVERT(INT,CONVERT(VARCHAR(10), YEAR(GETDATE()-@DayRange)) + RIGHT('00'+ CONVERT(VARCHAR(10), MONTH(GETDATE()-@DayRange)),2) + RIGHT('00'+CONVERT(VARCHAR(10), DAY(GETDATE()-@DayRange)),2))

		PRINT '@DayRange - ' + CONVERT(VARCHAR(10),@DayRange)
		PRINT '@ToDate - ' + CONVERT(VARCHAR,@ToDate)
		PRINT '@FromDate - ' + CONVERT(VARCHAR,@FromDate)
		

		Declare @tblBarcode As Table
		(
			Barcode Varchar(100)
		)

		--Start Add by Rashid Siddiqui 01/08/2015 for Reprint BarCode
		IF(@Operation = 'GET_LINECODE')
		BEGIN
			SELECT L.LineCode, L.LineName FROM LineMst L (NOLOCK)
				WHERE L.LineCode IN 
				(
					SELECT DISTINCT A.LineCode FROM Assy_RunningPart A (NOLOCK)
						WHERE
							LEFT(LineCode,1) = LEFT(@LineCode,1)
							AND CONVERT(INT,CONVERT(VARCHAR(10), YEAR(CreatedDate)) + RIGHT('00'+CONVERT(VARCHAR(10), MONTH(CreatedDate)),2) + RIGHT('00'+CONVERT(VARCHAR(10), DAY(CreatedDate)),2))
							BETWEEN @FromDate AND @ToDate
					UNION
					SELECT DISTINCT B.LineCode FROM Assy_RunningPart_History B (NOLOCK)
						WHERE
							LEFT(LineCode,1) = LEFT(@LineCode,1)
							AND CONVERT(INT,CONVERT(VARCHAR(10), YEAR(CreatedDate)) + RIGHT('00'+CONVERT(VARCHAR(10), MONTH(CreatedDate)),2) + RIGHT('00'+CONVERT(VARCHAR(10), DAY(CreatedDate)),2))
							BETWEEN @FromDate AND @ToDate
				) AND ProfitCenterCode = @ProfitCode AND LineCode = @LineCode
			Order By 2
		END
		
		ELSE IF(@Operation = 'GET_DATECODE')
		BEGIN
			--INSERT INTO @tblBarcode
			--SELECT Distinct PartBarcode FROM SkidBarcodeDetail (NOLOCK)
			--	WHERE CHARINDEX (@LineCode,PartBarcode) <> 0 AND WH_CODE = @ProfitCode
			
			--INSERT INTO @tblBarcode
			--SELECT Distinct CHILD_Barcode Barcode FROM Assy_Couplingdetails WITH (NOLOCK)
			--	WHERE CHARINDEX (@LineCode,CHILD_Barcode) <> 0 AND ProfitcentreCode = @ProfitCode

			SELECT DISTINCT L.Datecode FROM Assy_LineAssyStatus L (NOLOCK)
							WHERE L.Barcode NOT IN 
							(
								SELECT Distinct PartBarcode FROM SkidBarcodeDetail (NOLOCK)
									WHERE WH_CODE = @ProfitCode AND CHARINDEX (@LineCode,PartBarcode) <> 0
							) AND L.LineCode = @LineCode AND L.ProfitCenterCode = @ProfitCode
							AND CONVERT(INT,CONVERT(VARCHAR(10), YEAR(L.ScanTimestamp)) + RIGHT('00'+CONVERT(VARCHAR(10), MONTH(L.ScanTimestamp)),2) + RIGHT('00'+CONVERT(VARCHAR(10), DAY(L.ScanTimestamp)),2))
						BETWEEN @FromDate AND @ToDate
		END

		ELSE IF(@Operation = 'GET_PARTNUMBER')
		BEGIN
			INSERT INTO @tblBarcode
			SELECT Distinct PartBarcode FROM SkidBarcodeDetail (NOLOCK)
				WHERE CHARINDEX (@Datecode,PartBarcode) <> 0 AND CHARINDEX (@LineCode,PartBarcode) <> 0 AND WH_CODE = @ProfitCode
			
			INSERT INTO @tblBarcode
			SELECT Distinct CHILD_Barcode Barcode FROM Assy_Couplingdetails WITH (NOLOCK)
				WHERE CHARINDEX (@Datecode,CHILD_Barcode) <> 0 AND CHARINDEX (@LineCode,CHILD_Barcode) <> 0 AND ProfitcentreCode = @ProfitCode

			SELECT DISTINCT L.PartNo FROM Assy_LineAssyStatus L (NOLOCK)
							WHERE L.Barcode NOT IN 
							(
								SELECT Distinct Barcode FROM @tblBarcode
							) AND Datecode = @DateCode AND L.LineCode = @LineCode AND ISNULL(L.PartNo,'')  != '' AND L.ProfitCenterCode = @ProfitCode
							AND CONVERT(INT,CONVERT(VARCHAR(10), YEAR(L.ScanTimestamp)) + RIGHT('00'+CONVERT(VARCHAR(10), MONTH(L.ScanTimestamp)),2) + RIGHT('00'+CONVERT(VARCHAR(10), DAY(L.ScanTimestamp)),2))
						BETWEEN @FromDate AND @ToDate
						Order by 1
		END

		ELSE IF(@Operation = 'GET_REPRINT_BARCODE')
		BEGIN
			INSERT INTO @tblBarcode
			SELECT Distinct PartBarcode FROM SkidBarcodeDetail (NOLOCK)
				WHERE CHARINDEX (@Datecode,PartBarcode) <> 0 AND CHARINDEX (@Part_No,PartBarcode) <> 0 AND CHARINDEX (@LineCode,PartBarcode) <> 0 AND WH_CODE = @ProfitCode
			
			INSERT INTO @tblBarcode
			SELECT Distinct CHILD_Barcode Barcode FROM Assy_Couplingdetails WITH (NOLOCK)
				WHERE CHARINDEX (@Datecode,CHILD_Barcode) <> 0 AND CHARINDEX (@Part_No,CHILD_Barcode) <> 0 AND CHARINDEX (@LineCode,CHILD_Barcode) <> 0 AND ProfitcentreCode = @ProfitCode

			Declare @LineType VARCHAR(20) = '',	@Day INT = 0,@Month INT = 0,@Year INT = 0
			SELECT @LineType = dbo.Assy_FN_Get_LineTypeName_From_LineCode(@ProfitCode,@LineCode)

			--IF LEN(@LineCode)  = 3
			IF (@LineType = 'TMC')
			BEGIN
				SELECT Distinct L.Barcode FROM Assy_LineAssyStatus L (NOLOCK)
					WHERE L.Barcode NOT IN 
					(
						SELECT Distinct Barcode FROM @tblBarcode
					) AND L.DateCode = @Datecode AND L.PartNo = @Part_No AND L.ProfitcenterCode = @ProfitCode AND RIGHT(L.Barcode,3) = @LineCode
				Order By 1
			END
			--ELSE IF LEN(@LineCode)  = 2
			ELSE IF (@LineType = 'STMC')
			BEGIN
				Declare @CheckCoupleBarcode VARCHAR(60) = '', @CheckCustomerPartNo VARCHAR(60) = '', @GroupCode VARCHAR(60) = '',
						@Filter1 VARCHAR(60) = '', @Filter2 VARCHAR(60) = '',@Filter3 VARCHAR(10) = '',@Filter4 VARCHAR(100) = ''
				
				SELECT Top 1 @CheckCoupleBarcode = L.Barcode, @Day = DAY(MIN(L.ScanTimestamp)) , @Month = MONTH(MIN(L.ScanTimestamp)) , @Year = RIGHT(YEAR(MIN(L.ScanTimestamp)),2)
					FROM Assy_LineAssyStatus L (NOLOCK)
						WHERE L.DateCode = @Datecode AND L.PartNo = @Part_No AND L.ProfitcenterCode = @ProfitCode AND L.LineCode = @LineCode
							Group By L.Barcode
							--Order By ResultTimestamp Desc
				
				SET @Filter3 = RIGHT('0' + CONVERT(VARCHAR(2),@Day),2) + RIGHT('0' + CONVERT(VARCHAR(2),@Month),2) + CONVERT(VARCHAR(2),@Year)

				IF CHARINDEX(':',@CheckCoupleBarcode) <> 0 AND ISNULL(@CheckCoupleBarcode,'') <> ''
				BEGIN

					SELECT Top 1 @CheckCustomerPartNo = CustomerPartNo, @GroupCode = GroupCode FROM Assy_PRN_CustomerGroupMaster WITH (NOLOCK)
						WHERE PartNo = @Part_No
				
					SELECT Top 1 @Filter2 = LabelDataValue FROM Assy_Coupling_LabelInfo_Mst WITH (NOLOCK)
						WHERE LabelDataName = 'Plant_Code' AND PartNo = @Part_No AND CustomerPartNo = @CheckCustomerPartNo AND ProfitCenterCode = @ProfitCode

					IF (@GroupCode = 'GC_MAHINDRA')
					BEGIN
						SELECT Top 1 @Filter1 = LabelDataValue FROM Assy_Coupling_LabelInfo_Mst WITH (NOLOCK)
							WHERE LabelDataName = 'Part_Identification_Code' AND PartNo = @Part_No AND CustomerPartNo = @CheckCustomerPartNo AND ProfitCenterCode = @ProfitCode
					END
					ELSE IF (@GroupCode = 'GC_NON_MAHINDRA')
					BEGIN
						SELECT Top 1 @Filter1 = LabelDataValue FROM Assy_Coupling_LabelInfo_Mst WITH (NOLOCK)
							WHERE LabelDataName = 'Part_Type' AND PartNo = @Part_No AND CustomerPartNo = @CheckCustomerPartNo AND ProfitCenterCode = @ProfitCode
					END

					SET @Filter4 = LTRIM(RTRIM(@Filter1)) + ':' + LTRIM(RTRIM(@CheckCustomerPartNo)) + ':' + LTRIM(RTRIM(@Filter2)) + ':' + LTRIM(RTRIM(@Filter3))

					SELECT Distinct L.Barcode FROM Assy_LineAssyStatus L (NOLOCK)
						WHERE L.DateCode = @Datecode AND L.PartNo = @Part_No AND L.ProfitcenterCode = @ProfitCode AND L.LineCode = @LineCode
						AND CHARINDEX(':',L.Barcode) <> 0 AND L.Barcode NOT IN 
						(
							SELECT Distinct PartBarcode FROM SkidBarcodeDetail (NOLOCK)
								WHERE CHARINDEX(':',PartBarcode) <> 0 AND CHARINDEX (@Filter4,PartBarcode) <> 0
									AND ISNULL(PartBarcode,'') <> '' AND WH_CODE = @ProfitCode
									--AND CHARINDEX (@Filter1,PartBarcode) <> 0
									--AND CHARINDEX (@Filter2,PartBarcode) <> 0
									--AND CHARINDEX (@Filter3,PartBarcode) <> 0
						)
					Order By 1
				END
				ELSE
				BEGIN
					SELECT Distinct L.Barcode FROM Assy_LineAssyStatus L (NOLOCK)
						WHERE L.Barcode NOT IN 
						(
							SELECT Distinct Barcode FROM @tblBarcode
						) AND L.DateCode = @Datecode AND L.PartNo = @Part_No AND L.ProfitcenterCode = @ProfitCode AND RIGHT(L.Barcode,2) = @LineCode
					Order By 1
				END
			END
		END

		ELSE IF(@Operation = 'INSERT_REPRINT_BARCODE')
		BEGIN
			BEGIN
				INSERT INTO [Assy_LineAssyManualRePrint] ([ProfitCenterCode],[LineCode],[Datecode],[Barcode],[PartNo],[Remarks],[Status],Serialno,CurrentLineCode,CurrentDateCode,Reprint, CreatedBy, CreatedOn, ModifiedBy, ModifiedOn , PrintType)
								VALUES(@ProfitCode,@LineCode,@DateCode, @Barcode,@Part_No,@Remarks,@Status,@SerialNo, @CurrLineCode,@CurrDateCode, @Reprint, @Username, GETDATE(), @Username, GETDATE(), @PrintType)
			END
		END

		ELSE IF(@Operation = 'GET_SERIALNO')
		BEGIN
			--Modified By Rashid Siddiqui on 19th July 2016 (8 Character Seq problem when barcode is produced in Rework mode)
			Declare @Barcode_DateCode CHAR(4) = '', @8CharSeq CHAR(8) = ''
			SELECT TOP 1 @Barcode_DateCode = SUBSTRING(Barcode,CHARINDEX(PartNo,Barcode) + LEN(PartNo),4) FROM Assy_LineAssyStatus A (NOLOCK)
						WHERE LineCode = @LineCode AND DateCode = @DateCode AND PartNo = @Part_No AND Barcode = @Barcode AND ProfitCenterCode = @ProfitCode

			SELECT TOP 1 @8CharSeq = SUBSTRING(Barcode,CHARINDEX(Datecode,Barcode) + LEN(Datecode),8) FROM Assy_LineAssyStatus A (NOLOCK)
					WHERE LineCode = @LineCode AND DateCode = @DateCode AND PartNo = @Part_No AND Barcode = @Barcode AND ProfitCenterCode = @ProfitCode

			IF (@DateCode = @Barcode_DateCode)
			BEGIN
				SELECT @8CharSeq
			END
			ELSE
			BEGIN
				IF LEN(@Part_No) = 8
				BEGIN
					SELECT TOP 1 SUBSTRING(Barcode,CHARINDEX(SUBSTRING(Barcode,CHARINDEX(PartNo,Barcode) + LEN(PartNo),4),Barcode) + LEN(SUBSTRING(Barcode,CHARINDEX(PartNo,Barcode) + LEN(PartNo),4)),8) FROM Assy_LineAssyStatus A (NOLOCK)
						WHERE LineCode = @LineCode AND DateCode = @DateCode AND PartNo = @Part_No AND Barcode = @Barcode AND ProfitCenterCode = @ProfitCode
				END
				ELSE
				BEGIN
					SELECT @8CharSeq
				END
			END
		END
		
		ELSE IF(@Operation = 'GET_SERIALNO_RUNNINGPART')
		BEGIN
			SELECT TOP 1 SUBSTRING(Barcode,CHARINDEX(Datecode,Barcode) + LEN(Datecode),8) FROM Assy_LineAssyStatus_Running A (NOLOCK)
				WHERE LineCode = @LineCode AND DateCode = @DateCode AND PartNo = @Part_No AND Barcode = @Barcode AND ProfitCenterCode = @ProfitCode
		END

		ELSE IF(@Operation = 'GET_PRINTCOUNT')
		BEGIN
			SELECT  COUNT(Barcode) FROM Assy_LineAssyManualRePrint (NOLOCK)
				WHERE LineCode = @LineCode --AND DateCode = @DateCode commented by sachin 20170816
				AND PartNo = @Part_No AND Barcode = @Barcode AND ProfitCenterCode = @ProfitCode
				AND PrintType = @PrintType
		END

		ELSE IF(@Operation = 'GET_RUNNING_BARCODE_REPRINT')
		BEGIN
			SELECT DISTINCT L.MachineCode, M.MachineName FROM Assy_LineAssyStatus_Running L WITH (NOLOCK)
				INNER JOIN MachineMst M WITH (NOLOCK)
					ON M.MachineCode = L.MachineCode
						WHERE L.PartNo = (SELECT Top 1 Case ISNULL(PartType,'') WHEN 'STMC' THEN Assy_PartNo ELSE @Part_No END FROM Assy_RunningPart (NOLOCK)
							WHERE ProfitcenterCode = @ProfitCode AND LineCode = @LineCode) AND L.ProfitcenterCode = @ProfitCode AND L.LineCode = @LineCode AND Datecode != 'PKYK'
							Order By 1

			SELECT Distinct L.Barcode, L.MachineCode FROM Assy_LineAssyStatus_Running L (NOLOCK)
				WHERE L.PartNo = (SELECT Top 1 Case ISNULL(PartType,'') WHEN 'STMC' THEN Assy_PartNo ELSE @Part_No END FROM Assy_RunningPart (NOLOCK)
					WHERE ProfitcenterCode = @ProfitCode AND LineCode = @LineCode) AND L.ProfitcenterCode = @ProfitCode AND L.LineCode = @LineCode AND Datecode != 'PKYK'
						Order By 2,1
		END
		--End Add by Rashid Siddiqui 01/08/2015 for Reprint BarCode
		-- Added By Sachin 20170817
		ELSE IF(@Operation = 'GET_LABEL_ZPL')
		BEGIN
					Declare @ReprintBarcodeFormatOpt varchar(20)
					Declare @SERIAL_PREFIX1 varchar(1)
					Declare @SERIAL_PREFIX2 varchar(1)
					Declare @SEQENCE_NUMBER varchar(4)
					Declare @DateCodeLbl varchar(4)
					Declare @ZPL varchar(2000)
					
					select @ReprintBarcodeFormatOpt=KeyValue from RoutingConfigDetails(nolock) 
					where PROFITCENTERCODE=@ProfitCode AND LINECODE=@LineCode AND 
					PartNumber=@Part_No and STS_CD=0 and KeyType='ReprintBarcodeFormat'

					IF(ISNULL(@REPRINTBARCODEFORMATOPT,'')='')
					BEGIN
						SELECT 'NOK' , 'REPRINT OPTION NOT FOUND'
						Return
					END
					

					if(@ReprintBarcodeFormatOpt='Option_1')
					begin
						
						
						select @ZPL=ISNULL(keyvalue,'') from RoutingConfigDetails(nolock) 
						where PROFITCENTERCODE=@ProfitCode AND LINECODE=@LineCode 
						AND PartNumber=@Part_No and STS_CD=0
						and KeyType='ReprintBarcodeLbl'
						
						select @SERIAL_PREFIX1 = keyvalue from RoutingConfigDetails(nolock) where ProfitCenterCode=@ProfitCode
						and LineCode=@LineCode and  STS_CD=0 and KeyType='BarcodePrefix1'
		
						select @SERIAL_PREFIX2 = keyvalue from RoutingConfigDetails(nolock) where ProfitCenterCode=@ProfitCode
						and LineCode=@LineCode and STS_CD=0 and KeyType='BarcodePrefix2'

						
						IF(ISNULL(@ZPL,'')='')
						BEGIN
							SELECT 'NOK' , 'REPRINT ZPL NOT FOUND'
							Return
						END

						--set @SERIAL_PREFIX1= subString(@Barcode,1,1)
						--set @SERIAL_PREFIX2= subString(@Barcode,2,1)
						set @SEQENCE_NUMBER= subString(@Barcode,1,3)
						set @DateCodeLbl      =subString(@Barcode,4,4)

						SET @ZPL = REPLACE(@ZPL,'[SERIAL_PREFIX1]',@SERIAL_PREFIX1)
						SET @ZPL = REPLACE(@ZPL,'[SERIAL_PREFIX2]',@SERIAL_PREFIX2)
						SET @ZPL = REPLACE(@ZPL,'[SEQENCE_NUMBER]',@SEQENCE_NUMBER)
						SET @ZPL = REPLACE(@ZPL,'[TMP_DATE_CODE1]',SUBSTRING(@DateCodeLbl,1,1))
						SET @ZPL = REPLACE(@ZPL,'[TMP_DATE_CODE2]',SUBSTRING(@DateCodeLbl,2,3))
						SET @ZPL = REPLACE(@ZPL,'[PRINT_CONTENT]',ISNULL(@SERIAL_PREFIX1,'')+ISNULL(@SERIAL_PREFIX2,'')+@Barcode)

						SELECT 'OK' , @ZPL

					end

		END
		-- Ended By Sachin 20170817
	--TRY BLOCK ENDS
	END TRY 
	BEGIN CATCH  
	--CATCH BLOCK BEGINS
		SET @ReturnValue =	CAST(ERROR_NUMBER() as VARCHAR(5)) + '|' + 
		CAST(ERROR_SEVERITY()as VARCHAR(5)) + '|' + 
		CAST(ERROR_STATE() as VARCHAR(5)) + '|' + 
		CAST(ERROR_PROCEDURE() as VARCHAR(200)) + '|' + 
		CAST(ERROR_LINE() as VARCHAR(5)) + '|' + 
		CAST(ERROR_MESSAGE() as VARCHAR(1500))
		RAISERROR(@ReturnValue,16,1)
		SET @ReturnInt = 2
	--CATCH BLOCK ENDS 
	END CATCH
END




GO
/****** Object:  StoredProcedure [dbo].[Assy_PROC_ReprintBarcode]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[Assy_PROC_ReprintBarcode]
(
@CONDITION VARCHAR(100)=NULL,
@DATE varchar(20) = NULL,
@CALIPERDATECODE varchar(4) = NULL,
@CALIPERSERIALNO smallint = 0,
@ProfitCenterCode nvarchar(4),
@LineCode varchar(10),
@PARTNO VARCHAR(20) = NULL,
@ReturnValue VARCHAR (2000) = NULL OUT,
@ReturnInt INT = NULL OUT,
@Barcode VARCHAR (60) = NULL OUT,
@UserID VARCHAR(20) = NULL,
@PrintedTimestamp DATETIME = NULL
)
AS
BEGIN 
		-- =============================================
		-- Author:	<Mohit Prabhakar>
		-- Create date:	<30 June 2016>
		-- Description:	<The procedure is used to get the barcode for Reprint Barcode Screen.>
		-- EXEC [Assy_PROC_ReprintBarcode]		 @CONDITION='GETBARCODE', @PARTNO = ''
		-- =============================================

		-- =============================================
		-- Modified By:	<Ravishankar Mishra>
		-- Modified date:	<28 July 2016>
		-- Description:	Added profitcentercode and linecode in all conditions		
		-- =============================================

		SET NOCOUNT ON	
		set dateformat dmy
	
		IF(@CONDITION = 'GETPARTNO')
			BEGIN
								
				if(ISNULL(@DATE,'') != '' and ISNULL(@CALIPERDATECODE,'') != '' 
				and ISNULL(@CALIPERSERIALNO,0) != 0)
				begin
						SELECT DISTINCT PartNo
						FROM Assy_FinalViewing_RFID_Barcode_Mapping	with(nolock)
						WHERE  ProfitCenterCode=@ProfitCenterCode and linecode=@linecode	
						and (CONVERT(VARCHAR(10),PrintedTimestamp,105)) = @DATE	
						AND CaliperDatecode=@CALIPERDATECODE AND 
						CaliperSerNo=@CALIPERSERIALNO
				end
				else 
				if(ISNULL(@DATE,'') != '' and ISNULL(@CALIPERDATECODE,'') != '' )
				begin
						SELECT DISTINCT PartNo
						FROM Assy_FinalViewing_RFID_Barcode_Mapping	with(nolock)
						WHERE  ProfitCenterCode=@ProfitCenterCode and linecode=@linecode	
						and (CONVERT(VARCHAR(10),PrintedTimestamp,105)) = @DATE	
						AND CaliperDatecode=@CALIPERDATECODE
				end				
				else
				if(ISNULL(@DATE,'') != '' 	and ISNULL(@CALIPERSERIALNO,0) != 0)
				begin
						SELECT DISTINCT PartNo
						FROM Assy_FinalViewing_RFID_Barcode_Mapping	with(nolock)
						WHERE  ProfitCenterCode=@ProfitCenterCode and linecode=@linecode	
						and (CONVERT(VARCHAR(10),PrintedTimestamp,105)) = @DATE	
						AND CaliperSerNo=@CALIPERSERIALNO 
				end
				else
				if(ISNULL(@CALIPERDATECODE,'') != '' 	and ISNULL(@CALIPERSERIALNO,0) != 0)
				begin
						SELECT DISTINCT PartNo
						FROM Assy_FinalViewing_RFID_Barcode_Mapping	with(nolock)
						WHERE  ProfitCenterCode=@ProfitCenterCode and linecode=@linecode	
					    AND CaliperDatecode=@CALIPERDATECODE
						AND CaliperSerNo=@CALIPERSERIALNO 
				end
				else
				if(ISNULL(@CALIPERSERIALNO,0) != 0)
				begin
						SELECT DISTINCT PartNo
						FROM Assy_FinalViewing_RFID_Barcode_Mapping	with(nolock)
						WHERE  ProfitCenterCode=@ProfitCenterCode and linecode=@linecode						    
						AND CaliperSerNo=@CALIPERSERIALNO 
				end
				else
				if(ISNULL(@CALIPERDATECODE,0) <> '')
				begin
						SELECT DISTINCT PartNo
						FROM Assy_FinalViewing_RFID_Barcode_Mapping	with(nolock)
						WHERE  ProfitCenterCode=@ProfitCenterCode and linecode=@linecode						    
						AND CaliperDatecode=@CALIPERDATECODE
				end
				else 
				if(ISNULL(@DATE,'') != '')
				begin
						SELECT DISTINCT PartNo
						FROM Assy_FinalViewing_RFID_Barcode_Mapping	with(nolock)
						WHERE  ProfitCenterCode=@ProfitCenterCode and linecode=@linecode	
						and (CONVERT(VARCHAR(10),PrintedTimestamp,105)) = @DATE	
						
				end
				SET @ReturnValue = 'SUCCESS'
				SET @ReturnInt = 1
				return
				END
				
		ELSE IF(@CONDITION = 'GETBARCODE')
		BEGIN
			
			if(ISNULL(@DATE,'') != '' and ISNULL(@CALIPERDATECODE,'') != '' 
				and ISNULL(@CALIPERSERIALNO,0) != 0)
				begin
						SELECT DISTINCT Barcode
						FROM Assy_FinalViewing_RFID_Barcode_Mapping	with(nolock)
						WHERE  ProfitCenterCode=@ProfitCenterCode and linecode=@linecode	
						and (CONVERT(VARCHAR(10),PrintedTimestamp,105)) = @DATE	
						AND CaliperDatecode=@CALIPERDATECODE AND 
						CaliperSerNo=@CALIPERSERIALNO
						and PartNo=@PARTNO
				end
				else 
				if(ISNULL(@DATE,'') != '' and ISNULL(@CALIPERDATECODE,'') != '' )
				begin
						SELECT DISTINCT Barcode
						FROM Assy_FinalViewing_RFID_Barcode_Mapping	with(nolock)
						WHERE  ProfitCenterCode=@ProfitCenterCode and linecode=@linecode	
						and (CONVERT(VARCHAR(10),PrintedTimestamp,105)) = @DATE	
						AND CaliperDatecode=@CALIPERDATECODE
						and PartNo=@PARTNO
				end				
				else
				if(ISNULL(@DATE,'') != '' 	and ISNULL(@CALIPERSERIALNO,0) != 0)
				begin
						SELECT DISTINCT Barcode
						FROM Assy_FinalViewing_RFID_Barcode_Mapping	with(nolock)
						WHERE  ProfitCenterCode=@ProfitCenterCode and linecode=@linecode	
						and (CONVERT(VARCHAR(10),PrintedTimestamp,105)) = @DATE	
						AND CaliperSerNo=@CALIPERSERIALNO 
						and PartNo=@PARTNO
				end
				else
				if(ISNULL(@CALIPERDATECODE,'') != '' 	and ISNULL(@CALIPERSERIALNO,0) != 0)
				begin
						SELECT DISTINCT Barcode
						FROM Assy_FinalViewing_RFID_Barcode_Mapping	with(nolock)
						WHERE  ProfitCenterCode=@ProfitCenterCode and linecode=@linecode	
					    AND CaliperDatecode=@CALIPERDATECODE
						AND CaliperSerNo=@CALIPERSERIALNO 
						and PartNo=@PARTNO
				end
				else
				if(ISNULL(@CALIPERSERIALNO,0) != 0)
				begin
						SELECT DISTINCT Barcode
						FROM Assy_FinalViewing_RFID_Barcode_Mapping	with(nolock)
						WHERE  ProfitCenterCode=@ProfitCenterCode and linecode=@linecode						    
						AND CaliperSerNo=@CALIPERSERIALNO and PartNo=@PARTNO
				end
				else
				if(ISNULL(@CALIPERDATECODE,0) <> '')
				begin
						SELECT DISTINCT Barcode
						FROM Assy_FinalViewing_RFID_Barcode_Mapping	with(nolock)
						WHERE  ProfitCenterCode=@ProfitCenterCode and linecode=@linecode						    
						AND CaliperDatecode=@CALIPERDATECODE and PartNo=@PARTNO
				end
				else 
				if(ISNULL(@DATE,'') != '')
				begin
						SELECT DISTINCT Barcode
						FROM Assy_FinalViewing_RFID_Barcode_Mapping	with(nolock)
						WHERE  ProfitCenterCode=@ProfitCenterCode and linecode=@linecode	
						and (CONVERT(VARCHAR(10),PrintedTimestamp,105)) = @DATE	
						and PartNo=@PARTNO
				end

			SET @ReturnValue = 'SUCCESS'
			SET @ReturnInt = 1		
		END

		ELSE IF(@Condition = 'INSERT_REPRINT_BARCODE_DETAIL')
		BEGIN
			BEGIN
					INSERT INTO [Assy_FinalViewing_RFID_Barcode_RePrint] (ProfitCenterCode,linecode,Barcode,UserID,PrintedTimestamp)
									VALUES(@ProfitCenterCode,@linecode,@Barcode,@UserID,GetDate())
					SET @ReturnValue = 'SUCCESS'
					SET @ReturnInt = 1		
			END
		END
		else if @CONDITION='REPRINT_CUSTOMER_LABEL'
		begin								
					
					SELECT TOP 1 ISNULL(ZPL_DATA,'') FROM ASSY_ZPL_LOG(NOLOCK)   
					WHERE PROFITCENTERCODE=@PROFITCENTERCODE
					AND LINECODE=@LINECODE
					AND PARTNO=@PARTNO
					AND BARCODE=@BARCODE

					set @ReturnInt=1
					return
		end	
END

GO
