/****** Object:  StoredProcedure [dbo].[Assy_Proc_Retest_Manage]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[Assy_Proc_Retest_Manage]
(    
	@Condition VARCHAR(50),
	@LineCode VARCHAR(10) = '',
	@OperationCode VARCHAR(20),
	@Barcode VARCHAR(60) = '',
	@StationCode VARCHAR(5) = '',
	@HMIMessage VARCHAR(500) = ''
)
AS    
BEGIN
	/*
		-- AUTHOR:		<Rashid Siddiqui>
		-- CREATE DATE: <01 June 2016>
		-- DESCRIPTION:	<ReTest Tag in Crimping>

		-- Modified By:	<Rashid Siddiqui>
		-- Modified on: <01 June 2016>
		-- Description: <Retest Tag in Crimping>
	*/
	SET NOCOUNT ON;
	IF @Condition = 'UPDATE'
	BEGIN
		IF EXISTS(SELECT 1 FROM Assy_ReTestLabel WITH (NOLOCK) WHERE OperationCode = @OperationCode AND LineCode = @LineCode)					
		BEGIN
			--IF EXISTS( SELECT 1 from Assy_Scan_OK WITH (NOLOCK) WHERE LineCode = @LineCode AND OperationCode = @OperationCode AND ISNULL(IsCycleStarted,0) = 1)
			--BEGIN
			--	RETURN
			--END
			
			UPDATE Assy_ReTestLabel SET IsReTest = 1, Barcode = @Barcode, HMIMessageCode = @HMIMessage
						WHERE OperationCode = @OperationCode AND LineCode = @LineCode
			--Reset Incorrect Label
			UPDATE Assy_incorrectLabel SET isIncorrect = 0, Barcode = @Barcode, HMIMessageCode = @HMIMessage
						WHERE OperationCode = @OperationCode AND LineCode = @LineCode					
			--Reset Duplicate Label
			UPDATE Assy_DuplicateLabel SET isDuplicate = 0 WHERE LineCode = @LineCode AND OperationCode = @OperationCode
			--Reset Scan Ok
			UPDATE Assy_Scan_OK SET isScan = 0 WHERE LineCode = @LineCode AND OperationCode = @OperationCode
		END
		ELSE
		BEGIN
			INSERT INTO Assy_ReTestLabel (LineCode,OperationCode,Barcode,HMIMessageCode,IsReTest)
			SELECT @LineCode, @OperationCode, @Barcode, @HMIMessage, 1 
				
			--Reset Incorrect Label
			UPDATE Assy_incorrectLabel SET isIncorrect = 0, Barcode = @Barcode, HMIMessageCode = @HMIMessage
						WHERE OperationCode = @OperationCode AND LineCode = @LineCode					
			--Reset Duplicate Label
			UPDATE Assy_DuplicateLabel SET isDuplicate = 0 WHERE LineCode = @LineCode AND OperationCode = @OperationCode
			--Reset Scan Ok
			UPDATE Assy_Scan_OK SET isScan = 0 WHERE LineCode = @LineCode AND OperationCode = @OperationCode
		END
	END
END
GO
/****** Object:  StoredProcedure [dbo].[ASSY_PROC_REWORK]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
/*************************************************************************************** 
PROCEDURE : ASSY_PROC_REWORK
AUTHOR: SACHIN KUMAR
DATE WRITTEN :  July 26, 2017
PURPOSE:  

TEST SCRIPT  
exec ASSY_PROC_REWORK @P_MODE='GET_LINE_CODE',@P_profitCenterCode='0088'

****************************************************************************************/
CREATE PROCEDURE [dbo].[ASSY_PROC_REWORK]
(
 @P_MODE varchar(50)='',
 @P_profitCenterCode varchar(10)='',
 @P_lineCode varchar(10)='',
 @P_PartNo varchar(30)='',
 @P_barcode varchar(30)='',
 @P_FoundIn varchar(20)='',
 @TYPE_REWORK_PART_BARCODES TYPE_REWORK_PART_BARCODES READONLY,
 @P_ReworkStation varchar(10)='',
 @P_UserCode varchar(30)='',
 @ReturnValue VARCHAR (2000)=NULL OUT,
 @ReturnInt INT=NULL OUT
)
AS
BEGIN

if(@P_MODE='GET_LINE_CODE')
begin

	SELECT DISTINCT LINECODE AS 'LINECODE',LINENAME AS 'LINENAME' FROM LINEMST(NOLOCK) 
	WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE

end


if(@P_MODE='GET_PART_NO')
begin
     SELECT DISTINCT PARTNO AS 'PART_NO' , PARTNO AS 'PART_DESC'  FROM ROUTINGCONFIGPARTWISE(NOLOCK)
	 WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE 
end

if(@P_MODE='GET_PARAMETER')
begin
	
	select config1.OperationCode,config2.KeyValue into #TEMP_REWORK_COUNT  from RoutingConfigDetails(nolock) config1 inner join
	RoutingConfigDetails(nolock) config2 on config1.OperationCode=config2.OperationCode and
	config1.STS_CD=config2.STS_CD and
	config1.ProfitCenterCode=config2.ProfitCenterCode and
	config1.lineCode = config2.LineCode
	where config1.ProfitCenterCode=@P_profitCenterCode
	and config1.LineCode=@P_lineCode and config1.keyType='IsReworkRequired' and config1.sts_cd=0 
	and config1.KeyValue='1' and config2.keyType='MaxReworkCount'

	SELECT distinct OM.OperationName + ' [ ' +TMP.KEYVALUE+' ] ' as 'PARAMETER' FROM OPERATIONMST(NOLOCK) OM INNER JOIN #TEMP_REWORK_COUNT TMP
	ON TMP.OPERATIONCODE=OM.OPERATIONCODE
	WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE

end

if(@P_MODE='GET_OPERATION_CODE')
begin
    
	select om.OperationCode,om.OperationName from RoutingConfigLineWise(nolock) rcl inner join
	OperationMst(nolock) om on rcl.OperationCode=om.OperationCode 
	where rcl.ProfitCenterCode=@P_profitCenterCode and rcl.LineCode=@P_lineCode
	and rcl.OperationCode not in ('OCIG')
	order by OperationSeqNo asc

end

if(@P_MODE='VALIDATE_N_RETURN_CHILD_PART_BARCODE')
begin
	
	DECLARE @FOUND_IN varchar(20) = ''
	DECLARE @EXECQUERY VARCHAR(MAX),@LINKSERVERNAME VARCHAR(100)
	DECLARE @GET_CHILD_PART_BARCODES table
	(
	  PART_DESC varchar(100),
	  PART_BARCODE varchar(30),
	  REWORK INT,
	  SCRAP INT,
	  SEQ_NO INT,
	  OC_CODE varchar(10)
	)
	
	DECLARE @PACKAGEBARCODE  TABLE	(BARCODE VARCHAR(60) NOT NULL)

	if exists(select top 1 1 from Assy_StatusRework_Data_Move_To_Running(nolock) where ProfitCenterCode = @P_PROFITCENTERCODE
					and LineCode = @P_lineCode and PartNo=@P_PartNo and Barcode=@P_barcode)
	begin
			SELECT 'NOK' , 'Rework Done for Scanned Part !!!'
			RETURN
	end

	SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL  WITH (NOLOCK) 
	WHERE PROFITCENTERCODE = @P_PROFITCENTERCODE AND LINECODE = @P_lineCode

	SET @EXECQUERY = 'SELECT PARTBARCODE FROM ' + @LINKSERVERNAME 
	+ '.DBO.SKIDBARCODEDETAIL WITH (NOLOCK) WHERE WH_CODE = ''' + @P_PROFITCENTERCODE + ''' AND PARTBARCODE = ''' + @P_barcode + ''''

	INSERT INTO @PACKAGEBARCODE(BARCODE)
	EXEC (@EXECQUERY)

	IF EXISTS (SELECT 1 FROM @PACKAGEBARCODE)
	BEGIN
		SELECT 'NOK' , 'PART ALREADY PACKED IN PACKAGING, UNPACK THE PART.'
		RETURN
	END

	IF NOT EXISTS(select top 1 1 from Assy_TallyChartStatusData_History(NOLOCK) where barcode=@P_barcode 
	and Assy_Auth=1 and (NotProcessedStatus='REWORK' OR Result='FAIL') and PROFITCENTERCODE=@P_PROFITCENTERCODE 
	and LineCode=@P_lineCode and ISNULL(IsReworkAppUse,0)=0)
	BEGIN
		SELECT 'NOK' , 'REWORK\FAIL NOT MARKED FOR SCANNED PART DURING TALLY CHART.'
		RETURN
	END

	select ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,Status,FailCount,Datecode,PartNo,
    Active,ResultTimestamp,ScanTimestamp,UserID,IsTallyChartApproved,IsReworkPart,IsPendingPart,ProductionOrderNo,PROD_LOT_NO
	into #TEMP_RW_Assy_LineAssyStatus_running	
	from Assy_LineAssyStatus(nolock) 
	where PROFITCENTERCODE=@P_PROFITCENTERCODE and LineCode=@P_lineCode 
	and PartNo=@P_PartNo and barcode=@P_barcode and OperationCode not in ('OCIG')

	IF (@@rowcount > 0)
	BEGIN
			SET @FOUND_IN='FIXED'
	END
	
	if exists(select * from #TEMP_RW_Assy_LineAssyStatus_running)
	begin
		  -- Check for Maximum Rework Attempts	
			select OperationCode,convert(int,KeyValue) as 'maxReworkCount' into #TEMP_REWORK_COUNT_ 
			from RoutingConfigDetails(nolock) where ProfitCenterCode=@P_profitCenterCode
			and LineCode=@P_lineCode and STS_CD=0 and KeyType='MaxReworkCount'
		  	  
			select OperationCode,SUM(ReworkCount) as PrvReworkCount into #TEMP_PrvReworkCount_
			FROM Assy_Status_Rework_log(NOLOCK) STS_RUN
			WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE AND LINECODE=@P_LINECODE 
			AND PARTNO=@P_PARTNO AND BARCODE=@P_BARCODE 
			group by profitCenterCode,LineCode,MachineCode,OperationCode,Barcode
													
							
		  if exists(select top 1 1 from #TEMP_PrvReworkCount_ tmp inner join
		  #TEMP_REWORK_COUNT_ trc on tmp.OperationCode=trc.OperationCode and
		  trc.maxReworkCount=tmp.PrvReworkCount)
		  begin
		        
				SELECT 'NOK' , 'Maximum Rework Attempt Reached for Barcode ( '+ @P_barcode + ' )'
				return	      
		  end
		  -- End of Check for Maximum Rework Attempts
		  		
		  select OperationCode into #TEMP_REWORK_REQUIRED_ON from RoutingConfigDetails(nolock) where ProfitCenterCode=@P_profitCenterCode
		  and LineCode=@P_lineCode and STS_CD=0 and KeyType='IsReworkRequired' and KeyValue='1'

		  select distinct om.OperationCode as 'OperationCode',om.OperationName as 'OperationName' , OperationSeqNo as 'OperationSeqNo' into #TEMP_REWORK_OC_CODE
		  from RoutingConfigLineWise(nolock) rcl inner join
		  OperationMst(nolock) om on rcl.OperationCode=om.OperationCode 
		  where rcl.ProfitCenterCode=@P_profitCenterCode and rcl.LineCode=@P_lineCode
		   and rcl.OperationCode in (select distinct OperationCode from #TEMP_RW_Assy_LineAssyStatus_running)
		   --and rcl.OperationCode in (select distinct OperationCode from #TEMP_REWORK_REQUIRED_ON)
		   and om.ProfitCenterCode=@P_profitCenterCode
		  --order by OperationSeqNo asc

		  SELECT * FROM #TEMP_REWORK_OC_CODE ORDER BY OPERATIONSEQNO ASC

		  insert into @GET_CHILD_PART_BARCODES(
		   PART_DESC,PART_BARCODE,REWORK,SCRAP,SEQ_NO,OC_CODE
		  )
	      SELECT distinct REPLACE(ChildPartNo,'_',' '),ChildPartBarcode,0 as 'Rework' , 0 as 'SCRAP' , 
		  tmp.OperationSeqNo,tmp.OperationCode
		  FROM ASSY_CHILD_PART_DETAILS(NOLOCK) cpd inner join #TEMP_REWORK_OC_CODE 
		  tmp on cpd.OperationCode=tmp.OperationCode
		  where 
		  PROFITCENTERCODE=@P_PROFITCENTERCODE and LineCode=@P_lineCode and 
		  PartNumber=@P_PartNo and  Barcode=@P_barcode and STS_CD=0
		  --and cpd.OperationCode in (select distinct OperationCode from #TEMP_REWORK_REQUIRED_ON)
		  --order by tmp.OperationSeqNo

		  declare @max int
		  select @max = ISNULL(MAX(SEQ_NO),0) + 1 from @GET_CHILD_PART_BARCODES

		 
			insert into @GET_CHILD_PART_BARCODES(
			PART_DESC,PART_BARCODE,REWORK,SCRAP,SEQ_NO,OC_CODE
			)
			VALUES('FG BARCODE',@P_barcode,0,0,@max,'OCFV')
		 

		  SELECT @FOUND_IN as 'FOUND_IN'
		  SELECT  PART_DESC as 'PART_DESC',PART_BARCODE as 'PART_BARCODE',REWORK as 'REWORK',SCRAP as 'SCRAP' , 
		  OC_CODE as 'OPERATION_CODE' FROM @GET_CHILD_PART_BARCODES order by SEQ_NO

	end
	else
	begin
			SELECT 'NOK' , 'Scanned Barcode ( '+ @P_barcode + ' ) Not For Rework'
	end
	
enD


if(@P_MODE='SAVE')
begin
	
	begin try
	begin tran
	declare @OperationSeq int = 0
	
	SELECT @OperationSeq=ISNULL(OPERATIONSEQNO,0) FROM ROUTINGCONFIGLINEWISE(nolock)
	WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE AND LINECODE=@P_LINECODE AND OPERATIONCODE=@P_REWORKSTATION

	SELECT OPERATIONCODE into #TEMP_OPERATION_CODE FROM ROUTINGCONFIGLINEWISE(nolock)
	WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE AND LINECODE=@P_LINECODE and OPERATIONSEQNO >=@OperationSeq
			
	SELECT OPERATIONCODE into #TEMP_OPERATION_CODE_R FROM ROUTINGCONFIGLINEWISE(nolock)
	WHERE PROFITCENTERCODE=@P_PROFITCENTERCODE AND LINECODE=@P_LINECODE and OPERATIONSEQNO < @OperationSeq

	IF EXISTS(SELECT TOP 1 1  FROM @TYPE_REWORK_PART_BARCODES WHERE PART_BARCODE=@P_BARCODE AND REWORK=1)
	BEGIN
			
			
			if(@OperationSeq = 0)
			begin
				SELECT 'NOK' , 'Operation Sequence Not Found'
				rollback tran
				return
			end
	
			if(@P_FoundIn='FIXED')
			begin
					begin try
							
							-- Rework
							insert into ASSY_STATUS_REWORK_LOG(
							ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,Status,FailCount,Datecode,PartNo,
							Active,ResultTimestamp,ScanTimestamp,UserID,IsTallyChartApproved,IsReworkPart,ProductionOrderNo,PROD_LOT_NO,
							[ReworkUser],[ReworkTimeStamp],REWORKCOUNT 
							)
							select ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,Status,FailCount,Datecode,PartNo,
							Active,ResultTimestamp,ScanTimestamp,UserID,IsTallyChartApproved,IsReworkPart,ProductionOrderNo,PROD_LOT_NO,
							@P_UserCode,GETDATE(),1 
							from ASSY_LINEASSYSTATUS(nolock) 
							where PROFITCENTERCODE=@P_PROFITCENTERCODE and LineCode=@P_lineCode 
							and PartNo=@P_PartNo and barcode=@P_barcode and operationCode in (select OPERATIONCODE from #TEMP_OPERATION_CODE)


							INSERT INTO ASSY_LINEASSYSTATUS_HISTORY (PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,STATIONCODE,BARCODE,STATUS,
							FAILCOUNT,DATECODE,PARTNO,SCANTIMESTAMP,RESULTTIMESTAMP,ACTIVE,USERID,ISTALLYCHARTAPPROVED,
							TRANSACTION_NUMBER,ISCONFIRMED,KANBAN_ID,ERP_CONF_TIMESTAMP,HIS_ENT_DT,HIS_ENT_BY,ISREWORKPART,ProductionOrderNo)
							SELECT PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,STATIONCODE,BARCODE,STATUS,FAILCOUNT,
							DATECODE,PARTNO,SCANTIMESTAMP,RESULTTIMESTAMP,ACTIVE,USERID,ISTALLYCHARTAPPROVED,TRANSACTION_NUMBER,
							ISCONFIRMED,KANBAN_ID,ERP_CONF_TIMESTAMP,GETDATE(),@P_UserCode,ISREWORKPART,ProductionOrderNo 
							FROM ASSY_LINEASSYSTATUS WITH (NOLOCK) WHERE BARCODE = @P_barcode  and 
							PROFITCENTERCODE=@P_PROFITCENTERCODE and LineCode=@P_lineCode and PartNo=@P_PartNo
							and operationCode in (select OPERATIONCODE from #TEMP_OPERATION_CODE_R)

							-- Move Data To Running
							insert into Assy_StatusRework_Data_Move_To_Running(
							ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,Status,FailCount,Datecode,PartNo,
							Active,ResultTimestamp,ScanTimestamp,UserID,IsTallyChartApproved,IsReworkPart,ProductionOrderNo,PROD_LOT_NO
							)
							select ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,Status,FailCount,Datecode,PartNo,
							Active,ResultTimestamp,ScanTimestamp,UserID,0,IsReworkPart,ProductionOrderNo,PROD_LOT_NO
							from ASSY_LINEASSYSTATUS(nolock) 
							where PROFITCENTERCODE=@P_PROFITCENTERCODE and LineCode=@P_lineCode 
							and PartNo=@P_PartNo and barcode=@P_barcode and operationCode in (select OPERATIONCODE from #TEMP_OPERATION_CODE_R)

							-- Delete Data
							delete from ASSY_LINEASSYSTATUS
							where PROFITCENTERCODE=@P_PROFITCENTERCODE and LineCode=@P_lineCode 
							and PartNo=@P_PartNo and barcode=@P_barcode

							-- ByPass Tally Chart Check
							update Assy_TallyChartStatusData_History 
							set IsReworkAppUse = 1
							where barcode=@P_barcode and PROFITCENTERCODE=@P_PROFITCENTERCODE 
							and LineCode=@P_lineCode and ISNULL(IsReworkAppUse,0)=0

					end try
					begin catch
					SELECT 'NOK' ,  CAST(ISNULL(ERROR_NUMBER(),0) AS VARCHAR(5)) + '|' + 
										CAST(ISNULL(ERROR_SEVERITY(),0)AS VARCHAR(5)) + '|' + 
										CAST(ISNULL(ERROR_STATE(),0) AS VARCHAR(5)) + '|' + 
										CAST(ISNULL(ERROR_PROCEDURE(),'') AS VARCHAR(200)) + '|' + 
										CAST(ISNULL(ERROR_LINE(),0) AS VARCHAR(5)) + '|' + 
										CAST(ISNULL(ERROR_MESSAGE(),'') AS VARCHAR(1500)) AS 'MSG'
						rollback tran
					end catch
					--To Do Write Code Also Delete Data From Line

		end
	
			if exists ( select top 1 1 from Assy_LineAssyParamData(nolock) where 
							PROFITCENTERCODE=@P_PROFITCENTERCODE and LineCode=@P_lineCode 
							and PartNo=@P_PartNo and barcode=@P_barcode and
							operationCode in (select OPERATIONCODE from #TEMP_OPERATION_CODE)
			)
			begin

				insert into Assy_ParamData_Rework_log(
				ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,
				TagName,Value,Result,Datecode,UserID,Timestamp,PartNo,UID,ReworkUser,ReworkTimeStamp,ScanTimeStamp 
				)
				select distinct ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,
				TagName,Value,Result,Datecode,UserID,Timestamp,PartNo,UID ,@P_UserCode,GETDATE(),ScanTimeStamp
				from Assy_LineAssyParamData(nolock) where 
				PROFITCENTERCODE=@P_PROFITCENTERCODE and LineCode=@P_lineCode 
				and PartNo=@P_PartNo and barcode=@P_barcode and
				operationCode in (select OPERATIONCODE from #TEMP_OPERATION_CODE)

				insert into Assy_ParamDataRework_To_Running(
				ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,
				TagName,Value,Result,Datecode,UserID,Timestamp,PartNo,UID,ScanTimeStamp
				)
				select distinct ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,Barcode,
				TagName,Value,Result,Datecode,UserID,Timestamp,PartNo,UID,ScanTimeStamp
				from Assy_LineAssyParamData(nolock) where 
				PROFITCENTERCODE=@P_PROFITCENTERCODE and LineCode=@P_lineCode 
				and PartNo=@P_PartNo and barcode=@P_barcode and
				operationCode in (select OPERATIONCODE from #TEMP_OPERATION_CODE_R)

				insert into Assy_ParamData_Dtl_Rework_Log(
				[UID],[TagId],[Value],[ReworkUser],[ReworkTimeStamp])
				select distinct UID,TagId,Value,@P_UserCode,getdate() from Assy_LineAssyParamData_dtl where UID in (
				select UID from Assy_LineAssyParamData(nolock) where 
				PROFITCENTERCODE=@P_PROFITCENTERCODE and LineCode=@P_lineCode 
				and PartNo=@P_PartNo and barcode=@P_barcode and
				operationCode in (select OPERATIONCODE from #TEMP_OPERATION_CODE)
				)

				insert into Assy_ParamDataRework_Move_To_Running_Dtl(
				[UID],[TagId],[Value])
				select distinct UID,TagId,Value from Assy_LineAssyParamData_dtl where UID in (
				select UID from Assy_LineAssyParamData(nolock) where 
				PROFITCENTERCODE=@P_PROFITCENTERCODE and LineCode=@P_lineCode 
				and PartNo=@P_PartNo and barcode=@P_barcode and
				operationCode in (select OPERATIONCODE from #TEMP_OPERATION_CODE_R)
				)
							
				delete from Assy_LineAssyParamData_dtl where UID in (
				select UID from Assy_LineAssyParamData(nolock) where 
				PROFITCENTERCODE=@P_PROFITCENTERCODE and LineCode=@P_lineCode 
				and PartNo=@P_PartNo and barcode=@P_barcode 
				)

				delete from Assy_LineAssyParamData where 
				PROFITCENTERCODE=@P_PROFITCENTERCODE and LineCode=@P_lineCode 
				and PartNo=@P_PartNo and barcode=@P_barcode 
			end		

	end

	IF EXISTS(SELECT TOP 1 1  FROM @TYPE_REWORK_PART_BARCODES WHERE PART_BARCODE<>@P_BARCODE )
	BEGIN
		
		begin try
		
		  SELECT  * into #TEMP_TYPE_REWORK_PART_BARCODES FROM @TYPE_REWORK_PART_BARCODES WHERE PART_BARCODE<>@P_BARCODE
		  
		  -- STS_CD 100 Rework.
		  -- STS_CD 200 Scrap. // Scrap Will Not Be Allowed 
		  insert into ASSY_CHILD_PART_DETAILS_REWORK_LOG(
		  ProfitCenterCode,LineCode,MachineCode,OperationCode,PartNumber,DateCode,Barcode,ChildPartNo,
		  ChildPartBarcode,SeqNumber,STS_CD,ENT_BY,ENT_STAMP,ReworkUser,ReworkTimeStamp
		  )
		  select ProfitCenterCode,LineCode,MachineCode,OperationCode,PartNumber,DateCode,Barcode,ChildPartNo,
		  ChildPartBarcode,SeqNumber,case when tmp.Rework=1 then 100 else 200 end as 'STS_CD' ,ENT_BY,ENT_STAMP,@P_UserCode,GETDATE()
		  FROM ASSY_CHILD_PART_DETAILS(NOLOCK) cpd inner join #TEMP_TYPE_REWORK_PART_BARCODES tmp
		  on cpd.ChildPartBarcode=tmp.PART_BARCODE
		  where 
		  PROFITCENTERCODE=@P_PROFITCENTERCODE and LineCode=@P_lineCode and 
		  PartNumber=@P_PartNo and  Barcode=@P_barcode and STS_CD=0
		  and ChildPartBarcode in (select PART_BARCODE from #TEMP_TYPE_REWORK_PART_BARCODES)
		  and operationCode in (select OPERATIONCODE from #TEMP_OPERATION_CODE)	
		

		  delete FROM ASSY_CHILD_PART_DETAILS where 
		  PROFITCENTERCODE=@P_PROFITCENTERCODE and LineCode=@P_lineCode and 
		  PartNumber=@P_PartNo and  Barcode=@P_barcode and STS_CD=0
		  and ChildPartBarcode in (select PART_BARCODE from #TEMP_TYPE_REWORK_PART_BARCODES)
		  and operationCode in (select OPERATIONCODE from #TEMP_OPERATION_CODE)	
		 
		  end try
		  begin catch
		  rollback tran
				SELECT 'NOK', CAST(ISNULL(ERROR_NUMBER(),0) AS VARCHAR(5)) + '|' + 
			CAST(ISNULL(ERROR_SEVERITY(),0)AS VARCHAR(5)) + '|' + 
			CAST(ISNULL(ERROR_STATE(),0) AS VARCHAR(5)) + '|' + 
			CAST(ISNULL(ERROR_PROCEDURE(),'') AS VARCHAR(200)) + '|' + 
			CAST(ISNULL(ERROR_LINE(),0) AS VARCHAR(5)) + '|' + 
			CAST(ISNULL(ERROR_MESSAGE(),'') AS VARCHAR(1500)) AS 'MSG'
		  end catch
	END
	
	commit tran
	SELECT 'OK' 
	
	end try
	begin catch
			SELECT 'NOK', CAST(ISNULL(ERROR_NUMBER(),0) AS VARCHAR(5)) + '|' + 
			CAST(ISNULL(ERROR_SEVERITY(),0)AS VARCHAR(5)) + '|' + 
			CAST(ISNULL(ERROR_STATE(),0) AS VARCHAR(5)) + '|' + 
			CAST(ISNULL(ERROR_PROCEDURE(),'') AS VARCHAR(200)) + '|' + 
			CAST(ISNULL(ERROR_LINE(),0) AS VARCHAR(5)) + '|' + 
			CAST(ISNULL(ERROR_MESSAGE(),'') AS VARCHAR(1500)) AS 'MSG'
			rollback tran
	end catch
	
	
enD

IF(@P_MODE='GET_SERIAL_PORT')
BEGIN					
	select ISNULL(KeyValue,'') from routingConfigDetails(nolock) where ProfitCenterCode=@P_profitCenterCode and
	LineCode=@P_lineCode and STS_CD=0 and KeyType='ReworkSerialPort'
END

END




GO
/****** Object:  StoredProcedure [dbo].[ASSY_PROC_REWORK_REJECTION]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[ASSY_PROC_REWORK_REJECTION] 
(
@DATA  ASSY_REWORK READONLY,
@LINECODE VARCHAR(100)=NULL,
@PROFITCENTERCODE VARCHAR(100)=NULL,
@CONDITION VARCHAR(100)=NULL,
@BARCODE VARCHAR(30)=NULL,
@MACHINE_CODE VARCHAR(50)=NULL,
@OPERATION_CODE VARCHAR(50)=NULL,
@USERID VARCHAR(50)=NULL,
@RETURNVALUE VARCHAR (2000)=NULL OUT,
@RETURNINT INT=NULL OUT
)
AS
BEGIN
SET NOCOUNT ON
-- NOTHING = 0
-- SUCCESS = 1
-- ERROR = 2
-- ALREADYEXISTS = 3
 --NOTEXISTS = 4

BEGIN TRY
IF @CONDITION='MACHINEDETAIL'
BEGIN
		SELECT RP.PARTNO,LL.LINECODE,LL.LINENAME,OM.OPERATIONCODE,OM.OPERATIONNAME FROM ROUTINGCONFIGLINEWISE RL JOIN ROUTINGCONFIGPARTWISE RP ON RL.PROFITCENTERCODE = RP.PROFITCENTERCODE
		AND RL.OPERATIONCODE = RP.OPERATIONCODE  AND RL.MACHINECODE = RP.MACHINECODE 
		JOIN OPERATIONMST OM ON OM.PROFITCENTERCODE = RP.PROFITCENTERCODE  
		AND OM.OPERATIONCODE = RP.OPERATIONCODE 
		join linemst LL ON LL.LINECODE= RL.LINECODE AND 
		RL.PROFITCENTERCODE = LL.PROFITCENTERCODE
		WHERE RP.PARTNO  =left(@BARCODE,8)
		RETURN
END


IF @CONDITION='VALIDATEBARCODE'
	BEGIN
		IF NOT EXISTS (SELECT TOP 1 * FROM ASSY_TALLYCHARTSTATUSDATA WHERE BARCODE=@BARCODE and NotProcessedStatus='REWORK')
		BEGIN
			SET @RETURNVALUE='INVALID_BARCODE'
			SET @RETURNINT=3
			RETURN
		END
		--CHECK WHETHER CHILD PARTS HAVE MARKED AS REJECT OR NOT
		IF EXISTS( SELECT 1 FROM ASSY_REWORK_REJECTION_HDR(NOLOCK) WHERE  
		BARCODE=@BARCODE AND PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE and STATUS='REWORK' )
		BEGIN
			SET @RETURNVALUE='ALREADY_REWORKED'
			SET @RETURNINT=3
			RETURN
		END
		--CHECKED WHETHER PART HAS MARKED REWORK IN TALLY CHART OR REWORKED MANUALLY BY USER
		IF NOT EXISTS (SELECT 1 FROM ASSY_REWORK_HDR (NOLOCK) WHERE  BARCODE=@BARCODE AND PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE )
		BEGIN
			SET @RETURNVALUE='REWORK_NOT_PERFORMED'
			SET @RETURNINT=3
			RETURN
		END
END

IF @CONDITION='VALIDATEBARCODE_REWORK'
	BEGIN
		IF NOT EXISTS (SELECT TOP 1 * FROM ASSY_TALLYCHARTSTATUSDATA WHERE BARCODE=@BARCODE)
		BEGIN
			SET @RETURNVALUE='INVALID_BARCODE'
			SET @RETURNINT=3
			RETURN
		END
		--CHECK WHETHER CHILD PARTS HAVE MARKED AS REJECT OR NOT
		IF EXISTS( SELECT 1 FROM ASSY_REWORK_REJECTION_HDR(NOLOCK) WHERE  
		BARCODE=@BARCODE AND PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE and STATUS='REWORK' )
		BEGIN
			SET @RETURNVALUE='ALREADY_REWORKED'
			SET @RETURNINT=3
			RETURN
		END
		--CHECKED WHETHER PART HAS MARKED REWORK IN TALLY CHART OR REWORKED MANUALLY BY USER
		IF NOT EXISTS (SELECT 1 FROM ASSY_REWORK_HDR (NOLOCK) WHERE  BARCODE=@BARCODE AND PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE )
		BEGIN
			SET @RETURNVALUE='REWORK_NOT_PERFORMED'
			SET @RETURNINT=3
			RETURN
		END
		
		INSERT INTO ASSY_REWORK_REJECTION_HDR (PROFITCENTERCODE,LINECODE,BARCODE,FGPARTNO,REWORKCODE,REWORKREASON,REMARKS,USERID,CREATEDON,MACHINE_CODE,OPERATION_CODE,STATUS)
		SELECT  @PROFITCENTERCODE ,@LINECODE,@BARCODE,LEFT(@BARCODE,8),'' ,'','',@USERID ,GETDATE(),@MACHINE_CODE,@OPERATION_CODE,'REWORK'
																													
		INSERT INTO ASSY_REWORK_REJECTION_DTL(PROFITCENTERCODE,LINECODE,BARCODE,CHILDPARTNO,REJECTEDQTY,STATUS,desp)			
		SELECT @PROFITCENTERCODE ,@LINECODE ,@BARCODE , SUBSTRING(RM_ITEM,0,CHARINDEX('--',RM_ITEM)),
		convert(numeric(10,2), substring(RM_ITEM,charindex('(',RM_ITEM)+1,charindex(')',RM_ITEM)-charindex('(',RM_ITEM)-1)),'REWORK',
		substring(RM_ITEM,CHARINDEX('--',RM_ITEM) +2 ,CHARINDEX('(',RM_ITEM)-CHARINDEX('--',RM_ITEM)-2) FROM @DATA
		where RM_ITEM <> left(@BARCODE,8)
		
		SET @RETURNVALUE='SUCCESS'
		SET @RETURNINT=1
		RETURN
	END
	

IF @CONDITION='VALIDATEBARCODE_REJECT'
	BEGIN
		IF NOT EXISTS (SELECT TOP 1 * FROM ASSY_TALLYCHARTSTATUSDATA WHERE BARCODE=@BARCODE)
		BEGIN
			SET @RETURNVALUE='INVALID_BARCODE'
			SET @RETURNINT=3
			RETURN
		END
		--CHECK WHETHER CHILD PARTS HAVE MARKED AS REJECT OR NOT
		IF EXISTS( SELECT 1 FROM ASSY_REWORK_REJECTION_HDR(NOLOCK) WHERE  
		BARCODE=@BARCODE AND PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE and STATUS='REJECT' )
		BEGIN
			SET @RETURNVALUE='ALREADY_REJECT'
			SET @RETURNINT=3
			RETURN
		END
		--CHECKED WHETHER PART HAS MARKED REWORK IN TALLY CHART OR REWORKED MANUALLY BY USER
		IF NOT EXISTS (SELECT 1 FROM ASSY_REWORK_HDR (NOLOCK) WHERE  BARCODE=@BARCODE AND PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE )
		BEGIN
			SET @RETURNVALUE='REWORK_NOT_PERFORMED'
			SET @RETURNINT=3
			RETURN
		END
		
		INSERT INTO ASSY_REWORK_REJECTION_HDR (PROFITCENTERCODE,LINECODE,BARCODE,FGPARTNO,REWORKCODE,REWORKREASON,REMARKS,USERID,CREATEDON,MACHINE_CODE,OPERATION_CODE,STATUS)
		SELECT  @PROFITCENTERCODE ,@LINECODE,@BARCODE,LEFT(@BARCODE,8),'' ,'','',@USERID ,GETDATE(),@MACHINE_CODE,@OPERATION_CODE,'REJECT'
																													
		INSERT INTO ASSY_REWORK_REJECTION_DTL(PROFITCENTERCODE,LINECODE,BARCODE,CHILDPARTNO,REJECTEDQTY,STATUS,desp)			
		SELECT @PROFITCENTERCODE ,@LINECODE ,@BARCODE , substring(RTRIM(LTRIM(RM_ITEM)),1,charindex('--',RM_ITEM)-1),
		convert(numeric(10,2), substring(RM_ITEM,charindex('(',RM_ITEM)+1,charindex(')',RM_ITEM)-charindex('(',RM_ITEM)-1)),'REJECT',
		substring(RM_ITEM,CHARINDEX('--',RM_ITEM) +2 ,CHARINDEX('(',RM_ITEM)-CHARINDEX('--',RM_ITEM)-2) FROM @DATA
		where RM_ITEM <> left(@BARCODE,8)
		
		SET @RETURNVALUE='SUCCESS'
		SET @RETURNINT=1
		RETURN
	END
	
		
END TRY
BEGIN CATCH
		SET @RETURNVALUE =	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 	CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
		CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
		CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + CAST(ERROR_MESSAGE() AS VARCHAR(1500))
		SET @RETURNINT = 2
END CATCH
END










GO
/****** Object:  StoredProcedure [dbo].[ASSY_PROC_REWORKBARCODE_PRINT]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[ASSY_PROC_REWORKBARCODE_PRINT]
(
@DATA  ASSY_REWORK_BARCODEPRINT READONLY,
@LINECODE VARCHAR(100)=NULL,
@PROFITCENTERCODE VARCHAR(100)=NULL,
@BARCODE VARCHAR(30)=NULL,
@REMARKS VARCHAR(500)=NULL,
@CONDITION VARCHAR(50)=NULL,
@BARCODE_TYPE VARCHAR(50)=NULL,
@USERID VARCHAR(50)=NULL,
@RETURNVALUE VARCHAR (2000)=NULL OUT,
@RETURNINT INT=NULL OUT
)
AS
BEGIN
SET NOCOUNT ON
-- NOTHING = 0, SUCCESS = 1, ERROR = 2, ALREADYEXISTS = 3, NOTEXISTS = 4
BEGIN TRY

IF @CONDITION='VALIDATEBARCODE'
	BEGIN
		SELECT DISTINCT CHILDPARTNO,DESP,REJECTEDQTY,PIECES_PER_BOX FROM ASSY_REWORK_REJECTION_DTL DTL JOIN PRODUCT_MASTER PM ON 
		DTL.CHILDPARTNO=PM.SEWS_PART_NO
		where dtl.status=@BARCODE_TYPE
		SET @RETURNVALUE='SUCCESS'
		SET @RETURNINT=1
END
IF @CONDITION='SAVEMODE'
	BEGIN
		
		INSERT INTO ASSY_REWORKBARCODE_PRINT_DTL(Barcode,PartDetail,PrintBarcode_No,DESP,QTY,PACK_SIZE,NO_LABEL,REMARKS,USERNAME,CREATEDATE,TYPE,PROFITCENTERCODE,LINECODE)			
		SELECT '',PARTNO,'',DESP,CONVERT(INT,QTY),CONVERT(INT,PACKING),CONVERT(INT,NO_LABEL),@REMARKS,@USERID,getdate(),@BARCODE_TYPE,
		@PROFITCENTERCODE,@LINECODE FROM @DATA 
		
		SET @RETURNVALUE='SUCCESS'
		SET @RETURNINT=1
		RETURN
	END
	
		
END TRY
BEGIN CATCH
		SET @RETURNVALUE =	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 	CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
		CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
		CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + CAST(ERROR_MESSAGE() AS VARCHAR(1500))
		SET @RETURNINT = 2
END CATCH
END










GO
/****** Object:  StoredProcedure [dbo].[Assy_proc_RFIDBarcode_Mapping]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE Proc [dbo].[Assy_proc_RFIDBarcode_Mapping]
(
@CONDITION VARCHAR(60),
@PROFITCENTERCODE VARCHAR(20)=NULL,
@LINECODE VARCHAR(20)=NULL,
@Barcode varchar(100)=NUll,
@RFID varchar(100)=NULL,
@PartNo varchar(60)=null,
@DateCode varchar(10)=null,
@CaliperSerNo smallint=null,
@ReturnValue VARCHAR (2000)=NULL OUT,
@ReturnInt INT=NULL OUT
)
AS
BEGIN
		
--Author :<Ravishankar Mishra>
--Created date:<25/07/2016>

--Modified By:<Ravishankar Mishra>
--Modified date:<06/12/2016>
--Description- To search data on basis of Caliper Date code not on basis of RFID date code 
--exec Assy_proc_RFIDBarcode_Mapping  @CONDITION='PartNo',@profitcentercode='0088',@linecode='j04'
--exec Assy_proc_RFIDBarcode_Mapping  @CONDITION='SHOW_RFID_BARCODE_MAPPING',@profitcentercode='0088',@linecode='j04',@Barcode='00193160050016180000117216'
--exec Assy_proc_RFIDBarcode_Mapping  @CONDITION='SHOW_RFID_BARCODE_MAPPING',@profitcentercode='0088',@linecode='j04'
--,@PartNo='19316006',@datecode='27',@CaliperSerNo='0013'

		SET NOCOUNT ON
		if @CONDITION='SHOW_RFID_BARCODE_MAPPING'
		begin
				if isnull(@RFID,'')='' and isnull(@Barcode,'')='' 
				begin
				           if isnull(@CaliperSerNo,'')<>''
						   begin 
					    			select ROW_NUMBER() over(order by CaliperSerNo)[Serial Number] ,RFID as [RFID Tags],Barcode,convert(varchar(20),CaliperSerNo) as [Caliper Serial Number],CaliperDatecode as Datecode,PartNo as [Part Number]  
									from dbo.Assy_FinalViewing_RFID_Barcode_Mapping with(nolock) where profitcentercode=@profitcentercode 
									and linecode=@linecode and PartNo=@PartNo and CaliperDatecode like '%'+@DateCode+'%' 
									and convert(varchar(20),CaliperSerNo) like '%'+convert(varchar(20),@CaliperSerNo)+'%'
						   end
						   ELSE
									select ROW_NUMBER() over(order by CaliperSerNo)[Serial Number],RFID as [RFID Tags],Barcode,CaliperSerNo as [Caliper Serial Number],CaliperDatecode as Datecode,PartNo as [Part Number]  
									from dbo.Assy_FinalViewing_RFID_Barcode_Mapping with(nolock) where profitcentercode=@profitcentercode 
									and linecode=@linecode and PartNo=@PartNo and CaliperDatecode like '%'+@DateCode+'%' 
									
							set @ReturnInt=1
							return
				end
				else if isnull(@Barcode,'')=''
				begin
							select  ROW_NUMBER() over(order by CaliperSerNo)[Serial Number] ,RFID as [RFID Tags],Barcode,CaliperSerNo as [Caliper Serial Number],CaliperDatecode as Datecode,PartNo as [Part Number]
							from dbo.Assy_FinalViewing_RFID_Barcode_Mapping with(nolock) where profitcentercode=@profitcentercode 
							and linecode=@linecode and RFID like '%'+@RFID+'%'
							set @ReturnInt=1
							return
				end
				else if isnull(@RFID,'')=''
				begin
							select  ROW_NUMBER() over(order by CaliperSerNo)[Serial Number] ,RFID as [RFID Tags],Barcode,CaliperSerNo as [Caliper Serial Number],CaliperDatecode as Datecode,PartNo as [Part Number]  
							from dbo.Assy_FinalViewing_RFID_Barcode_Mapping with(nolock) where profitcentercode=@profitcentercode 
							and linecode=@linecode and Barcode like '%'+@Barcode+'%'
							set @ReturnInt=1
							return
				end			
		end
		else if @CONDITION='PartNo'
		begin				
				select SEWS_PART_NO  as PartNo from dbo.product_master with(nolock) where warehouse_cd=@profitcentercode and sts_cd=0
				and MATERIAL_TP=dbo.Assy_FN_Get_LineTypeName_From_LineCode(@profitcentercode,@linecode)
				order by 1
				return
		end
end

GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_Routing_Changed_Dtl]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


create PROC [dbo].[Assy_Proc_Routing_Changed_Dtl]
(
@CONDITION VARCHAR(70),
@ProfitCenterCode varchar(20)=NULL,
@LineCode varchar(20)=NULL,
@RETURNVALUE VARCHAR (2000)=NULL OUT,
@RETURNINT INT=NULL OUT
)
AS
BEGIN
--<Created By>:Ravishankar Mishra
--<Created Date> : 22-02-2016
-- TO REMBEMBER
-- NOTHING = 0
-- SUCCESS = 1
-- ERROR = 2
-- ALREADYEXISTS = 3
-- NOTEXISTS = 4
--exec Assy_Proc_Routing_Changed_Dtl @CONDITION='UPDATE',@ProfitCenterCode=@ProfitCenterCode,@LineCode=@LineCode
		set nocount on
		if @CONDITION='UPDATE'
		begin
				if exists
				(
					select  1 from Assy_Routing_Changed_Dtl with(nolock) where ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode
				)
				begin
						update Assy_Routing_Changed_Dtl set IsBarcodePrinted=1 , timestamp =getdate()  where ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode
				end
				else
					begin
							insert into Assy_Routing_Changed_Dtl(ProfitCenterCode,LineCode,IsBarcodePrinted,Timestamp,Datecode,PartNo)
							select ProfitCenterCode,LineCode,1,getdate(),datecode,assy_PartNo from assy_runningpart with(nolock)
							 where ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode order by CreatedDate desc
					end
					return
		end
		else if @CONDITION='Routing_Changed'
		begin				
				
				if exists
				(
					select 1 from  Assy_Routing_Changed_Dtl with(nolock) where ProfitCenterCode=@ProfitCenterCode 
					and linecode=@LineCode and isnull(IsBarcodePrinted,0)=1
				)
				begin
						 set @ReturnValue = 'CHANGED'
				end
				else
					begin
							 set @ReturnValue = 'NC'
					end
					SET @ReturnInt=1
				    return
		end

END

GO
/****** Object:  StoredProcedure [dbo].[Assy_PROC_RoutingConfigLineWise]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

--declare @p4 dbo.TBLRoutingConfigLineWise
--insert into @p4 values(N'0021',N'RETE',N'1',N'L0001',N'1',N'1',N'1',N'1',N'1',N'0',N'0',N'3',N'FDG',N'ABCD')
--insert into @p4 values(NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL)

--declare @p5 varchar(2000)
--set @p5='INVALID MACHINE CODE:ABCD'
--declare @p6 int
--set @p6=4
--exec USP_RoutingConfigLineWise @Mode=N'd',@ProfitCenterCode=N'0021',@LineCode=N'p2',
--@TBLRoutingLine=@p4,@ReturnValue=@p5 output,@ReturnInt=@p6 output
--select @p5, @p6


/*****************************************************************************************                                                                
PROCEDURE		:  USP_RoutingConfigLineWise                                           
AUTHOR			:  Mrigendra Kumar Kashyap                        
DATE WRITTEN	:  01 Aug 2014
PURPOSE			:  To fetch/save/update Routing Configuration Line wise.                
TEST SCRIPT  :  Modified By Ravi on 31/03/2016                 
*****************************************************************************************/
CREATE proc [dbo].[Assy_PROC_RoutingConfigLineWise]
(
	@TBLRoutingLine		TBLRoutingConfigLineWise readonly,
	@ProfitCenterCode		varchar(10)=null,
	@LineCode				varchar(10)=null,
	@Mode					varchar(1)='D',
	@OperationCode 			varchar(10)=null,
	@MachineCode 			varchar(10)=null,
	@WIPQty					int=null,	
	@OperationName			varchar(50)=null,
	@ReturnValue			varchar(2000)=null output,
	@ReturnInt				int =null output,
	@ISLocal                bit=0
)
as 
begin
			set nocount on
			declare @countMaster int=0;
			declare @invalidMachineCode varchar(100)='';

			Declare @MachineLinkServerName varchar(100)						-- ADDED BY Rashid 20190424
				, @MachineLinkServerDB varchar(100)						-- ADDED BY Rashid 20190424
				, @MachineLinkServer varchar(300)						-- ADDED BY Rashid 20190424
				, @MachineDBRoutingLineWiseTableName varchar(100)		-- ADDED BY Rashid 20190424
				, @MachineDBRoutingPartWiseTableName varchar(100)		-- ADDED BY Rashid 20190424
				, @MachineDBPokaYokeMasterTableName varchar(100)		-- ADDED BY Rashid 20190424
				, @LinkServerType VARCHAR(60) = ''						-- ADDED BY Rashid 20190424
				, @Dynamic_Query VARCHAR(MAX) = ''						-- ADDED BY Rashid 20190424
				, @PartNo VARCHAR(50) = ''								-- ADDED BY Rashid 20190424
			
			declare  @TEMP_RoutingConfigLineWise as TABLE
			(
				ProfitCenterCode [varchar](10) NOT NULL,
				[OperationCode] [varchar](10) NOT NULL,
				[LineCode] [varchar](10) NOT NULL,
				[MachineCode] [varchar](10) NOT NULL,
				[OperationRequired] [bit] NULL,
				[Traceability] [bit] NULL,
				[Recipe] [bit] NULL,
				[LabelPrinting] [bit] NULL,
				[Torque] [bit] NULL,
				[POKA_YOKE_ALLOWED] [bit] NULL,
				[Engraving] [bit] NULL,
				[OperationSeqNo] [int] NULL,
				[WIP_Quantity] [int] NULL
			)



		if(@Mode='D')
		begin
			BEGIN TRY
				--TRY BLOCK BEGINS
				select * from (
					SELECT ROW_NUMBER() over(order by  RC.OPERATIONCODE) SNO, UPPER(RC.ProfitCenterCode) ProfitCenterCode,upper(RC.LineCode) LineCode,upper(RC.OPERATIONCODE) OperationCode,upper(O.OperationName) OperationName
							,upper(RC.MachineCode) MachineCode,upper(M.MachineName) MachineName, OperationSeqNo,OperationRequired,Traceability
							,Recipe,LabelPrinting,Torque,POKA_YOKE_ALLOWED,Engraving, RC.WIP_Quantity,M.NoOfStations, RC.ent_by as [ent_by],  RC.ENT_STAMP, RC.last_upd_by as [last_upd_by]
							,RC.last_upd_stamp
							FROM  RoutingConfigLineWise(NOLOCK) RC 			
							join machinemst M on RC.MachineCode=M.MachineCode and RC.ProfitCenterCode=M.ProfitCenterCode 			
							join operationmst O on RC.OPERATIONCODE=O.OPERATIONCODE and RC.ProfitCenterCode=O.ProfitCenterCode  
						WHERE RC.ProfitCenterCode =@ProfitCenterCode	AND RC.lineCode=@LineCode
						)a ORDER BY ProfitCenterCode,OperationSeqNo, OPERATIONCODE
					set @ReturnValue='DATA SELECTED'
					set @ReturnInt=1
				--TRY BLOCK END
			END TRY
			begin catch
				--CATCH BLOCK BEGINS
					SET @ReturnValue =	CAST(ERROR_NUMBER() as varchar(5)) + '|' + 
					CAST(ERROR_SEVERITY()as varchar(5)) + '|' + 
					CAST(ERROR_STATE() as varchar(5)) + '|' + 
					CAST(ERROR_PROCEDURE() as varchar(200)) + '|' + 
					CAST(ERROR_LINE() as varchar(5)) + '|' + 
					CAST(ERROR_MESSAGE() as varchar(1500))							
					SET @ReturnInt = 2	
				--CATCH BLOCK ENDS 
			end catch
		end

		else if (@Mode='S')
		begin			
			BEGIN TRY--TRY BLOCK BEGINS
				create table #TBLValidate(MachineCode varchar(10));

					select * into #TBLRouting from @TBLRoutingLine;

					 insert into  #TBLValidate select #TBLRouting.NewMachineCode from #TBLRouting,MachineMst
					--where #TBLRouting.NewMachineCode=MachineMst.MachineCode and MachineMst.isActive=1;
					--select @countUpdate= count(*) from #TBLRouting;
					--select @countMaster=count(*) from #TBLValidate;
					--if(@countUpdate=@countMaster)
					where #TBLRouting.MachineCode=MachineMst.MachineCode  and  #TBLRouting.NewMachineCode not in (select MachineCode from MachineMst where isActive=1)  and #TBLRouting.ProfitCenterCode=MachineMst.ProfitCenterCode;
					--select @countUpdate= count(*) from #TBLRouting;
					select @countMaster=count(*) from #TBLValidate where MachineCode is not NULL;
					select * from #TBLValidate;
					select * from #TBLRouting; 
					if(@countMaster=0)
					begin
					BEGIN TRAN--TRY TRAN BEGINS

						-- ADDED BY Ravi ON 21/09/2015 FOR TALLY CHART BYPASS FUNCTIONALITY
						INSERT INTO @TEMP_RoutingConfigLineWise
						(	ProfitCenterCode,OperationCode,LineCode,MachineCode,OperationRequired,Traceability,
							Recipe,LabelPrinting,Torque,POKA_YOKE_ALLOWED,Engraving,OperationSeqNo,WIP_Quantity
						)
						SELECT ProfitCenterCode,OperationCode,LineCode,MachineCode,OperationRequired,Traceability,
							Recipe,LabelPrinting,Torque,POKA_YOKE_ALLOWED,Engraving,OperationSeqNo,WIP_Quantity
							FROM RoutingConfigLineWise with(nolock) WHERE LineCode=@LineCode and ProfitCenterCode=@ProfitCenterCode					

							update RoutingConfigLineWise   
							set RoutingConfigLineWise.MachineCode= case when #TBLRouting.NewMachineCode <>'' then #TBLRouting.NewMachineCode
																else #TBLRouting.MachineCode end,
								RoutingConfigLineWise.OperationRequired= #TBLRouting.OperationRequired,
								RoutingConfigLineWise.Traceability= #TBLRouting.Traceability,
								RoutingConfigLineWise.Recipe= #TBLRouting.Recipe,
								RoutingConfigLineWise.LabelPrinting= #TBLRouting.LabelPrinting,
								RoutingConfigLineWise.Torque= #TBLRouting.Torque,
								RoutingConfigLineWise.Engraving=#TBLRouting.Engraving,
								RoutingConfigLineWise.POKA_YOKE_ALLOWED= #TBLRouting.POKA_YOKE_ALLOWED,
								RoutingConfigLineWise.OperationSeqNo= #TBLRouting.OperationSeqNo,
								RoutingConfigLineWise.WIP_Quantity=#TBLRouting.WIP_Quantity
							from RoutingConfigLineWise,#TBLRouting
							where RoutingConfigLineWise.ProfitCenterCode=#TBLRouting.ProfitCenterCode and RoutingConfigLineWise.OperationCode=#TBLRouting.OperationCode
								and RoutingConfigLineWise.LineCode=#TBLRouting.LineCode	and RoutingConfigLineWise.MachineCode=#TBLRouting.MachineCode 

						if @ISLocal=1
						begin
								if 
								( 
								  (select dbo.Assy_FN_IS_Barcode_Printed_For_RunningPart(@Linecode,@ProfitCenterCode))>0
								)
								BEGIN
											-- CHECK IF ROUTING CHANGED OR NOT
											IF EXISTS
											(
												SELECT 1 FROM RoutingConfigLineWise A with (nolock) INNER JOIN @TEMP_RoutingConfigLineWise B
												ON A.LineCode=B.LineCode AND A.ProfitCenterCode=B.ProfitCenterCode
												AND A.OperationCode=B.OperationCode AND A.MachineCode=B.MachineCode
												WHERE A.LineCode=@LineCode
												AND 
												(
													isnull(A.OperationRequired,0)<>isnull(B.OperationRequired,0) OR 
													isnull(A.Traceability,0)<>isnull(B.Traceability,0)								
												)
											)
											BEGIN							
													exec Assy_Proc_Routing_Changed_Dtl @CONDITION='UPDATE',@ProfitCenterCode=@ProfitCenterCode,@LineCode=@LineCode
											END
								END
						end	
													
				--print 'ok'
				declare @ReturnValue1 VARCHAR (2000)
				declare @ReturnInt1 INT
							
				 
				COMMIT TRAN--TRY TRAN END	

				IF @IsLocal =  1
				BEGIN
					IF EXISTS
					(
						SELECT TOP 1 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
							AND LineCode = @LineCode AND KeyType = 'IsPushMasterDataIntoMESServerOnSetParameter' AND ISNULL(KeyValue,'0') = '1'
					)
					BEGIN
						SELECT TOP 1 @MachineLinkServerName = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode 
							AND LineCode = @LineCode AND KeyType = 'MachineDBLinkServerName' AND STS_CD = 0
				
						IF(ISNULL(@MachineLinkServerName,'') = '' )
						BEGIN
							SET @ReturnValue = 'Machine Link Server Name Configuration Not Found !! [RoutingConfigDetails Key: MachineDBLinkServerName] '
							SET @ReturnInt = 2
							RETURN
						END

						SELECT TOP 1 @MachineLinkServerDB = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
							AND LineCode = @LineCode AND KeyType = 'MachineDBLinkServerDB' AND STS_CD = 0

						IF(ISNULL(@MachineLinkServerDB,'') = '' )
						BEGIN
							SET @ReturnValue = 'Machine Link Server Database Configuration Not Found !! [RoutingConfigDetails Key: MachineDBLinkServerDB]'
							SET @ReturnInt = 2
							RETURN
						END

						SELECT TOP 1 @MachineDBRoutingLineWiseTableName = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
							AND LineCode = @LineCode AND KeyType = 'MachineDBRoutingLineWiseTableName' AND STS_CD = 0

						IF(ISNULL(@MachineDBRoutingLineWiseTableName,'') = '' )
						BEGIN
							SET @ReturnValue = 'Link Server Routing Line Wise Table Configuration Not Found !! [RoutingConfigDetails Key: MachineDBRoutingLineWiseTableName] '
							SET @ReturnInt = 2
							RETURN
						END

						SELECT TOP 1 @LinkServerType = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
							AND LineCode = @LineCode AND KeyType = 'LinkServerType' AND STS_CD = 0

						IF(ISNULL(@LinkServerType,'') = '' )
						BEGIN
							SET @ReturnValue = 'Link Server Type Parameter Configuration Not Found !! [RoutingConfigDetails Key: LinkServerType] '
							SET @ReturnInt = 2
							RETURN
						END

						BEGIN TRY
							Declare @s sysname = REPLACE(REPLACE(@MachineLinkServerName,'[',''),']','')
							EXEC sys.sp_testlinkedserver @s
						END TRY
						BEGIN CATCH
							SET @ReturnValue = 'Kindly Check, Not Able To Connect MES SQL Server !!! ' + @MachineLinkServerName
							SET @ReturnInt = 2
							RETURN
						END CATCH

						IF(@LinkServerType = 'MSSQL')
						BEGIN
							SET @MachineLinkServer = @MachineLinkServerName + '.' + @MachineLinkServerDB
							SET @MachineLinkServer = REPLACE(@MachineLinkServer,'TABLE_NAME',@MachineDBRoutingLineWiseTableName)
							PRINT 'RoutingConfigLineWise - LinkServer - ' + @MachineLinkServer

							EXEC Assy_Proc_PushMasterDataIntoMES @MachineLinkServer = @MachineLinkServer, @ProfitCenterCode = @ProfitCenterCode, @LineCode = @LineCode,
								@Condition = 'RoutingConfigLineWise'
						END

						IF(@LinkServerType = 'MYSQL')
						BEGIN
							PRINT 'MYSQL Connection Code Required'
						END
					END
				END

				set @ReturnValue='DATA SAVED'
				set @ReturnInt=1	
				End
				else
				Begin
				--print 'not ok'
				set @invalidMachineCode = (select top 1 MachineCode #TBLValidate from #TBLValidate)
				set @ReturnValue='INVALID MACHINE CODE:'+@invalidMachineCode
				set @ReturnInt=4	
				END
			END TRY--TRY BLOCK END
			begin catch	--CATCH BLOCK BEGINS
					SET @ReturnValue =	CAST(ERROR_NUMBER() as varchar(5)) + '|' + 
					CAST(ERROR_SEVERITY()as varchar(5)) + '|' + 
					CAST(ERROR_STATE() as varchar(5)) + '|' + 
					CAST(ERROR_PROCEDURE() as varchar(200)) + '|' + 
					CAST(ERROR_LINE() as varchar(5)) + '|' + 
					CAST(ERROR_MESSAGE() as varchar(1500))							
					SET @ReturnInt = 2	
					ROLLBACK TRAN	--ROLLBACK TRANSACTION		
					raiserror(@ReturnValue,16,1)
							
			end catch--CATCH BLOCK ENDS 
		end
		
		
		else if(@Mode='F')
		begin
		if @OperationCode='' and @OperationName='' and @MachineCode='' and @WIPQty='' 
		begin
		 set @ReturnValue='NO DATA FOUND'
		  set @ReturnInt=0
		end
		begin
	 SELECT ROW_NUMBER() over(order by  RC.OPERATIONCODE) SNO, UPPER(RC.ProfitCenterCode) ProfitCenterCode,upper(RC.LineCode) LineCode,upper(RC.OPERATIONCODE) OperationCode,upper(O.OperationName) OperationName
							,upper(RC.MachineCode) MachineCode,upper(M.MachineName) MachineName, OperationSeqNo,OperationRequired,Traceability
							,Recipe,LabelPrinting,Torque,POKA_YOKE_ALLOWED,Engraving,RC.WIP_Quantity,M.NoOfStations, RC.ent_by as [ent_by],  RC.ENT_STAMP, RC.last_upd_by as [last_upd_by]
							,RC.last_upd_stamp
							FROM  RoutingConfigLineWise(NOLOCK) RC 			
							join machinemst M on RC.MachineCode=M.MachineCode and RC.ProfitCenterCode=M.ProfitCenterCode 			
							join operationmst O on RC.OPERATIONCODE=O.OPERATIONCODE and RC.ProfitCenterCode=O.ProfitCenterCode  
						WHERE RC.ProfitCenterCode =@ProfitCenterCode	AND RC.lineCode=@LineCode 		 
						and RC.OperationCode like '%'+@OperationCode+'%' and O.OperationName like '%'+@OperationName+'%' AND Rc.MachineCode Like'%'+@MachineCode+'%' ORDER BY RC.ProfitCenterCode, RC.OPERATIONCODE
		  set @ReturnValue='DATA SEARCHED'
		  set @ReturnInt=1
	     
	 end
  end
end



GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_RunningPart_Type]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[Assy_Proc_RunningPart_Type]
(
@Condition varchar(50),
@ProfitCenterCode varchar(20)='0021',
@LineCode varchar(20),
@PartNo varchar(60)=NULL,
@PartType varchar(20)=NULL,
@UserId varchar(20)=NULL
)
as
begin
--Author:<Ravishankar Mishra>
--Created date:<11-07-2015>
--exec Assy_Proc_RunningPart_Type @Condition='insert',@ProfitCenterCode='0021',@LineCode='S04'
--select * from Assy_RunningPart_Type
--select * from Assy_RunningPart
			SET NOCOUNT ON
			if @Condition='INSERT'
			begin
					delete from Assy_RunningPart_Type where ProfitCenterCode=@ProfitCenterCode and LineCode =@LineCode
					insert into Assy_RunningPart_Type
					(
					ProfitCenterCode,
					LineCode,
					PartNo,
					PartType,
					CreatedDate,
					CreatedBy
					)
					select @ProfitCenterCode,RP.linecode,rp.Assy_PartNo ,PM.MATERIAL_TP as PartType,getdate(),RP.CreatedBy from Assy_RunningPart(nolock) RP 
					inner join product_master PM on rp.Assy_PartNo=pm.SEWS_PART_NO  
					where RP.LineCode=@LineCode and PM.warehouse_cd=@ProfitCenterCode
					return
			end
end


