/****** Object:  StoredProcedure [dbo].[Assy_Proc_Scan_OK_RFID]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[Assy_Proc_Scan_OK_RFID]
(
@CONDITION VARCHAR(60),
@PROFITCENTERCODE VARCHAR(10),
@LINECODE VARCHAR(10),
@MACHINECODE VARCHAR(20)=null,
@OPERATIONCODE VARCHAR(20)=NULL,
@STATIONCODE VARCHAR(5)=NULL,
@BARCODE VARCHAR(100)=NULL,
@RETURNVALUE VARCHAR (2000) = NULL OUT,
@RETURNINT INT=NULL OUT
)
AS
BEGIN	
			-- AUTHOR:		<RAVISHANKAR MISHRA>
			-- CREATE DATE: < 25/05/2016>	

			-- TO REMBEMBER
			-- NOTHING = 0
			-- SUCCESS = 1
			-- ERROR = 2
			-- ALREADYEXISTS = 3
			-- NOTEXISTS = 4

			--EXEC ASSY_PROC_SCAN_OK_RFID @CONDITION='UPDATE',@PROFITCENTERCODE='0088',@LINECODE='J04',@MACHINECODE='MC4S'
			--,@OPERATIONCODE='0C42',@STATIONCODE='1',@BARCODE='BAR1234'

			--EXEC ASSY_PROC_SCAN_OK_RFID @CONDITION='SELECT',@PROFITCENTERCODE='0088',@LINECODE='J04',@MACHINECODE='MC4S'
			--,@OPERATIONCODE='0C41'		

			--EXEC ASSY_PROC_SCAN_OK_RFID @CONDITION='INSERT_ROTARY_DATA',@PROFITCENTERCODE='0088',@LINECODE='J04',@MACHINECODE='MC4S'
			--,@OPERATIONCODE='0C41',@BARCODE='BAR1'	

			--SELECT * FROM Assy_LineAssyStatus_Running 
			--SELECT * FROM ASSY_SCAN_OK_RFID		

			SET NOCOUNT ON
			IF @CONDITION='SELECT'
			BEGIN				
					SELECT MACHINECODE,OPERATIONCODE,ISNULL(BARCODE,'')BARCODE,StationCode FROM ASSY_SCAN_OK_RFID WITH (NOLOCK) 
					WHERE PROFITCENTERCODE=@PROFITCENTERCODE 
					AND LINECODE=@LINECODE  AND ISNULL(ISSCAN,0)=1
					
					set @RETURNINT=1
					RETURN
			END
			ELSE IF @CONDITION='UPDATE'
			BEGIN	
					IF EXISTS
					(	
						SELECT 1 FROM  ASSY_SCAN_OK_RFID WITH (NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE 
						AND LINECODE=@LINECODE	AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE 
					)			
					BEGIN
							UPDATE ASSY_SCAN_OK_RFID SET BARCODE=@BARCODE ,ISSCAN=1,TIMESTAMP=GETDATE() WHERE PROFITCENTERCODE=@PROFITCENTERCODE 
							AND LINECODE=@LINECODE	AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE 
					END
					ELSE
						BEGIN
								INSERT INTO ASSY_SCAN_OK_RFID
								(
									PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE
									,STATIONCODE,BARCODE,ISSCAN,TIMESTAMP
								)
								SELECT @PROFITCENTERCODE,@LINECODE,@MACHINECODE,@OPERATIONCODE
								,@STATIONCODE,@BARCODE,1,GETDATE()
						END
				
					set @RETURNINT=1
					RETURN
			END
			ELSE IF @CONDITION='RESET_SCANOK'
			BEGIN						
					UPDATE ASSY_SCAN_OK_RFID SET ISSCAN=0 WHERE PROFITCENTERCODE=@PROFITCENTERCODE 
					AND LINECODE=@LINECODE	AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE 
									
					set @RETURNINT=1
					RETURN
			END

			ELSE IF @CONDITION='INSERT_ROTARY_DATA'
			BEGIN						

					UPDATE ASSY_SCAN_OK_RFID SET ISSCAN=0 WHERE PROFITCENTERCODE=@PROFITCENTERCODE 
					AND LINECODE=@LINECODE	AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE 
									
					insert into Assy_LineAssyStatus_Running 
					(
						ProfitCenterCode,LineCode,MachineCode,OperationCode,StationCode,
						Barcode,Status,FailCount,Active,ResultTimestamp,
						ScanTimestamp,IsTallyChartApproved,IsReworkPart
						,Datecode,PartNo,UserID				
					)

					select TOP 1 @PROFITCENTERCODE,@LINECODE,@MACHINECODE,@OPERATIONCODE ,(case when @STATIONCODE is null then '1' end)STATIONCODE,
					@BARCODE, NULL,0,1, NULL,
					GETDATE(),0,0  
					,Datecode,Assy_PartNo,CreatedBy
					from Assy_RunningPart  with (nolock) where ProfitCenterCode=@PROFITCENTERCODE 
					aND LineCode =@LINECODE ORDER BY CreatedDate DESC

					set @RETURNINT=1
					RETURN
			END
			else if @CONDITION='GET_ID_Generation_Machinecode'
			begin
						SELECT TOP 1 @RETURNVALUE=MACHINECODE FROM ROUTINGCONFIGLINEWISE WITH (NOLOCK)
					     WHERE   PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND OPERATIONSEQNO =1 					
						SET @RETURNINT=1
						RETURN
			end

END


GO
