/****** Object:  StoredProcedure [dbo].[Assy_Proc_Send_Mail]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[Assy_Proc_Send_Mail]
(
@CONDITION VARCHAR(50),
@ProfitCenterCode varchar(10)='0021',
@ReturnValue VARCHAR (2000)=NULL OUT,
@ReturnInt INT=NULL OUT
)
as
begin
		--Author:<Ravishankar Mishra>
		--Created date:<26/05/2015>
		--exec Assy_Proc_Send_Mail @CONDITION='Manual_Printed_Barcode',@ProfitCenterCode='0021'
		--select * from Assy_Manual_Printed_Barcode_Dtl
		SET NOCOUNT ON
		declare @WEB_TO_EMAILID nvarchar(max), @WEB_CC_EMAILID nvarchar(1000),@MESSAGE NVARCHAR(max),@SUBJECT NVARCHAR(1000),@MessageHeading varchar(500)

		if  @CONDITION='Manual_Printed_Barcode'
		BEGIN
				select @WEB_TO_EMAILID=dbo.ASSY_FN_GET_PARAMETER_VALUE('assline','ManualLabelPrinting','MAIL_ALERT_LIST_TO',@ProfitCenterCode)
				--select @WEB_TO_EMAILID='manoj.kumar@mind-infotech.com;ravi.mishra@mind-infotech.com'
				select @WEB_CC_EMAILID=dbo.ASSY_FN_GET_PARAMETER_VALUE('assline','ManualLabelPrinting','TS_MAIL_ALERT_LIST_CC',@ProfitCenterCode)
				--select @WEB_TO_EMAILID,@WEB_CC_EMAILID
				set @MESSAGE =''									
				set @SUBJECT ='Manual Barcode Printing on Assembly Line'								
				set @MessageHeading='Line Code|Line Name'+space(4)+'|Date Code|Part No.|Labels Printed|From Serial No.|To Serial No.|User Id'
				+space(3)+'|Date Time'+space(10)+'|Remarks'+char(10)+char(13)
				set @MESSAGE=@MessageHeading
				select @MESSAGE=isnull(@MESSAGE,'')+mlp.LineCode +space(6)+'|' +LM.LineName+space(3)+'|'+datecode+space(5)+'|'
				+partno+'|'+replicate('0', 2 - len(convert(varchar(10),NoOfPrintedLbl)))+convert(varchar(10),NoOfPrintedLbl)+space(12)+'|'+FromSerialNo+space(7)
				+'|'+ToSerialNo+space(5)+'|'+replicate(' ', 10 - len(UserID))  + UserID+'|'+convert(varchar,Timestamp,120)+'|'+Reason+char(10)+ char(13)   
				from Assy_Manual_Printed_Barcode_Dtl(nolock) MLP
				inner join LineMst(Nolock)LM on MLP.LineCode =LM.LineCode  
				where isnull(IsMailSent,0)=0 
				--order by LM.LineCode
				print @MESSAGE
								
				IF exists (select 1 from Assy_Manual_Printed_Barcode_Dtl(nolock) where ProfitCenterCode =@ProfitCenterCode and isnull(IsMailSent,0 )=0)
				begin
					EXEC PROC_SEND_MAIL @WEB_TO_EMAILID, '', @MESSAGE, @SUBJECT, @WEB_CC_EMAILID
					update Assy_Manual_Printed_Barcode_Dtl set IsMailSent=1 where ProfitCenterCode =@ProfitCenterCode and isnull(IsMailSent,0 )=0
				end


									


									
		END

end
GO
/****** Object:  StoredProcedure [dbo].[Assy_PROC_ServoPerformance]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE proc [dbo].[Assy_PROC_ServoPerformance] 
(
@CONDITION VARCHAR(50),
@ProfitCenterCode varchar(20)=null,
@LineCode varchar(20)=null,
@OperationCode varchar(20)=null,
@FG_PART_NO VARCHAR(20) = NULL,
@CHILD_PART_NO VARCHAR(20) = NULL,
@MachineCode varchar(20)=null,
@StationCode varchar(20)='1',
@DateCode varchar(4)=null,
@PartNumber varchar(20)=null,
@Barcode varchar(35)=null,
@Prefix char(2)=null,
@Suffix char(2)=null,
@ReturnValue VARCHAR (2000)=NULL OUT,
@ReturnInt INT=NULL OUT,
@UserId varchar(50)=NULL,
@HMI_MESSAGE VARCHAR(100)=NULL,
@PARAM_CODE VARCHAR(50) = NULL,
@PARAM_VALUE NUMERIC(7,2) = NULL
)
AS
BEGIN

-- Author:		<Manoj Kumar>
-- Create date: < 13 Jan 2015>
-- Description:	<Coupling.>

-- To Rembember
-- Nothing = 0
-- Success = 1
-- Error = 2
-- AlreadyExists = 3
-- NotExists = 4

/*
select * from Assy_Stations_Zig_In_Out_Status
exec [Assy_PROC_FinalViewing] @CONDITION='GET_TAGS',@LineCode='m07' ,@OperationCode='ocFV'
*/
--update  Assy_Stations_Zig_In_Out_Status set StatusInOut=1

BEGIN TRY
        Declare @MinValue numeric (7,2) = null;
        Declare @MaxValue numeric (7,2) = null;
        Declare @Line_Code_Of_Barcode varchar(5) = '';
        Declare @Torque_1 numeric(10, 5) = 0;
        Declare @Torque_2 numeric (10, 5) = 0;
        Declare @IsTorque1OK bit;
        Declare @IsTorque2OK bit;
        Declare @Part_Type varchar(10) = ''
        Declare @failCountDefined int=0
		declare @failCount int=0
		Declare @TempScannedPartType varchar(15)
		Declare @TempRunningPartType varchar(15)
		Declare @TempOperationType varchar(20),@LineTypeCode varchar(20)=''
		Declare @FinalViewing_OperationCode varchar(10)
		declare @OperationSeqNo int,@OperationName varchar(50)

		
		select @FinalViewing_OperationCode=rtrim(ltrim( PARAMETER_VALUE))  from PARAMETER_MST(nolock) 
		where PARAMETER_C ='assline' and PARAMETER_C1 ='FinalViewing' 
		and PARAMETER_C2 ='QCStation_OperationCode' and wh_code=@ProfitCenterCode 

		SET NOCOUNT ON
		
		IF @CONDITION = 'GET_INSIDE_ZIG_NAME'
		Begin
	        
			SET @ReturnValue = (select StationCode from Assy_Stations_Zig_In_Out_Status WHERE StatusInOut = 1
			and LineCode = @LineCode and OperationCode = @OperationCode)
			
		End
		
		IF @CONDITION = 'UPDATE_INCORRECT_LABEL'
		Begin
		  select * from Assy_incorrectLabel
		  update Assy_incorrectLabel set HMIMessageCode = @HMI_MESSAGE, isIncorrect = 1 WHERE LineCode = @LineCode
		  and OperationCode = @OperationCode and StationCode = @StationCode
		End
		IF @CONDITION = 'IS_SERVO_SCANNED'
		Begin
		  IF EXISTS 
		  (
			SELECT TOP 1 1 FROM Assy_Coupling_Temp WHERE PART_TYPE = 'Servo' and STMC_PART_NO = @FG_PART_NO
		  )
		  Begin
		    set @ReturnValue = 'SERVO_ALREADY_SCANNED'
		    RETURN;
		  End
		   SET @ReturnValue = 'SUCCESS'
		End
		-- select * from MachineMst
		--select * from OperationMst
		--EXEC [Assy_PROC_Coupling] @CONDITION = 'VALIDATE_SERVO' @FG_PART_NO = '29049654' @CHILD_PART_NO = '29049655'
		--@ProfitCenterCode = '0021' @MachineCode = 'MCCP-BRCD1' @OperationCode = 'OCCOUP', @Barcode =  '2904965543Ta09090909S01'
		--@LineCode = 'S01'
		--
		
		IF @CONDITION = 'CHECK_VALUE_LIMIT'
		Begin
		 --Check if IsActive flag is 1. If Yes validate if it is between min max ranges else return OK
		 IF((SELECT ISACTIVE FROM Assy_parametermst WHERE ParameterCode = @PARAM_CODE and PartNo = @CHILD_PART_NO) = 1)
		 Begin
		   select @MinValue =  MinValue, @MaxValue = MaxValue from Assy_parametermst WHERE ParameterCode = @PARAM_CODE and PartNo = @CHILD_PART_NO
		   IF((@PARAM_VALUE >= @MinValue) AND (@PARAM_VALUE <= @MaxValue))
		   Begin
		     set @ReturnInt = 1
		   End
		   else
		   Begin
		      set @ReturnInt = 2
		   end
		 End
		 else
		 Begin
		   set @ReturnInt = 1
		 end
		End
		IF @CONDITION = 'VALIDATE_SERVO'
		Begin
		  IF NOT EXISTS (SELECT TOP 1 1 FROM BOM_MASTER WHERE FG_PART_NO = @FG_PART_NO AND RM_PART_NO = @CHILD_PART_NO)
		  Begin
		     set @ReturnValue= 'INVALID_CHILD_PART_AGAINST_FG'
		     RETURN
		  End
		  
		  --Check if part is a valid servo type..
		  set @Part_Type = (SELECT pt_part_type FROM PRODUCT_MASTER WHERE SEWS_PART_NO = @CHILD_PART_NO)
		  
		  if(@Part_Type <> 'Servo')
		  Begin
		     set @ReturnValue = 'PART_IS_NOT_SERVO'
		     RETURN
		  End
		  
		  --Check if the record is not there in SCAN OK..
		  IF EXISTS (SELECT Barcode from Assy_Scan_OK where Barcode = @Barcode and MachineCode = @MachineCode)
		  Begin
		   set @ReturnValue = 'PART_ALREADY_SCANNED'
		     RETURN
		  end
		  
		  --Get the line code from the barcode..
		  set @Line_Code_Of_Barcode = (select SUBSTRING(@Barcode, (Len(@Barcode) - 2), 3))
		  --Check if the servo part has been passed from previous stations..
		  IF not exists (SELECT top 1 1 FROM Assy_LineAssyStatus_Running WHERE LineCode = @Line_Code_Of_Barcode
		   AND Barcode = @Barcode and STATUS = 'PS')
           Begin
             set @ReturnValue = 'PART_IS_NOT_PASSED_FROM_PREVIOUS_STATIONS'
             RETURN	
           End
		  
		 			IF NOT EXISTS
					(
						select distinct 1 from product_master(nolock) where warehouse_cd=@ProfitCenterCode and SEWS_PART_NO =@CHILD_PART_NO and STS_CD =0  and pt_part_type=
						(select LT.LineTypeName from LineTypeMst(nolock) LT inner join LineMst(nolock) LM on LT.LineTypeCode =LM.LineTypeCode where LM.LineCode=@LineCode) 
					)
					begin
								--SELECT 'PART_NOT_ACTIVE_IN_PRODUCT_MASTER'
						SET @RETURNINT=1
						SET @RETURNVALUE='PART_NOT_ACTIVE_IN_PRODUCT_MASTER'

						--update incorrect label
						if @OperationCode <>@FinalViewing_OperationCode
						begin
								exec Assy_proc_IncorrectLabel_Manage @CONDITION='update',@LineCode=@LINECODE,@OperationCode=@OPERATIONCODE
								,@BARCODE=@Barcode,@HMIMEssage='PART_NOT_ACTIVE_IN_PRODUCT_MASTER'
						end
						COMMIT TRAN
						RETURN
					end
                --Check part has already scraped in tally  chart
				   IF EXISTS
				   ( 
				      select top 1 1 from Assy_TallyChartStatusData(nolock) where barcode=@Barcode and isnull(Assy_Auth,0)=1 
					  and LineCode =@LineCode and ProfitCenterCode=@ProfitCenterCode
				   )
				   begin
				   
				   SET @RETURNINT=1
				   SET @RETURNVALUE='PART_HAS_ALREADY_PROCESSED_IN_TALLYCHART'
				   COMMIT TRAN
				RETURN
				End	
				
		
		--This servo part should not be coupled with any other STMC part..
		
		IF EXISTS
		(
			select TOP 1 1 from Assy_CouplingDetails where CHILD_PART_NO = @CHILD_PART_NO
		) 
		Begin
		   SET @RETURNVALUE='PART_HAS_ALREADY_BEEN_COUPLED'
		   RETURN
		End 
		
		 SET @RETURNVALUE='success' 
		 --since status is Success insert a record in Assy_Scan_OK Table.
		 insert into Assy_Scan_OK(linecode,machinecode,operationcode,stationcode,barcode,isScan) values (@LineCode, @MachineCode, @OperationCode, @StationCode, @Barcode, 1)
		 
		 --Hold a record in temp table..
		 insert into Assy_Coupling_Temp(ProfitCentreCode, LineCode, STMC_PART_NO, CHILD_PART_NO, PART_TYPE,
		 MACHINE_CODE, OPERATION_CODE, ENT_DT) VALUES 
		 (@ProfitCenterCode, @LineCode, @FG_PART_NO, @CHILD_PART_NO, 'Servo', @MachineCode, @OperationCode, GETDATE())
		End
		
		
		
		
		IF @CONDITION = 'VALIDATE_TMC'
		Begin
		  IF NOT EXISTS (SELECT TOP 1 1 FROM BOM_MASTER WHERE FG_PART_NO = @FG_PART_NO AND RM_PART_NO = @CHILD_PART_NO)
		  Begin
		     set @ReturnValue= 'INVALID_CHILD_PART_AGAINST_FG'
		     RETURN
		  End
		  
		  --Check if part is a valid servo type..
		  set @Part_Type = (SELECT pt_part_type FROM PRODUCT_MASTER WHERE SEWS_PART_NO = @CHILD_PART_NO)
		  
		  if(@Part_Type <> 'TMC')
		  Begin
		     set @ReturnValue = 'PART_IS_NOT_TMC'
		     RETURN
		  End
		  
		  --Check if the record is not there in SCAN OK..
		  IF EXISTS (SELECT Barcode from Assy_Scan_OK where Barcode = @Barcode and MachineCode = @MachineCode)
		  Begin
		   set @ReturnValue = 'PART_ALREADY_SCANNED'
		     RETURN
		  end
		  
		  --Get the line code from the barcode..
		  set @Line_Code_Of_Barcode = (select SUBSTRING(@Barcode, (Len(@Barcode) - 2), 3))
		  --Check if the servo part has been passed from previous stations..
		  IF not exists (SELECT top 1 1 FROM Assy_LineAssyStatus_Running WHERE LineCode = @Line_Code_Of_Barcode
		   AND Barcode = @Barcode and STATUS = 'PS')
           Begin
             set @ReturnValue = 'PART_IS_NOT_PASSED_FROM_PREVIOUS_STATIONS'
             RETURN	
           End
		  
		 			IF NOT EXISTS
					(
						select distinct 1 from product_master(nolock) where warehouse_cd=@ProfitCenterCode and SEWS_PART_NO =@CHILD_PART_NO and STS_CD =0  and pt_part_type=
						(select LT.LineTypeName from LineTypeMst(nolock) LT inner join LineMst(nolock) LM on LT.LineTypeCode =LM.LineTypeCode where LM.LineCode=@LineCode) 
					)
					begin
								--SELECT 'PART_NOT_ACTIVE_IN_PRODUCT_MASTER'
						SET @RETURNINT=1
						SET @RETURNVALUE='PART_NOT_ACTIVE_IN_PRODUCT_MASTER'

						--update incorrect label
						if @OperationCode <>@FinalViewing_OperationCode
						begin
								exec Assy_proc_IncorrectLabel_Manage @CONDITION='update',@LineCode=@LINECODE,@OperationCode=@OPERATIONCODE
								,@BARCODE=@Barcode,@HMIMEssage='PART_NOT_ACTIVE_IN_PRODUCT_MASTER'
						end
						COMMIT TRAN
						RETURN
					end
                --Check part has already scraped in tally  chart
				   IF EXISTS
				   ( 
				      select top 1 1 from Assy_TallyChartStatusData(nolock) where barcode=@Barcode and isnull(Assy_Auth,0)=1 
					  and LineCode =@LineCode and ProfitCenterCode=@ProfitCenterCode
				   )
				   begin
				   
				   SET @RETURNINT=1
				   SET @RETURNVALUE='PART_HAS_ALREADY_PROCESSED_IN_TALLYCHART'
				   COMMIT TRAN
				RETURN
				End	
				
		
		--This servo part should not be coupled with any other STMC part..
		
		IF EXISTS
		(
			select TOP 1 1 from Assy_CouplingDetails where CHILD_PART_NO = @CHILD_PART_NO
		) 
		Begin
		   SET @RETURNVALUE='PART_HAS_ALREADY_BEEN_COUPLED'
		   RETURN
		End 
		
		--Need to check if torque has to be measured for this TMC Part..
		IF  ((select Torque from RoutingConfigPartWise where PartNo = @CHILD_PART_NO and OperationCode = @OperationCode) = 1)
		Begin
		  --Torque Flag is ON.. Check if the torque has been measured.. If Not, return with message Please measure torque..
		  select @Torque_1 = Torque_1, @Torque_2 = Torque_2, @IsTorque1OK = Is_Torque1_OK,
		  @IsTorque2OK = Is_Torque2_OK  from Assy_CouplingTorqueStatus where LineCode = @LineCode
		  
		  IF(@Torque_1 = 0)
		  Begin
		     SET @ReturnValue = 'WAITING_FOR_TORQUE_1'
		     return
		  End
		  
		  IF(@Torque_2 = 0)
		  Begin
		     SET @ReturnValue = 'WAITING_FOR_TORQUE_2'
		     return
		  End
		  
		  IF(@IsTorque1OK <> 1)
		  Begin
		     SET @ReturnValue = 'TORQUE1_NOT_OK'
		     return
		  End
		  
		  IF(@IsTorque2OK <> 1)
		  Begin
		     SET @ReturnValue = 'TORQUE2_NOT_OK'
		     return
		  End
		End
		
		 SET @RETURNVALUE='success' 
		 --since status is Success insert a record in Assy_Scan_OK Table.
		 insert into Assy_Scan_OK(LineCode,MachineCode,OperationCode,StationCode,Barcode,isScan) values (@LineCode, @MachineCode, @OperationCode, @StationCode, @Barcode, 1)
		 
		 --Hold a record in temp table..
		 insert into Assy_Coupling_Temp(ProfitCentreCode, LineCode, STMC_PART_NO, CHILD_PART_NO, PART_TYPE,
		 MACHINE_CODE, OPERATION_CODE, TORQUE_1, TORQUE_2, ENT_DT) VALUES 
		 (@ProfitCenterCode, @LineCode, @FG_PART_NO, @CHILD_PART_NO, 'TMC', @MachineCode, @OperationCode,
		 @Torque_1, @Torque_2, GETDATE())
		 
		 insert into Assy_CouplingDetails (ProfitCentreCode, LineCode, STMC_PART_NO,
		 CHILD_PART_NO, PART_TYPE, MACHINE_CODE, OPERATION_CODE, TORQUE_1, TORQUE_2, ENT_DT, ENT_BY)
		 
		 --Insert the record in details table from temp table..
		 select ProfitCentreCode, LineCode, STMC_PART_NO,
		 CHILD_PART_NO, PART_TYPE, MACHINE_CODE, OPERATION_CODE, TORQUE_1, TORQUE_2, ENT_DT, ENT_BY from  Assy_Coupling_Temp 
		 where STMC_PART_NO = @FG_PART_NO and LineCode = @LineCode
		 
		 --Delete the record from temp table..
		 delete from Assy_Coupling_Temp where STMC_PART_NO = @FG_PART_NO and LineCode = @LineCode
		 
		 
		End
		
		IF @CONDITION = 'VALIDATE_ENGRAVING'
		Begin
		  IF NOT EXISTS (SELECT TOP 1 1 FROM BOM_MASTER WHERE FG_PART_NO = @FG_PART_NO AND RM_PART_NO = @CHILD_PART_NO)
		  Begin
		     set @ReturnValue= 'INVALID_CHILD_PART_AGAINST_FG'
		     RETURN
		  End
		  
		  --Check if part is a valid servo type..
		  set @Part_Type = (SELECT pt_part_type FROM PRODUCT_MASTER WHERE SEWS_PART_NO = @CHILD_PART_NO)
		  
		  if(@Part_Type <> 'TMC')
		  Begin
		     set @ReturnValue = 'PART_IS_NOT_TMC'
		     RETURN
		  End
		  
		  --Check if the record is not there in SCAN OK..
		  IF EXISTS (SELECT Barcode from Assy_Scan_OK where Barcode = @Barcode and MachineCode = @MachineCode)
		  Begin
		   set @ReturnValue = 'PART_ALREADY_SCANNED'
		     RETURN
		  end
		  
		  --Get the line code from the barcode..
		  set @Line_Code_Of_Barcode = (select SUBSTRING(@Barcode, (Len(@Barcode) - 2), 3))
		  --Check if the servo part has been passed from previous stations..
		  IF not exists (SELECT top 1 1 FROM Assy_LineAssyStatus_Running WHERE LineCode = @Line_Code_Of_Barcode
		   AND Barcode = @Barcode and STATUS <> 'PS')
         Begin
             set @ReturnValue = 'PART_ALREADY_ENGRAVED'
             RETURN	
           End
		  
		 			IF NOT EXISTS
					(
						select distinct 1 from product_master(nolock) where warehouse_cd=@ProfitCenterCode and SEWS_PART_NO =@CHILD_PART_NO and STS_CD =0  and pt_part_type=
						(select LT.LineTypeName from LineTypeMst(nolock) LT inner join LineMst(nolock) LM on LT.LineTypeCode =LM.LineTypeCode where LM.LineCode=@LineCode) 
					)
					begin
								--SELECT 'PART_NOT_ACTIVE_IN_PRODUCT_MASTER'
						SET @RETURNINT=1
						SET @RETURNVALUE='PART_NOT_ACTIVE_IN_PRODUCT_MASTER'

						--update incorrect label
						if @OperationCode <>@FinalViewing_OperationCode
						begin
								exec Assy_proc_IncorrectLabel_Manage @CONDITION='update',@LineCode=@LINECODE,@OperationCode=@OPERATIONCODE
								,@BARCODE=@Barcode,@HMIMEssage='PART_NOT_ACTIVE_IN_PRODUCT_MASTER'
						end
						COMMIT TRAN
						RETURN
					end
                --Check part has already scraped in tally  chart
				   IF EXISTS
				   ( 
				      select top 1 1 from Assy_TallyChartStatusData(nolock) where barcode=@Barcode and isnull(Assy_Auth,0)=1 
					  and LineCode =@LineCode and ProfitCenterCode=@ProfitCenterCode
				   )
				   begin
				   
				   SET @RETURNINT=1
				   SET @RETURNVALUE='PART_HAS_ALREADY_PROCESSED_IN_TALLYCHART'
				   COMMIT TRAN
				RETURN
				End	
				
		
		--This servo part should not be coupled with any other STMC part..
		
		IF EXISTS
		(
			select TOP 1 1 from Assy_CouplingDetails where CHILD_PART_NO = @CHILD_PART_NO
		) 
		Begin
		   SET @RETURNVALUE='PART_HAS_ALREADY_BEEN_COUPLED'
		   RETURN
		End 
		
		 SET @RETURNVALUE='success' 
		 --since status is Success insert a record in Assy_Scan_OK Table.
		 insert into Assy_Scan_OK(LineCode,MachineCode,OperationCode,StationCode,Barcode,isScan) values (@LineCode, @MachineCode, @OperationCode, @StationCode, @Barcode, 1)

		
		End
		
		
		IF @CONDITION = 'IS_JIG_INSIDE'
		Begin
		  IF ((SELECT IS_JIG_IN FROM Assy_JigMovement WHERE PART_CODE = @CHILD_PART_NO AND LineCode = @LineCode AND ProfitCentreCode = @ProfitCenterCode) = 1)
		  Begin
		    set @ReturnValue = 'JIG_INSIDE'
		    RETURN
		  End
		  
		  SET @ReturnValue = 'JIG_OUTSIDE'
		End
	
		
									
					     
END TRY
			BEGIN CATCH
			
			SET @ReturnValue =	CAST(ERROR_NUMBER() as varchar(5)) + '|' + 
			CAST(ERROR_SEVERITY()as varchar(5)) + '|' + 
			CAST(ERROR_STATE() as varchar(5)) + '|' + 
			CAST(ERROR_PROCEDURE() as varchar(200)) + '|' + 
			CAST(ERROR_LINE() as varchar(5)) + '|' + 
			CAST(ERROR_MESSAGE() as varchar(1500))
			
			Rollback tran				
		   SET @ReturnInt = 2
			END CATCH

END





GO
/****** Object:  StoredProcedure [dbo].[Assy_PROC_ShiftMst]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[Assy_PROC_ShiftMst]
( 
	@Current_Time VARCHAR (20), 
	@ProfitCenterCode VARCHAR (20),
	@Current_Shift VARCHAR (10) OUTPUT, 
	@ShiftCode VARCHAR (10) output 
) 
AS 
BEGIN
	/* 
	DECLARE @Time VARCHAR(20), @Current_Shift VARCHAR(10) , @ShiftCode VARCHAR(10) 
	set @Time = LEFT(CONVERT(VARCHAR(20),CONVERT(time,GETDATE())),8)  
	SELECT @Time  

	EXEC Assy_PROC_ShiftMst '22:00:01' ,'0021' ,@Current_Shift OUTPUT,@ShiftCode output  
	SELECT @Current_Shift,@ShiftCode  
	SELECT * FROM ShiftMst   WHERE ProfitCenterCode='0021'
	*/
			    
	SET NOCOUNT ON
	DECLARE @StartShift as CHAR(12) 
	DECLARE @EndShift as CHAR(12)

	IF (@Current_Time = '00:00:00')
		SET @Current_Time = '00:00:01'

	SELECT @StartShift = CONVERT(CHAR(12),FromTime,114), @EndShift = CONVERT(CHAR(12),ToTime,114) FROM ShiftMst (NOLOCK) 
	WHERE ToTime < FromTime AND ProfitCenterCode = @ProfitCenterCode
				
	SELECT @Current_Shift = Shift, @ShiftCode = ShiftCode FROM 
	(
		SELECT RTRIM(ShiftName) Shift, ShiftCode FROM ShiftMst 
		WHERE 
		CONVERT(CHAR(12),@Current_Time,114) >= CONVERT(CHAR(12),FromTime,114) 
		AND CONVERT(CHAR(12),@Current_Time,114) <= CONVERT(CHAR(12),ToTime,114) 
		AND ProfitCenterCode = @ProfitCenterCode
		
		UNION ALL 
					
		SELECT RTRIM(ShiftName) Shift,ShiftCode
		FROM ShiftMst(NOLOCK) 
		WHERE 
		((CONVERT(CHAR(12),@Current_Time,114)) >= '00:00:00:000' AND CONVERT(CHAR(12),@Current_Time,114) <= CONVERT(CHAR(12),@EndShift,114) 
		OR (CONVERT(CHAR(12),@Current_Time,114) > CONVERT(CHAR(12),@StartShift,114) AND CONVERT(CHAR(12),@Current_Time,114) < '24:00:00:000')) 
		AND (CONVERT(CHAR(12),FromTime,114) >= @StartShift AND CONVERT(CHAR(12),ToTime,114) <= @EndShift) 
		AND ProfitCenterCode = @ProfitCenterCode
	) A
END
GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_ShiftQty_Update]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
