CREATE PROC [dbo].[Assy_Proc_ShiftQty_Update]
(
	@Condition varchar(50) = NULL,
	@ProfitCenterCode varchar(20) = NULL,
	@LineCode varchar(20) = NULL,
	@ReturnValue varchar(2000) = NULL OUT,
	@ReturnInt int = NULL OUT,
	@Barcode varchar(100) = NULL,
	@OperationCode varchar(20) = NULL,
	@CurrentDateCode char(4) = NULL,
	@CurrentPartNo varchar(30) = NULL,
	@IsLabelPRTForSelPart bit = 0,
	@ComponentStatus varchar(5) ='' --Added by Aadil on 25012021 for Pass/Fail mode check
)
AS
BEGIN
	/*
	AUTHOR:			<RAVISHANKAR MISHRA>
	CREATE DATE:	<25 NOVEMBER 2014>
	MODIFIED BY:	<Rashid Siddiqui>
	MODIFIED DATE:	<16 March 2016>
	DESCRIPTION:	<Part No Filter Change Logic for Pass/fail Qty in Update Block>
	MODIFIED DATE:	<29 Aug 2019>
	DESCRIPTION:	<Fail Count From Running Table -  Correction>
	MODIFIED BY:	<Mohd Aadil>
	MODIFIED DATE:	<25 Jan 2021>
	DESCRIPTION:	<Pass/Fail Count From Running Table -  Correction>

	EXEC Assy_Proc_ShiftQty_Update @Condition = 'UPDATE',@ProfitCenterCode = '0021',@LineCode = 'M07',@OperationCode = 'OCFV',@Barcode = '2906683552DA00000010M07'
	EXEC Assy_Proc_ShiftQty_Update @Condition = 'SELECT',@ProfitCenterCode = '0021',@CurrentDateCode = '13GB',@LineCode = 'M07'
	EXEC Assy_Proc_ShiftQty_Update @Condition = 'UPDATE_SHIFT_PRODUCE_QTY_IN_MAIN_SERVER',@ProfitCenterCode = '0021',@LineCode = 'M07'
	EXEC Assy_Proc_ShiftQty_Update @Condition = 'UPDATE_PLANNED_QTY',@ProfitCenterCode = '0021',@LineCode = 'M07'


	SELECT * FROM Assy_ShiftWise_PassFail_Count
	SELECT * FROM Assy_PartWise_PassFail_Count
	SELECT * FROM Assy_LineAssyStatus_Running
	SELECT * FROM Assy_RunningPart

	DELETE Assy_ShiftWise_PassFail_Count
	DELETE Assy_PartWise_PassFail_Count 
	*/
	SET NOCOUNT ON;
	DECLARE @FailCount tinyint
	DECLARE @Status char(2)
	DECLARE @PassQty int = 0
	DECLARE @FailQty int = 0
	DECLARE @PartNo varchar(20) = ''
	DECLARE @TotalShiftQty int = 0
	DECLARE @TotalPartWiseQty int = 0
	DECLARE @ProductionOrderNo varchar(30) = NULL
	DECLARE @Assy_DateCode CHAR(4) = '',@Total_Pass_Qty INT = 0,@Total_Fail_Qty INT = 0, @Part_Pass_Qty INT = 0,@Part_Fail_Qty INT = 0,@Part_Running_Fail_Qty INT = 0
	DECLARE @FailBarcodeqty int=0
	DECLARE @SetParameterDate datetime
	DECLARE @CustomerPartNo varchar(30) = ''
	DECLARE @SetParamPlannedQty INT = 0
	DECLARE @Partcategory VARCHAR(10) = ''
 
	IF @Condition = 'UPDATE'
	BEGIN
		-- Commented By Sachin 210402
		-- Part Number & Date Code Should Be Come From Caller Of Procedure
		--SELECT TOP 1
		--	@PartNo = ISNULL(Assy_PartNo,''),
		--	@Assy_DateCode = ISNULL(DateCode,'')
		--FROM Assy_RunningPart (NOLOCK)
		--	WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode Order By CreatedDate Desc
		-- Commented By Sachin 210402

		SET @PartNo  = @CurrentPartNo
		SET @Assy_DateCode  = @CurrentDateCode

		--[Modified] Added by Aadil on 25012021 for Check part already fail or not 
		SELECT ProfitCenterCode,LineCode,DateCode,OperationCode,Status,PartNo,IsTallyChartApproved,Barcode,FailCount INTO #Assy_LineAssyStatus FROM Assy_LineAssyStatus_running (NOLOCK)
			WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND DateCode = @Assy_DateCode AND OperationCode = @OperationCode
		SELECT @Total_Pass_Qty = COUNT(*) FROM #Assy_LineAssyStatus WHERE ISNULL(Status,'') = 'PS'
		SELECT @Total_Fail_Qty = COUNT(*) FROM #Assy_LineAssyStatus WHERE ISNULL(Status,'') = 'FL'
		SELECT @Part_Pass_Qty = COUNT(*) FROM #Assy_LineAssyStatus WHERE PartNo = @PartNo AND ISNULL(Status,'') = 'PS' --AND ISNULL(IsTallyChartApproved,0) = 0 commented by Sachin 16July20
		SELECT @Part_Fail_Qty = COUNT(*) FROM #Assy_LineAssyStatus WHERE PartNo = @PartNo AND ISNULL(Status,'') = 'FL' AND barcode=@barcode AND FailCount>1   --AND ISNULL(IsTallyChartApproved,0) = 0 commented by Sachin 16July20		
		SELECT @Part_Running_Fail_Qty = COUNT(*) FROM Assy_LineAssyStatus_Running (NOLOCK)
			WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND DateCode = @Assy_DateCode AND OperationCode = @OperationCode
				AND PartNo = @PartNo AND ISNULL(Status,'') = 'FL'
		
		SELECT @FailBarcodeqty = COUNT(*) FROM #Assy_LineAssyStatus WHERE PartNo = @PartNo  AND barcode=@barcode AND FailCount>0
		--[Start] Added by Aadil on 25012021 for Check part already fail or not 
		IF (@ComponentStatus='FAIL')
		BEGIN
			SET @FailBarcodeqty=0
			IF(@Part_Fail_Qty>0)
				SET @Part_Fail_Qty=0
			ELSE
				SET @Part_Fail_Qty=1
		END
		--[End] Added by Aadil on 25012021 for Check part already fail or not 

		/*
		SELECT @Total_Pass_Qty = COUNT(*)
		FROM Assy_LineAssyStatus (NOLOCK) WHERE  ProfitCenterCode = @ProfitCenterCode
		AND LineCode = @LineCode
		AND DateCode = @Assy_DateCode
		AND OperationCode = @OperationCode
		AND ISNULL(Status,'') = 'PS'
               
		SELECT @Total_Fail_Qty = COUNT(*)
		FROM Assy_LineAssyStatus (NOLOCK) WHERE  ProfitCenterCode = @ProfitCenterCode
		AND LineCode = @LineCode
		AND DateCode = @Assy_DateCode
		AND OperationCode = @OperationCode
		AND ISNULL(Status,'') = 'FL'
               
		SELECT @Part_Pass_Qty = COUNT(*) 
		FROM Assy_LineAssyStatus (NOLOCK) WHERE  ProfitCenterCode = @ProfitCenterCode
		AND LineCode = @LineCode
		AND DateCode = @Assy_DateCode
		AND OperationCode = @OperationCode
		AND PartNo = @PartNo
		AND ISNULL(Status,'') = 'PS'
		AND ISNULL(IsTallyChartApproved,0) = 0
                 
		SELECT  @Part_Fail_Qty = COUNT(*) 
		FROM Assy_LineAssyStatus (NOLOCK) WHERE  ProfitCenterCode = @ProfitCenterCode
		AND LineCode = @LineCode
		AND DateCode = @Assy_DateCode
		AND OperationCode = @OperationCode
		AND PartNo = @PartNo
		AND ISNULL(Status,'') = 'FL'
		AND ISNULL(IsTallyChartApproved,0) = 0
               
		SELECT @Part_Running_Fail_Qty = COUNT(*) 
		FROM Assy_LineAssyStatus_Running (NOLOCK) WHERE  ProfitCenterCode = @ProfitCenterCode
		AND LineCode = @LineCode
		AND DateCode = @Assy_DateCode
		AND OperationCode = @OperationCode
		AND PartNo = @PartNo
		AND ISNULL(Status,'') = 'FL'
        */   
		--SELECT @Total_Pass_Qty Total_Pass_Qty,@Total_Fail_Qty Total_Fail_Qty,@Part_Pass_Qty Part_Pass_Qty,@Part_Fail_Qty Part_Fail_Qty,@Part_Running_Fail_Qty Part_Running_Fail_Qty

		IF EXISTS
		(
			SELECT 1 FROM Assy_ShiftWise_PassFail_Count (NOLOCK) WHERE LineCode = @LineCode AND DateCode = @Assy_DateCode
		)
		BEGIN
		--[Start] Added by Aadil on 20210406 for Log Query when Pass or fail qty is negative
			Declare @PassCountNegValueCheck int= 0
			Declare @failCountNegValueCheck int= 0
			Declare @LogDetails varchar(max)= ''

			SELECT @failCountNegValueCheck = ISNULL(FailQty,0)+ (ISNULL(@Part_Fail_Qty,0))- @FailBarcodeqty
			,@PassCountNegValueCheck=ISNULL(PassQty,0)+ ISNULL(@Total_Pass_Qty,0) FROM Assy_ShiftWise_PassFail_Count(Nolock) 
			WHERE ProfitCenterCode = @ProfitCenterCode AND DateCode = @Assy_DateCode AND LineCode = @LineCode

			if(@PassCountNegValueCheck < 0 OR @failCountNegValueCheck<0)
			begin

				DECLARE @tableName  VARCHAR(60)='Assy_LineAssyStatus_Running_'
				SET @tableName=@tableName+'S_'+ CONVERT(varchar,GETDATE(),112)
				IF EXISTS(SELECT Top 1 1 FROM sys.tables WHERE NAME=@tableName)
				exec('DROP TABLE '+@tableName)
				exec('select * into '+@tableName+' from Assy_LineAssyStatus_Running(Nolock)')
				
				set @LogDetails ='EXEC ASSY_PROC_SHIFTQTY_UPDATE @CONDITION='+@CONDITION+', @PROFITCENTERCODE='+@PROFITCENTERCODE
							+',@ComponentStatus='+@ComponentStatus+',@LINECODE='+@LINECODE+',@BARCODE='+@BARCODE+',@OPERATIONCODE='
							+@OPERATIONCODE+',@CURRENTDATECODE='+@CURRENTDATECODE+',@CURRENTPARTNO='+@CURRENTPARTNO
							+ '|@failCountNegValueCheck : '+CONVERT(varchar(4),@failCountNegValueCheck)
							+'@PassCountNegValueCheck : '+CONVERT(varchar(4),@PassCountNegValueCheck)
				INSERT INTO process_log(prg_name,barcodes,count,value,ent_dt,remarks) values('Assy_Proc_ShiftQty_Update','Negative Count',1,@LogDetails,GETDATE(),'Negative Count'+@tableName)
			end
		--[END] Added by Aadil on 20210406 for Log Query when Pass or fail qty is negative
		--[Start] modified by Aadil on 25012021 for update pass/fail count 
			UPDATE Assy_ShiftWise_PassFail_Count
			SET PassQty = ISNULL(PassQty,0)+ ISNULL(@Total_Pass_Qty,0),

			FailQty =ISNULL(FailQty,0)+ (ISNULL(@Part_Fail_Qty,0))- @FailBarcodeqty --+ ISNULL(@Part_Running_Fail_Qty,0)),
			,TIMESTAMP = GETDATE()
			WHERE ProfitCenterCode = @ProfitCenterCode AND DateCode = @Assy_DateCode AND LineCode = @LineCode
		END
  
		IF EXISTS
		(
			SELECT 1 FROM Assy_PartWise_PassFail_Count (NOLOCK) WHERE LineCode = @LineCode AND DateCode = @Assy_DateCode AND PartNo = @PartNo
		)
		BEGIN
			--[Start] Added by Aadil on 20210406 for Log Query when Pass or fail qty is negative
			Select @PassCountNegValueCheck = ISNULL(PassQty,0)+ ISNULL(@Total_Pass_Qty,0)
			,@failCountNegValueCheck = ISNULL(FailQty,0)+(ISNULL(@Part_Fail_Qty,0))- @FailBarcodeqty from Assy_PartWise_PassFail_Count(Nolock)
			WHERE ProfitCenterCode = @ProfitCenterCode AND DateCode = @Assy_DateCode AND LineCode = @LineCode AND PartNo = @PartNo AND ISNULL(IsAuthorized,0) = 0
			
			if(@PassCountNegValueCheck < 0 OR @failCountNegValueCheck<0)
			begin
				
				set @tableName=@tableName+'P_'+ CONVERT(varchar,GETDATE(),112)
				IF EXISTS(SELECT Top 1 1 FROM sys.tables where name=@tableName)
				exec('DROP TABLE '+@tableName)
				exec('select * into '+@tableName+' from Assy_LineAssyStatus_Running(Nolock)')
				
				set @LogDetails ='EXEC ASSY_PROC_SHIFTQTY_UPDATE @CONDITION='+@CONDITION+', @PROFITCENTERCODE='+@PROFITCENTERCODE
							+',@ComponentStatus='+@ComponentStatus+',@LINECODE='+@LINECODE+',@BARCODE='+@BARCODE+',@OPERATIONCODE='
							+@OPERATIONCODE+',@CURRENTDATECODE='+@CURRENTDATECODE+',@CURRENTPARTNO='+@CURRENTPARTNO
							+ ' |@failCountNegValueCheck : '+CONVERT(varchar(4),@failCountNegValueCheck)
							+'@PassCountNegValueCheck : '+CONVERT(varchar(4),@PassCountNegValueCheck)
				INSERT INTO process_log(prg_name,barcodes,count,value,ent_dt,remarks) values('Assy_Proc_ShiftQty_Update','Negative Count',1,@LogDetails,GETDATE(),'Negative Count'+@tableName)
			end
			--[END] Added by Aadil on 20210406 for Log Query when Pass or fail qty is negative
			UPDATE Assy_PartWise_PassFail_Count
			SET PassQty = ISNULL(PassQty,0)+ ISNULL(@Total_Pass_Qty,0),
			FailQty = ISNULL(FailQty,0)+(ISNULL(@Part_Fail_Qty,0))- @FailBarcodeqty,-- + ISNULL(@Part_Running_Fail_Qty,0)),
			TIMESTAMP = GETDATE()
			WHERE ProfitCenterCode = @ProfitCenterCode AND DateCode = @Assy_DateCode AND LineCode = @LineCode AND PartNo = @PartNo AND ISNULL(IsAuthorized,0) = 0
			
		--[END] modified by Aadil on 25012021 for update pass/fail count 
		END

		SET @ReturnInt = 1
		SET @ReturnValue = 'UPDATED'
		RETURN
	END

	ELSE IF @Condition = 'SELECT'
	BEGIN
		SELECT * INTO #Assy_RunningPart FROM Assy_RunningPart (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode

		SELECT @PartNo = Assy_PartNo,@ProductionOrderNo = ProductionOrderNo,@CurrentDateCode = DateCode,@SetParameterDate = ISNULL(ModifiedOn,CreatedDate),
			@CustomerPartNo = ISNULL(CustomerPartNo,''),@SetParamPlannedQty = CurrentPlannedQty, @Partcategory = Category FROM #Assy_RunningPart

		--GET SHIFT WISE PASS FAIL DATA
		SELECT ISNULL(TotalQty,0) TotalQty,ISNULL(PassQty,0) PassQty,ISNULL(FailQty,0) FailQty,
			CASE WHEN ISNULL(TotalQty,0) = 0 THEN 0
				ELSE CONVERT(numeric(10,2),(CONVERT(numeric(10,2),(ISNULL(PassQty,0) * 100)) / CONVERT(numeric(10,2),ISNULL(TotalQty,1)))) END AS PERCOMPLETED
					FROM Assy_ShiftWise_PassFail_Count(NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode AND DateCode = @CurrentDateCode

		--GET PART WISE PASS FAIL DATA
		SELECT ISNULL(SUM(ISNULL(TotalQty,0)),0) TOTALQTYPART,ISNULL(SUM(ISNULL(PassQty,0)),0) PASSQTYPART,ISNULL(SUM(ISNULL(FailQty,0)),0) FAILQTYPART,
			CASE WHEN ISNULL(SUM(ISNULL(TotalQty,0)),0) = 0 THEN 0
				ELSE CONVERT(numeric(10,2),(CONVERT(numeric(10,2),(ISNULL(SUM(ISNULL(PassQty,0)),0) * 100)) / CONVERT(numeric(10,2),ISNULL(SUM(ISNULL(TotalQty,0)),1)))) END AS PERCOMPLETEDPART
					FROM Assy_PartWise_PassFail_Count(NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode AND DateCode = @CurrentDateCode 
					AND PartNo = @PartNo and IsAuthorized='0'

		--GET PRODUCTION ODER AND MODE
		SELECT TOP 1 @ProductionOrderNo AS ProductionOrderNo,Assy_Mode,@PartNo AS PartNo,@CustomerPartNo AS CustomerPartNo
			FROM #Assy_RunningPart

		SELECT TOP 1 PartNo PARTNUMBER, CONVERT(int,ISNULL(QTY,0)) PLANNEDQTY 
			FROM ASSY_PRODUCTIONORDERMST(NOLOCK) H
				INNER JOIN LINEMST(NOLOCK) L
					ON L.WORKCENTERCODE = H.WORKCENTERCODE
						WHERE ISNULL(H.Status,'') <> '100' AND H.ORDERNO != @ProductionOrderNo AND L.LineCode = @LineCode AND L.IsActive = 1 AND H.ProfitCenterCode = @ProfitCenterCode
							AND H.IsActive = 1 AND ISNULL(@CurrentPartNo,'') <> '' AND ISNULL(@ProductionOrderNo,'') <> ''
								ORDER BY ORDERDATE,H.PRIORITY ASC

		-- ADD BY RASHID SIDDIQUI ON 13TH OCT 2015 FOR GET PART TYPE,SERVO AND TMC PART
		SELECT TOP 1 ISNULL(PARTTYPE,'') PARTTYPE,ISNULL(TMC_PARTNO,'') TMC_PARTNO,ISNULL(SERVO_PARTNO,'') SERVO_PARTNO FROM #Assy_RunningPart ORDER BY CREATEDDATE DESC 
		
		IF ISNULL(@Partcategory,'') = ''
		BEGIN
			SELECT @CurrentDateCode + ' - ' + CONVERT(VARCHAR,ISNULL(@SetParamPlannedQty,0)), @SetParameterDate
		END
		ELSE
		BEGIN
			SELECT @CurrentDateCode + ' - ' + CONVERT(VARCHAR,ISNULL(@SetParamPlannedQty,0)) + ' - ' + ISNULL(@Partcategory,''), @SetParameterDate
		END

		--Added By Sachin 210302
		--GET FAMILY GROUP CODE FROM PRODUCT MASTER.
		select TOP 1 ISNULL(Family_Group_Code,'') as Family_Group_Code from PRODUCT_MASTER(nolock) where warehouse_cd=@ProfitCenterCode 
		and SEWS_PART_NO=@PartNo
		--Ended By Sachin 210302

		RETURN
	END

	ELSE IF @Condition = 'UPDATE_PLANNED_QTY'
	BEGIN
		SELECT * INTO #U_Assy_RunningPart FROM Assy_RunningPart(NOLOCK) WHERE LineCode = @LineCode
		
		SELECT @PartNo = Assy_PartNo,@CurrentDateCode = DateCode,@TotalPartWiseQty = ISNULL(CurrentPlannedQty,0) FROM #U_Assy_RunningPart
		SET @CurrentPartNo = @PartNo
		---------------------------------------------PART WISE----------------------------
		--SET @TotalPartWiseQty = (SELECT TOP 1 ISNULL(CurrentPlannedQty,0) FROM Assy_RunningPart(NOLOCK)	WHERE LineCode = @LineCode)

		IF EXISTS
		(
			SELECT 1 FROM Assy_PartWise_PassFail_Count(NOLOCK) PP WHERE PP.LineCode = @LineCode AND PP.DateCode = @CurrentDateCode
				AND PP.PartNo = @CurrentPartNo AND ISNULL(PP.IsAuthorized,0) = 0
		)
		BEGIN
			IF
			(
				@IsLabelPRTForSelPart = 1
			)
			BEGIN
				UPDATE PP
					SET PP.TotalQty = (ISNULL(PP.TotalQty,0) + ISNULL(RP.CurrentPlannedQty,0))
						FROM Assy_PartWise_PassFail_Count(NOLOCK) PP
							INNER JOIN #U_Assy_RunningPart RP
								ON RP.LineCode = PP.LineCode AND RP.Assy_PartNo = PP.PartNo AND RP.DateCode = PP.DateCode
									WHERE PP.LineCode = @LineCode AND PP.DateCode = @CurrentDateCode AND PP.PartNo = @CurrentPartNo
										AND ISNULL(RP.PrintedQty,0) = 0 AND ISNULL(PP.IsAuthorized,0) = 0
			END
			ELSE
			BEGIN
							--UPDATE PP
							--	SET TotalQty = (ISNULL(RPP.CurrentPlannedQty,0) + @TotalPartWiseQty),TIMESTAMP = GETDATE()
							--		FROM Assy_PartWise_PassFail_Count(NOLOCK) PP
							--			INNER JOIN #U_Assy_RunningPart RP
							--				ON RP.LineCode = PP.LineCode AND RP.Assy_PartNo = PP.PartNo AND RP.DateCode = PP.DateCode
							--			LEFT OUTER JOIN Assy_RunningPart_Previous(NOLOCK) RPP
							--				ON RPP.LineCode = RP.LineCode AND RPP.Assy_PartNo = RP.Assy_PartNo AND RPP.DateCode = RP.DateCode AND RPP.Assy_Mode = RP.Assy_Mode
							--					WHERE PP.LineCode = @LineCode AND PP.DateCode = @CurrentDateCode AND PP.PartNo = @CurrentPartNo AND ISNULL(RP.PrintedQty,0) = 0
							--						AND ISNULL(RP.PrintedQty,0) = 0 AND ISNULL(PP.IsAuthorized,0) = 0
							Declare @currentcount int																	
							select @currentcount=SUM(ISNULL(RPP.CurrentPlannedQty,0))  FROM Assy_PartWise_PassFail_Count(NOLOCK) PP
							INNER JOIN #U_Assy_RunningPart RP ON RP.LineCode = PP.LineCode AND RP.Assy_PartNo = PP.PartNo AND RP.DateCode = PP.DateCode
							LEFT OUTER JOIN Assy_RunningPart_Previous(NOLOCK) RPP
							ON RPP.LineCode = RP.LineCode AND RPP.Assy_PartNo = RP.Assy_PartNo AND RPP.DateCode = RP.DateCode AND RPP.Assy_Mode = RP.Assy_Mode
							WHERE PP.LineCode = @LineCode AND PP.DateCode = @CurrentDateCode AND PP.PartNo = @CurrentPartNo AND ISNULL(RP.PrintedQty,0) = 0
							AND ISNULL(RP.PrintedQty,0) = 0 AND ISNULL(PP.IsAuthorized,0) = 0
							
							update PP  set PP.TotalQty=@currentcount + @TotalPartWiseQty from Assy_PartWise_PassFail_Count (NOLOCK) PP
							WHERE PP.LineCode = @LineCode AND PP.DateCode = @CurrentDateCode AND PP.PartNo = @CurrentPartNo And ISNULL(PP.IsAuthorized,0) = 0
			END																
		END
		ELSE
		BEGIN
			INSERT INTO Assy_PartWise_PassFail_Count (LineCode,ProfitCenterCode,[DateCode],PartNo,TotalQty)
			SELECT @LineCode,@ProfitCenterCode,@CurrentDateCode,@CurrentPartNo,@TotalPartWiseQty WHERE @CurrentPartNo <> '#' AND @CurrentPartNo <> '0' AND ISNULL(@CurrentPartNo,'') <> ''
		END
		---------------------------------------------SHIFT WISE----------------------------
		IF EXISTS
		(
			SELECT 1 FROM Assy_ShiftWise_PassFail_Count(NOLOCK) WHERE LineCode = @LineCode	AND DateCode = @CurrentDateCode
		)
		BEGIN
			SELECT @TotalShiftQty = ISNULL(SUM(ISNULL(TotalQty,0)),0)
			FROM Assy_PartWise_PassFail_Count(NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode 
			AND DateCode = @CurrentDateCode --AND ISNULL(IsAuthorized,0) = 1 --Commented By Sachin 20190503

			--Commented By Sachin 20190503
			--IF ISNULL(@TotalShiftQty,0) = 0
			--BEGIN
			--	SELECT @TotalShiftQty = ISNULL(TotalQty,0)
			--	FROM Assy_PartWise_PassFail_Count(NOLOCK)
			--	WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode	AND DateCode = @CurrentDateCode 
			--	AND PartNo = @CurrentPartNo	AND ISNULL(IsAuthorized,0) = 0
			--END
			--ELSE
			--BEGIN
			--	SELECT @TotalShiftQty = @TotalShiftQty + ISNULL(TotalQty,0)
			--	FROM Assy_PartWise_PassFail_Count(NOLOCK)
			--	WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode AND DateCode = @CurrentDateCode 
			--	AND PartNo = @CurrentPartNo AND ISNULL(IsAuthorized,0) = 0
			--END
			--Commented End By Sachin 20190503

			UPDATE Assy_ShiftWise_PassFail_Count
				SET TotalQty = @TotalShiftQty,TIMESTAMP = GETDATE()
					WHERE DateCode = @CurrentDateCode AND LineCode = @LineCode
		END
		ELSE
		BEGIN
			SELECT @TotalShiftQty = SUM(ISNULL(TotalQty,0))
				FROM Assy_PartWise_PassFail_Count(NOLOCK)
					WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode AND DateCode = @CurrentDateCode --AND ISNULL(IsAuthorized,0) = 0

			INSERT INTO Assy_ShiftWise_PassFail_Count (LineCode,ProfitCenterCode,[DateCode],TotalQty,[TIMESTAMP])
			SELECT @LineCode,@ProfitCenterCode,@CurrentDateCode,@TotalShiftQty,GETDATE() WHERE @TotalShiftQty <> 0
		END

		RETURN
	END

	ELSE IF @Condition = 'UPDATE_SHIFT_PRODUCE_QTY_IN_MAIN_SERVER'
	BEGIN
		BEGIN TRY
		DECLARE @EXECQUERY AS nvarchar(1000),@LINKSERVERNAME varchar(100)
		
		SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME + '.DBO.' FROM ASSY_LINKSERVER_DTL(NOLOCK)	WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode

		SET @EXECQUERY = '
		INSERT INTO  ' + @LINKSERVERNAME + 'Assy_ShiftWise_PassFail_Count
		(
			LineCode,
			ProfitCenterCode,
			DateCode,
			TotalQty,
			PassQty,
			FailQty,
			TIMESTAMP,
			ISMAILSENT
		) 
		SELECT
			LineCode,
			ProfitCenterCode,
			DateCode,
			TotalQty,
			PassQty,
			FailQty,
			TIMESTAMP,
			ISMAILSENT
		FROM Assy_ShiftWise_PassFail_Count WHERE ISNULL(ISMAILSENT,0) = 0 AND  
		ProfitCenterCode = ''' + @ProfitCenterCode + ''' AND LineCode = ''' + @LineCode + '''
		UPDATE Assy_ShiftWise_PassFail_Count SET  ISMAILSENT = 1 WHERE ISNULL(ISMAILSENT,0) = 0 AND  
		ProfitCenterCode = ''' + @ProfitCenterCode + ''' AND LineCode = ''' + @LineCode + ''''
		EXECUTE SP_EXECUTESQL @EXECQUERY

		SET @EXECQUERY = '
		INSERT INTO   ' + @LINKSERVERNAME + 'Assy_PartWise_PassFail_Count
		(
			LineCode,
			ProfitCenterCode,
			DateCode,
			PartNo,
			TotalQty,
			PassQty,
			FailQty,
			TIMESTAMP,
			ProductionOrderNo,
			IsAuthorized,
			ISMAILSENT
		)
		SELECT
			LineCode,
			ProfitCenterCode,
			DateCode,
			PartNo,
			TotalQty,
			PassQty,
			FailQty,
			TIMESTAMP,
			ProductionOrderNo,
			IsAuthorized,
			ISMAILSENT
		FROM Assy_PartWise_PassFail_Count WHERE ISNULL(ISMAILSENT,0) = 0 AND  
		ProfitCenterCode = ''' + @ProfitCenterCode + ''' AND LineCode = ''' + @LineCode + '''
		UPDATE Assy_PartWise_PassFail_Count SET ISMAILSENT = 1  WHERE ISNULL(ISMAILSENT,0) = 0 AND  
		ProfitCenterCode = ''' + @ProfitCenterCode + ''' AND LineCode = ''' + @LineCode + ''''
		
		EXECUTE SP_EXECUTESQL @EXECQUERY
		SET @ReturnInt = 1
		
		END TRY
		BEGIN CATCH
			SET @ReturnValue = CAST(ERROR_NUMBER() AS varchar(5)) + '|' +
			CAST(ERROR_SEVERITY() AS varchar(5)) + '|' +
			CAST(ERROR_STATE() AS varchar(5)) + '|' +
			CAST(ERROR_PROCEDURE() AS varchar(200)) + '|' +
			CAST(ERROR_LINE() AS varchar(5)) + '|' +
			CAST(ERROR_MESSAGE() AS varchar(1500))
			SET @ReturnInt = 2
			--ROLLBACK TRAN
			RAISERROR (@ReturnValue,16,1)
		END CATCH
		RETURN
	END
END
GO
/****** Object:  StoredProcedure [dbo].[ASSY_PROC_SHOWPARAMETERS]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[ASSY_PROC_SHOWPARAMETERS]
(
@LineCode varchar(20)=null,
@USERCODE VARCHAR(20)=NULL,
@CONDITION VARCHAR(50),
@RETURNVALUE VARCHAR (2000)=NULL OUT,
@RETURNINT INT=NULL OUT
)
as
begin

begin try
          IF @CONDITION='GET_PARAMETERS'
		BEGIN
			--select  L.OperationCode,Opt.OperationName,Assy.Barcode,
			--        Case Assy.Status when 'PS' then 'PASS' else 'FAIL' end [Status],
			--		Assy.FailCount,Assy.PartNo    from                                    RoutingConfigLineWise L inner join
			--		RoutingConfigPartWise P  on L.OperationCode =l.OperationCode and 
			--		l.ProfitCenterCode =p.ProfitCenterCode  and p.MachineCode =l.MachineCode inner join OperationMst Opt on                                              L.OperationCode=Opt.OperationCode 
			--		left outer join Assy_LineAssyStatus Assy on L.OperationCode=Assy.OperationCode and L.LineCode=Assy.LineCode 
			--		where P.Traceability =1 and P.OperationRequired =1
			--		and L.LineCode ='L0001' and L.Traceability =1 and L.OperationRequired =1 order by L.OperationSeqNo


			 select OperationCode,OperationName,Barcode,Status,FailCount,PartNo  from 
			(select  Distinct L.OperationCode,Opt.OperationName,
			        Assy.Barcode,
			        Case Assy.Status when 'PS' then 'PASS' else 'FAIL' end [Status],
					Assy.FailCount,Assy.PartNo,L.OperationSeqNo   
					from  RoutingConfigLineWise L inner join
					RoutingConfigPartWise P  on L.OperationCode =l.OperationCode and 
					l.ProfitCenterCode =p.ProfitCenterCode  and p.MachineCode =l.MachineCode inner join OperationMst Opt on                                              L.OperationCode=Opt.OperationCode 
					left outer join Assy_LineAssyStatus Assy on L.OperationCode=Assy.OperationCode and L.LineCode=Assy.LineCode 
					where P.Traceability =1 and P.OperationRequired =1
					and L.LineCode =@LineCode and L.Traceability =1 and L.OperationRequired =1) tb  order by OperationSeqNo

					
                  --Update TagMst Set UOM='Kg'
                  --select * from TagMst

					select Distinct  L.OperationCode,Assy.Barcode,Assy.TagName,Assy.Value,Tag.UOM    from  RoutingConfigLineWise                     L inner join
					RoutingConfigPartWise P  on L.OperationCode =l.OperationCode and 
					l.ProfitCenterCode =p.ProfitCenterCode  and p.MachineCode =l.MachineCode
					left outer join Assy_LineAssyParamData Assy on L.OperationCode =Assy.OperationCode and                                           L.LineCode=Assy.LineCode
					left outer join TagMst Tag on Assy.TagName=Tag.TagName and Tag.isActive=1 
					where P.Traceability =1 and P.OperationRequired =1
					and L.LineCode =@LineCode and L.Traceability =1 and L.OperationRequired =1 

			SET @RETURNVALUE='DATA SELECTED'
			SET @RETURNINT=1
		END
end Try
begin catch
            --CATCH BLOCK BEGINS
		SET @RETURNVALUE =	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
		CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
		CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_MESSAGE() AS VARCHAR(1500))
		SET @RETURNINT = 2
		--CATCH BLOCK ENDS 
End Catch

end


