/****** Object:  StoredProcedure [dbo].[Assy_Proc_STMCRework]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[Assy_Proc_STMCRework]
(
	@CONDITION VARCHAR(100),
	@PROFITCENTERCODE VARCHAR(10),
	@LINECODE VARCHAR(10),
	@STMCBARCODE VARCHAR(60),
	@PARTTYPE NVARCHAR(50)=NULL,
	@STATUS VARCHAR(10)=NULL,
	@CHILDBARCODE NVARCHAR(50)=NULL,
	@REMARK NVARCHAR(500)=NULL,
	@ENTERBY NVARCHAR(30)=NULL,
	@RETURNVALUE VARCHAR (2000)=NULL OUT,
	@RETURNINT INT=NULL OUT
	)
AS
BEGIN
-- =============================================
-- AUTHOR:		<SUNDARA MOORTHI>
-- CREATE DATE: <15-10-2015>
-- DESCRIPTION:	<STMC ASSYMBLY REWORK DEFINING PROCEEDURE>
-- =============================================
-- EXEC ASSY_PROC_STMCREWORK 'BARCODECHECK','0021','P3','093:51000M79F30:BD0121:041015:01:0001'

BEGIN TRY
	 SET NOCOUNT ON;
	IF (@CONDITION='BARCODECHECK')
		BEGIN
			 IF EXISTS(SELECT
						 STMCBARCODE 
						FROM Assy_STMC_Rework (NOLOCK) 
							WHERE 
							STMCBARCODE=@STMCBARCODE AND LineCode=@LINECODE AND ProfitcenterCode=@PROFITCENTERCODE)
				BEGIN
					SET @RETURNVALUE='Already_Reworked_Ok'
					RETURN
				END
			ELSE IF EXISTS(SELECT 
								ALAS.BARCODE 
							FROM 
							ASSY_LINEASSYSTATUS  ALAS (NOLOCK)
								WHERE
									ALAS.PROFITCENTERCODE=@PROFITCENTERCODE
									AND ALAS.LINECODE=@LINECODE 
									AND ALAS.STATUS='PS' 
									AND ALAS.MachineCode='MCFVSTMC' 
									AND ALAS.BARCODE=@STMCBARCODE
							UNION
							SELECT 
							ALASR.BARCODE 
								FROM ASSY_LINEASSYSTATUS_RUNNING ALASR (NOLOCK)
									WHERE
										ALASR.PROFITCENTERCODE=@PROFITCENTERCODE 
										AND ALASR.LINECODE=@LINECODE 
										AND ALASR.STATUS='PS' 
										AND ALASR.MachineCode='MCFVSTMC' 
										AND ALASR.BARCODE=@STMCBARCODE)
							BEGIN
									SET @RETURNVALUE='Already_Passed_Ok'
									RETURN
							END
        			ELSE
						BEGIN
							SELECT 
								ACD.FG_BARCODE,
								ACD.PART_TYPE,
								ACD.CHILD_Barcode
							FROM ASSY_COUPLINGDETAILS ACD (NOLOCK)
								 WHERE
									ACD.PROFITCENTRECODE=@PROFITCENTERCODE
									AND ACD.LINECODE=@LINECODE 
									AND ACD.FG_BARCODE=@STMCBARCODE
							SET @RETURNVALUE='NOPASSBARCODES'
							RETURN
						END
		END
		ELSE IF (@CONDITION='DATASAVE')
			BEGIN
				INSERT INTO ASSY_STMC_REWORK(
				PROFITCENTERCODE,
				LINECODE,
				STMCBARCODE,
				CHILDBARCODE,
				PARTTYPE,
				[STATUS],
				REMARKS,
				ENT_BY,
				ENT_DT
				)
				VALUES
				(
				@PROFITCENTERCODE,
				@LINECODE,
				@STMCBARCODE,
				@CHILDBARCODE,
				@PARTTYPE,
				@STATUS,
				@REMARK,
				@ENTERBY,
				GETDATE()
				)
				SET @RETURNVALUE='Record Saved Successfully'
				RETURN
			END
IF (@CONDITION='GETCHILDBARCODE')
	BEGIN
		SELECT ACD.FG_BARCODE,ACD.PART_TYPE,ACD.CHILD_BARCODE FROM ASSY_COUPLINGDETAILS ACD (NOLOCK)
			WHERE
				ACD.PROFITCENTRECODE=@PROFITCENTERCODE
				AND ACD.LINECODE=@LINECODE 
				AND ACD.FG_BARCODE=@STMCBARCODE
				RETURN
	END
IF(@CONDITION='GETFGBARCODE')
	BEGIN
		SELECT 
		ALAS.BARCODE 
		FROM 
			ASSY_LINEASSYSTATUS  ALAS (NOLOCK)
				WHERE
					ALAS.PROFITCENTERCODE=@PROFITCENTERCODE
					AND ALAS.LINECODE=@LINECODE 
					AND ALAS.BARCODE=@STMCBARCODE
		UNION
		SELECT 
		ALASR.BARCODE 
			FROM ASSY_LINEASSYSTATUS_RUNNING ALASR (NOLOCK)
				WHERE
					ALASR.PROFITCENTERCODE=@PROFITCENTERCODE 
					AND ALASR.LINECODE=@LINECODE 
					AND ALASR.BARCODE=@STMCBARCODE
					RETURN
	END
END TRY
BEGIN CATCH
		SET @RETURNVALUE =	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 	CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
		CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
		CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + CAST(ERROR_MESSAGE() AS VARCHAR(1500))
		SET @RETURNINT = 2
		RAISERROR(@RETURNVALUE,16,1)
END CATCH
END

