/****** Object:  StoredProcedure [dbo].[Assy_Proc_Stroking]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

CREATE proc [dbo].[Assy_Proc_Stroking] 
(
@CONDITION VARCHAR(50),
@ProfitCenterCode varchar(20)=null,
@LineCode varchar(20)=null,
@LineTypeName varchar(20) = null,

@OperationCode varchar(20)=null,
@MachineCode varchar(20)=null,
@StationCode varchar(20)='1',
@DateCode varchar(4)=null,
@PartNumber varchar(20)=null,
@Barcode varchar(35)=null,
@Prefix char(2)=null,
@Suffix char(2)=null,
@ReturnValue VARCHAR (2000)=NULL OUT,
@ReturnInt INT=NULL OUT,
@UserId varchar(50)=NULL,
@PassQty int=0,
@FailQty int=0
)
AS
BEGIN

-- Author:		<Manoj Kumar>
-- Create date: < 22 December 2014>
-- Description:	<Stroking.>

-- To Rembember
-- Nothing = 0
-- Success = 1
-- Error = 2
-- AlreadyExists = 3
-- NotExists = 4
-- Yes = 5
--No = 6

/*
select * from Assy_Stations_Zig_In_Out_Status
exec [Assy_Proc_FinalViewing] @CONDITION='SCAN_OK',@LineCode='L0001' ,@OperationCode='OP0001'
*/
--update  Assy_Stations_Zig_In_Out_Status set StatusInOut=1

BEGIN TRY

        Declare @failCountDefined int=0
		declare @failCount int=0
		Declare @TempScannedPartType varchar(15)
		Declare @TempRunningPartType varchar(15)
		Declare @TempOperationType varchar(20)
		Declare @FinalViewing_OperationCode varchar(10)='OCFV'
		
		Declare @Part_Code varchar(20) = null
		Declare @Servo_Part_Code varchar(20) = null
		Declare @Sequence int = null
		Declare @Sequence_string varchar(10) = null
		Declare @Final_Barcode varchar(20) = null


		SET NOCOUNT ON
		
		IF @CONDITION='IS_MODE_PLC'
		BEGIN
		   IF((select PARAMETER_VALUE from PARAMETER_MST WHERE PARAMETER_C = 'AssyLine' AND PARAMETER_C1 = 'IsStrokingLabelPrintThroughPLC') = 'Yes')
		   Begin
		     set @ReturnInt = 5
		   End
		   Else
		   Begin
		     set @ReturnInt = 6
		   End    
		END
		
		IF @CONDITION = 'IS_PRINT_SIGNAL_ON'
		Begin
		 if((select PrintSignal from ASSY_STROKING_PRINTSIGNAL where LineCode = @LineCode) = 1)
		 Begin
		   set @ReturnInt = 5
		 End
		 Else
		 Begin
		    set @ReturnInt = 6
		 End
		End
		
		
		--exec Assy_Proc_Stroking @CONDITION = 'GET_BARCODE_DATA', @LineCode = 'M07', @ReturnValue out = @ReturnValue
		--print @ReturnValue
		IF @CONDITION = 'GET_BARCODE_DATA'
		Begin
		  
		  print 'inside'
		  if not exists (select ASSY_Mode from Assy_RunningPart where LineCode = @LineCode)
		  Begin
		    set @ReturnValue = 'PART_NOT_AVAILABLE_ON_LINE'
		    RETURN
		  End
		  print '1'
		  if((select ASSY_Mode from Assy_RunningPart where LineCode = @LineCode) <> 'Production')
		  Begin
		    set @ReturnValue = 'MODE_IS_NOT_PRODUCTION'
		    RETURN
		  End
		  print '2'
		  
		 set @LineTypeName =  (SELECT B.LineTypeName from LineMst as A inner join LineTypeMst as B ON A.LineTypeCode = B.LineTypeCode
		  WHERE A.LineCode = @LineCode)
		  
		  print @LineTypeName
		  if not ((@LineTypeName = 'SERVO') OR (@LineTypeName = 'STMC'))
		  Begin
		   set @ReturnValue = 'PART_IS_NOT_SERVO_OR_STMC'
		    RETURN
		  End
		 
		 print '3'
		
		 select @Part_Code = Assy_PartNo, @DateCode = DateCode from Assy_RunningPart where LineCode = @LineCode
		 if(@LineTypeName = 'SERVO')
		 Begin
		  set @Servo_Part_Code = @Part_Code
		 End
		 print @Servo_Part_Code
		 print '4'
		 if(@LineTypeName = 'STMC')
		 Begin
		   select @Servo_Part_Code = A.RM_PART_NO FROM BOM_MASTER AS A INNER JOIN PRODUCT_MASTER AS B ON A.RM_PART_NO = B.SEWS_PART_NO 
		   WHERE A.FG_PART_NO = @Part_Code AND B.pt_part_type = 'SERVO'
		   
		   IF(@Servo_Part_Code = NULL)
		   Begin
		    set @ReturnValue = 'STMC_PART_NOT_DEFINED_IN_BOM_OR_PRODUCT_MASTER'
		    RETURN
		   End
		  End
		 
		   
		   --Get the barcode sequence
		   print '5'
			if not exists (select top 1 1 from ASSY_STROKING_BARCODE_SEQUENCE where LineCode = @LineCode and Part_code = @Servo_Part_Code)
			Begin
			
			 set @Sequence = 1
			 Insert into ASSY_STROKING_BARCODE_SEQUENCE (LineCode, Part_code, Sequence, Ent_Dt) Values (@LineCode, @Servo_Part_Code, 1, GETDATE())
			End
			
			else
			Begin
			 print '6'
			 set @Sequence = (select Sequence from ASSY_STROKING_BARCODE_SEQUENCE where LineCode = @LineCode and Part_code = @Servo_Part_Code)
			 set @Sequence = @Sequence + 1
			End
			
			set @Sequence_string = (SELECT RIGHT('00000000' + CAST(@Sequence AS NVARCHAR), 8))
			
			set @Final_Barcode = @Servo_Part_Code + @DateCode + @Sequence_string + @LineCode 
		    
		    set @ReturnValue = @Final_Barcode   
		 End  
		
		
		
		IF @CONDITION='GET_TAGS'
		BEGIN
		  
		

					 select top 1 Assy.OperationCode,Assy.Barcode,Assy.TagName,Assy.Value,ISNULL(Assy.Result,'')Result ,isnull( Tag.UOM,'')UOM   from 
					 (
							select linecode, OperationCode,Barcode,TagName,Value,Timestamp,Result  from Assy_LineAssyParamData_Running(nolock)
							union
							select linecode, OperationCode,Barcode,TagName,Value,Timestamp,Result  from Assy_LineAssyParamData(nolock)

					 )Assy
					left outer join TagMst(nolock) Tag on Assy.TagName=Tag.TagName and Tag.isActive=1 
						where Assy.LineCode =@LineCode  
						and Assy.OperationCode =@OperationCode 
						order by Timestamp desc
		END

		IF @CONDITION='GET_PLCADDRESS'
		BEGIN
		select R.LineCode,O.OperationName,O.OperationCode,StationCode,R.MachineCode,Mach.MachineName ,mach.PLCAddress from (
			
											select L.LineCode , L.OperationCode,L.OperationSeqNo,p.PartNo,MD.StationCode,p.MachineCode   from RoutingConfigLineWise(nolock) L 
											inner join RoutingConfigPartWise(nolock) P 
												on L.ProfitCenterCode=p.ProfitCenterCode and l.OperationCode =p.OperationCode   and l.MachineCode=p.MachineCode
												--and l.OperationSeqNo =p.OperationSeqNo 
											inner join MachineDtl MD on l.OperationCode=MD.OperationCode and l.LineCode=MD.LineCode 	
												where l.LineCode =@LineCode  and P.PartNo=(select Assy_PartNo from Assy_RunningPart where LineCode =@LineCode ) and
												--L.OperationRequired =1 and 
												l.Traceability =1
												--and p.OperationRequired =1 
												and p.Traceability =1
												
									)R
									inner join OperationMst (nolock) O on o.OperationCode  =R.OperationCode 
									left outer join MachineMst (nolock) Mach on Mach.MachineCode = R.MachineCode
									where O.OperationCode not in('OCVS','OCFV')
									order by R.OperationSeqNo 
			set @ReturnInt=1
		    set @ReturnValue='Success' 	
		END

		IF @CONDITION='GET_SHOWRESULT_DATA'
		BEGIN
					--select Run.LineCode ,Run.OperationCode,Run.MachineCode,Run.StationCode ,run.Barcode,Run.Status    from Assy_Result (NOLOCK) Res				
					--	inner	join Assy_LineAssyStatus_Running (NOLOCK) Run on Res.LineCode =Run.LineCode and	Res.OperationCode =Run.OperationCode 
					--and Res.StationCode=Run.StationCode and Res.Barcode=Run.Barcode 
					--where  isnull(Res.Barcode,'') <>'' and isnull(Run.Status,'')<>''

					--Update Assy_Result set Barcode='' where  isnull(Barcode,'') <>''
					
					select Res.LineCode ,Res.OperationCode,Run.MachineCode,Run.StationCode ,run.Barcode,Run.Status    from Assy_Result (NOLOCK) Res				
						inner	join Assy_LineAssyStatus_Running (NOLOCK) Run on Res.LineCode =Run.LineCode and	Res.OperationCode =Run.OperationCode 
					and Res.StationCode=Run.StationCode and Res.Barcode=Run.Barcode 
					where  isnull(Res.Barcode,'') <>'' and isnull(Run.Status,'')<>''

					Update Assy_Result set Barcode='' where  isnull(Barcode,'') <>''


		  	set @ReturnInt=1
		    set @ReturnValue='Success' 
		END	
		IF @CONDITION='GETPARAMETERS'
		BEGIN
			SELECT PARAMETER_C2,PARAMETER_NM,PARAMETER_VALUE FROM PARAMETER_MST (NOLOCK) WHERE PARAMETER_C='ASSLINE' 
			AND   USER_CONFIGURABLE_FLG=1
			SET @RETURNVALUE='DATA SELECTED'
			SET @RETURNINT=1
		END
		IF @CONDITION='STATION_ORDERS'
						BEGIN
		
					   select O.OperationCode,R.OperationSeqNo,O.OperationName from (
			
										select L.LineCode , L.OperationCode,L.OperationSeqNo,p.PartNo  from RoutingConfigLineWise(nolock) L 
										inner join RoutingConfigPartWise(nolock) P 
										on L.ProfitCenterCode=p.ProfitCenterCode and l.OperationCode =p.OperationCode   and l.MachineCode                                                   =p.MachineCode
										--and l.OperationSeqNo =p.OperationSeqNo 				
										where l.LineCode =@LineCode and
										L.OperationRequired =1 and l.Traceability =1
										and p.OperationRequired =1 and p.Traceability =1
										and p.PartNo =(select Assy_PartNo from Assy_RunningPart(nolock) where LineCode=@LineCode and Assy_Mode IN ('Production','Rework') )
								)R
								inner join OperationMst (nolock) O on o.OperationCode  =R.OperationCode  
								order by R.OperationSeqNo 

								set @ReturnInt=1
								set @ReturnValue='Success'
						END
		IF @CONDITION='LINE_PREFIX'
						BEGIN
		
						select  LineCode,LinePrefix from LineMst(nolock) where ProfitCenterCode=@ProfitCenterCode and LineCode=@LineCode
								set @ReturnInt=1
								set @ReturnValue='Success'
						END
		IF @CONDITION='GET_ACTIVE_STATION'
							BEGIN
				
									

									select R.LineCode,O.OperationName,R.OperationSeqNo,R.PartNo,O.OperationCode,StationCode from (
			
											select L.LineCode , L.OperationCode,L.OperationSeqNo,p.PartNo,MD.StationCode   from RoutingConfigLineWise(nolock) L 
											inner join RoutingConfigPartWise(nolock) P 
											on L.ProfitCenterCode=p.ProfitCenterCode and l.OperationCode =p.OperationCode   and l.MachineCode  =p.MachineCode
										  inner join MachineDtl MD on l.OperationCode=MD.OperationCode and  l.LineCode=MD.LineCode 	
											where l.LineCode =@LineCode and P.PartNo=(select Assy_PartNo from Assy_RunningPart where LineCode =@LineCode )
											and l.Traceability =1
											 and p.Traceability =1
									)R
									inner join OperationMst (nolock) O on o.OperationCode  =R.OperationCode  
									order by R.OperationSeqNo 	

									set @ReturnInt=1
									set @ReturnValue='Success'
							   END
        IF @CONDITION='GET_MACHINE_DTL'
							BEGIN		
							select LineCode,MachineCode,OperationCode,StationCode   from MachineDtl (nolock)  where Prefix=@Prefix and  
							Suffix=@Suffix
									set @ReturnInt=1
									set @ReturnValue='Success'
							END
  --      IF @CONDITION='TESTING_IS_ON'
		--BEGIN		
		--		select StatusInOut from Assy_Stations_Zig_In_Out_Status(nolock) where LineCode=@LineCode  and 
		--		OperationCode=@OperationCode and StationCode=@StationCode and StatusInOut=1
		--				set @ReturnInt=1
		--				set @ReturnValue='Success'
		--				return
		--END

        IF @CONDITION='SCAN_OK'
		begin			
						
		BEGIN TRY
		 BEGIN TRAN
				--Check for jig in/out status
				 IF EXISTS
				 ( 
						 SELECT 1 FROM ASSY_STATIONS_ZIG_IN_OUT_STATUS(NOLOCK) WHERE LINECODE=@LINECODE  AND 
						 OPERATIONCODE=@OPERATIONCODE  AND STATUSINOUT=1
						 --AND STATIONCODE=@STATIONCODE
				
				  )
				  BEGIN
								--SELECT 'JIG_IS_INSIDE' 
								SET @RETURNINT=1
								SET @RETURNVALUE='JIG_IS_INSIDE'
						
								--update incorrect label
								exec Assy_proc_IncorrectLabel_Manage @CONDITION='update',@LineCode=@LINECODE,@OperationCode=@OPERATIONCODE
								,@BARCODE=@Barcode,@HMIMEssage='Jig_Is_Inside_You_cannot_scan_barcode'

								COMMIT TRAN
								RETURN

				  END
			
				--Note its work for only servo or tmc line, not work for stmc	 
				--Check part exists in product master
						IF NOT EXISTS
						(
							select distinct 1 from product_master(nolock) where warehouse_cd=@ProfitCenterCode and SEWS_PART_NO =@PartNumber  and pt_part_type=
							(select LT.LineTypeName from LineTypeMst(nolock) LT inner join LineMst(nolock) LM on LT.LineTypeCode =LM.LineTypeCode where LM.LineCode=@LineCode) 
						)
						begin
									--SELECT 'PART_DOES_NOT_EXISTS_IN_PRODUCT_MASTER'
									SET @RETURNINT=1
									SET @RETURNVALUE='PART_DOES_NOT_EXISTS_IN_PRODUCT_MASTER'
								
									--update incorrect label
									if @OperationCode <>@FinalViewing_OperationCode
									begin
											exec Assy_proc_IncorrectLabel_Manage @CONDITION='update',@LineCode=@LINECODE,@OperationCode=@OPERATIONCODE
											,@BARCODE=@Barcode,@HMIMEssage='PART_DOES_NOT_EXISTS_IN_PRODUCT_MASTER'
									end			
									COMMIT TRAN
									--PRINT 'A'
									RETURN
						end

				--check part  active in product master
					IF NOT EXISTS
					(
						select distinct 1 from product_master(nolock) where warehouse_cd=@ProfitCenterCode and SEWS_PART_NO =@PartNumber and STS_CD =0  and pt_part_type=
						(select LT.LineTypeName from LineTypeMst(nolock) LT inner join LineMst(nolock) LM on LT.LineTypeCode =LM.LineTypeCode where LM.LineCode=@LineCode) 
					)
					begin
								--SELECT 'PART_NOT_ACTIVE_IN_PRODUCT_MASTER'
								SET @RETURNINT=1
								SET @RETURNVALUE='PART_NOT_ACTIVE_IN_PRODUCT_MASTER'

								--update incorrect label
								if @OperationCode <>@FinalViewing_OperationCode
								begin
										exec Assy_proc_IncorrectLabel_Manage @CONDITION='update',@LineCode=@LINECODE,@OperationCode=@OPERATIONCODE
										,@BARCODE=@Barcode,@HMIMEssage='PART_NOT_ACTIVE_IN_PRODUCT_MASTER'
								end
								COMMIT TRAN
								RETURN
					end

				--Check scanned part is curently running part OR NOT
					IF  EXISTS
					(
						--select distinct 1 from product_master(nolock) where warehouse_cd=@ProfitCenterCode  and STS_CD =0  
						--and pt_part_type=
						--(
						--	select LT.LineTypeName from LineTypeMst(nolock) LT inner join LineMst(nolock) LM on LT.LineTypeCode =LM.LineTypeCode where LM.LineCode=@LineCode
						--) 
						--AND  SEWS_PART_NO =
