CREATE proc [dbo].[Assy_proc_TallyChart_GUI_Status]
(
@Condition varchar(100),
@Authorize_Assembly bit =0,
@Authorize_Child bit =0,
@Authorize_TallyChart bit =0,
@Show_Material bit=0,
@Save_Material bit=0,
@Print_Material bit=0,
@profitCenterCode varchar(10)=NULL,
@UserId varchar(20)=NULL,
@ReturnValue as varchar(2000) output,
@ReturnInt as int output  
)
as
begin

--<Author:-Ravishankar Mishra>
--<Date:-17/11/14>

-- To Rembember
-- Nothing = 0
-- Success = 1
-- Error = 2
-- AlreadyExists = 3
-- NotExists = 4

		SET NOCOUNT ON

		BEGIN TRY
		if @Condition='Update'
		begin
					if exists
					(
						select 1 from Assy_TallyChart_GUI_Status(nolock)
					)
					begin

							  update Assy_TallyChart_GUI_Status
								set  Authorize_Assembly=@Authorize_Assembly
								, Authorize_Child=@Authorize_Child
								,Authorize_TallyChart=@Authorize_TallyChart
								, Show_Material=@Show_Material
								, Save_Material=@Save_Material
								, Print_Material=@Print_Material
								, timestamp=getdate()
								, UserId=@userid

					end
					else
						begin

						insert into Assy_TallyChart_GUI_Status
						(
						Authorize_Assembly,Authorize_Child,Authorize_TallyChart,Show_Material,Save_Material,Print_Material,timestamp,UserId
						)
						select @Authorize_Assembly,@Authorize_Child,@Authorize_TallyChart,@Show_Material,@Save_Material,@Print_Material,getdate(),@UserId


						end

						set @ReturnInt=1
						set @ReturnValue ='Updated'

		end
		else if @condition='delete'
		begin

			delete Assy_TallyChart_GUI_Status
			set @ReturnInt=1
			set @ReturnValue ='deleted'

		end

		else if @Condition='select'
		begin
			
			 declare @VAlue varchar(10)
				select @VAlue=PARAMETER_VALUE from PARAMETER_MST(nolock)  where PARAMETER_C ='AssLine' 
                 and PARAMETER_C1 ='Tally_Chart' and PARAMETER_C2 ='Validate_Material' 
				 --and wh_code=@profitCenterCode
				 
				 --if  @VAlue='Y'
				 --begin
				 
						select 
						Authorize_Assembly,
						Authorize_Child,
						Authorize_TallyChart,
						Show_Material,
						Save_Material,
						Print_Material					
						from Assy_TallyChart_GUI_Status(nolock)
				----end

				----Else if  @VAlue='N'
				---- begin
				 
				--		select 
				--		Authorize_Assembly,
				--		false Authorize_Child,
				--		Authorize_TallyChart,
				--		0 Show_Material,
				--		0 Save_Material,
				--		0	Print_Material				
				--		from Assy_TallyChart_GUI_Status(nolock)
				--end


				set @ReturnInt=1
			    set @ReturnValue ='select'
		end

		else if @condition ='Check_Child_Validation_Required'
		begin

		      
				select @VAlue=PARAMETER_VALUE from PARAMETER_MST(nolock)  where PARAMETER_C ='AssLine' 
                 and PARAMETER_C1 ='Tally_Chart' and PARAMETER_C2 ='Validate_Material' 
				 and wh_code=@profitCenterCode
				 
				 set @ReturnInt=1
			    set @ReturnValue =@VAlue

		end



		END TRY 
       BEGIN CATCH  



		SET @ReturnValue =	CAST(ERROR_NUMBER() as varchar(5)) + '|' + 
		CAST(ERROR_SEVERITY()as varchar(5)) + '|' + 
		CAST(ERROR_STATE() as varchar(5)) + '|' + 
		CAST(ERROR_PROCEDURE() as varchar(200)) + '|' + 
		CAST(ERROR_LINE() as varchar(5)) + '|' + 
		CAST(ERROR_MESSAGE() as varchar(1500))
							
		SET @ReturnInt = 2
		select @ReturnInt,@ReturnValue
		--SELECT @ReturnValue
	--CATCH BLOCK ENDS 
	END CATCH

end




GO
