CREATE PROC [dbo].[Assy_Proc_TallyChartStatus]
(
	@QueryExecuteOption VARCHAR(300), 
	@ProfitCenterCode VARCHAR(10) = NULL, 
	@LineCode VARCHAR(10) = NULL, 
	@StationCode VARCHAR(10) = NULL, 
	@DateCode CHAR(4) = NULL, 
	@MachineCode VARCHAR(10) = NULL, 
	@OperationCode VARCHAR(10) = NULL, 
	@ASSYTABLE ASSY_TABLE_TYPE READONLY, 
	@ASSY_MATERIALSTATUSTBL ASSY_MATERIALSTATUSTBL_TYPE READONLY, 
	@ProductionOrderNo VARCHAR(40) = NULL, 
	@Serial_No VARCHAR(20) = NULL, 
	@ChildPartNo VARCHAR(60) = NULL, 
	@Req_Status VARCHAR(10) = NULL, 
	@UserID VARCHAR(10) = '', 
	@DateCodeForMaterialReprint CHAR(4) = NULL, 
	@ReturnValue AS VARCHAR(MAX) = NULL OUTPUT, 
	@ReturnInt AS INT = -1 OUTPUT
)
AS
BEGIN
	-- =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  = 
	-- Author:			< Ravi Shankar Mishra >
	-- Create Date:		< 27 JULY 2014 >
	-- Description:		< Tally Chart Status >
	-- Modified By:		< Rashid Siddiqui > 
	-- Modified ON:		< 16-Nov-2016 > 
	-- Description:		< NOT Consider Engraving Station AND Move Tally Chart Data INTO Central Server >
	-- Modified ON:		< 30-Dec-2016 > 
	-- Description:		< Do NOT Mark Scrap/Rework IF any Barcode IS Pass/Fail during Tally Chart Processing. Refresh the Data. >
	-- Modified ON:		< 05-May-2017 > 
	-- Description:		< Optimize the Query - Remove NOT necessary Order By, Top , DISTINCT, Inline Query, Cusrsor, Loop >
	-- Modified ON:		< 11-May-2017 > 
	-- Description:		< Remove Negative Tally Chart - Coupling Station IS there after First Stattion >
	-- Modified By:		< Sudesh Kumar > 
	-- Modified ON:		< 20170515 > 
	-- Description:		< Added column ProductionOrderNo IN Table Assy_LineAssyStatus_Running for mapping of Production Order with Barcode >
	-- Modified By:		< Rashid Siddiqui > 
	-- Modified ON:		< 20170606 > 
	-- Description:		< DELETE Coupling Record IF any EXISTS >
	-- Modified ON:		< 20170727 > 
	-- Description:		< For optimizing of Scrapping of Barcodes IN Scrap OR Reowrk Block >
	-- Modified ON:		< 20170816 >
	-- Description:		< Added ScanTimeStamp On Pass/Fail Barcode >
	-- Modified By:		< Rashid Siddiqui > 
	-- Modified ON:		< 20171128 >
	-- Description:		< Tally Chart Data moved to Central Server by Flag basis (@QueryExecuteOption = 'REQNOAUTH')>
	-- Modified ON:		< 20171130 >
	-- Description:		< Sync will not happen at Tally Chart time; supervisor has to do by button click as and when require >	
	-- Modified ON:		< 20190424 >
	-- Description:		< Update MES Set Parameter Table on Tally Chart >
	-- Modified ON:		< 20190828 >
	-- Description:		< Delink of Bore Mix Up Barcode if marked in case of Fail or Rework in Tally Chart >

	-- =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  =  = 
	/*
	SELECT * FROM Assy_LineAssyParamData_Running
	SELECT * FROM Assy_RunningPart
	EXEC Assy_Proc_TallyChartStatus @QueryExecuteOption = 'FETCH', @ProfitCenterCode = '0021', @LineCode = 'M07'
	EXEC Assy_Proc_TallyChartStatus @QueryExecuteOption = 'AUTO_TALLY_CHART', @ProfitCenterCode = '0021', @LineCode = 'M03'
	*/	
	SET NOCOUNT ON;
	DECLARE @AssyPartNo VARCHAR(60),  @Assy_PartNo VARCHAR(60),@OperationSeqNo NUMERIC(18, 0) = 0, @LineTypeName VARCHAR(20), @PartType VARCHAR(10), @ExecQuery AS NVARCHAR(MAX), @LinkServerName VARCHAR(200) = '',
			@ResultVar VARCHAR(10) = ''
	DECLARE @TotRecords AS INT, @TempMachineCode VARCHAR(30), @TotTallyChartDupRecords INT, @RowCountStart INT = 1, @FailCount INT = 0, @EngravingMachineCode VARCHAR(20) = ''
	DECLARE @DayWiseTimeStamp datetime
	DECLARE  @LoopCount INT = 0, @AutoID INT = 1, @Machine1 VARCHAR(50) = '', @Machine2 VARCHAR(50) = '', @CouplingMachineCode VARCHAR(50) = ''
	
	IF ISNULL(@Req_Status, '') = 'LOOP_TALLY'
	BEGIN
		SELECT Top 1 @Assy_PartNo = Assy_PartNo, @DateCode = DateCode
			FROM Assy_RunningPartFamily (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode AND ISNULL(IsAutoComplete,0) = 0
	END
	ELSE
	BEGIN
	SELECT Top 1 @AssyPartNo = Assy_PartNo, @DateCode = DateCode, @ProductionOrderNo = ProductionOrderNo, @ProfitCenterCode = ProfitCenterCode, @PartType = ISNULL(PartType, '')
		FROM Assy_RunningPart (NOLOCK) WHERE LineCode = @LineCode -- AND Assy_Mode IN ('Production', 'Rework') --Order By CreatedDate Desc
	END	
	DECLARE @Frequency_Value INT
	Declare @MachineLinkServerName varchar(100)						-- ADDED BY Rashid 20190424
			, @MachineLinkServerDB varchar(100)						-- ADDED BY Rashid 20190424
			, @MachineLinkServer varchar(300)						-- ADDED BY Rashid 20190424
			, @MachineDBTableName varchar(100)						-- ADDED BY Rashid 20190424
			, @Dynamic_Query VARCHAR(MAX) = ''						-- ADDED BY Rashid 20190424
			, @LinkServerType VARCHAR(60) = ''						-- ADDED BY Rashid 20190424
	SELECT @LinkServerName = LinkServerName + '.' + DataBaseName + '.dbo.' FROM Assy_LinkServer_Dtl (NOLOCK) 
		WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode

	
		CREATE Table #MachineCodeLoop
		(
			AutoID TINYINT IDENTITY(1, 1), 
			OperationSeqNo INT, 
			MachineCode VARCHAR(50)
		)

		CREATE Table #AlternateMachineCodeLoop
		(
			AutoID TINYINT IDENTITY(1, 1), 
			OperationSeqNo INT, 
			MachineCode VARCHAR(50)
		)

		DECLARE @Assy_LineAssyParamData_Running_Dtl as table 
		(
			[UID] [uniqueidentifier] NOT NULL
		)

	--CHECK REQUESTION NO IS OR PRODUCTION NO OR PURCHASE Order NO IS AUTHORIZED OR NOT
	IF @QueryExecuteOption = 'REQNOAUTH_CHECK'
	BEGIN 
		SELECT * INTO #Assy_ProductionOrderMst FROM Assy_ProductionOrderMst (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
		--Added By Ravi Mishra ON 12/11/14
		IF NOT EXISTS
		(
			SELECT 1 FROM #Assy_ProductionOrderMst
		)
		BEGIN				
			SELECT @ReturnValue = 'PRODUCTION Order NO. HAS NOT DEFINE FOR  ASSEMBLY LINE.', @ReturnInt = 3
			SELECT @ReturnValue, @ReturnInt
			RETURN
		END

		IF NOT EXISTS
		(
			SELECT 1 FROM #Assy_ProductionOrderMst WHERE IsActive = 1
			--SELECT 1 FROM Assy_ProductionOrderMst (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND IsActive = 1
		)
		BEGIN
			SELECT @ReturnValue = 'PRODUCTION Order NO. HAS  DEFINE BUT NOT Active FOR  ASSEMBLY LINE.', @ReturnInt = 3
			SELECT @ReturnValue, @ReturnInt
			RETURN
		END

		IF NOT EXISTS
		(
			SELECT 1 FROM #Assy_ProductionOrderMst PO INNER JOIN LineMst (NOLOCK) LM ON PO.WorkCenterCode = LM.WorkCenterCode
				WHERE PO.ProfitCenterCode = @ProfitCenterCode AND PO.IsActive = 1 AND LM.ProfitCenterCode = @ProfitCenterCode AND LM.IsActive = 1
		)
		BEGIN
			SELECT @ReturnValue = 'PRODUCTION Order NO. HAS NOT DEFINE  FOR THIS ASSEMBLY LINE.', @ReturnInt = 3
			SELECT @ReturnValue, @ReturnInt
			RETURN
		END

		IF EXISTS(SELECT Status FROM #Assy_ProductionOrderMst WHERE OrderNo = @ProductionOrderNo AND Status = 'C')
		--IF EXISTS(SELECT Status FROM Assy_ProductionOrderMst (NOLOCK) WHERE OrderNo = @ProductionOrderNo AND ProfitCenterCode = @ProfitCenterCode AND Status = 'C')
		BEGIN
			SELECT @ReturnValue = 'SELECTED REQUISITION NO. IS CLOSED.', @ReturnInt = 1
			SELECT @ReturnValue, @ReturnInt
			RETURN
		END

		IF EXISTS
		(
			SELECT ISNULL(Status, '') FROM #Assy_ProductionOrderMst WHERE OrderNo = @ProductionOrderNo AND Status = 'H' 
			--SELECT ISNULL(Status, '') FROM Assy_ProductionOrderMst (NOLOCK) WHERE OrderNo = @ProductionOrderNo AND ProfitCenterCode = @ProfitCenterCode AND Status = 'H' 
				AND ISNULL(BalanceQty, 0) < = ISNULL(ProducedQty, 0)
		)
		BEGIN
			SELECT @ReturnValue = 'SELECTED REQUISITION NO. IS ON HOLD.', @ReturnInt = 2
			SELECT @ReturnValue, @ReturnInt
			RETURN
		END
		ELSE
		BEGIN
			SELECT @ReturnValue = 'SELECTED REQUISITION NO. IS OPEN.', @ReturnInt = 0
			SELECT @ReturnValue, @ReturnInt
			RETURN
		END
	END

	--AUTHORIZE REQUESTION NO IS OR PRODUCTION NO OR PURCHASE Order
	ELSE IF @QueryExecuteOption = 'REQNOAUTH'
	BEGIN 
		
		declare @mydate datetime = getdate()
		print convert(vaRCHAR,@mydate,121)
		print '----1------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()

		insert into process_log([prg_name],barcodes,[ent_dt],[remarks])
		values('Tally Chart : REQNOAUTH','Main Process Start',convert(varchar,getdate(),121),'PROCESS START')

		BEGIN TRY
		--SET @QueryExecuteOption = 'INSERT_TALLY_DATA_TO_MAIN_SERVER'
		-- added by Sachin 20190418

		IF EXISTS
		(
			SELECT TOP 1 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
				AND LineCode = @LineCode AND KeyType = 'SetParameterMESTableUpdateOnTallyChart' AND ISNULL(KeyValue,'0') = '1'
		)
		BEGIN
			SELECT TOP 1 @MachineLinkServerName = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode 
				AND LineCode = @LineCode AND KeyType = 'MachineDBLinkServerName' AND STS_CD = 0
				
			IF(ISNULL(@MachineLinkServerName,'') = '' )
			BEGIN
				SET @ReturnValue = 'Machine Link Server Name Configuration Not Found !! [RoutingConfigDetails Key: MachineDBLinkServerName] '
				SET @ReturnInt = 2
				RETURN
			END

			SELECT TOP 1 @MachineLinkServerDB = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
				AND LineCode = @LineCode AND KeyType = 'MachineDBLinkServerDB' AND STS_CD = 0

			IF(ISNULL(@MachineLinkServerDB,'') = '' )
			BEGIN
				SET @ReturnValue = 'Machine Link Server Database Configuration Not Found !! [RoutingConfigDetails Key: MachineDBLinkServerDB]'
				SET @ReturnInt = 2
				RETURN
			END

			SELECT TOP 1 @MachineDBTableName = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
				AND LineCode = @LineCode AND KeyType = 'MachineDBSetParameterTableName' AND STS_CD = 0

			IF(ISNULL(@MachineDBTableName,'') = '' )
			BEGIN
				SET @ReturnValue = 'Link Server Set Parameter Table Name Configuration Not Found !! [RoutingConfigDetails Key: MachineDBSetParameterTableName]'
				SET @ReturnInt = 2
				RETURN
			END

			SELECT TOP 1 @LinkServerType = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode
				AND LineCode = @LineCode AND KeyType = 'LinkServerType' AND STS_CD = 0

			IF(ISNULL(@LinkServerType,'') = '' )
			BEGIN
				SET @ReturnValue = 'Link Server Type Parameter Configuration Not Found !! [RoutingConfigDetails Key: LinkServerType]'
				SET @ReturnInt = 2
				RETURN
			END

			BEGIN TRY
				Declare @s sysname = REPLACE(REPLACE(@MachineLinkServerName,'[',''),']','')
				EXEC sys.sp_testlinkedserver @s
			END TRY
			BEGIN CATCH
				SET @ReturnValue = 'Kindly Check, Not Able To Connect MES SQL Server !!! ' + @MachineLinkServerName
				SET @ReturnInt = 2
				insert into process_log([prg_name],barcodes,[ent_dt],[remarks])
				values('Tally Chart : sp_testlinkedserver','sp_testlinkedserver',convert(varchar,getdate(),121),@ReturnValue)
				RETURN
			END CATCH

			IF(@LinkServerType = 'MSSQL')
			BEGIN
				SET @MachineLinkServer = @MachineLinkServerName + '.' + @MachineLinkServerDB
				SET @MachineLinkServer = REPLACE(@MachineLinkServer,'TABLE_NAME',@MachineDBTableName)
				PRINT 'LinkServer - ' + @MachineLinkServer

				SET @Dynamic_Query = '
					UPDATE ' + ISNULL(@MachineLinkServer,'') + ' SET STS_CD = CONVERT(varchar, 1)'
				PRINT @Dynamic_Query
				EXEC (@Dynamic_Query)
			END

			IF(@LinkServerType = 'MYSQL')
			BEGIN
				PRINT 'MYSQL Connection Code Required'
			END
		END
		
		print '----2------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()

		IF Object_ID('Assy_TallyChartStatusData_WIP_LOG') IS NOT NULL
		BEGIN
			insert into Assy_TallyChartStatusData_WIP_LOG
			select * from Assy_TallyChartStatusData (nolock) where Reason='WIP'

			delete t2 from Assy_TallyChartStatusData(nolock) t
			inner join Assy_TallyChartStatusData(nolock) t2
			on t.barcode = t2.Barcode
			where t.Reason='WIP'	
			-- ended by Sachin 20190418
		END
		--Added By Sachin 20190604

		BEGIN TRY
			Declare @bils sysname ;
			select Top 1 @bils=REPLACE(REPLACE(LinkServerName,'[',''),']','')  
			from Assy_LinkServer_Dtl(nolock) where ProfitCenterCode=@ProfitCenterCode
			and LineCode=@LineCode
			EXEC sys.sp_testlinkedserver @bils

		END TRY
		BEGIN CATCH
				SET @ReturnValue = 'Kindly Check, Not Able To Connect Central SQL Server !!! ' + convert(varchar,@bils)
				SET @ReturnInt = 2
				insert into process_log([prg_name],barcodes,[ent_dt],[remarks])
				values('Tally Chart : sp_testlinkedserver','sp_testlinkedserver 1',convert(varchar,getdate(),121),@ReturnValue)
				RETURN
		END CATCH

		BEGIN TRY
		print '----3------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()

		insert into process_log([prg_name],barcodes,[ent_dt],[remarks])
		values('Tally Chart : REQNOAUTH','INSERT_TALLY_DATA_TO_MAIN_SERVER',convert(varchar,getdate(),121),'PROCESS START')

		EXEC Assy_Proc_TallyChartStatus @QueryExecuteOption = 'INSERT_TALLY_DATA_TO_MAIN_SERVER', 
		@LineCode = @LineCode, @ProfitCenterCode = @ProfitCenterCode

		insert into process_log([prg_name],barcodes,[ent_dt],[remarks])
		values('Tally Chart : REQNOAUTH','INSERT_TALLY_DATA_TO_MAIN_SERVER',convert(varchar,getdate(),121),'PROCESS END')


		print '----4------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()

		insert into process_log([prg_name],barcodes,[ent_dt],[remarks])
		values('Tally Chart : REQNOAUTH','INSERT_BYPASS_POKA_YOKE_IN_MAIN_SERVER',convert(varchar,getdate(),121),'PROCESS START')

		EXEC Assy_Proc_UpdatePokaYokeStatus @Condition = 'INSERT_BYPASS_POKA_YOKE_IN_MAIN_SERVER', 
		@LineCode = @LineCode, @ProfitCenterCode = @ProfitCenterCode
		
		insert into process_log([prg_name],barcodes,[ent_dt],[remarks])
		values('Tally Chart : REQNOAUTH','INSERT_BYPASS_POKA_YOKE_IN_MAIN_SERVER',convert(varchar,getdate(),121),'PROCESS END')

		print '----5------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()

		--Start-Added By RS 20190828 - Delink of Bore Mix Up Barcode if marked as Fail or Rework in Tally Chart
		IF EXISTS
			(
				SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
					AND KeyType = 'IsBoreViewingMixUpRequired' AND KeyValue = '1'
			)
			BEGIN
				Declare @Curr_MachineCode VARCHAR(20) = '', @MixUpOperationCode VARCHAR(20) = ''
				
				SELECT @MixUpOperationCode = KeyValue FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
					AND KeyType = 'MixUpOperationCode'
				
				SELECT @Curr_MachineCode = MachineCode FROM RoutingConfigLineWise WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
					AND OperationCode = @MixUpOperationCode

				SELECT Barcode, MachineCode, NotProcessedStatus, Result INTO #Assy_TallyChartStatusData_BMU FROM Assy_TallyChartStatusData(NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
				
				IF EXISTS (SELECT Top 1 1 FROM #Assy_TallyChartStatusData_BMU WHERE MachineCode = @Curr_MachineCode)
				BEGIN
					IF OBJECT_ID('Barcode_BMU') IS NOT NULL 
					BEGIN 
						DROP TABLE Barcode_BMU
					END
					SELECT Distinct Barcode INTO Barcode_BMU FROM #Assy_TallyChartStatusData_BMU WHERE (ISNULL(NotProcessedStatus,'') != '' OR Result = 'FAIL')

					IF EXISTS (SELECT 1 FROM Barcode_BMU)
					BEGIN
						INSERT INTO Assy_BoreInspection_Result_History(ProfitCenterCode,LineCode,DateCode,PartNo,Barcode,Status,ReasonCode,Remark,IsRework,IsMapped,TSBarcode,ScanTimeStamp,
							Scan_By,ResultTimeStamp,MappedTimeStamp,ResultUpdated_By,Hist_Upd_Stamp,Hist_Upd_By,IsLocked,LockedTimeStamp)
						SELECT A.ProfitCenterCode,A.LineCode,A.DateCode,A.PartNo,A.Barcode,A.Status,A.ReasonCode,A.Remark,A.IsRework,A.IsMapped,A.TSBarcode,A.ScanTimeStamp,
							A.Scan_By,A.ResultTimeStamp,A.MappedTimeStamp,A.ResultUpdated_By,GETDATE(),@UserID,A.IsLocked,A.LockedTimeStamp
						FROM Barcode_BMU B
							JOIN Assy_BoreInspection_Result (NOLOCK) A
								ON B.Barcode = A.TSBarcode

						UPDATE A SET A.IsMapped = 0, A.MappedTimeStamp = NULL, A.TSBarcode = ''
							FROM Barcode_BMU B
								JOIN Assy_BoreInspection_Result (NOLOCK) A
									ON B.Barcode = A.TSBarcode

						DELETE A FROM Barcode_BMU B
							JOIN Assy_TS_Bracket_Barcode_Mapping (NOLOCK) A
								ON B.Barcode = A.TSBarcode

						SET @ExecQuery = ''
						SET @ExecQuery = 'Update C SET C.IsMapped = 0, C.MappedTimeStamp = NULL, C.TSBarcode = NULL FROM ' + @LinkServerName + 'Assy_BoreInspection_Result C
						JOIN Barcode_BMU L
						ON C.TSBarcode = L.Barcode'

						PRINT @ExecQuery
						EXECUTE (@ExecQuery)
					END
				END
			END
		--END-Added By RS 20190828 - Delink of Bore Mix Up Barcode if marked as Fail or Rework in Tally Chart

		END TRY
		BEGIN CATCH			
			SET @ReturnValue = 	CAST(ISNULL(ERROR_NUMBER(),0) AS VARCHAR(5)) + '|' + 
			CAST(ISNULL(ERROR_SEVERITY(),0)AS VARCHAR(5)) + '|' + 
			CAST(ISNULL(ERROR_STATE(),0) AS VARCHAR(5)) + '|' + 
			CAST(ISNULL(ERROR_PROCEDURE(),'') AS VARCHAR(200)) + '|' + 
			CAST(ISNULL(ERROR_LINE(),0) AS VARCHAR(5)) + '|' + 
			CAST(ISNULL(ERROR_MESSAGE(),'') AS VARCHAR(1500))
			SET @ReturnInt = 2				
			insert into process_log([prg_name],barcodes,[ent_dt],[remarks])
			values('Tally Chart : REQNOAUTH','REQNOAUTH',convert(varchar,getdate(),121),@ReturnValue)		
			RETURN
		END CATCH
		--Ended By Sachin 20190604

		BEGIN TRAN

		SELECT * INTO #Assy_TallyChartStatusData FROM Assy_TallyChartStatusData (NOLOCK)

		insert into process_log([prg_name],barcodes,[count],[ent_dt],[remarks])
		values('Tally Chart : REQNOAUTH','DataCount',@@rowcount,convert(varchar,getdate(),121),'')
		 
		SELECT DISTINCT Barcode INTO #Assy_TallyChartStatusData_Barcode FROM #Assy_TallyChartStatusData

		--Added By Rashid For Poka Yoke disable IN Rework mode ON 30th June 2016
		IF EXISTS (SELECT 1 FROM Assy_Rework_PokaYoke_Status WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(PokaYokeMandatoryStatus, 0) = 1)
		BEGIN
			UPDATE LineMst SET isPokaYokeMandatory = 1 WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(isPokaYokeMandatory, 0) = 0
			UPDATE Assy_Rework_PokaYoke_Status SET PokaYokeMandatoryStatus = 0, Ent_TimeStamp = GETDATE() WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
		END
		--Added By Rashid For Poka Yoke disable IN Rework mode ON 30th June 2016
		
		print '----6------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()
		
		--UPDATE AssyStatus Table------------------------------------------------------------------------------------------------------------------
		UPDATE Assy_LineAssyStatus SET IsTallyChartApproved = 1
		WHERE RTRIM(LTRIM(LineCode)) = @LineCode AND RTRIM(LTRIM(ProfitCenterCode)) 
		= @ProfitCenterCode AND ISNULL(IsTallyChartApproved, 0) = 0 
		AND Barcode IN (SELECT Barcode FROM #Assy_TallyChartStatusData_Barcode)

		UPDATE Assy_LineAssyStatus_Running SET IsTallyChartApproved = 1
		WHERE RTRIM(LTRIM(LineCode)) = @LineCode AND RTRIM(LTRIM(ProfitCenterCode)) 
		= @ProfitCenterCode AND ISNULL(IsTallyChartApproved, 0) = 0
		AND Barcode IN (SELECT Barcode FROM #Assy_TallyChartStatusData_Barcode)

		---UPDATE Tally Chart RELEATED TABLES-------------------------------------------------------------------------------------
		IF @Req_Status = 'H'
			SET @Req_Status = '140'
		ELSE IF @Req_Status = 'C'
			SET @Req_Status = '100'
		
		print '----7------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()

		UPDATE Assy_TallyChartStatusData SET Assy_Auth = 1 WHERE ProfitCenterCode = @ProfitCenterCode 
		AND LineCode = @LineCode AND DateCode = @DateCode AND ISNULL(Assy_Auth, 0) = 0

		--DELTE CURRENT RUNNING PATR ---------------------------------------------------------------------------------------------		
		UPDATE Assy_RunningPart SET IsAuthorized = 1 WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode

		print '----8------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()

		DELETE  Assy_RunningPart  WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
		DELETE FROM Assy_ProductionOrder_ParameterSetting WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode

		DELETE FROM Assy_RunningPart_Previous WHERE LineCode = @LineCode
		UPDATE Assy_Scan_OK SET IsScan = 0, Barcode = '' WHERE LineCode = @LineCode
		
		print '----9------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()

		--RESET ALL WIP RELATED TABLES
		EXEC Assy_Proc_WIP_Manage @Condition = 'RESET_WIP_RELEATED_TABLES', @LineCode = @LineCode

		UPDATE Assy_PartWise_PassFail_Count SET IsAuthorized = 1 WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode AND ISNULL(IsAuthorized, 0) = 0
		
		print '----10------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()

		--RESET ASSY_TALLYCHART_APPROVAL_PENDING Table
		EXEC ASSY_PROC_TALLYCHART_APPROVAL_PENDING @Condition = 'RESET_PENDING_STATUS', @ProfitCenterCode = @ProfitCenterCode, @LineCode = @LineCode
		
		print '----11------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()

		-- DELETE PRINTED Barcode COUNTER FROM Table ASSY_BARCODE_PRINTED_COUNTER
		EXEC Assy_Proc_Barcode_Printed_Counter @Condition = 'DELETE', @LineCode = @LineCode, @ProfitCenterCode = @ProfitCenterCode
		
		print '----12------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()

		/* Commented By RS On 30-Nov-2017 (20171130) as agreed by MKN sir (Sync will not happen at Tally Chart time; supervisor has to do by button click as and when require)
		--SYNC ALL MASTER TABLES
		EXEC ASSY_PROC_SYNC_MASTERS_DATA @LineCode = @LineCode, @ProfitCenterCode = @ProfitCenterCode, @UserName = @UserID, @UIInterfaceName = 'Tally Chart'
		*/
		DELETE FROM Assy_RunningPart_Type WHERE LineCode = @LineCode

		print '----13------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()

		--Added By Rashid On 20180611 for removing already inserted record (Barcode(s)) IN Table Assy_LineAssyStatus
		DELETE FROM A
			FROM Assy_LineAssyStatus_Running (NOLOCK) R
				INNER JOIN Assy_LineAssyStatus (NOLOCK) A
					ON A.ProfitCenterCode = R.ProfitCenterCode AND A.LineCode = R.LineCode AND A.MachineCode = R.MachineCode AND A.OperationCode = R.OperationCode
						--AND A.Barcode = R.Barcode AND A.Datecode = R.Datecode AND A.PartNo = R.PartNo
							AND A.Barcode = R.Barcode AND A.PartNo = R.PartNo
								WHERE R.LineCode = @LineCode AND R.ProfitCenterCode = @ProfitCenterCode AND R.DateCode ! = 'PKYK'

		print '----14------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()
		--Added By Rashid On 20180611 for removing already inserted record (Barcode(s)) IN Table Assy_LineAssyStatus

		--Modified By Sudesh on 20170515 for new column ProductionOrderNo IN Table Assy_LineAssyStatus_Running
		INSERT INTO Assy_LineAssyStatus
		(
			ProfitCenterCode, 
			LineCode, 
			MachineCode, 
			OperationCode, 
			StationCode, 
			Barcode, 
			Status, 
			FailCount, 
			DateCode, 
			PartNo, 
			ScanTimeStamp, 
			ResultTimeStamp, 
			Active, 
			UserID, 
			IsTallyChartApproved,
			ProductionOrderNo,
			PROD_LOT_NO, -- Added by Sachin 20170828
			Live_Datecode
		)
		
		SELECT 
			ProfitCenterCode, 
			LineCode, 
			MachineCode, 
			OperationCode, 
			StationCode, 
			Barcode, 
			Status, 
			FailCount, 
			DateCode, 
			PartNo, 
			ScanTimeStamp, 
			ResultTimeStamp, 
			Active, 
			UserID, 
			IsTallyChartApproved,
			ProductionOrderNo,
			PROD_LOT_NO ,-- Added by Sachin 20170828
			Live_Datecode
		FROM Assy_LineAssyStatus_Running (NOLOCK) WHERE LineCode = @LineCode 
			AND ProfitCenterCode = @ProfitCenterCode AND DateCode ! = 'PKYK'
				AND Barcode IN (SELECT Barcode FROM #Assy_TallyChartStatusData_Barcode)
				
		DELETE Assy_LineAssyStatus_Running WHERE LineCode = @LineCode 
			AND ProfitCenterCode = @ProfitCenterCode AND DateCode ! = 'PKYK'
				AND Barcode IN (SELECT Barcode FROM #Assy_TallyChartStatusData_Barcode)
		
		print '----15------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()
									
		--Modified By Ravi ON 22-03-16
		--INSERT DATA FROM Assy_LineAssyParamData_Running INTO Assy_LineAssyParamData FOR CURENT Barcode AND LINE CODE
		--Added By Rashid On 20170816 to include ScanTimeStamp
		INSERT INTO Assy_LineAssyParamData
		(
			[ProfitCenterCode]
			, [LineCode]
			, [MachineCode]
			, [OperationCode]
			, [StationCode]
			, [Barcode]
			, [TagName]
			, [Value]
			, [Result]
			, [DateCode]
			, [UserID]
			, [TimeStamp]
			, PartNo
			, UID
			, ScanTimeStamp
			, CaliperDatecode
			, CaliperSrNo
			,Live_Datecode
		)
		SELECT
			[ProfitCenterCode]
			, [LineCode]
			, [MachineCode]
			, [OperationCode]
			, [StationCode]
			, [Barcode]
			, [TagName]
			, [Value]
			, [Result]
			, [DateCode]
			, [UserID]
			, [TimeStamp]
			, PartNo
			, UID
			, ScanTimeStamp
			, CaliperDatecode
			, CaliperSrNo
			,Live_Datecode
		FROM Assy_LineAssyParamData_Running (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
			AND Barcode IN (SELECT Barcode FROM #Assy_TallyChartStatusData_Barcode)
		
		print '----16------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()

		--Added By Sachin 20181211
		INSERT INTO @Assy_LineAssyParamData_Running_Dtl(UID)
		SELECT DISTINCT [UID] FROM  Assy_LineAssyParamData_Running WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
			AND Barcode IN (SELECT Barcode FROM #Assy_TallyChartStatusData_Barcode)	AND uid IS NOT NULL
		--Ended By Sachin
											
		DELETE Assy_LineAssyParamData_Running WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
			AND Barcode IN (SELECT Barcode FROM #Assy_TallyChartStatusData_Barcode)

		DELETE FROM Assy_Vision_System WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
			AND Barcode IN (SELECT Barcode FROM #Assy_TallyChartStatusData_Barcode)

		print '----17------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()

		INSERT INTO Assy_TallyChartStatusData_History
		(
			[ProfitCenterCode], 
			[LineCode], 
			[DateCode], 
			[MachineCode], 
			[Barcode], 
			[Result], 
			[NotProcessedStatus],
			[Reason],
			[Remarks],
			[Assy_Auth],
			[UserID],
			[TimeStamp],
			[PartNo],
			[EntStamp]
		)
		SELECT
			[ProfitCenterCode], 
			[LineCode], 
			[DateCode], 
			[MachineCode], 
			[Barcode], 
			[Result], 
			[NotProcessedStatus], 
			[Reason], 
			[Remarks], 
			[Assy_Auth], 
			[UserID], 
			[TimeStamp], 
			[PartNo],
			GETDATE()
		FROM #Assy_TallyChartStatusData (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode

		DELETE FROM Assy_TallyChartStatusData WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
		DELETE FROM Assy_Vision_System_Last_Printed_Barcode WHERE LineCode = @LineCode
		
		print '----18------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()
							 
		--Modified By Ravi ON 22-03-16
		INSERT INTO Assy_LineAssyParamData_Dtl
		(
			UID, 
			TagId, 
			Value
		)
		SELECT UID, TagId, Value FROM  Assy_LineAssyParamData_Running_Dtl (NOLOCK)
			WHERE [UID] IN (SELECT [UID] FROM @Assy_LineAssyParamData_Running_Dtl)

		DELETE FROM Assy_LineAssyParamData_Running_Dtl
			WHERE [UID] IN (SELECT [UID] FROM @Assy_LineAssyParamData_Running_Dtl)
		-- DELETE Coupling Record IF any EXISTS - By Rashid On 20170606
		DELETE FROM Assy_Coupling_Temp
		
		IF OBJECT_ID('Assy_TS_NonTS_Barcode_Scan') IS NOT NULL
		BEGIN
			DELETE FROM Assy_TS_NonTS_Barcode_Scan WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
		END


		-- Added by Sachin 20190206
		-- Reset PokaYoke Components
		IF EXISTS
		(
			SELECT Top 1 1 FROM RoutingConfigDetails (NOLOCK) WHERE KeyType = 'ResetPokaYokeData' AND KeyValue = '1'
				AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
		)
		BEGIN
			DELETE FROM Assy_LineAssyStatus_Running WHERE Datecode = 'PKYK'
			DELETE FROM Assy_LineAssyParamData_Running_Dtl WHERE [UID] IN
			(
				SELECT [UID] FROM Assy_LineAssyParamData_Running WHERE Datecode = 'PKYK'
			)
			DELETE FROM Assy_LineAssyParamData_Running WHERE Datecode = 'PKYK'
		END
		-- Ended by Sachin 20190206

		-- Added by prerna 20200409
		-- Reset ekanban details
			IF EXISTS(SELECT TOP 1 1 FROM TYPE_DEFINITION_XREF_DATA(NOLOCK)
			WHERE ATTRB_CD=@LineCode AND TYPE_CATEGORY_CD='LINE_ATTRB'
			AND TYPE_CD='eKanban_Enable' AND WH_CODE=@ProfitCenterCode AND ATTRB_VAL='1')
			BEGIN

			delete from Assy_RunningKanban where isnull(isrunning,0)=0 and isnull(iscompleted,0)=0 
		    and LineCode=@LineCode and ProfitCenterCode=@ProfitCenterCode

			end

		-- Ended by Sachin 20200409
		print '----19------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()

		IF @Req_Status = '100'
		BEGIN				
			SELECT @ReturnValue = 'SELECTED REQUISITION NO. HAS BEEN CLOSED.', @ReturnInt = 1
			SELECT @ReturnValue, @ReturnInt
		END
		ELSE IF @Req_Status = '140'
		BEGIN
			SELECT @ReturnValue = 'SELECTED REQUISITION NO. HAS BEEN ON HOLD.', @ReturnInt = 2
			SELECT @ReturnValue, @ReturnInt
		END	
		print '----20------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
		set @mydate = getdate()

		insert into process_log([prg_name],barcodes,[ent_dt],[remarks])
		values('Tally Chart : REQNOAUTH','',convert(varchar,getdate(),121),'PROCESS END')

		COMMIT TRAN			  
		END TRY

		BEGIN CATCH
			--CATCH BLOCK BEGINS
			print '----30------ ' + convert(varchar,datediff(millisecond,@mydate,getdate()),121)
			set @mydate = getdate()

			SET @ReturnValue = 	CAST(ISNULL(ERROR_NUMBER(),0) AS VARCHAR(5)) + '|' + 
			CAST(ISNULL(ERROR_SEVERITY(),0) AS VARCHAR(5)) + '|' + 
			CAST(ISNULL(ERROR_STATE(),0) AS VARCHAR(5)) + '|' + 
			CAST(ISNULL(ERROR_PROCEDURE(),'') AS VARCHAR(200)) + '|' + 
			CAST(ISNULL(ERROR_LINE(),0) AS VARCHAR(5)) + '|' + 
			CAST(ISNULL(ERROR_MESSAGE(),'') AS VARCHAR(1500))
			SET @ReturnInt = 2
			ROLLBACK TRAN
			insert into process_log([prg_name],barcodes,[ent_dt],[remarks])
			values('Tally Chart : REQNOAUTH','REQNOAUTH 1',convert(varchar,getdate(),121),@ReturnValue)
			RAISERROR(@ReturnValue, 16, 1)
		END CATCH

		insert into process_log([prg_name],barcodes,[ent_dt],[remarks])
		values('Tally Chart : REQNOAUTH','Assy_Proc_ProductionOrder',convert(varchar,getdate(),121),'PROCESS START')

		SET @ExecQuery = ''
		SET @ExecQuery = 'EXEC ' + @LinkServerName + 'Assy_Proc_ProductionOrder  @Condition = ''DELTE_CURRENT_RUNNING_PATR_FROM_MAIN_SERVER'', 
						@LineCode = '''+ @LineCode +''', @ProductionOrderNo = '''+ @ProductionOrderNo +'''
						, @ProfitCenterCode = '''+ @ProfitCenterCode +''''
		
		EXECUTE SP_EXECUTESQL @ExecQuery
		--EXEC Assy_Proc_ShiftQty_Update @Condition = 'UPDATE_SHIFT_PRODUCE_QTY_IN_MAIN_SERVER', @ProfitCenterCode = @ProfitCenterCode, @LineCode = @LineCode
		insert into process_log([prg_name],barcodes,[ent_dt],[remarks])
		values('Tally Chart : REQNOAUTH','Main Process End',convert(varchar,getdate(),121),'PROCESS END')
		RETURN
	END
	
	--GET RUNNING PART NO
	ELSE IF @QueryExecuteOption = 'P'
	BEGIN 
		--TRUNCATE Table Assy_RunningPart
		SELECT Top 1 Assy_PartNo, LineCode, ProductionOrderNo, DateCode FROM Assy_RunningPart (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
		IF @@rowcount = 0
		BEGIN
			SELECT @ReturnValue = 'CURRENTLY NO PART IS RUNNING ON ASSEMBLY LINE.', @ReturnInt = 0
			SELECT @ReturnValue, @ReturnInt
		END
		RETURN
	END

	ELSE IF @QueryExecuteOption = 'R'
	BEGIN 
		SELECT @LineTypeName = LTM.LineTypeName
			FROM LineTypeMst (NOLOCK) LTM
				INNER JOIN LineMst (NOLOCK) LM
					ON LTM.LineTypeCode = LM.LineTypeCode AND LTM.ProfitCenterCode = LM.ProfitCenterCode
						WHERE LM.LineCode = @LineCode AND LM.ProfitCenterCode = @ProfitCenterCode
		
		IF @LineTypeName = 'TMC'
		BEGIN
			SET @PartType = 'TMC'
		END
		ELSE IF @LineTypeName = 'STMC'
		BEGIN
			SELECT @PartType = ISNULL(PM.MATERIAL_TP, '') FROM PRODUCT_MASTER (NOLOCK) PM
				INNER JOIN Assy_RunningPart (NOLOCK) RP ON PM.SEWS_PART_NO = RP.Assy_PartNo AND PM.Warehouse_cd = RP.ProfitCenterCode
					WHERE PM.MATERIAL_TP IN ('SERVO', 'STMC') AND Warehouse_cd = @ProfitCenterCode AND RP.LineCode = @LineCode
		END
		ELSE
		BEGIN
			SELECT @PartType = ISNULL(PM.MATERIAL_TP, '') FROM PRODUCT_MASTER (NOLOCK) PM
				INNER JOIN Assy_RunningPart (NOLOCK) RP ON PM.SEWS_PART_NO = RP.Assy_PartNo AND PM.Warehouse_cd = RP.ProfitCenterCode
					WHERE PM.MATERIAL_TP = @LineTypeName AND Warehouse_cd = @ProfitCenterCode AND RP.LineCode = @LineCode
		END

		SELECT REASON_CD, REASON_DESC FROM REASON_MASTER (NOLOCK) WHERE Warehouse_cd = @ProfitCenterCode AND STS_CD = 0 AND REASON_TP = @PartType --Order By REASON_DESC
		RETURN
	END
		
	ELSE IF @QueryExecuteOption = 'BP'
	BEGIN 
		SELECT Barcode, A.MachineCode, B.MachineName 
			FROM Assy_TallyChartStatusData (NOLOCK) A INNER JOIN MachineMst (NOLOCK) B ON A.MachineCode = B.MachineCode AND A.ProfitCenterCode = B.ProfitCenterCode
				WHERE LineCode = @LineCode 
				--AND A.DateCode = @DateCode 
				AND A.Assy_Auth = 0 AND A.MachineCode = @MachineCode AND A.ProfitCenterCode = @ProfitCenterCode
					Order By Barcode
		RETURN
	END
		
	ELSE IF @QueryExecuteOption = 'PS' 
	BEGIN 
		SELECT @ResultVar = 'PASS'
		SELECT Barcode, A.MachineCode, B.MachineName
			FROM Assy_TallyChartStatusData (NOLOCK) A INNER JOIN MachineMst (NOLOCK) B ON A.MachineCode = B.MachineCode AND A.ProfitCenterCode = B.ProfitCenterCode
				WHERE LineCode = @LineCode AND A.MachineCode = @MachineCode AND A.Result = @ResultVar AND 
				--A.DateCode = @DateCode AND 
				A.Assy_Auth = 0 AND A.ProfitCenterCode = @ProfitCenterCode
					Order By Barcode
		RETURN
	END
		
	ELSE IF @QueryExecuteOption = 'FL'
	BEGIN 
		SELECT @ResultVar = 'FAIL'
		SELECT Barcode, A.MachineCode, B.MachineName
			FROM Assy_TallyChartStatusData (NOLOCK) A INNER JOIN MachineMst (NOLOCK) B ON A.MachineCode = B.MachineCode AND A.ProfitCenterCode = B.ProfitCenterCode
				WHERE LineCode = @LineCode AND A.MachineCode = @MachineCode AND A.Result = @ResultVar AND 
				-- A.DateCode = @DateCode AND 
				A.Assy_Auth = 0 AND A.ProfitCenterCode = @ProfitCenterCode
				Order By Barcode
		RETURN
	END
	
	ELSE IF @QueryExecuteOption = 'SCRP'
	BEGIN 
		SELECT @ResultVar = 'SCRAP'
		SELECT Barcode, A.MachineCode, B.MachineName, A.Reason, A.Remarks
			FROM Assy_TallyChartStatusData A WITH (NOLOCK) INNER JOIN MachineMst (NOLOCK) B ON A.MachineCode = B.MachineCode AND A.ProfitCenterCode = B.ProfitCenterCode
				WHERE LineCode = @LineCode AND A.MachineCode = @MachineCode AND A.NotProcessedStatus = @ResultVar 
				--AND A.DateCode = @DateCode 
				AND A.Assy_Auth = 0 AND A.ProfitCenterCode = @ProfitCenterCode
					Order By Barcode
		RETURN
	END

	ELSE IF @QueryExecuteOption = 'REW'
	BEGIN 
		SELECT @ResultVar = 'REWORK'
		SELECT A.Barcode, A.MachineCode, B.MachineName, A.Reason, A.Remarks
			FROM Assy_TallyChartStatusData A WITH (NOLOCK) INNER JOIN MachineMst (NOLOCK) B ON A.MachineCode = B.MachineCode AND A.ProfitCenterCode = B.ProfitCenterCode
				WHERE LineCode = @LineCode AND A.MachineCode = @MachineCode AND A.NotProcessedStatus = @ResultVar 
				--AND A.DateCode = @DateCode 
				AND A.Assy_Auth = 0 AND A.ProfitCenterCode = @ProfitCenterCode
					Order By Barcode
		RETURN
	END

	ELSE IF @QueryExecuteOption = 'NPS'
	BEGIN 
		DECLARE @PrevMachineCode VARCHAR(20) = NULL, @RunningPartNo VARCHAR (20)
		
		SELECT @RunningPartNo = Assy_PartNo FROM Assy_RunningPart (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
					
		EXEC ASSY_PROC_GET_PREVIOUS_MACHINECODE @LineCode = @LineCode, @MachineCode = @MachineCode, @PARTNUMBER = @RunningPartNo, @PrevMachineCode = @PrevMachineCode OUTPUT
		--SELECT @PrevMachineCode

		SELECT * INTO #Assy_TallyChartStatusData_NPS FROM Assy_TallyChartStatusData (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode

		IF @MachineCode = (SELECT dbo.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'COUPLING', 'MachineCode', @ProfitCenterCode)) AND @ProfitCenterCode = '0021'
		BEGIN
			--Added By Rashid Siddiqui On 20170511 To handle Negative Case for Coupling Station After Print Station
			DECLARE @PrevSeqNo INT = 0
			SELECT @PrevSeqNo = OperationSeqNo FROM RoutingConfigLineWise WITH (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND MachineCode = @PrevMachineCode
			IF ISNULL(@PrevSeqNo,0) = 1
			BEGIN
				-- DELETE Coupling Record IF any EXISTS - By Rashid On 20170606
				SELECT ACD.CHILD_Barcode INTO #CoupledBarcode FROM Assy_CouplingDetails ACD WITH (NOLOCK)
									INNER JOIN #Assy_TallyChartStatusData_NPS ATCD WITH (NOLOCK)
										ON ACD.FG_Barcode = ATCD.Barcode AND ACD.LineCode = ATCD.LineCode AND ACD.DateCode = ATCD.Datecode
											WHERE ATCD.LineCode = @LineCode  AND ATCD.MachineCode = @MachineCode AND ATCD.Assy_Auth = 0 AND ACD.PART_TYPE = 'SERVO'
											--AND ATCD.Datecode = @DateCode
				
				IF EXISTS (SELECT 1 FROM #CoupledBarcode)
				BEGIN
					SELECT Barcode, A.MachineCode, B.MachineName
						FROM #Assy_TallyChartStatusData_NPS (NOLOCK) A INNER JOIN MachineMst (NOLOCK) B ON A.MachineCode = B.MachineCode AND A.ProfitCenterCode = B.ProfitCenterCode
							WHERE LineCode = @LineCode AND A.Assy_Auth = 0 AND  A.MachineCode = @PrevMachineCode AND Result = 'PASS'  AND PartNo = @RunningPartNo AND A.ProfitCenterCode = @ProfitCenterCode --AND DateCode = @DateCode
								AND Barcode NOT IN
								(
										SELECT ACD.CHILD_Barcode FROM Assy_CouplingDetails ACD WITH (NOLOCK)
											INNER JOIN #Assy_TallyChartStatusData_NPS ATCD WITH (NOLOCK)
												ON ACD.FG_Barcode = ATCD.Barcode AND ACD.LineCode = ATCD.LineCode 
													WHERE ATCD.LineCode = @LineCode AND ATCD.Datecode = @DateCode AND ATCD.MachineCode = @MachineCode AND ATCD.Assy_Auth = 0 AND ACD.PART_TYPE = 'SERVO' AND A.ProfitCenterCode = @ProfitCenterCode
													--AND ACD.DateCode = ATCD.Datecode
								)
				END
				ELSE
				BEGIN
					SELECT Barcode, A.MachineCode, B.MachineName
					FROM #Assy_TallyChartStatusData_NPS (NOLOCK) A INNER JOIN MachineMst (NOLOCK) B ON A.MachineCode = B.MachineCode AND A.ProfitCenterCode = B.ProfitCenterCode
						WHERE LineCode = @LineCode  AND A.Assy_Auth = 0 AND  A.MachineCode = @PrevMachineCode AND Result = 'PASS'  AND PartNo = @RunningPartNo AND A.ProfitCenterCode = @ProfitCenterCode --AND DateCode = @DateCode
							AND Barcode NOT IN
							(
								SELECT Barcode FROM #Assy_TallyChartStatusData_NPS WITH (NOLOCK) WHERE LineCode = @LineCode AND MachineCode = @MachineCode  AND Assy_Auth = 0 AND A.ProfitCenterCode = @ProfitCenterCode --AND DateCode = @DateCode
							)
								Order By Barcode
				END
			END
			ELSE
			BEGIN
				SELECT Barcode, A.MachineCode, B.MachineName
					FROM #Assy_TallyChartStatusData_NPS(NOLOCK) A INNER JOIN MachineMst(NOLOCK) B ON A.MachineCode = B.MachineCode AND A.ProfitCenterCode = B.ProfitCenterCode
						WHERE LineCode = @LineCode  AND A.Assy_Auth = 0	AND  A.MachineCode = @PrevMachineCode AND Result = 'PASS'  AND PartNo = @RunningPartNo AND A.ProfitCenterCode = @ProfitCenterCode --AND DateCode = @DateCode
							AND Barcode NOT IN
							(
								SELECT CHILD_Barcode FROM Assy_CouplingDetails (NOLOCK) WHERE ProfitCentreCode = @ProfitCenterCode AND LineCode = @LineCode AND PART_TYPE = 'SERVO' AND A.ProfitCenterCode = @ProfitCenterCode
							)
								Order By Barcode
			END
		END
		ELSE
		BEGIN
			SELECT Barcode, A.MachineCode, B.MachineName
				FROM #Assy_TallyChartStatusData_NPS (NOLOCK) A INNER JOIN MachineMst (NOLOCK) B ON A.MachineCode = B.MachineCode AND A.ProfitCenterCode = B.ProfitCenterCode
					WHERE LineCode = @LineCode  AND A.Assy_Auth = 0 AND  A.MachineCode = @PrevMachineCode AND Result = 'PASS'  AND PartNo = @RunningPartNo AND A.ProfitCenterCode = @ProfitCenterCode --AND DateCode = @DateCode
						AND Barcode NOT IN
						(
							SELECT Barcode FROM #Assy_TallyChartStatusData_NPS WITH (NOLOCK) WHERE LineCode = @LineCode AND MachineCode = @MachineCode  AND Assy_Auth = 0 AND A.ProfitCenterCode = @ProfitCenterCode --AND DateCode = @DateCode
						)
							Order By Barcode
		END
		RETURN
	END

	--SCRAPPED AND REWORK DATA
	ELSE IF (@QueryExecuteOption = 'SCRAP') OR (@QueryExecuteOption = 'REWORK')
	BEGIN 
		--Added By Rashid ON 30th Dec 2016 Do NOT Mark Scrap/Rework IF any Barcode IS Pass/Fail during Tally Chart Processing. Refresh the Data.
		IF EXISTS
		(
			SELECT 1 FROM Assy_LineAssyStatus_Running (NOLOCK) WHERE Status IN ('PS', 'FL')
				AND Barcode IN
				(
					SELECT TV.Barcode FROM @ASSYTABLE TV INNER JOIN Assy_RunningPart (NOLOCK) RP ON TV.LineCode = RP.LineCode
						WHERE TV.ProfitCenterCode = @ProfitCenterCode AND TV.LineCode = @LineCode
				)
				AND MachineCode IN
				(
					SELECT TV.MachineCode FROM @ASSYTABLE TV INNER JOIN Assy_RunningPart (NOLOCK) RP ON TV.LineCode = RP.LineCode
						WHERE TV.ProfitCenterCode = @ProfitCenterCode AND TV.LineCode = @LineCode
				) AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
		)
		BEGIN
			SELECT @ReturnValue = 'ONE OR MORE SELECTED Barcode IS ALREADY PASS/FAIL. PLEASE DO REFRESH FOR LATEST Tally Chart DATA .', @ReturnInt = @@ROWCOUNT
			SELECT @ReturnValue, @ReturnInt
			RETURN
		END
		ELSE IF EXISTS
		(
			SELECT 1 FROM Assy_LineAssyStatus (NOLOCK) WHERE Status IN ('PS', 'FL')
				AND Barcode IN
				(
					SELECT TV.Barcode FROM @ASSYTABLE TV INNER JOIN Assy_RunningPart (NOLOCK) RP ON TV.LineCode = RP.LineCode
						WHERE TV.ProfitCenterCode = @ProfitCenterCode AND TV.LineCode = @LineCode
				)
				AND MachineCode IN
				(
					SELECT TV.MachineCode FROM @ASSYTABLE TV INNER JOIN Assy_RunningPart (NOLOCK) RP ON TV.LineCode = RP.LineCode
						WHERE TV.ProfitCenterCode = @ProfitCenterCode AND TV.LineCode = @LineCode
				) AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
		)
		BEGIN
			SELECT @ReturnValue = 'ONE OR MORE SELECTED Barcode IS ALREADY PASS/FAIL. PLEASE DO REFRESH FOR LATEST Tally Chart DATA .', @ReturnInt = @@ROWCOUNT
			SELECT @ReturnValue, @ReturnInt
			RETURN
		END
		-- DELETE Coupling Record IF any EXISTS - By Rashid On 20170606
		IF EXISTS (SELECT 1 FROM Assy_Coupling_Temp WITH (NOLOCK)
					WHERE CHILD_Barcode IN
					(
						SELECT TV.Barcode FROM @ASSYTABLE TV INNER JOIN Assy_RunningPart (NOLOCK) RP ON TV.LineCode = RP.LineCode
							WHERE TV.ProfitCenterCode = @ProfitCenterCode AND TV.LineCode = @LineCode
					))
		BEGIN
			DELETE FROM Assy_Coupling_Temp
			SET @ReturnValue = 'DELETE_Assy_Coupling_Temp.'
		END
		--Start-- WIP Barcode Carry Forward For Next Shift -- BY RS On 02-April-2020
		IF EXISTS (SELECT 1 FROM RoutingConfigDetails (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND KeyType = 'IsWIPCountManage' AND KeyValue = '1')
		BEGIN
			DELETE WPP
				FROM @ASSYTABLE TV INNER JOIN Assy_WIP_Pending_Part_Status (NOLOCK) WPP
					ON TV.LineCode = WPP.LineCode AND TV.ProfitCenterCode = WPP.ProfitCenterCode AND TV.BarCode = WPP.Barcode
						WHERE TV.ProfitCenterCode = @ProfitCenterCode AND TV.LineCode = @LineCode

			INSERT INTO Assy_WIP_Pending_Part_Status
			(
				ProfitCenterCode, LineCode, DateCode, MachineCode, Barcode, Reason, PartNo, ENT_BY, ENT_STAMP, LAST_UPD_BY, LAST_UPD_STAMP
			)
			SELECT @ProfitCenterCode, @LineCode, @DateCode, TV.MachineCode, TV.Barcode, Reason, RP.Assy_PartNo, @UserID, GETDATE(), @UserID, GETDATE()
				FROM @ASSYTABLE TV INNER JOIN Assy_RunningPart (NOLOCK) RP ON TV.LineCode = RP.LineCode
					WHERE TV.ProfitCenterCode = @ProfitCenterCode AND TV.LineCode = @LineCode AND Reason = 'WIP'
		END
		--End-- WIP Barcode Carry Forward For Next Shift -- BY RS On 02-April-2020

		INSERT INTO Assy_TallyChartStatusData
		(
			ProfitCenterCode, LineCode, StationCode, DateCode, MachineCode, Barcode, Result, NotProcessedStatus, RePrint, Reason, Remarks, UserID, TimeStamp, PartNo
		)
		SELECT @ProfitCenterCode, @LineCode, @StationCode, @DateCode, TV.MachineCode, TV.Barcode, '', @QueryExecuteOption, '', Reason, Remarks, @UserID, GETDATE(), RP.Assy_PartNo
			FROM @ASSYTABLE TV INNER JOIN Assy_RunningPart (NOLOCK) RP ON TV.LineCode = RP.LineCode
				WHERE TV.ProfitCenterCode = @ProfitCenterCode AND TV.LineCode = @LineCode

		UPDATE Assy_Scan_OK SET IsScan = 0, Barcode = '' WHERE LineCode = @LineCode

		SET @ReturnValue = ISNULL(@ReturnValue,'') + 'RECORD SAVED SUCCESSFULLY.'
		SET @ReturnInt = @@ROWCOUNT
		SELECT @ReturnValue, @ReturnInt
		RETURN
	END

	--RePrint BARCODES
	ELSE IF @QueryExecuteOption = 'REPRINT'
	BEGIN 
		DECLARE @STMCPartNo VARCHAR(30), @SERVOPartNo VARCHAR(30)
		
		SELECT Top 1 @STMCPartNo = Assy_PartNo, @SERVOPartNo = ISNULL(SERVO_PARTNO, ''), @PartType = ISNULL(PartType, ''), @DateCode = DateCode FROM Assy_RunningPart (NOLOCK)
			WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND Assy_Mode IN ('Production', 'Rework')
		
		IF(@PartType <> 'STMC')
		BEGIN
			SET @SERVOPartNo = @STMCPartNo
		END

		INSERT INTO Assy_TallyChart_RePrintBarCode
		(			
			ProfitCenterCode, LineCode, StationCode, DateCode, MachineCode, OperationCode, Barcode, RePrint, Reason, Remarks, UserID, CreatedDt, PartNo, SerialNo
		)
		SELECT @ProfitCenterCode, @LineCode, @StationCode, VS.DateCode, MachineCode, @OperationCode, TV.Barcode, 0, Reason, Remarks, @UserID, GETDATE(), VS.PartNo, VS.SerialNo 
			FROM @ASSYTABLE TV INNER JOIN Assy_Vision_System (NOLOCK) VS ON VS.LineCode = TV.LineCode  AND VS.Barcode = TV.Barcode		
				WHERE TV.ProfitCenterCode = @ProfitCenterCode AND TV.LineCode = @LineCode AND VS.DateCode = @DateCode AND VS.PartNo = @SERVOPartNo									
		
		SET @ReturnValue = 'SELECTED RECORD PRINTED SUCCESSFULLY.'
		SET @ReturnInt = @@ROWCOUNT
		SELECT @ReturnValue, @ReturnInt
		RETURN
	END
	
	--GET Tally Chart ASSEMBLY DATA
	--Ravi
	ELSE IF @QueryExecuteOption = 'FETCH'
	BEGIN 
		--DECLARE @TotRecords AS INT, @TempMachineCode VARCHAR(30), @TotTallyChartDupRecords INT, @RowCountStart INT = 1, @FailCount INT = 0, @EngravingMachineCode VARCHAR(20) = ''
		
		DELETE FROM Assy_TallyChartStatusData
		WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode 
	     AND PartNo = @AssyPartNo AND ISNULL(Result, '') 
		= 'FAIL' AND ISNULL(Assy_Auth, 0) = 0 --	AND DateCode = @DateCode

		IF(@ProfitCenterCode='0021')
		BEGIN
			SELECT @EngravingMachineCode = dbo.ASSY_FN_GET_PARAMETER_VALUE('ASSLINE', 'Engraving', 'MachineCode', @ProfitCenterCode)
		END
		ELSE
		BEGIN
			SELECT @EngravingMachineCode = ''
		END


		INSERT INTO Assy_TallyChartStatusData
		(
			ProfitCenterCode, LineCode, StationCode, DateCode, MachineCode, Barcode, PartNo, Result, NotProcessedStatus, RePrint, UserID, TimeStamp
		)

		SELECT 
			[ProfitCenterCode]
			, [LineCode]
			, [StationCode]
			, [DateCode]
			, [MachineCode]
			, [Barcode]
			, PartNo							
			, Case WHEN [Result] = 'PS' THEN 'PASS' ELSE 'FAIL' END Result
			, [NotProcessedStatus]
			, [RePrint]
			, [UserID]
			, [ResultTimeStamp]
		FROM Assy_VIEW_LineAssyStatus_Both (NOLOCK) A
			WHERE A.ProfitCenterCode = @ProfitCenterCode AND A.LineCode = @LineCode	--AND A.DateCode = @DateCode 
				AND A.PartNo = @AssyPartNo AND ISNULL(A.IsReworkPart, 0) = 0
					AND A.MachineCode != @EngravingMachineCode 
						AND NOT EXISTS
						(
							SELECT Barcode FROM Assy_TallyChartStatusData C WITH (NOLOCK)
								WHERE A.ProfitCenterCode = C.ProfitCenterCode AND A.LineCode = C.LineCode AND  A.Barcode = C.Barcode 
									AND A.MachineCode = C.MachineCode
										AND C.ProfitCenterCode = @ProfitCenterCode AND C.LineCode = @LineCode --AND C.DateCode = @DateCode 
											AND C.PartNo = @AssyPartNo
						)
		
		SELECT Top 1 @DateCode = DateCode, @AssyPartNo = Assy_PartNo FROM Assy_RunningPart(NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
		
		--TRUNCATE Table Assy_Temp_RoutingMachine
		SELECT  L.OperationSeqNo, L.ProfitCenterCode, L.LineCode, L.MachineCode, L.OperationCode, M.MachineName INTO #RoutingInfoDataWithMachineName
			FROM RoutingConfigLineWise (NOLOCK) L
				INNER JOIN RoutingConfigPartWise (NOLOCK) P 
					ON L.OperationCode = P.OperationCode AND L.MachineCode = P.MachineCode  AND L.ProfitCenterCode = P.ProfitCenterCode
				INNER JOIN MachineMst (NOLOCK) M
					ON L.MachineCode = M.MachineCode AND L.ProfitCenterCode = M.ProfitCenterCode
			WHERE L.LineCode = @LineCode AND L.Traceability = 1 AND P.Traceability = 1
				-- Added By Rashid For Handling Engraving Station ON 10th Sep 2016
				AND ISNULL(L.Engraving, 0) = 0 AND ISNULL(P.Engraving, 0) = 0
					AND P.PartNo = @AssyPartNo AND L.ProfitCenterCode = @ProfitCenterCode
						Order By L.OperationSeqNo

		;With DuplicateRecords_Assy_TallyChartStatusData
		As
		(
			SELECT ROW_NUMBER() OVER (Partition By ProfitCenterCode, LineCode, DateCode, PartNo, MachineCode, Barcode Order by Barcode) AS DuplicateRecords
				FROM Assy_TallyChartStatusData (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
				--AND DateCode = @DateCode 
				AND PartNo = @AssyPartNo AND ISNULL(Result, '') <> '' AND Assy_Auth = 0
		)
		DELETE FROM DuplicateRecords_Assy_TallyChartStatusData WHERE DuplicateRecords > 1
		/*
		SELECT @TotRecords = @@rowcount --Count(OperationSeqNo) FROM Assy_Temp_RoutingMachine(NOLOCK) 
		
		DECLARE @Count INT = 1
				
		WHILE(@TotRecords > = @Count)
		BEGIN
			SELECT @TempMachineCode = MachineCode FROM Assy_Temp_RoutingMachine WHERE ID = @Count							 				
			TRUNCATE Table Assy_Temp_TallyChartStatusData
			
			INSERT INTO  Assy_Temp_TallyChartStatusData
			(
				ProfitCenterCode, 
				LineCode, 
				DateCode, 
				PartNo, 
				MachineCode, 
				Barcode, 
				Records
			)
			
			SELECT 
				ProfitCenterCode, 
				LineCode, 
				DateCode, 	
				PartNo, 
				MachineCode, 
				Barcode, 
				Count(Barcode)
			FROM Assy_TallyChartStatusData (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND MachineCode = @TempMachineCode
				AND DateCode = @DateCode AND PartNo = @AssyPartNo AND ISNULL(Result, '') <> '' AND Assy_Auth = 0
					GROUP By ProfitCenterCode, LineCode, DateCode, PartNo, MachineCode, Barcode
						HAVING Count(Barcode)> = 2
			
			SELECT @TotTallyChartDupRecords = @@rowcount -- Count(ID) FROM Assy_Temp_TallyChartStatusData (NOLOCK)
			SET @RowCountStart = 1
			
			IF @TotTallyChartDupRecords = 0
			BEGIN
				SET	@Count = @Count + 1
				CONTINUE
			END

			WHILE(@TotTallyChartDupRecords> = @RowCountStart)
			BEGIN
				DELETE FROM Assy_TallyChartStatusData WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND MachineCode = @TempMachineCode
					AND DateCode = @DateCode AND PartNo = @AssyPartNo AND ISNULL(Result, '') = 'FAIL' AND ISNULL(Assy_Auth, 0) = 0
						AND TimeStamp IN
							(
								SELECT Top 1 Tally.TimeStamp FROM Assy_Temp_TallyChartStatusData (NOLOCK)TMP INNER JOIN  Assy_TallyChartStatusData (NOLOCK) Tally
									ON Tally.ProfitCenterCode = TMP.ProfitCenterCode AND Tally.LineCode = TMP.LineCode AND Tally.MachineCode = TMP.MachineCode 
										AND Tally.DateCode = TMP.DateCode AND Tally.PartNo = TMP.PartNo AND Tally.Barcode = TMP.Barcode
									WHERE  TMP.ProfitCenterCode = @ProfitCenterCode	AND TMP.LineCode = @LineCode AND TMP.DateCode = @DateCode AND TMP.PartNo = @AssyPartNo 
										AND TMP.MachineCode = @TempMachineCode AND Tally.Result = 'FAIL'
											AND Tally.Barcode = (SELECT Top 1 Barcode FROM Assy_Temp_TallyChartStatusData (NOLOCK) WHERE ID = @RowCountStart)
									Order By Tally.TimeStamp
							)
				SET @RowCountStart = @RowCountStart + 1
			END

			SET @Count = @Count+1
		END
		
		TRUNCATE Table Assy_Temp_TallyChartStatusData
		TRUNCATE Table Assy_Temp_RoutingMachine
		*/
		UPDATE AT SET AT.OperationSeqNo = TEMP_ROUT.OperationSeqNo
			FROM Assy_TallyChartStatusData AT
				INNER JOIN
				(
					SELECT ProfitCenterCode, LineCode, OperationCode, OperationSeqNo, MachineCode FROM #RoutingInfoDataWithMachineName
					--SELECT L.ProfitCenterCode, LineCode, L.OperationCode, L.OperationSeqNo, L.MachineCode
					--	FROM RoutingConfigLineWise (NOLOCK) L INNER JOIN RoutingConfigPartWise (NOLOCK) P
					--		ON L.OperationCode = P.OperationCode AND  L.MachineCode = P.MachineCode  AND L.ProfitCenterCode = L.ProfitCenterCode 
					--			WHERE L.LineCode = @LineCode AND L.Traceability = 1	AND P.Traceability = 1
					--				-- Added By Rashid For Handling Engraving Station ON 10th Sep 2016
					--				AND ISNULL(L.Engraving, 0) = 0 AND ISNULL(P.Engraving, 0) = 0
					--					AND P.PartNo = @AssyPartNo 
				)TEMP_ROUT
			ON AT.ProfitCenterCode = TEMP_ROUT.ProfitCenterCode AND AT.LineCode = TEMP_ROUT.LineCode AND AT.MachineCode = TEMP_ROUT.MachineCode
				WHERE AT.ProfitCenterCode = @ProfitCenterCode AND AT.LineCode = @LineCode
	
		--DROP Table TEMP
		--SELECT * FROM Assy_TallyChartStatusData

		CREATE Table #TEMP
		(
			SeqID INT IDENTITY(1, 1), 
			OperationSeqNo NUMERIC(18, 0), 
			ProfitCenterCode VARCHAR(10), 
			LineCode VARCHAR(10), 
			MachineCode NVARCHAR(10), 
			MachineName VARCHAR(250), 
		)
		
		INSERT INTO #TEMP
		SELECT 0, @ProfitCenterCode, @LineCode, 'ST1', 'Status'
	
		INSERT INTO #TEMP
		SELECT OperationSeqNo, ProfitCenterCode, LineCode, MachineCode, MachineName FROM #RoutingInfoDataWithMachineName
		Group By OperationSeqNo, ProfitCenterCode, LineCode, MachineCode, MachineName
		Order By OperationSeqNo
		--SELECT  L.OperationSeqNo, @ProfitCenterCode, @LineCode, L.MachineCode, B.MachineName 
		--	FROM RoutingConfigLineWise (NOLOCK) L
		--		INNER JOIN RoutingConfigPartWise (NOLOCK) P 
		--	ON L.OperationCode = P.OperationCode AND  L.MachineCode = P.MachineCode  AND L.ProfitCenterCode = P.ProfitCenterCode 
		--		INNER JOIN MachineMst B
		--	ON L.MachineCode = B.MachineCode  	
		--		WHERE L.LineCode = @LineCode AND L.Traceability = 1 AND P.Traceability = 1
		--		-- Added By Rashid For Handling Engraving Station ON 10th Sep 2016
		--		AND ISNULL(L.Engraving, 0) = 0 AND ISNULL(P.Engraving, 0) = 0
		--			AND P.PartNo = @AssyPartNo 
		--	Order By L.OperationSeqNo

		--SELECT * FROM Assy_Temp_Status
		DELETE FROM Assy_Temp_Status
		
		INSERT INTO Assy_Temp_Status
		(
			ProfitCenterCode, DateCode, LineCode, OperationSeqNo, MachineCode, MachineName, BARCODE_PRINTED, PASSED, FAILED, NOT_PROCESSED, REWORK, SCRAPPED, SeqID
		)
		SELECT @ProfitCenterCode, @DateCode, @LineCode, OperationSeqNo, MachineCode, MachineName, 0, 0, 0, 0, 0, 0, SeqID FROM #TEMP Order By OperationSeqNo
  
		--SELECT * FROM Assy_Temp_Status
		--UPDATE Tally Chart Barcode PRINTED FOR FIRST STATION
		SELECT ProfitCenterCode, LineCode, MachineCode, Count(Result) AS BarcodeCount, Result INTO #BarcodeCountResultTable
			FROM Assy_TallyChartStatusData (NOLOCK)
				WHERE Assy_Auth = 0 AND PartNo = @AssyPartNo
					GROUP By ProfitCenterCode, LineCode,MachineCode, Result -- AND DateCode = @DateCode

		UPDATE Assy SET Assy.BARCODE_PRINTED = Temp_Assy.BARCODE_PRINTED
			FROM Assy_Temp_Status Assy
				INNER JOIN
				(
					SELECT ProfitCenterCode, LineCode, MachineCode, BarcodeCount BARCODE_PRINTED FROM #BarcodeCountResultTable WHERE Result = 'PASS'
					--SELECT ProfitCenterCode, LineCode, DateCode, MachineCode, Count(Result) AS BARCODE_PRINTED
					--	FROM Assy_TallyChartStatusData (NOLOCK)
					--		WHERE Result = 'PASS' AND OperationSeqNo = 1 AND Assy_Auth = 0 AND PartNo = @AssyPartNo AND DateCode = @DateCode
					--	GROUP By ProfitCenterCode, LineCode, DateCode, MachineCode
				)Temp_Assy
				ON Assy.MachineCode = Temp_Assy.MachineCode
					WHERE Assy.ProfitCenterCode = @ProfitCenterCode AND Assy.LineCode = @LineCode AND Assy.OperationSeqNo = 1
		--UPDATE Tally Chart PASS FIRST STATION
		UPDATE Assy SET Assy.PASSED = Temp_Assy.PASSED
			FROM Assy_Temp_Status(NOLOCK) Assy
				INNER JOIN
				(
					SELECT ProfitCenterCode, LineCode,  MachineCode, BarcodeCount PASSED FROM #BarcodeCountResultTable WHERE Result = 'PASS'

					--SELECT ProfitCenterCode, LineCode, DateCode, MachineCode, Count(Result) AS PASSED
					--	FROM Assy_TallyChartStatusData (NOLOCK)
					--		WHERE Result = 'PASS' AND Assy_Auth = 0 AND PartNo = @AssyPartNo AND DateCode = @DateCode
					--	GROUP By ProfitCenterCode, LineCode, DateCode, MachineCode
				)Temp_Assy
				ON Assy.MachineCode = Temp_Assy.MachineCode
					WHERE Assy.ProfitCenterCode = @ProfitCenterCode	AND Assy.LineCode = @LineCode AND NOT Assy.OperationSeqNo = 1
		--UPDATE Tally Chart FAIL FOR FIRST STATION
		UPDATE Assy SET Assy.FAILED = Temp_Assy.FAILED
			FROM Assy_Temp_Status Assy
				INNER JOIN
				(
					SELECT ProfitCenterCode, LineCode,  MachineCode, BarcodeCount FAILED FROM #BarcodeCountResultTable WHERE Result = 'FAIL'
					--SELECT ProfitCenterCode, LineCode, DateCode, MachineCode, Count(Result) AS FAILED
					--	FROM Assy_TallyChartStatusData (NOLOCK)
					--		WHERE Result = 'FAIL' AND Assy_Auth = 0 AND PartNo = @AssyPartNo AND DateCode = @DateCode
					--	GROUP By ProfitCenterCode, LineCode, DateCode, MachineCode
				)Temp_Assy
				ON Assy.MachineCode = Temp_Assy.MachineCode
					WHERE Assy.ProfitCenterCode = @ProfitCenterCode	AND Assy.LineCode = @LineCode AND NOT Assy.OperationSeqNo = 1

		--SELECT  @AssyPartNo, @LineCode, @DateCode

		--UPDATE SCRAPPED QUANTITY FOR FIRST STATION
		SELECT ProfitCenterCode, LineCode, MachineCode, Count(Barcode) AS BarcodeCount, NotProcessedStatus INTO #BarcodeCountNotProcessedStatusTable
			FROM Assy_TallyChartStatusData (NOLOCK)
				WHERE ISNULL(Result, '') = '' AND Assy_Auth = 0 AND PartNo = @AssyPartNo 
			GROUP By ProfitCenterCode, LineCode, MachineCode, NotProcessedStatus
			
		UPDATE Assy SET Assy.SCRAPPED = Temp_Assy.SCRAPPED
			FROM Assy_Temp_Status Assy
				INNER JOIN
				(
					SELECT ProfitCenterCode, LineCode, MachineCode, BarcodeCount SCRAPPED FROM #BarcodeCountNotProcessedStatusTable
						WHERE NotProcessedStatus = 'SCRAP'
					--SELECT ProfitCenterCode, LineCode, DateCode, MachineCode, Count(Barcode) AS SCRAPPED
					--	FROM Assy_TallyChartStatusData (NOLOCK)
					--		WHERE NotProcessedStatus = 'SCRAP' AND ISNULL(Result, '') = '' AND Assy_Auth = 0 AND PartNo = @AssyPartNo AND DateCode = @DateCode
					--	GROUP By ProfitCenterCode, LineCode, DateCode, MachineCode
				)Temp_Assy
				ON Assy.MachineCode = Temp_Assy.MachineCode
				WHERE Assy.ProfitCenterCode = @ProfitCenterCode AND Assy.LineCode = @LineCode AND NOT Assy.OperationSeqNo = 1
		--FOR FIRST STATION REWORK
		UPDATE Assy SET Assy.REWORK = Temp_Assy.REWORK
			FROM Assy_Temp_Status Assy
				INNER JOIN
				(
					SELECT ProfitCenterCode, LineCode, MachineCode, BarcodeCount REWORK FROM #BarcodeCountNotProcessedStatusTable
						WHERE NotProcessedStatus = 'REWORK'

					--SELECT ProfitCenterCode, LineCode, DateCode, MachineCode, Count(Barcode) AS REWORK
					--	FROM Assy_TallyChartStatusData (NOLOCK)
					--		WHERE NotProcessedStatus = 'REWORK' AND ISNULL(Result, '') = '' AND Assy_Auth = 0 AND PartNo = @AssyPartNo AND DateCode = @DateCode
					--	GROUP By ProfitCenterCode, LineCode, DateCode, MachineCode
				)Temp_Assy
				ON Assy.MachineCode = Temp_Assy.MachineCode
				WHERE Assy.ProfitCenterCode = @ProfitCenterCode	AND Assy.LineCode = @LineCode AND NOT Assy.OperationSeqNo = 1

		DECLARE @TotalBarcode NUMERIC(18, 0)
		--SET @TotalBarcode = (SELECT BARCODE_PRINTED FROM Assy_Temp_Status (NOLOCK) WHERE OperationSeqNo = 1 AND LineCode = @LineCode)
		
		--UPDATE Assy_Temp_Status 
		--	SET NOT_PROCESSED = ISNULL(@TotalBarcode, 0) - (ISNULL(PASSED, 0) + ISNULL(FAILED, 0) + ISNULL(SCRAPPED, 0) + ISNULL(REWORK, 0))  
		--		WHERE SeqID = (SELECT SeqID + 1 FROM Assy_Temp_Status WHERE OperationSeqNo = 1) AND LineCode = @LineCode

		DECLARE @Passed NUMERIC(18, 0), @SeqID AS INT
		
		--SELECT OperationSeqNo, ProfitCenterCode, LineCode, MachineCode, SeqID FROM #TEMP WHERE NOT OperationSeqNo = 1 Order By SeqID 
		--SELECT * FROM Assy_Temp_Status
		
		--SELECT OperationSeqNo, ProfitCenterCode, DateCode, MachineCode,Count(Result) AS PASSED INTO #Data
		--FROM Assy_TallyChartStatusData(NOLOCK)
		--	WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode	AND DateCode = @DateCode AND Result = 'PASS' AND Assy_Auth = 0 
		--GROUP By OperationSeqNo, ProfitCenterCode, DateCode, MachineCode

		--SELECT  * FROM #Data

		--UPDATE ATS 
		--	SET ATS.NOT_PROCESSED = (D.PASSED) - (ISNULL(ATS.PASSED, 0) + ISNULL(ATS.FAILED, 0)+ ISNULL(ATS.SCRAPPED, 0) + ISNULL(ATS.REWORK, 0))
		--	FROM Assy_Temp_Status ATS
		--		INNER JOIN #Data D ON D.MachineCode = ATS.MachineCode
		--		WHERE ATS.ProfitCenterCode = @ProfitCenterCode AND ATS.LineCode = @LineCode AND ATS.OperationSeqNo > 2

		--UPDATE ATS SET ATS.NOT_PROCESSED = ATS2.PASSED-(ISNULL(ATS.PASSED, 0) + ISNULL(ATS.FAILED, 0)+ ISNULL(ATS.SCRAPPED, 0) + ISNULL(ATS.REWORK, 0))
	
		UPDATE ATS SET ATS.NOT_PROCESSED = (CASE WHEN ATS2.OperationSeqNo = 1 THEN ATS2.BARCODE_PRINTED 
			ELSE ATS2.PASSED END)-(ISNULL(ATS.PASSED, 0) + ISNULL(ATS.FAILED, 0)+ ISNULL(ATS.SCRAPPED, 0) + ISNULL(ATS.REWORK, 0))
				FROM Assy_Temp_Status ATS
					LEFT JOIN Assy_Temp_Status ATS2 
						ON ATS.SeqID = ATS2.SeqID + 1
							WHERE ATS.SeqID > 2
		
		-- Added By Sachin 20170828
		UPDATE ATS SET ATS.NOT_PROCESSED = 0
			FROM Assy_Temp_Status ATS
				WHERE ATS.NOT_PROCESSED < 0
		-- Ended By Sachin 20170828

		--SELECT * FROM Assy_Temp_Status

		--DECLARE AssyStatus CURSOR FOR
		--	SELECT OperationSeqNo, ProfitCenterCode, LineCode, MachineCode, SeqID FROM #TEMP WHERE NOT OperationSeqNo = 1 Order By SeqID 
		--OPEN AssyStatus
		--FETCH NEXT FROM AssyStatus INTO @OperationSeqNo, @ProfitCenterCode, @LineCode, @MachineCode, @SeqID
		--WHILE @@FETCH_STATUS = 0
		--BEGIN   
		--	SET @Passed = 0
		--	SET @Passed = (
		--		SELECT Count(Result) AS PASSED
		--			FROM Assy_TallyChartStatusData(NOLOCK)
		--				WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode	AND DateCode = @DateCode AND Result = 'PASS' AND OperationSeqNo = @OperationSeqNo AND Assy_Auth = 0 
		--			GROUP By OperationSeqNo, ProfitCenterCode, DateCode, MachineCode
		--	)
			
		--	UPDATE Assy_Temp_Status 
		--		SET NOT_PROCESSED = ISNULL(@Passed, 0) - (ISNULL(PASSED, 0) + ISNULL(FAILED, 0)+ ISNULL(SCRAPPED, 0) + ISNULL(REWORK, 0))   
		--			WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND SeqID = @SeqID + 1
		
		--FETCH NEXT FROM AssyStatus INTO @OperationSeqNo, @ProfitCenterCode, @LineCode, @MachineCode, @SeqID
		--END   

		--CLOSE AssyStatus   
		--DEALLOCATE AssyStatus
		--TRUNCATE Table Assy_Temp_Status
		SELECT OperationSeqNo, MachineCode, MachineName, BARCODE_PRINTED, PASSED, FAILED, NOT_PROCESSED, REWORK, SCRAPPED
			FROM Assy_Temp_Status (NOLOCK) --WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode

		RETURN
	END

	-- UPDATE AUTHORIZE STSTUS
	ELSE IF @QueryExecuteOption = 'AUTHASSY'
	BEGIN 
		IF EXISTS
		(
			SELECT 1 FROM Assy_TallyChartStatusData (NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode--AND StationCode = @StationCode
					AND DateCode = @DateCode AND Assy_Auth = 0
		)
		BEGIN
			UPDATE Assy_TallyChartStatusData SET Assy_Auth = 1 WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode --AND StationCode = @StationCode
				--AND DateCode = @DateCode
				AND Assy_Auth = 0
			
			SELECT @ReturnValue = 'ASSEMBLY DETAILS HAS BEEN AUTHORIZED.', @ReturnInt = 1
			SELECT @ReturnInt, @ReturnValue
		END
		ELSE
		BEGIN
			SELECT @ReturnValue = 'ASSEMBLY DETAILS DATA NOT FOUND FOR AUTHORIZATION.', @ReturnInt = -1
			SELECT @ReturnInt, @ReturnValue
		END
		RETURN
	END

	-- UPDATE AUTHORIZE STSTUS
	ELSE IF @QueryExecuteOption = 'AUTHCHILDPART'
	BEGIN 
		IF EXISTS
		(
			SELECT 1 FROM Assy_TallyChartMaterialStatus (NOLOCK)
				WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND FGPartCode = @AssyPartNo AND ProductionOrderNo = @ProductionOrderNo	AND DateCode = @DateCode
					AND Assy_Auth = 0
		)
		BEGIN
			UPDATE Assy_TallyChartMaterialStatus SET Assy_Auth = 1
				WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode	AND DateCode = @DateCode AND FGPartCode = @AssyPartNo AND ProductionOrderNo = @ProductionOrderNo
					AND Assy_Auth = 0
			
			SELECT @ReturnValue = 'ASSEMBLY DETAILS HAS BEEN AUTHORIZED.', @ReturnInt = 1
			SELECT @ReturnInt, @ReturnValue
		END
		ELSE
		BEGIN
			SELECT @ReturnValue = 'ASSEMBLY DETAILS DATA NOT FOUND FOR AUTHORIZATION.', @ReturnInt = -1
			SELECT @ReturnInt, @ReturnValue
		END
		RETURN
	END

	--GET AUTHORIZED STSTUS
	ELSE IF @QueryExecuteOption = 'AUTHSTATUS'
	BEGIN 
		IF EXISTS	
		(
			SELECT 1 FROM Assy_TallyChartStatusData (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND Assy_Auth = 1
			--AND StationCode = @StationCode AND DateCode = @DateCode
		)
		BEGIN
			SELECT @ReturnValue = 'AUTHORIZED Status IS TRUE', @ReturnInt = 1
			SELECT @ReturnInt, @ReturnValue
		END
		ELSE
		BEGIN
			SELECT @ReturnValue = 'ASSEMBLY DETAILS IS NOT AUTHORIZED SO THAT MATERIAL Status DETAILS IS BE DISABLE.', @ReturnInt = -1
			SELECT @ReturnInt, @ReturnValue
		END
		RETURN
	END

	--GET AUTHORIZED STSTUS OF MATERIAL Status
	ELSE IF @QueryExecuteOption = 'AUTHSTATUSCHILDPART'
	BEGIN 
		IF EXISTS	
		(
			SELECT 1 FROM Assy_TallyChartMaterialStatus (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND Assy_Auth = 1
			--AND StationCode = @StationCode AND DateCode = @DateCode
		)
		BEGIN
			SELECT @ReturnValue = 'AUTHORIZED Status IS TRUE', @ReturnInt = 1
			SELECT @ReturnInt, @ReturnValue
		END
		ELSE
		BEGIN
			SELECT @ReturnValue = 'MATERIAL Status IS AUTHORIZED SO THAT MATERIAL Status DETAILS IS BE DISABLE.', @ReturnInt = -1
			SELECT @ReturnInt, @ReturnValue
		END
		RETURN
	END

	--MATERIAL DETAILS
	ELSE IF @QueryExecuteOption = 'MATERIALDETAILS'
	BEGIN 
		--IF EXISTS (SELECT Top 1 ProfitCenterCode FROM Assy_TallyChartMaterialStatus WITH (NOLOCK) 
		--		WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
		--		AND DateCode = @DateCode
		--		)
		--		BEGIN
		--			SELECT ChildPartNo, D.Product_NM, A.FGPartCode, A.ProductionOrderNo, A.Serial_No, A.FeedQuantity, A.ConsumedQty, A.BalanceQty, 
		--			A.ScrappedQty, A.FINALQTY, A.Reason, A.Remarks
		--				FROM Assy_TallyChartMaterialStatus A WITH(NOLOCK) 
		--				INNER JOIN REQUISITION_DETAIL B
		--			ON A.ProfitCenterCode = B.WH_CODE
		--				AND A.ProductionOrderNo = B.REQ_NO
		--			INNER JOIN BOM_MASTER C
		--				ON B.WH_CODE = C.WH_CODE AND A.ChildPartNo = C.RM_PART_NO
		--				AND B.PART_NO = C.FG_PART_NO 
		--			INNER JOIN PRODUCT_MASTER D
		--				ON C.WH_CODE = D.Warehouse_cd AND C.RM_PART_NO = D.SEWS_PART_NO
		--		WHERE ProfitCenterCode = @ProfitCenterCode 
		--					AND LineCode = @LineCode
		--		END
		--	ELSE
		--	BEGIN
		DECLARE @DBLBarcodes NUMERIC(18, 0)
		SET @DBLBarcodes = (
		--SELECT ISNULL(BARCODE_PRINTED, 0)
		--FROM Assy_Temp_Status(NOLOCK) 
		--WHERE OperationSeqNo = 1 
		--AND ProfitCenterCode = @ProfitCenterCode
		--AND LineCode = @LineCode
		--AND DateCode = @DateCode
			SELECT SUM(ISNULL(PASSED, 0)) + SUM(ISNULL(FAILED, 0)) FROM Assy_Temp_Status (NOLOCK) 
			WHERE OperationSeqNo = 
			(
				SELECT MAX( OperationSeqNo) FROM RoutingConfigLineWise (NOLOCK) WHERE Traceability = 1 AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
					-- Added By Rashid For Handling Engraving Station ON 10th Sep 2016
					AND ISNULL(Engraving, 0) = 0
			)
		)

		SELECT A.ChildPartNo, D.Product_NM, A.FGPartCode, A.ProductionOrderNo, A.PACKETID, A.FeedQuantity, (@DBLBarcodes * ISNULL(BOM_QTY, 0)) AS ConsumedQty, 
			ISNULL(A.FeedQuantity, 0)-(@DBLBarcodes * ISNULL(BOM_QTY, 0)) AS BALQTY, 0 AS ScrappedQty, 
				ISNULL(A.FeedQuantity, 0)-(@DBLBarcodes * ISNULL(BOM_QTY, 0)) AS FINALQTY, '' AS Reason, '' AS Remarks
		
		FROM Assy_MaterialFeeding (NOLOCK) A  INNER JOIN Assy_ProductionOrderMst (NOLOCK) B
			ON A.ProfitCenterCode = B.ProfitCenterCode AND A.ProductionOrderNo = B.OrderNo AND A.FGPartCode = B.PartNo 
				INNER JOIN BOM_MASTER (NOLOCK) C
			ON B.ProfitCenterCode = C.WH_CODE AND A.ChildPartNo = C.RM_PART_NO AND B.PartNo = C.FG_PART_NO
				INNER JOIN LineMst (NOLOCK) LM
			ON LM.WorkCenterCode = B.WorkCenterCode 
				INNER JOIN PRODUCT_MASTER (NOLOCK) D
			ON C.WH_CODE = D.Warehouse_cd AND C.RM_PART_NO = D.SEWS_PART_NO
				WHERE A.LineCode = @LineCode AND A.ProfitCenterCode = @ProfitCenterCode 
				AND A.FGPartCode = (SELECT Assy_PartNo FROM Assy_RunningPart(NOLOCK) WHERE LineCode = @LineCode  AND Assy_Mode IN ('Production', 'Rework') )
					AND A.ProductionOrderNo = (SELECT ProductionOrderNo FROM Assy_RunningPart(NOLOCK) WHERE LineCode = @LineCode AND Assy_Mode IN ('Production', 'Rework') )
						AND ISNULL(A.IsProcessed, 0) = 0 AND LM.IsActive = 1 AND LM.LineCode = @LineCode AND  B.Status <> 'C' AND B.IsActive = 1 

		--UPDATE PRODUCE QUANTITY INTO PRODUCTION Order Table
