		--			 WHERE Traceability = 1 AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
		--	)
		--	)

		--UPDATE Assy_ProductionOrderMst SET ProducedQty = ISNULL(ProducedQty, 0)+@PRODUCEPART WHERE ProfitCenterCode = @ProfitCenterCode AND OrderNo = @ProductionOrderNo 
		--AND WorkCenterCode = (SELECT WorkCenterCode FROM LineMst WHERE LineCode = @LineCode)
		--AND PartNo = @AssyPartNo AND ISNULL(ProducedQty, 0)< = QTY
		--END
		RETURN
	END
	
