	ELSE IF @QueryExecuteOption = 'GETSERIALDATAREPRINT_LABEL'
	BEGIN 
		SELECT  @ProfitCenterCode, @LineCode, @DateCode, A.SEWS_PART_NO, @ProductionOrderNo, @Serial_No, '', A.GE_NO, A.GR_NO, B.EXP_RACK_LOC, 
			D.LOC_ID, C.Product_NM, B.TEMP_LOC, A.SUPPLIER_CD, A.STS_CD, A.ENT_BY, A.ENT_STAMP, '', GETDATE(), E.SUPPLIER_DESC, A.INT_LOT_NO, 
				B.ACK_QTY, A.ERP_LOT_NO, A.SERIAL_QTY, F.PLANT_CODE, C.SEWS_DESIGN_LEVEL, A.BOX_LOT_NO
			FROM INV_SERIAL (NOLOCK) A
				INNER JOIN Assy_TallyChartMatSts_PrintLabel (NOLOCK) Assy
			ON A.SEWS_PART_NO = Assy.ChildPartNo AND A.WH_CODE = Assy.ProfitCenterCode
				INNER JOIN ERP_RECEIVING_DETAILS (NOLOCK) B
			ON A.WH_CODE = B.WH_CODE AND A.GE_NO = B.GE_NO AND A.GR_NO = B.GR_NO 
				INNER JOIN PRODUCT_MASTER (NOLOCK) C
			ON A.WH_CODE = C.Warehouse_cd AND A.ITEM_NO = C.ITEM_NO AND B.WH_CODE = C.Warehouse_cd AND B.PART_NO = C.SEWS_PART_NO
				INNER JOIN LOCATION_PART_MATRIX (NOLOCK) D
			ON A.WH_CODE = D.WH_CODE AND A.ITEM_NO = D.ITEM_NO
				INNER JOIN SUPPLIER_MASTER (NOLOCK) E
			ON A.WH_CODE = E.Warehouse_cd AND A.SUPPLIER_CD = E.SUPPLIER_CD
				INNER JOIN WAREHOUSE_MASTER (NOLOCK) F
			ON A.WH_CODE = F.Warehouse_cd
				WHERE Assy.ProfitCenterCode = @ProfitCenterCode AND A.Serial_No = @Serial_No

		/*SELECT A.ChildPartNo, B.Product_NM, A.FGPARTNO, A.ProductionOrderNo, A.SerialNo, A.Remarks 
