	else if(@Condition='PRODUCTIONDATASUMMARY_MIDDLEDROPPassBUTNOTPROCESSED')
			begin
				DECLARE	@Cols AS nVARCHAR(MAX) = '';
				DECLARE	@FilterColumn AS nVARCHAR(MAX) = '', @FilterQuery AS nVARCHAR(MAX) = '';

				IF OBJECT_ID ('Tempdb..#RunningStatus') IS NOT NULL
				DROP TABLE #RunningStatus

						SELECT DISTINCT
						R.OperationSeqNo,
						ISNULL(A.Barcode, '') Barcode,
						ISNULL(A.MachineCode, '') MachineCode,
						M.MachineName AS MachineName,
						(CASE
							WHEN ISNULL(A.Status,'') = '' THEN ''
							ELSE (CASE
									WHEN A.Status = 'PS' THEN 'Pass'
									ELSE 'FAIL'
								END)
						END) ResuLt,
						ISNULL(A.ResultTimestamp, '') ResultTimestamp INTO #RunningStatus
					FROM (SELECT
						L.*
					FROM RoutingConfigLineWise L WITH (NOLOCK)
					INNER JOIN RoutingConfigPartWise P WITH (NOLOCK)
						ON L.ProfitCenterCode = P.ProfitCenterCode
						AND L.OperationCode = P.OperationCode
						AND L.MachineCode = P.MachineCode
					WHERE L.LineCode = @LineCode
					AND L.TraceabiLity = 1
					AND P.TraceabiLity = 1) R
					LEFT OUTER JOIN Assy_LineAssyStatus A WITH (NOLOCK)
						ON A.LineCode = R.LineCode
						AND A.MachineCode = R.MachineCode
					INNER JOIN MachineMst M WITH (NOLOCK)
						ON A.MachineCode = M.MachineCode
					WHERE A.ProfitCenterCode = @ProfitCenterCode AND A.LineCode = @LineCode
							AND A.Status = 'PS'
							AND A.Datecode = @DateCode
						Order By R.OperationSeqNo

						--SELECT * FROM #RunningStatus Order By OperationSeqNo
					DECLARE @TempRunning AS TABLE (
						MachineCode VARCHAR(20),
						Barcode VARCHAR(60),
						Record INT
					)
		
					INSERT INTO @TempRunning (MachineCode, Barcode, Record)
						SELECT
							MachineCode,
							Barcode,
							COUNT(Barcode)
						FROM #RunningStatus(NOLOCK)
							GROUP By MachineCode,Barcode
								HAVING COUNT(Barcode) > 1
		
					DELETE Running_Temp
						FROM #RunningStatus Running_Temp
						INNER JOIN @TempRunning TV
							ON Running_Temp.MachineCode = TV.MachineCode
							AND Running_Temp.Barcode = TV.Barcode
					WHERE Running_Temp.ResuLt = 'FaiL'

					--SELECT * FROM #RunningStatus
					SELECT
						@Cols = STUFF((SELECT
							',' + QUOTENAME(Col + '_' + CAST(Seq AS VARCHAR(10)))
						FROM (SELECT
							ROW_NUMBER() OVER (Partition By Barcode
							Order By OperationSeqNo) Seq
						FROM #RunningStatus) T
						CROSS APPLY (SELECT
							'MachineName',
							1
						UNION ALL
						SELECT
							'ResuLt',
							2
						UNION ALL
						SELECT
							'ResultTimestamp',
							3) c (Col, So)
						GROUP By	Col,Seq,So
						Order By Seq, So
						FOR xml PATH (''), TYPE)
						.value('.', 'NVARCHAR(MAX)')
						, 1, 1, '')

					SELECT
						@FilterColumn = STUFF((SELECT
							',' + QUOTENAME(Col + '_' + CAST(Seq AS VARCHAR(10)))
						FROM (SELECT
							ROW_NUMBER() OVER (Partition By Barcode
							Order By OperationSeqNo) Seq
						FROM #RunningStatus) T
						CROSS APPLY (
						SELECT
							'ResultTimestamp',
							3) c (Col, So)
						GROUP By	Col,Seq,So
						Order By Seq, So
						FOR xml PATH (''), TYPE)
						.value('.', 'NVARCHAR(MAX)')
						, 1, 1, '')
						DECLARE @Result TABLE (Id INT IDENTITY(1,1) NOT NULL,Column1 VARCHAR(100))
						DECLARE @IntLocation INT
						WHILE (CHARINDEX(',',    @FilterColumn, 0) > 0)
						BEGIN
							  SET @IntLocation =   CHARINDEX(',',    @FilterColumn, 0)      
							  INSERT INTO   @Result (Column1)
							  SELECT RTRIM(LTRIM(SUBSTRING(@FilterColumn, 0, @IntLocation)))
							  SET @FilterColumn = STUFF(@FilterColumn, 1, @IntLocation, '')
						END
						INSERT INTO   @Result (Column1)
						SELECT RTRIM(LTRIM(@FilterColumn))

						SET @Id = 1
						WHILE((SELECT COUNT(*) FROM @Result) > 0)
						BEGIN
							IF @Id = 1
								SET @FilterQuery = ' WHERE ' + 'ISNULL(' + (SELECT Column1 FROM @Result WHERE Id = @Id) + ','''') = '''''
							ELSE IF @Id > 1
							BEGIN
								SET @FilterQuery = @FilterQuery + ' OR ' + 'ISNULL(' + (SELECT Column1 FROM @Result WHERE Id = @Id) + ','''') = '''''
							END
				
							IF @Id = (SELECT COUNT(*) FROM @Result)
								BREAK
							SET @Id = @Id + 1
						END
						--SELECT @FilterQuery
						IF OBJECT_ID('FinalResult') IS NOT NULL
							DROP TABLE FinalResult

						SET @qry = 'SELECT Barcode ,' + @Cols + ' INTO FinalResult
									FROM 
									(
									 SELECT Barcode, 
										Col = Col+''_''+cast(Seq AS VARCHAR(10)), 
										value
									 FROM
									 (
										SELECT Barcode, MachineName , ResuLt, CONVERT(VARCHAR,ResultTimestamp,120) ResultTimestamp,
										 row_number() OVER(Partition By Barcode
															Order By OperationSeqNo ) Seq
										FROM #RunningStatus
									 ) SRC
									 CROSS APPLY
									 (
										SELECT ''MachineName'',MachineName UNION ALL
										SELECT ''ResuLt'', ResuLt UNION ALL
										SELECT ''ResultTimestamp'', CONVERT(VARCHAR(100), ResultTimestamp) 
									 ) c (Col, value)
									) x
									pivot 
									(
										MAX(value)
										for Col in (' + @Cols + ')
									) P
									'
						EXECUTE sp_EXECutesqL @qry
						SET @qry = ''
						SET @qry = ' SELECT CAST(ResultTimestamp_1 AS DATE) BarcodePrintDate,* FROM FinalResult ' + @FilterQuery + ''
						Execute sp_sqlexec @qry

				set @ReturnValue='SUCCESS'
				set @ReturnInt=0
				return
			end
	else if(@Condition='COUPLINGDATA')
			begin
					DECLARE @LineTypeCode VARCHAR(20) = '';
					SELECT Top 1 @LineTypeCode = dbo.Assy_FN_Get_LineTypeName_From_LineCode(@ProfitCenterCode,@LineCode)

					IF @LineTypeCode != 'STMC'
					BEGIN
						set @ReturnValue='This Line is not having Coupling Station'
						set @ReturnInt=1
						RETURN
					END

					Declare @CouplingData As Table
						(	CouplingDate Date,
							LineName Varchar(30),
							DateCode Char(4),
							MachineName Varchar(50),
							FG_PartNo Varchar(20),
							FG_Barcode Varchar(60) Primary Key,
							BoosterPartNo Varchar(20),
							BoosterBarcode Varchar(60),
							BoosterScanDate DateTime,
							TMCPartNo Varchar(20),
							TMCBarcode Varchar(60),
							TMCScanDate DateTime
						)

					DELETE FROM @CouplingData

					INSERT INTO @CouplingData (LineName, DateCode, MachineName, FG_Barcode)
					SELECT Distinct L.LineName, A.Datecode, M.MachineName, A.FG_Barcode FROM Assy_CouplingDetails A WITH (NOLOCK)
					INNER JOIN LineMst L WITH (NOLOCK) ON L.ProfitCenterCode = A.ProfitCentreCode AND L.LineCode = A.LineCode
					INNER JOIN MachineMst M WITH (NOLOCK) ON M.ProfitCenterCode = A.ProfitCentreCode AND M.MachineCode = A.MACHINE_CODE
					WHERE A.ProfitCentreCode = @ProfitCenterCode AND A.LineCode = @LineCode 
					AND A.ENT_DT between case when (@isDateCodeFilter=1) then  A.ENT_DT else @FromDate end
									 and case when (@isDateCodeFilter=1) then A.ENT_DT else  @ToDate end
					AND A.DateCode = case when @isDateCodeFilter = 1 then @DateCode else A.DateCode end
					Group By L.LineName, A.Datecode, M.MachineName, A.STMC_PART_NO, A.FG_Barcode
					Order By 2,4

					UPDATE C SET
						C.BoosterPartNo = AC.CHILD_PART_NO,
						C.BoosterBarcode = AC.CHILD_Barcode ,
						C.BoosterScanDate = AC.ENT_DT,
						C.FG_PartNo = AC.STMC_PART_NO
					FROM @CouplingData C
					INNER JOIN Assy_CouplingDetails AC WITH (NOLOCK) ON C.FG_Barcode = AC.FG_Barcode
					WHERE AC.ProfitCentreCode = @ProfitCenterCode AND AC.LineCode = @LineCode
					AND AC.PART_TYPE = 'SERVO' AND  AC.ENT_DT between case when (@isDateCodeFilter=1) then  AC.ENT_DT else @FromDate end
					and case when (@isDateCodeFilter=1) then AC.ENT_DT else  @ToDate end
					AND AC.DateCode = case when @isDateCodeFilter = 1 then @DateCode else AC.DateCode end

					UPDATE C SET
						C.TMCPartNo = AC.CHILD_PART_NO,
						C.TMCBarcode = AC.CHILD_Barcode ,
						C.TMCScanDate = AC.ENT_DT,
						C.CouplingDate = AC.ENT_DT
					FROM @CouplingData C
					INNER JOIN Assy_CouplingDetails AC WITH (NOLOCK)
					ON C.FG_Barcode = AC.FG_Barcode
					WHERE AC.ProfitCentreCode = @ProfitCenterCode AND AC.LineCode = @LineCode
					AND AC.PART_TYPE = 'TMC' AND AC.ENT_DT between case when (@isDateCodeFilter=1) then  AC.ENT_DT else @FromDate end
					and case when (@isDateCodeFilter=1) then AC.ENT_DT else  @ToDate end
					AND AC.DateCode = case when @isDateCodeFilter = 1 then @DateCode else AC.DateCode end

					SELECT CouplingDate, LineName, DateCode, MachineName, FG_PartNo, FG_Barcode, BoosterPartNo, BoosterBarcode, BoosterScanDate, TMCPartNo, TMCBarcode, TMCScanDate
						FROM @CouplingData Order By 1,3,5,6,8,11
			
					set @ReturnValue='SUCCESS'
					set @ReturnInt=0
					return
			end
	else if(@Condition='MANUALPassDATA')
			begin
				--set @Qry='SELECT CAST(A.Timestamp AS DATE) ManualPassDate , A.ProfitCenterCode, L.LineName, M.MachineName, A.Barcode, Case A.Status WHEN ''PS'' THEN ''Pass'' ELSE A.Status END Barcode_Status, A.Remarks
				--	FROM Assy_LineAssyManualPassFail A WITH (NOLOCK)
				--		INNER JOIN MachineMst M WITH (NOLOCK)
				--			ON M.ProfitCenterCode = A.ProfitCenterCode AND M.MachineCode = A.MachineCode
				--				INNER JOIN LineMst L WITH (NOLOCK)
				--					ON L.ProfitCenterCode = A.ProfitCenterCode AND L.LineCode = A.LineCode
				--						WHERE A.ProfitCenterCode ='''+ @ProfitCenterCode + '''AND A.LineCode ='''+  @LineCode +''''

				--if(@FromDate<>'' and @ToDate<>'')
				--	begin											
				--		set @qry=@qry + '  And convert(Date,A.Timestamp)>=convert(Date,''' + @FromDate +''',105) 
				--					AND convert(Date,A.Timestamp)<=Convert(Date,''' + @ToDate +''',105)'										
				--	end
				--if(@PartNo<>'')
				--	begin
				--		set @qry=@qry + ' And A.Barcode like ''%' + @PartNo +'%'''
				--	end
				--if(@DateCode<>'')
				--begin
				--	set @qry=@qry + ' And A.Barcode like ''%' + @DateCode +'%'''
				--end
				--set @Qry=@qry + ' Order By 1,4,5'
				
				--print @Qry
				
				--Execute sp_sqlexec @qry	
				SELECT CAST(A.Timestamp AS DATE) ManualPassDate , A.ProfitCenterCode, L.LineName, M.MachineName, A.Barcode, 
				Case A.Status WHEN 'PS' THEN 'Pass' ELSE A.Status END Barcode_Status, A.Remarks
				FROM Assy_LineAssyManualPassFail A WITH (NOLOCK)
				INNER JOIN MachineMst M WITH (NOLOCK) ON M.ProfitCenterCode = A.ProfitCenterCode AND M.MachineCode = A.MachineCode
				INNER JOIN LineMst L WITH (NOLOCK) ON L.ProfitCenterCode = A.ProfitCenterCode AND L.LineCode = A.LineCode
				WHERE A.ProfitCenterCode =@ProfitCenterCode AND A.LineCode = @LineCode 
				AND A.Timestamp between case when (@isDateCodeFilter=1) then  A.Timestamp else @FromDate end
									and case when (@isDateCodeFilter=1) then A.Timestamp else  @ToDate end
				AND A.Barcode like case when @isDateCodeFilter = 1 then '%'+@DateCode+'%' else A.Barcode end
				AND A.Barcode like '%' + @PartNo +'%' 
				Order By 1,4,5		
				
				set @ReturnValue='SUCCESS'
				set @ReturnInt=0
				return
			end
		else if(@Condition='PACKAGING_SUMMARYDATA')
			begin
				--set @Qry='SELECT SBI.WH_CODE ProfitCenterCode, CAST(SBI.SkidBarcodePrintedTimestamp AS DATE) SkidLabelPrintDate,
				--			SBI.SkidBarcode, SBI.DispatchType, COUNT(SBD.PartBarcode) Qty
				--				FROM SkidBarcodeInfo SBI WITH (NOLOCK)
				--					INNER JOIN SkidBarcodeDetail SBD WITH (NOLOCK)
				--						ON SBI.SkidBarcodeInfoID = SBD.SkidBarcodeInfoID AND SBI.WH_CODE = SBD.WH_CODE
				--							WHERE SBI.WH_CODE =''' + @ProfitCenterCode + '''AND SBD.WH_CODE = ''' + @ProfitCenterCode + '''
				--								AND SBI.SkidBarcodeInfoID IN (SELECT Distinct SkidBarcodeInfoID FROM SkidBarcodeDetail (NOLOCK)
				--											WHERE WH_CODE =''' + @ProfitCenterCode + '''AND SBI.DATECODE=''' + @DateCode + ''')
				--									AND ISNULL(SBI.SkidBarcode,'''') != '''''
				--if(@PartNo<>'')
				--	begin
				--		set @qry=@qry + ' And SBI.SkidBarcode like ''%' + @PartNo +'%'''
				--	end
				--set @Qry=@qry + '	Group By SBI.WH_CODE, SBI.SkidBarcodePrintedTimestamp, SBI.SkidBarcode, SBI.DispatchType
				--		Order By 1,2,3,4,5'
				--		print @Qry
				--Execute sp_sqlexec @qry
				--Comented and replaced by AV ON 20170302

				SELECT SBI.WH_CODE ProfitCenterCode, CAST(SBI.SkidBarcodePrintedTimestamp AS DATE) SkidLabelPrintDate, SBI.SkidBarcode, 
				SBI.DispatchType, COUNT(SBD.PartBarcode) Qty FROM SkidBarcodeInfo SBI WITH (NOLOCK)
				INNER JOIN SkidBarcodeDetail SBD WITH (NOLOCK) ON SBI.SkidBarcodeInfoID = SBD.SkidBarcodeInfoID AND SBI.WH_CODE = SBD.WH_CODE
				inner join Pkg_part_mapping pkg on SBI.PartCustMapId=Pkg.Pkg_Def_ID
				WHERE SBI.WH_CODE = @ProfitCenterCode AND SBD.WH_CODE =  @ProfitCenterCode AND SBD.WH_CODE =@ProfitCenterCode 
				AND CONVERT(DATETIME,SBI.SkidBarcodePrintedTimestamp,111) between case when (@isDateCodeFilter=1) then CONVERT(DATETIME,SBI.SkidBarcodePrintedTimestamp,111) else CONVERT(DATETIME,@FromDate,111) end
														and case when (@isDateCodeFilter=1) then CONVERT(DATETIME,SBI.SkidBarcodePrintedTimestamp,111) else  CONVERT(DATETIME,@ToDate,111) end
				AND SBI.DATECODE = case when @isDateCodeFilter = 1 then @DateCode else SBI.DATECODE end
				AND ISNULL(SBI.SkidBarcode,'')<>''
				And Pkg.PART_NUMBER like '%' + @PartNo +'%'
				Group By SBI.WH_CODE, SBI.SkidBarcodePrintedTimestamp, SBI.SkidBarcode, SBI.DispatchType
				Order By 1,2,3,4,5
				
				set @ReturnValue='SUCCESS'
				set @ReturnInt=0
				return
			end
	else if(@Condition='PACKAGING_SUMMARYDATAWITHBARCODE')
			begin
				--set @Qry='SELECT SBI.WH_CODE ProfitCenterCode, CAST(SBI.SkidBarcodePrintedTimestamp AS DATE) SkidLabelPrintDateTime,
				--			SBI.SkidBarcode, SBI.DispatchType, SBD.PartBarcode, SBD.ScanTimeStamp BarcodeScanDateTime
				--				FROM SkidBarcodeInfo SBI WITH (NOLOCK)
				--					INNER JOIN SkidBarcodeDetail SBD WITH (NOLOCK)
				--						ON SBI.SkidBarcodeInfoID = SBD.SkidBarcodeInfoID AND SBI.WH_CODE = SBD.WH_CODE
				--							WHERE SBI.WH_CODE =''' + @ProfitCenterCode + '''AND SBD.WH_CODE = ''' + @ProfitCenterCode + '''
				--								AND SBI.SkidBarcodeInfoID IN (SELECT Distinct SkidBarcodeInfoID FROM SkidBarcodeDetail (NOLOCK)
				--											WHERE WH_CODE =''' + @ProfitCenterCode + '''AND SBI.DATECODE=''' + @DateCode + ''')
				--									AND ISNULL(SBI.SkidBarcode,'''') != '''''
				--if(@PartNo<>'')
				--	begin
				--		set @qry=@qry + ' And SBI.SkidBarcode like ''%' + @PartNo +'%'''
				--	end
				--set @Qry=@qry + ' Order By 1,2,3,4,5,6'
				--Execute sp_sqlexec @qry	
				--Comented and replaced by AV ON 20170302
				SELECT SBI.WH_CODE ProfitCenterCode, CAST(SBI.SkidBarcodePrintedTimestamp AS DATE) SkidLabelPrintDateTime,
				SBI.SkidBarcode, SBI.DispatchType, SBD.PartBarcode, SBD.ScanTimeStamp BarcodeScanDateTime
				FROM SkidBarcodeInfo SBI (NOLOCK)
				INNER JOIN SkidBarcodeDetail SBD(NOLOCK) ON SBI.SkidBarcodeInfoID = SBD.SkidBarcodeInfoID AND SBI.WH_CODE = SBD.WH_CODE
				inner join Pkg_part_mapping pkg on SBI.PartCustMapId=Pkg.Pkg_Def_ID
				WHERE SBI.WH_CODE =@ProfitCenterCode AND SBD.WH_CODE = @ProfitCenterCode
				AND SBI.SkidBarcodePrintedTimestamp between case when (@isDateCodeFilter=1) then SBI.SkidBarcodePrintedTimestamp else @FromDate end
									and case when (@isDateCodeFilter=1) then SBI.SkidBarcodePrintedTimestamp else  @ToDate end
				AND SBI.DATECODE = case when @isDateCodeFilter = 1 then @DateCode else SBI.DATECODE end
				AND ISNULL(SBI.SkidBarcode,'') <>''
				AND Pkg.PART_NUMBER like '%' + @PartNo +'%' 
				Order By 1,2,3,4,5,6
			
				set @ReturnValue='SUCCESS'
				set @ReturnInt=0
				return
			end
	/*
	This block will executable in central server.
	It is fetching data for all assembly lines.
	EXECUTE Assy_Proc_Traceability_Analysis @ProfitcenterCode='0021'
		,@LineCode='M02'
		,@DateCode='20Qc'
		,@PartNo='ALL'
		,@Condition='BARCODE_TRACE'
	*/
	ELSE IF(@Condition='BARCODE_TRACE')
		BEGIN
			DECLARE @LineTypeName	NVARCHAR(25);
		
			SELECT @LineTypeName=ltm.LineTypeName FROM LineMst lm(NOLOCK) 
				INNER JOIN LineTypeMst ltm(NOLOCK) ON lm.LineTypeCode=ltm.LineTypeCode AND lm.ProfitCenterCode=ltm.ProfitCenterCode
					WHERE lm.LineCode=@LineCode
						AND lm.ProfitCenterCode=@ProfitCentercode
			IF(@LineTypeName='CALIPER')
			BEGIN
				CREATE TABLE #BARCODE_TRACE(
				WH_CODE VARCHAR(10),
				LineCode  VARCHAR(10),
				Datecode  VARCHAR(10),
				PART_NO  VARCHAR(20),
				BARCODE  VARCHAR(50),
				SkidBarcode  VARCHAR(50),
				LOC_ID  VARCHAR(10),
				STATUS  VARCHAR(50)
				)

				SET @PartNo=NULLIF(@PartNo,'ALL')

				INSERT INTO #BARCODE_TRACE(WH_CODE,LineCode,Datecode, PART_NO, BARCODE,SkidBarcode,LOC_ID,STATUS)
				SELECT I.WH_CODE,A.LineCode,A.Datecode,I.SEWS_PART_NO AS PART_NO,D.PartBarcode AS BARCODE,S.SkidBarcode,I.LOC_ID,CASE I.STS_CD WHEN 2 THEN 'PACKED AND SHIPPED' ELSE 'PACKED NOT SHIPPED'  END 
				FROM SKIDBARCODEDETAIL(NOLOCK) D 
				INNER JOIN ASSY_LINEASSYSTATUS(NOLOCK) A ON A.BARCODE=D.PARTBARCODE AND A.PROFITCENTERCODE=D.WH_CODE
				INNER JOIN SKIDBARCODEINFO(NOLOCK) S ON D.SKIDBARCODEINFOID=S.SKIDBARCODEINFOID AND S.WH_CODE=D.WH_CODE
				INNER JOIN INV_SERIAL(NOLOCK) I ON I.SERIAL_NO=S.PKG_TS_SERIAL
				WHERE A.LineCode=@LineCode AND S.DATECODE=@DateCode AND A.DATECODE=@DateCode AND S.WH_CODE=@ProfitCenterCode
				AND A.ProfitCenterCode=@ProfitCenterCode AND I.SEWS_PART_NO=ISNULL(@PartNo,I.SEWS_PART_NO)

				INSERT INTO #BARCODE_TRACE(WH_CODE,LineCode,Datecode, PART_NO, BARCODE,SkidBarcode,LOC_ID,STATUS)
				SELECT A.ProfitCenterCode AS WH_CODE ,A.LineCode,A.Datecode,A.PartNo AS PART_NO,A.Barcode AS BARCODE, '' AS SkidBarcode,'' LOC_ID,'NOT PACKED AND NOT SHIPPED' AS STATUS 
				FROM  Assy_LineAssyStatus A (NOLOCK)
				LEFT JOIN #BARCODE_TRACE B ON A.Barcode=B.BARCODE
				WHERE A.ProfitCenterCode=@ProfitCenterCode AND A.LineCode=@LineCode AND A.DATECODE=@DateCode AND ISNULL(B.BARCODE,'')=''
				AND A.PartNo=ISNULL(@PartNo,A.PartNo)

				SELECT * FROM #BARCODE_TRACE
				RETURN

			END
			SET @Qry='DECLARE @tbTraceBarcodeStatus AS TABLE
						(
						ProfitCenterCode			VARCHAR(10)
						,LineCode					VARCHAR(10)
						,DateCode					VARCHAR(4)
						,PartNo						VARCHAR(15)
						,Barcode					NVARCHAR(100)
						,Servo						NVARCHAR(100)
						,TMC						NVARCHAR(100)
						,SkidBarcode				NVARCHAR(100)
						,SkidSerialNo				NVARCHAR(15)
						,WH_Code					VARCHAR(10)
						,SkidOrPartCurrentLocation	VARCHAR(100)
						,CurrentStatus				VARCHAR(100)); 

						IF(OBJECT_ID(''tempdb..#CouplingDetails'')) IS NOT NULL 
							DROP TABLE #CouplingDetails '

			IF(@LineTypeName='TMC') -- We are checking the line type TMC or STMC
				BEGIN
					SET @Qry=@Qry + ' SELECT acd.ProfitCentreCode,acd.LineCode, acd.DateCode, acd.STMC_PART_NO AS PartNo, acd.FG_Barcode AS Barcode, acd.PART_TYPE, acd.CHILD_Barcode
							INTO #CouplingDetails FROM  Assy_CouplingDetails acd(NOLOCK)  
							WHERE acd.FG_Barcode IN (SELECT FG_Barcode FROM Assy_CouplingDetails acd(NOLOCK) INNER JOIN assy_lineassystatus alas(NOLOCK) ON acd.Child_Barcode =alas.Barcode  
								AND acd.ProfitCentreCode=alas.ProfitCenterCode 
							WHERE alas.datecode =''' + @DateCode  + '''
								AND alas.LineCode=''' + @LineCode + ''''
						IF(@PartNo<>'ALL')
							BEGIN
								SET @Qry=@Qry + ' and alas.Partno=''' + @PartNo + ''''
							END
					SET @Qry=@Qry + ' AND alas.ProfitCenterCode=''' + @ProfitCentercode +''')'
				END
			IF(@LineTypeName='STMC')
				BEGIN
					SET @Qry=@Qry + ' SELECT acd.ProfitCentreCode,acd.LineCode,acd.DateCode,acd.STMC_PART_NO AS PartNo,acd.FG_Barcode AS Barcode,acd.PART_TYPE,acd.CHILD_Barcode  
										INTO #CouplingDetails FROM  Assy_CouplingDetails acd (NOLOCK) 
											WHERE acd.datecode =''' + @DateCode + '''
												AND acd.LineCode=''' + @LineCode + '''' 
							IF(@PartNo<>'ALL')
							BEGIN
								SET @Qry=@Qry + ' AND acd.STMC_Part_no=''' + @PartNo + ''''
							END
					SET @Qry=@Qry + ' AND acd.ProfitCentreCode=''' + @ProfitCentercode +''''
				END
				IF(@LineTypeName='CALIPER') -- We are checking the line type TMC or STMC
				BEGIN
					SET @Qry=@Qry + ' SELECT acd.ProfitCentreCode,acd.LineCode, acd.DateCode, acd.STMC_PART_NO AS PartNo, acd.FG_Barcode AS Barcode, acd.PART_TYPE, acd.CHILD_Barcode
							INTO #CouplingDetails FROM  Assy_CouplingDetails acd(NOLOCK)  
							WHERE acd.FG_Barcode IN (SELECT FG_Barcode FROM Assy_CouplingDetails acd(NOLOCK) INNER JOIN assy_lineassystatus alas(NOLOCK) ON acd.Child_Barcode =alas.Barcode  
								AND acd.ProfitCentreCode=alas.ProfitCenterCode 
							WHERE alas.datecode =''' + @DateCode  + '''
								AND alas.LineCode=''' + @LineCode + ''''
						IF(@PartNo<>'ALL')
							BEGIN
								SET @Qry=@Qry + ' and alas.Partno=''' + @PartNo + ''''
							END
					SET @Qry=@Qry + ' AND alas.ProfitCenterCode=''' + @ProfitCentercode +''')'
				END
			SET @Qry=@Qry + ' INSERT INTO @tbTraceBarcodeStatus SELECT pitb.*,sbi.SkidBarcode,iv.Serial_no,iv.WH_CODE,iv.Loc_id+ '' - '' + cm.CUSTOMER_NM AS SkidorPartCurrentLocation, ''COUPLED, PACKED,SHIPPED'' AS CurrentStatus FROM #CouplingDetails cd 
								PIVOT (MAX(CHILD_Barcode)  FOR Part_Type IN ([SERVO],[TMC])) AS pitb 
								INNER JOIN SkidBarcodeDetail sbd(NOLOCK) ON sbd.PartBarcode=pitb.Barcode 
								INNER JOIN SkidBarcodeInfo sbi(NOLOCK) ON sbi.SkidBarcodeInfoID=sbd.SkidBarcodeInfoID 
								INNER JOIN inv_serial iv(NOLOCK) on iv.SERIAL_NO=sbi.pkg_ts_serial 
								INNER JOIN Customer_Master cm(NOLOCK) ON cm.Customer_C=iv.LOC_ID
			
							INSERT INTO @tbTraceBarcodeStatus SELECT pitb.*,sbi.SkidBarcode,iv.Serial_no,iv.WH_CODE,iv.Loc_id + '' - '' + LM.LOCATION_NAME, ''COUPLED, PACKED,NOT SHIPPED'' AS CurrentStatus FROM #CouplingDetails cd 
								PIVOT (MAX(CHILD_Barcode)  FOR Part_Type IN ([SERVO],[TMC])) AS pitb 
								INNER JOIN SkidBarcodeDetail sbd(NOLOCK) ON sbd.PartBarcode=pitb.Barcode 
								INNER JOIN SkidBarcodeInfo sbi(NOLOCK) ON sbi.SkidBarcodeInfoID=sbd.SkidBarcodeInfoID 
								INNER JOIN inv_serial iv(NOLOCK) on iv.SERIAL_NO=sbi.pkg_ts_serial 
								INNER JOIN LOCATION_MASTER lm(NOLOCK) ON lm.LOC_ID=iv.LOC_ID
	
							INSERT INTO @tbTraceBarcodeStatus SELECT pitb.*,'''' AS SkidBarcode,'''' AS Serial_no,lm.ProfitCenterCode,lm.WorkCenterCode AS Loc_id, ''COUPLED, NOT PACKED'' AS CurrentStatus FROM #CouplingDetails cd 
								PIVOT (MAX(CHILD_Barcode)  FOR Part_Type IN ([SERVO],[TMC])) AS pitb 
								INNER JOIN lineMst lm(NOLOCK) ON lm.LineCode=pitb.LineCode AND lm.ProfitCenterCode=pitb.ProfitCentreCode 
									WHERE pitb.Barcode NOT IN (SELECT Barcode FROM @tbTraceBarcodeStatus) 
	
							 INSERT INTO @tbTraceBarcodeStatus SELECT alas.ProfitCenterCode,alas.LineCode, alas.DateCode, 


							alas.PartNo, alas.Barcode,'''' AS SERVO,'''' AS TMC, sbi.SkidBarcode,iv.Serial_no,iv.WH_CODE,iv.Loc_id + '' - '' + cm.CUSTOMER_NM,
							''PACKED,SHIPPED'' as CurrentStatus
							 from assy_lineassystatus alas(NOLOCK) 
								INNER JOIN SkidBarcodeDetail sbd(NOLOCK) ON sbd.PartBarcode=alas.Barcode 
								INNER JOIN SkidBarcodeInfo sbi(NOLOCK) ON sbi.SkidBarcodeInfoID=sbd.SkidBarcodeInfoID 
								INNER JOIN inv_serial iv(NOLOCK) ON iv.SERIAL_NO=sbi.pkg_ts_serial 
								INNER JOIN Customer_Master cm(NOLOCK) ON cm.Customer_C=iv.LOC_ID
								WHERE alas.datecode=''' + @DateCode + '''   
									AND alas.LineCode=''' + @LineCode + '''
									AND alas.ProfitCenterCode=''' + @ProfitCenterCode + '''

							INSERT INTO @tbTraceBarcodeStatus SELECT alas.ProfitCenterCode,alas.LineCode, alas.DateCode, alas.PartNo, alas.Barcode,'''' AS SERVO,
							'''' AS TMC, sbi.SkidBarcode,iv.Serial_no,iv.WH_CODE,iv.Loc_id + '' - '' + LM.LOCATION_NAME,
							''PACKED,NOT SHIPPED'' as CurrentStatus from assy_lineassystatus alas(NOLOCK) 
								INNER JOIN SkidBarcodeDetail sbd(NOLOCK) ON sbd.PartBarcode=alas.Barcode 
								INNER JOIN SkidBarcodeInfo sbi(NOLOCK) ON sbi.SkidBarcodeInfoID=sbd.SkidBarcodeInfoID 
								INNER JOIN inv_serial iv(NOLOCK) ON iv.SERIAL_NO=sbi.pkg_ts_serial 
								INNER JOIN LOCATION_MASTER lm(NOLOCK) ON lm.LOC_ID=iv.LOC_ID
								WHERE alas.datecode=''' + @DateCode + '''  
									AND alas.LineCode=''' + @LineCode + '''
									AND alas.ProfitCenterCode=''' + @ProfitCenterCode + '''
									AND alas.Barcode NOT IN (SELECT Barcode FROM @tbTraceBarcodeStatus) 

		
							INSERT INTO @tbTraceBarcodeStatus SELECT alas.ProfitCenterCode,alas.LineCode, alas.DateCode, alas.PartNo, alas.Barcode,'''' as SERVO,'''' as TMC,
							 '''' as SkidBarcode,'''' as Serial_no,lm.ProfitCenterCode,lm.WorkCenterCode as Loc_id,
							''NOT COUPLED / NOT PACKED'' as CurrentStatus from assy_lineassystatus alas(NOLOCK)  
								INNER JOIN lineMst lm(NOLOCK) on lm.LineCode=alas.LineCode AND lm.ProfitCenterCode=alas.ProfitCenterCode 
								WHERE alas.Barcode NOT IN (SELECT Barcode FROM @tbTraceBarcodeStatus) 
									AND alas.Barcode NOT IN (SELECT TMC FROM @tbTraceBarcodeStatus WHERE TMC<>'''') 
									AND  alas.datecode=''' + @DateCode + '''  
									AND alas.LineCode=''' + @LineCode + '''
									AND alas.ProfitCenterCode=''' + @ProfitCenterCode + ''''

						IF(@PartNo<>'ALL')
							BEGIN
								SET @Qry=@Qry + ' and alas.Partno=''' + @PartNo + ''''
							END

						SET @Qry=@Qry + ' SELECT * FROM @tbTraceBarcodeStatus'
						PRINT @Qry
				EXECUTE sp_sqlexec @Qry
		END
	ELSE IF(@Condition='MANPOWER_DATA')
			BEGIN
				SELECT amp.ProfitCenterCode,PartNo,LineCode,mm.MachineName,DateCode,Clock_ID,Created_TimeStamp FROM assy_manpower4s amp(NOLOCK) 
				INNER JOIN MachineMst mm ON	amp.ProfitCenterCode=mm.ProfitCenterCode AND amp.StationCode=mm.MachineCode 
				WHERE	amp.Created_TimeStamp between case when (@isDateCodeFilter=1) then  amp.Created_TimeStamp else @FromDate end
												  and case when (@isDateCodeFilter=1) then amp.Created_TimeStamp else  @ToDate end
				and amp.DateCode = case when @isDateCodeFilter = 1 then @DateCode else amp.DateCode end
				AND amp.LineCode=@LineCode AND amp.ProfitCenterCode=@ProfitCentercode
				--@isDateCodeFilter

				ORDER  BY 1,2 ASC
			END
	ELSE IF(@Condition='POKAYOKE_RESULT')
		BEGIN
			
			set @FromDate = @FromDate + ' 00:00:00.000'
			set @TODATE = @TODATE + ' 23:59:59.999'		

			SELECT FORMAT(ResultTimestamp,'dd-MM-yyyy') AS [Date], UserID AS UserID ,
			pk.LineCode  AS LineCode, pk.Datecode AS DateCode,PK.PartNo AS PartNo,
			ISNULL(OM.OperationName,'') AS OperatorName,
			PK.Barcode,PK.ExpResult as 'Expected Status',
			CASE WHEN ISNULL(Pk.IsActive,0)=0 THEN 'By Pass' ELSE ISNULL(pk.ActResult,'') 
			END AS  'Actual Status',ISNULL(pk.Description,'') AS [Description]			
			FROM Assy_POKAYOKE_Status PK WITH(NOLOCK) 			
			LEFT OUTER JOIN OperationMst OM WITH (NOLOCK) ON pk.OperationCode =OM.OperationCode 
			LEFT OUTER JOIN RoutingConfigLineWise RL WITH (NOLOCK) ON UPPER(LTRIM(RTRIM(PK.linecode)))=UPPER(LTRIM(RTRIM(RL.linecode))) 
			AND LTRIM(RTRIM(PK.operationcode))=LTRIM(RTRIM(rl.operationcode))
			WHERE	
			--pk.Datecode=@DateCode AND 
			pk.ScanTimestamp between case when (@isDateCodeFilter=1) then pk.ScanTimestamp else @FromDate end
													and case when (@isDateCodeFilter=1) then pk.ScanTimestamp else  @ToDate end
			AND pk.Datecode = case when @isDateCodeFilter = 1 then @DateCode else PK.DATECODE end
			AND PK.PartNo=isNull(nullif(@Partno,''),PK.PartNo)
			AND pk.LineCode=@LineCode
			and pk.ProfitCenterCode =@ProfitCentercode
			ORDER BY 3,4 ASC
		END
	ELSE IF(@Condition='MANUAL_PRINTED_BARCODES')
		BEGIN
			SELECT ProfitCenterCode,LineCode,DateCode,Barcode,TimeStamp,PartNo FROM Assy_Manual_Printed_Barcode WITH (NOLOCK)
			WHERE Timestamp between case when (@isDateCodeFilter=1) then Timestamp else @FromDate end
								and case when (@isDateCodeFilter=1) then Timestamp else  @ToDate end
			AND DATECODE = case when @isDateCodeFilter = 1 then @DateCode else DATECODE end
			AND LineCode=@LineCode
			AND ProfitCenterCode=@ProfitCentercode
			ORDER BY 1,2,3,4 ASC
		END
	else if(@Condition='PARAMETER_DATA_ANALYSIS')
			begin
				-- Delete Temp Tables
				DECLARE @JoinQuery1 VARCHAR(MAX)=''
				BEGIN
					IF(OBJECT_ID('tempdb...#AssyParamdata')) IS NOT NULL
						DROP TABLE #AssyParamdata

					IF(OBJECT_ID('tempdb...#TagDetails')) IS NOT NULL
						DROP TABLE #TagDetails
					IF(OBJECT_ID('tempdb...#MachineDetails')) IS NOT NULL
						DROP TABLE #MachineDetails
					IF(OBJECT_ID('TEMP_Report_ParamDataTable')) IS NOT NULL
					DROP TABLE TEMP_Report_ParamDataTable
					IF(OBJECT_ID('TEMP_Report_TagDetailS')) IS NOT NULL
					DROP TABLE TEMP_Report_TagDetailS
					IF(OBJECT_ID('TEMP_Report_MachineDetails')) IS NOT NULL
					DROP TABLE TEMP_Report_MachineDetails
					IF(OBJECT_ID('TEMP_REPORT_MC4S')) IS NOT NULL
					DROP TABLE TEMP_REPORT_MC4S
					IF(OBJECT_ID('TEMP_REPORT_MCPA')) IS NOT NULL
					DROP TABLE TEMP_REPORT_MCPA
					IF(OBJECT_ID('TEMP_REPORT_MCLP')) IS NOT NULL
					DROP TABLE TEMP_REPORT_MCLP
					IF(OBJECT_ID('TEMP_REPORT_MCHP')) IS NOT NULL
					DROP TABLE TEMP_REPORT_MCHP
					IF(OBJECT_ID('TEMP_REPORT_MCDC')) IS NOT NULL
					DROP TABLE TEMP_REPORT_MCDC
					IF(OBJECT_ID('TEMP_REPORT_MCFA')) IS NOT NULL
					DROP TABLE TEMP_REPORT_MCFA
					IF(OBJECT_ID('TEMP_REPORT_MCSR')) IS NOT NULL
					DROP TABLE TEMP_REPORT_MCSR
					IF(OBJECT_ID('TEMP_REPORT_MCFV')) IS NOT NULL
					DROP TABLE TEMP_REPORT_MCFV
					IF(OBJECT_ID('TEMP_REPORT_MCIG')) IS NOT NULL
					DROP TABLE TEMP_REPORT_MCIG
					IF(OBJECT_ID('TEMP_REPORT_MCHA')) IS NOT NULL
					DROP TABLE TEMP_REPORT_MCHA
					IF(OBJECT_ID('TEMP_REPORT_MCCP')) IS NOT NULL
					DROP TABLE TEMP_REPORT_MCCP
					IF(OBJECT_ID('TEMP_REPORT_MC10')) IS NOT NULL 
					DROP TABLE TEMP_REPORT_MC10
					IF(OBJECT_ID('TEMP_REPORT_MC100')) IS NOT NULL 
					DROP TABLE TEMP_REPORT_MC100
					IF(OBJECT_ID('TEMP_REPORT_MC110')) IS NOT NULL 
					DROP TABLE TEMP_REPORT_MC110
					IF(OBJECT_ID('TEMP_REPORT_MC120')) IS NOT NULL 
					DROP TABLE TEMP_REPORT_MC120
