					SELECT @cols2 = STUFF((SELECT ',' + QUOTENAME(MachineCode) + ' AS [' + MachineName +' TimeStamp]' FROM #TagDetails2 WHERE MachineCode IN (SELECT MachineCode FROM #MachineDetails2)
