					SELECT @cols2 = STUFF((SELECT ',' + QUOTENAME(MachineCode) + ' AS [' + MachineName +' TimeStamp]' FROM #TagDetails3 WHERE MachineCode IN (SELECT MachineCode FROM #MachineDetails3)
