																			GROUP BY OperationSeqNo,MachineCode
																			ORDER BY OperationSeqNo,MachineCode
																FOR XML PATH(''), TYPE
																).value('.', 'NVARCHAR(MAX)') 
															,1,1,'')
									SELECT @cols2 = STUFF((SELECT ',' + QUOTENAME(MachineCode) + ' AS [' + MachineName +' TimeStamp]' FROM #TagDetails15 WHERE MachineCode IN (SELECT MachineCode FROM #MachineDetails15 where ID=@ID1)
																			GROUP BY OperationSeqNo,MachineCode,MachineName
																			ORDER BY OperationSeqNo,MachineCode,MachineName
																FOR XML PATH(''), TYPE
																).value('.', 'NVARCHAR(MAX)') 
															,1,1,'')

					
									SET @TableName =(SELECT TOP 1 MachineCode FROM #MachineDetails15 WHERE ID=@ID1)
									SELECT ROW_NUMBER() OVER(ORDER BY OperationSeqNo,TagName ASC) AS ID, * INTO #TagDetails16 fROM #TagDetails15 WHERE MachineCode=@TableName ORDER BY OperationSeqNo,MachineCode,TagName
									--select * from #TagDetails16 
									declare @iii int =1;
									SET @id3 =(select count(*) from #TagDetails16)
									
									set @sql='';
									set @SqlStart = '
											CREATE TABLE #' + @TableName + ' ( ProfitCenterCode NVARCHAR(50),FGBarcode NVARCHAR(50),SERVOBARCODE NVARCHAR(50),TMCBARCODE NVARCHAR(50),MachineName NVARCHAR(50), TimeStamp NVARCHAR(30), Result NVARCHAR(50) '
				
									--while @iii<=@id3
