									--		SET @iii=@iii+1
									--	end
									SET @sqlEnd=@SqlStart + ')'
	--PRINT @sqlEnd
									SET @sqlEnd = @sqlEnd + '
												INSERT INTO #' + @TableName + ' 
												SELECT A.ProfitCenterCode,A.FGBarcode,A.SERVOBARCODE,A.TMCBARCODE,MachineName,'+ @cols2 +' ,Result AS Result  FROM 
													(
													SELECT ProfitCenterCode,FGBarcode,MachineCode,MachineName,Result,Timestamp,OperationSeqNo,SERVOBarcode,TMCBarcode
													FROM @SERVOPARAMDATA1 WHERE MachineCode IN (SELECT MachineCode FROM #MachineDetails15 where ID=' + CAST(@ID1 as varchar) + ')
												) tmptable
													
												PIVOT 
												(
													MAX(Timestamp)
													FOR MachineCode in (' + @cols1 + ')
												) A '

									SET @TableQuery =@TableQuery + @sqlend
									SET @SqlStart=''
									SET @ID1=@ID1+1
				
							IF(@JoinQuery='')
