			,Result				NVARCHAR(20)
			,Timestamp			DATETIME
			,OperationSeqNo		INT
			,ServoBarcode		NVARCHAR(100)
			,TMCBarcode			NVARCHAR(100)
			)
		 INSERT INTO @SERVOPARAMDATA1 SELECT DISTINCT * FROM (SELECT acd.ProfitCentreCode as ProfitCenterCode,acd.LineCode,acd.Datecode,mm.MachineName,mm.MachineCode,acd.STMC_PART_NO,acd.FG_Barcode as Barcode,acd.PART_TYPE,acd.Child_Barcode,
						ISNULL(alpd.TagName,mm.MachineCode + ''_Station'') AS TagName, convert(varchar(20),alpd.Value) AS Value,
						CASE WHEN alpd.Result=''PS'' THEN ''Pass''
							WHEN alpd.Result=''FL'' THEN ''Fail''
							ELSE alpd.Result END AS Result,alpd.Timestamp,rclw.OperationSeqNo
							 FROM Assy_View_ParamData alpd(NOLOCK)
								INNER JOIN  Assy_CouplingDetails acd (NOLOCK) ON acd.LineCode=alpd.LineCode
									AND alpd.Barcode in (acd.Child_Barcode,acd.FG_Barcode)
									AND acd.ProfitCentreCode=alpd.ProfitCenterCode
									AND acd.STMC_PART_NO=alpd.PartNo
									AND acd.DateCode=alpd.DateCode
										left JOIN TagMst tm(NOLOCK) ON ISNULL(alpd.tagid,0)=ISNULL(tm.tagid,0)
											JOIN MachineMst mm(NOLOCK) ON mm.Machinecode=alpd.Machinecode
												JOIN RoutingConfigLineWise rclw(NOLOCK)  ON rclw.MachineCode=mm.MachineCode
												WHERE  alpd.Timestamp between case when (''' + convert(varchar,@isDateCodeFilter) + '''=1) then  alpd.Timestamp else ''' + @FromDate + ''' end
																		     and case when (''' + convert(varchar,@isDateCodeFilter)  + '''=1) then alpd.Timestamp else ''' + @ToDate + '''  end
													AND alpd.DateCode = case when ''' + convert(varchar,@isDateCodeFilter) + ''' = 1 then ''' + @DateCode + ''' else alpd.DateCode end
													AND alpd.LineCode=''' + @LineCode + '''
													AND alpd.ProfitCenterCode=''' + @ProfitCenterCode + '''
													AND ISNULL(alpd.Tagname,alpd.MachineCode) in (SELECT CASE WHEN tagname='''' THEN MachineCode + ''_Station'' ELSE tagname END AS tagname FROM Assy_TraceabilityAnalysis_Tags (NOLOCK) 
													WHERE ProfitCentercode=''' + @ProfitCentercode + ''' AND LineCode=''' + @LineCode + ''' AND activestatus=1)) A
													PIVOT(MAX(CHild_Barcode) FOR Part_Type IN ([SERVO],[TMC])) AS tbResult


		INSERT INTO @SERVOPARAMDATA1	SELECT avpd.ProfitCenterCode, avpd.LineCode,avpd.Datecode, mm.MachineName,mm.MachineCode,avpd.PartNo, avpd.Barcode,ISNULL(avpd.TagName,mm.MachineName) AS TagName,ISNULL(avpd.Value,'''') AS Value, 
									CASE WHEN avpd.Result= ''PS'' THEN ''Pass''
									WHEN avpd.Result=''FL'' THEN ''Fail''
									ELSE avpd.Result END AS Result ,avpd.Timestamp, rclw.OperationSeqNo,'''' AS ServoBarcode,'''' AS TMCBarcode
								FROM Assy_View_ParamData avpd
									INNER JOIN MachineMst mm ON avpd.MachineCode=mm.MachineCode
										AND avpd.ProfitCenterCode=mm.ProfitCenterCode
									INNER JOIN RoutingConfigLineWise rclw ON avpd.LineCode=rclw.LineCode
										AND avpd.MachineCode=rclw.MachineCode
										AND avpd.ProfitCenterCode=rclw.ProfitCenterCode
							WHERE avpd.Timestamp between case when (''' + convert(varchar,@isDateCodeFilter) + '''=1) then  avpd.Timestamp else ''' + @FromDate + ''' end
													and case when (''' + convert(varchar,@isDateCodeFilter)  + '''=1) then avpd.Timestamp else ''' + @ToDate + '''  end
							AND avpd.DateCode = case when ''' + convert(varchar,@isDateCodeFilter) + ''' = 1 then ''' + @DateCode + ''' else avpd.DateCode end
								AND avpd.ProfitCenterCode=''' + @ProfitCenterCode + '''
								AND avpd.LineCode='''  + @LineCode + '''
								AND isnull(avpd.TagName,avpd.MachineCode) IN (select case when tagname='''' then MachineCode + ''_Station''  else tagname end as tagname from Assy_TraceabilityAnalysis_Tags (nolock) 
								where ProfitCentercode=''' + @ProfitCenterCode + ''' and LineCode='''+ @Linecode +''' and activestatus=1)
								AND avpd.Barcode NOT IN (SELECT FGBARCODE FROM @SERVOPARAMDATA1)
								ORDER BY rclw.OperationSeqNo 
							
								SELECT DISTINCT DENSE_RANK() OVER(ORDER BY OperationSeqNo ASC) AS ID, MachineCode,MachineName,OperationSeqNo INTO #MachineDetails13 FROM @SERVOPARAMDATA1'

							--DROP TABLE @SERVOPARAMDATA1 
		 INSERT INTO @SERVOPARAMDATA1 SELECT DISTINCT * FROM (SELECT acd.ProfitCentreCode as ProfitCenterCode,acd.LineCode,acd.Datecode,mm.MachineName,mm.MachineCode,acd.STMC_PART_NO,acd.FG_Barcode as Barcode,acd.PART_TYPE,acd.Child_Barcode,
						ISNULL(alpd.TagName,mm.MachineCode + '_Station') AS TagName, convert(varchar(20),alpd.Value) AS Value,
						CASE WHEN alpd.Result='PS' THEN 'Pass'
							WHEN alpd.Result='FL' THEN 'Fail'
							--WHEN alpd.Result='PE' THEN 'Fail'
							ELSE alpd.Result END AS Result,alpd.Timestamp,rclw.OperationSeqNo
							 FROM Assy_View_ParamData alpd(NOLOCK)
								INNER JOIN  Assy_CouplingDetails acd (NOLOCK) ON acd.LineCode=alpd.LineCode
									AND alpd.Barcode in (acd.Child_Barcode,acd.FG_Barcode)
									AND acd.ProfitCentreCode=alpd.ProfitCenterCode
									AND acd.STMC_PART_NO=alpd.PartNo
									AND acd.DateCode=alpd.DateCode
										left JOIN TagMst tm(NOLOCK) ON ISNULL(alpd.tagid,0)=ISNULL(tm.tagid,0)
											JOIN MachineMst mm(NOLOCK) ON mm.Machinecode=alpd.Machinecode
												JOIN RoutingConfigLineWise rclw(NOLOCK)  ON rclw.MachineCode=mm.MachineCode
												WHERE  alpd.Timestamp between case when (@isDateCodeFilter =1) then  alpd.Timestamp else @FromDate end
																		and case when (@isDateCodeFilter =1) then alpd.Timestamp else @ToDate end
													AND alpd.DateCode = case when @isDateCodeFilter= 1 then @DateCode else alpd.DateCode end
													AND alpd.LineCode=@LineCode
													AND alpd.ProfitCenterCode=@ProfitCentercode
													AND ISNULL(alpd.Tagname,alpd.MachineCode) in (SELECT CASE WHEN tagname='' THEN MachineCode + '_Station' ELSE tagname END AS tagname 
													FROM Assy_TraceabilityAnalysis_Tags (NOLOCK) WHERE ProfitCentercode=@ProfitCentercode AND LineCode=@LineCode AND activestatus=1)
					) A
					PIVOT(MAX(CHild_Barcode) FOR Part_Type IN ([SERVO],[TMC])) AS tbResult


		INSERT INTO @SERVOPARAMDATA1	SELECT avpd.ProfitCenterCode, avpd.LineCode,avpd.Datecode, mm.MachineName,mm.MachineCode,avpd.PartNo, avpd.Barcode,ISNULL(avpd.TagName,mm.MachineName) AS TagName,ISNULL(avpd.Value,'') AS Value, 
									CASE WHEN avpd.Result= 'PS' THEN 'Pass'
									WHEN avpd.Result='FL' THEN 'Fail'
									ELSE avpd.Result END AS Result ,avpd.Timestamp, rclw.OperationSeqNo,'' AS ServoBarcode,'' AS TMCBarcode
								FROM Assy_View_ParamData avpd
									INNER JOIN MachineMst mm ON avpd.MachineCode=mm.MachineCode
										AND avpd.ProfitCenterCode=mm.ProfitCenterCode
									INNER JOIN RoutingConfigLineWise rclw ON avpd.LineCode=rclw.LineCode
										AND avpd.MachineCode=rclw.MachineCode
										AND avpd.ProfitCenterCode=rclw.ProfitCenterCode
							WHERE avpd.Timestamp between case when (@isDateCodeFilter=1) then  avpd.Timestamp else @FromDate end
														 and case when (@isDateCodeFilter =1) then avpd.Timestamp else @ToDate end
								AND avpd.DateCode = case when @isDateCodeFilter = 1 then @DateCode else avpd.DateCode end
								AND avpd.ProfitCenterCode=@ProfitCenterCode
								AND avpd.LineCode=@LineCode
								AND isnull(avpd.TagName,avpd.MachineCode) IN (select case when tagname='' then MachineCode + '_Station'  else tagname end as tagname from 
								Assy_TraceabilityAnalysis_Tags (nolock) where ProfitCentercode=@ProfitCentercode and LineCode=@LineCode and activestatus=1)
								AND avpd.BARCODE NOT IN (SELECT FGBARCODE FROM @SERVOPARAMDATA1)
							ORDER BY rclw.OperationSeqNo


							SELECT Distinct MachineCode,MachineName,Tagname,OperationSeqNo into #TagDetailS13 FROM @SERVOPARAMDATA1 order by TagName

							--DROP TABLE #TagDetailS
		
							SELECT DISTINCT DENSE_RANK() OVER(ORDER BY OperationSeqNo ASC) AS ID, MachineCode,MachineName,OperationSeqNo INTO #MachineDetails13 FROM @SERVOPARAMDATA1
							SELECT * FROM #MachineDetails13 --ORDER BY ID
							SELECT * FROM #TagDetails13 ORDER BY OperationSeqNo,MachineCode,TagName

							SET @COUNT=(SELECT  count(*) FROM #MachineDetails13)
							set @ID1=1;
							WHILE @ID1<=@COUNT
								BEGIN
									SET @TEMPQUERY= @TEMPQUERY + '
												if exists(select * from tempdb.dbo.sysobjects o
														where o.name like ''%' + (SELECT MachineCode FROM #MachineDetails13 where ID=@ID1) + '%'') 
															DROP TABLE #' + (SELECT MachineCode FROM #MachineDetails13 where ID=@ID1) +'  '
									SET @ID1 =@ID1 + 1;
								END

							SET @ID1=1;
				
							WHILE @ID1<=@COUNT
								BEGIN

									SELECT @cols = STUFF((SELECT ',' + QUOTENAME(TagName) FROM #TagDetails13 WHERE MachineCode IN (SELECT MachineCode FROM #MachineDetails13 where ID=@ID1)
																			GROUP BY OperationSeqNo,MachineCode,TagName
																			ORDER BY  OperationSeqNo,MachineCode,TagName
																FOR XML PATH(''), TYPE
																).value('.', 'NVARCHAR(MAX)') 
															,1,1,'')
	
									SELECT @cols1 = STUFF((SELECT ',' + QUOTENAME(MachineCode) FROM #TagDetails13 WHERE MachineCode IN (SELECT MachineCode FROM #MachineDetails13 where ID=@ID1)
																			GROUP BY OperationSeqNo,MachineCode
																			ORDER BY OperationSeqNo,MachineCode
																FOR XML PATH(''), TYPE
																).value('.', 'NVARCHAR(MAX)') 
															,1,1,'')
									SELECT @cols2 = STUFF((SELECT ',' + QUOTENAME(MachineCode) + ' AS [' + MachineName +' TimeStamp]' FROM #TagDetails13 WHERE MachineCode IN (SELECT MachineCode FROM #MachineDetails13 where ID=@ID1)
																			GROUP BY OperationSeqNo,MachineCode,MachineName
																			ORDER BY OperationSeqNo,MachineCode,MachineName
																FOR XML PATH(''), TYPE
																).value('.', 'NVARCHAR(MAX)') 
															,1,1,'')

					
									SET @TableName =(SELECT TOP 1 MachineCode FROM #MachineDetails13 WHERE ID=@ID1)
									SELECT ROW_NUMBER() OVER(ORDER BY OperationSeqNo,TagName ASC) AS ID, * INTO #TagDetails14 fROM #TagDetails13 WHERE MachineCode=@TableName ORDER BY OperationSeqNo,MachineCode,TagName
									--select * from #TagDetails14 
									declare @ii int =1;
									SET @id3 =(select count(*) from #TagDetails14)
									
									set @sql='';
									set @SqlStart = '
											CREATE TABLE #' + @TableName + ' ( ProfitCenterCode NVARCHAR(50),FGBarcode NVARCHAR(50),SERVOBARCODE NVARCHAR(50),TMCBARCODE NVARCHAR(50),MachineName NVARCHAR(50), TimeStamp NVARCHAR(30), Result NVARCHAR(50) '
				
									while @ii<=@id3
										begin
										--select TagName from #TagDetails14 where ID=@ii
											SET @sql = @sql + ',[' + (select TagName from #TagDetails14 where MachineCode=@TableName AND id=@ii) + ']	NVARCHAR(50) '
											SET @ii=@ii+1
										end
									SET @sqlEnd=@SqlStart + @sql + ')'
	--PRINT @sqlEnd
									SET @sqlEnd = @sqlEnd + '
												INSERT INTO #' + @TableName + ' 
												SELECT A.ProfitCenterCode,A.FGBarcode,A.SERVOBARCODE,A.TMCBARCODE,MachineName,'+ @cols2 +' ,Result AS Result,' + @cols + '  FROM 
													(
													SELECT ProfitCenterCode,FGBarcode,MachineCode,MachineName,TagName,Value,Result,Timestamp,OperationSeqNo,SERVOBarcode,TMCBarcode
													FROM @SERVOPARAMDATA1 WHERE MachineCode IN (SELECT MachineCode FROM #MachineDetails13 where ID=' + CAST(@ID1 as varchar) + ')
												) tmptable
													
												PIVOT 
												(
													MAX(Value)
													FOR TagName in (' + @cols + ')
												) P1

												PIVOT 
												(
													MAX(Timestamp)
													FOR MachineCode in (' + @cols1 + ')
												) A '

									SET @TableQuery =@TableQuery + @sqlend
									--PRINT @TableQuery
									SET @SqlStart=''
									SET @ID1=@ID1+1
				
							IF(@JoinQuery='')
								BEGIN
									SET @ParentTable='#' + @TableName
									SET @JoinQuery=' SELECT DISTINCT * FROM #' + @TableName
								END
							ELSE
								BEGIN
									 SET @JoinQuery= @JoinQuery +' LEFT OUTER JOIN #' + @TableName + ' ON ' + @ParentTable +'.PROFITCENTERCODE=#'+ @TableName +'.PROFITCENTERCODE AND ' + @ParentTable +'.FGBARCODE=#'+@TableName+'.FGBARCODE'
								END
							drop table #TagDetailS14
							set @query=''
						END	
			
				set @query=''
				--print @QRYPARAMETER  
				--print   @TableQuery 
				set @query = @QRYPARAMETER+  @TEMPQUERY + @TableQuery + @JoinQuery
			
				PRINT  @query;

				EXEC sp_sqlexec @query;
			END

	else if(@Condition='SERVO_PARAMETERDATAANALYSIS_STATIONWISE_RESULT')
