					SELECT @cols2 = STUFF((SELECT ',' + QUOTENAME(MachineCode) + ' AS [' + MachineName +' TimeStamp]' FROM #TagDetails8 WHERE MachineCode IN (SELECT MachineCode FROM #MachineDetails8)
															GROUP BY OperationSeqNo,MachineCode,MachineName
															ORDER BY OperationSeqNo,MachineCode,MachineName
												FOR XML PATH(''), TYPE
												).value('.', 'NVARCHAR(MAX)') 
