					JOIN SkidBarcodeInfo sbi(NOLOCK) ON sbi.pkg_ts_serial=tsc.Serial_no
            WHERE	tsc.INVOICE_NO LIKE '%' + @InvoiceNo +'%'
		END
	ELSE IF(@Condition = 'GET_SKID_DETAILS')
		BEGIN
		    SELECT ROW_NUMBER() OVER (ORDER BY SKIDBARCODE ASC) AS Sno,sbd.WH_Code,sbd.SkidBarcodeInfoID,sbd.PartBarcode,sbd.ScanTimeStamp,sbd.LocationInSkid FROM SkidBarcodeDetail sbd 
			INNER JOIN SkidBarcodeInfo sbi ON sbi.SkidBarcodeInfoID=sbd.SkidBarcodeInfoID 
			WHERE sbi.SkidBarcode=@SkidBarcode
		END
	ELSE IF(@Condition = 'GET_BOM_DETAILS')
		BEGIN
			CREATE TABLE #BOM_DETAILS
			(
			FG_PartNo			VARCHAR(50)
			,BOMPart_No			VARCHAR(50)
			,RM_Part_No			VARCHAR(50)
			,BOM_QTY			INT
			,BOM_UOM			NVARCHAR(50)
			,MAT_PROCURE_TYPE	NVARCHAR(50)
			,MAT_USE_RATION		NVARCHAR(50)
			,ALT_ITEM_GRP_CODE	NVARCHAR(50)
			)

			SELECT TOP 1 @Partno=PartNo FROM Assy_LineAssyStatus WITH (NOLOCK) WHERE Barcode=@Barcode AND ProfitCenterCode=@ProfitCentercode

			INSERT INTO #BOM_DETAILS EXECUTE Proc_BOM_Explosion @ProfitCenterCode,@PartNo,'','1','SUMMARY'

			SELECT FG_PartNo,RM_Part_No,BOM_QTY FROM #BOM_DETAILS

			--SELECT FG_PartNo,RM_Part_No,BOM_QTY FROM #BOM_DETAILS BD
			--INNER JOIN Product_Master PM WITH (NOLOCK) ON BD.RM_Part_No=PM.SEWS_PART_NO AND PM.PART_TRACE_FLAG=1

			--ADDED BY AV 20170407 TO RETURN DETALILED SUMMRY OF BOM DATA 
			SELECT bd.FG_PartNo,bd.RM_Part_No,bd.BOM_QTY, ISNULL(FGC.RM_SERIAL_NO,'')as INV_SERIAL,isnull(I.GE_NO,'') 
			AS GE_NO,ISNULL(I.GR_NO,'') AS GR_NO,ISNULL(I.INT_LOT_NO,'') AS LOT_NO FROM #BOM_DETAILS bd
			left JOIN Assy_FGChildPartConsumption fgc ON bD.FG_PartNo= FGC.FG_PART_NO AND bd.RM_Part_No=FGC.RM_PART_NO AND fgc.FG_BARCODE=@Barcode
			LEFT JOIN INV_SERIAL I ON fgc.Rm_SERIAL_NO=i.SERIAL_NO
			GROUP BY FGC.RM_SERIAL_NO,bd.FG_PartNo,bd.RM_Part_No,bd.BOM_QTY,I.GE_NO,I.GR_NO,I.INT_LOT_NO

			SELECT LineCode,STMC_PART_NO,CHILD_PART_NO,PART_TYPE,CHILD_Barcode,DateCode FROM Assy_CouplingDetails WHERE FG_Barcode=@Barcode
	END
	ELSE IF(@Condition = 'GET_DATE_RANGE_FOR_REPORTS')
	BEGIN
		SELECT @ReturnValue = Parameter_Value FROM PARAMETER_MST (Nolock) where PARAMETER_C = 'Assline' AND PARAMETER_C1 = 'Dashboad_Report' AND PARAMETER_C2 = 'Max_Date_Differece' AND wh_Code = @ProfitCenterCode
		
		IF ISNULL(@ReturnValue,0) = 0
			SET @ReturnValue = 30
		
		SET @ReturnInt = 1
	END
	ELSE IF(@Condition = 'MANUAL_BARCODE_HISTORY')
	BEGIN
		--SELECT  AMPL.ProfitCenterCode,AMPL.LineCode,AMPL.Barcode,AMPL.DateCode,AMPL.PartNo,AMPL.Timestamp,AMPD.REASON,AMPL.SerialNo 
		--FROM Assy_Manual_Printed_Barcode (nolock) AMPL
		--INNER JOIN Assy_Manual_Printed_Barcode_Dtl (nolock)AMPD ON  AMPL.datecode =AMPD.datecode AND AMPL.SerialNo BETWEEN AMPD.FromSerialNo and AMPD.ToSerialNo
		--AND AMPL.PartNo=AMPD.PartNo AND AMPL.LineCode=AMPD.LineCode AND AMPL.ProfitCenterCode=AMPD.ProfitCenterCode
		--WHERE AMPL.TimeStamp between case when (@isDateCodeFilter=1) then AMPL.TimeStamp else @FromDate end
		--							    and case when (@isDateCodeFilter=1) then AMPL.TimeStamp else @ToDate end
		--			AND AMPL.DateCode = case when @isDateCodeFilter = 1 then @DateCode else AMPL.DateCode end 
		--AND AMPL.LineCode=@LineCode AND AMPL.ProfitCenterCode=@ProfitCentercode and AMPL.PartNo like '%'+@Partno+'%'
		
		SELECT AMPD.ProfitCenterCode,AMPD.LineCode,AMPD.DateCode,AMPD.PartNo,AMPD.NoOfPrintedLbl,AMPD.FromSerialNo,
		AMPD.ToSerialNo,AMPD.UserID,AMPD.Timestamp,AMPD.Reason 
		FROM Assy_Manual_Printed_Barcode_Dtl AMPD
		WHERE AMPD.TimeStamp between case when (@isDateCodeFilter=1) then AMPD.TimeStamp else @FromDate end
								 and case when (@isDateCodeFilter=1) then AMPD.TimeStamp else @ToDate end
				 AND AMPD.DateCode = case when @isDateCodeFilter = 1 then @DateCode else AMPD.DateCode end 
		AND AMPD.LineCode=@LineCode AND AMPD.ProfitCenterCode=@ProfitCentercode and AMPD.PartNo =isNull(nullif(@Partno,''),AMPD.PartNo)
		SET @RETURNVALUE='SUCCESS'
		SET @RETURNINT=0
		RETURN
	END
	ELSE IF(@Condition = 'MANUAL_BARCODE_REPRINT_HISTORY')
	BEGIN
		SELECT ALMR.ProfitCenterCode,ALMR.LineCode,ALMR.DateCode,ALMR.Barcode,ALMR.PartNo
		,ALMR.Remarks,ALMR.CreatedBy,ALMR.CreatedOn
		FROM Assy_LineAssyManualRePrint(NOLOCK) ALMR
		WHERE ALMR.CreatedOn between case when (@isDateCodeFilter=1) then ALMR.CreatedOn else @FromDate end
								 and case when (@isDateCodeFilter=1) then ALMR.CreatedOn else @ToDate end
				 AND ALMR.DateCode = case when @isDateCodeFilter = 1 then @DateCode else ALMR.DateCode end 
		AND ALMR.LineCode=@LineCode AND ALMR.ProfitCenterCode=@ProfitCentercode AND ALMR.PartNo =isNull(nullif(@Partno,''),ALMR.PartNo)
		AND ALMR.PrintType='MBR'
		--MODIFICATION BY AV ON 20170426
		SET @RETURNVALUE='SUCCESS'
		SET @RETURNINT=0
		RETURN
	END
	ELSE IF(@Condition = 'Packaging_History')
	BEGIN
		--ADDED BY RAHUL ON 2706219 REPORTING FOR SANAND AND BAWAL PACKAGING DATA
		IF (@ProfitCentercode IN ('0060','0082')) -- BAWAL & SANAND
		BEGIN
			IF(@Type = 'LOT_MODE')
			BEGIN
			
				SELECT * INTO #SKIDBARCODEINFO_BAWAL_LOT_WISE 
				FROM SKIDBARCODEINFO(NOLOCK)
				WHERE CONVERT(DATE,SKIDBARCODEPRINTEDTIMESTAMP,111) BETWEEN  --MODIFIED BY RAHUL ON 24062019
				CASE WHEN (@ISDATECODEFILTER=1) THEN CONVERT(DATE,SKIDBARCODEPRINTEDTIMESTAMP,111) ELSE @FROMDATE END AND 
				CASE WHEN (@ISDATECODEFILTER=1) THEN CONVERT(DATE,SKIDBARCODEPRINTEDTIMESTAMP,111) ELSE @TODATE END AND 
				DATECODE = CASE WHEN @ISDATECODEFILTER = 1 THEN @DATECODE ELSE DATECODE END  
				AND WH_CODE=@PROFITCENTERCODE AND ISNULL(PKG_TS_SERIAL,'')<>'' AND ISNULL(Layers,0) = -1
				
				SELECT SBLW.SkidBarcodeInfoID, COUNT(PARSENAME(REPLACE(SBD.PartBarcode,'-','.'),2)) AS TOTAL_PASS,PARSENAME(REPLACE(SBD.PartBarcode,'-','.'),2) AS SERIAL  
				INTO #SKIDD  FROM #SKIDBARCODEINFO_BAWAL_LOT_WISE AS SBLW INNER JOIN SkidBarcodeDetail(NOLOCK) SBD ON SBLW.SkidBarcodeInfoID = SBD.SkidBarcodeInfoID
				GROUP BY SBLW.SkidBarcodeInfoID,PARSENAME(REPLACE(SBD.PartBarcode,'-','.'),2)
				
				SELECT  DISTINCT TROLLEY_SRL, COUNT(1) AS TOTAL_FAIL INTO #VM_FAIL FROM VIEWING_MACHINE (NOLOCK) WHERE TROLLEY_SRL IN (SELECT DISTINCT SERIAL FROM #SKIDD) AND STS =0 GROUP BY TROLLEY_SRL  
												
				SELECT DISTINCT(INFO.SKIDBARCODEINFOID), 
				INFO.SKIDBARCODE,
				PPD.CUSTOMER_PART_NO AS CUSTPARTNO,
				PPD.PART_NUMBER AS PARTNUMBER,
				PMST.PRODUCT_NM AS PARTDESCRIPTION,
				PPD.MODEL AS MODEL,
				PPD.CUSTOMER_CD CUSTOMERCODE,
				INFO.COUNTRYCODE,
				INFO.PKG_TS_SERIAL AS SERIALNO,
				INFO.CUST_SERIAL_NO AS CUSTSERIALNO,
				INFO.CUST_SERIAL_QTY AS CUSTSERIALQTY,
				INFO.LOTSIZE AS LOT_QTY,
				PPD.LOT_QTY AS STDPACKSIZE,
				PPD.DISPATCH_TYPE AS DISPATCH_TYPE,
				INFO.SKIDBARCODEPRINTEDTIMESTAMP AS ENT_STAMP,
				UM.USER_CODE AS USER_CODE,  
				INFO.DATECODE,
				INFO.Line_No AS LineCode,
				ISNULL(INFO.PALLET_NO,'') AS PALLET_NO
				,ISNULL(INFO.PALLETSIZE,0) AS BOXES_PER_PALLET,
				 CASE  WHEN INFO.PKG_TS_SERIAL= DETAIL.PARTBARCODE THEN 'MANUAL'
				ELSE 'PRINTSCAN' END AS SCANTYPE,
				SBLWR.SERIAL AS INCOMING_TROLLEY,
				ISNULL(SBLWR.TOTAL_PASS,0) AS TOTAL_PASS,
				ISNULL(VM.TOTAL_FAIL,0) AS TOTAL_FAIL
				FROM #SKIDBARCODEINFO_BAWAL_LOT_WISE INFO (NOLOCK)                                           
				INNER JOIN SKIDBARCODEDETAIL DETAIL (NOLOCK) ON INFO.SKIDBARCODEINFOID=DETAIL.SKIDBARCODEINFOID
				INNER JOIN PKG_PART_MAPPING PPD (NOLOCK) ON INFO.PARTCUSTMAPID=PPD.PKG_DEF_ID
				INNER JOIN PRODUCT_MASTER PMST (NOLOCK) ON PPD.PART_NUMBER = PMST.SEWS_PART_NO AND PPD.WH_CODE = @PROFITCENTERCODE
				INNER JOIN TL_MF_SEC_USER_MST(NOLOCK) UM ON UM.USER_ID = INFO.USERID
				INNER JOIN #SKIDD SBLWR (NOLOCK) ON SBLWR.SkidBarcodeInfoID =  INFO.SkidBarcodeInfoID
				LEFT OUTER JOIN #VM_FAIL  VM (NOLOCK) ON SBLWR.SERIAL LIKE '%' + VM.TROLLEY_SRL + '%' 
				AND PMST.WAREHOUSE_CD = @PROFITCENTERCODE
				ORDER BY INFO.SKIDBARCODEINFOID
			END
			ELSE IF (@Type = 'SINGLE_SCAN_MODE')
			BEGIN
				SELECT * INTO #SKIDBARCODEINFO_BAWAL_PART_WISE 
				FROM SKIDBARCODEINFO(NOLOCK)
				WHERE CONVERT(DATE,SKIDBARCODEPRINTEDTIMESTAMP,111) BETWEEN  --MODIFIED BY RAHUL ON 24062019
				CASE WHEN (@ISDATECODEFILTER=1) THEN CONVERT(DATE,SKIDBARCODEPRINTEDTIMESTAMP,111) ELSE @FROMDATE END AND 
				CASE WHEN (@ISDATECODEFILTER=1) THEN CONVERT(DATE,SKIDBARCODEPRINTEDTIMESTAMP,111) ELSE @TODATE END AND 
				DATECODE = CASE WHEN @ISDATECODEFILTER = 1 THEN @DATECODE ELSE DATECODE END  
				AND WH_CODE=@PROFITCENTERCODE AND ISNULL(PKG_TS_SERIAL,'')<>'' AND ISNULL(Layers,0) <> -1
				
				SELECT DISTINCT(INFO.SKIDBARCODEINFOID),
				INFO.SKIDBARCODE,
				PPD.CUSTOMER_PART_NO AS CUSTPARTNO,
				PPD.PART_NUMBER AS PARTNUMBER,
				PMST.PRODUCT_NM AS PARTDESCRIPTION,
				PPD.MODEL AS MODEL,
				PPD.CUSTOMER_CD CUSTOMERCODE,
				INFO.COUNTRYCODE,
				INFO.PKG_TS_SERIAL AS SERIALNO,
				INFO.CUST_SERIAL_NO AS CUSTSERIALNO,
				INFO.CUST_SERIAL_QTY AS CUSTSERIALQTY,
				INFO.LOTSIZE AS LOT_QTY,
				PPD.LOT_QTY AS STDPACKSIZE,
				PPD.DISPATCH_TYPE AS DISPATCH_TYPE,
				INFO.SKIDBARCODEPRINTEDTIMESTAMP AS ENT_STAMP,
				UM.USER_CODE AS USER_CODE, 
				INFO.DATECODE,
				INFO.Line_No AS LineCode,
				ISNULL(INFO.PALLET_NO,'') AS PALLET_NO
				,ISNULL(INFO.PALLETSIZE,0) AS BOXES_PER_PALLET,
				 CASE  WHEN INFO.PKG_TS_SERIAL= DETAIL.PARTBARCODE THEN 'MANUAL'
				ELSE 'PRINTSCAN' END AS SCANTYPE,
				VM.TROLLEY_SRL AS INCOMING_TROLLEY,
				CASE WHEN VM.STS = 1 THEN VM.DYNAMIC_BARCODE ELSE VM.BARCODE END AS BARCODE,
				CASE WHEN VM.STS = 1 THEN 'PASS' ELSE 'FAIL'END AS RESULT INTO #RESULT_TABLE
				FROM #SKIDBARCODEINFO_BAWAL_PART_WISE INFO (NOLOCK)                                           
				INNER JOIN SKIDBARCODEDETAIL DETAIL (NOLOCK) ON INFO.SKIDBARCODEINFOID=DETAIL.SKIDBARCODEINFOID
				INNER JOIN PKG_PART_MAPPING PPD (NOLOCK) ON INFO.PARTCUSTMAPID=PPD.PKG_DEF_ID
				INNER JOIN PRODUCT_MASTER PMST (NOLOCK) ON PPD.PART_NUMBER = PMST.SEWS_PART_NO AND PPD.WH_CODE = @PROFITCENTERCODE
				INNER JOIN TL_MF_SEC_USER_MST(NOLOCK) UM ON UM.USER_ID = INFO.USERID
				INNER JOIN VIEWING_MACHINE VM (NOLOCK) ON DETAIL.PARTBARCODE = VM.DYNAMIC_BARCODE  
				AND PMST.WAREHOUSE_CD = @PROFITCENTERCODE
				ORDER BY INFO.SKIDBARCODEINFOID
								
				IF EXISTS (SELECT TOP 1 1 FROM #RESULT_TABLE)
				BEGIN
					DECLARE @USERCODE VARCHAR(50) = ''
					SELECT TOP 1 @USERCODE = USER_CODE FROM #RESULT_TABLE 
					insert into #RESULT_TABLE (SKIDBARCODEINFOID,PARTNUMBER,SCANTYPE,INCOMING_TROLLEY,BARCODE,RESULT,CUSTPARTNO,PARTDESCRIPTION,DISPATCH_TYPE,PALLET_NO,BOXES_PER_PALLET,DATECODE,ENT_STAMP,USER_CODE)
					select '0000', VW_PARTNO,'PRINTSCAN',TROLLEY_SRL,BARCODE,'FAIL','FAILCUSTPART','FAILPARTDESC','FAILDISPATCH','FAILPALLET','0',DATE_CODE,ENT_STAMP,@USERCODE
					from VIEWING_MACHINE (nolock) where TROLLEY_SRL in (select distinct INCOMING_TROLLEY  from #RESULT_TABLE)
					and WH_CODE = @ProfitCentercode and STS = 0
				END
				
				SELECT * FROM #RESULT_TABLE ORDER BY SKIDBARCODEINFOID DESC
			END
		END
		ELSE
		BEGIN
			SELECT * INTO #SkidBarcodeInfo 
			FROM SkidBarcodeInfo(nolock)
			WHERE SkidBarcodePrintedTimestamp between 
			case when (@isDateCodeFilter=1) then SkidBarcodePrintedTimestamp else @FromDate end and 
			case when (@isDateCodeFilter=1) then SkidBarcodePrintedTimestamp else @ToDate end AND 
			DATECODE = case when @isDateCodeFilter = 1 then @DateCode else DATECODE end  
			AND WH_CODE=@ProfitCentercode and isnull(pkg_ts_serial,'')<>''
	
			SELECT DISTINCT(Info.SkidBarcodeInfoID),
			info.SkidBarcode,
			PPD.CUSTOMER_PART_NO as CustPartNo,
			PPD.PART_NUMBER as PartNumber,
			pmst.product_nm as PartDescription,
			PPD.MODEL as MODEL,
			PPD.CUSTOMER_CD CustomerCode,
			Info.CountryCode,
			INFO.pkg_ts_serial As SerialNo,
			Info.CUST_SERIAL_NO AS CustSerialNo,
			Info.CUST_SERIAL_QTY As CustSerialQty,
			info.LotSize as Lot_Qty,
			PPD.LOT_QTY as StdPackSize,
			PPD.DISPATCH_TYPE as DISPATCH_TYPE,
			Info.SkidBarcodePrintedTimestamp AS ENT_STAMP,
			Info.USERID,
			Info.DateCode,
			INFO.Line_No AS LineCode,
			isnull(Info.Pallet_No,'') As Pallet_No
			,isnull(Info.PalletSize,0) as BOXES_PER_PALLET,
			 case  when info.pkg_ts_serial= detail.PartBarcode then 'MANUAL'
			else 'PrintScan' end AS ScanType 
			FROM #SkidBarcodeInfo info (NOLOCK)                                         
			INNER JOIN SkidBarcodeDetail detail (NOLOCK) ON info.SkidBarcodeInfoID=detail.SkidBarcodeInfoID
			INNER JOIN PKG_PART_MAPPING PPD (NOLOCK) ON info.PartCustMapID=PPD.PKG_DEF_ID
			INNER JOIN PRODUCT_MASTER pmst (NOLOCK) ON PPD.PART_NUMBER = pmst.sews_part_no AND PPD.WH_CODE = @ProfitCentercode
			AND pmst.warehouse_cd = @ProfitCentercode
			ORDER BY info.SkidBarcodeInfoID
		END

		SET @RETURNVALUE='SUCCESS'
		SET @RETURNINT=0
		RETURN

	END
	ELSE IF(@Condition = 'Packaging_Details')
	BEGIN
		SELECT WH_CODE,SkidBarcodeInfoID ,PartBarcode,ScanTimeStamp,LocationInSkid,Layer,Line_No,UserId,StationCode 
		FROM SkidBarcodeDetail(nolock) where SkidBarcodeInfoID=@SkidBarcode and WH_CODE=@ProfitCentercode
		Order By LocationInSkid

		SET @RETURNVALUE='SUCCESS'
		SET @RETURNINT=0
		RETURN
	END
	ELSE IF(@Condition = 'Hold_Unhold')
	BEGIN
		--SELECT * INTO #Hold_Unhold 
		--FROM TRANS_LOG(nolock) 
		--WHERE WH_CODE=@ProfitCentercode AND PROGRAM_ID='HOLD-UNHOLD' AND ENT_STAMP BETWEEN @FromDate AND @ToDate
		
		--SELECT  HU.WH_CODE , HU.Serial_No,HU.SERIAL_QTY,P.SEWS_PART_NO ,HU.ORDER_NO AS [STATUS],
		--HU.ENT_STAMP AS [DATE], HU.ENT_BY AS [USER]
		--FROM #Hold_Unhold HU
		--INNER JOIN PRODUCT_MASTER(nolock) P ON HU.ITEM_NO = P.ITEM_NO and HU.WH_CODE=P.warehouse_cd
		--WHERE P.warehouse_cd=@ProfitCentercode and P.SEWS_PART_NO like '%'+@Partno +'%'
		--ORDER BY HU.SERIAL_NO,HU.ENT_STAMP
		SELECT ProfitCenterCode,SerialNo,PartNo,Qty,SkidLocation,UserId,EntTimeStamp,Remark,IsMailTimeStamp,CASE WHEN IsHold=0 THEN 'UnHold' ELSE 'Hold' End HoldDetails   
		FROM Skid_Hold_UnHold_Mail 
		WHERE ProfitCenterCode = @ProfitCentercode and EntTimeStamp BETWEEN @FromDate AND @ToDate
		ORDER BY EntTimeStamp Desc

		
		SET @RETURNVALUE='SUCCESS'
		SET @RETURNINT=0
		RETURN
	END

	IF EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID('Temp_Tags_Assy_Proc_Traceability_Analysis') AND type in (N'U'))
	BEGIN
		DROP TABLE Temp_Tags_Assy_Proc_Traceability_Analysis
	END
	END TRY
	 BEGIN catch
		SET @ReturnValue =	CAST(ERROR_NUMBER() as varchar(5)) + '|' + 
			CAST(ERROR_SEVERITY()as varchar(5)) + '|' + 
			CAST(ERROR_STATE() as varchar(5)) + '|' + 
			CAST(ERROR_PROCEDURE() as varchar(200)) + '|' + 
			CAST(ERROR_LINE() as varchar(5)) + '|' + 
			CAST(ERROR_MESSAGE() as varchar(1500))
			RAISERROR (@ReturnValue,16,1)						
		   SET @ReturnInt = 2
	END CATCH
END

















