CREATE PROCEDURE [dbo].[Assy_Proc_Traceability_Analysis_BK]
	(
	@ProfitCentercode	varchar(10)=null,
	@LineCode	varchar(10)=null,
	@LineName	varchar(30)=null,
	@FinalViewingCode varchar(30)=null,
	@FromDate varchar(20)='',
	@ToDate varchar(20)='',
	@MachineCode	varchar(200)=null,
	@MachineName	varchar(100)=null,
	@TagName	varchar(50)=null,
	@OperationCode varchar(50)=null,
	@OperationSeqno	tinyint=null,
	@ActiveStatus	bit=0,
	@isTmcLine	bit=0,
	@DateCode varchar(10)='',
	@Date date=null,
	@Partno varchar(15)='',
	@SerialNo varchar(15)='',
	@Shift varchar(15)='',
	@Barcode varchar(100)='',
	@SkidBarcode varchar(100)='',
	@Column varchar(Max)='',
	@Qry varchar(MAX)='',
	@FromTimeStamp varchar(30)='',
	@ToTimeStamp varchar(30)='',
	@Created_By	varchar(50)=null,
	@Updated_By	varchar(50)=null,
	@Condition VARCHAR(100)=NULL,
	@IsTagsReset VARCHAR(10)='1',
	@ReturnValue VARCHAR (2000)=NULL OUT,
	@ReturnInt INT=NULL OUT,

	@datetime1 varchar(20)='',
	@Minutes int=60,
	@ConditionalTime datetime=null,
	@ConditionalTime1 datetime=null,

	@COUNT	INT =0,
	@ID1 INT =1,
	@cols2	VARCHAR(MAX)='',
	@cols3	VARCHAR(MAX)='',
	@cols1	VARCHAR(MAX)='',
	@query  VARCHAR(MAX)='',
	@query1  VARCHAR(MAX)='',
	@tables VARCHAR(MAX)='',
	
	@InvoiceNo varchar(50)=null,
	@TableName nvarchar(50)='',
	@id3 int='',
	@JoinQuery varchar(max)='',
	@ParentTable varchar(max)='',
	@SqlStart varchar(max)='',
	@TableQuery varchar(max)='',
	@SqlEnd varchar(max)='',
	@TempQuery varchar(max)='',
	@sql varchar(max)='',
	@qryparameter varchar(max)='',
	@isDateCodeFilter bit=1 
	)
AS
BEGIN
-- =============================================
-- Author:		SUNDARA MOORTHI S	
-- Create date: 27-02-2016
-- Description:	Traceability analysis report settings and get details from this proc

-- Modified By : Sundaramoorthi S
-- Modified Date: 09-06-2016
-- Description : For production data get from local server. Previously it was in configured to central server but not released.
-- =============================================
	set nocount on;
	 begin try

	-- SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
	 ------------------------------------------------------------------------------Start of Tags setting queries---------------------------------------------------------

	 --Get_Part_Numbers
	  if(object_id('tempdb..#tbPartNumbers') is not null)
						drop table #tbPartNumbers

	DECLARE @SERVOPARAMDATA1  AS TABLE (
			ProfitCenterCode	NVARCHAR(10)
			,LineCode		NVARCHAR(10)
			,DateCode		NVARCHAR(10)
			,MachineName		NVARCHAR(50)
			,MachineCode		NVARCHAR(10)
			,PartNo			NVARCHAR(10)
			,FGBarcode			NVARCHAR(100)
			,TagName			NVARCHAR(50)
			,Value				NVARCHAR(50)
			,Result				NVARCHAR(20)
			,Timestamp			DATETIME
			,OperationSeqNo		INT
			,ServoBarcode		NVARCHAR(100)
			,TMCBarcode			NVARCHAR(100)
			)
	/*
	 Save required tagnames in Assy_TraceabilityAnalysis_Tags.
	 */
		IF EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID('Temp_Tags_Assy_Proc_Traceability_Analysis') AND type in (N'U'))
		BEGIN
			DROP TABLE Temp_Tags_Assy_Proc_Traceability_Analysis
		END
		Create Table Temp_Tags_Assy_Proc_Traceability_Analysis(TagName varchar(50))
		IF(@ProfitCenterCode='0088')
		BEGIN
			INSERT INTO Temp_Tags_Assy_Proc_Traceability_Analysis(TagName)
			select TagName
			from Assy_ReportAnalysis_Tags (nolock) where LineCode=ISNULL(@LineCode,LineCode) AND ProfitCentercode=@ProfitCenterCode  and activestatus=1
		END
		ELSE 
		BEGIN
			INSERT INTO Temp_Tags_Assy_Proc_Traceability_Analysis(TagName)
			select case when tagname='' then MachineCode + ' Barcode' else tagname end
			from Assy_TraceabilityAnalysis_Tags (nolock) where LineCode=ISNULL(@LineCode,LineCode) AND ProfitCentercode=@ProfitCenterCode  and activestatus=1
		END
	IF(@condition='SAVE')
			BEGIN
				IF @IsTagsReset='1'
					BEGIN
						TRUNCATE TABLE Assy_TraceabilityAnalysis_Tags
						
						INSERT INTO Assy_TraceabilityAnalysis_Tags
						(
						ProfitCentercode
						,LineCode
						,MachineCode
						,TagName
						,OperationSeqno
						,ActiveStatus
						,Created_By
						,Created_Datetime
						)
						SELECT 
						DISTINCT avpd.ProfitCenterCode
						,avpd.LineCode
						,avpd.MachineCode
						,avpd.TagName
						,0
						,1
						,''
						,GETDATE()
						FROM Assy_View_ParamData(NOLOCK) avpd
						WHERE --avpd.DateCode=@DateCode AND 
							avpd.LineCode=@LineCode
							AND avpd.ProfitCenterCode=@ProfitCenterCode
						 GROUP BY avpd.TagName,avpd.MachineCode,avpd.LineCode,avpd.ProfitCenterCode
					END
			ELSE IF @IsTagsReset='2'
				BEGIN
					SET @LineCode=@LineName
					--IF EXISTS(SELECT * FROM Assy_TraceabilityAnalysis_Tags(NOLOCK) 
					--			WHERE ProfitCentercode=@ProfitCentercode 
					--				AND LineCode=@LineCode 
					--				AND MachineCode=@MachineCode 
					--				AND TagName=@TagName)
					--	BEGIN
							--DELETE FROM Assy_TraceabilityAnalysis_Tags
							--WHERE ProfitCentercode=@ProfitCentercode
							--	AND LineCode=@LineCode
							--	AND TagName=@TagName
						
							--INSERT INTO Assy_TraceabilityAnalysis_Tags
							--(
							--ProfitCentercode
							--,LineCode
							--,MachineCode
							--,TagName
							--,OperationSeqno
							--,ActiveStatus
							--,Created_By
							--,Created_Datetime
							--)
							--VALUES
							--(
							--@ProfitCentercode
							--,@LineCode
							--,@MachineCode
							--,@TagName
							--,@OperationSeqno
							--,@ActiveStatus
							--,@Created_By
							--,GETDATE()
							--)
							
							UPDATE Assy_TraceabilityAnalysis_Tags SET 
							ActiveStatus=@ActiveStatus
							WHERE ProfitCentercode=@ProfitCentercode
								AND LineCode=@LineCode
								AND TagName=@TagName
							SET @ReturnValue='SUCCESS'
							SET @ReturnInt=0
							RETURN
						END
					--else
					--	begin
					--		insert into Assy_TraceabilityAnalysis_Tags
					--		(
					--		ProfitCentercode
					--		,LineCode
					--		,MachineCode
					--		,TagName
					--		,OperationSeqno
					--		,ActiveStatus
					--		,Created_By
					--		,Created_Datetime
					--		)
					--		values
					--		(
					--		@ProfitCentercode
					--		,@LineCode
					--		,@MachineCode
					--		,@TagName
					--		,@OperationSeqno
					--		,@ActiveStatus
					--		,@Created_By
					--		,getdate()
					--		)
					--		set @ReturnValue='SUCCESS'
					--		set @ReturnInt=0
					--		return
					--	end
		end
			--
			--Select tag names details from Assy_View_ParamData,machinemst,Assy_TraceabilityAnalysis_Tags
			--
	else if(@Condition='SELECT_REQUIRE_FIELDS')
			BEGIN
				--AV ON 20170621 TO ADD FROM DATE AND TO DATE FILTER 
				SELECT DISTINCT  avpd.MachineCode,mm.MachineName,avpd.LineCode,avpd.TagName,isnull(atat.OperationSeqno,'') as OperationSeqNo,0 as ActiveStatus 
				FROM Assy_View_ParamData(nolock) avpd
				LEFT JOIN Assy_TraceabilityAnalysis_Tags(nolock) atat on atat.MachineCode=avpd.MachineCode
				JOIN MachineMst mm(nolock) on mm.MachineCode=avpd.MachineCode
				WHERE avpd.Timestamp BETWEEN CASE WHEN (@isDateCodeFilter=1) THEN avpd.Timestamp ELSE @FromDate END
				AND CASE WHEN (@isDateCodeFilter=1) THEN avpd.Timestamp ELSE  @ToDate END
				AND avpd.DateCode = case when @isDateCodeFilter = 1 THEN @DateCode ELSE avpd.DateCode END
				AND avpd.LineCode=@LineCode
				AND avpd.ProfitCenterCode=@ProfitCenterCode
				GROUP BY avpd.TagName,avpd.MachineCode,mm.MachineName,atat.OperationSeqno,avpd.LineCode 

				set @ReturnValue='SUCCESS'
				set @ReturnInt=0
				return
			end
		--
		--Select line name details from linemst table
		--
	ELSE IF(@Condition='SELECT_LINE_DETAILS')
			BEGIN
				SELECT LineCode,LineName FROM linemst(NOLOCK)
				WHERE ProfitCenterCode=@ProfitCentercode 
					AND LineTypeCode IN ('LTTMC','LTSTMC','LTCALIPER') 
					AND isActive=1
					AND ProfitCenterCode=@ProfitCentercode
				SET @ReturnValue='SUCCESS'
				SET @ReturnInt=0
				RETURN
			END

	else if(@Condition='GET_TAG_STATUS')
			begin
			set @LineCode=@LineName
				select ActiveStatus from Assy_TraceabilityAnalysis_Tags(nolock)
				where LineCode=@LineCode
					and ProfitCenterCode=@ProfitCentercode
					and MachineCode=@MachineCode
					and TagName=@TagName
					--order by rclw.operationSeqNo asc  --if we need only currently active stations put on this condition  ****and rclw.Traceability=1 ****
				set @ReturnValue='SUCCESS'
				set @ReturnInt=0
				return
			end

		--
		------------------------------------------------------------------------------End of Tags setting---------------------------------------------------------
		--

		--
		------------------------------------------------------------------------------Starts Traceability Analysis---------------------------------------------------------
		--
	else if(@Condition='GET_PART_NUMBERS')
			begin
				select distinct isnull(partno,'') as partno 
					 into #tbPartNumbers from Assy_LineAssyStatus(nolock)  
						where isnull(DateCode,'')=@DateCode
							and isnull(linecode,'')=@LineCode 
							and isnull(profitcentercode,'')=@ProfitCentercode

				insert into #tbPartNumbers select distinct isnull(partno,'') as partno 
					from Assy_LineAssyStatus_Running(nolock)  
						where isnull(DateCode,'')=@DateCode
							and isnull(linecode,'')=@LineCode 
							and isnull(profitcentercode,'')=@ProfitCentercode

				select distinct(PartNo) as Partno from #tbPartNumbers

				set @ReturnValue='SUCCESS'
				set @ReturnInt=0
				return
			end
	else if(@Condition='SELECT_STATION_NAMES')
			begin
				--select distinct mm.MachineName,mm.MachineCode from  MachineMst mm (nolock)
				--	join Assy_TraceabilityAnalysis_Tags(nolock) atat on atat.MachineCode=mm.MachineCode
				--	and atat.ActiveStatus=1
				--where atat.LineCode=@LineCode
				--	and mm.ProfitCenterCode=@ProfitCentercode
				--	and mm.MachineCode in (select MachineCode from Assy_View_ParamData(nolock) where DateCode=@DateCode)
				--order by mm.MachineName,mm.MachineCode

				SELECT DISTINCT mm.MachineName,mm.MachineCode, rclw.OperationSeqNo FROM  MachineMst mm (NOLOCK)
				JOIN Assy_TraceabilityAnalysis_Tags(NOLOCK) atat ON atat.MachineCode=mm.MachineCode AND atat.ActiveStatus=1
				JOIN RoutingConfigLineWise(NOLOCK) rclw ON rclw.MachineCode=mm.MachineCode
				INNER JOIN Assy_View_ParamData(NOLOCK) AVY ON  MM.MachineCode=AVY.MachineCode
				AND AVY.Timestamp BETWEEN CASE WHEN (@isDateCodeFilter=1) THEN AVY.Timestamp ELSE @FromDate END
										AND CASE WHEN (@isDateCodeFilter=1) THEN AVY.Timestamp ELSE  @ToDate END
				AND AVY.DateCode = case when @isDateCodeFilter = 1 THEN @DateCode ELSE AVY.DateCode END
				WHERE atat.LineCode=@LineCode
				AND mm.ProfitCenterCode=@ProfitCentercode
				AND AVY.Timestamp BETWEEN CASE WHEN (@isDateCodeFilter=1) THEN AVY.Timestamp ELSE @FromDate END
										AND CASE WHEN (@isDateCodeFilter=1) THEN AVY.Timestamp ELSE  @ToDate END
				AND AVY.DateCode = case when @isDateCodeFilter = 1 THEN @DateCode ELSE AVY.DateCode END
				--AND mm.MachineCode in (SELECT MachineCode FROM Assy_View_ParamData(NOLOCK) WHERE DateCode=@DateCode)
				ORDER by rclw.OperationSeqNo, mm.MachineName,mm.MachineCode

				set @ReturnValue='SUCCESS'
				set @ReturnInt=0
				return
			end
	else if(@Condition='SELECT_LINE_NAMES')
			begin
				select LineCode,LineName from LineMst (nolock)
					where LineTypeCode in('LTTMC','LTSTMC','LTCALIPER') -- added by sachin 20170405
						and Isactive=1 
						and ProfitCenterCode=@ProfitCenterCode

				set @ReturnValue='SUCCESS'
				set @ReturnInt=0
				return
			end
	else if(@Condition='GET_REPORT_HOURLY_PRODUCTION')
			begin
				declare @c varchar(20);
				declare @Datetime datetime;
				declare @StartTime time;
				declare @EndTime time;
				declare @EndTime1 varchar(19);
				declare @Id int =1;
				create table #tb_Hourly_Report
					(id int,
					ProfitcenterCode varchar(50),
					LineCode varchar(50),
					Date Date,
					DateCode varchar(50),
					Partno varchar(50),
					Pass int,
					Fail int,
					ProductionHour varchar(50))

				EXEC @MachineCode=[dbo].Assy_FN_Get_FinalViewing_MachineCode_From_LineCode @PROFITCENTERCODE=@PROFITCENTERCODE,@LineCode=@LineCode

				create table #timetable
								(Production_Date date,
								 FromTime Time,
								 ToTime Time
								 )

					insert into #timetable 
						EXEC ASSY_PROC_GETDATE_FROMDATECODE @DATECODE=@DateCode,@PROFITCENTERCODE=@ProfitCenterCode
					set @Date=(select Production_Date from #timetable)
					set @StartTime=(select FromTime from #timetable)
					set @EndTime=(select ToTime from #timetable)


					set @c=convert(nvarchar(10),@Date) + ' ' +  convert(nvarchar(10),@StartTime,108)
					select @ConditionalTime= Convert(datetime,@c,121)
					set @ConditionalTime1=dateadd(mi,@Minutes,@ConditionalTime)
					set @EndTime=dateadd(MI,0,@EndTime)
					if (CHARINDEX('00',CAST(@ENDTIME AS VARCHAR)))<2
						BEGIN
							set @EndTime1=cast(DATEADD(DD,1,cast(@ConditionalTime1 as date)) as varchar) + ' ' + cast(@EndTime as varchar)
						END
					else
						begin
							set @EndTime1=cast(DATEADD(DD,0,cast(@ConditionalTime1 as date)) as varchar) + ' ' + cast(@EndTime as varchar)
						end


				--while(CAST(CONVERT(TIME,@ConditionalTime1) AS VARCHAR)<=CAST(@EndTime AS VARCHAR))
				while((DATEDIFF(MI,CAST(@ConditionalTime1 AS VARCHAR),@EndTime1)+50)>0)
					begin
					--print DATEDIFF(MI,CAST(@ConditionalTime1 AS VARCHAR),@EndTime1)
						if exists(select @Id,isnull(alas.ProfitCenterCode,''),isnull(alas.LineCode,''),@Date,isnull(alas.DateCode,''),isnull(alas.Partno,''), 
									isnull(sum(case when alas.status='PS' then 1 else 0 end),0) as Pass, 
									isnull(sum(case when alas.status='FL' then 1 else 0 end),0) as Fail,
									(substring(convert(varchar,@ConditionalTime),13,5) + ' - ' + substring(convert(varchar,@ConditionalTime1),13,5)) as Hr
									from assy_lineassystatus alas (nolock)
									where alas.datecode=@DateCode 
										and alas.MachineCode=@MachineCode
										and isnull(cast(ResultTimestamp as datetime),'')>=isnull(cast(@ConditionalTime as datetime),'')
										and isnull(cast(ResultTimestamp as datetime),'')<=isnull(cast(@ConditionalTime1 as datetime),'')
									group by alas.ProfitCenterCode,alas.LineCode,alas.DateCode,alas.Partno)
								begin
									insert into #tb_Hourly_Report
									select @Id,isnull(alas.ProfitCenterCode,''),isnull(alas.LineCode,''),@Date,isnull(alas.DateCode,''),isnull(alas.Partno,''), 
									isnull(sum(case when alas.status='PS' then 1 else 0 end),0) as Pass, 
									isnull(sum(case when alas.status='FL' then 1 else 0 end),0) as Fail,
									(substring(convert(varchar,cast(@ConditionalTime as time)),1,5) + ' - ' + substring(convert(varchar,cast(@ConditionalTime1 as time)),1,5)) as Hr
									from assy_lineassystatus alas (nolock)
									where alas.datecode=@DateCode 
										and alas.MachineCode=@MachineCode
										and isnull(cast(ResultTimestamp as datetime),'')>=isnull(cast(@ConditionalTime as datetime),'')
										and isnull(cast(ResultTimestamp as datetime),'')<=isnull(cast(@ConditionalTime1 as datetime),'')
									group by alas.ProfitCenterCode,alas.LineCode,alas.DateCode,alas.Partno
								end
						else
							begin
							--print DATEDIFF(MI,CAST(@ConditionalTime1 AS VARCHAR),@EndTime1)
								insert into #tb_Hourly_Report
								values(@Id,@ProfitCenterCode,@LineCode,@Date,@DateCode,(SELECT TOP 1 ISNULL(PARTNO,'Null') 
								FROM #tb_Hourly_Report 
								ORDER BY ProductionHour DESC),0,0,(substring(convert(varchar,cast(@ConditionalTime as time)),1,5) + ' - ' + substring(convert(varchar,cast(@ConditionalTime1 as time)),1,5)))
							end
								set @ConditionalTime=@ConditionalTime1
								set @ConditionalTime1=dateadd(mi,@Minutes,@ConditionalTime1)
								set @Id=@Id+1
					end
					--print DATEDIFF(MI,CAST(@ConditionalTime1 AS VARCHAR),@EndTime1)
							select ProfitcenterCode,LineCode,Date,DateCode,Partno,Pass,Fail,ProductionHour from #tb_Hourly_Report
							drop table #tb_Hourly_Report
							drop table #timetable
						set @ReturnValue='SUCCESS'
						set @ReturnInt=0
						return
	end
	else if(@Condition='GET_PRODUCTION_DATA')
		begin
				SELECT @FinalViewingCode = dbo.Assy_FN_Get_FinalViewing_MachineCode_From_LineCode(@ProfitCenterCode,@LineCode)

				SET @QRY='SELECT CAST(A.ScanTimestamp AS DATE) ScanDate, L.LineName, A.Datecode, A.PartNo, Case A.Status WHEN ''PS'' THEN ''Pass'' WHEN ''FL'' THEN ''Fail'' ELSE A.Status END FV_Status, COUNT(Barcode) Qty
							FROM Assy_LineAssyStatus A WITH (NOLOCK)
								INNER JOIN LineMst L WITH (NOLOCK)
									ON L.ProfitCenterCode = A.ProfitCenterCode AND L.LineCode = A.LineCode
											WHERE A.ProfitCenterCode =''' + @ProfitCenterCode +'''AND A.LineCode ='''+ @LineCode 
												+'''AND A.MachineCode =''' + @FinalViewingCode+ ''''
											if(@FromDate<>'' and @ToDate<>'')
												begin											
													set @qry=@qry + '  And convert(Date,A.ScanTimestamp)>=convert(Date,''' + @FromDate +''',105) 
																AND convert(Date,A.ScanTimestamp)<=Convert(Date,''' + @ToDate +''',105)'										
												end
											if(@PartNo<>'')
												begin
													set @qry=@qry + ' And A.PartNo=''' + @PartNo +''''
												end
											if(@DateCode<>'')
												begin
													set @qry=@qry + ' And A.DateCode=''' + @DateCode +''''
												end
				set @Qry=@qry + ' Group By CAST(A.ScanTimestamp AS DATE), L.LineName, A.Datecode, A.PartNo, A.Status
											Order By 1,3,4,6'
				Execute sp_sqlexec @qry

			set @ReturnValue='SUCCESS'
			set @ReturnInt=0
			return
		end
	else if(@Condition='GET_PRODUCTION_PARTNO')
		begin
				SELECT Distinct A.PartNo FROM Assy_LineAssyStatus A WITH (NOLOCK)
				WHERE	A.ScanTimestamp between case when (@isDateCodeFilter=1) then  A.ScanTimestamp else @FromDate end
									 and case when (@isDateCodeFilter=1) then A.ScanTimestamp else  @ToDate end
						AND A.DateCode = case when @isDateCodeFilter = 1 then @DateCode else A.DateCode end
						AND A.LineCode = @LineCode
						AND A.ProfitCenterCode = @ProfitCenterCode
						AND ISNULL(A.Status,'') != ''
						Group By CAST(A.ScanTimestamp AS DATE), A.LineCode, A.Datecode, A.PartNo, A.Status
												Order By 1
				set @ReturnValue='SUCCESS'
				set @ReturnInt=0
				return
		end
	else if(@Condition='GET_SUMMARY_SCANNED_BARCODE')
		begin
				SELECT @FinalViewingCode = dbo.Assy_FN_Get_FinalViewing_MachineCode_From_LineCode(@ProfitCenterCode,@LineCode)
				SET @QRY='SELECT CAST(A.ScanTimestamp AS DATE) ScanDate, L.LineName, A.Datecode, A.PartNo, Case A.Status 
							WHEN ''PS'' THEN ''Pass'' WHEN ''FL'' THEN ''Fail'' ELSE ''OnlyScanned'' END FV_Status, COUNT(Barcode) Qty
								FROM Assy_LineAssyStatus A WITH (NOLOCK)
									INNER JOIN LineMst L WITH (NOLOCK)
										ON L.ProfitCenterCode = A.ProfitCenterCode AND L.LineCode = A.LineCode
											WHERE A.ProfitCenterCode =''' + @ProfitCenterCode +'''AND A.LineCode ='''+ @LineCode 
												+'''AND A.MachineCode =''' + @FinalViewingCode+ ''''
											if(@FromDate<>'' and @ToDate<>'')
												begin											
													set @qry=@qry + '  And convert(Date,A.ScanTimestamp)>=convert(Date,''' + @FromDate +''',105) 
																AND convert(Date,A.ScanTimestamp)<=Convert(Date,''' + @ToDate +''',105)'										
												end
											if(@PartNo<>'')
												begin
													set @qry=@qry + ' And A.PartNo=''' + @PartNo +''''
												end
											if(@DateCode<>'')
												begin
													set @qry=@qry + ' And A.DateCode=''' + @DateCode +''''
												end
				set @Qry=@qry + ' Group By CAST(A.ScanTimestamp AS DATE), L.LineName, A.Datecode, A.PartNo, A.Status
									Order By 1,3,4,6'
				Execute sp_sqlexec @qry

				set @ReturnValue='SUCCESS'
				set @ReturnInt=0
				return
			end
	else if(@Condition='PRODUCTIONDATASUMMARY_FAILBUTNOTPROCESSED')
			begin
				SELECT @FinalViewingCode = dbo.Assy_FN_Get_FinalViewing_MachineCode_From_LineCode(@ProfitCenterCode,@LineCode)
				SET @QRY='SELECT CAST(A.ScanTimestamp AS DATE) ScanDate, L.LineName, A.Datecode, A.PartNo, A.Barcode, M.MachineCode, M.MachineName, Case A.Status WHEN ''PS'' THEN ''Pass'' WHEN ''FL'' THEN ''Fail'' ELSE ''OnlyScanned'' END Barcode_Status, A.FailCount
 




				FROM Assy_LineAssyStatus A WITH (NOLOCK)
								INNER JOIN LineMst L WITH (NOLOCK)
									ON L.ProfitCenterCode = A.ProfitCenterCode AND L.LineCode = A.LineCode
										INNER JOIN MachineMst M WITH (NOLOCK)
											ON M.ProfitCenterCode = A.ProfitCenterCode AND M.MachineCode = A.MachineCode
												WHERE A.FailCount > 0 AND ISNULL(A.Status,'''') = ''FL'' and A.ProfitCenterCode =''' + @ProfitCenterCode +'''AND A.LineCode ='''+ @LineCode 
												+'''AND A.MachineCode =''' + @FinalViewingCode+ ''''
				if(@FromDate<>'' and @ToDate<>'')
					begin											
						set @qry=@qry + '  And convert(Date,A.ScanTimestamp)>=convert(Date,''' + @FromDate +''',105) 
									AND convert(Date,A.ScanTimestamp)<=Convert(Date,''' + @ToDate +''',105)'										
					end
				if(@PartNo<>'')
					begin
						set @qry=@qry + ' And A.PartNo=''' + @PartNo +''''
					end
				if(@DateCode<>'')
					begin
						set @qry=@qry + ' And A.DateCode=''' + @DateCode +''''
					end
				set @Qry=@qry + 'Group By CAST(A.ScanTimestamp AS DATE), L.LineName, A.Datecode, A.PartNo, A.Status, A.Barcode,
															M.MachineName, M.MachineCode, A.FailCount Order By 1,3,4,6'

				Execute sp_sqlexec @qry

				set @ReturnValue='SUCCESS'
				set @ReturnInt=0
				return
			end
	else if(@Condition='PRODUCTIONDATASUMMARY_MULTIPLETIMESFAILED')
			begin
				SELECT @FinalViewingCode = dbo.Assy_FN_Get_FinalViewing_MachineCode_From_LineCode(@ProfitCenterCode,@LineCode)
				SET @QRY='SELECT CAST(A.ScanTimestamp AS DATE) ScanDate, L.LineName, A.Datecode, A.PartNo, A.Barcode, M.MachineCode, M.MachineName, Cas
e A.Status WHEN ''PS'' THEN ''Pass'' WHEN ''FL'' THEN ''Fail'' ELSE ''OnlyScanned'' END Barcode_Status, A.FailCount 
				FROM Assy_LineAssyStatus A WITH (NOLOCK)
								INNER JOIN LineMst L WITH (NOLOCK)
									ON L.ProfitCenterCode = A.ProfitCenterCode AND L.LineCode = A.LineCode
										INNER JOIN MachineMst M WITH (NOLOCK)
											ON M.ProfitCenterCode = A.ProfitCenterCode AND M.MachineCode = A.MachineCode
												WHERE A.FailCount > 0 and A.ProfitCenterCode =''' + @ProfitCenterCode +'''AND A.LineCode ='''+ @LineCode 
												+'''AND A.MachineCode =''' + @FinalViewingCode+ ''''
				if(@FromDate<>'' and @ToDate<>'')
					begin											
						set @qry=@qry + '  And convert(Date,A.ScanTimestamp)>=convert(Date,''' + @FromDate +''',105) 
									AND convert(Date,A.ScanTimestamp)<=Convert(Date,''' + @ToDate +''',105)'										
					end
				if(@PartNo<>'')
					begin
						set @qry=@qry + ' And A.PartNo=''' + @PartNo +''''
					end
				if(@DateCode<>'')
					begin
						set @qry=@qry + ' And A.DateCode=''' + @DateCode +''''
					end
				set @Qry=@qry + 'Group By CAST(A.ScanTimestamp AS DATE), L.LineName, A.Datecode, A.PartNo, A.Status, A.Barcode,
									M.MachineName, M.MachineCode, A.FailCount
										Order By 1,3,4,5,9'

				Execute sp_sqlexec @qry

				set @ReturnValue='SUCCESS'
				set @ReturnInt=0
				return
			end
	else if(@Condition='PRODUCTIONDATASUMMARY_MIDDLEDROPPassBUTNOTPROCESSED')
			begin
				DECLARE	@Cols AS nVARCHAR(MAX) = '';
				DECLARE	@FilterColumn AS nVARCHAR(MAX) = '', @FilterQuery AS nVARCHAR(MAX) = '';

				IF OBJECT_ID ('Tempdb..#RunningStatus') IS NOT NULL
				DROP TABLE #RunningStatus

						SELECT DISTINCT
						R.OperationSeqNo,
						ISNULL(A.Barcode, '') Barcode,
						ISNULL(A.MachineCode, '') MachineCode,
						M.MachineName AS MachineName,
						(CASE
							WHEN ISNULL(A.Status,'') = '' THEN ''
							ELSE (CASE
									WHEN A.Status = 'PS' THEN 'Pass'
									ELSE 'FAIL'
								END)
						END) ResuLt,
						ISNULL(A.ResultTimestamp, '') ResultTimestamp INTO #RunningStatus
					FROM (SELECT
						L.*
					FROM RoutingConfigLineWise L WITH (NOLOCK)
					INNER JOIN RoutingConfigPartWise P WITH (NOLOCK)
						ON L.ProfitCenterCode = P.ProfitCenterCode
						AND L.OperationCode = P.OperationCode
						AND L.MachineCode = P.MachineCode
					WHERE L.LineCode = @LineCode
					AND L.TraceabiLity = 1
					AND P.TraceabiLity = 1) R
					LEFT OUTER JOIN Assy_LineAssyStatus A WITH (NOLOCK)
						ON A.LineCode = R.LineCode
						AND A.MachineCode = R.MachineCode
					INNER JOIN MachineMst M WITH (NOLOCK)
						ON A.MachineCode = M.MachineCode
					WHERE A.ProfitCenterCode = @ProfitCenterCode AND A.LineCode = @LineCode
							AND A.Status = 'PS'
							AND A.Datecode = @DateCode
						Order By R.OperationSeqNo

						--SELECT * FROM #RunningStatus Order By OperationSeqNo
					DECLARE @TempRunning AS TABLE (
						MachineCode VARCHAR(20),
						Barcode VARCHAR(60),
						Record INT
					)
		
					INSERT INTO @TempRunning (MachineCode, Barcode, Record)
						SELECT
							MachineCode,
							Barcode,
							COUNT(Barcode)
						FROM #RunningStatus(NOLOCK)
							GROUP By MachineCode,Barcode
								HAVING COUNT(Barcode) > 1
		
					DELETE Running_Temp
						FROM #RunningStatus Running_Temp
						INNER JOIN @TempRunning TV
							ON Running_Temp.MachineCode = TV.MachineCode
							AND Running_Temp.Barcode = TV.Barcode
					WHERE Running_Temp.ResuLt = 'FaiL'

					--SELECT * FROM #RunningStatus
					SELECT
						@Cols = STUFF((SELECT
							',' + QUOTENAME(Col + '_' + CAST(Seq AS VARCHAR(10)))
						FROM (SELECT
							ROW_NUMBER() OVER (Partition By Barcode
							Order By OperationSeqNo) Seq
						FROM #RunningStatus) T
						CROSS APPLY (SELECT
							'MachineName',
							1
						UNION ALL
						SELECT
							'ResuLt',
							2
						UNION ALL
						SELECT
							'ResultTimestamp',
							3) c (Col, So)
						GROUP By	Col,Seq,So
						Order By Seq, So
						FOR xml PATH (''), TYPE)
						.value('.', 'NVARCHAR(MAX)')
						, 1, 1, '')

					SELECT
						@FilterColumn = STUFF((SELECT
							',' + QUOTENAME(Col + '_' + CAST(Seq AS VARCHAR(10)))
						FROM (SELECT
							ROW_NUMBER() OVER (Partition By Barcode
							Order By OperationSeqNo) Seq
						FROM #RunningStatus) T
						CROSS APPLY (
						SELECT
							'ResultTimestamp',
							3) c (Col, So)
						GROUP By	Col,Seq,So
						Order By Seq, So
						FOR xml PATH (''), TYPE)
						.value('.', 'NVARCHAR(MAX)')
						, 1, 1, '')
						DECLARE @Result TABLE (Id INT IDENTITY(1,1) NOT NULL,Column1 VARCHAR(100))
						DECLARE @IntLocation INT
						WHILE (CHARINDEX(',',    @FilterColumn, 0) > 0)
						BEGIN
							  SET @IntLocation =   CHARINDEX(',',    @FilterColumn, 0)      
							  INSERT INTO   @Result (Column1)
							  SELECT RTRIM(LTRIM(SUBSTRING(@FilterColumn, 0, @IntLocation)))
							  SET @FilterColumn = STUFF(@FilterColumn, 1, @IntLocation, '')
						END
						INSERT INTO   @Result (Column1)
						SELECT RTRIM(LTRIM(@FilterColumn))

						SET @Id = 1
						WHILE((SELECT COUNT(*) FROM @Result) > 0)
						BEGIN
							IF @Id = 1
								SET @FilterQuery = ' WHERE ' + 'ISNULL(' + (SELECT Column1 FROM @Result WHERE Id = @Id) + ','''') = '''''
							ELSE IF @Id > 1
							BEGIN
								SET @FilterQuery = @FilterQuery + ' OR ' + 'ISNULL(' + (SELECT Column1 FROM @Result WHERE Id = @Id) + ','''') = '''''
							END
				
							IF @Id = (SELECT COUNT(*) FROM @Result)
								BREAK
							SET @Id = @Id + 1
						END
						--SELECT @FilterQuery
						IF OBJECT_ID('FinalResult') IS NOT NULL
							DROP TABLE FinalResult

						SET @qry = 'SELECT Barcode ,' + @Cols + ' INTO FinalResult
									FROM 
									(
									 SELECT Barcode, 
										Col = Col+''_''+cast(Seq AS VARCHAR(10)), 
										value
									 FROM
									 (
										SELECT Barcode, MachineName , ResuLt, CONVERT(VARCHAR,ResultTimestamp,120) ResultTimestamp,
										 row_number() OVER(Partition By Barcode
															Order By OperationSeqNo ) Seq
										FROM #RunningStatus
									 ) SRC
									 CROSS APPLY
									 (
										SELECT ''MachineName'',MachineName UNION ALL
										SELECT ''ResuLt'', ResuLt UNION ALL
										SELECT ''ResultTimestamp'', CONVERT(VARCHAR(100), ResultTimestamp) 
									 ) c (Col, value)
									) x
									pivot 
									(
										MAX(value)
										for Col in (' + @Cols + ')
									) P
									'
						EXECUTE sp_EXECutesqL @qry
						SET @qry = ''
						SET @qry = ' SELECT CAST(ResultTimestamp_1 AS DATE) BarcodePrintDate,* FROM FinalResult ' + @FilterQuery + ''
						Execute sp_sqlexec @qry

				set @ReturnValue='SUCCESS'
				set @ReturnInt=0
				return
			end
	else if(@Condition='COUPLINGDATA')
			begin
					DECLARE @LineTypeCode VARCHAR(20) = '';
					SELECT Top 1 @LineTypeCode = dbo.Assy_FN_Get_LineTypeName_From_LineCode(@ProfitCenterCode,@LineCode)

					IF @LineTypeCode != 'STMC'
					BEGIN
						set @ReturnValue='This Line is not having Coupling Station'
						set @ReturnInt=1
						RETURN
					END

					Declare @CouplingData As Table
						(	CouplingDate Date,
							LineName Varchar(30),
							DateCode Char(4),
							MachineName Varchar(50),
							FG_PartNo Varchar(20),
							FG_Barcode Varchar(60) Primary Key,
							BoosterPartNo Varchar(20),
							BoosterBarcode Varchar(60),
							BoosterScanDate DateTime,
							TMCPartNo Varchar(20),
							TMCBarcode Varchar(60),
							TMCScanDate DateTime
						)

					DELETE FROM @CouplingData

					INSERT INTO @CouplingData (LineName, DateCode, MachineName, FG_Barcode)
					SELECT Distinct L.LineName, A.Datecode, M.MachineName, A.FG_Barcode FROM Assy_CouplingDetails A WITH (NOLOCK)
					INNER JOIN LineMst L WITH (NOLOCK) ON L.ProfitCenterCode = A.ProfitCentreCode AND L.LineCode = A.LineCode
					INNER JOIN MachineMst M WITH (NOLOCK) ON M.ProfitCenterCode = A.ProfitCentreCode AND M.MachineCode = A.MACHINE_CODE
					WHERE A.ProfitCentreCode = @ProfitCenterCode AND A.LineCode = @LineCode 
					AND A.ENT_DT between case when (@isDateCodeFilter=1) then  A.ENT_DT else @FromDate end
									 and case when (@isDateCodeFilter=1) then A.ENT_DT else  @ToDate end
					AND A.DateCode = case when @isDateCodeFilter = 1 then @DateCode else A.DateCode end
					Group By L.LineName, A.Datecode, M.MachineName, A.STMC_PART_NO, A.FG_Barcode
					Order By 2,4

					UPDATE C SET
						C.BoosterPartNo = AC.CHILD_PART_NO,
						C.BoosterBarcode = AC.CHILD_Barcode ,
						C.BoosterScanDate = AC.ENT_DT,
						C.FG_PartNo = AC.STMC_PART_NO
					FROM @CouplingData C
					INNER JOIN Assy_CouplingDetails AC WITH (NOLOCK) ON C.FG_Barcode = AC.FG_Barcode
					WHERE AC.ProfitCentreCode = @ProfitCenterCode AND AC.LineCode = @LineCode
					AND AC.PART_TYPE = 'SERVO' AND  AC.ENT_DT between case when (@isDateCodeFilter=1) then  AC.ENT_DT else @FromDate end
					and case when (@isDateCodeFilter=1) then AC.ENT_DT else  @ToDate end
					AND AC.DateCode = case when @isDateCodeFilter = 1 then @DateCode else AC.DateCode end

					UPDATE C SET
						C.TMCPartNo = AC.CHILD_PART_NO,
						C.TMCBarcode = AC.CHILD_Barcode ,
						C.TMCScanDate = AC.ENT_DT,
						C.CouplingDate = AC.ENT_DT
					FROM @CouplingData C
					INNER JOIN Assy_CouplingDetails AC WITH (NOLOCK)
					ON C.FG_Barcode = AC.FG_Barcode
					WHERE AC.ProfitCentreCode = @ProfitCenterCode AND AC.LineCode = @LineCode
					AND AC.PART_TYPE = 'TMC' AND AC.ENT_DT between case when (@isDateCodeFilter=1) then  AC.ENT_DT else @FromDate end
					and case when (@isDateCodeFilter=1) then AC.ENT_DT else  @ToDate end
					AND AC.DateCode = case when @isDateCodeFilter = 1 then @DateCode else AC.DateCode end

					SELECT CouplingDate, LineName, DateCode, MachineName, FG_PartNo, FG_Barcode, BoosterPartNo, BoosterBarcode, BoosterScanDate, TMCPartNo, TMCBarcode, TMCScanDate
						FROM @CouplingData Order By 1,3,5,6,8,11
			
					set @ReturnValue='SUCCESS'
					set @ReturnInt=0
					return
			end
	else if(@Condition='MANUALPassDATA')
			begin
				--set @Qry='SELECT CAST(A.Timestamp AS DATE) ManualPassDate , A.ProfitCenterCode, L.LineName, M.MachineName, A.Barcode, Case A.Status WHEN ''PS'' THEN ''Pass'' ELSE A.Status END Barcode_Status, A.Remarks
				--	FROM Assy_LineAssyManualPassFail A WITH (NOLOCK)
				--		INNER JOIN MachineMst M WITH (NOLOCK)
