				--if(@FromDate<>'' and @ToDate<>'')
				--	begin											
				--		set @qry=@qry + '  And convert(Date,A.Timestamp)>=convert(Date,''' + @FromDate +''',105) 
				--					AND convert(Date,A.Timestamp)<=Convert(Date,''' + @ToDate +''',105)'										
				--	end
