				--Execute sp_sqlexec @qry	
				SELECT CAST(A.Timestamp AS DATE) ManualPassDate , A.ProfitCenterCode, L.LineName, M.MachineName, A.Barcode, 
				Case A.Status WHEN 'PS' THEN 'Pass' ELSE A.Status END Barcode_Status, A.Remarks
				FROM Assy_LineAssyManualPassFail A WITH (NOLOCK)
				INNER JOIN MachineMst M WITH (NOLOCK) ON M.ProfitCenterCode = A.ProfitCenterCode AND M.MachineCode = A.MachineCode
				INNER JOIN LineMst L WITH (NOLOCK) ON L.ProfitCenterCode = A.ProfitCenterCode AND L.LineCode = A.LineCode
				WHERE A.ProfitCenterCode =@ProfitCenterCode AND A.LineCode = @LineCode 
				AND A.Timestamp between case when (@isDateCodeFilter=1) then  A.Timestamp else @FromDate end
									and case when (@isDateCodeFilter=1) then A.Timestamp else  @ToDate end
				AND A.Barcode like case when @isDateCodeFilter = 1 then '%'+@DateCode+'%' else A.Barcode end
				AND A.Barcode like '%' + @PartNo +'%' 
				Order By 1,4,5		
				
				set @ReturnValue='SUCCESS'
				set @ReturnInt=0
				return
			end
		else if(@Condition='PACKAGING_SUMMARYDATA')
			begin
				--set @Qry='SELECT SBI.WH_CODE ProfitCenterCode, CAST(SBI.SkidBarcodePrintedTimestamp AS DATE) SkidLabelPrintDate,
				--			SBI.SkidBarcode, SBI.DispatchType, COUNT(SBD.PartBarcode) Qty
				--				FROM SkidBarcodeInfo SBI WITH (NOLOCK)
				--					INNER JOIN SkidBarcodeDetail SBD WITH (NOLOCK)
				--						ON SBI.SkidBarcodeInfoID = SBD.SkidBarcodeInfoID AND SBI.WH_CODE = SBD.WH_CODE
				--							WHERE SBI.WH_CODE =''' + @ProfitCenterCode + '''AND SBD.WH_CODE = ''' + @ProfitCenterCode + '''
				--								AND SBI.SkidBarcodeInfoID IN (SELECT Distinct SkidBarcodeInfoID FROM SkidBarcodeDetail (NOLOCK)
				--											WHERE WH_CODE =''' + @ProfitCenterCode + '''AND SBI.DATECODE=''' + @DateCode + ''')
				--									AND ISNULL(SBI.SkidBarcode,'''') != '''''
				--if(@PartNo<>'')
				--	begin
				--		set @qry=@qry + ' And SBI.SkidBarcode like ''%' + @PartNo +'%'''
				--	end
				--set @Qry=@qry + '	Group By SBI.WH_CODE, SBI.SkidBarcodePrintedTimestamp, SBI.SkidBarcode, SBI.DispatchType
				--		Order By 1,2,3,4,5'
				--		print @Qry
				--Execute sp_sqlexec @qry
				--Comented and replaced by AV ON 20170302

				SELECT SBI.WH_CODE ProfitCenterCode, CAST(SBI.SkidBarcodePrintedTimestamp AS DATE) SkidLabelPrintDate, SBI.SkidBarcode, 
				SBI.DispatchType, COUNT(SBD.PartBarcode) Qty FROM SkidBarcodeInfo SBI WITH (NOLOCK)
				INNER JOIN SkidBarcodeDetail SBD WITH (NOLOCK) ON SBI.SkidBarcodeInfoID = SBD.SkidBarcodeInfoID AND SBI.WH_CODE = SBD.WH_CODE
				WHERE SBI.WH_CODE = @ProfitCenterCode AND SBD.WH_CODE =  @ProfitCenterCode AND SBD.WH_CODE =@ProfitCenterCode 
				AND SBI.SkidBarcodePrintedTimestamp between case when (@isDateCodeFilter=1) then SBI.SkidBarcodePrintedTimestamp else @FromDate end
														and case when (@isDateCodeFilter=1) then SBI.SkidBarcodePrintedTimestamp else  @ToDate end
				AND SBI.DATECODE = case when @isDateCodeFilter = 1 then @DateCode else SBI.DATECODE end
				AND ISNULL(SBI.SkidBarcode,'')<>''
				And SBI.SkidBarcode like '%' + isNull(@PartNo,'') +'%'
				Group By SBI.WH_CODE, SBI.SkidBarcodePrintedTimestamp, SBI.SkidBarcode, SBI.DispatchType
				Order By 1,2,3,4,5	
							
				set @ReturnValue='SUCCESS'
