	/*
	This block will executable in central server.
	It is fetching data for all assembly lines.
	EXECUTE Assy_Proc_Traceability_Analysis @ProfitcenterCode='0021'
		,@LineCode='M02'
		,@DateCode='20Qc'
		,@PartNo='ALL'
