					WHERE lm.LineCode=@LineCode
						AND lm.ProfitCenterCode=@ProfitCentercode
			SET @Qry='DECLARE @tbTraceBarcodeStatus AS TABLE
						(
						ProfitCenterCode			VARCHAR(10)
						,LineCode					VARCHAR(10)
						,DateCode					VARCHAR(4)
						,PartNo						VARCHAR(15)
						,Barcode					NVARCHAR(100)
						,Servo						NVARCHAR(100)
						,TMC						NVARCHAR(100)
						,SkidBarcode				NVARCHAR(100)
						,SkidSerialNo				NVARCHAR(15)
						,WH_Code					VARCHAR(10)
						,SkidOrPartCurrentLocation	VARCHAR(100)
						,CurrentStatus				VARCHAR(100)); 

						IF(OBJECT_ID(''tempdb..#CouplingDetails'')) IS NOT NULL 
							DROP TABLE #CouplingDetails '

			IF(@LineTypeName='TMC') -- We are checking the line type TMC or STMC
				BEGIN
					SET @Qry=@Qry + ' SELECT acd.ProfitCentreCode,acd.LineCode, acd.DateCode, acd.STMC_PART_NO AS PartNo, acd.FG_Barcode AS Barcode, acd.PART_TYPE, acd.CHILD_Barcode
							INTO #CouplingDetails FROM  Assy_CouplingDetails acd(NOLOCK)  
							WHERE acd.FG_Barcode IN (SELECT FG_Barcode FROM Assy_CouplingDetails acd(NOLOCK) INNER JOIN assy_lineassystatus alas(NOLOCK) ON acd.Child_Barcode =alas.Barcode  
								AND acd.ProfitCentreCode=alas.ProfitCenterCode 
							WHERE alas.datecode =''' + @DateCode  + '''
								AND alas.LineCode=''' + @LineCode + ''''
						IF(@PartNo<>'ALL')
							BEGIN
								SET @Qry=@Qry + ' and alas.Partno=''' + @PartNo + ''''
							END
					SET @Qry=@Qry + ' AND alas.ProfitCenterCode=''' + @ProfitCentercode +''')'
				END
			IF(@LineTypeName='STMC')
				BEGIN
					SET @Qry=@Qry + ' SELECT acd.ProfitCentreCode,acd.LineCode,acd.DateCode,acd.STMC_PART_NO AS PartNo,acd.FG_Barcode AS Barcode,acd.PART_TYPE,acd.CHILD_Barcode  
										INTO #CouplingDetails FROM  Assy_CouplingDetails acd (NOLOCK) 
											WHERE acd.datecode =''' + @DateCode + '''
												AND acd.LineCode=''' + @LineCode + '''' 
							IF(@PartNo<>'ALL')
							BEGIN
								SET @Qry=@Qry + ' AND acd.STMC_Part_no=''' + @PartNo + ''''
							END
					SET @Qry=@Qry + ' AND acd.ProfitCentreCode=''' + @ProfitCentercode +''''
				END
				IF(@LineTypeName='CALIPER') -- We are checking the line type TMC or STMC
				BEGIN
					SET @Qry=@Qry + ' SELECT acd.ProfitCentreCode,acd.LineCode, acd.DateCode, acd.STMC_PART_NO AS PartNo, acd.FG_Barcode AS Barcode, acd.PART_TYPE, acd.CHILD_Barcode
							INTO #CouplingDetails FROM  Assy_CouplingDetails acd(NOLOCK)  
							WHERE acd.FG_Barcode IN (SELECT FG_Barcode FROM Assy_CouplingDetails acd(NOLOCK) INNER JOIN assy_lineassystatus alas(NOLOCK) ON acd.Child_Barcode =alas.Barcode  
								AND acd.ProfitCentreCode=alas.ProfitCenterCode 
							WHERE alas.datecode =''' + @DateCode  + '''
								AND alas.LineCode=''' + @LineCode + ''''
						IF(@PartNo<>'ALL')
							BEGIN
								SET @Qry=@Qry + ' and alas.Partno=''' + @PartNo + ''''
							END
					SET @Qry=@Qry + ' AND alas.ProfitCenterCode=''' + @ProfitCentercode +''')'
				END
			SET @Qry=@Qry + ' INSERT INTO @tbTraceBarcodeStatus SELECT pitb.*,sbi.SkidBarcode,iv.Serial_no,iv.WH_CODE,iv.Loc_id+ '' - '' + cm.CUSTOMER_NM AS SkidorPartCurrentLocation, ''COUPLED, PACKED,SHIPPED'' AS CurrentStatus FROM #CouplingDetails cd 
								PIVOT (MAX(CHILD_Barcode)  FOR Part_Type IN ([SERVO],[TMC])) AS pitb 
								INNER JOIN SkidBarcodeDetail sbd(NOLOCK) ON sbd.PartBarcode=pitb.Barcode 
								INNER JOIN SkidBarcodeInfo sbi(NOLOCK) ON sbi.SkidBarcodeInfoID=sbd.SkidBarcodeInfoID 
								INNER JOIN inv_serial iv(NOLOCK) on iv.SERIAL_NO=sbi.pkg_ts_serial 
								INNER JOIN Customer_Master cm(NOLOCK) ON cm.Customer_C=iv.LOC_ID
			
							INSERT INTO @tbTraceBarcodeStatus SELECT pitb.*,sbi.SkidBarcode,iv.Serial_no,iv.WH_CODE,iv.Loc_id + '' - '' + LM.LOCATION_NAME, ''COUPLED, PACKED,NOT SHIPPED'' AS CurrentStatus FROM #CouplingDetails cd 
								PIVOT (MAX(CHILD_Barcode)  FOR Part_Type IN ([SERVO],[TMC])) AS pitb 
								INNER JOIN SkidBarcodeDetail sbd(NOLOCK) ON sbd.PartBarcode=pitb.Barcode 
								INNER JOIN SkidBarcodeInfo sbi(NOLOCK) ON sbi.SkidBarcodeInfoID=sbd.SkidBarcodeInfoID 
								INNER JOIN inv_serial iv(NOLOCK) on iv.SERIAL_NO=sbi.pkg_ts_serial 
								INNER JOIN LOCATION_MASTER lm(NOLOCK) ON lm.LOC_ID=iv.LOC_ID
	
							INSERT INTO @tbTraceBarcodeStatus SELECT pitb.*,'''' AS SkidBarcode,'''' AS Serial_no,lm.ProfitCenterCode,lm.WorkCenterCode AS Loc_id, ''COUPLED, NOT PACKED'' AS CurrentStatus FROM #CouplingDetails cd 
								PIVOT (MAX(CHILD_Barcode)  FOR Part_Type IN ([SERVO],[TMC])) AS pitb 
								INNER JOIN lineMst lm(NOLOCK) ON lm.LineCode=pitb.LineCode AND lm.ProfitCenterCode=pitb.ProfitCentreCode 
									WHERE pitb.Barcode NOT IN (SELECT Barcode FROM @tbTraceBarcodeStatus) 
	
							INSERT INTO @tbTraceBarcodeStatus SELECT alas.ProfitCenterCode,alas.LineCode, alas.DateCode, alas.PartNo, alas.Barcode,'''' AS SERVO,'''' AS TMC, sbi.SkidBarcode,iv.Serial_no,iv.WH_CODE,iv.Loc_id + '' - '' + cm.CUSTOMER_NM,''PACKED,SHIPPED'' as Cu


r


rentStatus
							 from assy_lineassystatus alas(NOLOCK) 
								INNER JOIN SkidBarcodeDetail sbd(NOLOCK) ON sbd.PartBarcode=alas.Barcode 
								INNER JOIN SkidBarcodeInfo sbi(NOLOCK) ON sbi.SkidBarcodeInfoID=sbd.SkidBarcodeInfoID 
								INNER JOIN inv_serial iv(NOLOCK) ON iv.SERIAL_NO=sbi.pkg_ts_serial 
								INNER JOIN Customer_Master cm(NOLOCK) ON cm.Customer_C=iv.LOC_ID
								WHERE alas.datecode=''' + @DateCode + '''   
									AND alas.LineCode=''' + @LineCode + '''
									AND alas.ProfitCenterCode=''' + @ProfitCenterCode + '''

							INSERT INTO @tbTraceBarcodeStatus SELECT alas.ProfitCenterCode,alas.LineCode, alas.DateCode, alas.PartNo, alas.Barcode,'''' AS SERVO,'''' AS TMC, sbi.SkidBarcode,iv.Serial_no,iv.WH_CODE,iv.Loc_id + '' - '' + LM.LOCATION_NAME,''PACKED,NOT SHIPPED'' 




as CurrentStatus from assy_lineassystatus alas(NOLOCK) 
								INNER JOIN SkidBarcodeDetail sbd(NOLOCK) ON sbd.PartBarcode=alas.Barcode 
								INNER JOIN SkidBarcodeInfo sbi(NOLOCK) ON sbi.SkidBarcodeInfoID=sbd.SkidBarcodeInfoID 
								INNER JOIN inv_serial iv(NOLOCK) ON iv.SERIAL_NO=sbi.pkg_ts_serial 
								INNER JOIN LOCATION_MASTER lm(NOLOCK) ON lm.LOC_ID=iv.LOC_ID
								WHERE alas.datecode=''' + @DateCode + '''  
									AND alas.LineCode=''' + @LineCode + '''
									AND alas.ProfitCenterCode=''' + @ProfitCenterCode + '''
									AND alas.Barcode NOT IN (SELECT Barcode FROM @tbTraceBarcodeStatus) 

		
							INSERT INTO @tbTraceBarcodeStatus SELECT alas.ProfitCenterCode,alas.LineCode, alas.DateCode, alas.PartNo, alas.Barcode,'''' as SERVO,'''' as TMC, '''' as SkidBarcode,'''' as Serial_no,lm.ProfitCenterCode,lm.WorkCenterCode as Loc_id,
							''NOT COUPLED / NOT PACKED'' as CurrentStatus from assy_lineassystatus alas(NOLOCK)  
								INNER JOIN lineMst lm(NOLOCK) on lm.LineCode=alas.LineCode AND lm.ProfitCenterCode=alas.ProfitCenterCode 
								WHERE alas.Barcode NOT IN (SELECT Barcode FROM @tbTraceBarcodeStatus) 
									AND alas.Barcode NOT IN (SELECT TMC FROM @tbTraceBarcodeStatus WHERE TMC<>'''') 
									AND  alas.datecode=''' + @DateCode + '''  
									AND alas.LineCode=''' + @LineCode + '''
									AND alas.ProfitCenterCode=''' + @ProfitCenterCode + ''''

						IF(@PartNo<>'ALL')
							BEGIN
								SET @Qry=@Qry + ' and alas.Partno=''' + @PartNo + ''''
							END

						SET @Qry=@Qry + ' SELECT * FROM @tbTraceBarcodeStatus'
						PRINT @Qry
				EXECUTE sp_sqlexec @Qry
		END
	ELSE IF(@Condition='MANPOWER_DATA')
			BEGIN
				SELECT amp.ProfitCenterCode,PartNo,LineCode,mm.MachineName,DateCode,Clock_ID,Created_TimeStamp FROM assy_manpower4s amp(NOLOCK) 
				INNER JOIN MachineMst mm ON	amp.ProfitCenterCode=mm.ProfitCenterCode AND amp.StationCode=mm.MachineCode 
				WHERE	amp.Created_TimeStamp between case when (@isDateCodeFilter=1) then  amp.Created_TimeStamp else @FromDate end
												  and case when (@isDateCodeFilter=1) then amp.Created_TimeStamp else  @ToDate end
				and amp.DateCode = case when @isDateCodeFilter = 1 then @DateCode else amp.DateCode end
				AND amp.LineCode=@LineCode AND amp.ProfitCenterCode=@ProfitCentercode
				--@isDateCodeFilter

				ORDER  BY 1,2 ASC
			END
	ELSE IF(@Condition='POKAYOKE_RESULT')
		BEGIN
			SELECT FORMAT(ResultTimestamp,'dd-MM-yyyy') AS [Date], UserID AS UserID ,pk.LineCode  AS LineCode, pk.Datecode AS DateCode,PK.PartNo AS PartNo,ISNULL(OM.OperationName,'') AS OperatorName,
			CASE WHEN ISNULL(Pk.IsActive,0)=0 THEN 'By Pass' ELSE ISNULL(pk.ActResult,'') END AS [Status],ISNULL(pk.Description,'') AS [Description]
			FROM Assy_POKAYOKE_Status PK WITH(NOLOCK) 			
			LEFT OUTER JOIN OperationMst OM WITH (NOLOCK) ON pk.OperationCode =OM.OperationCode 
			LEFT OUTER JOIN RoutingConfigLineWise RL WITH (NOLOCK) ON UPPER(LTRIM(RTRIM(PK.linecode)))=UPPER(LTRIM(RTRIM(RL.linecode))) 
			AND LTRIM(RTRIM(PK.operationcode))=LTRIM(RTRIM(rl.operationcode))
			WHERE	
			--pk.Datecode=@DateCode AND 
			pk.ScanTimestamp between case when (@isDateCodeFilter=1) then pk.ScanTimestamp else @FromDate end
													and case when (@isDateCodeFilter=1) then pk.ScanTimestamp else  @ToDate end
			AND pk.Datecode = case when @isDateCodeFilter = 1 then @DateCode else PK.DATECODE end
			AND PK.PartNo=isNull(nullif(@Partno,''),PK.PartNo)
			AND pk.LineCode=@LineCode
			and pk.ProfitCenterCode =@ProfitCentercode
			ORDER BY 3,4 ASC
		END
	ELSE IF(@Condition='MANUAL_PRINTED_BARCODES')
		BEGIN
			SELECT ProfitCenterCode,LineCode,DateCode,Barcode,TimeStamp,PartNo FROM Assy_Manual_Printed_Barcode WITH (NOLOCK)
			WHERE Timestamp between case when (@isDateCodeFilter=1) then Timestamp else @FromDate end
								and case when (@isDateCodeFilter=1) then Timestamp else  @ToDate end
			AND DATECODE = case when @isDateCodeFilter = 1 then @DateCode else DATECODE end
			AND LineCode=@LineCode
			AND ProfitCenterCode=@ProfitCentercode
			ORDER BY 1,2,3,4 ASC
		END
	else if(@Condition='PARAMETER_DATA_ANALYSIS')
			begin
