					DROP TABLE #TagDetails
				IF(OBJECT_ID('tempdb...#MachineDetails')) IS NOT NULL
					DROP TABLE #MachineDetails
				IF(OBJECT_ID('TEMP_Report_ParamDataTable')) IS NOT NULL
				DROP TABLE TEMP_Report_ParamDataTable
				IF(OBJECT_ID('TEMP_Report_TagDetailS')) IS NOT NULL
				DROP TABLE TEMP_Report_TagDetailS
				IF(OBJECT_ID('TEMP_Report_MachineDetails')) IS NOT NULL
				DROP TABLE TEMP_Report_MachineDetails

				
				--SET @QRYPARAMETER='
				--			IF(OBJECT_ID(''tempdb...#ParamDataTable'')) IS NOT NULL
				--			DROP TABLE #ParamDataTable

				--			SELECT avpd.ProfitCenterCode, avpd.Barcode,ISNULL(avpd.TagName,mm.MachineName) AS TagName,ISNULL(avpd.Value,'''') AS Value, mm.MachineCode,mm.MachineName
				--			,CASE WHEN avpd.Result= ''PS'' THEN ''Pass''
				--			WHEN avpd.Result=''FL'' THEN ''Fail''
				--			ELSE avpd.Result END AS Result ,avpd.Timestamp, rclw.OperationSeqNo
				--			INTO #ParamDataTable FROM Assy_View_ParamData avpd
				--			INNER JOIN MachineMst mm ON avpd.MachineCode=mm.MachineCode
				--				AND avpd.ProfitCenterCode=mm.ProfitCenterCode
				--			INNER JOIN RoutingConfigLineWise rclw ON avpd.LineCode=rclw.LineCode
				--				AND avpd.MachineCode=rclw.MachineCode
				--				AND avpd.ProfitCenterCode=rclw.ProfitCenterCode
				--			WHERE avpd.ProfitCenterCode=''' + @ProfitCentercode + '''
				--			AND avpd.LineCode=''' + @LineCode + '''
				--			AND avpd.Timestamp between case when (''' + convert(varchar,@isDateCodeFilter) + '''=1) then  avpd.Timestamp else ''' + @FromDate + ''' end
				--									and case when (''' + convert(varchar,@isDateCodeFilter)  + '''=1) then avpd.Timestamp else ''' + @ToDate + '''  end
				--			AND avpd.DateCode = case when ''' + convert(varchar,@isDateCodeFilter) + ''' = 1 then ''' + @DateCode + ''' else avpd.DateCode end
				--			AND ISNULL(avpd.TagName,avpd.MachineCode) IN  (select tagname from Temp_Tags_Assy_Proc_Traceability_Analysis)
				--			ORDER BY rclw.OperationSeqNo
				--			SELECT DISTINCT DENSE_RANK() OVER(ORDER BY OperationSeqNo ASC) AS ID, MachineCode,MachineName,OperationSeqNo INTO #MachineDetails FROM #ParamDataTable'

				
							SELECT avpd.ProfitCenterCode, avpd.Barcode,ISNULL(avpd.TagName,mm.MachineName) AS TagName,ISNULL(avpd.Value,'') AS Value, mm.MachineCode,mm.MachineName
								,CASE WHEN avpd.Result= 'PS' THEN 'Pass'
									WHEN avpd.Result='FL' THEN 'Fail'
									ELSE avpd.Result END AS Result ,avpd.Timestamp, rclw.OperationSeqNo
							INTO TEMP_Report_ParamDataTable FROM Assy_View_ParamData avpd
								INNER JOIN MachineMst mm ON avpd.MachineCode=mm.MachineCode
									AND avpd.ProfitCenterCode=mm.ProfitCenterCode
								INNER JOIN RoutingConfigLineWise rclw ON avpd.LineCode=rclw.LineCode
									AND avpd.MachineCode=rclw.MachineCode
									AND avpd.ProfitCenterCode=rclw.ProfitCenterCode
									AND rclw.Traceability=1
									AND rclw.OperationRequired=1
							WHERE 
