												   and case when (@isDateCodeFilter=1) then avpd.Timestamp else  @ToDate end
								AND avpd.DateCode = case when @isDateCodeFilter = 1 then @DateCode else avpd.DateCode end
								AND avpd.ProfitCenterCode=@ProfitCentercode
								AND avpd.LineCode=@LineCode
								AND isnull(avpd.TagName,avpd.MachineCode) IN (select tagname from Temp_Tags_Assy_Proc_Traceability_Analysis)
								--IN (select case when tagname='' then MachineCode + ' Barcode'  else tagname end as tagname from Assy_TraceabilityAnalysis_Tags (nolock) where ProfitCentercode=@ProfitCenterCode 
								--and LineCode=@LineCode and activestatus=1)
							ORDER BY rclw.OperationSeqNo
			
							SELECT Distinct MachineCode,MachineName,Tagname,OperationSeqNo into TEMP_Report_TagDetailS FROM TEMP_Report_ParamDataTable order by TagName
							delete from TEMP_Report_TagDetailS where TagName in ('Result','TimeStamp','Barcode','ProfitCenterCode','MachineName')

							

							--DROP TABLE #TagDetailS
		
							SELECT DISTINCT DENSE_RANK() OVER(ORDER BY OperationSeqNo ASC) AS ID, MachineCode,MachineName,OperationSeqNo INTO TEMP_Report_MachineDetails FROM TEMP_Report_ParamDataTable
							SELECT * FROM TEMP_Report_MachineDetails --ORDER BY ID
							SELECT * FROM TEMP_Report_TagDetailS ORDER BY OperationSeqNo,MachineCode,TagName

							SET @COUNT=(SELECT  count(*) FROM TEMP_Report_MachineDetails)
							print '------ Count ---------- ' + Convert(varchar,@COUNT)
							--WHILE @ID1<=@COUNT
							--	BEGIN
