																GROUP BY OperationSeqNo,MachineCode,TagName
																ORDER BY  OperationSeqNo,MachineCode,TagName
																FOR XML PATH(''), TYPE
																).value('.', 'NVARCHAR(MAX)') 
															,1,1,'')
	
									SELECT @cols1 = STUFF((SELECT ',' + QUOTENAME(MachineCode) FROM TEMP_Report_TagDetails 
									WHERE MachineCode IN (SELECT MachineCode FROM TEMP_Report_MachineDetails where ID=@ID1) 
																			GROUP BY OperationSeqNo,MachineCode
																			ORDER BY OperationSeqNo,MachineCode
																FOR XML PATH(''), TYPE
																).value('.', 'NVARCHAR(MAX)') 
															,1,1,'')
									
									IF(ISNULL(@cols1,'')='')
