									SELECT @cols2 = STUFF((SELECT ',' + QUOTENAME(MachineCode) + ' AS [' + MachineName +' TimeStamp]' FROM TEMP_Report_TagDetails 
									WHERE MachineCode IN (SELECT MachineCode FROM TEMP_Report_MachineDetails where ID=@ID1)
																			GROUP BY OperationSeqNo,MachineCode,MachineName
																			ORDER BY OperationSeqNo,MachineCode,MachineName
																FOR XML PATH(''), TYPE
																).value('.', 'NVARCHAR(MAX)') 
															,1,1,'')

									SELECT  TOP 1 @TableName = MachineCode FROM TEMP_Report_MachineDetails where ID=@ID1
									
									SELECT ROW_NUMBER() OVER(ORDER BY OperationSeqNo,TagName ASC) AS ID, * INTO #TagDetails11 fROM TEMP_Report_TagDetails 									
									WHERE MachineCode=@TableName ORDER BY TagName asc
									DECLARE @i int=1;
									--DECLARE @MACHINENAME1 VARCHAR(30);
									
									SET @id3 =(select count(*) from #TagDetails11 WHERE MachineCode=@TableName )
									
									--SET @TableName =(SELECT TOP 1 MachineCode FROM #MachineDetails WHERE ID=@ID1)
									--SELECT * FROM #TagDetails11
									set @SqlStart = '
											IF(OBJECT_ID('+''''+ 'TEMP_REPORT_'+@TableName +''''+')) IS NOT NULL
											DROP TABLE TEMP_REPORT_' + @TableName + '

											CREATE TABLE TEMP_REPORT_' + @TableName + ' ( ProfitCenterCode NVARCHAR(50), MachineName NVARCHAR(50), Barcode NVARCHAR(100), TimeStamp NVARCHAR(30), Result NVARCHAR(50) '
								SET @sql=''
																		
									while @i<=@id3
										begin
											SET @sql = @sql + ',[' + (select TagName from #TagDetailS11 where ID=@i and MachineCode= @TableName) + ']	NVARCHAR(50) '
											SET @i=@i+1
										end
									SET @sqlEnd=@SqlStart + ISNULL(@sql,'') + ')'
									
									IF(ISNULL(@cols2,'')='' OR ISNULL(@cols,'')='')
									BEGIN
										
										SET @sqlEnd = @sqlEnd + '
												INSERT INTO TEMP_REPORT_' + @TableName + ' 
												SELECT ProfitCenterCode,MachineName,Barcode,[Timestamp],Result FROM 
													(
													SELECT ProfitCenterCode,Barcode,MachineCode,MachineName,Result,Timestamp,OperationSeqNo,Value
													FROM TEMP_Report_ParamDataTable WHERE MachineCode IN (SELECT MachineCode FROM TEMP_Report_MachineDetails where ID=' + CAST(@ID1 as varchar) + ')
												) tmptable

												'
									END
									ELSE
									BEGIN
										
									SET @sqlEnd = @sqlEnd + '
												INSERT INTO TEMP_REPORT_' + @TableName + ' 
												SELECT A.ProfitCenterCode,A.MachineName,A.Barcode,'+ @cols2 +' ,Result,' + @cols + ' FROM 
													(
													SELECT ProfitCenterCode,Barcode,MachineCode,MachineName,Result,Timestamp,OperationSeqNo,Value,TagName
													FROM TEMP_Report_ParamDataTable WHERE MachineCode IN (SELECT MachineCode FROM TEMP_Report_MachineDetails where ID=' + CAST(@ID1 as varchar) + ')
												) tmptable
													
												PIVOT 
												(
													MAX(Value)
													FOR TagName in (' + @cols + ')
												) P1

												PIVOT 
												(
													MAX(Timestamp)
													FOR MachineCode in (' + @cols1 + ')
												) A 											
												
												'
									
									END
									SET @TableQuery =@TableQuery + @sqlend
									print @sqlend
									exec(@sqlend)  -- Added by sachin 30-03-2018
									set @TableQuery=''
