					DROP TABLE #TagDetails
				IF(OBJECT_ID('tempdb...#MachineDetails')) IS NOT NULL
					DROP TABLE #MachineDetails
				SET @QRYPARAMETER='
							IF(OBJECT_ID(''tempdb...#ParamDataTable1'')) IS NOT NULL
							DROP TABLE #ParamDataTable1
							SELECT avpd.ProfitCenterCode, avpd.Barcode,ISNULL(avpd.TagName,mm.MachineName) AS TagName,ISNULL(avpd.Value,'''') AS Value, mm.MachineCode,mm.MachineName
							,CASE WHEN avpd.Result= ''PS'' THEN ''Pass''
							WHEN avpd.Result=''FL'' THEN ''Fail''
							ELSE avpd.Result END AS Result ,avpd.Timestamp, rclw.OperationSeqNo
								 INTO #ParamDataTable1 FROM Assy_View_ParamData avpd
								INNER JOIN MachineMst mm ON avpd.MachineCode=mm.MachineCode
										AND avpd.ProfitCenterCode=mm.ProfitCenterCode
								INNER JOIN RoutingConfigLineWise rclw ON avpd.LineCode=rclw.LineCode
										AND avpd.MachineCode=rclw.MachineCode
										AND avpd.ProfitCenterCode=rclw.ProfitCenterCode
							WHERE avpd.ProfitCenterCode=''' + @ProfitCentercode + '''
									AND avpd.LineCode=''' + @LineCode + '''
									AND avpd.Timestamp between case when (''' + convert(varchar,@isDateCodeFilter) + '''=1) then  avpd.Timestamp else ''' + @FromDate + ''' end
														  and case when (''' + convert(varchar,@isDateCodeFilter) + '''=1) then avpd.Timestamp else ''' + @ToDate + '''  end
									AND avpd.DateCode = case when ''' + convert(varchar,@isDateCodeFilter) + ''' = 1 then ''' + @DateCode + ''' else avpd.DateCode end
									AND ISNULL(avpd.TagName,avpd.MachineCode) IN (select tagname from Temp_Tags_Assy_Proc_Traceability_Analysis)
							ORDER BY rclw.OperationSeqNo
			
							SELECT DISTINCT DENSE_RANK() OVER(ORDER BY OperationSeqNo ASC) AS ID, MachineCode,MachineName,OperationSeqNo INTO #MachineDetails1 FROM #ParamDataTable1'

							SELECT avpd.ProfitCenterCode, avpd.Barcode,ISNULL(avpd.TagName,mm.MachineName) AS TagName,ISNULL(avpd.Value,'') AS Value, mm.MachineCode,mm.MachineName
								,CASE WHEN avpd.Result= 'PS' THEN 'Pass'
									WHEN avpd.Result='FL' THEN 'Fail'
									ELSE avpd.Result END AS Result ,avpd.Timestamp, rclw.OperationSeqNo
							INTO #ParamDataTable1 FROM Assy_View_ParamData avpd
								INNER JOIN MachineMst mm ON avpd.MachineCode=mm.MachineCode
									AND avpd.ProfitCenterCode=mm.ProfitCenterCode
								INNER JOIN RoutingConfigLineWise rclw ON avpd.LineCode=rclw.LineCode
									AND avpd.MachineCode=rclw.MachineCode
									AND avpd.ProfitCenterCode=rclw.ProfitCenterCode
							WHERE avpd.Timestamp between case when (@isDateCodeFilter=1) then avpd.Timestamp else @FromDate end
												   and case when (@isDateCodeFilter=1) then avpd.Timestamp else  @ToDate end
								AND avpd.DateCode = case when @isDateCodeFilter = 1 then @DateCode else avpd.DateCode end
								AND avpd.ProfitCenterCode=@ProfitCentercode
								AND avpd.LineCode=@LineCode
								AND isnull(avpd.TagName,avpd.MachineCode) IN (select tagname from Temp_Tags_Assy_Proc_Traceability_Analysis)
								-- (select case when tagname='' then MachineCode + ' Barcode'  else tagname end as tagname 
								--from Assy_TraceabilityAnalysis_Tags (nolock) where ProfitCentercode=@ProfitCenterCode and LineCode=@LineCode and activestatus=1)
							ORDER BY rclw.OperationSeqNo
			
							SELECT Distinct MachineCode,MachineName,Tagname,OperationSeqNo into #TagDetailS1 FROM #ParamDataTable1 order by TagName

							--DROP TABLE #TagDetailS
		
							SELECT DISTINCT DENSE_RANK() OVER(ORDER BY OperationSeqNo ASC) AS ID, MachineCode,MachineName,OperationSeqNo INTO #MachineDetails1 FROM #ParamDataTable1
							--SELECT * FROM #MachineDetails --ORDER BY ID
							SELECT * FROM #MachineDetails1 --ORDER BY ID
							SELECT * FROM #TagDetails1 ORDER BY OperationSeqNo,MachineCode,TagName
							--SELECT * FROM #TagDetailS1 ORDER BY OperationSeqNo,MachineCode,TagName

							SET @COUNT=(SELECT  count(*) FROM #MachineDetails1)
							set @ID1=1
							WHILE @ID1<=@COUNT
								BEGIN
									SET @TEMPQUERY= @TEMPQUERY + '
												if exists(select * from tempdb.dbo.sysobjects o
														where o.name like ''%' + (SELECT MachineCode FROM #MachineDetails1 where ID=@ID1) + '%'') 
															DROP TABLE #' + (SELECT MachineCode FROM #MachineDetails1 where ID=@ID1) +'  '
									SET @ID1 =@ID1 + 1;
								END

							SET @ID1=1;
				
							WHILE @ID1<=@COUNT
								BEGIN
									SELECT  TOP 1 @TableName = MachineCode FROM #MachineDetails1 where ID=@ID1
									
									SELECT ROW_NUMBER() OVER(ORDER BY OperationSeqNo,TagName ASC) AS ID, * INTO #TagDetails12 fROM #TagDetails1 WHERE MachineCode=@TableName ORDER BY TagName asc
									DECLARE @i3 int=1;
									--DECLARE @MACHINENAME1 VARCHAR(30);
									
									SET @id3 =(select count(*) from #TagDetails12 WHERE MachineCode=@TableName)
					
									set @SqlStart = '
											CREATE TABLE #' + @TableName + ' ( ProfitCenterCode NVARCHAR(50), MachineName NVARCHAR(50), Barcode NVARCHAR(100), TimeStamp NVARCHAR(30), Result NVARCHAR(50) )'
									SET @sqlEnd=@SqlStart;
									SET @sqlEnd = @sqlEnd + '
												INSERT INTO #' + @TableName + ' 
												SELECT A.ProfitCenterCode,A.MachineName,A.Barcode,A.Timestamp,A.Result FROM 
													(
													SELECT ProfitCenterCode,Barcode,MachineCode,MachineName,Result,Timestamp,OperationSeqNo,Value,TagName
													FROM #ParamDataTable1 WHERE MachineCode IN (SELECT MachineCode FROM #MachineDetails1 where ID=' + CAST(@ID1 as varchar) + ')
												) A '

									SET @TableQuery =@TableQuery + @sqlend
									SET @sqlend= '';
									SET @ID1=@ID1+1
				
							IF(@JoinQuery='')
								BEGIN
									SET @ParentTable='#' + @TableName
									SET @JoinQuery=' SELECT DISTINCT * FROM #' + @TableName
								END
							ELSE
								BEGIN
									 SET @JoinQuery= @JoinQuery +' LEFT OUTER JOIN #' + @TableName + ' ON ' + @ParentTable +'.PROFITCENTERCODE=#'+ @TableName +'.PROFITCENTERCODE AND ' + @ParentTable +'.BARCODE=#'+@TableName+'.BARCODE'
								END
							drop table #TagDetailS12
							set @query=''
						END	
				
				set @query=''
				set @query = @TEMPQUERY + @QRYPARAMETER + @TableQuery + @JoinQuery
				PRINT  @query;
				EXEC sp_sqlexec @query;
			end
	else if(@Condition='PARAMETERDATAANALYSIS_STATIONWISE')
		begin
				IF(OBJECT_ID('tempdb...#AssyParamdata2')) IS NOT NULL
					DROP TABLE #AssyParamdata

				IF(OBJECT_ID('tempdb...#TagDetails2')) IS NOT NULL
					DROP TABLE #TagDetails
				IF(OBJECT_ID('tempdb...#MachineDetails2')) IS NOT NULL
