							WHERE avpd.Timestamp between case when (''' + convert(varchar,@isDateCodeFilter) + '''=1) then  avpd.Timestamp else ''' + @FromDate + ''' end
													and case when (''' + convert(varchar,@isDateCodeFilter)  + '''=1) then avpd.Timestamp else ''' + @ToDate + '''  end
							AND avpd.DateCode = case when ''' + convert(varchar,@isDateCodeFilter) + ''' = 1 then ''' + @DateCode + ''' else avpd.DateCode end
								AND avpd.ProfitCenterCode=''' + @ProfitCenterCode + '''
								AND avpd.LineCode='''  + @LineCode + '''
								AND isnull(avpd.TagName,avpd.MachineCode) IN (select case when tagname='''' then MachineCode + ''_Station''  else tagname end as tagname from Assy_TraceabilityAnalysis_Tags (nolock) 
								where ProfitCentercode=''' + @ProfitCenterCode + ''' and LineCode='''+ @Linecode +''' and activestatus=1)
								AND avpd.Barcode NOT IN (SELECT FGBARCODE FROM @SERVOPARAMDATA1)
								ORDER BY rclw.OperationSeqNo 
							
								SELECT DISTINCT DENSE_RANK() OVER(ORDER BY OperationSeqNo ASC) AS ID, MachineCode,MachineName,OperationSeqNo INTO #MachineDetails13 FROM @SERVOPARAMDATA1'

							--DROP TABLE @SERVOPARAMDATA1 
		 INSERT INTO @SERVOPARAMDATA1 SELECT DISTINCT * FROM (SELECT acd.ProfitCentreCode as ProfitCenterCode,acd.LineCode,acd.Datecode,mm.MachineName,mm.MachineCode,acd.STMC_PART_NO,acd.FG_Barcode as Barcode,acd.PART_TYPE,acd.Child_Barcode,
						ISNULL(alpd.TagName,mm.MachineCode + '_Station') AS TagName, convert(varchar(20),alpd.Value) AS Value,
						CASE WHEN alpd.Result='PS' THEN 'Pass'
							WHEN alpd.Result='FL' THEN 'Fail'
							--WHEN alpd.Result='PE' THEN 'Fail'
							ELSE alpd.Result END AS Result,alpd.Timestamp,rclw.OperationSeqNo
							 FROM Assy_View_ParamData alpd(NOLOCK)
								INNER JOIN  Assy_CouplingDetails acd (NOLOCK) ON acd.LineCode=alpd.LineCode
									AND alpd.Barcode in (acd.Child_Barcode,acd.FG_Barcode)
									AND acd.ProfitCentreCode=alpd.ProfitCenterCode
									AND acd.STMC_PART_NO=alpd.PartNo
									AND acd.DateCode=alpd.DateCode
										left JOIN TagMst tm(NOLOCK) ON ISNULL(alpd.tagid,0)=ISNULL(tm.tagid,0)
											JOIN MachineMst mm(NOLOCK) ON mm.Machinecode=alpd.Machinecode
												JOIN RoutingConfigLineWise rclw(NOLOCK)  ON rclw.MachineCode=mm.MachineCode
												WHERE  alpd.Timestamp between case when (@isDateCodeFilter =1) then  alpd.Timestamp else @FromDate end
																		and case when (@isDateCodeFilter =1) then alpd.Timestamp else @ToDate end
													AND alpd.DateCode = case when @isDateCodeFilter= 1 then @DateCode else alpd.DateCode end
													AND alpd.LineCode=@LineCode
													AND alpd.ProfitCenterCode=@ProfitCentercode
													AND ISNULL(alpd.Tagname,alpd.MachineCode) in (SELECT CASE WHEN tagname='' THEN MachineCode + '_Station' ELSE tagname END AS tagname 
													FROM Assy_TraceabilityAnalysis_Tags (NOLOCK) WHERE ProfitCentercode=@ProfitCentercode AND LineCode=@LineCode AND activestatus=1)
					) A
					PIVOT(MAX(CHild_Barcode) FOR Part_Type IN ([SERVO],[TMC])) AS tbResult


		INSERT INTO @SERVOPARAMDATA1	SELECT avpd.ProfitCenterCode, avpd.LineCode,avpd.Datecode, mm.MachineName,mm.MachineCode,avpd.PartNo, avpd.Barcode,ISNULL(avpd.TagName,mm.MachineName) AS TagName,ISNULL(avpd.Value,'') AS Value, 
									CASE WHEN avpd.Result= 'PS' THEN 'Pass'
									WHEN avpd.Result='FL' THEN 'Fail'
									ELSE avpd.Result END AS Result ,avpd.Timestamp, rclw.OperationSeqNo,'' AS ServoBarcode,'' AS TMCBarcode
								FROM Assy_View_ParamData avpd
									INNER JOIN MachineMst mm ON avpd.MachineCode=mm.MachineCode
										AND avpd.ProfitCenterCode=mm.ProfitCenterCode
									INNER JOIN RoutingConfigLineWise rclw ON avpd.LineCode=rclw.LineCode
										AND avpd.MachineCode=rclw.MachineCode
										AND avpd.ProfitCenterCode=rclw.ProfitCenterCode
							WHERE avpd.Timestamp between case when (@isDateCodeFilter=1) then  avpd.Timestamp else @FromDate end
														 and case when (@isDateCodeFilter =1) then avpd.Timestamp else @ToDate end
								AND avpd.DateCode = case when @isDateCodeFilter = 1 then @DateCode else avpd.DateCode end
								AND avpd.ProfitCenterCode=@ProfitCenterCode
								AND avpd.LineCode=@LineCode
								AND isnull(avpd.TagName,avpd.MachineCode) IN (select case when tagname='' then MachineCode + '_Station'  else tagname end as tagname from 
								Assy_TraceabilityAnalysis_Tags (nolock) where ProfitCentercode=@ProfitCentercode and LineCode=@LineCode and activestatus=1)
								AND avpd.BARCODE NOT IN (SELECT FGBARCODE FROM @SERVOPARAMDATA1)
							ORDER BY rclw.OperationSeqNo


							SELECT Distinct MachineCode,MachineName,Tagname,OperationSeqNo into #TagDetailS13 FROM @SERVOPARAMDATA1 order by TagName

							--DROP TABLE #TagDetailS
		
							SELECT DISTINCT DENSE_RANK() OVER(ORDER BY OperationSeqNo ASC) AS ID, MachineCode,MachineName,OperationSeqNo INTO #MachineDetails13 FROM @SERVOPARAMDATA1
							SELECT * FROM #MachineDetails13 --ORDER BY ID
							SELECT * FROM #TagDetails13 ORDER BY OperationSeqNo,MachineCode,TagName

							SET @COUNT=(SELECT  count(*) FROM #MachineDetails13)
							set @ID1=1;
							WHILE @ID1<=@COUNT
								BEGIN
									SET @TEMPQUERY= @TEMPQUERY + '
												if exists(select * from tempdb.dbo.sysobjects o
														where o.name like ''%' + (SELECT MachineCode FROM #MachineDetails13 where ID=@ID1) + '%'') 
															DROP TABLE #' + (SELECT MachineCode FROM #MachineDetails13 where ID=@ID1) +'  '
									SET @ID1 =@ID1 + 1;
								END

							SET @ID1=1;
				
							WHILE @ID1<=@COUNT
								BEGIN

									SELECT @cols = STUFF((SELECT ',' + QUOTENAME(TagName) FROM #TagDetails13 WHERE MachineCode IN (SELECT MachineCode FROM #MachineDetails13 where ID=@ID1)
																			GROUP BY OperationSeqNo,MachineCode,TagName
																			ORDER BY  OperationSeqNo,MachineCode,TagName
																FOR XML PATH(''), TYPE
																).value('.', 'NVARCHAR(MAX)') 
															,1,1,'')
	
									SELECT @cols1 = STUFF((SELECT ',' + QUOTENAME(MachineCode) FROM #TagDetails13 WHERE MachineCode IN (SELECT MachineCode FROM #MachineDetails13 where ID=@ID1)
																			GROUP BY OperationSeqNo,MachineCode
																			ORDER BY OperationSeqNo,MachineCode
																FOR XML PATH(''), TYPE
																).value('.', 'NVARCHAR(MAX)') 
															,1,1,'')
									SELECT @cols2 = STUFF((SELECT ',' + QUOTENAME(MachineCode) + ' AS [' + MachineName +' TimeStamp]' FROM #TagDetails13 WHERE MachineCode IN (SELECT MachineCode FROM #MachineDetails13 where ID=@ID1)
																			GROUP BY OperationSeqNo,MachineCode,MachineName
																			ORDER BY OperationSeqNo,MachineCode,MachineName
																FOR XML PATH(''), TYPE
																).value('.', 'NVARCHAR(MAX)') 
															,1,1,'')

					
									SET @TableName =(SELECT TOP 1 MachineCode FROM #MachineDetails13 WHERE ID=@ID1)
									SELECT ROW_NUMBER() OVER(ORDER BY OperationSeqNo,TagName ASC) AS ID, * INTO #TagDetails14 fROM #TagDetails13 WHERE MachineCode=@TableName ORDER BY OperationSeqNo,MachineCode,TagName
									--select * from #TagDetails14 
									declare @ii int =1;
									SET @id3 =(select count(*) from #TagDetails14)
									
									set @sql='';
									set @SqlStart = '
											CREATE TABLE #' + @TableName + ' ( ProfitCenterCode NVARCHAR(50),FGBarcode NVARCHAR(50),SERVOBARCODE NVARCHAR(50),TMCBARCODE NVARCHAR(50),MachineName NVARCHAR(50), TimeStamp NVARCHAR(30), Result NVARCHAR(50) '
				
									while @ii<=@id3
										begin
										--select TagName from #TagDetails14 where ID=@ii
											SET @sql = @sql + ',[' + (select TagName from #TagDetails14 where MachineCode=@TableName AND id=@ii) + ']	NVARCHAR(50) '
											SET @ii=@ii+1
										end
									SET @sqlEnd=@SqlStart + @sql + ')'
	--PRINT @sqlEnd
									SET @sqlEnd = @sqlEnd + '
												INSERT INTO #' + @TableName + ' 
												SELECT A.ProfitCenterCode,A.FGBarcode,A.SERVOBARCODE,A.TMCBARCODE,MachineName,'+ @cols2 +' ,Result AS Result,' + @cols + '  FROM 
													(
													SELECT ProfitCenterCode,FGBarcode,MachineCode,MachineName,TagName,Value,Result,Timestamp,OperationSeqNo,SERVOBarcode,TMCBarcode
													FROM @SERVOPARAMDATA1 WHERE MachineCode IN (SELECT MachineCode FROM #MachineDetails13 where ID=' + CAST(@ID1 as varchar) + ')
												) tmptable
													
												PIVOT 
												(
													MAX(Value)
													FOR TagName in (' + @cols + ')
												) P1

												PIVOT 
												(
													MAX(Timestamp)
													FOR MachineCode in (' + @cols1 + ')
												) A '

									SET @TableQuery =@TableQuery + @sqlend
									--PRINT @TableQuery
									SET @SqlStart=''
									SET @ID1=@ID1+1
				
							IF(@JoinQuery='')
								BEGIN
									SET @ParentTable='#' + @TableName
									SET @JoinQuery=' SELECT DISTINCT * FROM #' + @TableName
								END
							ELSE
								BEGIN
									 SET @JoinQuery= @JoinQuery +' LEFT OUTER JOIN #' + @TableName + ' ON ' + @ParentTable +'.PROFITCENTERCODE=#'+ @TableName +'.PROFITCENTERCODE AND ' + @ParentTable +'.FGBARCODE=#'+@TableName+'.FGBARCODE'
								END
							drop table #TagDetailS14
							set @query=''
						END	
			
				set @query=''
				--print @QRYPARAMETER  
				--print   @TableQuery 
				set @query = @QRYPARAMETER+  @TEMPQUERY + @TableQuery + @JoinQuery
			
				PRINT  @query;

				EXEC sp_sqlexec @query;
			END

	else if(@Condition='SERVO_PARAMETERDATAANALYSIS_STATIONWISE_RESULT')
		begin
				IF(OBJECT_ID('tempdb...#AssyParamdata8')) IS NOT NULL
					DROP TABLE #AssyParamdata8

				IF(OBJECT_ID('tempdb...#TagDetails8')) IS NOT NULL
					DROP TABLE #TagDetails8
				IF(OBJECT_ID('tempdb...#MachineDetails8')) IS NOT NULL
					DROP TABLE #MachineDetails8

			SELECT avpd.ProfitCenterCode, avpd.Barcode,ISNULL(avpd.TagName,mm.MachineName) AS TagName,ISNULL(avpd.Value,'') AS Value, mm.MachineCode,mm.MachineName
				,CASE WHEN avpd.Result= 'PS' THEN 'Pass'
					WHEN avpd.Result='FL' THEN 'Fail'
					ELSE avpd.Result END AS Result ,avpd.Timestamp, rclw.OperationSeqNo
			INTO #AssyParamdata8 FROM Assy_View_ParamData avpd
				INNER JOIN MachineMst mm ON avpd.MachineCode=mm.MachineCode
					AND avpd.ProfitCenterCode=mm.ProfitCenterCode
				INNER JOIN RoutingConfigLineWise rclw ON avpd.LineCode=rclw.LineCode
					AND avpd.MachineCode=rclw.MachineCode
					AND avpd.ProfitCenterCode=rclw.ProfitCenterCode
					--AND avpd.Result='FL'
			WHERE avpd.Timestamp between case when (@isDateCodeFilter=1) then  avpd.Timestamp else @FromDate end
									 and case when (@isDateCodeFilter =1) then avpd.Timestamp else @ToDate end
				AND avpd.DateCode = case when @isDateCodeFilter = 1 then @DateCode else avpd.DateCode end
				AND avpd.LineCode=@LineCode
				AND avpd.ProfitCenterCode=@ProfitCenterCode
				AND avpd.TagName in (select case when tagname='' then MachineCode + ' Barcode' else tagname end as tagname from Assy_TraceabilityAnalysis_Tags (nolock) where LineCode=@LineCode AND ProfitCentercode=@ProfitCenterCode  and activestatus=1)
			ORDER BY rclw.OperationSeqNo

			SELECT Distinct MachineCode,MachineName,Tagname,OperationSeqNo into #TagDetailS8 FROM #AssyParamdata8 WHERE MachineCode=@MachineCode order by TagName

			--DROP TABLE #TagDetailS

			SELECT DISTINCT DENSE_RANK() OVER(ORDER BY OperationSeqNo ASC) AS ID, MachineCode,MachineName,OperationSeqNo INTO #MachineDetails8 FROM #AssyParamdata8 WHERE MachineCode=@MachineCode
			SELECT * FROM #MachineDetails8 --ORDER BY ID
			SELECT * FROM #TagDetails8 ORDER BY OperationSeqNo,MachineCode,TagName


					SELECT @cols = STUFF((SELECT ',' + QUOTENAME(TagName) FROM #TagDetails8 WHERE MachineCode IN (SELECT MachineCode FROM #MachineDetails8)
															GROUP BY OperationSeqNo,MachineCode,TagName
															ORDER BY  OperationSeqNo,MachineCode,TagName
												FOR XML PATH(''), TYPE
												).value('.', 'NVARCHAR(MAX)') 
											,1,1,'')
	
					SELECT @cols1 = STUFF((SELECT ',' + QUOTENAME(MachineCode) FROM #TagDetails8 WHERE MachineCode IN (SELECT MachineCode FROM #MachineDetails8)
															GROUP BY OperationSeqNo,MachineCode
															ORDER BY OperationSeqNo,MachineCode
												FOR XML PATH(''), TYPE
												).value('.', 'NVARCHAR(MAX)') 
											,1,1,'')
					SELECT @cols2 = STUFF((SELECT ',' + QUOTENAME(MachineCode) + ' AS [' + MachineName +' TimeStamp]' FROM #TagDetails8 WHERE MachineCode IN (SELECT MachineCode FROM #MachineDetails8)
															GROUP BY OperationSeqNo,MachineCode,MachineName
															ORDER BY OperationSeqNo,MachineCode,MachineName
												FOR XML PATH(''), TYPE
												).value('.', 'NVARCHAR(MAX)') 
											,1,1,'')


					SET @query = ' SELECT ProfitCenterCode,Barcode,'+ @cols2 +' ,Result fRoM 
									(
									SELECT ProfitCenterCode,Barcode,MachineCode,MachineName,Result,Timestamp,OperationSeqNo
									FROM #AssyParamdata8 WHERE MachineCode=''' + @MachineCode + '''
								) tmptable
								
								PIVOT 
								(
									MAX(Timestamp)
									FOR MachineCode in (' + @cols1 + ')
								) A '

			--SET @query= REPLACE(@query,SUBSTRING(@query COLLATE Latin1_General_CS_AS, CHARINDEX('fRoM', @query COLLATE Latin1_General_CS_AS), 4),',' + SUBSTRING(@tables,1,LEN(@tables)-1) + ' from')

			PRINT @Query
			EXECUTE(@query);
			end

	else if(@Condition='SERVO_PARAMETERDATAANALYSIS_STATIONWISE')
		BEGIN
			IF(OBJECT_ID('tempdb...#AssyParamdata9')) IS NOT NULL
				DROP TABLE #AssyParamdata9
			IF(OBJECT_ID('tempdb...#TagDetails9')) IS NOT NULL
				DROP TABLE #TagDetails9
			IF(OBJECT_ID('tempdb...#MachineDetails9')) IS NOT NULL
				DROP TABLE #MachineDetails9

			SELECT avpd.ProfitCenterCode, avpd.Barcode,ISNULL(avpd.TagName,mm.MachineName) AS TagName,ISNULL(avpd.Value,'') AS Value,
			 mm.MachineCode,mm.MachineName,CASE WHEN avpd.Result= 'PS' THEN 'Pass'
			 WHEN avpd.Result='FL' THEN 'Fail'
			 ELSE avpd.Result END AS Result ,avpd.Timestamp, rclw.OperationSeqNo
			 INTO #AssyParamdata9 FROM Assy_View_ParamData avpd
			INNER JOIN MachineMst mm ON avpd.MachineCode=mm.MachineCode
			AND avpd.ProfitCenterCode=mm.ProfitCenterCode
			INNER JOIN RoutingConfigLineWise rclw ON avpd.LineCode=rclw.LineCode
			AND avpd.MachineCode=rclw.MachineCode
			AND avpd.ProfitCenterCode=rclw.ProfitCenterCode
			WHERE avpd.Timestamp between case when @isDateCodeFilter=1 then  avpd.Timestamp else @FromDate end
									 and case when @isDateCodeFilter=1 then avpd.Timestamp else @ToDate end
					AND avpd.DateCode = case when @isDateCodeFilter= 1 then @DateCode else avpd.DateCode end
				AND avpd.LineCode=@LineCode
				AND avpd.ProfitCenterCode=@ProfitCenterCode
				AND avpd.TagName in (select case when tagname='' then MachineCode + ' Barcode' else tagname end as tagname from Assy_TraceabilityAnalysis_Tags (nolock) where ProfitCentercode=@ProfitCenterCode and LineCode=@LineCode and activestatus=1)
			ORDER BY rclw.OperationSeqNo

			SELECT Distinct MachineCode,MachineName,Tagname,OperationSeqNo into #TagDetailS9 FROM #AssyParamdata9 WHERE MachineCode=@MachineCode order by TagName

			--DROP TABLE #TagDetailS

			SELECT DISTINCT DENSE_RANK() OVER(ORDER BY OperationSeqNo ASC) AS ID, MachineCode,MachineName,OperationSeqNo INTO #MachineDetails9 FROM #AssyParamdata9 WHERE MachineCode=@MachineCode
			SELECT * FROM #MachineDetails9 --ORDER BY ID
			SELECT * FROM #TagDetails9 ORDER BY OperationSeqNo,MachineCode,TagName


					SELECT @cols = STUFF((SELECT ',' + QUOTENAME(TagName) FROM #TagDetails9 WHERE MachineCode IN (SELECT MachineCode FROM #MachineDetails9)
															GROUP BY OperationSeqNo,MachineCode,TagName
															ORDER BY  OperationSeqNo,MachineCode,TagName
												FOR XML PATH(''), TYPE
												).value('.', 'NVARCHAR(MAX)') 
											,1,1,'')
	
					SELECT @cols1 = STUFF((SELECT ',' + QUOTENAME(MachineCode) FROM #TagDetails9 WHERE MachineCode IN (SELECT MachineCode FROM #MachineDetails9)
															GROUP BY OperationSeqNo,MachineCode
															ORDER BY OperationSeqNo,MachineCode
												FOR XML PATH(''), TYPE
												).value('.', 'NVARCHAR(MAX)') 
											,1,1,'')
					SELECT @cols2 = STUFF((SELECT ',' + QUOTENAME(MachineCode) + ' AS [' + MachineName +' TimeStamp]' FROM #TagDetails9 WHERE MachineCode IN (SELECT MachineCode FROM #MachineDetails9)
															GROUP BY OperationSeqNo,MachineCode,MachineName
															ORDER BY OperationSeqNo,MachineCode,MachineName
												FOR XML PATH(''), TYPE
												).value('.', 'NVARCHAR(MAX)') 
											,1,1,'')


					SET @query = ' SELECT ProfitCenterCode,Barcode,'+ @cols2 +' ,Result,' + @cols + ' fRoM 
									(
									SELECT ProfitCenterCode,Barcode,MachineCode,MachineName,Result,Timestamp,OperationSeqNo,Value,TagName
									FROM #AssyParamdata9 WHERE MachineCode=''' + @MachineCode + '''
								) tmptable
													
								PIVOT 
								(
									MAX(Value)
									FOR TagName in (' + @cols + ')
								) P1

								PIVOT 
								(
									MAX(Timestamp)
									FOR MachineCode in (' + @cols1 + ')
								) A '

			--SET @query= REPLACE(@query,SUBSTRING(@query COLLATE Latin1_General_CS_AS, CHARINDEX('fRoM', @query COLLATE Latin1_General_CS_AS), 4),',' + SUBSTRING(@tables,1,LEN(@tables)-1) + ' from')

			PRINT @Query
			EXECUTE(@query);
			end
	ELSE IF(@Condition = 'TALLYCHART_SUMMARY')
		BEGIN
					SELECT  ATCSDH.ProfitCenterCode,ATCSDH.LineCode, ATCSDH.DateCode,ATCSDH.MachineCode,MM.MachineName,	
					SUM(CASE WHEN ATCSDH.Result='PASS' THEN 1 ELSE 0 END) AS Pass_Qty,
					SUM(CASE WHEN ATCSDH.Result='FAIL' THEN 1 ELSE 0 END) AS Fail_Qty,
					SUM(CASE WHEN ATCSDH.Result='' AND ATCSDH.NotProcessedStatus='SCRAP' THEN 1 ELSE 0 END) AS Scrap_Qty,
					SUM(CASE WHEN ATCSDH.Result='' AND ATCSDH.NotProcessedStatus='REWORK' THEN 1 ELSE 0 END) AS Rework_Qty
					FROM Assy_TallyChartStatusData_History (nolock) ATCSDH
					INNER JOIN MachineMst MM ON ATCSDH.ProfitCenterCode = MM.ProfitCenterCode AND ATCSDH.MachineCode = MM.MachineCode
					INNER JOIN (SELECT DISTINCT ProfitCenterCode, MachineCode,OperationSeqNo FROM RoutingConfigLineWise) RCLW ON MM.ProfitCenterCode = RCLW.ProfitCenterCode
					AND MM.MachineCode = RCLW.MachineCode
					WHERE	ATCSDH.TimeStamp between case when (@isDateCodeFilter=1) then ATCSDH.TimeStamp else @FromDate end
												 and case when (@isDateCodeFilter=1) then ATCSDH.TimeStamp else @ToDate end
					AND ATCSDH.DateCode = case when @isDateCodeFilter = 1 then @DateCode else ATCSDH.DateCode end
					AND ATCSDH.LineCode = @LineCode AND ATCSDH.ProfitCenterCode=@ProfitCentercode
					GROUP BY ATCSDH.ProfitCenterCode,Datecode,ATCSDH.LineCode,ATCSDH.MachineCode,MM.MachineName,RCLW.OperationSeqNo
					ORDER BY RCLW.OperationSeqNo,ATCSDH.DateCode
			
		END
	ELSE IF(@Condition = 'TALLYCHART_SUMMARY_DETAILS')
		BEGIN
		SELECT @isDateCodeFilter,@FromDate,@ToDate,@DateCode,@MachineCode,@ProfitCentercode

					SELECT ProfitCenterCode,LineCode,Datecode,PartNo,Barcode,Result,Timestamp,NotProcessedStatus,Reason,Remarks FROM Assy_TallyChartStatusData_History (nolock)
					WHERE TimeStamp between case when (@isDateCodeFilter=1) then TimeStamp else @FromDate end
									    and case when (@isDateCodeFilter=1) then TimeStamp else @ToDate end
					AND DateCode = case when @isDateCodeFilter = 1 then @DateCode else DateCode end
					AND Result = 'PASS'
					AND MachineCode = @MachineCode
					AND ProfitCenterCode=@ProfitCentercode
					--MODIFICATION BY AV ON 20170426
					--AND PartNo = @PartNo
					--ORDER BY Timestamp,Barcode,PartNo,Result
					return
		END
	ELSE IF(@Condition = 'INVOICE_TRACE')
		BEGIN
		    SELECT CAST(tsc.ENT_STAMP AS DATE) AS [Date], tsc.INVOICE_NO, tsc.SERIAL_NO, sbi.SkidBarcode,sbi.LotSize, sbi.DispatchType FROM Temp_Shipment_confirmation tsc(NOLOCK)
					JOIN SkidBarcodeInfo sbi(NOLOCK) ON sbi.pkg_ts_serial=tsc.Serial_no
            WHERE	tsc.INVOICE_NO LIKE '%' + @InvoiceNo +'%'
		END
	ELSE IF(@Condition = 'GET_SKID_DETAILS')
		BEGIN
		    SELECT ROW_NUMBER() OVER (ORDER BY SKIDBARCODE ASC) AS Sno,sbd.WH_Code,sbd.SkidBarcodeInfoID,sbd.PartBarcode,sbd.ScanTimeStamp,sbd.LocationInSkid FROM SkidBarcodeDetail sbd 
			INNER JOIN SkidBarcodeInfo sbi ON sbi.SkidBarcodeInfoID=sbd.SkidBarcodeInfoID 
			WHERE sbi.SkidBarcode=@SkidBarcode
		END
	ELSE IF(@Condition = 'GET_BOM_DETAILS')
		BEGIN
			CREATE TABLE #BOM_DETAILS
			(
			FG_PartNo			VARCHAR(50)
			,BOMPart_No			VARCHAR(50)
			,RM_Part_No			VARCHAR(50)
			,BOM_QTY			INT
			,BOM_UOM			NVARCHAR(50)
			,MAT_PROCURE_TYPE	NVARCHAR(50)
			,MAT_USE_RATION		NVARCHAR(50)
			,ALT_ITEM_GRP_CODE	NVARCHAR(50)
			)

			SELECT TOP 1 @Partno=PartNo FROM Assy_LineAssyStatus WITH (NOLOCK) WHERE Barcode=@Barcode AND ProfitCenterCode=@ProfitCentercode

			INSERT INTO #BOM_DETAILS EXECUTE Proc_BOM_Explosion @ProfitCenterCode,@PartNo,'','1','SUMMARY'

			SELECT FG_PartNo,RM_Part_No,BOM_QTY FROM #BOM_DETAILS

			--SELECT FG_PartNo,RM_Part_No,BOM_QTY FROM #BOM_DETAILS BD
			--INNER JOIN Product_Master PM WITH (NOLOCK) ON BD.RM_Part_No=PM.SEWS_PART_NO AND PM.PART_TRACE_FLAG=1

			--ADDED BY AV 20170407 TO RETURN DETALILED SUMMRY OF BOM DATA 
			SELECT bd.FG_PartNo,bd.RM_Part_No,bd.BOM_QTY, ISNULL(FGC.RM_SERIAL_NO,'')as INV_SERIAL,isnull(I.GE_NO,'') 
			AS GE_NO,ISNULL(I.GR_NO,'') AS GR_NO,ISNULL(I.INT_LOT_NO,'') AS LOT_NO FROM #BOM_DETAILS bd
			left JOIN Assy_FGChildPartConsumption fgc ON bD.FG_PartNo= FGC.FG_PART_NO AND bd.RM_Part_No=FGC.RM_PART_NO AND fgc.FG_BARCODE=@Barcode
			LEFT JOIN INV_SERIAL I ON fgc.Rm_SERIAL_NO=i.SERIAL_NO
			GROUP BY FGC.RM_SERIAL_NO,bd.FG_PartNo,bd.RM_Part_No,bd.BOM_QTY,I.GE_NO,I.GR_NO,I.INT_LOT_NO

			SELECT LineCode,STMC_PART_NO,CHILD_PART_NO,PART_TYPE,CHILD_Barcode,DateCode FROM Assy_CouplingDetails WHERE FG_Barcode=@Barcode
	END
	ELSE IF(@Condition = 'GET_DATE_RANGE_FOR_REPORTS')
	BEGIN
		SELECT @ReturnValue = Parameter_Value FROM PARAMETER_MST (Nolock) where PARAMETER_C = 'Assline' AND PARAMETER_C1 = 'Dashboad_Report' AND PARAMETER_C2 = 'Max_Date_Differece' AND wh_Code = @ProfitCenterCode
		
		IF ISNULL(@ReturnValue,0) = 0
			SET @ReturnValue = 30
		
		SET @ReturnInt = 1
	END
	ELSE IF(@Condition = 'MANUAL_BARCODE_HISTORY')
	BEGIN
		--SELECT  AMPL.ProfitCenterCode,AMPL.LineCode,AMPL.Barcode,AMPL.DateCode,AMPL.PartNo,AMPL.Timestamp,AMPD.REASON,AMPL.SerialNo 
		--FROM Assy_Manual_Printed_Barcode (nolock) AMPL
		--INNER JOIN Assy_Manual_Printed_Barcode_Dtl (nolock)AMPD ON  AMPL.datecode =AMPD.datecode AND AMPL.SerialNo BETWEEN AMPD.FromSerialNo and AMPD.ToSerialNo
		--AND AMPL.PartNo=AMPD.PartNo AND AMPL.LineCode=AMPD.LineCode AND AMPL.ProfitCenterCode=AMPD.ProfitCenterCode
		--WHERE AMPL.TimeStamp between case when (@isDateCodeFilter=1) then AMPL.TimeStamp else @FromDate end
		--							    and case when (@isDateCodeFilter=1) then AMPL.TimeStamp else @ToDate end
		--			AND AMPL.DateCode = case when @isDateCodeFilter = 1 then @DateCode else AMPL.DateCode end 
		--AND AMPL.LineCode=@LineCode AND AMPL.ProfitCenterCode=@ProfitCentercode and AMPL.PartNo like '%'+@Partno+'%'
		
		SELECT AMPD.ProfitCenterCode,AMPD.LineCode,AMPD.DateCode,AMPD.PartNo,AMPD.NoOfPrintedLbl,AMPD.FromSerialNo,
		AMPD.ToSerialNo,AMPD.UserID,AMPD.Timestamp,AMPD.Reason 
		FROM Assy_Manual_Printed_Barcode_Dtl AMPD
		WHERE AMPD.TimeStamp between case when (@isDateCodeFilter=1) then AMPD.TimeStamp else @FromDate end
								 and case when (@isDateCodeFilter=1) then AMPD.TimeStamp else @ToDate end
				 AND AMPD.DateCode = case when @isDateCodeFilter = 1 then @DateCode else AMPD.DateCode end 
		AND AMPD.LineCode=@LineCode AND AMPD.ProfitCenterCode=@ProfitCentercode and AMPD.PartNo =isNull(nullif(@Partno,''),AMPD.PartNo)
		SET @RETURNVALUE='SUCCESS'
		SET @RETURNINT=0
		RETURN
	END
	ELSE IF(@Condition = 'MANUAL_BARCODE_REPRINT_HISTORY')
	BEGIN
		SELECT ALMR.ProfitCenterCode,ALMR.LineCode,ALMR.DateCode,ALMR.Barcode,ALMR.PartNo
		,ALMR.Remarks,ALMR.CreatedBy,ALMR.CreatedOn
		FROM Assy_LineAssyManualRePrint(NOLOCK) ALMR
		WHERE ALMR.CreatedOn between case when (@isDateCodeFilter=1) then ALMR.CreatedOn else @FromDate end
								 and case when (@isDateCodeFilter=1) then ALMR.CreatedOn else @ToDate end
				 AND ALMR.DateCode = case when @isDateCodeFilter = 1 then @DateCode else ALMR.DateCode end 
		AND ALMR.LineCode=@LineCode AND ALMR.ProfitCenterCode=@ProfitCentercode AND ALMR.PartNo =isNull(nullif(@Partno,''),ALMR.PartNo)
		AND ALMR.PrintType='MBR'
		--MODIFICATION BY AV ON 20170426
		SET @RETURNVALUE='SUCCESS'
		SET @RETURNINT=0
		RETURN
	END
	ELSE IF(@Condition = 'Packaging_History')
	BEGIN
		SELECT * INTO #SkidBarcodeInfo 
		FROM SkidBarcodeInfo(nolock)
		WHERE SkidBarcodePrintedTimestamp between 
		case when (@isDateCodeFilter=1) then SkidBarcodePrintedTimestamp else @FromDate end and 
		case when (@isDateCodeFilter=1) then SkidBarcodePrintedTimestamp else @ToDate end AND 
		DATECODE = case when @isDateCodeFilter = 1 then @DateCode else DATECODE end  
		AND WH_CODE=@ProfitCentercode and isnull(pkg_ts_serial,'')<>''

		SELECT DISTINCT(Info.SkidBarcodeInfoID),
		info.SkidBarcode,
		PPD.CUSTOMER_PART_NO as CustPartNo,
		PPD.PART_NUMBER as PartNumber,
		pmst.product_nm as PartDescription,
		PPD.MODEL as MODEL,
		PPD.CUSTOMER_CD CustomerCode,
		Info.CountryCode,
		INFO.pkg_ts_serial As SerialNo,
		Info.CUST_SERIAL_NO AS CustSerialNo,
		Info.CUST_SERIAL_QTY As CustSerialQty,
		info.LotSize as Lot_Qty,
		PPD.LOT_QTY as StdPackSize,
		PPD.DISPATCH_TYPE as DISPATCH_TYPE,
		Info.SkidBarcodePrintedTimestamp AS ENT_STAMP,
		Info.USERID,
		Info.DateCode,
		isnull(Info.Pallet_No,'') As Pallet_No
		,isnull(Info.PalletSize,0) as BOXES_PER_PALLET,
		 case  when info.pkg_ts_serial= detail.PartBarcode then 'MANUAL'
		else 'PrintScan' end AS ScanType 
		FROM #SkidBarcodeInfo info (NOLOCK)                                         
		INNER JOIN SkidBarcodeDetail detail (NOLOCK) ON info.SkidBarcodeInfoID=detail.SkidBarcodeInfoID
		INNER JOIN PKG_PART_MAPPING PPD (NOLOCK) ON info.PartCustMapID=PPD.PKG_DEF_ID
		INNER JOIN PRODUCT_MASTER pmst (NOLOCK) ON PPD.PART_NUMBER = pmst.sews_part_no AND PPD.WH_CODE = @ProfitCentercode
		AND pmst.warehouse_cd = @ProfitCentercode
		ORDER BY info.SkidBarcodeInfoID

		SET @RETURNVALUE='SUCCESS'
		SET @RETURNINT=0
		RETURN

	END
	ELSE IF(@Condition = 'Packaging_Details')
	BEGIN
		SELECT WH_CODE,SkidBarcodeInfoID ,PartBarcode,ScanTimeStamp,LocationInSkid,Layer,Line_No,UserId,StationCode 
		FROM SkidBarcodeDetail(nolock) where SkidBarcodeInfoID=@SkidBarcode and WH_CODE=@ProfitCentercode
		Order By LocationInSkid

		SET @RETURNVALUE='SUCCESS'
		SET @RETURNINT=0
		RETURN
	END
	ELSE IF(@Condition = 'Hold_Unhold')
	BEGIN
		--SELECT * INTO #Hold_Unhold 
		--FROM TRANS_LOG(nolock) 
		--WHERE WH_CODE=@ProfitCentercode AND PROGRAM_ID='HOLD-UNHOLD' AND ENT_STAMP BETWEEN @FromDate AND @ToDate
		
		--SELECT  HU.WH_CODE , HU.Serial_No,HU.SERIAL_QTY,P.SEWS_PART_NO ,HU.ORDER_NO AS [STATUS],
		--HU.ENT_STAMP AS [DATE], HU.ENT_BY AS [USER]
		--FROM #Hold_Unhold HU
		--INNER JOIN PRODUCT_MASTER(nolock) P ON HU.ITEM_NO = P.ITEM_NO and HU.WH_CODE=P.warehouse_cd
		--WHERE P.warehouse_cd=@ProfitCentercode and P.SEWS_PART_NO like '%'+@Partno +'%'
		--ORDER BY HU.SERIAL_NO,HU.ENT_STAMP
		SELECT ProfitCenterCode,SerialNo,PartNo,Qty,SkidLocation,UserId,EntTimeStamp,Remark,IsMailTimeStamp,CASE WHEN IsHold=0 THEN 'UnHold' ELSE 'Hold' End HoldDetails   
		FROM Skid_Hold_UnHold_Mail 
		WHERE ProfitCenterCode = @ProfitCentercode and EntTimeStamp BETWEEN @FromDate AND @ToDate
		ORDER BY EntTimeStamp Desc

		
		SET @RETURNVALUE='SUCCESS'
		SET @RETURNINT=0
		RETURN
	END

	IF EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID('Temp_Tags_Assy_Proc_Traceability_Analysis') AND type in (N'U'))
	BEGIN
		DROP TABLE Temp_Tags_Assy_Proc_Traceability_Analysis
	END
	END TRY
	 BEGIN catch
		SET @ReturnValue =	CAST(ERROR_NUMBER() as varchar(5)) + '|' + 
			CAST(ERROR_SEVERITY()as varchar(5)) + '|' + 
			CAST(ERROR_STATE() as varchar(5)) + '|' + 
			CAST(ERROR_PROCEDURE() as varchar(200)) + '|' + 
			CAST(ERROR_LINE() as varchar(5)) + '|' + 
			CAST(ERROR_MESSAGE() as varchar(1500))
			RAISERROR (@ReturnValue,16,1)						
		   SET @ReturnInt = 2
	END CATCH
END







GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_UpdatePokaYokeStatus]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

CREATE PROC [dbo].[Assy_Proc_UpdatePokaYokeStatus]
(
@CONDITION VARCHAR(60),
@LINECODE VARCHAR(20)=NULL,
@OPERATIONCODE VARCHAR(20)=NULL,
@MACHINECODE VARCHAR(20)=NULL,
@PROFITCENTERCODE VARCHAR(20)=NULL,
@PLCRESULT VARCHAR(10)=NULL,
@BARCODE VARCHAR(100)=NULL,
@USERID VARCHAR(20)=NULL,
@ISTestCompleted varchar(10)='NO' output,
@ISByPassPokaYoke bit=0,
@ISFaultBarcodeScanned bit=0,
@Allow2Parts bit=0
)
AS
BEGIN
	/****************************************************************************
	AUTHOR:<RAVISHANKAR MISHRA>
	CREATED ON:<10-12-2015>
	Modified By:<Rashid Siddiqui>
	Modified ON:<01-August-2016>	 
	Description: - Station Index Capture in ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE For twin station PokaYoke.
	Modified By:<RAVISHANKAR MISHRA>
	Modified ON:<07-09-17>	 
	Description: - For running 2 parts at a time, get current date code instead of reading date code from  assy_runningpart table
	,changed in 'INSERT_BYPASS_POKA_YOKE_IN_MAIN_SERVER' and 'UPDATE_POKA_YOKE_RESULT' blocks.
		
	declare @ISTestCompleted1 varchar(20)
	EXEC [Assy_Proc_UpdatePokaYokeStatus] @CONDITION='UPDATE_POKA_YOKE_COMPELETE_FOR_FAULT_PART',  @LINECODE='M03',@PROFITCENTERCODE='0021',@MACHINECODE='MCRT'
	,@OPERATIONCODE='OCRTLH',@BARCODE='29066278PKYKrt066278M03',@ISTestCompleted=@ISTestCompleted1 out
	select  @ISTestCompleted1
	EXEC [Assy_Proc_UpdatePokaYokeStatus] @CONDITION='UPDATE_POKA_YOKE_RESULT',  @LINECODE='M07',@OPERATIONCODE='OCMSLH',@MACHINECODE='MCMS',@PROFITCENTERCODE='0021'
	,@PLCRESULT='PASS'
	,@BARCODE='29066617PKYKMC000003M07'
	,@USERID ='RAVI1',@Allow2Parts=1	
	EXEC [Assy_Proc_UpdatePokaYokeStatus] @CONDITION='INSERT_BYPASS_POKA_YOKE_IN_MAIN_SERVER',  @LINECODE='M08',@PROFITCENTERCODE='0021',@Allow2Parts=1	
	exec Assy_Proc_UpdatePokaYokeStatus @CONDITION='UPDATE_POKAYOKE_COMPLETED_FOR_NA_PART',@LINECODE='M08',@PROFITCENTERCODE='0021',@ISByPassPokaYoke=1
	exec Assy_Proc_UpdatePokaYokeStatus @CONDITION='UPDATE_CYCLE_STARTED_FROM_PLC_PROC',@LINECODE='M07',@MACHINECODE='MCMS'
	,@OPERATIONCODE='OCMSLH',@BARCODE='29066617PKYKMC000003M07'
	*********************************************************************************/
	SET NOCOUNT ON
	DECLARE @PRODUCTIONSTARTDATETIME DATETIME
	DECLARE @RUNNINGPARTNO VARCHAR(30)
	DECLARE @PART_FIXTUREGROUPTYPE VARCHAR(30)
	DECLARE @EXECQUERY AS NVARCHAR(MAX),@LINKSERVERNAME VARCHAR(200) ,@RealTimeDateCode char(4)=''
	--DECLARE @FAULTRESULTCOUNT INT
	--DECLARE @PASSFAILRESULTCOUNT INT
	set @ISTestCompleted='NO'
	--ADDED BY RAVI ON 22/12/2015 FOR THE PURPOSE OF SENDING MAIL FOR DE ACTIVE PART IN POKA YOKE DEFINITION
    	SELECT TOP 1 @PRODUCTIONSTARTDATETIME=CREATEDDATE,@RUNNINGPARTNO=ASSY_PARTNO FROM ASSY_RUNNINGPART(NOLOCK) WHERE LINECODE=@LINECODE	
		AND ASSY_MODE IN ('Production','Rework') ORDER BY CREATEDDATE DESC
		
		IF @RUNNINGPARTNO=''
		begin			
			set @ISTestCompleted='NA'								
			RETURN		
		end					
		SELECT TOP 1 @PART_FIXTUREGROUPTYPE=ISNULL(PART_FIXTUREGROUPTYPE,'') FROM ROUTINGCONFIGPARTWISE WITH (NOLOCK)
		WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND PARTNO=@RUNNINGPARTNO AND 
			MACHINECODE=DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE)

		IF @PART_FIXTUREGROUPTYPE='' and  @ISByPassPokaYoke=0
		BEGIN									
				SET @ISTESTCOMPLETED='NA'								
				RETURN		
		END

			IF @CONDITION='INSERT_BYPASS_POKA_YOKE_IN_MAIN_SERVER'
			BEGIN
			        --Changed by Ravi on 07-09-17 to store current date code into ASSY_POKAYOKE_STATUS table
					if isnull(@Allow2Parts,0)=1
					begin
							exec assy_PROC_DateCode @ProfitCenterCode=@ProfitCenterCode,@ReturnValue= @RealTimeDateCode output     
					end	

					SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL  WITH (NOLOCK) 
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE 
					SET @EXECQUERY='INSERT INTO '+@LINKSERVERNAME+'.DBO.[ASSY_POKAYOKE_STATUS]
					(
						[PROFITCENTERCODE],[LINECODE],[MACHINECODE],[OPERATIONCODE]
						,[BARCODE],[PARTNO],[DATECODE],[EXPRESULT],[ACTRESULT]
						,[USERID],[ISMAILSENT],[MAILSENTTIMESTAMP],[SCANTIMESTAMP]
						,[RESULTTIMESTAMP],ISACTIVE,DESCRIPTION
					)
					SELECT PK.PROFITCENTERCODE,PK.LINECODE,PK.MACHINECODE,PK.OPERATIONCODE
						,PK.BARCODE,pk.PartNo,PK.Datecode,PK.EXPRESULT,PK.ACTRESULT
						,PK.USERID,PK.ISMAILSENT,PK.MAILSENTTIMESTAMP,PK.SCANTIMESTAMP
						,PK.RESULTTIMESTAMP,ISNULL(PK.ISACTIVE,0)ISACTIVE,PK.DESCRIPTION FROM  ASSY_POKAYOKE_STATUS PK WITH(NOLOCK) 				
						WHERE PK.PROFITCENTERCODE='''+@PROFITCENTERCODE+''' 
						AND PK.LINECODE ='''+@LINECODE+''' AND ISNULL(PK.ISMAILSENT,0)=0';		
					EXEC(@EXECQUERY)

					UPDATE ASSY_POKAYOKE_STATUS SET ISMAILSENT=1,MAILSENTTIMESTAMP=GETDATE() WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE 
					AND ISNULL(ISMAILSENT,0)=0		
	   				UPDATE ASSY_SCAN_OK SET	BARCODE='' WHERE LINECODE=@LINECODE
					
					SET @EXECQUERY=''
					SET @EXECQUERY='INSERT INTO '+@LINKSERVERNAME+'.DBO.[ASSY_POKAYOKE_STATUS]		
					(
							PROFITCENTERCODE,LINECODE,MACHINECODE,BARCODE,PARTNO
						   ,USERID,ISACTIVE,RESULTTIMESTAMP,DESCRIPTION,DATECODE
					)
						SELECT  PK.PROFITCENTERCODE, PK.LINECODE, PK.MACHINECODE, PK.BARCODE, RP.ASSY_PARTNO,
						PK.ENTBY,
						ISNULL(PK.ISACTIVE,''0'')ISACTIVE,GETDATE() AS RESULTTIMESTAMP,PK.DESCRIPTION,
						(case when isnull('+convert(nvarchar,@Allow2Parts)+',0)=1 then ' + ''''+ isnull(@RealTimeDateCode,'''') +'''' +' else RP.DATECODE end) as DATECODE FROM
						ASSY_POKAYOKE PK WITH(NOLOCK)	INNER JOIN ASSY_RUNNINGPART RP WITH(NOLOCK) ON PK.PROFITCENTERCODE =RP.PROFITCENTERCODE 
						AND PK.LINECODE=RP.LINECODE 	
						WHERE PK.PROFITCENTERCODE='''+@PROFITCENTERCODE+''' AND  PK.LINECODE ='''+@LINECODE+'''  AND ISNULL(PK.ISACTIVE,0)=0
						and pk.PARTNUMBER IN
						(
							SELECT DISTINCT PARTNO FROM ROUTINGCONFIGPARTWISE(NOLOCK) 
							WHERE PROFITCENTERCODE='''+@PROFITCENTERCODE+''' AND PART_FIXTUREGROUPTYPE='''+@PART_FIXTUREGROUPTYPE+'''
						)

						ORDER BY PK.PROFITCENTERCODE,PK.LINECODE,PK.MACHINECODE,PK.BARCODE'			
					EXEC(@EXECQUERY)
					print @EXECQUERY
					UPDATE Assy_Scan_OK_History_For_PokaYoke SET BARCODE='',ISCYCLESTARTED=0 WHERE LINECODE=@LINECODE
					--Added by Ravi on 27-Feb-2016
					------------------update Assy_PokaYoke_Completed_Dtl table for checking whether Final viewing testing has been completed or not--------------------------
					declare @ISPartTestedAfterPKYK int =0
					declare @Datecode char(4),@PartNo varchar(60),@CreatedDate datetime					
					if exists
					(
					  select 1 from linemst with(nolock) where profitcentercode=@profitcentercode and linecode=@linecode and isnull(isPokaYokeMandatory,0)=1
					)
					begin		 
							select top 1  @Datecode=Datecode,@PartNo=Assy_PartNo,@CreatedDate=CreatedDate from assy_runningpart with (nolock) 
							where ProfitCenterCode=@profitcentercode  and LineCode=@linecode order by CreatedDate desc

							--delete Assy_PokaYoke_Completed_Dtl if datecode is old
								if exists(select 1 from Assy_PokaYoke_Completed_Dtl with(nolock) where Datecode!=@Datecode)
									truncate table Assy_PokaYoke_Completed_Dtl 

							select @ISPartTestedAfterPKYK=isnull(count(isnull (barcode,0)),0) from assy_lineassystatus with(nolock) where ProfitCenterCode=@profitcentercode 
							and linecode=@linecode
							and Datecode=@Datecode and MachineCode=dbo.Assy_FN_Get_FinalViewing_MachineCode_From_LineCode(@profitcentercode,@linecode)
							and PartNo=@PartNo and ScanTimestamp>=@CreatedDate and isnull(IsTallyChartApproved,0)=0 and isnull(status,'')!=''

							if(isnull(@ISPartTestedAfterPKYK,0)>0)
							begin
								IF NOT EXISTS (SELECT 1 FROM Assy_PokaYoke_Completed_Dtl WHERE ProfitCenterCode=@profitcentercode 
										and linecode=@linecode	and Datecode=@Datecode and PartNo=@PartNo)
								BEGIN
									insert into Assy_PokaYoke_Completed_Dtl
									(
									ProfitCenterCode,LineCode,Datecode,PartNo,Is_PKYK_Completed,Is_Fv_Completed,Timestamp
									)
									select @profitcentercode,@LineCode,@Datecode,@PartNo,1, (case when @ISPartTestedAfterPKYK=0 then 0 else 1 end)Is_PKYK_Completed,getdate()
								END
								ELSE
								BEGIN
									UPDATE Assy_PokaYoke_Completed_Dtl SET Timestamp = GETDATE() WHERE ProfitCenterCode=@profitcentercode 
										and linecode=@linecode	and Datecode=@Datecode and PartNo=@PartNo
								END
							end
					end
					----------------------------------------------------------------------------------------------------------------------------------------
					RETURN
			END					
		else IF @CONDITION='UPDATE_POKA_YOKE_COMPELETE_FOR_FAULT_PART'
	      BEGIN			

		           update assy_lineassyStatus_running set Status='FT',RESULTTIMESTAMP =GETDATE() where ProfitCenterCode=@PROFITCENTERCODE and linecode=@LINECODE 
					and MachineCode=@MACHINECODE and OperationCode=@OPERATIONCODE and barcode=@BARCODE and isnull(status,'')!='PS'
					--INSERT DATA INTO ASSY_POKAYOKE_STATUS FOR THE PURPOSE OF SENDING MAIL
					INSERT INTO ASSY_POKAYOKE_STATUS
					(
						PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,BARCODE,PARTNO,DATECODE
						,ACTRESULT,USERID,SCANTIMESTAMP,RESULTTIMESTAMP
						,EXPRESULT,ISACTIVE,ISMAILSENT,DESCRIPTION
					)
					 SELECT  ASSY.PROFITCENTERCODE, ASSY.LINECODE, ASSY.MACHINECODE, ASSY.OPERATIONCODE, ASSY.BARCODE,RP.ASSY_PARTNO,RP.DATECODE
					 ,(CASE WHEN ISNULL( ASSY.STATUS,'')='PS' THEN 'PASS'  WHEN ISNULL( ASSY.STATUS,'')='FL' THEN 'FAIL' 
					  ELSE 'FAULT' END)AS ACTRESULT,ASSY.USERID, ASSY.SCANTIMESTAMP, ASSY.RESULTTIMESTAMP
					 ,ISNULL(PK.EXPRESULT,'') EXPRESULT,ISNULL(PK.ISACTIVE,'0')ISACTIVE	,0,PK.DESCRIPTION	 
					FROM  ASSY_LINEASSYSTATUS_RUNNING ASSY WITH (NOLOCK)  
					INNER JOIN ASSY_POKAYOKE PK WITH(NOLOCK) ON 
					  ASSY.PROFITCENTERCODE=PK.PROFITCENTERCODE AND ASSY.LINECODE =PK.LINECODE AND ASSY.MACHINECODE=PK.MACHINECODE 
						AND ASSY.BARCODE =PK.BARCODE	
					INNER JOIN ASSY_RUNNINGPART RP WITH(NOLOCK) ON PK.PROFITCENTERCODE =RP.PROFITCENTERCODE AND PK.LINECODE=RP.LINECODE		
					WHERE ASSY.PROFITCENTERCODE=@PROFITCENTERCODE AND  ASSY.LINECODE =@LINECODE AND  ASSY.MACHINECODE=@MACHINECODE AND  ASSY.OPERATIONCODE=@OPERATIONCODE
					AND  ASSY.BARCODE =@BARCODE  AND  ASSY.ACTIVE =0  AND ISNULL(PK.ISACTIVE,0)=1
					AND ISNULL( ASSY.STATUS,'')<>'' 
					ORDER BY RESULTTIMESTAMP  		
				
					UPDATE ASSY_LINEASSYSTATUS_RUNNING SET ACTIVE=1 WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE AND MACHINECODE=@MACHINECODE 
					AND OPERATIONCODE=@OPERATIONCODE AND BARCODE =@BARCODE AND ISNULL(ACTIVE,0) =0  AND ISNULL(STATUS,'')<>'' 	
					
					IF NOT EXISTS
					(
							SELECT  top 1 1 FROM ASSY_POKAYOKE(NOLOCK) A left outer join assy_LINEASSYSTATUS_RUNNING(NOLOCK) B
							ON  A.PROFITCENTERCODE=B.PROFITCENTERCODE AND A.LINECODE=B.LINECODE AND A.MACHINECODE=B.MACHINECODE AND A.BARCODE=B.BARCODE	
								AND B.OPERATIONCODE=@OPERATIONCODE 	
							INNER JOIN ROUTINGCONFIGPARTWISE PR WITH (NOLOCK) ON							 
								A.PROFITCENTERCODE=PR.PROFITCENTERCODE AND A.MACHINECODE=PR.MACHINECODE AND A.PARTNUMBER=PR.PARTNO
								and PR.PART_FIXTUREGROUPTYPE=@PART_FIXTUREGROUPTYPE	and PR.OperationCode= @OPERATIONCODE	
							WHERE A.PROFITCENTERCODE=@PROFITCENTERCODE AND A.LINECODE=@LINECODE AND A.MACHINECODE=@MACHINECODE 											
							AND ISNULL(B.STATUS,'')=''  AND ISNULL(A.ISACTIVE,0)=1 	and isnull(PR.Traceability,0)=1									
					)
					BEGIN
							UPDATE ASSY_SCAN_OK SET ISPOKAYOKECOMPLETED=1,Barcode='' WHERE LINECODE=@LINECODE AND MACHINECODE=@MACHINECODE
							AND OPERATIONCODE=@OPERATIONCODE
							UPDATE ASSY_RESULT	SET	STATIONCODE='PKYK',Barcode=@BARCODE	WHERE LINECODE=@LINECODE AND OPERATIONCODE=@OPERATIONCODE	
							set @ISTestCompleted='YES'										
							UPDATE Assy_Scan_OK_History_For_PokaYoke SET BARCODE='',ISCYCLESTARTED=0 
							WHERE LINECODE=@LINECODE AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE	

							exec Assy_Proc_PokaYoke_Last_Tested_Part @CONDITION='INSERT',@ProfitCenterCode=@ProfitCenterCode,@LineCode=@LINECODE
							,@MachineCode=@MACHINECODE,@OperationCode=@OPERATIONCODE
					END						
				
	END
	    ELSE IF @CONDITION='UPDATE_POKA_YOKE_RESULT'
		   BEGIN
				
				--Changed by Ravi on 07-09-17 to store current date code into ASSY_POKAYOKE_STATUS table
				if isnull(@Allow2Parts,0)=1
				begin
						exec assy_PROC_DateCode @ProfitCenterCode=@ProfitCenterCode,@ReturnValue= @RealTimeDateCode output     
				end	

				--CHECK PLC RESULT AND POKA YOKE EXPECTED RESULT IS NOT SAME
				IF EXISTS
				(
						SELECT 1 FROM ASSY_POKAYOKE (NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE AND MACHINECODE=@MACHINECODE
						AND BARCODE =@BARCODE AND ISNULL(EXPRESULT,'')<> ISNULL(@PLCRESULT,'') AND 
						ISNULL(RESVERREQUIRED,0)=1 AND ISNULL(ISACTIVE,0)=1 and (@ISFaultBarcodeScanned=0)
				)
				BEGIN
				    
						DELETE FROM ASSY_POKAYOKE_CURRENT_RESULT WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE AND MACHINECODE=@MACHINECODE 
						AND OPERATIONCODE =@OPERATIONCODE
						INSERT INTO ASSY_POKAYOKE_CURRENT_RESULT
						(
						 PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,BARCODE,ACTRESULT,EXPRESULT,USERID,RESULTTIMESTAMP,ISPROCESSED
						)
						SELECT @PROFITCENTERCODE,@LINECODE,@MACHINECODE,@OPERATIONCODE,@BARCODE,@PLCRESULT,
						(
						 SELECT ISNULL(EXPRESULT,'') EXPRESULT FROM ASSY_POKAYOKE (NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE 
						 AND MACHINECODE=@MACHINECODE
						 AND BARCODE =@BARCODE AND  ISNULL(ISACTIVE,0)=1
						)
						,@USERID,GETDATE(),1

						set @ISTestCompleted='NA'
						RETURN
				END
				--UPDATE RESULT FOR POKA YOKE INTO ASSY_LINEASSYSTATUS_RUNNING TABLE
				UPDATE ASSY_LINEASSYSTATUS_RUNNING SET RESULTTIMESTAMP =GETDATE(),STATUS=(CASE WHEN ISNULL(@PLCRESULT,'')='PASS' THEN 'PS'   
				WHEN ISNULL(@PLCRESULT,'')='FAIL' then 'FL' ELSE 'FT' END) 
				WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE 
				AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE AND BARCODE =@BARCODE
				AND SCANTIMESTAMP=(SELECT TOP 1 SCANTIMESTAMP FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK)  WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE 
				AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE AND BARCODE =@BARCODE ORDER BY SCANTIMESTAMP DESC)

			--INSERT DATA INTO ASSY_POKAYOKE_STATUS FOR THE PURPOSE OF SENDING MAIL
				INSERT INTO ASSY_POKAYOKE_STATUS
				(
					PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,BARCODE,PARTNO,DATECODE
					,ACTRESULT,USERID,SCANTIMESTAMP,RESULTTIMESTAMP
					,EXPRESULT,ISACTIVE,ISMAILSENT,DESCRIPTION
				)
				 SELECT  ASSY.PROFITCENTERCODE, ASSY.LINECODE, ASSY.MACHINECODE, ASSY.OPERATIONCODE, ASSY.BARCODE,RP.ASSY_PARTNO
				 ,(case when isnull(@Allow2Parts,0)=1 then @RealTimeDateCode else RP.DATECODE end)DATECODE
				 ,(CASE WHEN ISNULL( ASSY.STATUS,'')='PS' THEN 'PASS'  WHEN ISNULL( ASSY.STATUS,'')='FL' THEN 'FAIL' 
				  ELSE 'FAULT' END)AS ACTRESULT,ASSY.USERID, ASSY.SCANTIMESTAMP, ASSY.RESULTTIMESTAMP
				 ,ISNULL(PK.EXPRESULT,'') EXPRESULT,ISNULL(PK.ISACTIVE,'0')ISACTIVE	,0,PK.DESCRIPTION	 
				FROM  ASSY_LINEASSYSTATUS_RUNNING ASSY WITH (NOLOCK)  
				INNER JOIN ASSY_POKAYOKE PK WITH(NOLOCK) ON 
				  ASSY.PROFITCENTERCODE=PK.PROFITCENTERCODE AND ASSY.LINECODE =PK.LINECODE AND ASSY.MACHINECODE=PK.MACHINECODE 
					AND ASSY.BARCODE =PK.BARCODE	
				INNER JOIN ASSY_RUNNINGPART RP WITH(NOLOCK) ON PK.PROFITCENTERCODE =RP.PROFITCENTERCODE AND PK.LINECODE=RP.LINECODE		
				WHERE ASSY.PROFITCENTERCODE=@PROFITCENTERCODE AND  ASSY.LINECODE =@LINECODE AND  ASSY.MACHINECODE=@MACHINECODE AND  ASSY.OPERATIONCODE=@OPERATIONCODE
				AND  ASSY.BARCODE =@BARCODE  AND  ASSY.ACTIVE =0  AND ISNULL(PK.ISACTIVE,0)=1
				AND ISNULL( ASSY.STATUS,'')<>'' 
				ORDER BY RESULTTIMESTAMP  		
				
				UPDATE ASSY_LINEASSYSTATUS_RUNNING SET ACTIVE=1 WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE AND MACHINECODE=@MACHINECODE 
				AND OPERATIONCODE=@OPERATIONCODE AND BARCODE =@BARCODE AND ISNULL(ACTIVE,0) =0  AND ISNULL(STATUS,'')<>'' 									
						
				IF NOT EXISTS
				(
				
							SELECT  top 1 1 FROM ASSY_POKAYOKE(NOLOCK) A left outer join assy_LINEASSYSTATUS_RUNNING(NOLOCK) B
							ON  A.PROFITCENTERCODE=B.PROFITCENTERCODE AND A.LINECODE=B.LINECODE AND A.MACHINECODE=B.MACHINECODE AND A.BARCODE=B.BARCODE	
								AND B.OPERATIONCODE=@OPERATIONCODE 	
							INNER JOIN ROUTINGCONFIGPARTWISE PR WITH (NOLOCK) ON							 
								A.PROFITCENTERCODE=PR.PROFITCENTERCODE AND A.MACHINECODE=PR.MACHINECODE AND A.PARTNUMBER=PR.PARTNO
								and PR.PART_FIXTUREGROUPTYPE=@PART_FIXTUREGROUPTYPE	and PR.OperationCode= @OPERATIONCODE	
							WHERE A.PROFITCENTERCODE=@PROFITCENTERCODE AND A.LINECODE=@LINECODE AND A.MACHINECODE=@MACHINECODE 											
							AND ISNULL(B.STATUS,'')=''  AND ISNULL(A.ISACTIVE,0)=1 	and isnull(PR.Traceability,0)=1											
				)
				BEGIN					
								UPDATE ASSY_SCAN_OK SET ISPOKAYOKECOMPLETED=1,Barcode='' WHERE LINECODE=@LINECODE AND MACHINECODE=@MACHINECODE
								AND OPERATIONCODE=@OPERATIONCODE
								UPDATE ASSY_RESULT	SET	STATIONCODE='PKYK',Barcode=@BARCODE	WHERE LINECODE=@LINECODE AND OPERATIONCODE=@OPERATIONCODE		
								set @ISTestCompleted='YES'	
								UPDATE Assy_Scan_OK_History_For_PokaYoke SET BARCODE='',ISCYCLESTARTED=0 
								WHERE LINECODE=@LINECODE AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE	
																
								exec Assy_Proc_PokaYoke_Last_Tested_Part @CONDITION='INSERT',@ProfitCenterCode=@ProfitCenterCode,@LineCode=@LINECODE
								,@MachineCode=@MACHINECODE,@OperationCode=@OPERATIONCODE
				END				
							    	
				
		END
		--Update Poka yoke completed for a particular part ,for that Poka yoke master has not been defined
		ELSE IF @CONDITION='UPDATE_POKAYOKE_COMPLETED_FOR_NA_PART'
		BEGIN
				DECLARE @TMPALLACTIVERECORDS  TABLE
				(
				PROFITCENTERCODE VARCHAR(20),
				LINECODE VARCHAR(20),
				MACHINECODE VARCHAR(20),
				OPERATIONCODE VARCHAR(20),
				PARTNO VARCHAR(60),
				OPERATIONSEQNO INT 
				)				
				IF ISNULL(@PART_FIXTUREGROUPTYPE,'')=''
				BEGIN		
					
						INSERT INTO @TMPALLACTIVERECORDS(PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,PARTNO,OPERATIONSEQNO)	
						SELECT L.PROFITCENTERCODE,L.LINECODE,RP.MACHINECODE,RP.OPERATIONCODE,RP.PARTNO,RL.OPERATIONSEQNO  FROM LINEMST L  WITH (NOLOCK) 
						INNER JOIN ROUTINGCONFIGLINEWISE RL WITH(NOLOCK)
							ON L.PROFITCENTERCODE = RL.PROFITCENTERCODE AND L.LINECODE=RL.LINECODE 
						INNER JOIN ROUTINGCONFIGPARTWISE  RP WITH(NOLOCK)
							ON RL.PROFITCENTERCODE =RP.PROFITCENTERCODE AND RL.MACHINECODE =RP.MACHINECODE AND RL.OPERATIONCODE =RP.OPERATIONCODE
						WHERE L.PROFITCENTERCODE=@PROFITCENTERCODE
						AND L.LINECODE=@LINECODE AND ISNULL(L.ISACTIVE,0)=1 AND ISNULL(L.ISPOKAYOKEMANDATORY,0)=1		
						AND ISNULL(RL.POKA_YOKE_ALLOWED,0) =1 AND ISNULL(RL.TRACEABILITY,0) =1 AND ISNULL(RP.TRACEABILITY,0) =1
						AND RP.PartNo=@RUNNINGPARTNO
						ORDER BY RP.PARTNO,RL.OPERATIONSEQNO
				END
				ELSE
					BEGIN						
						INSERT INTO @TMPALLACTIVERECORDS(PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,PARTNO,OPERATIONSEQNO)
						SELECT L.PROFITCENTERCODE,L.LINECODE,RP.MACHINECODE,RP.OPERATIONCODE,RP.PARTNO,RL.OPERATIONSEQNO  FROM LINEMST L  WITH (NOLOCK) 
						INNER JOIN ROUTINGCONFIGLINEWISE RL WITH(NOLOCK)
							ON L.PROFITCENTERCODE = RL.PROFITCENTERCODE AND L.LINECODE=RL.LINECODE 
						INNER JOIN ROUTINGCONFIGPARTWISE  RP WITH(NOLOCK)
							ON RL.PROFITCENTERCODE =RP.PROFITCENTERCODE AND RL.MACHINECODE =RP.MACHINECODE AND RL.OPERATIONCODE =RP.OPERATIONCODE
						WHERE L.PROFITCENTERCODE=@PROFITCENTERCODE
						AND L.LINECODE=@LINECODE AND ISNULL(L.ISACTIVE,0)=1 AND ISNULL(L.ISPOKAYOKEMANDATORY,0)=1		
						AND ISNULL(RL.POKA_YOKE_ALLOWED,0) =1 AND ISNULL(RL.TRACEABILITY,0) =1 AND ISNULL(RP.TRACEABILITY,0) =1
						AND RP.PART_FIXTUREGROUPTYPE=@PART_FIXTUREGROUPTYPE
						ORDER BY RP.PARTNO,RL.OPERATIONSEQNO 

				   END
				--SELECT * FROM  @TMPALLACTIVERECORDS
				
				DECLARE @ALLACTIVEOPEARTIONCODE AS TABLE
				(
					ID INT IDENTITY(1,1),
					OPERATIONCODE VARCHAR(20),
					MACHINECODE VARCHAR(20)
				)
				INSERT INTO @ALLACTIVEOPEARTIONCODE(OPERATIONCODE,MACHINECODE)
				SELECT DISTINCT OPERATIONCODE,MACHINECODE FROM @TMPALLACTIVERECORDS 
				--SELECT * FROM @ALLACTIVEOPEARTIONCODE
				DECLARE @START INT=1
				DECLARE @END    INT
				SELECT @END =COUNT(ID) FROM @ALLACTIVEOPEARTIONCODE

				WHILE(@START<=@END)
				BEGIN
						SELECT @MACHINECODE=MACHINECODE,@OPERATIONCODE=OPERATIONCODE FROM @ALLACTIVEOPEARTIONCODE WHERE ID=@START
						IF  NOT EXISTS
						(
							 SELECT 1 FROM @TMPALLACTIVERECORDS T  JOIN ASSY_POKAYOKE P WITH (NOLOCK) 
							 ON T.PROFITCENTERCODE=P.PROFITCENTERCODE AND T.LINECODE =P.LINECODE AND T.MACHINECODE =P.MACHINECODE 
							 AND T.PARTNO =P.PARTNUMBER
							 AND P.ISACTIVE =1 
							 WHERE T.OPERATIONCODE =@OPERATIONCODE AND T.MACHINECODE =@MACHINECODE
			
						)
						BEGIN
								IF  EXISTS
								(
									SELECT DISTINCT 1 FROM ASSY_SCAN_OK(NOLOCK) WHERE LINECODE=@LINECODE 
									AND OPERATIONCODE=@OPERATIONCODE AND MACHINECODE=@MACHINECODE 
								)
								BEGIN
										UPDATE ASSY_SCAN_OK SET ISPOKAYOKECOMPLETED=1 WHERE LINECODE=@LINECODE AND OPERATIONCODE=@OPERATIONCODE AND MACHINECODE=@MACHINECODE	
										AND ISNULL(ISPOKAYOKECOMPLETED,0)=0											
								END
								ELSE
									BEGIN
										INSERT INTO ASSY_SCAN_OK(LINECODE,OPERATIONCODE,MACHINECODE,ISPOKAYOKECOMPLETED)
										SELECT @LINECODE,@OPERATIONCODE,@MACHINECODE,1											
									END
						END
						SET @START=@START+1
						--PRINT 'OC '+CONVERT(VARCHAR(20), @START)
				END
		END
		--Update Cycle Started from PLC procedure
		ELSE IF @CONDITION='UPDATE_CYCLE_STARTED_FROM_PLC_PROC'
		BEGIN
			IF CHARINDEX('PKYK',@BARCODE) = 0
				RETURN
			
			-- Added By Rashid For PokaYoke 29-July-2016 For twin Index
			Declare @ScannedStationIndex INT;
			SET @ScannedStationIndex = (SELECT dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
			
			IF(@ScannedStationIndex = -1)
			BEGIN
				IF EXISTS
				(	
					SELECT 1 FROM ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE WITH (NOLOCK) WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE 
						AND OPERATIONCODE = @OPERATIONCODE
				)
				BEGIN					
					UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE SET ISCYCLESTARTED = 1, BARCODE = @BARCODE, TIMESTAMP = GETDATE()
					WHERE  LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE
				END
				ELSE
				BEGIN					
						INSERT INTO ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE
						(
							LINECODE,
							MACHINECODE,
							OPERATIONCODE,
							ISCYCLESTARTED,
							BARCODE
						)
						SELECT @LINECODE,@MACHINECODE,@OPERATIONCODE,1,@BARCODE
				END
			END
			ELSE
			-- Added By Rashid For PokaYoke 01-August-2016 For twin Index
			BEGIN
				Declare @InsideStationIndex INT;
					IF(@ScannedStationIndex = 1)
						SET @InsideStationIndex = 1
					ELSE IF(@ScannedStationIndex = 2)
						SET @InsideStationIndex = 2
				IF EXISTS
				(	
					SELECT 1 FROM ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE WITH (NOLOCK) WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE 
						AND OPERATIONCODE = @OPERATIONCODE AND StationCode = @InsideStationIndex
				)
				BEGIN					
					UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE SET ISCYCLESTARTED = 1, BARCODE = @BARCODE, TIMESTAMP = GETDATE()
					WHERE  LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND StationCode = @InsideStationIndex
				END
				ELSE
				BEGIN					
					INSERT INTO ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE
					(
						LINECODE,
						MACHINECODE,
						OPERATIONCODE,
						ISCYCLESTARTED,
						BARCODE,
						StationCode
					)
					SELECT @LINECODE,@MACHINECODE,@OPERATIONCODE,1,@BARCODE,@InsideStationIndex
				END
			END
		END
END




GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_UpdatePokaYokeStatus_TEST]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
CREATE PROC [dbo].[Assy_Proc_UpdatePokaYokeStatus_TEST]
(
@CONDITION VARCHAR(60),
@LINECODE VARCHAR(20)=NULL,
@OPERATIONCODE VARCHAR(20)=NULL,
@MACHINECODE VARCHAR(20)=NULL,
@PROFITCENTERCODE VARCHAR(20)=NULL,
@PLCRESULT VARCHAR(10)=NULL,
@BARCODE VARCHAR(100)=NULL,
@USERID VARCHAR(20)=NULL,
@ISTestCompleted varchar(10)='NO' output,
@ISByPassPokaYoke bit=0,
@ISFaultBarcodeScanned bit=0
)
AS
BEGIN
     --AUTHOR:<RAVISHANKAR MISHRA>
	 --CREATED ON:<10-12-2015>
	  --Modified By:<Rashid Siddiqui>
	 --Modified ON:<01-August-2016>	 
	 /*Description: - Station Index Capture in ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE For twin station PokaYoke.*/

	
	--declare @ISTestCompleted1 varchar(20)
	--	EXEC [Assy_Proc_UpdatePokaYokeStatus] @CONDITION='UPDATE_POKA_YOKE_COMPELETE_FOR_FAULT_PART',  @LINECODE='M03',@PROFITCENTERCODE='0021',@MACHINECODE='MCRT'
	--	,@OPERATIONCODE='OCRTLH',@BARCODE='29066278PKYKrt066278M03',@ISTestCompleted=@ISTestCompleted1 out
	--	select  @ISTestCompleted1
		-- EXEC [Assy_Proc_UpdatePokaYokeStatus] @CONDITION='UPDATE_POKA_YOKE_RESULT',  @LINECODE='M07',@OPERATIONCODE='OCMSLH',@MACHINECODE='MCMS',@PROFITCENTERCODE='0021'
		--,@PLCRESULT='PASS'
		--,@BARCODE='29066617PKYKMC000003M07'
		--,@USERID ='RAVI1'
		--EXEC [Assy_Proc_UpdatePokaYokeStatus] @CONDITION='INSERT_BYPASS_POKA_YOKE_IN_MAIN_SERVER',  @LINECODE='M08',@PROFITCENTERCODE='0021'		
		--exec Assy_Proc_UpdatePokaYokeStatus @CONDITION='UPDATE_POKAYOKE_COMPLETED_FOR_NA_PART',@LINECODE='M08',@PROFITCENTERCODE='0021',@ISByPassPokaYoke=1
	 --   exec Assy_Proc_UpdatePokaYokeStatus @CONDITION='UPDATE_CYCLE_STARTED_FROM_PLC_PROC',@LINECODE='M07',@MACHINECODE='MCMS'
		--,@OPERATIONCODE='OCMSLH',@BARCODE='29066617PKYKMC000003M07'
	SET NOCOUNT ON
	DECLARE @PRODUCTIONSTARTDATETIME DATETIME
	DECLARE @RUNNINGPARTNO VARCHAR(30)
	DECLARE @PART_FIXTUREGROUPTYPE VARCHAR(30)
	DECLARE @EXECQUERY AS NVARCHAR(MAX),@LINKSERVERNAME VARCHAR(200) 
	--DECLARE @FAULTRESULTCOUNT INT
	--DECLARE @PASSFAILRESULTCOUNT INT
	set @ISTestCompleted='NO'
	--ADDED BY RAVI ON 22/12/2015 FOR THE PURPOSE OF SENDING MAIL FOR DE ACTIVE PART IN POKA YOKE DEFINITION
    	SELECT TOP 1 @PRODUCTIONSTARTDATETIME=CREATEDDATE,@RUNNINGPARTNO=ASSY_PARTNO FROM ASSY_RUNNINGPART(NOLOCK) WHERE LINECODE=@LINECODE	
		AND ASSY_MODE IN ('Production','Rework') ORDER BY CREATEDDATE DESC
		
		IF @RUNNINGPARTNO=''
		begin			
			set @ISTestCompleted='NA'								
			RETURN		
		end					
		SELECT TOP 1 @PART_FIXTUREGROUPTYPE=ISNULL(PART_FIXTUREGROUPTYPE,'') FROM ROUTINGCONFIGPARTWISE WITH (NOLOCK)
		WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND PARTNO=@RUNNINGPARTNO AND 
			MACHINECODE=DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE,@LINECODE)

		IF @PART_FIXTUREGROUPTYPE='' and  @ISByPassPokaYoke=0
		BEGIN									
				SET @ISTESTCOMPLETED='NA'								
				RETURN		
		END

			IF @CONDITION='INSERT_BYPASS_POKA_YOKE_IN_MAIN_SERVER'
			BEGIN
					SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL  WITH (NOLOCK) 
					WHERE PROFITCENTERCODE = @PROFITCENTERCODE AND LINECODE = @LINECODE 
					SET @EXECQUERY='INSERT INTO '+@LINKSERVERNAME+'.DBO.[ASSY_POKAYOKE_STATUS]
					(
						[PROFITCENTERCODE],[LINECODE],[MACHINECODE],[OPERATIONCODE]
						,[BARCODE],[PARTNO],[DATECODE],[EXPRESULT],[ACTRESULT]
						,[USERID],[ISMAILSENT],[MAILSENTTIMESTAMP],[SCANTIMESTAMP]
						,[RESULTTIMESTAMP],ISACTIVE,DESCRIPTION
					)
					SELECT PK.PROFITCENTERCODE,PK.LINECODE,PK.MACHINECODE,PK.OPERATIONCODE
						,PK.BARCODE,pk.PartNo,PK.Datecode,PK.EXPRESULT,PK.ACTRESULT
						,PK.USERID,PK.ISMAILSENT,PK.MAILSENTTIMESTAMP,PK.SCANTIMESTAMP
						,PK.RESULTTIMESTAMP,ISNULL(PK.ISACTIVE,0)ISACTIVE,PK.DESCRIPTION FROM  ASSY_POKAYOKE_STATUS PK WITH(NOLOCK) 				
						WHERE PK.PROFITCENTERCODE='''+@PROFITCENTERCODE+''' 
						AND PK.LINECODE ='''+@LINECODE+''' AND ISNULL(PK.ISMAILSENT,0)=0';		
					EXEC(@EXECQUERY)

					UPDATE ASSY_POKAYOKE_STATUS SET ISMAILSENT=1,MAILSENTTIMESTAMP=GETDATE() WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE 
					AND ISNULL(ISMAILSENT,0)=0		
	   				UPDATE ASSY_SCAN_OK SET	BARCODE='' WHERE LINECODE=@LINECODE
					
					SET @EXECQUERY=''
					SET @EXECQUERY='INSERT INTO '+@LINKSERVERNAME+'.DBO.[ASSY_POKAYOKE_STATUS]		
					(
							PROFITCENTERCODE,LINECODE,MACHINECODE,BARCODE,PARTNO
						   ,USERID,ISACTIVE,RESULTTIMESTAMP,DESCRIPTION,DATECODE
					)
						SELECT  PK.PROFITCENTERCODE, PK.LINECODE, PK.MACHINECODE, PK.BARCODE, RP.ASSY_PARTNO,
						PK.ENTBY,
						ISNULL(PK.ISACTIVE,''0'')ISACTIVE,GETDATE() AS RESULTTIMESTAMP,PK.DESCRIPTION,RP.DATECODE FROM
						ASSY_POKAYOKE PK WITH(NOLOCK)	INNER JOIN ASSY_RUNNINGPART RP WITH(NOLOCK) ON PK.PROFITCENTERCODE =RP.PROFITCENTERCODE 
						AND PK.LINECODE=RP.LINECODE 	
						WHERE PK.PROFITCENTERCODE='''+@PROFITCENTERCODE+''' AND  PK.LINECODE ='''+@LINECODE+'''  AND ISNULL(PK.ISACTIVE,0)=0
						and pk.PARTNUMBER IN
						(
							SELECT DISTINCT PARTNO FROM ROUTINGCONFIGPARTWISE(NOLOCK) 
							WHERE PROFITCENTERCODE='''+@PROFITCENTERCODE+''' AND PART_FIXTUREGROUPTYPE='''+@PART_FIXTUREGROUPTYPE+'''
						)

						ORDER BY PK.PROFITCENTERCODE,PK.LINECODE,PK.MACHINECODE,PK.BARCODE'			
					EXEC(@EXECQUERY)
					UPDATE Assy_Scan_OK_History_For_PokaYoke SET BARCODE='',ISCYCLESTARTED=0 WHERE LINECODE=@LINECODE
					--Added by Ravi on 27-Feb-2016
					------------------update Assy_PokaYoke_Completed_Dtl table for checking whether Final viewing testing has been completed or not--------------------------
					declare @ISPartTestedAfterPKYK int =0
					declare @Datecode char(4),@PartNo varchar(60),@CreatedDate datetime					
					if exists
					(
					  select 1 from linemst with(nolock) where profitcentercode=@profitcentercode and linecode=@linecode and isnull(isPokaYokeMandatory,0)=1
					)
					begin		 
							select top 1  @Datecode=Datecode,@PartNo=Assy_PartNo,@CreatedDate=CreatedDate from assy_runningpart with (nolock) 
							where ProfitCenterCode=@profitcentercode  and LineCode=@linecode order by CreatedDate desc

							--delete Assy_PokaYoke_Completed_Dtl if datecode is old
								if exists(select 1 from Assy_PokaYoke_Completed_Dtl with(nolock) where Datecode!=@Datecode)
									truncate table Assy_PokaYoke_Completed_Dtl 

							select @ISPartTestedAfterPKYK=isnull(count(isnull (barcode,0)),0) from assy_lineassystatus with(nolock) where ProfitCenterCode=@profitcentercode 
							and linecode=@linecode
							and Datecode=@Datecode and MachineCode=dbo.Assy_FN_Get_FinalViewing_MachineCode_From_LineCode(@profitcentercode,@linecode)
							and PartNo=@PartNo and ScanTimestamp>=@CreatedDate and isnull(IsTallyChartApproved,0)=0 and isnull(status,'')!=''

							if(isnull(@ISPartTestedAfterPKYK,0)>0)
							begin
								IF NOT EXISTS (SELECT 1 FROM Assy_PokaYoke_Completed_Dtl WHERE ProfitCenterCode=@profitcentercode 
										and linecode=@linecode	and Datecode=@Datecode and PartNo=@PartNo)
								BEGIN
									insert into Assy_PokaYoke_Completed_Dtl
									(
									ProfitCenterCode,LineCode,Datecode,PartNo,Is_PKYK_Completed,Is_Fv_Completed,Timestamp
									)
									select @profitcentercode,@LineCode,@Datecode,@PartNo,1, (case when @ISPartTestedAfterPKYK=0 then 0 else 1 end)Is_PKYK_Completed,getdate()
								END
								ELSE
								BEGIN
									UPDATE Assy_PokaYoke_Completed_Dtl SET Timestamp = GETDATE() WHERE ProfitCenterCode=@profitcentercode 
										and linecode=@linecode	and Datecode=@Datecode and PartNo=@PartNo
								END
							end
					end
					----------------------------------------------------------------------------------------------------------------------------------------
					RETURN
			END					
		else IF @CONDITION='UPDATE_POKA_YOKE_COMPELETE_FOR_FAULT_PART'
	      BEGIN			

		           update assy_lineassyStatus_running set Status='FT',RESULTTIMESTAMP =GETDATE() where ProfitCenterCode=@PROFITCENTERCODE and linecode=@LINECODE 
					and MachineCode=@MACHINECODE and OperationCode=@OPERATIONCODE and barcode=@BARCODE and isnull(status,'')!='PS'
					--INSERT DATA INTO ASSY_POKAYOKE_STATUS FOR THE PURPOSE OF SENDING MAIL
					INSERT INTO ASSY_POKAYOKE_STATUS
					(
						PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,BARCODE,PARTNO,DATECODE
						,ACTRESULT,USERID,SCANTIMESTAMP,RESULTTIMESTAMP
						,EXPRESULT,ISACTIVE,ISMAILSENT,DESCRIPTION
					)
					 SELECT  ASSY.PROFITCENTERCODE, ASSY.LINECODE, ASSY.MACHINECODE, ASSY.OPERATIONCODE, ASSY.BARCODE,RP.ASSY_PARTNO,RP.DATECODE
					 ,(CASE WHEN ISNULL( ASSY.STATUS,'')='PS' THEN 'PASS'  WHEN ISNULL( ASSY.STATUS,'')='FL' THEN 'FAIL' 
					  ELSE 'FAULT' END)AS ACTRESULT,ASSY.USERID, ASSY.SCANTIMESTAMP, ASSY.RESULTTIMESTAMP
					 ,ISNULL(PK.EXPRESULT,'') EXPRESULT,ISNULL(PK.ISACTIVE,'0')ISACTIVE	,0,PK.DESCRIPTION	 
					FROM  ASSY_LINEASSYSTATUS_RUNNING ASSY WITH (NOLOCK)  
					INNER JOIN ASSY_POKAYOKE PK WITH(NOLOCK) ON 
					  ASSY.PROFITCENTERCODE=PK.PROFITCENTERCODE AND ASSY.LINECODE =PK.LINECODE AND ASSY.MACHINECODE=PK.MACHINECODE 
						AND ASSY.BARCODE =PK.BARCODE	
					INNER JOIN ASSY_RUNNINGPART RP WITH(NOLOCK) ON PK.PROFITCENTERCODE =RP.PROFITCENTERCODE AND PK.LINECODE=RP.LINECODE		
					WHERE ASSY.PROFITCENTERCODE=@PROFITCENTERCODE AND  ASSY.LINECODE =@LINECODE AND  ASSY.MACHINECODE=@MACHINECODE AND  ASSY.OPERATIONCODE=@OPERATIONCODE
					AND  ASSY.BARCODE =@BARCODE  AND  ASSY.ACTIVE =0  AND ISNULL(PK.ISACTIVE,0)=1
					AND ISNULL( ASSY.STATUS,'')<>'' 
					ORDER BY RESULTTIMESTAMP  		
				
					UPDATE ASSY_LINEASSYSTATUS_RUNNING SET ACTIVE=1 WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE AND MACHINECODE=@MACHINECODE 
					AND OPERATIONCODE=@OPERATIONCODE AND BARCODE =@BARCODE AND ISNULL(ACTIVE,0) =0  AND ISNULL(STATUS,'')<>'' 	
					
					IF NOT EXISTS
					(
							SELECT  top 1 1 FROM ASSY_POKAYOKE(NOLOCK) A left outer join assy_LINEASSYSTATUS_RUNNING(NOLOCK) B
							ON  A.PROFITCENTERCODE=B.PROFITCENTERCODE AND A.LINECODE=B.LINECODE AND A.MACHINECODE=B.MACHINECODE AND A.BARCODE=B.BARCODE	
								AND B.OPERATIONCODE=@OPERATIONCODE 	
							INNER JOIN ROUTINGCONFIGPARTWISE PR WITH (NOLOCK) ON							 
								A.PROFITCENTERCODE=PR.PROFITCENTERCODE AND A.MACHINECODE=PR.MACHINECODE AND A.PARTNUMBER=PR.PARTNO
								and PR.PART_FIXTUREGROUPTYPE=@PART_FIXTUREGROUPTYPE	and PR.OperationCode= @OPERATIONCODE	
							WHERE A.PROFITCENTERCODE=@PROFITCENTERCODE AND A.LINECODE=@LINECODE AND A.MACHINECODE=@MACHINECODE 											
							AND ISNULL(B.STATUS,'')=''  AND ISNULL(A.ISACTIVE,0)=1 	and isnull(PR.Traceability,0)=1									
					)
					BEGIN
							UPDATE ASSY_SCAN_OK SET ISPOKAYOKECOMPLETED=1,Barcode='' WHERE LINECODE=@LINECODE AND MACHINECODE=@MACHINECODE
							AND OPERATIONCODE=@OPERATIONCODE
							UPDATE ASSY_RESULT	SET	STATIONCODE='PKYK',Barcode=@BARCODE	WHERE LINECODE=@LINECODE AND OPERATIONCODE=@OPERATIONCODE	
							set @ISTestCompleted='YES'										
							UPDATE Assy_Scan_OK_History_For_PokaYoke SET BARCODE='',ISCYCLESTARTED=0 
							WHERE LINECODE=@LINECODE AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE	

							exec Assy_Proc_PokaYoke_Last_Tested_Part @CONDITION='INSERT',@ProfitCenterCode=@ProfitCenterCode,@LineCode=@LINECODE
							,@MachineCode=@MACHINECODE,@OperationCode=@OPERATIONCODE
					END						
				
	END
	    ELSE IF @CONDITION='UPDATE_POKA_YOKE_RESULT'
		   BEGIN
				
				--CHECK PLC RESULT AND POKA YOKE EXPECTED RESULT IS NOT SAME
				IF EXISTS
				(
						SELECT 1 FROM ASSY_POKAYOKE (NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE AND MACHINECODE=@MACHINECODE
						AND BARCODE =@BARCODE AND ISNULL(EXPRESULT,'')<> ISNULL(@PLCRESULT,'') AND 
						ISNULL(RESVERREQUIRED,0)=1 AND ISNULL(ISACTIVE,0)=1 and (@ISFaultBarcodeScanned=0)
				)
				BEGIN
				    
						DELETE FROM ASSY_POKAYOKE_CURRENT_RESULT WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE AND MACHINECODE=@MACHINECODE 
						AND OPERATIONCODE =@OPERATIONCODE
						INSERT INTO ASSY_POKAYOKE_CURRENT_RESULT
						(
						 PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,BARCODE,ACTRESULT,EXPRESULT,USERID,RESULTTIMESTAMP,ISPROCESSED
						)
						SELECT @PROFITCENTERCODE,@LINECODE,@MACHINECODE,@OPERATIONCODE,@BARCODE,@PLCRESULT,
						(
						 SELECT ISNULL(EXPRESULT,'') EXPRESULT FROM ASSY_POKAYOKE (NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE 
						 AND MACHINECODE=@MACHINECODE
						 AND BARCODE =@BARCODE AND  ISNULL(ISACTIVE,0)=1
						)
						,@USERID,GETDATE(),1

						set @ISTestCompleted='NA'
						RETURN
				END
				--UPDATE RESULT FOR POKA YOKE INTO ASSY_LINEASSYSTATUS_RUNNING TABLE
				UPDATE ASSY_LINEASSYSTATUS_RUNNING SET RESULTTIMESTAMP =GETDATE(),STATUS=(CASE WHEN ISNULL(@PLCRESULT,'')='PASS' THEN 'PS'   
				WHEN ISNULL(@PLCRESULT,'')='FAIL' then 'FL' ELSE 'FT' END) 
				WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE 
				AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE AND BARCODE =@BARCODE
				AND SCANTIMESTAMP=(SELECT TOP 1 SCANTIMESTAMP FROM ASSY_LINEASSYSTATUS_RUNNING WITH (NOLOCK)  WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE 
				AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE AND BARCODE =@BARCODE ORDER BY SCANTIMESTAMP DESC)

			--INSERT DATA INTO ASSY_POKAYOKE_STATUS FOR THE PURPOSE OF SENDING MAIL
				INSERT INTO ASSY_POKAYOKE_STATUS
				(
					PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,BARCODE,PARTNO,DATECODE
					,ACTRESULT,USERID,SCANTIMESTAMP,RESULTTIMESTAMP
					,EXPRESULT,ISACTIVE,ISMAILSENT,DESCRIPTION
				)
				 SELECT  ASSY.PROFITCENTERCODE, ASSY.LINECODE, ASSY.MACHINECODE, ASSY.OPERATIONCODE, ASSY.BARCODE,RP.ASSY_PARTNO,RP.DATECODE
				 ,(CASE WHEN ISNULL( ASSY.STATUS,'')='PS' THEN 'PASS'  WHEN ISNULL( ASSY.STATUS,'')='FL' THEN 'FAIL' 
				  ELSE 'FAULT' END)AS ACTRESULT,ASSY.USERID, ASSY.SCANTIMESTAMP, ASSY.RESULTTIMESTAMP
				 ,ISNULL(PK.EXPRESULT,'') EXPRESULT,ISNULL(PK.ISACTIVE,'0')ISACTIVE	,0,PK.DESCRIPTION	 
				FROM  ASSY_LINEASSYSTATUS_RUNNING ASSY WITH (NOLOCK)  
				INNER JOIN ASSY_POKAYOKE PK WITH(NOLOCK) ON 
				  ASSY.PROFITCENTERCODE=PK.PROFITCENTERCODE AND ASSY.LINECODE =PK.LINECODE AND ASSY.MACHINECODE=PK.MACHINECODE 
					AND ASSY.BARCODE =PK.BARCODE	
				INNER JOIN ASSY_RUNNINGPART RP WITH(NOLOCK) ON PK.PROFITCENTERCODE =RP.PROFITCENTERCODE AND PK.LINECODE=RP.LINECODE		
				WHERE ASSY.PROFITCENTERCODE=@PROFITCENTERCODE AND  ASSY.LINECODE =@LINECODE AND  ASSY.MACHINECODE=@MACHINECODE AND  ASSY.OPERATIONCODE=@OPERATIONCODE
				AND  ASSY.BARCODE =@BARCODE  AND  ASSY.ACTIVE =0  AND ISNULL(PK.ISACTIVE,0)=1
				AND ISNULL( ASSY.STATUS,'')<>'' 
				ORDER BY RESULTTIMESTAMP  		
				
				UPDATE ASSY_LINEASSYSTATUS_RUNNING SET ACTIVE=1 WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE =@LINECODE AND MACHINECODE=@MACHINECODE 
				AND OPERATIONCODE=@OPERATIONCODE AND BARCODE =@BARCODE AND ISNULL(ACTIVE,0) =0  AND ISNULL(STATUS,'')<>'' 									
						
				IF NOT EXISTS
				(
				
							SELECT  top 1 1 FROM ASSY_POKAYOKE(NOLOCK) A left outer join assy_LINEASSYSTATUS_RUNNING(NOLOCK) B
							ON  A.PROFITCENTERCODE=B.PROFITCENTERCODE AND A.LINECODE=B.LINECODE AND A.MACHINECODE=B.MACHINECODE AND A.BARCODE=B.BARCODE	
								AND B.OPERATIONCODE=@OPERATIONCODE 	
							INNER JOIN ROUTINGCONFIGPARTWISE PR WITH (NOLOCK) ON							 
								A.PROFITCENTERCODE=PR.PROFITCENTERCODE AND A.MACHINECODE=PR.MACHINECODE AND A.PARTNUMBER=PR.PARTNO
								and PR.PART_FIXTUREGROUPTYPE=@PART_FIXTUREGROUPTYPE	and PR.OperationCode= @OPERATIONCODE	
							WHERE A.PROFITCENTERCODE=@PROFITCENTERCODE AND A.LINECODE=@LINECODE AND A.MACHINECODE=@MACHINECODE 											
							AND ISNULL(B.STATUS,'')=''  AND ISNULL(A.ISACTIVE,0)=1 	and isnull(PR.Traceability,0)=1											
				)
				BEGIN					
								UPDATE ASSY_SCAN_OK SET ISPOKAYOKECOMPLETED=1,Barcode='' WHERE LINECODE=@LINECODE AND MACHINECODE=@MACHINECODE
								AND OPERATIONCODE=@OPERATIONCODE
								UPDATE ASSY_RESULT	SET	STATIONCODE='PKYK',Barcode=@BARCODE	WHERE LINECODE=@LINECODE AND OPERATIONCODE=@OPERATIONCODE		
								set @ISTestCompleted='YES'	
								UPDATE Assy_Scan_OK_History_For_PokaYoke SET BARCODE='',ISCYCLESTARTED=0 
								WHERE LINECODE=@LINECODE AND MACHINECODE=@MACHINECODE AND OPERATIONCODE=@OPERATIONCODE	
																
								exec Assy_Proc_PokaYoke_Last_Tested_Part @CONDITION='INSERT',@ProfitCenterCode=@ProfitCenterCode,@LineCode=@LINECODE
								,@MachineCode=@MACHINECODE,@OperationCode=@OPERATIONCODE
				END				
							    	
				
		END
		--Update Poka yoke completed for a particular part ,for that Poka yoke master has not been defined
		ELSE IF @CONDITION='UPDATE_POKAYOKE_COMPLETED_FOR_NA_PART'
		BEGIN
				print '----------------------1'
				DECLARE @TMPALLACTIVERECORDS  TABLE
				(
				PROFITCENTERCODE VARCHAR(20),
				LINECODE VARCHAR(20),
				MACHINECODE VARCHAR(20),
				OPERATIONCODE VARCHAR(20),
				PARTNO VARCHAR(60),
				OPERATIONSEQNO INT 
				)				
				IF ISNULL(@PART_FIXTUREGROUPTYPE,'')=''
				BEGIN		
					
						INSERT INTO @TMPALLACTIVERECORDS(PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,PARTNO,OPERATIONSEQNO)	
						SELECT L.PROFITCENTERCODE,L.LINECODE,RP.MACHINECODE,RP.OPERATIONCODE,RP.PARTNO,RL.OPERATIONSEQNO  FROM LINEMST L  WITH (NOLOCK) 
						INNER JOIN ROUTINGCONFIGLINEWISE RL WITH(NOLOCK)
							ON L.PROFITCENTERCODE = RL.PROFITCENTERCODE AND L.LINECODE=RL.LINECODE 
						INNER JOIN ROUTINGCONFIGPARTWISE  RP WITH(NOLOCK)
							ON RL.PROFITCENTERCODE =RP.PROFITCENTERCODE AND RL.MACHINECODE =RP.MACHINECODE AND RL.OPERATIONCODE =RP.OPERATIONCODE
						WHERE L.PROFITCENTERCODE=@PROFITCENTERCODE
						AND L.LINECODE=@LINECODE AND ISNULL(L.ISACTIVE,0)=1 AND ISNULL(L.ISPOKAYOKEMANDATORY,0)=1		
						AND ISNULL(RL.POKA_YOKE_ALLOWED,0) =1 AND ISNULL(RL.TRACEABILITY,0) =1 AND ISNULL(RP.TRACEABILITY,0) =1
						AND RP.PartNo=@RUNNINGPARTNO
						ORDER BY RP.PARTNO,RL.OPERATIONSEQNO
				END
				ELSE
					BEGIN						
						INSERT INTO @TMPALLACTIVERECORDS(PROFITCENTERCODE,LINECODE,MACHINECODE,OPERATIONCODE,PARTNO,OPERATIONSEQNO)
						SELECT L.PROFITCENTERCODE,L.LINECODE,RP.MACHINECODE,RP.OPERATIONCODE,RP.PARTNO,RL.OPERATIONSEQNO  FROM LINEMST L  WITH (NOLOCK) 
						INNER JOIN ROUTINGCONFIGLINEWISE RL WITH(NOLOCK)
							ON L.PROFITCENTERCODE = RL.PROFITCENTERCODE AND L.LINECODE=RL.LINECODE 
						INNER JOIN ROUTINGCONFIGPARTWISE  RP WITH(NOLOCK)
							ON RL.PROFITCENTERCODE =RP.PROFITCENTERCODE AND RL.MACHINECODE =RP.MACHINECODE AND RL.OPERATIONCODE =RP.OPERATIONCODE
						WHERE L.PROFITCENTERCODE=@PROFITCENTERCODE
						AND L.LINECODE=@LINECODE AND ISNULL(L.ISACTIVE,0)=1 AND ISNULL(L.ISPOKAYOKEMANDATORY,0)=1		
						AND ISNULL(RL.POKA_YOKE_ALLOWED,0) =1 AND ISNULL(RL.TRACEABILITY,0) =1 AND ISNULL(RP.TRACEABILITY,0) =1
						AND RP.PART_FIXTUREGROUPTYPE=@PART_FIXTUREGROUPTYPE
						ORDER BY RP.PARTNO,RL.OPERATIONSEQNO 

				   END
				--SELECT * FROM  @TMPALLACTIVERECORDS
				
				DECLARE @ALLACTIVEOPEARTIONCODE AS TABLE
				(
					ID INT IDENTITY(1,1),
					OPERATIONCODE VARCHAR(20),
					MACHINECODE VARCHAR(20)
				)
				INSERT INTO @ALLACTIVEOPEARTIONCODE(OPERATIONCODE,MACHINECODE)
				SELECT DISTINCT OPERATIONCODE,MACHINECODE FROM @TMPALLACTIVERECORDS 
				--SELECT * FROM @ALLACTIVEOPEARTIONCODE
				DECLARE @START INT=1
				DECLARE @END    INT
				SELECT @END =COUNT(ID) FROM @ALLACTIVEOPEARTIONCODE

				WHILE(@START<=@END)
				BEGIN
						SELECT @MACHINECODE=MACHINECODE,@OPERATIONCODE=OPERATIONCODE FROM @ALLACTIVEOPEARTIONCODE WHERE ID=@START
						IF  NOT EXISTS
						(
							 SELECT 1 FROM @TMPALLACTIVERECORDS T  JOIN ASSY_POKAYOKE P WITH (NOLOCK) 
							 ON T.PROFITCENTERCODE=P.PROFITCENTERCODE AND T.LINECODE =P.LINECODE AND T.MACHINECODE =P.MACHINECODE 
							 AND T.PARTNO =P.PARTNUMBER
							 AND P.ISACTIVE =1 
							 WHERE T.OPERATIONCODE =@OPERATIONCODE AND T.MACHINECODE =@MACHINECODE
			
						)
						BEGIN
								IF  EXISTS
								(
									SELECT DISTINCT 1 FROM ASSY_SCAN_OK(NOLOCK) WHERE LINECODE=@LINECODE 
									AND OPERATIONCODE=@OPERATIONCODE AND MACHINECODE=@MACHINECODE 
								)
								BEGIN
										UPDATE ASSY_SCAN_OK SET ISPOKAYOKECOMPLETED=1 WHERE LINECODE=@LINECODE AND OPERATIONCODE=@OPERATIONCODE AND MACHINECODE=@MACHINECODE	
										AND ISNULL(ISPOKAYOKECOMPLETED,0)=0											
								END
								ELSE
									BEGIN
										INSERT INTO ASSY_SCAN_OK(LINECODE,OPERATIONCODE,MACHINECODE,ISPOKAYOKECOMPLETED)
										SELECT @LINECODE,@OPERATIONCODE,@MACHINECODE,1											
									END
						END
						SET @START=@START+1
						--PRINT 'OC '+CONVERT(VARCHAR(20), @START)
				END
		END
		--Update Cycle Started from PLC procedure
		ELSE IF @CONDITION='UPDATE_CYCLE_STARTED_FROM_PLC_PROC'
		BEGIN
			IF CHARINDEX('PKYK',@BARCODE) = 0
				RETURN
			
			-- Added By Rashid For PokaYoke 29-July-2016 For twin Index
			Declare @ScannedStationIndex INT;
			SET @ScannedStationIndex = (SELECT dbo.assy_fnGetScannedStationIndex(@LineCode, @OperationCode))
			
			IF(@ScannedStationIndex = -1)
			BEGIN
				IF EXISTS
				(	
					SELECT 1 FROM ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE WITH (NOLOCK) WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE 
						AND OPERATIONCODE = @OPERATIONCODE
				)
				BEGIN					
					UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE SET ISCYCLESTARTED = 1, BARCODE = @BARCODE, TIMESTAMP = GETDATE()
					WHERE  LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE
				END
				ELSE
				BEGIN					
						INSERT INTO ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE
						(
							LINECODE,
							MACHINECODE,
							OPERATIONCODE,
							ISCYCLESTARTED,
							BARCODE
						)
						SELECT @LINECODE,@MACHINECODE,@OPERATIONCODE,1,@BARCODE
				END
			END
			ELSE
			-- Added By Rashid For PokaYoke 01-August-2016 For twin Index
			BEGIN
				Declare @InsideStationIndex INT;
					IF(@ScannedStationIndex = 1)
						SET @InsideStationIndex = 1
					ELSE IF(@ScannedStationIndex = 2)
						SET @InsideStationIndex = 2
				IF EXISTS
				(	
					SELECT 1 FROM ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE WITH (NOLOCK) WHERE LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE 
						AND OPERATIONCODE = @OPERATIONCODE AND StationCode = @InsideStationIndex
				)
				BEGIN					
					UPDATE ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE SET ISCYCLESTARTED = 1, BARCODE = @BARCODE, TIMESTAMP = GETDATE()
					WHERE  LINECODE = @LINECODE AND MACHINECODE = @MACHINECODE AND OPERATIONCODE = @OPERATIONCODE AND StationCode = @InsideStationIndex
				END
				ELSE
				BEGIN					
					INSERT INTO ASSY_SCAN_OK_HISTORY_FOR_POKAYOKE
					(
						LINECODE,
						MACHINECODE,
						OPERATIONCODE,
						ISCYCLESTARTED,
						BARCODE,
						StationCode
					)
					SELECT @LINECODE,@MACHINECODE,@OPERATIONCODE,1,@BARCODE,@InsideStationIndex
				END
			END
		END
END



GO
/****** Object:  StoredProcedure [dbo].[Assy_PROC_Validate_Manual_Datecode]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[Assy_PROC_Validate_Manual_Datecode]
@Operation varchar(50),
@Manual_Datecode char(4)=null,
@LoginID varchar(20)=null,
@ProfitCenterCode varchar(20)=NULL,
@ReturnValue VARCHAR (2000)=NULL OUT,
@ReturnInt INT=NULL OUT , 
@LineCode Varchar(20)=NULL  
AS
BEGIN

		BEGIN TRY 
		SET NOCOUNT ON

--declare @p4 varchar(2000)
--set @p4='OK'
--declare @p5 int
--set @p5=1
--exec Assy_PROC_Validate_Manual_Datecode @Operation=N'FILL_SHIFT',@Manual_Datecode=N'17Pb',
--@LoginID=N'Empro',@ProfitCenterCode='0021',@ReturnValue=@p4 output,@ReturnInt=@p5 output,@LineCode='M07'
--select @p4, @p5

	  if @Operation='EXEC_PROC'
	  begin
				Declare @ReturnValue_PROC varchar(2000)
				Declare @ReturnInt_PROC int
				exec Assy_PROC_ManualDateCode_Updating @Operation='update',@DateCode=@Manual_Datecode,@UserName=@LoginID
				,@ReturnValue=@ReturnValue_PROC output,@ReturnInt=@ReturnInt_PROC output,@ProfitCenterCode=@ProfitCenterCode,@LineCode=@LineCode

				if @ReturnInt_PROC=1
				begin
						 set @ReturnValue= 'OK'
						 set @ReturnInt=1
				 end
				 else
				 begin
						set @ReturnValue= 'NOT OK'
						set @ReturnInt=2
				 end
	  end

	  if @Operation='FILL_SHIFT'
	  begin
			
			    SELECT code
					  FROM     
						 (    
						SELECT ShiftCode    
						 ,[Monday]    
						 ,[Tuesday]    
						 ,[Wednesday]    
						 ,[Thursday]    
						 ,[Friday]    
						 ,[Saturday]    
						 ,[Sunday]  				
						FROM DateCodeMst where ProfitCenterCode =@ProfitCenterCode
			         
						 ) p    
					  UNPIVOT    
						 (code FOR day1 IN     
						 (Monday    
						 ,[Tuesday]    
						 ,[Wednesday]    
						 ,[Thursday]    
						 ,[Friday]    
						 ,[Saturday]    
						 ,[Sunday]    
						 )    
			            
			            
					  )AS unpvt    

			 set @ReturnValue= 'OK'
             set @ReturnInt=1
	  end

	  if @Operation='FILL_WEEK'
	  begin
			  select Code from WeekMst(nolock) where Code<=52 order by Code
			 set @ReturnValue= 'OK'
				 set @ReturnInt=1
	  end

	  if @Operation='FILL_YEAR'
	  begin
			 select code from YearMst(nolock) where code<>'' order by year
			 set @ReturnValue= 'OK'
             set @ReturnInt=1
	  end

	  if @Operation='VALIDATE_DATECODE'
	  begin
						  --Get current datecode
							 declare @Current_Datecode char(4)=''      		    
							 exec ASSY_PROC_DATECODE @ProfitCenterCode, @Current_Datecode output      
						    -- print @Current_Datecode
	                         
						  --Validate week
						 -- print '@Current_Datecode'+SUBSTRING (@Current_Datecode,1,2)
						  --print '@Manual_Datecode'+SUBSTRING (@Manual_Datecode,1,2)

						  if CONVERT (int,SUBSTRING (@Current_Datecode,1,2))<CONVERT (int,SUBSTRING (@Manual_Datecode,1,2))
						  begin
							   set @ReturnValue= 'Week code is not correct'
							   return
	        
						  end
	  
						  --Validate year
						  if upper(substring(@Current_Datecode,4,1))<> upper(substring(@Manual_Datecode,4,1))
						  begin
							   set @ReturnValue= 'Year code is not correct'
							   return

						  end
	  
						  --Validate day					   

						 if(CONVERT (int,SUBSTRING (@Current_Datecode,1,2))=CONVERT (int,SUBSTRING (@Manual_Datecode,1,2)))	 
						   and (Ascii(SUBSTRING (@Current_Datecode,3,1))<Ascii(SUBSTRING (@Manual_Datecode,3,1)))
							begin
								set @ReturnValue= 'Shift code is not correct'
								return;
							end
							set @ReturnValue= 'OK'
							set @ReturnInt=1
			end

	     END TRY 
		 BEGIN CATCH  
					--CATCH BLOCK BEGINS
						SET @ReturnValue =	CAST(ERROR_NUMBER() as varchar(5)) + '|' + 
						CAST(ERROR_SEVERITY()as varchar(5)) + '|' + 
						CAST(ERROR_STATE() as varchar(5)) + '|' + 
						CAST(ERROR_PROCEDURE() as varchar(200)) + '|' + 
						CAST(ERROR_LINE() as varchar(5)) + '|' + 
						CAST(ERROR_MESSAGE() as varchar(1500))
							
						SET @ReturnInt = 2
		
					--CATCH BLOCK ENDS 
	   END CATCH
END

GO
/****** Object:  StoredProcedure [dbo].[ASSY_PROC_VARIFY_PARAMETERS_ON_FV]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/***************************************************************************************                    
PROCEDURE         :     ASSY_PROC_VARIFY_PARAMETERS_ON_FV
AUTHOR            :     SACHIN KUMAR
DATE WRITTEN      :     July 24, 2017
PURPOSE           :     

TEST SCRIPT  
exec ASSY_PROC_VARIFY_PARAMETERS_ON_FV 'MAL1','0088','L1000829Nd'

****************************************************************************************/
CREATE PROCEDURE [dbo].[ASSY_PROC_VARIFY_PARAMETERS_ON_FV]
(
 @P_lineCode varchar(10)='',
 @P_profitCenterCode varchar(10)='',
 @P_barcode varchar(30)='',
 @ReturnValue VARCHAR (2000)=NULL OUT,
  @ReturnInt INT=NULL OUT
)
AS
BEGIN

DECLARE @OC VARCHAR(10)
DECLARE @SEQNo smallint
CREATE TABLE #Get_Parameter_values 
(
   OperationCode varchar(10),
   TagName varchar(100),
   TagValue varchar(30),
   TagId int,
   SeqNo smallint
)

select * into #temp_VRF_LS from Assy_LineAssyStatus_Running(nolock) 
where Barcode=@P_barcode and LineCode=@P_lineCode and ProfitCenterCode=@P_profitCenterCode

select distinct OperationSeqNo,OperationCode into #TEMP_ACT_OC from RoutingConfigLineWise(nolock) where 
LineCode=@P_lineCode and ProfitCenterCode=@P_profitCenterCode  
and OperationCode in (select distinct OperationCode from #temp_VRF_LS where OperationCode not in ('OCIG'))

select *  into #TEMP_VRF_MTM from machineTagMapping where LineCode=@P_lineCode and ProfitCenterCode=@P_profitCenterCode

select * into #temp_VRF_PDR from Assy_LineAssyParamData_Running(nolock) 
where Barcode=@P_barcode and LineCode=@P_lineCode and ProfitCenterCode=@P_profitCenterCode

select * into #temp_VRF_TM from  TagMst(nolock) where ProfitCenterCode=@P_profitCenterCode

select * into #WHILE_TEMP_ACT_OC from #TEMP_ACT_OC

while exists(select top 1 1 from #WHILE_TEMP_ACT_OC  )
begin

select top 1 @OC = OperationCode, @SEQNo=OperationSeqNo from #WHILE_TEMP_ACT_OC order by OperationSeqNo asc

insert into #Get_Parameter_values(OperationCode,TagName,TagValue,TagId,seqNo)
select pdr.OperationCode,tag.TagDescription,dtl.Value,tag.TagId,@SEQNo from  #temp_VRF_PDR(nolock) pdr inner join
Assy_LineAssyParamData_Running_Dtl(nolock) dtl on 
pdr.UID=dtl.UID
inner join #temp_VRF_TM tag on
tag.TagId=dtl.TagId
where pdr.OperationCode=@OC

delete #WHILE_TEMP_ACT_OC where OperationCode=@OC

end

select  distinct oc.OperationSeqNo,mtm.operationCode,tag.TagDescription,'' as TagValue,tagId into #TEMP_PRM_DATA 
from #TEMP_VRF_MTM mtm inner join #temp_VRF_TM tag on tag.tagName=mtm.tagName
inner join #TEMP_ACT_OC oc on oc.operationCode= mtm.operationCode


delete #TEMP_PRM_DATA where tagId in (select tagId from #Get_Parameter_values)

insert into #Get_Parameter_values(OperationCode,TagName,TagValue,TagId,seqNo)
select operationCode,TagDescription,TagValue,tagId,OperationSeqNo from
#TEMP_PRM_DATA order by OperationSeqNo

select OperationCode,TagName,TagValue from #Get_Parameter_values order by SeqNo

END
