CREATE PROCEDURE [dbo].[ASSY_PROC_VIEW_DATA]
(

@P_LINECODE VARCHAR(10) = '',
@P_PROFITCENTERCODE VARCHAR(10)='',
@P_PARTCODE VARCHAR(50)='',
@P_DATECODE VARCHAR(10)='',
@P_OPTION   VARCHAR(100)=''
)
AS
BEGIN

DECLARE @LINECODE VARCHAR(10)
DECLARE @PROFITCENTERCODE VARCHAR(10)
DECLARE @PARTCODE VARCHAR(50)
DECLARE @DATECODE VARCHAR(10)
DECLARE @prevDate			varchar(20)
DECLARE @lastDayDate       varchar(20)=NULL


SET @LINECODE=@P_LINECODE
SET @PROFITCENTERCODE = @P_PROFITCENTERCODE
SET @PARTCODE=@P_PARTCODE
SET @DATECODE=@P_DATECODE


IF OBJECT_ID('tempdb..#TEMP_DATA_TABLE') IS NOT NULL
DROP TABLE #TEMP_DATA_TABLE
		

CREATE TABLE [dbo].[#TEMP_DATA_TABLE](
	[Barcode] [varchar](100) NOT NULL,
	[TagName] [varchar](50) NOT NULL,
	[Value] [varchar](60) NULL,
	[TagId] [int] NOT NULL,
	[LineCode] [varchar](10) NOT NULL,
	[StationCode] [varchar](10) NOT NULL,
	[Datecode] [char](4) NOT NULL,
	[MachineCode] [varchar](20) NOT NULL,
	[OperationCode] [varchar](10) NOT NULL,
	[ProfitCenterCode] [varchar](10) NOT NULL,
	[Result] [varchar](5) NOT NULL,
	[Timestamp] [datetime] NOT NULL,
	[PartNo] [varchar](60) NULL
) ON [PRIMARY]



IF(@P_OPTION='GET_DATECODE_PARTWISE_DATA')
BEGIN 


INSERT INTO [#TEMP_DATA_TABLE]
([ProfitCenterCode],[LineCode],[MachineCode],[OperationCode],
[Barcode],[Result],[Datecode],[PartNo],[Timestamp],[StationCode],[TagName],[Value],[TagId]
)
SELECT ProfitCenterCode,LineCode,MachineCode,OperationCode,Barcode,isnull([Status],'WP'),
Datecode,PartNo,isnull(ResultTimestamp,''),StationCode,'','',0
FROM ASSY_LINEASSYSTATUS(NOLOCK) WHERE 
LINECODE=@LINECODE AND ProfitCenterCode=@PROFITCENTERCODE AND Datecode=@DATECODE AND PartNo=@PARTCODE

INSERT INTO [#TEMP_DATA_TABLE]
([ProfitCenterCode],[LineCode],[MachineCode],[OperationCode],
[Barcode],[Result],[Datecode],[PartNo],[Timestamp],[StationCode],[TagName],[Value],[TagId]
)
SELECT ProfitCenterCode,LineCode,MachineCode,OperationCode,Barcode,isnull([Status],'WP'),
Datecode,PartNo,isnull(ResultTimestamp,''),StationCode,'','',0
FROM ASSY_LINEASSYSTATUS_RUNNING(NOLOCK) WHERE 
LINECODE=@LINECODE AND ProfitCenterCode=@PROFITCENTERCODE AND Datecode=@DATECODE AND PartNo=@PARTCODE

SELECT * FROM [#TEMP_DATA_TABLE]

END

IF(@P_OPTION='LASTMONTH_PRODUCTION')
BEGIN 


			
SET @prevDate= convert(varchar,year(dateadd(mm, -1, getdate()))) + '-'+convert(varchar,month(dateadd(mm, -1, getdate())))+'-'+
convert(varchar,1)+' 00:00:00.000'
					
SET @lastDayDate= convert(varchar,year(dateadd(mm, -1, getdate()))) + '-'+convert(varchar,month(dateadd(mm, -1, getdate())))+'-'+
convert(varchar,day(dateadd(month, -1, getdate())))+' 23:59:59.999' -- modified by sachin 20170331
					

INSERT INTO [#TEMP_DATA_TABLE]
([ProfitCenterCode],[LineCode],[MachineCode],[OperationCode],
[Barcode],[Result],[Datecode],[PartNo],[Timestamp],[StationCode],[TagName],[Value],[TagId]
)
SELECT ProfitCenterCode,LineCode,MachineCode,OperationCode,Barcode,isnull([Status],'WP'),
Datecode,PartNo,isnull(ResultTimestamp,''),StationCode,'','',0
FROM ASSY_LINEASSYSTATUS(NOLOCK) WHERE 
LINECODE=@LINECODE AND 
ProfitCenterCode=@PROFITCENTERCODE AND 
--PartNo=@PARTCODE AND
ScanTimestamp between @prevDate and @lastDayDate

INSERT INTO [#TEMP_DATA_TABLE]
([ProfitCenterCode],[LineCode],[MachineCode],[OperationCode],
[Barcode],[Result],[Datecode],[PartNo],[Timestamp],[StationCode],[TagName],[Value],[TagId]
)
SELECT ProfitCenterCode,LineCode,MachineCode,OperationCode,Barcode,isnull([Status],'WP'),
Datecode,PartNo,isnull(ResultTimestamp,''),StationCode,'','',0
FROM ASSY_LINEASSYSTATUS_RUNNING(NOLOCK) WHERE 
LINECODE=@LINECODE AND 
ProfitCenterCode=@PROFITCENTERCODE AND
--PartNo=@PARTCODE AND
ScanTimestamp between @prevDate and @lastDayDate

SELECT * FROM [#TEMP_DATA_TABLE]

END

IF(@P_OPTION='CURRENTMONTH_PRODUCTION')
BEGIN 


			
--2017-01-06 11:24:34.143
SET @prevDate= convert(varchar,year(getdate())) + '-'+convert(varchar,month(getdate()))+'-'+
convert(varchar,1)+' 00:00:00.000'
									

INSERT INTO [#TEMP_DATA_TABLE]
([ProfitCenterCode],[LineCode],[MachineCode],[OperationCode],
[Barcode],[Result],[Datecode],[PartNo],[Timestamp],[StationCode],[TagName],[Value],[TagId]
)
SELECT ProfitCenterCode,LineCode,MachineCode,OperationCode,Barcode,isnull([Status],'WP'),
Datecode,PartNo,isnull(ResultTimestamp,''),StationCode,'','',0
FROM ASSY_LINEASSYSTATUS(NOLOCK) WHERE 
LINECODE=@LINECODE AND 
ProfitCenterCode=@PROFITCENTERCODE AND 
--PartNo=@PARTCODE AND
ScanTimestamp between @prevDate and getdate()

INSERT INTO [#TEMP_DATA_TABLE]
([ProfitCenterCode],[LineCode],[MachineCode],[OperationCode],
[Barcode],[Result],[Datecode],[PartNo],[Timestamp],[StationCode],[TagName],[Value],[TagId]
)
SELECT ProfitCenterCode,LineCode,MachineCode,OperationCode,Barcode,isnull([Status],'WP'),
Datecode,PartNo,isnull(ResultTimestamp,''),StationCode,'','',0
FROM ASSY_LINEASSYSTATUS_RUNNING(NOLOCK) WHERE 
LINECODE=@LINECODE AND 
ProfitCenterCode=@PROFITCENTERCODE AND
PartNo=@PARTCODE AND
ScanTimestamp between @prevDate and getdate()

SELECT * FROM [#TEMP_DATA_TABLE]

END

END


