/****** Object:  StoredProcedure [dbo].[Assy_Proc_Vision_System]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[Assy_Proc_Vision_System]     
(          
  @BARCODE VARCHAR(25) = '',
  @LINECODE VARCHAR(10) = '',
  @USERID VARCHAR(20) = '' ,
  @PROFITCENTERCODE VARCHAR(20) = '',
  @SERIALNO VARCHAR(15) = NULL,
  @LOTSERIALNO VARCHAR(20) = NULL,
  @ISMANUAL BIT = 0,
  @P_DateCode VARCHAR(10)='',
  @P_PartNo	  VARCHAR(10)=''
)          
AS          
BEGIN
	/*
	AUTHOR:				<RAVISHANKAR MISHRA>
	CREATE DATE:		< 15 SEP 2014>
	MODIFIED BY:		<Rashid Siddiqui>
	MODIFIED DATE:		< 19th May 2016>
	DESCRIPTION:		<Add Rework Mode>
	MODIFIED BY:		< Sudesh Kumar > 
	MODIFIED DATE:		< 20170515 > 
	DESCRIPTION:		< Added column ProductionOrderNo in Table Assy_LineAssyStatus_Running for mapping of Production Order with Barcode >

	EXEC Assy_Proc_Vision_System '2906714637QB12345676M07','M07','RAVI','0021','12345676'
	SELECT * FROM ASSY_WIP
	SELECT * FROM ASSY_VISION_SYSTEM ORDER BY TIMESTAMP DESC
	SELECT * FROM ASSY_LINEASSYSTATUS_RUNNING ORDER BY SCANTIMESTAMP DESC	
	
	*/

	   SET NOCOUNT ON;		  
	   DECLARE @MACHINECODE VARCHAR(10)
	   DECLARE @OPERATIONCODE VARCHAR(10)
	   DECLARE @DATECODE CHAR(4),@PARTNO VARCHAR(30)
	   DECLARE @LOGINUSERID VARCHAR(20)
	   DECLARE @SERVOPARTNO VARCHAR(30)
	   Declare @SaveMode VARCHAR(20) = '', @IsRework INT = 0
	   DECLARE @ProductionOrderNo VARCHAR(40)

       IF NOT EXISTS(SELECT DISTINCT 1 FROM  ASSY_VISION_SYSTEM(NOLOCK) WHERE PROFITCENTERCODE=@PROFITCENTERCODE AND LINECODE=@LINECODE AND BARCODE=@BARCODE)  
	   BEGIN		           
			       
				    SELECT @MACHINECODE=MACHINECODE,@OPERATIONCODE=OPERATIONCODE FROM ROUTINGCONFIGLINEWISE(NOLOCK) WHERE TRACEABILITY=1 
				    AND OPERATIONSEQNO=1 AND LINECODE =@LINECODE AND PROFITCENTERCODE=@PROFITCENTERCODE

					IF EXISTS(SELECT TOP 1 1 FROM RoutingConfigDetails(NOLOCK) WHERE LineCode=@LINECODE AND KeyType='IsMaualPrintingWithoutSetParameter' and KeyValue=1)
					BEGIN
						SET @DATECODE=@P_DateCode
						SET @PARTNO=@P_PartNo
						SET @LOGINUSERID='NA'
						SET @SaveMode=''
						SET @ProductionOrderNo='NA'
					END
					ELSE
					BEGIN
					SELECT TOP 1 @DATECODE=DATECODE,@PARTNO =ASSY_PARTNO,@LOGINUSERID=CREATEDBY,@SaveMode = UPPER(RTRIM(LTRIM(ISNULL(Assy_Mode,'')))),
						@ProductionOrderNo = ProductionOrderNo  
						FROM ASSY_RUNNINGPART(NOLOCK) 
						WHERE LINECODE =@LINECODE AND ASSY_MODE IN ('Production','Rework')
					END
					IF EXISTS 
					(
					   SELECT 1 FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE LINECODE =@LINECODE AND ASSY_MODE IN ('Production','Rework') AND ISNULL(PARTTYPE,'')='STMC'
					)
					BEGIN
						 SELECT TOP 1 @SERVOPARTNO=SERVO_PARTNO FROM ASSY_RUNNINGPART WITH (NOLOCK) WHERE LINECODE =@LINECODE  AND ASSY_MODE IN ('Production','Rework')		
					END
					ELSE
					   SET @SERVOPARTNO=@PARTNO

					IF @SaveMode = 'PRODUCTION'
						SET @IsRework = 0
					ELSE IF @SaveMode = 'REWORK'
						SET @IsRework = 1
					
					INSERT INTO ASSY_VISION_SYSTEM(PROFITCENTERCODE,LINECODE,BARCODE,PARTNO,DATECODE,SERIALNO,TIMESTAMP,IsRework)        
					                        SELECT @PROFITCENTERCODE,@LINECODE,@BARCODE,@SERVOPARTNO,@DATECODE,@SERIALNO,GETDATE(),@IsRework
					
					IF @USERID =''
						SET @USERID=@LOGINUSERID
					--Modified By Sudesh on 20170515 for new column ProductionOrderNo in Table Assy_LineAssyStatus_Running
		            INSERT INTO ASSY_LINEASSYSTATUS_RUNNING 
					(
					PROFITCENTERCODE,
					LINECODE,
					MACHINECODE,
					OPERATIONCODE,
					STATIONCODE,
					BARCODE,
					STATUS,
					FAILCOUNT,
					DATECODE,
					PARTNO,
					RESULTTIMESTAMP,
					SCANTIMESTAMP,
					USERID,
					ProductionOrderNo,
					PROD_LOT_NO
					)
					SELECT
					@PROFITCENTERCODE
					,@LINECODE,
					@MACHINECODE ,
					@OPERATIONCODE 
					,'1'
					,@BARCODE
					,'PS'
					,0
					,@DATECODE
					,@PARTNO
					,GETDATE()
					,GETDATE()
					,@USERID
					,@ProductionOrderNo
					,@LOTSERIALNO

					--UPDATE PRINTED BARCODE COUNTER
					EXEC Assy_Proc_Barcode_Printed_Counter @CONDITION='UPDATE',@LINECODE =@LINECODE ,@PROFITCENTERCODE =@PROFITCENTERCODE
					UPDATE ASSY_RUNNINGPART SET PRINTEDQTY=ISNULL(PRINTEDQTY,0)+1 WHERE LINECODE=@LINECODE AND CURRENTPLANNEDQTY>ISNULL(PRINTEDQTY,0)
					
					--MODIFIED BY RAVI ON 11-09-2015, UPDATE WIP QTY. FOR BARCODE PRINTING STATION 
					IF @ISMANUAL=0
			    		EXEC ASSY_PROC_WIP_MANAGE  @CONDITION='UPDATE_WIP_COUNT', @LINECODE=@LINECODE,@MACHINECODE=@MACHINECODE
						,@BARCODE=@BARCODE,@PROFITCENTERCODE=@PROFITCENTERCODE			

		END     
END



GO
