CREATE proc [dbo].[ASSY_Proc_Vision_System_IPAddress]
(
@Condition varchar(50),
@ProfitCenterCode varchar(30)=null,
@LineCode Varchar(30)=null,
@IpAddress varchar(20)=null,
@Port varchar(20)=null
)
AS
BEGIN

--author:<Ravishankar Mishra>
--created on :<30-04-15>
--exec ASSY_Proc_Vision_System_IPAddress @Condition='insert',@ProfitCenterCode='0021',@LineCode='m06',@IpAddress='192.168.202.25',@Port='12000'
--exec ASSY_Proc_Vision_System_IPAddress @Condition='SELECT',@ProfitCenterCode='0021',@LineCode='m07'
--select * from ASSY_Vision_System_IPAddress

		SET NOCOUNT ON
		if @Condition ='INSERT'
		begin

						if exists
						(
							select 1 from ASSY_Vision_System_IPAddress(nolock) where linecode =@LineCode and ProfitCenterCode=@ProfitCenterCode  
						)
						begin
								update ASSY_Vision_System_IPAddress set IpAddress =@IpAddress,Port =@Port ,Timestamp=getdate()
								where linecode =@LineCode and ProfitCenterCode=@ProfitCenterCode  

						end
						else
						begin
								insert into ASSY_Vision_System_IPAddress
								(
								ProfitCenterCode,
								LineCode,
								IpAddress,
								Port,
								Timestamp
								)
								select
								@ProfitCenterCode ,
								@LineCode ,
								@IpAddress ,
								@Port ,
								getdate()

						end


		end

		else if @Condition ='SELECT'
		begin
				select IpAddress,Port from ASSY_Vision_System_IPAddress(nolock) where linecode =@LineCode and ProfitCenterCode=@ProfitCenterCode 
		end


END


