/****** Object:  StoredProcedure [dbo].[ASSY_PROC_VISION_SYSTEM_LAST_PRINTED_BARCODE]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create PROC [dbo].[ASSY_PROC_VISION_SYSTEM_LAST_PRINTED_BARCODE]
(
@CONDITION VARCHAR(50),
@LINECODE VARCHAR(20)=NULL,
@PROFITCENTERCODE VARCHAR(20)=NULL,
@RETURNVALUE VARCHAR (2000)=NULL OUT,
@RETURNINT INT=NULL OUT

)

--CREATED BY: <RAVISHANKAR MISHRA>
--CREAETD DATE- 29/12/2014

--MODIFIED BY: <RAVISHANKAR MISHRA>
--MODIFIED DATE- 23/05/2016

--SELECT * FROM ASSY_VISION_SYSTEM_LAST_PRINTED_BARCODE
--EXEC ASSY_PROC_VISION_SYSTEM_LAST_PRINTED_BARCODE @CONDITION='LAST_PRINTED_BARCODE',@LINECODE='S02'
--DECLARE @RETURNVALUEACT VARCHAR(20)
--EXEC ASSY_PROC_VISION_SYSTEM_LAST_PRINTED_BARCODE @CONDITION='GET_VISION_SYSTEM_IN_ROUTING',@LINECODE='J04',@PROFITCENTERCODE='0088',@RETURNVALUE=@RETURNVALUEACT OUT
--SELECT @RETURNVALUEACT

-- TO REMBEMBER
-- NOTHING = 0
-- SUCCESS = 1
-- ERROR = 2
-- ALREADYEXISTS = 3
-- NOTEXISTS = 4


AS
BEGIN
         
		 SET NOCOUNT ON
		 DECLARE @OPERATIONSEQNO INT=0,@LINETYPECODE VARCHAR(20)='',@OPERATIONCODE VARCHAR(20)=''
		 IF @CONDITION='LAST_PRINTED_BARCODE'
		 BEGIN
				 SELECT BARCODE+'^'+CONVERT(VARCHAR,TIMESTAMP) FROM ASSY_VISION_SYSTEM_LAST_PRINTED_BARCODE(NOLOCK) WHERE LINECODE=@LINECODE
				 SET @RETURNINT=1
				 SET @RETURNVALUE='SELECTED'				 
				 RETURN

		 END

		 IF @CONDITION='GET_VISION_SYSTEM_IN_ROUTING'
		 BEGIN

					 SELECT TOP 1 @OPERATIONSEQNO=L.OPERATIONSEQNO,@OPERATIONCODE=L.OPERATIONCODE FROM ROUTINGCONFIGLINEWISE(NOLOCK) L
					INNER JOIN ROUTINGCONFIGPARTWISE(NOLOCK) P
						ON  l.ProfitCenterCode =p.ProfitCenterCode 
						and L.OPERATIONCODE =P.OPERATIONCODE 
						AND L.MACHINECODE =P.MACHINECODE 
					 WHERE L.PROFITCENTERCODE =@PROFITCENTERCODE 
							and L.LINECODE  =@LINECODE
							AND P.PARTNO =(SELECT top 1 ASSY_PARTNO  FROM ASSY_RUNNINGPART(NOLOCK) where ProfitCenterCode =@PROFITCENTERCODE and LineCode =@LINECODE )
							AND L.TRACEABILITY =1
							AND P.TRACEABILITY =1														
							ORDER BY L.OPERATIONSEQNO 					
					
					
					IF @OPERATIONSEQNO=1 
					BEGIN	
								 SET @RETURNINT=1
								 SET @RETURNVALUE='FOUND_IN_ROUTING'
								 SELECT @OPERATIONCODE			 
									 
					END
					RETURN
			END
END
GO
