CREATE PROC [dbo].[ASSY_Proc_Vision_System_Log]
(          
  @OPeration varchar(60)='',
  @PartNo VARCHAR(25)='',
  @LineCode varchar(10)='',  
  @PROFITCENTERCODE nVARCHAR(4)='0021',
  @Counter varchar(8)='',
  @LastPrintBarcode varchar(50) =''     
)          
AS          

BEGIN          
	   SET NOCOUNT ON	
	   if @OPeration ='UPDATE_SEQUENCE_NUMBER'
		   BEGIN
			   IF NOT EXISTS(select 1 from ASSY_Vision_System_Log(nolock) where partnumber =@PartNo and linecode =@LineCode and PROFITCENTERCODE=@PROFITCENTERCODE)  
			   begin
						INSERT INTO ASSY_Vision_System_Log(PROFITCENTERCODE,LineCode,partnumber,SequenceNumber,Counter,LastPrintedBarcode,LastPrintTimeStamp)        
						 VALUES(@PROFITCENTERCODE,@LineCode,@PartNo ,'1','1',@LastPrintBarcode ,getdate()) 
			   end
				else
					begin
							update ASSY_Vision_System_Log set counter =convert(varchar(8),(convert(int,counter)+1))
							,lastprintedBarcode = @LastPrintBarcode,LastPrintTimeStamp =getdate() 
							where partnumber = @PartNo and Linecode =@lineCode and PROFITCENTERCODE=@PROFITCENTERCODE
					end
			END
		ELSE IF @OPERATION ='SELECT_SEQUENCE_NUMBER'
		begin
			
			   IF NOT EXISTS(select 1 from ASSY_Vision_System_Log(nolock) where partnumber =@PartNo and linecode =@LineCode and PROFITCENTERCODE=@PROFITCENTERCODE)  
			   begin
						INSERT INTO ASSY_Vision_System_Log(PROFITCENTERCODE,LineCode,partnumber,SequenceNumber,Counter,LastPrintedBarcode,LastPrintTimeStamp)        
						 VALUES(@PROFITCENTERCODE,@LineCode,@PartNo ,'1','1','' ,getdate()) 
			   end

                select counter from ASSY_Vision_System_Log(nolock) where PartNumber=@PartNo  and linecode = @LineCode and profitcentercode=@PROFITCENTERCODE
		end
END 





