/****** Object:  StoredProcedure [dbo].[Assy_Proc_Vision_System_Part_Selection]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[Assy_Proc_Vision_System_Part_Selection]
(
@OPERATION VARCHAR(30),
@LINECODE VARCHAR(10)=NULL,
@PROFITCENTERCODE VARCHAR(20)=NULL
)
AS
BEGIN

		--EXEC Assy_Proc_Vision_System_Part_Selection 'SELECT_PARTTYPE','S02','0021'
		SET NOCOUNT ON  
		IF @OPERATION='SELECT'
		BEGIN
				SELECT ASSY_PARTNO,DATECODE ,ASSY_MODE FROM ASSY_RUNNINGPART(NOLOCK) WHERE LINECODE =@LINECODE AND ASSY_MODE IN ('Production','Rework')
		END
		IF @OPERATION='SELECT_PARTTYPE'
		BEGIN			
				DECLARE @RUNNINGPART AS TABLE
				(
				 ASSY_PARTNO VARCHAR(50),
				 DATECODE CHAR(4),
				 ASSY_MODE VARCHAR(20),
				 PARTTYPE VARCHAR(10)
				)
				INSERT INTO @RUNNINGPART(ASSY_PARTNO,DATECODE,ASSY_MODE,PARTTYPE)
				SELECT RP.ASSY_PARTNO,RP.DATECODE ,RP.ASSY_MODE,ISNULL(PM.MATERIAL_TP,'')PARTTYPE FROM ASSY_RUNNINGPART(NOLOCK) RP 
				INNER JOIN PRODUCT_MASTER(NOLOCK) PM ON PM.SEWS_PART_NO=RP.ASSY_PARTNO 
				WHERE RP.LINECODE =@LINECODE AND ASSY_MODE IN ('Production','Rework') AND PM.WAREHOUSE_CD=@PROFITCENTERCODE

				--SELECT ASSY_PARTNO,DATECODE,ASSY_MODE,PARTTYPE FROM @RUNNINGPART
				IF(SELECT PARTTYPE FROM @RUNNINGPART)='STMC'
				BEGIN							
							SELECT  TOP 1 ISNULL(SERVO_PARTNO,'')  AS ASSY_PARTNO, RP.DATECODE,RP.ASSY_MODE,RP.PARTTYPE,CONVERT(INT, ISNULL(VS.COUNTER,0))COUNTER,
							BOOST_RATIO  AS BOOSTRATIO  FROM ASSY_RUNNINGPART(NOLOCK)RP							
							LEFT OUTER JOIN ASSY_VISION_SYSTEM_LOG(NOLOCK) VS ON RP.SERVO_PARTNO =VS.PARTNUMBER AND RP.LINECODE =VS.LINECODE 
						    AND VS.LINECODE=@LINECODE WHERE RP.LINECODE=@LINECODE AND ASSY_MODE IN ('Production','Rework')

				END
				ELSE  IF (SELECT PARTTYPE FROM @RUNNINGPART)='SERVO' 
				BEGIN
					SELECT ASSY_PARTNO,DATECODE,ASSY_MODE,PARTTYPE,DBO.ASSY_FN_GET_BOOSTRATIO(@PROFITCENTERCODE,(SELECT ASSY_PARTNO FROM @RUNNINGPART)) AS BOOSTRATIO
					 FROM @RUNNINGPART
				END

		END		
END

GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_WIP_Check]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Assy_Proc_WIP_Check] 
	-- Add the parameters for the stored procedure here
	(
	@CONDITION VARCHAR(100) = NULL,
	@LineCode VARCHAR(20) = NULL,
	@MachineCode VARCHAR(20) = NULL,
	@ReturnValue VARCHAR (2000) = NULL OUT,
	@ReturnInt INT = NULL OUT,
	@Enable_WIP INT = NULL,
	@ProfitCenterCode VARCHAR(20) = '0021'
	)
AS
BEGIN
	-- =============================================
	-- Author:		SUNDARA MOORTHI
	-- Create date: 21-01-2016
	-- Modified BY:	Rashid Siddiqui
	-- Modified date: 03-March-2016
	-- Description:	Check WIP Limit AND Reset the Table, Bypass WIP Condition
	-- =============================================
	SET NOCOUNT ON;
	BEGIN TRY
		IF(@CONDITION = 'GET_WIP_DETAILS')
		BEGIN
			IF OBJECT_ID('tempdb..#temp') IS NOT NULL
				DROP TABLE #temp
			IF (SELECT Top 1 ISNULL(WIPCheck,0) FROM LINEMST(NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode) = 1
			BEGIN	
				SELECT  Assy_WIP.LineCode, MachineMst.MachineName, MachineMst.MachineCode, Assy_WIP.WIPCount AS WIPCount, RoutingConfigLineWise.OperationSeqNo
				INTO #temp
				FROM  MachineMst (NOLOCK) INNER JOIN
						Assy_WIP(NOLOCK) ON MachineMst.MachineCode = Assy_WIP.MachineCode
				INNER JOIN RoutingConfigLineWise(NOLOCK) ON Assy_WIP.MachineCode = RoutingConfigLineWise.MachineCode
				WHERE Assy_WIP.LineCode  = @LineCode 
				AND	RoutingConfigLineWise.LineCode = @LineCode
				GROUP BY Assy_WIP.LineCode, MachineMst.MachineName, MachineMst.MachineCode, RoutingConfigLineWise.OperationSeqNo, Assy_WIP.WIPCount
				ORDER BY Assy_WIP.LineCode, MachineMst.MachineName, MachineMst.MachineCode, RoutingConfigLineWise.OperationSeqNo, Assy_WIP.WIPCount ASC

				SELECT * FROM #temp ORDER BY OperationSeqNo
			END
			SET @ReturnValue = 'SUCCESS'
			SET @ReturnInt = 0
		END
		ELSE IF(@CONDITION = 'UPDATE_WIP')
		BEGIN
			SET @MachineCode = (SELECT Top 1 MachineCode FROM MachineMst(NOLOCK) WHERE MachineName = @MachineCode)
			UPDATE Assy_WIP SET WIPCount = 0 WHERE LineCode = @LineCode AND MachineCode = @MachineCode

			SET @ReturnValue = 'SUCCESS'
			SET @ReturnInt = 0
		END
		ELSE IF(@CONDITION = 'ENABLE_DISABLE_WIP')
		BEGIN
			IF(@Enable_WIP IN (0,1))
			BEGIN
				UPDATE LineMst SET WIPCheck = @Enable_WIP WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			END
			
			SELECT  ISNULL(WIPCheck,0) WIPCheck FROM LineMst (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
			RETURN
		END
	END TRY
	BEGIN CATCH
		SET @ReturnValue =	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
			CAST(ERROR_SEVERITY() AS VARCHAR(5)) + '|' + 
			CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
			CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
			CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
			CAST(ERROR_MESSAGE() AS VARCHAR(1500))
			RAISERROR (@ReturnValue,16,1)						
		   SET @ReturnInt = 2
	END CATCH
END


GO
/****** Object:  StoredProcedure [dbo].[ASSY_PROC_WIP_GET_PREVIOUSSTATION_MACHINECODE]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[ASSY_PROC_WIP_GET_PREVIOUSSTATION_MACHINECODE]
(
	@CONDITION VARCHAR(50) = NULL,
	@LINECODE VARCHAR(10) = NULL,
	@MACHINECODE VARCHAR(20) = NULL,
	@PREVMACHINECODE VARCHAR(20) = NULL OUT,
	@RETURNINT INT = NULL OUT
)
AS
BEGIN
	-- AUTHOR:		<RAVISHANKAR MISHRA>
	-- CREATE DATE: < 15/01/2015>
	-- DESCRIPTION:	<FINAL VIEWING.>

	-- MODIFIED BY - RASHID SIDDIQUI
	-- MODIFIED DATE - 09-OCT-2015

	-- TO REMBEMBER
	-- NOTHING = 0
	-- SUCCESS = 1
	-- ERROR = 2
	-- ALREADYEXISTS = 3
	-- NOTEXISTS = 4

	--DECLARE @RETURNVALUE1 VARCHAR(100),@RETURNINT1 INT
	--EXEC ASSY_PROC_WIP_GET_PREVIOUSSTATION_MACHINECODE @CONDITION='WIP_PREVIOUS_STATION' ,@LINECODE='M07',@MACHINECODE='MCMS',@PREVMACHINECODE=@RETURNVALUE1 OUT,@RETURNINT=@RETURNINT1 OUT
	--SELECT @RETURNVALUE1,@RETURNINT1

		SET NOCOUNT ON

		CREATE TABLE #TEMP_WIP
		(
			MACHINECODE VARCHAR(20),
			OPERATIONSEQNO INT
		)
		CREATE TABLE #TEMP_WIP_NEW
		(
			MACHINECODE VARCHAR(20),
			OPERATIONSEQNO INT
		)
		CREATE TABLE #TEMP_ACTUAL_MACHINE_SEQ
		(
			ID INT,
			MACHINECODE VARCHAR(20),
			OPERATIONSEQNO INT
		)

		IF @CONDITION = 'WIP_PREVIOUS_STATION'
		BEGIN
			INSERT INTO  #TEMP_WIP
			(
				MACHINECODE,
				OPERATIONSEQNO
			)

			SELECT L.MACHINECODE, L.OPERATIONSEQNO
				FROM ROUTINGCONFIGLINEWISE(NOLOCK) L 
					INNER JOIN ROUTINGCONFIGPARTWISE (NOLOCK) P 
						ON L.PROFITCENTERCODE = P.PROFITCENTERCODE AND L.OPERATIONCODE = P.OPERATIONCODE AND L.MACHINECODE = P.MACHINECODE
					INNER JOIN LINEMST (NOLOCK) LM ON L.LINECODE = LM.LINECODE
						WHERE L.LINECODE = @LINECODE
							AND P.PARTNO = (SELECT TOP 1 ASSY_PARTNO FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE ORDER BY CREATEDDATE DESC )
							AND L.TRACEABILITY = 1
							AND L.WIP_QUANTITY <> 0
							AND LM.WIPCHECK = 1
							AND LM.ISACTIVE = 1
							AND P.TRACEABILITY = 1
								ORDER BY L.OPERATIONSEQNO

			/* COMMENT BY RASHID ON 9TH OCT 2015
			SELECT   L.MACHINECODE,L.OPERATIONSEQNO FROM  ROUTINGCONFIGLINEWISE(NOLOCK) L
			INNER JOIN LINEMST (NOLOCK) LM
			ON L.LINECODE = LM.LINECODE
			WHERE  L.TRACEABILITY = 1
			AND L.WIP_QUANTITY <> 0
			AND LM.WIPCHECK = 1
			AND LM.ISACTIVE = 1
			AND LM.LINECODE = @LINECODE
			ORDER BY L.OPERATIONSEQNO
			*/
							
			INSERT INTO #TEMP_WIP_NEW(MACHINECODE,OPERATIONSEQNO)
			SELECT DISTINCT MACHINECODE,OPERATIONSEQNO   FROM #TEMP_WIP(NOLOCK) ORDER BY OPERATIONSEQNO
							 
			INSERT INTO #TEMP_ACTUAL_MACHINE_SEQ
			(
				ID,
				MACHINECODE,
				OPERATIONSEQNO
			)
			SELECT
			ROW_NUMBER() OVER (ORDER BY OPERATIONSEQNO)ID,
			MACHINECODE,
			OPERATIONSEQNO
			FROM #TEMP_WIP_NEW(NOLOCK) ORDER BY OPERATIONSEQNO

			SELECT @PREVMACHINECODE = ISNULL(MACHINECODE,'') FROM #TEMP_ACTUAL_MACHINE_SEQ(NOLOCK)
			WHERE ID = (SELECT ID-1 FROM #TEMP_ACTUAL_MACHINE_SEQ(NOLOCK) WHERE MACHINECODE = @MACHINECODE )
			SET @RETURNINT = 1
							
			--DROP TABLES IF ALREDY EXISTS
			IF OBJECT_ID('TEMPDB..#TEMP_WIP') IS NOT NULL
				DROP TABLE  #TEMP_WIP
							
			IF OBJECT_ID('TEMPDB..#TEMP_WIP_NEW') IS NOT NULL
				DROP TABLE  #TEMP_WIP_NEW

			IF OBJECT_ID('TEMPDB..#TEMP_ACTUAL_MACHINE_SEQ') IS NOT NULL
				DROP TABLE  #TEMP_ACTUAL_MACHINE_SEQ
		END

		ELSE IF @CONDITION = 'WIP_FIFO_PREVIOUS_STATION'
		BEGIN

			INSERT INTO  #TEMP_WIP
			(
				MACHINECODE,
				OPERATIONSEQNO
			)
			SELECT L.MACHINECODE, L.OPERATIONSEQNO
				FROM ROUTINGCONFIGLINEWISE(NOLOCK) L 
					INNER JOIN ROUTINGCONFIGPARTWISE (NOLOCK) P 
						ON L.PROFITCENTERCODE = P.PROFITCENTERCODE AND L.OPERATIONCODE = P.OPERATIONCODE AND L.MACHINECODE = P.MACHINECODE
					INNER JOIN LINEMST (NOLOCK) LM ON L.LINECODE = LM.LINECODE
						WHERE L.LINECODE = @LINECODE
							AND P.PARTNO = (SELECT TOP 1 ASSY_PARTNO FROM ASSY_RUNNINGPART (NOLOCK) WHERE LINECODE = @LINECODE ORDER BY CREATEDDATE DESC )
							AND L.TRACEABILITY = 1
							AND L.WIP_QUANTITY <> 0
							AND LM.WIPCHECK = 1
							AND LM.ISACTIVE = 1
							AND P.TRACEABILITY = 1
								ORDER BY L.OPERATIONSEQNO

			/* COMMENT BY RASHID ON 9TH OCT 2015
			SELECT   L.MACHINECODE,L.OPERATIONSEQNO FROM  ROUTINGCONFIGLINEWISE(NOLOCK) L
			INNER JOIN LINEMST (NOLOCK) LM
			ON L.LINECODE = LM.LINECODE
			WHERE  L.TRACEABILITY = 1
			AND L.WIPFIFOCHECK = 1
			AND LM.WIPFIFOCHECK = 1
			AND LM.ISACTIVE = 1
			AND LM.LINECODE = @LINECODE
			ORDER BY L.OPERATIONSEQNO
			*/
						
			INSERT INTO #TEMP_WIP_NEW(MACHINECODE,OPERATIONSEQNO)
			SELECT DISTINCT MACHINECODE,OPERATIONSEQNO  FROM #TEMP_WIP(NOLOCK) ORDER BY OPERATIONSEQNO
							 
			INSERT INTO #TEMP_ACTUAL_MACHINE_SEQ
			(
				ID,
				MACHINECODE,
				OPERATIONSEQNO
			)
			SELECT
			ROW_NUMBER() OVER (ORDER BY OPERATIONSEQNO)ID,
			MACHINECODE,
			OPERATIONSEQNO
			FROM #TEMP_WIP_NEW(NOLOCK) ORDER BY OPERATIONSEQNO

			SELECT @PREVMACHINECODE = ISNULL(MACHINECODE,'') FROM #TEMP_ACTUAL_MACHINE_SEQ(NOLOCK)
			WHERE ID = (SELECT ID-1 FROM #TEMP_ACTUAL_MACHINE_SEQ(NOLOCK) WHERE MACHINECODE = @MACHINECODE )
			SET @RETURNINT = 1

			--DROP TABLES IF ALREDY EXISTS
			IF OBJECT_ID('TEMPDB..#TEMP_WIP') IS NOT NULL
				DROP TABLE  #TEMP_WIP
							
			IF OBJECT_ID('TEMPDB..#TEMP_WIP_NEW') IS NOT NULL
				DROP TABLE  #TEMP_WIP_NEW

			IF OBJECT_ID('TEMPDB..#TEMP_ACTUAL_MACHINE_SEQ') IS NOT NULL
				DROP TABLE  #TEMP_ACTUAL_MACHINE_SEQ
		END
END
GO
/****** Object:  StoredProcedure [dbo].[Assy_Proc_WIP_Manage]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
CREATE PROC [dbo].[Assy_Proc_WIP_Manage]
(
	@CONDITION VARCHAR(50) = NULL,
	@LINECODE VARCHAR(10) =	NULL,
	@MACHINECODE VARCHAR(20) = NULL,
	@PARTNO VARCHAR(20) = NULL,
	@BARCODE VARCHAR(30) = NULL,
	@NEXTSTATIONOPERATIONCODE VARCHAR(20) = NULL,
	@PROFITCENTERCODE VARCHAR(20) = NULL,
	@MachineName VARCHAR(50) = NULL,
	@RETURNVALUE VARCHAR (2000) = NULL OUT,
	@RETURNINT INT = NULL OUT,
	@RESULT VARCHAR(10) = NULL
)
AS 
  BEGIN
		/*
      Created By	:	<Rashid Siddiqui>
      Created Date	:	<03-Nov-2015>
	  Modified By	:	<Rashid Siddiqui>
	  Modified on	:	<10-Sep-2016>
	  Description	:	<Not Consider Engraving Station>
	  Modified on	:	<23-Dec-2016>
	  Description	:	<Change WIP Logic Due to Nissan Line 6 Barcode>
	  Modified on	:	<14-July-2017>
	  Description	:	<Try Catch Block>
	   Modified on	:	<25-July-2017>
	  Description	:	<Tran While Update WIP>

	  DECLARE @RETURNVALUE1 VARCHAR(100),@RETURNINT1 INT 
      EXEC Assy_Proc_WIP_Manage  @CONDITION='VALIDATE_WIP', @LINECODE='M07',@MACHINECODE='MCFV',@BARCODE='2906683505NB00000005M07',@PROFITCENTERCODE='0021',@RETURNVALUE=@RETURNVALUE1 OUT,@RETURNINT=@RETURNINT1 OUT
      SELECT @RETURNVALUE1,@RETURNINT1 
      
	  DECLARE @RETURNVALUE1 VARCHAR(100),@RETURNINT1 INT 
      EXEC Assy_Proc_WIP_Manage  @CONDITION='UPDATE_WIP_COUNT', @LINECODE='M07',@MACHINECODE='MCFV',@BARCODE='2906683505DB00000005M07',@PROFITCENTERCODE='0021',@RETURNVALUE=@RETURNVALUE1 OUT,@RETURNINT=@RETURNINT1 OUT      
      SELECT @RETURNVALUE1,@RETURNINT1 
      
	  DECLARE @RETURNVALUE1 VARCHAR(100),@RETURNINT1 INT 
      EXEC Assy_Proc_WIP_Manage  @CONDITION='UPDATE_NEXTSTATION_OPERATIONCODE', @LINECODE='M07',@MACHINECODE='MCRA',@NEXTSTATIONOPERATIONCODE='OCMSLH'
      ,@BARCODE='2906683503MB00000002M07',@RETURNVALUE=@RETURNVALUE1 OUT,@RETURNINT=@RETURNINT1 OUT      
      SELECT @RETURNVALUE1,@RETURNINT1 
      
	  DECLARE @RETURNVALUE1 VARCHAR(100),@RETURNINT1 INT 
      EXEC Assy_Proc_WIP_Manage  @CONDITION='VALIDATE_WIP_FIFO_BARCODE',@LINECODE='M07',@MACHINECODE='MCMS',@BARCODE='2906683505NB00000005M07',@NEXTSTATIONOPERATIONCODE='OCMSLH' ,@RETURNVALUE=@RETURNVALUE1 OUT,@RETURNINT=@RETURNINT1 OUT
      SELECT @RETURNVALUE1,@RETURNINT1 
      
	  SELECT * FROM ASSY_WIPFIFOCHECK  
      SELECT * FROM ASSY_WIP 
	  */
      ------------------ 
      SET NOCOUNT ON 

      DECLARE @PREVMACHINECODE VARCHAR(20) = NULL
      DECLARE @FINALVIEWING_MACHINECODE VARCHAR(20) = NULL 
      DECLARE @WIPDEFINEDQTY INT = 0 
	  DECLARE @RowCount INT = 0
	  DECLARE @RowCount_Qty INT = 0
      SELECT @FINALVIEWING_MACHINECODE = DBO.ASSY_FN_GET_FINALVIEWING_MACHINECODE_FROM_LINECODE(@PROFITCENTERCODE, @LINECODE)
	  Declare @FailCountDefined INT = 0
			SELECT @FailCountDefined = CONVERT(INT,PARAMETER_VALUE) FROM PARAMETER_MST (NOLOCK) WHERE PARAMETER_C = 'ASSLINE' 
					AND PARAMETER_C1 = 'REWORK_COUNT'AND WH_CODE = @ProfitCenterCode
	BEGIN TRY

	IF @CONDITION = 'UPDATE_WIP_COUNT'
	BEGIN 
		IF (SELECT Top 1 ISNULL(WIPCheck,0) FROM LINEMST(NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode) = 1
		BEGIN
			Declare @PartType_WIP VARCHAR(30) = ''
			SELECT Top 1 @PartType_WIP = LTRIM(RTRIM(PartType)), @PARTNO = Assy_PartNo FROM Assy_RunningPart (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
			IF @PartType_WIP = 'STMC'
			BEGIN
				IF OBJECT_ID('tempdb..#STMC_Final_Data_Qty') IS NOT NULL
				BEGIN
					DROP TABLE #STMC_Final_Data_Qty
				END
				IF OBJECT_ID('tempdb..#STMC_WIPMST_Qty') IS NOT NULL
				BEGIN
					DROP TABLE #STMC_WIPMST_Qty
				END
				SELECT ROW_NUMBER() OVER(ORDER BY OperationSeqNo) Seq, LineCode, Machinecode, OperationSeqNo, WIP_Quantity  
					INTO #STMC_WIPMST_Qty
						FROM (
							SELECT  ROW_NUMBER() OVER(PARTITION BY RCLW.MachineCode ORDER BY RCLW.OperationSeqNo) AS SeqNo,
									RCLW.LineCode, RCLW.MachineCode, RCLW.OperationSeqNo, RCLW.WIP_Quantity
										FROM RoutingConfigLineWise (NOLOCK) RCLW
										JOIN
										RoutingConfigPartWise (NOLOCK) RCPW
											ON	RCLW.ProfitCenterCode=RCPW.ProfitCenterCode AND
													RCLW.MachineCode = RCPW.MachineCode AND
														RCLW.OperationCode = RCPW.OperationCode AND
															RCLW.Traceability = RCPW.Traceability
																	
										JOIN
										LineMst (NOLOCK) LM
											ON	RCLW.ProfitCenterCode = LM.ProfitCenterCode AND
													RCLW.LineCode = LM.LineCode
											WHERE ISNULL(RCLW.Traceability,0) = 1 AND
													--RCPW.PartNo = (SELECT Top 1 Assy_PartNo FROM ASSY_RUNNINGPART (NOLOCK) WHERE LineCode = @LineCode ORDER BY CreatedDate Desc) AND
													RCPW.PartNo = @PARTNO AND
														RCLW.WIP_Quantity <> 0 AND
															ISNULL(LM.WIPCheck,0) = 1 AND
																ISNULL(LM.isActive,0) = 1 AND
																	ISNULL(RCPW.Traceability,0) = 1
																		-- Added By Rashid For Handling Engraving Station on 10th Sep 2016
																		AND ISNULL(RCLW.Engraving,0) = 0 AND ISNULL(RCPW.Engraving,0) = 0
																			AND LM.ProfitCenterCode = @ProfitCenterCode
																				AND LM.LineCode = @LineCode
																					
										) Source WHERE SeqNo = 1
			
				IF OBJECT_ID('tempdb..#STMC_Assy_LineAssyStatus_Running_WIP_Qty') IS NOT NULL
				BEGIN
					DROP TABLE #STMC_Assy_LineAssyStatus_Running_WIP_Qty
				END
				--Change WIP Logic By Rashid Siddiqui 23rd Dec 2016 Due to Nissan Line 6 Barcode WHEN CHARINDEX(@LineCode,Barcode) = 0 THEN RIGHT(Barcode,4) AND MachineCode != 'MCENGSTN'
				SELECT LineCode, MachineCode, Case WHEN CHARINDEX(':',Barcode) > 0 THEN RIGHT(Barcode,4) WHEN CHARINDEX(@LineCode,Barcode) = 0 THEN RIGHT(Barcode,4) ELSE LEFT(RIGHT(Barcode,6),4) END Barcode, Status, FailCount 
				INTO #STMC_Assy_LineAssyStatus_Running_WIP_Qty FROM Assy_LineAssyStatus_Running (NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(Status,'') NOT IN ('','PE') AND Datecode != 'PKYK' AND MachineCode != 'MCENGSTN'
						AND Barcode NOT IN (SELECT Distinct Barcode FROM Assy_TallyChartStatusData WITH (NOLOCK)
							WHERE ISNULL(Result,'') = '' AND ISNULL(NotProcessedStatus,'') = 'SCRAP' AND ISNULL(Assy_Auth,0) = 0
								AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode)
						ORDER BY 1

				IF ((OBJECT_ID('tempdb..#STMC_WIPMST_Qty') IS NOT NULL) AND (OBJECT_ID('tempdb..#STMC_Assy_LineAssyStatus_Running_WIP_Qty') IS NOT NULL))
				BEGIN
					SELECT W.Seq, W.LineCode, W.MachineCode, R.Barcode, R.Status, R.FailCount INTO #STMC_Final_Data_Qty FROM #STMC_WIPMST_Qty (NOLOCK) W
						LEFT OUTER JOIN #STMC_Assy_LineAssyStatus_Running_WIP_Qty (NOLOCK) R
							ON W.LineCode = R.LineCode AND W.MachineCode = R.MachineCode
								WHERE ISNULL(R.Status,'') NOT IN ('','PE')
				END

				--SELECT * FROM #Final_Data Order by 1,2,4				

				SET @RowCount_Qty = (SELECT MAX(Seq) FROM #STMC_Final_Data_Qty);
					DECLARE @RowSeq1 INT = 1;
				WHILE @RowSeq1 <= @RowCount_Qty
				BEGIN
					Declare @SecondLastSeq1 INT = 0
					SELECT Top 1 @SecondLastSeq1 = Seq FROM #STMC_WIPMST_Qty Order by Seq Desc
					DELETE FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 AND Barcode IN (SELECT Barcode FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 + 1 AND ISNULL(Status,'') != 'FL')
					DELETE FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 AND Barcode IN (SELECT Barcode FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 + 1 AND ISNULL(Status,'') = 'FL')
					DELETE FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 AND Barcode IN (SELECT Barcode FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 + 1 AND ISNULL(Status,'') = 'FL' AND FailCount = @FailCountDefined) AND Seq != @SecondLastSeq1 - 1
					DELETE FROM #STMC_Final_Data_Qty WHERE Seq = @RowSeq1 + 1 AND ISNULL(Status,'') = 'FL' --AND FailCount = @FailCountDefined 
					SET @RowSeq1 = @RowSeq1 + 1
				END
				--SELECT * FROM #STMC_Final_Data_Qty WHERE MachineCode = (SELECT Top 1 MachineCode FROM MachineMst (NOLOCK) WHERE UPPER(MachineName) = UPPER(@MachineName))
				IF OBJECT_ID('tempdb..#N_Final_Data_Qty_WIP1') IS NOT NULL
				BEGIN
					DROP TABLE #N_Final_Data_Qty_WIP1
				END
				
				SELECT LineCode, MachineCode, Count(*) Qty INTO #N_Final_Data_Qty_WIP1 FROM #STMC_Final_Data_Qty
					Group By LineCode, MachineCode
					
				IF OBJECT_ID('tempdb..#N_Final_Data_Qty_WIP1') IS NOT NULL
				BEGIN
					IF OBJECT_ID('tempdb..#Assy_WIP') IS NOT NULL
					BEGIN
						DROP TABLE #Assy_WIP
					END

					SELECT LineCode, MachineCode, WIPCount INTO #Assy_WIP FROM Assy_WIP WHERE 1 = 2

					INSERT INTO #Assy_WIP
					SELECT Distinct LineCode, MachineCode, 0 FROM #STMC_WIPMST_Qty --ORDER BY Seq ASC

					Update AW SET AW.WIPCount = N.Qty
					FROM #Assy_WIP AW
					JOIN #N_Final_Data_Qty_WIP1 N
					ON AW.LineCode = N.LineCode AND AW.MachineCode = N.MachineCode

					BEGIN TRAN
						TRUNCATE TABLE Assy_WIP
						INSERT INTO Assy_WIP (LineCode, MachineCode, WIPCount)
						SELECT LineCode, MachineCode, WIPCount FROM #Assy_WIP
					COMMIT TRAN
					/*
					TRUNCATE TABLE Assy_WIP
					
					INSERT INTO Assy_WIP
					SELECT Distinct LineCode, MachineCode, 0 FROM #STMC_WIPMST_Qty --ORDER BY Seq ASC

					Update AW SET AW.WIPCount = N.Qty
					FROM Assy_WIP AW
					JOIN #N_Final_Data_Qty_WIP1 N
					ON AW.LineCode = N.LineCode AND AW.MachineCode = N.MachineCode
					*/
				END
			END
			ELSE IF @PartType_WIP IN ('TMC','SERVO','CALIPER')
			BEGIN
				IF OBJECT_ID('tempdb..#N_Final_Data_Qty') IS NOT NULL
				BEGIN
					DROP TABLE #N_Final_Data_Qty
				END
				IF OBJECT_ID('tempdb..#N_WIPMST_Qty') IS NOT NULL
				BEGIN
					DROP TABLE #N_WIPMST_Qty
				END
				SELECT ROW_NUMBER() OVER(ORDER BY OperationSeqNo) Seq, LineCode, Machinecode, OperationSeqNo, WIP_Quantity  
					INTO #N_WIPMST_Qty
						FROM (
							SELECT  ROW_NUMBER() OVER(PARTITION BY RCLW.MachineCode ORDER BY RCLW.OperationSeqNo) AS SeqNo,
									RCLW.LineCode, RCLW.MachineCode, RCLW.OperationSeqNo, RCLW.WIP_Quantity
										FROM RoutingConfigLineWise (NOLOCK) RCLW
										JOIN
										RoutingConfigPartWise (NOLOCK) RCPW
											ON	RCLW.ProfitCenterCode=RCPW.ProfitCenterCode AND
													RCLW.MachineCode = RCPW.MachineCode AND
														RCLW.OperationCode = RCPW.OperationCode AND
															RCLW.Traceability = RCPW.Traceability
																	
										JOIN
										LineMst (NOLOCK) LM
											ON	RCLW.ProfitCenterCode = LM.ProfitCenterCode AND
													RCLW.LineCode = LM.LineCode
											WHERE ISNULL(RCLW.Traceability,0) = 1 AND
													--RCPW.PartNo = (SELECT Top 1 Assy_PartNo FROM ASSY_RUNNINGPART (NOLOCK) WHERE LineCode = @LineCode ORDER BY CreatedDate Desc) AND
													RCPW.PartNo = @PARTNO AND
														RCLW.WIP_Quantity <> 0 AND
															ISNULL(LM.WIPCheck,0) = 1 AND
																ISNULL(LM.isActive,0) = 1 AND
																	ISNULL(RCPW.Traceability,0) = 1
																	-- Added By Rashid For Handling Engraving Station on 10th Sep 2016
																		AND ISNULL(RCLW.Engraving,0) = 0 AND ISNULL(RCPW.Engraving,0) = 0
																			AND LM.ProfitCenterCode = @ProfitCenterCode
																				AND LM.LineCode = @LineCode
																					
										) Source WHERE SeqNo = 1
			
				IF OBJECT_ID('tempdb..#N_Assy_LineAssyStatus_Running_WIP_Qty') IS NOT NULL
				BEGIN
					DROP TABLE #N_Assy_LineAssyStatus_Running_WIP_Qty
				END

				SELECT LineCode, MachineCode, Barcode, Status, FailCount INTO #N_Assy_LineAssyStatus_Running_WIP_Qty FROM Assy_LineAssyStatus_Running (NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(Status,'') NOT IN ('','PE') AND Datecode != 'PKYK'
						AND Barcode NOT IN (SELECT Distinct Barcode FROM Assy_TallyChartStatusData WITH (NOLOCK)
							WHERE ISNULL(Result,'') = '' AND ISNULL(NotProcessedStatus,'') = 'SCRAP' AND ISNULL(Assy_Auth,0) = 0
								AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode)
						ORDER BY 1

				IF ((OBJECT_ID('tempdb..#N_WIPMST_Qty') IS NOT NULL) AND (OBJECT_ID('tempdb..#N_Assy_LineAssyStatus_Running_WIP_Qty') IS NOT NULL))
				BEGIN
					SELECT W.Seq, W.LineCode, W.MachineCode, R.Barcode, R.Status, R.FailCount INTO #N_Final_Data_Qty FROM #N_WIPMST_Qty (NOLOCK) W
						LEFT OUTER JOIN #N_Assy_LineAssyStatus_Running_WIP_Qty (NOLOCK) R
							ON W.LineCode = R.LineCode AND W.MachineCode = R.MachineCode
								WHERE ISNULL(R.Status,'') NOT IN ('','PE')
				END

				--SELECT * FROM #Final_Data Order by 1,2,4
				--SELECT * FROM #N_Final_Data_Qty
				SET @RowCount_Qty = (SELECT MAX(Seq) FROM #N_Final_Data_Qty);
				DECLARE @RowSeq_TMC1 INT = 1;
				WHILE @RowSeq_TMC1 <= @RowCount_Qty
				BEGIN
					Declare @SecondLastSeq_TMC1 INT = 0
					SELECT Top 1 @SecondLastSeq_TMC1 = Seq FROM #N_WIPMST_Qty Order by Seq Desc
					DELETE FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 AND Barcode IN (SELECT Barcode FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 + 1 AND ISNULL(Status,'') != 'FL')
					DELETE FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 AND Barcode IN (SELECT Barcode FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 + 1 AND ISNULL(Status,'') = 'FL')
					DELETE FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 AND Barcode IN (SELECT Barcode FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 + 1 AND ISNULL(Status,'') = 'FL' AND FailCount = @FailCountDefined) AND Seq != @SecondLastSeq_TMC1 - 1
					DELETE FROM #N_Final_Data_Qty WHERE Seq = @RowSeq_TMC1 + 1 AND ISNULL(Status,'') = 'FL' --AND FailCount = @FailCountDefined 
					SET @RowSeq_TMC1 = @RowSeq_TMC1 + 1
				END
				--SELECT * FROM #N_Final_Data_Qty WHERE MachineCode = (SELECT Top 1 MachineCode FROM MachineMst (NOLOCK) WHERE UPPER(MachineName) = UPPER(@MachineName))
					IF OBJECT_ID('tempdb..#N_Final_Data_Qty_WIP') IS NOT NULL
					BEGIN
						DROP TABLE #N_Final_Data_Qty_WIP
					END
					--SELECT * FROM #N_Final_Data_Qty
					SELECT LineCode, MachineCode, Count(*) Qty INTO #N_Final_Data_Qty_WIP FROM #N_Final_Data_Qty
						Group By LineCode, MachineCode
					
					IF OBJECT_ID('tempdb..#N_Final_Data_Qty_WIP') IS NOT NULL
					BEGIN
						IF OBJECT_ID('tempdb..#Assy_WIP1') IS NOT NULL
						BEGIN
							DROP TABLE #Assy_WIP1
						END

						SELECT LineCode, MachineCode, WIPCount INTO #Assy_WIP1 FROM Assy_WIP WHERE 1 = 2

						INSERT INTO #Assy_WIP1
						SELECT Distinct LineCode, MachineCode, 0 FROM #N_WIPMST_Qty --ORDER BY Seq ASC

						Update AW SET AW.WIPCount = N.Qty
						FROM #Assy_WIP1 AW
						JOIN #N_Final_Data_Qty_WIP N
						ON AW.LineCode = N.LineCode AND AW.MachineCode = N.MachineCode

						BEGIN TRAN
							TRUNCATE TABLE Assy_WIP
							INSERT INTO Assy_WIP (LineCode, MachineCode, WIPCount)
							SELECT LineCode, MachineCode, WIPCount FROM #Assy_WIP1
						COMMIT TRAN
						/*
						TRUNCATE TABLE Assy_WIP
					
						INSERT INTO Assy_WIP
						SELECT Distinct LineCode, MachineCode, 0 FROM #N_WIPMST_Qty --ORDER BY Seq ASC

						Update AW SET AW.WIPCount = N.Qty
						FROM Assy_WIP AW
						JOIN #N_Final_Data_Qty_WIP N
						ON AW.LineCode = N.LineCode AND AW.MachineCode = N.MachineCode
						*/
					END
			END
		END
	END
    ELSE IF @CONDITION = 'VALIDATE_WIP' 
    BEGIN 
		IF EXISTS(SELECT Top 1 1 FROM LineMst (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE AND LineCode = @LINECODE AND ISNULL(WIPCheck,0) = 1)
		BEGIN
			-- Added By Rashid Siddiqui For Handling WIP On timer and First Station -- 07th October 2016
			SET @CONDITION = 'UPDATE_WIP_COUNT'
			EXEC Assy_Proc_WIP_Manage  @CONDITION ='UPDATE_WIP_COUNT', @LINECODE = @LINECODE, @PROFITCENTERCODE = @PROFITCENTERCODE

			  SELECT DISTINCT @WIPDEFINEDQTY = ISNULL(L.WIP_QUANTITY, 0)
					FROM ROUTINGCONFIGLINEWISE(NOLOCK) L 
						INNER JOIN ROUTINGCONFIGPARTWISE (NOLOCK) P 
							ON L.PROFITCENTERCODE = P.PROFITCENTERCODE AND L.OPERATIONCODE = P.OPERATIONCODE AND L.MACHINECODE = P.MACHINECODE
						INNER JOIN LINEMST (NOLOCK) LM ON L.LINECODE = LM.LINECODE
							WHERE LM.LINECODE = @LINECODE
								AND P.PARTNO = (SELECT TOP 1 ASSY_PARTNO FROM ASSY_RUNNINGPART (NOLOCK) WHERE ProfitCenterCode = @PROFITCENTERCODE AND LINECODE = @LINECODE ORDER BY CREATEDDATE DESC )
								AND L.TRACEABILITY = 1
								AND L.WIP_QUANTITY <> 0
								AND LM.WIPCHECK = 1
								AND LM.ISACTIVE = 1
								AND P.TRACEABILITY = 1
								AND L.MACHINECODE = @MACHINECODE
								AND LM.ProfitCenterCode = @PROFITCENTERCODE
								-- Added By Rashid For Handling Engraving Station on 10th Sep 2016
								AND ISNULL(L.Engraving,0) = 0 AND ISNULL(P.Engraving,0) = 0

			  /* COMMENT BY RASHID ON 9TH OCT 2015
			  SELECT DISTINCT @WIPDEFINEDQTY = ISNULL(L.WIP_QUANTITY, 0) 
			  FROM   ROUTINGCONFIGLINEWISE(NOLOCK) L 
					 INNER JOIN LINEMST(NOLOCK) LM 
							 ON L.LINECODE = LM.LINECODE 
			  WHERE  L.TRACEABILITY = 1 
					 AND L.WIP_QUANTITY <> 0 
					 AND LM.WIPCHECK = 1 
					 AND LM.ISACTIVE = 1 
					 AND LM.LINECODE = @LINECODE 
					 AND L.MACHINECODE = @MACHINECODE 
			  */

			  IF @WIPDEFINEDQTY IS NULL 
				  OR @WIPDEFINEDQTY = '' 
				BEGIN 
					SET @RETURNVALUE = 'WIP_NOT_APPLICABLE' 
					SET @RETURNINT = 1 

					RETURN 
				END 

			  --FOR FINAL QC STATION NO NEED TO VALIDATE WIP               
			  IF @MACHINECODE = @FINALVIEWING_MACHINECODE 
				BEGIN 
					SET @RETURNVALUE = 'WIP_NOT_APPLICABLE' 
					SET @RETURNINT = 1 

					RETURN 
				END 

			  IF( (SELECT ISNULL(WIPCOUNT, 0) 
				   FROM   ASSY_WIP(NOLOCK) 
				   WHERE  MACHINECODE = @MACHINECODE) >= @WIPDEFINEDQTY ) 
				BEGIN 
					SET @RETURNVALUE = 'WIP_LIMIT_HAS_REACHED' 
					SET @RETURNINT = 1 

					RETURN 
				END 
			  ELSE 
				BEGIN 
					SET @RETURNVALUE = 'WIP_OK' 
					SET @RETURNINT = 1 

					RETURN 
				END
		END
		ELSE
		BEGIN
				SET @RETURNVALUE = 'WIP_OK' 
				SET @RETURNINT = 1 
				RETURN
		END
    END
    ELSE IF @CONDITION = 'VALIDATE_WIP_FIFO_BARCODE' 
    BEGIN 
          SET @RETURNVALUE = '' 
          SET @RETURNINT = -1 

          IF OBJECT_ID('TEMPDB..#TEMP_TBL_NEW') IS NOT NULL 
            DROP TABLE #TEMP_TBL_NEW 

          --CHECK WIP FIFO IS APLICABLE FOR THIS LINE,IF NOT SIMPLY RETURN 
          IF NOT EXISTS (SELECT TOP 1 1 
                         FROM   LINEMST(NOLOCK) 
                         WHERE  LINECODE = @LINECODE 
                                AND ISNULL(WIPFIFOCHECK, 0) = 1 
                                AND ISACTIVE = 1) 
            BEGIN 
                SET @RETURNVALUE = 'WIP_FIFO_OK' 
                SET @RETURNINT = 1 

                RETURN 
            END 

		  /* COMMENT BY RASHID ON 9TH OCT 2015
          --CHECK WIP FIFO IS APLICABLE FOR THIS MACHINE IN ROUTING,IF NOT SIMPLY RETURN 
          IF NOT EXISTS (SELECT TOP 1 1 
                         FROM   ROUTINGCONFIGLINEWISE(NOLOCK) 
                         WHERE  LINECODE = @LINECODE 
                                AND MACHINECODE = @MACHINECODE 
                                AND ISNULL(WIPFIFOCHECK, 0) = 1 
                                AND TRACEABILITY = 1)
			*/
			IF NOT EXISTS (SELECT TOP 1 1 
                        FROM   ROUTINGCONFIGLINEWISE(NOLOCK) R
						INNER JOIN ROUTINGCONFIGPARTWISE (NOLOCK) P 
						ON R.PROFITCENTERCODE = P.PROFITCENTERCODE AND R.OPERATIONCODE = P.OPERATIONCODE AND R.MACHINECODE = P.MACHINECODE 
                           WHERE  R.LINECODE = @LINECODE 
                                  AND R.MACHINECODE = @MACHINECODE 
                                  AND ISNULL(R.WIPFIFOCHECK, 0) = 1
                                  AND R.TRACEABILITY = 1
								  AND P.TRACEABILITY = 1
								  -- Added By Rashid For Handling Engraving Station on 10th Sep 2016
								AND ISNULL(R.Engraving,0) = 0 AND ISNULL(P.Engraving,0) = 0)					 
            BEGIN 
                SET @RETURNVALUE = 'WIP_FIFO_OK' 
                SET @RETURNINT = 1 

                RETURN 
            END 

          EXEC ASSY_PROC_WIP_GET_PREVIOUSSTATION_MACHINECODE 
            @CONDITION = 'WIP_FIFO_PREVIOUS_STATION', 
            @LINECODE = @LINECODE, 
            @MACHINECODE = @MACHINECODE, 
            @PREVMACHINECODE = @PREVMACHINECODE OUT, 
            @RETURNINT = @RETURNINT OUT 

          IF @PREVMACHINECODE IS NOT NULL 
              OR @PREVMACHINECODE <> '' 
            BEGIN 
                DECLARE @ID INT 

                SELECT ROW_NUMBER () 
                         OVER( 
                           ORDER BY CONVERT(INT, SUBSTRING(BARCODE, 13, 8))) ID, 
                       BARCODE 
                INTO   #TEMP_TBL_NEW 
                FROM   ASSY_WIPFIFOCHECK(NOLOCK) 
                WHERE  LINECODE = @LINECODE 
                       AND MACHINECODE = @PREVMACHINECODE 
                       AND ( ISNULL(NEXTSTATIONOPERATIONCODE, '') = 
                             @NEXTSTATIONOPERATIONCODE 
                              OR ISNULL(NEXTSTATIONOPERATIONCODE, '') = '' ) 

                SELECT @ID = ID 
                FROM   #TEMP_TBL_NEW(NOLOCK) 
                WHERE  BARCODE = @BARCODE 

                IF @ID = 1 
                  BEGIN 
                      SET @RETURNVALUE = 'WIP_FIFO_OK' 
                      SET @RETURNINT = 1 
                  END 
                ELSE 
                  BEGIN 
                      SET @RETURNVALUE= 'WIP_FIFO_NOTOK|' 
                                        + (SELECT BARCODE 
                                           FROM   #TEMP_TBL_NEW(NOLOCK) 
                                           WHERE  ID = 1) 
                      SET @RETURNINT = 1 
                  END 

                RETURN 
            END 
          ELSE 
            BEGIN 
                SET @RETURNVALUE = 'WIP_FIFO_OK' 
                SET @RETURNINT = 1 
            END 
      END 
    ELSE IF @CONDITION = 'RESET_WIP_RELEATED_TABLES' 
    BEGIN 
          DELETE FROM ASSY_WIP 
          WHERE  LINECODE = @LINECODE 

          DELETE FROM ASSY_WIPFIFOCHECK 
          WHERE  LINECODE = @LINECODE 

          SET @RETURNVALUE = 'RESET_WIP_RELEATED_TABLES' 
          SET @RETURNINT = 1 

          RETURN 
      END 
    ELSE IF @CONDITION = 'UPDATE_NEXTSTATION_OPERATIONCODE' 
    BEGIN 
          EXEC ASSY_PROC_WIP_GET_PREVIOUSSTATION_MACHINECODE 
            @CONDITION = 'WIP_PREVIOUS_STATION', 
            @LINECODE = @LINECODE, 
            @MACHINECODE = @MACHINECODE, 
            @PREVMACHINECODE = @PREVMACHINECODE OUT, 
            @RETURNINT = @RETURNINT OUT 

          IF @PREVMACHINECODE IS NOT NULL 
              OR @PREVMACHINECODE <> '' 
            BEGIN 
                UPDATE ASSY_WIPFIFOCHECK 
                SET    NEXTSTATIONOPERATIONCODE = NULL 
                WHERE  LINECODE = @LINECODE 
                       AND MACHINECODE = @PREVMACHINECODE 
                       AND NEXTSTATIONOPERATIONCODE = @NEXTSTATIONOPERATIONCODE 

                UPDATE ASSY_WIPFIFOCHECK 
                SET    NEXTSTATIONOPERATIONCODE = @NEXTSTATIONOPERATIONCODE 
                WHERE  LINECODE = @LINECODE 
                       AND MACHINECODE = @PREVMACHINECODE 
                       AND BARCODE = @BARCODE 

                SET @RETURNVALUE = 'NEXTSTATION_OPERATIONCODE_UPDATED' 
                SET @RETURNINT = 1 
            END 
      END
	ELSE IF @CONDITION = 'SELECT_WIP_BARCODE'
	BEGIN 
		IF (SELECT Top 1 ISNULL(WIPCheck,0) FROM LINEMST(NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode) = 1
		BEGIN
			Declare @PartType VARCHAR(30) = ''
			SELECT Top 1 @PartType = LTRIM(RTRIM(PartType)), @PARTNO = Assy_PartNo FROM Assy_RunningPart (NOLOCK) WHERE LineCode = @LineCode AND ProfitCenterCode = @ProfitCenterCode
			IF @PartType = 'STMC'
			BEGIN
				IF OBJECT_ID('tempdb..#STMC_Final_Data') IS NOT NULL
				BEGIN
					DROP TABLE #STMC_Final_Data
				END
				IF OBJECT_ID('tempdb..#STMC_WIPMST') IS NOT NULL
				BEGIN
					DROP TABLE #STMC_WIPMST
				END
				SELECT ROW_NUMBER() OVER(ORDER BY OperationSeqNo) Seq, LineCode, Machinecode, OperationSeqNo, WIP_Quantity  
					INTO #STMC_WIPMST
						FROM (
							SELECT  ROW_NUMBER() OVER(PARTITION BY RCLW.MachineCode ORDER BY RCLW.OperationSeqNo) AS SeqNo,
									RCLW.LineCode, RCLW.MachineCode, RCLW.OperationSeqNo, RCLW.WIP_Quantity
										FROM RoutingConfigLineWise (NOLOCK) RCLW
										JOIN
										RoutingConfigPartWise (NOLOCK) RCPW
											ON	RCLW.ProfitCenterCode=RCPW.ProfitCenterCode AND
													RCLW.MachineCode = RCPW.MachineCode AND
														RCLW.OperationCode = RCPW.OperationCode AND
															RCLW.Traceability = RCPW.Traceability
																	
										JOIN
										LineMst (NOLOCK) LM
											ON	RCLW.ProfitCenterCode = LM.ProfitCenterCode AND
													RCLW.LineCode = LM.LineCode
											WHERE ISNULL(RCLW.Traceability,0) = 1 AND
													--RCPW.PartNo = (SELECT Top 1 Assy_PartNo FROM ASSY_RUNNINGPART (NOLOCK) WHERE LineCode = @LineCode ORDER BY CreatedDate Desc) AND
													RCPW.PartNo = @PARTNO AND
														RCLW.WIP_Quantity <> 0 AND
															ISNULL(LM.WIPCheck,0) = 1 AND
																ISNULL(LM.isActive,0) = 1 AND
																	ISNULL(RCPW.Traceability,0) = 1
																	-- Added By Rashid For Handling Engraving Station on 10th Sep 2016
																		AND ISNULL(RCLW.Engraving,0) = 0 AND ISNULL(RCPW.Engraving,0) = 0
																			AND LM.ProfitCenterCode = @ProfitCenterCode
																				AND LM.LineCode = @LineCode
																					
										) Source WHERE SeqNo = 1
			
				IF OBJECT_ID('tempdb..#STMC_Assy_LineAssyStatus_Running_WIP') IS NOT NULL
				BEGIN
					DROP TABLE #STMC_Assy_LineAssyStatus_Running_WIP
				END
				--Change WIP Logic By Rashid Siddiqui 23rd Dec 2016 Due to Nissan Line 6 Barcode WHEN CHARINDEX(@LineCode,Barcode) = 0 THEN RIGHT(Barcode,4) AND MachineCode != 'MCENGSTN'
				SELECT LineCode, MachineCode, Case WHEN CHARINDEX(':',Barcode) > 0 THEN RIGHT(Barcode,4) WHEN CHARINDEX(@LineCode,Barcode) = 0 THEN RIGHT(Barcode,4) ELSE LEFT(RIGHT(Barcode,6),4) END Barcode, Status, FailCount 
				INTO #STMC_Assy_LineAssyStatus_Running_WIP FROM Assy_LineAssyStatus_Running (NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(Status,'') NOT IN ('','PE') AND Datecode != 'PKYK' AND MachineCode != 'MCENGSTN' 
						AND Barcode NOT IN (SELECT Distinct Barcode FROM Assy_TallyChartStatusData WITH (NOLOCK)
							WHERE ISNULL(Result,'') = '' AND ISNULL(NotProcessedStatus,'') = 'SCRAP' AND ISNULL(Assy_Auth,0) = 0
								AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode)
						ORDER BY 1

				IF ((OBJECT_ID('tempdb..#STMC_WIPMST') IS NOT NULL) AND (OBJECT_ID('tempdb..#STMC_Assy_LineAssyStatus_Running_WIP') IS NOT NULL))
				BEGIN
					SELECT W.Seq, W.LineCode, W.MachineCode, R.Barcode, R.Status, R.FailCount INTO #STMC_Final_Data FROM #STMC_WIPMST (NOLOCK) W
						LEFT OUTER JOIN #STMC_Assy_LineAssyStatus_Running_WIP (NOLOCK) R
							ON W.LineCode = R.LineCode AND W.MachineCode = R.MachineCode
								WHERE ISNULL(R.Status,'') NOT IN ('','PE')
				END

				--SELECT * FROM #Final_Data Order by 1,2,4

				SET @RowCount = (SELECT MAX(Seq) FROM #STMC_Final_Data);
					DECLARE @RowSeq INT = 1;
				WHILE @RowSeq <= @RowCount
				BEGIN
					Declare @SecondLastSeq INT = 0
					SELECT Top 1 @SecondLastSeq = Seq FROM #STMC_WIPMST Order by Seq Desc
					DELETE FROM #STMC_Final_Data WHERE Seq = @RowSeq AND Barcode IN (SELECT Barcode FROM #STMC_Final_Data WHERE Seq = @RowSeq + 1 AND ISNULL(Status,'') != 'FL')
					DELETE FROM #STMC_Final_Data WHERE Seq = @RowSeq AND Barcode IN (SELECT Barcode FROM #STMC_Final_Data WHERE Seq = @RowSeq + 1 AND ISNULL(Status,'') = 'FL')
					DELETE FROM #STMC_Final_Data WHERE Seq = @RowSeq AND Barcode IN (SELECT Barcode FROM #STMC_Final_Data WHERE Seq = @RowSeq + 1 AND ISNULL(Status,'') = 'FL' AND FailCount = @FailCountDefined) AND Seq != @SecondLastSeq - 1
					DELETE FROM #STMC_Final_Data WHERE Seq = @RowSeq + 1 AND ISNULL(Status,'') = 'FL' --AND FailCount = @FailCountDefined 
					SET @RowSeq = @RowSeq + 1
				END
				--SELECT * FROM #STMC_Final_Data WHERE MachineCode = (SELECT Top 1 MachineCode FROM MachineMst (NOLOCK) WHERE UPPER(MachineName) = UPPER(@MachineName))
				SELECT S.Seq, S.LineCode, (SELECT Top 1 MachineName FROM MachineMst (NOLOCK) WHERE MachineCode = S.MachineCode) MachineCode, R.Barcode, S.Status, S.FailCount FROM #STMC_Final_Data S
				JOIN Assy_LineAssyStatus_Running R
				--Change WIP Logic By Rashid Siddiqui 23rd Dec 2016 Due to Nissan Line 6 Barcode WHEN CHARINDEX(@LineCode,Barcode) = 0 THEN RIGHT(Barcode,4)
				ON S.LineCode = R.LineCode AND S.MachineCode = R.MachineCode AND S.Barcode = Case WHEN CHARINDEX(':',R.Barcode) > 0 THEN RIGHT(R.Barcode,4) WHEN CHARINDEX(R.LineCode,R.Barcode) = 0 THEN RIGHT(R.Barcode,4) ELSE LEFT(RIGHT(R.Barcode,6),4) END
				WHERE S.MachineCode = (SELECT Top 1 MachineCode FROM MachineMst (NOLOCK) WHERE UPPER(MachineName) = UPPER(@MachineName)) Order by 1,4
			END
			ELSE IF @PartType IN ('TMC','SERVO','CALIPER')
			BEGIN
				IF OBJECT_ID('tempdb..#N_Final_Data') IS NOT NULL
				BEGIN
					DROP TABLE #N_Final_Data
				END
				IF OBJECT_ID('tempdb..#N_WIPMST') IS NOT NULL
				BEGIN
					DROP TABLE #N_WIPMST
				END
				print 1
				SELECT ROW_NUMBER() OVER(ORDER BY OperationSeqNo) Seq, LineCode, Machinecode, OperationSeqNo, WIP_Quantity  
					INTO #N_WIPMST
						FROM (
							SELECT  ROW_NUMBER() OVER(PARTITION BY RCLW.MachineCode ORDER BY RCLW.OperationSeqNo) AS SeqNo,
									RCLW.LineCode, RCLW.MachineCode, RCLW.OperationSeqNo, RCLW.WIP_Quantity
										FROM RoutingConfigLineWise (NOLOCK) RCLW
										JOIN
										RoutingConfigPartWise (NOLOCK) RCPW
											ON	RCLW.ProfitCenterCode=RCPW.ProfitCenterCode AND
													RCLW.MachineCode = RCPW.MachineCode AND
														RCLW.OperationCode = RCPW.OperationCode AND
															RCLW.Traceability = RCPW.Traceability
																	
										JOIN
										LineMst (NOLOCK) LM
											ON	RCLW.ProfitCenterCode = LM.ProfitCenterCode AND
													RCLW.LineCode = LM.LineCode
											WHERE ISNULL(RCLW.Traceability,0) = 1 AND
													--RCPW.PartNo = (SELECT Top 1 Assy_PartNo FROM ASSY_RUNNINGPART (NOLOCK) WHERE LineCode = @LineCode ORDER BY CreatedDate Desc) AND
													RCPW.PartNo = @PARTNO AND
														RCLW.WIP_Quantity <> 0 AND
															ISNULL(LM.WIPCheck,0) = 1 AND
																ISNULL(LM.isActive,0) = 1 AND
																	ISNULL(RCPW.Traceability,0) = 1
																	-- Added By Rashid For Handling Engraving Station on 10th Sep 2016
																		AND ISNULL(RCLW.Engraving,0) = 0 AND ISNULL(RCPW.Engraving,0) = 0
																			AND LM.ProfitCenterCode = @ProfitCenterCode
																				AND LM.LineCode = @LineCode
																					
										) Source WHERE SeqNo = 1
				
				IF OBJECT_ID('tempdb..#N_Assy_LineAssyStatus_Running_WIP') IS NOT NULL
				BEGIN
					DROP TABLE #N_Assy_LineAssyStatus_Running_WIP
				END

				SELECT LineCode, MachineCode, Barcode, Status, FailCount INTO #N_Assy_LineAssyStatus_Running_WIP FROM Assy_LineAssyStatus_Running (NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode AND ISNULL(Status,'') NOT IN ('','PE') AND Datecode != 'PKYK'
						AND Barcode NOT IN (SELECT Distinct Barcode FROM Assy_TallyChartStatusData WITH (NOLOCK)
							WHERE ISNULL(Result,'') = '' AND ISNULL(NotProcessedStatus,'') = 'SCRAP' AND ISNULL(Assy_Auth,0) = 0
								AND ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode)
						ORDER BY 1

						

				IF ((OBJECT_ID('tempdb..#N_WIPMST') IS NOT NULL) AND (OBJECT_ID('tempdb..#N_Assy_LineAssyStatus_Running_WIP') IS NOT NULL))
				BEGIN
					SELECT W.Seq, W.LineCode, W.MachineCode, R.Barcode, R.Status, R.FailCount INTO #N_Final_Data FROM #N_WIPMST (NOLOCK) W
						LEFT OUTER JOIN #N_Assy_LineAssyStatus_Running_WIP (NOLOCK) R
							ON W.LineCode = R.LineCode AND W.MachineCode = R.MachineCode
								WHERE ISNULL(R.Status,'') NOT IN ('','PE')
				END

				
				--SELECT * FROM #Final_Data Order by 1,2,4

				SET @RowCount = (SELECT MAX(Seq) FROM #N_Final_Data);
				DECLARE @RowSeq_TMC INT = 1;
				WHILE @RowSeq_TMC <= @RowCount
				BEGIN
					Declare @SecondLastSeq_TMC INT = 0
					SELECT Top 1 @SecondLastSeq_TMC = Seq FROM #N_WIPMST Order by Seq Desc
					DELETE FROM #N_Final_Data WHERE Seq = @RowSeq_TMC AND Barcode IN (SELECT Barcode FROM #N_Final_Data WHERE Seq = @RowSeq_TMC + 1 AND ISNULL(Status,'') != 'FL')
					DELETE FROM #N_Final_Data WHERE Seq = @RowSeq_TMC AND Barcode IN (SELECT Barcode FROM #N_Final_Data WHERE Seq = @RowSeq_TMC + 1 AND ISNULL(Status,'') = 'FL')
					DELETE FROM #N_Final_Data WHERE Seq = @RowSeq_TMC AND Barcode IN (SELECT Barcode FROM #N_Final_Data WHERE Seq = @RowSeq_TMC + 1 AND ISNULL(Status,'') = 'FL' AND FailCount = @FailCountDefined) AND Seq != @SecondLastSeq_TMC - 1
					DELETE FROM #N_Final_Data WHERE Seq = @RowSeq_TMC + 1 AND ISNULL(Status,'') = 'FL' --AND FailCount = @FailCountDefined 
					SET @RowSeq_TMC = @RowSeq_TMC + 1
				END
				SELECT F.Seq, F.LineCode, M.MachineName, F.Barcode, F.Status, F.FailCount FROM #N_Final_Data F
				JOIN MachineMst M
				ON M.MachineCode = F.MachineCode
				WHERE UPPER(M.MachineName) = UPPER(@MachineName)
				Order by 1,4
			END
		END
	END
	ELSE IF @CONDITION = 'WIP_STATUS_LINEMST'
	BEGIN 
		Declare @WIPStatus INT = 0
		SELECT Top 1 @WIPStatus = ISNULL(WIPCheck,0) FROM LineMst (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode
		IF (@WIPStatus = 1)
			SET @RETURNVALUE = 'Y'
		ELSE
			SET @RETURNVALUE = 'N'
         
		 SET @RETURNINT = 1
	END

	END TRY
	BEGIN CATCH
		SET @ReturnValue = 	CAST(ERROR_NUMBER() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_SEVERITY()AS VARCHAR(5)) + '|' + 
		CAST(ERROR_STATE() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_PROCEDURE() AS VARCHAR(200)) + '|' + 
		CAST(ERROR_LINE() AS VARCHAR(5)) + '|' + 
		CAST(ERROR_MESSAGE() AS VARCHAR(1500))
		ROLLBACK TRAN
		SET @ReturnInt = 2
		RAISERROR(@ReturnValue, 16, 1)
	END CATCH
END








