/****** Object:  StoredProcedure [dbo].[ASSY_PROC_WRITEOPCTAGSAUTO]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/***************************************************************************************                    
PROCEDURE         :     ASSY_PROC_WRITEOPCTAGSAUTO
AUTHOR            :     SACHIN KUMAR
DATE WRITTEN      :     02/06/2017
PURPOSE           :     

TEST SCRIPT  

exec [ASSY_PROC_WRITEOPCTAGSAUTO] @P_Mode='WRITE_STATUS',@PROFITCENTERCODE='0030',@LINECODE='I09',@P_MachineCode='MC40',@VALUE='XYZ'

****************************************************************************************/
CREATE PROCEDURE [dbo].[ASSY_PROC_WRITEOPCTAGSAUTO]
(
  @P_Mode varchar(50) ='',
  @PROFITCENTERCODE varchar(10) = '',
  @LINECODE  varchar(10) = '',
  @P_MachineCode varchar(10)='',
  @OPERATION_CODE varchar(10) ='',
  @VALUE varchar(50) ='',
  @ReturnValue VARCHAR (2000)=NULL OUT,
  @ReturnInt INT=NULL OUT
  
)
AS
BEGIN

IF(@P_Mode='WRITE_STATUS')
BEGIN
					delete from WriteOPCTagsAuto where ProfitCenterCode=@PROFITCENTERCODE AND LineCode=@LINECODE AND MachineCode=@P_MachineCode and
					TagType='WRITE_STATUS'

					insert into WriteOPCTagsAuto
					SELECT m.ProfitCenterCode,m.LineCode,m.MachineCode,m.OperationCode,m.ChannelName,m.DeviceName,
					t.TagName,t.TagType,@VALUE,0,'ADMIN',getdate(),'ADMIN',getdate()
					FROM ASSY_TD_OPERATION_TABLE_MAPPING(nolock) m inner join MachineTagDecisionMapping(nolock) t
					on 
					m.ProfitCenterCode = t.ProfitCenterCode and
					m.LineCode = t.LineCode and
					m.MachineCode = t.MachineCode and
					m.OperationCode = t.OperationCode
					WHERE m.ProfitCenterCode=@PROFITCENTERCODE AND m.LineCode=@LINECODE AND m.MachineCode=@P_MachineCode and
					t.TagType='WRITE_STATUS'

END 

IF(@P_Mode='WRITE_BARCODE')
BEGIN
					delete from WriteOPCTagsAuto where ProfitCenterCode=@PROFITCENTERCODE AND LineCode=@LINECODE AND MachineCode=@P_MachineCode and
					TagType='WRITE_BARCODE'

					insert into WriteOPCTagsAuto
					SELECT m.ProfitCenterCode,m.LineCode,m.MachineCode,m.OperationCode,m.ChannelName,m.DeviceName,
					t.TagName,t.TagType,@VALUE,0,'ADMIN',getdate(),'ADMIN',getdate()
					FROM ASSY_TD_OPERATION_TABLE_MAPPING(nolock) m inner join MachineTagDecisionMapping(nolock) t
					on 
					m.ProfitCenterCode = t.ProfitCenterCode and
					m.LineCode = t.LineCode and
					m.MachineCode = t.MachineCode and
					m.OperationCode = t.OperationCode
					WHERE m.ProfitCenterCode=@PROFITCENTERCODE AND m.LineCode=@LINECODE AND m.MachineCode=@P_MachineCode and
					t.TagType='WRITE_BARCODE'

END 


IF(@P_Mode='WRITE_SHOE_BARCODE')
BEGIN
					delete from WriteOPCTagsAuto where ProfitCenterCode=@PROFITCENTERCODE AND LineCode=@LINECODE AND MachineCode=@P_MachineCode and
					TagType='WRITE_SHOE_BARCODE'

					insert into WriteOPCTagsAuto
					SELECT m.ProfitCenterCode,m.LineCode,m.MachineCode,m.OperationCode,m.ChannelName,m.DeviceName,
					t.TagName,t.TagType,@VALUE,0,'ADMIN',getdate(),'ADMIN',getdate()
					FROM ASSY_TD_OPERATION_TABLE_MAPPING(nolock) m inner join MachineTagDecisionMapping(nolock) t
					on 
					m.ProfitCenterCode = t.ProfitCenterCode and
					m.LineCode = t.LineCode and
					m.MachineCode = t.MachineCode and
					m.OperationCode = t.OperationCode
					WHERE m.ProfitCenterCode=@PROFITCENTERCODE AND m.LineCode=@LINECODE AND m.MachineCode=@P_MachineCode and
					t.TagType='WRITE_SHOE_BARCODE'

END 

IF(@P_Mode='GetWRITEOPCTAGSAUTO')
BEGIN
		select ChannelName,DeviceName,TagName,TagValue from 
		WriteOPCTagsAuto(nolock) where ProfitCenterCode=@PROFITCENTERCODE AND LineCode=@LINECODE AND MachineCode=@P_MachineCode 
		AND sts_cd=0
END

IF(@P_Mode='DEL')
BEGIN
		delete from WriteOPCTagsAuto where ProfitCenterCode=@PROFITCENTERCODE AND LineCode=@LINECODE AND 
		MachineCode=@P_MachineCode AND TagName=@VALUE
					
END


END



GO
/****** Object:  StoredProcedure [dbo].[Assy_ProductionOrderPull]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
		
 /*
 Written by Nelson
    
 */
CREATE PROCEDURE [dbo].[Assy_ProductionOrderPull]
      @OrderNo                  NVARCHAR(10),	--Order No which the user enter
      @WH_CODE                  VARCHAR(4),		-- Profit Center Code
      @PartNo                   NVARCHAR(10) = NULL,	 
      @Validate_ProductionOrder VARCHAR(50) = NULL,
      @Splitchar                NVARCHAR(100) = NULL,
      @PrintParNo               NVARCHAR(100) = NULL,
      @UserId                   NVARCHAR(50),		 --UserId of who logged in
      @ReturnValue              VARCHAR(2000) = NULL OUT,
      @ReturnInt                INT = NULL OUT
AS
    BEGIN
    BEGIN TRY
        SELECT @Validate_ProductionOrder = [dbo].[FN_Validate_ProductionOrder]( @WH_CODE, @OrderNo );  --Fuction  which is written by Jogender
        PRINT @Validate_ProductionOrder;
        SELECT @Splitchar = SUBSTRING(@Validate_ProductionOrder, 0, CHARINDEX('|', @Validate_ProductionOrder));
        SELECT @PrintParNo = SUBSTRING(@Validate_ProductionOrder, CHARINDEX('|', @Validate_ProductionOrder)+1, 100);
        IF( @Splitchar = '' )
            BEGIN
                SET @Splitchar = @Validate_ProductionOrder;
            END;
            IF( @Splitchar = 'ASSY_EXISTS' )
                BEGIN
                    SET @ReturnValue = 'Order No.Exists';
                    PRINT @ReturnValue;
                END;
                IF( @Splitchar = 'PROD_CONF_FAILED' )
                    BEGIN
                        SET @Returnvalue = 'Production Confirmation Pending for this Part No. ' + @PrintParNo;
                        PRINT @Returnvalue;
                    END;
                    IF( @Splitchar = 'ERP_LOG_EXISTS' )
                        BEGIN
                            SET @ReturnValue = @PrintParNo + '  IS DATA_PULL_ID IN WHICH DATA IS ALREADY PULLED';
                            PRINT @ReturnValue;
                            PRINT 'Production Order Data Procedure Initiated';
                            EXEC [DBO].[PROC_ERP_PRODUCTION_ORDER_DATA] 'BD01', @WH_CODE, @UserId, @PrintParNo, @OrderNo;
                        END;
                        IF( @Splitchar = 'NOT_EXISTS' )
                            BEGIN
                                PRINT 'PROC_ERP_DATA_REPLICATION_1 Procedure Initiated';
						  print @WH_CODE;
						  print @UserId;
						  print @OrderNo;
                                EXEC PROC_ERP_DATA_REPLICATION_1 @P_WH_CODE =@WH_CODE, @P_PLANT_CODE='BD01', @P_ERP_TABLE_NAME='|ERP_PRODUCTION_ORDER_DATA|',@P_USERNAME=@UserId, @P_DATA=@OrderNo,@P_DATE='';
                                SET @ReturnValue = 'Data Pulled Sucessfully';
                                PRINT @ReturnValue;
                            END;
    END TRY
    BEGIN CATCH
    declare @msg nvarchar(max);
      set  @msg= 'Error Line :' + cast(ERROR_LINE() as nvarchar)  +',Error Msg :' + ERROR_MESSAGE() +',Error No :' +cast( ERROR_NUMBER() as nvarchar);
	 print @msg;
        SET @ReturnInt = 0;
       SET @ReturnValue = @msg;
    END CATCH;
    END;
GO
