/***************************************************************************************                    
PROCEDURE         :     [Assy_ResetBarcode]
AUTHOR            :     
DATE WRITTEN      :     Handle Scanning
PURPOSE           :     To Reset Barcode

TEST SCRIPT  

exec [Assy_ResetBarcode] 'OC10','19316005','1931600520Nd00001635J04'


****************************************************************************************/

CREATE PROC [dbo].[Assy_ResetBarcode]     
( 
  @P_Mode nvarchar(10)='',          
  @P_MC_SEQ_NO nvarchar(10)='',
  @P_PART VARCHAR(15)='',
  @P_BARCODE VARCHAR(100)='',
  @P_STS_CD int = 0     ,
  @ReturnValue varchar(2000)='' output ,
  @ReturnInt int = 0 output

)          
AS          
BEGIN          
	
	declare @MainTable  varchar(100) = ''
	declare @MainLogTable  varchar(100) = ''
	declare @listCoulumn varchar(2000) = ''
	declare @listCoulumnMain varchar(2000) = ''
	declare @listCoulumnlog varchar(2000) = ''
	declare @dynamic_query nvarchar(max) = ''

	select top 1  @MainTable=TD_TABLE_NAME from	ASSY_TD_OPERATION_TABLE_MAPPING(nolock) 
	where OperationCode=@P_MC_SEQ_NO
	set @MainLogTable = @MainTable+'_LOG'

	SELECT TABLE_NAME,COLUMN_NAME into #TEMP_MAIN_TBL  FROM INFORMATION_SCHEMA.COLUMNS
	WHERE TABLE_NAME = @MainTable

	SELECT TABLE_NAME,COLUMN_NAME  into #TEMP_MAIN_LOG_TBL FROM INFORMATION_SCHEMA.COLUMNS
	WHERE TABLE_NAME =@MainLogTable
	
	select @listCoulumn =COALESCE(@listCoulumn + ',', '') +  '[' + CONVERT(VARCHAR,main.COLUMN_NAME) + ']' from #TEMP_MAIN_TBL main inner join 
	#TEMP_MAIN_LOG_TBL _log on main.COLUMN_NAME=_log.COLUMN_NAME

	if(substring(@listCoulumn,1,1) = ',')
	begin
	set @listCoulumn = substring(@listCoulumn,2,len(@listCoulumn))
	end
	
	set @listCoulumnMain = 'getdate(),' + @listCoulumn
	set @listCoulumnlog = '[TD_DEL_ACK_TIME],' + @listCoulumn
	

	if(ISNULL(@P_BARCODE,'')='')
	begin
	set @dynamic_query = '
						insert into ' + @MainLogTable + '(
						 ' + @listCoulumnlog +'
						)
						select ' + @listCoulumnMain +' from ' + @MainTable +'(nolock)
						
						delete from ' + @MainTable + '

						'

	--print 	@dynamic_query						
	exec(@dynamic_query)
	end
	else
	begin
			
				
				SET @MainTable= @MainTable + '_SAVE_RESULT'
				
				
				set @dynamic_query = '
							
						insert into ' + @MainLogTable + '(
						 ' + @listCoulumnlog +'
						)
						select ' + @listCoulumnMain +' from ' + @MainTable +'(nolock) where barcode = ISNULL(' +''''+@P_BARCODE+''''+','''')
						
						delete from ' + @MainTable  + ' where barcode = ISNULL(' +''''+@P_BARCODE+'''' +','''')
						
						'

			--print 	@dynamic_query						
			exec(@dynamic_query)

			set @dynamic_query = '
							
						insert into ' + @MainLogTable + '(
						 ' + @listCoulumnlog +'
						)
						select ' + @listCoulumnMain +' from ' + @MainTable +'(nolock) 
						where ScanTimeStamp < (getdate()-2)
						
						delete from ' + @MainTable  + ' where ScanTimeStamp < (getdate()-2)
						
						'
            exec(@dynamic_query)

	end
END 



GO
