/****** Object:  StoredProcedure [dbo].[ASSY_RPT_MATERIALFEEDING]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[ASSY_RPT_MATERIALFEEDING]
@LINECODE nvarchar(5) = NULL,
@PROFITCENTERCODE nvarchar(5) = NULL,
@DATECODE nvarchar(5) = NULL,
@SERIALNO nvarchar(10) = NULL,
@PARTNUMBER nvarchar(30) = NULL,
@FROMDATE datetime = NULL,
@TODATE datetime = NULL,
@ReturnValue nvarchar(max) OUTPUT,
@ReturnInt int OUTPUT
AS
BEGIN
	DECLARE @SQLQUERY nvarchar(max) = '';


	SET @SQLQUERY = 'SELECT FGPartCode as PARTNUMBER,DATECODE,PRODUCTIONORDERNO as ORDERNO ,PacketId as SERIALNO,ChildPartNo,LotNumber,FeedQuantity,UserCode,EntDt FROM Assy_MaterialFeeding(nolock) where 1=1';

	IF (@DATECODE != '')
	BEGIN
		SET @SQLQUERY = CONCAT(@SQLQUERY, ' AND DATECODE=''' + @DATECODE + '''')
	END
	IF (@LINECODE != '')
	BEGIN
		SET @SQLQUERY = CONCAT(@SQLQUERY, ' AND LINECODE=''' + @LINECODE + '''')
	END
	IF (@PROFITCENTERCODE != '')
	BEGIN
		SET @SQLQUERY = CONCAT(@SQLQUERY, ' AND PROFITCENTERCODE=''' + @PROFITCENTERCODE + '''')
	END
	IF (@PARTNUMBER != '')
	BEGIN
		SET @SQLQUERY = CONCAT(@SQLQUERY, ' AND FGPARTCODE=''' + @PARTNUMBER + '''')
	END
	IF (@SERIALNO != '')
	BEGIN
		SET @SQLQUERY = CONCAT(@SQLQUERY, ' AND PACKETID=''' + @SERIALNO + '''')
	END

	IF (@FROMDATE != ''
		AND @TODATE != '')
	BEGIN
		SET @SQLQUERY = CONCAT(@SQLQUERY, ' AND ENTDT BETWEEN convert(datetime,''' + CAST(@FROMDATE AS varchar(50)) + ''' ,103)  and  convert(datetime,''' + CAST(@TODATE AS varchar(50)) + ''',103)');

		PRINT @SQLQUERY;

	END
	EXEC (@SQLQUERY)

END


GO
/****** Object:  StoredProcedure [dbo].[Assy_Set_Line_ManPower]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROC [dbo].[Assy_Set_Line_ManPower]
(
			@Condition Varchar(200) = null,
			@ProfitCenterCode Varchar(10) = null,
			@LineCode Varchar(10) = null,
			@PartNumber Varchar(10) = null,
			@RefNumber Varchar(10) = null,
			@DateCode Varchar(10) = null,
			@StationCode Varchar(10) = null,
			@ClockID Varchar(20) = null,
			@CreatedBy Varchar(10) = null,
			@Enable_ManPower  INT = 0,
			@RETURNVALUE VARCHAR (2000) = null OUT,
			@RETURNINT INT = null OUT
)
AS
BEGIN   
		
		-- Author:		<Aasiya>
		-- Create date: < 31-12-2015>
		-- Description:	<sets line's station wise clock id for the date code>
		-- EXEC [Assy_Set_Line_ManPower] '0021','M07','','01Nc','MCMS','1123','1145'	
			SET NOCOUNT  ON
			IF (@Condition = 'INSERT_MAN_POWER')
			BEGIN
				SELECT Top 1 @PartNumber = ISNULL(RTRIM(Assy_PartNo),'') FROM Assy_RunningPart (NOLOCK) WHERE LineCode = @LineCode Order By CreatedDate Desc
				/*
				Declare @RefNumber nvarchar(20);
				SELECT @RefNumber= CONVERT(varchar(10),sum(pa.rows)+1) 
								FROM sys.tables ta
										INNER  JOIN  sys.partitions pa
											ON (pa.object_id=ta.object_id) 
								WHERE ta.name='Assy_Manpower4S' --+  @DateCode; 
				SET @RefNumber = @RefNumber + @DateCode
				*/
				INSERT INTO [dbo].[Assy_Manpower4S]
						   ([ProfitCenterCode]
						   ,[PartNo]
						   ,[LineCode]
						   ,[StationCode]
						   ,[DateCode]
						   ,[Clock_ID]
						   ,[Created_TimeStamp]
						   ,[Created_By]
						   ,[RefNumber])
					 VALUES
						   (@ProfitCenterCode
						   ,@PartNumber
						   ,@LineCode
						   ,@StationCode
						   ,@DateCode
						   ,@ClockID
						   ,getdate()
						   ,@CreatedBy
						   ,@RefNumber + @DateCode)
			END
			ELSE IF (@Condition = 'MAN_POWER_VALIDATION')
			BEGIN
				SELECT @RETURNVALUE = dbo.ASSY_FN_GET_PARAMETER_VALUE('AssLine','FinalViewing','ManPowerValidation4S',@ProfitCenterCode)
				SET @RETURNINT = 1
			END
			ELSE IF (@Condition = 'MAN_POWER_ENTRY_EXISTS')
			BEGIN
				SELECT Top 1 @PartNumber = ISNULL(RTRIM(Assy_PartNo),''),@DateCode = ISNULL(RTRIM(Datecode),'') FROM Assy_RunningPart (NOLOCK)
					WHERE LineCode = @LineCode Order By CreatedDate Desc

				IF NOT EXISTS (SELECT 1 FROM Assy_Manpower4S (NOLOCK)
					WHERE ProfitCenterCode = @ProfitCenterCode AND PartNo = @PartNumber AND DateCode = @DateCode AND LineCode = @LineCode)
				BEGIN
					SET @RETURNVALUE = 'NOT_EXISTS'
					SET @RETURNINT = 1
				END
				ELSE
				BEGIN
					SET @RETURNVALUE = 'EXISTS'
					SET @RETURNINT = 1
				END
			END
			ELSE IF (@Condition = 'GetManPowerCounter')
			BEGIN
				Declare @MP_Count INT = 0
				SELECT @MP_Count = COUNT(*) FROM Assy_Manpower4S (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode

				IF (@MP_Count <> 0)
				BEGIN
					SELECT Top 1 @MP_Count = REVERSE(RIGHT(REVERSE(RefNumber),LEN(RefNumber) - 4)) FROM Assy_Manpower4S (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode Order by Created_TimeStamp Desc
					SET @RETURNVALUE = Convert(VARCHAR(10),@MP_Count + 1)
					SET @RETURNINT = 1
				END
				ELSE
				BEGIN
					SET @RETURNVALUE = Convert(VARCHAR(10),@MP_Count + 1)
					SET @RETURNINT = 1
				END
			END
			ELSE IF (@Condition = 'IsManPowerRequired')
			BEGIN
				SELECT @RETURNVALUE = ISNULL(IsManPowerRequired,0) FROM LineMst (NOLOCK) WHERE ProfitCenterCode = @ProfitCenterCode AND LineCode = @LineCode

				IF (@RETURNVALUE = 1)
				BEGIN
					SET @RETURNVALUE = 'Y'
					SET @RETURNINT = 1
				END
				ELSE
				BEGIN
					SET @RETURNVALUE = 'N'
					SET @RETURNINT = 1
				END
			END
			ELSE IF (@Condition = 'ENABLE_DISABLE_MAN_POWER')
			BEGIN
				IF(@Enable_ManPower = 1) 
				BEGIN 
					UPDATE LineMst SET IsManPowerRequired = 1 WHERE LineCode = @linecode AND ProfitCenterCode = @ProfitCenterCode
     
					SET @RETURNVALUE = (SELECT Case ISNULL(IsManPowerRequired,0) WHEN 1 THEN 'Y' ELSE 'N' END IsManPowerRequired 
					FROM LineMst (NOLOCK) WHERE LineCode = @linecode AND ProfitCenterCode = @ProfitCenterCode)
					SET @RETURNVALUE = @RETURNVALUE
					SET @RETURNINT = 1
					SELECT @RETURNVALUE
					RETURN
				END

				IF(@Enable_ManPower = 0) 
				BEGIN 
					UPDATE LineMst SET IsManPowerRequired = 0 WHERE LineCode = @linecode AND ProfitCenterCode = @ProfitCenterCode
				
					SET @RETURNVALUE = (SELECT  Case ISNULL(IsManPowerRequired,0) WHEN 1 THEN 'Y' ELSE 'N' END IsManPowerRequired FROM LineMst (NOLOCK) WHERE LineCode = @linecode AND ProfitCenterCode = @ProfitCenterCode)
					SET @RETURNVALUE = @RETURNVALUE
					SET @RETURNINT = 1
					SELECT @RETURNVALUE
					RETURN 
				END
			END
  END





GO
