SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

create procedure [dbo].[DB_SIZE]
as
begin
    set nocount on
     --------------------------TO KNOW OVERALL DATABASE SIZE IN COMPUTER,ORDER BY SIZE DESC-------------------------------------
--select D.Name,
--       M.name as [Database mdf/ldf File name],
--	   M.physical_name as File_path, 
--	   M.state_desc as OnlineStatus,
--	   M.SIZE as SIZE,     
--	   cast((M.SIZE *8) As decimal(18)) as KB, 
--	   cast((M.SIZE *8)/1024 As decimal(18)) as MB, 
--	   cast(((M.SIZE*8.0)/1024)/1024 AS decimal(18,3)) AS GB
--	   from sys.master_files M 
--	   inner join 
--	   sys.Databases D on M.database_id=D.database_id order by GB desc

        ----------------------TO KNOW INDIVIDUAL DATABASE SIZE ---------------------------------------------------

select DB_NAME(database_id) AS DatabaseName,
	                   Name AS [Database mdf/ldf File name],
			  Physical_name as FilePath,
					   SIZE as SIZE,     
	             cast((SIZE *8) As decimal(18)) as KB, 
	             cast((SIZE *8)/1024 As decimal(18)) as MB, 
	            cast(((SIZE*8.0)/1024)/1024 AS decimal(18,3)) AS GB
	   from sys.master_files where DB_NAME(database_id)='BTS_J09_LIVE'
 
end
 
