CREATE   PROC [dbo].[PROC_ASSY_LINEDATA_DELETION]
AS
/*----------------------------------------------------------------------------------------------------------------------------------------------------------
	PROCEDURE				:  [PROC_ASSY_LINEDATA_DELETION]
	AUTHOR					:  Mullai/GOWTHAM
	CREATED DATE			:  25 MAY 2023
	TEST SCRIPT				:  NA

	EXEC PROC_ASSY_LINEDATA_DELETION

	MODIFIED BY	:	< Mullai >
	MODIFIED ON	:	< 26 MAY 2023 >
	DESCRIPTION :	< ARCHIVAL LINKSERVER LOGIC TO PICK RECEIVEDFILENAME BEFORE DELETION>
	MODIFIED BY	:	< GOWTHAM >
	MODIFIED ON	:	< 29 MAY 2023 >
	DESCRIPTION :	< ADDED DELETION LOG AND ARCHIVEDETAIL TABLE DATA AFTER ARCHIVAL ON LOCAL>
	MODIFIED BY	:	< GOWTHAM >
	MODIFIED ON	:	< 31 MAY 2023 >
	DESCRIPTION :	< ADDED DELETION LOGIC FOR PUSH TABLES>
	MODIFIED BY	:	< Mullai >
	MODIFIED ON	:	< 08 JUNE 2023 >
	DESCRIPTION :	< ARCHIVAL LINKSERVER LOGIC TO UPDATE ISSENTTODESTINATION=1 AFTER ARCHIVAL>
	MODIFIED BY	:	< Mullai >
	MODIFIED ON	:	< 21 JULY 2023 >
	DESCRIPTION :	< WHILE LOOP CONDITION ADDED WITH THE SELECTION OF ONE WEEK TO DELETE MULTIPLE ARCHIVEIDS IN SINGLE EXECUTION AFTER ARCHIVAL>
-------------------------------------------------------------------------------------------------------------------------------------------------------------*/

BEGIN
	SET NOCOUNT ON
 BEGIN TRAN
 BEGIN TRY

					DECLARE @TABLEID int ='',
					@Table_Name VARCHAR (500) ='',
					@FROMRID INT ='',@TORID INT ='',
					@sql NVARCHAR(500),
					@ARCHIVEID VARCHAR(MAX)='',
					@ARID VARCHAR(MAX)='',
					@EXECQUERY VARCHAR(MAX)='',
					@LINKSERVERNAME VARCHAR(100) ='',
					@P_PROFITCENTERCODE VARCHAR(10) ='',
					@P_lineCode VARCHAR(10)='',
					@LINEID VARCHAR(20)='',
					@MsgOut VARCHAR(MAX) = NULL,
					@ARCHIVEFILE VARCHAR(MAX)='',
					@COUNT INT=0,
					@COUNT_START INT=0,
					@DB_NAME VARCHAR(20),
					@EVENTID VARCHAR(20),
					@DATA_DELETE_DURATION VARCHAR(10),
					@DELETE_ONLY_DURATION VARCHAR(10),
					@CURR_DATE_TIME	Datetime

				SET @CURR_DATE_TIME=GETDATE()
				SELECT @DATA_DELETE_DURATION=Delete_Gap_InDays FROM LineToHop_Configuration
				SELECT @DELETE_ONLY_DURATION=Delete_Only_Gap_InDays FROM LineToHop_Configuration
				SELECT @P_PROFITCENTERCODE=PROFITCENTERCODE, @P_lineCode=LINECODE FROM ASSY_LINKSERVER_DTL  WITH (NOLOCK) WHERE DataBaseName='[BTS_ARCHIVAL]' 
				SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL  WITH (NOLOCK) WHERE PROFITCENTERCODE = @P_PROFITCENTERCODE AND LINECODE = @P_lineCode and DataBaseName='[BTS_ARCHIVAL]' 
				SELECT @LINEID=LineId FROM ArchiveTablesList WITH (NOLOCK)
				SET @P_lineCode =''
				SELECT @P_lineCode = LineCode FROM LineMst (NOLOCK)  WHERE ProfitCenterCode = @P_PROFITCENTERCODE
				
				SELECT @EVENTID = REPLACE(REPLACE(REPLACE(CONVERT(VARCHAR(20),GETDATE(),120),'-',''),':',''),' ','')
		

				INSERT INTO DELETE_EVENT_LOG ([EVENT_ID],[WH_CODE],[LINECODE],[EVENT_NAME],[EVENT_DESC],[EVENT_START_TIME])
				VALUES(@EVENTID,@P_PROFITCENTERCODE,@P_lineCode,'Data Delete','Deletion of Archived Data',GETDATE())

				DECLARE @ARCHIVEIDTOBEDELETED TABLE  
				(
				ARCHIVEID VARCHAR(100)
				)
					SET @EXECQUERY ='SELECT TOP 150 ReceivedFileName FROM ' + @LINKSERVERNAME + '.DBO.Archive_FileMovementLog WITH (NOLOCK) WHERE Mycode = '''+@P_PROFITCENTERCODE+''' AND  ReceivedFromSourceCode='''+@LINEID+'''
					AND IsSavedToDB=1 AND IsSentToDestinationstatus=1 AND ISNULL(IsDeleted_EOL,'''')='''' AND DATEDIFF(DD, SavedOn, GETDATE()) > '''+@DATA_DELETE_DURATION+''' ORDER BY SavedOn ASC'
			 	--PRINT (@EXECQUERY)
				INSERT INTO @ARCHIVEIDTOBEDELETED 
				EXEC (@EXECQUERY)

			SELECT * INTO #TOBEUPDATED FROM @ARCHIVEIDTOBEDELETED			
			SELECT @COUNT_START=COUNT(*) FROM @ARCHIVEIDTOBEDELETED
		

	WHILE(@COUNT_START > @COUNT)
	BEGIN		

			SELECT TOP 1 @ARCHIVEID=ARCHIVEID FROM @ARCHIVEIDTOBEDELETED 
			DELETE FROM @ARCHIVEIDTOBEDELETED WHERE  ARCHIVEID=@ARCHIVEID
			SET @ARCHIVEID= REPLACE (@ARCHIVEID,'.zip','')
			SELECT @TABLEID =MIN(Id) FROM ArchiveTablesList WITH(NOLOCK)
			SELECT  @Table_Name = TableName FROM ArchiveTablesList WITH(NOLOCK)  WHERE Id = @TABLEID

		IF @Table_Name = 'Assy_LineAssyParamData'
		BEGIN    
    		 IF EXISTS (SELECT TOP 1 1 FROM ArchiveDetail WITH (NOLOCK)  WHERE TableId = @TABLEID AND ArchiveId = @ARCHIVEID AND RowsCount > 0)
    	  		BEGIN

					SELECT @FROMRID = FromRId, @TORID =ToRId FROM ArchiveDetail WITH(NOLOCK)  WHERE TableId = @TABLEID AND ArchiveId = @ARCHIVEID

					INSERT INTO ARCHIVE_DELETION_LOG (UNIQUE_ID,WH_CODE,LINECODE,TABLE_NAME,FROM_RID,TO_RID,ArchiveId,START_TIME) 
					VALUES(@EVENTID,@P_PROFITCENTERCODE,@P_lineCode,@Table_Name,@FROMRID,@TORID,@ARCHIVEID,GETDATE())

    	  			DELETE FROM Assy_LineAssyParamData WHERE RID_NO BETWEEN @FROMRID  AND @TORID					

					UPDATE ARCHIVE_DELETION_LOG SET DELETED_RECORDS=@@ROWCOUNT,END_TIME=GETDATE()
					WHERE UNIQUE_ID=@EVENTID AND TABLE_NAME=@Table_Name
				END

    			SET @TABLEID = @TABLEID + 1
				SET @Table_Name=''
    			SELECT  @Table_Name = TableName FROM ArchiveTablesList WITH (NOLOCK)   WHERE Id = @TABLEID  
		END
		
