/****** Object:  StoredProcedure [dbo].[PROC_CHECK_AVAILABLE_DB_SIZE]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
--exec [PROC_CHECK_AVAILABLE_DB_SIZE]


CREATE PROCEDURE [dbo].[PROC_CHECK_AVAILABLE_DB_SIZE]
AS
BEGIN
    DECLARE @DBName NVARCHAR(128) = DB_NAME(),
            @UsedSpaceMB FLOAT,
            @TotalSpaceMB FLOAT=10240,
            @AvailableSpaceMB FLOAT,
            @ThresholdMB FLOAT = 1024, -- 1 GB threshold in MB
            @EMAIL_ID NVARCHAR(2000) = 'ishant.rawat@motherson.com;siddharth.kashyap@motherson.com;thrainder.kumar@motherson.com;prerna.gupta@motherson.com',
            @MSG NVARCHAR(MAX),
            @SUB NVARCHAR(200) = 'Database Free Space Alert',
            @CC_EMAIL_ID NVARCHAR(2000) = NULL,
            @FILE_NAME NVARCHAR(200) = NULL,
            @P_BODY_TYPE NVARCHAR(30) = 'HTML',
			@LINE NVARCHAR(40)  = NULL,
			@P_SQLEXEC NVARCHAR(MAX) = NULL,
			@UNIT NVARCHAR(10)=null;
			DECLARE @TABLEID int ='',
				@EXECQUERY VARCHAR(MAX)='',
				@LINKSERVERNAME VARCHAR(100) =''
						
				select top 1 @LINE = Linecode, @UNIT = Wh_Code from LineToHop_Configuration(nolock)				
				SELECT @LINKSERVERNAME = LINKSERVERNAME + '.' + DATABASENAME FROM ASSY_LINKSERVER_DTL  WITH (NOLOCK) WHERE PROFITCENTERCODE = @UNIT AND LINECODE = 'ARCH' and DataBaseName='[BTS_ARCHIVAL]' 											
				
				DECLARE @PARAMETER TABLE  
				(
				PARAMETER_VALUE VARCHAR(100)
				)
					SET @EXECQUERY ='SELECT top 1 PARAMETER_VALUE FROM ' + @LINKSERVERNAME + '.DBO.PARAMETER_MST WITH (NOLOCK) WHERE  PARAMETER_C=''FIleSize'' AND PARAMETER_C1=''ThresholdMB''
'
					--PRINT (@EXECQUERY)
			 	INSERT INTO @PARAMETER 
				EXEC (@EXECQUERY)
				select @ThresholdMB=PARAMETER_VALUE from @PARAMETER


	SET @SUB = 'Database Free Space Alert at ' + @UNIT + '-' + @LINE

	SELECT  @UsedSpaceMB=SUM(CAST(FILEPROPERTY(name, 'SpaceUsed') AS FLOAT) * 8.0 / 1024)
	FROM sys.master_files
	WHERE database_id = DB_ID(@DBName)  AND type = 0;

    -- Calculate available space
    SET @AvailableSpaceMB = @TotalSpaceMB - @UsedSpaceMB;

    -- Check if the available space is below the threshold
    IF @AvailableSpaceMB < @ThresholdMB
    BEGIN
        -- Compose the email message
        SET @MSG = N'<html>
        <body>
        <p>Dear Team,</p>
        <p>The available space in the  <b>' + @UNIT + N'</b> database <b>' + @LINE + N'</b> is critically low:</p>
        <table border="1" style="border-collapse: collapse;">
            <tr style="background-color: #06a8bd; color: #ffffff; font-family: Tahoma;">
                <th>Database Name</th>
                <th>Total Space (MB)</th>
                <th>Used Space (MB)</th>
                <th>Available Space (MB)</th>
                <th>Threshold (MB)</th>
            </tr>
            <tr style="background-color: #ebf5f7; color: #000000; font-family: Tahoma;">
                <td>' + @LINE + N'</td>
                <td>' + CAST(@TotalSpaceMB AS NVARCHAR) + N'</td>
                <td>' + CAST(@UsedSpaceMB AS NVARCHAR) + N'</td>
                <td>' + CAST(@AvailableSpaceMB AS NVARCHAR) + N'</td>
                <td>' + CAST(@ThresholdMB AS NVARCHAR) + N'</td>
            </tr>
        </table>
        <p>Please take necessary action to free up or expand the database size.</p>
        <p>Regards,</p>
        <p>Database Monitoring System</p>
        </body>
        </html>';

        -- Send the email
        SET @P_SQLEXEC = 
        'EXEC [BTSDB.BRAKESINDIA.ORG].[BTS].dbo.PROC_SEND_MAIL ' +
        '@EMAIL_ID,'''', @MSG, @SUB, @CC_EMAIL_ID, '''', @P_BODY_TYPE';
 
    -- Execute the remote email procedure
    EXEC SP_EXECUTESQL @P_SQLEXEC,
        N'@EMAIL_ID NVARCHAR(255),@FILE_NAME NVARCHAR(MAX), @MSG NVARCHAR(MAX), @SUB NVARCHAR(255), @CC_EMAIL_ID NVARCHAR(255), @P_BODY_TYPE NVARCHAR(50)',
        @EMAIL_ID,@FILE_NAME, @MSG, @SUB, @CC_EMAIL_ID, @P_BODY_TYPE;
		
    END
END

GO
