create procedure [dbo].[Proc_CheckBarcodeStatus]
(
   @P_Mode varchar(100)='',
   @P_ProfitcenterCode varchar(100)='',
   @P_LineCode varchar(100)='',
   @P_RoutingTable varchar(100)='',
   @P_RoutingCol1 varchar(100)='',
   @P_Config_Key varchar(100)='',
   @P_Config_Value varchar(100)='',
   @P_RouteConfiguration Type_RouteConfiguration readonly,
   @P_RouteConfiguration_MessageData Type_RouteConfiguration_MessageData readonly,
   @P_RouteId int=0,
   @P_TableCount int =0,
   @P_SetRouteId varchar(10)='',
   @P_Barcode varchar(100)='',
   @P_GetRouteObject varchar(100)='PROC_GET_ROUTE_UID_01',
   @P_GetBarcodeDtObject varchar(100)='PROC_GET_BARCODE_DT_UID_01',
   @P_GetBarcodeParamDataObject varchar(100)='PROC_GET_BARCODE_PARAM_DT_UID_01',
   @ReturnValue VARCHAR(MAX) = NULL OUT,
   @ReturnInt INT = NULL OUT
)
as
begin
		declare @MaxRouteId int
		declare @sqlQuery varchar(max)=''		
		declare @strTableName varchar(100) = ''
		declare @TableName as table
		(
				TableName varchar(100),
				SeqNo int
		)
		declare @Tbl_RouteConfiguration Type_RouteConfiguration
		if (@P_Mode='GetRoute')
		begin
			exec PROC_CHK_BARCODE_EXEC_MODE @P_ProfitcenterCode=@P_ProfitcenterCode,@P_LineCode=@P_LineCode,
			@P_ExecMode=@P_GetRouteObject
		end
		else if (@P_Mode='SetRoute')
		begin				
				
				update Tbl_ActiveRouteId set Isactive = 0  where RouteId<>@P_SetRouteId
				update Tbl_ActiveRouteId set Isactive = 1  where RouteId=@P_SetRouteId
				Select RouteId from Tbl_ActiveRouteId(nolock)
			    where isActive =1
		end
		else if (@P_Mode='LoadConfig')
		begin				
				select ConfigKey,ConfigValue from Tbl_Configuration(nolock) where ConfigFor='CheckBarcodeStatus'
		end
		else if (@P_Mode='UpdateConfig')
		begin
			
				if not exists (select top 1 1 from Tbl_Configuration(nolock) where 
				ConfigFor='CheckBarcodeStatus' and ConfigKey=@P_Config_Key
				)
				begin
						insert into Tbl_Configuration(ConfigFor,ConfigKey,ConfigValue)
						select 'CheckBarcodeStatus',@P_Config_Key,@P_Config_Value
				end
				else
				begin
						update Tbl_Configuration set ConfigValue=@P_Config_Value
						where ConfigFor='CheckBarcodeStatus' and ConfigKey=@P_Config_Key
				end
		end		
		else if (@P_Mode='AddRoute')
		begin
			
			select @MaxRouteId=Isnull(Max(RouteId),0)+1 from Tbl_RouteConfiguration(nolock)

			select * into #TEMP_P_RouteConfiguration from @P_RouteConfiguration where IsActive=1

			if exists(select top 1 1 from #TEMP_P_RouteConfiguration)
			begin
				MERGE Tbl_RouteConfiguration t
				USING #TEMP_P_RouteConfiguration s
				ON t.RouteId=@MaxRouteId
				and t.OperationCode=s.OperationCode
				WHEN MATCHED
				THEN UPDATE SET   
				t.IsActive=s.IsActive,t.SeqNo=s.SeqNo,  
				t.TableName=s.TableName,
				t.UpdBy='admin',
				t.Upddt=getdate(),
				t.FailMsg=s.FailMsg,
				t.WIPMsg=s.WIPMsg
				WHEN NOT MATCHED
				THEN
				INSERT (RouteId,IsActive,OperationCode,SeqNo,TableName,EntBy,Entdt,FailMsg,WIPMsg)
				VALUES (@MaxRouteId,s.IsActive, s.OperationCode, s.SeqNo,s.TableName,'admin'
				,getdate(),s.FailMsg,s.WIPMsg);

				if not exists(select top 1 1 from Tbl_ActiveRouteId(nolock) where RouteId=@MaxRouteId)
				begin
						insert into Tbl_ActiveRouteId(RouteId,IsActive,EntBy,EntDt,UpdBy,UpdDt)
						select @MaxRouteId,1,'admin',getdate(),'admin',getdate()
				end

				update Tbl_ActiveRouteId set UpdDt=getdate(),UpdBy='admin',IsActive=0
				where RouteId != @MaxRouteId

				exec Proc_CheckBarcodeStatus @P_Mode='UpdateConfig',
				@P_Config_Key='ActiveRouteId',@P_Config_Value=@MaxRouteId

				Select 'Added Route Id '+ convert(varchar,@MaxRouteId) + ' Sucessfully' as Msg
			end
			else
			begin
			   Select 'Please Mark Any Station As Active' as Msg
			end
		end
		else if (@P_Mode='UpdateRoute')
		begin

			MERGE Tbl_RouteConfiguration t
			USING @P_RouteConfiguration s
			ON t.RouteId=s.RouteId
			and t.OperationCode=s.OperationCode
			WHEN MATCHED
			THEN UPDATE SET   
			t.IsActive=s.IsActive,t.SeqNo=s.SeqNo,  
			t.TableName=s.TableName,
			t.UpdBy='admin',
			t.Upddt=getdate(),
			t.FailMsg=s.FailMsg,
			t.WIPMsg=s.WIPMsg
			WHEN NOT MATCHED
			THEN
			INSERT (RouteId,IsActive,OperationCode,SeqNo,TableName,EntBy,Entdt,FailMsg,WIPMsg)
			VALUES (s.RouteId,s.IsActive, s.OperationCode, s.SeqNo,s.TableName,'admin'
			,getdate(),s.FailMsg,s.WIPMsg);

			Select 'Updated Sucessfully' as Msg

		end
		else if (@P_Mode='GetMessageData')
		begin
				--select * from RouteConfiguration_MessageData
				--select * from Tbl_RouteConfiguration
			
			select * into #RouteConfiguration_MessageData from @P_RouteConfiguration_MessageData
			delete from #RouteConfiguration_MessageData where WIPMsg is null
			--select * into @P_RouteConfiguration_MessageData from #RouteConfiguration_MessageData

			MERGE RouteConfiguration_MessageData t
			USING #RouteConfiguration_MessageData s
			ON t.ProfitCenterCode=s.ProfitCenterCode
			and t.LineCode=s.LineCode
			and t.OperationCode=s.OperationCode
			and t.FailMsg=s.FailMsg 
			and t.WIPMsg=s.WIPMsg
			
			WHEN MATCHED
			THEN UPDATE SET   
			t.OperationCode=s.OperationCode,
			t.FailMsg=s.FailMsg,  
			t.WIPMsg=s.WIPMsg,
			t.UpdBy='admin',
			t.Upddt=getdate()			
			WHEN NOT MATCHED
			THEN
			INSERT (ProfitCenterCode,LineCode,OperationCode,FailMsg,WIPMsg,EntBy,Entdt)
			VALUES (s.ProfitCenterCode,s.LineCode, s.OperationCode, s.FailMsg,s.WIPMsg,'admin'
			,getdate());

			Select 'Message Data Updated Sucessfully' as Msg

		end
		else if (@P_Mode='GetRouteIds')
		begin
			
				if exists(select top 1 1 from Tbl_ActiveRouteId(nolock))
				begin
						select RouteId from Tbl_ActiveRouteId(nolock)
						order by isActive desc
				end
				else
				begin
						select 0 as RouteId 
				end
		end
		else if (@P_Mode='GetLatestRouteId')
		begin
			
				if exists(select top 1 1 from Tbl_ActiveRouteId(nolock))
				begin
						select Top 1 RouteId from Tbl_ActiveRouteId(nolock)
						order by isActive desc
				end
				else
				begin
						select 0 as RouteId 
				end
		end
		else if (@P_Mode='GetRouteUsingRouteId')
		begin			
				select IsActive,RouteId,SeqNo,OperationCode,TableName ,
				Isnull(FailMsg ,'') as FailMsg,Isnull(WIPMsg ,'') as WIPMsg
				from Tbl_RouteConfiguration(nolock) where
				RouteId in (@P_RouteId)
				order by SeqNo asc
		end
		else if (@P_Mode='GetActiveRoute')
		begin			
				select IsActive,RouteId,SeqNo,OperationCode,Isnull(TableName ,'') as TableName,
				Isnull(FailMsg ,'') as FailMsg,Isnull(WIPMsg ,'') as WIPMsg
				from Tbl_RouteConfiguration(nolock) where
				RouteId in (select RouteId from Tbl_ActiveRouteId(nolock)
						    where isActive =1) 
				order by SeqNo asc
		end
		else if (@P_Mode='ShowBarcodeData')
		begin			
							
				truncate table Tbl_Get_Barcode_Status
				insert into @Tbl_RouteConfiguration(RouteId,IsActive,OperationCode,SeqNo,TableName,FailMsg,WIPMsg )
				select RouteId,IsActive,OperationCode,SeqNo,TableName,FailMsg,WIPMsg  
				from Tbl_RouteConfiguration(nolock)
				where RouteId in (select RouteId from Tbl_ActiveRouteId(nolock)
				where isActive =1)	AND IsActive=1
				
				exec PROC_CHK_BARCODE_EXEC_MODE @P_ExecMode = @P_GetBarcodeDtObject, @P_Barcode=@P_Barcode,
				@P_RouteConfiguration=@Tbl_RouteConfiguration

				select SeqNo,OperationCode,Barcode,[Status],Remarks,convert(varchar,ScanTimeStamp,121) as ScanTimeStamp ,
				convert(varchar,ResultTimeStamp,121) as ResultTimeStamp  
				from Tbl_Get_Barcode_Status order by SeqNo

		end
		else if (@P_Mode='ShowBarcodeLogData')
		begin
					insert into @TableName (TableName,SeqNo)
					select  distinct TableName + '_Log',SeqNo  from Tbl_RouteConfiguration 
					where IsActive=1 and isnull(TableName,'') != ''

					while exists(select top 1 1 from @TableName )
					begin
							select top 1 @strTableName=TableName  from @TableName order by SeqNo
							set @sqlQuery = '			
								IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID('+'''' +@strTableName+''''+') AND type in (N''U''))
								BEGIN
										select ' + '''' +@strTableName + '''' + ' as TableName '+'
										select ''Table Not Found : ' + @strTableName +''' as Msg
								END
								ELSE
								BEGIN
										select ' + '''' +@strTableName + '''' + ' as TableName '+'
										select top 1 * from ' + @strTableName +' where RFID='+ ''''+ @P_Barcode + '''' +' and Audit_Inserted is not null
								END
							'
							exec(@sqlQuery)
							--print @sqlQuery
							delete @TableName where TableName=@strTableName
					end

		end
		else if (@P_Mode='ShowBarcodeParameter')
		begin
					
				truncate table Tbl_Get_Barcode_Param_dt

				insert into @Tbl_RouteConfiguration(RouteId,IsActive,OperationCode,SeqNo,TableName,FailMsg,WIPMsg )
				select RouteId,IsActive,OperationCode,SeqNo,TableName,FailMsg,WIPMsg  
				from Tbl_RouteConfiguration(nolock)
				where RouteId in (select RouteId from Tbl_ActiveRouteId(nolock)
				where isActive =1)	AND IsActive=1
				
				exec PROC_CHK_BARCODE_EXEC_MODE @P_ExecMode = @P_GetBarcodeParamDataObject, @P_Barcode=@P_Barcode,
				@P_RouteConfiguration=@Tbl_RouteConfiguration,@P_LineCode=@P_LineCode,@P_ProfitcenterCode=@P_ProfitcenterCode

				select Barcode,OperationCode,Result,TagName,[Value],convert(varchar,[TimeStamp],121) [TimeStamp] from Tbl_Get_Barcode_Param_dt(nolock)
				order by MachineSeqNo,OperationSeqno


	end
	else if (@P_Mode='MessageData')
	begin				
				select ProfitCenterCode,LineCode,OperationCode,FailMsg,WIPMsg from RouteConfiguration_MessageData(nolock)
	end


end

GO
/****** Object:  StoredProcedure [dbo].[PROC_CHK_BARCODE_EXEC_MODE]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
