create procedure [dbo].[PROC_CHK_BARCODE_EXEC_MODE]
(   
	@P_ExecMode  varchar(100)='',
	@P_ProfitcenterCode varchar(100)='',
	@P_LineCode varchar(100)='',
	@P_RouteConfiguration Type_RouteConfiguration readonly,
	@P_Barcode varchar(100)=''
)
as
begin	
	    If(@P_ExecMode = 'PROC_GET_ROUTE_UID_BIL_01')
		begin
				exec PROC_GET_ROUTE_UID_BIL_01 @P_ProfitcenterCode=@P_ProfitcenterCode , @P_LineCode=@P_LineCode
		end
		else  If(@P_ExecMode = 'PROC_GET_BARCODE_DT_BIL_UID_01')
		begin
				exec PROC_GET_BARCODE_DT_BIL_UID_01 @P_Barcode=@P_Barcode,@P_RouteConfiguration=@P_RouteConfiguration
		end
		else  If(@P_ExecMode = 'PROC_GET_BARCODE_PARAM_DT_BIL_UID_01')
		begin
				exec PROC_GET_BARCODE_PARAM_DT_BIL_UID_01 @P_Barcode=@P_Barcode,@P_RouteConfiguration=@P_RouteConfiguration,
				@P_ProfitcenterCode=@P_ProfitcenterCode,@P_LineCode=@P_LineCode
		end
		else If(@P_ExecMode = 'PROC_GET_ROUTE_UID_TEL_01')
		begin
				exec PROC_GET_ROUTE_UID_TEL_01 @P_ProfitcenterCode=@P_ProfitcenterCode , @P_LineCode=@P_LineCode
		end
		else  If(@P_ExecMode = 'PROC_GET_BARCODE_DT_UID_TEL_01')
		begin
				exec PROC_GET_BARCODE_DT_UID_TEL_01 @P_Barcode=@P_Barcode,@P_RouteConfiguration=@P_RouteConfiguration
		end
		else  If(@P_ExecMode = 'PROC_GET_BARCODE_PARAM_DT_UID_TEL_01')
		begin
				exec PROC_GET_BARCODE_PARAM_DT_UID_TEL_01 @P_Barcode=@P_Barcode,@P_RouteConfiguration=@P_RouteConfiguration,
				@P_ProfitcenterCode=@P_ProfitcenterCode,@P_LineCode=@P_LineCode
		end
		
end
