GO

/***************************************************************************************                    
PROCEDURE         :     PROC_Compare_Col_Btw_Local_And_Live
AUTHOR            :     SACHIN KUMAR
DATE WRITTEN      :     18/11/2019
PURPOSE           :     Compare Live and Local Table Column/s
TEST SCRIPT  

declare @ReturnValue VARCHAR (2000)=NULL
declare @ReturnInt INT=NULL   
exec PROC_Compare_Col_Btw_Local_And_Live @table_name='LineMst' ,@LinkServerName='[10.241.64.121].[SSIS_MINI_SERVER_U21]'
select @ReturnInt,@ReturnValue 

****************************************************************************************/
create procedure [dbo].[PROC_Compare_Col_Btw_Local_And_Live]
(
  @table_name						SYSNAME,
  @LinkServerName					varchar(100),
  @ReturnValue						VARCHAR (2000)='' OUT,
  @ReturnInt						INT=0 OUT 
  
)
as
begin

DECLARE @SQL VARCHAR(MAX) = ''
set @ReturnValue = ''
set @ReturnInt = 0

DECLARE @LIVE_SRV_COLUMN_NAME as table
(
   columnName varchar(1000)
)

DECLARE @LOCAL_SRV_COLUMN_NAME as table
(
   columnName varchar(1000)
)

set @SQL = '
SELECT c.Name as [ColumnName]  ' +   
'FROM ' + @LinkServerName + '.sys.objects o WITH (NOWAIT) ' + char(13)
+ 'JOIN '+@LinkServerName+'.sys.schemas s WITH (NOWAIT) ON o.[schema_id] = s.[schema_id] ' + char(13)
+ 'JOIN '+@LinkServerName+'.sys.columns c WITH (NOWAIT) ON c.[object_id] = o.[object_id]' + char(13) +
'WHERE o.name = ' + ''''+ @table_name + ''''+ ' AND o.[type] = ''U'' AND o.is_ms_shipped = 0'

--print @SQL

insert into @LIVE_SRV_COLUMN_NAME
exec(@SQL)

insert into @LOCAL_SRV_COLUMN_NAME
SELECT c.Name as [ColumnName]  FROM sys.objects o WITH (NOWAIT) 
JOIN sys.schemas s WITH (NOWAIT) ON o.[schema_id] = s.[schema_id] 
JOIN sys.columns c WITH (NOWAIT) ON c.[object_id] = o.[object_id]
WHERE o.name = @table_name AND o.[type] = 'U' AND o.is_ms_shipped = 0

select li.[ColumnName] as 'LiveCol' , Lo.[ColumnName] as 'LocalCol' 
into #TEMP_LILO_SRV_COLUMN_NAME
from @LIVE_SRV_COLUMN_NAME li
full join @LOCAL_SRV_COLUMN_NAME lo
on li.[ColumnName] = lo.[ColumnName]
where li.[ColumnName] is null or Lo.[ColumnName] is null

--select * from #TEMP_LILO_SRV_COLUMN_NAME

if exists(select top 1 1 from #TEMP_LILO_SRV_COLUMN_NAME)
begin
		set @ReturnValue += ISNULL((select 'Column Not Available In Local Table ' + @table_name + ':' + STUFF(( select CHAR(9) + ', [' + LiveCol + ']' 								
		from #TEMP_LILO_SRV_COLUMN_NAME  where LocalCol is null
		FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, CHAR(9) + ' ')
		 + CHAR(13)),'')   
		--print @ReturnValue
		set @ReturnValue +=ISNULL((select 'Column Not Available In Live Table ' + @table_name + ':' + STUFF(( select CHAR(9) + ', [' + LocalCol + ']' 								
		from #TEMP_LILO_SRV_COLUMN_NAME  where LiveCol is null
		FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, CHAR(9) + ' ')
		+ CHAR(13)),'')   

		set @ReturnInt=2
end


end
GO
/****** Object:  StoredProcedure [dbo].[PROC_Enable_xp_cmdshell]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
