/*----------------------------------------------------------------------
CREATED BY		: SACHIN KUMAR
DATE			: 19 June 2020
REMARKS			:   
REVISION HISTORY: 

TEST SCRIPT		: 

exec PROC_Enable_xp_cmdshell
-----------------------------------------------------------------*/
create procedure [dbo].[PROC_Enable_xp_cmdshell]
as
begin
	if((SELECT CONVERT(INT, ISNULL(value, value_in_use)) AS config_value
		FROM  sys.configurations WHERE  name = 'xp_cmdshell')=1)
		begin
				print 'Already Enabled'	
		end
		else
		begin
			exec sp_configure 'show advanced options', '1'
			RECONFIGURE
			-- this disables xp_cmdshell
			exec sp_configure 'xp_cmdshell', '1' 
			RECONFIGURE
		end 

end
GO
/****** Object:  StoredProcedure [dbo].[Proc_FilterHtmlLogFile]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 CREATE proc [dbo].[Proc_FilterHtmlLogFile]  
(  
@Mode varchar(100) = '',  
@FromDate datetime = null,  
@ToDate   datetime = null,  
@ReturnValue VARCHAR(MAX) = '' OUT ,  
@ReturnInt INT =0 OUT ,  
@TableName varchar(100) = null,  
@ColumnName varchar(100) = null,  
@Rfid varchar(100) = null,  
@filename varchar(100) ='',  
@wh_code varchar(10) ='',   
@mccode varchar(10) ='',   
@opcode varchar(10) ='',  
@lineCode varchar(10) =''  
)  
AS   
BEGIN  
     Declare @SQlQuery varchar(max)=''  
   if(@Mode='GET_DATA_BY_DATE_FILTER')  
   begin  
   select * from ReadHtmlLogFile where CONVERT(VARCHAR, Date_Time , 120)  between CONVERT(DATETIME, CONVERT(VARCHAR(20), @FromDate, 120)) and  CONVERT(DATETIME, CONVERT(VARCHAR(20), @ToDate, 120))  
   end  
     
   else  
   if (@Mode='GET_DATA')  
   begin  
   select Date_Time,line_code,machine_code,Operation_code,msg from ReadHtmlLogFile   
   end  
  -- else  
  --  if(@Mode='GET_Time_Gap')  
  -- begin  
  -- SELECT  a1.Date_Time,DATEDIFF(MILLISECOND,a1.Date_Time, a2.Date_Time) as Difference,a1.line_code,a1.machine_code,a1.Operation_code,a1.msg  from ReadHtmlLogFile a1 inner join ReadHtmlLogFile a2 on a2.id=a1.id+1    
  -- end  
  else  
       if(@Mode='CheckExistingFile')  
   begin  
  
    
  set @SQlQuery = '  
  if exists( select top 1 1 from ' + @TableName +' where FileName = '+''''+@filename+''''+')  
  begin   
    insert into ' + @TableName + '_History  
    select * from '+@TableName+' where FileName= ' + ''''+@filename+''''+'  
    delete from '+@TableName+' where FileName = ' + ''''+@filename+'''' +'    
   end'  
   set @ReturnInt = 1  
   print @SQlQuery  
   exec(@SQlQuery)  
   end  
   else  
   if (@Mode ='PopulateColumnName')  
   Begin  
     select COLUMN_NAME AS COLUMN_NAME  
     from INFORMATION_SCHEMA.COLUMNS  
     where TABLE_NAME=@TableName  
 End  
 else  
 if (@Mode ='PopulateSecondColumnName')  
 begin  
  select COLUMN_NAME AS COLUMN_NAME  
     from INFORMATION_SCHEMA.COLUMNS  
     where TABLE_NAME= @TableName and COLUMN_NAME <> @ColumnName  
  end  
 else  
 if(@Mode ='GetLogData')  
 Begin   
    
  set @SQlQuery = '  
   select distinct * from  ' + @TableName +' order by date_time  
  '  
   print @SQlQuery  
   exec(@SQlQuery)  
 End  
 if(@Mode ='GetSequenceData')  
 Begin  
   
 --Declare @Barcode varchar(100)  
  
 --SELECT @Barcode =   RIGHT(msg, 23)  from  ReadHtmlLogFile_Sequence   
 --where msg like '%RFID MOVE FOR VALIDATION%';  
  
 UPDATE ReadHtmlLogFile_Sequence set msg= REPLACE(msg,@Rfid,'{Barcode}')  
  
 Delete from ReadHtmlLogFile_Sequence where isnull(msg,'')=''  
  
 --Select ROW_NUMBER() OVER(ORDER BY Date_Time ASC) AS Sequence_No,machine_code AS Sequence_Name,  
 --   machine_code AS Machine_Code, msg AS Expected_Sequence  
 --   from ReadHtmlLogFile_Sequence   
 --   order by Date_Time  
  End  
    
 else  
 if (@Mode ='GetExceptionLogDataTable')  
 begin    
  
  IF OBJECT_ID(N'tempdb..#ReadHtmlLogFile_Sequence') IS NOT NULL  
  BEGIN  
  DROP TABLE #ReadHtmlLogFile_Sequence  
  END  
  
  IF OBJECT_ID(N'tempdb..#TEMP_ReadHtmlLogFile_Log') IS NOT NULL  
  BEGIN  
  DROP TABLE #TEMP_ReadHtmlLogFile_Log  
  END  
  
  Select Sequence_No,SubStartIndex,SubEndIndex,msg,Tag_Write_By,Tag_Read_By,Remarks into #ReadHtmlLogFile_Sequence   
  from ReadHtmlLogFile_Sequence(nolock) where IsActive=1 and line_code=@lineCode and machine_code=@mccode  
  and Operation_code=@opcode  
  
  select ROW_NUMBER() OVER(ORDER BY Date_Time ASC) AS Sequence_No,Msg,date_time into #TEMP_ReadHtmlLogFile_Log   
  from ReadHtmlLogFile_Log(nolock) where date_time is not null  
  
  UPDATE #ReadHtmlLogFile_Sequence set msg= REPLACE(msg,'(Barcode)',@Rfid)  
  
  Select convert(varchar,rl.date_time,121) as 'DateTime',rs.msg as 'Expected Tag Flow',isnull(rl.msg,'') as 'Actual Tag Flow' ,Tag_Write_By,Tag_Read_By,Remarks  
  from #ReadHtmlLogFile_Sequence rs  full outer join   
  #TEMP_ReadHtmlLogFile_Log rl on  rl.msg like '%' + substring(rs.msg,rs.SubStartIndex,rs.SubEndIndex) + '%'  
  order by rs.Sequence_No  
  
  delete from ReadHtmlLogFile_Log  
  
 end  
  
End   
  
  
  
GO
