/***************************************************************************************                    
PROCEDURE         :     PROC_Generate_Variable_Table_Script
AUTHOR            :     SACHIN KUMAR
DATE WRITTEN      :     18/11/2019
PURPOSE           :     Proc to generate merge script
TEST SCRIPT  

declare @TableScript varchar(max)='',@InsertTableScript varchar(max)='',
@ColumnName varchar(max)='',@TargetTableColumnName varchar(max)='',@SourceTableColumnName varchar(max)='',
@MergeUpdateTableColumnName varchar(max)='',@IdentityInsertOn varchar(1000)='',
@IdentityInsertOff varchar(1000)='',@PrimaryKeyColumnName varchar(max)=''

exec PROC_Generate_Variable_Table_Script @table_name='PRODUCT_MASTER',
@TableScript=@TableScript out , @InsertTableScript=@InsertTableScript out,
@ColumnName=@ColumnName out,@TargetTableColumnName=@TargetTableColumnName out,
@SourceTableColumnName=@SourceTableColumnName out,@MergeUpdateTableColumnName=@MergeUpdateTableColumnName out,
@IdentityInsertOn = @IdentityInsertOn out ,@IdentityInsertOff=@IdentityInsertOff out,@PrimaryKeyColumnName=@PrimaryKeyColumnName out

print @TableScript 
print @InsertTableScript
print @ColumnName
print @TargetTableColumnName
print @SourceTableColumnName
print @MergeUpdateTableColumnName
print @IdentityInsertOn
print @IdentityInsertOff
print @PrimaryKeyColumnName

declare @MergeQuery varchar(max)=''

exec PROC_Generate_Variable_Table_Script @table_name='bom_master',@table_merge_column='WH_CODE,FG_PART_NO,RM_PART_NO,VER,STS_CD,EFFECTIVE_IN,EFFECTIVE_OUT',
@MergeQuery=@MergeQuery out 

select @MergeQuery


****************************************************************************************/
CREATE procedure [dbo].[PROC_Generate_Variable_Table_Script]
(
  @table_name						SYSNAME,
  @table_merge_column				varchar(2000)='',
  @TableScript						varchar(max) = NULL OUT,
  @InsertTableScript				varchar(max) = NULL OUT,
  @ColumnName						varchar(max) = NULL OUT,
  @TargetTableColumnName			varchar(max) = NULL OUT,
  @SourceTableColumnName			varchar(max) = NULL OUT,
  @MergeUpdateTableColumnName		varchar(max) = NULL OUT,
  @IdentityInsertOn					varchar(1000) = NULL OUT,
  @IdentityInsertOff				varchar(1000) = NULL OUT,
  @PrimaryKeyColumnName				varchar(max) = NULL OUT,
  @MergeQuery						varchar(max) = NULL OUT,
  @Remove_Duplicate					varchar(max) = NULL OUT,
  @IsInsertScript					BIT = 0
)
as
begin



DECLARE 
      @object_name SYSNAME
    , @object_id INT

SELECT 
      @object_name = '@DEC_'+ o.name + ''
    , @object_id = o.[object_id]
FROM sys.objects o WITH (NOWAIT)
JOIN sys.schemas s WITH (NOWAIT) ON o.[schema_id] = s.[schema_id]
WHERE o.name = @table_name
    AND o.[type] = 'U'
    AND o.is_ms_shipped = 0

DECLARE @SQL					 VARCHAR(MAX) = ''
DECLARE @InsertTableScriptSQL	 VARCHAR(MAX) = ''
DECLARE @TargetSQL				 VARCHAR(MAX) = ''
DECLARE @SourceSQL				 VARCHAR(MAX) = ''
DECLARE @TSUpdateSQL			 VARCHAR(MAX) = ''
DECLARE @IdentityInsertOnSQL	 VARCHAR(1000) = ''
DECLARE @IdentityInsertOffSQL	 VARCHAR(1000) = ''
DECLARE @PrimaryKeyColumnNameSQL VARCHAR(max) = ''
DECLARE @Comma varchar(1)=''


select c.name as 'ColumnName',tp.name,c.is_computed,c.max_length,c.scale,c.[precision],cc.[definition]
,ROW_NUMBER() OVER(ORDER BY c.column_id) as column_id,c.is_identity,0 as PrimaryKeyCol
 into #TBL_SCHEMA from sys.columns c WITH (NOWAIT)
JOIN sys.types tp WITH (NOWAIT) ON c.user_type_id = tp.user_type_id
LEFT JOIN sys.computed_columns cc WITH (NOWAIT) ON c.[object_id] = cc.[object_id] AND c.column_id = cc.column_id
LEFT JOIN sys.default_constraints dc WITH (NOWAIT) ON c.default_object_id != 0 AND c.[object_id] = dc.parent_object_id AND c.column_id = dc.parent_column_id
LEFT JOIN sys.identity_columns ic WITH (NOWAIT) ON c.is_identity = 1 AND c.[object_id] = ic.[object_id] AND c.column_id = ic.column_id
WHERE c.[object_id] = @object_id
ORDER BY c.column_id



update #TBL_SCHEMA set PrimaryKeyCol = 1 where ColumnName in (
select distinct col1 from dbo.FN_GRID_SPLIT_STRING(@table_merge_column,'',',')
)

--select * from #TBL_SCHEMA

SELECT @SQL = 'declare ' + @object_name + ' as Table ' + CHAR(13) + '(' + CHAR(13) + STUFF((
    SELECT CHAR(9) + ', [' + ColumnName + '] ' + 
        CASE WHEN is_computed = 1
            THEN 'AS ' + [definition] 
            ELSE UPPER(name) + 
                CASE WHEN name IN ('varchar', 'char', 'varbinary', 'binary', 'text')
                       THEN '(' + CASE WHEN max_length = -1 THEN 'MAX' ELSE CAST(max_length AS VARCHAR(5)) END + ')'
                     WHEN name IN ('nvarchar', 'nchar', 'ntext')
                       THEN '(' + CASE WHEN max_length = -1 THEN 'MAX' ELSE CAST(max_length / 2 AS VARCHAR(5)) END + ')'
                     WHEN name IN ('datetime2', 'time2', 'datetimeoffset') 
                       THEN '(' + CAST(scale AS VARCHAR(5)) + ')'
                     WHEN name = 'decimal' 
                       THEN '(' + CAST([precision] AS VARCHAR(5)) + ',' + CAST(scale AS VARCHAR(5)) + ')'
                    ELSE ''
                END +
                ' NULL'+
                CASE WHEN [definition] IS NOT NULL THEN ' DEFAULT' + [definition] ELSE '' END 
        END + CHAR(13)
    FROM #TBL_SCHEMA tc
    FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, CHAR(9) + ' ')
    +  ')'  + CHAR(13)    
   

set @TableScript = @SQL

declare @strRange smallint = 1 , @endRange smallint =5 , @maxRange smallint = 0 , @incrementCount smallint = 6;
set @endRange = @incrementCount
set @SQL = ''
select top 1 @maxRange = column_id from #TBL_SCHEMA order by column_id desc

--print '------1------'
if(@maxRange> 0)
begin
	--print '------2------'
	if(@maxRange <= @endRange)
	begin
		--print '------3------'
		SELECT @SQL += STUFF(( select CHAR(9) + ', [' + ColumnName + ']' 								
				  from #TBL_SCHEMA where column_id between @strRange and @maxRange
				  FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, CHAR(9) + ' ')
				  + CHAR(13)   

		SELECT @TargetSQL += STUFF(( select CHAR(9) + ', t.[' + ColumnName + ']' 								
				  from #TBL_SCHEMA where column_id between @strRange and @maxRange
				  FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, CHAR(9) + ' ')
				  + CHAR(13)   

		SELECT @SourceSQL += STUFF(( select CHAR(9) + ', s.[' + ColumnName + ']' 								
				  from #TBL_SCHEMA where column_id between @strRange and @maxRange
				  FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, CHAR(9) + ' ')
				  + CHAR(13) 
		
		SELECT @TSUpdateSQL += STUFF(( select CHAR(9) + ', t.[' + ColumnName + ']' + '=' + 's.[' + ColumnName + ']' 								
				  from #TBL_SCHEMA where is_identity =0 and column_id between @strRange and @maxRange
				  FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, CHAR(9) + ' ')
				  + CHAR(13) 				    

	end
	else
	begin
		--print '------4------'
			while(@maxRange > @endRange)
			begin
				--print 'Start:' + convert(varchar,@strRange)
				--print 'End:' + convert(varchar,@endRange)
				
				SELECT @SQL += @Comma + STUFF(( select CHAR(9) + ', [' + ColumnName + ']' 								
					  from #TBL_SCHEMA where column_id between @strRange and @endRange
					  FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, CHAR(9) + ' ')
					  + CHAR(13)   

				SELECT @TargetSQL += @Comma + STUFF(( select CHAR(9) + ', t.[' + ColumnName + ']' 								
						from #TBL_SCHEMA where column_id between @strRange and @endRange
						FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, CHAR(9) + ' ')
						+ CHAR(13)   

				SELECT @SourceSQL += @Comma + STUFF(( select CHAR(9) + ', s.[' + ColumnName + ']' 								
						  from #TBL_SCHEMA where  column_id between @strRange and @endRange
						  FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, CHAR(9) + ' ')
						  + CHAR(13)  
				
				SELECT @TSUpdateSQL += @Comma + STUFF(( select CHAR(9) + ', t.[' + ColumnName + ']' + '=' + 's.[' + ColumnName + ']' 								
				  from #TBL_SCHEMA where is_identity =0 and column_id between @strRange and @endRange
				  FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, CHAR(9) + ' ')
				  + CHAR(13) 	
				
				set @strRange = @strRange + @incrementCount
				set @endRange = @endRange + @incrementCount
				set @Comma = ','
			end
			if((@maxRange >= @strRange) and (@maxRange <= @endRange))
			begin
			--print 'While End'
			--print convert(varchar,@strRange)
			--print convert(varchar,@endRange)

			SELECT @SQL += @Comma + STUFF(( select CHAR(9) + ', [' + ColumnName + ']' 								
					  from #TBL_SCHEMA where column_id between @strRange and @maxRange
					  FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, CHAR(9) + ' ')
					  + CHAR(13) 

			SELECT @TargetSQL += @Comma + STUFF(( select CHAR(9) + ', t.[' + ColumnName + ']' 								
					from #TBL_SCHEMA where column_id between @strRange and @maxRange
					FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, CHAR(9) + ' ')
					+ CHAR(13)   

			SELECT @SourceSQL += @Comma + STUFF(( select CHAR(9) + ', s.[' + ColumnName + ']' 								
						from #TBL_SCHEMA where column_id between @strRange and @maxRange
						FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, CHAR(9) + ' ')
						+ CHAR(13) 
			
			SELECT @TSUpdateSQL += @Comma + STUFF(( select CHAR(9) + ', t.[' + ColumnName + ']' + '=' + 's.[' + ColumnName + ']' 								
				  from #TBL_SCHEMA where is_identity =0 and column_id between @strRange and @maxRange
				  FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, CHAR(9) + ' ')
				  + CHAR(13) 

			end
	end


end

if exists(select top 1 1 from #TBL_SCHEMA where is_identity = 1)
begin

set @IdentityInsertOnSQL = 'SET IDENTITY_INSERT '+@table_name+ ' ON;' + CHAR(13)	
set @IdentityInsertOffSQL = 'SET IDENTITY_INSERT '+@table_name+ ' OFF;' + CHAR(13)	

end

if exists(select top 1 1 from #TBL_SCHEMA where PrimaryKeyCol = 1)
begin

		SELECT @PrimaryKeyColumnNameSQL += ISNULL(STUFF(( 
		
		select CHAR(9)  + '& ISNULL(convert(varchar('+convert(varchar,max_length)+'),t.[' + ColumnName + ']' + '),'''')' +'=' 
		+ ' ISNULL(convert(varchar('+convert(varchar,max_length)+'),s.[' + ColumnName + ']' + '),'''')' + CHAR(13) 								
		from #TBL_SCHEMA where PrimaryKeyCol =1 and name not in ('datetime')
		FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, CHAR(9) + ' '),'')
		

		IF(ISNULL(@PrimaryKeyColumnNameSQL,'')='')
		BEGIN
				SELECT @PrimaryKeyColumnNameSQL += ISNULL(STUFF(( 
		
				select CHAR(9)  + '& t.[' + ColumnName + ']' +'=' 
				+ 's.[' + ColumnName + ']'  + CHAR(13) 								
				from #TBL_SCHEMA where PrimaryKeyCol =1 and name in ('datetime')
				FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, CHAR(9) + ' '),'')
			
			
		END
		ELSE
		BEGIN
				SELECT @PrimaryKeyColumnNameSQL += ISNULL('& ' + STUFF(( 
		
				select CHAR(9)  + '& t.[' + ColumnName + ']' +'=' 
				+ 's.[' + ColumnName + ']'  + CHAR(13) 								
				from #TBL_SCHEMA where PrimaryKeyCol =1 and name in ('datetime')
				FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, CHAR(9) + ' '),'')
		

		END

		set @PrimaryKeyColumnNameSQL = REPLACE(@PrimaryKeyColumnNameSQL,'&',' AND ') +  CHAR(13) 
		--print @PrimaryKeyColumnNameSQL
end

set @InsertTableScriptSQL =  
						' 
						declare @MergeCount as table
						( MAction Varchar(20) ) ' + char(13) +
						'Insert Into ' + @object_name + '(' +  @SQL + ')'

 

SET @Remove_Duplicate = '	;WITH CTE_Remove_Duplicate 
										AS
										( 
											SELECT ROW_NUMBER() OVER 
												( 
													PARTITION BY ' + @table_merge_column + ' Order By ' 
													+ Case CHARINDEX(',',@table_merge_column) 
													  WHEN 0 
														THEN @table_merge_column 
													  ELSE 
													  CAST(LEFT(@table_merge_column,CHARINDEX(',',@table_merge_column) - 1) AS VARCHAR) END + '
												) CTE_Id, *
												FROM ' + @object_name + ' 
										) 
										DELETE  FROM CTE_Remove_Duplicate WHERE CTE_Id > 1
										'


--print @SQL
--print @TargetSQL
--print @SourceSQL
--print @TSUpdateSQL
--print @IdentityInsertOnSQL
--print @IdentityInsertOffSQL
--print @Remove_Duplicate

--print @InsertTableScriptSQL 

set @ColumnName=@SQL				
set @TargetTableColumnName=@TargetSQL			
set @SourceTableColumnName=@SourceSQL			
set @MergeUpdateTableColumnName=@TSUpdateSQL		
set @IdentityInsertOn=@IdentityInsertOnSQL
set @IdentityInsertOff=@IdentityInsertOffSQL
set @PrimaryKeyColumnName=@PrimaryKeyColumnNameSQL
set @InsertTableScript=@InsertTableScriptSQL

--print @PrimaryKeyColumnName
IF @IsInsertScript = 0
BEGIN
	set @SQL = @IdentityInsertOn +   
			  'MERGE INTO ' + @table_name + ' AS t ' + CHAR(13) +
			  'USING ' + @object_name + ' AS s ' + CHAR(13) +
			  ' ON ' + @PrimaryKeyColumnName + CHAR(13) +
			  'WHEN NOT MATCHED THEN ' + CHAR(13) +
			  'INSERT ' + CHAR(13) +
			  '(' + CHAR(13) +
				 @ColumnName +
			  ')' + CHAR(13) +
			  ' VALUES '+ CHAR(13) +
			  '(' + CHAR(13) +
				 @SourceTableColumnName +
			  ')' + CHAR(13) +
			  'WHEN MATCHED THEN ' + CHAR(13) +
			  'UPDATE SET ' + CHAR(13) +
			  @MergeUpdateTableColumnName  + CHAR(13) +

			  '
				OUTPUT $action		
				[action]	
				into @MergeCount

			  ' 
			  + ';'
			  + CHAR(13) +
			  'select * from @MergeCount'
			  + CHAR(13) +
			  + @IdentityInsertOff
END
ELSE
BEGIN
	set @SQL = ''
END
--print @SQL

set @MergeQuery = @SQL


end
--EXEC sys.sp_executesql @SQL

GO
/****** Object:  StoredProcedure [dbo].[PROC_GET_RECORDS_ARCHIVE]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROC [dbo].[PROC_GET_RECORDS_ARCHIVE]
(
  @ProfitCentercode VARCHAR(20) = NULL,
  @LineCode			VARCHAR(100) = NULL,
  @Mode				VARCHAR(500) = NULL,
  @Table_Name		VARCHAR(100) = NULL,
  @MsgOut			VARCHAR(MAX)=NULL, 
  @ArchiveId		BIGINT = 0,
  @FromRId			INT = 0,
  @ToRId			INT = 0,
  @TableId			INT = 0,
  @Remarks			NVARCHAR(MAX)=NULL,
  @HopIP			VARCHAR(100) = NULL,
  @SentToHopOn		Datetime = NULL,
  @SentToHopSize	VARCHAR(100) = NULL,
  @HopAckOn			Datetime = NULL, 
  @HopAckSize		VARCHAR(100) = NULL,
  @AfterHopFileMovedTo VARCHAR(MAX)=NULL, 
  @ReturnInt		INT = 0 output,
  @ClosePassword	VARCHAR(20) = NULL,
  @Exceptiondetail  NVARCHAR(MAX)=NULL,
  @FromDate			Datetime = NULL,
  @ToDate			Datetime = NULL,
  @ReturnValue		INT = 0 output,
  @RecordsCount		INT = 0,
  @GapInDays		VARCHAR(10)=NULL
)
AS 
BEGIN 
SET @ToDate= DATEADD(MS, -1, DATEADD(D, 1, CONVERT(DATETIME2, @ToDate)))
DECLARE @DEFAULTDATE DATETIME = '1912-10-25 00:00:00.000'
	--SET @GapInDays=(SELECT MaintainGapInDays FROM LineToHop_Configuration)
	DECLARE  @NoOfRows INT=100,@YEAR varchar(10),@Date VARCHAR(50), @MONTH VARCHAR(10),@MaintainGapOfInHours INT=10
	
	Select  @NoOfRows=MaxRows,@MaintainGapOfInHours=MaintainGapOfInHours from LineToHop_Configuration 
	CREATE TABLE #ArchiveTablesList(ArchiveId INT,Wh_Code VARCHAR(50),LineCode VARCHAR(50),LineId VARCHAR(50),CurrentDate DATETIME,NoOfRows INT, TableName VARCHAR(50),
	BackupToFolder VARCHAR(500),AfterSentToDestinationMoveToFolder VARCHAR(500),OutboxFolder VARCHAR(500),ScheduleIntervalInUnits INT,
	ScheduleIntervalUnits VARCHAR(50),DestinationServerIP VARCHAR(50),DestinationServerPort int,RC_ON_Column VARCHAR(50),AddWhereCondition VARCHAR(100)) 
	
	INSERT INTO #ArchiveTablesList Select Id,Wh_Code,LineCode,LineId,GETDATE(),MaxRows,TableName,BackupToFolder,AfterSentToDestinationMoveToFolder,
	OutboxFolder,ScheduleIntervalInUnits,ScheduleIntervalUnits,DestinationServerIP,DestinationServerPort,RC_ON_Column,AddWhereCondition 
	from LineToHop_Configuration(nolock) LHC Inner Join ArchiveTablesList(nolock) ATL on LHC.ConfigureID=ATL.ConfigurationID Where  IsActive=1  

	IF @Mode = 'APP_CLOSE'
	BEGIN		
		SELECT [ClosePassword] FROM [LineToHop_Configuration](nolock) where ClosePassword= @ClosePassword
	END
	
	IF @Mode = 'SETUP_CONFIGURATION'
	BEGIN		
		 SELECT [ConfigureID],[Wh_Code],[LineCode],[MaxRows],[RunMode],[DestinationServerIP],[DestinationServerPort],[BackupToFolder],[AfterSentToDestinationMoveToFolder]
      ,[OutboxFolder],HopDestinationPath,[ScheduleIntervalUnits],[ScheduleIntervalInUnits] ,[MaintainGapOfInHours],[DoUploadToDestination],[Ent_By],[ENT_DATE],[RunStatus]
		,DomainName,UserName,Password,UploadBatchSize,FilesToKeep FROM [LineToHop_Configuration](nolock)
		UPDATE LineToHop_Configuration set RunStatus=0
	END
	ELSE IF @Mode = 'GET_TABLENAME'
	BEGIN
		SELECT TOP (1000) [Id],[LineId],[TableName],[IdentityColumn],[RC_ON_Column],[RLU_ON_Column],[SeedId],[IsActive],[Remarks],
		[CreatedOn],[CreatedByName],[LastModifiedOn],[LastModifuedByName],[AddWhereCondition],[ConfigurationID]
		 FROM [ArchiveTablesList](nolock) Where  IsActive=1
		UPDATE LineToHop_Configuration set RunStatus=1
	END
	ELSE IF @Mode = 'FETCH_RECORDS'
	BEGIN	
	    Select NoOfRows,ArchiveId,Wh_Code,LineCode,LineId,REPLACE(CONVERT(VARCHAR, GETDATE(), 106),' ', '-') + ' ' + REPLACE(CONVERT(VARCHAR, GETDATE(), 8), ':', '.')AS CurrentDate,
		TableName,BackupToFolder,AfterSentToDestinationMoveToFolder,OutboxFolder,ScheduleIntervalInUnits,ScheduleIntervalUnits,DestinationServerIP,
		DestinationServerPort,RC_ON_Column,AddWhereCondition from #ArchiveTablesList(nolock) 

		Select  @ToRId=isnull(Max(ToRId),0) from ArchiveDetail(NOLOCK) where TableId=1 
		Select Top (@NoOfRows)  [ProfitCenterCode],[LineCode],[StationCode],[Datecode],[MachineCode],[OperationCode],[Barcode],ISNULL(TagName, '') as TagName,ISNULL([Value], '') as [Value],[Result]
		,ISNULL(UserID, '') as [UserID],[Timestamp],ISNULL(PartNo, '')as [PartNo],ISNULL(NULLIF(UID, null), '00000000-0000-0000-0000-000000000000') as [UID],ISNULL(ScanTimestamp, @DEFAULTDATE) as [ScanTimestamp],[CaliperDatecode],
		ISNULL(CaliperSrNo, 0) as [CaliperSrNo],ISNULL(IsSyncDone,0) as IsSyncDone,ISNULL(SyncTimeStamp, @DEFAULTDATE) as [SyncTimeStamp],ISNULL(LIVE_DATECODE, '')as [LIVE_DATECODE],[RID_NO],ISNULL(RC_ON, GETDATE()) as[RC_ON],ISNULL(RLU_ON, GETDATE()) as [RLU_ON]
		from Assy_LineAssyParamData(NOLOCK)  where RID_NO>@ToRId AND [Timestamp] < DATEADD(HH,-@MaintainGapOfInHours,getdate()) 
		ORDER BY RID_NO ASC
	
 	
		Select  @ToRId=isnull(Max(ToRId),0) from ArchiveDetail(NOLOCK) where TableId=2 
		Select Top (@NoOfRows) ISNULL(NULLIF(UID, null), '00000000-0000-0000-0000-000000000000') as [UID],[TagId],ISNULL([Value], '') as [Value],ISNULL(IsSyncDone,0) as IsSyncDone,ISNULL(SyncTimeStamp, @DEFAULTDATE) as [SyncTimeStamp],ISNULL(Timestamp, @DEFAULTDATE) as [Timestamp],
		[RID_NO],ISNULL(RC_ON, GETDATE()) as[RC_ON],ISNULL(RLU_ON, GETDATE()) as [RLU_ON],(select Wh_Code from LineToHop_Configuration)As [ProfitCenterCode],(select LineCode from LineToHop_Configuration)As LineCode 
		from Assy_LineAssyParamData_Dtl(NOLOCK) where RID_NO>@ToRId AND [Timestamp] < DATEADD(HH,-@MaintainGapOfInHours,getdate()) 
		ORDER BY RID_NO ASC
	

		Select  @ToRId=isnull(Max(ToRId),0) from ArchiveDetail(NOLOCK) where TableId=3 
		Select Top (@NoOfRows)  [ProfitCenterCode],[LineCode],[MachineCode],[OperationCode],[StationCode],[Barcode],ISNULL(TagName, '') as TagName,ISNULL([Value], '') as [Value],[Result],[Datecode]
		,ISNULL(UserID, '') as [UserID],[Timestamp],ISNULL(PartNo, '')as [PartNo],ISNULL(NULLIF(UID, null), '00000000-0000-0000-0000-000000000000') as [UID],ISNULL( ScanTimestamp, @DEFAULTDATE) as [ScanTimestamp],
		[CaliperDatecode],ISNULL(CaliperSrNo, 0) as [CaliperSrNo],ISNULL(LIVE_DATECODE, '')as [LIVE_DATECODE],[RID_NO],ISNULL(RC_ON, GETDATE()) as[RC_ON],ISNULL(RLU_ON, GETDATE()) as [RLU_ON]
		from Assy_LineAssyParamData_Running(NOLOCK) where RID_NO>@ToRId AND [Timestamp] < DATEADD(HH,-@MaintainGapOfInHours,getdate()) 
		ORDER BY RID_NO ASC

		Select  @ToRId=isnull(Max(ToRId),0) from ArchiveDetail(NOLOCK) where TableId=4
		Select Top (@NoOfRows) ISNULL(NULLIF(UID, null), '00000000-0000-0000-0000-000000000000') as [UID],[TagId],ISNULL([Value], '')as [Value],[Timestamp],[SyncTimeStamp],ISNULL(IsSyncDone,0) as IsSyncDone,[RID_NO],
		ISNULL(RC_ON, GETDATE()) as[RC_ON],ISNULL(RLU_ON, GETDATE()) as [RLU_ON],(select Wh_Code from LineToHop_Configuration)As [ProfitCenterCode],(select LineCode from LineToHop_Configuration)As LineCode 
		from Assy_LineAssyParamData_Running_Dtl(NOLOCK) where RID_NO>@ToRId AND [Timestamp] < DATEADD(HH,-@MaintainGapOfInHours,getdate()) 
		ORDER BY RID_NO ASC
	

		Select  @ToRId=isnull(Max(ToRId),0) from ArchiveDetail(NOLOCK) where TableId=5 
		Select Top (@NoOfRows)  [ProfitCenterCode],[LineCode],[MachineCode],[OperationCode],[StationCode],[Barcode],ISNULL([Status],'NA') as [Status],[FailCount],[Datecode],[PartNo],ISNULL( ScanTimestamp, @DEFAULTDATE) as [ScanTimestamp]
		,ISNULL(ResultTimestamp, @DEFAULTDATE) as [ResultTimestamp],ISNULL(Active,0) as Active,ISNULL(UserID, '')as [UserID],CASE  WHEN [IsTallyChartApproved] = 1 THEN 'True' WHEN [IsTallyChartApproved] = 0 THEN 'False' ELSE '5' END AS [IsTallyChartApproved],
		ISNULL(Transaction_Number, '')as [Transaction_Number],ISNULL(isConfirmed,0) as isConfirmed,ISNULL(Kanban_Id, '')as [Kanban_Id],ISNULL(ERP_Conf_Timestamp, @DEFAULTDATE) as ERP_Conf_Timestamp,ISNULL(IsReworkPart,0) as IsReworkPart,ISNULL(Is_Manual,0) as Is_Manual,ISNULL(IsPendingPart,0) as IsPendingPart
		,ISNULL(ProductionOrderNo, '')as [ProductionOrderNo],ISNULL(PROD_LOT_NO, '')as [PROD_LOT_NO],ISNULL(Category, '')as [Category],ISNULL(IsSyncDone,0) as IsSyncDone
		,ISNULL(SyncTimeStamp, @DEFAULTDATE) as SyncTimeStamp,ISNULL(LIVE_DATECODE, '')as [LIVE_DATECODE],[RID_NO],ISNULL(RC_ON, GETDATE()) as[RC_ON],ISNULL(RLU_ON, GETDATE()) as [RLU_ON] 
		from Assy_LineAssyStatus(NOLOCK) where RID_NO>@ToRId AND OperationCode<>'OCFV' AND ScanTimestamp < DATEADD(HH,-@MaintainGapOfInHours,getdate()) 
		ORDER BY RID_NO ASC
	

		Select  @ToRId=isnull(Max(ToRId),0) from ArchiveDetail(NOLOCK) where TableId=6
		Select Top (@NoOfRows) [ProfitCenterCode],[LineCode],[MachineCode],[OperationCode],[StationCode],[Barcode],ISNULL([Status],'NA') as [Status],[FailCount],[Datecode]
		,[PartNo],ISNULL(Active,0) as Active,ISNULL(ResultTimestamp, @DEFAULTDATE) as [ResultTimestamp],[ScanTimestamp],ISNULL(UserID, '')as [UserID],ISNULL(IsTallyChartApproved,0) as IsTallyChartApproved,ISNULL(IsReworkPart,0) as IsReworkPart,ISNULL(IsPendingPart,0) as IsPendingPart
		,ISNULL(ProductionOrderNo, '')as [ProductionOrderNo],ISNULL(PROD_LOT_NO, '')as [PROD_LOT_NO],ISNULL(Category, '')as [Category],ISNULL(LIVE_DATECODE, '')as [LIVE_DATECODE],
		[RID_NO],ISNULL(RC_ON, GETDATE()) as[RC_ON],ISNULL(RLU_ON, GETDATE()) as [RLU_ON] from Assy_LineAssyStatus_Running(NOLOCK) 
		where RID_NO>@ToRId AND ScanTimestamp < DATEADD(HH,-@MaintainGapOfInHours,getdate()) 
		ORDER BY RID_NO ASC
		

		--Select  @ToRId=isnull(Max(ToRId),0) from ArchiveDetail(NOLOCK) where TableId=7 
		--Select Top (@NoOfRows) [ProfitCenterCode], [LineCode], [MachineCode], [OperationCode], [Barcode], ISNULL([Status],'NA') as [Status], [Remarks], [Timestamp], ISNULL(UserID, '')as [UserID], [IsMailSent],
		--[RID_NO], ISNULL(RC_ON, GETDATE()) as[RC_ON],ISNULL(RLU_ON, GETDATE()) as [RLU_ON]
		--from Assy_LineAssyManualPassFail(NOLOCK) where RID_NO>@ToRId AND [Timestamp] < DATEADD(HH,-@MaintainGapOfInHours,getdate()) 
		--ORDER BY RID_NO ASC
				
		set @ReturnInt=1		
	END
	ELSE IF @Mode = 'CREATE_BATCH'
	BEGIN	
		if(@RecordsCount>0)
	begin
		Insert Into Archive (LineId,BackupTime,Remarks,CreatedOn,RowsCount)		
        Select Top 1 LineId,GETDATE(),'Created a Archival',GETDATE(),@RecordsCount from ArchiveTablesList (nolock) Where  IsActive=1
		end
 
		Select Top 1 Id,LineId,REPLACE(CONVERT(VARCHAR, CreatedOn, 106), ' ', '-') + ' ' + REPLACE(CONVERT(VARCHAR, CreatedOn, 8), ':', '.') as CreatedOn,RowsCount from Archive(nolock) order by Id desc	
	END
	ELSE IF @Mode = 'UPDATE_BATCH'
	BEGIN	
		UPDATE [dbo].[Archive] SET [HopIP] = @HopIP,[SentToHopOn] = @SentToHopOn,[SentToHopSize] = @SentToHopSize,[HopAckOn]=@HopAckOn,[HopAckSize]=@HopAckSize,[AfterHopFileMovedTo]=@AfterHopFileMovedTo WHERE Id=@ArchiveId
        Select Top 1 Id,LineId,REPLACE(CONVERT(VARCHAR, CreatedOn, 106), ' ', '-') + ' ' + REPLACE(CONVERT(VARCHAR, CreatedOn, 8), ':', '.') as CreatedOn,RowsCount from Archive(nolock) order by Id desc			
	END
	ELSE IF @Mode = 'TABLE_LOG_DETAIL'
	BEGIN	
		Insert Into ArchiveDetail ([ArchiveId],[TableId],[FromRId],[ToRId],[RowsCount],[Remarks],[CreatedOn],[CreatedByName],[LastModifiedOn],[LastModifuedByName])	
		Select @ArchiveId,@TableId,@FromRId,@ToRId,@RecordsCount,@Remarks,GETDATE(),NULL,GETDATE(),NULL
	END
	ELSE IF @Mode = 'CACULATE_BATCH'
	BEGIN	
	    Select Top 1 NoOfRows from #ArchiveTablesList(nolock)
		
		CREATE TABLE #MaxCount_Table(Total_Max_Count INT)
		Insert into #MaxCount_Table (Total_Max_Count)
		Select Count(*) from  Assy_LineAssyParamData(NOLOCK)
		Union ALL
		Select Count(*) from  Assy_LineAssyParamData_Dtl(NOLOCK)
		Union ALL
		Select Count(*) from  Assy_LineAssyParamData_Running(NOLOCK)
		Union ALL
		Select Count(*) from Assy_LineAssyParamData_Running_Dtl(NOLOCK)
		Union ALL
		Select Count(*) from Assy_LineAssyStatus(NOLOCK)
		Union ALL
		Select Count(*) from Assy_LineAssyStatus_Running(NOLOCK)
		Union ALL
		Select Count(*) from Assy_LineAssyManualPassFail(NOLOCK)
		Select MAX(Total_Max_Count) AS Total_Max_Count from #MaxCount_Table
		set @ReturnInt=1	
	END
	ELSE IF @Mode = 'GET_TABLEVIEWDATA'
	BEGIN		    
		select @TableId=id from ArchiveTablesList where TableName=@Table_Name
		Select AD.TableId,AD.FromRId,AD.ToRId,AD.[CreatedOn],AD.[LastModifiedOn] ,AD.RowsCount 
		from  ArchiveDetail AD (NOLOCK)  INNER JOIN ArchiveTablesList(NOLOCK) AL ON AD.TABLEID=AL.ID
		where tableid=@TableId			   
	END		   

	ELSE IF @Mode = 'GET_CON_VIEW'
	BEGIN	
		Select AL.TableName ,MAX(AD.ToRId) AS BackupRows
		from  ArchiveDetail AD(NOLOCK) INNER JOIN ArchiveTablesList AL(NOLOCK) ON AD.TABLEID=AL.ID	where AL.IsActive=1 GROUP BY AL.TableName	
	END		
	ELSE IF @Mode = 'FETCH_REPORT'
	BEGIN	
	  Select  SUBSTRING(AR.LineId, CHARINDEX('-', AR.LineId) + 1, LEN(AR.LineId))  as [Line Code] ,
	  CONCAT(ArchiveId, '.zip') as [Line To Hop Movement Files],ATL.TableName as [Table Name],AD.FromRId AS [From RID_NO],AD.ToRId AS [To RID_NO], AD.ToRId-(AD.FromRId-1) as [No of Record Fetched from Loacal DB] , 
	  AR.CreatedOn as [File Created Timestamp], AR.SentToHopOn as [File Sent to HOP Timestamp], (Select DestinationServerIP from LineToHop_Configuration(NOLOCK)) as [HOP IP], (Select HopDestinationPath from LineToHop_Configuration) as [Saved to HOP Location] from Archive AR(NOLOCK) inner join  ArchiveDetail AD(NOLOCK) on AR.Id=AD.ArchiveId inner join ArchiveTablesList ATL on AD.TableId=ATL.id 
	  where  Ar.CreatedOn BETWEEN @FromDate AND @ToDate
	  set @ReturnInt=1		
	  set @ReturnValue=5
	END
	ELSE IF @Mode = 'DeletionLog'
	BEGIN	
		SELECT DL.[LINECODE],CASE WHEN ISNULL([ArchiveId],'')='' THEN '-' ELSE CONCAT(DL.[ArchiveId], '.zip') END AS [ArchiveId],DL.[UNIQUE_ID] AS [BATCH ID],EL.[EVENT_NAME],
		DL.[TABLE_NAME],DL.[FROM_RID],DL.[TO_RID],DL.[DELETED_RECORDS],EL.[EVENT_START_TIME],EL.[EVENT_END_TIME],ISNULL(DL.[ERROR_DESC], 'OK') AS [REMARKS] FROM ARCHIVE_DELETION_LOG DL(NOLOCK) 
		INNER JOIN DELETE_EVENT_LOG EL(NOLOCK) ON DL.UNIQUE_ID=EL.EVENT_ID WHERE EL.EVENT_END_TIME BETWEEN @FromDate AND @ToDate	
	END
	ELSE IF @Mode = 'EXCEPTION_LOG'
	BEGIN	
		update ArchiveDetail set exception = @Exceptiondetail where  ArchiveId = @ArchiveId 
	END	
	--ELSE IF @Mode = 'DELETE_FILES'
--BEGIN	
--	update Archive set DELETION_REMARKS = 'This Zip file has been deleted by the user due to less space.' where  id = @ArchiveId 
--END?
END

GO
/****** Object:  StoredProcedure [dbo].[PROC_Get_Table_ColValue_Query]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/***************************************************************************************                    
PROCEDURE         :     PROC_Get_Table_ColValue_Query
AUTHOR            :     SACHIN KUMAR
DATE WRITTEN      :     2021-06-09
PURPOSE           :     Proc to generate table column name and values
TEST SCRIPT  

exec PROC_Get_Table_ColValue_Query @P_table_name='PUSH_OP10_01_SEALCHECK'
****************************************************************************************/
create procedure [dbo].[PROC_Get_Table_ColValue_Query]
(
  @P_table_name	SYSNAME 
)
as
begin
	
	
	DECLARE   @DummySQLQuery AS NVARCHAR(MAX)
	DECLARE   @SQLQuery AS NVARCHAR(MAX)
	DECLARE   @PivotColumns AS NVARCHAR(MAX)

	declare @dynamictblcoldetails as table
	(
		TableName varchar(255),
		ColumnName varchar(255),
		DataType varchar(255),
		is_computed	 bit,
		max_length	 int,
		scale	int,
		[precision]	int,
		definition varchar(255),	
		column_id int,	
		is_identity	bit,
		PrimaryKeyCol int,
		RANK_DT_ML int
	)

	declare @PivotCols as table
	(
		PivotCols varchar(max),		
		RANK_DT_ML int,
		DataType varchar(255)
	)
	
	insert into @dynamictblcoldetails
	exec PROC_Get_Table_ColName @P_table_name=@P_table_name

	delete from @dynamictblcoldetails where ColumnName='RFID'

	insert into @PivotCols(RANK_DT_ML,PivotCols,DataType)
	SELECT RANK_DT_ML,
		STUFF((
		SELECT ', ' +  QUOTENAME(ColumnName)
		FROM @dynamictblcoldetails 
		WHERE (RANK_DT_ML = Results.RANK_DT_ML) 
		FOR XML PATH(''),TYPE).value('(./text())[1]','VARCHAR(MAX)')
		,1,2,'') AS PivotCols ,DataType 
	FROM @dynamictblcoldetails Results
	GROUP BY RANK_DT_ML,DataType

	SET   @DummySQLQuery = '
	SELECT   RFID as ID,ColName,@@ColVal
	FROM '+@P_table_name+' (nolock)
	UNPIVOT
	(
		ColVal
		FOR [ColName] IN (@PivotColumns)
	) AS P ' 
	-- REPLACE(REPLACE(@DummySQLQuery,'@PivotColumns',PivotCols),'@convert','')
	--select * from @PivotCols

	select @PivotColumns= COALESCE(@PivotColumns + ' UNION ','') + 
	case DataType
	when 'varchar' then	REPLACE(REPLACE(@DummySQLQuery,'@PivotColumns',PivotCols),'@@ColVal','ColVal')
	when 'datetime' then REPLACE(REPLACE(@DummySQLQuery,'@PivotColumns',PivotCols),'@@ColVal','convert(varchar, ColVal, 25) as ColVal')
	ELSE REPLACE(REPLACE(@DummySQLQuery,'@PivotColumns',PivotCols),'@@ColVal','convert(varchar, ColVal) as ColVal')
	END
	from @PivotCols --where RANK_DT_ML in (1,2,3)

	 select @P_table_name as TableName,ISNULL(@PivotColumns,'') as Query
	--select convert(varchar, getdate(), 25)
	--select getdate()	
	--EXEC sp_executesql @PivotColumns
end


GO
/****** Object:  StoredProcedure [dbo].[Proc_Jhagadia_Reports]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[Proc_Jhagadia_Reports]
(
	@ProfitCentercode	VARCHAR(10)=null,
	@LineCode			VARCHAR(10)=null,
	@DateCode			VARCHAR(10)='',
	@Condition			VARCHAR(50)='',
	@Barcode			VARCHAR(100)='',
	@SaveUpdateInfo     NVARCHAR(max)='',
	@isDateCodeFilter	bit=1,
	@FromDate			varchar(20)='',
	@ToDate				varchar(20)='',
	@ReturnValue		VARCHAR(50)='' OUT,
	@ReturnInt			INT=0	OUT,
	@P_ReportType		INT=1,
	@P_RESULT			VARCHAR(10)='PS',
	@PartNo				VARCHAR(20)=''

	/*
		Created By			: Sundaramoorthi S
		Created Date		: 15-Jan-2017
		Last Accessed By	: Sundaramoorthi S
		
		Last Modified Date	: 27-Jan-2017
		Description			: Develop the final report for the Jahagadia.

		Last Modified Date :  31-01-2017
		Description        : Added TagSeqNo To Sort Tag Parameter in excel. 

		Modified By		   : Sachin
		Last Modified Date : 08-04-2017 
		Description		   : Change Assy_TraceabilityAnalysis_Tags -> Assy_ReportAnalysis_Tags

		Modified By		   : Aman Virmani
		Last Modified Date : 20170621 
		Description		   : ADDED DEFAULT PARAMETER IN PROCEDURE TO MAKE COMPATIBLE WITH PADI PROCEDURE

		Modified By		   : Aman Virmani
		Last Modified Date : 20170811 
		Description		   : CHANGES FOR NEW REPORT FORMAT

		Modified By		   : Aman Virmani
		Last Modified Date : 20170829 
		Description		   : ADDED PART NO FILTER
 	*/
)
AS
BEGIN
	--EXECUTE Proc_Jhagadia_Reports @ProfitCenterCode='0088',@DateCode='27Qc',@LineCode='J04',@Condition='CALIPER_LINE_EXCEL_REPORT'

	-- TRACE SERIAL ON THE BASIS OF ENGRAVED CALIPER SERIAL NUMBER

	BEGIN TRY 
	DROP TABLE #DATE_CODE
	DROP TABLE #BARCODE
	END TRY
	BEGIN CATCH

	END CATCH

	CREATE TABLE #DATE_CODE
	(
	  DATECODE nvarchar(4) COLLATE SQL_Latin1_General_CP1_CI_AS   

	)

	CREATE TABLE #BARCODE
	(
	  BARCODE nvarchar(100) COLLATE SQL_Latin1_General_CP1_CI_AS   

	)
	IF(@Condition='GET_PART_DETAILS')
	BEGIN
		SELECT PG.CustomerPartNo AS CustomerPart,PM.Product_nm as PartDesc From  Assy_PRN_CustomerGroupMaster PG
		INNER JOIN PRODUCT_MASTER PM ON PG.PartNo=PM.SEWS_PART_NO
		WHERE PM.SEWS_PART_NO=@PartNo and PM.warehouse_cd=@ProfitCentercode

		RETURN
	END
	IF(@P_ReportType=2)
	BEGIN
		IF(@Condition='GET_PARTS')
		BEGIN
			SELECT DISTINCT PartNo FROM Assy_View_ParamData
		END
		IF(@Condition='GET_CAP_SERIAL_DATA')
		BEGIN
			SELECT 
			 A.PartNo
			,T.ReportDesc
			,RC.OperationSeqNo
			,ATAT.MinValue+'-'+ATAT.MaxValue+' '+ATAT.UOM AS [SPECIFICATION / TOLERANCE]
			,'' AS [STAGE OF INSPECTION]
			,RIGHT('0000'+ CAST(R.CaliperSerNo  AS VARCHAR(4)), 4) +'-'+R.CaliperDatecode AS RFID
			,CASE WHEN A.Value='TRUE' THEN 'OK' 
									   WHEN  A.Value='FALSE' THEN 'NG' 
										WHEN A.Value='PS' THEN 'PASS'
									   WHEN A.Value='FL' THEN 'FAIL' 
									   ELSE isnull(A.Value,'') END AS value 
			INTO #REPORT_DATA
			FROM Assy_View_ParamData A
			INNER JOIN ASSY_FINALVIEWING_RFID_BARCODE_MAPPING R ON A.Barcode=R.RFID 
			INNER JOIN Assy_ReportAnalysis_Tags(nolock) ATAT ON ATAT.TagName = A.TagName
			INNER JOIN RoutingConfigLineWise RC ON ATAT.OperationSeqno=RC.OperationSeqNo
			INNER JOIN TagMst T ON T.TagId = A.TagId
			WHERE A.RESULT =@P_RESULT AND  A.PartNo=@PartNo
			--AND R.CaliperSerNo=1 
			AND A.TagName<>'CALIPER_SERIAL_NO'
			AND R.CaliperDatecode=IsNULL(NULLIF(@DateCode,''),R.CaliperDatecode)
			AND R.CaliperSerNo=IsNUll(NullIf(@Barcode,''),R.CaliperSerNo)
			ORDER BY R.RFID,ATAT.OperationSeqno

			IF @@ROWCOUNT=0
			BEGIN
				RETURN
			END
			DECLARE @Param_Code VARCHAR(MAX)=''
			SELECT  @Param_Code = STUFF(( SELECT DISTINCT
										  '],[' + RFID
										  FROM #REPORT_DATA (NOLOCK)
										  ORDER BY '],[' + RFID
										  FOR XML PATH('')
										  ), 1, 2, '') + ']'
			declare @strQuery VARCHAR(max)=''
			SET @strQuery =
							'SELECT * INTO TEMP FROM
							(
								SELECT OperationSeqNo,ReportDesc AS TagName,[SPECIFICATION / TOLERANCE], RFID, Value
								FROM #REPORT_DATA
							)t
							PIVOT (MIN(Value) FOR RFID
							IN ('+@Param_Code+')) AS pvt
							ORDER BY OperationSeqNo '
							PRINT @strQuery
							EXECUTE (@strQuery)

					
							SELECT * FROM TEMP
							ORDER BY OperationSeqNo

							--DROP TABLE #COL
							DROP TABLE TEMP
							DROP TABLE #REPORT_DATA

			END
	END
	ELSE
	BEGIN 
		IF(@Condition='TRACEABILITY_USING_CALIPER_DATE_CODE')
		begin
		
			INSERT INTO #DATE_CODE
			SELECT DISTINCT DATECODE FROM ASSY_FINALVIEWING_RFID_BARCODE_MAPPING(NOLOCK)
			WHERE CaliperDatecode=@DATECODE
			--SELECT TOP 1 @DATECODE=DATECODE FROM ASSY_FINALVIEWING_RFID_BARCODE_MAPPING(NOLOCK)
		
		
			INSERT INTO #BARCODE
			SELECT distinct RFID FROM ASSY_FINALVIEWING_RFID_BARCODE_MAPPING(NOLOCK)
			WHERE CaliperDatecode=@DATECODE 
			--and CaliperSerNo= CONVERT(int,@Barcode)




			SET @Condition='TRACEABILITY_MASTER_SHEET_DATA_PASS'

		end

		IF(@Condition='TRACEABILITY_USING_CALIPER_SERIAL')
		begin
		
		INSERT INTO #DATE_CODE
		SELECT DISTINCT DATECODE FROM ASSY_FINALVIEWING_RFID_BARCODE_MAPPING(NOLOCK)
		WHERE CaliperDatecode=@DATECODE

		INSERT INTO #BARCODE
		SELECT distinct RFID FROM ASSY_FINALVIEWING_RFID_BARCODE_MAPPING(NOLOCK)
		WHERE CaliperDatecode=@DATECODE 
		and CaliperSerNo= CONVERT(int,@Barcode)

		SET @Condition='TRACEABILITY_MASTER_SHEET_DATA_PASS'

		end

		IF(@Condition='CALIPER_LINE_EXCEL_REPORT')	
		BEGIN
			SELECT	(ROW_NUMBER() OVER (ORDER BY TB1.BARCODE ASC)) SNO
					,'N/A' as UID
					,TB1.BARCODE
					--,TB1.LINECODE
					--,TB1.MACHINECODE
					,TB1.MC4S_Timestamp
					,TB1.SealChecking
					,TB1.ContinuityTesting
					,TB1.TORQUE
					,TB1.TORQUE_ANGLE
					,TB2.MCSP_Timestamp
					,TB2.[SLEEVE_TAG.SLEEVE_PRESS_LOAD]
					--,TB2.MachineCode
					--,TB3.MachineCode
					,TB3.MCPA_TimeStamp
					,TB3.WASHER_STATUS
					,TB3.ORING_STATUS
					,TB3.EXCLUDER_PRESSURE
					,TB3.STROKE_FORCE
					,(CAST(CAST(TB3.[LPT_ACT_DROP_PR] AS FLOAT) AS DECIMAL(28, 16)))
					,TB4.MCLP_TIMESTAMP
					,TB4.PFT_ACT_DROP
					,TB4.DYNAMIC_PR_ACT_DROP
					--,TB5.MachineCode
					,TB5.MCHP_TimeStaMp
					,TB5.HP_ACT_DROP
					--,TB6.MachineCode
					,TB6.MCAT_TIMESTAMP
					,TB6.LH_TORQUE
					,TB6.LH_TORQUE_ANGLE
					,TB6.RH_TORQUE
					,TB6.RH_TORQUE_ANGLE
					--,TB7.MACHINECODE
					,TB7.MCET_TIMESTAMP
					,TB7.[ACTUATOR]
					,TB7.t_start_1
					,TB7.I_PEAK_SUPPLY
					,TB7.t_idle_1
					,TB7.I_IDLE_SUPPLY
					,TB7.T_FAIL_SAFE
					,TB7.f_threshold_1
					,TB7.T_APPLY
					,TB7.F_CLAMP1
					,TB7.F_CLAMP2
					,TB7.F_SUPPLY
					,TB7.F_HOLD_DIFF
					,TB7.I_IDLE_RELEASE
					,TB7.I_RELEASE
					,TB7.t_release
					,TB7.T_CLAMP
					,TB7.I_OSCILLATION
					--,TB8.MACHINECODE
					,TB8.LOADING_TORQUE_OK
					,TB8.AR_CLIP_ASSY
					,TB8.SLIDE_PIN_LENGTH_AND_DIA
					,TB8.PAD_SUB_ASSY
					,TB8.[carr_assy.PROBING_OK]
					,TB8.LH_TORQUE
					,TB8.LH_TORQUE_ANGLE
					,TB8.RH_TORQUE
					,TB8.RH_TORQUE_ANGLE
					,TB8.PROFILE_CHECK
					,TB8.ASR_TEST_VALUE
					,TB8.DATE_CODE_COUPLING
					,TB8.PLANT_CODE
					,TB8.CALIPER_SERIAL_NO
					,TB9.[MCFV Barcode] FROM (SELECT PROFITCENTERCODE, Barcode,LineCode,MachineCode,PARTNO,
														(CASE WHEN [ROT_STN.seal_ok]='True' THEN 'OK' 
															WHEN [ROT_STN.seal_ng]='True' THEN 'NOT OK'
															ELSE '' END) AS SealChecking,
														(CASE WHEN [ROT_STN.bleed_cont_ok]='True' THEN 'OK' 
															WHEN [ROT_STN.bleed_cont_ng]='True' THEN 'NOT OK'
															ELSE '' END) AS ContinuityTesting,
												[TORQUE],
												[TORQUE_ANGLE],TIMESTAMP as MC4S_Timestamp FROM (SELECT PROFITCENTERCODE, Barcode,LineCode,MachineCode,PARTNO,TagName,isnull(Value,0) as value,TIMESTAMP FROM Assy_View_ParamData 
																		WHERE DATECODE=@DateCode AND LineCode=@LineCode AND MACHINECODE='MC4S' AND RESULT='PS') TB
												PIVOT
												(MAX(VALUE) FOR TAGNAME IN ([ROT_STN.bleed_cont_ng],
												[ROT_STN.bleed_cont_ok],
												[ROT_STN.seal_ng],
												[ROT_STN.seal_ok],
												[TORQUE],
												[TORQUE_ANGLE]
												)) PITB1) TB1
											INNER JOIN
												(SELECT PROFITCENTERCODE, Barcode,LineCode,MachineCode,PARTNO,TIMESTAMP as MCSP_Timestamp,
													[SLEEVE_TAG.SLEEVE_PRESS_LOAD] FROM (SELECT PROFITCENTERCODE, Barcode,LineCode,MachineCode,PARTNO,TIMESTAMP,TagName,isnull(Value,0) as value FROM Assy_View_ParamData 
																							WHERE DATECODE=@DateCode 
																								AND LineCode=@LineCode 
																								AND machinecode='MCSP' 
																								AND RESULT='PS') TB
												PIVOT
												(MAX(VALUE) FOR TAGNAME IN ([SLEEVE_TAG.SLEEVE_PRESS_LOAD]
												)) PITB)  TB2  ON TB1.ProfitCenterCode=TB2.ProfitCenterCode
													AND TB1.Barcode=TB2.Barcode
													AND TB1.LineCode=TB2.LineCode
											INNER JOIN
												(SELECT PROFITCENTERCODE, Barcode,LineCode,MachineCode,PARTNO,
														'' As WASHER_STATUS,
														'' AS ORING_STATUS,
												[EXCLUDER_PRESSURE],
												[STROKE_FORCE],
												[LPT_ACT_DROP_PR],TIMESTAMP AS MCPA_TimeStamp FROM (SELECT PROFITCENTERCODE, Barcode,LineCode,MachineCode,PARTNO,TagName,TIMESTAMP,isnull(Value,0) as value FROM Assy_View_ParamData 
																					WHERE DATECODE=@DateCode 
																						AND LineCode=@LineCode 
																						AND MACHINECODE='MCPA' 
																						AND RESULT='PS') TB
												PIVOT
												(MAX(VALUE) FOR TAGNAME IN ([EXCLUDER_PRESSURE],
												[STROKE_FORCE],
												[LPT_ACT_DROP_PR]
												)) PITB1) TB3 ON TB1.ProfitCenterCode=TB3.ProfitCenterCode
													AND TB1.Barcode=TB3.Barcode
													AND TB1.LineCode=TB3.LineCode
											INNER JOIN
												(SELECT PROFITCENTERCODE, Barcode,LineCode,MachineCode,PARTNO,
														[PFT_ACT_DROP],
														[DYNAMIC_PR_ACT_DROP],
														TIMESTAMP AS MCLP_TIMESTAMP FROM (SELECT PROFITCENTERCODE, Barcode,LineCode,MachineCode,PARTNO,TagName,TIMESTAMP,isnull(Value,0) as value FROM Assy_View_ParamData 
																							WHERE DATECODE=@DateCode 
																								AND LineCode=@LineCode 
																								AND MACHINECODE='MCLP' 
																								AND RESULT='PS') TB
												PIVOT
												(MAX(VALUE) FOR TAGNAME IN (
												[PFT_ACT_DROP]
												,[DYNAMIC_PR_ACT_DROP]
												)) PITB1) TB4 ON TB1.ProfitCenterCode=TB4.ProfitCenterCode
													AND TB1.Barcode=TB4.Barcode
													AND TB1.LineCode=TB4.LineCode
											INNER JOIN
												(SELECT PROFITCENTERCODE, Barcode,LineCode,MachineCode,PARTNO,
														[HP_ACT_DROP],
														TIMESTAMP AS MCHP_TIMESTAMP FROM (SELECT PROFITCENTERCODE, Barcode,LineCode,MachineCode,PARTNO,TagName,TIMESTAMP,isnull(Value,0) as value FROM Assy_View_ParamData 
																								WHERE DATECODE=@DateCode 
																									AND LineCode=@LineCode 
																									AND MACHINECODE='MCHP' 
																									AND RESULT='PS') TB
												PIVOT
												(MAX(VALUE) FOR TAGNAME IN (
												[HP_ACT_DROP]
												)) PITB1) TB5 ON TB1.ProfitCenterCode=TB5.ProfitCenterCode
													AND TB1.Barcode=TB5.Barcode
													AND TB1.LineCode=TB5.LineCode
											INNER JOIN
												(SELECT PROFITCENTERCODE, Barcode,LineCode,MachineCode,PARTNO,
														[LH_TORQUE],
														[LH_TORQUE_ANGLE],
														[RH_TORQUE],
														[RH_TORQUE_ANGLE],
														TIMESTAMP AS MCAT_TIMESTAMP FROM (SELECT PROFITCENTERCODE, Barcode,LineCode,MachineCode,PARTNO,TagName,TIMESTAMP,isnull(Value,0) as value FROM Assy_View_ParamData 
																							WHERE DATECODE=@DateCode 
																								AND LineCode=@LineCode 
																								AND MACHINECODE='MCAT' 
																								AND RESULT='PS') TB
												PIVOT
												(MAX(VALUE) FOR TAGNAME IN (
												[LH_TORQUE]
												,[LH_TORQUE_ANGLE]
												,[RH_TORQUE]
												,[RH_TORQUE_ANGLE]
												)) PITB1) TB6 ON TB1.ProfitCenterCode=TB6.ProfitCenterCode
													AND TB1.Barcode=TB6.Barcode
													AND TB1.LineCode=TB6.LineCode
											INNER JOIN
												(SELECT PROFITCENTERCODE, Barcode,LineCode,MachineCode,PARTNO,
														[ACTUATOR],
														'N/A' AS t_start_1,
														[I_PEAK_SUPPLY],
														'N/A' AS t_idle_1,
														[I_IDLE_SUPPLY],
														[T_FAIL_SAFE],
														'N/A' AS f_threshold_1,
														[T_APPLY],
														[F_CLAMP1],
														[F_CLAMP2],
														[F_SUPPLY],
														[F_HOLD_DIFF],
														[I_IDLE_RELEASE],
														[I_RELEASE],
														'N/A' AS t_release,
														[T_CLAMP],
														[I_OSCILLATION],
														TIMESTAMP AS MCET_TIMESTAMP FROM (SELECT PROFITCENTERCODE, Barcode,LineCode,MachineCode,PARTNO,TagName,TIMESTAMP,isnull(Value,0) as value FROM Assy_View_ParamData 
																							WHERE DATECODE=@DateCode 
																								AND LineCode=@LineCode 
																								AND MACHINECODE='MCET' 
																								AND RESULT='PS') TB
												PIVOT
												(MAX(VALUE) FOR TAGNAME IN (
												[ACTUATOR]	
												,[I_PEAK_SUPPLY]
												,[I_IDLE_SUPPLY]
												,[T_FAIL_SAFE]
												,[T_APPLY]
												,[F_CLAMP1]
												,[F_CLAMP2]
												,[F_SUPPLY]
												,[F_HOLD_DIFF]
												,[I_IDLE_RELEASE]
												,[I_RELEASE]
												,[T_CLAMP]
												,[I_OSCILLATION]
												)) PITB1) TB7 ON TB1.ProfitCenterCode=TB7.ProfitCenterCode
													AND TB1.Barcode=TB7.Barcode
													AND TB1.LineCode=TB7.LineCode
											INNER JOIN
												(SELECT PROFITCENTERCODE, Barcode,LineCode,MachineCode,PARTNO,
														[LOADING_TORQUE_OK],
														[AR_CLIP_ASSY],
														[SLIDE_PIN_LENGTH_AND_DIA],
														[PAD_SUB_ASSY],
														[carr_assy.PROBING_OK],
														[LH_TORQUE],
														[LH_TORQUE_ANGLE],
														[RH_TORQUE],
														[RH_TORQUE_ANGLE],
														[PROFILE_CHECK],
														[ASR_TEST_VALUE],
														[DATE_CODE_COUPLING],
														[PLANT_CODE],
														[CALIPER_SERIAL_NO],
														[MCFV Barcode]
													FROM (SELECT PROFITCENTERCODE, Barcode,LineCode,MachineCode,PARTNO,TagName,TIMESTAMP,isnull(Value,0) as value FROM Assy_View_ParamData 
															WHERE DATECODE=@DateCode 
																AND LineCode=@LineCode 
																AND MACHINECODE = 'MCCP' 
																AND RESULT='PS') TB
												PIVOT
												(MAX(VALUE) FOR TAGNAME IN (
												[LOADING_TORQUE_OK]	
												,[AR_CLIP_ASSY]
												,[SLIDE_PIN_LENGTH_AND_DIA]
												,[PAD_SUB_ASSY]
												,[carr_assy.PROBING_OK]
												,[LH_TORQUE]
												,[LH_TORQUE_ANGLE]
												,[RH_TORQUE]
												,[RH_TORQUE_ANGLE]
												,[PROFILE_CHECK]
												,[ASR_TEST_VALUE]
												,[DATE_CODE_COUPLING]
												,[PLANT_CODE]
												,[CALIPER_SERIAL_NO]
												,[MCFV Barcode]
												)) PITB1) TB8 ON TB1.ProfitCenterCode=TB8.ProfitCenterCode
													AND TB1.Barcode=TB8.Barcode
													AND TB1.LineCode=TB8.LineCode
											INNER JOIN
												(SELECT PROFITCENTERCODE, Barcode,LineCode,MachineCode,PARTNO,
														[MCFV Barcode]
													FROM (SELECT PROFITCENTERCODE, Barcode,LineCode,MachineCode,PARTNO,TagName,TIMESTAMP,isnull(Value,0) as value FROM Assy_View_ParamData 
															WHERE DATECODE=@DateCode 
																AND LineCode=@LineCode 
																AND MACHINECODE = 'MCFV' 
																AND RESULT='PS') TB
												PIVOT
												(MAX(VALUE) FOR TAGNAME IN (
												[MCFV Barcode]
												)) PITB1) TB9 ON TB1.ProfitCenterCode=TB9.ProfitCenterCode
													AND TB1.Barcode=TB9.Barcode
													AND TB1.LineCode=TB9.LineCode
		END

	--Get barcode details from Assy_LineAssyStatus table.
	ELSE IF(@Condition='GET_BARCODE_DETAILS')
		BEGIN
			SELECT Barcode FROM Assy_LineAssyStatus 
			WHERE Datecode=@DateCode
				AND	LINECODE=@LineCode	
				AND ProfitCenterCode=@ProfitCentercode
				AND MACHINECODE = 'MCFV' 

			SET @ReturnInt=0;
			SET @ReturnValue='SUCCESS';
		END
	
	--EXECUTE Proc_Jhagadia_Reports @ProfitCenterCode='0088',@DateCode='27Qc',@LineCode='J04',@Condition='CALIPER_LINE_EXCEL_REPORT'
	--Get Particular barcode parameter details
	ELSE IF(@Condition='GET_BARCODE_PARAMETERDETAILS')
		BEGIN
	--(CAST(CAST(TB3.[LPT_ACT_DROP_PR] AS FLOAT) AS DECIMAL(28, 16)))
		--IF('tmpdb.dbo.#ParameterTable') IS NOT NULL
			--DROP TABLE #ParameterTable

			SELECT DISTINCT AVP.PROFITCENTERCODE
				,AVP.Barcode
				--,AVP.LineCode
				,MM.MachineName
				--,AVP.PARTNO
				,TM.TagDescription
				,TM.TagName
				,isnull(Value,0) as value
				,CASE  WHEN Result='PS' THEN 'PASS'
					WHEN Result='FL' THEN 'FAIL'
					ELSE 'FAIL' END AS Result
				,AVP.TIMESTAMP 
				,RCLW.OperationSeqNo
			INTO #ParameterTable FROM Assy_View_ParamData AVP
				INNER JOIN MACHINEMST MM WITH (NOLOCK) ON AVP.MachineCode=MM.MachineCode
					AND AVP.PROFITCENTERCODE=MM.PROFITCENTERCODE
				INNER JOIN RoutingConfigLineWise RCLW ON AVP.LineCode=RCLW.LineCode
					AND AVP.MachineCode=RCLW.MachineCode
				INNER JOIN Assy_ReportAnalysis_Tags(NOLOCK) ATAT ON AVP.ProfitCenterCode=ATAT.ProfitCentercode
					AND ISNULL(avp.TagName,avp.MachineCode) IN (SELECT CASE WHEN tagname='' 
					THEN MachineCode + ' Barcode' ELSE tagname END AS tagname FROM Assy_ReportAnalysis_Tags(NOLOCK) 
					WHERE ProfitCentercode= @ProfitCenterCode AND LineCode=@LineCode AND activestatus=1)
				LEFT JOIN TagMst TM ON AVP.ProfitCenterCode=TM.ProfitCenterCode
					AND ISNULL(AVP.TagId,0)=ISNULL(TM.TagId,0)
				
			WHERE BARCODE=@Barcode
					AND AVP.LineCode=@LineCode 
					--AND AVP.RESULT='PS'
					AND AVP.DATECODE=@DateCode 
			ORDER BY RCLW.OperationSeqNo ASC

			UPDATE #ParameterTable SET value=(CAST(CAST((SELECT TOP 1 value FROM #ParameterTable WHERE BARCODE=@Barcode
					AND TagName='LPT_ACT_DROP_PR')  AS FLOAT) AS DECIMAL(28, 16))) WHERE TagName='LPT_ACT_DROP_PR'

			SELECT PROFITCENTERCODE
				,Barcode
				,OperationSeqNo
