			update #Assy_View_ParamData_TB  set value = left(convert(decimal(8,2),value)/1000,8) where tagname = 'clamp2'
			DECLARE @cols NVARCHAR(MAX);
			DECLARE @Qry NVARCHAR(MAX);
				
		    
					 
				CREATE TABLE #Barcodes
				(
				  Barcode varchar(100)
				)

				if(isnull(@Barcode,'')='')
				begin
				insert into #Barcodes
				SELECT DISTINCT  Barcode  FROM Assy_View_ParamData(nolock) 
				WHERE Datecode in (select DATECODE from #DATE_CODE) --=@DateCode 
				AND Barcode in (select TOP 318 BARCODE from #BARCODE) ---BY RKB
				AND LineCode=@LineCode 
				AND ProfitCenterCode=@ProfitCentercode 
				GROUP BY BARCODE,MachineCode HAVING MachineCode IN ('MCFV')
				end
				else
				begin
				insert into #Barcodes
				SELECT DISTINCT Barcode  FROM Assy_View_ParamData(nolock) 
				WHERE Datecode in (select DATECODE from #DATE_CODE) --=@DateCode 
				AND LineCode=@LineCode 
				AND ProfitCenterCode=@ProfitCentercode AND Barcode in (select BARCODE from #BARCODE) --=@barcode
				GROUP BY BARCODE,MachineCode HAVING MachineCode IN ('MCFV')
				end
				
				SELECT @cols = STUFF((SELECT ',' +  QUOTENAME(BARCODE) FROM #Barcodes
															FOR XML PATH(''), TYPE
															).value('.', 'NVARCHAR(MAX)') 
														,1,1,'')
														
			
			SET @Qry=' SELECT tb1.* INTO #ReportTable FROM  (
										SELECT CustomerOperationNo As OperationNo
												,Barcode
												,MachineCode
												,Seq_No
												,TagName
												,MinValue As [Min Value]
												,MaxValue As [Max Value]
												,UOM As [UOM]
												,ISNULL(Value,0) AS value
												,TagSeqNo
										FROM #Assy_View_ParamData_TB 
										WHERE ISNULL(VALUE,'''')<>''''
										) tb
												PIVOT (MAX(VALUE) FOR Barcode  IN (' + @cols + ')) TB1
									INNER JOIN #RoutingConfigLineWise RCFL ON tb1.MachineCode=RCFL.MachineCode
										ORDER BY RCFL.OperationSeqNo ASC		

					update q
					set q.OperationNo = a.CustomerOperationNo
					from #ReportTable q
					inner join RoutingConfigLineWise a
					on q.MachineCode = a.MachineCode

					update q
					set q.MachineCode = a.MachineName
					from #ReportTable q
					inner join MachineMst a
					on q.MachineCode = a.MachineCode

					
					SELECT q.* into	 ReportTable_TMP				
