					on q.MachineCode =a.MachineName
					INNER JOIN #RoutingConfigLineWise RCFL ON a.MachineCode=RCFL.MachineCode
					ORDER BY RCFL.OperationSeqNo  ASC

					
					'
				
					EXEC sp_sqlexec @Qry
					print @Qry

					-- Modified By Sachin 20170131
					select name, column_id into #ReportTable_ColumnName  from sys.columns where object_id =
					object_id('ReportTable_TMP') and name <> 'TagSeqNo'

					--select * from #ReportTable_ColumnName
					
					SELECT @cols = STUFF((SELECT ',' + 'ISNULL(q.' + QUOTENAME(name)+','''')' + ' AS ' +QUOTENAME(name) FROM #ReportTable_ColumnName
										order by column_id asc
															FOR XML PATH(''), TYPE
															).value('.', 'NVARCHAR(MAX)') 
														,1,1,'')
										
					if(isnull(@cols,'') <> '')
