					update ReportTable_TMP 
					set seq_no = convert(varchar,operationno) + '-' + seq_no
					where seq_no in ('R' , 'T')

					set @Qry=' select '+ @cols +' from ReportTable_TMP q
					inner join #MachineMst a
					on q.MachineCode =a.MachineName
					INNER JOIN #RoutingConfigLineWise RCFL ON a.MachineCode=RCFL.MachineCode
					ORDER BY RCFL.OperationSeqNo , TagSeqNo  ASC '

					print @Qry
					exec sp_sqlexec @Qry
					drop table ReportTable_TMP
					end
					--

