		 BEGIN TRY
				
				BEGIN TRAN
				
				SELECT  
				col1 as 'ProfitCentercode',
				col2 as 'LineCode',
				col3 as 'MachineCode',
				col4 as 'CustomerTagSeqNo',
				col5 as 'ActiveStatus',
				col6 as 'TagId',
				col7 as 'Updated_By'
				into #TEMP_ASSY_TRACEABILITYANALYSIS_TAGS 
				FROM FN_GRID_SPLIT_STRING(@SAVEUPDATEINFO,'|','#')

				
				--update #TEMP_ASSY_TRACEABILITYANALYSIS_TAGS
				--set ActiveStatus='1'
				--where ActiveStatus='true'

				--update #TEMP_ASSY_TRACEABILITYANALYSIS_TAGS
				--set ActiveStatus='0'
				--where ActiveStatus='false'
				
