				--T.ProfitCentercode=S.ProfitCentercode and
				--T.LineCode = S.LineCode and
				--T.MachineCode = S.MachineCode
				

				MERGE  Assy_ReportAnalysis_Tags AS T
				USING #TEMP_ASSY_TRACEABILITYANALYSIS_TAGS  AS S
				ON 
				( isnull(T.TagId,0)=isnull(S.TagID,0) and 
				T.ProfitCentercode=S.ProfitCentercode and
				T.LineCode = S.LineCode and
				T.MachineCode = S.MachineCode
				) 
				--WHEN NOT MATCHED BY TARGET AND S.EmployeeName LIKE 'S%' 
				--THEN INSERT(EmployeeID, EmployeeName) VALUES(S.EmployeeID, S.EmployeeName)
				WHEN MATCHED and T.ActiveStatus <> S.ActiveStatus
				THEN UPDATE 
				SET T.ActiveStatus = S.ActiveStatus ,
				T.Updated_By = S.Updated_By ,
				T.Updated_Datetime = getdate();
				;
				--WHEN NOT MATCHED BY SOURCE AND T.EmployeeName LIKE 'S%'
				--THEN DELETE 
				
				IF(@@ROWCOUNT > 0)
				BEGIN
				SET @RETURNVALUE='SUCCESS'				
				END
				ELSE
				BEGIN
				SET @RETURNVALUE='OK'
				END

				COMMIT TRAN

			END TRY
			BEGIN CATCH

			SET @RETURNVALUE='ERROR ' + ERROR_MESSAGE() + ' ' + ERROR_PROCEDURE() 
			+ ' '  + ERROR_LINE() 

			ROLLBACK TRAN
			END CATCH

		 END
