			LineCode=@LineCode
			 AND ProfitCenterCode=@ProfitCentercode 
			GROUP BY ProfitCenterCode, Barcode,TagName,LineCode,MachineCode,PartNo,Value,Timestamp,Result
			
			 end

			INSERT INTO #Assy_View_ParamData_TB_FAIL(ProfitCenterCode, Barcode,TagName,LineCode,MachineCode
			,PartNo,Value,Seq_No,CustomerOperationNo,TagSeqNo,MinValue,MaxValue,UOM) 
			SELECT DISTINCT ProfitCenterCode, Barcode,'PermanentSerialNo',LineCode,'General',PartNo,Value,'15-3','15',3,'','','' 
			FROM #ASSY_PARAM_DATA_TEMP_(nolock) WHERE --Datecode=@DateCode AND 
			LineCode=@LineCode AND ProfitCenterCode=@ProfitCentercode 
			AND TagName='MCFV Barcode' 
			GROUP BY ProfitCenterCode, Barcode,TagName,LineCode,MachineCode,PartNo,Value,Timestamp,Result
			
			if(@@rowcount = 0)
			 begin

			 INSERT INTO #Assy_View_ParamData_TB_FAIL(ProfitCenterCode, Barcode,TagName,LineCode,MachineCode
			,PartNo,Value,Seq_No,CustomerOperationNo,TagSeqNo,MinValue,MaxValue,UOM) 
			SELECT DISTINCT ProfitCenterCode, Barcode,'PermanentSerialNo',LineCode,'General',PartNo,'-','15-3','15',3,'','','' 
			FROM #ASSY_PARAM_DATA_TEMP_(nolock) WHERE --Datecode=@DateCode AND 
			LineCode=@LineCode AND ProfitCenterCode=@ProfitCentercode 
			GROUP BY ProfitCenterCode, Barcode,TagName,LineCode,MachineCode,PartNo,Value,Timestamp,Result
			
			 end
			
			INSERT INTO #Assy_View_ParamData_TB_FAIL(ProfitCenterCode, Barcode,TagName,LineCode,MachineCode
			,PartNo,Value,Seq_No,CustomerOperationNo,TagSeqNo,MinValue,MaxValue,UOM) 
			SELECT DISTINCT ProfitCenterCode, Barcode,'DateCode',LineCode,'General',PartNo,Value,'15-4','15',4 ,'','',''
			FROM #ASSY_PARAM_DATA_TEMP_(nolock) WHERE --Datecode=@DateCode AND 
			LineCode=@LineCode 
			AND ProfitCenterCode=@ProfitCentercode AND TagName='DATE_CODE_COUPLING' 
			GROUP BY ProfitCenterCode, Barcode,TagName,LineCode,MachineCode,PartNo,Value,Timestamp,Result

			if(@@rowcount = 0)
			 begin

			 INSERT INTO #Assy_View_ParamData_TB_FAIL(ProfitCenterCode, Barcode,TagName,LineCode,MachineCode
			,PartNo,Value,Seq_No,CustomerOperationNo,TagSeqNo,MinValue,MaxValue,UOM) 
			SELECT DISTINCT ProfitCenterCode, Barcode,'DateCode',LineCode,'General',PartNo,'-','15-4','15',4 ,'','',''
			FROM #ASSY_PARAM_DATA_TEMP_(nolock) WHERE --Datecode=@DateCode AND 
			LineCode=@LineCode 
			AND ProfitCenterCode=@ProfitCentercode 
			GROUP BY ProfitCenterCode, Barcode,TagName,LineCode,MachineCode,PartNo,Value,Timestamp,Result


			end
			
			
			DECLARE @cols_FAIL NVARCHAR(MAX);
			DECLARE @Qry_FAIL NVARCHAR(MAX);
				
				 
				CREATE TABLE #Barcodes_FAIL
				(
				  Barcode varchar(100)
				)

				
				INSERT INTO #BARCODES_FAIL
				SELECT DISTINCT BARCODE FROM #Assy_View_ParamData_TB_FAIL WHERE VALUE='FAIL'
			
				
				
				
				

				SELECT @cols_FAIL = STUFF((SELECT ',' +  QUOTENAME(BARCODE) FROM #Barcodes_FAIL
															FOR XML PATH(''), TYPE
															).value('.', 'NVARCHAR(MAX)') 
														,1,1,'')
														
			
			SET @Qry_FAIL=' SELECT tb1.* INTO #ReportTable_FAIL FROM  (
										SELECT CustomerOperationNo As OperationNo
												,Barcode
												,MachineCode
												,Seq_No
												,TagName
												,MinValue As [Min Value]
												,MaxValue As [Max Value]
												,UOM As [UOM]
												,ISNULL(Value,0) AS value
												,TagSeqNo
										FROM #Assy_View_ParamData_TB_FAIL 
										WHERE ISNULL(VALUE,'''')<>''''
										) tb
												PIVOT (MAX(VALUE) FOR Barcode  IN (' + @cols_FAIL + ')) TB1
									INNER JOIN #RoutingConfigLineWise_FAIL RCFL ON tb1.MachineCode=RCFL.MachineCode
										ORDER BY RCFL.OperationSeqNo ASC		

					update q
					set q.OperationNo = a.CustomerOperationNo
					from #ReportTable_FAIL q
					inner join RoutingConfigLineWise a
					on q.MachineCode = a.MachineCode

					update q
					set q.MachineCode = a.MachineName
					from #ReportTable_FAIL q
					inner join MachineMst a
					on q.MachineCode = a.MachineCode

					
					SELECT q.* into	 ReportTable_TMP_FAIL				
					FROM #ReportTable_FAIL q
					inner join #MachineMst_FAIL a
					on q.MachineCode =a.MachineName
					INNER JOIN #RoutingConfigLineWise_FAIL RCFL ON a.MachineCode=RCFL.MachineCode
					ORDER BY RCFL.OperationSeqNo  ASC

					
					'
				
					EXEC sp_sqlexec @Qry_FAIL
					--print @Qry_FAIL

					-- Modified By Sachin 20170131
					select name, column_id into #ReportTable_ColumnName_FAIL  from sys.columns where object_id =
					object_id('ReportTable_TMP_FAIL') and name <> 'TagSeqNo'

					--select * from #ReportTable_ColumnName
					
					SELECT @cols_FAIL = STUFF((SELECT ',' + 'ISNULL(q.' + QUOTENAME(name)+','''')' + ' AS ' +QUOTENAME(name) FROM #ReportTable_ColumnName_FAIL
										order by column_id asc
															FOR XML PATH(''), TYPE
															).value('.', 'NVARCHAR(MAX)') 
														,1,1,'')
										
					if(isnull(@cols_FAIL,'') <> '')
					begin
					
					update ReportTable_TMP_FAIL 
					set seq_no = convert(varchar,operationno) + '-' + seq_no
					where seq_no in ('R' , 'T')

					set @Qry_FAIL=' select '+ @cols_FAIL +' from ReportTable_TMP_FAIL q
					inner join #MachineMst_FAIL a
					on q.MachineCode =a.MachineName
					INNER JOIN #RoutingConfigLineWise_FAIL RCFL ON a.MachineCode=RCFL.MachineCode
					ORDER BY RCFL.OperationSeqNo , TagSeqNo  ASC '

					--print @Qry_FAIL
					exec sp_sqlexec @Qry_FAIL
					drop table ReportTable_TMP_FAIL
					end
					--

		END
	END 
END
								
								


GO
/****** Object:  StoredProcedure [dbo].[PROC_lOGIN_USER]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

Create PROC [dbo].[PROC_lOGIN_USER]
@USERNAME VARCHAR(20)='',
@USER_ID int='',
@PASSWORD VARCHAR(20)='',
@P_INPUT_TYPE VARCHAR(100)='',

@OLDPASS VARCHAR(100)='',-- Added by AK on 10-july-2020 
@NEWPASS VARCHAR(100)='',-- Added by AK on 10-july-2020 

@ReturnValue VARCHAR (2000)=NULL OUT,
@ReturnInt INT=NULL OUT
AS
	BEGIN
		IF(@P_INPUT_TYPE = 'login')
		BEGIN
			IF EXISTS(SELECT top 1 1 FROM USER_DETAILS(nolock) WHERE  [USER_NAME] = @USERNAME AND UPASSWORD = @PASSWORD and sts=1)
			BEGIN			
				SELECT top 1 EmpID [USER_ID], [USER_NAME]FROM USER_DETAILS(nolock) WHERE  [USER_NAME] = @USERNAME AND UPASSWORD = @PASSWORD
				SET @ReturnInt = 1
				SET @ReturnValue='DATA SELECTED'
			END
		END

		-- Added by AK on 10-july-2020 
		IF(@P_INPUT_TYPE = 'ChangePass')
		BEGIN
			IF EXISTS(SELECT top 1 1 FROM USER_DETAILS(nolock) WHERE  [USER_NAME] = @USERNAME AND UPASSWORD = @OLDPASS and sts=1)
			BEGIN			
				Update USER_DETAILS set UPASSWORD=@NEWPASS WHERE [USER_NAME] = @USERNAME AND UPASSWORD = @OLDPASS
				SET @ReturnInt = 1
				SET @ReturnValue='Password Has Been Updated Successfully'
			END

			Else
			Begin
			SET @ReturnInt = 2
			SET @ReturnValue='Old Password Is Not Correct'
			END
		END
		-- Added by AK on 10-july-2020 
		
	end
GO
/****** Object:  StoredProcedure [dbo].[PROC_Maintenance]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*----------------------------------------------------------------------
CREATED BY		: SACHIN KUMAR
DATE			: 19 June 2020
REMARKS			:   
REVISION HISTORY: 

TEST SCRIPT		: 
exec PROC_Maintenance @P_Mode='LOG_DAYWISE_TBL_SIZE_REPORT'
exec PROC_Maintenance @P_Mode='LOG_DB_FILES'
exec PROC_Maintenance @P_Mode='GET_HARD_DISK_SPACE'
exec PROC_Maintenance @P_Mode='Get_Win_Event_Today'
exec PROC_Maintenance @P_Mode='Get_Event_Log',@P_FromDate='06/17/2020 00:00:00',@P_ToDate='06/17/2020 14:00:00',@P_MaxEvent=1000,@P_EventType='Error',
@P_LogName='Application'
-----------------------------------------------------------------*/
create procedure [dbo].[PROC_Maintenance] 
(
	@P_Mode			varchar(100)='',
	@P_ErrorType	varchar(100)='',
	@P_AppName		varchar(100)='',
	@P_ClassName	varchar(100)='',
	@P_MethodName	varchar(100)='',
	@P_ConString	varchar(200)='',
	@P_ErrorMsg	    varchar(max)='',	
	@P_MethodParam  varchar(2000) ='',
	@P_FromDate  varchar(30)='',
	@P_ToDate  varchar(30)='',
	@P_TableName	varchar(100)='',
	@P_MaxEvent int = 0,
	@P_EventType varchar(100)='',
	@P_LogName varchar(100)='',
	@P_Index varchar(100)='',
	@ReturnValue  varchar(max)='' out,
	@ReturnInt int = 0 out
)
as
begin
	
	declare @sql varchar(400)
	declare @EventTxt varchar(max)
	CREATE TABLE #output
	(line varchar(max))

			
	if(@P_Mode='SAVESQLEXCEPTIONLOG')		
	begin
			insert into MNT_LOG_ERROS(ErrorType,AppName,ClassName,MethodName,ConString,ErrorMsg,EntStamp,MethodParam)
			select @P_ErrorType,@P_AppName,@P_ClassName,@P_MethodName,@P_ConString,@P_ErrorMsg,getdate(),@P_MethodParam
	end			   
	if(@P_Mode='SHOWSQLEXCEPTIONLOG')		
	begin
			select ErrorId,ErrorType,AppName,ClassName,MethodName,MethodParam,ConString,ErrorMsg,EntStamp 
			from MNT_LOG_ERROS(nolock) where convert(date,EntStamp) between convert(date,@P_FromDate) and convert(date,@P_ToDate) 
			order by EntStamp desc
	end			
	if(@P_Mode='LOG_DAYWISE_TBL_SIZE_REPORT')
	begin			
			SELECT
			t.Name AS TableName,
			p.rows AS RowCounts,
			CAST(ROUND((SUM(a.total_pages) / 128.00), 2) AS NUMERIC(36, 2)) AS Total_MB,
			GETDATE() as LogDT
			into #TEMP_tables_dt
			FROM sys.tables t
			INNER JOIN sys.indexes i ON t.OBJECT_ID = i.object_id
			INNER JOIN sys.partitions p ON i.object_id = p.OBJECT_ID AND i.index_id = p.index_id
			INNER JOIN sys.allocation_units a ON p.partition_id = a.container_id
			INNER JOIN sys.schemas s ON t.schema_id = s.schema_id
			GROUP BY t.Name, s.Name, p.Rows
			having p.Rows > 1000
			ORDER BY p.rows desc		

			insert into MNT_LOG_DAYWISE_TBL_SIZE_REPORT
			select a.TableName,a.RowCounts,a.Total_MB,a.LogDT from #TEMP_tables_dt a 
			left join MNT_LOG_DAYWISE_TBL_SIZE_REPORT(nolock)
			b on a.TableName=b.TableName and a.RowCounts=b.RowCounts
			where b.RowCounts is null

	end   
	if(@P_Mode='SHOW_DAYWISE_TBL_SIZE_REPORT')
	begin
			if(@P_TableName='ALL')
			begin
					select LogId,TableName,RowCounts,Total_MB,LogDT 
					from MNT_LOG_DAYWISE_TBL_SIZE_REPORT(nolock)
					where convert(date,LogDT) between convert(date,@P_FromDate) and convert(date,@P_ToDate) 					
					order by LogDT desc
			end
			else
			begin
					select LogId,TableName,RowCounts,Total_MB,LogDT 
					from MNT_LOG_DAYWISE_TBL_SIZE_REPORT(nolock)
					where convert(date,LogDT) between convert(date,@P_FromDate) and convert(date,@P_ToDate) 
					and TableName=@P_TableName
					order by LogDT desc
			end
	end
	if(@P_Mode='LOG_DAYWISE_TBL_NAME')
	begin	
			declare @TableLog as table
			(
			  TableName varchar(100)
			)
			insert into @TableLog values('ALL')

			insert into @TableLog
			select distinct TableName  from MNT_LOG_DAYWISE_TBL_SIZE_REPORT(nolock)

			select TableName from @TableLog
	end
	if(@P_Mode='LOG_DB_FILES')
	begin
			
			select name,physical_name,(size),state_desc,is_media_read_only,is_read_only,
			is_sparse,getdate() as LogDateTime into #TEMP_database_files_lg from sys.database_files	
		
			insert into MNT_LOG_DB_FILES
			select  a.name,a.physical_name,a.size,a.state_desc,a.is_media_read_only,a.is_read_only,
			a.is_sparse,a.LogDateTime from #TEMP_database_files_lg a 
			left join MNT_LOG_DB_FILES(nolock)
			b on a.name=b.name and a.size=b.size
			where b.size is null
								
	end
	if(@P_Mode='SHW_LOG_DB_FILES')
	begin		
			select LogId,name,physical_name,(size),state_desc,is_media_read_only,is_read_only,
			is_sparse,LogDateTime from MNT_LOG_DB_FILES(nolock)
			where convert(date,LogDateTime) between convert(date,@P_FromDate) and convert(date,@P_ToDate) 					
			order by LogDateTime desc					
	end		
	if(@P_Mode='GET_HARD_DISK_SPACE')
	begin
			
		    exec PROC_Enable_xp_cmdshell
			exec PROC_MNT_GET_HARD_DISK_SPACE_USING_xp_cmdshell;
								
	end	
	if(@P_Mode='SHW_HARD_DISK_SPACE')
	begin
			
		   select LogId,driveName,capacity,freespace,LogDate from MNT_LOG_HARD_SIZE(nolock)
		   where convert(date,LogDate) between convert(date,@P_FromDate) and convert(date,@P_ToDate) 	
		   order by LogDate desc
								
	end	
	if(@P_Mode='Shrink_LogFile')
	begin			
		  exec Assy_Proc_Shrink_LogFile								
	end
	if(@P_Mode='Get_Win_Event_Today')
	begin			
			exec PROC_Enable_xp_cmdshell;
						
			set @sql = 'powershell.exe -c "Get-WinEvent @{logname=''application'',''system'';starttime=[datetime]::today;level=2 } ' 
			set @sql = @sql + '| select logname, id, message -Unique ';
			set @sql = @sql + '| foreach{$_.logname+''|''+$_.id+''|''+$_.message.subString(0,100)+''*''}"';

			PRINT @sql

			insert #output
			EXEC xp_cmdshell @sql

			--select top 10 Line from #output

			Select @EventTxt = COALESCE(@EventTxt + '' + isnull(Line,''),isnull(Line,'')) 
			From #output;
		
			insert into MNT_WIN_EVENT_LOG(logname,id,[message],LogDate)
			select col1,coL2,col3,GETDATE() from dbo.[FN_GRID_SPLIT_STRING](@EventTxt,'|','*')   
			
			delete from MNT_WIN_EVENT_LOG where logname is null or id is null or [message] is null

	end
	if(@P_Mode='Get_Win_Event_TimeBase')
	begin			
			exec PROC_Enable_xp_cmdshell;


			
			set @sql = 'powershell.exe -c "Get-WinEvent @{logname=''application'',''system'';starttime='+''''+@P_FromDate+''''+';endtime='+''''+@P_ToDate+''''+';level=2 } -MaxEvents 5000 ' 
			set @sql = @sql + '| select-object { ''''+$_.timecreated+''|'',$_.logname+''%'',$_.id+''@'',$_.message+''%''} "';
			
			PRINT @sql

			insert #output
			EXEC xp_cmdshell @sql

			 select * into TEMP_OUT_2 
			 from #output where line is not null
			 select CHARINDEX(' ',line)  from #output where line is not null

			select rtrim(ltrim(SUBSTRING(line,1,CHARINDEX('|',line) -1))) as [DateTime]
			,rtrim(ltrim(SUBSTRING(line,CHARINDEX('|',line)+1,
			(CHARINDEX('%',line) -1)-CHARINDEX('|',line)))) as [Type],
			rtrim(ltrim(SUBSTRING(line,CHARINDEX('%',line)+1,
			(CHARINDEX('@',line) -1)-CHARINDEX('%',line)))) as [Id],
			rtrim(ltrim(SUBSTRING(line,CHARINDEX('...',line)+1,
			(CHARINDEX('*',line) -1)-CHARINDEX('...',line)))) as [Msg]
			from #output
	end
	if(@P_Mode='Get_Event_Log')
	begin	
			exec PROC_Enable_xp_cmdshell;

			--set @sql = 'powershell.exe -c "Get-EventLog -LogName System -EntryType Error -Newest 5 -After ''06/17/2020'' -Before ''06/21/2020'' ' 
			--set @sql = @sql + '| Select-Object -Property Time,Index,UserName, Source, EventID, InstanceId, Message"';
			set @sql = 'powershell.exe -c "Get-EventLog -LogName '+@P_LogName+' -EntryType '+@P_EventType+' -Newest '+convert(varchar,@P_MaxEvent)+' -After '+ ''''+ @P_FromDate+''''+' -Before '+ ''''+@P_ToDate+'''' +' '
			set @sql = @sql + '| Select-Object { '''' + $_.Index+''|'' , $_.Timegenerated + ''@'', $_.Message }"';
			
			PRINT @sql

			insert #output
			EXEC xp_cmdshell @sql

			 --select * into TEMP_OUT_2 
			 --from #output where line is not null
			 --select CHARINDEX(' ',line)  from #output where line is not null

			select rtrim(ltrim(SUBSTRING(line,1,CHARINDEX('|',line) -1))) as [Index]
			,rtrim(ltrim(SUBSTRING(line,CHARINDEX('|',line)+1,
			(CHARINDEX('@',line) -1)-CHARINDEX('|',line)))) as [DateTime],
			rtrim(ltrim(SUBSTRING(line,CHARINDEX('@',line)+1,
			(CHARINDEX('.',line) -1)-CHARINDEX('@',line)))) + '...' as [Msg]
			from #output where line is not null and line not like '%$_.%' and line not like '%----------------%'
	end
	if(@P_Mode='Get_Event_Log_Using_Index')
	begin	
			exec PROC_Enable_xp_cmdshell;

			
			--set @sql = 'powershell.exe -c "Get-EventLog -LogName System -EntryType Error -Newest 5 -After ''06/17/2020'' -Before ''06/21/2020'' ' 
			--set @sql = @sql + '| Select-Object -Property Time,Index,UserName, Source, EventID, InstanceId, Message"';
			set @sql = 'powershell.exe -c "Get-EventLog -LogName '+@P_LogName+' -EntryType '+@P_EventType+' -Index '+@P_Index+' '
			set @sql = @sql + '| Select-Object -Property Timegenerated,Index,UserName, Source, EventID, InstanceId, Message"';
			
			PRINT @sql

			insert #output
			EXEC xp_cmdshell @sql

			 --select * into TEMP_OUT_2 
			 --from #output where line is not null
			 --select CHARINDEX(' ',line)  from #output where line is not null
			 --select * into TEMP_A from #output where line is not null
			select @ReturnValue = COALESCE(ISNULL(@ReturnValue,''),'','') + char(13) + rtrim(ltrim(line)) from TEMP_A
			
	end


end				   	 
				   	 
GO
/****** Object:  StoredProcedure [dbo].[PROC_MNT_GET_HARD_DISK_SPACE_USING_xp_cmdshell]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*----------------------------------------------------------------------
CREATED BY		: SACHIN KUMAR
DATE			: 19 June 2020
REMARKS			:   
REVISION HISTORY: 

TEST SCRIPT		: 


-----------------------------------------------------------------*/
create procedure [dbo].[PROC_MNT_GET_HARD_DISK_SPACE_USING_xp_cmdshell]
as
begin

declare @svrName varchar(255)
declare @sql varchar(400)

set @sql = 'powershell.exe -c "Get-WmiObject  -Class Win32_Volume -Filter ''DriveType = 3'' | select name,capacity,freespace | foreach{$_.name+''|''+$_.capacity/1048576+''%''+$_.freespace/1048576+''*''}"'
--print @sql
--creating a temporary table
CREATE TABLE #output
(line varchar(255))
--inserting disk name, total space and free space value in to temporary table
insert #output
EXEC xp_cmdshell @sql
--script to retrieve the values in MB from PS Script output
--select rtrim(ltrim(SUBSTRING(line,1,CHARINDEX('|',line) -1))) as drivename
--   ,round(cast(rtrim(ltrim(SUBSTRING(line,CHARINDEX('|',line)+1,
--   (CHARINDEX('%',line) -1)-CHARINDEX('|',line)) )) as Float),0) as 'capacity(MB)'
--   ,round(cast(rtrim(ltrim(SUBSTRING(line,CHARINDEX('%',line)+1,
--   (CHARINDEX('*',line) -1)-CHARINDEX('%',line)) )) as Float),0) as 'freespace(MB)'
--from #output
--where line like '[A-Z][:]%'
--order by drivename
--script to retrieve the values in GB from PS Script output
select rtrim(ltrim(SUBSTRING(line,1,CHARINDEX('|',line) -1))) as drivename
   ,round(cast(rtrim(ltrim(SUBSTRING(line,CHARINDEX('|',line)+1,
   (CHARINDEX('%',line) -1)-CHARINDEX('|',line)) )) as Float)/1024,0) as 'capacity(GB)'
   ,round(cast(rtrim(ltrim(SUBSTRING(line,CHARINDEX('%',line)+1,
   (CHARINDEX('*',line) -1)-CHARINDEX('%',line)) )) as Float) /1024 ,0)as 'freespace(GB)',
   GETDATE() as LogDate into #TEMP_output
from #output
where line like '[A-Z][:]%'

insert into MNT_LOG_HARD_SIZE
select a.drivename,a.[capacity(GB)],a.[freespace(GB)],a.LogDate from #TEMP_output a left join MNT_LOG_HARD_SIZE(nolock) b
on a.drivename COLLATE DATABASE_DEFAULT = b.driveName COLLATE DATABASE_DEFAULT
and a.[capacity(GB)] =b.capacity  
where b.capacity is null

--script to drop the temporary table
drop table #output

end
GO
/****** Object:  StoredProcedure [dbo].[proc_rebuild_indexes]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[proc_rebuild_indexes]
AS
BEGIN

	DECLARE @CurrentDatabase NVARCHAR(200);
	SET @CurrentDatabase = DB_NAME();

-- Disable automatic statistics update to prevent it during the index rebuild

	DECLARE @SQL NVARCHAR(MAX);
	SET @SQL = 'ALTER DATABASE [' + @CurrentDatabase + '] SET AUTO_UPDATE_STATISTICS OFF;';

	EXEC sp_executesql @SQL;

-- Rebuild all indexes for all tables in the database

DECLARE @TableName NVARCHAR(255);
DECLARE TableCursor CURSOR FOR
SELECT '[' + TABLE_SCHEMA + '].[' + TABLE_NAME + ']' AS TableName
FROM INFORMATION_SCHEMA.TABLES
WHERE TABLE_TYPE = 'BASE TABLE';

OPEN TableCursor;
FETCH NEXT FROM TableCursor INTO @TableName;

WHILE @@FETCH_STATUS = 0
BEGIN
    PRINT 'Rebuilding indexes for ' + @TableName;
    BEGIN TRY

        SET @SQL=('ALTER INDEX ALL ON ' + @TableName + ' REBUILD;');
		--PRINT (@SQL)
		EXEC (@SQL)
    END TRY
    BEGIN CATCH
        PRINT 'Failed to rebuild indexes for ' + @TableName + '. Error: ' + ERROR_MESSAGE();
    END CATCH
    FETCH NEXT FROM TableCursor INTO @TableName;
END;

CLOSE TableCursor;
DEALLOCATE TableCursor;

-- Re-enable automatic statistics update

SET @SQL = 'ALTER DATABASE [' + @CurrentDatabase + '] SET AUTO_UPDATE_STATISTICS ON;';

EXEC sp_executesql @SQL;

END;
GO
