CREATE PROC [dbo].[PROC_SUPPORTCALL]
@USERNAME VARCHAR(20)='',
@PASSWORD VARCHAR(20)='',
@P_INPUT_TYPE VARCHAR(100)='',

 @programid VARCHAR(100)='',
 @testcaseid VARCHAR(100)='',
 @bugdescription VARCHAR(2000)='', 
 @severity VARCHAR(100)='', 
 @phaseintroduced VARCHAR(100)='', 
 @bugcategory VARCHAR(100)='', 
 @cause VARCHAR(100)='', 
 @causedescription VARCHAR(100)='', 
 @countofoccurrence int=0, 
 @recvdate datetime='', 
 @bugfoundon datetime='', 
 @developby VARCHAR(100)='', 
 @testedby  VARCHAR(100)='', 
 @status  VARCHAR(100)='', 
 @closuredate datetime='',
 @fromdate datetime='',
 @Todate datetime='', 
 @remarks  VARCHAR(100)='',
 @sts_cd int =0,
 @userid int=0,
 @LASTID VARCHAR(20)='',
 @timespent VARCHAR(20)='00:00', -- Added by AK on 09 july 2020

@ReturnValue VARCHAR (2000)=NULL OUT,
@ReturnInt INT=NULL OUT
AS
	BEGIN
		IF(@P_INPUT_TYPE = 'GET_UNITS')
		BEGIN
			IF EXISTS(SELECT TOP 1 1 FROM UnitMst)
			BEGIN
				SELECT SUBSTRING('0000',1,4-len(unitcode))+convert(varchar,unitcode)+' ['+name+']' UNITNAME ,unitcode FROM UnitMst  order by unitcode-- Modified by AK for fetching the correct warehouse code on front end earlier the wh code was coming with additon of 1 
				--SELECT '00'+convert(varchar,unitcode)+' ['+name+']' UNITNAME ,unitcode FROM UnitMst  order by unitcode
				SET @ReturnInt = 1
				SET @ReturnValue='DATA SELECTED'
			END
		END
		IF(@P_INPUT_TYPE = 'GET_Buglist')
		BEGIN
			IF EXISTS(SELECT TOP 1 1 FROM UnitMst)
			BEGIN			
				SELECT BugCategory+' : '+BugDescription as Bug, BugCategory  FROM bugmst  order by BugCategory
				SET @ReturnInt = 1
				SET @ReturnValue='DATA SELECTED'
			END
		END
		IF(@P_INPUT_TYPE = 'GET_LastID')
		BEGIN
			IF NOT EXISTS(SELECT TOP 1 1 FROM LastSupportID WHERE isnull(LASTID,'')='' )
			BEGIN 		
				select top 1 SUBSTRING('00000',1,5-len(LASTID+1))+convert(varchar,LASTID+1) LASTID from LastSupportID order by LASTID desc
				
				SET @ReturnInt = 1
				SET @ReturnValue='DATA SELECTED'
			END
			ELSE
			BEGIN
				IF EXISTS(SELECT TOP 1 1 FROM SupportCall)
				BEGIN 
					select top 1 @LASTID=(SUBSTRING('00000',1,5-len(id+1))+convert(varchar,id+1))  from SupportCall order by id DESC
					UPDATE LastSupportID
					SET LASTID =@LASTID
				end
			end
		END
		IF(@P_INPUT_TYPE = 'GetEmpName')
		BEGIN
			IF EXISTS(SELECT TOP 1 1 FROM USER_DETAILS)
			BEGIN			
				select [USER_NAME] [USER_NAME],EmpID  from USER_DETAILS where sts=1 order by [USER_NAME]
				SET @ReturnInt = 1
				SET @ReturnValue='DATA SELECTED'
			END
		END
		IF(@P_INPUT_TYPE = 'GetReport')
		BEGIN
			IF EXISTS(SELECT TOP 1 1 FROM SupportCall)
			BEGIN

				--Added by AK on 13 july 2020
				if(ISNULL(@status,'') <> '' and ISNULL(@userid,'') <>'')
				begin
					print 'From date ' +convert(varchar(10),@fromdate)
					print 'To date ' + convert(varchar(10),@Todate)
					select id,ProgramId,TestCaseId,BugDescription,severity
							,PhaseIntroduced,bugCategory,Cause,CauseDescription,CountOfOccurrence
							,RecvDate,BugFoundOn,DevelopBy,TestedBy,Status,ClosureDate,Remarks,Task_Time as ManHours
					from SupportCall where convert(varchar(10),ENT_STAMP,23) between convert(varchar(10),@fromdate,23) and convert(varchar(10),@Todate,23) and EmpID = @userid and Status=@status ORDER BY ENT_STAMP desc 
					SET @ReturnInt = 1
				SET @ReturnValue='DATA SELECTED 1'
				end	

				else if(ISNULL(@status,'') = '' and ISNULL(@userid,'') <>'')
				begin
					print 'From date ' +convert(varchar(10),@fromdate)
					print 'To date ' + convert(varchar(10),@Todate)
					select id,ProgramId,TestCaseId,BugDescription,severity
							,PhaseIntroduced,bugCategory,Cause,CauseDescription,CountOfOccurrence
							,RecvDate,BugFoundOn,DevelopBy,TestedBy,Status,ClosureDate,Remarks,Task_Time as ManHours
					from SupportCall where convert(varchar(10),ENT_STAMP,23) between convert(varchar(10),@fromdate,23) and convert(varchar(10),@Todate,23) and EmpID = @userid ORDER BY ENT_STAMP desc 
					SET @ReturnInt = 1
				SET @ReturnValue='DATA SELECTED 2'
				end	

				else if(ISNULL(@status,'') <> '' and ISNULL(@userid,'') ='')
				begin
					Print @status
					print 'From date ' +convert(varchar(10),@fromdate)
					print 'To date ' + convert(varchar(10),@Todate)
					select id,ProgramId,TestCaseId,BugDescription,severity
							,PhaseIntroduced,bugCategory,Cause,CauseDescription,CountOfOccurrence
							,RecvDate,BugFoundOn,DevelopBy,TestedBy,Status,ClosureDate,Remarks,Task_Time as ManHours
					from SupportCall where convert(varchar(10),ENT_STAMP,23) between convert(varchar(10),@fromdate,23) and convert(varchar(10),@Todate,23) and Status=@status ORDER BY ENT_STAMP desc 
					SET @ReturnInt = 1
				SET @ReturnValue='DATA SELECTED 3'
				end

				--Added by AK on 13 july 2020

				else if(ISNULL(@userid,'') <> '')
				begin
				   print '2'
					select id,ProgramId,TestCaseId,BugDescription,severity
							,PhaseIntroduced,bugCategory,Cause,CauseDescription,CountOfOccurrence
							,RecvDate,BugFoundOn,DevelopBy,TestedBy,Status,ClosureDate,Remarks,Task_Time as ManHours
					from SupportCall where convert(varchar(10),ENT_STAMP,23) between convert(varchar(10),@fromdate,23) and convert(varchar(10),@Todate,23) and EmpID = @userid ORDER BY ENT_STAMP desc
					SET @ReturnInt = 1
				SET @ReturnValue='DATA SELECTED 4'
				end

				else
				begin
					print 'From date ' +convert(varchar(10),@fromdate)
					print 'To date ' + convert(varchar(10),@Todate)
					select id,ProgramId,TestCaseId,BugDescription,severity
							,PhaseIntroduced,bugCategory,Cause,CauseDescription,CountOfOccurrence
							,RecvDate,BugFoundOn,DevelopBy,TestedBy,Status,ClosureDate,Remarks,Task_Time as ManHours
					from SupportCall where convert(varchar(10),ENT_STAMP,23) between convert(varchar(10),@fromdate,23) and convert(varchar(10),@Todate,23) ORDER BY ENT_STAMP desc --and EmpID = @userid
					SET @ReturnInt = 1
				SET @ReturnValue='DATA SELECTED 5'
				end		
			END
		END
		--
		IF(@P_INPUT_TYPE = 'Insert')
		BEGIN
			IF NOT EXISTS(SELECT TOP 1  1 FROM SupportCall WHERE TestCaseId = @TestCaseId)
			BEGIN
				print '1'					
				--INSERT INTO SupportCall (TestCaseId, BugDescription, severity, PhaseIntroduced, bugCategory, Cause, CauseDescription, CountOfOccurrence, RecvDate, 
				--BugFoundOn, DevelopBy, TestedBy, [Status], ClosureDate, Remarks, STS_CD, ENT_STAMP, ENT_BY, LAST_UPD_STAMP, LAST_UPD_BY,EmpID)
				--VALUES (@testcaseid, @bugdescription, @severity, @phaseintroduced, @bugcategory, @cause, @causedescription, @countofoccurrence, @recvdate,
				-- @bugfoundon, @developby, @testedby, @status, @closuredate, @remarks, @sts_cd, getdate(), @USERNAME, null, '',@userid)

				 INSERT INTO SupportCall (ProgramId,TestCaseId, BugDescription, severity, PhaseIntroduced, bugCategory
				 , Cause, CauseDescription, CountOfOccurrence, RecvDate , 
				BugFoundOn, DevelopBy, TestedBy, [Status], ClosureDate, Remarks
				, STS_CD, ENT_STAMP
				, ENT_BY, LAST_UPD_STAMP, LAST_UPD_BY,EmpID,Task_Time
				)
				VALUES (@programid,@testcaseid, @bugdescription, @severity, @phaseintroduced, @bugcategory
				, @cause, @causedescription, @countofoccurrence, @recvdate
				,
				 @bugfoundon, @developby, @testedby, @status, @closuredate, @remarks
				, @sts_cd, getdate()
				, @USERNAME, null, '',@userid,@timespent) --Added @timespent by AK on 09-july-2020
				SET @LASTID=scope_identity()

				print '2'
				print @LASTID	
				IF not(isnull(@LASTID,'')='')
				begin
					UPDATE LastSupportID
					SET  LASTID=@LASTID
				end
				SET @ReturnInt = 1
				SET @ReturnValue='Data Logged Successfully'
			END
			else
			begin
			SET @ReturnInt = 2
			SET @ReturnValue=' TESTCASEID ALREADY EXISTS'
			end
		END
		IF(@P_INPUT_TYPE = 'Update')
		BEGIN
			IF EXISTS(SELECT  TOP 1  1 FROM SupportCall WHERE TestCaseId = @TestCaseId)
			BEGIN
				print '1'	  
				
				IF not EXISTS(SELECT  TOP 1  1 FROM SupportCall WHERE empid = @userid and TestCaseId = @TestCaseId)
				BEGIN
				   SET @ReturnInt = 2
				   SET @ReturnValue='You Are Not Authorized For this Updation/EMP ID Mismatch' 
				   RETURN
				end
				
				 UPDATE SupportCall
					SET  BugDescription = @bugdescription
						, severity = @severity
						, PhaseIntroduced = @phaseintroduced
						, bugCategory = @bugcategory
						, Cause = @cause
						, CauseDescription = @causedescription
						, CountOfOccurrence = @countofoccurrence
						, RecvDate = @recvdate
						, BugFoundOn = @bugfoundon
						, DevelopBy = @developby
						, TestedBy = @testedby
						, Status = @status
						, ClosureDate = @closuredate
						, Remarks = @remarks
						, STS_CD = 0
						, LAST_UPD_STAMP = getdate()
						, LAST_UPD_BY = @userid
						, Task_Time = @timespent -- Added by AK on 09-july-2020
						, ProgramId = @programid
					WHERE testcaseid = @testcaseid

				SET @ReturnInt = 1
				SET @ReturnValue='UPDATE DONE'
			END
			else
			begin
			SET @ReturnInt = 2
			SET @ReturnValue=' TESTCASEID NOT EXISTS'
			end
		END
		
		IF(@P_INPUT_TYPE = 'GetReportCountGrpBy')
		BEGIN
			IF EXISTS(SELECT TOP 1 1 FROM SupportCall)
			BEGIN
			   set @fromdate= convert(varchar(10),@fromdate,23)
			   set @Todate=convert(varchar(10),@Todate,23)
				if(ISNULL(@userid,'') <> '')
				begin
				   print '2'

				    SELECT ENT_BY Name,COUNT(*) As [Count]
					from SupportCall where ISNULL(ENT_BY,'')<>'' and convert(varchar(10),ENT_STAMP,23) between @fromdate and @Todate and EmpID=@userid  GROUP BY ENT_BY 

					SELECT bugCategory As BugCategory ,COUNT(*) As [BugCount]
					from SupportCall where ISNULL(ENT_BY,'')<>'' and convert(varchar(10),ENT_STAMP,23) between @fromdate and @Todate and EmpID=@userid GROUP BY bugCategory

					SET @ReturnInt = 1
				SET @ReturnValue='DATA SELECTED'
				end
				else
				begin
					print 'From date ' +convert(varchar(10),@fromdate)
					print 'To date ' + convert(varchar(10),@Todate)

					SELECT ENT_BY Name,COUNT(*) As [Count]
					from SupportCall where ISNULL(ENT_BY,'')<>'' and  convert(varchar(10),ENT_STAMP,23) between @fromdate and @Todate  GROUP BY ENT_BY  --and EmpID = @userid

					SELECT bugCategory As BugCategory ,COUNT(*) As [BugCount]
					from SupportCall where ISNULL(ENT_BY,'')<>'' and convert(varchar(10),ENT_STAMP,23) between @fromdate and @Todate GROUP BY bugCategory

					SET @ReturnInt = 1
				SET @ReturnValue='DATA SELECTED'
				end			
			END
		END

		IF(@P_INPUT_TYPE = 'GetEmpOpenCount')
		BEGIN

			select Count(*) as [Open Bug Count] from supportcall where status ='Open' and EmpID=@userid 
			SET @ReturnInt = 1
			SET @ReturnValue='DATA SELECTED'

		END

		IF(@P_INPUT_TYPE = 'GetProgramID')
		BEGIN

			select Program_ID,id from ProgramMst where STS_CD=1
			SET @ReturnInt = 1
			SET @ReturnValue='DATA SELECTED'

		END

	END
GO
/****** Object:  StoredProcedure [dbo].[PROC_VALIDATE_N_SAVE_SCANNED_BARCODE]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*************************************************************************************** 
PROCEDURE:		PROC_VALIDATE_N_SAVE_SCANNED_BARCODE
AUTHOR:			SACHIN KUMAR
DATE WRITTEN :  Jan 15, 2018
PURPOSE:		Validate and Save Scanned Barcode

TEST SCRIPT  

 exec [PROC_VALIDATE_N_SAVE_SCANNED_BARCODE] @P_Mode='VS',@P_PROFITCENTER_CODE='0018',
 @P_LINE_CODE='S01', @P_MACHINE_CODE='MC5A',@P_OPERATION_CODE='OC5A',@P_BARCODE='0000203AeS01'

 exec [PROC_VALIDATE_N_SAVE_SCANNED_BARCODE] @P_Mode='RELOAD_CPD_DATA',@P_PROFITCENTER_CODE='0068',
 @P_LINE_CODE='F02',@P_PART_NO='29670304'
 
****************************************************************************************/
CREATE procedure [dbo].[PROC_VALIDATE_N_SAVE_SCANNED_BARCODE]
(
   @P_Mode varchar(50)='',
   @P_PROFITCENTER_CODE varchar(10)='',
   @P_LINE_CODE varchar(10)='',     
   @P_MACHINE_CODE varchar(10)='',
   @P_OPERATION_CODE varchar(10)='',
   @P_PART_NO varchar(20)='',
   @P_BARCODE varchar(100)='',
   @P_TableName varchar(100)='',
   @P_Column VARCHAR (100)=NULL OUT,
   @ReturnValue VARCHAR (2000)=NULL OUT,
   @ReturnInt INT=NULL OUT
)
AS
BEGIN

		Declare @DynamicQuery varchar(max)
		Declare @TableName varchar(100)
		Declare @Operation_Code varchar(10)
		Declare @Machine_Code varchar(10)
		Declare @P_COLUMN_TABLE1 varchar(1000)
		Declare @P_TABLE1 varchar(100)
		declare @bom_qty int 
		declare @child_Part varchar(100)
		declare @Column varchar(100)
		declare @TS_Barcode varchar(100) = ''
		declare @Column_Seq int = 0
		declare @totalSeq int
		declare @ScannedCount int
		declare @P_RETURNVALUE nvarchar(2000)
		declare @P_RETURNInt int
		declare @Error_Msg varchar(1000)
		Declare @RequesTD varchar(2000)
		Declare @generatedBarcode varchar(100)
		declare @zpl varchar(2000)
		declare @childPartBarcode varchar(100) = ''
		declare @TSBarcode varchar(100) = ''
		declare @childPart varchar(100) = ''
		declare @OperationWiseTotalScan smallint
		declare @OperationWiseCurrentScanned smallint

		Declare @findCount table(
			[count] int
		)

		Declare @findBarcode table(
			[Barcode] varchar(100)
		)
		Declare @OperationCode table(
			SeqNo int,
			[OperationCode] varchar(10),
			[MachineCode] varchar(10)
		)
		DECLARE @CHILDPART_1 VARCHAR(2000)
		DECLARE @SQL_QUERY nvarchar(2000)
		Declare @ChildPartsList nvarchar(2400)
		Declare @ChildPartsBomQty nvarchar(2400)
		Declare @ChildPartsTraceFlag nvarchar(2400)
		Declare @TSBarcodeSeq smallint

		Declare @ChildPartDetails table
		(
		  SR_NO int,
		  ChildPart nvarchar(100),
		  bom_qty int,
		  trace_flag nvarchar(2)
		)

		Declare @TEMP_ChildPart table
		(
		  S_NO int,
		  ChildPart nvarchar(100)		
		)
		Declare @TEMP_BomQty table
		(
		  S_NO int,
		  bom_qty int
		)
		
		Declare @TEMP_TraceFlag table
		(
		  S_NO int,
		  trace_flag nvarchar(2)
		)
		

		Declare @ChildPartScanningSeqColumnWise table
		(
		  SR_NO int identity(1,1),
		  ChildPart nvarchar(100),
		  bom_qty int , 
		  FoundInColumn nvarchar(100),
		  IsScanned bit
		)
		
		Declare @Generate_Barcode_Result table
		(
		   Result varchar(10),
		   Msg varchar(1000),
		   PRN varchar(2000)		
		)
		declare @ScanningMode varchar(50) = 'BS'

		
		Declare  @RoutingConfigPartWise table 
		(
			[ProfitCenterCode] [nvarchar](4) NOT NULL,
			[OperationCode] [varchar](10) NOT NULL,
			[PartNo] [varchar](60) NOT NULL,
			[MachineCode] [varchar](10) NOT NULL,
			[OperationRequired] [bit] NULL,
			[Traceability] [bit] NULL,
			[Recipe] [bit] NULL,
			[LabelPrinting] [bit] NULL,
			[Torque] [bit] NULL,
			[Engraving] [bit] NULL,
			[POKA_YOKE_ALLOWED] [bit] NULL,
			[OperationSeqNo] [int] NULL,
			[ent_stamp] [datetime] NULL,
			[last_upd_stamp] [datetime] NULL,
			[ent_by] [varchar](20) NULL,
			[last_upd_by] [varchar](20) NULL,
			[Part_FixtureGroupType] [varchar](50) NULL,
			[IsCPValidationRequired] [bit] NULL,
			[ChildPartsList] [nvarchar](1200) NULL,
			[CPBomQty] [nvarchar](1200) NULL,
			[CPTraceFlag] [nvarchar](1200) NULL,
			[TSBarcodeSeq] [smallint] NULL
 
		) 

		




begin try

IF(@P_MODE='VS')
BEGIN
		-- 1. Check Scanned Barcode is Child Part Barcode or TS Barcode.
		-- if it contain LineCode then it is TS Barcode else CP.


		select @TableName=TblHoldScannedValues from machineDtl(nolock) where ProfitCenterCode=@P_PROFITCENTER_CODE and
				LineCode=@P_LINE_CODE and MachineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE
		
		if(@P_BARCODE='RESET')
		begin
				set @DynamicQuery = 'delete from '+ @TableName 
				if(@ScanningMode='DB')
				begin
				exec(@DynamicQuery)
				end
				set @RETURNVALUE = 'Reset !! Done Kindly Scan Again.'
				set @RETURNINT = 100
				return
		end

		if( CHARINDEX(@P_LINE_CODE,@P_BARCODE) > 0 AND @ScanningMode='DB') -- TS Barcode
		begin

				
				delete from @findCount
				set @DynamicQuery = 'select count(barcode) as count from '+ @TableName + 
				' where barcode=' + ''''+@P_BARCODE+''''
				--print @DynamicQuery
				insert into @findCount
				exec(@DynamicQuery)

				if((select [count] from @findCount) > 0)
				begin
						-- Check for any child Part Barcode Scanning Required 
						-- if not then provide [isActive] = 1 else [isActive]=0 wait for child Part Scanning
							select @totalSeq=max(SeqNumber) from Assy_Temp_ChildPartColumnMapping(nolock) where ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
							machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO

							select @ScannedCount=sum(IsScanned) from Assy_Temp_ChildPartColumnMapping(nolock) where ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
							machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO

							if(isnull(@totalSeq,0)=isnull(@ScannedCount,0))
							begin
									 set  @DynamicQuery =
									'Update ' + @TableName + ' set isActive=1 '+
									' where Barcode=' +''''+@P_BARCODE+''''

									--print @DynamicQuery
									exec(@DynamicQuery)
									insert into TD_Barcode_Info(OC_CODE,Barcode,Part_No,ent_dt) values (@P_OPERATION_CODE,'','',GETDATE())
									set @RETURNVALUE = 'Barcode Scanned, Waiting for Cycle Start'
									set @RETURNINT = 100	
							end
							else
							begin
						
									select top 1 @CHILDPART_1=childPart from Assy_Temp_ChildPartColumnMapping where 
									ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
									machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO and isScanned=0 
									order by seqNumber asc

									SET @RETURNVALUE ='Please Scan CP ('+isnull(@CHILDPART_1,'')+')'
									SET @RETURNINT =1	
									RETURN
							end
				end
				else
				begin
						set  @DynamicQuery =
						'insert into ' + @TableName + '([OC_CODE],[Barcode],[isActive],[ent_stamp]) '+
						'values('+''''+@P_OPERATION_CODE+''''+','+''''+@P_BARCODE+''''+','+'0,getdate())'

						--print @DynamicQuery
						exec(@DynamicQuery)		
						
						delete Assy_Temp_ChildPartColumnMapping where ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
						machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO
						 
						 exec [PROC_VALIDATE_N_SAVE_SCANNED_BARCODE] @P_Mode='FIND_NEXT_CP_TO_SCAN',@P_PROFITCENTER_CODE=@P_PROFITCENTER_CODE,
						 @P_LINE_CODE=@P_LINE_CODE, @P_MACHINE_CODE=@P_MACHINE_CODE,@P_OPERATION_CODE=@P_OPERATION_CODE,@P_BARCODE=@P_BARCODE,
						 @P_PART_NO=@P_PART_NO,@P_TableName=@TableName,@RETURNVALUE = @P_RETURNVALUE out,@RETURNInt=@P_RETURNInt out,
						 @P_Column=@Column out

						 if(@P_RETURNInt=100)
						 begin
								
									 set  @DynamicQuery =
									'Update ' + @TableName + ' set isActive=1 '+
									' where Barcode=' +''''+@P_BARCODE+''''

								--print @DynamicQuery
								exec(@DynamicQuery)
								insert into TD_Barcode_Info(OC_CODE,Barcode,Part_No,ent_dt) values (@P_OPERATION_CODE,'','',GETDATE())	
								set @RETURNVALUE = 'Barcode Scanned, Waiting for Cycle Start'
								set @RETURNINT = 100
								
						 end
						 else
						 begin									

									set @RETURNVALUE = @P_RETURNVALUE
									set @ReturnInt = @P_RETURNINT

						 end
										
				end

		end
		else  -- Child Part Barcode
		begin
						
						 if((select isnull(KeyValue,'N') from RoutingConfigDetails(nolock) where ProfitCenterCode=@P_PROFITCENTER_CODE and
							 LineCode=@P_LINE_CODE and MachineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and keyType='IsGenerateBarcodeCallRequired') = 'Y')
							begin
								
								 delete from @findBarcode
								 set @DynamicQuery = 'select barcode from '+ @TableName  
								 print @DynamicQuery
								 insert into @findBarcode
								 exec(@DynamicQuery)
								 --select * from @findBarcode
								  if not exists(select top 1 1 from @findBarcode)
								  begin
								  										
										exec ASSY_PROC_GENERATE_BARCODE @P_Mode=N'Barcode_Gen_2',@P_LINE_CODE=@P_LINE_CODE,
										@P_PROFITCENTER_CODE=@P_PROFITCENTER_CODE,@P_OPERATION_CODE='OCIG', 
										@RETURNVALUE=@P_RETURNVALUE out,@RETURNINT=@P_RETURNINT out
 
										 if(@P_RETURNINT=100)
										 begin												
												set @RETURNVALUE = @P_RETURNVALUE
												set @RETURNINT = 200
												return
										 end
										 
										 if(@P_RETURNINT=1)
										 begin												
												print 'to do barcode priting if required'
												-- 	@P_RETURNVALUE = barcode|zpl
												select top 1 @generatedBarcode=col1 , @zpl = isnull(col2,'') from fn_grid_split_string(@P_RETURNVALUE,'','|')
																								
												set  @DynamicQuery =
												'insert into ' + @TableName + '([OC_CODE],[Barcode],[isActive],[ent_stamp]) '+
												'values('+''''+'OCIG'+''''+','+''''+@generatedBarcode+''''+','+'0,getdate())'

												--print @DynamicQuery
												if(@ScanningMode='DB')
												begin
												exec(@DynamicQuery)											
												end
										 end
										 
										 delete Assy_Temp_ChildPartColumnMapping where ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
										 machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO
						 
										 exec [PROC_VALIDATE_N_SAVE_SCANNED_BARCODE] @P_Mode='FIND_NEXT_CP_TO_SCAN',@P_PROFITCENTER_CODE=@P_PROFITCENTER_CODE,
										 @P_LINE_CODE=@P_LINE_CODE, @P_MACHINE_CODE=@P_MACHINE_CODE,@P_OPERATION_CODE=@P_OPERATION_CODE,@P_BARCODE='',
										 @P_PART_NO=@P_PART_NO,@P_TableName=@TableName,@RETURNVALUE = @P_RETURNVALUE out,@RETURNInt=@P_RETURNInt out,
										 @P_Column=@Column out
									end
							end

						 delete from @findCount
						 set @DynamicQuery = 'select count(*) as count from '+ @TableName  				
						 --print @DynamicQuery
						 if(@ScanningMode='DB')
						 begin
							insert into @findCount
							exec(@DynamicQuery)
						 
						 
							 if((select [count] from @findCount) = 0)
							 begin
						
									set @RETURNVALUE = 'Kindly Scan TS Barcode First'
									set @RETURNINT = 200
									return
							end	
						end
						 

						 exec [PROC_VALIDATE_N_SAVE_SCANNED_BARCODE] @P_Mode='VALIDATE_CHILD_PART',@P_PROFITCENTER_CODE=@P_PROFITCENTER_CODE,
						 @P_LINE_CODE=@P_LINE_CODE, @P_MACHINE_CODE=@P_MACHINE_CODE,@P_OPERATION_CODE=@P_OPERATION_CODE,@P_BARCODE=@P_BARCODE,
						 @P_PART_NO=@P_PART_NO,@P_TableName=@TableName,@RETURNVALUE = @P_RETURNVALUE out,@RETURNInt=@P_RETURNInt out,
						 @P_Column=@Column out

						 print @P_RETURNVALUE
						 print @Column
						 if(@P_RETURNInt=100)
						 begin
									if(ISNULL(@Column,'') != '')
									begin
								 			set  @DynamicQuery =
											'Update ' + @TableName + ' set isActive=1 , '+ @Column + '=' + ''''+@P_BARCODE+'''' 
														
											--print @DynamicQuery 	
											if(@ScanningMode='DB')
											begin							
												exec(@DynamicQuery)
											end			
									end
								
								if(@ScanningMode='DB')
								begin
								insert into TD_Barcode_Info(OC_CODE,Barcode,Part_No,ent_dt) values (@P_OPERATION_CODE,'','',GETDATE())
								end

								set @RETURNVALUE = 'All Child Part Scanned, Waiting for Cycle Start'
								set @RETURNINT = 100

						 end
						 else
						 begin
									if(ISNULL(@Column,'') != '')
									begin

									set  @DynamicQuery =
									'Update ' + @TableName + ' set isActive=0 , '+ @Column + '=' + ''''+@P_BARCODE+'''' 
														
									--print @DynamicQuery 			
									if(@ScanningMode='DB')
									begin					
									exec(@DynamicQuery)		
									end
									end
								set @RETURNVALUE = @P_RETURNVALUE
								set @RETURNINT = @P_RETURNINT
						 end
						 		
		end

END


IF(@P_MODE='VALIDATE_CHILD_PART')
BEGIN
print 'START'
	if exists(select top 1 1 from Assy_Temp_ChildPartColumnMapping(nolock) where ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
	machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO)
	begin
				print 'START'
				print '-----1------'
				select top 1 @totalSeq=SeqNumber, @child_Part=ChildPart,@Column=[Column] from Assy_Temp_ChildPartColumnMapping(nolock) where 
				ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
				machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO and isScanned=0
				order by seqNumber asc		
				
				select @OperationWiseTotalScan = count(*) from Assy_Temp_ChildPartColumnMapping(nolock) where 
				ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
				machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE 
				print @OperationWiseTotalScan
				select @OperationWiseCurrentScanned = SUM(isScanned) from Assy_Temp_ChildPartColumnMapping(nolock) where 
				ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
				machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and isScanned=1
				print @OperationWiseCurrentScanned
				-- check if Same Barcode Scanned Again
				if exists(select top 1 1 from Assy_Temp_ChildPartColumnMapping(nolock) 
				where ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
				machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO 
				and ChildPartBarcode=@p_barcode)
				begin
						-- find next barcode to be scan if exists
						if exists(select top 1 1 from Assy_Temp_ChildPartColumnMapping(nolock) where 
						ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
						machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO and isScanned=0 
						order by seqNumber asc)
						begin

							select top 1 @CHILDPART_1=childPart , @totalSeq=seqNumber from Assy_Temp_ChildPartColumnMapping(nolock) where 
							ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
							machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO and isScanned=0 
							order by seqNumber asc

							SELECT 1 as 'STS_CD','Barcode Already Scanned , Kindly Scan Next Child Part ('+isnull(@CHILDPART_1,'')+')' + ' Seq No. ' 
							+ convert(varchar,ISNULL(@totalSeq,'')) as 'MSG',
							@p_barcode as 'TS_BARCODE'

							return
						end
				end

				if(@OperationWiseTotalScan=@OperationWiseCurrentScanned)
						begin	
								select top 1 @TS_Barcode=ChildPartBarcode from Assy_Temp_ChildPartColumnMapping(nolock) where 
								ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
								machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO 
								and [Column] = 'TS_BARCODE'

								if(@TS_Barcode <> @P_BARCODE)
								begin
									SELECT 1 as 'STS_CD','Kindly Provide Pass for TS Barcode (' + @TS_Barcode +')'  as 'MSG',
									@P_BARCODE as 'TS_BARCODE'
								end
								else
								begin
									SELECT 100 as 'STS_CD','Child Part Scanning Done Provide OK signal' as 'MSG',
									@TS_Barcode as 'TS_BARCODE'
								end

								return
						end

				/**********
					- Code Added By Sachin 20170711
					- Below is Used to Validation using Validation Matrix Table
				*/
						
				BEGIN

						if exists(select top 1 1 from Assy_Validation_Matrix(nolock) 
						where profitcenterCode=@P_PROFITCENTER_CODE and LineCode=@P_LINE_CODE
						and OperationCode=@P_OPERATION_CODE and isValidationReq=1 and STS_CD=0 and [Priority] > 0 )
						begin

							declare @validationCode int  = 0
							select * into #temp1 from Assy_Validation_Matrix(nolock) 
							where profitcenterCode=@P_PROFITCENTER_CODE and LineCode=@P_LINE_CODE
							and OperationCode=@P_OPERATION_CODE and isValidationReq=1 
							and STS_CD=0 and [Priority] > 0
																		
							declare @error_found bit = 0
							declare @V_RETURNINT int 
							declare @V_RETURNVALUE VARCHAR (2000)
									

						while(exists (select top 1 1 from #temp1) )
						begin 
								select top 1 @validationCode = ValidationCode from #temp1 order by [Priority]		
								IF(@Column='TS_Barcode' and @validationCode=9)
								BEGIN
									print 'Skip Validation 4 for TS Barcode'
								END
								ELSE
								BEGIN
								    print 'Do Validation ' + Convert(varchar,@validationCode) + ISNULL(@child_Part,'')

									EXEC ASSY_PROC_DO_VALIDATION @P_VALIDATIONCODE=@validationCode,@P_PROFITCENTERCODE=@P_PROFITCENTER_CODE,
									@P_LINECODE=@P_LINE_CODE,@P_OPERATION_CODE=@P_OPERATION_CODE,@P_PartNo=@child_Part, 
									@P_MachineCode=@P_MACHINE_CODE,@P_Barcode=@P_BARCODE, 
									@RETURNINT=@V_RETURNINT out,@RETURNVALUE=@V_RETURNVALUE out
																		
									if(ISNULL(@V_RETURNINT,0)<>0)
									begin									
											set @error_found = 1
											delete from #temp1			
									end
								END
								delete from #temp1 where ValidationCode=@validationCode
						 end
								
							if(@error_found=1)
							begin														
									SELECT @V_RETURNINT as 'STS_CD',@V_RETURNVALUE as 'MSG',@p_barcode as 'TS_BARCODE'	
									RETURN
							end
						END
				END	
								
				/**********
					- Code Ended By Sachin 20170711
				*/
				
				print 'sequence ' + convert(nvarchar,@totalSeq)

				update Assy_Temp_ChildPartColumnMapping
				set [ChildPartBarcode]=@P_BARCODE,IsScanned=1
				where ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
				machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO
				and seqNumber=@totalSeq			

				--Check All Child Part Scanning Complete for Not.
				
				select * into #TEMP_Assy_Temp_ChildPartColumnMapping from Assy_Temp_ChildPartColumnMapping(nolock) where ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
				machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO
				
				select @P_Column=[Column] from #TEMP_Assy_Temp_ChildPartColumnMapping(nolock) where ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
				machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO and  seqNumber=@totalSeq

				select @totalSeq=max(SeqNumber) from #TEMP_Assy_Temp_ChildPartColumnMapping(nolock) where ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
				machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO
				
				select @ScannedCount=sum(IsScanned) from #TEMP_Assy_Temp_ChildPartColumnMapping(nolock) where ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE 
				and	machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO
				
				

				if(@totalSeq=@ScannedCount)
				begin			
						
						select top 1 @TS_Barcode=ChildPartBarcode from Assy_Temp_ChildPartColumnMapping(nolock) where 
						ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
						machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO 
						and [Column] = 'TS_BARCODE'

						SELECT 100 as 'STS_CD','Child Part Scanning Done Provide OK signal' as 'MSG',
						@TS_Barcode as 'TS_BARCODE'

				end
				else
				begin
						
						select top 1 @CHILDPART_1=childPart , @totalSeq=seqNumber from Assy_Temp_ChildPartColumnMapping where 
						ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
						machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO and isScanned=0 
						order by seqNumber asc
						
						SELECT 1 as 'STS_CD',
						'Please Scan Next Child Part ('+isnull(@CHILDPART_1,'')+')' + ' Seq No. ' 
						+ convert(varchar,ISNULL(@totalSeq,'')) as 'MSG',
						@p_barcode as 'TS_BARCODE'						

				end

				 
	end
END

IF(@P_MODE='FIND_NEXT_CP_TO_SCAN')
BEGIN

	-- CHECK CHILD PART SCAN REQUIRED OR NOT.
	-- Get Child Parts Scanned Over Station
	select * into #TEMP_ROUTINGCONFIGPARTWISE from routingConfigPartWise(nolock) where partNo=@P_PART_NO and 
	machineCode=@P_MACHINE_CODE and operationCode=@P_OPERATION_CODE and isnull(IsCPValidationRequired,0)=1
	and ProfitCenterCode=@P_PROFITCENTER_CODE

	if exists(select top 1 1 from #TEMP_ROUTINGCONFIGPARTWISE)
	begin

	  	SELECT 
		@ChildPartsList=ChildPartsList,
		@ChildPartsBomQty=CPBomQty,
		@ChildPartsTraceFlag= CPTraceFlag, 
		@TSBarcodeSeq = TSBarcodeSeq
		FROM  #TEMP_ROUTINGCONFIGPARTWISE 
		

		print 1
		--insert into @ChildPartDetails(SR_NO,ChildPart)
		select ROW_NO as 'S_NO',col1 as 'ChildPart' into #TEMP_ChildPart from fn_grid_split_string(ltrim(rtrim(@ChildPartsList)),'',',')
		select ROW_NO as 'S_NO',col1 as 'BomQty' into #TEMP_BomQty from fn_grid_split_string(ltrim(rtrim(@ChildPartsBomQty)),'',',')
		select ROW_NO as 'S_NO',col1 as 'TraceFlag' into #TEMP_TraceFlag from fn_grid_split_string(ltrim(rtrim(@ChildPartsTraceFlag)),'',',')
		--select * from @ChildPartDetails
		insert into @ChildPartDetails(SR_NO,ChildPart,bom_qty,trace_flag)
		select cp.S_NO,cp.ChildPart,bq.BomQty,tf.TraceFlag from #TEMP_ChildPart cp inner join 
		#TEMP_BomQty bq on cp.S_NO=bq.S_NO inner join
		#TEMP_TraceFlag tf on tf.S_NO=cp.S_NO
		
		-- Delete Lot Trace Child Parts
		delete from @ChildPartDetails where trace_flag='L'			
		print 2
		-- if any part loaded exists check for sequence
		if exists (select top 1 1 from @ChildPartDetails)
		begin
				
				while exists(select top 1 1 from @ChildPartDetails)
				begin
						SELECT @CHILD_PART=CHILDPART,@BOM_QTY=BOM_QTY FROM @CHILDPARTDETAILS ORDER BY SR_NO DESC
						
						while(@BOM_QTY > 0)
						begin
								set @Column_Seq = @Column_Seq + 1
								set @Column = 'ChildPart_' + CONVERT(varchar,@Column_Seq)
								--select @Column
								set @BOM_QTY = @BOM_QTY - 1
								insert into @ChildPartScanningSeqColumnWise(ChildPart,bom_qty,FoundInColumn,IsScanned)
								values(@CHILD_PART,1,@Column,0)
						end

						delete from  @CHILDPARTDETAILS where CHILDPART=@CHILD_PART
				end
				
				insert into Assy_Temp_ChildPartColumnMapping(
				ProfitCenterCode,LineCode,MachineCode,OperationCode,PartNumber,[Table],[Column],ChildPart,bom_qty,[ChildPartBarcode],
				[SeqNumber],IsScanned,Sts_Cd,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP
				)
				select @P_PROFITCENTER_CODE,@P_LINE_CODE,@P_MACHINE_CODE,@P_OPERATION_CODE,@P_PART_NO,@P_TableName, 
				FoundInColumn,ChildPart,bom_qty,'',SR_NO,IsScanned,1,'ADMIN',GETDATE(),'ADMIN',GETDATE() from @ChildPartScanningSeqColumnWise

				
				select @totalSeq=max(SeqNumber) from Assy_Temp_ChildPartColumnMapping where ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
				machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO

				select @ScannedCount=sum(IsScanned) from Assy_Temp_ChildPartColumnMapping where ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
				machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO

				if(@totalSeq=@ScannedCount)
				begin
						SET @RETURNVALUE = 'Child Part Scanning Done Provide OK signal'
						SET @RETURNINT =100
						return
				end
				else
				begin	
						select top 1 @CHILDPART_1=childPart,@totalSeq=seqNumber from Assy_Temp_ChildPartColumnMapping where 
						ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
						machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO and isScanned=0 
						order by seqNumber asc

						SET @RETURNVALUE ='Barcode Scanned,Please Scan Child Part ('+isnull(@CHILDPART_1,'')+')' +  ' Seq No. ' + convert(varchar,ISNULL(@totalSeq,''))
						SET @RETURNINT =1	
						RETURN

				end

			end
		else
		begin
				SET @RETURNVALUE = 'Child Part Scanning Not Required for Station. All Loaded Parts were lot traceable.'
				SET @RETURNINT =100
		end
	end
	else
	begin
	-- No Child Part Required To Be Scanned 
	SET @RETURNVALUE = 'Child Part Scanning Not Required for Station.'
	SET @RETURNINT =100
	end											

END

IF(@P_MODE='LOAD_ALL_CPD')
BEGIN

	if NOT exists(select top 1 1 from Assy_Temp_ChildPartColumnMapping(nolock) where ISNULL(ChildPartBarcode,'')<>'' 
	and  ProfitCenterCode=@P_PROFITCENTER_CODE 
	and LineCode = @P_LINE_CODE )
	begin
	
	delete from Assy_Temp_ChildPartColumnMapping
	-- CHECK CHILD PART SCAN REQUIRED OR NOT.
	-- Get Child Parts Scanned Over Station
	insert into @RoutingConfigPartWise (
	ProfitCenterCode,OperationCode,PartNo,MachineCode,OperationRequired,Traceability,Recipe,LabelPrinting,
	Torque,Engraving,POKA_YOKE_ALLOWED,OperationSeqNo,ent_stamp,last_upd_stamp,ent_by,last_upd_by,
	Part_FixtureGroupType,IsCPValidationRequired,ChildPartsList,CPBomQty,CPTraceFlag,TSBarcodeSeq
	)
	select ProfitCenterCode,OperationCode,PartNo,MachineCode,OperationRequired,Traceability,Recipe,LabelPrinting,
	Torque,Engraving,POKA_YOKE_ALLOWED,OperationSeqNo,ent_stamp,last_upd_stamp,ent_by,last_upd_by,
	Part_FixtureGroupType,IsCPValidationRequired,ChildPartsList,CPBomQty,CPTraceFlag,TSBarcodeSeq
	from routingConfigPartWise(nolock) where partNo=@P_PART_NO and 
	isnull(IsCPValidationRequired,0)=1 and ProfitCenterCode=@P_PROFITCENTER_CODE

	insert into @OperationCode(SeqNo,OperationCode,MachineCode)
	select distinct OperationSeqNo,OperationCode,MachineCode from @RoutingConfigPartWise
	
	while exists (select top 1 1 from @OperationCode)
	begin
	select top 1  @Operation_Code = OperationCode, @Machine_Code=MachineCode from @OperationCode order by SeqNo
	
	if exists(select top 1 1 from @RoutingConfigPartWise where OperationCode=@Operation_Code)
	begin

	  	SELECT 
		@ChildPartsList=ChildPartsList,
		@ChildPartsBomQty=CPBomQty,
		@ChildPartsTraceFlag= CPTraceFlag, 
		@TSBarcodeSeq = TSBarcodeSeq
		FROM  @RoutingConfigPartWise 
		where OperationCode=@Operation_Code

		print 1
		--insert into @ChildPartDetails(SR_NO,ChildPart)
		delete from @TEMP_ChildPart
		insert into @TEMP_ChildPart(S_NO,ChildPart)
		select ROW_NO as 'S_NO',col1 as 'ChildPart' from fn_grid_split_string(ltrim(rtrim(@ChildPartsList)),'',',')

		delete from @TEMP_BomQty
		insert into @TEMP_BomQty(S_NO,bom_qty)
		select ROW_NO as 'S_NO',col1 as 'BomQty' from fn_grid_split_string(ltrim(rtrim(@ChildPartsBomQty)),'',',')

		delete from @TEMP_TraceFlag
		insert into @TEMP_TraceFlag(S_NO,trace_flag)
		select ROW_NO as 'S_NO',col1 as 'TraceFlag' from fn_grid_split_string(ltrim(rtrim(@ChildPartsTraceFlag)),'',',')

		delete from @ChildPartDetails
		--select * from @ChildPartDetails
		insert into @ChildPartDetails(SR_NO,ChildPart,bom_qty,trace_flag)
		select cp.S_NO,cp.ChildPart,bq.bom_qty,tf.trace_flag from @TEMP_ChildPart cp inner join 
		@TEMP_BomQty bq on cp.S_NO=bq.S_NO inner join
		@TEMP_TraceFlag tf on tf.S_NO=cp.S_NO
		
		delete from @ChildPartScanningSeqColumnWise
		-- Delete Lot Trace Child Parts
		delete from @ChildPartDetails where trace_flag='L'			
		print 2
		-- if any part loaded exists check for sequence
		if exists (select top 1 1 from @ChildPartDetails)
		begin
				
				while exists(select top 1 1 from @ChildPartDetails)
				begin
						SELECT @CHILD_PART=CHILDPART,@BOM_QTY=BOM_QTY FROM @CHILDPARTDETAILS ORDER BY SR_NO DESC
						
						while(@BOM_QTY > 0)
						begin
								set @Column_Seq = @Column_Seq + 1
								if(@Column_Seq = @TSBarcodeSeq)
								begin
								set @Column='TS_Barcode'
								end
								else
								begin
								set @Column = 'ChildPart_' + CONVERT(varchar,@Column_Seq)
								end
								--select @Column
								set @BOM_QTY = @BOM_QTY - 1

								insert into @ChildPartScanningSeqColumnWise(ChildPart,bom_qty,FoundInColumn,IsScanned)
								values(@CHILD_PART,1,@Column,0)
						end

						delete from  @CHILDPARTDETAILS where CHILDPART=@CHILD_PART
				end
				
				insert into Assy_Temp_ChildPartColumnMapping(
				ProfitCenterCode,LineCode,MachineCode,OperationCode,PartNumber,[Table],[Column],ChildPart,bom_qty,[ChildPartBarcode],
				[SeqNumber],IsScanned,Sts_Cd,ENT_BY,ENT_STAMP,LAST_UPD_BY,LAST_UPD_STAMP
				)
				select @P_PROFITCENTER_CODE,@P_LINE_CODE,@Machine_Code,@Operation_Code,@P_PART_NO,@P_TableName, 
				FoundInColumn,ChildPart,bom_qty,'',SR_NO,IsScanned,1,'ADMIN',GETDATE(),'ADMIN',GETDATE() from @ChildPartScanningSeqColumnWise
				
				

			end
		
	end
		
	delete from @OperationCode where OperationCode = @Operation_Code
	set @Column_Seq=0						
	end

	end

	select SeqNumber,PartNumber,ChildPart,[Column],OperationCode,ChildPartBarcode 
	from Assy_Temp_ChildPartColumnMapping(nolock) where ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE
	order by SeqNumber
END
IF(@P_MODE='GET_RUNNING_PART')
BEGIN

select ISNULL(Assy_PartNo,'') as 'Assy_PartNo' from Assy_RunningPart(nolock) where ProfitCenterCode=@P_PROFITCENTER_CODE
and LineCode=@P_LINE_CODE

END

IF(@P_MODE='GET_OPERATION_CODE')
BEGIN

select distinct o.OperationName,o.OperationCode from Assy_Temp_ChildPartColumnMapping(nolock) tmp inner join
OperationMst(nolock) o on tmp.OperationCode=o.OperationCode
where tmp.LineCode=@P_LINE_CODE and tmp.ProfitCenterCode=@P_PROFITCENTER_CODE

END

IF(@P_MODE='HOLD_CPD_DATA')
BEGIN

	insert into assy_Child_Part_Details_Hold(
	ProfitCenterCode,LineCode,MachineCode,OperationCode,PartNumber,DateCode,Barcode,ChildPartNo,
	ChildPartBarcode,STS_CD,ENT_BY,ENT_STAMP
	)
	select distinct ProfitCenterCode,LineCode,MachineCode,OperationCode,PartNumber,'',@P_Barcode,ChildPart,
	ChildPartBarcode,0,'ADMIN',getdate() from Assy_Temp_ChildPartColumnMapping(nolock) where ProfitCenterCode=@P_PROFITCENTER_CODE 
	and LineCode = @P_LINE_CODE and	machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO
	and [Column] <> 'TS_BARCODE'

END

IF(@P_MODE='SAVE_CPD_DATA')
BEGIN
		BEGIN TRY
			
			if exists(select top 1 1 from Assy_Temp_ChildPartColumnMapping(nolock) where ProfitCenterCode=@P_PROFITCENTER_CODE 
			and LineCode = @P_LINE_CODE and	machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE 
			and PartNumber=@P_PART_NO)
			begin
					
				select @OperationWiseTotalScan = count(*) from Assy_Temp_ChildPartColumnMapping(nolock) where 
				ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
				machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE 
				print @OperationWiseTotalScan
				select @OperationWiseCurrentScanned = SUM(isScanned) from Assy_Temp_ChildPartColumnMapping(nolock) where 
				ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
				machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and isScanned=1
				print @OperationWiseCurrentScanned	

				if(@OperationWiseTotalScan=@OperationWiseCurrentScanned)
				begin	
				print 'Go For Pass'			
				end
				else
				begin
						
						select top 1 @CHILDPART_1=childPart , @totalSeq=seqNumber from Assy_Temp_ChildPartColumnMapping where 
						ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
						machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO and isScanned=0 
						order by seqNumber asc
						
						SELECT 1 as 'STS_CD',
						'Please Scan Barcode of Child Part ('+isnull(@CHILDPART_1,'')+')' + ' Seq No. ' 
						+ convert(varchar,ISNULL(@totalSeq,'')) as 'MSG',
						@P_BARCODE as 'TS_BARCODE'		

						return
				end


			end

			BEGIN TRAN SAVE_CPD_DATA

			Declare @ParameterData Assy_TYPE_LineAssyParamData_Running_DB

			select top 1 @TS_Barcode=ChildPartBarcode from Assy_Temp_ChildPartColumnMapping(nolock) where ProfitCenterCode=@P_PROFITCENTER_CODE 
			and LineCode = @P_LINE_CODE and	machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE 
			and PartNumber=@P_PART_NO and [Column]='TS_BARCODE'

			insert into @ParameterData(
			ProfitCenterCode,LineCode,MachineCode,
			OperationCode,StationCode,Barcode,TagName,Value,Result,Datecode,UserID)
			select @P_PROFITCENTER_CODE,@P_LINE_CODE,@P_MACHINE_CODE,
			@P_OPERATION_CODE,'1',@TS_Barcode,'Result','PS','PS','','TS' 
				
			exec Assy_Proc_DBIntegration @Operation='INSERT_PLC_PARAMS',@LineCode=@P_LINE_CODE,
			@tblParameters=@ParameterData 
			print '-----INSERT ASSY_CHILD_PART_DETAILS ----------'
			insert into assy_Child_Part_Details(
			ProfitCenterCode,LineCode,MachineCode,OperationCode,PartNumber,DateCode,Barcode,
			ChildPartNo,ChildPartBarcode,SeqNumber,STS_CD,ENT_BY,ENT_STAMP 
			)
			select ProfitCenterCode,LineCode,MachineCode,OperationCode,PartNumber,DateCode,Barcode,
			ChildPartNo,ChildPartBarcode,SeqNumber,STS_CD,ENT_BY,ENT_STAMP 
			from assy_Child_Part_Details_Hold(nolock) where ProfitCenterCode=@P_PROFITCENTER_CODE
			and LineCode=@P_LINE_CODE and MachineCode=@P_MACHINE_CODE 
			and OperationCode=@P_OPERATION_CODE

			print '-----DELETE assy_Child_Part_Details_Hold ----------'
			print 'Profitcenter ' + ISNULL(@P_PROFITCENTER_CODE,'') + ' LineCode ' + ISNULL(@P_LINE_CODE,'') 
			+ ' MachineCode ' + ISNULL(@P_MACHINE_CODE,'') + ' OperationCode ' + ISNULL(@P_OPERATION_CODE,'') 

			delete from assy_Child_Part_Details_Hold where ProfitCenterCode=@P_PROFITCENTER_CODE
			and LineCode=@P_LINE_CODE and MachineCode=@P_MACHINE_CODE 
			and OperationCode=@P_OPERATION_CODE

			print '-----RESET Assy_Temp_ChildPartColumnMapping ----------'
			update Assy_Temp_ChildPartColumnMapping set ChildPartBarcode='',IsScanned=0
			where ProfitCenterCode=@P_PROFITCENTER_CODE
			and LineCode=@P_LINE_CODE and MachineCode=@P_MACHINE_CODE 
			and OperationCode=@P_OPERATION_CODE

			SELECT 100 as 'STS_CD','Part Has Been Passed' as 'MSG',	@TS_Barcode as 'TS_BARCODE'	

		COMMIT TRAN SAVE_CPD_DATA
		END TRY
		BEGIN CATCH
		ROLLBACK TRAN SAVE_CPD_DATA
		END CATCH
		
END

IF(@P_MODE='RESET_CPD_DATA')
BEGIN
		BEGIN TRY
	
			print '-----DELETE assy_Child_Part_Details_Hold ----------'
			print 'Profitcenter ' + ISNULL(@P_PROFITCENTER_CODE,'') + ' LineCode ' + ISNULL(@P_LINE_CODE,'') 
			+ ' MachineCode ' + ISNULL(@P_MACHINE_CODE,'') + ' OperationCode ' + ISNULL(@P_OPERATION_CODE,'') 

			delete from assy_Child_Part_Details_Hold where ProfitCenterCode=@P_PROFITCENTER_CODE
			and LineCode=@P_LINE_CODE and MachineCode=@P_MACHINE_CODE 
			and OperationCode=@P_OPERATION_CODE

			print '-----RESET Assy_Temp_ChildPartColumnMapping ----------'
			update Assy_Temp_ChildPartColumnMapping set ChildPartBarcode='',IsScanned=0
			where ProfitCenterCode=@P_PROFITCENTER_CODE
			and LineCode=@P_LINE_CODE and MachineCode=@P_MACHINE_CODE 
			and OperationCode=@P_OPERATION_CODE

			SELECT ' RESET DONE !! KINDLY SCAN BARCODE AGAIN ' as 'MSG'

		
		END TRY
		BEGIN CATCH		
		END CATCH
		
END

IF(@P_MODE='RESET_TS_BARCODE') -- if any error reset TS barcode
BEGIN
		
		update Assy_Temp_ChildPartColumnMapping
		set [ChildPartBarcode]='',IsScanned=0
		where ProfitCenterCode=@P_PROFITCENTER_CODE and LineCode = @P_LINE_CODE and
		machineCode=@P_MACHINE_CODE and OperationCode=@P_OPERATION_CODE and PartNumber=@P_PART_NO
		and [ChildPartBarcode]=@P_BARCODE

END

IF(@P_MODE='RELOAD_CPD_DATA')
BEGIN
		BEGIN TRY
	
			print '-----DELETE assy_Child_Part_Details_Hold ----------'
			print 'Profitcenter ' + ISNULL(@P_PROFITCENTER_CODE,'') + ' LineCode ' + ISNULL(@P_LINE_CODE,'') 
			+ ' MachineCode ' + ISNULL(@P_MACHINE_CODE,'') + ' OperationCode ' + ISNULL(@P_OPERATION_CODE,'') 

			delete from assy_Child_Part_Details_Hold where ProfitCenterCode=@P_PROFITCENTER_CODE
			and LineCode=@P_LINE_CODE 

			print '-----RESET Assy_Temp_ChildPartColumnMapping ----------'
			delete Assy_Temp_ChildPartColumnMapping where ProfitCenterCode=@P_PROFITCENTER_CODE
			and LineCode=@P_LINE_CODE 

			exec [PROC_VALIDATE_N_SAVE_SCANNED_BARCODE] @P_Mode='LOAD_ALL_CPD',@P_PROFITCENTER_CODE=@P_PROFITCENTER_CODE,
			@P_LINE_CODE=@P_LINE_CODE,@P_PART_NO=@P_PART_NO

		
		END TRY
		BEGIN CATCH		
		END CATCH
		
END

end try
begin catch
	SET @RETURNVALUE =	CAST(ISNULL(ERROR_NUMBER(),0) AS VARCHAR(5)) + '|' + 
	CAST(ISNULL(ERROR_SEVERITY(),0)AS VARCHAR(5)) + '|' + 
	CAST(ISNULL(ERROR_STATE(),0) AS VARCHAR(5)) + '|' + 
	CAST(ISNULL(ERROR_PROCEDURE(),'') AS VARCHAR(200)) + '|' + 
	CAST(ISNULL(ERROR_LINE(),0) AS VARCHAR(5)) + '|' + 
	CAST(ISNULL(ERROR_MESSAGE(),'') AS VARCHAR(1500))
	SET @RETURNINT =1
end catch
END
GO
/****** Object:  StoredProcedure [dbo].[PROC_VERIFY_LOGIN]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


/*----------------------------------------------------------------------
'(C) 2005 SUMITOMO WIRING SYSTEMS LTD, ALL RIGHTS RESERVED
'
'PROCEDURE NAME		: PROC_VERIFY_LOGIN
'FUNCTION		: TO VERIFY THE LOGGED IN USER
'CREATED BY		: VISHAL BHOLA
'CREATED ON		: 2006-10-12  
'REVISION HISTORY	:
'DATE				MODIFIED BY						DESCRIPTION
'2009-09-22			SK								FOR FORGET PASSWORD, NEED TO VALIDATE THE USERID ONLY
'2009-09-24			TG								If User Account Has Been Locked He Cannot Login
'2011-04-26         KG                              Changed for Hungary Plant2

2012-10-23			SB								To check the user is defined in MFG?PRO or not
20121026 SB To check from table MFG_USR_MSTR
20121027 GG Active user check in MFG_USR_MSTR
20140708 GG USER_SITE_MAP_MASTER only for Desktop and not for HHT
20141128 GG user name to user code
20170303 RR TO INSERT APP VERSION AND DBVERSION IN LOG FILE ANG TABLE
20170321 PK TO REDIRECT USER ON CHANGE PASSWORD SCREEN IF PASSWORD IS EXPIRED OR TO SHOW ERROR MSGS FOR VALID APP IDS.	
20170503 AV CHANGES TO CALL VERSION VALIDATION PROCEDURE TO VALIDATE VERSION OF THE APPLICATION WITH THE VERSION STORED IN DATABASE 
20170522 AV TO REDIRECT USER TO CHANGE PASSWORD SCREEN ON FIRST TIME LOGIN
20170525 NK TO ADD @P_REMAINING_DAYS PARAMETER OF TYPE INT (ERROR IN NON ASSEMBLY APPLICATION IF @Msg_Out PARAMETER like '500|' + @P_REMAINING_DAYS AS NVARCHAR)
20170530 AP Login validation with ware house = OR @APP_ID = '3'
20170727 PK TO ADD DOWNTIME ALERT FUNCTIONALITY
20170817 TO USE KEY FOR PASSWORD EXPIRY ALERTS DAYS
20170926 Move User Exist or not on top
declare @msg_out nvarchar(25)
exec PROC_VERIFY_LOGIN 'SHELL','0','L',@msg_out out
select @msg_out
----------------------------------------------------------------------*/
CREATE PROC [dbo].[PROC_VERIFY_LOGIN]
(    
 @USERNAME 		NVARCHAR(20),    
 @PASSWORD 		NVARCHAR(50),
 @FLAG			nchar(1),       -- FLAG FLAG L IS FOR LOGIN , U IS FOR UPDATE INTO LOGINSTATUS , F IS FOR USER CHECK IN ELSE CASES
 @MSG_OUT    	NVARCHAR(200)     OUTPUT,
 @SITE          nvarchar(4) = '',
 @APP_ID		nvarchar(4) = '2',
 @MACHINE		NVARCHAR(50) = '',
 @SERVERNAME	NVARCHAR(50) = '',
 @P_SESSION_ID	NVARCHAR(50) = '',
 @P_APP_VERSION	NVARCHAR(40) = '',
 @P_DATEFORMAT	int = 105,
 @P_SID	        NVARCHAR(40) = '' OUTPUT,
 @P_REMAINING_DAYS INT = 0  OUTPUT,
 @P_ERROR_MSG NVARCHAR(200) = '' OUTPUT
) 
AS
BEGIN
	SELECT * INTO #TL_MF_SEC_USER_MST FROM TL_MF_SEC_USER_MST(NOLOCK) WHERE USER_CODE = @USERNAME AND PASSWORD=@PASSWORD
	DECLARE @IsValidatePwdExpiry   NVARCHAR(10)
	SELECT @IsValidatePwdExpiry = dbo.FN_GET_PARAMETER_VALUE_SECTION('SECURITY','VALIDATE_LOGIN_PWD_EXPIRY','',@SITE)
	SELECT data As AppId  INTO #AllowedAppIds FROM dbo.SplitString(@IsValidatePwdExpiry,',')

	DECLARE @USER_ID		NUMERIC(8,0)
	DECLARE @EXPIRY_DAYS INT,
			@EXPIRY_DATE DATETIME, 
			@LASTPASSWORDCHANGEDATE DATETIME, 
			@WARNINGDAYSBEFOREEXPIRE INT = 5,  
			@REMAININGDAYS INT = 5  
	
	SELECT @WARNINGDAYSBEFOREEXPIRE = dbo.FN_GET_PARAMETER_VALUE_SECTION('LOGIN','PASSWORRD_EXPIRY_ALERT','NO_OF_DAYS',@SITE)
		
	IF ISNULL(NULLIF(@WARNINGDAYSBEFOREEXPIRE,0),0) = 0
	BEGIN
		SET @WARNINGDAYSBEFOREEXPIRE = 5
	END

	IF Exists (SELECT TOP 1 1 FROM #AllowedAppIds WHERE AppId = @APP_ID) 
	BEGIN
		SELECT @USER_ID  = [user_id]
		FROM #TL_MF_SEC_USER_MST 

		SELECT TOP 1 @LASTPASSWORDCHANGEDATE = ISNULL(LAST_PWD_CHANGE_DATETIME, REGISTRATION_DATETIME_TIME), @EXPIRY_DAYS = ISNULL(EXPIRY_DAYS,0)
		FROM #TL_MF_SEC_USER_MST

		SET  @REMAININGDAYS = @EXPIRY_DAYS  - DATEDIFF(DAY,@LASTPASSWORDCHANGEDATE, GETDATE()) 

		IF(ISNULL(@EXPIRY_DAYS,0) <> 0 AND (@REMAININGDAYS = 0 OR @REMAININGDAYS < 0))
		BEGIN
			UPDATE #TL_MF_SEC_USER_MST SET EXPIRY_STATUS = '01' 
			UPDATE TL_MF_SEC_USER_MST SET EXPIRY_STATUS = '01' WHERE USER_ID = @USER_ID
		END
	END

	IF @FLAG = 'F'
	BEGIN
		IF (SELECT count(*) FROM #TL_MF_SEC_USER_MST  WHERE	USER_CODE = @USERNAME) = 0  
		BEGIN    
			--  SELECT 'LOGIN ERROR !'    
			SELECT @MSG_OUT = '100'   
			RETURN    
		END   
	END

	IF @FLAG = 'L'
	BEGIN
		
		-- 20170926 -- Invalid USER block move by sachin
		IF ((SELECT count(*) FROM #TL_MF_SEC_USER_MST) = 0  )      
		BEGIN    
			--  SELECT 'INVALID USER '    
			SELECT @MSG_OUT ='100'   
			RETURN    
		END  

		IF ((SELECT count(*) FROM #TL_MF_SEC_USER_MST  WHERE LOCK_FLAG = '01') > 0 ) 
		BEGIN    
		--  SELECT 'Account is locked'    
			SELECT @MSG_OUT ='200'   
		RETURN    
		END 
			
		IF Exists (SELECT TOP 1 1  FROM #AllowedAppIds WHERE AppId = @APP_ID) 
		BEGIN
			IF ((SELECT count(*) FROM #TL_MF_SEC_USER_MST  WHERE EXPIRY_STATUS = '01') > 0 ) 
			BEGIN    
			--  SELECT 'Please Change Your Password'    
				SELECT @MSG_OUT ='300'   
			RETURN    
			END 
		END
		--To CHECK IF USER IS LOGGING IN FIRST TIME
		IF Exists (SELECT 1 FROM #TL_MF_SEC_USER_MST WHERE LAST_PWD_CHANGE_DATETIME is Null) 
			BEGIN    
			--  SELECT 'Please Change Your Password'    
				SELECT @MSG_OUT ='400'   
			RETURN    
			END 
		-- IF Remaining Days will be less than or equal to @WarningDaysBeforeExpire then a message will be shown to the user 
		-- that your password will expire in next @RemainingDays	
        IF (@RemainingDays <= @WarningDaysBeforeExpire)
              BEGIN
                     SELECT @MSG_OUT ='500'
					 SELECT @P_REMAINING_DAYS = @RemainingDays
					 RETURN
		END

-- end
		

		ELSE 
		BEGIN
			--SB on 2012-10-23
			declare @USER_ACTIVE nvarchar(10), @USERNAME1 NVARCHAR(30), @FLG_USER_CHECK NVARCHAR(4)

			SELECT @FLG_USER_CHECK = DBO.FN_GET_WMS_KEY_VAL(@SITE,'USER MFGPRO CHECK')
  
			IF @FLG_USER_CHECK ='Y'
			BEGIN
				SELECT @USERNAME1 = EMPLOYEE_ID FROM TL_MF_SEC_USER_MST (NOLOCK) 
				WHERE USER_CODE = @USERNAME  and isnull(EMPLOYEE_ID,'')  <> ''

				if isnull(@USERNAME1,'')  = ''  
				begin
					select @USERNAME1 = @USERNAME
				end

				--Modified by SB On 20121026
--				SELECT @USER_ACTIVE = usrl_active
--				FROM   mfg_usrl_det (NOLOCK)
--				WHERE  usrl_userid = @USERNAME1
--				AND usrl_product = 'MFG/PRO'

				SELECT @USER_ACTIVE = usr_active
				FROM   MFG_USR_MSTR (NOLOCK)
				WHERE  usr_userid = @USERNAME1
				--and usr_active = 1  --Commented by SB on 20121029
				--AND usr_product = 'MFG/PRO'

				IF ISNULL(@USER_ACTIVE,'')=''
				BEGIN
					--SELECT @MSG_OUT =20170--'USER NOT DEFINED IN MFG/PRO'
					EXEC PROC_CUSTOM_RAISERROR 50001,16,1, '80617'
					RETURN
				END
				IF @USER_ACTIVE <> '1'
				BEGIN
					--SELECT @MSG_OUT =20170--'USER IS NOT ACTIVE IN MFG/PRO'
					EXEC PROC_CUSTOM_RAISERROR 50001,16,1, '80618'
					RETURN
				END
			END


		if (@APP_ID = '1' OR @APP_ID = '3') -- 1 : TS web site , 3 = Non-assemblye-application
		begin

					if not exists (SELECT SITE_CODE FROM USER_SITE_MAP_MASTER(NOLOCK) M
							WHERE M.[USER_ID] = @USERNAME
							AND M.SITE_CODE =  @SITE  
							AND STS_CD = 0
					)
					begin
							--SELECT @MSG_OUT =20170--'USER IS NOT ACTIVE IN MFG/PRO'
							EXEC PROC_CUSTOM_RAISERROR 50001,16,1, '80300'
							RETURN
			
					end
			
		end			
			--ADDED BY PK ON 20170719
			DECLARE @STARTTIME DATETIME, @ENDTIME DATETIME, @SYSTEMMSG NVARCHAR(200), @GUNMSG NVARCHAR(200),@DOWNTIMEINTERVAL int = 30
			
			--Fetch SYSTEM DOWTIME INFO
			SELECT TOP 1 @STARTTIME = STARTDATETIME, @ENDTIME=ENDDATETIME,  @SYSTEMMSG = MESSAGE,@GUNMSG = GUNMESSAGE
			FROM SYSTEM_MESSAGE_SERVICE 
			WHERE STARTDATETIME BETWEEN GETDATE() AND DATEADD(MI,@DOWNTIMEINTERVAL,GETDATE()) OR (STARTDATETIME < GETDATE() AND ENDDATETIME > GETDATE()) 
				AND MSG_TYPE = 'SYSTEM_DOWNTIME' AND STS_CD = 0 AND WH_CODE = case when isnull(@SITE,'') = '' then '0021' else @SITE END
			ORDER BY STARTDATETIME ASC

			IF @STARTTIME < GETDATE() AND @ENDTIME > GETDATE() AND @APP_ID = '1'
			BEGIN
				SET @MSG_OUT = @SYSTEMMSG + ' Start Time: ' + CONVERT(NVARCHAR(5),@STARTTIME,108)  + ' End Time: ' 
				 + CONVERT(NVARCHAR(5),@ENDTIME,108) + ' Duration: ' + CONVERT(NVARCHAR(3),DateDiff(minute,@STARTTIME,@ENDTIME)) + ' Minute'
				RETURN
			END

			IF @STARTTIME < GETDATE() AND @ENDTIME > GETDATE() AND @APP_ID = '2'
			BEGIN
				SET @MSG_OUT = @GUNMSG + ' Start Time: ' + CONVERT(NVARCHAR(5),@STARTTIME,108)  + ' End Time: ' 
				+ CONVERT(NVARCHAR(5),@ENDTIME,108) + ' Duration: ' + CONVERT(NVARCHAR(3),DateDiff(minute,@STARTTIME,@ENDTIME)) + ' Minute'
				RETURN
			END

			--ADDED BY AV ON 20170503
			DECLARE @MSG NVARCHAR(200)
			--WHEN USER & PASSSWORD ARE OK THEN WE WILL VERIFY VERSION OF THE APPLICATION
			EXEC PROC_VERIFY_APP_VERSION @P_WH_CODE=@SITE,@P_APP_ID=@APP_ID,@P_APP_VERSION=@P_APP_VERSION ,@P_MSG_OUT=@MSG OUT 	
			IF @MSG <> '600' --IF VERSION IS NOT OK THEN WE WILL RETURN VALIDATION FAIL MESSAGE WHITH WARNIG OR ERROR AS CONFIGURED IN PARAMETER_MST
			BEGIN
				SELECT	@MSG_OUT = @MSG
				RETURN
			END
			ELSE --SUCCESS MESSAGE
			SELECT @MSG_OUT ='20170'

			DECLARE @SID NVARCHAR(50) =''
			DECLARE @DB_VERSION NVARCHAR(50) =''
			SELECT @DB_VERSION = dbo.FN_GET_PARAMETER_VALUE_SECTION('DACS DB VERSION','','',@SITE)
		
			SELECT @SID = CONVERT(VARCHAR(8),GETDATE(),112)+CONVERT(VARCHAR(12),GETDATE(),114)

			INSERT INTO LOGINSTATUS ([SID], [USERNAME], [MACHINE], [SERVERNAME],[SESSION_ID],[LOGINTIME],[APP_ID],[AppVersion],[DBVersion])
			VALUES (@SID, @USERNAME, @MACHINE,@SERVERNAME,@P_SESSION_ID ,GETDATE(),@APP_ID,@P_APP_VERSION,@DB_VERSION)
			SELECT @P_SID =@SID

		END 
	END

    IF @FLAG = 'U'
    BEGIN		
		UPDATE LOGINSTATUS SET LOGOUTTIME = GETDATE()-.00001 WHERE  LOGOUTTIME IS NULL and [SID] = @P_SID
		SELECT 'OK|'
	END
END


GO
/****** Object:  StoredProcedure [dbo].[ProcAssyValidateVisionSystem]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
