CREATE Procedure [dbo].[ProcAssyValidateVisionSystem]
(
@ProfitCentercode varchar(30),
@LineCode varchar(20),
@Option varchar(100),
@DateCode varchar(10),
@LeftShoeBarcode varchar(160) = null,
@RightShoeBarcode varchar(160) = null,
@Barcode varchar(160)=null,
@Result varchar(10) = null,
@FGPartNumber varchar(60) = null,
@rmPartNumber varchar(60) = null,
@UserId varchar(100)=null,
@VisionResult varchar(10)=null,
@ReturnInt int out,
@ReturnValue varchar(100) out
)
as

Begin

Begin Try
	create table #temp_bomdata
	(FG_PART_NO  NVARCHAR(30), BOMPart_no  NVARCHAR(30),
	RM_PART_NO NVARCHAR(30), bom_qty  NVARCHAR(30), base_qty  NVARCHAR(30),
	MAT_PROCURE_TYPE  NVARCHAR(30),MAT_USE_RATIO  NVARCHAR(30),ALT_ITEM_GRP_CODE  NVARCHAR(30))

	Declare @DateCodeValue varchar(20),@FGLocal varchar(100),@FGLive varchar(100),@ModelData nvarchar(100),@CustomerData nvarchar(100)

If (@Option = 'SELECT_PART')
Begin
	select Distinct DrumBrakePartNumber from PartMaster(nolock)
End

If (@Option = 'SAVE_DATE')
Begin
	--select DrumBrakePartNumber,LineShoePartNumber,Model,Customer from  WHERE DrumBrakePartNumber = @FGPartNumber
	
	insert into #temp_bomdata exec Proc_BOM_Explosion @ProfitCenterCode = @ProfitCentercode ,@PartNumber = @FGPartNumber,@BOM_VERSION = '1'
	select @ModelData=isnull(LabelDataValue,'') from Assy_Coupling_LabelInfo_Mst where LabelDataName='Cust_Model_No' and partno=@FGPartNumber
	select @CustomerData=isnull(LabelDataValue,'') from Assy_Coupling_LabelInfo_Mst where LabelDataName='CUSTOMER_MODEL' and partno=@FGPartNumber
	select distinct FG_PART_NO DrumBrakePartNumber,RM_PART_NO LineShoePartNumber,@ModelData Model, @CustomerData Customer from #temp_bomdata BM 
	left join PRODUCT_MASTER(nolock) PM on PM.SEWS_PART_NO=BM.RM_PART_NO where BM.FG_PART_NO=@FGPartNumber and PM.product_nm 
	like '%LINED SHOE ASSY%' and PM.warehouse_cd=@ProfitCentercode

End

If (@Option = 'GET_DATE_CODE')
Begin


	EXEC [ASSY_PROC_GET_DATECODE] @ProfitCenterCode,@LineCode,@RETURNVALUE  OUT,@RETURNINT   OUT
	Set @DateCodeValue = @RETURNVALUE

	select @DateCodeValue

End

If (@Option = 'INSERT_RUNNING_PART')
Begin

	EXEC [ASSY_PROC_GET_DATECODE] @ProfitCenterCode,@LineCode,@RETURNVALUE  OUT,@RETURNINT   OUT
	Set @DateCodeValue = @RETURNVALUE
	
	If Exists (Select top 1 1 from CurrentRunningPart)
	Begin

	insert into CurrentRunningPartHistory (ProfitCenterCode, LineCode, DateCode, FGPartNumber, EntBy, ChangeOverEntStamp)
	select ProfitCentercode,LineCode,DateCode,FGPartNumber,EntBy,GETDATE() from CurrentRunningPart

	Delete from CurrentRunningPart

	Insert Into CurrentRunningPart (ProfitCentercode,LineCode,DateCode,FGPartNumber,EntBy,EntStamp) 
	select @ProfitCentercode,@LineCode,@DateCodeValue,@FGPartNumber,@UserId,GETDATE()

	Set @ReturnValue = 'Part Number Set Successfully'
	Set @ReturnInt = 1

	Select @ReturnValue,@ReturnInt

	End

	Else
	Begin

	Insert Into CurrentRunningPart (ProfitCentercode,LineCode,DateCode,FGPartNumber,EntBy,EntStamp) 
	select @ProfitCentercode,@LineCode,@DateCodeValue,@FGPartNumber,@UserId,GETDATE()
	
	End


End

If (@Option = 'VALIDATE_BOM')
Begin

	DECLARE @ProfitCenter varchar(30), @FGPartNo varchar(30), @RMPartNo varchar(30)

	select @ProfitCenter = ProfitCenterCode, @FGPartNo = FGPartNumber from CurrentRunningPart

	If Exists (Select top 1 1 from AssyBarcodeData where (LeftShoeBarcode = LTRIM(RTRIM(@LeftShoeBarcode))) or (RightShoeBarcode = LTRIM(RTRIM(@RightShoeBarcode))) and FGPartNumber = @FGPartNo)
	Begin
	
	Set @ReturnValue = 'Barcode Already Associated With FG Part Number : ' + @FGPartNo
	Set @ReturnInt = 2
	
	Select @ReturnValue, @ReturnInt 

	Return

	End

	Else

	begin

	--Select @RMPartNo = SUBSTRING(LineShoePartNumber,1,4) + @rmPartNumber from PartMaster where SUBSTRING(LineShoePartNumber, 5,4) = @rmPartNumber and DrumBrakePartNumber = @FGPartNo 
		if Exists(select top 1 1 from [dbo].[PRODUCT_MASTER] where [SEWS_PART_NO]=@FGPartNo and sts_cd=0)
			Begin
			
			insert into #temp_bomdata exec Proc_BOM_Explosion @ProfitCenterCode = @ProfitCentercode ,@PartNumber = @FGPartNumber,@BOM_VERSION = '1'
				If Exists (select top 1 1 from #temp_bomdata where SUBSTRING(RM_PART_NO, 5, 4) =  @rmPartNumber and FG_PART_NO = @FGPartNo)
					Begin

							Set @ReturnValue = 'VALID'
							Set @ReturnInt = 1

							Select @ReturnValue, @ReturnInt

					End

				Else

					Begin

							Set @ReturnValue = 'INVALID'
							Set @ReturnInt = 2

							Select @ReturnValue, @ReturnInt

					End

			End
	End

	--DECLARE @Bom_Explosion AS TABLE
	--(
	--	AutoID SMALLINT IDENTITY(1,1),FG_Part_No VARCHAR(20) NULL,BOM_Part_No VARCHAR(20) NULL,RM_Part_No VARCHAR(20) NULL,
	--	BOM_Qty INT NULL,BOM_Unit VARCHAR(20) NULL,MAT_Procure_Type VARCHAR(20) NULL,MAT_Use_Ratio VARCHAR(20) NULL,
	--	Alt_Item_Grp_Code VARCHAR(20) NULL,IsMandatory BIT DEFAULT(0)
	--)	
	--DELETE FROM @Bom_Explosion	
	--INSERT INTO @Bom_Explosion(FG_Part_No, BOM_Part_No, RM_Part_No, BOM_Qty, BOM_Unit, MAT_Procure_Type, MAT_Use_Ratio, Alt_Item_grp_Code)
	--EXEC Proc_BOM_Explosion @ProfitCenter, @FGPartNo, '', '1', 'SUMMARY'	
	--If exists (select top 1 1 from @bom_explosion where rm_part_no = @rmPartNumber)
	--Begin	
	--Select 'OK'	
	--End	
	--Else 	
	--Begin 	
	--Select 'NOK'	
	--End

End

If (@Option = 'VALIDATE_BARCODE')
Begin

	select @FGPartNo = FGPartNumber from CurrentRunningPart

	If Exists (Select top 1 1 from AssyBarcodeData where (LeftShoeBarcode = LTRIM(RTRIM(@Barcode)) or RightShoeBarcode = LTRIM(RTRIM(@Barcode)) ) and FGPartNumber = @FGPartNo and Result = 'OK')
	Begin
	if Not Exists(select top 1 1 from assy_visionresult where barcode=@Barcode and result='PASS')
	Begin
	Set @ReturnValue = 'Success'
	Set @ReturnInt = 1
	
	--Select @ReturnValue, @ReturnInt 

	Return
	End
	else
	Begin
	Set @ReturnValue = 'Already Scanned in Vision System!!'
	Set @ReturnInt = 2
	Return
	End
	End
	
	Else

	Begin

	Set @ReturnValue = 'Barcode data not found!! Not scanned in previous station!!'
	Set @ReturnInt = 2

	--Select @ReturnValue, @ReturnInt
	
	Return

	End

End

If (@Option = 'INSERT_BARCODDE_DETAIL')
Begin

	declare @FgPart varchar(30)

	EXEC [ASSY_PROC_GET_DATECODE] @ProfitCenterCode,@LineCode,@RETURNVALUE  OUT,@RETURNINT   OUT
	Set @DateCodeValue = @RETURNVALUE

	select @FgPart = FGPartNumber from CurrentRunningPart

	Insert Into AssyBarcodeData (ProfitCenterCode,Linecode,DateCode,FGPartNumber,LeftShoeBarcode,RightShoeBarcode,Result,EntBy,EntStamp)
	values( @ProfitCentercode, @LineCode, @DateCodeValue, @FgPart, @LeftShoeBarcode, @RightShoeBarcode, 'OK' , @UserId, GETDATE())

	 

	Set @ReturnValue = 'Data Inserted Successfully'
	Set @ReturnInt = 1

	Select @ReturnValue , @ReturnInt

End

If (@Option = 'Vision_Insert')
Begin
	If Not Exists (Select top 1 1 from assy_visionresult where barcode=@Barcode)	
	Begin
	Insert Into assy_visionresult (barcode,result,enttimestamp)
	values( @Barcode,'RESULT',getdate())
	End
	else
	Begin
	update assy_visionresult set result='RESULT' where barcode=@Barcode
	END
	
End




If (@Option = 'Vision_Update')
Begin
	
	update assy_visionresult set result=@VisionResult where result='RESULT'
	
	
End

if(@Option='CurrentRunning')

Begin

If Exists (select top 1 1 Assy_PartNo from Assy_RunningPart where linecode=@LineCode and profitcentercode=@ProfitCentercode order by createddate desc)
Begin
	select top 1 @FGLive=Assy_PartNo  from Assy_RunningPart where linecode=@LineCode and profitcentercode=@ProfitCentercode order by createddate desc

	If Exists (select top 1 1 from CurrentRunningPart where ProfitCentercode=@ProfitCentercode and LineCode=@LineCode)
	Begin
	 select @FGLocal=FGPartNumber from CurrentRunningPart where ProfitCentercode=@ProfitCentercode and LineCode=@LineCode
	 if(@FGLive <> @FGLocal)
	 Begin 
	   Insert into [dbo].[CurrentRunningPartHistory]([ProfitCentercode],[LineCode],[DateCode],[FGPartNumber],[EntBy],[ChangeOverEntStamp])
	   (select [ProfitCentercode],[LineCode],[DateCode],[FGPartNumber],[EntBy],getdate() from CurrentRunningPart)
	   delete from CurrentRunningPart
	   Insert into [dbo].[CurrentRunningPart]([ProfitCentercode],[LineCode],[DateCode],[FGPartNumber],[EntBy],EntStamp)
		(select profitcentercode,linecode,datecode,Assy_PartNo,createdby,getdate() from Assy_RunningPart )
	    
	 end 
	end
	else
	Begin
	 Insert into [dbo].[CurrentRunningPart]([ProfitCentercode],[LineCode],[DateCode],[FGPartNumber],[EntBy],EntStamp)
	 (select profitcentercode,linecode,datecode,Assy_PartNo,createdby,getdate() from Assy_RunningPart)
	end
	 
	
    select FGPartNumber from CurrentRunningPart where ProfitCentercode=@ProfitCentercode and LineCode=@LineCode  
	
end	

else
Begin

    Set @ReturnValue = 'No Part running on Line'
	Set @ReturnInt = 2
end

end

if(@Option='SaveEvent')
Begin

select top 1 * from Assy_PushButtonEvent 

delete from Assy_PushButtonEvent
end




End Try 
	
	Begin Catch  
	--CATCH BLOCK BEGINS
		SET @ReturnValue =	CAST(ERROR_NUMBER() as varchar(5)) + '|' + 
		CAST(ERROR_SEVERITY()as varchar(5)) + '|' + 
		CAST(ERROR_STATE() as varchar(5)) + '|' + 
		CAST(ERROR_PROCEDURE() as varchar(200)) + '|' + 
		CAST(ERROR_LINE() as varchar(5)) + '|' + 
		CAST(ERROR_MESSAGE() as varchar(1500))
							
		SET @ReturnInt = 2
		
		Select @ReturnValue, @ReturnInt

	--CATCH BLOCK ENDS 
	End Catch

End
GO
/****** Object:  StoredProcedure [dbo].[ProcSkidBarcodeInfo]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Anuj Suri>
-- Create date: <03 July 2014>
-- Description:	<Get Set Skid details>
-- To Rembember
-- Nothing = 0
-- Success = 1
-- Error = 2
-- AlreadyExists = 3
-- NotExists = 4
-- =============================================

CREATE PROCEDURE [dbo].[ProcSkidBarcodeInfo] 
	@SkidBarcodeInfoID BIGINT=NULL,
	@PartCustMapID INT=NULL,
	@PartNumber VARCHAR(50)=NULL,
	@PartSerialNumber BIGINT=NULL,
	@PartBarcode VARCHAR(50)=NULL,
	@NewPartBarcode VARCHAR(50)=NULL,	
	@SkidLabelBarcode VARCHAR(50)=NULL,
	@DateCode VARCHAR(10)=NULL,
	@SkidLabelBarcodePrinted BIT=NULL,
	@SkidBarcodePrintedTimestamp DATETIME=NULL,
	@IsHold BIT=NULL,
	@IsNotFirstPartInSkid BIT=NULL,
	@PrintedTimestamp [datetime]=NULL,	
	@LocationInSkid INT=NULL,
	@Remarks VARCHAR(300)=NULL,
	@SkidIds VARCHAR(300)=NULL,
	@Layer INT=NULL,
	@LayerQty INT=NULL,
	@FilledQty INT=NULL,
	@UserID INT=NULL,	
	@CustPartNumberLength  INT=NULL,
	@partNumberLastCharactersLength INT=NULL,
	@TotalPartsNumberLength INT=NULL,
	@LotSize INT=NULL,	
	@Rows INT=NULL, 
	@Columns INT=NULL,
	@Layers INT=NULL,
	@CountryCode VARCHAR(50)=NULL,
	@Confirmation BIT=NULL,
	@EmpCode VARCHAR (20)=NULL,
	@TransType VARCHAR (40),
	@WH_CODE warehouse_cd,
	@Line_cd VARCHAR(4)=NULL,
	@Station_cd varchar(20) =NULL,
	@OnlineOfflineflg BIT=NULL,					--Added by VM on 22-06-2015
	@Dispatchtype VARCHAR (100)=NULL,			--Added by VM on 22-06-2015
	@ReturnValue VARCHAR (2000)=NULL OUT,
	@ReturnInt INT=NULL OUT
AS
BEGIN
	BEGIN TRY 
	--TRY BLOCK BEGINS
		--Added by VM on 22-06-2015 [Start]
		IF (@OnlineOfflineflg=0)	--[Offline = Line Cd is not required , Online = Line Cd is required]   
		BEGIN
			SET @Line_cd=''
		END
		--Added by VM on 22-06-2015 [End]
		If(@TransType='CHECKBARCODEEXISTS')
		BEGIN
				DECLARE @EXIST INT
				SELECT @EXIST=COUNT(*) 
				FROM SkidBarcodeDetail 
				WHERE PartBarcode=@PartBarcode 
				and WH_CODE = @WH_CODE 

			IF(@EXIST<>0)
			BEGIN
				SET @ReturnValue='Barcode already linked with another skid.'
				SET @ReturnInt=3 
			END
			ELSE
			BEGIN
				SET @ReturnValue='Barcode not exists.'
				SET @ReturnInt=1 
			END	
		END
		ELSE IF(@TransType='REPRINTSELECT')
		BEGIN
			SELECT 
				ROW_NUMBER() OVER(ORDER BY PART_NUMBER) AS SrNo,
				PART_NUMBER, 
				PART_DESC, 
				ENT_DATE,
				Is_Active,
				IS_LAYERED_PACKING,
				PKG_DEF_ID
			FROM PKG_Part_Mapping ORDER BY PART_DESC
		END
		ELSE If(@TransType='CHECKSKIDDETAILSALREADYEXISTS')
		BEGIN
			DECLARE @SkidBarcodeIDLocal BIGINT
			DECLARE @PartCustMapIDLocal BIGINT
			--DECLARE @CountryCodeLocal VARCHAR(50)
			--DECLARE @CustomerCodeLocal VARCHAR(50)			

			SELECT	@SkidBarcodeIDLocal=MAX(SkidBarcodeInfoID)
			FROM SkidBarcodeInfo WHERE SkidBarcodePrinted=0 AND WH_CODE = @WH_CODE 
			AND StationCode=@Station_cd		--Added by VM on 16-06-2015	

			SELECT	info.SkidBarcodeInfoID,
					info.PartCustMapID, 
					info.SkidBarcode, 
					info.SkidBarcodePrinted, 
					info.SkidBarcodePrintedTimestamp, 
					info.IsHold, 
					detail.PartBarcode, 
					detail.ID,
					detail.LocationInSkid,
					info.Columns,
					info.Rows,
					info.Layers,
					info.LotSize as Lot_Qty,
					info.CountryCode as Country,
					-- ADDED BY VB ON 01-06-2015
					PPD.CUSTOMER_PART_NO as CustPartNo,
					PPD.PART_NUMBER as PartNumber,
					-- PPD.CUSTOMER_CODE CustomerCode,
					PPD.COUNTRY as Country,  -- ADDED BY VB ON 11-06-2015
					info.PartCustMapID AS Part_Cust_Map_ID,
					PPD.IS_LAYERED_PACKING LayerWisePrinting,
					PPD.PKG_SERIAL_NO as SerialNumber,
					pmst.product_nm as PartDescription,
					PPD.DISPATCH_TYPE as DISPATCH_TYPE -- ADDED BY VM ON 22-06-2015
					--info.Columns,
					--info.Rows,
					--info.Layers,
					--info.LotSize,
					--info.CountryCode,
					--map.CustPartNo,
					--map.PartNumber,
					--map.CustomerCode,
					--info.PartCustMapID AS Part_Cust_Map_ID,
					--pmst.LayerWisePrinting,
					--pmst.SerialNumber,
					--pmst.PartName PartDescription
					-- ADDED BY VB On 01-06-2015
			FROM SkidBarcodeInfo info				
					INNER JOIN SkidBarcodeDetail detail ON info.SkidBarcodeInfoID=detail.SkidBarcodeInfoID
					INNER JOIN PKG_PART_MAPPING PPD ON info.PartCustMapID=PPD.PKG_DEF_ID    -- CHANGED BY VB ON 11-06-2015
					--INNER JOIN PKG_PACKAGING_DEFINITION PPD ON info.PartCustMapID=PPD.PKG_DEF_ID 
					--INNER JOIN CUSTOMER_MASTER CM ON PPD.CUSTOMER_CODE = CM.CUSTOMER_C AND CM.WAREHOUSE_CD = PPD.WH_CODE AND CM.WAREHOUSE_CD = @WH_CODE
					--INNER JOIN PartMaster pmst ON map.PartNumber=pmst.PartNumber
					INNER JOIN PRODUCT_MASTER pmst ON PPD.PART_NUMBER = pmst.sews_part_no AND PPD.WH_CODE = @WH_CODE 
			WHERE info.SkidBarcodeInfoID=@SkidBarcodeIDLocal AND info.SkidBarcodePrinted=0 AND info.IsHold=0
			AND info.StationCode=@Station_cd		--Added by VM on 16-06-2015	
			ORDER BY detail.ID			
			
			SET @ReturnValue='Success'
			SET @ReturnInt=1 			
		END
		ELSE If(@TransType='CHECKSKIDDETAILSALREADYEXISTSONMAPID')
		BEGIN
			DECLARE @SkidBarcodeIDLocal1 BIGINT

			SELECT	@SkidBarcodeIDLocal1=MAX(SkidBarcodeInfoID) FROM SkidBarcodeInfo 
			WHERE SkidBarcodePrinted=0 AND PartCustMapID=@PartCustMapID	--AND IsHold=0
			AND StationCode=@Station_cd		--Added by VM on 16-06-2015			
			-- ADDED BY VB On 01-06-2015 START
			SELECT
					info.SkidBarcodeInfoID,
					info.PartCustMapID, 
					info.SkidBarcode, 
					info.SkidBarcodePrinted, 
					info.SkidBarcodePrintedTimestamp, 
					info.IsHold, 
					detail.PartBarcode, 
					detail.ID,
					detail.LocationInSkid,
					info.Columns,
					info.Rows,
					info.Layers,
					info.LotSize AS LOT_QTY,
					info.CountryCode AS COUNTRY,
					-- ADDED BY VB ON 01-06-2015
					PPD.CUSTOMER_PART_NO as CustPartNo ,
					PPD.PART_NUMBER as PartNumber,
					PPD.COUNTRY as Country,  -- ADDED BY VB ON 11-06-2015
					-- PPD.CUSTOMER_CODE as CustomerCode,
					info.PartCustMapID AS Part_Cust_Map_ID,
					PPD.IS_LAYERED_PACKING AS LayerWisePrinting,
					PPD.PKG_SERIAL_NO as SerialNumber ,
					pmst.product_nm as PartDescription
					--map.CustPartNo,
					--map.PartNumber,
					--map.CustomerCode,
					--info.PartCustMapID AS Part_Cust_Map_ID,
					--pmst.LayerWisePrinting,
					--pmst.SerialNumber,
					--pmst.PartName PartDescription
					-- ADDED BY VB On 01-06-2015
			FROM SkidBarcodeInfo info
					INNER JOIN SkidBarcodeDetail detail ON info.SkidBarcodeInfoID=detail.SkidBarcodeInfoID
					INNER JOIN PKG_PART_MAPPING PPD ON info.PartCustMapID=PPD.PKG_DEF_ID 
					INNER JOIN PRODUCT_MASTER pmst ON PPD.PART_NUMBER = pmst.sews_part_no AND PPD.WH_CODE = @WH_CODE 
					 --Modified by VM on 22-06-2015 [Start]
					 --AND ISNULL(Detail.LINE_NO,'') = @Line_cd  AND info.StationCode = @Station_cd
					 AND ISNULL(Detail.LINE_NO,'') LIKE '%' + ISNULL(@Line_cd,'') + '%'  AND info.StationCode = @Station_cd
					 --Modified by VM on 22-06-2015 [End]
					--INNER JOIN PKG_PACKAGING_DEFINITION PPD ON info.PartCustMapID=PPD.PKG_DEF_ID 
					-- INNER JOIN CUSTOMER_MASTER CM ON PPD.CUSTOMER_CODE = CM.CUSTOMER_C AND CM.WAREHOUSE_CD = PPD.WH_CODE AND CM.WAREHOUSE_CD = @WH_CODE
					-- INNER JOIN PartMaster pmst ON map.PartNumber=pmst.PartNumber
			WHERE info.SkidBarcodeInfoID=@SkidBarcodeIDLocal1
			ORDER BY detail.ID			

			--SELECT
			--		info.SkidBarcodeInfoID,
			--		info.PartCustMapID, 
			--		info.SkidBarcode, 
			--		info.SkidBarcodePrinted, 
			--		info.SkidBarcodePrintedTimestamp, 
			--		info.IsHold, 
			--		detail.PartBarcode, 
			--		detail.ID,
			--		detail.LocationInSkid,
			--		info.Columns,
			--		info.Rows,
			--		info.Layers,
			--		info.LotSize,
			--		info.CountryCode,
			--		map.CustPartNo,
			--		map.PartNumber,
			--		map.CustomerCode,
			--		info.PartCustMapID AS Part_Cust_Map_ID,
			--		pmst.LayerWisePrinting,
			--		pmst.SerialNumber,
			--		pmst.PartName PartDescription
			--FROM SkidBarcodeInfo info
			--		INNER JOIN SkidBarcodeDetail detail ON info.SkidBarcodeInfoID=detail.SkidBarcodeInfoID
			--		INNER JOIN MappingPartCust map ON info.PartCustMapID=map.ID
			--		INNER JOIN PartMaster pmst ON map.PartNumber=pmst.PartNumber
			--	WHERE info.SkidBarcodeInfoID=@SkidBarcodeIDLocal1
			--	ORDER BY detail.ID
			-- ADDED BY VB On 01-06-2015 END
			SET @ReturnValue='Success'
			SET @ReturnInt=1 		
		END
		ELSE If(@TransType='GETLOCATIONS')
		BEGIN
			SELECT	PartBarcode, 
					ID,
					LocationInSkid,
					Layer
			FROM SkidBarcodeDetail 
			WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID
			ORDER BY LocationInSkid

			SET @ReturnValue='Success'
			SET @ReturnInt=1 			
		END
		ELSE IF(@TransType='INSERT')
		BEGIN
		DECLARE @SkidBarcodeInfoIDLocal BIGINT
			-- IF it is first part in skid then we have to add in SkidBarcodeInfo table
			IF(@SkidBarcodeInfoID=0) 
			BEGIN				
				INSERT INTO SkidBarcodeInfo(
						PartCustMapID,
						SkidBarcode,
						SkidBarcodePrinted,
						SkidBarcodePrintedTimestamp,
						IsHold,
						USERID,
						LotSize,
						Rows,
						Columns,
						Layers,
						CountryCode,
						WH_CODE,
						Line_No,
						StationCode,	-- ADDED BY VB ON 11-06-2015
						DispatchType )	-- ADDED BY VM ON 22-06-2015
				VALUES(
						@PartCustMapID, 
						@SkidLabelBarcode, 
						@SkidLabelBarcodePrinted, 
						@SkidBarcodePrintedTimestamp, 
						@IsHold,
						@UserID,
						@LotSize,
						@Rows, 
						@Columns,
						@Layers,
						@CountryCode,
						@WH_CODE ,
						ISNULL(@Line_cd,''),
						@Station_Cd,
						@Dispatchtype	--Added by VM on 22-06-2015
					)

				SET @SkidBarcodeInfoIDLocal = SCOPE_IDENTITY()
			END
			ELSE -- We will use the same id for detail table
			BEGIN
				SET @SkidBarcodeInfoIDLocal=@SkidBarcodeInfoID
			END

				INSERT INTO SkidBarcodeDetail
					(SkidBarcodeInfoID, PartBarcode, ScanTimeStamp, LocationInSkid, Layer, UserID,WH_CODE,LINE_NO,StationCode)
				VALUES
					( @SkidBarcodeInfoIDLocal, @PartBarcode, GETDATE(), @LocationInSkid, @Layer, @UserID,@WH_CODE,ISNULL(@Line_cd,''),@Station_cd )				

				UPDATE SkidBarcodeInfo SET EmpCode=@EmpCode WHERE SkidBarcodeInfoID=@SkidBarcodeInfoIDLocal
				SET @ReturnValue= CAST(@SkidBarcodeInfoIDLocal  as varchar(5)) + '|' + 'Barcode details entered successfully.'
				SET @ReturnInt=1
		END
		ELSE IF(@TransType='ADDLAYER')
		BEGIN
			INSERT INTO LayerMaster
           ([SkidBarcodeInfoID]
           ,[LayerNumber]
           ,[LayerQty]
           ,[FilledQty]
           ,[Complete]
           ,[PrintCompleted]
           )
     VALUES(
            @SkidBarcodeInfoID
           ,@Layer
           ,@LayerQty
           ,0
           ,0
           ,0
           )

			SET @ReturnValue='Layer added.'
			SET @ReturnInt=1			
		END
		ELSE IF(@TransType='UPDATELAYER')
		BEGIN
			UPDATE LayerMaster
			SET FilledQty=(FilledQty+1)
			WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID AND LayerNumber=@Layer

			DECLARE @LayerQtyLocal INT
			DECLARE @FilledQtyLocal INT

			SELECT @LayerQtyLocal=LayerQty, @FilledQtyLocal=FilledQty FROM LayerMaster
			WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID AND LayerNumber=@Layer
			IF(@LayerQtyLocal=@FilledQtyLocal)
			BEGIN
				UPDATE LayerMaster
				SET Complete=1
				WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID AND LayerNumber=@Layer

				SET @ReturnValue='PRINT'
				SET @ReturnInt=1			
			END
			ELSE 
			BEGIN
				SET @ReturnValue='UPDATED'
				SET @ReturnInt=1
			END			
		END
		ELSE IF(@TransType='UPDATELAYERDECREMENT')
		BEGIN
			UPDATE LayerMaster
			SET FilledQty=(FilledQty-1)
			WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID AND LayerNumber=@Layer

			SET @ReturnValue='UPDATED'
			SET @ReturnInt=1
		END	
		ELSE IF(@TransType='GETLAYERS')
		BEGIN			
			SELECT LayerNumber, 'Layer ' + CAST(LayerNumber as varchar(5)) AS LayerName FROM LayerMaster
			WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID AND Complete=1

			SET @ReturnValue='SUCCESS'
			SET @ReturnInt=1
		END		
		ELSE IF(@TransType='SETLAYERBARCODE')
		BEGIN
			UPDATE LayerMaster
			SET LayerLabel=@SkidLabelBarcode, PrintCompleted=1, PrintedDateTime=GETDATE()
			WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID AND LayerNumber=@Layer

			SET @ReturnValue='Layer label generated.'
			SET @ReturnInt=1
		END		
		ELSE IF(@TransType='REMOVEPART')
		BEGIN
			BEGIN TRAN
				DECLARE @RemovedLocation INT
				--DECLARE @SkidIDLocal BIGINT
				SELECT @RemovedLocation=LocationInSkid
				FROM SkidBarcodeDetail 
				WHERE PartBarcode=@PartBarcode AND SkidBarcodeInfoID=@SkidBarcodeInfoID

				INSERT INTO SkidBarcodeDetailHistory
					   ([SkidBarcodeDetailHistoryID]
					     ,[SkidBarcodeInfoID]
						 ,[PartBarcode]
						 ,[Remarks]
						 ,[ScanTimeStamp]
						 ,[DeletedTimeStamp]
						 ,[LocationInSkid]
						 ,[Layer]
						 ,[LayerSize]
						 ,[LayerLabelPrinted]
						 ,[UserID]
						 ,[WH_Code]		--Added by VM on 23-06-2015
						 ,[Line_No])	--Added by VM on 23-06-2015
				( SELECT [ID]
				   ,[SkidBarcodeInfoID]
				   ,[PartBarcode]
				   ,@Remarks
				   ,[ScanTimeStamp]
				   ,GETDATE()
				   ,[LocationInSkid]
				   ,[Layer]
				   ,[LayerSize]
				   ,[LayerLabelPrinted]
				   ,@UserID
				   ,[WH_CODE]	--Added by VM on 23-06-2015
				   ,[Line_No]	--Added by VM on 23-06-2015
				 FROM SkidBarcodeDetail
				 WHERE PartBarcode=@PartBarcode AND SkidBarcodeInfoID=@SkidBarcodeInfoID
				)				

				DELETE FROM SkidBarcodeDetail 
				WHERE PartBarcode=@PartBarcode AND SkidBarcodeInfoID=@SkidBarcodeInfoID

				IF((SELECT COUNT(*) FROM SkidBarcodeDetail WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID)=0)
				BEGIN
					INSERT INTO SkidBarcodeInfoHistory
						( [SkidBarcodeInfoID]
						,[PartCustMapID]
						,[SkidBarcode]
						,[SkidBarcodePrinted]
						,[SkidBarcodePrintedTimestamp]
						,[IsHold]
						,[USERID]
						,[HoldRemarks]
						,[HoldDateTime]
						,[IsRework]
						,[SkidBarcodeBeforeRework]
						,[ReworkTimeStamp]
						,[DeletedDateTime]
						,Remarks,
						LotSize,
						Columns,
						Rows,
						Layers,
						CountryCode
						,[WH_Code]		--Added by VM on 23-06-2015
						,[Line_No])		--Added by VM on 23-06-2015

					( SELECT [SkidBarcodeInfoID]
						  ,[PartCustMapID]
						  ,[SkidBarcode]
						  ,[SkidBarcodePrinted]
						  ,[SkidBarcodePrintedTimestamp]
						  ,[IsHold]
						  ,@UserID
						  ,[HoldRemarks]
						  ,[HoldDateTime]
						  ,[IsRework]
						  ,[SkidBarcodeBeforeRework]
						  ,[ReworkTimeStamp]
						  ,GETDATE()
						  ,'Deleted because all parts removed.' AS Remarks,
						   LotSize,
						   Columns,
						   Rows,
						   Layers,
						   CountryCode,
						   WH_Code	--Added by VM on 23-06-2015
						  ,Line_No	--Added by VM on 23-06-2015
					  FROM SkidBarcodeInfo
					  WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID
					)

					DELETE FROM SkidBarcodeInfo WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID
				END
			
				SET @ReturnValue=CAST(@RemovedLocation as varchar(5)) + '|Part removed from skid.'
				SET @ReturnInt=1
			COMMIT			
		END
		ELSE IF(@TransType='HOLDSKID')
		BEGIN
			UPDATE SkidBarcodeInfo
			SET IsHold=@IsHold, HoldRemarks=@Remarks, HoldDateTime=GETDATE(), HoldUserID=@UserID
			WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID	

			SET @ReturnValue='Running skid packaging is now on hold.'
			SET @ReturnInt=1			
		END
		ELSE IF(@TransType='ResumeSkid')
		BEGIN
			UPDATE SkidBarcodeInfo
			SET IsHold=@IsHold, ResumeUserID=@UserID
			,HoldRemarks=@Remarks --Added by VM on 17-06-2015
			WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID
		
			SET @ReturnValue='This skid is now resumed, you can scan parts and add them to skid.'
			SET @ReturnInt=1			
		END
		ELSE IF(@TransType='SETSKIDBARCODE')
		BEGIN
			UPDATE SkidBarcodeInfo
			SET		SkidBarcode=@SkidLabelBarcode, 
					SkidBarcodePrinted=1, 
					SrNo=@PartSerialNumber,
					SkidBarcodePrintedTimestamp=GETDATE(),
					USERID=@UserID
			WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID

			--If limit exceed to 99999 then serial number will be reset to 1
			IF(@PartSerialNumber = 99999)
				SET @PartSerialNumber=0

			-- ADDED BY VB ON 01-06-2015
			--UPDATE PartMaster
			--SET		SerialNumber=@PartSerialNumber
			--WHERE PartNumber=@PartNumber

			UPDATE PKG_PART_MAPPING  -- CHANGED BY VB ON 11-06-2015 
			SET PKG_SERIAL_NO = @PartSerialNumber
			WHERE PART_NUMBER = @PartNumber
			-- ADDED BY VB ON 01-06-2015

			SET @ReturnValue='Skid barcode label generated.'
			SET @ReturnInt=1			
		END
		-- ADDED BY VM ON 04-06-2015 [Start]
		ELSE IF (@TransType='SET_PARTIAL_CLOSE_QTY') 
		BEGIN 
			UPDATE SkidBarcodeInfo
			SET		LotSize=@LotSize, 
					SkidBarcodePrintedTimestamp=GETDATE(),
					USERID=@UserID
			WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID
			
			INSERT INTO SkidBarcodeInfoHistory
						   ([SkidBarcodeInfoID]
						   ,[PartCustMapID]
						   ,[SkidBarcode]
						   ,[SkidBarcodePrinted]
						   ,[SkidBarcodePrintedTimestamp]
						   ,[IsHold]
						   ,[USERID]
						   ,[HoldRemarks]
						   ,[HoldDateTime]
						   ,[IsRework]
						   ,[SkidBarcodeBeforeRework]
						   ,[ReworkTimeStamp]
						   ,[DeletedDateTime]
						   ,Remarks
						   ,LotSize,
						   Columns,
						   Rows,
						   Layers,
						   CountryCode
						   )
					( SELECT [SkidBarcodeInfoID]
					       ,[PartCustMapID]
						   ,[SkidBarcode]
						   ,[SkidBarcodePrinted]
						   ,[SkidBarcodePrintedTimestamp]
						   ,[IsHold]
						   ,@UserID
						   ,[HoldRemarks]
						   ,[HoldDateTime]
						   ,[IsRework]
						   ,[SkidBarcodeBeforeRework]
						   ,[ReworkTimeStamp]
						   ,GETDATE()
						   ,'Partial Close.' AS Remarks,
						   LotSize,
						   Columns,
						   Rows,
						   Layers,
						   CountryCode
						   FROM SkidBarcodeInfo 
					  WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID
				)

			SET @ReturnValue='Partial Close Skid barcode label generated.'
			SET @ReturnInt=1			
		END
		-- ADDED BY VM ON 04-06-2015 [End]
		ELSE IF(@TransType='GETSKIDBARCODES')--For reprinting
		BEGIN
			SELECT SkidBarcodeInfoID, SkidBarcode FROM SkidBarcodeInfo 
			WHERE	SkidBarcode LIKE '%' + @DateCode + '%' 
					AND SkidBarcode LIKE '%' + @PartNumber + '%'
					AND SkidBarcodePrinted=1

			SET @ReturnValue='Get details successfully.'
			SET @ReturnInt=1			
		END	
		ELSE IF(@TransType='GetLastGeneratedSkid')--Get Last Generated Skid
		BEGIN
			DECLARE @SKIDID BIGINT, @SkidpartBarcode varchar(50)
			SELECT TOP 1 @SKIDID=SkidBarcodeInfoID FROM SkidBarcodeInfo ORDER BY SkidBarcodeInfoID DESC
			SELECT TOP 1 @SkidpartBarcode=PartBarcode FROM SkidBarcodeDetail where SkidBarcodeInfoID = @SKIDID 

			CREATE TABLE #PartDetails
			(
				ID INT IDENTITY(1,1),
				PartBarcode VARCHAR(50),
				PartDate VARCHAR(6),
				ShiftNo VARCHAR(4)
			)

			CREATE TABLE #PartSummary
			(
				Datecode VARCHAR(6),
				PartBarcode VARCHAR(50),
				PartCounter Numeric(7,0)
			)
			--Logic to insert splitted values into table
			--Splitted values from part barcode are date and shift code

			IF  ( CHARINDEX(':', @SkidpartBarcode) > 0 ) 
			BEGIN
				INSERT INTO #PartDetails
				SELECT PartBarcode, 
				SUBSTRING(
					PartBarcode, 
					CHARINDEX(':', PartBarcode, CHARINDEX(':', PartBarcode, CHARINDEX(':', PartBarcode) + 1) + 1) + 1,
					(CHARINDEX(':', PartBarcode, CHARINDEX(':', PartBarcode, CHARINDEX(':', PartBarcode, CHARINDEX(':', PartBarcode) + 1) + 1) + 1))
							-(CHARINDEX(':', PartBarcode, CHARINDEX(':', PartBarcode, CHARINDEX(':', PartBarcode) + 1) + 1) + 1)
					) 
				AS PartDate,  --- added by VB on 05-06-2015 for EHSU Barcode
				( Select PARAMETER_C2 from PARAMETER_MST where WH_CODE = '0021' and PARAMETER_C = 'PACKAGING' AND Parameter_NM = 'Shift_Name' and Parameter_Value =  
				SUBSTRING(
					PartBarcode, 
					CHARINDEX(':', PartBarcode, CHARINDEX(':', PartBarcode, CHARINDEX(':', PartBarcode,CHARINDEX(':', PartBarcode) + 1) + 1) + 1) + 1,
					((CHARINDEX(':', PartBarcode, CHARINDEX(':', PartBarcode, CHARINDEX(':', PartBarcode, CHARINDEX(':', PartBarcode, CHARINDEX(':', PartBarcode) + 1) + 1) + 1) + 1))
				-
				(CHARINDEX(':', PartBarcode, CHARINDEX(':', PartBarcode, CHARINDEX(':', PartBarcode, CHARINDEX(':', PartBarcode) + 1) + 1) + 1) + 1))
					) )
				AS ShiftNo

				FROM SkidBarcodeInfo skidInfo 
				INNER JOIN SkidBarcodeDetail skidDtl ON skidInfo.SkidBarcodeInfoID=skidDtl.SkidBarcodeInfoID
				WHERE skidInfo.SkidBarcodeInfoID=@SKIDID
			
				--SELECT dbo.Ufndatecodeondate(( '20' + Substring(partdate, 5, 2) + '-'
				--								   + Substring(partdate, 3, 2) + '-'
				--								   + Substring(partdate, 1, 2)), ShiftNo
				--		   ) AS
				--			DateCode,
				--			PartBarcode
				--FROM   #PartDetails 
				--ORDER BY DateCode, PartBarcode

				INSERT INTO #PartSummary (Datecode, PartBarcode, PartCounter)
				SELECT dbo.fnGetDateCodeOnDate(( '20' + Substring(partdate, 5, 2) + '-'
												   + Substring(partdate, 3, 2) + '-'
												   + Substring(partdate, 1, 2)), ShiftNo
						   ) AS
							DateCode,
							PartBarcode, 0
				FROM   #PartDetails 
		END 
		ELSE  /* Added By VB On 05-06-2015 start for internal tarcking*/
		BEGIN
			INSERT INTO #PartDetails
			SELECT PartBarcode, Substring(PartBarcode,8,4) as partdate,'01'as ShiftNo
				FROM SkidBarcodeInfo skidInfo 
				INNER JOIN SkidBarcodeDetail skidDtl ON skidInfo.SkidBarcodeInfoID=skidDtl.SkidBarcodeInfoID
				WHERE skidInfo.SkidBarcodeInfoID=@SKIDID

			INSERT INTO #PartSummary (Datecode, PartBarcode, PartCounter)
			Select partdate as datecode,PartBarcode,0 FROM   #PartDetails
		END  /* Added By VB On 05-06-2015 End*/
			
			update  t1 set t1.partcounter= t2.pcnt
				 from #PartSummary t1, (select datecode,count(PartBarcode ) pcnt from  #PartSummary group by datecode) t2 
				 where t2.datecode=t1.Datecode
			
			SELECT Datecode, PartBarcode, PartCounter FROM #PartSummary
			ORDER BY Datecode
			
			SET @ReturnValue='Get Last Generated Skid.'
			SET @ReturnInt=1			
		END	
		ELSE If(@TransType='SkidDetailsOnSkidID')
		BEGIN
			-- ADDED BY VB On 01-06-2015 START
			SELECT	info.SkidBarcodeInfoID,
					info.PartCustMapID, 
					info.SkidBarcode, 
					info.SkidBarcodePrinted, 
					info.SkidBarcodePrintedTimestamp, 
					info.IsHold, 
					info.Columns,
					info.Rows,
					info.Layers,
					info.LotSize,
					info.CountryCode,
					info.SrNo,
					info.ScanConfirmation,
					detail.PartBarcode, 
					detail.ID,
					detail.LocationInSkid,
					-- ADDED BY VB ON 01-06-2015
					PPD.CUSTOMER_PART_NO as CustPartNo,
					PPD.PART_NUMBER as PartNumber,
					PPD.COUNTRY as Country,  -- ADDED BY VB ON 11-06-2015
					--PPD.CUSTOMER_CODE as CustomerCode ,
					info.PartCustMapID AS Part_Cust_Map_ID,
					PPD.IS_LAYERED_PACKING as LayerWisePrinting,
					PPD.PKG_SERIAL_NO as SerialNumber,
					pmst.product_nm as PartDescription
					--map.CustPartNo,
					--map.PartNumber,
					--map.CustomerCode,
					--info.PartCustMapID AS Part_Cust_Map_ID,
					--pmst.LayerWisePrinting,
					--pmst.SerialNumber,
					--pmst.PartName PartDescription
					-- ADDED BY VB On 01-06-2015
			FROM SkidBarcodeInfo info   
					INNER JOIN SkidBarcodeDetail detail ON info.SkidBarcodeInfoID=detail.SkidBarcodeInfoID
					INNER JOIN PKG_PART_MAPPING PPD ON info.PartCustMapID=PPD.PKG_DEF_ID -- CHANGED BY VB ON 11-06-2015
					-- INNER JOIN PKG_PACKAGING_DEFINITION PPD ON info.PartCustMapID=PPD.PKG_DEF_ID 
					--INNER JOIN PartMaster pmst ON map.PartNumber=pmst.PartNumber
					INNER JOIN PRODUCT_MASTER pmst ON PPD.PART_NUMBER = pmst.sews_part_no AND PPD.WH_CODE = @WH_CODE 
			WHERE info.SkidBarcodeInfoID=@SkidBarcodeInfoID	
			ORDER BY detail.ID			
			
			-- ADDED BY VB On 01-06-2015 END
			--SELECT
			--		info.SkidBarcodeInfoID,
			--		info.PartCustMapID, 
			--		info.SkidBarcode, 
			--		info.SkidBarcodePrinted, 
			--		info.SkidBarcodePrintedTimestamp, 
			--		info.IsHold, 
			--		info.Columns,
			--		info.Rows,
			--		info.Layers,
			--		info.LotSize,
			--		info.CountryCode,
			--		info.SrNo,
			--		info.ScanConfirmation,
			--		map.CustPartNo,
			--		map.PartNumber,
			--		map.CustomerCode,
			--		info.PartCustMapID AS Part_Cust_Map_ID,
			--		pmst.LayerWisePrinting,
			--		pmst.SerialNumber,
			--		pmst.PartName PartDescription
			--FROM SkidBarcodeInfo info
			--	INNER JOIN SkidBarcodeDetail detail ON info.SkidBarcodeInfoID=detail.SkidBarcodeInfoID
			--	INNER JOIN MappingPartCust map ON info.PartCustMapID=map.ID
			--	INNER JOIN PartMaster pmst ON map.PartNumber=pmst.PartNumber
			--  WHERE info.SkidBarcodeInfoID=@SkidBarcodeInfoID			

			SET @ReturnValue='Success'
			SET @ReturnInt=1 			
		END
		ELSE If(@TransType='SetConfirmationForSkidLabel')
		BEGIN
			UPDATE SkidBarcodeInfo SET ScanConfirmation=@Confirmation WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID
			SET @ReturnValue='Success'
			SET @ReturnInt=1 			
		END
		ELSE IF(@TransType='REWORKSELECT')--For Rework
		BEGIN  
			--SELECT Dispatch_id,Dispatch_Barcode FROM Dispatch_Barcode_Info((NOLOCK)) WHERE stmc_Barcode=@stmc_Barcode and Barcode_Printed=1  
			DECLARE @EXISTRW INT
			SELECT @EXISTRW=COUNT(*) 
			FROM SkidBarcodeDetail 
			WHERE PartBarcode=@PartBarcode
			IF(@EXISTRW=0)
			BEGIN
				SET @ReturnValue='Barcode details not exists.'
				SET @ReturnInt=4 
			END
			ELSE
			BEGIN
				DECLARE @SkidBarcodeIDLocalRW VARCHAR(50)			
				SELECT  @SkidBarcodeIDLocalRW=SkidBarcodeInfoID
				FROM SkidBarcodeDetail
				WHERE PartBarcode=@PartBarcode  

				SELECT	info.SkidBarcodeInfoID,
					info.PartCustMapID, 
					info.SkidBarcode, 
					info.SkidBarcodePrinted, 
					info.SkidBarcodePrintedTimestamp,
					info.IsHold, 
					detail.PartBarcode, 
					detail.ID,
					detail.LocationInSkid,
					info.Columns,
					info.Rows,
					info.Layers,
					info.LotSize,
					info.CountryCode,
					--ADDED BY VB ON 01-06-2015 start
					PPD.CUSTOMER_PART_NO as CustPartNo,
					PPD.PART_NUMBER as PartNumber,
					PPD.COUNTRY as Country,  -- ADDED BY VB ON 11-06-2015
					-- PPD.CUSTOMER_CODE as CustomerCode ,
					info.PartCustMapID AS Part_Cust_Map_ID,
					PPD.IS_LAYERED_PACKING as LayerWisePrinting,
					PPD.PKG_SERIAL_NO as SerialNumber
					-- pmst.LayerWisePrinting,
					-- pmst.SerialNumber
					--ADDED BY VB ON 01-06-2015 End
				FROM SkidBarcodeInfo info
					INNER JOIN SkidBarcodeDetail detail ON info.SkidBarcodeInfoID=detail.SkidBarcodeInfoID
					INNER JOIN PKG_PART_MAPPING  PPD ON info.PartCustMapID=PPD.PKG_DEF_ID -- CHANGED BY VB 11-06-2015
					--INNER JOIN PKG_PACKAGING_DEFINITION  PPD ON info.PartCustMapID=pPD.PKG_DEF_ID 
					INNER JOIN PRODUCT_MASTER pmst ON PPD.PART_NUMBER =pmst.SEWS_PART_NO 
				WHERE info.SkidBarcodeInfoID=@SkidBarcodeIDLocalRW AND info.SkidBarcodePrinted=1
				ORDER BY detail.PartBarcode				

				SET @ReturnValue=''
				SET @ReturnInt=1
			END 
		END 
		--Modified by VM on 08-06-2015 [Start]
      ELSE IF(@TransType='REWORKPART')
	  	BEGIN
			BEGIN TRAN
				DECLARE @RemovedLocationRW INT
				DECLARE @RemovedLayerRW INT
				DECLARE @SkidLabelLocal VARCHAR(50)
				DECLARE @SkidLabelLocalNew VARCHAR(50)
		
				SELECT @RemovedLocationRW=LocationInSkid, @RemovedLayerRW=Layer
				FROM SkidBarcodeDetail 
				WHERE PartBarcode=@PartBarcode AND SkidBarcodeInfoID=@SkidBarcodeInfoID		

				INSERT INTO SkidBarcodeDetailHistory
					   ([SkidBarcodeDetailHistoryID]
					     ,[SkidBarcodeInfoID]
						 ,[PartBarcode]
						 ,[Remarks]
						 ,[ScanTimeStamp]
						 ,[DeletedTimeStamp]
						 ,[LocationInSkid]
						 ,[Layer]
						 ,[LayerSize]
						 ,[LayerLabelPrinted]
						 ,[UserID]
						 ,[WH_CODE],[Line_no])	--Added by VM on 22-06-2015
					( SELECT [ID]
					   ,[SkidBarcodeInfoID]
					   ,[PartBarcode]
					   ,@Remarks
					   ,[ScanTimeStamp]
					   ,GETDATE()
					   ,[LocationInSkid]
					   ,[Layer]
					   ,[LayerSize]
					   ,[LayerLabelPrinted]
					   ,@UserID
					   ,[WH_Code],[Line_no] 	--Added by VM on 22-06-2015
					 FROM SkidBarcodeDetail
					 WHERE PartBarcode=@PartBarcode AND SkidBarcodeInfoID=@SkidBarcodeInfoID
					)				

				DELETE FROM SkidBarcodeDetail 
				WHERE PartBarcode=@PartBarcode AND SkidBarcodeInfoID=@SkidBarcodeInfoID			

				INSERT INTO SkidBarcodeDetail
				(SkidBarcodeInfoID, PartBarcode, ScanTimeStamp, LocationInSkid, Layer, UserID,Line_no,WH_CODE)
				VALUES ( @SkidBarcodeInfoID, @NewPartBarcode, GETDATE(), @RemovedLocationRW, @RemovedLayerRW, @UserID,@Line_cd,@WH_CODE)

				SELECT @SkidLabelLocal=SkidBarcode FROM SkidBarcodeInfo WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID

				DECLARE @SubStrWithDateCode VARCHAR(50)
				DECLARE @SubStrWithOutDateCode VARCHAR(50)
				DECLARE @SubStrDateCode VARCHAR(50)

				SET @SubStrWithDateCode = SUBSTRING (@SkidLabelLocal, 1 , @CustPartNumberLength+@partNumberLastCharactersLength + 4 )
				SET @SubStrDateCode = SUBSTRING (@SubStrWithDateCode, @CustPartNumberLength+@partNumberLastCharactersLength+1 , @CustPartNumberLength+@partNumberLastCharactersLength + 4 )
				SET @SkidLabelLocalNew = REPLACE(@SkidLabelLocal,@SubStrDateCode,@DateCode)

				--SET @SubStrWithDateCode = SUBSTRING (@SkidLabelLocal, 1 , @TotalPartsNumberLength + 4 )
				--SET @SubStrDateCode = SUBSTRING (@SubStrWithDateCode, @TotalPartsNumberLength , @TotalPartsNumberLength + 4 )
				--SET @SkidLabelLocalNew = REPLACE(@SkidLabelLocal,@SubStrDateCode,@DateCode)

				UPDATE SkidBarcodeInfo
				SET		--SkidBarcode=@SkidLabelLocalNew, 						 
						IsRework=1,
						SkidBarcodeBeforeRework=@SkidLabelLocal,						
						ReworkTimeStamp=GETDATE(),ReworkUserID=@UserID
				WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID
			
				SELECT
					info.SkidBarcodeInfoID,
					info.PartCustMapID, 
					info.SkidBarcode, 
					info.SkidBarcodePrinted, 
					info.SkidBarcodePrintedTimestamp, 
					info.IsHold, 
					detail.PartBarcode, 
					detail.ID,
					detail.LocationInSkid,
					PPD.COLS_PER_LAYER as columns,
					PPD.ROWS_PER_LAYER as rows,
					PPD.NO_OF_LAYERS as Layers,
					PPD.LOT_QTY  as LotSize  -- ADDED BY VB ON 11-06-2015
					-- PPD.PACK_SIZE as LotSize  
				FROM SkidBarcodeInfo info
					INNER JOIN SkidBarcodeDetail detail ON info.SkidBarcodeInfoID=detail.SkidBarcodeInfoID
					INNER JOIN PKG_PART_MAPPING PPD  ON info.PartCustMapID=PPD.PKG_DEF_ID  -- CHANGED BY VB ON 11-06-2015
					-- INNER JOIN PKG_PACKAGING_DEFINITION PPD  ON info.PartCustMapID=PPD.PKG_DEF_ID 
				WHERE info.SkidBarcodeInfoID=@SkidBarcodeInfoID AND info.SkidBarcodePrinted=1
				ORDER BY detail.PartBarcode		

				SET @ReturnValue= @SkidLabelLocalNew +'|'+  CAST(@RemovedLocation as varchar(5)) + '|Rework done successfully.'
				SET @ReturnInt=1
			COMMIT			
		END
		--Modified by VM on 08-06-2015 [End]
		--Modified by VM on 24-06-2015 [Start]
		ELSE IF(@TransType='GETHOLDSKID')
		BEGIN			
			SELECT SkidBarcode FROM SKIDBARCODEINFO
			WHERE StationCode=@Station_cd AND IsHold=1 AND WH_CODE=@WH_CODE

			SET @ReturnValue='SUCCESS'
			SET @ReturnInt=1
		END		
		--Modified by VM on 24-06-2015 [Start]
		--Modified by VM on 08-06-2015 [Start]
       ELSE IF(@TransType='UNDOSKID')
		BEGIN

			BEGIN TRAN
				--Insert all PartBarCode for Skid to SkidBarCodeDetailHistory
				INSERT INTO SkidBarcodeDetailHistory
					   ([SkidBarcodeDetailHistoryID]
					   ,[SkidBarcodeInfoID]
					   ,[PartBarcode]
					   ,[Remarks]
					   ,[ScanTimeStamp]
					   ,[DeletedTimeStamp]
					   ,[LocationInSkid]
					   ,[Layer]
					   ,[LayerSize]
					   ,[LayerLabelPrinted]
					   ,IsRework
					   ,UserID
					   ,[WH_CODE],[Line_no])	--Added by VM on 22-06-2015
				 (
				 SELECT [ID]
					   ,[SkidBarcodeInfoID]
					   ,[PartBarcode]
					   ,@Remarks
					   ,[ScanTimeStamp]
					   ,GETDATE()
					   ,[LocationInSkid]
					   ,[Layer]
					   ,[LayerSize]
					   ,[LayerLabelPrinted]
					   ,1
					   ,@UserID
					   ,WH_CODE,Line_no	--Added by VM on 22-06-2015
				 FROM SkidBarcodeDetail
				 WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID
				 )				
				--Delete all PartBarCode for Skid to SkidBarCodeDetailHistory
				DELETE FROM SkidBarcodeDetail 
				WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID			

				INSERT INTO SkidBarcodeInfoHistory
						   ([SkidBarcodeInfoID]
						   ,[PartCustMapID]
						   ,[SkidBarcode]
						   ,[SkidBarcodePrinted]
						   ,[SkidBarcodePrintedTimestamp]
						   ,[IsHold]
						   ,[USERID]
						   ,[HoldRemarks]
						   ,[HoldDateTime]
						   ,[IsRework]
						   ,[SkidBarcodeBeforeRework]
						   ,[ReworkTimeStamp]
						   ,[DeletedDateTime]
						   ,Remarks,
						   LotSize,
						   Columns,
						   Rows,
						   Layers,
						   CountryCode
						   ,[WH_CODE],[Line_no])	--Added by VM on 22-06-2015)
					(
					 SELECT [SkidBarcodeInfoID]
						  ,[PartCustMapID]
						  ,[SkidBarcode]
						  ,[SkidBarcodePrinted]
						  ,[SkidBarcodePrintedTimestamp]
						  ,[IsHold]
						  ,@UserID
						  ,[HoldRemarks]
						  ,[HoldDateTime]
						  ,[IsRework]
						  ,[SkidBarcodeBeforeRework]
						  ,[ReworkTimeStamp]
						  ,GETDATE()
						  ,'Undo Skid' AS Remarks,
						   LotSize,
						   Columns,
						   Rows,
						   Layers,
						   CountryCode
						   ,WH_CODE,Line_no	--Added by VM on 22-06-2015
					  FROM SkidBarcodeInfo 
					  WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID
					)

					DELETE FROM SkidBarcodeInfo WHERE SkidBarcodeInfoID=@SkidBarcodeInfoID

					SET @ReturnValue='Skid Undo Sucessfully'
					SET @ReturnInt=1
			
			COMMIT			
		END
		 --Modified by VM on 08-06-2015 [End]
	END TRY 
	BEGIN CATCH  
	--CATCH BLOCK BEGINS
		IF @@TRANCOUNT > 0
			ROLLBACK
			
		SET @ReturnValue =	CAST(ERROR_NUMBER() as varchar(5)) + '|' + 
		CAST(ERROR_SEVERITY()as varchar(5)) + '|' + 
		CAST(ERROR_STATE() as varchar(5)) + '|' + 
		CAST(ERROR_PROCEDURE() as varchar(200)) + '|' + 
		CAST(ERROR_LINE() as varchar(5)) + '|' + 
		CAST(ERROR_MESSAGE() as varchar(1500))		
		
		SET @ReturnInt = 2
	--CATCH BLOCK ENDS 
	END CATCH
END





GO
/****** Object:  StoredProcedure [dbo].[sp_find]    Script Date: 30-09-2026 14:44:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

create  procedure [dbo].[sp_find] (
@p_findtext as  nvarchar(100)
)
as 

set @p_findtext = '%'+ @p_findtext +'%'

select distinct object_name(o.id) 
from dbo.sysobjects o inner join dbo.syscomments c on o.id = c.id 
where c.text like @p_findtext
GO
